INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-1', 'en', 'Bài 1: Giáo dục & Trường học (1) - CEFR B1', 'CEFR B1', 'B1 · Giáo dục', '22 từ vựng Tiếng Anh CEFR B1 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3001, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_summary', 'en-b1-1', 'summary', '/ˈsʌməri/', 'B1', 'bản tóm tắt; bản tổng kết; tóm tắt; khái quát', 'n.', 'summarise (v.), summarisation (n.)', 'Đồng nghĩa: overview, synopsis', 'a summary of đi kèm với đối tượng được tóm tắt; in summary dùng để chuyển sang phần kết luận.', 'Could you give me a quick summary of the meeting?', NULL, 'Bạn có thể tóm tắt ngắn gọn cho tôi về cuộc họp được không?', '{"wordId":"summary","ukIpa":"/ˈsʌməri/","usIpa":"/ˈsʌməri/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a short account giving the main points of something","vi":"bản tóm tắt; bản tổng kết"},{"pos":"adj.","en":"presenting only the main facts or points","vi":"tóm tắt; khái quát"}],"examples":[{"en":"Could you give me a quick summary of the meeting?","vi":"Bạn có thể tóm tắt ngắn gọn cho tôi về cuộc họp được không?","audioKind":"ex"},{"en":"A clear summary at the beginning of a report helps readers understand its main findings quickly.","vi":"Một bản tóm tắt rõ ràng ở phần đầu của báo cáo giúp người đọc nhanh chóng nắm bắt được các kết quả chính.","audioKind":"ex2"}],"collocations":[{"en":"a brief summary","vi":"một bản tóm tắt ngắn gọn"},{"en":"a summary of","vi":"tóm tắt về"},{"en":"in summary","vi":"tóm lại; tổng kết lại"},{"en":"an executive summary","vi":"bản tóm tắt điều hành"}],"wordFamily":["summarise (v.)","summarisation (n.)"],"synonyms":["overview","synopsis"],"antonyms":[],"tipVi":"a summary of đi kèm với đối tượng được tóm tắt; in summary dùng để chuyển sang phần kết luận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_multiply', 'en-b1-1', 'multiply', '/ˈmʌltɪplaɪ/', 'B1', 'nhân lên; làm phép nhân; tăng lên nhanh chóng; sinh sôi nảy nở', 'v.', 'multiplication (n.), multiplier (n.), multiple (adj.)', 'Đồng nghĩa: increase, reproduce · Trái nghĩa: divide', 'A nhân với B nói multiply A by B; dạng quá khứ là multiplied.', 'Multiply the price by three to find the total.', NULL, 'Nhân giá tiền lên ba lần để ra được tổng số tiền.', '{"wordId":"multiply","ukIpa":"/ˈmʌltɪplaɪ/","usIpa":"/ˈmʌltɪplaɪ/","cefr":"B1","topic":"education","senses":[{"pos":"v.","en":"to calculate a total by adding equal amounts repeatedly","vi":"nhân lên; làm phép nhân"},{"pos":"v.","en":"to increase greatly in quantity, or produce more living organisms","vi":"tăng lên nhanh chóng; sinh sôi nảy nở"}],"examples":[{"en":"Multiply the price by three to find the total.","vi":"Nhân giá tiền lên ba lần để ra được tổng số tiền.","audioKind":"ex"},{"en":"Bacteria can multiply rapidly in warm conditions, making proper food storage essential for public health.","vi":"Vi khuẩn có thể sinh sôi nhanh chóng trong điều kiện ấm áp, khiến việc bảo quản thực phẩm đúng cách trở nên cốt yếu đối với sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"multiply by","vi":"nhân với"},{"en":"multiply rapidly","vi":"tăng nhanh hoặc sinh sôi nhanh"},{"en":"multiply tenfold","vi":"tăng gấp mười lần"}],"wordFamily":["multiplication (n.)","multiplier (n.)","multiple (adj.)"],"synonyms":["increase","reproduce"],"antonyms":["divide"],"tipVi":"A nhân với B nói multiply A by B; dạng quá khứ là multiplied.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chapter', 'en-b1-1', 'chapter', '/ˈtʃæptər/', 'B1', 'chương (sách); hồi; giai đoạn (trong cuộc đời hoặc lịch sử); phân hội địa phương (của một tổ chức lớn)', 'n.', NULL, NULL, 'Dùng chapter cho "chương" sách; các phần nhỏ hơn bên trong chương thường dùng section.', 'I read one chapter before turning off the light.', NULL, 'Tôi đã đọc được một chương trước khi tắt đèn đi ngủ.', '{"wordId":"chapter","ukIpa":"/ˈtʃæptə/","usIpa":"/ˈtʃæptər/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"one of the main sections of a book","vi":"chương (sách); hồi"},{"pos":"n.","en":"a distinct period in someone''s life or in history","vi":"giai đoạn (trong cuộc đời hoặc lịch sử)"},{"pos":"n.","en":"a local branch of a larger organisation","vi":"phân hội địa phương (của một tổ chức lớn)"}],"examples":[{"en":"I read one chapter before turning off the light.","vi":"Tôi đã đọc được một chương trước khi tắt đèn đi ngủ.","audioKind":"ex"},{"en":"The final chapter examines how public transport investment can reduce inequality in rapidly growing cities.","vi":"Chương cuối cùng xem xét việc đầu tư vào giao thông công cộng có thể làm giảm bất bình đẳng ở các thành phố đang phát triển nhanh như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"the opening chapter","vi":"chương mở đầu"},{"en":"a new chapter","vi":"một chương mới"},{"en":"a chapter in history","vi":"một giai đoạn trong lịch sử"},{"en":"a local chapter","vi":"phân hội địa phương"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng chapter cho \"chương\" sách; các phần nhỏ hơn bên trong chương thường dùng section.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unit', 'en-b1-1', 'unit', '/ˈjuːnɪt/', 'B1', 'đơn vị; bài học; thiết bị; bộ phận; tiểu đội; ban', 'n.', NULL, NULL, 'Khi chỉ đơn vị đo lường thường dùng a unit of, theo sau là đối tượng được đo.', 'We finished the first unit before our lunch break.', NULL, 'Chúng tôi đã hoàn thành bài học đầu tiên trước giờ nghỉ trưa.', '{"wordId":"unit","ukIpa":"/ˈjuːnɪt/","usIpa":"/ˈjuːnɪt/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a single part or quantity within a larger whole","vi":"đơn vị; bài học"},{"pos":"n.","en":"a device or separate part of a machine","vi":"thiết bị; bộ phận"},{"pos":"n.","en":"a group organised for a particular task","vi":"bộ phận; tiểu đội; ban"}],"examples":[{"en":"We finished the first unit before our lunch break.","vi":"Chúng tôi đã hoàn thành bài học đầu tiên trước giờ nghỉ trưa.","audioKind":"ex"},{"en":"Each unit of the course introduces practical skills that students can apply in the workplace.","vi":"Mỗi bài học trong khóa học đều giới thiệu các kỹ năng thực tế mà học viên có thể ứng dụng tại nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"a unit of measurement","vi":"đơn vị đo lường"},{"en":"a family unit","vi":"đơn vị gia đình"},{"en":"an air-conditioning unit","vi":"thiết bị điều hòa không khí"},{"en":"an intensive care unit","vi":"khoa hồi sức tích cực"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ đơn vị đo lường thường dùng a unit of, theo sau là đối tượng được đo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fluent', 'en-b1-1', 'fluent', '/ˈfluːənt/', 'B1', 'trôi chảy; lưu loát', 'adj.', 'fluency (n.), fluently (adv.)', 'Trái nghĩa: halting', 'Nói trôi chảy một ngôn ngữ dùng be fluent in; lưu loát không có nghĩa là hoàn toàn không sai sót.', 'She became fluent in Spanish after living abroad.', NULL, 'Cô ấy đã nói tiếng Tây Ban Nha trôi chảy sau khi sống ở nước ngoài.', '{"wordId":"fluent","ukIpa":"/ˈfluːənt/","usIpa":"/ˈfluːənt/","cefr":"B1","topic":"education","senses":[{"pos":"adj.","en":"Able to speak or write a language easily and smoothly.","vi":"trôi chảy; lưu loát"}],"examples":[{"en":"She became fluent in Spanish after living abroad.","vi":"Cô ấy đã nói tiếng Tây Ban Nha trôi chảy sau khi sống ở nước ngoài.","audioKind":"ex"},{"en":"Fluent speakers may still make grammatical mistakes, so language assessments should consider both communication skills and accuracy.","vi":"Những người nói lưu loát vẫn có thể mắc lỗi ngữ pháp, vì vậy các bài kiểm tra ngôn ngữ nên xem xét cả kỹ năng giao tiếp lẫn độ chính xác.","audioKind":"ex2"}],"collocations":[{"en":"fluent in English","vi":"nói tiếng Anh lưu loát"},{"en":"a fluent speaker","vi":"người nói lưu loát"},{"en":"fluent speech","vi":"bài phát biểu trôi chảy"}],"wordFamily":["fluency (n.)","fluently (adv.)"],"synonyms":[],"antonyms":["halting"],"tipVi":"Nói trôi chảy một ngôn ngữ dùng be fluent in; lưu loát không có nghĩa là hoàn toàn không sai sót.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subtraction', 'en-b1-1', 'subtraction', '/səbˈtrækʃən/', 'B1', 'phép trừ', 'n.', 'subtract (v.)', 'Trái nghĩa: addition', 'Cấu trúc subtract A from B có nghĩa là lấy B trừ đi A, cần chú ý thứ tự.', 'We practised subtraction by taking buttons out of a bowl.', NULL, 'Chúng tôi đã luyện tập phép trừ bằng cách lấy những chiếc cúc áo ra khỏi một cái bát.', '{"wordId":"subtraction","ukIpa":"/səbˈtrækʃən/","usIpa":"/səbˈtrækʃən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"The process of taking one amount away from another.","vi":"phép trừ"}],"examples":[{"en":"We practised subtraction by taking buttons out of a bowl.","vi":"Chúng tôi đã luyện tập phép trừ bằng cách lấy những chiếc cúc áo ra khỏi một cái bát.","audioKind":"ex"},{"en":"A secure understanding of subtraction helps children develop the numerical skills needed for everyday financial decisions.","vi":"Việc nắm vững phép trừ giúp trẻ phát triển các kỹ năng tính toán cần thiết cho các quyết định tài chính hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"addition and subtraction","vi":"cộng và trừ"},{"en":"simple subtraction","vi":"phép trừ đơn giản"},{"en":"subtraction problem","vi":"bài toán trừ"}],"wordFamily":["subtract (v.)"],"synonyms":[],"antonyms":["addition"],"tipVi":"Cấu trúc subtract A from B có nghĩa là lấy B trừ đi A, cần chú ý thứ tự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_requirement', 'en-b1-1', 'requirement', '/rɪˈkwaɪrmənt/', 'B1', 'yêu cầu; điều kiện tiên quyết; nhu cầu; thứ cần thiết cho một mục đích cụ thể', 'n.', 'require (v.), required (adj.)', 'Đồng nghĩa: prerequisite, condition, need', 'Đạt yêu cầu dùng meet requirements, không dùng reach.', 'Wearing a helmet is a requirement at this skatepark.', NULL, 'Đội mũ bảo hiểm là một yêu cầu bắt buộc tại công viên trượt ván này.', '{"wordId":"requirement","ukIpa":"/rɪˈkwaɪəmənt/","usIpa":"/rɪˈkwaɪrmənt/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"Something that must be done, possessed, or provided","vi":"yêu cầu; điều kiện tiên quyết"},{"pos":"n.","en":"Something needed for a particular purpose","vi":"nhu cầu; thứ cần thiết cho một mục đích cụ thể"}],"examples":[{"en":"Wearing a helmet is a requirement at this skatepark.","vi":"Đội mũ bảo hiểm là một yêu cầu bắt buộc tại công viên trượt ván này.","audioKind":"ex"},{"en":"Clear entry requirements help prospective students assess whether they are adequately prepared for university courses.","vi":"Các yêu cầu đầu vào rõ ràng giúp sinh viên tương lai đánh giá xem họ đã chuẩn bị đầy đủ cho các khóa học đại học hay chưa.","audioKind":"ex2"}],"collocations":[{"en":"meet the requirements","vi":"đáp ứng các yêu cầu"},{"en":"entry requirements","vi":"yêu cầu đầu vào"},{"en":"a legal requirement","vi":"yêu cầu pháp lý"},{"en":"energy requirements","vi":"nhu cầu năng lượng"}],"wordFamily":["require (v.)","required (adj.)"],"synonyms":["prerequisite","condition","need"],"antonyms":[],"tipVi":"Đạt yêu cầu dùng meet requirements, không dùng reach.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cheating', 'en-b1-1', 'cheating', '/ˈtʃiːtɪŋ/', 'B1', 'sự gian lận; hành vi gian lận', 'n.', 'cheat (v.), cheat (n.), cheater (n.)', 'Đồng nghĩa: dishonesty · Trái nghĩa: honesty', 'Cheating đóng vai trò danh từ chỉ hành vi thường không đếm được; cheat cũng có thể chỉ kẻ gian lận.', 'Peeking at another player''s cards is cheating, even among friends.', NULL, 'Liếc nhìn bài của người chơi khác là gian lận, ngay cả khi chơi giữa những người bạn với nhau.', '{"wordId":"cheating","ukIpa":"/ˈtʃiːtɪŋ/","usIpa":"/ˈtʃiːtɪŋ/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"Dishonest behaviour intended to gain an unfair advantage.","vi":"sự gian lận; hành vi gian lận"}],"examples":[{"en":"Peeking at another player''s cards is cheating, even among friends.","vi":"Liếc nhìn bài của người chơi khác là gian lận, ngay cả khi chơi giữa những người bạn với nhau.","audioKind":"ex"},{"en":"Schools can discourage cheating by designing assessments that reward independent thinking rather than the simple recall of facts.","vi":"Nhà trường có thể ngăn chặn nạn gian lận bằng cách thiết kế các bài kiểm tra khen thưởng tư duy độc lập thay vì chỉ ghi nhớ thông tin đơn thuần.","audioKind":"ex2"}],"collocations":[{"en":"cheating in exams","vi":"gian lận trong thi cử"},{"en":"prevent cheating","vi":"ngăn chặn gian lận"},{"en":"accuse someone of cheating","vi":"buộc tội ai đó gian lận"}],"wordFamily":["cheat (v.)","cheat (n.)","cheater (n.)"],"synonyms":["dishonesty"],"antonyms":["honesty"],"tipVi":"Cheating đóng vai trò danh từ chỉ hành vi thường không đếm được; cheat cũng có thể chỉ kẻ gian lận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_absent', 'en-b1-1', 'absent', '/ˈæbsənt/', 'B1', 'vắng mặt; không có ở nơi được mong đợi; thiếu; không có', 'adj.', 'absence (n.), absentee (n.), absenteeism (n.)', 'Đồng nghĩa: missing · Trái nghĩa: present', 'Biểu thị vắng mặt ở một dịp/nơi nào đó dùng absent from, không dùng absent in.', 'Lina was absent from class because she felt ill.', NULL, 'Lina vắng mặt ở lớp vì cô ấy cảm thấy không khỏe.', '{"wordId":"absent","ukIpa":"/ˈæbsənt/","usIpa":"/ˈæbsənt/","cefr":"B1","topic":"education","senses":[{"pos":"adj.","en":"Not present where someone is expected to be.","vi":"vắng mặt; không có ở nơi được mong đợi"},{"pos":"adj.","en":"Not existing or found in a particular place or situation.","vi":"thiếu; không có"}],"examples":[{"en":"Lina was absent from class because she felt ill.","vi":"Lina vắng mặt ở lớp vì cô ấy cảm thấy không khỏe.","audioKind":"ex"},{"en":"Students who are frequently absent from school may require additional support to keep up with their classmates.","vi":"Những học sinh thường xuyên vắng mặt ở trường có thể cần sự hỗ trợ thêm để theo kịp các bạn cùng lớp.","audioKind":"ex2"}],"collocations":[{"en":"absent from school","vi":"vắng học"},{"en":"absent from work","vi":"vắng mặt tại nơi làm việc"},{"en":"conspicuously absent","vi":"vắng mặt rõ rệt"}],"wordFamily":["absence (n.)","absentee (n.)","absenteeism (n.)"],"synonyms":["missing"],"antonyms":["present"],"tipVi":"Biểu thị vắng mặt ở một dịp/nơi nào đó dùng absent from, không dùng absent in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arithmetic', 'en-b1-1', 'arithmetic', '/əˈrɪθmətɪk/', 'B1', 'toán học; phép tính số học', 'n.', 'arithmetical (adj.), arithmetically (adv.)', NULL, 'Đóng vai trò danh từ thường không đếm được; phạm vi hẹp hơn mathematics.', 'We practised mental arithmetic while waiting for the bus.', NULL, 'Chúng tôi đã luyện tập tính nhẩm trong lúc chờ xe buýt.', '{"wordId":"arithmetic","ukIpa":"/əˈrɪθmətɪk/","usIpa":"/əˈrɪθmətɪk/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"mathematics involving addition, subtraction, multiplication, and division","vi":"toán học; phép tính số học"}],"examples":[{"en":"We practised mental arithmetic while waiting for the bus.","vi":"Chúng tôi đã luyện tập tính nhẩm trong lúc chờ xe buýt.","audioKind":"ex"},{"en":"Strong arithmetic skills help young adults manage personal budgets and make informed financial decisions.","vi":"Kỹ năng tính nhẩm vững vàng giúp người trẻ quản lý ngân sách cá nhân và đưa ra các quyết định tài chính sáng suốt.","audioKind":"ex2"}],"collocations":[{"en":"mental arithmetic","vi":"tính nhẩm"},{"en":"basic arithmetic","vi":"số học cơ bản"},{"en":"arithmetic skills","vi":"kỹ năng số học"}],"wordFamily":["arithmetical (adj.)","arithmetically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Đóng vai trò danh từ thường không đếm được; phạm vi hẹp hơn mathematics.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_opportunity', 'en-b1-1', 'opportunity', '/ˌɑːpərˈtuːnəti/', 'B1', 'cơ hội; thời cơ', 'n.', NULL, 'Đồng nghĩa: chance', 'Thường dùng cấu trúc an opportunity to do để chỉ cơ hội làm việc gì đó.', 'The school trip gave me an opportunity to try climbing.', NULL, 'Chuyến dã ngoại của trường đã cho tôi cơ hội thử sức với môn leo núi.', '{"wordId":"opportunity","ukIpa":"/ˌɒpəˈtjuːnəti/","usIpa":"/ˌɑːpərˈtuːnəti/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A situation that makes it possible to do something.","vi":"cơ hội; thời cơ"}],"examples":[{"en":"The school trip gave me an opportunity to try climbing.","vi":"Chuyến dã ngoại của trường đã cho tôi cơ hội thử sức với môn leo núi.","audioKind":"ex"},{"en":"Public libraries provide an important opportunity for residents to develop skills without paying expensive course fees.","vi":"Các thư viện công cộng mang đến cơ hội quan trọng để cư dân phát triển kỹ năng mà không phải trả học phí tốn kém.","audioKind":"ex2"}],"collocations":[{"en":"an opportunity to learn","vi":"cơ hội học tập"},{"en":"seize an opportunity","vi":"nắm bắt cơ hội"},{"en":"equal opportunities","vi":"cơ hội bình đẳng"}],"wordFamily":[],"synonyms":["chance"],"antonyms":[],"tipVi":"Thường dùng cấu trúc an opportunity to do để chỉ cơ hội làm việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lecturer', 'en-b1-1', 'lecturer', '/ˈlektʃərər/', 'B1', 'giảng viên đại học; báo cáo viên', 'n.', 'lecture (n.), lecture (v.), lectureship (n.)', 'Đồng nghĩa: instructor', 'Dùng lecturer in kèm theo môn học; từ này không đồng nghĩa hoàn toàn với giáo sư (professor).', 'Our lecturer stayed after class to explain the diagram.', NULL, 'Giảng viên của chúng tôi ở lại sau giờ học để giải thích sơ đồ.', '{"wordId":"lecturer","ukIpa":"/ˈlektʃərə/","usIpa":"/ˈlektʃərər/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"Someone who teaches at a university or gives educational talks","vi":"giảng viên đại học; báo cáo viên"}],"examples":[{"en":"Our lecturer stayed after class to explain the diagram.","vi":"Giảng viên của chúng tôi ở lại sau giờ học để giải thích sơ đồ.","audioKind":"ex"},{"en":"A university lecturer can encourage critical thinking by asking students to compare evidence from different sources.","vi":"Một giảng viên đại học có thể khuyến khích tư duy phản biện bằng cách yêu cầu sinh viên so sánh các bằng chứng từ nhiều nguồn khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"university lecturer","vi":"giảng viên đại học"},{"en":"senior lecturer","vi":"giảng viên cao cấp"},{"en":"lecturer in economics","vi":"giảng viên môn kinh tế học"},{"en":"guest lecturer","vi":"giảng viên thỉnh giảng"}],"wordFamily":["lecture (n.)","lecture (v.)","lectureship (n.)"],"synonyms":["instructor"],"antonyms":[],"tipVi":"Dùng lecturer in kèm theo môn học; từ này không đồng nghĩa hoàn toàn với giáo sư (professor).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_section', 'en-b1-1', 'section', '/ˈsekʃən/', 'B1', 'phần; mục; khu vực; mặt cắt; lát cắt; chia cắt; cắt thành từng khúc', 'n.', 'sectional (adj.)', 'Đồng nghĩa: part, portion', 'section có thể chỉ chương mục trong văn bản, hoặc khu vực trong các địa điểm như cửa hàng.', 'You''ll find fresh bread in the bakery section.', NULL, 'Bạn sẽ tìm thấy bánh mì tươi ở khu vực bánh kẹo.', '{"wordId":"section","ukIpa":"/ˈsekʃən/","usIpa":"/ˈsekʃən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A distinct part of something larger.","vi":"phần; mục; khu vực"},{"pos":"n.","en":"A surface or thin piece exposed by cutting through something.","vi":"mặt cắt; lát cắt"},{"pos":"v.","en":"To divide something into parts or cut it into slices.","vi":"chia cắt; cắt thành từng khúc"}],"examples":[{"en":"You''ll find fresh bread in the bakery section.","vi":"Bạn sẽ tìm thấy bánh mì tươi ở khu vực bánh kẹo.","audioKind":"ex"},{"en":"The final section of the report examines how urban design can encourage healthier lifestyles.","vi":"Phần cuối cùng của báo cáo xem xét cách thiết kế đô thị có thể thúc đẩy lối sống lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"a section of","vi":"một phần của"},{"en":"final section","vi":"phần cuối"},{"en":"cross section","vi":"mặt cắt ngang"},{"en":"section off","vi":"vây ngăn ra"}],"wordFamily":["sectional (adj.)"],"synonyms":["part","portion"],"antonyms":[],"tipVi":"section có thể chỉ chương mục trong văn bản, hoặc khu vực trong các địa điểm như cửa hàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_infinitive', 'en-b1-1', 'infinitive', '/ɪnˈfɪnətɪv/', 'B1', 'động từ nguyên thể; nguyên mẫu; thuộc về nguyên thể', 'n.', NULL, NULL, 'Động từ nguyên thể có thể đi kèm to hoặc không; ví dụ to go và go trong must go.', 'Our teacher explained the infinitive with three simple examples.', NULL, 'Giáo viên của chúng tôi đã giải thích về động từ nguyên thể bằng ba ví dụ đơn giản.', '{"wordId":"infinitive","ukIpa":"/ɪnˈfɪnətɪv/","usIpa":"/ɪnˈfɪnətɪv/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"the basic verb form, used with or without to","vi":"động từ nguyên thể; nguyên mẫu"},{"pos":"adj.","en":"relating to or using the basic form of a verb","vi":"thuộc về nguyên thể"}],"examples":[{"en":"Our teacher explained the infinitive with three simple examples.","vi":"Giáo viên của chúng tôi đã giải thích về động từ nguyên thể bằng ba ví dụ đơn giản.","audioKind":"ex"},{"en":"Understanding when to use an infinitive helps language learners express intentions and purposes more accurately.","vi":"Việc hiểu rõ khi nào nên sử dụng động từ nguyên thể giúp người học ngôn ngữ diễn đạt ý định và mục đích chính xác hơn.","audioKind":"ex2"}],"collocations":[{"en":"a bare infinitive","vi":"nguyên thể không to"},{"en":"a to-infinitive","vi":"nguyên thể có to"},{"en":"an infinitive phrase","vi":"cụm động từ nguyên thể"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ nguyên thể có thể đi kèm to hoặc không; ví dụ to go và go trong must go.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_introduction', 'en-b1-1', 'introduction', '/ˌɪntrəˈdʌkʃən/', 'B1', 'lời giới thiệu; sự giới thiệu; phần mở đầu; sự đưa vào sử dụng; sự ban hành; sự ra mắt', 'n.', 'introduce (v.), introductory (adj.)', NULL, 'Dùng introduction to cho phần giới thiệu nhập môn; dùng of khi chỉ việc đưa cái gì vào.', 'After a brief introduction, we started cooking together.', NULL, 'Sau màn giới thiệu ngắn gọn, chúng tôi bắt đầu cùng nhau nấu ăn.', '{"wordId":"introduction","ukIpa":"/ˌɪntrəˈdʌkʃən/","usIpa":"/ˌɪntrəˈdʌkʃən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"An explanation or meeting that first presents someone or something.","vi":"lời giới thiệu; sự giới thiệu; phần mở đầu"},{"pos":"n.","en":"The act of bringing something into use or a place.","vi":"sự đưa vào sử dụng; sự ban hành; sự ra mắt"}],"examples":[{"en":"After a brief introduction, we started cooking together.","vi":"Sau màn giới thiệu ngắn gọn, chúng tôi bắt đầu cùng nhau nấu ăn.","audioKind":"ex"},{"en":"The introduction of electric buses could reduce air pollution in densely populated urban areas.","vi":"Việc đưa xe buýt điện vào hoạt động có thể làm giảm ô nhiễm không khí tại các khu đô thị đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"a brief introduction","vi":"lời giới thiệu ngắn gọn"},{"en":"an introduction to","vi":"giới thiệu sơ lược về; nhập môn về"},{"en":"the introduction of","vi":"sự ra mắt của; sự đưa vào của"}],"wordFamily":["introduce (v.)","introductory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng introduction to cho phần giới thiệu nhập môn; dùng of khi chỉ việc đưa cái gì vào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_term', 'en-b1-1', 'term', '/tɝːm/', 'B1', 'thuật ngữ; từ ngữ; học kỳ; thời hạn; nhiệm kỳ', 'n.', 'terminology (n.)', NULL, 'in terms of có nghĩa là xét về...; nghĩa về điều khoản thường dùng ở số nhiều là terms.', 'Our teacher explained a scientific term using a simple drawing.', NULL, 'Giáo viên của chúng tôi đã giải thích một thuật ngữ khoa học bằng một bức vẽ đơn giản.', '{"wordId":"term","ukIpa":"/tɜːm/","usIpa":"/tɝːm/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A word or expression with a particular meaning.","vi":"thuật ngữ; từ ngữ"},{"pos":"n.","en":"One of the periods into which a school year is divided.","vi":"học kỳ"},{"pos":"n.","en":"A fixed period during which something lasts or someone serves.","vi":"thời hạn; nhiệm kỳ"}],"examples":[{"en":"Our teacher explained a scientific term using a simple drawing.","vi":"Giáo viên của chúng tôi đã giải thích một thuật ngữ khoa học bằng một bức vẽ đơn giản.","audioKind":"ex"},{"en":"The term sustainability describes meeting present needs without limiting the opportunities available to future generations.","vi":"Thuật ngữ phát triển bền vững mô tả việc đáp ứng các nhu cầu hiện tại mà không làm hạn chế các cơ hội dành cho các thế hệ tương lai.","audioKind":"ex2"}],"collocations":[{"en":"technical term","vi":"thuật ngữ chuyên môn"},{"en":"school term","vi":"học kỳ"},{"en":"in the long term","vi":"về lâu dài"},{"en":"terms and conditions","vi":"các điều khoản và điều kiện"}],"wordFamily":["terminology (n.)"],"synonyms":[],"antonyms":[],"tipVi":"in terms of có nghĩa là xét về...; nghĩa về điều khoản thường dùng ở số nhiều là terms.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_graduate', 'en-b1-1', 'graduate', '/ˈɡrædʒuət/', 'B1', 'người đã tốt nghiệp đại học; tốt nghiệp; hoàn thành bậc học ở trường hoặc đại học', 'n.', 'graduation (n.), undergraduate (n.), postgraduate (n.)', NULL, 'Danh từ phát âm âm đuôi /ət/, động từ phát âm /eɪt/; tốt nghiệp từ trường nào dùng graduate from.', 'My sister graduated from university and started work nearby.', NULL, 'Chị gái tôi tốt nghiệp đại học và bắt đầu làm việc ở gần nhà.', '{"wordId":"graduate","ukIpa":"/ˈɡrædʒuət/","usIpa":"/ˈɡrædʒuət/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"someone who has successfully completed a university degree","vi":"người đã tốt nghiệp đại học"},{"pos":"v.","en":"to successfully complete a course at a school or university","vi":"tốt nghiệp; hoàn thành bậc học ở trường hoặc đại học"}],"examples":[{"en":"My sister graduated from university and started work nearby.","vi":"Chị gái tôi tốt nghiệp đại học và bắt đầu làm việc ở gần nhà.","audioKind":"ex"},{"en":"Many recent graduates struggle to find employment that matches their qualifications in an increasingly competitive labour market.","vi":"Nhiều sinh viên mới tốt nghiệp phải vật lộn để tìm được việc làm phù hợp với trình độ chuyên môn của họ trong một thị trường lao động ngày càng cạnh tranh khốc liệt.","audioKind":"ex2"}],"collocations":[{"en":"university graduate","vi":"cử nhân đại học"},{"en":"recent graduate","vi":"sinh viên mới tốt nghiệp"},{"en":"graduate from university","vi":"tốt nghiệp đại học"},{"en":"graduate with honours","vi":"tốt nghiệp loại xuất sắc"}],"wordFamily":["graduation (n.)","undergraduate (n.)","postgraduate (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ phát âm âm đuôi /ət/, động từ phát âm /eɪt/; tốt nghiệp từ trường nào dùng graduate from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dormitory', 'en-b1-1', 'dormitory', '/ˈdɔːrmətɔːri/', 'B1', 'phòng ngủ tập thể; tòa nhà ký túc xá học sinh, sinh viên', 'n.', NULL, 'Đồng nghĩa: dorm', 'Trong tiếng Anh-Mỹ thường chỉ tòa nhà ký túc xá; tiếng Anh-Anh cũng thường chỉ phòng ngủ nhiều giường.', 'We shared a dormitory with six other travellers.', NULL, 'Chúng tôi ở chung phòng ngủ tập thể với sáu du khách khác.', '{"wordId":"dormitory","ukIpa":"/ˈdɔːmɪtri/","usIpa":"/ˈdɔːrmətɔːri/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A large room where several people sleep.","vi":"phòng ngủ tập thể"},{"pos":"n.","en":"A building where students live, especially at American colleges.","vi":"tòa nhà ký túc xá học sinh, sinh viên"}],"examples":[{"en":"We shared a dormitory with six other travellers.","vi":"Chúng tôi ở chung phòng ngủ tập thể với sáu du khách khác.","audioKind":"ex"},{"en":"Living in a university dormitory can help new students build friendships and adjust to campus life.","vi":"Sống trong ký túc xá đại học có thể giúp sinh viên mới kết bạn và thích nghi với đời sống khuôn viên trường.","audioKind":"ex2"}],"collocations":[{"en":"shared dormitory","vi":"phòng ngủ tập thể"},{"en":"university dormitory","vi":"ký túc xá đại học"},{"en":"dormitory room","vi":"phòng ký túc xá"}],"wordFamily":[],"synonyms":["dorm"],"antonyms":[],"tipVi":"Trong tiếng Anh-Mỹ thường chỉ tòa nhà ký túc xá; tiếng Anh-Anh cũng thường chỉ phòng ngủ nhiều giường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_structure', 'en-b1-1', 'structure', '/ˈstrʌktʃər/', 'B1', 'cấu trúc; kết cấu; công trình kiến trúc; kết cấu xây dựng; tổ chức; sắp xếp', 'n.', 'structural (adj.), structurally (adv.), restructure (v.)', NULL, 'structure vừa có thể đóng vai trò là danh từ, vừa là động từ diễn tả hành động tổ chức, sắp xếp.', 'The model shows the structure of a wooden bridge.', NULL, 'Mô hình này cho thấy kết cấu của một cây cầu gỗ.', '{"wordId":"structure","ukIpa":"/ˈstrʌktʃə/","usIpa":"/ˈstrʌktʃər/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"The way parts are arranged and connected within a whole.","vi":"cấu trúc; kết cấu"},{"pos":"n.","en":"Something built from connected parts, such as a bridge.","vi":"công trình kiến trúc; kết cấu xây dựng"},{"pos":"v.","en":"Arrange parts or activities into an organised whole.","vi":"tổ chức; sắp xếp"}],"examples":[{"en":"The model shows the structure of a wooden bridge.","vi":"Mô hình này cho thấy kết cấu của một cây cầu gỗ.","audioKind":"ex"},{"en":"A clear essay structure helps readers follow complex arguments and understand the writer''s main conclusions.","vi":"Cấu trúc bài luận rõ ràng giúp người đọc theo dõi các lập luận phức tạp và nắm bắt các kết luận chính của tác giả.","audioKind":"ex2"}],"collocations":[{"en":"social structure","vi":"cấu trúc xã hội"},{"en":"sentence structure","vi":"cấu trúc câu"},{"en":"structure an essay","vi":"sắp xếp bố cục bài viết"},{"en":"supporting structure","vi":"cấu trúc nâng đỡ"}],"wordFamily":["structural (adj.)","structurally (adv.)","restructure (v.)"],"synonyms":[],"antonyms":[],"tipVi":"structure vừa có thể đóng vai trò là danh từ, vừa là động từ diễn tả hành động tổ chức, sắp xếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_examination', 'en-b1-1', 'examination', '/ɪɡˌzæmɪˈneɪʃən/', 'B1', 'kỳ thi; bài kiểm tra năng lực; sự kiểm tra kỹ lưỡng; sự xem xét cẩn thận', 'n.', 'examine (v.), examiner (n.), examinee (n.)', 'Đồng nghĩa: exam, inspection', 'Nghĩa kỳ thi trong văn phong thông thường hay được gọi tắt là exam; nghĩa kiểm tra thường đi với giới từ of.', 'She felt relieved when her final examination was over.', NULL, 'Cô ấy cảm thấy nhẹ nhõm khi kỳ thi cuối kỳ đã kết thúc.', '{"wordId":"examination","ukIpa":"/ɪɡˌzæmɪˈneɪʃən/","usIpa":"/ɪɡˌzæmɪˈneɪʃən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a formal test of knowledge or ability","vi":"kỳ thi; bài kiểm tra năng lực"},{"pos":"n.","en":"the act of looking at something carefully to assess it","vi":"sự kiểm tra kỹ lưỡng; sự xem xét cẩn thận"}],"examples":[{"en":"She felt relieved when her final examination was over.","vi":"Cô ấy cảm thấy nhẹ nhõm khi kỳ thi cuối kỳ đã kết thúc.","audioKind":"ex"},{"en":"A detailed examination of local housing conditions can help governments identify communities that need urgent support.","vi":"Việc khảo sát chi tiết điều kiện nhà ở địa phương có thể giúp chính phủ xác định các cộng đồng đang cần sự hỗ trợ khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"take an examination","vi":"tham gia một kỳ thi"},{"en":"pass an examination","vi":"vượt qua kỳ thi"},{"en":"a medical examination","vi":"khám sức khỏe"},{"en":"close examination","vi":"sự xem xét kỹ lưỡng"}],"wordFamily":["examine (v.)","examiner (n.)","examinee (n.)"],"synonyms":["exam","inspection"],"antonyms":[],"tipVi":"Nghĩa kỳ thi trong văn phong thông thường hay được gọi tắt là exam; nghĩa kiểm tra thường đi với giới từ of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_retell', 'en-b1-1', 'retell', '/ˌriːˈtel/', 'B1', 'phục tụng; kể lại; thuật lại', 'v.', 'retelling (n.), tell (v.)', 'Đồng nghĩa: recount', 'Dạng quá khứ và quá khứ phân từ của từ này đều là retold.', 'My grandmother retells her favourite story every winter.', NULL, 'Bà tôi kể lại câu chuyện yêu thích của bà vào mỗi dịp mùa đông.', '{"wordId":"retell","ukIpa":"/ˌriːˈtel/","usIpa":"/ˌriːˈtel/","cefr":"B1","topic":"education","senses":[{"pos":"v.","en":"to tell a story or describe events again","vi":"phục tụng; kể lại; thuật lại"}],"examples":[{"en":"My grandmother retells her favourite story every winter.","vi":"Bà tôi kể lại câu chuyện yêu thích của bà vào mỗi dịp mùa đông.","audioKind":"ex"},{"en":"Asking students to retell a story in their own words can improve comprehension and speaking skills.","vi":"Yêu cầu học sinh kể lại một câu chuyện bằng ngôn từ của riêng mình có thể cải thiện khả năng hiểu và kỹ năng nói.","audioKind":"ex2"}],"collocations":[{"en":"retell a story","vi":"kể lại một câu chuyện"},{"en":"retell events","vi":"thuật lại các sự kiện"},{"en":"retell in your own words","vi":"kể lại bằng ngôn từ của chính bạn"}],"wordFamily":["retelling (n.)","tell (v.)"],"synonyms":["recount"],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ của từ này đều là retold.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_campus', 'en-b1-1', 'campus', '/ˈkæmpəs/', 'B1', 'khuôn viên trường đại học; khu học xá', 'n.', NULL, NULL, 'Diễn đạt "trong khuôn viên trường" thường dùng on campus và không đi kèm mạo từ.', 'We found a quiet bench near the campus library.', NULL, 'Chúng tôi tìm thấy một chiếc ghế đá yên tĩnh gần thư viện trường.', '{"wordId":"campus","ukIpa":"/ˈkæmpəs/","usIpa":"/ˈkæmpəs/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"the grounds and buildings belonging to a university or college","vi":"khuôn viên trường đại học; khu học xá"}],"examples":[{"en":"We found a quiet bench near the campus library.","vi":"Chúng tôi tìm thấy một chiếc ghế đá yên tĩnh gần thư viện trường.","audioKind":"ex"},{"en":"Providing affordable accommodation on campus can help students spend less time commuting and more time studying.","vi":"Việc cung cấp chỗ ở giá cả phải chăng trong khuôn viên trường có thể giúp sinh viên giảm bớt thời gian đi lại và có nhiều thời gian học tập hơn.","audioKind":"ex2"}],"collocations":[{"en":"on campus","vi":"trong khuôn viên trường"},{"en":"off campus","vi":"ngoài khuôn viên trường"},{"en":"university campus","vi":"khuôn viên đại học"},{"en":"campus facilities","vi":"cơ sở vật chất của trường"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Diễn đạt \"trong khuôn viên trường\" thường dùng on campus và không đi kèm mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_1_1', 'en-b1-1', 'Cách dùng “examination” (n.) — kỳ thi; bài kiểm tra năng lực', 'take an examination  ·  pass an examination  ·  a medical examination', 'Nghĩa kỳ thi trong văn phong thông thường hay được gọi tắt là exam; nghĩa kiểm tra thường đi với giới từ of.', 'Họ từ (Word Family): examine (v.), examiner (n.), examinee (n.) | Đồng nghĩa: exam, inspection', '[{"hanzi":"She felt relieved when her final examination was over.","pinyin":"","meaning":"Cô ấy cảm thấy nhẹ nhõm khi kỳ thi cuối kỳ đã kết thúc."},{"hanzi":"A detailed examination of local housing conditions can help governments identify communities that need urgent support.","pinyin":"","meaning":"Việc khảo sát chi tiết điều kiện nhà ở địa phương có thể giúp chính phủ xác định các cộng đồng đang cần sự hỗ trợ khẩn cấp."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_1_2', 'en-b1-1', 'Cách dùng “dormitory” (n.) — phòng ngủ tập thể', 'shared dormitory  ·  university dormitory  ·  dormitory room', 'Trong tiếng Anh-Mỹ thường chỉ tòa nhà ký túc xá; tiếng Anh-Anh cũng thường chỉ phòng ngủ nhiều giường.', 'Đồng nghĩa: dorm', '[{"hanzi":"We shared a dormitory with six other travellers.","pinyin":"","meaning":"Chúng tôi ở chung phòng ngủ tập thể với sáu du khách khác."},{"hanzi":"Living in a university dormitory can help new students build friendships and adjust to campus life.","pinyin":"","meaning":"Sống trong ký túc xá đại học có thể giúp sinh viên mới kết bạn và thích nghi với đời sống khuôn viên trường."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_1_3', 'en-b1-1', 'Cách dùng “cheating” (n.) — sự gian lận; hành vi gian lận', 'cheating in exams  ·  prevent cheating  ·  accuse someone of cheating', 'Cheating đóng vai trò danh từ chỉ hành vi thường không đếm được; cheat cũng có thể chỉ kẻ gian lận.', 'Họ từ (Word Family): cheat (v.), cheat (n.), cheater (n.) | Đồng nghĩa: dishonesty · Trái nghĩa: honesty', '[{"hanzi":"Peeking at another player''s cards is cheating, even among friends.","pinyin":"","meaning":"Liếc nhìn bài của người chơi khác là gian lận, ngay cả khi chơi giữa những người bạn với nhau."},{"hanzi":"Schools can discourage cheating by designing assessments that reward independent thinking rather than the simple recall of facts.","pinyin":"","meaning":"Nhà trường có thể ngăn chặn nạn gian lận bằng cách thiết kế các bài kiểm tra khen thưởng tư duy độc lập thay vì chỉ ghi nhớ thông tin đơn thuần."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_1_4', 'en-b1-1', 'Cách dùng “fluent” (adj.) — trôi chảy; lưu loát', 'fluent in English  ·  a fluent speaker  ·  fluent speech', 'Nói trôi chảy một ngôn ngữ dùng be fluent in; lưu loát không có nghĩa là hoàn toàn không sai sót.', 'Họ từ (Word Family): fluency (n.), fluently (adv.) | Trái nghĩa: halting', '[{"hanzi":"She became fluent in Spanish after living abroad.","pinyin":"","meaning":"Cô ấy đã nói tiếng Tây Ban Nha trôi chảy sau khi sống ở nước ngoài."},{"hanzi":"Fluent speakers may still make grammatical mistakes, so language assessments should consider both communication skills and accuracy.","pinyin":"","meaning":"Những người nói lưu loát vẫn có thể mắc lỗi ngữ pháp, vì vậy các bài kiểm tra ngôn ngữ nên xem xét cả kỹ năng giao tiếp lẫn độ chính xác."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
