INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_1_1_4', 'ten_b1_1_1', 'unit', 'We finished the first unit before our lunch break.', 'We finished the first unit before our lunch break.', '/ˈjuːnɪt/', 'Chúng tôi đã hoàn thành bài học đầu tiên trước giờ nghỉ trưa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
