INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_1_1_6', 'ten_b1_1_1', 'subtraction', 'We practised subtraction by taking buttons out of a bowl.', 'We practised subtraction by taking buttons out of a bowl.', '/səbˈtrækʃən/', 'Chúng tôi đã luyện tập phép trừ bằng cách lấy những chiếc cúc áo ra khỏi một cái bát.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_1_1_7', 'ten_b1_1_1', 'requirement', 'Wearing a helmet is a requirement at this skatepark.', 'Wearing a helmet is a requirement at this skatepark.', '/rɪˈkwaɪrmənt/', 'Đội mũ bảo hiểm là một yêu cầu bắt buộc tại công viên trượt ván này.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_1_1_8', 'ten_b1_1_1', 'cheating', 'Peeking at another player''s cards is cheating, even among friends.', 'Peeking at another player''s cards is cheating, even among friends.', '/ˈtʃiːtɪŋ/', 'Liếc nhìn bài của người chơi khác là gian lận, ngay cả khi chơi giữa những người bạn với nhau.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_1_1_1', 'en-b1-1', 'ten_b1_1_1', 'listening', 'listening', 'Could you give me a quick summary of the meeting?', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chị gái tôi tốt nghiệp đại học và bắt đầu làm việc ở gần nhà.","Nhân giá tiền lên ba lần để ra được tổng số tiền.","Cô ấy cảm thấy nhẹ nhõm khi kỳ thi cuối kỳ đã kết thúc.","Bạn có thể tóm tắt ngắn gọn cho tôi về cuộc họp được không?"]'::jsonb, 3, 'Could you give me a quick summary of the meeting? → Bạn có thể tóm tắt ngắn gọn cho tôi về cuộc họp được không?', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_1_1_2', 'en-b1-1', 'ten_b1_1_1', 'listening', 'listening', 'Multiply the price by three to find the total.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhân giá tiền lên ba lần để ra được tổng số tiền.","Sau màn giới thiệu ngắn gọn, chúng tôi bắt đầu cùng nhau nấu ăn.","Bạn sẽ tìm thấy bánh mì tươi ở khu vực bánh kẹo.","Chúng tôi đã luyện tập phép trừ bằng cách lấy những chiếc cúc áo ra khỏi một cái bát."]'::jsonb, 0, 'Multiply the price by three to find the total. → Nhân giá tiền lên ba lần để ra được tổng số tiền.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_1_1_3', 'en-b1-1', 'ten_b1_1_1', 'listening', 'listening', 'I read one chapter before turning off the light.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giảng viên của chúng tôi ở lại sau giờ học để giải thích sơ đồ.","Bà tôi kể lại câu chuyện yêu thích của bà vào mỗi dịp mùa đông.","Tôi đã đọc được một chương trước khi tắt đèn đi ngủ.","Giáo viên của chúng tôi đã giải thích về động từ nguyên thể bằng ba ví dụ đơn giản."]'::jsonb, 2, 'I read one chapter before turning off the light. → Tôi đã đọc được một chương trước khi tắt đèn đi ngủ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_1_2', 'en-b1-1', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_1_2_1', 'ten_b1_1_2', 'summary', 'A clear summary at the beginning of a report helps readers understand its main findings quickly.', 'A clear summary at the beginning of a report helps readers understand its main findings quickly.', '/ˈsʌməri/', 'Một bản tóm tắt rõ ràng ở phần đầu của báo cáo giúp người đọc nhanh chóng nắm bắt được các kết quả chính.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_1_2_2', 'ten_b1_1_2', 'multiply', 'Bacteria can multiply rapidly in warm conditions, making proper food storage essential for public health.', 'Bacteria can multiply rapidly in warm conditions, making proper food storage essential for public health.', '/ˈmʌltɪplaɪ/', 'Vi khuẩn có thể sinh sôi nhanh chóng trong điều kiện ấm áp, khiến việc bảo quản thực phẩm đúng cách trở nên cốt yếu đối với sức khỏe cộng đồng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_1_2_3', 'ten_b1_1_2', 'chapter', 'The final chapter examines how public transport investment can reduce inequality in rapidly growing cities.', 'The final chapter examines how public transport investment can reduce inequality in rapidly growing cities.', '/ˈtʃæptər/', 'Chương cuối cùng xem xét việc đầu tư vào giao thông công cộng có thể làm giảm bất bình đẳng ở các thành phố đang phát triển nhanh như thế nào.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_1_2_4', 'ten_b1_1_2', 'unit', 'Each unit of the course introduces practical skills that students can apply in the workplace.', 'Each unit of the course introduces practical skills that students can apply in the workplace.', '/ˈjuːnɪt/', 'Mỗi bài học trong khóa học đều giới thiệu các kỹ năng thực tế mà học viên có thể ứng dụng tại nơi làm việc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_1_2_5', 'ten_b1_1_2', 'fluent', 'Fluent speakers may still make grammatical mistakes, so language assessments should consider both communication skills and accuracy.', 'Fluent speakers may still make grammatical mistakes, so language assessments should consider both communication skills and accuracy.', '/ˈfluːənt/', 'Những người nói lưu loát vẫn có thể mắc lỗi ngữ pháp, vì vậy các bài kiểm tra ngôn ngữ nên xem xét cả kỹ năng giao tiếp lẫn độ chính xác.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_1_2_6', 'ten_b1_1_2', 'subtraction', 'A secure understanding of subtraction helps children develop the numerical skills needed for everyday financial decisions.', 'A secure understanding of subtraction helps children develop the numerical skills needed for everyday financial decisions.', '/səbˈtrækʃən/', 'Việc nắm vững phép trừ giúp trẻ phát triển các kỹ năng tính toán cần thiết cho các quyết định tài chính hàng ngày.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_1_2_1', 'en-b1-1', 'ten_b1_1_2', 'listening', 'listening', 'A clear summary at the beginning of a report helps readers understand its main findings quickly.', NULL, 'Trong câu vừa nghe, từ “summary” mang nghĩa nào sau đây?', '["trao đổi; đổi","nước hoa","bản tóm tắt; bản tổng kết","nhà ảo thuật"]'::jsonb, 2, '“summary” (/ˈsʌməri/): bản tóm tắt; bản tổng kết. Câu đầy đủ: A clear summary at the beginning of a report helps readers understand its main findings quickly.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_1_2_2', 'en-b1-1', 'ten_b1_1_2', 'listening', 'listening', 'Bacteria can multiply rapidly in warm conditions, making proper food storage essential for public health.', NULL, 'Trong câu vừa nghe, từ “multiply” mang nghĩa nào sau đây?', '["nguyên liệu; thành phần (nấu ăn)","nhân lên; làm phép nhân","không thể; không có khả năng","vợt (thể thao)"]'::jsonb, 1, '“multiply” (/ˈmʌltɪplaɪ/): nhân lên; làm phép nhân. Câu đầy đủ: Bacteria can multiply rapidly in warm conditions, making proper food storage essential for public health.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
