INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_1_2', 'en-b1-1', NULL, 'comprehensive_test', 'listening', 'Multiply the price by three to find the total.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Lina vắng mặt ở lớp vì cô ấy cảm thấy không khỏe.","Chúng tôi đã luyện tập tính nhẩm trong lúc chờ xe buýt.","Nhân giá tiền lên ba lần để ra được tổng số tiền.","Chúng tôi đã luyện tập phép trừ bằng cách lấy những chiếc cúc áo ra khỏi một cái bát."]'::jsonb, 2, 'Multiply the price by three to find the total. → Nhân giá tiền lên ba lần để ra được tổng số tiền.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_1_3', 'en-b1-1', NULL, 'comprehensive_test', 'listening', 'chapter', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quần áo thể thao; trang phục thể thao","chương (sách); hồi","đau; nhức mỏi (nhất là khi chạm vào hoặc cử động)","trao đổi; đổi"]'::jsonb, 1, 'chapter (/ˈtʃæptər/) → chương (sách); hồi; giai đoạn (trong cuộc đời hoặc lịch sử); phân hội địa phương (của một tổ chức lớn)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_1_4', 'en-b1-1', NULL, 'comprehensive_test', 'listening', 'We finished the first unit before our lunch break.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bà tôi kể lại câu chuyện yêu thích của bà vào mỗi dịp mùa đông.","Chị gái tôi tốt nghiệp đại học và bắt đầu làm việc ở gần nhà.","Mô hình này cho thấy kết cấu của một cây cầu gỗ.","Chúng tôi đã hoàn thành bài học đầu tiên trước giờ nghỉ trưa."]'::jsonb, 3, 'We finished the first unit before our lunch break. → Chúng tôi đã hoàn thành bài học đầu tiên trước giờ nghỉ trưa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_1_5', 'en-b1-1', NULL, 'comprehensive_test', 'listening', 'fluent', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trôi chảy; lưu loát","hoạt động buôn bán, giao thương hàng hóa hoặc dịch vụ","giấy phép; bằng lái; chứng chỉ","đan; đan len"]'::jsonb, 0, 'fluent (/ˈfluːənt/) → trôi chảy; lưu loát', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_1_6', 'en-b1-1', NULL, 'comprehensive_test', 'listening', 'We practised subtraction by taking buttons out of a bowl.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã luyện tập phép trừ bằng cách lấy những chiếc cúc áo ra khỏi một cái bát.","Cô ấy đã nói tiếng Tây Ban Nha trôi chảy sau khi sống ở nước ngoài.","Chúng tôi tìm thấy một chiếc ghế đá yên tĩnh gần thư viện trường.","Bà tôi kể lại câu chuyện yêu thích của bà vào mỗi dịp mùa đông."]'::jsonb, 0, 'We practised subtraction by taking buttons out of a bowl. → Chúng tôi đã luyện tập phép trừ bằng cách lấy những chiếc cúc áo ra khỏi một cái bát.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
