INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_1_8', 'en-b1-1', NULL, 'comprehensive_test', 'listening', 'Peeking at another player''s cards is cheating, even among friends.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chị gái tôi tốt nghiệp đại học và bắt đầu làm việc ở gần nhà.","Giảng viên của chúng tôi ở lại sau giờ học để giải thích sơ đồ.","Liếc nhìn bài của người chơi khác là gian lận, ngay cả khi chơi giữa những người bạn với nhau.","Bà tôi kể lại câu chuyện yêu thích của bà vào mỗi dịp mùa đông."]'::jsonb, 2, 'Peeking at another player''s cards is cheating, even among friends. → Liếc nhìn bài của người chơi khác là gian lận, ngay cả khi chơi giữa những người bạn với nhau.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
