INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_1_18', 'en-b1-1', NULL, 'comprehensive_test', 'reading', NULL, 'A clear summary at the beginning of a report helps readers understand its main findings quickly.', 'Dựa vào câu trên, từ “summary” có nghĩa phù hợp nhất là gì?', '["bể cá cảnh; hồ cá","tiếng sấm; tiếng sét","bản tóm tắt; bản tổng kết","sự lựa chọn; phương án"]'::jsonb, 2, 'summary: bản tóm tắt; bản tổng kết; tóm tắt; khái quát. Dịch cả câu: Một bản tóm tắt rõ ràng ở phần đầu của báo cáo giúp người đọc nhanh chóng nắm bắt được các kết quả chính.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_1_19', 'en-b1-1', NULL, 'comprehensive_test', 'reading', NULL, 'Bacteria can multiply rapidly in warm conditions, making proper food storage essential for public health.', 'Dựa vào câu trên, từ “multiply” có nghĩa phù hợp nhất là gì?', '["kỳ lạ; quái lạ; bất thường","ôn tập; ôn thi","nhân lên; làm phép nhân","thú vị; dễ chịu; mang lại niềm vui"]'::jsonb, 2, 'multiply: nhân lên; làm phép nhân; tăng lên nhanh chóng; sinh sôi nảy nở. Dịch cả câu: Vi khuẩn có thể sinh sôi nhanh chóng trong điều kiện ấm áp, khiến việc bảo quản thực phẩm đúng cách trở nên cốt yếu đối với sức khỏe cộng đồng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_1_20', 'en-b1-1', NULL, 'comprehensive_test', 'reading', NULL, 'The final chapter examines how public transport investment can reduce inequality in rapidly growing cities.', 'Dựa vào câu trên, từ “chapter” có nghĩa phù hợp nhất là gì?', '["bản tin định kỳ; thông cáo","tuyệt vời; cực kỳ thú vị","vật nặng; khối lượng chuyên chở","chương (sách); hồi"]'::jsonb, 3, 'chapter: chương (sách); hồi; giai đoạn (trong cuộc đời hoặc lịch sử); phân hội địa phương (của một tổ chức lớn). Dịch cả câu: Chương cuối cùng xem xét việc đầu tư vào giao thông công cộng có thể làm giảm bất bình đẳng ở các thành phố đang phát triển nhanh như thế nào.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_1_21', 'en-b1-1', NULL, 'comprehensive_test', 'reading', NULL, 'Each unit of the course introduces practical skills that students can apply in the workplace.', 'Dựa vào câu trên, từ “unit” có nghĩa phù hợp nhất là gì?', '["hiểu lầm; hiểu sai","khán giả; thính giả","đơn vị; bài học","kỳ lạ; quái lạ; bất thường"]'::jsonb, 2, 'unit: đơn vị; bài học; thiết bị; bộ phận; tiểu đội; ban. Dịch cả câu: Mỗi bài học trong khóa học đều giới thiệu các kỹ năng thực tế mà học viên có thể ứng dụng tại nơi làm việc.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
