INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_1_24', 'en-b1-1', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khuôn viên trường đại học; khu học xá”', '["campus","widely","giant","chilli"]'::jsonb, 0, 'khuôn viên trường đại học; khu học xá → campus (/ˈkæmpəs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-2', 'en', 'Bài 2: Giáo dục & Trường học (2) - CEFR B1', 'CEFR B1', 'B1 · Giáo dục', '22 từ vựng Tiếng Anh CEFR B1 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3002, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grade', 'en-b1-2', 'grade', '/ɡreɪd/', 'B1', 'điểm số; cấp độ chất lượng; khối lớp (học đường); chấm điểm; phân loại', 'n.', 'grading (n.), graded (adj.)', NULL, 'Khi chỉ khối lớp, từ này dùng phổ biến trong tiếng Anh Mỹ; tiếng Anh Anh thường dùng year.', 'I got a good grade on my science project.', NULL, 'Tôi đạt điểm tốt trong dự án khoa học của mình.', '{"wordId":"grade","ukIpa":"/ɡreɪd/","usIpa":"/ɡreɪd/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a mark showing achievement, or a level of quality","vi":"điểm số; cấp độ chất lượng"},{"pos":"n.","en":"a school year level, especially in the American system","vi":"khối lớp (học đường)"},{"pos":"v.","en":"to assess work or sort things by quality","vi":"chấm điểm; phân loại"}],"examples":[{"en":"I got a good grade on my science project.","vi":"Tôi đạt điểm tốt trong dự án khoa học của mình.","audioKind":"ex"},{"en":"Teachers should grade assignments consistently so that students understand how their performance is assessed across different subjects.","vi":"Giáo viên nên chấm điểm các bài tập một cách nhất quán để học sinh hiểu cách năng lực của các em được đánh giá qua các môn học khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"get a good grade","vi":"đạt điểm tốt"},{"en":"grade assignments","vi":"chấm điểm bài tập"},{"en":"in sixth grade","vi":"học lớp sáu"},{"en":"high-grade materials","vi":"vật liệu chất lượng cao"}],"wordFamily":["grading (n.)","graded (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ khối lớp, từ này dùng phổ biến trong tiếng Anh Mỹ; tiếng Anh Anh thường dùng year.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stationery', 'en-b1-2', 'stationery', '/ˈsteɪʃəneri/', 'B1', 'văn phòng phẩm', 'n.', 'stationer (n.)', NULL, 'Đây là danh từ không đếm được; tránh nhầm lẫn với từ stationary (mang nghĩa tĩnh tại, đứng yên).', 'I bought some stationery for my new evening class.', NULL, 'Tôi đã mua vài món văn phòng phẩm cho lớp học buổi tối mới của mình.', '{"wordId":"stationery","ukIpa":"/ˈsteɪʃənəri/","usIpa":"/ˈsteɪʃəneri/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"Materials used for writing, such as paper, pens, and envelopes.","vi":"văn phòng phẩm"}],"examples":[{"en":"I bought some stationery for my new evening class.","vi":"Tôi đã mua vài món văn phòng phẩm cho lớp học buổi tối mới của mình.","audioKind":"ex"},{"en":"Providing basic stationery can help disadvantaged students participate more fully in classroom activities and complete assignments.","vi":"Việc cung cấp văn phòng phẩm cơ bản có thể giúp học sinh có hoàn cảnh khó khăn tham gia đầy đủ hơn vào các hoạt động trên lớp và hoàn thành bài tập.","audioKind":"ex2"}],"collocations":[{"en":"office stationery","vi":"văn phòng phẩm công sở"},{"en":"stationery supplies","vi":"đồ dùng văn phòng phẩm"},{"en":"stationery shop","vi":"cửa hàng văn phòng phẩm"}],"wordFamily":["stationer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Đây là danh từ không đếm được; tránh nhầm lẫn với từ stationary (mang nghĩa tĩnh tại, đứng yên).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_translate', 'en-b1-2', 'translate', '/trænzˈleɪt/', 'B1', 'dịch; dịch thuật; chuyển hóa; chuyển đổi', 'v.', 'translation (n.), translator (n.), translatable (adj.)', NULL, 'Chuyển ngữ từ ngôn ngữ này sang ngôn ngữ khác dùng cấu trúc translate from…into….', 'Could you translate this recipe into English for me?', NULL, 'Bạn có thể dịch giúp tôi công thức nấu ăn này sang tiếng Anh được không?', '{"wordId":"translate","ukIpa":"/trænzˈleɪt/","usIpa":"/trænzˈleɪt/","cefr":"B1","topic":"education","senses":[{"pos":"v.","en":"To express words or writing in another language","vi":"dịch; dịch thuật"},{"pos":"v.","en":"To change something into a different form or practical result","vi":"chuyển hóa; chuyển đổi"}],"examples":[{"en":"Could you translate this recipe into English for me?","vi":"Bạn có thể dịch giúp tôi công thức nấu ăn này sang tiếng Anh được không?","audioKind":"ex"},{"en":"Governments must translate environmental commitments into practical policies that encourage businesses to reduce emissions.","vi":"Chính phủ phải chuyển hóa các cam kết bảo vệ môi trường thành các chính sách thiết thực nhằm khuyến khích doanh nghiệp cắt giảm khí thải.","audioKind":"ex2"}],"collocations":[{"en":"translate into English","vi":"dịch sang tiếng Anh"},{"en":"translate from Chinese","vi":"dịch từ tiếng Trung"},{"en":"translate ideas into action","vi":"biến ý tưởng thành hành động"}],"wordFamily":["translation (n.)","translator (n.)","translatable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chuyển ngữ từ ngôn ngữ này sang ngôn ngữ khác dùng cấu trúc translate from…into….","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dorm', 'en-b1-2', 'dorm', '/dɔːrm/', 'B1', 'ký túc xá; phòng ngủ tập thể', 'n.', 'dormitory (n.)', 'Đồng nghĩa: dormitory', 'Dorm là dạng viết tắt thân mật của dormitory, được sử dụng phổ biến trong tiếng Anh-Mỹ.', 'My dorm is just five minutes from the library.', NULL, 'Ký túc xá của tôi chỉ cách thư viện có năm phút đi bộ.', '{"wordId":"dorm","ukIpa":"/dɔːm/","usIpa":"/dɔːrm/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a building or shared room where students sleep","vi":"ký túc xá; phòng ngủ tập thể"}],"examples":[{"en":"My dorm is just five minutes from the library.","vi":"Ký túc xá của tôi chỉ cách thư viện có năm phút đi bộ.","audioKind":"ex"},{"en":"Living in a dorm can help first-year students develop social skills and adjust to university life.","vi":"Sống trong ký túc xá có thể giúp sinh viên năm nhất phát triển các kỹ năng xã hội và thích nghi với đời sống đại học.","audioKind":"ex2"}],"collocations":[{"en":"dorm room","vi":"phòng ký túc xá"},{"en":"dorm life","vi":"đời sống ký túc xá"},{"en":"college dorm","vi":"ký túc xá đại học"}],"wordFamily":["dormitory (n.)"],"synonyms":["dormitory"],"antonyms":[],"tipVi":"Dorm là dạng viết tắt thân mật của dormitory, được sử dụng phổ biến trong tiếng Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_journal', 'en-b1-2', 'journal', '/ˈdʒɝːnəl/', 'B1', 'tạp chí chuyên khảo, tạp chí học thuật; nhật ký, sổ tay ghi chép', 'n.', NULL, 'Đồng nghĩa: periodical, diary', 'journal thường chỉ tạp chí chuyên ngành; khi chỉ ghi chép cá nhân thì gần nghĩa với diary.', 'I keep a journal beside my bed every night.', NULL, 'Tôi giữ một cuốn nhật ký cạnh giường ngủ mỗi tối.', '{"wordId":"journal","ukIpa":"/ˈdʒɜːnəl/","usIpa":"/ˈdʒɝːnəl/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a publication containing articles about a particular subject","vi":"tạp chí chuyên khảo, tạp chí học thuật"},{"pos":"n.","en":"a personal record of experiences, thoughts, or events","vi":"nhật ký, sổ tay ghi chép"}],"examples":[{"en":"I keep a journal beside my bed every night.","vi":"Tôi giữ một cuốn nhật ký cạnh giường ngủ mỗi tối.","audioKind":"ex"},{"en":"Researchers publish their findings in academic journals so that other experts can evaluate the evidence.","vi":"Các nhà nghiên cứu công bố phát hiện của họ trên các tạp chí học thuật để các chuyên gia khác có thể đánh giá bằng chứng.","audioKind":"ex2"}],"collocations":[{"en":"an academic journal","vi":"tạp chí học thuật"},{"en":"a medical journal","vi":"tạp chí y học"},{"en":"keep a journal","vi":"viết nhật ký"},{"en":"a journal article","vi":"bài báo tạp chí"}],"wordFamily":[],"synonyms":["periodical","diary"],"antonyms":[],"tipVi":"journal thường chỉ tạp chí chuyên ngành; khi chỉ ghi chép cá nhân thì gần nghĩa với diary.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accent', 'en-b1-2', 'accent', '/ˈæksent/', 'B1', 'giọng điệu, khẩu âm; trọng âm, dấu trọng âm; nhấn mạnh, làm nổi bật', 'n.', 'accented (adj.), accentuation (n.), accentuate (v.)', NULL, 'accent chỉ đặc điểm phát âm; dialect còn liên quan đến từ vựng và ngữ pháp.', 'Her accent reminds me of my neighbours back home.', NULL, 'Giọng điệu của cô ấy làm tôi nhớ đến những người hàng xóm ở quê nhà.', '{"wordId":"accent","ukIpa":"/ˈæksent/","usIpa":"/ˈæksent/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a pronunciation style associated with a place or social group","vi":"giọng điệu, khẩu âm"},{"pos":"n.","en":"emphasis on a syllable, or a mark indicating pronunciation","vi":"trọng âm, dấu trọng âm"},{"pos":"v.","en":"to give special emphasis or prominence to something","vi":"nhấn mạnh, làm nổi bật"}],"examples":[{"en":"Her accent reminds me of my neighbours back home.","vi":"Giọng điệu của cô ấy làm tôi nhớ đến những người hàng xóm ở quê nhà.","audioKind":"ex"},{"en":"Teachers should value different accents while helping learners develop clear pronunciation for effective international communication.","vi":"Giáo viên nên coi trọng các giọng điệu khác nhau đồng thời giúp người học phát triển phát âm rõ ràng để giao tiếp quốc tế hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"regional accent","vi":"giọng địa phương"},{"en":"strong accent","vi":"giọng nặng"},{"en":"speak with an accent","vi":"nói có giọng địa phương"},{"en":"accent mark","vi":"dấu trọng âm"}],"wordFamily":["accented (adj.)","accentuation (n.)","accentuate (v.)"],"synonyms":[],"antonyms":[],"tipVi":"accent chỉ đặc điểm phát âm; dialect còn liên quan đến từ vựng và ngữ pháp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_phrase', 'en-b1-2', 'phrase', '/freɪz/', 'B1', 'cụm từ; thành ngữ; cách nói; diễn đạt; chọn lời văn', 'n.', 'phrasing (n.), phrasal (adj.)', 'Đồng nghĩa: expression', 'Phrase là một cụm từ, không nhất thiết phải tạo thành một câu hoàn chỉnh.', 'I learned a useful phrase in my English class today.', NULL, 'Hôm nay tôi đã học được một cụm từ hữu ích trong lớp tiếng Anh.', '{"wordId":"phrase","ukIpa":"/freɪz/","usIpa":"/freɪz/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a group of words expressing an idea or forming a unit","vi":"cụm từ; thành ngữ; cách nói"},{"pos":"v.","en":"to express something using particular words","vi":"diễn đạt; chọn lời văn"}],"examples":[{"en":"I learned a useful phrase in my English class today.","vi":"Hôm nay tôi đã học được một cụm từ hữu ích trong lớp tiếng Anh.","audioKind":"ex"},{"en":"Researchers must phrase survey questions carefully to avoid influencing participants and reducing the reliability of their findings.","vi":"Các nhà nghiên cứu phải cẩn thận lựa chọn cách diễn đạt các câu hỏi khảo sát để tránh gây ảnh hưởng đến người tham gia và làm giảm độ tin cậy của kết quả nghiên cứu.","audioKind":"ex2"}],"collocations":[{"en":"a common phrase","vi":"cụm từ thông dụng"},{"en":"a noun phrase","vi":"cụm danh từ"},{"en":"phrase a question","vi":"đặt câu hỏi; chọn lời cho câu hỏi"},{"en":"a useful phrase","vi":"cụm từ hữu ích"}],"wordFamily":["phrasing (n.)","phrasal (adj.)"],"synonyms":["expression"],"antonyms":[],"tipVi":"Phrase là một cụm từ, không nhất thiết phải tạo thành một câu hoàn chỉnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_minus', 'en-b1-2', 'minus', '/ˈmaɪnəs/', 'B1', 'trừ đi; khấu trừ; âm (dưới số không); nhược điểm; điểm bất lợi', 'prep.', NULL, 'Trái nghĩa: plus', 'minus có thể dùng để chỉ phép trừ, hoặc đặt trước nhiệt độ để chỉ số âm.', 'Ten minus three leaves enough apples for everyone.', NULL, 'Mười trừ đi ba là còn đủ táo cho tất cả mọi người.', '{"wordId":"minus","ukIpa":"/ˈmaɪnəs/","usIpa":"/ˈmaɪnəs/","cefr":"B1","topic":"education","senses":[{"pos":"prep.","en":"with a particular amount taken away","vi":"trừ đi; khấu trừ"},{"pos":"adj.","en":"below zero","vi":"âm (dưới số không)"},{"pos":"n.","en":"a disadvantage or negative feature","vi":"nhược điểm; điểm bất lợi"}],"examples":[{"en":"Ten minus three leaves enough apples for everyone.","vi":"Mười trừ đi ba là còn đủ táo cho tất cả mọi người.","audioKind":"ex"},{"en":"A household''s disposable income is its total income minus taxes and other compulsory payments.","vi":"Thu nhập khả dụng của một hộ gia đình là tổng thu nhập trừ đi thuế và các khoản thanh toán bắt buộc khác.","audioKind":"ex2"}],"collocations":[{"en":"minus ten degrees","vi":"âm mười độ"},{"en":"minus sign","vi":"dấu trừ; dấu âm"},{"en":"pluses and minuses","vi":"những ưu và nhược điểm"}],"wordFamily":[],"synonyms":[],"antonyms":["plus"],"tipVi":"minus có thể dùng để chỉ phép trừ, hoặc đặt trước nhiệt độ để chỉ số âm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_progress', 'en-b1-2', 'progress', '/ˈprɑːɡres/', 'B1', 'sự tiến bộ; sự phát triển; tiến bộ; phát triển', 'n.', 'progressive (adj.), progression (n.)', 'Đồng nghĩa: advancement · Trái nghĩa: regression', 'Danh từ không đếm được; động từ trọng âm rơi vào âm tiết thứ hai, phiên âm Anh-Anh là /prəˈɡres/.', 'You have made real progress with your swimming.', NULL, 'Trình độ bơi lội của bạn đã tiến bộ thật rồi.', '{"wordId":"progress","ukIpa":"/ˈprəʊɡres/","usIpa":"/ˈprɑːɡres/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"improvement or movement towards a goal","vi":"sự tiến bộ; sự phát triển"},{"pos":"v.","en":"to improve or move towards a more advanced stage","vi":"tiến bộ; phát triển"}],"examples":[{"en":"You have made real progress with your swimming.","vi":"Trình độ bơi lội của bạn đã tiến bộ thật rồi.","audioKind":"ex"},{"en":"Regular feedback helps students monitor their progress and identify areas that require further practice.","vi":"Phản hồi thường xuyên giúp học sinh theo dõi sự tiến bộ của bản thân và xác định những phần cần luyện tập thêm.","audioKind":"ex2"}],"collocations":[{"en":"make progress","vi":"tiến bộ"},{"en":"steady progress","vi":"tiến triển đều đặn"},{"en":"in progress","vi":"đang diễn ra"}],"wordFamily":["progressive (adj.)","progression (n.)"],"synonyms":["advancement"],"antonyms":["regression"],"tipVi":"Danh từ không đếm được; động từ trọng âm rơi vào âm tiết thứ hai, phiên âm Anh-Anh là /prəˈɡres/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_instructor', 'en-b1-2', 'instructor', '/ɪnˈstrʌktər/', 'B1', 'người hướng dẫn; huấn luyện viên; giảng viên', 'n.', 'instruct (v.), instruction (n.), instructive (adj.)', 'Đồng nghĩa: trainer, teacher', 'Thường chỉ người dạy các kỹ năng cụ thể như lái xe, bơi lội.', 'Our swimming instructor showed us how to breathe properly.', NULL, 'Huấn luyện viên bơi lội của chúng tôi đã chỉ cho chúng tôi cách thở đúng cách.', '{"wordId":"instructor","ukIpa":"/ɪnˈstrʌktə/","usIpa":"/ɪnˈstrʌktər/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"Someone who teaches a particular skill or activity.","vi":"người hướng dẫn; huấn luyện viên"},{"pos":"n.","en":"A teacher at an American college or university.","vi":"giảng viên"}],"examples":[{"en":"Our swimming instructor showed us how to breathe properly.","vi":"Huấn luyện viên bơi lội của chúng tôi đã chỉ cho chúng tôi cách thở đúng cách.","audioKind":"ex"},{"en":"A qualified instructor can help older adults exercise safely and develop confidence in their physical abilities.","vi":"Một huấn luyện viên đủ trình độ có thể giúp người cao tuổi tập thể dục an toàn và xây dựng sự tự tin vào khả năng thể chất của họ.","audioKind":"ex2"}],"collocations":[{"en":"driving instructor","vi":"giáo viên dạy lái xe"},{"en":"qualified instructor","vi":"huấn luyện viên có chuyên môn"},{"en":"fitness instructor","vi":"huấn luyện viên thể hình"}],"wordFamily":["instruct (v.)","instruction (n.)","instructive (adj.)"],"synonyms":["trainer","teacher"],"antonyms":[],"tipVi":"Thường chỉ người dạy các kỹ năng cụ thể như lái xe, bơi lội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_written', 'en-b1-2', 'written', '/ˈrɪtn/', 'B1', 'bằng văn bản; có tính viết ra; phân từ quá khứ của write', 'adj.', 'write (v.), writer (n.), writing (n.)', 'Trái nghĩa: spoken', 'Các dạng thức của write là write–wrote–written.', 'Please send written instructions so I can follow them.', NULL, 'Vui lòng gửi các hướng dẫn bằng văn bản để tôi có thể làm theo.', '{"wordId":"written","ukIpa":"/ˈrɪtn/","usIpa":"/ˈrɪtn/","cefr":"B1","topic":"education","senses":[{"pos":"adj.","en":"Expressed in writing rather than speech.","vi":"bằng văn bản; có tính viết ra"},{"pos":"v.","en":"Past participle of write.","vi":"phân từ quá khứ của write"}],"examples":[{"en":"Please send written instructions so I can follow them.","vi":"Vui lòng gửi các hướng dẫn bằng văn bản để tôi có thể làm theo.","audioKind":"ex"},{"en":"Written feedback allows students to review their mistakes and improve their performance over time.","vi":"Phản hồi bằng văn bản giúp học sinh xem lại các lỗi sai và cải thiện kết quả học tập theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"written permission","vi":"sự cho phép bằng văn bản"},{"en":"written agreement","vi":"thỏa thuận bằng văn bản"},{"en":"written exam","vi":"bài thi viết"},{"en":"written feedback","vi":"phản hồi bằng văn bản"}],"wordFamily":["write (v.)","writer (n.)","writing (n.)"],"synonyms":[],"antonyms":["spoken"],"tipVi":"Các dạng thức của write là write–wrote–written.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_questionnaire', 'en-b1-2', 'questionnaire', '/ˌkwestʃəˈner/', 'B1', 'bảng câu hỏi; phiếu điều tra', 'n.', 'question (n.), question (v.), questioner (n.)', NULL, 'Từ này có hai chữ n, trọng âm rơi vào âm tiết cuối; "survey" dùng để chỉ cuộc khảo sát chung, còn bảng câu hỏi chỉ là công cụ trong đó.', 'Please complete this short questionnaire before leaving the clinic.', NULL, 'Vui lòng hoàn thành bảng câu hỏi ngắn này trước khi rời phòng khám.', '{"wordId":"questionnaire","ukIpa":"/ˌkwestʃəˈneə/","usIpa":"/ˌkwestʃəˈner/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A set of written questions used to collect information from people.","vi":"bảng câu hỏi; phiếu điều tra"}],"examples":[{"en":"Please complete this short questionnaire before leaving the clinic.","vi":"Vui lòng hoàn thành bảng câu hỏi ngắn này trước khi rời phòng khám.","audioKind":"ex"},{"en":"Researchers distributed a questionnaire to investigate how commuting time affects workers'' wellbeing and satisfaction with their jobs.","vi":"Các nhà nghiên cứu đã phát bảng câu hỏi để khảo sát thời gian đi lại ảnh hưởng thế nào đến hạnh phúc và sự hài lòng trong công việc của người lao động.","audioKind":"ex2"}],"collocations":[{"en":"complete a questionnaire","vi":"hoàn thành bảng câu hỏi"},{"en":"design a questionnaire","vi":"thiết kế bảng câu hỏi"},{"en":"distribute a questionnaire","vi":"phát bảng câu hỏi"},{"en":"questionnaire responses","vi":"phản hồi qua bảng câu hỏi"}],"wordFamily":["question (n.)","question (v.)","questioner (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ này có hai chữ n, trọng âm rơi vào âm tiết cuối; \"survey\" dùng để chỉ cuộc khảo sát chung, còn bảng câu hỏi chỉ là công cụ trong đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_apply', 'en-b1-2', 'apply', '/əˈplaɪ/', 'B1', 'nộp đơn chính thức xin việc, vị trí hoặc xin phép; áp dụng vào thực tế hoặc có liên quan đến một tình huống; bôi hoặc xoa một chất lên bề mặt', 'v.', 'application (n.), applicant (n.), applicable (adj.)', NULL, 'apply for đi với việc xin thứ gì đó; apply to đi với tổ chức hoặc đối tượng áp dụng.', 'Apply sunscreen before you go outside on sunny days.', NULL, 'Hãy bôi kem chống nắng trước khi bạn ra ngoài vào những ngày nắng.', '{"wordId":"apply","ukIpa":"/əˈplaɪ/","usIpa":"/əˈplaɪ/","cefr":"B1","topic":"education","senses":[{"pos":"v.","en":"To formally ask for a job, place, or permission","vi":"nộp đơn chính thức xin việc, vị trí hoặc xin phép"},{"pos":"v.","en":"To use something practically, or be relevant to a situation","vi":"áp dụng vào thực tế hoặc có liên quan đến một tình huống"},{"pos":"v.","en":"To spread a substance onto a surface","vi":"bôi hoặc xoa một chất lên bề mặt"}],"examples":[{"en":"Apply sunscreen before you go outside on sunny days.","vi":"Hãy bôi kem chống nắng trước khi bạn ra ngoài vào những ngày nắng.","audioKind":"ex"},{"en":"Universities should encourage students from disadvantaged backgrounds to apply for scholarships that cover tuition and living expenses.","vi":"Các trường đại học nên khuyến khích sinh viên có hoàn cảnh khó khăn nộp đơn xin học bổng bao gồm cả học phí và sinh hoạt phí.","audioKind":"ex2"}],"collocations":[{"en":"apply for a job","vi":"xin việc"},{"en":"apply to a university","vi":"nộp đơn vào trường đại học"},{"en":"apply knowledge","vi":"áp dụng kiến thức"},{"en":"apply sunscreen","vi":"bôi kem chống nắng"}],"wordFamily":["application (n.)","applicant (n.)","applicable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"apply for đi với việc xin thứ gì đó; apply to đi với tổ chức hoặc đối tượng áp dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_certificate', 'en-b1-2', 'certificate', '/sərˈtɪfɪkət/', 'B1', 'chứng chỉ; văn bằng; giấy chứng nhận', 'n.', 'certify (v.), certification (n.), certified (adj.)', NULL, 'certificate dùng chung cho giấy chứng nhận hoặc chứng chỉ nghề nghiệp, không nhất thiết là bằng cấp đại học.', 'Lena proudly showed her swimming certificate to her grandparents.', NULL, 'Lena tự hào khoe chứng chỉ bơi lội của mình với ông bà.', '{"wordId":"certificate","ukIpa":"/səˈtɪfɪkət/","usIpa":"/sərˈtɪfɪkət/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"An official document proving a fact or qualification.","vi":"chứng chỉ; văn bằng; giấy chứng nhận"}],"examples":[{"en":"Lena proudly showed her swimming certificate to her grandparents.","vi":"Lena tự hào khoe chứng chỉ bơi lội của mình với ông bà.","audioKind":"ex"},{"en":"A professional certificate can improve employment prospects, but employers also value practical experience.","vi":"Chứng chỉ chuyên môn có thể cải thiện cơ hội việc làm, nhưng các nhà tuyển dụng cũng đánh giá cao kinh nghiệm thực tế.","audioKind":"ex2"}],"collocations":[{"en":"a birth certificate","vi":"giấy khai sinh"},{"en":"a medical certificate","vi":"giấy chứng nhận y tế"},{"en":"a professional certificate","vi":"chứng chỉ chuyên môn"},{"en":"award a certificate","vi":"cấp chứng chỉ"}],"wordFamily":["certify (v.)","certification (n.)","certified (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"certificate dùng chung cho giấy chứng nhận hoặc chứng chỉ nghề nghiệp, không nhất thiết là bằng cấp đại học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_explanation', 'en-b1-2', 'explanation', '/ˌekspləˈneɪʃən/', 'B1', 'lời giải thích; sự giải thích; lý do; lời biện minh', 'n.', 'explain (v.), explanatory (adj.), explainable (adj.)', 'Đồng nghĩa: clarification', '"explanation of" thường dùng để giải thích nội dung, còn "explanation for" thường dùng để giải thích nguyên nhân.', 'Her simple explanation helped me understand the new game.', NULL, 'Lời giải thích đơn giản của cô ấy đã giúp tôi hiểu trò chơi mới.', '{"wordId":"explanation","ukIpa":"/ˌekspləˈneɪʃən/","usIpa":"/ˌekspləˈneɪʃən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"information that makes something easier to understand","vi":"lời giải thích; sự giải thích"},{"pos":"n.","en":"a reason given for why something happened","vi":"lý do; lời biện minh"}],"examples":[{"en":"Her simple explanation helped me understand the new game.","vi":"Lời giải thích đơn giản của cô ấy đã giúp tôi hiểu trò chơi mới.","audioKind":"ex"},{"en":"One possible explanation for declining car ownership is the growing availability of reliable public transport.","vi":"Một lý do có thể giải thích cho việc tỷ lệ sở hữu ô tô giảm là sự phổ biến ngày càng tăng của các phương tiện giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"clear explanation","vi":"lời giải thích rõ ràng"},{"en":"give an explanation","vi":"đưa ra lời giải thích"},{"en":"explanation for","vi":"lời giải thích cho (lý do)"},{"en":"explanation of","vi":"sự giải thích về (nội dung)"}],"wordFamily":["explain (v.)","explanatory (adj.)","explainable (adj.)"],"synonyms":["clarification"],"antonyms":[],"tipVi":"\"explanation of\" thường dùng để giải thích nội dung, còn \"explanation for\" thường dùng để giải thích nguyên nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_practical', 'en-b1-2', 'practical', '/ˈpræktɪkəl/', 'B1', 'thuộc thực tế; mang tính thực hành; thực tế; thiết thực; tháo vát', 'adj.', 'practically (adv.), practicality (n.), impractical (adj.)', 'Đồng nghĩa: hands-on, useful · Trái nghĩa: theoretical, impractical', 'practical có thể nhấn mạnh vào việc tự tay làm, hoặc dùng để chỉ tính thực tế và khả thi.', 'The course gave me practical experience in repairing bikes.', NULL, 'Khóa học đã mang lại cho tôi kinh nghiệm thực tế trong việc sửa chữa xe đạp.', '{"wordId":"practical","ukIpa":"/ˈpræktɪkəl/","usIpa":"/ˈpræktɪkəl/","cefr":"B1","topic":"education","senses":[{"pos":"adj.","en":"involving real activities and experience rather than only ideas","vi":"thuộc thực tế; mang tính thực hành"},{"pos":"adj.","en":"useful or suitable for real situations","vi":"thực tế; thiết thực"},{"pos":"adj.","en":"good at solving everyday problems and making or repairing things","vi":"thực tế; tháo vát"}],"examples":[{"en":"The course gave me practical experience in repairing bikes.","vi":"Khóa học đã mang lại cho tôi kinh nghiệm thực tế trong việc sửa chữa xe đạp.","audioKind":"ex"},{"en":"Schools should combine academic learning with practical skills to prepare students for a changing workplace.","vi":"Nhà trường nên kết hợp việc học lý thuyết với các kỹ năng thiết thực để chuẩn bị cho học sinh trước một môi trường làm việc không ngừng thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"practical experience","vi":"kinh nghiệm thực tế"},{"en":"practical skills","vi":"kỹ năng thiết thực"},{"en":"practical solution","vi":"giải pháp khả thi"},{"en":"practical advice","vi":"lời khuyên thiết thực"}],"wordFamily":["practically (adv.)","practicality (n.)","impractical (adj.)"],"synonyms":["hands-on","useful"],"antonyms":["theoretical","impractical"],"tipVi":"practical có thể nhấn mạnh vào việc tự tay làm, hoặc dùng để chỉ tính thực tế và khả thi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_semester', 'en-b1-2', 'semester', '/sɪˈmestɚ/', 'B1', 'học kỳ', 'n.', NULL, NULL, 'thường chỉ một trong hai học kỳ của năm học, không tương đương với nửa năm.', 'I''m taking a photography class at college this semester.', NULL, 'Học kỳ này tôi đang tham gia một lớp học nhiếp ảnh ở trường cao đẳng.', '{"wordId":"semester","ukIpa":"/sɪˈmestə/","usIpa":"/sɪˈmestɚ/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"one of the two main periods of an academic year","vi":"học kỳ"}],"examples":[{"en":"I''m taking a photography class at college this semester.","vi":"Học kỳ này tôi đang tham gia một lớp học nhiếp ảnh ở trường cao đẳng.","audioKind":"ex"},{"en":"Offering work placements during the final semester can help university students move successfully into employment.","vi":"Cung cấp cơ hội thực tập trong học kỳ cuối có thể giúp sinh viên đại học bước vào thị trường việc làm một cách thuận lợi.","audioKind":"ex2"}],"collocations":[{"en":"first semester","vi":"học kỳ đầu tiên"},{"en":"fall semester","vi":"học kỳ mùa thu"},{"en":"semester break","vi":"kỳ nghỉ giữa học kỳ"},{"en":"end of the semester","vi":"cuối học kỳ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"thường chỉ một trong hai học kỳ của năm học, không tương đương với nửa năm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_encourage', 'en-b1-2', 'encourage', '/ɪnˈkɜːrɪdʒ/', 'B1', 'khích lệ; động viên; thúc đẩy; khuyến khích phát triển', 'v.', 'encouragement (n.), encouraging (adj.), encouraged (adj.)', 'Đồng nghĩa: support, motivate · Trái nghĩa: discourage', 'Dùng encourage sb to do sth để diễn tả việc khuyến khích ai đó làm điều gì.', 'My sister encouraged me to join the swimming club.', NULL, 'Chị tôi đã khuyến khích tôi tham gia câu lạc bộ bơi lội.', '{"wordId":"encourage","ukIpa":"/ɪnˈkʌrɪdʒ/","usIpa":"/ɪnˈkɜːrɪdʒ/","cefr":"B1","topic":"education","senses":[{"pos":"v.","en":"Give someone confidence or support to do something","vi":"khích lệ; động viên"},{"pos":"v.","en":"Make an activity or development more likely","vi":"thúc đẩy; khuyến khích phát triển"}],"examples":[{"en":"My sister encouraged me to join the swimming club.","vi":"Chị tôi đã khuyến khích tôi tham gia câu lạc bộ bơi lội.","audioKind":"ex"},{"en":"Local governments can encourage cycling by providing safer routes and secure bicycle parking near workplaces.","vi":"Chính quyền địa phương có thể thúc đẩy việc đạp xe bằng cách cung cấp các tuyến đường an toàn hơn và bãi đỗ xe đạp an toàn gần nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"encourage someone to do something","vi":"khuyến khích ai đó làm điều gì"},{"en":"strongly encourage","vi":"nhiệt liệt khuyến khích"},{"en":"encourage participation","vi":"khuyến khích sự tham gia"}],"wordFamily":["encouragement (n.)","encouraging (adj.)","encouraged (adj.)"],"synonyms":["support","motivate"],"antonyms":["discourage"],"tipVi":"Dùng encourage sb to do sth để diễn tả việc khuyến khích ai đó làm điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alphabetical', 'en-b1-2', 'alphabetical', '/ˌælfəˈbetɪkəl/', 'B1', 'theo thứ tự bảng chữ cái', 'adj.', 'alphabet (n.), alphabetically (adv.)', NULL, 'Thường dùng cụm in alphabetical order để chỉ việc xếp theo thứ tự bảng chữ cái.', 'Please put these names in alphabetical order before lunch.', NULL, 'Vui lòng sắp xếp các tên này theo thứ tự bảng chữ cái trước bữa trưa.', '{"wordId":"alphabetical","ukIpa":"/ˌælfəˈbetɪkəl/","usIpa":"/ˌælfəˈbetɪkəl/","cefr":"B1","topic":"education","senses":[{"pos":"adj.","en":"arranged in the order of the alphabet","vi":"theo thứ tự bảng chữ cái"}],"examples":[{"en":"Please put these names in alphabetical order before lunch.","vi":"Vui lòng sắp xếp các tên này theo thứ tự bảng chữ cái trước bữa trưa.","audioKind":"ex"},{"en":"An alphabetical index helps students locate specific topics quickly in a lengthy reference book.","vi":"Bảng mục lục theo thứ tự bảng chữ cái giúp học sinh nhanh chóng tìm thấy các chủ đề cụ thể trong một cuốn sách tham khảo dày.","audioKind":"ex2"}],"collocations":[{"en":"alphabetical order","vi":"thứ tự bảng chữ cái"},{"en":"alphabetical list","vi":"danh sách sắp xếp theo bảng chữ cái"},{"en":"alphabetical index","vi":"bảng chỉ mục theo thứ tự bảng chữ cái"}],"wordFamily":["alphabet (n.)","alphabetically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cụm in alphabetical order để chỉ việc xếp theo thứ tự bảng chữ cái.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_source', 'en-b1-2', 'source', '/sɔːrs/', 'B1', 'nguồn; nguồn gốc; nguồn tài liệu; nguồn tin; tìm nguồn cung ứng; thu mua', 'n.', NULL, 'Đồng nghĩa: origin', 'Cụm source of dùng để chỉ nguồn gốc; khi làm động từ có thể dùng cấu trúc source…from….', 'We followed the stream uphill to find its source.', NULL, 'Chúng tôi đi ngược dòng suối lên đồi để tìm nguồn nước của nó.', '{"wordId":"source","ukIpa":"/sɔːs/","usIpa":"/sɔːrs/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A place, person, or thing that something comes from.","vi":"nguồn; nguồn gốc"},{"pos":"n.","en":"A person or document that provides information.","vi":"nguồn tài liệu; nguồn tin"},{"pos":"v.","en":"To find and obtain something from a particular supplier.","vi":"tìm nguồn cung ứng; thu mua"}],"examples":[{"en":"We followed the stream uphill to find its source.","vi":"Chúng tôi đi ngược dòng suối lên đồi để tìm nguồn nước của nó.","audioKind":"ex"},{"en":"Researchers should compare several independent sources before drawing conclusions about the effects of social media.","vi":"Các nhà nghiên cứu nên đối chiếu nhiều nguồn độc lập trước khi đưa ra kết luận về tác động của mạng xã hội.","audioKind":"ex2"}],"collocations":[{"en":"a source of income","vi":"nguồn thu nhập"},{"en":"a reliable source","vi":"nguồn tin cậy"},{"en":"source materials locally","vi":"thu mua nguyên liệu tại địa phương"}],"wordFamily":[],"synonyms":["origin"],"antonyms":[],"tipVi":"Cụm source of dùng để chỉ nguồn gốc; khi làm động từ có thể dùng cấu trúc source…from….","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diagram', 'en-b1-2', 'diagram', '/ˈdaɪəɡræm/', 'B1', 'biểu đồ; sơ đồ; hình vẽ minh họa; minh họa bằng sơ đồ', 'n.', 'diagrammatic (adj.), diagrammatically (adv.)', 'Đồng nghĩa: illustration', 'Tập trung vào sơ đồ cấu trúc hoặc nguyên lý hoạt động, khác biệt với biểu đồ số liệu.', 'The diagram shows how to put the shelves together.', NULL, 'Sơ đồ này hướng dẫn cách lắp ráp các kệ sách lại với nhau.', '{"wordId":"diagram","ukIpa":"/ˈdaɪəɡræm/","usIpa":"/ˈdaɪəɡræm/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a simple drawing showing how something works or is arranged","vi":"biểu đồ; sơ đồ; hình vẽ minh họa"},{"pos":"v.","en":"to explain or represent something using a simple drawing","vi":"minh họa bằng sơ đồ"}],"examples":[{"en":"The diagram shows how to put the shelves together.","vi":"Sơ đồ này hướng dẫn cách lắp ráp các kệ sách lại với nhau.","audioKind":"ex"},{"en":"A clear diagram can help students understand complex biological processes more effectively than a lengthy explanation.","vi":"Một sơ đồ rõ ràng có thể giúp học sinh hiểu các quá trình sinh học phức tạp hiệu quả hơn so với một lời giải thích dài dòng.","audioKind":"ex2"}],"collocations":[{"en":"draw a diagram","vi":"vẽ sơ đồ"},{"en":"a labelled diagram","vi":"sơ đồ có chú thích"},{"en":"a flow diagram","vi":"sơ đồ dòng chảy"}],"wordFamily":["diagrammatic (adj.)","diagrammatically (adv.)"],"synonyms":["illustration"],"antonyms":[],"tipVi":"Tập trung vào sơ đồ cấu trúc hoặc nguyên lý hoạt động, khác biệt với biểu đồ số liệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heading', 'en-b1-2', 'heading', '/ˈhedɪŋ/', 'B1', 'tiêu đề; đề mục; hướng đi (của tàu thủy hoặc máy bay)', 'n.', 'head (n.), subheading (n.)', 'Đồng nghĩa: title', '"heading" thường chỉ tiêu đề của một phần hoặc chương; "headline" thường dùng cho tiêu đề tin tức, báo chí.', 'Write a clear heading at the top of your page.', NULL, 'Hãy viết một tiêu đề rõ ràng ở đầu trang giấy của bạn.', '{"wordId":"heading","ukIpa":"/ˈhedɪŋ/","usIpa":"/ˈhedɪŋ/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"words introducing the subject of a document or section","vi":"tiêu đề; đề mục"},{"pos":"n.","en":"the direction in which a ship or aircraft travels","vi":"hướng đi (của tàu thủy hoặc máy bay)"}],"examples":[{"en":"Write a clear heading at the top of your page.","vi":"Hãy viết một tiêu đề rõ ràng ở đầu trang giấy của bạn.","audioKind":"ex"},{"en":"Clear headings help readers locate relevant information quickly, making lengthy academic reports easier to navigate and understand.","vi":"Các đề mục rõ ràng giúp người đọc nhanh chóng tìm thấy thông tin liên quan, khiến các báo cáo học thuật dài trở nên dễ tra cứu và dễ hiểu hơn.","audioKind":"ex2"}],"collocations":[{"en":"a section heading","vi":"tiêu đề phần; tiêu đề mục"},{"en":"a main heading","vi":"tiêu đề chính"},{"en":"under the heading","vi":"dưới tiêu đề"}],"wordFamily":["head (n.)","subheading (n.)"],"synonyms":["title"],"antonyms":[],"tipVi":"\"heading\" thường chỉ tiêu đề của một phần hoặc chương; \"headline\" thường dùng cho tiêu đề tin tức, báo chí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_2_1', 'en-b1-2', 'Cách dùng “questionnaire” (n.) — bảng câu hỏi; phiếu điều tra', 'complete a questionnaire  ·  design a questionnaire  ·  distribute a questionnaire', 'Từ này có hai chữ n, trọng âm rơi vào âm tiết cuối; "survey" dùng để chỉ cuộc khảo sát chung, còn bảng câu hỏi chỉ là công cụ trong đó.', 'Họ từ (Word Family): question (n.), question (v.), questioner (n.)', '[{"hanzi":"Please complete this short questionnaire before leaving the clinic.","pinyin":"","meaning":"Vui lòng hoàn thành bảng câu hỏi ngắn này trước khi rời phòng khám."},{"hanzi":"Researchers distributed a questionnaire to investigate how commuting time affects workers'' wellbeing and satisfaction with their jobs.","pinyin":"","meaning":"Các nhà nghiên cứu đã phát bảng câu hỏi để khảo sát thời gian đi lại ảnh hưởng thế nào đến hạnh phúc và sự hài lòng trong công việc của người lao động."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_2_2', 'en-b1-2', 'Cách dùng “explanation” (n.) — lời giải thích; sự giải thích', 'clear explanation  ·  give an explanation  ·  explanation for', '"explanation of" thường dùng để giải thích nội dung, còn "explanation for" thường dùng để giải thích nguyên nhân.', 'Họ từ (Word Family): explain (v.), explanatory (adj.), explainable (adj.) | Đồng nghĩa: clarification', '[{"hanzi":"Her simple explanation helped me understand the new game.","pinyin":"","meaning":"Lời giải thích đơn giản của cô ấy đã giúp tôi hiểu trò chơi mới."},{"hanzi":"One possible explanation for declining car ownership is the growing availability of reliable public transport.","pinyin":"","meaning":"Một lý do có thể giải thích cho việc tỷ lệ sở hữu ô tô giảm là sự phổ biến ngày càng tăng của các phương tiện giao thông công cộng đáng tin cậy."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_2_3', 'en-b1-2', 'Cách dùng “certificate” (n.) — chứng chỉ; văn bằng; giấy chứng nhận', 'a birth certificate  ·  a medical certificate  ·  a professional certificate', 'certificate dùng chung cho giấy chứng nhận hoặc chứng chỉ nghề nghiệp, không nhất thiết là bằng cấp đại học.', 'Họ từ (Word Family): certify (v.), certification (n.), certified (adj.)', '[{"hanzi":"Lena proudly showed her swimming certificate to her grandparents.","pinyin":"","meaning":"Lena tự hào khoe chứng chỉ bơi lội của mình với ông bà."},{"hanzi":"A professional certificate can improve employment prospects, but employers also value practical experience.","pinyin":"","meaning":"Chứng chỉ chuyên môn có thể cải thiện cơ hội việc làm, nhưng các nhà tuyển dụng cũng đánh giá cao kinh nghiệm thực tế."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_2_4', 'en-b1-2', 'Cách dùng “heading” (n.) — tiêu đề; đề mục', 'a section heading  ·  a main heading  ·  under the heading', '"heading" thường chỉ tiêu đề của một phần hoặc chương; "headline" thường dùng cho tiêu đề tin tức, báo chí.', 'Họ từ (Word Family): head (n.), subheading (n.) | Đồng nghĩa: title', '[{"hanzi":"Write a clear heading at the top of your page.","pinyin":"","meaning":"Hãy viết một tiêu đề rõ ràng ở đầu trang giấy của bạn."},{"hanzi":"Clear headings help readers locate relevant information quickly, making lengthy academic reports easier to navigate and understand.","pinyin":"","meaning":"Các đề mục rõ ràng giúp người đọc nhanh chóng tìm thấy thông tin liên quan, khiến các báo cáo học thuật dài trở nên dễ tra cứu và dễ hiểu hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
