INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_2_1_4', 'ten_b1_2_1', 'dorm', 'My dorm is just five minutes from the library.', 'My dorm is just five minutes from the library.', '/dɔːrm/', 'Ký túc xá của tôi chỉ cách thư viện có năm phút đi bộ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_2_1_5', 'ten_b1_2_1', 'journal', 'I keep a journal beside my bed every night.', 'I keep a journal beside my bed every night.', '/ˈdʒɝːnəl/', 'Tôi giữ một cuốn nhật ký cạnh giường ngủ mỗi tối.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_2_1_6', 'ten_b1_2_1', 'accent', 'Her accent reminds me of my neighbours back home.', 'Her accent reminds me of my neighbours back home.', '/ˈæksent/', 'Giọng điệu của cô ấy làm tôi nhớ đến những người hàng xóm ở quê nhà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_2_1_7', 'ten_b1_2_1', 'phrase', 'I learned a useful phrase in my English class today.', 'I learned a useful phrase in my English class today.', '/freɪz/', 'Hôm nay tôi đã học được một cụm từ hữu ích trong lớp tiếng Anh.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_2_1_8', 'ten_b1_2_1', 'minus', 'Ten minus three leaves enough apples for everyone.', 'Ten minus three leaves enough apples for everyone.', '/ˈmaɪnəs/', 'Mười trừ đi ba là còn đủ táo cho tất cả mọi người.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_2_1_1', 'en-b1-2', 'ten_b1_2_1', 'listening', 'listening', 'I got a good grade on my science project.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đạt điểm tốt trong dự án khoa học của mình.","Lena tự hào khoe chứng chỉ bơi lội của mình với ông bà.","Ký túc xá của tôi chỉ cách thư viện có năm phút đi bộ.","Mười trừ đi ba là còn đủ táo cho tất cả mọi người."]'::jsonb, 0, 'I got a good grade on my science project. → Tôi đạt điểm tốt trong dự án khoa học của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_2_1_2', 'en-b1-2', 'ten_b1_2_1', 'listening', 'listening', 'I bought some stationery for my new evening class.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giọng điệu của cô ấy làm tôi nhớ đến những người hàng xóm ở quê nhà.","Lena tự hào khoe chứng chỉ bơi lội của mình với ông bà.","Chị tôi đã khuyến khích tôi tham gia câu lạc bộ bơi lội.","Tôi đã mua vài món văn phòng phẩm cho lớp học buổi tối mới của mình."]'::jsonb, 3, 'I bought some stationery for my new evening class. → Tôi đã mua vài món văn phòng phẩm cho lớp học buổi tối mới của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_2_1_3', 'en-b1-2', 'ten_b1_2_1', 'listening', 'listening', 'Could you translate this recipe into English for me?', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chị tôi đã khuyến khích tôi tham gia câu lạc bộ bơi lội.","Tôi giữ một cuốn nhật ký cạnh giường ngủ mỗi tối.","Bạn có thể dịch giúp tôi công thức nấu ăn này sang tiếng Anh được không?","Giọng điệu của cô ấy làm tôi nhớ đến những người hàng xóm ở quê nhà."]'::jsonb, 2, 'Could you translate this recipe into English for me? → Bạn có thể dịch giúp tôi công thức nấu ăn này sang tiếng Anh được không?', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_2_2', 'en-b1-2', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_2_2_1', 'ten_b1_2_2', 'grade', 'Teachers should grade assignments consistently so that students understand how their performance is assessed across different subjects.', 'Teachers should grade assignments consistently so that students understand how their performance is assessed across different subjects.', '/ɡreɪd/', 'Giáo viên nên chấm điểm các bài tập một cách nhất quán để học sinh hiểu cách năng lực của các em được đánh giá qua các môn học khác nhau.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_2_2_2', 'ten_b1_2_2', 'stationery', 'Providing basic stationery can help disadvantaged students participate more fully in classroom activities and complete assignments.', 'Providing basic stationery can help disadvantaged students participate more fully in classroom activities and complete assignments.', '/ˈsteɪʃəneri/', 'Việc cung cấp văn phòng phẩm cơ bản có thể giúp học sinh có hoàn cảnh khó khăn tham gia đầy đủ hơn vào các hoạt động trên lớp và hoàn thành bài tập.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_2_2_3', 'ten_b1_2_2', 'translate', 'Governments must translate environmental commitments into practical policies that encourage businesses to reduce emissions.', 'Governments must translate environmental commitments into practical policies that encourage businesses to reduce emissions.', '/trænzˈleɪt/', 'Chính phủ phải chuyển hóa các cam kết bảo vệ môi trường thành các chính sách thiết thực nhằm khuyến khích doanh nghiệp cắt giảm khí thải.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_2_2_4', 'ten_b1_2_2', 'dorm', 'Living in a dorm can help first-year students develop social skills and adjust to university life.', 'Living in a dorm can help first-year students develop social skills and adjust to university life.', '/dɔːrm/', 'Sống trong ký túc xá có thể giúp sinh viên năm nhất phát triển các kỹ năng xã hội và thích nghi với đời sống đại học.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_2_2_5', 'ten_b1_2_2', 'journal', 'Researchers publish their findings in academic journals so that other experts can evaluate the evidence.', 'Researchers publish their findings in academic journals so that other experts can evaluate the evidence.', '/ˈdʒɝːnəl/', 'Các nhà nghiên cứu công bố phát hiện của họ trên các tạp chí học thuật để các chuyên gia khác có thể đánh giá bằng chứng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_2_2_6', 'ten_b1_2_2', 'accent', 'Teachers should value different accents while helping learners develop clear pronunciation for effective international communication.', 'Teachers should value different accents while helping learners develop clear pronunciation for effective international communication.', '/ˈæksent/', 'Giáo viên nên coi trọng các giọng điệu khác nhau đồng thời giúp người học phát triển phát âm rõ ràng để giao tiếp quốc tế hiệu quả.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_2_2_1', 'en-b1-2', 'ten_b1_2_2', 'listening', 'listening', 'Teachers should grade assignments consistently so that students understand how their performance is assessed across different subjects.', NULL, 'Trong câu vừa nghe, từ “grade” mang nghĩa nào sau đây?', '["say rượu","dần dần; từ từ","điểm số; cấp độ chất lượng","bột nhào (hỗn hợp bột và chất lỏng dùng để nướng)"]'::jsonb, 2, '“grade” (/ɡreɪd/): điểm số; cấp độ chất lượng. Câu đầy đủ: Teachers should grade assignments consistently so that students understand how their performance is assessed across different subjects.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_2_2_2', 'en-b1-2', 'ten_b1_2_2', 'listening', 'listening', 'Providing basic stationery can help disadvantaged students participate more fully in classroom activities and complete assignments.', NULL, 'Trong câu vừa nghe, từ “stationery” mang nghĩa nào sau đây?', '["xóa; loại bỏ","bằng nhau; bình đẳng","văn phòng phẩm","sự sắp xếp; sự chuẩn bị"]'::jsonb, 2, '“stationery” (/ˈsteɪʃəneri/): văn phòng phẩm. Câu đầy đủ: Providing basic stationery can help disadvantaged students participate more fully in classroom activities and complete assignments.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
