INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_2_2', 'en-b1-2', NULL, 'comprehensive_test', 'listening', 'I bought some stationery for my new evening class.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Học kỳ này tôi đang tham gia một lớp học nhiếp ảnh ở trường cao đẳng.","Tôi đạt điểm tốt trong dự án khoa học của mình.","Tôi đã mua vài món văn phòng phẩm cho lớp học buổi tối mới của mình.","Vui lòng gửi các hướng dẫn bằng văn bản để tôi có thể làm theo."]'::jsonb, 2, 'I bought some stationery for my new evening class. → Tôi đã mua vài món văn phòng phẩm cho lớp học buổi tối mới của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_2_3', 'en-b1-2', NULL, 'comprehensive_test', 'listening', 'translate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tình trạng; trạng thái","dịch; dịch thuật","mức tối thiểu; lượng tối thiểu","miếng bọt biển; mút"]'::jsonb, 1, 'translate (/trænzˈleɪt/) → dịch; dịch thuật; chuyển hóa; chuyển đổi', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_2_4', 'en-b1-2', NULL, 'comprehensive_test', 'listening', 'My dorm is just five minutes from the library.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sơ đồ này hướng dẫn cách lắp ráp các kệ sách lại với nhau.","Tôi đã mua vài món văn phòng phẩm cho lớp học buổi tối mới của mình.","Ký túc xá của tôi chỉ cách thư viện có năm phút đi bộ.","Tôi giữ một cuốn nhật ký cạnh giường ngủ mỗi tối."]'::jsonb, 2, 'My dorm is just five minutes from the library. → Ký túc xá của tôi chỉ cách thư viện có năm phút đi bộ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_2_5', 'en-b1-2', NULL, 'comprehensive_test', 'listening', 'journal', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tạp chí chuyên khảo, tạp chí học thuật","tàu vũ trụ","nhận ra; nhận diện","bóng; sáng lấp lánh"]'::jsonb, 0, 'journal (/ˈdʒɝːnəl/) → tạp chí chuyên khảo, tạp chí học thuật; nhật ký, sổ tay ghi chép', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_2_6', 'en-b1-2', NULL, 'comprehensive_test', 'listening', 'Her accent reminds me of my neighbours back home.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Trình độ bơi lội của bạn đã tiến bộ thật rồi.","Bạn có thể dịch giúp tôi công thức nấu ăn này sang tiếng Anh được không?","Giọng điệu của cô ấy làm tôi nhớ đến những người hàng xóm ở quê nhà.","Hãy viết một tiêu đề rõ ràng ở đầu trang giấy của bạn."]'::jsonb, 2, 'Her accent reminds me of my neighbours back home. → Giọng điệu của cô ấy làm tôi nhớ đến những người hàng xóm ở quê nhà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_2_7', 'en-b1-2', NULL, 'comprehensive_test', 'listening', 'phrase', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["người trông trẻ; bảo mẫu tạm thời","cụm từ; thành ngữ; cách nói","hắt hơi; nhảy mũi","nhấn; ấn"]'::jsonb, 1, 'phrase (/freɪz/) → cụm từ; thành ngữ; cách nói; diễn đạt; chọn lời văn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_2_8', 'en-b1-2', NULL, 'comprehensive_test', 'listening', 'Ten minus three leaves enough apples for everyone.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ký túc xá của tôi chỉ cách thư viện có năm phút đi bộ.","Khóa học đã mang lại cho tôi kinh nghiệm thực tế trong việc sửa chữa xe đạp.","Chúng tôi đi ngược dòng suối lên đồi để tìm nguồn nước của nó.","Mười trừ đi ba là còn đủ táo cho tất cả mọi người."]'::jsonb, 3, 'Ten minus three leaves enough apples for everyone. → Mười trừ đi ba là còn đủ táo cho tất cả mọi người.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
