INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_2_18', 'en-b1-2', NULL, 'comprehensive_test', 'reading', NULL, 'Teachers should grade assignments consistently so that students understand how their performance is assessed across different subjects.', 'Dựa vào câu trên, từ “grade” có nghĩa phù hợp nhất là gì?', '["điểm số; cấp độ chất lượng","huy hiệu; thẻ tên; biểu tượng","hải quân","nước hoa"]'::jsonb, 0, 'grade: điểm số; cấp độ chất lượng; khối lớp (học đường); chấm điểm; phân loại. Dịch cả câu: Giáo viên nên chấm điểm các bài tập một cách nhất quán để học sinh hiểu cách năng lực của các em được đánh giá qua các môn học khác nhau.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_2_19', 'en-b1-2', NULL, 'comprehensive_test', 'reading', NULL, 'Providing basic stationery can help disadvantaged students participate more fully in classroom activities and complete assignments.', 'Dựa vào câu trên, từ “stationery” có nghĩa phù hợp nhất là gì?', '["chia; phân chia; tách ra","lễ hội hóa trang; ngày hội","nỗi buồn; sự đau buồn (cảm giác không vui, đặc biệt sau khi mất mát hoặc thất vọng)","văn phòng phẩm"]'::jsonb, 3, 'stationery: văn phòng phẩm. Dịch cả câu: Việc cung cấp văn phòng phẩm cơ bản có thể giúp học sinh có hoàn cảnh khó khăn tham gia đầy đủ hơn vào các hoạt động trên lớp và hoàn thành bài tập.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_2_20', 'en-b1-2', NULL, 'comprehensive_test', 'reading', NULL, 'Governments must translate environmental commitments into practical policies that encourage businesses to reduce emissions.', 'Dựa vào câu trên, từ “translate” có nghĩa phù hợp nhất là gì?', '["đồ trang trí","khiếm thính; điếc","dịch; dịch thuật","niềm đam mê; sự say mê"]'::jsonb, 2, 'translate: dịch; dịch thuật; chuyển hóa; chuyển đổi. Dịch cả câu: Chính phủ phải chuyển hóa các cam kết bảo vệ môi trường thành các chính sách thiết thực nhằm khuyến khích doanh nghiệp cắt giảm khí thải.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_2_21', 'en-b1-2', NULL, 'comprehensive_test', 'reading', NULL, 'Living in a dorm can help first-year students develop social skills and adjust to university life.', 'Dựa vào câu trên, từ “dorm” có nghĩa phù hợp nhất là gì?', '["ký túc xá; phòng ngủ tập thể","lực; sức mạnh vật lý","tự hỏi; băn khoăn","người hầu; người ở"]'::jsonb, 0, 'dorm: ký túc xá; phòng ngủ tập thể. Dịch cả câu: Sống trong ký túc xá có thể giúp sinh viên năm nhất phát triển các kỹ năng xã hội và thích nghi với đời sống đại học.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
