INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-3', 'en', 'Bài 3: Giáo dục & Trường học (3) - CEFR B1', 'CEFR B1', 'B1 · Giáo dục', '21 từ vựng Tiếng Anh CEFR B1 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3003, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cheat', 'en-b1-3', 'cheat', '/tʃiːt/', 'B1', 'gian lận; chơi gian; lừa dối; lừa gạt; kẻ gian lận; kẻ lừa đảo', 'v.', 'cheating (n.), cheater (n.)', NULL, 'Cụm từ cheat someone out of something dùng để chỉ hành động lừa lấy đi tài sản của người khác.', 'My cousin cheated by hiding cards under the table.', NULL, 'Anh họ tôi đã gian lận bằng cách giấu những lá bài dưới gầm bàn.', '{"wordId":"cheat","ukIpa":"/tʃiːt/","usIpa":"/tʃiːt/","cefr":"B1","topic":"education","senses":[{"pos":"v.","en":"To break rules dishonestly to gain an unfair advantage.","vi":"gian lận; chơi gian"},{"pos":"v.","en":"To deceive someone to obtain something unfairly.","vi":"lừa dối; lừa gạt"},{"pos":"n.","en":"A person who acts dishonestly to gain an advantage.","vi":"kẻ gian lận; kẻ lừa đảo"}],"examples":[{"en":"My cousin cheated by hiding cards under the table.","vi":"Anh họ tôi đã gian lận bằng cách giấu những lá bài dưới gầm bàn.","audioKind":"ex"},{"en":"Schools can discourage students from cheating by designing assessments that reward original thinking rather than memorisation.","vi":"Nhà trường có thể ngăn chặn học sinh gian lận bằng cách thiết kế các bài kiểm tra đánh giá cao tư duy độc lập thay vì học vẹt.","audioKind":"ex2"}],"collocations":[{"en":"cheat in an exam","vi":"gian lận trong kỳ thi"},{"en":"cheat at cards","vi":"gian lận khi chơi bài"},{"en":"cheat someone out of money","vi":"lừa gạt tiền của ai đó"}],"wordFamily":["cheating (n.)","cheater (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ cheat someone out of something dùng để chỉ hành động lừa lấy đi tài sản của người khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_librarian', 'en-b1-3', 'librarian', '/laɪˈbreriən/', 'B1', 'thủ thư; nhân viên thư viện', 'n.', 'library (n.), librarianship (n.)', NULL, 'library chỉ thư viện; librarian chỉ nhân viên làm việc ở đó.', 'The librarian helped me find a book about birds.', NULL, 'Người thủ thư đã giúp tôi tìm một cuốn sách viết về các loài chim.', '{"wordId":"librarian","ukIpa":"/laɪˈbreəriən/","usIpa":"/laɪˈbreriən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A person who manages library resources and helps library users.","vi":"thủ thư; nhân viên thư viện"}],"examples":[{"en":"The librarian helped me find a book about birds.","vi":"Người thủ thư đã giúp tôi tìm một cuốn sách viết về các loài chim.","audioKind":"ex"},{"en":"School librarians support independent learning by teaching students how to locate reliable sources and evaluate information.","vi":"Các nhân viên thư viện trường học hỗ trợ việc tự học bằng cách hướng dẫn học sinh cách tìm kiếm nguồn tài liệu đáng tin cậy và đánh giá thông tin.","audioKind":"ex2"}],"collocations":[{"en":"school librarian","vi":"thủ thư trường học"},{"en":"chief librarian","vi":"giám đốc thư viện; thủ thư trưởng"},{"en":"ask a librarian","vi":"hỏi ý kiến thủ thư"}],"wordFamily":["library (n.)","librarianship (n.)"],"synonyms":[],"antonyms":[],"tipVi":"library chỉ thư viện; librarian chỉ nhân viên làm việc ở đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_secondly', 'en-b1-3', 'secondly', '/ˈsekəndli/', 'B1', 'thứ hai là; thứ nhì; mặt khác', 'adv.', 'second (num.)', 'Đồng nghĩa: second', 'Dùng để giới thiệu ý thứ hai trong bài luận hoặc tranh luận, khi đứng đầu câu thường có dấu phẩy đi kèm.', 'Firstly, the flat is affordable; secondly, it has a balcony.', NULL, 'Thứ nhất, căn hộ có giá cả phải chăng; thứ hai, nó có một ban công.', '{"wordId":"secondly","ukIpa":"/ˈsekəndli/","usIpa":"/ˈsekəndli/","cefr":"B1","topic":"education","senses":[{"pos":"adv.","en":"Used to introduce the second point in a list or argument.","vi":"thứ hai là; thứ nhì; mặt khác"}],"examples":[{"en":"Firstly, the flat is affordable; secondly, it has a balcony.","vi":"Thứ nhất, căn hộ có giá cả phải chăng; thứ hai, nó có một ban công.","audioKind":"ex"},{"en":"Secondly, expanding public transport could reduce traffic congestion and improve access to employment opportunities.","vi":"Thứ hai, việc mở rộng giao thông công cộng có thể làm giảm tình trạng tắc nghẽn giao thông và cải thiện khả năng tiếp cận cơ hội việc làm.","audioKind":"ex2"}],"collocations":[{"en":"firstly and secondly","vi":"thứ nhất và thứ hai"},{"en":"secondly, consider","vi":"thứ hai là, hãy cân nhắc"}],"wordFamily":["second (num.)"],"synonyms":["second"],"antonyms":[],"tipVi":"Dùng để giới thiệu ý thứ hai trong bài luận hoặc tranh luận, khi đứng đầu câu thường có dấu phẩy đi kèm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_improvement', 'en-b1-3', 'improvement', '/ɪmˈpruːvmənt/', 'B1', 'sự cải thiện; sự tiến bộ; điểm cải tiến; điểm tốt hơn', 'n.', 'improve (v.), improved (adj.)', 'Đồng nghĩa: progress, betterment · Trái nghĩa: deterioration', 'Sự cải thiện trong lĩnh vực nào dùng in; tốt hơn cái cũ dùng an improvement on.', 'Your latest drawing shows a real improvement in shading.', NULL, 'Bức vẽ mới nhất của bạn cho thấy sự tiến bộ rõ rệt trong kỹ thuật đánh bóng.', '{"wordId":"improvement","ukIpa":"/ɪmˈpruːvmənt/","usIpa":"/ɪmˈpruːvmənt/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"The process or result of becoming better.","vi":"sự cải thiện; sự tiến bộ"},{"pos":"n.","en":"A change that makes something better.","vi":"điểm cải tiến; điểm tốt hơn"}],"examples":[{"en":"Your latest drawing shows a real improvement in shading.","vi":"Bức vẽ mới nhất của bạn cho thấy sự tiến bộ rõ rệt trong kỹ thuật đánh bóng.","audioKind":"ex"},{"en":"Investment in public transport can bring significant improvements in air quality and reduce travel times for urban residents.","vi":"Đầu tư vào giao thông công cộng có thể mang lại những cải thiện đáng kể về chất lượng không khí và rút ngắn thời gian di chuyển cho cư dân đô thị.","audioKind":"ex2"}],"collocations":[{"en":"significant improvement","vi":"sự cải thiện đáng kể"},{"en":"room for improvement","vi":"dư địa để cải thiện"},{"en":"an improvement on","vi":"một bước tiến so với"},{"en":"make improvements","vi":"thực hiện cải tiến"}],"wordFamily":["improve (v.)","improved (adj.)"],"synonyms":["progress","betterment"],"antonyms":["deterioration"],"tipVi":"Sự cải thiện trong lĩnh vực nào dùng in; tốt hơn cái cũ dùng an improvement on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_define', 'en-b1-3', 'define', '/dɪˈfaɪn/', 'B1', 'định nghĩa; giải thích nghĩa; xác định rõ; vạch rõ; làm nên đặc trưng; định hình', 'v.', 'definition (n.), definable (adj.), defining (adj.), undefined (adj.)', 'Đồng nghĩa: explain, specify', 'define A as B có nghĩa là "định nghĩa A là B".', 'Can you define this word without using a dictionary?', NULL, 'Bạn có thể giải nghĩa từ này mà không cần dùng từ điển không?', '{"wordId":"define","ukIpa":"/dɪˈfaɪn/","usIpa":"/dɪˈfaɪn/","cefr":"B1","topic":"education","senses":[{"pos":"v.","en":"To state exactly what a word or idea means.","vi":"định nghĩa; giải thích nghĩa"},{"pos":"v.","en":"To establish the limits, duties, or nature of something clearly.","vi":"xác định rõ; vạch rõ"},{"pos":"v.","en":"To be the quality that makes someone or something distinctive.","vi":"làm nên đặc trưng; định hình"}],"examples":[{"en":"Can you define this word without using a dictionary?","vi":"Bạn có thể giải nghĩa từ này mà không cần dùng từ điển không?","audioKind":"ex"},{"en":"Governments should clearly define their environmental objectives before introducing policies that affect businesses and local communities.","vi":"Chính phủ nên xác định rõ các mục tiêu môi trường của mình trước khi ban hành các chính sách tác động đến doanh nghiệp và cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"define a term","vi":"định nghĩa một thuật ngữ"},{"en":"clearly define","vi":"xác định rõ ràng"},{"en":"define the scope","vi":"xác định phạm vi"},{"en":"define as","vi":"định nghĩa là"}],"wordFamily":["definition (n.)","definable (adj.)","defining (adj.)","undefined (adj.)"],"synonyms":["explain","specify"],"antonyms":[],"tipVi":"define A as B có nghĩa là \"định nghĩa A là B\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_handout', 'en-b1-3', 'handout', '/ˈhændaʊt/', 'B1', 'tài liệu phát tay; bài giảng in sẵn; tiền cứu trợ; vật phẩm bố thí', 'n.', NULL, NULL, 'handout là danh từ; trong khi hand out là cụm động từ mang nghĩa phân phát.', 'Our teacher gave us a handout about healthy eating.', NULL, 'Giáo viên của chúng tôi đã phát một tài liệu về chế độ ăn uống lành mạnh.', '{"wordId":"handout","ukIpa":"/ˈhændaʊt/","usIpa":"/ˈhændaʊt/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A document given to people attending a lesson or meeting.","vi":"tài liệu phát tay; bài giảng in sẵn"},{"pos":"n.","en":"Money or goods given free to someone in need.","vi":"tiền cứu trợ; vật phẩm bố thí"}],"examples":[{"en":"Our teacher gave us a handout about healthy eating.","vi":"Giáo viên của chúng tôi đã phát một tài liệu về chế độ ăn uống lành mạnh.","audioKind":"ex"},{"en":"A well-designed handout can help students review key concepts independently after a lecture has finished.","vi":"Một bản tài liệu phát tay được thiết kế tốt có thể giúp học sinh tự ôn lại các khái niệm cốt lõi sau khi buổi giảng kết thúc.","audioKind":"ex2"}],"collocations":[{"en":"course handout","vi":"tài liệu khóa học"},{"en":"distribute handouts","vi":"phát tài liệu"},{"en":"government handouts","vi":"khoản cứu trợ từ chính phủ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"handout là danh từ; trong khi hand out là cụm động từ mang nghĩa phân phát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_revise', 'en-b1-3', 'revise', '/rɪˈvaɪz/', 'B1', 'ôn tập; ôn thi; sửa đổi; chỉnh sửa', 'v.', 'revision (n.), revised (adj.)', NULL, 'Nghĩa ôn tập chủ yếu dùng trong tiếng Anh-Anh; tiếng Anh-Mỹ thường dùng review.', 'I need to revise for my biology exam tonight.', NULL, 'Tối nay tôi cần phải ôn bài để chuẩn bị cho kỳ thi sinh học.', '{"wordId":"revise","ukIpa":"/rɪˈvaɪz/","usIpa":"/rɪˈvaɪz/","cefr":"B1","topic":"education","senses":[{"pos":"v.","en":"To study material again in preparation for an examination.","vi":"ôn tập; ôn thi"},{"pos":"v.","en":"To change something to correct or improve it.","vi":"sửa đổi; chỉnh sửa"}],"examples":[{"en":"I need to revise for my biology exam tonight.","vi":"Tối nay tôi cần phải ôn bài để chuẩn bị cho kỳ thi sinh học.","audioKind":"ex"},{"en":"Governments should revise outdated housing policies to ensure that affordable homes remain accessible to young families.","vi":"Chính phủ nên sửa đổi các chính sách nhà ở đã lỗi thời để đảm bảo các gia đình trẻ vẫn có thể tiếp cận nhà ở vừa túi tiền.","audioKind":"ex2"}],"collocations":[{"en":"revise for an exam","vi":"ôn thi"},{"en":"revise a draft","vi":"sửa đổi bản thảo"},{"en":"revise an estimate","vi":"điều chỉnh bản dự toán"},{"en":"revise a policy","vi":"sửa đổi chính sách"}],"wordFamily":["revision (n.)","revised (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa ôn tập chủ yếu dùng trong tiếng Anh-Anh; tiếng Anh-Mỹ thường dùng review.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_graduation', 'en-b1-3', 'graduation', '/ˌɡrædʒuˈeɪʃən/', 'B1', 'sự tốt nghiệp; lễ tốt nghiệp', 'n.', 'graduate (v.), graduate (n.)', NULL, 'Khi nói tốt nghiệp từ trường nào, dùng động từ graduate from.', 'My sister wore a blue gown at her graduation.', NULL, 'Chị tôi mặc một chiếc áo cử nhân màu xanh trong lễ tốt nghiệp của mình.', '{"wordId":"graduation","ukIpa":"/ˌɡrædʒuˈeɪʃən/","usIpa":"/ˌɡrædʒuˈeɪʃən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"Completing a course of study, or the ceremony celebrating this.","vi":"sự tốt nghiệp; lễ tốt nghiệp"}],"examples":[{"en":"My sister wore a blue gown at her graduation.","vi":"Chị tôi mặc một chiếc áo cử nhân màu xanh trong lễ tốt nghiệp của mình.","audioKind":"ex"},{"en":"Universities should provide career guidance before graduation to help students make a successful transition into employment.","vi":"Các trường đại học nên cung cấp định hướng nghề nghiệp trước khi tốt nghiệp để giúp sinh viên chuyển đổi suôn sẻ sang môi trường làm việc.","audioKind":"ex2"}],"collocations":[{"en":"graduation ceremony","vi":"lễ tốt nghiệp"},{"en":"after graduation","vi":"sau khi tốt nghiệp"},{"en":"graduation gown","vi":"áo cử nhân"}],"wordFamily":["graduate (v.)","graduate (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói tốt nghiệp từ trường nào, dùng động từ graduate from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_educate', 'en-b1-3', 'educate', '/ˈedʒukeɪt/', 'B1', 'giáo dục; đào tạo; cung cấp thông tin; nâng cao nhận thức', 'v.', 'education (n.), educational (adj.), educated (adj.), educator (n.)', 'Đồng nghĩa: teach, instruct', 'educate nhấn mạnh việc giáo dục và nuôi dưỡng; teach cũng có thể đi thẳng với tên môn học.', 'These colourful picture books educate children while keeping them entertained.', NULL, 'Những cuốn sách tranh đầy màu sắc này vừa mang tính giải trí vừa giáo dục trẻ em.', '{"wordId":"educate","ukIpa":"/ˈedʒukeɪt/","usIpa":"/ˈedʒukeɪt/","cefr":"B1","topic":"education","senses":[{"pos":"v.","en":"To teach someone and develop their knowledge or skills.","vi":"giáo dục; đào tạo"},{"pos":"v.","en":"To give people information about a particular subject.","vi":"cung cấp thông tin; nâng cao nhận thức"}],"examples":[{"en":"These colourful picture books educate children while keeping them entertained.","vi":"Những cuốn sách tranh đầy màu sắc này vừa mang tính giải trí vừa giáo dục trẻ em.","audioKind":"ex"},{"en":"Public health campaigns should educate people about nutrition rather than simply encourage them to lose weight.","vi":"Các chiến dịch y tế công cộng nên phổ biến kiến thức dinh dưỡng cho người dân thay vì chỉ đơn thuần khuyến khích họ giảm cân.","audioKind":"ex2"}],"collocations":[{"en":"educate children","vi":"giáo dục trẻ em"},{"en":"educate people about","vi":"giáo dục mọi người về"},{"en":"educate the public","vi":"giáo dục công chúng"}],"wordFamily":["education (n.)","educational (adj.)","educated (adj.)","educator (n.)"],"synonyms":["teach","instruct"],"antonyms":[],"tipVi":"educate nhấn mạnh việc giáo dục và nuôi dưỡng; teach cũng có thể đi thẳng với tên môn học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tutor', 'en-b1-3', 'tutor', '/ˈtuːtər/', 'B1', 'gia sư; người hướng dẫn riêng; dạy kèm; kèm cặp', 'n.', 'tutoring (n.), tutorial (n.)', NULL, 'tutor nhấn mạnh việc dạy kèm cá nhân hoặc nhóm nhỏ, không nhất thiết là giảng viên đại học.', 'My tutor helped me understand fractions using paper circles.', NULL, 'Gia sư của tôi đã giúp tôi hiểu về các phân số bằng cách dùng các vòng tròn bằng giấy.', '{"wordId":"tutor","ukIpa":"/ˈtjuːtə/","usIpa":"/ˈtuːtər/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a teacher who guides individuals or small groups","vi":"gia sư; người hướng dẫn riêng"},{"pos":"v.","en":"to teach someone individually or in a small group","vi":"dạy kèm; kèm cặp"}],"examples":[{"en":"My tutor helped me understand fractions using paper circles.","vi":"Gia sư của tôi đã giúp tôi hiểu về các phân số bằng cách dùng các vòng tròn bằng giấy.","audioKind":"ex"},{"en":"A personal tutor can help students develop effective study habits and address specific learning difficulties.","vi":"Một giáo viên hướng dẫn riêng có thể giúp học sinh xây dựng thói quen học tập hiệu quả và giải quyết các khó khăn học tập cụ thể.","audioKind":"ex2"}],"collocations":[{"en":"private tutor","vi":"gia sư riêng"},{"en":"personal tutor","vi":"giáo viên hướng dẫn cá nhân"},{"en":"tutor someone in maths","vi":"dạy kèm môn toán cho ai đó"}],"wordFamily":["tutoring (n.)","tutorial (n.)"],"synonyms":[],"antonyms":[],"tipVi":"tutor nhấn mạnh việc dạy kèm cá nhân hoặc nhóm nhỏ, không nhất thiết là giảng viên đại học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_headmaster', 'en-b1-3', 'headmaster', '/ˌhedˈmæstər/', 'B1', 'hiệu trưởng nam; nam hiệu trưởng', 'n.', 'headmistress (n.), headship (n.)', NULL, 'Chỉ phái nam; từ headteacher trong tiếng Anh-Anh dùng chung cho cả hai giới, còn tiếng Anh-Mỹ thường dùng principal.', 'The headmaster welcomed new pupils at the school gate.', NULL, 'Nam hiệu trưởng chào đón các học sinh mới ở cổng trường.', '{"wordId":"headmaster","ukIpa":"/ˌhedˈmɑːstə/","usIpa":"/ˌhedˈmæstər/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A man who is in charge of a school.","vi":"hiệu trưởng nam; nam hiệu trưởng"}],"examples":[{"en":"The headmaster welcomed new pupils at the school gate.","vi":"Nam hiệu trưởng chào đón các học sinh mới ở cổng trường.","audioKind":"ex"},{"en":"The headmaster introduced a mentoring programme to help younger pupils develop confidence and settle into school life.","vi":"Nam hiệu trưởng đã giới thiệu một chương trình kèm cặp nhằm giúp các học sinh nhỏ tuổi xây dựng sự tự tin và hòa nhập với đời sống học đường.","audioKind":"ex2"}],"collocations":[{"en":"school headmaster","vi":"hiệu trưởng nhà trường"},{"en":"deputy headmaster","vi":"phó hiệu trưởng nam"},{"en":"headmaster''s office","vi":"phòng làm việc của hiệu trưởng"}],"wordFamily":["headmistress (n.)","headship (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ phái nam; từ headteacher trong tiếng Anh-Anh dùng chung cho cả hai giới, còn tiếng Anh-Mỹ thường dùng principal.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_multiplication', 'en-b1-3', 'multiplication', '/ˌmʌltəplɪˈkeɪʃən/', 'B1', 'phép nhân (toán học); sự nhân lên; sự sinh sôi; sự gia tăng nhanh chóng', 'n.', 'multiply (v.), multiplier (n.), multiple (adj.)', 'Trái nghĩa: division', 'Phép nhân dùng multiplication; nhân với có thể dùng multiplied by.', 'We practised multiplication by arranging buttons in equal rows.', NULL, 'Chúng tôi thực hành phép nhân bằng cách sắp xếp các nút áo thành các hàng đều nhau.', '{"wordId":"multiplication","ukIpa":"/ˌmʌltɪplɪˈkeɪʃən/","usIpa":"/ˌmʌltəplɪˈkeɪʃən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"Finding a total by adding equal groups together.","vi":"phép nhân (toán học)"},{"pos":"n.","en":"An increase in quantity, often through repeated reproduction.","vi":"sự nhân lên; sự sinh sôi; sự gia tăng nhanh chóng"}],"examples":[{"en":"We practised multiplication by arranging buttons in equal rows.","vi":"Chúng tôi thực hành phép nhân bằng cách sắp xếp các nút áo thành các hàng đều nhau.","audioKind":"ex"},{"en":"A strong understanding of multiplication helps children develop the mathematical skills needed for science and financial literacy.","vi":"Sự thấu hiểu vững chắc về phép nhân giúp trẻ em phát triển các kỹ năng toán học cần thiết cho khoa học và kiến thức tài chính.","audioKind":"ex2"}],"collocations":[{"en":"multiplication table","vi":"bảng cửu chương"},{"en":"multiplication sign","vi":"dấu nhân"},{"en":"rapid multiplication","vi":"sự nhân lên nhanh chóng"}],"wordFamily":["multiply (v.)","multiplier (n.)","multiple (adj.)"],"synonyms":[],"antonyms":["division"],"tipVi":"Phép nhân dùng multiplication; nhân với có thể dùng multiplied by.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lecture', 'en-b1-3', 'lecture', '/ˈlektʃɚ/', 'B1', 'bài giảng; buổi thuyết trình; giảng bài; thuyết trình; la mắng; khiển trách', 'n.', 'lecturer (n.)', NULL, 'lecture on dùng để chỉ việc giảng dạy về một chủ đề; lecture someone có thể mang nghĩa là khiển trách, la mắng.', 'I stayed after the lecture to ask a question.', NULL, 'Tôi ở lại sau buổi giảng để đặt một câu hỏi.', '{"wordId":"lecture","ukIpa":"/ˈlektʃə/","usIpa":"/ˈlektʃɚ/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"an educational talk given to an audience, especially university students","vi":"bài giảng; buổi thuyết trình"},{"pos":"v.","en":"to give an educational talk to an audience","vi":"giảng bài; thuyết trình"},{"pos":"v.","en":"to criticize someone at length about their behaviour","vi":"la mắng; khiển trách"}],"examples":[{"en":"I stayed after the lecture to ask a question.","vi":"Tôi ở lại sau buổi giảng để đặt một câu hỏi.","audioKind":"ex"},{"en":"Universities should combine traditional lectures with practical activities that encourage students to apply their knowledge.","vi":"Các trường đại học nên kết hợp các bài giảng truyền thống với các hoạt động thực tế khuyến khích sinh viên vận dụng kiến thức.","audioKind":"ex2"}],"collocations":[{"en":"attend a lecture","vi":"dự thính bài giảng"},{"en":"give a lecture","vi":"thuyết trình; giảng bài"},{"en":"lecture on biology","vi":"giảng dạy môn sinh học"},{"en":"lecture someone about","vi":"la mắng ai về việc gì"}],"wordFamily":["lecturer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"lecture on dùng để chỉ việc giảng dạy về một chủ đề; lecture someone có thể mang nghĩa là khiển trách, la mắng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_technique', 'en-b1-3', 'technique', '/tekˈniːk/', 'B1', 'kỹ thuật; phương pháp; thủ thuật; tay nghề; kỹ năng thực hiện', 'n.', 'technical (adj.), technically (adv.), technician (n.)', 'Đồng nghĩa: method, approach', 'technique tập trung vào phương pháp cụ thể; technology chỉ công nghệ.', 'The coach showed me a better technique for swimming.', NULL, 'Huấn luyện viên đã chỉ cho tôi một kỹ thuật bơi tốt hơn.', '{"wordId":"technique","ukIpa":"/tekˈniːk/","usIpa":"/tekˈniːk/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A particular way of doing something, often requiring skill.","vi":"kỹ thuật; phương pháp; thủ thuật"},{"pos":"n.","en":"The skill someone shows when performing a particular activity.","vi":"tay nghề; kỹ năng thực hiện"}],"examples":[{"en":"The coach showed me a better technique for swimming.","vi":"Huấn luyện viên đã chỉ cho tôi một kỹ thuật bơi tốt hơn.","audioKind":"ex"},{"en":"Teachers can use a range of assessment techniques to identify learning difficulties before students fall behind.","vi":"Giáo viên có thể sử dụng nhiều phương pháp đánh giá khác nhau để phát hiện khó khăn học tập trước khi học sinh bị tụt lại phía sau.","audioKind":"ex2"}],"collocations":[{"en":"a technique for doing something","vi":"phương pháp để làm gì đó"},{"en":"relaxation techniques","vi":"kỹ thuật thư giãn"},{"en":"improve your technique","vi":"cải thiện tay nghề kỹ thuật"},{"en":"teaching techniques","vi":"phương pháp giảng dạy"}],"wordFamily":["technical (adj.)","technically (adv.)","technician (n.)"],"synonyms":["method","approach"],"antonyms":[],"tipVi":"technique tập trung vào phương pháp cụ thể; technology chỉ công nghệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elementary', 'en-b1-3', 'elementary', '/ˌeləˈmentəri/', 'B1', 'cơ bản; vỡ lòng; tiểu học', 'adj.', NULL, 'Đồng nghĩa: basic, introductory · Trái nghĩa: advanced', 'elementary school chủ yếu dùng trong tiếng Anh-Mỹ, tiếng Anh-Anh thường dùng primary school.', 'This course teaches elementary cooking skills to complete beginners.', NULL, 'Khóa học này dạy các kỹ năng nấu ăn cơ bản cho người mới bắt đầu.', '{"wordId":"elementary","ukIpa":"/ˌelɪˈmentəri/","usIpa":"/ˌeləˈmentəri/","cefr":"B1","topic":"education","senses":[{"pos":"adj.","en":"Related to the simplest or first stages of learning.","vi":"cơ bản; vỡ lòng"},{"pos":"adj.","en":"Relating to the first years of formal school education.","vi":"tiểu học"}],"examples":[{"en":"This course teaches elementary cooking skills to complete beginners.","vi":"Khóa học này dạy các kỹ năng nấu ăn cơ bản cho người mới bắt đầu.","audioKind":"ex"},{"en":"Elementary education should develop children''s curiosity as well as their ability to read and calculate.","vi":"Giáo dục tiểu học nên phát triển sự tò mò của trẻ em cũng như khả năng đọc và tính toán.","audioKind":"ex2"}],"collocations":[{"en":"elementary knowledge","vi":"kiến thức cơ bản"},{"en":"elementary school","vi":"trường tiểu học"},{"en":"elementary education","vi":"giáo dục tiểu học"},{"en":"elementary level","vi":"trình độ sơ cấp"}],"wordFamily":[],"synonyms":["basic","introductory"],"antonyms":["advanced"],"tipVi":"elementary school chủ yếu dùng trong tiếng Anh-Mỹ, tiếng Anh-Anh thường dùng primary school.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_triangle', 'en-b1-3', 'triangle', '/ˈtraɪæŋɡəl/', 'B1', 'hình tam giác; cái tam tấu (nhạc cụ hình tam giác)', 'n.', 'triangular (adj.)', NULL, 'Tiếng Anh-Anh dùng right-angled triangle, trong khi tiếng Anh-Mỹ thường dùng right triangle.', 'Fold the paper into a triangle before cutting it.', NULL, 'Hãy gấp tờ giấy thành hình tam giác trước khi cắt nó.', '{"wordId":"triangle","ukIpa":"/ˈtraɪæŋɡəl/","usIpa":"/ˈtraɪæŋɡəl/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A flat shape with three straight sides and three angles.","vi":"hình tam giác"},{"pos":"n.","en":"A triangular metal musical instrument struck with a small metal stick.","vi":"cái tam tấu (nhạc cụ hình tam giác)"}],"examples":[{"en":"Fold the paper into a triangle before cutting it.","vi":"Hãy gấp tờ giấy thành hình tam giác trước khi cắt nó.","audioKind":"ex"},{"en":"Engineers often use triangles in bridge designs because these shapes provide strength without requiring excessive material.","vi":"Các kỹ sư thường sử dụng hình tam giác trong thiết kế cầu vì hình dạng này mang lại độ bền chắc mà không cần tốn quá nhiều vật liệu.","audioKind":"ex2"}],"collocations":[{"en":"right-angled triangle","vi":"tam giác vuông"},{"en":"equilateral triangle","vi":"tam giác đều"},{"en":"love triangle","vi":"mối tình tay ba"}],"wordFamily":["triangular (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Anh dùng right-angled triangle, trong khi tiếng Anh-Mỹ thường dùng right triangle.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chart', 'en-b1-3', 'chart', '/tʃɑːrt/', 'B1', 'biểu đồ; đồ thị; ghi chép; theo dõi; vẽ biểu đồ; bản đồ hàng hải; bản đồ hàng không', 'n.', NULL, NULL, 'Dùng chart cho biểu đồ thông tin; dùng map cho bản đồ thông thường và chart cho bản đồ hàng hải/hàng không.', 'This colourful chart shows how we spend our money.', NULL, 'Biểu đồ đầy màu sắc này cho thấy cách chúng tôi tiêu tiền như thế nào.', '{"wordId":"chart","ukIpa":"/tʃɑːt/","usIpa":"/tʃɑːrt/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a visual display of information, often showing comparisons or changes","vi":"biểu đồ; đồ thị"},{"pos":"v.","en":"to record or show how something develops over time","vi":"ghi chép; theo dõi; vẽ biểu đồ"},{"pos":"n.","en":"a detailed map used for navigation at sea or in air","vi":"bản đồ hàng hải; bản đồ hàng không"}],"examples":[{"en":"This colourful chart shows how we spend our money.","vi":"Biểu đồ đầy màu sắc này cho thấy cách chúng tôi tiêu tiền như thế nào.","audioKind":"ex"},{"en":"The chart compares the proportion of commuters using public transport in three different cities.","vi":"Biểu đồ so sánh tỷ lệ người đi làm sử dụng phương tiện giao thông công cộng tại ba thành phố khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"bar chart","vi":"biểu đồ cột"},{"en":"pie chart","vi":"biểu đồ tròn"},{"en":"chart progress","vi":"theo dõi tiến độ"},{"en":"navigation chart","vi":"bản đồ hàng hải"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng chart cho biểu đồ thông tin; dùng map cho bản đồ thông thường và chart cho bản đồ hàng hải/hàng không.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_talent', 'en-b1-3', 'talent', '/ˈtælənt/', 'B1', 'tài năng; khiếu; tài năng trẻ; nhân tài', 'n.', 'talented (adj.)', 'Đồng nghĩa: gift, aptitude', 'Để diễn tả năng khiếu trong lĩnh vực gì, dùng a talent for kèm theo danh từ hoặc danh động từ.', 'My cousin has a real talent for drawing animals.', NULL, 'Em họ tôi có năng khiếu thực sự trong việc vẽ động vật.', '{"wordId":"talent","ukIpa":"/ˈtælənt/","usIpa":"/ˈtælənt/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A natural ability to do something well.","vi":"tài năng; khiếu"},{"pos":"n.","en":"People who have strong abilities in a particular field.","vi":"tài năng trẻ; nhân tài"}],"examples":[{"en":"My cousin has a real talent for drawing animals.","vi":"Em họ tôi có năng khiếu thực sự trong việc vẽ động vật.","audioKind":"ex"},{"en":"Schools should nurture creative talent alongside academic skills to help students develop a wider range of abilities.","vi":"Các trường học nên bồi dưỡng tài năng sáng tạo bên cạnh các kỹ năng học thuật để giúp học sinh phát triển năng lực toàn diện hơn.","audioKind":"ex2"}],"collocations":[{"en":"a talent for","vi":"có năng khiếu về"},{"en":"natural talent","vi":"tài năng thiên bẩm"},{"en":"nurture talent","vi":"nuôi dưỡng nhân tài"},{"en":"attract talent","vi":"thu hút nhân tài"}],"wordFamily":["talented (adj.)"],"synonyms":["gift","aptitude"],"antonyms":[],"tipVi":"Để diễn tả năng khiếu trong lĩnh vực gì, dùng a talent for kèm theo danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diploma', 'en-b1-3', 'diploma', '/dɪˈploʊmə/', 'B1', 'bằng tốt nghiệp; chứng chỉ; văn bằng', 'n.', NULL, 'Đồng nghĩa: certificate', 'Diploma thường chỉ bằng tốt nghiệp khóa học hoặc chứng chỉ, không đồng nghĩa với degree (bằng đại học/sau đại học).', 'She proudly showed her diploma to her grandparents.', NULL, 'Cô ấy tự hào khoe văn bằng tốt nghiệp với ông bà của mình.', '{"wordId":"diploma","ukIpa":"/dɪˈpləʊmə/","usIpa":"/dɪˈploʊmə/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"an official document showing successful completion of a course","vi":"bằng tốt nghiệp; chứng chỉ; văn bằng"}],"examples":[{"en":"She proudly showed her diploma to her grandparents.","vi":"Cô ấy tự hào khoe văn bằng tốt nghiệp với ông bà của mình.","audioKind":"ex"},{"en":"A vocational diploma can provide practical skills that help graduates find employment in specialised industries.","vi":"Bằng cao đẳng nghề có thể cung cấp các kỹ năng thực tế giúp sinh viên mới tốt nghiệp tìm được việc làm trong các ngành công nghiệp chuyên môn.","audioKind":"ex2"}],"collocations":[{"en":"earn a diploma","vi":"đạt được bằng cấp"},{"en":"high school diploma","vi":"bằng tốt nghiệp trung học"},{"en":"diploma in nursing","vi":"bằng chuyên ngành điều dưỡng"}],"wordFamily":[],"synonyms":["certificate"],"antonyms":[],"tipVi":"Diploma thường chỉ bằng tốt nghiệp khóa học hoặc chứng chỉ, không đồng nghĩa với degree (bằng đại học/sau đại học).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_underline', 'en-b1-3', 'underline', '/ˌʌndərˈlaɪn/', 'B1', 'gạch chân; nhấn mạnh; làm nổi bật', 'v.', NULL, 'Đồng nghĩa: underscore', 'Nghĩa gốc là vẽ đường ở phía dưới, ngoài ra còn thường dùng để nhấn mạnh tầm quan trọng.', 'Our teacher asked us to underline the unfamiliar words.', NULL, 'Giáo viên yêu cầu chúng tôi gạch chân những từ chưa biết nghĩa.', '{"wordId":"underline","ukIpa":"/ˌʌndəˈlaɪn/","usIpa":"/ˌʌndərˈlaɪn/","cefr":"B1","topic":"education","senses":[{"pos":"v.","en":"to draw a line beneath a word or phrase","vi":"gạch chân"},{"pos":"v.","en":"to show that something is especially important","vi":"nhấn mạnh; làm nổi bật"}],"examples":[{"en":"Our teacher asked us to underline the unfamiliar words.","vi":"Giáo viên yêu cầu chúng tôi gạch chân những từ chưa biết nghĩa.","audioKind":"ex"},{"en":"These findings underline the importance of providing affordable housing near public transport for families on low incomes.","vi":"Những phát hiện này nhấn mạnh tầm quan trọng của việc cung cấp nhà ở giá rẻ gần phương tiện giao thông công cộng cho các gia đình có thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"underline a word","vi":"gạch chân một từ"},{"en":"underline the importance of","vi":"nhấn mạnh tầm quan trọng của"},{"en":"underline the need for","vi":"nhấn mạnh sự cần thiết của"}],"wordFamily":[],"synonyms":["underscore"],"antonyms":[],"tipVi":"Nghĩa gốc là vẽ đường ở phía dưới, ngoài ra còn thường dùng để nhấn mạnh tầm quan trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_achievement', 'en-b1-3', 'achievement', '/əˈtʃiːvmənt/', 'B1', 'thành tựu; thành tích; sự hoàn thành, đạt được mục tiêu', 'n.', 'achieve (v.), achievable (adj.), achiever (n.)', 'Đồng nghĩa: accomplishment, attainment · Trái nghĩa: failure', 'Thành tựu cụ thể thì đếm được; chỉ việc đạt được mục tiêu thường không đếm được.', 'Finishing my first long hike felt like a real achievement.', NULL, 'Hoàn thành chuyến đi bộ đường dài đầu tiên mang lại cho tôi cảm giác thực sự có thành tựu.', '{"wordId":"achievement","ukIpa":"/əˈtʃiːvmənt/","usIpa":"/əˈtʃiːvmənt/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"Something valuable accomplished through effort or skill.","vi":"thành tựu; thành tích"},{"pos":"n.","en":"The successful completion of a goal through effort.","vi":"sự hoàn thành, đạt được mục tiêu"}],"examples":[{"en":"Finishing my first long hike felt like a real achievement.","vi":"Hoàn thành chuyến đi bộ đường dài đầu tiên mang lại cho tôi cảm giác thực sự có thành tựu.","audioKind":"ex"},{"en":"Schools should recognise creative achievements alongside examination results to encourage a wider range of student abilities.","vi":"Các trường học nên công nhận các thành tích sáng tạo bên cạnh kết quả thi cử để khuyến khích năng lực đa dạng hơn của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"a major achievement","vi":"một thành tựu lớn"},{"en":"a sense of achievement","vi":"cảm giác thành tựu"},{"en":"academic achievement","vi":"thành tích học tập"},{"en":"the achievement of goals","vi":"việc đạt được các mục tiêu"}],"wordFamily":["achieve (v.)","achievable (adj.)","achiever (n.)"],"synonyms":["accomplishment","attainment"],"antonyms":["failure"],"tipVi":"Thành tựu cụ thể thì đếm được; chỉ việc đạt được mục tiêu thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_3_1', 'en-b1-3', 'Cách dùng “headmaster” (n.) — hiệu trưởng nam; nam hiệu trưởng', 'school headmaster  ·  deputy headmaster  ·  headmaster''s office', 'Chỉ phái nam; từ headteacher trong tiếng Anh-Anh dùng chung cho cả hai giới, còn tiếng Anh-Mỹ thường dùng principal.', 'Họ từ (Word Family): headmistress (n.), headship (n.)', '[{"hanzi":"The headmaster welcomed new pupils at the school gate.","pinyin":"","meaning":"Nam hiệu trưởng chào đón các học sinh mới ở cổng trường."},{"hanzi":"The headmaster introduced a mentoring programme to help younger pupils develop confidence and settle into school life.","pinyin":"","meaning":"Nam hiệu trưởng đã giới thiệu một chương trình kèm cặp nhằm giúp các học sinh nhỏ tuổi xây dựng sự tự tin và hòa nhập với đời sống học đường."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_3_2', 'en-b1-3', 'Cách dùng “diploma” (n.) — bằng tốt nghiệp; chứng chỉ; văn bằng', 'earn a diploma  ·  high school diploma  ·  diploma in nursing', 'Diploma thường chỉ bằng tốt nghiệp khóa học hoặc chứng chỉ, không đồng nghĩa với degree (bằng đại học/sau đại học).', 'Đồng nghĩa: certificate', '[{"hanzi":"She proudly showed her diploma to her grandparents.","pinyin":"","meaning":"Cô ấy tự hào khoe văn bằng tốt nghiệp với ông bà của mình."},{"hanzi":"A vocational diploma can provide practical skills that help graduates find employment in specialised industries.","pinyin":"","meaning":"Bằng cao đẳng nghề có thể cung cấp các kỹ năng thực tế giúp sinh viên mới tốt nghiệp tìm được việc làm trong các ngành công nghiệp chuyên môn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_3_3', 'en-b1-3', 'Cách dùng “lecture” (n.) — bài giảng; buổi thuyết trình', 'attend a lecture  ·  give a lecture  ·  lecture on biology', 'lecture on dùng để chỉ việc giảng dạy về một chủ đề; lecture someone có thể mang nghĩa là khiển trách, la mắng.', 'Họ từ (Word Family): lecturer (n.)', '[{"hanzi":"I stayed after the lecture to ask a question.","pinyin":"","meaning":"Tôi ở lại sau buổi giảng để đặt một câu hỏi."},{"hanzi":"Universities should combine traditional lectures with practical activities that encourage students to apply their knowledge.","pinyin":"","meaning":"Các trường đại học nên kết hợp các bài giảng truyền thống với các hoạt động thực tế khuyến khích sinh viên vận dụng kiến thức."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_3_4', 'en-b1-3', 'Cách dùng “chart” (n.) — biểu đồ; đồ thị', 'bar chart  ·  pie chart  ·  chart progress', 'Dùng chart cho biểu đồ thông tin; dùng map cho bản đồ thông thường và chart cho bản đồ hàng hải/hàng không.', NULL, '[{"hanzi":"This colourful chart shows how we spend our money.","pinyin":"","meaning":"Biểu đồ đầy màu sắc này cho thấy cách chúng tôi tiêu tiền như thế nào."},{"hanzi":"The chart compares the proportion of commuters using public transport in three different cities.","pinyin":"","meaning":"Biểu đồ so sánh tỷ lệ người đi làm sử dụng phương tiện giao thông công cộng tại ba thành phố khác nhau."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_3_1', 'en-b1-3', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
