INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_3_1_2', 'ten_b1_3_1', 'librarian', 'The librarian helped me find a book about birds.', 'The librarian helped me find a book about birds.', '/laɪˈbreriən/', 'Người thủ thư đã giúp tôi tìm một cuốn sách viết về các loài chim.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_3_1_3', 'ten_b1_3_1', 'secondly', 'Firstly, the flat is affordable; secondly, it has a balcony.', 'Firstly, the flat is affordable; secondly, it has a balcony.', '/ˈsekəndli/', 'Thứ nhất, căn hộ có giá cả phải chăng; thứ hai, nó có một ban công.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_3_1_4', 'ten_b1_3_1', 'improvement', 'Your latest drawing shows a real improvement in shading.', 'Your latest drawing shows a real improvement in shading.', '/ɪmˈpruːvmənt/', 'Bức vẽ mới nhất của bạn cho thấy sự tiến bộ rõ rệt trong kỹ thuật đánh bóng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_3_1_5', 'ten_b1_3_1', 'define', 'Can you define this word without using a dictionary?', 'Can you define this word without using a dictionary?', '/dɪˈfaɪn/', 'Bạn có thể giải nghĩa từ này mà không cần dùng từ điển không?', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_3_1_6', 'ten_b1_3_1', 'handout', 'Our teacher gave us a handout about healthy eating.', 'Our teacher gave us a handout about healthy eating.', '/ˈhændaʊt/', 'Giáo viên của chúng tôi đã phát một tài liệu về chế độ ăn uống lành mạnh.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_3_1_7', 'ten_b1_3_1', 'revise', 'I need to revise for my biology exam tonight.', 'I need to revise for my biology exam tonight.', '/rɪˈvaɪz/', 'Tối nay tôi cần phải ôn bài để chuẩn bị cho kỳ thi sinh học.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_3_1_8', 'ten_b1_3_1', 'graduation', 'My sister wore a blue gown at her graduation.', 'My sister wore a blue gown at her graduation.', '/ˌɡrædʒuˈeɪʃən/', 'Chị tôi mặc một chiếc áo cử nhân màu xanh trong lễ tốt nghiệp của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_3_1_1', 'en-b1-3', 'ten_b1_3_1', 'listening', 'listening', 'My cousin cheated by hiding cards under the table.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chị tôi mặc một chiếc áo cử nhân màu xanh trong lễ tốt nghiệp của mình.","Cô ấy tự hào khoe văn bằng tốt nghiệp với ông bà của mình.","Anh họ tôi đã gian lận bằng cách giấu những lá bài dưới gầm bàn.","Bạn có thể giải nghĩa từ này mà không cần dùng từ điển không?"]'::jsonb, 2, 'My cousin cheated by hiding cards under the table. → Anh họ tôi đã gian lận bằng cách giấu những lá bài dưới gầm bàn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_3_1_2', 'en-b1-3', 'ten_b1_3_1', 'listening', 'listening', 'The librarian helped me find a book about birds.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tối nay tôi cần phải ôn bài để chuẩn bị cho kỳ thi sinh học.","Hãy gấp tờ giấy thành hình tam giác trước khi cắt nó.","Người thủ thư đã giúp tôi tìm một cuốn sách viết về các loài chim.","Em họ tôi có năng khiếu thực sự trong việc vẽ động vật."]'::jsonb, 2, 'The librarian helped me find a book about birds. → Người thủ thư đã giúp tôi tìm một cuốn sách viết về các loài chim.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_3_1_3', 'en-b1-3', 'ten_b1_3_1', 'listening', 'listening', 'Firstly, the flat is affordable; secondly, it has a balcony.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thứ nhất, căn hộ có giá cả phải chăng; thứ hai, nó có một ban công.","Người thủ thư đã giúp tôi tìm một cuốn sách viết về các loài chim.","Huấn luyện viên đã chỉ cho tôi một kỹ thuật bơi tốt hơn.","Cô ấy tự hào khoe văn bằng tốt nghiệp với ông bà của mình."]'::jsonb, 0, 'Firstly, the flat is affordable; secondly, it has a balcony. → Thứ nhất, căn hộ có giá cả phải chăng; thứ hai, nó có một ban công.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_3_2', 'en-b1-3', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_3_2_1', 'ten_b1_3_2', 'cheat', 'Schools can discourage students from cheating by designing assessments that reward original thinking rather than memorisation.', 'Schools can discourage students from cheating by designing assessments that reward original thinking rather than memorisation.', '/tʃiːt/', 'Nhà trường có thể ngăn chặn học sinh gian lận bằng cách thiết kế các bài kiểm tra đánh giá cao tư duy độc lập thay vì học vẹt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_3_2_2', 'ten_b1_3_2', 'librarian', 'School librarians support independent learning by teaching students how to locate reliable sources and evaluate information.', 'School librarians support independent learning by teaching students how to locate reliable sources and evaluate information.', '/laɪˈbreriən/', 'Các nhân viên thư viện trường học hỗ trợ việc tự học bằng cách hướng dẫn học sinh cách tìm kiếm nguồn tài liệu đáng tin cậy và đánh giá thông tin.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_3_2_3', 'ten_b1_3_2', 'secondly', 'Secondly, expanding public transport could reduce traffic congestion and improve access to employment opportunities.', 'Secondly, expanding public transport could reduce traffic congestion and improve access to employment opportunities.', '/ˈsekəndli/', 'Thứ hai, việc mở rộng giao thông công cộng có thể làm giảm tình trạng tắc nghẽn giao thông và cải thiện khả năng tiếp cận cơ hội việc làm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_3_2_4', 'ten_b1_3_2', 'improvement', 'Investment in public transport can bring significant improvements in air quality and reduce travel times for urban residents.', 'Investment in public transport can bring significant improvements in air quality and reduce travel times for urban residents.', '/ɪmˈpruːvmənt/', 'Đầu tư vào giao thông công cộng có thể mang lại những cải thiện đáng kể về chất lượng không khí và rút ngắn thời gian di chuyển cho cư dân đô thị.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_3_2_5', 'ten_b1_3_2', 'define', 'Governments should clearly define their environmental objectives before introducing policies that affect businesses and local communities.', 'Governments should clearly define their environmental objectives before introducing policies that affect businesses and local communities.', '/dɪˈfaɪn/', 'Chính phủ nên xác định rõ các mục tiêu môi trường của mình trước khi ban hành các chính sách tác động đến doanh nghiệp và cộng đồng địa phương.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_3_2_6', 'ten_b1_3_2', 'handout', 'A well-designed handout can help students review key concepts independently after a lecture has finished.', 'A well-designed handout can help students review key concepts independently after a lecture has finished.', '/ˈhændaʊt/', 'Một bản tài liệu phát tay được thiết kế tốt có thể giúp học sinh tự ôn lại các khái niệm cốt lõi sau khi buổi giảng kết thúc.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_3_2_1', 'en-b1-3', 'ten_b1_3_2', 'listening', 'listening', 'Schools can discourage students from cheating by designing assessments that reward original thinking rather than memorisation.', NULL, 'Trong câu vừa nghe, từ “cheat” mang nghĩa nào sau đây?', '["gian lận; chơi gian","giải pháp; cách giải quyết","nghiên cứu; sự khảo sát","quốc gia; đất nước và toàn thể người dân"]'::jsonb, 0, '“cheat” (/tʃiːt/): gian lận; chơi gian. Câu đầy đủ: Schools can discourage students from cheating by designing assessments that reward original thinking rather than memorisation.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_3_2_2', 'en-b1-3', 'ten_b1_3_2', 'listening', 'listening', 'School librarians support independent learning by teaching students how to locate reliable sources and evaluate information.', NULL, 'Trong câu vừa nghe, từ “librarian” mang nghĩa nào sau đây?', '["cái thang","thủ thư; nhân viên thư viện","làm mệt mỏi; mệt mỏi","xe buýt nhỏ; xe khách nhỏ"]'::jsonb, 1, '“librarian” (/laɪˈbreriən/): thủ thư; nhân viên thư viện. Câu đầy đủ: School librarians support independent learning by teaching students how to locate reliable sources and evaluate information.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
