INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_3_2', 'en-b1-3', NULL, 'comprehensive_test', 'listening', 'The librarian helped me find a book about birds.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người thủ thư đã giúp tôi tìm một cuốn sách viết về các loài chim.","Em họ tôi có năng khiếu thực sự trong việc vẽ động vật.","Cô ấy tự hào khoe văn bằng tốt nghiệp với ông bà của mình.","Anh họ tôi đã gian lận bằng cách giấu những lá bài dưới gầm bàn."]'::jsonb, 0, 'The librarian helped me find a book about birds. → Người thủ thư đã giúp tôi tìm một cuốn sách viết về các loài chim.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_3_3', 'en-b1-3', NULL, 'comprehensive_test', 'listening', 'secondly', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ngăn chặn; phòng ngừa; cản trở","thứ hai là; thứ nhì; mặt khác","ở phía bên kia; vượt ra xa hơn","xe máy kéo; máy cày"]'::jsonb, 1, 'secondly (/ˈsekəndli/) → thứ hai là; thứ nhì; mặt khác', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_3_4', 'en-b1-3', NULL, 'comprehensive_test', 'listening', 'Your latest drawing shows a real improvement in shading.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Biểu đồ đầy màu sắc này cho thấy cách chúng tôi tiêu tiền như thế nào.","Em họ tôi có năng khiếu thực sự trong việc vẽ động vật.","Anh họ tôi đã gian lận bằng cách giấu những lá bài dưới gầm bàn.","Bức vẽ mới nhất của bạn cho thấy sự tiến bộ rõ rệt trong kỹ thuật đánh bóng."]'::jsonb, 3, 'Your latest drawing shows a real improvement in shading. → Bức vẽ mới nhất của bạn cho thấy sự tiến bộ rõ rệt trong kỹ thuật đánh bóng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_3_5', 'en-b1-3', NULL, 'comprehensive_test', 'listening', 'define', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chu đáo; ân cần; hay quan tâm đến người khác","định nghĩa; giải thích nghĩa","hợp thời trang; có phong cách; có gu thẩm mỹ","xu hướng; trào lưu"]'::jsonb, 1, 'define (/dɪˈfaɪn/) → định nghĩa; giải thích nghĩa; xác định rõ; vạch rõ; làm nên đặc trưng; định hình', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_3_6', 'en-b1-3', NULL, 'comprehensive_test', 'listening', 'Our teacher gave us a handout about healthy eating.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy tự hào khoe văn bằng tốt nghiệp với ông bà của mình.","Giáo viên của chúng tôi đã phát một tài liệu về chế độ ăn uống lành mạnh.","Chúng tôi thực hành phép nhân bằng cách sắp xếp các nút áo thành các hàng đều nhau.","Bạn có thể giải nghĩa từ này mà không cần dùng từ điển không?"]'::jsonb, 1, 'Our teacher gave us a handout about healthy eating. → Giáo viên của chúng tôi đã phát một tài liệu về chế độ ăn uống lành mạnh.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_3_7', 'en-b1-3', NULL, 'comprehensive_test', 'listening', 'revise', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ôn tập; ôn thi","xa hơn; thêm nữa; ở mức độ lớn hơn","hiện tại; đang","thương tích; chấn thương"]'::jsonb, 0, 'revise (/rɪˈvaɪz/) → ôn tập; ôn thi; sửa đổi; chỉnh sửa', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_3_8', 'en-b1-3', NULL, 'comprehensive_test', 'listening', 'My sister wore a blue gown at her graduation.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Khóa học này dạy các kỹ năng nấu ăn cơ bản cho người mới bắt đầu.","Giáo viên yêu cầu chúng tôi gạch chân những từ chưa biết nghĩa.","Chị tôi mặc một chiếc áo cử nhân màu xanh trong lễ tốt nghiệp của mình.","Tối nay tôi cần phải ôn bài để chuẩn bị cho kỳ thi sinh học."]'::jsonb, 2, 'My sister wore a blue gown at her graduation. → Chị tôi mặc một chiếc áo cử nhân màu xanh trong lễ tốt nghiệp của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_3_9', 'en-b1-3', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To state exactly what a word or idea means.”?', '["talent","define","handout","elementary"]'::jsonb, 1, 'define (/dɪˈfaɪn/) → định nghĩa; giải thích nghĩa', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
