INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_3_18', 'en-b1-3', NULL, 'comprehensive_test', 'reading', NULL, 'Schools can discourage students from cheating by designing assessments that reward original thinking rather than memorisation.', 'Dựa vào câu trên, từ “cheat” có nghĩa phù hợp nhất là gì?', '["lời cảnh báo; sự nhắc nhở","thời thanh thiếu niên; tuổi trẻ","chào hỏi; đón tiếp","gian lận; chơi gian"]'::jsonb, 3, 'cheat: gian lận; chơi gian; lừa dối; lừa gạt; kẻ gian lận; kẻ lừa đảo. Dịch cả câu: Nhà trường có thể ngăn chặn học sinh gian lận bằng cách thiết kế các bài kiểm tra đánh giá cao tư duy độc lập thay vì học vẹt.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_3_19', 'en-b1-3', NULL, 'comprehensive_test', 'reading', NULL, 'School librarians support independent learning by teaching students how to locate reliable sources and evaluate information.', 'Dựa vào câu trên, từ “librarian” có nghĩa phù hợp nhất là gì?', '["vận động viên","tái chế; xử lý chất liệu đã qua sử dụng để dùng lại","bão cuồng phong; bão lớn vùng nhiệt đới","thủ thư; nhân viên thư viện"]'::jsonb, 3, 'librarian: thủ thư; nhân viên thư viện. Dịch cả câu: Các nhân viên thư viện trường học hỗ trợ việc tự học bằng cách hướng dẫn học sinh cách tìm kiếm nguồn tài liệu đáng tin cậy và đánh giá thông tin.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_3_20', 'en-b1-3', NULL, 'comprehensive_test', 'reading', NULL, 'Secondly, expanding public transport could reduce traffic congestion and improve access to employment opportunities.', 'Dựa vào câu trên, từ “secondly” có nghĩa phù hợp nhất là gì?', '["anh rể; em rể; anh/em vợ; anh/em chồng","con cáo (loài thú hoang dã có tai nhọn và đuôi rậm)","thứ hai là; thứ nhì; mặt khác","ngực; khoang ngực"]'::jsonb, 2, 'secondly: thứ hai là; thứ nhì; mặt khác. Dịch cả câu: Thứ hai, việc mở rộng giao thông công cộng có thể làm giảm tình trạng tắc nghẽn giao thông và cải thiện khả năng tiếp cận cơ hội việc làm.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_3_21', 'en-b1-3', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in public transport can bring significant improvements in air quality and reduce travel times for urban residents.', 'Dựa vào câu trên, từ “improvement” có nghĩa phù hợp nhất là gì?', '["lưới; vật làm bằng lưới","sự cải thiện; sự tiến bộ","họng; cổ họng","thuộc về miền Nam; ở phía nam"]'::jsonb, 1, 'improvement: sự cải thiện; sự tiến bộ; điểm cải tiến; điểm tốt hơn. Dịch cả câu: Đầu tư vào giao thông công cộng có thể mang lại những cải thiện đáng kể về chất lượng không khí và rút ngắn thời gian di chuyển cho cư dân đô thị.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
