INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-4', 'en', 'Bài 4: Giáo dục & Trường học (4) - CEFR B1', 'CEFR B1', 'B1 · Giáo dục', '21 từ vựng Tiếng Anh CEFR B1 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3004, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intermediate', 'en-b1-4', 'intermediate', '/ˌɪntərˈmiːdiət/', 'B1', 'trung cấp; ở giữa; người học trình độ trung cấp', 'adj.', NULL, 'Đồng nghĩa: mid-level', 'Thường chỉ trình độ nằm giữa mức cơ bản (beginner) và nâng cao (advanced).', 'This swimming class is suitable for intermediate learners.', NULL, 'Lớp học bơi này phù hợp với các học viên ở trình độ trung cấp.', '{"wordId":"intermediate","ukIpa":"/ˌɪntəˈmiːdiət/","usIpa":"/ˌɪntərˈmiːdiət/","cefr":"B1","topic":"education","senses":[{"pos":"adj.","en":"Between basic and advanced levels, or between two stages.","vi":"trung cấp; ở giữa"},{"pos":"n.","en":"A learner whose skills are between beginner and advanced levels.","vi":"người học trình độ trung cấp"}],"examples":[{"en":"This swimming class is suitable for intermediate learners.","vi":"Lớp học bơi này phù hợp với các học viên ở trình độ trung cấp.","audioKind":"ex"},{"en":"Intermediate language courses should balance grammar instruction with opportunities for meaningful communication outside the classroom.","vi":"Các khóa học ngôn ngữ trung cấp nên cân bằng giữa việc giảng dạy ngữ pháp và cơ hội giao tiếp có ý nghĩa ngoài lớp học.","audioKind":"ex2"}],"collocations":[{"en":"intermediate level","vi":"trình độ trung cấp"},{"en":"an intermediate course","vi":"khóa học trung cấp"},{"en":"an intermediate stage","vi":"giai đoạn trung gian"}],"wordFamily":[],"synonyms":["mid-level"],"antonyms":[],"tipVi":"Thường chỉ trình độ nằm giữa mức cơ bản (beginner) và nâng cao (advanced).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subtract', 'en-b1-4', 'subtract', '/səbˈtrækt/', 'B1', 'trừ đi; khấu trừ', 'v.', 'subtraction (n.)', 'Đồng nghĩa: deduct · Trái nghĩa: add', 'subtract A from B nghĩa là lấy B trừ đi A.', 'Subtract the delivery charge to find the original price.', NULL, 'Trừ phí giao hàng để tìm ra giá gốc.', '{"wordId":"subtract","ukIpa":"/səbˈtrækt/","usIpa":"/səbˈtrækt/","cefr":"B1","topic":"education","senses":[{"pos":"v.","en":"to take one number or amount away from another","vi":"trừ đi; khấu trừ"}],"examples":[{"en":"Subtract the delivery charge to find the original price.","vi":"Trừ phí giao hàng để tìm ra giá gốc.","audioKind":"ex"},{"en":"Researchers subtract production costs from total revenue to calculate the profit generated by each farming method.","vi":"Các nhà nghiên cứu trừ chi phí sản xuất khỏi tổng doanh thu để tính toán lợi nhuận do từng phương thức canh tác tạo ra.","audioKind":"ex2"}],"collocations":[{"en":"subtract from","vi":"trừ đi từ"},{"en":"subtract the cost","vi":"khấu trừ chi phí"}],"wordFamily":["subtraction (n.)"],"synonyms":["deduct"],"antonyms":["add"],"tipVi":"subtract A from B nghĩa là lấy B trừ đi A.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aloud', 'en-b1-4', 'aloud', '/əˈlaʊd/', 'B1', 'lớn tiếng; thành tiếng', 'adv.', NULL, 'Đồng nghĩa: out loud · Trái nghĩa: silently', 'aloud nhấn mạnh việc phát ra âm thanh, không nhất thiết phải vang to như loudly.', 'Please read the recipe aloud while I mix.', NULL, 'Xin hãy đọc to công thức nấu ăn trong lúc tôi trộn nguyên liệu.', '{"wordId":"aloud","ukIpa":"/əˈlaʊd/","usIpa":"/əˈlaʊd/","cefr":"B1","topic":"education","senses":[{"pos":"adv.","en":"With an audible voice rather than silently.","vi":"lớn tiếng; thành tiếng"}],"examples":[{"en":"Please read the recipe aloud while I mix.","vi":"Xin hãy đọc to công thức nấu ăn trong lúc tôi trộn nguyên liệu.","audioKind":"ex"},{"en":"Reading stories aloud can help young children develop vocabulary and strengthen their understanding of spoken language.","vi":"Đọc to các câu chuyện có thể giúp trẻ nhỏ phát triển vốn từ vựng và củng cố sự hiểu biết về ngôn ngữ nói.","audioKind":"ex2"}],"collocations":[{"en":"read aloud","vi":"đọc thành tiếng"},{"en":"think aloud","vi":"nói ra suy nghĩ"},{"en":"say aloud","vi":"nói lớn tiếng"}],"wordFamily":[],"synonyms":["out loud"],"antonyms":["silently"],"tipVi":"aloud nhấn mạnh việc phát ra âm thanh, không nhất thiết phải vang to như loudly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_failure', 'en-b1-4', 'failure', '/ˈfeɪljər/', 'B1', 'sự thất bại; điều thất bại; sự cố; sự suy giảm; việc không thực hiện; sự xao lãng', 'n.', 'fail (v.), failed (adj.), failing (n.)', 'Trái nghĩa: success', 'Nói chung sự thất bại thường không đếm được; a failure có thể chỉ một sự việc thất bại cụ thể.', 'Despite her first failure, she tried baking bread again.', NULL, 'Mặc dù thất bại lần đầu, cô ấy vẫn thử nướng bánh mì lại một lần nữa.', '{"wordId":"failure","ukIpa":"/ˈfeɪljə/","usIpa":"/ˈfeɪljər/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a lack of success, or something that does not succeed","vi":"sự thất bại; điều thất bại"},{"pos":"n.","en":"a situation in which a machine or organ stops working","vi":"sự cố; sự suy giảm"},{"pos":"n.","en":"not doing something that is expected or required","vi":"việc không thực hiện; sự xao lãng"}],"examples":[{"en":"Despite her first failure, she tried baking bread again.","vi":"Mặc dù thất bại lần đầu, cô ấy vẫn thử nướng bánh mì lại một lần nữa.","audioKind":"ex"},{"en":"Schools should treat failure as an opportunity for learning rather than as evidence of a student''s limited ability.","vi":"Các trường học nên coi thất bại là cơ hội học hỏi thay vì bằng chứng cho thấy năng lực hạn chế của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"end in failure","vi":"kết thúc trong thất bại"},{"en":"power failure","vi":"sự cố mất điện"},{"en":"heart failure","vi":"suy tim"},{"en":"failure to comply","vi":"việc không tuân thủ"}],"wordFamily":["fail (v.)","failed (adj.)","failing (n.)"],"synonyms":[],"antonyms":["success"],"tipVi":"Nói chung sự thất bại thường không đếm được; a failure có thể chỉ một sự việc thất bại cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refer', 'en-b1-4', 'refer', '/rɪˈfɝː/', 'B1', 'nhắc đến; ám chỉ; tra cứu; tham khảo; chuyển tuyến; giới thiệu', 'v.', 'reference (n), referral (n)', 'Đồng nghĩa: mention, consult', 'Thường đi với giới từ to; dạng quá khứ là referred, phân từ là referring.', 'Please refer to the map inside your guidebook.', NULL, 'Vui lòng tham khảo bản đồ ở bên trong cuốn sách hướng dẫn của bạn.', '{"wordId":"refer","ukIpa":"/rɪˈfɜː/","usIpa":"/rɪˈfɝː/","cefr":"B1","topic":"education","senses":[{"pos":"v.","en":"mention someone or something, or have them as the meaning","vi":"nhắc đến; ám chỉ"},{"pos":"v.","en":"look at a source to find information","vi":"tra cứu; tham khảo"},{"pos":"v.","en":"send someone or something elsewhere for expert help or consideration","vi":"chuyển tuyến; giới thiệu"}],"examples":[{"en":"Please refer to the map inside your guidebook.","vi":"Vui lòng tham khảo bản đồ ở bên trong cuốn sách hướng dẫn của bạn.","audioKind":"ex"},{"en":"Doctors may refer patients to specialists when their symptoms require more detailed investigation or treatment.","vi":"Các bác sĩ có thể chuyển bệnh nhân đến gặp bác sĩ chuyên khoa khi các triệu chứng của họ đòi hỏi phải thăm khám hoặc điều trị chi tiết hơn.","audioKind":"ex2"}],"collocations":[{"en":"refer to a report","vi":"tham khảo báo cáo"},{"en":"refer to something as","vi":"gọi cái gì là"},{"en":"refer someone to a specialist","vi":"chuyển bệnh nhân cho chuyên gia"}],"wordFamily":["reference (n)","referral (n)"],"synonyms":["mention","consult"],"antonyms":[],"tipVi":"Thường đi với giới từ to; dạng quá khứ là referred, phân từ là referring.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_secondary', 'en-b1-4', 'secondary', '/ˈsekənderi/', 'B1', 'thuộc bậc trung học; trung học; thứ yếu; kém quan trọng hơn', 'adj.', 'second (num.), secondarily (adv.)', 'Trái nghĩa: primary', 'Biểu thị ý "thứ yếu hơn" thì dùng secondary to, không dùng secondary than.', 'My sister starts secondary school after the summer holidays.', NULL, 'Em gái tôi bắt đầu vào học cấp hai sau kỳ nghỉ hè.', '{"wordId":"secondary","ukIpa":"/ˈsekəndri/","usIpa":"/ˈsekənderi/","cefr":"B1","topic":"education","senses":[{"pos":"adj.","en":"Relating to education after primary school and before higher education.","vi":"thuộc bậc trung học; trung học"},{"pos":"adj.","en":"Less important than something else.","vi":"thứ yếu; kém quan trọng hơn"}],"examples":[{"en":"My sister starts secondary school after the summer holidays.","vi":"Em gái tôi bắt đầu vào học cấp hai sau kỳ nghỉ hè.","audioKind":"ex"},{"en":"Access to quality secondary education can improve employment prospects for young people in rural communities.","vi":"Việc tiếp cận giáo dục trung học chất lượng cao có thể cải thiện triển vọng việc làm cho giới trẻ ở các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"secondary school","vi":"trường trung học"},{"en":"secondary education","vi":"giáo dục trung học"},{"en":"of secondary importance","vi":"có tầm quan trọng thứ yếu"},{"en":"secondary to","vi":"thứ yếu so với"}],"wordFamily":["second (num.)","secondarily (adv.)"],"synonyms":[],"antonyms":["primary"],"tipVi":"Biểu thị ý \"thứ yếu hơn\" thì dùng secondary to, không dùng secondary than.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_workshop', 'en-b1-4', 'workshop', '/ˈwɝːkʃɑːp/', 'B1', 'buổi thảo luận thực tế; hội thảo; xưởng; xưởng làm việc', 'n.', NULL, NULL, 'Biểu đạt hoạt động học tập thường nhấn mạnh sự tham gia và thực hành, thay vì chỉ nghe giảng.', 'I made a clay bowl at a pottery workshop.', NULL, 'Tôi đã làm một chiếc bát đất sét tại một buổi hội thảo làm gốm.', '{"wordId":"workshop","ukIpa":"/ˈwɜːkʃɒp/","usIpa":"/ˈwɝːkʃɑːp/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A session where people learn by discussing and practising together.","vi":"buổi thảo luận thực tế; hội thảo"},{"pos":"n.","en":"A room or building where things are made or repaired.","vi":"xưởng; xưởng làm việc"}],"examples":[{"en":"I made a clay bowl at a pottery workshop.","vi":"Tôi đã làm một chiếc bát đất sét tại một buổi hội thảo làm gốm.","audioKind":"ex"},{"en":"Schools should offer practical workshops that help students develop communication skills through collaborative activities.","vi":"Các trường học nên tổ chức các buổi hội thảo thực tế giúp học sinh phát triển kỹ năng giao tiếp thông qua các hoạt động hợp tác.","audioKind":"ex2"}],"collocations":[{"en":"attend a workshop","vi":"tham gia hội thảo"},{"en":"run a workshop","vi":"tổ chức hội thảo"},{"en":"a training workshop","vi":"hội thảo đào tạo"},{"en":"a repair workshop","vi":"xưởng sửa chữa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Biểu đạt hoạt động học tập thường nhấn mạnh sự tham gia và thực hành, thay vì chỉ nghe giảng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_primary', 'en-b1-4', 'primary', '/ˈpraɪmeri/', 'B1', 'chủ yếu; quan trọng hàng đầu; chính; bậc tiểu học; giáo dục tiểu học; ban đầu; nguyên thủy; trực tiếp', 'adj.', 'primarily (adv.)', 'Đồng nghĩa: main, principal · Trái nghĩa: secondary', 'Primary school chỉ trường tiểu học; primarily là dạng phó từ.', 'Our primary concern is keeping the children safe.', NULL, 'Mối quan tâm hàng đầu của chúng tôi là giữ an toàn cho trẻ em.', '{"wordId":"primary","ukIpa":"/ˈpraɪməri/","usIpa":"/ˈpraɪmeri/","cefr":"B1","topic":"education","senses":[{"pos":"adj.","en":"more important than anything else","vi":"chủ yếu; quan trọng hàng đầu; chính"},{"pos":"adj.","en":"relating to the first stage of formal schooling","vi":"bậc tiểu học; giáo dục tiểu học"},{"pos":"adj.","en":"original or direct, rather than derived from something else","vi":"ban đầu; nguyên thủy; trực tiếp"}],"examples":[{"en":"Our primary concern is keeping the children safe.","vi":"Mối quan tâm hàng đầu của chúng tôi là giữ an toàn cho trẻ em.","audioKind":"ex"},{"en":"Investment in primary education can reduce inequality by giving children a stronger foundation for future learning.","vi":"Đầu tư vào giáo dục tiểu học có thể giảm bất bình đẳng bằng cách mang lại cho trẻ nền tảng vững chắc hơn cho việc học tập trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"primary concern","vi":"mối quan tâm hàng đầu"},{"en":"primary school","vi":"trường tiểu học"},{"en":"primary source","vi":"nguồn tài liệu gốc"},{"en":"primary objective","vi":"mục tiêu chính"}],"wordFamily":["primarily (adv.)"],"synonyms":["main","principal"],"antonyms":["secondary"],"tipVi":"Primary school chỉ trường tiểu học; primarily là dạng phó từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_presentation', 'en-b1-4', 'presentation', '/ˌprezənˈteɪʃən/', 'B1', 'bài thuyết trình; bài phát biểu; cách trình bày; hình thức thể hiện; sự trao tặng; sự biếu tặng', 'n.', 'present (v.), presenter (n.)', NULL, 'Thuyết trình dùng give a presentation; chú ý trọng âm của từ present khi làm động từ.', 'I practised my presentation in front of my sister.', NULL, 'Tôi đã luyện tập bài thuyết trình của mình trước mặt chị gái.', '{"wordId":"presentation","ukIpa":"/ˌprezənˈteɪʃən/","usIpa":"/ˌprezənˈteɪʃən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a talk that explains something to an audience","vi":"bài thuyết trình; bài phát biểu"},{"pos":"n.","en":"the way something is arranged, shown, or expressed","vi":"cách trình bày; hình thức thể hiện"},{"pos":"n.","en":"the formal act of giving something to someone","vi":"sự trao tặng; sự biếu tặng"}],"examples":[{"en":"I practised my presentation in front of my sister.","vi":"Tôi đã luyện tập bài thuyết trình của mình trước mặt chị gái.","audioKind":"ex"},{"en":"Giving a group presentation allows students to develop communication skills and learn how to divide responsibilities.","vi":"Việc thực hiện bài thuyết trình nhóm giúp học sinh phát triển kỹ năng giao tiếp và học cách phân chia trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"give a presentation","vi":"thực hiện bài thuyết trình"},{"en":"oral presentation","vi":"bài thuyết trình miệng"},{"en":"food presentation","vi":"cách trình bày món ăn"},{"en":"award presentation","vi":"lễ trao giải"}],"wordFamily":["present (v.)","presenter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thuyết trình dùng give a presentation; chú ý trọng âm của từ present khi làm động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preposition', 'en-b1-4', 'preposition', '/ˌprepəˈzɪʃən/', 'B1', 'giới từ', 'n.', 'prepositional (adj.)', NULL, 'Theo sau giới từ thường là danh từ, đại từ hoặc danh động từ.', 'Our teacher used a toy rabbit to explain each preposition.', NULL, 'Giáo viên của chúng tôi đã dùng một chú thỏ đồ chơi để giải thích từng giới từ.', '{"wordId":"preposition","ukIpa":"/ˌprepəˈzɪʃən/","usIpa":"/ˌprepəˈzɪʃən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a word showing relationships, such as location, direction, or time","vi":"giới từ"}],"examples":[{"en":"Our teacher used a toy rabbit to explain each preposition.","vi":"Giáo viên của chúng tôi đã dùng một chú thỏ đồ chơi để giải thích từng giới từ.","audioKind":"ex"},{"en":"Choosing the correct preposition helps language learners express relationships between ideas more precisely in academic writing.","vi":"Việc lựa chọn đúng giới từ giúp người học ngôn ngữ diễn đạt mối quan hệ giữa các ý tưởng một cách chính xác hơn trong văn viết học thuật.","audioKind":"ex2"}],"collocations":[{"en":"a preposition of place","vi":"giới từ chỉ địa điểm"},{"en":"a preposition of time","vi":"giới từ chỉ thời gian"},{"en":"prepositional phrase","vi":"cụm giới từ"}],"wordFamily":["prepositional (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Theo sau giới từ thường là danh từ, đại từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_revision', 'en-b1-4', 'revision', '/rɪˈvɪʒən/', 'B1', 'sự ôn tập; sự học tập lại; sự sửa đổi; sự chỉnh sửa', 'n.', 'revise (v.), revised (adj.)', NULL, 'Nghĩa revision chủ yếu được dùng trong tiếng Anh-Anh; tiếng Anh-Mỹ thường dùng review.', 'I do my revision at the kitchen table.', NULL, 'Tôi làm bài ôn tập ở chiếc bàn trong bếp.', '{"wordId":"revision","ukIpa":"/rɪˈvɪʒən/","usIpa":"/rɪˈvɪʒən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"Studying material again to prepare for an examination","vi":"sự ôn tập; sự học tập lại"},{"pos":"n.","en":"The process or result of changing something to improve it","vi":"sự sửa đổi; sự chỉnh sửa"}],"examples":[{"en":"I do my revision at the kitchen table.","vi":"Tôi làm bài ôn tập ở chiếc bàn trong bếp.","audioKind":"ex"},{"en":"Regular revision helps students retain knowledge more effectively than studying intensively just before an examination.","vi":"Việc ôn tập thường xuyên giúp học sinh ghi nhớ kiến thức hiệu quả hơn so với việc học nhồi nhét ngay trước kỳ thi.","audioKind":"ex2"}],"collocations":[{"en":"do revision","vi":"ôn tập"},{"en":"revision timetable","vi":"lịch ôn tập"},{"en":"major revision","vi":"sự sửa đổi lớn"}],"wordFamily":["revise (v.)","revised (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa revision chủ yếu được dùng trong tiếng Anh-Anh; tiếng Anh-Mỹ thường dùng review.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_atlas', 'en-b1-4', 'atlas', '/ˈætləs/', 'B1', 'tập bản đồ', 'n.', NULL, NULL, 'atlas là thành phẩm sách bản đồ; số nhiều là atlases.', 'We opened the atlas to find a mountain range.', NULL, 'Chúng tôi mở tập bản đồ ra để tìm một dãy núi.', '{"wordId":"atlas","ukIpa":"/ˈætləs/","usIpa":"/ˈætləs/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A book containing maps of the world or particular regions.","vi":"tập bản đồ"}],"examples":[{"en":"We opened the atlas to find a mountain range.","vi":"Chúng tôi mở tập bản đồ ra để tìm một dãy núi.","audioKind":"ex"},{"en":"Although digital maps are convenient, a printed atlas helps students compare geographical patterns across entire continents.","vi":"Mặc dù bản đồ điện tử rất tiện lợi, tập bản đồ in giấy vẫn giúp học sinh so sánh các đặc điểm phân bố địa lý trên toàn bộ các châu lục.","audioKind":"ex2"}],"collocations":[{"en":"world atlas","vi":"tập bản đồ thế giới"},{"en":"historical atlas","vi":"tập bản đồ lịch sử"},{"en":"road atlas","vi":"tập bản đồ giao thông"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"atlas là thành phẩm sách bản đồ; số nhiều là atlases.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_translation', 'en-b1-4', 'translation', '/trænzˈleɪʃən/', 'B1', 'sự dịch thuật; quá trình dịch; bản dịch; bài dịch', 'n.', 'translate (v.), translator (n.), translatable (adj.)', NULL, 'Dịch sang ngôn ngữ nào dùng into; dịch từ ngôn ngữ nào dùng from.', 'This translation of the story is easy to understand.', NULL, 'Bản dịch của câu chuyện này rất dễ hiểu.', '{"wordId":"translation","ukIpa":"/trænzˈleɪʃən/","usIpa":"/trænzˈleɪʃən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"The process of expressing meaning in another language.","vi":"sự dịch thuật; quá trình dịch"},{"pos":"n.","en":"A spoken or written version in another language.","vi":"bản dịch; bài dịch"}],"examples":[{"en":"This translation of the story is easy to understand.","vi":"Bản dịch của câu chuyện này rất dễ hiểu.","audioKind":"ex"},{"en":"Accurate translation allows researchers from different countries to share findings and collaborate more effectively.","vi":"Bản dịch chính xác giúp các nhà nghiên cứu từ các quốc gia khác nhau chia sẻ phát hiện và hợp tác hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"accurate translation","vi":"bản dịch chính xác"},{"en":"machine translation","vi":"dịch máy"},{"en":"literal translation","vi":"dịch sát nghĩa"},{"en":"translation into English","vi":"bản dịch sang tiếng Anh"}],"wordFamily":["translate (v.)","translator (n.)","translatable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dịch sang ngôn ngữ nào dùng into; dịch từ ngôn ngữ nào dùng from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assignment', 'en-b1-4', 'assignment', '/əˈsaɪnmənt/', 'B1', 'bài tập; nhiệm vụ; sự phân công; sự giao việc', 'n.', 'assign (v.), assigned (adj.)', 'Đồng nghĩa: task', 'Phân biệt: assignment dùng cho công việc, bài tập cụ thể và đếm được; homework thường không đếm được.', 'I finished my science assignment before dinner last night.', NULL, 'Tối qua tôi đã làm xong bài tập môn khoa học trước bữa tối.', '{"wordId":"assignment","ukIpa":"/əˈsaɪnmənt/","usIpa":"/əˈsaɪnmənt/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A piece of work someone is required to complete.","vi":"bài tập; nhiệm vụ"},{"pos":"n.","en":"The act of giving someone a task, role, or place.","vi":"sự phân công; sự giao việc"}],"examples":[{"en":"I finished my science assignment before dinner last night.","vi":"Tối qua tôi đã làm xong bài tập môn khoa học trước bữa tối.","audioKind":"ex"},{"en":"A group assignment can help students develop communication skills and learn to share responsibility.","vi":"Làm bài tập nhóm có thể giúp học sinh phát triển kỹ năng giao tiếp và học cách cùng nhau gánh vác trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"complete an assignment","vi":"hoàn thành bài tập"},{"en":"submit an assignment","vi":"nộp bài tập"},{"en":"on assignment","vi":"làm nhiệm vụ; đi công tác"},{"en":"assignment of duties","vi":"sự phân công nhiệm vụ"}],"wordFamily":["assign (v.)","assigned (adj.)"],"synonyms":["task"],"antonyms":[],"tipVi":"Phân biệt: assignment dùng cho công việc, bài tập cụ thể và đếm được; homework thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vowel', 'en-b1-4', 'vowel', '/ˈvaʊəl/', 'B1', 'nguyên âm; chữ cái nguyên âm', 'n.', NULL, 'Trái nghĩa: consonant', 'Việc chọn a hay an phụ thuộc vào âm đầu tiên của từ theo sau có phải là nguyên âm hay không, chứ không dựa vào mặt chữ cái.', 'Our teacher stretched the vowel sound as we listened.', NULL, 'Giáo viên kéo dài âm nguyên âm để chúng tôi cùng lắng nghe.', '{"wordId":"vowel","ukIpa":"/ˈvaʊəl/","usIpa":"/ˈvaʊəl/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"An unrestricted speech sound, or a letter representing such a sound.","vi":"nguyên âm; chữ cái nguyên âm"}],"examples":[{"en":"Our teacher stretched the vowel sound as we listened.","vi":"Giáo viên kéo dài âm nguyên âm để chúng tôi cùng lắng nghe.","audioKind":"ex"},{"en":"Recognising differences between vowel sounds can help language learners understand unfamiliar accents and communicate more clearly.","vi":"Việc nhận biết sự khác biệt giữa các âm nguyên âm giúp người học ngoại ngữ hiểu được các ọng địa phương lạ và giao tiếp rõ ràng hơn.","audioKind":"ex2"}],"collocations":[{"en":"vowel sound","vi":"âm nguyên âm"},{"en":"long vowel","vi":"nguyên âm dài"},{"en":"short vowel","vi":"nguyên âm ngắn"}],"wordFamily":[],"synonyms":[],"antonyms":["consonant"],"tipVi":"Việc chọn a hay an phụ thuộc vào âm đầu tiên của từ theo sau có phải là nguyên âm hay không, chứ không dựa vào mặt chữ cái.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_definition', 'en-b1-4', 'definition', '/ˌdefɪˈnɪʃən/', 'B1', 'định nghĩa; sự giải thích nghĩa; độ nét; độ phân giải', 'n.', 'define (v.), definable (adj.), undefined (adj.)', NULL, 'definition of dẫn đến khái niệm được định nghĩa; độ nét cao thường được viết tắt là HD.', 'Could you give me a simple definition of gravity?', NULL, 'Bạn có thể cho tôi một định nghĩa đơn giản về trọng lực không?', '{"wordId":"definition","ukIpa":"/ˌdefɪˈnɪʃən/","usIpa":"/ˌdefɪˈnɪʃən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"A statement explaining exactly what a word or concept means","vi":"định nghĩa; sự giải thích nghĩa"},{"pos":"n.","en":"How clearly the details of an image or sound appear","vi":"độ nét; độ phân giải"}],"examples":[{"en":"Could you give me a simple definition of gravity?","vi":"Bạn có thể cho tôi một định nghĩa đơn giản về trọng lực không?","audioKind":"ex"},{"en":"A broader definition of health includes emotional wellbeing and social relationships, not merely the absence of physical illness.","vi":"Một định nghĩa rộng hơn về sức khỏe bao gồm sự ổn định cảm xúc và các mối quan hệ xã hội, chứ không chỉ đơn thuần là việc không có bệnh tật thể xác.","audioKind":"ex2"}],"collocations":[{"en":"a clear definition","vi":"một định nghĩa rõ ràng"},{"en":"by definition","vi":"theo định nghĩa"},{"en":"high definition","vi":"độ nét cao"},{"en":"a broad definition","vi":"một định nghĩa mang tính bao quát"}],"wordFamily":["define (v.)","definable (adj.)","undefined (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"definition of dẫn đến khái niệm được định nghĩa; độ nét cao thường được viết tắt là HD.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quote', 'en-b1-4', 'quote', '/kwoʊt/', 'B1', 'trích dẫn; báo giá; đoạn trích; giá báo', 'v.', 'quotation (n.), quotable (adj.), misquote (v.)', 'Đồng nghĩa: cite', 'Quote dùng để trích dẫn nguyên văn; paraphrase dùng từ ngữ của riêng mình để diễn giải lại.', 'My sister loves to quote lines from old films.', NULL, 'Chị tôi rất thích trích dẫn các câu thoại từ phim cũ.', '{"wordId":"quote","ukIpa":"/kwəʊt/","usIpa":"/kwoʊt/","cefr":"B1","topic":"education","senses":[{"pos":"v.","en":"To repeat someone''s exact words in speech or writing.","vi":"trích dẫn"},{"pos":"v.","en":"To state the price you will charge for something.","vi":"báo giá"},{"pos":"n.","en":"Repeated words from a source, or a stated price.","vi":"đoạn trích; giá báo"}],"examples":[{"en":"My sister loves to quote lines from old films.","vi":"Chị tôi rất thích trích dẫn các câu thoại từ phim cũ.","audioKind":"ex"},{"en":"Students should quote reliable sources accurately and explain how the evidence supports their arguments in academic essays.","vi":"Học sinh nên trích dẫn các nguồn tin cậy một cách chính xác và giải thích cách bằng chứng hỗ trợ cho lập luận của mình trong các bài luận học thuật.","audioKind":"ex2"}],"collocations":[{"en":"quote a source","vi":"trích dẫn nguồn"},{"en":"quote someone a price","vi":"báo giá cho ai đó"},{"en":"a direct quote","vi":"một câu trích dẫn trực tiếp"},{"en":"get a quote","vi":"nhận báo giá"}],"wordFamily":["quotation (n.)","quotable (adj.)","misquote (v.)"],"synonyms":["cite"],"antonyms":[],"tipVi":"Quote dùng để trích dẫn nguyên văn; paraphrase dùng từ ngữ của riêng mình để diễn giải lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quotation', 'en-b1-4', 'quotation', '/kwoʊˈteɪʃən/', 'B1', 'lời trích dẫn; đoạn trích; bảng báo giá; giá ước tính', 'n.', 'quote (v.), quote (n.)', NULL, 'Lời trích dẫn từ ai đó hoặc tác phẩm dùng giới từ from; báo giá thường đi với for.', 'She opened her speech with a quotation from a poem.', NULL, 'Cô ấy mở đầu bài phát biểu của mình bằng một câu thơ trích dẫn.', '{"wordId":"quotation","ukIpa":"/kwəʊˈteɪʃən/","usIpa":"/kwoʊˈteɪʃən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"words repeated exactly from another person or source","vi":"lời trích dẫn; đoạn trích"},{"pos":"n.","en":"a statement of the expected price of goods or services","vi":"bảng báo giá; giá ước tính"}],"examples":[{"en":"She opened her speech with a quotation from a poem.","vi":"Cô ấy mở đầu bài phát biểu của mình bằng một câu thơ trích dẫn.","audioKind":"ex"},{"en":"Before selecting a contractor, local authorities should obtain a detailed quotation for the proposed construction work.","vi":"Trước khi lựa chọn nhà thầu, chính quyền địa phương nên lấy một bản báo giá chi tiết cho công việc xây dựng đề xuất.","audioKind":"ex2"}],"collocations":[{"en":"a quotation from","vi":"lời trích dẫn từ"},{"en":"quotation marks","vi":"dấu ngoặc kép"},{"en":"request a quotation","vi":"yêu cầu báo giá"},{"en":"provide a quotation","vi":"cung cấp báo giá"}],"wordFamily":["quote (v.)","quote (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Lời trích dẫn từ ai đó hoặc tác phẩm dùng giới từ from; báo giá thường đi với for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adverb', 'en-b1-4', 'adverb', '/ˈædvɜːrb/', 'B1', 'phó từ; trạng từ', 'n.', 'adverbial (adj.), adverbially (adv.)', NULL, 'Adverb là danh từ; tính từ mang nghĩa "thuộc về trạng từ" là adverbial.', 'Our teacher asked us to circle every adverb.', NULL, 'Giáo viên yêu cầu chúng tôi khoanh tròn mọi trạng từ.', '{"wordId":"adverb","ukIpa":"/ˈædvɜːb/","usIpa":"/ˈædvɜːrb/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a word modifying a verb, adjective, adverb, or whole sentence","vi":"phó từ; trạng từ"}],"examples":[{"en":"Our teacher asked us to circle every adverb.","vi":"Giáo viên yêu cầu chúng tôi khoanh tròn mọi trạng từ.","audioKind":"ex"},{"en":"Understanding how an adverb changes emphasis can help language learners express their opinions more precisely.","vi":"Hiểu được cách trạng từ thay đổi sắc thái nhấn mạnh có thể giúp người học ngôn ngữ bày tỏ quan điểm chính xác hơn.","audioKind":"ex2"}],"collocations":[{"en":"adverb of frequency","vi":"trạng từ chỉ tần suất"},{"en":"adverb of manner","vi":"trạng từ chỉ thể cách"},{"en":"adverb placement","vi":"vị trí của trạng từ"}],"wordFamily":["adverbial (adj.)","adverbially (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Adverb là danh từ; tính từ mang nghĩa \"thuộc về trạng từ\" là adverbial.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_session', 'en-b1-4', 'session', '/ˈseʃən/', 'B1', 'buổi; phiên họp hoặc khoảng thời gian dành cho một hoạt động cụ thể; kỳ họp chính thức của cơ quan nhà nước hoặc tòa án', 'n.', NULL, NULL, 'Từ session nhấn mạnh khoảng thời gian diễn ra một hoạt động; từ semester thường chỉ học kỳ trong trường học.', 'Our first swimming session starts early tomorrow morning.', NULL, 'Buổi học bơi đầu tiên của chúng tôi bắt đầu vào sáng sớm mai.', '{"wordId":"session","ukIpa":"/ˈseʃən/","usIpa":"/ˈseʃən/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"a period spent doing a particular activity","vi":"buổi; phiên họp hoặc khoảng thời gian dành cho một hoạt động cụ thể"},{"pos":"n.","en":"a formal meeting or period when an official body meets","vi":"kỳ họp chính thức của cơ quan nhà nước hoặc tòa án"}],"examples":[{"en":"Our first swimming session starts early tomorrow morning.","vi":"Buổi học bơi đầu tiên của chúng tôi bắt đầu vào sáng sớm mai.","audioKind":"ex"},{"en":"Regular revision sessions help students retain information more effectively than studying intensively just before examinations.","vi":"Các buổi ôn tập định kỳ giúp học sinh ghi nhớ kiến thức hiệu quả hơn so với việc học dồn dập ngay trước kỳ thi.","audioKind":"ex2"}],"collocations":[{"en":"a training session","vi":"buổi huấn luyện"},{"en":"a revision session","vi":"buổi ôn tập"},{"en":"a question-and-answer session","vi":"phiên hỏi đáp"},{"en":"in session","vi":"đang họp; đang mở phiên tòa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ session nhấn mạnh khoảng thời gian diễn ra một hoạt động; từ semester thường chỉ học kỳ trong trường học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_geometry', 'en-b1-4', 'geometry', '/dʒiˈɑːmətri/', 'B1', 'hình học', 'n.', 'geometric (adj.), geometrical (adj.), geometrically (adv.)', NULL, 'Đây là tên môn học và là danh từ không đếm được; thông thường không cần dùng mạo từ.', 'We used colourful wooden shapes in geometry class today.', NULL, 'Chúng tôi đã sử dụng các hình khối bằng gỗ đầy màu sắc trong lớp học hình học ngày hôm nay.', '{"wordId":"geometry","ukIpa":"/dʒiˈɒmətri/","usIpa":"/dʒiˈɑːmətri/","cefr":"B1","topic":"education","senses":[{"pos":"n.","en":"The study of shapes, angles, sizes, and spatial relationships.","vi":"hình học"}],"examples":[{"en":"We used colourful wooden shapes in geometry class today.","vi":"Chúng tôi đã sử dụng các hình khối bằng gỗ đầy màu sắc trong lớp học hình học ngày hôm nay.","audioKind":"ex"},{"en":"Learning geometry helps students develop spatial reasoning skills that are valuable in engineering and architecture.","vi":"Học hình học giúp học sinh phát triển kỹ năng tư duy không gian, vốn rất có giá trị trong ngành kỹ thuật và kiến trúc.","audioKind":"ex2"}],"collocations":[{"en":"plane geometry","vi":"hình học phẳng"},{"en":"solid geometry","vi":"hình học không gian"},{"en":"study geometry","vi":"học môn hình học"}],"wordFamily":["geometric (adj.)","geometrical (adj.)","geometrically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Đây là tên môn học và là danh từ không đếm được; thông thường không cần dùng mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_4_1', 'en-b1-4', 'Cách dùng “vowel” (n.) — nguyên âm; chữ cái nguyên âm', 'vowel sound  ·  long vowel  ·  short vowel', 'Việc chọn a hay an phụ thuộc vào âm đầu tiên của từ theo sau có phải là nguyên âm hay không, chứ không dựa vào mặt chữ cái.', 'Trái nghĩa: consonant', '[{"hanzi":"Our teacher stretched the vowel sound as we listened.","pinyin":"","meaning":"Giáo viên kéo dài âm nguyên âm để chúng tôi cùng lắng nghe."},{"hanzi":"Recognising differences between vowel sounds can help language learners understand unfamiliar accents and communicate more clearly.","pinyin":"","meaning":"Việc nhận biết sự khác biệt giữa các âm nguyên âm giúp người học ngoại ngữ hiểu được các ọng địa phương lạ và giao tiếp rõ ràng hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_4_2', 'en-b1-4', 'Cách dùng “session” (n.) — buổi; phiên họp hoặc khoảng thời gian dành cho một hoạt động cụ thể', 'a training session  ·  a revision session  ·  a question-and-answer session', 'Từ session nhấn mạnh khoảng thời gian diễn ra một hoạt động; từ semester thường chỉ học kỳ trong trường học.', NULL, '[{"hanzi":"Our first swimming session starts early tomorrow morning.","pinyin":"","meaning":"Buổi học bơi đầu tiên của chúng tôi bắt đầu vào sáng sớm mai."},{"hanzi":"Regular revision sessions help students retain information more effectively than studying intensively just before examinations.","pinyin":"","meaning":"Các buổi ôn tập định kỳ giúp học sinh ghi nhớ kiến thức hiệu quả hơn so với việc học dồn dập ngay trước kỳ thi."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_4_3', 'en-b1-4', 'Cách dùng “assignment” (n.) — bài tập; nhiệm vụ', 'complete an assignment  ·  submit an assignment  ·  on assignment', 'Phân biệt: assignment dùng cho công việc, bài tập cụ thể và đếm được; homework thường không đếm được.', 'Họ từ (Word Family): assign (v.), assigned (adj.) | Đồng nghĩa: task', '[{"hanzi":"I finished my science assignment before dinner last night.","pinyin":"","meaning":"Tối qua tôi đã làm xong bài tập môn khoa học trước bữa tối."},{"hanzi":"A group assignment can help students develop communication skills and learn to share responsibility.","pinyin":"","meaning":"Làm bài tập nhóm có thể giúp học sinh phát triển kỹ năng giao tiếp và học cách cùng nhau gánh vác trách nhiệm."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_4_4', 'en-b1-4', 'Cách dùng “failure” (n.) — sự thất bại; điều thất bại', 'end in failure  ·  power failure  ·  heart failure', 'Nói chung sự thất bại thường không đếm được; a failure có thể chỉ một sự việc thất bại cụ thể.', 'Họ từ (Word Family): fail (v.), failed (adj.), failing (n.) | Trái nghĩa: success', '[{"hanzi":"Despite her first failure, she tried baking bread again.","pinyin":"","meaning":"Mặc dù thất bại lần đầu, cô ấy vẫn thử nướng bánh mì lại một lần nữa."},{"hanzi":"Schools should treat failure as an opportunity for learning rather than as evidence of a student''s limited ability.","pinyin":"","meaning":"Các trường học nên coi thất bại là cơ hội học hỏi thay vì bằng chứng cho thấy năng lực hạn chế của học sinh."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
