INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_4_1_7', 'ten_b1_4_1', 'workshop', 'I made a clay bowl at a pottery workshop.', 'I made a clay bowl at a pottery workshop.', '/ˈwɝːkʃɑːp/', 'Tôi đã làm một chiếc bát đất sét tại một buổi hội thảo làm gốm.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_4_1_8', 'ten_b1_4_1', 'primary', 'Our primary concern is keeping the children safe.', 'Our primary concern is keeping the children safe.', '/ˈpraɪmeri/', 'Mối quan tâm hàng đầu của chúng tôi là giữ an toàn cho trẻ em.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_4_1_1', 'en-b1-4', 'ten_b1_4_1', 'listening', 'listening', 'This swimming class is suitable for intermediate learners.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã luyện tập bài thuyết trình của mình trước mặt chị gái.","Xin hãy đọc to công thức nấu ăn trong lúc tôi trộn nguyên liệu.","Cô ấy mở đầu bài phát biểu của mình bằng một câu thơ trích dẫn.","Lớp học bơi này phù hợp với các học viên ở trình độ trung cấp."]'::jsonb, 3, 'This swimming class is suitable for intermediate learners. → Lớp học bơi này phù hợp với các học viên ở trình độ trung cấp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_4_1_2', 'en-b1-4', 'ten_b1_4_1', 'listening', 'listening', 'Subtract the delivery charge to find the original price.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Giáo viên kéo dài âm nguyên âm để chúng tôi cùng lắng nghe.","Tôi đã làm một chiếc bát đất sét tại một buổi hội thảo làm gốm.","Trừ phí giao hàng để tìm ra giá gốc.","Bản dịch của câu chuyện này rất dễ hiểu."]'::jsonb, 2, 'Subtract the delivery charge to find the original price. → Trừ phí giao hàng để tìm ra giá gốc.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_4_1_3', 'en-b1-4', 'ten_b1_4_1', 'listening', 'listening', 'Please read the recipe aloud while I mix.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin hãy đọc to công thức nấu ăn trong lúc tôi trộn nguyên liệu.","Giáo viên kéo dài âm nguyên âm để chúng tôi cùng lắng nghe.","Trừ phí giao hàng để tìm ra giá gốc.","Chúng tôi mở tập bản đồ ra để tìm một dãy núi."]'::jsonb, 0, 'Please read the recipe aloud while I mix. → Xin hãy đọc to công thức nấu ăn trong lúc tôi trộn nguyên liệu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_4_2', 'en-b1-4', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_4_2_1', 'ten_b1_4_2', 'intermediate', 'Intermediate language courses should balance grammar instruction with opportunities for meaningful communication outside the classroom.', 'Intermediate language courses should balance grammar instruction with opportunities for meaningful communication outside the classroom.', '/ˌɪntərˈmiːdiət/', 'Các khóa học ngôn ngữ trung cấp nên cân bằng giữa việc giảng dạy ngữ pháp và cơ hội giao tiếp có ý nghĩa ngoài lớp học.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_4_2_2', 'ten_b1_4_2', 'subtract', 'Researchers subtract production costs from total revenue to calculate the profit generated by each farming method.', 'Researchers subtract production costs from total revenue to calculate the profit generated by each farming method.', '/səbˈtrækt/', 'Các nhà nghiên cứu trừ chi phí sản xuất khỏi tổng doanh thu để tính toán lợi nhuận do từng phương thức canh tác tạo ra.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_4_2_3', 'ten_b1_4_2', 'aloud', 'Reading stories aloud can help young children develop vocabulary and strengthen their understanding of spoken language.', 'Reading stories aloud can help young children develop vocabulary and strengthen their understanding of spoken language.', '/əˈlaʊd/', 'Đọc to các câu chuyện có thể giúp trẻ nhỏ phát triển vốn từ vựng và củng cố sự hiểu biết về ngôn ngữ nói.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_4_2_4', 'ten_b1_4_2', 'failure', 'Schools should treat failure as an opportunity for learning rather than as evidence of a student''s limited ability.', 'Schools should treat failure as an opportunity for learning rather than as evidence of a student''s limited ability.', '/ˈfeɪljər/', 'Các trường học nên coi thất bại là cơ hội học hỏi thay vì bằng chứng cho thấy năng lực hạn chế của học sinh.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_4_2_5', 'ten_b1_4_2', 'refer', 'Doctors may refer patients to specialists when their symptoms require more detailed investigation or treatment.', 'Doctors may refer patients to specialists when their symptoms require more detailed investigation or treatment.', '/rɪˈfɝː/', 'Các bác sĩ có thể chuyển bệnh nhân đến gặp bác sĩ chuyên khoa khi các triệu chứng của họ đòi hỏi phải thăm khám hoặc điều trị chi tiết hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_4_2_6', 'ten_b1_4_2', 'secondary', 'Access to quality secondary education can improve employment prospects for young people in rural communities.', 'Access to quality secondary education can improve employment prospects for young people in rural communities.', '/ˈsekənderi/', 'Việc tiếp cận giáo dục trung học chất lượng cao có thể cải thiện triển vọng việc làm cho giới trẻ ở các cộng đồng nông thôn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_4_2_1', 'en-b1-4', 'ten_b1_4_2', 'listening', 'listening', 'Intermediate language courses should balance grammar instruction with opportunities for meaningful communication outside the classroom.', NULL, 'Trong câu vừa nghe, từ “intermediate” mang nghĩa nào sau đây?', '["hiệu suất; thành tích; hiệu năng","sống; chưa nấu chín","hiếm khi; ít khi","trung cấp; ở giữa"]'::jsonb, 3, '“intermediate” (/ˌɪntərˈmiːdiət/): trung cấp; ở giữa. Câu đầy đủ: Intermediate language courses should balance grammar instruction with opportunities for meaningful communication outside the classroom.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_4_2_2', 'en-b1-4', 'ten_b1_4_2', 'listening', 'listening', 'Researchers subtract production costs from total revenue to calculate the profit generated by each farming method.', NULL, 'Trong câu vừa nghe, từ “subtract” mang nghĩa nào sau đây?', '["bài thuyết trình; bài phát biểu","phong tục; tập quán; thói quen truyền thống","bị cấm; không được phép","trừ đi; khấu trừ"]'::jsonb, 3, '“subtract” (/səbˈtrækt/): trừ đi; khấu trừ. Câu đầy đủ: Researchers subtract production costs from total revenue to calculate the profit generated by each farming method.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
