INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_4_4', 'en-b1-4', NULL, 'comprehensive_test', 'listening', 'Despite her first failure, she tried baking bread again.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bản dịch của câu chuyện này rất dễ hiểu.","Tôi đã làm một chiếc bát đất sét tại một buổi hội thảo làm gốm.","Mặc dù thất bại lần đầu, cô ấy vẫn thử nướng bánh mì lại một lần nữa.","Chị tôi rất thích trích dẫn các câu thoại từ phim cũ."]'::jsonb, 2, 'Despite her first failure, she tried baking bread again. → Mặc dù thất bại lần đầu, cô ấy vẫn thử nướng bánh mì lại một lần nữa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_4_5', 'en-b1-4', NULL, 'comprehensive_test', 'listening', 'refer', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc về kỹ thuật; mang tính chuyên môn","tuyệt vời; kỳ diệu; gây ấn tượng mạnh","nhắc đến; ám chỉ","cây lau nhà; giẻ lau nhà"]'::jsonb, 2, 'refer (/rɪˈfɝː/) → nhắc đến; ám chỉ; tra cứu; tham khảo; chuyển tuyến; giới thiệu', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_4_6', 'en-b1-4', NULL, 'comprehensive_test', 'listening', 'My sister starts secondary school after the summer holidays.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bản dịch của câu chuyện này rất dễ hiểu.","Em gái tôi bắt đầu vào học cấp hai sau kỳ nghỉ hè.","Vui lòng tham khảo bản đồ ở bên trong cuốn sách hướng dẫn của bạn.","Tôi làm bài ôn tập ở chiếc bàn trong bếp."]'::jsonb, 1, 'My sister starts secondary school after the summer holidays. → Em gái tôi bắt đầu vào học cấp hai sau kỳ nghỉ hè.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_4_7', 'en-b1-4', NULL, 'comprehensive_test', 'listening', 'workshop', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["buổi thảo luận thực tế; hội thảo","ghen tị; đố kỵ","sự quản lý; sự điều hành","hoạt động giải trí về đêm; đời sống về đêm"]'::jsonb, 0, 'workshop (/ˈwɝːkʃɑːp/) → buổi thảo luận thực tế; hội thảo; xưởng; xưởng làm việc', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
