INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_4_18', 'en-b1-4', NULL, 'comprehensive_test', 'reading', NULL, 'Intermediate language courses should balance grammar instruction with opportunities for meaningful communication outside the classroom.', 'Dựa vào câu trên, từ “intermediate” có nghĩa phù hợp nhất là gì?', '["hình tam giác","sự giúp đỡ; việc làm ơn","trung cấp; ở giữa","lễ; nghi lễ; nghi thức"]'::jsonb, 2, 'intermediate: trung cấp; ở giữa; người học trình độ trung cấp. Dịch cả câu: Các khóa học ngôn ngữ trung cấp nên cân bằng giữa việc giảng dạy ngữ pháp và cơ hội giao tiếp có ý nghĩa ngoài lớp học.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_4_19', 'en-b1-4', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers subtract production costs from total revenue to calculate the profit generated by each farming method.', 'Dựa vào câu trên, từ “subtract” có nghĩa phù hợp nhất là gì?', '["khăng khăng đòi; kiên quyết","trừ đi; khấu trừ","hai tuần; nửa tháng","tỷ lệ; tốc độ"]'::jsonb, 1, 'subtract: trừ đi; khấu trừ. Dịch cả câu: Các nhà nghiên cứu trừ chi phí sản xuất khỏi tổng doanh thu để tính toán lợi nhuận do từng phương thức canh tác tạo ra.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_4_20', 'en-b1-4', NULL, 'comprehensive_test', 'reading', NULL, 'Reading stories aloud can help young children develop vocabulary and strengthen their understanding of spoken language.', 'Dựa vào câu trên, từ “aloud” có nghĩa phù hợp nhất là gì?', '["vòi nước","hóa chất; chất hóa học","lớn tiếng; thành tiếng","đài tưởng niệm; công trình tưởng niệm"]'::jsonb, 2, 'aloud: lớn tiếng; thành tiếng. Dịch cả câu: Đọc to các câu chuyện có thể giúp trẻ nhỏ phát triển vốn từ vựng và củng cố sự hiểu biết về ngôn ngữ nói.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_4_21', 'en-b1-4', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should treat failure as an opportunity for learning rather than as evidence of a student''s limited ability.', 'Dựa vào câu trên, từ “failure” có nghĩa phù hợp nhất là gì?', '["món hời; hàng giá rẻ","sự thất bại; điều thất bại","tờ rơi; tờ quảng cáo","bị che khuất; ẩn giấu; khó nhận thấy"]'::jsonb, 1, 'failure: sự thất bại; điều thất bại; sự cố; sự suy giảm; việc không thực hiện; sự xao lãng. Dịch cả câu: Các trường học nên coi thất bại là cơ hội học hỏi thay vì bằng chứng cho thấy năng lực hạn chế của học sinh.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
