INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-5', 'en', 'Bài 5: Du lịch & Di chuyển (1) - CEFR B1', 'CEFR B1', 'B1 · Du lịch', '25 từ vựng Tiếng Anh CEFR B1 chủ đề du lịch & di chuyển kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3005, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hut', 'en-b1-5', 'hut', '/hʌt/', 'B1', 'lều; nhà tranh; chòi', 'n.', NULL, NULL, 'hut nhấn mạnh quy mô nhỏ và sự đơn sơ, thường không phải là nơi ở đầy đủ tiện nghi.', 'We sheltered from the rain in a wooden hut.', NULL, 'Chúng tôi đã trú mưa trong một ngôi nhà gỗ nhỏ.', '{"wordId":"hut","ukIpa":"/hʌt/","usIpa":"/hʌt/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A small, simple building, often made of wood or grass.","vi":"lều; nhà tranh; chòi"}],"examples":[{"en":"We sheltered from the rain in a wooden hut.","vi":"Chúng tôi đã trú mưa trong một ngôi nhà gỗ nhỏ.","audioKind":"ex"},{"en":"Mountain huts provide essential shelter for hikers, but their construction should minimise damage to fragile ecosystems.","vi":"Những căn lều trên núi cung cấp nơi trú ẩn thiết yếu cho người đi bộ đường dài, nhưng việc xây dựng chúng nên hạn chế tối đa tổn hại đến các hệ sinh thái mỏng manh.","audioKind":"ex2"}],"collocations":[{"en":"wooden hut","vi":"nhà gỗ"},{"en":"mountain hut","vi":"lều trên núi"},{"en":"thatched hut","vi":"nhà tranh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"hut nhấn mạnh quy mô nhỏ và sự đơn sơ, thường không phải là nơi ở đầy đủ tiện nghi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hostel', 'en-b1-5', 'hostel', '/ˈhɑːstəl/', 'B1', 'nhà nghỉ giá rẻ; ký túc xá cho khách du lịch; nhà tạm trú; nơi cung cấp chỗ ở tạm thời cho người cần hỗ trợ', 'n.', NULL, NULL, 'Từ hostel thường có phòng ngủ tập thể, trong khi hotel thường cung cấp phòng riêng biệt.', 'We shared a room with other travellers at the hostel.', NULL, 'Chúng tôi ở chung phòng với những du khách khác tại nhà nghỉ.', '{"wordId":"hostel","ukIpa":"/ˈhɒstəl/","usIpa":"/ˈhɑːstəl/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"An inexpensive place to stay, often with shared rooms.","vi":"nhà nghỉ giá rẻ; ký túc xá cho khách du lịch"},{"pos":"n.","en":"A place providing temporary accommodation for people needing support.","vi":"nhà tạm trú; nơi cung cấp chỗ ở tạm thời cho người cần hỗ trợ"}],"examples":[{"en":"We shared a room with other travellers at the hostel.","vi":"Chúng tôi ở chung phòng với những du khách khác tại nhà nghỉ.","audioKind":"ex"},{"en":"Youth hostels make international travel more affordable for students while encouraging interaction between people from different backgrounds.","vi":"Các nhà nghỉ thanh niên giúp việc du lịch quốc tế trở nên dễ chi trả hơn đối với học sinh, sinh viên đồng thời thúc đẩy sự giao lưu giữa những người đến từ các nền văn hóa khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"youth hostel","vi":"nhà nghỉ thanh niên"},{"en":"stay in a hostel","vi":"ở nhà nghỉ"},{"en":"hostel accommodation","vi":"dịch vụ lưu trú tại nhà nghỉ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ hostel thường có phòng ngủ tập thể, trong khi hotel thường cung cấp phòng riêng biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_port', 'en-b1-5', 'port', '/pɔːrt/', 'B1', 'cảng; thành phố cảng; cổng kết nối; giao diện; mạn trái (của tàu thủy hoặc máy bay)', 'n.', NULL, 'Đồng nghĩa: harbour', 'Khi port chỉ mạn trái, từ trái nghĩa của nó là starboard (mạn phải).', 'We watched fishing boats returning to the port.', NULL, 'Chúng tôi ngắm nhìn những chiếc thuyền đánh cá đang quay trở lại cảng.', '{"wordId":"port","ukIpa":"/pɔːt/","usIpa":"/pɔːrt/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A place where ships load, unload, or shelter.","vi":"cảng; thành phố cảng"},{"pos":"n.","en":"A physical connection point or virtual channel for computer communication.","vi":"cổng kết nối; giao diện"},{"pos":"n.","en":"The left side of a ship or aircraft, facing forward.","vi":"mạn trái (của tàu thủy hoặc máy bay)"}],"examples":[{"en":"We watched fishing boats returning to the port.","vi":"Chúng tôi ngắm nhìn những chiếc thuyền đánh cá đang quay trở lại cảng.","audioKind":"ex"},{"en":"Expanding the port could increase international trade, but it may also damage nearby marine habitats.","vi":"Việc mở rộng cảng có thể làm tăng thương mại quốc tế, nhưng nó cũng có thể phá hủy các môi trường sống dưới nước ở gần đó.","audioKind":"ex2"}],"collocations":[{"en":"a busy port","vi":"cảng bận rộn"},{"en":"a port city","vi":"thành phố cảng"},{"en":"a USB port","vi":"cổng USB"},{"en":"the port side","vi":"mạn trái"}],"wordFamily":[],"synonyms":["harbour"],"antonyms":[],"tipVi":"Khi port chỉ mạn trái, từ trái nghĩa của nó là starboard (mạn phải).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cab', 'en-b1-5', 'cab', '/kæb/', 'B1', 'xe taxi; khoang lái; buồng lái (của xe tải hoặc phương tiện)', 'n.', NULL, 'Đồng nghĩa: taxi', 'Từ này đồng nghĩa với taxi khi chỉ xe chở khách; ngoài ra còn có thể chỉ buồng lái của xe tải hoặc phương tiện lớn.', 'We shared a cab home after the concert.', NULL, 'Chúng tôi chung tiền đi một chiếc taxi về nhà sau buổi hòa nhạc.', '{"wordId":"cab","ukIpa":"/kæb/","usIpa":"/kæb/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A car with a driver whom you pay for transport.","vi":"xe taxi"},{"pos":"n.","en":"The enclosed part of a vehicle where the driver sits.","vi":"khoang lái; buồng lái (của xe tải hoặc phương tiện)"}],"examples":[{"en":"We shared a cab home after the concert.","vi":"Chúng tôi chung tiền đi một chiếc taxi về nhà sau buổi hòa nhạc.","audioKind":"ex"},{"en":"Affordable night buses could reduce reliance on cabs among workers whose shifts end after midnight.","vi":"Xe buýt đêm giá rẻ có thể giúp giảm sự phụ thuộc vào taxi đối với những công nhân có ca làm việc kết thúc sau nửa đêm.","audioKind":"ex2"}],"collocations":[{"en":"hail a cab","vi":"vẫy gọi xe taxi"},{"en":"take a cab","vi":"đi xe taxi"},{"en":"cab fare","vi":"tiền cước taxi"},{"en":"a truck cab","vi":"khoang lái xe tải"}],"wordFamily":[],"synonyms":["taxi"],"antonyms":[],"tipVi":"Từ này đồng nghĩa với taxi khi chỉ xe chở khách; ngoài ra còn có thể chỉ buồng lái của xe tải hoặc phương tiện lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vehicle', 'en-b1-5', 'vehicle', '/ˈviːəkl/', 'B1', 'phương tiện giao thông; xe cộ; phương tiện; công cụ (để truyền đạt ý tưởng hoặc đạt mục đích)', 'n.', 'vehicular (adj.)', NULL, 'Khi chỉ phương tiện giao thông thì đây là danh từ đếm được, không chỉ riêng ô tô.', 'We left our vehicle outside the small mountain hotel.', NULL, 'Chúng tôi để chiếc xe của mình ở bên ngoài khách sạn nhỏ trên núi.', '{"wordId":"vehicle","ukIpa":"/ˈviːəkl/","usIpa":"/ˈviːəkl/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A machine used to transport people or goods.","vi":"phương tiện giao thông; xe cộ"},{"pos":"n.","en":"Something used to communicate ideas or achieve a purpose.","vi":"phương tiện; công cụ (để truyền đạt ý tưởng hoặc đạt mục đích)"}],"examples":[{"en":"We left our vehicle outside the small mountain hotel.","vi":"Chúng tôi để chiếc xe của mình ở bên ngoài khách sạn nhỏ trên núi.","audioKind":"ex"},{"en":"Electric vehicles can reduce urban air pollution, especially when their electricity comes from renewable sources.","vi":"Xe điện có thể giúp giảm ô nhiễm không khí đô thị, đặc biệt là khi nguồn điện được tạo ra từ các nguồn năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"electric vehicle","vi":"xe điện"},{"en":"commercial vehicle","vi":"xe thương mại"},{"en":"a vehicle for change","vi":"công cụ để tạo ra sự thay đổi"}],"wordFamily":["vehicular (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ phương tiện giao thông thì đây là danh từ đếm được, không chỉ riêng ô tô.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_destination', 'en-b1-5', 'destination', '/ˌdestɪˈneɪʃən/', 'B1', 'đích đến; điểm đến', 'n.', NULL, NULL, 'Cụm từ reach a destination không cần dùng giới từ to; còn arrive at đi với điểm đến.', 'We finally reached our destination just before sunset.', NULL, 'Cuối cùng chúng tôi cũng đến được điểm đến của mình ngay trước khi mặt trời lặn.', '{"wordId":"destination","ukIpa":"/ˌdestɪˈneɪʃən/","usIpa":"/ˌdestɪˈneɪʃən/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"the place someone or something is travelling to","vi":"đích đến; điểm đến"}],"examples":[{"en":"We finally reached our destination just before sunset.","vi":"Cuối cùng chúng tôi cũng đến được điểm đến của mình ngay trước khi mặt trời lặn.","audioKind":"ex"},{"en":"Popular tourist destinations must balance economic benefits with the need to protect local communities and natural environments.","vi":"Các điểm đến du lịch nổi tiếng phải cân bằng giữa lợi ích kinh tế với nhu cầu bảo vệ cộng đồng địa phương và môi trường tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"reach your destination","vi":"đến nơi"},{"en":"tourist destination","vi":"điểm đến du lịch"},{"en":"final destination","vi":"điểm đến cuối cùng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ reach a destination không cần dùng giới từ to; còn arrive at đi với điểm đến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lighthouse', 'en-b1-5', 'lighthouse', '/ˈlaɪthaʊs/', 'B1', 'đèn biển; ngọn hải đăng', 'n.', NULL, NULL, 'Là danh từ đếm được, dạng số nhiều thêm s thành lighthouses.', 'The lighthouse beam swept across the dark sea.', NULL, 'Luồng sáng từ ngọn hải đăng quét qua vùng biển tối tăm.', '{"wordId":"lighthouse","ukIpa":"/ˈlaɪthaʊs/","usIpa":"/ˈlaɪthaʊs/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A coastal tower with a powerful light that guides ships.","vi":"đèn biển; ngọn hải đăng"}],"examples":[{"en":"The lighthouse beam swept across the dark sea.","vi":"Luồng sáng từ ngọn hải đăng quét qua vùng biển tối tăm.","audioKind":"ex"},{"en":"Although modern navigation relies on satellites, lighthouses remain valuable landmarks along dangerous stretches of coastline.","vi":"Mặc dù hàng hải hiện đại phụ thuộc vào vệ tinh, ngọn hải đăng vẫn là những mốc định hướng quan trọng dọc theo các vùng bờ biển nguy hiểm.","audioKind":"ex2"}],"collocations":[{"en":"lighthouse keeper","vi":"người gác hải đăng"},{"en":"lighthouse beam","vi":"luồng sáng hải đăng"},{"en":"historic lighthouse","vi":"ngọn hải đăng lịch sử"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được, dạng số nhiều thêm s thành lighthouses.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tyre', 'en-b1-5', 'tyre', '/ˈtaɪr/', 'B1', 'lốp xe; vỏ xe', 'n.', NULL, NULL, 'Tyre là cách viết theo tiếng Anh-Anh, còn tiếng Anh-Mỹ viết là tire.', 'We stopped beside the road to change a flat tyre.', NULL, 'Chúng tôi dừng xe bên đường để thay chiếc lốp bị xịt.', '{"wordId":"tyre","ukIpa":"/ˈtaɪə/","usIpa":"/ˈtaɪr/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A rubber covering around a wheel that touches the road.","vi":"lốp xe; vỏ xe"}],"examples":[{"en":"We stopped beside the road to change a flat tyre.","vi":"Chúng tôi dừng xe bên đường để thay chiếc lốp bị xịt.","audioKind":"ex"},{"en":"Recycling used tyres can reduce landfill waste and provide materials for safer playground surfaces.","vi":"Việc tái chế lốp xe cũ có thể giảm lượng rác thải chôn lấp và cung cấp vật liệu cho bề mặt sân chơi an toàn hơn.","audioKind":"ex2"}],"collocations":[{"en":"a flat tyre","vi":"lốp xe bị thủng"},{"en":"a spare tyre","vi":"lốp dự phòng"},{"en":"tyre pressure","vi":"áp suất lốp"},{"en":"change a tyre","vi":"thay lốp xe"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tyre là cách viết theo tiếng Anh-Anh, còn tiếng Anh-Mỹ viết là tire.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attraction', 'en-b1-5', 'attraction', '/əˈtrækʃən/', 'B1', 'địa điểm thu hút; danh lam thắng cảnh; sức hút; sự hấp dẫn', 'n.', 'attract (v.), attractive (adj.), attractively (adv.), attractiveness (n.)', 'Đồng nghĩa: appeal, draw · Trái nghĩa: repulsion', 'Khi chỉ địa điểm tham quan thì đếm được; khi chỉ sức hút thì thường không đếm được.', 'The old castle is the town''s most popular attraction.', NULL, 'Lâu đài cổ là điểm tham quan nổi tiếng nhất của thị trấn.', '{"wordId":"attraction","ukIpa":"/əˈtrækʃən/","usIpa":"/əˈtrækʃən/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A place or feature that people want to visit or experience.","vi":"địa điểm thu hút; danh lam thắng cảnh"},{"pos":"n.","en":"The power to interest someone or draw them towards something.","vi":"sức hút; sự hấp dẫn"}],"examples":[{"en":"The old castle is the town''s most popular attraction.","vi":"Lâu đài cổ là điểm tham quan nổi tiếng nhất của thị trấn.","audioKind":"ex"},{"en":"Although tourism creates jobs, overcrowding at major attractions can damage historic buildings and disrupt local life.","vi":"Mặc dù ngành du lịch tạo ra việc làm, tình trạng quá tải tại các điểm du lịch lớn có thể làm hư hại các di tích lịch sử và làm xáo trộn cuộc sống địa phương.","audioKind":"ex2"}],"collocations":[{"en":"tourist attraction","vi":"điểm du lịch"},{"en":"main attraction","vi":"điểm thu hút chính"},{"en":"mutual attraction","vi":"sự hấp dẫn lẫn nhau"},{"en":"gravitational attraction","vi":"lực hút hấp dẫn"}],"wordFamily":["attract (v.)","attractive (adj.)","attractively (adv.)","attractiveness (n.)"],"synonyms":["appeal","draw"],"antonyms":["repulsion"],"tipVi":"Khi chỉ địa điểm tham quan thì đếm được; khi chỉ sức hút thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_depart', 'en-b1-5', 'depart', '/dɪˈpɑːrt/', 'B1', 'rời đi; khởi hành; khác biệt; đi chệch (khỏi quy tắc)', 'v.', 'departure (n.)', 'Đồng nghĩa: leave · Trái nghĩa: arrive', 'Depart from đi với điểm xuất phát, depart for đi với điểm đến.', 'Our train departs at dawn, so pack your bag tonight.', NULL, 'Tàu của chúng tôi khởi hành vào lúc sáng sớm, vì vậy hãy thu dọn hành lý tối nay nhé.', '{"wordId":"depart","ukIpa":"/dɪˈpɑːt/","usIpa":"/dɪˈpɑːrt/","cefr":"B1","topic":"travel","senses":[{"pos":"v.","en":"to leave a place, especially to start a journey","vi":"rời đi; khởi hành"},{"pos":"v.","en":"to act differently from an established rule or practice","vi":"khác biệt; đi chệch (khỏi quy tắc)"}],"examples":[{"en":"Our train departs at dawn, so pack your bag tonight.","vi":"Tàu của chúng tôi khởi hành vào lúc sáng sớm, vì vậy hãy thu dọn hành lý tối nay nhé.","audioKind":"ex"},{"en":"Buses that depart regularly from residential areas can reduce commuters'' dependence on private cars.","vi":"Các chuyến xe buýt khởi hành đều đặn từ các khu dân cư có thể làm giảm sự phụ thuộc của người đi làm vào xe hơi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"depart from","vi":"khởi hành từ...; đi chệch khỏi..."},{"en":"depart for","vi":"lên đường đi đến..."},{"en":"depart on time","vi":"khởi hành đúng giờ"}],"wordFamily":["departure (n.)"],"synonyms":["leave"],"antonyms":["arrive"],"tipVi":"Depart from đi với điểm xuất phát, depart for đi với điểm đến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_booking', 'en-b1-5', 'booking', '/ˈbʊkɪŋ/', 'B1', 'sự đặt chỗ; việc đặt trước', 'n.', 'book (v.)', 'Đồng nghĩa: reservation', 'booking là danh từ đếm được; việc đặt trước một dịch vụ nào đó thường dùng booking for.', 'I called the hotel to confirm our booking.', NULL, 'Tôi đã gọi điện cho khách sạn để xác nhận việc đặt phòng của chúng tôi.', '{"wordId":"booking","ukIpa":"/ˈbʊkɪŋ/","usIpa":"/ˈbʊkɪŋ/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"An arrangement to reserve a room, seat, or service.","vi":"sự đặt chỗ; việc đặt trước"}],"examples":[{"en":"I called the hotel to confirm our booking.","vi":"Tôi đã gọi điện cho khách sạn để xác nhận việc đặt phòng của chúng tôi.","audioKind":"ex"},{"en":"Online booking systems allow tourists to compare accommodation prices and plan their journeys more efficiently.","vi":"Hệ thống đặt chỗ trực tuyến cho phép khách du lịch so sánh giá phòng và lên kế hoạch cho chuyến đi của họ hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"make a booking","vi":"thực hiện việc đặt chỗ"},{"en":"confirm a booking","vi":"xác nhận đặt chỗ"},{"en":"cancel a booking","vi":"hủy đặt chỗ"},{"en":"advance booking","vi":"đặt trước"}],"wordFamily":["book (v.)"],"synonyms":["reservation"],"antonyms":[],"tipVi":"booking là danh từ đếm được; việc đặt trước một dịch vụ nào đó thường dùng booking for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_junction', 'en-b1-5', 'junction', '/ˈdʒʌŋkʃn/', 'B1', 'nút giao thông; ngã rẽ; điểm giao nhau', 'n.', NULL, 'Đồng nghĩa: intersection', 'tiếng Anh-Anh thường dùng junction, trong khi tiếng Anh-Mỹ thường gọi ngã rẽ là intersection.', 'Turn left at the junction beside the bakery.', NULL, 'Rẽ trái tại ngã rẽ ngay cạnh tiệm bánh mì.', '{"wordId":"junction","ukIpa":"/ˈdʒʌŋkʃn/","usIpa":"/ˈdʒʌŋkʃn/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A place where roads, railway lines, or other things meet.","vi":"nút giao thông; ngã rẽ; điểm giao nhau"}],"examples":[{"en":"Turn left at the junction beside the bakery.","vi":"Rẽ trái tại ngã rẽ ngay cạnh tiệm bánh mì.","audioKind":"ex"},{"en":"Installing better lighting at busy junctions could reduce accidents involving cyclists and pedestrians.","vi":"Việc lắp đặt hệ thống chiếu sáng tốt hơn tại các nút giao thông đông đúc có thể làm giảm các vụ tai nạn liên quan đến người đi xe đạp và người đi bộ.","audioKind":"ex2"}],"collocations":[{"en":"road junction","vi":"nút giao thông đường bộ"},{"en":"railway junction","vi":"nút giao thông đường sắt"},{"en":"busy junction","vi":"nút giao thông đông đúc"}],"wordFamily":[],"synonyms":["intersection"],"antonyms":[],"tipVi":"tiếng Anh-Anh thường dùng junction, trong khi tiếng Anh-Mỹ thường gọi ngã rẽ là intersection.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overnight', 'en-b1-5', 'overnight', '/ˌoʊvərˈnaɪt/', 'B1', 'qua đêm; vào ban đêm; nhanh chóng; đột ngột; trong chớp mắt; trong đêm; diễn ra qua đêm', 'adv.', NULL, NULL, 'khi diễn tả ý nghĩa "trong một đêm", từ này thường nhấn mạnh sự thay đổi diễn ra rất nhanh chứ không nhất thiết phải đúng nghĩa đen là qua một đêm.', 'We stayed overnight at a small hotel near the station.', NULL, 'Chúng tôi đã nghỉ qua đêm tại một khách sạn nhỏ gần nhà ga.', '{"wordId":"overnight","ukIpa":"/ˌəʊvəˈnaɪt/","usIpa":"/ˌoʊvərˈnaɪt/","cefr":"B1","topic":"travel","senses":[{"pos":"adv.","en":"during the night or for one night","vi":"qua đêm; vào ban đêm"},{"pos":"adv.","en":"very quickly or suddenly","vi":"nhanh chóng; đột ngột; trong chớp mắt"},{"pos":"adj.","en":"happening during or lasting for one night","vi":"trong đêm; diễn ra qua đêm"}],"examples":[{"en":"We stayed overnight at a small hotel near the station.","vi":"Chúng tôi đã nghỉ qua đêm tại một khách sạn nhỏ gần nhà ga.","audioKind":"ex"},{"en":"Investment in public transport can improve urban mobility, but meaningful changes rarely happen overnight.","vi":"Việc đầu tư vào giao thông công cộng có thể cải thiện khả năng di chuyển đô thị, nhưng những thay đổi mang tính cốt lõi hiếm khi diễn ra một cách tức thì trong một sớm một chiều.","audioKind":"ex2"}],"collocations":[{"en":"stay overnight","vi":"ở lại qua đêm"},{"en":"overnight success","vi":"thành công sau một đêm"},{"en":"overnight flight","vi":"chuyến bay đêm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"khi diễn tả ý nghĩa \"trong một đêm\", từ này thường nhấn mạnh sự thay đổi diễn ra rất nhanh chứ không nhất thiết phải đúng nghĩa đen là qua một đêm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_direct', 'en-b1-5', 'direct', '/dəˈrekt/', 'B1', 'trực tiếp; thẳng; chỉ đạo; đạo diễn; điều khiển; hướng dẫn đường đi; hướng sự chú ý', 'adj.', 'directly (adv.), direction (n.), director (n.), indirect (adj.)', 'Trái nghĩa: indirect', 'direct có thể đóng vai trò là tính từ hoặc động từ; cách phát âm phổ biến cũng có thể là /daɪˈrekt/.', 'There is a direct train from here to the airport.', NULL, 'Có một chuyến tàu chạy thẳng từ đây ra sân bay.', '{"wordId":"direct","ukIpa":"/dəˈrekt/","usIpa":"/dəˈrekt/","cefr":"B1","topic":"travel","senses":[{"pos":"adj.","en":"Without anything or anyone coming between.","vi":"trực tiếp; thẳng"},{"pos":"v.","en":"To guide or control an activity, performance, or group.","vi":"chỉ đạo; đạo diễn; điều khiển"},{"pos":"v.","en":"To show the way or aim something towards a place.","vi":"hướng dẫn đường đi; hướng sự chú ý"}],"examples":[{"en":"There is a direct train from here to the airport.","vi":"Có một chuyến tàu chạy thẳng từ đây ra sân bay.","audioKind":"ex"},{"en":"Improved public transport can have a direct impact on employment by connecting residents with more job opportunities.","vi":"Hệ thống giao thông công cộng được cải thiện có thể tác động trực tiếp đến việc làm bằng cách kết nối người dân với nhiều cơ hội nghề nghiệp hơn.","audioKind":"ex2"}],"collocations":[{"en":"direct contact","vi":"tiếp xúc trực tiếp"},{"en":"a direct flight","vi":"chuyến bay thẳng"},{"en":"direct a film","vi":"đạo diễn phim"},{"en":"direct attention to","vi":"hướng sự chú ý vào"}],"wordFamily":["directly (adv.)","direction (n.)","director (n.)","indirect (adj.)"],"synonyms":[],"antonyms":["indirect"],"tipVi":"direct có thể đóng vai trò là tính từ hoặc động từ; cách phát âm phổ biến cũng có thể là /daɪˈrekt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eastern', 'en-b1-5', 'eastern', '/ˈiːstərn/', 'B1', 'thuộc phía đông; ở phía đông', 'adj.', 'east (n.), eastward (adv.), easterly (adj.)', 'Trái nghĩa: western', 'eastern thường chỉ đóng vai trò là tính từ, không dùng để chỉ người phương Đông.', 'Our hotel overlooks the island''s quiet eastern coast.', NULL, 'Khách sạn của chúng tôi nhìn ra bờ biển phía đông yên tĩnh của hòn đảo.', '{"wordId":"eastern","ukIpa":"/ˈiːstən/","usIpa":"/ˈiːstərn/","cefr":"B1","topic":"travel","senses":[{"pos":"adj.","en":"In or relating to the east of an area.","vi":"thuộc phía đông; ở phía đông"}],"examples":[{"en":"Our hotel overlooks the island''s quiet eastern coast.","vi":"Khách sạn của chúng tôi nhìn ra bờ biển phía đông yên tĩnh của hòn đảo.","audioKind":"ex"},{"en":"Improved railway connections could help eastern regions attract investment and reduce economic differences within the country.","vi":"Việc cải thiện các tuyến đường sắt có thể giúp các khu vực phía đông thu hút đầu tư và giảm bớt sự chênh lệch kinh tế trong nước.","audioKind":"ex2"}],"collocations":[{"en":"eastern coast","vi":"bờ biển phía đông"},{"en":"eastern region","vi":"vùng phía đông"},{"en":"eastern boundary","vi":"ranh giới phía đông"}],"wordFamily":["east (n.)","eastward (adv.)","easterly (adj.)"],"synonyms":[],"antonyms":["western"],"tipVi":"eastern thường chỉ đóng vai trò là tính từ, không dùng để chỉ người phương Đông.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scooter', 'en-b1-5', 'scooter', '/ˈskuːtər/', 'B1', 'xe trượt scooter; xe máy tay ga nhỏ', 'n.', 'scoot (v.)', NULL, 'Có thể chỉ loại xe trượt đứng hoặc xe máy tay ga nhỏ.', 'The child pushed her scooter along the smooth path.', NULL, 'Đứa trẻ đẩy chiếc xe trượt scooter của mình dọc theo con đường phẳng lỳ.', '{"wordId":"scooter","ukIpa":"/ˈskuːtə/","usIpa":"/ˈskuːtər/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A small wheeled platform with handlebars, ridden standing up.","vi":"xe trượt scooter"},{"pos":"n.","en":"A small motorcycle with a low platform for your feet.","vi":"xe máy tay ga nhỏ"}],"examples":[{"en":"The child pushed her scooter along the smooth path.","vi":"Đứa trẻ đẩy chiếc xe trượt scooter của mình dọc theo con đường phẳng lỳ.","audioKind":"ex"},{"en":"Shared electric scooter schemes may reduce short car journeys if cities provide safe routes and suitable parking areas.","vi":"Các chương trình xe điện trượt chia sẻ có thể làm giảm các chuyến đi xe hơi ngắn nếu các thành phố cung cấp các tuyến đường an toàn và khu vực đỗ xe phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"ride a scooter","vi":"đi xe trượt hoặc xe tay ga"},{"en":"an electric scooter","vi":"xe trượt điện"},{"en":"a motor scooter","vi":"xe máy tay ga"}],"wordFamily":["scoot (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ loại xe trượt đứng hoặc xe máy tay ga nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_minibus', 'en-b1-5', 'minibus', '/ˈmɪnibʌs/', 'B1', 'xe buýt nhỏ; xe khách nhỏ', 'n.', 'bus (n.)', NULL, 'minibus chỉ dòng xe buýt chở khách cỡ nhỏ, không phải mọi xe tải van đều được gọi là minibus.', 'A minibus picked us up outside the village shop.', NULL, 'Một chiếc xe buýt nhỏ đã đón chúng tôi ở bên ngoài cửa hàng tạp hóa của làng.', '{"wordId":"minibus","ukIpa":"/ˈmɪnibʌs/","usIpa":"/ˈmɪnibʌs/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A small bus carrying fewer passengers than a standard bus.","vi":"xe buýt nhỏ; xe khách nhỏ"}],"examples":[{"en":"A minibus picked us up outside the village shop.","vi":"Một chiếc xe buýt nhỏ đã đón chúng tôi ở bên ngoài cửa hàng tạp hóa của làng.","audioKind":"ex"},{"en":"A community minibus can help older residents reach essential services in areas with limited public transport.","vi":"Xe buýt nhỏ cộng đồng có thể giúp cư dân lớn tuổi tiếp cận các dịch vụ thiết yếu tại những khu vực có phương tiện giao thông công cộng hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"hire a minibus","vi":"thuê một chiếc xe buýt nhỏ"},{"en":"a minibus service","vi":"dịch vụ xe buýt nhỏ đưa đón"},{"en":"travel by minibus","vi":"di chuyển bằng xe buýt nhỏ"}],"wordFamily":["bus (n.)"],"synonyms":[],"antonyms":[],"tipVi":"minibus chỉ dòng xe buýt chở khách cỡ nhỏ, không phải mọi xe tải van đều được gọi là minibus.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_turning', 'en-b1-5', 'turning', '/ˈtɝːnɪŋ/', 'B1', 'chỗ rẽ; ngã rẽ; ngã ba, ngã tư; sự quay; sự xoay', 'n.', 'turn (v.)', NULL, 'Khi chỉ ngã rẽ/chỗ rẽ, từ này chủ yếu dùng trong tiếng Anh-Anh; đây cũng là dạng V-ing của turn.', 'Take the next turning after the small bakery.', NULL, 'Hãy rẽ ở ngã rẽ tiếp theo sau tiệm bánh nhỏ nhé.', '{"wordId":"turning","ukIpa":"/ˈtɜːnɪŋ/","usIpa":"/ˈtɝːnɪŋ/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"a place where a road branches off another road","vi":"chỗ rẽ; ngã rẽ; ngã ba, ngã tư"},{"pos":"n.","en":"the action of moving around a central point","vi":"sự quay; sự xoay"}],"examples":[{"en":"Take the next turning after the small bakery.","vi":"Hãy rẽ ở ngã rẽ tiếp theo sau tiệm bánh nhỏ nhé.","audioKind":"ex"},{"en":"Poor visibility at this turning increases the risk of accidents for cyclists and other road users.","vi":"Tầm nhìn hạn chế tại khúc cua này làm tăng nguy cơ tai nạn cho người đi xe đạp và các phương tiện giao thông khác.","audioKind":"ex2"}],"collocations":[{"en":"miss a turning","vi":"bỏ lỡ chỗ rẽ"},{"en":"take a turning","vi":"rẽ vào một con đường"},{"en":"a turning on the left","vi":"một ngã rẽ ở bên trái"}],"wordFamily":["turn (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ ngã rẽ/chỗ rẽ, từ này chủ yếu dùng trong tiếng Anh-Anh; đây cũng là dạng V-ing của turn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jet', 'en-b1-5', 'jet', '/dʒet/', 'B1', 'máy bay phản lực; tia; dòng phun mạnh (chất lỏng hoặc khí)', 'n.', NULL, NULL, 'a jet of water chỉ một dòng nước phun mạnh.', 'A jet flew low over the beach this morning.', NULL, 'Một chiếc máy bay phản lực bay thấp qua bãi biển vào sáng nay.', '{"wordId":"jet","ukIpa":"/dʒet/","usIpa":"/dʒet/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"An aircraft powered by jet engines.","vi":"máy bay phản lực"},{"pos":"n.","en":"A narrow, forceful stream of liquid or gas.","vi":"tia; dòng phun mạnh (chất lỏng hoặc khí)"}],"examples":[{"en":"A jet flew low over the beach this morning.","vi":"Một chiếc máy bay phản lực bay thấp qua bãi biển vào sáng nay.","audioKind":"ex"},{"en":"Replacing older passenger jets with more efficient aircraft could reduce fuel consumption across the aviation industry.","vi":"Việc thay thế các dòng máy bay chở khách cũ bằng các loại máy bay hiệu quả hơn có thể làm giảm tiêu thụ nhiên liệu trong toàn ngành hàng không.","audioKind":"ex2"}],"collocations":[{"en":"passenger jet","vi":"máy bay phản lực chở khách"},{"en":"jet engine","vi":"động cơ phản lực"},{"en":"a jet of water","vi":"một tia nước phun"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"a jet of water chỉ một dòng nước phun mạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crash', 'en-b1-5', 'crash', '/kræʃ/', 'B1', 'tai nạn xe cộ; sự va chạm mạnh; sự rơi (máy bay); va đâm mạnh; rơi và hư hỏng nặng; ngừng hoạt động đột ngột; sụp đổ, tụt giảm cực nhanh', 'n.', NULL, NULL, 'crash into sau tiếp theo là vật bị va đạm; lỗi máy tính treo cũng có thể dùng crash.', 'Nobody was hurt in the crash outside our house.', NULL, 'Không có ai bị thương trong vụ tai nạn xe cộ ngay bên ngoài nhà chúng tôi.', '{"wordId":"crash","ukIpa":"/kræʃ/","usIpa":"/kræʃ/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"an accident in which a vehicle hits something or falls","vi":"tai nạn xe cộ; sự va chạm mạnh; sự rơi (máy bay)"},{"pos":"v.","en":"to hit something violently or fall and be badly damaged","vi":"va đâm mạnh; rơi và hư hỏng nặng"},{"pos":"v.","en":"to stop working suddenly or lose value very quickly","vi":"ngừng hoạt động đột ngột; sụp đổ, tụt giảm cực nhanh"}],"examples":[{"en":"Nobody was hurt in the crash outside our house.","vi":"Không có ai bị thương trong vụ tai nạn xe cộ ngay bên ngoài nhà chúng tôi.","audioKind":"ex"},{"en":"Financial markets can crash when investors suddenly lose confidence in the stability of the economy.","vi":"Các thị trường tài chính có thể sụp đổ khi các nhà đầu tư đột nhiên mất lòng tin vào sự ổn định của nền kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"a car crash","vi":"vụ tai nạn xe hơi"},{"en":"crash into a wall","vi":"đâm sầm vào tường"},{"en":"a computer crash","vi":"máy tính bị treo"},{"en":"a stock market crash","vi":"thị trường chứng khoán sụp đổ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"crash into sau tiếp theo là vật bị va đạm; lỗi máy tính treo cũng có thể dùng crash.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arrow', 'en-b1-5', 'arrow', '/ˈæroʊ/', 'B1', 'mũi tên; ký hiệu hình mũi tên; mũi tên (bắn từ cung)', 'n.', NULL, NULL, 'arrow vừa chỉ mũi tên bắn ra từ cung, vừa chỉ mũi tên chỉ đường.', 'Follow the arrow on the floor to the exit.', NULL, 'Hãy đi theo mũi tên trên mặt sàn để ra lối thoát hiểm.', '{"wordId":"arrow","ukIpa":"/ˈærəʊ/","usIpa":"/ˈæroʊ/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"a pointed symbol showing direction","vi":"mũi tên; ký hiệu hình mũi tên"},{"pos":"n.","en":"a thin pointed object shot from a bow","vi":"mũi tên (bắn từ cung)"}],"examples":[{"en":"Follow the arrow on the floor to the exit.","vi":"Hãy đi theo mũi tên trên mặt sàn để ra lối thoát hiểm.","audioKind":"ex"},{"en":"Clear arrows on station floors can improve passenger flow and reduce confusion during busy commuting periods.","vi":"Những mũi tên rõ ràng trên sàn nhà ga có thể giúp cải thiện luồng di chuyển của hành khách và giảm bớt sự hỗn loạn trong giờ cao điểm đi lại.","audioKind":"ex2"}],"collocations":[{"en":"follow the arrow","vi":"đi theo hướng mũi tên"},{"en":"an arrow points to","vi":"mũi tên chỉ vào"},{"en":"bow and arrow","vi":"cung và tên"},{"en":"shoot an arrow","vi":"bắn tên"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"arrow vừa chỉ mũi tên bắn ra từ cung, vừa chỉ mũi tên chỉ đường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_honeymoon', 'en-b1-5', 'honeymoon', '/ˈhʌnimuːn/', 'B1', 'tuần trăng mật; kỳ nghỉ trăng mật; giai đoạn đầu hòa hợp; đi hưởng tuần trăng mật', 'n.', 'honeymooner (n.)', NULL, 'Tiếng Anh–Anh thường dùng on honeymoon, trong khi tiếng Anh–Mỹ dùng on a honeymoon.', 'They spent their honeymoon in a quiet seaside village.', NULL, 'Họ đã dành kỳ nghỉ trăng mật của mình tại một ngôi làng ven biển yên tĩnh.', '{"wordId":"honeymoon","ukIpa":"/ˈhʌnimuːn/","usIpa":"/ˈhʌnimuːn/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A holiday taken by a couple just after their wedding.","vi":"tuần trăng mật; kỳ nghỉ trăng mật"},{"pos":"n.","en":"An early period when a relationship or situation goes well.","vi":"giai đoạn đầu hòa hợp"},{"pos":"v.","en":"To take a holiday together just after getting married.","vi":"đi hưởng tuần trăng mật"}],"examples":[{"en":"They spent their honeymoon in a quiet seaside village.","vi":"Họ đã dành kỳ nghỉ trăng mật của mình tại một ngôi làng ven biển yên tĩnh.","audioKind":"ex"},{"en":"Popular honeymoon destinations can support local economies, but excessive tourism may damage fragile coastal environments.","vi":"Các điểm đến trăng mật nổi tiếng có thể hỗ trợ kinh tế địa phương, nhưng du lịch quá mức có thể tàn phá môi trường vùng ven biển mỏng manh.","audioKind":"ex2"}],"collocations":[{"en":"on honeymoon","vi":"đi hưởng tuần trăng mật"},{"en":"honeymoon destination","vi":"địa điểm hưởng tuần trăng mật"},{"en":"honeymoon period","vi":"giai đoạn mật ngọt"}],"wordFamily":["honeymooner (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh–Anh thường dùng on honeymoon, trong khi tiếng Anh–Mỹ dùng on a honeymoon.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cabin', 'en-b1-5', 'cabin', '/ˈkæbɪn/', 'B1', 'nhà gỗ nhỏ; lều gỗ; khoang tàu; cabin máy bay', 'n.', NULL, NULL, 'Từ này vừa chỉ ngôi nhà nhỏ trên cạn, vừa chỉ khoang trên tàu thủy hoặc máy bay.', 'We spent the weekend in a cabin beside the lake.', NULL, 'Chúng tôi đã dành trọn cuối tuần tại một ngôi nhà gỗ nhỏ bên hồ.', '{"wordId":"cabin","ukIpa":"/ˈkæbɪn/","usIpa":"/ˈkæbɪn/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A small, simple house, often built from wood.","vi":"nhà gỗ nhỏ; lều gỗ"},{"pos":"n.","en":"A room on a ship or passenger space in an aircraft.","vi":"khoang tàu; cabin máy bay"}],"examples":[{"en":"We spent the weekend in a cabin beside the lake.","vi":"Chúng tôi đã dành trọn cuối tuần tại một ngôi nhà gỗ nhỏ bên hồ.","audioKind":"ex"},{"en":"Holiday cabins in protected forests should be carefully managed to limit their impact on local wildlife.","vi":"Các khu nhà nghỉ dưỡng trong khu rừng được bảo vệ cần được quản lý cẩn thận nhằm hạn chế tác động tiêu cực đến động vật hoang dã địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a log cabin","vi":"nhà gỗ tròn"},{"en":"cabin crew","vi":"đội ngũ tiếp viên hàng không"},{"en":"a passenger cabin","vi":"khoang hành khách"},{"en":"cabin baggage","vi":"hành lý xách tay"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ này vừa chỉ ngôi nhà nhỏ trên cạn, vừa chỉ khoang trên tàu thủy hoặc máy bay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_track', 'en-b1-5', 'track', '/træk/', 'B1', 'đường mòn; đường chạy; đường ray; theo dõi; giám sát; dấu vết', 'n.', 'tracker (n.), tracking (n.)', NULL, 'keep track of chỉ việc tiếp tục nắm bắt thông tin; lose track of chỉ việc mất dấu hoặc quên mất.', 'We followed a narrow track through the pine forest.', NULL, 'Chúng tôi đi theo một con đường mòn nhỏ xuyên qua khu rừng thông.', '{"wordId":"track","ukIpa":"/træk/","usIpa":"/træk/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A path or course for walking, running, or trains.","vi":"đường mòn; đường chạy; đường ray"},{"pos":"v.","en":"To follow movement or monitor changes over time.","vi":"theo dõi; giám sát"},{"pos":"n.","en":"A mark left by a person, animal, or vehicle.","vi":"dấu vết"}],"examples":[{"en":"We followed a narrow track through the pine forest.","vi":"Chúng tôi đi theo một con đường mòn nhỏ xuyên qua khu rừng thông.","audioKind":"ex"},{"en":"Researchers use satellite technology to track animal movements and identify habitats that require greater protection.","vi":"Các nhà nghiên cứu sử dụng công nghệ vệ tinh để theo dõi sự di chuyểnของ động vật và xác định các sinh cảnh cần được bảo vệ nhiều hơn.","audioKind":"ex2"}],"collocations":[{"en":"a railway track","vi":"đường ray xe lửa"},{"en":"a running track","vi":"đường chạy điền kinh"},{"en":"track progress","vi":"theo dõi tiến độ"},{"en":"keep track of","vi":"theo dõi sát sao; nắm bắt"}],"wordFamily":["tracker (n.)","tracking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"keep track of chỉ việc tiếp tục nắm bắt thông tin; lose track of chỉ việc mất dấu hoặc quên mất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guidebook', 'en-b1-5', 'guidebook', '/ˈɡaɪdbʊk/', 'B1', 'sách hướng dẫn du lịch; cẩm nang', 'n.', 'guide (n.), guide (v.)', 'Đồng nghĩa: guide', 'Sách hướng dẫn về một địa điểm cụ thể thường dùng cấu trúc a guidebook to kèm theo tên địa danh.', 'Our guidebook recommended a quiet beach near the village.', NULL, 'Cuốn cẩm nang du lịch của chúng tôi đã gợi ý một bãi biển yên tĩnh gần ngôi làng.', '{"wordId":"guidebook","ukIpa":"/ˈɡaɪdbʊk/","usIpa":"/ˈɡaɪdbʊk/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"a book giving information about a place or practical subject","vi":"sách hướng dẫn du lịch; cẩm nang"}],"examples":[{"en":"Our guidebook recommended a quiet beach near the village.","vi":"Cuốn cẩm nang du lịch của chúng tôi đã gợi ý một bãi biển yên tĩnh gần ngôi làng.","audioKind":"ex"},{"en":"Although digital maps are convenient, a detailed guidebook can provide valuable cultural context for independent travellers.","vi":"Mặc dù bản đồ kỹ thuật số rất tiện lợi, một cuốn sách hướng dẫn chi tiết có thể cung cấp bối cảnh văn hóa quý giá cho khách du lịch tự túc.","audioKind":"ex2"}],"collocations":[{"en":"a travel guidebook","vi":"sách hướng dẫn du lịch"},{"en":"a guidebook to","vi":"cẩm nang giới thiệu về"},{"en":"consult a guidebook","vi":"tra cứu sách hướng dẫn"}],"wordFamily":["guide (n.)","guide (v.)"],"synonyms":["guide"],"antonyms":[],"tipVi":"Sách hướng dẫn về một địa điểm cụ thể thường dùng cấu trúc a guidebook to kèm theo tên địa danh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_5_1', 'en-b1-5', 'Cách dùng “overnight” (adv.) — qua đêm; vào ban đêm', 'stay overnight  ·  overnight success  ·  overnight flight', 'khi diễn tả ý nghĩa "trong một đêm", từ này thường nhấn mạnh sự thay đổi diễn ra rất nhanh chứ không nhất thiết phải đúng nghĩa đen là qua một đêm.', NULL, '[{"hanzi":"We stayed overnight at a small hotel near the station.","pinyin":"","meaning":"Chúng tôi đã nghỉ qua đêm tại một khách sạn nhỏ gần nhà ga."},{"hanzi":"Investment in public transport can improve urban mobility, but meaningful changes rarely happen overnight.","pinyin":"","meaning":"Việc đầu tư vào giao thông công cộng có thể cải thiện khả năng di chuyển đô thị, nhưng những thay đổi mang tính cốt lõi hiếm khi diễn ra một cách tức thì trong một sớm một chiều."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_5_2', 'en-b1-5', 'Cách dùng “cab” (n.) — xe taxi', 'hail a cab  ·  take a cab  ·  cab fare', 'Từ này đồng nghĩa với taxi khi chỉ xe chở khách; ngoài ra còn có thể chỉ buồng lái của xe tải hoặc phương tiện lớn.', 'Đồng nghĩa: taxi', '[{"hanzi":"We shared a cab home after the concert.","pinyin":"","meaning":"Chúng tôi chung tiền đi một chiếc taxi về nhà sau buổi hòa nhạc."},{"hanzi":"Affordable night buses could reduce reliance on cabs among workers whose shifts end after midnight.","pinyin":"","meaning":"Xe buýt đêm giá rẻ có thể giúp giảm sự phụ thuộc vào taxi đối với những công nhân có ca làm việc kết thúc sau nửa đêm."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_5_3', 'en-b1-5', 'Cách dùng “direct” (adj.) — trực tiếp; thẳng', 'direct contact  ·  a direct flight  ·  direct a film', 'direct có thể đóng vai trò là tính từ hoặc động từ; cách phát âm phổ biến cũng có thể là /daɪˈrekt/.', 'Họ từ (Word Family): directly (adv.), direction (n.), director (n.), indirect (adj.) | Trái nghĩa: indirect', '[{"hanzi":"There is a direct train from here to the airport.","pinyin":"","meaning":"Có một chuyến tàu chạy thẳng từ đây ra sân bay."},{"hanzi":"Improved public transport can have a direct impact on employment by connecting residents with more job opportunities.","pinyin":"","meaning":"Hệ thống giao thông công cộng được cải thiện có thể tác động trực tiếp đến việc làm bằng cách kết nối người dân với nhiều cơ hội nghề nghiệp hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_5_4', 'en-b1-5', 'Cách dùng “turning” (n.) — chỗ rẽ; ngã rẽ; ngã ba, ngã tư', 'miss a turning  ·  take a turning  ·  a turning on the left', 'Khi chỉ ngã rẽ/chỗ rẽ, từ này chủ yếu dùng trong tiếng Anh-Anh; đây cũng là dạng V-ing của turn.', 'Họ từ (Word Family): turn (v.)', '[{"hanzi":"Take the next turning after the small bakery.","pinyin":"","meaning":"Hãy rẽ ở ngã rẽ tiếp theo sau tiệm bánh nhỏ nhé."},{"hanzi":"Poor visibility at this turning increases the risk of accidents for cyclists and other road users.","pinyin":"","meaning":"Tầm nhìn hạn chế tại khúc cua này làm tăng nguy cơ tai nạn cho người đi xe đạp và các phương tiện giao thông khác."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_5_1', 'en-b1-5', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_1_1', 'ten_b1_5_1', 'hut', 'We sheltered from the rain in a wooden hut.', 'We sheltered from the rain in a wooden hut.', '/hʌt/', 'Chúng tôi đã trú mưa trong một ngôi nhà gỗ nhỏ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_1_2', 'ten_b1_5_1', 'hostel', 'We shared a room with other travellers at the hostel.', 'We shared a room with other travellers at the hostel.', '/ˈhɑːstəl/', 'Chúng tôi ở chung phòng với những du khách khác tại nhà nghỉ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_1_3', 'ten_b1_5_1', 'port', 'We watched fishing boats returning to the port.', 'We watched fishing boats returning to the port.', '/pɔːrt/', 'Chúng tôi ngắm nhìn những chiếc thuyền đánh cá đang quay trở lại cảng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_1_4', 'ten_b1_5_1', 'cab', 'We shared a cab home after the concert.', 'We shared a cab home after the concert.', '/kæb/', 'Chúng tôi chung tiền đi một chiếc taxi về nhà sau buổi hòa nhạc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_1_5', 'ten_b1_5_1', 'vehicle', 'We left our vehicle outside the small mountain hotel.', 'We left our vehicle outside the small mountain hotel.', '/ˈviːəkl/', 'Chúng tôi để chiếc xe của mình ở bên ngoài khách sạn nhỏ trên núi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_1_6', 'ten_b1_5_1', 'destination', 'We finally reached our destination just before sunset.', 'We finally reached our destination just before sunset.', '/ˌdestɪˈneɪʃən/', 'Cuối cùng chúng tôi cũng đến được điểm đến của mình ngay trước khi mặt trời lặn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_1_7', 'ten_b1_5_1', 'lighthouse', 'The lighthouse beam swept across the dark sea.', 'The lighthouse beam swept across the dark sea.', '/ˈlaɪthaʊs/', 'Luồng sáng từ ngọn hải đăng quét qua vùng biển tối tăm.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_1_8', 'ten_b1_5_1', 'tyre', 'We stopped beside the road to change a flat tyre.', 'We stopped beside the road to change a flat tyre.', '/ˈtaɪr/', 'Chúng tôi dừng xe bên đường để thay chiếc lốp bị xịt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_5_1_1', 'en-b1-5', 'ten_b1_5_1', 'listening', 'listening', 'We sheltered from the rain in a wooden hut.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Rẽ trái tại ngã rẽ ngay cạnh tiệm bánh mì.","Chúng tôi đã trú mưa trong một ngôi nhà gỗ nhỏ.","Chúng tôi đã dành trọn cuối tuần tại một ngôi nhà gỗ nhỏ bên hồ.","Hãy đi theo mũi tên trên mặt sàn để ra lối thoát hiểm."]'::jsonb, 1, 'We sheltered from the rain in a wooden hut. → Chúng tôi đã trú mưa trong một ngôi nhà gỗ nhỏ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_5_1_2', 'en-b1-5', 'ten_b1_5_1', 'listening', 'listening', 'We shared a room with other travellers at the hostel.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã gọi điện cho khách sạn để xác nhận việc đặt phòng của chúng tôi.","Tàu của chúng tôi khởi hành vào lúc sáng sớm, vì vậy hãy thu dọn hành lý tối nay nhé.","Một chiếc máy bay phản lực bay thấp qua bãi biển vào sáng nay.","Chúng tôi ở chung phòng với những du khách khác tại nhà nghỉ."]'::jsonb, 3, 'We shared a room with other travellers at the hostel. → Chúng tôi ở chung phòng với những du khách khác tại nhà nghỉ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_5_1_3', 'en-b1-5', 'ten_b1_5_1', 'listening', 'listening', 'We watched fishing boats returning to the port.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi ngắm nhìn những chiếc thuyền đánh cá đang quay trở lại cảng.","Cuối cùng chúng tôi cũng đến được điểm đến của mình ngay trước khi mặt trời lặn.","Rẽ trái tại ngã rẽ ngay cạnh tiệm bánh mì.","Không có ai bị thương trong vụ tai nạn xe cộ ngay bên ngoài nhà chúng tôi."]'::jsonb, 0, 'We watched fishing boats returning to the port. → Chúng tôi ngắm nhìn những chiếc thuyền đánh cá đang quay trở lại cảng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_5_2', 'en-b1-5', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_2_1', 'ten_b1_5_2', 'hut', 'Mountain huts provide essential shelter for hikers, but their construction should minimise damage to fragile ecosystems.', 'Mountain huts provide essential shelter for hikers, but their construction should minimise damage to fragile ecosystems.', '/hʌt/', 'Những căn lều trên núi cung cấp nơi trú ẩn thiết yếu cho người đi bộ đường dài, nhưng việc xây dựng chúng nên hạn chế tối đa tổn hại đến các hệ sinh thái mỏng manh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_2_2', 'ten_b1_5_2', 'hostel', 'Youth hostels make international travel more affordable for students while encouraging interaction between people from different backgrounds.', 'Youth hostels make international travel more affordable for students while encouraging interaction between people from different backgrounds.', '/ˈhɑːstəl/', 'Các nhà nghỉ thanh niên giúp việc du lịch quốc tế trở nên dễ chi trả hơn đối với học sinh, sinh viên đồng thời thúc đẩy sự giao lưu giữa những người đến từ các nền văn hóa khác nhau.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_2_3', 'ten_b1_5_2', 'port', 'Expanding the port could increase international trade, but it may also damage nearby marine habitats.', 'Expanding the port could increase international trade, but it may also damage nearby marine habitats.', '/pɔːrt/', 'Việc mở rộng cảng có thể làm tăng thương mại quốc tế, nhưng nó cũng có thể phá hủy các môi trường sống dưới nước ở gần đó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_2_4', 'ten_b1_5_2', 'cab', 'Affordable night buses could reduce reliance on cabs among workers whose shifts end after midnight.', 'Affordable night buses could reduce reliance on cabs among workers whose shifts end after midnight.', '/kæb/', 'Xe buýt đêm giá rẻ có thể giúp giảm sự phụ thuộc vào taxi đối với những công nhân có ca làm việc kết thúc sau nửa đêm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_2_5', 'ten_b1_5_2', 'vehicle', 'Electric vehicles can reduce urban air pollution, especially when their electricity comes from renewable sources.', 'Electric vehicles can reduce urban air pollution, especially when their electricity comes from renewable sources.', '/ˈviːəkl/', 'Xe điện có thể giúp giảm ô nhiễm không khí đô thị, đặc biệt là khi nguồn điện được tạo ra từ các nguồn năng lượng tái tạo.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_5_2_6', 'ten_b1_5_2', 'destination', 'Popular tourist destinations must balance economic benefits with the need to protect local communities and natural environments.', 'Popular tourist destinations must balance economic benefits with the need to protect local communities and natural environments.', '/ˌdestɪˈneɪʃən/', 'Các điểm đến du lịch nổi tiếng phải cân bằng giữa lợi ích kinh tế với nhu cầu bảo vệ cộng đồng địa phương và môi trường tự nhiên.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_5_2_1', 'en-b1-5', 'ten_b1_5_2', 'listening', 'listening', 'Mountain huts provide essential shelter for hikers, but their construction should minimise damage to fragile ecosystems.', NULL, 'Trong câu vừa nghe, từ “hut” mang nghĩa nào sau đây?', '["mịn màng; phẳng phiu, không có vùng gồ ghề hoặc lồi lõm","tuyệt vời; cực kỳ thú vị","phong cảnh; cảnh quan thiên nhiên","lều; nhà tranh; chòi"]'::jsonb, 3, '“hut” (/hʌt/): lều; nhà tranh; chòi. Câu đầy đủ: Mountain huts provide essential shelter for hikers, but their construction should minimise damage to fragile ecosystems.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_5_2_2', 'en-b1-5', 'ten_b1_5_2', 'listening', 'listening', 'Youth hostels make international travel more affordable for students while encouraging interaction between people from different backgrounds.', NULL, 'Trong câu vừa nghe, từ “hostel” mang nghĩa nào sau đây?', '["xin lỗi","định nghĩa; sự giải thích nghĩa","nhà nghỉ giá rẻ; ký túc xá cho khách du lịch","tha thứ; khoan dung"]'::jsonb, 2, '“hostel” (/ˈhɑːstəl/): nhà nghỉ giá rẻ; ký túc xá cho khách du lịch. Câu đầy đủ: Youth hostels make international travel more affordable for students while encouraging interaction between people from different backgrounds.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
