INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_1', 'en-b1-5', NULL, 'comprehensive_test', 'listening', 'hut', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lực; sức mạnh vật lý","hiệu trưởng nam; nam hiệu trưởng","lều; nhà tranh; chòi","cầu nguyện; cầu xin (thần linh)"]'::jsonb, 2, 'hut (/hʌt/) → lều; nhà tranh; chòi', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_2', 'en-b1-5', NULL, 'comprehensive_test', 'listening', 'We shared a room with other travellers at the hostel.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Họ đã dành kỳ nghỉ trăng mật của mình tại một ngôi làng ven biển yên tĩnh.","Chúng tôi đã nghỉ qua đêm tại một khách sạn nhỏ gần nhà ga.","Chúng tôi ở chung phòng với những du khách khác tại nhà nghỉ.","Chúng tôi để chiếc xe của mình ở bên ngoài khách sạn nhỏ trên núi."]'::jsonb, 2, 'We shared a room with other travellers at the hostel. → Chúng tôi ở chung phòng với những du khách khác tại nhà nghỉ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_3', 'en-b1-5', NULL, 'comprehensive_test', 'listening', 'port', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cảng; thành phố cảng","thang cuốn","gạch chân","sống sót; tồn tại"]'::jsonb, 0, 'port (/pɔːrt/) → cảng; thành phố cảng; cổng kết nối; giao diện; mạn trái (của tàu thủy hoặc máy bay)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_4', 'en-b1-5', NULL, 'comprehensive_test', 'listening', 'We shared a cab home after the concert.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy rẽ ở ngã rẽ tiếp theo sau tiệm bánh nhỏ nhé.","Luồng sáng từ ngọn hải đăng quét qua vùng biển tối tăm.","Chúng tôi chung tiền đi một chiếc taxi về nhà sau buổi hòa nhạc.","Họ đã dành kỳ nghỉ trăng mật của mình tại một ngôi làng ven biển yên tĩnh."]'::jsonb, 2, 'We shared a cab home after the concert. → Chúng tôi chung tiền đi một chiếc taxi về nhà sau buổi hòa nhạc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_5', 'en-b1-5', NULL, 'comprehensive_test', 'listening', 'vehicle', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vấn đề, đề tài (vấn đề quan trọng cần được thảo luận)","hợp lý; có lý; thấu tình đạt lý","phương tiện giao thông; xe cộ","sự tự tin; niềm tin"]'::jsonb, 2, 'vehicle (/ˈviːəkl/) → phương tiện giao thông; xe cộ; phương tiện; công cụ (để truyền đạt ý tưởng hoặc đạt mục đích)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_6', 'en-b1-5', NULL, 'comprehensive_test', 'listening', 'We finally reached our destination just before sunset.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi để chiếc xe của mình ở bên ngoài khách sạn nhỏ trên núi.","Cuốn cẩm nang du lịch của chúng tôi đã gợi ý một bãi biển yên tĩnh gần ngôi làng.","Không có ai bị thương trong vụ tai nạn xe cộ ngay bên ngoài nhà chúng tôi.","Cuối cùng chúng tôi cũng đến được điểm đến của mình ngay trước khi mặt trời lặn."]'::jsonb, 3, 'We finally reached our destination just before sunset. → Cuối cùng chúng tôi cũng đến được điểm đến của mình ngay trước khi mặt trời lặn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_7', 'en-b1-5', NULL, 'comprehensive_test', 'listening', 'lighthouse', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mang ý nghĩa lịch sử; có tầm quan trọng lịch sử; lịch sử","lặp đi lặp lại; nhiều lần","không thể; không có khả năng","đèn biển; ngọn hải đăng"]'::jsonb, 3, 'lighthouse (/ˈlaɪthaʊs/) → đèn biển; ngọn hải đăng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_8', 'en-b1-5', NULL, 'comprehensive_test', 'listening', 'We stopped beside the road to change a flat tyre.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tàu của chúng tôi khởi hành vào lúc sáng sớm, vì vậy hãy thu dọn hành lý tối nay nhé.","Cuối cùng chúng tôi cũng đến được điểm đến của mình ngay trước khi mặt trời lặn.","Chúng tôi dừng xe bên đường để thay chiếc lốp bị xịt.","Một chiếc xe buýt nhỏ đã đón chúng tôi ở bên ngoài cửa hàng tạp hóa của làng."]'::jsonb, 2, 'We stopped beside the road to change a flat tyre. → Chúng tôi dừng xe bên đường để thay chiếc lốp bị xịt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_9', 'en-b1-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A machine used to transport people or goods.”?', '["cabin","arrow","track","vehicle"]'::jsonb, 3, 'vehicle (/ˈviːəkl/) → phương tiện giao thông; xe cộ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_10', 'en-b1-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the place someone or something is travelling to”?', '["destination","hut","minibus","honeymoon"]'::jsonb, 0, 'destination (/ˌdestɪˈneɪʃən/) → đích đến; điểm đến', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_11', 'en-b1-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A coastal tower with a powerful light that guides ships.”?', '["guidebook","crash","lighthouse","cabin"]'::jsonb, 2, 'lighthouse (/ˈlaɪthaʊs/) → đèn biển; ngọn hải đăng', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_12', 'en-b1-5', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A rubber covering around a wheel that touches the road.”?', '["hut","tyre","booking","arrow"]'::jsonb, 1, 'tyre (/ˈtaɪr/) → lốp xe; vỏ xe', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
