INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_18', 'en-b1-5', NULL, 'comprehensive_test', 'reading', NULL, 'Mountain huts provide essential shelter for hikers, but their construction should minimise damage to fragile ecosystems.', 'Dựa vào câu trên, từ “hut” có nghĩa phù hợp nhất là gì?', '["diễn viên hài, nghệ sĩ hài","ôm; ôm chặt","lều; nhà tranh; chòi","môn thể dục dụng cụ; nghệ thuật thể dục"]'::jsonb, 2, 'hut: lều; nhà tranh; chòi. Dịch cả câu: Những căn lều trên núi cung cấp nơi trú ẩn thiết yếu cho người đi bộ đường dài, nhưng việc xây dựng chúng nên hạn chế tối đa tổn hại đến các hệ sinh thái mỏng manh.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_19', 'en-b1-5', NULL, 'comprehensive_test', 'reading', NULL, 'Youth hostels make international travel more affordable for students while encouraging interaction between people from different backgrounds.', 'Dựa vào câu trên, từ “hostel” có nghĩa phù hợp nhất là gì?', '["tiếng khóc; sự khóc","thường ngày; giản dị; không trang trọng","nhà nghỉ giá rẻ; ký túc xá cho khách du lịch","bóng; sáng lấp lánh"]'::jsonb, 2, 'hostel: nhà nghỉ giá rẻ; ký túc xá cho khách du lịch; nhà tạm trú; nơi cung cấp chỗ ở tạm thời cho người cần hỗ trợ. Dịch cả câu: Các nhà nghỉ thanh niên giúp việc du lịch quốc tế trở nên dễ chi trả hơn đối với học sinh, sinh viên đồng thời thúc đẩy sự giao lưu giữa những người đến từ các nền văn hóa khác nhau.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_20', 'en-b1-5', NULL, 'comprehensive_test', 'reading', NULL, 'Expanding the port could increase international trade, but it may also damage nearby marine habitats.', 'Dựa vào câu trên, từ “port” có nghĩa phù hợp nhất là gì?', '["con ngỗng","độ C (thuộc thang nhiệt độ với điểm đóng băng của nước là không độ)","sửa chữa; vá","cảng; thành phố cảng"]'::jsonb, 3, 'port: cảng; thành phố cảng; cổng kết nối; giao diện; mạn trái (của tàu thủy hoặc máy bay). Dịch cả câu: Việc mở rộng cảng có thể làm tăng thương mại quốc tế, nhưng nó cũng có thể phá hủy các môi trường sống dưới nước ở gần đó.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_21', 'en-b1-5', NULL, 'comprehensive_test', 'reading', NULL, 'Affordable night buses could reduce reliance on cabs among workers whose shifts end after midnight.', 'Dựa vào câu trên, từ “cab” có nghĩa phù hợp nhất là gì?', '["tấm chăn; lớp phủ","kẹo cao su","xe taxi","thuyền kayak; thuyền độc mộc thể thao"]'::jsonb, 2, 'cab: xe taxi; khoang lái; buồng lái (của xe tải hoặc phương tiện). Dịch cả câu: Xe buýt đêm giá rẻ có thể giúp giảm sự phụ thuộc vào taxi đối với những công nhân có ca làm việc kết thúc sau nửa đêm.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_22', 'en-b1-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhà gỗ nhỏ; lều gỗ”', '["ballet","cabin","imagination","balcony"]'::jsonb, 1, 'nhà gỗ nhỏ; lều gỗ → cabin (/ˈkæbɪn/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_23', 'en-b1-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đường mòn; đường chạy; đường ray”', '["track","rainbow","trend","puzzle"]'::jsonb, 0, 'đường mòn; đường chạy; đường ray → track (/træk/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_5_24', 'en-b1-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sách hướng dẫn du lịch; cẩm nang”', '["outdoors","donate","guidebook","darkness"]'::jsonb, 2, 'sách hướng dẫn du lịch; cẩm nang → guidebook (/ˈɡaɪdbʊk/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-6', 'en', 'Bài 6: Du lịch & Di chuyển (2) - CEFR B1', 'CEFR B1', 'B1 · Du lịch', '25 từ vựng Tiếng Anh CEFR B1 chủ đề du lịch & di chuyển kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3006, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cyclist', 'en-b1-6', 'cyclist', '/ˈsaɪklɪst/', 'B1', 'người đi xe đạp', 'n.', 'cycle (v.), cycling (n.)', NULL, '"cyclist" chỉ người đi xe đạp, không dùng để chỉ người đi xe máy.', 'The cyclist stopped beside the bridge for water.', NULL, 'Người đi xe đạp dừng lại bên cầu để uống nước.', '{"wordId":"cyclist","ukIpa":"/ˈsaɪklɪst/","usIpa":"/ˈsaɪklɪst/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"a person who rides a bicycle","vi":"người đi xe đạp"}],"examples":[{"en":"The cyclist stopped beside the bridge for water.","vi":"Người đi xe đạp dừng lại bên cầu để uống nước.","audioKind":"ex"},{"en":"Protected cycle lanes can reduce the risk of collisions between cyclists and motor vehicles in busy cities.","vi":"Các làn đường dành riêng cho xe đạp được bảo vệ có thể làm giảm nguy cơ va chạm giữa người đi xe đạp và xe cơ giới ở các thành phố đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"commuter cyclist","vi":"người đi xe đạp đi làm"},{"en":"professional cyclist","vi":"vận động viên xe đạp chuyên nghiệp"},{"en":"cyclist safety","vi":"an toàn cho người đi xe đạp"}],"wordFamily":["cycle (v.)","cycling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"cyclist\" chỉ người đi xe đạp, không dùng để chỉ người đi xe máy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guided', 'en-b1-6', 'guided', '/ˈɡaɪdɪd/', 'B1', 'có hướng dẫn; có người dẫn đường', 'adj.', 'guide (v.), guidance (n.), unguided (adj.)', 'Trái nghĩa: unguided', 'guided tour chỉ chuyến tham quan có hướng dẫn viên; guided cũng đồng thời là phân từ hai của động từ guide.', 'We joined a guided walk through the forest yesterday.', NULL, 'Hôm qua chúng tôi đã tham gia một chuyến đi bộ xuyên rừng có người hướng dẫn.', '{"wordId":"guided","ukIpa":"/ˈɡaɪdɪd/","usIpa":"/ˈɡaɪdɪd/","cefr":"B1","topic":"travel","senses":[{"pos":"adj.","en":"led or supported by someone with knowledge or experience","vi":"có hướng dẫn; có người dẫn đường"}],"examples":[{"en":"We joined a guided walk through the forest yesterday.","vi":"Hôm qua chúng tôi đã tham gia một chuyến đi bộ xuyên rừng có người hướng dẫn.","audioKind":"ex"},{"en":"Guided learning can help students build confidence before they begin working independently on complex tasks.","vi":"Việc học tập có hướng dẫn giúp học sinh xây dựng sự tự tin trước khi bắt đầu tự mình thực hiện các nhiệm vụ phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"guided tour","vi":"chuyến tham quan có hướng dẫn"},{"en":"guided walk","vi":"chuyến đi bộ có người dẫn đường"},{"en":"guided learning","vi":"việc học tập có hướng dẫn"}],"wordFamily":["guide (v.)","guidance (n.)","unguided (adj.)"],"synonyms":[],"antonyms":["unguided"],"tipVi":"guided tour chỉ chuyến tham quan có hướng dẫn viên; guided cũng đồng thời là phân từ hai của động từ guide.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_motel', 'en-b1-6', 'motel', '/moʊˈtel/', 'B1', 'khách sạn ven đường', 'n.', NULL, NULL, 'motel chủ yếu phục vụ khách du lịch đi xe hơi, thường cung cấp chỗ đỗ xe thuận tiện.', 'We found a quiet motel just outside the town.', NULL, 'Chúng tôi tìm thấy một nhà nghỉ ven đường yên tĩnh ngay ngoài thị trấn.', '{"wordId":"motel","ukIpa":"/məʊˈtel/","usIpa":"/moʊˈtel/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A roadside hotel with convenient parking for guests.","vi":"khách sạn ven đường"}],"examples":[{"en":"We found a quiet motel just outside the town.","vi":"Chúng tôi tìm thấy một nhà nghỉ ven đường yên tĩnh ngay ngoài thị trấn.","audioKind":"ex"},{"en":"Affordable motels along major roads provide convenient accommodation for travellers exploring rural areas by car.","vi":"Các nhà nghỉ giá cả phải chăng dọc theo các tuyến đường chính cung cấp chỗ ở tiện lợi cho du khách tự lái xe khám phá các vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"stay at a motel","vi":"ở tại khách sạn ven đường"},{"en":"roadside motel","vi":"khách sạn ven đường"},{"en":"motel room","vi":"phòng khách sạn ven đường"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"motel chủ yếu phục vụ khách du lịch đi xe hơi, thường cung cấp chỗ đỗ xe thuận tiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_southern', 'en-b1-6', 'southern', '/ˈsʌðərn/', 'B1', 'thuộc về miền Nam; ở phía nam', 'adj.', 'south (n.), southward (adv.), southerly (adj.)', 'Trái nghĩa: northern', 'Trong từ ''south'', phần ''ou'' đọc là /aʊ/, nhưng nguyên âm trong ''southern'' lại đọc là /ʌ/.', 'We spent a week exploring the island''s southern coast.', NULL, 'Chúng tôi đã dành một tuần để khám phá bờ biển phía nam của hòn đảo.', '{"wordId":"southern","ukIpa":"/ˈsʌðən/","usIpa":"/ˈsʌðərn/","cefr":"B1","topic":"travel","senses":[{"pos":"adj.","en":"Located in, coming from, or relating to the south.","vi":"thuộc về miền Nam; ở phía nam"}],"examples":[{"en":"We spent a week exploring the island''s southern coast.","vi":"Chúng tôi đã dành một tuần để khám phá bờ biển phía nam của hòn đảo.","audioKind":"ex"},{"en":"Southern regions of the country may face longer droughts as rising temperatures increase pressure on water supplies.","vi":"Các vùng phía nam của đất nước có thể phải đối mặt với tình trạng hạn hán kéo dài hơn khi nhiệt độ tăng cao làm gia tăng áp lực lên nguồn cung cấp nước.","audioKind":"ex2"}],"collocations":[{"en":"southern coast","vi":"bờ biển phía nam"},{"en":"southern hemisphere","vi":"nam bán cầu"},{"en":"southern regions","vi":"các vùng phía nam"},{"en":"southern border","vi":"biên giới phía nam"}],"wordFamily":["south (n.)","southward (adv.)","southerly (adj.)"],"synonyms":[],"antonyms":["northern"],"tipVi":"Trong từ ''south'', phần ''ou'' đọc là /aʊ/, nhưng nguyên âm trong ''southern'' lại đọc là /ʌ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_harbour', 'en-b1-6', 'harbour', '/ˈhɑːrbər/', 'B1', 'cảng biển; bến cảng; ấp ủ; nuôi dưỡng (ý nghĩ, cảm xúc); che giấu; dung túng (tội phạm, người bị truy nã)', 'n.', NULL, NULL, 'Cách viết harbour là Anh-Anh, còn harbor là Anh-Mỹ.', 'Small fishing boats returned to the harbour before sunset.', NULL, 'Những chiếc thuyền đánh cá nhỏ đã quay trở lại bến cảng trước khi mặt trời lặn.', '{"wordId":"harbour","ukIpa":"/ˈhɑːbə/","usIpa":"/ˈhɑːrbər/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A sheltered area of water where boats can stay safely.","vi":"cảng biển; bến cảng"},{"pos":"v.","en":"To keep a thought or feeling, often secretly.","vi":"ấp ủ; nuôi dưỡng (ý nghĩ, cảm xúc)"},{"pos":"v.","en":"To hide or shelter someone, especially someone wanted by authorities.","vi":"che giấu; dung túng (tội phạm, người bị truy nã)"}],"examples":[{"en":"Small fishing boats returned to the harbour before sunset.","vi":"Những chiếc thuyền đánh cá nhỏ đã quay trở lại bến cảng trước khi mặt trời lặn.","audioKind":"ex"},{"en":"Expanding the harbour could increase trade, but construction may damage nearby coastal habitats.","vi":"Việc mở rộng cảng biển có thể thúc đẩy thương mại, nhưng quá trình thi công có thể gây tổn hại đến các hệ sinh thái ven biển gần đó.","audioKind":"ex2"}],"collocations":[{"en":"a natural harbour","vi":"một cảng tự nhiên"},{"en":"harbour doubts","vi":"nuôi dưỡng mối nghi ngờ"},{"en":"harbour a grudge","vi":"ôm hận trong lòng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cách viết harbour là Anh-Anh, còn harbor là Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_highway', 'en-b1-6', 'highway', '/ˈhaɪweɪ/', 'B1', 'quốc lộ; đường cao tốc chính', 'n.', NULL, 'Đồng nghĩa: main road', 'Thường gặp trong tiếng Anh Mỹ; không nhất thiết phải là đường cao tốc khép kín.', 'We followed the highway along the coast until sunset.', NULL, 'Chúng tôi lái xe dọc theo con đường cao tốc ven biển cho đến khi mặt trời lặn.', '{"wordId":"highway","ukIpa":"/ˈhaɪweɪ/","usIpa":"/ˈhaɪweɪ/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"a main public road connecting towns or cities","vi":"quốc lộ; đường cao tốc chính"}],"examples":[{"en":"We followed the highway along the coast until sunset.","vi":"Chúng tôi lái xe dọc theo con đường cao tốc ven biển cho đến khi mặt trời lặn.","audioKind":"ex"},{"en":"Building a new highway may reduce travel times but also damage nearby wildlife habitats.","vi":"Việc xây dựng một tuyến quốc lộ mới có thể rút ngắn thời gian di chuyển nhưng đồng thời cũng làm tổn hại đến môi trường sống của động vật hoang dã ở khu vực lân cận.","audioKind":"ex2"}],"collocations":[{"en":"major highway","vi":"đường cao tốc lớn"},{"en":"highway construction","vi":"việc xây dựng đường cao tốc"},{"en":"highway maintenance","vi":"bảo trì đường cao tốc"}],"wordFamily":[],"synonyms":["main road"],"antonyms":[],"tipVi":"Thường gặp trong tiếng Anh Mỹ; không nhất thiết phải là đường cao tốc khép kín.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accommodation', 'en-b1-6', 'accommodation', '/əˌkɑːməˈdeɪʃən/', 'B1', 'chỗ ở; nơi ở; sự dàn xếp; thỏa thuận thỏa đáng', 'n.', 'accommodate (v.), accommodating (adj.)', 'Đồng nghĩa: lodging, housing', 'Trong tiếng Anh-Anh, từ chỉ chỗ ở thường là danh từ không đếm được; hãy chú ý viết đúng hai chữ c và hai chữ m.', 'We found cheap accommodation near the beach last summer.', NULL, 'Chúng tôi đã tìm được chỗ ở giá rẻ gần bãi biển vào mùa hè năm ngoái.', '{"wordId":"accommodation","ukIpa":"/əˌkɒməˈdeɪʃən/","usIpa":"/əˌkɑːməˈdeɪʃən/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"a place where someone can live or stay","vi":"chỗ ở; nơi ở"},{"pos":"n.","en":"an arrangement that meets different needs or settles a disagreement","vi":"sự dàn xếp; thỏa thuận thỏa đáng"}],"examples":[{"en":"We found cheap accommodation near the beach last summer.","vi":"Chúng tôi đã tìm được chỗ ở giá rẻ gần bãi biển vào mùa hè năm ngoái.","audioKind":"ex"},{"en":"Universities should provide affordable accommodation so that students from disadvantaged backgrounds can study without excessive financial pressure.","vi":"Các trường đại học nên cung cấp chỗ ở giá cả phải chăng để sinh viên có hoàn cảnh khó khăn có thể học tập mà không phải chịu áp lực tài chính quá lớn.","audioKind":"ex2"}],"collocations":[{"en":"student accommodation","vi":"chỗ ở cho sinh viên"},{"en":"affordable accommodation","vi":"chỗ ở giá rẻ"},{"en":"temporary accommodation","vi":"chỗ ở tạm thời"},{"en":"reach an accommodation","vi":"đạt được thỏa thuận"}],"wordFamily":["accommodate (v.)","accommodating (adj.)"],"synonyms":["lodging","housing"],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, từ chỉ chỗ ở thường là danh từ không đếm được; hãy chú ý viết đúng hai chữ c và hai chữ m.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_visa', 'en-b1-6', 'visa', '/ˈviːzə/', 'B1', 'thị thực; visa', 'n.', NULL, NULL, 'visa là thị thực, passport là hộ chiếu; thường cần có hộ chiếu để xin cấp visa.', 'My student visa arrived just before the flight.', NULL, 'Visa du học của tôi đã được cấp ngay trước chuyến bay.', '{"wordId":"visa","ukIpa":"/ˈviːzə/","usIpa":"/ˈviːzə/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"Official permission to enter or stay in a foreign country.","vi":"thị thực; visa"}],"examples":[{"en":"My student visa arrived just before the flight.","vi":"Visa du học của tôi đã được cấp ngay trước chuyến bay.","audioKind":"ex"},{"en":"Simpler visa procedures can encourage international students to study abroad and contribute to local economies.","vi":"Thủ tục visa đơn giản hơn có thể khuyến khích sinh viên quốc tế đi du học và đóng góp cho nền kinh tế địa phương.","audioKind":"ex2"}],"collocations":[{"en":"apply for a visa","vi":"nộp đơn xin visa"},{"en":"student visa","vi":"visa du học"},{"en":"visa application","vi":"đơn xin cấp visa"},{"en":"visa requirements","vi":"yêu cầu về visa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"visa là thị thực, passport là hộ chiếu; thường cần có hộ chiếu để xin cấp visa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_buffet', 'en-b1-6', 'buffet', '/bəˈfeɪ/', 'B1', 'tiệc tự chọn; tiệc buffet; quầy bán đồ ăn nhẹ (ở nhà ga hoặc trên tàu)', 'n.', NULL, NULL, 'Khi mang nghĩa "tiệc tự chọn", âm "t" là âm câm; động từ mang nghĩa "đánh mạnh" đọc là /ˈbʌfɪt/.', 'We helped ourselves to fresh fruit at the breakfast buffet.', NULL, 'Chúng tôi tự lấy trái cây tươi tại quầy ăn sáng tự chọn.', '{"wordId":"buffet","ukIpa":"/ˈbʊfeɪ/","usIpa":"/bəˈfeɪ/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A meal where people serve themselves from dishes set out.","vi":"tiệc tự chọn; tiệc buffet"},{"pos":"n.","en":"A small place selling refreshments at a station or on a train.","vi":"quầy bán đồ ăn nhẹ (ở nhà ga hoặc trên tàu)"}],"examples":[{"en":"We helped ourselves to fresh fruit at the breakfast buffet.","vi":"Chúng tôi tự lấy trái cây tươi tại quầy ăn sáng tự chọn.","audioKind":"ex"},{"en":"Hotels can reduce food waste by offering smaller portions and replenishing buffet dishes more frequently.","vi":"Các khách sạn có thể giảm lãng phí thực phẩm bằng cách phục vụ khẩu phần nhỏ hơn và bổ sung các món ăn tự chọn thường xuyên hơn.","audioKind":"ex2"}],"collocations":[{"en":"a buffet breakfast","vi":"bữa sáng tự chọn"},{"en":"a buffet lunch","vi":"bữa trưa tự chọn"},{"en":"a buffet car","vi":"toa ăn uống (trên tàu)"},{"en":"a cold buffet","vi":"tiệc nguội tự chọn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa \"tiệc tự chọn\", âm \"t\" là âm câm; động từ mang nghĩa \"đánh mạnh\" đọc là /ˈbʌfɪt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boarding', 'en-b1-6', 'boarding', '/ˈbɔːrdɪŋ/', 'B1', 'quá trình lên máy bay, tàu hoặc phương tiện khác; sự lưu trú có kèm bữa ăn, đặc biệt là tại trường học; vật liệu bằng gỗ dùng để che phủ bề mặt', 'n.', 'board (v.), boarder (n.)', NULL, 'Dùng làm danh từ để chỉ quá trình lên tàu xe; cũng có thể đóng vai trò là phân từ hiện tại của động từ board.', 'We bought some sandwiches before boarding began this morning.', NULL, 'Chúng tôi đã mua vài chiếc bánh mì trước khi quá trình lên máy bay bắt đầu vào sáng nay.', '{"wordId":"boarding","ukIpa":"/ˈbɔːdɪŋ/","usIpa":"/ˈbɔːrdɪŋ/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"The process of getting onto an aircraft, ship, or other vehicle.","vi":"quá trình lên máy bay, tàu hoặc phương tiện khác"},{"pos":"n.","en":"Staying somewhere with meals provided, especially at school.","vi":"sự lưu trú có kèm bữa ăn, đặc biệt là tại trường học"},{"pos":"n.","en":"Wooden boards used together to cover a surface.","vi":"vật liệu bằng gỗ dùng để che phủ bề mặt"}],"examples":[{"en":"We bought some sandwiches before boarding began this morning.","vi":"Chúng tôi đã mua vài chiếc bánh mì trước khi quá trình lên máy bay bắt đầu vào sáng nay.","audioKind":"ex"},{"en":"Airports can reduce boarding delays by providing clearer instructions and additional assistance for passengers with limited mobility.","vi":"Các sân bay có thể giảm thiểu tình trạng chậm trễ khi lên máy bay bằng cách cung cấp hướng dẫn rõ ràng hơn và hỗ trợ thêm cho hành khách đi lại khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"boarding pass","vi":"thẻ lên máy bay"},{"en":"boarding gate","vi":"cửa lên máy bay"},{"en":"boarding school","vi":"trường nội trú"},{"en":"priority boarding","vi":"lên máy bay ưu tiên"}],"wordFamily":["board (v.)","boarder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng làm danh từ để chỉ quá trình lên tàu xe; cũng có thể đóng vai trò là phân từ hiện tại của động từ board.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beyond', 'en-b1-6', 'beyond', '/bɪˈjɑːnd/', 'B1', 'ở phía bên kia; vượt ra xa hơn; vượt quá; ngoài; ở phía xa hơn', 'prep.', NULL, NULL, 'beyond không chỉ dùng để chỉ vị trí vật lý mà còn diễn tả việc vượt quá năng lực hoặc giới hạn.', 'A narrow path leads to the beach beyond the dunes.', NULL, 'Một con đường nhỏ hẹp dẫn ra bãi biển nằm ở phía bên kia các cồn cát.', '{"wordId":"beyond","ukIpa":"/bɪˈjɒnd/","usIpa":"/bɪˈjɑːnd/","cefr":"B1","topic":"travel","senses":[{"pos":"prep.","en":"on the farther side of something","vi":"ở phía bên kia; vượt ra xa hơn"},{"pos":"prep.","en":"outside a particular limit, range, or ability","vi":"vượt quá; ngoài"},{"pos":"adv.","en":"at or towards a place farther away","vi":"ở phía xa hơn"}],"examples":[{"en":"A narrow path leads to the beach beyond the dunes.","vi":"Một con đường nhỏ hẹp dẫn ra bãi biển nằm ở phía bên kia các cồn cát.","audioKind":"ex"},{"en":"The benefits of university education extend beyond employment prospects to include personal growth and greater social awareness.","vi":"Lợi ích của giáo dục đại học vượt ra ngoài triển vọng việc làm, bao gồm cả sự phát triển cá nhân và ý thức xã hội cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"beyond repair","vi":"hư hỏng nặng không thể sửa chữa"},{"en":"beyond reach","vi":"với không tới"},{"en":"beyond recognition","vi":"biến dạng không nhận ra"},{"en":"go beyond","vi":"vượt ra ngoài"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"beyond không chỉ dùng để chỉ vị trí vật lý mà còn diễn tả việc vượt quá năng lực hoặc giới hạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arrival', 'en-b1-6', 'arrival', '/əˈraɪvəl/', 'B1', 'sự đến; sự cập bến; sự tới nơi; người mới đến; vật mới đến', 'n.', 'arrive (v.)', 'Trái nghĩa: departure', 'On arrival có nghĩa là khi đến nơi, tương đương với upon arrival.', 'Our arrival at the campsite was delayed by heavy rain.', NULL, 'Việc chúng tôi đến khu cắm trại đã bị trì hoãn bởi cơn mưa lớn.', '{"wordId":"arrival","ukIpa":"/əˈraɪvəl/","usIpa":"/əˈraɪvəl/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"The act of reaching a place.","vi":"sự đến; sự cập bến; sự tới nơi"},{"pos":"n.","en":"A person or thing that has recently reached a place.","vi":"người mới đến; vật mới đến"}],"examples":[{"en":"Our arrival at the campsite was delayed by heavy rain.","vi":"Việc chúng tôi đến khu cắm trại đã bị trì hoãn bởi cơn mưa lớn.","audioKind":"ex"},{"en":"The arrival of faster rail services has made smaller towns more attractive to commuters seeking affordable housing.","vi":"Sự xuất hiện của các dịch vụ đường sắt nhanh hơn đã làm cho các thị trấn nhỏ trở nên hấp dẫn hơn đối với những người đi làm tìm kiếm nhà ở giá rẻ.","audioKind":"ex2"}],"collocations":[{"en":"on arrival","vi":"ngay khi đến"},{"en":"arrival time","vi":"thời gian đến"},{"en":"new arrival","vi":"người mới đến"},{"en":"arrival at the airport","vi":"việc đến sân bay"}],"wordFamily":["arrive (v.)"],"synonyms":[],"antonyms":["departure"],"tipVi":"On arrival có nghĩa là khi đến nơi, tương đương với upon arrival.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_campsite', 'en-b1-6', 'campsite', '/ˈkæmpsaɪt/', 'B1', 'khu cắm trại', 'n.', 'camp (v.), camping (n.), camper (n.)', 'Đồng nghĩa: campground', 'Tiếng Anh-Anh dùng campsite, trong khi tiếng Anh-Mỹ thường dùng campground.', 'We found a quiet campsite beside the lake.', NULL, 'Chúng tôi tìm thấy một khu cắm trại yên tĩnh cạnh hồ.', '{"wordId":"campsite","ukIpa":"/ˈkæmpsaɪt/","usIpa":"/ˈkæmpsaɪt/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A place where people can stay in tents.","vi":"khu cắm trại"}],"examples":[{"en":"We found a quiet campsite beside the lake.","vi":"Chúng tôi tìm thấy một khu cắm trại yên tĩnh cạnh hồ.","audioKind":"ex"},{"en":"Well-managed campsites allow visitors to enjoy natural landscapes while limiting damage to local ecosystems.","vi":"Các khu cắm trại được quản lý tốt cho phép du khách thưởng ngoạn phong cảnh thiên nhiên đồng thời hạn chế tổn hại đến hệ sinh thái địa phương.","audioKind":"ex2"}],"collocations":[{"en":"stay at a campsite","vi":"ở lại một khu cắm trại"},{"en":"book a campsite","vi":"đặt chỗ cắm trại"},{"en":"a lakeside campsite","vi":"khu cắm trại bên hồ"}],"wordFamily":["camp (v.)","camping (n.)","camper (n.)"],"synonyms":["campground"],"antonyms":[],"tipVi":"Tiếng Anh-Anh dùng campsite, trong khi tiếng Anh-Mỹ thường dùng campground.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_take-off', 'en-b1-6', 'take-off', '/ˈteɪk ɔːf/', 'B1', 'sự cas cánh; lúc cất cánh; sự bắt chước hài hước', 'n.', 'take off (v.)', 'Trái nghĩa: landing', 'Danh từ viết là take-off; động từ viết là take off không có dấu gạch nối.', 'Please keep your seat belt fastened during take-off.', NULL, 'Xin vui lòng thắt dây an toàn trong suốt quá trình cất cánh.', '{"wordId":"take-off","ukIpa":"/ˈteɪk ɒf/","usIpa":"/ˈteɪk ɔːf/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"The moment an aircraft leaves the ground.","vi":"sự cas cánh; lúc cất cánh"},{"pos":"n.","en":"An amusing imitation of a person or performance.","vi":"sự bắt chước hài hước"}],"examples":[{"en":"Please keep your seat belt fastened during take-off.","vi":"Xin vui lòng thắt dây an toàn trong suốt quá trình cất cánh.","audioKind":"ex"},{"en":"Aircraft noise during take-off can significantly affect the quality of life in communities near major airports.","vi":"Tiếng ồn của máy bay trong lúc cất cánh có thể ảnh hưởng đáng kể đến chất lượng cuộc sống của cộng đồng dân cư gần các sân bay lớn.","audioKind":"ex2"}],"collocations":[{"en":"during take-off","vi":"trong lúc cất cánh"},{"en":"prepare for take-off","vi":"chuẩn bị cất cánh"},{"en":"take-off speed","vi":"tốc độ cất cánh"}],"wordFamily":["take off (v.)"],"synonyms":[],"antonyms":["landing"],"tipVi":"Danh từ viết là take-off; động từ viết là take off không có dấu gạch nối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_manila', 'en-b1-6', 'Manila', '/məˈnɪlə/', 'B1', 'Manila (thủ đô của Philippines)', 'n.', NULL, NULL, 'Tên thành phố phải viết hoa chữ cái đầu; từ manila viết thường thường chỉ giấy manila hoặc các chất liệu tương tự.', 'Our flight landed in Manila just before sunset.', NULL, 'Chuyến bay của chúng tôi hạ cánh xuống Manila ngay trước khi hoàng hôn buông xuống.', '{"wordId":"manila","ukIpa":"/məˈnɪlə/","usIpa":"/məˈnɪlə/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"The capital city of the Philippines.","vi":"Manila (thủ đô của Philippines)"}],"examples":[{"en":"Our flight landed in Manila just before sunset.","vi":"Chuyến bay của chúng tôi hạ cánh xuống Manila ngay trước khi hoàng hôn buông xuống.","audioKind":"ex"},{"en":"Coastal cities such as Manila need resilient infrastructure to reduce the risks associated with flooding.","vi":"Các thành phố ven biển như Manila cần có cơ sở hạ tầng kiên cố để giảm thiểu các rủi ro liên quan đến ngập lụt.","audioKind":"ex2"}],"collocations":[{"en":"Manila Bay","vi":"vịnh Manila"},{"en":"central Manila","vi":"trung tâm Manila"},{"en":"a flight to Manila","vi":"chuyến bay đi Manila"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên thành phố phải viết hoa chữ cái đầu; từ manila viết thường thường chỉ giấy manila hoặc các chất liệu tương tự.","noteVi":"Tên riêng địa danh phải luôn được viết hoa chữ cái đầu thành Manila.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_departure', 'en-b1-6', 'departure', '/dɪˈpɑːrtʃər/', 'B1', 'sự rời đi; sự khởi hành; sự thay đổi; sự khác biệt', 'n.', 'depart (v.)', 'Trái nghĩa: arrival', 'Cụm departure from có thể mang nghĩa là "sự khởi hành từ..." hoặc "sự đi chệch khỏi... / sự thay đổi so với...".', 'We packed our bags the night before departure.', NULL, 'Chúng tôi đã thu dọn hành lý vào đêm trước ngày khởi hành.', '{"wordId":"departure","ukIpa":"/dɪˈpɑːtʃə/","usIpa":"/dɪˈpɑːrtʃər/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"The act of leaving a place.","vi":"sự rời đi; sự khởi hành"},{"pos":"n.","en":"A change from what is usual or expected.","vi":"sự thay đổi; sự khác biệt"}],"examples":[{"en":"We packed our bags the night before departure.","vi":"Chúng tôi đã thu dọn hành lý vào đêm trước ngày khởi hành.","audioKind":"ex"},{"en":"The new housing policy represents a significant departure from previous approaches to urban development.","vi":"Chính sách nhà ở mới này đánh dấu một sự thay đổi đáng kể so với các phương pháp phát triển đô thị trước đây.","audioKind":"ex2"}],"collocations":[{"en":"departure time","vi":"giờ khởi hành"},{"en":"departure lounge","vi":"phòng chờ khởi hành"},{"en":"a departure from tradition","vi":"sự phá cách so với truyền thống"}],"wordFamily":["depart (v.)"],"synonyms":[],"antonyms":["arrival"],"tipVi":"Cụm departure from có thể mang nghĩa là \"sự khởi hành từ...\" hoặc \"sự đi chệch khỏi... / sự thay đổi so với...\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gasoline', 'en-b1-6', 'gasoline', '/ˈɡæsəliːn/', 'B1', 'xăng', 'n.', NULL, 'Đồng nghĩa: petrol, gas', 'Tiếng Anh-Mỹ dùng gasoline, văn nói thường gọi là gas; tiếng Anh-Anh thường dùng petrol.', 'We stopped to buy gasoline before crossing the desert.', NULL, 'Chúng tôi đã dừng lại để mua xăng trước khi băng qua sa mạc.', '{"wordId":"gasoline","ukIpa":"/ˈɡæsəliːn/","usIpa":"/ˈɡæsəliːn/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A liquid fuel used in cars and other engines.","vi":"xăng"}],"examples":[{"en":"We stopped to buy gasoline before crossing the desert.","vi":"Chúng tôi đã dừng lại để mua xăng trước khi băng qua sa mạc.","audioKind":"ex"},{"en":"Higher gasoline prices may encourage commuters to share cars or switch to public transport.","vi":"Giá xăng cao hơn có thể khuyến khích những người đi làm xa chung xe đi lại hoặc chuyển sang sử dụng phương tiện giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"gasoline prices","vi":"giá xăng"},{"en":"gasoline engine","vi":"động cơ xăng"},{"en":"unleaded gasoline","vi":"xăng không chì"}],"wordFamily":[],"synonyms":["petrol","gas"],"antonyms":[],"tipVi":"Tiếng Anh-Mỹ dùng gasoline, văn nói thường gọi là gas; tiếng Anh-Anh thường dùng petrol.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_caravan', 'en-b1-6', 'caravan', '/ˈkærəvæn/', 'B1', 'xe nhà lưu động (kéo theo sau ô tô); đoàn người hoặc đoàn xe đi cùng nhau (nhất là qua sa mạc)', 'n.', 'caravanning (n.)', NULL, 'Trong tiếng Anh-Anh chỉ xe nhà lưu động kéo theo sau ô tô; tiếng Anh-Mỹ thường dùng "travel trailer".', 'We parked our caravan beside a quiet lake.', NULL, 'Chúng tôi đỗ chiếc xe nhà lưu động bên cạnh một hồ nước yên tĩnh.', '{"wordId":"caravan","ukIpa":"/ˈkærəvæn/","usIpa":"/ˈkærəvæn/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A wheeled home pulled by a car, especially for holidays","vi":"xe nhà lưu động (kéo theo sau ô tô)"},{"pos":"n.","en":"A group of people or vehicles travelling together, especially through deserts","vi":"đoàn người hoặc đoàn xe đi cùng nhau (nhất là qua sa mạc)"}],"examples":[{"en":"We parked our caravan beside a quiet lake.","vi":"Chúng tôi đỗ chiếc xe nhà lưu động bên cạnh một hồ nước yên tĩnh.","audioKind":"ex"},{"en":"Caravan holidays can support rural tourism by bringing visitors to areas without large hotels.","vi":"Những kỳ nghỉ bằng xe nhà lưu động có thể hỗ trợ du lịch nông thôn bằng cách đưa du khách đến những khu vực không có khách sạn lớn.","audioKind":"ex2"}],"collocations":[{"en":"caravan park","vi":"bãi đỗ xe nhà lưu động"},{"en":"tow a caravan","vi":"kéo xe nhà lưu động"},{"en":"camel caravan","vi":"đoàn lạc đà thồ hàng"}],"wordFamily":["caravanning (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh chỉ xe nhà lưu động kéo theo sau ô tô; tiếng Anh-Mỹ thường dùng \"travel trailer\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unpack', 'en-b1-6', 'unpack', '/ʌnˈpæk/', 'B1', 'dỡ đồ (khỏi túi, hộp, vali); phân tích; giải thích chi tiết', 'v.', 'pack (v.), packing (n.), repack (v.)', 'Trái nghĩa: pack', 'Có thể dùng để chỉ việc lấy đồ ra khỏi hành lý, hoặc dùng theo nghĩa bóng là mổ xẻ một quan điểm phức tạp.', 'I unpacked my suitcase and hung up my shirts.', NULL, 'Tôi dỡ vali và treo những chiếc áo sơ mi của mình lên.', '{"wordId":"unpack","ukIpa":"/ʌnˈpæk/","usIpa":"/ʌnˈpæk/","cefr":"B1","topic":"travel","senses":[{"pos":"v.","en":"take things out of a bag, box, or other container","vi":"dỡ đồ (khỏi túi, hộp, vali)"},{"pos":"v.","en":"examine an idea carefully to explain its different parts","vi":"phân tích; giải thích chi tiết"}],"examples":[{"en":"I unpacked my suitcase and hung up my shirts.","vi":"Tôi dỡ vali và treo những chiếc áo sơ mi của mình lên.","audioKind":"ex"},{"en":"Teachers can help students unpack complex arguments by examining the evidence and assumptions behind each claim.","vi":"Giáo viên có thể giúp học sinh phân tích các lập luận phức tạp bằng cách xem xét các bằng chứng và giả định đằng sau mỗi luận điểm.","audioKind":"ex2"}],"collocations":[{"en":"unpack a suitcase","vi":"dỡ đồ trong vali"},{"en":"unpack boxes","vi":"mở hộp lấy đồ"},{"en":"unpack an argument","vi":"phân tích một lập luận"}],"wordFamily":["pack (v.)","packing (n.)","repack (v.)"],"synonyms":[],"antonyms":["pack"],"tipVi":"Có thể dùng để chỉ việc lấy đồ ra khỏi hành lý, hoặc dùng theo nghĩa bóng là mổ xẻ một quan điểm phức tạp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_explore', 'en-b1-6', 'explore', '/ɪkˈsplɔːr/', 'B1', 'khám phá; thám hiểm; nghiên cứu; tìm hiểu; thảo luận sâu', 'v.', 'exploration (n.), explorer (n.), exploratory (adj.)', 'Đồng nghĩa: investigate, examine', 'Khi là ngoại động từ, explore đi trực tiếp với địa điểm hoặc vấn đề mà không cần dùng giới từ about.', 'We spent the afternoon exploring narrow streets near the harbour.', NULL, 'Chúng tôi đã dành cả buổi chiều để khám phá những con phố hẹp gần cảng.', '{"wordId":"explore","ukIpa":"/ɪkˈsplɔː/","usIpa":"/ɪkˈsplɔːr/","cefr":"B1","topic":"travel","senses":[{"pos":"v.","en":"Travel around a place to discover what it is like","vi":"khám phá; thám hiểm"},{"pos":"v.","en":"Examine an idea or issue carefully to learn more","vi":"nghiên cứu; tìm hiểu; thảo luận sâu"}],"examples":[{"en":"We spent the afternoon exploring narrow streets near the harbour.","vi":"Chúng tôi đã dành cả buổi chiều để khám phá những con phố hẹp gần cảng.","audioKind":"ex"},{"en":"Schools should encourage students to explore different career options before choosing subjects for further study.","vi":"Các trường học nên khuyến khích học sinh tìm hiểu các lựa chọn nghề nghiệp khác nhau trước khi chọn môn học để học lên cao.","audioKind":"ex2"}],"collocations":[{"en":"explore the area","vi":"khám phá khu vực"},{"en":"explore possibilities","vi":"khám phá các khả năng"},{"en":"explore an issue","vi":"thảo luận một vấn đề"}],"wordFamily":["exploration (n.)","explorer (n.)","exploratory (adj.)"],"synonyms":["investigate","examine"],"antonyms":[],"tipVi":"Khi là ngoại động từ, explore đi trực tiếp với địa điểm hoặc vấn đề mà không cần dùng giới từ about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transportation', 'en-b1-6', 'transportation', '/ˌtrænspərˈteɪʃən/', 'B1', 'sự vận chuyển; hệ thống giao thông', 'n.', 'transport (v.), transportable (adj.), transporter (n.)', 'Đồng nghĩa: transport', 'Mỹ thường dùng transportation, Anh thường dùng transport.', 'We arranged transportation from the airport to our hotel.', NULL, 'Chúng tôi đã sắp xếp xe đưa đón từ sân bay về khách sạn.', '{"wordId":"transportation","ukIpa":"/ˌtrænspɔːˈteɪʃən/","usIpa":"/ˌtrænspərˈteɪʃən/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"Moving people or goods, or the systems used for this.","vi":"sự vận chuyển; hệ thống giao thông"}],"examples":[{"en":"We arranged transportation from the airport to our hotel.","vi":"Chúng tôi đã sắp xếp xe đưa đón từ sân bay về khách sạn.","audioKind":"ex"},{"en":"Reliable public transportation can reduce traffic congestion and make employment opportunities more accessible to people without cars.","vi":"Hệ thống giao thông công cộng đáng tin cậy có thể làm giảm tình trạng tắc nghẽn giao thông và giúp những người không có ô tô dễ dàng tiếp cận các cơ hội việc làm hơn.","audioKind":"ex2"}],"collocations":[{"en":"public transportation","vi":"giao thông công cộng"},{"en":"transportation costs","vi":"chi phí vận chuyển"},{"en":"transportation network","vi":"mạng lưới giao thông"},{"en":"transportation of goods","vi":"vận chuyển hàng hóa"}],"wordFamily":["transport (v.)","transportable (adj.)","transporter (n.)"],"synonyms":["transport"],"antonyms":[],"tipVi":"Mỹ thường dùng transportation, Anh thường dùng transport.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_via', 'en-b1-6', 'via', '/ˈvaɪə/', 'B1', 'qua; đi qua; thông qua; bằng; thông qua (phương pháp, hệ thống, người)', 'prep.', NULL, NULL, 'via đứng trực tiếp trước địa điểm hoặc phương thức, ví dụ via email.', 'We travelled to the coast via a small mountain village.', NULL, 'Chúng tôi đã đi đến vùng ven biển qua một ngôi làng nhỏ trên núi.', '{"wordId":"via","ukIpa":"/ˈvaɪə/","usIpa":"/ˈvaɪə/","cefr":"B1","topic":"travel","senses":[{"pos":"prep.","en":"travelling through a particular place on the way somewhere","vi":"qua; đi qua; thông qua"},{"pos":"prep.","en":"using a particular method, system, or person","vi":"bằng; thông qua (phương pháp, hệ thống, người)"}],"examples":[{"en":"We travelled to the coast via a small mountain village.","vi":"Chúng tôi đã đi đến vùng ven biển qua một ngôi làng nhỏ trên núi.","audioKind":"ex"},{"en":"Providing medical advice via video calls can improve access to healthcare for people in remote communities.","vi":"Việc cung cấp tư vấn y tế thông qua các cuộc gọi video có thể cải thiện khả năng tiếp cận dịch vụ chăm sóc sức khỏe cho người dân ở các vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"travel via","vi":"đi qua"},{"en":"via email","vi":"thông qua email"},{"en":"via satellite","vi":"thông qua vệ tinh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"via đứng trực tiếp trước địa điểm hoặc phương thức, ví dụ via email.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rail', 'en-b1-6', 'rail', '/reɪl/', 'B1', 'đường ray; vận tải đường sắt; lan tỏa; lan can; thanh ngang; lên án gay gắt; chỉ trích', 'n.', 'railing (n.)', NULL, 'by rail có nghĩa là đi bằng tàu hỏa, không dùng mạo từ; động từ thường đi với against.', 'We travelled by rail through the snowy mountains.', NULL, 'Chúng tôi đã đi du lịch bằng tàu hỏa qua những ngọn núi phủ đầy tuyết trắng.', '{"wordId":"rail","ukIpa":"/reɪl/","usIpa":"/reɪl/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"a steel track for trains, or transport by train","vi":"đường ray; vận tải đường sắt"},{"pos":"n.","en":"a horizontal bar used for support or as a barrier","vi":"lan tỏa; lan can; thanh ngang"},{"pos":"v.","en":"to complain angrily and strongly about something","vi":"lên án gay gắt; chỉ trích"}],"examples":[{"en":"We travelled by rail through the snowy mountains.","vi":"Chúng tôi đã đi du lịch bằng tàu hỏa qua những ngọn núi phủ đầy tuyết trắng.","audioKind":"ex"},{"en":"Investment in rail infrastructure can reduce road congestion and provide a cleaner alternative to domestic flights.","vi":"Đầu tư vào cơ sở hạ tầng đường sắt có thể làm giảm tắc nghẽn đường bộ và cung cấp một lựa chọn xanh hơn so với các chuyến bay nội địa.","audioKind":"ex2"}],"collocations":[{"en":"travel by rail","vi":"đi bằng tàu hỏa"},{"en":"rail network","vi":"mạng lưới đường sắt"},{"en":"hold onto the rail","vi":"bám chặt lấy tay vịn"},{"en":"rail against","vi":"chỉ trích gay gắt"}],"wordFamily":["railing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"by rail có nghĩa là đi bằng tàu hỏa, không dùng mạo từ; động từ thường đi với against.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ferry', 'en-b1-6', 'ferry', '/ˈferi/', 'B1', 'tàu phà; phà; chuyên chở; đưa đón', 'n.', NULL, NULL, 'Dạng số nhiều của danh từ là ferries; động từ cũng có thể chỉ việc dùng phương tiện để vận chuyển lặp đi lặp lại.', 'We took the ferry across the lake this morning.', NULL, 'Chúng tôi đã đi phà băng qua hồ vào sáng nay.', '{"wordId":"ferry","ukIpa":"/ˈferi/","usIpa":"/ˈferi/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A boat carrying passengers or vehicles across water regularly.","vi":"tàu phà; phà"},{"pos":"v.","en":"To carry people or goods between places, often repeatedly.","vi":"chuyên chở; đưa đón"}],"examples":[{"en":"We took the ferry across the lake this morning.","vi":"Chúng tôi đã đi phà băng qua hồ vào sáng nay.","audioKind":"ex"},{"en":"Reliable ferry services connect island communities with mainland hospitals, schools, and employment opportunities throughout the year.","vi":"Các dịch vụ phà đáng tin cậy kết nối các cộng đồng trên đảo với các bệnh viện, trường học và cơ hội việc làm ở đất liền quanh năm.","audioKind":"ex2"}],"collocations":[{"en":"take a ferry","vi":"đi phà"},{"en":"ferry terminal","vi":"bến phà"},{"en":"ferry service","vi":"dịch vụ phà"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều của danh từ là ferries; động từ cũng có thể chỉ việc dùng phương tiện để vận chuyển lặp đi lặp lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delay', 'en-b1-6', 'delay', '/dɪˈleɪ/', 'B1', 'làm chậm trễ; hoãn lại; sự trì hoãn; khoảng thời gian chờ đợi', 'v.', 'delayed (adj.)', 'Đồng nghĩa: postpone', 'Sau động từ delay dùng động từ thêm -ing (delay doing), không dùng to do.', 'Heavy snow delayed our flight until the next morning.', NULL, 'Tuyết rơi dày đặc đã làm chuyến bay của chúng tôi bị hoãn đến sáng hôm sau.', '{"wordId":"delay","ukIpa":"/dɪˈleɪ/","usIpa":"/dɪˈleɪ/","cefr":"B1","topic":"travel","senses":[{"pos":"v.","en":"To make something happen later than expected or planned.","vi":"làm chậm trễ; hoãn lại"},{"pos":"n.","en":"A period of waiting before something happens or continues.","vi":"sự trì hoãn; khoảng thời gian chờ đợi"}],"examples":[{"en":"Heavy snow delayed our flight until the next morning.","vi":"Tuyết rơi dày đặc đã làm chuyến bay của chúng tôi bị hoãn đến sáng hôm sau.","audioKind":"ex"},{"en":"Delays in public transport can reduce productivity and discourage people from leaving their cars at home.","vi":"Sự chậm trễ trong giao thông công cộng có thể làm giảm năng suất lao động và khiến mọi người ngại từ bỏ việc lái xe cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"delay a decision","vi":"hoãn một quyết định"},{"en":"a lengthy delay","vi":"sự chậm trễ kéo dài"},{"en":"without delay","vi":"ngay lập tức; không chậm trễ"},{"en":"delay doing something","vi":"trì hoãn làm việc gì"}],"wordFamily":["delayed (adj.)"],"synonyms":["postpone"],"antonyms":[],"tipVi":"Sau động từ delay dùng động từ thêm -ing (delay doing), không dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_6_1', 'en-b1-6', 'Cách dùng “Manila” (n.) — Manila (thủ đô của Philippines)', 'Manila Bay  ·  central Manila  ·  a flight to Manila', 'Tên thành phố phải viết hoa chữ cái đầu; từ manila viết thường thường chỉ giấy manila hoặc các chất liệu tương tự.', NULL, '[{"hanzi":"Our flight landed in Manila just before sunset.","pinyin":"","meaning":"Chuyến bay của chúng tôi hạ cánh xuống Manila ngay trước khi hoàng hôn buông xuống."},{"hanzi":"Coastal cities such as Manila need resilient infrastructure to reduce the risks associated with flooding.","pinyin":"","meaning":"Các thành phố ven biển như Manila cần có cơ sở hạ tầng kiên cố để giảm thiểu các rủi ro liên quan đến ngập lụt."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_6_2', 'en-b1-6', 'Cách dùng “ferry” (n.) — tàu phà; phà', 'take a ferry  ·  ferry terminal  ·  ferry service', 'Dạng số nhiều của danh từ là ferries; động từ cũng có thể chỉ việc dùng phương tiện để vận chuyển lặp đi lặp lại.', NULL, '[{"hanzi":"We took the ferry across the lake this morning.","pinyin":"","meaning":"Chúng tôi đã đi phà băng qua hồ vào sáng nay."},{"hanzi":"Reliable ferry services connect island communities with mainland hospitals, schools, and employment opportunities throughout the year.","pinyin":"","meaning":"Các dịch vụ phà đáng tin cậy kết nối các cộng đồng trên đảo với các bệnh viện, trường học và cơ hội việc làm ở đất liền quanh năm."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_6_3', 'en-b1-6', 'Cách dùng “departure” (n.) — sự rời đi; sự khởi hành', 'departure time  ·  departure lounge  ·  a departure from tradition', 'Cụm departure from có thể mang nghĩa là "sự khởi hành từ..." hoặc "sự đi chệch khỏi... / sự thay đổi so với...".', 'Họ từ (Word Family): depart (v.) | Trái nghĩa: arrival', '[{"hanzi":"We packed our bags the night before departure.","pinyin":"","meaning":"Chúng tôi đã thu dọn hành lý vào đêm trước ngày khởi hành."},{"hanzi":"The new housing policy represents a significant departure from previous approaches to urban development.","pinyin":"","meaning":"Chính sách nhà ở mới này đánh dấu một sự thay đổi đáng kể so với các phương pháp phát triển đô thị trước đây."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_6_4', 'en-b1-6', 'Cách dùng “accommodation” (n.) — chỗ ở; nơi ở', 'student accommodation  ·  affordable accommodation  ·  temporary accommodation', 'Trong tiếng Anh-Anh, từ chỉ chỗ ở thường là danh từ không đếm được; hãy chú ý viết đúng hai chữ c và hai chữ m.', 'Họ từ (Word Family): accommodate (v.), accommodating (adj.) | Đồng nghĩa: lodging, housing', '[{"hanzi":"We found cheap accommodation near the beach last summer.","pinyin":"","meaning":"Chúng tôi đã tìm được chỗ ở giá rẻ gần bãi biển vào mùa hè năm ngoái."},{"hanzi":"Universities should provide affordable accommodation so that students from disadvantaged backgrounds can study without excessive financial pressure.","pinyin":"","meaning":"Các trường đại học nên cung cấp chỗ ở giá cả phải chăng để sinh viên có hoàn cảnh khó khăn có thể học tập mà không phải chịu áp lực tài chính quá lớn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_6_1', 'en-b1-6', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
