INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_6_1_3', 'ten_b1_6_1', 'motel', 'We found a quiet motel just outside the town.', 'We found a quiet motel just outside the town.', '/moʊˈtel/', 'Chúng tôi tìm thấy một nhà nghỉ ven đường yên tĩnh ngay ngoài thị trấn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_6_1_4', 'ten_b1_6_1', 'southern', 'We spent a week exploring the island''s southern coast.', 'We spent a week exploring the island''s southern coast.', '/ˈsʌðərn/', 'Chúng tôi đã dành một tuần để khám phá bờ biển phía nam của hòn đảo.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_6_1_5', 'ten_b1_6_1', 'harbour', 'Small fishing boats returned to the harbour before sunset.', 'Small fishing boats returned to the harbour before sunset.', '/ˈhɑːrbər/', 'Những chiếc thuyền đánh cá nhỏ đã quay trở lại bến cảng trước khi mặt trời lặn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_6_1_6', 'ten_b1_6_1', 'highway', 'We followed the highway along the coast until sunset.', 'We followed the highway along the coast until sunset.', '/ˈhaɪweɪ/', 'Chúng tôi lái xe dọc theo con đường cao tốc ven biển cho đến khi mặt trời lặn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_6_1_7', 'ten_b1_6_1', 'accommodation', 'We found cheap accommodation near the beach last summer.', 'We found cheap accommodation near the beach last summer.', '/əˌkɑːməˈdeɪʃən/', 'Chúng tôi đã tìm được chỗ ở giá rẻ gần bãi biển vào mùa hè năm ngoái.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_6_1_8', 'ten_b1_6_1', 'visa', 'My student visa arrived just before the flight.', 'My student visa arrived just before the flight.', '/ˈviːzə/', 'Visa du học của tôi đã được cấp ngay trước chuyến bay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_6_1_1', 'en-b1-6', 'ten_b1_6_1', 'listening', 'listening', 'The cyclist stopped beside the bridge for water.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã mua vài chiếc bánh mì trước khi quá trình lên máy bay bắt đầu vào sáng nay.","Người đi xe đạp dừng lại bên cầu để uống nước.","Chúng tôi lái xe dọc theo con đường cao tốc ven biển cho đến khi mặt trời lặn.","Chuyến bay của chúng tôi hạ cánh xuống Manila ngay trước khi hoàng hôn buông xuống."]'::jsonb, 1, 'The cyclist stopped beside the bridge for water. → Người đi xe đạp dừng lại bên cầu để uống nước.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_6_1_2', 'en-b1-6', 'ten_b1_6_1', 'listening', 'listening', 'We joined a guided walk through the forest yesterday.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hôm qua chúng tôi đã tham gia một chuyến đi bộ xuyên rừng có người hướng dẫn.","Việc chúng tôi đến khu cắm trại đã bị trì hoãn bởi cơn mưa lớn.","Chúng tôi đã sắp xếp xe đưa đón từ sân bay về khách sạn.","Chúng tôi lái xe dọc theo con đường cao tốc ven biển cho đến khi mặt trời lặn."]'::jsonb, 0, 'We joined a guided walk through the forest yesterday. → Hôm qua chúng tôi đã tham gia một chuyến đi bộ xuyên rừng có người hướng dẫn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_6_1_3', 'en-b1-6', 'ten_b1_6_1', 'listening', 'listening', 'We found a quiet motel just outside the town.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi tìm thấy một nhà nghỉ ven đường yên tĩnh ngay ngoài thị trấn.","Chuyến bay của chúng tôi hạ cánh xuống Manila ngay trước khi hoàng hôn buông xuống.","Chúng tôi đã dành cả buổi chiều để khám phá những con phố hẹp gần cảng.","Những chiếc thuyền đánh cá nhỏ đã quay trở lại bến cảng trước khi mặt trời lặn."]'::jsonb, 0, 'We found a quiet motel just outside the town. → Chúng tôi tìm thấy một nhà nghỉ ven đường yên tĩnh ngay ngoài thị trấn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_6_2', 'en-b1-6', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_6_2_1', 'ten_b1_6_2', 'cyclist', 'Protected cycle lanes can reduce the risk of collisions between cyclists and motor vehicles in busy cities.', 'Protected cycle lanes can reduce the risk of collisions between cyclists and motor vehicles in busy cities.', '/ˈsaɪklɪst/', 'Các làn đường dành riêng cho xe đạp được bảo vệ có thể làm giảm nguy cơ va chạm giữa người đi xe đạp và xe cơ giới ở các thành phố đông đúc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_6_2_2', 'ten_b1_6_2', 'guided', 'Guided learning can help students build confidence before they begin working independently on complex tasks.', 'Guided learning can help students build confidence before they begin working independently on complex tasks.', '/ˈɡaɪdɪd/', 'Việc học tập có hướng dẫn giúp học sinh xây dựng sự tự tin trước khi bắt đầu tự mình thực hiện các nhiệm vụ phức tạp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_6_2_3', 'ten_b1_6_2', 'motel', 'Affordable motels along major roads provide convenient accommodation for travellers exploring rural areas by car.', 'Affordable motels along major roads provide convenient accommodation for travellers exploring rural areas by car.', '/moʊˈtel/', 'Các nhà nghỉ giá cả phải chăng dọc theo các tuyến đường chính cung cấp chỗ ở tiện lợi cho du khách tự lái xe khám phá các vùng nông thôn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_6_2_4', 'ten_b1_6_2', 'southern', 'Southern regions of the country may face longer droughts as rising temperatures increase pressure on water supplies.', 'Southern regions of the country may face longer droughts as rising temperatures increase pressure on water supplies.', '/ˈsʌðərn/', 'Các vùng phía nam của đất nước có thể phải đối mặt với tình trạng hạn hán kéo dài hơn khi nhiệt độ tăng cao làm gia tăng áp lực lên nguồn cung cấp nước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_6_2_5', 'ten_b1_6_2', 'harbour', 'Expanding the harbour could increase trade, but construction may damage nearby coastal habitats.', 'Expanding the harbour could increase trade, but construction may damage nearby coastal habitats.', '/ˈhɑːrbər/', 'Việc mở rộng cảng biển có thể thúc đẩy thương mại, nhưng quá trình thi công có thể gây tổn hại đến các hệ sinh thái ven biển gần đó.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_6_2_6', 'ten_b1_6_2', 'highway', 'Building a new highway may reduce travel times but also damage nearby wildlife habitats.', 'Building a new highway may reduce travel times but also damage nearby wildlife habitats.', '/ˈhaɪweɪ/', 'Việc xây dựng một tuyến quốc lộ mới có thể rút ngắn thời gian di chuyển nhưng đồng thời cũng làm tổn hại đến môi trường sống của động vật hoang dã ở khu vực lân cận.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_6_2_1', 'en-b1-6', 'ten_b1_6_2', 'listening', 'listening', 'Protected cycle lanes can reduce the risk of collisions between cyclists and motor vehicles in busy cities.', NULL, 'Trong câu vừa nghe, từ “cyclist” mang nghĩa nào sau đây?', '["cuộc thi; cuộc đấu tranh","làm rối trí; làm bối rối; làm hoang mang","người đi xe đạp","lợi ích; ưu điểm"]'::jsonb, 2, '“cyclist” (/ˈsaɪklɪst/): người đi xe đạp. Câu đầy đủ: Protected cycle lanes can reduce the risk of collisions between cyclists and motor vehicles in busy cities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_6_2_2', 'en-b1-6', 'ten_b1_6_2', 'listening', 'listening', 'Guided learning can help students build confidence before they begin working independently on complex tasks.', NULL, 'Trong câu vừa nghe, từ “guided” mang nghĩa nào sau đây?', '["giấc ngủ ngắn; giờ nghỉ trưa","có hướng dẫn; có người dẫn đường","bài tập giữ gìn vóc dáng; thể dục giữ vóc dáng","kẻ ngốc; người hành động thiếu khôn ngoan"]'::jsonb, 1, '“guided” (/ˈɡaɪdɪd/): có hướng dẫn; có người dẫn đường. Câu đầy đủ: Guided learning can help students build confidence before they begin working independently on complex tasks.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
