INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_2', 'en-b1-6', NULL, 'comprehensive_test', 'listening', 'We joined a guided walk through the forest yesterday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hôm qua chúng tôi đã tham gia một chuyến đi bộ xuyên rừng có người hướng dẫn.","Chúng tôi tự lấy trái cây tươi tại quầy ăn sáng tự chọn.","Chúng tôi lái xe dọc theo con đường cao tốc ven biển cho đến khi mặt trời lặn.","Việc chúng tôi đến khu cắm trại đã bị trì hoãn bởi cơn mưa lớn."]'::jsonb, 0, 'We joined a guided walk through the forest yesterday. → Hôm qua chúng tôi đã tham gia một chuyến đi bộ xuyên rừng có người hướng dẫn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
