INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_4', 'en-b1-6', NULL, 'comprehensive_test', 'listening', 'We spent a week exploring the island''s southern coast.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hôm qua chúng tôi đã tham gia một chuyến đi bộ xuyên rừng có người hướng dẫn.","Chúng tôi đã đi du lịch bằng tàu hỏa qua những ngọn núi phủ đầy tuyết trắng.","Chúng tôi đã dành một tuần để khám phá bờ biển phía nam của hòn đảo.","Chúng tôi đỗ chiếc xe nhà lưu động bên cạnh một hồ nước yên tĩnh."]'::jsonb, 2, 'We spent a week exploring the island''s southern coast. → Chúng tôi đã dành một tuần để khám phá bờ biển phía nam của hòn đảo.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_5', 'en-b1-6', NULL, 'comprehensive_test', 'listening', 'harbour', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cảng biển; bến cảng","khiếm thính; điếc","trang trí; bày biện","người bán thịt; thợ mổ thịt"]'::jsonb, 0, 'harbour (/ˈhɑːrbər/) → cảng biển; bến cảng; ấp ủ; nuôi dưỡng (ý nghĩ, cảm xúc); che giấu; dung túng (tội phạm, người bị truy nã)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_6', 'en-b1-6', NULL, 'comprehensive_test', 'listening', 'We followed the highway along the coast until sunset.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chuyến bay của chúng tôi hạ cánh xuống Manila ngay trước khi hoàng hôn buông xuống.","Chúng tôi đỗ chiếc xe nhà lưu động bên cạnh một hồ nước yên tĩnh.","Visa du học của tôi đã được cấp ngay trước chuyến bay.","Chúng tôi lái xe dọc theo con đường cao tốc ven biển cho đến khi mặt trời lặn."]'::jsonb, 3, 'We followed the highway along the coast until sunset. → Chúng tôi lái xe dọc theo con đường cao tốc ven biển cho đến khi mặt trời lặn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_7', 'en-b1-6', NULL, 'comprehensive_test', 'listening', 'accommodation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["rủi ro; nguy cơ","chỗ ở; nơi ở","cuộc thi; cuộc đấu tranh","chương (sách); hồi"]'::jsonb, 1, 'accommodation (/əˌkɑːməˈdeɪʃən/) → chỗ ở; nơi ở; sự dàn xếp; thỏa thuận thỏa đáng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_8', 'en-b1-6', NULL, 'comprehensive_test', 'listening', 'My student visa arrived just before the flight.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Visa du học của tôi đã được cấp ngay trước chuyến bay.","Chúng tôi tự lấy trái cây tươi tại quầy ăn sáng tự chọn.","Chúng tôi đỗ chiếc xe nhà lưu động bên cạnh một hồ nước yên tĩnh.","Chúng tôi đã mua vài chiếc bánh mì trước khi quá trình lên máy bay bắt đầu vào sáng nay."]'::jsonb, 0, 'My student visa arrived just before the flight. → Visa du học của tôi đã được cấp ngay trước chuyến bay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_9', 'en-b1-6', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A sheltered area of water where boats can stay safely.”?', '["guided","highway","Manila","harbour"]'::jsonb, 3, 'harbour (/ˈhɑːrbər/) → cảng biển; bến cảng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_10', 'en-b1-6', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a main public road connecting towns or cities”?', '["highway","cyclist","explore","campsite"]'::jsonb, 0, 'highway (/ˈhaɪweɪ/) → quốc lộ; đường cao tốc chính', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_11', 'en-b1-6', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a place where someone can live or stay”?', '["Manila","southern","accommodation","beyond"]'::jsonb, 2, 'accommodation (/əˌkɑːməˈdeɪʃən/) → chỗ ở; nơi ở', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
