INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_18', 'en-b1-6', NULL, 'comprehensive_test', 'reading', NULL, 'Protected cycle lanes can reduce the risk of collisions between cyclists and motor vehicles in busy cities.', 'Dựa vào câu trên, từ “cyclist” có nghĩa phù hợp nhất là gì?', '["sự hài hước; khiếu hài hước","nhà gỗ nhỏ; lều gỗ","người đi xe đạp","sự thật; chân lý"]'::jsonb, 2, 'cyclist: người đi xe đạp. Dịch cả câu: Các làn đường dành riêng cho xe đạp được bảo vệ có thể làm giảm nguy cơ va chạm giữa người đi xe đạp và xe cơ giới ở các thành phố đông đúc.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_19', 'en-b1-6', NULL, 'comprehensive_test', 'reading', NULL, 'Guided learning can help students build confidence before they begin working independently on complex tasks.', 'Dựa vào câu trên, từ “guided” có nghĩa phù hợp nhất là gì?', '["gian lận; chơi gian","giọng điệu, khẩu âm","sự gian lận; hành vi gian lận","có hướng dẫn; có người dẫn đường"]'::jsonb, 3, 'guided: có hướng dẫn; có người dẫn đường. Dịch cả câu: Việc học tập có hướng dẫn giúp học sinh xây dựng sự tự tin trước khi bắt đầu tự mình thực hiện các nhiệm vụ phức tạp.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_20', 'en-b1-6', NULL, 'comprehensive_test', 'reading', NULL, 'Affordable motels along major roads provide convenient accommodation for travellers exploring rural areas by car.', 'Dựa vào câu trên, từ “motel” có nghĩa phù hợp nhất là gì?', '["sự giảm giá; chiết khấu","cực kỳ ngạc nhiên và buồn bã trước điều gì đó bất ngờ; bị sốc; bàng hoàng","khách sạn ven đường","ngoài trời; lộ thiên"]'::jsonb, 2, 'motel: khách sạn ven đường. Dịch cả câu: Các nhà nghỉ giá cả phải chăng dọc theo các tuyến đường chính cung cấp chỗ ở tiện lợi cho du khách tự lái xe khám phá các vùng nông thôn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_21', 'en-b1-6', NULL, 'comprehensive_test', 'reading', NULL, 'Southern regions of the country may face longer droughts as rising temperatures increase pressure on water supplies.', 'Dựa vào câu trên, từ “southern” có nghĩa phù hợp nhất là gì?', '["thuộc về miền Nam; ở phía nam","hàng tháng; mỗi tháng một lần","thường; nhìn chung","cụ thể; riêng"]'::jsonb, 0, 'southern: thuộc về miền Nam; ở phía nam. Dịch cả câu: Các vùng phía nam của đất nước có thể phải đối mặt với tình trạng hạn hán kéo dài hơn khi nhiệt độ tăng cao làm gia tăng áp lực lên nguồn cung cấp nước.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_6_22', 'en-b1-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đường ray; vận tải đường sắt”', '["stripes","smooth","rail","hardly"]'::jsonb, 2, 'đường ray; vận tải đường sắt → rail (/reɪl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
