INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-7', 'en', 'Bài 7: Du lịch & Di chuyển (3) - CEFR B1', 'CEFR B1', 'B1 · Du lịch', '25 từ vựng Tiếng Anh CEFR B1 chủ đề du lịch & di chuyển kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3007, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_customs', 'en-b1-7', 'customs', '/ˈkʌstəmz/', 'B1', 'hải quan; thuế quan; thuế hải quan; thói quen; phong tục tập quán', 'n.', 'custom (n.), customary (adj.), customarily (adv.)', NULL, 'Khi chỉ hải quan phải giữ nguyên đuôi s; từ custom ở dạng số ít không mang nghĩa hải quan.', 'We opened our suitcases for inspection at customs.', NULL, 'Chúng tôi đã mở vali để kiểm tra tại khu vực hải quan.', '{"wordId":"customs","ukIpa":"/ˈkʌstəmz/","usIpa":"/ˈkʌstəmz/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"The authority or place checking goods entering a country","vi":"hải quan"},{"pos":"n.","en":"Taxes charged on goods brought into a country","vi":"thuế quan; thuế hải quan"},{"pos":"n.","en":"Traditional practices shared by a community or social group","vi":"thói quen; phong tục tập quán"}],"examples":[{"en":"We opened our suitcases for inspection at customs.","vi":"Chúng tôi đã mở vali để kiểm tra tại khu vực hải quan.","audioKind":"ex"},{"en":"More efficient customs procedures can reduce delays at borders and support international trade without weakening security.","vi":"Quy trình hải quan hiệu quả hơn có thể làm giảm tình trạng chậm trễ ở biên giới và hỗ trợ thương mại quốc tế mà không làm suy giảm an ninh.","audioKind":"ex2"}],"collocations":[{"en":"go through customs","vi":"làm thủ tục hải quan"},{"en":"customs officer","vi":"cán bộ hải quan"},{"en":"customs duty","vi":"thuế hải quan"},{"en":"local customs","vi":"phong tục địa phương"}],"wordFamily":["custom (n.)","customary (adj.)","customarily (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ hải quan phải giữ nguyên đuôi s; từ custom ở dạng số ít không mang nghĩa hải quan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_farther', 'en-b1-7', 'farther', '/ˈfɑːrðər/', 'B1', 'xa hơn (về khoảng cách); ở xa hơn về phía trước hoặc khoảng cách lớn hơn', 'adv.', 'far (adv), farthest (adv)', 'Đồng nghĩa: further · Trái nghĩa: nearer', 'farther thường chỉ khoảng cách vật lý thực tế; further dùng cho sự tiến triển hoặc trừu tượng hơn.', 'We walked farther along the beach before stopping for lunch.', NULL, 'Chúng tôi đi bộ xa hơn dọc theo bãi biển trước khi dừng lại ăn trưa.', '{"wordId":"farther","ukIpa":"/ˈfɑːðə/","usIpa":"/ˈfɑːrðər/","cefr":"B1","topic":"travel","senses":[{"pos":"adv.","en":"At or to a greater distance.","vi":"xa hơn (về khoảng cách)"},{"pos":"adj.","en":"Located at a greater distance.","vi":"ở xa hơn về phía trước hoặc khoảng cách lớn hơn"}],"examples":[{"en":"We walked farther along the beach before stopping for lunch.","vi":"Chúng tôi đi bộ xa hơn dọc theo bãi biển trước khi dừng lại ăn trưa.","audioKind":"ex"},{"en":"As housing costs rise, many workers move farther from city centres and face longer daily commutes.","vi":"Khi chi phí nhà ở tăng lên, nhiều người lao động chuyển đến sống ở những nơi xa trung tâm thành phố hơn và phải đối mặt với thời gian di chuyển đi làm hằng ngày lâu hơn.","audioKind":"ex2"}],"collocations":[{"en":"farther away","vi":"xa hơn nữa"},{"en":"farther north","vi":"xa hơn về phía bắc"},{"en":"farther from home","vi":"xa nhà hơn"}],"wordFamily":["far (adv)","farthest (adv)"],"synonyms":["further"],"antonyms":["nearer"],"tipVi":"farther thường chỉ khoảng cách vật lý thực tế; further dùng cho sự tiến triển hoặc trừu tượng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_western', 'en-b1-7', 'western', '/ˈwestərn/', 'B1', 'thuộc về phía tây; phía tây; thuộc phương Tây; phương Tây; phim cao bồi miền Tây', 'adj.', 'west (n.), westward (adv.), westerner (n.)', 'Trái nghĩa: eastern', 'Khi chỉ các quốc gia hoặc nền văn hóa phương Tây, từ này thường được viết hoa thành Western.', 'Our cabin faces the lake on its western shore.', NULL, 'Nhà gỗ của chúng tôi nằm ở bờ phía tây của hồ.', '{"wordId":"western","ukIpa":"/ˈwestən/","usIpa":"/ˈwestərn/","cefr":"B1","topic":"travel","senses":[{"pos":"adj.","en":"In, from, or relating to the west of an area.","vi":"thuộc về phía tây; phía tây"},{"pos":"adj.","en":"Relating to Europe, North America, and their associated cultures.","vi":"thuộc phương Tây; phương Tây"},{"pos":"n.","en":"A film or story about the historical American West.","vi":"phim cao bồi miền Tây"}],"examples":[{"en":"Our cabin faces the lake on its western shore.","vi":"Nhà gỗ của chúng tôi nằm ở bờ phía tây của hồ.","audioKind":"ex"},{"en":"Investment in western regions could improve transport links and reduce economic inequalities within the country.","vi":"Đầu tư vào các khu vực miền tây có thể cải thiện kết nối giao thông và giảm bất bình đẳng kinh tế trong nước.","audioKind":"ex2"}],"collocations":[{"en":"the western coast","vi":"bờ biển phía tây"},{"en":"western regions","vi":"các khu vực miền tây"},{"en":"Western culture","vi":"văn hóa phương Tây"},{"en":"a western film","vi":"phim miền Tây"}],"wordFamily":["west (n.)","westward (adv.)","westerner (n.)"],"synonyms":[],"antonyms":["eastern"],"tipVi":"Khi chỉ các quốc gia hoặc nền văn hóa phương Tây, từ này thường được viết hoa thành Western.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_landing', 'en-b1-7', 'landing', '/ˈlændɪŋ/', 'B1', 'sự hạ cánh; sự cập bến; chiếu nghỉ (khu vực phẳng ở đầu hoặc giữa các bậc cầu thang)', 'n.', 'land (v.)', 'Trái nghĩa: take-off', 'Ngoài nghĩa hạ cánh, từ này còn chỉ khoảng không gian phẳng ở đầu hoặc giữa các bậc thang.', 'The plane made a smooth landing despite the wind.', NULL, 'Máy bay hạ cánh êm ái bất chấp gió lớn.', '{"wordId":"landing","ukIpa":"/ˈlændɪŋ/","usIpa":"/ˈlændɪŋ/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"The act of reaching the ground or shore.","vi":"sự hạ cánh; sự cập bến"},{"pos":"n.","en":"A flat area at the top of or between stairs.","vi":"chiếu nghỉ (khu vực phẳng ở đầu hoặc giữa các bậc cầu thang)"}],"examples":[{"en":"The plane made a smooth landing despite the wind.","vi":"Máy bay hạ cánh êm ái bất chấp gió lớn.","audioKind":"ex"},{"en":"Improved weather forecasting can help pilots prepare for a safe landing during rapidly changing conditions.","vi":"Công tác dự báo thời tiết được cải thiện có thể giúp phi công chuẩn bị cho một cuộc hạ cánh an toàn trong điều kiện thời tiết thay đổi nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"emergency landing","vi":"hạ cánh khẩn cấp"},{"en":"smooth landing","vi":"hạ cánh êm ái"},{"en":"landing gear","vi":"hệ thống càng đáp"},{"en":"upstairs landing","vi":"chiếu nghỉ cầu thang trên lầu"}],"wordFamily":["land (v.)"],"synonyms":[],"antonyms":["take-off"],"tipVi":"Ngoài nghĩa hạ cánh, từ này còn chỉ khoảng không gian phẳng ở đầu hoặc giữa các bậc thang.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reservation', 'en-b1-7', 'reservation', '/ˌrezɚˈveɪʃən/', 'B1', 'sự đặt chỗ; sự đặt trước; sự nghi ngờ; sự e dè', 'n.', 'reserve (v.), reserved (adj.)', 'Đồng nghĩa: booking', 'Để diễn tả sự nghi ngờ, người ta thường dùng số nhiều: "have reservations about".', 'I made a reservation for dinner by the window.', NULL, 'Tôi đã đặt một bàn cạnh cửa sổ cho bữa tối.', '{"wordId":"reservation","ukIpa":"/ˌrezəˈveɪʃən/","usIpa":"/ˌrezɚˈveɪʃən/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"An arrangement to keep a room, seat, or table available.","vi":"sự đặt chỗ; sự đặt trước"},{"pos":"n.","en":"A doubt that prevents complete acceptance of something.","vi":"sự nghi ngờ; sự e dè"}],"examples":[{"en":"I made a reservation for dinner by the window.","vi":"Tôi đã đặt một bàn cạnh cửa sổ cho bữa tối.","audioKind":"ex"},{"en":"Some residents expressed reservations about the proposed airport expansion because of increased noise pollution.","vi":"Một số cư dân bày tỏ sự e dè về dự án mở rộng sân bay được đề xuất do ô nhiễm tiếng ồn gia tăng.","audioKind":"ex2"}],"collocations":[{"en":"make a reservation","vi":"đặt chỗ"},{"en":"cancel a reservation","vi":"hủy đặt chỗ"},{"en":"have reservations about","vi":"có sự nghi ngờ về"},{"en":"without reservation","vi":"hoàn toàn không ngần ngại"}],"wordFamily":["reserve (v.)","reserved (adj.)"],"synonyms":["booking"],"antonyms":[],"tipVi":"Để diễn tả sự nghi ngờ, người ta thường dùng số nhiều: \"have reservations about\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_canal', 'en-b1-7', 'canal', '/kəˈnæl/', 'B1', 'kênh; kênh đào; ống dẫn (trong cơ thể)', 'n.', NULL, NULL, 'Canal thường là đường nước nhân tạo; river chỉ sông tự nhiên.', 'We watched a narrow boat glide along the canal.', NULL, 'Chúng tôi ngắm nhìn một chiếc thuyền hẹp lướt êm đềm dọc theo con kênh đào.', '{"wordId":"canal","ukIpa":"/kəˈnæl/","usIpa":"/kəˈnæl/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"an artificial waterway for boats or carrying water","vi":"kênh; kênh đào"},{"pos":"n.","en":"a narrow passage inside the body","vi":"ống dẫn (trong cơ thể)"}],"examples":[{"en":"We watched a narrow boat glide along the canal.","vi":"Chúng tôi ngắm nhìn một chiếc thuyền hẹp lướt êm đềm dọc theo con kênh đào.","audioKind":"ex"},{"en":"Restoring historic canals can attract tourists while providing valuable habitats for wildlife in densely populated urban areas.","vi":"Việc phục hồi các con kênh lịch sử có thể thu hút khách du lịch đồng thời cung cấp môi trường sống quý giá cho động vật hoang dã ở các khu đô thị đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"irrigation canal","vi":"kênh tưới tiêu"},{"en":"canal boat","vi":"thuyền đi kênh"},{"en":"ear canal","vi":"ống tai"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Canal thường là đường nước nhân tạo; river chỉ sông tự nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cottage', 'en-b1-7', 'cottage', '/ˈkɑːtɪdʒ/', 'B1', 'nhà tranh; nhà nghỉ nông thôn; nhà nhỏ ở vùng quê', 'n.', NULL, NULL, 'Thường chỉ nhà ở nhỏ vùng nông thôn, không đồng nghĩa với biệt thự (villa) sang trọng.', 'Their cottage has a tiny garden full of roses.', NULL, 'Ngôi nhà tranh của họ có một khu vườn nhỏ xinh ngập tràn hoa hồng.', '{"wordId":"cottage","ukIpa":"/ˈkɒtɪdʒ/","usIpa":"/ˈkɑːtɪdʒ/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A small house, usually in the countryside.","vi":"nhà tranh; nhà nghỉ nông thôn; nhà nhỏ ở vùng quê"}],"examples":[{"en":"Their cottage has a tiny garden full of roses.","vi":"Ngôi nhà tranh của họ có một khu vườn nhỏ xinh ngập tràn hoa hồng.","audioKind":"ex"},{"en":"Converting an unused cottage into holiday accommodation can provide rural families with an additional source of income.","vi":"Việc chuyển đổi một ngôi nhà nông thôn không sử dụng thành nơi lưu trú nghỉ dưỡng có thể mang lại cho các gia đình nông thôn một nguồn thu nhập bổ sung.","audioKind":"ex2"}],"collocations":[{"en":"a country cottage","vi":"nhà tranh vùng quê"},{"en":"a thatched cottage","vi":"nhà tranh mái tranh"},{"en":"a holiday cottage","vi":"nhà nghỉ dưỡng nông thôn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ nhà ở nhỏ vùng nông thôn, không đồng nghĩa với biệt thự (villa) sang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_duty-free', 'en-b1-7', 'duty-free', '/ˌduːti ˈfriː/', 'B1', 'miễn thuế', 'adj.', 'duty (n.), dutiable (adj.)', 'Trái nghĩa: dutiable', 'Duty ở đây chỉ thuế quan; hàng miễn thuế vẫn tuân theo hạn mức nhập cảnh.', 'She bought some duty-free perfume before boarding her flight.', NULL, 'Cô ấy mua một ít nước hoa miễn thuế trước khi lên máyบิน.', '{"wordId":"duty-free","ukIpa":"/ˌdjuːti ˈfriː/","usIpa":"/ˌduːti ˈfriː/","cefr":"B1","topic":"travel","senses":[{"pos":"adj.","en":"Sold without certain taxes, especially to international travellers.","vi":"miễn thuế"},{"pos":"adv.","en":"Without paying certain taxes on goods.","vi":"miễn thuế"}],"examples":[{"en":"She bought some duty-free perfume before boarding her flight.","vi":"Cô ấy mua một ít nước hoa miễn thuế trước khi lên máyบิน.","audioKind":"ex"},{"en":"Duty-free shopping can generate substantial revenue for airports, although travellers may not always find the lowest prices.","vi":"Mua sắm miễn thuế có thể tạo ra doanh thu đáng kể cho các sân bay, mặc dù hành khách không phải lúc nào cũng tìm được mức giá thấp nhất.","audioKind":"ex2"}],"collocations":[{"en":"duty-free shop","vi":"cửa hàng miễn thuế"},{"en":"duty-free goods","vi":"hàng hóa miễn thuế"},{"en":"duty-free allowance","vi":"hạn mức miễn thuế"}],"wordFamily":["duty (n.)","dutiable (adj.)"],"synonyms":[],"antonyms":["dutiable"],"tipVi":"Duty ở đây chỉ thuế quan; hàng miễn thuế vẫn tuân theo hạn mức nhập cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fare', 'en-b1-7', 'fare', '/fer/', 'B1', 'tiền xe; tiền vé; cước phí; tiến triển; làm ăn; sống; đồ ăn; món ăn', 'n.', NULL, NULL, 'fare là tiền vé xe/tàu; fee thường chỉ phí dịch vụ hoặc học phí.', 'I had just enough coins for the bus fare.', NULL, 'Tôi chỉ có vừa đủ tiền lẻ để trả tiền xe buýt.', '{"wordId":"fare","ukIpa":"/feə/","usIpa":"/fer/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"The money paid for a journey on public transport.","vi":"tiền xe; tiền vé; cước phí"},{"pos":"v.","en":"To perform or experience a particular level of success.","vi":"tiến triển; làm ăn; sống"},{"pos":"n.","en":"Food of a particular kind served in a place.","vi":"đồ ăn; món ăn"}],"examples":[{"en":"I had just enough coins for the bus fare.","vi":"Tôi chỉ có vừa đủ tiền lẻ để trả tiền xe buýt.","audioKind":"ex"},{"en":"Reducing train fares could encourage commuters to leave their cars at home and use public transport.","vi":"Việc giảm giá vé tàu có thể khuyến khích những người đi lại hàng ngày bỏ xe ở nhà và sử dụng phương tiện công cộng.","audioKind":"ex2"}],"collocations":[{"en":"bus fare","vi":"tiền vé xe buýt"},{"en":"fare increase","vi":"giá vé tăng"},{"en":"fare well","vi":"làm ăn thuận lợi; tiến triển tốt"},{"en":"traditional fare","vi":"món ăn truyền thống"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"fare là tiền vé xe/tàu; fee thường chỉ phí dịch vụ hoặc học phí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guesthouse', 'en-b1-7', 'guesthouse', '/ˈɡesthaʊs/', 'B1', 'nhà khách; nhà nghỉ gia đình', 'n.', 'guest (n.)', NULL, 'Thường chỉ quy mô nhỏ, không dùng để chỉ khách sạn lớn.', 'We found a cosy guesthouse overlooking the fishing harbour.', NULL, 'Chúng tôi tìm được một nhà nghỉ ấm cúng nhìn ra cảng đánh cá.', '{"wordId":"guesthouse","ukIpa":"/ˈɡesthaʊs/","usIpa":"/ˈɡesthaʊs/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A small place providing paid accommodation, often in someone''s home.","vi":"nhà khách; nhà nghỉ gia đình"}],"examples":[{"en":"We found a cosy guesthouse overlooking the fishing harbour.","vi":"Chúng tôi tìm được một nhà nghỉ ấm cúng nhìn ra cảng đánh cá.","audioKind":"ex"},{"en":"Family-run guesthouses can support rural economies by encouraging tourists to spend money in local communities.","vi":"Các nhà nghỉ do gia đình quản lý có thể hỗ trợ kinh tế nông thôn bằng cách khuyến khích khách du lịch chi tiêu tại các cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"stay at a guesthouse","vi":"ở tại một nhà nghỉ"},{"en":"family-run guesthouse","vi":"nhà nghỉ do gia đình quản lý"},{"en":"seaside guesthouse","vi":"nhà nghỉ bên bờ biển"}],"wordFamily":["guest (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ quy mô nhỏ, không dùng để chỉ khách sạn lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lavatory', 'en-b1-7', 'lavatory', '/ˈlævətɔːri/', 'B1', 'phòng vệ sinh; nhà vệ sinh', 'n.', NULL, 'Đồng nghĩa: toilet, washroom', 'Mang tính trang trọng hơn, phổ biến trong tiếng Anh-Anh; hàng ngày thường dùng "toilet".', 'The lavatory is just beyond the waiting room.', NULL, 'Phòng vệ sinh nằm ngay phía sau phòng đợi.', '{"wordId":"lavatory","ukIpa":"/ˈlævətri/","usIpa":"/ˈlævətɔːri/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A toilet or a room containing one.","vi":"phòng vệ sinh; nhà vệ sinh"}],"examples":[{"en":"The lavatory is just beyond the waiting room.","vi":"Phòng vệ sinh nằm ngay phía sau phòng đợi.","audioKind":"ex"},{"en":"Every passenger carriage should include a lavatory that travellers with limited mobility can access easily.","vi":"Mỗi toa hành khách nên có một phòng vệ sinh mà hành khách khuyết tật có thể dễ dàng tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"public lavatory","vi":"phòng vệ sinh công cộng"},{"en":"lavatory door","vi":"cửa nhà vệ sinh"},{"en":"lavatory facilities","vi":"tiện nghi vệ sinh"}],"wordFamily":[],"synonyms":["toilet","washroom"],"antonyms":[],"tipVi":"Mang tính trang trọng hơn, phổ biến trong tiếng Anh-Anh; hàng ngày thường dùng \"toilet\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nightlife', 'en-b1-7', 'nightlife', '/ˈnaɪtlaɪf/', 'B1', 'hoạt động giải trí về đêm; đời sống về đêm', 'n.', NULL, NULL, 'nightlife thường không đếm được, chỉ các hoạt động giải trí giao lưu về đêm.', 'We enjoyed the city''s nightlife after dinner by the river.', NULL, 'Chúng tôi đã tận hưởng đời sống về đêm của thành phố sau bữa tối bên dòng sông.', '{"wordId":"nightlife","ukIpa":"/ˈnaɪtlaɪf/","usIpa":"/ˈnaɪtlaɪf/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"Entertainment and social activities available in a place at night","vi":"hoạt động giải trí về đêm; đời sống về đêm"}],"examples":[{"en":"We enjoyed the city''s nightlife after dinner by the river.","vi":"Chúng tôi đã tận hưởng đời sống về đêm của thành phố sau bữa tối bên dòng sông.","audioKind":"ex"},{"en":"A vibrant nightlife can attract tourists and create jobs, but noise may disturb local residents.","vi":"Đời sống về đêm sôi động có thể thu hút khách du lịch và tạo ra việc làm, nhưng tiếng ồn có thể làm phiền cư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"vibrant nightlife","vi":"đời sống về đêm sôi động"},{"en":"enjoy the nightlife","vi":"tận hưởng đời sống về đêm"},{"en":"nightlife scene","vi":"khung cảnh giải trí về đêm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"nightlife thường không đếm được, chỉ các hoạt động giải trí giao lưu về đêm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_porter', 'en-b1-7', 'porter', '/ˈpɔːrtər/', 'B1', 'nhân viên khuân vác hành lý (ở khách sạn, nhà ga); người gác cổng; người kiểm soát ra vào tòa nhà', 'n.', NULL, NULL, 'không dùng chung chung cho nhân viên phục vụ, thường chỉ người vác hành lý hoặc người gác cổng.', 'The porter carried our heavy suitcases to the lift.', NULL, 'Nhân viên khuân vác đã mang những chiếc vali nặng của chúng tôi ra thang máy.', '{"wordId":"porter","ukIpa":"/ˈpɔːtə/","usIpa":"/ˈpɔːrtər/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"Someone employed to carry luggage at hotels or stations.","vi":"nhân viên khuân vác hành lý (ở khách sạn, nhà ga)"},{"pos":"n.","en":"Someone who controls entry to a building.","vi":"người gác cổng; người kiểm soát ra vào tòa nhà"}],"examples":[{"en":"The porter carried our heavy suitcases to the lift.","vi":"Nhân viên khuân vác đã mang những chiếc vali nặng của chúng tôi ra thang máy.","audioKind":"ex"},{"en":"Hotels can improve accessibility by training each porter to assist guests with limited mobility.","vi":"Các khách sạn có thể cải thiện khả năng tiếp cận bằng cách đào tạo mỗi nhân viên khuân vác hỗ trợ khách hàng có khả năng vận động hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"hotel porter","vi":"nhân viên khuân vác khách sạn"},{"en":"luggage porter","vi":"nhân viên khuân vác hành lý"},{"en":"night porter","vi":"người gác cửa ca đêm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"không dùng chung chung cho nhân viên phục vụ, thường chỉ người vác hành lý hoặc người gác cổng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sail', 'en-b1-7', 'sail', '/seɪl/', 'B1', 'chèo thuyền; lướt thuyền trên mặt nước; cánh buồm', 'v.', 'sailing (n.), sailor (n.)', NULL, 'Khi là động từ, từ này không chỉ giới hạn ở thuyền buồm mà còn có thể chỉ tàu thuyền nói chung.', 'We sailed across the lake on a sunny afternoon.', NULL, 'Chúng tôi đã chèo thuyền vượt qua hồ vào một buổi chiều đầy nắng.', '{"wordId":"sail","ukIpa":"/seɪl/","usIpa":"/seɪl/","cefr":"B1","topic":"travel","senses":[{"pos":"v.","en":"Travel across water in a boat or ship.","vi":"chèo thuyền; lướt thuyền trên mặt nước"},{"pos":"n.","en":"A large sheet of material that catches wind to move boats.","vi":"cánh buồm"}],"examples":[{"en":"We sailed across the lake on a sunny afternoon.","vi":"Chúng tôi đã chèo thuyền vượt qua hồ vào một buổi chiều đầy nắng.","audioKind":"ex"},{"en":"Ships that sail through sensitive marine habitats should follow strict rules to protect wildlife.","vi":"Các tàu thuyền đi qua các khu vực sinh thái biển nhạy cảm phải tuân thủ các quy định nghiêm ngặt để bảo vệ động thực vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"set sail","vi":"nhổ neo khởi hành; ra khơi"},{"en":"sail across the ocean","vi":"chèo thuyền vượt đại dương"},{"en":"raise the sails","vi":"kéo buồm lên"}],"wordFamily":["sailing (n.)","sailor (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là động từ, từ này không chỉ giới hạn ở thuyền buồm mà còn có thể chỉ tàu thuyền nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_souvenir', 'en-b1-7', 'souvenir', '/ˌsuːvəˈnɪr/', 'B1', 'đồ lưu niệm; quà lưu niệm', 'n.', NULL, 'Đồng nghĩa: memento, keepsake', 'Thường dùng a souvenir of để chỉ kỷ vật của một chuyến đi hoặc sự kiện nào đó.', 'We bought a small wooden boat as a souvenir.', NULL, 'Chúng tôi đã mua một chiếc thuyền gỗ nhỏ làm đồ lưu niệm.', '{"wordId":"souvenir","ukIpa":"/ˌsuːvəˈnɪə/","usIpa":"/ˌsuːvəˈnɪr/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"An object kept to remember a place, person, or event.","vi":"đồ lưu niệm; quà lưu niệm"}],"examples":[{"en":"We bought a small wooden boat as a souvenir.","vi":"Chúng tôi đã mua một chiếc thuyền gỗ nhỏ làm đồ lưu niệm.","audioKind":"ex"},{"en":"Buying a locally made souvenir can support traditional crafts and provide income for communities that depend on tourism.","vi":"Việc mua đồ lưu niệm làm tại địa phương có thể hỗ trợ các nghề thủ công truyền thống và tạo thu nhập cho các cộng đồng phụ thuộc vào du lịch.","audioKind":"ex2"}],"collocations":[{"en":"souvenir shop","vi":"cửa hàng lưu niệm"},{"en":"buy a souvenir","vi":"mua đồ lưu niệm"},{"en":"as a souvenir","vi":"như một món quà lưu niệm"}],"wordFamily":[],"synonyms":["memento","keepsake"],"antonyms":[],"tipVi":"Thường dùng a souvenir of để chỉ kỷ vật của một chuyến đi hoặc sự kiện nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tunnel', 'en-b1-7', 'tunnel', '/ˈtʌnəl/', 'B1', 'hầm; đường hầm; đào hầm; làm hầm', 'n.', 'tunnelling (n.)', NULL, 'Giới từ through thường chỉ hành động đi xuyên qua bên trong đường hầm.', 'The train entered a dark tunnel beneath the hill.', NULL, 'Con tàu lao vào một đường hầm tối đen như mực dưới chân đồi.', '{"wordId":"tunnel","ukIpa":"/ˈtʌnəl/","usIpa":"/ˈtʌnəl/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A passage built underground or through a hill.","vi":"hầm; đường hầm"},{"pos":"v.","en":"To dig a passage underground or through something.","vi":"đào hầm; làm hầm"}],"examples":[{"en":"The train entered a dark tunnel beneath the hill.","vi":"Con tàu lao vào một đường hầm tối đen như mực dưới chân đồi.","audioKind":"ex"},{"en":"Building a tunnel under the river could reduce traffic congestion and improve connections between neighbouring districts.","vi":"Việc xây dựng một đường hầm dưới lòng sông có thể làm giảm tình trạng ùn tắc giao thông và cải thiện kết nối giữa các quận lân cận.","audioKind":"ex2"}],"collocations":[{"en":"railway tunnel","vi":"đường hầm xe lửa"},{"en":"dig a tunnel","vi":"đào hầm"},{"en":"tunnel through","vi":"đào xuyên qua"}],"wordFamily":["tunnelling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Giới từ through thường chỉ hành động đi xuyên qua bên trong đường hầm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hike', 'en-b1-7', 'hike', '/haɪk/', 'B1', 'chuyến đi bộ đường dài; cuộc đi dã ngoại; đi bộ đường dài; đi dã ngoại; sự tăng vọt (giá cả, chi phí)', 'n.', 'hiking (n.), hiker (n.)', 'Đồng nghĩa: trek', 'hike thường chỉ việc đi bộ dài ngoài trời, hoặc sự tăng giá mạnh.', 'Our weekend hike ended beside a clear mountain lake.', NULL, 'Chuyến đi bộ đường dài cuối tuần của chúng tôi kết thúc bên cạnh một hồ nước trong veo trên núi.', '{"wordId":"hike","ukIpa":"/haɪk/","usIpa":"/haɪk/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A long walk, usually through the countryside or mountains.","vi":"chuyến đi bộ đường dài; cuộc đi dã ngoại"},{"pos":"v.","en":"To walk a long distance, especially in natural surroundings.","vi":"đi bộ đường dài; đi dã ngoại"},{"pos":"n.","en":"A large increase in a price, cost, or rate.","vi":"sự tăng vọt (giá cả, chi phí)"}],"examples":[{"en":"Our weekend hike ended beside a clear mountain lake.","vi":"Chuyến đi bộ đường dài cuối tuần của chúng tôi kết thúc bên cạnh một hồ nước trong veo trên núi.","audioKind":"ex"},{"en":"A sharp hike in public transport fares could discourage commuters from choosing buses over private cars.","vi":"Việc tăng vọt giá vé phương tiện giao thông công cộng có thể làm giảm mong muốn chọn xe buýt thay vì xe hơi riêng của những người đi làm.","audioKind":"ex2"}],"collocations":[{"en":"go for a hike","vi":"đi bộ đường dài"},{"en":"mountain hike","vi":"leo núi đi bộ"},{"en":"price hike","vi":"giá cả tăng vọt"}],"wordFamily":["hiking (n.)","hiker (n.)"],"synonyms":["trek"],"antonyms":[],"tipVi":"hike thường chỉ việc đi bộ dài ngoài trời, hoặc sự tăng giá mạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_windscreen', 'en-b1-7', 'windscreen', '/ˈwɪndskriːn/', 'B1', 'kính chắn gió ô tô', 'n.', NULL, 'Đồng nghĩa: windshield', 'Tiếng Anh - Anh dùng windscreen, trong khi tiếng Anh - Mỹ thường dùng windshield.', 'Heavy rain splashed against the windscreen throughout our journey.', NULL, 'Mưa lớn xối xả đập vào kính chắn gió suốt cả chuyến đi của chúng tôi.', '{"wordId":"windscreen","ukIpa":"/ˈwɪndskriːn/","usIpa":"/ˈwɪndskriːn/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"The front window of a car or other vehicle.","vi":"kính chắn gió ô tô"}],"examples":[{"en":"Heavy rain splashed against the windscreen throughout our journey.","vi":"Mưa lớn xối xả đập vào kính chắn gió suốt cả chuyến đi của chúng tôi.","audioKind":"ex"},{"en":"A damaged windscreen can reduce visibility, so regular vehicle inspections are essential for maintaining road safety.","vi":"Kính chắn gió bị hỏng có thể làm giảm tầm nhìn, vì vậy việc kiểm tra xe định kỳ là rất cần thiết để duy trì an toàn giao thông.","audioKind":"ex2"}],"collocations":[{"en":"windscreen wipers","vi":"cần gạt nước mưa"},{"en":"cracked windscreen","vi":"kính chắn gió bị nứt"},{"en":"heated windscreen","vi":"kính chắn gió sưởi ấm"}],"wordFamily":[],"synonyms":["windshield"],"antonyms":[],"tipVi":"Tiếng Anh - Anh dùng windscreen, trong khi tiếng Anh - Mỹ thường dùng windshield.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_explorer', 'en-b1-7', 'explorer', '/ɪkˈsplɔːrər/', 'B1', 'nhà thám hiểm; nhà khai phá', 'n.', 'explore (v.), exploration (n.), exploratory (adj.)', 'Đồng nghĩa: adventurer', 'Explorer chỉ người đi thám hiểm, còn exploration chỉ hoạt động thám hiểm.', 'The explorer carried a compass through the dense forest.', NULL, 'Nhà thám hiểm mang theo một chiếc la bàn băng qua khu rừng rậm.', '{"wordId":"explorer","ukIpa":"/ɪkˈsplɔːrə/","usIpa":"/ɪkˈsplɔːrər/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"someone who travels through unfamiliar places to discover more about them","vi":"nhà thám hiểm; nhà khai phá"}],"examples":[{"en":"The explorer carried a compass through the dense forest.","vi":"Nhà thám hiểm mang theo một chiếc la bàn băng qua khu rừng rậm.","audioKind":"ex"},{"en":"An explorer can contribute valuable observations, but expeditions should avoid disturbing local wildlife and communities.","vi":"Một nhà thám hiểm có thể đóng góp những quan sát có giá trị, nhưng các chuyến thám hiểm nên tránh làm xáo trộn động vật hoang dã và cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"polar explorer","vi":"nhà thám hiểm vùng cực"},{"en":"intrepid explorer","vi":"nhà thám hiểm gan dạ"},{"en":"early explorers","vi":"các nhà thám hiểm thời kỳ đầu"}],"wordFamily":["explore (v.)","exploration (n.)","exploratory (adj.)"],"synonyms":["adventurer"],"antonyms":[],"tipVi":"Explorer chỉ người đi thám hiểm, còn exploration chỉ hoạt động thám hiểm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lounge', 'en-b1-7', 'lounge', '/laʊndʒ/', 'B1', 'phòng chờ; sảnh đợi; phòng khách; ngồi (hoặc nằm) thõng thượt; nằm ườn', 'n.', NULL, NULL, 'Trong tiếng Anh-Anh (British English), từ này có thể chỉ phòng khách trong nhà; dạng động từ thường đi với giới từ around.', 'We waited in the lounge until our room was ready.', NULL, 'Chúng tôi đợi ở phòng chờ cho đến khi phòng của mình sẵn sàng.', '{"wordId":"lounge","ukIpa":"/laʊndʒ/","usIpa":"/laʊndʒ/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"a comfortable room for sitting, relaxing, or waiting","vi":"phòng chờ; sảnh đợi"},{"pos":"n.","en":"a room in a home for sitting and relaxing","vi":"phòng khách"},{"pos":"v.","en":"to sit or lie in a relaxed, lazy way","vi":"ngồi (hoặc nằm) thõng thượt; nằm ườn"}],"examples":[{"en":"We waited in the lounge until our room was ready.","vi":"Chúng tôi đợi ở phòng chờ cho đến khi phòng của mình sẵn sàng.","audioKind":"ex"},{"en":"Comfortable airport lounges can make long journeys less stressful for passengers travelling with young children.","vi":"Phòng chờ sân bay thoải mái có thể giúp hành khách đi cùng trẻ nhỏ giảm bớt căng thẳng trong những chuyến đi dài.","audioKind":"ex2"}],"collocations":[{"en":"departure lounge","vi":"phòng chờ khởi hành"},{"en":"hotel lounge","vi":"phòng chờ khách sạn"},{"en":"lounge around","vi":"ngồi ườn ra; nằm dài thảnh thơi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh (British English), từ này có thể chỉ phòng khách trong nhà; dạng động từ thường đi với giới từ around.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stewardess', 'en-b1-7', 'stewardess', '/ˌstuːərˈdes/', 'B1', 'nữ tiếp viên hàng không; nữ tiếp viên tàu thủy', 'n.', 'steward (n.)', 'Đồng nghĩa: flight attendant', 'Là từ cũ và chỉ giới hạn đối với nữ; hiện nay thường dùng flight attendant.', 'My grandmother worked as a stewardess before becoming a teacher.', NULL, 'Bà của tôi từng làm tiếp viên hàng không trước khi trở thành giáo viên.', '{"wordId":"stewardess","ukIpa":"/ˌstjuːəˈdes/","usIpa":"/ˌstuːərˈdes/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"an older term for a female aircraft or ship attendant","vi":"nữ tiếp viên hàng không; nữ tiếp viên tàu thủy"}],"examples":[{"en":"My grandmother worked as a stewardess before becoming a teacher.","vi":"Bà của tôi từng làm tiếp viên hàng không trước khi trở thành giáo viên.","audioKind":"ex"},{"en":"The replacement of stewardess with flight attendant reflects a broader shift towards gender-neutral language in professional settings.","vi":"Việc thay thế stewardess bằng flight attendant phản ánh xu hướng rộng lớn hơn trong việc chuyển sang sử dụng ngôn ngữ trung lập về giới tính trong môi trường chuyên nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"work as a stewardess","vi":"làm nghề tiếp viên hàng không"},{"en":"airline stewardess","vi":"nữ tiếp viên hàng không"}],"wordFamily":["steward (n.)"],"synonyms":["flight attendant"],"antonyms":[],"tipVi":"Là từ cũ và chỉ giới hạn đối với nữ; hiện nay thường dùng flight attendant.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_route', 'en-b1-7', 'route', '/ruːt/', 'B1', 'tuyến đường; lộ trình; điều phối đường đi; gửi theo một tuyến đường nhất định', 'n.', 'reroute (v.), routing (n.)', 'Đồng nghĩa: path, way', 'Từ route nhấn mạnh hành trình di chuyển từ điểm này đến điểm khác.', 'We took a different route home to avoid traffic.', NULL, 'Chúng tôi đi một tuyến đường khác để về nhà nhằm tránh kẹt xe.', '{"wordId":"route","ukIpa":"/ruːt/","usIpa":"/ruːt/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"a way taken to get from one place to another","vi":"tuyến đường; lộ trình"},{"pos":"v.","en":"to send someone or something along a particular path","vi":"điều phối đường đi; gửi theo một tuyến đường nhất định"}],"examples":[{"en":"We took a different route home to avoid traffic.","vi":"Chúng tôi đi một tuyến đường khác để về nhà nhằm tránh kẹt xe.","audioKind":"ex"},{"en":"Expanding bus routes to rural communities would improve access to employment and essential public services.","vi":"Việc mở rộng các tuyến xe buýt đến các cộng đồng nông thôn sẽ giúp người dân dễ dàng tiếp cận việc làm và các dịch vụ công cộng thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"bus route","vi":"tuyến xe buýt"},{"en":"alternative route","vi":"tuyến đường thay thế"},{"en":"trade route","vi":"tuyến đường thương mại"},{"en":"route calls","vi":"chuyển cuộc gọi"}],"wordFamily":["reroute (v.)","routing (n.)"],"synonyms":["path","way"],"antonyms":[],"tipVi":"Từ route nhấn mạnh hành trình di chuyển từ điểm này đến điểm khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_minivan', 'en-b1-7', 'minivan', '/ˈmɪnivæn/', 'B1', 'xe ô tô gia đình nhiều chỗ ngồi; xe tải nhỏ chở hàng', 'n.', 'van (n.)', NULL, 'Mỹ thường chỉ xe gia đình nhiều chỗ ngồi, không nên dịch cứng nhắc là xe tải nhỏ.', 'Our minivan has enough seats for the whole family.', NULL, 'Xe minivan của chúng tôi có đủ chỗ ngồi cho cả gia đình.', '{"wordId":"minivan","ukIpa":"/ˈmɪnivæn/","usIpa":"/ˈmɪnivæn/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"A vehicle with several passenger seats, often used by families.","vi":"xe ô tô gia đình nhiều chỗ ngồi"},{"pos":"n.","en":"A small van used for transporting goods.","vi":"xe tải nhỏ chở hàng"}],"examples":[{"en":"Our minivan has enough seats for the whole family.","vi":"Xe minivan của chúng tôi có đủ chỗ ngồi cho cả gia đình.","audioKind":"ex"},{"en":"Shared minivan services can improve access to healthcare for rural residents who lack reliable public transport.","vi":"Dịch vụ xe minivan chung có thể cải thiện khả năng tiếp cận dịch vụ chăm sóc sức khỏe cho cư dân nông thôn thiếu giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"family minivan","vi":"xe minivan gia đình"},{"en":"rent a minivan","vi":"thuê xe minivan"},{"en":"seven-seater minivan","vi":"xe minivan bảy chỗ"}],"wordFamily":["van (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Mỹ thường chỉ xe gia đình nhiều chỗ ngồi, không nên dịch cứng nhắc là xe tải nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aircraft', 'en-b1-7', 'aircraft', '/ˈerkræft/', 'B1', 'máy bay; tàu bay; hàng không mẫu', 'n.', NULL, NULL, 'aircraft có dạng số ít và số nhiều như nhau, không thêm -s.', 'A small aircraft flew low over the fields.', NULL, 'Một chiếc máy bay nhỏ bay là đà thấp qua các cánh đồng.', '{"wordId":"aircraft","ukIpa":"/ˈeəkrɑːft/","usIpa":"/ˈerkræft/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"a vehicle that flies, such as a plane or helicopter","vi":"máy bay; tàu bay; hàng không mẫu"}],"examples":[{"en":"A small aircraft flew low over the fields.","vi":"Một chiếc máy bay nhỏ bay là đà thấp qua các cánh đồng.","audioKind":"ex"},{"en":"Developing more efficient aircraft could reduce fuel consumption, although growing passenger demand may limit the environmental benefits.","vi":"Việc phát triển các loại máy bay hiệu quả hơn có thể làm giảm tiêu thụ nhiên liệu, mặc dù nhu cầu hành khách gia tăng có thể hạn chế lợi ích môi trường.","audioKind":"ex2"}],"collocations":[{"en":"commercial aircraft","vi":"máy bay thương mại"},{"en":"passenger aircraft","vi":"máy bay chở khách"},{"en":"light aircraft","vi":"máy bay hạng nhẹ"},{"en":"aircraft maintenance","vi":"bảo dưỡng tàu bay"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"aircraft có dạng số ít và số nhiều như nhau, không thêm -s.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_baggage', 'en-b1-7', 'baggage', '/ˈbæɡɪdʒ/', 'B1', 'hành lý; gánh nặng tâm lý; hành trang tinh thần', 'n.', NULL, 'Đồng nghĩa: luggage', 'Đây là danh từ không đếm được; một kiện hành lý nói là a piece of baggage.', 'Our baggage arrived on the next flight this afternoon.', NULL, 'Hành lý của chúng tôi đã đến trên chuyến bay tiếp theo vào chiều nay.', '{"wordId":"baggage","ukIpa":"/ˈbæɡɪdʒ/","usIpa":"/ˈbæɡɪdʒ/","cefr":"B1","topic":"travel","senses":[{"pos":"n.","en":"the bags and suitcases you take when travelling","vi":"hành lý"},{"pos":"n.","en":"past experiences or feelings that continue to cause difficulties","vi":"gánh nặng tâm lý; hành trang tinh thần"}],"examples":[{"en":"Our baggage arrived on the next flight this afternoon.","vi":"Hành lý của chúng tôi đã đến trên chuyến bay tiếp theo vào chiều nay.","audioKind":"ex"},{"en":"Airlines often charge additional fees for checked baggage, increasing the overall cost of travel.","vi":"Các hãng hàng không thường thu phí bổ sung đối với hành lý ký gửi, làm tăng tổng chi phí chuyến đi.","audioKind":"ex2"}],"collocations":[{"en":"checked baggage","vi":"hành lý ký gửi"},{"en":"baggage allowance","vi":"hạn mức hành lý"},{"en":"baggage claim","vi":"khu vực nhận hành lý"},{"en":"emotional baggage","vi":"gánh nặng tình cảm"}],"wordFamily":[],"synonyms":["luggage"],"antonyms":[],"tipVi":"Đây là danh từ không đếm được; một kiện hành lý nói là a piece of baggage.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_7_1', 'en-b1-7', 'Cách dùng “lounge” (n.) — phòng chờ; sảnh đợi', 'departure lounge  ·  hotel lounge  ·  lounge around', 'Trong tiếng Anh-Anh (British English), từ này có thể chỉ phòng khách trong nhà; dạng động từ thường đi với giới từ around.', NULL, '[{"hanzi":"We waited in the lounge until our room was ready.","pinyin":"","meaning":"Chúng tôi đợi ở phòng chờ cho đến khi phòng của mình sẵn sàng."},{"hanzi":"Comfortable airport lounges can make long journeys less stressful for passengers travelling with young children.","pinyin":"","meaning":"Phòng chờ sân bay thoải mái có thể giúp hành khách đi cùng trẻ nhỏ giảm bớt căng thẳng trong những chuyến đi dài."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_7_2', 'en-b1-7', 'Cách dùng “farther” (adv.) — xa hơn (về khoảng cách)', 'farther away  ·  farther north  ·  farther from home', 'farther thường chỉ khoảng cách vật lý thực tế; further dùng cho sự tiến triển hoặc trừu tượng hơn.', 'Họ từ (Word Family): far (adv), farthest (adv) | Đồng nghĩa: further · Trái nghĩa: nearer', '[{"hanzi":"We walked farther along the beach before stopping for lunch.","pinyin":"","meaning":"Chúng tôi đi bộ xa hơn dọc theo bãi biển trước khi dừng lại ăn trưa."},{"hanzi":"As housing costs rise, many workers move farther from city centres and face longer daily commutes.","pinyin":"","meaning":"Khi chi phí nhà ở tăng lên, nhiều người lao động chuyển đến sống ở những nơi xa trung tâm thành phố hơn và phải đối mặt với thời gian di chuyển đi làm hằng ngày lâu hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_7_3', 'en-b1-7', 'Cách dùng “porter” (n.) — nhân viên khuân vác hành lý (ở khách sạn, nhà ga)', 'hotel porter  ·  luggage porter  ·  night porter', 'không dùng chung chung cho nhân viên phục vụ, thường chỉ người vác hành lý hoặc người gác cổng.', NULL, '[{"hanzi":"The porter carried our heavy suitcases to the lift.","pinyin":"","meaning":"Nhân viên khuân vác đã mang những chiếc vali nặng của chúng tôi ra thang máy."},{"hanzi":"Hotels can improve accessibility by training each porter to assist guests with limited mobility.","pinyin":"","meaning":"Các khách sạn có thể cải thiện khả năng tiếp cận bằng cách đào tạo mỗi nhân viên khuân vác hỗ trợ khách hàng có khả năng vận động hạn chế."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_7_4', 'en-b1-7', 'Cách dùng “sail” (v.) — chèo thuyền; lướt thuyền trên mặt nước', 'set sail  ·  sail across the ocean  ·  raise the sails', 'Khi là động từ, từ này không chỉ giới hạn ở thuyền buồm mà còn có thể chỉ tàu thuyền nói chung.', 'Họ từ (Word Family): sailing (n.), sailor (n.)', '[{"hanzi":"We sailed across the lake on a sunny afternoon.","pinyin":"","meaning":"Chúng tôi đã chèo thuyền vượt qua hồ vào một buổi chiều đầy nắng."},{"hanzi":"Ships that sail through sensitive marine habitats should follow strict rules to protect wildlife.","pinyin":"","meaning":"Các tàu thuyền đi qua các khu vực sinh thái biển nhạy cảm phải tuân thủ các quy định nghiêm ngặt để bảo vệ động thực vật hoang dã."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_7_1', 'en-b1-7', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_1_1', 'ten_b1_7_1', 'customs', 'We opened our suitcases for inspection at customs.', 'We opened our suitcases for inspection at customs.', '/ˈkʌstəmz/', 'Chúng tôi đã mở vali để kiểm tra tại khu vực hải quan.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_1_2', 'ten_b1_7_1', 'farther', 'We walked farther along the beach before stopping for lunch.', 'We walked farther along the beach before stopping for lunch.', '/ˈfɑːrðər/', 'Chúng tôi đi bộ xa hơn dọc theo bãi biển trước khi dừng lại ăn trưa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_1_3', 'ten_b1_7_1', 'western', 'Our cabin faces the lake on its western shore.', 'Our cabin faces the lake on its western shore.', '/ˈwestərn/', 'Nhà gỗ của chúng tôi nằm ở bờ phía tây của hồ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_1_4', 'ten_b1_7_1', 'landing', 'The plane made a smooth landing despite the wind.', 'The plane made a smooth landing despite the wind.', '/ˈlændɪŋ/', 'Máy bay hạ cánh êm ái bất chấp gió lớn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_1_5', 'ten_b1_7_1', 'reservation', 'I made a reservation for dinner by the window.', 'I made a reservation for dinner by the window.', '/ˌrezɚˈveɪʃən/', 'Tôi đã đặt một bàn cạnh cửa sổ cho bữa tối.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_1_6', 'ten_b1_7_1', 'canal', 'We watched a narrow boat glide along the canal.', 'We watched a narrow boat glide along the canal.', '/kəˈnæl/', 'Chúng tôi ngắm nhìn một chiếc thuyền hẹp lướt êm đềm dọc theo con kênh đào.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_1_7', 'ten_b1_7_1', 'cottage', 'Their cottage has a tiny garden full of roses.', 'Their cottage has a tiny garden full of roses.', '/ˈkɑːtɪdʒ/', 'Ngôi nhà tranh của họ có một khu vườn nhỏ xinh ngập tràn hoa hồng.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_1_8', 'ten_b1_7_1', 'duty-free', 'She bought some duty-free perfume before boarding her flight.', 'She bought some duty-free perfume before boarding her flight.', '/ˌduːti ˈfriː/', 'Cô ấy mua một ít nước hoa miễn thuế trước khi lên máyบิน.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_7_1_1', 'en-b1-7', 'ten_b1_7_1', 'listening', 'listening', 'We opened our suitcases for inspection at customs.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy mua một ít nước hoa miễn thuế trước khi lên máyบิน.","Chúng tôi đã mở vali để kiểm tra tại khu vực hải quan.","Chuyến đi bộ đường dài cuối tuần của chúng tôi kết thúc bên cạnh một hồ nước trong veo trên núi.","Nhà gỗ của chúng tôi nằm ở bờ phía tây của hồ."]'::jsonb, 1, 'We opened our suitcases for inspection at customs. → Chúng tôi đã mở vali để kiểm tra tại khu vực hải quan.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_7_1_2', 'en-b1-7', 'ten_b1_7_1', 'listening', 'listening', 'We walked farther along the beach before stopping for lunch.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ngôi nhà tranh của họ có một khu vườn nhỏ xinh ngập tràn hoa hồng.","Chúng tôi đã tận hưởng đời sống về đêm của thành phố sau bữa tối bên dòng sông.","Chúng tôi đi bộ xa hơn dọc theo bãi biển trước khi dừng lại ăn trưa.","Xe minivan của chúng tôi có đủ chỗ ngồi cho cả gia đình."]'::jsonb, 2, 'We walked farther along the beach before stopping for lunch. → Chúng tôi đi bộ xa hơn dọc theo bãi biển trước khi dừng lại ăn trưa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_7_1_3', 'en-b1-7', 'ten_b1_7_1', 'listening', 'listening', 'Our cabin faces the lake on its western shore.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhà gỗ của chúng tôi nằm ở bờ phía tây của hồ.","Cô ấy mua một ít nước hoa miễn thuế trước khi lên máyบิน.","Máy bay hạ cánh êm ái bất chấp gió lớn.","Mưa lớn xối xả đập vào kính chắn gió suốt cả chuyến đi của chúng tôi."]'::jsonb, 0, 'Our cabin faces the lake on its western shore. → Nhà gỗ của chúng tôi nằm ở bờ phía tây của hồ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_7_2', 'en-b1-7', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_2_1', 'ten_b1_7_2', 'customs', 'More efficient customs procedures can reduce delays at borders and support international trade without weakening security.', 'More efficient customs procedures can reduce delays at borders and support international trade without weakening security.', '/ˈkʌstəmz/', 'Quy trình hải quan hiệu quả hơn có thể làm giảm tình trạng chậm trễ ở biên giới và hỗ trợ thương mại quốc tế mà không làm suy giảm an ninh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_2_2', 'ten_b1_7_2', 'farther', 'As housing costs rise, many workers move farther from city centres and face longer daily commutes.', 'As housing costs rise, many workers move farther from city centres and face longer daily commutes.', '/ˈfɑːrðər/', 'Khi chi phí nhà ở tăng lên, nhiều người lao động chuyển đến sống ở những nơi xa trung tâm thành phố hơn và phải đối mặt với thời gian di chuyển đi làm hằng ngày lâu hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_2_3', 'ten_b1_7_2', 'western', 'Investment in western regions could improve transport links and reduce economic inequalities within the country.', 'Investment in western regions could improve transport links and reduce economic inequalities within the country.', '/ˈwestərn/', 'Đầu tư vào các khu vực miền tây có thể cải thiện kết nối giao thông và giảm bất bình đẳng kinh tế trong nước.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_2_4', 'ten_b1_7_2', 'landing', 'Improved weather forecasting can help pilots prepare for a safe landing during rapidly changing conditions.', 'Improved weather forecasting can help pilots prepare for a safe landing during rapidly changing conditions.', '/ˈlændɪŋ/', 'Công tác dự báo thời tiết được cải thiện có thể giúp phi công chuẩn bị cho một cuộc hạ cánh an toàn trong điều kiện thời tiết thay đổi nhanh chóng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_2_5', 'ten_b1_7_2', 'reservation', 'Some residents expressed reservations about the proposed airport expansion because of increased noise pollution.', 'Some residents expressed reservations about the proposed airport expansion because of increased noise pollution.', '/ˌrezɚˈveɪʃən/', 'Một số cư dân bày tỏ sự e dè về dự án mở rộng sân bay được đề xuất do ô nhiễm tiếng ồn gia tăng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_7_2_6', 'ten_b1_7_2', 'canal', 'Restoring historic canals can attract tourists while providing valuable habitats for wildlife in densely populated urban areas.', 'Restoring historic canals can attract tourists while providing valuable habitats for wildlife in densely populated urban areas.', '/kəˈnæl/', 'Việc phục hồi các con kênh lịch sử có thể thu hút khách du lịch đồng thời cung cấp môi trường sống quý giá cho động vật hoang dã ở các khu đô thị đông dân cư.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_7_2_1', 'en-b1-7', 'ten_b1_7_2', 'listening', 'listening', 'More efficient customs procedures can reduce delays at borders and support international trade without weakening security.', NULL, 'Trong câu vừa nghe, từ “customs” mang nghĩa nào sau đây?', '["giới từ","trốn thoát; thoát khỏi","khoảng chừng; đại khái","hải quan"]'::jsonb, 3, '“customs” (/ˈkʌstəmz/): hải quan. Câu đầy đủ: More efficient customs procedures can reduce delays at borders and support international trade without weakening security.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_7_2_2', 'en-b1-7', 'ten_b1_7_2', 'listening', 'listening', 'As housing costs rise, many workers move farther from city centres and face longer daily commutes.', NULL, 'Trong câu vừa nghe, từ “farther” mang nghĩa nào sau đây?', '["xa hơn (về khoảng cách)","hội đồng; ủy ban","nộp đơn chính thức xin việc, vị trí hoặc xin phép","khung; khung sườn"]'::jsonb, 0, '“farther” (/ˈfɑːrðər/): xa hơn (về khoảng cách). Câu đầy đủ: As housing costs rise, many workers move farther from city centres and face longer daily commutes.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
