INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_1', 'en-b1-7', NULL, 'comprehensive_test', 'listening', 'customs', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lông thú; bộ lông","móc treo quần áo","hải quan","địa điểm thu hút; danh lam thắng cảnh"]'::jsonb, 2, 'customs (/ˈkʌstəmz/) → hải quan; thuế quan; thuế hải quan; thói quen; phong tục tập quán', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_2', 'en-b1-7', NULL, 'comprehensive_test', 'listening', 'We walked farther along the beach before stopping for lunch.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhà gỗ của chúng tôi nằm ở bờ phía tây của hồ.","Nhà thám hiểm mang theo một chiếc la bàn băng qua khu rừng rậm.","Chúng tôi đi bộ xa hơn dọc theo bãi biển trước khi dừng lại ăn trưa.","Chúng tôi đã tận hưởng đời sống về đêm của thành phố sau bữa tối bên dòng sông."]'::jsonb, 2, 'We walked farther along the beach before stopping for lunch. → Chúng tôi đi bộ xa hơn dọc theo bãi biển trước khi dừng lại ăn trưa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_3', 'en-b1-7', NULL, 'comprehensive_test', 'listening', 'western', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc về phía tây; phía tây","con dơi (thú bay hoạt động chủ yếu về đêm)","gật đầu","nướng bằng vỉ"]'::jsonb, 0, 'western (/ˈwestərn/) → thuộc về phía tây; phía tây; thuộc phương Tây; phương Tây; phim cao bồi miền Tây', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_4', 'en-b1-7', NULL, 'comprehensive_test', 'listening', 'The plane made a smooth landing despite the wind.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đi một tuyến đường khác để về nhà nhằm tránh kẹt xe.","Máy bay hạ cánh êm ái bất chấp gió lớn.","Hành lý của chúng tôi đã đến trên chuyến bay tiếp theo vào chiều nay.","Phòng vệ sinh nằm ngay phía sau phòng đợi."]'::jsonb, 1, 'The plane made a smooth landing despite the wind. → Máy bay hạ cánh êm ái bất chấp gió lớn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_5', 'en-b1-7', NULL, 'comprehensive_test', 'listening', 'reservation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chức năng; trách nhiệm","sự đặt chỗ; sự đặt trước","dần dần; từ từ","địa điểm; công trường; khu di tích"]'::jsonb, 1, 'reservation (/ˌrezɚˈveɪʃən/) → sự đặt chỗ; sự đặt trước; sự nghi ngờ; sự e dè', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_6', 'en-b1-7', NULL, 'comprehensive_test', 'listening', 'We watched a narrow boat glide along the canal.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi ngắm nhìn một chiếc thuyền hẹp lướt êm đềm dọc theo con kênh đào.","Chúng tôi đã mở vali để kiểm tra tại khu vực hải quan.","Ngôi nhà tranh của họ có một khu vườn nhỏ xinh ngập tràn hoa hồng.","Máy bay hạ cánh êm ái bất chấp gió lớn."]'::jsonb, 0, 'We watched a narrow boat glide along the canal. → Chúng tôi ngắm nhìn một chiếc thuyền hẹp lướt êm đềm dọc theo con kênh đào.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_7', 'en-b1-7', NULL, 'comprehensive_test', 'listening', 'cottage', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà tranh; nhà nghỉ nông thôn; nhà nhỏ ở vùng quê","đáng sợ; khiếp đảm","sự so sánh; sự đối chiếu","làm mệt mỏi; mệt mỏi"]'::jsonb, 0, 'cottage (/ˈkɑːtɪdʒ/) → nhà tranh; nhà nghỉ nông thôn; nhà nhỏ ở vùng quê', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_8', 'en-b1-7', NULL, 'comprehensive_test', 'listening', 'She bought some duty-free perfume before boarding her flight.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy mua một ít nước hoa miễn thuế trước khi lên máyบิน.","Chúng tôi đã chèo thuyền vượt qua hồ vào một buổi chiều đầy nắng.","Phòng vệ sinh nằm ngay phía sau phòng đợi.","Chúng tôi đợi ở phòng chờ cho đến khi phòng của mình sẵn sàng."]'::jsonb, 0, 'She bought some duty-free perfume before boarding her flight. → Cô ấy mua một ít nước hoa miễn thuế trước khi lên máyบิน.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
