INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_18', 'en-b1-7', NULL, 'comprehensive_test', 'reading', NULL, 'More efficient customs procedures can reduce delays at borders and support international trade without weakening security.', 'Dựa vào câu trên, từ “customs” có nghĩa phù hợp nhất là gì?', '["hải quan","tòa nhà chọc trời","bài tập giữ gìn vóc dáng; thể dục giữ vóc dáng","sự tiến bộ; sự phát triển"]'::jsonb, 0, 'customs: hải quan; thuế quan; thuế hải quan; thói quen; phong tục tập quán. Dịch cả câu: Quy trình hải quan hiệu quả hơn có thể làm giảm tình trạng chậm trễ ở biên giới và hỗ trợ thương mại quốc tế mà không làm suy giảm an ninh.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_19', 'en-b1-7', NULL, 'comprehensive_test', 'reading', NULL, 'As housing costs rise, many workers move farther from city centres and face longer daily commutes.', 'Dựa vào câu trên, từ “farther” có nghĩa phù hợp nhất là gì?', '["xa hơn (về khoảng cách)","tương tự; giống như vậy","trông trẻ hộ; giữ em bé","nhiều cát; có nhiều cát"]'::jsonb, 0, 'farther: xa hơn (về khoảng cách); ở xa hơn về phía trước hoặc khoảng cách lớn hơn. Dịch cả câu: Khi chi phí nhà ở tăng lên, nhiều người lao động chuyển đến sống ở những nơi xa trung tâm thành phố hơn và phải đối mặt với thời gian di chuyển đi làm hằng ngày lâu hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_20', 'en-b1-7', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in western regions could improve transport links and reduce economic inequalities within the country.', 'Dựa vào câu trên, từ “western” có nghĩa phù hợp nhất là gì?', '["sự so sánh; sự đối chiếu","thuộc về phía tây; phía tây","nhãn; mác","thủ thư; nhân viên thư viện"]'::jsonb, 1, 'western: thuộc về phía tây; phía tây; thuộc phương Tây; phương Tây; phim cao bồi miền Tây. Dịch cả câu: Đầu tư vào các khu vực miền tây có thể cải thiện kết nối giao thông và giảm bất bình đẳng kinh tế trong nước.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_21', 'en-b1-7', NULL, 'comprehensive_test', 'reading', NULL, 'Improved weather forecasting can help pilots prepare for a safe landing during rapidly changing conditions.', 'Dựa vào câu trên, từ “landing” có nghĩa phù hợp nhất là gì?', '["sự hạ cánh; sự cập bến","sự đặt chỗ; việc đặt trước","nhận ra; hiểu rõ","sự thèm ăn; cảm giác thèm ăn"]'::jsonb, 0, 'landing: sự hạ cánh; sự cập bến; chiếu nghỉ (khu vực phẳng ở đầu hoặc giữa các bậc cầu thang). Dịch cả câu: Công tác dự báo thời tiết được cải thiện có thể giúp phi công chuẩn bị cho một cuộc hạ cánh an toàn trong điều kiện thời tiết thay đổi nhanh chóng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_22', 'en-b1-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “xe ô tô gia đình nhiều chỗ ngồi”', '["corridor","eyebrow","minivan","crash"]'::jsonb, 2, 'xe ô tô gia đình nhiều chỗ ngồi → minivan (/ˈmɪnivæn/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_23', 'en-b1-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “máy bay; tàu bay; hàng không mẫu”', '["ache","research","gain","aircraft"]'::jsonb, 3, 'máy bay; tàu bay; hàng không mẫu → aircraft (/ˈerkræft/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_7_24', 'en-b1-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hành lý”', '["rainbow","annual","shot","baggage"]'::jsonb, 3, 'hành lý → baggage (/ˈbæɡɪdʒ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-8', 'en', 'Bài 8: Xã hội & Cộng đồng (1) - CEFR B1', 'CEFR B1', 'B1 · Xã hội', '26 từ vựng Tiếng Anh CEFR B1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3008, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_issue', 'en-b1-8', 'issue', '/ˈɪʃuː/', 'B1', 'vấn đề, đề tài (vấn đề quan trọng cần được thảo luận); phát hành, cấp phát (công bố chính thức hoặc cung cấp cái gì cho mọi người); số báo, ấn bản (một số của báo hoặc tạp chí được phát hành định kỳ)', 'n.', 'issuance (n.), issuer (n.), reissue (v.)', NULL, 'Từ issue khi chỉ vấn đề thường mang nghĩa là một đề tài cần được thảo luận, không nhất thiết phải là một rắc rối khó khăn.', 'We discussed the parking issue at our neighbourhood meeting.', NULL, 'Chúng tôi đã thảo luận về vấn đề đậu xe tại cuộc họp khu1 phố của mình.', '{"wordId":"issue","ukIpa":"/ˈɪʃuː/","usIpa":"/ˈɪʃuː/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"An important subject or problem that needs discussion.","vi":"vấn đề, đề tài (vấn đề quan trọng cần được thảo luận)"},{"pos":"v.","en":"To officially announce or give something to people.","vi":"phát hành, cấp phát (công bố chính thức hoặc cung cấp cái gì cho mọi người)"},{"pos":"n.","en":"One edition of a regularly published newspaper or magazine.","vi":"số báo, ấn bản (một số của báo hoặc tạp chí được phát hành định kỳ)"}],"examples":[{"en":"We discussed the parking issue at our neighbourhood meeting.","vi":"Chúng tôi đã thảo luận về vấn đề đậu xe tại cuộc họp khu1 phố của mình.","audioKind":"ex"},{"en":"Governments must address the issue of housing affordability to ensure that young adults can live independently.","vi":"Chính phủ phải giải quyết vấn đề khả năng chi trả nhà ở để đảm bảo rằng người trẻ tuổi có thể sống tự lập.","audioKind":"ex2"}],"collocations":[{"en":"address an issue","vi":"giải quyết vấn đề"},{"en":"a controversial issue","vi":"một vấn đề gây tranh cãi"},{"en":"issue a warning","vi":"phát lệnh cảnh cáo"},{"en":"the latest issue","vi":"số báo mới nhất"}],"wordFamily":["issuance (n.)","issuer (n.)","reissue (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ issue khi chỉ vấn đề thường mang nghĩa là một đề tài cần được thảo luận, không nhất thiết phải là một rắc rối khó khăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_volunteer', 'en-b1-8', 'volunteer', '/ˌvɑːlənˈtɪr/', 'B1', 'tình nguyện viên; người làm công tác thiện nguyện; tình nguyện; xung phong', 'n.', 'voluntary (adj.), voluntarily (adv.)', NULL, 'Dùng volunteer to do để diễn tả hành động tự nguyện làm việc gì; voluntary là tính từ thông dụng liên quan.', 'A volunteer helped us carry the boxes upstairs.', NULL, 'Một tình nguyện viên đã giúp chúng tôi khuân các thùng hàng lên lầu.', '{"wordId":"volunteer","ukIpa":"/ˌvɒlənˈtɪə/","usIpa":"/ˌvɑːlənˈtɪr/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"someone who freely offers to help, usually without payment","vi":"tình nguyện viên; người làm công tác thiện nguyện"},{"pos":"v.","en":"to freely offer to do something or give information","vi":"tình nguyện; xung phong"}],"examples":[{"en":"A volunteer helped us carry the boxes upstairs.","vi":"Một tình nguyện viên đã giúp chúng tôi khuân các thùng hàng lên lầu.","audioKind":"ex"},{"en":"Universities can encourage students to volunteer in their communities by offering flexible schedules and practical support.","vi":"Các trường đại học có thể khuyến khích sinh viên tham gia công tác tình nguyện tại cộng đồng bằng cách cung cấp lịch trình linh hoạt và hỗ trợ thiết thực.","audioKind":"ex2"}],"collocations":[{"en":"volunteer work","vi":"công việc tình nguyện"},{"en":"volunteer to help","vi":"tình nguyện giúp đỡ"},{"en":"volunteer for a charity","vi":"làm tình nguyện cho một tổ chức từ thiện"},{"en":"recruit volunteers","vi":"tuyển mộ tình nguyện viên"}],"wordFamily":["voluntary (adj.)","voluntarily (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng volunteer to do để diễn tả hành động tự nguyện làm việc gì; voluntary là tính từ thông dụng liên quan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sister-in-law', 'en-b1-8', 'sister-in-law', '/ˈsɪstər ɪn lɔː/', 'B1', 'chị dâu; em dâu; chị chồng; em chồng; chị vợ; em vợ', 'n.', NULL, NULL, 'Chỉ chị em họ hàng qua đường hôn nhân, không phải chị em kế; dạng số nhiều là sisters-in-law.', 'My sister-in-law brought homemade soup when I was ill.', NULL, 'Chị dâu tôi đã mang canh nhà nấu sang khi tôi ốm.', '{"wordId":"sister-in-law","ukIpa":"/ˈsɪstər ɪn lɔː/","usIpa":"/ˈsɪstər ɪn lɔː/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"your spouse''s sister, or your sibling''s or spouse''s sibling''s wife","vi":"chị dâu; em dâu; chị chồng; em chồng; chị vợ; em vợ"}],"examples":[{"en":"My sister-in-law brought homemade soup when I was ill.","vi":"Chị dâu tôi đã mang canh nhà nấu sang khi tôi ốm.","audioKind":"ex"},{"en":"Sharing childcare with a sister-in-law can help working parents balance professional responsibilities and family life.","vi":"Việc cùng chia sẻ việc chăm sóc con cái với chị dâu có thể giúp các bậc phụ huynh đi làm cân bằng tốt hơn giữa trách nhiệm nghề nghiệp và đời sống gia đình.","audioKind":"ex2"}],"collocations":[{"en":"future sister-in-law","vi":"em dâu tương lai"},{"en":"my sister-in-law''s family","vi":"gia đình bên nhà chồng/vợ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ chị em họ hàng qua đường hôn nhân, không phải chị em kế; dạng số nhiều là sisters-in-law.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disabled', 'en-b1-8', 'disabled', '/dɪsˈeɪbəld/', 'B1', 'khuyết tật; tàn tật', 'adj.', 'disability (n.), disable (v.)', NULL, 'Có thể dùng disabled people hoặc people with disabilities, tùy theo sự tôn trọng sở thích cá nhân.', 'The pool has a lift for disabled swimmers.', NULL, 'Hồ bơi có lắp đặt thang máy dành cho người bơi khuyết tật.', '{"wordId":"disabled","ukIpa":"/dɪsˈeɪbəld/","usIpa":"/dɪsˈeɪbəld/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"Having a condition that limits activities or participation in society.","vi":"khuyết tật; tàn tật"}],"examples":[{"en":"The pool has a lift for disabled swimmers.","vi":"Hồ bơi có lắp đặt thang máy dành cho người bơi khuyết tật.","audioKind":"ex"},{"en":"Universities should provide accessible facilities and appropriate support to ensure that disabled students can participate fully in campus life.","vi":"Các trường đại học nên cung cấp các cơ sở vật chất dễ tiếp cận và sự hỗ trợ phù hợp để đảm bảo sinh viên khuyết tật có thể tham gia đầy đủ vào đời sống học đường.","audioKind":"ex2"}],"collocations":[{"en":"disabled people","vi":"người khuyết tật"},{"en":"disabled access","vi":"lối đi cho người khuyết tật"},{"en":"disabled parking space","vi":"chỗ đậu xe dành cho người khuyết tật"}],"wordFamily":["disability (n.)","disable (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể dùng disabled people hoặc people with disabilities, tùy theo sự tôn trọng sở thích cá nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hero', 'en-b1-8', 'hero', '/ˈhɪroʊ/', 'B1', 'anh hùng (người được ngưỡng mộ vì lòng dũng cảm, thành tựu hoặc hành động cao đẹp); nhân vật nam chính (trong một câu chuyện)', 'n.', 'heroic (adj.), heroism (n.), heroine (n.)', NULL, 'Số nhiều là heroes; nhân vật hero trong câu chuyện không nhất thiết phải có phẩm chất đạo đức cao thượng.', 'The firefighter became a local hero after the rescue.', NULL, 'Người lính cứu hỏa đã trở thành người hùng địa phương sau vụ giải cứu.', '{"wordId":"hero","ukIpa":"/ˈhɪərəʊ/","usIpa":"/ˈhɪroʊ/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"someone admired for courage, achievements, or good actions","vi":"anh hùng (người được ngưỡng mộ vì lòng dũng cảm, thành tựu hoặc hành động cao đẹp)"},{"pos":"n.","en":"the main male character in a story","vi":"nhân vật nam chính (trong một câu chuyện)"}],"examples":[{"en":"The firefighter became a local hero after the rescue.","vi":"Người lính cứu hỏa đã trở thành người hùng địa phương sau vụ giải cứu.","audioKind":"ex"},{"en":"Films often portray the hero as an exceptional individual, although real social progress usually requires collective effort.","vi":"Phim ảnh thường khắc họa nhân vật chính là một cá nhân xuất chúng, mặc dù tiến bộ xã hội thực sự thường đòi hỏi nỗ lực tập thể.","audioKind":"ex2"}],"collocations":[{"en":"national hero","vi":"anh hùng dân tộc"},{"en":"local hero","vi":"người hùng địa phương"},{"en":"unsung hero","vi":"anh hùng thầm lặng"},{"en":"action hero","vi":"nam chính phim hành động"}],"wordFamily":["heroic (adj.)","heroism (n.)","heroine (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Số nhiều là heroes; nhân vật hero trong câu chuyện không nhất thiết phải có phẩm chất đạo đức cao thượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_responsibility', 'en-b1-8', 'responsibility', '/rɪˌspɑːnsəˈbɪləti/', 'B1', 'trách nhiệm; sự chịu trách nhiệm; nhiệm vụ; bổn phận', 'n.', 'responsible (adj.), responsibly (adv.), irresponsible (adj.), irresponsibility (n.)', 'Đồng nghĩa: duty, obligation', 'Khi chỉ trách nhiệm chung chung thường không đếm được; khi chỉ nhiệm vụ cụ thể thì đếm được; phía sau thường đi với giới từ for.', 'Feeding the dog is your responsibility this weekend.', NULL, 'Cho chó ăn là trách nhiệm của bạn vào cuối tuần này.', '{"wordId":"responsibility","ukIpa":"/rɪˌspɒnsəˈbɪləti/","usIpa":"/rɪˌspɑːnsəˈbɪləti/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"The duty to manage something or answer for its results.","vi":"trách nhiệm; sự chịu trách nhiệm"},{"pos":"n.","en":"A task or duty that you are expected to handle.","vi":"nhiệm vụ; bổn phận"}],"examples":[{"en":"Feeding the dog is your responsibility this weekend.","vi":"Cho chó ăn là trách nhiệm của bạn vào cuối tuần này.","audioKind":"ex"},{"en":"Governments and businesses share responsibility for reducing waste, but individuals also have an important role to play.","vi":"Chính phủ và các doanh nghiệp cùng chia sẻ trách nhiệm giảm thiểu rác thải, nhưng các cá nhân cũng đóng một vai trò quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"take responsibility for","vi":"chịu trách nhiệm cho..."},{"en":"a sense of responsibility","vi":"ý thức trách nhiệm"},{"en":"accept responsibility","vi":"nhận trách nhiệm"},{"en":"share responsibility","vi":"chia sẻ trách nhiệm"}],"wordFamily":["responsible (adj.)","responsibly (adv.)","irresponsible (adj.)","irresponsibility (n.)"],"synonyms":["duty","obligation"],"antonyms":[],"tipVi":"Khi chỉ trách nhiệm chung chung thường không đếm được; khi chỉ nhiệm vụ cụ thể thì đếm được; phía sau thường đi với giới từ for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_powerful', 'en-b1-8', 'powerful', '/ˈpaʊərfəl/', 'B1', 'mạnh mẽ; có lực lớn; có quyền lực; có sức ảnh hưởng lớn', 'adj.', 'power (n.), powerfully (adv.), powerless (adj.)', 'Đồng nghĩa: strong, influential · Trái nghĩa: weak, powerless', 'Thường đóng vai trò tính từ; trạng từ tương ứng là powerfully, không dùng powerful.', 'The powerful wind blew our garden chairs onto the grass.', NULL, 'Cơn gió mạnh đã thổi những chiếc ghế trong vườn của chúng tôi bay xuống bãi cỏ.', '{"wordId":"powerful","ukIpa":"/ˈpaʊəfəl/","usIpa":"/ˈpaʊərfəl/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"Having great physical strength or producing a strong effect.","vi":"mạnh mẽ; có lực lớn"},{"pos":"adj.","en":"Able to control people or strongly influence events.","vi":"có quyền lực; có sức ảnh hưởng lớn"}],"examples":[{"en":"The powerful wind blew our garden chairs onto the grass.","vi":"Cơn gió mạnh đã thổi những chiếc ghế trong vườn của chúng tôi bay xuống bãi cỏ.","audioKind":"ex"},{"en":"Powerful companies should take greater responsibility for reducing the environmental damage caused by their operations.","vi":"Các doanh nghiệp có tầm ảnh hưởng lớn nên gánh vác trách nhiệm lớn hơn trong việc giảm thiểu tổn hại môi trường do hoạt động của họ gây ra.","audioKind":"ex2"}],"collocations":[{"en":"powerful engine","vi":"động cơ mạnh mẽ"},{"en":"powerful influence","vi":"sức ảnh hưởng mạnh mẽ"},{"en":"powerful argument","vi":"lập luận đanh thép"}],"wordFamily":["power (n.)","powerfully (adv.)","powerless (adj.)"],"synonyms":["strong","influential"],"antonyms":["weak","powerless"],"tipVi":"Thường đóng vai trò tính từ; trạng từ tương ứng là powerfully, không dùng powerful.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_follower', 'en-b1-8', 'follower', '/ˈfɑːloʊɚ/', 'B1', 'người ủng hộ; tín đồ; người theo dõi (trên mạng xã hội)', 'n.', 'follow (v.), following (n.)', 'Đồng nghĩa: supporter, adherent · Trái nghĩa: leader', 'Chỉ người theo dõi hoặc tài khoản đăng ký nhận thông tin, không nhất thiết phải là người hâm mộ cuồng nhiệt.', 'My uncle is a devoted follower of the local team.', NULL, 'Chú tôi là một người ủng hộ trung thành của đội bóng địa phương.', '{"wordId":"follower","ukIpa":"/ˈfɒləʊə/","usIpa":"/ˈfɑːloʊɚ/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"Someone who supports a person, belief, or movement","vi":"người ủng hộ; tín đồ"},{"pos":"n.","en":"Someone who subscribes to another user''s social media updates","vi":"người theo dõi (trên mạng xã hội)"}],"examples":[{"en":"My uncle is a devoted follower of the local team.","vi":"Chú tôi là một người ủng hộ trung thành của đội bóng địa phương.","audioKind":"ex"},{"en":"Having many followers on social media does not necessarily make someone a reliable source of health advice.","vi":"Việc có nhiều người theo dõi trên mạng xã hội không nhất thiết khiến một người trở thành nguồn cung cấp lời khuyên sức khỏe đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"a devoted follower","vi":"một người ủng hộ trung thành"},{"en":"social media followers","vi":"người theo dõi trên mạng xã hội"},{"en":"gain followers","vi":"tăng lượng người theo dõi"}],"wordFamily":["follow (v.)","following (n.)"],"synonyms":["supporter","adherent"],"antonyms":["leader"],"tipVi":"Chỉ người theo dõi hoặc tài khoản đăng ký nhận thông tin, không nhất thiết phải là người hâm mộ cuồng nhiệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prayer', 'en-b1-8', 'prayer', '/prer/', 'B1', 'sự cầu nguyện; lời cầu nguyện; bài kinh nguyện', 'n.', 'pray (v.), prayerful (adj.)', NULL, 'Hành động cầu nguyện thường không đếm được; một lời cầu nguyện cụ thể là danh từ đếm được.', 'She closed her eyes and said a quiet prayer.', NULL, 'Cô ấy nhắm mắt lại và thầm cầu nguyện.', '{"wordId":"prayer","ukIpa":"/preə/","usIpa":"/prer/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the act of speaking to God or a god","vi":"sự cầu nguyện; lời cầu nguyện"},{"pos":"n.","en":"words spoken to God or a god","vi":"bài kinh nguyện"}],"examples":[{"en":"She closed her eyes and said a quiet prayer.","vi":"Cô ấy nhắm mắt lại và thầm cầu nguyện.","audioKind":"ex"},{"en":"For many communities, prayer provides comfort during difficult times and strengthens a sense of belonging.","vi":"Đối với nhiều cộng đồng, lời cầu nguyện mang lại sự an ủi trong những thời điểm khó khăn và củng cố ý thức thuộc về tập thể.","audioKind":"ex2"}],"collocations":[{"en":"say a prayer","vi":"cầu nguyện"},{"en":"daily prayer","vi":"lời cầu nguyện hàng ngày"},{"en":"a prayer for peace","vi":"lời cầu nguyện cho hòa bình"}],"wordFamily":["pray (v.)","prayerful (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Hành động cầu nguyện thường không đếm được; một lời cầu nguyện cụ thể là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_register', 'en-b1-8', 'register', '/ˈredʒɪstər/', 'B1', 'đăng ký; ghi danh; sổ đăng ký; danh sách chính thức; hiển thị; ghi lại (trên thiết bị đo)', 'v.', 'registration (n.), registered (adj.)', 'Đồng nghĩa: enrol, record', 'Đăng ký khóa học dùng register for; đăng ký làm gì dùng register to do.', 'You can register for swimming lessons at the pool.', NULL, 'Bạn có thể đăng ký học bơi tại hồ bơi.', '{"wordId":"register","ukIpa":"/ˈredʒɪstə/","usIpa":"/ˈredʒɪstər/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"To put information on an official list","vi":"đăng ký; ghi danh"},{"pos":"n.","en":"An official list or record of people or things","vi":"sổ đăng ký; danh sách chính thức"},{"pos":"v.","en":"To show or record an amount on a measuring instrument","vi":"hiển thị; ghi lại (trên thiết bị đo)"}],"examples":[{"en":"You can register for swimming lessons at the pool.","vi":"Bạn có thể đăng ký học bơi tại hồ bơi.","audioKind":"ex"},{"en":"Residents should be able to register for local healthcare services online, reducing unnecessary travel and administrative delays.","vi":"Cư dân nên có thể đăng ký sử dụng các dịch vụ y tế địa phương trực tuyến, giúp giảm bớt việc đi lại không cần thiết và sự chậm trễ hành chính.","audioKind":"ex2"}],"collocations":[{"en":"register for a course","vi":"đăng ký một khóa học"},{"en":"register to vote","vi":"đăng ký đi bầu cử"},{"en":"an attendance register","vi":"sổ điểm danh"},{"en":"register a complaint","vi":"chính thức khiếu nại"}],"wordFamily":["registration (n.)","registered (adj.)"],"synonyms":["enrol","record"],"antonyms":[],"tipVi":"Đăng ký khóa học dùng register for; đăng ký làm gì dùng register to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_respect', 'en-b1-8', 'respect', '/rɪˈspekt/', 'B1', 'sự tôn trọng; lòng kính trọng; tôn trọng; tuân thủ; khía cạnh; phương diện', 'n.', 'respectful (adj.), respectfully (adv.), respectable (adj.), disrespect (n.)', 'Trái nghĩa: disrespect', 'Danh từ thường đi với giới từ for; động từ đi thẳng với tân ngữ, không thêm for.', 'She showed respect by listening without interrupting her colleague.', NULL, 'Cô ấy thể hiện sự tôn trọng bằng cách lắng nghe mà không ngắt lời đồng nghiệp.', '{"wordId":"respect","ukIpa":"/rɪˈspekt/","usIpa":"/rɪˈspekt/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"Admiration for someone or consideration for their rights and feelings.","vi":"sự tôn trọng; lòng kính trọng"},{"pos":"v.","en":"To value someone or follow a rule or agreement.","vi":"tôn trọng; tuân thủ"},{"pos":"n.","en":"A particular feature or aspect of something.","vi":"khía cạnh; phương diện"}],"examples":[{"en":"She showed respect by listening without interrupting her colleague.","vi":"Cô ấy thể hiện sự tôn trọng bằng cách lắng nghe mà không ngắt lời đồng nghiệp.","audioKind":"ex"},{"en":"Schools should encourage students to respect different opinions while evaluating the evidence behind each argument.","vi":"Nhà trường nên khuyến khích học sinh tôn trọng các quan điểm khác nhau đồng thời đánh giá các bằng chứng đằng sau mỗi lập luận.","audioKind":"ex2"}],"collocations":[{"en":"show respect for","vi":"thể hiện sự tôn trọng đối với"},{"en":"mutual respect","vi":"sự tôn trọng lẫn nhau"},{"en":"respect privacy","vi":"tôn trọng quyền riêng tư"},{"en":"in this respect","vi":"về mặt này; xét ở phương diện này"}],"wordFamily":["respectful (adj.)","respectfully (adv.)","respectable (adj.)","disrespect (n.)"],"synonyms":[],"antonyms":["disrespect"],"tipVi":"Danh từ thường đi với giới từ for; động từ đi thẳng với tân ngữ, không thêm for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_major', 'en-b1-8', 'major', '/ˈmeɪdʒər/', 'B1', 'lớn; trọng yếu; nghiêm trọng; chuyên ngành đại học; sinh viên chuyên ngành; học chuyên ngành', 'adj.', 'majority (n.)', 'Đồng nghĩa: significant, important · Trái nghĩa: minor', 'Động từ chuyên ngành dùng major in; chủ yếu dùng trong tiếng Anh-Mỹ.', 'The storm caused major damage to our roof.', NULL, 'Cơn bão đã gây ra thiệt hại lớn cho mái nhà của chúng tôi.', '{"wordId":"major","ukIpa":"/ˈmeɪdʒə/","usIpa":"/ˈmeɪdʒər/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"very important, large, or serious","vi":"lớn; trọng yếu; nghiêm trọng"},{"pos":"n.","en":"a main university subject, or a student studying that subject","vi":"chuyên ngành đại học; sinh viên chuyên ngành"},{"pos":"v.","en":"to study a particular subject as your main university subject","vi":"học chuyên ngành"}],"examples":[{"en":"The storm caused major damage to our roof.","vi":"Cơn bão đã gây ra thiệt hại lớn cho mái nhà của chúng tôi.","audioKind":"ex"},{"en":"Access to affordable childcare remains a major concern for parents who wish to return to work.","vi":"Việc tiếp cận dịch vụ chăm sóc trẻ em với chi phí phải chăng vẫn là mối quan tâm lớn đối với các bậc cha mẹ muốn quay lại làm việc.","audioKind":"ex2"}],"collocations":[{"en":"major problem","vi":"vấn đề lớn"},{"en":"major role","vi":"vai trò quan trọng"},{"en":"major in biology","vi":"chuyên ngành sinh học"},{"en":"major breakthrough","vi":"bước đột phá lớn"}],"wordFamily":["majority (n.)"],"synonyms":["significant","important"],"antonyms":["minor"],"tipVi":"Động từ chuyên ngành dùng major in; chủ yếu dùng trong tiếng Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contact', 'en-b1-8', 'contact', '/ˈkɑːntækt/', 'B1', 'sự liên lạc; sự tiếp xúc; liên lạc; kết nối; người quen; mối quan hệ', 'n.', 'contactable (adj.), contactless (adj.)', NULL, 'Động từ contact trực tiếp tiếp nhận tân ngữ chỉ người, không thêm with; danh từ có thể đi kèm với with.', 'Please contact the receptionist if you lose your key.', NULL, 'Vui lòng liên hệ với nhân viên lễ tân nếu bạn làm mất chìa khóa.', '{"wordId":"contact","ukIpa":"/ˈkɒntækt/","usIpa":"/ˈkɑːntækt/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"Communication with someone, or physical touching between things.","vi":"sự liên lạc; sự tiếp xúc"},{"pos":"v.","en":"To communicate with someone by calling, writing, or another method.","vi":"liên lạc; kết nối"},{"pos":"n.","en":"Someone you know who can offer help or information.","vi":"người quen; mối quan hệ"}],"examples":[{"en":"Please contact the receptionist if you lose your key.","vi":"Vui lòng liên hệ với nhân viên lễ tân nếu bạn làm mất chìa khóa.","audioKind":"ex"},{"en":"Regular contact with family members can reduce loneliness among older people who live alone.","vi":"Việc thường xuyên liên lạc với các thành viên trong gia đình có thể làm giảm bớt cảm giác cô đơn ở những người cao tuổi sống một mình.","audioKind":"ex2"}],"collocations":[{"en":"keep in contact with","vi":"giữ liên lạc với"},{"en":"contact details","vi":"chi tiết liên hệ"},{"en":"direct contact","vi":"tiếp xúc trực tiếp"},{"en":"make contact with","vi":"lập liên lạc với"}],"wordFamily":["contactable (adj.)","contactless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ contact trực tiếp tiếp nhận tân ngữ chỉ người, không thêm with; danh từ có thể đi kèm với with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jail', 'en-b1-8', 'jail', '/dʒeɪl/', 'B1', 'nhà tù; trại giam; tống giam; bỏ tù', 'n.', 'jailer (n.)', 'Đồng nghĩa: prison, imprison', 'in jail chỉ trạng thái đang bị giam giữ, không thêm mạo từ; cách viết cổ trong tiếng Anh-Anh là gaol.', 'The old jail now welcomes visitors as a museum.', NULL, 'Nhà tù cũ giờ đây chào đón du khách đến tham quan như một bảo tàng.', '{"wordId":"jail","ukIpa":"/dʒeɪl/","usIpa":"/dʒeɪl/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A place where people are kept as punishment or awaiting trial.","vi":"nhà tù; trại giam"},{"pos":"v.","en":"Put someone in jail.","vi":"tống giam; bỏ tù"}],"examples":[{"en":"The old jail now welcomes visitors as a museum.","vi":"Nhà tù cũ giờ đây chào đón du khách đến tham quan như một bảo tàng.","audioKind":"ex"},{"en":"Education programmes in jail can help prisoners develop skills and improve their chances of finding work after release.","vi":"Các chương trình giáo dục trong tù có thể giúp các phạm nhân phát triển kỹ năng và cải thiện cơ hội tìm kiếm việc làm sau khi mãn hạn tù.","audioKind":"ex2"}],"collocations":[{"en":"go to jail","vi":"vào tù"},{"en":"a jail sentence","vi":"bản án tù"},{"en":"be jailed for fraud","vi":"bị bỏ tù vì tội lừa đảo"}],"wordFamily":["jailer (n.)"],"synonyms":["prison","imprison"],"antonyms":[],"tipVi":"in jail chỉ trạng thái đang bị giam giữ, không thêm mạo từ; cách viết cổ trong tiếng Anh-Anh là gaol.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disadvantage', 'en-b1-8', 'disadvantage', '/ˌdɪsədˈvæntɪdʒ/', 'B1', 'bất lợi; điểm bất lợi; điểm yếu', 'n.', 'disadvantaged (adj.), advantage (n.)', 'Đồng nghĩa: drawback, downside · Trái nghĩa: advantage, benefit', 'Diễn tả việc ở vào thế bất lợi, dùng at a disadvantage.', 'The main disadvantage of this flat is the noise.', NULL, 'Nhược điểm chính của căn hộ này là tiếng ồn lớn.', '{"wordId":"disadvantage","ukIpa":"/ˌdɪsədˈvɑːntɪdʒ/","usIpa":"/ˌdɪsədˈvæntɪdʒ/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"something that makes success harder or reduces something''s value","vi":"bất lợi; điểm bất lợi; điểm yếu"}],"examples":[{"en":"The main disadvantage of this flat is the noise.","vi":"Nhược điểm chính của căn hộ này là tiếng ồn lớn.","audioKind":"ex"},{"en":"Students without reliable internet access face a significant disadvantage when schools rely heavily on online learning.","vi":"Những học sinh thiếu khả năng truy cập internet ổn định phải đối mặt với một bất lợi đáng kể khi nhà trường phụ thuộc nhiều vào việc học trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"at a disadvantage","vi":"ở thế bất lợi"},{"en":"a major disadvantage","vi":"một bất lợi lớn"},{"en":"advantages and disadvantages","vi":"ưu điểm và nhược điểm"}],"wordFamily":["disadvantaged (adj.)","advantage (n.)"],"synonyms":["drawback","downside"],"antonyms":["advantage","benefit"],"tipVi":"Diễn tả việc ở vào thế bất lợi, dùng at a disadvantage.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_identity', 'en-b1-8', 'identity', '/aɪˈdentəti/', 'B1', 'thân phận; danh tính; bản sắc; tính đặc trưng; sự nhận diện', 'n.', 'identify (v.), identification (n.), identifiable (adj.)', NULL, 'identity chỉ danh tính hoặc bản sắc; identify là động từ có nghĩa là nhận diện, xác định danh tính.', 'The receptionist checked my identity before handing me the key.', NULL, 'Nhân viên lễ tân kiểm tra giấy tờ tùy thân của tôi trước khi đưa chìa khóa.', '{"wordId":"identity","ukIpa":"/aɪˈdentəti/","usIpa":"/aɪˈdentəti/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"who a person is","vi":"thân phận; danh tính"},{"pos":"n.","en":"qualities and beliefs distinguishing a person or group","vi":"bản sắc; tính đặc trưng; sự nhận diện"}],"examples":[{"en":"The receptionist checked my identity before handing me the key.","vi":"Nhân viên lễ tân kiểm tra giấy tờ tùy thân của tôi trước khi đưa chìa khóa.","audioKind":"ex"},{"en":"Preserving local languages can strengthen cultural identity while helping communities pass traditional knowledge to younger generations.","vi":"Việc bảo tồn tiếng địa phương có thể củng cố bản sắc văn hóa đồng thời giúp các cộng đồng truyền lại tri thức truyền thống cho thế hệ trẻ.","audioKind":"ex2"}],"collocations":[{"en":"proof of identity","vi":"bằng chứng nhận dạng; giấy tờ tùy thân"},{"en":"cultural identity","vi":"bản sắc văn hóa"},{"en":"sense of identity","vi":"ý thức về bản thân; cảm giác thuộc về một nhóm"},{"en":"identity theft","vi":"trộm cắp danh tính"}],"wordFamily":["identify (v.)","identification (n.)","identifiable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"identity chỉ danh tính hoặc bản sắc; identify là động từ có nghĩa là nhận diện, xác định danh tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_treat', 'en-b1-8', 'treat', '/triːt/', 'B1', 'đối xử; đối đãi; cư xử; điều trị; chữa trị; sự thết đãi; niềm vui đặc biệt', 'v.', 'treatment (n.), treatable (adj.), untreated (adj.)', NULL, 'treat someone to a meal diễn tả việcết đãi ai đó một bữa ăn.', 'Our neighbours treat their rescue dog with great kindness.', NULL, 'Những người hàng xóm của chúng tôi đối xử với chú chó cứu hộ của họ vô cùng tử tế.', '{"wordId":"treat","ukIpa":"/triːt/","usIpa":"/triːt/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"Behave towards someone or consider something in a particular way.","vi":"đối xử; đối đãi; cư xử"},{"pos":"v.","en":"Use medicine or other care to help an illness improve.","vi":"điều trị; chữa trị"},{"pos":"n.","en":"Something enjoyable that you do not have very often.","vi":"sự thết đãi; niềm vui đặc biệt"}],"examples":[{"en":"Our neighbours treat their rescue dog with great kindness.","vi":"Những người hàng xóm của chúng tôi đối xử với chú chó cứu hộ của họ vô cùng tử tế.","audioKind":"ex"},{"en":"Employers should treat all applicants fairly and assess their suitability using relevant skills rather than personal background.","vi":"Các nhà tuyển dụng nên đối xử công bằng với tất cả ứng viên và đánh giá sự phù hợp của họ thông qua các kỹ năng liên quan thay vì nền tảng cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"treat someone with respect","vi":"đối xử với ai đó bằng sự tôn trọng"},{"en":"treat something as","vi":"coi cái gì như là"},{"en":"treat a disease","vi":"chữa bệnh"},{"en":"a special treat","vi":"một niềm vui đặc biệt"}],"wordFamily":["treatment (n.)","treatable (adj.)","untreated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"treat someone to a meal diễn tả việcết đãi ai đó một bữa ăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deserve', 'en-b1-8', 'deserve', '/dɪˈzɝːv/', 'B1', 'xứng đáng; có công', 'v.', 'deserving (adj.), undeserved (adj.)', 'Đồng nghĩa: merit', 'Kết hợp với danh từ hoặc to do; không dùng deserve doing theo nghĩa chủ động.', 'You deserve a rest after carrying those heavy boxes.', NULL, 'Bạn rất đáng được nghỉ ngơi sau khi khiêng những chiếc thùng nặng đó.', '{"wordId":"deserve","ukIpa":"/dɪˈzɜːv/","usIpa":"/dɪˈzɝːv/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"To have earned something because of your actions or qualities.","vi":"xứng đáng; có công"}],"examples":[{"en":"You deserve a rest after carrying those heavy boxes.","vi":"Bạn rất đáng được nghỉ ngơi sau khi khiêng những chiếc thùng nặng đó.","audioKind":"ex"},{"en":"Healthcare workers deserve greater recognition because their dedication contributes directly to the wellbeing of society.","vi":"Nhân viên y tế xứng đáng nhận được sự ghi nhận lớn hơn vì sự cống hiến của họ đóng góp trực tiếp vào hạnh phúc của xã hội.","audioKind":"ex2"}],"collocations":[{"en":"deserve praise","vi":"xứng đáng được ca ngợi"},{"en":"deserve attention","vi":"đáng được quan tâm"},{"en":"deserve to win","vi":"xứng đáng chiến thắng"}],"wordFamily":["deserving (adj.)","undeserved (adj.)"],"synonyms":["merit"],"antonyms":[],"tipVi":"Kết hợp với danh từ hoặc to do; không dùng deserve doing theo nghĩa chủ động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_benefit', 'en-b1-8', 'benefit', '/ˈbenɪfɪt/', 'B1', 'lợi ích; ưu điểm; hưởng lợi; giúp ích; trợ cấp; tiền trợ cấp chính phủ', 'n.', 'beneficial (adj.), beneficiary (n.)', 'Đồng nghĩa: advantage, gain · Trái nghĩa: disadvantage', 'benefit sb chỉ làm cho ai đó hưởng lợi; benefit from chỉ việc nhận được lợi ích từ cái gì.', 'One benefit of cycling is arriving home feeling refreshed.', NULL, 'Một lợi ích của việc đạp xe là về đến nhà với tinh thần sảng khoái.', '{"wordId":"benefit","ukIpa":"/ˈbenɪfɪt/","usIpa":"/ˈbenɪfɪt/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"a helpful or positive effect of something","vi":"lợi ích; ưu điểm"},{"pos":"v.","en":"to help someone or receive help or an advantage","vi":"hưởng lợi; giúp ích"},{"pos":"n.","en":"money provided by the government to people needing support","vi":"trợ cấp; tiền trợ cấp chính phủ"}],"examples":[{"en":"One benefit of cycling is arriving home feeling refreshed.","vi":"Một lợi ích của việc đạp xe là về đến nhà với tinh thần sảng khoái.","audioKind":"ex"},{"en":"Rural communities can benefit from improved internet access through greater opportunities for education and employment.","vi":"Các cộng đồng nông thôn có thể hưởng lợi từ việc cải thiện khả năng truy cập Internet thông qua các cơ hội giáo dục và việc làm rộng mở hơn.","audioKind":"ex2"}],"collocations":[{"en":"health benefits","vi":"lợi ích sức khỏe"},{"en":"benefit from","vi":"hưởng lợi từ"},{"en":"unemployment benefit","vi":"trợ cấp thất nghiệp"},{"en":"mutual benefit","vi":"lợi ích song phương; cùng có lợi"}],"wordFamily":["beneficial (adj.)","beneficiary (n.)"],"synonyms":["advantage","gain"],"antonyms":["disadvantage"],"tipVi":"benefit sb chỉ làm cho ai đó hưởng lợi; benefit from chỉ việc nhận được lợi ích từ cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_christian', 'en-b1-8', 'Christian', '/ˈkrɪstʃən/', 'B1', 'thuộc đạo Thiên Chúa; thuộc Cơ Đốc giáo; tín đồ Thiên Chúa giáo; tín đồ Cơ Đốc giáo', 'adj.', 'Christianity (n.)', NULL, 'Dù đóng vai trò danh từ hay tính từ, chữ cái đầu tiên của từ này luôn phải viết hoa.', 'Our neighbour attends a Christian church near the park.', NULL, 'Người hàng xóm của chúng tôi đi nhà thờ Thiên Chúa giáo gần công viên.', '{"wordId":"christian","ukIpa":"/ˈkrɪstʃən/","usIpa":"/ˈkrɪstʃən/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"relating to Christianity or its followers","vi":"thuộc đạo Thiên Chúa; thuộc Cơ Đốc giáo"},{"pos":"n.","en":"a person who follows the religion based on Jesus Christ","vi":"tín đồ Thiên Chúa giáo; tín đồ Cơ Đốc giáo"}],"examples":[{"en":"Our neighbour attends a Christian church near the park.","vi":"Người hàng xóm của chúng tôi đi nhà thờ Thiên Chúa giáo gần công viên.","audioKind":"ex"},{"en":"Christian charities, alongside other religious and secular organisations, provide essential support for vulnerable communities in many countries.","vi":"Các tổ chức từ thiện Cơ Đốc giáo, cùng với các tổ chức tôn giáo và thế tục khác, cung cấp sự hỗ trợ thiết yếu cho các cộng đồng dễ bị tổn thương ở nhiều quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"Christian church","vi":"nhà thờ Thiên Chúa giáo"},{"en":"Christian faith","vi":"đức tin Cơ Đốc"},{"en":"Christian community","vi":"cộng đồng Cơ Đốc giáo"}],"wordFamily":["Christianity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dù đóng vai trò danh từ hay tính từ, chữ cái đầu tiên của từ này luôn phải viết hoa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_campaign', 'en-b1-8', 'campaign', '/kæmˈpeɪn/', 'B1', 'chiến dịch; cuộc vận động; tham gia vận động; tổ chức chiến dịch; chiến dịch quân sự', 'n.', 'campaigner (n.)', 'Đồng nghĩa: drive', 'động từ đi với for thể hiện sự tranh đấu, ủng hộ, đi với against thể hiện sự phản đối.', 'Our school launched a campaign to reduce food waste.', NULL, 'Trường học của chúng tôi đã phát động một chiến dịch nhằm giảm thiểu lãng phí thực phẩm.', '{"wordId":"campaign","ukIpa":"/kæmˈpeɪn/","usIpa":"/kæmˈpeɪn/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A series of organised activities aimed at achieving a goal","vi":"chiến dịch; cuộc vận động"},{"pos":"v.","en":"To organise or take part in activities supporting a cause","vi":"tham gia vận động; tổ chức chiến dịch"},{"pos":"n.","en":"A series of military operations with a particular objective","vi":"chiến dịch quân sự"}],"examples":[{"en":"Our school launched a campaign to reduce food waste.","vi":"Trường học của chúng tôi đã phát động một chiến dịch nhằm giảm thiểu lãng phí thực phẩm.","audioKind":"ex"},{"en":"Public health campaigns can encourage healthier habits, especially when supported by affordable access to nutritious food.","vi":"Các chiến dịch y tế cộng đồng có thể thúc đẩy thói quen sống lành mạnh hơn, đặc biệt khi được hỗ trợ bởi khả năng tiếp cận thực phẩm bổ dưỡng với giá cả phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"launch a campaign","vi":"phát động một chiến dịch"},{"en":"an advertising campaign","vi":"chiến dịch quảng cáo"},{"en":"campaign for reform","vi":"vận động cải cách"},{"en":"campaign against pollution","vi":"chiến dịch chống ô nhiễm"}],"wordFamily":["campaigner (n.)"],"synonyms":["drive"],"antonyms":[],"tipVi":"động từ đi với for thể hiện sự tranh đấu, ủng hộ, đi với against thể hiện sự phản đối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_background', 'en-b1-8', 'background', '/ˈbækɡraʊnd/', 'B1', 'xuất thân; nền tảng gia đình, học vấn và kinh nghiệm định hình cuộc đời ai đó; thông tin nền; sự việc cần thiết để hiểu rõ một tình huống; hậu cảnh; phần khung cảnh phía sau chủ thể chính', 'n.', NULL, 'Trái nghĩa: foreground', 'Lĩnh vực kinh nghiệm dùng background in; ở hậu cảnh dùng in the background.', 'Her background in nursing helped her care for Grandpa.', NULL, 'Nền tảng kinh nghiệm điều dưỡng đã giúp cô ấy chăm sóc ông nội.', '{"wordId":"background","ukIpa":"/ˈbækɡraʊnd/","usIpa":"/ˈbækɡraʊnd/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"The family, education, and experience that shape someone''s life","vi":"xuất thân; nền tảng gia đình, học vấn và kinh nghiệm định hình cuộc đời ai đó"},{"pos":"n.","en":"Information or events needed to understand a situation","vi":"thông tin nền; sự việc cần thiết để hiểu rõ một tình huống"},{"pos":"n.","en":"The part of a scene behind the main subject","vi":"hậu cảnh; phần khung cảnh phía sau chủ thể chính"}],"examples":[{"en":"Her background in nursing helped her care for Grandpa.","vi":"Nền tảng kinh nghiệm điều dưỡng đã giúp cô ấy chăm sóc ông nội.","audioKind":"ex"},{"en":"Universities should provide equal opportunities for applicants from different social backgrounds, regardless of their family income.","vi":"Các trường đại học nên cung cấp cơ hội bình đẳng cho các ứng viên đến từ các nền tảng xã hội khác nhau, bất kể thu nhập gia đình của họ.","audioKind":"ex2"}],"collocations":[{"en":"a professional background","vi":"nền tảng chuyên môn"},{"en":"background information","vi":"thông tin nền"},{"en":"in the background","vi":"ở phía sau hậu cảnh"},{"en":"a disadvantaged background","vi":"hoàn cảnh khó khăn"}],"wordFamily":[],"synonyms":[],"antonyms":["foreground"],"tipVi":"Lĩnh vực kinh nghiệm dùng background in; ở hậu cảnh dùng in the background.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rescue', 'en-b1-8', 'rescue', '/ˈreskjuː/', 'B1', 'cứu hộ; giải cứu ai đó hoặc vật gì khỏi nguy hiểm hoặc khó khăn; cuộc giải cứu; hành động cứu người hoặc vật khỏi hiểm nguy', 'v.', 'rescuer (n.)', 'Đồng nghĩa: save', 'Thường dùng cấu trúc rescue sb from sth, thể hiện việc cứu ai thoát khỏi tình thế hiểm nghèo.', 'Firefighters rescued a kitten from the roof this morning.', NULL, 'Sáng nay, các lính cứu hỏa đã giải cứu một chú mèo con khỏi mái nhà.', '{"wordId":"rescue","ukIpa":"/ˈreskjuː/","usIpa":"/ˈreskjuː/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"To save someone or something from danger or difficulty.","vi":"cứu hộ; giải cứu ai đó hoặc vật gì khỏi nguy hiểm hoặc khó khăn"},{"pos":"n.","en":"An act of saving someone or something from danger.","vi":"cuộc giải cứu; hành động cứu người hoặc vật khỏi hiểm nguy"}],"examples":[{"en":"Firefighters rescued a kitten from the roof this morning.","vi":"Sáng nay, các lính cứu hỏa đã giải cứu một chú mèo con khỏi mái nhà.","audioKind":"ex"},{"en":"Coastal communities need well-equipped teams to rescue residents when severe flooding blocks roads and damages homes.","vi":"Các cộng đồng ven biển cần những đội cứu hộ được trang bị đầy đủ để giải cứu người dân khi lũ lụt nặng làm tắc nghẽn đường sá và phá hủy nhà cửa.","audioKind":"ex2"}],"collocations":[{"en":"rescue someone from","vi":"cứu ai khỏi cái gì"},{"en":"a rescue team","vi":"đội cứu hộ"},{"en":"a rescue operation","vi":"chiến dịch cứu hộ"},{"en":"come to the rescue","vi":"đến để giải cứu"}],"wordFamily":["rescuer (n.)"],"synonyms":["save"],"antonyms":[],"tipVi":"Thường dùng cấu trúc rescue sb from sth, thể hiện việc cứu ai thoát khỏi tình thế hiểm nghèo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relation', 'en-b1-8', 'relation', '/rɪˈleɪʃən/', 'B1', 'mối quan hệ; sự liên quan; họ hàng; người thân', 'n.', 'relate (v.), related (adj.), relationship (n.), relational (adj.)', 'Đồng nghĩa: connection, link, relative', 'Mối quan hệ giữa các quốc gia hoặc các nhóm thường dùng danh từ số nhiều relations.', 'The price seems to bear no relation to quality.', NULL, 'Mức giá này dường như không có sự liên quan nào đến chất lượng.', '{"wordId":"relation","ukIpa":"/rɪˈleɪʃən/","usIpa":"/rɪˈleɪʃən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"a connection between people, things, or ideas","vi":"mối quan hệ; sự liên quan"},{"pos":"n.","en":"a person who belongs to your family","vi":"họ hàng; người thân"}],"examples":[{"en":"The price seems to bear no relation to quality.","vi":"Mức giá này dường như không có sự liên quan nào đến chất lượng.","audioKind":"ex"},{"en":"Researchers are examining the relation between access to green spaces and mental health in urban communities.","vi":"Các nhà nghiên cứu đang khảo sát mối liên hệ giữa khả năng tiếp cận không gian xanh và sức khỏe tinh thần trong cộng đồng đô thị.","audioKind":"ex2"}],"collocations":[{"en":"in relation to","vi":"liên quan đến; đối với"},{"en":"bear no relation to","vi":"không liên quan gì đến"},{"en":"relations between countries","vi":"mối quan hệ giữa các quốc gia"},{"en":"a close relation","vi":"họ hàng gần"}],"wordFamily":["relate (v.)","related (adj.)","relationship (n.)","relational (adj.)"],"synonyms":["connection","link","relative"],"antonyms":[],"tipVi":"Mối quan hệ giữa các quốc gia hoặc các nhóm thường dùng danh từ số nhiều relations.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fiance', 'en-b1-8', 'fiance', '/ˌfiːɑːnˈseɪ/', 'B1', 'vị hôn phu; chồng chưa cưới', 'n.', 'fiancee (n.)', NULL, 'Cũng có thể viết là fiancé; vợ chưa cưới là fiancee hoặc fiancée.', 'My fiance and I are choosing wedding flowers.', NULL, 'Tôi và vị hôn phu đang chọn hoa cưới.', '{"wordId":"fiance","ukIpa":"/fiˈɒnseɪ/","usIpa":"/ˌfiːɑːnˈseɪ/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A man who is engaged to be married.","vi":"vị hôn phu; chồng chưa cưới"}],"examples":[{"en":"My fiance and I are choosing wedding flowers.","vi":"Tôi và vị hôn phu đang chọn hoa cưới.","audioKind":"ex"},{"en":"Moving abroad with a fiance can require careful planning around employment, housing, and future family responsibilities.","vi":"Chuyển ra nước ngoài cùng vị hôn phu có thể đòi hỏi sự chuẩn bị kỹ lưỡng về việc làm, nhà ở và trách nhiệm gia đình trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"her fiance","vi":"vị hôn phu của cô ấy"},{"en":"my fiance and I","vi":"tôi và vị hôn phu của tôi"}],"wordFamily":["fiancee (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cũng có thể viết là fiancé; vợ chưa cưới là fiancee hoặc fiancée.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_protest', 'en-b1-8', 'protest', '/ˈproʊtest/', 'B1', 'sự phản đối mạnh mẽ; cuộc biểu tình, cuộc kháng nghị; bày tỏ sự không đồng tình mạnh mẽ; phản đối', 'n.', 'protester (n.), protestation (n.)', 'Đồng nghĩa: objection, demonstration', 'Phiên âm trên là danh từ; động từ đọc là /prəˈtest/, thường đi với against.', 'Residents held a peaceful protest outside the town hall.', NULL, 'Người dân đã tổ chức một cuộc biểu tình ôn hòa bên ngoài tòa nhà thị chính.', '{"wordId":"protest","ukIpa":"/ˈprəʊtest/","usIpa":"/ˈproʊtest/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"An expression or action showing strong disagreement or opposition.","vi":"sự phản đối mạnh mẽ; cuộc biểu tình, cuộc kháng nghị"},{"pos":"v.","en":"Express strong disagreement with something.","vi":"bày tỏ sự không đồng tình mạnh mẽ; phản đối"}],"examples":[{"en":"Residents held a peaceful protest outside the town hall.","vi":"Người dân đã tổ chức một cuộc biểu tình ôn hòa bên ngoài tòa nhà thị chính.","audioKind":"ex"},{"en":"Citizens may protest against environmental policies that fail to protect local forests and water supplies.","vi":"Công dân có thể phản đối các chính sách môi trường không bảo vệ được rừng và nguồn nước địa phương.","audioKind":"ex2"}],"collocations":[{"en":"peaceful protest","vi":"cuộc biểu tình ôn hòa"},{"en":"protest against","vi":"biểu tình chống lại"},{"en":"in protest at","vi":"để phản đối..."},{"en":"under protest","vi":"bị ép buộc; miễn cưỡng kháng nghị"}],"wordFamily":["protester (n.)","protestation (n.)"],"synonyms":["objection","demonstration"],"antonyms":[],"tipVi":"Phiên âm trên là danh từ; động từ đọc là /prəˈtest/, thường đi với against.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_8_1', 'en-b1-8', 'Cách dùng “responsibility” (n.) — trách nhiệm; sự chịu trách nhiệm', 'take responsibility for  ·  a sense of responsibility  ·  accept responsibility', 'Khi chỉ trách nhiệm chung chung thường không đếm được; khi chỉ nhiệm vụ cụ thể thì đếm được; phía sau thường đi với giới từ for.', 'Họ từ (Word Family): responsible (adj.), responsibly (adv.), irresponsible (adj.), irresponsibility (n.) | Đồng nghĩa: duty, obligation', '[{"hanzi":"Feeding the dog is your responsibility this weekend.","pinyin":"","meaning":"Cho chó ăn là trách nhiệm của bạn vào cuối tuần này."},{"hanzi":"Governments and businesses share responsibility for reducing waste, but individuals also have an important role to play.","pinyin":"","meaning":"Chính phủ và các doanh nghiệp cùng chia sẻ trách nhiệm giảm thiểu rác thải, nhưng các cá nhân cũng đóng một vai trò quan trọng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_8_2', 'en-b1-8', 'Cách dùng “issue” (n.) — vấn đề, đề tài (vấn đề quan trọng cần được thảo luận)', 'address an issue  ·  a controversial issue  ·  issue a warning', 'Từ issue khi chỉ vấn đề thường mang nghĩa là một đề tài cần được thảo luận, không nhất thiết phải là một rắc rối khó khăn.', 'Họ từ (Word Family): issuance (n.), issuer (n.), reissue (v.)', '[{"hanzi":"We discussed the parking issue at our neighbourhood meeting.","pinyin":"","meaning":"Chúng tôi đã thảo luận về vấn đề đậu xe tại cuộc họp khu1 phố của mình."},{"hanzi":"Governments must address the issue of housing affordability to ensure that young adults can live independently.","pinyin":"","meaning":"Chính phủ phải giải quyết vấn đề khả năng chi trả nhà ở để đảm bảo rằng người trẻ tuổi có thể sống tự lập."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_8_3', 'en-b1-8', 'Cách dùng “follower” (n.) — người ủng hộ; tín đồ', 'a devoted follower  ·  social media followers  ·  gain followers', 'Chỉ người theo dõi hoặc tài khoản đăng ký nhận thông tin, không nhất thiết phải là người hâm mộ cuồng nhiệt.', 'Họ từ (Word Family): follow (v.), following (n.) | Đồng nghĩa: supporter, adherent · Trái nghĩa: leader', '[{"hanzi":"My uncle is a devoted follower of the local team.","pinyin":"","meaning":"Chú tôi là một người ủng hộ trung thành của đội bóng địa phương."},{"hanzi":"Having many followers on social media does not necessarily make someone a reliable source of health advice.","pinyin":"","meaning":"Việc có nhiều người theo dõi trên mạng xã hội không nhất thiết khiến một người trở thành nguồn cung cấp lời khuyên sức khỏe đáng tin cậy."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_8_4', 'en-b1-8', 'Cách dùng “volunteer” (n.) — tình nguyện viên; người làm công tác thiện nguyện', 'volunteer work  ·  volunteer to help  ·  volunteer for a charity', 'Dùng volunteer to do để diễn tả hành động tự nguyện làm việc gì; voluntary là tính từ thông dụng liên quan.', 'Họ từ (Word Family): voluntary (adj.), voluntarily (adv.)', '[{"hanzi":"A volunteer helped us carry the boxes upstairs.","pinyin":"","meaning":"Một tình nguyện viên đã giúp chúng tôi khuân các thùng hàng lên lầu."},{"hanzi":"Universities can encourage students to volunteer in their communities by offering flexible schedules and practical support.","pinyin":"","meaning":"Các trường đại học có thể khuyến khích sinh viên tham gia công tác tình nguyện tại cộng đồng bằng cách cung cấp lịch trình linh hoạt và hỗ trợ thiết thực."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_8_1', 'en-b1-8', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_1_1', 'ten_b1_8_1', 'issue', 'We discussed the parking issue at our neighbourhood meeting.', 'We discussed the parking issue at our neighbourhood meeting.', '/ˈɪʃuː/', 'Chúng tôi đã thảo luận về vấn đề đậu xe tại cuộc họp khu1 phố của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_1_2', 'ten_b1_8_1', 'volunteer', 'A volunteer helped us carry the boxes upstairs.', 'A volunteer helped us carry the boxes upstairs.', '/ˌvɑːlənˈtɪr/', 'Một tình nguyện viên đã giúp chúng tôi khuân các thùng hàng lên lầu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_1_3', 'ten_b1_8_1', 'sister-in-law', 'My sister-in-law brought homemade soup when I was ill.', 'My sister-in-law brought homemade soup when I was ill.', '/ˈsɪstər ɪn lɔː/', 'Chị dâu tôi đã mang canh nhà nấu sang khi tôi ốm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_1_4', 'ten_b1_8_1', 'disabled', 'The pool has a lift for disabled swimmers.', 'The pool has a lift for disabled swimmers.', '/dɪsˈeɪbəld/', 'Hồ bơi có lắp đặt thang máy dành cho người bơi khuyết tật.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_1_5', 'ten_b1_8_1', 'hero', 'The firefighter became a local hero after the rescue.', 'The firefighter became a local hero after the rescue.', '/ˈhɪroʊ/', 'Người lính cứu hỏa đã trở thành người hùng địa phương sau vụ giải cứu.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_1_6', 'ten_b1_8_1', 'responsibility', 'Feeding the dog is your responsibility this weekend.', 'Feeding the dog is your responsibility this weekend.', '/rɪˌspɑːnsəˈbɪləti/', 'Cho chó ăn là trách nhiệm của bạn vào cuối tuần này.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_1_7', 'ten_b1_8_1', 'powerful', 'The powerful wind blew our garden chairs onto the grass.', 'The powerful wind blew our garden chairs onto the grass.', '/ˈpaʊərfəl/', 'Cơn gió mạnh đã thổi những chiếc ghế trong vườn của chúng tôi bay xuống bãi cỏ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_1_8', 'ten_b1_8_1', 'follower', 'My uncle is a devoted follower of the local team.', 'My uncle is a devoted follower of the local team.', '/ˈfɑːloʊɚ/', 'Chú tôi là một người ủng hộ trung thành của đội bóng địa phương.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_8_1_1', 'en-b1-8', 'ten_b1_8_1', 'listening', 'listening', 'We discussed the parking issue at our neighbourhood meeting.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã thảo luận về vấn đề đậu xe tại cuộc họp khu1 phố của mình.","Vui lòng liên hệ với nhân viên lễ tân nếu bạn làm mất chìa khóa.","Người hàng xóm của chúng tôi đi nhà thờ Thiên Chúa giáo gần công viên.","Nhân viên lễ tân kiểm tra giấy tờ tùy thân của tôi trước khi đưa chìa khóa."]'::jsonb, 0, 'We discussed the parking issue at our neighbourhood meeting. → Chúng tôi đã thảo luận về vấn đề đậu xe tại cuộc họp khu1 phố của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_8_1_2', 'en-b1-8', 'ten_b1_8_1', 'listening', 'listening', 'A volunteer helped us carry the boxes upstairs.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một tình nguyện viên đã giúp chúng tôi khuân các thùng hàng lên lầu.","Một lợi ích của việc đạp xe là về đến nhà với tinh thần sảng khoái.","Nền tảng kinh nghiệm điều dưỡng đã giúp cô ấy chăm sóc ông nội.","Cho chó ăn là trách nhiệm của bạn vào cuối tuần này."]'::jsonb, 0, 'A volunteer helped us carry the boxes upstairs. → Một tình nguyện viên đã giúp chúng tôi khuân các thùng hàng lên lầu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_8_1_3', 'en-b1-8', 'ten_b1_8_1', 'listening', 'listening', 'My sister-in-law brought homemade soup when I was ill.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hồ bơi có lắp đặt thang máy dành cho người bơi khuyết tật.","Cho chó ăn là trách nhiệm của bạn vào cuối tuần này.","Chị dâu tôi đã mang canh nhà nấu sang khi tôi ốm.","Chú tôi là một người ủng hộ trung thành của đội bóng địa phương."]'::jsonb, 2, 'My sister-in-law brought homemade soup when I was ill. → Chị dâu tôi đã mang canh nhà nấu sang khi tôi ốm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_8_2', 'en-b1-8', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_2_1', 'ten_b1_8_2', 'issue', 'Governments must address the issue of housing affordability to ensure that young adults can live independently.', 'Governments must address the issue of housing affordability to ensure that young adults can live independently.', '/ˈɪʃuː/', 'Chính phủ phải giải quyết vấn đề khả năng chi trả nhà ở để đảm bảo rằng người trẻ tuổi có thể sống tự lập.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_2_2', 'ten_b1_8_2', 'volunteer', 'Universities can encourage students to volunteer in their communities by offering flexible schedules and practical support.', 'Universities can encourage students to volunteer in their communities by offering flexible schedules and practical support.', '/ˌvɑːlənˈtɪr/', 'Các trường đại học có thể khuyến khích sinh viên tham gia công tác tình nguyện tại cộng đồng bằng cách cung cấp lịch trình linh hoạt và hỗ trợ thiết thực.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_2_3', 'ten_b1_8_2', 'sister-in-law', 'Sharing childcare with a sister-in-law can help working parents balance professional responsibilities and family life.', 'Sharing childcare with a sister-in-law can help working parents balance professional responsibilities and family life.', '/ˈsɪstər ɪn lɔː/', 'Việc cùng chia sẻ việc chăm sóc con cái với chị dâu có thể giúp các bậc phụ huynh đi làm cân bằng tốt hơn giữa trách nhiệm nghề nghiệp và đời sống gia đình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_2_4', 'ten_b1_8_2', 'disabled', 'Universities should provide accessible facilities and appropriate support to ensure that disabled students can participate fully in campus life.', 'Universities should provide accessible facilities and appropriate support to ensure that disabled students can participate fully in campus life.', '/dɪsˈeɪbəld/', 'Các trường đại học nên cung cấp các cơ sở vật chất dễ tiếp cận và sự hỗ trợ phù hợp để đảm bảo sinh viên khuyết tật có thể tham gia đầy đủ vào đời sống học đường.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_2_5', 'ten_b1_8_2', 'hero', 'Films often portray the hero as an exceptional individual, although real social progress usually requires collective effort.', 'Films often portray the hero as an exceptional individual, although real social progress usually requires collective effort.', '/ˈhɪroʊ/', 'Phim ảnh thường khắc họa nhân vật chính là một cá nhân xuất chúng, mặc dù tiến bộ xã hội thực sự thường đòi hỏi nỗ lực tập thể.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_8_2_6', 'ten_b1_8_2', 'responsibility', 'Governments and businesses share responsibility for reducing waste, but individuals also have an important role to play.', 'Governments and businesses share responsibility for reducing waste, but individuals also have an important role to play.', '/rɪˌspɑːnsəˈbɪləti/', 'Chính phủ và các doanh nghiệp cùng chia sẻ trách nhiệm giảm thiểu rác thải, nhưng các cá nhân cũng đóng một vai trò quan trọng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_8_2_1', 'en-b1-8', 'ten_b1_8_2', 'listening', 'listening', 'Governments must address the issue of housing affordability to ensure that young adults can live independently.', NULL, 'Trong câu vừa nghe, từ “issue” mang nghĩa nào sau đây?', '["lễ; nghi lễ; nghi thức","hài hước; liên quan đến hài kịch","vấn đề, đề tài (vấn đề quan trọng cần được thảo luận)","nhảy lò cò; nhảy chồm chồm"]'::jsonb, 2, '“issue” (/ˈɪʃuː/): vấn đề, đề tài (vấn đề quan trọng cần được thảo luận). Câu đầy đủ: Governments must address the issue of housing affordability to ensure that young adults can live independently.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_8_2_2', 'en-b1-8', 'ten_b1_8_2', 'listening', 'listening', 'Universities can encourage students to volunteer in their communities by offering flexible schedules and practical support.', NULL, 'Trong câu vừa nghe, từ “volunteer” mang nghĩa nào sau đây?', '["tái chế; tái tạo","tăng dần; ngày càng nhiều","hiếm; ít khi xảy ra","tình nguyện viên; người làm công tác thiện nguyện"]'::jsonb, 3, '“volunteer” (/ˌvɑːlənˈtɪr/): tình nguyện viên; người làm công tác thiện nguyện. Câu đầy đủ: Universities can encourage students to volunteer in their communities by offering flexible schedules and practical support.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
