INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_8_1', 'en-b1-8', NULL, 'comprehensive_test', 'listening', 'issue', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["giải đấu thể thao","cung cấp; cung ứng","vấn đề, đề tài (vấn đề quan trọng cần được thảo luận)","tòa án; pháp đình"]'::jsonb, 2, 'issue (/ˈɪʃuː/) → vấn đề, đề tài (vấn đề quan trọng cần được thảo luận); phát hành, cấp phát (công bố chính thức hoặc cung cấp cái gì cho mọi người); số báo, ấn bản (một số của báo hoặc tạp chí được phát hành định kỳ)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_8_2', 'en-b1-8', NULL, 'comprehensive_test', 'listening', 'A volunteer helped us carry the boxes upstairs.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mức giá này dường như không có sự liên quan nào đến chất lượng.","Nhược điểm chính của căn hộ này là tiếng ồn lớn.","Một tình nguyện viên đã giúp chúng tôi khuân các thùng hàng lên lầu.","Cho chó ăn là trách nhiệm của bạn vào cuối tuần này."]'::jsonb, 2, 'A volunteer helped us carry the boxes upstairs. → Một tình nguyện viên đã giúp chúng tôi khuân các thùng hàng lên lầu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_8_3', 'en-b1-8', NULL, 'comprehensive_test', 'listening', 'sister-in-law', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tòa án; pháp đình","mô hình; quy luật","chị dâu; em dâu; chị chồng; em chồng; chị vợ; em vợ","mối liên hệ; sự liên quan"]'::jsonb, 2, 'sister-in-law (/ˈsɪstər ɪn lɔː/) → chị dâu; em dâu; chị chồng; em chồng; chị vợ; em vợ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_8_4', 'en-b1-8', NULL, 'comprehensive_test', 'listening', 'The pool has a lift for disabled swimmers.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một lợi ích của việc đạp xe là về đến nhà với tinh thần sảng khoái.","Nền tảng kinh nghiệm điều dưỡng đã giúp cô ấy chăm sóc ông nội.","Hồ bơi có lắp đặt thang máy dành cho người bơi khuyết tật.","Nhà tù cũ giờ đây chào đón du khách đến tham quan như một bảo tàng."]'::jsonb, 2, 'The pool has a lift for disabled swimmers. → Hồ bơi có lắp đặt thang máy dành cho người bơi khuyết tật.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_8_5', 'en-b1-8', NULL, 'comprehensive_test', 'listening', 'hero', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["anh hùng (người được ngưỡng mộ vì lòng dũng cảm, thành tựu hoặc hành động cao đẹp)","khả năng","manh mối; gợi ý","thuộc chuyên môn; chuyên nghiệp"]'::jsonb, 0, 'hero (/ˈhɪroʊ/) → anh hùng (người được ngưỡng mộ vì lòng dũng cảm, thành tựu hoặc hành động cao đẹp); nhân vật nam chính (trong một câu chuyện)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_8_6', 'en-b1-8', NULL, 'comprehensive_test', 'listening', 'Feeding the dog is your responsibility this weekend.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một tình nguyện viên đã giúp chúng tôi khuân các thùng hàng lên lầu.","Những người hàng xóm của chúng tôi đối xử với chú chó cứu hộ của họ vô cùng tử tế.","Nền tảng kinh nghiệm điều dưỡng đã giúp cô ấy chăm sóc ông nội.","Cho chó ăn là trách nhiệm của bạn vào cuối tuần này."]'::jsonb, 3, 'Feeding the dog is your responsibility this weekend. → Cho chó ăn là trách nhiệm của bạn vào cuối tuần này.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
