INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_8_18', 'en-b1-8', NULL, 'comprehensive_test', 'reading', NULL, 'Governments must address the issue of housing affordability to ensure that young adults can live independently.', 'Dựa vào câu trên, từ “issue” có nghĩa phù hợp nhất là gì?', '["vấn đề, đề tài (vấn đề quan trọng cần được thảo luận)","tấn công; chỉ trích gay gắt","quốc lộ; đường cao tốc chính","tiếng báo động; thiết bị báo động; đồng hồ báo thức"]'::jsonb, 0, 'issue: vấn đề, đề tài (vấn đề quan trọng cần được thảo luận); phát hành, cấp phát (công bố chính thức hoặc cung cấp cái gì cho mọi người); số báo, ấn bản (một số của báo hoặc tạp chí được phát hành định kỳ). Dịch cả câu: Chính phủ phải giải quyết vấn đề khả năng chi trả nhà ở để đảm bảo rằng người trẻ tuổi có thể sống tự lập.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_8_19', 'en-b1-8', NULL, 'comprehensive_test', 'reading', NULL, 'Universities can encourage students to volunteer in their communities by offering flexible schedules and practical support.', 'Dựa vào câu trên, từ “volunteer” có nghĩa phù hợp nhất là gì?', '["tình nguyện viên; người làm công tác thiện nguyện","bất lợi; điểm bất lợi; điểm yếu","thứ một trăm","một tá; mười hai"]'::jsonb, 0, 'volunteer: tình nguyện viên; người làm công tác thiện nguyện; tình nguyện; xung phong. Dịch cả câu: Các trường đại học có thể khuyến khích sinh viên tham gia công tác tình nguyện tại cộng đồng bằng cách cung cấp lịch trình linh hoạt và hỗ trợ thiết thực.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_8_20', 'en-b1-8', NULL, 'comprehensive_test', 'reading', NULL, 'Sharing childcare with a sister-in-law can help working parents balance professional responsibilities and family life.', 'Dựa vào câu trên, từ “sister-in-law” có nghĩa phù hợp nhất là gì?', '["chị dâu; em dâu; chị chồng; em chồng; chị vợ; em vợ","khu cắm trại","buổi tụ họp; buổi liên hoan","chung; phổ biến; toàn thể"]'::jsonb, 0, 'sister-in-law: chị dâu; em dâu; chị chồng; em chồng; chị vợ; em vợ. Dịch cả câu: Việc cùng chia sẻ việc chăm sóc con cái với chị dâu có thể giúp các bậc phụ huynh đi làm cân bằng tốt hơn giữa trách nhiệm nghề nghiệp và đời sống gia đình.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_8_21', 'en-b1-8', NULL, 'comprehensive_test', 'reading', NULL, 'Universities should provide accessible facilities and appropriate support to ensure that disabled students can participate fully in campus life.', 'Dựa vào câu trên, từ “disabled” có nghĩa phù hợp nhất là gì?', '["bắn; nã đạn","làm cho phấn khích; làm cho hào hứng","khuyết tật; tàn tật","kính viễn vọng"]'::jsonb, 2, 'disabled: khuyết tật; tàn tật. Dịch cả câu: Các trường đại học nên cung cấp các cơ sở vật chất dễ tiếp cận và sự hỗ trợ phù hợp để đảm bảo sinh viên khuyết tật có thể tham gia đầy đủ vào đời sống học đường.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_8_22', 'en-b1-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mối quan hệ; sự liên quan”', '["surround","mention","relation","arts"]'::jsonb, 2, 'mối quan hệ; sự liên quan → relation (/rɪˈleɪʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_8_23', 'en-b1-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vị hôn phu; chồng chưa cưới”', '["embarrass","millimetre","fiance","specially"]'::jsonb, 2, 'vị hôn phu; chồng chưa cưới → fiance (/ˌfiːɑːnˈseɪ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_8_24', 'en-b1-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự phản đối mạnh mẽ; cuộc biểu tình, cuộc kháng nghị”', '["spill","intention","protest","feature"]'::jsonb, 2, 'sự phản đối mạnh mẽ; cuộc biểu tình, cuộc kháng nghị → protest (/ˈproʊtest/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-9', 'en', 'Bài 9: Xã hội & Cộng đồng (2) - CEFR B1', 'CEFR B1', 'B1 · Xã hội', '26 từ vựng Tiếng Anh CEFR B1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3009, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prisoner', 'en-b1-9', 'prisoner', '/ˈprɪzənər/', 'B1', 'tù nhân; người bị giam giữ, người bị cầm tù; tù binh; người bị kẻ địch bắt giữ trong thời chiến', 'n.', 'prison (n.), imprison (v.), imprisonment (n.)', 'Đồng nghĩa: captive, inmate', 'prisoner không nhất thiết phải là người đã kết án, mà còn chỉ người bị bắt giữ hoặc giam cầm.', 'The prisoner borrowed a novel from the prison library.', NULL, 'Tù nhân đó đã mượn một cuốn tiểu thuyết từ thư viện nhà tù.', '{"wordId":"prisoner","ukIpa":"/ˈprɪzənə/","usIpa":"/ˈprɪzənər/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A person kept in prison or prevented from leaving.","vi":"tù nhân; người bị giam giữ, người bị cầm tù"},{"pos":"n.","en":"A person captured and held by an enemy during war.","vi":"tù binh; người bị kẻ địch bắt giữ trong thời chiến"}],"examples":[{"en":"The prisoner borrowed a novel from the prison library.","vi":"Tù nhân đó đã mượn một cuốn tiểu thuyết từ thư viện nhà tù.","audioKind":"ex"},{"en":"Providing prisoners with education and vocational training may improve their chances of finding employment after release.","vi":"Việc cung cấp giáo dục và đào tạo nghề cho tù nhân có thể cải thiện cơ hội tìm việc làm sau khi họ ra tù.","audioKind":"ex2"}],"collocations":[{"en":"release a prisoner","vi":"trả tự do cho tù nhân"},{"en":"prisoner of war","vi":"tù binh chiến tranh"},{"en":"take someone prisoner","vi":"bắt ai làm tù binh"}],"wordFamily":["prison (n.)","imprison (v.)","imprisonment (n.)"],"synonyms":["captive","inmate"],"antonyms":[],"tipVi":"prisoner không nhất thiết phải là người đã kết án, mà còn chỉ người bị bắt giữ hoặc giam cầm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_apologize', 'en-b1-9', 'apologize', '/əˈpɑːlədʒaɪz/', 'B1', 'xin lỗi; nhận lỗi', 'v.', 'apology (n.), apologetic (adj.), apologetically (adv.)', 'Đồng nghĩa: say sorry', 'Khi xin lỗi một người dùng giới từ to, khi xin lỗi về một việc gì dùng giới từ for; trong tiếng Anh - Anh cũng có thể viết là apologise.', 'I apologized to my neighbour for the noise.', NULL, 'Tôi đã sang xin lỗi người hàng xóm vì tiếng ồn.', '{"wordId":"apologize","ukIpa":"/əˈpɒlədʒaɪz/","usIpa":"/əˈpɑːlədʒaɪz/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"To tell someone you are sorry for doing something wrong","vi":"xin lỗi; nhận lỗi"}],"examples":[{"en":"I apologized to my neighbour for the noise.","vi":"Tôi đã sang xin lỗi người hàng xóm vì tiếng ồn.","audioKind":"ex"},{"en":"Companies should apologize promptly for service failures and explain what steps they will take to prevent further problems.","vi":"Các công ty nên chủ động xin lỗi kịp thời khi xảy ra sự cố dịch vụ và giải thích rõ các bước họ sẽ thực hiện để ngăn chặn những vấn đề tương tự.","audioKind":"ex2"}],"collocations":[{"en":"apologize to someone","vi":"xin lỗi ai đó"},{"en":"apologize for doing something","vi":"xin lỗi vì đã làm điều gì"},{"en":"apologize sincerely","vi":"chân thành xin lỗi"}],"wordFamily":["apology (n.)","apologetic (adj.)","apologetically (adv.)"],"synonyms":["say sorry"],"antonyms":[],"tipVi":"Khi xin lỗi một người dùng giới từ to, khi xin lỗi về một việc gì dùng giới từ for; trong tiếng Anh - Anh cũng có thể viết là apologise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_foreigner', 'en-b1-9', 'foreigner', '/ˈfɔːrənər/', 'B1', 'người nước ngoài', 'n.', 'foreign (adj.)', NULL, 'Dùng foreigner để chỉ chung người mang quốc tịch khác; nếu muốn nhấn mạnh khách du lịch thì dùng visitor sẽ tự nhiên hơn.', 'As a foreigner, I needed help understanding local customs.', NULL, 'Là một người nước ngoài, tôi cần sự giúp đỡ để hiểu các phong tục tập quán địa phương.', '{"wordId":"foreigner","ukIpa":"/ˈfɒrənə/","usIpa":"/ˈfɔːrənər/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A person from a country other than the one being discussed.","vi":"người nước ngoài"}],"examples":[{"en":"As a foreigner, I needed help understanding local customs.","vi":"Là một người nước ngoài, tôi cần sự giúp đỡ để hiểu các phong tục tập quán địa phương.","audioKind":"ex"},{"en":"Language courses can help foreigners participate more fully in community life and access essential public services.","vi":"Các khóa học ngoại ngữ có thể giúp người nước ngoài hòa nhập tốt hơn vào đời sống cộng đồng và tiếp cận các dịch vụ công thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"as a foreigner","vi":"với tư cách là người nước ngoài"},{"en":"foreigners living abroad","vi":"người nước ngoài sinh sống ở nước ngoài"},{"en":"welcome foreigners","vi":"chào đón người nước ngoài"}],"wordFamily":["foreign (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng foreigner để chỉ chung người mang quốc tịch khác; nếu muốn nhấn mạnh khách du lịch thì dùng visitor sẽ tự nhiên hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_engaged', 'en-b1-9', 'engaged', '/ɪnˈɡeɪdʒd/', 'B1', 'đã đính hôn; bận rộn; tham gia vào; đang bận (đường dây điện thoại); đang được sử dụng', 'adj.', 'engage (v.), engagement (n.), engaging (adj.)', NULL, 'Khi nói về đối tượng đính hôn dùng giới từ to; khi nói về việc tham gia hoạt động dùng giới từ in.', 'My sister got engaged during her holiday by the sea.', NULL, 'Chị tôi đã đính hôn trong chuyến nghỉ mát bên bờ biển.', '{"wordId":"engaged","ukIpa":"/ɪnˈɡeɪdʒd/","usIpa":"/ɪnˈɡeɪdʒd/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"Having formally agreed to marry someone.","vi":"đã đính hôn"},{"pos":"adj.","en":"Actively involved in an activity or task.","vi":"bận rộn; tham gia vào"},{"pos":"adj.","en":"Currently being used and therefore unavailable.","vi":"đang bận (đường dây điện thoại); đang được sử dụng"}],"examples":[{"en":"My sister got engaged during her holiday by the sea.","vi":"Chị tôi đã đính hôn trong chuyến nghỉ mát bên bờ biển.","audioKind":"ex"},{"en":"Students who are actively engaged in classroom discussions often develop stronger communication and critical thinking skills.","vi":"Những học sinh tích cực tham gia vào các cuộc thảo luận trên lớp thường phát triển tốt hơn các kỹ năng giao tiếp và tư duy phản biện.","audioKind":"ex2"}],"collocations":[{"en":"get engaged","vi":"đính hôn"},{"en":"engaged to someone","vi":"đính hôn với ai"},{"en":"engaged in research","vi":"tham gia nghiên cứu"},{"en":"the line is engaged","vi":"đường dây điện thoại đang bận"}],"wordFamily":["engage (v.)","engagement (n.)","engaging (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói về đối tượng đính hôn dùng giới từ to; khi nói về việc tham gia hoạt động dùng giới từ in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fool', 'en-b1-9', 'fool', '/fuːl/', 'B1', 'kẻ ngốc; người hành động thiếu khôn ngoan; lừa gạt; đánh lừa', 'n.', 'foolish (adj.), foolishly (adv.), foolishness (n.)', NULL, 'Từ fool dùng làm danh từ gọi người khác mang sắc thái chê bai; động từ có thể đi với cấu trúc into doing.', 'The realistic plastic spider fooled everyone at the party.', NULL, 'Con nhện nhựa trông như thật đã lừa được tất cả mọi người trong bữa tiệc.', '{"wordId":"fool","ukIpa":"/fuːl/","usIpa":"/fuːl/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"someone who behaves without good sense or judgment","vi":"kẻ ngốc; người hành động thiếu khôn ngoan"},{"pos":"v.","en":"to make someone believe something that is not true","vi":"lừa gạt; đánh lừa"}],"examples":[{"en":"The realistic plastic spider fooled everyone at the party.","vi":"Con nhện nhựa trông như thật đã lừa được tất cả mọi người trong bữa tiệc.","audioKind":"ex"},{"en":"Misleading advertisements can fool consumers into buying products that offer little practical benefit.","vi":"Các quảng cáo gây hiểu lầm có thể lừa người tiêu dùng mua những sản phẩm có ít giá trị thực tiễn.","audioKind":"ex2"}],"collocations":[{"en":"fool someone into doing something","vi":"lừa ai đó làm việc gì"},{"en":"make a fool of yourself","vi":"làm trò hề cho thiên hạ; tự chuốc lấy sự lố bịch"},{"en":"fool around","vi":"làm trò đùa; la cà đùa giỡn"}],"wordFamily":["foolish (adj.)","foolishly (adv.)","foolishness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ fool dùng làm danh từ gọi người khác mang sắc thái chê bai; động từ có thể đi với cấu trúc into doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bible', 'en-b1-9', 'Bible', '/ˈbaɪbəl/', 'B1', 'kinh Thánh', 'n.', 'biblical (adj.)', 'Đồng nghĩa: Scripture', 'Khi chỉ kinh Thánh thì viết hoa chữ cái đầu, thường đi kèm mạo từ the Bible.', 'She keeps a Bible on the shelf beside her bed.', NULL, 'Cô ấy đặt một cuốn kinh Thánh trên kệ sách cạnh giường.', '{"wordId":"bible","ukIpa":"/ˈbaɪbəl/","usIpa":"/ˈbaɪbəl/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the collection of sacred writings used in Christianity","vi":"kinh Thánh"}],"examples":[{"en":"She keeps a Bible on the shelf beside her bed.","vi":"Cô ấy đặt một cuốn kinh Thánh trên kệ sách cạnh giường.","audioKind":"ex"},{"en":"Studying the Bible can help students understand religious references in European literature and visual art.","vi":"Việc nghiên cứu kinh Thánh có thể giúp học sinh hiểu các điển tích tôn giáo trong văn học và nghệ thuật thị giác châu Âu.","audioKind":"ex2"}],"collocations":[{"en":"read the Bible","vi":"đọc kinh Thánh"},{"en":"a Bible translation","vi":"bản dịch kinh Thánh"},{"en":"Bible study","vi":"nghiên cứu kinh Thánh"}],"wordFamily":["biblical (adj.)"],"synonyms":["Scripture"],"antonyms":[],"tipVi":"Khi chỉ kinh Thánh thì viết hoa chữ cái đầu, thường đi kèm mạo từ the Bible.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weapon', 'en-b1-9', 'weapon', '/ˈwepən/', 'B1', 'vũ khí; binh khí', 'n.', 'weaponry (n.)', NULL, 'Danh từ đếm được; thuật ngữ chung chỉ vũ khí cũng có thể dùng weaponry.', 'The museum displays an ancient weapon behind thick glass.', NULL, 'Bảo tàng trưng bày một thứ vũ khí cổ đằng sau lớp kính dày.', '{"wordId":"weapon","ukIpa":"/ˈwepən/","usIpa":"/ˈwepən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"an object used for fighting or causing physical harm","vi":"vũ khí; binh khí"}],"examples":[{"en":"The museum displays an ancient weapon behind thick glass.","vi":"Bảo tàng trưng bày một thứ vũ khí cổ đằng sau lớp kính dày.","audioKind":"ex"},{"en":"Stricter controls on weapon sales may help governments improve public safety and reduce violent crime.","vi":"Việc kiểm soát chặt chẽ hơn việc buôn bán vũ khí có thể giúp các chính phủ nâng cao an toàn công cộng và giảm thiểu tội phạm bạo lực.","audioKind":"ex2"}],"collocations":[{"en":"nuclear weapon","vi":"vũ khí hạt nhân"},{"en":"carry a weapon","vi":"mang theo vũ khí"},{"en":"weapon sales","vi":"buôn bán vũ khí"}],"wordFamily":["weaponry (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được; thuật ngữ chung chỉ vũ khí cũng có thể dùng weaponry.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lover', 'en-b1-9', 'lover', '/ˈlʌvər/', 'B1', 'người yêu; tình nhân; người có sở thích; người say mê', 'n.', 'love (n.), love (v.), loving (adj.), lovable (adj.)', NULL, 'Để chỉ người thích gì đó, thường dùng danh từ ghép với lover; dùng đơn lẻ có thể ám chỉ người tình.', 'The two lovers walked hand in hand beside the river.', NULL, 'Đôi uyên ương dạo bước tay trong tay bên bờ sông.', '{"wordId":"lover","ukIpa":"/ˈlʌvə/","usIpa":"/ˈlʌvər/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"Someone in a romantic or sexual relationship with another person.","vi":"người yêu; tình nhân"},{"pos":"n.","en":"Someone who enjoys or admires something very much.","vi":"người có sở thích; người say mê"}],"examples":[{"en":"The two lovers walked hand in hand beside the river.","vi":"Đôi uyên ương dạo bước tay trong tay bên bờ sông.","audioKind":"ex"},{"en":"Public gardens offer nature lovers valuable opportunities to observe wildlife without leaving the city.","vi":"Các khu vườn công cộng mang lại cho những người yêu thiên nhiên cơ hội quý giá để quan sát động vật hoang dã mà không cần rời khỏi thành phố.","audioKind":"ex2"}],"collocations":[{"en":"young lovers","vi":"đôi trẻ yêu nhau"},{"en":"a music lover","vi":"người yêu âm nhạc"},{"en":"a nature lover","vi":"người yêu thiên nhiên"}],"wordFamily":["love (n.)","love (v.)","loving (adj.)","lovable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Để chỉ người thích gì đó, thường dùng danh từ ghép với lover; dùng đơn lẻ có thể ám chỉ người tình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aged', 'en-b1-9', 'aged', '/eɪdʒd/', 'B1', '... tuổi; lớn tuổi; cao tuổi; già', 'adj.', 'age (n.), age (v.), ageing (n.), ageless (adj.)', NULL, 'Khi chỉ độ tuổi thì đọc là /eɪdʒd/; khi chỉ sự cao tuổi thì đọc là /ˈeɪdʒɪd/.', 'The swimming class welcomes children aged six and above.', NULL, 'Lớp học bơi chào đón trẻ em từ sáu tuổi trở lên.', '{"wordId":"aged","ukIpa":"/eɪdʒd/","usIpa":"/eɪdʒd/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"Having reached a particular age.","vi":"... tuổi"},{"pos":"adj.","en":"Very old, especially when describing people.","vi":"lớn tuổi; cao tuổi; già"}],"examples":[{"en":"The swimming class welcomes children aged six and above.","vi":"Lớp học bơi chào đón trẻ em từ sáu tuổi trở lên.","audioKind":"ex"},{"en":"Public libraries can support children aged five to twelve by providing free reading activities during school holidays.","vi":"Các thư viện công cộng có thể hỗ trợ trẻ em từ năm đến mười hai tuổi bằng cách cung cấp các hoạt động đọc sách miễn phí trong kỳ nghỉ học.","audioKind":"ex2"}],"collocations":[{"en":"children aged five","vi":"trẻ em năm tuổi"},{"en":"aged eighteen and over","vi":"từ mười tám tuổi trở lên"},{"en":"aged relatives","vi":"những người họ hàng cao tuổi"}],"wordFamily":["age (n.)","age (v.)","ageing (n.)","ageless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ độ tuổi thì đọc là /eɪdʒd/; khi chỉ sự cao tuổi thì đọc là /ˈeɪdʒɪd/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_current', 'en-b1-9', 'current', '/ˈkɝːənt/', 'B1', 'đang diễn ra, đang tồn tại hoặc đang được sử dụng ở hiện tại; hiện tại; hiện hành; dòng chuyển động liên tục của nước, không khí hoặc điện; dòng chảy; dòng điện', 'adj.', 'currently (adv.)', 'Đồng nghĩa: present, existing · Trái nghĩa: past, future', 'Tính từ chỉ tính thời sự hiện tại; danh từ có thể chỉ dòng nước hoặc dòng điện.', 'My current flat is much closer to work.', NULL, 'Căn hộ hiện tại của tôi gần chỗ làm hơn nhiều.', '{"wordId":"current","ukIpa":"/ˈkʌrənt/","usIpa":"/ˈkɝːənt/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"happening, existing, or being used now","vi":"đang diễn ra, đang tồn tại hoặc đang được sử dụng ở hiện tại; hiện tại; hiện hành"},{"pos":"n.","en":"a continuous movement of water, air, or electricity","vi":"dòng chuyển động liên tục của nước, không khí hoặc điện; dòng chảy; dòng điện"}],"examples":[{"en":"My current flat is much closer to work.","vi":"Căn hộ hiện tại của tôi gần chỗ làm hơn nhiều.","audioKind":"ex"},{"en":"Current policies may need revision as cities face increasing pressure on housing and transport.","vi":"Các chính sách hiện hành có thể cần được sửa đổi khi các đô thị phải đối mặt với áp lực ngày càng tăng về nhà ở và giao thông.","audioKind":"ex2"}],"collocations":[{"en":"the current situation","vi":"tình hình hiện tại"},{"en":"current affairs","vi":"thời sự"},{"en":"a strong current","vi":"dòng nước xiết"},{"en":"electric current","vi":"dòng điện"}],"wordFamily":["currently (adv.)"],"synonyms":["present","existing"],"antonyms":["past","future"],"tipVi":"Tính từ chỉ tính thời sự hiện tại; danh từ có thể chỉ dòng nước hoặc dòng điện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_community', 'en-b1-9', 'community', '/kəˈmjuːnəti/', 'B1', 'cộng đồng; người dân địa phương; hội nhóm', 'n.', 'communal (adj.)', NULL, 'Từ này vừa dùng để chỉ cư dân trong một khu vực, vừa chỉ những người có chung sở thích hoặc hoàn cảnh.', 'Our community gathers every spring to clean the park.', NULL, 'Cộng đồng chúng tôi tụ họp vào mỗi mùa xuân để dọn dẹp công viên.', '{"wordId":"community","ukIpa":"/kəˈmjuːnəti/","usIpa":"/kəˈmjuːnəti/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"people living in the same area","vi":"cộng đồng; người dân địa phương"},{"pos":"n.","en":"people sharing interests, beliefs, or a particular background","vi":"cộng đồng; hội nhóm"}],"examples":[{"en":"Our community gathers every spring to clean the park.","vi":"Cộng đồng chúng tôi tụ họp vào mỗi mùa xuân để dọn dẹp công viên.","audioKind":"ex"},{"en":"Public libraries strengthen the local community by providing free learning spaces and opportunities for social interaction.","vi":"Các thư viện công cộng thắt chặt sự gắn kết của cộng đồng địa phương bằng cách cung cấp không gian học tập miễn phí và cơ hội giao lưu xã hội.","audioKind":"ex2"}],"collocations":[{"en":"local community","vi":"cộng đồng địa phương"},{"en":"community centre","vi":"trung tâm sinh hoạt cộng đồng"},{"en":"scientific community","vi":"giới khoa học"},{"en":"sense of community","vi":"ý thức cộng đồng"}],"wordFamily":["communal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ này vừa dùng để chỉ cư dân trong một khu vực, vừa chỉ những người có chung sở thích hoặc hoàn cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strict', 'en-b1-9', 'strict', '/strɪkt/', 'B1', 'nghiêm khắc; khắt khe; nghiêm ngặt; chính xác', 'adj.', 'strictly (adv.), strictness (n.)', 'Đồng nghĩa: rigorous, stringent · Trái nghĩa: lenient, lax', 'Dùng strict with khi khắt khe với con người; dùng strict about khi yêu cầu nghiêm ngặt đối với một việc cụ thể.', 'Our coach is strict about arriving on time.', NULL, 'Huấn luyện viên của chúng tôi rất nghiêm khắc về việc có mặt đúng giờ.', '{"wordId":"strict","ukIpa":"/strɪkt/","usIpa":"/strɪkt/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"requiring rules to be obeyed and standards to be met","vi":"nghiêm khắc; khắt khe"},{"pos":"adj.","en":"following an exact meaning or limit without exceptions","vi":"nghiêm ngặt; chính xác"}],"examples":[{"en":"Our coach is strict about arriving on time.","vi":"Huấn luyện viên của chúng tôi rất nghiêm khắc về việc có mặt đúng giờ.","audioKind":"ex"},{"en":"Strict environmental regulations can encourage manufacturers to adopt cleaner technologies and reduce harmful industrial emissions.","vi":"Các quy định môi trường nghiêm ngặt có thể khuyến khích các nhà sản xuất áp dụng công nghệ sạch hơn và cắt giảm lượng khí thải công nghiệp độc hại.","audioKind":"ex2"}],"collocations":[{"en":"strict rules","vi":"quy định nghiêm ngặt"},{"en":"strict about punctuality","vi":"khắt khe về việc đúng giờ"},{"en":"strict with children","vi":"nghiêm khắc với trẻ nhỏ"},{"en":"in the strict sense","vi":"theo nghĩa đen"}],"wordFamily":["strictly (adv.)","strictness (n.)"],"synonyms":["rigorous","stringent"],"antonyms":["lenient","lax"],"tipVi":"Dùng strict with khi khắt khe với con người; dùng strict about khi yêu cầu nghiêm ngặt đối với một việc cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_truth', 'en-b1-9', 'truth', '/truːθ/', 'B1', 'sự thật; chân lý; lẽ phải; chân lý được công nhận chung', 'n.', 'true (adj.), truly (adv.), truthful (adj.), truthfully (adv.)', 'Trái nghĩa: falsehood', 'Nói sự thật dùng tell the truth, thường không được lược bỏ mạo từ the.', 'Please tell me the truth about the broken cup.', NULL, 'Làm ơn hãy nói cho tôi sự thật về chiếc cốc bị vỡ.', '{"wordId":"truth","ukIpa":"/truːθ/","usIpa":"/truːθ/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"what is real or actually happened","vi":"sự thật; chân lý"},{"pos":"n.","en":"a fact or principle generally accepted as true","vi":"lẽ phải; chân lý được công nhận chung"}],"examples":[{"en":"Please tell me the truth about the broken cup.","vi":"Làm ơn hãy nói cho tôi sự thật về chiếc cốc bị vỡ.","audioKind":"ex"},{"en":"Journalists should seek the truth rather than publish stories that simply attract public attention.","vi":"Các nhà báo nên tìm kiếm sự thật thay vì đăng tải những câu chuyện chỉ để thu hút sự chú ý của công chúng.","audioKind":"ex2"}],"collocations":[{"en":"tell the truth","vi":"nói sự thật"},{"en":"discover the truth","vi":"khám phá sự thật"},{"en":"the truth about something","vi":"sự thật về điều gì đó"}],"wordFamily":["true (adj.)","truly (adv.)","truthful (adj.)","truthfully (adv.)"],"synonyms":[],"antonyms":["falsehood"],"tipVi":"Nói sự thật dùng tell the truth, thường không được lược bỏ mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trend', 'en-b1-9', 'trend', '/trend/', 'B1', 'xu hướng; trào lưu; trở thành chủ đề thịnh hành trên mạng', 'n.', 'trendy (adj.)', 'Đồng nghĩa: tendency', 'Để chỉ xu hướng hướng tới một cái gì đó, thường dùng cụm a trend towards theo sau là một danh từ.', 'Growing vegetables at home is a popular trend here.', NULL, 'Trồng rau tại nhà đang là một trào lưu phổ biến ở đây.', '{"wordId":"trend","ukIpa":"/trend/","usIpa":"/trend/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"a general direction of change or development","vi":"xu hướng; trào lưu"},{"pos":"v.","en":"to become widely discussed or shared online","vi":"trở thành chủ đề thịnh hành trên mạng"}],"examples":[{"en":"Growing vegetables at home is a popular trend here.","vi":"Trồng rau tại nhà đang là một trào lưu phổ biến ở đây.","audioKind":"ex"},{"en":"The growing trend towards remote working may reduce traffic congestion in major cities.","vi":"Xu hướng ngày càng gia tăng đối với việc làm việc từ xa có thể giúp giảm thiểu tình trạng ùn tắc giao thông ở các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"an upward trend","vi":"xu hướng đi lên"},{"en":"a growing trend","vi":"xu hướng ngày càng phát triển"},{"en":"follow a trend","vi":"chạy theo xu hướng"},{"en":"a trend towards","vi":"xu hướng hướng tới..."}],"wordFamily":["trendy (adj.)"],"synonyms":["tendency"],"antonyms":[],"tipVi":"Để chỉ xu hướng hướng tới một cái gì đó, thường dùng cụm a trend towards theo sau là một danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_persuading', 'en-b1-9', 'persuading', '/pərˈsweɪdɪŋ/', 'B1', 'thuyết phục; khuyên nhủ', 'v.', 'persuade (v.), persuasion (n.), persuasive (adj.), persuasively (adv.)', 'Đồng nghĩa: convincing · Trái nghĩa: dissuading', 'persuade của dạng -ing; khuyên ai làm gì dùng to do.', 'She is persuading her brother to try vegetable soup.', NULL, 'Cô ấy đang thuyết phục anh trai thử món súp rau củ.', '{"wordId":"persuading","ukIpa":"/pəˈsweɪdɪŋ/","usIpa":"/pərˈsweɪdɪŋ/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"getting someone to act or believe something by giving reasons","vi":"thuyết phục; khuyên nhủ"}],"examples":[{"en":"She is persuading her brother to try vegetable soup.","vi":"Cô ấy đang thuyết phục anh trai thử món súp rau củ.","audioKind":"ex"},{"en":"Persuading commuters to use public transport requires reliable services as well as affordable fares and convenient routes.","vi":"Việc thuyết phục người đi làm sử dụng phương tiện công cộng đòi hỏi các dịch vụ đáng tin cậy cùng với giá vé phải chăng và các tuyến đường thuận tiện.","audioKind":"ex2"}],"collocations":[{"en":"persuading someone to act","vi":"thuyết phục ai đó hành động"},{"en":"persuading someone of the benefits","vi":"thuyết phục ai đó về những lợi ích"},{"en":"persuading someone that","vi":"thuyết phục ai đó rằng"}],"wordFamily":["persuade (v.)","persuasion (n.)","persuasive (adj.)","persuasively (adv.)"],"synonyms":["convincing"],"antonyms":["dissuading"],"tipVi":"persuade của dạng -ing; khuyên ai làm gì dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_admit', 'en-b1-9', 'admit', '/ədˈmɪt/', 'B1', 'thừa nhận; cho phép vào; tiếp nhận', 'v.', 'admission (n.), admittedly (adv.), admittance (n.)', 'Đồng nghĩa: acknowledge, confess · Trái nghĩa: deny', 'Dùng admit doing, không dùng admit to do; dạng quá khứ gấp đôi chữ t.', 'I admit that I forgot to water your plants.', NULL, 'Tôi thừa nhận rằng tôi đã quên tưới cây cho bạn.', '{"wordId":"admit","ukIpa":"/ədˈmɪt/","usIpa":"/ədˈmɪt/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"to accept that something is true, often reluctantly","vi":"thừa nhận"},{"pos":"v.","en":"to allow someone to enter or join a place or institution","vi":"cho phép vào; tiếp nhận"}],"examples":[{"en":"I admit that I forgot to water your plants.","vi":"Tôi thừa nhận rằng tôi đã quên tưới cây cho bạn.","audioKind":"ex"},{"en":"Governments should admit when policies have failed and use reliable evidence to develop more effective alternatives.","vi":"Chính phủ nên thừa nhận khi các chính sách thất bại và sử dụng các bằng chứng đáng tin cậy để phát triển những giải pháp thay thế hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"admit a mistake","vi":"thừa nhận sai lầm"},{"en":"admit doing something","vi":"thừa nhận đã làm gì"},{"en":"admit that","vi":"thừa nhận rằng"},{"en":"be admitted to hospital","vi":"được nhập viện"}],"wordFamily":["admission (n.)","admittedly (adv.)","admittance (n.)"],"synonyms":["acknowledge","confess"],"antonyms":["deny"],"tipVi":"Dùng admit doing, không dùng admit to do; dạng quá khứ gấp đôi chữ t.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_communicate', 'en-b1-9', 'communicate', '/kəˈmjuːnɪkeɪt/', 'B1', 'giao tiếp; liên lạc; truyền đạt; bày tỏ', 'v.', 'communication (n.), communicative (adj.), communicator (n.)', 'Đồng nghĩa: convey', 'Giao tiếp với ai dùng với with; truyền đạt điều gì cho ai dùng sth to sb.', 'We communicate with our neighbours through a shared online group.', NULL, 'Chúng tôi giao tiếp với những người hàng xóm thông qua một nhóm trực tuyến chung.', '{"wordId":"communicate","ukIpa":"/kəˈmjuːnɪkeɪt/","usIpa":"/kəˈmjuːnɪkeɪt/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"to share information, thoughts, or feelings with others","vi":"giao tiếp; liên lạc"},{"pos":"v.","en":"to make information or feelings known to someone","vi":"truyền đạt; bày tỏ"}],"examples":[{"en":"We communicate with our neighbours through a shared online group.","vi":"Chúng tôi giao tiếp với những người hàng xóm thông qua một nhóm trực tuyến chung.","audioKind":"ex"},{"en":"Teachers need to communicate complex ideas clearly so that students with different abilities can understand them.","vi":"Giáo viên cần truyền đạt các khái niệm phức tạp một cách rõ ràng để học sinh có năng lực khác nhau đều có thể hiểu được.","audioKind":"ex2"}],"collocations":[{"en":"communicate with","vi":"giao tiếp với"},{"en":"communicate effectively","vi":"giao tiếp hiệu quả"},{"en":"communicate ideas","vi":"truyền đạt ý tưởng"}],"wordFamily":["communication (n.)","communicative (adj.)","communicator (n.)"],"synonyms":["convey"],"antonyms":[],"tipVi":"Giao tiếp với ai dùng với with; truyền đạt điều gì cho ai dùng sth to sb.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_society', 'en-b1-9', 'society', '/səˈsaɪəti/', 'B1', 'xã hội; hiệp hội; câu lạc bộ', 'n.', 'social (adj.), socially (adv.), societal (adj.)', NULL, 'Khi chỉ chung chung xã hội thì thường không dùng the; khi chỉ tổ chức, hội nhóm thì đây là danh từ đếm được.', 'Everyone has a part to play in society.', NULL, 'Mỗi người đều có một vai trò cần đóng góp trong xã hội.', '{"wordId":"society","ukIpa":"/səˈsaɪəti/","usIpa":"/səˈsaɪəti/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"People living together in an organised community.","vi":"xã hội"},{"pos":"n.","en":"An organisation for people who share an interest or purpose.","vi":"hiệp hội; câu lạc bộ"}],"examples":[{"en":"Everyone has a part to play in society.","vi":"Mỗi người đều có một vai trò cần đóng góp trong xã hội.","audioKind":"ex"},{"en":"An ageing society requires accessible healthcare and policies that support older people''s independence.","vi":"Một xã hội già hóa đòi hỏi các dịch vụ y tế dễ tiếp cận và các chính sách hỗ trợ tính tự lập của người cao tuổi.","audioKind":"ex2"}],"collocations":[{"en":"modern society","vi":"xã hội hiện đại"},{"en":"an ageing society","vi":"xã hội già hóa"},{"en":"society as a whole","vi":"toàn bộ xã hội"},{"en":"join a society","vi":"gia nhập một hội nhóm"}],"wordFamily":["social (adj.)","socially (adv.)","societal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ chung chung xã hội thì thường không dùng the; khi chỉ tổ chức, hội nhóm thì đây là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_apologise', 'en-b1-9', 'apologise', '/əˈpɑːlədʒaɪz/', 'B1', 'xin lỗi', 'v.', 'apology (n.), apologetic (adj.), apologetically (adv.)', NULL, 'Cách viết theo Anh-Anh; tiếng Anh-Mỹ thường dùng apologize, đi kèm với to (ai) và for (việc gì).', 'I should apologise for spilling juice on your jacket.', NULL, 'Tôi nên xin lỗi vì đã làm đổ nước ép lên áo khoác của bạn.', '{"wordId":"apologise","ukIpa":"/əˈpɒlədʒaɪz/","usIpa":"/əˈpɑːlədʒaɪz/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"To say you are sorry for something you have done.","vi":"xin lỗi"}],"examples":[{"en":"I should apologise for spilling juice on your jacket.","vi":"Tôi nên xin lỗi vì đã làm đổ nước ép lên áo khoác của bạn.","audioKind":"ex"},{"en":"Companies should apologise publicly when their mistakes cause inconvenience or financial loss to customers.","vi":"Các công ty nên công khai xin lỗi khi những sai sót của họ gây ra sự bất tiện hoặc thiệt hại tài chính cho khách hàng.","audioKind":"ex2"}],"collocations":[{"en":"apologise to someone","vi":"xin lỗi ai đó"},{"en":"apologise for something","vi":"xin lỗi vì điều gì"},{"en":"apologise sincerely","vi":"thành tâm xin lỗi"}],"wordFamily":["apology (n.)","apologetic (adj.)","apologetically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết theo Anh-Anh; tiếng Anh-Mỹ thường dùng apologize, đi kèm với to (ai) và for (việc gì).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_informal', 'en-b1-9', 'informal', '/ɪnˈfɔːrməl/', 'B1', 'thân mật; thoải mái; không trang trọng; thuộc văn phong khẩu ngữ; dùng trong giao tiếp hàng ngày; không chính thức; không theo quy định nhà nước', 'adj.', 'informally (adv.), informality (n.), formal (adj.)', 'Đồng nghĩa: casual, relaxed · Trái nghĩa: formal', 'Chỉ sự không câu nệ lễ tiết, không có nghĩa là bất lịch sự hay thiếu chuyên nghiệp.', 'We had an informal chat over tea this morning.', NULL, 'Chúng tôi đã có một buổi trò chuyện thân mật bên ly trà vào sáng nay.', '{"wordId":"informal","ukIpa":"/ɪnˈfɔːməl/","usIpa":"/ɪnˈfɔːrməl/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"Relaxed and friendly rather than following strict social rules.","vi":"thân mật; thoải mái; không trang trọng"},{"pos":"adj.","en":"Suitable for casual communication rather than formal writing or speech.","vi":"thuộc văn phong khẩu ngữ; dùng trong giao tiếp hàng ngày"},{"pos":"adj.","en":"Not officially arranged, recognized, or controlled.","vi":"không chính thức; không theo quy định nhà nước"}],"examples":[{"en":"We had an informal chat over tea this morning.","vi":"Chúng tôi đã có một buổi trò chuyện thân mật bên ly trà vào sáng nay.","audioKind":"ex"},{"en":"Informal learning outside the classroom allows children to develop practical skills through play and everyday experiences.","vi":"Việc học tập không chính thức ngoài lớp học giúp trẻ em phát triển các kỹ năng thực tế thông qua trò chơi và trải nghiệm hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"informal chat","vi":"buổi trò chuyện thân mật"},{"en":"informal language","vi":"ngôn ngữ thông tục"},{"en":"informal learning","vi":"việc học tập không chính thức"}],"wordFamily":["informally (adv.)","informality (n.)","formal (adj.)"],"synonyms":["casual","relaxed"],"antonyms":["formal"],"tipVi":"Chỉ sự không câu nệ lễ tiết, không có nghĩa là bất lịch sự hay thiếu chuyên nghiệp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guilty', 'en-b1-9', 'guilty', '/ˈɡɪlti/', 'B1', 'có tội; phạm tội; cảm thấy tội lỗi; ân hận; áy náy', 'adj.', 'guilt (n.), guiltily (adv.), guiltless (adj.)', 'Đồng nghĩa: remorseful · Trái nghĩa: innocent', 'Dùng "guilty of" khi nói về tội danh; dùng "feel guilty about" khi diễn tả cảm giác ăn năn, tội lỗi về việc gì.', 'I felt guilty about forgetting my sister''s birthday.', NULL, 'Tôi cảm thấy áy náy vì đã quên sinh nhật của chị gái.', '{"wordId":"guilty","ukIpa":"/ˈɡɪlti/","usIpa":"/ˈɡɪlti/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"Responsible for breaking a law or doing something wrong.","vi":"có tội; phạm tội"},{"pos":"adj.","en":"Feeling bad because you believe you have done something wrong.","vi":"cảm thấy tội lỗi; ân hận; áy náy"}],"examples":[{"en":"I felt guilty about forgetting my sister''s birthday.","vi":"Tôi cảm thấy áy náy vì đã quên sinh nhật của chị gái.","audioKind":"ex"},{"en":"Companies found guilty of illegally dumping waste should face penalties that reflect the environmental damage caused.","vi":"Các công ty bị phán quyết là có tội khi xả thải trái phép phải đối mặt với các hình phạt tương xứng với tổn hại môi trường mà họ gây ra.","audioKind":"ex2"}],"collocations":[{"en":"guilty of","vi":"phạm tội gì"},{"en":"find someone guilty","vi":"kết tội ai"},{"en":"plead guilty","vi":"nhận tội"},{"en":"feel guilty about","vi":"cảm thấy áy náy vì"}],"wordFamily":["guilt (n.)","guiltily (adv.)","guiltless (adj.)"],"synonyms":["remorseful"],"antonyms":["innocent"],"tipVi":"Dùng \"guilty of\" khi nói về tội danh; dùng \"feel guilty about\" khi diễn tả cảm giác ăn năn, tội lỗi về việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_honest', 'en-b1-9', 'honest', '/ˈɑːnɪst/', 'B1', 'thành thật; trung thực; thẳng thắn; chân thành', 'adj.', 'honesty (n.), honestly (adv.), dishonest (adj.), dishonesty (n.)', 'Đồng nghĩa: truthful, sincere · Trái nghĩa: dishonest', 'Phụ âm h không phát âm, do đó dùng mạo từ an trước honest person.', 'The honest cashier returned the money I had overpaid.', NULL, 'Người thu ngân trung thực đã trả lại số tiền tôi đưa thừa.', '{"wordId":"honest","ukIpa":"/ˈɒnɪst/","usIpa":"/ˈɑːnɪst/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"Telling the truth and not cheating or stealing.","vi":"thành thật; trung thực"},{"pos":"adj.","en":"Expressing what you really think or feel.","vi":"thẳng thắn; chân thành"}],"examples":[{"en":"The honest cashier returned the money I had overpaid.","vi":"Người thu ngân trung thực đã trả lại số tiền tôi đưa thừa.","audioKind":"ex"},{"en":"Honest communication between teachers and parents can help schools address students'' difficulties before they become serious.","vi":"Giao tiếp thành thật giữa giáo viên và phụ huynh có thể giúp nhà trường giải quyết các khó khăn của học sinh trước khi chúng trở nên nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"an honest person","vi":"một người trung thực"},{"en":"an honest answer","vi":"một câu trả lời thẳng thắn"},{"en":"to be honest","vi":"nói thật lòng"}],"wordFamily":["honesty (n.)","honestly (adv.)","dishonest (adj.)","dishonesty (n.)"],"synonyms":["truthful","sincere"],"antonyms":["dishonest"],"tipVi":"Phụ âm h không phát âm, do đó dùng mạo từ an trước honest person.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_victim', 'en-b1-9', 'victim', '/ˈvɪktɪm/', 'B1', 'nạn nhân', 'n.', 'victimise (v.), victimisation (n.)', NULL, 'Để diễn tả nạn nhân của việc gì, dùng victim of.', 'Neighbours brought warm blankets to the flood victims.', NULL, 'Những người hàng xóm mang chăn ấm đến cho các nạn nhân vụ lũ lụt.', '{"wordId":"victim","ukIpa":"/ˈvɪktɪm/","usIpa":"/ˈvɪktɪm/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"someone harmed by an accident, crime, or unfair treatment","vi":"nạn nhân"}],"examples":[{"en":"Neighbours brought warm blankets to the flood victims.","vi":"Những người hàng xóm mang chăn ấm đến cho các nạn nhân vụ lũ lụt.","audioKind":"ex"},{"en":"Governments should provide practical support for victims of online fraud, including free legal advice.","vi":"Chính phủ nên cung cấp sự hỗ trợ thiết thực cho các nạn nhân của vụ lừa đảo trực tuyến, bao gồm cả tư vấn pháp lý miễn phí.","audioKind":"ex2"}],"collocations":[{"en":"victim of crime","vi":"nạn nhân của tội phạm"},{"en":"fall victim to","vi":"trở thành nạn nhân của"},{"en":"flood victims","vi":"nạn nhân lũ lụt"}],"wordFamily":["victimise (v.)","victimisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Để diễn tả nạn nhân của việc gì, dùng victim of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arrest', 'en-b1-9', 'arrest', '/əˈrest/', 'B1', 'bắt giữ; sự bắt giữ; ngăn chặn; kìm hãm', 'v.', NULL, 'Đồng nghĩa: apprehend, halt', 'Bị bắt vì tội gì dùng be arrested for; cụm under arrest diễn tả trạng thái đang bị bắt giữ.', 'Police arrested the suspect outside the station yesterday.', NULL, 'Cảnh sát đã bắt giữ nghi phạm bên ngoài nhà ga ngày hôm qua.', '{"wordId":"arrest","ukIpa":"/əˈrest/","usIpa":"/əˈrest/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"to take someone into police custody under legal authority","vi":"bắt giữ"},{"pos":"n.","en":"the act of taking someone into police custody","vi":"sự bắt giữ"},{"pos":"v.","en":"to stop the progress or development of something","vi":"ngăn chặn; kìm hãm"}],"examples":[{"en":"Police arrested the suspect outside the station yesterday.","vi":"Cảnh sát đã bắt giữ nghi phạm bên ngoài nhà ga ngày hôm qua.","audioKind":"ex"},{"en":"Early investment in building maintenance can arrest the decline of historic neighbourhoods and preserve their distinctive character.","vi":"Việc đầu tư sớm vào bảo trì công trình có thể chặn đứng đà xuống cấp của các khu phố lịch sử và bảo tồn nét đặc trưng của chúng.","audioKind":"ex2"}],"collocations":[{"en":"arrest someone for theft","vi":"bắt giữ ai vì tội trộm cắp"},{"en":"under arrest","vi":"bị bắt"},{"en":"make an arrest","vi":"thực hiện lệnh bắt giữ"},{"en":"arrest the decline","vi":"ngăn chặn đà suy giảm"}],"wordFamily":[],"synonyms":["apprehend","halt"],"antonyms":[],"tipVi":"Bị bắt vì tội gì dùng be arrested for; cụm under arrest diễn tả trạng thái đang bị bắt giữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tradition', 'en-b1-9', 'tradition', '/trəˈdɪʃən/', 'B1', 'truyền thống; tập quán', 'n.', 'traditional (adj.), traditionally (adv.), traditionalist (n.)', 'Đồng nghĩa: custom', 'Khi chỉ một phong tục cụ thể thì đếm được; khi chỉ khái niệm trừu tượng chung có thể không đếm được, ví dụ như trong cụm "break with tradition".', 'Making dumplings together is a tradition in our family.', NULL, 'Cùng nhau gói bánh chưng là một truyền thống trong gia đình chúng tôi.', '{"wordId":"tradition","ukIpa":"/trəˈdɪʃən/","usIpa":"/trəˈdɪʃən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A belief or custom passed down through generations.","vi":"truyền thống; tập quán"}],"examples":[{"en":"Making dumplings together is a tradition in our family.","vi":"Cùng nhau gói bánh chưng là một truyền thống trong gia đình chúng tôi.","audioKind":"ex"},{"en":"Schools can help preserve local traditions by inviting older residents to share their knowledge and practical skills.","vi":"Các trường học có thể góp phần bảo tồn truyền thống địa phương bằng cách mời những bậc cao niên đến chia sẻ kiến thức và kỹ năng thực tiễn.","audioKind":"ex2"}],"collocations":[{"en":"family tradition","vi":"truyền thống gia đình"},{"en":"preserve a tradition","vi":"bảo tồn truyền thống"},{"en":"break with tradition","vi":"phá vỡ truyền thống"},{"en":"oral tradition","vi":"truyền thống truyền miệng"}],"wordFamily":["traditional (adj.)","traditionally (adv.)","traditionalist (n.)"],"synonyms":["custom"],"antonyms":[],"tipVi":"Khi chỉ một phong tục cụ thể thì đếm được; khi chỉ khái niệm trừu tượng chung có thể không đếm được, ví dụ như trong cụm \"break with tradition\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_individual', 'en-b1-9', 'individual', '/ˌɪndɪˈvɪdʒuəl/', 'B1', 'riêng lẻ; cá nhân; cá thể; đặc sắc; mang tính cá nhân', 'adj.', 'individually (adv.), individuality (n.), individualism (n.), individualistic (adj.)', 'Đồng nghĩa: personal, distinctive · Trái nghĩa: collective', 'Tính từ nhấn mạnh tính riêng lẻ hoặc thuộc về cá nhân; khi đóng vai trò danh từ đếm được, nó chỉ một người hoặc một cá thể.', 'The teacher gave each child an individual box of crayons.', NULL, 'Giáo viên phát cho mỗi đứa trẻ một hộp bút sáp màu riêng.', '{"wordId":"individual","ukIpa":"/ˌɪndɪˈvɪdʒuəl/","usIpa":"/ˌɪndɪˈvɪdʒuəl/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"Relating to one person or thing rather than a group","vi":"riêng lẻ; cá nhân"},{"pos":"n.","en":"One person or living thing considered separately from others","vi":"cá nhân; cá thể"},{"pos":"adj.","en":"Having qualities that make someone or something different from others","vi":"đặc sắc; mang tính cá nhân"}],"examples":[{"en":"The teacher gave each child an individual box of crayons.","vi":"Giáo viên phát cho mỗi đứa trẻ một hộp bút sáp màu riêng.","audioKind":"ex"},{"en":"Education systems should recognise individual learning needs rather than expect every student to progress at the same pace.","vi":"Hệ thống giáo dục nên công nhận nhu cầu học tập cá nhân thay vì mong đợi mọi học sinh tiến bộ cùng một tốc độ.","audioKind":"ex2"}],"collocations":[{"en":"individual needs","vi":"nhu cầu cá nhân"},{"en":"individual responsibility","vi":"trách nhiệm cá nhân"},{"en":"individual differences","vi":"sự khác biệt cá nhân"},{"en":"a talented individual","vi":"một cá nhân tài năng"}],"wordFamily":["individually (adv.)","individuality (n.)","individualism (n.)","individualistic (adj.)"],"synonyms":["personal","distinctive"],"antonyms":["collective"],"tipVi":"Tính từ nhấn mạnh tính riêng lẻ hoặc thuộc về cá nhân; khi đóng vai trò danh từ đếm được, nó chỉ một người hoặc một cá thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_9_1', 'en-b1-9', 'Cách dùng “tradition” (n.) — truyền thống; tập quán', 'family tradition  ·  preserve a tradition  ·  break with tradition', 'Khi chỉ một phong tục cụ thể thì đếm được; khi chỉ khái niệm trừu tượng chung có thể không đếm được, ví dụ như trong cụm "break with tradition".', 'Họ từ (Word Family): traditional (adj.), traditionally (adv.), traditionalist (n.) | Đồng nghĩa: custom', '[{"hanzi":"Making dumplings together is a tradition in our family.","pinyin":"","meaning":"Cùng nhau gói bánh chưng là một truyền thống trong gia đình chúng tôi."},{"hanzi":"Schools can help preserve local traditions by inviting older residents to share their knowledge and practical skills.","pinyin":"","meaning":"Các trường học có thể góp phần bảo tồn truyền thống địa phương bằng cách mời những bậc cao niên đến chia sẻ kiến thức và kỹ năng thực tiễn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_9_2', 'en-b1-9', 'Cách dùng “apologize” (v.) — xin lỗi; nhận lỗi', 'apologize to someone  ·  apologize for doing something  ·  apologize sincerely', 'Khi xin lỗi một người dùng giới từ to, khi xin lỗi về một việc gì dùng giới từ for; trong tiếng Anh - Anh cũng có thể viết là apologise.', 'Họ từ (Word Family): apology (n.), apologetic (adj.), apologetically (adv.) | Đồng nghĩa: say sorry', '[{"hanzi":"I apologized to my neighbour for the noise.","pinyin":"","meaning":"Tôi đã sang xin lỗi người hàng xóm vì tiếng ồn."},{"hanzi":"Companies should apologize promptly for service failures and explain what steps they will take to prevent further problems.","pinyin":"","meaning":"Các công ty nên chủ động xin lỗi kịp thời khi xảy ra sự cố dịch vụ và giải thích rõ các bước họ sẽ thực hiện để ngăn chặn những vấn đề tương tự."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_9_3', 'en-b1-9', 'Cách dùng “individual” (adj.) — riêng lẻ; cá nhân', 'individual needs  ·  individual responsibility  ·  individual differences', 'Tính từ nhấn mạnh tính riêng lẻ hoặc thuộc về cá nhân; khi đóng vai trò danh từ đếm được, nó chỉ một người hoặc một cá thể.', 'Họ từ (Word Family): individually (adv.), individuality (n.), individualism (n.), individualistic (adj.) | Đồng nghĩa: personal, distinctive · Trái nghĩa: collective', '[{"hanzi":"The teacher gave each child an individual box of crayons.","pinyin":"","meaning":"Giáo viên phát cho mỗi đứa trẻ một hộp bút sáp màu riêng."},{"hanzi":"Education systems should recognise individual learning needs rather than expect every student to progress at the same pace.","pinyin":"","meaning":"Hệ thống giáo dục nên công nhận nhu cầu học tập cá nhân thay vì mong đợi mọi học sinh tiến bộ cùng một tốc độ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_9_4', 'en-b1-9', 'Cách dùng “foreigner” (n.) — người nước ngoài', 'as a foreigner  ·  foreigners living abroad  ·  welcome foreigners', 'Dùng foreigner để chỉ chung người mang quốc tịch khác; nếu muốn nhấn mạnh khách du lịch thì dùng visitor sẽ tự nhiên hơn.', 'Họ từ (Word Family): foreign (adj.)', '[{"hanzi":"As a foreigner, I needed help understanding local customs.","pinyin":"","meaning":"Là một người nước ngoài, tôi cần sự giúp đỡ để hiểu các phong tục tập quán địa phương."},{"hanzi":"Language courses can help foreigners participate more fully in community life and access essential public services.","pinyin":"","meaning":"Các khóa học ngoại ngữ có thể giúp người nước ngoài hòa nhập tốt hơn vào đời sống cộng đồng và tiếp cận các dịch vụ công thiết yếu."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_9_1', 'en-b1-9', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
