INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_9_1_2', 'ten_b1_9_1', 'apologize', 'I apologized to my neighbour for the noise.', 'I apologized to my neighbour for the noise.', '/əˈpɑːlədʒaɪz/', 'Tôi đã sang xin lỗi người hàng xóm vì tiếng ồn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_9_1_3', 'ten_b1_9_1', 'foreigner', 'As a foreigner, I needed help understanding local customs.', 'As a foreigner, I needed help understanding local customs.', '/ˈfɔːrənər/', 'Là một người nước ngoài, tôi cần sự giúp đỡ để hiểu các phong tục tập quán địa phương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_9_1_4', 'ten_b1_9_1', 'engaged', 'My sister got engaged during her holiday by the sea.', 'My sister got engaged during her holiday by the sea.', '/ɪnˈɡeɪdʒd/', 'Chị tôi đã đính hôn trong chuyến nghỉ mát bên bờ biển.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_9_1_5', 'ten_b1_9_1', 'fool', 'The realistic plastic spider fooled everyone at the party.', 'The realistic plastic spider fooled everyone at the party.', '/fuːl/', 'Con nhện nhựa trông như thật đã lừa được tất cả mọi người trong bữa tiệc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_9_1_6', 'ten_b1_9_1', 'Bible', 'She keeps a Bible on the shelf beside her bed.', 'She keeps a Bible on the shelf beside her bed.', '/ˈbaɪbəl/', 'Cô ấy đặt một cuốn kinh Thánh trên kệ sách cạnh giường.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_9_1_7', 'ten_b1_9_1', 'weapon', 'The museum displays an ancient weapon behind thick glass.', 'The museum displays an ancient weapon behind thick glass.', '/ˈwepən/', 'Bảo tàng trưng bày một thứ vũ khí cổ đằng sau lớp kính dày.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_9_1_8', 'ten_b1_9_1', 'lover', 'The two lovers walked hand in hand beside the river.', 'The two lovers walked hand in hand beside the river.', '/ˈlʌvər/', 'Đôi uyên ương dạo bước tay trong tay bên bờ sông.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_9_1_1', 'en-b1-9', 'ten_b1_9_1', 'listening', 'listening', 'The prisoner borrowed a novel from the prison library.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cùng nhau gói bánh chưng là một truyền thống trong gia đình chúng tôi.","Tù nhân đó đã mượn một cuốn tiểu thuyết từ thư viện nhà tù.","Những người hàng xóm mang chăn ấm đến cho các nạn nhân vụ lũ lụt.","Cảnh sát đã bắt giữ nghi phạm bên ngoài nhà ga ngày hôm qua."]'::jsonb, 1, 'The prisoner borrowed a novel from the prison library. → Tù nhân đó đã mượn một cuốn tiểu thuyết từ thư viện nhà tù.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_9_1_2', 'en-b1-9', 'ten_b1_9_1', 'listening', 'listening', 'I apologized to my neighbour for the noise.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Huấn luyện viên của chúng tôi rất nghiêm khắc về việc có mặt đúng giờ.","Tôi đã sang xin lỗi người hàng xóm vì tiếng ồn.","Cộng đồng chúng tôi tụ họp vào mỗi mùa xuân để dọn dẹp công viên.","Chúng tôi đã có một buổi trò chuyện thân mật bên ly trà vào sáng nay."]'::jsonb, 1, 'I apologized to my neighbour for the noise. → Tôi đã sang xin lỗi người hàng xóm vì tiếng ồn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_9_1_3', 'en-b1-9', 'ten_b1_9_1', 'listening', 'listening', 'As a foreigner, I needed help understanding local customs.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Là một người nước ngoài, tôi cần sự giúp đỡ để hiểu các phong tục tập quán địa phương.","Huấn luyện viên của chúng tôi rất nghiêm khắc về việc có mặt đúng giờ.","Làm ơn hãy nói cho tôi sự thật về chiếc cốc bị vỡ.","Tôi đã sang xin lỗi người hàng xóm vì tiếng ồn."]'::jsonb, 0, 'As a foreigner, I needed help understanding local customs. → Là một người nước ngoài, tôi cần sự giúp đỡ để hiểu các phong tục tập quán địa phương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_9_2', 'en-b1-9', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_9_2_1', 'ten_b1_9_2', 'prisoner', 'Providing prisoners with education and vocational training may improve their chances of finding employment after release.', 'Providing prisoners with education and vocational training may improve their chances of finding employment after release.', '/ˈprɪzənər/', 'Việc cung cấp giáo dục và đào tạo nghề cho tù nhân có thể cải thiện cơ hội tìm việc làm sau khi họ ra tù.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_9_2_2', 'ten_b1_9_2', 'apologize', 'Companies should apologize promptly for service failures and explain what steps they will take to prevent further problems.', 'Companies should apologize promptly for service failures and explain what steps they will take to prevent further problems.', '/əˈpɑːlədʒaɪz/', 'Các công ty nên chủ động xin lỗi kịp thời khi xảy ra sự cố dịch vụ và giải thích rõ các bước họ sẽ thực hiện để ngăn chặn những vấn đề tương tự.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_9_2_3', 'ten_b1_9_2', 'foreigner', 'Language courses can help foreigners participate more fully in community life and access essential public services.', 'Language courses can help foreigners participate more fully in community life and access essential public services.', '/ˈfɔːrənər/', 'Các khóa học ngoại ngữ có thể giúp người nước ngoài hòa nhập tốt hơn vào đời sống cộng đồng và tiếp cận các dịch vụ công thiết yếu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_9_2_4', 'ten_b1_9_2', 'engaged', 'Students who are actively engaged in classroom discussions often develop stronger communication and critical thinking skills.', 'Students who are actively engaged in classroom discussions often develop stronger communication and critical thinking skills.', '/ɪnˈɡeɪdʒd/', 'Những học sinh tích cực tham gia vào các cuộc thảo luận trên lớp thường phát triển tốt hơn các kỹ năng giao tiếp và tư duy phản biện.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_9_2_5', 'ten_b1_9_2', 'fool', 'Misleading advertisements can fool consumers into buying products that offer little practical benefit.', 'Misleading advertisements can fool consumers into buying products that offer little practical benefit.', '/fuːl/', 'Các quảng cáo gây hiểu lầm có thể lừa người tiêu dùng mua những sản phẩm có ít giá trị thực tiễn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_9_2_6', 'ten_b1_9_2', 'Bible', 'Studying the Bible can help students understand religious references in European literature and visual art.', 'Studying the Bible can help students understand religious references in European literature and visual art.', '/ˈbaɪbəl/', 'Việc nghiên cứu kinh Thánh có thể giúp học sinh hiểu các điển tích tôn giáo trong văn học và nghệ thuật thị giác châu Âu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_9_2_1', 'en-b1-9', 'ten_b1_9_2', 'listening', 'listening', 'Providing prisoners with education and vocational training may improve their chances of finding employment after release.', NULL, 'Trong câu vừa nghe, từ “prisoner” mang nghĩa nào sau đây?', '["giấy phép; bằng lái; chứng chỉ","tham gia; liên quan","khoảng chừng; đại khái","tù nhân; người bị giam giữ, người bị cầm tù"]'::jsonb, 3, '“prisoner” (/ˈprɪzənər/): tù nhân; người bị giam giữ, người bị cầm tù. Câu đầy đủ: Providing prisoners with education and vocational training may improve their chances of finding employment after release.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_9_2_2', 'en-b1-9', 'ten_b1_9_2', 'listening', 'listening', 'Companies should apologize promptly for service failures and explain what steps they will take to prevent further problems.', NULL, 'Trong câu vừa nghe, từ “apologize” mang nghĩa nào sau đây?', '["nướng bằng vỉ","xin lỗi; nhận lỗi","làm phiền; làm bực mình; chọc tức","sự thèm ăn; cảm giác thèm ăn"]'::jsonb, 1, '“apologize” (/əˈpɑːlədʒaɪz/): xin lỗi; nhận lỗi. Câu đầy đủ: Companies should apologize promptly for service failures and explain what steps they will take to prevent further problems.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
