INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_1', 'en-b1-9', NULL, 'comprehensive_test', 'listening', 'prisoner', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bài tập giữ gìn vóc dáng; thể dục giữ vóc dáng","khách sạn ven đường","chẳng lẽ lại; chắc hẳn là","tù nhân; người bị giam giữ, người bị cầm tù"]'::jsonb, 3, 'prisoner (/ˈprɪzənər/) → tù nhân; người bị giam giữ, người bị cầm tù; tù binh; người bị kẻ địch bắt giữ trong thời chiến', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_2', 'en-b1-9', NULL, 'comprehensive_test', 'listening', 'I apologized to my neighbour for the noise.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đang thuyết phục anh trai thử món súp rau củ.","Chị tôi đã đính hôn trong chuyến nghỉ mát bên bờ biển.","Tôi đã sang xin lỗi người hàng xóm vì tiếng ồn.","Là một người nước ngoài, tôi cần sự giúp đỡ để hiểu các phong tục tập quán địa phương."]'::jsonb, 2, 'I apologized to my neighbour for the noise. → Tôi đã sang xin lỗi người hàng xóm vì tiếng ồn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_3', 'en-b1-9', NULL, 'comprehensive_test', 'listening', 'foreigner', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["người nước ngoài","hoàn toàn; tuyệt đối","trung bình; thông thường","sự hiểu biết; sự thông cảm"]'::jsonb, 0, 'foreigner (/ˈfɔːrənər/) → người nước ngoài', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_4', 'en-b1-9', NULL, 'comprehensive_test', 'listening', 'My sister got engaged during her holiday by the sea.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bảo tàng trưng bày một thứ vũ khí cổ đằng sau lớp kính dày.","Đôi uyên ương dạo bước tay trong tay bên bờ sông.","Chúng tôi đã có một buổi trò chuyện thân mật bên ly trà vào sáng nay.","Chị tôi đã đính hôn trong chuyến nghỉ mát bên bờ biển."]'::jsonb, 3, 'My sister got engaged during her holiday by the sea. → Chị tôi đã đính hôn trong chuyến nghỉ mát bên bờ biển.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_5', 'en-b1-9', NULL, 'comprehensive_test', 'listening', 'fool', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà nghiên cứu; nghiên cứu viên","làm cong; bẻ cong","kẻ ngốc; người hành động thiếu khôn ngoan","đồ đựng; vật dùng để chứa hoặc bảo quản đồ đạc"]'::jsonb, 2, 'fool (/fuːl/) → kẻ ngốc; người hành động thiếu khôn ngoan; lừa gạt; đánh lừa', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_6', 'en-b1-9', NULL, 'comprehensive_test', 'listening', 'She keeps a Bible on the shelf beside her bed.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tù nhân đó đã mượn một cuốn tiểu thuyết từ thư viện nhà tù.","Đôi uyên ương dạo bước tay trong tay bên bờ sông.","Những người hàng xóm mang chăn ấm đến cho các nạn nhân vụ lũ lụt.","Cô ấy đặt một cuốn kinh Thánh trên kệ sách cạnh giường."]'::jsonb, 3, 'She keeps a Bible on the shelf beside her bed. → Cô ấy đặt một cuốn kinh Thánh trên kệ sách cạnh giường.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_7', 'en-b1-9', NULL, 'comprehensive_test', 'listening', 'weapon', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nghề nghiệp; chuyên môn (đòi hỏi đào tạo chuyên sâu)","ngoài trời; lộ thiên","vũ khí; binh khí","bài thơ; tác phẩm văn học sử dụng ngôn từ được gọt giũa cẩn thận, thường được chia thành các dòng"]'::jsonb, 2, 'weapon (/ˈwepən/) → vũ khí; binh khí', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_8', 'en-b1-9', NULL, 'comprehensive_test', 'listening', 'The two lovers walked hand in hand beside the river.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đôi uyên ương dạo bước tay trong tay bên bờ sông.","Mỗi người đều có một vai trò cần đóng góp trong xã hội.","Cô ấy đang thuyết phục anh trai thử món súp rau củ.","Tù nhân đó đã mượn một cuốn tiểu thuyết từ thư viện nhà tù."]'::jsonb, 0, 'The two lovers walked hand in hand beside the river. → Đôi uyên ương dạo bước tay trong tay bên bờ sông.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_9', 'en-b1-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “someone who behaves without good sense or judgment”?', '["apologize","guilty","victim","fool"]'::jsonb, 3, 'fool (/fuːl/) → kẻ ngốc; người hành động thiếu khôn ngoan', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_10', 'en-b1-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the collection of sacred writings used in Christianity”?', '["Bible","individual","apologise","community"]'::jsonb, 0, 'Bible (/ˈbaɪbəl/) → kinh Thánh', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_11', 'en-b1-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “an object used for fighting or causing physical harm”?', '["weapon","arrest","foreigner","strict"]'::jsonb, 0, 'weapon (/ˈwepən/) → vũ khí; binh khí', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_12', 'en-b1-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Someone in a romantic or sexual relationship with another person.”?', '["apologize","individual","lover","aged"]'::jsonb, 2, 'lover (/ˈlʌvər/) → người yêu; tình nhân', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
