INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_18', 'en-b1-9', NULL, 'comprehensive_test', 'reading', NULL, 'Providing prisoners with education and vocational training may improve their chances of finding employment after release.', 'Dựa vào câu trên, từ “prisoner” có nghĩa phù hợp nhất là gì?', '["đã chuẩn bị sẵn sàng","tù nhân; người bị giam giữ, người bị cầm tù","tồn tại; có thật","đồ lót; trang phục mặc sát da"]'::jsonb, 1, 'prisoner: tù nhân; người bị giam giữ, người bị cầm tù; tù binh; người bị kẻ địch bắt giữ trong thời chiến. Dịch cả câu: Việc cung cấp giáo dục và đào tạo nghề cho tù nhân có thể cải thiện cơ hội tìm việc làm sau khi họ ra tù.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_19', 'en-b1-9', NULL, 'comprehensive_test', 'reading', NULL, 'Companies should apologize promptly for service failures and explain what steps they will take to prevent further problems.', 'Dựa vào câu trên, từ “apologize” có nghĩa phù hợp nhất là gì?', '["thân mật; thoải mái; không trang trọng","xin lỗi; nhận lỗi","khẽ; nhỏ nhẹ","thân phận; danh tính"]'::jsonb, 1, 'apologize: xin lỗi; nhận lỗi. Dịch cả câu: Các công ty nên chủ động xin lỗi kịp thời khi xảy ra sự cố dịch vụ và giải thích rõ các bước họ sẽ thực hiện để ngăn chặn những vấn đề tương tự.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_20', 'en-b1-9', NULL, 'comprehensive_test', 'reading', NULL, 'Language courses can help foreigners participate more fully in community life and access essential public services.', 'Dựa vào câu trên, từ “foreigner” có nghĩa phù hợp nhất là gì?', '["hóa chất; chất hóa học","người nước ngoài","khám phá; thám hiểm","sa mạc; vùng hoang mạc"]'::jsonb, 1, 'foreigner: người nước ngoài. Dịch cả câu: Các khóa học ngoại ngữ có thể giúp người nước ngoài hòa nhập tốt hơn vào đời sống cộng đồng và tiếp cận các dịch vụ công thiết yếu.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_21', 'en-b1-9', NULL, 'comprehensive_test', 'reading', NULL, 'Students who are actively engaged in classroom discussions often develop stronger communication and critical thinking skills.', 'Dựa vào câu trên, từ “engaged” có nghĩa phù hợp nhất là gì?', '["khoản tiền hoàn lại; sự hoàn tiền","đã đính hôn","bình tĩnh; điềm tĩnh","nền tảng; cơ sở"]'::jsonb, 1, 'engaged: đã đính hôn; bận rộn; tham gia vào; đang bận (đường dây điện thoại); đang được sử dụng. Dịch cả câu: Những học sinh tích cực tham gia vào các cuộc thảo luận trên lớp thường phát triển tốt hơn các kỹ năng giao tiếp và tư duy phản biện.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_22', 'en-b1-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bắt giữ”', '["filling","medal","arrest","payment"]'::jsonb, 2, 'bắt giữ → arrest (/əˈrest/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_23', 'en-b1-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “truyền thống; tập quán”', '["baby-sitter","striped","nightmare","tradition"]'::jsonb, 3, 'truyền thống; tập quán → tradition (/trəˈdɪʃən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_9_24', 'en-b1-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “riêng lẻ; cá nhân”', '["dot","trick","individual","deposit"]'::jsonb, 2, 'riêng lẻ; cá nhân → individual (/ˌɪndɪˈvɪdʒuəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-10', 'en', 'Bài 10: Xã hội & Cộng đồng (3) - CEFR B1', 'CEFR B1', 'B1 · Xã hội', '26 từ vựng Tiếng Anh CEFR B1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3010, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_involved', 'en-b1-10', 'involved', '/ɪnˈvɑːlvd/', 'B1', 'tham gia; liên quan; phức tạp; rối rắc', 'adj.', 'involve (v.), involvement (n.)', 'Trái nghĩa: uninvolved', 'Cụm từ "tham gia vào việc gì" sử dụng be involved in; có thể đặt sau danh từ khi làm định ngữ rút gọn.', 'Everyone involved in the picnic brought something to share.', NULL, 'Mọi người tham gia buổi dã ngoại đều mang theo thứ gì đó để chia sẻ.', '{"wordId":"involved","ukIpa":"/ɪnˈvɒlvd/","usIpa":"/ɪnˈvɑːlvd/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"taking part in or connected with something","vi":"tham gia; liên quan"},{"pos":"adj.","en":"complicated and difficult to understand","vi":"phức tạp; rối rắc"}],"examples":[{"en":"Everyone involved in the picnic brought something to share.","vi":"Mọi người tham gia buổi dã ngoại đều mang theo thứ gì đó để chia sẻ.","audioKind":"ex"},{"en":"Residents should be actively involved in planning decisions that affect the future of their neighbourhoods.","vi":"Cư dân nên tích cực tham gia vào các quyết định quy hoạch ảnh hưởng đến tương lai khu1 neighborhood của họ.","audioKind":"ex2"}],"collocations":[{"en":"get involved in","vi":"tham gia vào"},{"en":"actively involved","vi":"tham gia tích cực"},{"en":"an involved process","vi":"một quy trình phức tạp"}],"wordFamily":["involve (v.)","involvement (n.)"],"synonyms":[],"antonyms":["uninvolved"],"tipVi":"Cụm từ \"tham gia vào việc gì\" sử dụng be involved in; có thể đặt sau danh từ khi làm định ngữ rút gọn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stolen', 'en-b1-10', 'stolen', '/ˈstoʊlən/', 'B1', 'bị đánh cắp; bị mất trộm; đã lấy đi mà không được phép (phân từ quá khứ của steal)', 'adj.', 'steal (v.), theft (n.)', NULL, 'Biến đổi dạng thức steal — stole — stolen; stolen không được dùng đơn độc làm thì quá khứ.', 'The police found my stolen bicycle behind a garage.', NULL, 'Cảnh sát đã tìm thấy chiếc xe đạp bị trộm của tôi ở phía sau một gara.', '{"wordId":"stolen","ukIpa":"/ˈstəʊlən/","usIpa":"/ˈstoʊlən/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"taken from its owner without permission","vi":"bị đánh cắp; bị mất trộm"},{"pos":"v.","en":"taken something without permission, as the past participle of steal","vi":"đã lấy đi mà không được phép (phân từ quá khứ của steal)"}],"examples":[{"en":"The police found my stolen bicycle behind a garage.","vi":"Cảnh sát đã tìm thấy chiếc xe đạp bị trộm của tôi ở phía sau một gara.","audioKind":"ex"},{"en":"Stolen personal data can expose internet users to financial losses, highlighting the importance of effective online security.","vi":"Dữ liệu cá nhân bị đánh cắp có thể khiến người dùng internet đối mặt với tổn thất tài chính, làm nổi bật tầm quan trọng của bảo mật trực tuyến hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"stolen goods","vi":"hàng gian; tang vật"},{"en":"a stolen vehicle","vi":"một chiếc xe bị đánh cắp"},{"en":"stolen data","vi":"dữ liệu bị đánh cắp"}],"wordFamily":["steal (v.)","theft (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Biến đổi dạng thức steal — stole — stolen; stolen không được dùng đơn độc làm thì quá khứ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_poverty', 'en-b1-10', 'poverty', '/ˈpɑːvərti/', 'B1', 'sự nghèo đói; cảnh nghèo túng; sự thiếu thốn; sự bần cùng', 'n.', 'poor (adj.), impoverish (v.), impoverished (adj.)', 'Đồng nghĩa: destitution · Trái nghĩa: wealth, affluence', 'Danh từ không đếm được; cụm từ "sống nghèo khổ" dùng live in poverty.', 'The charity helps local families living in poverty.', NULL, 'Tổ chức từ thiện này giúp đỡ các gia đình địa phương đang sống trong cảnh nghèo khó.', '{"wordId":"poverty","ukIpa":"/ˈpɒvəti/","usIpa":"/ˈpɑːvərti/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"The condition of lacking money for basic needs.","vi":"sự nghèo đói; cảnh nghèo túng"},{"pos":"n.","en":"A serious lack of something needed or valued.","vi":"sự thiếu thốn; sự bần cùng"}],"examples":[{"en":"The charity helps local families living in poverty.","vi":"Tổ chức từ thiện này giúp đỡ các gia đình địa phương đang sống trong cảnh nghèo khó.","audioKind":"ex"},{"en":"Improving access to education and stable employment can help reduce poverty across both rural and urban communities.","vi":"Việc nâng cao khả năng tiếp cận giáo dục và việc làm ổn định có thể góp phần giảm nghèo ở cả vùng nông thôn và thành thị.","audioKind":"ex2"}],"collocations":[{"en":"live in poverty","vi":"sống trong cảnh nghèo đói"},{"en":"reduce poverty","vi":"giảm nghèo"},{"en":"extreme poverty","vi":"cảnh nghèo đói cùng cực"},{"en":"a poverty of ideas","vi":"sự nghèo nàn về ý tưởng"}],"wordFamily":["poor (adj.)","impoverish (v.)","impoverished (adj.)"],"synonyms":["destitution"],"antonyms":["wealth","affluence"],"tipVi":"Danh từ không đếm được; cụm từ \"sống nghèo khổ\" dùng live in poverty.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_march', 'en-b1-10', 'march', '/mɑːrtʃ/', 'B1', 'diễu hành; bước đều; cuộc diễu hành; cuộc biểu tình; nhạc hành khúc', 'v.', 'marcher (n.)', NULL, 'Chữ march viết thường có nghĩa là hành tiến; viết hoa March chỉ tháng Ba.', 'The band marched through the square in bright uniforms.', NULL, 'Đội kèn trống mặc đồng phục rực rỡ diễu hành qua quảng trường.', '{"wordId":"march","ukIpa":"/mɑːtʃ/","usIpa":"/mɑːrtʃ/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"Walk with firm, regular steps, often in a group.","vi":"diễu hành; bước đều"},{"pos":"n.","en":"An organised walk by a group, often to protest.","vi":"cuộc diễu hành; cuộc biểu tình"},{"pos":"n.","en":"Music with a strong regular rhythm suitable for marching.","vi":"nhạc hành khúc"}],"examples":[{"en":"The band marched through the square in bright uniforms.","vi":"Đội kèn trống mặc đồng phục rực rỡ diễu hành qua quảng trường.","audioKind":"ex"},{"en":"Residents organised a peaceful march to demand safer roads and better public transport in their neighbourhood.","vi":"Người dân đã tổ chức một cuộc diễu hành ôn hòa nhằm yêu cầu nâng cao an toàn giao thông và cải thiện giao thông công cộng tại khu vực của họ.","audioKind":"ex2"}],"collocations":[{"en":"march through the streets","vi":"diễu hành qua các con phố"},{"en":"a protest march","vi":"cuộc biểu tình"},{"en":"a peaceful march","vi":"cuộc diễu hành hòa bình"},{"en":"a military march","vi":"nhạc quân hành"}],"wordFamily":["marcher (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ march viết thường có nghĩa là hành tiến; viết hoa March chỉ tháng Ba.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_affect', 'en-b1-10', 'affect', '/əˈfekt/', 'B1', 'gây ảnh hưởng; tác động đến; làm cho ai đó cảm động; làm ai đó đau buồn', 'v.', 'affected (adj.), unaffected (adj.)', 'Đồng nghĩa: influence, impact', 'Khi mang nghĩa "ảnh hưởng", "affect" là động từ, trong khi "effect" thường là danh từ.', 'Too much coffee can affect how well you sleep.', NULL, 'Uống quá nhiều cà phê có thể ảnh hưởng đến chất lượng giấc ngủ của bạn.', '{"wordId":"affect","ukIpa":"/əˈfekt/","usIpa":"/əˈfekt/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"to cause a change in someone or something","vi":"gây ảnh hưởng; tác động đến"},{"pos":"v.","en":"to cause someone to feel a strong emotion","vi":"làm cho ai đó cảm động; làm ai đó đau buồn"}],"examples":[{"en":"Too much coffee can affect how well you sleep.","vi":"Uống quá nhiều cà phê có thể ảnh hưởng đến chất lượng giấc ngủ của bạn.","audioKind":"ex"},{"en":"Rising food prices disproportionately affect poorer households, which spend a larger share of their income on essentials.","vi":"Giá thực phẩm tăng cao ảnh hưởng không cân xứng đến các hộ gia đình nghèo hơn, những người phải dành phần lớn thu nhập cho các nhu yếu phẩm.","audioKind":"ex2"}],"collocations":[{"en":"affect health","vi":"ảnh hưởng đến sức khỏe"},{"en":"adversely affect","vi":"tác động bất lợi"},{"en":"deeply affect someone","vi":"làm sâu sắc thêm cảm xúc của ai"},{"en":"affect performance","vi":"ảnh hưởng đến hiệu suất"}],"wordFamily":["affected (adj.)","unaffected (adj.)"],"synonyms":["influence","impact"],"antonyms":[],"tipVi":"Khi mang nghĩa \"ảnh hưởng\", \"affect\" là động từ, trong khi \"effect\" thường là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_advantage', 'en-b1-10', 'advantage', '/ədˈvæntɪdʒ/', 'B1', 'lợi thế; ưu thế; điểm có lợi; ích lợi', 'n.', 'advantageous (adj.), disadvantage (n.), disadvantaged (adj.)', 'Đồng nghĩa: benefit, edge · Trái nghĩa: disadvantage', '"Take advantage of" có thể mang nghĩa tận dụng cơ hội tốt, hoặc lợi dụng ai đó.', 'Your long arms give you an advantage in swimming.', NULL, 'Sải tay dài mang lại cho bạn lợi thế khi bơi lội.', '{"wordId":"advantage","ukIpa":"/ədˈvɑːntɪdʒ/","usIpa":"/ədˈvæntɪdʒ/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"Something that makes success more likely than for others.","vi":"lợi thế; ưu thế"},{"pos":"n.","en":"A useful or positive feature of something.","vi":"điểm có lợi; ích lợi"}],"examples":[{"en":"Your long arms give you an advantage in swimming.","vi":"Sải tay dài mang lại cho bạn lợi thế khi bơi lội.","audioKind":"ex"},{"en":"One major advantage of public transport is its ability to reduce traffic congestion in urban areas.","vi":"Một lợi thế lớn của giao thông công cộng là khả năng giảm thiểu tình trạng ùn tắc giao thông ở các đô thị.","audioKind":"ex2"}],"collocations":[{"en":"competitive advantage","vi":"lợi thế cạnh tranh"},{"en":"have an advantage over","vi":"có lợi thế hơn so với"},{"en":"take advantage of","vi":"tận dụng; lợi dụng"},{"en":"a major advantage","vi":"một ưu điểm lớn"}],"wordFamily":["advantageous (adj.)","disadvantage (n.)","disadvantaged (adj.)"],"synonyms":["benefit","edge"],"antonyms":["disadvantage"],"tipVi":"\"Take advantage of\" có thể mang nghĩa tận dụng cơ hội tốt, hoặc lợi dụng ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cultural', 'en-b1-10', 'cultural', '/ˈkʌltʃərəl/', 'B1', 'thuộc về văn hóa; mang tính văn hóa; thuộc về nghệ thuật; văn nghệ', 'adj.', 'culture (n.), culturally (adv.), multicultural (adj.)', NULL, '''cultural'' chỉ những gì liên quan đến văn hóa; ''cultured'' dùng để miêu tả người có học thức, tao nhã.', 'The festival celebrates the town''s rich cultural traditions.', NULL, 'Lễ hội này tôn vinh các truyền thống văn hóa phong phú của thị trấn.', '{"wordId":"cultural","ukIpa":"/ˈkʌltʃərəl/","usIpa":"/ˈkʌltʃərəl/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"relating to a group''s customs, beliefs, and way of life","vi":"thuộc về văn hóa; mang tính văn hóa"},{"pos":"adj.","en":"relating to activities such as music, literature, and theatre","vi":"thuộc về nghệ thuật; văn nghệ"}],"examples":[{"en":"The festival celebrates the town''s rich cultural traditions.","vi":"Lễ hội này tôn vinh các truyền thống văn hóa phong phú của thị trấn.","audioKind":"ex"},{"en":"Schools can promote cultural understanding by encouraging students to share their family traditions and experiences.","vi":"Nhà trường có thể thúc đẩy sự hiểu biết văn hóa bằng cách khuyến khích học sinh chia sẻ truyền thống và trải nghiệm của gia đình các em.","audioKind":"ex2"}],"collocations":[{"en":"cultural heritage","vi":"di sản văn hóa"},{"en":"cultural diversity","vi":"sự đa dạng văn hóa"},{"en":"cultural differences","vi":"khác biệt văn hóa"},{"en":"cultural activities","vi":"hoạt động văn nghệ"}],"wordFamily":["culture (n.)","culturally (adv.)","multicultural (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"''cultural'' chỉ những gì liên quan đến văn hóa; ''cultured'' dùng để miêu tả người có học thức, tao nhã.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_communication', 'en-b1-10', 'communication', '/kəˌmjuːnɪˈkeɪʃən/', 'B1', 'sự giao tiếp; sự trao đổi; sự liên lạc; thông điệp; văn bản liên lạc', 'n.', 'communicate (v.), communicative (adj.), communicator (n.)', NULL, 'Nghĩa sự giao tiếp thường không đếm được; nghĩa văn bản/thông điệp chính thức có thể đếm được.', 'Clear communication helps us share the kitchen without arguments.', NULL, 'Giao tiếp rõ ràng giúp chúng ta cùng sử dụng phòng bếp mà không xảy ra tranh cãi.', '{"wordId":"communication","ukIpa":"/kəˌmjuːnɪˈkeɪʃən/","usIpa":"/kəˌmjuːnɪˈkeɪʃən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the process of sharing information, ideas, or feelings","vi":"sự giao tiếp; sự trao đổi; sự liên lạc"},{"pos":"n.","en":"a formal message sent to someone","vi":"thông điệp; văn bản liên lạc"}],"examples":[{"en":"Clear communication helps us share the kitchen without arguments.","vi":"Giao tiếp rõ ràng giúp chúng ta cùng sử dụng phòng bếp mà không xảy ra tranh cãi.","audioKind":"ex"},{"en":"Effective communication between healthcare professionals and patients can improve treatment outcomes and reduce misunderstandings.","vi":"Giao tiếp hiệu quả giữa các chuyên gia y tế và bệnh nhân có thể cải thiện kết quả điều trị và giảm thiểu hiểu lầm.","audioKind":"ex2"}],"collocations":[{"en":"communication skills","vi":"kỹ năng giao tiếp"},{"en":"effective communication","vi":"giao tiếp hiệu quả"},{"en":"nonverbal communication","vi":"giao tiếp phi ngôn ngữ"},{"en":"a breakdown in communication","vi":"sự gián đoạn trong giao tiếp"}],"wordFamily":["communicate (v.)","communicative (adj.)","communicator (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa sự giao tiếp thường không đếm được; nghĩa văn bản/thông điệp chính thức có thể đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_apology', 'en-b1-10', 'apology', '/əˈpɑːlədʒi/', 'B1', 'lời xin lỗi; sự hối lỗi', 'n.', 'apologise (v.), apologetic (adj.), apologetically (adv.)', NULL, 'Nói lời xin lỗi với ai đó về việc gì dùng apology to someone for something.', 'I sent my neighbour an apology for the noise.', NULL, 'Tôi đã gửi lời xin lỗi đến hàng xóm vì tiếng ồn.', '{"wordId":"apology","ukIpa":"/əˈpɒlədʒi/","usIpa":"/əˈpɑːlədʒi/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"words expressing regret for something wrong or hurtful","vi":"lời xin lỗi; sự hối lỗi"}],"examples":[{"en":"I sent my neighbour an apology for the noise.","vi":"Tôi đã gửi lời xin lỗi đến hàng xóm vì tiếng ồn.","audioKind":"ex"},{"en":"A sincere public apology can help organisations rebuild trust after mistakes, but practical changes are also necessary.","vi":"Một lời xin lỗi công khai chân thành có thể giúp các tổ chức lấy lại niềm tin sau những sai lầm, nhưng những thay đổi thực tế cũng rất cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"offer an apology","vi":"đưa ra lời xin lỗi"},{"en":"accept an apology","vi":"chấp nhận lời xin lỗi"},{"en":"a sincere apology","vi":"một lời xin lỗi chân thành"},{"en":"owe someone an apology","vi":"mắc nợ ai đó một lời xin lỗi"}],"wordFamily":["apologise (v.)","apologetic (adj.)","apologetically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Nói lời xin lỗi với ai đó về việc gì dùng apology to someone for something.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_survey', 'en-b1-10', 'survey', '/ˈsɝːveɪ/', 'B1', 'cuộc khảo sát; cuộc thăm dò ý kiến; tiến hành khảo sát; thu thập ý kiến; khảo sát; đo đạc (đất đai, công trình)', 'n.', 'surveyor (n.)', 'Đồng nghĩa: poll', 'Danh từ trọng âm ở âm tiết đầu, động từ trọng âm ở âm tiết cuối.', 'I completed a short survey about our local library.', NULL, 'Tôi đã hoàn thành một bảng khảo sát ngắn về thư viện địa phương của chúng ta.', '{"wordId":"survey","ukIpa":"/ˈsɜːveɪ/","usIpa":"/ˈsɝːveɪ/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A study that collects information by asking people questions.","vi":"cuộc khảo sát; cuộc thăm dò ý kiến"},{"pos":"v.","en":"Collect information by asking people questions.","vi":"tiến hành khảo sát; thu thập ý kiến"},{"pos":"v.","en":"Examine and measure land or buildings in detail.","vi":"khảo sát; đo đạc (đất đai, công trình)"}],"examples":[{"en":"I completed a short survey about our local library.","vi":"Tôi đã hoàn thành một bảng khảo sát ngắn về thư viện địa phương của chúng ta.","audioKind":"ex"},{"en":"A recent survey suggests that many commuters would cycle more often if safer routes were available.","vi":"Một cuộc khảo sát gần đây cho thấy nhiều người đi lại làm việc thường xuyên hơn bằng xe đạp nếu có sẵn các tuyến đường an toàn hơn.","audioKind":"ex2"}],"collocations":[{"en":"conduct a survey","vi":"thực hiện khảo sát"},{"en":"survey results","vi":"kết quả khảo sát"},{"en":"survey respondents","vi":"những người tham gia khảo sát"},{"en":"survey the land","vi":"khảo sát đất đai"}],"wordFamily":["surveyor (n.)"],"synonyms":["poll"],"antonyms":[],"tipVi":"Danh từ trọng âm ở âm tiết đầu, động từ trọng âm ở âm tiết cuối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kindness', 'en-b1-10', 'kindness', '/ˈkaɪndnəs/', 'B1', 'lòng tốt; sự ân cần; sự tử tế; hành động tốt; cử chỉ ân cần', 'n.', 'kind (adj.), kindly (adv.), unkind (adj.)', 'Đồng nghĩa: benevolence, compassion · Trái nghĩa: cruelty, unkindness', 'Khi chỉ phẩm chất tốt, từ này không đếm được; khi chỉ hành động tử tế cụ thể, từ này đếm được.', 'Her kindness made our new neighbour feel welcome.', NULL, 'Sự tử tế của cô ấy đã khiến người hàng xóm mới của chúng tôi cảm thấy được chào đón.', '{"wordId":"kindness","ukIpa":"/ˈkaɪndnəs/","usIpa":"/ˈkaɪndnəs/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the quality of caring about others and helping them","vi":"lòng tốt; sự ân cần; sự tử tế"},{"pos":"n.","en":"an act that helps someone or shows care","vi":"hành động tốt; cử chỉ ân cần"}],"examples":[{"en":"Her kindness made our new neighbour feel welcome.","vi":"Sự tử tế của cô ấy đã khiến người hàng xóm mới của chúng tôi cảm thấy được chào đón.","audioKind":"ex"},{"en":"Schools can encourage kindness by giving students opportunities to support classmates who face personal difficulties.","vi":"Nhà trường có thể khuyến khích lòng tốt bằng cách tạo cơ hội cho học sinh giúp đỡ các bạn cùng lớp đang gặp khó khăn trong cuộc sống.","audioKind":"ex2"}],"collocations":[{"en":"show kindness","vi":"thể hiện lòng tốt"},{"en":"an act of kindness","vi":"một hành động tử tế"},{"en":"kindness towards others","vi":"lòng tốt đối với người khác"}],"wordFamily":["kind (adj.)","kindly (adv.)","unkind (adj.)"],"synonyms":["benevolence","compassion"],"antonyms":["cruelty","unkindness"],"tipVi":"Khi chỉ phẩm chất tốt, từ này không đếm được; khi chỉ hành động tử tế cụ thể, từ này đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_native', 'en-b1-10', 'native', '/ˈneɪtɪv/', 'B1', 'thuộc nơi sinh hoặc tiếng mẹ đẻ; bản địa, nguyên sinh, mọc hoặc sống tự nhiên tại một khu vực; người sinh ra tại một địa phương cụ thể, người bản xứ', 'adj.', 'non-native (adj.)', 'Trái nghĩa: non-native', 'a native of dùng để chỉ người sinh ra ở một nơi nào đó; the natives đôi khi có thể mang hàm ý mỉa mai.', 'After years abroad, Ravi returned to his native city.', NULL, 'Sau nhiều năm ở nước ngoài, Ravi đã trở về thành phố quê hương của mình.', '{"wordId":"native","ukIpa":"/ˈneɪtɪv/","usIpa":"/ˈneɪtɪv/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"connected with the place or language of someone''s early life","vi":"thuộc nơi sinh hoặc tiếng mẹ đẻ"},{"pos":"adj.","en":"living or growing naturally in a particular region","vi":"bản địa, nguyên sinh, mọc hoặc sống tự nhiên tại một khu vực"},{"pos":"n.","en":"a person born in a particular place","vi":"người sinh ra tại một địa phương cụ thể, người bản xứ"}],"examples":[{"en":"After years abroad, Ravi returned to his native city.","vi":"Sau nhiều năm ở nước ngoài, Ravi đã trở về thành phố quê hương của mình.","audioKind":"ex"},{"en":"Planting native species in urban gardens can support local wildlife and reduce the need for additional watering.","vi":"Việc trồng các loài cây bản địa trong các khu vườn đô thị có thể hỗ trợ động vật hoang dã địa phương và giảm nhu cầu tưới nước bổ sung.","audioKind":"ex2"}],"collocations":[{"en":"native language","vi":"tiếng mẹ đẻ"},{"en":"native speaker","vi":"người bản xứ"},{"en":"native species","vi":"loài bản địa"},{"en":"be native to","vi":"vốn có nguồn gốc từ"}],"wordFamily":["non-native (adj.)"],"synonyms":[],"antonyms":["non-native"],"tipVi":"a native of dùng để chỉ người sinh ra ở một nơi nào đó; the natives đôi khi có thể mang hàm ý mỉa mai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prison', 'en-b1-10', 'prison', '/ˈprɪzən/', 'B1', 'nhà tù, trại giam; tình trạng bị giam cầm trong tù', 'n.', 'prisoner (n.), imprison (v.), imprisonment (n.)', 'Đồng nghĩa: jail', 'in prison mang nghĩa đang thụ án tù; in the prison nhấn mạnh vị trí ở bên trong nhà tù.', 'The old prison has become a popular local museum.', NULL, 'Nhà tù cũ đã trở thành một bảo tàng địa phương nổi tiếng.', '{"wordId":"prison","ukIpa":"/ˈprɪzən/","usIpa":"/ˈprɪzən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A place where people are kept as punishment for crimes.","vi":"nhà tù, trại giam"},{"pos":"n.","en":"The state of being kept in a prison.","vi":"tình trạng bị giam cầm trong tù"}],"examples":[{"en":"The old prison has become a popular local museum.","vi":"Nhà tù cũ đã trở thành một bảo tàng địa phương nổi tiếng.","audioKind":"ex"},{"en":"Education programmes in prison can help individuals develop skills that support their successful return to society.","vi":"Các chương trình giáo dục trong tù có thể giúp các cá nhân phát triển các kỹ năng hỗ trợ họ tái hòa nhập cộng đồng thành công.","audioKind":"ex2"}],"collocations":[{"en":"in prison","vi":"đang thi hành án tù"},{"en":"go to prison","vi":"vào tù"},{"en":"prison sentence","vi":"bản án tù"},{"en":"prison reform","vi":"cải cách nhà tù"}],"wordFamily":["prisoner (n.)","imprison (v.)","imprisonment (n.)"],"synonyms":["jail"],"antonyms":[],"tipVi":"in prison mang nghĩa đang thụ án tù; in the prison nhấn mạnh vị trí ở bên trong nhà tù.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_independent', 'en-b1-10', 'independent', '/ˌɪndɪˈpendənt/', 'B1', 'độc lập; tự chủ; tự lập; không bị chi phối; không bị kiểm soát; không liên quan; không bị ảnh hưởng', 'adj.', 'independence (n.), independently (adv.), dependent (adj.), dependence (n.)', 'Đồng nghĩa: self-reliant, autonomous · Trái nghĩa: dependent', 'Thường đi kèm với giới từ of: independent of có nghĩa là không phụ thuộc hoặc không bị ảnh hưởng bởi.', 'Living alone has made me much more independent.', NULL, 'Việc sống một mình đã khiến tôi trở nên độc lập hơn rất nhiều.', '{"wordId":"independent","ukIpa":"/ˌɪndɪˈpendənt/","usIpa":"/ˌɪndɪˈpendənt/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"able to live or act without relying on others","vi":"độc lập; tự chủ; tự lập"},{"pos":"adj.","en":"not controlled by another person, organisation, or country","vi":"không bị chi phối; không bị kiểm soát"},{"pos":"adj.","en":"not connected with or affected by something else","vi":"không liên quan; không bị ảnh hưởng"}],"examples":[{"en":"Living alone has made me much more independent.","vi":"Việc sống một mình đã khiến tôi trở nên độc lập hơn rất nhiều.","audioKind":"ex"},{"en":"Independent research can help governments assess whether new environmental policies are achieving their intended goals.","vi":"Nghiên cứu độc lập có thể giúp chính phủ đánh giá xem các chính sách môi trường mới có đang đạt được các mục tiêu đề ra hay không.","audioKind":"ex2"}],"collocations":[{"en":"financially independent","vi":"độc lập về tài chính"},{"en":"independent research","vi":"nghiên cứu độc lập"},{"en":"independent of","vi":"không phụ thuộc vào; không bị ảnh hưởng bởi"},{"en":"independent judgement","vi":"nhận định độc lập"}],"wordFamily":["independence (n.)","independently (adv.)","dependent (adj.)","dependence (n.)"],"synonyms":["self-reliant","autonomous"],"antonyms":["dependent"],"tipVi":"Thường đi kèm với giới từ of: independent of có nghĩa là không phụ thuộc hoặc không bị ảnh hưởng bởi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pray', 'en-b1-10', 'pray', '/preɪ/', 'B1', 'cầu nguyện; cầu xin (thần linh); hy vọng thiết tha; khẩn cầu', 'v.', 'prayer (n.)', NULL, 'pray to dùng cho đối tượng được hướng lời cầu nguyện, pray for dùng cho điều được khẩn cầu.', 'They gather quietly each morning to pray for peace.', NULL, 'Họ lặng lẽ tụ họp vào mỗi buổi sáng để cầu nguyện cho hòa bình.', '{"wordId":"pray","ukIpa":"/preɪ/","usIpa":"/preɪ/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"To speak to a god to ask, thank, or worship.","vi":"cầu nguyện; cầu xin (thần linh)"},{"pos":"v.","en":"To hope very strongly that something will happen.","vi":"hy vọng thiết tha; khẩn cầu"}],"examples":[{"en":"They gather quietly each morning to pray for peace.","vi":"Họ lặng lẽ tụ họp vào mỗi buổi sáng để cầu nguyện cho hòa bình.","audioKind":"ex"},{"en":"Providing quiet spaces allows people of different faiths to pray while studying or working on campus.","vi":"Việc cung cấp không gian yên tĩnh giúp những người có tín ngưỡng khác nhau có thể cầu nguyện trong lúc học tập hoặc làm việc tại trường.","audioKind":"ex2"}],"collocations":[{"en":"pray for peace","vi":"cầu nguyện cho hòa bình"},{"en":"pray to God","vi":"cầu nguyện cùng Chúa"},{"en":"pray that","vi":"cầu mong rằng"}],"wordFamily":["prayer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"pray to dùng cho đối tượng được hướng lời cầu nguyện, pray for dùng cho điều được khẩn cầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dialogue', 'en-b1-10', 'dialogue', '/ˈdaɪəlɔːɡ/', 'B1', 'cuộc đối thoại; sự trao đổi ý kiến; lời thoại; đối thoại (trong tác phẩm, kịch nghệ)', 'n.', NULL, 'Đồng nghĩa: conversation, discussion', 'Từ này vừa chỉ sự giao tiếp trong đời thực, vừa chỉ phần lời thoại của nhân vật trong tiểu thuyết hoặc phim ảnh.', 'The neighbours began a friendly dialogue about their shared garden.', NULL, 'Những người hàng xóm đã bắt đầu một cuộc đối thoại thân thiện về khu vườn chung của họ.', '{"wordId":"dialogue","ukIpa":"/ˈdaɪəlɒɡ/","usIpa":"/ˈdaɪəlɔːɡ/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A conversation or discussion, especially to exchange views","vi":"cuộc đối thoại; sự trao đổi ý kiến"},{"pos":"n.","en":"The words spoken by characters in a story or performance","vi":"lời thoại; đối thoại (trong tác phẩm, kịch nghệ)"}],"examples":[{"en":"The neighbours began a friendly dialogue about their shared garden.","vi":"Những người hàng xóm đã bắt đầu một cuộc đối thoại thân thiện về khu vườn chung của họ.","audioKind":"ex"},{"en":"Open dialogue between teachers and parents can help schools respond more effectively to children''s needs.","vi":"Cuộc đối thoại cởi mở giữa giáo viên và phụ huynh có thể giúp nhà trường đáp ứng hiệu quả hơn các nhu cầu của trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"open dialogue","vi":"đối thoại cởi mở"},{"en":"engage in dialogue","vi":"tham gia vào đối thoại"},{"en":"dialogue between communities","vi":"cuộc đối thoại giữa các cộng đồng"},{"en":"natural dialogue","vi":"lời thoại tự nhiên"}],"wordFamily":[],"synonyms":["conversation","discussion"],"antonyms":[],"tipVi":"Từ này vừa chỉ sự giao tiếp trong đời thực, vừa chỉ phần lời thoại của nhân vật trong tiểu thuyết hoặc phim ảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_face-to-face', 'en-b1-10', 'face-to-face', '/ˌfeɪs tə ˈfeɪs/', 'B1', 'trực tiếp; đối mặt; một cách trực tiếp', 'adj.', NULL, 'Đồng nghĩa: in-person', 'Thường có gạch nối khi đứng trước danh từ; viết rời là face to face khi làm trạng ngữ.', 'We arranged a face-to-face meeting at the local café.', NULL, 'Chúng tôi đã sắp xếp một cuộc họp trực tiếp tại quán cà phê địa phương.', '{"wordId":"face-to-face","ukIpa":"/ˌfeɪs tə ˈfeɪs/","usIpa":"/ˌfeɪs tə ˈfeɪs/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"Involving people physically present together and looking at each other.","vi":"trực tiếp; đối mặt"},{"pos":"adv.","en":"With people physically present together rather than communicating remotely.","vi":"một cách trực tiếp"}],"examples":[{"en":"We arranged a face-to-face meeting at the local café.","vi":"Chúng tôi đã sắp xếp một cuộc họp trực tiếp tại quán cà phê địa phương.","audioKind":"ex"},{"en":"Face-to-face communication can strengthen relationships between teachers and students by allowing immediate feedback and clearer emotional expression.","vi":"Giao tiếp trực tiếp có thể củng cố mối quan hệ giữa giáo viên và học sinh bằng cách cho phép phản hồi tức thì và biểu đạt cảm xúc rõ ràng hơn.","audioKind":"ex2"}],"collocations":[{"en":"a face-to-face meeting","vi":"cuộc họp trực tiếp"},{"en":"face-to-face communication","vi":"giao tiếp trực tiếp"},{"en":"a face-to-face interview","vi":"phỏng vấn trực tiếp"}],"wordFamily":[],"synonyms":["in-person"],"antonyms":[],"tipVi":"Thường có gạch nối khi đứng trước danh từ; viết rời là face to face khi làm trạng ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_divorce', 'en-b1-10', 'divorce', '/dɪˈvɔːrs/', 'B1', 'sự ly hôn; ly hôn; tách biệt; tách rời', 'n.', 'divorced (adj.)', NULL, 'Dùng divorce sb để chỉ việc ly hôn với ai đó, không dùng kèm với with.', 'They remained good friends even after their divorce.', NULL, 'Họ vẫn giữ mối quan hệ bạn bè tốt đẹp ngay cả sau khi ly hôn.', '{"wordId":"divorce","ukIpa":"/dɪˈvɔːs/","usIpa":"/dɪˈvɔːrs/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the legal ending of a marriage","vi":"sự ly hôn"},{"pos":"v.","en":"to legally end a marriage","vi":"ly hôn"},{"pos":"v.","en":"to separate something from something closely connected with it","vi":"tách biệt; tách rời"}],"examples":[{"en":"They remained good friends even after their divorce.","vi":"Họ vẫn giữ mối quan hệ bạn bè tốt đẹp ngay cả sau khi ly hôn.","audioKind":"ex"},{"en":"Economic growth cannot be divorced from environmental concerns when governments develop policies for sustainable urban expansion.","vi":"Chính phủ không thể tách rời tăng trưởng kinh tế ra khỏi các vấn đề môi trường khi hoạch định chính sách phát triển đô thị bền vững.","audioKind":"ex2"}],"collocations":[{"en":"get a divorce","vi":"làm thủ tục ly hôn"},{"en":"file for divorce","vi":"nộp đơn ly hôn"},{"en":"divorce something from something","vi":"tách biệt cái gì ra khỏi cái gì"}],"wordFamily":["divorced (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng divorce sb để chỉ việc ly hôn với ai đó, không dùng kèm với with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_organization', 'en-b1-10', 'organization', '/ˌɔːrɡənəˈzeɪʃən/', 'B1', 'tổ chức; cơ quan; hiệp hội; công tác tổ chức; sự sắp xếp', 'n.', 'organize (v.), organizer (n.), organizational (adj.), organized (adj.)', 'Đồng nghĩa: institution, association', 'Đếm được khi chỉ cơ quan, không đếm được khi chỉ công tác tổ chức; tiếng Anh-Anh cũng viết là organisation.', 'She volunteers for an organization that rescues injured birds.', NULL, 'Cô ấy làm tình nguyện viên cho một tổ chức cứu hộ chim bị thương.', '{"wordId":"organization","ukIpa":"/ˌɔːɡənaɪˈzeɪʃən/","usIpa":"/ˌɔːrɡənəˈzeɪʃən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A group of people working together for a shared purpose.","vi":"tổ chức; cơ quan; hiệp hội"},{"pos":"n.","en":"The process of planning activities and arranging things efficiently.","vi":"công tác tổ chức; sự sắp xếp"}],"examples":[{"en":"She volunteers for an organization that rescues injured birds.","vi":"Cô ấy làm tình nguyện viên cho một tổ chức cứu hộ chim bị thương.","audioKind":"ex"},{"en":"International organizations can help governments coordinate their responses to environmental problems that extend beyond national borders.","vi":"Các tổ chức quốc tế có thể giúp các chính phủ phối hợp ứng phó với các vấn đề môi trường vượt ra ngoài biên giới quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"a non-profit organization","vi":"một tổ chức phi lợi nhuận"},{"en":"an international organization","vi":"một tổ chức quốc tế"},{"en":"the organization of an event","vi":"việc tổ chức một sự kiện"},{"en":"poor organization","vi":"công tác tổ chức kém"}],"wordFamily":["organize (v.)","organizer (n.)","organizational (adj.)","organized (adj.)"],"synonyms":["institution","association"],"antonyms":[],"tipVi":"Đếm được khi chỉ cơ quan, không đếm được khi chỉ công tác tổ chức; tiếng Anh-Anh cũng viết là organisation.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insist', 'en-b1-10', 'insist', '/ɪnˈsɪst/', 'B1', 'khăng khăng đòi; kiên quyết; khẳng định; nằng nặc cho là', 'v.', 'insistence (n.), insistent (adj.), insistently (adv.)', 'Đồng nghĩa: demand, maintain', 'Dùng insist on doing, không dùng insist to do.', 'My grandparents insist on paying for lunch every time.', NULL, 'Ông bà tôi lần nào cũng kiên quyết trả tiền bữa trưa.', '{"wordId":"insist","ukIpa":"/ɪnˈsɪst/","usIpa":"/ɪnˈsɪst/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"to demand something firmly despite disagreement","vi":"khăng khăng đòi; kiên quyết"},{"pos":"v.","en":"to state firmly that something is true","vi":"khẳng định; nằng nặc cho là"}],"examples":[{"en":"My grandparents insist on paying for lunch every time.","vi":"Ông bà tôi lần nào cũng kiên quyết trả tiền bữa trưa.","audioKind":"ex"},{"en":"Many parents insist that schools provide regular physical education, even when academic subjects compete for classroom time.","vi":"Nhiều phụ huynh kiên quyết yêu cầu nhà trường tổ chức các lớp giáo dục thể chất đều đặn, ngay cả khi các môn học văn hóa chiếm hết thời gian trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"insist on doing something","vi":"khăng khăng đòi làm gì"},{"en":"insist that","vi":"kiên quyết rằng"},{"en":"insist on payment","vi":"khăng khăng đòi thanh toán"}],"wordFamily":["insistence (n.)","insistent (adj.)","insistently (adv.)"],"synonyms":["demand","maintain"],"antonyms":[],"tipVi":"Dùng insist on doing, không dùng insist to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rob', 'en-b1-10', 'rob', '/rɑːb/', 'B1', 'cướp; trấn lột tài sản; tước đoạt; làm mất đi', 'v.', 'robber (n.), robbery (n.)', NULL, 'rob đi với người hoặc địa điểm; steal đi với vật bị đánh cắp.', 'Someone tried to rob the shop near our house.', NULL, 'Ai đó đã cố gắng cướp tiệm tạp hóa gần nhà chúng tôi.', '{"wordId":"rob","ukIpa":"/rɒb/","usIpa":"/rɑːb/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"To take money or property illegally from someone or somewhere.","vi":"cướp; trấn lột tài sản"},{"pos":"v.","en":"To unfairly take away something valuable or important.","vi":"tước đoạt; làm mất đi"}],"examples":[{"en":"Someone tried to rob the shop near our house.","vi":"Ai đó đã cố gắng cướp tiệm tạp hóa gần nhà chúng tôi.","audioKind":"ex"},{"en":"Long working hours can rob parents of valuable opportunities to spend time with their children.","vi":"Thời gian làm việc kéo dài có thể tước đoạt của các bậc cha mẹ những cơ hội quý giá để dành thời gian cho con cái.","audioKind":"ex2"}],"collocations":[{"en":"rob a bank","vi":"cướp ngân hàng"},{"en":"rob someone of something","vi":"cướp của ai cái gì"},{"en":"rob someone of opportunities","vi":"tước đoạt cơ hội của ai"}],"wordFamily":["robber (n.)","robbery (n.)"],"synonyms":[],"antonyms":[],"tipVi":"rob đi với người hoặc địa điểm; steal đi với vật bị đánh cắp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_symbol', 'en-b1-10', 'symbol', '/ˈsɪmbəl/', 'B1', 'biểu tượng; dấu hiệu đại diện; ký hiệu; con dấu tượng trưng', 'n.', 'symbolic (adj.), symbolically (adv.), symbolise (v.), symbolism (n.)', NULL, 'Cụm từ "biểu tượng của..." tiếng Anh dùng a symbol of, không dùng symbol for.', 'For my grandparents, this old house is a symbol of hope.', NULL, 'Đối với ông bà tôi, ngôi nhà cũ này là một biểu tượng của hy vọng.', '{"wordId":"symbol","ukIpa":"/ˈsɪmbəl/","usIpa":"/ˈsɪmbəl/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"Something that represents an idea, quality, or group.","vi":"biểu tượng; dấu hiệu đại diện"},{"pos":"n.","en":"A written mark used to represent information.","vi":"ký hiệu; con dấu tượng trưng"}],"examples":[{"en":"For my grandparents, this old house is a symbol of hope.","vi":"Đối với ông bà tôi, ngôi nhà cũ này là một biểu tượng của hy vọng.","audioKind":"ex"},{"en":"Public parks can become a symbol of a city''s commitment to environmental protection and residents'' quality of life.","vi":"Các công viên công cộng có thể trở thành biểu tượng cho cam kết của thành phố đối với công tác bảo vệ môi trường và chất lượng cuộc sống của người dân.","audioKind":"ex2"}],"collocations":[{"en":"a symbol of peace","vi":"biểu tượng của hòa bình"},{"en":"a status symbol","vi":"biểu tượng địa vị"},{"en":"a mathematical symbol","vi":"ký hiệu toán học"}],"wordFamily":["symbolic (adj.)","symbolically (adv.)","symbolise (v.)","symbolism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ \"biểu tượng của...\" tiếng Anh dùng a symbol of, không dùng symbol for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gap', 'en-b1-10', 'gap', '/ɡæp/', 'B1', 'khe hở; khoảng trống; khoảng cách; sự khác biệt; khoảng thời gian gián đoạn', 'n.', 'gapped (adj.)', NULL, 'Khoảng cách giữa hai bên dùng gap between A and B.', 'The kitten squeezed through a gap in the fence.', NULL, 'Chú mèo con luồn qua khe hở trên hàng rào.', '{"wordId":"gap","ukIpa":"/ɡæp/","usIpa":"/ɡæp/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"An empty space between things or within something.","vi":"khe hở; khoảng trống"},{"pos":"n.","en":"A difference between people, groups, or situations.","vi":"khoảng cách; sự khác biệt"},{"pos":"n.","en":"A period when something stops or does not happen.","vi":"khoảng thời gian gián đoạn; khoảng trống"}],"examples":[{"en":"The kitten squeezed through a gap in the fence.","vi":"Chú mèo con luồn qua khe hở trên hàng rào.","audioKind":"ex"},{"en":"Improving access to affordable education could narrow the gap between wealthy households and disadvantaged communities.","vi":"Việc nâng cao khả năng tiếp cận giáo dục vừa túi tiền có thể thu hẹp khoảng cách giữa các hộ gia đình giàu có và các cộng đồng còn nhiều thiệt thòi.","audioKind":"ex2"}],"collocations":[{"en":"a gap in the fence","vi":"khe hở trên hàng rào"},{"en":"narrow the gap","vi":"thu hẹp khoảng cách"},{"en":"the generation gap","vi":"khoảng cách thế hệ"},{"en":"a gap year","vi":"năm trải nghiệm gián đoạn"}],"wordFamily":["gapped (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khoảng cách giữa hai bên dùng gap between A and B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thanksgiving', 'en-b1-10', 'thanksgiving', '/ˌθæŋksˈɡɪvɪŋ/', 'B1', 'sự tạ ơn; lời cầu nguyện cảm ơn; lễ Tạ ơn', 'n.', 'thank (v.), thankful (adj.), thankfully (adv.), thanks (n.)', NULL, 'Viết hoa chữ cái đầu khi chỉ ngày lễ (Thanksgiving); viết thường khi dùng với nghĩa tạ ơn chung.', 'They held a small thanksgiving ceremony after the harvest.', NULL, 'Họ tổ chức một buổi lễ tạ ơn nhỏ sau mùa gặt.', '{"wordId":"thanksgiving","ukIpa":"/ˌθæŋksˈɡɪvɪŋ/","usIpa":"/ˌθæŋksˈɡɪvɪŋ/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"The expression of gratitude, especially in prayer.","vi":"sự tạ ơn; lời cầu nguyện cảm ơn"},{"pos":"n.","en":"A holiday for expressing gratitude, celebrated in the US and Canada.","vi":"lễ Tạ ơn"}],"examples":[{"en":"They held a small thanksgiving ceremony after the harvest.","vi":"Họ tổ chức một buổi lễ tạ ơn nhỏ sau mùa gặt.","audioKind":"ex"},{"en":"In some countries, Thanksgiving brings families together and encourages reflection on the importance of community support.","vi":"Ở một số quốc gia, lễ Tạ ơn giúp gia đình quây quần bên nhau và khích lệ mọi người suy ngẫm về tầm quan trọng của việc hỗ trợ trong cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"in thanksgiving for","vi":"để bày tỏ lòng biết ơn vì"},{"en":"a prayer of thanksgiving","vi":"lời cầu nguyện tạ ơn"},{"en":"Thanksgiving dinner","vi":"bữa tối ngày lễ Tạ ơn"}],"wordFamily":["thank (v.)","thankful (adj.)","thankfully (adv.)","thanks (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu khi chỉ ngày lễ (Thanksgiving); viết thường khi dùng với nghĩa tạ ơn chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_friendship', 'en-b1-10', 'friendship', '/ˈfrendʃɪp/', 'B1', 'tình bạn; mối quan hệ bạn bè', 'n.', 'friend (n.), friendly (adj.), befriend (v.), friendliness (n.)', 'Trái nghĩa: enmity', 'Nghĩa chung chung là tình bạn thì không đếm được; một mối quan hệ bạn bè cụ thể thì đếm được.', 'Our friendship began when we shared a school desk.', NULL, 'Tình bạn của chúng tôi bắt đầu từ những ngày ngồi chung một bàn học.', '{"wordId":"friendship","ukIpa":"/ˈfrendʃɪp/","usIpa":"/ˈfrendʃɪp/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"a relationship between people who like and support each other","vi":"tình bạn; mối quan hệ bạn bè"}],"examples":[{"en":"Our friendship began when we shared a school desk.","vi":"Tình bạn của chúng tôi bắt đầu từ những ngày ngồi chung một bàn học.","audioKind":"ex"},{"en":"Close friendship can improve mental health by providing emotional support during periods of stress.","vi":"Tình bạn khăng khít có thể cải thiện sức khỏe tinh thần bằng cách cung cấp sự hỗ trợ về mặt cảm xúc trong những giai đoạn căng thẳng.","audioKind":"ex2"}],"collocations":[{"en":"close friendship","vi":"tình bạn thân thiết"},{"en":"form a friendship","vi":"gây dựng tình bạn"},{"en":"lasting friendship","vi":"tình bạn lâu bền"},{"en":"a bond of friendship","vi":"tình bạn gắn bó"}],"wordFamily":["friend (n.)","friendly (adj.)","befriend (v.)","friendliness (n.)"],"synonyms":[],"antonyms":["enmity"],"tipVi":"Nghĩa chung chung là tình bạn thì không đếm được; một mối quan hệ bạn bè cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_appearance', 'en-b1-10', 'appearance', '/əˈpɪrəns/', 'B1', 'ngoại hình; vẻ bề ngoài; sự xuất hiện; sự lộ diện', 'n.', 'appear (v.), disappear (v.), disappearance (n.)', 'Đồng nghĩa: looks', 'Cả diện mạo lẫn sự xuất hiện đều dùng appearance; xuất hiện thường dùng cấu trúc make an appearance.', 'A fresh coat of paint transformed the room''s appearance.', NULL, 'Một lớp sơn mới đã làm thay đổi hoàn toàn diện mạo của căn phòng.', '{"wordId":"appearance","ukIpa":"/əˈpɪərəns/","usIpa":"/əˈpɪrəns/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the way someone or something looks","vi":"ngoại hình; vẻ bề ngoài"},{"pos":"n.","en":"an occasion when someone or something becomes visible or present","vi":"sự xuất hiện; sự lộ diện"}],"examples":[{"en":"A fresh coat of paint transformed the room''s appearance.","vi":"Một lớp sơn mới đã làm thay đổi hoàn toàn diện mạo của căn phòng.","audioKind":"ex"},{"en":"Employers should assess candidates on their skills and experience rather than judging them by their appearance.","vi":"Các nhà tuyển dụng nên đánh giá ứng viên dựa trên kỹ năng và kinh nghiệm thay vì đánh giá qua bề ngoài.","audioKind":"ex2"}],"collocations":[{"en":"physical appearance","vi":"vẻ bề ngoài"},{"en":"make an appearance","vi":"xuất hiện"},{"en":"outward appearance","vi":"ngoại hình bên ngoài"},{"en":"improve the appearance of","vi":"cải thiện diện mạo của"}],"wordFamily":["appear (v.)","disappear (v.)","disappearance (n.)"],"synonyms":["looks"],"antonyms":[],"tipVi":"Cả diện mạo lẫn sự xuất hiện đều dùng appearance; xuất hiện thường dùng cấu trúc make an appearance.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_10_1', 'en-b1-10', 'Cách dùng “dialogue” (n.) — cuộc đối thoại; sự trao đổi ý kiến', 'open dialogue  ·  engage in dialogue  ·  dialogue between communities', 'Từ này vừa chỉ sự giao tiếp trong đời thực, vừa chỉ phần lời thoại của nhân vật trong tiểu thuyết hoặc phim ảnh.', 'Đồng nghĩa: conversation, discussion', '[{"hanzi":"The neighbours began a friendly dialogue about their shared garden.","pinyin":"","meaning":"Những người hàng xóm đã bắt đầu một cuộc đối thoại thân thiện về khu vườn chung của họ."},{"hanzi":"Open dialogue between teachers and parents can help schools respond more effectively to children''s needs.","pinyin":"","meaning":"Cuộc đối thoại cởi mở giữa giáo viên và phụ huynh có thể giúp nhà trường đáp ứng hiệu quả hơn các nhu cầu của trẻ em."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_10_2', 'en-b1-10', 'Cách dùng “organization” (n.) — tổ chức; cơ quan; hiệp hội', 'a non-profit organization  ·  an international organization  ·  the organization of an event', 'Đếm được khi chỉ cơ quan, không đếm được khi chỉ công tác tổ chức; tiếng Anh-Anh cũng viết là organisation.', 'Họ từ (Word Family): organize (v.), organizer (n.), organizational (adj.), organized (adj.) | Đồng nghĩa: institution, association', '[{"hanzi":"She volunteers for an organization that rescues injured birds.","pinyin":"","meaning":"Cô ấy làm tình nguyện viên cho một tổ chức cứu hộ chim bị thương."},{"hanzi":"International organizations can help governments coordinate their responses to environmental problems that extend beyond national borders.","pinyin":"","meaning":"Các tổ chức quốc tế có thể giúp các chính phủ phối hợp ứng phó với các vấn đề môi trường vượt ra ngoài biên giới quốc gia."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_10_3', 'en-b1-10', 'Cách dùng “involved” (adj.) — tham gia; liên quan', 'get involved in  ·  actively involved  ·  an involved process', 'Cụm từ "tham gia vào việc gì" sử dụng be involved in; có thể đặt sau danh từ khi làm định ngữ rút gọn.', 'Họ từ (Word Family): involve (v.), involvement (n.) | Trái nghĩa: uninvolved', '[{"hanzi":"Everyone involved in the picnic brought something to share.","pinyin":"","meaning":"Mọi người tham gia buổi dã ngoại đều mang theo thứ gì đó để chia sẻ."},{"hanzi":"Residents should be actively involved in planning decisions that affect the future of their neighbourhoods.","pinyin":"","meaning":"Cư dân nên tích cực tham gia vào các quyết định quy hoạch ảnh hưởng đến tương lai khu1 neighborhood của họ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_10_4', 'en-b1-10', 'Cách dùng “native” (adj.) — thuộc nơi sinh hoặc tiếng mẹ đẻ', 'native language  ·  native speaker  ·  native species', 'a native of dùng để chỉ người sinh ra ở một nơi nào đó; the natives đôi khi có thể mang hàm ý mỉa mai.', 'Họ từ (Word Family): non-native (adj.) | Trái nghĩa: non-native', '[{"hanzi":"After years abroad, Ravi returned to his native city.","pinyin":"","meaning":"Sau nhiều năm ở nước ngoài, Ravi đã trở về thành phố quê hương của mình."},{"hanzi":"Planting native species in urban gardens can support local wildlife and reduce the need for additional watering.","pinyin":"","meaning":"Việc trồng các loài cây bản địa trong các khu vườn đô thị có thể hỗ trợ động vật hoang dã địa phương và giảm nhu cầu tưới nước bổ sung."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
