INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_10_1_2', 'ten_b1_10_1', 'stolen', 'The police found my stolen bicycle behind a garage.', 'The police found my stolen bicycle behind a garage.', '/ˈstoʊlən/', 'Cảnh sát đã tìm thấy chiếc xe đạp bị trộm của tôi ở phía sau một gara.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_10_1_3', 'ten_b1_10_1', 'poverty', 'The charity helps local families living in poverty.', 'The charity helps local families living in poverty.', '/ˈpɑːvərti/', 'Tổ chức từ thiện này giúp đỡ các gia đình địa phương đang sống trong cảnh nghèo khó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_10_1_4', 'ten_b1_10_1', 'march', 'The band marched through the square in bright uniforms.', 'The band marched through the square in bright uniforms.', '/mɑːrtʃ/', 'Đội kèn trống mặc đồng phục rực rỡ diễu hành qua quảng trường.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_10_1_5', 'ten_b1_10_1', 'affect', 'Too much coffee can affect how well you sleep.', 'Too much coffee can affect how well you sleep.', '/əˈfekt/', 'Uống quá nhiều cà phê có thể ảnh hưởng đến chất lượng giấc ngủ của bạn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_10_1_6', 'ten_b1_10_1', 'advantage', 'Your long arms give you an advantage in swimming.', 'Your long arms give you an advantage in swimming.', '/ədˈvæntɪdʒ/', 'Sải tay dài mang lại cho bạn lợi thế khi bơi lội.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_10_1_7', 'ten_b1_10_1', 'cultural', 'The festival celebrates the town''s rich cultural traditions.', 'The festival celebrates the town''s rich cultural traditions.', '/ˈkʌltʃərəl/', 'Lễ hội này tôn vinh các truyền thống văn hóa phong phú của thị trấn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_10_1_8', 'ten_b1_10_1', 'communication', 'Clear communication helps us share the kitchen without arguments.', 'Clear communication helps us share the kitchen without arguments.', '/kəˌmjuːnɪˈkeɪʃən/', 'Giao tiếp rõ ràng giúp chúng ta cùng sử dụng phòng bếp mà không xảy ra tranh cãi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_10_1_1', 'en-b1-10', 'ten_b1_10_1', 'listening', 'listening', 'Everyone involved in the picnic brought something to share.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Họ vẫn giữ mối quan hệ bạn bè tốt đẹp ngay cả sau khi ly hôn.","Mọi người tham gia buổi dã ngoại đều mang theo thứ gì đó để chia sẻ.","Cảnh sát đã tìm thấy chiếc xe đạp bị trộm của tôi ở phía sau một gara.","Nhà tù cũ đã trở thành một bảo tàng địa phương nổi tiếng."]'::jsonb, 1, 'Everyone involved in the picnic brought something to share. → Mọi người tham gia buổi dã ngoại đều mang theo thứ gì đó để chia sẻ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_10_1_2', 'en-b1-10', 'ten_b1_10_1', 'listening', 'listening', 'The police found my stolen bicycle behind a garage.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tình bạn của chúng tôi bắt đầu từ những ngày ngồi chung một bàn học.","Đội kèn trống mặc đồng phục rực rỡ diễu hành qua quảng trường.","Chú mèo con luồn qua khe hở trên hàng rào.","Cảnh sát đã tìm thấy chiếc xe đạp bị trộm của tôi ở phía sau một gara."]'::jsonb, 3, 'The police found my stolen bicycle behind a garage. → Cảnh sát đã tìm thấy chiếc xe đạp bị trộm của tôi ở phía sau một gara.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_10_1_3', 'en-b1-10', 'ten_b1_10_1', 'listening', 'listening', 'The charity helps local families living in poverty.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tổ chức từ thiện này giúp đỡ các gia đình địa phương đang sống trong cảnh nghèo khó.","Tôi đã gửi lời xin lỗi đến hàng xóm vì tiếng ồn.","Họ lặng lẽ tụ họp vào mỗi buổi sáng để cầu nguyện cho hòa bình.","Tôi đã hoàn thành một bảng khảo sát ngắn về thư viện địa phương của chúng ta."]'::jsonb, 0, 'The charity helps local families living in poverty. → Tổ chức từ thiện này giúp đỡ các gia đình địa phương đang sống trong cảnh nghèo khó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_10_2', 'en-b1-10', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_10_2_1', 'ten_b1_10_2', 'involved', 'Residents should be actively involved in planning decisions that affect the future of their neighbourhoods.', 'Residents should be actively involved in planning decisions that affect the future of their neighbourhoods.', '/ɪnˈvɑːlvd/', 'Cư dân nên tích cực tham gia vào các quyết định quy hoạch ảnh hưởng đến tương lai khu1 neighborhood của họ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_10_2_2', 'ten_b1_10_2', 'stolen', 'Stolen personal data can expose internet users to financial losses, highlighting the importance of effective online security.', 'Stolen personal data can expose internet users to financial losses, highlighting the importance of effective online security.', '/ˈstoʊlən/', 'Dữ liệu cá nhân bị đánh cắp có thể khiến người dùng internet đối mặt với tổn thất tài chính, làm nổi bật tầm quan trọng của bảo mật trực tuyến hiệu quả.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_10_2_3', 'ten_b1_10_2', 'poverty', 'Improving access to education and stable employment can help reduce poverty across both rural and urban communities.', 'Improving access to education and stable employment can help reduce poverty across both rural and urban communities.', '/ˈpɑːvərti/', 'Việc nâng cao khả năng tiếp cận giáo dục và việc làm ổn định có thể góp phần giảm nghèo ở cả vùng nông thôn và thành thị.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_10_2_4', 'ten_b1_10_2', 'march', 'Residents organised a peaceful march to demand safer roads and better public transport in their neighbourhood.', 'Residents organised a peaceful march to demand safer roads and better public transport in their neighbourhood.', '/mɑːrtʃ/', 'Người dân đã tổ chức một cuộc diễu hành ôn hòa nhằm yêu cầu nâng cao an toàn giao thông và cải thiện giao thông công cộng tại khu vực của họ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_10_2_5', 'ten_b1_10_2', 'affect', 'Rising food prices disproportionately affect poorer households, which spend a larger share of their income on essentials.', 'Rising food prices disproportionately affect poorer households, which spend a larger share of their income on essentials.', '/əˈfekt/', 'Giá thực phẩm tăng cao ảnh hưởng không cân xứng đến các hộ gia đình nghèo hơn, những người phải dành phần lớn thu nhập cho các nhu yếu phẩm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_10_2_6', 'ten_b1_10_2', 'advantage', 'One major advantage of public transport is its ability to reduce traffic congestion in urban areas.', 'One major advantage of public transport is its ability to reduce traffic congestion in urban areas.', '/ədˈvæntɪdʒ/', 'Một lợi thế lớn của giao thông công cộng là khả năng giảm thiểu tình trạng ùn tắc giao thông ở các đô thị.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_10_2_1', 'en-b1-10', 'ten_b1_10_2', 'listening', 'listening', 'Residents should be actively involved in planning decisions that affect the future of their neighbourhoods.', NULL, 'Trong câu vừa nghe, từ “involved” mang nghĩa nào sau đây?', '["vận động viên thi đấu môn quyền Anh","tham gia; liên quan","thủy thủ; người đi biển; người chèo thuyền buồm","phòng vệ sinh; nhà vệ sinh"]'::jsonb, 1, '“involved” (/ɪnˈvɑːlvd/): tham gia; liên quan. Câu đầy đủ: Residents should be actively involved in planning decisions that affect the future of their neighbourhoods.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_10_2_2', 'en-b1-10', 'ten_b1_10_2', 'listening', 'listening', 'Stolen personal data can expose internet users to financial losses, highlighting the importance of effective online security.', NULL, 'Trong câu vừa nghe, từ “stolen” mang nghĩa nào sau đây?', '["chộp lấy; vồ lấy; nắm lấy","dựa vào; lệ thuộc vào sự giúp đỡ của ai","bị đánh cắp; bị mất trộm","giao hàng; phân phát"]'::jsonb, 2, '“stolen” (/ˈstoʊlən/): bị đánh cắp; bị mất trộm. Câu đầy đủ: Stolen personal data can expose internet users to financial losses, highlighting the importance of effective online security.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
