INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_2', 'en-b1-10', NULL, 'comprehensive_test', 'listening', 'The police found my stolen bicycle behind a garage.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã hoàn thành một bảng khảo sát ngắn về thư viện địa phương của chúng ta.","Uống quá nhiều cà phê có thể ảnh hưởng đến chất lượng giấc ngủ của bạn.","Đội kèn trống mặc đồng phục rực rỡ diễu hành qua quảng trường.","Cảnh sát đã tìm thấy chiếc xe đạp bị trộm của tôi ở phía sau một gara."]'::jsonb, 3, 'The police found my stolen bicycle behind a garage. → Cảnh sát đã tìm thấy chiếc xe đạp bị trộm của tôi ở phía sau một gara.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_3', 'en-b1-10', NULL, 'comprehensive_test', 'listening', 'poverty', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["định nghĩa; giải thích nghĩa","dịp; lần","sự nghèo đói; cảnh nghèo túng","thang cuốn"]'::jsonb, 2, 'poverty (/ˈpɑːvərti/) → sự nghèo đói; cảnh nghèo túng; sự thiếu thốn; sự bần cùng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_4', 'en-b1-10', NULL, 'comprehensive_test', 'listening', 'The band marched through the square in bright uniforms.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhà tù cũ đã trở thành một bảo tàng địa phương nổi tiếng.","Cô ấy làm tình nguyện viên cho một tổ chức cứu hộ chim bị thương.","Ông bà tôi lần nào cũng kiên quyết trả tiền bữa trưa.","Đội kèn trống mặc đồng phục rực rỡ diễu hành qua quảng trường."]'::jsonb, 3, 'The band marched through the square in bright uniforms. → Đội kèn trống mặc đồng phục rực rỡ diễu hành qua quảng trường.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_5', 'en-b1-10', NULL, 'comprehensive_test', 'listening', 'affect', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["người hầu; người ở","tính cách; cá tính","gây ảnh hưởng; tác động đến","khác biệt; không giống"]'::jsonb, 2, 'affect (/əˈfekt/) → gây ảnh hưởng; tác động đến; làm cho ai đó cảm động; làm ai đó đau buồn', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_6', 'en-b1-10', NULL, 'comprehensive_test', 'listening', 'Your long arms give you an advantage in swimming.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Họ tổ chức một buổi lễ tạ ơn nhỏ sau mùa gặt.","Sải tay dài mang lại cho bạn lợi thế khi bơi lội.","Lễ hội này tôn vinh các truyền thống văn hóa phong phú của thị trấn.","Cảnh sát đã tìm thấy chiếc xe đạp bị trộm của tôi ở phía sau một gara."]'::jsonb, 1, 'Your long arms give you an advantage in swimming. → Sải tay dài mang lại cho bạn lợi thế khi bơi lội.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_7', 'en-b1-10', NULL, 'comprehensive_test', 'listening', 'cultural', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thể lực; sức lực","sản xuất; tạo ra","thuộc về văn hóa; mang tính văn hóa","tư cách thành viên; hội viên"]'::jsonb, 2, 'cultural (/ˈkʌltʃərəl/) → thuộc về văn hóa; mang tính văn hóa; thuộc về nghệ thuật; văn nghệ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_8', 'en-b1-10', NULL, 'comprehensive_test', 'listening', 'Clear communication helps us share the kitchen without arguments.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giao tiếp rõ ràng giúp chúng ta cùng sử dụng phòng bếp mà không xảy ra tranh cãi.","Chú mèo con luồn qua khe hở trên hàng rào.","Sải tay dài mang lại cho bạn lợi thế khi bơi lội.","Đối với ông bà tôi, ngôi nhà cũ này là một biểu tượng của hy vọng."]'::jsonb, 0, 'Clear communication helps us share the kitchen without arguments. → Giao tiếp rõ ràng giúp chúng ta cùng sử dụng phòng bếp mà không xảy ra tranh cãi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_9', 'en-b1-10', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to cause a change in someone or something”?', '["affect","face-to-face","involved","organization"]'::jsonb, 0, 'affect (/əˈfekt/) → gây ảnh hưởng; tác động đến', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
