INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_18', 'en-b1-10', NULL, 'comprehensive_test', 'reading', NULL, 'Residents should be actively involved in planning decisions that affect the future of their neighbourhoods.', 'Dựa vào câu trên, từ “involved” có nghĩa phù hợp nhất là gì?', '["tham gia; liên quan","lớn tiếng; thành tiếng","cơ hội; thời cơ","sai; không chính xác; không đúng"]'::jsonb, 0, 'involved: tham gia; liên quan; phức tạp; rối rắc. Dịch cả câu: Cư dân nên tích cực tham gia vào các quyết định quy hoạch ảnh hưởng đến tương lai khu1 neighborhood của họ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_19', 'en-b1-10', NULL, 'comprehensive_test', 'reading', NULL, 'Stolen personal data can expose internet users to financial losses, highlighting the importance of effective online security.', 'Dựa vào câu trên, từ “stolen” có nghĩa phù hợp nhất là gì?', '["hôn nhân; lễ kết hôn","niềm tin; sự tin tưởng","bị đánh cắp; bị mất trộm","khuyên; khuyên bảo"]'::jsonb, 2, 'stolen: bị đánh cắp; bị mất trộm; đã lấy đi mà không được phép (phân từ quá khứ của steal). Dịch cả câu: Dữ liệu cá nhân bị đánh cắp có thể khiến người dùng internet đối mặt với tổn thất tài chính, làm nổi bật tầm quan trọng của bảo mật trực tuyến hiệu quả.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_20', 'en-b1-10', NULL, 'comprehensive_test', 'reading', NULL, 'Improving access to education and stable employment can help reduce poverty across both rural and urban communities.', 'Dựa vào câu trên, từ “poverty” có nghĩa phù hợp nhất là gì?', '["cân; đo trọng lượng","khối; tảng","sự nghèo đói; cảnh nghèo túng","giới hạn; hạn mức"]'::jsonb, 2, 'poverty: sự nghèo đói; cảnh nghèo túng; sự thiếu thốn; sự bần cùng. Dịch cả câu: Việc nâng cao khả năng tiếp cận giáo dục và việc làm ổn định có thể góp phần giảm nghèo ở cả vùng nông thôn và thành thị.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_21', 'en-b1-10', NULL, 'comprehensive_test', 'reading', NULL, 'Residents organised a peaceful march to demand safer roads and better public transport in their neighbourhood.', 'Dựa vào câu trên, từ “march” có nghĩa phù hợp nhất là gì?', '["chà; xát; cọ xát","máy sấy; thiết bị làm khô","diễu hành; bước đều","khẽ; nhỏ nhẹ"]'::jsonb, 2, 'march: diễu hành; bước đều; cuộc diễu hành; cuộc biểu tình; nhạc hành khúc. Dịch cả câu: Người dân đã tổ chức một cuộc diễu hành ôn hòa nhằm yêu cầu nâng cao an toàn giao thông và cải thiện giao thông công cộng tại khu vực của họ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_22', 'en-b1-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự tạ ơn; lời cầu nguyện cảm ơn”', '["thanksgiving","enjoyable","mixture","rug"]'::jsonb, 0, 'sự tạ ơn; lời cầu nguyện cảm ơn → thanksgiving (/ˌθæŋksˈɡɪvɪŋ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_23', 'en-b1-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tình bạn; mối quan hệ bạn bè”', '["buyer","friendship","medal","trend"]'::jsonb, 1, 'tình bạn; mối quan hệ bạn bè → friendship (/ˈfrendʃɪp/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_10_24', 'en-b1-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngoại hình; vẻ bề ngoài”', '["poisonous","appearance","importance","explanation"]'::jsonb, 1, 'ngoại hình; vẻ bề ngoài → appearance (/əˈpɪrəns/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-11', 'en', 'Bài 11: Xã hội & Cộng đồng (4) - CEFR B1', 'CEFR B1', 'B1 · Xã hội', '25 từ vựng Tiếng Anh CEFR B1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3011, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contest', 'en-b1-11', 'contest', '/ˈkɑːntest/', 'B1', 'cuộc thi; cuộc đấu tranh; tranh cãi; phản đối; tranh giành; tham gia tranh cử', 'n.', 'contestant (n.), contested (adj.), uncontested (adj.)', 'Đồng nghĩa: competition, challenge', 'Danh từ có trọng âm rơi vào âm tiết đầu; động từ có trọng âm rơi vào âm tiết thứ hai.', 'My cousin won a baking contest with her lemon cake.', NULL, 'Em họ tôi đã giành chiến thắng trong một cuộc thi làm bánh với chiếc bánh chanh của mình.', '{"wordId":"contest","ukIpa":"/ˈkɒntest/","usIpa":"/ˈkɑːntest/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"an event or struggle in which people compete to win","vi":"cuộc thi; cuộc đấu tranh"},{"pos":"v.","en":"to formally challenge a decision, claim, or result","vi":"tranh cãi; phản đối"},{"pos":"v.","en":"to compete for a position, prize, or political seat","vi":"tranh giành; tham gia tranh cử"}],"examples":[{"en":"My cousin won a baking contest with her lemon cake.","vi":"Em họ tôi đã giành chiến thắng trong một cuộc thi làm bánh với chiếc bánh chanh của mình.","audioKind":"ex"},{"en":"Citizens should have access to affordable legal advice when they wish to contest an official decision.","vi":"Công dân nên có quyền tiếp cận tư vấn pháp lý với chi phí phải chăng khi họ muốn phản đối một quyết định hành chính.","audioKind":"ex2"}],"collocations":[{"en":"enter a contest","vi":"tham gia cuộc thi"},{"en":"a close contest","vi":"một cuộc tranh tài gay cấn"},{"en":"contest a decision","vi":"phản đối một quyết định"},{"en":"contest an election","vi":"tranh cử một vị trí"}],"wordFamily":["contestant (n.)","contested (adj.)","uncontested (adj.)"],"synonyms":["competition","challenge"],"antonyms":[],"tipVi":"Danh từ có trọng âm rơi vào âm tiết đầu; động từ có trọng âm rơi vào âm tiết thứ hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_host', 'en-b1-11', 'host', '/hoʊst/', 'B1', 'chủ nhà; người dẫn chương trình; tổ chức; làm chủ nhà; dẫn (chương trình); số lượng lớn; một loạt', 'n.', 'hosting (n.), hostess (n.)', 'Trái nghĩa: guest', 'a host of sau đó đi với danh từ số nhiều, biểu thị nghĩa "lượng lớn".', 'Our host welcomed us with warm bread and tea.', NULL, 'Chủ nhà của chúng tôi đã chào đón chúng tôi bằng bánh mì nóng và trà.', '{"wordId":"host","ukIpa":"/həʊst/","usIpa":"/hoʊst/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"someone who welcomes guests or presents a programme or event","vi":"chủ nhà; người dẫn chương trình"},{"pos":"v.","en":"to organise an event, present a programme, or receive guests","vi":"tổ chức; làm chủ nhà; dẫn (chương trình)"},{"pos":"n.","en":"a large number of people or things","vi":"số lượng lớn; một loạt"}],"examples":[{"en":"Our host welcomed us with warm bread and tea.","vi":"Chủ nhà của chúng tôi đã chào đón chúng tôi bằng bánh mì nóng và trà.","audioKind":"ex"},{"en":"Cities that host international sporting events often invest heavily in transport infrastructure and visitor accommodation.","vi":"Các thành phố đăng cai các sự kiện thể thao quốc tế thường đầu tư mạnh mẽ vào cơ sở hạ tầng giao thông và nơi lưu trú cho du khách.","audioKind":"ex2"}],"collocations":[{"en":"host country","vi":"nước chủ nhà"},{"en":"host an event","vi":"tổ chức một sự kiện"},{"en":"a host of problems","vi":"vô số vấn đề"},{"en":"television host","vi":"người dẫn chương trình truyền hình"}],"wordFamily":["hosting (n.)","hostess (n.)"],"synonyms":[],"antonyms":["guest"],"tipVi":"a host of sau đó đi với danh từ số nhiều, biểu thị nghĩa \"lượng lớn\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_role', 'en-b1-11', 'role', '/roʊl/', 'B1', 'chức năng; trách nhiệm; vai diễn', 'n.', NULL, NULL, 'Cụm từ "trong... đóng vai trò" được thể hiện bằng play a role in.', 'My role is to welcome guests at the door.', NULL, 'Vai trò của tôi là chào đón khách ở cửa.', '{"wordId":"role","ukIpa":"/rəʊl/","usIpa":"/roʊl/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"The function or responsibility someone or something has.","vi":"chức năng; trách nhiệm"},{"pos":"n.","en":"A character played by an actor in a performance.","vi":"vai diễn"}],"examples":[{"en":"My role is to welcome guests at the door.","vi":"Vai trò của tôi là chào đón khách ở cửa.","audioKind":"ex"},{"en":"Public libraries play an important role in providing equal access to information and educational resources.","vi":"Các thư viện công cộng đóng vai trò quan trọng trong việc cung cấp khả năng tiếp cận công bằng đối với thông tin và nguồn tài nguyên giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"play a role in","vi":"đóng vai trò trong"},{"en":"a key role","vi":"vai trò chủ chốt"},{"en":"take on a role","vi":"đảm nhận vai trò"},{"en":"a leading role","vi":"vai trò chính"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ \"trong... đóng vai trò\" được thể hiện bằng play a role in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_security', 'en-b1-11', 'security', '/səˈkjʊrəti/', 'B1', 'sự an ninh; sự bảo mật; lực lượng an ninh; nhân viên bảo vệ; sự ổn định; sự bảo đảm', 'n.', 'secure (adj.), secure (v.), securely (adv.), insecurity (n.)', 'Đồng nghĩa: protection, safety · Trái nghĩa: insecurity', 'Security nhấn mạnh vào việc phòng ngừa các mối đe dọa cố ý (tội phạm, xâm nhập); trong khi safety mang nghĩa rộng hơn là sự an toàn nói chung tránh khỏi nguy hiểm.', 'We fitted stronger locks to improve our home security.', NULL, 'Chúng tôi đã lắp đặt những chiếc khóa chắc chắn hơn để nâng cao độ an toàn cho ngôi nhà.', '{"wordId":"security","ukIpa":"/sɪˈkjʊərəti/","usIpa":"/səˈkjʊrəti/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"Protection against danger, crime, loss, or unwanted access","vi":"sự an ninh; sự bảo mật"},{"pos":"n.","en":"People or activities responsible for protecting a place","vi":"lực lượng an ninh; nhân viên bảo vệ"},{"pos":"n.","en":"Freedom from worries about losing money, work, or essential support","vi":"sự ổn định; sự bảo đảm"}],"examples":[{"en":"We fitted stronger locks to improve our home security.","vi":"Chúng tôi đã lắp đặt những chiếc khóa chắc chắn hơn để nâng cao độ an toàn cho ngôi nhà.","audioKind":"ex"},{"en":"Organisations must strengthen data security to protect personal information as more services move online.","vi":"Các tổ chức phải tăng cường bảo mật dữ liệu để bảo vệ thông tin cá nhân khi ngày càng có nhiều dịch vụ chuyển lên nền tảng trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"security measures","vi":"biện pháp an ninh"},{"en":"data security","vi":"bảo mật dữ liệu"},{"en":"job security","vi":"sự ổn định công việc"},{"en":"security guard","vi":"nhân viên bảo vệ"}],"wordFamily":["secure (adj.)","secure (v.)","securely (adv.)","insecurity (n.)"],"synonyms":["protection","safety"],"antonyms":["insecurity"],"tipVi":"Security nhấn mạnh vào việc phòng ngừa các mối đe dọa cố ý (tội phạm, xâm nhập); trong khi safety mang nghĩa rộng hơn là sự an toàn nói chung tránh khỏi nguy hiểm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_culture', 'en-b1-11', 'culture', '/ˈkʌltʃər/', 'B1', 'văn hóa; phong tục tập quán; nghệ thuật; văn hóa nghệ thuật; (sinh học) vi sinh vật nuôi cấy', 'n.', 'cultural (adj.), culturally (adv.), multicultural (adj.), cultured (adj.)', NULL, 'Phân hóa văn hóa nói chung thường không đếm được; có thể dùng cultures để chỉ các nền văn hóa khác nhau.', 'Sharing traditional meals helps children learn about their culture.', NULL, 'Cùng nhau thưởng thức các món ăn truyền thống giúp trẻ em hiểu hơn về nền văn hóa của mình.', '{"wordId":"culture","ukIpa":"/ˈkʌltʃə/","usIpa":"/ˈkʌltʃər/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the shared beliefs, customs and ways of life of a group","vi":"văn hóa; phong tục tập quán"},{"pos":"n.","en":"activities involving art, music, literature and other creative work","vi":"nghệ thuật; văn hóa nghệ thuật"},{"pos":"n.","en":"cells or microorganisms grown under controlled conditions","vi":"(sinh học) vi sinh vật nuôi cấy"}],"examples":[{"en":"Sharing traditional meals helps children learn about their culture.","vi":"Cùng nhau thưởng thức các món ăn truyền thống giúp trẻ em hiểu hơn về nền văn hóa của mình.","audioKind":"ex"},{"en":"Preserving local culture can strengthen community identity while allowing residents to benefit from international exchange.","vi":"Việc bảo tồn văn hóa bản địa có thể củng cố bản sắc cộng đồng, đồng thời giúp người dân hưởng lợi từ giao lưu quốc tế.","audioKind":"ex2"}],"collocations":[{"en":"local culture","vi":"văn hóa địa phương"},{"en":"cultural exchange","vi":"giao lưu văn hóa"},{"en":"popular culture","vi":"văn hóa đại chúng"},{"en":"bacterial culture","vi":"mẫu nuôi cấy vi khuẩn"}],"wordFamily":["cultural (adj.)","culturally (adv.)","multicultural (adj.)","cultured (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Phân hóa văn hóa nói chung thường không đếm được; có thể dùng cultures để chỉ các nền văn hóa khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_personality', 'en-b1-11', 'personality', '/ˌpɜːrsəˈnæləti/', 'B1', 'tính cách; cá tính; sức hút cá nhân; sự quyến rũ; nhân vật nổi tiếng; người nổi tiếng', 'n.', 'person (n.), personal (adj.), personally (adv.)', 'Đồng nghĩa: character', 'Khi chỉ tính cách thì đếm được; have personality mang nghĩa có sức hút cá nhân.', 'Her cheerful personality makes everyone feel welcome at dinner.', NULL, 'Tính cách vui vẻ của cô ấy khiến mọi người đều cảm thấy thoải mái khi dự tiệc tối.', '{"wordId":"personality","ukIpa":"/ˌpɜːsəˈnæləti/","usIpa":"/ˌpɜːrsəˈnæləti/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the qualities that shape how someone thinks, feels, and behaves","vi":"tính cách; cá tính"},{"pos":"n.","en":"lively or appealing qualities that make someone interesting","vi":"sức hút cá nhân; sự quyến rũ"},{"pos":"n.","en":"a well-known person, especially in entertainment or broadcasting","vi":"nhân vật nổi tiếng; người nổi tiếng"}],"examples":[{"en":"Her cheerful personality makes everyone feel welcome at dinner.","vi":"Tính cách vui vẻ của cô ấy khiến mọi người đều cảm thấy thoải mái khi dự tiệc tối.","audioKind":"ex"},{"en":"Schools should recognise that differences in personality can influence how students participate in group activities.","vi":"Các trường học nên nhận thức rằng sự khác biệt về tính cách có thể ảnh hưởng đến cách học sinh tham gia các hoạt động nhóm.","audioKind":"ex2"}],"collocations":[{"en":"outgoing personality","vi":"tính cách hướng ngoại"},{"en":"personality traits","vi":"đặc điểm tính cách"},{"en":"strong personality","vi":"cá tính mạnh mẽ"},{"en":"television personality","vi":"người nổi tiếng trên truyền hình"}],"wordFamily":["person (n.)","personal (adj.)","personally (adv.)"],"synonyms":["character"],"antonyms":[],"tipVi":"Khi chỉ tính cách thì đếm được; have personality mang nghĩa có sức hút cá nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_complaint', 'en-b1-11', 'complaint', '/kəmˈpleɪnt/', 'B1', 'lời phàn nàn; đơn khiếu nại; sự khiếu nại; chứng bệnh; sự khó chịu cơ thể', 'n.', 'complain (v.), complainant (n.)', 'Đồng nghĩa: grievance', 'complaint là danh từ, complain là động từ; phàn nàn về điều gì dùng about.', 'She made a complaint about the cold soup.', NULL, 'Cô ấy đã phàn nàn về việc món súp bị nguội.', '{"wordId":"complaint","ukIpa":"/kəmˈpleɪnt/","usIpa":"/kəmˈpleɪnt/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"a statement that something is wrong or unsatisfactory","vi":"lời phàn nàn; đơn khiếu nại; sự khiếu nại"},{"pos":"n.","en":"an illness or physical problem","vi":"chứng bệnh; sự khó chịu cơ thể"}],"examples":[{"en":"She made a complaint about the cold soup.","vi":"Cô ấy đã phàn nàn về việc món súp bị nguội.","audioKind":"ex"},{"en":"Local authorities should investigate residents'' complaints about noise before approving new entertainment venues in residential areas.","vi":"Chính quyền địa phương nên điều tra các khiếu nại của người dân về tiếng ồn trước khi phê duyệt các địa điểm giải trí mới trong khu dân cư.","audioKind":"ex2"}],"collocations":[{"en":"make a complaint","vi":"khiếu nại"},{"en":"a formal complaint","vi":"đơn khiếu nại chính thức"},{"en":"handle complaints","vi":"giải quyết khiếu nại"},{"en":"a common complaint","vi":"bệnh thông thường; phàn nàn phổ biến"}],"wordFamily":["complain (v.)","complainant (n.)"],"synonyms":["grievance"],"antonyms":[],"tipVi":"complaint là danh từ, complain là động từ; phàn nàn về điều gì dùng about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ceremony', 'en-b1-11', 'ceremony', '/ˈserəmoʊni/', 'B1', 'lễ; nghi lễ; nghi thức; nghi thức xã giao; phép tắc', 'n.', 'ceremonial (adj.), ceremoniously (adv.)', NULL, 'Chỉ một buổi lễ cụ thể thì đếm được; without ceremony nghĩa là không khách sáo, không câu nệ.', 'We attended a small wedding ceremony by the lake.', NULL, 'Chúng tôi tham dự một lễ cưới nhỏ bên bờ hồ.', '{"wordId":"ceremony","ukIpa":"/ˈserəməni/","usIpa":"/ˈserəmoʊni/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A formal event marking an important occasion.","vi":"lễ; nghi lễ; nghi thức"},{"pos":"n.","en":"Formal behaviour required by tradition or social rules.","vi":"nghi thức xã giao; phép tắc"}],"examples":[{"en":"We attended a small wedding ceremony by the lake.","vi":"Chúng tôi tham dự một lễ cưới nhỏ bên bờ hồ.","audioKind":"ex"},{"en":"A graduation ceremony allows students and families to celebrate educational achievements together as a community.","vi":"Lễ tốt nghiệp giúp học sinh và gia đình cùng nhau tôn vinh các thành tựu học tập như một tập thể.","audioKind":"ex2"}],"collocations":[{"en":"opening ceremony","vi":"lễ khai mạc"},{"en":"graduation ceremony","vi":"lễ tốt nghiệp"},{"en":"without ceremony","vi":"không chút câu nệ; tự nhiên"}],"wordFamily":["ceremonial (adj.)","ceremoniously (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ một buổi lễ cụ thể thì đếm được; without ceremony nghĩa là không khách sáo, không câu nệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_influence', 'en-b1-11', 'influence', '/ˈɪnfluəns/', 'B1', 'ảnh hưởng; sức ảnh hưởng; tác động; gây ảnh hưởng', 'n.', 'influential (adj.)', 'Đồng nghĩa: affect, impact', 'Danh từ thường đi với giới từ on; động từ tác động trực tiếp lên tân ngữ.', 'My older sister had a strong influence on me.', NULL, 'Chị gái lớn đã có ảnh hưởng rất lớn đối với tôi.', '{"wordId":"influence","ukIpa":"/ˈɪnfluəns/","usIpa":"/ˈɪnfluəns/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the power to affect how someone thinks or behaves","vi":"ảnh hưởng; sức ảnh hưởng"},{"pos":"v.","en":"to affect someone''s decisions, behaviour, or development","vi":"tác động; gây ảnh hưởng"}],"examples":[{"en":"My older sister had a strong influence on me.","vi":"Chị gái lớn đã có ảnh hưởng rất lớn đối với tôi.","audioKind":"ex"},{"en":"Advertising can influence children''s food preferences, which makes responsible marketing particularly important for public health.","vi":"Quảng cáo có thể tác động đến sở thích ăn uống của trẻ em, điều này khiến cho công tác tiếp thị có trách nhiệm trở nên vô cùng quan trọng đối với sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"have an influence on","vi":"có ảnh hưởng đến"},{"en":"a positive influence","vi":"tác động tích cực"},{"en":"influence a decision","vi":"tác động đến quyết định"}],"wordFamily":["influential (adj.)"],"synonyms":["affect","impact"],"antonyms":[],"tipVi":"Danh từ thường đi với giới từ on; động từ tác động trực tiếp lên tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_membership', 'en-b1-11', 'membership', '/ˈmembɚʃɪp/', 'B1', 'tư cách thành viên; hội viên; tập thể hội viên; số lượng hội viên', 'n.', 'member (n.)', NULL, 'Chỉ tư cách gia nhập một tổ chức nào đó, thường dùng với membership of.', 'My gym membership includes free swimming lessons every weekend.', NULL, 'Thẻ hội viên phòng gym của tôi bao gồm các buổi bơi miễn phí vào mỗi cuối tuần.', '{"wordId":"membership","ukIpa":"/ˈmembəʃɪp/","usIpa":"/ˈmembɚʃɪp/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the status of belonging to a club or organisation","vi":"tư cách thành viên; hội viên"},{"pos":"n.","en":"all members of a group, or the total member count","vi":"tập thể hội viên; số lượng hội viên"}],"examples":[{"en":"My gym membership includes free swimming lessons every weekend.","vi":"Thẻ hội viên phòng gym của tôi bao gồm các buổi bơi miễn phí vào mỗi cuối tuần.","audioKind":"ex"},{"en":"Affordable membership fees can encourage more residents to use local sports facilities and improve their health.","vi":"Mức phí hội viên phải chăng có thể khuyến khích nhiều cư dân sử dụng các cơ sở thể thao địa phương và cải thiện sức khỏe của họ.","audioKind":"ex2"}],"collocations":[{"en":"membership fee","vi":"phí hội viên"},{"en":"annual membership","vi":"tư cách hội viên hằng năm"},{"en":"renew your membership","vi":"gia hạn tư cách hội viên"},{"en":"union membership","vi":"tư cách công đoàn viên"}],"wordFamily":["member (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ tư cách gia nhập một tổ chức nào đó, thường dùng với membership of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_royal', 'en-b1-11', 'royal', '/ˈrɔɪəl/', 'B1', 'hoàng gia; thuộc về nhà vua hoặc hoàng hậu; thành viên hoàng gia', 'adj.', 'royalty (n.), royally (adv.)', NULL, 'royal có nghĩa là thuộc về hoàng gia; cần phân biệt với loyal nghĩa là trung thành, hãy chú ý kỹ chữ cái đầu tiên.', 'We visited the royal palace during our holiday.', NULL, 'Chúng tôi đã tham quan cung điện hoàng gia trong chuyến nghỉ mát.', '{"wordId":"royal","ukIpa":"/ˈrɔɪəl/","usIpa":"/ˈrɔɪəl/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"Relating to a king, queen, or their family.","vi":"hoàng gia; thuộc về nhà vua hoặc hoàng hậu"},{"pos":"n.","en":"A member of a royal family.","vi":"thành viên hoàng gia"}],"examples":[{"en":"We visited the royal palace during our holiday.","vi":"Chúng tôi đã tham quan cung điện hoàng gia trong chuyến nghỉ mát.","audioKind":"ex"},{"en":"Some royal residences are open to visitors, generating income that helps preserve historic buildings.","vi":"Một số dinh thự hoàng gia mở cửa cho du khách, tạo ra nguồn thu giúp bảo tồn các công trình lịch sử.","audioKind":"ex2"}],"collocations":[{"en":"the royal family","vi":"hoàng gia"},{"en":"a royal palace","vi":"cung điện hoàng gia"},{"en":"royal duties","vi":"nhiệm vụ hoàng gia"}],"wordFamily":["royalty (n.)","royally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"royal có nghĩa là thuộc về hoàng gia; cần phân biệt với loyal nghĩa là trung thành, hãy chú ý kỹ chữ cái đầu tiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_get-together', 'en-b1-11', 'get-together', '/ˈɡet təɡeðər/', 'B1', 'buổi tụ họp; buổi liên hoan', 'n.', NULL, 'Đồng nghĩa: gathering, party', 'Danh từ có dấu gạch ngang, trong khi cụm động từ get together thì không.', 'We''re having a small get-together at our flat tonight.', NULL, 'Tối nay chúng tôi sẽ tổ chức một buổi tụ họp nhỏ tại căn hộ của mình.', '{"wordId":"get-together","ukIpa":"/ˈɡet təɡeðə/","usIpa":"/ˈɡet təɡeðər/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"an informal meeting of friends, relatives, or colleagues","vi":"buổi tụ họp; buổi liên hoan"}],"examples":[{"en":"We''re having a small get-together at our flat tonight.","vi":"Tối nay chúng tôi sẽ tổ chức một buổi tụ họp nhỏ tại căn hộ của mình.","audioKind":"ex"},{"en":"A regular neighbourhood get-together can strengthen social ties and help new residents feel more welcome.","vi":"Một buổi tụ họp hàng xóm thường xuyên có thể thắt chặt mối quan hệ xã hội và giúp những cư dân mới cảm thấy được chào đón hơn.","audioKind":"ex2"}],"collocations":[{"en":"family get-together","vi":"buổi tụ họp gia đình"},{"en":"informal get-together","vi":"buổi gặp mặt thân mật"},{"en":"organise a get-together","vi":"tổ chức một buổi tụ họp"}],"wordFamily":[],"synonyms":["gathering","party"],"antonyms":[],"tipVi":"Danh từ có dấu gạch ngang, trong khi cụm động từ get together thì không.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exchange', 'en-b1-11', 'exchange', '/ɪksˈtʃeɪndʒ/', 'B1', 'trao đổi; đổi; sự trao đổi; sự giao lưu; cuộc trao đổi; sở giao dịch; thị trường giao dịch', 'v.', 'exchangeable (adj.)', 'Đồng nghĩa: swap', 'Cấu trúc exchange A for B nghĩa là dùng A đổi lấy B, hãy chú ý dùng giới từ for.', 'Can I exchange this shirt for a smaller size?', NULL, 'Tôi có thể đổi chiếc áo sơ mi này lấy size nhỏ hơn được không?', '{"wordId":"exchange","ukIpa":"/ɪksˈtʃeɪndʒ/","usIpa":"/ɪksˈtʃeɪndʒ/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"to give something and receive something else in return","vi":"trao đổi; đổi"},{"pos":"n.","en":"an act of giving and receiving things, information, or ideas","vi":"sự trao đổi; sự giao lưu; cuộc trao đổi"},{"pos":"n.","en":"a market where shares, currencies, or goods are traded","vi":"sở giao dịch; thị trường giao dịch"}],"examples":[{"en":"Can I exchange this shirt for a smaller size?","vi":"Tôi có thể đổi chiếc áo sơ mi này lấy size nhỏ hơn được không?","audioKind":"ex"},{"en":"International exchange programmes allow students to experience different cultures and develop greater confidence in communicating.","vi":"Các chương trình trao đổi quốc tế giúp học sinh trải nghiệm các nền văn hóa khác nhau và tự tin hơn trong giao tiếp.","audioKind":"ex2"}],"collocations":[{"en":"exchange ideas","vi":"trao đổi ý kiến"},{"en":"exchange rate","vi":"tỷ giá hối đoái"},{"en":"in exchange for","vi":"đổi lại; để đổi lấy"},{"en":"stock exchange","vi":"sở giao dịch chứng khoán"}],"wordFamily":["exchangeable (adj.)"],"synonyms":["swap"],"antonyms":[],"tipVi":"Cấu trúc exchange A for B nghĩa là dùng A đổi lấy B, hãy chú ý dùng giới từ for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sociable', 'en-b1-11', 'sociable', '/ˈsoʊʃəbl/', 'B1', 'hòa đồng; thích giao du; thân thiện', 'adj.', 'sociability (n.), sociably (adv.), unsociable (adj.)', 'Đồng nghĩa: outgoing, gregarious · Trái nghĩa: unsociable', 'sociable chỉ tính cách thích giao tiếp, hòa đồng; còn social thường dùng để chỉ các vấn đề thuộc về xã hội hoặc tính chất xã giao.', 'My sociable neighbour invites everyone over for tea.', NULL, 'Người hàng xóm thân thiện của tôi mời tất cả mọi người sang uống trà.', '{"wordId":"sociable","ukIpa":"/ˈsəʊʃəbl/","usIpa":"/ˈsoʊʃəbl/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"Enjoying meeting people and spending time with them.","vi":"hòa đồng; thích giao du; thân thiện"}],"examples":[{"en":"My sociable neighbour invites everyone over for tea.","vi":"Người hàng xóm thân thiện của tôi mời tất cả mọi người sang uống trà.","audioKind":"ex"},{"en":"Shared spaces can encourage residents to become more sociable and develop stronger relationships with their neighbours.","vi":"Không gian chung có thể khuyến khích cư dân trở nên hòa đồng hơn và xây dựng mối quan hệ gắn kết hơn với những người hàng xóm.","audioKind":"ex2"}],"collocations":[{"en":"a sociable person","vi":"một người hay giao thiệp"},{"en":"a sociable atmosphere","vi":"bầu không khí thân thiện"},{"en":"sociable activities","vi":"các hoạt động giao lưu xã hội"}],"wordFamily":["sociability (n.)","sociably (adv.)","unsociable (adj.)"],"synonyms":["outgoing","gregarious"],"antonyms":["unsociable"],"tipVi":"sociable chỉ tính cách thích giao tiếp, hòa đồng; còn social thường dùng để chỉ các vấn đề thuộc về xã hội hoặc tính chất xã giao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_defend', 'en-b1-11', 'defend', '/dɪˈfend/', 'B1', 'bảo vệ; che chở; bênh vực; biện hộ; bảo vệ quan điểm; phòng thủ', 'v.', 'defence (n.), defender (n.), defensive (adj.), defensible (adj.)', 'Đồng nghĩa: protect, guard · Trái nghĩa: attack', 'defend... against/from... diễn tả việc bảo vệ... khỏi...', 'The mother duck spread her wings to defend her ducklings.', NULL, 'Vịt mẹ xòe cánh bảo vệ đàn con nhỏ của mình.', '{"wordId":"defend","ukIpa":"/dɪˈfend/","usIpa":"/dɪˈfend/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"to protect someone or something from attack or harm","vi":"bảo vệ; che chở"},{"pos":"v.","en":"to give reasons supporting someone or something being criticised","vi":"bênh vực; biện hộ; bảo vệ quan điểm"},{"pos":"v.","en":"to prevent opponents from scoring in a sport","vi":"phòng thủ"}],"examples":[{"en":"The mother duck spread her wings to defend her ducklings.","vi":"Vịt mẹ xòe cánh bảo vệ đàn con nhỏ của mình.","audioKind":"ex"},{"en":"Governments should defend citizens'' rights while ensuring that public safety measures remain fair and proportionate.","vi":"Chính phủ nên bảo vệ các quyền của công dân đồng thời đảm bảo rằng các biện pháp an toàn công cộng vẫn công bằng và hợp lý.","audioKind":"ex2"}],"collocations":[{"en":"defend against attack","vi":"chống lại sự tấn công"},{"en":"defend human rights","vi":"bảo vệ nhân quyền"},{"en":"defend a decision","vi":"bênh vực một quyết định"},{"en":"defend a title","vi":"bảo vệ ngôi vô địch"}],"wordFamily":["defence (n.)","defender (n.)","defensive (adj.)","defensible (adj.)"],"synonyms":["protect","guard"],"antonyms":["attack"],"tipVi":"defend... against/from... diễn tả việc bảo vệ... khỏi...","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_emergency', 'en-b1-11', 'emergency', '/ɪˈmɝːdʒənsi/', 'B1', 'tình trạng khẩn cấp; trường hợp cấp bách', 'n.', NULL, 'Đồng nghĩa: crisis', 'Là danh từ đếm được; emergency exit có danh từ đứng trước làm bổ ngữ.', 'Keep a torch nearby in case of an emergency.', NULL, 'Hãy để sẵn một chiếc đèn pin gần đó để phòng khi có trường hợp khẩn cấp.', '{"wordId":"emergency","ukIpa":"/ɪˈmɜːdʒənsi/","usIpa":"/ɪˈmɝːdʒənsi/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A serious, unexpected situation requiring immediate action.","vi":"tình trạng khẩn cấp; trường hợp cấp bách"}],"examples":[{"en":"Keep a torch nearby in case of an emergency.","vi":"Hãy để sẵn một chiếc đèn pin gần đó để phòng khi có trường hợp khẩn cấp.","audioKind":"ex"},{"en":"Governments should invest in emergency services to ensure that communities receive rapid assistance during natural disasters.","vi":"Chính phủ nên đầu tư vào các dịch vụ cứu hộ khẩn cấp để đảm bảo các cộng đồng nhận được sự hỗ trợ nhanh chóng trong các thảm họa tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"in an emergency","vi":"trong trường hợp khẩn cấp"},{"en":"emergency services","vi":"các dịch vụ khẩn cấp"},{"en":"emergency evacuation","vi":"sự sơ tán khẩn cấp"},{"en":"a state of emergency","vi":"tình trạng khẩn cấp"}],"wordFamily":[],"synonyms":["crisis"],"antonyms":[],"tipVi":"Là danh từ đếm được; emergency exit có danh từ đứng trước làm bổ ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obey', 'en-b1-11', 'obey', '/əˈbeɪ/', 'B1', 'tuân theo; vâng lời; chấp hành', 'v.', 'obedience (n.), obedient (adj.), obediently (adv.), disobey (v.)', 'Trái nghĩa: disobey', 'Động từ obey đi trực tiếp với tân ngữ chỉ người, mệnh lệnh hoặc quy tắc mà không cần giới từ to: obey the law.', 'Our dog will obey simple commands for a treat.', NULL, 'Con chó của chúng tôi sẽ vâng lời các hiệu lệnh đơn giản để đổi lấy phần thưởng là đồ ăn.', '{"wordId":"obey","ukIpa":"/əˈbeɪ/","usIpa":"/əˈbeɪ/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"to do what someone orders or what a rule requires","vi":"tuân theo; vâng lời; chấp hành"}],"examples":[{"en":"Our dog will obey simple commands for a treat.","vi":"Con chó của chúng tôi sẽ vâng lời các hiệu lệnh đơn giản để đổi lấy phần thưởng là đồ ăn.","audioKind":"ex"},{"en":"Drivers who obey speed limits help protect pedestrians and reduce the risk of serious accidents.","vi":"Những tài xế tuân thủ quy định tốc độ giúp bảo vệ người đi bộ và giảm nguy cơ xảy ra tai nạn nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"obey orders","vi":"tuân lệnh"},{"en":"obey the law","vi":"tuân thủ pháp luật"},{"en":"obey instructions","vi":"tuân theo hướng dẫn"}],"wordFamily":["obedience (n.)","obedient (adj.)","obediently (adv.)","disobey (v.)"],"synonyms":[],"antonyms":["disobey"],"tipVi":"Động từ obey đi trực tiếp với tân ngữ chỉ người, mệnh lệnh hoặc quy tắc mà không cần giới từ to: obey the law.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attack', 'en-b1-11', 'attack', '/əˈtæk/', 'B1', 'tấn công; chỉ trích gay gắt; sự tấn công; sự chỉ trích; cơn phát bệnh; cơn đau bất chợt', 'v.', 'attacker (n.)', 'Đồng nghĩa: assault', 'Động từ trực tiếp đi với tân ngữ; danh từ thường dùng an attack on.', 'The goose attacked my bag when I approached the pond.', NULL, 'Con ngỗng lao vào mổ túi của tôi khi tôi đến gần ao.', '{"wordId":"attack","ukIpa":"/əˈtæk/","usIpa":"/əˈtæk/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"Try to hurt someone or criticize something strongly","vi":"tấn công; chỉ trích gay gắt"},{"pos":"n.","en":"An act of violence or strong criticism","vi":"sự tấn công; sự chỉ trích"},{"pos":"n.","en":"A sudden period of illness or severe symptoms","vi":"cơn phát bệnh; cơn đau bất chợt"}],"examples":[{"en":"The goose attacked my bag when I approached the pond.","vi":"Con ngỗng lao vào mổ túi của tôi khi tôi đến gần ao.","audioKind":"ex"},{"en":"Critics attacked the proposal because it offered little support for families living in poverty.","vi":"Giới phê bình đã chỉ trích gay gắt đề xuất này vì nó hầu như không hỗ trợ gì cho các gia đình sống trong cảnh nghèo khó.","audioKind":"ex2"}],"collocations":[{"en":"come under attack","vi":"bị tấn công hoặc chỉ trích"},{"en":"heart attack","vi":"cơn đau tim"},{"en":"attack a proposal","vi":"tấn công một đề xuất"}],"wordFamily":["attacker (n.)"],"synonyms":["assault"],"antonyms":[],"tipVi":"Động từ trực tiếp đi với tân ngữ; danh từ thường dùng an attack on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_state', 'en-b1-11', 'state', '/steɪt/', 'B1', 'trạng thái; tình trạng; quốc gia; tiểu bang; nhà nước; tuyên bố; phát biểu rõ ràng', 'n.', 'statement (n.), statehood (n.)', NULL, 'state đóng vai trò động từ có tính trang trọng cao, thường đi với mệnh đề that; danh từ có thể chỉ trạng thái hoặc quốc gia/tiểu bang.', 'The kitchen was in a terrible state after dinner.', NULL, 'Căn bếp trông thật tồi tàn và bừa bộn sau bữa tối.', '{"wordId":"state","ukIpa":"/steɪt/","usIpa":"/steɪt/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the condition of someone or something at a particular time","vi":"trạng thái; tình trạng"},{"pos":"n.","en":"a country, its government, or a region within a country","vi":"quốc gia; tiểu bang; nhà nước"},{"pos":"v.","en":"to express something clearly in speech or writing","vi":"tuyên bố; phát biểu rõ ràng"}],"examples":[{"en":"The kitchen was in a terrible state after dinner.","vi":"Căn bếp trông thật tồi tàn và bừa bộn sau bữa tối.","audioKind":"ex"},{"en":"The report states that reliable public transport is essential for reducing dependence on private cars.","vi":"Bản báo cáo nêu rõ rằng hệ thống giao thông công cộng đáng tin cậy là điều cốt yếu để giảm bớt sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"in a good state","vi":"ở trong trạng thái tốt"},{"en":"state of mind","vi":"tâm trạng; trạng thái tinh thần"},{"en":"state funding","vi":"nguồn tài trợ từ nhà nước"},{"en":"state clearly","vi":"nêu rõ; khẳng định rõ ràng"}],"wordFamily":["statement (n.)","statehood (n.)"],"synonyms":[],"antonyms":[],"tipVi":"state đóng vai trò động từ có tính trang trọng cao, thường đi với mệnh đề that; danh từ có thể chỉ trạng thái hoặc quốc gia/tiểu bang.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_promote', 'en-b1-11', 'promote', '/prəˈmoʊt/', 'B1', 'thúc đẩy; khuyến khích; đề cao; thăng chức; thăng cấp; quảng bá; quảng cáo; tiếp thị', 'v.', 'promotion (n.), promotional (adj.), promoter (n.)', 'Đồng nghĩa: encourage, advance · Trái nghĩa: demote', 'Được thăng chức lên một vị trí cụ thể dùng be promoted to + chức vụ.', 'Our local club promotes cycling through free weekend rides.', NULL, 'Câu lạc bộ địa phương của chúng tôi thúc đẩy phong trào đạp xe thông qua các chuyến đi dã ngoại cuối tuần miễn phí.', '{"wordId":"promote","ukIpa":"/prəˈməʊt/","usIpa":"/prəˈmoʊt/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"to encourage something to develop or become more widely accepted","vi":"thúc đẩy; khuyến khích; đề cao"},{"pos":"v.","en":"to give someone a higher position at work","vi":"thăng chức; thăng cấp"},{"pos":"v.","en":"to attract attention to something to increase interest or sales","vi":"quảng bá; quảng cáo; tiếp thị"}],"examples":[{"en":"Our local club promotes cycling through free weekend rides.","vi":"Câu lạc bộ địa phương của chúng tôi thúc đẩy phong trào đạp xe thông qua các chuyến đi dã ngoại cuối tuần miễn phí.","audioKind":"ex"},{"en":"Schools can promote healthier lifestyles by providing nutritious meals and encouraging students to take regular exercise.","vi":"Các trường học có thể thúc đẩy lối sống lành mạnh hơn bằng cách cung cấp các bữa ăn đủ dinh dưỡng và khuyến khích học sinh tập thể dục thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"promote economic growth","vi":"thúc đẩy tăng trưởng kinh tế"},{"en":"promote awareness","vi":"nâng cao nhận thức"},{"en":"be promoted to manager","vi":"được thăng chức làm quản lý"},{"en":"promote a product","vi":"quảng bá sản phẩm"}],"wordFamily":["promotion (n.)","promotional (adj.)","promoter (n.)"],"synonyms":["encourage","advance"],"antonyms":["demote"],"tipVi":"Được thăng chức lên một vị trí cụ thể dùng be promoted to + chức vụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_burglar', 'en-b1-11', 'burglar', '/ˈbɝːɡlər/', 'B1', 'kẻ trộm đột nhập; kẻ gian', 'n.', 'burglary (n.), burgle (v.)', NULL, 'burglar chỉ kẻ đột nhập trộm cắp; robber thường chỉ kẻ cướp dùng vũ lực hoặc đe dọa.', 'A burglar climbed through the window while everyone was away.', NULL, 'Một tên trộm đã leo qua cửa sổ khi mọi người đều đi vắng.', '{"wordId":"burglar","ukIpa":"/ˈbɜːɡlə/","usIpa":"/ˈbɝːɡlər/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"someone who enters a building illegally to steal things","vi":"kẻ trộm đột nhập; kẻ gian"}],"examples":[{"en":"A burglar climbed through the window while everyone was away.","vi":"Một tên trộm đã leo qua cửa sổ khi mọi người đều đi vắng.","audioKind":"ex"},{"en":"Improved street lighting and secure doors may discourage burglars from targeting homes in residential areas.","vi":"Cải thiện hệ thống chiếu sáng đường phố và cửa ra vào kiên cố có thể ngăn chặn kẻ gian nhắm mục tiêu vào các ngôi nhà trong khu dân cư.","audioKind":"ex2"}],"collocations":[{"en":"burglar alarm","vi":"chuông báo động chống trộm"},{"en":"deter burglars","vi":"ngăn chặn kẻ trộm đột nhập"},{"en":"catch a burglar","vi":"bắt kẻ trộm"}],"wordFamily":["burglary (n.)","burgle (v.)"],"synonyms":[],"antonyms":[],"tipVi":"burglar chỉ kẻ đột nhập trộm cắp; robber thường chỉ kẻ cướp dùng vũ lực hoặc đe dọa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_caring', 'en-b1-11', 'caring', '/ˈkerɪŋ/', 'B1', 'chu đáo; ân cần; hay quan tâm đến người khác; công tác chăm sóc; công việc điều dưỡng', 'adj.', 'care (v.), care (n.), careful (adj.), careless (adj.)', 'Đồng nghĩa: kind, compassionate, considerate · Trái nghĩa: uncaring', 'Caring chỉ sự quan tâm đến người khác; careful chỉ tính cẩn thận trong công việc.', 'Our caring neighbour brought soup when I was ill.', NULL, 'Người hàng xóm chu đáo của chúng tôi đã mang súp sang khi tôi bị ốm.', '{"wordId":"caring","ukIpa":"/ˈkeərɪŋ/","usIpa":"/ˈkerɪŋ/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"kind and concerned about other people''s needs","vi":"chu đáo; ân cần; hay quan tâm đến người khác"},{"pos":"n.","en":"the work of looking after people who need help","vi":"công tác chăm sóc; công việc điều dưỡng"}],"examples":[{"en":"Our caring neighbour brought soup when I was ill.","vi":"Người hàng xóm chu đáo của chúng tôi đã mang súp sang khi tôi bị ốm.","audioKind":"ex"},{"en":"A caring school environment can improve children''s confidence and encourage them to seek help when needed.","vi":"Một môi trường học đường đầy sự quan tâm chăm sóc có thể nâng cao sự tự tin của trẻ em và khích lệ các em tìm kiếm sự giúp đỡ khi cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"a caring attitude","vi":"thái độ quan tâm"},{"en":"a caring profession","vi":"ngành nghề chăm sóc"},{"en":"a caring environment","vi":"môi trường đầy tình thương"}],"wordFamily":["care (v.)","care (n.)","careful (adj.)","careless (adj.)"],"synonyms":["kind","compassionate","considerate"],"antonyms":["uncaring"],"tipVi":"Caring chỉ sự quan tâm đến người khác; careful chỉ tính cẩn thận trong công việc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compliment', 'en-b1-11', 'compliment', '/ˈkɑːmplɪmənt/', 'B1', 'lời khen ngợi; sự ca tụng; khen ngợi; tán dương', 'n.', 'complimentary (adj.)', 'Đồng nghĩa: praise · Trái nghĩa: insult', 'Compliment là lời khen; còn complement nghĩa là phần bù, sự bổ sung cho hoàn thiện.', 'Her compliment about my cooking made me smile.', NULL, 'Lời khen của cô ấy về món ăn do tôi nấu khiến tôi mỉm cười.', '{"wordId":"compliment","ukIpa":"/ˈkɒmplɪmənt/","usIpa":"/ˈkɑːmplɪmənt/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A remark expressing admiration or approval.","vi":"lời khen ngợi; sự ca tụng"},{"pos":"v.","en":"To tell someone that you admire something about them.","vi":"khen ngợi; tán dương"}],"examples":[{"en":"Her compliment about my cooking made me smile.","vi":"Lời khen của cô ấy về món ăn do tôi nấu khiến tôi mỉm cười.","audioKind":"ex"},{"en":"Teachers who compliment students on specific improvements can strengthen motivation and encourage continued effort.","vi":"Giáo viên khen ngợi học sinh về những tiến bộ cụ thể có thể củng cố động lực và khuyến khích các em tiếp tục nỗ lực.","audioKind":"ex2"}],"collocations":[{"en":"pay someone a compliment","vi":"khen ngợi ai đó"},{"en":"compliment someone on something","vi":"khen ai về việc gì"},{"en":"accept a compliment","vi":"nhận lời khen"},{"en":"a sincere compliment","vi":"lời khen chân thành"}],"wordFamily":["complimentary (adj.)"],"synonyms":["praise"],"antonyms":["insult"],"tipVi":"Compliment là lời khen; còn complement nghĩa là phần bù, sự bổ sung cho hoàn thiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_power', 'en-b1-11', 'power', '/ˈpaʊər/', 'B1', 'quyền lực; sức ảnh hưởng; năng lượng; điện năng; cung cấp năng lượng; phát điện', 'n.', 'powerful (adj.), powerless (adj.), powerfully (adv.)', NULL, 'Diễn đạt có quyền làm gì dùng have the power to do.', 'The manager has the power to change our shifts.', NULL, 'Người quản lý có quyền thay đổi ca làm việc của chúng tôi.', '{"wordId":"power","ukIpa":"/ˈpaʊə/","usIpa":"/ˈpaʊər/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"The ability or authority to control people, events, or decisions.","vi":"quyền lực; sức ảnh hưởng"},{"pos":"n.","en":"Energy used to make machines and equipment work.","vi":"năng lượng; điện năng"},{"pos":"v.","en":"To supply energy that makes something work.","vi":"cung cấp năng lượng; phát điện"}],"examples":[{"en":"The manager has the power to change our shifts.","vi":"Người quản lý có quyền thay đổi ca làm việc của chúng tôi.","audioKind":"ex"},{"en":"Solar panels can power rural schools while reducing their dependence on expensive and unreliable fuel supplies.","vi":"Các tấm pin mặt trời có thể cung cấp điện cho các trường học vùng sâu vùng xa đồng thời giảm sự phụ thuộc vào nguồn nhiên liệu đắt đỏ và kém ổn định.","audioKind":"ex2"}],"collocations":[{"en":"political power","vi":"quyền lực chính trị"},{"en":"renewable power","vi":"năng lượng tái tạo"},{"en":"power supply","vi":"nguồn điện; hệ thống cung cấp điện"},{"en":"the power to decide","vi":"quyền quyết định"}],"wordFamily":["powerful (adj.)","powerless (adj.)","powerfully (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Diễn đạt có quyền làm gì dùng have the power to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_misunderstand', 'en-b1-11', 'misunderstand', '/ˌmɪsʌndərˈstænd/', 'B1', 'hiểu lầm; hiểu sai', 'v.', 'misunderstanding (n.), understand (v.), understanding (n.)', 'Đồng nghĩa: misinterpret, misread · Trái nghĩa: understand', 'Dạng quá khứ và quá khứ phân từ đều là misunderstood.', 'Please don''t misunderstand me; I really want to help.', NULL, 'Xin đừng hiểu lầm tôi; tôi thực sự muốn giúp đỡ.', '{"wordId":"misunderstand","ukIpa":"/ˌmɪsʌndəˈstænd/","usIpa":"/ˌmɪsʌndərˈstænd/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"to understand someone''s words, actions, or intentions incorrectly","vi":"hiểu lầm; hiểu sai"}],"examples":[{"en":"Please don''t misunderstand me; I really want to help.","vi":"Xin đừng hiểu lầm tôi; tôi thực sự muốn giúp đỡ.","audioKind":"ex"},{"en":"Patients may misunderstand medical advice when professionals use technical language rather than clear explanations suited to their audience.","vi":"Bệnh nhân có thể hiểu sai lời khuyên y tế khi các chuyên gia sử dụng thuật ngữ chuyên môn thay vì giải thích rõ ràng, dễ hiểu đối với người nghe.","audioKind":"ex2"}],"collocations":[{"en":"misunderstand instructions","vi":"hiểu lầm hướng dẫn"},{"en":"misunderstand someone''s intentions","vi":"hiểu sai ý định của ai đó"},{"en":"easily misunderstood","vi":"dễ bị hiểu lầm"}],"wordFamily":["misunderstanding (n.)","understand (v.)","understanding (n.)"],"synonyms":["misinterpret","misread"],"antonyms":["understand"],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là misunderstood.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_11_1', 'en-b1-11', 'Cách dùng “security” (n.) — sự an ninh; sự bảo mật', 'security measures  ·  data security  ·  job security', 'Security nhấn mạnh vào việc phòng ngừa các mối đe dọa cố ý (tội phạm, xâm nhập); trong khi safety mang nghĩa rộng hơn là sự an toàn nói chung tránh khỏi nguy hiểm.', 'Họ từ (Word Family): secure (adj.), secure (v.), securely (adv.), insecurity (n.) | Đồng nghĩa: protection, safety · Trái nghĩa: insecurity', '[{"hanzi":"We fitted stronger locks to improve our home security.","pinyin":"","meaning":"Chúng tôi đã lắp đặt những chiếc khóa chắc chắn hơn để nâng cao độ an toàn cho ngôi nhà."},{"hanzi":"Organisations must strengthen data security to protect personal information as more services move online.","pinyin":"","meaning":"Các tổ chức phải tăng cường bảo mật dữ liệu để bảo vệ thông tin cá nhân khi ngày càng có nhiều dịch vụ chuyển lên nền tảng trực tuyến."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_11_2', 'en-b1-11', 'Cách dùng “state” (n.) — trạng thái; tình trạng', 'in a good state  ·  state of mind  ·  state funding', 'state đóng vai trò động từ có tính trang trọng cao, thường đi với mệnh đề that; danh từ có thể chỉ trạng thái hoặc quốc gia/tiểu bang.', 'Họ từ (Word Family): statement (n.), statehood (n.)', '[{"hanzi":"The kitchen was in a terrible state after dinner.","pinyin":"","meaning":"Căn bếp trông thật tồi tàn và bừa bộn sau bữa tối."},{"hanzi":"The report states that reliable public transport is essential for reducing dependence on private cars.","pinyin":"","meaning":"Bản báo cáo nêu rõ rằng hệ thống giao thông công cộng đáng tin cậy là điều cốt yếu để giảm bớt sự phụ thuộc vào ô tô cá nhân."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_11_3', 'en-b1-11', 'Cách dùng “sociable” (adj.) — hòa đồng; thích giao du; thân thiện', 'a sociable person  ·  a sociable atmosphere  ·  sociable activities', 'sociable chỉ tính cách thích giao tiếp, hòa đồng; còn social thường dùng để chỉ các vấn đề thuộc về xã hội hoặc tính chất xã giao.', 'Họ từ (Word Family): sociability (n.), sociably (adv.), unsociable (adj.) | Đồng nghĩa: outgoing, gregarious · Trái nghĩa: unsociable', '[{"hanzi":"My sociable neighbour invites everyone over for tea.","pinyin":"","meaning":"Người hàng xóm thân thiện của tôi mời tất cả mọi người sang uống trà."},{"hanzi":"Shared spaces can encourage residents to become more sociable and develop stronger relationships with their neighbours.","pinyin":"","meaning":"Không gian chung có thể khuyến khích cư dân trở nên hòa đồng hơn và xây dựng mối quan hệ gắn kết hơn với những người hàng xóm."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_11_4', 'en-b1-11', 'Cách dùng “royal” (adj.) — hoàng gia; thuộc về nhà vua hoặc hoàng hậu', 'the royal family  ·  a royal palace  ·  royal duties', 'royal có nghĩa là thuộc về hoàng gia; cần phân biệt với loyal nghĩa là trung thành, hãy chú ý kỹ chữ cái đầu tiên.', 'Họ từ (Word Family): royalty (n.), royally (adv.)', '[{"hanzi":"We visited the royal palace during our holiday.","pinyin":"","meaning":"Chúng tôi đã tham quan cung điện hoàng gia trong chuyến nghỉ mát."},{"hanzi":"Some royal residences are open to visitors, generating income that helps preserve historic buildings.","pinyin":"","meaning":"Một số dinh thự hoàng gia mở cửa cho du khách, tạo ra nguồn thu giúp bảo tồn các công trình lịch sử."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_11_1', 'en-b1-11', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
