INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_11_1_2', 'ten_b1_11_1', 'host', 'Our host welcomed us with warm bread and tea.', 'Our host welcomed us with warm bread and tea.', '/hoʊst/', 'Chủ nhà của chúng tôi đã chào đón chúng tôi bằng bánh mì nóng và trà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_11_1_3', 'ten_b1_11_1', 'role', 'My role is to welcome guests at the door.', 'My role is to welcome guests at the door.', '/roʊl/', 'Vai trò của tôi là chào đón khách ở cửa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_11_1_4', 'ten_b1_11_1', 'security', 'We fitted stronger locks to improve our home security.', 'We fitted stronger locks to improve our home security.', '/səˈkjʊrəti/', 'Chúng tôi đã lắp đặt những chiếc khóa chắc chắn hơn để nâng cao độ an toàn cho ngôi nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_11_1_5', 'ten_b1_11_1', 'culture', 'Sharing traditional meals helps children learn about their culture.', 'Sharing traditional meals helps children learn about their culture.', '/ˈkʌltʃər/', 'Cùng nhau thưởng thức các món ăn truyền thống giúp trẻ em hiểu hơn về nền văn hóa của mình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_11_1_6', 'ten_b1_11_1', 'personality', 'Her cheerful personality makes everyone feel welcome at dinner.', 'Her cheerful personality makes everyone feel welcome at dinner.', '/ˌpɜːrsəˈnæləti/', 'Tính cách vui vẻ của cô ấy khiến mọi người đều cảm thấy thoải mái khi dự tiệc tối.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_11_1_7', 'ten_b1_11_1', 'complaint', 'She made a complaint about the cold soup.', 'She made a complaint about the cold soup.', '/kəmˈpleɪnt/', 'Cô ấy đã phàn nàn về việc món súp bị nguội.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_11_1_8', 'ten_b1_11_1', 'ceremony', 'We attended a small wedding ceremony by the lake.', 'We attended a small wedding ceremony by the lake.', '/ˈserəmoʊni/', 'Chúng tôi tham dự một lễ cưới nhỏ bên bờ hồ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_11_1_1', 'en-b1-11', 'ten_b1_11_1', 'listening', 'listening', 'My cousin won a baking contest with her lemon cake.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Em họ tôi đã giành chiến thắng trong một cuộc thi làm bánh với chiếc bánh chanh của mình.","Thẻ hội viên phòng gym của tôi bao gồm các buổi bơi miễn phí vào mỗi cuối tuần.","Tối nay chúng tôi sẽ tổ chức một buổi tụ họp nhỏ tại căn hộ của mình.","Người hàng xóm thân thiện của tôi mời tất cả mọi người sang uống trà."]'::jsonb, 0, 'My cousin won a baking contest with her lemon cake. → Em họ tôi đã giành chiến thắng trong một cuộc thi làm bánh với chiếc bánh chanh của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_11_1_2', 'en-b1-11', 'ten_b1_11_1', 'listening', 'listening', 'Our host welcomed us with warm bread and tea.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Câu lạc bộ địa phương của chúng tôi thúc đẩy phong trào đạp xe thông qua các chuyến đi dã ngoại cuối tuần miễn phí.","Chủ nhà của chúng tôi đã chào đón chúng tôi bằng bánh mì nóng và trà.","Người hàng xóm thân thiện của tôi mời tất cả mọi người sang uống trà.","Chị gái lớn đã có ảnh hưởng rất lớn đối với tôi."]'::jsonb, 1, 'Our host welcomed us with warm bread and tea. → Chủ nhà của chúng tôi đã chào đón chúng tôi bằng bánh mì nóng và trà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_11_1_3', 'en-b1-11', 'ten_b1_11_1', 'listening', 'listening', 'My role is to welcome guests at the door.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Vịt mẹ xòe cánh bảo vệ đàn con nhỏ của mình.","Con ngỗng lao vào mổ túi của tôi khi tôi đến gần ao.","Hãy để sẵn một chiếc đèn pin gần đó để phòng khi có trường hợp khẩn cấp.","Vai trò của tôi là chào đón khách ở cửa."]'::jsonb, 3, 'My role is to welcome guests at the door. → Vai trò của tôi là chào đón khách ở cửa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_11_2', 'en-b1-11', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_11_2_1', 'ten_b1_11_2', 'contest', 'Citizens should have access to affordable legal advice when they wish to contest an official decision.', 'Citizens should have access to affordable legal advice when they wish to contest an official decision.', '/ˈkɑːntest/', 'Công dân nên có quyền tiếp cận tư vấn pháp lý với chi phí phải chăng khi họ muốn phản đối một quyết định hành chính.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_11_2_2', 'ten_b1_11_2', 'host', 'Cities that host international sporting events often invest heavily in transport infrastructure and visitor accommodation.', 'Cities that host international sporting events often invest heavily in transport infrastructure and visitor accommodation.', '/hoʊst/', 'Các thành phố đăng cai các sự kiện thể thao quốc tế thường đầu tư mạnh mẽ vào cơ sở hạ tầng giao thông và nơi lưu trú cho du khách.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_11_2_3', 'ten_b1_11_2', 'role', 'Public libraries play an important role in providing equal access to information and educational resources.', 'Public libraries play an important role in providing equal access to information and educational resources.', '/roʊl/', 'Các thư viện công cộng đóng vai trò quan trọng trong việc cung cấp khả năng tiếp cận công bằng đối với thông tin và nguồn tài nguyên giáo dục.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_11_2_4', 'ten_b1_11_2', 'security', 'Organisations must strengthen data security to protect personal information as more services move online.', 'Organisations must strengthen data security to protect personal information as more services move online.', '/səˈkjʊrəti/', 'Các tổ chức phải tăng cường bảo mật dữ liệu để bảo vệ thông tin cá nhân khi ngày càng có nhiều dịch vụ chuyển lên nền tảng trực tuyến.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_11_2_5', 'ten_b1_11_2', 'culture', 'Preserving local culture can strengthen community identity while allowing residents to benefit from international exchange.', 'Preserving local culture can strengthen community identity while allowing residents to benefit from international exchange.', '/ˈkʌltʃər/', 'Việc bảo tồn văn hóa bản địa có thể củng cố bản sắc cộng đồng, đồng thời giúp người dân hưởng lợi từ giao lưu quốc tế.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_11_2_6', 'ten_b1_11_2', 'personality', 'Schools should recognise that differences in personality can influence how students participate in group activities.', 'Schools should recognise that differences in personality can influence how students participate in group activities.', '/ˌpɜːrsəˈnæləti/', 'Các trường học nên nhận thức rằng sự khác biệt về tính cách có thể ảnh hưởng đến cách học sinh tham gia các hoạt động nhóm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_11_2_1', 'en-b1-11', 'ten_b1_11_2', 'listening', 'listening', 'Citizens should have access to affordable legal advice when they wish to contest an official decision.', NULL, 'Trong câu vừa nghe, từ “contest” mang nghĩa nào sau đây?', '["người biểu diễn; nghệ sĩ biểu diễn","xuất thân; nền tảng gia đình, học vấn và kinh nghiệm định hình cuộc đời ai đó","bình minh; lúc mặt trời mọc","cuộc thi; cuộc đấu tranh"]'::jsonb, 3, '“contest” (/ˈkɑːntest/): cuộc thi; cuộc đấu tranh. Câu đầy đủ: Citizens should have access to affordable legal advice when they wish to contest an official decision.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_11_2_2', 'en-b1-11', 'ten_b1_11_2', 'listening', 'listening', 'Cities that host international sporting events often invest heavily in transport infrastructure and visitor accommodation.', NULL, 'Trong câu vừa nghe, từ “host” mang nghĩa nào sau đây?', '["thường xuyên; hay xảy ra","ấm cúng; dễ chịu","chủ nhà; người dẫn chương trình","tài năng; khiếu"]'::jsonb, 2, '“host” (/hoʊst/): chủ nhà; người dẫn chương trình. Câu đầy đủ: Cities that host international sporting events often invest heavily in transport infrastructure and visitor accommodation.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
