INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_11_2', 'en-b1-11', NULL, 'comprehensive_test', 'listening', 'Our host welcomed us with warm bread and tea.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cùng nhau thưởng thức các món ăn truyền thống giúp trẻ em hiểu hơn về nền văn hóa của mình.","Tôi có thể đổi chiếc áo sơ mi này lấy size nhỏ hơn được không?","Vịt mẹ xòe cánh bảo vệ đàn con nhỏ của mình.","Chủ nhà của chúng tôi đã chào đón chúng tôi bằng bánh mì nóng và trà."]'::jsonb, 3, 'Our host welcomed us with warm bread and tea. → Chủ nhà của chúng tôi đã chào đón chúng tôi bằng bánh mì nóng và trà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
