INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_11_4', 'en-b1-11', NULL, 'comprehensive_test', 'listening', 'We fitted stronger locks to improve our home security.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người hàng xóm thân thiện của tôi mời tất cả mọi người sang uống trà.","Em họ tôi đã giành chiến thắng trong một cuộc thi làm bánh với chiếc bánh chanh của mình.","Chúng tôi đã lắp đặt những chiếc khóa chắc chắn hơn để nâng cao độ an toàn cho ngôi nhà.","Người quản lý có quyền thay đổi ca làm việc của chúng tôi."]'::jsonb, 2, 'We fitted stronger locks to improve our home security. → Chúng tôi đã lắp đặt những chiếc khóa chắc chắn hơn để nâng cao độ an toàn cho ngôi nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_11_5', 'en-b1-11', NULL, 'comprehensive_test', 'listening', 'culture', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chị dâu; em dâu; chị chồng; em chồng; chị vợ; em vợ","phù hợp; thích hợp","văn hóa; phong tục tập quán","thật vậy; quả thực"]'::jsonb, 2, 'culture (/ˈkʌltʃər/) → văn hóa; phong tục tập quán; nghệ thuật; văn hóa nghệ thuật; (sinh học) vi sinh vật nuôi cấy', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_11_6', 'en-b1-11', NULL, 'comprehensive_test', 'listening', 'Her cheerful personality makes everyone feel welcome at dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xin đừng hiểu lầm tôi; tôi thực sự muốn giúp đỡ.","Tính cách vui vẻ của cô ấy khiến mọi người đều cảm thấy thoải mái khi dự tiệc tối.","Chúng tôi tham dự một lễ cưới nhỏ bên bờ hồ.","Vịt mẹ xòe cánh bảo vệ đàn con nhỏ của mình."]'::jsonb, 1, 'Her cheerful personality makes everyone feel welcome at dinner. → Tính cách vui vẻ của cô ấy khiến mọi người đều cảm thấy thoải mái khi dự tiệc tối.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_11_7', 'en-b1-11', NULL, 'comprehensive_test', 'listening', 'complaint', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ở dưới; bên dưới","khí hậu","lời phàn nàn; đơn khiếu nại; sự khiếu nại","thu hút; hấp dẫn sự quan tâm"]'::jsonb, 2, 'complaint (/kəmˈpleɪnt/) → lời phàn nàn; đơn khiếu nại; sự khiếu nại; chứng bệnh; sự khó chịu cơ thể', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_11_8', 'en-b1-11', NULL, 'comprehensive_test', 'listening', 'We attended a small wedding ceremony by the lake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi tham dự một lễ cưới nhỏ bên bờ hồ.","Con chó của chúng tôi sẽ vâng lời các hiệu lệnh đơn giản để đổi lấy phần thưởng là đồ ăn.","Người hàng xóm chu đáo của chúng tôi đã mang súp sang khi tôi bị ốm.","Người quản lý có quyền thay đổi ca làm việc của chúng tôi."]'::jsonb, 0, 'We attended a small wedding ceremony by the lake. → Chúng tôi tham dự một lễ cưới nhỏ bên bờ hồ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
