INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_11_18', 'en-b1-11', NULL, 'comprehensive_test', 'reading', NULL, 'Citizens should have access to affordable legal advice when they wish to contest an official decision.', 'Dựa vào câu trên, từ “contest” có nghĩa phù hợp nhất là gì?', '["nơi làm việc; môi trường công sở","cuộc thi; cuộc đấu tranh","thị thực; visa","đã ký; có chữ ký"]'::jsonb, 1, 'contest: cuộc thi; cuộc đấu tranh; tranh cãi; phản đối; tranh giành; tham gia tranh cử. Dịch cả câu: Công dân nên có quyền tiếp cận tư vấn pháp lý với chi phí phải chăng khi họ muốn phản đối một quyết định hành chính.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_11_19', 'en-b1-11', NULL, 'comprehensive_test', 'reading', NULL, 'Cities that host international sporting events often invest heavily in transport infrastructure and visitor accommodation.', 'Dựa vào câu trên, từ “host” có nghĩa phù hợp nhất là gì?', '["thảm họa; tai họa gây tổn thất lớn","người trông trẻ tạm thời","làm mệt mỏi; căng thẳng; mệt nhọc","chủ nhà; người dẫn chương trình"]'::jsonb, 3, 'host: chủ nhà; người dẫn chương trình; tổ chức; làm chủ nhà; dẫn (chương trình); số lượng lớn; một loạt. Dịch cả câu: Các thành phố đăng cai các sự kiện thể thao quốc tế thường đầu tư mạnh mẽ vào cơ sở hạ tầng giao thông và nơi lưu trú cho du khách.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_11_20', 'en-b1-11', NULL, 'comprehensive_test', 'reading', NULL, 'Public libraries play an important role in providing equal access to information and educational resources.', 'Dựa vào câu trên, từ “role” có nghĩa phù hợp nhất là gì?', '["chức năng; trách nhiệm","sự dũng cảm; lòng can đảm","động tác chống đẩy; hít đất","gửi một tài liệu hoặc đơn từ để được xem xét; nộp; trình"]'::jsonb, 0, 'role: chức năng; trách nhiệm; vai diễn. Dịch cả câu: Các thư viện công cộng đóng vai trò quan trọng trong việc cung cấp khả năng tiếp cận công bằng đối với thông tin và nguồn tài nguyên giáo dục.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_11_21', 'en-b1-11', NULL, 'comprehensive_test', 'reading', NULL, 'Organisations must strengthen data security to protect personal information as more services move online.', 'Dựa vào câu trên, từ “security” có nghĩa phù hợp nhất là gì?', '["hít thở; thở","nhà nghỉ giá rẻ; ký túc xá cho khách du lịch","sự an ninh; sự bảo mật","thuyết phục; khuyên nhủ"]'::jsonb, 2, 'security: sự an ninh; sự bảo mật; lực lượng an ninh; nhân viên bảo vệ; sự ổn định; sự bảo đảm. Dịch cả câu: Các tổ chức phải tăng cường bảo mật dữ liệu để bảo vệ thông tin cá nhân khi ngày càng có nhiều dịch vụ chuyển lên nền tảng trực tuyến.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
