INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_11_24', 'en-b1-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hiểu lầm; hiểu sai”', '["misunderstand","rob","instant","length"]'::jsonb, 0, 'hiểu lầm; hiểu sai → misunderstand (/ˌmɪsʌndərˈstænd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-12', 'en', 'Bài 12: Xã hội & Cộng đồng (5) - CEFR B1', 'CEFR B1', 'B1 · Xã hội', '25 từ vựng Tiếng Anh CEFR B1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3012, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_movement', 'en-b1-12', 'movement', '/ˈmuːvmənt/', 'B1', 'sự chuyển động; động tác; phong trào xã hội; chương nhạc', 'n.', 'move (v.), movable (adj.), moving (adj.)', 'Đồng nghĩa: motion · Trái nghĩa: stillness', 'Khi chỉ hành động cụ thể hoặc phong trào xã hội thì đếm được; khi chỉ sự di chuyển nói chung thì không đếm được.', 'A sudden movement in the bushes caught my attention.', NULL, 'Một cử động bất ngờ trong bụi cây đã thu hút sự chú ý của tôi.', '{"wordId":"movement","ukIpa":"/ˈmuːvmənt/","usIpa":"/ˈmuːvmənt/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"an act of changing position or moving the body","vi":"sự chuyển động; động tác"},{"pos":"n.","en":"an organised effort by people seeking shared social change","vi":"phong trào xã hội"},{"pos":"n.","en":"one main section of a long piece of music","vi":"chương nhạc"}],"examples":[{"en":"A sudden movement in the bushes caught my attention.","vi":"Một cử động bất ngờ trong bụi cây đã thu hút sự chú ý của tôi.","audioKind":"ex"},{"en":"The environmental movement has encouraged governments to adopt stronger policies on waste reduction and renewable energy.","vi":"Phong trào bảo vệ môi trường đã khuyến khích các chính phủ áp dụng các chính sách mạnh mẽ hơn về giảm thiểu rác thải và năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"freedom of movement","vi":"quyền tự do đi lại"},{"en":"sudden movement","vi":"chuyển động đột ngột"},{"en":"environmental movement","vi":"phong trào môi trường"},{"en":"social movement","vi":"phong trào xã hội"}],"wordFamily":["move (v.)","movable (adj.)","moving (adj.)"],"synonyms":["motion"],"antonyms":["stillness"],"tipVi":"Khi chỉ hành động cụ thể hoặc phong trào xã hội thì đếm được; khi chỉ sự di chuyển nói chung thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_celebration', 'en-b1-12', 'celebration', '/ˌseləˈbreɪʃən/', 'B1', 'lễ kỷ niệm; sự kiện ăn mừng; việc ăn mừng; sự kỷ niệm', 'n.', 'celebrate (v.), celebratory (adj.)', 'Đồng nghĩa: festivity', 'Danh từ đếm được khi chỉ sự kiện cụ thể, không đếm được khi chỉ hành động ăn mừng.', 'We decorated the garden for our grandparents'' anniversary celebration.', NULL, 'Chúng tôi đã trang trí khu vườn cho lễ kỷ niệm ngày cưới của ông bà.', '{"wordId":"celebration","ukIpa":"/ˌselɪˈbreɪʃən/","usIpa":"/ˌseləˈbreɪʃən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A special event held to mark a happy occasion.","vi":"lễ kỷ niệm; sự kiện ăn mừng"},{"pos":"n.","en":"The act of showing happiness about something special.","vi":"việc ăn mừng; sự kỷ niệm"}],"examples":[{"en":"We decorated the garden for our grandparents'' anniversary celebration.","vi":"Chúng tôi đã trang trí khu vườn cho lễ kỷ niệm ngày cưới của ông bà.","audioKind":"ex"},{"en":"Community celebrations can strengthen social bonds by bringing together residents from different cultural backgrounds.","vi":"Các hoạt động kỷ niệm cộng đồng có thể thắt chặt tình đoàn kết xã hội bằng cách kết nối cư dân từ các nền văn hóa khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"hold a celebration","vi":"tổ chức lễ kỷ niệm"},{"en":"in celebration of","vi":"để ăn mừng..."},{"en":"birthday celebration","vi":"tiệc mừng sinh nhật"}],"wordFamily":["celebrate (v.)","celebratory (adj.)"],"synonyms":["festivity"],"antonyms":[],"tipVi":"Danh từ đếm được khi chỉ sự kiện cụ thể, không đếm được khi chỉ hành động ăn mừng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unfriendly', 'en-b1-12', 'unfriendly', '/ʌnˈfrendli/', 'B1', 'không thân thiện; lạnh lùng; không thuận lợi; khó sử dụng', 'adj.', 'friendly (adj.), friendliness (n.), unfriendliness (n.)', 'Đồng nghĩa: unwelcoming, cold · Trái nghĩa: friendly, welcoming', 'Mặc dù tận cùng bằng -ly, từ này thường là tính từ chứ không phải phó từ.', 'The new neighbour seemed unfriendly but was simply shy.', NULL, 'Người hàng xóm mới có vẻ lạnh lùng nhưng thực ra chỉ là người hay ngại ngùng.', '{"wordId":"unfriendly","ukIpa":"/ʌnˈfrendli/","usIpa":"/ʌnˈfrendli/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"not kind or welcoming towards others","vi":"không thân thiện; lạnh lùng"},{"pos":"adj.","en":"making an activity difficult or causing harm","vi":"không thuận lợi; khó sử dụng"}],"examples":[{"en":"The new neighbour seemed unfriendly but was simply shy.","vi":"Người hàng xóm mới có vẻ lạnh lùng nhưng thực ra chỉ là người hay ngại ngùng.","audioKind":"ex"},{"en":"An unfriendly working environment can discourage employees from sharing ideas and seeking support.","vi":"Môi trường làm việc không thân thiện có thể khiến nhân viên nản lòng trong việc chia sẻ ý tưởng và tìm kiếm sự hỗ trợ.","audioKind":"ex2"}],"collocations":[{"en":"unfriendly atmosphere","vi":"bầuok không khí lạnh lẽo"},{"en":"unfriendly attitude","vi":"thái độ không thân thiện"},{"en":"environmentally unfriendly","vi":"gây hại cho môi trường"}],"wordFamily":["friendly (adj.)","friendliness (n.)","unfriendliness (n.)"],"synonyms":["unwelcoming","cold"],"antonyms":["friendly","welcoming"],"tipVi":"Mặc dù tận cùng bằng -ly, từ này thường là tính từ chứ không phải phó từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bride', 'en-b1-12', 'bride', '/braɪd/', 'B1', 'cô dâu', 'n.', 'bridal (adj.)', NULL, '"Bride" chỉ cô dâu, còn "groom" chỉ chú rể.', 'The bride held fresh flowers as she entered the garden.', NULL, 'Cô dâu tay cầm hoa tươi bước vào khu vườn.', '{"wordId":"bride","ukIpa":"/braɪd/","usIpa":"/braɪd/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A woman who is getting married or has just married.","vi":"cô dâu"}],"examples":[{"en":"The bride held fresh flowers as she entered the garden.","vi":"Cô dâu tay cầm hoa tươi bước vào khu vườn.","audioKind":"ex"},{"en":"In many cultures, the bride and her family share responsibility for organising the wedding celebration.","vi":"Trong nhiều nền văn hóa, cô dâu và gia đình cô ấy cùng chia sẻ trách nhiệm tổ chức lễ cưới.","audioKind":"ex2"}],"collocations":[{"en":"bride and groom","vi":"cô dâu và chú rể"},{"en":"a beautiful bride","vi":"một cô dâu xinh đẹp"},{"en":"a bride-to-be","vi":"cô dâu tương lai"}],"wordFamily":["bridal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"Bride\" chỉ cô dâu, còn \"groom\" chỉ chú rể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_agreement', 'en-b1-12', 'agreement', '/əˈɡriːmənt/', 'B1', 'thỏa thuận; hiệp định; sự đồng ý; sự tán thành; sự tương hợp về mặt ngữ pháp', 'n.', 'agree (v.), disagree (v.), disagreement (n.), agreeable (adj.)', 'Đồng nghĩa: accord · Trái nghĩa: disagreement', 'Thỏa thuận cụ thể là danh từ đếm được; biểu thị sự đồng thuận thường là không đếm được.', 'We reached an agreement about sharing the kitchen.', NULL, 'Chúng tôi đã đạt được thỏa thuận về việc dùng chung nhà bếp.', '{"wordId":"agreement","ukIpa":"/əˈɡriːmənt/","usIpa":"/əˈɡriːmənt/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"an arrangement accepted by two or more people or groups","vi":"thỏa thuận; hiệp định"},{"pos":"n.","en":"the state of sharing an opinion or accepting a proposal","vi":"sự đồng ý; sự tán thành"},{"pos":"n.","en":"a grammatical match between related words in a sentence","vi":"sự tương hợp về mặt ngữ pháp"}],"examples":[{"en":"We reached an agreement about sharing the kitchen.","vi":"Chúng tôi đã đạt được thỏa thuận về việc dùng chung nhà bếp.","audioKind":"ex"},{"en":"International agreements on carbon emissions are more effective when participating countries establish clear targets and monitor progress.","vi":"Các hiệp định quốc tế về lượng khí thải carbon sẽ hiệu quả hơn khi các quốc gia tham gia thiết lập các mục tiêu rõ ràng và giám sát tiến độ.","audioKind":"ex2"}],"collocations":[{"en":"reach an agreement","vi":"đạt được thỏa thuận"},{"en":"sign an agreement","vi":"ký kết thỏa thuận"},{"en":"be in agreement","vi":"đồng tình với nhau"},{"en":"subject–verb agreement","vi":"sự hòa hợp giữa chủ ngữ và động từ"}],"wordFamily":["agree (v.)","disagree (v.)","disagreement (n.)","agreeable (adj.)"],"synonyms":["accord"],"antonyms":["disagreement"],"tipVi":"Thỏa thuận cụ thể là danh từ đếm được; biểu thị sự đồng thuận thường là không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_religion', 'en-b1-12', 'religion', '/rɪˈlɪdʒən/', 'B1', 'tôn giáo; tín ngưỡng', 'n.', 'religious (adj), religiously (adv)', 'Đồng nghĩa: faith', 'Dùng ở dạng không đếm được khi chỉ tôn giáo nói chung; đếm được khi chỉ một tôn giáo cụ thể.', 'We learned about different religions at school today.', NULL, 'Hôm nay chúng tôi đã học về các tôn giáo khác nhau ở trường.', '{"wordId":"religion","ukIpa":"/rɪˈlɪdʒən/","usIpa":"/rɪˈlɪdʒən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"belief in gods or spiritual powers, with related practices","vi":"tôn giáo; tín ngưỡng"}],"examples":[{"en":"We learned about different religions at school today.","vi":"Hôm nay chúng tôi đã học về các tôn giáo khác nhau ở trường.","audioKind":"ex"},{"en":"Schools can teach students about religion while encouraging respect for people with different beliefs.","vi":"Nhà trường có thể dạy học sinh về tôn giáo đồng thời khuyến khích sự tôn trọng đối với những người có niềm tin khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"freedom of religion","vi":"tự do tôn giáo"},{"en":"organised religion","vi":"tôn giáo có tổ chức"},{"en":"religious beliefs","vi":"niềm tin tôn giáo"}],"wordFamily":["religious (adj)","religiously (adv)"],"synonyms":["faith"],"antonyms":[],"tipVi":"Dùng ở dạng không đếm được khi chỉ tôn giáo nói chung; đếm được khi chỉ một tôn giáo cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_widely', 'en-b1-12', 'widely', '/ˈwaɪdli/', 'B1', 'rộng rãi; phổ biến; khác biệt nhiều', 'adv.', 'wide (adj.), widen (v.), width (n.)', 'Đồng nghĩa: extensively, broadly', 'widely chỉ phạm vi rộng lớn; wide còn có thể diễn tả trạng thái mở rộng hoàn toàn.', 'This fruit is widely available in local shops.', NULL, 'Loại trái cây này được bày bán rộng rãi ở các cửa hàng địa phương.', '{"wordId":"widely","ukIpa":"/ˈwaɪdli/","usIpa":"/ˈwaɪdli/","cefr":"B1","topic":"society","senses":[{"pos":"adv.","en":"Across many places or among many people","vi":"rộng rãi; phổ biến"},{"pos":"adv.","en":"With a large difference between people, things, or situations","vi":"khác biệt nhiều"}],"examples":[{"en":"This fruit is widely available in local shops.","vi":"Loại trái cây này được bày bán rộng rãi ở các cửa hàng địa phương.","audioKind":"ex"},{"en":"Although online learning is widely accepted, access to reliable internet connections still varies considerably between regions.","vi":"Mặc dù việc học trực tuyến đã được chấp nhận rộng rãi, điều kiện tiếp cận kết nối internet ổn định vẫn có sự khác biệt lớn giữa các vùng miền.","audioKind":"ex2"}],"collocations":[{"en":"widely available","vi":"có sẵn rộng rãi"},{"en":"widely used","vi":"được sử dụng rộng rãi"},{"en":"widely accepted","vi":"được chấp nhận rộng rãi"},{"en":"vary widely","vi":"khác biệt đáng kể"}],"wordFamily":["wide (adj.)","widen (v.)","width (n.)"],"synonyms":["extensively","broadly"],"antonyms":[],"tipVi":"widely chỉ phạm vi rộng lớn; wide còn có thể diễn tả trạng thái mở rộng hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unkind', 'en-b1-12', 'unkind', '/ˌʌnˈkaɪnd/', 'B1', 'tàn nhẫn; khắc nghiệt; thiếu tử tế', 'adj.', 'kind (adj.), kindness (n.), unkindness (n.), unkindly (adv.)', 'Đồng nghĩa: mean, hurtful · Trái nghĩa: kind, considerate', 'Biểu đạt "đối xử không thân thiện/tệ với ai" dùng be unkind to someone.', 'It was unkind to laugh at his first drawing.', NULL, 'Thật là tàn nhẫn khi chế nhạo bức vẽ đầu tiên của cậu ấy.', '{"wordId":"unkind","ukIpa":"/ˌʌnˈkaɪnd/","usIpa":"/ˌʌnˈkaɪnd/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"not caring about others'' feelings or treating them kindly","vi":"tàn nhẫn; khắc nghiệt; thiếu tử tế"}],"examples":[{"en":"It was unkind to laugh at his first drawing.","vi":"Thật là tàn nhẫn khi chế nhạo bức vẽ đầu tiên của cậu ấy.","audioKind":"ex"},{"en":"Schools should teach children how unkind comments online can affect the emotional wellbeing of their classmates.","vi":"Các trường học nên dạy học sinh hiểu rằng những lời bình luận cay nghiệt trên mạng có thể ảnh hưởng đến sức khỏe tinh thần của các bạn cùng lớp như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"unkind remarks","vi":"lời nói cay nghiệt"},{"en":"be unkind to someone","vi":"đối xử tệ với ai đó"},{"en":"unkind behaviour","vi":"hành vi thiếu tử tế"}],"wordFamily":["kind (adj.)","kindness (n.)","unkindness (n.)","unkindly (adv.)"],"synonyms":["mean","hurtful"],"antonyms":["kind","considerate"],"tipVi":"Biểu đạt \"đối xử không thân thiện/tệ với ai\" dùng be unkind to someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_acceptable', 'en-b1-12', 'acceptable', '/əkˈseptəbl/', 'B1', 'có thể chấp nhận được; đạt yêu cầu', 'adj.', 'accept (v.), acceptance (n.), unacceptable (adj.), acceptability (n.)', 'Đồng nghĩa: satisfactory, adequate · Trái nghĩa: unacceptable', 'acceptable thể hiện việc đạt mức yêu cầu, không đồng nghĩa với mức xuất sắc.', 'These shoes are acceptable for work, but trainers aren''t.', NULL, 'Đôi giày này phù hợp để đi làm, nhưng giày thể thao thì không.', '{"wordId":"acceptable","ukIpa":"/əkˈseptəbl/","usIpa":"/əkˈseptəbl/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"good enough or suitable to be allowed or approved","vi":"có thể chấp nhận được; đạt yêu cầu"}],"examples":[{"en":"These shoes are acceptable for work, but trainers aren''t.","vi":"Đôi giày này phù hợp để đi làm, nhưng giày thể thao thì không.","audioKind":"ex"},{"en":"Governments must establish acceptable limits for industrial emissions to protect public health and nearby ecosystems.","vi":"Chính phủ phải thiết lập các giới hạn có thể chấp nhận được đối với lượng khí thải công nghiệp nhằm bảo vệ sức khỏe cộng đồng và các hệ sinh thái xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"acceptable standard","vi":"tiêu chuẩn chấp nhận được"},{"en":"socially acceptable","vi":"được xã hội chấp nhận"},{"en":"acceptable to everyone","vi":"được mọi người chấp nhận"}],"wordFamily":["accept (v.)","acceptance (n.)","unacceptable (adj.)","acceptability (n.)"],"synonyms":["satisfactory","adequate"],"antonyms":["unacceptable"],"tipVi":"acceptable thể hiện việc đạt mức yêu cầu, không đồng nghĩa với mức xuất sắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_priest', 'en-b1-12', 'priest', '/priːst/', 'B1', 'linh mục; thầy tu', 'n.', 'priesthood (n.), priestly (adj.)', 'Đồng nghĩa: cleric', 'Không phải tất cả tu sĩ đều gọi là priest; tu sĩ Phật giáo thường gọi là monk.', 'The priest welcomed everyone as they entered the church.', NULL, 'Linh mục chào đón mọi người khi họ bước vào nhà thờ.', '{"wordId":"priest","ukIpa":"/priːst/","usIpa":"/priːst/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"a person authorised to perform religious ceremonies","vi":"linh mục; thầy tu"}],"examples":[{"en":"The priest welcomed everyone as they entered the church.","vi":"Linh mục chào đón mọi người khi họ bước vào nhà thờ.","audioKind":"ex"},{"en":"In many communities, a priest provides emotional support and helps organise assistance for families in need.","vi":"Ở nhiều cộng đồng, linh mục mang lại sự hỗ trợ tinh thần và giúp tổ chức cứu trợ cho các gia đình có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"a parish priest","vi":"linh mục giáo xứ"},{"en":"a Catholic priest","vi":"linh mục công giáo"},{"en":"be ordained a priest","vi":"được phong chức linh mục"}],"wordFamily":["priesthood (n.)","priestly (adj.)"],"synonyms":["cleric"],"antonyms":[],"tipVi":"Không phải tất cả tu sĩ đều gọi là priest; tu sĩ Phật giáo thường gọi là monk.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marriage', 'en-b1-12', 'marriage', '/ˈmærɪdʒ/', 'B1', 'hôn nhân; lễ kết hôn; sự kết hợp chặt chẽ', 'n.', 'marry (v.), married (adj.), unmarried (adj.)', 'Đồng nghĩa: matrimony', 'marriage chỉ mối quan hệ hôn nhân; wedding chủ yếu chỉ lễ cưới.', 'Their marriage grew stronger as they learned to listen.', NULL, 'Mối quan hệ hôn nhân của họ ngày càng bền chặt hơn khi họ học cách lắng nghe nhau.', '{"wordId":"marriage","ukIpa":"/ˈmærɪdʒ/","usIpa":"/ˈmærɪdʒ/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the legally or socially recognised relationship between two spouses","vi":"hôn nhân; lễ kết hôn"},{"pos":"n.","en":"a successful combination of different things","vi":"sự kết hợp chặt chẽ"}],"examples":[{"en":"Their marriage grew stronger as they learned to listen.","vi":"Mối quan hệ hôn nhân của họ ngày càng bền chặt hơn khi họ học cách lắng nghe nhau.","audioKind":"ex"},{"en":"Changing attitudes towards marriage have influenced household structures and housing demand in many societies.","vi":"Thái độ thay đổi đối với hôn nhân đã ảnh hưởng đến cấu trúc hộ gia đình và nhu cầu nhà ở trong nhiều xã hội.","audioKind":"ex2"}],"collocations":[{"en":"a happy marriage","vi":"một cuộc hôn nhân hạnh phúc"},{"en":"marriage certificate","vi":"giấy đăng ký kết hôn"},{"en":"marriage ceremony","vi":"lễ cưới"},{"en":"marriage to someone","vi":"cuộc hôn nhân với ai đó"}],"wordFamily":["marry (v.)","married (adj.)","unmarried (adj.)"],"synonyms":["matrimony"],"antonyms":[],"tipVi":"marriage chỉ mối quan hệ hôn nhân; wedding chủ yếu chỉ lễ cưới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_persuade', 'en-b1-12', 'persuade', '/pərˈsweɪd/', 'B1', 'thuyết phục; khuyên nhủ; làm cho tin; làm cho tin tưởng', 'v.', 'persuasion (n.), persuasive (adj.), persuasively (adv.)', 'Đồng nghĩa: convince · Trái nghĩa: dissuade', '"persuade sb to do" nhấn mạnh việc khuyên nhủ thành công, không chỉ là đưa ra gợi ý.', 'I persuaded my brother to join our walking group.', NULL, 'Tôi đã thuyết phục anh trai tham gia nhóm đi bộ của chúng tôi.', '{"wordId":"persuade","ukIpa":"/pəˈsweɪd/","usIpa":"/pərˈsweɪd/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"To get someone to do something by giving reasons","vi":"thuyết phục; khuyên nhủ"},{"pos":"v.","en":"To make someone believe something is true","vi":"làm cho tin; làm cho tin tưởng"}],"examples":[{"en":"I persuaded my brother to join our walking group.","vi":"Tôi đã thuyết phục anh trai tham gia nhóm đi bộ của chúng tôi.","audioKind":"ex"},{"en":"Public health campaigns can persuade people to adopt healthier habits by explaining the benefits in accessible language.","vi":"Các chiến dịch y tế công cộng có thể thuyết phục mọi người áp dụng các thói quen lành mạnh hơn bằng cách giải thích lợi ích bằng ngôn ngữ dễ hiểu.","audioKind":"ex2"}],"collocations":[{"en":"persuade someone to do something","vi":"thuyết phục ai làm điều gì"},{"en":"persuade someone of something","vi":"làm cho ai tin điều gì"},{"en":"hard to persuade","vi":"khó thuyết phục"}],"wordFamily":["persuasion (n.)","persuasive (adj.)","persuasively (adv.)"],"synonyms":["convince"],"antonyms":["dissuade"],"tipVi":"\"persuade sb to do\" nhấn mạnh việc khuyên nhủ thành công, không chỉ là đưa ra gợi ý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_generation', 'en-b1-12', 'generation', '/ˌdʒenəˈreɪʃən/', 'B1', 'thế hệ; sự phát điện; sự tạo ra; thế hệ sản phẩm; thế hệ công nghệ', 'n.', 'generate (v.), generator (n.), generational (adj.)', NULL, 'Khi mang nghĩa "thế hệ" thì đếm được; khi mang nghĩa "sự tạo ra" thì thường không đếm được.', 'Three generations of our family gathered for dinner yesterday.', NULL, 'Ba thế hệ trong gia đình chúng tôi đã quây quần bên nhau ăn tối ngày hôm qua.', '{"wordId":"generation","ukIpa":"/ˌdʒenəˈreɪʃən/","usIpa":"/ˌdʒenəˈreɪʃən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"people born and living at roughly the same time","vi":"thế hệ"},{"pos":"n.","en":"the process of producing something, especially electricity","vi":"sự phát điện; sự tạo ra"},{"pos":"n.","en":"a stage in the development of a product or technology","vi":"thế hệ sản phẩm; thế hệ công nghệ"}],"examples":[{"en":"Three generations of our family gathered for dinner yesterday.","vi":"Ba thế hệ trong gia đình chúng tôi đã quây quần bên nhau ăn tối ngày hôm qua.","audioKind":"ex"},{"en":"Each generation faces different challenges as technological progress changes the skills required in the workplace.","vi":"Mỗi thế hệ đều phải đối mặt với những thử thách khác nhau khi tiến bộ công nghệ thay đổi các kỹ năng cần thiết trong môi trường làm việc.","audioKind":"ex2"}],"collocations":[{"en":"future generations","vi":"các thế hệ tương lai"},{"en":"generation gap","vi":"khoảng cách thế hệ"},{"en":"electricity generation","vi":"sự phát điện"},{"en":"younger generation","vi":"thế hệ trẻ"}],"wordFamily":["generate (v.)","generator (n.)","generational (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa \"thế hệ\" thì đếm được; khi mang nghĩa \"sự tạo ra\" thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crime', 'en-b1-12', 'crime', '/kraɪm/', 'B1', 'tội phạm; tệ nạn tội phạm; tội ác; hành vi phạm tội', 'n.', 'criminal (n.), criminal (adj.), criminality (n.)', NULL, 'Chỉ tệ nạn tội phạm nói chung thì không đếm được; chỉ hành vi phạm tội cụ thể thì đếm được, chẳng hạn như commit a crime.', 'Better street lighting has helped reduce crime here.', NULL, 'Hệ thống đèn đường tốt hơn đã giúp giảm thiểu tình trạng tội phạm ở đây.', '{"wordId":"crime","ukIpa":"/kraɪm/","usIpa":"/kraɪm/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"illegal activities considered as a whole","vi":"tội phạm; tệ nạn tội phạm"},{"pos":"n.","en":"an action that breaks the law","vi":"tội ác; hành vi phạm tội"}],"examples":[{"en":"Better street lighting has helped reduce crime here.","vi":"Hệ thống đèn đường tốt hơn đã giúp giảm thiểu tình trạng tội phạm ở đây.","audioKind":"ex"},{"en":"Investment in education and employment opportunities may reduce crime more effectively than increasingly severe punishments.","vi":"Việc đầu tư vào giáo dục và cơ hội việc làm có thể làm giảm tội phạm hiệu quả hơn so với các hình phạt ngày càng nghiêm khắc.","audioKind":"ex2"}],"collocations":[{"en":"commit a crime","vi":"phạm tội"},{"en":"prevent crime","vi":"phòng chống tội phạm"},{"en":"crime rate","vi":"tỷ lệ tội phạm"},{"en":"violent crime","vi":"tội phạm bạo lực"}],"wordFamily":["criminal (n.)","criminal (adj.)","criminality (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ tệ nạn tội phạm nói chung thì không đếm được; chỉ hành vi phạm tội cụ thể thì đếm được, chẳng hạn như commit a crime.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_honestly', 'en-b1-12', 'honestly', '/ˈɑːnɪstli/', 'B1', 'một cách thành thật; trung thực; thành thật mà nói; thực sự', 'adv.', 'honest (adj.), honesty (n.), dishonest (adj.)', 'Đồng nghĩa: truthfully, sincerely · Trái nghĩa: dishonestly', 'honestly trọng về sự thành thật; biểu thị sự công bằng thường dùng fairly.', 'Please answer honestly: did you enjoy the soup?', NULL, 'Hãy trả lời thành thật: bạn có thích món súp này không?', '{"wordId":"honestly","ukIpa":"/ˈɒnɪstli/","usIpa":"/ˈɑːnɪstli/","cefr":"B1","topic":"society","senses":[{"pos":"adv.","en":"In a truthful way, without lying or cheating.","vi":"một cách thành thật; trung thực"},{"pos":"adv.","en":"Used to emphasize sincerity or introduce a frank opinion.","vi":"thành thật mà nói; thực sự"}],"examples":[{"en":"Please answer honestly: did you enjoy the soup?","vi":"Hãy trả lời thành thật: bạn có thích món súp này không?","audioKind":"ex"},{"en":"Companies that communicate honestly about environmental challenges are more likely to earn lasting public trust.","vi":"Các doanh nghiệp giao tiếp thành thật về các thách thức môi trường sẽ có nhiều khả năng giành được niềm tin lâu dài của công chúng.","audioKind":"ex2"}],"collocations":[{"en":"answer honestly","vi":"trả lời thành thật"},{"en":"honestly believe","vi":"thành tâm tin rằng"},{"en":"speak honestly","vi":"nói chuyện thành thật"}],"wordFamily":["honest (adj.)","honesty (n.)","dishonest (adj.)"],"synonyms":["truthfully","sincerely"],"antonyms":["dishonestly"],"tipVi":"honestly trọng về sự thành thật; biểu thị sự công bằng thường dùng fairly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_childhood', 'en-b1-12', 'childhood', '/ˈtʃaɪldhʊd/', 'B1', 'thời thơ ấu; tuổi thơ', 'n.', 'child (n.), childish (adj.), childlike (adj.)', 'Trái nghĩa: adulthood', 'during childhood chỉ chung thời thơ ấu; in my childhood chỉ thời thơ ấu của tôi.', 'My happiest childhood memories involve baking with my grandmother.', NULL, 'Những kỷ niệm tuổi thơ hạnh phúc nhất của tôi gắn liền với việc làm bánh cùng bà.', '{"wordId":"childhood","ukIpa":"/ˈtʃaɪldhʊd/","usIpa":"/ˈtʃaɪldhʊd/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the period of life when someone is a child","vi":"thời thơ ấu; tuổi thơ"}],"examples":[{"en":"My happiest childhood memories involve baking with my grandmother.","vi":"Những kỷ niệm tuổi thơ hạnh phúc nhất của tôi gắn liền với việc làm bánh cùng bà.","audioKind":"ex"},{"en":"Access to safe outdoor spaces during childhood can support physical development and emotional wellbeing.","vi":"Tiếp cận với không gian ngoài trời an toàn trong thời thơ ấu có thể hỗ trợ sự phát triển thể chất và sức khỏe cảm xúc.","audioKind":"ex2"}],"collocations":[{"en":"early childhood","vi":"thời thơ ấu"},{"en":"childhood memories","vi":"kỷ niệm tuổi thơ"},{"en":"a happy childhood","vi":"một tuổi thơ hạnh phúc"}],"wordFamily":["child (n.)","childish (adj.)","childlike (adj.)"],"synonyms":[],"antonyms":["adulthood"],"tipVi":"during childhood chỉ chung thời thơ ấu; in my childhood chỉ thời thơ ấu của tôi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brother-in-law', 'en-b1-12', 'brother-in-law', '/ˈbrʌðər ɪn lɔː/', 'B1', 'anh rể; em rể; anh/em vợ; anh/em chồng', 'n.', 'sister-in-law (n.), father-in-law (n.), mother-in-law (n.)', NULL, 'Dạng số nhiều là brothers-in-law; từ này không dùng cho họ hàng bên bác/chú/cô (anh em họ).', 'My brother-in-law helped my sister carry their new sofa upstairs.', NULL, 'Anh rể tôi đã giúp chị gái tôi khiêng chiếc ghế sofa mới lên lầu.', '{"wordId":"brother-in-law","ukIpa":"/ˈbrʌðər ɪn lɔː/","usIpa":"/ˈbrʌðər ɪn lɔː/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"your spouse''s brother, or your sibling''s or spouse''s sibling''s husband","vi":"anh rể; em rể; anh/em vợ; anh/em chồng"}],"examples":[{"en":"My brother-in-law helped my sister carry their new sofa upstairs.","vi":"Anh rể tôi đã giúp chị gái tôi khiêng chiếc ghế sofa mới lên lầu.","audioKind":"ex"},{"en":"Sharing childcare with relatives, such as a brother-in-law, can help working parents manage their daily responsibilities.","vi":"Việc chia sẻ trách nhiệm chăm sóc con cái với họ hàng, chẳng hạn như anh/em rể, có thể giúp các bậc phụ huynh bận rộn xoay sở tốt hơn với công việc hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"my brother-in-law","vi":"anh/em rể của tôi"},{"en":"a future brother-in-law","vi":"một người anh/em rể tương lai"}],"wordFamily":["sister-in-law (n.)","father-in-law (n.)","mother-in-law (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là brothers-in-law; từ này không dùng cho họ hàng bên bác/chú/cô (anh em họ).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relative', 'en-b1-12', 'relative', '/ˈrelətɪv/', 'B1', 'họ hàng; người thân; tương đối; mang tính so sánh', 'n.', 'relatively (adv.), related (adj.), relation (n.), relationship (n.)', NULL, 'Khi là danh từ, từ này chỉ người thân; khi là tính từ, nó thường đi với to để chỉ sự so sánh.', 'A relative brought us homemade bread during the holidays.', NULL, 'Một người họ hàng đã mang cho chúng tôi bánh mì tự làm trong kỳ nghỉ.', '{"wordId":"relative","ukIpa":"/ˈrelətɪv/","usIpa":"/ˈrelətɪv/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A person connected to you by blood or marriage.","vi":"họ hàng; người thân"},{"pos":"adj.","en":"Judged by comparison rather than by a fixed standard.","vi":"tương đối; mang tính so sánh"}],"examples":[{"en":"A relative brought us homemade bread during the holidays.","vi":"Một người họ hàng đã mang cho chúng tôi bánh mì tự làm trong kỳ nghỉ.","audioKind":"ex"},{"en":"The relative cost of public transport influences whether residents choose buses over private cars.","vi":"Chi phí tương đối của phương tiện giao thông công cộng ảnh hưởng đến việc cư dân chọn xe buýt thay vì ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"a close relative","vi":"họ hàng gần"},{"en":"a distant relative","vi":"họ hàng xa"},{"en":"relative importance","vi":"tầm quan trọng tương đối"},{"en":"relative to","vi":"tương đối so với"}],"wordFamily":["relatively (adv.)","related (adj.)","relation (n.)","relationship (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là danh từ, từ này chỉ người thân; khi là tính từ, nó thường đi với to để chỉ sự so sánh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nowadays', 'en-b1-12', 'nowadays', '/ˈnaʊədeɪz/', 'B1', 'ngày nay; hiện nay', 'adv.', NULL, 'Đồng nghĩa: these days, currently · Trái nghĩa: formerly', 'Thường đi với thì hiện tại đơn, nhấn mạnh sự so sánh giữa quá khứ và hiện tại; không cần dùng giới từ đi trước.', 'Nowadays, I usually pay for groceries with my phone.', NULL, 'Ngày nay, tôi thường mua sắm tạp hóa bằng điện thoại của mình.', '{"wordId":"nowadays","ukIpa":"/ˈnaʊədeɪz/","usIpa":"/ˈnaʊədeɪz/","cefr":"B1","topic":"society","senses":[{"pos":"adv.","en":"At the present time, especially compared with the past.","vi":"ngày nay; hiện nay"}],"examples":[{"en":"Nowadays, I usually pay for groceries with my phone.","vi":"Ngày nay, tôi thường mua sắm tạp hóa bằng điện thoại của mình.","audioKind":"ex"},{"en":"Nowadays, many employees expect flexible working arrangements that allow them to balance professional and family responsibilities.","vi":"Ngày nay, nhiều nhân viên mong đợi các thỏa thuận làm việc linh hoạt giúp họ cân bằng giữa trách nhiệm công việc và gia đình.","audioKind":"ex2"}],"collocations":[{"en":"nowadays, many people","vi":"ngày nay, nhiều người"},{"en":"more common nowadays","vi":"phổ biến hơn vào ngày nay"},{"en":"rarely used nowadays","vi":"ít được sử dụng vào ngày nay"}],"wordFamily":[],"synonyms":["these days","currently"],"antonyms":["formerly"],"tipVi":"Thường đi với thì hiện tại đơn, nhấn mạnh sự so sánh giữa quá khứ và hiện tại; không cần dùng giới từ đi trước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_population', 'en-b1-12', 'population', '/ˌpɑːpjuˈleɪʃən/', 'B1', 'dân số; toàn bộ cư dân; quần thể (sinh học)', 'n.', 'populate (v.), populated (adj.), overpopulation (n.)', NULL, 'Dân số nhiều hay ít dùng tính từ "large" hoặc "small", không dùng "many" hay "few".', 'The village population grows when families move here.', NULL, 'Dân số của làng tăng lên khi có các gia đình chuyển đến đây sinh sống.', '{"wordId":"population","ukIpa":"/ˌpɒpjuˈleɪʃən/","usIpa":"/ˌpɑːpjuˈleɪʃən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"all people living in an area, or their total number","vi":"dân số; toàn bộ cư dân"},{"pos":"n.","en":"all organisms of one species living in a particular area","vi":"quần thể (sinh học)"}],"examples":[{"en":"The village population grows when families move here.","vi":"Dân số của làng tăng lên khi có các gia đình chuyển đến đây sinh sống.","audioKind":"ex"},{"en":"An ageing population can place additional pressure on healthcare systems and increase demand for accessible public transport.","vi":"Dân số già hóa có thể đặt thêm áp lực lên hệ thống y tế và làm tăng nhu cầu về giao thông công cộng dễ tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"population growth","vi":"sự tăng trưởng dân số"},{"en":"ageing population","vi":"dân số già hóa"},{"en":"population density","vi":"mật độ dân số"},{"en":"bird population","vi":"quần thể chim"}],"wordFamily":["populate (v.)","populated (adj.)","overpopulation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dân số nhiều hay ít dùng tính từ \"large\" hoặc \"small\", không dùng \"many\" hay \"few\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_charity', 'en-b1-12', 'charity', '/ˈtʃærəti/', 'B1', 'tổ chức từ thiện; hoạt động từ thiện; sự cứu trợ', 'n.', 'charitable (adj.), charitably (adv.)', NULL, 'Khi chỉ tổ chức thì đếm được; khi chỉ hoạt động từ thiện hoặc tiền cứu trợ thì không đếm được.', 'My sister volunteers at a charity that rescues dogs.', NULL, 'Chị gái tôi làm tình nguyện viên tại một tổ chức từ thiện chuyên giải cứu chó.', '{"wordId":"charity","ukIpa":"/ˈtʃærəti/","usIpa":"/ˈtʃærəti/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"an organisation that helps people or causes in need","vi":"tổ chức từ thiện"},{"pos":"n.","en":"help, especially money, given to those in need","vi":"hoạt động từ thiện; sự cứu trợ"}],"examples":[{"en":"My sister volunteers at a charity that rescues dogs.","vi":"Chị gái tôi làm tình nguyện viên tại một tổ chức từ thiện chuyên giải cứu chó.","audioKind":"ex"},{"en":"Local charities can provide essential support, but governments remain responsible for ensuring access to basic services.","vi":"Các tổ chức từ thiện địa phương có thể cung cấp sự hỗ trợ thiết yếu, nhưng chính phủ vẫn chịu trách nhiệm đảm bảo khả năng tiếp cận các dịch vụ cơ bản.","audioKind":"ex2"}],"collocations":[{"en":"donate to charity","vi":"quyên góp cho từ thiện"},{"en":"raise money for charity","vi":"gây quỹ từ thiện"},{"en":"charity event","vi":"sự kiện từ thiện"}],"wordFamily":["charitable (adj.)","charitably (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ tổ chức thì đếm được; khi chỉ hoạt động từ thiện hoặc tiền cứu trợ thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_criminal', 'en-b1-12', 'criminal', '/ˈkrɪmɪnəl/', 'B1', 'thuộc tội phạm; hình sự; tội phạm; kẻ gian', 'adj.', 'crime (n.), criminally (adv.), criminality (n.)', NULL, 'criminal có thể là tính từ hoặc danh từ; trong khi crime là danh từ chỉ tội ác.', 'The police found evidence of criminal activity in the warehouse.', NULL, 'Cảnh sát đã tìm thấy bằng chứng về hoạt động phạm tội trong kho hàng.', '{"wordId":"criminal","ukIpa":"/ˈkrɪmɪnəl/","usIpa":"/ˈkrɪmɪnəl/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"relating to crime or the legal treatment of crime","vi":"thuộc tội phạm; hình sự"},{"pos":"n.","en":"a person who has committed a crime","vi":"tội phạm; kẻ gian"}],"examples":[{"en":"The police found evidence of criminal activity in the warehouse.","vi":"Cảnh sát đã tìm thấy bằng chứng về hoạt động phạm tội trong kho hàng.","audioKind":"ex"},{"en":"Education and employment programmes may reduce criminal behaviour by providing young people with better opportunities.","vi":"Các chương trình giáo dục và việc làm có thể làm giảm hành vi phạm tội bằng cách cung cấp cho giới trẻ nhiều cơ hội tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"criminal offence","vi":"tội hình sự"},{"en":"criminal record","vi":"tiền án tiền sự"},{"en":"criminal justice system","vi":"hệ thống tư pháp hình sự"},{"en":"criminal behaviour","vi":"hành vi phạm tội"}],"wordFamily":["crime (n.)","criminally (adv.)","criminality (n.)"],"synonyms":[],"antonyms":[],"tipVi":"criminal có thể là tính từ hoặc danh từ; trong khi crime là danh từ chỉ tội ác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attract', 'en-b1-12', 'attract', '/əˈtrækt/', 'B1', 'thu hút; hấp dẫn sự quan tâm; hút; lôi kéo lại gần', 'v.', 'attraction (n.), attractive (adj.), attractively (adv.)', 'Đồng nghĩa: draw, entice · Trái nghĩa: repel', 'attract là ngoại động từ, theo sau trực tiếp là tân ngữ chỉ người hoặc vật.', 'The bright flowers attract butterflies to our small balcony.', NULL, 'Những bông hoa rực rỡ thu hút bướm bay đến ban công nhỏ của chúng tôi.', '{"wordId":"attract","ukIpa":"/əˈtrækt/","usIpa":"/əˈtrækt/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"Make someone interested in or drawn towards something","vi":"thu hút; hấp dẫn sự quan tâm"},{"pos":"v.","en":"Pull something closer through a physical force","vi":"hút; lôi kéo lại gần"}],"examples":[{"en":"The bright flowers attract butterflies to our small balcony.","vi":"Những bông hoa rực rỡ thu hút bướm bay đến ban công nhỏ của chúng tôi.","audioKind":"ex"},{"en":"Cities that invest in reliable public transport are more likely to attract businesses and skilled workers.","vi":"Những thành phố đầu tư vào hệ thống giao thông công cộng đáng tin cậy sẽ có nhiều khả năng thu hút các doanh nghiệp và lao động tay nghề cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"attract attention","vi":"thu hút sự chú ý"},{"en":"attract tourists","vi":"thu hút khách du lịch"},{"en":"attract investment","vi":"thu hút đầu tư"},{"en":"attract customers","vi":"thu hút khách hàng"}],"wordFamily":["attraction (n.)","attractive (adj.)","attractively (adv.)"],"synonyms":["draw","entice"],"antonyms":["repel"],"tipVi":"attract là ngoại động từ, theo sau trực tiếp là tân ngữ chỉ người hoặc vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boxing-day', 'en-b1-12', 'Boxing Day', '/ˈbɑːksɪŋ deɪ/', 'B1', 'ngày Lễ tặng quà (ngày 26 tháng 12)', 'n.', NULL, NULL, 'Cố định chỉ ngày 26 tháng 12; viết hoa chữ cái đầu và không có dấu gạch ngang trong cách viết chuẩn.', 'We usually eat leftover turkey together on Boxing Day.', NULL, 'Chúng tôi thường cùng nhau ăn phần gà tây thừa vào ngày Lễ tặng quà.', '{"wordId":"boxing-day","ukIpa":"/ˈbɒksɪŋ deɪ/","usIpa":"/ˈbɑːksɪŋ deɪ/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"December 26, a public holiday in Britain and several other countries.","vi":"ngày Lễ tặng quà (ngày 26 tháng 12)"}],"examples":[{"en":"We usually eat leftover turkey together on Boxing Day.","vi":"Chúng tôi thường cùng nhau ăn phần gà tây thừa vào ngày Lễ tặng quà.","audioKind":"ex"},{"en":"Boxing Day sales can boost retail revenue, but they also raise concerns about unnecessary consumption.","vi":"Các đợt giảm giá nhân ngày Lễ tặng quà có thể thúc đẩy doanh thu bán lẻ, nhưng chúng cũng dấy lên lo ngại về tình trạng tiêu dùng lãng phí.","audioKind":"ex2"}],"collocations":[{"en":"on Boxing Day","vi":"vào ngày Lễ tặng quà"},{"en":"Boxing Day sales","vi":"đợt giảm giá ngày Lễ tặng quà"},{"en":"a Boxing Day walk","vi":"chuyến đi dạo ngày Lễ tặng quà"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cố định chỉ ngày 26 tháng 12; viết hoa chữ cái đầu và không có dấu gạch ngang trong cách viết chuẩn.","noteVi":"Đã điều chỉnh cách viết không chuẩn thành Boxing Day.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_murder', 'en-b1-12', 'murder', '/ˈmɝːdɚ/', 'B1', 'tội giết người; vụ án mạng; sắt hại; mưu sát', 'n.', 'murderer (n.), murderous (adj.)', NULL, 'Murder nhấn mạnh hành vi cố ý và trái pháp luật; trong khi kill có nghĩa rộng hơn.', 'We watched a film about a detective investigating a murder.', NULL, 'Chúng tôi đã xem một bộ phim về một thám tử đang điều tra một vụ án mạng.', '{"wordId":"murder","ukIpa":"/ˈmɜːdə/","usIpa":"/ˈmɝːdɚ/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the crime of deliberately and unlawfully killing someone","vi":"tội giết người; vụ án mạng"},{"pos":"v.","en":"to deliberately and unlawfully kill someone","vi":"sắt hại; mưu sát"}],"examples":[{"en":"We watched a film about a detective investigating a murder.","vi":"Chúng tôi đã xem một bộ phim về một thám tử đang điều tra một vụ án mạng.","audioKind":"ex"},{"en":"Accurate forensic evidence plays a crucial role in solving murder cases and preventing wrongful convictions.","vi":"Bằng chứng pháp y chính xác đóng vai trò vô cùng quan trọng trong việc phá án giết người và ngăn chặn các án oan sai.","audioKind":"ex2"}],"collocations":[{"en":"commit murder","vi":"phạm tội giết người"},{"en":"attempted murder","vi":"âm mưu giết người; mưu sát bất thành"},{"en":"murder investigation","vi":"cuộc điều tra án mạng"},{"en":"be charged with murder","vi":"bị buộc tội giết người"}],"wordFamily":["murderer (n.)","murderous (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Murder nhấn mạnh hành vi cố ý và trái pháp luật; trong khi kill có nghĩa rộng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_12_1', 'en-b1-12', 'Cách dùng “crime” (n.) — tội phạm; tệ nạn tội phạm', 'commit a crime  ·  prevent crime  ·  crime rate', 'Chỉ tệ nạn tội phạm nói chung thì không đếm được; chỉ hành vi phạm tội cụ thể thì đếm được, chẳng hạn như commit a crime.', 'Họ từ (Word Family): criminal (n.), criminal (adj.), criminality (n.)', '[{"hanzi":"Better street lighting has helped reduce crime here.","pinyin":"","meaning":"Hệ thống đèn đường tốt hơn đã giúp giảm thiểu tình trạng tội phạm ở đây."},{"hanzi":"Investment in education and employment opportunities may reduce crime more effectively than increasingly severe punishments.","pinyin":"","meaning":"Việc đầu tư vào giáo dục và cơ hội việc làm có thể làm giảm tội phạm hiệu quả hơn so với các hình phạt ngày càng nghiêm khắc."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_12_2', 'en-b1-12', 'Cách dùng “movement” (n.) — sự chuyển động; động tác', 'freedom of movement  ·  sudden movement  ·  environmental movement', 'Khi chỉ hành động cụ thể hoặc phong trào xã hội thì đếm được; khi chỉ sự di chuyển nói chung thì không đếm được.', 'Họ từ (Word Family): move (v.), movable (adj.), moving (adj.) | Đồng nghĩa: motion · Trái nghĩa: stillness', '[{"hanzi":"A sudden movement in the bushes caught my attention.","pinyin":"","meaning":"Một cử động bất ngờ trong bụi cây đã thu hút sự chú ý của tôi."},{"hanzi":"The environmental movement has encouraged governments to adopt stronger policies on waste reduction and renewable energy.","pinyin":"","meaning":"Phong trào bảo vệ môi trường đã khuyến khích các chính phủ áp dụng các chính sách mạnh mẽ hơn về giảm thiểu rác thải và năng lượng tái tạo."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_12_3', 'en-b1-12', 'Cách dùng “nowadays” (adv.) — ngày nay; hiện nay', 'nowadays, many people  ·  more common nowadays  ·  rarely used nowadays', 'Thường đi với thì hiện tại đơn, nhấn mạnh sự so sánh giữa quá khứ và hiện tại; không cần dùng giới từ đi trước.', 'Đồng nghĩa: these days, currently · Trái nghĩa: formerly', '[{"hanzi":"Nowadays, I usually pay for groceries with my phone.","pinyin":"","meaning":"Ngày nay, tôi thường mua sắm tạp hóa bằng điện thoại của mình."},{"hanzi":"Nowadays, many employees expect flexible working arrangements that allow them to balance professional and family responsibilities.","pinyin":"","meaning":"Ngày nay, nhiều nhân viên mong đợi các thỏa thuận làm việc linh hoạt giúp họ cân bằng giữa trách nhiệm công việc và gia đình."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_12_4', 'en-b1-12', 'Cách dùng “Boxing Day” (n.) — ngày Lễ tặng quà (ngày 26 tháng 12)', 'on Boxing Day  ·  Boxing Day sales  ·  a Boxing Day walk', 'Cố định chỉ ngày 26 tháng 12; viết hoa chữ cái đầu và không có dấu gạch ngang trong cách viết chuẩn.', NULL, '[{"hanzi":"We usually eat leftover turkey together on Boxing Day.","pinyin":"","meaning":"Chúng tôi thường cùng nhau ăn phần gà tây thừa vào ngày Lễ tặng quà."},{"hanzi":"Boxing Day sales can boost retail revenue, but they also raise concerns about unnecessary consumption.","pinyin":"","meaning":"Các đợt giảm giá nhân ngày Lễ tặng quà có thể thúc đẩy doanh thu bán lẻ, nhưng chúng cũng dấy lên lo ngại về tình trạng tiêu dùng lãng phí."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_12_1', 'en-b1-12', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_12_1_1', 'ten_b1_12_1', 'movement', 'A sudden movement in the bushes caught my attention.', 'A sudden movement in the bushes caught my attention.', '/ˈmuːvmənt/', 'Một cử động bất ngờ trong bụi cây đã thu hút sự chú ý của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_12_1_2', 'ten_b1_12_1', 'celebration', 'We decorated the garden for our grandparents'' anniversary celebration.', 'We decorated the garden for our grandparents'' anniversary celebration.', '/ˌseləˈbreɪʃən/', 'Chúng tôi đã trang trí khu vườn cho lễ kỷ niệm ngày cưới của ông bà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_12_1_3', 'ten_b1_12_1', 'unfriendly', 'The new neighbour seemed unfriendly but was simply shy.', 'The new neighbour seemed unfriendly but was simply shy.', '/ʌnˈfrendli/', 'Người hàng xóm mới có vẻ lạnh lùng nhưng thực ra chỉ là người hay ngại ngùng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_12_1_4', 'ten_b1_12_1', 'bride', 'The bride held fresh flowers as she entered the garden.', 'The bride held fresh flowers as she entered the garden.', '/braɪd/', 'Cô dâu tay cầm hoa tươi bước vào khu vườn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
