INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_12_1_1', 'en-b1-12', 'ten_b1_12_1', 'listening', 'listening', 'A sudden movement in the bushes caught my attention.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một cử động bất ngờ trong bụi cây đã thu hút sự chú ý của tôi.","Chúng tôi thường cùng nhau ăn phần gà tây thừa vào ngày Lễ tặng quà.","Cảnh sát đã tìm thấy bằng chứng về hoạt động phạm tội trong kho hàng.","Linh mục chào đón mọi người khi họ bước vào nhà thờ."]'::jsonb, 0, 'A sudden movement in the bushes caught my attention. → Một cử động bất ngờ trong bụi cây đã thu hút sự chú ý của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_12_1_2', 'en-b1-12', 'ten_b1_12_1', 'listening', 'listening', 'We decorated the garden for our grandparents'' anniversary celebration.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những kỷ niệm tuổi thơ hạnh phúc nhất của tôi gắn liền với việc làm bánh cùng bà.","Cô dâu tay cầm hoa tươi bước vào khu vườn.","Chúng tôi đã trang trí khu vườn cho lễ kỷ niệm ngày cưới của ông bà.","Dân số của làng tăng lên khi có các gia đình chuyển đến đây sinh sống."]'::jsonb, 2, 'We decorated the garden for our grandparents'' anniversary celebration. → Chúng tôi đã trang trí khu vườn cho lễ kỷ niệm ngày cưới của ông bà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_12_1_3', 'en-b1-12', 'ten_b1_12_1', 'listening', 'listening', 'The new neighbour seemed unfriendly but was simply shy.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một người họ hàng đã mang cho chúng tôi bánh mì tự làm trong kỳ nghỉ.","Hệ thống đèn đường tốt hơn đã giúp giảm thiểu tình trạng tội phạm ở đây.","Ba thế hệ trong gia đình chúng tôi đã quây quần bên nhau ăn tối ngày hôm qua.","Người hàng xóm mới có vẻ lạnh lùng nhưng thực ra chỉ là người hay ngại ngùng."]'::jsonb, 3, 'The new neighbour seemed unfriendly but was simply shy. → Người hàng xóm mới có vẻ lạnh lùng nhưng thực ra chỉ là người hay ngại ngùng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_12_2', 'en-b1-12', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_12_2_1', 'ten_b1_12_2', 'movement', 'The environmental movement has encouraged governments to adopt stronger policies on waste reduction and renewable energy.', 'The environmental movement has encouraged governments to adopt stronger policies on waste reduction and renewable energy.', '/ˈmuːvmənt/', 'Phong trào bảo vệ môi trường đã khuyến khích các chính phủ áp dụng các chính sách mạnh mẽ hơn về giảm thiểu rác thải và năng lượng tái tạo.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_12_2_2', 'ten_b1_12_2', 'celebration', 'Community celebrations can strengthen social bonds by bringing together residents from different cultural backgrounds.', 'Community celebrations can strengthen social bonds by bringing together residents from different cultural backgrounds.', '/ˌseləˈbreɪʃən/', 'Các hoạt động kỷ niệm cộng đồng có thể thắt chặt tình đoàn kết xã hội bằng cách kết nối cư dân từ các nền văn hóa khác nhau.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_12_2_3', 'ten_b1_12_2', 'unfriendly', 'An unfriendly working environment can discourage employees from sharing ideas and seeking support.', 'An unfriendly working environment can discourage employees from sharing ideas and seeking support.', '/ʌnˈfrendli/', 'Môi trường làm việc không thân thiện có thể khiến nhân viên nản lòng trong việc chia sẻ ý tưởng và tìm kiếm sự hỗ trợ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_12_2_4', 'ten_b1_12_2', 'bride', 'In many cultures, the bride and her family share responsibility for organising the wedding celebration.', 'In many cultures, the bride and her family share responsibility for organising the wedding celebration.', '/braɪd/', 'Trong nhiều nền văn hóa, cô dâu và gia đình cô ấy cùng chia sẻ trách nhiệm tổ chức lễ cưới.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_12_2_5', 'ten_b1_12_2', 'agreement', 'International agreements on carbon emissions are more effective when participating countries establish clear targets and monitor progress.', 'International agreements on carbon emissions are more effective when participating countries establish clear targets and monitor progress.', '/əˈɡriːmənt/', 'Các hiệp định quốc tế về lượng khí thải carbon sẽ hiệu quả hơn khi các quốc gia tham gia thiết lập các mục tiêu rõ ràng và giám sát tiến độ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_12_2_6', 'ten_b1_12_2', 'religion', 'Schools can teach students about religion while encouraging respect for people with different beliefs.', 'Schools can teach students about religion while encouraging respect for people with different beliefs.', '/rɪˈlɪdʒən/', 'Nhà trường có thể dạy học sinh về tôn giáo đồng thời khuyến khích sự tôn trọng đối với những người có niềm tin khác nhau.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_12_2_1', 'en-b1-12', 'ten_b1_12_2', 'listening', 'listening', 'The environmental movement has encouraged governments to adopt stronger policies on waste reduction and renewable energy.', NULL, 'Trong câu vừa nghe, từ “movement” mang nghĩa nào sau đây?', '["sự chuyển động; động tác","nhà hóa học","tác động; hiệu quả","nhiệt kế"]'::jsonb, 0, '“movement” (/ˈmuːvmənt/): sự chuyển động; động tác. Câu đầy đủ: The environmental movement has encouraged governments to adopt stronger policies on waste reduction and renewable energy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_12_2_2', 'en-b1-12', 'ten_b1_12_2', 'listening', 'listening', 'Community celebrations can strengthen social bonds by bringing together residents from different cultural backgrounds.', NULL, 'Trong câu vừa nghe, từ “celebration” mang nghĩa nào sau đây?', '["mối quan hệ; sự liên quan","qua; đi qua; thông qua","lễ kỷ niệm; sự kiện ăn mừng","nhân viên bảo vệ; lính canh"]'::jsonb, 2, '“celebration” (/ˌseləˈbreɪʃən/): lễ kỷ niệm; sự kiện ăn mừng. Câu đầy đủ: Community celebrations can strengthen social bonds by bringing together residents from different cultural backgrounds.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
