INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_12_2', 'en-b1-12', NULL, 'comprehensive_test', 'listening', 'We decorated the garden for our grandparents'' anniversary celebration.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thật là tàn nhẫn khi chế nhạo bức vẽ đầu tiên của cậu ấy.","Một người họ hàng đã mang cho chúng tôi bánh mì tự làm trong kỳ nghỉ.","Một cử động bất ngờ trong bụi cây đã thu hút sự chú ý của tôi.","Chúng tôi đã trang trí khu vườn cho lễ kỷ niệm ngày cưới của ông bà."]'::jsonb, 3, 'We decorated the garden for our grandparents'' anniversary celebration. → Chúng tôi đã trang trí khu vườn cho lễ kỷ niệm ngày cưới của ông bà.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
