INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_12_18', 'en-b1-12', NULL, 'comprehensive_test', 'reading', NULL, 'The environmental movement has encouraged governments to adopt stronger policies on waste reduction and renewable energy.', 'Dựa vào câu trên, từ “movement” có nghĩa phù hợp nhất là gì?', '["chiều rộng; bề ngang","về phần mình; cá nhân tôi","sự chuyển động; động tác","đăng ký; ghi danh"]'::jsonb, 2, 'movement: sự chuyển động; động tác; phong trào xã hội; chương nhạc. Dịch cả câu: Phong trào bảo vệ môi trường đã khuyến khích các chính phủ áp dụng các chính sách mạnh mẽ hơn về giảm thiểu rác thải và năng lượng tái tạo.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_12_19', 'en-b1-12', NULL, 'comprehensive_test', 'reading', NULL, 'Community celebrations can strengthen social bonds by bringing together residents from different cultural backgrounds.', 'Dựa vào câu trên, từ “celebration” có nghĩa phù hợp nhất là gì?', '["quyên góp; hiến tặng","tác phẩm điêu khắc","lễ kỷ niệm; sự kiện ăn mừng","làm cho ai đó thất vọng vì không đáp ứng được kỳ vọng của họ"]'::jsonb, 2, 'celebration: lễ kỷ niệm; sự kiện ăn mừng; việc ăn mừng; sự kỷ niệm. Dịch cả câu: Các hoạt động kỷ niệm cộng đồng có thể thắt chặt tình đoàn kết xã hội bằng cách kết nối cư dân từ các nền văn hóa khác nhau.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_12_20', 'en-b1-12', NULL, 'comprehensive_test', 'reading', NULL, 'An unfriendly working environment can discourage employees from sharing ideas and seeking support.', 'Dựa vào câu trên, từ “unfriendly” có nghĩa phù hợp nhất là gì?', '["không thân thiện; lạnh lùng","chim bồ câu","lời phàn nàn; đơn khiếu nại; sự khiếu nại","quá cân; thừa cân"]'::jsonb, 0, 'unfriendly: không thân thiện; lạnh lùng; không thuận lợi; khó sử dụng. Dịch cả câu: Môi trường làm việc không thân thiện có thể khiến nhân viên nản lòng trong việc chia sẻ ý tưởng và tìm kiếm sự hỗ trợ.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_12_21', 'en-b1-12', NULL, 'comprehensive_test', 'reading', NULL, 'In many cultures, the bride and her family share responsibility for organising the wedding celebration.', 'Dựa vào câu trên, từ “bride” có nghĩa phù hợp nhất là gì?', '["cô dâu","riêng lẻ; cá nhân","thuốc giảm đau","chua (có vị gắt như chanh)"]'::jsonb, 0, 'bride: cô dâu. Dịch cả câu: Trong nhiều nền văn hóa, cô dâu và gia đình cô ấy cùng chia sẻ trách nhiệm tổ chức lễ cưới.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_12_22', 'en-b1-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thu hút; hấp dẫn sự quan tâm”', '["unbelievable","attract","power","flyer"]'::jsonb, 1, 'thu hút; hấp dẫn sự quan tâm → attract (/əˈtrækt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_12_23', 'en-b1-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngày Lễ tặng quà (ngày 26 tháng 12)”', '["queue","maid","Boxing Day","ache"]'::jsonb, 2, 'ngày Lễ tặng quà (ngày 26 tháng 12) → Boxing Day (/ˈbɑːksɪŋ deɪ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_12_24', 'en-b1-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tội giết người; vụ án mạng”', '["murder","spice","destination","pigeon"]'::jsonb, 0, 'tội giết người; vụ án mạng → murder (/ˈmɝːdɚ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-13', 'en', 'Bài 13: Xã hội & Cộng đồng (6) - CEFR B1', 'CEFR B1', 'B1 · Xã hội', '25 từ vựng Tiếng Anh CEFR B1 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3013, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_general', 'en-b1-13', 'general', '/ˈdʒenərəl/', 'B1', 'chung; phổ biến; toàn thể; chung chung; đại khái; tổng quát; đại tướng; tướng quân', 'adj.', 'generally (adv.), generalise (v.), generalisation (n.)', 'Trái nghĩa: specific', 'Cụm từ in general mang nghĩa "nói chung", thường dùng khi đưa ra nhận định khái quát.', 'There was general agreement that the kitchen needed repainting.', NULL, 'Đã có sự đồng thuận chung rằng nhà bếp cần phải được sơn lại.', '{"wordId":"general","ukIpa":"/ˈdʒenərəl/","usIpa":"/ˈdʒenərəl/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"affecting or involving most people, things, or situations","vi":"chung; phổ biến; toàn thể"},{"pos":"adj.","en":"describing main points rather than particular details","vi":"chung chung; đại khái; tổng quát"},{"pos":"n.","en":"an officer with a very high rank in the army","vi":"đại tướng; tướng quân"}],"examples":[{"en":"There was general agreement that the kitchen needed repainting.","vi":"Đã có sự đồng thuận chung rằng nhà bếp cần phải được sơn lại.","audioKind":"ex"},{"en":"Although the general standard of education has improved, significant differences remain between urban and rural schools.","vi":"Mặc dù mặt bằng chung về giáo dục đã được nâng cao, những khác biệt đáng kể vẫn tồn tại giữa các trường học thành thị và nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"in general","vi":"nói chung; nhìn chung"},{"en":"general public","vi":"công chúng; đại chúng"},{"en":"general knowledge","vi":"kiến thức phổ thông; kiến thức chung"},{"en":"general overview","vi":"tổng quan chung"}],"wordFamily":["generally (adv.)","generalise (v.)","generalisation (n.)"],"synonyms":[],"antonyms":["specific"],"tipVi":"Cụm từ in general mang nghĩa \"nói chung\", thường dùng khi đưa ra nhận định khái quát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blame', 'en-b1-13', 'blame', '/bleɪm/', 'B1', 'đổ lỗi; trách mắng; trách nhiệm; sự đổ lỗi', 'v.', 'blameless (adj.), blameworthy (adj.)', NULL, 'Người làm tân ngữ dùng blame sb for; sự việc làm tân ngữ dùng blame sth on.', 'Don''t blame me for the broken kitchen chair.', NULL, 'Đừng có đổ lỗi cho tôi vì cái ghế bếp bị gãy đó nhé.', '{"wordId":"blame","ukIpa":"/bleɪm/","usIpa":"/bleɪm/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"To consider someone or something responsible for a problem.","vi":"đổ lỗi; trách mắng"},{"pos":"n.","en":"Responsibility for something bad that has happened.","vi":"trách nhiệm; sự đổ lỗi"}],"examples":[{"en":"Don''t blame me for the broken kitchen chair.","vi":"Đừng có đổ lỗi cho tôi vì cái ghế bếp bị gãy đó nhé.","audioKind":"ex"},{"en":"It is unfair to blame individuals alone for environmental problems caused partly by industrial activity.","vi":"Thật bất công khi chỉ quy trách nhiệm cho các cá nhân đối với các vấn đề môi trường mà một phần là do hoạt động công nghiệp gây ra.","audioKind":"ex2"}],"collocations":[{"en":"blame someone for something","vi":"đổ lỗi cho ai vì việc gì"},{"en":"blame something on someone","vi":"đổ điều gì lên đầu ai"},{"en":"take the blame","vi":"gánh chịu trách nhiệm"},{"en":"be to blame","vi":"phải chịu trách nhiệm"}],"wordFamily":["blameless (adj.)","blameworthy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Người làm tân ngữ dùng blame sb for; sự việc làm tân ngữ dùng blame sth on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_permitted', 'en-b1-13', 'permitted', '/pɚˈmɪtɪd/', 'B1', 'được cho phép; được chuẩn y', 'v.', 'permit (v.), permission (n.), permissible (adj.)', 'Đồng nghĩa: allowed, authorized · Trái nghĩa: forbidden, prohibited', 'Động từ permit khi chia quá khứ phải gấp đôi chữ t; thể bị động theo sau bằng to do.', 'We were permitted to feed the goats at noon.', NULL, 'Chúng tôi đã được phép cho lũ dê ăn vào lúc trưa đứng bóng.', '{"wordId":"permitted","ukIpa":"/pəˈmɪtɪd/","usIpa":"/pɚˈmɪtɪd/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"allowed something; the past tense and past participle of permit","vi":"được cho phép; được chuẩn y"}],"examples":[{"en":"We were permitted to feed the goats at noon.","vi":"Chúng tôi đã được phép cho lũ dê ăn vào lúc trưa đứng bóng.","audioKind":"ex"},{"en":"Students should be permitted to use digital tools when these genuinely support learning rather than distract from it.","vi":"Học sinh nên được phép sử dụng các công cụ kỹ thuật số khi chúng thực sự hỗ trợ việc học tập thay vì làm xao lãng điều đó.","audioKind":"ex2"}],"collocations":[{"en":"be permitted to do something","vi":"được phép làm gì"},{"en":"not permitted","vi":"không được phép"},{"en":"legally permitted","vi":"được pháp luật cho phép"}],"wordFamily":["permit (v.)","permission (n.)","permissible (adj.)"],"synonyms":["allowed","authorized"],"antonyms":["forbidden","prohibited"],"tipVi":"Động từ permit khi chia quá khứ phải gấp đôi chữ t; thể bị động theo sau bằng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mate', 'en-b1-13', 'mate', '/meɪt/', 'B1', 'bạn bè; bạn đồng hành; bạn đời của động vật; giao phối', 'n.', 'mating (n.), classmate (n.), teammate (n.)', 'Đồng nghĩa: friend, companion', 'Biểu đạt bạn bè thuộc văn phong thân mật kiểu Anh, văn viết trang trọng nên dùng friend.', 'I''m meeting a mate for lunch near the station.', NULL, 'Tôi chuẩn bị gặp một người bạn để ăn trưa gần nhà ga.', '{"wordId":"mate","ukIpa":"/meɪt/","usIpa":"/meɪt/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A friend or someone you share an activity with","vi":"bạn bè; bạn đồng hành"},{"pos":"n.","en":"An animal''s partner for breeding","vi":"bạn đời của động vật"},{"pos":"v.","en":"To breed, or bring animals together to breed","vi":"giao phối"}],"examples":[{"en":"I''m meeting a mate for lunch near the station.","vi":"Tôi chuẩn bị gặp một người bạn để ăn trưa gần nhà ga.","audioKind":"ex"},{"en":"Some bird species stay with the same mate for years, sharing responsibility for raising their young.","vi":"Một số loài chim gắn bó với cùng một bạn đời trong nhiều năm, cùng chia sẻ trách nhiệm nuôi dưỡng con non.","audioKind":"ex2"}],"collocations":[{"en":"a close mate","vi":"bạn thân"},{"en":"find a mate","vi":"tìm kiếm bạn đời"},{"en":"mate for life","vi":"ghép đôi trọn đời"}],"wordFamily":["mating (n.)","classmate (n.)","teammate (n.)"],"synonyms":["friend","companion"],"antonyms":[],"tipVi":"Biểu đạt bạn bè thuộc văn phong thân mật kiểu Anh, văn viết trang trọng nên dùng friend.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_citizen', 'en-b1-13', 'citizen', '/ˈsɪtɪzən/', 'B1', 'công dân; người dân thành phố; cư dân', 'n.', 'citizenship (n.)', NULL, 'citizen nhấn mạnh tư cách công dân; resident nhấn mạnh sự cư trú.', 'My aunt became a citizen after living here for years.', NULL, 'Dì của tôi đã trở thành công dân sau khi sinh sống ở đây nhiều năm.', '{"wordId":"citizen","ukIpa":"/ˈsɪtɪzən/","usIpa":"/ˈsɪtɪzən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A legal member of a country with rights and responsibilities.","vi":"công dân"},{"pos":"n.","en":"A person who lives in a particular town or city.","vi":"người dân thành phố; cư dân"}],"examples":[{"en":"My aunt became a citizen after living here for years.","vi":"Dì của tôi đã trở thành công dân sau khi sinh sống ở đây nhiều năm.","audioKind":"ex"},{"en":"Every citizen should have access to reliable public services, regardless of income or place of residence.","vi":"Mỗi công dân đều nên được tiếp cận các dịch vụ công đáng tin cậy, bất kể thu nhập hay nơi cư trú.","audioKind":"ex2"}],"collocations":[{"en":"become a citizen","vi":"trở thành công dân"},{"en":"a senior citizen","vi":"người cao tuổi"},{"en":"a responsible citizen","vi":"công dân có trách nhiệm"}],"wordFamily":["citizenship (n.)"],"synonyms":[],"antonyms":[],"tipVi":"citizen nhấn mạnh tư cách công dân; resident nhấn mạnh sự cư trú.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_worldwide', 'en-b1-13', 'worldwide', '/ˌwɝːldˈwaɪd/', 'B1', 'toàn cầu; trên toàn thế giới; trên khắp thế giới', 'adj.', NULL, 'Đồng nghĩa: global, international', 'Có thể đóng vai trò là tính từ hoặc trạng từ: sell worldwide.', 'The band''s new song became a worldwide hit.', NULL, 'Bài hát mới của ban nhạc đã trở thành bản hit trên toàn cầu.', '{"wordId":"worldwide","ukIpa":"/ˌwɜːldˈwaɪd/","usIpa":"/ˌwɝːldˈwaɪd/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"Existing or happening in all parts of the world.","vi":"toàn cầu; trên toàn thế giới"},{"pos":"adv.","en":"In or to all parts of the world.","vi":"trên khắp thế giới; toàn cầu"}],"examples":[{"en":"The band''s new song became a worldwide hit.","vi":"Bài hát mới của ban nhạc đã trở thành bản hit trên toàn cầu.","audioKind":"ex"},{"en":"Worldwide cooperation is essential for reducing carbon emissions and protecting communities from the effects of climate change.","vi":"Hợp tác toàn cầu là điều cần thiết để giảm lượng khí thải carbon và bảo vệ cộng đồng trước các tác động của biến đổi khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"worldwide demand","vi":"nhu cầu toàn cầu"},{"en":"worldwide recognition","vi":"sự công nhận toàn cầu"},{"en":"available worldwide","vi":"có sẵn trên toàn thế giới"},{"en":"worldwide distribution","vi":"sự phân phối toàn cầu"}],"wordFamily":[],"synonyms":["global","international"],"antonyms":[],"tipVi":"Có thể đóng vai trò là tính từ hoặc trạng từ: sell worldwide.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shelter', 'en-b1-13', 'shelter', '/ˈʃeltər/', 'B1', 'sự che chở; nơi trú ẩn; nhà tạm; trú ẩn; che chở', 'n.', 'sheltered (adj.)', 'Đồng nghĩa: refuge, protection', 'Nghĩa sự che chở thường không đếm được; chỉ cụ thể nơi trú ẩn thì đếm được.', 'We found shelter under a bridge during the storm.', NULL, 'Chúng tôi đã tìm chỗ trú ẩn dưới một cây cầu trong cơn giông bão.', '{"wordId":"shelter","ukIpa":"/ˈʃeltə/","usIpa":"/ˈʃeltər/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"Protection from danger or bad weather.","vi":"sự che chở; nơi trú ẩn"},{"pos":"n.","en":"A place that provides safety or protection.","vi":"nơi trú ẩn; nhà tạm"},{"pos":"v.","en":"To stay somewhere protected, or protect someone from harm.","vi":"trú ẩn; che chở"}],"examples":[{"en":"We found shelter under a bridge during the storm.","vi":"Chúng tôi đã tìm chỗ trú ẩn dưới một cây cầu trong cơn giông bão.","audioKind":"ex"},{"en":"Local authorities should provide temporary shelter for residents whose homes have been damaged by floods.","vi":"Chính quyền địa phương nên cung cấp chỗ ở tạm thời cho những cư dân có nhà cửa bị tàn phá bởi lũ lụt.","audioKind":"ex2"}],"collocations":[{"en":"take shelter","vi":"tìm chỗ trú ẩn"},{"en":"temporary shelter","vi":"nơi trú tạm"},{"en":"shelter from the rain","vi":"trú mưa"},{"en":"animal shelter","vi":"trạm cứu hộ động vật"}],"wordFamily":["sheltered (adj.)"],"synonyms":["refuge","protection"],"antonyms":[],"tipVi":"Nghĩa sự che chở thường không đếm được; chỉ cụ thể nơi trú ẩn thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expression', 'en-b1-13', 'expression', '/ɪkˈspreʃən/', 'B1', 'sự biểu lộ; sự thể hiện; vẻ mặt; nét mặt; cách diễn đạt; thành ngữ', 'n.', 'express (v.), expressive (adj.), expressively (adv.)', NULL, 'Chỉ "vẻ mặt, cách nói" thì đếm được; chỉ "sự biểu đạt" thường không đếm được.', 'He sent flowers as an expression of his gratitude.', NULL, 'Anh ấy gửi hoa như một cách để bày tỏ lòng biết ơn.', '{"wordId":"expression","ukIpa":"/ɪkˈspreʃən/","usIpa":"/ɪkˈspreʃən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"The act of showing thoughts or feelings through words or actions.","vi":"sự biểu lộ; sự thể hiện"},{"pos":"n.","en":"The look on someone''s face that reveals feelings.","vi":"vẻ mặt; nét mặt"},{"pos":"n.","en":"A word or phrase with a particular meaning.","vi":"cách diễn đạt; thành ngữ"}],"examples":[{"en":"He sent flowers as an expression of his gratitude.","vi":"Anh ấy gửi hoa như một cách để bày tỏ lòng biết ơn.","audioKind":"ex"},{"en":"Schools should encourage creative expression by giving students regular opportunities to explore music, drama, and visual arts.","vi":"Nhà trường nên khuyến khích sự thể hiện sáng tạo bằng cách thường xuyên cho học sinh cơ hội khám phá âm nhạc, kịch nghệ và nghệ thuật thị giác.","audioKind":"ex2"}],"collocations":[{"en":"freedom of expression","vi":"tự do ngôn luận"},{"en":"facial expression","vi":"biểu cảm khuôn mặt"},{"en":"an expression of gratitude","vi":"sự bày tỏ lòng biết ơn"},{"en":"idiomatic expression","vi":"cách nói quen thuộc"}],"wordFamily":["express (v.)","expressive (adj.)","expressively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ \"vẻ mặt, cách nói\" thì đếm được; chỉ \"sự biểu đạt\" thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stranger', 'en-b1-13', 'stranger', '/ˈstreɪndʒər/', 'B1', 'người lạ; người không quen biết; người mới đến; người lạ nước lạ cái', 'n.', 'strange (adj.), strangely (adv.), strangeness (n.)', 'Trái nghĩa: acquaintance', 'stranger là người lạ, không đồng nghĩa với foreigner là người nước ngoài.', 'A kind stranger helped me carry my heavy suitcase.', NULL, 'Một người lạ tốt bụng đã giúp tôi xách chiếc vali nặng.', '{"wordId":"stranger","ukIpa":"/ˈstreɪndʒə/","usIpa":"/ˈstreɪndʒər/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"someone you do not know","vi":"người lạ; người không quen biết"},{"pos":"n.","en":"someone unfamiliar with a particular place or community","vi":"người mới đến; người lạ nước lạ cái"}],"examples":[{"en":"A kind stranger helped me carry my heavy suitcase.","vi":"Một người lạ tốt bụng đã giúp tôi xách chiếc vali nặng.","audioKind":"ex"},{"en":"Community events can encourage residents to interact with strangers and develop a stronger sense of belonging.","vi":"Các hoạt động cộng đồng có thể khuyến khích cư dân giao lưu với những người lạ và phát triển ý thức thuộc về mạnh mẽ hơn.","audioKind":"ex2"}],"collocations":[{"en":"complete stranger","vi":"người hoàn toàn xa lạ"},{"en":"stranger to the area","vi":"người mới đến khu vực này"},{"en":"no stranger to","vi":"không còn xa lạ với"}],"wordFamily":["strange (adj.)","strangely (adv.)","strangeness (n.)"],"synonyms":[],"antonyms":["acquaintance"],"tipVi":"stranger là người lạ, không đồng nghĩa với foreigner là người nước ngoài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unfair', 'en-b1-13', 'unfair', '/ˌʌnˈfer/', 'B1', 'bất công; không công bằng', 'adj.', 'fair (adj.), unfairly (adv.), unfairness (n.), fairness (n.)', 'Đồng nghĩa: unjust, inequitable · Trái nghĩa: fair, just', 'Biểu thị "bất công với ai" dùng unfair to someone.', 'It seems unfair that I always wash the dishes.', NULL, 'Cứ nhắc tôi rửa bát mãi thì có vẻ không công bằng.', '{"wordId":"unfair","ukIpa":"/ˌʌnˈfeə/","usIpa":"/ˌʌnˈfer/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"not treating people equally or reasonably","vi":"bất công; không công bằng"}],"examples":[{"en":"It seems unfair that I always wash the dishes.","vi":"Cứ nhắc tôi rửa bát mãi thì có vẻ không công bằng.","audioKind":"ex"},{"en":"Unfair hiring practices can prevent qualified applicants from accessing employment opportunities and reduce diversity in the workplace.","vi":"Những quy trình tuyển dụng bất công có thể ngăn cản các ứng viên đủ điều kiện tiếp cận cơ hội việc làm và làm giảm sự đa dạng nơi công sở.","audioKind":"ex2"}],"collocations":[{"en":"unfair treatment","vi":"đối xử bất công"},{"en":"unfair advantage","vi":"lợi thế không công bằng"},{"en":"unfair competition","vi":"cạnh tranh không lành mạnh"},{"en":"unfair to someone","vi":"bất công với ai"}],"wordFamily":["fair (adj.)","unfairly (adv.)","unfairness (n.)","fairness (n.)"],"synonyms":["unjust","inequitable"],"antonyms":["fair","just"],"tipVi":"Biểu thị \"bất công với ai\" dùng unfair to someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_character', 'en-b1-13', 'character', '/ˈkærəktər/', 'B1', 'tính cách; phẩm chất; nét đặc sắc; nhân vật; ký tự; chữ viết', 'n.', 'characteristic (adj.), characteristically (adv.), characterise (v.), characterisation (n.)', 'Đồng nghĩa: personality', 'Nghĩa "nhân vật, ký tự" là danh từ đếm được; nghĩa "phẩm chất tổng thể" thường là danh từ không đếm được.', 'Her cheerful character makes even rainy mornings feel brighter.', NULL, 'Tính cách vui tươi của cô ấy làm cho ngay cả những buổi sáng mưa gió cũng trở nên tươi sáng hơn.', '{"wordId":"character","ukIpa":"/ˈkærəktə/","usIpa":"/ˈkærəktər/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the qualities that make someone or something distinctive","vi":"tính cách; phẩm chất; nét đặc sắc"},{"pos":"n.","en":"a person represented in a story, play, or film","vi":"nhân vật"},{"pos":"n.","en":"a written or printed symbol, such as a letter","vi":"ký tự; chữ viết"}],"examples":[{"en":"Her cheerful character makes even rainy mornings feel brighter.","vi":"Tính cách vui tươi của cô ấy làm cho ngay cả những buổi sáng mưa gió cũng trở nên tươi sáng hơn.","audioKind":"ex"},{"en":"Preserving historic buildings helps cities retain their distinctive character while adapting to modern economic demands.","vi":"Việc bảo tồn các tòa nhà lịch sử giúp các thành phố giữ gìn nét đặc sắc riêng biệt của mình trong khi vẫn thích ứng với các nhu cầu kinh tế hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"main character","vi":"nhân vật chính"},{"en":"strength of character","vi":"phẩm chất kiên cường"},{"en":"distinctive character","vi":"nét đặc sắc riêng"},{"en":"Chinese characters","vi":"chữ Hán"}],"wordFamily":["characteristic (adj.)","characteristically (adv.)","characterise (v.)","characterisation (n.)"],"synonyms":["personality"],"antonyms":[],"tipVi":"Nghĩa \"nhân vật, ký tự\" là danh từ đếm được; nghĩa \"phẩm chất tổng thể\" thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_selfish', 'en-b1-13', 'selfish', '/ˈselfɪʃ/', 'B1', 'ích kỷ; chỉ biết nghĩ đến bản thân', 'adj.', 'selfishly (adv.), selfishness (n.), selfless (adj.)', 'Đồng nghĩa: self-centred · Trái nghĩa: selfless, unselfish', 'Khi muốn nhận xét hành động của ai là ích kỷ, dùng cấu trúc It is selfish of sb to do.', 'It was selfish to take the whole cake.', NULL, 'Thật ích kỷ khi ăn hết cả cái bánh.', '{"wordId":"selfish","ukIpa":"/ˈselfɪʃ/","usIpa":"/ˈselfɪʃ/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"Caring about your own needs without considering other people","vi":"ích kỷ; chỉ biết nghĩ đến bản thân"}],"examples":[{"en":"It was selfish to take the whole cake.","vi":"Thật ích kỷ khi ăn hết cả cái bánh.","audioKind":"ex"},{"en":"Selfish behaviour in shared housing can create tension and undermine trust among residents over time.","vi":"Hành vi ích kỷ khi ở chung nhà có thể tạo ra sự căng thẳng và dần làm sứt mẻ lòng tin giữa những người cùng thuê trọ.","audioKind":"ex2"}],"collocations":[{"en":"selfish behaviour","vi":"hành vi ích kỷ"},{"en":"selfish motives","vi":"động cơ ích kỷ"},{"en":"selfish of someone","vi":"ai đó thật ích kỷ khi làm gì"}],"wordFamily":["selfishly (adv.)","selfishness (n.)","selfless (adj.)"],"synonyms":["self-centred"],"antonyms":["selfless","unselfish"],"tipVi":"Khi muốn nhận xét hành động của ai là ích kỷ, dùng cấu trúc It is selfish of sb to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_express', 'en-b1-13', 'express', '/ɪkˈspres/', 'B1', 'bày tỏ; thể hiện; diễn đạt; nhanh; hỏa tốc; rõ ràng; tường minh', 'v.', 'expression (n.), expressive (adj.), expressively (adv.)', 'Đồng nghĩa: convey, communicate', 'express khi làm động từ sẽ đi thẳng với tân ngữ, ví dụ như express your views.', 'Leah expressed her thanks with a warm smile.', NULL, 'Leah bày tỏ lòng biết ơn của mình bằng một nụ cười ấm áp.', '{"wordId":"express","ukIpa":"/ɪkˈspres/","usIpa":"/ɪkˈspres/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"Show or communicate a thought, feeling, or opinion.","vi":"bày tỏ; thể hiện; diễn đạt"},{"pos":"adj.","en":"Providing a faster service than usual.","vi":"nhanh; hỏa tốc"},{"pos":"adj.","en":"Clearly and directly stated.","vi":"rõ ràng; tường minh"}],"examples":[{"en":"Leah expressed her thanks with a warm smile.","vi":"Leah bày tỏ lòng biết ơn của mình bằng một nụ cười ấm áp.","audioKind":"ex"},{"en":"Schools should provide opportunities for students to express their opinions on decisions that affect their education.","vi":"Nhà trường nên tạo cơ hội cho học sinh bày tỏ quan điểm của các em về các quyết định ảnh hưởng đến việc học tập của mình.","audioKind":"ex2"}],"collocations":[{"en":"express concern","vi":"bày tỏ sự lo ngại"},{"en":"express an opinion","vi":"nêu lên quan điểm"},{"en":"express delivery","vi":"dịch vụ chuyển phát hỏa tốc"},{"en":"express permission","vi":"sự cho phép rõ ràng"}],"wordFamily":["expression (n.)","expressive (adj.)","expressively (adv.)"],"synonyms":["convey","communicate"],"antonyms":[],"tipVi":"express khi làm động từ sẽ đi thẳng với tân ngữ, ví dụ như express your views.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_standard', 'en-b1-13', 'standard', '/ˈstændərd/', 'B1', 'tiêu chuẩn; mức độ chất lượng; chuẩn mực; thông thường', 'n.', 'standardise (v.), standardisation (n.), substandard (adj.)', 'Đồng nghĩa: benchmark, norm', 'Đạt tiêu chuẩn dùng meet a standard; mức sống dùng standard of living.', 'The food here is always of a high standard.', NULL, 'Đồ ăn ở đây luôn đạt chất lượng cao.', '{"wordId":"standard","ukIpa":"/ˈstændəd/","usIpa":"/ˈstændərd/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A required or achieved level of quality or performance.","vi":"tiêu chuẩn; mức độ chất lượng"},{"pos":"adj.","en":"Generally accepted, regularly used, or meeting an established requirement.","vi":"chuẩn mực; thông thường"}],"examples":[{"en":"The food here is always of a high standard.","vi":"Đồ ăn ở đây luôn đạt chất lượng cao.","audioKind":"ex"},{"en":"Governments should enforce strict safety standards to ensure that new housing protects residents from avoidable risks.","vi":"Chính phủ nên thực thi các tiêu chuẩn an toàn nghiêm ngặt để đảm bảo nhà ở mới bảo vệ cư dân khỏi những rủi ro có thể tránh được.","audioKind":"ex2"}],"collocations":[{"en":"meet a standard","vi":"đạt tiêu chuẩn"},{"en":"standard of living","vi":"mức sống"},{"en":"safety standards","vi":"tiêu chuẩn an toàn"},{"en":"standard practice","vi":"thực tiễn thông thường"}],"wordFamily":["standardise (v.)","standardisation (n.)","substandard (adj.)"],"synonyms":["benchmark","norm"],"antonyms":[],"tipVi":"Đạt tiêu chuẩn dùng meet a standard; mức sống dùng standard of living.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_punish', 'en-b1-13', 'punish', '/ˈpʌnɪʃ/', 'B1', 'trừng phạt; xử phạt', 'v.', 'punishment (n.), punishable (adj.), punitive (adj.)', 'Đồng nghĩa: penalise · Trái nghĩa: reward', 'punish sb for sth biểu thị ý nghĩa phạt ai vì điều gì.', 'The referee punished the player for breaking the rules.', NULL, 'Trọng tài đã phạt cầu thủ đó vì phạm luật.', '{"wordId":"punish","ukIpa":"/ˈpʌnɪʃ/","usIpa":"/ˈpʌnɪʃ/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"make someone face an unpleasant consequence for doing wrong","vi":"trừng phạt; xử phạt"}],"examples":[{"en":"The referee punished the player for breaking the rules.","vi":"Trọng tài đã phạt cầu thủ đó vì phạm luật.","audioKind":"ex"},{"en":"Schools should explain why behaviour is unacceptable rather than simply punish students without offering guidance.","vi":"Nhà trường nên giải thích lý do tại sao một hành vi nào đó là không thể chấp nhận được thay vì chỉ đơn thuần trừng phạt học sinh mà không đưa ra sự hướng dẫn.","audioKind":"ex2"}],"collocations":[{"en":"punish someone for something","vi":"phạt ai vì điều gì"},{"en":"punish severely","vi":"trừng phạt nghiêm khắc"},{"en":"punish offenders","vi":"xử phạt người vi phạm"}],"wordFamily":["punishment (n.)","punishable (adj.)","punitive (adj.)"],"synonyms":["penalise"],"antonyms":["reward"],"tipVi":"punish sb for sth biểu thị ý nghĩa phạt ai vì điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gentleman', 'en-b1-13', 'gentleman', '/ˈdʒentlmən/', 'B1', 'quý ông; người lịch sự; ông; quý ông (cách gọi lịch sự trang trọng)', 'n.', 'gentlemanly (adj.)', NULL, 'Dạng số nhiều là gentlemen; cách gọi trang trọng khi nhắc đến nam giới không nhất thiết phải nhấn mạnh vào phẩm hạnh.', 'A gentleman held the door open for us.', NULL, 'Một quý ông đã giữ cửa mở cho chúng tôi.', '{"wordId":"gentleman","ukIpa":"/ˈdʒentlmən/","usIpa":"/ˈdʒentlmən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A man who behaves politely and considers other people.","vi":"quý ông; người lịch sự"},{"pos":"n.","en":"A polite or formal way to refer to a man.","vi":"ông; quý ông (cách gọi lịch sự trang trọng)"}],"examples":[{"en":"A gentleman held the door open for us.","vi":"Một quý ông đã giữ cửa mở cho chúng tôi.","audioKind":"ex"},{"en":"The elderly gentleman described how public transport had improved his independence and access to community activities.","vi":"Quý ông lớn tuổi đã mô tả cách mà giao thông công cộng cải thiện tính tự lập của ông và giúp ông dễ dàng tham gia các hoạt động cộng đồng hơn.","audioKind":"ex2"}],"collocations":[{"en":"a perfect gentleman","vi":"một quý ông hoàn hảo"},{"en":"an elderly gentleman","vi":"một quý ông lớn tuổi"},{"en":"ladies and gentlemen","vi":"kính thưa quý ông quý bà"}],"wordFamily":["gentlemanly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là gentlemen; cách gọi trang trọng khi nhắc đến nam giới không nhất thiết phải nhấn mạnh vào phẩm hạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_equal', 'en-b1-13', 'equal', '/ˈiːkwəl/', 'B1', 'bằng nhau; bình đẳng; bằng; tương đương với; người ngang hàng; đối thủ tương đương', 'adj.', 'equality (n.), equally (adv.), unequal (adj.), equalise (v.)', 'Trái nghĩa: unequal', 'Tính từ thường đi với giới từ to; động từ equal đi trực tiếp với tân ngữ mà không cần thêm to.', 'We divided the cake into equal pieces for everyone.', NULL, 'Chúng tôi chia chiếc bánh thành những phần bằng nhau cho mọi người.', '{"wordId":"equal","ukIpa":"/ˈiːkwəl/","usIpa":"/ˈiːkwəl/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"The same in amount, value, status, or opportunity.","vi":"bằng nhau; bình đẳng"},{"pos":"v.","en":"To be the same in quantity, value, or quality.","vi":"bằng; tương đương với"},{"pos":"n.","en":"Someone with the same status, ability, or rights as another.","vi":"người ngang hàng; đối thủ tương đương"}],"examples":[{"en":"We divided the cake into equal pieces for everyone.","vi":"Chúng tôi chia chiếc bánh thành những phần bằng nhau cho mọi người.","audioKind":"ex"},{"en":"Governments should ensure that children from all backgrounds have equal access to quality education and essential healthcare.","vi":"Chính phủ nên đảm bảo rằng trẻ em từ mọi hoàn cảnh đều có cơ hội tiếp cận bình đẳng với nền giáo dục chất lượng và dịch vụ chăm sóc sức khỏe thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"equal opportunities","vi":"cơ hội bình đẳng"},{"en":"equal access","vi":"quyền tiếp cận bình đẳng"},{"en":"equal to","vi":"bằng với; đủ sức đảm nhận"},{"en":"treat as an equal","vi":"đối xử như người ngang hàng"}],"wordFamily":["equality (n.)","equally (adv.)","unequal (adj.)","equalise (v.)"],"synonyms":[],"antonyms":["unequal"],"tipVi":"Tính từ thường đi với giới từ to; động từ equal đi trực tiếp với tân ngữ mà không cần thêm to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_donate', 'en-b1-13', 'donate', '/ˈdoʊneɪt/', 'B1', 'quyên góp; hiến tặng', 'v.', 'donation (n.), donor (n.)', 'Đồng nghĩa: contribute', 'Dùng donate something to someone, không dùng cấu trúc hai tân ngữ.', 'We donate our spare blankets to the local shelter.', NULL, 'Chúng tôi quyên góp những chiếc chăn thừa cho trung tâm bảo trợ xã hội địa phương.', '{"wordId":"donate","ukIpa":"/dəʊˈneɪt/","usIpa":"/ˈdoʊneɪt/","cefr":"B1","topic":"society","senses":[{"pos":"v.","en":"To give money, goods, or blood to help others","vi":"quyên góp; hiến tặng"}],"examples":[{"en":"We donate our spare blankets to the local shelter.","vi":"Chúng tôi quyên góp những chiếc chăn thừa cho trung tâm bảo trợ xã hội địa phương.","audioKind":"ex"},{"en":"Businesses can reduce food waste by donating surplus products to charities that support vulnerable families.","vi":"Các doanh nghiệp có thể giảm lượng thực phẩm thừa bằng cách tặng các sản phẩm dư thừa cho các tổ chức từ thiện hỗ trợ các gia đình khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"donate money to charity","vi":"quyên góp tiền cho từ thiện"},{"en":"donate blood","vi":"hiến máu"},{"en":"donate organs","vi":"hiến tạng"}],"wordFamily":["donation (n.)","donor (n.)"],"synonyms":["contribute"],"antonyms":[],"tipVi":"Dùng donate something to someone, không dùng cấu trúc hai tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nation', 'en-b1-13', 'nation', '/ˈneɪʃən/', 'B1', 'quốc gia; đất nước và toàn thể người dân; dân tộc (gắn kết bởi lịch sử, văn hóa hoặc ngôn ngữ chung)', 'n.', 'national (adj.), nationality (n.), nationalism (n.), nationally (adv.)', 'Đồng nghĩa: country', 'nation nhấn mạnh vào quốc gia và con người, trong khi state thường nhấn mạnh vào chính quyền hoặc thực thể chính trị.', 'Fans across the nation celebrated the team''s victory.', NULL, 'Người hâm mộ trên khắp cả nước đã ăn mừng chiến thắng của đội bóng.', '{"wordId":"nation","ukIpa":"/ˈneɪʃən/","usIpa":"/ˈneɪʃən/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"A country considered together with its people","vi":"quốc gia; đất nước và toàn thể người dân"},{"pos":"n.","en":"A people united by shared history, culture, or language","vi":"dân tộc (gắn kết bởi lịch sử, văn hóa hoặc ngôn ngữ chung)"}],"examples":[{"en":"Fans across the nation celebrated the team''s victory.","vi":"Người hâm mộ trên khắp cả nước đã ăn mừng chiến thắng của đội bóng.","audioKind":"ex"},{"en":"Wealthier nations should support international efforts to improve access to clean water in poorer regions.","vi":"Các quốc gia giàu có hơn nên hỗ trợ các nỗ lực quốc tế nhằm cải thiện khả năng tiếp cận nước sạch ở các khu vực nghèo khó hơn.","audioKind":"ex2"}],"collocations":[{"en":"developing nation","vi":"quốc gia đang phát triển"},{"en":"the entire nation","vi":"toàn thể quốc gia"},{"en":"host nation","vi":"quốc gia đăng cai"},{"en":"nation building","vi":"xây dựng đất nước"}],"wordFamily":["national (adj.)","nationality (n.)","nationalism (n.)","nationally (adv.)"],"synonyms":["country"],"antonyms":[],"tipVi":"nation nhấn mạnh vào quốc gia và con người, trong khi state thường nhấn mạnh vào chính quyền hoặc thực thể chính trị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_youth', 'en-b1-13', 'youth', '/juːθ/', 'B1', 'thời thanh thiếu niên; tuổi trẻ; giới trẻ; thanh niên; chàng trai trẻ', 'n.', 'youthful (adj.), youthfulness (n.)', 'Trái nghĩa: old age', 'Chỉ tuổi trẻ thường không đếm được; a youth dùng để chỉ một nam thanh niên.', 'My grandmother spent her youth in a seaside village.', NULL, 'Bà tôi đã trải qua tuổi thanh xuân của mình ở một ngôi làng ven biển.', '{"wordId":"youth","ukIpa":"/juːθ/","usIpa":"/juːθ/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the period of life when someone is young","vi":"thời thanh thiếu niên; tuổi trẻ"},{"pos":"n.","en":"young people considered as a group","vi":"giới trẻ; thanh niên"},{"pos":"n.","en":"a young man, especially a teenager","vi":"chàng trai trẻ"}],"examples":[{"en":"My grandmother spent her youth in a seaside village.","vi":"Bà tôi đã trải qua tuổi thanh xuân của mình ở một ngôi làng ven biển.","audioKind":"ex"},{"en":"Investment in youth services can give young people valuable skills and strengthen their sense of belonging.","vi":"Việc đầu tư vào các dịch vụ dành cho giới trẻ có thể mang lại cho những người trẻ tuổi các kỹ năng quý giá và củng cố ý thức thuộc về cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"in one''s youth","vi":"thời trẻ; khi còn trẻ"},{"en":"youth unemployment","vi":"tình trạng thất nghiệp của thanh niên"},{"en":"youth centre","vi":"trung tâm thanh thiếu niên"}],"wordFamily":["youthful (adj.)","youthfulness (n.)"],"synonyms":[],"antonyms":["old age"],"tipVi":"Chỉ tuổi trẻ thường không đếm được; a youth dùng để chỉ một nam thanh niên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_custom', 'en-b1-13', 'custom', '/ˈkʌstəm/', 'B1', 'phong tục; tập quán; thói quen truyền thống; hàng đặt riêng (được làm theo yêu cầu riêng của khách hàng); sự ủng hộ; sự chiếu cố (khách hàng dành cho một cửa hàng hoặc công ty)', 'n.', 'customary (adj.), customarily (adv.), customise (v.), customisation (n.)', 'Đồng nghĩa: tradition, practice', 'custom mang nghĩa là phong tục hoặc thói quen; ngoài ra, dạng số nhiều customs còn có thể chỉ cơ quan hải quan.', 'Sharing a meal is an important custom in our family.', NULL, 'Cùng nhau quây quần bên bữa ăn là một tập quán quan trọng trong gia đình chúng tôi.', '{"wordId":"custom","ukIpa":"/ˈkʌstəm/","usIpa":"/ˈkʌstəm/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"a traditional or usual way of behaving","vi":"phong tục; tập quán; thói quen truyền thống"},{"pos":"adj.","en":"made to meet a particular customer''s needs","vi":"hàng đặt riêng (được làm theo yêu cầu riêng của khách hàng)"},{"pos":"n.","en":"the business customers give to a shop or company","vi":"sự ủng hộ; sự chiếu cố (khách hàng dành cho một cửa hàng hoặc công ty)"}],"examples":[{"en":"Sharing a meal is an important custom in our family.","vi":"Cùng nhau quây quần bên bữa ăn là một tập quán quan trọng trong gia đình chúng tôi.","audioKind":"ex"},{"en":"Schools can introduce children to local customs while encouraging respect for traditions from other cultures.","vi":"Nhà trường có thể giới thiệu cho trẻ em các phong tục địa phương đồng thời khuyến khích sự tôn trọng đối với truyền thống từ các nền văn hóa khác.","audioKind":"ex2"}],"collocations":[{"en":"local customs","vi":"phong tục địa phương"},{"en":"an ancient custom","vi":"tập quán lâu đời"},{"en":"custom furniture","vi":"đồ nội thất làm theo yêu cầu"},{"en":"regular custom","vi":"sự ủng hộ thường xuyên"}],"wordFamily":["customary (adj.)","customarily (adv.)","customise (v.)","customisation (n.)"],"synonyms":["tradition","practice"],"antonyms":[],"tipVi":"custom mang nghĩa là phong tục hoặc thói quen; ngoài ra, dạng số nhiều customs còn có thể chỉ cơ quan hải quan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_murderer', 'en-b1-13', 'murderer', '/ˈmɝːdərər/', 'B1', 'kẻ giết người; kẻ thủ ác', 'n.', 'murder (n.), murder (v.), murderous (adj.)', NULL, 'Chỉ kẻ cố ý tước đoạt mạng sống người khác một cách phi pháp; killer có phạm vi nghĩa rộng hơn.', 'The detective finally identified the murderer in the novel.', NULL, 'Cuối cùng viên thám tử cũng vạch mặt được kẻ giết người trong tiểu thuyết.', '{"wordId":"murderer","ukIpa":"/ˈmɜːdərə/","usIpa":"/ˈmɝːdərər/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"Someone who deliberately and unlawfully kills another person.","vi":"kẻ giết người; kẻ thủ ác"}],"examples":[{"en":"The detective finally identified the murderer in the novel.","vi":"Cuối cùng viên thám tử cũng vạch mặt được kẻ giết người trong tiểu thuyết.","audioKind":"ex"},{"en":"Documentaries about convicted murderers should avoid sensationalism and consider the feelings of victims'' families.","vi":"Các bộ phim tài liệu về những kẻ sát nhân đã bị kết án nên tránh việc giật gân hóa và cần cân nhắc cảm xúc của gia đình nạn nhân.","audioKind":"ex2"}],"collocations":[{"en":"convicted murderer","vi":"kẻ sát nhân đã bị kết án"},{"en":"identify the murderer","vi":"xác định kẻ giết người"},{"en":"catch a murderer","vi":"bắt giữ kẻ giết người"}],"wordFamily":["murder (n.)","murder (v.)","murderous (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ kẻ cố ý tước đoạt mạng sống người khác một cách phi pháp; killer có phạm vi nghĩa rộng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trust', 'en-b1-13', 'trust', '/trʌst/', 'B1', 'sự tin tưởng; lòng tin; tin tưởng; tin cậy; quỹ tín thác; tổ chức quản lý tài sản thay cho người khác', 'n.', 'trustworthy (adj.), trusting (adj.), distrust (n.)', 'Đồng nghĩa: confidence, faith · Trái nghĩa: distrust, mistrust', 'Cấu trúc trust sb to do sth diễn tả việc tin tưởng ai đó sẽ thực hiện một cách đáng tin cậy.', 'I trust my neighbour to feed our cat.', NULL, 'Tôi tin tưởng nhờ người hàng xóm cho con mèo của chúng tôi ăn.', '{"wordId":"trust","ukIpa":"/trʌst/","usIpa":"/trʌst/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"Belief that someone or something is honest, reliable, or safe.","vi":"sự tin tưởng; lòng tin"},{"pos":"v.","en":"To believe someone or something is honest, reliable, or safe.","vi":"tin tưởng; tin cậy"},{"pos":"n.","en":"An arrangement or organisation managing money or property for others.","vi":"quỹ tín thác; tổ chức quản lý tài sản thay cho người khác"}],"examples":[{"en":"I trust my neighbour to feed our cat.","vi":"Tôi tin tưởng nhờ người hàng xóm cho con mèo của chúng tôi ăn.","audioKind":"ex"},{"en":"Public trust in scientific advice depends partly on how clearly researchers communicate uncertainty and evidence.","vi":"Sự tin tưởng của công chúng đối với các lời khuyên khoa học phụ thuộc một phần vào mức độ rõ ràng của các nhà nghiên cứu khi truyền đạt về tính không chắc chắn và các bằng chứng.","audioKind":"ex2"}],"collocations":[{"en":"build trust","vi":"xây dựng lòng tin"},{"en":"trust someone to do something","vi":"tin tưởng ai đó làm việc gì"},{"en":"mutual trust","vi":"sự tin tưởng lẫn nhau"},{"en":"a charitable trust","vi":"quỹ từ thiện"}],"wordFamily":["trustworthy (adj.)","trusting (adj.)","distrust (n.)"],"synonyms":["confidence","faith"],"antonyms":["distrust","mistrust"],"tipVi":"Cấu trúc trust sb to do sth diễn tả việc tin tưởng ai đó sẽ thực hiện một cách đáng tin cậy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_generous', 'en-b1-13', 'generous', '/ˈdʒenərəs/', 'B1', 'hào phóng; rộng lượng; dồi dào; phong phú; rộng rãi', 'adj.', 'generosity (n.), generously (adv.)', 'Đồng nghĩa: giving, liberal · Trái nghĩa: mean, stingy', 'Cụm từ be generous with sth có nghĩa là hào phóng về mặt nào đó.', 'Our generous neighbour shared her fresh vegetables with us.', NULL, 'Người hàng xóm hào phóng của chúng tôi đã chia sẻ rau tươi cho chúng tôi.', '{"wordId":"generous","ukIpa":"/ˈdʒenərəs/","usIpa":"/ˈdʒenərəs/","cefr":"B1","topic":"society","senses":[{"pos":"adj.","en":"willing to give money, time, or help freely","vi":"hào phóng; rộng lượng"},{"pos":"adj.","en":"larger or more plentiful than usual or expected","vi":"dồi dào; phong phú; rộng rãi"}],"examples":[{"en":"Our generous neighbour shared her fresh vegetables with us.","vi":"Người hàng xóm hào phóng của chúng tôi đã chia sẻ rau tươi cho chúng tôi.","audioKind":"ex"},{"en":"Generous donations from local businesses can help community centres provide affordable activities for children and older residents.","vi":"Sự đóng góp hào phóng từ các doanh nghiệp địa phương có thể giúp các trung tâm cộng đồng cung cấp các hoạt động giá cả phải chăng cho trẻ em và người cao tuổi.","audioKind":"ex2"}],"collocations":[{"en":"generous donation","vi":"khoản đóng góp hào phóng"},{"en":"generous portion","vi":"phần ăn thị soạn; phần ăn đầy đặn"},{"en":"generous with your time","vi":"hào phóng về thời gian"}],"wordFamily":["generosity (n.)","generously (adv.)"],"synonyms":["giving","liberal"],"antonyms":["mean","stingy"],"tipVi":"Cụm từ be generous with sth có nghĩa là hào phóng về mặt nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_atmosphere', 'en-b1-13', 'atmosphere', '/ˈætməsfɪr/', 'B1', 'bầu không khí; không gian; bầu khí quyển', 'n.', 'atmospheric (adj.)', NULL, 'Biểu thị một bầu không khí nào đó thường dùng an atmosphere; khí quyển Trái Đất dùng the atmosphere.', 'Soft lighting gave the little restaurant a relaxed atmosphere.', NULL, 'Ánh đèn dịu nhẹ mang lại cho nhà hàng nhỏ một bầu không khí thư thái.', '{"wordId":"atmosphere","ukIpa":"/ˈætməsfɪə/","usIpa":"/ˈætməsfɪr/","cefr":"B1","topic":"society","senses":[{"pos":"n.","en":"the feeling or mood of a place or situation","vi":"bầu không khí; không gian"},{"pos":"n.","en":"the mixture of gases surrounding a planet","vi":"bầu khí quyển"}],"examples":[{"en":"Soft lighting gave the little restaurant a relaxed atmosphere.","vi":"Ánh đèn dịu nhẹ mang lại cho nhà hàng nhỏ một bầu không khí thư thái.","audioKind":"ex"},{"en":"A supportive classroom atmosphere encourages students to ask questions and participate more actively in discussions.","vi":"Bầu không khí lớp học mang tính hỗ trợ khuyến khích học sinh đặt câu hỏi và tham gia thảo luận tích cực hơn.","audioKind":"ex2"}],"collocations":[{"en":"relaxed atmosphere","vi":"bầu không khí thư thái"},{"en":"create an atmosphere","vi":"tạo dựng bầu không khí"},{"en":"Earth''s atmosphere","vi":"bầu khí quyển Trái Đất"}],"wordFamily":["atmospheric (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Biểu thị một bầu không khí nào đó thường dùng an atmosphere; khí quyển Trái Đất dùng the atmosphere.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_13_1', 'en-b1-13', 'Cách dùng “gentleman” (n.) — quý ông; người lịch sự', 'a perfect gentleman  ·  an elderly gentleman  ·  ladies and gentlemen', 'Dạng số nhiều là gentlemen; cách gọi trang trọng khi nhắc đến nam giới không nhất thiết phải nhấn mạnh vào phẩm hạnh.', 'Họ từ (Word Family): gentlemanly (adj.)', '[{"hanzi":"A gentleman held the door open for us.","pinyin":"","meaning":"Một quý ông đã giữ cửa mở cho chúng tôi."},{"hanzi":"The elderly gentleman described how public transport had improved his independence and access to community activities.","pinyin":"","meaning":"Quý ông lớn tuổi đã mô tả cách mà giao thông công cộng cải thiện tính tự lập của ông và giúp ông dễ dàng tham gia các hoạt động cộng đồng hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_13_2', 'en-b1-13', 'Cách dùng “nation” (n.) — quốc gia; đất nước và toàn thể người dân', 'developing nation  ·  the entire nation  ·  host nation', 'nation nhấn mạnh vào quốc gia và con người, trong khi state thường nhấn mạnh vào chính quyền hoặc thực thể chính trị.', 'Họ từ (Word Family): national (adj.), nationality (n.), nationalism (n.), nationally (adv.) | Đồng nghĩa: country', '[{"hanzi":"Fans across the nation celebrated the team''s victory.","pinyin":"","meaning":"Người hâm mộ trên khắp cả nước đã ăn mừng chiến thắng của đội bóng."},{"hanzi":"Wealthier nations should support international efforts to improve access to clean water in poorer regions.","pinyin":"","meaning":"Các quốc gia giàu có hơn nên hỗ trợ các nỗ lực quốc tế nhằm cải thiện khả năng tiếp cận nước sạch ở các khu vực nghèo khó hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_13_3', 'en-b1-13', 'Cách dùng “custom” (n.) — phong tục; tập quán; thói quen truyền thống', 'local customs  ·  an ancient custom  ·  custom furniture', 'custom mang nghĩa là phong tục hoặc thói quen; ngoài ra, dạng số nhiều customs còn có thể chỉ cơ quan hải quan.', 'Họ từ (Word Family): customary (adj.), customarily (adv.), customise (v.), customisation (n.) | Đồng nghĩa: tradition, practice', '[{"hanzi":"Sharing a meal is an important custom in our family.","pinyin":"","meaning":"Cùng nhau quây quần bên bữa ăn là một tập quán quan trọng trong gia đình chúng tôi."},{"hanzi":"Schools can introduce children to local customs while encouraging respect for traditions from other cultures.","pinyin":"","meaning":"Nhà trường có thể giới thiệu cho trẻ em các phong tục địa phương đồng thời khuyến khích sự tôn trọng đối với truyền thống từ các nền văn hóa khác."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_13_4', 'en-b1-13', 'Cách dùng “character” (n.) — tính cách; phẩm chất; nét đặc sắc', 'main character  ·  strength of character  ·  distinctive character', 'Nghĩa "nhân vật, ký tự" là danh từ đếm được; nghĩa "phẩm chất tổng thể" thường là danh từ không đếm được.', 'Họ từ (Word Family): characteristic (adj.), characteristically (adv.), characterise (v.), characterisation (n.) | Đồng nghĩa: personality', '[{"hanzi":"Her cheerful character makes even rainy mornings feel brighter.","pinyin":"","meaning":"Tính cách vui tươi của cô ấy làm cho ngay cả những buổi sáng mưa gió cũng trở nên tươi sáng hơn."},{"hanzi":"Preserving historic buildings helps cities retain their distinctive character while adapting to modern economic demands.","pinyin":"","meaning":"Việc bảo tồn các tòa nhà lịch sử giúp các thành phố giữ gìn nét đặc sắc riêng biệt của mình trong khi vẫn thích ứng với các nhu cầu kinh tế hiện đại."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_13_1', 'en-b1-13', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_1_1', 'ten_b1_13_1', 'general', 'There was general agreement that the kitchen needed repainting.', 'There was general agreement that the kitchen needed repainting.', '/ˈdʒenərəl/', 'Đã có sự đồng thuận chung rằng nhà bếp cần phải được sơn lại.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_1_2', 'ten_b1_13_1', 'blame', 'Don''t blame me for the broken kitchen chair.', 'Don''t blame me for the broken kitchen chair.', '/bleɪm/', 'Đừng có đổ lỗi cho tôi vì cái ghế bếp bị gãy đó nhé.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_1_3', 'ten_b1_13_1', 'permitted', 'We were permitted to feed the goats at noon.', 'We were permitted to feed the goats at noon.', '/pɚˈmɪtɪd/', 'Chúng tôi đã được phép cho lũ dê ăn vào lúc trưa đứng bóng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_1_4', 'ten_b1_13_1', 'mate', 'I''m meeting a mate for lunch near the station.', 'I''m meeting a mate for lunch near the station.', '/meɪt/', 'Tôi chuẩn bị gặp một người bạn để ăn trưa gần nhà ga.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_1_5', 'ten_b1_13_1', 'citizen', 'My aunt became a citizen after living here for years.', 'My aunt became a citizen after living here for years.', '/ˈsɪtɪzən/', 'Dì của tôi đã trở thành công dân sau khi sinh sống ở đây nhiều năm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_1_6', 'ten_b1_13_1', 'worldwide', 'The band''s new song became a worldwide hit.', 'The band''s new song became a worldwide hit.', '/ˌwɝːldˈwaɪd/', 'Bài hát mới của ban nhạc đã trở thành bản hit trên toàn cầu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_1_7', 'ten_b1_13_1', 'shelter', 'We found shelter under a bridge during the storm.', 'We found shelter under a bridge during the storm.', '/ˈʃeltər/', 'Chúng tôi đã tìm chỗ trú ẩn dưới một cây cầu trong cơn giông bão.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_1_8', 'ten_b1_13_1', 'expression', 'He sent flowers as an expression of his gratitude.', 'He sent flowers as an expression of his gratitude.', '/ɪkˈspreʃən/', 'Anh ấy gửi hoa như một cách để bày tỏ lòng biết ơn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_13_1_1', 'en-b1-13', 'ten_b1_13_1', 'listening', 'listening', 'There was general agreement that the kitchen needed repainting.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cuối cùng viên thám tử cũng vạch mặt được kẻ giết người trong tiểu thuyết.","Tôi tin tưởng nhờ người hàng xóm cho con mèo của chúng tôi ăn.","Đã có sự đồng thuận chung rằng nhà bếp cần phải được sơn lại.","Người hâm mộ trên khắp cả nước đã ăn mừng chiến thắng của đội bóng."]'::jsonb, 2, 'There was general agreement that the kitchen needed repainting. → Đã có sự đồng thuận chung rằng nhà bếp cần phải được sơn lại.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_13_1_2', 'en-b1-13', 'ten_b1_13_1', 'listening', 'listening', 'Don''t blame me for the broken kitchen chair.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi chuẩn bị gặp một người bạn để ăn trưa gần nhà ga.","Leah bày tỏ lòng biết ơn của mình bằng một nụ cười ấm áp.","Đừng có đổ lỗi cho tôi vì cái ghế bếp bị gãy đó nhé.","Trọng tài đã phạt cầu thủ đó vì phạm luật."]'::jsonb, 2, 'Don''t blame me for the broken kitchen chair. → Đừng có đổ lỗi cho tôi vì cái ghế bếp bị gãy đó nhé.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_13_1_3', 'en-b1-13', 'ten_b1_13_1', 'listening', 'listening', 'We were permitted to feed the goats at noon.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Leah bày tỏ lòng biết ơn của mình bằng một nụ cười ấm áp.","Trọng tài đã phạt cầu thủ đó vì phạm luật.","Chúng tôi đã được phép cho lũ dê ăn vào lúc trưa đứng bóng.","Chúng tôi quyên góp những chiếc chăn thừa cho trung tâm bảo trợ xã hội địa phương."]'::jsonb, 2, 'We were permitted to feed the goats at noon. → Chúng tôi đã được phép cho lũ dê ăn vào lúc trưa đứng bóng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_13_2', 'en-b1-13', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_2_1', 'ten_b1_13_2', 'general', 'Although the general standard of education has improved, significant differences remain between urban and rural schools.', 'Although the general standard of education has improved, significant differences remain between urban and rural schools.', '/ˈdʒenərəl/', 'Mặc dù mặt bằng chung về giáo dục đã được nâng cao, những khác biệt đáng kể vẫn tồn tại giữa các trường học thành thị và nông thôn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_2_2', 'ten_b1_13_2', 'blame', 'It is unfair to blame individuals alone for environmental problems caused partly by industrial activity.', 'It is unfair to blame individuals alone for environmental problems caused partly by industrial activity.', '/bleɪm/', 'Thật bất công khi chỉ quy trách nhiệm cho các cá nhân đối với các vấn đề môi trường mà một phần là do hoạt động công nghiệp gây ra.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_2_3', 'ten_b1_13_2', 'permitted', 'Students should be permitted to use digital tools when these genuinely support learning rather than distract from it.', 'Students should be permitted to use digital tools when these genuinely support learning rather than distract from it.', '/pɚˈmɪtɪd/', 'Học sinh nên được phép sử dụng các công cụ kỹ thuật số khi chúng thực sự hỗ trợ việc học tập thay vì làm xao lãng điều đó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_2_4', 'ten_b1_13_2', 'mate', 'Some bird species stay with the same mate for years, sharing responsibility for raising their young.', 'Some bird species stay with the same mate for years, sharing responsibility for raising their young.', '/meɪt/', 'Một số loài chim gắn bó với cùng một bạn đời trong nhiều năm, cùng chia sẻ trách nhiệm nuôi dưỡng con non.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_2_5', 'ten_b1_13_2', 'citizen', 'Every citizen should have access to reliable public services, regardless of income or place of residence.', 'Every citizen should have access to reliable public services, regardless of income or place of residence.', '/ˈsɪtɪzən/', 'Mỗi công dân đều nên được tiếp cận các dịch vụ công đáng tin cậy, bất kể thu nhập hay nơi cư trú.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_13_2_6', 'ten_b1_13_2', 'worldwide', 'Worldwide cooperation is essential for reducing carbon emissions and protecting communities from the effects of climate change.', 'Worldwide cooperation is essential for reducing carbon emissions and protecting communities from the effects of climate change.', '/ˌwɝːldˈwaɪd/', 'Hợp tác toàn cầu là điều cần thiết để giảm lượng khí thải carbon và bảo vệ cộng đồng trước các tác động của biến đổi khí hậu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_13_2_1', 'en-b1-13', 'ten_b1_13_2', 'listening', 'listening', 'Although the general standard of education has improved, significant differences remain between urban and rural schools.', NULL, 'Trong câu vừa nghe, từ “general” mang nghĩa nào sau đây?', '["chung; phổ biến; toàn thể","độc mộc; thuyền chèo tay","gây ấn tượng sâu sắc; hùng vĩ; xuất sắc; đáng nể","sự phản đối mạnh mẽ; cuộc biểu tình, cuộc kháng nghị"]'::jsonb, 0, '“general” (/ˈdʒenərəl/): chung; phổ biến; toàn thể. Câu đầy đủ: Although the general standard of education has improved, significant differences remain between urban and rural schools.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_13_2_2', 'en-b1-13', 'ten_b1_13_2', 'listening', 'listening', 'It is unfair to blame individuals alone for environmental problems caused partly by industrial activity.', NULL, 'Trong câu vừa nghe, từ “blame” mang nghĩa nào sau đây?', '["tù nhân; người bị giam giữ, người bị cầm tù","hôi thối; khó ngửi","đổ lỗi; trách mắng","lưới; vật làm bằng lưới"]'::jsonb, 2, '“blame” (/bleɪm/): đổ lỗi; trách mắng. Câu đầy đủ: It is unfair to blame individuals alone for environmental problems caused partly by industrial activity.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
