INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_13_2', 'en-b1-13', NULL, 'comprehensive_test', 'listening', 'Don''t blame me for the broken kitchen chair.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuối cùng viên thám tử cũng vạch mặt được kẻ giết người trong tiểu thuyết.","Người hâm mộ trên khắp cả nước đã ăn mừng chiến thắng của đội bóng.","Bà tôi đã trải qua tuổi thanh xuân của mình ở một ngôi làng ven biển.","Đừng có đổ lỗi cho tôi vì cái ghế bếp bị gãy đó nhé."]'::jsonb, 3, 'Don''t blame me for the broken kitchen chair. → Đừng có đổ lỗi cho tôi vì cái ghế bếp bị gãy đó nhé.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
