INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_13_4', 'en-b1-13', NULL, 'comprehensive_test', 'listening', 'I''m meeting a mate for lunch near the station.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người hàng xóm hào phóng của chúng tôi đã chia sẻ rau tươi cho chúng tôi.","Tôi chuẩn bị gặp một người bạn để ăn trưa gần nhà ga.","Cùng nhau quây quần bên bữa ăn là một tập quán quan trọng trong gia đình chúng tôi.","Đừng có đổ lỗi cho tôi vì cái ghế bếp bị gãy đó nhé."]'::jsonb, 1, 'I''m meeting a mate for lunch near the station. → Tôi chuẩn bị gặp một người bạn để ăn trưa gần nhà ga.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_13_5', 'en-b1-13', NULL, 'comprehensive_test', 'listening', 'citizen', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["công dân","rừng mưa nhiệt đới; rừng mưa","trả lời; hồi âm","cởi quần áo; thay đồ"]'::jsonb, 0, 'citizen (/ˈsɪtɪzən/) → công dân; người dân thành phố; cư dân', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_13_6', 'en-b1-13', NULL, 'comprehensive_test', 'listening', 'The band''s new song became a worldwide hit.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bài hát mới của ban nhạc đã trở thành bản hit trên toàn cầu.","Cuối cùng viên thám tử cũng vạch mặt được kẻ giết người trong tiểu thuyết.","Cứ nhắc tôi rửa bát mãi thì có vẻ không công bằng.","Ánh đèn dịu nhẹ mang lại cho nhà hàng nhỏ một bầu không khí thư thái."]'::jsonb, 0, 'The band''s new song became a worldwide hit. → Bài hát mới của ban nhạc đã trở thành bản hit trên toàn cầu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_13_7', 'en-b1-13', NULL, 'comprehensive_test', 'listening', 'shelter', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự che chở; nơi trú ẩn","niềm vui; sự thích thú","kênh; kênh đào","có xu hướng; thường"]'::jsonb, 0, 'shelter (/ˈʃeltər/) → sự che chở; nơi trú ẩn; nhà tạm; trú ẩn; che chở', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_13_8', 'en-b1-13', NULL, 'comprehensive_test', 'listening', 'He sent flowers as an expression of his gratitude.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy gửi hoa như một cách để bày tỏ lòng biết ơn.","Đừng có đổ lỗi cho tôi vì cái ghế bếp bị gãy đó nhé.","Tôi tin tưởng nhờ người hàng xóm cho con mèo của chúng tôi ăn.","Dì của tôi đã trở thành công dân sau khi sinh sống ở đây nhiều năm."]'::jsonb, 0, 'He sent flowers as an expression of his gratitude. → Anh ấy gửi hoa như một cách để bày tỏ lòng biết ơn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
