INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_13_18', 'en-b1-13', NULL, 'comprehensive_test', 'reading', NULL, 'Although the general standard of education has improved, significant differences remain between urban and rural schools.', 'Dựa vào câu trên, từ “general” có nghĩa phù hợp nhất là gì?', '["chung; phổ biến; toàn thể","sự mua chịu; tín dụng; hình thức trả chậm hoặc vay tiền","anh rể; em rể; anh/em vợ; anh/em chồng","ôn tập; ôn thi"]'::jsonb, 0, 'general: chung; phổ biến; toàn thể; chung chung; đại khái; tổng quát; đại tướng; tướng quân. Dịch cả câu: Mặc dù mặt bằng chung về giáo dục đã được nâng cao, những khác biệt đáng kể vẫn tồn tại giữa các trường học thành thị và nông thôn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_13_19', 'en-b1-13', NULL, 'comprehensive_test', 'reading', NULL, 'It is unfair to blame individuals alone for environmental problems caused partly by industrial activity.', 'Dựa vào câu trên, từ “blame” có nghĩa phù hợp nhất là gì?', '["đổ lỗi; trách mắng","chôn; chôn cất","cảng; thành phố cảng","triệu chứng"]'::jsonb, 0, 'blame: đổ lỗi; trách mắng; trách nhiệm; sự đổ lỗi. Dịch cả câu: Thật bất công khi chỉ quy trách nhiệm cho các cá nhân đối với các vấn đề môi trường mà một phần là do hoạt động công nghiệp gây ra.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_13_20', 'en-b1-13', NULL, 'comprehensive_test', 'reading', NULL, 'Students should be permitted to use digital tools when these genuinely support learning rather than distract from it.', 'Dựa vào câu trên, từ “permitted” có nghĩa phù hợp nhất là gì?', '["được cho phép; được chuẩn y","tập trung; chú trọng","đã ký; có chữ ký","dỡ đồ (khỏi túi, hộp, vali)"]'::jsonb, 0, 'permitted: được cho phép; được chuẩn y. Dịch cả câu: Học sinh nên được phép sử dụng các công cụ kỹ thuật số khi chúng thực sự hỗ trợ việc học tập thay vì làm xao lãng điều đó.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_13_21', 'en-b1-13', NULL, 'comprehensive_test', 'reading', NULL, 'Some bird species stay with the same mate for years, sharing responsibility for raising their young.', 'Dựa vào câu trên, từ “mate” có nghĩa phù hợp nhất là gì?', '["ngưỡng mộ; khâm phục","diễu hành; bước đều","khủng long","bạn bè; bạn đồng hành"]'::jsonb, 3, 'mate: bạn bè; bạn đồng hành; bạn đời của động vật; giao phối. Dịch cả câu: Một số loài chim gắn bó với cùng một bạn đời trong nhiều năm, cùng chia sẻ trách nhiệm nuôi dưỡng con non.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
