INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-14', 'en', 'Bài 14: Thiên nhiên & Thời tiết (1) - CEFR B1', 'CEFR B1', 'B1 · Thiên nhiên', '25 từ vựng Tiếng Anh CEFR B1 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3014, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_freezing', 'en-b1-14', 'freezing', '/ˈfriːzɪŋ/', 'B1', 'lạnh cóng; băng giá; điểm đóng băng', 'adj.', 'freeze (v.), frozen (adj.), freezer (n.)', 'Đồng nghĩa: icy, frigid · Trái nghĩa: hot', 'Cụm ''I''m freezing'' diễn tả cảm giác rất lạnh, không nhất thiết là nhiệt độ ngoài trời đã đạt điểm đóng băng.', 'My hands were freezing after waiting outside for the bus.', NULL, 'Tay tôi lạnh cóng sau khi đứng chờ xe buýt ngoài trời.', '{"wordId":"freezing","ukIpa":"/ˈfriːzɪŋ/","usIpa":"/ˈfriːzɪŋ/","cefr":"B1","topic":"nature","senses":[{"pos":"adj.","en":"Extremely cold, or cold enough for water to become ice.","vi":"lạnh cóng; băng giá"},{"pos":"n.","en":"The temperature at which water turns into ice.","vi":"điểm đóng băng"}],"examples":[{"en":"My hands were freezing after waiting outside for the bus.","vi":"Tay tôi lạnh cóng sau khi đứng chờ xe buýt ngoài trời.","audioKind":"ex"},{"en":"Freezing temperatures can damage water pipes and disrupt essential services, particularly in areas with ageing infrastructure.","vi":"Nhiệt độ băng giá có thể làm hỏng đường ống nước và làm gián đoạn các dịch vụ thiết yếu, đặc biệt là ở những khu vực có cơ sở hạ tầng cũ kỹ.","audioKind":"ex2"}],"collocations":[{"en":"freezing cold","vi":"lạnh cóng"},{"en":"freezing temperatures","vi":"nhiệt độ băng giá"},{"en":"below freezing","vi":"dưới điểm đóng băng"},{"en":"freezing point","vi":"điểm đóng băng"}],"wordFamily":["freeze (v.)","frozen (adj.)","freezer (n.)"],"synonyms":["icy","frigid"],"antonyms":["hot"],"tipVi":"Cụm ''I''m freezing'' diễn tả cảm giác rất lạnh, không nhất thiết là nhiệt độ ngoài trời đã đạt điểm đóng băng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_equator', 'en-b1-14', 'equator', '/ɪˈkweɪtər/', 'B1', 'đường xích đạo', 'n.', 'equatorial (adj.)', NULL, 'Xích đạo trước thường dùng the; tính từ là equatorial.', 'Our guide explained why it stays warm near the equator.', NULL, 'Hướng dẫn viên của chúng tôi giải thích lý do tại sao ở gần xích đạo thời tiết luôn ấm áp.', '{"wordId":"equator","ukIpa":"/ɪˈkweɪtə/","usIpa":"/ɪˈkweɪtər/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"An imaginary line around Earth''s middle, equally distant from both poles.","vi":"đường xích đạo"}],"examples":[{"en":"Our guide explained why it stays warm near the equator.","vi":"Hướng dẫn viên của chúng tôi giải thích lý do tại sao ở gần xích đạo thời tiết luôn ấm áp.","audioKind":"ex"},{"en":"Regions near the equator receive intense sunlight throughout the year, contributing to consistently high temperatures.","vi":"Các khu vực gần xích đạo nhận được ánh sáng mặt trời gay gắt quanh năm, góp phần duy trì nền nhiệt độ luôn cao.","audioKind":"ex2"}],"collocations":[{"en":"near the equator","vi":"gần xích đạo"},{"en":"cross the equator","vi":"vượt qua đường xích đạo"},{"en":"north of the equator","vi":"bắc xích đạo"}],"wordFamily":["equatorial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Xích đạo trước thường dùng the; tính từ là equatorial.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_olive', 'en-b1-14', 'olive', '/ˈɑːlɪv/', 'B1', 'quả ô liu; cây ô liu (loại quả nhỏ có vị đắng dùng để ép dầu); màu xanh ô liu; da nâu sáng (màu xanh vàng hoặc chỉ làn da nâu nhạt)', 'n.', NULL, NULL, 'olive có thể chỉ quả, cây hoặc màu sắc; olive oil thường là danh từ không đếm được.', 'She added a few olives to the fresh salad.', NULL, 'Cô ấy cho thêm vài quả ô liu vào đĩa salad tươi.', '{"wordId":"olive","ukIpa":"/ˈɒlɪv/","usIpa":"/ˈɑːlɪv/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A small bitter fruit used for oil, or its tree","vi":"quả ô liu; cây ô liu (loại quả nhỏ có vị đắng dùng để ép dầu)"},{"pos":"adj.","en":"Yellowish green in colour, or describing light brown skin","vi":"màu xanh ô liu; da nâu sáng (màu xanh vàng hoặc chỉ làn da nâu nhạt)"}],"examples":[{"en":"She added a few olives to the fresh salad.","vi":"Cô ấy cho thêm vài quả ô liu vào đĩa salad tươi.","audioKind":"ex"},{"en":"Olive cultivation supports rural livelihoods in dry regions, although prolonged drought can significantly reduce harvests.","vi":"Việc trồng ô liu duy trì sinh kế cho người dân ở các vùng khô hạn, mặc dù hạn hán kéo dài có thể làm giảm mạnh năng suất thu hoạch.","audioKind":"ex2"}],"collocations":[{"en":"olive oil","vi":"dầu ô liu"},{"en":"olive grove","vi":"rừng ô liu"},{"en":"olive skin","vi":"làn da ngăm ô liu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"olive có thể chỉ quả, cây hoặc màu sắc; olive oil thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_starfish', 'en-b1-14', 'starfish', '/ˈstɑːrfɪʃ/', 'B1', 'con sao biển', 'n.', NULL, 'Đồng nghĩa: sea star', 'Dạng số ít và số nhiều của từ này thường giống nhau; sao biển là động vật không xương sống, không phải là cá.', 'We spotted an orange starfish in a shallow rock pool.', NULL, 'Chúng tôi phát hiện ra một con sao biển màu cam trong một vũng nước cạn trên bãi đá.', '{"wordId":"starfish","ukIpa":"/ˈstɑːfɪʃ/","usIpa":"/ˈstɑːrfɪʃ/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A sea animal with a central body and usually five arms.","vi":"con sao biển"}],"examples":[{"en":"We spotted an orange starfish in a shallow rock pool.","vi":"Chúng tôi phát hiện ra một con sao biển màu cam trong một vũng nước cạn trên bãi đá.","audioKind":"ex"},{"en":"Changes in ocean temperature can affect starfish populations and disrupt the balance of coastal ecosystems.","vi":"Sự thay đổi nhiệt độ đại dương có thể ảnh hưởng đến quần thể sao biển và làm gián đoạn sự cân bằng của các hệ sinh thái ven biển.","audioKind":"ex2"}],"collocations":[{"en":"a rock pool starfish","vi":"sao biển trong vũng nước trên đá"},{"en":"starfish populations","vi":"quần thể sao biển"},{"en":"a starfish arm","vi":"cánh tay sao biển"}],"wordFamily":[],"synonyms":["sea star"],"antonyms":[],"tipVi":"Dạng số ít và số nhiều của từ này thường giống nhau; sao biển là động vật không xương sống, không phải là cá.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outdoors', 'en-b1-14', 'outdoors', '/ˌaʊtˈdɔːrz/', 'B1', 'ở ngoài trời; ngoài trời; khu vực ngoài trời; thiên nhiên hoang dã', 'adv.', 'outdoor (adj.)', 'Đồng nghĩa: outside · Trái nghĩa: indoors', 'outdoors là phó từ; bổ nghĩa cho danh từ dùng outdoor, ví dụ outdoor activities.', 'The weather is warm enough to eat outdoors tonight.', NULL, 'Thời tiết đủ ấm để tối nay chúng ta ăn uống ngoài trời.', '{"wordId":"outdoors","ukIpa":"/ˌaʊtˈdɔːz/","usIpa":"/ˌaʊtˈdɔːrz/","cefr":"B1","topic":"nature","senses":[{"pos":"adv.","en":"outside a building, in the open air","vi":"ở ngoài trời; ngoài trời"},{"pos":"n.","en":"the natural world away from buildings","vi":"khu vực ngoài trời; thiên nhiên hoang dã"}],"examples":[{"en":"The weather is warm enough to eat outdoors tonight.","vi":"Thời tiết đủ ấm để tối nay chúng ta ăn uống ngoài trời.","audioKind":"ex"},{"en":"Spending time outdoors can improve children''s wellbeing and encourage greater interest in protecting the natural environment.","vi":"Dành thời gian hoạt động ngoài trời có thể cải thiện sức khỏe tinh thần của trẻ nhỏ và khơi gợi sự quan tâm lớn hơn đến việc bảo vệ môi trường tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"spend time outdoors","vi":"dành thời gian ngoài trời"},{"en":"eat outdoors","vi":"ăn uống ngoài trời"},{"en":"the great outdoors","vi":"thế giới tự nhiên bên ngoài"}],"wordFamily":["outdoor (adj.)"],"synonyms":["outside"],"antonyms":["indoors"],"tipVi":"outdoors là phó từ; bổ nghĩa cho danh từ dùng outdoor, ví dụ outdoor activities.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_berry', 'en-b1-14', 'berry', '/ˈberi/', 'B1', 'quả mọng; quả dâu nhỏ', 'n.', NULL, NULL, 'Dạng số nhiều là berries; cách dùng thông thường có điểm khác biệt so với định nghĩa thực vật học.', 'She dropped a ripe berry into her bowl of yoghurt.', NULL, 'Cô ấy thả một quả mọng chín mọng vào bát sữa chua của mình.', '{"wordId":"berry","ukIpa":"/ˈberi/","usIpa":"/ˈberi/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a small, usually round fruit, often growing in clusters","vi":"quả mọng; quả dâu nhỏ"}],"examples":[{"en":"She dropped a ripe berry into her bowl of yoghurt.","vi":"Cô ấy thả một quả mọng chín mọng vào bát sữa chua của mình.","audioKind":"ex"},{"en":"Protecting native shrubs ensures that birds have access to berries and other food sources throughout the year.","vi":"Việc bảo vệ các loài cây bụi bản địa đảm bảo rằng các loài chim luôn có sẵn nguồn quả mọng và thức ăn quanh năm.","audioKind":"ex2"}],"collocations":[{"en":"wild berries","vi":"quả mọng hoang dã"},{"en":"ripe berries","vi":"quả mọng chín"},{"en":"pick berries","vi":"hái quả mọng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là berries; cách dùng thông thường có điểm khác biệt so với định nghĩa thực vật học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_branch', 'en-b1-14', 'branch', '/bræntʃ/', 'B1', 'cành cây; chi nhánh; phân nhánh cơ quan hoặc lĩnh vực; chia nhánh; rẽ nhánh', 'n.', 'branching (adj.)', NULL, 'Branch vừa chỉ cành cây, vừa chỉ nhánh của tổ chức hoặc ngành học.', 'A small bird landed on the lowest branch.', NULL, 'Một chú chim nhỏ đậu trên cành cây thấp nhất.', '{"wordId":"branch","ukIpa":"/brɑːntʃ/","usIpa":"/bræntʃ/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a woody part growing from a tree''s trunk","vi":"cành cây"},{"pos":"n.","en":"a local office or division of a larger organization or subject","vi":"chi nhánh; phân nhánh cơ quan hoặc lĩnh vực"},{"pos":"v.","en":"to divide into separate routes or parts","vi":"chia nhánh; rẽ nhánh"}],"examples":[{"en":"A small bird landed on the lowest branch.","vi":"Một chú chim nhỏ đậu trên cành cây thấp nhất.","audioKind":"ex"},{"en":"Opening a local branch allows banks to provide essential services to communities with limited internet access.","vi":"Việc mở chi nhánh tại địa phương giúp các ngân hàng cung cấp dịch vụ thiết yếu cho các cộng đồng còn hạn chế về kết nối internet.","audioKind":"ex2"}],"collocations":[{"en":"tree branch","vi":"cành cây"},{"en":"local branch","vi":"chi nhánh địa phương"},{"en":"a branch of science","vi":"một nhánh khoa học"},{"en":"branch out into","vi":"mở rộng sang lĩnh vực"}],"wordFamily":["branching (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Branch vừa chỉ cành cây, vừa chỉ nhánh của tổ chức hoặc ngành học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nest', 'en-b1-14', 'nest', '/nest/', 'B1', 'tổ (chim, động vật); làm tổ; trú ngụ trong tổ', 'n.', 'nestling (n.), nesting (n.)', NULL, 'Nest vừa có thể đóng vai trò danh từ là tổ, vừa làm động từ là làm tổ.', 'A small bird carried twigs to its nest.', NULL, 'Một chú chim nhỏ ngậm cành cây khô về tổ của mình.', '{"wordId":"nest","ukIpa":"/nest/","usIpa":"/nest/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A structure animals build to hold eggs or raise their young.","vi":"tổ (chim, động vật)"},{"pos":"v.","en":"Build or occupy a nest.","vi":"làm tổ; trú ngụ trong tổ"}],"examples":[{"en":"A small bird carried twigs to its nest.","vi":"Một chú chim nhỏ ngậm cành cây khô về tổ của mình.","audioKind":"ex"},{"en":"Protecting trees where rare birds nest is essential for maintaining biodiversity in areas affected by urban development.","vi":"Bảo vệ những tán cây nơi các loài chim quý hiếm làm tổ đóng vai trò cốt lõi trong việc duy trì đa dạng sinh học tại các vùng chịu ảnh hưởng bởi đô thị hóa.","audioKind":"ex2"}],"collocations":[{"en":"build a nest","vi":"xây tổ"},{"en":"a bird''s nest","vi":"tổ chim"},{"en":"nesting site","vi":"vị trí làm tổ"},{"en":"nesting season","vi":"mùa sinh sản làm tổ"}],"wordFamily":["nestling (n.)","nesting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nest vừa có thể đóng vai trò danh từ là tổ, vừa làm động từ là làm tổ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_antarctica', 'en-b1-14', 'Antarctica', '/ænˈtɑːrktɪkə/', 'B1', 'châu Nam Cực', 'n.', 'Antarctic (adj.)', NULL, 'Tên châu lục phải viết hoa chữ cái đầu và thường không đi kèm mạo từ ''the''.', 'My cousin photographed penguins during a trip to Antarctica.', NULL, 'Anh họ tôi đã chụp ảnh những chú chim cánh cụt trong chuyến đi đến châu Nam Cực.', '{"wordId":"antarctica","ukIpa":"/ænˈtɑːktɪkə/","usIpa":"/ænˈtɑːrktɪkə/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"the ice-covered continent surrounding the South Pole","vi":"châu Nam Cực"}],"examples":[{"en":"My cousin photographed penguins during a trip to Antarctica.","vi":"Anh họ tôi đã chụp ảnh những chú chim cánh cụt trong chuyến đi đến châu Nam Cực.","audioKind":"ex"},{"en":"Scientists studying Antarctica analyse ancient ice to understand how the Earth''s climate has changed over time.","vi":"Các nhà khoa học nghiên cứu về châu Nam Cực phân tích các lớp băng cổ để hiểu cách khí hậu Trái Đất thay đổi theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"expedition to Antarctica","vi":"chuyến thám hiểm châu Nam Cực"},{"en":"research in Antarctica","vi":"nghiên cứu tại châu Nam Cực"},{"en":"the coast of Antarctica","vi":"bờ biển châu Nam Cực"}],"wordFamily":["Antarctic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên châu lục phải viết hoa chữ cái đầu và thường không đi kèm mạo từ ''the''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bull', 'en-b1-14', 'bull', '/bʊl/', 'B1', 'con đực (bò, voi, cá voi...); nhà đầu tư giá lên; người kỳ vọng thị trường tăng giá', 'n.', 'bullish (adj.)', 'Trái nghĩa: bear', 'Trong tài chính, bull chỉ người dự đoán thị trường tăng giá, trái ngược với bear (người dự đoán thị trường giảm giá).', 'A large bull stood quietly beside the farm gate.', NULL, 'Một con bò đực lớn đứng lặng lẽ bên cạnh cổng trang trại.', '{"wordId":"bull","ukIpa":"/bʊl/","usIpa":"/bʊl/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"an adult male animal of the cattle family","vi":"con đực (bò, voi, cá voi...)"},{"pos":"n.","en":"an investor who expects market prices to rise","vi":"nhà đầu tư giá lên; người kỳ vọng thị trường tăng giá"}],"examples":[{"en":"A large bull stood quietly beside the farm gate.","vi":"Một con bò đực lớn đứng lặng lẽ bên cạnh cổng trang trại.","audioKind":"ex"},{"en":"During a bull market, rising share prices may encourage households to invest more of their savings.","vi":"Trong thời kỳ thị trường giá lên, giá cổ phiếu tăng có thể khuyến khích các hộ gia đình đầu tư nhiều hơn số tiền tiết kiệm của họ.","audioKind":"ex2"}],"collocations":[{"en":"a breeding bull","vi":"bò đực giống"},{"en":"a bull market","vi":"thị trường giá lên (thị trường bò tót)"},{"en":"take the bull by the horns","vi":"dũng cảm đối mặt với khó khăn"}],"wordFamily":["bullish (adj.)"],"synonyms":[],"antonyms":["bear"],"tipVi":"Trong tài chính, bull chỉ người dự đoán thị trường tăng giá, trái ngược với bear (người dự đoán thị trường giảm giá).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_continent', 'en-b1-14', 'continent', '/ˈkɑːntɪnənt/', 'B1', 'châu lục; đại lục', 'n.', 'continental (adj.), intercontinental (adj.)', NULL, 'Continent là châu lục hoặc đại lục, country là quốc gia.', 'Our teacher pointed to the African continent on a globe.', NULL, 'Giáo viên của chúng tôi đã chỉ vào châu Phi trên quả địa cầu.', '{"wordId":"continent","ukIpa":"/ˈkɒntɪnənt/","usIpa":"/ˈkɑːntɪnənt/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"one of the Earth''s main large areas of land","vi":"châu lục; đại lục"}],"examples":[{"en":"Our teacher pointed to the African continent on a globe.","vi":"Giáo viên của chúng tôi đã chỉ vào châu Phi trên quả địa cầu.","audioKind":"ex"},{"en":"Climate change affects every continent, although its consequences vary considerably between regions and communities.","vi":"Biến đổi khí hậu ảnh hưởng đến mọi châu lục, mặc dù hậu quả của nó có sự khác biệt đáng kể giữa các vùng và cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"the African continent","vi":"châu Phi"},{"en":"across continents","vi":"trên khắp các châu lục"},{"en":"continental climate","vi":"khí hậu lục địa"}],"wordFamily":["continental (adj.)","intercontinental (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Continent là châu lục hoặc đại lục, country là quốc gia.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whale', 'en-b1-14', 'whale', '/weɪl/', 'B1', 'cá voi', 'n.', 'whaling (n.), whaler (n.)', NULL, 'Cá voi là loài động vật có vú, không phải cá; dạng số nhiều thường là whales.', 'A whale surfaced beside our boat and sprayed water.', NULL, 'Một con cá voi trồi lên mặt nước cạnh thuyền chúng tôi và phun nước.', '{"wordId":"whale","ukIpa":"/weɪl/","usIpa":"/weɪl/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A very large sea mammal that breathes air.","vi":"cá voi"}],"examples":[{"en":"A whale surfaced beside our boat and sprayed water.","vi":"Một con cá voi trồi lên mặt nước cạnh thuyền chúng tôi và phun nước.","audioKind":"ex"},{"en":"Protecting whale populations requires international cooperation because these marine mammals migrate across vast areas of ocean.","vi":"Việc bảo vệ các quần thể cá voi đòi hỏi sự hợp tác quốc tế vì những loài động vật có vú biển này di cư qua các vùng đại dương bao la.","audioKind":"ex2"}],"collocations":[{"en":"blue whale","vi":"cá voi xanh"},{"en":"whale watching","vi":"ngắm cá voi"},{"en":"whale conservation","vi":"bảo tồn cá voi"}],"wordFamily":["whaling (n.)","whaler (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cá voi là loài động vật có vú, không phải cá; dạng số nhiều thường là whales.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pond', 'en-b1-14', 'pond', '/pɑːnd/', 'B1', 'ao; hồ nước nhỏ', 'n.', NULL, NULL, 'Pond thường nhỏ hơn lake; có thể là ao tự nhiên hoặc nhân tạo.', 'A green frog jumped into the pond beside our house.', NULL, 'Một con ếch xanh nhảy xuống cái ao bên cạnh nhà chúng tôi.', '{"wordId":"pond","ukIpa":"/pɒnd/","usIpa":"/pɑːnd/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a small area of still water surrounded by land","vi":"ao; hồ nước nhỏ"}],"examples":[{"en":"A green frog jumped into the pond beside our house.","vi":"Một con ếch xanh nhảy xuống cái ao bên cạnh nhà chúng tôi.","audioKind":"ex"},{"en":"Creating ponds in urban parks can provide valuable habitats for amphibians and increase local biodiversity.","vi":"Việc tạo ra các ao nước trong công viên đô thị có thể cung cấp môi trường sống quý giá cho các loài lưỡng cư và làm tăng đa dạng sinh học địa phương.","audioKind":"ex2"}],"collocations":[{"en":"garden pond","vi":"ao vườn"},{"en":"fish pond","vi":"ao cá"},{"en":"pond life","vi":"hệ sinh thái ao hồ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Pond thường nhỏ hơn lake; có thể là ao tự nhiên hoặc nhân tạo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pigeon', 'en-b1-14', 'pigeon', '/ˈpɪdʒɪn/', 'B1', 'chim bồ câu', 'n.', NULL, NULL, 'Lưu ý cách viết pigeon; từ đồng âm pidgin có nghĩa là ngôn ngữ bồi.', 'A grey pigeon landed on the bench beside me.', NULL, 'Một con bồ câu xám sà xuống chiếc ghế dài cạnh tôi.', '{"wordId":"pigeon","ukIpa":"/ˈpɪdʒɪn/","usIpa":"/ˈpɪdʒɪn/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A plump bird with short legs, commonly seen in cities","vi":"chim bồ câu"}],"examples":[{"en":"A grey pigeon landed on the bench beside me.","vi":"Một con bồ câu xám sà xuống chiếc ghế dài cạnh tôi.","audioKind":"ex"},{"en":"Urban pigeon populations often grow where food waste is abundant, highlighting the importance of effective rubbish collection.","vi":"Quần thể chim bồ câu ở đô thị thường phát triển mạnh ở những nơi dồi dào rác thải thực phẩm, qua đó nhấn mạnh tầm quan trọng của việc thu gom rác hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"a flock of pigeons","vi":"một đàn bồ câu"},{"en":"homing pigeon","vi":"chim bồ câu đưa thư"},{"en":"feed the pigeons","vi":"cho chim bồ câu ăn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Lưu ý cách viết pigeon; từ đồng âm pidgin có nghĩa là ngôn ngữ bồi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sunlight', 'en-b1-14', 'sunlight', '/ˈsʌnlaɪt/', 'B1', 'ánh sáng mặt trời; ánh nắng', 'n.', 'sun (n.), sunny (adj.), sunlit (adj.)', 'Đồng nghĩa: sunshine', 'Là danh từ không đếm được; in direct sunlight diễn tả việc ở dưới ánh nắng trực tiếp.', 'Warm sunlight streamed through the window onto my desk.', NULL, 'Ánh nắng ấm áp chiếu qua cửa sổ rọi lên bàn làm việc của tôi.', '{"wordId":"sunlight","ukIpa":"/ˈsʌnlaɪt/","usIpa":"/ˈsʌnlaɪt/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"the natural light that comes from the sun","vi":"ánh sáng mặt trời; ánh nắng"}],"examples":[{"en":"Warm sunlight streamed through the window onto my desk.","vi":"Ánh nắng ấm áp chiếu qua cửa sổ rọi lên bàn làm việc của tôi.","audioKind":"ex"},{"en":"Designing classrooms to receive more natural sunlight may improve students'' comfort and reduce electricity use.","vi":"Thiết kế các phòng học đón nhiều ánh sáng tự nhiên hơn có thể nâng cao sự thoải mái của học sinh và giảm thiểu lượng điện tiêu thụ.","audioKind":"ex2"}],"collocations":[{"en":"direct sunlight","vi":"ánh nắng chiếu trực tiếp"},{"en":"bright sunlight","vi":"ánh nắng rực rỡ"},{"en":"exposure to sunlight","vi":"sự tiếp xúc với ánh nắng mặt trời"}],"wordFamily":["sun (n.)","sunny (adj.)","sunlit (adj.)"],"synonyms":["sunshine"],"antonyms":[],"tipVi":"Là danh từ không đếm được; in direct sunlight diễn tả việc ở dưới ánh nắng trực tiếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swan', 'en-b1-14', 'swan', '/swɑːn/', 'B1', 'thiên nga', 'n.', NULL, NULL, 'Là danh từ đếm được, số nhiều là swans; thiên nga con gọi là cygnet.', 'A white swan glided silently across the lake.', NULL, 'Một con thiên nga trắng lướt đi lặng lẽ trên mặt hồ.', '{"wordId":"swan","ukIpa":"/swɒn/","usIpa":"/swɑːn/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A large waterbird with a long neck, usually white","vi":"thiên nga"}],"examples":[{"en":"A white swan glided silently across the lake.","vi":"Một con thiên nga trắng lướt đi lặng lẽ trên mặt hồ.","audioKind":"ex"},{"en":"Protecting wetland habitats benefits swan populations while also preserving the wider ecosystems on which many other species depend.","vi":"Việc bảo vệ các môi trường sống vùng đất ngập nước mang lại lợi ích cho các quần thể thiên nga đồng thời gìn giữ các hệ sinh thái rộng lớn hơn mà nhiều loài khác phải dựa vào để sinh tồn.","audioKind":"ex2"}],"collocations":[{"en":"a pair of swans","vi":"một đôi thiên nga"},{"en":"a swan''s nest","vi":"tổ thiên nga"},{"en":"black swan","vi":"thiên nga đen"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được, số nhiều là swans; thiên nga con gọi là cygnet.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coconut', 'en-b1-14', 'coconut', '/ˈkoʊkənʌt/', 'B1', 'dừa; quả dừa; cùi dừa; cơm dừa', 'n.', NULL, NULL, 'Chỉ toàn bộ quả dừa là danh từ đếm được, còn chỉ cùi dừa thường là danh từ không đếm được.', 'We shared a fresh coconut beside the beach.', NULL, 'Chúng tôi cùng nhau uống một quả dừa tươi ngay cạnh bãi biển.', '{"wordId":"coconut","ukIpa":"/ˈkəʊkənʌt/","usIpa":"/ˈkoʊkənʌt/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A large tropical fruit with a hard shell and white flesh.","vi":"dừa; quả dừa"},{"pos":"n.","en":"The white flesh of a coconut, used as food.","vi":"cùi dừa; cơm dừa"}],"examples":[{"en":"We shared a fresh coconut beside the beach.","vi":"Chúng tôi cùng nhau uống một quả dừa tươi ngay cạnh bãi biển.","audioKind":"ex"},{"en":"Coastal farmers can earn additional income by processing coconut shells into useful household products.","vi":"Nông dân vùng ven biển có thể kiếm thêm thu nhập bằng cách chế biến vỏ dừa thành các sản phẩm gia dụng hữu ích.","audioKind":"ex2"}],"collocations":[{"en":"coconut milk","vi":"nước cốt dừa"},{"en":"coconut water","vi":"nước dừa"},{"en":"coconut oil","vi":"dầu dừa"},{"en":"coconut shell","vi":"vỏ dừa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ toàn bộ quả dừa là danh từ đếm được, còn chỉ cùi dừa thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shore', 'en-b1-14', 'shore', '/ʃɔːr/', 'B1', 'bờ; dải đất dọc theo mép biển hoặc hồ; chống đỡ; củng cố thứ gì đó yếu ớt hoặc dễ sụp đổ, thường dùng với up', 'n.', 'shoreline (n.), offshore (adj.)', NULL, 'shore chủ yếu chỉ bờ biển hoặc bờ hồ; bờ sông thường dùng bank.', 'We left our shoes on the shore and went swimming.', NULL, 'Chúng tôi để giày trên bờ rồi xuống bơi.', '{"wordId":"shore","ukIpa":"/ʃɔː/","usIpa":"/ʃɔːr/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"the land along the edge of a sea or lake","vi":"bờ; dải đất dọc theo mép biển hoặc hồ"},{"pos":"v.","en":"to support something weak or likely to fail, with up","vi":"chống đỡ; củng cố thứ gì đó yếu ớt hoặc dễ sụp đổ, thường dùng với up"}],"examples":[{"en":"We left our shoes on the shore and went swimming.","vi":"Chúng tôi để giày trên bờ rồi xuống bơi.","audioKind":"ex"},{"en":"Construction near the shore should be carefully controlled to protect coastal habitats from permanent damage.","vi":"Các công trình xây dựng gần bờ biển nên được kiểm soát cẩn thận để bảo vệ các sinh cảnh ven biển khỏi bị tổn hại vĩnh viễn.","audioKind":"ex2"}],"collocations":[{"en":"on the shore","vi":"trên bờ"},{"en":"reach the shore","vi":"đến bờ"},{"en":"shore up confidence","vi":"củng cố niềm tin"}],"wordFamily":["shoreline (n.)","offshore (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"shore chủ yếu chỉ bờ biển hoặc bờ hồ; bờ sông thường dùng bank.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pony', 'en-b1-14', 'pony', '/ˈpoʊni/', 'B1', 'ngựa lùn; ngựa nhỏ', 'n.', NULL, NULL, 'pony chỉ giống ngựa nhỏ; ngựa con mới sinh là foal.', 'The little pony gently ate a carrot from my hand.', NULL, 'Chú ngựa lùn nhỏ bé ngoan ngoãn ăn củ cà rốt từ tay tôi.', '{"wordId":"pony","ukIpa":"/ˈpəʊni/","usIpa":"/ˈpoʊni/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A horse of a small breed.","vi":"ngựa lùn; ngựa nhỏ"}],"examples":[{"en":"The little pony gently ate a carrot from my hand.","vi":"Chú ngựa lùn nhỏ bé ngoan ngoãn ăn củ cà rốt từ tay tôi.","audioKind":"ex"},{"en":"Supervised pony riding can help children develop confidence while teaching them how to care responsibly for animals.","vi":"Việc cưỡi ngựa lùn có sự giám sát có thể giúp trẻ em phát triển sự tự tin đồng thời dạy các em cách chăm sóc động vật có trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"ride a pony","vi":"cưỡi ngựa lùn"},{"en":"pony riding","vi":"hoạt động cưỡi ngựa lùn"},{"en":"a Shetland pony","vi":"ngựa lùn Shetland"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"pony chỉ giống ngựa nhỏ; ngựa con mới sinh là foal.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_furry', 'en-b1-14', 'furry', '/ˈfɝːi/', 'B1', 'có lông mềm; phủ lông; như lông thú', 'adj.', 'fur (n.)', 'Trái nghĩa: hairless', 'Từ fur khi chuyển sang furry phải gấp đôi chữ r; có thể dùng để chỉ động vật hoặc chất liệu giả lông.', 'A furry little rabbit curled up beside my feet.', NULL, 'Một chú thỏ nhỏ lông xù đang cuộn tròn bên đôi chân tôi.', '{"wordId":"furry","ukIpa":"/ˈfɜːri/","usIpa":"/ˈfɝːi/","cefr":"B1","topic":"nature","senses":[{"pos":"adj.","en":"covered with thick, soft hair or material resembling fur","vi":"có lông mềm; phủ lông; như lông thú"}],"examples":[{"en":"A furry little rabbit curled up beside my feet.","vi":"Một chú thỏ nhỏ lông xù đang cuộn tròn bên đôi chân tôi.","audioKind":"ex"},{"en":"Many furry mammals depend on dense coats to maintain body temperature in extremely cold environments.","vi":"Nhiều loài động vật có vú phủ lông dày phụ thuộc vào lớp lông ấm áp để duy trì thân nhiệt trong môi trường cực kỳ lạnh giá.","audioKind":"ex2"}],"collocations":[{"en":"furry animal","vi":"động vật có lông"},{"en":"furry coat","vi":"bộ lông mềm mại"},{"en":"furry paws","vi":"bàn chân có lông"}],"wordFamily":["fur (n.)"],"synonyms":[],"antonyms":["hairless"],"tipVi":"Từ fur khi chuyển sang furry phải gấp đôi chữ r; có thể dùng để chỉ động vật hoặc chất liệu giả lông.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_desert', 'en-b1-14', 'desert', '/ˈdezɚt/', 'B1', 'sa mạc; vùng hoang mạc; bỏ rơi; đào ngũ; bỏ trốn', 'n.', 'desertion (n.), deserter (n.), deserted (adj.)', NULL, 'Động từ được phát âm là /dɪˈzɜːt/; cần phân biệt với dessert có nghĩa là món tráng miệng.', 'We crossed the desert before the afternoon heat arrived.', NULL, 'Chúng tôi đã băng qua sa mạc trước khi cái nóng buổi chiều ập đến.', '{"wordId":"desert","ukIpa":"/ˈdezət/","usIpa":"/ˈdezɚt/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a very dry area with little rain and few plants","vi":"sa mạc; vùng hoang mạc"},{"pos":"v.","en":"to leave someone or somewhere you should stay with","vi":"bỏ rơi; đào ngũ; bỏ trốn"}],"examples":[{"en":"We crossed the desert before the afternoon heat arrived.","vi":"Chúng tôi đã băng qua sa mạc trước khi cái nóng buổi chiều ập đến.","audioKind":"ex"},{"en":"As desert areas expand, nearby farming communities face increasing pressure on their water supplies and agricultural land.","vi":"Khi các vùng sa mạc mở rộng, các cộng đồng nông nghiệp lân cận phải đối mặt với áp lực ngày càng tăng đối với nguồn nước và đất canh tác.","audioKind":"ex2"}],"collocations":[{"en":"a vast desert","vi":"sa mạc bao la"},{"en":"desert plants","vi":"thực vật sa mạc"},{"en":"desert a post","vi":"bỏ vị trí công tác"}],"wordFamily":["desertion (n.)","deserter (n.)","deserted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ được phát âm là /dɪˈzɜːt/; cần phân biệt với dessert có nghĩa là món tráng miệng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surround', 'en-b1-14', 'surround', '/səˈraʊnd/', 'B1', 'bao quanh; vây quanh ở mọi phía; gắn bó mật thiết với một sự kiện, tình huống hoặc chủ đề nào đó', 'v.', 'surrounding (adj.), surroundings (n.)', 'Đồng nghĩa: encircle, enclose', 'Thường dùng cấu trúc be surrounded by; surroundings chỉ môi trường xung quanh.', 'Tall trees surround the cottage and shade its windows.', NULL, 'Những cây cổ thụ cao lớn bao quanh ngôi nhà nhỏ và che bóng râm cho các khung cửa sổ.', '{"wordId":"surround","ukIpa":"/səˈraʊnd/","usIpa":"/səˈraʊnd/","cefr":"B1","topic":"nature","senses":[{"pos":"v.","en":"be or move into positions on every side of something","vi":"bao quanh; vây quanh ở mọi phía"},{"pos":"v.","en":"be closely connected with an event, situation, or subject","vi":"gắn bó mật thiết với một sự kiện, tình huống hoặc chủ đề nào đó"}],"examples":[{"en":"Tall trees surround the cottage and shade its windows.","vi":"Những cây cổ thụ cao lớn bao quanh ngôi nhà nhỏ và che bóng râm cho các khung cửa sổ.","audioKind":"ex"},{"en":"Uncertainty continues to surround the proposed transport scheme, making it difficult for local businesses to plan ahead.","vi":"Vẫn còn nhiều điểm chưa chắc chắn xoay quanh kế hoạch giao thông được đề xuất, khiến các doanh nghiệp địa phương khó lên kế hoạch trước.","audioKind":"ex2"}],"collocations":[{"en":"be surrounded by","vi":"bị bao quanh bởi"},{"en":"surround yourself with","vi":"tạo dựng một môi trường xung quanh toàn là..."},{"en":"the circumstances surrounding","vi":"những hoàn cảnh xung quanh..."}],"wordFamily":["surrounding (adj.)","surroundings (n.)"],"synonyms":["encircle","enclose"],"antonyms":[],"tipVi":"Thường dùng cấu trúc be surrounded by; surroundings chỉ môi trường xung quanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rat', 'en-b1-14', 'rat', '/ræt/', 'B1', 'chuột lớn (gặm nhấm, có đuôi dài)', 'n.', NULL, NULL, 'rat thường chỉ chuột lớn, mouse thường chỉ chuột nhắt có kích thước nhỏ hơn.', 'A rat disappeared behind the bins near the gate.', NULL, 'Một con chuột lớn đã biến mất sau mấy cái thùng rác gần cổng.', '{"wordId":"rat","ukIpa":"/ræt/","usIpa":"/ræt/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a rodent with a long tail, larger than a mouse","vi":"chuột lớn (gặm nhấm, có đuôi dài)"}],"examples":[{"en":"A rat disappeared behind the bins near the gate.","vi":"Một con chuột lớn đã biến mất sau mấy cái thùng rác gần cổng.","audioKind":"ex"},{"en":"Proper waste management helps control rat populations and reduces health risks in densely populated neighbourhoods.","vi":"Công tác quản lý rác thải đúng cách giúp kiểm soát số lượng chuột và giảm thiểu rủi ro y tế ở các khu dân cư đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"rat population","vi":"quần thể chuột"},{"en":"rat trap","vi":"bẫy chuột"},{"en":"laboratory rat","vi":"chuột thí nghiệm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"rat thường chỉ chuột lớn, mouse thường chỉ chuột nhắt có kích thước nhỏ hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ladybird', 'en-b1-14', 'ladybird', '/ˈleɪdibɝːd/', 'B1', 'con bọ rùa', 'n.', NULL, 'Đồng nghĩa: ladybug', 'Tiếng Anh-Anh dùng ladybird, trong khi tiếng Anh-Mỹ dùng ladybug.', 'A tiny ladybird landed on the edge of my sleeve.', NULL, 'Một chú bọ rùa nhỏ xíu đã đậu trên mép tay áo của tôi.', '{"wordId":"ladybird","ukIpa":"/ˈleɪdibɜːd/","usIpa":"/ˈleɪdibɝːd/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A small beetle, often red with black spots","vi":"con bọ rùa"}],"examples":[{"en":"A tiny ladybird landed on the edge of my sleeve.","vi":"Một chú bọ rùa nhỏ xíu đã đậu trên mép tay áo của tôi.","audioKind":"ex"},{"en":"Ladybirds can help farmers control certain crop pests, reducing the need for chemical pesticides.","vi":"Bọ rùa có thể giúp nông dân kiểm soát một số loài dịch hại cây trồng, qua đó giảm nhu cầu sử dụng thuốc trừ sâu hóa học.","audioKind":"ex2"}],"collocations":[{"en":"a red ladybird","vi":"một con bọ rùa đỏ"},{"en":"ladybird larvae","vi":"ấu trùng bọ rùa"},{"en":"a seven-spot ladybird","vi":"bọ rùa bảy chấm"}],"wordFamily":[],"synonyms":["ladybug"],"antonyms":[],"tipVi":"Tiếng Anh-Anh dùng ladybird, trong khi tiếng Anh-Mỹ dùng ladybug.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scenery', 'en-b1-14', 'scenery', '/ˈsiːnəri/', 'B1', 'phong cảnh; cảnh quan thiên nhiên; phông cảnh sân khấu', 'n.', 'scenic (adj.)', 'Đồng nghĩa: landscape', 'scenery là danh từ không đếm được, không dùng a scenery hoặc sceneries.', 'We stopped by the lake to admire the scenery.', NULL, 'Chúng tôi dừng chân bên hồ để ngắm cảnh.', '{"wordId":"scenery","ukIpa":"/ˈsiːnəri/","usIpa":"/ˈsiːnəri/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"The natural features of a place considered for their beauty.","vi":"phong cảnh; cảnh quan thiên nhiên"},{"pos":"n.","en":"Painted backgrounds and structures that create a play''s setting.","vi":"phông cảnh sân khấu"}],"examples":[{"en":"We stopped by the lake to admire the scenery.","vi":"Chúng tôi dừng chân bên hồ để ngắm cảnh.","audioKind":"ex"},{"en":"Protecting natural scenery can attract responsible tourism while preserving valuable habitats for local wildlife.","vi":"Bảo vệ phong cảnh tự nhiên có thể thu hút hoạt động du lịch có trách nhiệm đồng thời bảo tồn các sinh cảnh quý giá cho động vật hoang dã địa phương.","audioKind":"ex2"}],"collocations":[{"en":"beautiful scenery","vi":"cảnh đẹp"},{"en":"mountain scenery","vi":"cảnh núi non"},{"en":"spectacular scenery","vi":"cảnh quan ngoạn mục"},{"en":"stage scenery","vi":"phông nền sân khấu"}],"wordFamily":["scenic (adj.)"],"synonyms":["landscape"],"antonyms":[],"tipVi":"scenery là danh từ không đếm được, không dùng a scenery hoặc sceneries.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_14_1', 'en-b1-14', 'Cách dùng “bull” (n.) — con đực (bò, voi, cá voi...)', 'a breeding bull  ·  a bull market  ·  take the bull by the horns', 'Trong tài chính, bull chỉ người dự đoán thị trường tăng giá, trái ngược với bear (người dự đoán thị trường giảm giá).', 'Họ từ (Word Family): bullish (adj.) | Trái nghĩa: bear', '[{"hanzi":"A large bull stood quietly beside the farm gate.","pinyin":"","meaning":"Một con bò đực lớn đứng lặng lẽ bên cạnh cổng trang trại."},{"hanzi":"During a bull market, rising share prices may encourage households to invest more of their savings.","pinyin":"","meaning":"Trong thời kỳ thị trường giá lên, giá cổ phiếu tăng có thể khuyến khích các hộ gia đình đầu tư nhiều hơn số tiền tiết kiệm của họ."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_14_2', 'en-b1-14', 'Cách dùng “starfish” (n.) — con sao biển', 'a rock pool starfish  ·  starfish populations  ·  a starfish arm', 'Dạng số ít và số nhiều của từ này thường giống nhau; sao biển là động vật không xương sống, không phải là cá.', 'Đồng nghĩa: sea star', '[{"hanzi":"We spotted an orange starfish in a shallow rock pool.","pinyin":"","meaning":"Chúng tôi phát hiện ra một con sao biển màu cam trong một vũng nước cạn trên bãi đá."},{"hanzi":"Changes in ocean temperature can affect starfish populations and disrupt the balance of coastal ecosystems.","pinyin":"","meaning":"Sự thay đổi nhiệt độ đại dương có thể ảnh hưởng đến quần thể sao biển và làm gián đoạn sự cân bằng của các hệ sinh thái ven biển."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_14_3', 'en-b1-14', 'Cách dùng “freezing” (adj.) — lạnh cóng; băng giá', 'freezing cold  ·  freezing temperatures  ·  below freezing', 'Cụm ''I''m freezing'' diễn tả cảm giác rất lạnh, không nhất thiết là nhiệt độ ngoài trời đã đạt điểm đóng băng.', 'Họ từ (Word Family): freeze (v.), frozen (adj.), freezer (n.) | Đồng nghĩa: icy, frigid · Trái nghĩa: hot', '[{"hanzi":"My hands were freezing after waiting outside for the bus.","pinyin":"","meaning":"Tay tôi lạnh cóng sau khi đứng chờ xe buýt ngoài trời."},{"hanzi":"Freezing temperatures can damage water pipes and disrupt essential services, particularly in areas with ageing infrastructure.","pinyin":"","meaning":"Nhiệt độ băng giá có thể làm hỏng đường ống nước và làm gián đoạn các dịch vụ thiết yếu, đặc biệt là ở những khu vực có cơ sở hạ tầng cũ kỹ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_14_4', 'en-b1-14', 'Cách dùng “furry” (adj.) — có lông mềm; phủ lông; như lông thú', 'furry animal  ·  furry coat  ·  furry paws', 'Từ fur khi chuyển sang furry phải gấp đôi chữ r; có thể dùng để chỉ động vật hoặc chất liệu giả lông.', 'Họ từ (Word Family): fur (n.) | Trái nghĩa: hairless', '[{"hanzi":"A furry little rabbit curled up beside my feet.","pinyin":"","meaning":"Một chú thỏ nhỏ lông xù đang cuộn tròn bên đôi chân tôi."},{"hanzi":"Many furry mammals depend on dense coats to maintain body temperature in extremely cold environments.","pinyin":"","meaning":"Nhiều loài động vật có vú phủ lông dày phụ thuộc vào lớp lông ấm áp để duy trì thân nhiệt trong môi trường cực kỳ lạnh giá."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_14_1', 'en-b1-14', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_1_1', 'ten_b1_14_1', 'freezing', 'My hands were freezing after waiting outside for the bus.', 'My hands were freezing after waiting outside for the bus.', '/ˈfriːzɪŋ/', 'Tay tôi lạnh cóng sau khi đứng chờ xe buýt ngoài trời.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_1_2', 'ten_b1_14_1', 'equator', 'Our guide explained why it stays warm near the equator.', 'Our guide explained why it stays warm near the equator.', '/ɪˈkweɪtər/', 'Hướng dẫn viên của chúng tôi giải thích lý do tại sao ở gần xích đạo thời tiết luôn ấm áp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_1_3', 'ten_b1_14_1', 'olive', 'She added a few olives to the fresh salad.', 'She added a few olives to the fresh salad.', '/ˈɑːlɪv/', 'Cô ấy cho thêm vài quả ô liu vào đĩa salad tươi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_1_4', 'ten_b1_14_1', 'starfish', 'We spotted an orange starfish in a shallow rock pool.', 'We spotted an orange starfish in a shallow rock pool.', '/ˈstɑːrfɪʃ/', 'Chúng tôi phát hiện ra một con sao biển màu cam trong một vũng nước cạn trên bãi đá.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_1_5', 'ten_b1_14_1', 'outdoors', 'The weather is warm enough to eat outdoors tonight.', 'The weather is warm enough to eat outdoors tonight.', '/ˌaʊtˈdɔːrz/', 'Thời tiết đủ ấm để tối nay chúng ta ăn uống ngoài trời.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_1_6', 'ten_b1_14_1', 'berry', 'She dropped a ripe berry into her bowl of yoghurt.', 'She dropped a ripe berry into her bowl of yoghurt.', '/ˈberi/', 'Cô ấy thả một quả mọng chín mọng vào bát sữa chua của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_1_7', 'ten_b1_14_1', 'branch', 'A small bird landed on the lowest branch.', 'A small bird landed on the lowest branch.', '/bræntʃ/', 'Một chú chim nhỏ đậu trên cành cây thấp nhất.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_1_8', 'ten_b1_14_1', 'nest', 'A small bird carried twigs to its nest.', 'A small bird carried twigs to its nest.', '/nest/', 'Một chú chim nhỏ ngậm cành cây khô về tổ của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_14_1_1', 'en-b1-14', 'ten_b1_14_1', 'listening', 'listening', 'My hands were freezing after waiting outside for the bus.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi phát hiện ra một con sao biển màu cam trong một vũng nước cạn trên bãi đá.","Một con cá voi trồi lên mặt nước cạnh thuyền chúng tôi và phun nước.","Tay tôi lạnh cóng sau khi đứng chờ xe buýt ngoài trời.","Chúng tôi để giày trên bờ rồi xuống bơi."]'::jsonb, 2, 'My hands were freezing after waiting outside for the bus. → Tay tôi lạnh cóng sau khi đứng chờ xe buýt ngoài trời.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_14_1_2', 'en-b1-14', 'ten_b1_14_1', 'listening', 'listening', 'Our guide explained why it stays warm near the equator.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy thả một quả mọng chín mọng vào bát sữa chua của mình.","Một con bò đực lớn đứng lặng lẽ bên cạnh cổng trang trại.","Chúng tôi cùng nhau uống một quả dừa tươi ngay cạnh bãi biển.","Hướng dẫn viên của chúng tôi giải thích lý do tại sao ở gần xích đạo thời tiết luôn ấm áp."]'::jsonb, 3, 'Our guide explained why it stays warm near the equator. → Hướng dẫn viên của chúng tôi giải thích lý do tại sao ở gần xích đạo thời tiết luôn ấm áp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_14_1_3', 'en-b1-14', 'ten_b1_14_1', 'listening', 'listening', 'She added a few olives to the fresh salad.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một chú thỏ nhỏ lông xù đang cuộn tròn bên đôi chân tôi.","Chúng tôi để giày trên bờ rồi xuống bơi.","Cô ấy cho thêm vài quả ô liu vào đĩa salad tươi.","Chúng tôi dừng chân bên hồ để ngắm cảnh."]'::jsonb, 2, 'She added a few olives to the fresh salad. → Cô ấy cho thêm vài quả ô liu vào đĩa salad tươi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_14_2', 'en-b1-14', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_2_1', 'ten_b1_14_2', 'freezing', 'Freezing temperatures can damage water pipes and disrupt essential services, particularly in areas with ageing infrastructure.', 'Freezing temperatures can damage water pipes and disrupt essential services, particularly in areas with ageing infrastructure.', '/ˈfriːzɪŋ/', 'Nhiệt độ băng giá có thể làm hỏng đường ống nước và làm gián đoạn các dịch vụ thiết yếu, đặc biệt là ở những khu vực có cơ sở hạ tầng cũ kỹ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_2_2', 'ten_b1_14_2', 'equator', 'Regions near the equator receive intense sunlight throughout the year, contributing to consistently high temperatures.', 'Regions near the equator receive intense sunlight throughout the year, contributing to consistently high temperatures.', '/ɪˈkweɪtər/', 'Các khu vực gần xích đạo nhận được ánh sáng mặt trời gay gắt quanh năm, góp phần duy trì nền nhiệt độ luôn cao.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_2_3', 'ten_b1_14_2', 'olive', 'Olive cultivation supports rural livelihoods in dry regions, although prolonged drought can significantly reduce harvests.', 'Olive cultivation supports rural livelihoods in dry regions, although prolonged drought can significantly reduce harvests.', '/ˈɑːlɪv/', 'Việc trồng ô liu duy trì sinh kế cho người dân ở các vùng khô hạn, mặc dù hạn hán kéo dài có thể làm giảm mạnh năng suất thu hoạch.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_2_4', 'ten_b1_14_2', 'starfish', 'Changes in ocean temperature can affect starfish populations and disrupt the balance of coastal ecosystems.', 'Changes in ocean temperature can affect starfish populations and disrupt the balance of coastal ecosystems.', '/ˈstɑːrfɪʃ/', 'Sự thay đổi nhiệt độ đại dương có thể ảnh hưởng đến quần thể sao biển và làm gián đoạn sự cân bằng của các hệ sinh thái ven biển.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_2_5', 'ten_b1_14_2', 'outdoors', 'Spending time outdoors can improve children''s wellbeing and encourage greater interest in protecting the natural environment.', 'Spending time outdoors can improve children''s wellbeing and encourage greater interest in protecting the natural environment.', '/ˌaʊtˈdɔːrz/', 'Dành thời gian hoạt động ngoài trời có thể cải thiện sức khỏe tinh thần của trẻ nhỏ và khơi gợi sự quan tâm lớn hơn đến việc bảo vệ môi trường tự nhiên.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_14_2_6', 'ten_b1_14_2', 'berry', 'Protecting native shrubs ensures that birds have access to berries and other food sources throughout the year.', 'Protecting native shrubs ensures that birds have access to berries and other food sources throughout the year.', '/ˈberi/', 'Việc bảo vệ các loài cây bụi bản địa đảm bảo rằng các loài chim luôn có sẵn nguồn quả mọng và thức ăn quanh năm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_14_2_1', 'en-b1-14', 'ten_b1_14_2', 'listening', 'listening', 'Freezing temperatures can damage water pipes and disrupt essential services, particularly in areas with ageing infrastructure.', NULL, 'Trong câu vừa nghe, từ “freezing” mang nghĩa nào sau đây?', '["cay; có nhiều gia vị","xin lỗi","ngoài trời; lộ thiên","lạnh cóng; băng giá"]'::jsonb, 3, '“freezing” (/ˈfriːzɪŋ/): lạnh cóng; băng giá. Câu đầy đủ: Freezing temperatures can damage water pipes and disrupt essential services, particularly in areas with ageing infrastructure.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_14_2_2', 'en-b1-14', 'ten_b1_14_2', 'listening', 'listening', 'Regions near the equator receive intense sunlight throughout the year, contributing to consistently high temperatures.', NULL, 'Trong câu vừa nghe, từ “equator” mang nghĩa nào sau đây?', '["lương thực; ngũ cốc","đường xích đạo","làm tràn; làm đổ; làm rơi vãi","cái đĩa lót tách; đĩa đựng chén trà"]'::jsonb, 1, '“equator” (/ɪˈkweɪtər/): đường xích đạo. Câu đầy đủ: Regions near the equator receive intense sunlight throughout the year, contributing to consistently high temperatures.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_14_1', 'en-b1-14', 'My hands were freezing after waiting outside for the bus', 'Tay tôi lạnh cóng sau khi đứng chờ xe buýt ngoài trời.', 'freezing /ˈfriːzɪŋ/', '["after","My","waiting","outside","bus","the","were","for","hands","freezing"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
