INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_14_4', 'en-b1-14', 'We spotted an orange starfish in a shallow rock pool', 'Chúng tôi phát hiện ra một con sao biển màu cam trong một vũng nước cạn trên bãi đá.', 'starfish /ˈstɑːrfɪʃ/', '["in","orange","rock","pool","spotted","a","an","shallow","starfish","We"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_14_5', 'en-b1-14', 'The weather is warm enough to eat outdoors tonight', 'Thời tiết đủ ấm để tối nay chúng ta ăn uống ngoài trời.', 'outdoors /ˌaʊtˈdɔːrz/', '["eat","enough","The","weather","to","tonight","outdoors","warm","is"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
