INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_b1_14_14', 'en-b1-14', NULL, 'expanded_quiz', 'definition', NULL, NULL, 'Chọn từ tiếng Anh khớp với định nghĩa: “A plump bird with short legs, commonly seen in cities”', '["pigeon","berry","pony","sunlight"]'::jsonb, 0, '“pigeon” (/ˈpɪdʒɪn/) nghĩa là: chim bồ câu.', 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
