INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_1', 'en-b1-14', NULL, 'comprehensive_test', 'listening', 'freezing', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xuất khẩu; đem bán ra nước ngoài","lan truyền; truyền bá","lạnh cóng; băng giá","kết hợp; phối hợp"]'::jsonb, 2, 'freezing (/ˈfriːzɪŋ/) → lạnh cóng; băng giá; điểm đóng băng', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_2', 'en-b1-14', NULL, 'comprehensive_test', 'listening', 'Our guide explained why it stays warm near the equator.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hướng dẫn viên của chúng tôi giải thích lý do tại sao ở gần xích đạo thời tiết luôn ấm áp.","Một con chuột lớn đã biến mất sau mấy cái thùng rác gần cổng.","Một con thiên nga trắng lướt đi lặng lẽ trên mặt hồ.","Thời tiết đủ ấm để tối nay chúng ta ăn uống ngoài trời."]'::jsonb, 0, 'Our guide explained why it stays warm near the equator. → Hướng dẫn viên của chúng tôi giải thích lý do tại sao ở gần xích đạo thời tiết luôn ấm áp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_3', 'en-b1-14', NULL, 'comprehensive_test', 'listening', 'olive', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phức tạp, có nhiều phần liên kết và khó hiểu","chủ yếu là; phần lớn","mi-li-mét","quả ô liu; cây ô liu (loại quả nhỏ có vị đắng dùng để ép dầu)"]'::jsonb, 3, 'olive (/ˈɑːlɪv/) → quả ô liu; cây ô liu (loại quả nhỏ có vị đắng dùng để ép dầu); màu xanh ô liu; da nâu sáng (màu xanh vàng hoặc chỉ làn da nâu nhạt)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_4', 'en-b1-14', NULL, 'comprehensive_test', 'listening', 'We spotted an orange starfish in a shallow rock pool.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi để giày trên bờ rồi xuống bơi.","Chúng tôi phát hiện ra một con sao biển màu cam trong một vũng nước cạn trên bãi đá.","Một con chuột lớn đã biến mất sau mấy cái thùng rác gần cổng.","Một chú thỏ nhỏ lông xù đang cuộn tròn bên đôi chân tôi."]'::jsonb, 1, 'We spotted an orange starfish in a shallow rock pool. → Chúng tôi phát hiện ra một con sao biển màu cam trong một vũng nước cạn trên bãi đá.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_5', 'en-b1-14', NULL, 'comprehensive_test', 'listening', 'outdoors', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quý ông; người lịch sự","quảng cáo; quảng bá","hương va-ni; quả va-ni","ở ngoài trời; ngoài trời"]'::jsonb, 3, 'outdoors (/ˌaʊtˈdɔːrz/) → ở ngoài trời; ngoài trời; khu vực ngoài trời; thiên nhiên hoang dã', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_6', 'en-b1-14', NULL, 'comprehensive_test', 'listening', 'She dropped a ripe berry into her bowl of yoghurt.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã băng qua sa mạc trước khi cái nóng buổi chiều ập đến.","Cô ấy thả một quả mọng chín mọng vào bát sữa chua của mình.","Một con bò đực lớn đứng lặng lẽ bên cạnh cổng trang trại.","Chúng tôi dừng chân bên hồ để ngắm cảnh."]'::jsonb, 1, 'She dropped a ripe berry into her bowl of yoghurt. → Cô ấy thả một quả mọng chín mọng vào bát sữa chua của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_7', 'en-b1-14', NULL, 'comprehensive_test', 'listening', 'branch', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["rõ ràng; hiển nhiên; dễ nhận thấy","thuật ngữ; từ ngữ","cành cây","tái chế; tái tạo"]'::jsonb, 2, 'branch (/bræntʃ/) → cành cây; chi nhánh; phân nhánh cơ quan hoặc lĩnh vực; chia nhánh; rẽ nhánh', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_8', 'en-b1-14', NULL, 'comprehensive_test', 'listening', 'A small bird carried twigs to its nest.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một chú chim nhỏ ngậm cành cây khô về tổ của mình.","Chúng tôi dừng chân bên hồ để ngắm cảnh.","Chúng tôi cùng nhau uống một quả dừa tươi ngay cạnh bãi biển.","Những cây cổ thụ cao lớn bao quanh ngôi nhà nhỏ và che bóng râm cho các khung cửa sổ."]'::jsonb, 0, 'A small bird carried twigs to its nest. → Một chú chim nhỏ ngậm cành cây khô về tổ của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_9', 'en-b1-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “outside a building, in the open air”?', '["freezing","swan","desert","outdoors"]'::jsonb, 3, 'outdoors (/ˌaʊtˈdɔːrz/) → ở ngoài trời; ngoài trời', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_10', 'en-b1-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a small, usually round fruit, often growing in clusters”?', '["sunlight","surround","bull","berry"]'::jsonb, 3, 'berry (/ˈberi/) → quả mọng; quả dâu nhỏ', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
