INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_18', 'en-b1-14', NULL, 'comprehensive_test', 'reading', NULL, 'Freezing temperatures can damage water pipes and disrupt essential services, particularly in areas with ageing infrastructure.', 'Dựa vào câu trên, từ “freezing” có nghĩa phù hợp nhất là gì?', '["bảo hiểm","lạnh cóng; băng giá","hoài bão; chí hướng","đồ đựng; vật dùng để chứa hoặc bảo quản đồ đạc"]'::jsonb, 1, 'freezing: lạnh cóng; băng giá; điểm đóng băng. Dịch cả câu: Nhiệt độ băng giá có thể làm hỏng đường ống nước và làm gián đoạn các dịch vụ thiết yếu, đặc biệt là ở những khu vực có cơ sở hạ tầng cũ kỹ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_19', 'en-b1-14', NULL, 'comprehensive_test', 'reading', NULL, 'Regions near the equator receive intense sunlight throughout the year, contributing to consistently high temperatures.', 'Dựa vào câu trên, từ “equator” có nghĩa phù hợp nhất là gì?', '["ở ngoài trời; ngoài trời","hương vị; mùi vị","đường xích đạo","người đưa thư; sứ giả; người truyền tin"]'::jsonb, 2, 'equator: đường xích đạo. Dịch cả câu: Các khu vực gần xích đạo nhận được ánh sáng mặt trời gay gắt quanh năm, góp phần duy trì nền nhiệt độ luôn cao.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_20', 'en-b1-14', NULL, 'comprehensive_test', 'reading', NULL, 'Olive cultivation supports rural livelihoods in dry regions, although prolonged drought can significantly reduce harvests.', 'Dựa vào câu trên, từ “olive” có nghĩa phù hợp nhất là gì?', '["tàu vũ trụ","buổi thảo luận thực tế; hội thảo","lộn ngược; đảo ngược","quả ô liu; cây ô liu (loại quả nhỏ có vị đắng dùng để ép dầu)"]'::jsonb, 3, 'olive: quả ô liu; cây ô liu (loại quả nhỏ có vị đắng dùng để ép dầu); màu xanh ô liu; da nâu sáng (màu xanh vàng hoặc chỉ làn da nâu nhạt). Dịch cả câu: Việc trồng ô liu duy trì sinh kế cho người dân ở các vùng khô hạn, mặc dù hạn hán kéo dài có thể làm giảm mạnh năng suất thu hoạch.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_21', 'en-b1-14', NULL, 'comprehensive_test', 'reading', NULL, 'Changes in ocean temperature can affect starfish populations and disrupt the balance of coastal ecosystems.', 'Dựa vào câu trên, từ “starfish” có nghĩa phù hợp nhất là gì?', '["con sao biển","quần áo thể thao; trang phục thể thao","bóng tối; sự tối tăm","tuyến đường; lộ trình"]'::jsonb, 0, 'starfish: con sao biển. Dịch cả câu: Sự thay đổi nhiệt độ đại dương có thể ảnh hưởng đến quần thể sao biển và làm gián đoạn sự cân bằng của các hệ sinh thái ven biển.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_22', 'en-b1-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chuột lớn (gặm nhấm, có đuôi dài)”', '["rat","fee","ribbon","calm"]'::jsonb, 0, 'chuột lớn (gặm nhấm, có đuôi dài) → rat (/ræt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_23', 'en-b1-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “con bọ rùa”', '["ladybird","stain","discovery","consist"]'::jsonb, 0, 'con bọ rùa → ladybird (/ˈleɪdibɝːd/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_14_24', 'en-b1-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phong cảnh; cảnh quan thiên nhiên”', '["baby-sit","duty","scenery","achieve"]'::jsonb, 2, 'phong cảnh; cảnh quan thiên nhiên → scenery (/ˈsiːnəri/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-15', 'en', 'Bài 15: Thiên nhiên & Thời tiết (2) - CEFR B1', 'CEFR B1', 'B1 · Thiên nhiên', '25 từ vựng Tiếng Anh CEFR B1 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3015, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_northern', 'en-b1-15', 'northern', '/ˈnɔːrðərn/', 'B1', 'thuộc về phương bắc; ở miền bắc', 'adj.', 'north (n.), northward (adv.), northerly (adj.)', 'Trái nghĩa: southern', 'northern là tính từ, thường đứng trước các danh từ chỉ địa danh như region, coast.', 'My grandparents live in a quiet northern village.', NULL, 'Ông bà tôi sống ở một ngôi làng yên bình ở miền bắc.', '{"wordId":"northern","ukIpa":"/ˈnɔːðən/","usIpa":"/ˈnɔːrðərn/","cefr":"B1","topic":"nature","senses":[{"pos":"adj.","en":"In, from, or relating to the north.","vi":"thuộc về phương bắc; ở miền bắc"}],"examples":[{"en":"My grandparents live in a quiet northern village.","vi":"Ông bà tôi sống ở một ngôi làng yên bình ở miền bắc.","audioKind":"ex"},{"en":"Northern regions often face higher heating costs, making energy efficiency particularly important for local households.","vi":"Các vùng phía bắc thường phải đối mặt với chi phí sưởi ấm cao hơn, điều này làm cho hiệu quả năng lượng trở nên đặc biệt quan trọng đối với các hộ gia đình địa phương.","audioKind":"ex2"}],"collocations":[{"en":"northern regions","vi":"các vùng phía bắc"},{"en":"the northern hemisphere","vi":"bán cầu bắc"},{"en":"the northern coast","vi":"bờ biển phía bắc"}],"wordFamily":["north (n.)","northward (adv.)","northerly (adj.)"],"synonyms":[],"antonyms":["southern"],"tipVi":"northern là tính từ, thường đứng trước các danh từ chỉ địa danh như region, coast.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_poisonous', 'en-b1-15', 'poisonous', '/ˈpɔɪzənəs/', 'B1', 'có độc; độc hại; độc ác; đầy ác ý', 'adj.', 'poison (n.), poison (v.), poisoning (n.)', 'Đồng nghĩa: toxic · Trái nghĩa: non-toxic', 'poisonous chỉ có độc; venomous nhấn mạnh việc cắn, chích để tiêm nọc độc.', 'Some colourful berries are poisonous, so leave them alone.', NULL, 'Một số loại quả mọng có màu sắc sặc sỡ rất có độc, vì vậy đừng chạm vào chúng.', '{"wordId":"poisonous","ukIpa":"/ˈpɔɪzənəs/","usIpa":"/ˈpɔɪzənəs/","cefr":"B1","topic":"nature","senses":[{"pos":"adj.","en":"Containing a substance that can cause illness or death.","vi":"có độc; độc hại"},{"pos":"adj.","en":"Extremely unkind or harmful to relationships.","vi":"độc ác; đầy ác ý"}],"examples":[{"en":"Some colourful berries are poisonous, so leave them alone.","vi":"Một số loại quả mọng có màu sắc sặc sỡ rất có độc, vì vậy đừng chạm vào chúng.","audioKind":"ex"},{"en":"Factories must prevent poisonous substances from entering rivers that supply drinking water to nearby communities.","vi":"Các nhà máy phải ngăn chặn các chất độc hại xâm nhập vào các con sông cung cấp nước sinh hoạt cho các cộng đồng xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"poisonous plants","vi":"thực vật có độc"},{"en":"poisonous gases","vi":"khí độc"},{"en":"poisonous remarks","vi":"lời lẽ cay độc; những phát ngôn ác ý"}],"wordFamily":["poison (n.)","poison (v.)","poisoning (n.)"],"synonyms":["toxic"],"antonyms":["non-toxic"],"tipVi":"poisonous chỉ có độc; venomous nhấn mạnh việc cắn, chích để tiêm nọc độc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_valley', 'en-b1-15', 'valley', '/ˈvæli/', 'B1', 'thung lũng; thung lũng sông', 'n.', NULL, NULL, 'Valley là vùng đất trũng nằm giữa các ngọn đồi hoặc dãy núi, không đồng nghĩa với thung lũng lòng chảo (basin).', 'A narrow river winds through the green valley.', NULL, 'Một dòng sông nhỏ uốn lượn qua thung lũng xanh tươi.', '{"wordId":"valley","ukIpa":"/ˈvæli/","usIpa":"/ˈvæli/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"Low land between hills or mountains, often containing a river.","vi":"thung lũng; thung lũng sông"}],"examples":[{"en":"A narrow river winds through the green valley.","vi":"Một dòng sông nhỏ uốn lượn qua thung lũng xanh tươi.","audioKind":"ex"},{"en":"Farming communities in the valley depend on seasonal rainfall to maintain their crops and support local livelihoods.","vi":"Các cộng đồng làm nông nghiệp trong thung lũng phụ thuộc vào lượng mưa theo mùa để duy trì mùa màng và bảo đảm sinh kế địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a river valley","vi":"thung lũng sông"},{"en":"a deep valley","vi":"thung lũng sâu"},{"en":"the valley floor","vi":"đáy thung lũng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Valley là vùng đất trũng nằm giữa các ngọn đồi hoặc dãy núi, không đồng nghĩa với thung lũng lòng chảo (basin).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dolphin', 'en-b1-15', 'dolphin', '/ˈdɑːlfɪn/', 'B1', 'con cá heo', 'n.', NULL, NULL, 'Cá heo là loài thú có vú; một đàn cá heo có thể gọi là a pod of dolphins.', 'A dolphin leapt beside our boat early this morning.', NULL, 'Một chú cá heo đã nhảy vọt lên ngay cạnh thuyền của chúng tôi vào sáng sớm nay.', '{"wordId":"dolphin","ukIpa":"/ˈdɒlfɪn/","usIpa":"/ˈdɑːlfɪn/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"An intelligent aquatic mammal with a long snout and curved fin.","vi":"con cá heo"}],"examples":[{"en":"A dolphin leapt beside our boat early this morning.","vi":"Một chú cá heo đã nhảy vọt lên ngay cạnh thuyền của chúng tôi vào sáng sớm nay.","audioKind":"ex"},{"en":"Underwater noise from shipping can disrupt dolphin communication and make it harder for these animals to find food.","vi":"Tiếng ồn dưới nước do tàu bè gây ra có thể làm gián đoạn sự giao tiếp của cá heo và khiến cho loài động vật này khó kiếm thức ăn hơn.","audioKind":"ex2"}],"collocations":[{"en":"a pod of dolphins","vi":"một đàn cá heo"},{"en":"bottlenose dolphin","vi":"cá heo mũi chai"},{"en":"dolphin conservation","vi":"bảo tồn cá heo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cá heo là loài thú có vú; một đàn cá heo có thể gọi là a pod of dolphins.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_goose', 'en-b1-15', 'goose', '/ɡuːs/', 'B1', 'con ngỗng; thịt ngỗng', 'n.', NULL, NULL, 'Dạng số nhiều là geese; khi chỉ thịt ngỗng thì không đếm được.', 'A white goose waddled across the path towards us.', NULL, 'Một con ngỗng trắng lạch bạch đi qua con đường hướng về phía chúng tôi.', '{"wordId":"goose","ukIpa":"/ɡuːs/","usIpa":"/ɡuːs/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A large waterbird with a long neck and webbed feet.","vi":"con ngỗng"},{"pos":"n.","en":"Meat from a goose, eaten as food.","vi":"thịt ngỗng"}],"examples":[{"en":"A white goose waddled across the path towards us.","vi":"Một con ngỗng trắng lạch bạch đi qua con đường hướng về phía chúng tôi.","audioKind":"ex"},{"en":"Protecting wetlands provides essential feeding grounds for wild geese and many other migratory birds.","vi":"Việc bảo vệ các vùng đất ngập nước cung cấp các bãi kiếm ăn thiết yếu cho ngỗng trời và nhiều loài chim di cư khác.","audioKind":"ex2"}],"collocations":[{"en":"wild geese","vi":"ngỗng trời"},{"en":"a flock of geese","vi":"một đàn ngỗng"},{"en":"roast goose","vi":"thịt ngỗng quay"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là geese; khi chỉ thịt ngỗng thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_salmon', 'en-b1-15', 'salmon', '/ˈsæmən/', 'B1', 'cá hồi; thịt cá hồi; màu hồng cam nhạt', 'n.', NULL, NULL, 'Chữ l không phát âm; khi chỉ con cá thì số ít và số nhiều giống nhau, khi chỉ thịt cá thì không đếm được.', 'We watched a salmon leap up the rocky stream.', NULL, 'Chúng tôi nhìn thấy một con cá hồi bơi vượt qua con suối nhiều đá lên thượng nguồn.', '{"wordId":"salmon","ukIpa":"/ˈsæmən/","usIpa":"/ˈsæmən/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a fish with pink flesh, or its flesh as food","vi":"cá hồi; thịt cá hồi"},{"pos":"adj.","en":"having a pink colour with a slight orange shade","vi":"màu hồng cam nhạt"}],"examples":[{"en":"We watched a salmon leap up the rocky stream.","vi":"Chúng tôi nhìn thấy một con cá hồi bơi vượt qua con suối nhiều đá lên thượng nguồn.","audioKind":"ex"},{"en":"Dams can disrupt salmon migration, so river management should consider both energy production and wildlife protection.","vi":"Các con đập có thể cản trở sự di cư của cá hồi, vì vậy việc quản lý sông ngòi cần cân nhắc cả việc sản xuất năng lượng lẫn bảo vệ động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"smoked salmon","vi":"cá hồi xông khói"},{"en":"wild salmon","vi":"cá hồi hoang dã"},{"en":"salmon fillet","vi":"phi lê cá hồi"},{"en":"salmon migration","vi":"sự di cư của cá hồi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chữ l không phát âm; khi chỉ con cá thì số ít và số nhiều giống nhau, khi chỉ thịt cá thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_turkey', 'en-b1-15', 'turkey', '/ˈtɜːrki/', 'B1', 'con gà tây; thịt gà tây; vật phẩm thất bại; tác phẩm dở tệ', 'n.', NULL, NULL, 'Chim thì đếm được, thịt thì không đếm được; dùng chỉ tác phẩm thất bại là cách nói thân mật.', 'A turkey spread its tail feathers near the farm gate.', NULL, 'Một con gà tây xòe lông đuôi ở gần cổng trang trại.', '{"wordId":"turkey","ukIpa":"/ˈtɜːki/","usIpa":"/ˈtɜːrki/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A large bird often raised for its meat","vi":"con gà tây"},{"pos":"n.","en":"Meat from a turkey, eaten as food","vi":"thịt gà tây"},{"pos":"n.","en":"Something that fails badly, especially a film or play","vi":"vật phẩm thất bại; tác phẩm dở tệ"}],"examples":[{"en":"A turkey spread its tail feathers near the farm gate.","vi":"Một con gà tây xòe lông đuôi ở gần cổng trang trại.","audioKind":"ex"},{"en":"Turkey production provides affordable protein, but intensive farming can raise concerns about animal welfare and environmental damage.","vi":"Việc chăn nuôi gà tây cung cấp nguồn protein giá cả phải chăng, nhưng chăn nuôi thâm canh có thể làmấy lên những lo ngại về phúc lợi động vật và tổn hại môi trường.","audioKind":"ex2"}],"collocations":[{"en":"roast turkey","vi":"gà tây quay"},{"en":"turkey breast","vi":"ức gà tây"},{"en":"wild turkey","vi":"gà tây hoang dã"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chim thì đếm được, thịt thì không đếm được; dùng chỉ tác phẩm thất bại là cách nói thân mật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aquarium', 'en-b1-15', 'aquarium', '/əˈkweriəm/', 'B1', 'bể cá cảnh; hồ cá; thủy cung', 'n.', NULL, 'Đồng nghĩa: fish tank', 'Dùng để chỉ cả bể cá nuôi ở nhà lẫn viện bảo hiểm sinh vật biển lớn.', 'Two orange fish swim among plants in our aquarium.', NULL, 'Hai con cá cam bơi lội giữa các khóm cây trong bể cá nhà chúng tôi.', '{"wordId":"aquarium","ukIpa":"/əˈkweəriəm/","usIpa":"/əˈkweriəm/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A water-filled container for keeping fish and other aquatic animals","vi":"bể cá cảnh; hồ cá"},{"pos":"n.","en":"A public building where people can see aquatic animals","vi":"thủy cung"}],"examples":[{"en":"Two orange fish swim among plants in our aquarium.","vi":"Hai con cá cam bơi lội giữa các khóm cây trong bể cá nhà chúng tôi.","audioKind":"ex"},{"en":"A well-managed aquarium can teach visitors about marine ecosystems and encourage greater concern for ocean conservation.","vi":"Một thủy cung được quản lý tốt có thể giúp du khách tìm hiểu về hệ sinh thái biển và nâng cao ý thức bảo vệ đại dương.","audioKind":"ex2"}],"collocations":[{"en":"a freshwater aquarium","vi":"bể cá nước ngọt"},{"en":"a public aquarium","vi":"thủy cung công cộng"},{"en":"aquarium fish","vi":"cá cảnh"}],"wordFamily":[],"synonyms":["fish tank"],"antonyms":[],"tipVi":"Dùng để chỉ cả bể cá nuôi ở nhà lẫn viện bảo hiểm sinh vật biển lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sunrise', 'en-b1-15', 'sunrise', '/ˈsʌnraɪz/', 'B1', 'bình minh; lúc mặt trời mọc', 'n.', NULL, 'Trái nghĩa: sunset', 'Dùng "at sunrise" để chỉ thời điểm bình minh; từ trái nghĩa là "sunset" ( hoàng hôn).', 'We woke early to watch the sunrise over the lake.', NULL, 'Chúng tôi thức dậy từ sớm để ngắm cảnh bình minh trên hồ.', '{"wordId":"sunrise","ukIpa":"/ˈsʌnraɪz/","usIpa":"/ˈsʌnraɪz/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"The appearance of the sun above the horizon each morning.","vi":"bình minh; lúc mặt trời mọc"}],"examples":[{"en":"We woke early to watch the sunrise over the lake.","vi":"Chúng tôi thức dậy từ sớm để ngắm cảnh bình minh trên hồ.","audioKind":"ex"},{"en":"Outdoor activities scheduled around sunrise allow tourists to enjoy cooler temperatures and observe local wildlife.","vi":"Các hoạt động ngoài trời được lên lịch vào thời điểm bình minh giúp du khách tận hưởng nền nhiệt dịu mát hơn và quan sát động vật hoang dã địa phương.","audioKind":"ex2"}],"collocations":[{"en":"at sunrise","vi":"vào lúc bình minh"},{"en":"watch the sunrise","vi":"ngắm bình minh"},{"en":"before sunrise","vi":"trước khi mặt trời mọc"}],"wordFamily":[],"synonyms":[],"antonyms":["sunset"],"tipVi":"Dùng \"at sunrise\" để chỉ thời điểm bình minh; từ trái nghĩa là \"sunset\" ( hoàng hôn).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sandy', 'en-b1-15', 'sandy', '/ˈsændi/', 'B1', 'nhiều cát; có nhiều cát; có màu vàng cát; màu nâu nhạt', 'adj.', 'sand (n.)', NULL, 'Từ "sandy" vừa dùng để miêu tả bề mặt địa hình ngập cát, vừa dùng để chỉ màu tóc vàng nhạt tự nhiên.', 'We left our shoes beside the sandy path.', NULL, 'Chúng tôi để giày dép bên lối đi nhiều cát.', '{"wordId":"sandy","ukIpa":"/ˈsændi/","usIpa":"/ˈsændi/","cefr":"B1","topic":"nature","senses":[{"pos":"adj.","en":"covered with sand or containing a lot of sand","vi":"nhiều cát; có nhiều cát"},{"pos":"adj.","en":"light yellowish brown in colour, especially describing hair","vi":"có màu vàng cát; màu nâu nhạt"}],"examples":[{"en":"We left our shoes beside the sandy path.","vi":"Chúng tôi để giày dép bên lối đi nhiều cát.","audioKind":"ex"},{"en":"Sandy soils often require careful irrigation because they retain less water than soils with more clay.","vi":"Đất pha cát thường cần được tưới tiêu cẩn thận vì khả năng giữ nước kém hơn so với đất có hàm lượng đất sét cao.","audioKind":"ex2"}],"collocations":[{"en":"sandy beach","vi":"bãi cát"},{"en":"sandy soil","vi":"đất cát"},{"en":"sandy hair","vi":"mái tóc màu vàng cát"}],"wordFamily":["sand (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ \"sandy\" vừa dùng để miêu tả bề mặt địa hình ngập cát, vừa dùng để chỉ màu tóc vàng nhạt tự nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_atlantic', 'en-b1-15', 'Atlantic', '/ətˈlæntɪk/', 'B1', 'Đại Tây Dương; thuộc về Đại Tây Dương', 'n.', 'transatlantic (adj.)', NULL, 'Luôn viết hoa chữ cái đầu; khi làm danh từ thường đi kèm mạo từ xác định "the Atlantic".', 'We watched huge waves roll in from the Atlantic.', NULL, 'Chúng tôi đứng ngắm những con sóng lớn cuồn cuộn đổ vào từ phía Đại Tây Dương.', '{"wordId":"atlantic","ukIpa":"/ətˈlæntɪk/","usIpa":"/ətˈlæntɪk/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"The ocean between the Americas and Europe and Africa.","vi":"Đại Tây Dương"},{"pos":"adj.","en":"Relating to the Atlantic Ocean or its surrounding regions.","vi":"thuộc về Đại Tây Dương"}],"examples":[{"en":"We watched huge waves roll in from the Atlantic.","vi":"Chúng tôi đứng ngắm những con sóng lớn cuồn cuộn đổ vào từ phía Đại Tây Dương.","audioKind":"ex"},{"en":"Changes in Atlantic ocean currents could influence weather patterns and agricultural production across several continents.","vi":"Sự thay đổi của các dòng hải lưu Đại Tây Dương có thể tác động đến các hình thái thời tiết và năng suất nông nghiệp ở nhiều châu lục.","audioKind":"ex2"}],"collocations":[{"en":"the Atlantic Ocean","vi":"vùng biển Đại Tây Dương"},{"en":"cross the Atlantic","vi":"vượt Đại Tây Dương"},{"en":"the Atlantic coast","vi":"bờ biển Đại Tây Dương"}],"wordFamily":["transatlantic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Luôn viết hoa chữ cái đầu; khi làm danh từ thường đi kèm mạo từ xác định \"the Atlantic\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pole', 'en-b1-15', 'pole', '/poʊl/', 'B1', 'cây sào; cột; cực (địa cầu, nam châm, pin); cực đối lập; mặt đối lập hoàn toàn', 'n.', 'polar (adj.)', 'Đồng nghĩa: rod', 'pole phát âm giống poll; tên địa lý the North Pole cần viết hoa.', 'We used a long pole to support the tent.', NULL, 'Chúng tôi dùng một cây sào dài để chống lều.', '{"wordId":"pole","ukIpa":"/pəʊl/","usIpa":"/poʊl/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A long, narrow stick or post, often used for support.","vi":"cây sào; cột"},{"pos":"n.","en":"Either of two opposite ends of Earth, a magnet, or battery.","vi":"cực (địa cầu, nam châm, pin)"},{"pos":"n.","en":"Either of two completely opposite positions or qualities.","vi":"cực đối lập; mặt đối lập hoàn toàn"}],"examples":[{"en":"We used a long pole to support the tent.","vi":"Chúng tôi dùng một cây sào dài để chống lều.","audioKind":"ex"},{"en":"Climate change is affecting both poles, although the environmental consequences differ significantly between the two regions.","vi":"Biến đổi khí hậu đang tác động đến cả hai cực, mặc dù hậu quả môi trường có sự khác biệt đáng kể giữa hai khu vực này.","audioKind":"ex2"}],"collocations":[{"en":"a tent pole","vi":"cọc chống lều"},{"en":"the North Pole","vi":"Cực Bắc"},{"en":"a magnetic pole","vi":"cực từ"},{"en":"poles apart","vi":"khác biệt một trời một vực"}],"wordFamily":["polar (adj.)"],"synonyms":["rod"],"antonyms":[],"tipVi":"pole phát âm giống poll; tên địa lý the North Pole cần viết hoa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mud', 'en-b1-15', 'mud', '/mʌd/', 'B1', 'bùn; bùn lầy', 'n.', 'muddy (adj.)', NULL, 'Danh từ mud thường không đếm được; tính từ chỉ sự bùn lầy là muddy.', 'Our boots were covered in mud after the walk.', NULL, 'Đôi bốt của chúng tôi dính đầy bùn sau buổi đi dạo.', '{"wordId":"mud","ukIpa":"/mʌd/","usIpa":"/mʌd/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"Soft, wet earth made when soil mixes with water.","vi":"bùn; bùn lầy"}],"examples":[{"en":"Our boots were covered in mud after the walk.","vi":"Đôi bốt của chúng tôi dính đầy bùn sau buổi đi dạo.","audioKind":"ex"},{"en":"Heavy rainfall can turn unpaved roads into mud, making rural communities difficult to reach.","vi":"Mưa lớn có thể biến những con đường chưa trải nhựa thành bùn lầy, khiến việc tiếp cận các cộng đồng nông thôn trở nên khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"thick mud","vi":"bùn dày"},{"en":"covered in mud","vi":"dính đầy bùn"},{"en":"get stuck in the mud","vi":"sa lầy; kẹt trong bùn"}],"wordFamily":["muddy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ mud thường không đếm được; tính từ chỉ sự bùn lầy là muddy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cycle', 'en-b1-15', 'cycle', '/ˈsaɪkəl/', 'B1', 'chu kỳ; vòng tuần hoàn; đi xe đạp; xe đạp', 'n.', 'cycling (n.), cyclist (n.), cyclical (adj.)', NULL, 'Cycle làm động từ nghĩa là đi xe đạp; đi làm bằng xe đạp dùng cycle to work.', 'I usually cycle to the park on sunny mornings.', NULL, 'Tôi thường đạp xe đến công viên vào những buổi sáng trời nắng.', '{"wordId":"cycle","ukIpa":"/ˈsaɪkəl/","usIpa":"/ˈsaɪkəl/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a series of events or stages that repeats","vi":"chu kỳ; vòng tuần hoàn"},{"pos":"v.","en":"to travel by bicycle","vi":"đi xe đạp"},{"pos":"n.","en":"a vehicle with two wheels powered by pedalling","vi":"xe đạp"}],"examples":[{"en":"I usually cycle to the park on sunny mornings.","vi":"Tôi thường đạp xe đến công viên vào những buổi sáng trời nắng.","audioKind":"ex"},{"en":"Climate change can disrupt the natural water cycle, increasing the frequency of droughts and floods in some regions.","vi":"Biến đổi khí hậu có thể phá vỡ vòng tuần hoàn nước tự nhiên, làm gia tăng tần suất hạn hán và lũ lụt ở một số khu vực.","audioKind":"ex2"}],"collocations":[{"en":"life cycle","vi":"vòng đời; chu kỳ sống"},{"en":"water cycle","vi":"chu trình nước"},{"en":"vicious cycle","vi":"vòng luẩn quẩn"},{"en":"cycle to work","vi":"đạp xe đi làm"}],"wordFamily":["cycling (n.)","cyclist (n.)","cyclical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cycle làm động từ nghĩa là đi xe đạp; đi làm bằng xe đạp dùng cycle to work.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cliff', 'en-b1-15', 'cliff', '/klɪf/', 'B1', 'vách đá; vách dựng đứng', 'n.', NULL, NULL, 'Cliff emphasizes a steep rock face, not just a general hillside.', 'We watched seabirds nesting halfway up the cliff.', NULL, 'Chúng tôi ngắm nhìn những chú chim biển làm tổ giữa lưng chừng vách đá.', '{"wordId":"cliff","ukIpa":"/klɪf/","usIpa":"/klɪf/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A high, very steep rock face, often beside the sea.","vi":"vách đá; vách dựng đứng"}],"examples":[{"en":"We watched seabirds nesting halfway up the cliff.","vi":"Chúng tôi ngắm nhìn những chú chim biển làm tổ giữa lưng chừng vách đá.","audioKind":"ex"},{"en":"Coastal erosion can weaken a cliff over time, putting nearby homes and walking routes at risk.","vi":"Sự xói mòn bờ biển có thể làm suy yếu vách đá theo thời gian, đặt các ngôi nhà và tuyến đường đi bộ gần đó vào tình trạng nguy hiểm.","audioKind":"ex2"}],"collocations":[{"en":"a cliff edge","vi":"mép vách đá"},{"en":"a sheer cliff","vi":"vách đá dựng đứng"},{"en":"a cliff face","vi":"bề mặt vách đá"},{"en":"coastal cliffs","vi":"vách đá ven biển"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cliff emphasizes a steep rock face, not just a general hillside.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_waterfall', 'en-b1-15', 'waterfall', '/ˈwɔːtərfɔːl/', 'B1', 'thác nước', 'n.', NULL, 'Đồng nghĩa: cascade', 'Danh từ đếm được: dùng a waterfall để chỉ một thác nước.', 'We could hear the waterfall long before we saw it.', NULL, 'Chúng tôi có thể nghe thấy tiếng thác nước từ rất lâu trước khi nhìn thấy nó.', '{"wordId":"waterfall","ukIpa":"/ˈwɔːtəfɔːl/","usIpa":"/ˈwɔːtərfɔːl/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"Water falling from a height over a steep rock face","vi":"thác nước"}],"examples":[{"en":"We could hear the waterfall long before we saw it.","vi":"Chúng tôi có thể nghe thấy tiếng thác nước từ rất lâu trước khi nhìn thấy nó.","audioKind":"ex"},{"en":"Tourism near a waterfall can support local businesses, but visitor facilities should protect the surrounding natural habitat.","vi":"Hoạt động du lịch gần thác nước có thể hỗ trợ các doanh nghiệp địa phương, nhưng các tiện ích phục vụ du khách cần phải bảo vệ môi trường sống tự nhiên xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"a spectacular waterfall","vi":"một ngọn thác ngoạn mục"},{"en":"the base of a waterfall","vi":"chân thác nước"},{"en":"a cascading waterfall","vi":"thác nước chảy xiết"}],"wordFamily":[],"synonyms":["cascade"],"antonyms":[],"tipVi":"Danh từ đếm được: dùng a waterfall để chỉ một thác nước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_float', 'en-b1-15', 'float', '/floʊt/', 'B1', 'nổi; trôi bồng bềnh; đề xuất; đưa ra ý kiến; xe hoa diễu hành', 'v.', 'floating (adj.), floatation (n.)', 'Đồng nghĩa: drift · Trái nghĩa: sink', 'float an idea là đưa ra ý tưởng để thảo luận chứ chưa phải là thực hiện.', 'A yellow leaf floated gently across the garden pond.', NULL, 'Một chiếc lá vàng trôi lững lờ qua ao vườn.', '{"wordId":"float","ukIpa":"/fləʊt/","usIpa":"/floʊt/","cefr":"B1","topic":"nature","senses":[{"pos":"v.","en":"To stay on a liquid''s surface or move gently through air.","vi":"nổi; trôi bồng bềnh"},{"pos":"v.","en":"To suggest an idea for others to consider.","vi":"đề xuất; đưa ra ý kiến"},{"pos":"n.","en":"A decorated vehicle used in a parade.","vi":"xe hoa diễu hành"}],"examples":[{"en":"A yellow leaf floated gently across the garden pond.","vi":"Một chiếc lá vàng trôi lững lờ qua ao vườn.","audioKind":"ex"},{"en":"Researchers have floated the idea of using artificial islands to provide additional housing in crowded coastal cities.","vi":"Các nhà nghiên cứu đã đưa ra ý tưởng sử dụng các hòn đảo nhân tạo để cung cấp thêm nhà ở tại các thành phố ven biển đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"float on water","vi":"nổi trên mặt nước"},{"en":"float an idea","vi":"đưa ra một ý tưởng"},{"en":"float downstream","vi":"trôi xuôi dòng"},{"en":"parade float","vi":"xe hoa diễu hành"}],"wordFamily":["floating (adj.)","floatation (n.)"],"synonyms":["drift"],"antonyms":["sink"],"tipVi":"float an idea là đưa ra ý tưởng để thảo luận chứ chưa phải là thực hiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bay', 'en-b1-15', 'bay', '/beɪ/', 'B1', 'vịnh; vùng không gian riêng; ô đỗ xe; khu vực chuyên dụng', 'n.', NULL, NULL, 'bay chủ yếu chỉ hải vận/vịnh; trong ngữ cảnh đỗ xe hoặc bốc dỡ hàng hóa thì chỉ khu vực chuyên dụng.', 'Small fishing boats floated in the sheltered bay.', NULL, 'Những chiếc thuyền đánh cá nhỏ bồng bềnh trong vịnh kín gió.', '{"wordId":"bay","ukIpa":"/beɪ/","usIpa":"/beɪ/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"An area of sea partly enclosed by land.","vi":"vịnh"},{"pos":"n.","en":"A designated space within a building or parking area.","vi":"vùng không gian riêng; ô đỗ xe; khu vực chuyên dụng"}],"examples":[{"en":"Small fishing boats floated in the sheltered bay.","vi":"Những chiếc thuyền đánh cá nhỏ bồng bềnh trong vịnh kín gió.","audioKind":"ex"},{"en":"Coastal development around the bay must be carefully managed to protect marine habitats and local livelihoods.","vi":"Việc phát triển ven biển xung quanh vịnh phải được quản lý cẩn thận để bảo vệ các môi trường sống dưới nước và sinh kế của người dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"sheltered bay","vi":"vịnh kín gió"},{"en":"sandy bay","vi":"vịnh cát"},{"en":"parking bay","vi":"chỗ đỗ xe"},{"en":"loading bay","vi":"khu vực bốc dỡ hàng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"bay chủ yếu chỉ hải vận/vịnh; trong ngữ cảnh đỗ xe hoặc bốc dỡ hàng hóa thì chỉ khu vực chuyên dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_penguin', 'en-b1-15', 'penguin', '/ˈpeŋɡwɪn/', 'B1', 'chim cánh cụt', 'n.', NULL, NULL, 'Chim cánh cụt là loài chim không biết bay; không phải tất cả đều sống ở Nam Cực.', 'The penguin waddled across the rocks towards the sea.', NULL, 'Con chim cánh cụt lạch bạch bước qua những tảng đá hướng về phía biển.', '{"wordId":"penguin","ukIpa":"/ˈpeŋɡwɪn/","usIpa":"/ˈpeŋɡwɪn/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a flightless seabird with black and white feathers, found mainly south","vi":"chim cánh cụt"}],"examples":[{"en":"The penguin waddled across the rocks towards the sea.","vi":"Con chim cánh cụt lạch bạch bước qua những tảng đá hướng về phía biển.","audioKind":"ex"},{"en":"Changes in ocean temperatures can affect penguin populations by altering the availability of fish and other prey.","vi":"Sự thay đổi nhiệt độ đại dương có thể ảnh hưởng đến các quần thể chim cánh cụt bằng cách làm thay đổi nguồn cung cấp cá và các loài con mồi khác.","audioKind":"ex2"}],"collocations":[{"en":"penguin colony","vi":"bầy chim cánh cụt"},{"en":"penguin chick","vi":"chim cánh cụt non"},{"en":"penguin species","vi":"loài chim cánh cụt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chim cánh cụt là loài chim không biết bay; không phải tất cả đều sống ở Nam Cực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_turtle', 'en-b1-15', 'turtle', '/ˈtɝːtəl/', 'B1', 'rùa biển; con rùa', 'n.', NULL, NULL, 'Trong tiếng Anh, turtle thường chỉ rùa sống dưới nước hoặc rùa biển; rùa cạn thường được gọi là tortoise.', 'We watched a turtle swimming slowly over the reef.', NULL, 'Chúng tôi ngắm nhìn một con rùa đang bơi thong thả bên trên rạn san hô.', '{"wordId":"turtle","ukIpa":"/ˈtɜːtəl/","usIpa":"/ˈtɝːtəl/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A reptile with a protective shell, often living in water.","vi":"rùa biển; con rùa"}],"examples":[{"en":"We watched a turtle swimming slowly over the reef.","vi":"Chúng tôi ngắm nhìn một con rùa đang bơi thong thả bên trên rạn san hô.","audioKind":"ex"},{"en":"Reducing plastic pollution in coastal waters is essential for protecting turtle populations and other marine wildlife.","vi":"Việc giảm thiểu ô nhiễm nhựa ở vùng nước ven biển đóng vai trò thiết yếu trong việc bảo vệ các quần thể rùa và động vật hoang dã dưới nước khác.","audioKind":"ex2"}],"collocations":[{"en":"sea turtle","vi":"rùa biển"},{"en":"freshwater turtle","vi":"rùa nước ngọt"},{"en":"turtle shell","vi":"mai rùa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh, turtle thường chỉ rùa sống dưới nước hoặc rùa biển; rùa cạn thường được gọi là tortoise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bush', 'en-b1-15', 'bush', '/bʊʃ/', 'B1', 'bụi cây; cây bụi; vùng hoang dã; rừng rậm', 'n.', 'bushy (adj.)', 'Đồng nghĩa: shrub', 'Bush là danh từ đếm được; the bush có thể chỉ vùng hoang dã ở Úc hoặc các nơi khác.', 'A small bird was hiding in the rose bush.', NULL, 'Một chú chim nhỏ đang ẩn nấp trong bụi hoa hồng.', '{"wordId":"bush","ukIpa":"/bʊʃ/","usIpa":"/bʊʃ/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A woody plant with several branches growing near the ground.","vi":"bụi cây; cây bụi"},{"pos":"n.","en":"Wild, uncultivated land, especially in Australia or Africa.","vi":"vùng hoang dã; rừng rậm"}],"examples":[{"en":"A small bird was hiding in the rose bush.","vi":"Một chú chim nhỏ đang ẩn nấp trong bụi hoa hồng.","audioKind":"ex"},{"en":"Planting native bushes in urban gardens can provide shelter and food for local wildlife.","vi":"Việc trồng các loài cây bụi bản địa trong vườn đô thị có thể cung cấp nơi trú ẩn và thức ăn cho động vật hoang dã địa phương.","audioKind":"ex2"}],"collocations":[{"en":"rose bush","vi":"bụi hoa hồng"},{"en":"dense bushes","vi":"bụi rậm dày đặc"},{"en":"in the bush","vi":"ở vùng hoang dã"}],"wordFamily":["bushy (adj.)"],"synonyms":["shrub"],"antonyms":[],"tipVi":"Bush là danh từ đếm được; the bush có thể chỉ vùng hoang dã ở Úc hoặc các nơi khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cattle', 'en-b1-15', 'cattle', '/ˈkætl/', 'B1', 'gia súc; đàn bò', 'n.', NULL, NULL, 'cattle là danh từ tập hợp số nhiều, đi với động từ số nhiều như are; một con bò không dùng a cattle.', 'The cattle gathered under a tree during the storm.', NULL, 'Đàn bò tụ tập dưới một gốc cây trong cơn giông bão.', '{"wordId":"cattle","ukIpa":"/ˈkætl/","usIpa":"/ˈkætl/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"Farm animals kept for their milk or meat.","vi":"gia súc; đàn bò"}],"examples":[{"en":"The cattle gathered under a tree during the storm.","vi":"Đàn bò tụ tập dưới một gốc cây trong cơn giông bão.","audioKind":"ex"},{"en":"Raising cattle requires substantial land and water, which can place pressure on local ecosystems.","vi":"Việc chăn nuôi gia súc đòi hỏi lượng lớn đất đai và nước, điều này có thể gây áp lực lên hệ sinh thái địa phương.","audioKind":"ex2"}],"collocations":[{"en":"raise cattle","vi":"chăn nuôi gia súc"},{"en":"a herd of cattle","vi":"một đàn bò"},{"en":"dairy cattle","vi":"bò sữa"},{"en":"beef cattle","vi":"bò thịt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"cattle là danh từ tập hợp số nhiều, đi với động từ số nhiều như are; một con bò không dùng a cattle.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_corn', 'en-b1-15', 'corn', '/kɔːrn/', 'B1', 'ngô; bắp; ngũ cốc', 'n.', NULL, 'Đồng nghĩa: maize', 'Trong tiếng Anh-Mỹ, corn thường chỉ ngô; trong tiếng Anh-Anh, từ này cũng có thể chỉ chung các loại ngũ cốc.', 'We grilled fresh corn and served it with butter.', NULL, 'Chúng tôi nướng ngô tươi và phết bơ lên ăn.', '{"wordId":"corn","ukIpa":"/kɔːn/","usIpa":"/kɔːrn/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a tall crop with large heads of yellow edible seeds","vi":"ngô; bắp"},{"pos":"n.","en":"grain crops such as wheat or barley, especially in British English","vi":"ngũ cốc"}],"examples":[{"en":"We grilled fresh corn and served it with butter.","vi":"Chúng tôi nướng ngô tươi và phết bơ lên ăn.","audioKind":"ex"},{"en":"Farmers growing corn may need more efficient irrigation systems as droughts become increasingly frequent.","vi":"Nông dân trồng ngô có thể cần các hệ thống tưới tiêu hiệu quả hơn khi tình trạng hạn hán ngày càng trở nên thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"corn on the cob","vi":"bắp ngô luộc hoặc nướng"},{"en":"corn kernels","vi":"hạt ngô"},{"en":"corn field","vi":"cánh đồng ngô"},{"en":"corn oil","vi":"dầu ngô"}],"wordFamily":[],"synonyms":["maize"],"antonyms":[],"tipVi":"Trong tiếng Anh-Mỹ, corn thường chỉ ngô; trong tiếng Anh-Anh, từ này cũng có thể chỉ chung các loại ngũ cốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wheat', 'en-b1-15', 'wheat', '/wiːt/', 'B1', 'lúa mì; mỳ', 'n.', NULL, NULL, 'wheat thường không đếm được; một hạt lúa mì dùng a grain of wheat.', 'Golden wheat swayed in the field behind our house.', NULL, 'Lúa mì vàng óng đung đưa trên cánh đồng phía sau nhà chúng tôi.', '{"wordId":"wheat","ukIpa":"/wiːt/","usIpa":"/wiːt/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a cereal crop whose grain is commonly ground into flour","vi":"lúa mì; mỳ"}],"examples":[{"en":"Golden wheat swayed in the field behind our house.","vi":"Lúa mì vàng óng đung đưa trên cánh đồng phía sau nhà chúng tôi.","audioKind":"ex"},{"en":"Prolonged droughts can reduce wheat harvests, raising food prices and threatening food security in vulnerable regions.","vi":"Hạn hán kéo dài có thể làm giảm sản lượng lúa mì, đẩy giá lương thực lên cao và đe dọa an ninh lương thực ở các vùng dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"grow wheat","vi":"trồng lúa mì"},{"en":"wheat flour","vi":"bột mì"},{"en":"wheat harvest","vi":"vụ thu hoạch lúa mì"},{"en":"whole wheat","vi":"toàn phần lúa mì"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"wheat thường không đếm được; một hạt lúa mì dùng a grain of wheat.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shade', 'en-b1-15', 'shade', '/ʃeɪd/', 'B1', 'bóng râm; bóng mát; sắc thái; tông màu; che bóng; che nắng', 'n.', 'shady (adj.), shaded (adj.), shading (n.)', NULL, 'shade thường chỉ vùng râm mát; shadow chỉ cái bóng do vật thể đổ xuống.', 'We rested in the shade beneath a large tree.', NULL, 'Chúng tôi nghỉ ngơi trong bóng râm dưới một gốc cây lớn.', '{"wordId":"shade","ukIpa":"/ʃeɪd/","usIpa":"/ʃeɪd/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"an area protected from direct sunlight","vi":"bóng râm; bóng mát"},{"pos":"n.","en":"a particular form of a colour","vi":"sắc thái; tông màu"},{"pos":"v.","en":"to protect something from direct light","vi":"che bóng; che nắng"}],"examples":[{"en":"We rested in the shade beneath a large tree.","vi":"Chúng tôi nghỉ ngơi trong bóng râm dưới một gốc cây lớn.","audioKind":"ex"},{"en":"Planting trees along urban streets provides shade and can reduce residents'' exposure to extreme summer heat.","vi":"Việc trồng cây dọc theo các con đường đô thị tạo ra bóng mát và có thể làm giảm mức độ tiếp xúc của cư dân với cái nóng gay gắt của mùa hè.","audioKind":"ex2"}],"collocations":[{"en":"in the shade","vi":"ở trong bóng râm"},{"en":"provide shade","vi":"cung cấp bóng mát"},{"en":"a shade of blue","vi":"một sắc thái xanh lam"},{"en":"shade your eyes","vi":"che mắt tránh ánh sáng"}],"wordFamily":["shady (adj.)","shaded (adj.)","shading (n.)"],"synonyms":[],"antonyms":[],"tipVi":"shade thường chỉ vùng râm mát; shadow chỉ cái bóng do vật thể đổ xuống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_15_1', 'en-b1-15', 'Cách dùng “valley” (n.) — thung lũng; thung lũng sông', 'a river valley  ·  a deep valley  ·  the valley floor', 'Valley là vùng đất trũng nằm giữa các ngọn đồi hoặc dãy núi, không đồng nghĩa với thung lũng lòng chảo (basin).', NULL, '[{"hanzi":"A narrow river winds through the green valley.","pinyin":"","meaning":"Một dòng sông nhỏ uốn lượn qua thung lũng xanh tươi."},{"hanzi":"Farming communities in the valley depend on seasonal rainfall to maintain their crops and support local livelihoods.","pinyin":"","meaning":"Các cộng đồng làm nông nghiệp trong thung lũng phụ thuộc vào lượng mưa theo mùa để duy trì mùa màng và bảo đảm sinh kế địa phương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_15_2', 'en-b1-15', 'Cách dùng “corn” (n.) — ngô; bắp', 'corn on the cob  ·  corn kernels  ·  corn field', 'Trong tiếng Anh-Mỹ, corn thường chỉ ngô; trong tiếng Anh-Anh, từ này cũng có thể chỉ chung các loại ngũ cốc.', 'Đồng nghĩa: maize', '[{"hanzi":"We grilled fresh corn and served it with butter.","pinyin":"","meaning":"Chúng tôi nướng ngô tươi và phết bơ lên ăn."},{"hanzi":"Farmers growing corn may need more efficient irrigation systems as droughts become increasingly frequent.","pinyin":"","meaning":"Nông dân trồng ngô có thể cần các hệ thống tưới tiêu hiệu quả hơn khi tình trạng hạn hán ngày càng trở nên thường xuyên."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_15_3', 'en-b1-15', 'Cách dùng “salmon” (n.) — cá hồi; thịt cá hồi', 'smoked salmon  ·  wild salmon  ·  salmon fillet', 'Chữ l không phát âm; khi chỉ con cá thì số ít và số nhiều giống nhau, khi chỉ thịt cá thì không đếm được.', NULL, '[{"hanzi":"We watched a salmon leap up the rocky stream.","pinyin":"","meaning":"Chúng tôi nhìn thấy một con cá hồi bơi vượt qua con suối nhiều đá lên thượng nguồn."},{"hanzi":"Dams can disrupt salmon migration, so river management should consider both energy production and wildlife protection.","pinyin":"","meaning":"Các con đập có thể cản trở sự di cư của cá hồi, vì vậy việc quản lý sông ngòi cần cân nhắc cả việc sản xuất năng lượng lẫn bảo vệ động vật hoang dã."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_15_4', 'en-b1-15', 'Cách dùng “turtle” (n.) — rùa biển; con rùa', 'sea turtle  ·  freshwater turtle  ·  turtle shell', 'Trong tiếng Anh, turtle thường chỉ rùa sống dưới nước hoặc rùa biển; rùa cạn thường được gọi là tortoise.', NULL, '[{"hanzi":"We watched a turtle swimming slowly over the reef.","pinyin":"","meaning":"Chúng tôi ngắm nhìn một con rùa đang bơi thong thả bên trên rạn san hô."},{"hanzi":"Reducing plastic pollution in coastal waters is essential for protecting turtle populations and other marine wildlife.","pinyin":"","meaning":"Việc giảm thiểu ô nhiễm nhựa ở vùng nước ven biển đóng vai trò thiết yếu trong việc bảo vệ các quần thể rùa và động vật hoang dã dưới nước khác."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_15_1', 'en-b1-15', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_1_1', 'ten_b1_15_1', 'northern', 'My grandparents live in a quiet northern village.', 'My grandparents live in a quiet northern village.', '/ˈnɔːrðərn/', 'Ông bà tôi sống ở một ngôi làng yên bình ở miền bắc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_1_2', 'ten_b1_15_1', 'poisonous', 'Some colourful berries are poisonous, so leave them alone.', 'Some colourful berries are poisonous, so leave them alone.', '/ˈpɔɪzənəs/', 'Một số loại quả mọng có màu sắc sặc sỡ rất có độc, vì vậy đừng chạm vào chúng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_1_3', 'ten_b1_15_1', 'valley', 'A narrow river winds through the green valley.', 'A narrow river winds through the green valley.', '/ˈvæli/', 'Một dòng sông nhỏ uốn lượn qua thung lũng xanh tươi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_1_4', 'ten_b1_15_1', 'dolphin', 'A dolphin leapt beside our boat early this morning.', 'A dolphin leapt beside our boat early this morning.', '/ˈdɑːlfɪn/', 'Một chú cá heo đã nhảy vọt lên ngay cạnh thuyền của chúng tôi vào sáng sớm nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_1_5', 'ten_b1_15_1', 'goose', 'A white goose waddled across the path towards us.', 'A white goose waddled across the path towards us.', '/ɡuːs/', 'Một con ngỗng trắng lạch bạch đi qua con đường hướng về phía chúng tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_1_6', 'ten_b1_15_1', 'salmon', 'We watched a salmon leap up the rocky stream.', 'We watched a salmon leap up the rocky stream.', '/ˈsæmən/', 'Chúng tôi nhìn thấy một con cá hồi bơi vượt qua con suối nhiều đá lên thượng nguồn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_1_7', 'ten_b1_15_1', 'turkey', 'A turkey spread its tail feathers near the farm gate.', 'A turkey spread its tail feathers near the farm gate.', '/ˈtɜːrki/', 'Một con gà tây xòe lông đuôi ở gần cổng trang trại.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_1_8', 'ten_b1_15_1', 'aquarium', 'Two orange fish swim among plants in our aquarium.', 'Two orange fish swim among plants in our aquarium.', '/əˈkweriəm/', 'Hai con cá cam bơi lội giữa các khóm cây trong bể cá nhà chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_15_1_1', 'en-b1-15', 'ten_b1_15_1', 'listening', 'listening', 'My grandparents live in a quiet northern village.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ông bà tôi sống ở một ngôi làng yên bình ở miền bắc.","Con chim cánh cụt lạch bạch bước qua những tảng đá hướng về phía biển.","Chúng tôi thức dậy từ sớm để ngắm cảnh bình minh trên hồ.","Hai con cá cam bơi lội giữa các khóm cây trong bể cá nhà chúng tôi."]'::jsonb, 0, 'My grandparents live in a quiet northern village. → Ông bà tôi sống ở một ngôi làng yên bình ở miền bắc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_15_1_2', 'en-b1-15', 'ten_b1_15_1', 'listening', 'listening', 'Some colourful berries are poisonous, so leave them alone.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một con ngỗng trắng lạch bạch đi qua con đường hướng về phía chúng tôi.","Đàn bò tụ tập dưới một gốc cây trong cơn giông bão.","Một số loại quả mọng có màu sắc sặc sỡ rất có độc, vì vậy đừng chạm vào chúng.","Chúng tôi thức dậy từ sớm để ngắm cảnh bình minh trên hồ."]'::jsonb, 2, 'Some colourful berries are poisonous, so leave them alone. → Một số loại quả mọng có màu sắc sặc sỡ rất có độc, vì vậy đừng chạm vào chúng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_15_1_3', 'en-b1-15', 'ten_b1_15_1', 'listening', 'listening', 'A narrow river winds through the green valley.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi có thể nghe thấy tiếng thác nước từ rất lâu trước khi nhìn thấy nó.","Một con gà tây xòe lông đuôi ở gần cổng trang trại.","Một dòng sông nhỏ uốn lượn qua thung lũng xanh tươi.","Hai con cá cam bơi lội giữa các khóm cây trong bể cá nhà chúng tôi."]'::jsonb, 2, 'A narrow river winds through the green valley. → Một dòng sông nhỏ uốn lượn qua thung lũng xanh tươi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_15_2', 'en-b1-15', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_2_1', 'ten_b1_15_2', 'northern', 'Northern regions often face higher heating costs, making energy efficiency particularly important for local households.', 'Northern regions often face higher heating costs, making energy efficiency particularly important for local households.', '/ˈnɔːrðərn/', 'Các vùng phía bắc thường phải đối mặt với chi phí sưởi ấm cao hơn, điều này làm cho hiệu quả năng lượng trở nên đặc biệt quan trọng đối với các hộ gia đình địa phương.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_2_2', 'ten_b1_15_2', 'poisonous', 'Factories must prevent poisonous substances from entering rivers that supply drinking water to nearby communities.', 'Factories must prevent poisonous substances from entering rivers that supply drinking water to nearby communities.', '/ˈpɔɪzənəs/', 'Các nhà máy phải ngăn chặn các chất độc hại xâm nhập vào các con sông cung cấp nước sinh hoạt cho các cộng đồng xung quanh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_2_3', 'ten_b1_15_2', 'valley', 'Farming communities in the valley depend on seasonal rainfall to maintain their crops and support local livelihoods.', 'Farming communities in the valley depend on seasonal rainfall to maintain their crops and support local livelihoods.', '/ˈvæli/', 'Các cộng đồng làm nông nghiệp trong thung lũng phụ thuộc vào lượng mưa theo mùa để duy trì mùa màng và bảo đảm sinh kế địa phương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_2_4', 'ten_b1_15_2', 'dolphin', 'Underwater noise from shipping can disrupt dolphin communication and make it harder for these animals to find food.', 'Underwater noise from shipping can disrupt dolphin communication and make it harder for these animals to find food.', '/ˈdɑːlfɪn/', 'Tiếng ồn dưới nước do tàu bè gây ra có thể làm gián đoạn sự giao tiếp của cá heo và khiến cho loài động vật này khó kiếm thức ăn hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_2_5', 'ten_b1_15_2', 'goose', 'Protecting wetlands provides essential feeding grounds for wild geese and many other migratory birds.', 'Protecting wetlands provides essential feeding grounds for wild geese and many other migratory birds.', '/ɡuːs/', 'Việc bảo vệ các vùng đất ngập nước cung cấp các bãi kiếm ăn thiết yếu cho ngỗng trời và nhiều loài chim di cư khác.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_15_2_6', 'ten_b1_15_2', 'salmon', 'Dams can disrupt salmon migration, so river management should consider both energy production and wildlife protection.', 'Dams can disrupt salmon migration, so river management should consider both energy production and wildlife protection.', '/ˈsæmən/', 'Các con đập có thể cản trở sự di cư của cá hồi, vì vậy việc quản lý sông ngòi cần cân nhắc cả việc sản xuất năng lượng lẫn bảo vệ động vật hoang dã.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_15_2_1', 'en-b1-15', 'ten_b1_15_2', 'listening', 'listening', 'Northern regions often face higher heating costs, making energy efficiency particularly important for local households.', NULL, 'Trong câu vừa nghe, từ “northern” mang nghĩa nào sau đây?', '["khóa kéo","đội ngũ nhân viên trên tàu hoặc máy bay","thuộc về phương bắc; ở miền bắc","tiểu thuyết; truyện dài"]'::jsonb, 2, '“northern” (/ˈnɔːrðərn/): thuộc về phương bắc; ở miền bắc. Câu đầy đủ: Northern regions often face higher heating costs, making energy efficiency particularly important for local households.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_15_2_2', 'en-b1-15', 'ten_b1_15_2', 'listening', 'listening', 'Factories must prevent poisonous substances from entering rivers that supply drinking water to nearby communities.', NULL, 'Trong câu vừa nghe, từ “poisonous” mang nghĩa nào sau đây?', '["có độc; độc hại","khẩn cấp; cấp bách","thủ thư; nhân viên thư viện","cực kỳ sợ hãi; khiếp sợ"]'::jsonb, 0, '“poisonous” (/ˈpɔɪzənəs/): có độc; độc hại. Câu đầy đủ: Factories must prevent poisonous substances from entering rivers that supply drinking water to nearby communities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
