INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_2', 'en-b1-15', NULL, 'comprehensive_test', 'listening', 'Some colourful berries are poisonous, so leave them alone.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con chim cánh cụt lạch bạch bước qua những tảng đá hướng về phía biển.","Một số loại quả mọng có màu sắc sặc sỡ rất có độc, vì vậy đừng chạm vào chúng.","Chúng tôi ngắm nhìn những chú chim biển làm tổ giữa lưng chừng vách đá.","Ông bà tôi sống ở một ngôi làng yên bình ở miền bắc."]'::jsonb, 1, 'Some colourful berries are poisonous, so leave them alone. → Một số loại quả mọng có màu sắc sặc sỡ rất có độc, vì vậy đừng chạm vào chúng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_3', 'en-b1-15', NULL, 'comprehensive_test', 'listening', 'valley', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đèn pin","quần áo bẩn (hoặc mới giặt)","thung lũng; thung lũng sông","tàu vũ trụ"]'::jsonb, 2, 'valley (/ˈvæli/) → thung lũng; thung lũng sông', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_4', 'en-b1-15', NULL, 'comprehensive_test', 'listening', 'A dolphin leapt beside our boat early this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ông bà tôi sống ở một ngôi làng yên bình ở miền bắc.","Một chú cá heo đã nhảy vọt lên ngay cạnh thuyền của chúng tôi vào sáng sớm nay.","Chúng tôi dùng một cây sào dài để chống lều.","Tôi thường đạp xe đến công viên vào những buổi sáng trời nắng."]'::jsonb, 1, 'A dolphin leapt beside our boat early this morning. → Một chú cá heo đã nhảy vọt lên ngay cạnh thuyền của chúng tôi vào sáng sớm nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_5', 'en-b1-15', NULL, 'comprehensive_test', 'listening', 'goose', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc về sơ cứu; cấp cứu","tiếng khóc; sự khóc","kem chống nắng","con ngỗng"]'::jsonb, 3, 'goose (/ɡuːs/) → con ngỗng; thịt ngỗng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_6', 'en-b1-15', NULL, 'comprehensive_test', 'listening', 'We watched a salmon leap up the rocky stream.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một chú cá heo đã nhảy vọt lên ngay cạnh thuyền của chúng tôi vào sáng sớm nay.","Chúng tôi thức dậy từ sớm để ngắm cảnh bình minh trên hồ.","Chúng tôi nhìn thấy một con cá hồi bơi vượt qua con suối nhiều đá lên thượng nguồn.","Chúng tôi dùng một cây sào dài để chống lều."]'::jsonb, 2, 'We watched a salmon leap up the rocky stream. → Chúng tôi nhìn thấy một con cá hồi bơi vượt qua con suối nhiều đá lên thượng nguồn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_7', 'en-b1-15', NULL, 'comprehensive_test', 'listening', 'turkey', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["con gà tây","vùng; khu vực","giấy dán tường","thân phận; danh tính"]'::jsonb, 0, 'turkey (/ˈtɜːrki/) → con gà tây; thịt gà tây; vật phẩm thất bại; tác phẩm dở tệ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_8', 'en-b1-15', NULL, 'comprehensive_test', 'listening', 'Two orange fish swim among plants in our aquarium.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi thức dậy từ sớm để ngắm cảnh bình minh trên hồ.","Chúng tôi ngắm nhìn những chú chim biển làm tổ giữa lưng chừng vách đá.","Một con gà tây xòe lông đuôi ở gần cổng trang trại.","Hai con cá cam bơi lội giữa các khóm cây trong bể cá nhà chúng tôi."]'::jsonb, 3, 'Two orange fish swim among plants in our aquarium. → Hai con cá cam bơi lội giữa các khóm cây trong bể cá nhà chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_9', 'en-b1-15', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A large waterbird with a long neck and webbed feet.”?', '["aquarium","goose","cliff","sandy"]'::jsonb, 1, 'goose (/ɡuːs/) → con ngỗng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
