INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_18', 'en-b1-15', NULL, 'comprehensive_test', 'reading', NULL, 'Northern regions often face higher heating costs, making energy efficiency particularly important for local households.', 'Dựa vào câu trên, từ “northern” có nghĩa phù hợp nhất là gì?', '["ở phía bên kia; vượt ra xa hơn","nút giao thông; ngã rẽ; điểm giao nhau","thằn lằn; kỳ nhông","thuộc về phương bắc; ở miền bắc"]'::jsonb, 3, 'northern: thuộc về phương bắc; ở miền bắc. Dịch cả câu: Các vùng phía bắc thường phải đối mặt với chi phí sưởi ấm cao hơn, điều này làm cho hiệu quả năng lượng trở nên đặc biệt quan trọng đối với các hộ gia đình địa phương.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_19', 'en-b1-15', NULL, 'comprehensive_test', 'reading', NULL, 'Factories must prevent poisonous substances from entering rivers that supply drinking water to nearby communities.', 'Dựa vào câu trên, từ “poisonous” có nghĩa phù hợp nhất là gì?', '["mê hoặc; đáng yêu; duyên dáng","lỗi; sai sót","đơn vị; bài học","có độc; độc hại"]'::jsonb, 3, 'poisonous: có độc; độc hại; độc ác; đầy ác ý. Dịch cả câu: Các nhà máy phải ngăn chặn các chất độc hại xâm nhập vào các con sông cung cấp nước sinh hoạt cho các cộng đồng xung quanh.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_20', 'en-b1-15', NULL, 'comprehensive_test', 'reading', NULL, 'Farming communities in the valley depend on seasonal rainfall to maintain their crops and support local livelihoods.', 'Dựa vào câu trên, từ “valley” có nghĩa phù hợp nhất là gì?', '["thung lũng; thung lũng sông","nhân viên văn phòng; thư ký; nhân viên lưu trữ hồ sơ","cạnh tranh; tranh đua","tàn nhẫn; khắc nghiệt; thiếu tử tế"]'::jsonb, 0, 'valley: thung lũng; thung lũng sông. Dịch cả câu: Các cộng đồng làm nông nghiệp trong thung lũng phụ thuộc vào lượng mưa theo mùa để duy trì mùa màng và bảo đảm sinh kế địa phương.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_21', 'en-b1-15', NULL, 'comprehensive_test', 'reading', NULL, 'Underwater noise from shipping can disrupt dolphin communication and make it harder for these animals to find food.', 'Dựa vào câu trên, từ “dolphin” có nghĩa phù hợp nhất là gì?', '["con cá heo","bạn bè; bạn đồng hành","xe buýt nhỏ; xe khách nhỏ","nhắc nhở; làm cho nhớ"]'::jsonb, 0, 'dolphin: con cá heo. Dịch cả câu: Tiếng ồn dưới nước do tàu bè gây ra có thể làm gián đoạn sự giao tiếp của cá heo và khiến cho loài động vật này khó kiếm thức ăn hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_22', 'en-b1-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngô; bắp”', '["corn","reservation","chapter","worldwide"]'::jsonb, 0, 'ngô; bắp → corn (/kɔːrn/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_23', 'en-b1-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lúa mì; mỳ”', '["sail","cheque/check","wheat","property"]'::jsonb, 2, 'lúa mì; mỳ → wheat (/wiːt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_15_24', 'en-b1-15', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bóng râm; bóng mát”', '["element","shade","physical","cathedral"]'::jsonb, 1, 'bóng râm; bóng mát → shade (/ʃeɪd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-16', 'en', 'Bài 16: Thiên nhiên & Thời tiết (3) - CEFR B1', 'CEFR B1', 'B1 · Thiên nhiên', '24 từ vựng Tiếng Anh CEFR B1 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3016, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tortoise', 'en-b1-16', 'tortoise', '/ˈtɔːrtəs/', 'B1', 'con rùa cạn', 'n.', NULL, NULL, 'thường chỉ rùa cạn; trong tiếng Anh-Anh turtle thường chỉ rùa biển.', 'The tortoise slowly stretched its neck towards a lettuce leaf.', NULL, 'Con rùa cạn từ từ vươn cổ về phía một chiếc lá xà lách.', '{"wordId":"tortoise","ukIpa":"/ˈtɔːtəs/","usIpa":"/ˈtɔːrtəs/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A land reptile with a hard shell and short legs.","vi":"con rùa cạn"}],"examples":[{"en":"The tortoise slowly stretched its neck towards a lettuce leaf.","vi":"Con rùa cạn từ từ vươn cổ về phía một chiếc lá xà lách.","audioKind":"ex"},{"en":"Protecting natural habitats is essential for tortoise populations threatened by illegal trade and agricultural expansion.","vi":"Bảo vệ môi trường sống tự nhiên là điều cần thiết đối với các quần thể rùa cạn đang bị đe dọa bởi nạn buôn bán bất hợp pháp và sự mở rộng nông nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"giant tortoise","vi":"rùa cạn khổng lồ"},{"en":"tortoise shell","vi":"mai rùa cạn"},{"en":"pet tortoise","vi":"rùa cạn cảnh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"thường chỉ rùa cạn; trong tiếng Anh-Anh turtle thường chỉ rùa biển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cage', 'en-b1-16', 'cage', '/keɪdʒ/', 'B1', 'lồng; chuồng; nhốt vào lồng', 'n.', 'caged (adj.)', NULL, 'in a cage có nghĩa là ở trong lồng; caged birds dùng để chỉ chim nuôi trong lồng.', 'The rabbit''s cage has fresh hay and clean water.', NULL, 'Chiếc lồng của chú thỏ có cỏ khô tươi và nước sạch.', '{"wordId":"cage","ukIpa":"/keɪdʒ/","usIpa":"/keɪdʒ/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a container with bars or wire for keeping animals inside","vi":"lồng; chuồng"},{"pos":"v.","en":"to put or keep an animal in a cage","vi":"nhốt vào lồng"}],"examples":[{"en":"The rabbit''s cage has fresh hay and clean water.","vi":"Chiếc lồng của chú thỏ có cỏ khô tươi và nước sạch.","audioKind":"ex"},{"en":"Animal welfare groups argue that small cages prevent birds from flying freely and expressing natural behaviour.","vi":"Các nhóm bảo vệ động vật cho rằng những chiếc lồng nhỏ khiến loài chim không thể tự do bay lượn và thể hiện bản năng tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"bird cage","vi":"lồng chim"},{"en":"wire cage","vi":"lồng sắt"},{"en":"keep in a cage","vi":"nhốt trong lồng"}],"wordFamily":["caged (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"in a cage có nghĩa là ở trong lồng; caged birds dùng để chỉ chim nuôi trong lồng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hunt', 'en-b1-16', 'hunt', '/hʌnt/', 'B1', 'săn bắn; lùng sục; tìm kiếm; cuộc săn bắt; cuộc tìm kiếm', 'v.', 'hunter (n.), hunting (n.)', NULL, 'Săn bắt động vật có thể đi thẳng với tân ngữ; tìm kiếm đồ vật thường dùng hunt for.', 'We hunted for my keys under the sofa.', NULL, 'Chúng tôi đã tìm kiếm chiếc chìa khóa của tôi dưới ghế sofa.', '{"wordId":"hunt","ukIpa":"/hʌnt/","usIpa":"/hʌnt/","cefr":"B1","topic":"nature","senses":[{"pos":"v.","en":"to chase wild animals to catch or kill them","vi":"săn bắn"},{"pos":"v.","en":"to search carefully for someone or something","vi":"lùng sục; tìm kiếm"},{"pos":"n.","en":"an organised search or an activity involving chasing wild animals","vi":"cuộc săn bắt; cuộc tìm kiếm"}],"examples":[{"en":"We hunted for my keys under the sofa.","vi":"Chúng tôi đã tìm kiếm chiếc chìa khóa của tôi dưới ghế sofa.","audioKind":"ex"},{"en":"When natural habitats shrink, predators may hunt closer to farms, increasing conflict between wildlife and local communities.","vi":"Khi môi trường sống tự nhiên thu hẹp, động vật săn mồi có thể tiến gần các khu trang trại hơn để kiếm mồi, làm gia tăng xung đột giữa động vật hoang dã và cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"hunt for food","vi":"đi kiếm ăn"},{"en":"hunt for a job","vi":"tìm kiếm việc làm"},{"en":"a treasure hunt","vi":"chương trình tìm kho báu"},{"en":"hunt wild animals","vi":"săn bắt động vật hoang dã"}],"wordFamily":["hunter (n.)","hunting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Săn bắt động vật có thể đi thẳng với tân ngữ; tìm kiếm đồ vật thường dùng hunt for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_survive', 'en-b1-16', 'survive', '/sɚˈvaɪv/', 'B1', 'sống sót; tồn tại; tiếp tục tồn tại; vượt qua; sống lâu hơn', 'v.', 'survival (n.), survivor (n.)', 'Trái nghĩa: perish', 'Để diễn tả ý nghĩa sống sót sau một tai nạn, bạn có thể dùng trực tiếp survive an accident.', 'Our little cactus survived three weeks without water.', NULL, 'Cây xương rồng nhỏ của chúng tôi đã sống sót suốt ba tuần không có nước.', '{"wordId":"survive","ukIpa":"/səˈvaɪv/","usIpa":"/sɚˈvaɪv/","cefr":"B1","topic":"nature","senses":[{"pos":"v.","en":"stay alive despite danger, illness, or hardship","vi":"sống sót; tồn tại"},{"pos":"v.","en":"continue to exist after difficulties or changes","vi":"tiếp tục tồn tại; vượt qua"},{"pos":"v.","en":"live longer than another person","vi":"sống lâu hơn"}],"examples":[{"en":"Our little cactus survived three weeks without water.","vi":"Cây xương rồng nhỏ của chúng tôi đã sống sót suốt ba tuần không có nước.","audioKind":"ex"},{"en":"Small businesses are more likely to survive economic downturns when they maintain strong relationships with local customers.","vi":"Các doanh nghiệp nhỏ có nhiều khả năng vượt qua được thời kỳ kinh tế suy thoái hơn khi họ duy trì mối quan hệ bền chặt với khách hàng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"survive an accident","vi":"sống sót sau một vụ tai nạn"},{"en":"survive on","vi":"sống bằng; xoay sở sống qua"},{"en":"survive a crisis","vi":"vượt qua một cuộc khủng hoảng"}],"wordFamily":["survival (n.)","survivor (n.)"],"synonyms":[],"antonyms":["perish"],"tipVi":"Để diễn tả ý nghĩa sống sót sau một tai nạn, bạn có thể dùng trực tiếp survive an accident.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lizard', 'en-b1-16', 'lizard', '/ˈlɪzərd/', 'B1', 'thằn lằn; kỳ nhông', 'n.', NULL, NULL, 'Lizard là một danh từ đếm được, dạng số nhiều là lizards.', 'A tiny lizard rested on the warm garden wall.', NULL, 'Một con thằn lằn nhỏ đang đậu trên bức tường vườn ấm áp.', '{"wordId":"lizard","ukIpa":"/ˈlɪzəd/","usIpa":"/ˈlɪzərd/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a reptile with a long tail, usually with four legs","vi":"thằn lằn; kỳ nhông"}],"examples":[{"en":"A tiny lizard rested on the warm garden wall.","vi":"Một con thằn lằn nhỏ đang đậu trên bức tường vườn ấm áp.","audioKind":"ex"},{"en":"Protecting rocky habitats helps preserve lizard populations, which play an important role in controlling insects.","vi":"Việc bảo vệ môi trường sống nhiều đá giúp duy trì các quần thể thằn lằn, loài đóng vai trò quan trọng trong việc kiểm soát côn trùng.","audioKind":"ex2"}],"collocations":[{"en":"small lizard","vi":"thằn lằn nhỏ"},{"en":"lizard species","vi":"loài thằn lằn"},{"en":"lizard habitat","vi":"môi trường sống của thằn lằn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Lizard là một danh từ đếm được, dạng số nhiều là lizards.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mushroom', 'en-b1-16', 'mushroom', '/ˈmʌʃruːm/', 'B1', 'nấm; phát triển nhanh; mọc lên như nấm', 'n.', NULL, NULL, 'Khi dùng làm động từ chỉ sự tăng trưởng nhanh, nó không đi với tân ngữ trực tiếp.', 'I added sliced mushrooms to the soup for lunch.', NULL, 'Tôi đã cho thêm nấm thái lát vào món súp cho bữa trưa.', '{"wordId":"mushroom","ukIpa":"/ˈmʌʃruːm/","usIpa":"/ˈmʌʃruːm/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A fungus often shaped like an umbrella; some are edible.","vi":"nấm"},{"pos":"v.","en":"Grow or increase very quickly.","vi":"phát triển nhanh; mọc lên như nấm"}],"examples":[{"en":"I added sliced mushrooms to the soup for lunch.","vi":"Tôi đã cho thêm nấm thái lát vào món súp cho bữa trưa.","audioKind":"ex"},{"en":"Online learning platforms have mushroomed as demand for flexible and affordable education has increased worldwide.","vi":"Các nền tảng học trực tuyến đã phát triển nhanh chóng khi nhu cầu về giáo dục linh hoạt và giá cả phải chăng tăng lên trên toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"mushroom soup","vi":"súp nấm"},{"en":"wild mushrooms","vi":"nấm hoang dã"},{"en":"mushroom into a large business","vi":"phát triển thành một doanh nghiệp lớn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng làm động từ chỉ sự tăng trưởng nhanh, nó không đi với tân ngữ trực tiếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seed', 'en-b1-16', 'seed', '/siːd/', 'B1', 'hạt giống; gieo hạt; gieo trồng', 'n.', 'seedling (n.), seedless (adj.), seedy (adj.)', NULL, 'sow seeds chỉ hành động gieo hạt; seedling chỉ cây con đã mọc mầm.', 'She planted each seed in a small clay pot.', NULL, 'Cô ấy gieo từng hạt giống vào một chiếc chậu đất nung nhỏ.', '{"wordId":"seed","ukIpa":"/siːd/","usIpa":"/siːd/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A small part of a plant that can grow into another.","vi":"hạt giống"},{"pos":"v.","en":"Put seeds into soil so that plants will grow.","vi":"gieo hạt; gieo trồng"}],"examples":[{"en":"She planted each seed in a small clay pot.","vi":"Cô ấy gieo từng hạt giống vào một chiếc chậu đất nung nhỏ.","audioKind":"ex"},{"en":"Protecting seed diversity helps farmers adapt to changing climates and reduces the risk of widespread crop failure.","vi":"Bảo vệ sự đa dạng của hạt giống giúp nông dân thích ứng với khí hậu biến đổi và giảm nguy cơ mất mùa diện rộng.","audioKind":"ex2"}],"collocations":[{"en":"sow seeds","vi":"gieo hạt"},{"en":"plant a seed","vi":"gieo mầm"},{"en":"sunflower seeds","vi":"hạt hướng dương"},{"en":"seed bank","vi":"ngân hàng hạt giống"}],"wordFamily":["seedling (n.)","seedless (adj.)","seedy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"sow seeds chỉ hành động gieo hạt; seedling chỉ cây con đã mọc mầm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_creature', 'en-b1-16', 'creature', '/ˈkriːtʃɚ/', 'B1', 'sinh vật; loài vật; sinh vật huyền thoại; quái vật', 'n.', NULL, 'Đồng nghĩa: animal, being', 'creature thường chỉ động vật, nhưng cũng có thể chỉ các sinh vật trong tưởng tượng.', 'A tiny creature crawled out from under the leaf.', NULL, 'Một sinh vật nhỏ bé bò ra từ dưới chiếc lá.', '{"wordId":"creature","ukIpa":"/ˈkriːtʃə/","usIpa":"/ˈkriːtʃɚ/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a living being, especially an animal","vi":"sinh vật; loài vật"},{"pos":"n.","en":"an imaginary being with unusual physical features","vi":"sinh vật huyền thoại; quái vật"}],"examples":[{"en":"A tiny creature crawled out from under the leaf.","vi":"Một sinh vật nhỏ bé bò ra từ dưới chiếc lá.","audioKind":"ex"},{"en":"Even the smallest marine creature can play an important role in maintaining a healthy ocean ecosystem.","vi":"Ngay cả sinh vật biển nhỏ bé nhất cũng có thể đóng vai trò quan trọng trong việc duy trì hệ sinh thái đại dương khỏe mạnh.","audioKind":"ex2"}],"collocations":[{"en":"a sea creature","vi":"sinh vật biển"},{"en":"a living creature","vi":"sinh vật sống"},{"en":"a mythical creature","vi":"sinh vật thần thoại"}],"wordFamily":[],"synonyms":["animal","being"],"antonyms":[],"tipVi":"creature thường chỉ động vật, nhưng cũng có thể chỉ các sinh vật trong tưởng tượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_straw', 'en-b1-16', 'straw', '/strɔː/', 'B1', 'rơm; rạ; cỏ khô; ống hút', 'n.', NULL, NULL, 'Dùng chỉ rơm là không đếm được, chỉ ống hút là đếm được; hay chỉ cỏ khô dùng làm thức ăn gia súc.', 'The farmer spread fresh straw across the barn floor.', NULL, 'Người nông dân rải rơm tươi khắp sàn chuồng.', '{"wordId":"straw","ukIpa":"/strɔː/","usIpa":"/strɔː/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"Dried cereal stems used for animal bedding and other purposes.","vi":"rơm; rạ; cỏ khô"},{"pos":"n.","en":"A narrow tube used for drinking liquids.","vi":"ống hút"}],"examples":[{"en":"The farmer spread fresh straw across the barn floor.","vi":"Người nông dân rải rơm tươi khắp sàn chuồng.","audioKind":"ex"},{"en":"Replacing plastic straws with reusable alternatives can reduce waste, although wider changes in consumption remain necessary.","vi":"Việc thay thế ống hút nhựa bằng các giải pháp thay thế có thể tái sử dụng giúp giảm thiểu rác thải, dù những thay đổi sâu rộng hơn trong tiêu dùng vẫn là điều cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"a bale of straw","vi":"một cuộn rơm"},{"en":"a straw hat","vi":"một chiếc mũ rơm"},{"en":"a drinking straw","vi":"một chiếc ống hút"},{"en":"the last straw","vi":"giọt nước tràn ly"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng chỉ rơm là không đếm được, chỉ ống hút là đếm được; hay chỉ cỏ khô dùng làm thức ăn gia súc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bat', 'en-b1-16', 'bat', '/bæt/', 'B1', 'con dơi (thú bay hoạt động chủ yếu về đêm); cây gậy (dùng để đánh bóng trong một số môn thể thao); đánh bóng hoặc cố gắng đánh bóng bằng gậy', 'n.', 'batter (n.), batting (n.)', NULL, 'Vợt tennis dùng racket, gậy bóng chày và gậy khúc côn cầu dùng bat.', 'A bat flew above our garden at dusk.', NULL, 'Một con dơi bay qua khu vườn của chúng tôi vào lúc chạng vạng.', '{"wordId":"bat","ukIpa":"/bæt/","usIpa":"/bæt/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A flying mammal usually active at night.","vi":"con dơi (thú bay hoạt động chủ yếu về đêm)"},{"pos":"n.","en":"An object used to hit the ball in certain sports.","vi":"cây gậy (dùng để đánh bóng trong một số môn thể thao)"},{"pos":"v.","en":"To hit or try to hit a ball with a bat.","vi":"đánh bóng hoặc cố gắng đánh bóng bằng gậy"}],"examples":[{"en":"A bat flew above our garden at dusk.","vi":"Một con dơi bay qua khu vườn của chúng tôi vào lúc chạng vạng.","audioKind":"ex"},{"en":"Protecting bat habitats can benefit agriculture because many species feed on insects that damage crops.","vi":"Việc bảo vệ môi trường sống của loài dơi có thể mang lại lợi ích cho nông nghiệp vì nhiều loài ăn côn trùng gây hại cho mùa màng.","audioKind":"ex2"}],"collocations":[{"en":"a cricket bat","vi":"gậy đánh bản cầu"},{"en":"a baseball bat","vi":"gậy bóng chày"},{"en":"bat wings","vi":"cánh dơi"}],"wordFamily":["batter (n.)","batting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Vợt tennis dùng racket, gậy bóng chày và gậy khúc côn cầu dùng bat.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cave', 'en-b1-16', 'cave', '/keɪv/', 'B1', 'hang động; động', 'n.', NULL, 'Đồng nghĩa: cavern', 'cave chỉ hang động; cụm động từ cave in có nghĩa là sụt lở hoặc đầu hàng, khuất phục.', 'We sheltered from the rain inside a small cave.', NULL, 'Chúng tôi đã trú mưa bên trong một hang động nhỏ.', '{"wordId":"cave","ukIpa":"/keɪv/","usIpa":"/keɪv/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A large natural hollow inside rock or under the ground.","vi":"hang động; động"}],"examples":[{"en":"We sheltered from the rain inside a small cave.","vi":"Chúng tôi đã trú mưa bên trong một hang động nhỏ.","audioKind":"ex"},{"en":"Ancient paintings found in a cave can reveal how early communities understood their surroundings.","vi":"Những bức bích họa cổ được tìm thấy trong hang động có thể tiết lộ cách các cộng đồng thời sơ khai nhận thức về môi trường xung quanh họ.","audioKind":"ex2"}],"collocations":[{"en":"explore a cave","vi":"thám hiểm hang động"},{"en":"cave entrance","vi":"lối vào hang"},{"en":"cave paintings","vi":"bích họa trong hang động"}],"wordFamily":[],"synonyms":["cavern"],"antonyms":[],"tipVi":"cave chỉ hang động; cụm động từ cave in có nghĩa là sụt lở hoặc đầu hàng, khuất phục.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mosquito', 'en-b1-16', 'mosquito', '/məˈskiːtoʊ/', 'B1', 'muỗi', 'n.', NULL, NULL, 'Dạng số nhiều có thể viết là mosquitoes hoặc mosquitos.', 'A mosquito landed on my arm during dinner.', NULL, 'Một con muỗi đậu lên tay tôi trong bữa tối.', '{"wordId":"mosquito","ukIpa":"/məˈskiːtəʊ/","usIpa":"/məˈskiːtoʊ/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A small flying insect whose females bite and suck blood.","vi":"muỗi"}],"examples":[{"en":"A mosquito landed on my arm during dinner.","vi":"Một con muỗi đậu lên tay tôi trong bữa tối.","audioKind":"ex"},{"en":"Warmer temperatures may allow mosquito populations to spread into regions where they were previously uncommon.","vi":"Nhiệt độ ấm hơn có thể tạo điều kiện cho quần thể muỗi lan rộng đến những vùng trước đây ít khi xuất hiện loài này.","audioKind":"ex2"}],"collocations":[{"en":"mosquito bite","vi":"muỗi đốt"},{"en":"mosquito net","vi":"mùng ngủ; màn"},{"en":"mosquito repellent","vi":"thuốc chống muỗi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều có thể viết là mosquitoes hoặc mosquitos.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stormy', 'en-b1-16', 'stormy', '/ˈstɔːrmi/', 'B1', 'có bão; giông bão; dữ dội; đầy bất đồng; sóng gió', 'adj.', 'storm (n.)', 'Đồng nghĩa: tempestuous · Trái nghĩa: calm', 'Tính từ này vừa có thể dùng để mô tả thời tiết bão gió, vừa dùng để chỉ các mối quan hệ hoặc cuộc tranh luận đầy căng thẳng, xung đột.', 'We stayed indoors because the weather was so stormy.', NULL, 'Chúng tôi ở trong nhà vì thời tiết bên ngoài quá giông bão.', '{"wordId":"stormy","ukIpa":"/ˈstɔːmi/","usIpa":"/ˈstɔːrmi/","cefr":"B1","topic":"nature","senses":[{"pos":"adj.","en":"Having strong winds and often heavy rain, thunder, or lightning.","vi":"có bão; giông bão"},{"pos":"adj.","en":"Involving strong emotions, arguments, or disagreement.","vi":"dữ dội; đầy bất đồng; sóng gió"}],"examples":[{"en":"We stayed indoors because the weather was so stormy.","vi":"Chúng tôi ở trong nhà vì thời tiết bên ngoài quá giông bão.","audioKind":"ex"},{"en":"Increasingly stormy conditions may disrupt shipping routes and threaten the livelihoods of people in coastal communities.","vi":"Điều kiện thời tiết ngày càng khắc nghiệt có thể làm gián đoạn các tuyến đường hàng hải và đe dọa sinh kế của người dân các cộng đồng ven biển.","audioKind":"ex2"}],"collocations":[{"en":"stormy weather","vi":"thời tiết giông bão"},{"en":"stormy seas","vi":"biển động dữ dội"},{"en":"a stormy relationship","vi":"mối quan hệ sóng gió"},{"en":"a stormy debate","vi":"một cuộc tranh luận nảy lửa"}],"wordFamily":["storm (n.)"],"synonyms":["tempestuous"],"antonyms":["calm"],"tipVi":"Tính từ này vừa có thể dùng để mô tả thời tiết bão gió, vừa dùng để chỉ các mối quan hệ hoặc cuộc tranh luận đầy căng thẳng, xung đột.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wolf', 'en-b1-16', 'wolf', '/wʊlf/', 'B1', 'con sói; ngấu nghiến; ăn lấy ăn để', 'n.', NULL, NULL, 'Dạng số nhiều của wolf là wolves; động từ thường đi với giới từ down thành wolf down để chỉ hành động ăn rất nhanh.', 'A grey wolf stood silently at the forest edge.', NULL, 'Một con sói xám lặng lẽ đứng ở rìa rừng.', '{"wordId":"wolf","ukIpa":"/wʊlf/","usIpa":"/wʊlf/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a wild animal related to dogs, often living in packs","vi":"con sói"},{"pos":"v.","en":"to eat food very quickly and eagerly","vi":"ngấu nghiến; ăn lấy ăn để"}],"examples":[{"en":"A grey wolf stood silently at the forest edge.","vi":"Một con sói xám lặng lẽ đứng ở rìa rừng.","audioKind":"ex"},{"en":"Protecting wolf populations can help restore ecological balance by controlling the numbers of deer in forest habitats.","vi":"Bảo vệ các quần thể sói có thể giúp khôi phục cân bằng sinh thái bằng cách kiểm soát số lượng loài hươu trong môi trường sống rừng.","audioKind":"ex2"}],"collocations":[{"en":"a pack of wolves","vi":"một bầy sói"},{"en":"a lone wolf","vi":"kẻ cô độc; người sống đơn độc"},{"en":"wolf down a meal","vi":"ngấu nghiến một bữa ăn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều của wolf là wolves; động từ thường đi với giới từ down thành wolf down để chỉ hành động ăn rất nhanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_antarctic', 'en-b1-16', 'Antarctic', '/ænˈtɑːrktɪk/', 'B1', 'thuộc vùng Nam Cực; vùng Nam Cực', 'adj.', 'Antarctica (n.)', NULL, 'Danh từ dùng the Antarctic; Antarctica dùng riêng cho châu Nam Cực.', 'We watched a film about penguins on Antarctic ice.', NULL, 'Chúng tôi đã xem một bộ phim về những chú chim cánh cụt trên băng Nam Cực.', '{"wordId":"antarctic","ukIpa":"/ænˈtɑːktɪk/","usIpa":"/ænˈtɑːrktɪk/","cefr":"B1","topic":"nature","senses":[{"pos":"adj.","en":"Relating to the region around the South Pole.","vi":"thuộc vùng Nam Cực"},{"pos":"n.","en":"The region surrounding the South Pole, including Antarctica.","vi":"vùng Nam Cực"}],"examples":[{"en":"We watched a film about penguins on Antarctic ice.","vi":"Chúng tôi đã xem một bộ phim về những chú chim cánh cụt trên băng Nam Cực.","audioKind":"ex"},{"en":"Scientists monitor Antarctic ice to understand how rising global temperatures affect sea levels worldwide.","vi":"Các nhà khoa học theo dõi lớp băng Nam Cực để hiểu nhiệt độ toàn cầu tăng lên ảnh hưởng thế nào đến mực nước biển trên toàn thế giới.","audioKind":"ex2"}],"collocations":[{"en":"Antarctic ice","vi":"băng Nam Cực"},{"en":"the Antarctic","vi":"vùng Nam Cực"},{"en":"Antarctic wildlife","vi":"động vật hoang dã Nam Cực"}],"wordFamily":["Antarctica (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ dùng the Antarctic; Antarctica dùng riêng cho châu Nam Cực.","noteVi":"Chữ cái đầu tiên đã được đổi thành chữ hoa chuẩn: Antarctic.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_region', 'en-b1-16', 'region', '/ˈriːdʒən/', 'B1', 'vùng; khu vực; vùng cơ thể', 'n.', 'regional (adj.), regionally (adv.)', 'Đồng nghĩa: area, zone', 'in the region of đi với số tiền hoặc con số, dùng để chỉ sự "khoảng chừng".', 'This region is famous for its apples and cheese.', NULL, 'Vùng này nổi tiếng với táo và phô mai của họ.', '{"wordId":"region","ukIpa":"/ˈriːdʒən/","usIpa":"/ˈriːdʒən/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"an area of a country or the world","vi":"vùng; khu vực"},{"pos":"n.","en":"a particular area of the body","vi":"vùng cơ thể"}],"examples":[{"en":"This region is famous for its apples and cheese.","vi":"Vùng này nổi tiếng với táo và phô mai của họ.","audioKind":"ex"},{"en":"Improved transport links could attract more businesses to the region and create jobs for local residents.","vi":"Việc cải thiện các kết nối giao thông có thể thu hút nhiều doanh nghiệp hơn đến khu vực này và tạo ra việc làm cho cư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"coastal region","vi":"vùng ven biển"},{"en":"rural region","vi":"vùng nông thôn"},{"en":"in the region of","vi":"khoảng chừng"}],"wordFamily":["regional (adj.)","regionally (adv.)"],"synonyms":["area","zone"],"antonyms":[],"tipVi":"in the region of đi với số tiền hoặc con số, dùng để chỉ sự \"khoảng chừng\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lamb', 'en-b1-16', 'lamb', '/læm/', 'B1', 'cừu con; cừu non; thịt cừu non', 'n.', 'lambing (n.)', NULL, 'Chữ b cuối từ không phát âm; chỉ cừu non là danh từ đếm được, chỉ thịt cừu là không đếm được.', 'A small lamb followed its mother across the field.', NULL, 'Một chú cừu con đi theo mẹ băng qua cánh đồng.', '{"wordId":"lamb","ukIpa":"/læm/","usIpa":"/læm/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a young sheep","vi":"cừu con; cừu non"},{"pos":"n.","en":"meat from a young sheep, eaten as food","vi":"thịt cừu non"}],"examples":[{"en":"A small lamb followed its mother across the field.","vi":"Một chú cừu con đi theo mẹ băng qua cánh đồng.","audioKind":"ex"},{"en":"Producing lamb requires land and water, so its environmental impact should be considered when planning sustainable diets.","vi":"Việc sản xuất thịt cừu tốn nhiều đất và nước, vì vậy tác động môi trường của nó cần được cân nhắc khi lập kế hoạch cho chế độ ăn uống bền vững.","audioKind":"ex2"}],"collocations":[{"en":"newborn lamb","vi":"cừu con mới sinh"},{"en":"roast lamb","vi":"thịt cừu nướng"},{"en":"lamb chops","vi":"sườn cừu"}],"wordFamily":["lambing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ b cuối từ không phát âm; chỉ cừu non là danh từ đếm được, chỉ thịt cừu là không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ripe', 'en-b1-16', 'ripe', '/raɪp/', 'B1', 'chín; đã trưởng thành để ăn hoặc thu hoạch; chín muồi; thích hợp (cho một hành động hoặc sự phát triển)', 'adj.', 'ripen (v.), ripeness (n.), unripe (adj.)', 'Trái nghĩa: unripe', 'Dùng ripe cho quả chín; mature thường dùng cho sự trưởng thành về tâm trí.', 'These ripe peaches smell wonderful and taste very sweet.', NULL, 'Những quả đào chín này thơm lừng và có vị rất ngọt.', '{"wordId":"ripe","ukIpa":"/raɪp/","usIpa":"/raɪp/","cefr":"B1","topic":"nature","senses":[{"pos":"adj.","en":"Fully grown and ready to eat or harvest","vi":"chín; đã trưởng thành để ăn hoặc thu hoạch"},{"pos":"adj.","en":"Ready for a particular action or development","vi":"chín muồi; thích hợp (cho một hành động hoặc sự phát triển)"}],"examples":[{"en":"These ripe peaches smell wonderful and taste very sweet.","vi":"Những quả đào chín này thơm lừng và có vị rất ngọt.","audioKind":"ex"},{"en":"With public support growing, the time is ripe for governments to invest more in renewable energy.","vi":"Khi sự ủng hộ của công chúng ngày càng tăng, thời điểm đã chín muồi để các chính phủ đầu tư nhiều hơn vào năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"ripe fruit","vi":"trái cây chín"},{"en":"fully ripe","vi":"chín hoàn toàn"},{"en":"ripe for change","vi":"chín muồi cho sự thay đổi"},{"en":"the time is ripe","vi":"thời cơ đã chín muồi"}],"wordFamily":["ripen (v.)","ripeness (n.)","unripe (adj.)"],"synonyms":[],"antonyms":["unripe"],"tipVi":"Dùng ripe cho quả chín; mature thường dùng cho sự trưởng thành về tâm trí.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tuna', 'en-b1-16', 'tuna', '/ˈtuːnə/', 'B1', 'cá ngừ; thịt cá ngừ', 'n.', NULL, NULL, 'Khi chỉ thịt cá thì không đếm được; khi chỉ con cá thì dạng số nhiều thường vẫn giữ nguyên là tuna.', 'I made a tuna sandwich for lunch today.', NULL, 'Hôm nay tôi làm bánh mì kẹp cá ngừ cho bữa trưa.', '{"wordId":"tuna","ukIpa":"/ˈtjuːnə/","usIpa":"/ˈtuːnə/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a large sea fish, or its flesh eaten as food","vi":"cá ngừ; thịt cá ngừ"}],"examples":[{"en":"I made a tuna sandwich for lunch today.","vi":"Hôm nay tôi làm bánh mì kẹp cá ngừ cho bữa trưa.","audioKind":"ex"},{"en":"International cooperation is essential to prevent overfishing and ensure that tuna populations remain healthy for future generations.","vi":"Hợp tác quốc tế là điều cốt yếu để ngăn chặn tình trạng đánh bắt quá mức và đảm bảo nguồn lợi cá ngừ luôn dồi dào cho các thế hệ mai sau.","audioKind":"ex2"}],"collocations":[{"en":"tuna sandwich","vi":"bánh mì kẹp cá ngừ"},{"en":"canned tuna","vi":"cá ngừ đóng hộp"},{"en":"bluefin tuna","vi":"cá ngừ vây xanh"},{"en":"tuna stocks","vi":"nguồn dự trữ cá ngừ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ thịt cá thì không đếm được; khi chỉ con cá thì dạng số nhiều thường vẫn giữ nguyên là tuna.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thunder', 'en-b1-16', 'thunder', '/ˈθʌndər/', 'B1', 'tiếng sấm; tiếng sét; đánh sấm; vang rền', 'n.', 'thunderous (adj.), thunderstorm (n.)', NULL, 'thunder chỉ tiếng sấm và thường là danh từ không đếm được; lightning chỉ tia chớp.', 'A sudden clap of thunder made the windows shake.', NULL, 'Một tiếng sấm bất ngờ làm rung chuyển cả khung cửa sổ.', '{"wordId":"thunder","ukIpa":"/ˈθʌndə/","usIpa":"/ˈθʌndər/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"The loud sound in the sky caused by lightning","vi":"tiếng sấm; tiếng sét"},{"pos":"v.","en":"Produce thunder or make a similarly loud, deep noise","vi":"đánh sấm; vang rền"}],"examples":[{"en":"A sudden clap of thunder made the windows shake.","vi":"Một tiếng sấm bất ngờ làm rung chuyển cả khung cửa sổ.","audioKind":"ex"},{"en":"Outdoor sports events should be suspended when thunder indicates that a storm is dangerously close.","vi":"Các sự kiện thể thao ngoài trời nên được tạm dừng khi tiếng sấm báo hiệu một cơn bão đang tiến đến gần ở khoảng cách nguy hiểm.","audioKind":"ex2"}],"collocations":[{"en":"a clap of thunder","vi":"một tiếng sấm nổ"},{"en":"a rumble of thunder","vi":"tiếng sấm rền trầm đục"},{"en":"thunder and lightning","vi":"sấm chớp"}],"wordFamily":["thunderous (adj.)","thunderstorm (n.)"],"synonyms":[],"antonyms":[],"tipVi":"thunder chỉ tiếng sấm và thường là danh từ không đếm được; lightning chỉ tia chớp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wing', 'en-b1-16', 'wing', '/wɪŋ/', 'B1', 'cánh (chim, máy bay); nhà phụ; khu nhà phụ; phe phái; cánh (trong tổ chức)', 'n.', 'winged (adj.)', NULL, 'Cả cánh chim lẫn cánh máy bay đều dùng "wing", và thường được dùng ở dạng số nhiều khi đi thành cặp.', 'The bird stretched its wings before leaving the branch.', NULL, 'Con chim vươn đôi cánh trước khi rời khỏi cành cây.', '{"wordId":"wing","ukIpa":"/wɪŋ/","usIpa":"/wɪŋ/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A body part or aircraft structure that enables flight.","vi":"cánh (chim, máy bay)"},{"pos":"n.","en":"A section extending from the main part of a building.","vi":"nhà phụ; khu nhà phụ"},{"pos":"n.","en":"A group within an organisation sharing particular views or aims.","vi":"phe phái; cánh (trong tổ chức)"}],"examples":[{"en":"The bird stretched its wings before leaving the branch.","vi":"Con chim vươn đôi cánh trước khi rời khỏi cành cây.","audioKind":"ex"},{"en":"The hospital''s new wing will provide additional beds and specialist facilities for the region''s growing population.","vi":"Khu nhà mới của bệnh viện sẽ cung cấp thêm giường bệnh và các trang thiết bị chuyên khoa cho dân số ngày càng tăng của khu vực.","audioKind":"ex2"}],"collocations":[{"en":"spread your wings","vi":"mở rộng đôi cánh; vươn xa"},{"en":"aircraft wing","vi":"cánh máy bay"},{"en":"hospital wing","vi":"dãy nhà bệnh viện"},{"en":"left wing","vi":"cánh tả"}],"wordFamily":["winged (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cả cánh chim lẫn cánh máy bay đều dùng \"wing\", và thường được dùng ở dạng số nhiều khi đi thành cặp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_horn', 'en-b1-16', 'horn', '/hɔːrn/', 'B1', 'sừng (trên đầu động vật); còi (xe cộ); kèn (nhạc cụ)', 'n.', 'horned (adj.), hornless (adj.)', NULL, 'Cả sừng động vật và còi xe đều dùng horn, đều là danh từ đếm được.', 'The goat caught its horn in the fence.', NULL, 'Con sơn dương bị vướng sừng vào hàng rào.', '{"wordId":"horn","ukIpa":"/hɔːn/","usIpa":"/hɔːrn/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A hard pointed growth on the head of some animals.","vi":"sừng (trên đầu động vật)"},{"pos":"n.","en":"A device on a vehicle that makes a loud warning sound.","vi":"còi (xe cộ)"},{"pos":"n.","en":"A musical instrument played by blowing into a tube.","vi":"kèn (nhạc cụ)"}],"examples":[{"en":"The goat caught its horn in the fence.","vi":"Con sơn dương bị vướng sừng vào hàng rào.","audioKind":"ex"},{"en":"Frequent use of car horns contributes to noise pollution and reduces residents'' quality of life.","vi":"Việc lạm dụng còi xe góp phần gây ô nhiễm tiếng ồn và làm giảm chất lượng cuộc sống của người dân.","audioKind":"ex2"}],"collocations":[{"en":"sound the horn","vi":"bóp còi; bấm còi"},{"en":"blow a horn","vi":"thổi kèn"},{"en":"a pair of horns","vi":"một cặp sừng"}],"wordFamily":["horned (adj.)","hornless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cả sừng động vật và còi xe đều dùng horn, đều là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wildlife', 'en-b1-16', 'wildlife', '/ˈwaɪldlaɪf/', 'B1', 'động vật hoang dã; sinh vật hoang dã', 'n.', NULL, NULL, 'Là danh từ không đếm được; wildlife đóng vai trò là danh từ bổ nghĩa trong wildlife park.', 'We watched the wildlife quietly from behind the trees.', NULL, 'Chúng tôi lặng lẽ quan sát động vật hoang dã từ phía sau những tán cây.', '{"wordId":"wildlife","ukIpa":"/ˈwaɪldlaɪf/","usIpa":"/ˈwaɪldlaɪf/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"Animals and other living things in their natural surroundings.","vi":"động vật hoang dã; sinh vật hoang dã"}],"examples":[{"en":"We watched the wildlife quietly from behind the trees.","vi":"Chúng tôi lặng lẽ quan sát động vật hoang dã từ phía sau những tán cây.","audioKind":"ex"},{"en":"Protecting wildlife requires governments to preserve natural habitats and limit development in environmentally sensitive areas.","vi":"Bảo vệ động vật hoang dã đòi hỏi các chính phủ phải gìn giữ các sinh cảnh tự nhiên và hạn chế phát triển ở những khu vực nhạy cảm về sinh thái.","audioKind":"ex2"}],"collocations":[{"en":"protect wildlife","vi":"bảo vệ động vật hoang dã"},{"en":"wildlife conservation","vi":"bảo tồn động vật hoang dã"},{"en":"a wildlife reserve","vi":"khu bảo tồn động vật hoang dã"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; wildlife đóng vai trò là danh từ bổ nghĩa trong wildlife park.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_naturally', 'en-b1-16', 'naturally', '/ˈnætʃərəli/', 'B1', 'một cách tự nhiên; theo tự nhiên; đương nhiên; tất nhiên; vốn dĩ; bẩm sinh', 'adv.', 'natural (adj.), nature (n.), unnatural (adj.)', 'Trái nghĩa: artificially', 'Từ đứng đầu câu Naturally thường mang nghĩa "đương nhiên", không nhất thiết chỉ tính chất tự nhiên.', 'Let your hair dry naturally after you wash it.', NULL, 'Hãy để tóc khô tự nhiên sau khi gội.', '{"wordId":"naturally","ukIpa":"/ˈnætʃərəli/","usIpa":"/ˈnætʃərəli/","cefr":"B1","topic":"nature","senses":[{"pos":"adv.","en":"Through natural processes rather than human action","vi":"một cách tự nhiên; theo tự nhiên"},{"pos":"adv.","en":"As would normally be expected","vi":"đương nhiên; tất nhiên"},{"pos":"adv.","en":"Because of qualities someone or something has from birth","vi":"vốn dĩ; bẩm sinh"}],"examples":[{"en":"Let your hair dry naturally after you wash it.","vi":"Hãy để tóc khô tự nhiên sau khi gội.","audioKind":"ex"},{"en":"Some pollutants occur naturally in the environment, but human activities can increase their concentration to harmful levels.","vi":"Một số chất gây ô nhiễm xuất hiện tự nhiên trong môi trường, nhưng các hoạt động của con người có thể làm tăng nồng độ của chúng lên mức có hại.","audioKind":"ex2"}],"collocations":[{"en":"occur naturally","vi":"xuất hiện tự nhiên"},{"en":"naturally curious","vi":"tò mò bẩm sinh"},{"en":"come naturally to someone","vi":"đến một cách tự nhiên với ai đó"},{"en":"dry naturally","vi":"khô tự nhiên"}],"wordFamily":["natural (adj.)","nature (n.)","unnatural (adj.)"],"synonyms":[],"antonyms":["artificially"],"tipVi":"Từ đứng đầu câu Naturally thường mang nghĩa \"đương nhiên\", không nhất thiết chỉ tính chất tự nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_16_1', 'en-b1-16', 'Cách dùng “stormy” (adj.) — có bão; giông bão', 'stormy weather  ·  stormy seas  ·  a stormy relationship', 'Tính từ này vừa có thể dùng để mô tả thời tiết bão gió, vừa dùng để chỉ các mối quan hệ hoặc cuộc tranh luận đầy căng thẳng, xung đột.', 'Họ từ (Word Family): storm (n.) | Đồng nghĩa: tempestuous · Trái nghĩa: calm', '[{"hanzi":"We stayed indoors because the weather was so stormy.","pinyin":"","meaning":"Chúng tôi ở trong nhà vì thời tiết bên ngoài quá giông bão."},{"hanzi":"Increasingly stormy conditions may disrupt shipping routes and threaten the livelihoods of people in coastal communities.","pinyin":"","meaning":"Điều kiện thời tiết ngày càng khắc nghiệt có thể làm gián đoạn các tuyến đường hàng hải và đe dọa sinh kế của người dân các cộng đồng ven biển."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_16_2', 'en-b1-16', 'Cách dùng “wolf” (n.) — con sói', 'a pack of wolves  ·  a lone wolf  ·  wolf down a meal', 'Dạng số nhiều của wolf là wolves; động từ thường đi với giới từ down thành wolf down để chỉ hành động ăn rất nhanh.', NULL, '[{"hanzi":"A grey wolf stood silently at the forest edge.","pinyin":"","meaning":"Một con sói xám lặng lẽ đứng ở rìa rừng."},{"hanzi":"Protecting wolf populations can help restore ecological balance by controlling the numbers of deer in forest habitats.","pinyin":"","meaning":"Bảo vệ các quần thể sói có thể giúp khôi phục cân bằng sinh thái bằng cách kiểm soát số lượng loài hươu trong môi trường sống rừng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_16_3', 'en-b1-16', 'Cách dùng “wing” (n.) — cánh (chim, máy bay)', 'spread your wings  ·  aircraft wing  ·  hospital wing', 'Cả cánh chim lẫn cánh máy bay đều dùng "wing", và thường được dùng ở dạng số nhiều khi đi thành cặp.', 'Họ từ (Word Family): winged (adj.)', '[{"hanzi":"The bird stretched its wings before leaving the branch.","pinyin":"","meaning":"Con chim vươn đôi cánh trước khi rời khỏi cành cây."},{"hanzi":"The hospital''s new wing will provide additional beds and specialist facilities for the region''s growing population.","pinyin":"","meaning":"Khu nhà mới của bệnh viện sẽ cung cấp thêm giường bệnh và các trang thiết bị chuyên khoa cho dân số ngày càng tăng của khu vực."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_16_4', 'en-b1-16', 'Cách dùng “tuna” (n.) — cá ngừ; thịt cá ngừ', 'tuna sandwich  ·  canned tuna  ·  bluefin tuna', 'Khi chỉ thịt cá thì không đếm được; khi chỉ con cá thì dạng số nhiều thường vẫn giữ nguyên là tuna.', NULL, '[{"hanzi":"I made a tuna sandwich for lunch today.","pinyin":"","meaning":"Hôm nay tôi làm bánh mì kẹp cá ngừ cho bữa trưa."},{"hanzi":"International cooperation is essential to prevent overfishing and ensure that tuna populations remain healthy for future generations.","pinyin":"","meaning":"Hợp tác quốc tế là điều cốt yếu để ngăn chặn tình trạng đánh bắt quá mức và đảm bảo nguồn lợi cá ngừ luôn dồi dào cho các thế hệ mai sau."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_16_1', 'en-b1-16', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_16_1_1', 'ten_b1_16_1', 'tortoise', 'The tortoise slowly stretched its neck towards a lettuce leaf.', 'The tortoise slowly stretched its neck towards a lettuce leaf.', '/ˈtɔːrtəs/', 'Con rùa cạn từ từ vươn cổ về phía một chiếc lá xà lách.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
