INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_16_1_3', 'ten_b1_16_1', 'hunt', 'We hunted for my keys under the sofa.', 'We hunted for my keys under the sofa.', '/hʌnt/', 'Chúng tôi đã tìm kiếm chiếc chìa khóa của tôi dưới ghế sofa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_16_1_4', 'ten_b1_16_1', 'survive', 'Our little cactus survived three weeks without water.', 'Our little cactus survived three weeks without water.', '/sɚˈvaɪv/', 'Cây xương rồng nhỏ của chúng tôi đã sống sót suốt ba tuần không có nước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
