INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_16_1_6', 'ten_b1_16_1', 'mushroom', 'I added sliced mushrooms to the soup for lunch.', 'I added sliced mushrooms to the soup for lunch.', '/ˈmʌʃruːm/', 'Tôi đã cho thêm nấm thái lát vào món súp cho bữa trưa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_16_1_7', 'ten_b1_16_1', 'seed', 'She planted each seed in a small clay pot.', 'She planted each seed in a small clay pot.', '/siːd/', 'Cô ấy gieo từng hạt giống vào một chiếc chậu đất nung nhỏ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_16_1_8', 'ten_b1_16_1', 'creature', 'A tiny creature crawled out from under the leaf.', 'A tiny creature crawled out from under the leaf.', '/ˈkriːtʃɚ/', 'Một sinh vật nhỏ bé bò ra từ dưới chiếc lá.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_16_1_1', 'en-b1-16', 'ten_b1_16_1', 'listening', 'listening', 'The tortoise slowly stretched its neck towards a lettuce leaf.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một con dơi bay qua khu vườn của chúng tôi vào lúc chạng vạng.","Con rùa cạn từ từ vươn cổ về phía một chiếc lá xà lách.","Cây xương rồng nhỏ của chúng tôi đã sống sót suốt ba tuần không có nước.","Một con muỗi đậu lên tay tôi trong bữa tối."]'::jsonb, 1, 'The tortoise slowly stretched its neck towards a lettuce leaf. → Con rùa cạn từ từ vươn cổ về phía một chiếc lá xà lách.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_16_1_2', 'en-b1-16', 'ten_b1_16_1', 'listening', 'listening', 'The rabbit''s cage has fresh hay and clean water.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi ở trong nhà vì thời tiết bên ngoài quá giông bão.","Chiếc lồng của chú thỏ có cỏ khô tươi và nước sạch.","Một tiếng sấm bất ngờ làm rung chuyển cả khung cửa sổ.","Một con sói xám lặng lẽ đứng ở rìa rừng."]'::jsonb, 1, 'The rabbit''s cage has fresh hay and clean water. → Chiếc lồng của chú thỏ có cỏ khô tươi và nước sạch.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_16_1_3', 'en-b1-16', 'ten_b1_16_1', 'listening', 'listening', 'We hunted for my keys under the sofa.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã trú mưa bên trong một hang động nhỏ.","Chúng tôi đã tìm kiếm chiếc chìa khóa của tôi dưới ghế sofa.","Một chú cừu con đi theo mẹ băng qua cánh đồng.","Hôm nay tôi làm bánh mì kẹp cá ngừ cho bữa trưa."]'::jsonb, 1, 'We hunted for my keys under the sofa. → Chúng tôi đã tìm kiếm chiếc chìa khóa của tôi dưới ghế sofa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_16_2', 'en-b1-16', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_16_2_1', 'ten_b1_16_2', 'tortoise', 'Protecting natural habitats is essential for tortoise populations threatened by illegal trade and agricultural expansion.', 'Protecting natural habitats is essential for tortoise populations threatened by illegal trade and agricultural expansion.', '/ˈtɔːrtəs/', 'Bảo vệ môi trường sống tự nhiên là điều cần thiết đối với các quần thể rùa cạn đang bị đe dọa bởi nạn buôn bán bất hợp pháp và sự mở rộng nông nghiệp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_16_2_2', 'ten_b1_16_2', 'cage', 'Animal welfare groups argue that small cages prevent birds from flying freely and expressing natural behaviour.', 'Animal welfare groups argue that small cages prevent birds from flying freely and expressing natural behaviour.', '/keɪdʒ/', 'Các nhóm bảo vệ động vật cho rằng những chiếc lồng nhỏ khiến loài chim không thể tự do bay lượn và thể hiện bản năng tự nhiên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_16_2_3', 'ten_b1_16_2', 'hunt', 'When natural habitats shrink, predators may hunt closer to farms, increasing conflict between wildlife and local communities.', 'When natural habitats shrink, predators may hunt closer to farms, increasing conflict between wildlife and local communities.', '/hʌnt/', 'Khi môi trường sống tự nhiên thu hẹp, động vật săn mồi có thể tiến gần các khu trang trại hơn để kiếm mồi, làm gia tăng xung đột giữa động vật hoang dã và cộng đồng địa phương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_16_2_4', 'ten_b1_16_2', 'survive', 'Small businesses are more likely to survive economic downturns when they maintain strong relationships with local customers.', 'Small businesses are more likely to survive economic downturns when they maintain strong relationships with local customers.', '/sɚˈvaɪv/', 'Các doanh nghiệp nhỏ có nhiều khả năng vượt qua được thời kỳ kinh tế suy thoái hơn khi họ duy trì mối quan hệ bền chặt với khách hàng địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_16_2_5', 'ten_b1_16_2', 'lizard', 'Protecting rocky habitats helps preserve lizard populations, which play an important role in controlling insects.', 'Protecting rocky habitats helps preserve lizard populations, which play an important role in controlling insects.', '/ˈlɪzərd/', 'Việc bảo vệ môi trường sống nhiều đá giúp duy trì các quần thể thằn lằn, loài đóng vai trò quan trọng trong việc kiểm soát côn trùng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_16_2_6', 'ten_b1_16_2', 'mushroom', 'Online learning platforms have mushroomed as demand for flexible and affordable education has increased worldwide.', 'Online learning platforms have mushroomed as demand for flexible and affordable education has increased worldwide.', '/ˈmʌʃruːm/', 'Các nền tảng học trực tuyến đã phát triển nhanh chóng khi nhu cầu về giáo dục linh hoạt và giá cả phải chăng tăng lên trên toàn cầu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_16_2_1', 'en-b1-16', 'ten_b1_16_2', 'listening', 'listening', 'Protecting natural habitats is essential for tortoise populations threatened by illegal trade and agricultural expansion.', NULL, 'Trong câu vừa nghe, từ “tortoise” mang nghĩa nào sau đây?', '["nộp đơn chính thức xin việc, vị trí hoặc xin phép","thị lực; thị giác","trò lướt ván nước","con rùa cạn"]'::jsonb, 3, '“tortoise” (/ˈtɔːrtəs/): con rùa cạn. Câu đầy đủ: Protecting natural habitats is essential for tortoise populations threatened by illegal trade and agricultural expansion.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_16_2_2', 'en-b1-16', 'ten_b1_16_2', 'listening', 'listening', 'Animal welfare groups argue that small cages prevent birds from flying freely and expressing natural behaviour.', NULL, 'Trong câu vừa nghe, từ “cage” mang nghĩa nào sau đây?', '["đau; nhức mỏi (nhất là khi chạm vào hoặc cử động)","lồng; chuồng","công tắc điện","giải pháp; cách giải quyết"]'::jsonb, 1, '“cage” (/keɪdʒ/): lồng; chuồng. Câu đầy đủ: Animal welfare groups argue that small cages prevent birds from flying freely and expressing natural behaviour.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
