INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_16_2', 'en-b1-16', NULL, 'comprehensive_test', 'listening', 'The rabbit''s cage has fresh hay and clean water.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc lồng của chú thỏ có cỏ khô tươi và nước sạch.","Chúng tôi lặng lẽ quan sát động vật hoang dã từ phía sau những tán cây.","Chúng tôi đã tìm kiếm chiếc chìa khóa của tôi dưới ghế sofa.","Vùng này nổi tiếng với táo và phô mai của họ."]'::jsonb, 0, 'The rabbit''s cage has fresh hay and clean water. → Chiếc lồng của chú thỏ có cỏ khô tươi và nước sạch.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_16_3', 'en-b1-16', NULL, 'comprehensive_test', 'listening', 'hunt', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đơn vị; bài học","săn bắn","phớt lờ; ngó lơ; không đếm xỉa","quả lạc; hạt đậu phộng"]'::jsonb, 1, 'hunt (/hʌnt/) → săn bắn; lùng sục; tìm kiếm; cuộc săn bắt; cuộc tìm kiếm', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_16_4', 'en-b1-16', NULL, 'comprehensive_test', 'listening', 'Our little cactus survived three weeks without water.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã xem một bộ phim về những chú chim cánh cụt trên băng Nam Cực.","Cây xương rồng nhỏ của chúng tôi đã sống sót suốt ba tuần không có nước.","Hôm nay tôi làm bánh mì kẹp cá ngừ cho bữa trưa.","Chúng tôi lặng lẽ quan sát động vật hoang dã từ phía sau những tán cây."]'::jsonb, 1, 'Our little cactus survived three weeks without water. → Cây xương rồng nhỏ của chúng tôi đã sống sót suốt ba tuần không có nước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_16_5', 'en-b1-16', NULL, 'comprehensive_test', 'listening', 'lizard', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xa hơn; thêm nữa; ở mức độ lớn hơn","sáng suốt; khôn ngoan","buổi thảo luận thực tế; hội thảo","thằn lằn; kỳ nhông"]'::jsonb, 3, 'lizard (/ˈlɪzərd/) → thằn lằn; kỳ nhông', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_16_6', 'en-b1-16', NULL, 'comprehensive_test', 'listening', 'I added sliced mushrooms to the soup for lunch.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những quả đào chín này thơm lừng và có vị rất ngọt.","Tôi đã cho thêm nấm thái lát vào món súp cho bữa trưa.","Hãy để tóc khô tự nhiên sau khi gội.","Cây xương rồng nhỏ của chúng tôi đã sống sót suốt ba tuần không có nước."]'::jsonb, 1, 'I added sliced mushrooms to the soup for lunch. → Tôi đã cho thêm nấm thái lát vào món súp cho bữa trưa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
