INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_16_18', 'en-b1-16', NULL, 'comprehensive_test', 'reading', NULL, 'Protecting natural habitats is essential for tortoise populations threatened by illegal trade and agricultural expansion.', 'Dựa vào câu trên, từ “tortoise” có nghĩa phù hợp nhất là gì?', '["con rùa cạn","hạn chế; có giới hạn","chìm xuống; làm chìm","sai; không chính xác; không đúng"]'::jsonb, 0, 'tortoise: con rùa cạn. Dịch cả câu: Bảo vệ môi trường sống tự nhiên là điều cần thiết đối với các quần thể rùa cạn đang bị đe dọa bởi nạn buôn bán bất hợp pháp và sự mở rộng nông nghiệp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_16_19', 'en-b1-16', NULL, 'comprehensive_test', 'reading', NULL, 'Animal welfare groups argue that small cages prevent birds from flying freely and expressing natural behaviour.', 'Dựa vào câu trên, từ “cage” có nghĩa phù hợp nhất là gì?', '["lồng; chuồng","thừa nhận","quả lạc; hạt đậu phộng","xóa; loại bỏ"]'::jsonb, 0, 'cage: lồng; chuồng; nhốt vào lồng. Dịch cả câu: Các nhóm bảo vệ động vật cho rằng những chiếc lồng nhỏ khiến loài chim không thể tự do bay lượn và thể hiện bản năng tự nhiên.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_16_20', 'en-b1-16', NULL, 'comprehensive_test', 'reading', NULL, 'When natural habitats shrink, predators may hunt closer to farms, increasing conflict between wildlife and local communities.', 'Dựa vào câu trên, từ “hunt” có nghĩa phù hợp nhất là gì?', '["tuyệt vời; kỳ diệu; gây ấn tượng mạnh","săn bắn","làm mệt mỏi; căng thẳng; mệt nhọc","nhà chính trị; chính trị gia"]'::jsonb, 1, 'hunt: săn bắn; lùng sục; tìm kiếm; cuộc săn bắt; cuộc tìm kiếm. Dịch cả câu: Khi môi trường sống tự nhiên thu hẹp, động vật săn mồi có thể tiến gần các khu trang trại hơn để kiếm mồi, làm gia tăng xung đột giữa động vật hoang dã và cộng đồng địa phương.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_16_21', 'en-b1-16', NULL, 'comprehensive_test', 'reading', NULL, 'Small businesses are more likely to survive economic downturns when they maintain strong relationships with local customers.', 'Dựa vào câu trên, từ “survive” có nghĩa phù hợp nhất là gì?', '["sống sót; tồn tại","làm tràn; làm đổ; làm rơi vãi","quả ô liu; cây ô liu (loại quả nhỏ có vị đắng dùng để ép dầu)","nghề nghiệp; chuyên môn (đòi hỏi đào tạo chuyên sâu)"]'::jsonb, 0, 'survive: sống sót; tồn tại; tiếp tục tồn tại; vượt qua; sống lâu hơn. Dịch cả câu: Các doanh nghiệp nhỏ có nhiều khả năng vượt qua được thời kỳ kinh tế suy thoái hơn khi họ duy trì mối quan hệ bền chặt với khách hàng địa phương.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_16_22', 'en-b1-16', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sừng (trên đầu động vật)”', '["responsible","northern","horn","fiction"]'::jsonb, 2, 'sừng (trên đầu động vật) → horn (/hɔːrn/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_16_23', 'en-b1-16', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “động vật hoang dã; sinh vật hoang dã”', '["wildlife","delivery","label","campus"]'::jsonb, 0, 'động vật hoang dã; sinh vật hoang dã → wildlife (/ˈwaɪldlaɪf/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_16_24', 'en-b1-16', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “một cách tự nhiên; theo tự nhiên”', '["lighthouse","celebration","naturally","obey"]'::jsonb, 2, 'một cách tự nhiên; theo tự nhiên → naturally (/ˈnætʃərəli/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-17', 'en', 'Bài 17: Thiên nhiên & Thời tiết (4) - CEFR B1', 'CEFR B1', 'B1 · Thiên nhiên', '24 từ vựng Tiếng Anh CEFR B1 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3017, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eagle', 'en-b1-17', 'eagle', '/ˈiːɡəl/', 'B1', 'chim đại bàng; con đại bàng', 'n.', 'eagle-eyed (adj.)', NULL, 'Eagle thường chỉ các loài chim săn mồi cỡ lớn; eagle-eyed dùng để chỉ tầm nhìn tinh anh, sắc sảo.', 'An eagle circled slowly above the rocky valley.', NULL, 'Một con đại bàng đang lượn chậm rãi phía trên thung lũng đá.', '{"wordId":"eagle","ukIpa":"/ˈiːɡəl/","usIpa":"/ˈiːɡəl/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A large hunting bird with powerful claws and sharp eyesight","vi":"chim đại bàng; con đại bàng"}],"examples":[{"en":"An eagle circled slowly above the rocky valley.","vi":"Một con đại bàng đang lượn chậm rãi phía trên thung lũng đá.","audioKind":"ex"},{"en":"Protecting mountain forests helps preserve the hunting grounds and nesting sites of the eagle.","vi":"Bảo vệ các khu rừng trên núi giúp duy trì các khu vực săn mồi và nơi làm tổ của đại bàng.","audioKind":"ex2"}],"collocations":[{"en":"a golden eagle","vi":"chim đại bàng vàng"},{"en":"a bald eagle","vi":"đại bàng đầu trắng"},{"en":"an eagle''s nest","vi":"tổ đại bàng"}],"wordFamily":["eagle-eyed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Eagle thường chỉ các loài chim săn mồi cỡ lớn; eagle-eyed dùng để chỉ tầm nhìn tinh anh, sắc sảo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stream', 'en-b1-17', 'stream', '/striːm/', 'B1', 'con suối; dòng suối nhỏ; dòng (người hoặc vật) liên tục; chảy liên tục; phát trực tuyến', 'n.', 'streaming (n.)', 'Đồng nghĩa: brook', 'a stream of có thể chỉ một dòng người hoặc sự việc diễn ra liên tục không dứt.', 'We crossed the shallow stream on flat stones.', NULL, 'Chúng tôi bước qua con suối nông trên những phiến đá phẳng.', '{"wordId":"stream","ukIpa":"/striːm/","usIpa":"/striːm/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A small, narrow river.","vi":"con suối; dòng suối nhỏ"},{"pos":"n.","en":"A continuous flow of people or things.","vi":"dòng (người hoặc vật) liên tục"},{"pos":"v.","en":"To flow continuously, or play media directly over the internet.","vi":"chảy liên tục; phát trực tuyến"}],"examples":[{"en":"We crossed the shallow stream on flat stones.","vi":"Chúng tôi bước qua con suối nông trên những phiến đá phẳng.","audioKind":"ex"},{"en":"Many students now stream educational videos at home, making reliable internet access increasingly important for learning.","vi":"Nhiều học sinh ngày nay xem video học tập trực tuyến tại nhà, điều này khiến cho kết nối internet ổn định ngày càng trở nên quan trọng đối với việc học.","audioKind":"ex2"}],"collocations":[{"en":"a mountain stream","vi":"một con suối trên núi"},{"en":"a steady stream of visitors","vi":"dòng khách tham quan tấp nập"},{"en":"stream music","vi":"nghe nhạc trực tuyến"}],"wordFamily":["streaming (n.)"],"synonyms":["brook"],"antonyms":[],"tipVi":"a stream of có thể chỉ một dòng người hoặc sự việc diễn ra liên tục không dứt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hunting', 'en-b1-17', 'hunting', '/ˈhʌntɪŋ/', 'B1', 'hoạt động săn bắn; săn bắt; sự tìm kiếm; sự lùng sục', 'n.', 'hunt (v.), hunter (n.)', NULL, 'Thường dùng dưới dạng danh từ không đếm được; job hunting dùng để chỉ công việc đi tìm việc.', 'We spotted fresh animal tracks during our hunting trip.', NULL, 'Chúng tôi đã phát hiện ra những dấu chân động vật tươi trong chuyến đi săn.', '{"wordId":"hunting","ukIpa":"/ˈhʌntɪŋ/","usIpa":"/ˈhʌntɪŋ/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"The activity of chasing and catching or killing wild animals.","vi":"hoạt động săn bắn; săn bắt"},{"pos":"n.","en":"The activity of trying to find something.","vi":"sự tìm kiếm; sự lùng sục"}],"examples":[{"en":"We spotted fresh animal tracks during our hunting trip.","vi":"Chúng tôi đã phát hiện ra những dấu chân động vật tươi trong chuyến đi săn.","audioKind":"ex"},{"en":"Restrictions on hunting can help protect endangered species and maintain balanced ecosystems in vulnerable natural habitats.","vi":"Việc hạn chế săn bắn có thể giúp bảo vệ các loài có nguy cơ tuyệt chủng và duy trì cân bằng sinh thái tại các môi trường sống tự nhiên dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"illegal hunting","vi":"săn bắn trái phép"},{"en":"a hunting ban","vi":"lệnh cấm săn bắn"},{"en":"job hunting","vi":"tìm kiếm việc làm"},{"en":"house hunting","vi":"đi tìm nhà"}],"wordFamily":["hunt (v.)","hunter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng dưới dạng danh từ không đếm được; job hunting dùng để chỉ công việc đi tìm việc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fur', 'en-b1-17', 'fur', '/fɜːr/', 'B1', 'lông thú; bộ lông; da thú có lông', 'n.', 'furry (adj.)', NULL, 'Chỉ lớp lông trên cơ thể động vật thường không đếm được; lông vũ dùng feather.', 'The cat''s wet fur dried quickly in the sunshine.', NULL, 'Bộ lông ướt sũng của con mèo đã khô rất nhanh dưới ánh nắng mặt trời.', '{"wordId":"fur","ukIpa":"/fɜː/","usIpa":"/fɜːr/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"the thick soft hair covering some animals","vi":"lông thú; bộ lông"},{"pos":"n.","en":"animal skin with hair attached, used for making clothing","vi":"da thú có lông"}],"examples":[{"en":"The cat''s wet fur dried quickly in the sunshine.","vi":"Bộ lông ướt sũng của con mèo đã khô rất nhanh dưới ánh nắng mặt trời.","audioKind":"ex"},{"en":"Thick fur helps many mammals survive in cold climates by trapping a layer of warm air.","vi":"Bộ lông dày giúp nhiều loài động vật có vú sinh tồn trong khí hậu lạnh giá bằng cách giữ lại một lớp không khí ấm.","audioKind":"ex2"}],"collocations":[{"en":"thick fur","vi":"lông dày"},{"en":"soft fur","vi":"lông mềm"},{"en":"faux fur","vi":"lông thú nhân tạo"},{"en":"fur coat","vi":"áo khoác lông thú"}],"wordFamily":["furry (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ lớp lông trên cơ thể động vật thường không đếm được; lông vũ dùng feather.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jungle', 'en-b1-17', 'jungle', '/ˈdʒʌŋɡəl/', 'B1', 'rừng rậm nhiệt đới; rừng nguyên sinh; môi trường cạnh tranh khốc liệt; chốn hỗn tạp hiểm nguy', 'n.', NULL, NULL, 'Thường chỉ rừng rậm vùng nhiệt đới; forest mang nghĩa rừng nói chung.', 'Thick vines hung above the narrow jungle path.', NULL, 'Những dây leo dày đặc rủ xuống phía trên lối mòn hẹp trong rừng rậm.', '{"wordId":"jungle","ukIpa":"/ˈdʒʌŋɡəl/","usIpa":"/ˈdʒʌŋɡəl/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A tropical forest with thick, closely growing plants and trees","vi":"rừng rậm nhiệt đới; rừng nguyên sinh"},{"pos":"n.","en":"A confusing or dangerous situation involving fierce competition","vi":"môi trường cạnh tranh khốc liệt; chốn hỗn tạp hiểm nguy"}],"examples":[{"en":"Thick vines hung above the narrow jungle path.","vi":"Những dây leo dày đặc rủ xuống phía trên lối mòn hẹp trong rừng rậm.","audioKind":"ex"},{"en":"Clearing jungle for agriculture destroys wildlife habitats and can reduce biodiversity across an entire region.","vi":"Việc phá rừng rậm nhiệt đới để làm nông nghiệp sẽ hủy hoại môi trường sống của động vật hoang dã và làm giảm đa dạng sinh học trên cả một vùng.","audioKind":"ex2"}],"collocations":[{"en":"dense jungle","vi":"rừng rậm u minh"},{"en":"jungle canopy","vi":"tán rừng rậm"},{"en":"urban jungle","vi":"chốn đô thị phồn hoa hiểm trở"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ rừng rậm vùng nhiệt đới; forest mang nghĩa rừng nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_volcano', 'en-b1-17', 'volcano', '/vɑːlˈkeɪnoʊ/', 'B1', 'núi lửa', 'n.', 'volcanic (adj.), volcanology (n.), volcanologist (n.)', NULL, 'Số 2 dạng số nhiều là volcanoes hoặc volcanos đều được; dùng từ erupt cho hành động phun trào.', 'We watched steam rising from the volcano across the lake.', NULL, 'Chúng tôi ngắm nhìn làn hơi nước bốc lên từ ngọn núi lửa bên kia hồ.', '{"wordId":"volcano","ukIpa":"/vɒlˈkeɪnəʊ/","usIpa":"/vɑːlˈkeɪnoʊ/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A mountain with an opening that releases lava, ash, and gases","vi":"núi lửa"}],"examples":[{"en":"We watched steam rising from the volcano across the lake.","vi":"Chúng tôi ngắm nhìn làn hơi nước bốc lên từ ngọn núi lửa bên kia hồ.","audioKind":"ex"},{"en":"Although an active volcano can threaten nearby communities, volcanic soils often provide valuable land for agriculture.","vi":"Mặc dù một ngọn núi lửa hoạt động có thể đe dọa các cộng đồng xung quanh, đất núi lửa thường mang lại những vùng đất màu mỡ quý giá cho nông nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"active volcano","vi":"núi lửa hoạt động"},{"en":"dormant volcano","vi":"núi lửa ngủ"},{"en":"extinct volcano","vi":"núi lửa đã tắt"},{"en":"a volcano erupts","vi":"núi lửa phun trào"}],"wordFamily":["volcanic (adj.)","volcanology (n.)","volcanologist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Số 2 dạng số nhiều là volcanoes hoặc volcanos đều được; dùng từ erupt cho hành động phun trào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_worm', 'en-b1-17', 'worm', '/wɝːm/', 'B1', 'con giun; con trùn; mã độc máy tính (virus máy tính lây lan qua mạng)', 'n.', 'wormlike (adj.)', NULL, 'Worm dùng chỉ chung các loài sâu bọ/giun, trong khi earthworm dùng riêng cho con trùn/giun đất.', 'A worm wriggled out of the wet garden soil.', NULL, 'Một con giun quằn quậy bò ra từ lớp đất vườn ẩm ướt.', '{"wordId":"worm","ukIpa":"/wɜːm/","usIpa":"/wɝːm/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a small animal with a long, soft body and no legs","vi":"con giun; con trùn"},{"pos":"n.","en":"a harmful computer program that copies itself across networks","vi":"mã độc máy tính (virus máy tính lây lan qua mạng)"}],"examples":[{"en":"A worm wriggled out of the wet garden soil.","vi":"Một con giun quằn quậy bò ra từ lớp đất vườn ẩm ướt.","audioKind":"ex"},{"en":"Worms improve soil quality by breaking down organic matter and allowing air to circulate underground.","vi":"Giun giúp cải thiện chất lượng đất bằng cách phân giải chất hữu cơ và tạo điều kiện cho không khí lưu thông dưới lòng đất.","audioKind":"ex2"}],"collocations":[{"en":"earthworms and other worms","vi":"giun đất và các loài giun khác"},{"en":"computer worm","vi":"mã độc máy tính"},{"en":"a can of worms","vi":"một vấn đề cực kỳ rắc rối"}],"wordFamily":["wormlike (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Worm dùng chỉ chung các loài sâu bọ/giun, trong khi earthworm dùng riêng cho con trùn/giun đất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_icy', 'en-b1-17', 'icy', '/ˈaɪsi/', 'B1', 'đóng băng; phủ đầy băng; lạnh buốt; giá lạnh; lạnh nhạt; thờ ơ', 'adj.', 'ice (n.), icily (adv.), iciness (n.)', 'Đồng nghĩa: frozen, freezing, unfriendly', 'icy vừa có thể chỉ trạng thái phủ băng hoặc cực lạnh, vừa miêu tả thái độ lạnh lùng.', 'We walked slowly along the icy path this morning.', NULL, 'Sáng nay chúng tôi đi bộ chậm rãi dọc theo con đường đóng băng.', '{"wordId":"icy","ukIpa":"/ˈaɪsi/","usIpa":"/ˈaɪsi/","cefr":"B1","topic":"nature","senses":[{"pos":"adj.","en":"Covered with ice.","vi":"đóng băng; phủ đầy băng"},{"pos":"adj.","en":"Extremely cold.","vi":"lạnh buốt; giá lạnh"},{"pos":"adj.","en":"Showing no warmth or friendliness.","vi":"lạnh nhạt; thờ ơ"}],"examples":[{"en":"We walked slowly along the icy path this morning.","vi":"Sáng nay chúng tôi đi bộ chậm rãi dọc theo con đường đóng băng.","audioKind":"ex"},{"en":"Local authorities should treat icy roads promptly to reduce accidents and maintain reliable public transport.","vi":"Chính quyền địa phương nên xử lý ngay các mặt đường đóng băng để giảm thiểu tai nạn và duy trì giao thông công cộng an toàn.","audioKind":"ex2"}],"collocations":[{"en":"icy roads","vi":"đường sá đóng băng"},{"en":"icy water","vi":"nước lạnh buốt"},{"en":"an icy stare","vi":"cái nhìn lạnh nhạt"}],"wordFamily":["ice (n.)","icily (adv.)","iciness (n.)"],"synonyms":["frozen","freezing","unfriendly"],"antonyms":[],"tipVi":"icy vừa có thể chỉ trạng thái phủ băng hoặc cực lạnh, vừa miêu tả thái độ lạnh lùng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rare', 'en-b1-17', 'rare', '/rer/', 'B1', 'hiếm; ít khi xảy ra; chín tái (thịt nấu chưa kỹ, bên trong vẫn còn màu đỏ)', 'adj.', 'rarely (adv.), rarity (n.)', 'Đồng nghĩa: uncommon, scarce · Trái nghĩa: common, frequent', 'khi dùng cho thịt, rare chỉ phần bên trong vẫn còn đỏ, độ chín thấp hơn medium.', 'We spotted a rare bird beside the lake yesterday.', NULL, 'Hôm qua chúng tôi đã phát hiện một loài chim quý hiếm bên hồ.', '{"wordId":"rare","ukIpa":"/reə/","usIpa":"/rer/","cefr":"B1","topic":"nature","senses":[{"pos":"adj.","en":"not common or not happening often","vi":"hiếm; ít khi xảy ra"},{"pos":"adj.","en":"cooked briefly so the inside remains red","vi":"chín tái (thịt nấu chưa kỹ, bên trong vẫn còn màu đỏ)"}],"examples":[{"en":"We spotted a rare bird beside the lake yesterday.","vi":"Hôm qua chúng tôi đã phát hiện một loài chim quý hiếm bên hồ.","audioKind":"ex"},{"en":"Protecting rare species requires long-term investment in habitat restoration and effective controls on illegal trade.","vi":"Việc bảo vệ các loài quý hiếm đòi hỏi sự đầu tư dài hạn vào việc khôi phục môi trường sống và kiểm soát hiệu quả hoạt động buôn bán trái phép.","audioKind":"ex2"}],"collocations":[{"en":"rare species","vi":"loài quý hiếm"},{"en":"rare opportunity","vi":"cơ hội hiếm có"},{"en":"rare steak","vi":"bít tết tái"}],"wordFamily":["rarely (adv.)","rarity (n.)"],"synonyms":["uncommon","scarce"],"antonyms":["common","frequent"],"tipVi":"khi dùng cho thịt, rare chỉ phần bên trong vẫn còn đỏ, độ chín thấp hơn medium.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flow', 'en-b1-17', 'flow', '/floʊ/', 'B1', 'chảy; luân chuyển; dòng chảy; lưu lượng', 'v.', 'flowing (adj.), inflow (n.), outflow (n.)', 'Đồng nghĩa: stream', 'Dạng quá khứ và phân từ hai đều là flowed, không phải flew.', 'Rainwater flowed down the path and into the garden.', NULL, 'Nước mưa chảy dọc theo con đường rồi đổ vào khu vườn.', '{"wordId":"flow","ukIpa":"/fləʊ/","usIpa":"/floʊ/","cefr":"B1","topic":"nature","senses":[{"pos":"v.","en":"To move continuously, like water through a channel.","vi":"chảy; luân chuyển"},{"pos":"n.","en":"Continuous movement, or the amount moving through a place.","vi":"dòng chảy; lưu lượng"}],"examples":[{"en":"Rainwater flowed down the path and into the garden.","vi":"Nước mưa chảy dọc theo con đường rồi đổ vào khu vườn.","audioKind":"ex"},{"en":"Improved public transport can ease the flow of traffic and reduce air pollution in crowded cities.","vi":"Việc cải thiện giao thông công cộng có thể giúp dòng xe cộ lưu thông trôi chảy hơn và giảm ô nhiễm không khí ở các đô thị đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"flow into","vi":"chảy vào"},{"en":"traffic flow","vi":"lưu lượng giao thông"},{"en":"cash flow","vi":"dòng tiền"},{"en":"flow rate","vi":"tốc độ dòng chảy"}],"wordFamily":["flowing (adj.)","inflow (n.)","outflow (n.)"],"synonyms":["stream"],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai đều là flowed, không phải flew.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dinosaur', 'en-b1-17', 'dinosaur', '/ˈdaɪnəsɔːr/', 'B1', 'khủng long; vật lỗi thời; người thủ hủ', 'n.', NULL, NULL, 'Khi dùng ám chỉ người hoặc tổ chức lỗi thời sẽ mang sắc thái châm biếm, cần thận trọng trong giao tiếp trang trọng.', 'We saw a huge dinosaur skeleton at the museum.', NULL, 'Chúng tôi đã nhìn thấy bộ xương khủng long khổng lồ tại bảo tàng.', '{"wordId":"dinosaur","ukIpa":"/ˈdaɪnəsɔː/","usIpa":"/ˈdaɪnəsɔːr/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a prehistoric reptile, often large, known mainly from fossils","vi":"khủng long"},{"pos":"n.","en":"a person or thing considered outdated and resistant to change","vi":"vật lỗi thời; người thủ hủ"}],"examples":[{"en":"We saw a huge dinosaur skeleton at the museum.","vi":"Chúng tôi đã nhìn thấy bộ xương khủng long khổng lồ tại bảo tàng.","audioKind":"ex"},{"en":"Studying dinosaur fossils helps researchers understand how ancient environments differed from those of the present day.","vi":"Nghiên cứu hóa thạch khủng long giúp các nhà nghiên cứu hiểu được môi trường thời cổ đại khác biệt như thế nào so với ngày nay.","audioKind":"ex2"}],"collocations":[{"en":"dinosaur fossils","vi":"hóa thạch khủng long"},{"en":"dinosaur skeleton","vi":"bộ xương khủng long"},{"en":"dinosaur extinction","vi":"sự tuyệt chủng của loài khủng long"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng ám chỉ người hoặc tổ chức lỗi thời sẽ mang sắc thái châm biếm, cần thận trọng trong giao tiếp trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fog', 'en-b1-17', 'fog', '/fɑːɡ/', 'B1', 'sương mù dày đặc; làm mờ đi; phủ sương mù', 'n.', 'foggy (adj.)', NULL, 'Fog dày hơn mist; cấu trúc fog up thường dùng khi bề mặt kính bị phủ một lớp hơi nước mờ đục.', 'Thick fog hid the hills behind our house.', NULL, 'Làn sương mù dày đặc đã che khuất những ngọn đồi phía sau ngôi nhà của chúng tôi.', '{"wordId":"fog","ukIpa":"/fɒɡ/","usIpa":"/fɑːɡ/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a thick cloud near the ground that limits visibility","vi":"sương mù dày đặc"},{"pos":"v.","en":"to become or make a surface covered with fine droplets","vi":"làm mờ đi; phủ sương mù"}],"examples":[{"en":"Thick fog hid the hills behind our house.","vi":"Làn sương mù dày đặc đã che khuất những ngọn đồi phía sau ngôi nhà của chúng tôi.","audioKind":"ex"},{"en":"Dense fog can disrupt transport networks, causing flight cancellations and increasing the risk of road accidents.","vi":"Sương mù dày đặc có thể làm tê liệt mạng lưới giao thông, gây ra việc hủy chuyến bay và làm tăng nguy cơ tai nạn giao thông đường bộ.","audioKind":"ex2"}],"collocations":[{"en":"thick fog","vi":"sương mù dày"},{"en":"dense fog","vi":"sương mù đặc quánh"},{"en":"fog lifts","vi":"sương mù tan đi"},{"en":"fog up","vi":"bị mờ đi (do hơi nước)"}],"wordFamily":["foggy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Fog dày hơn mist; cấu trúc fog up thường dùng khi bề mặt kính bị phủ một lớp hơi nước mờ đục.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spotted', 'en-b1-17', 'spotted', '/ˈspɑːtɪd/', 'B1', 'có đốm; có chấm tròn', 'adj.', 'spot (n.), spot (v.), spotty (adj.), spotless (adj.)', NULL, 'Cũng có thể dùng làm dạng quá khứ hoặc quá khứ phân từ của spot với nghĩa là nhìn thấy.', 'A spotted dog was sleeping beside the garden gate.', NULL, 'Một chú chó có đốm đang nằm ngủ cạnh cổng vườn.', '{"wordId":"spotted","ukIpa":"/ˈspɒtɪd/","usIpa":"/ˈspɑːtɪd/","cefr":"B1","topic":"nature","senses":[{"pos":"adj.","en":"Covered with small round marks or patches.","vi":"có đốm; có chấm tròn"}],"examples":[{"en":"A spotted dog was sleeping beside the garden gate.","vi":"Một chú chó có đốm đang nằm ngủ cạnh cổng vườn.","audioKind":"ex"},{"en":"Some spotted animals blend into their surroundings, making them harder for predators to detect.","vi":"Một số loài động vật có đốm có thể hòa lẫn vào môi trường xung quanh, khiến cho kẻ săn mồi khó phát hiện ra chúng hơn.","audioKind":"ex2"}],"collocations":[{"en":"spotted coat","vi":"bộ lông có đốm"},{"en":"spotted dress","vi":"chiếc váy chấm bi"},{"en":"spotted pattern","vi":"họa tiết chấm đốm"}],"wordFamily":["spot (n.)","spot (v.)","spotty (adj.)","spotless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cũng có thể dùng làm dạng quá khứ hoặc quá khứ phân từ của spot với nghĩa là nhìn thấy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_earthquake', 'en-b1-17', 'earthquake', '/ˈɜːrθkweɪk/', 'B1', 'trận động đất', 'n.', NULL, 'Đồng nghĩa: quake', 'Là danh từ đếm được; diễn tả động đất xảy ra có thể dùng an earthquake strikes.', 'The earthquake made the cups rattle on our kitchen shelf.', NULL, 'Trận động đất làm các chiếc cốc kêu lách cách trên kệ bếp của chúng tôi.', '{"wordId":"earthquake","ukIpa":"/ˈɜːθkweɪk/","usIpa":"/ˈɜːrθkweɪk/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"Sudden shaking of the ground caused by movement beneath Earth''s surface.","vi":"trận động đất"}],"examples":[{"en":"The earthquake made the cups rattle on our kitchen shelf.","vi":"Trận động đất làm các chiếc cốc kêu lách cách trên kệ bếp của chúng tôi.","audioKind":"ex"},{"en":"Strict building regulations can significantly reduce the risk of injury when an earthquake strikes a densely populated city.","vi":"Các quy định xây dựng nghiêm ngặt có thể làm giảm đáng kể nguy cơ thương vong khi một trận động đất xảy ra ở thành phố đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"a powerful earthquake","vi":"trận động đất mạnh"},{"en":"an earthquake strikes","vi":"động đất xảy ra"},{"en":"earthquake damage","vi":"thiệt hại do động đất"},{"en":"earthquake zone","vi":"vùng động đất"}],"wordFamily":[],"synonyms":["quake"],"antonyms":[],"tipVi":"Là danh từ đếm được; diễn tả động đất xảy ra có thể dùng an earthquake strikes.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_footpath', 'en-b1-17', 'footpath', '/ˈfʊtpæθ/', 'B1', 'đường mòn; lối đi bộ', 'n.', NULL, 'Đồng nghĩa: path, walkway', 'Thường chỉ đường dành riêng cho người đi bộ, không nhất thiết phải nằm sát đường lớn.', 'A narrow footpath leads from our village to the lake.', NULL, 'Một con đường mòn nhỏ hẹp dẫn từ làng chúng tôi ra hồ nước.', '{"wordId":"footpath","ukIpa":"/ˈfʊtpɑːθ/","usIpa":"/ˈfʊtpæθ/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A path intended for walking rather than driving.","vi":"đường mòn; lối đi bộ"}],"examples":[{"en":"A narrow footpath leads from our village to the lake.","vi":"Một con đường mòn nhỏ hẹp dẫn từ làng chúng tôi ra hồ nước.","audioKind":"ex"},{"en":"Maintaining rural footpaths encourages outdoor recreation while helping visitors avoid damage to surrounding farmland.","vi":"Việc duy trì các tuyến đường mòn vùng nông thôn khuyến khích các hoạt động giải trí ngoài trời đồng thời giúp du khách tránh làm hư hại đất nông nghiệp xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"public footpath","vi":"đường đi bộ công cộng"},{"en":"narrow footpath","vi":"đường mòn hẹp"},{"en":"follow a footpath","vi":"đi theo đường mòn"}],"wordFamily":[],"synonyms":["path","walkway"],"antonyms":[],"tipVi":"Thường chỉ đường dành riêng cho người đi bộ, không nhất thiết phải nằm sát đường lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shell', 'en-b1-17', 'shell', '/ʃel/', 'B1', 'vỏ (động vật, trứng, quả); bóc vỏ; tách vỏ; đạn pháo', 'n.', 'shellfish (n.), shelled (adj.)', NULL, 'shell làm động từ có thể chỉ việc bóc vỏ; shell peas là bóc vỏ đậu.', 'She found a tiny crab inside the empty shell.', NULL, 'Cô ấy tìm thấy một con cua nhỏ xíu bên trong chiếc vỏ rỗng.', '{"wordId":"shell","ukIpa":"/ʃel/","usIpa":"/ʃel/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A hard outer covering protecting an animal, egg, or nut.","vi":"vỏ (động vật, trứng, quả)"},{"pos":"v.","en":"To remove the hard outer covering of something.","vi":"bóc vỏ; tách vỏ"},{"pos":"n.","en":"An explosive object fired from a large gun.","vi":"đạn pháo"}],"examples":[{"en":"She found a tiny crab inside the empty shell.","vi":"Cô ấy tìm thấy một con cua nhỏ xíu bên trong chiếc vỏ rỗng.","audioKind":"ex"},{"en":"Rising ocean acidity can weaken the shells of marine animals, threatening their survival and wider ecosystems.","vi":"Độ axit đại dương tăng cao có thể làm suy yếu vỏ của các loài động vật biển, đe dọa sự sống còn của chúng và các hệ sinh thái rộng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"a hard shell","vi":"vỏ cứng"},{"en":"an empty shell","vi":"vỏ rỗng"},{"en":"shell peas","vi":"bóc vỏ đậu"}],"wordFamily":["shellfish (n.)","shelled (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"shell làm động từ có thể chỉ việc bóc vỏ; shell peas là bóc vỏ đậu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chick', 'en-b1-17', 'chick', '/tʃɪk/', 'B1', 'gà con; chim non', 'n.', 'chicken (n.)', 'Đồng nghĩa: hatchling', 'Không chỉ chỉ gà con, từ này còn dùng cho chim non của các loài khác.', 'A yellow chick followed the hen across the yard.', NULL, 'Một con gà con màu vàng đi theo gà mái bước qua sân.', '{"wordId":"chick","ukIpa":"/tʃɪk/","usIpa":"/tʃɪk/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A baby bird, especially a young chicken.","vi":"gà con; chim non"}],"examples":[{"en":"A yellow chick followed the hen across the yard.","vi":"Một con gà con màu vàng đi theo gà mái bước qua sân.","audioKind":"ex"},{"en":"Conservation teams monitor each newly hatched chick to assess whether habitat restoration is improving breeding success.","vi":"Các nhóm bảo tồn theo dõi từng chú chim non mới nở để đánh giá xem việc phục hồi môi trường sống có cải thiện tỷ lệ sinh sản hay không.","audioKind":"ex2"}],"collocations":[{"en":"newly hatched chick","vi":"chim non mới nở"},{"en":"day-old chick","vi":"gà con một ngày tuổi"},{"en":"rear chicks","vi":"nuôi dưỡng chim non"}],"wordFamily":["chicken (n.)"],"synonyms":["hatchling"],"antonyms":[],"tipVi":"Không chỉ chỉ gà con, từ này còn dùng cho chim non của các loài khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grain', 'en-b1-17', 'grain', '/ɡreɪn/', 'B1', 'lương thực; ngũ cốc; hạt; thớ; hạt nhỏ; vân (gỗ); thớ gỗ', 'n.', 'grainy (adj.)', NULL, 'grain chỉ lương thực thường không đếm được; chỉ từng hạt đơn lẻ hoặc hạt mịn thì đếm được.', 'The farmer stored the grain in a dry barn.', NULL, 'Người nông dân đã cất trữ số ngũ cốc trong một nhà kho khô ráo.', '{"wordId":"grain","ukIpa":"/ɡreɪn/","usIpa":"/ɡreɪn/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"seeds of crops such as wheat, used as food","vi":"lương thực; ngũ cốc"},{"pos":"n.","en":"a very small hard piece of a substance","vi":"hạt; thớ; hạt nhỏ"},{"pos":"n.","en":"the natural pattern of lines in wood","vi":"vân (gỗ); thớ gỗ"}],"examples":[{"en":"The farmer stored the grain in a dry barn.","vi":"Người nông dân đã cất trữ số ngũ cốc trong một nhà kho khô ráo.","audioKind":"ex"},{"en":"Growing grain requires reliable water supplies, which are increasingly threatened by drought in many agricultural regions.","vi":"Việc trồng ngũ cốc đòi hỏi nguồn nước ổn định, vốn đang ngày càng bị đe dọa bởi hạn hán ở nhiều vùng nông nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"whole grain","vi":"ngũ cốc nguyên hạt"},{"en":"a grain of sand","vi":"một hạt cát"},{"en":"wood grain","vi":"vân gỗ"}],"wordFamily":["grainy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"grain chỉ lương thực thường không đếm được; chỉ từng hạt đơn lẻ hoặc hạt mịn thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rainbow', 'en-b1-17', 'rainbow', '/ˈreɪnboʊ/', 'B1', 'cầu vồng; sự rực rỡ nhiều màu sắc', 'n.', NULL, NULL, 'Thường là danh từ đếm được; cụm a rainbow of diễn tả một dải màu sắc phong phú, đa dạng.', 'A bright rainbow appeared above the hills after lunch.', NULL, 'Một chiếc cầu vồng rực rỡ xuất hiện trên những ngọn đồi sau bữa trưa.', '{"wordId":"rainbow","ukIpa":"/ˈreɪnbəʊ/","usIpa":"/ˈreɪnboʊ/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a curved band of colours appearing in the sky after rain","vi":"cầu vồng"},{"pos":"n.","en":"a collection or range of many different colours","vi":"sự rực rỡ nhiều màu sắc"}],"examples":[{"en":"A bright rainbow appeared above the hills after lunch.","vi":"Một chiếc cầu vồng rực rỡ xuất hiện trên những ngọn đồi sau bữa trưa.","audioKind":"ex"},{"en":"Tourists often photograph the rainbow that forms in the spray near the base of the waterfall.","vi":"Du khách thường chụp ảnh cầu vồng hình thành trong lớp sương mù gần chân thác nước.","audioKind":"ex2"}],"collocations":[{"en":"a rainbow appears","vi":"cầu vồng xuất hiện"},{"en":"a rainbow of colours","vi":"muôn màu rực rỡ"},{"en":"a double rainbow","vi":"cầu vồng đôi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ đếm được; cụm a rainbow of diễn tả một dải màu sắc phong phú, đa dạng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thunderstorm', 'en-b1-17', 'thunderstorm', '/ˈθʌndərstɔːrm/', 'B1', 'cơn giông bão; trận mưa giông', 'n.', 'thunder (n.), thunderous (adj.), stormy (adj.)', NULL, 'Thunder là tiếng sấm, lightning là tia chớp; còn thunderstorm là từ chỉ cả trận giông bão.', 'We stayed indoors while the thunderstorm shook the windows.', NULL, 'Chúng tôi ở trong nhà trong khi trận giông bão làm rung chuyển cả khung cửa sổ.', '{"wordId":"thunderstorm","ukIpa":"/ˈθʌndəstɔːm/","usIpa":"/ˈθʌndərstɔːrm/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A storm with thunder, lightning, and usually heavy rain.","vi":"cơn giông bão; trận mưa giông"}],"examples":[{"en":"We stayed indoors while the thunderstorm shook the windows.","vi":"Chúng tôi ở trong nhà trong khi trận giông bão làm rung chuyển cả khung cửa sổ.","audioKind":"ex"},{"en":"Severe thunderstorms can disrupt transport networks and cause sudden flooding, particularly in cities with inadequate drainage.","vi":"Những trận giông bão lớn có thể làm gián đoạn mạng lưới giao thông và gây ngập lụt đột ngột, đặc biệt là ở những thành phố có hệ thống thoát nước kém.","audioKind":"ex2"}],"collocations":[{"en":"a severe thunderstorm","vi":"một trận giông bão lớn"},{"en":"a thunderstorm warning","vi":"cảnh báo giông bão"},{"en":"scattered thunderstorms","vi":"mưa giông rải rác"}],"wordFamily":["thunder (n.)","thunderous (adj.)","stormy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thunder là tiếng sấm, lightning là tia chớp; còn thunderstorm là từ chỉ cả trận giông bão.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deer', 'en-b1-17', 'deer', '/dɪr/', 'B1', 'con nai; con hươu', 'n.', NULL, NULL, 'Danh từ deer có dạng số ít và số nhiều như nhau: dùng one deer, several deer.', 'A deer stood quietly beside the forest path.', NULL, 'Một chú nai đứng lặng lẽ bên lối đi trong rừng.', '{"wordId":"deer","ukIpa":"/dɪə/","usIpa":"/dɪr/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a hoofed wild animal whose males usually have branching antlers","vi":"con nai; con hươu"}],"examples":[{"en":"A deer stood quietly beside the forest path.","vi":"Một chú nai đứng lặng lẽ bên lối đi trong rừng.","audioKind":"ex"},{"en":"Protecting woodland habitats helps maintain healthy deer populations, but careful management is needed to prevent excessive grazing.","vi":"Việc bảo vệ môi trường sống trong rừng giúp duy trì quần thể hươu nai khỏe mạnh, nhưng cần có biện pháp quản lý cẩn thận để ngăn chặn tình trạng ăn cỏ quá mức.","audioKind":"ex2"}],"collocations":[{"en":"a herd of deer","vi":"một bầy nai"},{"en":"deer antlers","vi":"sừng nai"},{"en":"wild deer","vi":"hươu nai hoang dã"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ deer có dạng số ít và số nhiều như nhau: dùng one deer, several deer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diamond', 'en-b1-17', 'diamond', '/ˈdaɪəmənd/', 'B1', 'kim cương; hột xoàn; hình thoi', 'n.', NULL, NULL, 'diamond chỉ kim cương; thuật ngữ hình học cho hình thoi là rhombus.', 'A tiny diamond sparkled on her silver ring.', NULL, 'Một viên kim cương nhỏ lấp lánh trên chiếc nhẫn bạc của cô ấy.', '{"wordId":"diamond","ukIpa":"/ˈdaɪəmənd/","usIpa":"/ˈdaɪəmənd/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"a very hard mineral used in jewellery and cutting tools","vi":"kim cương; hột xoàn"},{"pos":"n.","en":"a shape with four equal sides and opposite angles equal","vi":"hình thoi"}],"examples":[{"en":"A tiny diamond sparkled on her silver ring.","vi":"Một viên kim cương nhỏ lấp lánh trên chiếc nhẫn bạc của cô ấy.","audioKind":"ex"},{"en":"The diamond industry faces growing pressure to demonstrate that its mining practices protect workers and local ecosystems.","vi":"Ngành công nghiệp kim cương đang đối mặt với áp lực ngày càng lớn trong việc chứng minh rằng hoạt động khai thác của họ bảo vệ người lao động và hệ sinh thái địa phương.","audioKind":"ex2"}],"collocations":[{"en":"diamond ring","vi":"nhẫn kim cương"},{"en":"rough diamond","vi":"kim cương thô"},{"en":"diamond mining","vi":"khai thác kim cương"},{"en":"diamond shape","vi":"hình thoi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"diamond chỉ kim cương; thuật ngữ hình học cho hình thoi là rhombus.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_humid', 'en-b1-17', 'humid', '/ˈhjuːmɪd/', 'B1', 'ẩm ướt; nồm ẩm; ẩm thấp', 'adj.', 'humidity (n.), humidify (v.), humidifier (n.)', 'Đồng nghĩa: muggy · Trái nghĩa: dry', 'humid chủ yếu dùng để miêu tả không khí hoặc khí hậu ẩm, không dùng cho quần áo ướt.', 'It feels so humid that my shirt sticks to me.', NULL, 'Thời tiết ẩm ướt đến mức chiếc áo sơ mi dính bết vào người tôi.', '{"wordId":"humid","ukIpa":"/ˈhjuːmɪd/","usIpa":"/ˈhjuːmɪd/","cefr":"B1","topic":"nature","senses":[{"pos":"adj.","en":"containing a lot of moisture in the air","vi":"ẩm ướt; nồm ẩm; ẩm thấp"}],"examples":[{"en":"It feels so humid that my shirt sticks to me.","vi":"Thời tiết ẩm ướt đến mức chiếc áo sơ mi dính bết vào người tôi.","audioKind":"ex"},{"en":"In humid climates, buildings require effective ventilation to prevent mould growth and protect residents'' health.","vi":"Trong khí hậu ẩm ướt, các công trình xây dựng cần có hệ thống thông gió hiệu quả để ngăn ngừa sự phát triểnของ nấm mốc và bảo vệ sức khỏe cư dân.","audioKind":"ex2"}],"collocations":[{"en":"humid climate","vi":"khí hậu ẩm ướt"},{"en":"hot and humid","vi":"nóng ẩm"},{"en":"humid air","vi":"không khí ẩm"}],"wordFamily":["humidity (n.)","humidify (v.)","humidifier (n.)"],"synonyms":["muggy"],"antonyms":["dry"],"tipVi":"humid chủ yếu dùng để miêu tả không khí hoặc khí hậu ẩm, không dùng cho quần áo ướt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fox', 'en-b1-17', 'fox', '/fɑːks/', 'B1', 'con cáo (loài thú hoang dã có tai nhọn và đuôi rậm); làm cho bối rối; làm khó (khiến ai đó lúng túng hoặc bài toán khó giải)', 'n.', NULL, NULL, 'Khi dùng làm động từ mang nghĩa "làm khó/gây bối rối", từ này chủ yếu xuất hiện trong văn phong không trang trọng của tiếng Anh - Anh.', 'A fox slipped through the garden before sunrise.', NULL, 'Một con cáo đã lén lút băng qua khu vườn trước khi trời sáng.', '{"wordId":"fox","ukIpa":"/fɒks/","usIpa":"/fɑːks/","cefr":"B1","topic":"nature","senses":[{"pos":"n.","en":"A wild animal with pointed ears and a bushy tail.","vi":"con cáo (loài thú hoang dã có tai nhọn và đuôi rậm)"},{"pos":"v.","en":"To confuse someone or make a problem difficult to solve.","vi":"làm cho bối rối; làm khó (khiến ai đó lúng túng hoặc bài toán khó giải)"}],"examples":[{"en":"A fox slipped through the garden before sunrise.","vi":"Một con cáo đã lén lút băng qua khu vườn trước khi trời sáng.","audioKind":"ex"},{"en":"The red fox can adapt to urban environments where food is readily available from human activity.","vi":"Cáo đỏ có thể thích nghi với môi trường đô thị nơi thức ăn có sẵn từ các hoạt động của con người.","audioKind":"ex2"}],"collocations":[{"en":"a red fox","vi":"một con cáo đỏ"},{"en":"an urban fox","vi":"con cáo thành phố"},{"en":"a fox cub","vi":"cáo con"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng làm động từ mang nghĩa \"làm khó/gây bối rối\", từ này chủ yếu xuất hiện trong văn phong không trang trọng của tiếng Anh - Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_17_1', 'en-b1-17', 'Cách dùng “fox” (n.) — con cáo (loài thú hoang dã có tai nhọn và đuôi rậm)', 'a red fox  ·  an urban fox  ·  a fox cub', 'Khi dùng làm động từ mang nghĩa "làm khó/gây bối rối", từ này chủ yếu xuất hiện trong văn phong không trang trọng của tiếng Anh - Anh.', NULL, '[{"hanzi":"A fox slipped through the garden before sunrise.","pinyin":"","meaning":"Một con cáo đã lén lút băng qua khu vườn trước khi trời sáng."},{"hanzi":"The red fox can adapt to urban environments where food is readily available from human activity.","pinyin":"","meaning":"Cáo đỏ có thể thích nghi với môi trường đô thị nơi thức ăn có sẵn từ các hoạt động của con người."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_17_2', 'en-b1-17', 'Cách dùng “dinosaur” (n.) — khủng long', 'dinosaur fossils  ·  dinosaur skeleton  ·  dinosaur extinction', 'Khi dùng ám chỉ người hoặc tổ chức lỗi thời sẽ mang sắc thái châm biếm, cần thận trọng trong giao tiếp trang trọng.', NULL, '[{"hanzi":"We saw a huge dinosaur skeleton at the museum.","pinyin":"","meaning":"Chúng tôi đã nhìn thấy bộ xương khủng long khổng lồ tại bảo tàng."},{"hanzi":"Studying dinosaur fossils helps researchers understand how ancient environments differed from those of the present day.","pinyin":"","meaning":"Nghiên cứu hóa thạch khủng long giúp các nhà nghiên cứu hiểu được môi trường thời cổ đại khác biệt như thế nào so với ngày nay."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_17_3', 'en-b1-17', 'Cách dùng “eagle” (n.) — chim đại bàng; con đại bàng', 'a golden eagle  ·  a bald eagle  ·  an eagle''s nest', 'Eagle thường chỉ các loài chim săn mồi cỡ lớn; eagle-eyed dùng để chỉ tầm nhìn tinh anh, sắc sảo.', 'Họ từ (Word Family): eagle-eyed (adj.)', '[{"hanzi":"An eagle circled slowly above the rocky valley.","pinyin":"","meaning":"Một con đại bàng đang lượn chậm rãi phía trên thung lũng đá."},{"hanzi":"Protecting mountain forests helps preserve the hunting grounds and nesting sites of the eagle.","pinyin":"","meaning":"Bảo vệ các khu rừng trên núi giúp duy trì các khu vực săn mồi và nơi làm tổ của đại bàng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_17_4', 'en-b1-17', 'Cách dùng “worm” (n.) — con giun; con trùn', 'earthworms and other worms  ·  computer worm  ·  a can of worms', 'Worm dùng chỉ chung các loài sâu bọ/giun, trong khi earthworm dùng riêng cho con trùn/giun đất.', 'Họ từ (Word Family): wormlike (adj.)', '[{"hanzi":"A worm wriggled out of the wet garden soil.","pinyin":"","meaning":"Một con giun quằn quậy bò ra từ lớp đất vườn ẩm ướt."},{"hanzi":"Worms improve soil quality by breaking down organic matter and allowing air to circulate underground.","pinyin":"","meaning":"Giun giúp cải thiện chất lượng đất bằng cách phân giải chất hữu cơ và tạo điều kiện cho không khí lưu thông dưới lòng đất."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_17_1', 'en-b1-17', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_17_1_1', 'ten_b1_17_1', 'eagle', 'An eagle circled slowly above the rocky valley.', 'An eagle circled slowly above the rocky valley.', '/ˈiːɡəl/', 'Một con đại bàng đang lượn chậm rãi phía trên thung lũng đá.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_17_1_2', 'ten_b1_17_1', 'stream', 'We crossed the shallow stream on flat stones.', 'We crossed the shallow stream on flat stones.', '/striːm/', 'Chúng tôi bước qua con suối nông trên những phiến đá phẳng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_17_1_3', 'ten_b1_17_1', 'hunting', 'We spotted fresh animal tracks during our hunting trip.', 'We spotted fresh animal tracks during our hunting trip.', '/ˈhʌntɪŋ/', 'Chúng tôi đã phát hiện ra những dấu chân động vật tươi trong chuyến đi săn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_17_1_4', 'ten_b1_17_1', 'fur', 'The cat''s wet fur dried quickly in the sunshine.', 'The cat''s wet fur dried quickly in the sunshine.', '/fɜːr/', 'Bộ lông ướt sũng của con mèo đã khô rất nhanh dưới ánh nắng mặt trời.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_17_1_5', 'ten_b1_17_1', 'jungle', 'Thick vines hung above the narrow jungle path.', 'Thick vines hung above the narrow jungle path.', '/ˈdʒʌŋɡəl/', 'Những dây leo dày đặc rủ xuống phía trên lối mòn hẹp trong rừng rậm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
