INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_17_1_1', 'en-b1-17', 'ten_b1_17_1', 'listening', 'listening', 'An eagle circled slowly above the rocky valley.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một con đại bàng đang lượn chậm rãi phía trên thung lũng đá.","Thời tiết ẩm ướt đến mức chiếc áo sơ mi dính bết vào người tôi.","Một con đường mòn nhỏ hẹp dẫn từ làng chúng tôi ra hồ nước.","Sáng nay chúng tôi đi bộ chậm rãi dọc theo con đường đóng băng."]'::jsonb, 0, 'An eagle circled slowly above the rocky valley. → Một con đại bàng đang lượn chậm rãi phía trên thung lũng đá.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_17_1_2', 'en-b1-17', 'ten_b1_17_1', 'listening', 'listening', 'We crossed the shallow stream on flat stones.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi ngắm nhìn làn hơi nước bốc lên từ ngọn núi lửa bên kia hồ.","Một viên kim cương nhỏ lấp lánh trên chiếc nhẫn bạc của cô ấy.","Một con giun quằn quậy bò ra từ lớp đất vườn ẩm ướt.","Chúng tôi bước qua con suối nông trên những phiến đá phẳng."]'::jsonb, 3, 'We crossed the shallow stream on flat stones. → Chúng tôi bước qua con suối nông trên những phiến đá phẳng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_17_1_3', 'en-b1-17', 'ten_b1_17_1', 'listening', 'listening', 'We spotted fresh animal tracks during our hunting trip.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi ở trong nhà trong khi trận giông bão làm rung chuyển cả khung cửa sổ.","Làn sương mù dày đặc đã che khuất những ngọn đồi phía sau ngôi nhà của chúng tôi.","Một chú chó có đốm đang nằm ngủ cạnh cổng vườn.","Chúng tôi đã phát hiện ra những dấu chân động vật tươi trong chuyến đi săn."]'::jsonb, 3, 'We spotted fresh animal tracks during our hunting trip. → Chúng tôi đã phát hiện ra những dấu chân động vật tươi trong chuyến đi săn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_17_2', 'en-b1-17', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_17_2_1', 'ten_b1_17_2', 'eagle', 'Protecting mountain forests helps preserve the hunting grounds and nesting sites of the eagle.', 'Protecting mountain forests helps preserve the hunting grounds and nesting sites of the eagle.', '/ˈiːɡəl/', 'Bảo vệ các khu rừng trên núi giúp duy trì các khu vực săn mồi và nơi làm tổ của đại bàng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_17_2_2', 'ten_b1_17_2', 'stream', 'Many students now stream educational videos at home, making reliable internet access increasingly important for learning.', 'Many students now stream educational videos at home, making reliable internet access increasingly important for learning.', '/striːm/', 'Nhiều học sinh ngày nay xem video học tập trực tuyến tại nhà, điều này khiến cho kết nối internet ổn định ngày càng trở nên quan trọng đối với việc học.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_17_2_3', 'ten_b1_17_2', 'hunting', 'Restrictions on hunting can help protect endangered species and maintain balanced ecosystems in vulnerable natural habitats.', 'Restrictions on hunting can help protect endangered species and maintain balanced ecosystems in vulnerable natural habitats.', '/ˈhʌntɪŋ/', 'Việc hạn chế săn bắn có thể giúp bảo vệ các loài có nguy cơ tuyệt chủng và duy trì cân bằng sinh thái tại các môi trường sống tự nhiên dễ bị tổn thương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_17_2_4', 'ten_b1_17_2', 'fur', 'Thick fur helps many mammals survive in cold climates by trapping a layer of warm air.', 'Thick fur helps many mammals survive in cold climates by trapping a layer of warm air.', '/fɜːr/', 'Bộ lông dày giúp nhiều loài động vật có vú sinh tồn trong khí hậu lạnh giá bằng cách giữ lại một lớp không khí ấm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_17_2_5', 'ten_b1_17_2', 'jungle', 'Clearing jungle for agriculture destroys wildlife habitats and can reduce biodiversity across an entire region.', 'Clearing jungle for agriculture destroys wildlife habitats and can reduce biodiversity across an entire region.', '/ˈdʒʌŋɡəl/', 'Việc phá rừng rậm nhiệt đới để làm nông nghiệp sẽ hủy hoại môi trường sống của động vật hoang dã và làm giảm đa dạng sinh học trên cả một vùng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_17_2_6', 'ten_b1_17_2', 'volcano', 'Although an active volcano can threaten nearby communities, volcanic soils often provide valuable land for agriculture.', 'Although an active volcano can threaten nearby communities, volcanic soils often provide valuable land for agriculture.', '/vɑːlˈkeɪnoʊ/', 'Mặc dù một ngọn núi lửa hoạt động có thể đe dọa các cộng đồng xung quanh, đất núi lửa thường mang lại những vùng đất màu mỡ quý giá cho nông nghiệp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_17_2_1', 'en-b1-17', 'ten_b1_17_2', 'listening', 'listening', 'Protecting mountain forests helps preserve the hunting grounds and nesting sites of the eagle.', NULL, 'Trong câu vừa nghe, từ “eagle” mang nghĩa nào sau đây?', '["có đủ khả năng chi trả; mua nổi","thuyết phục; khuyên nhủ","chim đại bàng; con đại bàng","vui vẻ; rộn ràng; hân hoan"]'::jsonb, 2, '“eagle” (/ˈiːɡəl/): chim đại bàng; con đại bàng. Câu đầy đủ: Protecting mountain forests helps preserve the hunting grounds and nesting sites of the eagle.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_17_2_2', 'en-b1-17', 'ten_b1_17_2', 'listening', 'listening', 'Many students now stream educational videos at home, making reliable internet access increasingly important for learning.', NULL, 'Trong câu vừa nghe, từ “stream” mang nghĩa nào sau đây?', '["con suối; dòng suối nhỏ","con sói","hình tam giác","vật liệu; nguyên liệu; vải vóc"]'::jsonb, 0, '“stream” (/striːm/): con suối; dòng suối nhỏ. Câu đầy đủ: Many students now stream educational videos at home, making reliable internet access increasingly important for learning.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
