INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_2', 'en-b1-17', NULL, 'comprehensive_test', 'listening', 'We crossed the shallow stream on flat stones.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sáng nay chúng tôi đi bộ chậm rãi dọc theo con đường đóng băng.","Chúng tôi bước qua con suối nông trên những phiến đá phẳng.","Thời tiết ẩm ướt đến mức chiếc áo sơ mi dính bết vào người tôi.","Trận động đất làm các chiếc cốc kêu lách cách trên kệ bếp của chúng tôi."]'::jsonb, 1, 'We crossed the shallow stream on flat stones. → Chúng tôi bước qua con suối nông trên những phiến đá phẳng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_3', 'en-b1-17', NULL, 'comprehensive_test', 'listening', 'hunting', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tiền xe; tiền vé; cước phí","sự liên lạc; sự tiếp xúc","chấm; điểm tròn nhỏ","hoạt động săn bắn; săn bắt"]'::jsonb, 3, 'hunting (/ˈhʌntɪŋ/) → hoạt động săn bắn; săn bắt; sự tìm kiếm; sự lùng sục', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_4', 'en-b1-17', NULL, 'comprehensive_test', 'listening', 'The cat''s wet fur dried quickly in the sunshine.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Trận động đất làm các chiếc cốc kêu lách cách trên kệ bếp của chúng tôi.","Bộ lông ướt sũng của con mèo đã khô rất nhanh dưới ánh nắng mặt trời.","Chúng tôi ngắm nhìn làn hơi nước bốc lên từ ngọn núi lửa bên kia hồ.","Một viên kim cương nhỏ lấp lánh trên chiếc nhẫn bạc của cô ấy."]'::jsonb, 1, 'The cat''s wet fur dried quickly in the sunshine. → Bộ lông ướt sũng của con mèo đã khô rất nhanh dưới ánh nắng mặt trời.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_5', 'en-b1-17', NULL, 'comprehensive_test', 'listening', 'jungle', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["rừng rậm nhiệt đới; rừng nguyên sinh","vết nứt; vết rạn","ý định; mục đích; dự định","vũ khí; binh khí"]'::jsonb, 0, 'jungle (/ˈdʒʌŋɡəl/) → rừng rậm nhiệt đới; rừng nguyên sinh; môi trường cạnh tranh khốc liệt; chốn hỗn tạp hiểm nguy', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_6', 'en-b1-17', NULL, 'comprehensive_test', 'listening', 'We watched steam rising from the volcano across the lake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sáng nay chúng tôi đi bộ chậm rãi dọc theo con đường đóng băng.","Làn sương mù dày đặc đã che khuất những ngọn đồi phía sau ngôi nhà của chúng tôi.","Một chiếc cầu vồng rực rỡ xuất hiện trên những ngọn đồi sau bữa trưa.","Chúng tôi ngắm nhìn làn hơi nước bốc lên từ ngọn núi lửa bên kia hồ."]'::jsonb, 3, 'We watched steam rising from the volcano across the lake. → Chúng tôi ngắm nhìn làn hơi nước bốc lên từ ngọn núi lửa bên kia hồ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_7', 'en-b1-17', NULL, 'comprehensive_test', 'listening', 'worm', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["con giun; con trùn","cá hồi; thịt cá hồi","loạt; chuỗi; dải (các sự việc, sự kiện liên tiếp)","tiền tệ (được sử dụng ở một quốc gia cụ thể)"]'::jsonb, 0, 'worm (/wɝːm/) → con giun; con trùn; mã độc máy tính (virus máy tính lây lan qua mạng)', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_8', 'en-b1-17', NULL, 'comprehensive_test', 'listening', 'We walked slowly along the icy path this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sáng nay chúng tôi đi bộ chậm rãi dọc theo con đường đóng băng.","Cô ấy tìm thấy một con cua nhỏ xíu bên trong chiếc vỏ rỗng.","Thời tiết ẩm ướt đến mức chiếc áo sơ mi dính bết vào người tôi.","Chúng tôi ở trong nhà trong khi trận giông bão làm rung chuyển cả khung cửa sổ."]'::jsonb, 0, 'We walked slowly along the icy path this morning. → Sáng nay chúng tôi đi bộ chậm rãi dọc theo con đường đóng băng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
