INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_18', 'en-b1-17', NULL, 'comprehensive_test', 'reading', NULL, 'Protecting mountain forests helps preserve the hunting grounds and nesting sites of the eagle.', 'Dựa vào câu trên, từ “eagle” có nghĩa phù hợp nhất là gì?', '["sự thiệt hại; sự hư hại","ký túc xá; phòng ngủ tập thể","chim đại bàng; con đại bàng","tiệc tự chọn; tiệc buffet"]'::jsonb, 2, 'eagle: chim đại bàng; con đại bàng. Dịch cả câu: Bảo vệ các khu rừng trên núi giúp duy trì các khu vực săn mồi và nơi làm tổ của đại bàng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_19', 'en-b1-17', NULL, 'comprehensive_test', 'reading', NULL, 'Many students now stream educational videos at home, making reliable internet access increasingly important for learning.', 'Dựa vào câu trên, từ “stream” có nghĩa phù hợp nhất là gì?', '["cuộc đua tốc độ; môn đua","đuổi theo, rượt đuổi ai đó để bắt","con suối; dòng suối nhỏ","cập nhật; làm cho mới nhất"]'::jsonb, 2, 'stream: con suối; dòng suối nhỏ; dòng (người hoặc vật) liên tục; chảy liên tục; phát trực tuyến. Dịch cả câu: Nhiều học sinh ngày nay xem video học tập trực tuyến tại nhà, điều này khiến cho kết nối internet ổn định ngày càng trở nên quan trọng đối với việc học.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_20', 'en-b1-17', NULL, 'comprehensive_test', 'reading', NULL, 'Restrictions on hunting can help protect endangered species and maintain balanced ecosystems in vulnerable natural habitats.', 'Dựa vào câu trên, từ “hunting” có nghĩa phù hợp nhất là gì?', '["gồ ghề; xù xì; không bằng phẳng","hoạt động săn bắn; săn bắt","tăng dần; ngày càng nhiều","ống (vật hình trụ rỗng để dẫn chất lỏng hoặc khí)"]'::jsonb, 1, 'hunting: hoạt động săn bắn; săn bắt; sự tìm kiếm; sự lùng sục. Dịch cả câu: Việc hạn chế săn bắn có thể giúp bảo vệ các loài có nguy cơ tuyệt chủng và duy trì cân bằng sinh thái tại các môi trường sống tự nhiên dễ bị tổn thương.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_21', 'en-b1-17', NULL, 'comprehensive_test', 'reading', NULL, 'Thick fur helps many mammals survive in cold climates by trapping a layer of warm air.', 'Dựa vào câu trên, từ “fur” có nghĩa phù hợp nhất là gì?', '["nguyên liệu; thành phần (nấu ăn)","lông thú; bộ lông","làm bẹp dí; ép chặt vào không gian chật hẹp","bình phục; khôi phục (sức khỏe, trạng thái)"]'::jsonb, 1, 'fur: lông thú; bộ lông; da thú có lông. Dịch cả câu: Bộ lông dày giúp nhiều loài động vật có vú sinh tồn trong khí hậu lạnh giá bằng cách giữ lại một lớp không khí ấm.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_22', 'en-b1-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kim cương; hột xoàn”', '["split","easy-going","diamond","rather"]'::jsonb, 2, 'kim cương; hột xoàn → diamond (/ˈdaɪəmənd/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_23', 'en-b1-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ẩm ướt; nồm ẩm; ẩm thấp”', '["humid","positive","ashtray","economics"]'::jsonb, 0, 'ẩm ướt; nồm ẩm; ẩm thấp → humid (/ˈhjuːmɪd/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_17_24', 'en-b1-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “con cáo (loài thú hoang dã có tai nhọn và đuôi rậm)”', '["fox","uncertain","loudspeaker","spread"]'::jsonb, 0, 'con cáo (loài thú hoang dã có tai nhọn và đuôi rậm) → fox (/fɑːks/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-18', 'en', 'Bài 18: Môi trường & Sinh thái - CEFR B1', 'CEFR B1', 'B1 · Môi trường', '22 từ vựng Tiếng Anh CEFR B1 chủ đề môi trường & sinh thái kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3018, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recycle', 'en-b1-18', 'recycle', '/ˌriːˈsaɪkəl/', 'B1', 'tái chế; xử lý chất liệu đã qua sử dụng để dùng lại', 'v.', 'recycling (n.), recyclable (adj.)', NULL, 'recycle chỉ việc xử lý để tái chế, trong khi reuse nhấn mạnh việc sử dụng lại trực tiếp.', 'We recycle glass bottles at the centre near our house.', NULL, 'Chúng tôi tái chế chai thủy tinh tại trung tâm gần nhà.', '{"wordId":"recycle","ukIpa":"/ˌriːˈsaɪkəl/","usIpa":"/ˌriːˈsaɪkəl/","cefr":"B1","topic":"environment","senses":[{"pos":"v.","en":"to process used materials so they can be used again","vi":"tái chế; xử lý chất liệu đã qua sử dụng để dùng lại"}],"examples":[{"en":"We recycle glass bottles at the centre near our house.","vi":"Chúng tôi tái chế chai thủy tinh tại trung tâm gần nhà.","audioKind":"ex"},{"en":"Cities can reduce landfill waste by making it easier for residents to recycle everyday packaging.","vi":"Các thành phố có thể giảm lượng rác thải chôn lấp bằng cách tạo điều kiện thuận lợi cho cư dân tái chế bao bì hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"recycle household waste","vi":"tái chế rác thải sinh hoạt"},{"en":"recycled paper","vi":"giấy tái chế"},{"en":"recycle plastic bottles","vi":"tái chế chai nhựa"}],"wordFamily":["recycling (n.)","recyclable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"recycle chỉ việc xử lý để tái chế, trong khi reuse nhấn mạnh việc sử dụng lại trực tiếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_environmental', 'en-b1-18', 'environmental', '/ɪnˌvaɪrənˈmentəl/', 'B1', 'thuộc về môi trường tự nhiên; liên quan đến bảo vệ môi trường; thuộc về môi trường xung quanh', 'adj.', 'environment (n.), environmentally (adv.), environmentalist (n.)', NULL, 'environmental là tính từ, còn danh từ chỉ môi trường là environment.', 'Our school organised an environmental project to clean the river.', NULL, 'Trường chúng tôi đã tổ chức một dự án bảo vệ môi trường để làm sạch dòng sông.', '{"wordId":"environmental","ukIpa":"/ɪnˌvaɪrənˈmentəl/","usIpa":"/ɪnˌvaɪrənˈmentəl/","cefr":"B1","topic":"environment","senses":[{"pos":"adj.","en":"relating to nature or efforts to protect it","vi":"thuộc về môi trường tự nhiên; liên quan đến bảo vệ môi trường"},{"pos":"adj.","en":"relating to the surroundings in which people or organisms live","vi":"thuộc về môi trường xung quanh"}],"examples":[{"en":"Our school organised an environmental project to clean the river.","vi":"Trường chúng tôi đã tổ chức một dự án bảo vệ môi trường để làm sạch dòng sông.","audioKind":"ex"},{"en":"Governments should consider the environmental impact of new roads before approving major construction projects.","vi":"Chính phủ nên xem xét tác động môi trường của các con đường mới trước khi phê duyệt các dự án xây dựng lớn.","audioKind":"ex2"}],"collocations":[{"en":"environmental protection","vi":"bảo vệ môi trường"},{"en":"environmental impact","vi":"tác động môi trường"},{"en":"environmental factors","vi":"các yếu tố môi trường"},{"en":"environmental damage","vi":"tổn hại môi trường"}],"wordFamily":["environment (n.)","environmentally (adv.)","environmentalist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"environmental là tính từ, còn danh từ chỉ môi trường là environment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soil', 'en-b1-18', 'soil', '/sɔɪl/', 'B1', 'đất; đất trồng; làm bẩn; làm vấy bẩn', 'n.', 'soiled (adj.), soilless (adj.)', NULL, 'Danh từ đất thường không đếm được; các loại đất khác nhau có thể dùng dạng số nhiều soils.', 'She filled the pot with soil and planted seeds.', NULL, 'Cô ấy xúc đất đầy vào chậu rồi gieo hạt giống xuống.', '{"wordId":"soil","ukIpa":"/sɔɪl/","usIpa":"/sɔɪl/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"The earth in which plants grow.","vi":"đất; đất trồng"},{"pos":"v.","en":"To make something dirty.","vi":"làm bẩn; làm vấy bẩn"}],"examples":[{"en":"She filled the pot with soil and planted seeds.","vi":"Cô ấy xúc đất đầy vào chậu rồi gieo hạt giống xuống.","audioKind":"ex"},{"en":"Intensive farming can damage soil quality, reducing the land''s ability to support crops over time.","vi":"Canh tác thâm canh có thể làm tổn hại chất lượng đất, làm giảm dần khả năng nuôi trồng cây lương thực của đất theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"fertile soil","vi":"đất màu mỡ"},{"en":"soil erosion","vi":"xói mòn đất"},{"en":"soil quality","vi":"chất lượng đất"},{"en":"soil your clothes","vi":"làm bẩn quần áo"}],"wordFamily":["soiled (adj.)","soilless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đất thường không đếm được; các loại đất khác nhau có thể dùng dạng số nhiều soils.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pollution', 'en-b1-18', 'pollution', '/pəˈluːʃən/', 'B1', 'sự ô nhiễm', 'n.', 'pollute (v.), pollutant (n.), polluted (adj.)', 'Đồng nghĩa: contamination', 'pollution không đếm được; chất gây ô nhiễm cụ thể dùng pollutant.', 'Air pollution makes the distant hills difficult to see.', NULL, 'Ô nhiễm không khí khiến cho những ngọn đồi ở xa trở nên khó nhìn rõ.', '{"wordId":"pollution","ukIpa":"/pəˈluːʃən/","usIpa":"/pəˈluːʃən/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"damage to the environment caused by harmful substances or energy","vi":"sự ô nhiễm"}],"examples":[{"en":"Air pollution makes the distant hills difficult to see.","vi":"Ô nhiễm không khí khiến cho những ngọn đồi ở xa trở nên khó nhìn rõ.","audioKind":"ex"},{"en":"Reducing pollution requires governments to regulate industrial emissions while encouraging cleaner transport and more sustainable production methods.","vi":"Việc giảm thiểu ô nhiễm đòi hỏi chính phủ phải quản lý chặt chẽ lượng khí thải công nghiệp, đồng thời khuyến khích các phương tiện giao thông sạch hơn và các phương thức sản xuất bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"air pollution","vi":"ô nhiễm không khí"},{"en":"water pollution","vi":"ô nhiễm nguồn nước"},{"en":"noise pollution","vi":"ô nhiễm tiếng ồn"},{"en":"reduce pollution","vi":"giảm thiểu ô nhiễm"}],"wordFamily":["pollute (v.)","pollutant (n.)","polluted (adj.)"],"synonyms":["contamination"],"antonyms":[],"tipVi":"pollution không đếm được; chất gây ô nhiễm cụ thể dùng pollutant.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_protection', 'en-b1-18', 'protection', '/prəˈtekʃən/', 'B1', 'sự bảo vệ; sự che chở', 'n.', 'protect (v.), protective (adj.), protector (n.)', 'Đồng nghĩa: defence, safeguarding', 'Thường là danh từ không đếm được; protection from/against diễn tả việc tránh khỏi tổn hại.', 'This thick coat offers protection against the cold wind.', NULL, 'Chiếc áo khoác dày này giúp chống lại những cơn gió lạnh.', '{"wordId":"protection","ukIpa":"/prəˈtekʃən/","usIpa":"/prəˈtekʃən/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"the act of keeping someone or something safe from harm","vi":"sự bảo vệ; sự che chở"}],"examples":[{"en":"This thick coat offers protection against the cold wind.","vi":"Chiếc áo khoác dày này giúp chống lại những cơn gió lạnh.","audioKind":"ex"},{"en":"Stronger environmental laws are essential for the protection of endangered species and their natural habitats.","vi":"Các luật môi trường nghiêm ngặt hơn là điều cốt yếu để bảo vệ các loài có nguy cơ tuyệt chủng và môi trường sống tự nhiên của chúng.","audioKind":"ex2"}],"collocations":[{"en":"protection against","vi":"bảo vệ chống lại"},{"en":"environmental protection","vi":"bảo vệ môi trường"},{"en":"provide protection","vi":"cung cấp sự bảo vệ"}],"wordFamily":["protect (v.)","protective (adj.)","protector (n.)"],"synonyms":["defence","safeguarding"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; protection from/against diễn tả việc tránh khỏi tổn hại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hurricane', 'en-b1-18', 'hurricane', '/ˈhɝːɪkeɪn/', 'B1', 'bão cuồng phong; bão lớn vùng nhiệt đới', 'n.', NULL, 'Đồng nghĩa: tropical cyclone', 'Hurricane và typhoon đều là xoáy thuận nhiệt đới, tên gọi thay đổi tùy theo vùng biển.', 'We stayed indoors as the hurricane approached the coast.', NULL, 'Chúng tôi ở trong nhà khi cơn bão cuồng phong tiến sát bờ biển.', '{"wordId":"hurricane","ukIpa":"/ˈhʌrɪkən/","usIpa":"/ˈhɝːɪkeɪn/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"a powerful tropical storm with extremely strong winds","vi":"bão cuồng phong; bão lớn vùng nhiệt đới"}],"examples":[{"en":"We stayed indoors as the hurricane approached the coast.","vi":"Chúng tôi ở trong nhà khi cơn bão cuồng phong tiến sát bờ biển.","audioKind":"ex"},{"en":"Coastal cities need stronger flood defences and reliable warning systems to protect residents when a hurricane approaches.","vi":"Các thành phố ven biển cần có các công trình phòng chống lũ lụt kiên cố hơn và hệ thống cảnh báo đáng tin cậy để bảo vệ cư dân khi có bão cuồng phong.","audioKind":"ex2"}],"collocations":[{"en":"powerful hurricane","vi":"bão cuồng phong mạnh"},{"en":"hurricane season","vi":"mùa bão"},{"en":"hurricane warning","vi":"cảnh báo bão cuồng phong"},{"en":"hurricane damage","vi":"thiệt hại do bão cuồng phong"}],"wordFamily":[],"synonyms":["tropical cyclone"],"antonyms":[],"tipVi":"Hurricane và typhoon đều là xoáy thuận nhiệt đới, tên gọi thay đổi tùy theo vùng biển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fuel', 'en-b1-18', 'fuel', '/ˈfjuːəl/', 'B1', 'nhiên liệu; cung cấp nhiên liệu; làm gia tăng; thúc đẩy', 'n.', 'fuelling (n.), biofuel (n.)', NULL, 'fuel khi làm động từ còn có nghĩa là kích động cảm xúc hoặc đẩy mạnh sự thay đổi.', 'We stopped for fuel before driving into the mountains.', NULL, 'Chúng tôi tạt vào nạp nhiên liệu trước khi lái xe lên núi.', '{"wordId":"fuel","ukIpa":"/ˈfjuːəl/","usIpa":"/ˈfjuːəl/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"material burned or used to produce heat or power","vi":"nhiên liệu"},{"pos":"v.","en":"to supply something with fuel","vi":"cung cấp nhiên liệu"},{"pos":"v.","en":"to make a feeling or situation stronger","vi":"làm gia tăng; thúc đẩy"}],"examples":[{"en":"We stopped for fuel before driving into the mountains.","vi":"Chúng tôi tạt vào nạp nhiên liệu trước khi lái xe lên núi.","audioKind":"ex"},{"en":"Growing demand for private cars may fuel air pollution unless governments promote cleaner alternatives.","vi":"Nhu cầu gia tăng đối với xe ô tô cá nhân có thể làm gia tăng tình trạng ô nhiễm không khí trừ khi chính phủ thúc đẩy các phương tiện thay thế sạch hơn.","audioKind":"ex2"}],"collocations":[{"en":"fossil fuels","vi":"nhiên liệu hóa thạch"},{"en":"fuel consumption","vi":"tiêu thụ nhiên liệu"},{"en":"fuel prices","vi":"giá nhiên liệu"},{"en":"fuel speculation","vi":"thổi phồng suy đoán"}],"wordFamily":["fuelling (n.)","biofuel (n.)"],"synonyms":[],"antonyms":[],"tipVi":"fuel khi làm động từ còn có nghĩa là kích động cảm xúc hoặc đẩy mạnh sự thay đổi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recycled', 'en-b1-18', 'recycled', '/ˌriːˈsaɪkəld/', 'B1', 'tái chế; tái tạo', 'adj.', 'recycle (v.), recycling (n.), recyclable (adj.)', NULL, 'recycled chỉ vật liệu đã được thu gom và tái chế; recyclable chỉ vật liệu có thể tái chế được.', 'This notebook is made entirely from recycled paper.', NULL, 'Cuốn sổ tay này được làm hoàn toàn từ giấy tái chế.', '{"wordId":"recycled","ukIpa":"/ˌriːˈsaɪkəld/","usIpa":"/ˌriːˈsaɪkəld/","cefr":"B1","topic":"environment","senses":[{"pos":"adj.","en":"made from waste materials processed for use again","vi":"tái chế; tái tạo"}],"examples":[{"en":"This notebook is made entirely from recycled paper.","vi":"Cuốn sổ tay này được làm hoàn toàn từ giấy tái chế.","audioKind":"ex"},{"en":"Using recycled materials in construction can reduce demand for natural resources and limit waste sent to landfill.","vi":"Sử dụng vật liệu tái chế trong xây dựng có thể làm giảm nhu cầu về tài nguyên thiên nhiên và hạn chế lượng rác thải đưa đến bãi chôn lấp.","audioKind":"ex2"}],"collocations":[{"en":"recycled paper","vi":"giấy tái chế"},{"en":"recycled plastic","vi":"nhựa tái chế"},{"en":"recycled materials","vi":"vật liệu tái chế"}],"wordFamily":["recycle (v.)","recycling (n.)","recyclable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"recycled chỉ vật liệu đã được thu gom và tái chế; recyclable chỉ vật liệu có thể tái chế được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reduce', 'en-b1-18', 'reduce', '/rɪˈduːs/', 'B1', 'giảm, làm giảm, thu nhỏ', 'v.', 'reduction (n.), reduced (adj.)', 'Đồng nghĩa: decrease, lessen · Trái nghĩa: increase, raise', 'reduce by đi với khoảng giảm; reduce to đi với mức độ hoặc kết quả sau khi giảm.', 'We can reduce waste by using our leftovers.', NULL, 'Chúng ta có thể giảm lượng rác thải bằng cách tận dụng đồ ăn thừa.', '{"wordId":"reduce","ukIpa":"/rɪˈdjuːs/","usIpa":"/rɪˈduːs/","cefr":"B1","topic":"environment","senses":[{"pos":"v.","en":"To make something smaller or less in amount or degree.","vi":"giảm, làm giảm, thu nhỏ"}],"examples":[{"en":"We can reduce waste by using our leftovers.","vi":"Chúng ta có thể giảm lượng rác thải bằng cách tận dụng đồ ăn thừa.","audioKind":"ex"},{"en":"Governments should invest in renewable energy to reduce carbon emissions and improve long-term energy security.","vi":"Chính phủ nên đầu tư vào năng lượng tái tạo để giảm lượng khí thải carbon và cải thiện an ninh năng lượng lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"reduce costs","vi":"giảm chi phí"},{"en":"reduce emissions","vi":"giảm lượng khí thải"},{"en":"reduce the risk","vi":"giảm thiểu rủi ro"},{"en":"reduce waste","vi":"giảm lãng phí"}],"wordFamily":["reduction (n.)","reduced (adj.)"],"synonyms":["decrease","lessen"],"antonyms":["increase","raise"],"tipVi":"reduce by đi với khoảng giảm; reduce to đi với mức độ hoặc kết quả sau khi giảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coal', 'en-b1-18', 'coal', '/koʊl/', 'B1', 'than đá', 'n.', NULL, NULL, 'coal chỉ than, charcoal chỉ wood; than thường dùng như danh từ không đếm được.', 'The old stove still burns coal during winter.', NULL, 'Lò sưởi cũ vẫn đốt than vào mùa đông.', '{"wordId":"coal","ukIpa":"/kəʊl/","usIpa":"/koʊl/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"A hard black or brown material burned to produce heat.","vi":"than đá"}],"examples":[{"en":"The old stove still burns coal during winter.","vi":"Lò sưởi cũ vẫn đốt than vào mùa đông.","audioKind":"ex"},{"en":"Replacing coal with renewable energy can reduce air pollution and lower greenhouse gas emissions from electricity generation.","vi":"Việc thay thế than đá bằng năng lượng tái tạo có thể làm giảm ô nhiễm không khí và hạ thấp lượng khí thải nhà kính từ việc phát điện.","audioKind":"ex2"}],"collocations":[{"en":"coal mine","vi":"mỏ than"},{"en":"burn coal","vi":"đốt than"},{"en":"coal-fired power station","vi":"trạm iện chạy bằng than"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"coal chỉ than, charcoal chỉ wood; than thường dùng như danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_damage', 'en-b1-18', 'damage', '/ˈdæmɪdʒ/', 'B1', 'sự thiệt hại; sự hư hại; làm hư hỏng; làm thiệt hại', 'n.', 'damaged (adj.), damaging (adj.)', 'Đồng nghĩa: harm', 'damage dùng ở dạng không đếm được để chỉ sự hư hại; damages chỉ tiền bồi thường thiệt hại theo pháp luật.', 'The storm caused serious damage to our garden shed.', NULL, 'Cơn bão đã gây ra thiệt hại nghiêm trọng cho nhà kho trong vườn của chúng tôi.', '{"wordId":"damage","ukIpa":"/ˈdæmɪdʒ/","usIpa":"/ˈdæmɪdʒ/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"Harm that makes something less useful, valuable, or healthy.","vi":"sự thiệt hại; sự hư hại"},{"pos":"v.","en":"Harm something or make it less effective.","vi":"làm hư hỏng; làm thiệt hại"}],"examples":[{"en":"The storm caused serious damage to our garden shed.","vi":"Cơn bão đã gây ra thiệt hại nghiêm trọng cho nhà kho trong vườn của chúng tôi.","audioKind":"ex"},{"en":"Uncontrolled tourism can damage fragile ecosystems and reduce the quality of life for local residents.","vi":"Du lịch không kiểm soát có thể tàn phá các hệ sinh thái mỏng manh và làm giảm chất lượng cuộc sống của người dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"cause damage","vi":"gây thiệt hại"},{"en":"damage to property","vi":"thiệt hại về tài sản"},{"en":"environmental damage","vi":"tổn hại môi trường"},{"en":"damage someone''s reputation","vi":"tổn hại danh tiếng của ai đó"}],"wordFamily":["damaged (adj.)","damaging (adj.)"],"synonyms":["harm"],"antonyms":[],"tipVi":"damage dùng ở dạng không đếm được để chỉ sự hư hại; damages chỉ tiền bồi thường thiệt hại theo pháp luật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_litter', 'en-b1-18', 'litter', '/ˈlɪtər/', 'B1', 'rác bừa bãi nơi công cộng; xả rác bừa bãi; một ổ (chó, mèo con v.v.)', 'n.', 'littering (n.)', 'Đồng nghĩa: rubbish, trash', 'Litter as rubbish is uncountable; a litter of is used for animal offspring.', 'We picked up litter along the beach before lunch.', NULL, 'Chúng tôi đã nhặt rác dọc theo bờ biển trước bữa trưa.', '{"wordId":"litter","ukIpa":"/ˈlɪtə/","usIpa":"/ˈlɪtər/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"Waste left scattered in public places.","vi":"rác bừa bãi nơi công cộng"},{"pos":"v.","en":"To leave rubbish or other objects scattered across a place.","vi":"xả rác bừa bãi"},{"pos":"n.","en":"A group of young animals born to one mother together.","vi":"một ổ (chó, mèo con v.v.)"}],"examples":[{"en":"We picked up litter along the beach before lunch.","vi":"Chúng tôi đã nhặt rác dọc theo bờ biển trước bữa trưa.","audioKind":"ex"},{"en":"Reducing litter in urban parks requires convenient bins as well as sustained public education campaigns.","vi":"Việc giảm thiểu rác thải ở các công viên đô thị đòi hỏi phải có các thùng rác tiện lợi cũng như các chiến dịch giáo dục công cộng liên tục.","audioKind":"ex2"}],"collocations":[{"en":"drop litter","vi":"vứt rác bừa bãi"},{"en":"pick up litter","vi":"nhặt rác"},{"en":"a litter of puppies","vi":"một ổ chó con"}],"wordFamily":["littering (n.)"],"synonyms":["rubbish","trash"],"antonyms":[],"tipVi":"Litter as rubbish is uncountable; a litter of is used for animal offspring.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pollute', 'en-b1-18', 'pollute', '/pəˈluːt/', 'B1', 'làm ô nhiễm', 'v.', 'pollution (n.), pollutant (n.), polluter (n.), polluted (adj.)', 'Đồng nghĩa: contaminate · Trái nghĩa: purify', 'Transitive verb, takes the polluted object directly without a preposition.', 'Please don''t pollute the stream by throwing rubbish into it.', NULL, 'Xin đừng làm ô nhiễm dòng suối bằng cách vứt rác xuống đó.', '{"wordId":"pollute","ukIpa":"/pəˈluːt/","usIpa":"/pəˈluːt/","cefr":"B1","topic":"environment","senses":[{"pos":"v.","en":"to make air, water, or land dirty or harmful","vi":"làm ô nhiễm"}],"examples":[{"en":"Please don''t pollute the stream by throwing rubbish into it.","vi":"Xin đừng làm ô nhiễm dòng suối bằng cách vứt rác xuống đó.","audioKind":"ex"},{"en":"Factories that pollute local rivers should face stricter penalties to protect ecosystems and public health.","vi":"Các nhà máy làm ô nhiễm các con sông địa phương phải đối mặt với các hình phạt nghiêm khắc hơn để bảo vệ hệ sinh thái và sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"pollute the environment","vi":"ô nhiễm môi trường"},{"en":"pollute the air","vi":"làm ô nhiễm không khí"},{"en":"heavily polluted","vi":"bị ô nhiễm nặng"}],"wordFamily":["pollution (n.)","pollutant (n.)","polluter (n.)","polluted (adj.)"],"synonyms":["contaminate"],"antonyms":["purify"],"tipVi":"Transitive verb, takes the polluted object directly without a preposition.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_resource', 'en-b1-18', 'resource', '/ˈriːsɔːrs/', 'B1', 'tài nguyên; nguồn lực; tài liệu; nguồn tài nguyên học tập; cung cấp nguồn lực cho...', 'n.', 'resourceful (adj.), resourcefulness (n.), resourcing (n.)', NULL, 'Danh từ chỉ tài nguyên thường dùng dạng số nhiều resources; động từ mang nghĩa cung cấp nguồn lực.', 'Our village shares its water resources during dry summers.', NULL, 'Làng chúng tôi chia sẻ nguồn nước trong những mùa hè hạn hán.', '{"wordId":"resource","ukIpa":"/rɪˈzɔːs/","usIpa":"/ˈriːsɔːrs/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"Something useful that people or organisations can draw on.","vi":"tài nguyên; nguồn lực"},{"pos":"n.","en":"Material that provides information or support for learning.","vi":"tài liệu; nguồn tài nguyên học tập"},{"pos":"v.","en":"To supply an organisation or activity with necessary support.","vi":"cung cấp nguồn lực cho..."}],"examples":[{"en":"Our village shares its water resources during dry summers.","vi":"Làng chúng tôi chia sẻ nguồn nước trong những mùa hè hạn hán.","audioKind":"ex"},{"en":"Governments should manage natural resources carefully to balance economic development with long-term environmental protection.","vi":"Các chính phủ nên quản lý cẩn thận các nguồn tài nguyên thiên nhiên để cân bằng giữa phát triển kinh tế và bảo vệ môi trường lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"natural resources","vi":"tài nguyên thiên nhiên"},{"en":"human resources","vi":"nguồn nhân lực"},{"en":"learning resources","vi":"tài nguyên học tập"},{"en":"allocate resources","vi":"phân bổ nguồn lực"}],"wordFamily":["resourceful (adj.)","resourcefulness (n.)","resourcing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ tài nguyên thường dùng dạng số nhiều resources; động từ mang nghĩa cung cấp nguồn lực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rainforest', 'en-b1-18', 'rainforest', '/ˈreɪnfɔːrɪst/', 'B1', 'rừng mưa nhiệt đới; rừng mưa', 'n.', NULL, NULL, 'Thường viết liền thành rainforest; viết tách thành rain forest cũng hoàn toàn chính xác.', 'We spotted colourful birds high in the rainforest canopy.', NULL, 'Chúng tôi đã phát hiện ra những chú chim sặc sỡ trên tầng tán cao của khu rừng mưa.', '{"wordId":"rainforest","ukIpa":"/ˈreɪnfɒrɪst/","usIpa":"/ˈreɪnfɔːrɪst/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"a dense forest in an area receiving very heavy rainfall","vi":"rừng mưa nhiệt đới; rừng mưa"}],"examples":[{"en":"We spotted colourful birds high in the rainforest canopy.","vi":"Chúng tôi đã phát hiện ra những chú chim sặc sỡ trên tầng tán cao của khu rừng mưa.","audioKind":"ex"},{"en":"Protecting tropical rainforest helps preserve biodiversity and prevents large amounts of stored carbon from entering the atmosphere.","vi":"Bảo vệ rừng mưa nhiệt đới giúp duy trì sự đa dạng sinh học và ngăn chặn một lượng lớn lượng carbon được lưu trữ thải vào bầu khí quyển.","audioKind":"ex2"}],"collocations":[{"en":"tropical rainforest","vi":"rừng mưa nhiệt đới"},{"en":"rainforest canopy","vi":"tầng tán rừng mưa"},{"en":"rainforest conservation","vi":"bảo tồn rừng mưa"},{"en":"rainforest destruction","vi":"sự hủy diệt rừng mưa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường viết liền thành rainforest; viết tách thành rain forest cũng hoàn toàn chính xác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recycling', 'en-b1-18', 'recycling', '/ˌriːˈsaɪklɪŋ/', 'B1', 'sự tái chế; việc tái chế; vật liệu tái chế', 'n.', 'recycle (v.), recycled (adj.), recyclable (adj.)', NULL, 'thường không đếm được; chỉ hoạt động tái chế hoặc vật liệu chờ tái chế.', 'Our building has separate bins for recycling and food waste.', NULL, 'Tòa nhà của chúng tôi có các thùng riêng biệt dành cho đồ tái chế và rác thải thực phẩm.', '{"wordId":"recycling","ukIpa":"/ˌriːˈsaɪklɪŋ/","usIpa":"/ˌriːˈsaɪklɪŋ/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"the process of turning waste into materials usable again","vi":"sự tái chế; việc tái chế"},{"pos":"n.","en":"waste materials collected to be processed and used again","vi":"vật liệu tái chế"}],"examples":[{"en":"Our building has separate bins for recycling and food waste.","vi":"Tòa nhà của chúng tôi có các thùng riêng biệt dành cho đồ tái chế và rác thải thực phẩm.","audioKind":"ex"},{"en":"Effective recycling programmes require convenient collection services as well as clear public guidance on sorting household waste.","vi":"Các chương trình tái chế hiệu quả đòi hỏi dịch vụ thu gom thuận tiện cũng như hướng dẫn rõ ràng cho công chúng về cách phân loại rác thải sinh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"recycling centre","vi":"trung tâm tái chế"},{"en":"recycling bin","vi":"thùng đựng đồ tái chế"},{"en":"recycling scheme","vi":"chương trình tái chế"},{"en":"household recycling","vi":"tái chế hộ gia đình"}],"wordFamily":["recycle (v.)","recycled (adj.)","recyclable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"thường không đếm được; chỉ hoạt động tái chế hoặc vật liệu chờ tái chế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_global', 'en-b1-18', 'global', '/ˈɡloʊbəl/', 'B1', 'toàn cầu; mang tính thế giới; toàn diện; tổng thể', 'adj.', 'globe (n.), globally (adv.), globalisation (n.), globalise (v.)', 'Đồng nghĩa: worldwide · Trái nghĩa: local', 'global nhấn mạnh phạm vi toàn cầu; international nhấn mạnh giữa các quốc gia với nhau.', 'Our teacher showed us a map of global temperatures.', NULL, 'Giáo viên đã cho chúng tôi xem bản đồ nhiệt độ toàn cầu.', '{"wordId":"global","ukIpa":"/ˈɡləʊbəl/","usIpa":"/ˈɡloʊbəl/","cefr":"B1","topic":"environment","senses":[{"pos":"adj.","en":"Involving or affecting the whole world.","vi":"toàn cầu; mang tính thế giới"},{"pos":"adj.","en":"Considering all parts of something rather than individual details.","vi":"toàn diện; tổng thể"}],"examples":[{"en":"Our teacher showed us a map of global temperatures.","vi":"Giáo viên đã cho chúng tôi xem bản đồ nhiệt độ toàn cầu.","audioKind":"ex"},{"en":"Global cooperation is essential for tackling climate change because environmental damage rarely respects national borders.","vi":"Hợp tác toàn cầu là điều cốt yếu để giải quyết biến đổi khí hậu vì tổn hại môi trường hiếm khi bị giới hạn bởi biên giới quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"global warming","vi":"hiện tượng nóng lên toàn cầu"},{"en":"global economy","vi":"kinh tế toàn cầu"},{"en":"global cooperation","vi":"hợp tác toàn cầu"},{"en":"global perspective","vi":"tầm nhìn toàn cầu"}],"wordFamily":["globe (n.)","globally (adv.)","globalisation (n.)","globalise (v.)"],"synonyms":["worldwide"],"antonyms":["local"],"tipVi":"global nhấn mạnh phạm vi toàn cầu; international nhấn mạnh giữa các quốc gia với nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_climate', 'en-b1-18', 'climate', '/ˈklaɪmət/', 'B1', 'khí hậu; môi trường xã hội; bầu không khí; phong trào', 'n.', 'climatic (adj.), climatology (n.)', NULL, 'climate dùng để chỉ khí hậu dài hạn, trong khi weather chỉ thời tiết cụ thể.', 'These plants grow well in a warm, dry climate.', NULL, 'Những loài cây này phát triển tốt ở vùng khí hậu ấm áp và khô ráo.', '{"wordId":"climate","ukIpa":"/ˈklaɪmət/","usIpa":"/ˈklaɪmət/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"The typical weather conditions of a place over many years.","vi":"khí hậu"},{"pos":"n.","en":"The general attitudes and conditions within a society or organisation.","vi":"môi trường xã hội; bầu không khí; phong trào"}],"examples":[{"en":"These plants grow well in a warm, dry climate.","vi":"Những loài cây này phát triển tốt ở vùng khí hậu ấm áp và khô ráo.","audioKind":"ex"},{"en":"A changing climate may force farmers to grow different crops and adopt more efficient irrigation methods.","vi":"Biến đổi khí hậu có thể buộc nông dân phải chuyển sang trồng các loại cây trồng khác và áp dụng các phương pháp tưới tiêu hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"climate change","vi":"biến đổi khí hậu"},{"en":"mild climate","vi":"khí hậu ôn hòa"},{"en":"political climate","vi":"bối cảnh chính trị"}],"wordFamily":["climatic (adj.)","climatology (n.)"],"synonyms":[],"antonyms":[],"tipVi":"climate dùng để chỉ khí hậu dài hạn, trong khi weather chỉ thời tiết cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disaster', 'en-b1-18', 'disaster', '/dɪˈzæstər/', 'B1', 'thảm họa; tai họa gây tổn thất lớn; sự thất bại hoàn toàn', 'n.', 'disastrous (adj.), disastrously (adv.)', 'Đồng nghĩa: catastrophe, calamity', 'Có thể dùng một cách cường điệu để diễn tả sự thất bại: "The party was a disaster".', 'Dinner was a disaster because I burned the rice.', NULL, 'Bữa tối là một thảm họa vì tôi đã làm cháy cơm.', '{"wordId":"disaster","ukIpa":"/dɪˈzɑːstə/","usIpa":"/dɪˈzæstər/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"An event causing great damage, suffering, or loss.","vi":"thảm họa; tai họa gây tổn thất lớn"},{"pos":"n.","en":"Something that goes extremely badly or fails completely.","vi":"thảm họa; sự thất bại hoàn toàn"}],"examples":[{"en":"Dinner was a disaster because I burned the rice.","vi":"Bữa tối là một thảm họa vì tôi đã làm cháy cơm.","audioKind":"ex"},{"en":"Effective early warning systems can reduce the damage caused by natural disasters and help communities recover more quickly.","vi":"Hệ thống cảnh báo sớm hiệu quả có thể giảm thiểu thiệt hại do thiên tai gây ra và giúp cộng đồng phục hồi nhanh hơn.","audioKind":"ex2"}],"collocations":[{"en":"natural disaster","vi":"thảm họa thiên nhiên"},{"en":"disaster relief","vi":"cứu trợ thảm họa"},{"en":"avert disaster","vi":"ngăn chặn thảm họa"},{"en":"a complete disaster","vi":"một sự thất bại hoàn toàn"}],"wordFamily":["disastrous (adj.)","disastrously (adv.)"],"synonyms":["catastrophe","calamity"],"antonyms":[],"tipVi":"Có thể dùng một cách cường điệu để diễn tả sự thất bại: \"The party was a disaster\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crop', 'en-b1-18', 'crop', '/krɑːp/', 'B1', 'cây trồng; hoa màu; vụ mùa; sản lượng thu hoạch trong một mùa; cắt ngắn; xén bớt (tóc hoặc ảnh)', 'n.', NULL, NULL, 'crop vừa chỉ cây trồng vừa chỉ sản lượng thu hoạch; ở dạng động từ còn có nghĩa là cắt xén ảnh.', 'The farmer checked his wheat crop after the storm.', NULL, 'Người nông dân kiểm tra ruộng lúa mì của mình sau trận bão.', '{"wordId":"crop","ukIpa":"/krɒp/","usIpa":"/krɑːp/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"a plant grown in large quantities for food or other uses","vi":"cây trồng; hoa màu"},{"pos":"n.","en":"the amount of a plant harvested at one time","vi":"vụ mùa; sản lượng thu hoạch trong một mùa"},{"pos":"v.","en":"to remove outer parts of an image or cut hair short","vi":"cắt ngắn; xén bớt (tóc hoặc ảnh)"}],"examples":[{"en":"The farmer checked his wheat crop after the storm.","vi":"Người nông dân kiểm tra ruộng lúa mì của mình sau trận bão.","audioKind":"ex"},{"en":"Rising temperatures may reduce crop yields, threatening food security in regions that already experience water shortages.","vi":"Nhiệt độ tăng cao có thể làm giảm năng suất cây trồng, đe dọa an ninh lương thực ở những vùng vốn đã thiếu nước.","audioKind":"ex2"}],"collocations":[{"en":"grow crops","vi":"trồng trọt"},{"en":"crop yields","vi":"năng suất cây trồng"},{"en":"a bumper crop","vi":"vụ mùa bội thu"},{"en":"crop a photo","vi":"cắt xén ảnh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"crop vừa chỉ cây trồng vừa chỉ sản lượng thu hoạch; ở dạng động từ còn có nghĩa là cắt xén ảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_farming', 'en-b1-18', 'farming', '/ˈfɑːrmɪŋ/', 'B1', 'nông nghiệp; việc canh tác và chăn nuôi', 'n.', 'farm (n.), farm (v.), farmer (n.)', 'Đồng nghĩa: agriculture', 'Chỉ ngành nông nghiệp chung thường không đếm được; việc chăn nuôi cũng có thể dùng farming.', 'My grandparents earn their living from sheep farming.', NULL, 'Ông bà tôi kiếm sống bằng nghề nuôi cừu.', '{"wordId":"farming","ukIpa":"/ˈfɑːmɪŋ/","usIpa":"/ˈfɑːrmɪŋ/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"Growing crops or raising animals for food and other products","vi":"nông nghiệp; việc canh tác và chăn nuôi"}],"examples":[{"en":"My grandparents earn their living from sheep farming.","vi":"Ông bà tôi kiếm sống bằng nghề nuôi cừu.","audioKind":"ex"},{"en":"Sustainable farming can protect soil quality while providing enough food for a growing population.","vi":"Nông nghiệp bền vững có thể bảo vệ chất lượng đất đồng thời cung cấp đủ lương thực cho dân số đang gia tăng.","audioKind":"ex2"}],"collocations":[{"en":"organic farming","vi":"nông nghiệp hữu cơ"},{"en":"dairy farming","vi":"chăn nuôi bò sữa"},{"en":"intensive farming","vi":"nông nghiệp thâm canh"},{"en":"sustainable farming","vi":"nông nghiệp bền vững"}],"wordFamily":["farm (n.)","farm (v.)","farmer (n.)"],"synonyms":["agriculture"],"antonyms":[],"tipVi":"Chỉ ngành nông nghiệp chung thường không đếm được; việc chăn nuôi cũng có thể dùng farming.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flood', 'en-b1-18', 'flood', '/flʌd/', 'B1', 'lũ lụt; nạn hồng thủy (nước tràn ngập vùng đất vốn khô ráo); làm ngập; ngập lụt (tràn ngập nước); sự tràn ngập; lượng lớn (một lượng lớn người hoặc sự việc kéo đến cùng lúc)', 'n.', 'flooding (n.), flooded (adj.)', NULL, 'Cách phát âm vần của flood giống với blood, không vần với food.', 'The flood left our garden covered in thick mud.', NULL, 'Trận lụt đã khiến khu vườn nhà chúng tôi phủ đầy bùn dày.', '{"wordId":"flood","ukIpa":"/flʌd/","usIpa":"/flʌd/","cefr":"B1","topic":"environment","senses":[{"pos":"n.","en":"Water covering land that is normally dry.","vi":"lũ lụt; nạn hồng thủy (nước tràn ngập vùng đất vốn khô ráo)"},{"pos":"v.","en":"To cover with water or become covered with water.","vi":"làm ngập; ngập lụt (tràn ngập nước)"},{"pos":"n.","en":"A large amount of something arriving at once.","vi":"sự tràn ngập; lượng lớn (một lượng lớn người hoặc sự việc kéo đến cùng lúc)"}],"examples":[{"en":"The flood left our garden covered in thick mud.","vi":"Trận lụt đã khiến khu vườn nhà chúng tôi phủ đầy bùn dày.","audioKind":"ex"},{"en":"Restoring wetlands can reduce flood risks by allowing excess rainwater to spread and drain naturally.","vi":"Việc phục hồi các vùng đất ngập nước có thể làm giảm nguy cơ lũ lụt bằng cách cho phép lượng nước mưa dư thừa lan tỏa và thoát tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"flash flood","vi":"lũ quét"},{"en":"flood defences","vi":"hệ thống phòng chống lũ"},{"en":"flood damage","vi":"thiệt hại do lũ lụt"},{"en":"a flood of complaints","vi":"lượng lớn đơn khiếu nại"}],"wordFamily":["flooding (n.)","flooded (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách phát âm vần của flood giống với blood, không vần với food.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_18_1', 'en-b1-18', 'Cách dùng “damage” (n.) — sự thiệt hại; sự hư hại', 'cause damage  ·  damage to property  ·  environmental damage', 'damage dùng ở dạng không đếm được để chỉ sự hư hại; damages chỉ tiền bồi thường thiệt hại theo pháp luật.', 'Họ từ (Word Family): damaged (adj.), damaging (adj.) | Đồng nghĩa: harm', '[{"hanzi":"The storm caused serious damage to our garden shed.","pinyin":"","meaning":"Cơn bão đã gây ra thiệt hại nghiêm trọng cho nhà kho trong vườn của chúng tôi."},{"hanzi":"Uncontrolled tourism can damage fragile ecosystems and reduce the quality of life for local residents.","pinyin":"","meaning":"Du lịch không kiểm soát có thể tàn phá các hệ sinh thái mỏng manh và làm giảm chất lượng cuộc sống của người dân địa phương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_18_2', 'en-b1-18', 'Cách dùng “resource” (n.) — tài nguyên; nguồn lực', 'natural resources  ·  human resources  ·  learning resources', 'Danh từ chỉ tài nguyên thường dùng dạng số nhiều resources; động từ mang nghĩa cung cấp nguồn lực.', 'Họ từ (Word Family): resourceful (adj.), resourcefulness (n.), resourcing (n.)', '[{"hanzi":"Our village shares its water resources during dry summers.","pinyin":"","meaning":"Làng chúng tôi chia sẻ nguồn nước trong những mùa hè hạn hán."},{"hanzi":"Governments should manage natural resources carefully to balance economic development with long-term environmental protection.","pinyin":"","meaning":"Các chính phủ nên quản lý cẩn thận các nguồn tài nguyên thiên nhiên để cân bằng giữa phát triển kinh tế và bảo vệ môi trường lâu dài."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_18_3', 'en-b1-18', 'Cách dùng “crop” (n.) — cây trồng; hoa màu', 'grow crops  ·  crop yields  ·  a bumper crop', 'crop vừa chỉ cây trồng vừa chỉ sản lượng thu hoạch; ở dạng động từ còn có nghĩa là cắt xén ảnh.', NULL, '[{"hanzi":"The farmer checked his wheat crop after the storm.","pinyin":"","meaning":"Người nông dân kiểm tra ruộng lúa mì của mình sau trận bão."},{"hanzi":"Rising temperatures may reduce crop yields, threatening food security in regions that already experience water shortages.","pinyin":"","meaning":"Nhiệt độ tăng cao có thể làm giảm năng suất cây trồng, đe dọa an ninh lương thực ở những vùng vốn đã thiếu nước."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_18_4', 'en-b1-18', 'Cách dùng “recycled” (adj.) — tái chế; tái tạo', 'recycled paper  ·  recycled plastic  ·  recycled materials', 'recycled chỉ vật liệu đã được thu gom và tái chế; recyclable chỉ vật liệu có thể tái chế được.', 'Họ từ (Word Family): recycle (v.), recycling (n.), recyclable (adj.)', '[{"hanzi":"This notebook is made entirely from recycled paper.","pinyin":"","meaning":"Cuốn sổ tay này được làm hoàn toàn từ giấy tái chế."},{"hanzi":"Using recycled materials in construction can reduce demand for natural resources and limit waste sent to landfill.","pinyin":"","meaning":"Sử dụng vật liệu tái chế trong xây dựng có thể làm giảm nhu cầu về tài nguyên thiên nhiên và hạn chế lượng rác thải đưa đến bãi chôn lấp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_18_1', 'en-b1-18', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_1_1', 'ten_b1_18_1', 'recycle', 'We recycle glass bottles at the centre near our house.', 'We recycle glass bottles at the centre near our house.', '/ˌriːˈsaɪkəl/', 'Chúng tôi tái chế chai thủy tinh tại trung tâm gần nhà.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_1_2', 'ten_b1_18_1', 'environmental', 'Our school organised an environmental project to clean the river.', 'Our school organised an environmental project to clean the river.', '/ɪnˌvaɪrənˈmentəl/', 'Trường chúng tôi đã tổ chức một dự án bảo vệ môi trường để làm sạch dòng sông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_1_3', 'ten_b1_18_1', 'soil', 'She filled the pot with soil and planted seeds.', 'She filled the pot with soil and planted seeds.', '/sɔɪl/', 'Cô ấy xúc đất đầy vào chậu rồi gieo hạt giống xuống.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_1_4', 'ten_b1_18_1', 'pollution', 'Air pollution makes the distant hills difficult to see.', 'Air pollution makes the distant hills difficult to see.', '/pəˈluːʃən/', 'Ô nhiễm không khí khiến cho những ngọn đồi ở xa trở nên khó nhìn rõ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_1_5', 'ten_b1_18_1', 'protection', 'This thick coat offers protection against the cold wind.', 'This thick coat offers protection against the cold wind.', '/prəˈtekʃən/', 'Chiếc áo khoác dày này giúp chống lại những cơn gió lạnh.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_1_6', 'ten_b1_18_1', 'hurricane', 'We stayed indoors as the hurricane approached the coast.', 'We stayed indoors as the hurricane approached the coast.', '/ˈhɝːɪkeɪn/', 'Chúng tôi ở trong nhà khi cơn bão cuồng phong tiến sát bờ biển.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_1_7', 'ten_b1_18_1', 'fuel', 'We stopped for fuel before driving into the mountains.', 'We stopped for fuel before driving into the mountains.', '/ˈfjuːəl/', 'Chúng tôi tạt vào nạp nhiên liệu trước khi lái xe lên núi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_1_8', 'ten_b1_18_1', 'recycled', 'This notebook is made entirely from recycled paper.', 'This notebook is made entirely from recycled paper.', '/ˌriːˈsaɪkəld/', 'Cuốn sổ tay này được làm hoàn toàn từ giấy tái chế.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_18_1_1', 'en-b1-18', 'ten_b1_18_1', 'listening', 'listening', 'We recycle glass bottles at the centre near our house.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy xúc đất đầy vào chậu rồi gieo hạt giống xuống.","Trận lụt đã khiến khu vườn nhà chúng tôi phủ đầy bùn dày.","Ông bà tôi kiếm sống bằng nghề nuôi cừu.","Chúng tôi tái chế chai thủy tinh tại trung tâm gần nhà."]'::jsonb, 3, 'We recycle glass bottles at the centre near our house. → Chúng tôi tái chế chai thủy tinh tại trung tâm gần nhà.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_18_1_2', 'en-b1-18', 'ten_b1_18_1', 'listening', 'listening', 'Our school organised an environmental project to clean the river.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Trận lụt đã khiến khu vườn nhà chúng tôi phủ đầy bùn dày.","Trường chúng tôi đã tổ chức một dự án bảo vệ môi trường để làm sạch dòng sông.","Cơn bão đã gây ra thiệt hại nghiêm trọng cho nhà kho trong vườn của chúng tôi.","Tòa nhà của chúng tôi có các thùng riêng biệt dành cho đồ tái chế và rác thải thực phẩm."]'::jsonb, 1, 'Our school organised an environmental project to clean the river. → Trường chúng tôi đã tổ chức một dự án bảo vệ môi trường để làm sạch dòng sông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_18_1_3', 'en-b1-18', 'ten_b1_18_1', 'listening', 'listening', 'She filled the pot with soil and planted seeds.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy xúc đất đầy vào chậu rồi gieo hạt giống xuống.","Bữa tối là một thảm họa vì tôi đã làm cháy cơm.","Chúng ta có thể giảm lượng rác thải bằng cách tận dụng đồ ăn thừa.","Làng chúng tôi chia sẻ nguồn nước trong những mùa hè hạn hán."]'::jsonb, 0, 'She filled the pot with soil and planted seeds. → Cô ấy xúc đất đầy vào chậu rồi gieo hạt giống xuống.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_18_2', 'en-b1-18', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_2_1', 'ten_b1_18_2', 'recycle', 'Cities can reduce landfill waste by making it easier for residents to recycle everyday packaging.', 'Cities can reduce landfill waste by making it easier for residents to recycle everyday packaging.', '/ˌriːˈsaɪkəl/', 'Các thành phố có thể giảm lượng rác thải chôn lấp bằng cách tạo điều kiện thuận lợi cho cư dân tái chế bao bì hàng ngày.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_2_2', 'ten_b1_18_2', 'environmental', 'Governments should consider the environmental impact of new roads before approving major construction projects.', 'Governments should consider the environmental impact of new roads before approving major construction projects.', '/ɪnˌvaɪrənˈmentəl/', 'Chính phủ nên xem xét tác động môi trường của các con đường mới trước khi phê duyệt các dự án xây dựng lớn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_2_3', 'ten_b1_18_2', 'soil', 'Intensive farming can damage soil quality, reducing the land''s ability to support crops over time.', 'Intensive farming can damage soil quality, reducing the land''s ability to support crops over time.', '/sɔɪl/', 'Canh tác thâm canh có thể làm tổn hại chất lượng đất, làm giảm dần khả năng nuôi trồng cây lương thực của đất theo thời gian.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_2_4', 'ten_b1_18_2', 'pollution', 'Reducing pollution requires governments to regulate industrial emissions while encouraging cleaner transport and more sustainable production methods.', 'Reducing pollution requires governments to regulate industrial emissions while encouraging cleaner transport and more sustainable production methods.', '/pəˈluːʃən/', 'Việc giảm thiểu ô nhiễm đòi hỏi chính phủ phải quản lý chặt chẽ lượng khí thải công nghiệp, đồng thời khuyến khích các phương tiện giao thông sạch hơn và các phương thức sản xuất bền vững hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_2_5', 'ten_b1_18_2', 'protection', 'Stronger environmental laws are essential for the protection of endangered species and their natural habitats.', 'Stronger environmental laws are essential for the protection of endangered species and their natural habitats.', '/prəˈtekʃən/', 'Các luật môi trường nghiêm ngặt hơn là điều cốt yếu để bảo vệ các loài có nguy cơ tuyệt chủng và môi trường sống tự nhiên của chúng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_18_2_6', 'ten_b1_18_2', 'hurricane', 'Coastal cities need stronger flood defences and reliable warning systems to protect residents when a hurricane approaches.', 'Coastal cities need stronger flood defences and reliable warning systems to protect residents when a hurricane approaches.', '/ˈhɝːɪkeɪn/', 'Các thành phố ven biển cần có các công trình phòng chống lũ lụt kiên cố hơn và hệ thống cảnh báo đáng tin cậy để bảo vệ cư dân khi có bão cuồng phong.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_18_2_1', 'en-b1-18', 'ten_b1_18_2', 'listening', 'listening', 'Cities can reduce landfill waste by making it easier for residents to recycle everyday packaging.', NULL, 'Trong câu vừa nghe, từ “recycle” mang nghĩa nào sau đây?', '["thường ngày; giản dị; không trang trọng","cô dâu","hoàn toàn; tuyệt đối","tái chế; xử lý chất liệu đã qua sử dụng để dùng lại"]'::jsonb, 3, '“recycle” (/ˌriːˈsaɪkəl/): tái chế; xử lý chất liệu đã qua sử dụng để dùng lại. Câu đầy đủ: Cities can reduce landfill waste by making it easier for residents to recycle everyday packaging.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_18_2_2', 'en-b1-18', 'ten_b1_18_2', 'listening', 'listening', 'Governments should consider the environmental impact of new roads before approving major construction projects.', NULL, 'Trong câu vừa nghe, từ “environmental” mang nghĩa nào sau đây?', '["thuộc về môi trường tự nhiên; liên quan đến bảo vệ môi trường","thị thực; visa","bình tĩnh; điềm tĩnh","lời phát biểu; ý kiến"]'::jsonb, 0, '“environmental” (/ɪnˌvaɪrənˈmentəl/): thuộc về môi trường tự nhiên; liên quan đến bảo vệ môi trường. Câu đầy đủ: Governments should consider the environmental impact of new roads before approving major construction projects.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
