INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_18_4', 'en-b1-18', 'Air pollution makes the distant hills difficult to see', 'Ô nhiễm không khí khiến cho những ngọn đồi ở xa trở nên khó nhìn rõ.', 'pollution /pəˈluːʃən/', '["distant","pollution","Air","difficult","makes","hills","the","to","see"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
