INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_18_6', 'en-b1-18', 'We stayed indoors as the hurricane approached the coast', 'Chúng tôi ở trong nhà khi cơn bão cuồng phong tiến sát bờ biển.', 'hurricane /ˈhɝːɪkeɪn/', '["stayed","We","the","hurricane","as","approached","coast","the","indoors"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_18_7', 'en-b1-18', 'We stopped for fuel before driving into the mountains', 'Chúng tôi tạt vào nạp nhiên liệu trước khi lái xe lên núi.', 'fuel /ˈfjuːəl/', '["stopped","into","for","driving","mountains","the","fuel","before","We"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_18_8', 'en-b1-18', 'This notebook is made entirely from recycled paper', 'Cuốn sổ tay này được làm hoàn toàn từ giấy tái chế.', 'recycled /ˌriːˈsaɪkəld/', '["made","paper","is","recycled","from","notebook","This","entirely"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
