INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_1', 'en-b1-18', NULL, 'comprehensive_test', 'listening', 'recycle', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["inh-sơ (đơn vị đo chiều dài bằng 2,54 cm)","bị cấm; không được phép","tái chế; xử lý chất liệu đã qua sử dụng để dùng lại","bột mì; bột ngũ cốc"]'::jsonb, 2, 'recycle (/ˌriːˈsaɪkəl/) → tái chế; xử lý chất liệu đã qua sử dụng để dùng lại', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_2', 'en-b1-18', NULL, 'comprehensive_test', 'listening', 'Our school organised an environmental project to clean the river.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Trường chúng tôi đã tổ chức một dự án bảo vệ môi trường để làm sạch dòng sông.","Trận lụt đã khiến khu vườn nhà chúng tôi phủ đầy bùn dày.","Chiếc áo khoác dày này giúp chống lại những cơn gió lạnh.","Lò sưởi cũ vẫn đốt than vào mùa đông."]'::jsonb, 0, 'Our school organised an environmental project to clean the river. → Trường chúng tôi đã tổ chức một dự án bảo vệ môi trường để làm sạch dòng sông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_3', 'en-b1-18', NULL, 'comprehensive_test', 'listening', 'soil', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đất; đất trồng","thể lực; sức lực","gần đây; dạo này","chính thức; thuộc về cơ quan nhà nước"]'::jsonb, 0, 'soil (/sɔɪl/) → đất; đất trồng; làm bẩn; làm vấy bẩn', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_4', 'en-b1-18', NULL, 'comprehensive_test', 'listening', 'Air pollution makes the distant hills difficult to see.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuốn sổ tay này được làm hoàn toàn từ giấy tái chế.","Ô nhiễm không khí khiến cho những ngọn đồi ở xa trở nên khó nhìn rõ.","Tòa nhà của chúng tôi có các thùng riêng biệt dành cho đồ tái chế và rác thải thực phẩm.","Những loài cây này phát triển tốt ở vùng khí hậu ấm áp và khô ráo."]'::jsonb, 1, 'Air pollution makes the distant hills difficult to see. → Ô nhiễm không khí khiến cho những ngọn đồi ở xa trở nên khó nhìn rõ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_5', 'en-b1-18', NULL, 'comprehensive_test', 'listening', 'protection', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nguyên âm; chữ cái nguyên âm","chùa; đền thờ; đền","chảy máu; ra máu","sự bảo vệ; sự che chở"]'::jsonb, 3, 'protection (/prəˈtekʃən/) → sự bảo vệ; sự che chở', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_6', 'en-b1-18', NULL, 'comprehensive_test', 'listening', 'We stayed indoors as the hurricane approached the coast.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cơn bão đã gây ra thiệt hại nghiêm trọng cho nhà kho trong vườn của chúng tôi.","Những loài cây này phát triển tốt ở vùng khí hậu ấm áp và khô ráo.","Cô ấy xúc đất đầy vào chậu rồi gieo hạt giống xuống.","Chúng tôi ở trong nhà khi cơn bão cuồng phong tiến sát bờ biển."]'::jsonb, 3, 'We stayed indoors as the hurricane approached the coast. → Chúng tôi ở trong nhà khi cơn bão cuồng phong tiến sát bờ biển.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_7', 'en-b1-18', NULL, 'comprehensive_test', 'listening', 'fuel', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["người biên tập; chủ biên","nhiên liệu","gia súc; đàn bò","khí hậu"]'::jsonb, 1, 'fuel (/ˈfjuːəl/) → nhiên liệu; cung cấp nhiên liệu; làm gia tăng; thúc đẩy', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_8', 'en-b1-18', NULL, 'comprehensive_test', 'listening', 'This notebook is made entirely from recycled paper.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuốn sổ tay này được làm hoàn toàn từ giấy tái chế.","Cô ấy xúc đất đầy vào chậu rồi gieo hạt giống xuống.","Trận lụt đã khiến khu vườn nhà chúng tôi phủ đầy bùn dày.","Chúng tôi tạt vào nạp nhiên liệu trước khi lái xe lên núi."]'::jsonb, 0, 'This notebook is made entirely from recycled paper. → Cuốn sổ tay này được làm hoàn toàn từ giấy tái chế.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_9', 'en-b1-18', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the act of keeping someone or something safe from harm”?', '["litter","protection","disaster","coal"]'::jsonb, 1, 'protection (/prəˈtekʃən/) → sự bảo vệ; sự che chở', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_10', 'en-b1-18', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a powerful tropical storm with extremely strong winds”?', '["hurricane","litter","recycled","pollute"]'::jsonb, 0, 'hurricane (/ˈhɝːɪkeɪn/) → bão cuồng phong; bão lớn vùng nhiệt đới', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_11', 'en-b1-18', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “material burned or used to produce heat or power”?', '["rainforest","soil","recycling","fuel"]'::jsonb, 3, 'fuel (/ˈfjuːəl/) → nhiên liệu', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_12', 'en-b1-18', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “made from waste materials processed for use again”?', '["rainforest","global","recycled","resource"]'::jsonb, 2, 'recycled (/ˌriːˈsaɪkəld/) → tái chế; tái tạo', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
