INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_18', 'en-b1-18', NULL, 'comprehensive_test', 'reading', NULL, 'Cities can reduce landfill waste by making it easier for residents to recycle everyday packaging.', 'Dựa vào câu trên, từ “recycle” có nghĩa phù hợp nhất là gì?', '["móc treo quần áo","tái chế; xử lý chất liệu đã qua sử dụng để dùng lại","có vị đắng; đắng","tên ngốc; kẻ đần độn"]'::jsonb, 1, 'recycle: tái chế; xử lý chất liệu đã qua sử dụng để dùng lại. Dịch cả câu: Các thành phố có thể giảm lượng rác thải chôn lấp bằng cách tạo điều kiện thuận lợi cho cư dân tái chế bao bì hàng ngày.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_19', 'en-b1-18', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should consider the environmental impact of new roads before approving major construction projects.', 'Dựa vào câu trên, từ “environmental” có nghĩa phù hợp nhất là gì?', '["nhân viên; đội ngũ nhân viên","thuộc về môi trường tự nhiên; liên quan đến bảo vệ môi trường","ao; hồ nước nhỏ","nhẹ nhàng; dịu dàng"]'::jsonb, 1, 'environmental: thuộc về môi trường tự nhiên; liên quan đến bảo vệ môi trường; thuộc về môi trường xung quanh. Dịch cả câu: Chính phủ nên xem xét tác động môi trường của các con đường mới trước khi phê duyệt các dự án xây dựng lớn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_20', 'en-b1-18', NULL, 'comprehensive_test', 'reading', NULL, 'Intensive farming can damage soil quality, reducing the land''s ability to support crops over time.', 'Dựa vào câu trên, từ “soil” có nghĩa phù hợp nhất là gì?', '["lợi thế; ưu thế","khâu, may, vá","đất; đất trồng","tổ (chim, động vật)"]'::jsonb, 2, 'soil: đất; đất trồng; làm bẩn; làm vấy bẩn. Dịch cả câu: Canh tác thâm canh có thể làm tổn hại chất lượng đất, làm giảm dần khả năng nuôi trồng cây lương thực của đất theo thời gian.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_21', 'en-b1-18', NULL, 'comprehensive_test', 'reading', NULL, 'Reducing pollution requires governments to regulate industrial emissions while encouraging cleaner transport and more sustainable production methods.', 'Dựa vào câu trên, từ “pollution” có nghĩa phù hợp nhất là gì?', '["người đi xe đạp","bắn; nã đạn","sự ô nhiễm","thiên nga"]'::jsonb, 2, 'pollution: sự ô nhiễm. Dịch cả câu: Việc giảm thiểu ô nhiễm đòi hỏi chính phủ phải quản lý chặt chẽ lượng khí thải công nghiệp, đồng thời khuyến khích các phương tiện giao thông sạch hơn và các phương thức sản xuất bền vững hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_22', 'en-b1-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cây trồng; hoa màu”', '["gorgeous","export","detective","crop"]'::jsonb, 3, 'cây trồng; hoa màu → crop (/krɑːp/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_23', 'en-b1-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nông nghiệp; việc canh tác và chăn nuôi”', '["particular","caring","wing","farming"]'::jsonb, 3, 'nông nghiệp; việc canh tác và chăn nuôi → farming (/ˈfɑːrmɪŋ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_18_24', 'en-b1-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lũ lụt; nạn hồng thủy (nước tràn ngập vùng đất vốn khô ráo)”', '["turning","row","silent","flood"]'::jsonb, 3, 'lũ lụt; nạn hồng thủy (nước tràn ngập vùng đất vốn khô ráo) → flood (/flʌd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-19', 'en', 'Bài 19: Sức khỏe & Cơ thể (1) - CEFR B1', 'CEFR B1', 'B1 · Sức khỏe', '22 từ vựng Tiếng Anh CEFR B1 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3019, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mild', 'en-b1-19', 'mild', '/maɪld/', 'B1', 'nhẹ; không nặng (triệu chứng, ảnh hưởng); ôn hòa; dễ chịu (thời tiết); nhạt; không cay (hương vị)', 'adj.', 'mildly (adv.), mildness (n.)', 'Đồng nghĩa: slight, gentle · Trái nghĩa: severe, harsh', 'Từ mild có thể dùng để mô tả triệu chứng, thời tiết và hương vị, nhưng không đồng nghĩa với "vô hại".', 'I have a mild headache, so I''ll rest briefly.', NULL, 'Tôi bị đau đầu nhẹ nên sẽ nghỉ ngơi một lát.', '{"wordId":"mild","ukIpa":"/maɪld/","usIpa":"/maɪld/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"Not severe or strong in effect","vi":"nhẹ; không nặng (triệu chứng, ảnh hưởng)"},{"pos":"adj.","en":"Pleasantly warm rather than cold","vi":"ôn hòa; dễ chịu (thời tiết)"},{"pos":"adj.","en":"Not strong or spicy in flavour","vi":"nhạt; không cay (hương vị)"}],"examples":[{"en":"I have a mild headache, so I''ll rest briefly.","vi":"Tôi bị đau đầu nhẹ nên sẽ nghỉ ngơi một lát.","audioKind":"ex"},{"en":"Even mild air pollution can affect vulnerable groups, making regular monitoring essential in densely populated cities.","vi":"Ngay cả tình trạng ô nhiễm không khí nhẹ cũng có thể ảnh hưởng đến các nhóm dễ bị tổn thương, khiến việc theo dõi thường xuyên ở các thành phố đông dân trở nên vô cùng thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"mild symptoms","vi":"triệu chứng nhẹ"},{"en":"mild weather","vi":"thời tiết ôn hòa"},{"en":"mild flavour","vi":"hương vị thanh nhạt"},{"en":"mild headache","vi":"chứng đau đầu nhẹ"}],"wordFamily":["mildly (adv.)","mildness (n.)"],"synonyms":["slight","gentle"],"antonyms":["severe","harsh"],"tipVi":"Từ mild có thể dùng để mô tả triệu chứng, thời tiết và hương vị, nhưng không đồng nghĩa với \"vô hại\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fitness', 'en-b1-19', 'fitness', '/ˈfɪtnəs/', 'B1', 'thể lực; thể chất; sự thích hợp; năng lực đáp ứng', 'n.', 'fit (adj.), unfit (adj.)', NULL, 'Là danh từ không đếm được; fitness for dùng để chỉ mức độ thích hợp cho việc gì đó.', 'Swimming every morning has really improved my fitness.', NULL, 'Việc bơi lội mỗi buổi sáng đã thực sự cải thiện thể lực của tôi.', '{"wordId":"fitness","ukIpa":"/ˈfɪtnəs/","usIpa":"/ˈfɪtnəs/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"The condition of being physically healthy and strong.","vi":"thể lực; thể chất"},{"pos":"n.","en":"The quality of being suitable for a task or purpose.","vi":"sự thích hợp; năng lực đáp ứng"}],"examples":[{"en":"Swimming every morning has really improved my fitness.","vi":"Việc bơi lội mỗi buổi sáng đã thực sự cải thiện thể lực của tôi.","audioKind":"ex"},{"en":"Schools can improve children''s fitness by providing regular opportunities for enjoyable physical activity throughout the week.","vi":"Các trường học có thể nâng cao thể lực cho học sinh bằng cách tạo cơ hội tham gia các hoạt động thể chất thú vị đều đặn suốt tuần.","audioKind":"ex2"}],"collocations":[{"en":"physical fitness","vi":"thể lực; thể chất"},{"en":"fitness level","vi":"mức độ thể lực"},{"en":"fitness for work","vi":"năng lực làm việc"},{"en":"fitness centre","vi":"trung tâm thể hình"}],"wordFamily":["fit (adj.)","unfit (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; fitness for dùng để chỉ mức độ thích hợp cho việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suncream', 'en-b1-19', 'suncream', '/ˈsʌnkriːm/', 'B1', 'kem chống nắng', 'n.', NULL, 'Đồng nghĩa: sunscreen', 'Chủ yếu dùng trong tiếng Anh-Anh, cũng thường viết là sun cream.', 'I packed suncream and a hat for our afternoon walk.', NULL, 'Tôi đã mang theo kem chống nắng và một chiếc mũ cho buổi đi dạo buổi chiều.', '{"wordId":"suncream","ukIpa":"/ˈsʌnkriːm/","usIpa":"/ˈsʌnkriːm/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A cream that protects skin from the sun''s harmful rays.","vi":"kem chống nắng"}],"examples":[{"en":"I packed suncream and a hat for our afternoon walk.","vi":"Tôi đã mang theo kem chống nắng và một chiếc mũ cho buổi đi dạo buổi chiều.","audioKind":"ex"},{"en":"Schools can encourage children to use suncream and seek shade during outdoor activities in sunny weather.","vi":"Nhà trường có thể khuyến khích trẻ em bôi kem chống nắng và tìm nơi râm mát trong các hoạt động ngoài trời khi thời tiết có nắng.","audioKind":"ex2"}],"collocations":[{"en":"put on suncream","vi":"bôi kem chống nắng"},{"en":"a tube of suncream","vi":"một tuýp kem chống nắng"},{"en":"high-factor suncream","vi":"kem chống nắng chỉ số cao"}],"wordFamily":[],"synonyms":["sunscreen"],"antonyms":[],"tipVi":"Chủ yếu dùng trong tiếng Anh-Anh, cũng thường viết là sun cream.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_risk', 'en-b1-19', 'risk', '/rɪsk/', 'B1', 'rủi ro; nguy cơ; liều lĩnh làm gì; mạo hiểm', 'n.', 'risky (adj.)', 'Đồng nghĩa: danger · Trái nghĩa: safety', 'Từ risk đi theo sau bởi danh từ hoặc danh động từ (verb-ing), không đi với to do.', 'Wear sturdy shoes to reduce the risk of slipping.', NULL, 'Hãy đi giày đế bám chắc để giảm nguy cơ bị trượt ngã.', '{"wordId":"risk","ukIpa":"/rɪsk/","usIpa":"/rɪsk/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"the possibility that something harmful or unpleasant will happen","vi":"rủi ro; nguy cơ"},{"pos":"v.","en":"do something despite the possibility of harm or loss","vi":"liều lĩnh làm gì; mạo hiểm"}],"examples":[{"en":"Wear sturdy shoes to reduce the risk of slipping.","vi":"Hãy đi giày đế bám chắc để giảm nguy cơ bị trượt ngã.","audioKind":"ex"},{"en":"Governments should assess the risk of flooding before approving new housing developments near rivers.","vi":"Chính phủ nên đánh giá nguy cơ ngập lụt trước khi phê duyệt các dự án phát triển nhà ở mới gần sông ngòi.","audioKind":"ex2"}],"collocations":[{"en":"take a risk","vi":"liều lĩnh"},{"en":"at risk","vi":"gặp rủi ro"},{"en":"risk doing something","vi":"liều làm việc gì"},{"en":"reduce the risk","vi":"giảm thiểu rủi ro"}],"wordFamily":["risky (adj.)"],"synonyms":["danger"],"antonyms":["safety"],"tipVi":"Từ risk đi theo sau bởi danh từ hoặc danh động từ (verb-ing), không đi với to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tiredness', 'en-b1-19', 'tiredness', '/ˈtaɪərdnəs/', 'B1', 'sự mệt mỏi; sự uể oải', 'n.', 'tired (adj.), tiring (adj.), tire (v.)', 'Đồng nghĩa: fatigue, weariness', 'Thường là danh từ không đếm được; dùng ''tired'' để chỉ người mệt mỏi và ''tiring'' để chỉ sự việc gây mệt mỏi.', 'After the long walk, tiredness made my legs feel heavy.', NULL, 'Sau chuyến đi bộ dài, sự mệt mỏi khiến đôi chân tôi cảm thấy nặng trĩu.', '{"wordId":"tiredness","ukIpa":"/ˈtaɪədnəs/","usIpa":"/ˈtaɪərdnəs/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"the feeling of needing rest or sleep","vi":"sự mệt mỏi; sự uể oải"}],"examples":[{"en":"After the long walk, tiredness made my legs feel heavy.","vi":"Sau chuyến đi bộ dài, sự mệt mỏi khiến đôi chân tôi cảm thấy nặng trĩu.","audioKind":"ex"},{"en":"Persistent tiredness can reduce students'' concentration and may indicate that they are not getting enough sleep.","vi":"Tình trạng mệt mỏi kéo dài có thể làm giảm khả năng tập trung của học sinh và có thể cho thấy các em ngủ không đủ giấc.","audioKind":"ex2"}],"collocations":[{"en":"extreme tiredness","vi":"sự mệt mỏi cực độ"},{"en":"persistent tiredness","vi":"sự mệt mỏi kéo dài"},{"en":"signs of tiredness","vi":"dấu hiệu mệt mỏi"}],"wordFamily":["tired (adj.)","tiring (adj.)","tire (v.)"],"synonyms":["fatigue","weariness"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; dùng ''tired'' để chỉ người mệt mỏi và ''tiring'' để chỉ sự việc gây mệt mỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dizzy', 'en-b1-19', 'dizzy', '/ˈdɪzi/', 'B1', 'chóng mặt; hoa mắt', 'adj.', 'dizziness (n.), dizzily (adv.)', 'Đồng nghĩa: light-headed', 'Người làm chủ ngữ dùng feel dizzy; sự vật có thể làm cho ai đó chóng mặt (make someone dizzy).', 'I felt dizzy after spinning around with my little cousin.', NULL, 'Tôi cảm thấy chóng mặt sau khi quay vòng tròn cùng cậu em họ nhỏ tuổi.', '{"wordId":"dizzy","ukIpa":"/ˈdɪzi/","usIpa":"/ˈdɪzi/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"Feeling as if you or your surroundings are spinning.","vi":"chóng mặt; hoa mắt"}],"examples":[{"en":"I felt dizzy after spinning around with my little cousin.","vi":"Tôi cảm thấy chóng mặt sau khi quay vòng tròn cùng cậu em họ nhỏ tuổi.","audioKind":"ex"},{"en":"People who feel dizzy during exercise should stop immediately and seek medical advice if symptoms persist.","vi":"Những người cảm thấy chóng mặt khi tập thể dục nên dừng lại ngay lập tức và tìm sự tư vấn y tế nếu triệu chứng kéo dài.","audioKind":"ex2"}],"collocations":[{"en":"feel dizzy","vi":"cảm thấy chóng mặt"},{"en":"a dizzy spell","vi":"một cơn chóng mặt"},{"en":"make someone dizzy","vi":"làm ai đó chóng mặt"}],"wordFamily":["dizziness (n.)","dizzily (adv.)"],"synonyms":["light-headed"],"antonyms":[],"tipVi":"Người làm chủ ngữ dùng feel dizzy; sự vật có thể làm cho ai đó chóng mặt (make someone dizzy).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stress', 'en-b1-19', 'stress', '/stres/', 'B1', 'sự căng thẳng tinh thần; áp lực tinh thần; nhấn mạnh; làm nổi bật; trọng âm', 'n.', 'stressful (adj.), stressed (adj.)', 'Đồng nghĩa: strain, emphasise', 'Người cảm thấy áp lực dùng stressed; việc gây căng thẳng dùng stressful.', 'A short walk helps me deal with work stress.', NULL, 'Đi dạo một chút giúp tôi giải tỏa áp lực công việc.', '{"wordId":"stress","ukIpa":"/stres/","usIpa":"/stres/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"Mental strain caused by difficult situations or too many demands","vi":"sự căng thẳng tinh thần; áp lực tinh thần"},{"pos":"v.","en":"To give particular importance to something when speaking or writing","vi":"nhấn mạnh; làm nổi bật"},{"pos":"n.","en":"Extra force used when pronouncing a syllable or word","vi":"trọng âm"}],"examples":[{"en":"A short walk helps me deal with work stress.","vi":"Đi dạo một chút giúp tôi giải tỏa áp lực công việc.","audioKind":"ex"},{"en":"Schools should teach students practical strategies for managing stress during examinations and other demanding periods.","vi":"Các nhà trường nên dạy học sinh các chiến lược thiết thực để quản lý căng thẳng trong các kỳ thi và các giai đoạn đòi hỏi khắt khe khác.","audioKind":"ex2"}],"collocations":[{"en":"under stress","vi":"chịu áp lực"},{"en":"reduce stress","vi":"giảm bớt căng thẳng"},{"en":"stress the importance of","vi":"nhấn mạnh tầm quan trọng của"},{"en":"word stress","vi":"trọng âm từ"}],"wordFamily":["stressful (adj.)","stressed (adj.)"],"synonyms":["strain","emphasise"],"antonyms":[],"tipVi":"Người cảm thấy áp lực dùng stressed; việc gây căng thẳng dùng stressful.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prevent', 'en-b1-19', 'prevent', '/prɪˈvent/', 'B1', 'ngăn chặn; phòng ngừa; cản trở', 'v.', 'prevention (n.), preventive (adj.), preventable (adj.)', 'Đồng nghĩa: stop, avert', 'Sử dụng cấu trúc prevent sb from doing, không dùng prevent sb to do.', 'This tight lid will prevent the soup from spilling.', NULL, 'Chiếc nắp khít này sẽ ngăn không cho nước canh bị tràn ra ngoài.', '{"wordId":"prevent","ukIpa":"/prɪˈvent/","usIpa":"/prɪˈvent/","cefr":"B1","topic":"health","senses":[{"pos":"v.","en":"To stop something happening or someone doing something.","vi":"ngăn chặn; phòng ngừa; cản trở"}],"examples":[{"en":"This tight lid will prevent the soup from spilling.","vi":"Chiếc nắp khít này sẽ ngăn không cho nước canh bị tràn ra ngoài.","audioKind":"ex"},{"en":"Investing in early health education can help prevent chronic diseases and reduce future pressure on public healthcare services.","vi":"Việc đầu tư vào giáo dục sức khỏe từ sớm có thể giúp phòng ngừa các bệnh mạn tính và giảm bớt áp lực tương lai lên các dịch vụ y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"prevent accidents","vi":"ngăn ngừa tai nạn"},{"en":"prevent disease","vi":"phòng bệnh"},{"en":"prevent someone from doing","vi":"ngăn cản ai làm gì"}],"wordFamily":["prevention (n.)","preventive (adj.)","preventable (adj.)"],"synonyms":["stop","avert"],"antonyms":[],"tipVi":"Sử dụng cấu trúc prevent sb from doing, không dùng prevent sb to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cough', 'en-b1-19', 'cough', '/kɔːf/', 'B1', 'ho; cơn ho; tiếng ho', 'v.', NULL, NULL, 'Phần chữ gh ở đây phát âm là /f/; have a cough nghĩa là bị ho.', 'The dusty room made me cough several times.', NULL, 'Căn phòng đầy bụi khiến tôi ho liên tục vài lần.', '{"wordId":"cough","ukIpa":"/kɒf/","usIpa":"/kɔːf/","cefr":"B1","topic":"health","senses":[{"pos":"v.","en":"Force air suddenly from your throat with a rough sound.","vi":"ho"},{"pos":"n.","en":"The act or sound of coughing, or an illness causing it.","vi":"cơn ho; tiếng ho"}],"examples":[{"en":"The dusty room made me cough several times.","vi":"Căn phòng đầy bụi khiến tôi ho liên tục vài lần.","audioKind":"ex"},{"en":"People with a persistent cough should seek medical advice, particularly if symptoms interfere with sleep or daily activities.","vi":"Những người bị ho kéo dài nên đi khám bác sĩ, đặc biệt là khi các triệu chứng cản trở giấc ngủ hoặc hoạt động hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"a persistent cough","vi":"cơn ho kéo dài"},{"en":"a dry cough","vi":"ho khan"},{"en":"cough medicine","vi":"thuốc ho"},{"en":"cough up","vi":"ho ra"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Phần chữ gh ở đây phát âm là /f/; have a cough nghĩa là bị ho.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lifestyle', 'en-b1-19', 'lifestyle', '/ˈlaɪfstaɪl/', 'B1', 'lối sống; phong cách sống', 'n.', NULL, 'Đồng nghĩa: way of life', 'Đây là danh từ đếm được; thường dùng cụm lead a healthy lifestyle (có lối sống lành mạnh).', 'Cycling to work is part of her healthy lifestyle.', NULL, 'Đạp xe đi làm là một phần trong lối sống lành mạnh của cô ấy.', '{"wordId":"lifestyle","ukIpa":"/ˈlaɪfstaɪl/","usIpa":"/ˈlaɪfstaɪl/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"the habits and activities that shape how someone lives","vi":"lối sống; phong cách sống"}],"examples":[{"en":"Cycling to work is part of her healthy lifestyle.","vi":"Đạp xe đi làm là một phần trong lối sống lành mạnh của cô ấy.","audioKind":"ex"},{"en":"A sedentary lifestyle can increase health risks, particularly among people who spend long hours at desks.","vi":"Lối sống ít vận động có thể làm tăng rủi ro sức khỏe, đặc biệt đối với những người phải ngồi làm việc bàn giấy trong thời gian dài.","audioKind":"ex2"}],"collocations":[{"en":"healthy lifestyle","vi":"lối sống lành mạnh"},{"en":"sedentary lifestyle","vi":"lối sống ít vận động"},{"en":"lifestyle changes","vi":"những thay đổi trong lối sống"}],"wordFamily":[],"synonyms":["way of life"],"antonyms":[],"tipVi":"Đây là danh từ đếm được; thường dùng cụm lead a healthy lifestyle (có lối sống lành mạnh).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mental', 'en-b1-19', 'mental', '/ˈmentəl/', 'B1', 'thuộc tâm lý; thuộc tinh thần; thuộc tư duy; thuộc trí tuệ', 'adj.', 'mentally (adv.)', 'Đồng nghĩa: psychological · Trái nghĩa: physical', 'mental thiên về mặt tâm lý hoặc trí tuệ; trong văn nói, dùng để chỉ người khùng điên có thể gây xúc phạm.', 'A quiet walk helps me protect my mental health.', NULL, 'Một buổi đi dạo tĩnh lặng giúp tôi bảo vệ sức khỏe tinh thần của mình.', '{"wordId":"mental","ukIpa":"/ˈmentəl/","usIpa":"/ˈmentəl/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"Relating to the mind and emotional wellbeing.","vi":"thuộc tâm lý; thuộc tinh thần"},{"pos":"adj.","en":"Using thought rather than physical action or written calculation.","vi":"thuộc tư duy; thuộc trí tuệ"}],"examples":[{"en":"A quiet walk helps me protect my mental health.","vi":"Một buổi đi dạo tĩnh lặng giúp tôi bảo vệ sức khỏe tinh thần của mình.","audioKind":"ex"},{"en":"Employers should give mental wellbeing the same priority as physical safety when designing workplace policies.","vi":"Các nhà tuyển dụng nên đặt sức khỏe tâm lý ở mức ưu tiên tương đương với sự an toàn thể chất khi thiết kế chính sách nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"mental health","vi":"sức khỏe tâm thần"},{"en":"mental wellbeing","vi":"hạnh phúc tinh thần"},{"en":"mental arithmetic","vi":"tính nhẩm"},{"en":"mental effort","vi":"nỗ lực trí óc"}],"wordFamily":["mentally (adv.)"],"synonyms":["psychological"],"antonyms":["physical"],"tipVi":"mental thiên về mặt tâm lý hoặc trí tuệ; trong văn nói, dùng để chỉ người khùng điên có thể gây xúc phạm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drown', 'en-b1-19', 'drown', '/draʊn/', 'B1', 'chết đuối; nhấn chìm xuống nước; lấn át; át đi (âm thanh)', 'v.', 'drowning (n.)', NULL, 'drown chỉ việc chết đuối, không chỉ đơn thuần là rơi xuống nước; để át đi âm thanh thường đi kèm với out.', 'She nearly drowned when her boat overturned in the lake.', NULL, 'Cô ấy suýt chết đuối khi chiếc thuyền bị lật trên hồ.', '{"wordId":"drown","ukIpa":"/draʊn/","usIpa":"/draʊn/","cefr":"B1","topic":"health","senses":[{"pos":"v.","en":"To die, or cause death, by being unable to breathe underwater.","vi":"chết đuối; nhấn chìm xuống nước"},{"pos":"v.","en":"To cover a sound with a much louder sound.","vi":"lấn át; át đi (âm thanh)"}],"examples":[{"en":"She nearly drowned when her boat overturned in the lake.","vi":"Cô ấy suýt chết đuối khi chiếc thuyền bị lật trên hồ.","audioKind":"ex"},{"en":"Public safety campaigns can reduce the risk of children drowning by encouraging swimming lessons and adult supervision.","vi":"Các chiến dịch an toàn công cộng có thể làm giảm nguy cơ trẻ em bị đuối nước bằng cách khuyến khích các lớp học bơi và sự giám sát của người lớn.","audioKind":"ex2"}],"collocations":[{"en":"drown out a voice","vi":"át đi tiếng nói"},{"en":"nearly drown","vi":"suýt chết đuối"},{"en":"drown in paperwork","vi":"ngập chìm trong đống giấy tờ"}],"wordFamily":["drowning (n.)"],"synonyms":[],"antonyms":[],"tipVi":"drown chỉ việc chết đuối, không chỉ đơn thuần là rơi xuống nước; để át đi âm thanh thường đi kèm với out.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bandage', 'en-b1-19', 'bandage', '/ˈbændɪdʒ/', 'B1', 'băng gạc; băng cá nhân; băng bó', 'n.', NULL, NULL, 'Vừa là danh từ vừa là động từ; bandage a wound nghĩa là băng bó vết thương.', 'The nurse wrapped a clean bandage around my ankle.', NULL, 'Y tá quấn một dải băng sạch quanh mắt cá chân của tôi.', '{"wordId":"bandage","ukIpa":"/ˈbændɪdʒ/","usIpa":"/ˈbændɪdʒ/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A strip of material wrapped around an injury for protection.","vi":"băng gạc; băng cá nhân"},{"pos":"v.","en":"To wrap an injured body part in a bandage.","vi":"băng bó"}],"examples":[{"en":"The nurse wrapped a clean bandage around my ankle.","vi":"Y tá quấn một dải băng sạch quanh mắt cá chân của tôi.","audioKind":"ex"},{"en":"Basic first aid courses teach people how to apply a bandage safely before professional help arrives.","vi":"Các khóa học sơ cứu cơ bản dạy mọi người cách băng bó an toàn trước khi có sự trợ giúp chuyên nghiệp đến.","audioKind":"ex2"}],"collocations":[{"en":"apply a bandage","vi":"quấn băng gạc"},{"en":"change a bandage","vi":"thay băng"},{"en":"bandage a wound","vi":"băng bó vết thương"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Vừa là danh từ vừa là động từ; bandage a wound nghĩa là băng bó vết thương.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wheelchair', 'en-b1-19', 'wheelchair', '/ˈwiːltʃer/', 'B1', 'xe lăn', 'n.', NULL, NULL, 'hãy dùng a wheelchair user để diễn đạt tự nhiên, tránh dùng những từ mang tính áp đặt hay ràng buộc.', 'She rolled her wheelchair up the ramp into the library.', NULL, 'Cô ấy đẩy chiếc xe lăn lên lối đi dốc để vào thư viện.', '{"wordId":"wheelchair","ukIpa":"/ˈwiːltʃeə/","usIpa":"/ˈwiːltʃer/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A wheeled chair used by someone who has difficulty walking.","vi":"xe lăn"}],"examples":[{"en":"She rolled her wheelchair up the ramp into the library.","vi":"Cô ấy đẩy chiếc xe lăn lên lối đi dốc để vào thư viện.","audioKind":"ex"},{"en":"Public buildings should provide step-free entrances and spacious lifts so that wheelchair users can move around independently.","vi":"Các tòa nhà công cộng nên bố trí lối vào không có bậc thềm và thang máy rộng rãi để người sử dụng xe lăn có thể di chuyển một cách độc lập.","audioKind":"ex2"}],"collocations":[{"en":"wheelchair user","vi":"người sử dụng xe lăn"},{"en":"electric wheelchair","vi":"xe lăn điện"},{"en":"wheelchair access","vi":"lối đi cho xe lăn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"hãy dùng a wheelchair user để diễn đạt tự nhiên, tránh dùng những từ mang tính áp đặt hay ràng buộc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_depressed', 'en-b1-19', 'depressed', '/dɪˈprest/', 'B1', 'trầm cảm; chán nản, thất vọng; kém phát triển; ế ẩm, suy thoái', 'adj.', 'depress (v.), depression (n.), depressing (adj.)', 'Đồng nghĩa: dejected, downcast · Trái nghĩa: cheerful', 'depressed dùng để tả cảm xúc của con người; depressing dùng để tả sự việc gây chán nản.', 'He felt depressed after weeks of unsuccessful job hunting.', NULL, 'Anh ấy cảm thấy chán nản sau nhiều tuần xin việc không thành công.', '{"wordId":"depressed","ukIpa":"/dɪˈprest/","usIpa":"/dɪˈprest/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"very unhappy, sometimes persistently as part of a mental illness","vi":"trầm cảm; chán nản, thất vọng"},{"pos":"adj.","en":"having little economic activity or few opportunities","vi":"kém phát triển; ế ẩm, suy thoái"}],"examples":[{"en":"He felt depressed after weeks of unsuccessful job hunting.","vi":"Anh ấy cảm thấy chán nản sau nhiều tuần xin việc không thành công.","audioKind":"ex"},{"en":"Investment in public transport can connect economically depressed areas with employment opportunities and essential services.","vi":"Đầu tư vào giao thông công cộng có thể kết nối các khu vực kinh tế suy thoái với các cơ hội việc làm và dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"feel depressed","vi":"cảm thấy chán nản"},{"en":"severely depressed","vi":"bị trầm cảm nặng"},{"en":"economically depressed area","vi":"vùng kinh tế khó khăn"}],"wordFamily":["depress (v.)","depression (n.)","depressing (adj.)"],"synonyms":["dejected","downcast"],"antonyms":["cheerful"],"tipVi":"depressed dùng để tả cảm xúc của con người; depressing dùng để tả sự việc gây chán nản.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vegetarian', 'en-b1-19', 'vegetarian', '/ˌvedʒəˈteriən/', 'B1', 'người ăn chay; thuộc về ăn chay; không chứa thịt hoặc cá', 'n.', 'vegetarianism (n.)', NULL, 'vegetarian không ăn thịt và cá; vegan còn không ăn các sản phẩm từ động vật như trứng và sữa.', 'My sister became a vegetarian after learning to cook.', NULL, 'Chị tôi đã trở thành một người ăn chay sau khi học nấu ăn.', '{"wordId":"vegetarian","ukIpa":"/ˌvedʒɪˈteəriən/","usIpa":"/ˌvedʒəˈteriən/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A person who does not eat meat or fish.","vi":"người ăn chay"},{"pos":"adj.","en":"Containing no meat or fish, or following this diet.","vi":"thuộc về ăn chay; không chứa thịt hoặc cá"}],"examples":[{"en":"My sister became a vegetarian after learning to cook.","vi":"Chị tôi đã trở thành một người ăn chay sau khi học nấu ăn.","audioKind":"ex"},{"en":"Providing vegetarian meals in school canteens can accommodate different dietary preferences and reduce environmental impacts.","vi":"Việc cung cấp các bữa ăn chay trong căng tin trường học có thể đáp ứng các sở thích ăn uống khác nhau và giảm thiểu tác động đến môi trường.","audioKind":"ex2"}],"collocations":[{"en":"vegetarian diet","vi":"chế độ ăn chay"},{"en":"vegetarian option","vi":"lựa chọn món chay"},{"en":"become a vegetarian","vi":"trở thành người ăn chay"}],"wordFamily":["vegetarianism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"vegetarian không ăn thịt và cá; vegan còn không ăn các sản phẩm từ động vật như trứng và sữa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_throat', 'en-b1-19', 'throat', '/θroʊt/', 'B1', 'họng; cổ họng', 'n.', 'throaty (adj.)', NULL, 'Cụm từ ''đau họng'' dùng have a sore throat, chú ý mạo từ a.', 'My throat felt dry after talking all afternoon.', NULL, 'Cổ họng tôi cảm thấy khô rát sau khi nói chuyện cả buổi chiều.', '{"wordId":"throat","ukIpa":"/θrəʊt/","usIpa":"/θroʊt/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"the passage inside the neck through which air and food pass","vi":"họng; cổ họng"}],"examples":[{"en":"My throat felt dry after talking all afternoon.","vi":"Cổ họng tôi cảm thấy khô rát sau khi nói chuyện cả buổi chiều.","audioKind":"ex"},{"en":"Poor air quality can irritate the throat and worsen breathing problems, particularly among children and older adults.","vi":"Chất lượng không khí kém có thể gây kích ứng cổ họng và làm trầm trọng thêm các vấn đề về đường hô hấp, đặc biệt ở trẻ em và người cao tuổi.","audioKind":"ex2"}],"collocations":[{"en":"a sore throat","vi":"đau họng"},{"en":"clear your throat","vi":"hắng giọng"},{"en":"throat infection","vi":"nhiễm trùng họng"}],"wordFamily":["throaty (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ ''đau họng'' dùng have a sore throat, chú ý mạo từ a.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elbow', 'en-b1-19', 'elbow', '/ˈelboʊ/', 'B1', 'khuỷu tay; dùng khuỷu tay huých', 'n.', NULL, NULL, 'elbow khi là động từ thường chỉ hành động huých tay để chen lấn.', 'I knocked my elbow against the kitchen door.', NULL, 'Tôi bị khuỷu tay đập vào cửa bếp.', '{"wordId":"elbow","ukIpa":"/ˈelbəʊ/","usIpa":"/ˈelboʊ/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"the joint where your arm bends","vi":"khuỷu tay"},{"pos":"v.","en":"to push someone or something with your elbow","vi":"dùng khuỷu tay huých"}],"examples":[{"en":"I knocked my elbow against the kitchen door.","vi":"Tôi bị khuỷu tay đập vào cửa bếp.","audioKind":"ex"},{"en":"Passengers sometimes elbow their way onto crowded trains, making public transport uncomfortable for others.","vi":"Hành khách đôi khi dùng khuỷu tay chen lên những chuyến tàu đông đúc, khiến việc đi lại công cộng trở nên khó chịu đối với người khác.","audioKind":"ex2"}],"collocations":[{"en":"bend your elbow","vi":"gập khuỷu tay"},{"en":"rest your elbows on","vi":"tì khuỷu tay lên"},{"en":"elbow your way through","vi":"chen chúc đi qua bằng khuỷu tay"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"elbow khi là động từ thường chỉ hành động huých tay để chen lấn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_keep-fit', 'en-b1-19', 'keep-fit', '/ˌkiːp ˈfɪt/', 'B1', 'bài tập giữ gìn vóc dáng; thể dục giữ vóc dáng', 'n.', NULL, 'Đồng nghĩa: exercise', 'Chủ yếu dùng trong tiếng Anh-Anh; cụm từ chỉ hành động keep fit không có dấu gạch nối.', 'My aunt attends keep-fit classes at the community centre.', NULL, 'Dì tôi tham gia các lớp thể dục giữ vóc dáng tại trung tâm cộng đồng.', '{"wordId":"keep-fit","ukIpa":"/ˌkiːp ˈfɪt/","usIpa":"/ˌkiːp ˈfɪt/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"Physical exercises done to stay healthy and fit.","vi":"bài tập giữ gìn vóc dáng; thể dục giữ vóc dáng"}],"examples":[{"en":"My aunt attends keep-fit classes at the community centre.","vi":"Dì tôi tham gia các lớp thể dục giữ vóc dáng tại trung tâm cộng đồng.","audioKind":"ex"},{"en":"Affordable keep-fit classes can encourage older adults to exercise regularly and maintain social connections within their communities.","vi":"Các lớp tập thể dục giữ vóc dáng với chi phí phải chăng có thể khuyến khích người lớn tuổi tập luyện thường xuyên và duy trì kết nối xã hội trong cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"keep-fit classes","vi":"lớp tập thể dục giữ vóc dáng"},{"en":"keep-fit exercises","vi":"các bài tập giữ gìn vóc dáng"}],"wordFamily":[],"synonyms":["exercise"],"antonyms":[],"tipVi":"Chủ yếu dùng trong tiếng Anh-Anh; cụm từ chỉ hành động keep fit không có dấu gạch nối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sunburn', 'en-b1-19', 'sunburn', '/ˈsʌnbɜːrn/', 'B1', 'cháy nắng', 'n.', 'sunburned (adj.), sunburnt (adj.)', NULL, 'Tiếng Anh-Anh thường dùng get sunburn; tiếng Anh-Mỹ cũng thường dùng get a sunburn.', 'I got sunburn after spending all afternoon outside.', NULL, 'Tôi bị cháy nắng sau khi ở ngoài trời suốt cả buổi chiều.', '{"wordId":"sunburn","ukIpa":"/ˈsʌnbɜːn/","usIpa":"/ˈsʌnbɜːrn/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"red, painful skin caused by too much exposure to sunlight","vi":"cháy nắng"}],"examples":[{"en":"I got sunburn after spending all afternoon outside.","vi":"Tôi bị cháy nắng sau khi ở ngoài trời suốt cả buổi chiều.","audioKind":"ex"},{"en":"Public health campaigns should explain that preventing sunburn requires suitable clothing and shade as well as sunscreen.","vi":"Các chiến dịch y tế cộng đồng nên giải thích rằng việc phòng ngừa cháy nắng đòi hỏi phải mặc quần áo phù hợp, có chỗ râm mát cũng như dùng kem chống nắng.","audioKind":"ex2"}],"collocations":[{"en":"get sunburn","vi":"bị cháy nắng"},{"en":"severe sunburn","vi":"cháy nắng nặng"},{"en":"prevent sunburn","vi":"ngừa cháy nắng"}],"wordFamily":["sunburned (adj.)","sunburnt (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Anh thường dùng get sunburn; tiếng Anh-Mỹ cũng thường dùng get a sunburn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_injection', 'en-b1-19', 'injection', '/ɪnˈdʒekʃən/', 'B1', 'mũi tiêm; sự tiêm thuốc; sự rót vốn; sự bổ sung nguồn lực', 'n.', 'inject (v.), injectable (adj.)', NULL, 'Việc rót vốn có thể nói an injection of cash, thuộc cách dùng ẩn dụ.', 'The nurse gave me an injection in my arm.', NULL, 'Y tá tiêm cho tôi một mũi ở bắp tay.', '{"wordId":"injection","ukIpa":"/ɪnˈdʒekʃən/","usIpa":"/ɪnˈdʒekʃən/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"Putting medicine into the body using a needle.","vi":"mũi tiêm; sự tiêm thuốc"},{"pos":"n.","en":"The addition of money or resources to improve something.","vi":"sự rót vốn; sự bổ sung nguồn lực"}],"examples":[{"en":"The nurse gave me an injection in my arm.","vi":"Y tá tiêm cho tôi một mũi ở bắp tay.","audioKind":"ex"},{"en":"An injection of public funding could help local libraries modernise their facilities and expand community services.","vi":"Việc rót vốn công có thể giúp các thư viện địa phương hiện đại hóa cơ sở vật chất và mở rộng các dịch vụ cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"give an injection","vi":"tiêm một mũi"},{"en":"receive an injection","vi":"nhận mũi tiêm"},{"en":"a cash injection","vi":"một khoản bơm tiền"},{"en":"an injection of funding","vi":"sự rót vốn"}],"wordFamily":["inject (v.)","injectable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Việc rót vốn có thể nói an injection of cash, thuộc cách dùng ẩn dụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_symptom', 'en-b1-19', 'symptom', '/ˈsɪmptəm/', 'B1', 'triệu chứng; dấu hiệu; biểu hiện', 'n.', 'symptomatic (adj.)', NULL, 'Thường dùng cấu trúc a symptom of; giảm triệu chứng dùng relieve symptoms.', 'A sore throat was her first symptom of illness.', NULL, 'Đau họng là triệu chứng đầu tiên khi cô ấy bị ốm.', '{"wordId":"symptom","ukIpa":"/ˈsɪmptəm/","usIpa":"/ˈsɪmptəm/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"a physical or mental change that suggests an illness","vi":"triệu chứng"},{"pos":"n.","en":"a sign that an underlying problem exists","vi":"dấu hiệu; biểu hiện"}],"examples":[{"en":"A sore throat was her first symptom of illness.","vi":"Đau họng là triệu chứng đầu tiên khi cô ấy bị ốm.","audioKind":"ex"},{"en":"High staff turnover can be a symptom of poor management rather than a shortage of skilled workers.","vi":"Tỷ lệ nhân viên nghỉ việc cao có thể là biểu hiện của việc quản lý kém chứ không hẳn do thiếu hụt lao động lành nghề.","audioKind":"ex2"}],"collocations":[{"en":"common symptom","vi":"triệu chứng phổ biến"},{"en":"symptom of illness","vi":"triệu chứng bệnh"},{"en":"relieve symptoms","vi":"làm giảm triệu chứng"}],"wordFamily":["symptomatic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cấu trúc a symptom of; giảm triệu chứng dùng relieve symptoms.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_19_1', 'en-b1-19', 'Cách dùng “tiredness” (n.) — sự mệt mỏi; sự uể oải', 'extreme tiredness  ·  persistent tiredness  ·  signs of tiredness', 'Thường là danh từ không đếm được; dùng ''tired'' để chỉ người mệt mỏi và ''tiring'' để chỉ sự việc gây mệt mỏi.', 'Họ từ (Word Family): tired (adj.), tiring (adj.), tire (v.) | Đồng nghĩa: fatigue, weariness', '[{"hanzi":"After the long walk, tiredness made my legs feel heavy.","pinyin":"","meaning":"Sau chuyến đi bộ dài, sự mệt mỏi khiến đôi chân tôi cảm thấy nặng trĩu."},{"hanzi":"Persistent tiredness can reduce students'' concentration and may indicate that they are not getting enough sleep.","pinyin":"","meaning":"Tình trạng mệt mỏi kéo dài có thể làm giảm khả năng tập trung của học sinh và có thể cho thấy các em ngủ không đủ giấc."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_19_2', 'en-b1-19', 'Cách dùng “mental” (adj.) — thuộc tâm lý; thuộc tinh thần', 'mental health  ·  mental wellbeing  ·  mental arithmetic', 'mental thiên về mặt tâm lý hoặc trí tuệ; trong văn nói, dùng để chỉ người khùng điên có thể gây xúc phạm.', 'Họ từ (Word Family): mentally (adv.) | Đồng nghĩa: psychological · Trái nghĩa: physical', '[{"hanzi":"A quiet walk helps me protect my mental health.","pinyin":"","meaning":"Một buổi đi dạo tĩnh lặng giúp tôi bảo vệ sức khỏe tinh thần của mình."},{"hanzi":"Employers should give mental wellbeing the same priority as physical safety when designing workplace policies.","pinyin":"","meaning":"Các nhà tuyển dụng nên đặt sức khỏe tâm lý ở mức ưu tiên tương đương với sự an toàn thể chất khi thiết kế chính sách nơi làm việc."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_19_3', 'en-b1-19', 'Cách dùng “drown” (v.) — chết đuối; nhấn chìm xuống nước', 'drown out a voice  ·  nearly drown  ·  drown in paperwork', 'drown chỉ việc chết đuối, không chỉ đơn thuần là rơi xuống nước; để át đi âm thanh thường đi kèm với out.', 'Họ từ (Word Family): drowning (n.)', '[{"hanzi":"She nearly drowned when her boat overturned in the lake.","pinyin":"","meaning":"Cô ấy suýt chết đuối khi chiếc thuyền bị lật trên hồ."},{"hanzi":"Public safety campaigns can reduce the risk of children drowning by encouraging swimming lessons and adult supervision.","pinyin":"","meaning":"Các chiến dịch an toàn công cộng có thể làm giảm nguy cơ trẻ em bị đuối nước bằng cách khuyến khích các lớp học bơi và sự giám sát của người lớn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_19_4', 'en-b1-19', 'Cách dùng “mild” (adj.) — nhẹ; không nặng (triệu chứng, ảnh hưởng)', 'mild symptoms  ·  mild weather  ·  mild flavour', 'Từ mild có thể dùng để mô tả triệu chứng, thời tiết và hương vị, nhưng không đồng nghĩa với "vô hại".', 'Họ từ (Word Family): mildly (adv.), mildness (n.) | Đồng nghĩa: slight, gentle · Trái nghĩa: severe, harsh', '[{"hanzi":"I have a mild headache, so I''ll rest briefly.","pinyin":"","meaning":"Tôi bị đau đầu nhẹ nên sẽ nghỉ ngơi một lát."},{"hanzi":"Even mild air pollution can affect vulnerable groups, making regular monitoring essential in densely populated cities.","pinyin":"","meaning":"Ngay cả tình trạng ô nhiễm không khí nhẹ cũng có thể ảnh hưởng đến các nhóm dễ bị tổn thương, khiến việc theo dõi thường xuyên ở các thành phố đông dân trở nên vô cùng thiết yếu."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_19_1', 'en-b1-19', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_1_1', 'ten_b1_19_1', 'mild', 'I have a mild headache, so I''ll rest briefly.', 'I have a mild headache, so I''ll rest briefly.', '/maɪld/', 'Tôi bị đau đầu nhẹ nên sẽ nghỉ ngơi một lát.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_1_2', 'ten_b1_19_1', 'fitness', 'Swimming every morning has really improved my fitness.', 'Swimming every morning has really improved my fitness.', '/ˈfɪtnəs/', 'Việc bơi lội mỗi buổi sáng đã thực sự cải thiện thể lực của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_1_3', 'ten_b1_19_1', 'suncream', 'I packed suncream and a hat for our afternoon walk.', 'I packed suncream and a hat for our afternoon walk.', '/ˈsʌnkriːm/', 'Tôi đã mang theo kem chống nắng và một chiếc mũ cho buổi đi dạo buổi chiều.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_1_4', 'ten_b1_19_1', 'risk', 'Wear sturdy shoes to reduce the risk of slipping.', 'Wear sturdy shoes to reduce the risk of slipping.', '/rɪsk/', 'Hãy đi giày đế bám chắc để giảm nguy cơ bị trượt ngã.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_1_5', 'ten_b1_19_1', 'tiredness', 'After the long walk, tiredness made my legs feel heavy.', 'After the long walk, tiredness made my legs feel heavy.', '/ˈtaɪərdnəs/', 'Sau chuyến đi bộ dài, sự mệt mỏi khiến đôi chân tôi cảm thấy nặng trĩu.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_1_6', 'ten_b1_19_1', 'dizzy', 'I felt dizzy after spinning around with my little cousin.', 'I felt dizzy after spinning around with my little cousin.', '/ˈdɪzi/', 'Tôi cảm thấy chóng mặt sau khi quay vòng tròn cùng cậu em họ nhỏ tuổi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_1_7', 'ten_b1_19_1', 'stress', 'A short walk helps me deal with work stress.', 'A short walk helps me deal with work stress.', '/stres/', 'Đi dạo một chút giúp tôi giải tỏa áp lực công việc.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_1_8', 'ten_b1_19_1', 'prevent', 'This tight lid will prevent the soup from spilling.', 'This tight lid will prevent the soup from spilling.', '/prɪˈvent/', 'Chiếc nắp khít này sẽ ngăn không cho nước canh bị tràn ra ngoài.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_19_1_1', 'en-b1-19', 'ten_b1_19_1', 'listening', 'listening', 'I have a mild headache, so I''ll rest briefly.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi bị đau đầu nhẹ nên sẽ nghỉ ngơi một lát.","Cổ họng tôi cảm thấy khô rát sau khi nói chuyện cả buổi chiều.","Đạp xe đi làm là một phần trong lối sống lành mạnh của cô ấy.","Tôi đã mang theo kem chống nắng và một chiếc mũ cho buổi đi dạo buổi chiều."]'::jsonb, 0, 'I have a mild headache, so I''ll rest briefly. → Tôi bị đau đầu nhẹ nên sẽ nghỉ ngơi một lát.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_19_1_2', 'en-b1-19', 'ten_b1_19_1', 'listening', 'listening', 'Swimming every morning has really improved my fitness.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc bơi lội mỗi buổi sáng đã thực sự cải thiện thể lực của tôi.","Tôi cảm thấy chóng mặt sau khi quay vòng tròn cùng cậu em họ nhỏ tuổi.","Một buổi đi dạo tĩnh lặng giúp tôi bảo vệ sức khỏe tinh thần của mình.","Cô ấy suýt chết đuối khi chiếc thuyền bị lật trên hồ."]'::jsonb, 0, 'Swimming every morning has really improved my fitness. → Việc bơi lội mỗi buổi sáng đã thực sự cải thiện thể lực của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_19_1_3', 'en-b1-19', 'ten_b1_19_1', 'listening', 'listening', 'I packed suncream and a hat for our afternoon walk.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đau họng là triệu chứng đầu tiên khi cô ấy bị ốm.","Căn phòng đầy bụi khiến tôi ho liên tục vài lần.","Tôi đã mang theo kem chống nắng và một chiếc mũ cho buổi đi dạo buổi chiều.","Đạp xe đi làm là một phần trong lối sống lành mạnh của cô ấy."]'::jsonb, 2, 'I packed suncream and a hat for our afternoon walk. → Tôi đã mang theo kem chống nắng và một chiếc mũ cho buổi đi dạo buổi chiều.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_19_2', 'en-b1-19', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_2_1', 'ten_b1_19_2', 'mild', 'Even mild air pollution can affect vulnerable groups, making regular monitoring essential in densely populated cities.', 'Even mild air pollution can affect vulnerable groups, making regular monitoring essential in densely populated cities.', '/maɪld/', 'Ngay cả tình trạng ô nhiễm không khí nhẹ cũng có thể ảnh hưởng đến các nhóm dễ bị tổn thương, khiến việc theo dõi thường xuyên ở các thành phố đông dân trở nên vô cùng thiết yếu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_2_2', 'ten_b1_19_2', 'fitness', 'Schools can improve children''s fitness by providing regular opportunities for enjoyable physical activity throughout the week.', 'Schools can improve children''s fitness by providing regular opportunities for enjoyable physical activity throughout the week.', '/ˈfɪtnəs/', 'Các trường học có thể nâng cao thể lực cho học sinh bằng cách tạo cơ hội tham gia các hoạt động thể chất thú vị đều đặn suốt tuần.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_2_3', 'ten_b1_19_2', 'suncream', 'Schools can encourage children to use suncream and seek shade during outdoor activities in sunny weather.', 'Schools can encourage children to use suncream and seek shade during outdoor activities in sunny weather.', '/ˈsʌnkriːm/', 'Nhà trường có thể khuyến khích trẻ em bôi kem chống nắng và tìm nơi râm mát trong các hoạt động ngoài trời khi thời tiết có nắng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_2_4', 'ten_b1_19_2', 'risk', 'Governments should assess the risk of flooding before approving new housing developments near rivers.', 'Governments should assess the risk of flooding before approving new housing developments near rivers.', '/rɪsk/', 'Chính phủ nên đánh giá nguy cơ ngập lụt trước khi phê duyệt các dự án phát triển nhà ở mới gần sông ngòi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_2_5', 'ten_b1_19_2', 'tiredness', 'Persistent tiredness can reduce students'' concentration and may indicate that they are not getting enough sleep.', 'Persistent tiredness can reduce students'' concentration and may indicate that they are not getting enough sleep.', '/ˈtaɪərdnəs/', 'Tình trạng mệt mỏi kéo dài có thể làm giảm khả năng tập trung của học sinh và có thể cho thấy các em ngủ không đủ giấc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_19_2_6', 'ten_b1_19_2', 'dizzy', 'People who feel dizzy during exercise should stop immediately and seek medical advice if symptoms persist.', 'People who feel dizzy during exercise should stop immediately and seek medical advice if symptoms persist.', '/ˈdɪzi/', 'Những người cảm thấy chóng mặt khi tập thể dục nên dừng lại ngay lập tức và tìm sự tư vấn y tế nếu triệu chứng kéo dài.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_19_2_1', 'en-b1-19', 'ten_b1_19_2', 'listening', 'listening', 'Even mild air pollution can affect vulnerable groups, making regular monitoring essential in densely populated cities.', NULL, 'Trong câu vừa nghe, từ “mild” mang nghĩa nào sau đây?', '["khăn giấy; giấy ăn","nhẹ; không nặng (triệu chứng, ảnh hưởng)","bị dị ứng; có dị ứng với","địa điểm thu hút; danh lam thắng cảnh"]'::jsonb, 1, '“mild” (/maɪld/): nhẹ; không nặng (triệu chứng, ảnh hưởng). Câu đầy đủ: Even mild air pollution can affect vulnerable groups, making regular monitoring essential in densely populated cities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_19_2_2', 'en-b1-19', 'ten_b1_19_2', 'listening', 'listening', 'Schools can improve children''s fitness by providing regular opportunities for enjoyable physical activity throughout the week.', NULL, 'Trong câu vừa nghe, từ “fitness” mang nghĩa nào sau đây?', '["trạng thái; tình trạng","có liên quan; có dính líu","sự đặt chỗ; việc đặt trước","thể lực; thể chất"]'::jsonb, 3, '“fitness” (/ˈfɪtnəs/): thể lực; thể chất. Câu đầy đủ: Schools can improve children''s fitness by providing regular opportunities for enjoyable physical activity throughout the week.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_19_1', 'en-b1-19', 'I have a mild headache, so I''ll rest briefly', 'Tôi bị đau đầu nhẹ nên sẽ nghỉ ngơi một lát.', 'mild /maɪld/', '["I","headache","so","have","briefly","mild","I''ll","a","rest"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_19_2', 'en-b1-19', 'Swimming every morning has really improved my fitness', 'Việc bơi lội mỗi buổi sáng đã thực sự cải thiện thể lực của tôi.', 'fitness /ˈfɪtnəs/', '["my","Swimming","fitness","morning","has","really","improved","every"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_19_3', 'en-b1-19', 'I packed suncream and a hat for our afternoon walk', 'Tôi đã mang theo kem chống nắng và một chiếc mũ cho buổi đi dạo buổi chiều.', 'suncream /ˈsʌnkriːm/', '["and","for","hat","a","packed","walk","afternoon","I","suncream","our"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_19_4', 'en-b1-19', 'Wear sturdy shoes to reduce the risk of slipping', 'Hãy đi giày đế bám chắc để giảm nguy cơ bị trượt ngã.', 'risk /rɪsk/', '["shoes","to","of","reduce","Wear","sturdy","risk","the","slipping"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_19_5', 'en-b1-19', 'After the long walk, tiredness made my legs feel heavy', 'Sau chuyến đi bộ dài, sự mệt mỏi khiến đôi chân tôi cảm thấy nặng trĩu.', 'tiredness /ˈtaɪərdnəs/', '["the","tiredness","long","After","made","my","legs","walk","feel","heavy"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_19_6', 'en-b1-19', 'I felt dizzy after spinning around with my little cousin', 'Tôi cảm thấy chóng mặt sau khi quay vòng tròn cùng cậu em họ nhỏ tuổi.', 'dizzy /ˈdɪzi/', '["I","cousin","spinning","with","dizzy","felt","little","my","after","around"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_19_7', 'en-b1-19', 'A short walk helps me deal with work stress', 'Đi dạo một chút giúp tôi giải tỏa áp lực công việc.', 'stress /stres/', '["walk","me","helps","work","deal","stress","short","with","A"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_19_8', 'en-b1-19', 'This tight lid will prevent the soup from spilling', 'Chiếc nắp khít này sẽ ngăn không cho nước canh bị tràn ra ngoài.', 'prevent /prɪˈvent/', '["the","soup","from","spilling","will","prevent","lid","tight","This"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_19_9', 'en-b1-19', 'The dusty room made me cough several times', 'Căn phòng đầy bụi khiến tôi ho liên tục vài lần.', 'cough /kɔːf/', '["room","The","several","cough","times","dusty","made","me"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
