INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_1', 'en-b1-19', NULL, 'comprehensive_test', 'listening', 'mild', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["diễn viên hài, nghệ sĩ hài","nhẹ; không nặng (triệu chứng, ảnh hưởng)","giai điệu; khúc nhạc","bị che khuất; ẩn giấu; khó nhận thấy"]'::jsonb, 1, 'mild (/maɪld/) → nhẹ; không nặng (triệu chứng, ảnh hưởng); ôn hòa; dễ chịu (thời tiết); nhạt; không cay (hương vị)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_2', 'en-b1-19', NULL, 'comprehensive_test', 'listening', 'Swimming every morning has really improved my fitness.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã mang theo kem chống nắng và một chiếc mũ cho buổi đi dạo buổi chiều.","Tôi bị cháy nắng sau khi ở ngoài trời suốt cả buổi chiều.","Chị tôi đã trở thành một người ăn chay sau khi học nấu ăn.","Việc bơi lội mỗi buổi sáng đã thực sự cải thiện thể lực của tôi."]'::jsonb, 3, 'Swimming every morning has really improved my fitness. → Việc bơi lội mỗi buổi sáng đã thực sự cải thiện thể lực của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_3', 'en-b1-19', NULL, 'comprehensive_test', 'listening', 'suncream', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["độc lập; tự chủ; tự lập","kem chống nắng","lối sống; phong cách sống","phiên bản"]'::jsonb, 1, 'suncream (/ˈsʌnkriːm/) → kem chống nắng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_4', 'en-b1-19', NULL, 'comprehensive_test', 'listening', 'Wear sturdy shoes to reduce the risk of slipping.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã mang theo kem chống nắng và một chiếc mũ cho buổi đi dạo buổi chiều.","Hãy đi giày đế bám chắc để giảm nguy cơ bị trượt ngã.","Tôi bị khuỷu tay đập vào cửa bếp.","Một buổi đi dạo tĩnh lặng giúp tôi bảo vệ sức khỏe tinh thần của mình."]'::jsonb, 1, 'Wear sturdy shoes to reduce the risk of slipping. → Hãy đi giày đế bám chắc để giảm nguy cơ bị trượt ngã.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_5', 'en-b1-19', NULL, 'comprehensive_test', 'listening', 'tiredness', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bụi; bụi bặm","lọ miệng rộng; hũ; bình","khó quên; không thể nào quên","sự mệt mỏi; sự uể oải"]'::jsonb, 3, 'tiredness (/ˈtaɪərdnəs/) → sự mệt mỏi; sự uể oải', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_6', 'en-b1-19', NULL, 'comprehensive_test', 'listening', 'I felt dizzy after spinning around with my little cousin.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đau họng là triệu chứng đầu tiên khi cô ấy bị ốm.","Tôi cảm thấy chóng mặt sau khi quay vòng tròn cùng cậu em họ nhỏ tuổi.","Chị tôi đã trở thành một người ăn chay sau khi học nấu ăn.","Căn phòng đầy bụi khiến tôi ho liên tục vài lần."]'::jsonb, 1, 'I felt dizzy after spinning around with my little cousin. → Tôi cảm thấy chóng mặt sau khi quay vòng tròn cùng cậu em họ nhỏ tuổi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_7', 'en-b1-19', NULL, 'comprehensive_test', 'listening', 'stress', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc về phía tây; phía tây","sự căng thẳng tinh thần; áp lực tinh thần","phớt lờ; ngó lơ; không đếm xỉa","thuộc về chính trị; chính trị"]'::jsonb, 1, 'stress (/stres/) → sự căng thẳng tinh thần; áp lực tinh thần; nhấn mạnh; làm nổi bật; trọng âm', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_8', 'en-b1-19', NULL, 'comprehensive_test', 'listening', 'This tight lid will prevent the soup from spilling.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Căn phòng đầy bụi khiến tôi ho liên tục vài lần.","Chiếc nắp khít này sẽ ngăn không cho nước canh bị tràn ra ngoài.","Tôi đã mang theo kem chống nắng và một chiếc mũ cho buổi đi dạo buổi chiều.","Tôi cảm thấy chóng mặt sau khi quay vòng tròn cùng cậu em họ nhỏ tuổi."]'::jsonb, 1, 'This tight lid will prevent the soup from spilling. → Chiếc nắp khít này sẽ ngăn không cho nước canh bị tràn ra ngoài.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_9', 'en-b1-19', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the feeling of needing rest or sleep”?', '["tiredness","dizzy","elbow","throat"]'::jsonb, 0, 'tiredness (/ˈtaɪərdnəs/) → sự mệt mỏi; sự uể oải', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
