INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_18', 'en-b1-19', NULL, 'comprehensive_test', 'reading', NULL, 'Even mild air pollution can affect vulnerable groups, making regular monitoring essential in densely populated cities.', 'Dựa vào câu trên, từ “mild” có nghĩa phù hợp nhất là gì?', '["hình tam giác","bằng nhau; bình đẳng","nhẹ; không nặng (triệu chứng, ảnh hưởng)","mã; mật mã; mã máy tính"]'::jsonb, 2, 'mild: nhẹ; không nặng (triệu chứng, ảnh hưởng); ôn hòa; dễ chịu (thời tiết); nhạt; không cay (hương vị). Dịch cả câu: Ngay cả tình trạng ô nhiễm không khí nhẹ cũng có thể ảnh hưởng đến các nhóm dễ bị tổn thương, khiến việc theo dõi thường xuyên ở các thành phố đông dân trở nên vô cùng thiết yếu.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_19', 'en-b1-19', NULL, 'comprehensive_test', 'reading', NULL, 'Schools can improve children''s fitness by providing regular opportunities for enjoyable physical activity throughout the week.', 'Dựa vào câu trên, từ “fitness” có nghĩa phù hợp nhất là gì?', '["gia sư; người hướng dẫn riêng","thể lực; thể chất","quả mọng; quả dâu nhỏ","ban ngày; thời gian ban ngày"]'::jsonb, 1, 'fitness: thể lực; thể chất; sự thích hợp; năng lực đáp ứng. Dịch cả câu: Các trường học có thể nâng cao thể lực cho học sinh bằng cách tạo cơ hội tham gia các hoạt động thể chất thú vị đều đặn suốt tuần.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_20', 'en-b1-19', NULL, 'comprehensive_test', 'reading', NULL, 'Schools can encourage children to use suncream and seek shade during outdoor activities in sunny weather.', 'Dựa vào câu trên, từ “suncream” có nghĩa phù hợp nhất là gì?', '["xuất bản; đăng tải","máy bay phản lực","kem chống nắng","làm cho ai đó thất vọng vì không đáp ứng được kỳ vọng của họ"]'::jsonb, 2, 'suncream: kem chống nắng. Dịch cả câu: Nhà trường có thể khuyến khích trẻ em bôi kem chống nắng và tìm nơi râm mát trong các hoạt động ngoài trời khi thời tiết có nắng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_21', 'en-b1-19', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should assess the risk of flooding before approving new housing developments near rivers.', 'Dựa vào câu trên, từ “risk” có nghĩa phù hợp nhất là gì?', '["rủi ro; nguy cơ","lời thỉnh cầu; sự yêu cầu lịch sự hoặc trang trọng","người nước ngoài","thị trưởng; chủ tịch ủy ban nhân dân thị trấn"]'::jsonb, 0, 'risk: rủi ro; nguy cơ; liều lĩnh làm gì; mạo hiểm. Dịch cả câu: Chính phủ nên đánh giá nguy cơ ngập lụt trước khi phê duyệt các dự án phát triển nhà ở mới gần sông ngòi.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_22', 'en-b1-19', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cháy nắng”', '["old-fashioned","involve","sunburn","shared"]'::jsonb, 2, 'cháy nắng → sunburn (/ˈsʌnbɜːrn/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_23', 'en-b1-19', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mũi tiêm; sự tiêm thuốc”', '["blind","drummer","deserve","injection"]'::jsonb, 3, 'mũi tiêm; sự tiêm thuốc → injection (/ɪnˈdʒekʃən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_19_24', 'en-b1-19', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “triệu chứng”', '["symptom","licence","gasoline","application"]'::jsonb, 0, 'triệu chứng → symptom (/ˈsɪmptəm/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-20', 'en', 'Bài 20: Sức khỏe & Cơ thể (2) - CEFR B1', 'CEFR B1', 'B1 · Sức khỏe', '22 từ vựng Tiếng Anh CEFR B1 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3020, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exhausted', 'en-b1-20', 'exhausted', '/ɪɡˈzɔːstɪd/', 'B1', 'kiệt sức; mệt lử; cạn kiệt; khô cạn', 'adj.', 'exhaust (v.), exhaustion (n.), exhausting (adj.)', 'Đồng nghĩa: worn out, drained · Trái nghĩa: energetic, refreshed', 'Dùng exhausted khi chỉ người cảm thấy mệt mỏi; dùng exhausting khi chỉ sự việc gây mệt mỏi.', 'After carrying those boxes upstairs, I felt completely exhausted.', NULL, 'Sau khi khiêng mấy cái thùng đó lên lầu, tôi cảm thấy kiệt sức hoàn toàn.', '{"wordId":"exhausted","ukIpa":"/ɪɡˈzɔːstɪd/","usIpa":"/ɪɡˈzɔːstɪd/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"extremely tired and lacking energy","vi":"kiệt sức; mệt lử"},{"pos":"adj.","en":"completely used up, with nothing remaining","vi":"cạn kiệt; khô cạn"}],"examples":[{"en":"After carrying those boxes upstairs, I felt completely exhausted.","vi":"Sau khi khiêng mấy cái thùng đó lên lầu, tôi cảm thấy kiệt sức hoàn toàn.","audioKind":"ex"},{"en":"Employees who are constantly exhausted may struggle to concentrate, increasing the risk of mistakes at work.","vi":"Những nhân viên liên tục bị kiệt sức có thể gặp khó khăn trong việc tập trung, làm gia tăng nguy cơ mắc lỗi trong công việc.","audioKind":"ex2"}],"collocations":[{"en":"feel exhausted","vi":"cảm thấy kiệt sức"},{"en":"physically exhausted","vi":"kiệt quệ về thể chất"},{"en":"mentally exhausted","vi":"kiệt quệ về tinh thần"},{"en":"exhausted resources","vi":"nguồn lực cạn kiệt"}],"wordFamily":["exhaust (v.)","exhaustion (n.)","exhausting (adj.)"],"synonyms":["worn out","drained"],"antonyms":["energetic","refreshed"],"tipVi":"Dùng exhausted khi chỉ người cảm thấy mệt mỏi; dùng exhausting khi chỉ sự việc gây mệt mỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_muscle', 'en-b1-20', 'muscle', '/ˈmʌsəl/', 'B1', 'cơ; bắp thịt; sức mạnh; thế lực', 'n.', 'muscular (adj.)', NULL, 'Chữ c trong muscle không phát âm; pull a muscle có nghĩa là bị kéo căng cơ.', 'I pulled a muscle while lifting a heavy box.', NULL, 'Tôi bị căng cơ khi nhấc một chiếc hộp nặng.', '{"wordId":"muscle","ukIpa":"/ˈmʌsəl/","usIpa":"/ˈmʌsəl/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"body tissue that tightens and relaxes to produce movement","vi":"cơ; bắp thịt"},{"pos":"n.","en":"power or influence used to achieve something","vi":"sức mạnh; thế lực"}],"examples":[{"en":"I pulled a muscle while lifting a heavy box.","vi":"Tôi bị căng cơ khi nhấc một chiếc hộp nặng.","audioKind":"ex"},{"en":"Regular strength training builds muscle and helps older adults maintain balance and independence in daily life.","vi":"Tập luyện sức mạnh đều đặn giúp phát triển cơ bắp và hỗ trợ người cao tuổi duy trì khả năng giữ thăng bằng cũng như sự độc lập trong đời sống hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"build muscle","vi":"xây dựng cơ bắp"},{"en":"pull a muscle","vi":"kéo căng cơ; căng cơ"},{"en":"muscle strength","vi":"sức mạnh cơ bắp"},{"en":"financial muscle","vi":"tiềm lực tài chính"}],"wordFamily":["muscular (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ c trong muscle không phát âm; pull a muscle có nghĩa là bị kéo căng cơ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sickness', 'en-b1-20', 'sickness', '/ˈsɪknəs/', 'B1', 'bệnh tật; sự ốm đau; sự buồn nôn; chứng nôn mửa', 'n.', 'sick (adj.), sickly (adj.), sicken (v.)', 'Đồng nghĩa: illness · Trái nghĩa: health', 'Thông thường là danh từ không đếm được; trong tiếng Anh-Anh, từ này còn chỉ cảm giác buồn nôn hoặc nôn mửa.', 'Several children missed school because of sickness this week.', NULL, 'Nhiều đứa trẻ đã phải nghỉ học vì ốm đau trong tuần này.', '{"wordId":"sickness","ukIpa":"/ˈsɪknəs/","usIpa":"/ˈsɪknəs/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"the state of being ill","vi":"bệnh tật; sự ốm đau"},{"pos":"n.","en":"the feeling of needing to vomit, or vomiting itself","vi":"sự buồn nôn; chứng nôn mửa"}],"examples":[{"en":"Several children missed school because of sickness this week.","vi":"Nhiều đứa trẻ đã phải nghỉ học vì ốm đau trong tuần này.","audioKind":"ex"},{"en":"Employers can reduce absence due to sickness by improving ventilation and encouraging staff to stay home when unwell.","vi":"Các nhà tuyển dụng có thể giảm bớt tình trạng nghỉ làm do ốm đau bằng cách cải thiện thông gió và khuyến khích nhân viên ở nhà khi không khỏe.","audioKind":"ex2"}],"collocations":[{"en":"travel sickness","vi":"chứng say xe"},{"en":"morning sickness","vi":"ốm nghén"},{"en":"altitude sickness","vi":"bệnh độ cao"},{"en":"sickness absence","vi":"nghỉ vì ốm đau"}],"wordFamily":["sick (adj.)","sickly (adj.)","sicken (v.)"],"synonyms":["illness"],"antonyms":["health"],"tipVi":"Thông thường là danh từ không đếm được; trong tiếng Anh-Anh, từ này còn chỉ cảm giác buồn nôn hoặc nôn mửa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spinach', 'en-b1-20', 'spinach', '/ˈspɪnɪtʃ/', 'B1', 'rau bina; cải bó xôi', 'n.', NULL, NULL, 'Danh từ này thường không đếm được; khi chỉ một chiếc lá riêng lẻ dùng a spinach leaf.', 'I added fresh spinach to the soup before dinner.', NULL, 'Tôi đã cho thêm rau bina tươi vào món súp trước bữa tối.', '{"wordId":"spinach","ukIpa":"/ˈspɪnɪtʃ/","usIpa":"/ˈspɪnɪtʃ/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A vegetable with dark green leaves eaten raw or cooked.","vi":"rau bina; cải bó xôi"}],"examples":[{"en":"I added fresh spinach to the soup before dinner.","vi":"Tôi đã cho thêm rau bina tươi vào món súp trước bữa tối.","audioKind":"ex"},{"en":"Leafy vegetables such as spinach provide nutrients that support a healthy, balanced diet.","vi":"Các loại rau có lá xanh như rau bina cung cấp các dưỡng chất thiết yếu cho một chế độ ăn uống lành mạnh và cân đối.","audioKind":"ex2"}],"collocations":[{"en":"fresh spinach","vi":"rau bina tươi"},{"en":"spinach leaves","vi":"lá rau bina"},{"en":"steamed spinach","vi":"rau bina hấp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ này thường không đếm được; khi chỉ một chiếc lá riêng lẻ dùng a spinach leaf.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_allergic', 'en-b1-20', 'allergic', '/əˈlɝːdʒɪk/', 'B1', 'bị dị ứng; có dị ứng với; do dị ứng gây ra', 'adj.', 'allergy (n.), allergen (n.)', NULL, 'Diễn đạt việc dị ứng với cái gì dùng be allergic to, không dùng allergic with.', 'I am allergic to cats, so I keep my distance.', NULL, 'Tôi bị dị ứng với mèo nên tôi luôn giữ khoảng cách.', '{"wordId":"allergic","ukIpa":"/əˈlɜːdʒɪk/","usIpa":"/əˈlɝːdʒɪk/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"Having an allergy to a particular substance","vi":"bị dị ứng; có dị ứng với"},{"pos":"adj.","en":"Caused by an allergy","vi":"do dị ứng gây ra"}],"examples":[{"en":"I am allergic to cats, so I keep my distance.","vi":"Tôi bị dị ứng với mèo nên tôi luôn giữ khoảng cách.","audioKind":"ex"},{"en":"Restaurants should provide accurate ingredient information to protect customers who are allergic to common foods.","vi":"Các nhà hàng nên cung cấp thông tin thành phần chính xác để bảo vệ những khách hàng bị dị ứng với các loại thực phẩm phổ biến.","audioKind":"ex2"}],"collocations":[{"en":"be allergic to","vi":"bị dị ứng với"},{"en":"allergic reaction","vi":"phản ứng dị ứng"},{"en":"allergic to pollen","vi":"dị ứng phấn hoa"}],"wordFamily":["allergy (n.)","allergen (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Diễn đạt việc dị ứng với cái gì dùng be allergic to, không dùng allergic with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_breathe', 'en-b1-20', 'breathe', '/briːð/', 'B1', 'hít thở; thở', 'v.', 'breath (n.), breathing (n.), breathless (adj.)', 'Đồng nghĩa: respire', 'breathe là động từ với âm cuối /ð/; breath là danh từ với âm cuối /θ/.', 'Sit by the window and breathe slowly for a minute.', NULL, 'Hãy ngồi bên cửa sổ và hít thở nhẹ nhàng trong một phút.', '{"wordId":"breathe","ukIpa":"/briːð/","usIpa":"/briːð/","cefr":"B1","topic":"health","senses":[{"pos":"v.","en":"take air into your lungs and let it out","vi":"hít thở; thở"}],"examples":[{"en":"Sit by the window and breathe slowly for a minute.","vi":"Hãy ngồi bên cửa sổ và hít thở nhẹ nhàng trong một phút.","audioKind":"ex"},{"en":"People living near busy roads often breathe polluted air, which can increase their risk of respiratory illness.","vi":"Những người sống gần các con đường tấp nập thường hít phải không khí ô nhiễm, điều này có thể làm tăng nguy cơ mắc bệnh đường hô hấp.","audioKind":"ex2"}],"collocations":[{"en":"breathe deeply","vi":"hít thở sâu"},{"en":"breathe in","vi":"hít vào"},{"en":"breathe out","vi":"thở ra"},{"en":"breathe fresh air","vi":"hít thở không khí trong lành"}],"wordFamily":["breath (n.)","breathing (n.)","breathless (adj.)"],"synonyms":["respire"],"antonyms":[],"tipVi":"breathe là động từ với âm cuối /ð/; breath là danh từ với âm cuối /θ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alcohol', 'en-b1-20', 'alcohol', '/ˈælkəhɔːl/', 'B1', 'đồ uống có cồn; rượu; chất cồn; rượu ê-ty-lic', 'n.', 'alcoholic (adj.), non-alcoholic (adj.)', NULL, 'Khi chỉ chung rượu hoặc cồn thì thường không đếm được; a drink có thể chỉ một ly rượu.', 'This restaurant serves fresh juice but does not sell alcohol.', NULL, 'Nhà hàng này phục vụ nước ép tươi nhưng không bán đồ uống có cồn.', '{"wordId":"alcohol","ukIpa":"/ˈælkəhɒl/","usIpa":"/ˈælkəhɔːl/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"drinks containing a substance that can make people drunk","vi":"đồ uống có cồn; rượu"},{"pos":"n.","en":"a colourless liquid used in drinks, cleaning products, and fuels","vi":"chất cồn; rượu ê-ty-lic"}],"examples":[{"en":"This restaurant serves fresh juice but does not sell alcohol.","vi":"Nhà hàng này phục vụ nước ép tươi nhưng không bán đồ uống có cồn.","audioKind":"ex"},{"en":"Public health campaigns should explain how excessive alcohol consumption can damage both physical and mental health.","vi":"Các chiến dịch y tế công cộng nên giải thích việc tiêu thụ quá nhiều rượu bia có thể tổn hại đến cả sức khỏe thể chất lẫn tinh thần như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"alcohol consumption","vi":"lượng tiêu thụ rượu bia"},{"en":"alcohol abuse","vi":"lạm dụng rượu"},{"en":"alcohol content","vi":"nồng độ cồn"},{"en":"rubbing alcohol","vi":"cồn y tế"}],"wordFamily":["alcoholic (adj.)","non-alcoholic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ chung rượu hoặc cồn thì thường không đếm được; a drink có thể chỉ một ly rượu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sneeze', 'en-b1-20', 'sneeze', '/sniːz/', 'B1', 'hắt hơi; nhảy mũi; cái hắt hơi', 'v.', 'sneezing (n.)', NULL, 'Động từ không có tân ngữ trực tiếp; cụm từ "hắt một cái" có thể dùng give a sneeze.', 'Dust from the old rug made me sneeze.', NULL, 'Bụi từ tấm thảm cũ làm tôi hắt hơi.', '{"wordId":"sneeze","ukIpa":"/sniːz/","usIpa":"/sniːz/","cefr":"B1","topic":"health","senses":[{"pos":"v.","en":"To suddenly force air out through your nose and mouth.","vi":"hắt hơi; nhảy mũi"},{"pos":"n.","en":"A sudden, involuntary burst of air from the nose and mouth.","vi":"cái hắt hơi"}],"examples":[{"en":"Dust from the old rug made me sneeze.","vi":"Bụi từ tấm thảm cũ làm tôi hắt hơi.","audioKind":"ex"},{"en":"Covering your mouth and nose when you sneeze helps reduce the spread of respiratory infections.","vi":"Che miệng và mũi khi bạn hắt hơi giúp giảm sự lây lan của các bệnh nhiễm trùng đường hô hấp.","audioKind":"ex2"}],"collocations":[{"en":"sneeze into a tissue","vi":"hắt hơi vào khăn giấy"},{"en":"a fit of sneezing","vi":"một cơn hắt hơi"},{"en":"stifle a sneeze","vi":"cố nén cái hắt hơi"}],"wordFamily":["sneezing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ không có tân ngữ trực tiếp; cụm từ \"hắt một cái\" có thể dùng give a sneeze.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_treatment', 'en-b1-20', 'treatment', '/ˈtriːtmənt/', 'B1', 'sự điều trị; phép chữa bệnh; cách đối xử; sự đối đãi; sự xử lý; phương pháp xử lý', 'n.', 'treat (v.), treatable (adj.)', NULL, 'Nói chung về việc điều trị thì không đếm được; khi chỉ một liệu pháp cụ thể thì dùng a treatment.', 'After treatment, her injured ankle felt much better.', NULL, 'Sau khi điều trị, cổ chân bị thương của cô ấy đã đỡ hơn rất nhiều.', '{"wordId":"treatment","ukIpa":"/ˈtriːtmənt/","usIpa":"/ˈtriːtmənt/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"medical care given to improve an illness or injury","vi":"sự điều trị; phép chữa bệnh"},{"pos":"n.","en":"the way someone behaves towards a person or group","vi":"cách đối xử; sự đối đãi"},{"pos":"n.","en":"a process that cleans, protects, or changes a substance","vi":"sự xử lý; phương pháp xử lý"}],"examples":[{"en":"After treatment, her injured ankle felt much better.","vi":"Sau khi điều trị, cổ chân bị thương của cô ấy đã đỡ hơn rất nhiều.","audioKind":"ex"},{"en":"Access to affordable medical treatment is essential for reducing health inequalities between wealthy and disadvantaged communities.","vi":"Việc tiếp cận dịch vụ y tế phải chăng là điều cốt yếu để giảm bớt sự bất bình đẳng về y tế giữa các cộng đồng giàu có và kém may mắn.","audioKind":"ex2"}],"collocations":[{"en":"receive treatment","vi":"nhận điều trị"},{"en":"medical treatment","vi":"điều trị y tế"},{"en":"equal treatment","vi":"đối xử công bằng"},{"en":"wastewater treatment","vi":"xử lý nước thải"}],"wordFamily":["treat (v.)","treatable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nói chung về việc điều trị thì không đếm được; khi chỉ một liệu pháp cụ thể thì dùng a treatment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_waist', 'en-b1-20', 'waist', '/weɪst/', 'B1', 'vòng eo; eo; phần cạp (quần áo)', 'n.', 'waistline (n.)', NULL, '"waist" có nghĩa là eo, phát âm đồng âm với "waste" (sự lãng phí).', 'These trousers fit perfectly around my waist now.', NULL, 'Chiếc quần này giờ đây vừa vặn hoàn hảo quanh eo tôi.', '{"wordId":"waist","ukIpa":"/weɪst/","usIpa":"/weɪst/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"The middle part of your body above your hips.","vi":"vòng eo; eo"},{"pos":"n.","en":"The part of a garment that fits around your waist.","vi":"phần cạp (quần áo)"}],"examples":[{"en":"These trousers fit perfectly around my waist now.","vi":"Chiếc quần này giờ đây vừa vặn hoàn hảo quanh eo tôi.","audioKind":"ex"},{"en":"Measuring waist size can help health professionals assess certain risks associated with excess body fat.","vi":"Việc đo vòng eo có thể giúp các chuyên gia y tế đánh giá một số rủi ro liên quan đến tình trạng mỡ thừa trong cơ thể.","audioKind":"ex2"}],"collocations":[{"en":"waist size","vi":"số đo vòng eo"},{"en":"around the waist","vi":"quanh vòng eo"},{"en":"from the waist up","vi":"từ eo trở lên"}],"wordFamily":["waistline (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"waist\" có nghĩa là eo, phát âm đồng âm với \"waste\" (sự lãng phí).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recover', 'en-b1-20', 'recover', '/rɪˈkʌvər/', 'B1', 'bình phục; khôi phục (sức khỏe, trạng thái); lấy lại; tìm lại được', 'v.', 'recovery (n.), recoverable (adj.)', 'Đồng nghĩa: recuperate, regain · Trái nghĩa: deteriorate', 'Dùng cấu trúc "recover from" khi nói về việc hồi phục sau bệnh tật hoặc sự cố.', 'It took several days to recover from the flu.', NULL, 'Tôi phải mất mấy ngày mới bình phục hẳn sau trận cúm.', '{"wordId":"recover","ukIpa":"/rɪˈkʌvə/","usIpa":"/rɪˈkʌvər/","cefr":"B1","topic":"health","senses":[{"pos":"v.","en":"return to health or a normal condition after difficulty","vi":"bình phục; khôi phục (sức khỏe, trạng thái)"},{"pos":"v.","en":"get back something lost, stolen, or spent","vi":"lấy lại; tìm lại được"}],"examples":[{"en":"It took several days to recover from the flu.","vi":"Tôi phải mất mấy ngày mới bình phục hẳn sau trận cúm.","audioKind":"ex"},{"en":"Local economies often recover more quickly when governments provide timely support for small businesses.","vi":"Các nền kinh tế địa phương thường phục hồi nhanh hơn khi chính phủ cung cấp sự hỗ trợ kịp thời cho các doanh nghiệp nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"recover from an illness","vi":"hồi phục sau trận ốm"},{"en":"fully recover","vi":"hồi phục hoàn toàn"},{"en":"recover lost data","vi":"khôi phục dữ liệu bị mất"},{"en":"recover costs","vi":"thu hồi chi phí"}],"wordFamily":["recovery (n.)","recoverable (adj.)"],"synonyms":["recuperate","regain"],"antonyms":["deteriorate"],"tipVi":"Dùng cấu trúc \"recover from\" khi nói về việc hồi phục sau bệnh tật hoặc sự cố.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strength', 'en-b1-20', 'strength', '/streŋθ/', 'B1', 'thể lực; sức lực; thế mạnh; ưu điểm; độ bền; cường độ', 'n.', 'strong (adj.), strongly (adv.), strengthen (v.)', 'Trái nghĩa: weakness', 'Nghĩa chỉ thể lực thường không đếm được; nghĩa chỉ thế mạnh có thể đếm được.', 'I needed all my strength to lift the suitcase.', NULL, 'Tôi đã phải dùng hết sức lực mới nhấc nổi chiếc vali đó.', '{"wordId":"strength","ukIpa":"/streŋθ/","usIpa":"/streŋθ/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"Physical power to lift, move, or resist something.","vi":"thể lực; sức lực"},{"pos":"n.","en":"A quality or skill that makes someone or something effective.","vi":"thế mạnh; ưu điểm"},{"pos":"n.","en":"How strong, powerful, or resistant to damage something is.","vi":"độ bền; cường độ"}],"examples":[{"en":"I needed all my strength to lift the suitcase.","vi":"Tôi đã phải dùng hết sức lực mới nhấc nổi chiếc vali đó.","audioKind":"ex"},{"en":"Schools should help students identify their strengths rather than judge everyone solely through written examinations.","vi":"Nhà trường nên giúp học sinh nhận ra thế mạnh của bản thân thay vì đánh giá tất cả mọi người chỉ qua các bài kiểm tra viết.","audioKind":"ex2"}],"collocations":[{"en":"physical strength","vi":"thể lực"},{"en":"strengths and weaknesses","vi":"ưu điểm và nhược điểm"},{"en":"tensile strength","vi":"độ bền kéo"},{"en":"build strength","vi":"tăng cường sức mạnh"}],"wordFamily":["strong (adj.)","strongly (adv.)","strengthen (v.)"],"synonyms":[],"antonyms":["weakness"],"tipVi":"Nghĩa chỉ thể lực thường không đếm được; nghĩa chỉ thế mạnh có thể đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tongue', 'en-b1-20', 'tongue', '/tʌŋ/', 'B1', 'lưỡi; tiếng; ngôn ngữ', 'n.', NULL, 'Đồng nghĩa: language', 'Nghĩa "ngôn ngữ" của "tongue" thường xuất hiện trong các cụm từ như "mother tongue".', 'I burned my tongue on the hot soup.', NULL, 'Tôi đã bị bỏng lưỡi vì bát súp nóng.', '{"wordId":"tongue","ukIpa":"/tʌŋ/","usIpa":"/tʌŋ/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"the soft organ in your mouth used for tasting and speaking","vi":"lưỡi"},{"pos":"n.","en":"a language used by a particular community","vi":"tiếng; ngôn ngữ"}],"examples":[{"en":"I burned my tongue on the hot soup.","vi":"Tôi đã bị bỏng lưỡi vì bát súp nóng.","audioKind":"ex"},{"en":"Children who receive early education in their mother tongue may develop stronger foundations for learning other languages.","vi":"Trẻ em được giáo dục sớm bằng tiếng mẹ đẻ có thể xây dựng nền tảng vững chắc hơn khi học các ngôn ngữ khác.","audioKind":"ex2"}],"collocations":[{"en":"mother tongue","vi":"tiếng mẹ đẻ"},{"en":"stick out your tongue","vi":"thè lưỡi ra"},{"en":"bite your tongue","vi":"cắn chặt môi (để nhịn nói)"},{"en":"on the tip of your tongue","vi":"sắp nói ra đến miệng nhưng quên mất"}],"wordFamily":[],"synonyms":["language"],"antonyms":[],"tipVi":"Nghĩa \"ngôn ngữ\" của \"tongue\" thường xuất hiện trong các cụm từ như \"mother tongue\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sex', 'en-b1-20', 'sex', '/seks/', 'B1', 'giới tính sinh học; quan hệ tình dục; phân định giới tính', 'n.', 'sexual (adj.), sexually (adv.), sexuality (n.)', NULL, 'sex nhấn mạnh giới tính sinh học; gender thường thiên về giới tính xã hội.', 'The vet checked the sex of our new kitten.', NULL, 'Bác sĩ thú y đã kiểm tra giới tính của chú mèo con mới của chúng tôi.', '{"wordId":"sex","ukIpa":"/seks/","usIpa":"/seks/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"Biological classification based on reproductive and other physical characteristics.","vi":"giới tính sinh học"},{"pos":"n.","en":"Physical activity involving sexual intimacy.","vi":"quan hệ tình dục"},{"pos":"v.","en":"To identify the biological sex of an animal.","vi":"phân định giới tính"}],"examples":[{"en":"The vet checked the sex of our new kitten.","vi":"Bác sĩ thú y đã kiểm tra giới tính của chú mèo con mới của chúng tôi.","audioKind":"ex"},{"en":"Researchers examined whether biological sex influenced participants'' responses to the treatment in the clinical study.","vi":"Các nhà nghiên cứu đã xem xét liệu giới tính sinh học có ảnh hưởng đến phản ứng của người tham gia đối với phương pháp điều trị trong nghiên cứu lâm sàng hay không.","audioKind":"ex2"}],"collocations":[{"en":"biological sex","vi":"giới tính sinh học"},{"en":"sex differences","vi":"sự khác biệt giới tính"},{"en":"sex education","vi":"giáo dục giới tính"},{"en":"determine the sex","vi":"xác định giới tính"}],"wordFamily":["sexual (adj.)","sexually (adv.)","sexuality (n.)"],"synonyms":[],"antonyms":[],"tipVi":"sex nhấn mạnh giới tính sinh học; gender thường thiên về giới tính xã hội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_virus', 'en-b1-20', 'virus', '/ˈvaɪrəs/', 'B1', 'vi-rút; tác nhân truyền nhiễm nhỏ sinh sôi bên trong tế bào sống; mã độc máy tính lây lan bằng cách nhiễm vào các tệp tin hoặc chương trình', 'n.', 'viral (adj.), antiviral (adj.)', NULL, 'virus là vi-rút, bacterium là vi khuẩn; hai từ này không thể dùng thay thế cho nhau.', 'The doctor said a virus was causing my cough.', NULL, 'Bác sĩ nói một loại vi-rút đang làm tôi bị ho.', '{"wordId":"virus","ukIpa":"/ˈvaɪrəs/","usIpa":"/ˈvaɪrəs/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A tiny infectious agent that reproduces inside living cells","vi":"vi-rút; tác nhân truyền nhiễm nhỏ sinh sôi bên trong tế bào sống"},{"pos":"n.","en":"Harmful computer code that spreads by infecting files or programs","vi":"mã độc máy tính lây lan bằng cách nhiễm vào các tệp tin hoặc chương trình"}],"examples":[{"en":"The doctor said a virus was causing my cough.","vi":"Bác sĩ nói một loại vi-rút đang làm tôi bị ho.","audioKind":"ex"},{"en":"Public health campaigns can limit the spread of a virus by encouraging vaccination and regular handwashing.","vi":"Các chiến dịch y tế công cộng có thể hạn chế sự lây lan của vi-rút bằng cách khuyến khích tiêm chủng và rửa tay thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"spread a virus","vi":"lây lan vi-rút"},{"en":"computer virus","vi":"vi-rút máy tính"},{"en":"virus infection","vi":"nhiễm vi-rút"}],"wordFamily":["viral (adj.)","antiviral (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"virus là vi-rút, bacterium là vi khuẩn; hai từ này không thể dùng thay thế cho nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_injure', 'en-b1-20', 'injure', '/ˈɪndʒər/', 'B1', 'làm bị thương; gây tổn hại thân thể', 'v.', 'injury (n.), injured (adj.)', 'Đồng nghĩa: hurt, harm', 'injure thường chỉ người hoặc động vật bị thương; làm hư hỏng đồ vật thường dùng damage.', 'You could injure your back lifting that heavy box.', NULL, 'Bạn có thể làm đau lưng khi khiêng chiếc hộp nặng đó.', '{"wordId":"injure","ukIpa":"/ˈɪndʒə/","usIpa":"/ˈɪndʒər/","cefr":"B1","topic":"health","senses":[{"pos":"v.","en":"to cause physical harm to a person or animal","vi":"làm bị thương; gây tổn hại thân thể"}],"examples":[{"en":"You could injure your back lifting that heavy box.","vi":"Bạn có thể làm đau lưng khi khiêng chiếc hộp nặng đó.","audioKind":"ex"},{"en":"Employers should provide safety training to reduce the risk of workers injuring themselves while operating machinery.","vi":"Người sử dụng lao động nên cung cấp đào tạo an toàn để giảm nguy cơ công nhân tự làm bị thương khi vận hành máy móc.","audioKind":"ex2"}],"collocations":[{"en":"injure your knee","vi":"bị thương đầu gối"},{"en":"seriously injured","vi":"bị thương nặng"},{"en":"injure yourself","vi":"làm bản thân bị thương"}],"wordFamily":["injury (n.)","injured (adj.)"],"synonyms":["hurt","harm"],"antonyms":[],"tipVi":"injure thường chỉ người hoặc động vật bị thương; làm hư hỏng đồ vật thường dùng damage.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yoga', 'en-b1-20', 'yoga', '/ˈjoʊɡə/', 'B1', 'bài tập yoga; môn yoga', 'n.', NULL, NULL, 'Tập yoga dùng động từ do hoặc practise yoga, không dùng play.', 'She does yoga on a mat beside the window.', NULL, 'Cô ấy tập yoga trên một tấm thảm cạnh cửa sổ.', '{"wordId":"yoga","ukIpa":"/ˈjəʊɡə/","usIpa":"/ˈjoʊɡə/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A practice combining body positions, controlled breathing, and mental focus.","vi":"bài tập yoga; môn yoga"}],"examples":[{"en":"She does yoga on a mat beside the window.","vi":"Cô ấy tập yoga trên một tấm thảm cạnh cửa sổ.","audioKind":"ex"},{"en":"Offering yoga classes in community centres may help residents manage stress and maintain flexibility.","vi":"Việc cung cấp các lớp học yoga tại các trung tâm cộng đồng có thể giúp cư dân giải tỏa căng thẳng và duy trì độ dẻo dai.","audioKind":"ex2"}],"collocations":[{"en":"do yoga","vi":"tập yoga"},{"en":"yoga mat","vi":"thảm tập yoga"},{"en":"yoga instructor","vi":"huấn luyện viên yoga"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tập yoga dùng động từ do hoặc practise yoga, không dùng play.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_physically', 'en-b1-20', 'physically', '/ˈfɪzɪkli/', 'B1', 'về mặt thể chất; về thể lực; thực tế; trên thực tế', 'adv.', 'physical (adj.), physicality (n.)', 'Trái nghĩa: mentally', 'Khi nhấn mạnh khía cạnh cơ thể, từ này thường được đặt đối lập với mentally.', 'After moving those boxes, I felt physically exhausted.', NULL, 'Sau khi chuyển những chiếc hộp đó, tôi cảm thấy kiệt sức về thể xác.', '{"wordId":"physically","ukIpa":"/ˈfɪzɪkli/","usIpa":"/ˈfɪzɪkli/","cefr":"B1","topic":"health","senses":[{"pos":"adv.","en":"In a way related to the body or physical effort.","vi":"về mặt thể chất; về thể lực"},{"pos":"adv.","en":"In a real, material way rather than virtually or theoretically.","vi":"thực tế; trên thực tế"}],"examples":[{"en":"After moving those boxes, I felt physically exhausted.","vi":"Sau khi chuyển những chiếc hộp đó, tôi cảm thấy kiệt sức về thể xác.","audioKind":"ex"},{"en":"Physically active children often develop healthier habits that continue into adulthood, reducing their risk of chronic disease.","vi":"Trẻ em thường xuyên vận động thường phát triển các thói quen lành mạnh kéo dài đến tuổi trưởng thành, giúp giảm nguy cơ mắc bệnh mãn tính.","audioKind":"ex2"}],"collocations":[{"en":"physically active","vi":"năng động về thể chất"},{"en":"physically demanding","vi":"đòi hỏi thể lực"},{"en":"physically present","vi":"có mặt trực tiếp"}],"wordFamily":["physical (adj.)","physicality (n.)"],"synonyms":[],"antonyms":["mentally"],"tipVi":"Khi nhấn mạnh khía cạnh cơ thể, từ này thường được đặt đối lập với mentally.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suffer', 'en-b1-20', 'suffer', '/ˈsʌfɚ/', 'B1', 'chịu đựng đau đớn; mắc bệnh; gặp phải; chịu thiệt hại', 'v.', 'suffering (n.), sufferer (n.)', NULL, 'Khi nói về bệnh tật thường dùng ''suffer from''; các từ chỉ tổn thất hay hư hỏng thường đi trực tiếp sau ''suffer''.', 'I suffer from headaches when I skip lunch.', NULL, 'Tôi thường bị đau đầu khi bỏ bữa trưa.', '{"wordId":"suffer","ukIpa":"/ˈsʌfə/","usIpa":"/ˈsʌfɚ/","cefr":"B1","topic":"health","senses":[{"pos":"v.","en":"To experience physical pain or mental distress.","vi":"chịu đựng đau đớn; mắc bệnh"},{"pos":"v.","en":"To experience something harmful or become worse.","vi":"gặp phải; chịu thiệt hại"}],"examples":[{"en":"I suffer from headaches when I skip lunch.","vi":"Tôi thường bị đau đầu khi bỏ bữa trưa.","audioKind":"ex"},{"en":"Small businesses often suffer financial losses when major roadworks prevent customers from reaching their premises.","vi":"Các doanh nghiệp nhỏ thường chịu tổn thất tài chính khi các công trình giao thông lớn cản trở khách hàng đến cửa hàng.","audioKind":"ex2"}],"collocations":[{"en":"suffer from headaches","vi":"bị những cơn đau đầu hành hạ"},{"en":"suffer a loss","vi":"chịu tổn thất"},{"en":"suffer damage","vi":"bị hư hỏng"},{"en":"suffer badly","vi":"chịu ảnh hưởng nặng nề"}],"wordFamily":["suffering (n.)","sufferer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói về bệnh tật thường dùng ''suffer from''; các từ chỉ tổn thất hay hư hỏng thường đi trực tiếp sau ''suffer''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relaxing', 'en-b1-20', 'relaxing', '/rɪˈlæksɪŋ/', 'B1', 'thư giãn; dễ chịu; thoải mái', 'adj.', 'relax (v.), relaxed (adj.), relaxation (n.)', 'Đồng nghĩa: soothing, restful, calming · Trái nghĩa: stressful', '''relaxing'' dùng để mô tả sự vật làm cho người khác thư giãn; ''relaxed'' dùng để mô tả cảm giác thư giãn của con người.', 'A warm bath is wonderfully relaxing after a busy day.', NULL, 'Ngâm mình trong bồn nước ấm mang lại cảm giác vô cùng dễ chịu sau một ngày bận rộn.', '{"wordId":"relaxing","ukIpa":"/rɪˈlæksɪŋ/","usIpa":"/rɪˈlæksɪŋ/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"making you feel calm and free from stress","vi":"thư giãn; dễ chịu; thoải mái"}],"examples":[{"en":"A warm bath is wonderfully relaxing after a busy day.","vi":"Ngâm mình trong bồn nước ấm mang lại cảm giác vô cùng dễ chịu sau một ngày bận rộn.","audioKind":"ex"},{"en":"Access to relaxing green spaces may improve mental wellbeing among residents of densely populated urban areas.","vi":"Khả năng tiếp cận các không gian xanh thư giãn có thể cải thiện sức khỏe tinh thần cho cư dân ở các khu đô thị đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"relaxing atmosphere","vi":"bầu không khí thư giãn"},{"en":"relaxing music","vi":"nhạc nhẹ nhàng thư giãn"},{"en":"relaxing holiday","vi":"kỳ nghỉ thư thái"}],"wordFamily":["relax (v.)","relaxed (adj.)","relaxation (n.)"],"synonyms":["soothing","restful","calming"],"antonyms":["stressful"],"tipVi":"''relaxing'' dùng để mô tả sự vật làm cho người khác thư giãn; ''relaxed'' dùng để mô tả cảm giác thư giãn của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unhealthy', 'en-b1-20', 'unhealthy', '/ʌnˈhelθi/', 'B1', 'có hại cho sức khỏe; không lành mạnh; không khỏe mạnh; ốm yếu; bất thường; độc hại', 'adj.', 'health (n.), healthy (adj.), unhealthily (adv.)', 'Đồng nghĩa: harmful · Trái nghĩa: healthy', 'unhealthy có thể chỉ sự vật gây hại cho sức khỏe, hoặc chỉ tình trạng cơ thể kém.', 'Eating only biscuits for dinner is an unhealthy habit.', NULL, 'Chỉ ăn bánh quy vào bữa tối là một thói quen không lành mạnh.', '{"wordId":"unhealthy","ukIpa":"/ʌnˈhelθi/","usIpa":"/ʌnˈhelθi/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"likely to damage physical or mental health","vi":"có hại cho sức khỏe; không lành mạnh"},{"pos":"adj.","en":"not in good physical condition","vi":"không khỏe mạnh; ốm yếu"},{"pos":"adj.","en":"harmful or excessive in a way that causes problems","vi":"bất thường; độc hại"}],"examples":[{"en":"Eating only biscuits for dinner is an unhealthy habit.","vi":"Chỉ ăn bánh quy vào bữa tối là một thói quen không lành mạnh.","audioKind":"ex"},{"en":"Advertising unhealthy foods to children may contribute to poor dietary habits and higher rates of obesity.","vi":"Việc quảng cáo thực phẩm không lành mạnh cho trẻ em có thể góp phần tạo ra thói quen ăn uống kém và tỷ lệ béo phì cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"an unhealthy diet","vi":"chế độ ăn uống không lành mạnh"},{"en":"an unhealthy lifestyle","vi":"lối sống không lành mạnh"},{"en":"unhealthy competition","vi":"cạnh tranh không lành mạnh"},{"en":"an unhealthy obsession","vi":"sự ám ảnh độc hại"}],"wordFamily":["health (n.)","healthy (adj.)","unhealthily (adv.)"],"synonyms":["harmful"],"antonyms":["healthy"],"tipVi":"unhealthy có thể chỉ sự vật gây hại cho sức khỏe, hoặc chỉ tình trạng cơ thể kém.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blind', 'en-b1-20', 'blind', '/blaɪnd/', 'B1', 'khiếm thị; mù; mù quáng; không nhận thức được (vấn đề, thực tế); rèm cửa; bạt che', 'adj.', 'blindness (n.), blindly (adv.)', 'Trái nghĩa: sighted', 'blind to có nghĩa là không nhận thức được hoặc làm ngơ; nghĩa rèm cửa là danh từ đếm được.', 'My blind uncle reads stories using his fingertips.', NULL, 'Người chú khiếm thị của tôi đọc truyện bằng các đầu ngón tay.', '{"wordId":"blind","ukIpa":"/blaɪnd/","usIpa":"/blaɪnd/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"Unable to see.","vi":"khiếm thị; mù"},{"pos":"adj.","en":"Unwilling or unable to recognize facts or problems.","vi":"mù quáng; không nhận thức được (vấn đề, thực tế)"},{"pos":"n.","en":"A window covering that can be raised or adjusted.","vi":"rèm cửa; bạt che"}],"examples":[{"en":"My blind uncle reads stories using his fingertips.","vi":"Người chú khiếm thị của tôi đọc truyện bằng các đầu ngón tay.","audioKind":"ex"},{"en":"Public transport systems should provide clear audio announcements to help blind passengers travel safely and independently.","vi":"Các hệ thống giao thông công cộng nên cung cấp thông báo âm thanh rõ ràng để giúp hành khách khiếm thị đi lại an toàn và độc lập.","audioKind":"ex2"}],"collocations":[{"en":"blind passengers","vi":"hành khách khiếm thị"},{"en":"blind faith","vi":"lòng tin mù quáng"},{"en":"blind to the risks","vi":"làm ngơ trước rủi ro"},{"en":"roller blind","vi":"rèm cuốn"}],"wordFamily":["blindness (n.)","blindly (adv.)"],"synonyms":[],"antonyms":["sighted"],"tipVi":"blind to có nghĩa là không nhận thức được hoặc làm ngơ; nghĩa rèm cửa là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_20_1', 'en-b1-20', 'Cách dùng “relaxing” (adj.) — thư giãn; dễ chịu; thoải mái', 'relaxing atmosphere  ·  relaxing music  ·  relaxing holiday', '''relaxing'' dùng để mô tả sự vật làm cho người khác thư giãn; ''relaxed'' dùng để mô tả cảm giác thư giãn của con người.', 'Họ từ (Word Family): relax (v.), relaxed (adj.), relaxation (n.) | Đồng nghĩa: soothing, restful, calming · Trái nghĩa: stressful', '[{"hanzi":"A warm bath is wonderfully relaxing after a busy day.","pinyin":"","meaning":"Ngâm mình trong bồn nước ấm mang lại cảm giác vô cùng dễ chịu sau một ngày bận rộn."},{"hanzi":"Access to relaxing green spaces may improve mental wellbeing among residents of densely populated urban areas.","pinyin":"","meaning":"Khả năng tiếp cận các không gian xanh thư giãn có thể cải thiện sức khỏe tinh thần cho cư dân ở các khu đô thị đông đúc."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_20_2', 'en-b1-20', 'Cách dùng “suffer” (v.) — chịu đựng đau đớn; mắc bệnh', 'suffer from headaches  ·  suffer a loss  ·  suffer damage', 'Khi nói về bệnh tật thường dùng ''suffer from''; các từ chỉ tổn thất hay hư hỏng thường đi trực tiếp sau ''suffer''.', 'Họ từ (Word Family): suffering (n.), sufferer (n.)', '[{"hanzi":"I suffer from headaches when I skip lunch.","pinyin":"","meaning":"Tôi thường bị đau đầu khi bỏ bữa trưa."},{"hanzi":"Small businesses often suffer financial losses when major roadworks prevent customers from reaching their premises.","pinyin":"","meaning":"Các doanh nghiệp nhỏ thường chịu tổn thất tài chính khi các công trình giao thông lớn cản trở khách hàng đến cửa hàng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_20_3', 'en-b1-20', 'Cách dùng “sickness” (n.) — bệnh tật; sự ốm đau', 'travel sickness  ·  morning sickness  ·  altitude sickness', 'Thông thường là danh từ không đếm được; trong tiếng Anh-Anh, từ này còn chỉ cảm giác buồn nôn hoặc nôn mửa.', 'Họ từ (Word Family): sick (adj.), sickly (adj.), sicken (v.) | Đồng nghĩa: illness · Trái nghĩa: health', '[{"hanzi":"Several children missed school because of sickness this week.","pinyin":"","meaning":"Nhiều đứa trẻ đã phải nghỉ học vì ốm đau trong tuần này."},{"hanzi":"Employers can reduce absence due to sickness by improving ventilation and encouraging staff to stay home when unwell.","pinyin":"","meaning":"Các nhà tuyển dụng có thể giảm bớt tình trạng nghỉ làm do ốm đau bằng cách cải thiện thông gió và khuyến khích nhân viên ở nhà khi không khỏe."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_20_4', 'en-b1-20', 'Cách dùng “treatment” (n.) — sự điều trị; phép chữa bệnh', 'receive treatment  ·  medical treatment  ·  equal treatment', 'Nói chung về việc điều trị thì không đếm được; khi chỉ một liệu pháp cụ thể thì dùng a treatment.', 'Họ từ (Word Family): treat (v.), treatable (adj.)', '[{"hanzi":"After treatment, her injured ankle felt much better.","pinyin":"","meaning":"Sau khi điều trị, cổ chân bị thương của cô ấy đã đỡ hơn rất nhiều."},{"hanzi":"Access to affordable medical treatment is essential for reducing health inequalities between wealthy and disadvantaged communities.","pinyin":"","meaning":"Việc tiếp cận dịch vụ y tế phải chăng là điều cốt yếu để giảm bớt sự bất bình đẳng về y tế giữa các cộng đồng giàu có và kém may mắn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_20_1', 'en-b1-20', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_20_1_1', 'ten_b1_20_1', 'exhausted', 'After carrying those boxes upstairs, I felt completely exhausted.', 'After carrying those boxes upstairs, I felt completely exhausted.', '/ɪɡˈzɔːstɪd/', 'Sau khi khiêng mấy cái thùng đó lên lầu, tôi cảm thấy kiệt sức hoàn toàn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_20_1_2', 'ten_b1_20_1', 'muscle', 'I pulled a muscle while lifting a heavy box.', 'I pulled a muscle while lifting a heavy box.', '/ˈmʌsəl/', 'Tôi bị căng cơ khi nhấc một chiếc hộp nặng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_20_1_3', 'ten_b1_20_1', 'sickness', 'Several children missed school because of sickness this week.', 'Several children missed school because of sickness this week.', '/ˈsɪknəs/', 'Nhiều đứa trẻ đã phải nghỉ học vì ốm đau trong tuần này.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_20_1_4', 'ten_b1_20_1', 'spinach', 'I added fresh spinach to the soup before dinner.', 'I added fresh spinach to the soup before dinner.', '/ˈspɪnɪtʃ/', 'Tôi đã cho thêm rau bina tươi vào món súp trước bữa tối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_20_1_5', 'ten_b1_20_1', 'allergic', 'I am allergic to cats, so I keep my distance.', 'I am allergic to cats, so I keep my distance.', '/əˈlɝːdʒɪk/', 'Tôi bị dị ứng với mèo nên tôi luôn giữ khoảng cách.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_20_1_6', 'ten_b1_20_1', 'breathe', 'Sit by the window and breathe slowly for a minute.', 'Sit by the window and breathe slowly for a minute.', '/briːð/', 'Hãy ngồi bên cửa sổ và hít thở nhẹ nhàng trong một phút.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_20_1_7', 'ten_b1_20_1', 'alcohol', 'This restaurant serves fresh juice but does not sell alcohol.', 'This restaurant serves fresh juice but does not sell alcohol.', '/ˈælkəhɔːl/', 'Nhà hàng này phục vụ nước ép tươi nhưng không bán đồ uống có cồn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
