INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_20_1_1', 'en-b1-20', 'ten_b1_20_1', 'listening', 'listening', 'After carrying those boxes upstairs, I felt completely exhausted.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi bị dị ứng với mèo nên tôi luôn giữ khoảng cách.","Hãy ngồi bên cửa sổ và hít thở nhẹ nhàng trong một phút.","Sau khi khiêng mấy cái thùng đó lên lầu, tôi cảm thấy kiệt sức hoàn toàn.","Tôi thường bị đau đầu khi bỏ bữa trưa."]'::jsonb, 2, 'After carrying those boxes upstairs, I felt completely exhausted. → Sau khi khiêng mấy cái thùng đó lên lầu, tôi cảm thấy kiệt sức hoàn toàn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_20_1_2', 'en-b1-20', 'ten_b1_20_1', 'listening', 'listening', 'I pulled a muscle while lifting a heavy box.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã bị bỏng lưỡi vì bát súp nóng.","Tôi bị dị ứng với mèo nên tôi luôn giữ khoảng cách.","Cô ấy tập yoga trên một tấm thảm cạnh cửa sổ.","Tôi bị căng cơ khi nhấc một chiếc hộp nặng."]'::jsonb, 3, 'I pulled a muscle while lifting a heavy box. → Tôi bị căng cơ khi nhấc một chiếc hộp nặng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_20_1_3', 'en-b1-20', 'ten_b1_20_1', 'listening', 'listening', 'Several children missed school because of sickness this week.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhiều đứa trẻ đã phải nghỉ học vì ốm đau trong tuần này.","Bụi từ tấm thảm cũ làm tôi hắt hơi.","Bạn có thể làm đau lưng khi khiêng chiếc hộp nặng đó.","Tôi bị dị ứng với mèo nên tôi luôn giữ khoảng cách."]'::jsonb, 0, 'Several children missed school because of sickness this week. → Nhiều đứa trẻ đã phải nghỉ học vì ốm đau trong tuần này.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_20_2', 'en-b1-20', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_20_2_1', 'ten_b1_20_2', 'exhausted', 'Employees who are constantly exhausted may struggle to concentrate, increasing the risk of mistakes at work.', 'Employees who are constantly exhausted may struggle to concentrate, increasing the risk of mistakes at work.', '/ɪɡˈzɔːstɪd/', 'Những nhân viên liên tục bị kiệt sức có thể gặp khó khăn trong việc tập trung, làm gia tăng nguy cơ mắc lỗi trong công việc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_20_2_2', 'ten_b1_20_2', 'muscle', 'Regular strength training builds muscle and helps older adults maintain balance and independence in daily life.', 'Regular strength training builds muscle and helps older adults maintain balance and independence in daily life.', '/ˈmʌsəl/', 'Tập luyện sức mạnh đều đặn giúp phát triển cơ bắp và hỗ trợ người cao tuổi duy trì khả năng giữ thăng bằng cũng như sự độc lập trong đời sống hàng ngày.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_20_2_3', 'ten_b1_20_2', 'sickness', 'Employers can reduce absence due to sickness by improving ventilation and encouraging staff to stay home when unwell.', 'Employers can reduce absence due to sickness by improving ventilation and encouraging staff to stay home when unwell.', '/ˈsɪknəs/', 'Các nhà tuyển dụng có thể giảm bớt tình trạng nghỉ làm do ốm đau bằng cách cải thiện thông gió và khuyến khích nhân viên ở nhà khi không khỏe.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_20_2_4', 'ten_b1_20_2', 'spinach', 'Leafy vegetables such as spinach provide nutrients that support a healthy, balanced diet.', 'Leafy vegetables such as spinach provide nutrients that support a healthy, balanced diet.', '/ˈspɪnɪtʃ/', 'Các loại rau có lá xanh như rau bina cung cấp các dưỡng chất thiết yếu cho một chế độ ăn uống lành mạnh và cân đối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_20_2_5', 'ten_b1_20_2', 'allergic', 'Restaurants should provide accurate ingredient information to protect customers who are allergic to common foods.', 'Restaurants should provide accurate ingredient information to protect customers who are allergic to common foods.', '/əˈlɝːdʒɪk/', 'Các nhà hàng nên cung cấp thông tin thành phần chính xác để bảo vệ những khách hàng bị dị ứng với các loại thực phẩm phổ biến.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_20_2_6', 'ten_b1_20_2', 'breathe', 'People living near busy roads often breathe polluted air, which can increase their risk of respiratory illness.', 'People living near busy roads often breathe polluted air, which can increase their risk of respiratory illness.', '/briːð/', 'Những người sống gần các con đường tấp nập thường hít phải không khí ô nhiễm, điều này có thể làm tăng nguy cơ mắc bệnh đường hô hấp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_20_2_1', 'en-b1-20', 'ten_b1_20_2', 'listening', 'listening', 'Employees who are constantly exhausted may struggle to concentrate, increasing the risk of mistakes at work.', NULL, 'Trong câu vừa nghe, từ “exhausted” mang nghĩa nào sau đây?', '["sự tạ ơn; lời cầu nguyện cảm ơn","đóng băng; làm đông lạnh","kiệt sức; mệt lử","chật; bó sát; chặt"]'::jsonb, 2, '“exhausted” (/ɪɡˈzɔːstɪd/): kiệt sức; mệt lử. Câu đầy đủ: Employees who are constantly exhausted may struggle to concentrate, increasing the risk of mistakes at work.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_20_2_2', 'en-b1-20', 'ten_b1_20_2', 'listening', 'listening', 'Regular strength training builds muscle and helps older adults maintain balance and independence in daily life.', NULL, 'Trong câu vừa nghe, từ “muscle” mang nghĩa nào sau đây?', '["gần đây; dạo này","hải quân","cơ; bắp thịt","tỷ lệ phần trăm; phần trăm"]'::jsonb, 2, '“muscle” (/ˈmʌsəl/): cơ; bắp thịt. Câu đầy đủ: Regular strength training builds muscle and helps older adults maintain balance and independence in daily life.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
