INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_20_2', 'en-b1-20', NULL, 'comprehensive_test', 'listening', 'I pulled a muscle while lifting a heavy box.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chỉ ăn bánh quy vào bữa tối là một thói quen không lành mạnh.","Ngâm mình trong bồn nước ấm mang lại cảm giác vô cùng dễ chịu sau một ngày bận rộn.","Sau khi điều trị, cổ chân bị thương của cô ấy đã đỡ hơn rất nhiều.","Tôi bị căng cơ khi nhấc một chiếc hộp nặng."]'::jsonb, 3, 'I pulled a muscle while lifting a heavy box. → Tôi bị căng cơ khi nhấc một chiếc hộp nặng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_20_3', 'en-b1-20', NULL, 'comprehensive_test', 'listening', 'sickness', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự căng thẳng tinh thần; áp lực tinh thần","xa hơn (về khoảng cách)","người biên tập; chủ biên","bệnh tật; sự ốm đau"]'::jsonb, 3, 'sickness (/ˈsɪknəs/) → bệnh tật; sự ốm đau; sự buồn nôn; chứng nôn mửa', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_20_4', 'en-b1-20', NULL, 'comprehensive_test', 'listening', 'I added fresh spinach to the soup before dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy tập yoga trên một tấm thảm cạnh cửa sổ.","Tôi đã phải dùng hết sức lực mới nhấc nổi chiếc vali đó.","Nhà hàng này phục vụ nước ép tươi nhưng không bán đồ uống có cồn.","Tôi đã cho thêm rau bina tươi vào món súp trước bữa tối."]'::jsonb, 3, 'I added fresh spinach to the soup before dinner. → Tôi đã cho thêm rau bina tươi vào món súp trước bữa tối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_20_5', 'en-b1-20', NULL, 'comprehensive_test', 'listening', 'allergic', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bị dị ứng; có dị ứng với","thằn lằn; kỳ nhông","truyền thống; tập quán","ngực; khoang ngực"]'::jsonb, 0, 'allergic (/əˈlɝːdʒɪk/) → bị dị ứng; có dị ứng với; do dị ứng gây ra', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_20_6', 'en-b1-20', NULL, 'comprehensive_test', 'listening', 'Sit by the window and breathe slowly for a minute.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã cho thêm rau bina tươi vào món súp trước bữa tối.","Hãy ngồi bên cửa sổ và hít thở nhẹ nhàng trong một phút.","Sau khi chuyển những chiếc hộp đó, tôi cảm thấy kiệt sức về thể xác.","Ngâm mình trong bồn nước ấm mang lại cảm giác vô cùng dễ chịu sau một ngày bận rộn."]'::jsonb, 1, 'Sit by the window and breathe slowly for a minute. → Hãy ngồi bên cửa sổ và hít thở nhẹ nhàng trong một phút.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
