INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_20_8', 'en-b1-20', NULL, 'comprehensive_test', 'listening', 'Dust from the old rug made me sneeze.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi phải mất mấy ngày mới bình phục hẳn sau trận cúm.","Nhà hàng này phục vụ nước ép tươi nhưng không bán đồ uống có cồn.","Bụi từ tấm thảm cũ làm tôi hắt hơi.","Nhiều đứa trẻ đã phải nghỉ học vì ốm đau trong tuần này."]'::jsonb, 2, 'Dust from the old rug made me sneeze. → Bụi từ tấm thảm cũ làm tôi hắt hơi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
