INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_20_18', 'en-b1-20', NULL, 'comprehensive_test', 'reading', NULL, 'Employees who are constantly exhausted may struggle to concentrate, increasing the risk of mistakes at work.', 'Dựa vào câu trên, từ “exhausted” có nghĩa phù hợp nhất là gì?', '["một phần; ở một mức độ nào đó","lỗi; sai sót","kiệt sức; mệt lử","lễ hội hóa trang; ngày hội"]'::jsonb, 2, 'exhausted: kiệt sức; mệt lử; cạn kiệt; khô cạn. Dịch cả câu: Những nhân viên liên tục bị kiệt sức có thể gặp khó khăn trong việc tập trung, làm gia tăng nguy cơ mắc lỗi trong công việc.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_20_19', 'en-b1-20', NULL, 'comprehensive_test', 'reading', NULL, 'Regular strength training builds muscle and helps older adults maintain balance and independence in daily life.', 'Dựa vào câu trên, từ “muscle” có nghĩa phù hợp nhất là gì?', '["cơ; bắp thịt","quyền sử dụng; cơ hội tiếp cận","nữ nhân viên dọn phòng; nữ giúp việc","một cách tự nhiên; theo tự nhiên"]'::jsonb, 0, 'muscle: cơ; bắp thịt; sức mạnh; thế lực. Dịch cả câu: Tập luyện sức mạnh đều đặn giúp phát triển cơ bắp và hỗ trợ người cao tuổi duy trì khả năng giữ thăng bằng cũng như sự độc lập trong đời sống hàng ngày.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_20_20', 'en-b1-20', NULL, 'comprehensive_test', 'reading', NULL, 'Employers can reduce absence due to sickness by improving ventilation and encouraging staff to stay home when unwell.', 'Dựa vào câu trên, từ “sickness” có nghĩa phù hợp nhất là gì?', '["làn đường","bệnh tật; sự ốm đau","giải đấu; cuộc thi đấu","lỗi thời; theo kiểu cũ"]'::jsonb, 1, 'sickness: bệnh tật; sự ốm đau; sự buồn nôn; chứng nôn mửa. Dịch cả câu: Các nhà tuyển dụng có thể giảm bớt tình trạng nghỉ làm do ốm đau bằng cách cải thiện thông gió và khuyến khích nhân viên ở nhà khi không khỏe.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_20_21', 'en-b1-20', NULL, 'comprehensive_test', 'reading', NULL, 'Leafy vegetables such as spinach provide nutrients that support a healthy, balanced diet.', 'Dựa vào câu trên, từ “spinach” có nghĩa phù hợp nhất là gì?', '["sự tự tin; niềm tin","buồn bã; lo lắng; thất vọng","rau bina; cải bó xôi","nhà hóa học"]'::jsonb, 2, 'spinach: rau bina; cải bó xôi. Dịch cả câu: Các loại rau có lá xanh như rau bina cung cấp các dưỡng chất thiết yếu cho một chế độ ăn uống lành mạnh và cân đối.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_20_22', 'en-b1-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thư giãn; dễ chịu; thoải mái”', '["net","base","relaxing","phrase"]'::jsonb, 2, 'thư giãn; dễ chịu; thoải mái → relaxing (/rɪˈlæksɪŋ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_20_23', 'en-b1-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có hại cho sức khỏe; không lành mạnh”', '["require","unhealthy","national","pony"]'::jsonb, 1, 'có hại cho sức khỏe; không lành mạnh → unhealthy (/ʌnˈhelθi/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_20_24', 'en-b1-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khiếm thị; mù”', '["blind","brunch","physically","political"]'::jsonb, 0, 'khiếm thị; mù → blind (/blaɪnd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-21', 'en', 'Bài 21: Sức khỏe & Cơ thể (3) - CEFR B1', 'CEFR B1', 'B1 · Sức khỏe', '22 từ vựng Tiếng Anh CEFR B1 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3021, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_painkiller', 'en-b1-21', 'painkiller', '/ˈpeɪnkɪlər/', 'B1', 'thuốc giảm đau', 'n.', 'pain (n.), painkilling (adj.), painful (adj.), painless (adj.)', 'Đồng nghĩa: analgesic', 'Danh từ đếm được; “uống thuốc giảm đau” dùng take a painkiller.', 'The pharmacist explained when I should take the painkiller.', NULL, 'Dược sĩ đã giải thích thời điểm tôi nên uống thuốc giảm đau.', '{"wordId":"painkiller","ukIpa":"/ˈpeɪnkɪlə/","usIpa":"/ˈpeɪnkɪlər/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"a medicine that reduces or removes pain","vi":"thuốc giảm đau"}],"examples":[{"en":"The pharmacist explained when I should take the painkiller.","vi":"Dược sĩ đã giải thích thời điểm tôi nên uống thuốc giảm đau.","audioKind":"ex"},{"en":"Patients should receive clear guidance on using painkillers safely, including information about possible side effects.","vi":"Bệnh nhân nên nhận được hướng dẫn rõ ràng về việc sử dụng thuốc giảm đau an toàn, bao gồm cả thông tin về các tác dụng phụ có thể xảy ra.","audioKind":"ex2"}],"collocations":[{"en":"take a painkiller","vi":"uống thuốc giảm đau"},{"en":"prescribe painkillers","vi":"kê đơn thuốc giảm đau"},{"en":"over-the-counter painkillers","vi":"thuốc giảm đau không kê đơn"}],"wordFamily":["pain (n.)","painkilling (adj.)","painful (adj.)","painless (adj.)"],"synonyms":["analgesic"],"antonyms":[],"tipVi":"Danh từ đếm được; “uống thuốc giảm đau” dùng take a painkiller.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sunblock', 'en-b1-21', 'sunblock', '/ˈsʌnblɑːk/', 'B1', 'kem chống nắng', 'n.', NULL, 'Đồng nghĩa: sunscreen', 'Thường là danh từ không đếm được; tên gọi không có nghĩa là chống tia cực tím hoàn toàn 100%.', 'Put some sunblock on your shoulders before swimming.', NULL, 'Hãy bôi một ít kem chống nắng lên vai trước khi bơi.', '{"wordId":"sunblock","ukIpa":"/ˈsʌnblɒk/","usIpa":"/ˈsʌnblɑːk/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A cream or lotion that protects skin from sunlight.","vi":"kem chống nắng"}],"examples":[{"en":"Put some sunblock on your shoulders before swimming.","vi":"Hãy bôi một ít kem chống nắng lên vai trước khi bơi.","audioKind":"ex"},{"en":"Using sunblock alongside protective clothing can reduce skin damage during prolonged exposure to sunlight.","vi":"Sử dụng kem chống nắng kết hợp với quần áo bảo hộ có thể làm giảm tổn thương da khi tiếp xúc lâu với ánh nắng mặt trời.","audioKind":"ex2"}],"collocations":[{"en":"apply sunblock","vi":"bôi kem chống nắng"},{"en":"wear sunblock","vi":"thoa kem chống nắng"},{"en":"water-resistant sunblock","vi":"kem chống nắng không thấm nước"}],"wordFamily":[],"synonyms":["sunscreen"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; tên gọi không có nghĩa là chống tia cực tím hoàn toàn 100%.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sight', 'en-b1-21', 'sight', '/saɪt/', 'B1', 'thị lực; thị giác; tầm nhìn; tầm quan sát; cảnh tượng; thắng cảnh', 'n.', 'sighted (adj.), sightless (adj.)', 'Đồng nghĩa: vision, eyesight', 'Thị lực thường không đếm được; khi chỉ các danh thắng, từ này thường ở dạng số nhiều sights.', 'Her sight improved after she got new glasses.', NULL, 'Thị lực của cô ấy đã tốt hơn sau khi cắt kính mới.', '{"wordId":"sight","ukIpa":"/saɪt/","usIpa":"/saɪt/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"The ability to see.","vi":"thị lực; thị giác"},{"pos":"n.","en":"The act of seeing or the area that can be seen.","vi":"tầm nhìn; tầm quan sát"},{"pos":"n.","en":"Something seen, especially something impressive or worth visiting.","vi":"cảnh tượng; thắng cảnh"}],"examples":[{"en":"Her sight improved after she got new glasses.","vi":"Thị lực của cô ấy đã tốt hơn sau khi cắt kính mới.","audioKind":"ex"},{"en":"Regular eye examinations can help preserve sight by detecting problems before they cause permanent damage.","vi":"Việc khám mắt định kỳ có thể giúp bảo vệ thị lực bằng cách phát hiện các vấn đề trước khi chúng gây tổn thương vĩnh viễn.","audioKind":"ex2"}],"collocations":[{"en":"lose one''s sight","vi":"mất thị lực; bị mù"},{"en":"out of sight","vi":"ngoài tầm nhìn"},{"en":"at first sight","vi":"thoạt nhìn; ngay từ cái nhìn đầu tiên"},{"en":"the sights","vi":"các danh thắng"}],"wordFamily":["sighted (adj.)","sightless (adj.)"],"synonyms":["vision","eyesight"],"antonyms":[],"tipVi":"Thị lực thường không đếm được; khi chỉ các danh thắng, từ này thường ở dạng số nhiều sights.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_check-up', 'en-b1-21', 'check-up', '/ˈtʃek ʌp/', 'B1', 'buổi khám sức khỏe tổng quát; sự kiểm tra sức khỏe', 'n.', 'check (v.)', 'Đồng nghĩa: medical examination', 'check-up là danh từ; cụm động từ check up on mang nghĩa xem xét hoặc kiểm tra ai/cái gì.', 'I booked a check-up because I felt unusually tired.', NULL, 'Tôi đã đặt lịch khám sức khỏe vì cảm thấy mệt mỏi bất thường.', '{"wordId":"check-up","ukIpa":"/ˈtʃek ʌp/","usIpa":"/ˈtʃek ʌp/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"a medical examination to assess your general health","vi":"buổi khám sức khỏe tổng quát; sự kiểm tra sức khỏe"}],"examples":[{"en":"I booked a check-up because I felt unusually tired.","vi":"Tôi đã đặt lịch khám sức khỏe vì cảm thấy mệt mỏi bất thường.","audioKind":"ex"},{"en":"Regular check-ups can help doctors detect health problems before they require more expensive treatment.","vi":"Việc kiểm tra sức khỏe định kỳ có thể giúp bác sĩ phát hiện các vấn đề y tế trước khi chúng đòi hỏi các phương pháp điều trị tốn kém hơn.","audioKind":"ex2"}],"collocations":[{"en":"annual check-up","vi":"khám sức khỏe hàng năm"},{"en":"dental check-up","vi":"khám răng định kỳ"},{"en":"routine check-up","vi":"kiểm tra sức khỏe định kỳ"}],"wordFamily":["check (v.)"],"synonyms":["medical examination"],"antonyms":[],"tipVi":"check-up là danh từ; cụm động từ check up on mang nghĩa xem xét hoặc kiểm tra ai/cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sweat', 'en-b1-21', 'sweat', '/swet/', 'B1', 'mồ hôi; đổ mồ hôi; toát mồ hôi', 'n.', 'sweaty (adj.), sweating (n.)', 'Đồng nghĩa: perspiration', 'Mồ hôi thông thường là danh từ không đếm được; có thể dùng a sweat khi nói về một trận ra mồ hôi.', 'Sweat ran down my face during the steep climb.', NULL, 'Mồ hôi túa ra trên mặt tôi trong suốt chặng leo dốc đứng.', '{"wordId":"sweat","ukIpa":"/swet/","usIpa":"/swet/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"Liquid produced by your skin when hot or nervous.","vi":"mồ hôi"},{"pos":"v.","en":"To produce liquid through your skin.","vi":"đổ mồ hôi; toát mồ hôi"}],"examples":[{"en":"Sweat ran down my face during the steep climb.","vi":"Mồ hôi túa ra trên mặt tôi trong suốt chặng leo dốc đứng.","audioKind":"ex"},{"en":"People who exercise in hot weather lose water through sweat and should drink regularly.","vi":"Những người tập thể dục trong thời tiết nóng bức sẽ mất nước qua tuyến mồ hôi và nên uống nước thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"break into a sweat","vi":"bỗng dưng toát mồ hôi"},{"en":"wipe away sweat","vi":"lau mồ hôi"},{"en":"sweat heavily","vi":"đổ mồ hôi đầm đìa"}],"wordFamily":["sweaty (adj.)","sweating (n.)"],"synonyms":["perspiration"],"antonyms":[],"tipVi":"Mồ hôi thông thường là danh từ không đếm được; có thể dùng a sweat khi nói về một trận ra mồ hôi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_breathing', 'en-b1-21', 'breathing', '/ˈbriːðɪŋ/', 'B1', 'sự hô hấp; việc thở', 'n.', 'breathe (v.), breath (n.), breathless (adj.)', 'Đồng nghĩa: respiration', 'breathing vừa đóng vai trò danh từ, vừa là phân từ của từ breathe.', 'After the steep climb, my breathing slowly returned to normal.', NULL, 'Sau đoạn đường dốc đứng, nhịp thở của tôi từ từ trở lại bình thường.', '{"wordId":"breathing","ukIpa":"/ˈbriːðɪŋ/","usIpa":"/ˈbriːðɪŋ/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"the process of taking air into and out of the lungs","vi":"sự hô hấp; việc thở"}],"examples":[{"en":"After the steep climb, my breathing slowly returned to normal.","vi":"Sau đoạn đường dốc đứng, nhịp thở của tôi từ từ trở lại bình thường.","audioKind":"ex"},{"en":"Regular breathing exercises may help students manage stress and improve their concentration during demanding periods of study.","vi":"Các bài tập thở đều đặn có thể giúp học sinh quản lý căng thẳng và cải thiện khả năng tập trung trong những giai đoạn học tập căng thẳng.","audioKind":"ex2"}],"collocations":[{"en":"deep breathing","vi":"thở sâu"},{"en":"breathing exercises","vi":"bài tập hít thở"},{"en":"breathing difficulties","vi":"khó thở"},{"en":"heavy breathing","vi":"tiếng thở hồng hộc"}],"wordFamily":["breathe (v.)","breath (n.)","breathless (adj.)"],"synonyms":["respiration"],"antonyms":[],"tipVi":"breathing vừa đóng vai trò danh từ, vừa là phân từ của từ breathe.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overweight', 'en-b1-21', 'overweight', '/ˌoʊvərˈweɪt/', 'B1', 'quá cân; thừa cân', 'adj.', 'weight (n.), weigh (v.), underweight (adj.)', 'Trái nghĩa: underweight', 'Thường đóng vai trò là tính từ; từ obese dùng để chỉ mức độ béo phì nặng hơn.', 'My suitcase was overweight, so I removed some books.', NULL, 'Vali của tôi đã bị quá cước, vì vậy tôi đã lấy bớt một số cuốn sách ra.', '{"wordId":"overweight","ukIpa":"/ˌəʊvəˈweɪt/","usIpa":"/ˌoʊvərˈweɪt/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"heavier than is considered healthy, suitable, or officially allowed","vi":"quá cân; thừa cân"}],"examples":[{"en":"My suitcase was overweight, so I removed some books.","vi":"Vali của tôi đã bị quá cước, vì vậy tôi đã lấy bớt một số cuốn sách ra.","audioKind":"ex"},{"en":"People who are overweight may benefit from accessible exercise facilities and practical advice on balanced diets.","vi":"Những người thừa cân có thể nhận được nhiều lợi ích từ các cơ sở tập luyện dễ tiếp cận và những lời khuyên thiết thực về chế độ ăn uống cân bằng.","audioKind":"ex2"}],"collocations":[{"en":"be slightly overweight","vi":"hơi thừa cân một chút"},{"en":"overweight luggage","vi":"hành lý quá cước"},{"en":"become overweight","vi":"trở nên thừa cân"}],"wordFamily":["weight (n.)","weigh (v.)","underweight (adj.)"],"synonyms":[],"antonyms":["underweight"],"tipVi":"Thường đóng vai trò là tính từ; từ obese dùng để chỉ mức độ béo phì nặng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heel', 'en-b1-21', 'heel', '/hiːl/', 'B1', 'gót chân; gót giày', 'n.', 'heeled (adj.)', NULL, 'Heel là gót chân hoặc gót giày; heal có nghĩa là chữa lành, hai từ này phát âm giống nhau.', 'These new shoes rub against my left heel.', NULL, 'Đôi giày mới này đang cọ vào gót chân trái của tôi.', '{"wordId":"heel","ukIpa":"/hiːl/","usIpa":"/hiːl/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"The rounded back part of the foot below the ankle.","vi":"gót chân"},{"pos":"n.","en":"The raised part beneath the back of a shoe.","vi":"gót giày"}],"examples":[{"en":"These new shoes rub against my left heel.","vi":"Đôi giày mới này đang cọ vào gót chân trái của tôi.","audioKind":"ex"},{"en":"Shoes that support the heel properly may improve comfort for people who spend long hours standing.","vi":"Những đôi giày nâng đỡ gót chân tốt có thể mang lại sự thoải mái hơn cho những người phải đứng làm việc trong thời gian dài.","audioKind":"ex2"}],"collocations":[{"en":"heel pain","vi":"đau gót chân"},{"en":"high heels","vi":"giày cao gót"},{"en":"low heels","vi":"giày thấp gót"}],"wordFamily":["heeled (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Heel là gót chân hoặc gót giày; heal có nghĩa là chữa lành, hai từ này phát âm giống nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_appetite', 'en-b1-21', 'appetite', '/ˈæpətaɪt/', 'B1', 'sự thèm ăn; cảm giác thèm ăn; sự thèm muốn; khát khao mạnh mẽ đối với điều gì', 'n.', 'appetising (adj.), appetiser (n.)', NULL, 'appetite for ngoài nghĩa thèm ăn, còn có thể diễn tả sự khao khát kiến thức hay trải nghiệm.', 'A long walk always gives me a good appetite.', NULL, 'Đi bộ đường dài một quãng đường dài luôn làm tôi rất thèm ăn.', '{"wordId":"appetite","ukIpa":"/ˈæpɪtaɪt/","usIpa":"/ˈæpətaɪt/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"The desire to eat food.","vi":"sự thèm ăn; cảm giác thèm ăn"},{"pos":"n.","en":"A strong desire to have or experience something.","vi":"sự thèm muốn; khát khao mạnh mẽ đối với điều gì"}],"examples":[{"en":"A long walk always gives me a good appetite.","vi":"Đi bộ đường dài một quãng đường dài luôn làm tôi rất thèm ăn.","audioKind":"ex"},{"en":"The growing public appetite for sustainable products encourages companies to reconsider their materials and manufacturing processes.","vi":"Nhu cầu ngày càng tăng của công chúng đối với các sản phẩm bền vững đang khuyến khích các doanh nghiệp xem xét lại nguyên liệu và quy trình sản xuất của họ.","audioKind":"ex2"}],"collocations":[{"en":"lose your appetite","vi":"mất khẩu vị"},{"en":"a healthy appetite","vi":"sự thèm ăn ngon miệng"},{"en":"work up an appetite","vi":"kích thích sự thèm ăn"},{"en":"an appetite for","vi":"khát khao đối với"}],"wordFamily":["appetising (adj.)","appetiser (n.)"],"synonyms":[],"antonyms":[],"tipVi":"appetite for ngoài nghĩa thèm ăn, còn có thể diễn tả sự khao khát kiến thức hay trải nghiệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mask', 'en-b1-21', 'mask', '/mæsk/', 'B1', 'khẩu trang; mặt nạ; che đậy; che giấu', 'n.', 'masked (adj.), unmask (v.)', NULL, 'mask (động từ) trực tiếp đi với tân ngữ, dùng để chỉ hành động che giấu vấn đề hoặc cảm xúc.', 'She wore a mask while cleaning the dusty cupboard.', NULL, 'Cô ấy đeo khẩu trang trong lúc dọn dẹp chiếc tủ đầy bụi.', '{"wordId":"mask","ukIpa":"/mɑːsk/","usIpa":"/mæsk/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A covering worn over part or all of the face.","vi":"khẩu trang; mặt nạ"},{"pos":"v.","en":"To hide something or make it less noticeable.","vi":"che đậy; che giấu"}],"examples":[{"en":"She wore a mask while cleaning the dusty cupboard.","vi":"Cô ấy đeo khẩu trang trong lúc dọn dẹp chiếc tủ đầy bụi.","audioKind":"ex"},{"en":"Rapid economic growth can mask serious inequalities in access to education and healthcare.","vi":"Sự tăng trưởng kinh tế nhanh chóng có thể che giấu những bất bình đẳng nghiêm trọng trong việc tiếp cận giáo dục và y tế.","audioKind":"ex2"}],"collocations":[{"en":"wear a mask","vi":"đeo khẩu trang"},{"en":"face mask","vi":"mặt nạ; khẩu trang; mặt nạ dưỡng da"},{"en":"mask the smell","vi":"che đậy mùi"},{"en":"mask the problem","vi":"che đậy vấn đề"}],"wordFamily":["masked (adj.)","unmask (v.)"],"synonyms":[],"antonyms":[],"tipVi":"mask (động từ) trực tiếp đi với tân ngữ, dùng để chỉ hành động che giấu vấn đề hoặc cảm xúc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_breath', 'en-b1-21', 'breath', '/breθ/', 'B1', 'hơi thở; khí; nhịp thở', 'n.', 'breathe (v.), breathless (adj.), breathlessness (n.)', NULL, 'breath là danh từ; còn breathe là động từ, có phát âm đuôi là /ð/.', 'Her breath formed a cloud in the cold air.', NULL, 'Hơi thở của cô ấy tạo thành một làn mây trắng trong không khí lạnh.', '{"wordId":"breath","ukIpa":"/breθ/","usIpa":"/breθ/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"air moving into or out of your lungs","vi":"hơi thở; khí"},{"pos":"n.","en":"one act of taking air into your lungs","vi":"nhịp thở; hơi thở"}],"examples":[{"en":"Her breath formed a cloud in the cold air.","vi":"Hơi thở của cô ấy tạo thành một làn mây trắng trong không khí lạnh.","audioKind":"ex"},{"en":"Taking a slow, deep breath can help students manage anxiety before an important examination.","vi":"Việc hít thở chậm và sâu có thể giúp học sinh giảm bớt sự lo lắng trước một kỳ thi quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"take a deep breath","vi":"hít một hơi thật sâu"},{"en":"out of breath","vi":"hụt hơi; thở hổn hển"},{"en":"hold your breath","vi":"nín thở"},{"en":"catch your breath","vi":"lấy lại hơi thở; thở phào"}],"wordFamily":["breathe (v.)","breathless (adj.)","breathlessness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"breath là danh từ; còn breathe là động từ, có phát âm đuôi là /ð/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_allergy', 'en-b1-21', 'allergy', '/ˈælɚdʒi/', 'B1', 'chứng dị ứng; bệnh dị ứng', 'n.', 'allergic (adj.), allergen (n.)', NULL, 'Thường dùng cấu trúc have an allergy to; giới từ to đi kèm với tác nhân gây dị ứng.', 'My brother has an allergy to peanuts and walnuts.', NULL, 'Anh trai tôi bị dị ứng với đậu phộng và quả óc chó.', '{"wordId":"allergy","ukIpa":"/ˈælədʒi/","usIpa":"/ˈælɚdʒi/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A condition causing illness after contact with a normally harmless substance","vi":"chứng dị ứng; bệnh dị ứng"}],"examples":[{"en":"My brother has an allergy to peanuts and walnuts.","vi":"Anh trai tôi bị dị ứng với đậu phộng và quả óc chó.","audioKind":"ex"},{"en":"Schools should have clear procedures for helping children who experience a severe food allergy reaction.","vi":"Các trường học nên có quy trình rõ ràng để hỗ trợ trẻ em gặp phải phản ứng dị ứng thực phẩm nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"food allergy","vi":"dị ứng thực phẩm"},{"en":"pollen allergy","vi":"dị ứng phấn hoa"},{"en":"have an allergy to","vi":"bị dị ứng với..."}],"wordFamily":["allergic (adj.)","allergen (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cấu trúc have an allergy to; giới từ to đi kèm với tác nhân gây dị ứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_physical', 'en-b1-21', 'physical', '/ˈfɪzɪkəl/', 'B1', 'thuộc về thể chất; thuộc cơ thể; vật chất; hữu hình; thuộc vật lý', 'adj.', 'physically (adv.), physicality (n.)', 'Đồng nghĩa: bodily, material · Trái nghĩa: mental', 'Physical hướng về cơ thể hoặc vật chất; physiological dùng cho các vấn đề sinh lý.', 'Gardening gives me plenty of physical exercise every weekend.', NULL, 'Làm vườn mang lại cho tôi rất nhiều bài tập thể chất vào mỗi dịp cuối tuần.', '{"wordId":"physical","ukIpa":"/ˈfɪzɪkəl/","usIpa":"/ˈfɪzɪkəl/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"Relating to the body rather than the mind.","vi":"thuộc về thể chất; thuộc cơ thể"},{"pos":"adj.","en":"Existing as something real that can be touched or measured.","vi":"vật chất; hữu hình"},{"pos":"adj.","en":"Relating to natural forces, matter, and energy.","vi":"thuộc vật lý"}],"examples":[{"en":"Gardening gives me plenty of physical exercise every weekend.","vi":"Làm vườn mang lại cho tôi rất nhiều bài tập thể chất vào mỗi dịp cuối tuần.","audioKind":"ex"},{"en":"Regular physical activity can improve public health and reduce the financial pressure on national healthcare systems.","vi":"Hoạt động thể chất đều đặn có thể cải thiện sức khỏe cộng đồng và giảm áp lực tài chính lên các hệ thống y tế quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"physical activity","vi":"hoạt động thể chất"},{"en":"physical health","vi":"sức khỏe thể chất"},{"en":"physical properties","vi":"tính chất vật lý"},{"en":"physical evidence","vi":"chứng cứ vật chất"}],"wordFamily":["physically (adv.)","physicality (n.)"],"synonyms":["bodily","material"],"antonyms":["mental"],"tipVi":"Physical hướng về cơ thể hoặc vật chất; physiological dùng cho các vấn đề sinh lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_medical', 'en-b1-21', 'medical', '/ˈmedɪkəl/', 'B1', 'thuộc y tế; thuộc y học; khám chữa bệnh; cuộc khám sức khỏe định kỳ', 'adj.', 'medically (adv.), medicine (n.)', NULL, 'Medical khi là danh từ thường được dùng trong tiếng Anh-Anh để chỉ việc khám sức khỏe, không dùng để chỉ bác sĩ.', 'The hotel called for medical help when a guest fainted.', NULL, 'Khách sạn đã gọi cấp cứu y tế khi một vị khách ngất xỉu.', '{"wordId":"medical","ukIpa":"/ˈmedɪkəl/","usIpa":"/ˈmedɪkəl/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"Related to medicine or the treatment of illness.","vi":"thuộc y tế; thuộc y học; khám chữa bệnh"},{"pos":"n.","en":"An examination to check a person''s health.","vi":"cuộc khám sức khỏe định kỳ"}],"examples":[{"en":"The hotel called for medical help when a guest fainted.","vi":"Khách sạn đã gọi cấp cứu y tế khi một vị khách ngất xỉu.","audioKind":"ex"},{"en":"Governments should improve access to medical services in rural areas where hospitals are often far away.","vi":"Các chính phủ nên cải thiện khả năng tiếp cận dịch vụ y tế tại các vùng nông thôn nơi bệnh viện thường nằm ở khoảng cách rất xa.","audioKind":"ex2"}],"collocations":[{"en":"medical treatment","vi":"điều trị y tế"},{"en":"medical research","vi":"nghiên cứu y học"},{"en":"medical care","vi":"chăm sóc y tế"},{"en":"have a medical","vi":"khám sức khỏe"}],"wordFamily":["medically (adv.)","medicine (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Medical khi là danh từ thường được dùng trong tiếng Anh-Anh để chỉ việc khám sức khỏe, không dùng để chỉ bác sĩ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pharmacy', 'en-b1-21', 'pharmacy', '/ˈfɑːrməsi/', 'B1', 'tiệm thuốc; nhà thuốc; quầy dược; ngành dược; dược học', 'n.', 'pharmacist (n.), pharmaceutical (adj.)', 'Đồng nghĩa: chemist''s, drugstore', 'Tiệm thuốc là danh từ đếm được, còn dược học là không đếm được; dược sĩ là pharmacist.', 'I collected my medicine from the pharmacy after lunch.', NULL, 'Tôi đã lấy thuốc ở tiệm thuốc sau bữa trưa.', '{"wordId":"pharmacy","ukIpa":"/ˈfɑːməsi/","usIpa":"/ˈfɑːrməsi/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A shop or hospital department that prepares and supplies medicines.","vi":"tiệm thuốc; nhà thuốc; quầy dược"},{"pos":"n.","en":"The study and practice of preparing and supplying medicines.","vi":"ngành dược; dược học"}],"examples":[{"en":"I collected my medicine from the pharmacy after lunch.","vi":"Tôi đã lấy thuốc ở tiệm thuốc sau bữa trưa.","audioKind":"ex"},{"en":"A community pharmacy can improve access to healthcare by offering professional advice close to people''s homes.","vi":"Một hiệu thuốc cộng đồng có thể giúp mọi người dễ dàng tiếp cận dịch vụ chăm sóc sức khỏe hơn bằng cách cung cấp những lời khuyên chuyên môn ngay gần khu dân cư.","audioKind":"ex2"}],"collocations":[{"en":"community pharmacy","vi":"hiệu thuốc cộng đồng"},{"en":"hospital pharmacy","vi":"nhà thuốc bệnh viện"},{"en":"study pharmacy","vi":"học ngành dược"}],"wordFamily":["pharmacist (n.)","pharmaceutical (adj.)"],"synonyms":["chemist''s","drugstore"],"antonyms":[],"tipVi":"Tiệm thuốc là danh từ đếm được, còn dược học là không đếm được; dược sĩ là pharmacist.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yawn', 'en-b1-21', 'yawn', '/jɑːn/', 'B1', 'ngáp; cái ngáp', 'v.', NULL, NULL, 'Hành động ngáp có thể diễn tả bằng động từ yawn hoặc cụm từ give a yawn.', 'I yawned twice while waiting for the kettle to boil.', NULL, 'Tôi đã ngáp hai lần trong lúc đợi ấm nước sôi.', '{"wordId":"yawn","ukIpa":"/jɔːn/","usIpa":"/jɑːn/","cefr":"B1","topic":"health","senses":[{"pos":"v.","en":"Open your mouth widely and breathe deeply from tiredness or boredom.","vi":"ngáp"},{"pos":"n.","en":"An involuntary wide opening of the mouth with a deep breath.","vi":"cái ngáp"}],"examples":[{"en":"I yawned twice while waiting for the kettle to boil.","vi":"Tôi đã ngáp hai lần trong lúc đợi ấm nước sôi.","audioKind":"ex"},{"en":"Students who regularly yawn during morning lessons may not be getting enough sleep at night.","vi":"Những học sinh thường xuyên ngáp trong các tiết học buổi sáng có thể là do ban đêm ngủ không đủ giấc.","audioKind":"ex2"}],"collocations":[{"en":"give a yawn","vi":"ngáp một cái"},{"en":"stifle a yawn","vi":"kìm nén tiếng ngáp"},{"en":"yawn widely","vi":"ngáp thật to"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Hành động ngáp có thể diễn tả bằng động từ yawn hoặc cụm từ give a yawn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peanut', 'en-b1-21', 'peanut', '/ˈpiːnʌt/', 'B1', 'quả lạc; hạt đậu phộng; một số lượng tiền rất ít ỏi', 'n.', NULL, NULL, 'Khi chỉ số tiền cực ít, dùng dạng số nhiều peanuts theo văn phong không trang trọng.', 'She cracked the shell and ate the peanut inside.', NULL, 'Cô ấy bóc lớp vỏ mỏng và ăn hạt đậu phộng bên trong.', '{"wordId":"peanut","ukIpa":"/ˈpiːnʌt/","usIpa":"/ˈpiːnʌt/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"an edible seed that grows underground inside a thin shell","vi":"quả lạc; hạt đậu phộng"},{"pos":"n.","en":"a very small amount of money, expressed as peanuts","vi":"một số lượng tiền rất ít ỏi"}],"examples":[{"en":"She cracked the shell and ate the peanut inside.","vi":"Cô ấy bóc lớp vỏ mỏng và ăn hạt đậu phộng bên trong.","audioKind":"ex"},{"en":"Schools should consider peanut allergies when planning meals to ensure that all children can eat safely.","vi":"Các trường học nên cân nhắc vấn đề dị ứng đậu phộng khi lên thực đơn để đảm bảo tất cả trẻ em đều có thể ăn uống an toàn.","audioKind":"ex2"}],"collocations":[{"en":"peanut butter","vi":"bơ đậu phộng"},{"en":"peanut allergy","vi":"dị ứng đậu phộng"},{"en":"roasted peanuts","vi":"lạc rang"},{"en":"work for peanuts","vi":"làm việc với mức lương rẻ mạt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ số tiền cực ít, dùng dạng số nhiều peanuts theo văn phong không trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relaxation', 'en-b1-21', 'relaxation', '/ˌriːlækˈseɪʃən/', 'B1', 'sự nghỉ ngơi; sự giải trí; sự thả lỏng cơ bắp; sự nới lỏng quy định hoặc hạn chế', 'n.', 'relax (v.), relaxed (adj.), relaxing (adj.)', NULL, 'Khi diễn tả sự thư giãn, nghỉ ngơi, danh từ này thường không đếm được: for relaxation.', 'After work, I enjoy a warm bath for relaxation.', NULL, 'Sau giờ làm việc, tôi thích ngâm mình trong bồn nước ấm để thư giãn.', '{"wordId":"relaxation","ukIpa":"/ˌriːlækˈseɪʃən/","usIpa":"/ˌriːlækˈseɪʃən/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"Rest or enjoyable activity that reduces stress and tension.","vi":"sự nghỉ ngơi; sự giải trí"},{"pos":"n.","en":"The process of muscles becoming less tight.","vi":"sự thả lỏng cơ bắp"},{"pos":"n.","en":"The act of making rules or restrictions less strict.","vi":"sự nới lỏng quy định hoặc hạn chế"}],"examples":[{"en":"After work, I enjoy a warm bath for relaxation.","vi":"Sau giờ làm việc, tôi thích ngâm mình trong bồn nước ấm để thư giãn.","audioKind":"ex"},{"en":"Schools should teach relaxation techniques to help students manage anxiety before important examinations.","vi":"Nhà trường nên dạy các kỹ thuật thư giãn để giúp học sinh quản lý sự lo âu trước các kỳ thi quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"relaxation techniques","vi":"kỹ thuật thư giãn"},{"en":"muscle relaxation","vi":"sự thả lỏng cơ bắp"},{"en":"relaxation of restrictions","vi":"sự nới lỏng các biện pháp hạn chế"}],"wordFamily":["relax (v.)","relaxed (adj.)","relaxing (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi diễn tả sự thư giãn, nghỉ ngơi, danh từ này thường không đếm được: for relaxation.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tissue', 'en-b1-21', 'tissue', '/ˈtɪʃuː/', 'B1', 'khăn giấy; giấy ăn; mô sinh học', 'n.', NULL, NULL, 'Khăn giấy là danh từ đếm được; còn mô sinh học thường là danh từ không đếm được.', 'She handed me a tissue when I sneezed.', NULL, 'Cô ấy đưa cho tôi một tờ khăn giấy khi tôi hắt hơi.', '{"wordId":"tissue","ukIpa":"/ˈtɪʃuː/","usIpa":"/ˈtɪʃuː/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A small piece of soft paper used for wiping.","vi":"khăn giấy; giấy ăn"},{"pos":"n.","en":"A group of similar cells performing a particular bodily function.","vi":"mô sinh học"}],"examples":[{"en":"She handed me a tissue when I sneezed.","vi":"Cô ấy đưa cho tôi một tờ khăn giấy khi tôi hắt hơi.","audioKind":"ex"},{"en":"Scientists are developing new treatments that help damaged tissue recover more effectively after an injury.","vi":"Các nhà khoa học đang phát triển các phương pháp điều trị mới giúp mô bị tổn thương phục hồi hiệu quả hơn sau chấn thương.","audioKind":"ex2"}],"collocations":[{"en":"a box of tissues","vi":"một hộp khăn giấy"},{"en":"muscle tissue","vi":"mô cơ"},{"en":"damaged tissue","vi":"mô bị tổn thương"},{"en":"tissue repair","vi":"sự phục hồi mô"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khăn giấy là danh từ đếm được; còn mô sinh học thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chest', 'en-b1-21', 'chest', '/tʃest/', 'B1', 'ngực; khoang ngực; thùng lớn; rương; hòm', 'n.', NULL, NULL, 'Chest chỉ ngực hoặc thùng lớn; chest of drawers mới là tủ kéo đựng quần áo.', 'She held the sleeping kitten gently against her chest.', NULL, 'Cô ấy ôm nhẹ chú mèo con đang ngủ vào lồng ngực mình.', '{"wordId":"chest","ukIpa":"/tʃest/","usIpa":"/tʃest/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"The upper front part of the body, enclosing heart and lungs.","vi":"ngực; khoang ngực"},{"pos":"n.","en":"A large strong box with a lid, used for storage.","vi":"thùng lớn; rương; hòm"}],"examples":[{"en":"She held the sleeping kitten gently against her chest.","vi":"Cô ấy ôm nhẹ chú mèo con đang ngủ vào lồng ngực mình.","audioKind":"ex"},{"en":"Workers exposed to polluted air may develop chest problems, highlighting the importance of effective workplace ventilation.","vi":"Công nhân tiếp xúc với không khí ô nhiễm có thể gặp các vấn đề về ngực, điều này làm nổi bật tầm quan trọng của hệ thống thông gió hiệu quả tại nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"chest pain","vi":"đau ngực"},{"en":"a chest infection","vi":"nhiễm trùng ngực"},{"en":"a wooden chest","vi":"rương gỗ"},{"en":"a chest of drawers","vi":"tủ có ngăn kéo; tủ kéo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chest chỉ ngực hoặc thùng lớn; chest of drawers mới là tủ kéo đựng quần áo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_safety', 'en-b1-21', 'safety', '/ˈseɪfti/', 'B1', 'sự an toàn; sự an tâm', 'n.', 'safe (adj.), safely (adv.), unsafe (adj.)', 'Trái nghĩa: danger', 'Thường là danh từ không đếm được; safe là tính từ, safety là danh từ.', 'Please wear a helmet for your own safety.', NULL, 'Xin vui lòng đội mũ bảo hiểm vì sự an toàn của chính bạn.', '{"wordId":"safety","ukIpa":"/ˈseɪfti/","usIpa":"/ˈseɪfti/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"the state of being protected from danger or harm","vi":"sự an toàn; sự an tâm"}],"examples":[{"en":"Please wear a helmet for your own safety.","vi":"Xin vui lòng đội mũ bảo hiểm vì sự an toàn của chính bạn.","audioKind":"ex"},{"en":"Improving road safety requires better street design as well as stricter enforcement of traffic laws.","vi":"Nâng cao an toàn giao thông đòi hỏi thiết kế đường sá tốt hơn cũng như thực thi luật giao thông nghiêm ngặt hơn.","audioKind":"ex2"}],"collocations":[{"en":"road safety","vi":"an toàn giao thông"},{"en":"safety standards","vi":"tiêu chuẩn an toàn"},{"en":"for safety reasons","vi":"vì lý do an toàn"},{"en":"reach safety","vi":"đến nơi an toàn"}],"wordFamily":["safe (adj.)","safely (adv.)","unsafe (adj.)"],"synonyms":[],"antonyms":["danger"],"tipVi":"Thường là danh từ không đếm được; safe là tính từ, safety là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nap', 'en-b1-21', 'nap', '/næp/', 'B1', 'giấc ngủ ngắn; giờ nghỉ trưa; chợp mắt; ngủ trưa', 'n.', 'napper (n.)', 'Đồng nghĩa: doze, snooze', 'Động từ chia gấp đôi chữ p: napped, napping.', 'I took a short nap after lunch on Sunday.', NULL, 'Tôi đã chợp mắt một lát sau bữa trưa vào chủ nhật.', '{"wordId":"nap","ukIpa":"/næp/","usIpa":"/næp/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"a short sleep, usually during the day","vi":"giấc ngủ ngắn; giờ nghỉ trưa"},{"pos":"v.","en":"to sleep briefly, usually during the day","vi":"chợp mắt; ngủ trưa"}],"examples":[{"en":"I took a short nap after lunch on Sunday.","vi":"Tôi đã chợp mắt một lát sau bữa trưa vào chủ nhật.","audioKind":"ex"},{"en":"A brief afternoon nap may improve alertness, but it should not replace adequate sleep at night.","vi":"Một giấc ngủ ngắn vào buổi chiều có thể cải thiện sự tỉnh táo, nhưng nó không nên thay thế cho giấc ngủ đầy đủ vào ban đêm.","audioKind":"ex2"}],"collocations":[{"en":"take a nap","vi":"chợp mắt một lát"},{"en":"an afternoon nap","vi":"giấc ngủ trưa"},{"en":"a power nap","vi":"giấc ngủ ngắn lấy lại năng lượng"}],"wordFamily":["napper (n.)"],"synonyms":["doze","snooze"],"antonyms":[],"tipVi":"Động từ chia gấp đôi chữ p: napped, napping.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_21_1', 'en-b1-21', 'Cách dùng “medical” (adj.) — thuộc y tế; thuộc y học; khám chữa bệnh', 'medical treatment  ·  medical research  ·  medical care', 'Medical khi là danh từ thường được dùng trong tiếng Anh-Anh để chỉ việc khám sức khỏe, không dùng để chỉ bác sĩ.', 'Họ từ (Word Family): medically (adv.), medicine (n.)', '[{"hanzi":"The hotel called for medical help when a guest fainted.","pinyin":"","meaning":"Khách sạn đã gọi cấp cứu y tế khi một vị khách ngất xỉu."},{"hanzi":"Governments should improve access to medical services in rural areas where hospitals are often far away.","pinyin":"","meaning":"Các chính phủ nên cải thiện khả năng tiếp cận dịch vụ y tế tại các vùng nông thôn nơi bệnh viện thường nằm ở khoảng cách rất xa."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_21_2', 'en-b1-21', 'Cách dùng “sweat” (n.) — mồ hôi', 'break into a sweat  ·  wipe away sweat  ·  sweat heavily', 'Mồ hôi thông thường là danh từ không đếm được; có thể dùng a sweat khi nói về một trận ra mồ hôi.', 'Họ từ (Word Family): sweaty (adj.), sweating (n.) | Đồng nghĩa: perspiration', '[{"hanzi":"Sweat ran down my face during the steep climb.","pinyin":"","meaning":"Mồ hôi túa ra trên mặt tôi trong suốt chặng leo dốc đứng."},{"hanzi":"People who exercise in hot weather lose water through sweat and should drink regularly.","pinyin":"","meaning":"Những người tập thể dục trong thời tiết nóng bức sẽ mất nước qua tuyến mồ hôi và nên uống nước thường xuyên."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_21_3', 'en-b1-21', 'Cách dùng “sunblock” (n.) — kem chống nắng', 'apply sunblock  ·  wear sunblock  ·  water-resistant sunblock', 'Thường là danh từ không đếm được; tên gọi không có nghĩa là chống tia cực tím hoàn toàn 100%.', 'Đồng nghĩa: sunscreen', '[{"hanzi":"Put some sunblock on your shoulders before swimming.","pinyin":"","meaning":"Hãy bôi một ít kem chống nắng lên vai trước khi bơi."},{"hanzi":"Using sunblock alongside protective clothing can reduce skin damage during prolonged exposure to sunlight.","pinyin":"","meaning":"Sử dụng kem chống nắng kết hợp với quần áo bảo hộ có thể làm giảm tổn thương da khi tiếp xúc lâu với ánh nắng mặt trời."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_21_4', 'en-b1-21', 'Cách dùng “sight” (n.) — thị lực; thị giác', 'lose one''s sight  ·  out of sight  ·  at first sight', 'Thị lực thường không đếm được; khi chỉ các danh thắng, từ này thường ở dạng số nhiều sights.', 'Họ từ (Word Family): sighted (adj.), sightless (adj.) | Đồng nghĩa: vision, eyesight', '[{"hanzi":"Her sight improved after she got new glasses.","pinyin":"","meaning":"Thị lực của cô ấy đã tốt hơn sau khi cắt kính mới."},{"hanzi":"Regular eye examinations can help preserve sight by detecting problems before they cause permanent damage.","pinyin":"","meaning":"Việc khám mắt định kỳ có thể giúp bảo vệ thị lực bằng cách phát hiện các vấn đề trước khi chúng gây tổn thương vĩnh viễn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_21_1', 'en-b1-21', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_1_1', 'ten_b1_21_1', 'painkiller', 'The pharmacist explained when I should take the painkiller.', 'The pharmacist explained when I should take the painkiller.', '/ˈpeɪnkɪlər/', 'Dược sĩ đã giải thích thời điểm tôi nên uống thuốc giảm đau.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_1_2', 'ten_b1_21_1', 'sunblock', 'Put some sunblock on your shoulders before swimming.', 'Put some sunblock on your shoulders before swimming.', '/ˈsʌnblɑːk/', 'Hãy bôi một ít kem chống nắng lên vai trước khi bơi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_1_3', 'ten_b1_21_1', 'sight', 'Her sight improved after she got new glasses.', 'Her sight improved after she got new glasses.', '/saɪt/', 'Thị lực của cô ấy đã tốt hơn sau khi cắt kính mới.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_1_4', 'ten_b1_21_1', 'check-up', 'I booked a check-up because I felt unusually tired.', 'I booked a check-up because I felt unusually tired.', '/ˈtʃek ʌp/', 'Tôi đã đặt lịch khám sức khỏe vì cảm thấy mệt mỏi bất thường.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_1_5', 'ten_b1_21_1', 'sweat', 'Sweat ran down my face during the steep climb.', 'Sweat ran down my face during the steep climb.', '/swet/', 'Mồ hôi túa ra trên mặt tôi trong suốt chặng leo dốc đứng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_1_6', 'ten_b1_21_1', 'breathing', 'After the steep climb, my breathing slowly returned to normal.', 'After the steep climb, my breathing slowly returned to normal.', '/ˈbriːðɪŋ/', 'Sau đoạn đường dốc đứng, nhịp thở của tôi từ từ trở lại bình thường.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_1_7', 'ten_b1_21_1', 'overweight', 'My suitcase was overweight, so I removed some books.', 'My suitcase was overweight, so I removed some books.', '/ˌoʊvərˈweɪt/', 'Vali của tôi đã bị quá cước, vì vậy tôi đã lấy bớt một số cuốn sách ra.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_1_8', 'ten_b1_21_1', 'heel', 'These new shoes rub against my left heel.', 'These new shoes rub against my left heel.', '/hiːl/', 'Đôi giày mới này đang cọ vào gót chân trái của tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_21_1_1', 'en-b1-21', 'ten_b1_21_1', 'listening', 'listening', 'The pharmacist explained when I should take the painkiller.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Dược sĩ đã giải thích thời điểm tôi nên uống thuốc giảm đau.","Làm vườn mang lại cho tôi rất nhiều bài tập thể chất vào mỗi dịp cuối tuần.","Vali của tôi đã bị quá cước, vì vậy tôi đã lấy bớt một số cuốn sách ra.","Sau đoạn đường dốc đứng, nhịp thở của tôi từ từ trở lại bình thường."]'::jsonb, 0, 'The pharmacist explained when I should take the painkiller. → Dược sĩ đã giải thích thời điểm tôi nên uống thuốc giảm đau.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_21_1_2', 'en-b1-21', 'ten_b1_21_1', 'listening', 'listening', 'Put some sunblock on your shoulders before swimming.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đôi giày mới này đang cọ vào gót chân trái của tôi.","Cô ấy ôm nhẹ chú mèo con đang ngủ vào lồng ngực mình.","Vali của tôi đã bị quá cước, vì vậy tôi đã lấy bớt một số cuốn sách ra.","Hãy bôi một ít kem chống nắng lên vai trước khi bơi."]'::jsonb, 3, 'Put some sunblock on your shoulders before swimming. → Hãy bôi một ít kem chống nắng lên vai trước khi bơi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_21_1_3', 'en-b1-21', 'ten_b1_21_1', 'listening', 'listening', 'Her sight improved after she got new glasses.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sau đoạn đường dốc đứng, nhịp thở của tôi từ từ trở lại bình thường.","Tôi đã lấy thuốc ở tiệm thuốc sau bữa trưa.","Khách sạn đã gọi cấp cứu y tế khi một vị khách ngất xỉu.","Thị lực của cô ấy đã tốt hơn sau khi cắt kính mới."]'::jsonb, 3, 'Her sight improved after she got new glasses. → Thị lực của cô ấy đã tốt hơn sau khi cắt kính mới.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_21_2', 'en-b1-21', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_2_1', 'ten_b1_21_2', 'painkiller', 'Patients should receive clear guidance on using painkillers safely, including information about possible side effects.', 'Patients should receive clear guidance on using painkillers safely, including information about possible side effects.', '/ˈpeɪnkɪlər/', 'Bệnh nhân nên nhận được hướng dẫn rõ ràng về việc sử dụng thuốc giảm đau an toàn, bao gồm cả thông tin về các tác dụng phụ có thể xảy ra.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_2_2', 'ten_b1_21_2', 'sunblock', 'Using sunblock alongside protective clothing can reduce skin damage during prolonged exposure to sunlight.', 'Using sunblock alongside protective clothing can reduce skin damage during prolonged exposure to sunlight.', '/ˈsʌnblɑːk/', 'Sử dụng kem chống nắng kết hợp với quần áo bảo hộ có thể làm giảm tổn thương da khi tiếp xúc lâu với ánh nắng mặt trời.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_2_3', 'ten_b1_21_2', 'sight', 'Regular eye examinations can help preserve sight by detecting problems before they cause permanent damage.', 'Regular eye examinations can help preserve sight by detecting problems before they cause permanent damage.', '/saɪt/', 'Việc khám mắt định kỳ có thể giúp bảo vệ thị lực bằng cách phát hiện các vấn đề trước khi chúng gây tổn thương vĩnh viễn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_2_4', 'ten_b1_21_2', 'check-up', 'Regular check-ups can help doctors detect health problems before they require more expensive treatment.', 'Regular check-ups can help doctors detect health problems before they require more expensive treatment.', '/ˈtʃek ʌp/', 'Việc kiểm tra sức khỏe định kỳ có thể giúp bác sĩ phát hiện các vấn đề y tế trước khi chúng đòi hỏi các phương pháp điều trị tốn kém hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_2_5', 'ten_b1_21_2', 'sweat', 'People who exercise in hot weather lose water through sweat and should drink regularly.', 'People who exercise in hot weather lose water through sweat and should drink regularly.', '/swet/', 'Những người tập thể dục trong thời tiết nóng bức sẽ mất nước qua tuyến mồ hôi và nên uống nước thường xuyên.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_21_2_6', 'ten_b1_21_2', 'breathing', 'Regular breathing exercises may help students manage stress and improve their concentration during demanding periods of study.', 'Regular breathing exercises may help students manage stress and improve their concentration during demanding periods of study.', '/ˈbriːðɪŋ/', 'Các bài tập thở đều đặn có thể giúp học sinh quản lý căng thẳng và cải thiện khả năng tập trung trong những giai đoạn học tập căng thẳng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_21_2_1', 'en-b1-21', 'ten_b1_21_2', 'listening', 'listening', 'Patients should receive clear guidance on using painkillers safely, including information about possible side effects.', NULL, 'Trong câu vừa nghe, từ “painkiller” mang nghĩa nào sau đây?', '["thuốc giảm đau","hoãn lại; lùi lịch","ngày kỷ niệm (hàng năm)","bất cứ nơi nào; dù ở đâu"]'::jsonb, 0, '“painkiller” (/ˈpeɪnkɪlər/): thuốc giảm đau. Câu đầy đủ: Patients should receive clear guidance on using painkillers safely, including information about possible side effects.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_21_2_2', 'en-b1-21', 'ten_b1_21_2', 'listening', 'listening', 'Using sunblock alongside protective clothing can reduce skin damage during prolonged exposure to sunlight.', NULL, 'Trong câu vừa nghe, từ “sunblock” mang nghĩa nào sau đây?', '["tập trung; chú trọng","cầu nguyện; cầu xin (thần linh)","kem chống nắng","bắn; nã đạn"]'::jsonb, 2, '“sunblock” (/ˈsʌnblɑːk/): kem chống nắng. Câu đầy đủ: Using sunblock alongside protective clothing can reduce skin damage during prolonged exposure to sunlight.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
