INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_1', 'en-b1-21', NULL, 'comprehensive_test', 'listening', 'painkiller', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["văn hóa; phong tục tập quán","thuốc giảm đau","dập ghim; máy bấm giấy","nguồn; nguồn gốc"]'::jsonb, 1, 'painkiller (/ˈpeɪnkɪlər/) → thuốc giảm đau', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_2', 'en-b1-21', NULL, 'comprehensive_test', 'listening', 'Put some sunblock on your shoulders before swimming.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sau đoạn đường dốc đứng, nhịp thở của tôi từ từ trở lại bình thường.","Hãy bôi một ít kem chống nắng lên vai trước khi bơi.","Cô ấy đưa cho tôi một tờ khăn giấy khi tôi hắt hơi.","Vali của tôi đã bị quá cước, vì vậy tôi đã lấy bớt một số cuốn sách ra."]'::jsonb, 1, 'Put some sunblock on your shoulders before swimming. → Hãy bôi một ít kem chống nắng lên vai trước khi bơi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_3', 'en-b1-21', NULL, 'comprehensive_test', 'listening', 'sight', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tiếng cười; sự cười","thập kỷ; mười năm","làm cho ai đó sợ hãi; dọa","thị lực; thị giác"]'::jsonb, 3, 'sight (/saɪt/) → thị lực; thị giác; tầm nhìn; tầm quan sát; cảnh tượng; thắng cảnh', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_4', 'en-b1-21', NULL, 'comprehensive_test', 'listening', 'I booked a check-up because I felt unusually tired.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã đặt lịch khám sức khỏe vì cảm thấy mệt mỏi bất thường.","Sau giờ làm việc, tôi thích ngâm mình trong bồn nước ấm để thư giãn.","Vali của tôi đã bị quá cước, vì vậy tôi đã lấy bớt một số cuốn sách ra.","Đôi giày mới này đang cọ vào gót chân trái của tôi."]'::jsonb, 0, 'I booked a check-up because I felt unusually tired. → Tôi đã đặt lịch khám sức khỏe vì cảm thấy mệt mỏi bất thường.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_5', 'en-b1-21', NULL, 'comprehensive_test', 'listening', 'sweat', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hóa chất; chất hóa học","gối tựa; đệm lót","tự động","mồ hôi"]'::jsonb, 3, 'sweat (/swet/) → mồ hôi; đổ mồ hôi; toát mồ hôi', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_6', 'en-b1-21', NULL, 'comprehensive_test', 'listening', 'After the steep climb, my breathing slowly returned to normal.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sau đoạn đường dốc đứng, nhịp thở của tôi từ từ trở lại bình thường.","Khách sạn đã gọi cấp cứu y tế khi một vị khách ngất xỉu.","Mồ hôi túa ra trên mặt tôi trong suốt chặng leo dốc đứng.","Cô ấy đưa cho tôi một tờ khăn giấy khi tôi hắt hơi."]'::jsonb, 0, 'After the steep climb, my breathing slowly returned to normal. → Sau đoạn đường dốc đứng, nhịp thở của tôi từ từ trở lại bình thường.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_7', 'en-b1-21', NULL, 'comprehensive_test', 'listening', 'overweight', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quá cân; thừa cân","vách đá; vách dựng đứng","chiến dịch; cuộc vận động","áo lót sát nách (Anh); áo lê-ki-na, áo ghi-lê (Mỹ)"]'::jsonb, 0, 'overweight (/ˌoʊvərˈweɪt/) → quá cân; thừa cân', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_8', 'en-b1-21', NULL, 'comprehensive_test', 'listening', 'These new shoes rub against my left heel.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy bóc lớp vỏ mỏng và ăn hạt đậu phộng bên trong.","Cô ấy đeo khẩu trang trong lúc dọn dẹp chiếc tủ đầy bụi.","Khách sạn đã gọi cấp cứu y tế khi một vị khách ngất xỉu.","Đôi giày mới này đang cọ vào gót chân trái của tôi."]'::jsonb, 3, 'These new shoes rub against my left heel. → Đôi giày mới này đang cọ vào gót chân trái của tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
