INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_18', 'en-b1-21', NULL, 'comprehensive_test', 'reading', NULL, 'Patients should receive clear guidance on using painkillers safely, including information about possible side effects.', 'Dựa vào câu trên, từ “painkiller” có nghĩa phù hợp nhất là gì?', '["người đại diện; đại lý","thuốc giảm đau","phòng khám; phòng khám đa khoa/chuyên khoa","quá trình; quy trình"]'::jsonb, 1, 'painkiller: thuốc giảm đau. Dịch cả câu: Bệnh nhân nên nhận được hướng dẫn rõ ràng về việc sử dụng thuốc giảm đau an toàn, bao gồm cả thông tin về các tác dụng phụ có thể xảy ra.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_19', 'en-b1-21', NULL, 'comprehensive_test', 'reading', NULL, 'Using sunblock alongside protective clothing can reduce skin damage during prolonged exposure to sunlight.', 'Dựa vào câu trên, từ “sunblock” có nghĩa phù hợp nhất là gì?', '["lời phàn nàn; đơn khiếu nại; sự khiếu nại","món hầm; thịt hầm","đinh ghim; kim băng","kem chống nắng"]'::jsonb, 3, 'sunblock: kem chống nắng. Dịch cả câu: Sử dụng kem chống nắng kết hợp với quần áo bảo hộ có thể làm giảm tổn thương da khi tiếp xúc lâu với ánh nắng mặt trời.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_20', 'en-b1-21', NULL, 'comprehensive_test', 'reading', NULL, 'Regular eye examinations can help preserve sight by detecting problems before they cause permanent damage.', 'Dựa vào câu trên, từ “sight” có nghĩa phù hợp nhất là gì?', '["đồ đựng; vật dùng để chứa hoặc bảo quản đồ đạc","thị lực; thị giác","thiên nga","phía trên; trên cao"]'::jsonb, 1, 'sight: thị lực; thị giác; tầm nhìn; tầm quan sát; cảnh tượng; thắng cảnh. Dịch cả câu: Việc khám mắt định kỳ có thể giúp bảo vệ thị lực bằng cách phát hiện các vấn đề trước khi chúng gây tổn thương vĩnh viễn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_21', 'en-b1-21', NULL, 'comprehensive_test', 'reading', NULL, 'Regular check-ups can help doctors detect health problems before they require more expensive treatment.', 'Dựa vào câu trên, từ “check-up” có nghĩa phù hợp nhất là gì?', '["động vật hoang dã; sinh vật hoang dã","buổi khám sức khỏe tổng quát; sự kiểm tra sức khỏe","đau; nhức mỏi (nhất là khi chạm vào hoặc cử động)","đồ đạc; thứ; vật dụng"]'::jsonb, 1, 'check-up: buổi khám sức khỏe tổng quát; sự kiểm tra sức khỏe. Dịch cả câu: Việc kiểm tra sức khỏe định kỳ có thể giúp bác sĩ phát hiện các vấn đề y tế trước khi chúng đòi hỏi các phương pháp điều trị tốn kém hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_22', 'en-b1-21', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngực; khoang ngực”', '["register","marriage","tick","chest"]'::jsonb, 3, 'ngực; khoang ngực → chest (/tʃest/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_23', 'en-b1-21', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự an toàn; sự an tâm”', '["symbol","fashionable","safety","selfish"]'::jsonb, 2, 'sự an toàn; sự an tâm → safety (/ˈseɪfti/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_21_24', 'en-b1-21', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giấc ngủ ngắn; giờ nghỉ trưa”', '["nap","port","judge","worth"]'::jsonb, 0, 'giấc ngủ ngắn; giờ nghỉ trưa → nap (/næp/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-22', 'en', 'Bài 22: Sức khỏe & Cơ thể (4) - CEFR B1', 'CEFR B1', 'B1 · Sức khỏe', '22 từ vựng Tiếng Anh CEFR B1 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3022, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_injury', 'en-b1-22', 'injury', '/ˈɪndʒəri/', 'B1', 'thương tích; chấn thương', 'n.', 'injure (v.), injured (adj.)', NULL, 'Vị trí chấn thương cụ thể có thể đếm được; khi chỉ tổn thương cơ thể nói chung thường không đếm được.', 'His knee injury kept him away from football practice.', NULL, 'Chấn thương đầu gối khiến anh ấy phải vắng mặt trong buổi tập bóng đá.', '{"wordId":"injury","ukIpa":"/ˈɪndʒəri/","usIpa":"/ˈɪndʒəri/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"Physical harm to someone''s body, often caused by an accident","vi":"thương tích; chấn thương"}],"examples":[{"en":"His knee injury kept him away from football practice.","vi":"Chấn thương đầu gối khiến anh ấy phải vắng mặt trong buổi tập bóng đá.","audioKind":"ex"},{"en":"Employers should provide regular safety training to reduce the risk of injury among workers operating heavy machinery.","vi":"Người sử dụng lao động nên cung cấp đào tạo an toàn thường xuyên để giảm nguy cơ chấn thương cho công nhân vận hành máy móc hạng nặng.","audioKind":"ex2"}],"collocations":[{"en":"suffer an injury","vi":"bị chấn thương"},{"en":"a serious injury","vi":"chấn thương nghiêm trọng"},{"en":"a knee injury","vi":"chấn thương đầu gối"},{"en":"risk of injury","vi":"nguy cơ chấn thương"}],"wordFamily":["injure (v.)","injured (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Vị trí chấn thương cụ thể có thể đếm được; khi chỉ tổn thương cơ thể nói chung thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_first-aid', 'en-b1-22', 'first-aid', '/ˌfɝːst ˈeɪd/', 'B1', 'thuộc về sơ cứu; cấp cứu', 'adj.', NULL, NULL, 'Danh từ viết là first aid; khi đứng trước danh từ làm định ngữ thì thêm dấu gạch nối.', 'There is a first-aid kit in the kitchen cupboard.', NULL, 'Có một hộp sơ cứu trong tủ bếp.', '{"wordId":"first-aid","ukIpa":"/ˌfɜːst ˈeɪd/","usIpa":"/ˌfɝːst ˈeɪd/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"Used for immediate basic care after injury or sudden illness.","vi":"thuộc về sơ cứu; cấp cứu"}],"examples":[{"en":"There is a first-aid kit in the kitchen cupboard.","vi":"Có một hộp sơ cứu trong tủ bếp.","audioKind":"ex"},{"en":"Employers should provide first-aid training so that staff can respond effectively to minor workplace injuries.","vi":"Người sử dụng lao động nên cung cấp đào tạo sơ cứu để nhân viên có thể ứng phó hiệu quả với các chấn thương nhẹ tại nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"first-aid kit","vi":"hộp sơ cứu"},{"en":"first-aid training","vi":"đào tạo sơ cứu"},{"en":"first-aid equipment","vi":"trang thiết bị sơ cứu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ viết là first aid; khi đứng trước danh từ làm định ngữ thì thêm dấu gạch nối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_workout', 'en-b1-22', 'workout', '/ˈwɝːkaʊt/', 'B1', 'buổi tập luyện; rèn luyện thể chất', 'n.', NULL, 'Đồng nghĩa: exercise session', 'workout là danh từ; cụm động từ work out phải viết tách nhau.', 'After a short workout, I felt ready for breakfast.', NULL, 'Sau một buổi tập ngắn, tôi thấy sẵn sàng để ăn sáng.', '{"wordId":"workout","ukIpa":"/ˈwɜːkaʊt/","usIpa":"/ˈwɝːkaʊt/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"a period of physical exercise to improve strength or fitness","vi":"buổi tập luyện; rèn luyện thể chất"}],"examples":[{"en":"After a short workout, I felt ready for breakfast.","vi":"Sau một buổi tập ngắn, tôi thấy sẵn sàng để ăn sáng.","audioKind":"ex"},{"en":"A regular workout can improve physical health and help office workers manage stress more effectively.","vi":"Tập luyện thường xuyên có thể cải thiện sức khỏe thể chất và giúp nhân viên văn phòng quản lý căng thẳng hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"daily workout","vi":"buổi tập hàng ngày"},{"en":"intense workout","vi":"bài tập cường độ cao"},{"en":"workout routine","vi":"chế độ tập luyện"}],"wordFamily":[],"synonyms":["exercise session"],"antonyms":[],"tipVi":"workout là danh từ; cụm động từ work out phải viết tách nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pregnant', 'en-b1-22', 'pregnant', '/ˈpreɡnənt/', 'B1', 'mang thai; có bầu', 'adj.', 'pregnancy (n.)', 'Đồng nghĩa: expectant', 'Biểu thị mang thai bao nhiêu tháng có thể dùng "six months pregnant".', 'My cousin is pregnant and expects her baby in June.', NULL, 'Em họ tôi đang mang thai và dự sinh vào tháng Sáu.', '{"wordId":"pregnant","ukIpa":"/ˈpreɡnənt/","usIpa":"/ˈpreɡnənt/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"having a baby developing inside the body","vi":"mang thai; có bầu"}],"examples":[{"en":"My cousin is pregnant and expects her baby in June.","vi":"Em họ tôi đang mang thai và dự sinh vào tháng Sáu.","audioKind":"ex"},{"en":"Accessible healthcare helps pregnant women receive regular check-ups and reliable advice throughout their pregnancy.","vi":"Dịch vụ chăm sóc sức khỏe dễ tiếp cận giúp phụ nữ mang thai được khám định kỳ và nhận những lời khuyên đáng tin cậy trong suốt thai kỳ.","audioKind":"ex2"}],"collocations":[{"en":"become pregnant","vi":"mang thai"},{"en":"pregnant women","vi":"phụ nữ mang thai"},{"en":"heavily pregnant","vi":"mang thai những tháng cuối"}],"wordFamily":["pregnancy (n.)"],"synonyms":["expectant"],"antonyms":[],"tipVi":"Biểu thị mang thai bao nhiêu tháng có thể dùng \"six months pregnant\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clinic', 'en-b1-22', 'clinic', '/ˈklɪnɪk/', 'B1', 'phòng khám; phòng khám đa khoa/chuyên khoa', 'n.', 'clinical (adj.), clinician (n.), clinically (adv.)', NULL, 'clinic chỉ phòng khám hoặc trạm y tế; tính từ "lâm sàng" là clinical.', 'The clinic near our house opens early on weekdays.', NULL, 'Phòng khám gần nhà chúng tôi mở cửa rất sớm vào các ngày trong tuần.', '{"wordId":"clinic","ukIpa":"/ˈklɪnɪk/","usIpa":"/ˈklɪnɪk/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A place providing medical advice or treatment without overnight stays.","vi":"phòng khám; phòng khám đa khoa/chuyên khoa"}],"examples":[{"en":"The clinic near our house opens early on weekdays.","vi":"Phòng khám gần nhà chúng tôi mở cửa rất sớm vào các ngày trong tuần.","audioKind":"ex"},{"en":"Local clinics can reduce pressure on hospitals by treating common illnesses and providing preventive care.","vi":"Các phòng khám địa phương có thể giảm tải áp lực cho bệnh viện bằng cách điều trị các bệnh thông thường và cung cấp dịch vụ chăm sóc phòng ngừa.","audioKind":"ex2"}],"collocations":[{"en":"dental clinic","vi":"phòng khám nha khoa"},{"en":"outpatient clinic","vi":"phòng khám ngoại trú"},{"en":"attend a clinic","vi":"đến phòng khám khám bệnh"}],"wordFamily":["clinical (adj.)","clinician (n.)","clinically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"clinic chỉ phòng khám hoặc trạm y tế; tính từ \"lâm sàng\" là clinical.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ambulance', 'en-b1-22', 'ambulance', '/ˈæmbjələns/', 'B1', 'xe cứu thương; xe cấp cứu', 'n.', NULL, NULL, 'Bắt đầu bằng nguyên âm nên dùng an; gọi xe cứu thương dùng call an ambulance.', 'An ambulance arrived quickly and took him to hospital.', NULL, 'Xe cứu thương nhanh chóng đến nơi và đưa anh ấy vào bệnh viện.', '{"wordId":"ambulance","ukIpa":"/ˈæmbjələns/","usIpa":"/ˈæmbjələns/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A vehicle that transports sick or injured people for medical care.","vi":"xe cứu thương; xe cấp cứu"}],"examples":[{"en":"An ambulance arrived quickly and took him to hospital.","vi":"Xe cứu thương nhanh chóng đến nơi và đưa anh ấy vào bệnh viện.","audioKind":"ex"},{"en":"Improving ambulance access in remote communities can reduce delays in treatment and increase patients'' chances of recovery.","vi":"Cải thiện khả năng tiếp cận xe cứu thương ở các cộng đồng vùng sâu vùng xa có thể giảm thời gian chậm trễ trong điều trị và nâng cao cơ hội hồi phục của bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"call an ambulance","vi":"gọi xe cứu thương"},{"en":"ambulance service","vi":"dịch vụ xe cứu thương"},{"en":"ambulance crew","vi":"đội ngũ cấp cứu trên xe"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Bắt đầu bằng nguyên âm nên dùng an; gọi xe cứu thương dùng call an ambulance.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sunscreen', 'en-b1-22', 'sunscreen', '/ˈsʌnskriːn/', 'B1', 'kem chống nắng', 'n.', NULL, 'Đồng nghĩa: suncream', 'Thông thường là danh từ không đếm được; hành động bôi kem chống nắng dùng động từ apply hoặc put on.', 'Please put on sunscreen before we leave for the beach.', NULL, 'Xin hãy bôi kem chống nắng trước khi chúng ta khởi hành đi ra biển.', '{"wordId":"sunscreen","ukIpa":"/ˈsʌnskriːn/","usIpa":"/ˈsʌnskriːn/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A substance applied to skin to protect it from sunlight.","vi":"kem chống nắng"}],"examples":[{"en":"Please put on sunscreen before we leave for the beach.","vi":"Xin hãy bôi kem chống nắng trước khi chúng ta khởi hành đi ra biển.","audioKind":"ex"},{"en":"Using sunscreen alongside protective clothing can reduce skin damage caused by prolonged exposure to sunlight.","vi":"Việc sử dụng kem chống nắng kết hợp với mặc đồ bảo hộ có thể làm giảm tổn thương da do tiếp xúc lâu với ánh nắng mặt trời.","audioKind":"ex2"}],"collocations":[{"en":"apply sunscreen","vi":"bôi kem chống nắng"},{"en":"reapply sunscreen","vi":"thoa lại kem chống nắng"},{"en":"water-resistant sunscreen","vi":"kem chống nắng chống thấm nước"}],"wordFamily":[],"synonyms":["suncream"],"antonyms":[],"tipVi":"Thông thường là danh từ không đếm được; hành động bôi kem chống nắng dùng động từ apply hoặc put on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thermometer', 'en-b1-22', 'thermometer', '/θərˈmɑːmɪtər/', 'B1', 'nhiệt kế', 'n.', NULL, NULL, 'Trọng âm rơi vào âm tiết thứ hai; để đo thân nhiệt, thường dùng cụm từ take someone''s temperature.', 'She placed the thermometer gently under her son''s tongue.', NULL, 'Cô ấy nhẹ nhàng đặt nhiệt kế dưới lưỡi con trai.', '{"wordId":"thermometer","ukIpa":"/θəˈmɒmɪtə/","usIpa":"/θərˈmɑːmɪtər/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"An instrument used to measure temperature.","vi":"nhiệt kế"}],"examples":[{"en":"She placed the thermometer gently under her son''s tongue.","vi":"Cô ấy nhẹ nhàng đặt nhiệt kế dưới lưỡi con trai.","audioKind":"ex"},{"en":"Accurate thermometers help researchers monitor temperature changes in natural habitats affected by global warming.","vi":"Nhiệt kế chính xác giúp các nhà nghiên cứu theo dõi sự biến đổi nhiệt độ tại các môi trường sống tự nhiên bị ảnh hưởng bởi hiện tượng ấm lên toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"digital thermometer","vi":"nhiệt kế điện tử"},{"en":"clinical thermometer","vi":"nhiệt kế y tế"},{"en":"read a thermometer","vi":"đọc số đo nhiệt kế"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trọng âm rơi vào âm tiết thứ hai; để đo thân nhiệt, thường dùng cụm từ take someone''s temperature.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drunk', 'en-b1-22', 'drunk', '/drʌŋk/', 'B1', 'say rượu; say mê; choáng ngợp (vì quyền lực, v.c.); kẻ say xỉn; người nghiện rượu', 'adj.', 'drink (v.), drunken (adj.), drunkenness (n.)', 'Đồng nghĩa: intoxicated · Trái nghĩa: sober', 'drunk thường đóng vai trò vị ngữ; khi đứng trước bổ nghĩa cho danh từ, người ta thường dùng drunken.', 'He was too drunk to walk home safely.', NULL, 'Anh ấy quá say để có thể đi bộ về nhà an toàn.', '{"wordId":"drunk","ukIpa":"/drʌŋk/","usIpa":"/drʌŋk/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"Unable to think or act normally after drinking alcohol","vi":"say rượu"},{"pos":"adj.","en":"So excited by something that sensible judgment is lost","vi":"say mê; choáng ngợp (vì quyền lực, v.c.)"},{"pos":"n.","en":"Someone who is drunk or frequently drinks too much alcohol","vi":"kẻ say xỉn; người nghiện rượu"}],"examples":[{"en":"He was too drunk to walk home safely.","vi":"Anh ấy quá say để có thể đi bộ về nhà an toàn.","audioKind":"ex"},{"en":"Public awareness campaigns can help reduce accidents caused by drunk drivers, especially among younger adults.","vi":"Các chiến dịch nâng cao nhận thức cộng đồng có thể giúp giảm thiểu các vụ tai nạn do tài xế say rượu gây ra, đặc biệt là ở nhóm người trẻ tuổi.","audioKind":"ex2"}],"collocations":[{"en":"get drunk","vi":"say rượu"},{"en":"drunk driving","vi":"lái xe khi say rượu"},{"en":"drunk with power","vi":"say sưa vì quyền lực"}],"wordFamily":["drink (v.)","drunken (adj.)","drunkenness (n.)"],"synonyms":["intoxicated"],"antonyms":["sober"],"tipVi":"drunk thường đóng vai trò vị ngữ; khi đứng trước bổ nghĩa cho danh từ, người ta thường dùng drunken.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deaf', 'en-b1-22', 'deaf', '/def/', 'B1', 'khiếm thính; điếc', 'adj.', 'deafness (n.), deafen (v.), deafening (adj.)', NULL, 'Phát âm giống def; chữ viết hoa Deaf có thể nhấn mạnh bản sắc văn hóa của người điếc.', 'My deaf cousin taught me some useful everyday signs.', NULL, 'Người anh em họ khiếm thính của tôi đã dạy tôi một số ký hiệu giao tiếp hàng ngày rất hữu ích.', '{"wordId":"deaf","ukIpa":"/def/","usIpa":"/def/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"Unable to hear, or able to hear very little.","vi":"khiếm thính; điếc"}],"examples":[{"en":"My deaf cousin taught me some useful everyday signs.","vi":"Người anh em họ khiếm thính của tôi đã dạy tôi một số ký hiệu giao tiếp hàng ngày rất hữu ích.","audioKind":"ex"},{"en":"Providing captions and sign language interpretation can make public information more accessible to deaf people.","vi":"Việc cung cấp phụ đề và phiên dịch ngôn ngữ ký hiệu có thể giúp người khiếm thính tiếp cận thông tin công cộng dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"deaf people","vi":"người khiếm thính"},{"en":"born deaf","vi":"bẩm sinh điếc"},{"en":"go deaf","vi":"mất thính lực"}],"wordFamily":["deafness (n.)","deafen (v.)","deafening (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Phát âm giống def; chữ viết hoa Deaf có thể nhấn mạnh bản sắc văn hóa của người điếc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unwell', 'en-b1-22', 'unwell', '/ʌnˈwel/', 'B1', 'không khỏe; mệt trong người', 'adj.', 'well (adj.), wellness (n.)', 'Đồng nghĩa: ill, sick · Trái nghĩa: well, healthy', 'Thường đứng sau động từ feel hoặc be làm vị ngữ, ít khi đứng trực tiếp trước danh từ.', 'I felt unwell and went home before lunch.', NULL, 'Tôi cảm thấy không khỏe và đã về nhà trước bữa trưa.', '{"wordId":"unwell","ukIpa":"/ʌnˈwel/","usIpa":"/ʌnˈwel/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"feeling ill or not in good health","vi":"không khỏe; mệt trong người"}],"examples":[{"en":"I felt unwell and went home before lunch.","vi":"Tôi cảm thấy không khỏe và đã về nhà trước bữa trưa.","audioKind":"ex"},{"en":"Employees who feel unwell should be encouraged to stay home to prevent infections spreading at work.","vi":"Nên khuyến khích những nhân viên cảm thấy không khỏe ở nhà để ngăn chặn sự lây lan của dịch bệnh tại nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"feel unwell","vi":"cảm thấy không khỏe"},{"en":"become unwell","vi":"bắt đầu thấy mệt"},{"en":"slightly unwell","vi":"hơi khó chịu trong người"}],"wordFamily":["well (adj.)","wellness (n.)"],"synonyms":["ill","sick"],"antonyms":["well","healthy"],"tipVi":"Thường đứng sau động từ feel hoặc be làm vị ngữ, ít khi đứng trực tiếp trước danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gum', 'en-b1-22', 'gum', '/ɡʌm/', 'B1', 'kẹo cao su; lợi; nướu răng; chất gôm; nhựa cây', 'n.', NULL, NULL, '"gum" với nghĩa kẹo cao su là danh từ không đếm được; trong khi nướu răng thường dùng ở dạng số nhiều "gums".', 'She offered me a piece of mint gum.', NULL, 'Cô ấy mời tôi một miếng kẹo cao su vị bạc hà.', '{"wordId":"gum","ukIpa":"/ɡʌm/","usIpa":"/ɡʌm/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A sweet substance chewed but not swallowed","vi":"kẹo cao su"},{"pos":"n.","en":"The firm pink flesh surrounding the bases of teeth","vi":"lợi; nướu răng"},{"pos":"n.","en":"A sticky substance from plants, often used for making glue","vi":"chất gôm; nhựa cây"}],"examples":[{"en":"She offered me a piece of mint gum.","vi":"Cô ấy mời tôi một miếng kẹo cao su vị bạc hà.","audioKind":"ex"},{"en":"Regular dental checkups can help detect gum disease before it causes serious damage.","vi":"Khám răng định kỳ có thể giúp phát hiện bệnh về nướu trước khi gây ra tổn thương nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"chewing gum","vi":"kẹo cao su"},{"en":"a piece of gum","vi":"một miếng kẹo cao su"},{"en":"gum disease","vi":"bệnh về nướu"},{"en":"natural gum","vi":"nhựa cây tự nhiên"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"gum\" với nghĩa kẹo cao su là danh từ không đếm được; trong khi nướu răng thường dùng ở dạng số nhiều \"gums\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bleed', 'en-b1-22', 'bleed', '/bliːd/', 'B1', 'chảy máu; ra máu', 'v.', 'blood (n.), bleeding (n.)', NULL, 'Dạng quá khứ và quá khứ phân từ đều là bled; blood là danh từ chỉ máu.', 'My finger started to bleed after a small paper cut.', NULL, 'Ngón tay tôi bắt đầu chảy máu sau một vết cắt giấy nhỏ.', '{"wordId":"bleed","ukIpa":"/bliːd/","usIpa":"/bliːd/","cefr":"B1","topic":"health","senses":[{"pos":"v.","en":"To lose blood from a wound or inside the body.","vi":"chảy máu; ra máu"}],"examples":[{"en":"My finger started to bleed after a small paper cut.","vi":"Ngón tay tôi bắt đầu chảy máu sau một vết cắt giấy nhỏ.","audioKind":"ex"},{"en":"First aid courses teach people how to respond safely when minor injuries cause someone to bleed.","vi":"Các khóa học sơ cứu dạy mọi người cách phản ứng an toàn khi chấn thương nhẹ làm ai đó bị chảy máu.","audioKind":"ex2"}],"collocations":[{"en":"bleed heavily","vi":"chảy máu nhiều"},{"en":"bleed internally","vi":"chảy máu trong"},{"en":"stop the bleeding","vi":"cầm máu"}],"wordFamily":["blood (n.)","bleeding (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là bled; blood là danh từ chỉ máu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hunger', 'en-b1-22', 'hunger', '/ˈhʌŋɡɚ/', 'B1', 'sự đói; nạn đói; sự khao khát; khao khát; khát khao', 'n.', 'hungry (adj.), hungrily (adv.)', NULL, 'Danh từ thường không đếm được; khao khát điều gì dùng hunger for.', 'A bowl of warm soup quickly satisfied my hunger.', NULL, 'Một bát súp ấm đã nhanh chóng xua tan cơn đói của tôi.', '{"wordId":"hunger","ukIpa":"/ˈhʌŋɡə/","usIpa":"/ˈhʌŋɡɚ/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"the need for food or suffering caused by its lack","vi":"sự đói; nạn đói"},{"pos":"n.","en":"a strong desire for something","vi":"sự khao khát"},{"pos":"v.","en":"to want something very strongly","vi":"khao khát; khát khao"}],"examples":[{"en":"A bowl of warm soup quickly satisfied my hunger.","vi":"Một bát súp ấm đã nhanh chóng xua tan cơn đói của tôi.","audioKind":"ex"},{"en":"Reducing global hunger requires reliable food supplies as well as better access to education and employment.","vi":"Giảm thiểu nạn đói toàn cầu đòi hỏi nguồn cung cấp thực phẩm ổn định cũng như khả năng tiếp cận tốt hơn với giáo dục và việc làm.","audioKind":"ex2"}],"collocations":[{"en":"satisfy your hunger","vi":"làm hết đói"},{"en":"combat hunger","vi":"chống lại nạn đói"},{"en":"a hunger for knowledge","vi":"niềm khao khát tri thức"},{"en":"hunger for success","vi":"khát khao thành công"}],"wordFamily":["hungry (adj.)","hungrily (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ thường không đếm được; khao khát điều gì dùng hunger for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fever', 'en-b1-22', 'fever', '/ˈfiːvər/', 'B1', 'cơn sốt; sự phát sốt; sự cuồng nhiệt; sự phấn khích tột độ', 'n.', 'feverish (adj.), feverishly (adv.)', NULL, 'Nói bị sốt thường dùng have a fever, cũng có thể dùng have a temperature.', 'He stayed in bed because he had a fever.', NULL, 'Anh ấy phải nằm trên giường vì bị sốt.', '{"wordId":"fever","ukIpa":"/ˈfiːvə/","usIpa":"/ˈfiːvər/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"a body temperature higher than normal, usually caused by illness","vi":"cơn sốt; sự phát sốt"},{"pos":"n.","en":"intense excitement shared by a person or group","vi":"sự cuồng nhiệt; sự phấn khích tột độ"}],"examples":[{"en":"He stayed in bed because he had a fever.","vi":"Anh ấy phải nằm trên giường vì bị sốt.","audioKind":"ex"},{"en":"A persistent fever may indicate an infection and should be assessed by a qualified healthcare professional.","vi":"Sốt kéo dài có thể cho thấy tình trạng nhiễm trùng và nên được đánh giá bởi chuyên gia y tế có chuyên môn.","audioKind":"ex2"}],"collocations":[{"en":"have a fever","vi":"bị sốt"},{"en":"a high fever","vi":"sốt cao"},{"en":"a mild fever","vi":"sốt nhẹ"},{"en":"football fever","vi":"cơn cuồng bóng đá"}],"wordFamily":["feverish (adj.)","feverishly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Nói bị sốt thường dùng have a fever, cũng có thể dùng have a temperature.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_poison', 'en-b1-22', 'poison', '/ˈpɔɪzən/', 'B1', 'chất độc; thuốc độc; làm nhiễm độc; đầu độc; làm tổn hại; làm vẩn đục (mối quan hệ, tình hình)', 'n.', 'poisonous (adj.), poisoning (n.)', 'Đồng nghĩa: toxin', 'poison vừa là danh từ vừa là động từ; tính từ mang nghĩa ''có độc'' là poisonous.', 'Some garden plants contain poison, so keep pets away.', NULL, 'Một số loài cây cảnh có chứa chất độc, vì vậy hãy để thú cưng tránh xa.', '{"wordId":"poison","ukIpa":"/ˈpɔɪzən/","usIpa":"/ˈpɔɪzən/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A substance that can seriously harm or kill living things.","vi":"chất độc; thuốc độc"},{"pos":"v.","en":"Harm living things or contaminate something with a toxic substance.","vi":"làm nhiễm độc; đầu độc"},{"pos":"v.","en":"Make a relationship or situation unpleasant or harmful.","vi":"làm tổn hại; làm vẩn đục (mối quan hệ, tình hình)"}],"examples":[{"en":"Some garden plants contain poison, so keep pets away.","vi":"Một số loài cây cảnh có chứa chất độc, vì vậy hãy để thú cưng tránh xa.","audioKind":"ex"},{"en":"Toxic waste from poorly regulated factories can poison rivers, threatening wildlife and the health of nearby communities.","vi":"Chất thải độc hại từ các nhà máy thiếu sự quản lý chặt chẽ có thể làm ô nhiễm các con sông, đe dọa động vật hoang dã và sức khỏe của các cộng đồng dân cư gần đó.","audioKind":"ex2"}],"collocations":[{"en":"contain poison","vi":"chứa chất độc"},{"en":"poison the water supply","vi":"làm ô nhiễm nguồn nước"},{"en":"poisoning prevention","vi":"phòng ngừa ngộ độc"},{"en":"poison relations","vi":"làm rạn nứt mối quan hệ"}],"wordFamily":["poisonous (adj.)","poisoning (n.)"],"synonyms":["toxin"],"antonyms":[],"tipVi":"poison vừa là danh từ vừa là động từ; tính từ mang nghĩa ''có độc'' là poisonous.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drug', 'en-b1-22', 'drug', '/drʌɡ/', 'B1', 'thuốc chữa bệnh; chất gây nghiện; ma túy; chuốc thuốc mê; cho uống thuốc độc', 'n.', 'drugged (adj.)', 'Đồng nghĩa: medicine, medication', 'Có thể chỉ thuốc chữa bệnh hoặc chất gây nghiện, cần xét theo ngữ cảnh.', 'The doctor prescribed a drug to ease her pain.', NULL, 'Bác sĩ kê đơn một loại thuốc để làm dịu cơn đau cho cô ấy.', '{"wordId":"drug","ukIpa":"/drʌɡ/","usIpa":"/drʌɡ/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"A substance used to prevent or treat illness.","vi":"thuốc chữa bệnh"},{"pos":"n.","en":"A substance taken for its effects on mind or body.","vi":"chất gây nghiện; ma túy"},{"pos":"v.","en":"To give someone a substance that makes them unconscious or weak.","vi":"chuốc thuốc mê; cho uống thuốc độc"}],"examples":[{"en":"The doctor prescribed a drug to ease her pain.","vi":"Bác sĩ kê đơn một loại thuốc để làm dịu cơn đau cho cô ấy.","audioKind":"ex"},{"en":"New drug development requires extensive testing to ensure that treatments are both safe and effective.","vi":"Quá trình phát triển thuốc mới đòi hỏi phải thử nghiệm diện rộng để đảm bảo rằng các phương pháp điều trị vừa an toàn vừa hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"prescription drug","vi":"thuốc theo đơn"},{"en":"drug development","vi":"phát triển thuốc mới"},{"en":"drug abuse","vi":"lạm dụng ma túy"},{"en":"drug resistance","vi":"tính kháng thuốc"}],"wordFamily":["drugged (adj.)"],"synonyms":["medicine","medication"],"antonyms":[],"tipVi":"Có thể chỉ thuốc chữa bệnh hoặc chất gây nghiện, cần xét theo ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alcoholic', 'en-b1-22', 'alcoholic', '/ˌælkəˈhɑːlɪk/', 'B1', 'chứa cồn; có cồn; mắc chứng nghiện rượu; do rượu gây ra; người nghiện rượu', 'adj.', 'alcohol (n.), alcoholism (n.), non-alcoholic (adj.)', 'Trái nghĩa: non-alcoholic', 'Chỉ người khi dùng person with alcohol dependence sẽ mang tính tôn trọng hơn.', 'The waiter asked whether we wanted any alcoholic drinks.', NULL, 'Người phục vụ hỏi liệu chúng tôi có muốn gọi đồ uống có cồn nào không.', '{"wordId":"alcoholic","ukIpa":"/ˌælkəˈhɒlɪk/","usIpa":"/ˌælkəˈhɑːlɪk/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"Containing alcohol.","vi":"chứa cồn; có cồn"},{"pos":"adj.","en":"Affected by alcohol dependence, or caused by alcohol.","vi":"mắc chứng nghiện rượu; do rượu gây ra"},{"pos":"n.","en":"A person who is dependent on alcohol.","vi":"người nghiện rượu"}],"examples":[{"en":"The waiter asked whether we wanted any alcoholic drinks.","vi":"Người phục vụ hỏi liệu chúng tôi có muốn gọi đồ uống có cồn nào không.","audioKind":"ex"},{"en":"Clear information about alcoholic beverages can help consumers understand health risks and make more informed choices.","vi":"Thông tin rõ ràng về các loại đồ uống có cồn có thể giúp người tiêu dùng hiểu rõ rủi ro sức khỏe và đưa ra lựa chọn sáng suốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"alcoholic drinks","vi":"đồ uống có cồn"},{"en":"alcoholic beverages","vi":"thức uống có cồn"},{"en":"alcoholic liver disease","vi":"bệnh gan do rượu"}],"wordFamily":["alcohol (n.)","alcoholism (n.)","non-alcoholic (adj.)"],"synonyms":[],"antonyms":["non-alcoholic"],"tipVi":"Chỉ người khi dùng person with alcohol dependence sẽ mang tính tôn trọng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ache', 'en-b1-22', 'ache', '/eɪk/', 'B1', 'đau âm ỉ; nhức mỏi; cơn đau âm ỉ; sự nhức mỏi; khao khát; mong mỏi da diết', 'v.', 'aching (adj.), achy (adj.)', 'Đồng nghĩa: hurt', 'ache thường chỉ cơn đau âm ỉ kéo dài; pain có thể dùng chung cho nhiều loại đau khác nhau.', 'My legs ache after walking up all those stairs.', NULL, 'Chân tôi ê ẩm sau khi leo toàn bộ số bậc cầu thang đó.', '{"wordId":"ache","ukIpa":"/eɪk/","usIpa":"/eɪk/","cefr":"B1","topic":"health","senses":[{"pos":"v.","en":"to feel a steady pain that is usually not sharp","vi":"đau âm ỉ; nhức mỏi"},{"pos":"n.","en":"a steady pain that lasts for some time","vi":"cơn đau âm ỉ; sự nhức mỏi"},{"pos":"v.","en":"to want something very deeply","vi":"khao khát; mong mỏi da diết"}],"examples":[{"en":"My legs ache after walking up all those stairs.","vi":"Chân tôi ê ẩm sau khi leo toàn bộ số bậc cầu thang đó.","audioKind":"ex"},{"en":"Office workers whose backs ache regularly may benefit from adjustable desks and more frequent movement breaks.","vi":"Những nhân viên văn phòng bị đau lưng thường xuyên có thể được hỗ trợ nhờ bàn làm việc có thể điều chỉnh độ cao và những khoảng nghỉ vận động thường xuyên hơn.","audioKind":"ex2"}],"collocations":[{"en":"a dull ache","vi":"cơn đau âm ỉ"},{"en":"aches and pains","vi":"những cơn đau nhức khắp cơ thể"},{"en":"ache for","vi":"khao khát"}],"wordFamily":["aching (adj.)","achy (adj.)"],"synonyms":["hurt"],"antonyms":[],"tipVi":"ache thường chỉ cơn đau âm ỉ kéo dài; pain có thể dùng chung cho nhiều loại đau khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wrist', 'en-b1-22', 'wrist', '/rɪst/', 'B1', 'cổ tay', 'n.', 'wristband (n.), wristwatch (n.)', NULL, 'Chữ w ở đầu không phát âm; cổ tay là wrist, còn mắt cá chân là ankle.', 'She wore a silver bracelet around her wrist.', NULL, 'Cô ấy đeo một chiếc vòng tay bằng bạc quanh cổ tay.', '{"wordId":"wrist","ukIpa":"/rɪst/","usIpa":"/rɪst/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"The joint connecting your hand to your arm.","vi":"cổ tay"}],"examples":[{"en":"She wore a silver bracelet around her wrist.","vi":"Cô ấy đeo một chiếc vòng tay bằng bạc quanh cổ tay.","audioKind":"ex"},{"en":"Office workers should adjust their keyboards to reduce pressure on their wrists during prolonged computer use.","vi":"Nhân viên văn phòng nên điều chỉnh bàn phím để giảm áp lực lên cổ tay khi sử dụng máy tính trong thời gian dài.","audioKind":"ex2"}],"collocations":[{"en":"a wrist injury","vi":"chấn thương cổ tay"},{"en":"sprain your wrist","vi":"trật cổ tay"},{"en":"a wrist support","vi":"dây đeo hỗ trợ cổ tay"}],"wordFamily":["wristband (n.)","wristwatch (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ w ở đầu không phát âm; cổ tay là wrist, còn mắt cá chân là ankle.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sore', 'en-b1-22', 'sore', '/sɔːr/', 'B1', 'đau; nhức mỏi (nhất là khi chạm vào hoặc cử động); vết loét; chỗ đau sưng; bực bội; cáu giận vì điều bất công hoặc thất vọng', 'adj.', 'soreness (n.)', 'Đồng nghĩa: painful', 'Tính từ sore thường dùng để miêu tả các bộ phận cơ thể bị đau, ví dụ như a sore throat.', 'My legs are sore after yesterday''s long walk.', NULL, 'Chân tôi bị nhức mỏi sau chuyến đi bộ dài ngày hôm qua.', '{"wordId":"sore","ukIpa":"/sɔː/","usIpa":"/sɔːr/","cefr":"B1","topic":"health","senses":[{"pos":"adj.","en":"painful, especially when touched or moved","vi":"đau; nhức mỏi (nhất là khi chạm vào hoặc cử động)"},{"pos":"n.","en":"a painful damaged area on the skin","vi":"vết loét; chỗ đau sưng"},{"pos":"adj.","en":"upset or annoyed about something unfair or disappointing","vi":"bực bội; cáu giận vì điều bất công hoặc thất vọng"}],"examples":[{"en":"My legs are sore after yesterday''s long walk.","vi":"Chân tôi bị nhức mỏi sau chuyến đi bộ dài ngày hôm qua.","audioKind":"ex"},{"en":"Office workers may develop sore muscles if they remain seated without taking regular breaks.","vi":"Nhân viên văn phòng có thể bị đau nhức cơ bắp nếu họ ngồi làm việc liên tục mà không nghỉ giải lao đều đặn.","audioKind":"ex2"}],"collocations":[{"en":"sore throat","vi":"đau họng"},{"en":"sore muscles","vi":"đau nhức cơ bắp"},{"en":"feel sore","vi":"cảm thấy đau nhức"}],"wordFamily":["soreness (n.)"],"synonyms":["painful"],"antonyms":[],"tipVi":"Tính từ sore thường dùng để miêu tả các bộ phận cơ thể bị đau, ví dụ như a sore throat.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_operation', 'en-b1-22', 'operation', '/ˌɑːpəˈreɪʃən/', 'B1', 'ca phẫu thuật; sự vận hành; hoạt động quản lý; cuộc hành quân; chiến dịch có tổ chức', 'n.', 'operate (v.), operator (n.), operational (adj.)', NULL, 'Bộ phận cơ thể cần phẫu thuật thường đi với giới từ on: an operation on the knee.', 'My aunt is recovering well after her knee operation.', NULL, 'Dì tôi đang hồi phục sức khỏe rất tốt sau ca phẫu thuật đầu gối.', '{"wordId":"operation","ukIpa":"/ˌɒpəˈreɪʃən/","usIpa":"/ˌɑːpəˈreɪʃən/","cefr":"B1","topic":"health","senses":[{"pos":"n.","en":"Medical treatment involving cutting into the body.","vi":"ca phẫu thuật"},{"pos":"n.","en":"The functioning or management of a machine, system, or business.","vi":"sự vận hành; hoạt động quản lý"},{"pos":"n.","en":"A planned activity involving several people working together.","vi":"cuộc hành quân; chiến dịch có tổ chức"}],"examples":[{"en":"My aunt is recovering well after her knee operation.","vi":"Dì tôi đang hồi phục sức khỏe rất tốt sau ca phẫu thuật đầu gối.","audioKind":"ex"},{"en":"The successful operation of public transport systems depends on reliable funding and careful long-term planning.","vi":"Sự vận hành thành công của hệ thống giao thông công cộng phụ thuộc vào nguồn vốn ổn định và kế hoạch dài hạn chu đáo.","audioKind":"ex2"}],"collocations":[{"en":"have an operation","vi":"trải qua một ca phẫu thuật"},{"en":"perform an operation","vi":"tiến hành phẫu thuật"},{"en":"in operation","vi":"đang hoạt động"},{"en":"rescue operation","vi":"chiến dịch cứu hộ"}],"wordFamily":["operate (v.)","operator (n.)","operational (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Bộ phận cơ thể cần phẫu thuật thường đi với giới từ on: an operation on the knee.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_22_1', 'en-b1-22', 'Cách dùng “gum” (n.) — kẹo cao su', 'chewing gum  ·  a piece of gum  ·  gum disease', '"gum" với nghĩa kẹo cao su là danh từ không đếm được; trong khi nướu răng thường dùng ở dạng số nhiều "gums".', NULL, '[{"hanzi":"She offered me a piece of mint gum.","pinyin":"","meaning":"Cô ấy mời tôi một miếng kẹo cao su vị bạc hà."},{"hanzi":"Regular dental checkups can help detect gum disease before it causes serious damage.","pinyin":"","meaning":"Khám răng định kỳ có thể giúp phát hiện bệnh về nướu trước khi gây ra tổn thương nghiêm trọng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_22_2', 'en-b1-22', 'Cách dùng “injury” (n.) — thương tích; chấn thương', 'suffer an injury  ·  a serious injury  ·  a knee injury', 'Vị trí chấn thương cụ thể có thể đếm được; khi chỉ tổn thương cơ thể nói chung thường không đếm được.', 'Họ từ (Word Family): injure (v.), injured (adj.)', '[{"hanzi":"His knee injury kept him away from football practice.","pinyin":"","meaning":"Chấn thương đầu gối khiến anh ấy phải vắng mặt trong buổi tập bóng đá."},{"hanzi":"Employers should provide regular safety training to reduce the risk of injury among workers operating heavy machinery.","pinyin":"","meaning":"Người sử dụng lao động nên cung cấp đào tạo an toàn thường xuyên để giảm nguy cơ chấn thương cho công nhân vận hành máy móc hạng nặng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_22_3', 'en-b1-22', 'Cách dùng “sunscreen” (n.) — kem chống nắng', 'apply sunscreen  ·  reapply sunscreen  ·  water-resistant sunscreen', 'Thông thường là danh từ không đếm được; hành động bôi kem chống nắng dùng động từ apply hoặc put on.', 'Đồng nghĩa: suncream', '[{"hanzi":"Please put on sunscreen before we leave for the beach.","pinyin":"","meaning":"Xin hãy bôi kem chống nắng trước khi chúng ta khởi hành đi ra biển."},{"hanzi":"Using sunscreen alongside protective clothing can reduce skin damage caused by prolonged exposure to sunlight.","pinyin":"","meaning":"Việc sử dụng kem chống nắng kết hợp với mặc đồ bảo hộ có thể làm giảm tổn thương da do tiếp xúc lâu với ánh nắng mặt trời."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_22_4', 'en-b1-22', 'Cách dùng “drunk” (adj.) — say rượu', 'get drunk  ·  drunk driving  ·  drunk with power', 'drunk thường đóng vai trò vị ngữ; khi đứng trước bổ nghĩa cho danh từ, người ta thường dùng drunken.', 'Họ từ (Word Family): drink (v.), drunken (adj.), drunkenness (n.) | Đồng nghĩa: intoxicated · Trái nghĩa: sober', '[{"hanzi":"He was too drunk to walk home safely.","pinyin":"","meaning":"Anh ấy quá say để có thể đi bộ về nhà an toàn."},{"hanzi":"Public awareness campaigns can help reduce accidents caused by drunk drivers, especially among younger adults.","pinyin":"","meaning":"Các chiến dịch nâng cao nhận thức cộng đồng có thể giúp giảm thiểu các vụ tai nạn do tài xế say rượu gây ra, đặc biệt là ở nhóm người trẻ tuổi."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_22_1', 'en-b1-22', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_1_1', 'ten_b1_22_1', 'injury', 'His knee injury kept him away from football practice.', 'His knee injury kept him away from football practice.', '/ˈɪndʒəri/', 'Chấn thương đầu gối khiến anh ấy phải vắng mặt trong buổi tập bóng đá.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_1_2', 'ten_b1_22_1', 'first-aid', 'There is a first-aid kit in the kitchen cupboard.', 'There is a first-aid kit in the kitchen cupboard.', '/ˌfɝːst ˈeɪd/', 'Có một hộp sơ cứu trong tủ bếp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_1_3', 'ten_b1_22_1', 'workout', 'After a short workout, I felt ready for breakfast.', 'After a short workout, I felt ready for breakfast.', '/ˈwɝːkaʊt/', 'Sau một buổi tập ngắn, tôi thấy sẵn sàng để ăn sáng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_1_4', 'ten_b1_22_1', 'pregnant', 'My cousin is pregnant and expects her baby in June.', 'My cousin is pregnant and expects her baby in June.', '/ˈpreɡnənt/', 'Em họ tôi đang mang thai và dự sinh vào tháng Sáu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_1_5', 'ten_b1_22_1', 'clinic', 'The clinic near our house opens early on weekdays.', 'The clinic near our house opens early on weekdays.', '/ˈklɪnɪk/', 'Phòng khám gần nhà chúng tôi mở cửa rất sớm vào các ngày trong tuần.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_1_6', 'ten_b1_22_1', 'ambulance', 'An ambulance arrived quickly and took him to hospital.', 'An ambulance arrived quickly and took him to hospital.', '/ˈæmbjələns/', 'Xe cứu thương nhanh chóng đến nơi và đưa anh ấy vào bệnh viện.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_1_7', 'ten_b1_22_1', 'sunscreen', 'Please put on sunscreen before we leave for the beach.', 'Please put on sunscreen before we leave for the beach.', '/ˈsʌnskriːn/', 'Xin hãy bôi kem chống nắng trước khi chúng ta khởi hành đi ra biển.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_1_8', 'ten_b1_22_1', 'thermometer', 'She placed the thermometer gently under her son''s tongue.', 'She placed the thermometer gently under her son''s tongue.', '/θərˈmɑːmɪtər/', 'Cô ấy nhẹ nhàng đặt nhiệt kế dưới lưỡi con trai.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_22_1_1', 'en-b1-22', 'ten_b1_22_1', 'listening', 'listening', 'His knee injury kept him away from football practice.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xe cứu thương nhanh chóng đến nơi và đưa anh ấy vào bệnh viện.","Chân tôi ê ẩm sau khi leo toàn bộ số bậc cầu thang đó.","Chấn thương đầu gối khiến anh ấy phải vắng mặt trong buổi tập bóng đá.","Chân tôi bị nhức mỏi sau chuyến đi bộ dài ngày hôm qua."]'::jsonb, 2, 'His knee injury kept him away from football practice. → Chấn thương đầu gối khiến anh ấy phải vắng mặt trong buổi tập bóng đá.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_22_1_2', 'en-b1-22', 'ten_b1_22_1', 'listening', 'listening', 'There is a first-aid kit in the kitchen cupboard.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bác sĩ kê đơn một loại thuốc để làm dịu cơn đau cho cô ấy.","Tôi cảm thấy không khỏe và đã về nhà trước bữa trưa.","Có một hộp sơ cứu trong tủ bếp.","Cô ấy nhẹ nhàng đặt nhiệt kế dưới lưỡi con trai."]'::jsonb, 2, 'There is a first-aid kit in the kitchen cupboard. → Có một hộp sơ cứu trong tủ bếp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_22_1_3', 'en-b1-22', 'ten_b1_22_1', 'listening', 'listening', 'After a short workout, I felt ready for breakfast.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bác sĩ kê đơn một loại thuốc để làm dịu cơn đau cho cô ấy.","Tôi cảm thấy không khỏe và đã về nhà trước bữa trưa.","Người anh em họ khiếm thính của tôi đã dạy tôi một số ký hiệu giao tiếp hàng ngày rất hữu ích.","Sau một buổi tập ngắn, tôi thấy sẵn sàng để ăn sáng."]'::jsonb, 3, 'After a short workout, I felt ready for breakfast. → Sau một buổi tập ngắn, tôi thấy sẵn sàng để ăn sáng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_22_2', 'en-b1-22', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_2_1', 'ten_b1_22_2', 'injury', 'Employers should provide regular safety training to reduce the risk of injury among workers operating heavy machinery.', 'Employers should provide regular safety training to reduce the risk of injury among workers operating heavy machinery.', '/ˈɪndʒəri/', 'Người sử dụng lao động nên cung cấp đào tạo an toàn thường xuyên để giảm nguy cơ chấn thương cho công nhân vận hành máy móc hạng nặng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_2_2', 'ten_b1_22_2', 'first-aid', 'Employers should provide first-aid training so that staff can respond effectively to minor workplace injuries.', 'Employers should provide first-aid training so that staff can respond effectively to minor workplace injuries.', '/ˌfɝːst ˈeɪd/', 'Người sử dụng lao động nên cung cấp đào tạo sơ cứu để nhân viên có thể ứng phó hiệu quả với các chấn thương nhẹ tại nơi làm việc.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_2_3', 'ten_b1_22_2', 'workout', 'A regular workout can improve physical health and help office workers manage stress more effectively.', 'A regular workout can improve physical health and help office workers manage stress more effectively.', '/ˈwɝːkaʊt/', 'Tập luyện thường xuyên có thể cải thiện sức khỏe thể chất và giúp nhân viên văn phòng quản lý căng thẳng hiệu quả hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_2_4', 'ten_b1_22_2', 'pregnant', 'Accessible healthcare helps pregnant women receive regular check-ups and reliable advice throughout their pregnancy.', 'Accessible healthcare helps pregnant women receive regular check-ups and reliable advice throughout their pregnancy.', '/ˈpreɡnənt/', 'Dịch vụ chăm sóc sức khỏe dễ tiếp cận giúp phụ nữ mang thai được khám định kỳ và nhận những lời khuyên đáng tin cậy trong suốt thai kỳ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_2_5', 'ten_b1_22_2', 'clinic', 'Local clinics can reduce pressure on hospitals by treating common illnesses and providing preventive care.', 'Local clinics can reduce pressure on hospitals by treating common illnesses and providing preventive care.', '/ˈklɪnɪk/', 'Các phòng khám địa phương có thể giảm tải áp lực cho bệnh viện bằng cách điều trị các bệnh thông thường và cung cấp dịch vụ chăm sóc phòng ngừa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_22_2_6', 'ten_b1_22_2', 'ambulance', 'Improving ambulance access in remote communities can reduce delays in treatment and increase patients'' chances of recovery.', 'Improving ambulance access in remote communities can reduce delays in treatment and increase patients'' chances of recovery.', '/ˈæmbjələns/', 'Cải thiện khả năng tiếp cận xe cứu thương ở các cộng đồng vùng sâu vùng xa có thể giảm thời gian chậm trễ trong điều trị và nâng cao cơ hội hồi phục của bệnh nhân.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_22_2_1', 'en-b1-22', 'ten_b1_22_2', 'listening', 'listening', 'Employers should provide regular safety training to reduce the risk of injury among workers operating heavy machinery.', NULL, 'Trong câu vừa nghe, từ “injury” mang nghĩa nào sau đây?', '["quý giá; đắt tiền","thuộc về miền Nam; ở phía nam","thương tích; chấn thương","đóng băng; làm đông lạnh"]'::jsonb, 2, '“injury” (/ˈɪndʒəri/): thương tích; chấn thương. Câu đầy đủ: Employers should provide regular safety training to reduce the risk of injury among workers operating heavy machinery.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_22_2_2', 'en-b1-22', 'ten_b1_22_2', 'listening', 'listening', 'Employers should provide first-aid training so that staff can respond effectively to minor workplace injuries.', NULL, 'Trong câu vừa nghe, từ “first-aid” mang nghĩa nào sau đây?', '["thuộc về sơ cứu; cấp cứu","phần thưởng; sự đền bù; tiền thưởng","xấu hổ; hổ thẹn","nhà hóa học"]'::jsonb, 0, '“first-aid” (/ˌfɝːst ˈeɪd/): thuộc về sơ cứu; cấp cứu. Câu đầy đủ: Employers should provide first-aid training so that staff can respond effectively to minor workplace injuries.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
