INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_1', 'en-b1-22', NULL, 'comprehensive_test', 'listening', 'injury', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chủ đề; tư tưởng chủ đạo","đã đính hôn","thương tích; chấn thương","ảnh hưởng; sức ảnh hưởng"]'::jsonb, 2, 'injury (/ˈɪndʒəri/) → thương tích; chấn thương', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_2', 'en-b1-22', NULL, 'comprehensive_test', 'listening', 'There is a first-aid kit in the kitchen cupboard.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy phải nằm trên giường vì bị sốt.","Cô ấy mời tôi một miếng kẹo cao su vị bạc hà.","Có một hộp sơ cứu trong tủ bếp.","Phòng khám gần nhà chúng tôi mở cửa rất sớm vào các ngày trong tuần."]'::jsonb, 2, 'There is a first-aid kit in the kitchen cupboard. → Có một hộp sơ cứu trong tủ bếp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_3', 'en-b1-22', NULL, 'comprehensive_test', 'listening', 'workout', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cái xô; một xô","gây bối rối; xấu hổ; khó xử","buổi tập luyện; rèn luyện thể chất","chất nhão; hồ dán"]'::jsonb, 2, 'workout (/ˈwɝːkaʊt/) → buổi tập luyện; rèn luyện thể chất', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_4', 'en-b1-22', NULL, 'comprehensive_test', 'listening', 'My cousin is pregnant and expects her baby in June.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xin hãy bôi kem chống nắng trước khi chúng ta khởi hành đi ra biển.","Sau một buổi tập ngắn, tôi thấy sẵn sàng để ăn sáng.","Chân tôi ê ẩm sau khi leo toàn bộ số bậc cầu thang đó.","Em họ tôi đang mang thai và dự sinh vào tháng Sáu."]'::jsonb, 3, 'My cousin is pregnant and expects her baby in June. → Em họ tôi đang mang thai và dự sinh vào tháng Sáu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_5', 'en-b1-22', NULL, 'comprehensive_test', 'listening', 'clinic', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["da rám nắng","thúc đẩy; khuyến khích; đề cao","buồn bã; lo lắng; thất vọng","phòng khám; phòng khám đa khoa/chuyên khoa"]'::jsonb, 3, 'clinic (/ˈklɪnɪk/) → phòng khám; phòng khám đa khoa/chuyên khoa', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_6', 'en-b1-22', NULL, 'comprehensive_test', 'listening', 'An ambulance arrived quickly and took him to hospital.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dì tôi đang hồi phục sức khỏe rất tốt sau ca phẫu thuật đầu gối.","Chân tôi bị nhức mỏi sau chuyến đi bộ dài ngày hôm qua.","Xe cứu thương nhanh chóng đến nơi và đưa anh ấy vào bệnh viện.","Cô ấy mời tôi một miếng kẹo cao su vị bạc hà."]'::jsonb, 2, 'An ambulance arrived quickly and took him to hospital. → Xe cứu thương nhanh chóng đến nơi và đưa anh ấy vào bệnh viện.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_7', 'en-b1-22', NULL, 'comprehensive_test', 'listening', 'sunscreen', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sừng (trên đầu động vật)","hiểu lầm; hiểu sai","làm cho ai đó ấn tượng; gây ấn tượng sâu sắc","kem chống nắng"]'::jsonb, 3, 'sunscreen (/ˈsʌnskriːn/) → kem chống nắng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_8', 'en-b1-22', NULL, 'comprehensive_test', 'listening', 'She placed the thermometer gently under her son''s tongue.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một bát súp ấm đã nhanh chóng xua tan cơn đói của tôi.","Cô ấy mời tôi một miếng kẹo cao su vị bạc hà.","Sau một buổi tập ngắn, tôi thấy sẵn sàng để ăn sáng.","Cô ấy nhẹ nhàng đặt nhiệt kế dưới lưỡi con trai."]'::jsonb, 3, 'She placed the thermometer gently under her son''s tongue. → Cô ấy nhẹ nhàng đặt nhiệt kế dưới lưỡi con trai.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_9', 'en-b1-22', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A place providing medical advice or treatment without overnight stays.”?', '["clinic","drunk","sore","alcoholic"]'::jsonb, 0, 'clinic (/ˈklɪnɪk/) → phòng khám; phòng khám đa khoa/chuyên khoa', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_10', 'en-b1-22', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A vehicle that transports sick or injured people for medical care.”?', '["first-aid","pregnant","ambulance","thermometer"]'::jsonb, 2, 'ambulance (/ˈæmbjələns/) → xe cứu thương; xe cấp cứu', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_11', 'en-b1-22', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A substance applied to skin to protect it from sunlight.”?', '["sunscreen","fever","poison","sore"]'::jsonb, 0, 'sunscreen (/ˈsʌnskriːn/) → kem chống nắng', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
