INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_18', 'en-b1-22', NULL, 'comprehensive_test', 'reading', NULL, 'Employers should provide regular safety training to reduce the risk of injury among workers operating heavy machinery.', 'Dựa vào câu trên, từ “injury” có nghĩa phù hợp nhất là gì?', '["gói; bọc; quấn","sự liên lạc; sự tiếp xúc","thương tích; chấn thương","vô dụng; không có ích; không đạt được kết quả mong muốn"]'::jsonb, 2, 'injury: thương tích; chấn thương. Dịch cả câu: Người sử dụng lao động nên cung cấp đào tạo an toàn thường xuyên để giảm nguy cơ chấn thương cho công nhân vận hành máy móc hạng nặng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_19', 'en-b1-22', NULL, 'comprehensive_test', 'reading', NULL, 'Employers should provide first-aid training so that staff can respond effectively to minor workplace injuries.', 'Dựa vào câu trên, từ “first-aid” có nghĩa phù hợp nhất là gì?', '["thợ đánh máy; nhân viên đánh máy","buồn bã; lo lắng; thất vọng","lễ kỷ niệm; sự kiện ăn mừng","thuộc về sơ cứu; cấp cứu"]'::jsonb, 3, 'first-aid: thuộc về sơ cứu; cấp cứu. Dịch cả câu: Người sử dụng lao động nên cung cấp đào tạo sơ cứu để nhân viên có thể ứng phó hiệu quả với các chấn thương nhẹ tại nơi làm việc.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_20', 'en-b1-22', NULL, 'comprehensive_test', 'reading', NULL, 'A regular workout can improve physical health and help office workers manage stress more effectively.', 'Dựa vào câu trên, từ “workout” có nghĩa phù hợp nhất là gì?', '["một tỷ (1.000.000.000)","học kỳ","buổi tập luyện; rèn luyện thể chất","tiền xe; tiền vé; cước phí"]'::jsonb, 2, 'workout: buổi tập luyện; rèn luyện thể chất. Dịch cả câu: Tập luyện thường xuyên có thể cải thiện sức khỏe thể chất và giúp nhân viên văn phòng quản lý căng thẳng hiệu quả hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_21', 'en-b1-22', NULL, 'comprehensive_test', 'reading', NULL, 'Accessible healthcare helps pregnant women receive regular check-ups and reliable advice throughout their pregnancy.', 'Dựa vào câu trên, từ “pregnant” có nghĩa phù hợp nhất là gì?', '["mang thai; có bầu","khẩu trang; mặt nạ","tổ chức; cơ quan; hiệp hội","những thứ được sản xuất để bán hoặc vận chuyển để trao đổi thương mại; hàng hóa; sản phẩm"]'::jsonb, 0, 'pregnant: mang thai; có bầu. Dịch cả câu: Dịch vụ chăm sóc sức khỏe dễ tiếp cận giúp phụ nữ mang thai được khám định kỳ và nhận những lời khuyên đáng tin cậy trong suốt thai kỳ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_22', 'en-b1-22', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cổ tay”', '["contest","membership","wrist","starfish"]'::jsonb, 2, 'cổ tay → wrist (/rɪst/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_23', 'en-b1-22', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đau; nhức mỏi (nhất là khi chạm vào hoặc cử động)”', '["biologist","tractor","sore","pretend"]'::jsonb, 2, 'đau; nhức mỏi (nhất là khi chạm vào hoặc cử động) → sore (/sɔːr/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_22_24', 'en-b1-22', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ca phẫu thuật”', '["operation","shocked","rugby","convince"]'::jsonb, 0, 'ca phẫu thuật → operation (/ˌɑːpəˈreɪʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-23', 'en', 'Bài 23: Nghệ thuật & Sáng tạo (1) - CEFR B1', 'CEFR B1', 'B1 · Nghệ thuật', '26 từ vựng Tiếng Anh CEFR B1 chủ đề nghệ thuật & sáng tạo kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3023, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comic', 'en-b1-23', 'comic', '/ˈkɑːmɪk/', 'B1', 'hài hước; liên quan đến hài kịch; truyện tranh (ấn phẩm kể chuyện qua chuỗi tranh vẽ); diễn viên hài; nghệ sĩ hài', 'adj.', 'comical (adj.), comically (adv.), comedy (n.)', 'Đồng nghĩa: funny, humorous · Trái nghĩa: serious', 'Comic có thể chỉ các yếu tố hài kịch; trong khi comical nhấn mạnh tính chất buồn cười, lố bịch.', 'His comic dance had everyone laughing at the party.', NULL, 'Điệu nhảy hài hước của anh ấy làm mọi người cười vang trong buổi tiệc.', '{"wordId":"comic","ukIpa":"/ˈkɒmɪk/","usIpa":"/ˈkɑːmɪk/","cefr":"B1","topic":"arts","senses":[{"pos":"adj.","en":"funny or connected with comedy","vi":"hài hước; liên quan đến hài kịch"},{"pos":"n.","en":"a publication telling stories through sequences of pictures","vi":"truyện tranh (ấn phẩm kể chuyện qua chuỗi tranh vẽ)"},{"pos":"n.","en":"a performer who entertains people by making them laugh","vi":"diễn viên hài; nghệ sĩ hài"}],"examples":[{"en":"His comic dance had everyone laughing at the party.","vi":"Điệu nhảy hài hước của anh ấy làm mọi người cười vang trong buổi tiệc.","audioKind":"ex"},{"en":"Comic characters can make educational programmes more engaging and help children remember important information.","vi":"Các nhân vật hoạt hình/truyện tranh có thể làm cho các chương trình giáo dục trở nên hấp dẫn hơn và giúp trẻ em ghi nhớ thông tin quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"comic timing","vi":"nhịp điệu hài hước"},{"en":"comic strip","vi":"dải truyện tranh"},{"en":"comic book","vi":"sách truyện tranh"},{"en":"comic effect","vi":"hiệu ứng gây cười"}],"wordFamily":["comical (adj.)","comically (adv.)","comedy (n.)"],"synonyms":["funny","humorous"],"antonyms":["serious"],"tipVi":"Comic có thể chỉ các yếu tố hài kịch; trong khi comical nhấn mạnh tính chất buồn cười, lố bịch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_statue', 'en-b1-23', 'statue', '/ˈstætʃuː/', 'B1', 'tượng; bức tượng', 'n.', NULL, NULL, 'Statue là bức tượng, trong khi status là địa vị, cần chú ý phân biệt chính tả.', 'A bronze statue of a horse stands beside the fountain.', NULL, 'Một bức tượng đồng hình con ngựa đang đứng cạnh đài phun nước.', '{"wordId":"statue","ukIpa":"/ˈstætʃuː/","usIpa":"/ˈstætʃuː/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"A sculpture representing a person or animal.","vi":"tượng; bức tượng"}],"examples":[{"en":"A bronze statue of a horse stands beside the fountain.","vi":"Một bức tượng đồng hình con ngựa đang đứng cạnh đài phun nước.","audioKind":"ex"},{"en":"Public statues can preserve local history, but communities should discuss which figures deserve such recognition.","vi":"Các bức tượng công cộng có thể lưu giữ lịch sử địa phương, nhưng cộng đồng nên thảo luận xem những nhân vật nào xứng đáng được tôn vinh như vậy.","audioKind":"ex2"}],"collocations":[{"en":"a bronze statue","vi":"tượng đồng"},{"en":"a marble statue","vi":"tượng đá cẩm thạch"},{"en":"erect a statue","vi":"dựng tượng"},{"en":"unveil a statue","vi":"khánh thành tượng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Statue là bức tượng, trong khi status là địa vị, cần chú ý phân biệt chính tả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_poetry', 'en-b1-23', 'poetry', '/ˈpoʊətri/', 'B1', 'thơ ca; vẻ đẹp nên thơ; chất thơ', 'n.', 'poem (n.), poet (n.), poetic (adj.), poetically (adv.)', 'Đồng nghĩa: verse · Trái nghĩa: prose', 'Poetry là danh từ không đếm được; một bài thơ dùng a poem, tuyệt đối không dùng a poetry.', 'She reads poetry aloud while her tea cools.', NULL, 'Cô ấy vừa đọc thơ thành tiếng vừa đợi trà nguội.', '{"wordId":"poetry","ukIpa":"/ˈpəʊətri/","usIpa":"/ˈpoʊətri/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"Literature using carefully arranged language, rhythm, and imagery.","vi":"thơ ca"},{"pos":"n.","en":"Beauty or emotional power resembling that of poems.","vi":"vẻ đẹp nên thơ; chất thơ"}],"examples":[{"en":"She reads poetry aloud while her tea cools.","vi":"Cô ấy vừa đọc thơ thành tiếng vừa đợi trà nguội.","audioKind":"ex"},{"en":"Studying poetry encourages students to explore complex emotions and appreciate the expressive possibilities of language.","vi":"Việc nghiên cứu thơ ca khuyến khích học sinh khám phá những cảm xúc phức tạp và trân trọng khả năng biểu đạt phong phú của ngôn ngữ.","audioKind":"ex2"}],"collocations":[{"en":"write poetry","vi":"làm thơ"},{"en":"poetry collection","vi":"tuyển tập thơ"},{"en":"poetry reading","vi":"buổi ngâm thơ"},{"en":"modern poetry","vi":"thơ ca hiện đại"}],"wordFamily":["poem (n.)","poet (n.)","poetic (adj.)","poetically (adv.)"],"synonyms":["verse"],"antonyms":["prose"],"tipVi":"Poetry là danh từ không đếm được; một bài thơ dùng a poem, tuyệt đối không dùng a poetry.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_monster', 'en-b1-23', 'monster', '/ˈmɑːnstər/', 'B1', 'quái vật; quái thú; kẻ tàn nhẫn; người độc ác; khổng lồ; to lớn', 'n.', 'monstrous (adj.), monstrously (adv.)', NULL, 'Cách dùng tính từ mang sắc thái khẩu ngữ, thường đặt trước danh từ để chỉ kích thước cực lớn.', 'The friendly monster in the cartoon has purple feet.', NULL, 'Con quái vật thân thiện trong hoạt hình có đôi chân màu tím.', '{"wordId":"monster","ukIpa":"/ˈmɒnstə/","usIpa":"/ˈmɑːnstər/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"an imaginary creature that is large, strange, or frightening","vi":"quái vật; quái thú"},{"pos":"n.","en":"a person who behaves in an extremely cruel way","vi":"kẻ tàn nhẫn; người độc ác"},{"pos":"adj.","en":"extremely large in size or amount","vi":"khổng lồ; to lớn"}],"examples":[{"en":"The friendly monster in the cartoon has purple feet.","vi":"Con quái vật thân thiện trong hoạt hình có đôi chân màu tím.","audioKind":"ex"},{"en":"Stories about monsters can help children explore their fears within a safe and imaginative setting.","vi":"Những câu chuyện về quái vật có thể giúp trẻ em khám phá nỗi sợ hãi trong một không gian an toàn và giàu trí tưởng tượng.","audioKind":"ex2"}],"collocations":[{"en":"sea monster","vi":"quái vật biển"},{"en":"a monster truck","vi":"xe tải bánh xích khổng lồ"},{"en":"a fictional monster","vi":"quái vật giả tưởng"}],"wordFamily":["monstrous (adj.)","monstrously (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách dùng tính từ mang sắc thái khẩu ngữ, thường đặt trước danh từ để chỉ kích thước cực lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_poet', 'en-b1-23', 'poet', '/ˈpoʊət/', 'B1', 'nhà thơ; thi sĩ', 'n.', 'poem (n.), poetry (n.), poetic (adj.), poetically (adv.)', NULL, 'poet chỉ nhà thơ, poem chỉ một bài thơ, poetry dùng để chỉ chung thơ ca.', 'The poet read her latest work beside the fireplace.', NULL, 'Nữ nhà thơ đã đọc tác phẩm mới nhất của mình cạnh lò sưởi.', '{"wordId":"poet","ukIpa":"/ˈpəʊɪt/","usIpa":"/ˈpoʊət/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"a person who writes poems","vi":"nhà thơ; thi sĩ"}],"examples":[{"en":"The poet read her latest work beside the fireplace.","vi":"Nữ nhà thơ đã đọc tác phẩm mới nhất của mình cạnh lò sưởi.","audioKind":"ex"},{"en":"A poet can challenge social attitudes by expressing familiar experiences in unexpected and emotionally powerful ways.","vi":"Một nhà thơ có thể thách thức các quan niệm xã hội bằng cách diễn đạt những trải nghiệm quen thuộc theo những cách thức bất ngờ và giàu cảm xúc.","audioKind":"ex2"}],"collocations":[{"en":"a celebrated poet","vi":"một nhà thơ nổi tiếng"},{"en":"a contemporary poet","vi":"một nhà thơ đương đại"},{"en":"a poet''s work","vi":"tác phẩm của nhà thơ"}],"wordFamily":["poem (n.)","poetry (n.)","poetic (adj.)","poetically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"poet chỉ nhà thơ, poem chỉ một bài thơ, poetry dùng để chỉ chung thơ ca.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drum', 'en-b1-23', 'drum', '/drʌm/', 'B1', 'cái trống; thùng phuy; thùng lớn hình trụ; đánh trống; gõ nhịp liên tục', 'n.', 'drummer (n.), drumming (n.)', NULL, 'Play the drums thường chỉ việc đánh trống; drum cũng có thể chỉ thùng phuy lớn.', 'The little boy beat the drum with both hands.', NULL, 'Cậu bé đánh chiếc trống bằng cả hai tay.', '{"wordId":"drum","ukIpa":"/drʌm/","usIpa":"/drʌm/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"a musical instrument played by hitting its stretched surface","vi":"cái trống"},{"pos":"n.","en":"a large cylindrical container for storing liquids or other materials","vi":"thùng phuy; thùng lớn hình trụ"},{"pos":"v.","en":"to play a drum or tap something repeatedly","vi":"đánh trống; gõ nhịp liên tục"}],"examples":[{"en":"The little boy beat the drum with both hands.","vi":"Cậu bé đánh chiếc trống bằng cả hai tay.","audioKind":"ex"},{"en":"Learning to play the drum can help children develop coordination and participate in group performances.","vi":"Học đánh trống có thể giúp trẻ phát triển khả năng phối hợp và tham gia vào các buổi biểu diễn nhóm.","audioKind":"ex2"}],"collocations":[{"en":"play the drums","vi":"chơi trống"},{"en":"beat a drum","vi":"đánh trống"},{"en":"an oil drum","vi":"thùng dầu"}],"wordFamily":["drummer (n.)","drumming (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Play the drums thường chỉ việc đánh trống; drum cũng có thể chỉ thùng phuy lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_magician', 'en-b1-23', 'magician', '/məˈdʒɪʃn/', 'B1', 'nhà ảo thuật; pháp sư; người có phép thuật', 'n.', 'magic (n.), magical (adj.), magically (adv.)', 'Đồng nghĩa: conjurer, illusionist', 'Trong thực tế chỉ người biểu diễn ảo thuật; trong truyện kể cũng có thể chỉ pháp sư.', 'The magician pulled a silk scarf from an empty cup.', NULL, 'Nhà ảo thuật lấy ra một chiếc khăn lụa từ một chiếc cốc rỗng.', '{"wordId":"magician","ukIpa":"/məˈdʒɪʃn/","usIpa":"/məˈdʒɪʃn/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"A performer who entertains people by doing seemingly impossible tricks.","vi":"nhà ảo thuật"},{"pos":"n.","en":"A person believed or imagined to have magical powers.","vi":"pháp sư; người có phép thuật"}],"examples":[{"en":"The magician pulled a silk scarf from an empty cup.","vi":"Nhà ảo thuật lấy ra một chiếc khăn lụa từ một chiếc cốc rỗng.","audioKind":"ex"},{"en":"A skilled magician can demonstrate how easily human attention is directed away from important visual details.","vi":"Một nhà ảo thuật tài ba có thể minh họa việc sự chú ý của con người dễ dàng bị chuyển hướng khỏi các chi tiết thị giác quan trọng như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"performing magician","vi":"nhà ảo thuật biểu diễn"},{"en":"stage magician","vi":"ảo thuật gia sân khấu"},{"en":"skilled magician","vi":"nhà ảo thuật tài ba"}],"wordFamily":["magic (n.)","magical (adj.)","magically (adv.)"],"synonyms":["conjurer","illusionist"],"antonyms":[],"tipVi":"Trong thực tế chỉ người biểu diễn ảo thuật; trong truyện kể cũng có thể chỉ pháp sư.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_silk', 'en-b1-23', 'silk', '/sɪlk/', 'B1', 'tơ tằm; lụa; vải lụa', 'n.', 'silky (adj.), silkworm (n.)', NULL, 'silk thường không đếm được; silky dùng để chỉ độ mềm mượt như lụa, không nhất thiết phải làm từ lụa.', 'She wrapped a soft silk scarf around her neck.', NULL, 'Cô ấy quấn một chiếc khăn lụa mềm mại quanh cổ.', '{"wordId":"silk","ukIpa":"/sɪlk/","usIpa":"/sɪlk/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"Fine thread produced by silkworms, or fabric made from it.","vi":"tơ tằm; lụa; vải lụa"}],"examples":[{"en":"She wrapped a soft silk scarf around her neck.","vi":"Cô ấy quấn một chiếc khăn lụa mềm mại quanh cổ.","audioKind":"ex"},{"en":"Traditional silk production provides employment in rural communities while preserving skills passed down through generations.","vi":"Hoạt động sản xuất lụa truyền thống tạo ra việc làm cho các cộng đồng nông thôn đồng thời giữ gìn những kỹ năng được truyền qua nhiều thế hệ.","audioKind":"ex2"}],"collocations":[{"en":"silk scarf","vi":"khăn quàng lụa"},{"en":"pure silk","vi":"lụa tơ tằm nguyên chất"},{"en":"silk production","vi":"sản xuất lụa"}],"wordFamily":["silky (adj.)","silkworm (n.)"],"synonyms":[],"antonyms":[],"tipVi":"silk thường không đếm được; silky dùng để chỉ độ mềm mượt như lụa, không nhất thiết phải làm từ lụa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_portrait', 'en-b1-23', 'portrait', '/ˈpɔːrtrət/', 'B1', 'chân dung; ảnh chụp chân dung; sự miêu tả chi tiết', 'n.', 'portraiture (n.)', NULL, 'portrait tập trung vào con người; landscape thường chỉ phong cảnh hoặc tranh/ảnh phong cảnh.', 'My grandmother''s portrait hangs above the living room fireplace.', NULL, 'Bức chân dung của bà tôi được treo phía trên lò sưởi trong phòng khách.', '{"wordId":"portrait","ukIpa":"/ˈpɔːtreɪt/","usIpa":"/ˈpɔːrtrət/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"a painting, drawing, or photograph of a person","vi":"chân dung; ảnh chụp chân dung"},{"pos":"n.","en":"a detailed description of a person, place, or situation","vi":"sự miêu tả chi tiết"}],"examples":[{"en":"My grandmother''s portrait hangs above the living room fireplace.","vi":"Bức chân dung của bà tôi được treo phía trên lò sưởi trong phòng khách.","audioKind":"ex"},{"en":"The documentary offers a compelling portrait of rural life as younger generations move to urban areas.","vi":"Bộ phim tài liệu mang đến bức tranh sinh động về cuộc sống nông thôn khi thế hệ trẻ di chuyển đến các khu vực đô thị.","audioKind":"ex2"}],"collocations":[{"en":"paint a portrait","vi":"vẽ chân dung"},{"en":"a family portrait","vi":"ảnh gia đình"},{"en":"a vivid portrait","vi":"mô tả sinh động"},{"en":"portrait photography","vi":"nhiếp ảnh chân dung"}],"wordFamily":["portraiture (n.)"],"synonyms":[],"antonyms":[],"tipVi":"portrait tập trung vào con người; landscape thường chỉ phong cảnh hoặc tranh/ảnh phong cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_instrument', 'en-b1-23', 'instrument', '/ˈɪnstrəmənt/', 'B1', 'nhạc cụ; dụng cụ; thiết bị khoa học/y tế; phương tiện; công cụ', 'n.', 'instrumental (adj.), instrumentalist (n.)', NULL, 'Cả nhạc cụ và thiết bị chính xác đều dùng instrument; công cụ thông thường thường dùng tool.', 'My sister plays a different instrument at each rehearsal.', NULL, 'Chị tôi chơi một nhạc cụ khác nhau ở mỗi buổi tập.', '{"wordId":"instrument","ukIpa":"/ˈɪnstrəmənt/","usIpa":"/ˈɪnstrəmənt/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"an object played to produce musical sounds","vi":"nhạc cụ"},{"pos":"n.","en":"a tool or device for precise scientific or medical work","vi":"dụng cụ; thiết bị khoa học/y tế"},{"pos":"n.","en":"something used to achieve a particular purpose","vi":"phương tiện; công cụ"}],"examples":[{"en":"My sister plays a different instrument at each rehearsal.","vi":"Chị tôi chơi một nhạc cụ khác nhau ở mỗi buổi tập.","audioKind":"ex"},{"en":"Learning a musical instrument can strengthen concentration and encourage cooperation among children from different backgrounds.","vi":"Học chơi nhạc cụ có thể củng cố khả năng tập trung và khuyến khích sự hợp tác giữa những đứa trẻ có hoàn cảnh khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"musical instrument","vi":"nhạc cụ"},{"en":"scientific instrument","vi":"dụng cụ khoa học"},{"en":"surgical instrument","vi":"dụng cụ phẫu thuật"},{"en":"instrument of change","vi":"công cụ thay đổi"}],"wordFamily":["instrumental (adj.)","instrumentalist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cả nhạc cụ và thiết bị chính xác đều dùng instrument; công cụ thông thường thường dùng tool.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tale', 'en-b1-23', 'tale', '/teɪl/', 'B1', 'truyện; chuyện cổ tích; chuyện truyền thuyết; chuyện kể; lời thuật lại', 'n.', NULL, 'Đồng nghĩa: story, narrative', 'tale có nghĩa là câu chuyện; tail có nghĩa là cái đuôi, hai từ này phát âm giống nhau.', 'Grandfather told us a tale about a clever fox.', NULL, 'Ông đã kể cho chúng tôi nghe một câu chuyện về một con cáo khôn ngoan.', '{"wordId":"tale","ukIpa":"/teɪl/","usIpa":"/teɪl/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"a story, especially one involving imaginary or exciting events","vi":"truyện; chuyện cổ tích; chuyện truyền thuyết"},{"pos":"n.","en":"an account of something that happened to someone","vi":"chuyện kể; lời thuật lại"}],"examples":[{"en":"Grandfather told us a tale about a clever fox.","vi":"Ông đã kể cho chúng tôi nghe một câu chuyện về một con cáo khôn ngoan.","audioKind":"ex"},{"en":"Traditional tales can preserve cultural values while helping children explore complex emotions through memorable characters.","vi":"Những câu chuyện truyền thống có thể lưu giữ các giá trị văn hóa đồng thời giúp trẻ em khám phá những cảm xúc phức tạp thông qua các nhân vật đáng nhớ.","audioKind":"ex2"}],"collocations":[{"en":"a fairy tale","vi":"truyện cổ tích"},{"en":"a folk tale","vi":"truyện dân gian"},{"en":"a cautionary tale","vi":"câu chuyện mang tính cảnh báo"},{"en":"tell a tale","vi":"kể chuyện"}],"wordFamily":[],"synonyms":["story","narrative"],"antonyms":[],"tipVi":"tale có nghĩa là câu chuyện; tail có nghĩa là cái đuôi, hai từ này phát âm giống nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_performer', 'en-b1-23', 'performer', '/pɚˈfɔːrmɚ/', 'B1', 'người biểu diễn; nghệ sĩ biểu diễn; người (hoặc vật) thể hiện xuất sắc', 'n.', 'perform (v.), performance (n.), performing (adj.)', 'Đồng nghĩa: entertainer', 'Không chỉ chỉ diễn viên; top performer còn có thể chỉ nhân viên có hiệu suất làm việc xuất sắc.', 'A street performer juggled oranges beside the crowded market.', NULL, 'Một nghệ sĩ đường phố tung hứng những quả cam bên khu chợ đông đúc.', '{"wordId":"performer","ukIpa":"/pəˈfɔːmə/","usIpa":"/pɚˈfɔːrmɚ/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"someone who entertains an audience by acting, singing, or playing","vi":"người biểu diễn; nghệ sĩ biểu diễn"},{"pos":"n.","en":"a person or thing achieving a particular level of success","vi":"người (hoặc vật) thể hiện xuất sắc"}],"examples":[{"en":"A street performer juggled oranges beside the crowded market.","vi":"Một nghệ sĩ đường phố tung hứng những quả cam bên khu chợ đông đúc.","audioKind":"ex"},{"en":"Public funding can help young performers develop their skills and bring live entertainment to underserved communities.","vi":"Sự hỗ trợ từ nguồn vốn công có thể giúp các tài năng trẻ phát triển kỹ năng và mang các chương trình giải trí trực tiếp đến các cộng đồng còn thiếu thốn dịch vụ văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"a street performer","vi":"nghệ sĩ đường phố"},{"en":"a live performer","vi":"người biểu diễn trực tiếp"},{"en":"a top performer","vi":"người có thành tích xuất sắc"}],"wordFamily":["perform (v.)","performance (n.)","performing (adj.)"],"synonyms":["entertainer"],"antonyms":[],"tipVi":"Không chỉ chỉ diễn viên; top performer còn có thể chỉ nhân viên có hiệu suất làm việc xuất sắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comedian', 'en-b1-23', 'comedian', '/kəˈmiːdiən/', 'B1', 'diễn viên hài, nghệ sĩ hài', 'n.', 'comedy (n.), comedic (adj.)', 'Đồng nghĩa: comic', 'Comedian chỉ người, trong khi comedy chỉ thể loại hài kịch hoặc tác phẩm hài.', 'The comedian made everyone laugh with stories about his cat.', NULL, 'Nam diễn viên hài đã làm cho mọi người cười ngất với những câu chuyện về con mèo của anh ấy.', '{"wordId":"comedian","ukIpa":"/kəˈmiːdiən/","usIpa":"/kəˈmiːdiən/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"a performer who entertains people by making them laugh","vi":"diễn viên hài, nghệ sĩ hài"}],"examples":[{"en":"The comedian made everyone laugh with stories about his cat.","vi":"Nam diễn viên hài đã làm cho mọi người cười ngất với những câu chuyện về con mèo của anh ấy.","audioKind":"ex"},{"en":"A skilled comedian can encourage audiences to question social habits while providing enjoyable entertainment.","vi":"Một diễn viên hài tài năng có thể khơi gợi cho khán giả suy ngẫm về các thói quen xã hội trong khi vẫn mang lại những phút giây giải trí thú vị.","audioKind":"ex2"}],"collocations":[{"en":"stand-up comedian","vi":"diễn viên độc thoại gây cười"},{"en":"professional comedian","vi":"diễn viên hài chuyên nghiệp"},{"en":"talented comedian","vi":"diễn viên hài tài năng"}],"wordFamily":["comedy (n.)","comedic (adj.)"],"synonyms":["comic"],"antonyms":[],"tipVi":"Comedian chỉ người, trong khi comedy chỉ thể loại hài kịch hoặc tác phẩm hài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sculpture', 'en-b1-23', 'sculpture', '/ˈskʌlptʃər/', 'B1', 'tác phẩm điêu khắc; nghệ thuật điêu khắc', 'n.', 'sculpt (v.), sculptor (n.), sculptural (adj.)', NULL, 'Chỉ bộ môn nghệ thuật thì không đếm được; chỉ một tác phẩm cụ thể thì đếm được.', 'A bronze sculpture of a horse stands outside the library.', NULL, 'Một bức tượng đồng hình con ngựa được đặt ở bên ngoài thư viện.', '{"wordId":"sculpture","ukIpa":"/ˈskʌlptʃə/","usIpa":"/ˈskʌlptʃər/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"an artwork made by carving, shaping, or assembling materials","vi":"tác phẩm điêu khắc"},{"pos":"n.","en":"the art of creating solid forms from materials","vi":"nghệ thuật điêu khắc"}],"examples":[{"en":"A bronze sculpture of a horse stands outside the library.","vi":"Một bức tượng đồng hình con ngựa được đặt ở bên ngoài thư viện.","audioKind":"ex"},{"en":"Public sculpture can strengthen a city''s cultural identity while making art accessible to people outside traditional galleries.","vi":"Nghệ thuật điêu khắc công cộng có thể củng cố bản sắc văn hóa của một thành phố đồng thời giúp mọi người tiếp cận nghệ thuật bên ngoài các phòng trưng bày truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"a bronze sculpture","vi":"tượng đồng điêu khắc"},{"en":"public sculpture","vi":"điêu khắc công cộng"},{"en":"a sculpture garden","vi":"vườn tượng điêu khắc"},{"en":"abstract sculpture","vi":"nghệ thuật điêu khắc trừu tượng"}],"wordFamily":["sculpt (v.)","sculptor (n.)","sculptural (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ bộ môn nghệ thuật thì không đếm được; chỉ một tác phẩm cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_classical', 'en-b1-23', 'classical', '/ˈklæsɪkəl/', 'B1', 'thuộc về âm nhạc cổ điển; thuộc về văn hóa cổ đại Hy Lạp hoặc La Mã; cổ điển; mang tính truyền thống', 'adj.', 'classically (adv.), classicism (n.), classicist (n.)', NULL, 'Âm nhạc cổ điển dùng classical; tác phẩm kinh điển thường dùng classic.', 'My sister listens to classical music while cooking.', NULL, 'Chị gái tôi thường nghe nhạc cổ điển trong lúc nấu ăn.', '{"wordId":"classical","ukIpa":"/ˈklæsɪkəl/","usIpa":"/ˈklæsɪkəl/","cefr":"B1","topic":"arts","senses":[{"pos":"adj.","en":"relating to formal Western music, such as symphonies and operas","vi":"thuộc về âm nhạc cổ điển"},{"pos":"adj.","en":"relating to ancient Greece or Rome and their culture","vi":"thuộc về văn hóa cổ đại Hy Lạp hoặc La Mã; cổ điển"},{"pos":"adj.","en":"based on established theories rather than newer approaches","vi":"mang tính truyền thống"}],"examples":[{"en":"My sister listens to classical music while cooking.","vi":"Chị gái tôi thường nghe nhạc cổ điển trong lúc nấu ăn.","audioKind":"ex"},{"en":"Studying classical architecture helps students understand how ancient design principles continue to influence modern public buildings.","vi":"Việc nghiên cứu kiến trúc cổ điển giúp học sinh hiểu được các nguyên tắc thiết kế thời cổ đại tiếp tục ảnh hưởng như thế nào đến các công trình công cộng hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"classical music","vi":"âm nhạc cổ điển"},{"en":"classical architecture","vi":"kiến trúc cổ điển"},{"en":"classical civilisation","vi":"nền văn minh cổ đại"},{"en":"classical mechanics","vi":"cơ học cổ điển"}],"wordFamily":["classically (adv.)","classicism (n.)","classicist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Âm nhạc cổ điển dùng classical; tác phẩm kinh điển thường dùng classic.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_entertain', 'en-b1-23', 'entertain', '/ˌentərˈteɪn/', 'B1', 'làm cho vui; giải trí; tiếp đãi; khoản đãi; cân nhắc; ấp ủ', 'v.', 'entertainment (n.), entertainer (n.), entertaining (adj.), entertained (adj.)', 'Đồng nghĩa: amuse', 'entertain an idea chỉ việc cân nhắc một ý tưởng, không có nghĩa là đã chấp nhận nó.', 'My brother entertained the children with funny animal noises.', NULL, 'Anh trai tôi đã làm cho lũ trẻ vui thích bằng những tiếng kêu mô phỏng động vật hài hước.', '{"wordId":"entertain","ukIpa":"/ˌentəˈteɪn/","usIpa":"/ˌentərˈteɪn/","cefr":"B1","topic":"arts","senses":[{"pos":"v.","en":"to keep someone interested or amused","vi":"làm cho vui; giải trí"},{"pos":"v.","en":"to welcome guests and provide food, drink, or activities","vi":"tiếp đãi; khoản đãi"},{"pos":"v.","en":"to consider an idea or hold a thought or feeling","vi":"cân nhắc; ấp ủ"}],"examples":[{"en":"My brother entertained the children with funny animal noises.","vi":"Anh trai tôi đã làm cho lũ trẻ vui thích bằng những tiếng kêu mô phỏng động vật hài hước.","audioKind":"ex"},{"en":"Public museums should educate visitors as well as entertain them through engaging displays and interactive activities.","vi":"Các bảo tàng công cộng nên giáo dục khách tham quan đồng thời mang lại cho họ niềm vui thông qua các khu trưng bày hấp dẫn và hoạt động tương tác.","audioKind":"ex2"}],"collocations":[{"en":"entertain an audience","vi":"mang lại giải trí cho khán giả"},{"en":"entertain guests","vi":"tiếp đãi khách"},{"en":"entertain the idea of","vi":"cân nhắc ý tưởng về"}],"wordFamily":["entertainment (n.)","entertainer (n.)","entertaining (adj.)","entertained (adj.)"],"synonyms":["amuse"],"antonyms":[],"tipVi":"entertain an idea chỉ việc cân nhắc một ý tưởng, không có nghĩa là đã chấp nhận nó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trumpet', 'en-b1-23', 'trumpet', '/ˈtrʌmpɪt/', 'B1', 'kèn trôm-pét; kèn đồng; rao giảng; lớn tiếng khoe khoang; ca ngợi rùm beng; kêu rống lên (như tiếng voi)', 'n.', 'trumpeter (n.)', NULL, 'Nghĩa thông dụng là nhạc cụ "kèn trôm-pét"; ở nghĩa động từ, từ này có sắc thái đại ngôn, khoe khoang.', 'The musician lifted her trumpet and played a cheerful tune.', NULL, 'Nữ nghệ sĩ nâng chiếc kèn trôm-pét lên và thổi một giai điệu vui tươi.', '{"wordId":"trumpet","ukIpa":"/ˈtrʌmpɪt/","usIpa":"/ˈtrʌmpɪt/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"A brass musical instrument with three valves and a bright sound.","vi":"kèn trôm-pét; kèn đồng"},{"pos":"v.","en":"To announce or praise something loudly and publicly.","vi":"rao giảng; lớn tiếng khoe khoang; ca ngợi rùm beng"},{"pos":"v.","en":"To make a loud sound like an elephant''s call.","vi":"kêu rống lên (như tiếng voi)"}],"examples":[{"en":"The musician lifted her trumpet and played a cheerful tune.","vi":"Nữ nghệ sĩ nâng chiếc kèn trôm-pét lên và thổi một giai điệu vui tươi.","audioKind":"ex"},{"en":"Learning the trumpet in a school orchestra can improve students'' concentration and ability to cooperate with others.","vi":"Việc học kèn trôm-pét trong dàn nhạc trường học có thể giúp học sinh nâng cao sự tập trung và khả năng phối hợp với người khác.","audioKind":"ex2"}],"collocations":[{"en":"play the trumpet","vi":"chơi kèn trôm-pét"},{"en":"trumpet player","vi":"người thổi kèn"},{"en":"trumpet achievements","vi":"khoa trương thành tích"}],"wordFamily":["trumpeter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa thông dụng là nhạc cụ \"kèn trôm-pét\"; ở nghĩa động từ, từ này có sắc thái đại ngôn, khoe khoang.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unique', 'en-b1-23', 'unique', '/juˈniːk/', 'B1', 'độc nhất; độc đáo; đặc thù; riêng biệt', 'adj.', 'uniquely (adv.), uniqueness (n.)', 'Đồng nghĩa: distinctive · Trái nghĩa: ordinary, common', 'unique to dùng để chỉ đặc trưng của một nơi nào đó; khi mang nghĩa tuyệt đối là duy nhất thì không dùng very để bổ nghĩa.', 'Each handmade bowl has a unique pattern inside.', NULL, 'Mỗi chiếc bát thủ công đều có một họa tiết độc đáo ở bên trong.', '{"wordId":"unique","ukIpa":"/juˈniːk/","usIpa":"/juˈniːk/","cefr":"B1","topic":"arts","senses":[{"pos":"adj.","en":"Unlike anything else, or the only one of its kind","vi":"độc nhất; độc đáo"},{"pos":"adj.","en":"Found only in a particular person, place, or thing","vi":"đặc thù; riêng biệt"}],"examples":[{"en":"Each handmade bowl has a unique pattern inside.","vi":"Mỗi chiếc bát thủ công đều có một họa tiết độc đáo ở bên trong.","audioKind":"ex"},{"en":"Protecting local crafts helps communities preserve their unique cultural identity in an increasingly globalised world.","vi":"Việc bảo tồn các nghề thủ công địa phương giúp cộng đồng duy trì bản sắc văn hóa độc đáo của họ trong một thế giới ngày càng toàn cầu hóa.","audioKind":"ex2"}],"collocations":[{"en":"unique opportunity","vi":"cơ hội hiếm có"},{"en":"unique features","vi":"đặc điểm riêng biệt"},{"en":"unique to the region","vi":"đặc trưng của vùng"}],"wordFamily":["uniquely (adv.)","uniqueness (n.)"],"synonyms":["distinctive"],"antonyms":["ordinary","common"],"tipVi":"unique to dùng để chỉ đặc trưng của một nơi nào đó; khi mang nghĩa tuyệt đối là duy nhất thì không dùng very để bổ nghĩa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_display', 'en-b1-23', 'display', '/dɪˈspleɪ/', 'B1', 'bày ra; trưng bày; hiển thị; sự trưng bày; sự triển lãm; màn hình hiển thị', 'v.', NULL, 'Đồng nghĩa: show, exhibit · Trái nghĩa: hide', 'on display ý nghĩa là "đang trưng bày", ở giữa không thêm mạo từ.', 'The bakery displays fresh cakes beside the front window.', NULL, 'Tiệm bánh trưng bày những chiếc bánh tươi ngon ngay cạnh cửa sổ phía trước.', '{"wordId":"display","ukIpa":"/dɪˈspleɪ/","usIpa":"/dɪˈspleɪ/","cefr":"B1","topic":"arts","senses":[{"pos":"v.","en":"Put something where people can see it","vi":"bày ra; trưng bày; hiển thị"},{"pos":"n.","en":"An arrangement of things for people to look at","vi":"sự trưng bày; sự triển lãm"},{"pos":"n.","en":"A screen that shows information or images","vi":"màn hình hiển thị"}],"examples":[{"en":"The bakery displays fresh cakes beside the front window.","vi":"Tiệm bánh trưng bày những chiếc bánh tươi ngon ngay cạnh cửa sổ phía trước.","audioKind":"ex"},{"en":"Museums increasingly display everyday objects to illustrate how ordinary people lived in the past.","vi":"Các bảo tàng ngày càng trưng bày nhiều vật dụng hàng ngày để minh họa cách sống của người bình thường trong quá khứ.","audioKind":"ex2"}],"collocations":[{"en":"on display","vi":"đang trưng bày"},{"en":"display information","vi":"hiển thị thông tin"},{"en":"a colourful display","vi":"một màn trưng bày rực rỡ sắc màu"},{"en":"digital display","vi":"màn hình kỹ thuật số"}],"wordFamily":[],"synonyms":["show","exhibit"],"antonyms":["hide"],"tipVi":"on display ý nghĩa là \"đang trưng bày\", ở giữa không thêm mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clown', 'en-b1-23', 'clown', '/klaʊn/', 'B1', 'chú hề; kẻ hay đùa cợt; người hay pha trò; làm trò hề; đùa giỡn', 'n.', 'clowning (n.), clownish (adj.)', NULL, 'clown around nghĩa là làm trò đùa cợt; gọi ai là clown đôi khi có hàm ý chê bai.', 'The clown made a tiny dog from a balloon.', NULL, 'Chú hề đã làm một chú chó nhỏ từ quả bóng bay.', '{"wordId":"clown","ukIpa":"/klaʊn/","usIpa":"/klaʊn/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"a performer who wears funny clothes and makes people laugh","vi":"chú hề"},{"pos":"n.","en":"someone who behaves foolishly to make others laugh","vi":"kẻ hay đùa cợt; người hay pha trò"},{"pos":"v.","en":"to behave playfully or foolishly to amuse others","vi":"làm trò hề; đùa giỡn"}],"examples":[{"en":"The clown made a tiny dog from a balloon.","vi":"Chú hề đã làm một chú chó nhỏ từ quả bóng bay.","audioKind":"ex"},{"en":"A trained clown can help young patients feel more comfortable during their stay in hospital.","vi":"Một chú hề được huấn luyện bài bản có thể giúp các bệnh nhân nhí cảm thấy thoải mái hơn trong thời gian nằm viện.","audioKind":"ex2"}],"collocations":[{"en":"circus clown","vi":"chú hề rạp xiếc"},{"en":"class clown","vi":"trò cười của lớp; cây hài"},{"en":"clown around","vi":"làm trò đùa cợt"}],"wordFamily":["clowning (n.)","clownish (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"clown around nghĩa là làm trò đùa cợt; gọi ai là clown đôi khi có hàm ý chê bai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_poem', 'en-b1-23', 'poem', '/ˈpoʊəm/', 'B1', 'bài thơ; tác phẩm văn học sử dụng ngôn từ được gọt giũa cẩn thận, thường được chia thành các dòng', 'n.', 'poet (n.), poetry (n.), poetic (adj.), poetically (adv.)', NULL, 'poem là danh từ đếm được, chỉ một bài thơ cụ thể; poetry là danh từ không đếm được, dùng để chỉ chung thơ ca.', 'Leila read a short poem aloud after dinner.', NULL, 'Leila đọc to một bài thơ ngắn sau bữa tối.', '{"wordId":"poem","ukIpa":"/ˈpəʊɪm/","usIpa":"/ˈpoʊəm/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"A literary work using carefully arranged language, often in lines.","vi":"bài thơ; tác phẩm văn học sử dụng ngôn từ được gọt giũa cẩn thận, thường được chia thành các dòng"}],"examples":[{"en":"Leila read a short poem aloud after dinner.","vi":"Leila đọc to một bài thơ ngắn sau bữa tối.","audioKind":"ex"},{"en":"Reading a poem from another culture can help students explore unfamiliar perspectives and develop sensitivity to language.","vi":"Việc đọc một bài thơ từ nền văn hóa khác có thể giúp học sinh khám phá những góc nhìn mới lạ và phát triển sự nhạy cảm với ngôn ngữ.","audioKind":"ex2"}],"collocations":[{"en":"write a poem","vi":"làm thơ"},{"en":"recite a poem","vi":"ngâm thơ"},{"en":"a collection of poems","vi":"tuyển tập thơ"}],"wordFamily":["poet (n.)","poetry (n.)","poetic (adj.)","poetically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"poem là danh từ đếm được, chỉ một bài thơ cụ thể; poetry là danh từ không đếm được, dùng để chỉ chung thơ ca.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pianist', 'en-b1-23', 'pianist', '/ˈpiːənɪst/', 'B1', 'nghệ sĩ piano; người chơi đàn piano', 'n.', 'piano (n.)', NULL, 'pianist chỉ người biểu diễn; nhạc cụ piano gọi là piano.', 'The pianist smiled before playing her favourite song.', NULL, 'Nữ nghệ sĩ piano mỉm cười trước khi chơi bài hát yêu thích của cô ấy.', '{"wordId":"pianist","ukIpa":"/ˈpɪənɪst/","usIpa":"/ˈpiːənɪst/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"Someone who plays the piano, especially professionally.","vi":"nghệ sĩ piano; người chơi đàn piano"}],"examples":[{"en":"The pianist smiled before playing her favourite song.","vi":"Nữ nghệ sĩ piano mỉm cười trước khi chơi bài hát yêu thích của cô ấy.","audioKind":"ex"},{"en":"A professional pianist usually needs years of disciplined practice as well as opportunities to perform publicly.","vi":"Một nghệ sĩ piano chuyên nghiệp thường cần nhiều năm luyện tập kỷ luật cũng như các cơ hội biểu diễn trước công chúng.","audioKind":"ex2"}],"collocations":[{"en":"concert pianist","vi":"nghệ sĩ piano hòa nhạc"},{"en":"professional pianist","vi":"nghệ sĩ piano chuyên nghiệp"},{"en":"accompanying pianist","vi":"người đệm piano"}],"wordFamily":["piano (n.)"],"synonyms":[],"antonyms":[],"tipVi":"pianist chỉ người biểu diễn; nhạc cụ piano gọi là piano.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_opera', 'en-b1-23', 'opera', '/ˈɑːpərə/', 'B1', 'vở kịch hát, nhạc kịch opera', 'n.', 'operatic (adj.)', NULL, 'Khi chỉ nghệ thuật opera nói chung thì không đếm được; khi chỉ một tác phẩm cụ thể thì dùng an opera.', 'We watched an opera at the theatre last night.', NULL, 'Chúng tôi đã xem một buổi nhạc kịch opera tại nhà hát vào tối qua.', '{"wordId":"opera","ukIpa":"/ˈɒpərə/","usIpa":"/ˈɑːpərə/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"a musical drama in which performers sing most words","vi":"vở kịch hát, nhạc kịch opera"}],"examples":[{"en":"We watched an opera at the theatre last night.","vi":"Chúng tôi đã xem một buổi nhạc kịch opera tại nhà hát vào tối qua.","audioKind":"ex"},{"en":"Public funding for opera can preserve artistic traditions while making performances accessible to a wider audience.","vi":"Việc tài trợ công cho nghệ thuật opera có thể bảo tồn các truyền thống nghệ thuật đồng thời giúp công chúng tiếp cận các buổi biểu diễn rộng rãi hơn.","audioKind":"ex2"}],"collocations":[{"en":"an opera singer","vi":"ca sĩ nhạc kịch"},{"en":"an opera house","vi":"nhà hát opera"},{"en":"perform an opera","vi":"biểu diễn một vở opera"}],"wordFamily":["operatic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ nghệ thuật opera nói chung thì không đếm được; khi chỉ một tác phẩm cụ thể thì dùng an opera.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arts', 'en-b1-23', 'arts', '/ɑːrts/', 'B1', 'nghệ thuật; các hoạt động nghệ thuật; các môn khoa học xã hội và nhân văn; văn khoa', 'n.', 'art (n.), artist (n.), artistic (adj.), artistically (adv.)', NULL, 'the arts dùng để chỉ chung nghệ thuật; arts subjects dùng để chỉ các môn khoa học xã hội và nhân văn.', 'Our local arts centre offers pottery and dance classes.', NULL, 'Trung tâm nghệ thuật địa phương của chúng tôi có các lớp học làm gốm và khiêu vũ.', '{"wordId":"arts","ukIpa":"/ɑːts/","usIpa":"/ɑːrts/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"Creative activities such as painting, music, theatre, and dance.","vi":"nghệ thuật; các hoạt động nghệ thuật"},{"pos":"n.","en":"Subjects such as languages, literature, philosophy, and history.","vi":"các môn khoa học xã hội và nhân văn; văn khoa"}],"examples":[{"en":"Our local arts centre offers pottery and dance classes.","vi":"Trung tâm nghệ thuật địa phương của chúng tôi có các lớp học làm gốm và khiêu vũ.","audioKind":"ex"},{"en":"Studying arts subjects can develop critical thinking and deepen students'' understanding of different cultures.","vi":"Việc học các môn khoa học xã hội và nhân văn có thể phát triển tư duy phản biện và làm sâu sắc thêm sự hiểu biết của học sinh về các nền văn hóa khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"the performing arts","vi":"nghệ thuật biểu diễn"},{"en":"arts subjects","vi":"các môn khoa học xã hội và nhân văn"},{"en":"arts centre","vi":"trung tâm nghệ thuật"},{"en":"Bachelor of Arts","vi":"cử nhân văn khoa"}],"wordFamily":["art (n.)","artist (n.)","artistic (adj.)","artistically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"the arts dùng để chỉ chung nghệ thuật; arts subjects dùng để chỉ các môn khoa học xã hội và nhân văn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tune', 'en-b1-23', 'tune', '/tuːn/', 'B1', 'giai điệu; khúc nhạc; lên dây (đàn); chỉnh tần số; điều chỉnh thiết bị', 'n.', 'tuning (n.), tuner (n.), tuneful (adj.)', 'Đồng nghĩa: melody', 'in tune chỉ âm điều chính xác; out of tune chỉ lạc điệu.', 'My brother whistled a cheerful tune while washing dishes.', NULL, 'Anh trai tôi huýt sáo một giai điệu vui tươi trong lúc rửa bát.', '{"wordId":"tune","ukIpa":"/tjuːn/","usIpa":"/tuːn/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"a series of musical notes forming a recognizable pattern","vi":"giai điệu; khúc nhạc"},{"pos":"v.","en":"to adjust an instrument so it produces the correct notes","vi":"lên dây (đàn)"},{"pos":"v.","en":"to adjust a device to work or receive signals correctly","vi":"chỉnh tần số; điều chỉnh thiết bị"}],"examples":[{"en":"My brother whistled a cheerful tune while washing dishes.","vi":"Anh trai tôi huýt sáo một giai điệu vui tươi trong lúc rửa bát.","audioKind":"ex"},{"en":"A memorable tune can help young learners retain new vocabulary and develop greater confidence in speaking.","vi":"Một giai điệu dễ nhớ có thể giúp người học nhỏ tuổi ghi nhớ từ vựng mới và tự tin hơn khi nói.","audioKind":"ex2"}],"collocations":[{"en":"catchy tune","vi":"giai điệu bắt tai"},{"en":"in tune","vi":"đúng nhịp; đúng tông"},{"en":"out of tune","vi":"lạc điệu; sai tông"},{"en":"tune a piano","vi":"lên dây đàn piano"}],"wordFamily":["tuning (n.)","tuner (n.)","tuneful (adj.)"],"synonyms":["melody"],"antonyms":[],"tipVi":"in tune chỉ âm điều chính xác; out of tune chỉ lạc điệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carnival', 'en-b1-23', 'carnival', '/ˈkɑːrnəvəl/', 'B1', 'lễ hội hóa trang; ngày hội; hội chợ vui chơi (ngoài trời có các trò chơi và hoạt động giải trí)', 'n.', NULL, 'Đồng nghĩa: festival', 'Trong tiếng Anh-Mỹ, từ này còn có thể chỉ hội chợ giải trí có các trò chơi và khu vui chơi.', 'We wore colourful masks and danced at the carnival.', NULL, 'Chúng tôi đã đeo mặt nạ sặc sỡ và khiêu vũ tại lễ hội hóa trang.', '{"wordId":"carnival","ukIpa":"/ˈkɑːnɪvəl/","usIpa":"/ˈkɑːrnəvəl/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"A public celebration with music, costumes, and street entertainment.","vi":"lễ hội hóa trang; ngày hội"},{"pos":"n.","en":"An outdoor event with rides, games, and entertainment.","vi":"hội chợ vui chơi (ngoài trời có các trò chơi và hoạt động giải trí)"}],"examples":[{"en":"We wore colourful masks and danced at the carnival.","vi":"Chúng tôi đã đeo mặt nạ sặc sỡ và khiêu vũ tại lễ hội hóa trang.","audioKind":"ex"},{"en":"An annual carnival can strengthen community ties while attracting visitors who support local shops and restaurants.","vi":"Lễ hội thường niên có thể thắt chặt tình đoàn kết cộng đồng đồng thời thu hút du khách đến ủng hộ các cửa hàng và nhà hàng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a carnival parade","vi":"diễu hành lễ hội"},{"en":"a carnival atmosphere","vi":"không khí lễ hội"},{"en":"an annual carnival","vi":"lễ hội thường niên"}],"wordFamily":[],"synonyms":["festival"],"antonyms":[],"tipVi":"Trong tiếng Anh-Mỹ, từ này còn có thể chỉ hội chợ giải trí có các trò chơi và khu vui chơi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_23_1', 'en-b1-23', 'Cách dùng “unique” (adj.) — độc nhất; độc đáo', 'unique opportunity  ·  unique features  ·  unique to the region', 'unique to dùng để chỉ đặc trưng của một nơi nào đó; khi mang nghĩa tuyệt đối là duy nhất thì không dùng very để bổ nghĩa.', 'Họ từ (Word Family): uniquely (adv.), uniqueness (n.) | Đồng nghĩa: distinctive · Trái nghĩa: ordinary, common', '[{"hanzi":"Each handmade bowl has a unique pattern inside.","pinyin":"","meaning":"Mỗi chiếc bát thủ công đều có một họa tiết độc đáo ở bên trong."},{"hanzi":"Protecting local crafts helps communities preserve their unique cultural identity in an increasingly globalised world.","pinyin":"","meaning":"Việc bảo tồn các nghề thủ công địa phương giúp cộng đồng duy trì bản sắc văn hóa độc đáo của họ trong một thế giới ngày càng toàn cầu hóa."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_23_2', 'en-b1-23', 'Cách dùng “poem” (n.) — bài thơ; tác phẩm văn học sử dụng ngôn từ được gọt giũa cẩn thận, thường được chia thành các dòng', 'write a poem  ·  recite a poem  ·  a collection of poems', 'poem là danh từ đếm được, chỉ một bài thơ cụ thể; poetry là danh từ không đếm được, dùng để chỉ chung thơ ca.', 'Họ từ (Word Family): poet (n.), poetry (n.), poetic (adj.), poetically (adv.)', '[{"hanzi":"Leila read a short poem aloud after dinner.","pinyin":"","meaning":"Leila đọc to một bài thơ ngắn sau bữa tối."},{"hanzi":"Reading a poem from another culture can help students explore unfamiliar perspectives and develop sensitivity to language.","pinyin":"","meaning":"Việc đọc một bài thơ từ nền văn hóa khác có thể giúp học sinh khám phá những góc nhìn mới lạ và phát triển sự nhạy cảm với ngôn ngữ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_23_3', 'en-b1-23', 'Cách dùng “trumpet” (n.) — kèn trôm-pét; kèn đồng', 'play the trumpet  ·  trumpet player  ·  trumpet achievements', 'Nghĩa thông dụng là nhạc cụ "kèn trôm-pét"; ở nghĩa động từ, từ này có sắc thái đại ngôn, khoe khoang.', 'Họ từ (Word Family): trumpeter (n.)', '[{"hanzi":"The musician lifted her trumpet and played a cheerful tune.","pinyin":"","meaning":"Nữ nghệ sĩ nâng chiếc kèn trôm-pét lên và thổi một giai điệu vui tươi."},{"hanzi":"Learning the trumpet in a school orchestra can improve students'' concentration and ability to cooperate with others.","pinyin":"","meaning":"Việc học kèn trôm-pét trong dàn nhạc trường học có thể giúp học sinh nâng cao sự tập trung và khả năng phối hợp với người khác."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_23_4', 'en-b1-23', 'Cách dùng “opera” (n.) — vở kịch hát, nhạc kịch opera', 'an opera singer  ·  an opera house  ·  perform an opera', 'Khi chỉ nghệ thuật opera nói chung thì không đếm được; khi chỉ một tác phẩm cụ thể thì dùng an opera.', 'Họ từ (Word Family): operatic (adj.)', '[{"hanzi":"We watched an opera at the theatre last night.","pinyin":"","meaning":"Chúng tôi đã xem một buổi nhạc kịch opera tại nhà hát vào tối qua."},{"hanzi":"Public funding for opera can preserve artistic traditions while making performances accessible to a wider audience.","pinyin":"","meaning":"Việc tài trợ công cho nghệ thuật opera có thể bảo tồn các truyền thống nghệ thuật đồng thời giúp công chúng tiếp cận các buổi biểu diễn rộng rãi hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_23_1', 'en-b1-23', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
