INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_23_1_2', 'ten_b1_23_1', 'statue', 'A bronze statue of a horse stands beside the fountain.', 'A bronze statue of a horse stands beside the fountain.', '/ˈstætʃuː/', 'Một bức tượng đồng hình con ngựa đang đứng cạnh đài phun nước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_23_1_3', 'ten_b1_23_1', 'poetry', 'She reads poetry aloud while her tea cools.', 'She reads poetry aloud while her tea cools.', '/ˈpoʊətri/', 'Cô ấy vừa đọc thơ thành tiếng vừa đợi trà nguội.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_23_1_4', 'ten_b1_23_1', 'monster', 'The friendly monster in the cartoon has purple feet.', 'The friendly monster in the cartoon has purple feet.', '/ˈmɑːnstər/', 'Con quái vật thân thiện trong hoạt hình có đôi chân màu tím.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_23_1_5', 'ten_b1_23_1', 'poet', 'The poet read her latest work beside the fireplace.', 'The poet read her latest work beside the fireplace.', '/ˈpoʊət/', 'Nữ nhà thơ đã đọc tác phẩm mới nhất của mình cạnh lò sưởi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_23_1_6', 'ten_b1_23_1', 'drum', 'The little boy beat the drum with both hands.', 'The little boy beat the drum with both hands.', '/drʌm/', 'Cậu bé đánh chiếc trống bằng cả hai tay.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_23_1_7', 'ten_b1_23_1', 'magician', 'The magician pulled a silk scarf from an empty cup.', 'The magician pulled a silk scarf from an empty cup.', '/məˈdʒɪʃn/', 'Nhà ảo thuật lấy ra một chiếc khăn lụa từ một chiếc cốc rỗng.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_23_1_8', 'ten_b1_23_1', 'silk', 'She wrapped a soft silk scarf around her neck.', 'She wrapped a soft silk scarf around her neck.', '/sɪlk/', 'Cô ấy quấn một chiếc khăn lụa mềm mại quanh cổ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_23_1_1', 'en-b1-23', 'ten_b1_23_1', 'listening', 'listening', 'His comic dance had everyone laughing at the party.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nữ nghệ sĩ piano mỉm cười trước khi chơi bài hát yêu thích của cô ấy.","Điệu nhảy hài hước của anh ấy làm mọi người cười vang trong buổi tiệc.","Anh trai tôi huýt sáo một giai điệu vui tươi trong lúc rửa bát.","Cô ấy vừa đọc thơ thành tiếng vừa đợi trà nguội."]'::jsonb, 1, 'His comic dance had everyone laughing at the party. → Điệu nhảy hài hước của anh ấy làm mọi người cười vang trong buổi tiệc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_23_1_2', 'en-b1-23', 'ten_b1_23_1', 'listening', 'listening', 'A bronze statue of a horse stands beside the fountain.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một bức tượng đồng hình con ngựa đang đứng cạnh đài phun nước.","Chị tôi chơi một nhạc cụ khác nhau ở mỗi buổi tập.","Một bức tượng đồng hình con ngựa được đặt ở bên ngoài thư viện.","Điệu nhảy hài hước của anh ấy làm mọi người cười vang trong buổi tiệc."]'::jsonb, 0, 'A bronze statue of a horse stands beside the fountain. → Một bức tượng đồng hình con ngựa đang đứng cạnh đài phun nước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_23_1_3', 'en-b1-23', 'ten_b1_23_1', 'listening', 'listening', 'She reads poetry aloud while her tea cools.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy vừa đọc thơ thành tiếng vừa đợi trà nguội.","Leila đọc to một bài thơ ngắn sau bữa tối.","Chị tôi chơi một nhạc cụ khác nhau ở mỗi buổi tập.","Bức chân dung của bà tôi được treo phía trên lò sưởi trong phòng khách."]'::jsonb, 0, 'She reads poetry aloud while her tea cools. → Cô ấy vừa đọc thơ thành tiếng vừa đợi trà nguội.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_23_2', 'en-b1-23', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_23_2_1', 'ten_b1_23_2', 'comic', 'Comic characters can make educational programmes more engaging and help children remember important information.', 'Comic characters can make educational programmes more engaging and help children remember important information.', '/ˈkɑːmɪk/', 'Các nhân vật hoạt hình/truyện tranh có thể làm cho các chương trình giáo dục trở nên hấp dẫn hơn và giúp trẻ em ghi nhớ thông tin quan trọng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_23_2_2', 'ten_b1_23_2', 'statue', 'Public statues can preserve local history, but communities should discuss which figures deserve such recognition.', 'Public statues can preserve local history, but communities should discuss which figures deserve such recognition.', '/ˈstætʃuː/', 'Các bức tượng công cộng có thể lưu giữ lịch sử địa phương, nhưng cộng đồng nên thảo luận xem những nhân vật nào xứng đáng được tôn vinh như vậy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_23_2_3', 'ten_b1_23_2', 'poetry', 'Studying poetry encourages students to explore complex emotions and appreciate the expressive possibilities of language.', 'Studying poetry encourages students to explore complex emotions and appreciate the expressive possibilities of language.', '/ˈpoʊətri/', 'Việc nghiên cứu thơ ca khuyến khích học sinh khám phá những cảm xúc phức tạp và trân trọng khả năng biểu đạt phong phú của ngôn ngữ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_23_2_4', 'ten_b1_23_2', 'monster', 'Stories about monsters can help children explore their fears within a safe and imaginative setting.', 'Stories about monsters can help children explore their fears within a safe and imaginative setting.', '/ˈmɑːnstər/', 'Những câu chuyện về quái vật có thể giúp trẻ em khám phá nỗi sợ hãi trong một không gian an toàn và giàu trí tưởng tượng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_23_2_5', 'ten_b1_23_2', 'poet', 'A poet can challenge social attitudes by expressing familiar experiences in unexpected and emotionally powerful ways.', 'A poet can challenge social attitudes by expressing familiar experiences in unexpected and emotionally powerful ways.', '/ˈpoʊət/', 'Một nhà thơ có thể thách thức các quan niệm xã hội bằng cách diễn đạt những trải nghiệm quen thuộc theo những cách thức bất ngờ và giàu cảm xúc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_23_2_6', 'ten_b1_23_2', 'drum', 'Learning to play the drum can help children develop coordination and participate in group performances.', 'Learning to play the drum can help children develop coordination and participate in group performances.', '/drʌm/', 'Học đánh trống có thể giúp trẻ phát triển khả năng phối hợp và tham gia vào các buổi biểu diễn nhóm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_23_2_1', 'en-b1-23', 'ten_b1_23_2', 'listening', 'listening', 'Comic characters can make educational programmes more engaging and help children remember important information.', NULL, 'Trong câu vừa nghe, từ “comic” mang nghĩa nào sau đây?', '["mực (viết, vẽ, in)","dàn nhạc giao hưởng; dàn nhạc","hài hước; liên quan đến hài kịch","xóa; loại bỏ"]'::jsonb, 2, '“comic” (/ˈkɑːmɪk/): hài hước; liên quan đến hài kịch. Câu đầy đủ: Comic characters can make educational programmes more engaging and help children remember important information.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_23_2_2', 'en-b1-23', 'ten_b1_23_2', 'listening', 'listening', 'Public statues can preserve local history, but communities should discuss which figures deserve such recognition.', NULL, 'Trong câu vừa nghe, từ “statue” mang nghĩa nào sau đây?', '["mỗi khi; bất cứ khi nào","sự đặt chỗ; sự đặt trước","tượng; bức tượng","kinh Thánh"]'::jsonb, 2, '“statue” (/ˈstætʃuː/): tượng; bức tượng. Câu đầy đủ: Public statues can preserve local history, but communities should discuss which figures deserve such recognition.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
