INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_1', 'en-b1-23', NULL, 'comprehensive_test', 'listening', 'comic', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chịu đựng đau đớn; mắc bệnh","người đi xe đạp","hài hước; liên quan đến hài kịch","ngay lập tức; tức thì"]'::jsonb, 2, 'comic (/ˈkɑːmɪk/) → hài hước; liên quan đến hài kịch; truyện tranh (ấn phẩm kể chuyện qua chuỗi tranh vẽ); diễn viên hài; nghệ sĩ hài', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_2', 'en-b1-23', NULL, 'comprehensive_test', 'listening', 'A bronze statue of a horse stands beside the fountain.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một bức tượng đồng hình con ngựa đang đứng cạnh đài phun nước.","Chúng tôi đã xem một buổi nhạc kịch opera tại nhà hát vào tối qua.","Nam diễn viên hài đã làm cho mọi người cười ngất với những câu chuyện về con mèo của anh ấy.","Cô ấy quấn một chiếc khăn lụa mềm mại quanh cổ."]'::jsonb, 0, 'A bronze statue of a horse stands beside the fountain. → Một bức tượng đồng hình con ngựa đang đứng cạnh đài phun nước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_3', 'en-b1-23', NULL, 'comprehensive_test', 'listening', 'poetry', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bình rót nước; cái vại","khuyên; khuyên bảo","thơ ca","sự nghèo đói; cảnh nghèo túng"]'::jsonb, 2, 'poetry (/ˈpoʊətri/) → thơ ca; vẻ đẹp nên thơ; chất thơ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_4', 'en-b1-23', NULL, 'comprehensive_test', 'listening', 'The friendly monster in the cartoon has purple feet.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con quái vật thân thiện trong hoạt hình có đôi chân màu tím.","Leila đọc to một bài thơ ngắn sau bữa tối.","Nam diễn viên hài đã làm cho mọi người cười ngất với những câu chuyện về con mèo của anh ấy.","Trung tâm nghệ thuật địa phương của chúng tôi có các lớp học làm gốm và khiêu vũ."]'::jsonb, 0, 'The friendly monster in the cartoon has purple feet. → Con quái vật thân thiện trong hoạt hình có đôi chân màu tím.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_5', 'en-b1-23', NULL, 'comprehensive_test', 'listening', 'poet', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["có đốm; có chấm tròn","nhà thơ; thi sĩ","sự yên lặng; sự im lặng","kiến trúc sư"]'::jsonb, 1, 'poet (/ˈpoʊət/) → nhà thơ; thi sĩ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_6', 'en-b1-23', NULL, 'comprehensive_test', 'listening', 'The little boy beat the drum with both hands.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhà ảo thuật lấy ra một chiếc khăn lụa từ một chiếc cốc rỗng.","Một nghệ sĩ đường phố tung hứng những quả cam bên khu chợ đông đúc.","Cậu bé đánh chiếc trống bằng cả hai tay.","Nữ nghệ sĩ piano mỉm cười trước khi chơi bài hát yêu thích của cô ấy."]'::jsonb, 2, 'The little boy beat the drum with both hands. → Cậu bé đánh chiếc trống bằng cả hai tay.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_7', 'en-b1-23', NULL, 'comprehensive_test', 'listening', 'magician', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["dự định; có ý định","nhà ảo thuật","cá hồi; thịt cá hồi","kỳ lạ; quái lạ; bất thường"]'::jsonb, 1, 'magician (/məˈdʒɪʃn/) → nhà ảo thuật; pháp sư; người có phép thuật', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_8', 'en-b1-23', NULL, 'comprehensive_test', 'listening', 'She wrapped a soft silk scarf around her neck.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chị gái tôi thường nghe nhạc cổ điển trong lúc nấu ăn.","Tiệm bánh trưng bày những chiếc bánh tươi ngon ngay cạnh cửa sổ phía trước.","Nữ nghệ sĩ nâng chiếc kèn trôm-pét lên và thổi một giai điệu vui tươi.","Cô ấy quấn một chiếc khăn lụa mềm mại quanh cổ."]'::jsonb, 3, 'She wrapped a soft silk scarf around her neck. → Cô ấy quấn một chiếc khăn lụa mềm mại quanh cổ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_9', 'en-b1-23', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a person who writes poems”?', '["tune","tale","poetry","poet"]'::jsonb, 3, 'poet (/ˈpoʊət/) → nhà thơ; thi sĩ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_10', 'en-b1-23', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a musical instrument played by hitting its stretched surface”?', '["drum","comedian","statue","poet"]'::jsonb, 0, 'drum (/drʌm/) → cái trống', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_11', 'en-b1-23', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A performer who entertains people by doing seemingly impossible tricks.”?', '["magician","carnival","comedian","statue"]'::jsonb, 0, 'magician (/məˈdʒɪʃn/) → nhà ảo thuật', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_12', 'en-b1-23', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Fine thread produced by silkworms, or fabric made from it.”?', '["arts","poet","monster","silk"]'::jsonb, 3, 'silk (/sɪlk/) → tơ tằm; lụa; vải lụa', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
