INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_18', 'en-b1-23', NULL, 'comprehensive_test', 'reading', NULL, 'Comic characters can make educational programmes more engaging and help children remember important information.', 'Dựa vào câu trên, từ “comic” có nghĩa phù hợp nhất là gì?', '["cầu nguyện; cầu xin (thần linh)","hài hước; liên quan đến hài kịch","rắn, có hình dạng cố định chứ không phải lỏng hay khí","sự thanh toán; việc trả tiền"]'::jsonb, 1, 'comic: hài hước; liên quan đến hài kịch; truyện tranh (ấn phẩm kể chuyện qua chuỗi tranh vẽ); diễn viên hài; nghệ sĩ hài. Dịch cả câu: Các nhân vật hoạt hình/truyện tranh có thể làm cho các chương trình giáo dục trở nên hấp dẫn hơn và giúp trẻ em ghi nhớ thông tin quan trọng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_19', 'en-b1-23', NULL, 'comprehensive_test', 'reading', NULL, 'Public statues can preserve local history, but communities should discuss which figures deserve such recognition.', 'Dựa vào câu trên, từ “statue” có nghĩa phù hợp nhất là gì?', '["trong lúc đó; đồng thời; trong khi đó","đội trưởng; thuyền trưởng; cơ trưởng","người mua; khách hàng","tượng; bức tượng"]'::jsonb, 3, 'statue: tượng; bức tượng. Dịch cả câu: Các bức tượng công cộng có thể lưu giữ lịch sử địa phương, nhưng cộng đồng nên thảo luận xem những nhân vật nào xứng đáng được tôn vinh như vậy.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_20', 'en-b1-23', NULL, 'comprehensive_test', 'reading', NULL, 'Studying poetry encourages students to explore complex emotions and appreciate the expressive possibilities of language.', 'Dựa vào câu trên, từ “poetry” có nghĩa phù hợp nhất là gì?', '["thông báo; cho biết","nhai; cắn","thơ ca","bìa cứng; giấy các-tông"]'::jsonb, 2, 'poetry: thơ ca; vẻ đẹp nên thơ; chất thơ. Dịch cả câu: Việc nghiên cứu thơ ca khuyến khích học sinh khám phá những cảm xúc phức tạp và trân trọng khả năng biểu đạt phong phú của ngôn ngữ.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_21', 'en-b1-23', NULL, 'comprehensive_test', 'reading', NULL, 'Stories about monsters can help children explore their fears within a safe and imaginative setting.', 'Dựa vào câu trên, từ “monster” có nghĩa phù hợp nhất là gì?', '["bằng văn bản; có tính viết ra","tàn nhẫn; khắc nghiệt; thiếu tử tế","chính trị; hoạt động chính trị","quái vật; quái thú"]'::jsonb, 3, 'monster: quái vật; quái thú; kẻ tàn nhẫn; người độc ác; khổng lồ; to lớn. Dịch cả câu: Những câu chuyện về quái vật có thể giúp trẻ em khám phá nỗi sợ hãi trong một không gian an toàn và giàu trí tưởng tượng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_22', 'en-b1-23', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nghệ thuật; các hoạt động nghệ thuật”', '["gap","safety","nightlife","arts"]'::jsonb, 3, 'nghệ thuật; các hoạt động nghệ thuật → arts (/ɑːrts/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_23', 'en-b1-23', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giai điệu; khúc nhạc”', '["tune","arithmetic","grain","architect"]'::jsonb, 0, 'giai điệu; khúc nhạc → tune (/tuːn/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_23_24', 'en-b1-23', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lễ hội hóa trang; ngày hội”', '["carnival","certificate","attraction","parcel"]'::jsonb, 0, 'lễ hội hóa trang; ngày hội → carnival (/ˈkɑːrnəvəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-24', 'en', 'Bài 24: Nghệ thuật & Sáng tạo (2) - CEFR B1', 'CEFR B1', 'B1 · Nghệ thuật', '26 từ vựng Tiếng Anh CEFR B1 chủ đề nghệ thuật & sáng tạo kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3024, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thriller', 'en-b1-24', 'thriller', '/ˈθrɪlər/', 'B1', 'truyện trinh thám ly kỳ; phim kinh dị ly kỳ', 'n.', 'thrill (n.), thrill (v.), thrilling (adj.), thrilled (adj.)', NULL, 'thriller tập trung vào yếu tố hồi hộp và căng thẳng, không đồng nghĩa với phim kinh dị hù dọa thông thường (horror).', 'We watched a thriller and kept guessing the ending.', NULL, 'Chúng tôi đã xem một bộ phim ly kỳ và liên tục đoán xem kết cục sẽ ra sao.', '{"wordId":"thriller","ukIpa":"/ˈθrɪlə/","usIpa":"/ˈθrɪlər/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"An exciting story or film involving danger, suspense, or crime.","vi":"truyện trinh thám ly kỳ; phim kinh dị ly kỳ"}],"examples":[{"en":"We watched a thriller and kept guessing the ending.","vi":"Chúng tôi đã xem một bộ phim ly kỳ và liên tục đoán xem kết cục sẽ ra sao.","audioKind":"ex"},{"en":"A well-made thriller can encourage audiences to consider ethical questions while maintaining a strong sense of suspense.","vi":"Một bộ phim ly kỳ được đầu tư kỹ lưỡng có thể khuyến khích khán giả suy ngẫm về các vấn đề đạo đức trong khi vẫn duy trì được sự hồi hộp mãnh liệt.","audioKind":"ex2"}],"collocations":[{"en":"a crime thriller","vi":"tác phẩm trinh thám tội phạm"},{"en":"a psychological thriller","vi":"tác phẩm giật gân tâm lý"},{"en":"a political thriller","vi":"tác phẩm chính trị ly kỳ"}],"wordFamily":["thrill (n.)","thrill (v.)","thrilling (adj.)","thrilled (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"thriller tập trung vào yếu tố hồi hộp và căng thẳng, không đồng nghĩa với phim kinh dị hù dọa thông thường (horror).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decoration', 'en-b1-24', 'decoration', '/ˌdekəˈreɪʃən/', 'B1', 'đồ trang trí; sự trang trí; cách trang hoàng; huân chương; huy chương', 'n.', 'decorate (v.), decorative (adj.), decorator (n.)', 'Đồng nghĩa: ornament, adornment', 'Khi chỉ quá trình trang trí thì không đếm được; khi chỉ từng món đồ trang trí riêng lẻ thì đếm được.', 'She hung a bright paper decoration above the kitchen table.', NULL, 'Cô ấy treo một món đồ trang trí bằng giấy rực rỡ phía trên bàn bếp.', '{"wordId":"decoration","ukIpa":"/ˌdekəˈreɪʃən/","usIpa":"/ˌdekəˈreɪʃən/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"An object added to make something look more attractive.","vi":"đồ trang trí"},{"pos":"n.","en":"The process or style of making a place look attractive.","vi":"sự trang trí; cách trang hoàng"},{"pos":"n.","en":"An official award worn to honour service or bravery.","vi":"huân chương; huy chương"}],"examples":[{"en":"She hung a bright paper decoration above the kitchen table.","vi":"Cô ấy treo một món đồ trang trí bằng giấy rực rỡ phía trên bàn bếp.","audioKind":"ex"},{"en":"The decoration of public libraries can create welcoming spaces that encourage residents to spend more time reading.","vi":"Việc trang hoàng các thư viện công cộng có thể tạo ra những không gian thân thiện, khuyến khích người dân dành nhiều thời gian đọc sách hơn.","audioKind":"ex2"}],"collocations":[{"en":"interior decoration","vi":"trang trí nội thất"},{"en":"party decorations","vi":"đồ trang trí tiệc"},{"en":"table decoration","vi":"đồ trang trí bàn ăn"}],"wordFamily":["decorate (v.)","decorative (adj.)","decorator (n.)"],"synonyms":["ornament","adornment"],"antonyms":[],"tipVi":"Khi chỉ quá trình trang trí thì không đếm được; khi chỉ từng món đồ trang trí riêng lẻ thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_studio', 'en-b1-24', 'studio', '/ˈstuːdioʊ/', 'B1', 'phòng thu; xưởng nghệ thuật; phim trường; hãng phim; căn hộ studio (căn hộ nhỏ một phòng)', 'n.', NULL, NULL, 'Cả studio flat (tiếng Anh-Anh) và studio apartment (tiếng Anh-Mỹ) đều chỉ căn hộ một phòng.', 'The artist invited us into her bright upstairs studio.', NULL, 'Nữ nghệ sĩ mời chúng tôi vào xưởng vẽ ngập tràn ánh sáng của cô ấy ở lầu trên.', '{"wordId":"studio","ukIpa":"/ˈstjuːdiəʊ/","usIpa":"/ˈstuːdioʊ/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"A room where art, music, or broadcasts are produced","vi":"phòng thu; xưởng nghệ thuật; phim trường"},{"pos":"n.","en":"A company that makes films","vi":"hãng phim"},{"pos":"n.","en":"A flat combining living and sleeping space in one room","vi":"căn hộ studio (căn hộ nhỏ một phòng)"}],"examples":[{"en":"The artist invited us into her bright upstairs studio.","vi":"Nữ nghệ sĩ mời chúng tôi vào xưởng vẽ ngập tràn ánh sáng của cô ấy ở lầu trên.","audioKind":"ex"},{"en":"Public funding for affordable studio spaces can help emerging artists contribute to a city''s cultural life.","vi":"Kinh phí công cộng dành cho các không gian xưởng nghệ thuật giá rẻ có thể giúp các nghệ sĩ mới nổi đóng góp vào đời sống văn hóa của thành phố.","audioKind":"ex2"}],"collocations":[{"en":"recording studio","vi":"phòng thu âm"},{"en":"art studio","vi":"xưởng nghệ thuật"},{"en":"film studio","vi":"hãng phim điện ảnh"},{"en":"studio flat","vi":"căn hộ studio"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cả studio flat (tiếng Anh-Anh) và studio apartment (tiếng Anh-Mỹ) đều chỉ căn hộ một phòng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_photography', 'en-b1-24', 'photography', '/fəˈtɑːɡrəfi/', 'B1', 'nghệ thuật nhiếp ảnh; kỹ thuật chụp ảnh', 'n.', 'photograph (n.), photograph (v.), photographer (n.), photographic (adj.)', NULL, 'Photography là danh từ không đếm được; một bức ảnh cụ thể dùng photograph.', 'My sister enjoys photography and carries her camera everywhere.', NULL, 'Chị gái tôi thích chụp ảnh và mang theo máy ảnh đi bất cứ đâu.', '{"wordId":"photography","ukIpa":"/fəˈtɒɡrəfi/","usIpa":"/fəˈtɑːɡrəfi/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"The activity or skill of taking photographs.","vi":"nghệ thuật nhiếp ảnh; kỹ thuật chụp ảnh"}],"examples":[{"en":"My sister enjoys photography and carries her camera everywhere.","vi":"Chị gái tôi thích chụp ảnh và mang theo máy ảnh đi bất cứ đâu.","audioKind":"ex"},{"en":"Digital photography allows researchers to document environmental changes and share visual evidence with a wider audience.","vi":"Nhiếp ảnh kỹ thuật số cho phép các nhà nghiên cứu ghi lại những thay đổi của môi trường và chia sẻ bằng chứng trực quan với nhiều đối tượng hơn.","audioKind":"ex2"}],"collocations":[{"en":"digital photography","vi":"nhiếp ảnh kỹ thuật số"},{"en":"wildlife photography","vi":"nhiếp ảnh động vật hoang dã"},{"en":"portrait photography","vi":"nhiếp ảnh chân dung"},{"en":"take up photography","vi":"bắt đầu học chụp ảnh"}],"wordFamily":["photograph (n.)","photograph (v.)","photographer (n.)","photographic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Photography là danh từ không đếm được; một bức ảnh cụ thể dùng photograph.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fiction', 'en-b1-24', 'fiction', '/ˈfɪkʃən/', 'B1', 'truyện hư cấu; tiểu thuyết; điều bịa đặt; chuyện hoang đường', 'n.', 'fictional (adj.), fictionalise (v.)', 'Trái nghĩa: non-fiction', 'Khi chỉ thể loại tiểu thuyết nói chung thì không đếm được; một cuốn tiểu thuyết cụ thể có thể dùng a work of fiction.', 'My sister reads fiction on the train every morning.', NULL, 'Chị tôi đọc tiểu thuyết trên tàu vào mỗi buổi sáng.', '{"wordId":"fiction","ukIpa":"/ˈfɪkʃən/","usIpa":"/ˈfɪkʃən/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"Stories about imagined people and events.","vi":"truyện hư cấu; tiểu thuyết"},{"pos":"n.","en":"Something invented that is presented as true.","vi":"điều bịa đặt; chuyện hoang đường"}],"examples":[{"en":"My sister reads fiction on the train every morning.","vi":"Chị tôi đọc tiểu thuyết trên tàu vào mỗi buổi sáng.","audioKind":"ex"},{"en":"Reading fiction can help young people understand unfamiliar perspectives and develop greater empathy for others.","vi":"Việc đọc tiểu thuyết có thể giúp người trẻ hiểu được những góc nhìn xa lạ và nuôi dưỡng sự đồng cảm lớn hơn đối với người khác.","audioKind":"ex2"}],"collocations":[{"en":"science fiction","vi":"truyện khoa học viễn tưởng"},{"en":"historical fiction","vi":"tiểu thuyết lịch sử"},{"en":"a work of fiction","vi":"một tác phẩm văn học hư cấu"},{"en":"fact and fiction","vi":"thực tế và hư cấu"}],"wordFamily":["fictional (adj.)","fictionalise (v.)"],"synonyms":[],"antonyms":["non-fiction"],"tipVi":"Khi chỉ thể loại tiểu thuyết nói chung thì không đếm được; một cuốn tiểu thuyết cụ thể có thể dùng a work of fiction.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_orchestra', 'en-b1-24', 'orchestra', '/ˈɔːrkɪstrə/', 'B1', 'dàn nhạc giao hưởng; dàn nhạc', 'n.', 'orchestral (adj.)', NULL, 'Chỉ toàn bộ dàn nhạc lớn; các thành viên thường chơi nhạc cụ dây, nhạc cụ hơi và nhạc cụ gõ.', 'The orchestra began playing as the lights dimmed.', NULL, 'Dàn nhạc bắt đầu chơi khi đèn mờ dần.', '{"wordId":"orchestra","ukIpa":"/ˈɔːkɪstrə/","usIpa":"/ˈɔːrkɪstrə/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"A large group of musicians playing different instruments together.","vi":"dàn nhạc giao hưởng; dàn nhạc"}],"examples":[{"en":"The orchestra began playing as the lights dimmed.","vi":"Dàn nhạc bắt đầu chơi khi đèn mờ dần.","audioKind":"ex"},{"en":"Public funding helps the local orchestra offer affordable concerts and introduce classical music to younger audiences.","vi":"Sự tài trợ công giúp dàn nhạc địa phương tổ chức các buổi hòa nhạc với giá vé phải chăng và đưa âm nhạc cổ điển đến gần hơn với khán giả trẻ.","audioKind":"ex2"}],"collocations":[{"en":"symphony orchestra","vi":"dàn nhạc giao hưởng"},{"en":"conduct an orchestra","vi":"chỉ huy dàn nhạc"},{"en":"play in an orchestra","vi":"biểu diễn trong dàn nhạc"}],"wordFamily":["orchestral (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ toàn bộ dàn nhạc lớn; các thành viên thường chơi nhạc cụ dây, nhạc cụ hơi và nhạc cụ gõ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_talented', 'en-b1-24', 'talented', '/ˈtæləntɪd/', 'B1', 'có năng khiếu; có tài', 'adj.', 'talent (n.)', 'Đồng nghĩa: gifted, skilled · Trái nghĩa: untalented', 'talented nhấn mạnh vào thiên bẩm; skilled nhấn mạnh vào kỹ năng được rèn luyện.', 'My talented cousin painted this beautiful picture of our garden.', NULL, 'Người anh em họ tài năng của tôi đã vẽ bức tranh đẹp này về khu vườn của chúng tôi.', '{"wordId":"talented","ukIpa":"/ˈtæləntɪd/","usIpa":"/ˈtæləntɪd/","cefr":"B1","topic":"arts","senses":[{"pos":"adj.","en":"Having a natural ability to do something very well.","vi":"có năng khiếu; có tài"}],"examples":[{"en":"My talented cousin painted this beautiful picture of our garden.","vi":"Người anh em họ tài năng của tôi đã vẽ bức tranh đẹp này về khu vườn của chúng tôi.","audioKind":"ex"},{"en":"Schools should provide opportunities for talented students to develop their abilities beyond the standard curriculum.","vi":"Các trường học nên tạo cơ hội cho những học sinh có tài năng phát triển khả năng của các em vượt ra ngoài chương trình giảng dạy tiêu chuẩn.","audioKind":"ex2"}],"collocations":[{"en":"a talented musician","vi":"một nhạc sĩ tài năng"},{"en":"a talented artist","vi":"một nghệ sĩ tài hoa"},{"en":"highly talented","vi":"có tài năng xuất chúng"}],"wordFamily":["talent (n.)"],"synonyms":["gifted","skilled"],"antonyms":["untalented"],"tipVi":"talented nhấn mạnh vào thiên bẩm; skilled nhấn mạnh vào kỹ năng được rèn luyện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stylish', 'en-b1-24', 'stylish', '/ˈstaɪlɪʃ/', 'B1', 'hợp thời trang; có phong cách; có gu thẩm mỹ', 'adj.', 'style (n.), style (v.), stylishly (adv.)', 'Đồng nghĩa: fashionable, chic · Trái nghĩa: unfashionable', 'stylish nhấn mạnh vào sự hợp mốt và đẹp mắt, không đồng nghĩa với việc cứ phải đắt tiền hay xa xỉ.', 'Her stylish green jacket looked great with plain trousers.', NULL, 'Chiếc áo khoác xanh sành điệu của cô ấy trông rất hợp với chiếc quần trơn.', '{"wordId":"stylish","ukIpa":"/ˈstaɪlɪʃ/","usIpa":"/ˈstaɪlɪʃ/","cefr":"B1","topic":"arts","senses":[{"pos":"adj.","en":"Attractive and fashionable in appearance or design","vi":"hợp thời trang; có phong cách; có gu thẩm mỹ"}],"examples":[{"en":"Her stylish green jacket looked great with plain trousers.","vi":"Chiếc áo khoác xanh sành điệu của cô ấy trông rất hợp với chiếc quần trơn.","audioKind":"ex"},{"en":"Affordable, stylish furniture can encourage young consumers to choose recycled materials for their homes.","vi":"Đồ nội thất giá cả phải chăng và có thiết kế hợp thời trang có thể khuyến khích người tiêu dùng trẻ tuổi lựa chọn vật liệu tái chế cho ngôi nhà của họ.","audioKind":"ex2"}],"collocations":[{"en":"stylish clothes","vi":"quần áo sành điệu"},{"en":"a stylish design","vi":"thiết kế có phong cách"},{"en":"a stylish interior","vi":"không gian nội thất trang nhã"}],"wordFamily":["style (n.)","style (v.)","stylishly (adv.)"],"synonyms":["fashionable","chic"],"antonyms":["unfashionable"],"tipVi":"stylish nhấn mạnh vào sự hợp mốt và đẹp mắt, không đồng nghĩa với việc cứ phải đắt tiền hay xa xỉ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flute', 'en-b1-24', 'flute', '/fluːt/', 'B1', 'cây sáo (nhạc cụ hơi)', 'n.', 'flautist (n.), flutist (n.)', NULL, 'Trong tiếng Anh-Anh, người chơi sáo thường được gọi là flautist, còn tiếng Anh-Mỹ ưa dùng từ flutist hơn.', 'She practises the flute by her bedroom window every afternoon.', NULL, 'Cô ấy tập thổi sáo bên cửa sổ phòng ngủ vào mỗi buổi chiều.', '{"wordId":"flute","ukIpa":"/fluːt/","usIpa":"/fluːt/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"A wind instrument held sideways and played by blowing across it.","vi":"cây sáo (nhạc cụ hơi)"}],"examples":[{"en":"She practises the flute by her bedroom window every afternoon.","vi":"Cô ấy tập thổi sáo bên cửa sổ phòng ngủ vào mỗi buổi chiều.","audioKind":"ex"},{"en":"Learning to play the flute can develop concentration and encourage children to participate in musical ensembles.","vi":"Học thổi sáo có thể giúp rèn luyện sự tập trung và khuyến khích trẻ em tham gia vào các ban nhạc hòa tấu.","audioKind":"ex2"}],"collocations":[{"en":"play the flute","vi":"thổi sáo"},{"en":"a flute solo","vi":"bản hòa tấu sáo đơn"},{"en":"flute lessons","vi":"các buổi học sáo"}],"wordFamily":["flautist (n.)","flutist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, người chơi sáo thường được gọi là flautist, còn tiếng Anh-Mỹ ưa dùng từ flutist hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exhibition', 'en-b1-24', 'exhibition', '/ˌeksəˈbɪʃən/', 'B1', 'triển lãm; cuộc triển lãm', 'n.', 'exhibit (v.), exhibit (n.), exhibitor (n.)', 'Đồng nghĩa: show, display', 'exhibition chỉ toàn bộ sự kiện triển lãm; exhibit có thể chỉ một hiện vật trưng bày cụ thể.', 'We visited a photography exhibition at the local museum.', NULL, 'Chúng tôi đã tham quan một buổi triển lãm nhiếp ảnh tại bảo tàng địa phương.', '{"wordId":"exhibition","ukIpa":"/ˌeksɪˈbɪʃən/","usIpa":"/ˌeksəˈbɪʃən/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"A public display of art, objects, or products.","vi":"triển lãm; cuộc triển lãm"}],"examples":[{"en":"We visited a photography exhibition at the local museum.","vi":"Chúng tôi đã tham quan một buổi triển lãm nhiếp ảnh tại bảo tàng địa phương.","audioKind":"ex"},{"en":"An interactive exhibition can make scientific discoveries more accessible to children and encourage their interest in research.","vi":"Một cuộc triển lãm tương tác có thể giúp trẻ em tiếp cận các khám phá khoa học dễ dàng hơn và khơi dậy sự quan tâm của các em đối với hoạt động nghiên cứu.","audioKind":"ex2"}],"collocations":[{"en":"art exhibition","vi":"triển lãm nghệ thuật"},{"en":"hold an exhibition","vi":"tổ chức triển lãm"},{"en":"on exhibition","vi":"đang trưng bày"}],"wordFamily":["exhibit (v.)","exhibit (n.)","exhibitor (n.)"],"synonyms":["show","display"],"antonyms":[],"tipVi":"exhibition chỉ toàn bộ sự kiện triển lãm; exhibit có thể chỉ một hiện vật trưng bày cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_biography', 'en-b1-24', 'biography', '/baɪˈɑːɡrəfi/', 'B1', 'sách tiểu sử; lý lịch', 'n.', 'biographer (n.), biographical (adj.), autobiography (n.)', NULL, 'biography là tiểu sử do người khác viết về cuộc đời một nhân vật; tự truyện dùng autobiography.', 'I''m reading a biography of an explorer before bed.', NULL, 'Tôi đang đọc cuốn tiểu sử về một nhà thám hiểm trước khi đi ngủ.', '{"wordId":"biography","ukIpa":"/baɪˈɒɡrəfi/","usIpa":"/baɪˈɑːɡrəfi/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"a written account of someone''s life by another person","vi":"sách tiểu sử; lý lịch"}],"examples":[{"en":"I''m reading a biography of an explorer before bed.","vi":"Tôi đang đọc cuốn tiểu sử về một nhà thám hiểm trước khi đi ngủ.","audioKind":"ex"},{"en":"A well-researched biography can reveal how social conditions influence an individual''s choices and achievements.","vi":"Một cuốn tiểu sử được nghiên cứu kỹ lưỡng có thể tiết lộ cách các điều kiện xã hội chi phối những lựa chọn và thành tựu của một cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"write a biography","vi":"viết tiểu sử"},{"en":"a biography of someone","vi":"tiểu sử của ai đó"},{"en":"an authorised biography","vi":"tiểu sử chính thức được ủy quyền"}],"wordFamily":["biographer (n.)","biographical (adj.)","autobiography (n.)"],"synonyms":[],"antonyms":[],"tipVi":"biography là tiểu sử do người khác viết về cuộc đời một nhân vật; tự truyện dùng autobiography.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_entertainment', 'en-b1-24', 'entertainment', '/ˌentərˈteɪnmənt/', 'B1', 'sự giải trí; hoạt động giải trí', 'n.', 'entertain (v.), entertaining (adj.), entertainer (n.)', 'Đồng nghĩa: amusement', 'Thường không đếm được: cung cấp giải trí dùng provide entertainment.', 'The hotel provides live entertainment beside the pool every evening.', NULL, 'Khách sạn cung cấp các tiết mục biểu diễn giải trí trực tiếp bên hồ bơi mỗi buổi tối.', '{"wordId":"entertainment","ukIpa":"/ˌentəˈteɪnmənt/","usIpa":"/ˌentərˈteɪnmənt/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"Performances or activities that people enjoy watching or doing.","vi":"sự giải trí; hoạt động giải trí"}],"examples":[{"en":"The hotel provides live entertainment beside the pool every evening.","vi":"Khách sạn cung cấp các tiết mục biểu diễn giải trí trực tiếp bên hồ bơi mỗi buổi tối.","audioKind":"ex"},{"en":"Affordable entertainment facilities can improve urban life by giving residents opportunities to relax and socialise.","vi":"Các cơ sở giải trí giá cả phải chăng có thể cải thiện đời sống đô thị bằng cách mang lại cho cư dân cơ hội thư giãn và giao lưu.","audioKind":"ex2"}],"collocations":[{"en":"live entertainment","vi":"giải trí trực tiếp"},{"en":"the entertainment industry","vi":"ngành công nghiệp giải trí"},{"en":"family entertainment","vi":"giải trí gia đình"},{"en":"a form of entertainment","vi":"một hình thức giải trí"}],"wordFamily":["entertain (v.)","entertaining (adj.)","entertainer (n.)"],"synonyms":["amusement"],"antonyms":[],"tipVi":"Thường không đếm được: cung cấp giải trí dùng provide entertainment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ghost', 'en-b1-24', 'ghost', '/ɡoʊst/', 'B1', 'ma; linh hồn; bóng ma; một chút; nét phảng phất', 'n.', 'ghostly (adj.)', 'Đồng nghĩa: spirit, apparition', 'a ghost of a smile chỉ một nụ cười thoáng qua, mờ nhạt.', 'My little cousin dressed as a ghost for the party.', NULL, 'Cậu em họ nhỏ của tôi đã hóa trang thành một hồn ma để đi dự tiệc.', '{"wordId":"ghost","ukIpa":"/ɡəʊst/","usIpa":"/ɡoʊst/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"The spirit of a dead person, imagined as appearing alive.","vi":"ma; linh hồn; bóng ma"},{"pos":"n.","en":"A very slight trace of a feeling, expression, or quality.","vi":"một chút; nét phảng phất"}],"examples":[{"en":"My little cousin dressed as a ghost for the party.","vi":"Cậu em họ nhỏ của tôi đã hóa trang thành một hồn ma để đi dự tiệc.","audioKind":"ex"},{"en":"Local ghost stories can attract tourists while revealing how communities interpret their history and cultural traditions.","vi":"Những câu chuyện ma địa phương có thể thu hút khách du lịch đồng thời cho thấy cách cộng đồng lý giải lịch sử và truyền thống văn hóa của họ.","audioKind":"ex2"}],"collocations":[{"en":"a ghost story","vi":"câu chuyện ma"},{"en":"a ghost town","vi":"thị trấn hoang vắng"},{"en":"a ghost of a smile","vi":"nụ cười phảng phất"},{"en":"see a ghost","vi":"nhìn thấy ma"}],"wordFamily":["ghostly (adj.)"],"synonyms":["spirit","apparition"],"antonyms":[],"tipVi":"a ghost of a smile chỉ một nụ cười thoáng qua, mờ nhạt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drummer', 'en-b1-24', 'drummer', '/ˈdrʌmɚ/', 'B1', 'tay trống; người đánh trống', 'n.', 'drum (n.), drum (v.), drumming (n.)', NULL, 'drum thêm -er thành drummer, lưu ý gấp đôi chữ m.', 'The drummer tapped her sticks together before the song.', NULL, 'Nữ tay trống gõ hai chiếc dìu trống vào nhau trước bài hát.', '{"wordId":"drummer","ukIpa":"/ˈdrʌmə(r)/","usIpa":"/ˈdrʌmɚ/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"A person who plays drums, especially in a musical group.","vi":"tay trống; người đánh trống"}],"examples":[{"en":"The drummer tapped her sticks together before the song.","vi":"Nữ tay trống gõ hai chiếc dìu trống vào nhau trước bài hát.","audioKind":"ex"},{"en":"A skilled drummer helps musicians maintain a steady rhythm, which is essential for a coordinated live performance.","vi":"Một tay trống giỏi giúp các nhạc công duy trì nhịp điệu ổn định, điều rất quan trọng cho một buổi biểu diễn trực tiếp ăn ý.","audioKind":"ex2"}],"collocations":[{"en":"a skilled drummer","vi":"một tay trống cừ khôi"},{"en":"a jazz drummer","vi":"tay trống nhạc jazz"},{"en":"the band''s drummer","vi":"tay trống của ban nhạc"}],"wordFamily":["drum (n.)","drum (v.)","drumming (n.)"],"synonyms":[],"antonyms":[],"tipVi":"drum thêm -er thành drummer, lưu ý gấp đôi chữ m.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ballet', 'en-b1-24', 'ballet', '/bæˈleɪ/', 'B1', 'múa ba-lê; vở múa ba-lê', 'n.', NULL, NULL, 'Âm t ở cuối từ không phát âm; trọng âm tiếng Anh-Anh nằm ở đầu từ, còn tiếng Anh-Mỹ nằm ở cuối.', 'My sister practises ballet at the studio every Saturday.', NULL, 'Em gái tôi tập múa ba-lê tại phòng tập vào mỗi thứ Bảy.', '{"wordId":"ballet","ukIpa":"/ˈbæleɪ/","usIpa":"/bæˈleɪ/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"A formal dance style, or a performance using this style.","vi":"múa ba-lê; vở múa ba-lê"}],"examples":[{"en":"My sister practises ballet at the studio every Saturday.","vi":"Em gái tôi tập múa ba-lê tại phòng tập vào mỗi thứ Bảy.","audioKind":"ex"},{"en":"Public funding for ballet can help preserve artistic traditions and make performances accessible to a wider audience.","vi":"Sự tài trợ công cho nghệ thuật múa ba-lê có thể giúp bảo tồn các truyền thống nghệ thuật và giúp đông đảo khán giả tiếp cận các buổi biểu diễn hơn.","audioKind":"ex2"}],"collocations":[{"en":"ballet dancer","vi":"vũ công ba-lê"},{"en":"ballet company","vi":"đoàn múa ba-lê"},{"en":"ballet lessons","vi":"lớp học múa ba-lê"},{"en":"classical ballet","vi":"múa ba-lê cổ điển"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Âm t ở cuối từ không phát âm; trọng âm tiếng Anh-Anh nằm ở đầu từ, còn tiếng Anh-Mỹ nằm ở cuối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_angel', 'en-b1-24', 'angel', '/ˈeɪndʒəl/', 'B1', 'thiên thần; người cực kỳ tốt bụng hoặc hay giúp đỡ', 'n.', 'angelic (adj.)', NULL, 'Goi ai đó là an angel, có thể biểu thị người đó tốt bụng hoặc đã giúp đỡ rất nhiều.', 'The painting shows an angel with shining white wings.', NULL, 'Bức tranh vẽ một vị thiên thần với đôi cánh trắng ngần tỏa sáng.', '{"wordId":"angel","ukIpa":"/ˈeɪndʒəl/","usIpa":"/ˈeɪndʒəl/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"A spiritual being believed to carry messages from God","vi":"thiên thần"},{"pos":"n.","en":"Someone who is exceptionally kind or helpful","vi":"người cực kỳ tốt bụng hoặc hay giúp đỡ"}],"examples":[{"en":"The painting shows an angel with shining white wings.","vi":"Bức tranh vẽ một vị thiên thần với đôi cánh trắng ngần tỏa sáng.","audioKind":"ex"},{"en":"Images of angels appear in religious art and can reveal important aspects of a society''s beliefs.","vi":"Hình ảnh các thiên thần xuất hiện trong nghệ thuật tôn giáo và có thể bộc lộ những khía cạnh quan trọng trong niềm tin của một xã hội.","audioKind":"ex2"}],"collocations":[{"en":"guardian angel","vi":"thiên thần hộ mệnh"},{"en":"an absolute angel","vi":"một người thực sự tốt bụng"},{"en":"angel wings","vi":"cánh thiên thần"}],"wordFamily":["angelic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Goi ai đó là an angel, có thể biểu thị người đó tốt bụng hoặc đã giúp đỡ rất nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_novel', 'en-b1-24', 'novel', '/ˈnɑːvəl/', 'B1', 'tiểu thuyết; truyện dài; mới lạ; độc đáo', 'n.', 'novelist (n.), novelty (n.)', NULL, 'Khi là danh từ nghĩa là tiểu thuyết; khi là tính từ mang nghĩa mới mẻ.', 'I finished the novel on the train yesterday.', NULL, 'Tôi đã đọc xong cuốn tiểu thuyết trên chuyến tàu vào ngày hôm qua.', '{"wordId":"novel","ukIpa":"/ˈnɒvəl/","usIpa":"/ˈnɑːvəl/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"A long written story about imaginary people and events.","vi":"tiểu thuyết; truyện dài"},{"pos":"adj.","en":"New and different from what is already known.","vi":"mới lạ; độc đáo"}],"examples":[{"en":"I finished the novel on the train yesterday.","vi":"Tôi đã đọc xong cuốn tiểu thuyết trên chuyến tàu vào ngày hôm qua.","audioKind":"ex"},{"en":"Schools can use historical novels to help students understand how ordinary people experienced major social changes.","vi":"Các trường học có thể sử dụng tiểu thuyết lịch sử để giúp học sinh hiểu được cách những người bình thường trải qua các thay đổi xã hội lớn lao.","audioKind":"ex2"}],"collocations":[{"en":"write a novel","vi":"viết tiểu thuyết"},{"en":"historical novel","vi":"tiểu thuyết lịch sử"},{"en":"novel approach","vi":"phương pháp mới lạ"}],"wordFamily":["novelist (n.)","novelty (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là danh từ nghĩa là tiểu thuyết; khi là tính từ mang nghĩa mới mẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_costume', 'en-b1-24', 'costume', '/ˈkɑːstuːm/', 'B1', 'trang phục hóa trang; trang phục diễn kịch; quần áo truyền thống; trang phục dân tộc', 'n.', 'costumed (adj.)', NULL, 'chỉ quần áo hóa trang nhân vật hoặc mang nét văn hóa đặc thù, không dùng cho quần áo thường ngày.', 'Lena wore a butterfly costume in the school play.', NULL, 'Lena mặc trang phục hình con bướm trong vở kịch của trường.', '{"wordId":"costume","ukIpa":"/ˈkɒstjuːm/","usIpa":"/ˈkɑːstuːm/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"clothes worn to look like a particular character or creature","vi":"trang phục hóa trang; trang phục diễn kịch"},{"pos":"n.","en":"clothing typical of a particular country, culture, or historical period","vi":"quần áo truyền thống; trang phục dân tộc"}],"examples":[{"en":"Lena wore a butterfly costume in the school play.","vi":"Lena mặc trang phục hình con bướm trong vở kịch của trường.","audioKind":"ex"},{"en":"Traditional costume can express cultural identity and help younger generations understand the history of their communities.","vi":"Trang phục truyền thống có thể thể hiện bản sắc văn hóa và giúp thế hệ trẻ hiểu về lịch sử cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"traditional costume","vi":"trang phục truyền thống"},{"en":"a costume designer","vi":"nhà thiết kế trang phục"},{"en":"a costume party","vi":"tiệc hóa trang"}],"wordFamily":["costumed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"chỉ quần áo hóa trang nhân vật hoặc mang nét văn hóa đặc thù, không dùng cho quần áo thường ngày.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_original', 'en-b1-24', 'original', '/əˈrɪdʒənəl/', 'B1', 'ban đầu; nguyên bản; độc đáo; sáng tạo; bản gốc', 'adj.', 'originally (adv.), originality (n.), origin (n.), originate (v.)', NULL, 'Có thể mang nghĩa là nguyên bản từ ban đầu, hoặc mang nghĩa sáng tạo độc đáo; cần phân tích dựa trên ngữ cảnh.', 'The kitchen still has its original wooden floor.', NULL, 'Căn bếp vẫn giữ nguyên vẹn sàn gỗ ban đầu của nó.', '{"wordId":"original","ukIpa":"/əˈrɪdʒənəl/","usIpa":"/əˈrɪdʒənəl/","cefr":"B1","topic":"arts","senses":[{"pos":"adj.","en":"existing at the beginning, before any changes","vi":"ban đầu; nguyên bản"},{"pos":"adj.","en":"new and different rather than copied from something else","vi":"độc đáo; sáng tạo"},{"pos":"n.","en":"the first version from which copies are made","vi":"bản gốc; nguyên bản"}],"examples":[{"en":"The kitchen still has its original wooden floor.","vi":"Căn bếp vẫn giữ nguyên vẹn sàn gỗ ban đầu của nó.","audioKind":"ex"},{"en":"Schools should encourage original thinking rather than reward students only for repeating information from textbooks.","vi":"Nhà trường nên khuyến khích tư duy sáng tạo thay vì chỉ thưởng cho học sinh vì việc lặp lại kiến thức từ sách giáo khoa.","audioKind":"ex2"}],"collocations":[{"en":"original plan","vi":"kế hoạch ban đầu"},{"en":"original design","vi":"thiết kế nguyên bản"},{"en":"original research","vi":"nghiên cứu gốc"},{"en":"original version","vi":"bản gốc"}],"wordFamily":["originally (adv.)","originality (n.)","origin (n.)","originate (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể mang nghĩa là nguyên bản từ ban đầu, hoặc mang nghĩa sáng tạo độc đáo; cần phân tích dựa trên ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_theme', 'en-b1-24', 'theme', '/θiːm/', 'B1', 'chủ đề; tư tưởng chủ đạo; nhạc hiệu; chủ đề âm nhạc', 'n.', 'thematic (adj.), thematically (adv.), themed (adj.)', 'Đồng nghĩa: subject, topic', 'theme nhấn mạnh nội dung tư tưởng xuyên suốt của tác phẩm; trong khi topic thường chỉ đề tài trò chuyện.', 'We chose a seaside theme for the birthday party.', NULL, 'Chúng tôi đã chọn chủ đề miền biển cho bữa tiệc sinh nhật.', '{"wordId":"theme","ukIpa":"/θiːm/","usIpa":"/θiːm/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"the main subject or idea in a work or discussion","vi":"chủ đề; tư tưởng chủ đạo"},{"pos":"n.","en":"a recognisable tune associated with a programme or musical work","vi":"nhạc hiệu; chủ đề âm nhạc"}],"examples":[{"en":"We chose a seaside theme for the birthday party.","vi":"Chúng tôi đã chọn chủ đề miền biển cho bữa tiệc sinh nhật.","audioKind":"ex"},{"en":"The relationship between economic growth and environmental protection is a central theme in contemporary public debate.","vi":"Mối quan hệ giữa tăng trưởng kinh tế và bảo vệ môi trường là chủ đề cốt lõi trong các cuộc tranh luận công khai đương đại.","audioKind":"ex2"}],"collocations":[{"en":"central theme","vi":"chủ đề trung tâm"},{"en":"recurring theme","vi":"chủ đề lặp đi lặp lại"},{"en":"theme music","vi":"nhạc chủ đề"},{"en":"theme park","vi":"công viên giải trí theo chủ đề"}],"wordFamily":["thematic (adj.)","thematically (adv.)","themed (adj.)"],"synonyms":["subject","topic"],"antonyms":[],"tipVi":"theme nhấn mạnh nội dung tư tưởng xuyên suốt của tác phẩm; trong khi topic thường chỉ đề tài trò chuyện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_choir', 'en-b1-24', 'choir', '/ˈkwaɪr/', 'B1', 'dàn hợp xướng; đội hợp ca', 'n.', 'choral (adj.), chorister (n.)', NULL, 'Cách phát âm tương tự từ quire, phần đầu không phải âm /ch/ thông thường.', 'My sister sings in the choir every Sunday.', NULL, 'Chị tôi hát trong dàn hợp xướng vào mỗi chủ nhật.', '{"wordId":"choir","ukIpa":"/ˈkwaɪə/","usIpa":"/ˈkwaɪr/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"An organised group of people who sing together.","vi":"dàn hợp xướng; đội hợp ca"}],"examples":[{"en":"My sister sings in the choir every Sunday.","vi":"Chị tôi hát trong dàn hợp xướng vào mỗi chủ nhật.","audioKind":"ex"},{"en":"Joining a community choir can reduce loneliness and strengthen social connections among older adults.","vi":"Tham gia một dàn hợp xướng cộng đồng có thể giảm bớt sự cô đơn và củng cố các mối quan hệ xã hội ở người lớn tuổi.","audioKind":"ex2"}],"collocations":[{"en":"join a choir","vi":"gia nhập dàn hợp xướng"},{"en":"church choir","vi":"dàn hợp xướng nhà thờ"},{"en":"choir practice","vi":"buổi tập hợp xướng"}],"wordFamily":["choral (adj.)","chorister (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách phát âm tương tự từ quire, phần đầu không phải âm /ch/ thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_creative', 'en-b1-24', 'creative', '/kriˈeɪtɪv/', 'B1', 'sáng tạo; có tính sáng tạo', 'adj.', 'create (v.), creativity (n.), creatively (adv.), creation (n.)', 'Đồng nghĩa: imaginative, inventive · Trái nghĩa: unimaginative', 'Dùng để miêu tả người có tính sáng tạo hoặc phương pháp mới mẻ; danh từ tương ứng là creativity.', 'My creative sister turned old jars into colourful lamps.', NULL, 'Người chị sáng tạo của tôi đã biến những chiếc lọ cũ thành những chiếc đèn đầy màu sắc.', '{"wordId":"creative","ukIpa":"/kriˈeɪtɪv/","usIpa":"/kriˈeɪtɪv/","cefr":"B1","topic":"arts","senses":[{"pos":"adj.","en":"Able to produce original ideas, or involving imagination.","vi":"sáng tạo; có tính sáng tạo"}],"examples":[{"en":"My creative sister turned old jars into colourful lamps.","vi":"Người chị sáng tạo của tôi đã biến những chiếc lọ cũ thành những chiếc đèn đầy màu sắc.","audioKind":"ex"},{"en":"Schools should encourage creative thinking by allowing students to explore several solutions to the same problem.","vi":"Các nhà trường nên khuyến khích tư duy sáng tạo bằng cách cho phép học sinh khám phá nhiều giải pháp cho cùng một vấn đề.","audioKind":"ex2"}],"collocations":[{"en":"creative thinking","vi":"tư duy sáng tạo"},{"en":"creative writing","vi":"viết sáng tạo"},{"en":"a creative solution","vi":"giải pháp sáng tạo"}],"wordFamily":["create (v.)","creativity (n.)","creatively (adv.)","creation (n.)"],"synonyms":["imaginative","inventive"],"antonyms":["unimaginative"],"tipVi":"Dùng để miêu tả người có tính sáng tạo hoặc phương pháp mới mẻ; danh từ tương ứng là creativity.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scene', 'en-b1-24', 'scene', '/siːn/', 'B1', 'cảnh; phong cảnh; hiện trường; nơi xảy ra sự việc; phân cảnh; cảnh phim', 'n.', 'scenery (n.), scenic (adj.)', NULL, 'scene là danh từ đếm được; trong khi scenery chỉ phong cảnh nói chung và là danh từ không đếm được.', 'The children playing by the lake made a peaceful scene.', NULL, 'Bọn trẻ đang vui đùa bên hồ nước tạo nên một khung cảnh vô cùng yên bình.', '{"wordId":"scene","ukIpa":"/siːn/","usIpa":"/siːn/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"a view or situation that you see","vi":"cảnh; phong cảnh"},{"pos":"n.","en":"the place where an event happens","vi":"hiện trường; nơi xảy ra sự việc"},{"pos":"n.","en":"a short part of a play or film","vi":"phân cảnh; cảnh phim"}],"examples":[{"en":"The children playing by the lake made a peaceful scene.","vi":"Bọn trẻ đang vui đùa bên hồ nước tạo nên một khung cảnh vô cùng yên bình.","audioKind":"ex"},{"en":"The film''s opening scene highlights the challenges faced by families living in crowded urban neighbourhoods.","vi":"Phân cảnh mở đầu của bộ phim làm nổi bật những thách thức mà các gia đình sống trong các khu phố đô thị đông đúc phải đối mặt.","audioKind":"ex2"}],"collocations":[{"en":"a peaceful scene","vi":"một khung cảnh yên bình"},{"en":"at the scene","vi":"có mặt tại hiện trường"},{"en":"opening scene","vi":"cảnh mở đầu"},{"en":"behind the scenes","vi":"ở hậu trường"}],"wordFamily":["scenery (n.)","scenic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"scene là danh từ đếm được; trong khi scenery chỉ phong cảnh nói chung và là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_literature', 'en-b1-24', 'literature', '/ˈlɪtərətʃər/', 'B1', 'văn học; tác phẩm văn học; tài liệu; văn bản nghiên cứu', 'n.', 'literary (adj.)', NULL, 'Thông thường là danh từ không đếm được; khi chỉ nhiều tài liệu cũng không thêm s.', 'My sister studies literature and always recommends wonderful novels.', NULL, 'Chị tôi học ngành văn học và luôn giới thiệu những cuốn tiểu thuyết tuyệt vời.', '{"wordId":"literature","ukIpa":"/ˈlɪtrətʃə/","usIpa":"/ˈlɪtərətʃər/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"Written works valued for their artistic qualities.","vi":"văn học; tác phẩm văn học"},{"pos":"n.","en":"Written material about a particular subject.","vi":"tài liệu; văn bản nghiên cứu"}],"examples":[{"en":"My sister studies literature and always recommends wonderful novels.","vi":"Chị tôi học ngành văn học và luôn giới thiệu những cuốn tiểu thuyết tuyệt vời.","audioKind":"ex"},{"en":"A review of the scientific literature suggests that regular exercise can improve mental health.","vi":"Tổng hợp các tài liệu khoa học cho thấy việc tập thể dục đều đặn có thể cải thiện sức khỏe tinh thần.","audioKind":"ex2"}],"collocations":[{"en":"English literature","vi":"văn học Anh"},{"en":"scientific literature","vi":"tài liệu khoa học"},{"en":"literature review","vi":"tổng quan tài liệu"},{"en":"children''s literature","vi":"văn học thiếu nhi"}],"wordFamily":["literary (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thông thường là danh từ không đếm được; khi chỉ nhiều tài liệu cũng không thêm s.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_architecture', 'en-b1-24', 'architecture', '/ˈɑːrkɪtektʃər/', 'B1', 'kiến trúc học; nghệ thuật kiến trúc; phong cách kiến trúc; cấu trúc hệ thống', 'n.', 'architect (n.), architectural (adj.), architecturally (adv.)', NULL, 'Architecture thường là danh từ không đếm được; architect dùng để chỉ kiến trúc sư.', 'My brother studies architecture and builds tiny house models.', NULL, 'Anh trai tôi học ngành thiết kế kiến trúc và làm những mô hình nhà nhỏ.', '{"wordId":"architecture","ukIpa":"/ˈɑːkɪtektʃə/","usIpa":"/ˈɑːrkɪtektʃər/","cefr":"B1","topic":"arts","senses":[{"pos":"n.","en":"The art and practice of designing buildings.","vi":"kiến trúc học; nghệ thuật kiến trúc"},{"pos":"n.","en":"The style and appearance of buildings.","vi":"phong cách kiến trúc"},{"pos":"n.","en":"The way a computer system or other complex structure is organised.","vi":"cấu trúc hệ thống"}],"examples":[{"en":"My brother studies architecture and builds tiny house models.","vi":"Anh trai tôi học ngành thiết kế kiến trúc và làm những mô hình nhà nhỏ.","audioKind":"ex"},{"en":"Sustainable architecture can reduce energy consumption by making better use of natural light and ventilation.","vi":"Kiến trúc bền vững có thể giảm lượng tiêu thụ năng lượng bằng cách tận dụng tối đa ánh sáng và thông gió tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"modern architecture","vi":"kiến trúc hiện đại"},{"en":"sustainable architecture","vi":"kiến trúc bền vững"},{"en":"software architecture","vi":"kiến trúc phần mềm"}],"wordFamily":["architect (n.)","architectural (adj.)","architecturally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Architecture thường là danh từ không đếm được; architect dùng để chỉ kiến trúc sư.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perform', 'en-b1-24', 'perform', '/pərˈfɔːrm/', 'B1', 'biểu diễn; trình diễn (trước khán giả qua ca hát, diễn xuất hoặc chơi nhạc); thực hiện; thi hành (một nhiệm vụ, hành động hoặc nghĩa vụ); thể hiện; hoạt động; vận hành (đạt kết quả theo một cách thức cụ thể)', 'v.', 'performance (n.), performer (n.)', 'Đồng nghĩa: carry out', 'Từ này vừa có thể chỉ hoạt động biểu diễn nghệ thuật, vừa đi với các từ như task, duty để chỉ việc thực hiện.', 'Our choir will perform at the community centre tonight.', NULL, 'Dàn hợp xướng của chúng tôi sẽ biểu diễn tại trung tâm cộng đồng vào tối nay.', '{"wordId":"perform","ukIpa":"/pəˈfɔːm/","usIpa":"/pərˈfɔːrm/","cefr":"B1","topic":"arts","senses":[{"pos":"v.","en":"to entertain an audience by acting, singing, or playing music","vi":"biểu diễn; trình diễn (trước khán giả qua ca hát, diễn xuất hoặc chơi nhạc)"},{"pos":"v.","en":"to carry out a task, action, or duty","vi":"thực hiện; thi hành (một nhiệm vụ, hành động hoặc nghĩa vụ)"},{"pos":"v.","en":"to work or achieve results in a particular way","vi":"thể hiện; hoạt động; vận hành (đạt kết quả theo một cách thức cụ thể)"}],"examples":[{"en":"Our choir will perform at the community centre tonight.","vi":"Dàn hợp xướng của chúng tôi sẽ biểu diễn tại trung tâm cộng đồng vào tối nay.","audioKind":"ex"},{"en":"Students often perform better academically when schools provide regular feedback and access to individual support.","vi":"Học sinh thường có kết quả học tập tốt hơn khi nhà trường cung cấp phản hồi thường xuyên và hỗ trợ cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"perform on stage","vi":"biểu diễn trên sân khấu"},{"en":"perform a task","vi":"thực hiện nhiệm vụ"},{"en":"perform well","vi":"thể hiện tốt; làm tốt"},{"en":"perform surgery","vi":"tiến hành phẫu thuật"}],"wordFamily":["performance (n.)","performer (n.)"],"synonyms":["carry out"],"antonyms":[],"tipVi":"Từ này vừa có thể chỉ hoạt động biểu diễn nghệ thuật, vừa đi với các từ như task, duty để chỉ việc thực hiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_24_1', 'en-b1-24', 'Cách dùng “fiction” (n.) — truyện hư cấu; tiểu thuyết', 'science fiction  ·  historical fiction  ·  a work of fiction', 'Khi chỉ thể loại tiểu thuyết nói chung thì không đếm được; một cuốn tiểu thuyết cụ thể có thể dùng a work of fiction.', 'Họ từ (Word Family): fictional (adj.), fictionalise (v.) | Trái nghĩa: non-fiction', '[{"hanzi":"My sister reads fiction on the train every morning.","pinyin":"","meaning":"Chị tôi đọc tiểu thuyết trên tàu vào mỗi buổi sáng."},{"hanzi":"Reading fiction can help young people understand unfamiliar perspectives and develop greater empathy for others.","pinyin":"","meaning":"Việc đọc tiểu thuyết có thể giúp người trẻ hiểu được những góc nhìn xa lạ và nuôi dưỡng sự đồng cảm lớn hơn đối với người khác."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_24_2', 'en-b1-24', 'Cách dùng “thriller” (n.) — truyện trinh thám ly kỳ; phim kinh dị ly kỳ', 'a crime thriller  ·  a psychological thriller  ·  a political thriller', 'thriller tập trung vào yếu tố hồi hộp và căng thẳng, không đồng nghĩa với phim kinh dị hù dọa thông thường (horror).', 'Họ từ (Word Family): thrill (n.), thrill (v.), thrilling (adj.), thrilled (adj.)', '[{"hanzi":"We watched a thriller and kept guessing the ending.","pinyin":"","meaning":"Chúng tôi đã xem một bộ phim ly kỳ và liên tục đoán xem kết cục sẽ ra sao."},{"hanzi":"A well-made thriller can encourage audiences to consider ethical questions while maintaining a strong sense of suspense.","pinyin":"","meaning":"Một bộ phim ly kỳ được đầu tư kỹ lưỡng có thể khuyến khích khán giả suy ngẫm về các vấn đề đạo đức trong khi vẫn duy trì được sự hồi hộp mãnh liệt."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_24_3', 'en-b1-24', 'Cách dùng “original” (adj.) — ban đầu; nguyên bản', 'original plan  ·  original design  ·  original research', 'Có thể mang nghĩa là nguyên bản từ ban đầu, hoặc mang nghĩa sáng tạo độc đáo; cần phân tích dựa trên ngữ cảnh.', 'Họ từ (Word Family): originally (adv.), originality (n.), origin (n.), originate (v.)', '[{"hanzi":"The kitchen still has its original wooden floor.","pinyin":"","meaning":"Căn bếp vẫn giữ nguyên vẹn sàn gỗ ban đầu của nó."},{"hanzi":"Schools should encourage original thinking rather than reward students only for repeating information from textbooks.","pinyin":"","meaning":"Nhà trường nên khuyến khích tư duy sáng tạo thay vì chỉ thưởng cho học sinh vì việc lặp lại kiến thức từ sách giáo khoa."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_24_4', 'en-b1-24', 'Cách dùng “perform” (v.) — biểu diễn; trình diễn (trước khán giả qua ca hát, diễn xuất hoặc chơi nhạc)', 'perform on stage  ·  perform a task  ·  perform well', 'Từ này vừa có thể chỉ hoạt động biểu diễn nghệ thuật, vừa đi với các từ như task, duty để chỉ việc thực hiện.', 'Họ từ (Word Family): performance (n.), performer (n.) | Đồng nghĩa: carry out', '[{"hanzi":"Our choir will perform at the community centre tonight.","pinyin":"","meaning":"Dàn hợp xướng của chúng tôi sẽ biểu diễn tại trung tâm cộng đồng vào tối nay."},{"hanzi":"Students often perform better academically when schools provide regular feedback and access to individual support.","pinyin":"","meaning":"Học sinh thường có kết quả học tập tốt hơn khi nhà trường cung cấp phản hồi thường xuyên và hỗ trợ cá nhân."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_24_1', 'en-b1-24', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
