INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_24_1_2', 'ten_b1_24_1', 'decoration', 'She hung a bright paper decoration above the kitchen table.', 'She hung a bright paper decoration above the kitchen table.', '/ˌdekəˈreɪʃən/', 'Cô ấy treo một món đồ trang trí bằng giấy rực rỡ phía trên bàn bếp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_24_1_3', 'ten_b1_24_1', 'studio', 'The artist invited us into her bright upstairs studio.', 'The artist invited us into her bright upstairs studio.', '/ˈstuːdioʊ/', 'Nữ nghệ sĩ mời chúng tôi vào xưởng vẽ ngập tràn ánh sáng của cô ấy ở lầu trên.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_24_1_4', 'ten_b1_24_1', 'photography', 'My sister enjoys photography and carries her camera everywhere.', 'My sister enjoys photography and carries her camera everywhere.', '/fəˈtɑːɡrəfi/', 'Chị gái tôi thích chụp ảnh và mang theo máy ảnh đi bất cứ đâu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_24_1_5', 'ten_b1_24_1', 'fiction', 'My sister reads fiction on the train every morning.', 'My sister reads fiction on the train every morning.', '/ˈfɪkʃən/', 'Chị tôi đọc tiểu thuyết trên tàu vào mỗi buổi sáng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_24_1_6', 'ten_b1_24_1', 'orchestra', 'The orchestra began playing as the lights dimmed.', 'The orchestra began playing as the lights dimmed.', '/ˈɔːrkɪstrə/', 'Dàn nhạc bắt đầu chơi khi đèn mờ dần.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_24_1_7', 'ten_b1_24_1', 'talented', 'My talented cousin painted this beautiful picture of our garden.', 'My talented cousin painted this beautiful picture of our garden.', '/ˈtæləntɪd/', 'Người anh em họ tài năng của tôi đã vẽ bức tranh đẹp này về khu vườn của chúng tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_24_1_8', 'ten_b1_24_1', 'stylish', 'Her stylish green jacket looked great with plain trousers.', 'Her stylish green jacket looked great with plain trousers.', '/ˈstaɪlɪʃ/', 'Chiếc áo khoác xanh sành điệu của cô ấy trông rất hợp với chiếc quần trơn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_24_1_1', 'en-b1-24', 'ten_b1_24_1', 'listening', 'listening', 'We watched a thriller and kept guessing the ending.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chị tôi hát trong dàn hợp xướng vào mỗi chủ nhật.","Chúng tôi đã xem một bộ phim ly kỳ và liên tục đoán xem kết cục sẽ ra sao.","Cậu em họ nhỏ của tôi đã hóa trang thành một hồn ma để đi dự tiệc.","Chị gái tôi thích chụp ảnh và mang theo máy ảnh đi bất cứ đâu."]'::jsonb, 1, 'We watched a thriller and kept guessing the ending. → Chúng tôi đã xem một bộ phim ly kỳ và liên tục đoán xem kết cục sẽ ra sao.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_24_1_2', 'en-b1-24', 'ten_b1_24_1', 'listening', 'listening', 'She hung a bright paper decoration above the kitchen table.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Dàn hợp xướng của chúng tôi sẽ biểu diễn tại trung tâm cộng đồng vào tối nay.","Chị tôi học ngành văn học và luôn giới thiệu những cuốn tiểu thuyết tuyệt vời.","Cô ấy treo một món đồ trang trí bằng giấy rực rỡ phía trên bàn bếp.","Khách sạn cung cấp các tiết mục biểu diễn giải trí trực tiếp bên hồ bơi mỗi buổi tối."]'::jsonb, 2, 'She hung a bright paper decoration above the kitchen table. → Cô ấy treo một món đồ trang trí bằng giấy rực rỡ phía trên bàn bếp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_24_1_3', 'en-b1-24', 'ten_b1_24_1', 'listening', 'listening', 'The artist invited us into her bright upstairs studio.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nữ nghệ sĩ mời chúng tôi vào xưởng vẽ ngập tràn ánh sáng của cô ấy ở lầu trên.","Tôi đang đọc cuốn tiểu sử về một nhà thám hiểm trước khi đi ngủ.","Anh trai tôi học ngành thiết kế kiến trúc và làm những mô hình nhà nhỏ.","Cô ấy treo một món đồ trang trí bằng giấy rực rỡ phía trên bàn bếp."]'::jsonb, 0, 'The artist invited us into her bright upstairs studio. → Nữ nghệ sĩ mời chúng tôi vào xưởng vẽ ngập tràn ánh sáng của cô ấy ở lầu trên.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_24_2', 'en-b1-24', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_24_2_1', 'ten_b1_24_2', 'thriller', 'A well-made thriller can encourage audiences to consider ethical questions while maintaining a strong sense of suspense.', 'A well-made thriller can encourage audiences to consider ethical questions while maintaining a strong sense of suspense.', '/ˈθrɪlər/', 'Một bộ phim ly kỳ được đầu tư kỹ lưỡng có thể khuyến khích khán giả suy ngẫm về các vấn đề đạo đức trong khi vẫn duy trì được sự hồi hộp mãnh liệt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_24_2_2', 'ten_b1_24_2', 'decoration', 'The decoration of public libraries can create welcoming spaces that encourage residents to spend more time reading.', 'The decoration of public libraries can create welcoming spaces that encourage residents to spend more time reading.', '/ˌdekəˈreɪʃən/', 'Việc trang hoàng các thư viện công cộng có thể tạo ra những không gian thân thiện, khuyến khích người dân dành nhiều thời gian đọc sách hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_24_2_3', 'ten_b1_24_2', 'studio', 'Public funding for affordable studio spaces can help emerging artists contribute to a city''s cultural life.', 'Public funding for affordable studio spaces can help emerging artists contribute to a city''s cultural life.', '/ˈstuːdioʊ/', 'Kinh phí công cộng dành cho các không gian xưởng nghệ thuật giá rẻ có thể giúp các nghệ sĩ mới nổi đóng góp vào đời sống văn hóa của thành phố.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_24_2_4', 'ten_b1_24_2', 'photography', 'Digital photography allows researchers to document environmental changes and share visual evidence with a wider audience.', 'Digital photography allows researchers to document environmental changes and share visual evidence with a wider audience.', '/fəˈtɑːɡrəfi/', 'Nhiếp ảnh kỹ thuật số cho phép các nhà nghiên cứu ghi lại những thay đổi của môi trường và chia sẻ bằng chứng trực quan với nhiều đối tượng hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_24_2_5', 'ten_b1_24_2', 'fiction', 'Reading fiction can help young people understand unfamiliar perspectives and develop greater empathy for others.', 'Reading fiction can help young people understand unfamiliar perspectives and develop greater empathy for others.', '/ˈfɪkʃən/', 'Việc đọc tiểu thuyết có thể giúp người trẻ hiểu được những góc nhìn xa lạ và nuôi dưỡng sự đồng cảm lớn hơn đối với người khác.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_24_2_6', 'ten_b1_24_2', 'orchestra', 'Public funding helps the local orchestra offer affordable concerts and introduce classical music to younger audiences.', 'Public funding helps the local orchestra offer affordable concerts and introduce classical music to younger audiences.', '/ˈɔːrkɪstrə/', 'Sự tài trợ công giúp dàn nhạc địa phương tổ chức các buổi hòa nhạc với giá vé phải chăng và đưa âm nhạc cổ điển đến gần hơn với khán giả trẻ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_24_2_1', 'en-b1-24', 'ten_b1_24_2', 'listening', 'listening', 'A well-made thriller can encourage audiences to consider ethical questions while maintaining a strong sense of suspense.', NULL, 'Trong câu vừa nghe, từ “thriller” mang nghĩa nào sau đây?', '["truyện trinh thám ly kỳ; phim kinh dị ly kỳ","dân số; toàn bộ cư dân","động tác chống đẩy; hít đất","con dơi (thú bay hoạt động chủ yếu về đêm)"]'::jsonb, 0, '“thriller” (/ˈθrɪlər/): truyện trinh thám ly kỳ; phim kinh dị ly kỳ. Câu đầy đủ: A well-made thriller can encourage audiences to consider ethical questions while maintaining a strong sense of suspense.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_24_2_2', 'en-b1-24', 'ten_b1_24_2', 'listening', 'listening', 'The decoration of public libraries can create welcoming spaces that encourage residents to spend more time reading.', NULL, 'Trong câu vừa nghe, từ “decoration” mang nghĩa nào sau đây?', '["hò reo; cổ vũ","giới thiệu; gợi ý","đồ trang trí","nhai; cắn"]'::jsonb, 2, '“decoration” (/ˌdekəˈreɪʃən/): đồ trang trí. Câu đầy đủ: The decoration of public libraries can create welcoming spaces that encourage residents to spend more time reading.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
