INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_2', 'en-b1-24', NULL, 'comprehensive_test', 'listening', 'She hung a bright paper decoration above the kitchen table.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chị tôi học ngành văn học và luôn giới thiệu những cuốn tiểu thuyết tuyệt vời.","Cô ấy treo một món đồ trang trí bằng giấy rực rỡ phía trên bàn bếp.","Tôi đang đọc cuốn tiểu sử về một nhà thám hiểm trước khi đi ngủ.","Căn bếp vẫn giữ nguyên vẹn sàn gỗ ban đầu của nó."]'::jsonb, 1, 'She hung a bright paper decoration above the kitchen table. → Cô ấy treo một món đồ trang trí bằng giấy rực rỡ phía trên bàn bếp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
