INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_4', 'en-b1-24', NULL, 'comprehensive_test', 'listening', 'My sister enjoys photography and carries her camera everywhere.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc áo khoác xanh sành điệu của cô ấy trông rất hợp với chiếc quần trơn.","Dàn nhạc bắt đầu chơi khi đèn mờ dần.","Chị gái tôi thích chụp ảnh và mang theo máy ảnh đi bất cứ đâu.","Chị tôi hát trong dàn hợp xướng vào mỗi chủ nhật."]'::jsonb, 2, 'My sister enjoys photography and carries her camera everywhere. → Chị gái tôi thích chụp ảnh và mang theo máy ảnh đi bất cứ đâu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_5', 'en-b1-24', NULL, 'comprehensive_test', 'listening', 'fiction', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự thoải mái; sự tiện nghi","truyện hư cấu; tiểu thuyết","đánh giá; phán đoán","phép trừ"]'::jsonb, 1, 'fiction (/ˈfɪkʃən/) → truyện hư cấu; tiểu thuyết; điều bịa đặt; chuyện hoang đường', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_6', 'en-b1-24', NULL, 'comprehensive_test', 'listening', 'The orchestra began playing as the lights dimmed.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đang đọc cuốn tiểu sử về một nhà thám hiểm trước khi đi ngủ.","Nữ nghệ sĩ mời chúng tôi vào xưởng vẽ ngập tràn ánh sáng của cô ấy ở lầu trên.","Dàn nhạc bắt đầu chơi khi đèn mờ dần.","Khách sạn cung cấp các tiết mục biểu diễn giải trí trực tiếp bên hồ bơi mỗi buổi tối."]'::jsonb, 2, 'The orchestra began playing as the lights dimmed. → Dàn nhạc bắt đầu chơi khi đèn mờ dần.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_7', 'en-b1-24', NULL, 'comprehensive_test', 'listening', 'talented', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ở trong nhà, vào trong nhà (bên trong một tòa nhà)","có năng khiếu; có tài","truyện; chuyện cổ tích; chuyện truyền thuyết","cá ngừ; thịt cá ngừ"]'::jsonb, 1, 'talented (/ˈtæləntɪd/) → có năng khiếu; có tài', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_8', 'en-b1-24', NULL, 'comprehensive_test', 'listening', 'Her stylish green jacket looked great with plain trousers.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cậu em họ nhỏ của tôi đã hóa trang thành một hồn ma để đi dự tiệc.","Chiếc áo khoác xanh sành điệu của cô ấy trông rất hợp với chiếc quần trơn.","Lena mặc trang phục hình con bướm trong vở kịch của trường.","Dàn nhạc bắt đầu chơi khi đèn mờ dần."]'::jsonb, 1, 'Her stylish green jacket looked great with plain trousers. → Chiếc áo khoác xanh sành điệu của cô ấy trông rất hợp với chiếc quần trơn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_9', 'en-b1-24', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Stories about imagined people and events.”?', '["novel","fiction","drummer","ballet"]'::jsonb, 1, 'fiction (/ˈfɪkʃən/) → truyện hư cấu; tiểu thuyết', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
