INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_18', 'en-b1-24', NULL, 'comprehensive_test', 'reading', NULL, 'A well-made thriller can encourage audiences to consider ethical questions while maintaining a strong sense of suspense.', 'Dựa vào câu trên, từ “thriller” có nghĩa phù hợp nhất là gì?', '["lương thực; ngũ cốc","thác nước","truyện trinh thám ly kỳ; phim kinh dị ly kỳ","người ủng hộ; tín đồ"]'::jsonb, 2, 'thriller: truyện trinh thám ly kỳ; phim kinh dị ly kỳ. Dịch cả câu: Một bộ phim ly kỳ được đầu tư kỹ lưỡng có thể khuyến khích khán giả suy ngẫm về các vấn đề đạo đức trong khi vẫn duy trì được sự hồi hộp mãnh liệt.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_19', 'en-b1-24', NULL, 'comprehensive_test', 'reading', NULL, 'The decoration of public libraries can create welcoming spaces that encourage residents to spend more time reading.', 'Dựa vào câu trên, từ “decoration” có nghĩa phù hợp nhất là gì?', '["xác nhận; chứng thực","đồ trang trí","tự phục vụ","kinh Thánh"]'::jsonb, 1, 'decoration: đồ trang trí; sự trang trí; cách trang hoàng; huân chương; huy chương. Dịch cả câu: Việc trang hoàng các thư viện công cộng có thể tạo ra những không gian thân thiện, khuyến khích người dân dành nhiều thời gian đọc sách hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_20', 'en-b1-24', NULL, 'comprehensive_test', 'reading', NULL, 'Public funding for affordable studio spaces can help emerging artists contribute to a city''s cultural life.', 'Dựa vào câu trên, từ “studio” có nghĩa phù hợp nhất là gì?', '["thuế; tiền thuế","bao gồm; đòi hỏi; liên quan đến","phòng thu; xưởng nghệ thuật; phim trường","áp lực (tinh thần); sự thúc ép"]'::jsonb, 2, 'studio: phòng thu; xưởng nghệ thuật; phim trường; hãng phim; căn hộ studio (căn hộ nhỏ một phòng). Dịch cả câu: Kinh phí công cộng dành cho các không gian xưởng nghệ thuật giá rẻ có thể giúp các nghệ sĩ mới nổi đóng góp vào đời sống văn hóa của thành phố.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_21', 'en-b1-24', NULL, 'comprehensive_test', 'reading', NULL, 'Digital photography allows researchers to document environmental changes and share visual evidence with a wider audience.', 'Dựa vào câu trên, từ “photography” có nghĩa phù hợp nhất là gì?', '["ngón tay cái","thuyết phục; khuyên nhủ","nghệ thuật nhiếp ảnh; kỹ thuật chụp ảnh","thị lực; thị giác"]'::jsonb, 2, 'photography: nghệ thuật nhiếp ảnh; kỹ thuật chụp ảnh. Dịch cả câu: Nhiếp ảnh kỹ thuật số cho phép các nhà nghiên cứu ghi lại những thay đổi của môi trường và chia sẻ bằng chứng trực quan với nhiều đối tượng hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_22', 'en-b1-24', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “văn học; tác phẩm văn học”', '["literature","luxury","telescope","technical"]'::jsonb, 0, 'văn học; tác phẩm văn học → literature (/ˈlɪtərətʃər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_23', 'en-b1-24', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kiến trúc học; nghệ thuật kiến trúc”', '["heel","achieve","cracker","architecture"]'::jsonb, 3, 'kiến trúc học; nghệ thuật kiến trúc → architecture (/ˈɑːrkɪtektʃər/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_24_24', 'en-b1-24', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “biểu diễn; trình diễn (trước khán giả qua ca hát, diễn xuất hoặc chơi nhạc)”', '["perform","fault","symptom","electronic"]'::jsonb, 0, 'biểu diễn; trình diễn (trước khán giả qua ca hát, diễn xuất hoặc chơi nhạc) → perform (/pərˈfɔːrm/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-25', 'en', 'Bài 25: Tư duy & Nhận thức (1) - CEFR B1', 'CEFR B1', 'B1 · Tư duy', '26 từ vựng Tiếng Anh CEFR B1 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3025, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_solution', 'en-b1-25', 'solution', '/səˈluːʃən/', 'B1', 'giải pháp; cách giải quyết; dung dịch', 'n.', 'solve (v.), soluble (adj.), solubility (n.)', 'Đồng nghĩa: answer, remedy', 'Cụm chỉ "giải pháp cho..." dùng solution to, không dùng solution of.', 'Adding another shelf was a simple solution to the clutter.', NULL, 'Việc lắp thêm một chiếc kệ là một giải pháp đơn giản để khắc phục tình trạng bừa bộn.', '{"wordId":"solution","ukIpa":"/səˈluːʃən/","usIpa":"/səˈluːʃən/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"a way to solve a problem or answer a question","vi":"giải pháp; cách giải quyết"},{"pos":"n.","en":"a liquid containing a substance dissolved in it","vi":"dung dịch"}],"examples":[{"en":"Adding another shelf was a simple solution to the clutter.","vi":"Việc lắp thêm một chiếc kệ là một giải pháp đơn giản để khắc phục tình trạng bừa bộn.","audioKind":"ex"},{"en":"Investment in renewable energy offers a long-term solution to the environmental problems caused by fossil fuels.","vi":"Việc đầu tư vào năng lượng tái tạo cung cấp một giải pháp lâu dài cho các vấn đề môi trường do nhiên liệu hóa thạch gây ra.","audioKind":"ex2"}],"collocations":[{"en":"a solution to a problem","vi":"giải pháp cho một vấn đề"},{"en":"find a solution","vi":"tìm ra giải pháp"},{"en":"a practical solution","vi":"giải pháp thiết thực"},{"en":"a salt solution","vi":"dung dịch muối"}],"wordFamily":["solve (v.)","soluble (adj.)","solubility (n.)"],"synonyms":["answer","remedy"],"antonyms":[],"tipVi":"Cụm chỉ \"giải pháp cho...\" dùng solution to, không dùng solution of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_therefore', 'en-b1-25', 'therefore', '/ˈðerfɔːr/', 'B1', 'vì vậy; do đó; cho nên', 'adv.', NULL, 'Đồng nghĩa: consequently, thus, hence', 'Là trạng từ, không thể dùng dấu phẩy đơn thuần để nối hai câu hoàn chỉnh.', 'The shop was closed; therefore, we went home empty-handed.', NULL, 'Cửa hàng đã đóng cửa; vì thế, chúng tôi đành tay trắng đi về.', '{"wordId":"therefore","ukIpa":"/ˈðeəfɔː/","usIpa":"/ˈðerfɔːr/","cefr":"B1","topic":"thinking","senses":[{"pos":"adv.","en":"as a result of what has just been stated","vi":"vì vậy; do đó; cho nên"}],"examples":[{"en":"The shop was closed; therefore, we went home empty-handed.","vi":"Cửa hàng đã đóng cửa; vì thế, chúng tôi đành tay trắng đi về.","audioKind":"ex"},{"en":"Public parks encourage physical activity and social interaction; therefore, cities should invest in maintaining accessible green spaces.","vi":"Các công viên công cộng thúc đẩy hoạt động thể chất và giao lưu xã hội; do đó, các thành phố nên đầu tư duy trì các không gian xanh dễ tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"therefore conclude","vi":"do đó kết luận"},{"en":"therefore necessary","vi":"do đó cần thiết"},{"en":"and therefore","vi":"và vì thế"}],"wordFamily":[],"synonyms":["consequently","thus","hence"],"antonyms":[],"tipVi":"Là trạng từ, không thể dùng dấu phẩy đơn thuần để nối hai câu hoàn chỉnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_claim', 'en-b1-25', 'claim', '/kleɪm/', 'B1', 'tuyên bố; quả quyết; đòi; nhận; yêu cầu; sự tuyên bố; đơn yêu cầu bồi thường', 'v.', 'claimant (n.), unclaimed (adj.)', 'Đồng nghĩa: assert, maintain', 'claim nhấn mạnh ý kiến hoặc lời nói của một cá nhân, chưa hẳn đã được chứng minh là đúng sự thật.', 'He claims he can fix my bike by lunchtime.', NULL, 'Anh ấy tuyên bố có thể sửa chiếc xe đạp của tôi trước giờ ăn trưa.', '{"wordId":"claim","ukIpa":"/kleɪm/","usIpa":"/kleɪm/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"to say something is true, often without providing proof","vi":"tuyên bố; quả quyết"},{"pos":"v.","en":"to ask for or take something you believe is yours","vi":"đòi; nhận; yêu cầu"},{"pos":"n.","en":"a statement of truth or a request for something owed","vi":"sự tuyên bố; đơn yêu cầu bồi thường"}],"examples":[{"en":"He claims he can fix my bike by lunchtime.","vi":"Anh ấy tuyên bố có thể sửa chiếc xe đạp của tôi trước giờ ăn trưa.","audioKind":"ex"},{"en":"Some researchers claim that access to green spaces can improve mental health and strengthen community relationships.","vi":"Một số nhà nghiên cứu cho rằng việc tiếp cận không gian xanh có thể cải thiện sức khỏe tinh thần và tăng cường các mối quan hệ cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"claim that","vi":"tuyên bố rằng"},{"en":"claim responsibility for","vi":"nhận trách nhiệm về"},{"en":"claim compensation","vi":"đòi bồi thường"},{"en":"make a claim","vi":"đưa ra yêu cầu hoặc khiếu nại"}],"wordFamily":["claimant (n.)","unclaimed (adj.)"],"synonyms":["assert","maintain"],"antonyms":[],"tipVi":"claim nhấn mạnh ý kiến hoặc lời nói của một cá nhân, chưa hẳn đã được chứng minh là đúng sự thật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intelligent', 'en-b1-25', 'intelligent', '/ɪnˈtelɪdʒənt/', 'B1', 'thông minh; sáng suốt; có khả năng hiểu biết tốt; có tính thông minh nhân tạo; tự động xử lý thông tin', 'adj.', 'intelligence (n.), intelligently (adv.)', 'Đồng nghĩa: clever, smart, bright · Trái nghĩa: unintelligent', 'intelligent chỉ người hoặc vật thông minh; intelligible chỉ cái gì đó có thể hiểu được.', 'Our intelligent puppy quickly learned how to open doors.', NULL, 'Chú cún thông minh của chúng tôi đã nhanh chóng học được cách mở cửa.', '{"wordId":"intelligent","ukIpa":"/ɪnˈtelɪdʒənt/","usIpa":"/ɪnˈtelɪdʒənt/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Able to learn, understand, and think well.","vi":"thông minh; sáng suốt; có khả năng hiểu biết tốt"},{"pos":"adj.","en":"Able to process information and respond automatically in useful ways.","vi":"có tính thông minh nhân tạo; tự động xử lý thông tin"}],"examples":[{"en":"Our intelligent puppy quickly learned how to open doors.","vi":"Chú cún thông minh của chúng tôi đã nhanh chóng học được cách mở cửa.","audioKind":"ex"},{"en":"Intelligent transport systems can reduce congestion by adjusting traffic signals in response to changing road conditions.","vi":"Các hệ thống giao thông thông minh có thể làm giảm tình trạng tắc nghẽn bằng cách điều chỉnh tín hiệu giao thông để đáp ứng các điều kiện đường sá thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"highly intelligent","vi":"rất thông minh"},{"en":"intelligent systems","vi":"hệ thống thông minh"},{"en":"intelligent decision","vi":"quyết định sáng suốt"}],"wordFamily":["intelligence (n.)","intelligently (adv.)"],"synonyms":["clever","smart","bright"],"antonyms":["unintelligent"],"tipVi":"intelligent chỉ người hoặc vật thông minh; intelligible chỉ cái gì đó có thể hiểu được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_concentrate', 'en-b1-25', 'concentrate', '/ˈkɑːnsntreɪt/', 'B1', 'tập trung (tư tưởng, sự chú ý); tập trung; dồn (nguồn lực, nỗ lực vào đâu); chất cô đặc; dung dịch đậm đặc', 'v.', 'concentration (n.), concentrated (adj.)', 'Đồng nghĩa: focus', 'Sau concentrate on đi với danh từ hoặc danh động từ, mang nghĩa là tập trung vào cái gì.', 'I cannot concentrate with the television playing so loudly.', NULL, 'Tôi không thể tập trung khi tivi bật tiếng quá lớn.', '{"wordId":"concentrate","ukIpa":"/ˈkɒnsntreɪt/","usIpa":"/ˈkɑːnsntreɪt/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"To give all your attention to a particular task.","vi":"tập trung (tư tưởng, sự chú ý)"},{"pos":"v.","en":"To bring things together in one place or direct efforts there.","vi":"tập trung; dồn (nguồn lực, nỗ lực vào đâu)"},{"pos":"n.","en":"A substance made stronger by removing water or other material.","vi":"chất cô đặc; dung dịch đậm đặc"}],"examples":[{"en":"I cannot concentrate with the television playing so loudly.","vi":"Tôi không thể tập trung khi tivi bật tiếng quá lớn.","audioKind":"ex"},{"en":"Governments should concentrate resources on preventive healthcare to reduce pressure on hospitals in the long term.","vi":"Chính phủ nên tập trung nguồn lực vào y tế dự phòng nhằm giảm bớt áp lực cho các bệnh viện về lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"concentrate on a task","vi":"tập trung vào một nhiệm vụ"},{"en":"concentrate resources on","vi":"tập trung nguồn lực vào"},{"en":"fruit juice concentrate","vi":"nước trái cây cô đặc"}],"wordFamily":["concentration (n.)","concentrated (adj.)"],"synonyms":["focus"],"antonyms":[],"tipVi":"Sau concentrate on đi với danh từ hoặc danh động từ, mang nghĩa là tập trung vào cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_foolish', 'en-b1-25', 'foolish', '/ˈfuːlɪʃ/', 'B1', 'ngu ngốc; dại dột; kém khôn ngoan', 'adj.', 'fool (n.), foolishly (adv.), foolishness (n.)', 'Đồng nghĩa: silly, unwise · Trái nghĩa: wise, sensible', 'Thường dùng cấu trúc It is foolish to do để diễn đạt việc làm gì đó là không khôn ngoan.', 'It was foolish to leave my umbrella at home.', NULL, 'Thật dại dột khi để quên ô ở nhà.', '{"wordId":"foolish","ukIpa":"/ˈfuːlɪʃ/","usIpa":"/ˈfuːlɪʃ/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Showing poor judgement or a lack of good sense.","vi":"ngu ngốc; dại dột; kém khôn ngoan"}],"examples":[{"en":"It was foolish to leave my umbrella at home.","vi":"Thật dại dột khi để quên ô ở nhà.","audioKind":"ex"},{"en":"It would be foolish to expand road networks without considering their long-term effects on air quality.","vi":"Thật kém khôn ngoan nếu mở rộng mạng lưới giao thông mà không cân nhắc tác động lâu dài của chúng đối với chất lượng không khí.","audioKind":"ex2"}],"collocations":[{"en":"a foolish mistake","vi":"một sai lầm ngớ ngẩn"},{"en":"feel foolish","vi":"cảm thấy mình thật ngốc nghếch"},{"en":"foolish to assume","vi":"thật dại dột khi mặc định rằng"}],"wordFamily":["fool (n.)","foolishly (adv.)","foolishness (n.)"],"synonyms":["silly","unwise"],"antonyms":["wise","sensible"],"tipVi":"Thường dùng cấu trúc It is foolish to do để diễn đạt việc làm gì đó là không khôn ngoan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_argument', 'en-b1-25', 'argument', '/ˈɑːrɡjəmənt/', 'B1', 'cuộc cãi vã; sự tranh cãi; lập luận; luận điểm', 'n.', 'argue (v.), argumentative (adj.)', NULL, 'Tranh cãi thường đi với with hoặc about; ủng hộ quan điểm nào dùng argument for.', 'We had an argument about whose turn it was.', NULL, 'Chúng tôi đã cãi nhau xem đến lượt ai rửa bát.', '{"wordId":"argument","ukIpa":"/ˈɑːɡjəmənt/","usIpa":"/ˈɑːrɡjəmənt/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"An angry disagreement between people.","vi":"cuộc cãi vã; sự tranh cãi"},{"pos":"n.","en":"A reason or set of reasons supporting an opinion.","vi":"lập luận; luận điểm"}],"examples":[{"en":"We had an argument about whose turn it was.","vi":"Chúng tôi đã cãi nhau xem đến lượt ai rửa bát.","audioKind":"ex"},{"en":"The strongest argument for public transport investment is its potential to reduce urban air pollution.","vi":"Lập luận vững chắc nhất cho việc đầu tư vào giao thông công cộng là tiềm năng giảm thiểu ô nhiễm không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"have an argument","vi":"cãi nhau"},{"en":"a convincing argument","vi":"lập luận thuyết phục"},{"en":"an argument for","vi":"lập luận ủng hộ"},{"en":"an argument against","vi":"lập luận phản đối"}],"wordFamily":["argue (v.)","argumentative (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tranh cãi thường đi với with hoặc about; ủng hộ quan điểm nào dùng argument for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_error', 'en-b1-25', 'error', '/ˈerər/', 'B1', 'lỗi; sai sót; sai số; độ lệch', 'n.', 'err (v.), erroneous (adj.), erroneously (adv.)', 'Đồng nghĩa: mistake', 'Từ error mang tính trang trọng hơn mistake, thường dùng trong các vấn đề kỹ thuật, tính toán hoặc phán đoán.', 'An error in the booking left us without seats.', NULL, 'Một lỗi trong khâu đặt phòng đã khiến chúng tôi không có chỗ ngồi.', '{"wordId":"error","ukIpa":"/ˈerə/","usIpa":"/ˈerər/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"something incorrect in an action, calculation, or judgement","vi":"lỗi; sai sót"},{"pos":"n.","en":"the difference between a measured value and the true value","vi":"sai số; độ lệch"}],"examples":[{"en":"An error in the booking left us without seats.","vi":"Một lỗi trong khâu đặt phòng đã khiến chúng tôi không có chỗ ngồi.","audioKind":"ex"},{"en":"Researchers should check their calculations carefully, as a minor error can significantly affect the final conclusions.","vi":"Các nhà nghiên cứu nên kiểm tra kỹ các phép tính của họ, vì một sai sót nhỏ cũng có thể ảnh hưởng lớn đến kết luận cuối cùng.","audioKind":"ex2"}],"collocations":[{"en":"make an error","vi":"mắc lỗi"},{"en":"human error","vi":"sai sót do con người"},{"en":"a margin of error","vi":"khoảng sai số cho phép"},{"en":"trial and error","vi":"phương pháp thử và sai"}],"wordFamily":["err (v.)","erroneous (adj.)","erroneously (adv.)"],"synonyms":["mistake"],"antonyms":[],"tipVi":"Từ error mang tính trang trọng hơn mistake, thường dùng trong các vấn đề kỹ thuật, tính toán hoặc phán đoán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_understanding', 'en-b1-25', 'understanding', '/ˌʌndərˈstændɪŋ/', 'B1', 'sự hiểu biết; sự thông cảm; thấu hiểu; biết thông cảm; sự thỏa thuận ngầm; sự đồng thuận', 'n.', 'understand (v.), understandable (adj.), understandably (adv.), misunderstanding (n.)', 'Đồng nghĩa: comprehension, sympathy · Trái nghĩa: misunderstanding', 'Biểu thị "đối với sự hiểu biết" dùng understanding of.', 'Thanks for your understanding when I arrived late yesterday.', NULL, 'Cảm ơn bạn đã thông cảm khi tôi đến muộn vào ngày hôm qua.', '{"wordId":"understanding","ukIpa":"/ˌʌndəˈstændɪŋ/","usIpa":"/ˌʌndərˈstændɪŋ/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"Knowledge of something, or sympathy for someone''s feelings and situation.","vi":"sự hiểu biết; sự thông cảm"},{"pos":"adj.","en":"Patient and sympathetic towards other people''s feelings or difficulties.","vi":"thấu hiểu; biết thông cảm"},{"pos":"n.","en":"An informal agreement between people or groups.","vi":"sự thỏa thuận ngầm; sự đồng thuận"}],"examples":[{"en":"Thanks for your understanding when I arrived late yesterday.","vi":"Cảm ơn bạn đã thông cảm khi tôi đến muộn vào ngày hôm qua.","audioKind":"ex"},{"en":"Learning another language can deepen students'' understanding of different cultures and encourage greater respect for others.","vi":"Việc học một ngôn ngữ khác có thể làm sâu sắc thêm sự hiểu biết của học sinh về các nền văn hóa khác nhau và thúc đẩy sự tôn trọng lớn hơn đối với người khác.","audioKind":"ex2"}],"collocations":[{"en":"a clear understanding of","vi":"sự hiểu rõ về"},{"en":"mutual understanding","vi":"sự hiểu biết lẫn nhau"},{"en":"reach an understanding","vi":"đạt được sự đồng thuận"},{"en":"an understanding friend","vi":"một người bạn biết thấu hiểu"}],"wordFamily":["understand (v.)","understandable (adj.)","understandably (adv.)","misunderstanding (n.)"],"synonyms":["comprehension","sympathy"],"antonyms":["misunderstanding"],"tipVi":"Biểu thị \"đối với sự hiểu biết\" dùng understanding of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_option', 'en-b1-25', 'option', '/ˈɑːpʃən/', 'B1', 'sự lựa chọn; phương án; quyền lựa chọn; cơ hội lựa chọn', 'n.', 'optional (adj.), optionally (adv.)', 'Đồng nghĩa: choice, alternative', 'Option chỉ phương án lựa chọn; have no option but to đi kèm với động từ nguyên thể.', 'Taking the bus is our cheapest option today.', NULL, 'Đi xe buýt là lựa chọn rẻ nhất của chúng ta hôm nay.', '{"wordId":"option","ukIpa":"/ˈɒpʃən/","usIpa":"/ˈɑːpʃən/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"Something you can choose from a range of possibilities.","vi":"sự lựa chọn; phương án"},{"pos":"n.","en":"The right or opportunity to choose whether to do something.","vi":"quyền lựa chọn; cơ hội lựa chọn"}],"examples":[{"en":"Taking the bus is our cheapest option today.","vi":"Đi xe buýt là lựa chọn rẻ nhất của chúng ta hôm nay.","audioKind":"ex"},{"en":"Remote working gives employees the option to live further from expensive city centres without changing jobs.","vi":"Làm việc từ xa mang lại cho nhân viên cơ hội lựa chọn sống xa các trung tâm thành phố đắt đỏ hơn mà không phải đổi việc.","audioKind":"ex2"}],"collocations":[{"en":"the best option","vi":"lựa chọn tốt nhất"},{"en":"have no option but to","vi":"không còn cách nào khác ngoài việc"},{"en":"keep your options open","vi":"giữ cho các lựa chọn của bạn rộng mở"},{"en":"the option to buy","vi":"quyền lựa chọn mua"}],"wordFamily":["optional (adj.)","optionally (adv.)"],"synonyms":["choice","alternative"],"antonyms":[],"tipVi":"Option chỉ phương án lựa chọn; have no option but to đi kèm với động từ nguyên thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_familiar', 'en-b1-25', 'familiar', '/fəˈmɪljɚ/', 'B1', 'quen thuộc; dễ nhận biết; am hiểu; hiểu rõ; nắm rõ', 'adj.', 'familiarity (n.), unfamiliar (adj.), familiarise (v.)', 'Đồng nghĩa: recognisable, well-known · Trái nghĩa: unfamiliar', 'Con người cảm thấy quen thuộc với điều gì dùng with; điều gì đó quen thuộc đối với ai dùng to.', 'I heard a familiar voice outside the kitchen door.', NULL, 'Tôi nghe thấy một giọng nói quen thuộc bên ngoài cửa nhà bếp.', '{"wordId":"familiar","ukIpa":"/fəˈmɪliə/","usIpa":"/fəˈmɪljɚ/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"easy to recognise because you have encountered it before","vi":"quen thuộc; dễ nhận biết"},{"pos":"adj.","en":"having knowledge or experience of something","vi":"am hiểu; hiểu rõ; nắm rõ"}],"examples":[{"en":"I heard a familiar voice outside the kitchen door.","vi":"Tôi nghe thấy một giọng nói quen thuộc bên ngoài cửa nhà bếp.","audioKind":"ex"},{"en":"Students who are familiar with digital tools may adapt more easily to online learning environments.","vi":"Những học sinh quen thuộc với các công cụ kỹ thuật số có thể thích nghi dễ dàng hơn với các môi trường học tập trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"familiar with","vi":"quen thuộc với"},{"en":"familiar to","vi":"quen thuộc đối với"},{"en":"a familiar face","vi":"một gương mặt quen thuộc"},{"en":"look familiar","vi":"trông quen quen"}],"wordFamily":["familiarity (n.)","unfamiliar (adj.)","familiarise (v.)"],"synonyms":["recognisable","well-known"],"antonyms":["unfamiliar"],"tipVi":"Con người cảm thấy quen thuộc với điều gì dùng with; điều gì đó quen thuộc đối với ai dùng to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_similarly', 'en-b1-25', 'similarly', '/ˈsɪmələrli/', 'B1', 'tương tự; giống như vậy', 'adv.', 'similar (adj.), similarity (n.), dissimilar (adj.)', 'Đồng nghĩa: likewise · Trái nghĩa: differently', 'Từ Similarly ở đầu câu thường đi kèm dấu phẩy để dẫn dắt một tình huống tương tự.', 'The twins dress similarly but have very different personalities.', NULL, 'Cặp sinh đôi ăn mặc giống nhau nhưng có tính cách rất khác biệt.', '{"wordId":"similarly","ukIpa":"/ˈsɪmələli/","usIpa":"/ˈsɪmələrli/","cefr":"B1","topic":"thinking","senses":[{"pos":"adv.","en":"In a similar way; also true of another person or thing","vi":"tương tự; giống như vậy"}],"examples":[{"en":"The twins dress similarly but have very different personalities.","vi":"Cặp sinh đôi ăn mặc giống nhau nhưng có tính cách rất khác biệt.","audioKind":"ex"},{"en":"Public libraries provide free access to information; similarly, community centres offer valuable opportunities for lifelong learning.","vi":"Các thư viện công cộng cung cấp quyền truy cập miễn phí vào thông tin; tương tự, các trung tâm cộng đồng cũng mang đến những cơ hội quý giá cho việc học tập suốt đời.","audioKind":"ex2"}],"collocations":[{"en":"similarly affected","vi":"chịu ảnh hưởng tương tự"},{"en":"similarly priced","vi":"có mức giá tương đương"},{"en":"behave similarly","vi":"cư xử tương tự"}],"wordFamily":["similar (adj.)","similarity (n.)","dissimilar (adj.)"],"synonyms":["likewise"],"antonyms":["differently"],"tipVi":"Từ Similarly ở đầu câu thường đi kèm dấu phẩy để dẫn dắt một tình huống tương tự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reality', 'en-b1-25', 'reality', '/riˈæləti/', 'B1', 'thực tế; thực trạng; sự thật; thực tế hiện hữu', 'n.', 'real (adj.), realistic (adj.), realistically (adv.), unreal (adj.)', 'Đồng nghĩa: actuality · Trái nghĩa: fantasy, illusion', 'in reality có nghĩa là "thực tế là"; a reality chỉ một điều đã trở thành hiện thực.', 'The holiday looked perfect, but reality was quite different.', NULL, 'Kỳ nghỉ có vẻ hoàn hảo, nhưng thực tế lại hoàn toàn khác.', '{"wordId":"reality","ukIpa":"/riˈæləti/","usIpa":"/riˈæləti/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"The way things actually are, rather than imagined or wished.","vi":"thực tế; thực trạng"},{"pos":"n.","en":"Something that actually exists or happens.","vi":"sự thật; thực tế hiện hữu"}],"examples":[{"en":"The holiday looked perfect, but reality was quite different.","vi":"Kỳ nghỉ có vẻ hoàn hảo, nhưng thực tế lại hoàn toàn khác.","audioKind":"ex"},{"en":"Although remote work offers flexibility, the reality is that many employees struggle to separate work from personal life.","vi":"Mặc dù làm việc từ xa mang lại sự linh hoạt, thực tế là nhiều nhân viên phải chật vật để tách biệt công việc và cuộc sống cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"in reality","vi":"trên thực tế; thực ra"},{"en":"face reality","vi":"đối mặt với thực tế"},{"en":"become a reality","vi":"trở thành sự thật"},{"en":"virtual reality","vi":"thực tế ảo"}],"wordFamily":["real (adj.)","realistic (adj.)","realistically (adv.)","unreal (adj.)"],"synonyms":["actuality"],"antonyms":["fantasy","illusion"],"tipVi":"in reality có nghĩa là \"thực tế là\"; a reality chỉ một điều đã trở thành hiện thực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impressive', 'en-b1-25', 'impressive', '/ɪmˈpresɪv/', 'B1', 'gây ấn tượng sâu sắc; hùng vĩ; xuất sắc; đáng nể', 'adj.', 'impress (v.), impression (n.), impressed (adj.), impressively (adv.)', 'Đồng nghĩa: remarkable, striking · Trái nghĩa: unimpressive', 'Sự vật gây ấn tượng dùng impressive; con người cảm thấy ấn tượng dùng impressed.', 'You made an impressive cake for your first attempt.', NULL, 'Bạn đã làm được một chiếc bánh rất tuyệt vời cho lần thử sức đầu tiên.', '{"wordId":"impressive","ukIpa":"/ɪmˈpresɪv/","usIpa":"/ɪmˈpresɪv/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Causing admiration because of exceptional quality, size, or skill.","vi":"gây ấn tượng sâu sắc; hùng vĩ; xuất sắc; đáng nể"}],"examples":[{"en":"You made an impressive cake for your first attempt.","vi":"Bạn đã làm được một chiếc bánh rất tuyệt vời cho lần thử sức đầu tiên.","audioKind":"ex"},{"en":"The region has made impressive progress in expanding access to clean water over the past decade.","vi":"Khu vực này đã đạt được những tiến bộ đáng chú ý trong việc mở rộng khả năng tiếp cận nước sạch trong thập kỷ qua.","audioKind":"ex2"}],"collocations":[{"en":"impressive achievement","vi":"thành tựu đáng nể"},{"en":"impressive progress","vi":"tiến bộ rõ rệt"},{"en":"impressive performance","vi":"màn trình diễn ấn tượng"}],"wordFamily":["impress (v.)","impression (n.)","impressed (adj.)","impressively (adv.)"],"synonyms":["remarkable","striking"],"antonyms":["unimpressive"],"tipVi":"Sự vật gây ấn tượng dùng impressive; con người cảm thấy ấn tượng dùng impressed.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_purpose', 'en-b1-25', 'purpose', '/ˈpɜːrpəs/', 'B1', 'mục đích; mục tiêu; ý định; mục đích sống; tinh thần cầu tiến', 'n.', 'purposeful (adj.), purposeless (adj.), purposely (adv.)', 'Đồng nghĩa: aim, objective, intention', 'on purpose mang nghĩa là "cố ý", không phải là "có mục đích".', 'What is the purpose of this tiny kitchen tool?', NULL, 'Dụng cụ nhà bếp nhỏ xíu này dùng để làm gì?', '{"wordId":"purpose","ukIpa":"/ˈpɜːpəs/","usIpa":"/ˈpɜːrpəs/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"the reason for doing something or what something is intended for","vi":"mục đích; mục tiêu; ý định"},{"pos":"n.","en":"a feeling of having meaningful aims in life","vi":"mục đích sống; tinh thần cầu tiến"}],"examples":[{"en":"What is the purpose of this tiny kitchen tool?","vi":"Dụng cụ nhà bếp nhỏ xíu này dùng để làm gì?","audioKind":"ex"},{"en":"The main purpose of public libraries is to provide equal access to information and learning opportunities.","vi":"Mục đích chính của các thư viện công cộng là giúp mọi người tiếp cận công bằng với thông tin và các cơ hội học tập.","audioKind":"ex2"}],"collocations":[{"en":"main purpose","vi":"mục đích chính"},{"en":"serve a purpose","vi":"phục vụ một mục đích; hữu ích"},{"en":"on purpose","vi":"cố ý; chủ tâm"},{"en":"a sense of purpose","vi":"cảm giác có mục đích sống"}],"wordFamily":["purposeful (adj.)","purposeless (adj.)","purposely (adv.)"],"synonyms":["aim","objective","intention"],"antonyms":[],"tipVi":"on purpose mang nghĩa là \"cố ý\", không phải là \"có mục đích\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sensible', 'en-b1-25', 'sensible', '/ˈsensəbl/', 'B1', 'hợp lý; khôn ngoan; thực tế', 'adj.', 'sensibly (adv.), sense (n.)', 'Đồng nghĩa: reasonable, practical, wise · Trái nghĩa: foolish, unwise', 'sensible mang nghĩa là hợp lý, khôn ngoan; còn sensitive mang nghĩa là nhạy cảm.', 'Taking an umbrella was sensible in this weather.', NULL, 'Mang theo một chiếc ô trong thời tiết này là một quyết định sáng suốt.', '{"wordId":"sensible","ukIpa":"/ˈsensəbl/","usIpa":"/ˈsensəbl/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Showing good judgement and practical understanding.","vi":"hợp lý; khôn ngoan; thực tế"}],"examples":[{"en":"Taking an umbrella was sensible in this weather.","vi":"Mang theo một chiếc ô trong thời tiết này là một quyết định sáng suốt.","audioKind":"ex"},{"en":"Investing in preventive healthcare is a sensible way to reduce pressure on public hospitals over time.","vi":"Đầu tư vào chăm sóc sức khỏe dự phòng là một cách hợp lý để giảm bớt áp lực cho các bệnh viện công theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"a sensible decision","vi":"một quyết định khôn ngoan"},{"en":"a sensible approach","vi":"một phương pháp hợp lý"},{"en":"sensible advice","vi":"lời khuyên hữu ích"}],"wordFamily":["sensibly (adv.)","sense (n.)"],"synonyms":["reasonable","practical","wise"],"antonyms":["foolish","unwise"],"tipVi":"sensible mang nghĩa là hợp lý, khôn ngoan; còn sensitive mang nghĩa là nhạy cảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_confuse', 'en-b1-25', 'confuse', '/kənˈfjuːz/', 'B1', 'làm rối trí; làm bối rối; làm hoang mang; nhầm lẫn; đánh tráo', 'v.', 'confusion (n.), confused (adj.), confusing (adj.)', 'Đồng nghĩa: puzzle, bewilder · Trái nghĩa: clarify', 'confused dùng để miêu tả cảm giác của con người; confusing dùng để miêu tả sự việc gây ra sự bối rối.', 'These complicated instructions confuse me every time I cook.', NULL, 'Những hướng dẫn phức tạp này làm tôi bối rối mỗi khi vào bếp nấu ăn.', '{"wordId":"confuse","ukIpa":"/kənˈfjuːz/","usIpa":"/kənˈfjuːz/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"To make someone unable to understand or think clearly.","vi":"làm rối trí; làm bối rối; làm hoang mang"},{"pos":"v.","en":"To wrongly think one person or thing is another.","vi":"nhầm lẫn; đánh tráo"}],"examples":[{"en":"These complicated instructions confuse me every time I cook.","vi":"Những hướng dẫn phức tạp này làm tôi bối rối mỗi khi vào bếp nấu ăn.","audioKind":"ex"},{"en":"Public health messages can confuse audiences when experts use technical language without explaining its meaning.","vi":"Các thông tin y tế công cộng có thể khiến người xem bối rối khi các chuyên gia sử dụng thuật ngữ chuyên môn mà không giải thích nghĩa của chúng.","audioKind":"ex2"}],"collocations":[{"en":"confuse A with B","vi":"nhầm lẫn A với B"},{"en":"confuse the issue","vi":"làm phức tạp vấn đề"},{"en":"easily confused","vi":"dễ bị nhầm lẫn"}],"wordFamily":["confusion (n.)","confused (adj.)","confusing (adj.)"],"synonyms":["puzzle","bewilder"],"antonyms":["clarify"],"tipVi":"confused dùng để miêu tả cảm giác của con người; confusing dùng để miêu tả sự việc gây ra sự bối rối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_curious', 'en-b1-25', 'curious', '/ˈkjʊriəs/', 'B1', 'tò mò; ham học hỏi; kỳ lạ; lạ lùng', 'adj.', 'curiosity (n.), curiously (adv.)', 'Đồng nghĩa: inquisitive, strange · Trái nghĩa: incurious', 'be curious about có nghĩa là "tò mò về...".', 'The curious kitten peered into my open shopping bag.', NULL, 'Chú mèo con tò mò đã thò đầu nhìn vào chiếc túi mua sắm đang mở của tôi.', '{"wordId":"curious","ukIpa":"/ˈkjʊəriəs/","usIpa":"/ˈkjʊriəs/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Wanting to learn or know more about something.","vi":"tò mò; ham học hỏi"},{"pos":"adj.","en":"Unusual or strange in a way that attracts attention.","vi":"kỳ lạ; lạ lùng"}],"examples":[{"en":"The curious kitten peered into my open shopping bag.","vi":"Chú mèo con tò mò đã thò đầu nhìn vào chiếc túi mua sắm đang mở của tôi.","audioKind":"ex"},{"en":"Teachers can encourage curious students to explore scientific questions through practical experiments rather than memorisation alone.","vi":"Giáo viên có thể khuyến khích những học sinh ham học hỏi khám phá các câu hỏi khoa học thông qua các thí nghiệm thực tế thay vì chỉ học vẹt.","audioKind":"ex2"}],"collocations":[{"en":"curious about","vi":"tò mò về"},{"en":"curious to know","vi":"rất muốn biết"},{"en":"a curious mixture","vi":"một sự kết hợp kỳ lạ"}],"wordFamily":["curiosity (n.)","curiously (adv.)"],"synonyms":["inquisitive","strange"],"antonyms":["incurious"],"tipVi":"be curious about có nghĩa là \"tò mò về...\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_previous', 'en-b1-25', 'previous', '/ˈpriːviəs/', 'B1', 'trước; trước đó; cũ', 'adj.', 'previously (adv.)', 'Đồng nghĩa: earlier, prior · Trái nghĩa: subsequent', 'previous là tính từ; để chỉ trạng từ "trước đây" dùng previously.', 'The previous tenant left some plants on the balcony.', NULL, 'Người thuê nhà trước đã để lại vài chậu cây trên ban công.', '{"wordId":"previous","ukIpa":"/ˈpriːviəs/","usIpa":"/ˈpriːviəs/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"happening or existing before the time or thing being discussed","vi":"trước; trước đó; cũ"}],"examples":[{"en":"The previous tenant left some plants on the balcony.","vi":"Người thuê nhà trước đã để lại vài chậu cây trên ban công.","audioKind":"ex"},{"en":"Previous studies suggest that regular physical activity can improve concentration and academic performance among school children.","vi":"Các nghiên cứu trước đây cho thấy việc tập thể dục đều đặn có thể cải thiện khả năng tập trung và thành tích học tập của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"previous experience","vi":"kinh nghiệm trước đây"},{"en":"previous studies","vi":"các nghiên cứu trước đó"},{"en":"the previous year","vi":"năm ngoái"}],"wordFamily":["previously (adv.)"],"synonyms":["earlier","prior"],"antonyms":["subsequent"],"tipVi":"previous là tính từ; để chỉ trạng từ \"trước đây\" dùng previously.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_similarity', 'en-b1-25', 'similarity', '/ˌsɪməˈlærəti/', 'B1', 'sự tương đồng; điểm giống nhau', 'n.', 'similar (adj.), similarly (adv.), dissimilar (adj.)', 'Đồng nghĩa: resemblance, likeness · Trái nghĩa: difference, dissimilarity', 'Tính tương đồng thường không đếm được; các điểm giống nhau cụ thể thì đếm được và thường dùng dạng số nhiều.', 'The similarity between these two jackets surprised me.', NULL, 'Sự giống nhau giữa hai chiếc áo khoác này làm tôi ngạc nhiên.', '{"wordId":"similarity","ukIpa":"/ˌsɪməˈlærəti/","usIpa":"/ˌsɪməˈlærəti/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"The state of being alike, or a shared feature","vi":"sự tương đồng; điểm giống nhau"}],"examples":[{"en":"The similarity between these two jackets surprised me.","vi":"Sự giống nhau giữa hai chiếc áo khoác này làm tôi ngạc nhiên.","audioKind":"ex"},{"en":"Despite their geographical distance, the two regions show striking similarities in traditional farming methods.","vi":"Mặc dù khoảng cách địa lý xa xôi, hai vùng này lại cho thấy những điểm tương đồng đến kinh ngạc trong phương thức canh tác truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"striking similarity","vi":"sự tương đồng rõ rệt"},{"en":"similarity between","vi":"sự giống nhau giữa"},{"en":"bear a similarity to","vi":"mang nét tương đồng với"}],"wordFamily":["similar (adj.)","similarly (adv.)","dissimilar (adj.)"],"synonyms":["resemblance","likeness"],"antonyms":["difference","dissimilarity"],"tipVi":"Tính tương đồng thường không đếm được; các điểm giống nhau cụ thể thì đếm được và thường dùng dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_personally', 'en-b1-25', 'personally', '/ˈpɝːsənəli/', 'B1', 'về phần mình; cá nhân tôi; trực tiếp; tận tay; về mặt cá nhân', 'adv.', 'person (n.), personal (adj.), personality (n.)', NULL, 'take it personally nghĩa là coi mọi việc như thể nhắm vào cá nhân mình.', 'Personally, I prefer walking to taking the bus.', NULL, 'Cá nhân tôi thích đi bộ hơn là đi xe buýt.', '{"wordId":"personally","ukIpa":"/ˈpɜːsənəli/","usIpa":"/ˈpɝːsənəli/","cefr":"B1","topic":"thinking","senses":[{"pos":"adv.","en":"used to introduce your own opinion or preference","vi":"về phần mình; cá nhân tôi"},{"pos":"adv.","en":"by a particular person rather than someone acting for them","vi":"trực tiếp; tận tay"},{"pos":"adv.","en":"as relating to someone''s character rather than their actions","vi":"về mặt cá nhân"}],"examples":[{"en":"Personally, I prefer walking to taking the bus.","vi":"Cá nhân tôi thích đi bộ hơn là đi xe buýt.","audioKind":"ex"},{"en":"Personally, I believe that public libraries remain essential because they provide free access to reliable information.","vi":"Tôi cá nhân tin rằng các thư viện công cộng vẫn vô cùng thiết yếu vì chúng cung cấp quyền truy cập miễn phí vào các thông tin đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"personally speaking","vi":"theo cá nhân tôi"},{"en":"take something personally","vi":"coi điều gì là xúc phạm cá nhân"},{"en":"personally responsible","vi":"chịu trách nhiệm cá nhân"},{"en":"know someone personally","vi":"quen biết ai ngoài đời thực"}],"wordFamily":["person (n.)","personal (adj.)","personality (n.)"],"synonyms":[],"antonyms":[],"tipVi":"take it personally nghĩa là coi mọi việc như thể nhắm vào cá nhân mình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recognize', 'en-b1-25', 'recognize', '/ˈrekəɡnaɪz/', 'B1', 'nhận ra; nhận diện; thừa nhận; nhận thức; công nhận; chính thức thừa nhận', 'v.', 'recognition (n.), recognizable (adj.), unrecognizable (adj.)', 'Đồng nghĩa: identify, acknowledge', 'Anh–Anh cũng thường được viết là recognise; khi mang nghĩa "nhận ra", từ này thường không dùng ở thì tiếp diễn.', 'I recognized my old teacher by her familiar laugh.', NULL, 'Tôi nhận ra cô giáo cũ nhờ tiếng cười quen thuộc của cô ấy.', '{"wordId":"recognize","ukIpa":"/ˈrekəɡnaɪz/","usIpa":"/ˈrekəɡnaɪz/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"Identify someone or something known or seen before.","vi":"nhận ra; nhận diện"},{"pos":"v.","en":"Accept or understand that something is true or important.","vi":"thừa nhận; nhận thức"},{"pos":"v.","en":"Officially accept someone''s status, qualifications, or achievements.","vi":"công nhận; chính thức thừa nhận"}],"examples":[{"en":"I recognized my old teacher by her familiar laugh.","vi":"Tôi nhận ra cô giáo cũ nhờ tiếng cười quen thuộc của cô ấy.","audioKind":"ex"},{"en":"Employers should recognize the value of practical experience when assessing candidates who lack formal qualifications.","vi":"Các nhà tuyển dụng nên nhìn nhận giá trị của kinh nghiệm thực tế khi đánh giá những ứng viên thiếu bằng cấp chính quy.","audioKind":"ex2"}],"collocations":[{"en":"recognize a face","vi":"nhận ra khuôn mặt"},{"en":"recognize the importance of","vi":"nhận thức được tầm quan trọng của"},{"en":"recognize someone as","vi":"công nhận ai là"},{"en":"internationally recognized","vi":"được quốc tế công nhận"}],"wordFamily":["recognition (n.)","recognizable (adj.)","unrecognizable (adj.)"],"synonyms":["identify","acknowledge"],"antonyms":[],"tipVi":"Anh–Anh cũng thường được viết là recognise; khi mang nghĩa \"nhận ra\", từ này thường không dùng ở thì tiếp diễn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_belief', 'en-b1-25', 'belief', '/bɪˈliːf/', 'B1', 'niềm tin; sự tin tưởng; tín ngưỡng', 'n.', 'believe (v.), believable (adj.), believer (n.), disbelief (n.)', 'Đồng nghĩa: conviction, faith · Trái nghĩa: disbelief', 'Cụm belief in dùng để chỉ sự tin cậy hoặc đức tin; trong khi belief that theo sau là một quan điểm cụ thể.', 'Her belief in me helped me try again.', NULL, 'Niềm tin của cô ấy đối với tôi đã giúp tôi sẵn sàng thử lại lần nữa.', '{"wordId":"belief","ukIpa":"/bɪˈliːf/","usIpa":"/bɪˈliːf/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"Confidence that something is true or someone is capable.","vi":"niềm tin; sự tin tưởng"},{"pos":"n.","en":"An idea accepted as true, especially about life or religion.","vi":"niềm tin; tín ngưỡng"}],"examples":[{"en":"Her belief in me helped me try again.","vi":"Niềm tin của cô ấy đối với tôi đã giúp tôi sẵn sàng thử lại lần nữa.","audioKind":"ex"},{"en":"The belief that education improves social mobility influences government spending priorities in many countries.","vi":"Niềm tin cho rằng giáo dục cải thiện sự di chuyển xã hội ảnh hưởng đến các ưu tiên chi tiêu chính phủ ở nhiều quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"belief in someone","vi":"sự tin tưởng vào ai đó"},{"en":"religious beliefs","vi":"tín ngưỡng tôn giáo"},{"en":"a widely held belief","vi":"quan điểm được nhiều người ủng hộ"},{"en":"contrary to popular belief","vi":"trái với quan niệm phổ biến"}],"wordFamily":["believe (v.)","believable (adj.)","believer (n.)","disbelief (n.)"],"synonyms":["conviction","faith"],"antonyms":["disbelief"],"tipVi":"Cụm belief in dùng để chỉ sự tin cậy hoặc đức tin; trong khi belief that theo sau là một quan điểm cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intention', 'en-b1-25', 'intention', '/ɪnˈtenʃən/', 'B1', 'ý định; mục đích; dự định', 'n.', 'intend (v.), intentional (adj.), intentionally (adv.), unintentional (adj.)', 'Đồng nghĩa: aim, purpose, plan', 'Có thể kết hợp với intention to do hoặc intention of doing.', 'I had no intention of staying out so late.', NULL, 'Tôi hoàn toàn không có ý định ở lại ngoài muộn đến thế.', '{"wordId":"intention","ukIpa":"/ɪnˈtenʃən/","usIpa":"/ɪnˈtenʃən/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"Something that you plan or mean to do.","vi":"ý định; mục đích; dự định"}],"examples":[{"en":"I had no intention of staying out so late.","vi":"Tôi hoàn toàn không có ý định ở lại ngoài muộn đến thế.","audioKind":"ex"},{"en":"The government announced its intention to expand public transport in order to reduce traffic congestion.","vi":"Chính phủ đã công bố dự định mở rộng hệ thống giao thông công cộng nhằm giảm thiểu tình trạng ùn tắc giao thông.","audioKind":"ex2"}],"collocations":[{"en":"have no intention of","vi":"không có ý định làm gì"},{"en":"with the intention of","vi":"với mục đích làm gì"},{"en":"announce an intention to","vi":"tuyên bố dự định làm gì"},{"en":"good intentions","vi":"ý tốt"}],"wordFamily":["intend (v.)","intentional (adj.)","intentionally (adv.)","unintentional (adj.)"],"synonyms":["aim","purpose","plan"],"antonyms":[],"tipVi":"Có thể kết hợp với intention to do hoặc intention of doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_basically', 'en-b1-25', 'basically', '/ˈbeɪsɪkli/', 'B1', 'về cơ bản; nhìn chung', 'adv.', 'basic (adj.), basics (n.)', 'Đồng nghĩa: essentially, fundamentally', 'Dùng để khái quát tình hình cốt lõi; không giống với từ "hầu như không" là barely.', 'The two recipes are basically the same, except for spices.', NULL, 'Hai công thức nấu ăn này về cơ bản giống nhau, ngoại trừ các loại gia vị.', '{"wordId":"basically","ukIpa":"/ˈbeɪsɪkli/","usIpa":"/ˈbeɪsɪkli/","cefr":"B1","topic":"thinking","senses":[{"pos":"adv.","en":"considering only the main facts or most important features","vi":"về cơ bản; nhìn chung"}],"examples":[{"en":"The two recipes are basically the same, except for spices.","vi":"Hai công thức nấu ăn này về cơ bản giống nhau, ngoại trừ các loại gia vị.","audioKind":"ex"},{"en":"Although delivery methods have changed, the purpose of public education remains basically the same across generations.","vi":"Mặc dù phương thức giảng dạy đã thay đổi, mục đích của giáo dục công lập về cơ bản vẫn giữ nguyên qua các thế hệ.","audioKind":"ex2"}],"collocations":[{"en":"basically the same","vi":"về cơ bản giống nhau"},{"en":"basically sound","vi":"về cơ bản là hợp lý; cơ bản là tốt"},{"en":"basically means","vi":"về cơ bản có nghĩa là"}],"wordFamily":["basic (adj.)","basics (n.)"],"synonyms":["essentially","fundamentally"],"antonyms":[],"tipVi":"Dùng để khái quát tình hình cốt lõi; không giống với từ \"hầu như không\" là barely.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clue', 'en-b1-25', 'clue', '/kluː/', 'B1', 'manh mối; gợi ý', 'n.', 'clueless (adj.)', 'Đồng nghĩa: hint, indication', 'a clue to trong đó to là giới từ, theo sau là danh từ và các từ tương đương.', 'The muddy footprints gave us a clue about the visitor.', NULL, 'Những vết chân dính bùn đã cho chúng tôi manh mối về vị khách.', '{"wordId":"clue","ukIpa":"/kluː/","usIpa":"/kluː/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"Information that helps you solve a problem or understand something.","vi":"manh mối; gợi ý"}],"examples":[{"en":"The muddy footprints gave us a clue about the visitor.","vi":"Những vết chân dính bùn đã cho chúng tôi manh mối về vị khách.","audioKind":"ex"},{"en":"Ancient tools provide valuable clues about how early communities adapted to changes in their natural environment.","vi":"Các công cụ cổ đại cung cấp những manh mối quý giá về cách các cộng đồng thời kỳ đầu thích nghi với sự thay đổi của môi trường tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"a clue to","vi":"manh mối cho"},{"en":"provide clues","vi":"cung cấp manh mối"},{"en":"not have a clue","vi":"hoàn toàn không biết gì"}],"wordFamily":["clueless (adj.)"],"synonyms":["hint","indication"],"antonyms":[],"tipVi":"a clue to trong đó to là giới từ, theo sau là danh từ và các từ tương đương.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_25_1', 'en-b1-25', 'Cách dùng “recognize” (v.) — nhận ra; nhận diện', 'recognize a face  ·  recognize the importance of  ·  recognize someone as', 'Anh–Anh cũng thường được viết là recognise; khi mang nghĩa "nhận ra", từ này thường không dùng ở thì tiếp diễn.', 'Họ từ (Word Family): recognition (n.), recognizable (adj.), unrecognizable (adj.) | Đồng nghĩa: identify, acknowledge', '[{"hanzi":"I recognized my old teacher by her familiar laugh.","pinyin":"","meaning":"Tôi nhận ra cô giáo cũ nhờ tiếng cười quen thuộc của cô ấy."},{"hanzi":"Employers should recognize the value of practical experience when assessing candidates who lack formal qualifications.","pinyin":"","meaning":"Các nhà tuyển dụng nên nhìn nhận giá trị của kinh nghiệm thực tế khi đánh giá những ứng viên thiếu bằng cấp chính quy."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_25_2', 'en-b1-25', 'Cách dùng “error” (n.) — lỗi; sai sót', 'make an error  ·  human error  ·  a margin of error', 'Từ error mang tính trang trọng hơn mistake, thường dùng trong các vấn đề kỹ thuật, tính toán hoặc phán đoán.', 'Họ từ (Word Family): err (v.), erroneous (adj.), erroneously (adv.) | Đồng nghĩa: mistake', '[{"hanzi":"An error in the booking left us without seats.","pinyin":"","meaning":"Một lỗi trong khâu đặt phòng đã khiến chúng tôi không có chỗ ngồi."},{"hanzi":"Researchers should check their calculations carefully, as a minor error can significantly affect the final conclusions.","pinyin":"","meaning":"Các nhà nghiên cứu nên kiểm tra kỹ các phép tính của họ, vì một sai sót nhỏ cũng có thể ảnh hưởng lớn đến kết luận cuối cùng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_25_3', 'en-b1-25', 'Cách dùng “similarity” (n.) — sự tương đồng; điểm giống nhau', 'striking similarity  ·  similarity between  ·  bear a similarity to', 'Tính tương đồng thường không đếm được; các điểm giống nhau cụ thể thì đếm được và thường dùng dạng số nhiều.', 'Họ từ (Word Family): similar (adj.), similarly (adv.), dissimilar (adj.) | Đồng nghĩa: resemblance, likeness · Trái nghĩa: difference, dissimilarity', '[{"hanzi":"The similarity between these two jackets surprised me.","pinyin":"","meaning":"Sự giống nhau giữa hai chiếc áo khoác này làm tôi ngạc nhiên."},{"hanzi":"Despite their geographical distance, the two regions show striking similarities in traditional farming methods.","pinyin":"","meaning":"Mặc dù khoảng cách địa lý xa xôi, hai vùng này lại cho thấy những điểm tương đồng đến kinh ngạc trong phương thức canh tác truyền thống."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_25_4', 'en-b1-25', 'Cách dùng “belief” (n.) — niềm tin; sự tin tưởng', 'belief in someone  ·  religious beliefs  ·  a widely held belief', 'Cụm belief in dùng để chỉ sự tin cậy hoặc đức tin; trong khi belief that theo sau là một quan điểm cụ thể.', 'Họ từ (Word Family): believe (v.), believable (adj.), believer (n.), disbelief (n.) | Đồng nghĩa: conviction, faith · Trái nghĩa: disbelief', '[{"hanzi":"Her belief in me helped me try again.","pinyin":"","meaning":"Niềm tin của cô ấy đối với tôi đã giúp tôi sẵn sàng thử lại lần nữa."},{"hanzi":"The belief that education improves social mobility influences government spending priorities in many countries.","pinyin":"","meaning":"Niềm tin cho rằng giáo dục cải thiện sự di chuyển xã hội ảnh hưởng đến các ưu tiên chi tiêu chính phủ ở nhiều quốc gia."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_25_1', 'en-b1-25', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
