INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_25_1_8', 'ten_b1_25_1', 'error', 'An error in the booking left us without seats.', 'An error in the booking left us without seats.', '/ˈerər/', 'Một lỗi trong khâu đặt phòng đã khiến chúng tôi không có chỗ ngồi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_25_1_1', 'en-b1-25', 'ten_b1_25_1', 'listening', 'listening', 'Adding another shelf was a simple solution to the clutter.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những hướng dẫn phức tạp này làm tôi bối rối mỗi khi vào bếp nấu ăn.","Việc lắp thêm một chiếc kệ là một giải pháp đơn giản để khắc phục tình trạng bừa bộn.","Chú cún thông minh của chúng tôi đã nhanh chóng học được cách mở cửa.","Cửa hàng đã đóng cửa; vì thế, chúng tôi đành tay trắng đi về."]'::jsonb, 1, 'Adding another shelf was a simple solution to the clutter. → Việc lắp thêm một chiếc kệ là một giải pháp đơn giản để khắc phục tình trạng bừa bộn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_25_1_2', 'en-b1-25', 'ten_b1_25_1', 'listening', 'listening', 'The shop was closed; therefore, we went home empty-handed.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cảm ơn bạn đã thông cảm khi tôi đến muộn vào ngày hôm qua.","Tôi nhận ra cô giáo cũ nhờ tiếng cười quen thuộc của cô ấy.","Tôi nghe thấy một giọng nói quen thuộc bên ngoài cửa nhà bếp.","Cửa hàng đã đóng cửa; vì thế, chúng tôi đành tay trắng đi về."]'::jsonb, 3, 'The shop was closed; therefore, we went home empty-handed. → Cửa hàng đã đóng cửa; vì thế, chúng tôi đành tay trắng đi về.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_25_1_3', 'en-b1-25', 'ten_b1_25_1', 'listening', 'listening', 'He claims he can fix my bike by lunchtime.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thật dại dột khi để quên ô ở nhà.","Cặp sinh đôi ăn mặc giống nhau nhưng có tính cách rất khác biệt.","Kỳ nghỉ có vẻ hoàn hảo, nhưng thực tế lại hoàn toàn khác.","Anh ấy tuyên bố có thể sửa chiếc xe đạp của tôi trước giờ ăn trưa."]'::jsonb, 3, 'He claims he can fix my bike by lunchtime. → Anh ấy tuyên bố có thể sửa chiếc xe đạp của tôi trước giờ ăn trưa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_25_2', 'en-b1-25', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_25_2_1', 'ten_b1_25_2', 'solution', 'Investment in renewable energy offers a long-term solution to the environmental problems caused by fossil fuels.', 'Investment in renewable energy offers a long-term solution to the environmental problems caused by fossil fuels.', '/səˈluːʃən/', 'Việc đầu tư vào năng lượng tái tạo cung cấp một giải pháp lâu dài cho các vấn đề môi trường do nhiên liệu hóa thạch gây ra.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_25_2_2', 'ten_b1_25_2', 'therefore', 'Public parks encourage physical activity and social interaction; therefore, cities should invest in maintaining accessible green spaces.', 'Public parks encourage physical activity and social interaction; therefore, cities should invest in maintaining accessible green spaces.', '/ˈðerfɔːr/', 'Các công viên công cộng thúc đẩy hoạt động thể chất và giao lưu xã hội; do đó, các thành phố nên đầu tư duy trì các không gian xanh dễ tiếp cận.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_25_2_3', 'ten_b1_25_2', 'claim', 'Some researchers claim that access to green spaces can improve mental health and strengthen community relationships.', 'Some researchers claim that access to green spaces can improve mental health and strengthen community relationships.', '/kleɪm/', 'Một số nhà nghiên cứu cho rằng việc tiếp cận không gian xanh có thể cải thiện sức khỏe tinh thần và tăng cường các mối quan hệ cộng đồng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_25_2_4', 'ten_b1_25_2', 'intelligent', 'Intelligent transport systems can reduce congestion by adjusting traffic signals in response to changing road conditions.', 'Intelligent transport systems can reduce congestion by adjusting traffic signals in response to changing road conditions.', '/ɪnˈtelɪdʒənt/', 'Các hệ thống giao thông thông minh có thể làm giảm tình trạng tắc nghẽn bằng cách điều chỉnh tín hiệu giao thông để đáp ứng các điều kiện đường sá thay đổi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_25_2_5', 'ten_b1_25_2', 'concentrate', 'Governments should concentrate resources on preventive healthcare to reduce pressure on hospitals in the long term.', 'Governments should concentrate resources on preventive healthcare to reduce pressure on hospitals in the long term.', '/ˈkɑːnsntreɪt/', 'Chính phủ nên tập trung nguồn lực vào y tế dự phòng nhằm giảm bớt áp lực cho các bệnh viện về lâu dài.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_25_2_6', 'ten_b1_25_2', 'foolish', 'It would be foolish to expand road networks without considering their long-term effects on air quality.', 'It would be foolish to expand road networks without considering their long-term effects on air quality.', '/ˈfuːlɪʃ/', 'Thật kém khôn ngoan nếu mở rộng mạng lưới giao thông mà không cân nhắc tác động lâu dài của chúng đối với chất lượng không khí.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_25_2_1', 'en-b1-25', 'ten_b1_25_2', 'listening', 'listening', 'Investment in renewable energy offers a long-term solution to the environmental problems caused by fossil fuels.', NULL, 'Trong câu vừa nghe, từ “solution” mang nghĩa nào sau đây?', '["giải pháp; cách giải quyết","tha thứ; khoan dung","cối xay gió","tầng hầm; phòng dưới mặt đất"]'::jsonb, 0, '“solution” (/səˈluːʃən/): giải pháp; cách giải quyết. Câu đầy đủ: Investment in renewable energy offers a long-term solution to the environmental problems caused by fossil fuels.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_25_2_2', 'en-b1-25', 'ten_b1_25_2', 'listening', 'listening', 'Public parks encourage physical activity and social interaction; therefore, cities should invest in maintaining accessible green spaces.', NULL, 'Trong câu vừa nghe, từ “therefore” mang nghĩa nào sau đây?', '["vì vậy; do đó; cho nên","thiên nga","tỷ lệ phần trăm; phần trăm","cơn ác mộng"]'::jsonb, 0, '“therefore” (/ˈðerfɔːr/): vì vậy; do đó; cho nên. Câu đầy đủ: Public parks encourage physical activity and social interaction; therefore, cities should invest in maintaining accessible green spaces.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
