INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_25_2', 'en-b1-25', NULL, 'comprehensive_test', 'listening', 'The shop was closed; therefore, we went home empty-handed.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi hoàn toàn không có ý định ở lại ngoài muộn đến thế.","Đi xe buýt là lựa chọn rẻ nhất của chúng ta hôm nay.","Cửa hàng đã đóng cửa; vì thế, chúng tôi đành tay trắng đi về.","Những hướng dẫn phức tạp này làm tôi bối rối mỗi khi vào bếp nấu ăn."]'::jsonb, 2, 'The shop was closed; therefore, we went home empty-handed. → Cửa hàng đã đóng cửa; vì thế, chúng tôi đành tay trắng đi về.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_25_3', 'en-b1-25', NULL, 'comprehensive_test', 'listening', 'claim', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tính phí; đòi tiền","lời chúc mừng; sự chúc mừng","tuyên bố; quả quyết","người đại diện; đại lý"]'::jsonb, 2, 'claim (/kleɪm/) → tuyên bố; quả quyết; đòi; nhận; yêu cầu; sự tuyên bố; đơn yêu cầu bồi thường', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_25_4', 'en-b1-25', NULL, 'comprehensive_test', 'listening', 'Our intelligent puppy quickly learned how to open doors.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một lỗi trong khâu đặt phòng đã khiến chúng tôi không có chỗ ngồi.","Những vết chân dính bùn đã cho chúng tôi manh mối về vị khách.","Tôi nhận ra cô giáo cũ nhờ tiếng cười quen thuộc của cô ấy.","Chú cún thông minh của chúng tôi đã nhanh chóng học được cách mở cửa."]'::jsonb, 3, 'Our intelligent puppy quickly learned how to open doors. → Chú cún thông minh của chúng tôi đã nhanh chóng học được cách mở cửa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_25_5', 'en-b1-25', NULL, 'comprehensive_test', 'listening', 'concentrate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tập trung (tư tưởng, sự chú ý)","rùa biển; con rùa","đặt trước; giữ lại","vợt (thể thao)"]'::jsonb, 0, 'concentrate (/ˈkɑːnsntreɪt/) → tập trung (tư tưởng, sự chú ý); tập trung; dồn (nguồn lực, nỗ lực vào đâu); chất cô đặc; dung dịch đậm đặc', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_25_6', 'en-b1-25', NULL, 'comprehensive_test', 'listening', 'It was foolish to leave my umbrella at home.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thật dại dột khi để quên ô ở nhà.","Bạn đã làm được một chiếc bánh rất tuyệt vời cho lần thử sức đầu tiên.","Tôi nghe thấy một giọng nói quen thuộc bên ngoài cửa nhà bếp.","Những vết chân dính bùn đã cho chúng tôi manh mối về vị khách."]'::jsonb, 0, 'It was foolish to leave my umbrella at home. → Thật dại dột khi để quên ô ở nhà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
