INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_25_18', 'en-b1-25', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in renewable energy offers a long-term solution to the environmental problems caused by fossil fuels.', 'Dựa vào câu trên, từ “solution” có nghĩa phù hợp nhất là gì?', '["đẹp trai; khôi ngô","dàn nhạc giao hưởng; dàn nhạc","giải pháp; cách giải quyết","nút giao thông; ngã rẽ; điểm giao nhau"]'::jsonb, 2, 'solution: giải pháp; cách giải quyết; dung dịch. Dịch cả câu: Việc đầu tư vào năng lượng tái tạo cung cấp một giải pháp lâu dài cho các vấn đề môi trường do nhiên liệu hóa thạch gây ra.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_25_19', 'en-b1-25', NULL, 'comprehensive_test', 'reading', NULL, 'Public parks encourage physical activity and social interaction; therefore, cities should invest in maintaining accessible green spaces.', 'Dựa vào câu trên, từ “therefore” có nghĩa phù hợp nhất là gì?', '["lớn tiếng; thành tiếng","xe máy kéo; máy cày","vì vậy; do đó; cho nên","tâm trạng; cảm xúc"]'::jsonb, 2, 'therefore: vì vậy; do đó; cho nên. Dịch cả câu: Các công viên công cộng thúc đẩy hoạt động thể chất và giao lưu xã hội; do đó, các thành phố nên đầu tư duy trì các không gian xanh dễ tiếp cận.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_25_20', 'en-b1-25', NULL, 'comprehensive_test', 'reading', NULL, 'Some researchers claim that access to green spaces can improve mental health and strengthen community relationships.', 'Dựa vào câu trên, từ “claim” có nghĩa phù hợp nhất là gì?', '["chu kỳ; vòng tuần hoàn","tuyên bố; quả quyết","niềm đam mê; sự say mê","ngoài ra; bên cạnh"]'::jsonb, 1, 'claim: tuyên bố; quả quyết; đòi; nhận; yêu cầu; sự tuyên bố; đơn yêu cầu bồi thường. Dịch cả câu: Một số nhà nghiên cứu cho rằng việc tiếp cận không gian xanh có thể cải thiện sức khỏe tinh thần và tăng cường các mối quan hệ cộng đồng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_25_21', 'en-b1-25', NULL, 'comprehensive_test', 'reading', NULL, 'Intelligent transport systems can reduce congestion by adjusting traffic signals in response to changing road conditions.', 'Dựa vào câu trên, từ “intelligent” có nghĩa phù hợp nhất là gì?', '["làm rối trí; làm bối rối; làm hoang mang","tình nguyện viên; người làm công tác thiện nguyện","trận động đất","thông minh; sáng suốt; có khả năng hiểu biết tốt"]'::jsonb, 3, 'intelligent: thông minh; sáng suốt; có khả năng hiểu biết tốt; có tính thông minh nhân tạo; tự động xử lý thông tin. Dịch cả câu: Các hệ thống giao thông thông minh có thể làm giảm tình trạng tắc nghẽn bằng cách điều chỉnh tín hiệu giao thông để đáp ứng các điều kiện đường sá thay đổi.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_25_22', 'en-b1-25', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ý định; mục đích; dự định”', '["percentage","fasten","sweetheart","intention"]'::jsonb, 3, 'ý định; mục đích; dự định → intention (/ɪnˈtenʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_25_23', 'en-b1-25', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “về cơ bản; nhìn chung”', '["rocket","time off","punish","basically"]'::jsonb, 3, 'về cơ bản; nhìn chung → basically (/ˈbeɪsɪkli/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_25_24', 'en-b1-25', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “manh mối; gợi ý”', '["wrist","shame","clue","celebration"]'::jsonb, 2, 'manh mối; gợi ý → clue (/kluː/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-26', 'en', 'Bài 26: Tư duy & Nhận thức (2) - CEFR B1', 'CEFR B1', 'B1 · Tư duy', '26 từ vựng Tiếng Anh CEFR B1 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3026, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_definite', 'en-b1-26', 'definite', '/ˈdefɪnət/', 'B1', 'rõ ràng; chắc chắn; rành mạch; thấy rõ', 'adj.', 'definitely (adv.), definiteness (n.), indefinite (adj.)', 'Đồng nghĩa: clear, certain · Trái nghĩa: indefinite, uncertain', 'definite là tính từ; definitely là trạng từ, mang nghĩa là chắc chắn.', 'We need a definite answer before booking the tickets.', NULL, 'Chúng ta cần một câu trả lời dứt khoát trước khi đặt vé.', '{"wordId":"definite","ukIpa":"/ˈdefɪnət/","usIpa":"/ˈdefɪnət/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Clearly decided or known, without uncertainty.","vi":"rõ ràng; chắc chắn"},{"pos":"adj.","en":"Clearly noticeable or unquestionably present.","vi":"rành mạch; thấy rõ"}],"examples":[{"en":"We need a definite answer before booking the tickets.","vi":"Chúng ta cần một câu trả lời dứt khoát trước khi đặt vé.","audioKind":"ex"},{"en":"Reliable public transport offers definite advantages for cities seeking to reduce congestion and improve air quality.","vi":"Hệ thống giao thông công cộng đáng tin cậy mang lại những lợi thế rõ rệt cho các thành phố đang tìm cách giảm thiểu tình trạng ùn tắc và cải thiện chất lượng không khí.","audioKind":"ex2"}],"collocations":[{"en":"a definite answer","vi":"một câu trả lời dứt khoát"},{"en":"definite plans","vi":"kế hoạch rõ ràng"},{"en":"a definite advantage","vi":"một lợi thế rõ rệt"}],"wordFamily":["definitely (adv.)","definiteness (n.)","indefinite (adj.)"],"synonyms":["clear","certain"],"antonyms":["indefinite","uncertain"],"tipVi":"definite là tính từ; definitely là trạng từ, mang nghĩa là chắc chắn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_convince', 'en-b1-26', 'convince', '/kənˈvɪns/', 'B1', 'làm cho tin; thuyết phục; thuyết phục (ai làm gì)', 'v.', 'convinced (adj.), convincing (adj.), convincingly (adv.)', 'Đồng nghĩa: persuade', 'Cấu trúc convince sb of sth có nghĩa là làm cho ai đó tin vào điều gì.', 'The photos convinced me that the flat was spacious.', NULL, 'Những bức ảnh đã thuyết phục tôi rằng căn hộ rất rộng rãi.', '{"wordId":"convince","ukIpa":"/kənˈvɪns/","usIpa":"/kənˈvɪns/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"to make someone believe something is true","vi":"làm cho tin; thuyết phục"},{"pos":"v.","en":"to persuade someone to do something","vi":"thuyết phục (ai làm gì)"}],"examples":[{"en":"The photos convinced me that the flat was spacious.","vi":"Những bức ảnh đã thuyết phục tôi rằng căn hộ rất rộng rãi.","audioKind":"ex"},{"en":"Governments must convince residents that improved public transport offers a practical alternative to private cars.","vi":"Chính phủ phải làm cho người dân tin rằng giao thông công cộng được cải thiện mang lại một giải pháp thay thế thiết thực cho xe hơi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"convince someone of something","vi":"làm cho ai tin điều gì"},{"en":"convince someone that","vi":"thuyết phục ai rằng"},{"en":"convince someone to do something","vi":"thuyết phục ai làm việc gì"}],"wordFamily":["convinced (adj.)","convincing (adj.)","convincingly (adv.)"],"synonyms":["persuade"],"antonyms":[],"tipVi":"Cấu trúc convince sb of sth có nghĩa là làm cho ai đó tin vào điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comparison', 'en-b1-26', 'comparison', '/kəmˈpærɪsən/', 'B1', 'sự so sánh; sự đối chiếu', 'n.', 'compare (v.), comparable (adj.), comparative (adj.)', NULL, 'Khi so sánh giữa hai đối tượng, dùng cấu trúc ''comparison between A and B''.', 'A quick comparison helped me choose the cheaper bicycle.', NULL, 'Một phép so sánh nhanh đã giúp tôi chọn được chiếc xe đạp rẻ hơn.', '{"wordId":"comparison","ukIpa":"/kəmˈpærɪsən/","usIpa":"/kəmˈpærɪsən/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"Examining things to see how they are similar or different.","vi":"sự so sánh; sự đối chiếu"}],"examples":[{"en":"A quick comparison helped me choose the cheaper bicycle.","vi":"Một phép so sánh nhanh đã giúp tôi chọn được chiếc xe đạp rẻ hơn.","audioKind":"ex"},{"en":"A comparison of public transport systems reveals significant differences in cost, reliability and environmental impact.","vi":"Việc so sánh các hệ thống giao thông công cộng cho thấy sự khác biệt đáng kể về chi phí, độ tin cậy và tác động đến môi trường.","audioKind":"ex2"}],"collocations":[{"en":"make a comparison","vi":"thực hiện phép so sánh"},{"en":"in comparison with","vi":"so với"},{"en":"by comparison","vi":"để so sánh"},{"en":"a direct comparison","vi":"sự so sánh trực tiếp"}],"wordFamily":["compare (v.)","comparable (adj.)","comparative (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi so sánh giữa hai đối tượng, dùng cấu trúc ''comparison between A and B''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mystery', 'en-b1-26', 'mystery', '/ˈmɪstəri/', 'B1', 'điều bí ẩn; điều chưa được giải đáp; sự huyền bí; vẻ bí ẩn; truyện trinh thám; truyện trinh thám hồi hộp', 'n.', 'mysterious (adj.), mysteriously (adv.)', 'Đồng nghĩa: puzzle, enigma', 'Dùng a mystery để chỉ một ẩn số cụ thể; cảm giác bí ẩn thường dùng dạng không đếm được.', 'Who left these flowers outside remains a mystery.', NULL, 'Ai đã để những bông hoa này ở bên ngoài đến nay vẫn là một điều bí ẩn.', '{"wordId":"mystery","ukIpa":"/ˈmɪstəri/","usIpa":"/ˈmɪstəri/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"Something that is unknown or cannot be explained","vi":"điều bí ẩn; điều chưa được giải đáp"},{"pos":"n.","en":"The quality of being strange, secret, or difficult to understand","vi":"sự huyền bí; vẻ bí ẩn"},{"pos":"n.","en":"A story about solving a puzzling event, often a crime","vi":"truyện trinh thám; truyện trinh thám hồi hộp"}],"examples":[{"en":"Who left these flowers outside remains a mystery.","vi":"Ai đã để những bông hoa này ở bên ngoài đến nay vẫn là một điều bí ẩn.","audioKind":"ex"},{"en":"Despite advances in marine research, the behaviour of many deep ocean species remains a mystery.","vi":"Mặc dù nghiên cứu biển đã có nhiều tiến bộ, hành vi của nhiều loài ở tầng biển sâu vẫn là một điều bí ẩn.","audioKind":"ex2"}],"collocations":[{"en":"solve a mystery","vi":"phá án; giải mã bí ẩn"},{"en":"remain a mystery","vi":"vẫn là một điều bí ẩn"},{"en":"a sense of mystery","vi":"cảm giác bí ẩn"},{"en":"mystery novel","vi":"tiểu thuyết trinh thám"}],"wordFamily":["mysterious (adj.)","mysteriously (adv.)"],"synonyms":["puzzle","enigma"],"antonyms":[],"tipVi":"Dùng a mystery để chỉ một ẩn số cụ thể; cảm giác bí ẩn thường dùng dạng không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unknown', 'en-b1-26', 'unknown', '/ˌʌnˈnoʊn/', 'B1', 'chưa biết; không rõ; không quen thuộc; điều chưa biết; người vô danh', 'adj.', 'know (v.), known (adj.), knowledge (n.)', 'Đồng nghĩa: unidentified, unfamiliar · Trái nghĩa: known', 'Cụm từ "the unknown" dùng để chỉ chung các sự việc, hiện tượng hoặc lĩnh vực chưa được khám phá.', 'An unknown caller rang while I was cooking dinner.', NULL, 'Một số điện thoại lạ đã gọi đến khi tôi đang nấu bữa tối.', '{"wordId":"unknown","ukIpa":"/ˌʌnˈnəʊn/","usIpa":"/ˌʌnˈnoʊn/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Not known, identified, or familiar.","vi":"chưa biết; không rõ; không quen thuộc"},{"pos":"n.","en":"Something not yet understood, or a person not widely known.","vi":"điều chưa biết; người vô danh"}],"examples":[{"en":"An unknown caller rang while I was cooking dinner.","vi":"Một số điện thoại lạ đã gọi đến khi tôi đang nấu bữa tối.","audioKind":"ex"},{"en":"The long-term effects of some new materials remain unknown, so further research is essential before widespread use.","vi":"Tác động lâu dài của một số vật liệu mới vẫn chưa được rõ, vì vậy việc nghiên cứu thêm trước khi đưa vào sử dụng rộng rãi là vô cùng cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"remain unknown","vi":"vẫn còn là ẩn số"},{"en":"unknown to someone","vi":"không được ai biết đến"},{"en":"an unknown cause","vi":"một nguyên nhân không rõ"},{"en":"the unknown","vi":"điều chưa biết"}],"wordFamily":["know (v.)","known (adj.)","knowledge (n.)"],"synonyms":["unidentified","unfamiliar"],"antonyms":["known"],"tipVi":"Cụm từ \"the unknown\" dùng để chỉ chung các sự việc, hiện tượng hoặc lĩnh vực chưa được khám phá.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impression', 'en-b1-26', 'impression', '/ɪmˈpreʃən/', 'B1', 'ấn tượng; cảm giác; màn biểu diễn bắt chước; vết lõm; dấu ấn', 'n.', 'impress (v.), impressive (adj.), impressed (adj.)', NULL, 'Cụm từ "under the impression that" có nghĩa là "tưởng rằng, cứ nghĩ rằng", thường hàm ý sự hiểu lầm.', 'Her warm welcome gave me a good first impression.', NULL, 'Sự chào đón nồng nhiệt của cô ấy đã để lại cho tôi ấn tượng ban đầu tốt đẹp.', '{"wordId":"impression","ukIpa":"/ɪmˈpreʃən/","usIpa":"/ɪmˈpreʃən/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"An idea or feeling formed about someone or something.","vi":"ấn tượng; cảm giác"},{"pos":"n.","en":"A performance copying someone''s voice, appearance, or behaviour.","vi":"màn biểu diễn bắt chước"},{"pos":"n.","en":"A mark left by pressing something into a surface.","vi":"vết lõm; dấu ấn"}],"examples":[{"en":"Her warm welcome gave me a good first impression.","vi":"Sự chào đón nồng nhiệt của cô ấy đã để lại cho tôi ấn tượng ban đầu tốt đẹp.","audioKind":"ex"},{"en":"The appearance of public spaces can strongly influence visitors'' overall impression of a city.","vi":"Diện mạo của các không gian công cộng có thể tác động mạnh mẽ đến ấn tượng chung của du khách về một thành phố.","audioKind":"ex2"}],"collocations":[{"en":"first impression","vi":"ấn tượng đầu tiên"},{"en":"make an impression on","vi":"tạo ấn tượng với"},{"en":"be under the impression that","vi":"có ấn tượng rằng"},{"en":"do an impression of","vi":"bắt chước ai"}],"wordFamily":["impress (v.)","impressive (adj.)","impressed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ \"under the impression that\" có nghĩa là \"tưởng rằng, cứ nghĩ rằng\", thường hàm ý sự hiểu lầm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_category', 'en-b1-26', 'category', '/ˈkætəɡɔːri/', 'B1', 'danh mục; thể loại; hạng', 'n.', 'categorise (v.), categorisation (n.)', 'Đồng nghĩa: class, group', 'Thường dùng cụm "fall into a category" để chỉ việc thuộc về một nhóm hoặc danh mục nào đó.', 'Put each book into the category that fits best.', NULL, 'Hãy xếp mỗi cuốn sách vào danh mục phù hợp nhất.', '{"wordId":"category","ukIpa":"/ˈkætəɡəri/","usIpa":"/ˈkætəɡɔːri/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"a group of things sharing particular features","vi":"danh mục; thể loại; hạng"}],"examples":[{"en":"Put each book into the category that fits best.","vi":"Hãy xếp mỗi cuốn sách vào danh mục phù hợp nhất.","audioKind":"ex"},{"en":"Researchers divided household spending into several categories to identify changes in consumer behaviour.","vi":"Các nhà nghiên cứu chia chi tiêu hộ gia đình thành nhiều loại để nhận diện sự thay đổi trong hành vi của người tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"fall into a category","vi":"thuộc một danh mục"},{"en":"broad category","vi":"danh mục rộng"},{"en":"age category","vi":"nhóm tuổi"},{"en":"divide into categories","vi":"chia thành các loại"}],"wordFamily":["categorise (v.)","categorisation (n.)"],"synonyms":["class","group"],"antonyms":[],"tipVi":"Thường dùng cụm \"fall into a category\" để chỉ việc thuộc về một nhóm hoặc danh mục nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attitude', 'en-b1-26', 'attitude', '/ˈætɪtuːd/', 'B1', 'thái độ; quan điểm', 'n.', NULL, 'Đồng nghĩa: outlook, stance', 'Nói về thái độ đối với việc gì thường dùng attitude to hoặc towards.', 'His cheerful attitude makes even rainy mornings feel brighter.', NULL, 'Thái độ vui vẻ của anh ấy làm cho những buổi sáng mưa gió cũng trở nên tươi tắn hơn.', '{"wordId":"attitude","ukIpa":"/ˈætɪtjuːd/","usIpa":"/ˈætɪtuːd/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"how you think or feel about someone or something","vi":"thái độ; quan điểm"}],"examples":[{"en":"His cheerful attitude makes even rainy mornings feel brighter.","vi":"Thái độ vui vẻ của anh ấy làm cho những buổi sáng mưa gió cũng trở nên tươi tắn hơn.","audioKind":"ex"},{"en":"Schools can encourage a positive attitude towards learning by giving students constructive feedback rather than constant criticism.","vi":"Nhà trường có thể khuyến khích thái độ học tập tích cực bằng cách đưa ra những góp ý mang tính xây dựng cho học sinh thay vì chỉ trích liên tục.","audioKind":"ex2"}],"collocations":[{"en":"positive attitude","vi":"thái độ tích cực"},{"en":"attitude towards","vi":"thái độ đối với"},{"en":"change of attitude","vi":"sự thay đổi thái độ"},{"en":"public attitudes","vi":"thái độ của công chúng"}],"wordFamily":[],"synonyms":["outlook","stance"],"antonyms":[],"tipVi":"Nói về thái độ đối với việc gì thường dùng attitude to hoặc towards.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_effect', 'en-b1-26', 'effect', '/ɪˈfekt/', 'B1', 'tác động; hiệu quả; đem lại; thực hiện', 'n.', 'effective (adj.), effectively (adv.), effectiveness (n.), ineffective (adj.)', 'Đồng nghĩa: impact, result', 'effect thường làm danh từ; affect thường làm động từ, mang nghĩa là ảnh hưởng.', 'The new curtains had a calming effect on the room.', NULL, 'Bộ rèm cửa mới mang lại cảm giác dễ chịu và thư thái cho căn phòng.', '{"wordId":"effect","ukIpa":"/ɪˈfekt/","usIpa":"/ɪˈfekt/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"A change or result caused by something.","vi":"tác động; hiệu quả"},{"pos":"v.","en":"To bring about a change or result.","vi":"đem lại; thực hiện"}],"examples":[{"en":"The new curtains had a calming effect on the room.","vi":"Bộ rèm cửa mới mang lại cảm giác dễ chịu và thư thái cho căn phòng.","audioKind":"ex"},{"en":"Higher parking charges may have little effect on traffic unless reliable public transport is also available.","vi":"Việc tăng phí đỗ xe có thể ít tác động đến tình trạng giao thông trừ khi có sẵn các phương tiện công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"have an effect on","vi":"có ảnh hưởng đến"},{"en":"side effect","vi":"tác dụng phụ"},{"en":"take effect","vi":"có hiệu lực; phát huy tác dụng"},{"en":"effect change","vi":"thực hiện sự thay đổi"}],"wordFamily":["effective (adj.)","effectively (adv.)","effectiveness (n.)","ineffective (adj.)"],"synonyms":["impact","result"],"antonyms":[],"tipVi":"effect thường làm danh từ; affect thường làm động từ, mang nghĩa là ảnh hưởng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conclusion', 'en-b1-26', 'conclusion', '/kənˈkluːʒən/', 'B1', 'sự kết luận; sự suy đoán; phần kết; phần cuối', 'n.', 'conclude (v.), conclusive (adj.), conclusively (adv.), inconclusive (adj.)', NULL, 'Cụm từ "đến kết luận" dùng reach hoặc draw a conclusion, không dùng make.', 'We reached the same conclusion after checking the receipts.', NULL, 'Chúng tôi đã đi đến cùng một kết luận sau khi kiểm tra các hóa đơn.', '{"wordId":"conclusion","ukIpa":"/kənˈkluːʒən/","usIpa":"/kənˈkluːʒən/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"a judgement formed after considering facts or evidence","vi":"sự kết luận; sự suy đoán"},{"pos":"n.","en":"the final part or ending of something","vi":"phần kết; phần cuối"}],"examples":[{"en":"We reached the same conclusion after checking the receipts.","vi":"Chúng tôi đã đi đến cùng một kết luận sau khi kiểm tra các hóa đơn.","audioKind":"ex"},{"en":"Researchers should consider alternative explanations before drawing a conclusion from a relatively small sample.","vi":"Các nhà nghiên cứu nên xem xét các lời giải thích thay thế trước khi đưa ra kết luận từ một mẫu có quy mô tương đối nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"reach a conclusion","vi":"đi đến kết luận"},{"en":"draw a conclusion","vi":"rút ra kết luận"},{"en":"jump to conclusions","vi":"vội vã kết luận"},{"en":"in conclusion","vi":"tóm lại"}],"wordFamily":["conclude (v.)","conclusive (adj.)","conclusively (adv.)","inconclusive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ \"đến kết luận\" dùng reach hoặc draw a conclusion, không dùng make.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_incorrect', 'en-b1-26', 'incorrect', '/ˌɪnkəˈrekt/', 'B1', 'sai; không chính xác; không đúng', 'adj.', 'correct (adj.), incorrectly (adv.), correctness (n.), correction (n.)', 'Đồng nghĩa: wrong, inaccurate, erroneous · Trái nghĩa: correct, accurate', 'incorrect mang tính trang trọng hơn wrong, thường dùng cho câu trả lời, thông tin hoặc dữ liệu.', 'The delivery failed because our address details were incorrect.', NULL, 'Việc giao hàng thất bại do thông tin địa chỉ của chúng tôi không chính xác.', '{"wordId":"incorrect","ukIpa":"/ˌɪnkəˈrekt/","usIpa":"/ˌɪnkəˈrekt/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Not accurate, true, or right.","vi":"sai; không chính xác; không đúng"}],"examples":[{"en":"The delivery failed because our address details were incorrect.","vi":"Việc giao hàng thất bại do thông tin địa chỉ của chúng tôi không chính xác.","audioKind":"ex"},{"en":"Incorrect information shared online can undermine public understanding of health issues and influence important personal decisions.","vi":"Thông tin sai lệch được chia sẻ trực tuyến có thể làm suy yếu sự hiểu biết của công chúng về các vấn đề sức khỏe và ảnh hưởng đến những quyết định cá nhân quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"incorrect information","vi":"thông tin sai lệch"},{"en":"incorrect answer","vi":"câu trả lời sai"},{"en":"factually incorrect","vi":"sai về mặt sự thật"}],"wordFamily":["correct (adj.)","incorrectly (adv.)","correctness (n.)","correction (n.)"],"synonyms":["wrong","inaccurate","erroneous"],"antonyms":["correct","accurate"],"tipVi":"incorrect mang tính trang trọng hơn wrong, thường dùng cho câu trả lời, thông tin hoặc dữ liệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_realise', 'en-b1-26', 'realise', '/ˈriːəlaɪz/', 'B1', 'nhận ra; hiểu rõ; thực hiện; biến thành hiện thực', 'v.', 'realisation (n.), realisable (adj.)', NULL, 'Kiểu Anh viết là realise, kiểu Mỹ viết là realize; có thể đi với mệnh đề that.', 'I suddenly realised my keys were still inside the house.', NULL, 'Tôi chợt nhận ra chìa khóa của mình vẫn ở trong nhà.', '{"wordId":"realise","ukIpa":"/ˈrɪəlaɪz/","usIpa":"/ˈriːəlaɪz/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"to become aware of a fact or understand a situation","vi":"nhận ra; hiểu rõ"},{"pos":"v.","en":"to make a hope, ambition, or possibility become real","vi":"thực hiện; biến thành hiện thực"}],"examples":[{"en":"I suddenly realised my keys were still inside the house.","vi":"Tôi chợt nhận ra chìa khóa của mình vẫn ở trong nhà.","audioKind":"ex"},{"en":"Many students realise the importance of time management when they begin balancing academic work with paid employment.","vi":"Nhiều học sinh nhận ra tầm quan trọng của việc quản lý thời gian khi họ bắt đầu cân đối giữa việc học và công việc làm thêm.","audioKind":"ex2"}],"collocations":[{"en":"realise that","vi":"nhận ra rằng"},{"en":"realise the importance of","vi":"nhận thức tầm quan trọng của"},{"en":"realise an ambition","vi":"thực hiện hoài bão"},{"en":"realise your potential","vi":"phát huy tiềm năng"}],"wordFamily":["realisation (n.)","realisable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Kiểu Anh viết là realise, kiểu Mỹ viết là realize; có thể đi với mệnh đề that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uncertain', 'en-b1-26', 'uncertain', '/ʌnˈsɝːtən/', 'B1', 'không chắc chắn; hoài nghi; chưa rõ ràng; khó đoán định', 'adj.', 'certainty (n.), uncertainty (n.), certain (adj.), uncertainly (adv.)', 'Đồng nghĩa: unsure, doubtful · Trái nghĩa: certain, sure', 'Dùng ''uncertain about'' khi nói về sự thiếu chắc chắn của con người; dùng ''remain uncertain'' cho những việc chưa được định đoạt.', 'I felt uncertain about which jacket to buy.', NULL, 'Tôi thấy phân vân không biết nên mua chiếc áo khoác nào.', '{"wordId":"uncertain","ukIpa":"/ʌnˈsɜːtn/","usIpa":"/ʌnˈsɝːtən/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"not sure about something","vi":"không chắc chắn; hoài nghi"},{"pos":"adj.","en":"not known, settled, or predictable","vi":"chưa rõ ràng; khó đoán định"}],"examples":[{"en":"I felt uncertain about which jacket to buy.","vi":"Tôi thấy phân vân không biết nên mua chiếc áo khoác nào.","audioKind":"ex"},{"en":"The long-term effects of remote working remain uncertain, particularly for younger employees entering the labour market.","vi":"Ảnh hưởng lâu dài của việc làm việc từ xa vẫn chưa rõ ràng, đặc biệt đối với các nhân viên trẻ mới bước chân vào thị trường lao động.","audioKind":"ex2"}],"collocations":[{"en":"uncertain about","vi":"chưa chắc chắn về điều gì"},{"en":"an uncertain future","vi":"tương lai bất định"},{"en":"remain uncertain","vi":"vẫn chưa được xác định"}],"wordFamily":["certainty (n.)","uncertainty (n.)","certain (adj.)","uncertainly (adv.)"],"synonyms":["unsure","doubtful"],"antonyms":["certain","sure"],"tipVi":"Dùng ''uncertain about'' khi nói về sự thiếu chắc chắn của con người; dùng ''remain uncertain'' cho những việc chưa được định đoạt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_complex', 'en-b1-26', 'complex', '/kəmˈpleks/', 'B1', 'phức tạp, có nhiều phần liên kết và khó hiểu; khu phức hợp, cụm công trình phục vụ các hoạt động liên quan', 'adj.', 'complexity (n.)', 'Đồng nghĩa: complicated · Trái nghĩa: simple', 'Khi là tính từ nghĩa là phức tạp; khi là danh từ có thể chỉ một cụm công trình xây dựng.', 'This recipe looks complex, but each step is simple.', NULL, 'Công thức nấu ăn này trông có vẻ phức tạp, nhưng từng bước lại rất đơn giản.', '{"wordId":"complex","ukIpa":"/ˈkɒmpleks/","usIpa":"/kəmˈpleks/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Having many connected parts and being difficult to understand.","vi":"phức tạp, có nhiều phần liên kết và khó hiểu"},{"pos":"n.","en":"A group of buildings used for related activities.","vi":"khu phức hợp, cụm công trình phục vụ các hoạt động liên quan"}],"examples":[{"en":"This recipe looks complex, but each step is simple.","vi":"Công thức nấu ăn này trông có vẻ phức tạp, nhưng từng bước lại rất đơn giản.","audioKind":"ex"},{"en":"Urban poverty is a complex issue that requires cooperation between governments, businesses and local communities.","vi":"Tình trạng nghèo đói ở đô thị là một vấn đề phức tạp đòi hỏi sự hợp tác giữa chính phủ, doanh nghiệp và cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"complex issue","vi":"vấn đề phức tạp"},{"en":"complex system","vi":"hệ thống phức tạp"},{"en":"sports complex","vi":"khu phức hợp thể thao"}],"wordFamily":["complexity (n.)"],"synonyms":["complicated"],"antonyms":["simple"],"tipVi":"Khi là tính từ nghĩa là phức tạp; khi là danh từ có thể chỉ một cụm công trình xây dựng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reasonable', 'en-b1-26', 'reasonable', '/ˈriːzənəbl/', 'B1', 'hợp lý; có lý; thấu tình đạt lý; giá cả phải chăng; không đắt; chấp nhận được; ở mức độ vừa phải', 'adj.', 'reason (n.), reasonably (adv.), unreasonable (adj.), reasonableness (n.)', 'Đồng nghĩa: sensible, fair · Trái nghĩa: unreasonable', 'Khi mô tả giá cả, từ này chỉ mức độ công đạo, không đắt đỏ, không nhất thiết là phải cực kỳ rẻ.', 'Your suggestion sounds reasonable, so let''s try it tomorrow.', NULL, 'Gợi ý của bạn nghe có vẻ hợp lý, vậy chúng ta hãy thử làm vào ngày mai nhé.', '{"wordId":"reasonable","ukIpa":"/ˈriːzənəbl/","usIpa":"/ˈriːzənəbl/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Fair and sensible, showing good judgement.","vi":"hợp lý; có lý; thấu tình đạt lý"},{"pos":"adj.","en":"Not too expensive.","vi":"giá cả phải chăng; không đắt"},{"pos":"adj.","en":"Acceptable in quality or amount, though not excellent.","vi":"chấp nhận được; ở mức độ vừa phải"}],"examples":[{"en":"Your suggestion sounds reasonable, so let''s try it tomorrow.","vi":"Gợi ý của bạn nghe có vẻ hợp lý, vậy chúng ta hãy thử làm vào ngày mai nhé.","audioKind":"ex"},{"en":"Employers should set reasonable targets that encourage productivity without placing excessive pressure on their staff.","vi":"Người sử dụng lao động nên đặt ra các mục tiêu hợp lý nhằm thúc đẩy năng suất mà không gây áp lực quá mức cho nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"a reasonable explanation","vi":"một lời giải thích hợp lý"},{"en":"a reasonable price","vi":"một mức giá phải chăng"},{"en":"reasonable expectations","vi":"những kỳ vọng hợp lý"},{"en":"a reasonable standard","vi":"một tiêu chuẩn chấp nhận được"}],"wordFamily":["reason (n.)","reasonably (adv.)","unreasonable (adj.)","reasonableness (n.)"],"synonyms":["sensible","fair"],"antonyms":["unreasonable"],"tipVi":"Khi mô tả giá cả, từ này chỉ mức độ công đạo, không đắt đỏ, không nhất thiết là phải cực kỳ rẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_focus', 'en-b1-26', 'focus', '/ˈfoʊkəs/', 'B1', 'tập trung; chú trọng; trọng tâm; điểm tập trung; độ nét; tiêu điểm', 'v.', 'focused (adj.), unfocused (adj.), refocus (v.), focal (adj.)', 'Đồng nghĩa: concentrate', 'Focus on đi với danh từ hoặc danh động từ; không dùng focus in.', 'Please turn the music down so I can focus.', NULL, 'Làm ơn vặn nhỏ nhạc lại để tôi có thể tập trung.', '{"wordId":"focus","ukIpa":"/ˈfəʊkəs/","usIpa":"/ˈfoʊkəs/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"direct attention or effort towards one particular thing","vi":"tập trung; chú trọng"},{"pos":"n.","en":"the main subject receiving attention or effort","vi":"trọng tâm; điểm tập trung"},{"pos":"n.","en":"image sharpness, or the point where light rays meet","vi":"độ nét; tiêu điểm"}],"examples":[{"en":"Please turn the music down so I can focus.","vi":"Làm ơn vặn nhỏ nhạc lại để tôi có thể tập trung.","audioKind":"ex"},{"en":"Governments should focus on affordable public transport to reduce congestion and improve access to employment.","vi":"Chính phủ nên tập trung vào hệ thống giao thông công cộng giá cả phải chăng để giảm thiểu ùn tắc và cải thiện khả năng tiếp cận việc làm.","audioKind":"ex2"}],"collocations":[{"en":"focus on","vi":"tập trung vào"},{"en":"the main focus","vi":"trọng tâm chính"},{"en":"in focus","vi":"lấy nét rõ"},{"en":"out of focus","vi":"mờ điểm"}],"wordFamily":["focused (adj.)","unfocused (adj.)","refocus (v.)","focal (adj.)"],"synonyms":["concentrate"],"antonyms":[],"tipVi":"Focus on đi với danh từ hoặc danh động từ; không dùng focus in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consist', 'en-b1-26', 'consist', '/kənˈsɪst/', 'B1', 'gồm có; bao gồm; cốt ở; chủ yếu ở', 'v.', NULL, NULL, 'Cấu trúc consist of dùng để chỉ thành phần cấu thành và không dùng ở thể bị động; consist in dùng để chỉ bản chất cốt lõi.', 'Our picnic lunch consists of sandwiches, fruit, and juice.', NULL, 'Bữa trưa dã ngoại của chúng tôi gồm có bánh mì kẹp, trái cây và nước ép.', '{"wordId":"consist","ukIpa":"/kənˈsɪst/","usIpa":"/kənˈsɪst/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"to be formed from particular parts or members","vi":"gồm có; bao gồm"},{"pos":"v.","en":"to have something as the essential feature","vi":"cốt ở; chủ yếu ở"}],"examples":[{"en":"Our picnic lunch consists of sandwiches, fruit, and juice.","vi":"Bữa trưa dã ngoại của chúng tôi gồm có bánh mì kẹp, trái cây và nước ép.","audioKind":"ex"},{"en":"An effective recycling programme consists of convenient collection services and clear guidance for local residents.","vi":"Một chương trình tái chế hiệu quả bao gồm các dịch vụ thu gom thuận tiện và hướng dẫn rõ ràng cho cư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"consist of","vi":"bao gồm"},{"en":"consist mainly of","vi":"chủ yếu bao gồm"},{"en":"consist in","vi":"cốt ở; nằm ở"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc consist of dùng để chỉ thành phần cấu thành và không dùng ở thể bị động; consist in dùng để chỉ bản chất cốt lõi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_select', 'en-b1-26', 'select', '/səˈlekt/', 'B1', 'lựa chọn; chọn lọc; tuyển chọn; ưu tú', 'v.', 'selection (n.), selective (adj.), selectively (adv.)', 'Đồng nghĩa: choose, pick', 'select trang trọng hơn choose, thường nhấn mạnh việc lựa chọn cẩn thận.', 'Please select a fresh apple from the basket.', NULL, 'Vui lòng chọn một quả táo tươi trong giỏ.', '{"wordId":"select","ukIpa":"/sɪˈlekt/","usIpa":"/səˈlekt/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"Choose someone or something carefully from available options.","vi":"lựa chọn; chọn lọc"},{"pos":"adj.","en":"Carefully chosen for special quality or suitability.","vi":"tuyển chọn; ưu tú"}],"examples":[{"en":"Please select a fresh apple from the basket.","vi":"Vui lòng chọn một quả táo tươi trong giỏ.","audioKind":"ex"},{"en":"Universities should select applicants using a range of criteria rather than relying entirely on examination results.","vi":"Các trường đại học nên tuyển chọn ứng viên dựa trên nhiều tiêu chí thay vì chỉ hoàn toàn dựa vào kết quả thi cử.","audioKind":"ex2"}],"collocations":[{"en":"select a candidate","vi":"chọn ứng viên"},{"en":"select from a list","vi":"chọn từ một danh sách"},{"en":"select someone for a role","vi":"chọn ai đó cho một vai trò"},{"en":"a select group","vi":"một nhóm được tuyển chọn kỹ lưỡng"}],"wordFamily":["selection (n.)","selective (adj.)","selectively (adv.)"],"synonyms":["choose","pick"],"antonyms":[],"tipVi":"select trang trọng hơn choose, thường nhấn mạnh việc lựa chọn cẩn thận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prove', 'en-b1-26', 'prove', '/pruːv/', 'B1', 'chứng minh; chứng thực; hóa ra là; tỏ ra là', 'v.', 'proof (n.), proven (adj.), provable (adj.)', 'Đồng nghĩa: demonstrate, establish · Trái nghĩa: disprove', 'prove có thể đi với mệnh đề that, hoặc đi trực tiếp với tính từ.', 'These photos prove that our dog opened the cupboard.', NULL, 'Những bức ảnh này chứng minh rằng con chó của chúng ta đã mở tủ chén.', '{"wordId":"prove","ukIpa":"/pruːv/","usIpa":"/pruːv/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"Show that something is true using evidence","vi":"chứng minh; chứng thực"},{"pos":"v.","en":"Turn out to be a particular thing or quality","vi":"hóa ra là; tỏ ra là"}],"examples":[{"en":"These photos prove that our dog opened the cupboard.","vi":"Những bức ảnh này chứng minh rằng con chó của chúng ta đã mở tủ chén.","audioKind":"ex"},{"en":"Long-term studies may prove that regular exercise improves concentration as well as physical health.","vi":"Các nghiên cứu dài hạn có thể chứng minh rằng việc tập thể dục thường xuyên giúp cải thiện khả năng tập trung cũng như sức khỏe thể chất.","audioKind":"ex2"}],"collocations":[{"en":"prove a point","vi":"chứng minh một quan điểm"},{"en":"prove effective","vi":"tỏ ra hiệu quả"},{"en":"prove someone wrong","vi":"chứng minh ai đó sai"}],"wordFamily":["proof (n.)","proven (adj.)","provable (adj.)"],"synonyms":["demonstrate","establish"],"antonyms":["disprove"],"tipVi":"prove có thể đi với mệnh đề that, hoặc đi trực tiếp với tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_basis', 'en-b1-26', 'basis', '/ˈbeɪsɪs/', 'B1', 'nền tảng; cơ sở; cách thức; tần suất', 'n.', NULL, 'Đồng nghĩa: foundation', 'Dạng số nhiều là "bases"; cụm "on a daily basis" có nghĩa là hàng ngày.', 'These fresh vegetables form the basis of our soup.', NULL, 'Những loại rau tươi này tạo nên thành phần cơ bản cho món súp của chúng tôi.', '{"wordId":"basis","ukIpa":"/ˈbeɪsɪs/","usIpa":"/ˈbeɪsɪs/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"The main facts or ideas supporting something.","vi":"nền tảng; cơ sở"},{"pos":"n.","en":"The arrangement or frequency according to which something happens.","vi":"cách thức; tần suất"}],"examples":[{"en":"These fresh vegetables form the basis of our soup.","vi":"Những loại rau tươi này tạo nên thành phần cơ bản cho món súp của chúng tôi.","audioKind":"ex"},{"en":"Reliable evidence should provide the basis for government decisions about public health and environmental protection.","vi":"Bằng chứng đáng tin cậy cần phải là cơ sở cho các quyết định của chính phủ về sức khỏe cộng đồng và bảo vệ môi trường.","audioKind":"ex2"}],"collocations":[{"en":"on a daily basis","vi":"hàng ngày"},{"en":"on the basis of","vi":"dựa trên cơ sở của"},{"en":"form the basis of","vi":"tạo thành nền tảng của"},{"en":"a sound basis","vi":"một nền tảng vững chắc"}],"wordFamily":[],"synonyms":["foundation"],"antonyms":[],"tipVi":"Dạng số nhiều là \"bases\"; cụm \"on a daily basis\" có nghĩa là hàng ngày.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_further', 'en-b1-26', 'further', '/ˈfɝːðɚ/', 'B1', 'xa hơn; thêm nữa; ở mức độ lớn hơn; hơn nữa; bổ sung; tiên tiến hơn; thúc đẩy; làm cho phát triển', 'adv.', NULL, NULL, 'further có thể chỉ cả mức độ hoặc khoảng cách; farther chủ yếu chỉ khoảng cách vật lý.', 'We walked further along the beach before stopping.', NULL, 'Chúng tôi đi bộ xa hơn dọc theo bãi biển trước khi dừng lại.', '{"wordId":"further","ukIpa":"/ˈfɜːðə/","usIpa":"/ˈfɝːðɚ/","cefr":"B1","topic":"thinking","senses":[{"pos":"adv.","en":"to a greater degree or a more distant place","vi":"xa hơn; thêm nữa; ở mức độ lớn hơn"},{"pos":"adj.","en":"additional or more advanced","vi":"hơn nữa; bổ sung; tiên tiến hơn"},{"pos":"v.","en":"to help something develop or succeed","vi":"thúc đẩy; làm cho phát triển"}],"examples":[{"en":"We walked further along the beach before stopping.","vi":"Chúng tôi đi bộ xa hơn dọc theo bãi biển trước khi dừng lại.","audioKind":"ex"},{"en":"Further research is needed to understand how urban green spaces affect residents'' mental health.","vi":"Cần phải nghiên cứu thêm để hiểu rõ không gian xanh đô thị ảnh hưởng thế nào đến sức khỏe tinh thần của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"further information","vi":"thêm thông tin"},{"en":"further research","vi":"nghiên cứu thêm"},{"en":"discuss further","vi":"thảo luận sâu hơn"},{"en":"further your career","vi":"thúc đẩy sự nghiệp của bạn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"further có thể chỉ cả mức độ hoặc khoảng cách; farther chủ yếu chỉ khoảng cách vật lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_particular', 'en-b1-26', 'particular', '/pərˈtɪkjələr/', 'B1', 'cụ thể; riêng; đặc biệt; hơn hẳn bình thường; kén chọn; khó tính', 'adj.', 'particularly (adv.), particulars (n.)', 'Đồng nghĩa: specific, fussy · Trái nghĩa: general', 'in particular ý nghĩa là đặc biệt; be particular about thể hiện sự kén chọn về thứ gì đó.', 'Are you looking for any particular book today?', NULL, 'Hôm nay bạn đang tìm một cuốn sách cụ thể nào đó phải không?', '{"wordId":"particular","ukIpa":"/pəˈtɪkjələ/","usIpa":"/pərˈtɪkjələr/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"used to refer to one specific person, thing, or situation","vi":"cụ thể; riêng"},{"pos":"adj.","en":"greater or more noticeable than usual","vi":"đặc biệt; hơn hẳn bình thường"},{"pos":"adj.","en":"having strong preferences and being difficult to satisfy","vi":"kén chọn; khó tính"}],"examples":[{"en":"Are you looking for any particular book today?","vi":"Hôm nay bạn đang tìm một cuốn sách cụ thể nào đó phải không?","audioKind":"ex"},{"en":"Schools should pay particular attention to students who lack access to digital resources at home.","vi":"Các trường học nên đặc biệt quan tâm đến những học sinh thiếu khả năng tiếp cận tài nguyên kỹ thuật số tại nhà.","audioKind":"ex2"}],"collocations":[{"en":"a particular reason","vi":"một lý do cụ thể"},{"en":"particular attention","vi":"sự quan tâm đặc biệt"},{"en":"in particular","vi":"đặc biệt; cụ thể là"},{"en":"particular about","vi":"cực kỳ kén chọn về"}],"wordFamily":["particularly (adv.)","particulars (n.)"],"synonyms":["specific","fussy"],"antonyms":["general"],"tipVi":"in particular ý nghĩa là đặc biệt; be particular about thể hiện sự kén chọn về thứ gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pattern', 'en-b1-26', 'pattern', '/ˈpætɚn/', 'B1', 'mô hình; quy luật; hoa văn; họa tiết', 'n.', 'patterned (adj.)', NULL, 'Để chỉ quy luật, thường dùng a pattern of + danh từ.', 'My cat follows the same sleeping pattern every day.', NULL, 'Con mèo của tôi tuân theo cùng một quy luật ngủ nghỉ mỗi ngày.', '{"wordId":"pattern","ukIpa":"/ˈpætən/","usIpa":"/ˈpætɚn/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"A regular or repeated way something happens or is done.","vi":"mô hình; quy luật"},{"pos":"n.","en":"An arrangement of shapes, lines, or colours forming a design.","vi":"hoa văn; họa tiết"}],"examples":[{"en":"My cat follows the same sleeping pattern every day.","vi":"Con mèo của tôi tuân theo cùng một quy luật ngủ nghỉ mỗi ngày.","audioKind":"ex"},{"en":"Researchers analyse patterns of energy consumption to identify opportunities for reducing waste in households.","vi":"Các nhà nghiên cứu phân tích các mẫu tiêu thụ năng lượng để tìm cơ hội giảm lãng phí trong các hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"a pattern of behaviour","vi":"mô hình hành vi"},{"en":"sleep patterns","vi":"quy luật giấc ngủ"},{"en":"a floral pattern","vi":"họa tiết hoa"},{"en":"follow a pattern","vi":"tuân theo một quy luật"}],"wordFamily":["patterned (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Để chỉ quy luật, thường dùng a pattern of + danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_related', 'en-b1-26', 'related', '/rɪˈleɪtɪd/', 'B1', 'có liên quan; có dính líu; có quan hệ họ hàng; có họ', 'adj.', 'relate (v.), relation (n.), relationship (n.), unrelated (adj.)', 'Đồng nghĩa: connected, linked · Trái nghĩa: unrelated', 'Thường dùng be related to; to là giới từ, theo sau là danh từ hoặc danh động từ.', 'These two problems are related to the same broken pipe.', NULL, 'Hai vấn đề này đều liên quan đến cùng một đoạn ống nước bị vỡ.', '{"wordId":"related","ukIpa":"/rɪˈleɪtɪd/","usIpa":"/rɪˈleɪtɪd/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"connected with something in some way","vi":"có liên quan; có dính líu"},{"pos":"adj.","en":"belonging to the same family","vi":"có quan hệ họ hàng; có họ"}],"examples":[{"en":"These two problems are related to the same broken pipe.","vi":"Hai vấn đề này đều liên quan đến cùng một đoạn ống nước bị vỡ.","audioKind":"ex"},{"en":"Many health problems are closely related to poor housing conditions and limited access to nutritious food.","vi":"Nhiều vấn đề sức khỏe có liên quan mật thiết đến điều kiện nhà ở kém và khả năng tiếp cận thực phẩm dinh dưỡng hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"related to","vi":"liên quan đến"},{"en":"closely related","vi":"có liên quan mật thiết"},{"en":"related issues","vi":"các vấn đề liên quan"},{"en":"related by marriage","vi":"có quan hệ thông gia"}],"wordFamily":["relate (v.)","relation (n.)","relationship (n.)","unrelated (adj.)"],"synonyms":["connected","linked"],"antonyms":["unrelated"],"tipVi":"Thường dùng be related to; to là giới từ, theo sau là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_identify', 'en-b1-26', 'identify', '/aɪˈdentɪfaɪ/', 'B1', 'nhận diện; xác định danh tính của ai hoặc cái gì; phát hiện hoặc xác định điều gì thông qua việc kiểm tra; tìm ra; đồng cảm; thấu cảm; cảm thấy gắn kết với ai đó qua cảm xúc hoặc trải nghiệm chung', 'v.', 'identification (n.), identifiable (adj.), identity (n.)', 'Đồng nghĩa: recognize, pinpoint', 'identify with ai đó mang nghĩa đồng cảm, không phải là nhận dạng đối phương.', 'Can you identify the bird sitting on our fence?', NULL, 'Bạn có nhận ra con chim đang đậu trên hàng rào nhà chúng ta không?', '{"wordId":"identify","ukIpa":"/aɪˈdentɪfaɪ/","usIpa":"/aɪˈdentɪfaɪ/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"To recognize and establish who or what someone or something is.","vi":"nhận diện; xác định danh tính của ai hoặc cái gì"},{"pos":"v.","en":"To discover or establish something through examination.","vi":"phát hiện hoặc xác định điều gì thông qua việc kiểm tra; tìm ra"},{"pos":"v.","en":"To feel connected to someone through shared feelings or experiences.","vi":"đồng cảm; thấu cảm; cảm thấy gắn kết với ai đó qua cảm xúc hoặc trải nghiệm chung"}],"examples":[{"en":"Can you identify the bird sitting on our fence?","vi":"Bạn có nhận ra con chim đang đậu trên hàng rào nhà chúng ta không?","audioKind":"ex"},{"en":"Schools should identify learning difficulties early so that students can receive appropriate support before falling behind.","vi":"Nhà trường nên sớm phát hiện các khó khăn trong học tập để học sinh nhận được sự hỗ trợ phù hợp trước khi bị tụt lại phía sau.","audioKind":"ex2"}],"collocations":[{"en":"identify a problem","vi":"phát hiện vấn đề"},{"en":"identify the cause","vi":"xác định nguyên nhân"},{"en":"identify someone as","vi":"nhận diện ai đó là"},{"en":"identify with","vi":"đồng cảm với"}],"wordFamily":["identification (n.)","identifiable (adj.)","identity (n.)"],"synonyms":["recognize","pinpoint"],"antonyms":[],"tipVi":"identify with ai đó mang nghĩa đồng cảm, không phải là nhận dạng đối phương.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consider', 'en-b1-26', 'consider', '/kənˈsɪdər/', 'B1', 'cân nhắc; suy nghĩ kỹ lưỡng trước khi quyết định; xem xét; có quan điểm hoặc đánh giá cụ thể về ai hoặc cái gì; để tâm đến; chiếu cố; tính đến yếu tố nào đó', 'v.', 'consideration (n.), considerate (adj.), considered (adj.)', 'Đồng nghĩa: contemplate, regard', '"Cân nhắc làm gì" dùng consider doing, không dùng consider to do.', 'We''re considering taking the train instead of driving tomorrow.', NULL, 'Chúng tôi đang cân nhắc đi tàu thay vì lái xe vào ngày mai.', '{"wordId":"consider","ukIpa":"/kənˈsɪdə/","usIpa":"/kənˈsɪdər/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"to think carefully about something before deciding","vi":"cân nhắc; suy nghĩ kỹ lưỡng trước khi quyết định"},{"pos":"v.","en":"to have a particular opinion about someone or something","vi":"xem xét; có quan điểm hoặc đánh giá cụ thể về ai hoặc cái gì"},{"pos":"v.","en":"to take someone or something into account","vi":"để tâm đến; chiếu cố; tính đến yếu tố nào đó"}],"examples":[{"en":"We''re considering taking the train instead of driving tomorrow.","vi":"Chúng tôi đang cân nhắc đi tàu thay vì lái xe vào ngày mai.","audioKind":"ex"},{"en":"Governments should consider the long-term environmental costs before approving major construction projects in sensitive coastal areas.","vi":"Chính phủ nên cân nhắc các chi phí môi trường lâu dài trước khi phê duyệt các dự án xây dựng lớn ở các vùng ven biển nhạy cảm.","audioKind":"ex2"}],"collocations":[{"en":"consider doing something","vi":"cân nhắc làm việc gì"},{"en":"consider the consequences","vi":"cân nhắc hậu quả"},{"en":"consider all options","vi":"xem xét mọi lựa chọn"},{"en":"be considered essential","vi":"được coi là thiết yếu"}],"wordFamily":["consideration (n.)","considerate (adj.)","considered (adj.)"],"synonyms":["contemplate","regard"],"antonyms":[],"tipVi":"\"Cân nhắc làm gì\" dùng consider doing, không dùng consider to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_26_1', 'en-b1-26', 'Cách dùng “uncertain” (adj.) — không chắc chắn; hoài nghi', 'uncertain about  ·  an uncertain future  ·  remain uncertain', 'Dùng ''uncertain about'' khi nói về sự thiếu chắc chắn của con người; dùng ''remain uncertain'' cho những việc chưa được định đoạt.', 'Họ từ (Word Family): certainty (n.), uncertainty (n.), certain (adj.), uncertainly (adv.) | Đồng nghĩa: unsure, doubtful · Trái nghĩa: certain, sure', '[{"hanzi":"I felt uncertain about which jacket to buy.","pinyin":"","meaning":"Tôi thấy phân vân không biết nên mua chiếc áo khoác nào."},{"hanzi":"The long-term effects of remote working remain uncertain, particularly for younger employees entering the labour market.","pinyin":"","meaning":"Ảnh hưởng lâu dài của việc làm việc từ xa vẫn chưa rõ ràng, đặc biệt đối với các nhân viên trẻ mới bước chân vào thị trường lao động."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_26_2', 'en-b1-26', 'Cách dùng “consist” (v.) — gồm có; bao gồm', 'consist of  ·  consist mainly of  ·  consist in', 'Cấu trúc consist of dùng để chỉ thành phần cấu thành và không dùng ở thể bị động; consist in dùng để chỉ bản chất cốt lõi.', NULL, '[{"hanzi":"Our picnic lunch consists of sandwiches, fruit, and juice.","pinyin":"","meaning":"Bữa trưa dã ngoại của chúng tôi gồm có bánh mì kẹp, trái cây và nước ép."},{"hanzi":"An effective recycling programme consists of convenient collection services and clear guidance for local residents.","pinyin":"","meaning":"Một chương trình tái chế hiệu quả bao gồm các dịch vụ thu gom thuận tiện và hướng dẫn rõ ràng cho cư dân địa phương."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_26_3', 'en-b1-26', 'Cách dùng “impression” (n.) — ấn tượng; cảm giác', 'first impression  ·  make an impression on  ·  be under the impression that', 'Cụm từ "under the impression that" có nghĩa là "tưởng rằng, cứ nghĩ rằng", thường hàm ý sự hiểu lầm.', 'Họ từ (Word Family): impress (v.), impressive (adj.), impressed (adj.)', '[{"hanzi":"Her warm welcome gave me a good first impression.","pinyin":"","meaning":"Sự chào đón nồng nhiệt của cô ấy đã để lại cho tôi ấn tượng ban đầu tốt đẹp."},{"hanzi":"The appearance of public spaces can strongly influence visitors'' overall impression of a city.","pinyin":"","meaning":"Diện mạo của các không gian công cộng có thể tác động mạnh mẽ đến ấn tượng chung của du khách về một thành phố."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_26_4', 'en-b1-26', 'Cách dùng “unknown” (adj.) — chưa biết; không rõ; không quen thuộc', 'remain unknown  ·  unknown to someone  ·  an unknown cause', 'Cụm từ "the unknown" dùng để chỉ chung các sự việc, hiện tượng hoặc lĩnh vực chưa được khám phá.', 'Họ từ (Word Family): know (v.), known (adj.), knowledge (n.) | Đồng nghĩa: unidentified, unfamiliar · Trái nghĩa: known', '[{"hanzi":"An unknown caller rang while I was cooking dinner.","pinyin":"","meaning":"Một số điện thoại lạ đã gọi đến khi tôi đang nấu bữa tối."},{"hanzi":"The long-term effects of some new materials remain unknown, so further research is essential before widespread use.","pinyin":"","meaning":"Tác động lâu dài của một số vật liệu mới vẫn chưa được rõ, vì vậy việc nghiên cứu thêm trước khi đưa vào sử dụng rộng rãi là vô cùng cần thiết."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_26_1', 'en-b1-26', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_1_1', 'ten_b1_26_1', 'definite', 'We need a definite answer before booking the tickets.', 'We need a definite answer before booking the tickets.', '/ˈdefɪnət/', 'Chúng ta cần một câu trả lời dứt khoát trước khi đặt vé.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_1_2', 'ten_b1_26_1', 'convince', 'The photos convinced me that the flat was spacious.', 'The photos convinced me that the flat was spacious.', '/kənˈvɪns/', 'Những bức ảnh đã thuyết phục tôi rằng căn hộ rất rộng rãi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_1_3', 'ten_b1_26_1', 'comparison', 'A quick comparison helped me choose the cheaper bicycle.', 'A quick comparison helped me choose the cheaper bicycle.', '/kəmˈpærɪsən/', 'Một phép so sánh nhanh đã giúp tôi chọn được chiếc xe đạp rẻ hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_1_4', 'ten_b1_26_1', 'mystery', 'Who left these flowers outside remains a mystery.', 'Who left these flowers outside remains a mystery.', '/ˈmɪstəri/', 'Ai đã để những bông hoa này ở bên ngoài đến nay vẫn là một điều bí ẩn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_1_5', 'ten_b1_26_1', 'unknown', 'An unknown caller rang while I was cooking dinner.', 'An unknown caller rang while I was cooking dinner.', '/ˌʌnˈnoʊn/', 'Một số điện thoại lạ đã gọi đến khi tôi đang nấu bữa tối.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_1_6', 'ten_b1_26_1', 'impression', 'Her warm welcome gave me a good first impression.', 'Her warm welcome gave me a good first impression.', '/ɪmˈpreʃən/', 'Sự chào đón nồng nhiệt của cô ấy đã để lại cho tôi ấn tượng ban đầu tốt đẹp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_1_7', 'ten_b1_26_1', 'category', 'Put each book into the category that fits best.', 'Put each book into the category that fits best.', '/ˈkætəɡɔːri/', 'Hãy xếp mỗi cuốn sách vào danh mục phù hợp nhất.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_1_8', 'ten_b1_26_1', 'attitude', 'His cheerful attitude makes even rainy mornings feel brighter.', 'His cheerful attitude makes even rainy mornings feel brighter.', '/ˈætɪtuːd/', 'Thái độ vui vẻ của anh ấy làm cho những buổi sáng mưa gió cũng trở nên tươi tắn hơn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_26_1_1', 'en-b1-26', 'ten_b1_26_1', 'listening', 'listening', 'We need a definite answer before booking the tickets.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Gợi ý của bạn nghe có vẻ hợp lý, vậy chúng ta hãy thử làm vào ngày mai nhé.","Việc giao hàng thất bại do thông tin địa chỉ của chúng tôi không chính xác.","Một số điện thoại lạ đã gọi đến khi tôi đang nấu bữa tối.","Chúng ta cần một câu trả lời dứt khoát trước khi đặt vé."]'::jsonb, 3, 'We need a definite answer before booking the tickets. → Chúng ta cần một câu trả lời dứt khoát trước khi đặt vé.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_26_1_2', 'en-b1-26', 'ten_b1_26_1', 'listening', 'listening', 'The photos convinced me that the flat was spacious.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn có nhận ra con chim đang đậu trên hàng rào nhà chúng ta không?","Công thức nấu ăn này trông có vẻ phức tạp, nhưng từng bước lại rất đơn giản.","Những bức ảnh đã thuyết phục tôi rằng căn hộ rất rộng rãi.","Những bức ảnh này chứng minh rằng con chó của chúng ta đã mở tủ chén."]'::jsonb, 2, 'The photos convinced me that the flat was spacious. → Những bức ảnh đã thuyết phục tôi rằng căn hộ rất rộng rãi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_26_1_3', 'en-b1-26', 'ten_b1_26_1', 'listening', 'listening', 'A quick comparison helped me choose the cheaper bicycle.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sự chào đón nồng nhiệt của cô ấy đã để lại cho tôi ấn tượng ban đầu tốt đẹp.","Tôi chợt nhận ra chìa khóa của mình vẫn ở trong nhà.","Một phép so sánh nhanh đã giúp tôi chọn được chiếc xe đạp rẻ hơn.","Con mèo của tôi tuân theo cùng một quy luật ngủ nghỉ mỗi ngày."]'::jsonb, 2, 'A quick comparison helped me choose the cheaper bicycle. → Một phép so sánh nhanh đã giúp tôi chọn được chiếc xe đạp rẻ hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_26_2', 'en-b1-26', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_2_1', 'ten_b1_26_2', 'definite', 'Reliable public transport offers definite advantages for cities seeking to reduce congestion and improve air quality.', 'Reliable public transport offers definite advantages for cities seeking to reduce congestion and improve air quality.', '/ˈdefɪnət/', 'Hệ thống giao thông công cộng đáng tin cậy mang lại những lợi thế rõ rệt cho các thành phố đang tìm cách giảm thiểu tình trạng ùn tắc và cải thiện chất lượng không khí.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_2_2', 'ten_b1_26_2', 'convince', 'Governments must convince residents that improved public transport offers a practical alternative to private cars.', 'Governments must convince residents that improved public transport offers a practical alternative to private cars.', '/kənˈvɪns/', 'Chính phủ phải làm cho người dân tin rằng giao thông công cộng được cải thiện mang lại một giải pháp thay thế thiết thực cho xe hơi cá nhân.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_2_3', 'ten_b1_26_2', 'comparison', 'A comparison of public transport systems reveals significant differences in cost, reliability and environmental impact.', 'A comparison of public transport systems reveals significant differences in cost, reliability and environmental impact.', '/kəmˈpærɪsən/', 'Việc so sánh các hệ thống giao thông công cộng cho thấy sự khác biệt đáng kể về chi phí, độ tin cậy và tác động đến môi trường.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_2_4', 'ten_b1_26_2', 'mystery', 'Despite advances in marine research, the behaviour of many deep ocean species remains a mystery.', 'Despite advances in marine research, the behaviour of many deep ocean species remains a mystery.', '/ˈmɪstəri/', 'Mặc dù nghiên cứu biển đã có nhiều tiến bộ, hành vi của nhiều loài ở tầng biển sâu vẫn là một điều bí ẩn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_2_5', 'ten_b1_26_2', 'unknown', 'The long-term effects of some new materials remain unknown, so further research is essential before widespread use.', 'The long-term effects of some new materials remain unknown, so further research is essential before widespread use.', '/ˌʌnˈnoʊn/', 'Tác động lâu dài của một số vật liệu mới vẫn chưa được rõ, vì vậy việc nghiên cứu thêm trước khi đưa vào sử dụng rộng rãi là vô cùng cần thiết.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_26_2_6', 'ten_b1_26_2', 'impression', 'The appearance of public spaces can strongly influence visitors'' overall impression of a city.', 'The appearance of public spaces can strongly influence visitors'' overall impression of a city.', '/ɪmˈpreʃən/', 'Diện mạo của các không gian công cộng có thể tác động mạnh mẽ đến ấn tượng chung của du khách về một thành phố.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_26_2_1', 'en-b1-26', 'ten_b1_26_2', 'listening', 'listening', 'Reliable public transport offers definite advantages for cities seeking to reduce congestion and improve air quality.', NULL, 'Trong câu vừa nghe, từ “definite” mang nghĩa nào sau đây?', '["rơm; rạ; cỏ khô","rõ ràng; chắc chắn","mê hoặc; đáng yêu; duyên dáng","lòng tốt; sự ân cần; sự tử tế"]'::jsonb, 1, '“definite” (/ˈdefɪnət/): rõ ràng; chắc chắn. Câu đầy đủ: Reliable public transport offers definite advantages for cities seeking to reduce congestion and improve air quality.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_26_2_2', 'en-b1-26', 'ten_b1_26_2', 'listening', 'listening', 'Governments must convince residents that improved public transport offers a practical alternative to private cars.', NULL, 'Trong câu vừa nghe, từ “convince” mang nghĩa nào sau đây?', '["nhẹ; không nặng (triệu chứng, ảnh hưởng)","tuyệt vời; xuất sắc","nhắc đến; đề cập","làm cho tin; thuyết phục"]'::jsonb, 3, '“convince” (/kənˈvɪns/): làm cho tin; thuyết phục. Câu đầy đủ: Governments must convince residents that improved public transport offers a practical alternative to private cars.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
