INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_2', 'en-b1-26', NULL, 'comprehensive_test', 'listening', 'The photos convinced me that the flat was spacious.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Gợi ý của bạn nghe có vẻ hợp lý, vậy chúng ta hãy thử làm vào ngày mai nhé.","Một phép so sánh nhanh đã giúp tôi chọn được chiếc xe đạp rẻ hơn.","Những bức ảnh đã thuyết phục tôi rằng căn hộ rất rộng rãi.","Con mèo của tôi tuân theo cùng một quy luật ngủ nghỉ mỗi ngày."]'::jsonb, 2, 'The photos convinced me that the flat was spacious. → Những bức ảnh đã thuyết phục tôi rằng căn hộ rất rộng rãi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_3', 'en-b1-26', NULL, 'comprehensive_test', 'listening', 'comparison', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự so sánh; sự đối chiếu","tiền phí dịch vụ; học phí; thù lao chuyên môn","hắt hơi; nhảy mũi","lạnh cóng; băng giá"]'::jsonb, 0, 'comparison (/kəmˈpærɪsən/) → sự so sánh; sự đối chiếu', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_4', 'en-b1-26', NULL, 'comprehensive_test', 'listening', 'Who left these flowers outside remains a mystery.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đi bộ xa hơn dọc theo bãi biển trước khi dừng lại.","Ai đã để những bông hoa này ở bên ngoài đến nay vẫn là một điều bí ẩn.","Tôi thấy phân vân không biết nên mua chiếc áo khoác nào.","Làm ơn vặn nhỏ nhạc lại để tôi có thể tập trung."]'::jsonb, 1, 'Who left these flowers outside remains a mystery. → Ai đã để những bông hoa này ở bên ngoài đến nay vẫn là một điều bí ẩn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_5', 'en-b1-26', NULL, 'comprehensive_test', 'listening', 'unknown', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chưa biết; không rõ; không quen thuộc","trầm cảm; chán nản, thất vọng","đơn giản, không có trang trí hoặc hoa văn","quý ông; người lịch sự"]'::jsonb, 0, 'unknown (/ˌʌnˈnoʊn/) → chưa biết; không rõ; không quen thuộc; điều chưa biết; người vô danh', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_6', 'en-b1-26', NULL, 'comprehensive_test', 'listening', 'Her warm welcome gave me a good first impression.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một số điện thoại lạ đã gọi đến khi tôi đang nấu bữa tối.","Bữa trưa dã ngoại của chúng tôi gồm có bánh mì kẹp, trái cây và nước ép.","Hãy xếp mỗi cuốn sách vào danh mục phù hợp nhất.","Sự chào đón nồng nhiệt của cô ấy đã để lại cho tôi ấn tượng ban đầu tốt đẹp."]'::jsonb, 3, 'Her warm welcome gave me a good first impression. → Sự chào đón nồng nhiệt của cô ấy đã để lại cho tôi ấn tượng ban đầu tốt đẹp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_7', 'en-b1-26', NULL, 'comprehensive_test', 'listening', 'category', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tạm thời; lâm thời","danh mục; thể loại; hạng","tỷ lệ; tốc độ","lau; chùi"]'::jsonb, 1, 'category (/ˈkætəɡɔːri/) → danh mục; thể loại; hạng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_8', 'en-b1-26', NULL, 'comprehensive_test', 'listening', 'His cheerful attitude makes even rainy mornings feel brighter.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bữa trưa dã ngoại của chúng tôi gồm có bánh mì kẹp, trái cây và nước ép.","Thái độ vui vẻ của anh ấy làm cho những buổi sáng mưa gió cũng trở nên tươi tắn hơn.","Một số điện thoại lạ đã gọi đến khi tôi đang nấu bữa tối.","Chúng ta cần một câu trả lời dứt khoát trước khi đặt vé."]'::jsonb, 1, 'His cheerful attitude makes even rainy mornings feel brighter. → Thái độ vui vẻ của anh ấy làm cho những buổi sáng mưa gió cũng trở nên tươi tắn hơn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
