INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_18', 'en-b1-26', NULL, 'comprehensive_test', 'reading', NULL, 'Reliable public transport offers definite advantages for cities seeking to reduce congestion and improve air quality.', 'Dựa vào câu trên, từ “definite” có nghĩa phù hợp nhất là gì?', '["người yêu; người thương","thợ điện; kỹ thuật viên điện","người trông trẻ; bảo mẫu tạm thời","rõ ràng; chắc chắn"]'::jsonb, 3, 'definite: rõ ràng; chắc chắn; rành mạch; thấy rõ. Dịch cả câu: Hệ thống giao thông công cộng đáng tin cậy mang lại những lợi thế rõ rệt cho các thành phố đang tìm cách giảm thiểu tình trạng ùn tắc và cải thiện chất lượng không khí.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_19', 'en-b1-26', NULL, 'comprehensive_test', 'reading', NULL, 'Governments must convince residents that improved public transport offers a practical alternative to private cars.', 'Dựa vào câu trên, từ “convince” có nghĩa phù hợp nhất là gì?', '["nhận diện; xác định danh tính của ai hoặc cái gì","xe trượt scooter","làm cho tin; thuyết phục","ở trong nhà, vào trong nhà (bên trong một tòa nhà)"]'::jsonb, 2, 'convince: làm cho tin; thuyết phục; thuyết phục (ai làm gì). Dịch cả câu: Chính phủ phải làm cho người dân tin rằng giao thông công cộng được cải thiện mang lại một giải pháp thay thế thiết thực cho xe hơi cá nhân.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_20', 'en-b1-26', NULL, 'comprehensive_test', 'reading', NULL, 'A comparison of public transport systems reveals significant differences in cost, reliability and environmental impact.', 'Dựa vào câu trên, từ “comparison” có nghĩa phù hợp nhất là gì?', '["kỳ lạ; quái lạ; bất thường","truyện hư cấu; tiểu thuyết","sự so sánh; sự đối chiếu","nhân viên văn phòng; thư ký; nhân viên lưu trữ hồ sơ"]'::jsonb, 2, 'comparison: sự so sánh; sự đối chiếu. Dịch cả câu: Việc so sánh các hệ thống giao thông công cộng cho thấy sự khác biệt đáng kể về chi phí, độ tin cậy và tác động đến môi trường.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_21', 'en-b1-26', NULL, 'comprehensive_test', 'reading', NULL, 'Despite advances in marine research, the behaviour of many deep ocean species remains a mystery.', 'Dựa vào câu trên, từ “mystery” có nghĩa phù hợp nhất là gì?', '["cái móc; móc treo","điều bí ẩn; điều chưa được giải đáp","sự so sánh; sự đối chiếu","lời khen ngợi; sự ca tụng"]'::jsonb, 1, 'mystery: điều bí ẩn; điều chưa được giải đáp; sự huyền bí; vẻ bí ẩn; truyện trinh thám; truyện trinh thám hồi hộp. Dịch cả câu: Mặc dù nghiên cứu biển đã có nhiều tiến bộ, hành vi của nhiều loài ở tầng biển sâu vẫn là một điều bí ẩn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_22', 'en-b1-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có liên quan; có dính líu”', '["category","freezing","stewardess","related"]'::jsonb, 3, 'có liên quan; có dính líu → related (/rɪˈleɪtɪd/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_23', 'en-b1-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhận diện; xác định danh tính của ai hoặc cái gì”', '["thunderstorm","classical","electrical","identify"]'::jsonb, 3, 'nhận diện; xác định danh tính của ai hoặc cái gì → identify (/aɪˈdentɪfaɪ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_26_24', 'en-b1-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cân nhắc; suy nghĩ kỹ lưỡng trước khi quyết định”', '["warmly","napkin","presentation","consider"]'::jsonb, 3, 'cân nhắc; suy nghĩ kỹ lưỡng trước khi quyết định → consider (/kənˈsɪdər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-27', 'en', 'Bài 27: Tư duy & Nhận thức (3) - CEFR B1', 'CEFR B1', 'B1 · Tư duy', '26 từ vựng Tiếng Anh CEFR B1 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3027, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obviously', 'en-b1-27', 'obviously', '/ˈɑːbviəsli/', 'B1', 'rõ ràng; hiển nhiên; dễ thấy', 'adv.', 'obvious (adj.)', 'Đồng nghĩa: clearly, evidently', 'Diễn đạt sự việc hiển nhiên; nên cẩn trọng khi dùng trong các cuộc tranh luận để tránh tỏ ra áp đặt.', 'The puppy was obviously tired after its long walk.', NULL, 'Chú chó con rõ ràng đã rất mệt sau chuyến đi dạo dài.', '{"wordId":"obviously","ukIpa":"/ˈɒbviəsli/","usIpa":"/ˈɑːbviəsli/","cefr":"B1","topic":"thinking","senses":[{"pos":"adv.","en":"in a way that is easy to see or understand","vi":"rõ ràng; hiển nhiên; dễ thấy"}],"examples":[{"en":"The puppy was obviously tired after its long walk.","vi":"Chú chó con rõ ràng đã rất mệt sau chuyến đi dạo dài.","audioKind":"ex"},{"en":"Although renewable energy obviously benefits the environment, its initial costs may discourage investment in poorer regions.","vi":"Mặc dù năng lượng tái tạo hiển nhiên mang lại lợi ích cho môi trường, chi phí ban đầu của nó có thể làm nản lòng các khoản đầu tư ở những vùng nghèo hơn.","audioKind":"ex2"}],"collocations":[{"en":"obviously pleased","vi":"rõ ràng là rất vui"},{"en":"obviously wrong","vi":"rõ ràng là sai"},{"en":"obviously important","vi":"hiển nhiên là quan trọng"}],"wordFamily":["obvious (adj.)"],"synonyms":["clearly","evidently"],"antonyms":[],"tipVi":"Diễn đạt sự việc hiển nhiên; nên cẩn trọng khi dùng trong các cuộc tranh luận để tránh tỏ ra áp đặt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indeed', 'en-b1-27', 'indeed', '/ɪnˈdiːd/', 'B1', 'thật vậy; quả thực; thực ra; thậm chí', 'adv.', NULL, 'Đồng nghĩa: certainly, truly', 'Có thể dùng very cộng tính từ cộng indeed để nhấn mạnh.', 'The soup was very tasty indeed, so I had more.', NULL, 'Món súp thực sự rất ngon, thế nên tôi đã ăn thêm.', '{"wordId":"indeed","ukIpa":"/ɪnˈdiːd/","usIpa":"/ɪnˈdiːd/","cefr":"B1","topic":"thinking","senses":[{"pos":"adv.","en":"Used to confirm something or emphasize that it is true.","vi":"thật vậy; quả thực"},{"pos":"adv.","en":"Used to add information that strengthens a previous statement.","vi":"thực ra; thậm chí"}],"examples":[{"en":"The soup was very tasty indeed, so I had more.","vi":"Món súp thực sự rất ngon, thế nên tôi đã ăn thêm.","audioKind":"ex"},{"en":"Public transport can reduce congestion; indeed, reliable bus services may persuade many commuters to stop driving.","vi":"Giao thông công cộng có thể làm giảm tình trạng tắc nghẽn; quả thực, dịch vụ xe buýt đáng tin cậy có thể thuyết phục nhiều người đi làm từ bỏ việc lái xe.","audioKind":"ex2"}],"collocations":[{"en":"very useful indeed","vi":"thực sự rất hữu ích"},{"en":"indeed the case","vi":"quả thực là như vậy"},{"en":"if indeed","vi":"nếu thực sự là thế"}],"wordFamily":[],"synonyms":["certainly","truly"],"antonyms":[],"tipVi":"Có thể dùng very cộng tính từ cộng indeed để nhấn mạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imagination', 'en-b1-27', 'imagination', '/ɪˌmædʒɪˈneɪʃən/', 'B1', 'trí tưởng tượng; sự tưởng tượng', 'n.', 'imagine (v.), imaginative (adj.), imaginary (adj.)', 'Đồng nghĩa: creativity', 'imaginative có nghĩa là giàu trí tưởng tượng; còn imaginary có nghĩa là tưởng tượng, không có thật.', 'With a little imagination, this box becomes a spaceship.', NULL, 'Chỉ cần một chút tưởng tượng, chiếc hộp này sẽ biến thành một con tàu vũ trụ.', '{"wordId":"imagination","ukIpa":"/ɪˌmædʒɪˈneɪʃən/","usIpa":"/ɪˌmædʒɪˈneɪʃən/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"The ability to form mental pictures or invent new ideas.","vi":"trí tưởng tượng; sự tưởng tượng"}],"examples":[{"en":"With a little imagination, this box becomes a spaceship.","vi":"Chỉ cần một chút tưởng tượng, chiếc hộp này sẽ biến thành một con tàu vũ trụ.","audioKind":"ex"},{"en":"Creative activities encourage children to use their imagination and approach unfamiliar problems from different perspectives.","vi":"Các hoạt động sáng tạo khuyến khích trẻ em phát huy trí tưởng tượng và tiếp cận các vấn đề lạ lẫm từ những góc độ khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"use your imagination","vi":"phát huy trí tưởng tượng"},{"en":"vivid imagination","vi":"trí tưởng tượng phong phú"},{"en":"capture the imagination","vi":"khơi gợi trí tưởng tượng"},{"en":"a figment of the imagination","vi":"sự tưởng tượng thuần túy"}],"wordFamily":["imagine (v.)","imaginative (adj.)","imaginary (adj.)"],"synonyms":["creativity"],"antonyms":[],"tipVi":"imaginative có nghĩa là giàu trí tưởng tượng; còn imaginary có nghĩa là tưởng tượng, không có thật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_challenge', 'en-b1-27', 'challenge', '/ˈtʃælɪndʒ/', 'B1', 'thử thách; nhiệm vụ khó khăn; chất vấn; hoài nghi; thách thức; khiêu chiến', 'n.', 'challenging (adj.), challenger (n.), unchallenged (adj.)', NULL, 'challenge khi làm động từ có thể đi thẳng với quan điểm để thể hiện sự chất vấn.', 'Cooking dinner for twelve guests was quite a challenge.', NULL, 'Nấu bữa tối cho mười hai vị khách thực sự là một thử thách lớn.', '{"wordId":"challenge","ukIpa":"/ˈtʃælɪndʒ/","usIpa":"/ˈtʃælɪndʒ/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"A difficult task or situation that tests someone''s abilities.","vi":"thử thách; nhiệm vụ khó khăn"},{"pos":"v.","en":"Question whether something is true, fair, or acceptable.","vi":"chất vấn; hoài nghi"},{"pos":"v.","en":"Invite someone to compete or test their abilities.","vi":"thách thức; khiêu chiến"}],"examples":[{"en":"Cooking dinner for twelve guests was quite a challenge.","vi":"Nấu bữa tối cho mười hai vị khách thực sự là một thử thách lớn.","audioKind":"ex"},{"en":"Providing affordable housing remains a major challenge for cities experiencing rapid population growth and rising land prices.","vi":"Việc cung cấp nhà ở giá rẻ vẫn là một thử thách lớn đối với các thành phố đang có tốc độ tăng trưởng dân số nhanh và giá đất leo thang.","audioKind":"ex2"}],"collocations":[{"en":"face a challenge","vi":"đối mặt với thử thách"},{"en":"meet a challenge","vi":"vượt qua thử thách"},{"en":"challenge an assumption","vi":"chất vấn một giả định"},{"en":"challenge someone to a contest","vi":"thách đấu ai đó"}],"wordFamily":["challenging (adj.)","challenger (n.)","unchallenged (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"challenge khi làm động từ có thể đi thẳng với quan điểm để thể hiện sự chất vấn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_confused', 'en-b1-27', 'confused', '/kənˈfjuːzd/', 'B1', 'bối rối; hoang mang; hỗn độn; khó hiểu', 'adj.', 'confuse (v.), confusion (n.), confusing (adj.)', 'Đồng nghĩa: puzzled, bewildered · Trái nghĩa: clear-headed', '"Confused" dùng để tả người cảm thấy bối rối; "confusing" dùng để tả sự việc gây hoang mang.', 'I felt confused when both doors led outside.', NULL, 'Tôi cảm thấy bối rối khi cả hai cánh cửa đều dẫn ra ngoài.', '{"wordId":"confused","ukIpa":"/kənˈfjuːzd/","usIpa":"/kənˈfjuːzd/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"unable to understand something or think clearly","vi":"bối rối; hoang mang"},{"pos":"adj.","en":"unclear or difficult to follow because of poor organisation","vi":"hỗn độn; khó hiểu"}],"examples":[{"en":"I felt confused when both doors led outside.","vi":"Tôi cảm thấy bối rối khi cả hai cánh cửa đều dẫn ra ngoài.","audioKind":"ex"},{"en":"Students may become confused if teachers introduce too many unfamiliar concepts in a single lesson.","vi":"Học sinh có thể trở nên bối rối nếu giáo viên đưa ra quá nhiều khái niệm lạ trong một bài học duy nhất.","audioKind":"ex2"}],"collocations":[{"en":"confused about","vi":"bối rối về"},{"en":"look confused","vi":"trông có vẻ bối rối"},{"en":"a confused account","vi":"một bản tường trình lộn xộn"}],"wordFamily":["confuse (v.)","confusion (n.)","confusing (adj.)"],"synonyms":["puzzled","bewildered"],"antonyms":["clear-headed"],"tipVi":"\"Confused\" dùng để tả người cảm thấy bối rối; \"confusing\" dùng để tả sự việc gây hoang mang.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wonder', 'en-b1-27', 'wonder', '/ˈwʌndər/', 'B1', 'tự hỏi; băn khoăn; sự kinh ngạc; sự thán phục; kỳ quan; điều kỳ diệu', 'v.', 'wonderful (adj.), wonderfully (adv.)', NULL, 'wonder khi đi sau với các từ để hỏi trong mệnh đề, hãy dùng trật tự câu khẳng định.', 'I wonder why the cat keeps watching that cupboard.', NULL, 'Tôi tự hỏi tại sao con mèo cứ nhìn chằm chằm vào chiếc tủ đó.', '{"wordId":"wonder","ukIpa":"/ˈwʌndə/","usIpa":"/ˈwʌndər/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"to think about something you do not know","vi":"tự hỏi; băn khoăn"},{"pos":"n.","en":"a feeling of surprise and admiration","vi":"sự kinh ngạc; sự thán phục"},{"pos":"n.","en":"something unusually impressive or surprising","vi":"kỳ quan; điều kỳ diệu"}],"examples":[{"en":"I wonder why the cat keeps watching that cupboard.","vi":"Tôi tự hỏi tại sao con mèo cứ nhìn chằm chằm vào chiếc tủ đó.","audioKind":"ex"},{"en":"Many parents wonder whether online lessons can provide the same social benefits as classroom learning.","vi":"Nhiều bậc phụ huynh tự hỏi liệu các bài học trực tuyến có thể mang lại những lợi ích xã hội giống như việc học trên lớp hay không.","audioKind":"ex2"}],"collocations":[{"en":"wonder whether","vi":"tự hỏi liệu"},{"en":"wonder about","vi":"tò mò về..."},{"en":"in wonder","vi":"trong sự kinh ngạc"},{"en":"natural wonders","vi":"kỳ quan thiên nhiên"}],"wordFamily":["wonderful (adj.)","wonderfully (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"wonder khi đi sau với các từ để hỏi trong mệnh đề, hãy dùng trật tự câu khẳng định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_positive', 'en-b1-27', 'positive', '/ˈpɑːzətɪv/', 'B1', 'lạc quan; tích cực; có ích; quả quyết; chắc chắn; dương tính; số dương', 'adj.', 'positively (adv.), positivity (n.)', 'Đồng nghĩa: optimistic, confident · Trái nghĩa: negative', 'Kết quả xét nghiệm positive chỉ dương tính, không hẳn là tin tốt.', 'She stayed positive even when rain spoiled our picnic.', NULL, 'Cô ấy vẫn giữ thái độ lạc quan ngay cả khi trời mưa làm hỏng buổi dã ngoại của chúng tôi.', '{"wordId":"positive","ukIpa":"/ˈpɒzətɪv/","usIpa":"/ˈpɑːzətɪv/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Hopeful, confident, or producing a good effect.","vi":"lạc quan; tích cực; có ích"},{"pos":"adj.","en":"Completely certain that something is true.","vi":"quả quyết; chắc chắn"},{"pos":"adj.","en":"Showing a condition is present, or mathematically greater than zero.","vi":"dương tính; số dương"}],"examples":[{"en":"She stayed positive even when rain spoiled our picnic.","vi":"Cô ấy vẫn giữ thái độ lạc quan ngay cả khi trời mưa làm hỏng buổi dã ngoại của chúng tôi.","audioKind":"ex"},{"en":"Regular contact with nature can have a positive effect on children''s emotional development and overall wellbeing.","vi":"Việc thường xuyên tiếp xúc với thiên nhiên có thể tác động tích cực đến sự phát triển cảm xúc và sức khỏe tổng thể của trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"positive attitude","vi":"thái độ tích cực"},{"en":"positive impact","vi":"tác động tích cực"},{"en":"positive result","vi":"kết quả dương tính; kết quả khả quan"}],"wordFamily":["positively (adv.)","positivity (n.)"],"synonyms":["optimistic","confident"],"antonyms":["negative"],"tipVi":"Kết quả xét nghiệm positive chỉ dương tính, không hẳn là tin tốt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recognise', 'en-b1-27', 'recognise', '/ˈrekəɡnaɪz/', 'B1', 'nhận ra; nhận biết; công nhận; thừa nhận; nhận thức; công nhận chính thức; biểu dương', 'v.', 'recognition (n.), recognisable (adj.), unrecognisable (adj.)', 'Đồng nghĩa: identify, acknowledge', 'recognise thường dùng trong tiếng Anh-Anh; tiếng Anh-Mỹ hay dùng recognize.', 'I recognised your brother immediately, despite his new haircut.', NULL, 'Tôi nhận ra anh trai bạn ngay lập tức, mặc dù anh ấy mới cắt tóc.', '{"wordId":"recognise","ukIpa":"/ˈrekəɡnaɪz/","usIpa":"/ˈrekəɡnaɪz/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"to identify someone or something known from before","vi":"nhận ra; nhận biết"},{"pos":"v.","en":"to accept or understand that something is true or important","vi":"công nhận; thừa nhận; nhận thức"},{"pos":"v.","en":"to officially accept something or honour someone''s achievements","vi":"công nhận chính thức; biểu dương"}],"examples":[{"en":"I recognised your brother immediately, despite his new haircut.","vi":"Tôi nhận ra anh trai bạn ngay lập tức, mặc dù anh ấy mới cắt tóc.","audioKind":"ex"},{"en":"Schools increasingly recognise that regular physical activity can improve both students'' health and academic performance.","vi":"Các trường học ngày càng nhận thức rõ rằng hoạt động thể chất thường xuyên có thể cải thiện cả sức khỏe lẫn thành tích học tập của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"recognise a face","vi":"nhận ra một khuôn mặt"},{"en":"recognise the importance of","vi":"nhận thức tầm quan trọng của"},{"en":"officially recognise","vi":"công nhận chính thức"}],"wordFamily":["recognition (n.)","recognisable (adj.)","unrecognisable (adj.)"],"synonyms":["identify","acknowledge"],"antonyms":[],"tipVi":"recognise thường dùng trong tiếng Anh-Anh; tiếng Anh-Mỹ hay dùng recognize.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wise', 'en-b1-27', 'wise', '/waɪz/', 'B1', 'sáng suốt; khôn ngoan', 'adj.', 'wisely (adv.), wisdom (n.), unwise (adj.)', 'Đồng nghĩa: sensible, prudent · Trái nghĩa: foolish, unwise', 'wise nhấn mạnh phán đoán khôn ngoan; clever nhấn mạnh sự thông minh, học nhanh.', 'Taking a warm coat was a wise decision today.', NULL, 'Mặc một chiếc áo khoác ấm áp là một quyết định sáng suốt vào ngày hôm nay.', '{"wordId":"wise","ukIpa":"/waɪz/","usIpa":"/waɪz/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Showing good judgment based on knowledge and experience.","vi":"sáng suốt; khôn ngoan"}],"examples":[{"en":"Taking a warm coat was a wise decision today.","vi":"Mặc một chiếc áo khoác ấm áp là một quyết định sáng suốt vào ngày hôm nay.","audioKind":"ex"},{"en":"It would be wise for governments to invest in preventive healthcare rather than rely solely on hospital treatment.","vi":"Chính phủ đầu tư vào y tế dự phòng thay vì chỉ dựa vào việc điều trị tại bệnh viện sẽ là một bước đi khôn ngoan.","audioKind":"ex2"}],"collocations":[{"en":"a wise decision","vi":"một quyết định sáng suốt"},{"en":"wise advice","vi":"lời khuyên khôn ngoan"},{"en":"wise to do something","vi":"khôn ngoan khi làm điều gì đó"}],"wordFamily":["wisely (adv.)","wisdom (n.)","unwise (adj.)"],"synonyms":["sensible","prudent"],"antonyms":["foolish","unwise"],"tipVi":"wise nhấn mạnh phán đoán khôn ngoan; clever nhấn mạnh sự thông minh, học nhanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_negative', 'en-b1-27', 'negative', '/ˈneɡətɪv/', 'B1', 'tiêu cực; bất lợi; phủ định; âm tính; số âm', 'adj.', 'negatively (adv.), negativity (n.), negate (v.)', 'Trái nghĩa: positive', 'Kết quả kiểm tra là negative nghĩa là không phát hiện thấy, không có nghĩa là kết quả xấu.', 'Her negative comments made me doubt my cooking skills.', NULL, 'Những lời bình luận tiêu cực của cô ấy khiến tôi nghi ngờ kỹ năng nấu nướng của mình.', '{"wordId":"negative","ukIpa":"/ˈneɡətɪv/","usIpa":"/ˈneɡətɪv/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"expressing pessimism or having a harmful effect","vi":"tiêu cực; bất lợi"},{"pos":"adj.","en":"expressing refusal or showing that something tested for is absent","vi":"phủ định; âm tính"},{"pos":"adj.","en":"less than zero","vi":"số âm"}],"examples":[{"en":"Her negative comments made me doubt my cooking skills.","vi":"Những lời bình luận tiêu cực của cô ấy khiến tôi nghi ngờ kỹ năng nấu nướng của mình.","audioKind":"ex"},{"en":"Heavy reliance on private cars can have negative effects on air quality and public health.","vi":"Việc phụ thuộc quá nhiều vào xe hơi cá nhân có thể gây ra những tác động bất lợi cho chất lượng không khí và sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"negative impact","vi":"tác động tiêu cực"},{"en":"negative attitude","vi":"thái độ tiêu cực"},{"en":"test negative for","vi":"xét nghiệm âm tính với"},{"en":"negative number","vi":"số âm"}],"wordFamily":["negatively (adv.)","negativity (n.)","negate (v.)"],"synonyms":[],"antonyms":["positive"],"tipVi":"Kết quả kiểm tra là negative nghĩa là không phát hiện thấy, không có nghĩa là kết quả xấu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_judge', 'en-b1-27', 'judge', '/dʒʌdʒ/', 'B1', 'đánh giá; phán đoán; thẩm phán; quan tòa; trọng tài; giám khảo', 'v.', 'judgement (n.), judgment (n.), judicial (adj.), judgemental (adj.)', 'Đồng nghĩa: assess, evaluate', 'Cấu trúc judge A by B nghĩa là đánh giá A dựa trên B.', 'Don''t judge the soup until you have tasted it.', NULL, 'Đừng vội đánh giá món súp cho đến khi bạn nếm thử nó.', '{"wordId":"judge","ukIpa":"/dʒʌdʒ/","usIpa":"/dʒʌdʒ/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"To form an opinion after considering someone or something.","vi":"đánh giá; phán đoán"},{"pos":"n.","en":"An official who oversees court proceedings and makes legal decisions.","vi":"thẩm phán; quan tòa"},{"pos":"n.","en":"Someone who assesses performances or decides the winner of a competition.","vi":"trọng tài; giám khảo"}],"examples":[{"en":"Don''t judge the soup until you have tasted it.","vi":"Đừng vội đánh giá món súp cho đến khi bạn nếm thử nó.","audioKind":"ex"},{"en":"Schools should judge students on a range of abilities rather than relying entirely on examination results.","vi":"Các trường học nên đánh giá học sinh dựa trên nhiều năng lực khác nhau thay vì phụ thuộc hoàn toàn vào kết quả thi cử.","audioKind":"ex2"}],"collocations":[{"en":"judge by appearances","vi":"trông mặt bắt hình dong"},{"en":"judge fairly","vi":"đánh giá công bằng"},{"en":"a panel of judges","vi":"hội đồng giám khảo"},{"en":"a court judge","vi":"thẩm phán tòa án"}],"wordFamily":["judgement (n.)","judgment (n.)","judicial (adj.)","judgemental (adj.)"],"synonyms":["assess","evaluate"],"antonyms":[],"tipVi":"Cấu trúc judge A by B nghĩa là đánh giá A dựa trên B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_complicated', 'en-b1-27', 'complicated', '/ˈkɑːmplɪkeɪtɪd/', 'B1', 'phức tạp; rắc rối', 'adj.', 'complicate (v.), complication (n.), uncomplicated (adj.)', 'Đồng nghĩa: complex, intricate · Trái nghĩa: simple, straightforward', 'nhấn mạnh sự phức tạp khó hiểu; complex cũng có thể chỉ đơn thuần là cấu trúc phức tạp.', 'This recipe is too complicated for a quick lunch.', NULL, 'Công thức nấu ăn này quá phức tạp cho một bữa trưa nhanh gọn.', '{"wordId":"complicated","ukIpa":"/ˈkɒmplɪkeɪtɪd/","usIpa":"/ˈkɑːmplɪkeɪtɪd/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Having many connected parts and therefore difficult to understand or manage.","vi":"phức tạp; rắc rối"}],"examples":[{"en":"This recipe is too complicated for a quick lunch.","vi":"Công thức nấu ăn này quá phức tạp cho một bữa trưa nhanh gọn.","audioKind":"ex"},{"en":"Complicated application procedures may discourage eligible students from seeking financial support for their university studies.","vi":"Thủ tục nộp đơn phức tạp có thể làm nản lòng những học sinh đủ điều kiện đang tìm kiếm sự hỗ trợ tài chính cho việc học đại học.","audioKind":"ex2"}],"collocations":[{"en":"complicated procedure","vi":"thủ tục phức tạp"},{"en":"complicated relationship","vi":"mối quan hệ phức tạp"},{"en":"highly complicated","vi":"hết sức phức tạp"}],"wordFamily":["complicate (v.)","complication (n.)","uncomplicated (adj.)"],"synonyms":["complex","intricate"],"antonyms":["simple","straightforward"],"tipVi":"nhấn mạnh sự phức tạp khó hiểu; complex cũng có thể chỉ đơn thuần là cấu trúc phức tạp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_doubt', 'en-b1-27', 'doubt', '/daʊt/', 'B1', 'sự nghi ngờ; sự hoài nghi; nghi ngờ; hoài nghi', 'n.', 'doubtful (adj.), doubtless (adv.), undoubtedly (adv.)', 'Đồng nghĩa: uncertainty, question · Trái nghĩa: certainty, trust', 'Chữ b không phát âm; I doubt that thường dùng để chỉ việc đánh giá một sự việc nào đó khó có khả năng xảy ra.', 'I doubt the shop is still open this late.', NULL, 'Tôi nghi ngờ rằng cửa hàng vẫn còn mở cửa vào muộn thế này.', '{"wordId":"doubt","ukIpa":"/daʊt/","usIpa":"/daʊt/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"A feeling of uncertainty about whether something is true or possible.","vi":"sự nghi ngờ; sự hoài nghi"},{"pos":"v.","en":"To feel uncertain about something or think it unlikely.","vi":"nghi ngờ; hoài nghi"}],"examples":[{"en":"I doubt the shop is still open this late.","vi":"Tôi nghi ngờ rằng cửa hàng vẫn còn mở cửa vào muộn thế này.","audioKind":"ex"},{"en":"There is little doubt that access to clean water is essential for improving public health.","vi":"Không còn nghi ngờ gì nữa rằng việc tiếp cận nước sạch là điều cốt yếu để cải thiện sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"have doubts about","vi":"có nghi ngờ về"},{"en":"no doubt","vi":"không còn nghi ngờ gì"},{"en":"cast doubt on","vi":"gây nghi ngờ cho"},{"en":"beyond doubt","vi":"ngoài vòng nghi ngờ"}],"wordFamily":["doubtful (adj.)","doubtless (adv.)","undoubtedly (adv.)"],"synonyms":["uncertainty","question"],"antonyms":["certainty","trust"],"tipVi":"Chữ b không phát âm; I doubt that thường dùng để chỉ việc đánh giá một sự việc nào đó khó có khả năng xảy ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_necessarily', 'en-b1-27', 'necessarily', '/ˌnesəˈserəli/', 'B1', 'tất yếu; nhất thiết; ắt là', 'adv.', 'necessary (adj.), necessity (n.), unnecessary (adj.)', 'Đồng nghĩa: inevitably', 'not necessarily có nghĩa là "không nhất thiết", không phải là "chắc chắn không".', 'An expensive coat is not necessarily a warmer one.', NULL, 'Một chiếc áo khoác đắt tiền chưa chắc đã là chiếc áo giữ ấm tốt hơn.', '{"wordId":"necessarily","ukIpa":"/ˈnesəsərɪli/","usIpa":"/ˌnesəˈserəli/","cefr":"B1","topic":"thinking","senses":[{"pos":"adv.","en":"As an unavoidable result or something that must be true","vi":"tất yếu; nhất thiết; ắt là"}],"examples":[{"en":"An expensive coat is not necessarily a warmer one.","vi":"Một chiếc áo khoác đắt tiền chưa chắc đã là chiếc áo giữ ấm tốt hơn.","audioKind":"ex"},{"en":"Economic growth does not necessarily improve living standards unless its benefits are shared widely across society.","vi":"Tăng trưởng kinh tế không nhất thiết làm nâng cao mức sống trừ khi các thành quả của nó được phân bổ rộng rãi trong toàn xã hội.","audioKind":"ex2"}],"collocations":[{"en":"not necessarily","vi":"không nhất thiết"},{"en":"necessarily involve","vi":"tất yếu liên quan đến"},{"en":"necessarily imply","vi":"tất yếu ngụ ý rằng"}],"wordFamily":["necessary (adj.)","necessity (n.)","unnecessary (adj.)"],"synonyms":["inevitably"],"antonyms":[],"tipVi":"not necessarily có nghĩa là \"không nhất thiết\", không phải là \"chắc chắn không\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_effective', 'en-b1-27', 'effective', '/ɪˈfektɪv/', 'B1', 'có hiệu quả; đem lại kết quả mong muốn; có hiệu lực; bắt đầu có hiệu lực; thực tế; trên thực tế', 'adj.', 'effect (n.), effectively (adv.), effectiveness (n.), ineffective (adj.)', 'Đồng nghĩa: successful · Trái nghĩa: ineffective', 'effective nhấn mạnh vào việc đạt được kết quả; efficient nhấn mạnh vào sự tiết kiệm thời gian và công sức.', 'This simple stretch is effective at easing shoulder tension.', NULL, 'Bài tập kéo giãn đơn giản này có hiệu quả trong việc làm giảm căng cứng ở vai.', '{"wordId":"effective","ukIpa":"/ɪˈfektɪv/","usIpa":"/ɪˈfektɪv/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"producing the intended or desired result","vi":"có hiệu quả; đem lại kết quả mong muốn"},{"pos":"adj.","en":"officially in force from a particular time","vi":"có hiệu lực; bắt đầu có hiệu lực"},{"pos":"adj.","en":"existing in practice, even if not officially recognised","vi":"thực tế; trên thực tế"}],"examples":[{"en":"This simple stretch is effective at easing shoulder tension.","vi":"Bài tập kéo giãn đơn giản này có hiệu quả trong việc làm giảm căng cứng ở vai.","audioKind":"ex"},{"en":"Effective environmental policies should combine clear regulations with financial incentives that encourage businesses to reduce waste.","vi":"Các chính sách môi trường hiệu quả nên kết hợp các quy định rõ ràng với các biện pháp khuyến khích tài chính nhằm thúc đẩy các doanh nghiệp giảm thiểu rác thải.","audioKind":"ex2"}],"collocations":[{"en":"effective treatment","vi":"phương pháp điều trị hiệu quả"},{"en":"effective in doing something","vi":"có hiệu quả trong việc làm gì"},{"en":"highly effective","vi":"rất hiệu quả"},{"en":"effective from","vi":"có hiệu lực từ"}],"wordFamily":["effect (n.)","effectively (adv.)","effectiveness (n.)","ineffective (adj.)"],"synonyms":["successful"],"antonyms":["ineffective"],"tipVi":"effective nhấn mạnh vào việc đạt được kết quả; efficient nhấn mạnh vào sự tiết kiệm thời gian và công sức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_realize', 'en-b1-27', 'realize', '/ˈriːəlaɪz/', 'B1', 'nhận thức được; hiểu rõ; thực hiện (ước mơ); biến (tiềm năng) thành hiện thực', 'v.', 'realization (n.), realizable (adj.), unrealized (adj.)', NULL, 'Trong tiếng Anh-Anh thường được viết là "realise"; khi mang nghĩa nhận thức sự việc có thể đi với mệnh đề "that".', 'I realized I had left my keys at home.', NULL, 'Tôi nhận ra rằng mình đã để quên chìa khóa ở nhà.', '{"wordId":"realize","ukIpa":"/ˈrɪəlaɪz/","usIpa":"/ˈriːəlaɪz/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"To become aware of something or understand it clearly","vi":"nhận thức được; hiểu rõ"},{"pos":"v.","en":"To make a hope happen or achieve possible success","vi":"thực hiện (ước mơ); biến (tiềm năng) thành hiện thực"}],"examples":[{"en":"I realized I had left my keys at home.","vi":"Tôi nhận ra rằng mình đã để quên chìa khóa ở nhà.","audioKind":"ex"},{"en":"Affordable training can help young people realize their potential and gain access to more rewarding careers.","vi":"Các khóa đào tạo có chi phí hợp lý có thể giúp người trẻ phát huy tiềm năng và tiếp cận với nhiều công việc có triển vọng hơn.","audioKind":"ex2"}],"collocations":[{"en":"realize that","vi":"nhận ra rằng"},{"en":"realize a dream","vi":"thực hiện giấc mơ"},{"en":"realize your potential","vi":"phát huy tiềm năng của bạn"},{"en":"fully realize","vi":"nhận thức đầy đủ"}],"wordFamily":["realization (n.)","realizable (adj.)","unrealized (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh thường được viết là \"realise\"; khi mang nghĩa nhận thức sự việc có thể đi với mệnh đề \"that\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_puzzle', 'en-b1-27', 'puzzle', '/ˈpʌzl/', 'B1', 'trò chơi trí tuệ; tranh ghép hình; điều khó hiểu; câu đố; làm bối rối; làm đau đầu', 'n.', 'puzzled (adj.), puzzling (adj.), puzzlement (n.)', NULL, 'puzzled dùng để chỉ người cảm thấy bối rối; puzzling dùng để chỉ sự vật gây bối rối.', 'We finished the puzzle together on the kitchen table.', NULL, 'Chúng tôi đã cùng nhau hoàn thành bức tranh ghép hình trên bàn bếp.', '{"wordId":"puzzle","ukIpa":"/ˈpʌzl/","usIpa":"/ˈpʌzl/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"A game or problem that tests your thinking skills.","vi":"trò chơi trí tuệ; tranh ghép hình"},{"pos":"n.","en":"Something that is difficult to understand or explain.","vi":"điều khó hiểu; câu đố"},{"pos":"v.","en":"To make someone feel confused because something is difficult to understand.","vi":"làm bối rối; làm đau đầu"}],"examples":[{"en":"We finished the puzzle together on the kitchen table.","vi":"Chúng tôi đã cùng nhau hoàn thành bức tranh ghép hình trên bàn bếp.","audioKind":"ex"},{"en":"The relationship between income and personal happiness remains a puzzle that researchers approach from several different perspectives.","vi":"Mối quan hệ giữa thu nhập và hạnh phúc cá nhân vẫn là một điều khó hiểu mà các nhà nghiên cứu tiếp cận từ nhiều góc độ khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"solve a puzzle","vi":"giải đố; giải câu đố"},{"en":"a jigsaw puzzle","vi":"trò chơi ghép hình"},{"en":"puzzle over something","vi":"suy nghĩ đắn đo về điều gì"},{"en":"a crossword puzzle","vi":"trò chơi ô chữ"}],"wordFamily":["puzzled (adj.)","puzzling (adj.)","puzzlement (n.)"],"synonyms":[],"antonyms":[],"tipVi":"puzzled dùng để chỉ người cảm thấy bối rối; puzzling dùng để chỉ sự vật gây bối rối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_differ', 'en-b1-27', 'differ', '/ˈdɪfər/', 'B1', 'khác biệt; không giống; bất đồng quan điểm; không đồng ý', 'v.', 'different (adj.), difference (n.), differently (adv.)', 'Đồng nghĩa: vary, disagree · Trái nghĩa: agree', 'Giới từ from dùng để dẫn ra đối tượng so sánh, còn in dùng để chỉ phương diện khác biệt.', 'These jackets differ in price, but both look great.', NULL, 'Những chiếc áo khoác này khác nhau về giá cả, nhưng cả hai đều rất đẹp.', '{"wordId":"differ","ukIpa":"/ˈdɪfə/","usIpa":"/ˈdɪfər/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"To be unlike something else in one or more ways.","vi":"khác biệt; không giống"},{"pos":"v.","en":"To have a different opinion from another person.","vi":"bất đồng quan điểm; không đồng ý"}],"examples":[{"en":"These jackets differ in price, but both look great.","vi":"Những chiếc áo khoác này khác nhau về giá cả, nhưng cả hai đều rất đẹp.","audioKind":"ex"},{"en":"Educational priorities differ between countries because economic conditions and cultural expectations shape national policies.","vi":"Các ưu tiên giáo dục khác nhau giữa các quốc gia vì điều kiện kinh tế và kỳ vọng văn hóa định hình chính sách quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"differ from","vi":"khác với"},{"en":"differ in size","vi":"khác nhau về kích thước"},{"en":"differ widely","vi":"khác biệt rất lớn"},{"en":"differ with someone","vi":"bất đồng ý kiến với ai đó"}],"wordFamily":["different (adj.)","difference (n.)","differently (adv.)"],"synonyms":["vary","disagree"],"antonyms":["agree"],"tipVi":"Giới từ from dùng để dẫn ra đối tượng so sánh, còn in dùng để chỉ phương diện khác biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surely', 'en-b1-27', 'surely', '/ˈʃʊrli/', 'B1', 'chẳng lẽ lại; chắc hẳn là; chắc chắn; nhất định', 'adv.', 'sure (adj.), sureness (n.)', 'Đồng nghĩa: certainly, undoubtedly', 'Là phó từ; đứng đầu câu thường thể hiện sự kỳ vọng người khác đồng tình.', 'Surely you can spare five minutes to help?', NULL, 'Chẳng lẽ cậu không thể bớt ra năm phút để giúp một tay sao?', '{"wordId":"surely","ukIpa":"/ˈʃʊəli/","usIpa":"/ˈʃʊrli/","cefr":"B1","topic":"thinking","senses":[{"pos":"adv.","en":"Used when expecting others to agree that something is true","vi":"chẳng lẽ lại; chắc hẳn là"},{"pos":"adv.","en":"Certainly, or in a way that will achieve a result","vi":"chắc chắn; nhất định"}],"examples":[{"en":"Surely you can spare five minutes to help?","vi":"Chẳng lẽ cậu không thể bớt ra năm phút để giúp một tay sao?","audioKind":"ex"},{"en":"Surely governments should prioritise clean drinking water before investing public money in expensive sports facilities.","vi":"Chính phủ chắc chắn nên ưu tiên nguồn nước uống sạch trước khi đầu tư tiền công quỹ vào các cơ sở thể thao đắt đỏ.","audioKind":"ex2"}],"collocations":[{"en":"surely not","vi":"chắc là không đâu"},{"en":"slowly but surely","vi":"chậm mà chắc"},{"en":"will surely lead to","vi":"chắc chắn sẽ dẫn đến"}],"wordFamily":["sure (adj.)","sureness (n.)"],"synonyms":["certainly","undoubtedly"],"antonyms":[],"tipVi":"Là phó từ; đứng đầu câu thường thể hiện sự kỳ vọng người khác đồng tình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_obvious', 'en-b1-27', 'obvious', '/ˈɑːbviəs/', 'B1', 'rõ ràng; hiển nhiên; dễ nhận thấy', 'adj.', 'obviously (adv.), obviousness (n.)', 'Đồng nghĩa: clear, evident, apparent · Trái nghĩa: unclear, hidden', 'Thường dùng cấu trúc It is obvious that… để diễn đạt ý "rõ ràng là…".', 'The muddy footprints made the dog''s hiding place obvious.', NULL, 'Những dấu chân bùn làm cho chỗ ẩn nấp của con chó trở nên rõ mồn một.', '{"wordId":"obvious","ukIpa":"/ˈɒbviəs/","usIpa":"/ˈɑːbviəs/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Easy to notice or understand.","vi":"rõ ràng; hiển nhiên; dễ nhận thấy"}],"examples":[{"en":"The muddy footprints made the dog''s hiding place obvious.","vi":"Những dấu chân bùn làm cho chỗ ẩn nấp của con chó trở nên rõ mồn một.","audioKind":"ex"},{"en":"The environmental benefits of cycling are obvious, but safer routes are needed to encourage more people to cycle.","vi":"Lợi ích môi trường của việc đi xe đạp là hiển nhiên, nhưng cần có những tuyến đường an toàn hơn để khuyến khích nhiều người đạp xe hơn.","audioKind":"ex2"}],"collocations":[{"en":"an obvious advantage","vi":"một lợi thế rõ ràng"},{"en":"for obvious reasons","vi":"vì những lý do hiển nhiên"},{"en":"obvious to everyone","vi":"ai cũng thấy rõ"}],"wordFamily":["obviously (adv.)","obviousness (n.)"],"synonyms":["clear","evident","apparent"],"antonyms":["unclear","hidden"],"tipVi":"Thường dùng cấu trúc It is obvious that… để diễn đạt ý \"rõ ràng là…\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sense', 'en-b1-27', 'sense', '/sens/', 'B1', 'giác quan; cảm giác; ý thức; cảm nhận; đánh hơi thấy', 'n.', 'sensory (adj.), sensible (adj.), sensitive (adj.)', NULL, 'make sense có nghĩa là hợp lý; make sense of có nghĩa là hiểu được.', 'Dogs have a much stronger sense of smell than humans.', NULL, 'Chó có khứu giác nhạy bén hơn nhiều so với con người.', '{"wordId":"sense","ukIpa":"/sens/","usIpa":"/sens/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"An ability to perceive through sight, hearing, touch, taste, or smell.","vi":"giác quan"},{"pos":"n.","en":"A feeling or awareness of something.","vi":"cảm giác; ý thức"},{"pos":"v.","en":"To become aware of something without being directly told.","vi":"cảm nhận; đánh hơi thấy"}],"examples":[{"en":"Dogs have a much stronger sense of smell than humans.","vi":"Chó có khứu giác nhạy bén hơn nhiều so với con người.","audioKind":"ex"},{"en":"Community gardens can strengthen residents'' sense of belonging by creating opportunities for regular social interaction.","vi":"Các khu vườn cộng đồng có thể củng cố ý thức thuộc về cộng đồng của cư dân bằng cách tạo ra cơ hội giaoi lưu xã hội thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"sense of smell","vi":"khứu giác"},{"en":"sense of belonging","vi":"cảm giác thuộc về"},{"en":"common sense","vi":"lẽ thường"},{"en":"make sense","vi":"có lý; hợp lý"}],"wordFamily":["sensory (adj.)","sensible (adj.)","sensitive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"make sense có nghĩa là hợp lý; make sense of có nghĩa là hiểu được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proof', 'en-b1-27', 'proof', '/pruːf/', 'B1', 'bằng chứng; chứng cứ; bản in thử; bản nháp kiểm tra; chống...; chịu được...', 'n.', 'prove (v.), proven (adj.), provable (adj.)', 'Đồng nghĩa: evidence', 'Khi chỉ bằng chứng, từ này thường không đếm được; với toán học thì dùng a proof.', 'Keep your receipt as proof that you paid.', NULL, 'Hãy giữ lấy hóa đơn của bạn như một bằng chứng thanh toán.', '{"wordId":"proof","ukIpa":"/pruːf/","usIpa":"/pruːf/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"Facts or information showing that something is true.","vi":"bằng chứng; chứng cứ"},{"pos":"n.","en":"A printed or digital copy checked before final publication.","vi":"bản in thử; bản nháp kiểm tra"},{"pos":"adj.","en":"Able to resist damage or effects from something.","vi":"chống...; chịu được..."}],"examples":[{"en":"Keep your receipt as proof that you paid.","vi":"Hãy giữ lấy hóa đơn của bạn như một bằng chứng thanh toán.","audioKind":"ex"},{"en":"Governments should require clear proof of a treatment''s effectiveness before allowing it to be widely marketed.","vi":"Chính phủ nên yêu cầu bằng chứng rõ ràng về hiệu quả của một phương pháp điều trị trước khi cho phép lưu hành rộng rãi trên thị trường.","audioKind":"ex2"}],"collocations":[{"en":"proof of identity","vi":"giấy tờ tùy thân"},{"en":"conclusive proof","vi":"bằng chứng xác thực"},{"en":"burden of proof","vi":"gánh nặng chứng minh"},{"en":"proof against","vi":"chống lại...; chịu được..."}],"wordFamily":["prove (v.)","proven (adj.)","provable (adj.)"],"synonyms":["evidence"],"antonyms":[],"tipVi":"Khi chỉ bằng chứng, từ này thường không đếm được; với toán học thì dùng a proof.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unlikely', 'en-b1-27', 'unlikely', '/ʌnˈlaɪkli/', 'B1', 'không có khả năng; khó xảy ra; đáng ngạc nhiên; khác thường', 'adj.', 'likely (adj.), likelihood (n.)', 'Đồng nghĩa: improbable · Trái nghĩa: likely, probable', 'Thường dùng cấu trúc be unlikely to do hoặc It is unlikely that.', 'With such dark clouds, sunshine seems unlikely this afternoon.', NULL, 'Với mây mù dày đặc thế này, chiều nay có vẻ khó có nắng.', '{"wordId":"unlikely","ukIpa":"/ʌnˈlaɪkli/","usIpa":"/ʌnˈlaɪkli/","cefr":"B1","topic":"thinking","senses":[{"pos":"adj.","en":"Not expected to happen or be true.","vi":"không có khả năng; khó xảy ra"},{"pos":"adj.","en":"Surprising because someone or something does not seem suitable.","vi":"đáng ngạc nhiên; khác thường"}],"examples":[{"en":"With such dark clouds, sunshine seems unlikely this afternoon.","vi":"Với mây mù dày đặc thế này, chiều nay có vẻ khó có nắng.","audioKind":"ex"},{"en":"Public transport use is unlikely to increase unless services become more reliable and affordable.","vi":"Việc sử dụng phương tiện giao thông công cộng khó có thể tăng lên trừ khi các dịch vụ trở nên đáng tin cậy và giá cả phải chăng hơn.","audioKind":"ex2"}],"collocations":[{"en":"unlikely to happen","vi":"khó xảy ra"},{"en":"highly unlikely","vi":"cực kỳ khó xảy ra"},{"en":"an unlikely friendship","vi":"một tình bạn đầy bất ngờ"}],"wordFamily":["likely (adj.)","likelihood (n.)"],"synonyms":["improbable"],"antonyms":["likely","probable"],"tipVi":"Thường dùng cấu trúc be unlikely to do hoặc It is unlikely that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_possibility', 'en-b1-27', 'possibility', '/ˌpɑːsəˈbɪləti/', 'B1', 'khả năng; khả năng có thể xảy ra; lựa chọn khả thi', 'n.', 'possible (adj.), possibly (adv.), impossible (adj.), impossibility (n.)', 'Đồng nghĩa: chance, prospect · Trái nghĩa: impossibility', 'Thường dùng cấu trúc possibility of doing hoặc mệnh đề với possibility that.', 'There is a possibility of snow later tonight.', NULL, 'Có khả năng sẽ có tuyết vào đêm nay.', '{"wordId":"possibility","ukIpa":"/ˌpɒsəˈbɪləti/","usIpa":"/ˌpɑːsəˈbɪləti/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"the chance that something might happen or be true","vi":"khả năng"},{"pos":"n.","en":"something that might happen or could be chosen","vi":"khả năng có thể xảy ra; lựa chọn khả thi"}],"examples":[{"en":"There is a possibility of snow later tonight.","vi":"Có khả năng sẽ có tuyết vào đêm nay.","audioKind":"ex"},{"en":"Improved public transport increases the possibility that commuters will leave their cars at home.","vi":"Hệ thống giao thông công cộng được cải thiện làm tăng khả năng những người đi làm sẽ để xe ở nhà.","audioKind":"ex2"}],"collocations":[{"en":"a real possibility","vi":"một khả năng có thật"},{"en":"the possibility of","vi":"khả năng xảy ra điều gì"},{"en":"explore the possibilities","vi":"khám phá các khả năng"},{"en":"rule out the possibility","vi":"loại trừ khả năng"}],"wordFamily":["possible (adj.)","possibly (adv.)","impossible (adj.)","impossibility (n.)"],"synonyms":["chance","prospect"],"antonyms":["impossibility"],"tipVi":"Thường dùng cấu trúc possibility of doing hoặc mệnh đề với possibility that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_importance', 'en-b1-27', 'importance', '/ɪmˈpɔːrtəns/', 'B1', 'tầm quan trọng; giá trị lớn', 'n.', 'important (adj.), importantly (adv.), unimportant (adj.)', 'Đồng nghĩa: significance · Trái nghĩa: insignificance', 'Importance là danh từ không đếm được; cụm từ diễn tả việc coi trọng việc gì là attach importance to.', 'Losing my keys taught me the importance of a spare.', NULL, 'Việc làm mất chìa khóa đã dạy tôi tầm quan trọng của việc có một chiếc chìa khóa dự phòng.', '{"wordId":"importance","ukIpa":"/ɪmˈpɔːtəns/","usIpa":"/ɪmˈpɔːrtəns/","cefr":"B1","topic":"thinking","senses":[{"pos":"n.","en":"The quality of having great value or a strong effect.","vi":"tầm quan trọng; giá trị lớn"}],"examples":[{"en":"Losing my keys taught me the importance of a spare.","vi":"Việc làm mất chìa khóa đã dạy tôi tầm quan trọng của việc có một chiếc chìa khóa dự phòng.","audioKind":"ex"},{"en":"Schools should emphasise the importance of critical thinking rather than focusing only on examination results.","vi":"Các trường học nên nhấn mạnh tầm quan trọng của tư duy phản biện thay vì chỉ tập trung vào kết quả thi cử.","audioKind":"ex2"}],"collocations":[{"en":"attach importance to","vi":"coi trọng; gắn tầm quan trọng cho"},{"en":"of great importance","vi":"có tầm quan trọng lớn"},{"en":"recognise the importance of","vi":"nhận thức tầm quan trọng của"}],"wordFamily":["important (adj.)","importantly (adv.)","unimportant (adj.)"],"synonyms":["significance"],"antonyms":["insignificance"],"tipVi":"Importance là danh từ không đếm được; cụm từ diễn tả việc coi trọng việc gì là attach importance to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_intend', 'en-b1-27', 'intend', '/ɪnˈtend/', 'B1', 'dự định; có ý định; có ý nghĩa; dành riêng cho mục đích nào đó', 'v.', 'intention (n.), intentional (adj.), intentionally (adv.), unintentional (adj.)', 'Đồng nghĩa: plan, mean', 'Cấu trúc intend to do có nghĩa là dự định làm gì; be intended for có nghĩa là dành riêng cho mục đích gì.', 'I intend to finish painting the kitchen this weekend.', NULL, 'Tôi dự định sẽ sơn xong phòng bếp vào cuối tuần này.', '{"wordId":"intend","ukIpa":"/ɪnˈtend/","usIpa":"/ɪnˈtend/","cefr":"B1","topic":"thinking","senses":[{"pos":"v.","en":"To have a plan or purpose in mind.","vi":"dự định; có ý định"},{"pos":"v.","en":"To mean something or design it for a particular purpose.","vi":"có ý nghĩa; dành riêng cho mục đích nào đó"}],"examples":[{"en":"I intend to finish painting the kitchen this weekend.","vi":"Tôi dự định sẽ sơn xong phòng bếp vào cuối tuần này.","audioKind":"ex"},{"en":"The council intends to expand public transport services to reduce dependence on private cars.","vi":"Hội đồng địa phương dự định mở rộng các dịch vụ giao thông công cộng để giảm sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"intend to do something","vi":"dự định làm điều gì"},{"en":"be intended for","vi":"dành cho (mục đích gì)"},{"en":"be intended to","vi":"nhằm mục đích"}],"wordFamily":["intention (n.)","intentional (adj.)","intentionally (adv.)","unintentional (adj.)"],"synonyms":["plan","mean"],"antonyms":[],"tipVi":"Cấu trúc intend to do có nghĩa là dự định làm gì; be intended for có nghĩa là dành riêng cho mục đích gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_27_1', 'en-b1-27', 'Cách dùng “realize” (v.) — nhận thức được; hiểu rõ', 'realize that  ·  realize a dream  ·  realize your potential', 'Trong tiếng Anh-Anh thường được viết là "realise"; khi mang nghĩa nhận thức sự việc có thể đi với mệnh đề "that".', 'Họ từ (Word Family): realization (n.), realizable (adj.), unrealized (adj.)', '[{"hanzi":"I realized I had left my keys at home.","pinyin":"","meaning":"Tôi nhận ra rằng mình đã để quên chìa khóa ở nhà."},{"hanzi":"Affordable training can help young people realize their potential and gain access to more rewarding careers.","pinyin":"","meaning":"Các khóa đào tạo có chi phí hợp lý có thể giúp người trẻ phát huy tiềm năng và tiếp cận với nhiều công việc có triển vọng hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_27_2', 'en-b1-27', 'Cách dùng “doubt” (n.) — sự nghi ngờ; sự hoài nghi', 'have doubts about  ·  no doubt  ·  cast doubt on', 'Chữ b không phát âm; I doubt that thường dùng để chỉ việc đánh giá một sự việc nào đó khó có khả năng xảy ra.', 'Họ từ (Word Family): doubtful (adj.), doubtless (adv.), undoubtedly (adv.) | Đồng nghĩa: uncertainty, question · Trái nghĩa: certainty, trust', '[{"hanzi":"I doubt the shop is still open this late.","pinyin":"","meaning":"Tôi nghi ngờ rằng cửa hàng vẫn còn mở cửa vào muộn thế này."},{"hanzi":"There is little doubt that access to clean water is essential for improving public health.","pinyin":"","meaning":"Không còn nghi ngờ gì nữa rằng việc tiếp cận nước sạch là điều cốt yếu để cải thiện sức khỏe cộng đồng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_27_3', 'en-b1-27', 'Cách dùng “effective” (adj.) — có hiệu quả; đem lại kết quả mong muốn', 'effective treatment  ·  effective in doing something  ·  highly effective', 'effective nhấn mạnh vào việc đạt được kết quả; efficient nhấn mạnh vào sự tiết kiệm thời gian và công sức.', 'Họ từ (Word Family): effect (n.), effectively (adv.), effectiveness (n.), ineffective (adj.) | Đồng nghĩa: successful · Trái nghĩa: ineffective', '[{"hanzi":"This simple stretch is effective at easing shoulder tension.","pinyin":"","meaning":"Bài tập kéo giãn đơn giản này có hiệu quả trong việc làm giảm căng cứng ở vai."},{"hanzi":"Effective environmental policies should combine clear regulations with financial incentives that encourage businesses to reduce waste.","pinyin":"","meaning":"Các chính sách môi trường hiệu quả nên kết hợp các quy định rõ ràng với các biện pháp khuyến khích tài chính nhằm thúc đẩy các doanh nghiệp giảm thiểu rác thải."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_27_4', 'en-b1-27', 'Cách dùng “intend” (v.) — dự định; có ý định', 'intend to do something  ·  be intended for  ·  be intended to', 'Cấu trúc intend to do có nghĩa là dự định làm gì; be intended for có nghĩa là dành riêng cho mục đích gì.', 'Họ từ (Word Family): intention (n.), intentional (adj.), intentionally (adv.), unintentional (adj.) | Đồng nghĩa: plan, mean', '[{"hanzi":"I intend to finish painting the kitchen this weekend.","pinyin":"","meaning":"Tôi dự định sẽ sơn xong phòng bếp vào cuối tuần này."},{"hanzi":"The council intends to expand public transport services to reduce dependence on private cars.","pinyin":"","meaning":"Hội đồng địa phương dự định mở rộng các dịch vụ giao thông công cộng để giảm sự phụ thuộc vào ô tô cá nhân."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_27_1', 'en-b1-27', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
