INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_27_1_2', 'ten_b1_27_1', 'indeed', 'The soup was very tasty indeed, so I had more.', 'The soup was very tasty indeed, so I had more.', '/ɪnˈdiːd/', 'Món súp thực sự rất ngon, thế nên tôi đã ăn thêm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_27_1_3', 'ten_b1_27_1', 'imagination', 'With a little imagination, this box becomes a spaceship.', 'With a little imagination, this box becomes a spaceship.', '/ɪˌmædʒɪˈneɪʃən/', 'Chỉ cần một chút tưởng tượng, chiếc hộp này sẽ biến thành một con tàu vũ trụ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_27_1_4', 'ten_b1_27_1', 'challenge', 'Cooking dinner for twelve guests was quite a challenge.', 'Cooking dinner for twelve guests was quite a challenge.', '/ˈtʃælɪndʒ/', 'Nấu bữa tối cho mười hai vị khách thực sự là một thử thách lớn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_27_1_5', 'ten_b1_27_1', 'confused', 'I felt confused when both doors led outside.', 'I felt confused when both doors led outside.', '/kənˈfjuːzd/', 'Tôi cảm thấy bối rối khi cả hai cánh cửa đều dẫn ra ngoài.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_27_1_6', 'ten_b1_27_1', 'wonder', 'I wonder why the cat keeps watching that cupboard.', 'I wonder why the cat keeps watching that cupboard.', '/ˈwʌndər/', 'Tôi tự hỏi tại sao con mèo cứ nhìn chằm chằm vào chiếc tủ đó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_27_1_7', 'ten_b1_27_1', 'positive', 'She stayed positive even when rain spoiled our picnic.', 'She stayed positive even when rain spoiled our picnic.', '/ˈpɑːzətɪv/', 'Cô ấy vẫn giữ thái độ lạc quan ngay cả khi trời mưa làm hỏng buổi dã ngoại của chúng tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_27_1_8', 'ten_b1_27_1', 'recognise', 'I recognised your brother immediately, despite his new haircut.', 'I recognised your brother immediately, despite his new haircut.', '/ˈrekəɡnaɪz/', 'Tôi nhận ra anh trai bạn ngay lập tức, mặc dù anh ấy mới cắt tóc.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_27_1_1', 'en-b1-27', 'ten_b1_27_1', 'listening', 'listening', 'The puppy was obviously tired after its long walk.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc làm mất chìa khóa đã dạy tôi tầm quan trọng của việc có một chiếc chìa khóa dự phòng.","Đừng vội đánh giá món súp cho đến khi bạn nếm thử nó.","Chú chó con rõ ràng đã rất mệt sau chuyến đi dạo dài.","Món súp thực sự rất ngon, thế nên tôi đã ăn thêm."]'::jsonb, 2, 'The puppy was obviously tired after its long walk. → Chú chó con rõ ràng đã rất mệt sau chuyến đi dạo dài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_27_1_2', 'en-b1-27', 'ten_b1_27_1', 'listening', 'listening', 'The soup was very tasty indeed, so I had more.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nấu bữa tối cho mười hai vị khách thực sự là một thử thách lớn.","Món súp thực sự rất ngon, thế nên tôi đã ăn thêm.","Tôi nghi ngờ rằng cửa hàng vẫn còn mở cửa vào muộn thế này.","Mặc một chiếc áo khoác ấm áp là một quyết định sáng suốt vào ngày hôm nay."]'::jsonb, 1, 'The soup was very tasty indeed, so I had more. → Món súp thực sự rất ngon, thế nên tôi đã ăn thêm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_27_1_3', 'en-b1-27', 'ten_b1_27_1', 'listening', 'listening', 'With a little imagination, this box becomes a spaceship.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Công thức nấu ăn này quá phức tạp cho một bữa trưa nhanh gọn.","Chỉ cần một chút tưởng tượng, chiếc hộp này sẽ biến thành một con tàu vũ trụ.","Việc làm mất chìa khóa đã dạy tôi tầm quan trọng của việc có một chiếc chìa khóa dự phòng.","Tôi tự hỏi tại sao con mèo cứ nhìn chằm chằm vào chiếc tủ đó."]'::jsonb, 1, 'With a little imagination, this box becomes a spaceship. → Chỉ cần một chút tưởng tượng, chiếc hộp này sẽ biến thành một con tàu vũ trụ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_27_2', 'en-b1-27', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_27_2_1', 'ten_b1_27_2', 'obviously', 'Although renewable energy obviously benefits the environment, its initial costs may discourage investment in poorer regions.', 'Although renewable energy obviously benefits the environment, its initial costs may discourage investment in poorer regions.', '/ˈɑːbviəsli/', 'Mặc dù năng lượng tái tạo hiển nhiên mang lại lợi ích cho môi trường, chi phí ban đầu của nó có thể làm nản lòng các khoản đầu tư ở những vùng nghèo hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_27_2_2', 'ten_b1_27_2', 'indeed', 'Public transport can reduce congestion; indeed, reliable bus services may persuade many commuters to stop driving.', 'Public transport can reduce congestion; indeed, reliable bus services may persuade many commuters to stop driving.', '/ɪnˈdiːd/', 'Giao thông công cộng có thể làm giảm tình trạng tắc nghẽn; quả thực, dịch vụ xe buýt đáng tin cậy có thể thuyết phục nhiều người đi làm từ bỏ việc lái xe.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_27_2_3', 'ten_b1_27_2', 'imagination', 'Creative activities encourage children to use their imagination and approach unfamiliar problems from different perspectives.', 'Creative activities encourage children to use their imagination and approach unfamiliar problems from different perspectives.', '/ɪˌmædʒɪˈneɪʃən/', 'Các hoạt động sáng tạo khuyến khích trẻ em phát huy trí tưởng tượng và tiếp cận các vấn đề lạ lẫm từ những góc độ khác nhau.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_27_2_4', 'ten_b1_27_2', 'challenge', 'Providing affordable housing remains a major challenge for cities experiencing rapid population growth and rising land prices.', 'Providing affordable housing remains a major challenge for cities experiencing rapid population growth and rising land prices.', '/ˈtʃælɪndʒ/', 'Việc cung cấp nhà ở giá rẻ vẫn là một thử thách lớn đối với các thành phố đang có tốc độ tăng trưởng dân số nhanh và giá đất leo thang.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_27_2_5', 'ten_b1_27_2', 'confused', 'Students may become confused if teachers introduce too many unfamiliar concepts in a single lesson.', 'Students may become confused if teachers introduce too many unfamiliar concepts in a single lesson.', '/kənˈfjuːzd/', 'Học sinh có thể trở nên bối rối nếu giáo viên đưa ra quá nhiều khái niệm lạ trong một bài học duy nhất.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_27_2_6', 'ten_b1_27_2', 'wonder', 'Many parents wonder whether online lessons can provide the same social benefits as classroom learning.', 'Many parents wonder whether online lessons can provide the same social benefits as classroom learning.', '/ˈwʌndər/', 'Nhiều bậc phụ huynh tự hỏi liệu các bài học trực tuyến có thể mang lại những lợi ích xã hội giống như việc học trên lớp hay không.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_27_2_1', 'en-b1-27', 'ten_b1_27_2', 'listening', 'listening', 'Although renewable energy obviously benefits the environment, its initial costs may discourage investment in poorer regions.', NULL, 'Trong câu vừa nghe, từ “obviously” mang nghĩa nào sau đây?', '["nông nghiệp; việc canh tác và chăn nuôi","rõ ràng; hiển nhiên; dễ thấy","ngô; bắp","quảng cáo; quảng bá"]'::jsonb, 1, '“obviously” (/ˈɑːbviəsli/): rõ ràng; hiển nhiên; dễ thấy. Câu đầy đủ: Although renewable energy obviously benefits the environment, its initial costs may discourage investment in poorer regions.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_27_2_2', 'en-b1-27', 'ten_b1_27_2', 'listening', 'listening', 'Public transport can reduce congestion; indeed, reliable bus services may persuade many commuters to stop driving.', NULL, 'Trong câu vừa nghe, từ “indeed” mang nghĩa nào sau đây?', '["cái kẹp; kẹp giấy","thật vậy; quả thực","vận động viên thi đấu môn quyền Anh","tình nguyện viên; người làm công tác thiện nguyện"]'::jsonb, 1, '“indeed” (/ɪnˈdiːd/): thật vậy; quả thực. Câu đầy đủ: Public transport can reduce congestion; indeed, reliable bus services may persuade many commuters to stop driving.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
