INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_1', 'en-b1-27', NULL, 'comprehensive_test', 'listening', 'obviously', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc về chính trị; chính trị","nơi làm việc; môi trường công sở","tủ gửi đồ; tủ có khóa (để đồ cá nhân)","rõ ràng; hiển nhiên; dễ thấy"]'::jsonb, 3, 'obviously (/ˈɑːbviəsli/) → rõ ràng; hiển nhiên; dễ thấy', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_2', 'en-b1-27', NULL, 'comprehensive_test', 'listening', 'The soup was very tasty indeed, so I had more.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy giữ lấy hóa đơn của bạn như một bằng chứng thanh toán.","Có khả năng sẽ có tuyết vào đêm nay.","Cô ấy vẫn giữ thái độ lạc quan ngay cả khi trời mưa làm hỏng buổi dã ngoại của chúng tôi.","Món súp thực sự rất ngon, thế nên tôi đã ăn thêm."]'::jsonb, 3, 'The soup was very tasty indeed, so I had more. → Món súp thực sự rất ngon, thế nên tôi đã ăn thêm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_3', 'en-b1-27', NULL, 'comprehensive_test', 'listening', 'imagination', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hầu như không; hầu như chẳng","chấm; điểm tròn nhỏ","vui vẻ; phấn khởi; lạc quan","trí tưởng tượng; sự tưởng tượng"]'::jsonb, 3, 'imagination (/ɪˌmædʒɪˈneɪʃən/) → trí tưởng tượng; sự tưởng tượng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_4', 'en-b1-27', NULL, 'comprehensive_test', 'listening', 'Cooking dinner for twelve guests was quite a challenge.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nấu bữa tối cho mười hai vị khách thực sự là một thử thách lớn.","Hãy giữ lấy hóa đơn của bạn như một bằng chứng thanh toán.","Chú chó con rõ ràng đã rất mệt sau chuyến đi dạo dài.","Công thức nấu ăn này quá phức tạp cho một bữa trưa nhanh gọn."]'::jsonb, 0, 'Cooking dinner for twelve guests was quite a challenge. → Nấu bữa tối cho mười hai vị khách thực sự là một thử thách lớn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_5', 'en-b1-27', NULL, 'comprehensive_test', 'listening', 'confused', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["rất; cực kỳ","phản ứng; ứng phó; có thái độ","bối rối; hoang mang","khổng lồ; to lớn; cực kỳ lớn"]'::jsonb, 2, 'confused (/kənˈfjuːzd/) → bối rối; hoang mang; hỗn độn; khó hiểu', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_6', 'en-b1-27', NULL, 'comprehensive_test', 'listening', 'I wonder why the cat keeps watching that cupboard.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi tự hỏi tại sao con mèo cứ nhìn chằm chằm vào chiếc tủ đó.","Chỉ cần một chút tưởng tượng, chiếc hộp này sẽ biến thành một con tàu vũ trụ.","Chú chó con rõ ràng đã rất mệt sau chuyến đi dạo dài.","Có khả năng sẽ có tuyết vào đêm nay."]'::jsonb, 0, 'I wonder why the cat keeps watching that cupboard. → Tôi tự hỏi tại sao con mèo cứ nhìn chằm chằm vào chiếc tủ đó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_7', 'en-b1-27', NULL, 'comprehensive_test', 'listening', 'positive', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chính trị; hoạt động chính trị","micrô; ống nói","lạc quan; tích cực; có ích","vùng; khu vực"]'::jsonb, 2, 'positive (/ˈpɑːzətɪv/) → lạc quan; tích cực; có ích; quả quyết; chắc chắn; dương tính; số dương', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_8', 'en-b1-27', NULL, 'comprehensive_test', 'listening', 'I recognised your brother immediately, despite his new haircut.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy vẫn giữ thái độ lạc quan ngay cả khi trời mưa làm hỏng buổi dã ngoại của chúng tôi.","Tôi nhận ra anh trai bạn ngay lập tức, mặc dù anh ấy mới cắt tóc.","Đừng vội đánh giá món súp cho đến khi bạn nếm thử nó.","Có khả năng sẽ có tuyết vào đêm nay."]'::jsonb, 1, 'I recognised your brother immediately, despite his new haircut. → Tôi nhận ra anh trai bạn ngay lập tức, mặc dù anh ấy mới cắt tóc.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_9', 'en-b1-27', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “unable to understand something or think clearly”?', '["judge","obviously","confused","imagination"]'::jsonb, 2, 'confused (/kənˈfjuːzd/) → bối rối; hoang mang', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_10', 'en-b1-27', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to think about something you do not know”?', '["wonder","imagination","importance","realize"]'::jsonb, 0, 'wonder (/ˈwʌndər/) → tự hỏi; băn khoăn', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_11', 'en-b1-27', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Hopeful, confident, or producing a good effect.”?', '["proof","positive","effective","judge"]'::jsonb, 1, 'positive (/ˈpɑːzətɪv/) → lạc quan; tích cực; có ích', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_12', 'en-b1-27', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to identify someone or something known from before”?', '["effective","recognise","possibility","importance"]'::jsonb, 1, 'recognise (/ˈrekəɡnaɪz/) → nhận ra; nhận biết', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
