INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_18', 'en-b1-27', NULL, 'comprehensive_test', 'reading', NULL, 'Although renewable energy obviously benefits the environment, its initial costs may discourage investment in poorer regions.', 'Dựa vào câu trên, từ “obviously” có nghĩa phù hợp nhất là gì?', '["tiêu đề; đề mục","khuấy; trộn","sọc; vạch; đường sọc","rõ ràng; hiển nhiên; dễ thấy"]'::jsonb, 3, 'obviously: rõ ràng; hiển nhiên; dễ thấy. Dịch cả câu: Mặc dù năng lượng tái tạo hiển nhiên mang lại lợi ích cho môi trường, chi phí ban đầu của nó có thể làm nản lòng các khoản đầu tư ở những vùng nghèo hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_19', 'en-b1-27', NULL, 'comprehensive_test', 'reading', NULL, 'Public transport can reduce congestion; indeed, reliable bus services may persuade many commuters to stop driving.', 'Dựa vào câu trên, từ “indeed” có nghĩa phù hợp nhất là gì?', '["trừ đi; khấu trừ","quá cân; thừa cân","niềm vui; sự thích thú","thật vậy; quả thực"]'::jsonb, 3, 'indeed: thật vậy; quả thực; thực ra; thậm chí. Dịch cả câu: Giao thông công cộng có thể làm giảm tình trạng tắc nghẽn; quả thực, dịch vụ xe buýt đáng tin cậy có thể thuyết phục nhiều người đi làm từ bỏ việc lái xe.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_20', 'en-b1-27', NULL, 'comprehensive_test', 'reading', NULL, 'Creative activities encourage children to use their imagination and approach unfamiliar problems from different perspectives.', 'Dựa vào câu trên, từ “imagination” có nghĩa phù hợp nhất là gì?', '["trí tưởng tượng; sự tưởng tượng","đạt được; giành được; hoàn thành","hối tiếc; ân hận","ăn mặc chỉn chu; ăn mặc lịch sự"]'::jsonb, 0, 'imagination: trí tưởng tượng; sự tưởng tượng. Dịch cả câu: Các hoạt động sáng tạo khuyến khích trẻ em phát huy trí tưởng tượng và tiếp cận các vấn đề lạ lẫm từ những góc độ khác nhau.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_21', 'en-b1-27', NULL, 'comprehensive_test', 'reading', NULL, 'Providing affordable housing remains a major challenge for cities experiencing rapid population growth and rising land prices.', 'Dựa vào câu trên, từ “challenge” có nghĩa phù hợp nhất là gì?', '["hứng thú; say mê; khao khát","thử thách; nhiệm vụ khó khăn","lợi nhuận; tiền lãi","múa ba-lê; vở múa ba-lê"]'::jsonb, 1, 'challenge: thử thách; nhiệm vụ khó khăn; chất vấn; hoài nghi; thách thức; khiêu chiến. Dịch cả câu: Việc cung cấp nhà ở giá rẻ vẫn là một thử thách lớn đối với các thành phố đang có tốc độ tăng trưởng dân số nhanh và giá đất leo thang.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_22', 'en-b1-27', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khả năng”', '["possibility","recover","fee","arrangement"]'::jsonb, 0, 'khả năng → possibility (/ˌpɑːsəˈbɪləti/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_23', 'en-b1-27', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tầm quan trọng; giá trị lớn”', '["practical","enjoyable","importance","contain"]'::jsonb, 2, 'tầm quan trọng; giá trị lớn → importance (/ɪmˈpɔːrtəns/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_27_24', 'en-b1-27', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dự định; có ý định”', '["intend","identify","peel","hire"]'::jsonb, 0, 'dự định; có ý định → intend (/ɪnˈtend/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-28', 'en', 'Bài 28: Cảm xúc & Tính cách (1) - CEFR B1', 'CEFR B1', 'B1 · Cảm xúc', '22 từ vựng Tiếng Anh CEFR B1 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3028, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amaze', 'en-b1-28', 'amaze', '/əˈmeɪz/', 'B1', 'làm kinh ngạc; làm ngạc nhiên', 'v.', 'amazed (adj.), amazing (adj.), amazement (n.), amazingly (adv.)', 'Đồng nghĩa: astonish, astound', 'Người cảm thấy kinh ngạc dùng amazed; sự vật gây kinh ngạc dùng amazing.', 'The magician''s clever tricks never fail to amaze the children.', NULL, 'Những trò ảo thuật khéo léo của nhà ảo thuật luôn làm cho lũ trẻ trầm trồ kinh ngạc.', '{"wordId":"amaze","ukIpa":"/əˈmeɪz/","usIpa":"/əˈmeɪz/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"to surprise someone very much","vi":"làm kinh ngạc; làm ngạc nhiên"}],"examples":[{"en":"The magician''s clever tricks never fail to amaze the children.","vi":"Những trò ảo thuật khéo léo của nhà ảo thuật luôn làm cho lũ trẻ trầm trồ kinh ngạc.","audioKind":"ex"},{"en":"Advances in medical technology continue to amaze researchers and offer new hope to patients with complex conditions.","vi":"Sự tiến bộ trong công nghệ y tế tiếp tục khiến các nhà nghiên cứu ngạc nhiên và thắp lên hy vọng mới cho những bệnh nhân mắc các bệnh phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"never cease to amaze","vi":"luôn làm kinh ngạc"},{"en":"amaze an audience","vi":"làm cho khán giả kinh ngạc"},{"en":"be amazed at","vi":"cảm thấy ngạc nhiên về"}],"wordFamily":["amazed (adj.)","amazing (adj.)","amazement (n.)","amazingly (adv.)"],"synonyms":["astonish","astound"],"antonyms":[],"tipVi":"Người cảm thấy kinh ngạc dùng amazed; sự vật gây kinh ngạc dùng amazing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_confidence', 'en-b1-28', 'confidence', '/ˈkɑːnfɪdəns/', 'B1', 'sự tự tin; niềm tin; sự tin tưởng; sự tín nhiệm', 'n.', 'confident (adj.), confidently (adv.), self-confidence (n.)', 'Đồng nghĩa: self-assurance, trust · Trái nghĩa: doubt, insecurity', 'Sử dụng cấu trúc confidence in khi muốn diễn tả niềm tin vào năng lực của ai đó hoặc sự chắc chắn về điều gì.', 'Practising with friends gave me confidence before the interview.', NULL, 'Việc luyện tập cùng bạn bè đã mang lại cho tôi sự tự tin trước buổi phỏng vấn.', '{"wordId":"confidence","ukIpa":"/ˈkɒnfɪdəns/","usIpa":"/ˈkɑːnfɪdəns/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"Belief in your abilities or in a successful outcome.","vi":"sự tự tin; niềm tin"},{"pos":"n.","en":"Trust that someone or something is reliable.","vi":"sự tin tưởng; sự tín nhiệm"}],"examples":[{"en":"Practising with friends gave me confidence before the interview.","vi":"Việc luyện tập cùng bạn bè đã mang lại cho tôi sự tự tin trước buổi phỏng vấn.","audioKind":"ex"},{"en":"Supportive feedback can build students'' confidence and encourage them to participate more actively in classroom discussions.","vi":"Phản hồi mang tính khích lệ có thể xây dựng sự tự tin cho học sinh và khuyến khích các em tham gia tích cực hơn vào các cuộc thảo luận trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"build confidence","vi":"gây dựng lòng tin"},{"en":"confidence in someone","vi":"sự tin tưởng đối với ai đó"},{"en":"lack confidence","vi":"thiếu sự tự tin"},{"en":"in confidence","vi":"giữ bí mật; nói riêng tư"}],"wordFamily":["confident (adj.)","confidently (adv.)","self-confidence (n.)"],"synonyms":["self-assurance","trust"],"antonyms":["doubt","insecurity"],"tipVi":"Sử dụng cấu trúc confidence in khi muốn diễn tả niềm tin vào năng lực của ai đó hoặc sự chắc chắn về điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_awesome', 'en-b1-28', 'awesome', '/ˈɔːsəm/', 'B1', 'tuyệt vời; cực kỳ thú vị; làm kinh ngạc; gây ngạc nhiên lớn; đáng sợ', 'adj.', 'awe (n.), awestruck (adj.)', 'Đồng nghĩa: amazing, fantastic', 'Khi dùng với nghĩa "siêu đỉnh/tuyệt vời", từ này mang tính khẩu ngữ; trong văn viết trang trọng nên chọn từ cụ thể hơn.', 'The mountain view from our tent was absolutely awesome.', NULL, 'Cảnh núi non nhìn từ lều của chúng tôi thực sự tuyệt vời.', '{"wordId":"awesome","ukIpa":"/ˈɔːsəm/","usIpa":"/ˈɔːsəm/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Extremely good or enjoyable.","vi":"tuyệt vời; cực kỳ thú vị"},{"pos":"adj.","en":"Causing great admiration, wonder, or sometimes fear.","vi":"làm kinh ngạc; gây ngạc nhiên lớn; đáng sợ"}],"examples":[{"en":"The mountain view from our tent was absolutely awesome.","vi":"Cảnh núi non nhìn từ lều của chúng tôi thực sự tuyệt vời.","audioKind":"ex"},{"en":"The awesome power of volcanic eruptions highlights the importance of effective monitoring systems in nearby communities.","vi":"Sức mạnh đáng kinh ngạc của các vụ phun trào núi lửa nhấn mạnh tầm quan trọng của các hệ thống giám sát hiệu quả ở các cộng đồng lân cận.","audioKind":"ex2"}],"collocations":[{"en":"an awesome experience","vi":"một trải nghiệm tuyệt vời"},{"en":"an awesome view","vi":"cảnh quan tuyệt đẹp"},{"en":"awesome power","vi":"sức mạnh đáng sợ"}],"wordFamily":["awe (n.)","awestruck (adj.)"],"synonyms":["amazing","fantastic"],"antonyms":[],"tipVi":"Khi dùng với nghĩa \"siêu đỉnh/tuyệt vời\", từ này mang tính khẩu ngữ; trong văn viết trang trọng nên chọn từ cụ thể hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sadness', 'en-b1-28', 'sadness', '/ˈsædnəs/', 'B1', 'nỗi buồn; sự đau buồn (cảm giác không vui, đặc biệt sau khi mất mát hoặc thất vọng)', 'n.', 'sad (adj.), sadly (adv.), sadden (v.)', 'Đồng nghĩa: sorrow, unhappiness · Trái nghĩa: happiness, joy', 'Thường là danh từ không đếm được; a sense of sadness chỉ một cảm giác buồn bã phảng phất.', 'She felt a deep sadness when her friend moved away.', NULL, 'Cô ấy cảm thấy một nỗi buồn sâu sắc khi người bạn thân chuyển đi nơi khác.', '{"wordId":"sadness","ukIpa":"/ˈsædnəs/","usIpa":"/ˈsædnəs/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"The feeling of being unhappy, especially after loss or disappointment.","vi":"nỗi buồn; sự đau buồn (cảm giác không vui, đặc biệt sau khi mất mát hoặc thất vọng)"}],"examples":[{"en":"She felt a deep sadness when her friend moved away.","vi":"Cô ấy cảm thấy một nỗi buồn sâu sắc khi người bạn thân chuyển đi nơi khác.","audioKind":"ex"},{"en":"Regular social contact can help reduce feelings of sadness among older people who live alone.","vi":"Giao social thường xuyên có thể giúp giảm bớt cảm giác buồn bã ở những người cao tuổi sống cô đơn.","audioKind":"ex2"}],"collocations":[{"en":"deep sadness","vi":"nỗi buồn sâu sắc"},{"en":"a sense of sadness","vi":"cảm giác buồn bã"},{"en":"overcome with sadness","vi":"chìm đắm trong đau buồn"}],"wordFamily":["sad (adj.)","sadly (adv.)","sadden (v.)"],"synonyms":["sorrow","unhappiness"],"antonyms":["happiness","joy"],"tipVi":"Thường là danh từ không đếm được; a sense of sadness chỉ một cảm giác buồn bã phảng phất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_embarrass', 'en-b1-28', 'embarrass', '/ɪmˈbærəs/', 'B1', 'làm cho lúng túng; làm ngượng ngùng; gây bối rối', 'v.', 'embarrassed (adj.), embarrassing (adj.), embarrassment (n.)', NULL, 'Dùng embarrassed khi chỉ cảm giác ngượng ngùng của con người; dùng embarrassing khi chỉ sự việc gây ngượng ngùng.', 'Please don''t embarrass me by sharing that childhood photo.', NULL, 'Đừng làm tôi ngượng bằng cách chia sẻ bức ảnh thời thơ ấu đó nhé.', '{"wordId":"embarrass","ukIpa":"/ɪmˈbærəs/","usIpa":"/ɪmˈbærəs/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"To make someone feel awkward, ashamed, or uncomfortable.","vi":"làm cho lúng túng; làm ngượng ngùng; gây bối rối"}],"examples":[{"en":"Please don''t embarrass me by sharing that childhood photo.","vi":"Đừng làm tôi ngượng bằng cách chia sẻ bức ảnh thời thơ ấu đó nhé.","audioKind":"ex"},{"en":"Correcting every mistake publicly can embarrass language learners and discourage them from participating in classroom discussions.","vi":"Việc công khai sửa mọi lỗi sai có thể khiến người học ngôn ngữ cảm thấy ngượng ngùng và nhụt chí tham gia vào các buổi thảo luận trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"embarrass someone","vi":"làm ai đó bối rối"},{"en":"deeply embarrassed","vi":"vô cùng lúng túng; cực kỳ ngượng ngùng"},{"en":"an embarrassing moment","vi":"một khoảnh khắc khó xử"}],"wordFamily":["embarrassed (adj.)","embarrassing (adj.)","embarrassment (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng embarrassed khi chỉ cảm giác ngượng ngùng của con người; dùng embarrassing khi chỉ sự việc gây ngượng ngùng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_incredible', 'en-b1-28', 'incredible', '/ɪnˈkredəbl/', 'B1', 'khó tin; kinh ngạc; tuyệt vời; cực kỳ lớn', 'adj.', 'incredibly (adv.), credible (adj.), credibility (n.)', 'Đồng nghĩa: unbelievable, amazing · Trái nghĩa: credible', 'incredible có thể dùng để chỉ điều khó tin, hoặc dùng trong văn nói để khen ngợi là "cực kỳ tốt".', 'It seems incredible that this tiny seed becomes a tree.', NULL, 'Thật khó tin khi hạt giống nhỏ xíu này lại có thể lớn lên thành một cái cây.', '{"wordId":"incredible","ukIpa":"/ɪnˈkredəbl/","usIpa":"/ɪnˈkredəbl/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"So surprising that it is difficult to believe","vi":"khó tin; kinh ngạc"},{"pos":"adj.","en":"Extremely good, impressive, or great in amount","vi":"tuyệt vời; cực kỳ lớn"}],"examples":[{"en":"It seems incredible that this tiny seed becomes a tree.","vi":"Thật khó tin khi hạt giống nhỏ xíu này lại có thể lớn lên thành một cái cây.","audioKind":"ex"},{"en":"Advances in medical technology have brought incredible improvements in the quality of life for many patients.","vi":"Những tiến bộ trong công nghệ y tế đã mang lại những cải thiện tuyệt vời về chất lượng cuộc sống cho rất nhiều bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"an incredible achievement","vi":"một thành tựu đáng kinh ngạc"},{"en":"an incredible amount","vi":"số lượng cực lớn"},{"en":"find it incredible","vi":"cảm thấy khó tin"}],"wordFamily":["incredibly (adv.)","credible (adj.)","credibility (n.)"],"synonyms":["unbelievable","amazing"],"antonyms":["credible"],"tipVi":"incredible có thể dùng để chỉ điều khó tin, hoặc dùng trong văn nói để khen ngợi là \"cực kỳ tốt\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scream', 'en-b1-28', 'scream', '/skriːm/', 'B1', 'gào thét; thét lên; tiếng thét; tiếng hét', 'v.', NULL, 'Đồng nghĩa: shriek', 'Scream nhấn mạnh âm thanh chói tai; shout chỉ nhấn mạnh việc nói to.', 'The children screamed with excitement as the ride began.', NULL, 'Bọn trẻ hò hét phấn khích ngay khi trò chơi bắt đầu.', '{"wordId":"scream","ukIpa":"/skriːm/","usIpa":"/skriːm/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"To give a loud, high cry from strong emotion.","vi":"gào thét; thét lên"},{"pos":"n.","en":"A loud, high cry expressing fear, pain, or excitement.","vi":"tiếng thét; tiếng hét"}],"examples":[{"en":"The children screamed with excitement as the ride began.","vi":"Bọn trẻ hò hét phấn khích ngay khi trò chơi bắt đầu.","audioKind":"ex"},{"en":"Residents complain that visitors scream late at night, disturbing sleep and reducing the neighbourhood''s quality of life.","vi":"Người dân phàn nàn rằng khách du lịch la hét vào đêm muộn, làm gián đoạn giấc ngủ và làm giảm chất lượng cuộc sống của khu1 phố.","audioKind":"ex2"}],"collocations":[{"en":"scream with excitement","vi":"hò hét vì phấn khích"},{"en":"scream for help","vi":"kêu cứu"},{"en":"let out a scream","vi":"phát ra một tiếng thét"}],"wordFamily":[],"synonyms":["shriek"],"antonyms":[],"tipVi":"Scream nhấn mạnh âm thanh chói tai; shout chỉ nhấn mạnh việc nói to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ashamed', 'en-b1-28', 'ashamed', '/əˈʃeɪmd/', 'B1', 'xấu hổ; hổ thẹn; ngại ngùng; e thẹn', 'adj.', 'shame (n.), shameful (adj.), shameless (adj.)', 'Trái nghĩa: proud', 'Thường đóng vai trò vị ngữ: be ashamed of hoặc be ashamed to do.', 'I felt ashamed after laughing at my friend''s mistake.', NULL, 'Tôi cảm thấy rất xấu hổ sau khi cười nhạo lỗi lầm của bạn mình.', '{"wordId":"ashamed","ukIpa":"/əˈʃeɪmd/","usIpa":"/əˈʃeɪmd/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"feeling guilty or embarrassed about something wrong or disappointing","vi":"xấu hổ; hổ thẹn"},{"pos":"adj.","en":"unwilling to do something because it feels embarrassing","vi":"ngại ngùng; e thẹn"}],"examples":[{"en":"I felt ashamed after laughing at my friend''s mistake.","vi":"Tôi cảm thấy rất xấu hổ sau khi cười nhạo lỗi lầm của bạn mình.","audioKind":"ex"},{"en":"Students should never feel ashamed to ask for help when they struggle with difficult subjects.","vi":"Học sinh không bao giờ nên cảm thấy xấu hổ khi nhờ giúp đỡ lúc gặp khó khăn với các môn học hóc búa.","audioKind":"ex2"}],"collocations":[{"en":"feel ashamed","vi":"cảm thấy hổ thẹn"},{"en":"ashamed of yourself","vi":"xấu hổ về bản thân"},{"en":"ashamed to admit","vi":"ngại ngùng không dám thừa nhận"}],"wordFamily":["shame (n.)","shameful (adj.)","shameless (adj.)"],"synonyms":[],"antonyms":["proud"],"tipVi":"Thường đóng vai trò vị ngữ: be ashamed of hoặc be ashamed to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nightmare', 'en-b1-28', 'nightmare', '/ˈnaɪtmer/', 'B1', 'cơn ác mộng; trải nghiệm tồi tệ; hoàn cảnh cực kỳ khó khăn', 'n.', 'nightmarish (adj.)', 'Đồng nghĩa: bad dream', 'Thường là danh từ đếm được; tính từ tương ứng là nightmarish.', 'I woke from a nightmare and switched on the lamp.', NULL, 'Tôi giật mình tỉnh dậy sau một cơn ác mộng và bật đèn lên.', '{"wordId":"nightmare","ukIpa":"/ˈnaɪtmeə/","usIpa":"/ˈnaɪtmer/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"a frightening or deeply unpleasant dream","vi":"cơn ác mộng"},{"pos":"n.","en":"an experience or situation that is extremely unpleasant or difficult","vi":"trải nghiệm tồi tệ; hoàn cảnh cực kỳ khó khăn"}],"examples":[{"en":"I woke from a nightmare and switched on the lamp.","vi":"Tôi giật mình tỉnh dậy sau một cơn ác mộng và bật đèn lên.","audioKind":"ex"},{"en":"Without reliable public transport, commuting can become a nightmare for people living outside major cities.","vi":"Nếu thiếu hệ thống giao thông công cộng đáng tin cậy, việc đi lại có thể trở thành một cơn ác mộng đối với những người sống ở ngoại ô thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"have a nightmare","vi":"gặp ác mộng"},{"en":"recurring nightmare","vi":"cơn ác mộng lặp đi lặp lại"},{"en":"logistical nightmare","vi":"bài toán khó về điều phối hậu cần"}],"wordFamily":["nightmarish (adj.)"],"synonyms":["bad dream"],"antonyms":[],"tipVi":"Thường là danh từ đếm được; tính từ tương ứng là nightmarish.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marvelous', 'en-b1-28', 'marvelous', '/ˈmɑːrvələs/', 'B1', 'tuyệt vời; kỳ diệu; gây ấn tượng mạnh', 'adj.', 'marvel (n.), marvel (v.), marvelously (adv.)', 'Đồng nghĩa: wonderful, excellent, splendid · Trái nghĩa: terrible', 'Marvelous là cách viết theo kiểu Mỹ; tiếng Anh-Anh thường viết là marvellous.', 'We had a marvelous view of the snowy mountains.', NULL, 'Chúng tôi có một tầm nhìn tuyệt đẹp ra những dãy núi phủ đầy tuyết.', '{"wordId":"marvelous","ukIpa":"/ˈmɑːvələs/","usIpa":"/ˈmɑːrvələs/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"extremely good or impressive","vi":"tuyệt vời; kỳ diệu; gây ấn tượng mạnh"}],"examples":[{"en":"We had a marvelous view of the snowy mountains.","vi":"Chúng tôi có một tầm nhìn tuyệt đẹp ra những dãy núi phủ đầy tuyết.","audioKind":"ex"},{"en":"Public libraries offer a marvelous opportunity for people of all ages to explore new interests.","vi":"Các thư viện công cộng mang lại cơ hội tuyệt vời cho mọi lứa tuổi khám phá các sở thích mới.","audioKind":"ex2"}],"collocations":[{"en":"a marvelous opportunity","vi":"một cơ hội tuyệt vời"},{"en":"a marvelous achievement","vi":"một thành tựu phi thường"},{"en":"a marvelous view","vi":"một khung cảnh tuyệt đẹp"}],"wordFamily":["marvel (n.)","marvel (v.)","marvelously (adv.)"],"synonyms":["wonderful","excellent","splendid"],"antonyms":["terrible"],"tipVi":"Marvelous là cách viết theo kiểu Mỹ; tiếng Anh-Anh thường viết là marvellous.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delighted', 'en-b1-28', 'delighted', '/dɪˈlaɪtɪd/', 'B1', 'rất vui mừng; hài lòng', 'adj.', 'delight (n.), delight (v.), delightful (adj.), delightfully (adv.)', 'Đồng nghĩa: thrilled, overjoyed · Trái nghĩa: disappointed', 'Con người cảm thấy vui dùng delighted; sự vật gây thích thú dùng delightful.', 'Lina was delighted to find her missing bracelet.', NULL, 'Lina rất vui mừng khi tìm thấy chiếc vòng tay bị mất của mình.', '{"wordId":"delighted","ukIpa":"/dɪˈlaɪtɪd/","usIpa":"/dɪˈlaɪtɪd/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"very pleased about something","vi":"rất vui mừng; hài lòng"}],"examples":[{"en":"Lina was delighted to find her missing bracelet.","vi":"Lina rất vui mừng khi tìm thấy chiếc vòng tay bị mất của mình.","audioKind":"ex"},{"en":"Residents were delighted with the new library, which offered free internet access and a welcoming space for study.","vi":"Cư dân vô cùng hài lòng với thư viện mới, nơi cung cấp dịch vụ internet miễn phí và một không gian học tập chào đón.","audioKind":"ex2"}],"collocations":[{"en":"delighted with the result","vi":"rất hài lòng với kết quả"},{"en":"delighted to hear","vi":"rất vui khi nghe tin"},{"en":"absolutely delighted","vi":"vui mừng khôn xiết"}],"wordFamily":["delight (n.)","delight (v.)","delightful (adj.)","delightfully (adv.)"],"synonyms":["thrilled","overjoyed"],"antonyms":["disappointed"],"tipVi":"Con người cảm thấy vui dùng delighted; sự vật gây thích thú dùng delightful.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mad', 'en-b1-28', 'mad', '/mæd/', 'B1', 'tức giận; nổi giận; mất trí; điên rồ; không hợp lý; say mê; cuồng nhiệt; cực kỳ thích thú', 'adj.', 'madly (adv.), madness (n.), madden (v.)', 'Đồng nghĩa: angry, furious', 'mad at thể hiện sự tức giận; mad about có thể thể hiện sự say mê, cuồng nhiệt.', 'Dad was mad because I broke his favourite cup.', NULL, 'Bố rất giận vì tôi đã làm vỡ chiếc cốc yêu thích của ông.', '{"wordId":"mad","ukIpa":"/mæd/","usIpa":"/mæd/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"very angry","vi":"tức giận; nổi giận"},{"pos":"adj.","en":"behaving or thinking in an unreasonable or foolish way","vi":"mất trí; điên rồ; không hợp lý"},{"pos":"adj.","en":"extremely enthusiastic about someone or something","vi":"say mê; cuồng nhiệt; cực kỳ thích thú"}],"examples":[{"en":"Dad was mad because I broke his favourite cup.","vi":"Bố rất giận vì tôi đã làm vỡ chiếc cốc yêu thích của ông.","audioKind":"ex"},{"en":"Although some residents are mad about football, public sports funding should support a wider range of activities.","vi":"Mặc dù một số cư dân cuồng nhiệt môn bóng đá, nguồn vốn tài trợ thể thao công cộng nên hỗ trợ cho nhiều hoạt động đa dạng hơn.","audioKind":"ex2"}],"collocations":[{"en":"get mad","vi":"nổi giận"},{"en":"mad at someone","vi":"giận ai đó"},{"en":"mad about football","vi":"cuồng bóng đá"},{"en":"drive someone mad","vi":"làm ai đó phát điên"}],"wordFamily":["madly (adv.)","madness (n.)","madden (v.)"],"synonyms":["angry","furious"],"antonyms":[],"tipVi":"mad at thể hiện sự tức giận; mad about có thể thể hiện sự say mê, cuồng nhiệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marvellous', 'en-b1-28', 'marvellous', '/ˈmɑːrvələs/', 'B1', 'tuyệt vời; tuyệt hảo; kỳ diệu; đáng ngưỡng mộ', 'adj.', 'marvel (n.), marvel (v.), marvellously (adv.)', 'Đồng nghĩa: wonderful, excellent, splendid · Trái nghĩa: awful, terrible', 'Cách viết theo kiểu Anh là marvellous, trong khi kiểu Mỹ thường là marvelous.', 'We had a marvellous picnic beside the lake.', NULL, 'Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ.', '{"wordId":"marvellous","ukIpa":"/ˈmɑːvələs/","usIpa":"/ˈmɑːrvələs/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Extremely good and very enjoyable.","vi":"tuyệt vời; tuyệt hảo"},{"pos":"adj.","en":"Causing great surprise or admiration.","vi":"kỳ diệu; đáng ngưỡng mộ"}],"examples":[{"en":"We had a marvellous picnic beside the lake.","vi":"Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ.","audioKind":"ex"},{"en":"Public gardens offer marvellous opportunities for urban residents to relax and reconnect with nature.","vi":"Các khu vườn công cộng mang đến những cơ hội tuyệt vời cho cư dân đô thị thư giãn và kết nối lại với thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"a marvellous idea","vi":"một ý tưởng tuyệt vời"},{"en":"a marvellous opportunity","vi":"một cơ hội tuyệt vời"},{"en":"a marvellous achievement","vi":"một thành tựu lớn"}],"wordFamily":["marvel (n.)","marvel (v.)","marvellously (adv.)"],"synonyms":["wonderful","excellent","splendid"],"antonyms":["awful","terrible"],"tipVi":"Cách viết theo kiểu Anh là marvellous, trong khi kiểu Mỹ thường là marvelous.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unforgettable', 'en-b1-28', 'unforgettable', '/ˌʌnfərˈɡetəbl/', 'B1', 'khó quên; không thể nào quên', 'adj.', 'forget (v.), forgettable (adj.), forgetful (adj.)', 'Đồng nghĩa: memorable · Trái nghĩa: forgettable', 'Dùng để chỉ trải nghiệm đáng nhớ; khác với forgetful nghĩa là hay quên.', 'Watching whales from the boat was an unforgettable experience.', NULL, 'Ngắm nhìn cá voi từ trên thuyền là một trải nghiệm khó quên.', '{"wordId":"unforgettable","ukIpa":"/ˌʌnfəˈɡetəbl/","usIpa":"/ˌʌnfərˈɡetəbl/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"so special or powerful that you will always remember it","vi":"khó quên; không thể nào quên"}],"examples":[{"en":"Watching whales from the boat was an unforgettable experience.","vi":"Ngắm nhìn cá voi từ trên thuyền là một trải nghiệm khó quên.","audioKind":"ex"},{"en":"School trips can provide unforgettable experiences that strengthen students'' understanding of history beyond the classroom.","vi":"Các chuyến tham quan của trường có thể mang lại những trải nghiệm khó quên, giúp học sinh củng cố hiểu biết về lịch sử ngoài không gian lớp học.","audioKind":"ex2"}],"collocations":[{"en":"an unforgettable experience","vi":"một trải nghiệm khó quên"},{"en":"an unforgettable moment","vi":"một khoảnh khắc khó quên"},{"en":"an unforgettable journey","vi":"một hành trình khó quên"}],"wordFamily":["forget (v.)","forgettable (adj.)","forgetful (adj.)"],"synonyms":["memorable"],"antonyms":["forgettable"],"tipVi":"Dùng để chỉ trải nghiệm đáng nhớ; khác với forgetful nghĩa là hay quên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hopefully', 'en-b1-28', 'hopefully', '/ˈhoʊpfəli/', 'B1', 'hy vọng rằng; mong sao; với vẻ hy vọng; tràn đầy hy vọng', 'adv.', 'hope (n.), hope (v.), hopeful (adj.), hopeless (adj.)', NULL, 'hopefully đứng đầu câu diễn tả điều mong ước, không đảm bảo chắc chắn sẽ xảy ra.', 'Hopefully, the weather will stay dry for our walk.', NULL, 'Hy vọng rằng thời tiết sẽ khô ráo để chúng ta đi dạo.', '{"wordId":"hopefully","ukIpa":"/ˈhəʊpfəli/","usIpa":"/ˈhoʊpfəli/","cefr":"B1","topic":"emotion","senses":[{"pos":"adv.","en":"Used to express what you hope will happen.","vi":"hy vọng rằng; mong sao"},{"pos":"adv.","en":"In a way that shows hope.","vi":"với vẻ hy vọng; tràn đầy hy vọng"}],"examples":[{"en":"Hopefully, the weather will stay dry for our walk.","vi":"Hy vọng rằng thời tiết sẽ khô ráo để chúng ta đi dạo.","audioKind":"ex"},{"en":"Hopefully, improvements in cycling infrastructure will encourage more residents to leave their cars at home.","vi":"Mong rằng những cải thiện về cơ sở hạ tầng dành cho xe đạp sẽ khuyến khích nhiều cư dân bỏ xe hơi ở nhà.","audioKind":"ex2"}],"collocations":[{"en":"hopefully soon","vi":"hy vọng sớm"},{"en":"look hopefully at","vi":"nhìn với vẻ kỳ vọng"},{"en":"wait hopefully","vi":"chờ đợi trong hy vọng"}],"wordFamily":["hope (n.)","hope (v.)","hopeful (adj.)","hopeless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"hopefully đứng đầu câu diễn tả điều mong ước, không đảm bảo chắc chắn sẽ xảy ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pity', 'en-b1-28', 'pity', '/ˈpɪti/', 'B1', 'lòng thương xót; sự đồng cảm; điều đáng tiếc; sự tiếc nuối; thương xót; cảm thông', 'n.', 'pitiful (adj.), pitiless (adj.)', 'Đồng nghĩa: compassion, sympathy', 'Khi mang nghĩa đồng cảm, pity thường không đếm được; khi mang nghĩa đáng tiếc, thường dùng a pity.', 'I felt pity for the puppy shivering in the rain.', NULL, 'Tôi cảm thấy thương xót cho chú chó con đang run lẩy bẩy dưới mưa.', '{"wordId":"pity","ukIpa":"/ˈpɪti/","usIpa":"/ˈpɪti/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"Sadness and concern for someone who is suffering.","vi":"lòng thương xót; sự đồng cảm"},{"pos":"n.","en":"Something disappointing or unfortunate.","vi":"điều đáng tiếc; sự tiếc nuối"},{"pos":"v.","en":"To feel sorry for someone because of their difficulties.","vi":"thương xót; cảm thông"}],"examples":[{"en":"I felt pity for the puppy shivering in the rain.","vi":"Tôi cảm thấy thương xót cho chú chó con đang run lẩy bẩy dưới mưa.","audioKind":"ex"},{"en":"It is a pity that many historic buildings are demolished before their cultural value is properly assessed.","vi":"Thật đáng tiếc khi nhiều tòa nhà lịch sử bị phá bỏ trước khi giá trị văn hóa của chúng được đánh giá đúng mức.","audioKind":"ex2"}],"collocations":[{"en":"feel pity for","vi":"cảm thấy thương xót cho"},{"en":"take pity on","vi":"động lòng trắc ẩn và giúp đỡ"},{"en":"what a pity","vi":"thật là đáng tiếc"},{"en":"a sense of pity","vi":"cảm giác xót xa"}],"wordFamily":["pitiful (adj.)","pitiless (adj.)"],"synonyms":["compassion","sympathy"],"antonyms":[],"tipVi":"Khi mang nghĩa đồng cảm, pity thường không đếm được; khi mang nghĩa đáng tiếc, thường dùng a pity.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sweetheart', 'en-b1-28', 'sweetheart', '/ˈswiːthɑːrt/', 'B1', 'người yêu; người thương; người tốt bụng; người nhiệt tình', 'n.', 'sweet (adj.), sweetness (n.)', 'Đồng nghĩa: darling, beloved', 'Có thể dùng để chỉ người yêu, hoặc dùng làm tiếng gọi thân mật; không nên tùy tiện dùng để gọi người lạ.', 'My sweetheart brought me flowers after a difficult day.', NULL, 'Người yêu của tôi đã mang hoa đến cho tôi sau một ngày mệt mỏi.', '{"wordId":"sweetheart","ukIpa":"/ˈswiːthɑːt/","usIpa":"/ˈswiːthɑːrt/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"someone you love, especially a romantic partner","vi":"người yêu; người thương"},{"pos":"n.","en":"a very kind and helpful person","vi":"người tốt bụng; người nhiệt tình"}],"examples":[{"en":"My sweetheart brought me flowers after a difficult day.","vi":"Người yêu của tôi đã mang hoa đến cho tôi sau một ngày mệt mỏi.","audioKind":"ex"},{"en":"Many older adults maintain strong emotional connections with sweethearts they first met during their school years.","vi":"Nhiều người cao tuổi vẫn duy trì mối quan hệ tình cảm bền chặt với những người yêu nhau từ thời đi học.","audioKind":"ex2"}],"collocations":[{"en":"childhood sweetheart","vi":"mối tình thanh mai trúc mã"},{"en":"be a sweetheart","vi":"người tốt bụng"}],"wordFamily":["sweet (adj.)","sweetness (n.)"],"synonyms":["darling","beloved"],"antonyms":[],"tipVi":"Có thể dùng để chỉ người yêu, hoặc dùng làm tiếng gọi thân mật; không nên tùy tiện dùng để gọi người lạ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scare', 'en-b1-28', 'scare', '/sker/', 'B1', 'làm cho ai đó sợ hãi; dọa; sự hoảng sợ; cơn hoảng hốt bất chợt', 'v.', 'scared (adj.), scary (adj.)', 'Đồng nghĩa: frighten, alarm · Trái nghĩa: reassure', 'scared dùng để chỉ người cảm thấy sợ hãi; scary dùng để chỉ sự vật gây sợ hãi.', 'Please knock gently so you don''t scare the baby.', NULL, 'Xin hãy gõ cửa nhẹ nhàng để không làm em bé giật mình.', '{"wordId":"scare","ukIpa":"/skeə/","usIpa":"/sker/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"to make someone feel frightened","vi":"làm cho ai đó sợ hãi; dọa"},{"pos":"n.","en":"a sudden feeling or period of fear","vi":"sự hoảng sợ; cơn hoảng hốt bất chợt"}],"examples":[{"en":"Please knock gently so you don''t scare the baby.","vi":"Xin hãy gõ cửa nhẹ nhàng để không làm em bé giật mình.","audioKind":"ex"},{"en":"Misleading reports about food safety can scare consumers and damage public confidence in local producers.","vi":"Các báo cáo gây hiểu lầm về an toàn thực phẩm có thể làm hoảng sợ người tiêu dùng và làm suy giảm niềm tin của công chúng đối với các nhà sản xuất địa phương.","audioKind":"ex2"}],"collocations":[{"en":"scare someone away","vi":"dọa cho ai đó bỏ chạy"},{"en":"give someone a scare","vi":"làm ai đó giật mình hoảng sợ"},{"en":"a health scare","vi":"cơn hoảng sợ về vấn đề sức khỏe"}],"wordFamily":["scared (adj.)","scary (adj.)"],"synonyms":["frighten","alarm"],"antonyms":["reassure"],"tipVi":"scared dùng để chỉ người cảm thấy sợ hãi; scary dùng để chỉ sự vật gây sợ hãi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disappoint', 'en-b1-28', 'disappoint', '/ˌdɪsəˈpɔɪnt/', 'B1', 'làm cho ai đó thất vọng vì không đáp ứng được kỳ vọng của họ', 'v.', 'disappointment (n.), disappointed (adj.), disappointing (adj.)', 'Đồng nghĩa: let down · Trái nghĩa: please, delight', 'Cảm giác thất vọng của con người dùng disappointed; sự vật gây thất vọng dùng disappointing.', 'I knew cancelling our picnic would disappoint the children.', NULL, 'Tôi biết việc hủy buổi dã ngoại sẽ làm lũ trẻ thất vọng.', '{"wordId":"disappoint","ukIpa":"/ˌdɪsəˈpɔɪnt/","usIpa":"/ˌdɪsəˈpɔɪnt/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"To make someone unhappy by failing to meet their expectations.","vi":"làm cho ai đó thất vọng vì không đáp ứng được kỳ vọng của họ"}],"examples":[{"en":"I knew cancelling our picnic would disappoint the children.","vi":"Tôi biết việc hủy buổi dã ngoại sẽ làm lũ trẻ thất vọng.","audioKind":"ex"},{"en":"Public transport improvements may disappoint commuters if services remain unreliable despite substantial investment in new vehicles.","vi":"Việc cải thiện giao thông công cộng có thể khiến những người đi làm thất vọng nếu chất lượng dịch vụ vẫn kém tin cậy bất chấp các khoản đầu tư lớn vào phương tiện mới.","audioKind":"ex2"}],"collocations":[{"en":"disappoint customers","vi":"làm khách hàng thất vọng"},{"en":"disappoint expectations","vi":"làm phụ lòng kỳ vọng"},{"en":"never disappoint","vi":"không bao giờ làm thất vọng"}],"wordFamily":["disappointment (n.)","disappointed (adj.)","disappointing (adj.)"],"synonyms":["let down"],"antonyms":["please","delight"],"tipVi":"Cảm giác thất vọng của con người dùng disappointed; sự vật gây thất vọng dùng disappointing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_annoyed', 'en-b1-28', 'annoyed', '/əˈnɔɪd/', 'B1', 'bực bội; khó chịu về một điều gì đó khó chịu hoặc bất tiện', 'adj.', 'annoy (v.), annoying (adj.), annoyance (n.)', 'Đồng nghĩa: irritated, bothered · Trái nghĩa: pleased', 'annoyed mô tả cảm xúc của con người; annoying mô tả sự việc gây bực bội.', 'Leila looked annoyed when the printer jammed again.', NULL, 'Leila trông có vẻ bực bội khi máy in lại bị kẹt giấy lần nữa.', '{"wordId":"annoyed","ukIpa":"/əˈnɔɪd/","usIpa":"/əˈnɔɪd/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"slightly angry about something unpleasant or inconvenient","vi":"bực bội; khó chịu về một điều gì đó khó chịu hoặc bất tiện"}],"examples":[{"en":"Leila looked annoyed when the printer jammed again.","vi":"Leila trông có vẻ bực bội khi máy in lại bị kẹt giấy lần nữa.","audioKind":"ex"},{"en":"Residents often become annoyed when construction noise continues late into the evening without prior warning.","vi":"Cư dân thường cảm thấy khó chịu khi tiếng ồn thi công kéo dài đến tận đêm muộn mà không có thông báo trước.","audioKind":"ex2"}],"collocations":[{"en":"annoyed with someone","vi":"bực mình với ai đó"},{"en":"annoyed about something","vi":"bực bội về điều gì đó"},{"en":"visibly annoyed","vi":"rõ ràng là đang bực mình"}],"wordFamily":["annoy (v.)","annoying (adj.)","annoyance (n.)"],"synonyms":["irritated","bothered"],"antonyms":["pleased"],"tipVi":"annoyed mô tả cảm xúc của con người; annoying mô tả sự việc gây bực bội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_calm', 'en-b1-28', 'calm', '/kɑːm/', 'B1', 'bình tĩnh; điềm tĩnh; làm cho bình tĩnh; xoa dịu; sự bình tĩnh; sự yên ả', 'adj.', 'calmly (adv.), calmness (n.), calming (adj.)', 'Đồng nghĩa: composed, peaceful · Trái nghĩa: agitated', 'chữ l trong calm không được phát âm; calm down nghĩa là bình tĩnh lại.', 'She stayed calm when the lights suddenly went out.', NULL, 'Cô ấy vẫn giữ được bình tĩnh khi đèn đột ngột vụt tắt.', '{"wordId":"calm","ukIpa":"/kɑːm/","usIpa":"/kɑːm/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Not worried or excited; without strong movement or disturbance.","vi":"bình tĩnh; điềm tĩnh"},{"pos":"v.","en":"To become less upset, or make someone feel more relaxed.","vi":"làm cho bình tĩnh; xoa dịu"},{"pos":"n.","en":"A peaceful state without worry, noise, or disturbance.","vi":"sự bình tĩnh; sự yên ả"}],"examples":[{"en":"She stayed calm when the lights suddenly went out.","vi":"Cô ấy vẫn giữ được bình tĩnh khi đèn đột ngột vụt tắt.","audioKind":"ex"},{"en":"A calm classroom atmosphere can help students concentrate and feel more confident about asking questions.","vi":"Bầu không khí lớp học bình tĩnh có thể giúp học sinh tập trung và cảm thấy tự tin hơn khi đặt câu hỏi.","audioKind":"ex2"}],"collocations":[{"en":"stay calm","vi":"giữ bình tĩnh"},{"en":"calm down","vi":"bình tĩnh lại"},{"en":"calm waters","vi":"mặt nước phẳng lặng"},{"en":"a sense of calm","vi":"cảm giác bình yên"}],"wordFamily":["calmly (adv.)","calmness (n.)","calming (adj.)"],"synonyms":["composed","peaceful"],"antonyms":["agitated"],"tipVi":"chữ l trong calm không được phát âm; calm down nghĩa là bình tĩnh lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_romantic', 'en-b1-28', 'romantic', '/roʊˈmæntɪk/', 'B1', 'lãng mạn; thuộc về tình yêu; lý tưởng hóa; không thực tế; người lãng mạn; người hay mộng mơ', 'adj.', 'romance (n.), romantically (adv.), romanticise (v.)', 'Trái nghĩa: unromantic', 'Ngoài nghĩa tình yêu, từ này cũng có thể chỉ việc nhìn nhận thực tế quá mức tốt đẹp.', 'They enjoyed a romantic dinner beside the quiet lake.', NULL, 'Họ đã tận hưởng một bữa tối lãng mạn bên hồ nước yên tĩnh.', '{"wordId":"romantic","ukIpa":"/rəʊˈmæntɪk/","usIpa":"/roʊˈmæntɪk/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"connected with love or expressing loving feelings","vi":"lãng mạn; thuộc về tình yêu"},{"pos":"adj.","en":"seeing things as more beautiful or exciting than they really are","vi":"lý tưởng hóa; không thực tế"},{"pos":"n.","en":"someone strongly influenced by love, imagination, or idealistic hopes","vi":"người lãng mạn; người hay mộng mơ"}],"examples":[{"en":"They enjoyed a romantic dinner beside the quiet lake.","vi":"Họ đã tận hưởng một bữa tối lãng mạn bên hồ nước yên tĩnh.","audioKind":"ex"},{"en":"Advertisements often present a romantic image of rural life while ignoring limited services and employment opportunities.","vi":"Quảng cáo thường vẽ ra một bức tranh lãng mạn về cuộc sống nông thôn trong khi phớt lờ những hạn chế về dịch vụ và cơ hội việc làm.","audioKind":"ex2"}],"collocations":[{"en":"romantic relationship","vi":"mối quan hệ yêu đương"},{"en":"romantic dinner","vi":"bữa tối lãng mạn"},{"en":"romantic comedy","vi":"phim hài tình cảm"},{"en":"a romantic view of","vi":"cái nhìn lý tưởng hóa về..."}],"wordFamily":["romance (n.)","romantically (adv.)","romanticise (v.)"],"synonyms":[],"antonyms":["unromantic"],"tipVi":"Ngoài nghĩa tình yêu, từ này cũng có thể chỉ việc nhìn nhận thực tế quá mức tốt đẹp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_28_1', 'en-b1-28', 'Cách dùng “awesome” (adj.) — tuyệt vời; cực kỳ thú vị', 'an awesome experience  ·  an awesome view  ·  awesome power', 'Khi dùng với nghĩa "siêu đỉnh/tuyệt vời", từ này mang tính khẩu ngữ; trong văn viết trang trọng nên chọn từ cụ thể hơn.', 'Họ từ (Word Family): awe (n.), awestruck (adj.) | Đồng nghĩa: amazing, fantastic', '[{"hanzi":"The mountain view from our tent was absolutely awesome.","pinyin":"","meaning":"Cảnh núi non nhìn từ lều của chúng tôi thực sự tuyệt vời."},{"hanzi":"The awesome power of volcanic eruptions highlights the importance of effective monitoring systems in nearby communities.","pinyin":"","meaning":"Sức mạnh đáng kinh ngạc của các vụ phun trào núi lửa nhấn mạnh tầm quan trọng của các hệ thống giám sát hiệu quả ở các cộng đồng lân cận."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_28_2', 'en-b1-28', 'Cách dùng “embarrass” (v.) — làm cho lúng túng; làm ngượng ngùng; gây bối rối', 'embarrass someone  ·  deeply embarrassed  ·  an embarrassing moment', 'Dùng embarrassed khi chỉ cảm giác ngượng ngùng của con người; dùng embarrassing khi chỉ sự việc gây ngượng ngùng.', 'Họ từ (Word Family): embarrassed (adj.), embarrassing (adj.), embarrassment (n.)', '[{"hanzi":"Please don''t embarrass me by sharing that childhood photo.","pinyin":"","meaning":"Đừng làm tôi ngượng bằng cách chia sẻ bức ảnh thời thơ ấu đó nhé."},{"hanzi":"Correcting every mistake publicly can embarrass language learners and discourage them from participating in classroom discussions.","pinyin":"","meaning":"Việc công khai sửa mọi lỗi sai có thể khiến người học ngôn ngữ cảm thấy ngượng ngùng và nhụt chí tham gia vào các buổi thảo luận trên lớp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_28_3', 'en-b1-28', 'Cách dùng “confidence” (n.) — sự tự tin; niềm tin', 'build confidence  ·  confidence in someone  ·  lack confidence', 'Sử dụng cấu trúc confidence in khi muốn diễn tả niềm tin vào năng lực của ai đó hoặc sự chắc chắn về điều gì.', 'Họ từ (Word Family): confident (adj.), confidently (adv.), self-confidence (n.) | Đồng nghĩa: self-assurance, trust · Trái nghĩa: doubt, insecurity', '[{"hanzi":"Practising with friends gave me confidence before the interview.","pinyin":"","meaning":"Việc luyện tập cùng bạn bè đã mang lại cho tôi sự tự tin trước buổi phỏng vấn."},{"hanzi":"Supportive feedback can build students'' confidence and encourage them to participate more actively in classroom discussions.","pinyin":"","meaning":"Phản hồi mang tính khích lệ có thể xây dựng sự tự tin cho học sinh và khuyến khích các em tham gia tích cực hơn vào các cuộc thảo luận trên lớp."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_28_4', 'en-b1-28', 'Cách dùng “sweetheart” (n.) — người yêu; người thương', 'childhood sweetheart  ·  be a sweetheart', 'Có thể dùng để chỉ người yêu, hoặc dùng làm tiếng gọi thân mật; không nên tùy tiện dùng để gọi người lạ.', 'Họ từ (Word Family): sweet (adj.), sweetness (n.) | Đồng nghĩa: darling, beloved', '[{"hanzi":"My sweetheart brought me flowers after a difficult day.","pinyin":"","meaning":"Người yêu của tôi đã mang hoa đến cho tôi sau một ngày mệt mỏi."},{"hanzi":"Many older adults maintain strong emotional connections with sweethearts they first met during their school years.","pinyin":"","meaning":"Nhiều người cao tuổi vẫn duy trì mối quan hệ tình cảm bền chặt với những người yêu nhau từ thời đi học."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_28_1', 'en-b1-28', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_1_1', 'ten_b1_28_1', 'amaze', 'The magician''s clever tricks never fail to amaze the children.', 'The magician''s clever tricks never fail to amaze the children.', '/əˈmeɪz/', 'Những trò ảo thuật khéo léo của nhà ảo thuật luôn làm cho lũ trẻ trầm trồ kinh ngạc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_1_2', 'ten_b1_28_1', 'confidence', 'Practising with friends gave me confidence before the interview.', 'Practising with friends gave me confidence before the interview.', '/ˈkɑːnfɪdəns/', 'Việc luyện tập cùng bạn bè đã mang lại cho tôi sự tự tin trước buổi phỏng vấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_1_3', 'ten_b1_28_1', 'awesome', 'The mountain view from our tent was absolutely awesome.', 'The mountain view from our tent was absolutely awesome.', '/ˈɔːsəm/', 'Cảnh núi non nhìn từ lều của chúng tôi thực sự tuyệt vời.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_1_4', 'ten_b1_28_1', 'sadness', 'She felt a deep sadness when her friend moved away.', 'She felt a deep sadness when her friend moved away.', '/ˈsædnəs/', 'Cô ấy cảm thấy một nỗi buồn sâu sắc khi người bạn thân chuyển đi nơi khác.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_1_5', 'ten_b1_28_1', 'embarrass', 'Please don''t embarrass me by sharing that childhood photo.', 'Please don''t embarrass me by sharing that childhood photo.', '/ɪmˈbærəs/', 'Đừng làm tôi ngượng bằng cách chia sẻ bức ảnh thời thơ ấu đó nhé.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_1_6', 'ten_b1_28_1', 'incredible', 'It seems incredible that this tiny seed becomes a tree.', 'It seems incredible that this tiny seed becomes a tree.', '/ɪnˈkredəbl/', 'Thật khó tin khi hạt giống nhỏ xíu này lại có thể lớn lên thành một cái cây.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_1_7', 'ten_b1_28_1', 'scream', 'The children screamed with excitement as the ride began.', 'The children screamed with excitement as the ride began.', '/skriːm/', 'Bọn trẻ hò hét phấn khích ngay khi trò chơi bắt đầu.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_1_8', 'ten_b1_28_1', 'ashamed', 'I felt ashamed after laughing at my friend''s mistake.', 'I felt ashamed after laughing at my friend''s mistake.', '/əˈʃeɪmd/', 'Tôi cảm thấy rất xấu hổ sau khi cười nhạo lỗi lầm của bạn mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_28_1_1', 'en-b1-28', 'ten_b1_28_1', 'listening', 'listening', 'The magician''s clever tricks never fail to amaze the children.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những trò ảo thuật khéo léo của nhà ảo thuật luôn làm cho lũ trẻ trầm trồ kinh ngạc.","Tôi cảm thấy rất xấu hổ sau khi cười nhạo lỗi lầm của bạn mình.","Tôi giật mình tỉnh dậy sau một cơn ác mộng và bật đèn lên.","Ngắm nhìn cá voi từ trên thuyền là một trải nghiệm khó quên."]'::jsonb, 0, 'The magician''s clever tricks never fail to amaze the children. → Những trò ảo thuật khéo léo của nhà ảo thuật luôn làm cho lũ trẻ trầm trồ kinh ngạc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_28_1_2', 'en-b1-28', 'ten_b1_28_1', 'listening', 'listening', 'Practising with friends gave me confidence before the interview.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Leila trông có vẻ bực bội khi máy in lại bị kẹt giấy lần nữa.","Cảnh núi non nhìn từ lều của chúng tôi thực sự tuyệt vời.","Việc luyện tập cùng bạn bè đã mang lại cho tôi sự tự tin trước buổi phỏng vấn.","Hy vọng rằng thời tiết sẽ khô ráo để chúng ta đi dạo."]'::jsonb, 2, 'Practising with friends gave me confidence before the interview. → Việc luyện tập cùng bạn bè đã mang lại cho tôi sự tự tin trước buổi phỏng vấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_28_1_3', 'en-b1-28', 'ten_b1_28_1', 'listening', 'listening', 'The mountain view from our tent was absolutely awesome.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bố rất giận vì tôi đã làm vỡ chiếc cốc yêu thích của ông.","Cảnh núi non nhìn từ lều của chúng tôi thực sự tuyệt vời.","Những trò ảo thuật khéo léo của nhà ảo thuật luôn làm cho lũ trẻ trầm trồ kinh ngạc.","Đừng làm tôi ngượng bằng cách chia sẻ bức ảnh thời thơ ấu đó nhé."]'::jsonb, 1, 'The mountain view from our tent was absolutely awesome. → Cảnh núi non nhìn từ lều của chúng tôi thực sự tuyệt vời.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_28_2', 'en-b1-28', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_2_1', 'ten_b1_28_2', 'amaze', 'Advances in medical technology continue to amaze researchers and offer new hope to patients with complex conditions.', 'Advances in medical technology continue to amaze researchers and offer new hope to patients with complex conditions.', '/əˈmeɪz/', 'Sự tiến bộ trong công nghệ y tế tiếp tục khiến các nhà nghiên cứu ngạc nhiên và thắp lên hy vọng mới cho những bệnh nhân mắc các bệnh phức tạp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_2_2', 'ten_b1_28_2', 'confidence', 'Supportive feedback can build students'' confidence and encourage them to participate more actively in classroom discussions.', 'Supportive feedback can build students'' confidence and encourage them to participate more actively in classroom discussions.', '/ˈkɑːnfɪdəns/', 'Phản hồi mang tính khích lệ có thể xây dựng sự tự tin cho học sinh và khuyến khích các em tham gia tích cực hơn vào các cuộc thảo luận trên lớp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_2_3', 'ten_b1_28_2', 'awesome', 'The awesome power of volcanic eruptions highlights the importance of effective monitoring systems in nearby communities.', 'The awesome power of volcanic eruptions highlights the importance of effective monitoring systems in nearby communities.', '/ˈɔːsəm/', 'Sức mạnh đáng kinh ngạc của các vụ phun trào núi lửa nhấn mạnh tầm quan trọng của các hệ thống giám sát hiệu quả ở các cộng đồng lân cận.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_2_4', 'ten_b1_28_2', 'sadness', 'Regular social contact can help reduce feelings of sadness among older people who live alone.', 'Regular social contact can help reduce feelings of sadness among older people who live alone.', '/ˈsædnəs/', 'Giao social thường xuyên có thể giúp giảm bớt cảm giác buồn bã ở những người cao tuổi sống cô đơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_2_5', 'ten_b1_28_2', 'embarrass', 'Correcting every mistake publicly can embarrass language learners and discourage them from participating in classroom discussions.', 'Correcting every mistake publicly can embarrass language learners and discourage them from participating in classroom discussions.', '/ɪmˈbærəs/', 'Việc công khai sửa mọi lỗi sai có thể khiến người học ngôn ngữ cảm thấy ngượng ngùng và nhụt chí tham gia vào các buổi thảo luận trên lớp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_28_2_6', 'ten_b1_28_2', 'incredible', 'Advances in medical technology have brought incredible improvements in the quality of life for many patients.', 'Advances in medical technology have brought incredible improvements in the quality of life for many patients.', '/ɪnˈkredəbl/', 'Những tiến bộ trong công nghệ y tế đã mang lại những cải thiện tuyệt vời về chất lượng cuộc sống cho rất nhiều bệnh nhân.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_28_2_1', 'en-b1-28', 'ten_b1_28_2', 'listening', 'listening', 'Advances in medical technology continue to amaze researchers and offer new hope to patients with complex conditions.', NULL, 'Trong câu vừa nghe, từ “amaze” mang nghĩa nào sau đây?', '["làm phiền; làm bực mình; chọc tức","thám tử; trinh thám; cảnh sát điều tra","tình trạng khẩn cấp; trường hợp cấp bách","làm kinh ngạc; làm ngạc nhiên"]'::jsonb, 3, '“amaze” (/əˈmeɪz/): làm kinh ngạc; làm ngạc nhiên. Câu đầy đủ: Advances in medical technology continue to amaze researchers and offer new hope to patients with complex conditions.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_28_2_2', 'en-b1-28', 'ten_b1_28_2', 'listening', 'listening', 'Supportive feedback can build students'' confidence and encourage them to participate more actively in classroom discussions.', NULL, 'Trong câu vừa nghe, từ “confidence” mang nghĩa nào sau đây?', '["không khỏe; mệt trong người","đã chuẩn bị sẵn sàng","chảy máu; ra máu","sự tự tin; niềm tin"]'::jsonb, 3, '“confidence” (/ˈkɑːnfɪdəns/): sự tự tin; niềm tin. Câu đầy đủ: Supportive feedback can build students'' confidence and encourage them to participate more actively in classroom discussions.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
