INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_28_3', 'en-b1-28', 'The mountain view from our tent was absolutely awesome', 'Cảnh núi non nhìn từ lều của chúng tôi thực sự tuyệt vời.', 'awesome /ˈɔːsəm/', '["awesome","absolutely","view","was","mountain","from","tent","our","The"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
