INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_1', 'en-b1-28', NULL, 'comprehensive_test', 'listening', 'amaze', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["áo lót sát nách (Anh); áo lê-ki-na, áo ghi-lê (Mỹ)","làm kinh ngạc; làm ngạc nhiên","ca phẫu thuật","hoạt động buôn bán, giao thương hàng hóa hoặc dịch vụ"]'::jsonb, 1, 'amaze (/əˈmeɪz/) → làm kinh ngạc; làm ngạc nhiên', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_2', 'en-b1-28', NULL, 'comprehensive_test', 'listening', 'Practising with friends gave me confidence before the interview.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi cảm thấy rất xấu hổ sau khi cười nhạo lỗi lầm của bạn mình.","Việc luyện tập cùng bạn bè đã mang lại cho tôi sự tự tin trước buổi phỏng vấn.","Người yêu của tôi đã mang hoa đến cho tôi sau một ngày mệt mỏi.","Thật khó tin khi hạt giống nhỏ xíu này lại có thể lớn lên thành một cái cây."]'::jsonb, 1, 'Practising with friends gave me confidence before the interview. → Việc luyện tập cùng bạn bè đã mang lại cho tôi sự tự tin trước buổi phỏng vấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_3', 'en-b1-28', NULL, 'comprehensive_test', 'listening', 'awesome', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["buổi khám sức khỏe tổng quát; sự kiểm tra sức khỏe","nhà chính trị; chính trị gia","cực kỳ sợ hãi; khiếp sợ","tuyệt vời; cực kỳ thú vị"]'::jsonb, 3, 'awesome (/ˈɔːsəm/) → tuyệt vời; cực kỳ thú vị; làm kinh ngạc; gây ngạc nhiên lớn; đáng sợ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_4', 'en-b1-28', NULL, 'comprehensive_test', 'listening', 'She felt a deep sadness when her friend moved away.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Leila trông có vẻ bực bội khi máy in lại bị kẹt giấy lần nữa.","Họ đã tận hưởng một bữa tối lãng mạn bên hồ nước yên tĩnh.","Tôi giật mình tỉnh dậy sau một cơn ác mộng và bật đèn lên.","Cô ấy cảm thấy một nỗi buồn sâu sắc khi người bạn thân chuyển đi nơi khác."]'::jsonb, 3, 'She felt a deep sadness when her friend moved away. → Cô ấy cảm thấy một nỗi buồn sâu sắc khi người bạn thân chuyển đi nơi khác.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_5', 'en-b1-28', NULL, 'comprehensive_test', 'listening', 'embarrass', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm cho lúng túng; làm ngượng ngùng; gây bối rối","cởi quần áo; thay đồ","thuộc về phương bắc; ở miền bắc","tù nhân; người bị giam giữ, người bị cầm tù"]'::jsonb, 0, 'embarrass (/ɪmˈbærəs/) → làm cho lúng túng; làm ngượng ngùng; gây bối rối', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_6', 'en-b1-28', NULL, 'comprehensive_test', 'listening', 'It seems incredible that this tiny seed becomes a tree.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi biết việc hủy buổi dã ngoại sẽ làm lũ trẻ thất vọng.","Xin hãy gõ cửa nhẹ nhàng để không làm em bé giật mình.","Thật khó tin khi hạt giống nhỏ xíu này lại có thể lớn lên thành một cái cây.","Bọn trẻ hò hét phấn khích ngay khi trò chơi bắt đầu."]'::jsonb, 2, 'It seems incredible that this tiny seed becomes a tree. → Thật khó tin khi hạt giống nhỏ xíu này lại có thể lớn lên thành một cái cây.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_7', 'en-b1-28', NULL, 'comprehensive_test', 'listening', 'scream', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thân phận; danh tính","nhà báo; phóng viên","gào thét; thét lên","chim bồ câu"]'::jsonb, 2, 'scream (/skriːm/) → gào thét; thét lên; tiếng thét; tiếng hét', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_8', 'en-b1-28', NULL, 'comprehensive_test', 'listening', 'I felt ashamed after laughing at my friend''s mistake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi cảm thấy rất xấu hổ sau khi cười nhạo lỗi lầm của bạn mình.","Cô ấy vẫn giữ được bình tĩnh khi đèn đột ngột vụt tắt.","Cảnh núi non nhìn từ lều của chúng tôi thực sự tuyệt vời.","Chúng tôi đã có một buổi dã ngoại tuyệt vời bên hồ."]'::jsonb, 0, 'I felt ashamed after laughing at my friend''s mistake. → Tôi cảm thấy rất xấu hổ sau khi cười nhạo lỗi lầm của bạn mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_9', 'en-b1-28', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To make someone feel awkward, ashamed, or uncomfortable.”?', '["delighted","embarrass","sadness","unforgettable"]'::jsonb, 1, 'embarrass (/ɪmˈbærəs/) → làm cho lúng túng; làm ngượng ngùng; gây bối rối', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
