INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_18', 'en-b1-28', NULL, 'comprehensive_test', 'reading', NULL, 'Advances in medical technology continue to amaze researchers and offer new hope to patients with complex conditions.', 'Dựa vào câu trên, từ “amaze” có nghĩa phù hợp nhất là gì?', '["nhà gỗ nhỏ; lều gỗ","ca phẫu thuật","mục tiêu; chỉ tiêu","làm kinh ngạc; làm ngạc nhiên"]'::jsonb, 3, 'amaze: làm kinh ngạc; làm ngạc nhiên. Dịch cả câu: Sự tiến bộ trong công nghệ y tế tiếp tục khiến các nhà nghiên cứu ngạc nhiên và thắp lên hy vọng mới cho những bệnh nhân mắc các bệnh phức tạp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_19', 'en-b1-28', NULL, 'comprehensive_test', 'reading', NULL, 'Supportive feedback can build students'' confidence and encourage them to participate more actively in classroom discussions.', 'Dựa vào câu trên, từ “confidence” có nghĩa phù hợp nhất là gì?', '["sự tự tin; niềm tin","sự sản xuất; chế tạo","đã qua sử dụng; hàng cũ; đồ si","cảng; thành phố cảng"]'::jsonb, 0, 'confidence: sự tự tin; niềm tin; sự tin tưởng; sự tín nhiệm. Dịch cả câu: Phản hồi mang tính khích lệ có thể xây dựng sự tự tin cho học sinh và khuyến khích các em tham gia tích cực hơn vào các cuộc thảo luận trên lớp.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_20', 'en-b1-28', NULL, 'comprehensive_test', 'reading', NULL, 'The awesome power of volcanic eruptions highlights the importance of effective monitoring systems in nearby communities.', 'Dựa vào câu trên, từ “awesome” có nghĩa phù hợp nhất là gì?', '["tài liệu phát tay; bài giảng in sẵn","tái nhợt; nhạt màu","trả lời; hồi âm","tuyệt vời; cực kỳ thú vị"]'::jsonb, 3, 'awesome: tuyệt vời; cực kỳ thú vị; làm kinh ngạc; gây ngạc nhiên lớn; đáng sợ. Dịch cả câu: Sức mạnh đáng kinh ngạc của các vụ phun trào núi lửa nhấn mạnh tầm quan trọng của các hệ thống giám sát hiệu quả ở các cộng đồng lân cận.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_21', 'en-b1-28', NULL, 'comprehensive_test', 'reading', NULL, 'Regular social contact can help reduce feelings of sadness among older people who live alone.', 'Dựa vào câu trên, từ “sadness” có nghĩa phù hợp nhất là gì?', '["dập ghim; máy bấm giấy","sự liên lạc; sự tiếp xúc","về cơ bản; nhìn chung","nỗi buồn; sự đau buồn (cảm giác không vui, đặc biệt sau khi mất mát hoặc thất vọng)"]'::jsonb, 3, 'sadness: nỗi buồn; sự đau buồn (cảm giác không vui, đặc biệt sau khi mất mát hoặc thất vọng). Dịch cả câu: Giao social thường xuyên có thể giúp giảm bớt cảm giác buồn bã ở những người cao tuổi sống cô đơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_22', 'en-b1-28', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bực bội; khó chịu về một điều gì đó khó chịu hoặc bất tiện”', '["annoyed","personally","conditioner","category"]'::jsonb, 0, 'bực bội; khó chịu về một điều gì đó khó chịu hoặc bất tiện → annoyed (/əˈnɔɪd/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_23', 'en-b1-28', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bình tĩnh; điềm tĩnh”', '["boarding","calm","surely","sportswear"]'::jsonb, 1, 'bình tĩnh; điềm tĩnh → calm (/kɑːm/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_28_24', 'en-b1-28', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lãng mạn; thuộc về tình yêu”', '["remain","network","relative","romantic"]'::jsonb, 3, 'lãng mạn; thuộc về tình yêu → romantic (/roʊˈmæntɪk/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-29', 'en', 'Bài 29: Cảm xúc & Tính cách (2) - CEFR B1', 'CEFR B1', 'B1 · Cảm xúc', '22 từ vựng Tiếng Anh CEFR B1 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3029, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dare', 'en-b1-29', 'dare', '/der/', 'B1', 'dám; cả gan; thách thức; khích; lời thách thức', 'v.', 'daring (adj.), daringly (adv.)', NULL, 'Dám làm gì dùng dare to do; thách thức ai làm gì dùng dare sb to do.', 'I finally dared to sing in front of everyone.', NULL, 'Cuối cùng tôi đã dám hát trước mặt mọi người.', '{"wordId":"dare","ukIpa":"/deə/","usIpa":"/der/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"to have enough courage to do something","vi":"dám; cả gan"},{"pos":"v.","en":"to challenge someone to do something requiring courage","vi":"thách thức; khích"},{"pos":"n.","en":"a challenge to do something difficult or frightening","vi":"lời thách thức"}],"examples":[{"en":"I finally dared to sing in front of everyone.","vi":"Cuối cùng tôi đã dám hát trước mặt mọi người.","audioKind":"ex"},{"en":"Students are more likely to dare to question established ideas when teachers welcome respectful disagreement.","vi":"Học sinh có nhiều khả năng dám đặt câu hỏi về các quan niệm đã có từ trước khi giáo viên cởi mở đón nhận những ý kiến trái chiều mang tính tôn trọng.","audioKind":"ex2"}],"collocations":[{"en":"dare to ask","vi":"dám hỏi"},{"en":"dare someone to do something","vi":"thách ai đó làm gì"},{"en":"not dare","vi":"không dám"},{"en":"for a dare","vi":"vì sự thách thức"}],"wordFamily":["daring (adj.)","daringly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Dám làm gì dùng dare to do; thách thức ai làm gì dùng dare sb to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_confident', 'en-b1-29', 'confident', '/ˈkɑːnfɪdənt/', 'B1', 'tự tin; tin tưởng; chắc chắn', 'adj.', 'confidence (n.), confidently (adv.)', 'Đồng nghĩa: self-assured, certain · Trái nghĩa: insecure, uncertain', 'confident là tính từ; confidence là danh từ.', 'After weeks of practice, I felt confident on stage.', NULL, 'Sau nhiều tuần tập luyện, tôi cảm thấy rất tự tin khi đứng trên sân khấu.', '{"wordId":"confident","ukIpa":"/ˈkɒnfɪdənt/","usIpa":"/ˈkɑːnfɪdənt/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"believing in your own ability to succeed","vi":"tự tin"},{"pos":"adj.","en":"certain that something is true or will happen","vi":"tin tưởng; chắc chắn"}],"examples":[{"en":"After weeks of practice, I felt confident on stage.","vi":"Sau nhiều tuần tập luyện, tôi cảm thấy rất tự tin khi đứng trên sân khấu.","audioKind":"ex"},{"en":"Students become more confident when teachers provide constructive feedback and opportunities to practise new skills.","vi":"Học sinh trở nên tự tin hơn khi giáo viên đưa ra những phản hồi mang tính xây dựng và tạo cơ hội rèn luyện các kỹ năng mới.","audioKind":"ex2"}],"collocations":[{"en":"feel confident","vi":"cảm thấy tự tin"},{"en":"confident about the future","vi":"tự tin về tương lai"},{"en":"confident that","vi":"tin chắc rằng"}],"wordFamily":["confidence (n.)","confidently (adv.)"],"synonyms":["self-assured","certain"],"antonyms":["insecure","uncertain"],"tipVi":"confident là tính từ; confidence là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shock', 'en-b1-29', 'shock', '/ʃɑːk/', 'B1', 'sự bàng hoàng; cú sốc; gây sốc; làm bàng hoàng; sốc y tế; điện giật', 'n.', 'shocked (adj.), shocking (adj.)', NULL, 'Cảm giác bàng hoàng dùng shocked; sự việc gây sốc dùng shocking.', 'The sudden rise in rent came as a shock.', NULL, 'Việc tiền thuê nhà tăng đột ngột quả là một cú sốc lớn.', '{"wordId":"shock","ukIpa":"/ʃɒk/","usIpa":"/ʃɑːk/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"a strong feeling of surprise caused by something unexpected","vi":"sự bàng hoàng; cú sốc"},{"pos":"v.","en":"to make someone feel very surprised or upset","vi":"gây sốc; làm bàng hoàng"},{"pos":"n.","en":"a dangerous medical collapse, or an electrical jolt through the body","vi":"sốc y tế; điện giật"}],"examples":[{"en":"The sudden rise in rent came as a shock.","vi":"Việc tiền thuê nhà tăng đột ngột quả là một cú sốc lớn.","audioKind":"ex"},{"en":"Moving abroad can cause culture shock, particularly when everyday customs differ greatly from those at home.","vi":"Việc chuyển ra nước ngoài sinh sống có thể gây ra cú sốc văn hóa, đặc biệt là khi các phong tục thường ngày khác biệt lớn so với ở quê nhà.","audioKind":"ex2"}],"collocations":[{"en":"come as a shock","vi":"gây ra cú sốc"},{"en":"culture shock","vi":"sốc văn hóa"},{"en":"electric shock","vi":"điện giật"},{"en":"in a state of shock","vi":"rơi vào trạng thái bàng hoàng"}],"wordFamily":["shocked (adj.)","shocking (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cảm giác bàng hoàng dùng shocked; sự việc gây sốc dùng shocking.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shocked', 'en-b1-29', 'shocked', '/ʃɑːkt/', 'B1', 'cực kỳ ngạc nhiên và buồn bã trước điều gì đó bất ngờ; bị sốc; bàng hoàng; cảm thấy phản đối mạnh mẽ trước điều gì đó xúc phạm hoặc sai trái; phẫn nộ', 'adj.', 'shock (n.), shock (v.), shocking (adj.)', 'Đồng nghĩa: appalled, stunned · Trái nghĩa: unfazed', 'Shocked dùng để tả cảm xúc của con người; shocking dùng để tả sự việc gây sốc.', 'I was shocked to find water flooding the kitchen.', NULL, 'Tôi chết lặng khi phát hiện nước ngập lê láng trong nhà bếp.', '{"wordId":"shocked","ukIpa":"/ʃɒkt/","usIpa":"/ʃɑːkt/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Very surprised and upset by something unexpected.","vi":"cực kỳ ngạc nhiên và buồn bã trước điều gì đó bất ngờ; bị sốc; bàng hoàng"},{"pos":"adj.","en":"Feeling strong disapproval at something offensive or wrong.","vi":"cảm thấy phản đối mạnh mẽ trước điều gì đó xúc phạm hoặc sai trái; phẫn nộ"}],"examples":[{"en":"I was shocked to find water flooding the kitchen.","vi":"Tôi chết lặng khi phát hiện nước ngập lê láng trong nhà bếp.","audioKind":"ex"},{"en":"Residents were shocked by the sudden closure of the only hospital serving their rural community.","vi":"Người dân vô cùng bàng hoàng trước việc bệnh viện duy nhất phục vụ cộng đồng nông thôn của họ bất ngờ đóng cửa.","audioKind":"ex2"}],"collocations":[{"en":"deeply shocked","vi":"vô cùng sốc"},{"en":"shocked by the news","vi":"bàng hoàng vì tin tức"},{"en":"shocked to hear","vi":"sốc khi nghe tin"}],"wordFamily":["shock (n.)","shock (v.)","shocking (adj.)"],"synonyms":["appalled","stunned"],"antonyms":["unfazed"],"tipVi":"Shocked dùng để tả cảm xúc của con người; shocking dùng để tả sự việc gây sốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enjoyment', 'en-b1-29', 'enjoyment', '/ɪnˈdʒɔɪmənt/', 'B1', 'niềm vui; sự thích thú', 'n.', 'enjoy (v.), enjoyable (adj.), enjoyably (adv.)', 'Đồng nghĩa: pleasure, delight · Trái nghĩa: displeasure', 'Từ này thường không đếm được; khi muốn diễn tả việc tìm thấy niềm vui từ điều gì, hãy dùng cấu trúc get enjoyment from.', 'My grandfather gets great enjoyment from feeding the birds.', NULL, 'Ông tôi tìm thấy niềm vui lớn lao từ việc cho chim ăn.', '{"wordId":"enjoyment","ukIpa":"/ɪnˈdʒɔɪmənt/","usIpa":"/ɪnˈdʒɔɪmənt/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"The pleasure you get from doing or experiencing something","vi":"niềm vui; sự thích thú"}],"examples":[{"en":"My grandfather gets great enjoyment from feeding the birds.","vi":"Ông tôi tìm thấy niềm vui lớn lao từ việc cho chim ăn.","audioKind":"ex"},{"en":"Schools should encourage reading for enjoyment rather than focusing exclusively on examination performance.","vi":"Các trường học nên khuyến khích việc đọc sách vì niềm vui thay vì chỉ tập trung hoàn toàn vào kết quả thi cử.","audioKind":"ex2"}],"collocations":[{"en":"get enjoyment from","vi":"thu được niềm vui từ"},{"en":"for enjoyment","vi":"vì sự thưởng thức; để giải trí"},{"en":"pure enjoyment","vi":"niềm vui thuần túy"}],"wordFamily":["enjoy (v.)","enjoyable (adj.)","enjoyably (adv.)"],"synonyms":["pleasure","delight"],"antonyms":["displeasure"],"tipVi":"Từ này thường không đếm được; khi muốn diễn tả việc tìm thấy niềm vui từ điều gì, hãy dùng cấu trúc get enjoyment from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frightening', 'en-b1-29', 'frightening', '/ˈfraɪtənɪŋ/', 'B1', 'đáng sợ; khiếp đảm', 'adj.', 'frighten (v.), frightened (adj.), fright (n.), frighteningly (adv.)', 'Đồng nghĩa: scary, terrifying · Trái nghĩa: reassuring', 'Dùng frightening để mô tả sự việc gây sợ hãi; dùng frightened để chỉ cảm giác sợ hãi của con người.', 'The sudden thunder was frightening, but our dog stayed calm.', NULL, 'Tiếng sấm bất ngờ thật đáng sợ, nhưng chú chó nhà chúng tôi vẫn giữ được bình tĩnh.', '{"wordId":"frightening","ukIpa":"/ˈfraɪtənɪŋ/","usIpa":"/ˈfraɪtənɪŋ/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Making someone feel afraid.","vi":"đáng sợ; khiếp đảm"}],"examples":[{"en":"The sudden thunder was frightening, but our dog stayed calm.","vi":"Tiếng sấm bất ngờ thật đáng sợ, nhưng chú chó nhà chúng tôi vẫn giữ được bình tĩnh.","audioKind":"ex"},{"en":"Experiencing a major flood can be frightening, especially for children who have never faced a natural disaster.","vi":"Trải qua một trận lũ lụt lớn có thể rất đáng sợ, đặc biệt đối với trẻ em chưa từng đối mặt với thảm họa thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"frightening experience","vi":"trải nghiệm đáng sợ"},{"en":"frightening thought","vi":"ý nghĩ đáng sợ"},{"en":"frightening prospect","vi":"viễn cảnh đáng sợ"}],"wordFamily":["frighten (v.)","frightened (adj.)","fright (n.)","frighteningly (adv.)"],"synonyms":["scary","terrifying"],"antonyms":["reassuring"],"tipVi":"Dùng frightening để mô tả sự việc gây sợ hãi; dùng frightened để chỉ cảm giác sợ hãi của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comfort', 'en-b1-29', 'comfort', '/ˈkʌmfərt/', 'B1', 'sự thoải mái; sự tiện nghi; sự an ủi; niềm khuây khỏa; an ủi; vỗ về', 'n.', 'comfortable (adj.), comfortably (adv.), comforting (adj.), discomfort (n.)', 'Đồng nghĩa: solace, console · Trái nghĩa: discomfort', 'Khi chỉ sự thoải mái hay niềm an ủi, từ này thường không đếm được; khi làm động từ, nó đi trực tiếp với tân ngữ chỉ người.', 'I enjoyed the comfort of a warm bed after camping.', NULL, 'Tôi tận hưởng cảm giác thoải mái của chiếc giường ấm áp sau chuyến cắm trại.', '{"wordId":"comfort","ukIpa":"/ˈkʌmfət/","usIpa":"/ˈkʌmfərt/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"A pleasant state of physical ease and relaxation.","vi":"sự thoải mái; sự tiện nghi"},{"pos":"n.","en":"Relief from sadness or worry, or something providing it.","vi":"sự an ủi; niềm khuây khỏa"},{"pos":"v.","en":"To help someone feel less sad, worried, or upset.","vi":"an ủi; vỗ về"}],"examples":[{"en":"I enjoyed the comfort of a warm bed after camping.","vi":"Tôi tận hưởng cảm giác thoải mái của chiếc giường ấm áp sau chuyến cắm trại.","audioKind":"ex"},{"en":"Support groups can comfort patients by providing opportunities to share experiences and discuss concerns openly.","vi":"Các nhóm hỗ trợ có thể an ủi bệnh nhân bằng cách tạo cơ hội để họ chia sẻ kinh nghiệm và cởi mở thảo luận về những lo lắng của mình.","audioKind":"ex2"}],"collocations":[{"en":"in comfort","vi":"thoải mái; thư thái"},{"en":"take comfort in","vi":"tìm thấy sự an ủi từ"},{"en":"comfort someone","vi":"an ủi ai đó"},{"en":"creature comforts","vi":"tiện nghi vật chất"}],"wordFamily":["comfortable (adj.)","comfortably (adv.)","comforting (adj.)","discomfort (n.)"],"synonyms":["solace","console"],"antonyms":["discomfort"],"tipVi":"Khi chỉ sự thoải mái hay niềm an ủi, từ này thường không đếm được; khi làm động từ, nó đi trực tiếp với tân ngữ chỉ người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amusing', 'en-b1-29', 'amusing', '/əˈmjuːzɪŋ/', 'B1', 'thú vị; buồn cười; làm vui vẻ', 'adj.', 'amuse (v.), amused (adj.), amusement (n.), amusingly (adv.)', 'Đồng nghĩa: funny, entertaining · Trái nghĩa: boring', 'amusing dùng để miêu tả sự vật, sự việc mang tính chất gây cười; amused dùng để diễn tả cảm giác buồn cười của con người.', 'My cousin told an amusing story about his cat.', NULL, 'Anh họ tôi kể một câu chuyện rất buồn cười về con mèo của anh ấy.', '{"wordId":"amusing","ukIpa":"/əˈmjuːzɪŋ/","usIpa":"/əˈmjuːzɪŋ/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"funny or entertaining in a pleasant way","vi":"thú vị; buồn cười; làm vui vẻ"}],"examples":[{"en":"My cousin told an amusing story about his cat.","vi":"Anh họ tôi kể một câu chuyện rất buồn cười về con mèo của anh ấy.","audioKind":"ex"},{"en":"Teachers can use amusing examples to maintain students'' attention while explaining difficult concepts in science lessons.","vi":"Giáo viên có thể sử dụng các ví dụ thú vị để duy trì sự chú ý của học sinh khi giải thích các khái niệm khó trong bài học khoa học.","audioKind":"ex2"}],"collocations":[{"en":"amusing story","vi":"câu chuyện thú vị"},{"en":"find something amusing","vi":"thấy điều gì đó buồn cười"},{"en":"amusing anecdote","vi":"giai thoại thú vị"}],"wordFamily":["amuse (v.)","amused (adj.)","amusement (n.)","amusingly (adv.)"],"synonyms":["funny","entertaining"],"antonyms":["boring"],"tipVi":"amusing dùng để miêu tả sự vật, sự việc mang tính chất gây cười; amused dùng để diễn tả cảm giác buồn cười của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grateful', 'en-b1-29', 'grateful', '/ˈɡreɪtfəl/', 'B1', 'biết ơn; cảm kích', 'adj.', 'gratitude (n.), gratefully (adv.), ungrateful (adj.)', 'Đồng nghĩa: thankful, appreciative · Trái nghĩa: ungrateful', 'Dùng cấu trúc "be grateful to" ai đó "for" điều gì; chú ý cách viết là "grateful" không phải "greatful".', 'I am grateful for your help with the move.', NULL, 'Tôi rất biết ơn sự giúp đỡ của bạn trong việc chuyển nhà.', '{"wordId":"grateful","ukIpa":"/ˈɡreɪtfəl/","usIpa":"/ˈɡreɪtfəl/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling thankful for kindness, help, or something good.","vi":"biết ơn; cảm kích"}],"examples":[{"en":"I am grateful for your help with the move.","vi":"Tôi rất biết ơn sự giúp đỡ của bạn trong việc chuyển nhà.","audioKind":"ex"},{"en":"Many students are grateful for scholarships that allow them to continue their education despite financial difficulties.","vi":"Nhiều sinh viên cảm thấy biết ơn các suất học bổng giúp họ tiếp tục việc học tập bất chấp khó khăn tài chính.","audioKind":"ex2"}],"collocations":[{"en":"grateful to someone","vi":"biết ơn ai đó"},{"en":"grateful for something","vi":"biết ơn về điều gì"},{"en":"deeply grateful","vi":"vô cùng biết ơn"}],"wordFamily":["gratitude (n.)","gratefully (adv.)","ungrateful (adj.)"],"synonyms":["thankful","appreciative"],"antonyms":["ungrateful"],"tipVi":"Dùng cấu trúc \"be grateful to\" ai đó \"for\" điều gì; chú ý cách viết là \"grateful\" không phải \"greatful\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_upset', 'en-b1-29', 'upset', '/ʌpˈset/', 'B1', 'buồn bã; lo lắng; thất vọng; làm buồn; làm lo lắng; làm xáo trộn; làm đảo lộn', 'adj.', 'upsetting (adj.)', 'Đồng nghĩa: distressed, unhappy · Trái nghĩa: happy', 'Dạng quá khứ và phân từ hai của động từ upset vẫn giữ nguyên là upset; danh từ có trọng âm rơi vào âm tiết đầu.', 'Lena felt upset when she lost her favourite scarf.', NULL, 'Lena cảm thấy buồn khi cô ấy làm mất chiếc khăn choàng cổ yêu thích của mình.', '{"wordId":"upset","ukIpa":"/ʌpˈset/","usIpa":"/ʌpˈset/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Unhappy, worried, or disappointed about something.","vi":"buồn bã; lo lắng; thất vọng"},{"pos":"v.","en":"To make someone feel unhappy or worried.","vi":"làm buồn; làm lo lắng"},{"pos":"v.","en":"To disturb the usual arrangement or balance of something.","vi":"làm xáo trộn; làm đảo lộn"}],"examples":[{"en":"Lena felt upset when she lost her favourite scarf.","vi":"Lena cảm thấy buồn khi cô ấy làm mất chiếc khăn choàng cổ yêu thích của mình.","audioKind":"ex"},{"en":"Sudden changes to school routines can upset younger children, who often rely on predictable daily activities.","vi":"Những thay đổi đột ngột trong sinh hoạt ở trường có thể khiến trẻ nhỏ lo âu, vì các em thường quen dựa vào các hoạt động hằng ngày có thể đoán trước.","audioKind":"ex2"}],"collocations":[{"en":"feel upset","vi":"cảm thấy buồn"},{"en":"upset about something","vi":"buồn bã vì điều gì"},{"en":"upset the balance","vi":"phá vỡ sự cân bằng"},{"en":"upset someone''s plans","vi":"làm xáo trộn kế hoạch của ai đó"}],"wordFamily":["upsetting (adj.)"],"synonyms":["distressed","unhappy"],"antonyms":["happy"],"tipVi":"Dạng quá khứ và phân từ hai của động từ upset vẫn giữ nguyên là upset; danh từ có trọng âm rơi vào âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pleasure', 'en-b1-29', 'pleasure', '/ˈpleʒɚ/', 'B1', 'niềm vui; sự thích thú; trải nghiệm thú vị', 'n.', 'please (v.), pleased (adj.), pleasant (adj.), pleasurable (adj.)', 'Đồng nghĩa: enjoyment, delight · Trái nghĩa: displeasure', 'Cảm giác vui vẻ thường là danh từ không đếm được; một niềm vui thích cụ thể có thể dùng a pleasure.', 'She takes great pleasure in growing herbs on her balcony.', NULL, 'Cô ấy rất thích thú với việc trồng các loại cây thảo mộc trên ban công của mình.', '{"wordId":"pleasure","ukIpa":"/ˈpleʒə/","usIpa":"/ˈpleʒɚ/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"A feeling of happiness or enjoyment","vi":"niềm vui; sự thích thú"},{"pos":"n.","en":"An activity or experience that brings enjoyment","vi":"niềm vui; trải nghiệm thú vị"}],"examples":[{"en":"She takes great pleasure in growing herbs on her balcony.","vi":"Cô ấy rất thích thú với việc trồng các loại cây thảo mộc trên ban công của mình.","audioKind":"ex"},{"en":"Public libraries encourage reading for pleasure while providing affordable access to knowledge for people of all ages.","vi":"Các thư viện công cộng khuyến khích văn hóa đọc vì niềm vui đồng thời cung cấp khả năng tiếp cận kiến thức chi phí thấp cho mọi lứa tuổi.","audioKind":"ex2"}],"collocations":[{"en":"take pleasure in","vi":"tìm thấy niềm vui trong việc gì"},{"en":"for pleasure","vi":"để giải trí; vì sở thích"},{"en":"a great pleasure","vi":"một niềm vui lớn; một điều thú vị"},{"en":"with pleasure","vi":"với niềm hân hạnh; rất sẵn lòng"}],"wordFamily":["please (v.)","pleased (adj.)","pleasant (adj.)","pleasurable (adj.)"],"synonyms":["enjoyment","delight"],"antonyms":["displeasure"],"tipVi":"Cảm giác vui vẻ thường là danh từ không đếm được; một niềm vui thích cụ thể có thể dùng a pleasure.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disgusting', 'en-b1-29', 'disgusting', '/dɪsˈɡʌstɪŋ/', 'B1', 'ghê tởm; kinh tởm; đáng ghét; không thể chấp nhận được', 'adj.', 'disgust (n.), disgust (v.), disgusted (adj.), disgustingly (adv.)', 'Đồng nghĩa: revolting, repulsive · Trái nghĩa: pleasant', 'disgusting dùng để mô tả sự vật gây khó chịu; disgusted dùng để diễn tả cảm giác bất bình của con người.', 'A disgusting smell came from the forgotten rubbish bag.', NULL, 'Một mùi kinh tởm bốc ra từ túi rác bị bỏ quên.', '{"wordId":"disgusting","ukIpa":"/dɪsˈɡʌstɪŋ/","usIpa":"/dɪsˈɡʌstɪŋ/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"extremely unpleasant, making you feel sick or strongly dislike something","vi":"ghê tởm; kinh tởm"},{"pos":"adj.","en":"so bad or wrong that it causes strong disapproval","vi":"đáng ghét; không thể chấp nhận được"}],"examples":[{"en":"A disgusting smell came from the forgotten rubbish bag.","vi":"Một mùi kinh tởm bốc ra từ túi rác bị bỏ quên.","audioKind":"ex"},{"en":"Residents described the illegal dumping of waste beside their homes as disgusting and demanded immediate action.","vi":"Cư dân mô tả hành vi xả rác bừa bãi cạnh nhà họ là đáng phẫn nộ và yêu cầu phải có biện pháp xử lý ngay lập tức.","audioKind":"ex2"}],"collocations":[{"en":"a disgusting smell","vi":"mùi hôi kinh tởm"},{"en":"disgusting behaviour","vi":"hành vi đáng ghét"},{"en":"absolutely disgusting","vi":"vô cùng kinh tởm"}],"wordFamily":["disgust (n.)","disgust (v.)","disgusted (adj.)","disgustingly (adv.)"],"synonyms":["revolting","repulsive"],"antonyms":["pleasant"],"tipVi":"disgusting dùng để mô tả sự vật gây khó chịu; disgusted dùng để diễn tả cảm giác bất bình của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unpleasant', 'en-b1-29', 'unpleasant', '/ʌnˈplezənt/', 'B1', 'khó chịu; không dễ chịu; đáng ghét; không thân thiện; thô lỗ', 'adj.', 'pleasant (adj.), unpleasantly (adv.), unpleasantness (n.)', 'Đồng nghĩa: disagreeable, unwelcome · Trái nghĩa: pleasant, agreeable', 'Khi dùng cho đồ vật, nó có nghĩa là khó chịu; khi dùng cho con người, thường chỉ thái độ không thân thiện.', 'An unpleasant smell was coming from the kitchen bin.', NULL, 'Một mùi khó chịu đang bốc lên từ thùng rác trong bếp.', '{"wordId":"unpleasant","ukIpa":"/ʌnˈplezənt/","usIpa":"/ʌnˈplezənt/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Causing discomfort, dislike, or unhappiness.","vi":"khó chịu; không dễ chịu; đáng ghét"},{"pos":"adj.","en":"Behaving in an unfriendly or rude way.","vi":"không thân thiện; thô lỗ"}],"examples":[{"en":"An unpleasant smell was coming from the kitchen bin.","vi":"Một mùi khó chịu đang bốc lên từ thùng rác trong bếp.","audioKind":"ex"},{"en":"Although commuting can be unpleasant, reliable public transport can reduce stress and improve the daily experience of workers.","vi":"Mặc dù việc đi lại đi làm có thể không dễ chịu gì, nhưng hệ thống giao thông công cộng đáng tin cậy có thể làm giảm căng thẳng và cải thiện trải nghiệm hằng ngày của người lao động.","audioKind":"ex2"}],"collocations":[{"en":"an unpleasant smell","vi":"mùi khó chịu"},{"en":"an unpleasant experience","vi":"một trải nghiệm tồi tệ"},{"en":"unpleasant side effects","vi":"tác dụng phụ khó chịu"},{"en":"unpleasant to someone","vi":"thái độ khó chịu với ai"}],"wordFamily":["pleasant (adj.)","unpleasantly (adv.)","unpleasantness (n.)"],"synonyms":["disagreeable","unwelcome"],"antonyms":["pleasant","agreeable"],"tipVi":"Khi dùng cho đồ vật, nó có nghĩa là khó chịu; khi dùng cho con người, thường chỉ thái độ không thân thiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_warmly', 'en-b1-29', 'warmly', '/ˈwɔːrmli/', 'B1', 'một cách nồng nhiệt; niềm nở; thân thiện; một cách ấm áp', 'adv.', 'warm (adj.), warmth (n.)', 'Đồng nghĩa: cordially · Trái nghĩa: coldly', '"Greet warmly" nghĩa là chào hỏi niềm nở; "dress warmly" nghĩa là mặc ấm áp.', 'The neighbours smiled and greeted us warmly this morning.', NULL, 'Những người hàng xóm đã mỉm cười và chào đón chúng tôi rất nồng nhiệt vào sáng nay.', '{"wordId":"warmly","ukIpa":"/ˈwɔːmli/","usIpa":"/ˈwɔːrmli/","cefr":"B1","topic":"emotion","senses":[{"pos":"adv.","en":"in a friendly and welcoming way","vi":"một cách nồng nhiệt; niềm nở; thân thiện"},{"pos":"adv.","en":"in a way that keeps someone comfortably warm","vi":"một cách ấm áp"}],"examples":[{"en":"The neighbours smiled and greeted us warmly this morning.","vi":"Những người hàng xóm đã mỉm cười và chào đón chúng tôi rất nồng nhiệt vào sáng nay.","audioKind":"ex"},{"en":"When schools welcome new students warmly, they can reduce anxiety and encourage participation in classroom activities.","vi":"Khi các trường học chào đón học sinh mới một cách nồng nhiệt, họ có thể xoa dịu sự lo lắng và khuyến khích các em tham gia vào các hoạt động trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"greet warmly","vi":"chào hỏi nồng nhiệt"},{"en":"welcome warmly","vi":"chào đón nồng nhiệt"},{"en":"dress warmly","vi":"mặc ấm"},{"en":"smile warmly","vi":"mỉm cười thân thiện"}],"wordFamily":["warm (adj.)","warmth (n.)"],"synonyms":["cordially"],"antonyms":["coldly"],"tipVi":"\"Greet warmly\" nghĩa là chào hỏi niềm nở; \"dress warmly\" nghĩa là mặc ấm áp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_humour', 'en-b1-29', 'humour', '/ˈhjuːmər/', 'B1', 'sự hài hước; khiếu hài hước; tâm trạng; tính khí; chiều theo; nịnh nọt', 'n.', 'humorous (adj.), humorously (adv.), humourless (adj.)', NULL, 'Cách viết Anh-Anh là humour, Anh-Mỹ là humor; khi làm động từ, nó mang nghĩa chiều theo hoặc thuận theo.', 'Her gentle humour made everyone at dinner feel relaxed.', NULL, 'Sự hài hước nhẹ nhàng của cô ấy khiến mọi người trong bữa tối đều cảm thấy thoải mái.', '{"wordId":"humour","ukIpa":"/ˈhjuːmə/","usIpa":"/ˈhjuːmər/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"The quality of being funny or the ability to appreciate funniness.","vi":"sự hài hước; khiếu hài hước"},{"pos":"n.","en":"A person''s mood or state of mind.","vi":"tâm trạng; tính khí"},{"pos":"v.","en":"To agree with someone''s wishes to keep them happy.","vi":"chiều theo; nịnh nọt"}],"examples":[{"en":"Her gentle humour made everyone at dinner feel relaxed.","vi":"Sự hài hước nhẹ nhàng của cô ấy khiến mọi người trong bữa tối đều cảm thấy thoải mái.","audioKind":"ex"},{"en":"Teachers can use humour to reduce classroom anxiety and encourage students to participate more confidently.","vi":"Giáo viên có thể sử dụng sự hài hước để giảm bớt sự lo lắng trong lớp học và khuyến khích học sinh tham gia tự tin hơn.","audioKind":"ex2"}],"collocations":[{"en":"a sense of humour","vi":"khiếu hài hước"},{"en":"good humour","vi":"tâm trạng tốt"},{"en":"dry humour","vi":"sự hài hước thâm trầm"},{"en":"humour someone","vi":"chiều theo ý ai đó"}],"wordFamily":["humorous (adj.)","humorously (adv.)","humourless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết Anh-Anh là humour, Anh-Mỹ là humor; khi làm động từ, nó mang nghĩa chiều theo hoặc thuận theo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regret', 'en-b1-29', 'regret', '/rɪˈɡret/', 'B1', 'hối tiếc; ân hận; niềm ân hận; sự hối tiếc', 'v.', 'regretful (adj.), regrettable (adj.), regretfully (adv.)', 'Đồng nghĩa: remorse', 'regret doing chỉ hối tiếc vì đã làm; regret to say chỉ sự tiếc nuối khi phải thông báo.', 'I regret leaving my umbrella at home this morning.', NULL, 'Tôi hối tiếc vì sáng nay đã để quên ô ở nhà.', '{"wordId":"regret","ukIpa":"/rɪˈɡret/","usIpa":"/rɪˈɡret/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"to feel sorry about something that happened or was done","vi":"hối tiếc; ân hận"},{"pos":"n.","en":"sadness about a past action, decision, or situation","vi":"niềm ân hận; sự hối tiếc"}],"examples":[{"en":"I regret leaving my umbrella at home this morning.","vi":"Tôi hối tiếc vì sáng nay đã để quên ô ở nhà.","audioKind":"ex"},{"en":"Graduates may regret choosing a career solely for its salary if the work provides little personal satisfaction.","vi":"Những người tốt nghiệp có thể sẽ hối tiếc vì chọn một nghề nghiệp chỉ vì mức lương của nó nếu công việc đó mang lại ít sự thỏa mãn cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"regret doing something","vi":"hối tiếc khi làm điều gì"},{"en":"deep regret","vi":"sự ân hận sâu sắc"},{"en":"express regret","vi":"bày tỏ sự hối tiếc"},{"en":"regret to inform","vi":"rất tiếc phải thông báo"}],"wordFamily":["regretful (adj.)","regrettable (adj.)","regretfully (adv.)"],"synonyms":["remorse"],"antonyms":[],"tipVi":"regret doing chỉ hối tiếc vì đã làm; regret to say chỉ sự tiếc nuối khi phải thông báo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_terrific', 'en-b1-29', 'terrific', '/təˈrɪfɪk/', 'B1', 'tuyệt vời; xuất sắc; cực kỳ lớn; dữ dội', 'adj.', 'terrifically (adv.)', 'Đồng nghĩa: excellent, fantastic · Trái nghĩa: awful', 'Thường dùng trong khẩu ngữ để khen ngợi; đừng nhầm lẫn với terrible "tệ hại".', 'You did a terrific job fixing that old bicycle.', NULL, 'Bạn đã làm rất xuất sắc khi sửa chiếc xe đạp cũ đó.', '{"wordId":"terrific","ukIpa":"/təˈrɪfɪk/","usIpa":"/təˈrɪfɪk/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Extremely good or enjoyable.","vi":"tuyệt vời; xuất sắc"},{"pos":"adj.","en":"Very great in amount, degree, or intensity.","vi":"cực kỳ lớn; dữ dội"}],"examples":[{"en":"You did a terrific job fixing that old bicycle.","vi":"Bạn đã làm rất xuất sắc khi sửa chiếc xe đạp cũ đó.","audioKind":"ex"},{"en":"Community gardens offer a terrific opportunity for residents to exercise outdoors while developing stronger social connections.","vi":"Khu vườn cộng đồng mang đến cơ hội tuyệt vời cho cư dân tập thể dục ngoài trời đồng thời vun đắp các mối quan hệ xã hội gắn kết hơn.","audioKind":"ex2"}],"collocations":[{"en":"terrific job","vi":"công việc xuất sắc"},{"en":"terrific opportunity","vi":"cơ hội tuyệt vời"},{"en":"terrific speed","vi":"tốc độ cực nhanh"},{"en":"terrific noise","vi":"tiếng động lớn"}],"wordFamily":["terrifically (adv.)"],"synonyms":["excellent","fantastic"],"antonyms":["awful"],"tipVi":"Thường dùng trong khẩu ngữ để khen ngợi; đừng nhầm lẫn với terrible \"tệ hại\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strongly', 'en-b1-29', 'strongly', '/ˈstrɔːŋli/', 'B1', 'mạnh mẽ; quyết liệt; kiên quyết', 'adv.', 'strong (adj.), strength (n.), strengthen (v.)', 'Đồng nghĩa: firmly, intensely · Trái nghĩa: weakly', 'Thường đi kèm với các từ như ''recommend'', ''oppose'', ''believe'' để nhấn mạnh thái độ.', 'I strongly recommend taking a jacket on this walk.', NULL, 'Tôi khuyên bạn nên mang theo áo khoác trong chuyến đi dạo này.', '{"wordId":"strongly","ukIpa":"/ˈstrɒŋli/","usIpa":"/ˈstrɔːŋli/","cefr":"B1","topic":"emotion","senses":[{"pos":"adv.","en":"With great force, intensity, or conviction.","vi":"mạnh mẽ; quyết liệt; kiên quyết"}],"examples":[{"en":"I strongly recommend taking a jacket on this walk.","vi":"Tôi khuyên bạn nên mang theo áo khoác trong chuyến đi dạo này.","audioKind":"ex"},{"en":"Many residents strongly oppose the proposed airport expansion because they fear increased noise and air pollution.","vi":"Nhiều cư dân kịch liệt phản đối dự án mở rộng sân bay vì họ lo ngại tiếng ồn và ô nhiễm không khí gia tăng.","audioKind":"ex2"}],"collocations":[{"en":"strongly recommend","vi":"khuyên chân thành"},{"en":"strongly oppose","vi":"kịch liệt phản đối"},{"en":"strongly believe","vi":"tin tưởng chắc chắn"},{"en":"strongly associated with","vi":"có liên quan mật thiết đến"}],"wordFamily":["strong (adj.)","strength (n.)","strengthen (v.)"],"synonyms":["firmly","intensely"],"antonyms":["weakly"],"tipVi":"Thường đi kèm với các từ như ''recommend'', ''oppose'', ''believe'' để nhấn mạnh thái độ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disappointed', 'en-b1-29', 'disappointed', '/ˌdɪsəˈpɔɪntɪd/', 'B1', 'thất vọng; buồn bã', 'adj.', 'disappoint (v.), disappointment (n.), disappointing (adj.), disappointingly (adv.)', 'Đồng nghĩa: let down, disheartened · Trái nghĩa: pleased, satisfied', 'disappointed dùng để mô tả cảm xúc của con người; trong khi disappointing dùng cho sự việc gây thất vọng.', 'I was disappointed when rain cancelled our beach picnic.', NULL, 'Tôi đã rất thất vọng khi trời mưa khiến buổi dã ngoại trên bãi biển của chúng tôi bị hủy.', '{"wordId":"disappointed","ukIpa":"/ˌdɪsəˈpɔɪntɪd/","usIpa":"/ˌdɪsəˈpɔɪntɪd/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Unhappy because something was not as good as you hoped.","vi":"thất vọng; buồn bã"}],"examples":[{"en":"I was disappointed when rain cancelled our beach picnic.","vi":"Tôi đã rất thất vọng khi trời mưa khiến buổi dã ngoại trên bãi biển của chúng tôi bị hủy.","audioKind":"ex"},{"en":"Graduates may feel disappointed if their first jobs offer few opportunities to apply the skills they have learned.","vi":"Sinh viên mới tốt nghiệp có thể cảm thấy thất vọng nếu công việc đầu tiên của họ mang lại ít cơ hội áp dụng những kỹ năng đã học.","audioKind":"ex2"}],"collocations":[{"en":"disappointed with","vi":"thất vọng về"},{"en":"deeply disappointed","vi":"vô cùng thất vọng"},{"en":"disappointed to hear","vi":"thất vọng khi nghe tin"}],"wordFamily":["disappoint (v.)","disappointment (n.)","disappointing (adj.)","disappointingly (adv.)"],"synonyms":["let down","disheartened"],"antonyms":["pleased","satisfied"],"tipVi":"disappointed dùng để mô tả cảm xúc của con người; trong khi disappointing dùng cho sự việc gây thất vọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_charming', 'en-b1-29', 'charming', '/ˈtʃɑːrmɪŋ/', 'B1', 'mê hoặc; đáng yêu; duyên dáng', 'adj.', 'charm (n.), charm (v.), charmed (adj.)', 'Đồng nghĩa: delightful, lovely · Trái nghĩa: unpleasant', 'Có thể dùng để miêu tả cả tính cách con người hoặc địa điểm thu hút.', 'We found a charming little café beside the river.', NULL, 'Chúng tôi đã tìm thấy một quán cà phê nhỏ xinh xắn bên bờ sông.', '{"wordId":"charming","ukIpa":"/ˈtʃɑːmɪŋ/","usIpa":"/ˈtʃɑːrmɪŋ/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"very pleasant or attractive in a way that delights people","vi":"mê hoặc; đáng yêu; duyên dáng"}],"examples":[{"en":"We found a charming little café beside the river.","vi":"Chúng tôi đã tìm thấy một quán cà phê nhỏ xinh xắn bên bờ sông.","audioKind":"ex"},{"en":"Preserving charming historic neighbourhoods can attract visitors while strengthening residents'' sense of belonging to their city.","vi":"Việc bảo tồn các khu phố lịch sử mang nét duyên dáng có thể thu hút du khách đồng thời củng cố ý thức thuộc về thành phố của người dân.","audioKind":"ex2"}],"collocations":[{"en":"charming smile","vi":"nụ cười duyên dáng"},{"en":"charming village","vi":"làng quê nên thơ"},{"en":"charming personality","vi":"tính cách đáng yêu"}],"wordFamily":["charm (n.)","charm (v.)","charmed (adj.)"],"synonyms":["delightful","lovely"],"antonyms":["unpleasant"],"tipVi":"Có thể dùng để miêu tả cả tính cách con người hoặc địa điểm thu hút.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crying', 'en-b1-29', 'crying', '/ˈkraɪɪŋ/', 'B1', 'tiếng khóc; sự khóc; cấp bách; rõ mồn một', 'n.', 'cry (v.), cry (n.)', 'Đồng nghĩa: weeping', 'cũng là dạng hiện phân từ của cry; a crying need chỉ nhu cầu bức thiết.', 'Soft crying came from the baby''s room after midnight.', NULL, 'Tiếng khóc nhẹ vang lên từ phòng của em bé sau nửa đêm.', '{"wordId":"crying","ukIpa":"/ˈkraɪɪŋ/","usIpa":"/ˈkraɪɪŋ/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"the act or sound of shedding tears from emotion or pain","vi":"tiếng khóc; sự khóc"},{"pos":"adj.","en":"extremely serious or obvious, especially when needing attention","vi":"cấp bách; rõ mồn một"}],"examples":[{"en":"Soft crying came from the baby''s room after midnight.","vi":"Tiếng khóc nhẹ vang lên từ phòng của em bé sau nửa đêm.","audioKind":"ex"},{"en":"There is a crying need for affordable childcare in communities where both parents work full time.","vi":"Có một nhu cầu cấp bách về dịch vụ chăm sóc trẻ giá cả phải chăng ở các cộng đồng nơi cả bố mẹ đều đi làm toàn thời gian.","audioKind":"ex2"}],"collocations":[{"en":"stop crying","vi":"ngừng khóc"},{"en":"a crying need","vi":"một nhu cầu cấp bách"},{"en":"a crying shame","vi":"một điều vô cùng đáng tiếc"}],"wordFamily":["cry (v.)","cry (n.)"],"synonyms":["weeping"],"antonyms":[],"tipVi":"cũng là dạng hiện phân từ của cry; a crying need chỉ nhu cầu bức thiết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unbelievable', 'en-b1-29', 'unbelievable', '/ˌʌnbɪˈliːvəbl/', 'B1', 'khó tin; đáng kinh ngạc; cực kỳ tốt hoặc tồi tệ (gây ngạc nhiên lớn)', 'adj.', 'believe (v.), belief (n.), believable (adj.), unbelievably (adv.)', 'Đồng nghĩa: incredible, astonishing · Trái nghĩa: believable', 'Có thể dùng để chỉ điều khó tin, hoặc dùng trong văn nói để nhấn mạnh mức độ cực kỳ tốt hoặc cực kỳ tồi tệ.', 'The view from the mountain was unbelievable at sunrise.', NULL, 'Cảnh quan từ ngọn núi lúc bình minh đẹp đến mức khó tin.', '{"wordId":"unbelievable","ukIpa":"/ˌʌnbɪˈliːvəbl/","usIpa":"/ˌʌnbɪˈliːvəbl/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"So surprising or unlikely that it is hard to believe.","vi":"khó tin; đáng kinh ngạc"},{"pos":"adj.","en":"Extremely good or bad, causing strong surprise.","vi":"cực kỳ tốt hoặc tồi tệ (gây ngạc nhiên lớn)"}],"examples":[{"en":"The view from the mountain was unbelievable at sunrise.","vi":"Cảnh quan từ ngọn núi lúc bình minh đẹp đến mức khó tin.","audioKind":"ex"},{"en":"Some online advertisements promise unbelievable results, making it difficult for consumers to distinguish evidence from exaggeration.","vi":"Một số quảng cáo trực tuyến hứa hẹn những kết quả khó tin, khiến người tiêu dùng khó phân biệt được bằng chứng thực tế và lời phóng đại.","audioKind":"ex2"}],"collocations":[{"en":"an unbelievable story","vi":"một câu chuyện khó tin"},{"en":"unbelievable results","vi":"kết quả đáng kinh ngạc"},{"en":"unbelievable luck","vi":"may mắn khó tin"}],"wordFamily":["believe (v.)","belief (n.)","believable (adj.)","unbelievably (adv.)"],"synonyms":["incredible","astonishing"],"antonyms":["believable"],"tipVi":"Có thể dùng để chỉ điều khó tin, hoặc dùng trong văn nói để nhấn mạnh mức độ cực kỳ tốt hoặc cực kỳ tồi tệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_29_1', 'en-b1-29', 'Cách dùng “comfort” (n.) — sự thoải mái; sự tiện nghi', 'in comfort  ·  take comfort in  ·  comfort someone', 'Khi chỉ sự thoải mái hay niềm an ủi, từ này thường không đếm được; khi làm động từ, nó đi trực tiếp với tân ngữ chỉ người.', 'Họ từ (Word Family): comfortable (adj.), comfortably (adv.), comforting (adj.), discomfort (n.) | Đồng nghĩa: solace, console · Trái nghĩa: discomfort', '[{"hanzi":"I enjoyed the comfort of a warm bed after camping.","pinyin":"","meaning":"Tôi tận hưởng cảm giác thoải mái của chiếc giường ấm áp sau chuyến cắm trại."},{"hanzi":"Support groups can comfort patients by providing opportunities to share experiences and discuss concerns openly.","pinyin":"","meaning":"Các nhóm hỗ trợ có thể an ủi bệnh nhân bằng cách tạo cơ hội để họ chia sẻ kinh nghiệm và cởi mở thảo luận về những lo lắng của mình."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_29_2', 'en-b1-29', 'Cách dùng “amusing” (adj.) — thú vị; buồn cười; làm vui vẻ', 'amusing story  ·  find something amusing  ·  amusing anecdote', 'amusing dùng để miêu tả sự vật, sự việc mang tính chất gây cười; amused dùng để diễn tả cảm giác buồn cười của con người.', 'Họ từ (Word Family): amuse (v.), amused (adj.), amusement (n.), amusingly (adv.) | Đồng nghĩa: funny, entertaining · Trái nghĩa: boring', '[{"hanzi":"My cousin told an amusing story about his cat.","pinyin":"","meaning":"Anh họ tôi kể một câu chuyện rất buồn cười về con mèo của anh ấy."},{"hanzi":"Teachers can use amusing examples to maintain students'' attention while explaining difficult concepts in science lessons.","pinyin":"","meaning":"Giáo viên có thể sử dụng các ví dụ thú vị để duy trì sự chú ý của học sinh khi giải thích các khái niệm khó trong bài học khoa học."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_29_3', 'en-b1-29', 'Cách dùng “enjoyment” (n.) — niềm vui; sự thích thú', 'get enjoyment from  ·  for enjoyment  ·  pure enjoyment', 'Từ này thường không đếm được; khi muốn diễn tả việc tìm thấy niềm vui từ điều gì, hãy dùng cấu trúc get enjoyment from.', 'Họ từ (Word Family): enjoy (v.), enjoyable (adj.), enjoyably (adv.) | Đồng nghĩa: pleasure, delight · Trái nghĩa: displeasure', '[{"hanzi":"My grandfather gets great enjoyment from feeding the birds.","pinyin":"","meaning":"Ông tôi tìm thấy niềm vui lớn lao từ việc cho chim ăn."},{"hanzi":"Schools should encourage reading for enjoyment rather than focusing exclusively on examination performance.","pinyin":"","meaning":"Các trường học nên khuyến khích việc đọc sách vì niềm vui thay vì chỉ tập trung hoàn toàn vào kết quả thi cử."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_29_4', 'en-b1-29', 'Cách dùng “upset” (adj.) — buồn bã; lo lắng; thất vọng', 'feel upset  ·  upset about something  ·  upset the balance', 'Dạng quá khứ và phân từ hai của động từ upset vẫn giữ nguyên là upset; danh từ có trọng âm rơi vào âm tiết đầu.', 'Họ từ (Word Family): upsetting (adj.) | Đồng nghĩa: distressed, unhappy · Trái nghĩa: happy', '[{"hanzi":"Lena felt upset when she lost her favourite scarf.","pinyin":"","meaning":"Lena cảm thấy buồn khi cô ấy làm mất chiếc khăn choàng cổ yêu thích của mình."},{"hanzi":"Sudden changes to school routines can upset younger children, who often rely on predictable daily activities.","pinyin":"","meaning":"Những thay đổi đột ngột trong sinh hoạt ở trường có thể khiến trẻ nhỏ lo âu, vì các em thường quen dựa vào các hoạt động hằng ngày có thể đoán trước."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_29_1', 'en-b1-29', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_1_1', 'ten_b1_29_1', 'dare', 'I finally dared to sing in front of everyone.', 'I finally dared to sing in front of everyone.', '/der/', 'Cuối cùng tôi đã dám hát trước mặt mọi người.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_1_2', 'ten_b1_29_1', 'confident', 'After weeks of practice, I felt confident on stage.', 'After weeks of practice, I felt confident on stage.', '/ˈkɑːnfɪdənt/', 'Sau nhiều tuần tập luyện, tôi cảm thấy rất tự tin khi đứng trên sân khấu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_1_3', 'ten_b1_29_1', 'shock', 'The sudden rise in rent came as a shock.', 'The sudden rise in rent came as a shock.', '/ʃɑːk/', 'Việc tiền thuê nhà tăng đột ngột quả là một cú sốc lớn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_1_4', 'ten_b1_29_1', 'shocked', 'I was shocked to find water flooding the kitchen.', 'I was shocked to find water flooding the kitchen.', '/ʃɑːkt/', 'Tôi chết lặng khi phát hiện nước ngập lê láng trong nhà bếp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_1_5', 'ten_b1_29_1', 'enjoyment', 'My grandfather gets great enjoyment from feeding the birds.', 'My grandfather gets great enjoyment from feeding the birds.', '/ɪnˈdʒɔɪmənt/', 'Ông tôi tìm thấy niềm vui lớn lao từ việc cho chim ăn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_1_6', 'ten_b1_29_1', 'frightening', 'The sudden thunder was frightening, but our dog stayed calm.', 'The sudden thunder was frightening, but our dog stayed calm.', '/ˈfraɪtənɪŋ/', 'Tiếng sấm bất ngờ thật đáng sợ, nhưng chú chó nhà chúng tôi vẫn giữ được bình tĩnh.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_1_7', 'ten_b1_29_1', 'comfort', 'I enjoyed the comfort of a warm bed after camping.', 'I enjoyed the comfort of a warm bed after camping.', '/ˈkʌmfərt/', 'Tôi tận hưởng cảm giác thoải mái của chiếc giường ấm áp sau chuyến cắm trại.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_1_8', 'ten_b1_29_1', 'amusing', 'My cousin told an amusing story about his cat.', 'My cousin told an amusing story about his cat.', '/əˈmjuːzɪŋ/', 'Anh họ tôi kể một câu chuyện rất buồn cười về con mèo của anh ấy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_29_1_1', 'en-b1-29', 'ten_b1_29_1', 'listening', 'listening', 'I finally dared to sing in front of everyone.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một mùi kinh tởm bốc ra từ túi rác bị bỏ quên.","Cuối cùng tôi đã dám hát trước mặt mọi người.","Tôi đã rất thất vọng khi trời mưa khiến buổi dã ngoại trên bãi biển của chúng tôi bị hủy.","Việc tiền thuê nhà tăng đột ngột quả là một cú sốc lớn."]'::jsonb, 1, 'I finally dared to sing in front of everyone. → Cuối cùng tôi đã dám hát trước mặt mọi người.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_29_1_2', 'en-b1-29', 'ten_b1_29_1', 'listening', 'listening', 'After weeks of practice, I felt confident on stage.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi khuyên bạn nên mang theo áo khoác trong chuyến đi dạo này.","Tiếng khóc nhẹ vang lên từ phòng của em bé sau nửa đêm.","Sau nhiều tuần tập luyện, tôi cảm thấy rất tự tin khi đứng trên sân khấu.","Cô ấy rất thích thú với việc trồng các loại cây thảo mộc trên ban công của mình."]'::jsonb, 2, 'After weeks of practice, I felt confident on stage. → Sau nhiều tuần tập luyện, tôi cảm thấy rất tự tin khi đứng trên sân khấu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_29_1_3', 'en-b1-29', 'ten_b1_29_1', 'listening', 'listening', 'The sudden rise in rent came as a shock.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi chết lặng khi phát hiện nước ngập lê láng trong nhà bếp.","Sự hài hước nhẹ nhàng của cô ấy khiến mọi người trong bữa tối đều cảm thấy thoải mái.","Việc tiền thuê nhà tăng đột ngột quả là một cú sốc lớn.","Một mùi khó chịu đang bốc lên từ thùng rác trong bếp."]'::jsonb, 2, 'The sudden rise in rent came as a shock. → Việc tiền thuê nhà tăng đột ngột quả là một cú sốc lớn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_29_2', 'en-b1-29', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_2_1', 'ten_b1_29_2', 'dare', 'Students are more likely to dare to question established ideas when teachers welcome respectful disagreement.', 'Students are more likely to dare to question established ideas when teachers welcome respectful disagreement.', '/der/', 'Học sinh có nhiều khả năng dám đặt câu hỏi về các quan niệm đã có từ trước khi giáo viên cởi mở đón nhận những ý kiến trái chiều mang tính tôn trọng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_2_2', 'ten_b1_29_2', 'confident', 'Students become more confident when teachers provide constructive feedback and opportunities to practise new skills.', 'Students become more confident when teachers provide constructive feedback and opportunities to practise new skills.', '/ˈkɑːnfɪdənt/', 'Học sinh trở nên tự tin hơn khi giáo viên đưa ra những phản hồi mang tính xây dựng và tạo cơ hội rèn luyện các kỹ năng mới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_2_3', 'ten_b1_29_2', 'shock', 'Moving abroad can cause culture shock, particularly when everyday customs differ greatly from those at home.', 'Moving abroad can cause culture shock, particularly when everyday customs differ greatly from those at home.', '/ʃɑːk/', 'Việc chuyển ra nước ngoài sinh sống có thể gây ra cú sốc văn hóa, đặc biệt là khi các phong tục thường ngày khác biệt lớn so với ở quê nhà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_2_4', 'ten_b1_29_2', 'shocked', 'Residents were shocked by the sudden closure of the only hospital serving their rural community.', 'Residents were shocked by the sudden closure of the only hospital serving their rural community.', '/ʃɑːkt/', 'Người dân vô cùng bàng hoàng trước việc bệnh viện duy nhất phục vụ cộng đồng nông thôn của họ bất ngờ đóng cửa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_2_5', 'ten_b1_29_2', 'enjoyment', 'Schools should encourage reading for enjoyment rather than focusing exclusively on examination performance.', 'Schools should encourage reading for enjoyment rather than focusing exclusively on examination performance.', '/ɪnˈdʒɔɪmənt/', 'Các trường học nên khuyến khích việc đọc sách vì niềm vui thay vì chỉ tập trung hoàn toàn vào kết quả thi cử.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_29_2_6', 'ten_b1_29_2', 'frightening', 'Experiencing a major flood can be frightening, especially for children who have never faced a natural disaster.', 'Experiencing a major flood can be frightening, especially for children who have never faced a natural disaster.', '/ˈfraɪtənɪŋ/', 'Trải qua một trận lũ lụt lớn có thể rất đáng sợ, đặc biệt đối với trẻ em chưa từng đối mặt với thảm họa thiên nhiên.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_29_2_1', 'en-b1-29', 'ten_b1_29_2', 'listening', 'listening', 'Students are more likely to dare to question established ideas when teachers welcome respectful disagreement.', NULL, 'Trong câu vừa nghe, từ “dare” mang nghĩa nào sau đây?', '["động từ nguyên thể; nguyên mẫu","sự liên lạc; sự tiếp xúc","thuộc về pháp luật; liên quan đến pháp lý","dám; cả gan"]'::jsonb, 3, '“dare” (/der/): dám; cả gan. Câu đầy đủ: Students are more likely to dare to question established ideas when teachers welcome respectful disagreement.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_29_2_2', 'en-b1-29', 'ten_b1_29_2', 'listening', 'listening', 'Students become more confident when teachers provide constructive feedback and opportunities to practise new skills.', NULL, 'Trong câu vừa nghe, từ “confident” mang nghĩa nào sau đây?', '["tự tin","bất hợp pháp; trái pháp luật","khâu, may, vá","truyền thống; tập quán"]'::jsonb, 0, '“confident” (/ˈkɑːnfɪdənt/): tự tin. Câu đầy đủ: Students become more confident when teachers provide constructive feedback and opportunities to practise new skills.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
