INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_1', 'en-b1-29', NULL, 'comprehensive_test', 'listening', 'dare', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["có liên quan; có dính líu","sự xa hoa; sự sang trọng","đóng băng; phủ đầy băng","dám; cả gan"]'::jsonb, 3, 'dare (/der/) → dám; cả gan; thách thức; khích; lời thách thức', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_2', 'en-b1-29', NULL, 'comprehensive_test', 'listening', 'After weeks of practice, I felt confident on stage.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi rất biết ơn sự giúp đỡ của bạn trong việc chuyển nhà.","Tiếng sấm bất ngờ thật đáng sợ, nhưng chú chó nhà chúng tôi vẫn giữ được bình tĩnh.","Sau nhiều tuần tập luyện, tôi cảm thấy rất tự tin khi đứng trên sân khấu.","Bạn đã làm rất xuất sắc khi sửa chiếc xe đạp cũ đó."]'::jsonb, 2, 'After weeks of practice, I felt confident on stage. → Sau nhiều tuần tập luyện, tôi cảm thấy rất tự tin khi đứng trên sân khấu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_3', 'en-b1-29', NULL, 'comprehensive_test', 'listening', 'shock', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tài khoản","sự bàng hoàng; cú sốc","ánh sáng ban ngày; ban ngày","dỡ đồ (khỏi túi, hộp, vali)"]'::jsonb, 1, 'shock (/ʃɑːk/) → sự bàng hoàng; cú sốc; gây sốc; làm bàng hoàng; sốc y tế; điện giật', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_4', 'en-b1-29', NULL, 'comprehensive_test', 'listening', 'I was shocked to find water flooding the kitchen.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi chết lặng khi phát hiện nước ngập lê láng trong nhà bếp.","Tôi rất biết ơn sự giúp đỡ của bạn trong việc chuyển nhà.","Cảnh quan từ ngọn núi lúc bình minh đẹp đến mức khó tin.","Lena cảm thấy buồn khi cô ấy làm mất chiếc khăn choàng cổ yêu thích của mình."]'::jsonb, 0, 'I was shocked to find water flooding the kitchen. → Tôi chết lặng khi phát hiện nước ngập lê láng trong nhà bếp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_5', 'en-b1-29', NULL, 'comprehensive_test', 'listening', 'enjoyment', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thông báo; cho biết","niềm vui; sự thích thú","nên; phải (chỉ lời khuyên, bổn phận hoặc hành động đúng đắn)","bắp cải; cải bắp"]'::jsonb, 1, 'enjoyment (/ɪnˈdʒɔɪmənt/) → niềm vui; sự thích thú', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_6', 'en-b1-29', NULL, 'comprehensive_test', 'listening', 'The sudden thunder was frightening, but our dog stayed calm.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một mùi kinh tởm bốc ra từ túi rác bị bỏ quên.","Tiếng sấm bất ngờ thật đáng sợ, nhưng chú chó nhà chúng tôi vẫn giữ được bình tĩnh.","Một mùi khó chịu đang bốc lên từ thùng rác trong bếp.","Tôi hối tiếc vì sáng nay đã để quên ô ở nhà."]'::jsonb, 1, 'The sudden thunder was frightening, but our dog stayed calm. → Tiếng sấm bất ngờ thật đáng sợ, nhưng chú chó nhà chúng tôi vẫn giữ được bình tĩnh.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_7', 'en-b1-29', NULL, 'comprehensive_test', 'listening', 'comfort', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["địa điểm; công trường; khu di tích","sự thoải mái; sự tiện nghi","nữ chủ nhà; bà chủ nhà cho thuê trọ","dừa; quả dừa"]'::jsonb, 1, 'comfort (/ˈkʌmfərt/) → sự thoải mái; sự tiện nghi; sự an ủi; niềm khuây khỏa; an ủi; vỗ về', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_8', 'en-b1-29', NULL, 'comprehensive_test', 'listening', 'My cousin told an amusing story about his cat.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã tìm thấy một quán cà phê nhỏ xinh xắn bên bờ sông.","Anh họ tôi kể một câu chuyện rất buồn cười về con mèo của anh ấy.","Lena cảm thấy buồn khi cô ấy làm mất chiếc khăn choàng cổ yêu thích của mình.","Cô ấy rất thích thú với việc trồng các loại cây thảo mộc trên ban công của mình."]'::jsonb, 1, 'My cousin told an amusing story about his cat. → Anh họ tôi kể một câu chuyện rất buồn cười về con mèo của anh ấy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
