INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_18', 'en-b1-29', NULL, 'comprehensive_test', 'reading', NULL, 'Students are more likely to dare to question established ideas when teachers welcome respectful disagreement.', 'Dựa vào câu trên, từ “dare” có nghĩa phù hợp nhất là gì?', '["thông báo; lời công bố","tấm thảm; chiếu","thông minh; sáng suốt; có khả năng hiểu biết tốt","dám; cả gan"]'::jsonb, 3, 'dare: dám; cả gan; thách thức; khích; lời thách thức. Dịch cả câu: Học sinh có nhiều khả năng dám đặt câu hỏi về các quan niệm đã có từ trước khi giáo viên cởi mở đón nhận những ý kiến trái chiều mang tính tôn trọng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_19', 'en-b1-29', NULL, 'comprehensive_test', 'reading', NULL, 'Students become more confident when teachers provide constructive feedback and opportunities to practise new skills.', 'Dựa vào câu trên, từ “confident” có nghĩa phù hợp nhất là gì?', '["kẹo cao su","nhân lên; làm phép nhân","ngày nay; hiện nay","tự tin"]'::jsonb, 3, 'confident: tự tin; tin tưởng; chắc chắn. Dịch cả câu: Học sinh trở nên tự tin hơn khi giáo viên đưa ra những phản hồi mang tính xây dựng và tạo cơ hội rèn luyện các kỹ năng mới.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_20', 'en-b1-29', NULL, 'comprehensive_test', 'reading', NULL, 'Moving abroad can cause culture shock, particularly when everyday customs differ greatly from those at home.', 'Dựa vào câu trên, từ “shock” có nghĩa phù hợp nhất là gì?', '["cắn; ngoạm; đốt","phiếu giảm giá; phiếu ưu đãi","sự bàng hoàng; cú sốc","người hướng dẫn; huấn luyện viên"]'::jsonb, 2, 'shock: sự bàng hoàng; cú sốc; gây sốc; làm bàng hoàng; sốc y tế; điện giật. Dịch cả câu: Việc chuyển ra nước ngoài sinh sống có thể gây ra cú sốc văn hóa, đặc biệt là khi các phong tục thường ngày khác biệt lớn so với ở quê nhà.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_21', 'en-b1-29', NULL, 'comprehensive_test', 'reading', NULL, 'Residents were shocked by the sudden closure of the only hospital serving their rural community.', 'Dựa vào câu trên, từ “shocked” có nghĩa phù hợp nhất là gì?', '["cực kỳ ngạc nhiên và buồn bã trước điều gì đó bất ngờ; bị sốc; bàng hoàng","câu trả lời; sự đáp lại","truyện trinh thám ly kỳ; phim kinh dị ly kỳ","chim cánh cụt"]'::jsonb, 0, 'shocked: cực kỳ ngạc nhiên và buồn bã trước điều gì đó bất ngờ; bị sốc; bàng hoàng; cảm thấy phản đối mạnh mẽ trước điều gì đó xúc phạm hoặc sai trái; phẫn nộ. Dịch cả câu: Người dân vô cùng bàng hoàng trước việc bệnh viện duy nhất phục vụ cộng đồng nông thôn của họ bất ngờ đóng cửa.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_22', 'en-b1-29', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mê hoặc; đáng yêu; duyên dáng”', '["mad","stationery","charming","triangle"]'::jsonb, 2, 'mê hoặc; đáng yêu; duyên dáng → charming (/ˈtʃɑːrmɪŋ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_23', 'en-b1-29', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tiếng khóc; sự khóc”', '["crying","workshop","muscle","chemist"]'::jsonb, 0, 'tiếng khóc; sự khóc → crying (/ˈkraɪɪŋ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_29_24', 'en-b1-29', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khó tin; đáng kinh ngạc”', '["brunch","unbelievable","previous","shoot"]'::jsonb, 1, 'khó tin; đáng kinh ngạc → unbelievable (/ˌʌnbɪˈliːvəbl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-30', 'en', 'Bài 30: Cảm xúc & Tính cách (3) - CEFR B1', 'CEFR B1', 'B1 · Cảm xúc', '22 từ vựng Tiếng Anh CEFR B1 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3030, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stressful', 'en-b1-30', 'stressful', '/ˈstresfəl/', 'B1', 'căng thẳng; gây áp lực tâm lý', 'adj.', 'stress (n.), stress (v.), stressed (adj.)', 'Đồng nghĩa: demanding, nerve-racking · Trái nghĩa: relaxing', 'stressful chỉ tính chất gây áp lực; stressed chỉ cảm giác bị căng thẳng của con người.', 'Moving house was stressful, but our friends helped.', NULL, 'Việc chuyển nhà rất căng thẳng, nhưng bạn bè đã giúp đỡ chúng tôi.', '{"wordId":"stressful","ukIpa":"/ˈstresfəl/","usIpa":"/ˈstresfəl/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Causing worry or mental strain","vi":"căng thẳng; gây áp lực tâm lý"}],"examples":[{"en":"Moving house was stressful, but our friends helped.","vi":"Việc chuyển nhà rất căng thẳng, nhưng bạn bè đã giúp đỡ chúng tôi.","audioKind":"ex"},{"en":"Long commutes can make working life more stressful and leave less time for family activities.","vi":"Việc đi lại quãng đường dài mỗi ngày có thể làm cho đời sống công việc thêm phần căng thẳng và chừa lại ít thời gian hơn cho các hoạt động gia đình.","audioKind":"ex2"}],"collocations":[{"en":"a stressful situation","vi":"tình huống căng thẳng"},{"en":"a stressful job","vi":"công việc áp lực"},{"en":"a stressful experience","vi":"trải nghiệm đầy căng thẳng"}],"wordFamily":["stress (n.)","stress (v.)","stressed (adj.)"],"synonyms":["demanding","nerve-racking"],"antonyms":["relaxing"],"tipVi":"stressful chỉ tính chất gây áp lực; stressed chỉ cảm giác bị căng thẳng của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mood', 'en-b1-30', 'mood', '/muːd/', 'B1', 'tâm trạng; cảm xúc; bầu không khí; không khí', 'n.', 'moody (adj.), moodiness (n.)', NULL, 'in the mood for đi theo sau là danh từ; nếu đi với động từ thì dùng to do.', 'A short walk usually puts me in a better mood.', NULL, 'Đi dạo một lát thường giúp tâm trạng tôi thoải mái hơn.', '{"wordId":"mood","ukIpa":"/muːd/","usIpa":"/muːd/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"the way someone feels at a particular time","vi":"tâm trạng; cảm xúc"},{"pos":"n.","en":"the feeling that a place, event, or artwork creates","vi":"bầu không khí; không khí"}],"examples":[{"en":"A short walk usually puts me in a better mood.","vi":"Đi dạo một lát thường giúp tâm trạng tôi thoải mái hơn.","audioKind":"ex"},{"en":"Access to green spaces can improve residents'' mood and encourage more positive interactions within urban communities.","vi":"Việc tiếp cận các không gian xanh có thể cải thiện tâm trạng của cư dân và thúc đẩy sự tương tác tích cực hơn trong cộng đồng đô thị.","audioKind":"ex2"}],"collocations":[{"en":"in a good mood","vi":"tâm trạng tốt"},{"en":"in the mood for","vi":"có hứng làm gì"},{"en":"mood swings","vi":"sự thay đổi cảm xúc thất thường"},{"en":"set the mood","vi":"tạo không khí"}],"wordFamily":["moody (adj.)","moodiness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"in the mood for đi theo sau là danh từ; nếu đi với động từ thì dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_annoy', 'en-b1-30', 'annoy', '/əˈnɔɪ/', 'B1', 'làm phiền; làm bực mình; chọc tức', 'v.', 'annoyed (adj.), annoying (adj.), annoyance (n.)', 'Đồng nghĩa: irritate, bother · Trái nghĩa: please', 'Cảm giác bực bội ở người dùng annoyed; sự việc gây phiền toái dùng annoying.', 'Those dripping taps annoy me when I try to sleep.', NULL, 'Mấy cái vòi nước nhỏ giọt đó làm tôi phát bực khi định đi ngủ.', '{"wordId":"annoy","ukIpa":"/əˈnɔɪ/","usIpa":"/əˈnɔɪ/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"To make someone feel slightly angry or irritated.","vi":"làm phiền; làm bực mình; chọc tức"}],"examples":[{"en":"Those dripping taps annoy me when I try to sleep.","vi":"Mấy cái vòi nước nhỏ giọt đó làm tôi phát bực khi định đi ngủ.","audioKind":"ex"},{"en":"Frequent online advertisements can annoy users and discourage them from returning to otherwise useful educational websites.","vi":"Các quảng cáo trực tuyến xuất hiện liên tục có thể làm người dùng khó chịu và khiến họ không muốn quay lại những trang web giáo dục vốn hữu ích.","audioKind":"ex2"}],"collocations":[{"en":"annoy someone","vi":"làm ai đó bực mình"},{"en":"annoyed with someone","vi":"bực mình với ai"},{"en":"annoying habit","vi":"thói quen phiền phức"}],"wordFamily":["annoyed (adj.)","annoying (adj.)","annoyance (n.)"],"synonyms":["irritate","bother"],"antonyms":["please"],"tipVi":"Cảm giác bực bội ở người dùng annoyed; sự việc gây phiền toái dùng annoying.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stressed', 'en-b1-30', 'stressed', '/strest/', 'B1', 'căng thẳng; lo âu; áp lực; được nhấn trọng âm; chịu ứng suất; chịu áp lực cơ học', 'adj.', 'stress (n.), stress (v.), stressful (adj.)', 'Đồng nghĩa: anxious, tense · Trái nghĩa: relaxed, unstressed', 'Cũng có thể đóng vai trò là quá khứ phân từ của động từ stress, mang nghĩa ''được nhấn mạnh''.', 'I felt stressed before my first driving lesson.', NULL, 'Tôi cảm thấy rất căng thẳng trước buổi học lái xe đầu tiên.', '{"wordId":"stressed","ukIpa":"/strest/","usIpa":"/strest/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling worried and unable to relax","vi":"căng thẳng; lo âu; áp lực"},{"pos":"adj.","en":"Pronounced with greater emphasis than surrounding sounds","vi":"được nhấn trọng âm"},{"pos":"adj.","en":"Experiencing physical force that may cause strain or damage","vi":"chịu ứng suất; chịu áp lực cơ học"}],"examples":[{"en":"I felt stressed before my first driving lesson.","vi":"Tôi cảm thấy rất căng thẳng trước buổi học lái xe đầu tiên.","audioKind":"ex"},{"en":"Students who feel stressed during examinations may benefit from regular exercise and adequate sleep.","vi":"Những học sinh cảm thấy áp lực trong các kỳ thi có thể cải thiện tình trạng này nhờ tập thể dục đều đặn và ngủ đủ giấc.","audioKind":"ex2"}],"collocations":[{"en":"feel stressed","vi":"cảm thấy căng thẳng"},{"en":"stressed about exams","vi":"lo âu vì thi cử"},{"en":"a stressed syllable","vi":"một âm tiết được nhấn trọng âm"},{"en":"highly stressed components","vi":"các linh kiện chịu ứng suất cao"}],"wordFamily":["stress (n.)","stress (v.)","stressful (adj.)"],"synonyms":["anxious","tense"],"antonyms":["relaxed","unstressed"],"tipVi":"Cũng có thể đóng vai trò là quá khứ phân từ của động từ stress, mang nghĩa ''được nhấn mạnh''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enjoyable', 'en-b1-30', 'enjoyable', '/ɪnˈdʒɔɪəbl/', 'B1', 'thú vị; dễ chịu; mang lại niềm vui', 'adj.', 'enjoy (v.), enjoyment (n.), enjoyably (adv.)', 'Đồng nghĩa: pleasant, pleasurable, fun · Trái nghĩa: unpleasant', 'Tính từ chỉ hoạt động mang lại niềm vui là enjoyable, không dùng enjoyed.', 'The cooking class was enjoyable, especially making fresh pasta.', NULL, 'Lớp học nấu ăn rất thú vị, đặc biệt là công đoạn làm mì tươi.', '{"wordId":"enjoyable","ukIpa":"/ɪnˈdʒɔɪəbl/","usIpa":"/ɪnˈdʒɔɪəbl/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Giving pleasure or making you feel happy","vi":"thú vị; dễ chịu; mang lại niềm vui"}],"examples":[{"en":"The cooking class was enjoyable, especially making fresh pasta.","vi":"Lớp học nấu ăn rất thú vị, đặc biệt là công đoạn làm mì tươi.","audioKind":"ex"},{"en":"Making physical activity enjoyable can encourage children to develop healthy habits that continue into adulthood.","vi":"Việc biến các hoạt động thể chất thành niềm vui có thể khuyến khích trẻ nhỏ hình thành thói quen lành mạnh kéo dài đến tận tuổi trưởng thành.","audioKind":"ex2"}],"collocations":[{"en":"enjoyable experience","vi":"trải nghiệm thú vị"},{"en":"enjoyable activity","vi":"hoạt động bổ ích"},{"en":"highly enjoyable","vi":"vô cùng thú vị"},{"en":"an enjoyable evening","vi":"một buổi tối tuyệt vời"}],"wordFamily":["enjoy (v.)","enjoyment (n.)","enjoyably (adv.)"],"synonyms":["pleasant","pleasurable","fun"],"antonyms":["unpleasant"],"tipVi":"Tính từ chỉ hoạt động mang lại niềm vui là enjoyable, không dùng enjoyed.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_congratulation', 'en-b1-30', 'congratulation', '/kənˌɡrætʃəˈleɪʃən/', 'B1', 'lời chúc mừng; sự chúc mừng', 'n.', 'congratulate (v.), congratulatory (adj.)', NULL, 'Lời chúc mừng thường ở dạng số nhiều congratulations, theo sau là on và danh động từ hoặc sự việc.', 'We sent our congratulations when she passed her driving test.', NULL, 'Chúng tôi đã gửi lời chúc mừng khi cô ấy vượt qua kỳ thi lái xe.', '{"wordId":"congratulation","ukIpa":"/kənˌɡrætʃəˈleɪʃən/","usIpa":"/kənˌɡrætʃəˈleɪʃən/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"An expression of pleasure at someone''s success or good fortune.","vi":"lời chúc mừng; sự chúc mừng"}],"examples":[{"en":"We sent our congratulations when she passed her driving test.","vi":"Chúng tôi đã gửi lời chúc mừng khi cô ấy vượt qua kỳ thi lái xe.","audioKind":"ex"},{"en":"Offering congratulations to students who achieve personal goals can strengthen their confidence and encourage further learning.","vi":"Việc gửi lời chúc mừng tới những học sinh đạt được mục tiêu cá nhân có thể củng cố sự tự tin và khuyến khích các em học tập tiến xa hơn.","audioKind":"ex2"}],"collocations":[{"en":"congratulations on","vi":"chúc mừng về điều gì"},{"en":"a letter of congratulation","vi":"thư chúc mừng"},{"en":"warm congratulations","vi":"lời chúc mừng nồng nhiệt"}],"wordFamily":["congratulate (v.)","congratulatory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Lời chúc mừng thường ở dạng số nhiều congratulations, theo sau là on và danh động từ hoặc sự việc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frighten', 'en-b1-30', 'frighten', '/ˈfraɪtən/', 'B1', 'làm cho sợ hãi; dọa', 'v.', 'fright (n.), frightened (adj.), frightening (adj.)', 'Đồng nghĩa: scare, alarm · Trái nghĩa: reassure', 'Frightened chỉ cảm giác sợ hãi của con người; frightening chỉ tính chất đáng sợ của sự vật.', 'Sudden loud noises can frighten our new puppy.', NULL, 'Tiếng động lớn bất ngờ có thể làm chú cún con mới của chúng ta sợ hãi.', '{"wordId":"frighten","ukIpa":"/ˈfraɪtən/","usIpa":"/ˈfraɪtən/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"To make someone feel afraid.","vi":"làm cho sợ hãi; dọa"}],"examples":[{"en":"Sudden loud noises can frighten our new puppy.","vi":"Tiếng động lớn bất ngờ có thể làm chú cún con mới của chúng ta sợ hãi.","audioKind":"ex"},{"en":"Alarming news reports may frighten children, so adults should explain difficult events in an appropriate way.","vi":"Các bản tin đáng sợ có thể làm trẻ em hoảng sợ, vì vậy người lớn nên giải thích các sự việc khó khăn theo cách phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"frighten someone away","vi":"làm ai đó sợ chạy mất"},{"en":"frighten someone into doing","vi":"đe dọa ép ai làm gì"},{"en":"frighten someone to death","vi":"làm ai đó sợ chết khiếp"}],"wordFamily":["fright (n.)","frightened (adj.)","frightening (adj.)"],"synonyms":["scare","alarm"],"antonyms":["reassure"],"tipVi":"Frightened chỉ cảm giác sợ hãi của con người; frightening chỉ tính chất đáng sợ của sự vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brave', 'en-b1-30', 'brave', '/breɪv/', 'B1', 'dũng cảm; can đảm; dám đương đầu; dũng cảm đối mặt', 'adj.', 'bravery (n.), bravely (adv.)', 'Đồng nghĩa: courageous, courageous · Trái nghĩa: cowardly', 'brave không có nghĩa là hoàn toàn không sợ hãi, mà là dẫu sợ nhưng vẫn dám đối mặt.', 'You were brave to speak in front of everyone.', NULL, 'Bạn thật dũng cảm khi dám phát biểu trước tất cả mọi người.', '{"wordId":"brave","ukIpa":"/breɪv/","usIpa":"/breɪv/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Willing to face danger or difficulty despite feeling afraid.","vi":"dũng cảm; can đảm"},{"pos":"v.","en":"To face something dangerous or unpleasant with courage.","vi":"dám đương đầu; dũng cảm đối mặt"}],"examples":[{"en":"You were brave to speak in front of everyone.","vi":"Bạn thật dũng cảm khi dám phát biểu trước tất cả mọi người.","audioKind":"ex"},{"en":"It takes brave leadership to introduce necessary environmental reforms when powerful groups strongly oppose them.","vi":"Cần có một bộ máy lãnh đạo dũng cảm để đưa ra những cải cách môi trường cần thiết khi các nhóm có thế lực kịch liệt phản đối.","audioKind":"ex2"}],"collocations":[{"en":"a brave decision","vi":"một quyết định dũng cảm"},{"en":"brave enough to","vi":"đủ dũng cảm để làm gì"},{"en":"brave the cold","vi":"bất chấp giá lạnh; đương đầu với cái lạnh"}],"wordFamily":["bravery (n.)","bravely (adv.)"],"synonyms":["courageous","courageous"],"antonyms":["cowardly"],"tipVi":"brave không có nghĩa là hoàn toàn không sợ hãi, mà là dẫu sợ nhưng vẫn dám đối mặt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_idiot', 'en-b1-30', 'idiot', '/ˈɪdiət/', 'B1', 'tên ngốc; kẻ đần độn', 'n.', 'idiotic (adj.), idiotically (adv.), idiocy (n.)', 'Đồng nghĩa: fool', 'Từ này mang tính xúc phạm, không phải là thuật ngữ y tế dùng để mô tả tình trạng khuyết tật trí tuệ.', 'I felt like an idiot after losing my keys again.', NULL, 'Tôi cảm thấy mình thật ngốc nghếch sau khi lại làm mất chìa khóa.', '{"wordId":"idiot","ukIpa":"/ˈɪdiət/","usIpa":"/ˈɪdiət/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"An insulting word for someone considered very foolish.","vi":"tên ngốc; kẻ đần độn"}],"examples":[{"en":"I felt like an idiot after losing my keys again.","vi":"Tôi cảm thấy mình thật ngốc nghếch sau khi lại làm mất chìa khóa.","audioKind":"ex"},{"en":"Calling a classmate an idiot can damage their confidence and undermine efforts to create a supportive learning environment.","vi":"Gọi một bạn cùng lớp là đồ ngốc có thể làm tổn hại lòng tự tin của họ và làm xói mòn nỗ lực xây dựng một môi trường học tập mang tính hỗ trợ.","audioKind":"ex2"}],"collocations":[{"en":"feel like an idiot","vi":"cảm thấy mình thật ngốc"},{"en":"a complete idiot","vi":"một kẻ hoàn toàn ng ngốc"}],"wordFamily":["idiotic (adj.)","idiotically (adv.)","idiocy (n.)"],"synonyms":["fool"],"antonyms":[],"tipVi":"Từ này mang tính xúc phạm, không phải là thuật ngữ y tế dùng để mô tả tình trạng khuyết tật trí tuệ.","noteVi":"Cách gọi mang tính xúc phạm, vui lòng sử dụng thận trọng.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_courage', 'en-b1-30', 'courage', '/ˈkɜːrɪdʒ/', 'B1', 'sự dũng cảm; lòng can đảm', 'n.', 'courageous (adj.), courageously (adv.)', 'Đồng nghĩa: bravery · Trái nghĩa: cowardice', 'Thường là danh từ không đếm được; cụm từ "dũng cảm làm gì" dùng courage to do.', 'It took courage to admit my mistake in class.', NULL, 'Tôi phải rất can đảm mới dám thừa nhận lỗi lầm của mình trước lớp.', '{"wordId":"courage","ukIpa":"/ˈkʌrɪdʒ/","usIpa":"/ˈkɜːrɪdʒ/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"Ability to face danger or difficulty despite feeling afraid.","vi":"sự dũng cảm; lòng can đảm"}],"examples":[{"en":"It took courage to admit my mistake in class.","vi":"Tôi phải rất can đảm mới dám thừa nhận lỗi lầm của mình trước lớp.","audioKind":"ex"},{"en":"Young people need courage to challenge unfair practices, especially when their opinions differ from those of others.","vi":"Giới trẻ cần có lòng dũng cảm để thách thức những tập tục bất công, đặc biệt là khi quan điểm của họ khác với những người khác.","audioKind":"ex2"}],"collocations":[{"en":"have the courage to do something","vi":"có can đảm làm điều gì đó"},{"en":"show courage","vi":"thể hiện lòng dũng cảm"},{"en":"take courage","vi":"lấy hết can đảm"}],"wordFamily":["courageous (adj.)","courageously (adv.)"],"synonyms":["bravery"],"antonyms":["cowardice"],"tipVi":"Thường là danh từ không đếm được; cụm từ \"dũng cảm làm gì\" dùng courage to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_satisfied', 'en-b1-30', 'satisfied', '/ˈsætɪsfaɪd/', 'B1', 'hài lòng; mãn nguyện; tin chắc; bị thuyết phục', 'adj.', 'satisfy (v.), satisfaction (n.), satisfying (adj.), satisfactory (adj.)', 'Đồng nghĩa: pleased, content · Trái nghĩa: dissatisfied, disappointed', 'Dùng satisfied khi chỉ người cảm thấy hài lòng; dùng satisfying để chỉ sự việc mang lại sự hài lòng.', 'I''m satisfied with these shoes; they fit perfectly.', NULL, 'Tôi rất hài lòng với đôi giày này; chúng vừa vặn một cách hoàn hảo.', '{"wordId":"satisfied","ukIpa":"/ˈsætɪsfaɪd/","usIpa":"/ˈsætɪsfaɪd/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Pleased because something meets your needs or expectations.","vi":"hài lòng; mãn nguyện"},{"pos":"adj.","en":"Convinced that something is true or has been done properly.","vi":"tin chắc; bị thuyết phục"}],"examples":[{"en":"I''m satisfied with these shoes; they fit perfectly.","vi":"Tôi rất hài lòng với đôi giày này; chúng vừa vặn một cách hoàn hảo.","audioKind":"ex"},{"en":"Employees who feel satisfied with their working conditions are more likely to remain with the same organisation.","vi":"Những nhân viên cảm thấy hài lòng với điều kiện làm việc của họ sẽ có nhiều khả năng gắn bó lâu dài với cùng một tổ chức hơn.","audioKind":"ex2"}],"collocations":[{"en":"satisfied with","vi":"hài lòng với"},{"en":"fully satisfied","vi":"hoàn toàn hài lòng"},{"en":"satisfied that","vi":"tin chắc rằng"}],"wordFamily":["satisfy (v.)","satisfaction (n.)","satisfying (adj.)","satisfactory (adj.)"],"synonyms":["pleased","content"],"antonyms":["dissatisfied","disappointed"],"tipVi":"Dùng satisfied khi chỉ người cảm thấy hài lòng; dùng satisfying để chỉ sự việc mang lại sự hài lòng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_emotional', 'en-b1-30', 'emotional', '/ɪˈmoʊʃənəl/', 'B1', 'thuộc về cảm xúc; thuộc về tinh thần; dễ xúc động; đầy cảm xúc', 'adj.', 'emotion (n.), emotionally (adv.), unemotional (adj.)', 'Trái nghĩa: unemotional', 'emotional không nhất thiết chỉ sự đau buồn, mà còn có thể chỉ những cảm xúc mạnh mẽ như niềm vui.', 'Her friends gave her emotional support during the move.', NULL, 'Bạn bè của cô ấy đã hỗ trợ tinh thần cho cô ấy trong suốt thời gian chuyển nhà.', '{"wordId":"emotional","ukIpa":"/ɪˈməʊʃənəl/","usIpa":"/ɪˈmoʊʃənəl/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Related to feelings rather than thoughts or physical needs.","vi":"thuộc về cảm xúc; thuộc về tinh thần"},{"pos":"adj.","en":"Showing or experiencing strong feelings.","vi":"dễ xúc động; đầy cảm xúc"}],"examples":[{"en":"Her friends gave her emotional support during the move.","vi":"Bạn bè của cô ấy đã hỗ trợ tinh thần cho cô ấy trong suốt thời gian chuyển nhà.","audioKind":"ex"},{"en":"Schools should support children''s emotional development alongside academic progress to promote their long-term well-being.","vi":"Nhà trường nên hỗ trợ sự phát triển cảm xúc của trẻ song song với tiến độ học tập nhằm thúc đẩy sự phát triển toàn diện lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"emotional support","vi":"hỗ trợ tinh thần"},{"en":"emotional well-being","vi":"sức khỏe cảm xúc"},{"en":"emotional development","vi":"sự phát triển cảm xúc"},{"en":"become emotional","vi":"trở nên xúc động"}],"wordFamily":["emotion (n.)","emotionally (adv.)","unemotional (adj.)"],"synonyms":[],"antonyms":["unemotional"],"tipVi":"emotional không nhất thiết chỉ sự đau buồn, mà còn có thể chỉ những cảm xúc mạnh mẽ như niềm vui.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impressed', 'en-b1-30', 'impressed', '/ɪmˈprest/', 'B1', 'ấn tượng; khâm phục; ngưỡng mộ', 'adj.', 'impress (v.), impression (n.), impressive (adj.), impressively (adv.)', 'Trái nghĩa: unimpressed', 'impressed dùng để miêu tả cảm xúc của con người; impressive dùng để miêu tả sự vật gây ấn tượng.', 'I was impressed by how quickly you fixed the bike.', NULL, 'Tôi rất ấn tượng với việc bạn sửa chiếc xe đạp nhanh đến thế.', '{"wordId":"impressed","ukIpa":"/ɪmˈprest/","usIpa":"/ɪmˈprest/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling admiration because someone or something is particularly good.","vi":"ấn tượng; khâm phục; ngưỡng mộ"}],"examples":[{"en":"I was impressed by how quickly you fixed the bike.","vi":"Tôi rất ấn tượng với việc bạn sửa chiếc xe đạp nhanh đến thế.","audioKind":"ex"},{"en":"Visitors are often impressed by museums that combine interactive technology with carefully preserved historical objects.","vi":"Du khách thường rất ấn tượng với những bảo tàng kết hợp giữa công nghệ tương tác và các hiện vật lịch sử được bảo tồn cẩn thận.","audioKind":"ex2"}],"collocations":[{"en":"impressed by","vi":"ấn tượng bởi"},{"en":"impressed with","vi":"ấn tượng với"},{"en":"deeply impressed","vi":"vô cùng ấn tượng"}],"wordFamily":["impress (v.)","impression (n.)","impressive (adj.)","impressively (adv.)"],"synonyms":[],"antonyms":["unimpressed"],"tipVi":"impressed dùng để miêu tả cảm xúc của con người; impressive dùng để miêu tả sự vật gây ấn tượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_excitement', 'en-b1-30', 'excitement', '/ɪkˈsaɪtmənt/', 'B1', 'sự phấn khích; sự hồi hộp mong chờ; điều thú vị; điều kích thích', 'n.', 'excite (v.), excited (adj.), exciting (adj.), excitedly (adv.)', 'Đồng nghĩa: thrill, enthusiasm · Trái nghĩa: boredom', 'Biểu thị cảm xúc phấn khích thường là danh từ không đếm được: with excitement.', 'The children jumped with excitement when the puppies arrived.', NULL, 'lũ trẻ nhảy cẫng lên vì phấn khích khi những chú chó con đến.', '{"wordId":"excitement","ukIpa":"/ɪkˈsaɪtmənt/","usIpa":"/ɪkˈsaɪtmənt/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"a feeling of great enthusiasm and eager anticipation","vi":"sự phấn khích; sự hồi hộp mong chờ"},{"pos":"n.","en":"something that creates strong interest or enthusiasm","vi":"điều thú vị; điều kích thích"}],"examples":[{"en":"The children jumped with excitement when the puppies arrived.","vi":"lũ trẻ nhảy cẫng lên vì phấn khích khi những chú chó con đến.","audioKind":"ex"},{"en":"Although international sporting events generate excitement, host cities must carefully assess their long-term financial costs.","vi":"Mặc dù các sự kiện thể thao quốc tế tạo ra sự phấn khích lớn, nhưng các thành phố đăng cai phải đánh giá cẩn thận chi phí tài chính dài hạn của chúng.","audioKind":"ex2"}],"collocations":[{"en":"with excitement","vi":"trong sự phấn khích"},{"en":"a sense of excitement","vi":"cảm giác phấn khích"},{"en":"generate excitement","vi":"tạo ra sự phấn khích"},{"en":"contain your excitement","vi":"kìm nén sự phấn khích"}],"wordFamily":["excite (v.)","excited (adj.)","exciting (adj.)","excitedly (adv.)"],"synonyms":["thrill","enthusiasm"],"antonyms":["boredom"],"tipVi":"Biểu thị cảm xúc phấn khích thường là danh từ không đếm được: with excitement.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_laughter', 'en-b1-30', 'laughter', '/ˈlæftər/', 'B1', 'tiếng cười; sự cười', 'n.', 'laugh (v.), laughing (adj.), laughable (adj.)', NULL, 'Laughter là danh từ không đếm được; diễn tả ''một trận cười'' dùng a burst of laughter.', 'Laughter filled the kitchen when the puppy sneezed.', NULL, 'Phòng bếp ngập tràn tiếng cười khi chú cún con hắt xì.', '{"wordId":"laughter","ukIpa":"/ˈlɑːftə/","usIpa":"/ˈlæftər/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"The sound or action of laughing","vi":"tiếng cười; sự cười"}],"examples":[{"en":"Laughter filled the kitchen when the puppy sneezed.","vi":"Phòng bếp ngập tràn tiếng cười khi chú cún con hắt xì.","audioKind":"ex"},{"en":"Shared laughter can strengthen social bonds and help people manage stress in demanding work environments.","vi":"Những tiếng cười chia sẻ cùng nhau có thể thắt chặt các mối quan hệ xã hội và giúp mọi người quản lý căng thẳng trong môi trường làm việc đòi hỏi khắt khe.","audioKind":"ex2"}],"collocations":[{"en":"burst into laughter","vi":"bật cười lớn"},{"en":"roar with laughter","vi":"cười vang"},{"en":"a burst of laughter","vi":"một tràng cười"},{"en":"infectious laughter","vi":"tiếng cười dễ lây lan"}],"wordFamily":["laugh (v.)","laughing (adj.)","laughable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Laughter là danh từ không đếm được; diễn tả ''một trận cười'' dùng a burst of laughter.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pride', 'en-b1-30', 'pride', '/praɪd/', 'B1', 'niềm tự hào; sự hãnh diện; lòng tự trọng; tính kiêu hãnh; lấy làm tự hào; kiêu hãnh về', 'n.', 'proud (adj.), proudly (adv.)', 'Trái nghĩa: shame', 'Động từ dùng pride oneself on; tính từ dùng proud of.', 'Her face shone with pride as she displayed her painting.', NULL, 'Khuôn mặt cô rạng ngời niềm tự hào khi trưng bày bức tranh của mình.', '{"wordId":"pride","ukIpa":"/praɪd/","usIpa":"/praɪd/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"Pleasure and satisfaction in achievements, qualities, or people you value.","vi":"niềm tự hào; sự hãnh diện"},{"pos":"n.","en":"Respect for yourself, sometimes involving an exaggerated sense of importance.","vi":"lòng tự trọng; tính kiêu hãnh"},{"pos":"v.","en":"To feel especially pleased about your own qualities or achievements.","vi":"lấy làm tự hào; kiêu hãnh về"}],"examples":[{"en":"Her face shone with pride as she displayed her painting.","vi":"Khuôn mặt cô rạng ngời niềm tự hào khi trưng bày bức tranh của mình.","audioKind":"ex"},{"en":"Schools can foster community pride by encouraging students to participate in projects that improve their local environment.","vi":"Nhà trường có thể nuôi dưỡng niềm tự hào cộng đồng bằng cách khuyến khích học sinh tham gia vào các dự án cải thiện môi trường địa phương.","audioKind":"ex2"}],"collocations":[{"en":"take pride in","vi":"tự hào về"},{"en":"a sense of pride","vi":"niềm tự hào"},{"en":"hurt someone''s pride","vi":"làm tổn thương lòng tự trọng của ai đó"},{"en":"pride yourself on","vi":"tự hào về bản thân"}],"wordFamily":["proud (adj.)","proudly (adv.)"],"synonyms":[],"antonyms":["shame"],"tipVi":"Động từ dùng pride oneself on; tính từ dùng proud of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dislike', 'en-b1-30', 'dislike', '/dɪsˈlaɪk/', 'B1', 'không thích; ghét; chán ghét; sự không thích; ác cảm; niềm chán ghét', 'v.', NULL, 'Trái nghĩa: like', 'Dislike theo sau bởi danh từ hoặc danh động từ: dislike waiting.', 'I dislike waiting outside when it is raining.', NULL, 'Tôi không thích đứng chờ bên ngoài trời mưa.', '{"wordId":"dislike","ukIpa":"/dɪsˈlaɪk/","usIpa":"/dɪsˈlaɪk/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"To find someone or something unpleasant or not enjoyable.","vi":"không thích; ghét; chán ghét"},{"pos":"n.","en":"A feeling of not liking someone or something.","vi":"sự không thích; ác cảm; niềm chán ghét"}],"examples":[{"en":"I dislike waiting outside when it is raining.","vi":"Tôi không thích đứng chờ bên ngoài trời mưa.","audioKind":"ex"},{"en":"Some students dislike group assignments because they feel that individual contributions are not assessed fairly.","vi":"Một số học sinh không thích làm bài tập nhóm vì các em cảm thấy những đóng góp cá nhân không được đánh giá công bằng.","audioKind":"ex2"}],"collocations":[{"en":"dislike doing something","vi":"không thích làm điều gì đó"},{"en":"a strong dislike of","vi":"sự ác cảm sâu sắc đối với"},{"en":"take a dislike to","vi":"bắt đầu có cảm giác ghét"}],"wordFamily":[],"synonyms":[],"antonyms":["like"],"tipVi":"Dislike theo sau bởi danh từ hoặc danh động từ: dislike waiting.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_admire', 'en-b1-30', 'admire', '/ədˈmaɪr/', 'B1', 'ngưỡng mộ; khâm phục; chiêm ngưỡng; ngắm nhìn', 'v.', 'admiration (n.), admirable (adj.), admirably (adv.), admirer (n.)', 'Đồng nghĩa: respect, appreciate · Trái nghĩa: despise', 'Cấu trúc admire sb for sth dùng để diễn tả việc khâm phục ai vì một điều gì đó.', 'I admire my sister for staying calm under pressure.', NULL, 'Tôi ngưỡng mộ chị tôi vì luôn giữ được bình tĩnh trước áp lực.', '{"wordId":"admire","ukIpa":"/ədˈmaɪə/","usIpa":"/ədˈmaɪr/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"To respect someone for their qualities or achievements","vi":"ngưỡng mộ; khâm phục"},{"pos":"v.","en":"To look at something with pleasure because it is attractive","vi":"chiêm ngưỡng; ngắm nhìn"}],"examples":[{"en":"I admire my sister for staying calm under pressure.","vi":"Tôi ngưỡng mộ chị tôi vì luôn giữ được bình tĩnh trước áp lực.","audioKind":"ex"},{"en":"People often admire successful athletes for their determination, but consistent training is equally important.","vi":"Mọi người thường khâm phục các vận động viên thành công vì sự kiên trì của họ, nhưng việc tập luyện đều đặn cũng quan trọng không kém.","audioKind":"ex2"}],"collocations":[{"en":"admire someone for something","vi":"ngưỡng mộ ai vì điều gì"},{"en":"greatly admire","vi":"vô cùng ngưỡng mộ"},{"en":"admire the view","vi":"ngắm cảnh"}],"wordFamily":["admiration (n.)","admirable (adj.)","admirably (adv.)","admirer (n.)"],"synonyms":["respect","appreciate"],"antonyms":["despise"],"tipVi":"Cấu trúc admire sb for sth dùng để diễn tả việc khâm phục ai vì một điều gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jealous', 'en-b1-30', 'jealous', '/ˈdʒeləs/', 'B1', 'ghen tị; đố kỵ; ghen tuông', 'adj.', 'jealousy (n.), jealously (adv.)', 'Đồng nghĩa: envious', 'Thường dùng be jealous of; từ này vừa có nghĩa ghen tị, vừa có nghĩa ghen tuông trong tình cảm.', 'I felt jealous when my cousin got a bicycle.', NULL, 'Tôi cảm thấy ghen tị khi anh họ tôi có được chiếc xe đạp.', '{"wordId":"jealous","ukIpa":"/ˈdʒeləs/","usIpa":"/ˈdʒeləs/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"unhappy because someone has something you want","vi":"ghen tị; đố kỵ"},{"pos":"adj.","en":"upset because someone you love shows interest in another person","vi":"ghen tuông"}],"examples":[{"en":"I felt jealous when my cousin got a bicycle.","vi":"Tôi cảm thấy ghen tị khi anh họ tôi có được chiếc xe đạp.","audioKind":"ex"},{"en":"Social media can make users jealous of others whose lives appear more successful or exciting.","vi":"Mạng xã hội có thể khiến người dùng ghen tị với những người có cuộc sống trông có vẻ thành công hoặc thú vị hơn.","audioKind":"ex2"}],"collocations":[{"en":"jealous of someone","vi":"ghen tị với ai đó"},{"en":"feel jealous","vi":"cảm thấy ghen tị"},{"en":"a jealous partner","vi":"một người bạn đời hay ghen"}],"wordFamily":["jealousy (n.)","jealously (adv.)"],"synonyms":["envious"],"antonyms":[],"tipVi":"Thường dùng be jealous of; từ này vừa có nghĩa ghen tị, vừa có nghĩa ghen tuông trong tình cảm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_easy-going', 'en-b1-30', 'easy-going', '/ˌiːzi ˈɡoʊɪŋ/', 'B1', 'dễ tính; thoải mái; hòa đồng', 'adj.', NULL, 'Đồng nghĩa: relaxed, laid-back · Trái nghĩa: uptight', 'Mô tả tính cách dễ chịu, không dễ cáu giận, không mang nghĩa lười biếng.', 'Our easy-going neighbour never complains when our dog barks.', NULL, 'Người hàng xóm dễ tính của chúng tôi không bao giờ phàn nàn khi chó nhà mình sủa.', '{"wordId":"easy-going","ukIpa":"/ˌiːzi ˈɡəʊɪŋ/","usIpa":"/ˌiːzi ˈɡoʊɪŋ/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"relaxed and not easily upset or worried","vi":"dễ tính; thoải mái; hòa đồng"}],"examples":[{"en":"Our easy-going neighbour never complains when our dog barks.","vi":"Người hàng xóm dễ tính của chúng tôi không bao giờ phàn nàn khi chó nhà mình sủa.","audioKind":"ex"},{"en":"Although an easy-going management style can reduce workplace stress, clear expectations remain essential for maintaining productivity.","vi":"Mặc dù phong cách quản lý thoải mái có thể làm giảm áp lực nơi công sở, nhưng những kỳ vọng rõ ràng vẫn rất cần thiết để duy trì năng suất làm việc.","audioKind":"ex2"}],"collocations":[{"en":"an easy-going personality","vi":"tính cách dễ tính"},{"en":"an easy-going attitude","vi":"thái độ thoải mái"},{"en":"an easy-going manner","vi":"cách ứng xử ôn hòa"}],"wordFamily":[],"synonyms":["relaxed","laid-back"],"antonyms":["uptight"],"tipVi":"Mô tả tính cách dễ chịu, không dễ cáu giận, không mang nghĩa lười biếng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fond', 'en-b1-30', 'fond', '/fɑːnd/', 'B1', 'thích; yêu mến; âu yếm; trìu mến', 'adj.', 'fondness (n.), fondly (adv.)', 'Đồng nghĩa: affectionate', 'be fond of sau cộng với danh từ hoặc động từ thêm -ing, không cộng với to do.', 'My grandmother is fond of walking by the river.', NULL, 'Bà tôi rất thích đi dạo ven sông.', '{"wordId":"fond","ukIpa":"/fɒnd/","usIpa":"/fɑːnd/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"having a liking or affection for someone or something","vi":"thích; yêu mến"},{"pos":"adj.","en":"showing or expressing warmth and affection","vi":"âu yếm; trìu mến"}],"examples":[{"en":"My grandmother is fond of walking by the river.","vi":"Bà tôi rất thích đi dạo ven sông.","audioKind":"ex"},{"en":"Many adults retain fond memories of teachers who encouraged their curiosity and supported their ambitions.","vi":"Nhiều người lớn vẫn lưu giữ những kỷ niệm ấm áp về những giáo viên đã khơi gợi sự tò mò và hỗ trợ hoài bão của họ.","audioKind":"ex2"}],"collocations":[{"en":"be fond of","vi":"thích"},{"en":"fond memories","vi":"kỷ niệm ấm áp"},{"en":"a fond farewell","vi":"lời chia tay lưu luyến"}],"wordFamily":["fondness (n.)","fondly (adv.)"],"synonyms":["affectionate"],"antonyms":[],"tipVi":"be fond of sau cộng với danh từ hoặc động từ thêm -ing, không cộng với to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_horror', 'en-b1-30', 'horror', '/ˈhɔːrər/', 'B1', 'sự kinh hãi; sự ghê sợ; nỗi sợ hãi; truyện kinh dị; phim kinh dị', 'n.', 'horrify (v.), horrified (adj.), horrifying (adj.), horrific (adj.)', 'Đồng nghĩa: terror, dread', 'Nghĩa cảm xúc thường không đếm được; cụm in horror biểu thị trạng thái kinh hãi.', 'She watched in horror as her laptop fell downstairs.', NULL, 'Cô ấy kinh hãi nhìn chiếc máy tính xách tay của mình rơi xuống cầu thang.', '{"wordId":"horror","ukIpa":"/ˈhɒrə/","usIpa":"/ˈhɔːrər/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"a strong feeling of fear, shock, or disgust","vi":"sự kinh hãi; sự ghê sợ; nỗi sợ hãi"},{"pos":"n.","en":"a type of fiction intended to frighten its audience","vi":"truyện kinh dị; phim kinh dị"}],"examples":[{"en":"She watched in horror as her laptop fell downstairs.","vi":"Cô ấy kinh hãi nhìn chiếc máy tính xách tay của mình rơi xuống cầu thang.","audioKind":"ex"},{"en":"Horror films often use music and lighting to create tension rather than relying entirely on frightening images.","vi":"Phim kinh dị thường sử dụng âm nhạc và ánh sáng để tạo sự căng thẳng thay vì hoàn toàn dựa vào những hình ảnh đáng sợ.","audioKind":"ex2"}],"collocations":[{"en":"in horror","vi":"trong sự kinh hãi"},{"en":"a horror film","vi":"phim kinh dị"},{"en":"a sense of horror","vi":"cảm giác sợ hãi"}],"wordFamily":["horrify (v.)","horrified (adj.)","horrifying (adj.)","horrific (adj.)"],"synonyms":["terror","dread"],"antonyms":[],"tipVi":"Nghĩa cảm xúc thường không đếm được; cụm in horror biểu thị trạng thái kinh hãi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_30_1', 'en-b1-30', 'Cách dùng “idiot” (n.) — tên ngốc; kẻ đần độn', 'feel like an idiot  ·  a complete idiot', 'Từ này mang tính xúc phạm, không phải là thuật ngữ y tế dùng để mô tả tình trạng khuyết tật trí tuệ.', 'Họ từ (Word Family): idiotic (adj.), idiotically (adv.), idiocy (n.) | Đồng nghĩa: fool', '[{"hanzi":"I felt like an idiot after losing my keys again.","pinyin":"","meaning":"Tôi cảm thấy mình thật ngốc nghếch sau khi lại làm mất chìa khóa."},{"hanzi":"Calling a classmate an idiot can damage their confidence and undermine efforts to create a supportive learning environment.","pinyin":"","meaning":"Gọi một bạn cùng lớp là đồ ngốc có thể làm tổn hại lòng tự tin của họ và làm xói mòn nỗ lực xây dựng một môi trường học tập mang tính hỗ trợ."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_30_2', 'en-b1-30', 'Cách dùng “satisfied” (adj.) — hài lòng; mãn nguyện', 'satisfied with  ·  fully satisfied  ·  satisfied that', 'Dùng satisfied khi chỉ người cảm thấy hài lòng; dùng satisfying để chỉ sự việc mang lại sự hài lòng.', 'Họ từ (Word Family): satisfy (v.), satisfaction (n.), satisfying (adj.), satisfactory (adj.) | Đồng nghĩa: pleased, content · Trái nghĩa: dissatisfied, disappointed', '[{"hanzi":"I''m satisfied with these shoes; they fit perfectly.","pinyin":"","meaning":"Tôi rất hài lòng với đôi giày này; chúng vừa vặn một cách hoàn hảo."},{"hanzi":"Employees who feel satisfied with their working conditions are more likely to remain with the same organisation.","pinyin":"","meaning":"Những nhân viên cảm thấy hài lòng với điều kiện làm việc của họ sẽ có nhiều khả năng gắn bó lâu dài với cùng một tổ chức hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_30_3', 'en-b1-30', 'Cách dùng “congratulation” (n.) — lời chúc mừng; sự chúc mừng', 'congratulations on  ·  a letter of congratulation  ·  warm congratulations', 'Lời chúc mừng thường ở dạng số nhiều congratulations, theo sau là on và danh động từ hoặc sự việc.', 'Họ từ (Word Family): congratulate (v.), congratulatory (adj.)', '[{"hanzi":"We sent our congratulations when she passed her driving test.","pinyin":"","meaning":"Chúng tôi đã gửi lời chúc mừng khi cô ấy vượt qua kỳ thi lái xe."},{"hanzi":"Offering congratulations to students who achieve personal goals can strengthen their confidence and encourage further learning.","pinyin":"","meaning":"Việc gửi lời chúc mừng tới những học sinh đạt được mục tiêu cá nhân có thể củng cố sự tự tin và khuyến khích các em học tập tiến xa hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_30_4', 'en-b1-30', 'Cách dùng “emotional” (adj.) — thuộc về cảm xúc; thuộc về tinh thần', 'emotional support  ·  emotional well-being  ·  emotional development', 'emotional không nhất thiết chỉ sự đau buồn, mà còn có thể chỉ những cảm xúc mạnh mẽ như niềm vui.', 'Họ từ (Word Family): emotion (n.), emotionally (adv.), unemotional (adj.) | Trái nghĩa: unemotional', '[{"hanzi":"Her friends gave her emotional support during the move.","pinyin":"","meaning":"Bạn bè của cô ấy đã hỗ trợ tinh thần cho cô ấy trong suốt thời gian chuyển nhà."},{"hanzi":"Schools should support children''s emotional development alongside academic progress to promote their long-term well-being.","pinyin":"","meaning":"Nhà trường nên hỗ trợ sự phát triển cảm xúc của trẻ song song với tiến độ học tập nhằm thúc đẩy sự phát triển toàn diện lâu dài."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_30_1', 'en-b1-30', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_30_1_1', 'ten_b1_30_1', 'stressful', 'Moving house was stressful, but our friends helped.', 'Moving house was stressful, but our friends helped.', '/ˈstresfəl/', 'Việc chuyển nhà rất căng thẳng, nhưng bạn bè đã giúp đỡ chúng tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
