INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_30_1_4', 'ten_b1_30_1', 'stressed', 'I felt stressed before my first driving lesson.', 'I felt stressed before my first driving lesson.', '/strest/', 'Tôi cảm thấy rất căng thẳng trước buổi học lái xe đầu tiên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_30_1_5', 'ten_b1_30_1', 'enjoyable', 'The cooking class was enjoyable, especially making fresh pasta.', 'The cooking class was enjoyable, especially making fresh pasta.', '/ɪnˈdʒɔɪəbl/', 'Lớp học nấu ăn rất thú vị, đặc biệt là công đoạn làm mì tươi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_30_1_6', 'ten_b1_30_1', 'congratulation', 'We sent our congratulations when she passed her driving test.', 'We sent our congratulations when she passed her driving test.', '/kənˌɡrætʃəˈleɪʃən/', 'Chúng tôi đã gửi lời chúc mừng khi cô ấy vượt qua kỳ thi lái xe.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_30_1_7', 'ten_b1_30_1', 'frighten', 'Sudden loud noises can frighten our new puppy.', 'Sudden loud noises can frighten our new puppy.', '/ˈfraɪtən/', 'Tiếng động lớn bất ngờ có thể làm chú cún con mới của chúng ta sợ hãi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_30_1_8', 'ten_b1_30_1', 'brave', 'You were brave to speak in front of everyone.', 'You were brave to speak in front of everyone.', '/breɪv/', 'Bạn thật dũng cảm khi dám phát biểu trước tất cả mọi người.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_30_1_1', 'en-b1-30', 'ten_b1_30_1', 'listening', 'listening', 'Moving house was stressful, but our friends helped.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Việc chuyển nhà rất căng thẳng, nhưng bạn bè đã giúp đỡ chúng tôi.","Tôi phải rất can đảm mới dám thừa nhận lỗi lầm của mình trước lớp.","Tiếng động lớn bất ngờ có thể làm chú cún con mới của chúng ta sợ hãi.","Tôi cảm thấy rất căng thẳng trước buổi học lái xe đầu tiên."]'::jsonb, 0, 'Moving house was stressful, but our friends helped. → Việc chuyển nhà rất căng thẳng, nhưng bạn bè đã giúp đỡ chúng tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_30_1_2', 'en-b1-30', 'ten_b1_30_1', 'listening', 'listening', 'A short walk usually puts me in a better mood.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn bè của cô ấy đã hỗ trợ tinh thần cho cô ấy trong suốt thời gian chuyển nhà.","Tiếng động lớn bất ngờ có thể làm chú cún con mới của chúng ta sợ hãi.","Việc chuyển nhà rất căng thẳng, nhưng bạn bè đã giúp đỡ chúng tôi.","Đi dạo một lát thường giúp tâm trạng tôi thoải mái hơn."]'::jsonb, 3, 'A short walk usually puts me in a better mood. → Đi dạo một lát thường giúp tâm trạng tôi thoải mái hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_30_1_3', 'en-b1-30', 'ten_b1_30_1', 'listening', 'listening', 'Those dripping taps annoy me when I try to sleep.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn thật dũng cảm khi dám phát biểu trước tất cả mọi người.","Tôi không thích đứng chờ bên ngoài trời mưa.","Bạn bè của cô ấy đã hỗ trợ tinh thần cho cô ấy trong suốt thời gian chuyển nhà.","Mấy cái vòi nước nhỏ giọt đó làm tôi phát bực khi định đi ngủ."]'::jsonb, 3, 'Those dripping taps annoy me when I try to sleep. → Mấy cái vòi nước nhỏ giọt đó làm tôi phát bực khi định đi ngủ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_30_2', 'en-b1-30', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_30_2_1', 'ten_b1_30_2', 'stressful', 'Long commutes can make working life more stressful and leave less time for family activities.', 'Long commutes can make working life more stressful and leave less time for family activities.', '/ˈstresfəl/', 'Việc đi lại quãng đường dài mỗi ngày có thể làm cho đời sống công việc thêm phần căng thẳng và chừa lại ít thời gian hơn cho các hoạt động gia đình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_30_2_2', 'ten_b1_30_2', 'mood', 'Access to green spaces can improve residents'' mood and encourage more positive interactions within urban communities.', 'Access to green spaces can improve residents'' mood and encourage more positive interactions within urban communities.', '/muːd/', 'Việc tiếp cận các không gian xanh có thể cải thiện tâm trạng của cư dân và thúc đẩy sự tương tác tích cực hơn trong cộng đồng đô thị.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_30_2_3', 'ten_b1_30_2', 'annoy', 'Frequent online advertisements can annoy users and discourage them from returning to otherwise useful educational websites.', 'Frequent online advertisements can annoy users and discourage them from returning to otherwise useful educational websites.', '/əˈnɔɪ/', 'Các quảng cáo trực tuyến xuất hiện liên tục có thể làm người dùng khó chịu và khiến họ không muốn quay lại những trang web giáo dục vốn hữu ích.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_30_2_4', 'ten_b1_30_2', 'stressed', 'Students who feel stressed during examinations may benefit from regular exercise and adequate sleep.', 'Students who feel stressed during examinations may benefit from regular exercise and adequate sleep.', '/strest/', 'Những học sinh cảm thấy áp lực trong các kỳ thi có thể cải thiện tình trạng này nhờ tập thể dục đều đặn và ngủ đủ giấc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_30_2_5', 'ten_b1_30_2', 'enjoyable', 'Making physical activity enjoyable can encourage children to develop healthy habits that continue into adulthood.', 'Making physical activity enjoyable can encourage children to develop healthy habits that continue into adulthood.', '/ɪnˈdʒɔɪəbl/', 'Việc biến các hoạt động thể chất thành niềm vui có thể khuyến khích trẻ nhỏ hình thành thói quen lành mạnh kéo dài đến tận tuổi trưởng thành.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_30_2_6', 'ten_b1_30_2', 'congratulation', 'Offering congratulations to students who achieve personal goals can strengthen their confidence and encourage further learning.', 'Offering congratulations to students who achieve personal goals can strengthen their confidence and encourage further learning.', '/kənˌɡrætʃəˈleɪʃən/', 'Việc gửi lời chúc mừng tới những học sinh đạt được mục tiêu cá nhân có thể củng cố sự tự tin và khuyến khích các em học tập tiến xa hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_30_2_1', 'en-b1-30', 'ten_b1_30_2', 'listening', 'listening', 'Long commutes can make working life more stressful and leave less time for family activities.', NULL, 'Trong câu vừa nghe, từ “stressful” mang nghĩa nào sau đây?', '["căng thẳng; gây áp lực tâm lý","làm mệt mỏi; mệt mỏi","lời trích dẫn; đoạn trích","sự tốt nghiệp; lễ tốt nghiệp"]'::jsonb, 0, '“stressful” (/ˈstresfəl/): căng thẳng; gây áp lực tâm lý. Câu đầy đủ: Long commutes can make working life more stressful and leave less time for family activities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_30_2_2', 'en-b1-30', 'ten_b1_30_2', 'listening', 'listening', 'Access to green spaces can improve residents'' mood and encourage more positive interactions within urban communities.', NULL, 'Trong câu vừa nghe, từ “mood” mang nghĩa nào sau đây?', '["mối quan hệ; sự liên quan","tâm trạng; cảm xúc","tội phạm; tệ nạn tội phạm","vật; đồ vật"]'::jsonb, 1, '“mood” (/muːd/): tâm trạng; cảm xúc. Câu đầy đủ: Access to green spaces can improve residents'' mood and encourage more positive interactions within urban communities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
