INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_30_2', 'en-b1-30', NULL, 'comprehensive_test', 'listening', 'A short walk usually puts me in a better mood.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người hàng xóm dễ tính của chúng tôi không bao giờ phàn nàn khi chó nhà mình sủa.","Đi dạo một lát thường giúp tâm trạng tôi thoải mái hơn.","Tôi cảm thấy mình thật ngốc nghếch sau khi lại làm mất chìa khóa.","Phòng bếp ngập tràn tiếng cười khi chú cún con hắt xì."]'::jsonb, 1, 'A short walk usually puts me in a better mood. → Đi dạo một lát thường giúp tâm trạng tôi thoải mái hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_30_3', 'en-b1-30', NULL, 'comprehensive_test', 'listening', 'annoy', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự liên lạc; sự tiếp xúc","yêu cầu; điều kiện tiên quyết","làm phiền; làm bực mình; chọc tức","sáng tạo; có tính sáng tạo"]'::jsonb, 2, 'annoy (/əˈnɔɪ/) → làm phiền; làm bực mình; chọc tức', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_30_4', 'en-b1-30', NULL, 'comprehensive_test', 'listening', 'I felt stressed before my first driving lesson.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi rất ấn tượng với việc bạn sửa chiếc xe đạp nhanh đến thế.","Tôi không thích đứng chờ bên ngoài trời mưa.","Bà tôi rất thích đi dạo ven sông.","Tôi cảm thấy rất căng thẳng trước buổi học lái xe đầu tiên."]'::jsonb, 3, 'I felt stressed before my first driving lesson. → Tôi cảm thấy rất căng thẳng trước buổi học lái xe đầu tiên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_30_5', 'en-b1-30', NULL, 'comprehensive_test', 'listening', 'enjoyable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["kênh truyền hình; đường truyền, phương tiện","thư tín và bưu kiện vận chuyển bằng đường hàng không; dịch vụ bưu chính hàng không","thú vị; dễ chịu; mang lại niềm vui","thuộc về sơ cứu; cấp cứu"]'::jsonb, 2, 'enjoyable (/ɪnˈdʒɔɪəbl/) → thú vị; dễ chịu; mang lại niềm vui', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_30_6', 'en-b1-30', NULL, 'comprehensive_test', 'listening', 'We sent our congratulations when she passed her driving test.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã gửi lời chúc mừng khi cô ấy vượt qua kỳ thi lái xe.","Phòng bếp ngập tràn tiếng cười khi chú cún con hắt xì.","Tôi cảm thấy rất căng thẳng trước buổi học lái xe đầu tiên.","Tôi ngưỡng mộ chị tôi vì luôn giữ được bình tĩnh trước áp lực."]'::jsonb, 0, 'We sent our congratulations when she passed her driving test. → Chúng tôi đã gửi lời chúc mừng khi cô ấy vượt qua kỳ thi lái xe.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
