INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_30_18', 'en-b1-30', NULL, 'comprehensive_test', 'reading', NULL, 'Long commutes can make working life more stressful and leave less time for family activities.', 'Dựa vào câu trên, từ “stressful” có nghĩa phù hợp nhất là gì?', '["xin lỗi; nhận lỗi","cac-bon; nguyên tố carbon","căng thẳng; gây áp lực tâm lý","công tắc điện"]'::jsonb, 2, 'stressful: căng thẳng; gây áp lực tâm lý. Dịch cả câu: Việc đi lại quãng đường dài mỗi ngày có thể làm cho đời sống công việc thêm phần căng thẳng và chừa lại ít thời gian hơn cho các hoạt động gia đình.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_30_19', 'en-b1-30', NULL, 'comprehensive_test', 'reading', NULL, 'Access to green spaces can improve residents'' mood and encourage more positive interactions within urban communities.', 'Dựa vào câu trên, từ “mood” có nghĩa phù hợp nhất là gì?', '["sự vận chuyển; hệ thống giao thông","làm cho lúng túng; làm ngượng ngùng; gây bối rối","tâm trạng; cảm xúc","micrô; ống nói"]'::jsonb, 2, 'mood: tâm trạng; cảm xúc; bầu không khí; không khí. Dịch cả câu: Việc tiếp cận các không gian xanh có thể cải thiện tâm trạng của cư dân và thúc đẩy sự tương tác tích cực hơn trong cộng đồng đô thị.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_30_20', 'en-b1-30', NULL, 'comprehensive_test', 'reading', NULL, 'Frequent online advertisements can annoy users and discourage them from returning to otherwise useful educational websites.', 'Dựa vào câu trên, từ “annoy” có nghĩa phù hợp nhất là gì?', '["làm phiền; làm bực mình; chọc tức","sự thanh toán; việc trả tiền","thực tập sinh; học viên tập sự","bối rối; hoang mang"]'::jsonb, 0, 'annoy: làm phiền; làm bực mình; chọc tức. Dịch cả câu: Các quảng cáo trực tuyến xuất hiện liên tục có thể làm người dùng khó chịu và khiến họ không muốn quay lại những trang web giáo dục vốn hữu ích.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_30_21', 'en-b1-30', NULL, 'comprehensive_test', 'reading', NULL, 'Students who feel stressed during examinations may benefit from regular exercise and adequate sleep.', 'Dựa vào câu trên, từ “stressed” có nghĩa phù hợp nhất là gì?', '["gian lận; chơi gian","tuân theo; vâng lời; chấp hành","căng thẳng; lo âu; áp lực","chết đuối; nhấn chìm xuống nước"]'::jsonb, 2, 'stressed: căng thẳng; lo âu; áp lực; được nhấn trọng âm; chịu ứng suất; chịu áp lực cơ học. Dịch cả câu: Những học sinh cảm thấy áp lực trong các kỳ thi có thể cải thiện tình trạng này nhờ tập thể dục đều đặn và ngủ đủ giấc.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_30_22', 'en-b1-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dễ tính; thoải mái; hòa đồng”', '["cab","easy-going","sum","involved"]'::jsonb, 1, 'dễ tính; thoải mái; hòa đồng → easy-going (/ˌiːzi ˈɡoʊɪŋ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_30_23', 'en-b1-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thích; yêu mến”', '["track","rush","rough","fond"]'::jsonb, 3, 'thích; yêu mến → fond (/fɑːnd/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_30_24', 'en-b1-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự kinh hãi; sự ghê sợ; nỗi sợ hãi”', '["hunt","easy-going","horror","roast"]'::jsonb, 2, 'sự kinh hãi; sự ghê sợ; nỗi sợ hãi → horror (/ˈhɔːrər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-31', 'en', 'Bài 31: Cảm xúc & Tính cách (4) - CEFR B1', 'CEFR B1', 'B1 · Cảm xúc', '21 từ vựng Tiếng Anh CEFR B1 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3031, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_merry', 'en-b1-31', 'merry', '/ˈmeri/', 'B1', 'vui vẻ; rộn ràng; hân hoan', 'adj.', 'merrily (adv.), merriment (n.)', 'Đồng nghĩa: cheerful, joyful · Trái nghĩa: gloomy, miserable', 'Thường dùng để tả không khí lễ hội; make merry nghĩa là vui chơi yến tiệc.', 'Their merry laughter filled the kitchen as they baked.', NULL, 'Tiếng cười vui vẻ của họ ngập tràn căn bếp khi họ nướng bánh.', '{"wordId":"merry","ukIpa":"/ˈmeri/","usIpa":"/ˈmeri/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Cheerful and full of enjoyment.","vi":"vui vẻ; rộn ràng; hân hoan"}],"examples":[{"en":"Their merry laughter filled the kitchen as they baked.","vi":"Tiếng cười vui vẻ của họ ngập tràn căn bếp khi họ nướng bánh.","audioKind":"ex"},{"en":"Community festivals create a merry atmosphere that encourages residents of different ages to interact and build friendships.","vi":"Các lễ hội cộng đồng tạo ra bầu không khí hân hoan, khuyến khích người dân ở mọi lứa tuổi giao lưu và xây dựng tình bạn.","audioKind":"ex2"}],"collocations":[{"en":"merry laughter","vi":"tiếng cười vui vẻ"},{"en":"a merry crowd","vi":"đám đông vui nhộn"},{"en":"make merry","vi":"vui chơi yến tiệc"}],"wordFamily":["merrily (adv.)","merriment (n.)"],"synonyms":["cheerful","joyful"],"antonyms":["gloomy","miserable"],"tipVi":"Thường dùng để tả không khí lễ hội; make merry nghĩa là vui chơi yến tiệc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_joy', 'en-b1-31', 'joy', '/dʒɔɪ/', 'B1', 'niềm vui; sự hân hoan; điều hạnh phúc', 'n.', 'joyful (adj.), joyfully (adv.), joyous (adj.)', 'Đồng nghĩa: delight, happiness · Trái nghĩa: sorrow, misery', 'Biểu thị niềm vui thường là danh từ không đếm được; biểu thị niềm vui thích/điều vui sướng là danh từ đếm được, chẳng hạn như a joy.', 'The children jumped for joy when the snow began.', NULL, 'Bọn trẻ nhảy cẫng lên vì vui sướng khi tuyết bắt đầu rơi.', '{"wordId":"joy","ukIpa":"/dʒɔɪ/","usIpa":"/dʒɔɪ/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"A feeling of great happiness","vi":"niềm vui; sự hân hoan"},{"pos":"n.","en":"A person or thing that brings great happiness","vi":"niềm vui; điều hạnh phúc"}],"examples":[{"en":"The children jumped for joy when the snow began.","vi":"Bọn trẻ nhảy cẫng lên vì vui sướng khi tuyết bắt đầu rơi.","audioKind":"ex"},{"en":"Community gardens can bring joy to residents while strengthening social connections and encouraging healthier lifestyles.","vi":"Các khu vườn cộng đồng có thể mang lại niềm vui cho cư dân, đồng thời thắt chặt tình òa xã hội và khuyến khích lối sống lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"bring joy","vi":"mang lại niềm vui"},{"en":"jump for joy","vi":"nhảy cẫng lên vì vui sướng"},{"en":"tears of joy","vi":"những giọt nước mắt hạnh phúc"},{"en":"the joys of parenthood","vi":"niềm vui khi làm cha mẹ"}],"wordFamily":["joyful (adj.)","joyfully (adv.)","joyous (adj.)"],"synonyms":["delight","happiness"],"antonyms":["sorrow","misery"],"tipVi":"Biểu thị niềm vui thường là danh từ không đếm được; biểu thị niềm vui thích/điều vui sướng là danh từ đếm được, chẳng hạn như a joy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disappointment', 'en-b1-31', 'disappointment', '/ˌdɪsəˈpɔɪntmənt/', 'B1', 'sự thất vọng; niềm thất vọng; người hoặc vật gây thất vọng', 'n.', 'disappoint (v.), disappointed (adj.), disappointing (adj.)', 'Đồng nghĩa: dismay, letdown · Trái nghĩa: satisfaction', 'Chỉ cảm xúc thường không đếm được; chỉ người/vật gây thất vọng có thể dùng a disappointment.', 'Her face showed disappointment when the picnic was cancelled.', NULL, 'Cô ấy lộ rõ vẻ thất vọng khi chuyến dã ngoại bị hủy.', '{"wordId":"disappointment","ukIpa":"/ˌdɪsəˈpɔɪntmənt/","usIpa":"/ˌdɪsəˈpɔɪntmənt/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"sadness because something was not as good as expected","vi":"sự thất vọng; niềm thất vọng"},{"pos":"n.","en":"someone or something that fails to meet your hopes","vi":"người hoặc vật gây thất vọng"}],"examples":[{"en":"Her face showed disappointment when the picnic was cancelled.","vi":"Cô ấy lộ rõ vẻ thất vọng khi chuyến dã ngoại bị hủy.","audioKind":"ex"},{"en":"Teaching young people to cope with disappointment can help them respond more positively to academic setbacks.","vi":"Dạy người trẻ cách đối phó với sự thất vọng có thể giúp họ phản ứng tích cực hơn trước những cú vấp ngã trong học tập.","audioKind":"ex2"}],"collocations":[{"en":"to my disappointment","vi":"làm tôi thất vọng"},{"en":"a bitter disappointment","vi":"một nỗi thất vọng cay đắng"},{"en":"cope with disappointment","vi":"đối phó với sự thất vọng"}],"wordFamily":["disappoint (v.)","disappointed (adj.)","disappointing (adj.)"],"synonyms":["dismay","letdown"],"antonyms":["satisfaction"],"tipVi":"Chỉ cảm xúc thường không đếm được; chỉ người/vật gây thất vọng có thể dùng a disappointment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_embarrassing', 'en-b1-31', 'embarrassing', '/ɪmˈbærəsɪŋ/', 'B1', 'gây bối rối; xấu hổ; khó xử', 'adj.', 'embarrass (v.), embarrassed (adj.), embarrassment (n.), embarrassingly (adv.)', 'Đồng nghĩa: awkward', 'Sự vật mang lại sự ngượng ngùng dùng embarrassing; con người cảm thấy ngượng ngùng dùng embarrassed.', 'It was embarrassing when my phone rang during the ceremony.', NULL, 'Thật là xấu hổ khi điện thoại của tôi reo lên trong buổi lễ.', '{"wordId":"embarrassing","ukIpa":"/ɪmˈbærəsɪŋ/","usIpa":"/ɪmˈbærəsɪŋ/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Making someone feel awkward, ashamed, or uncomfortable","vi":"gây bối rối; xấu hổ; khó xử"}],"examples":[{"en":"It was embarrassing when my phone rang during the ceremony.","vi":"Thật là xấu hổ khi điện thoại của tôi reo lên trong buổi lễ.","audioKind":"ex"},{"en":"Students may avoid asking questions if they believe that making mistakes in front of classmates is embarrassing.","vi":"Học sinh có thể tránh đặt câu hỏi nếu các em cho rằng việc mắc lỗi trước mặt bạn bè là điều xấu hổ.","audioKind":"ex2"}],"collocations":[{"en":"an embarrassing mistake","vi":"một lỗi lầm tai hại"},{"en":"an embarrassing situation","vi":"một hoàn cảnh khó xử"},{"en":"deeply embarrassing","vi":"vô cùng xấu hổ"}],"wordFamily":["embarrass (v.)","embarrassed (adj.)","embarrassment (n.)","embarrassingly (adv.)"],"synonyms":["awkward"],"antonyms":[],"tipVi":"Sự vật mang lại sự ngượng ngùng dùng embarrassing; con người cảm thấy ngượng ngùng dùng embarrassed.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_miserable', 'en-b1-31', 'miserable', '/ˈmɪzərəbl/', 'B1', 'khốn khổ; đau khổ; buồn rầu; tồi tệ; thảm hại (điều kiện sống, thời tiết)', 'adj.', 'misery (n.), miserably (adv.)', 'Đồng nghĩa: unhappy, wretched · Trái nghĩa: happy, cheerful', 'Có thể dùng để miêu tả tâm trạng con người hoặc thời tiết, điều kiện sống.', 'I felt miserable when rain ruined our picnic plans.', NULL, 'Tôi cảm thấy rất buồn khi cơn mưa làm hỏng kế hoạch đi dã ngoại của chúng tôi.', '{"wordId":"miserable","ukIpa":"/ˈmɪzərəbl/","usIpa":"/ˈmɪzərəbl/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Very unhappy or uncomfortable","vi":"khốn khổ; đau khổ; buồn rầu"},{"pos":"adj.","en":"Extremely unpleasant or of very poor quality","vi":"tồi tệ; thảm hại (điều kiện sống, thời tiết)"}],"examples":[{"en":"I felt miserable when rain ruined our picnic plans.","vi":"Tôi cảm thấy rất buồn khi cơn mưa làm hỏng kế hoạch đi dã ngoại của chúng tôi.","audioKind":"ex"},{"en":"Overcrowded housing can create miserable living conditions and negatively affect residents'' physical and mental health.","vi":"Nhà ở chật chội có thể tạo ra điều kiện sống tồi tệ và tác động tiêu cực đến sức khỏe thể chất lẫn tinh thần của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"feel miserable","vi":"cảm thấy tồi tệ/buồn bã"},{"en":"miserable weather","vi":"thời tiết xấu"},{"en":"miserable conditions","vi":"điều kiện sống tồi tệ"}],"wordFamily":["misery (n.)","miserably (adv.)"],"synonyms":["unhappy","wretched"],"antonyms":["happy","cheerful"],"tipVi":"Có thể dùng để miêu tả tâm trạng con người hoặc thời tiết, điều kiện sống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shame', 'en-b1-31', 'shame', '/ʃeɪm/', 'B1', 'sự xấu hổ; nỗi thẹn thùng; điều đáng tiếc; làm cho xấu hổ; làm cho bẽ mặt', 'n.', 'ashamed (adj.), shameful (adj.), shameless (adj.)', NULL, 'Nghĩa xấu hổ thường là danh từ không đếm được; cấu trúc It''s a shame diễn tả sự việc đáng tiếc.', 'He felt shame after lying to his closest friend.', NULL, 'Anh ấy cảm thấy vô cùng xấu hổ sau khi nói dối người bạn thân nhất của mình.', '{"wordId":"shame","ukIpa":"/ʃeɪm/","usIpa":"/ʃeɪm/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"A painful feeling caused by doing something wrong or embarrassing.","vi":"sự xấu hổ; nỗi thẹn thùng"},{"pos":"n.","en":"Something that causes disappointment or regret.","vi":"điều đáng tiếc"},{"pos":"v.","en":"To make someone feel guilty or embarrassed about their behaviour.","vi":"làm cho xấu hổ; làm cho bẽ mặt"}],"examples":[{"en":"He felt shame after lying to his closest friend.","vi":"Anh ấy cảm thấy vô cùng xấu hổ sau khi nói dối người bạn thân nhất của mình.","audioKind":"ex"},{"en":"Schools should address bullying without creating a culture of shame that prevents pupils from seeking help.","vi":"Nhà trường nên giải quyết tình trạng bắt nạt mà không tạo ra một bầu không khí đầy sự mặc cảm, khiến học sinh không dám tìm kiếm sự giúp đỡ.","audioKind":"ex2"}],"collocations":[{"en":"feel shame","vi":"cảm thấy xấu hổ"},{"en":"a sense of shame","vi":"sự hổ thẹn"},{"en":"a real shame","vi":"thật là đáng tiếc"},{"en":"shame someone into doing something","vi":"dùng áp lực tâm lý khiến ai đó phải làm gì"}],"wordFamily":["ashamed (adj.)","shameful (adj.)","shameless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa xấu hổ thường là danh từ không đếm được; cấu trúc It''s a shame diễn tả sự việc đáng tiếc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_willing', 'en-b1-31', 'willing', '/ˈwɪlɪŋ/', 'B1', 'sẵn lòng; tự nguyện; vui lòng; hăng hái; nhiệt tình', 'adj.', 'willingness (n.), willingly (adv.), unwilling (adj.)', 'Đồng nghĩa: ready, prepared · Trái nghĩa: unwilling, reluctant', 'Thường dùng trong cấu trúc be willing to do, diễn tả sự sẵn lòng chứ không mang nghĩa thì tương lai (sẽ).', 'I''m willing to help you move this weekend.', NULL, 'Tôi sẵn lòng giúp bạn chuyển nhà vào cuối tuần này.', '{"wordId":"willing","ukIpa":"/ˈwɪlɪŋ/","usIpa":"/ˈwɪlɪŋ/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"ready and happy to do something","vi":"sẵn lòng; tự nguyện; vui lòng"},{"pos":"adj.","en":"eager to help or work without needing persuasion","vi":"hăng hái; nhiệt tình"}],"examples":[{"en":"I''m willing to help you move this weekend.","vi":"Tôi sẵn lòng giúp bạn chuyển nhà vào cuối tuần này.","audioKind":"ex"},{"en":"Consumers may be more willing to buy sustainable products if prices remain affordable and information is clear.","vi":"Người tiêu dùng có thể sẵn sàng mua các sản phẩm bền vững hơn nếu giá cả phải chăng và thông tin được minh bạch.","audioKind":"ex2"}],"collocations":[{"en":"be willing to do something","vi":"sẵn lòng làm gì đó"},{"en":"a willing volunteer","vi":"một tình nguyện viên nhiệt tình"},{"en":"a willing helper","vi":"một người sẵn lòng giúp đỡ"}],"wordFamily":["willingness (n.)","willingly (adv.)","unwilling (adj.)"],"synonyms":["ready","prepared"],"antonyms":["unwilling","reluctant"],"tipVi":"Thường dùng trong cấu trúc be willing to do, diễn tả sự sẵn lòng chứ không mang nghĩa thì tương lai (sẽ).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_congratulate', 'en-b1-31', 'congratulate', '/kənˈɡrætʃəleɪt/', 'B1', 'chúc mừng; tán thành', 'v.', 'congratulation (n.), congratulatory (adj.)', NULL, 'Đi với cấu trúc congratulate sb on sth, giới từ đi kèm là on chứ không phải for.', 'We called to congratulate Lina on her new job.', NULL, 'Chúng tôi đã gọi điện để chúc mừng Lina về công việc mới của cô ấy.', '{"wordId":"congratulate","ukIpa":"/kənˈɡrætʃəleɪt/","usIpa":"/kənˈɡrætʃəleɪt/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"Tell someone you are pleased about their success or good fortune.","vi":"chúc mừng; tán thành"}],"examples":[{"en":"We called to congratulate Lina on her new job.","vi":"Chúng tôi đã gọi điện để chúc mừng Lina về công việc mới của cô ấy.","audioKind":"ex"},{"en":"Schools should congratulate students on personal improvement rather than focus exclusively on high examination scores.","vi":"Nhà trường nên chúc mừng học sinh vì sự tiến bộ của bản thân thay vì chỉ tập trung hoàn toàn vào điểm số thi cử cao.","audioKind":"ex2"}],"collocations":[{"en":"congratulate someone on something","vi":"chúc mừng ai đó về điều gì"},{"en":"congratulate someone warmly","vi":"chúc mừng nhiệt liệt ai đó"}],"wordFamily":["congratulation (n.)","congratulatory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Đi với cấu trúc congratulate sb on sth, giới từ đi kèm là on chứ không phải for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cheer', 'en-b1-31', 'cheer', '/tʃɪr/', 'B1', 'hò reo; cổ vũ; tiếng hò reo; tiếng cổ vũ; làm cho vui lên; làm phấn chấn', 'v.', 'cheerful (adj.), cheerfully (adv.), cheerfulness (n.), cheerless (adj.)', 'Đồng nghĩa: applaud, encourage · Trái nghĩa: boo', '"cheer on" dùng để cổ vũ, tiếp lửa; "cheer up" dùng để làm ai đó phấn chấn hoặc vui lên.', 'We cheered as our neighbour crossed the finish line.', NULL, 'Chúng tôi đã hò reo khi người hàng xóm về đích.', '{"wordId":"cheer","ukIpa":"/tʃɪə/","usIpa":"/tʃɪr/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"shout happily to show approval or encouragement","vi":"hò reo; cổ vũ"},{"pos":"n.","en":"a loud shout expressing happiness, approval, or encouragement","vi":"tiếng hò reo; tiếng cổ vũ"},{"pos":"v.","en":"make someone feel happier or more hopeful","vi":"làm cho vui lên; làm phấn chấn"}],"examples":[{"en":"We cheered as our neighbour crossed the finish line.","vi":"Chúng tôi đã hò reo khi người hàng xóm về đích.","audioKind":"ex"},{"en":"When spectators cheer for every participant, community sporting events can foster a stronger sense of belonging.","vi":"Khi khán giả cổ vũ cho mọi người tham gia, các sự kiện thể thao cộng đồng có thể nuôi dưỡng tinh thần gắn kết mạnh mẽ hơn.","audioKind":"ex2"}],"collocations":[{"en":"cheer someone on","vi":"cổ vũ ai đó"},{"en":"cheer someone up","vi":"làm ai đó vui lên"},{"en":"a loud cheer","vi":"tiếng hò reo lớn"},{"en":"cheer for a team","vi":"cổ vũ cho một đội"}],"wordFamily":["cheerful (adj.)","cheerfully (adv.)","cheerfulness (n.)","cheerless (adj.)"],"synonyms":["applaud","encourage"],"antonyms":["boo"],"tipVi":"\"cheer on\" dùng để cổ vũ, tiếp lửa; \"cheer up\" dùng để làm ai đó phấn chấn hoặc vui lên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cheerful', 'en-b1-31', 'cheerful', '/ˈtʃɪrfəl/', 'B1', 'vui vẻ; phấn khởi; lạc quan; tươi tắn; dễ chịu; rực rỡ', 'adj.', 'cheer (v.), cheerfully (adv.), cheerfulness (n.)', 'Đồng nghĩa: happy, upbeat · Trái nghĩa: gloomy, miserable', 'Có thể dùng để miêu tả tâm trạng con người hoặc không gian, cảnh vật tươi tắn.', 'Our cheerful neighbour waved as we left the house.', NULL, 'Người hàng xóm vui tính của chúng tôi vẫy tay chào khi chúng tôi rời khỏi nhà.', '{"wordId":"cheerful","ukIpa":"/ˈtʃɪəfəl/","usIpa":"/ˈtʃɪrfəl/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling or showing happiness and a positive attitude.","vi":"vui vẻ; phấn khởi; lạc quan"},{"pos":"adj.","en":"Making a place or experience feel bright and pleasant.","vi":"tươi tắn; dễ chịu; rực rỡ"}],"examples":[{"en":"Our cheerful neighbour waved as we left the house.","vi":"Người hàng xóm vui tính của chúng tôi vẫy tay chào khi chúng tôi rời khỏi nhà.","audioKind":"ex"},{"en":"A cheerful classroom atmosphere can encourage younger learners to participate more actively in group discussions.","vi":"Bầu không khí lớp học vui tươi có thể khuyến khích học sinh nhỏ tuổi tham gia tích cực hơn vào các hoạt động thảo luận nhóm.","audioKind":"ex2"}],"collocations":[{"en":"cheerful smile","vi":"nụ cười vui tươi"},{"en":"cheerful mood","vi":"tâm trạng vui vẻ"},{"en":"cheerful atmosphere","vi":"bầu không khí vui tươi"}],"wordFamily":["cheer (v.)","cheerfully (adv.)","cheerfulness (n.)"],"synonyms":["happy","upbeat"],"antonyms":["gloomy","miserable"],"tipVi":"Có thể dùng để miêu tả tâm trạng con người hoặc không gian, cảnh vật tươi tắn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_terrified', 'en-b1-31', 'terrified', '/ˈterəfaɪd/', 'B1', 'cực kỳ sợ hãi; khiếp sợ', 'adj.', 'terrify (v.), terrifying (adj.), terror (n.)', 'Đồng nghĩa: frightened, petrified · Trái nghĩa: unafraid', 'Người cảm thấy sợ hãi dùng terrified; sự vật gây sợ hãi dùng terrifying.', 'I was terrified when thunder shook the windows last night.', NULL, 'Tôi đã vô cùng hoảng sợ khi tiếng sấm làm rung chuyển những khung cửa sổ vào đêm qua.', '{"wordId":"terrified","ukIpa":"/ˈterɪfaɪd/","usIpa":"/ˈterəfaɪd/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling extremely afraid.","vi":"cực kỳ sợ hãi; khiếp sợ"}],"examples":[{"en":"I was terrified when thunder shook the windows last night.","vi":"Tôi đã vô cùng hoảng sợ khi tiếng sấm làm rung chuyển những khung cửa sổ vào đêm qua.","audioKind":"ex"},{"en":"Students who are terrified of public speaking may benefit from practising presentations in small, supportive groups.","vi":"Những học sinh sợ phát biểu trước đám đông có thể hưởng lợi từ việc tập thuyết trình trong các nhóm nhỏ và có sự hỗ trợ.","audioKind":"ex2"}],"collocations":[{"en":"terrified of","vi":"cực kỳ sợ (cái gì)"},{"en":"terrified at the thought of","vi":"khiếp sợ khi nghĩ đến"},{"en":"absolutely terrified","vi":"hoàn toàn khiếp sợ"}],"wordFamily":["terrify (v.)","terrifying (adj.)","terror (n.)"],"synonyms":["frightened","petrified"],"antonyms":["unafraid"],"tipVi":"Người cảm thấy sợ hãi dùng terrified; sự vật gây sợ hãi dùng terrifying.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_passion', 'en-b1-31', 'passion', '/ˈpæʃən/', 'B1', 'niềm đam mê; sự say mê; cảm xúc mãnh liệt; sự nồng nhiệt', 'n.', 'passionate (adj.), passionately (adv.), dispassionate (adj.)', 'Đồng nghĩa: enthusiasm, ardour · Trái nghĩa: apathy', 'Để diễn tả niềm đam mê đối với việc gì đó, sử dụng cấu trúc a passion for.', 'Her passion for baking fills our kitchen with delicious smells.', NULL, 'Niềm đam mê làm bánh của cô ấy khiến căn phòng bếp lúc nào cũng ngập tràn hương thơm hấp dẫn.', '{"wordId":"passion","ukIpa":"/ˈpæʃən/","usIpa":"/ˈpæʃən/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"a very strong enthusiasm for an activity or subject","vi":"niềm đam mê; sự say mê"},{"pos":"n.","en":"a powerful feeling, especially love or anger","vi":"cảm xúc mãnh liệt; sự nồng nhiệt"}],"examples":[{"en":"Her passion for baking fills our kitchen with delicious smells.","vi":"Niềm đam mê làm bánh của cô ấy khiến căn phòng bếp lúc nào cũng ngập tràn hương thơm hấp dẫn.","audioKind":"ex"},{"en":"Teachers who share their passion for science can inspire students to pursue careers in research.","vi":"Những giáo viên truyền đạt được niềm đam mê khoa học của họ có thể truyền cảm hứng cho học sinh theo đuổi sự nghiệp nghiên cứu.","audioKind":"ex2"}],"collocations":[{"en":"a passion for music","vi":"niềm đam mê âm nhạc"},{"en":"develop a passion for","vi":"nuôi dưỡng niềm đam mê"},{"en":"pursue your passion","vi":"theo đuổi niềm đam mê"}],"wordFamily":["passionate (adj.)","passionately (adv.)","dispassionate (adj.)"],"synonyms":["enthusiasm","ardour"],"antonyms":["apathy"],"tipVi":"Để diễn tả niềm đam mê đối với việc gì đó, sử dụng cấu trúc a passion for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_keen', 'en-b1-31', 'keen', '/kiːn/', 'B1', 'hứng thú; say mê; khao khát; sắc sảo; tinh nhạy; mãnh liệt; dữ dội', 'adj.', 'keenly (adv.), keenness (n.)', 'Đồng nghĩa: eager, enthusiastic · Trái nghĩa: uninterested', 'keen on theo sau bởi danh từ hoặc danh động từ; keen to theo sau bởi động từ nguyên mẫu.', 'Leila is keen to join our weekend hiking group.', NULL, 'Leila rất muốn tham gia nhóm đi bộ đường dài cuối tuần của chúng tôi.', '{"wordId":"keen","ukIpa":"/kiːn/","usIpa":"/kiːn/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"very interested in something or eager to do it","vi":"hứng thú; say mê; khao khát"},{"pos":"adj.","en":"quick to notice or understand things","vi":"sắc sảo; tinh nhạy"},{"pos":"adj.","en":"very strong or intense","vi":"mãnh liệt; dữ dội"}],"examples":[{"en":"Leila is keen to join our weekend hiking group.","vi":"Leila rất muốn tham gia nhóm đi bộ đường dài cuối tuần của chúng tôi.","audioKind":"ex"},{"en":"Students who are keen on science benefit from practical experiments that connect theory with everyday experience.","vi":"Những học sinh yêu thích khoa học sẽ được hưởng lợi từ các thí nghiệm thực tế kết nối lý thuyết với trải nghiệm hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"keen to learn","vi":"khao khát học hỏi"},{"en":"keen on sport","vi":"hứng thú với thể thao"},{"en":"a keen eye for detail","vi":"con mắt quan sát chi tiết tinh nhạy"},{"en":"keen competition","vi":"cạnh tranh khốc liệt"}],"wordFamily":["keenly (adv.)","keenness (n.)"],"synonyms":["eager","enthusiastic"],"antonyms":["uninterested"],"tipVi":"keen on theo sau bởi danh từ hoặc danh động từ; keen to theo sau bởi động từ nguyên mẫu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_embarrassed', 'en-b1-31', 'embarrassed', '/ɪmˈbærəst/', 'B1', 'xấu hổ; ngượng ngùng; bối rối', 'adj.', 'embarrass (v.), embarrassing (adj.), embarrassment (n.)', 'Đồng nghĩa: self-conscious, ashamed · Trái nghĩa: unembarrassed', 'Cảm giác của con người dùng embarrassed; sự việc gây ngượng ngùng dùng embarrassing.', 'I felt embarrassed when my phone rang during dinner.', NULL, 'Tôi cảm thấy rất ngượng ngùng khi điện thoại reo lên trong bữa tối.', '{"wordId":"embarrassed","ukIpa":"/ɪmˈbærəst/","usIpa":"/ɪmˈbærəst/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling uncomfortable or ashamed about something others notice.","vi":"xấu hổ; ngượng ngùng; bối rối"}],"examples":[{"en":"I felt embarrassed when my phone rang during dinner.","vi":"Tôi cảm thấy rất ngượng ngùng khi điện thoại reo lên trong bữa tối.","audioKind":"ex"},{"en":"Students may feel embarrassed about making mistakes, so teachers should create a supportive classroom environment.","vi":"Học sinh có thể cảm thấy ngại ngùng khi mắc lỗi, vì vậy giáo viên nên tạo ra một môi trường lớp học mang tính hỗ trợ.","audioKind":"ex2"}],"collocations":[{"en":"feel embarrassed","vi":"cảm thấy xấu hổ"},{"en":"embarrassed about","vi":"ngượng ngùng về"},{"en":"too embarrassed to ask","vi":"quá ngượng không dám hỏi"}],"wordFamily":["embarrass (v.)","embarrassing (adj.)","embarrassment (n.)"],"synonyms":["self-conscious","ashamed"],"antonyms":["unembarrassed"],"tipVi":"Cảm giác của con người dùng embarrassed; sự việc gây ngượng ngùng dùng embarrassing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_excite', 'en-b1-31', 'excite', '/ɪkˈsaɪt/', 'B1', 'làm cho phấn khích; làm cho hào hứng; khơi dậy; kích thích', 'v.', 'excited (adj.), exciting (adj.), excitement (n.)', 'Đồng nghĩa: thrill, stimulate · Trái nghĩa: bore', 'Người cảm thấy hào hứng dùng excited; sự vật gây hào hứng dùng exciting.', 'Trips to the seaside always excite my younger sister.', NULL, 'Những chuyến đi ra biển luôn làm cho em gái tôi phấn khích tột cùng.', '{"wordId":"excite","ukIpa":"/ɪkˈsaɪt/","usIpa":"/ɪkˈsaɪt/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"to make someone feel enthusiastic and eager","vi":"làm cho phấn khích; làm cho hào hứng"},{"pos":"v.","en":"to cause a particular feeling or reaction","vi":"khơi dậy; kích thích"}],"examples":[{"en":"Trips to the seaside always excite my younger sister.","vi":"Những chuyến đi ra biển luôn làm cho em gái tôi phấn khích tột cùng.","audioKind":"ex"},{"en":"Interactive science exhibitions can excite young visitors and encourage them to explore scientific ideas independently.","vi":"Các cuộc triển lãm khoa học tương tác có thể khơi gợi sự hứng thú ở khách tham quan nhỏ tuổi và khuyến khích họ tự khám phá các ý tưởng khoa học.","audioKind":"ex2"}],"collocations":[{"en":"excite interest","vi":"khơi gợi sự quan tâm"},{"en":"excite curiosity","vi":"khơi dậy sự tò mò"},{"en":"excite the imagination","vi":"kích thích trí tưởng tượng"}],"wordFamily":["excited (adj.)","exciting (adj.)","excitement (n.)"],"synonyms":["thrill","stimulate"],"antonyms":["bore"],"tipVi":"Người cảm thấy hào hứng dùng excited; sự vật gây hào hứng dùng exciting.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cruel', 'en-b1-31', 'cruel', '/ˈkruːəl/', 'B1', 'tàn nhẫn; cay nghiệt; gây đau khổ tột cùng; phũ phàng', 'adj.', 'cruelty (n.), cruelly (adv.)', 'Đồng nghĩa: unkind, heartless · Trái nghĩa: kind, compassionate', 'Biểu thị sự tàn nhẫn với ai hoặc động vật, dùng be cruel to.', 'It was cruel to laugh at her mistake.', NULL, 'Thật là cay nghiệt khi cười cợt trước lỗi lầm của cô ấy.', '{"wordId":"cruel","ukIpa":"/ˈkruːəl/","usIpa":"/ˈkruːəl/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Causing suffering without caring about others'' feelings.","vi":"tàn nhẫn; cay nghiệt"},{"pos":"adj.","en":"Causing great suffering or disappointment.","vi":"gây đau khổ tột cùng; phũ phàng"}],"examples":[{"en":"It was cruel to laugh at her mistake.","vi":"Thật là cay nghiệt khi cười cợt trước lỗi lầm của cô ấy.","audioKind":"ex"},{"en":"Schools should address cruel behaviour early to ensure that every child feels safe and respected.","vi":"Nhà trường nên giải quyết sớm các hành vi tàn nhẫn để đảm bảo mọi đứa trẻ đều cảm thấy an toàn và được tôn trọng.","audioKind":"ex2"}],"collocations":[{"en":"be cruel to animals","vi":"ngược đãi động vật"},{"en":"a cruel remark","vi":"lời nói cay nghiệt"},{"en":"a cruel blow","vi":"cú sốc phũ phàng"}],"wordFamily":["cruelty (n.)","cruelly (adv.)"],"synonyms":["unkind","heartless"],"antonyms":["kind","compassionate"],"tipVi":"Biểu thị sự tàn nhẫn với ai hoặc động vật, dùng be cruel to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hug', 'en-b1-31', 'hug', '/hʌɡ/', 'B1', 'ôm; ôm chặt; cái ôm', 'v.', NULL, 'Đồng nghĩa: embrace', 'Dạng quá khứ hugged và phân từ hiện đại hugging đều được gấp đôi chữ g.', 'Lena hugged her grandmother before leaving for school.', NULL, 'Lena đã ôm bà của mình trước khi đi học.', '{"wordId":"hug","ukIpa":"/hʌɡ/","usIpa":"/hʌɡ/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"Put your arms around someone and hold them close","vi":"ôm; ôm chặt"},{"pos":"n.","en":"An act of holding someone close with your arms","vi":"cái ôm"}],"examples":[{"en":"Lena hugged her grandmother before leaving for school.","vi":"Lena đã ôm bà của mình trước khi đi học.","audioKind":"ex"},{"en":"A reassuring hug from a parent can help young children manage stress in unfamiliar situations.","vi":"Một cái ôm trấn an từ cha mẹ có thể giúp trẻ nhỏ đối phó với căng thẳng trong những tình huống xa lạ.","audioKind":"ex2"}],"collocations":[{"en":"give someone a hug","vi":"ôm ai đó"},{"en":"a warm hug","vi":"cái ôm ấm áp"},{"en":"hug someone tightly","vi":"ôm chặt ai đó"}],"wordFamily":[],"synonyms":["embrace"],"antonyms":[],"tipVi":"Dạng quá khứ hugged và phân từ hiện đại hugging đều được gấp đôi chữ g.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amazed', 'en-b1-31', 'amazed', '/əˈmeɪzd/', 'B1', 'vô cùng ngạc nhiên; kinh ngạc', 'adj.', 'amaze (v.), amazing (adj.), amazement (n.)', 'Đồng nghĩa: astonished, astounded · Trái nghĩa: unsurprised', 'Dùng amazed để diễn tả cảm xúc của con người; dùng amazing để miêu tả sự vật, sự việc gây ngạc nhiên.', 'I was amazed to find flowers growing through concrete.', NULL, 'Tôi vô cùng ngạc nhiên khi thấy những bông hoa mọc xuyên qua lớp bê tông.', '{"wordId":"amazed","ukIpa":"/əˈmeɪzd/","usIpa":"/əˈmeɪzd/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"Very surprised by something unexpected.","vi":"vô cùng ngạc nhiên; kinh ngạc"}],"examples":[{"en":"I was amazed to find flowers growing through concrete.","vi":"Tôi vô cùng ngạc nhiên khi thấy những bông hoa mọc xuyên qua lớp bê tông.","audioKind":"ex"},{"en":"Researchers were amazed by how quickly children learned new vocabulary through interactive games.","vi":"Các nhà nghiên cứu đã rất kinh ngạc trước tốc độ học từ vựng mới nhanh chóng của trẻ em thông qua các trò chơi tương tác.","audioKind":"ex2"}],"collocations":[{"en":"be amazed at","vi":"ngạc nhiên về"},{"en":"be amazed by","vi":"bị kinh ngạc bởi"},{"en":"be amazed to discover","vi":"ngạc nhiên khi phát hiện"}],"wordFamily":["amaze (v.)","amazing (adj.)","amazement (n.)"],"synonyms":["astonished","astounded"],"antonyms":["unsurprised"],"tipVi":"Dùng amazed để diễn tả cảm xúc của con người; dùng amazing để miêu tả sự vật, sự việc gây ngạc nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fascinating', 'en-b1-31', 'fascinating', '/ˈfæsɪneɪtɪŋ/', 'B1', 'hấp dẫn; cực kỳ thú vị; mê hoặc', 'adj.', 'fascinate (v.), fascinated (adj.), fascination (n.)', 'Đồng nghĩa: captivating, engrossing, intriguing · Trái nghĩa: boring, dull', 'Sự vật khiến người khác say mê dùng fascinating; bản thân người bị cuốn hút dùng fascinated.', 'The guide told us fascinating stories about the castle.', NULL, 'Hướng dẫn viên đã kể cho chúng tôi nghe những câu chuyện cực kỳ thú vị về lâu đài này.', '{"wordId":"fascinating","ukIpa":"/ˈfæsɪneɪtɪŋ/","usIpa":"/ˈfæsɪneɪtɪŋ/","cefr":"B1","topic":"emotion","senses":[{"pos":"adj.","en":"so interesting that it holds your attention completely","vi":"hấp dẫn; cực kỳ thú vị; mê hoặc"}],"examples":[{"en":"The guide told us fascinating stories about the castle.","vi":"Hướng dẫn viên đã kể cho chúng tôi nghe những câu chuyện cực kỳ thú vị về lâu đài này.","audioKind":"ex"},{"en":"Museum collections offer fascinating insights into how earlier societies adapted to changes in their natural environments.","vi":"Các bộ sưu tập trong bảo tàng mang đến những góc nhìn vô cùng hấp dẫn về cách các xã hội thời kỳ đầu thích nghi với sự thay đổi của môi trường tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"absolutely fascinating","vi":"vô cùng hấp dẫn"},{"en":"fascinating insight","vi":"góc nhìn đầy lôi cuốn"},{"en":"fascinating discovery","vi":"phát hiện đầy kinh ngạc"}],"wordFamily":["fascinate (v.)","fascinated (adj.)","fascination (n.)"],"synonyms":["captivating","engrossing","intriguing"],"antonyms":["boring","dull"],"tipVi":"Sự vật khiến người khác say mê dùng fascinating; bản thân người bị cuốn hút dùng fascinated.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_romance', 'en-b1-31', 'romance', '/ˈroʊmæns/', 'B1', 'chuyện tình yêu; sự lãng mạn; truyện tình cảm; phim tình cảm', 'n.', 'romantic (adj.), romantically (adv.)', NULL, 'Danh từ chỉ tình yêu nói chung thường không đếm được; khi chỉ một cuộc tình cụ thể hoặc tác phẩm nghệ thuật thì đếm được.', 'Their romance began during a walking holiday in the mountains.', NULL, 'Mối tình của họ bắt đầu trong một chuyến đi bộ đường dài nghỉ dưỡng trên núi.', '{"wordId":"romance","ukIpa":"/rəʊˈmæns/","usIpa":"/ˈroʊmæns/","cefr":"B1","topic":"emotion","senses":[{"pos":"n.","en":"a loving relationship or the excitement and affection surrounding love","vi":"chuyện tình yêu; sự lãng mạn"},{"pos":"n.","en":"a story or film mainly about love","vi":"truyện tình cảm; phim tình cảm"}],"examples":[{"en":"Their romance began during a walking holiday in the mountains.","vi":"Mối tình của họ bắt đầu trong một chuyến đi bộ đường dài nghỉ dưỡng trên núi.","audioKind":"ex"},{"en":"Popular films often portray romance in idealised ways, which may shape young people''s expectations of relationships.","vi":"Các bộ phim phổ biến thường khắc họa tình yêu theo nhữngh lý tưởng hóa, điều này có thể định hình kỳ vọng của giới trẻ về các mối quan hệ tình cảm.","audioKind":"ex2"}],"collocations":[{"en":"a holiday romance","vi":"mối tình trong kỳ nghỉ"},{"en":"a whirlwind romance","vi":"mối tình chớp nhoáng"},{"en":"a sense of romance","vi":"cảm giác lãng mạn"}],"wordFamily":["romantic (adj.)","romantically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ tình yêu nói chung thường không đếm được; khi chỉ một cuộc tình cụ thể hoặc tác phẩm nghệ thuật thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forgive', 'en-b1-31', 'forgive', '/fərˈɡɪv/', 'B1', 'tha thứ; khoan dung; xóa nợ; miễn nợ', 'v.', 'forgiveness (n.), forgiving (adj.), forgivable (adj.), unforgivable (adj.)', 'Đồng nghĩa: pardon', 'Dùng cấu trúc forgive sb for doing sth; quá khứ là forgave, quá khứ phân từ là forgiven.', 'Can you forgive me for breaking your favourite mug?', NULL, 'Bạn có thể tha thứ cho tôi vì đã làm vỡ chiếc cốc yêu thích của bạn không?', '{"wordId":"forgive","ukIpa":"/fəˈɡɪv/","usIpa":"/fərˈɡɪv/","cefr":"B1","topic":"emotion","senses":[{"pos":"v.","en":"Stop blaming someone or feeling angry about what they did.","vi":"tha thứ; khoan dung"},{"pos":"v.","en":"Officially allow someone not to repay a debt.","vi":"xóa nợ; miễn nợ"}],"examples":[{"en":"Can you forgive me for breaking your favourite mug?","vi":"Bạn có thể tha thứ cho tôi vì đã làm vỡ chiếc cốc yêu thích của bạn không?","audioKind":"ex"},{"en":"International lenders may forgive some debts to help poorer countries invest more in healthcare and education.","vi":"Các chủ nợ quốc tế có thể xóa một số khoản nợ để giúp các nước nghèo hơn đầu tư nhiều hơn vào y tế và giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"forgive someone for something","vi":"tha thứ cho ai vì điều gì"},{"en":"forgive a mistake","vi":"tha thứ cho một lỗi lầm"},{"en":"forgive a debt","vi":"xóa nợ"}],"wordFamily":["forgiveness (n.)","forgiving (adj.)","forgivable (adj.)","unforgivable (adj.)"],"synonyms":["pardon"],"antonyms":[],"tipVi":"Dùng cấu trúc forgive sb for doing sth; quá khứ là forgave, quá khứ phân từ là forgiven.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_31_1', 'en-b1-31', 'Cách dùng “joy” (n.) — niềm vui; sự hân hoan', 'bring joy  ·  jump for joy  ·  tears of joy', 'Biểu thị niềm vui thường là danh từ không đếm được; biểu thị niềm vui thích/điều vui sướng là danh từ đếm được, chẳng hạn như a joy.', 'Họ từ (Word Family): joyful (adj.), joyfully (adv.), joyous (adj.) | Đồng nghĩa: delight, happiness · Trái nghĩa: sorrow, misery', '[{"hanzi":"The children jumped for joy when the snow began.","pinyin":"","meaning":"Bọn trẻ nhảy cẫng lên vì vui sướng khi tuyết bắt đầu rơi."},{"hanzi":"Community gardens can bring joy to residents while strengthening social connections and encouraging healthier lifestyles.","pinyin":"","meaning":"Các khu vườn cộng đồng có thể mang lại niềm vui cho cư dân, đồng thời thắt chặt tình òa xã hội và khuyến khích lối sống lành mạnh hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_31_2', 'en-b1-31', 'Cách dùng “romance” (n.) — chuyện tình yêu; sự lãng mạn', 'a holiday romance  ·  a whirlwind romance  ·  a sense of romance', 'Danh từ chỉ tình yêu nói chung thường không đếm được; khi chỉ một cuộc tình cụ thể hoặc tác phẩm nghệ thuật thì đếm được.', 'Họ từ (Word Family): romantic (adj.), romantically (adv.)', '[{"hanzi":"Their romance began during a walking holiday in the mountains.","pinyin":"","meaning":"Mối tình của họ bắt đầu trong một chuyến đi bộ đường dài nghỉ dưỡng trên núi."},{"hanzi":"Popular films often portray romance in idealised ways, which may shape young people''s expectations of relationships.","pinyin":"","meaning":"Các bộ phim phổ biến thường khắc họa tình yêu theo nhữngh lý tưởng hóa, điều này có thể định hình kỳ vọng của giới trẻ về các mối quan hệ tình cảm."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_31_3', 'en-b1-31', 'Cách dùng “willing” (adj.) — sẵn lòng; tự nguyện; vui lòng', 'be willing to do something  ·  a willing volunteer  ·  a willing helper', 'Thường dùng trong cấu trúc be willing to do, diễn tả sự sẵn lòng chứ không mang nghĩa thì tương lai (sẽ).', 'Họ từ (Word Family): willingness (n.), willingly (adv.), unwilling (adj.) | Đồng nghĩa: ready, prepared · Trái nghĩa: unwilling, reluctant', '[{"hanzi":"I''m willing to help you move this weekend.","pinyin":"","meaning":"Tôi sẵn lòng giúp bạn chuyển nhà vào cuối tuần này."},{"hanzi":"Consumers may be more willing to buy sustainable products if prices remain affordable and information is clear.","pinyin":"","meaning":"Người tiêu dùng có thể sẵn sàng mua các sản phẩm bền vững hơn nếu giá cả phải chăng và thông tin được minh bạch."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_31_4', 'en-b1-31', 'Cách dùng “amazed” (adj.) — vô cùng ngạc nhiên; kinh ngạc', 'be amazed at  ·  be amazed by  ·  be amazed to discover', 'Dùng amazed để diễn tả cảm xúc của con người; dùng amazing để miêu tả sự vật, sự việc gây ngạc nhiên.', 'Họ từ (Word Family): amaze (v.), amazing (adj.), amazement (n.) | Đồng nghĩa: astonished, astounded · Trái nghĩa: unsurprised', '[{"hanzi":"I was amazed to find flowers growing through concrete.","pinyin":"","meaning":"Tôi vô cùng ngạc nhiên khi thấy những bông hoa mọc xuyên qua lớp bê tông."},{"hanzi":"Researchers were amazed by how quickly children learned new vocabulary through interactive games.","pinyin":"","meaning":"Các nhà nghiên cứu đã rất kinh ngạc trước tốc độ học từ vựng mới nhanh chóng của trẻ em thông qua các trò chơi tương tác."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_31_1', 'en-b1-31', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_1_1', 'ten_b1_31_1', 'merry', 'Their merry laughter filled the kitchen as they baked.', 'Their merry laughter filled the kitchen as they baked.', '/ˈmeri/', 'Tiếng cười vui vẻ của họ ngập tràn căn bếp khi họ nướng bánh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_1_2', 'ten_b1_31_1', 'joy', 'The children jumped for joy when the snow began.', 'The children jumped for joy when the snow began.', '/dʒɔɪ/', 'Bọn trẻ nhảy cẫng lên vì vui sướng khi tuyết bắt đầu rơi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_1_3', 'ten_b1_31_1', 'disappointment', 'Her face showed disappointment when the picnic was cancelled.', 'Her face showed disappointment when the picnic was cancelled.', '/ˌdɪsəˈpɔɪntmənt/', 'Cô ấy lộ rõ vẻ thất vọng khi chuyến dã ngoại bị hủy.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_1_4', 'ten_b1_31_1', 'embarrassing', 'It was embarrassing when my phone rang during the ceremony.', 'It was embarrassing when my phone rang during the ceremony.', '/ɪmˈbærəsɪŋ/', 'Thật là xấu hổ khi điện thoại của tôi reo lên trong buổi lễ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_1_5', 'ten_b1_31_1', 'miserable', 'I felt miserable when rain ruined our picnic plans.', 'I felt miserable when rain ruined our picnic plans.', '/ˈmɪzərəbl/', 'Tôi cảm thấy rất buồn khi cơn mưa làm hỏng kế hoạch đi dã ngoại của chúng tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_1_6', 'ten_b1_31_1', 'shame', 'He felt shame after lying to his closest friend.', 'He felt shame after lying to his closest friend.', '/ʃeɪm/', 'Anh ấy cảm thấy vô cùng xấu hổ sau khi nói dối người bạn thân nhất của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_1_7', 'ten_b1_31_1', 'willing', 'I''m willing to help you move this weekend.', 'I''m willing to help you move this weekend.', '/ˈwɪlɪŋ/', 'Tôi sẵn lòng giúp bạn chuyển nhà vào cuối tuần này.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_1_8', 'ten_b1_31_1', 'congratulate', 'We called to congratulate Lina on her new job.', 'We called to congratulate Lina on her new job.', '/kənˈɡrætʃəleɪt/', 'Chúng tôi đã gọi điện để chúc mừng Lina về công việc mới của cô ấy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_31_1_1', 'en-b1-31', 'ten_b1_31_1', 'listening', 'listening', 'Their merry laughter filled the kitchen as they baked.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã vô cùng hoảng sợ khi tiếng sấm làm rung chuyển những khung cửa sổ vào đêm qua.","Tôi vô cùng ngạc nhiên khi thấy những bông hoa mọc xuyên qua lớp bê tông.","Tiếng cười vui vẻ của họ ngập tràn căn bếp khi họ nướng bánh.","Lena đã ôm bà của mình trước khi đi học."]'::jsonb, 2, 'Their merry laughter filled the kitchen as they baked. → Tiếng cười vui vẻ của họ ngập tràn căn bếp khi họ nướng bánh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_31_1_2', 'en-b1-31', 'ten_b1_31_1', 'listening', 'listening', 'The children jumped for joy when the snow began.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bọn trẻ nhảy cẫng lên vì vui sướng khi tuyết bắt đầu rơi.","Leila rất muốn tham gia nhóm đi bộ đường dài cuối tuần của chúng tôi.","Chúng tôi đã gọi điện để chúc mừng Lina về công việc mới của cô ấy.","Tôi cảm thấy rất buồn khi cơn mưa làm hỏng kế hoạch đi dã ngoại của chúng tôi."]'::jsonb, 0, 'The children jumped for joy when the snow began. → Bọn trẻ nhảy cẫng lên vì vui sướng khi tuyết bắt đầu rơi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_31_1_3', 'en-b1-31', 'ten_b1_31_1', 'listening', 'listening', 'Her face showed disappointment when the picnic was cancelled.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi cảm thấy rất ngượng ngùng khi điện thoại reo lên trong bữa tối.","Hướng dẫn viên đã kể cho chúng tôi nghe những câu chuyện cực kỳ thú vị về lâu đài này.","Tiếng cười vui vẻ của họ ngập tràn căn bếp khi họ nướng bánh.","Cô ấy lộ rõ vẻ thất vọng khi chuyến dã ngoại bị hủy."]'::jsonb, 3, 'Her face showed disappointment when the picnic was cancelled. → Cô ấy lộ rõ vẻ thất vọng khi chuyến dã ngoại bị hủy.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_31_2', 'en-b1-31', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_2_1', 'ten_b1_31_2', 'merry', 'Community festivals create a merry atmosphere that encourages residents of different ages to interact and build friendships.', 'Community festivals create a merry atmosphere that encourages residents of different ages to interact and build friendships.', '/ˈmeri/', 'Các lễ hội cộng đồng tạo ra bầu không khí hân hoan, khuyến khích người dân ở mọi lứa tuổi giao lưu và xây dựng tình bạn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_2_2', 'ten_b1_31_2', 'joy', 'Community gardens can bring joy to residents while strengthening social connections and encouraging healthier lifestyles.', 'Community gardens can bring joy to residents while strengthening social connections and encouraging healthier lifestyles.', '/dʒɔɪ/', 'Các khu vườn cộng đồng có thể mang lại niềm vui cho cư dân, đồng thời thắt chặt tình òa xã hội và khuyến khích lối sống lành mạnh hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_2_3', 'ten_b1_31_2', 'disappointment', 'Teaching young people to cope with disappointment can help them respond more positively to academic setbacks.', 'Teaching young people to cope with disappointment can help them respond more positively to academic setbacks.', '/ˌdɪsəˈpɔɪntmənt/', 'Dạy người trẻ cách đối phó với sự thất vọng có thể giúp họ phản ứng tích cực hơn trước những cú vấp ngã trong học tập.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_2_4', 'ten_b1_31_2', 'embarrassing', 'Students may avoid asking questions if they believe that making mistakes in front of classmates is embarrassing.', 'Students may avoid asking questions if they believe that making mistakes in front of classmates is embarrassing.', '/ɪmˈbærəsɪŋ/', 'Học sinh có thể tránh đặt câu hỏi nếu các em cho rằng việc mắc lỗi trước mặt bạn bè là điều xấu hổ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_2_5', 'ten_b1_31_2', 'miserable', 'Overcrowded housing can create miserable living conditions and negatively affect residents'' physical and mental health.', 'Overcrowded housing can create miserable living conditions and negatively affect residents'' physical and mental health.', '/ˈmɪzərəbl/', 'Nhà ở chật chội có thể tạo ra điều kiện sống tồi tệ và tác động tiêu cực đến sức khỏe thể chất lẫn tinh thần của cư dân.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_31_2_6', 'ten_b1_31_2', 'shame', 'Schools should address bullying without creating a culture of shame that prevents pupils from seeking help.', 'Schools should address bullying without creating a culture of shame that prevents pupils from seeking help.', '/ʃeɪm/', 'Nhà trường nên giải quyết tình trạng bắt nạt mà không tạo ra một bầu không khí đầy sự mặc cảm, khiến học sinh không dám tìm kiếm sự giúp đỡ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_31_2_1', 'en-b1-31', 'ten_b1_31_2', 'listening', 'listening', 'Community festivals create a merry atmosphere that encourages residents of different ages to interact and build friendships.', NULL, 'Trong câu vừa nghe, từ “merry” mang nghĩa nào sau đây?', '["nữ chủ nhà; nữ gia chủ (tiếp đón khách)","làm mệt mỏi; căng thẳng; mệt nhọc","niềm tin; sự tin tưởng","vui vẻ; rộn ràng; hân hoan"]'::jsonb, 3, '“merry” (/ˈmeri/): vui vẻ; rộn ràng; hân hoan. Câu đầy đủ: Community festivals create a merry atmosphere that encourages residents of different ages to interact and build friendships.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_31_2_2', 'en-b1-31', 'ten_b1_31_2', 'listening', 'listening', 'Community gardens can bring joy to residents while strengthening social connections and encouraging healthier lifestyles.', NULL, 'Trong câu vừa nghe, từ “joy” mang nghĩa nào sau đây?', '["gây bối rối; xấu hổ; khó xử","niềm vui; sự hân hoan","nghệ sĩ piano; người chơi đàn piano","chiến dịch; cuộc vận động"]'::jsonb, 1, '“joy” (/dʒɔɪ/): niềm vui; sự hân hoan. Câu đầy đủ: Community gardens can bring joy to residents while strengthening social connections and encouraging healthier lifestyles.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
