INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_31_1', 'en-b1-31', NULL, 'comprehensive_test', 'listening', 'merry', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vui vẻ; rộn ràng; hân hoan","tuyệt vời; cực kỳ thú vị","ban công; hiên nhà","giới từ"]'::jsonb, 0, 'merry (/ˈmeri/) → vui vẻ; rộn ràng; hân hoan', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_31_2', 'en-b1-31', NULL, 'comprehensive_test', 'listening', 'The children jumped for joy when the snow began.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những chuyến đi ra biển luôn làm cho em gái tôi phấn khích tột cùng.","Chúng tôi đã gọi điện để chúc mừng Lina về công việc mới của cô ấy.","Bạn có thể tha thứ cho tôi vì đã làm vỡ chiếc cốc yêu thích của bạn không?","Bọn trẻ nhảy cẫng lên vì vui sướng khi tuyết bắt đầu rơi."]'::jsonb, 3, 'The children jumped for joy when the snow began. → Bọn trẻ nhảy cẫng lên vì vui sướng khi tuyết bắt đầu rơi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_31_3', 'en-b1-31', NULL, 'comprehensive_test', 'listening', 'disappointment', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự thất vọng; niềm thất vọng","giả vờ; giả bộ","thỏa thuận; hiệp định","tầng của một tòa nhà"]'::jsonb, 0, 'disappointment (/ˌdɪsəˈpɔɪntmənt/) → sự thất vọng; niềm thất vọng; người hoặc vật gây thất vọng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_31_4', 'en-b1-31', NULL, 'comprehensive_test', 'listening', 'It was embarrassing when my phone rang during the ceremony.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Leila rất muốn tham gia nhóm đi bộ đường dài cuối tuần của chúng tôi.","Anh ấy cảm thấy vô cùng xấu hổ sau khi nói dối người bạn thân nhất của mình.","Thật là xấu hổ khi điện thoại của tôi reo lên trong buổi lễ.","Cô ấy lộ rõ vẻ thất vọng khi chuyến dã ngoại bị hủy."]'::jsonb, 2, 'It was embarrassing when my phone rang during the ceremony. → Thật là xấu hổ khi điện thoại của tôi reo lên trong buổi lễ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_31_5', 'en-b1-31', NULL, 'comprehensive_test', 'listening', 'miserable', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khốn khổ; đau khổ; buồn rầu","nướng (thức ăn bằng nhiệt khô, đặc biệt trong lò)","mũ lưỡi trai; mũ mềm có vành cứng phía trước","ban công; hiên nhà"]'::jsonb, 0, 'miserable (/ˈmɪzərəbl/) → khốn khổ; đau khổ; buồn rầu; tồi tệ; thảm hại (điều kiện sống, thời tiết)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_31_6', 'en-b1-31', NULL, 'comprehensive_test', 'listening', 'He felt shame after lying to his closest friend.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thật là xấu hổ khi điện thoại của tôi reo lên trong buổi lễ.","Bạn có thể tha thứ cho tôi vì đã làm vỡ chiếc cốc yêu thích của bạn không?","Anh ấy cảm thấy vô cùng xấu hổ sau khi nói dối người bạn thân nhất của mình.","Hướng dẫn viên đã kể cho chúng tôi nghe những câu chuyện cực kỳ thú vị về lâu đài này."]'::jsonb, 2, 'He felt shame after lying to his closest friend. → Anh ấy cảm thấy vô cùng xấu hổ sau khi nói dối người bạn thân nhất của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
