INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_31_18', 'en-b1-31', NULL, 'comprehensive_test', 'reading', NULL, 'Community festivals create a merry atmosphere that encourages residents of different ages to interact and build friendships.', 'Dựa vào câu trên, từ “merry” có nghĩa phù hợp nhất là gì?', '["cuộc đối thoại; sự trao đổi ý kiến","có hiệu quả; đem lại kết quả mong muốn","vui vẻ; rộn ràng; hân hoan","hàng rào; rào chắn"]'::jsonb, 2, 'merry: vui vẻ; rộn ràng; hân hoan. Dịch cả câu: Các lễ hội cộng đồng tạo ra bầu không khí hân hoan, khuyến khích người dân ở mọi lứa tuổi giao lưu và xây dựng tình bạn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_31_19', 'en-b1-31', NULL, 'comprehensive_test', 'reading', NULL, 'Community gardens can bring joy to residents while strengthening social connections and encouraging healthier lifestyles.', 'Dựa vào câu trên, từ “joy” có nghĩa phù hợp nhất là gì?', '["về phần mình; cá nhân tôi","niềm vui; sự hân hoan","đăng ký; ghi danh","ngoài trời; lộ thiên"]'::jsonb, 1, 'joy: niềm vui; sự hân hoan; điều hạnh phúc. Dịch cả câu: Các khu vườn cộng đồng có thể mang lại niềm vui cho cư dân, đồng thời thắt chặt tình òa xã hội và khuyến khích lối sống lành mạnh hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_31_20', 'en-b1-31', NULL, 'comprehensive_test', 'reading', NULL, 'Teaching young people to cope with disappointment can help them respond more positively to academic setbacks.', 'Dựa vào câu trên, từ “disappointment” có nghĩa phù hợp nhất là gì?', '["tiền phí dịch vụ; học phí; thù lao chuyên môn","sự thất vọng; niềm thất vọng","khó khăn; gai góc; nan giải","bể chứa; thùng chứa; hồ nước"]'::jsonb, 1, 'disappointment: sự thất vọng; niềm thất vọng; người hoặc vật gây thất vọng. Dịch cả câu: Dạy người trẻ cách đối phó với sự thất vọng có thể giúp họ phản ứng tích cực hơn trước những cú vấp ngã trong học tập.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_31_21', 'en-b1-31', NULL, 'comprehensive_test', 'reading', NULL, 'Students may avoid asking questions if they believe that making mistakes in front of classmates is embarrassing.', 'Dựa vào câu trên, từ “embarrassing” có nghĩa phù hợp nhất là gì?', '["biểu đồ; đồ thị","xu hướng; trào lưu","lúa mì; mỳ","gây bối rối; xấu hổ; khó xử"]'::jsonb, 3, 'embarrassing: gây bối rối; xấu hổ; khó xử. Dịch cả câu: Học sinh có thể tránh đặt câu hỏi nếu các em cho rằng việc mắc lỗi trước mặt bạn bè là điều xấu hổ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_31_22', 'en-b1-31', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hấp dẫn; cực kỳ thú vị; mê hoặc”', '["pyramid","wheat","fascinating","boxer"]'::jsonb, 2, 'hấp dẫn; cực kỳ thú vị; mê hoặc → fascinating (/ˈfæsɪneɪtɪŋ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_31_23', 'en-b1-31', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chuyện tình yêu; sự lãng mạn”', '["romance","drown","willing","bleed"]'::jsonb, 0, 'chuyện tình yêu; sự lãng mạn → romance (/ˈroʊmæns/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_31_24', 'en-b1-31', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tha thứ; khoan dung”', '["forgive","accommodation","handkerchief","ignore"]'::jsonb, 0, 'tha thứ; khoan dung → forgive (/fərˈɡɪv/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-32', 'en', 'Bài 32: Công việc & Nghề nghiệp (1) - CEFR B1', 'CEFR B1', 'B1 · Công việc', '24 từ vựng Tiếng Anh CEFR B1 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3032, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_qualification', 'en-b1-32', 'qualification', '/ˌkwɑːlɪfɪˈkeɪʃən/', 'B1', 'bằng cấp, chứng chỉ (chứng nhận hoàn thành chương trình học tập hoặc đào tạo); năng lực, trình độ chuyên môn (kỹ năng hoặc phẩm chất phù hợp cho một vị trí); điều kiện hạn chế, ý kiến bảo lưu (điều kiện làm giảm ý nghĩa hoặc sự chấp nhận của việc gì)', 'n.', 'qualify (v.), qualified (adj.), unqualified (adj.), qualifying (adj.)', 'Đồng nghĩa: credential', 'Khi nói về bằng cấp hoặc năng lực chuyên môn, người ta thường dùng hình thức số nhiều qualifications.', 'This qualification helped me find work at a nursery.', NULL, 'Chứng chỉ này đã giúp tôi tìm được việc làm tại một nhà trẻ.', '{"wordId":"qualification","ukIpa":"/ˌkwɒlɪfɪˈkeɪʃən/","usIpa":"/ˌkwɑːlɪfɪˈkeɪʃən/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"An official award showing successful completion of education or training.","vi":"bằng cấp, chứng chỉ (chứng nhận hoàn thành chương trình học tập hoặc đào tạo)"},{"pos":"n.","en":"A skill or quality making someone suitable for a role.","vi":"năng lực, trình độ chuyên môn (kỹ năng hoặc phẩm chất phù hợp cho một vị trí)"},{"pos":"n.","en":"A condition that limits the meaning or acceptance of something.","vi":"điều kiện hạn chế, ý kiến bảo lưu (điều kiện làm giảm ý nghĩa hoặc sự chấp nhận của việc gì)"}],"examples":[{"en":"This qualification helped me find work at a nursery.","vi":"Chứng chỉ này đã giúp tôi tìm được việc làm tại một nhà trẻ.","audioKind":"ex"},{"en":"Employers increasingly value practical experience alongside formal qualifications when recruiting graduates for demanding professional roles.","vi":"Các nhà tuyển dụng ngày càng coi trọng kinh nghiệm thực tế bên cạnh các văn bằng chính thức khi tuyển dụng sinh viên tốt nghiệp cho các vị trí chuyên môn đòi hỏi khắt khe.","audioKind":"ex2"}],"collocations":[{"en":"academic qualifications","vi":"trình độ học vấn, bằng cấp"},{"en":"professional qualification","vi":"chứng chỉ nghề nghiệp"},{"en":"entry qualifications","vi":"điều kiện đầu vào"},{"en":"without qualification","vi":"không có sự bảo lưu, hoàn toàn"}],"wordFamily":["qualify (v.)","qualified (adj.)","unqualified (adj.)","qualifying (adj.)"],"synonyms":["credential"],"antonyms":[],"tipVi":"Khi nói về bằng cấp hoặc năng lực chuyên môn, người ta thường dùng hình thức số nhiều qualifications.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_maker', 'en-b1-32', 'maker', '/ˈmeɪkər/', 'B1', 'nhà sản xuất; hãng sản xuất; thợ thủ công', 'n.', 'make (v.), making (n.)', 'Đồng nghĩa: manufacturer, producer', 'Thường đi kèm tên sản phẩm; người đưa ra quyết định dùng decision maker.', 'The furniture maker carved a beautiful chair from oak.', NULL, 'Người thợ mộc đã đẽo gọt một chiếc ghế đẹp từ gỗ sồi.', '{"wordId":"maker","ukIpa":"/ˈmeɪkə/","usIpa":"/ˈmeɪkər/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"A person or company that produces something.","vi":"nhà sản xuất; hãng sản xuất; thợ thủ công"}],"examples":[{"en":"The furniture maker carved a beautiful chair from oak.","vi":"Người thợ mộc đã đẽo gọt một chiếc ghế đẹp từ gỗ sồi.","audioKind":"ex"},{"en":"Car makers are investing in cleaner technologies to meet stricter environmental standards and changing consumer expectations.","vi":"Các nhà sản xuất ô tô đang đầu tư vào các công nghệ sạch hơn để đáp ứng các tiêu chuẩn môi trường ngặt nghèo hơn và kỳ vọng ngày càng thay đổi của người tiêu dùng.","audioKind":"ex2"}],"collocations":[{"en":"furniture maker","vi":"thợ mộc; nhà sản xuất đồ nội thất"},{"en":"car maker","vi":"hãng sản xuất ô tô"},{"en":"decision maker","vi":"người ra quyết định; nhà hoạch định"}],"wordFamily":["make (v.)","making (n.)"],"synonyms":["manufacturer","producer"],"antonyms":[],"tipVi":"Thường đi kèm tên sản phẩm; người đưa ra quyết định dùng decision maker.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_agent', 'en-b1-32', 'agent', '/ˈeɪdʒənt/', 'B1', 'người đại diện; đại lý; điệp viên; mật vụ; tác nhân; chất xúc tác', 'n.', 'agency (n.)', 'Đồng nghĩa: representative', 'agent không chỉ có nghĩa là điệp viên; trong cleaning agent thì agent mang nghĩa là chất/tác nhân.', 'The travel agent found us a cheaper flight home.', NULL, 'Nhân viên du lịch đã tìm cho chúng tôi một chuyến bay về nhà giá rẻ hơn.', '{"wordId":"agent","ukIpa":"/ˈeɪdʒənt/","usIpa":"/ˈeɪdʒənt/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"A person or business acting on behalf of others","vi":"người đại diện; đại lý"},{"pos":"n.","en":"Someone secretly gathering information for a government or organisation","vi":"điệp viên; mật vụ"},{"pos":"n.","en":"A substance or force that produces a particular effect","vi":"tác nhân; chất xúc tác"}],"examples":[{"en":"The travel agent found us a cheaper flight home.","vi":"Nhân viên du lịch đã tìm cho chúng tôi một chuyến bay về nhà giá rẻ hơn.","audioKind":"ex"},{"en":"Local community groups can act as agents of change by encouraging residents to adopt more sustainable habits.","vi":"Các nhóm cộng đồng địa phương có thể đóng vai trò là tác nhân thay đổi bằng cách khuyến khích cư dân áp dụng các thói quen bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"travel agent","vi":"đại lý du lịch"},{"en":"estate agent","vi":"người môi giới bất động sản"},{"en":"cleaning agent","vi":"chất tẩy rửa"},{"en":"an agent of change","vi":"tác nhân đổi mới"}],"wordFamily":["agency (n.)"],"synonyms":["representative"],"antonyms":[],"tipVi":"agent không chỉ có nghĩa là điệp viên; trong cleaning agent thì agent mang nghĩa là chất/tác nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_workplace', 'en-b1-32', 'workplace', '/ˈwɝːkpleɪs/', 'B1', 'nơi làm việc; môi trường công sở', 'n.', 'work (n.), work (v.), worker (n.)', NULL, 'Chỉ chung chung các không gian làm việc như văn phòng, nhà xưởng, không đồng nhất với mỗi phòng làm việc riêng lẻ.', 'Our workplace has a quiet room for lunch breaks.', NULL, 'Nơi làm việc của chúng tôi có một phòng yên tĩnh để nghỉ trưa.', '{"wordId":"workplace","ukIpa":"/ˈwɜːkpleɪs/","usIpa":"/ˈwɝːkpleɪs/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"A place where people do their jobs.","vi":"nơi làm việc; môi trường công sở"}],"examples":[{"en":"Our workplace has a quiet room for lunch breaks.","vi":"Nơi làm việc của chúng tôi có một phòng yên tĩnh để nghỉ trưa.","audioKind":"ex"},{"en":"Creating an inclusive workplace helps employees feel valued and encourages cooperation among people from different backgrounds.","vi":"Xây dựng một môi trường làm việc hòa nhập giúp nhân viên cảm thấy được coi trọng và khuyến khích sự hợp tác giữa những người có hoàn cảnh khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"workplace safety","vi":"an toàn tại nơi làm việc"},{"en":"in the workplace","vi":"tại nơi làm việc"},{"en":"workplace culture","vi":"văn hóa công sở"},{"en":"workplace training","vi":"đào tạo tại nơi làm việc"}],"wordFamily":["work (n.)","work (v.)","worker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ chung chung các không gian làm việc như văn phòng, nhà xưởng, không đồng nhất với mỗi phòng làm việc riêng lẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_employment', 'en-b1-32', 'employment', '/ɪmˈplɔɪmənt/', 'B1', 'việc làm; sự tuyển dụng; tình trạng có việc làm; sự sử dụng; sự vận dụng cái gì cho mục đích cụ thể', 'n.', 'employ (v.), employee (n.), employer (n.), unemployment (n.)', 'Đồng nghĩa: work · Trái nghĩa: unemployment', 'Thường là danh từ không đếm được; một công việc cụ thể dùng a job, không dùng an employment.', 'She found employment at a bakery near her home.', NULL, 'Cô ấy đã tìm được việc làm tại một tiệm bánh gần nhà.', '{"wordId":"employment","ukIpa":"/ɪmˈplɔɪmənt/","usIpa":"/ɪmˈplɔɪmənt/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"paid work or the state of having a paid job","vi":"việc làm; sự tuyển dụng; tình trạng có việc làm"},{"pos":"n.","en":"the use of something for a particular purpose","vi":"sự sử dụng; sự vận dụng cái gì cho mục đích cụ thể"}],"examples":[{"en":"She found employment at a bakery near her home.","vi":"Cô ấy đã tìm được việc làm tại một tiệm bánh gần nhà.","audioKind":"ex"},{"en":"Investment in renewable energy can create employment opportunities while helping countries meet their climate targets.","vi":"Việc đầu tư vào năng lượng tái tạo có thể tạo ra các cơ hội việc làm đồng thời giúp các quốc gia đạt được các mục tiêu khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"employment opportunities","vi":"cơ hội việc làm"},{"en":"full-time employment","vi":"việc làm toàn thời gian"},{"en":"seek employment","vi":"tìm việc làm"},{"en":"employment rate","vi":"tỷ lệ có việc làm"}],"wordFamily":["employ (v.)","employee (n.)","employer (n.)","unemployment (n.)"],"synonyms":["work"],"antonyms":["unemployment"],"tipVi":"Thường là danh từ không đếm được; một công việc cụ thể dùng a job, không dùng an employment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_signed', 'en-b1-32', 'signed', '/saɪnd/', 'B1', 'đã ký; có chữ ký; ký tên (quá khứ và phân từ của sign)', 'adj.', 'sign (v.), signature (n.), unsigned (adj.), signatory (n.)', 'Trái nghĩa: unsigned', 'signed có thể làm tính từ; "được ký bởi ai" dùng signed by.', 'I put the signed form in a blue envelope.', NULL, 'Tôi đặt tờ đơn đã ký vào một phong bì màu xanh.', '{"wordId":"signed","ukIpa":"/saɪnd/","usIpa":"/saɪnd/","cefr":"B1","topic":"work","senses":[{"pos":"adj.","en":"bearing someone''s signature as proof of agreement or authorship","vi":"đã ký; có chữ ký"},{"pos":"v.","en":"wrote a signature to identify oneself or show agreement","vi":"ký tên (quá khứ và phân từ của sign)"}],"examples":[{"en":"I put the signed form in a blue envelope.","vi":"Tôi đặt tờ đơn đã ký vào một phong bì màu xanh.","audioKind":"ex"},{"en":"A signed agreement helps protect both tenants and landlords by clearly defining their rights and responsibilities.","vi":"Một bản thỏa thuận đã ký giúp bảo vệ cả người thuê nhà và chủ nhà bằng cách xác định rõ ràng quyền lợi và trách nhiệm của họ.","audioKind":"ex2"}],"collocations":[{"en":"a signed contract","vi":"hợp đồng đã ký"},{"en":"a signed copy","vi":"bản có chữ ký"},{"en":"a signed agreement","vi":"thỏa thuận đã ký kết"}],"wordFamily":["sign (v.)","signature (n.)","unsigned (adj.)","signatory (n.)"],"synonyms":[],"antonyms":["unsigned"],"tipVi":"signed có thể làm tính từ; \"được ký bởi ai\" dùng signed by.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_full-time', 'en-b1-32', 'full-time', '/ˌfʊl ˈtaɪm/', 'B1', 'toàn thời gian; toàn ngày; theo chế độ toàn thời gian', 'adj.', 'part-time (adj.)', 'Trái nghĩa: part-time', 'Khi bổ nghĩa cho danh từ cần giữ dấu gạch nối, ví dụ a full-time job.', 'My sister starts her first full-time job next week.', NULL, 'Chị gái tôi sẽ bắt đầu công việc toàn thời gian đầu tiên vào tuần tới.', '{"wordId":"full-time","ukIpa":"/ˌfʊl ˈtaɪm/","usIpa":"/ˌfʊl ˈtaɪm/","cefr":"B1","topic":"work","senses":[{"pos":"adj.","en":"involving all the usual working or studying hours","vi":"toàn thời gian; toàn ngày"},{"pos":"adv.","en":"for all the usual working or studying hours","vi":"theo chế độ toàn thời gian"}],"examples":[{"en":"My sister starts her first full-time job next week.","vi":"Chị gái tôi sẽ bắt đầu công việc toàn thời gian đầu tiên vào tuần tới.","audioKind":"ex"},{"en":"Affordable childcare enables more parents to return to full-time employment without placing excessive pressure on family finances.","vi":"Dịch vụ chăm sóc trẻ em với chi phí phải chăng giúp nhiều bậc cha mẹ có thể quay trở lại làm việc toàn thời gian mà không gây áp lực quá lớn cho tài chính gia đình.","audioKind":"ex2"}],"collocations":[{"en":"full-time employment","vi":"việc làm toàn thời gian"},{"en":"a full-time student","vi":"sinh viên học toàn thời gian"},{"en":"work full-time","vi":"làm việc toàn thời gian"}],"wordFamily":["part-time (adj.)"],"synonyms":[],"antonyms":["part-time"],"tipVi":"Khi bổ nghĩa cho danh từ cần giữ dấu gạch nối, ví dụ a full-time job.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conference', 'en-b1-32', 'conference', '/ˈkɑːnfərəns/', 'B1', 'hội nghị; hội thảo trang trọng để thảo luận về một chủ đề cụ thể', 'n.', 'conferencing (n.)', NULL, 'Chỉ các cuộc họp chính thức lớn; tham gia hội nghị dùng attend a conference.', 'Our hotel is hosting a conference for local teachers.', NULL, 'Khách sạn của chúng tôi đang tổ chức một hội nghị dành cho giáo viên địa phương.', '{"wordId":"conference","ukIpa":"/ˈkɒnfərəns/","usIpa":"/ˈkɑːnfərəns/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"a formal meeting to discuss a particular subject","vi":"hội nghị; hội thảo trang trọng để thảo luận về một chủ đề cụ thể"}],"examples":[{"en":"Our hotel is hosting a conference for local teachers.","vi":"Khách sạn của chúng tôi đang tổ chức một hội nghị dành cho giáo viên địa phương.","audioKind":"ex"},{"en":"At the international conference, researchers discussed how cities could reduce air pollution without limiting economic growth.","vi":"Tại hội nghị quốc tế, các nhà nghiên cứu đã thảo luận về việc các thành phố có thể giảm ô nhiễm không khí như thế nào mà không làm hạn chế tăng trưởng kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"attend a conference","vi":"tham dự hội nghị"},{"en":"hold a conference","vi":"tổ chức hội nghị"},{"en":"press conference","vi":"họp báo"},{"en":"conference venue","vi":"địa điểm hội nghị"}],"wordFamily":["conferencing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ các cuộc họp chính thức lớn; tham gia hội nghị dùng attend a conference.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_electrician', 'en-b1-32', 'electrician', '/ɪˌlekˈtrɪʃən/', 'B1', 'thợ điện; kỹ thuật viên điện', 'n.', 'electric (adj.), electrical (adj.), electricity (n.)', NULL, 'electrician chỉ thợ điện thực hành; còn kỹ sư điện là electrical engineer.', 'The electrician fixed the broken light in our kitchen.', NULL, 'Thợ điện đã sửa chiếc đèn bị hỏng trong nhà bếp của chúng tôi.', '{"wordId":"electrician","ukIpa":"/ɪˌlekˈtrɪʃən/","usIpa":"/ɪˌlekˈtrɪʃən/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"Someone trained to install and repair electrical systems.","vi":"thợ điện; kỹ thuật viên điện"}],"examples":[{"en":"The electrician fixed the broken light in our kitchen.","vi":"Thợ điện đã sửa chiếc đèn bị hỏng trong nhà bếp của chúng tôi.","audioKind":"ex"},{"en":"Training more qualified electricians is essential as households increasingly adopt solar panels and electric vehicle charging equipment.","vi":"Việc đào tạo thêm nhiều thợ điện có tay nghề là vô cùng quan trọng khi các hộ gia đình ngày càng lắp đặt nhiều pin mặt trời và thiết bị sạc xe điện.","audioKind":"ex2"}],"collocations":[{"en":"qualified electrician","vi":"thợ điện có tay nghề"},{"en":"apprentice electrician","vi":"thợ điện học việc"},{"en":"call an electrician","vi":"gọi thợ điện"}],"wordFamily":["electric (adj.)","electrical (adj.)","electricity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"electrician chỉ thợ điện thực hành; còn kỹ sư điện là electrical engineer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_target', 'en-b1-32', 'target', '/ˈtɑːrɡɪt/', 'B1', 'mục tiêu; chỉ tiêu; đối tượng hướng tới; đưa vào tầm ngắm; nhắm vào', 'n.', 'targeted (adj.)', 'Đồng nghĩa: goal, aim', 'Diễn đạt việc hoàn thành mục tiêu dùng meet hoặc reach a target.', 'My savings target is enough for a new bicycle.', NULL, 'Mục tiêu tiết kiệm của tôi là đủ để mua một chiếc xe đạp mới.', '{"wordId":"target","ukIpa":"/ˈtɑːɡɪt/","usIpa":"/ˈtɑːrɡɪt/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"A result or level that someone aims to achieve.","vi":"mục tiêu; chỉ tiêu"},{"pos":"n.","en":"A person or thing aimed at or attacked.","vi":"mục tiêu; đối tượng hướng tới"},{"pos":"v.","en":"To direct actions or attention towards a particular person or group.","vi":"đưa vào tầm ngắm; nhắm vào"}],"examples":[{"en":"My savings target is enough for a new bicycle.","vi":"Mục tiêu tiết kiệm của tôi là đủ để mua một chiếc xe đạp mới.","audioKind":"ex"},{"en":"Governments should set realistic targets for reducing emissions and regularly assess progress towards achieving them.","vi":"Chính phủ nên đặt ra các mục tiêu thiết thực về giảm phát thải và thường xuyên đánh giá tiến độ thực hiện.","audioKind":"ex2"}],"collocations":[{"en":"meet a target","vi":"đạt được mục tiêu"},{"en":"set a target","vi":"đặt ra mục tiêu"},{"en":"target audience","vi":"khán thính giả mục tiêu"},{"en":"target vulnerable groups","vi":"nhắm đến các nhóm dễ bị tổn thương"}],"wordFamily":["targeted (adj.)"],"synonyms":["goal","aim"],"antonyms":[],"tipVi":"Diễn đạt việc hoàn thành mục tiêu dùng meet hoặc reach a target.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_schedule', 'en-b1-32', 'schedule', '/ˈskedʒuːl/', 'B1', 'lịch trình; bản tiến độ; lên lịch; sắp xếp thời gian', 'n.', 'scheduled (adj.), scheduling (n.), reschedule (v.)', 'Đồng nghĩa: timetable', 'Cách phát âm Anh-Anh bắt đầu bằng âm /ʃ/, còn Anh-Mỹ là /sk/; cụm on schedule có nghĩa là đúng giờ dự kiến.', 'My busy schedule leaves little time for cooking during weekdays.', NULL, 'Lịch trình bận rộn của tôi khiến tôi có rất ít thời gian để nấu nướng vào các ngày trong tuần.', '{"wordId":"schedule","ukIpa":"/ˈʃedjuːl/","usIpa":"/ˈskedʒuːl/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"a plan showing when activities or events will happen","vi":"lịch trình; bản tiến độ"},{"pos":"v.","en":"to arrange for something to happen at a particular time","vi":"lên lịch; sắp xếp thời gian"}],"examples":[{"en":"My busy schedule leaves little time for cooking during weekdays.","vi":"Lịch trình bận rộn của tôi khiến tôi có rất ít thời gian để nấu nướng vào các ngày trong tuần.","audioKind":"ex"},{"en":"Universities should schedule examinations carefully to give students sufficient time for revision and recovery between assessments.","vi":"Các trường đại học nên sắp xếp lịch thi cẩn thận để sinh viên có đủ thời gian ôn tập và nghỉ ngơi giữa các kỳ kiểm tra.","audioKind":"ex2"}],"collocations":[{"en":"a busy schedule","vi":"lịch trình bận rộn"},{"en":"on schedule","vi":"đúng tiến độ"},{"en":"ahead of schedule","vi":"trước thời hạn"},{"en":"schedule a meeting","vi":"lên lịch cuộc họp"}],"wordFamily":["scheduled (adj.)","scheduling (n.)","reschedule (v.)"],"synonyms":["timetable"],"antonyms":[],"tipVi":"Cách phát âm Anh-Anh bắt đầu bằng âm /ʃ/, còn Anh-Mỹ là /sk/; cụm on schedule có nghĩa là đúng giờ dự kiến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_professional', 'en-b1-32', 'professional', '/prəˈfeʃənəl/', 'B1', 'thuộc chuyên môn; chuyên nghiệp; có tác phong chuyên nghiệp; làm việc chuẩn mực; chuyên gia; vận động viên chuyên nghiệp', 'adj.', 'profession (n.), professionally (adv.), professionalism (n.), unprofessional (adj.)', 'Trái nghĩa: amateur, unprofessional', 'Khi đối lập với amateur, từ này nhấn mạnh tính nghề nghiệp; khi nói về thái độ, nó nhấn mạnh sự chuyên nghiệp, chuẩn mực.', 'We hired a professional photographer for our wedding.', NULL, 'Chúng tôi đã thuê một nhiếp ảnh gia chuyên nghiệp cho đám cưới của mình.', '{"wordId":"professional","ukIpa":"/prəˈfeʃənəl/","usIpa":"/prəˈfeʃənəl/","cefr":"B1","topic":"work","senses":[{"pos":"adj.","en":"Relating to skilled work or an activity done for payment.","vi":"thuộc chuyên môn; chuyên nghiệp"},{"pos":"adj.","en":"Showing the skill and behaviour expected of a trained worker.","vi":"có tác phong chuyên nghiệp; làm việc chuẩn mực"},{"pos":"n.","en":"Someone trained for skilled work or paid to perform.","vi":"chuyên gia; vận động viên chuyên nghiệp"}],"examples":[{"en":"We hired a professional photographer for our wedding.","vi":"Chúng tôi đã thuê một nhiếp ảnh gia chuyên nghiệp cho đám cưới của mình.","audioKind":"ex"},{"en":"Continuous professional development helps teachers adapt their methods to changing student needs and new educational technologies.","vi":"Sự phát triển chuyên môn liên tục giúp giáo viên thích ứng các phương pháp của họ với nhu cầu thay đổi của học sinh và các công nghệ giáo dục mới.","audioKind":"ex2"}],"collocations":[{"en":"professional advice","vi":"lời khuyên chuyên môn"},{"en":"professional development","vi":"phát triển chuyên môn"},{"en":"professional athlete","vi":"vận động viên chuyên nghiệp"},{"en":"healthcare professional","vi":"chuyên gia y tế"}],"wordFamily":["profession (n.)","professionally (adv.)","professionalism (n.)","unprofessional (adj.)"],"synonyms":[],"antonyms":["amateur","unprofessional"],"tipVi":"Khi đối lập với amateur, từ này nhấn mạnh tính nghề nghiệp; khi nói về thái độ, nó nhấn mạnh sự chuyên nghiệp, chuẩn mực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fisherman', 'en-b1-32', 'fisherman', '/ˈfɪʃərmən/', 'B1', 'người đánh cá; thợ câu cá', 'n.', 'fish (n.), fish (v.), fishing (n.), fishery (n.)', 'Đồng nghĩa: fisher', 'Dạng số nhiều là fishermen; có thể dùng từ trung tính là fisher.', 'The fisherman pulled his net onto the wooden boat.', NULL, 'Người ngư dân kéo lưới lên chiếc thuyền gỗ.', '{"wordId":"fisherman","ukIpa":"/ˈfɪʃəmən/","usIpa":"/ˈfɪʃərmən/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"someone who catches fish for work or pleasure","vi":"người đánh cá; thợ câu cá"}],"examples":[{"en":"The fisherman pulled his net onto the wooden boat.","vi":"Người ngư dân kéo lưới lên chiếc thuyền gỗ.","audioKind":"ex"},{"en":"Each fisherman in the coastal village depends on healthy marine ecosystems to maintain a reliable income.","vi":"Mỗi người ngư dân ở ngôi làng ven biển đều phụ thuộc vào hệ sinh thái biển khỏe mạnh để duy trì nguồn thu nhập ổn định.","audioKind":"ex2"}],"collocations":[{"en":"local fishermen","vi":"ngư dân địa phương"},{"en":"commercial fishermen","vi":"ngư dân đánh bắt thương mại"},{"en":"a fishing boat","vi":"thuyền đánh cá"}],"wordFamily":["fish (n.)","fish (v.)","fishing (n.)","fishery (n.)"],"synonyms":["fisher"],"antonyms":[],"tipVi":"Dạng số nhiều là fishermen; có thể dùng từ trung tính là fisher.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wage', 'en-b1-32', 'wage', '/weɪdʒ/', 'B1', 'tiền lương; tiền công (thường tính theo giờ hoặc tuần); tiến hành; phát động (chiến tranh hoặc chiến dịch)', 'n.', 'wages (n.), wage-earner (n.)', 'Đồng nghĩa: pay', 'wage thường tính theo giờ hoặc tuần; salary thường chỉ tiền lương cố định.', 'The café pays a decent wage for weekend work.', NULL, 'Quán cà phê trả mức lương khá cho ca làm việc cuối tuần.', '{"wordId":"wage","ukIpa":"/weɪdʒ/","usIpa":"/weɪdʒ/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"money earned for work, often calculated by the hour or week","vi":"tiền lương; tiền công (thường tính theo giờ hoặc tuần)"},{"pos":"v.","en":"to carry on a war or organised campaign","vi":"tiến hành; phát động (chiến tranh hoặc chiến dịch)"}],"examples":[{"en":"The café pays a decent wage for weekend work.","vi":"Quán cà phê trả mức lương khá cho ca làm việc cuối tuần.","audioKind":"ex"},{"en":"Raising the minimum wage may improve living standards, but small businesses could face higher operating costs.","vi":"Việc tăng mức lương tối thiểu có thể nâng cao mức sống, nhưng các doanh nghiệp nhỏ có thể phải đối mặt với chi phí vận hành cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"minimum wage","vi":"lương tối thiểu"},{"en":"earn a wage","vi":"kiếm tiền lương"},{"en":"wage increase","vi":"tăng lương"},{"en":"wage a campaign","vi":"phát động một chiến dịch"}],"wordFamily":["wages (n.)","wage-earner (n.)"],"synonyms":["pay"],"antonyms":[],"tipVi":"wage thường tính theo giờ hoặc tuần; salary thường chỉ tiền lương cố định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_time-off', 'en-b1-32', 'time off', '/ˌtaɪm ˈɔːf/', 'B1', 'thời gian nghỉ ngơi; thời gian nghỉ việc/nghỉ học', 'n.', NULL, NULL, 'Cụm này thường không đếm được; nếu muốn nói nghỉ một ngày, bạn dùng take a day off.', 'I need some time off to visit my grandparents.', NULL, 'Tôi cần xin nghỉ vài ngày để về thăm ông bà.', '{"wordId":"time-off","ukIpa":"/ˌtaɪm ˈɒf/","usIpa":"/ˌtaɪm ˈɔːf/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"Time when you are not working or attending school.","vi":"thời gian nghỉ ngơi; thời gian nghỉ việc/nghỉ học"}],"examples":[{"en":"I need some time off to visit my grandparents.","vi":"Tôi cần xin nghỉ vài ngày để về thăm ông bà.","audioKind":"ex"},{"en":"Providing paid time off can improve employee wellbeing and reduce stress in the workplace.","vi":"Việc cung cấp chế độ nghỉ có lương giúp cải thiện sức khỏe tinh thần của nhân viên và giảm bớt áp lực nơi công sở.","audioKind":"ex2"}],"collocations":[{"en":"take time off","vi":"xin nghỉ; nghỉ ngơi"},{"en":"paid time off","vi":"thời gian nghỉ có lương"},{"en":"time off work","vi":"thời gian nghỉ làm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm này thường không đếm được; nếu muốn nói nghỉ một ngày, bạn dùng take a day off.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_responsible', 'en-b1-32', 'responsible', '/rɪˈspɑːnsəbl/', 'B1', 'chịu trách nhiệm; có trách nhiệm quản lý; gây ra việc gì (thường là tiêu cực); là thủ phạm; đáng tin cậy; có tinh thần trách nhiệm', 'adj.', 'responsibility (n.), responsibly (adv.), irresponsible (adj.), irresponsibly (adv.)', 'Đồng nghĩa: accountable, reliable · Trái nghĩa: irresponsible', 'Sau responsible for đi với danh từ hoặc danh động từ; đi với giới từ to khi chỉ người quản lý cấp trên.', 'I''m responsible for feeding our cat every morning.', NULL, 'Tôi chịu trách nhiệm cho ăn mỗi sáng đối với con mèo nhà mình.', '{"wordId":"responsible","ukIpa":"/rɪˈspɒnsəbl/","usIpa":"/rɪˈspɑːnsəbl/","cefr":"B1","topic":"work","senses":[{"pos":"adj.","en":"having a duty to manage or look after something","vi":"chịu trách nhiệm; có trách nhiệm quản lý"},{"pos":"adj.","en":"being the cause of something, especially something bad","vi":"gây ra việc gì (thường là tiêu cực); là thủ phạm"},{"pos":"adj.","en":"sensible and trustworthy in your actions and decisions","vi":"đáng tin cậy; có tinh thần trách nhiệm"}],"examples":[{"en":"I''m responsible for feeding our cat every morning.","vi":"Tôi chịu trách nhiệm cho ăn mỗi sáng đối với con mèo nhà mình.","audioKind":"ex"},{"en":"Governments are responsible for ensuring that all children have access to safe and affordable education.","vi":"Chính phủ có trách nhiệm đảm bảo mọi trẻ em đều được tiếp cận nền giáo dục an toàn và vừa túi tiền.","audioKind":"ex2"}],"collocations":[{"en":"responsible for","vi":"chịu trách nhiệm về"},{"en":"responsible behaviour","vi":"hành vi có trách nhiệm"},{"en":"hold someone responsible","vi":"bắt ai đó phải chịu trách nhiệm"}],"wordFamily":["responsibility (n.)","responsibly (adv.)","irresponsible (adj.)","irresponsibly (adv.)"],"synonyms":["accountable","reliable"],"antonyms":["irresponsible"],"tipVi":"Sau responsible for đi với danh từ hoặc danh động từ; đi với giới từ to khi chỉ người quản lý cấp trên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pressure', 'en-b1-32', 'pressure', '/ˈpreʃər/', 'B1', 'áp lực (tinh thần); sự thúc ép; áp suất; sức ép; gây áp lực; ép buộc', 'n.', 'press (v.), pressurise (v.), pressurised (adj.)', NULL, 'under pressure diễn tả tình trạng chịu áp lực; động từ thường đi với giới từ into doing.', 'I feel pressure to answer work messages immediately.', NULL, 'Tôi cảm thấy có áp lực phải trả lời tin nhắn công việc ngay lập tức.', '{"wordId":"pressure","ukIpa":"/ˈpreʃə/","usIpa":"/ˈpreʃər/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"Worry or demands that make someone feel forced to act","vi":"áp lực (tinh thần); sự thúc ép"},{"pos":"n.","en":"Force pressing on a surface or within a substance","vi":"áp suất; sức ép"},{"pos":"v.","en":"Try to make someone do something through strong persuasion","vi":"gây áp lực; ép buộc"}],"examples":[{"en":"I feel pressure to answer work messages immediately.","vi":"Tôi cảm thấy có áp lực phải trả lời tin nhắn công việc ngay lập tức.","audioKind":"ex"},{"en":"Employers should avoid putting excessive pressure on staff, as this can damage both health and productivity.","vi":"Người sử dụng lao động nên tránh gây áp lực quá mức cho nhân viên vì điều này có thể làm tổn hại đến cả sức khỏe lẫn năng suất làm việc.","audioKind":"ex2"}],"collocations":[{"en":"under pressure","vi":"chịu áp lực"},{"en":"put pressure on","vi":"gây áp lực lên"},{"en":"blood pressure","vi":"huyết áp"},{"en":"pressure someone into doing something","vi":"gây sức ép buộc ai làm gì"}],"wordFamily":["press (v.)","pressurise (v.)","pressurised (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"under pressure diễn tả tình trạng chịu áp lực; động từ thường đi với giới từ into doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_effort', 'en-b1-32', 'effort', '/ˈefərt/', 'B1', 'năng lượng thể chất hoặc tinh thần bỏ ra để đạt được điều gì đó; sự nỗ lực; công sức; một nỗ lực hoặc hoạt động có tổ chức nhằm đạt được mục tiêu', 'n.', 'effortless (adj.), effortlessly (adv.)', 'Đồng nghĩa: exertion, attempt', 'Khi chỉ năng lượng thì từ này không đếm được; khi chỉ một lần cố gắng thì đếm được.', 'It took considerable effort to push the sofa upstairs.', NULL, 'Phải mất rất nhiều công sức mới đẩy được chiếc sofa lên lầu.', '{"wordId":"effort","ukIpa":"/ˈefət/","usIpa":"/ˈefərt/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"physical or mental energy used to achieve something","vi":"năng lượng thể chất hoặc tinh thần bỏ ra để đạt được điều gì đó; sự nỗ lực; công sức"},{"pos":"n.","en":"an attempt or organised activity intended to achieve a goal","vi":"một nỗ lực hoặc hoạt động có tổ chức nhằm đạt được mục tiêu"}],"examples":[{"en":"It took considerable effort to push the sofa upstairs.","vi":"Phải mất rất nhiều công sức mới đẩy được chiếc sofa lên lầu.","audioKind":"ex"},{"en":"Reducing household waste requires a joint effort from consumers, manufacturers and local authorities to change everyday practices.","vi":"Việc giảm thiểu rác thải sinh hoạt đòi hỏi sự nỗ lực chung từ người tiêu dùng, nhà sản xuất và chính quyền địa phương để thay đổi thói quen hằng ngày.","audioKind":"ex2"}],"collocations":[{"en":"make an effort","vi":"nỗ lực"},{"en":"put effort into","vi":"dồn tâm sức vào"},{"en":"a joint effort","vi":"nỗ lực chung"},{"en":"considerable effort","vi":"nỗ lực đáng kể"}],"wordFamily":["effortless (adj.)","effortlessly (adv.)"],"synonyms":["exertion","attempt"],"antonyms":[],"tipVi":"Khi chỉ năng lượng thì từ này không đếm được; khi chỉ một lần cố gắng thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_submit', 'en-b1-32', 'submit', '/səbˈmɪt/', 'B1', 'gửi một tài liệu hoặc đơn từ để được xem xét; nộp; trình; chấp nhận quyền lực hoặc sự kiểm soát của người khác; khuất phục; quy phục', 'v.', 'submission (n.), submissive (adj.)', NULL, 'Quá khứ là submitted; cấu trúc submit sth to sb có nghĩa là nộp cái gì cho ai.', 'Please submit your application before the end of Friday.', NULL, 'Xin vui lòng nộp hồ sơ của bạn trước khi kết thúc ngày thứ Sáu.', '{"wordId":"submit","ukIpa":"/səbˈmɪt/","usIpa":"/səbˈmɪt/","cefr":"B1","topic":"work","senses":[{"pos":"v.","en":"To send a document or application for consideration","vi":"gửi một tài liệu hoặc đơn từ để được xem xét; nộp; trình"},{"pos":"v.","en":"To accept another person''s authority or control","vi":"chấp nhận quyền lực hoặc sự kiểm soát của người khác; khuất phục; quy phục"}],"examples":[{"en":"Please submit your application before the end of Friday.","vi":"Xin vui lòng nộp hồ sơ của bạn trước khi kết thúc ngày thứ Sáu.","audioKind":"ex"},{"en":"Researchers must submit their findings for independent review before these can be published in reputable academic journals.","vi":"Các nhà nghiên cứu bắt buộc phải nộp các phát hiện của họ để được thẩm định độc lập trước khi chúng có thể được xuất bản trên các tạp chí học thuật có uy tín.","audioKind":"ex2"}],"collocations":[{"en":"submit an application","vi":"nộp đơn"},{"en":"submit a report","vi":"nộp báo cáo"},{"en":"submit something to","vi":"nộp cái gì cho ai"},{"en":"submit to authority","vi":"phục tùng quyền lực"}],"wordFamily":["submission (n.)","submissive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ là submitted; cấu trúc submit sth to sb có nghĩa là nộp cái gì cho ai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_performance', 'en-b1-32', 'performance', '/pərˈfɔːrməns/', 'B1', 'hiệu suất; thành tích; hiệu năng; buổi biểu diễn; màn trình diễn; sự thực hiện; sự thi hành', 'n.', 'perform (v.), performer (n.)', NULL, 'Nghĩa chỉ hiệu suất hoặc sự thể hiện chung thường không đếm được; trong khi một buổi biểu diễn cụ thể dùng a performance.', 'The coach praised our performance after the football match.', NULL, 'Huấn luyện viên đã ca ngợi màn thể hiện của chúng tôi sau trận đấu bóng đá.', '{"wordId":"performance","ukIpa":"/pəˈfɔːməns/","usIpa":"/pərˈfɔːrməns/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"How well a person, organisation or machine does something.","vi":"hiệu suất; thành tích; hiệu năng"},{"pos":"n.","en":"An occasion when someone entertains an audience by performing.","vi":"buổi biểu diễn; màn trình diễn"},{"pos":"n.","en":"The act of carrying out a task or duty.","vi":"sự thực hiện; sự thi hành"}],"examples":[{"en":"The coach praised our performance after the football match.","vi":"Huấn luyện viên đã ca ngợi màn thể hiện của chúng tôi sau trận đấu bóng đá.","audioKind":"ex"},{"en":"Regular feedback can improve employee performance by helping workers understand expectations and address specific weaknesses.","vi":"Phản hồi thường xuyên có thể cải thiện hiệu suất làm việc của nhân viên bằng cách giúp họ hiểu rõ kỳ vọng và khắc phục những điểm yếu cụ thể.","audioKind":"ex2"}],"collocations":[{"en":"academic performance","vi":"thành tích học tập"},{"en":"job performance","vi":"hiệu suất công việc"},{"en":"live performance","vi":"buổi biểu diễn trực tiếp"},{"en":"performance of duties","vi":"việc thực hiện nhiệm vụ"}],"wordFamily":["perform (v.)","performer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa chỉ hiệu suất hoặc sự thể hiện chung thường không đếm được; trong khi một buổi biểu diễn cụ thể dùng a performance.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_maid', 'en-b1-32', 'maid', '/meɪd/', 'B1', 'nữ nhân viên dọn phòng; nữ giúp việc', 'n.', NULL, NULL, 'Chỉ người giúp việc nữ hoặc nhân viên vệ sinh; ở khách sạn thường dùng room attendant.', 'The hotel maid brought fresh towels to our room.', NULL, 'Nữ nhân viên dọn phòng của khách sạn đã đem khăn tắm sạch đến phòng chúng tôi.', '{"wordId":"maid","ukIpa":"/meɪd/","usIpa":"/meɪd/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"a woman employed to clean rooms or do household work","vi":"nữ nhân viên dọn phòng; nữ giúp việc"}],"examples":[{"en":"The hotel maid brought fresh towels to our room.","vi":"Nữ nhân viên dọn phòng của khách sạn đã đem khăn tắm sạch đến phòng chúng tôi.","audioKind":"ex"},{"en":"Hotels should provide every maid with suitable equipment and sufficient time to clean rooms safely.","vi":"Khách sạn nên trang bị cho mỗi nữ nhân viên dọn phòng các thiết bị phù hợp cùng thời gian đầy đủ để dọn dẹp phòng một cách an toàn.","audioKind":"ex2"}],"collocations":[{"en":"hotel maid","vi":"nữ nhân viên dọn phòng khách sạn"},{"en":"work as a maid","vi":"làm nghề giúp việc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ người giúp việc nữ hoặc nhân viên vệ sinh; ở khách sạn thường dùng room attendant.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accountant', 'en-b1-32', 'accountant', '/əˈkaʊntənt/', 'B1', 'kế toán; kiểm toán viên', 'n.', 'account (n.), accounting (n.), accountancy (n.)', NULL, 'Accountant chỉ người làm kế toán; accounting chỉ ngành nghề hoặc công tác kế toán.', 'The accountant checked our expenses before we opened the café.', NULL, 'Nhà kế toán đã kiểm tra các khoản chi phí của chúng tôi trước khi quán cà phê đi vào hoạt động.', '{"wordId":"accountant","ukIpa":"/əˈkaʊntənt/","usIpa":"/əˈkaʊntənt/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"Someone whose job is to prepare and check financial records","vi":"kế toán; kiểm toán viên"}],"examples":[{"en":"The accountant checked our expenses before we opened the café.","vi":"Nhà kế toán đã kiểm tra các khoản chi phí của chúng tôi trước khi quán cà phê đi vào hoạt động.","audioKind":"ex"},{"en":"Employing a qualified accountant helps small businesses manage taxes accurately and make better financial decisions.","vi":"Việc thuê một kế toán có chuyên môn giúp các doanh nghiệp nhỏ xử lý thuế chính xác và đưa ra các quyết định tài chính tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"qualified accountant","vi":"kế toán có chứng chỉ hành nghề"},{"en":"chartered accountant","vi":"kế toán viên công chứng"},{"en":"hire an accountant","vi":"thuê kế toán"}],"wordFamily":["account (n.)","accounting (n.)","accountancy (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Accountant chỉ người làm kế toán; accounting chỉ ngành nghề hoặc công tác kế toán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_typist', 'en-b1-32', 'typist', '/ˈtaɪpɪst/', 'B1', 'thợ đánh máy; nhân viên đánh máy', 'n.', 'type (v.), typing (n.), typewriter (n.)', NULL, 'Chỉ người làm nghề dùng typist; typing chỉ hoạt động đánh máy, còn typewriter là máy đánh máy.', 'The typist finished the letter before her lunch break.', NULL, 'Nhân viên đánh máy đã hoàn thành bức thư trước giờ nghỉ trưa.', '{"wordId":"typist","ukIpa":"/ˈtaɪpɪst/","usIpa":"/ˈtaɪpɪst/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"A person who types, especially as a job.","vi":"thợ đánh máy; nhân viên đánh máy"}],"examples":[{"en":"The typist finished the letter before her lunch break.","vi":"Nhân viên đánh máy đã hoàn thành bức thư trước giờ nghỉ trưa.","audioKind":"ex"},{"en":"Although dedicated typist positions are less common today, accurate keyboard skills remain valuable in many workplaces.","vi":"Mặc dù các vị trí chuyên trách đánh máy nay ít phổ biến hơn, kỹ năng gõ phím chuẩn xác vẫn rất có giá trị ở nhiều nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"a fast typist","vi":"người đánh máy nhanh"},{"en":"a skilled typist","vi":"nhân viên đánh máy thành thạo"},{"en":"a touch typist","vi":"người gõ bàn phím mù (không nhìn bàn phím)"}],"wordFamily":["type (v.)","typing (n.)","typewriter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ người làm nghề dùng typist; typing chỉ hoạt động đánh máy, còn typewriter là máy đánh máy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mechanic', 'en-b1-32', 'mechanic', '/məˈkænɪk/', 'B1', 'thợ sửa chữa; thợ máy', 'n.', 'mechanical (adj.), mechanically (adv.), mechanics (n.)', NULL, 'mechanic chỉ người thợ sửa chữa; mechanics có thể chỉ ngành cơ khí hoặc môn lực học.', 'The mechanic found a leak under our car.', NULL, 'Thợ sửa chữa đã tìm thấy một chỗ rò rỉ dưới gầm xe của chúng tôi.', '{"wordId":"mechanic","ukIpa":"/məˈkænɪk/","usIpa":"/məˈkænɪk/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"Someone whose job is repairing vehicles or machines.","vi":"thợ sửa chữa; thợ máy"}],"examples":[{"en":"The mechanic found a leak under our car.","vi":"Thợ sửa chữa đã tìm thấy một chỗ rò rỉ dưới gầm xe của chúng tôi.","audioKind":"ex"},{"en":"As electric vehicles become more common, mechanics need additional training to maintain their complex systems safely.","vi":"Khi xe điện trở nên phổ biến hơn, các thợ sửa chữa cần được đào tạo thêm để bảo dưỡng hệ thống phức tạp của chúng một cách an toàn.","audioKind":"ex2"}],"collocations":[{"en":"car mechanic","vi":"thợ sửa ô tô"},{"en":"a qualified mechanic","vi":"thợ cơ khí có tay nghề"},{"en":"work as a mechanic","vi":"làm thợ sửa chữa"}],"wordFamily":["mechanical (adj.)","mechanically (adv.)","mechanics (n.)"],"synonyms":[],"antonyms":[],"tipVi":"mechanic chỉ người thợ sửa chữa; mechanics có thể chỉ ngành cơ khí hoặc môn lực học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_32_1', 'en-b1-32', 'Cách dùng “professional” (adj.) — thuộc chuyên môn; chuyên nghiệp', 'professional advice  ·  professional development  ·  professional athlete', 'Khi đối lập với amateur, từ này nhấn mạnh tính nghề nghiệp; khi nói về thái độ, nó nhấn mạnh sự chuyên nghiệp, chuẩn mực.', 'Họ từ (Word Family): profession (n.), professionally (adv.), professionalism (n.), unprofessional (adj.) | Trái nghĩa: amateur, unprofessional', '[{"hanzi":"We hired a professional photographer for our wedding.","pinyin":"","meaning":"Chúng tôi đã thuê một nhiếp ảnh gia chuyên nghiệp cho đám cưới của mình."},{"hanzi":"Continuous professional development helps teachers adapt their methods to changing student needs and new educational technologies.","pinyin":"","meaning":"Sự phát triển chuyên môn liên tục giúp giáo viên thích ứng các phương pháp của họ với nhu cầu thay đổi của học sinh và các công nghệ giáo dục mới."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_32_2', 'en-b1-32', 'Cách dùng “performance” (n.) — hiệu suất; thành tích; hiệu năng', 'academic performance  ·  job performance  ·  live performance', 'Nghĩa chỉ hiệu suất hoặc sự thể hiện chung thường không đếm được; trong khi một buổi biểu diễn cụ thể dùng a performance.', 'Họ từ (Word Family): perform (v.), performer (n.)', '[{"hanzi":"The coach praised our performance after the football match.","pinyin":"","meaning":"Huấn luyện viên đã ca ngợi màn thể hiện của chúng tôi sau trận đấu bóng đá."},{"hanzi":"Regular feedback can improve employee performance by helping workers understand expectations and address specific weaknesses.","pinyin":"","meaning":"Phản hồi thường xuyên có thể cải thiện hiệu suất làm việc của nhân viên bằng cách giúp họ hiểu rõ kỳ vọng và khắc phục những điểm yếu cụ thể."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_32_3', 'en-b1-32', 'Cách dùng “workplace” (n.) — nơi làm việc; môi trường công sở', 'workplace safety  ·  in the workplace  ·  workplace culture', 'Chỉ chung chung các không gian làm việc như văn phòng, nhà xưởng, không đồng nhất với mỗi phòng làm việc riêng lẻ.', 'Họ từ (Word Family): work (n.), work (v.), worker (n.)', '[{"hanzi":"Our workplace has a quiet room for lunch breaks.","pinyin":"","meaning":"Nơi làm việc của chúng tôi có một phòng yên tĩnh để nghỉ trưa."},{"hanzi":"Creating an inclusive workplace helps employees feel valued and encourages cooperation among people from different backgrounds.","pinyin":"","meaning":"Xây dựng một môi trường làm việc hòa nhập giúp nhân viên cảm thấy được coi trọng và khuyến khích sự hợp tác giữa những người có hoàn cảnh khác nhau."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_32_4', 'en-b1-32', 'Cách dùng “schedule” (n.) — lịch trình; bản tiến độ', 'a busy schedule  ·  on schedule  ·  ahead of schedule', 'Cách phát âm Anh-Anh bắt đầu bằng âm /ʃ/, còn Anh-Mỹ là /sk/; cụm on schedule có nghĩa là đúng giờ dự kiến.', 'Họ từ (Word Family): scheduled (adj.), scheduling (n.), reschedule (v.) | Đồng nghĩa: timetable', '[{"hanzi":"My busy schedule leaves little time for cooking during weekdays.","pinyin":"","meaning":"Lịch trình bận rộn của tôi khiến tôi có rất ít thời gian để nấu nướng vào các ngày trong tuần."},{"hanzi":"Universities should schedule examinations carefully to give students sufficient time for revision and recovery between assessments.","pinyin":"","meaning":"Các trường đại học nên sắp xếp lịch thi cẩn thận để sinh viên có đủ thời gian ôn tập và nghỉ ngơi giữa các kỳ kiểm tra."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_32_1', 'en-b1-32', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
