INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_32_1_5', 'ten_b1_32_1', 'employment', 'She found employment at a bakery near her home.', 'She found employment at a bakery near her home.', '/ɪmˈplɔɪmənt/', 'Cô ấy đã tìm được việc làm tại một tiệm bánh gần nhà.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_32_1_6', 'ten_b1_32_1', 'signed', 'I put the signed form in a blue envelope.', 'I put the signed form in a blue envelope.', '/saɪnd/', 'Tôi đặt tờ đơn đã ký vào một phong bì màu xanh.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_32_1_7', 'ten_b1_32_1', 'full-time', 'My sister starts her first full-time job next week.', 'My sister starts her first full-time job next week.', '/ˌfʊl ˈtaɪm/', 'Chị gái tôi sẽ bắt đầu công việc toàn thời gian đầu tiên vào tuần tới.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_32_1_8', 'ten_b1_32_1', 'conference', 'Our hotel is hosting a conference for local teachers.', 'Our hotel is hosting a conference for local teachers.', '/ˈkɑːnfərəns/', 'Khách sạn của chúng tôi đang tổ chức một hội nghị dành cho giáo viên địa phương.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_32_1_1', 'en-b1-32', 'ten_b1_32_1', 'listening', 'listening', 'This qualification helped me find work at a nursery.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chứng chỉ này đã giúp tôi tìm được việc làm tại một nhà trẻ.","Tôi cảm thấy có áp lực phải trả lời tin nhắn công việc ngay lập tức.","Chị gái tôi sẽ bắt đầu công việc toàn thời gian đầu tiên vào tuần tới.","Tôi cần xin nghỉ vài ngày để về thăm ông bà."]'::jsonb, 0, 'This qualification helped me find work at a nursery. → Chứng chỉ này đã giúp tôi tìm được việc làm tại một nhà trẻ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_32_1_2', 'en-b1-32', 'ten_b1_32_1', 'listening', 'listening', 'The furniture maker carved a beautiful chair from oak.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Huấn luyện viên đã ca ngợi màn thể hiện của chúng tôi sau trận đấu bóng đá.","Mục tiêu tiết kiệm của tôi là đủ để mua một chiếc xe đạp mới.","Thợ sửa chữa đã tìm thấy một chỗ rò rỉ dưới gầm xe của chúng tôi.","Người thợ mộc đã đẽo gọt một chiếc ghế đẹp từ gỗ sồi."]'::jsonb, 3, 'The furniture maker carved a beautiful chair from oak. → Người thợ mộc đã đẽo gọt một chiếc ghế đẹp từ gỗ sồi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_32_1_3', 'en-b1-32', 'ten_b1_32_1', 'listening', 'listening', 'The travel agent found us a cheaper flight home.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người thợ mộc đã đẽo gọt một chiếc ghế đẹp từ gỗ sồi.","Thợ điện đã sửa chiếc đèn bị hỏng trong nhà bếp của chúng tôi.","Nơi làm việc của chúng tôi có một phòng yên tĩnh để nghỉ trưa.","Nhân viên du lịch đã tìm cho chúng tôi một chuyến bay về nhà giá rẻ hơn."]'::jsonb, 3, 'The travel agent found us a cheaper flight home. → Nhân viên du lịch đã tìm cho chúng tôi một chuyến bay về nhà giá rẻ hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_32_2', 'en-b1-32', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_32_2_1', 'ten_b1_32_2', 'qualification', 'Employers increasingly value practical experience alongside formal qualifications when recruiting graduates for demanding professional roles.', 'Employers increasingly value practical experience alongside formal qualifications when recruiting graduates for demanding professional roles.', '/ˌkwɑːlɪfɪˈkeɪʃən/', 'Các nhà tuyển dụng ngày càng coi trọng kinh nghiệm thực tế bên cạnh các văn bằng chính thức khi tuyển dụng sinh viên tốt nghiệp cho các vị trí chuyên môn đòi hỏi khắt khe.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_32_2_2', 'ten_b1_32_2', 'maker', 'Car makers are investing in cleaner technologies to meet stricter environmental standards and changing consumer expectations.', 'Car makers are investing in cleaner technologies to meet stricter environmental standards and changing consumer expectations.', '/ˈmeɪkər/', 'Các nhà sản xuất ô tô đang đầu tư vào các công nghệ sạch hơn để đáp ứng các tiêu chuẩn môi trường ngặt nghèo hơn và kỳ vọng ngày càng thay đổi của người tiêu dùng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_32_2_3', 'ten_b1_32_2', 'agent', 'Local community groups can act as agents of change by encouraging residents to adopt more sustainable habits.', 'Local community groups can act as agents of change by encouraging residents to adopt more sustainable habits.', '/ˈeɪdʒənt/', 'Các nhóm cộng đồng địa phương có thể đóng vai trò là tác nhân thay đổi bằng cách khuyến khích cư dân áp dụng các thói quen bền vững hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_32_2_4', 'ten_b1_32_2', 'workplace', 'Creating an inclusive workplace helps employees feel valued and encourages cooperation among people from different backgrounds.', 'Creating an inclusive workplace helps employees feel valued and encourages cooperation among people from different backgrounds.', '/ˈwɝːkpleɪs/', 'Xây dựng một môi trường làm việc hòa nhập giúp nhân viên cảm thấy được coi trọng và khuyến khích sự hợp tác giữa những người có hoàn cảnh khác nhau.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_32_2_5', 'ten_b1_32_2', 'employment', 'Investment in renewable energy can create employment opportunities while helping countries meet their climate targets.', 'Investment in renewable energy can create employment opportunities while helping countries meet their climate targets.', '/ɪmˈplɔɪmənt/', 'Việc đầu tư vào năng lượng tái tạo có thể tạo ra các cơ hội việc làm đồng thời giúp các quốc gia đạt được các mục tiêu khí hậu.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_32_2_6', 'ten_b1_32_2', 'signed', 'A signed agreement helps protect both tenants and landlords by clearly defining their rights and responsibilities.', 'A signed agreement helps protect both tenants and landlords by clearly defining their rights and responsibilities.', '/saɪnd/', 'Một bản thỏa thuận đã ký giúp bảo vệ cả người thuê nhà và chủ nhà bằng cách xác định rõ ràng quyền lợi và trách nhiệm của họ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_32_2_1', 'en-b1-32', 'ten_b1_32_2', 'listening', 'listening', 'Employers increasingly value practical experience alongside formal qualifications when recruiting graduates for demanding professional roles.', NULL, 'Trong câu vừa nghe, từ “qualification” mang nghĩa nào sau đây?', '["bằng cấp, chứng chỉ (chứng nhận hoàn thành chương trình học tập hoặc đào tạo)","đường ray; vận tải đường sắt","lòng thương xót; sự đồng cảm","khăn giấy; giấy ăn"]'::jsonb, 0, '“qualification” (/ˌkwɑːlɪfɪˈkeɪʃən/): bằng cấp, chứng chỉ (chứng nhận hoàn thành chương trình học tập hoặc đào tạo). Câu đầy đủ: Employers increasingly value practical experience alongside formal qualifications when recruiting graduates for demanding professional roles.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_32_2_2', 'en-b1-32', 'ten_b1_32_2', 'listening', 'listening', 'Car makers are investing in cleaner technologies to meet stricter environmental standards and changing consumer expectations.', NULL, 'Trong câu vừa nghe, từ “maker” mang nghĩa nào sau đây?', '["nền tảng; cơ sở","thế hệ","nhà sản xuất; hãng sản xuất; thợ thủ công","dễ tính; thoải mái; hòa đồng"]'::jsonb, 2, '“maker” (/ˈmeɪkər/): nhà sản xuất; hãng sản xuất; thợ thủ công. Câu đầy đủ: Car makers are investing in cleaner technologies to meet stricter environmental standards and changing consumer expectations.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
