INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_32_2', 'en-b1-32', 'The furniture maker carved a beautiful chair from oak', 'Người thợ mộc đã đẽo gọt một chiếc ghế đẹp từ gỗ sồi.', 'maker /ˈmeɪkər/', '["a","The","oak","maker","from","chair","carved","beautiful","furniture"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
