INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_b1_32_1', 'en-b1-32', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “qualification” (/ˌkwɑːlɪfɪˈkeɪʃən/) có nghĩa là gì?', '["năng lượng thể chất hoặc tinh thần bỏ ra để đạt được điều gì đó; sự nỗ lực; công sức","thợ đánh máy; nhân viên đánh máy","chịu trách nhiệm; có trách nhiệm quản lý","bằng cấp, chứng chỉ (chứng nhận hoàn thành chương trình học tập hoặc đào tạo)"]'::jsonb, 3, '“qualification” (n.): bằng cấp, chứng chỉ (chứng nhận hoàn thành chương trình học tập hoặc đào tạo); năng lực, trình độ chuyên môn (kỹ năng hoặc phẩm chất phù hợp cho một vị trí); điều kiện hạn chế, ý kiến bảo lưu (điều kiện làm giảm ý nghĩa hoặc sự chấp nhận của việc gì).', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
