INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_1', 'en-b1-32', NULL, 'comprehensive_test', 'listening', 'qualification', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mục đích; mục tiêu","bằng cấp, chứng chỉ (chứng nhận hoàn thành chương trình học tập hoặc đào tạo)","kênh; kênh đào","hoàn hảo; không tì vết"]'::jsonb, 1, 'qualification (/ˌkwɑːlɪfɪˈkeɪʃən/) → bằng cấp, chứng chỉ (chứng nhận hoàn thành chương trình học tập hoặc đào tạo); năng lực, trình độ chuyên môn (kỹ năng hoặc phẩm chất phù hợp cho một vị trí); điều kiện hạn chế, ý kiến bảo lưu (điều kiện làm giảm ý nghĩa hoặc sự chấp nhận của việc gì)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_2', 'en-b1-32', NULL, 'comprehensive_test', 'listening', 'The furniture maker carved a beautiful chair from oak.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhân viên du lịch đã tìm cho chúng tôi một chuyến bay về nhà giá rẻ hơn.","Người thợ mộc đã đẽo gọt một chiếc ghế đẹp từ gỗ sồi.","Thợ sửa chữa đã tìm thấy một chỗ rò rỉ dưới gầm xe của chúng tôi.","Nữ nhân viên dọn phòng của khách sạn đã đem khăn tắm sạch đến phòng chúng tôi."]'::jsonb, 1, 'The furniture maker carved a beautiful chair from oak. → Người thợ mộc đã đẽo gọt một chiếc ghế đẹp từ gỗ sồi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_3', 'en-b1-32', NULL, 'comprehensive_test', 'listening', 'agent', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["giúp thoát khỏi; tẩy sạch","chung; phổ biến; toàn thể","người đại diện; đại lý","giao hàng; phân phát"]'::jsonb, 2, 'agent (/ˈeɪdʒənt/) → người đại diện; đại lý; điệp viên; mật vụ; tác nhân; chất xúc tác', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_4', 'en-b1-32', NULL, 'comprehensive_test', 'listening', 'Our workplace has a quiet room for lunch breaks.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Huấn luyện viên đã ca ngợi màn thể hiện của chúng tôi sau trận đấu bóng đá.","Lịch trình bận rộn của tôi khiến tôi có rất ít thời gian để nấu nướng vào các ngày trong tuần.","Phải mất rất nhiều công sức mới đẩy được chiếc sofa lên lầu.","Nơi làm việc của chúng tôi có một phòng yên tĩnh để nghỉ trưa."]'::jsonb, 3, 'Our workplace has a quiet room for lunch breaks. → Nơi làm việc của chúng tôi có một phòng yên tĩnh để nghỉ trưa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_5', 'en-b1-32', NULL, 'comprehensive_test', 'listening', 'employment', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự liên lạc; sự tiếp xúc","sự thật; chân lý","việc làm; sự tuyển dụng; tình trạng có việc làm","sáng tạo; có tính sáng tạo"]'::jsonb, 2, 'employment (/ɪmˈplɔɪmənt/) → việc làm; sự tuyển dụng; tình trạng có việc làm; sự sử dụng; sự vận dụng cái gì cho mục đích cụ thể', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_6', 'en-b1-32', NULL, 'comprehensive_test', 'listening', 'I put the signed form in a blue envelope.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đặt tờ đơn đã ký vào một phong bì màu xanh.","Người thợ mộc đã đẽo gọt một chiếc ghế đẹp từ gỗ sồi.","Chứng chỉ này đã giúp tôi tìm được việc làm tại một nhà trẻ.","Nhân viên đánh máy đã hoàn thành bức thư trước giờ nghỉ trưa."]'::jsonb, 0, 'I put the signed form in a blue envelope. → Tôi đặt tờ đơn đã ký vào một phong bì màu xanh.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_7', 'en-b1-32', NULL, 'comprehensive_test', 'listening', 'full-time', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bùn; bùn lầy","lời giải thích; sự giải thích","toàn thời gian; toàn ngày","đào; bới"]'::jsonb, 2, 'full-time (/ˌfʊl ˈtaɪm/) → toàn thời gian; toàn ngày; theo chế độ toàn thời gian', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_8', 'en-b1-32', NULL, 'comprehensive_test', 'listening', 'Our hotel is hosting a conference for local teachers.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người ngư dân kéo lưới lên chiếc thuyền gỗ.","Khách sạn của chúng tôi đang tổ chức một hội nghị dành cho giáo viên địa phương.","Nhà kế toán đã kiểm tra các khoản chi phí của chúng tôi trước khi quán cà phê đi vào hoạt động.","Quán cà phê trả mức lương khá cho ca làm việc cuối tuần."]'::jsonb, 1, 'Our hotel is hosting a conference for local teachers. → Khách sạn của chúng tôi đang tổ chức một hội nghị dành cho giáo viên địa phương.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_9', 'en-b1-32', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “paid work or the state of having a paid job”?', '["responsible","conference","employment","target"]'::jsonb, 2, 'employment (/ɪmˈplɔɪmənt/) → việc làm; sự tuyển dụng; tình trạng có việc làm', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
