INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_18', 'en-b1-32', NULL, 'comprehensive_test', 'reading', NULL, 'Employers increasingly value practical experience alongside formal qualifications when recruiting graduates for demanding professional roles.', 'Dựa vào câu trên, từ “qualification” có nghĩa phù hợp nhất là gì?', '["giấy viết thư; giấy viết nháp","bằng cấp, chứng chỉ (chứng nhận hoàn thành chương trình học tập hoặc đào tạo)","nam vận động viên; người đàn ông yêu thể thao","chính trị; hoạt động chính trị"]'::jsonb, 1, 'qualification: bằng cấp, chứng chỉ (chứng nhận hoàn thành chương trình học tập hoặc đào tạo); năng lực, trình độ chuyên môn (kỹ năng hoặc phẩm chất phù hợp cho một vị trí); điều kiện hạn chế, ý kiến bảo lưu (điều kiện làm giảm ý nghĩa hoặc sự chấp nhận của việc gì). Dịch cả câu: Các nhà tuyển dụng ngày càng coi trọng kinh nghiệm thực tế bên cạnh các văn bằng chính thức khi tuyển dụng sinh viên tốt nghiệp cho các vị trí chuyên môn đòi hỏi khắt khe.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_19', 'en-b1-32', NULL, 'comprehensive_test', 'reading', NULL, 'Car makers are investing in cleaner technologies to meet stricter environmental standards and changing consumer expectations.', 'Dựa vào câu trên, từ “maker” có nghĩa phù hợp nhất là gì?', '["múa ba-lê; vở múa ba-lê","sương mù dày đặc","nhà sản xuất; hãng sản xuất; thợ thủ công","khoản tiền hoàn lại; sự hoàn tiền"]'::jsonb, 2, 'maker: nhà sản xuất; hãng sản xuất; thợ thủ công. Dịch cả câu: Các nhà sản xuất ô tô đang đầu tư vào các công nghệ sạch hơn để đáp ứng các tiêu chuẩn môi trường ngặt nghèo hơn và kỳ vọng ngày càng thay đổi của người tiêu dùng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_20', 'en-b1-32', NULL, 'comprehensive_test', 'reading', NULL, 'Local community groups can act as agents of change by encouraging residents to adopt more sustainable habits.', 'Dựa vào câu trên, từ “agent” có nghĩa phù hợp nhất là gì?', '["về mặt thể chất; về thể lực","người đại diện; đại lý","lợi ích; ưu điểm","tiểu thuyết; truyện dài"]'::jsonb, 1, 'agent: người đại diện; đại lý; điệp viên; mật vụ; tác nhân; chất xúc tác. Dịch cả câu: Các nhóm cộng đồng địa phương có thể đóng vai trò là tác nhân thay đổi bằng cách khuyến khích cư dân áp dụng các thói quen bền vững hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_21', 'en-b1-32', NULL, 'comprehensive_test', 'reading', NULL, 'Creating an inclusive workplace helps employees feel valued and encourages cooperation among people from different backgrounds.', 'Dựa vào câu trên, từ “workplace” có nghĩa phù hợp nhất là gì?', '["dây thừng mảnh; dây buộc","nơi làm việc; môi trường công sở","làm cho ai đó ấn tượng; gây ấn tượng sâu sắc","khó chịu; không dễ chịu; đáng ghét"]'::jsonb, 1, 'workplace: nơi làm việc; môi trường công sở. Dịch cả câu: Xây dựng một môi trường làm việc hòa nhập giúp nhân viên cảm thấy được coi trọng và khuyến khích sự hợp tác giữa những người có hoàn cảnh khác nhau.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_22', 'en-b1-32', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kế toán; kiểm toán viên”', '["responsible","accountant","annoyed","heel"]'::jsonb, 1, 'kế toán; kiểm toán viên → accountant (/əˈkaʊntənt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_23', 'en-b1-32', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thợ đánh máy; nhân viên đánh máy”', '["version","marvellous","furry","typist"]'::jsonb, 3, 'thợ đánh máy; nhân viên đánh máy → typist (/ˈtaɪpɪst/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_32_24', 'en-b1-32', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thợ sửa chữa; thợ máy”', '["interrupt","mechanic","trolley","straw"]'::jsonb, 1, 'thợ sửa chữa; thợ máy → mechanic (/məˈkænɪk/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-33', 'en', 'Bài 33: Công việc & Nghề nghiệp (2) - CEFR B1', 'CEFR B1', 'B1 · Công việc', '24 từ vựng Tiếng Anh CEFR B1 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3033, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tractor', 'en-b1-33', 'tractor', '/ˈtræktər/', 'B1', 'xe máy kéo; máy cày', 'n.', NULL, NULL, 'tractor là máy kéo; truck là xe tải, cần lưu ý phân biệt.', 'The farmer drove a tractor across the muddy field.', NULL, 'Người nông dân lái máy kéo băng qua cánh đồng lầy lội.', '{"wordId":"tractor","ukIpa":"/ˈtræktə/","usIpa":"/ˈtræktər/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"A powerful farm vehicle used to pull equipment or loads","vi":"xe máy kéo; máy cày"}],"examples":[{"en":"The farmer drove a tractor across the muddy field.","vi":"Người nông dân lái máy kéo băng qua cánh đồng lầy lội.","audioKind":"ex"},{"en":"Using a tractor allows farmers to cultivate larger areas with less physical effort and fewer workers.","vi":"Việc sử dụng máy kéo giúp nông dân canh tác những diện tích rộng lớn hơn với ít sức lực và nhân công hơn.","audioKind":"ex2"}],"collocations":[{"en":"drive a tractor","vi":"lái máy kéo"},{"en":"tractor driver","vi":"tài xế máy kéo"},{"en":"tractor tyre","vi":"lốp máy kéo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"tractor là máy kéo; truck là xe tải, cần lưu ý phân biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brief', 'en-b1-33', 'brief', '/briːf/', 'B1', 'ngắn gọn; ngắn ngủi; thông tin ngắn gọn cho ai; hướng dẫn ai; bản tóm tắt công việc; nhiệm vụ', 'adj.', 'briefly (adv.), briefing (n.), brevity (n.)', 'Đồng nghĩa: short, concise · Trái nghĩa: lengthy', 'brief chỉ thời gian ngắn hoặc nội dung súc tích, bản thân không mang nghĩa là cẩu thả.', 'We took a brief break before finishing the puzzle.', NULL, 'Chúng tôi đã có một khoảng thời gian nghỉ ngơi ngắn trước khi hoàn thành bức tranh ghép.', '{"wordId":"brief","ukIpa":"/briːf/","usIpa":"/briːf/","cefr":"B1","topic":"work","senses":[{"pos":"adj.","en":"Lasting a short time or using few words.","vi":"ngắn gọn; ngắn ngủi"},{"pos":"v.","en":"To give someone essential information or instructions.","vi":"thông tin ngắn gọn cho ai; hướng dẫn ai"},{"pos":"n.","en":"Instructions explaining what a task should achieve.","vi":"bản tóm tắt công việc; nhiệm vụ"}],"examples":[{"en":"We took a brief break before finishing the puzzle.","vi":"Chúng tôi đã có một khoảng thời gian nghỉ ngơi ngắn trước khi hoàn thành bức tranh ghép.","audioKind":"ex"},{"en":"Teachers should brief students on safety procedures before allowing them to conduct experiments independently.","vi":"Giáo viên nên hướng dẫn học sinh về quy trình an toàn trước khi cho phép các em tự thực hiện thí nghiệm.","audioKind":"ex2"}],"collocations":[{"en":"a brief summary","vi":"bản tóm tắt ngắn gọn"},{"en":"a brief pause","vi":"một khoảng dừng ngắn"},{"en":"brief someone on","vi":"thông tin cho ai về việc gì"},{"en":"a design brief","vi":"bản tóm tắt thiết kế"}],"wordFamily":["briefly (adv.)","briefing (n.)","brevity (n.)"],"synonyms":["short","concise"],"antonyms":["lengthy"],"tipVi":"brief chỉ thời gian ngắn hoặc nội dung súc tích, bản thân không mang nghĩa là cẩu thả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_load', 'en-b1-33', 'load', '/loʊd/', 'B1', 'vật nặng; khối lượng chuyên chở; chất hàng; nạp (dữ liệu); khối lượng công việc; gánh nặng', 'n.', 'unload (v.), reload (v.), loaded (adj.), loading (n.)', 'Đồng nghĩa: burden', 'load A with B có nghĩa là chất B lên A; từ trái nghĩa dùng unload để chỉ việc dỡ hàng.', 'The donkey carried a heavy load up the hill.', NULL, 'Con lừa chở một gánh nặng trĩu đi lên đồi.', '{"wordId":"load","ukIpa":"/ləʊd/","usIpa":"/loʊd/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"something carried, or the amount a vehicle or person carries","vi":"vật nặng; khối lượng chuyên chở"},{"pos":"v.","en":"to put goods into something or data into computer memory","vi":"chất hàng; nạp (dữ liệu)"},{"pos":"n.","en":"the amount of work or responsibility someone must manage","vi":"khối lượng công việc; gánh nặng"}],"examples":[{"en":"The donkey carried a heavy load up the hill.","vi":"Con lừa chở một gánh nặng trĩu đi lên đồi.","audioKind":"ex"},{"en":"Sharing household tasks more equally can reduce the load on parents who also work full time.","vi":"Việc chia sẻ công việc gia đình công bằng hơn có thể làm giảm gánh nặng cho những bậc cha mẹ vừa đi làm toàn thời gian.","audioKind":"ex2"}],"collocations":[{"en":"a heavy load","vi":"một gánh nặng lớn"},{"en":"load a truck","vi":"chất hàng lên xe tải"},{"en":"load data","vi":"nạp dữ liệu"},{"en":"a load of laundry","vi":"một mẻ quần áo giặt"}],"wordFamily":["unload (v.)","reload (v.)","loaded (adj.)","loading (n.)"],"synonyms":["burden"],"antonyms":[],"tipVi":"load A with B có nghĩa là chất B lên A; từ trái nghĩa dùng unload để chỉ việc dỡ hàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_messenger', 'en-b1-33', 'messenger', '/ˈmesɪndʒɚ/', 'B1', 'người đưa thư; sứ giả; người truyền tin', 'n.', 'message (n.)', 'Đồng nghĩa: courier', 'message là thông điệp; messenger là người truyền tải thông điệp đó.', 'A messenger arrived with an envelope for the manager.', NULL, 'Một người đưa thư đã đến mang theo một phong bì gửi cho giám đốc.', '{"wordId":"messenger","ukIpa":"/ˈmesɪndʒə/","usIpa":"/ˈmesɪndʒɚ/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"a person who carries a message to someone","vi":"người đưa thư; sứ giả; người truyền tin"}],"examples":[{"en":"A messenger arrived with an envelope for the manager.","vi":"Một người đưa thư đã đến mang theo một phong bì gửi cho giám đốc.","audioKind":"ex"},{"en":"Before modern telecommunications, governments relied on messengers to carry important information between distant towns and military posts.","vi":"Trước khi có viễn thông hiện đại, các chính phủ phụ thuộc vào các sứ giả để mang thông tin quan trọng giữa các thị trấn xa xôi và đồn bốt quân sự.","audioKind":"ex2"}],"collocations":[{"en":"send a messenger","vi":"cử người đưa thư"},{"en":"bike messenger","vi":"nhân viên giao hàng bằng xe đạp"},{"en":"act as a messenger","vi":"đóng vai trò là người truyền tin"}],"wordFamily":["message (n.)"],"synonyms":["courier"],"antonyms":[],"tipVi":"message là thông điệp; messenger là người truyền tải thông điệp đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gain', 'en-b1-33', 'gain', '/ɡeɪn/', 'B1', 'đạt được; thu được; gia tăng; sự gia tăng; lợi ích', 'v.', 'gainful (adj.), gainfully (adv.)', 'Đồng nghĩa: obtain, acquire · Trái nghĩa: lose', '''gain'' thường đi với kinh nghiệm, sự tự tin; để chỉ việc thắng một trận đấu, người ta thường dùng ''win''.', 'You will gain confidence after a few lessons.', NULL, 'Bạn sẽ trở nên tự tin hơn sau một vài buổi học.', '{"wordId":"gain","ukIpa":"/ɡeɪn/","usIpa":"/ɡeɪn/","cefr":"B1","topic":"work","senses":[{"pos":"v.","en":"To obtain something useful or increase in amount.","vi":"đạt được; thu được; gia tăng"},{"pos":"n.","en":"An increase in something or a benefit received.","vi":"sự gia tăng; lợi ích"}],"examples":[{"en":"You will gain confidence after a few lessons.","vi":"Bạn sẽ trở nên tự tin hơn sau một vài buổi học.","audioKind":"ex"},{"en":"Students can gain valuable practical experience by volunteering for projects that benefit their local communities.","vi":"Học sinh có thể tích lũy kinh nghiệm thực tế quý giá bằng cách tình nguyện tham gia các dự án mang lại lợi ích cho cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"gain experience","vi":"tích lũy kinh nghiệm"},{"en":"gain access to","vi":"có được quyền tiếp cận"},{"en":"gain weight","vi":"tăng cân"},{"en":"financial gain","vi":"lợi ích kinh tế"}],"wordFamily":["gainful (adj.)","gainfully (adv.)"],"synonyms":["obtain","acquire"],"antonyms":["lose"],"tipVi":"''gain'' thường đi với kinh nghiệm, sự tự tin; để chỉ việc thắng một trận đấu, người ta thường dùng ''win''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_profession', 'en-b1-33', 'profession', '/prəˈfeʃən/', 'B1', 'nghề nghiệp; chuyên môn (đòi hỏi đào tạo chuyên sâu); giới làm nghề; đội ngũ nhân sự trong một ngành; tuyên bố công khai; sự bày tỏ (niềm tin, cảm xúc)', 'n.', 'professional (adj.), professionally (adv.), professionalism (n.)', 'Đồng nghĩa: occupation, career', 'profession thường chỉ nghề đòi hỏi đào tạo chuyên môn, phạm vi hẹp hơn job.', 'Nursing is a demanding profession, but my sister loves it.', NULL, 'Ngành điều dưỡng là một nghề nghiệp đòi hỏi cao, nhưng chị tôi rất yêu thích nó.', '{"wordId":"profession","ukIpa":"/prəˈfeʃən/","usIpa":"/prəˈfeʃən/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"A job requiring specialist knowledge and usually advanced training.","vi":"nghề nghiệp; chuyên môn (đòi hỏi đào tạo chuyên sâu)"},{"pos":"n.","en":"All the people working in a particular specialist occupation.","vi":"giới làm nghề; đội ngũ nhân sự trong một ngành"},{"pos":"n.","en":"An open statement of a belief, feeling, or intention.","vi":"tuyên bố công khai; sự bày tỏ (niềm tin, cảm xúc)"}],"examples":[{"en":"Nursing is a demanding profession, but my sister loves it.","vi":"Ngành điều dưỡng là một nghề nghiệp đòi hỏi cao, nhưng chị tôi rất yêu thích nó.","audioKind":"ex"},{"en":"The teaching profession needs greater public support to attract talented graduates and retain experienced staff.","vi":"Ngành giáo dục cần thêm sự hỗ trợ từ công chúng để thu hút các sinh viên tốt nghiệp tài năng và giữ chân đội ngũ nhân viên giàu kinh nghiệm.","audioKind":"ex2"}],"collocations":[{"en":"enter a profession","vi":"dấn thân vào một nghề"},{"en":"by profession","vi":"xét về mặt nghề nghiệp"},{"en":"the medical profession","vi":"giới y học"},{"en":"a profession of faith","vi":"tuyên ngôn đức tin"}],"wordFamily":["professional (adj.)","professionally (adv.)","professionalism (n.)"],"synonyms":["occupation","career"],"antonyms":[],"tipVi":"profession thường chỉ nghề đòi hỏi đào tạo chuyên môn, phạm vi hẹp hơn job.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_aim', 'en-b1-33', 'aim', '/eɪm/', 'B1', 'mục đích; mục tiêu; nhắm đến; có ý định; đặt mục tiêu; chĩa vào; nhắm vào; hướng vào', 'n.', 'aimless (adj.), aimlessly (adv.)', 'Đồng nghĩa: goal, objective', 'Aim to do dùng để chỉ dự định làm gì; aim at doing dùng để chỉ nỗ lực đạt được điều gì.', 'My main aim today is to tidy the kitchen.', NULL, 'Mục tiêu chính của tôi hôm nay là dọn dẹp nhà bếp.', '{"wordId":"aim","ukIpa":"/eɪm/","usIpa":"/eɪm/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"something you want or plan to achieve","vi":"mục đích; mục tiêu"},{"pos":"v.","en":"to intend or try to achieve something","vi":"nhắm đến; có ý định; đặt mục tiêu"},{"pos":"v.","en":"to point something towards a particular target","vi":"chĩa vào; nhắm vào; hướng vào"}],"examples":[{"en":"My main aim today is to tidy the kitchen.","vi":"Mục tiêu chính của tôi hôm nay là dọn dẹp nhà bếp.","audioKind":"ex"},{"en":"The programme aims to reduce youth unemployment by providing practical training and opportunities to gain workplace experience.","vi":"Chương trình nhằm mục đích giảm tỷ lệ thất nghiệp ở thanh thiếu niên bằng cách cung cấp đào tạo thực tế và cơ hội tích lũy kinh nghiệm làm việc.","audioKind":"ex2"}],"collocations":[{"en":"the main aim","vi":"mục tiêu chính"},{"en":"aim to do something","vi":"dự định làm gì"},{"en":"with the aim of","vi":"với mục đích là"},{"en":"aim at a target","vi":"nhắm vào một mục tiêu"}],"wordFamily":["aimless (adj.)","aimlessly (adv.)"],"synonyms":["goal","objective"],"antonyms":[],"tipVi":"Aim to do dùng để chỉ dự định làm gì; aim at doing dùng để chỉ nỗ lực đạt được điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_staff', 'en-b1-33', 'staff', '/stæf/', 'B1', 'nhân viên; đội ngũ nhân viên; cung cấp nhân sự; bố trí nhân viên', 'n.', 'staffing (n.), understaffed (adj.)', 'Đồng nghĩa: personnel, workforce', 'Một nhân viên dùng a member of staff, không nói a staff.', 'The hotel staff helped us carry our heavy bags.', NULL, 'Nhân viên khách sạn đã giúp chúng tôi mang những chiếc túi nặng.', '{"wordId":"staff","ukIpa":"/stɑːf/","usIpa":"/stæf/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"The people employed by an organisation.","vi":"nhân viên; đội ngũ nhân viên"},{"pos":"v.","en":"To provide workers for an organisation or service.","vi":"cung cấp nhân sự; bố trí nhân viên"}],"examples":[{"en":"The hotel staff helped us carry our heavy bags.","vi":"Nhân viên khách sạn đã giúp chúng tôi mang những chiếc túi nặng.","audioKind":"ex"},{"en":"Hospitals need sufficient staff to maintain high standards of care during periods of increased demand.","vi":"Các bệnh viện cần đủ nhân lực để duy trì chất lượng chăm sóc cao điểm trong các giai đoạn nhu cầu tăng cao.","audioKind":"ex2"}],"collocations":[{"en":"a member of staff","vi":"một nhân viên"},{"en":"staff training","vi":"đào tạo nhân viên"},{"en":"teaching staff","vi":"đội ngũ giảng viên"},{"en":"staff shortage","vi":"tình trạng thiếu nhân lực"}],"wordFamily":["staffing (n.)","understaffed (adj.)"],"synonyms":["personnel","workforce"],"antonyms":[],"tipVi":"Một nhân viên dùng a member of staff, không nói a staff.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_employer', 'en-b1-33', 'employer', '/ɪmˈplɔɪər/', 'B1', 'chủ; người sử dụng lao động; cơ quan tuyển dụng', 'n.', 'employ (v.), employee (n.), employment (n.), unemployed (adj.)', NULL, 'employer là chủ; employee là nhân viên.', 'My employer lets me work from home on Fridays.', NULL, 'Chủ của tôi cho phép tôi làm việc tại nhà vào các ngày thứ Sáu.', '{"wordId":"employer","ukIpa":"/ɪmˈplɔɪə/","usIpa":"/ɪmˈplɔɪər/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"A person or organisation that pays people to work.","vi":"chủ; người sử dụng lao động; cơ quan tuyển dụng"}],"examples":[{"en":"My employer lets me work from home on Fridays.","vi":"Chủ của tôi cho phép tôi làm việc tại nhà vào các ngày thứ Sáu.","audioKind":"ex"},{"en":"Employers can improve staff retention by offering fair wages, flexible schedules, and opportunities for professional development.","vi":"Các nhà tuyển dụng có thể cải thiện tỷ lệ giữ chân nhân viên bằng cách cung cấp mức lương công bằng, lịch trình linh hoạt và cơ hội phát triển nghề nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"a major employer","vi":"một nhà tuyển dụng lớn"},{"en":"a prospective employer","vi":"một nhà tuyển dụng tiềm năng"},{"en":"current employer","vi":"chủ hiện tại"}],"wordFamily":["employ (v.)","employee (n.)","employment (n.)","unemployed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"employer là chủ; employee là nhân viên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_occupation', 'en-b1-33', 'occupation', '/ˌɑːkjəˈpeɪʃən/', 'B1', 'nghề nghiệp; công việc; sự chiếm đóng; sự chiếm giữ (bởi quân đội nước ngoài); sự cư trú; việc sử dụng (nhà cửa, tòa nhà)', 'n.', 'occupy (v.), occupational (adj.), occupant (n.), occupied (adj.)', NULL, 'Khi chỉ nghề nghiệp, từ này mang tính trang trọng, thường xuất hiện trong các biểu mẫu; không nên nhầm lẫn với chức vụ.', 'Her occupation involves repairing bicycles in a small workshop.', NULL, 'Công việc của cô ấy liên quan đến việc sửa chữa xe đạp trong một xưởng nhỏ.', '{"wordId":"occupation","ukIpa":"/ˌɒkjəˈpeɪʃən/","usIpa":"/ˌɑːkjəˈpeɪʃən/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"the type of work someone does to earn money","vi":"nghề nghiệp; công việc"},{"pos":"n.","en":"control of a place by a foreign army","vi":"sự chiếm đóng; sự chiếm giữ (bởi quân đội nước ngoài)"},{"pos":"n.","en":"the act of living in or using a building","vi":"sự cư trú; việc sử dụng (nhà cửa, tòa nhà)"}],"examples":[{"en":"Her occupation involves repairing bicycles in a small workshop.","vi":"Công việc của cô ấy liên quan đến việc sửa chữa xe đạp trong một xưởng nhỏ.","audioKind":"ex"},{"en":"A person''s occupation can influence their income, social connections, and opportunities for further education.","vi":"Nghề nghiệp của một người có thể ảnh hưởng đến thu nhập, các mối quan hệ xã hội và cơ hội học tập nâng cao của họ.","audioKind":"ex2"}],"collocations":[{"en":"current occupation","vi":"nghề nghiệp hiện tại"},{"en":"military occupation","vi":"sự chiếm đóng quân sự"},{"en":"under occupation","vi":"đang nằm dưới sự chiếm đóng"},{"en":"ready for occupation","vi":"sẵn sàng để dọn vào ở"}],"wordFamily":["occupy (v.)","occupational (adj.)","occupant (n.)","occupied (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ nghề nghiệp, từ này mang tính trang trọng, thường xuất hiện trong các biểu mẫu; không nên nhầm lẫn với chức vụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_planned', 'en-b1-33', 'planned', '/plænd/', 'B1', 'đã lên kế hoạch; dự kiến trước; lên kế hoạch; trù định', 'adj.', 'plan (n.), plan (v.), planning (n.), planner (n.)', 'Đồng nghĩa: scheduled, arranged · Trái nghĩa: unplanned', 'Từ plan khi chuyển sang dạng planned phải gấp đôi phụ âm n; as planned có nghĩa là đúng như kế hoạch.', 'Our planned picnic was cancelled because of heavy rain.', NULL, 'Chuyến dã ngoại đã lên kế hoạch của chúng tôi phải hủy vì trời mưa lớn.', '{"wordId":"planned","ukIpa":"/plænd/","usIpa":"/plænd/","cefr":"B1","topic":"work","senses":[{"pos":"adj.","en":"arranged or decided before it happens","vi":"đã lên kế hoạch; dự kiến trước"},{"pos":"v.","en":"made arrangements or decisions about a future action","vi":"lên kế hoạch; trù định"}],"examples":[{"en":"Our planned picnic was cancelled because of heavy rain.","vi":"Chuyến dã ngoại đã lên kế hoạch của chúng tôi phải hủy vì trời mưa lớn.","audioKind":"ex"},{"en":"The planned expansion of the railway network could reduce road congestion and improve access to employment.","vi":"Việc mở rộng mạng lưới đường sắt theo kế hoạch có thể giúp giảm ùn tắc giao thông và cải thiện khả năng tiếp cận việc làm.","audioKind":"ex2"}],"collocations":[{"en":"planned expansion","vi":"sự mở rộng theo kế hoạch"},{"en":"planned maintenance","vi":"bảo trì định kỳ"},{"en":"as planned","vi":"đúng như kế hoạch"},{"en":"carefully planned","vi":"được lên kế hoạch kỹ lưỡng"}],"wordFamily":["plan (n.)","plan (v.)","planning (n.)","planner (n.)"],"synonyms":["scheduled","arranged"],"antonyms":["unplanned"],"tipVi":"Từ plan khi chuyển sang dạng planned phải gấp đôi phụ âm n; as planned có nghĩa là đúng như kế hoạch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_annual', 'en-b1-33', 'annual', '/ˈænjuəl/', 'B1', 'hàng năm; thường niên; sách niên giám; tạp chí xuất bản hàng năm; cây một năm (hoàn thành vòng đời trong một năm)', 'adj.', 'annually (adv.)', 'Đồng nghĩa: yearly', 'Annual là tính từ chỉ sự việc diễn ra hàng năm; annually là phó từ có nghĩa là hàng năm.', 'Our annual family picnic was held beside the lake.', NULL, 'Chuyến dã ngoại gia đình hàng năm của chúng tôi được tổ chức bên hồ.', '{"wordId":"annual","ukIpa":"/ˈænjuəl/","usIpa":"/ˈænjuəl/","cefr":"B1","topic":"work","senses":[{"pos":"adj.","en":"Happening once a year or relating to a whole year","vi":"hàng năm; thường niên"},{"pos":"n.","en":"A book or magazine published once each year","vi":"sách niên giám; tạp chí xuất bản hàng năm"},{"pos":"n.","en":"A plant that completes its life cycle within one year","vi":"cây một năm (hoàn thành vòng đời trong một năm)"}],"examples":[{"en":"Our annual family picnic was held beside the lake.","vi":"Chuyến dã ngoại gia đình hàng năm của chúng tôi được tổ chức bên hồ.","audioKind":"ex"},{"en":"The annual report provides useful evidence of how public funding has improved local transport services.","vi":"Báo cáo thường niên cung cấp những bằng chứng hữu ích về việc nguồn vốn công đã cải thiện các dịch vụ giao thông địa phương như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"annual report","vi":"báo cáo thường niên"},{"en":"annual income","vi":"thu nhập hàng năm"},{"en":"annual leave","vi":"phép nghỉ hàng năm"},{"en":"annual event","vi":"sự kiện thường niên"}],"wordFamily":["annually (adv.)"],"synonyms":["yearly"],"antonyms":[],"tipVi":"Annual là tính từ chỉ sự việc diễn ra hàng năm; annually là phó từ có nghĩa là hàng năm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_efficient', 'en-b1-33', 'efficient', '/ɪˈfɪʃənt/', 'B1', 'hiệu quả; có năng suất cao; tiết kiệm (thời gian, năng lượng)', 'adj.', 'efficiency (n.), efficiently (adv.), inefficient (adj.), inefficiency (n.)', 'Trái nghĩa: inefficient', 'efficient nhấn mạnh việc ít lãng phí; effective nhấn mạnh việc đạt được kết quả mong muốn.', 'Our new washing machine is quieter and more efficient.', NULL, 'Máy giặt mới của chúng tôi chạy êm hơn và tiết kiệm điện hơn.', '{"wordId":"efficient","ukIpa":"/ɪˈfɪʃənt/","usIpa":"/ɪˈfɪʃənt/","cefr":"B1","topic":"work","senses":[{"pos":"adj.","en":"Working well without wasting time, energy, or resources.","vi":"hiệu quả; có năng suất cao; tiết kiệm (thời gian, năng lượng)"}],"examples":[{"en":"Our new washing machine is quieter and more efficient.","vi":"Máy giặt mới của chúng tôi chạy êm hơn và tiết kiệm điện hơn.","audioKind":"ex"},{"en":"An efficient public transport network allows cities to move more people while consuming less energy.","vi":"Mạng lưới giao thông công cộng hiệu quả giúp các thành phố vận chuyển được nhiều người hơn trong khi tiêu thụ ít năng lượng hơn.","audioKind":"ex2"}],"collocations":[{"en":"energy-efficient buildings","vi":"tòa nhà tiết kiệm năng lượng"},{"en":"efficient use of resources","vi":"sử dụng tài nguyên hiệu quả"},{"en":"highly efficient","vi":"hiệu suất cao"},{"en":"efficient service","vi":"dịch vụ hiệu quả"}],"wordFamily":["efficiency (n.)","efficiently (adv.)","inefficient (adj.)","inefficiency (n.)"],"synonyms":[],"antonyms":["inefficient"],"tipVi":"efficient nhấn mạnh việc ít lãng phí; effective nhấn mạnh việc đạt được kết quả mong muốn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_agreed', 'en-b1-33', 'agreed', '/əˈɡriːd/', 'B1', 'đã thỏa thuận; được thống nhất', 'adj.', 'agree (v.), agreement (n.), disagree (v.), disagreement (n.)', 'Đồng nghĩa: settled', 'the agreed price chỉ mức giá đã ngã giá; Agreed! có thể dùng để thể hiện sự đồng tình.', 'We met outside the station at the agreed time.', NULL, 'Chúng tôi đã gặp nhau bên ngoài nhà ga vào đúng thời điểm đã thỏa thuận.', '{"wordId":"agreed","ukIpa":"/əˈɡriːd/","usIpa":"/əˈɡriːd/","cefr":"B1","topic":"work","senses":[{"pos":"adj.","en":"accepted or decided by everyone involved","vi":"đã thỏa thuận; được thống nhất"}],"examples":[{"en":"We met outside the station at the agreed time.","vi":"Chúng tôi đã gặp nhau bên ngoài nhà ga vào đúng thời điểm đã thỏa thuận.","audioKind":"ex"},{"en":"All participating countries should follow the agreed targets to ensure that collective efforts reduce carbon emissions.","vi":"Tất cả các quốc gia tham gia nên tuân thủ các mục tiêu đã thống nhất để đảm bảo các nỗ lực chung làm giảm lượng khí thải carbon.","audioKind":"ex2"}],"collocations":[{"en":"agreed time","vi":"thời gian đã thỏa thuận"},{"en":"agreed terms","vi":"các điều khoản đã thỏa thuận"},{"en":"agreed price","vi":"mức giá thỏa thuận"},{"en":"be agreed on","vi":"đạt được sự đồng thuận về"}],"wordFamily":["agree (v.)","agreement (n.)","disagree (v.)","disagreement (n.)"],"synonyms":["settled"],"antonyms":[],"tipVi":"the agreed price chỉ mức giá đã ngã giá; Agreed! có thể dùng để thể hiện sự đồng tình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_employ', 'en-b1-33', 'employ', '/ɪmˈplɔɪ/', 'B1', 'thuê; thuê mướn; sử dụng; áp dụng', 'v.', 'employment (n.), employer (n.), employee (n.), unemployed (adj.)', 'Đồng nghĩa: hire, use', 'employ có thể dùng để chỉ việc thuê mướn nhân sự, hoặc dùng một cách trang trọng để chỉ việc áp dụng một phương pháp.', 'The bakery employs three people from our neighbourhood.', NULL, 'Tiệm bánh này thuê ba người làm ở khu phố chúng tôi.', '{"wordId":"employ","ukIpa":"/ɪmˈplɔɪ/","usIpa":"/ɪmˈplɔɪ/","cefr":"B1","topic":"work","senses":[{"pos":"v.","en":"Pay someone to work for you.","vi":"thuê; thuê mướn"},{"pos":"v.","en":"Use a method, skill, or resource for a purpose.","vi":"sử dụng; áp dụng"}],"examples":[{"en":"The bakery employs three people from our neighbourhood.","vi":"Tiệm bánh này thuê ba người làm ở khu phố chúng tôi.","audioKind":"ex"},{"en":"Teachers can employ a range of practical activities to help students understand complex scientific concepts.","vi":"Giáo viên có thể áp dụng nhiều hoạt động thực tế khác nhau để giúp học sinh hiểu các khái niệm khoa học phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"employ staff","vi":"thuê nhân viên"},{"en":"employ someone as","vi":"thuê ai làm vị trí gì"},{"en":"employ a strategy","vi":"áp dụng một chiến lược"}],"wordFamily":["employment (n.)","employer (n.)","employee (n.)","unemployed (adj.)"],"synonyms":["hire","use"],"antonyms":[],"tipVi":"employ có thể dùng để chỉ việc thuê mướn nhân sự, hoặc dùng một cách trang trọng để chỉ việc áp dụng một phương pháp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lead', 'en-b1-33', 'lead', '/liːd/', 'B1', 'dẫn dắt; lãnh đạo; dẫn đến; vị thế dẫn đầu; ưu thế; chì', 'v.', 'leader (n.), leadership (n.), leading (adj.)', 'Đồng nghĩa: guide', 'Kim loại chì phát âm là /led/; động từ đọc là /liːd/, với dạng quá khứ và phân từ hai là led.', 'Our guide led us safely through the forest.', NULL, 'Người hướng dẫn đã dẫn chúng tôi đi an toàn qua khu rừng.', '{"wordId":"lead","ukIpa":"/liːd/","usIpa":"/liːd/","cefr":"B1","topic":"work","senses":[{"pos":"v.","en":"To guide people or cause something to happen","vi":"dẫn dắt; lãnh đạo; dẫn đến"},{"pos":"n.","en":"The position of being ahead of others","vi":"vị thế dẫn đầu; ưu thế"},{"pos":"n.","en":"A soft, heavy, grey metal that can be poisonous","vi":"chì"}],"examples":[{"en":"Our guide led us safely through the forest.","vi":"Người hướng dẫn đã dẫn chúng tôi đi an toàn qua khu rừng.","audioKind":"ex"},{"en":"Poor access to public transport can lead to greater dependence on private cars.","vi":"Việc giao thông công cộng kém phát triển có thể dẫn đến việc phụ thuộc nhiều hơn vào xe hơi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"lead to","vi":"dẫn đến"},{"en":"lead a team","vi":"lãnh đạo một đội ngũ"},{"en":"take the lead","vi":"giành vị trí dẫn đầu"},{"en":"lead poisoning","vi":"ngộ độc chì"}],"wordFamily":["leader (n.)","leadership (n.)","leading (adj.)"],"synonyms":["guide"],"antonyms":[],"tipVi":"Kim loại chì phát âm là /led/; động từ đọc là /liːd/, với dạng quá khứ và phân từ hai là led.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_junior', 'en-b1-33', 'junior', '/ˈdʒuːniər/', 'B1', 'cấp dưới; sơ cấp; ít thâm niên hơn; dành cho thanh thiếu niên; học sinh cấp dưới; người ít tuổi hơn', 'adj.', NULL, 'Trái nghĩa: senior', 'Khi so sánh chức vụ hoặc độ tuổi dùng junior to, không dùng junior than.', 'Our junior chef prepares vegetables before the restaurant opens.', NULL, 'Đầu bếp tập sự của chúng tôi sơ chế rau củ trước khi nhà hàng mở cửa.', '{"wordId":"junior","ukIpa":"/ˈdʒuːniə/","usIpa":"/ˈdʒuːniər/","cefr":"B1","topic":"work","senses":[{"pos":"adj.","en":"Having a lower rank or less experience in an organisation","vi":"cấp dưới; sơ cấp; ít thâm niên hơn"},{"pos":"adj.","en":"Intended for younger people or involving them","vi":"dành cho thanh thiếu niên"},{"pos":"n.","en":"A younger person, or a student below the final year","vi":"học sinh cấp dưới; người ít tuổi hơn"}],"examples":[{"en":"Our junior chef prepares vegetables before the restaurant opens.","vi":"Đầu bếp tập sự của chúng tôi sơ chế rau củ trước khi nhà hàng mở cửa.","audioKind":"ex"},{"en":"Companies should provide junior employees with structured training and regular opportunities to learn from experienced colleagues.","vi":"Các công ty nên cung cấp cho nhân viên sơ cấp các chương trình đào tạo bài bản và cơ hội thường xuyên học hỏi từ các đồng nghiệp giàu kinh nghiệm.","audioKind":"ex2"}],"collocations":[{"en":"junior staff","vi":"nhân viên cấp dưới"},{"en":"junior position","vi":"chức vụ sơ cấp"},{"en":"junior championship","vi":"giải vô địch trẻ"}],"wordFamily":[],"synonyms":[],"antonyms":["senior"],"tipVi":"Khi so sánh chức vụ hoặc độ tuổi dùng junior to, không dùng junior than.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_servant', 'en-b1-33', 'servant', '/ˈsɝːvənt/', 'B1', 'người hầu; người ở', 'n.', 'serve (v.), service (n.)', NULL, 'Công chức dùng civil servant, không được gọi đơn giản là servant.', 'The servant carried fresh towels into the guest bedroom.', NULL, 'Người hầu mang khăn tắm sạch vào phòng ngủ dành cho khách.', '{"wordId":"servant","ukIpa":"/ˈsɜːvənt/","usIpa":"/ˈsɝːvənt/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"Someone employed to do household work in another person''s home","vi":"người hầu; người ở"}],"examples":[{"en":"The servant carried fresh towels into the guest bedroom.","vi":"Người hầu mang khăn tắm sạch vào phòng ngủ dành cho khách.","audioKind":"ex"},{"en":"In wealthy households of the past, servants often worked long hours with little legal protection.","vi":"Trong các gia đình giàu có trước đây, những người hầu thường phải làm việc nhiều giờ với ít quyền bảo vệ pháp lý.","audioKind":"ex2"}],"collocations":[{"en":"domestic servant","vi":"người hầu gia đình"},{"en":"civil servant","vi":"công chức"},{"en":"public servant","vi":"nhân viên công tác công ích"}],"wordFamily":["serve (v.)","service (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Công chức dùng civil servant, không được gọi đơn giản là servant.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_butcher', 'en-b1-33', 'butcher', '/ˈbʊtʃər/', 'B1', 'người bán thịt; thợ mổ thịt; giết mổ; chặt thịt; làm hỏng; phá hỏng', 'n.', 'butchery (n.)', NULL, 'Cửa hàng thịt thường dùng the butcher''s; động từ cũng có thể chỉ việc làm hỏng một màn trình diễn.', 'The butcher wrapped our chicken and suggested a simple recipe.', NULL, 'Người bán thịt gói gà lại cho chúng tôi và gợi ý một công thức nấu ăn đơn giản.', '{"wordId":"butcher","ukIpa":"/ˈbʊtʃə/","usIpa":"/ˈbʊtʃər/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"someone who prepares and sells meat","vi":"người bán thịt; thợ mổ thịt"},{"pos":"v.","en":"to kill animals for meat or cut up their meat","vi":"giết mổ; chặt thịt"},{"pos":"v.","en":"to do something very badly, spoiling the result","vi":"làm hỏng; phá hỏng"}],"examples":[{"en":"The butcher wrapped our chicken and suggested a simple recipe.","vi":"Người bán thịt gói gà lại cho chúng tôi và gợi ý một công thức nấu ăn đơn giản.","audioKind":"ex"},{"en":"A local butcher can help customers reduce food waste by recommending suitable cuts and portion sizes.","vi":"Người bán thịt ở địa phương có thể giúp khách hàng giảm lãng phí thực phẩm bằng cách gợi ý các phần thịt và định lượng phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"local butcher","vi":"người bán thịt địa phương"},{"en":"butcher''s shop","vi":"cửa hàng thịt"},{"en":"butcher a song","vi":"hát lệch tông một bài hát"}],"wordFamily":["butchery (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cửa hàng thịt thường dùng the butcher''s; động từ cũng có thể chỉ việc làm hỏng một màn trình diễn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_involve', 'en-b1-33', 'involve', '/ɪnˈvɑːlv/', 'B1', 'bao gồm; đòi hỏi; liên quan đến; kéo theo; làm cho ai tham gia', 'v.', 'involvement (n.), involved (adj.)', 'Đồng nghĩa: entail, include', 'Diễn đạt ý cần phải làm gì, dùng involve doing, không dùng to do.', 'My new job involves talking to customers all day.', NULL, 'Công việc mới của tôi đòi hỏi phải trò chuyện với khách hàng cả ngày.', '{"wordId":"involve","ukIpa":"/ɪnˈvɒlv/","usIpa":"/ɪnˈvɑːlv/","cefr":"B1","topic":"work","senses":[{"pos":"v.","en":"to include something as a necessary part","vi":"bao gồm; đòi hỏi; liên quan đến"},{"pos":"v.","en":"to make someone take part in an activity","vi":"kéo theo; làm cho ai tham gia"}],"examples":[{"en":"My new job involves talking to customers all day.","vi":"Công việc mới của tôi đòi hỏi phải trò chuyện với khách hàng cả ngày.","audioKind":"ex"},{"en":"Local authorities should involve residents in planning decisions to ensure that new developments meet community needs.","vi":"Chính quyền địa phương nên tạo điều kiện cho người dân tham gia vào các quyết định quy hoạch nhằm đảm bảo những dự án phát triển mới đáp ứng nhu cầu cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"involve doing something","vi":"đòi hỏi phải làm việc gì"},{"en":"involve someone in something","vi":"lôi kéo ai tham gia việc gì"},{"en":"be closely involved","vi":"tham gia sâu sát"}],"wordFamily":["involvement (n.)","involved (adj.)"],"synonyms":["entail","include"],"antonyms":[],"tipVi":"Diễn đạt ý cần phải làm gì, dùng involve doing, không dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_management', 'en-b1-33', 'management', '/ˈmænɪdʒmənt/', 'B1', 'sự quản lý; sự điều hành; ban quản lý; ban giám đốc', 'n.', 'manage (v.), manager (n.), managerial (adj.), manageable (adj.)', 'Đồng nghĩa: administration', 'Khi chỉ công việc quản lý thì không đếm được; "the management" có thể chỉ ban quản lý.', 'Good time management leaves me free to relax.', NULL, 'Quản lý thời gian tốt giúp tôi có thời gian rảnh để thư giãn.', '{"wordId":"management","ukIpa":"/ˈmænɪdʒmənt/","usIpa":"/ˈmænɪdʒmənt/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"The work of organising and controlling activities or resources.","vi":"sự quản lý; sự điều hành"},{"pos":"n.","en":"The people responsible for running an organisation.","vi":"ban quản lý; ban giám đốc"}],"examples":[{"en":"Good time management leaves me free to relax.","vi":"Quản lý thời gian tốt giúp tôi có thời gian rảnh để thư giãn.","audioKind":"ex"},{"en":"Effective waste management requires cooperation between local authorities, businesses, and residents to reduce pollution and conserve resources.","vi":"Quản lý chất thải hiệu quả đòi hỏi sự hợp tác giữa chính quyền địa phương, doanh nghiệp và người dân nhằm giảm ô nhiễm và bảo tồn tài nguyên.","audioKind":"ex2"}],"collocations":[{"en":"time management","vi":"quản lý thời gian"},{"en":"waste management","vi":"quản lý chất thải"},{"en":"senior management","vi":"ban lãnh đạo cấp cao"},{"en":"management skills","vi":"kỹ năng quản lý"}],"wordFamily":["manage (v.)","manager (n.)","managerial (adj.)","manageable (adj.)"],"synonyms":["administration"],"antonyms":[],"tipVi":"Khi chỉ công việc quản lý thì không đếm được; \"the management\" có thể chỉ ban quản lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sailor', 'en-b1-33', 'sailor', '/ˈseɪlər/', 'B1', 'thủy thủ; người đi biển; người chèo thuyền buồm', 'n.', 'sail (v.), sail (n.), sailing (n.)', 'Đồng nghĩa: seafarer, mariner', 'Chỉ người làm việc trên tàu hoặc điều khiển thuyền buồm, không dùng để chỉ hành khách.', 'The sailor tied the boat securely to the dock.', NULL, 'Người thủy thủ buộc chặt con thuyền vào bến tàu.', '{"wordId":"sailor","ukIpa":"/ˈseɪlə/","usIpa":"/ˈseɪlər/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"Someone who works on ships or sails boats","vi":"thủy thủ; người đi biển; người chèo thuyền buồm"}],"examples":[{"en":"The sailor tied the boat securely to the dock.","vi":"Người thủy thủ buộc chặt con thuyền vào bến tàu.","audioKind":"ex"},{"en":"Modern navigation technology helps sailors avoid dangerous waters, but practical experience remains essential for safety at sea.","vi":"Công nghệ hàng hải hiện đại giúp các thủy thủ tránh được những vùng biển nguy hiểm, nhưng kinh nghiệm thực tế vẫn đóng vai trò thiết yếu đối với sự an toàn trên biển.","audioKind":"ex2"}],"collocations":[{"en":"experienced sailor","vi":"thủy thủ giàu kinh nghiệm"},{"en":"professional sailor","vi":"thủy thủ chuyên nghiệp"},{"en":"a crew of sailors","vi":"một thủy thủ đoàn"}],"wordFamily":["sail (v.)","sail (n.)","sailing (n.)"],"synonyms":["seafarer","mariner"],"antonyms":[],"tipVi":"Chỉ người làm việc trên tàu hoặc điều khiển thuyền buồm, không dùng để chỉ hành khách.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_handle', 'en-b1-33', 'handle', '/ˈhændl/', 'B1', 'xử lý; giải quyết; đối phó; cầm; nắm; chạm; điều khiển; tay cầm; quai cầm; núm', 'v.', 'handler (n.), handling (n.)', 'Đồng nghĩa: manage, deal with', 'handle mang nghĩa xử lý, giải quyết sẽ đi thẳng trực tiếp với tân ngữ, không cần dùng giới từ with.', 'Can you handle dinner while I collect the children?', NULL, 'Bạn có thể lo bữa tối trong lúc tôi đi đón các con không?', '{"wordId":"handle","ukIpa":"/ˈhændl/","usIpa":"/ˈhændl/","cefr":"B1","topic":"work","senses":[{"pos":"v.","en":"To deal with a situation, task, or person.","vi":"xử lý; giải quyết; đối phó"},{"pos":"v.","en":"To hold, touch, move, or control something with your hands.","vi":"cầm; nắm; chạm; điều khiển"},{"pos":"n.","en":"The part of an object used for holding or moving it.","vi":"tay cầm; quai cầm; núm"}],"examples":[{"en":"Can you handle dinner while I collect the children?","vi":"Bạn có thể lo bữa tối trong lúc tôi đi đón các con không?","audioKind":"ex"},{"en":"Healthcare workers need effective training to handle stressful situations while maintaining a high standard of care.","vi":"Nhân viên y tế cần được đào tạo hiệu quả để xử lý các tình huống căng thẳng đồng thời duy trì tiêu chuẩn chăm sóc cao.","audioKind":"ex2"}],"collocations":[{"en":"handle complaints","vi":"xử lý khiếu nại"},{"en":"handle with care","vi":"cẩn thận nhẹ tay"},{"en":"door handle","vi":"tay nắm cửa"},{"en":"handle pressure","vi":"chịu đựng áp lực"}],"wordFamily":["handler (n.)","handling (n.)"],"synonyms":["manage","deal with"],"antonyms":[],"tipVi":"handle mang nghĩa xử lý, giải quyết sẽ đi thẳng trực tiếp với tân ngữ, không cần dùng giới từ with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reward', 'en-b1-33', 'reward', '/rɪˈwɔːrd/', 'B1', 'phần thưởng; sự đền bù; tiền thưởng; thưởng; đền đáp', 'n.', 'rewarding (adj.), unrewarding (adj.)', 'Đồng nghĩa: recompense', 'reward nhấn mạnh sự đền đáp sau nỗ lực; award thường chỉ việc trao giải chính thức.', 'We gave the puppy a treat as a reward.', NULL, 'Chúng tôi đã cho chú cún con một chiếc bánh thưởng như một phần quà.', '{"wordId":"reward","ukIpa":"/rɪˈwɔːd/","usIpa":"/rɪˈwɔːrd/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"Something received for good work, helpful behaviour, or achievement.","vi":"phần thưởng; sự đền bù; tiền thưởng"},{"pos":"v.","en":"To give something to someone for their efforts or help.","vi":"thưởng; đền đáp"}],"examples":[{"en":"We gave the puppy a treat as a reward.","vi":"Chúng tôi đã cho chú cún con một chiếc bánh thưởng như một phần quà.","audioKind":"ex"},{"en":"Schools should reward consistent effort rather than focus exclusively on students who achieve the highest grades.","vi":"Nhà trường nên khen thưởng cho những nỗ lực bền bỉ thay vì chỉ tập trung vào những học sinh đạt điểm số cao nhất.","audioKind":"ex2"}],"collocations":[{"en":"financial reward","vi":"khoản tiền thưởng tài chính"},{"en":"reward someone for something","vi":"thưởng cho ai đó vì điều gì"},{"en":"reap the rewards","vi":"gặt hái thành quả"}],"wordFamily":["rewarding (adj.)","unrewarding (adj.)"],"synonyms":["recompense"],"antonyms":[],"tipVi":"reward nhấn mạnh sự đền đáp sau nỗ lực; award thường chỉ việc trao giải chính thức.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_33_1', 'en-b1-33', 'Cách dùng “occupation” (n.) — nghề nghiệp; công việc', 'current occupation  ·  military occupation  ·  under occupation', 'Khi chỉ nghề nghiệp, từ này mang tính trang trọng, thường xuất hiện trong các biểu mẫu; không nên nhầm lẫn với chức vụ.', 'Họ từ (Word Family): occupy (v.), occupational (adj.), occupant (n.), occupied (adj.)', '[{"hanzi":"Her occupation involves repairing bicycles in a small workshop.","pinyin":"","meaning":"Công việc của cô ấy liên quan đến việc sửa chữa xe đạp trong một xưởng nhỏ."},{"hanzi":"A person''s occupation can influence their income, social connections, and opportunities for further education.","pinyin":"","meaning":"Nghề nghiệp của một người có thể ảnh hưởng đến thu nhập, các mối quan hệ xã hội và cơ hội học tập nâng cao của họ."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_33_2', 'en-b1-33', 'Cách dùng “employ” (v.) — thuê; thuê mướn', 'employ staff  ·  employ someone as  ·  employ a strategy', 'employ có thể dùng để chỉ việc thuê mướn nhân sự, hoặc dùng một cách trang trọng để chỉ việc áp dụng một phương pháp.', 'Họ từ (Word Family): employment (n.), employer (n.), employee (n.), unemployed (adj.) | Đồng nghĩa: hire, use', '[{"hanzi":"The bakery employs three people from our neighbourhood.","pinyin":"","meaning":"Tiệm bánh này thuê ba người làm ở khu phố chúng tôi."},{"hanzi":"Teachers can employ a range of practical activities to help students understand complex scientific concepts.","pinyin":"","meaning":"Giáo viên có thể áp dụng nhiều hoạt động thực tế khác nhau để giúp học sinh hiểu các khái niệm khoa học phức tạp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_33_3', 'en-b1-33', 'Cách dùng “gain” (v.) — đạt được; thu được; gia tăng', 'gain experience  ·  gain access to  ·  gain weight', '''gain'' thường đi với kinh nghiệm, sự tự tin; để chỉ việc thắng một trận đấu, người ta thường dùng ''win''.', 'Họ từ (Word Family): gainful (adj.), gainfully (adv.) | Đồng nghĩa: obtain, acquire · Trái nghĩa: lose', '[{"hanzi":"You will gain confidence after a few lessons.","pinyin":"","meaning":"Bạn sẽ trở nên tự tin hơn sau một vài buổi học."},{"hanzi":"Students can gain valuable practical experience by volunteering for projects that benefit their local communities.","pinyin":"","meaning":"Học sinh có thể tích lũy kinh nghiệm thực tế quý giá bằng cách tình nguyện tham gia các dự án mang lại lợi ích cho cộng đồng địa phương."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_33_4', 'en-b1-33', 'Cách dùng “planned” (adj.) — đã lên kế hoạch; dự kiến trước', 'planned expansion  ·  planned maintenance  ·  as planned', 'Từ plan khi chuyển sang dạng planned phải gấp đôi phụ âm n; as planned có nghĩa là đúng như kế hoạch.', 'Họ từ (Word Family): plan (n.), plan (v.), planning (n.), planner (n.) | Đồng nghĩa: scheduled, arranged · Trái nghĩa: unplanned', '[{"hanzi":"Our planned picnic was cancelled because of heavy rain.","pinyin":"","meaning":"Chuyến dã ngoại đã lên kế hoạch của chúng tôi phải hủy vì trời mưa lớn."},{"hanzi":"The planned expansion of the railway network could reduce road congestion and improve access to employment.","pinyin":"","meaning":"Việc mở rộng mạng lưới đường sắt theo kế hoạch có thể giúp giảm ùn tắc giao thông và cải thiện khả năng tiếp cận việc làm."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_33_1', 'en-b1-33', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
