INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_33_1_3', 'ten_b1_33_1', 'load', 'The donkey carried a heavy load up the hill.', 'The donkey carried a heavy load up the hill.', '/loʊd/', 'Con lừa chở một gánh nặng trĩu đi lên đồi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_33_1_4', 'ten_b1_33_1', 'messenger', 'A messenger arrived with an envelope for the manager.', 'A messenger arrived with an envelope for the manager.', '/ˈmesɪndʒɚ/', 'Một người đưa thư đã đến mang theo một phong bì gửi cho giám đốc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_33_1_5', 'ten_b1_33_1', 'gain', 'You will gain confidence after a few lessons.', 'You will gain confidence after a few lessons.', '/ɡeɪn/', 'Bạn sẽ trở nên tự tin hơn sau một vài buổi học.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_33_1_6', 'ten_b1_33_1', 'profession', 'Nursing is a demanding profession, but my sister loves it.', 'Nursing is a demanding profession, but my sister loves it.', '/prəˈfeʃən/', 'Ngành điều dưỡng là một nghề nghiệp đòi hỏi cao, nhưng chị tôi rất yêu thích nó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_33_1_7', 'ten_b1_33_1', 'aim', 'My main aim today is to tidy the kitchen.', 'My main aim today is to tidy the kitchen.', '/eɪm/', 'Mục tiêu chính của tôi hôm nay là dọn dẹp nhà bếp.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_33_1_8', 'ten_b1_33_1', 'staff', 'The hotel staff helped us carry our heavy bags.', 'The hotel staff helped us carry our heavy bags.', '/stæf/', 'Nhân viên khách sạn đã giúp chúng tôi mang những chiếc túi nặng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_33_1_1', 'en-b1-33', 'ten_b1_33_1', 'listening', 'listening', 'The farmer drove a tractor across the muddy field.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chuyến dã ngoại gia đình hàng năm của chúng tôi được tổ chức bên hồ.","Người nông dân lái máy kéo băng qua cánh đồng lầy lội.","Máy giặt mới của chúng tôi chạy êm hơn và tiết kiệm điện hơn.","Công việc của cô ấy liên quan đến việc sửa chữa xe đạp trong một xưởng nhỏ."]'::jsonb, 1, 'The farmer drove a tractor across the muddy field. → Người nông dân lái máy kéo băng qua cánh đồng lầy lội.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_33_1_2', 'en-b1-33', 'ten_b1_33_1', 'listening', 'listening', 'We took a brief break before finishing the puzzle.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người hướng dẫn đã dẫn chúng tôi đi an toàn qua khu rừng.","Chúng tôi đã gặp nhau bên ngoài nhà ga vào đúng thời điểm đã thỏa thuận.","Người nông dân lái máy kéo băng qua cánh đồng lầy lội.","Chúng tôi đã có một khoảng thời gian nghỉ ngơi ngắn trước khi hoàn thành bức tranh ghép."]'::jsonb, 3, 'We took a brief break before finishing the puzzle. → Chúng tôi đã có một khoảng thời gian nghỉ ngơi ngắn trước khi hoàn thành bức tranh ghép.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_33_1_3', 'en-b1-33', 'ten_b1_33_1', 'listening', 'listening', 'The donkey carried a heavy load up the hill.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mục tiêu chính của tôi hôm nay là dọn dẹp nhà bếp.","Chúng tôi đã cho chú cún con một chiếc bánh thưởng như một phần quà.","Chúng tôi đã có một khoảng thời gian nghỉ ngơi ngắn trước khi hoàn thành bức tranh ghép.","Con lừa chở một gánh nặng trĩu đi lên đồi."]'::jsonb, 3, 'The donkey carried a heavy load up the hill. → Con lừa chở một gánh nặng trĩu đi lên đồi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_33_2', 'en-b1-33', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_33_2_1', 'ten_b1_33_2', 'tractor', 'Using a tractor allows farmers to cultivate larger areas with less physical effort and fewer workers.', 'Using a tractor allows farmers to cultivate larger areas with less physical effort and fewer workers.', '/ˈtræktər/', 'Việc sử dụng máy kéo giúp nông dân canh tác những diện tích rộng lớn hơn với ít sức lực và nhân công hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_33_2_2', 'ten_b1_33_2', 'brief', 'Teachers should brief students on safety procedures before allowing them to conduct experiments independently.', 'Teachers should brief students on safety procedures before allowing them to conduct experiments independently.', '/briːf/', 'Giáo viên nên hướng dẫn học sinh về quy trình an toàn trước khi cho phép các em tự thực hiện thí nghiệm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_33_2_3', 'ten_b1_33_2', 'load', 'Sharing household tasks more equally can reduce the load on parents who also work full time.', 'Sharing household tasks more equally can reduce the load on parents who also work full time.', '/loʊd/', 'Việc chia sẻ công việc gia đình công bằng hơn có thể làm giảm gánh nặng cho những bậc cha mẹ vừa đi làm toàn thời gian.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_33_2_4', 'ten_b1_33_2', 'messenger', 'Before modern telecommunications, governments relied on messengers to carry important information between distant towns and military posts.', 'Before modern telecommunications, governments relied on messengers to carry important information between distant towns and military posts.', '/ˈmesɪndʒɚ/', 'Trước khi có viễn thông hiện đại, các chính phủ phụ thuộc vào các sứ giả để mang thông tin quan trọng giữa các thị trấn xa xôi và đồn bốt quân sự.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_33_2_5', 'ten_b1_33_2', 'gain', 'Students can gain valuable practical experience by volunteering for projects that benefit their local communities.', 'Students can gain valuable practical experience by volunteering for projects that benefit their local communities.', '/ɡeɪn/', 'Học sinh có thể tích lũy kinh nghiệm thực tế quý giá bằng cách tình nguyện tham gia các dự án mang lại lợi ích cho cộng đồng địa phương.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_33_2_6', 'ten_b1_33_2', 'profession', 'The teaching profession needs greater public support to attract talented graduates and retain experienced staff.', 'The teaching profession needs greater public support to attract talented graduates and retain experienced staff.', '/prəˈfeʃən/', 'Ngành giáo dục cần thêm sự hỗ trợ từ công chúng để thu hút các sinh viên tốt nghiệp tài năng và giữ chân đội ngũ nhân viên giàu kinh nghiệm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_33_2_1', 'en-b1-33', 'ten_b1_33_2', 'listening', 'listening', 'Using a tractor allows farmers to cultivate larger areas with less physical effort and fewer workers.', NULL, 'Trong câu vừa nghe, từ “tractor” mang nghĩa nào sau đây?', '["xe máy kéo; máy cày","chứng minh; chứng thực","chủ yếu là; phần lớn","bài tập yoga; môn yoga"]'::jsonb, 0, '“tractor” (/ˈtræktər/): xe máy kéo; máy cày. Câu đầy đủ: Using a tractor allows farmers to cultivate larger areas with less physical effort and fewer workers.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
