INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_33_2', 'en-b1-33', NULL, 'comprehensive_test', 'listening', 'We took a brief break before finishing the puzzle.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một người đưa thư đã đến mang theo một phong bì gửi cho giám đốc.","Bạn có thể lo bữa tối trong lúc tôi đi đón các con không?","Quản lý thời gian tốt giúp tôi có thời gian rảnh để thư giãn.","Chúng tôi đã có một khoảng thời gian nghỉ ngơi ngắn trước khi hoàn thành bức tranh ghép."]'::jsonb, 3, 'We took a brief break before finishing the puzzle. → Chúng tôi đã có một khoảng thời gian nghỉ ngơi ngắn trước khi hoàn thành bức tranh ghép.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
