INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_33_4', 'en-b1-33', NULL, 'comprehensive_test', 'listening', 'A messenger arrived with an envelope for the manager.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người nông dân lái máy kéo băng qua cánh đồng lầy lội.","Tiệm bánh này thuê ba người làm ở khu phố chúng tôi.","Một người đưa thư đã đến mang theo một phong bì gửi cho giám đốc.","Chuyến dã ngoại gia đình hàng năm của chúng tôi được tổ chức bên hồ."]'::jsonb, 2, 'A messenger arrived with an envelope for the manager. → Một người đưa thư đã đến mang theo một phong bì gửi cho giám đốc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
