INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_33_6', 'en-b1-33', NULL, 'comprehensive_test', 'listening', 'Nursing is a demanding profession, but my sister loves it.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bạn có thể lo bữa tối trong lúc tôi đi đón các con không?","Nhân viên khách sạn đã giúp chúng tôi mang những chiếc túi nặng.","Ngành điều dưỡng là một nghề nghiệp đòi hỏi cao, nhưng chị tôi rất yêu thích nó.","Bạn sẽ trở nên tự tin hơn sau một vài buổi học."]'::jsonb, 2, 'Nursing is a demanding profession, but my sister loves it. → Ngành điều dưỡng là một nghề nghiệp đòi hỏi cao, nhưng chị tôi rất yêu thích nó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_33_7', 'en-b1-33', NULL, 'comprehensive_test', 'listening', 'aim', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lễ; nghi lễ; nghi thức","vương miện; mão","mục đích; mục tiêu","làm cho tin; thuyết phục"]'::jsonb, 2, 'aim (/eɪm/) → mục đích; mục tiêu; nhắm đến; có ý định; đặt mục tiêu; chĩa vào; nhắm vào; hướng vào', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_33_8', 'en-b1-33', NULL, 'comprehensive_test', 'listening', 'The hotel staff helped us carry our heavy bags.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhân viên khách sạn đã giúp chúng tôi mang những chiếc túi nặng.","Công việc mới của tôi đòi hỏi phải trò chuyện với khách hàng cả ngày.","Tiệm bánh này thuê ba người làm ở khu phố chúng tôi.","Người nông dân lái máy kéo băng qua cánh đồng lầy lội."]'::jsonb, 0, 'The hotel staff helped us carry our heavy bags. → Nhân viên khách sạn đã giúp chúng tôi mang những chiếc túi nặng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_33_9', 'en-b1-33', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To obtain something useful or increase in amount.”?', '["butcher","servant","gain","load"]'::jsonb, 2, 'gain (/ɡeɪn/) → đạt được; thu được; gia tăng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
