INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_33_18', 'en-b1-33', NULL, 'comprehensive_test', 'reading', NULL, 'Using a tractor allows farmers to cultivate larger areas with less physical effort and fewer workers.', 'Dựa vào câu trên, từ “tractor” có nghĩa phù hợp nhất là gì?', '["xe máy kéo; máy cày","sự phản đối mạnh mẽ; cuộc biểu tình, cuộc kháng nghị","sự mất mát; sự thất lạc; tổn thất","thơ ca"]'::jsonb, 0, 'tractor: xe máy kéo; máy cày. Dịch cả câu: Việc sử dụng máy kéo giúp nông dân canh tác những diện tích rộng lớn hơn với ít sức lực và nhân công hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_33_19', 'en-b1-33', NULL, 'comprehensive_test', 'reading', NULL, 'Teachers should brief students on safety procedures before allowing them to conduct experiments independently.', 'Dựa vào câu trên, từ “brief” có nghĩa phù hợp nhất là gì?', '["ngắn gọn; ngắn ngủi","năng lượng thể chất hoặc tinh thần bỏ ra để đạt được điều gì đó; sự nỗ lực; công sức","xa hơn (về khoảng cách)","tập phim (truyền hình/phát thanh)"]'::jsonb, 0, 'brief: ngắn gọn; ngắn ngủi; thông tin ngắn gọn cho ai; hướng dẫn ai; bản tóm tắt công việc; nhiệm vụ. Dịch cả câu: Giáo viên nên hướng dẫn học sinh về quy trình an toàn trước khi cho phép các em tự thực hiện thí nghiệm.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_33_20', 'en-b1-33', NULL, 'comprehensive_test', 'reading', NULL, 'Sharing household tasks more equally can reduce the load on parents who also work full time.', 'Dựa vào câu trên, từ “load” có nghĩa phù hợp nhất là gì?', '["nữ chủ nhà; nữ gia chủ (tiếp đón khách)","quận; khu vực; vùng","nhân viên bảo vệ; lính canh","vật nặng; khối lượng chuyên chở"]'::jsonb, 3, 'load: vật nặng; khối lượng chuyên chở; chất hàng; nạp (dữ liệu); khối lượng công việc; gánh nặng. Dịch cả câu: Việc chia sẻ công việc gia đình công bằng hơn có thể làm giảm gánh nặng cho những bậc cha mẹ vừa đi làm toàn thời gian.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_33_21', 'en-b1-33', NULL, 'comprehensive_test', 'reading', NULL, 'Before modern telecommunications, governments relied on messengers to carry important information between distant towns and military posts.', 'Dựa vào câu trên, từ “messenger” có nghĩa phù hợp nhất là gì?', '["chèo thuyền; môn đua thuyền","thuộc y tế; thuộc y học; khám chữa bệnh","người đưa thư; sứ giả; người truyền tin","chua (có vị gắt như chanh)"]'::jsonb, 2, 'messenger: người đưa thư; sứ giả; người truyền tin. Dịch cả câu: Trước khi có viễn thông hiện đại, các chính phủ phụ thuộc vào các sứ giả để mang thông tin quan trọng giữa các thị trấn xa xôi và đồn bốt quân sự.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_33_22', 'en-b1-33', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thủy thủ; người đi biển; người chèo thuyền buồm”', '["hook","sailor","process","represent"]'::jsonb, 1, 'thủy thủ; người đi biển; người chèo thuyền buồm → sailor (/ˈseɪlər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_33_23', 'en-b1-33', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “xử lý; giải quyết; đối phó”', '["volcano","handle","surround","physical"]'::jsonb, 1, 'xử lý; giải quyết; đối phó → handle (/ˈhændl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_33_24', 'en-b1-33', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phần thưởng; sự đền bù; tiền thưởng”', '["reward","lamb","freezing","strict"]'::jsonb, 0, 'phần thưởng; sự đền bù; tiền thưởng → reward (/rɪˈwɔːrd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-34', 'en', 'Bài 34: Công việc & Nghề nghiệp (3) - CEFR B1', 'CEFR B1', 'B1 · Công việc', '23 từ vựng Tiếng Anh CEFR B1 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3034, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crew', 'en-b1-34', 'crew', '/kruː/', 'B1', 'đội ngũ nhân viên trên tàu hoặc máy bay; nhóm làm việc chung trong một nhiệm vụ thực tế; làm thành viên đoàn tàu thuyền', 'n.', NULL, 'Đồng nghĩa: team', 'crew là danh từ tập thể; một thành viên riêng lẻ nói a crew member.', 'The crew welcomed us aboard with warm smiles.', NULL, 'Tổ bay đã chào đón chúng tôi lên máy bay với những nụ cười ấm áp.', '{"wordId":"crew","ukIpa":"/kruː/","usIpa":"/kruː/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"The people who work together on a ship or aircraft","vi":"đội ngũ nhân viên trên tàu hoặc máy bay"},{"pos":"n.","en":"A group working together on a particular practical task","vi":"nhóm làm việc chung trong một nhiệm vụ thực tế"},{"pos":"v.","en":"Work as a member of a boat''s crew","vi":"làm thành viên đoàn tàu thuyền"}],"examples":[{"en":"The crew welcomed us aboard with warm smiles.","vi":"Tổ bay đã chào đón chúng tôi lên máy bay với những nụ cười ấm áp.","audioKind":"ex"},{"en":"Airlines must ensure that every crew member receives regular safety training to protect passengers during emergencies.","vi":"Các hãng hàng không phải đảm bảo rằng mọi thành viên phi hành đoàn đều được đào tạo an toàn thường xuyên để bảo vệ hành khách trong các tình huống khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"cabin crew","vi":"phi hành đoàn"},{"en":"crew member","vi":"thành viên phi hành đoàn; thủy thủ"},{"en":"film crew","vi":"đoàn làm phim"},{"en":"rescue crew","vi":"đội cứu hộ"}],"wordFamily":[],"synonyms":["team"],"antonyms":[],"tipVi":"crew là danh từ tập thể; một thành viên riêng lẻ nói a crew member.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cashier', 'en-b1-34', 'cashier', '/kæˈʃɪr/', 'B1', 'nhân viên thu ngân; thâu ngân viên', 'n.', 'cash (n.), cash (v.)', NULL, 'cashier chịu trách nhiệm thu tiền, trong khi accountant phụ trách công tác kế toán.', 'The cashier smiled and handed me my change.', NULL, 'Cô thu ngân mỉm cười và đưa lại tiền thừa cho tôi.', '{"wordId":"cashier","ukIpa":"/kæˈʃɪə/","usIpa":"/kæˈʃɪr/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"Someone who receives customers'' payments in a shop or bank","vi":"nhân viên thu ngân; thâu ngân viên"}],"examples":[{"en":"The cashier smiled and handed me my change.","vi":"Cô thu ngân mỉm cười và đưa lại tiền thừa cho tôi.","audioKind":"ex"},{"en":"Automated checkouts may reduce demand for cashiers, although many customers still prefer assistance from a person.","vi":"Các quầy thanh toán tự động có thể làm giảm nhu cầu về nhân viên thu ngân, mặc dù nhiều khách hàng vẫn thích sự hỗ trợ từ con người hơn.","audioKind":"ex2"}],"collocations":[{"en":"work as a cashier","vi":"làm thu ngân"},{"en":"supermarket cashier","vi":"thu ngân siêu thị"},{"en":"pay the cashier","vi":"trả tiền cho nhân viên thu ngân"}],"wordFamily":["cash (n.)","cash (v.)"],"synonyms":[],"antonyms":[],"tipVi":"cashier chịu trách nhiệm thu tiền, trong khi accountant phụ trách công tác kế toán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impress', 'en-b1-34', 'impress', '/ɪmˈpres/', 'B1', 'làm cho ai đó ấn tượng; gây ấn tượng sâu sắc; làm cho ai đó nhận thức rõ tầm quan trọng của việc gì', 'v.', 'impression (n.), impressive (adj.), impressed (adj.), impressively (adv.)', NULL, 'impressed dùng để chỉ cảm xúc của con người; impressive dùng để miêu tả sự vật gây ấn tượng.', 'Her homemade bread impressed everyone at the family dinner.', NULL, 'Món bánh mì tự làm của cô ấy đã gây ấn tượng với tất cả mọi người trong bữa tối gia đình.', '{"wordId":"impress","ukIpa":"/ɪmˈpres/","usIpa":"/ɪmˈpres/","cefr":"B1","topic":"work","senses":[{"pos":"v.","en":"to make someone admire or respect someone or something","vi":"làm cho ai đó ấn tượng; gây ấn tượng sâu sắc"},{"pos":"v.","en":"to make someone understand how important something is","vi":"làm cho ai đó nhận thức rõ tầm quan trọng của việc gì"}],"examples":[{"en":"Her homemade bread impressed everyone at the family dinner.","vi":"Món bánh mì tự làm của cô ấy đã gây ấn tượng với tất cả mọi người trong bữa tối gia đình.","audioKind":"ex"},{"en":"Applicants can impress potential employers by explaining how their practical experience matches the requirements of the role.","vi":"Ứng viên có thể gây ấn tượng với nhà tuyển dụng tiềm năng bằng cách giải thích kinh nghiệm thực tế của họ phù hợp với yêu cầu công việc như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"impress someone with","vi":"gây ấn tượng với ai bằng"},{"en":"be impressed by","vi":"bị ấn tượng bởi"},{"en":"impress upon someone","vi":"khắc ghi vào tâm trí ai"}],"wordFamily":["impression (n.)","impressive (adj.)","impressed (adj.)","impressively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"impressed dùng để chỉ cảm xúc của con người; impressive dùng để miêu tả sự vật gây ấn tượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expert', 'en-b1-34', 'expert', '/ˈekspɝːt/', 'B1', 'chuyên gia; người có chuyên môn sâu; chuyên môn; có tay nghề cao', 'n.', 'expertise (n.), expertly (adv.)', 'Đồng nghĩa: specialist · Trái nghĩa: novice', 'expert on/in dùng để chỉ chuyên gia trong một lĩnh vực nào đó.', 'We asked an expert to examine the old painting.', NULL, 'Chúng tôi đã mời một chuyên gia đến kiểm tra bức tranh cũ.', '{"wordId":"expert","ukIpa":"/ˈekspɜːt/","usIpa":"/ˈekspɝːt/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"Someone with extensive knowledge or skill in a particular subject.","vi":"chuyên gia; người có chuyên môn sâu"},{"pos":"adj.","en":"Having or showing great knowledge or skill.","vi":"chuyên môn; có tay nghề cao"}],"examples":[{"en":"We asked an expert to examine the old painting.","vi":"Chúng tôi đã mời một chuyên gia đến kiểm tra bức tranh cũ.","audioKind":"ex"},{"en":"Schools should seek expert advice before introducing new technology into classrooms to support student learning.","vi":"Các trường học nên tham khảo ý kiến chuyên gia trước khi đưa công nghệ mới vào lớp học để hỗ trợ học sinh học tập.","audioKind":"ex2"}],"collocations":[{"en":"an expert on","vi":"chuyên gia về lĩnh vực gì"},{"en":"expert advice","vi":"ý kiến chuyên gia"},{"en":"medical expert","vi":"chuyên gia y tế"}],"wordFamily":["expertise (n.)","expertly (adv.)"],"synonyms":["specialist"],"antonyms":["novice"],"tipVi":"expert on/in dùng để chỉ chuyên gia trong một lĩnh vực nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_process', 'en-b1-34', 'process', '/ˈprɑːses/', 'B1', 'quá trình; quy trình; xử lý; gia công', 'n.', 'processing (n.), processor (n.)', 'Đồng nghĩa: procedure', 'in the process of đi sau danh từ hoặc động từ thêm -ing.', 'Making bread is a slow process, but I enjoy it.', NULL, 'Làm bánh mì là một quá trình chậm rãi, nhưng tôi rất thích nó.', '{"wordId":"process","ukIpa":"/ˈprəʊses/","usIpa":"/ˈprɑːses/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"A series of actions or changes leading to a result.","vi":"quá trình; quy trình"},{"pos":"v.","en":"Treat materials or information through a series of organised steps.","vi":"xử lý; gia công"}],"examples":[{"en":"Making bread is a slow process, but I enjoy it.","vi":"Làm bánh mì là một quá trình chậm rãi, nhưng tôi rất thích nó.","audioKind":"ex"},{"en":"The application process should be transparent so that all candidates have an equal opportunity to participate.","vi":"Quy trình nộp đơn nên minh bạch để tất cả các ứng viên đều có cơ hội tham gia công bằng.","audioKind":"ex2"}],"collocations":[{"en":"a gradual process","vi":"một quá trình tiệm tiến"},{"en":"in the process of","vi":"trong quá trình..."},{"en":"process data","vi":"xử lý dữ liệu"},{"en":"processed food","vi":"thực phẩm chế biến sẵn"}],"wordFamily":["processing (n.)","processor (n.)"],"synonyms":["procedure"],"antonyms":[],"tipVi":"in the process of đi sau danh từ hoặc động từ thêm -ing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deliver', 'en-b1-34', 'deliver', '/dɪˈlɪvər/', 'B1', 'giao hàng; phân phát; phát biểu; đọc (bài diễn văn); mang lại; thực hiện (lời hứa, kết quả)', 'v.', 'delivery (n.), deliverable (adj.)', NULL, 'Giao cái gì cho ai dùng deliver sth to sb; thực hiện lời hứa dùng deliver on.', 'The bakery delivers warm bread to our door every morning.', NULL, 'Tiệm bánh giao những chiếc bánh mì ấm nóng đến tận cửa nhà chúng tôi mỗi buổi sáng.', '{"wordId":"deliver","ukIpa":"/dɪˈlɪvə/","usIpa":"/dɪˈlɪvər/","cefr":"B1","topic":"work","senses":[{"pos":"v.","en":"to take goods or messages to their intended destination","vi":"giao hàng; phân phát"},{"pos":"v.","en":"to give a speech, lecture, or presentation","vi":"phát biểu; đọc (bài diễn văn)"},{"pos":"v.","en":"to produce the results or benefits that were promised","vi":"mang lại; thực hiện (lời hứa, kết quả)"}],"examples":[{"en":"The bakery delivers warm bread to our door every morning.","vi":"Tiệm bánh giao những chiếc bánh mì ấm nóng đến tận cửa nhà chúng tôi mỗi buổi sáng.","audioKind":"ex"},{"en":"Public transport projects must deliver clear benefits to local residents if they are to justify substantial investment.","vi":"Các dự án giao thông công cộng phải mang lại những lợi ích rõ ràng cho người dân địa phương thì mới biện minh được cho khoản đầu tư lớn.","audioKind":"ex2"}],"collocations":[{"en":"deliver a parcel","vi":"giao bưu kiện"},{"en":"deliver a speech","vi":"đọc một bài diễn văn"},{"en":"deliver results","vi":"đạt được kết quả"},{"en":"deliver on a promise","vi":"thực hiện lời hứa"}],"wordFamily":["delivery (n.)","deliverable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Giao cái gì cho ai dùng deliver sth to sb; thực hiện lời hứa dùng deliver on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inform', 'en-b1-34', 'inform', '/ɪnˈfɔːrm/', 'B1', 'thông báo; cho biết; cung cấp tri thức; làm cơ sở cho', 'v.', 'information (n.), informative (adj.), informed (adj.)', 'Đồng nghĩa: notify, tell', 'Thông báo cho ai đó việc gì dùng inform sb of/about sth.', 'Please inform the receptionist if you lose your key.', NULL, 'Vui lòng thông báo cho lễ tân nếu bạn làm mất chìa khóa.', '{"wordId":"inform","ukIpa":"/ɪnˈfɔːm/","usIpa":"/ɪnˈfɔːrm/","cefr":"B1","topic":"work","senses":[{"pos":"v.","en":"To give someone facts or tell them about something.","vi":"thông báo; cho biết"},{"pos":"v.","en":"To provide knowledge that shapes a decision, opinion, or approach.","vi":"cung cấp tri thức; làm cơ sở cho"}],"examples":[{"en":"Please inform the receptionist if you lose your key.","vi":"Vui lòng thông báo cho lễ tân nếu bạn làm mất chìa khóa.","audioKind":"ex"},{"en":"Reliable research should inform government decisions about how to allocate funding for public health services.","vi":"Các nghiên cứu đáng tin cậy nên là cơ sở để chính phủ đưa ra quyết định về cách phân bổ nguồn vốn cho các dịch vụ y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"inform someone of something","vi":"thông báo cho ai đó về việc gì"},{"en":"keep someone informed","vi":"giữ cho ai đó luôn được cập nhật thông tin"},{"en":"inform policy","vi":"định hình chính sách; làm cơ sở cho chính sách"}],"wordFamily":["information (n.)","informative (adj.)","informed (adj.)"],"synonyms":["notify","tell"],"antonyms":[],"tipVi":"Thông báo cho ai đó việc gì dùng inform sb of/about sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hire', 'en-b1-34', 'hire', '/ˈhaɪr/', 'B1', 'thuê; tuyển dụng; thuê mướn (sử dụng tạm thời); sự thuê mướn; sự cho thuê', 'v.', 'hiring (n.)', NULL, 'Thuê xe tiếng Anh Anh thường dùng hire, tiếng Mỹ thường dùng rent.', 'We hired a van to move our furniture.', NULL, 'Chúng tôi đã thuê một chiếc xe tải để chuyển đồ đạc.', '{"wordId":"hire","ukIpa":"/ˈhaɪə/","usIpa":"/ˈhaɪr/","cefr":"B1","topic":"work","senses":[{"pos":"v.","en":"To pay someone to do a job.","vi":"thuê; tuyển dụng"},{"pos":"v.","en":"To pay to use something for a limited time.","vi":"thuê mướn (sử dụng tạm thời)"},{"pos":"n.","en":"An arrangement to use something temporarily in exchange for payment.","vi":"sự thuê mướn; sự cho thuê"}],"examples":[{"en":"We hired a van to move our furniture.","vi":"Chúng tôi đã thuê một chiếc xe tải để chuyển đồ đạc.","audioKind":"ex"},{"en":"Businesses that hire local workers can strengthen regional economies and reduce the need for long commutes.","vi":"Các doanh nghiệp tuyển dụng lao động địa phương có thể thúc đẩy kinh tế vùng và giảm nhu cầu di chuyển đường dài.","audioKind":"ex2"}],"collocations":[{"en":"hire staff","vi":"tuyển dụng nhân sự"},{"en":"hire a car","vi":"thuê xe ô tô"},{"en":"for hire","vi":"cho thuê; để cho thuê"},{"en":"car hire","vi":"dịch vụ cho thuê xe ô tô"}],"wordFamily":["hiring (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thuê xe tiếng Anh Anh thường dùng hire, tiếng Mỹ thường dùng rent.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unemployed', 'en-b1-34', 'unemployed', '/ˌʌnɪmˈplɔɪd/', 'B1', 'thất nghiệp; không có việc làm', 'adj.', 'unemployment (n.), employment (n.), employ (v.), employee (n.)', 'Đồng nghĩa: jobless · Trái nghĩa: employed', 'the unemployed chỉ nhóm người thất nghiệp, vị ngữ dùng số nhiều.', 'My neighbour has been unemployed since the factory closed.', NULL, 'Hàng xóm của tôi đã thất nghiệp từ khi nhà máy đóng cửa.', '{"wordId":"unemployed","ukIpa":"/ˌʌnɪmˈplɔɪd/","usIpa":"/ˌʌnɪmˈplɔɪd/","cefr":"B1","topic":"work","senses":[{"pos":"adj.","en":"Without a paid job but available for work","vi":"thất nghiệp; không có việc làm"}],"examples":[{"en":"My neighbour has been unemployed since the factory closed.","vi":"Hàng xóm của tôi đã thất nghiệp từ khi nhà máy đóng cửa.","audioKind":"ex"},{"en":"Providing affordable training for unemployed adults can help them develop skills that match changing labour market demands.","vi":"Cung cấp các khóa đào tạo vừa túi tiền cho người lớn thất nghiệp có thể giúp họ phát triển các kỹ năng phù hợp với nhu cầu thay đổi của thị trường lao động.","audioKind":"ex2"}],"collocations":[{"en":"become unemployed","vi":"trở nên thất nghiệp"},{"en":"unemployed workers","vi":"công nhân thất nghiệp"},{"en":"the long-term unemployed","vi":"những người thất nghiệp lâu năm"}],"wordFamily":["unemployment (n.)","employment (n.)","employ (v.)","employee (n.)"],"synonyms":["jobless"],"antonyms":["employed"],"tipVi":"the unemployed chỉ nhóm người thất nghiệp, vị ngữ dùng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stapler', 'en-b1-34', 'stapler', '/ˈsteɪplər/', 'B1', 'dập ghim; máy bấm giấy', 'n.', 'staple (n.), staple (v.)', NULL, 'stapler là cái dập ghim, staple là ghim bấm, cũng có thể dùng như động từ.', 'Could you pass me the stapler beside your notebook?', NULL, 'Bạn có thể đưa cho tôi chiếc dập ghim bên cạnh cuốn sổ tay được không?', '{"wordId":"stapler","ukIpa":"/ˈsteɪplə/","usIpa":"/ˈsteɪplər/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"a device that joins papers using small metal staples","vi":"dập ghim; máy bấm giấy"}],"examples":[{"en":"Could you pass me the stapler beside your notebook?","vi":"Bạn có thể đưa cho tôi chiếc dập ghim bên cạnh cuốn sổ tay được không?","audioKind":"ex"},{"en":"Providing basic office equipment, such as staplers and printers, helps community centres support residents seeking employment.","vi":"Cung cấp các thiết bị văn phòng cơ bản, chẳng hạn như dập ghim và máy in, giúp các trung tâm cộng đồng hỗ trợ cư dân tìm kiếm việc làm.","audioKind":"ex2"}],"collocations":[{"en":"use a stapler","vi":"sử dụng dập ghim"},{"en":"a desk stapler","vi":"dập ghim để bàn"},{"en":"refill a stapler","vi":"nạp ghim cho máy bấm"}],"wordFamily":["staple (n.)","staple (v.)"],"synonyms":[],"antonyms":[],"tipVi":"stapler là cái dập ghim, staple là ghim bấm, cũng có thể dùng như động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guard', 'en-b1-34', 'guard', '/ɡɑːrd/', 'B1', 'nhân viên bảo vệ; lính canh; bảo vệ; canh gác; phòng ngừa; thiết bị bảo vệ; tấm chắn', 'n.', 'guardian (n.), guarded (adj.), unguarded (adj.)', NULL, 'guard against diễn tả việc đề phòng trước một rủi ro hoặc sai lầm nào đó.', 'The guard checked my ticket before opening the gate.', NULL, 'Bảo vệ kiểm tra vé của tôi trước khi mở cổng.', '{"wordId":"guard","ukIpa":"/ɡɑːd/","usIpa":"/ɡɑːrd/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"a person whose job is to protect people or places","vi":"nhân viên bảo vệ; lính canh"},{"pos":"v.","en":"to protect someone or something from danger or escape","vi":"bảo vệ; canh gác; phòng ngừa"},{"pos":"n.","en":"a cover or barrier that prevents injury or damage","vi":"thiết bị bảo vệ; tấm chắn"}],"examples":[{"en":"The guard checked my ticket before opening the gate.","vi":"Bảo vệ kiểm tra vé của tôi trước khi mở cổng.","audioKind":"ex"},{"en":"Museums employ trained staff to guard valuable collections while ensuring that visitors can enjoy them safely.","vi":"Các bảo tàng thuê nhân viên được đào tạo bài bản để bảo vệ các bộ sưu tập quý giá đồng thời đảm bảo du khách có thể tham quan một cách an toàn.","audioKind":"ex2"}],"collocations":[{"en":"security guard","vi":"nhân viên bảo vệ"},{"en":"guard against","vi":"đề phòng"},{"en":"on guard","vi":"cảnh giác"},{"en":"protective guard","vi":"tấm chắn bảo vệ"}],"wordFamily":["guardian (n.)","guarded (adj.)","unguarded (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"guard against diễn tả việc đề phòng trước một rủi ro hoặc sai lầm nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vet', 'en-b1-34', 'vet', '/vet/', 'B1', 'thú y; bác sĩ thú y; thẩm định; kiểm tra kỹ lưỡng', 'n.', 'veterinarian (n.), veterinary (adj.), vetting (n.)', 'Đồng nghĩa: veterinarian, screen', 'Dạng quá khứ là "vetted", danh động từ là "vetting", đều nhân đôi chữ "t".', 'The vet gently checked our puppy''s ears and paws.', NULL, 'Bác sĩ thú y nhẹ nhàng kiểm tra tai và bàn chân chú chó con của chúng tôi.', '{"wordId":"vet","ukIpa":"/vet/","usIpa":"/vet/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"a person trained to treat sick or injured animals","vi":"thú y; bác sĩ thú y"},{"pos":"v.","en":"to check someone or something carefully before giving approval","vi":"thẩm định; kiểm tra kỹ lưỡng"}],"examples":[{"en":"The vet gently checked our puppy''s ears and paws.","vi":"Bác sĩ thú y nhẹ nhàng kiểm tra tai và bàn chân chú chó con của chúng tôi.","audioKind":"ex"},{"en":"Organisations should vet potential employees carefully when recruiting people who will work with children or vulnerable adults.","vi":"Các tổ chức nên kiểm tra kỹ lưỡng các ứng viên tiềm năng khi tuyển dụng những người sẽ làm việc với trẻ em hoặc người lớn dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"take a pet to the vet","vi":"đưa thú cưng đi khám thú y"},{"en":"vet applicants","vi":"thẩm định ứng viên"},{"en":"vetting process","vi":"quy trình thẩm định"}],"wordFamily":["veterinarian (n.)","veterinary (adj.)","vetting (n.)"],"synonyms":["veterinarian","screen"],"antonyms":[],"tipVi":"Dạng quá khứ là \"vetted\", danh động từ là \"vetting\", đều nhân đôi chữ \"t\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_duty', 'en-b1-34', 'duty', '/ˈduːti/', 'B1', 'trách nhiệm; bổn phận; nhiệm vụ công việc; ca trực; thuế quan; thuế', 'n.', 'dutiful (adj.), dutifully (adv.), duty-free (adj.)', 'Đồng nghĩa: responsibility, obligation', 'Cụm on duty có nghĩa là đang làm nhiệm vụ; các nhiệm vụ công việc cụ thể thường dùng dạng số nhiều duties.', 'It is my duty to keep these animals safe.', NULL, 'Bảo vệ sự an toàn cho những loài động vật này là bổn phận của tôi.', '{"wordId":"duty","ukIpa":"/ˈdjuːti/","usIpa":"/ˈduːti/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"something you should do because it is right or required","vi":"trách nhiệm; bổn phận"},{"pos":"n.","en":"work required by a job or a period of service","vi":"nhiệm vụ công việc; ca trực"},{"pos":"n.","en":"a tax charged on certain goods","vi":"thuế quan; thuế"}],"examples":[{"en":"It is my duty to keep these animals safe.","vi":"Bảo vệ sự an toàn cho những loài động vật này là bổn phận của tôi.","audioKind":"ex"},{"en":"Governments have a duty to protect vulnerable citizens while ensuring that public services remain financially sustainable.","vi":"Chính phủ có trách nhiệm bảo vệ những công dân dễ bị tổn thương đồng thời đảm bảo các dịch vụ công duy trì được sự bền vững về tài chính.","audioKind":"ex2"}],"collocations":[{"en":"a sense of duty","vi":"ý thức trách nhiệm"},{"en":"on duty","vi":"đang làm nhiệm vụ"},{"en":"import duty","vi":"thuế nhập khẩu"},{"en":"carry out duties","vi":"thực hiện nhiệm vụ"}],"wordFamily":["dutiful (adj.)","dutifully (adv.)","duty-free (adj.)"],"synonyms":["responsibility","obligation"],"antonyms":[],"tipVi":"Cụm on duty có nghĩa là đang làm nhiệm vụ; các nhiệm vụ công việc cụ thể thường dùng dạng số nhiều duties.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_application', 'en-b1-34', 'application', '/ˌæplɪˈkeɪʃən/', 'B1', 'đơn xin; đơn ứng tuyển; sự ứng dụng; sự áp dụng; ứng dụng máy tính', 'n.', 'apply (v.), applicant (n.), applicable (adj.), applied (adj.)', NULL, 'Dùng application for khi xin cái gì, và application to khi nộp đơn cho cơ quan nào đó.', 'I sent my job application before breakfast this morning.', NULL, 'Tôi đã gửi đơn xin việc của mình trước bữa sáng vào sáng nay.', '{"wordId":"application","ukIpa":"/ˌæplɪˈkeɪʃən/","usIpa":"/ˌæplɪˈkeɪʃən/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"a formal request for a job, place, or permission","vi":"đơn xin; đơn ứng tuyển"},{"pos":"n.","en":"the practical use of knowledge, skills, or methods","vi":"sự ứng dụng; sự áp dụng"},{"pos":"n.","en":"a computer program designed to perform particular tasks","vi":"ứng dụng máy tính"}],"examples":[{"en":"I sent my job application before breakfast this morning.","vi":"Tôi đã gửi đơn xin việc của mình trước bữa sáng vào sáng nay.","audioKind":"ex"},{"en":"Simplifying the application process could encourage more students from disadvantaged backgrounds to apply for university scholarships.","vi":"Việc đơn giản hóa quy trình nộp đơn có thể khuyến khích nhiều học sinh có hoàn cảnh khó khăn nộp hồ sơ xin học bổng đại học.","audioKind":"ex2"}],"collocations":[{"en":"submit an application","vi":"nộp đơn"},{"en":"application form","vi":"mẫu đơn đăng ký"},{"en":"practical application","vi":"ứng dụng thực tiễn"},{"en":"software application","vi":"ứng dụng phần mềm"}],"wordFamily":["apply (v.)","applicant (n.)","applicable (adj.)","applied (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng application for khi xin cái gì, và application to khi nộp đơn cho cơ quan nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_client', 'en-b1-34', 'client', '/ˈklaɪənt/', 'B1', 'khách hàng; thân chủ; máy khách; chương trình khách', 'n.', NULL, 'Đồng nghĩa: customer', 'client thường mua dịch vụ chuyên nghiệp; customer dùng chung cho người mua hàng hóa hoặc dịch vụ.', 'The designer showed her client three possible kitchen layouts.', NULL, 'Nhà thiết kế đã cho khách hàng xem ba bố trí nhà bếp khả thi.', '{"wordId":"client","ukIpa":"/ˈklaɪənt/","usIpa":"/ˈklaɪənt/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"someone who pays for professional services","vi":"khách hàng; thân chủ"},{"pos":"n.","en":"a computer or program using services from a server","vi":"máy khách; chương trình khách"}],"examples":[{"en":"The designer showed her client three possible kitchen layouts.","vi":"Nhà thiết kế đã cho khách hàng xem ba bố trí nhà bếp khả thi.","audioKind":"ex"},{"en":"Maintaining clear communication with each client helps businesses build trust and establish lasting professional relationships.","vi":"Duy trì giao tiếp rõ ràng với từng khách hàng giúp doanh nghiệp xây dựng lòng tin và thiết lập mối quan hệ chuyên môn lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"potential client","vi":"khách hàng tiềm năng"},{"en":"client needs","vi":"nhu cầu của khách hàng"},{"en":"client base","vi":"tệp khách hàng"},{"en":"client confidentiality","vi":"bảo mật thông tin khách hàng"}],"wordFamily":[],"synonyms":["customer"],"antonyms":[],"tipVi":"client thường mua dịch vụ chuyên nghiệp; customer dùng chung cho người mua hàng hóa hoặc dịch vụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trainee', 'en-b1-34', 'trainee', '/ˌtreɪˈniː/', 'B1', 'thực tập sinh; học viên tập sự', 'n.', 'train (v.), trainer (n.), training (n.)', 'Đồng nghĩa: apprentice', 'trainee là người nhận đào tạo; trainer là người chịu trách nhiệm đào tạo người khác.', 'The trainee watched carefully as the chef chopped vegetables.', NULL, 'Thực tập sinh đứng quan sát chăm chú khi đầu bếp cắt rau củ.', '{"wordId":"trainee","ukIpa":"/ˌtreɪˈniː/","usIpa":"/ˌtreɪˈniː/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"Someone learning the skills needed for a particular job.","vi":"thực tập sinh; học viên tập sự"}],"examples":[{"en":"The trainee watched carefully as the chef chopped vegetables.","vi":"Thực tập sinh đứng quan sát chăm chú khi đầu bếp cắt rau củ.","audioKind":"ex"},{"en":"Assigning an experienced mentor to each trainee can improve workplace learning and reduce costly mistakes.","vi":"Việc phân công một người cố vấn có kinh nghiệm cho mỗi thực tập sinh có thể cải thiện hiệu quả học tập tại nơi làm việc và hạn chế những sai sót tốn kém.","audioKind":"ex2"}],"collocations":[{"en":"trainee teacher","vi":"giáo viên tập sự"},{"en":"management trainee","vi":"quản trị viên tập sự"},{"en":"graduate trainee","vi":"nhân viên tốt nghiệp đang tập sự"}],"wordFamily":["train (v.)","trainer (n.)","training (n.)"],"synonyms":["apprentice"],"antonyms":[],"tipVi":"trainee là người nhận đào tạo; trainer là người chịu trách nhiệm đào tạo người khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_architect', 'en-b1-34', 'architect', '/ˈɑːrkɪtekt/', 'B1', 'kiến trúc sư; người kiến tạo; người thiết kế chính', 'n.', 'architecture (n.), architectural (adj.), architecturally (adv.)', NULL, 'architect chỉ người, còn architecture chỉ ngành kiến trúc hoặc phong cách kiến trúc.', 'The architect showed us a model of our future home.', NULL, 'Kiến trúc sư đã cho chúng tôi xem mô hình ngôi nhà tương lai của mình.', '{"wordId":"architect","ukIpa":"/ˈɑːkɪtekt/","usIpa":"/ˈɑːrkɪtekt/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"Someone whose job is to design buildings","vi":"kiến trúc sư"},{"pos":"n.","en":"Someone who plans and develops an important change or project","vi":"người kiến tạo; người thiết kế chính"}],"examples":[{"en":"The architect showed us a model of our future home.","vi":"Kiến trúc sư đã cho chúng tôi xem mô hình ngôi nhà tương lai của mình.","audioKind":"ex"},{"en":"Architects can reduce energy consumption by designing buildings that make better use of natural light.","vi":"Các kiến trúc sư có thể giảm mức tiêu thụ năng lượng bằng cách thiết kế các tòa nhà tận dụng tốt hơn ánh sáng tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"qualified architect","vi":"kiến trúc sư có chuyên môn"},{"en":"chief architect","vi":"kiến trúc sư trưởng"},{"en":"the architect of reform","vi":"người kiến tạo cải cách"}],"wordFamily":["architecture (n.)","architectural (adj.)","architecturally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"architect chỉ người, còn architecture chỉ ngành kiến trúc hoặc phong cách kiến trúc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ambition', 'en-b1-34', 'ambition', '/æmˈbɪʃən/', 'B1', 'hoài bão; chí hướng; lòng tiến thủ; sự tham vọng', 'n.', 'ambitious (adj.), ambitiously (adv.)', 'Đồng nghĩa: aspiration', 'Nghĩa chỉ mục tiêu cụ thể là danh từ đếm được, nghĩa chỉ lòng tiến thủ là không đếm được; thường đi với động từ to do.', 'Her childhood ambition was to design bridges across rivers.', NULL, 'Hoài bão thời thơ ấu của cô ấy là thiết kế những cây cầu bắc qua các con sông.', '{"wordId":"ambition","ukIpa":"/æmˈbɪʃən/","usIpa":"/æmˈbɪʃən/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"A strong desire to achieve a particular goal.","vi":"hoài bão; chí hướng"},{"pos":"n.","en":"Determination to become successful, powerful, or highly skilled.","vi":"lòng tiến thủ; sự tham vọng"}],"examples":[{"en":"Her childhood ambition was to design bridges across rivers.","vi":"Hoài bão thời thơ ấu của cô ấy là thiết kế những cây cầu bắc qua các con sông.","audioKind":"ex"},{"en":"Schools should nurture students'' ambition while helping them set realistic goals and develop practical skills.","vi":"Nhà trường nên nuôi dưỡng lòng tiến thủ của học sinh, đồng thời giúp các em thiết lập những mục tiêu thực tế và phát triển kỹ năng thực hành.","audioKind":"ex2"}],"collocations":[{"en":"achieve an ambition","vi":"đạt được hoài bão"},{"en":"lifelong ambition","vi":"hoài bão suốt đời"},{"en":"political ambition","vi":"tham vọng chính trị"},{"en":"ambition to succeed","vi":"khát vọng vươn tới thành công"}],"wordFamily":["ambitious (adj.)","ambitiously (adv.)"],"synonyms":["aspiration"],"antonyms":[],"tipVi":"Nghĩa chỉ mục tiêu cụ thể là danh từ đếm được, nghĩa chỉ lòng tiến thủ là không đếm được; thường đi với động từ to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_detective', 'en-b1-34', 'detective', '/dɪˈtektɪv/', 'B1', 'thám tử; trinh thám; cảnh sát điều tra', 'n.', 'detect (v.), detection (n.), detectable (adj.)', 'Đồng nghĩa: investigator', 'Trong detective novel, từ detective đóng vai trò là danh từ làm định ngữ.', 'The detective found a muddy footprint beside the window.', NULL, 'Viên thám tử tìm thấy một dấu chân dính bùn ở ngay cạnh cửa sổ.', '{"wordId":"detective","ukIpa":"/dɪˈtektɪv/","usIpa":"/dɪˈtektɪv/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"Someone whose job is to investigate crimes or discover facts","vi":"thám tử; trinh thám; cảnh sát điều tra"}],"examples":[{"en":"The detective found a muddy footprint beside the window.","vi":"Viên thám tử tìm thấy một dấu chân dính bùn ở ngay cạnh cửa sổ.","audioKind":"ex"},{"en":"Modern detectives increasingly rely on digital evidence, which raises important questions about privacy and data protection.","vi":"Các thám tử hiện đại ngày càng phụ thuộc vào chứng cứ kỹ thuật số, điều này đặt ra những vấn đề quan trọng về quyền riêng tư và bảo vệ dữ liệu.","audioKind":"ex2"}],"collocations":[{"en":"private detective","vi":"thám tử tư"},{"en":"detective work","vi":"công việc điều tra"},{"en":"detective novel","vi":"truyện trinh thám"}],"wordFamily":["detect (v.)","detection (n.)","detectable (adj.)"],"synonyms":["investigator"],"antonyms":[],"tipVi":"Trong detective novel, từ detective đóng vai trò là danh từ làm định ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clerk', 'en-b1-34', 'clerk', '/klɝːk/', 'B1', 'nhân viên văn phòng; thư ký; nhân viên lưu trữ hồ sơ; nhân viên bán hàng; nhân viên tiếp khách; lễ tân', 'n.', 'clerical (adj.)', NULL, 'Trong tiếng Anh-Anh, nguyên âm thường phát âm là /ɑː/; trong tiếng Anh-Mỹ, từ này thường chỉ nhân viên cửa hàng.', 'The clerk checked my details and handed me a form.', NULL, 'Nhân viên văn phòng đã kiểm tra thông tin chi tiết của tôi và đưa cho tôi một tờ đơn.', '{"wordId":"clerk","ukIpa":"/klɑːk/","usIpa":"/klɝːk/","cefr":"B1","topic":"work","senses":[{"pos":"n.","en":"someone whose job involves records, documents, or routine office tasks","vi":"nhân viên văn phòng; thư ký; nhân viên lưu trữ hồ sơ"},{"pos":"n.","en":"someone serving customers in a shop or at a desk","vi":"nhân viên bán hàng; nhân viên tiếp khách; lễ tân"}],"examples":[{"en":"The clerk checked my details and handed me a form.","vi":"Nhân viên văn phòng đã kiểm tra thông tin chi tiết của tôi và đưa cho tôi một tờ đơn.","audioKind":"ex"},{"en":"Although digital services are expanding, many residents still prefer discussing complex applications with a trained clerk.","vi":"Mặc dù các dịch vụ kỹ thuật số đang ngày càng mở rộng, nhiều người dân vẫn thích trao đổi các thủ tục phức tạp với một nhân viên đã được đào tạo bài bản hơn.","audioKind":"ex2"}],"collocations":[{"en":"office clerk","vi":"nhân viên văn phòng"},{"en":"bank clerk","vi":"nhân viên ngân hàng"},{"en":"desk clerk","vi":"nhân viên lễ tân"},{"en":"court clerk","vi":"thư ký tòa án"}],"wordFamily":["clerical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, nguyên âm thường phát âm là /ɑː/; trong tiếng Anh-Mỹ, từ này thường chỉ nhân viên cửa hàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_retire', 'en-b1-34', 'retire', '/rɪˈtaɪr/', 'B1', 'nghỉ hưu; rút lui khỏi cuộc thi', 'v.', 'retirement (n.), retired (adj.)', NULL, 'Retire là động từ; danh từ chỉ việc "nghỉ hưu" là retirement.', 'My aunt plans to retire and spend more time gardening.', NULL, 'Cô tôi dự định nghỉ hưu và dành nhiều thời gian hơn cho việc làm vườn.', '{"wordId":"retire","ukIpa":"/rɪˈtaɪə/","usIpa":"/rɪˈtaɪr/","cefr":"B1","topic":"work","senses":[{"pos":"v.","en":"To stop working permanently, usually because of age.","vi":"nghỉ hưu"},{"pos":"v.","en":"To leave a competition before finishing it.","vi":"rút lui khỏi cuộc thi"}],"examples":[{"en":"My aunt plans to retire and spend more time gardening.","vi":"Cô tôi dự định nghỉ hưu và dành nhiều thời gian hơn cho việc làm vườn.","audioKind":"ex"},{"en":"As life expectancy increases, some governments encourage people to retire later to reduce pressure on pension systems.","vi":"Khi tuổi thọ tăng lên, một số chính phủ khuyến khích người dân nghỉ hưu muộn hơn để giảm bớt áp lực lên hệ thống hưu trí.","audioKind":"ex2"}],"collocations":[{"en":"retire early","vi":"nghỉ hưu sớm"},{"en":"retire from work","vi":"nghỉ việc về hưu"},{"en":"retire from a race","vi":"rút khỏi cuộc đua"}],"wordFamily":["retirement (n.)","retired (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Retire là động từ; danh từ chỉ việc \"nghỉ hưu\" là retirement.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_achieve', 'en-b1-34', 'achieve', '/əˈtʃiːv/', 'B1', 'đạt được; giành được; hoàn thành', 'v.', 'achievement (n.), achievable (adj.), achiever (n.)', 'Đồng nghĩa: accomplish, attain', 'Đi thẳng với mục tiêu hoặc kết quả, không dùng achieve to do.', 'With daily practice, she finally achieved her swimming goal.', NULL, 'Nhờ tập luyện mỗi ngày, cô ấy cuối cùng đã đạt được mục tiêu bơi lội của mình.', '{"wordId":"achieve","ukIpa":"/əˈtʃiːv/","usIpa":"/əˈtʃiːv/","cefr":"B1","topic":"work","senses":[{"pos":"v.","en":"Successfully reach a goal or result through effort.","vi":"đạt được; giành được; hoàn thành"}],"examples":[{"en":"With daily practice, she finally achieved her swimming goal.","vi":"Nhờ tập luyện mỗi ngày, cô ấy cuối cùng đã đạt được mục tiêu bơi lội của mình.","audioKind":"ex"},{"en":"Governments can achieve significant reductions in air pollution by investing in clean energy and improving public transport.","vi":"Các chính phủ có thể giảm thiểu đáng kể tình trạng ô nhiễm không khí bằng cách đầu tư vào năng lượng sạch và cải thiện giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"achieve success","vi":"đạt được thành công"},{"en":"achieve a goal","vi":"đạt được mục tiêu"},{"en":"achieve a balance","vi":"đạt được sự cân bằng"},{"en":"achieve results","vi":"đạt được kết quả"}],"wordFamily":["achievement (n.)","achievable (adj.)","achiever (n.)"],"synonyms":["accomplish","attain"],"antonyms":[],"tipVi":"Đi thẳng với mục tiêu hoặc kết quả, không dùng achieve to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_valuable', 'en-b1-34', 'valuable', '/ˈvæljuəbl/', 'B1', 'có giá trị; rất hữu ích, quan trọng; có giá trị cao; đắt tiền, quý giá', 'adj.', 'value (n.), valuation (n.), invaluable (adj.), valuables (n.)', 'Đồng nghĩa: useful, precious · Trái nghĩa: worthless', 'Đồ vật có giá trị thường dùng dạng số nhiều valuables; từ invaluable có nghĩa là vô giá, cực kỳ quý giá.', 'My neighbour gave me valuable advice about growing tomatoes.', NULL, 'Người hàng xóm đã cho tôi những lời khuyên bổ ích về việc trồng cà chua.', '{"wordId":"valuable","ukIpa":"/ˈvæljuəbl/","usIpa":"/ˈvæljuəbl/","cefr":"B1","topic":"work","senses":[{"pos":"adj.","en":"Very useful or important for a particular purpose.","vi":"có giá trị; rất hữu ích, quan trọng"},{"pos":"adj.","en":"Worth a large amount of money.","vi":"có giá trị cao; đắt tiền, quý giá"}],"examples":[{"en":"My neighbour gave me valuable advice about growing tomatoes.","vi":"Người hàng xóm đã cho tôi những lời khuyên bổ ích về việc trồng cà chua.","audioKind":"ex"},{"en":"Work placements provide valuable experience that helps students develop practical skills before entering full-time employment.","vi":"Các chương trình thực tập mang lại kinh nghiệm quý báu giúp học sinh, sinh viên phát triển các kỹ năng thực tế trước khi bước vào thị trường lao động toàn thời gian.","audioKind":"ex2"}],"collocations":[{"en":"valuable experience","vi":"kinh nghiệm quý báu"},{"en":"valuable advice","vi":"lời khuyên bổ ích"},{"en":"a valuable contribution","vi":"sự đóng góp quan trọng"},{"en":"valuable jewellery","vi":"trang sức quý giá"}],"wordFamily":["value (n.)","valuation (n.)","invaluable (adj.)","valuables (n.)"],"synonyms":["useful","precious"],"antonyms":["worthless"],"tipVi":"Đồ vật có giá trị thường dùng dạng số nhiều valuables; từ invaluable có nghĩa là vô giá, cực kỳ quý giá.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_34_1', 'en-b1-34', 'Cách dùng “ambition” (n.) — hoài bão; chí hướng', 'achieve an ambition  ·  lifelong ambition  ·  political ambition', 'Nghĩa chỉ mục tiêu cụ thể là danh từ đếm được, nghĩa chỉ lòng tiến thủ là không đếm được; thường đi với động từ to do.', 'Họ từ (Word Family): ambitious (adj.), ambitiously (adv.) | Đồng nghĩa: aspiration', '[{"hanzi":"Her childhood ambition was to design bridges across rivers.","pinyin":"","meaning":"Hoài bão thời thơ ấu của cô ấy là thiết kế những cây cầu bắc qua các con sông."},{"hanzi":"Schools should nurture students'' ambition while helping them set realistic goals and develop practical skills.","pinyin":"","meaning":"Nhà trường nên nuôi dưỡng lòng tiến thủ của học sinh, đồng thời giúp các em thiết lập những mục tiêu thực tế và phát triển kỹ năng thực hành."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_34_2', 'en-b1-34', 'Cách dùng “clerk” (n.) — nhân viên văn phòng; thư ký; nhân viên lưu trữ hồ sơ', 'office clerk  ·  bank clerk  ·  desk clerk', 'Trong tiếng Anh-Anh, nguyên âm thường phát âm là /ɑː/; trong tiếng Anh-Mỹ, từ này thường chỉ nhân viên cửa hàng.', 'Họ từ (Word Family): clerical (adj.)', '[{"hanzi":"The clerk checked my details and handed me a form.","pinyin":"","meaning":"Nhân viên văn phòng đã kiểm tra thông tin chi tiết của tôi và đưa cho tôi một tờ đơn."},{"hanzi":"Although digital services are expanding, many residents still prefer discussing complex applications with a trained clerk.","pinyin":"","meaning":"Mặc dù các dịch vụ kỹ thuật số đang ngày càng mở rộng, nhiều người dân vẫn thích trao đổi các thủ tục phức tạp với một nhân viên đã được đào tạo bài bản hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_34_3', 'en-b1-34', 'Cách dùng “duty” (n.) — trách nhiệm; bổn phận', 'a sense of duty  ·  on duty  ·  import duty', 'Cụm on duty có nghĩa là đang làm nhiệm vụ; các nhiệm vụ công việc cụ thể thường dùng dạng số nhiều duties.', 'Họ từ (Word Family): dutiful (adj.), dutifully (adv.), duty-free (adj.) | Đồng nghĩa: responsibility, obligation', '[{"hanzi":"It is my duty to keep these animals safe.","pinyin":"","meaning":"Bảo vệ sự an toàn cho những loài động vật này là bổn phận của tôi."},{"hanzi":"Governments have a duty to protect vulnerable citizens while ensuring that public services remain financially sustainable.","pinyin":"","meaning":"Chính phủ có trách nhiệm bảo vệ những công dân dễ bị tổn thương đồng thời đảm bảo các dịch vụ công duy trì được sự bền vững về tài chính."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_34_4', 'en-b1-34', 'Cách dùng “valuable” (adj.) — có giá trị; rất hữu ích, quan trọng', 'valuable experience  ·  valuable advice  ·  a valuable contribution', 'Đồ vật có giá trị thường dùng dạng số nhiều valuables; từ invaluable có nghĩa là vô giá, cực kỳ quý giá.', 'Họ từ (Word Family): value (n.), valuation (n.), invaluable (adj.), valuables (n.) | Đồng nghĩa: useful, precious · Trái nghĩa: worthless', '[{"hanzi":"My neighbour gave me valuable advice about growing tomatoes.","pinyin":"","meaning":"Người hàng xóm đã cho tôi những lời khuyên bổ ích về việc trồng cà chua."},{"hanzi":"Work placements provide valuable experience that helps students develop practical skills before entering full-time employment.","pinyin":"","meaning":"Các chương trình thực tập mang lại kinh nghiệm quý báu giúp học sinh, sinh viên phát triển các kỹ năng thực tế trước khi bước vào thị trường lao động toàn thời gian."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_34_1', 'en-b1-34', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_1_1', 'ten_b1_34_1', 'crew', 'The crew welcomed us aboard with warm smiles.', 'The crew welcomed us aboard with warm smiles.', '/kruː/', 'Tổ bay đã chào đón chúng tôi lên máy bay với những nụ cười ấm áp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_1_2', 'ten_b1_34_1', 'cashier', 'The cashier smiled and handed me my change.', 'The cashier smiled and handed me my change.', '/kæˈʃɪr/', 'Cô thu ngân mỉm cười và đưa lại tiền thừa cho tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_1_3', 'ten_b1_34_1', 'impress', 'Her homemade bread impressed everyone at the family dinner.', 'Her homemade bread impressed everyone at the family dinner.', '/ɪmˈpres/', 'Món bánh mì tự làm của cô ấy đã gây ấn tượng với tất cả mọi người trong bữa tối gia đình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_1_4', 'ten_b1_34_1', 'expert', 'We asked an expert to examine the old painting.', 'We asked an expert to examine the old painting.', '/ˈekspɝːt/', 'Chúng tôi đã mời một chuyên gia đến kiểm tra bức tranh cũ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_1_5', 'ten_b1_34_1', 'process', 'Making bread is a slow process, but I enjoy it.', 'Making bread is a slow process, but I enjoy it.', '/ˈprɑːses/', 'Làm bánh mì là một quá trình chậm rãi, nhưng tôi rất thích nó.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_1_6', 'ten_b1_34_1', 'deliver', 'The bakery delivers warm bread to our door every morning.', 'The bakery delivers warm bread to our door every morning.', '/dɪˈlɪvər/', 'Tiệm bánh giao những chiếc bánh mì ấm nóng đến tận cửa nhà chúng tôi mỗi buổi sáng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_1_7', 'ten_b1_34_1', 'inform', 'Please inform the receptionist if you lose your key.', 'Please inform the receptionist if you lose your key.', '/ɪnˈfɔːrm/', 'Vui lòng thông báo cho lễ tân nếu bạn làm mất chìa khóa.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_1_8', 'ten_b1_34_1', 'hire', 'We hired a van to move our furniture.', 'We hired a van to move our furniture.', '/ˈhaɪr/', 'Chúng tôi đã thuê một chiếc xe tải để chuyển đồ đạc.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_34_1_1', 'en-b1-34', 'ten_b1_34_1', 'listening', 'listening', 'The crew welcomed us aboard with warm smiles.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã mời một chuyên gia đến kiểm tra bức tranh cũ.","Hoài bão thời thơ ấu của cô ấy là thiết kế những cây cầu bắc qua các con sông.","Tổ bay đã chào đón chúng tôi lên máy bay với những nụ cười ấm áp.","Người hàng xóm đã cho tôi những lời khuyên bổ ích về việc trồng cà chua."]'::jsonb, 2, 'The crew welcomed us aboard with warm smiles. → Tổ bay đã chào đón chúng tôi lên máy bay với những nụ cười ấm áp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_34_1_2', 'en-b1-34', 'ten_b1_34_1', 'listening', 'listening', 'The cashier smiled and handed me my change.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Viên thám tử tìm thấy một dấu chân dính bùn ở ngay cạnh cửa sổ.","Cô thu ngân mỉm cười và đưa lại tiền thừa cho tôi.","Nhờ tập luyện mỗi ngày, cô ấy cuối cùng đã đạt được mục tiêu bơi lội của mình.","Bác sĩ thú y nhẹ nhàng kiểm tra tai và bàn chân chú chó con của chúng tôi."]'::jsonb, 1, 'The cashier smiled and handed me my change. → Cô thu ngân mỉm cười và đưa lại tiền thừa cho tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_34_1_3', 'en-b1-34', 'ten_b1_34_1', 'listening', 'listening', 'Her homemade bread impressed everyone at the family dinner.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã mời một chuyên gia đến kiểm tra bức tranh cũ.","Nhân viên văn phòng đã kiểm tra thông tin chi tiết của tôi và đưa cho tôi một tờ đơn.","Món bánh mì tự làm của cô ấy đã gây ấn tượng với tất cả mọi người trong bữa tối gia đình.","Bạn có thể đưa cho tôi chiếc dập ghim bên cạnh cuốn sổ tay được không?"]'::jsonb, 2, 'Her homemade bread impressed everyone at the family dinner. → Món bánh mì tự làm của cô ấy đã gây ấn tượng với tất cả mọi người trong bữa tối gia đình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_34_2', 'en-b1-34', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_2_1', 'ten_b1_34_2', 'crew', 'Airlines must ensure that every crew member receives regular safety training to protect passengers during emergencies.', 'Airlines must ensure that every crew member receives regular safety training to protect passengers during emergencies.', '/kruː/', 'Các hãng hàng không phải đảm bảo rằng mọi thành viên phi hành đoàn đều được đào tạo an toàn thường xuyên để bảo vệ hành khách trong các tình huống khẩn cấp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_2_2', 'ten_b1_34_2', 'cashier', 'Automated checkouts may reduce demand for cashiers, although many customers still prefer assistance from a person.', 'Automated checkouts may reduce demand for cashiers, although many customers still prefer assistance from a person.', '/kæˈʃɪr/', 'Các quầy thanh toán tự động có thể làm giảm nhu cầu về nhân viên thu ngân, mặc dù nhiều khách hàng vẫn thích sự hỗ trợ từ con người hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_2_3', 'ten_b1_34_2', 'impress', 'Applicants can impress potential employers by explaining how their practical experience matches the requirements of the role.', 'Applicants can impress potential employers by explaining how their practical experience matches the requirements of the role.', '/ɪmˈpres/', 'Ứng viên có thể gây ấn tượng với nhà tuyển dụng tiềm năng bằng cách giải thích kinh nghiệm thực tế của họ phù hợp với yêu cầu công việc như thế nào.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_2_4', 'ten_b1_34_2', 'expert', 'Schools should seek expert advice before introducing new technology into classrooms to support student learning.', 'Schools should seek expert advice before introducing new technology into classrooms to support student learning.', '/ˈekspɝːt/', 'Các trường học nên tham khảo ý kiến chuyên gia trước khi đưa công nghệ mới vào lớp học để hỗ trợ học sinh học tập.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_2_5', 'ten_b1_34_2', 'process', 'The application process should be transparent so that all candidates have an equal opportunity to participate.', 'The application process should be transparent so that all candidates have an equal opportunity to participate.', '/ˈprɑːses/', 'Quy trình nộp đơn nên minh bạch để tất cả các ứng viên đều có cơ hội tham gia công bằng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_34_2_6', 'ten_b1_34_2', 'deliver', 'Public transport projects must deliver clear benefits to local residents if they are to justify substantial investment.', 'Public transport projects must deliver clear benefits to local residents if they are to justify substantial investment.', '/dɪˈlɪvər/', 'Các dự án giao thông công cộng phải mang lại những lợi ích rõ ràng cho người dân địa phương thì mới biện minh được cho khoản đầu tư lớn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_34_2_1', 'en-b1-34', 'ten_b1_34_2', 'listening', 'listening', 'Airlines must ensure that every crew member receives regular safety training to protect passengers during emergencies.', NULL, 'Trong câu vừa nghe, từ “crew” mang nghĩa nào sau đây?', '["sự cas cánh; lúc cất cánh","đội ngũ nhân viên trên tàu hoặc máy bay","làm cho phấn khích; làm cho hào hứng","thành thật; trung thực"]'::jsonb, 1, '“crew” (/kruː/): đội ngũ nhân viên trên tàu hoặc máy bay. Câu đầy đủ: Airlines must ensure that every crew member receives regular safety training to protect passengers during emergencies.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_34_2_2', 'en-b1-34', 'ten_b1_34_2', 'listening', 'listening', 'Automated checkouts may reduce demand for cashiers, although many customers still prefer assistance from a person.', NULL, 'Trong câu vừa nghe, từ “cashier” mang nghĩa nào sau đây?', '["nhân viên thu ngân; thâu ngân viên","nơi; địa điểm; chốn","tự động","người hướng dẫn; huấn luyện viên"]'::jsonb, 0, '“cashier” (/kæˈʃɪr/): nhân viên thu ngân; thâu ngân viên. Câu đầy đủ: Automated checkouts may reduce demand for cashiers, although many customers still prefer assistance from a person.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
