INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_1', 'en-b1-34', NULL, 'comprehensive_test', 'listening', 'crew', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["la lớn; hét lớn","vật liệu; nguyên liệu; vải vóc","đội ngũ nhân viên trên tàu hoặc máy bay","mỹ phẩm; đồ trang điểm"]'::jsonb, 2, 'crew (/kruː/) → đội ngũ nhân viên trên tàu hoặc máy bay; nhóm làm việc chung trong một nhiệm vụ thực tế; làm thành viên đoàn tàu thuyền', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_2', 'en-b1-34', NULL, 'comprehensive_test', 'listening', 'The cashier smiled and handed me my change.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Viên thám tử tìm thấy một dấu chân dính bùn ở ngay cạnh cửa sổ.","Nhân viên văn phòng đã kiểm tra thông tin chi tiết của tôi và đưa cho tôi một tờ đơn.","Cô thu ngân mỉm cười và đưa lại tiền thừa cho tôi.","Thực tập sinh đứng quan sát chăm chú khi đầu bếp cắt rau củ."]'::jsonb, 2, 'The cashier smiled and handed me my change. → Cô thu ngân mỉm cười và đưa lại tiền thừa cho tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_3', 'en-b1-34', NULL, 'comprehensive_test', 'listening', 'impress', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tơ tằm; lụa; vải lụa","khác với","làm cho ai đó ấn tượng; gây ấn tượng sâu sắc","triệu chứng"]'::jsonb, 2, 'impress (/ɪmˈpres/) → làm cho ai đó ấn tượng; gây ấn tượng sâu sắc; làm cho ai đó nhận thức rõ tầm quan trọng của việc gì', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_4', 'en-b1-34', NULL, 'comprehensive_test', 'listening', 'We asked an expert to examine the old painting.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Làm bánh mì là một quá trình chậm rãi, nhưng tôi rất thích nó.","Bác sĩ thú y nhẹ nhàng kiểm tra tai và bàn chân chú chó con của chúng tôi.","Chúng tôi đã mời một chuyên gia đến kiểm tra bức tranh cũ.","Cô thu ngân mỉm cười và đưa lại tiền thừa cho tôi."]'::jsonb, 2, 'We asked an expert to examine the old painting. → Chúng tôi đã mời một chuyên gia đến kiểm tra bức tranh cũ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_5', 'en-b1-34', NULL, 'comprehensive_test', 'listening', 'process', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc về âm nhạc cổ điển","bằng len; làm từ len","quá trình; quy trình","kiến trúc học; nghệ thuật kiến trúc"]'::jsonb, 2, 'process (/ˈprɑːses/) → quá trình; quy trình; xử lý; gia công', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_6', 'en-b1-34', NULL, 'comprehensive_test', 'listening', 'The bakery delivers warm bread to our door every morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bạn có thể đưa cho tôi chiếc dập ghim bên cạnh cuốn sổ tay được không?","Tôi đã gửi đơn xin việc của mình trước bữa sáng vào sáng nay.","Chúng tôi đã mời một chuyên gia đến kiểm tra bức tranh cũ.","Tiệm bánh giao những chiếc bánh mì ấm nóng đến tận cửa nhà chúng tôi mỗi buổi sáng."]'::jsonb, 3, 'The bakery delivers warm bread to our door every morning. → Tiệm bánh giao những chiếc bánh mì ấm nóng đến tận cửa nhà chúng tôi mỗi buổi sáng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
