INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_8', 'en-b1-34', NULL, 'comprehensive_test', 'listening', 'We hired a van to move our furniture.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hàng xóm của tôi đã thất nghiệp từ khi nhà máy đóng cửa.","Thực tập sinh đứng quan sát chăm chú khi đầu bếp cắt rau củ.","Chúng tôi đã thuê một chiếc xe tải để chuyển đồ đạc.","Tôi đã gửi đơn xin việc của mình trước bữa sáng vào sáng nay."]'::jsonb, 2, 'We hired a van to move our furniture. → Chúng tôi đã thuê một chiếc xe tải để chuyển đồ đạc.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
