INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_18', 'en-b1-34', NULL, 'comprehensive_test', 'reading', NULL, 'Airlines must ensure that every crew member receives regular safety training to protect passengers during emergencies.', 'Dựa vào câu trên, từ “crew” có nghĩa phù hợp nhất là gì?', '["đội ngũ nhân viên trên tàu hoặc máy bay","chu kỳ; vòng tuần hoàn","sự tiến bộ; sự phát triển","loạt; chuỗi; dải (các sự việc, sự kiện liên tiếp)"]'::jsonb, 0, 'crew: đội ngũ nhân viên trên tàu hoặc máy bay; nhóm làm việc chung trong một nhiệm vụ thực tế; làm thành viên đoàn tàu thuyền. Dịch cả câu: Các hãng hàng không phải đảm bảo rằng mọi thành viên phi hành đoàn đều được đào tạo an toàn thường xuyên để bảo vệ hành khách trong các tình huống khẩn cấp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_19', 'en-b1-34', NULL, 'comprehensive_test', 'reading', NULL, 'Automated checkouts may reduce demand for cashiers, although many customers still prefer assistance from a person.', 'Dựa vào câu trên, từ “cashier” có nghĩa phù hợp nhất là gì?', '["chung; phổ biến; toàn thể","bữa điểm tâm muộn; bữa sáng kết hợp bữa trưa","thất vọng; buồn bã","nhân viên thu ngân; thâu ngân viên"]'::jsonb, 3, 'cashier: nhân viên thu ngân; thâu ngân viên. Dịch cả câu: Các quầy thanh toán tự động có thể làm giảm nhu cầu về nhân viên thu ngân, mặc dù nhiều khách hàng vẫn thích sự hỗ trợ từ con người hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_20', 'en-b1-34', NULL, 'comprehensive_test', 'reading', NULL, 'Applicants can impress potential employers by explaining how their practical experience matches the requirements of the role.', 'Dựa vào câu trên, từ “impress” có nghĩa phù hợp nhất là gì?', '["làm cho ai đó ấn tượng; gây ấn tượng sâu sắc","chương (sách); hồi","thợ sửa chữa; thợ máy","tài năng; khiếu"]'::jsonb, 0, 'impress: làm cho ai đó ấn tượng; gây ấn tượng sâu sắc; làm cho ai đó nhận thức rõ tầm quan trọng của việc gì. Dịch cả câu: Ứng viên có thể gây ấn tượng với nhà tuyển dụng tiềm năng bằng cách giải thích kinh nghiệm thực tế của họ phù hợp với yêu cầu công việc như thế nào.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_21', 'en-b1-34', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should seek expert advice before introducing new technology into classrooms to support student learning.', 'Dựa vào câu trên, từ “expert” có nghĩa phù hợp nhất là gì?', '["sự liên lạc; sự tiếp xúc","tác động; hiệu quả","tuân theo; vâng lời; chấp hành","chuyên gia; người có chuyên môn sâu"]'::jsonb, 3, 'expert: chuyên gia; người có chuyên môn sâu; chuyên môn; có tay nghề cao. Dịch cả câu: Các trường học nên tham khảo ý kiến chuyên gia trước khi đưa công nghệ mới vào lớp học để hỗ trợ học sinh học tập.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_22', 'en-b1-34', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nghỉ hưu”', '["retire","cave","tin","translate"]'::jsonb, 0, 'nghỉ hưu → retire (/rɪˈtaɪr/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_23', 'en-b1-34', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đạt được; giành được; hoàn thành”', '["vanilla","achieve","agent","preposition"]'::jsonb, 1, 'đạt được; giành được; hoàn thành → achieve (/əˈtʃiːv/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_34_24', 'en-b1-34', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có giá trị; rất hữu ích, quan trọng”', '["valuable","impression","Atlantic","bandage"]'::jsonb, 0, 'có giá trị; rất hữu ích, quan trọng → valuable (/ˈvæljuəbl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-35', 'en', 'Bài 35: Kinh tế & Tài chính (1) - CEFR B1', 'CEFR B1', 'B1 · Kinh tế', '21 từ vựng Tiếng Anh CEFR B1 chủ đề kinh tế & tài chính kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3035, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_currency', 'en-b1-35', 'currency', '/ˈkɜːrənsi/', 'B1', 'tiền tệ (được sử dụng ở một quốc gia cụ thể); sự lưu hành, sự thịnh hành (được chấp nhận hoặc sử dụng rộng rãi)', 'n.', NULL, NULL, 'Tên các loại tiền tệ có thể đếm được; còn khi chỉ chung khái niệm tiền tệ thì thường không đếm được.', 'We exchanged our money for local currency at the airport.', NULL, 'Chúng tôi đã đổi tiền của mình lấy nội tệ tại sân bay.', '{"wordId":"currency","ukIpa":"/ˈkʌrənsi/","usIpa":"/ˈkɜːrənsi/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"The money used in a particular country.","vi":"tiền tệ (được sử dụng ở một quốc gia cụ thể)"},{"pos":"n.","en":"The state of being widely accepted or used.","vi":"sự lưu hành, sự thịnh hành (được chấp nhận hoặc sử dụng rộng rãi)"}],"examples":[{"en":"We exchanged our money for local currency at the airport.","vi":"Chúng tôi đã đổi tiền của mình lấy nội tệ tại sân bay.","audioKind":"ex"},{"en":"A weaker currency can attract international tourists by making accommodation and other services more affordable.","vi":"Đồng tiền yếu hơn có thể thu hút khách du lịch quốc tế bằng cách giúp chi phí lưu trú và các dịch vụ khác trở nên phải chăng hơn.","audioKind":"ex2"}],"collocations":[{"en":"foreign currency","vi":"ngoại tệ"},{"en":"local currency","vi":"nội tệ, tiền địa phương"},{"en":"currency exchange","vi":"đổi tiền tệ"},{"en":"gain currency","vi":"trở nên phổ biến, được ưa chuộng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên các loại tiền tệ có thể đếm được; còn khi chỉ chung khái niệm tiền tệ thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_development', 'en-b1-35', 'development', '/dɪˈveləpmənt/', 'B1', 'sự phát triển; sự lớn lên; sự chế tạo; sự tiến triển; biến động mới', 'n.', 'develop (v.), developer (n.), developing (adj.), developmental (adj.)', 'Đồng nghĩa: growth, progress', 'Khi dùng với nghĩa phát triển chung thường không đếm được; khi chỉ tiến triển mới thì đếm được.', 'Regular play supports a young child''s development in many ways.', NULL, 'Vui chơi thường xuyên hỗ trợ sự phát triển của trẻ nhỏ theo nhiều cách.', '{"wordId":"development","ukIpa":"/dɪˈveləpmənt/","usIpa":"/dɪˈveləpmənt/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"the process of growing, changing, or becoming more advanced","vi":"sự phát triển; sự lớn lên"},{"pos":"n.","en":"the process of creating or improving products, land, or services","vi":"sự phát triển; sự chế tạo"},{"pos":"n.","en":"a new event or change in a situation","vi":"sự tiến triển; biến động mới"}],"examples":[{"en":"Regular play supports a young child''s development in many ways.","vi":"Vui chơi thường xuyên hỗ trợ sự phát triển của trẻ nhỏ theo nhiều cách.","audioKind":"ex"},{"en":"Investment in public transport can support economic development while reducing traffic congestion in growing cities.","vi":"Đầu tư vào giao thông công cộng có thể hỗ trợ phát triển kinh tế đồng thời giảm thiểu tình trạng ùn tắc giao thông ở các đô thị đang mở rộng.","audioKind":"ex2"}],"collocations":[{"en":"economic development","vi":"phát triển kinh tế"},{"en":"child development","vi":"sự phát triển của trẻ em"},{"en":"product development","vi":"phát triển sản phẩm"},{"en":"sustainable development","vi":"phát triển bền vững"}],"wordFamily":["develop (v.)","developer (n.)","developing (adj.)","developmental (adj.)"],"synonyms":["growth","progress"],"antonyms":[],"tipVi":"Khi dùng với nghĩa phát triển chung thường không đếm được; khi chỉ tiến triển mới thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inexpensive', 'en-b1-35', 'inexpensive', '/ˌɪnɪkˈspensɪv/', 'B1', 'giá rẻ; không đắt', 'adj.', 'expensive (adj.), inexpensively (adv.), expense (n.)', 'Đồng nghĩa: affordable, cheap, low-cost · Trái nghĩa: expensive, costly', 'Mang tính trung lập hơn cheap và thường không ngụ ý là chất lượng kém.', 'We found an inexpensive café near the train station.', NULL, 'Chúng tôi tìm thấy một quán cà phê giá rẻ gần ga xe lửa.', '{"wordId":"inexpensive","ukIpa":"/ˌɪnɪkˈspensɪv/","usIpa":"/ˌɪnɪkˈspensɪv/","cefr":"B1","topic":"economy","senses":[{"pos":"adj.","en":"Not costing much money.","vi":"giá rẻ; không đắt"}],"examples":[{"en":"We found an inexpensive café near the train station.","vi":"Chúng tôi tìm thấy một quán cà phê giá rẻ gần ga xe lửa.","audioKind":"ex"},{"en":"Cycling offers an inexpensive alternative to driving and can help reduce traffic congestion in growing cities.","vi":"Đi xe đạp là một lựa chọn thay thế tiết kiệm cho việc lái xe và có thể giúp giảm ùn tắc giao thông ở các thành phố đang phát triển.","audioKind":"ex2"}],"collocations":[{"en":"inexpensive alternative","vi":"lựa chọn thay thế giá rẻ"},{"en":"relatively inexpensive","vi":"tương đối rẻ"},{"en":"inexpensive accommodation","vi":"chỗ ở giá rẻ"}],"wordFamily":["expensive (adj.)","inexpensively (adv.)","expense (n.)"],"synonyms":["affordable","cheap","low-cost"],"antonyms":["expensive","costly"],"tipVi":"Mang tính trung lập hơn cheap và thường không ngụ ý là chất lượng kém.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_supply', 'en-b1-35', 'supply', '/səˈplaɪ/', 'B1', 'cung cấp; cung ứng; nguồn cung; lượng dự trữ; vật tư; nhu yếu phẩm', 'v.', 'supplier (n.), resupply (v.)', 'Đồng nghĩa: provide', 'supply A with B bằng nghĩa supply B to A; vật tư thường dùng ở số nhiều supplies.', 'A nearby farm supplies fresh eggs to our shop.', NULL, 'Một trang trại gần đó cung cấp trứng tươi cho cửa hàng của chúng tôi.', '{"wordId":"supply","ukIpa":"/səˈplaɪ/","usIpa":"/səˈplaɪ/","cefr":"B1","topic":"economy","senses":[{"pos":"v.","en":"to provide something that someone needs","vi":"cung cấp; cung ứng"},{"pos":"n.","en":"the provision or available amount of something needed","vi":"nguồn cung; lượng dự trữ"},{"pos":"n.","en":"essential items kept or provided for use","vi":"vật tư; nhu yếu phẩm"}],"examples":[{"en":"A nearby farm supplies fresh eggs to our shop.","vi":"Một trang trại gần đó cung cấp trứng tươi cho cửa hàng của chúng tôi.","audioKind":"ex"},{"en":"Cities must secure a reliable water supply as population growth and climate change place increasing pressure on resources.","vi":"Các thành phố phải đảm bảo nguồn cung cấp nước ổn định khi sự gia tăng dân số và biến đổi khí hậu đặt ra áp lực ngày càng lớn lên các nguồn tài nguyên.","audioKind":"ex2"}],"collocations":[{"en":"supply someone with something","vi":"cung cấp cho ai cái gì"},{"en":"water supply","vi":"nguồn cung cấp nước"},{"en":"supply and demand","vi":"cung và cầu"},{"en":"medical supplies","vi":"vật tư y tế"}],"wordFamily":["supplier (n.)","resupply (v.)"],"synonyms":["provide"],"antonyms":[],"tipVi":"supply A with B bằng nghĩa supply B to A; vật tư thường dùng ở số nhiều supplies.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_income', 'en-b1-35', 'income', '/ˈɪnkʌm/', 'B1', 'thu nhập; tiền kiếm được', 'n.', NULL, 'Đồng nghĩa: earnings', 'income có phạm vi rộng hơn salary, bao gồm cả tiền thuê nhà, lợi nhuận đầu tư.', 'My weekend job gives me a small extra income.', NULL, 'Công việc làm thêm cuối tuần mang lại cho tôi một khoản thu nhập nhỏ phụ trội.', '{"wordId":"income","ukIpa":"/ˈɪnkʌm/","usIpa":"/ˈɪnkʌm/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"Money received regularly from work, investments, or other sources.","vi":"thu nhập; tiền kiếm được"}],"examples":[{"en":"My weekend job gives me a small extra income.","vi":"Công việc làm thêm cuối tuần mang lại cho tôi một khoản thu nhập nhỏ phụ trội.","audioKind":"ex"},{"en":"Affordable public transport allows families on low incomes to access employment and essential services more easily.","vi":"Giao thông công cộng giá rẻ giúp các gia đình có thu nhập thấp tiếp cận việc làm và các dịch vụ thiết yếu dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"low income","vi":"thu nhập thấp"},{"en":"household income","vi":"thu nhập hộ gia đình"},{"en":"disposable income","vi":"thu nhập khả dụng"},{"en":"source of income","vi":"nguồn thu nhập"}],"wordFamily":[],"synonyms":["earnings"],"antonyms":[],"tipVi":"income có phạm vi rộng hơn salary, bao gồm cả tiền thuê nhà, lợi nhuận đầu tư.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decrease', 'en-b1-35', 'decrease', '/dɪˈkriːs/', 'B1', 'giảm; làm giảm; sự giảm; mức giảm', 'v.', 'decreasing (adj.)', 'Đồng nghĩa: decline, reduce · Trái nghĩa: increase', 'Động từ decrease trọng âm ở âm tiết sau, còn danh từ /ˈdiːkriːs/ trọng âm ở âm tiết đầu.', 'Our electricity bills decreased after we replaced the old heater.', NULL, 'Hóa đơn tiền điện của chúng tôi đã giảm sau khi chúng tôi thay chiếc máy sưởi cũ.', '{"wordId":"decrease","ukIpa":"/dɪˈkriːs/","usIpa":"/dɪˈkriːs/","cefr":"B1","topic":"economy","senses":[{"pos":"v.","en":"To become smaller or make something smaller in amount.","vi":"giảm; làm giảm"},{"pos":"n.","en":"A reduction in the size, number, or amount of something.","vi":"sự giảm; mức giảm"}],"examples":[{"en":"Our electricity bills decreased after we replaced the old heater.","vi":"Hóa đơn tiền điện của chúng tôi đã giảm sau khi chúng tôi thay chiếc máy sưởi cũ.","audioKind":"ex"},{"en":"Improved public transport could decrease traffic congestion and reduce air pollution in densely populated cities.","vi":"Việc cải thiện giao thông công cộng có thể làm giảm tình trạng ùn tắc giao thông và cắt giảm ô nhiễm không khí ở các thành phố đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"a decrease in demand","vi":"nhu cầu giảm"},{"en":"decrease significantly","vi":"giảm đáng kể"},{"en":"decrease by half","vi":"giảm một nửa"},{"en":"a steady decrease","vi":"sự giảm đều đặn"}],"wordFamily":["decreasing (adj.)"],"synonyms":["decline","reduce"],"antonyms":["increase"],"tipVi":"Động từ decrease trọng âm ở âm tiết sau, còn danh từ /ˈdiːkriːs/ trọng âm ở âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_afford', 'en-b1-35', 'afford', '/əˈfɔːrd/', 'B1', 'có đủ khả năng chi trả; mua nổi; mang lại; đem lại', 'v.', 'affordable (adj.), affordability (n.)', NULL, 'Thường dùng can afford sth hoặc can afford to do, không đi với dạng doing.', 'We cannot afford a new sofa this month.', NULL, 'Tháng này chúng tôi không đủ tiền mua chiếc ghế sofa mới.', '{"wordId":"afford","ukIpa":"/əˈfɔːd/","usIpa":"/əˈfɔːrd/","cefr":"B1","topic":"economy","senses":[{"pos":"v.","en":"to have enough money or resources for something","vi":"có đủ khả năng chi trả; mua nổi"},{"pos":"v.","en":"to provide something useful or desirable","vi":"mang lại; đem lại"}],"examples":[{"en":"We cannot afford a new sofa this month.","vi":"Tháng này chúng tôi không đủ tiền mua chiếc ghế sofa mới.","audioKind":"ex"},{"en":"Without financial assistance, many students cannot afford to attend university despite having strong academic potential.","vi":"Nếu không có hỗ trợ tài chính, nhiều sinh viên không thể kham nổi chi phí học đại học dù có tiềm năng học tập xuất sắc.","audioKind":"ex2"}],"collocations":[{"en":"can afford to do","vi":"có đủ khả năng làm gì"},{"en":"cannot afford to lose","vi":"không thể gánh chịu sự mất mát"},{"en":"afford protection","vi":"cung cấp sự bảo vệ"}],"wordFamily":["affordable (adj.)","affordability (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng can afford sth hoặc can afford to do, không đi với dạng doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_economics', 'en-b1-35', 'economics', '/ˌiːkəˈnɑːmɪks/', 'B1', 'kinh tế học; các yếu tố kinh tế; tính kinh tế', 'n.', 'economy (n.), economist (n.), economic (adj.), economically (adv.)', NULL, 'Khi chỉ tên môn học, dù có tận cùng bằng chữ s, từ này vẫn đi với động từ số ít.', 'My sister studies economics and enjoys discussing food prices.', NULL, 'Chị gái tôi học ngành kinh tế học và rất thích thảo luận về giá cả thực phẩm.', '{"wordId":"economics","ukIpa":"/ˌiːkəˈnɒmɪks/","usIpa":"/ˌiːkəˈnɑːmɪks/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"The study of how societies produce, distribute, and use resources.","vi":"kinh tế học"},{"pos":"n.","en":"The financial factors affecting whether an activity is practical.","vi":"các yếu tố kinh tế; tính kinh tế"}],"examples":[{"en":"My sister studies economics and enjoys discussing food prices.","vi":"Chị gái tôi học ngành kinh tế học và rất thích thảo luận về giá cả thực phẩm.","audioKind":"ex"},{"en":"Studying economics helps students understand how government policies influence employment, inflation, and the distribution of wealth.","vi":"Việc học kinh tế học giúp sinh viên hiểu cách các chính sách của chính phủ chi phối việc làm, lạm phát và sự phân phối của cải.","audioKind":"ex2"}],"collocations":[{"en":"study economics","vi":"học kinh tế học"},{"en":"behavioural economics","vi":"kinh tế học hành vi"},{"en":"the economics of recycling","vi":"tính kinh tế của việc tái chế"}],"wordFamily":["economy (n.)","economist (n.)","economic (adj.)","economically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ tên môn học, dù có tận cùng bằng chữ s, từ này vẫn đi với động từ số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_industry', 'en-b1-35', 'industry', '/ˈɪndəstri/', 'B1', 'công nghiệp; kỹ nghệ; ngành công nghiệp; lĩnh vực kinh doanh; sự siêng năng; sự cần cù', 'n.', 'industrial (adj.), industrialise (v.), industrialisation (n.), industrious (adj.)', NULL, 'Tính từ chỉ công nghiệp là industrial; tính từ chỉ sự siêng năng là industrious.', 'The fishing industry provides jobs for many local families.', NULL, 'Ngành đánh bắt cá tạo ra việc làm cho nhiều gia đình địa phương.', '{"wordId":"industry","ukIpa":"/ˈɪndəstri/","usIpa":"/ˈɪndəstri/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"the production of goods in factories","vi":"công nghiệp; kỹ nghệ"},{"pos":"n.","en":"businesses that provide a particular type of product or service","vi":"ngành công nghiệp; lĩnh vực kinh doanh"},{"pos":"n.","en":"steady effort and hard work","vi":"sự siêng năng; sự cần cù"}],"examples":[{"en":"The fishing industry provides jobs for many local families.","vi":"Ngành đánh bắt cá tạo ra việc làm cho nhiều gia đình địa phương.","audioKind":"ex"},{"en":"Investment in cleaner technology could help heavy industry reduce emissions without significantly lowering production levels.","vi":"Việc đầu tư vào công nghệ sạch hơn có thể giúp ngành công nghiệp nặng giảm phát thải mà không làm giảm đáng kể mức độ sản xuất.","audioKind":"ex2"}],"collocations":[{"en":"heavy industry","vi":"công nghiệp nặng"},{"en":"the tourism industry","vi":"ngành du lịch"},{"en":"the manufacturing industry","vi":"ngành chế tạo"},{"en":"industrial development","vi":"phát triển công nghiệp"}],"wordFamily":["industrial (adj.)","industrialise (v.)","industrialisation (n.)","industrious (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tính từ chỉ công nghiệp là industrial; tính từ chỉ sự siêng năng là industrious.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rate', 'en-b1-35', 'rate', '/reɪt/', 'B1', 'tỷ lệ; tốc độ; mức giá; biểu phí; đánh giá; xếp hạng', 'n.', 'rating (n.), rated (adj.)', NULL, 'rate có thể chỉ tỷ lệ hoặc đơn giá; dùng rate khi muốn đánh giá chất lượng của một vật.', 'This hotel offers a cheaper rate during the winter.', NULL, 'Khách sạn này có mức giá rẻ hơn vào mùa đông.', '{"wordId":"rate","ukIpa":"/reɪt/","usIpa":"/reɪt/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"How often something happens or how quickly something changes.","vi":"tỷ lệ; tốc độ"},{"pos":"n.","en":"An amount charged or paid for a particular unit.","vi":"mức giá; biểu phí"},{"pos":"v.","en":"To judge the quality, value, or level of something.","vi":"đánh giá; xếp hạng"}],"examples":[{"en":"This hotel offers a cheaper rate during the winter.","vi":"Khách sạn này có mức giá rẻ hơn vào mùa đông.","audioKind":"ex"},{"en":"Cities with reliable public transport often experience lower rates of car ownership, reducing congestion and improving air quality.","vi":"Các thành phố có hệ thống giao thông công cộng đáng tin cậy thường có tỷ lệ sở hữu ô tô thấp hơn, giúp giảm ùn tắc và cải thiện chất lượng không khí.","audioKind":"ex2"}],"collocations":[{"en":"unemployment rate","vi":"tỷ lệ thất nghiệp"},{"en":"interest rate","vi":"lãi suất"},{"en":"hourly rate","vi":"mức lương theo giờ; giá cước theo giờ"},{"en":"highly rated","vi":"được đánh giá cao"}],"wordFamily":["rating (n.)","rated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"rate có thể chỉ tỷ lệ hoặc đơn giá; dùng rate khi muốn đánh giá chất lượng của một vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deposit', 'en-b1-35', 'deposit', '/dɪˈpɑːzɪt/', 'B1', 'tiền đặt cọc; tiền ký quỹ; tiền gửi ngân hàng; gửi tiền; đặt cọc; làm lắng đọng; chất lắng đọng; trầm tích', 'n.', 'depositor (n.), deposition (n.)', 'Trái nghĩa: withdrawal', 'Deposit dùng cho cả tiền đặt cọc, tiền ký quỹ và tiền gửi ngân hàng.', 'We paid a deposit before moving into the flat.', NULL, 'Chúng tôi đã đóng tiền đặt cọc trước khi dọn vào căn hộ.', '{"wordId":"deposit","ukIpa":"/dɪˈpɒzɪt/","usIpa":"/dɪˈpɑːzɪt/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"money paid in advance, held as security, or banked","vi":"tiền đặt cọc; tiền ký quỹ; tiền gửi ngân hàng"},{"pos":"v.","en":"to put money or material somewhere for keeping or accumulation","vi":"gửi tiền; đặt cọc; làm lắng đọng"},{"pos":"n.","en":"material that builds up naturally in a place","vi":"chất lắng đọng; trầm tích"}],"examples":[{"en":"We paid a deposit before moving into the flat.","vi":"Chúng tôi đã đóng tiền đặt cọc trước khi dọn vào căn hộ.","audioKind":"ex"},{"en":"Requiring a refundable deposit on drink containers can encourage recycling and reduce waste in public spaces.","vi":"Yêu cầu khoản đặt cọc có thể hoàn lại cho các vỏ đựng đồ uống có thể khuyến khích việc tái chế và giảm thiểu rác thải ở không gian công cộng.","audioKind":"ex2"}],"collocations":[{"en":"pay a deposit","vi":"đóng tiền đặt cọc"},{"en":"refundable deposit","vi":"khoản tiền cọc được hoàn lại"},{"en":"deposit money","vi":"gửi tiền"},{"en":"mineral deposits","vi":"trầm tích khoáng sản"}],"wordFamily":["depositor (n.)","deposition (n.)"],"synonyms":[],"antonyms":["withdrawal"],"tipVi":"Deposit dùng cho cả tiền đặt cọc, tiền ký quỹ và tiền gửi ngân hàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cheque-check', 'en-b1-35', 'cheque/check', '/tʃek/', 'B1', 'tờ séc; lệnh viết tay yêu cầu ngân hàng trả một số tiền nhất định', 'n.', NULL, NULL, 'Séc được viết là cheque theo tiếng Anh-Anh và check theo tiếng Anh-Mỹ, phát âm giống nhau.', 'My grandmother sent me a cheque for my birthday.', NULL, 'Bà nội đã gửi cho tôi một tờ séc làm quà sinh nhật.', '{"wordId":"cheque-check","ukIpa":"/tʃek/","usIpa":"/tʃek/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"A written instruction asking a bank to pay a specified amount.","vi":"tờ séc; lệnh viết tay yêu cầu ngân hàng trả một số tiền nhất định"}],"examples":[{"en":"My grandmother sent me a cheque for my birthday.","vi":"Bà nội đã gửi cho tôi một tờ séc làm quà sinh nhật.","audioKind":"ex"},{"en":"Although digital payments are increasingly common, some businesses still accept a cheque from customers.","vi":"Mặc dù thanh toán kỹ thuật số ngày càng phổ biến, một số doanh nghiệp vẫn chấp nhận séc từ khách hàng.","audioKind":"ex2"}],"collocations":[{"en":"pay by cheque","vi":"thanh toán bằng séc"},{"en":"write a check","vi":"viết séc"},{"en":"cash a cheque","vi":"rút tiền séc"},{"en":"a bounced check","vi":"séc bị trả về do không đủ tiền"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Séc được viết là cheque theo tiếng Anh-Anh và check theo tiếng Anh-Mỹ, phát âm giống nhau.","noteVi":"Kết hợp cả hai cách viết Anh-Anh và Anh-Mỹ, không phải là một từ đơn lẻ.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_property', 'en-b1-35', 'property', '/ˈprɑːpɚti/', 'B1', 'tài sản; đồ đạc cá nhân; bất động sản; nhà đất; tính chất; đặc tính', 'n.', NULL, NULL, 'Nghĩa tài sản không đếm được; nghĩa bất động sản và tính chất là danh từ đếm được.', 'Please keep your personal property safe while you swim.', NULL, 'Vui lòng giữ gìn tài sản cá nhân cẩn thận khi bạn đi bơi.', '{"wordId":"property","ukIpa":"/ˈprɒpəti/","usIpa":"/ˈprɑːpɚti/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"things that belong to a person or organisation","vi":"tài sản; đồ đạc cá nhân"},{"pos":"n.","en":"land or buildings that someone owns","vi":"bất động sản; nhà đất"},{"pos":"n.","en":"a quality of a substance or material","vi":"tính chất; đặc tính"}],"examples":[{"en":"Please keep your personal property safe while you swim.","vi":"Vui lòng giữ gìn tài sản cá nhân cẩn thận khi bạn đi bơi.","audioKind":"ex"},{"en":"Understanding the thermal properties of building materials helps architects design homes that require less heating.","vi":"Hiểu rõ các tính chất nhiệt học của vật liệu xây dựng giúp các thiết kế nhà ở tốn ít năng lượng sưởi ấm hơn.","audioKind":"ex2"}],"collocations":[{"en":"private property","vi":"tài sản riêng"},{"en":"property prices","vi":"giá bất động sản"},{"en":"physical properties","vi":"tính chất vật lý"},{"en":"intellectual property","vi":"sở hữu trí tuệ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa tài sản không đếm được; nghĩa bất động sản và tính chất là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_developing', 'en-b1-35', 'developing', '/dɪˈveləpɪŋ/', 'B1', 'đang phát triển (về kinh tế, thường kèm theo mức sống được cải thiện); đang dần hình thành; đang lớn lên', 'adj.', 'develop (v.), development (n.), developed (adj.), developer (n.)', 'Trái nghĩa: developed', 'developing chỉ trạng thái đang phát triển; developed chỉ các nước đã phát triển, phát đạt.', 'My cousin builds water pumps in a developing country.', NULL, 'Anh họ tôi chế tạo máy bơm nước ở một quốc gia đang phát triển.', '{"wordId":"developing","ukIpa":"/dɪˈveləpɪŋ/","usIpa":"/dɪˈveləpɪŋ/","cefr":"B1","topic":"economy","senses":[{"pos":"adj.","en":"Becoming more economically advanced, often with improving living standards.","vi":"đang phát triển (về kinh tế, thường kèm theo mức sống được cải thiện)"},{"pos":"adj.","en":"Growing or becoming more complete over time.","vi":"đang dần hình thành; đang lớn lên"}],"examples":[{"en":"My cousin builds water pumps in a developing country.","vi":"Anh họ tôi chế tạo máy bơm nước ở một quốc gia đang phát triển.","audioKind":"ex"},{"en":"Developing economies often need sustained investment in education and infrastructure to improve living standards.","vi":"Các nền kinh tế đang phát triển thường cần sự đầu tư bền vững vào giáo dục và cơ sở hạ tầng để nâng cao mức sống.","audioKind":"ex2"}],"collocations":[{"en":"developing countries","vi":"các quốc gia đang phát triển"},{"en":"developing economies","vi":"các nền kinh tế đang phát triển"},{"en":"a developing situation","vi":"tình hình đang diễn biến"}],"wordFamily":["develop (v.)","development (n.)","developed (adj.)","developer (n.)"],"synonyms":[],"antonyms":["developed"],"tipVi":"developing chỉ trạng thái đang phát triển; developed chỉ các nước đã phát triển, phát đạt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seller', 'en-b1-35', 'seller', '/ˈselər/', 'B1', 'người bán; bên bán', 'n.', 'sell (v.), sale (n.)', 'Đồng nghĩa: vendor · Trái nghĩa: buyer', 'seller nghiêng về bên bán trong giao dịch, không nhất thiết là nhân viên bán hàng trong cửa hàng.', 'The seller wrapped the vase carefully before handing it over.', NULL, 'Người bán đã gói cẩn thận chiếc bình hoa trước khi đưa nó cho khách.', '{"wordId":"seller","ukIpa":"/ˈselə/","usIpa":"/ˈselər/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"a person or business that sells something","vi":"người bán; bên bán"}],"examples":[{"en":"The seller wrapped the vase carefully before handing it over.","vi":"Người bán đã gói cẩn thận chiếc bình hoa trước khi đưa nó cho khách.","audioKind":"ex"},{"en":"Online marketplaces should require each seller to provide accurate product information and clear policies for returns.","vi":"Các sàn giao dịch trực tuyến nên yêu cầu mỗi người bán cung cấp thông tin sản phẩm chính xác và chính sách đổi trả rõ ràng.","audioKind":"ex2"}],"collocations":[{"en":"online seller","vi":"người bán hàng trực tuyến"},{"en":"private seller","vi":"người bán cá nhân"},{"en":"buyers and sellers","vi":"bên mua và bên bán"}],"wordFamily":["sell (v.)","sale (n.)"],"synonyms":["vendor"],"antonyms":["buyer"],"tipVi":"seller nghiêng về bên bán trong giao dịch, không nhất thiết là nhân viên bán hàng trong cửa hàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_growth', 'en-b1-35', 'growth', '/ɡroʊθ/', 'B1', 'sự tăng trưởng; sự gia tăng; sự phát triển; sự lớn lên; khối u; vật tăng sinh', 'n.', 'grow (v.), growing (adj.)', 'Đồng nghĩa: increase, expansion · Trái nghĩa: decline', 'Chỉ sự tăng trưởng thường không đếm được; a growth có thể chỉ một khối u trên cơ thể.', 'The rapid growth of our town surprised my grandparents.', NULL, 'Sự phát triển nhanh chóng của thị trấn chúng tôi khiến ông bà tôi bất ngờ.', '{"wordId":"growth","ukIpa":"/ɡrəʊθ/","usIpa":"/ɡroʊθ/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"An increase in size, amount, or level.","vi":"sự tăng trưởng; sự gia tăng"},{"pos":"n.","en":"The process of growing physically or developing over time.","vi":"sự phát triển; sự lớn lên"},{"pos":"n.","en":"An unusual lump of tissue growing in or on the body.","vi":"khối u; vật tăng sinh"}],"examples":[{"en":"The rapid growth of our town surprised my grandparents.","vi":"Sự phát triển nhanh chóng của thị trấn chúng tôi khiến ông bà tôi bất ngờ.","audioKind":"ex"},{"en":"Governments should balance economic growth with environmental protection to ensure that rising prosperity does not exhaust natural resources.","vi":"Chính phủ nên cân bằng giữa tăng trưởng kinh tế và bảo vệ môi trường để đảm bảo sự thịnh vượng gia tăng không làm cạn kiệt tài nguyên thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"economic growth","vi":"tăng trưởng kinh tế"},{"en":"population growth","vi":"sự bùng nổ dân số"},{"en":"rapid growth","vi":"sự tăng trưởng nhanh chóng"},{"en":"personal growth","vi":"sự phát triển bản thân"}],"wordFamily":["grow (v.)","growing (adj.)"],"synonyms":["increase","expansion"],"antonyms":["decline"],"tipVi":"Chỉ sự tăng trưởng thường không đếm được; a growth có thể chỉ một khối u trên cơ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_net', 'en-b1-35', 'net', '/net/', 'B1', 'lưới; vật làm bằng lưới; ròng; thực tế (sau khi trừ chi phí hoặc thuế); thu được; kiếm được (lợi nhuận)', 'n.', 'netting (n.)', 'Trái nghĩa: gross', 'net chỉ số tiền hoặc giá trị sau khi đã trừ đi chi phí hoặc thuế; trái nghĩa với gross (tổng).', 'A small silver fish wriggled inside the fishing net.', NULL, 'Một con cá bạc nhỏ đang quẫy đạp bên trong chiếc lưới đánh cá.', '{"wordId":"net","ukIpa":"/net/","usIpa":"/net/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"material made of crossing threads with spaces between them","vi":"lưới; vật làm bằng lưới"},{"pos":"adj.","en":"remaining after costs, taxes, or other amounts have been deducted","vi":"ròng; thực tế (sau khi trừ chi phí hoặc thuế)"},{"pos":"v.","en":"to earn as profit or successfully obtain something","vi":"thu được; kiếm được (lợi nhuận)"}],"examples":[{"en":"A small silver fish wriggled inside the fishing net.","vi":"Một con cá bạc nhỏ đang quẫy đạp bên trong chiếc lưới đánh cá.","audioKind":"ex"},{"en":"The company increased its net profit by reducing energy consumption rather than raising prices for customers.","vi":"Công ty đã gia tăng lợi nhuận ròng bằng cách giảm tiêu thụ năng lượng thay vì tăng giá bán đối với khách hàng.","audioKind":"ex2"}],"collocations":[{"en":"fishing net","vi":"lưới đánh cá"},{"en":"net profit","vi":"lợi nhuận ròng"},{"en":"net income","vi":"thu nhập ròng"},{"en":"net gain","vi":"lợi ích ròng; mức tăng ròng"}],"wordFamily":["netting (n.)"],"synonyms":[],"antonyms":["gross"],"tipVi":"net chỉ số tiền hoặc giá trị sau khi đã trừ đi chi phí hoặc thuế; trái nghĩa với gross (tổng).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_goods', 'en-b1-35', 'goods', '/ɡʊdz/', 'B1', 'những thứ được sản xuất để bán hoặc vận chuyển để trao đổi thương mại; hàng hóa; sản phẩm; tài sản di động thuộc quyền sở hữu của một cá nhân; tư trang', 'n.', NULL, 'Đồng nghĩa: merchandise, products', 'Goods là danh từ số nhiều; để chỉ một món hàng đơn lẻ, có thể dùng an item.', 'The shop sells handmade goods from nearby villages.', NULL, 'Cửa hàng bán các mặt hàng thủ công làm từ các ngôi làng lân cận.', '{"wordId":"goods","ukIpa":"/ɡʊdz/","usIpa":"/ɡʊdz/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"Things produced for sale or transported for trade.","vi":"những thứ được sản xuất để bán hoặc vận chuyển để trao đổi thương mại; hàng hóa; sản phẩm"},{"pos":"n.","en":"Movable possessions belonging to a person.","vi":"tài sản di động thuộc quyền sở hữu của một cá nhân; tư trang"}],"examples":[{"en":"The shop sells handmade goods from nearby villages.","vi":"Cửa hàng bán các mặt hàng thủ công làm từ các ngôi làng lân cận.","audioKind":"ex"},{"en":"Transporting goods by rail rather than road can lower emissions and reduce congestion in urban areas.","vi":"Việc vận chuyển hàng hóa bằng đường sắt thay vì đường bộ có thể làm giảm lượng khí thải và hạn chế tình trạng ùn tắc ở các khu đô thị.","audioKind":"ex2"}],"collocations":[{"en":"consumer goods","vi":"hàng tiêu dùng"},{"en":"luxury goods","vi":"hàng xa xỉ phẩm"},{"en":"household goods","vi":"đồ dùng gia đình"},{"en":"transport goods","vi":"vận chuyển hàng hóa"}],"wordFamily":[],"synonyms":["merchandise","products"],"antonyms":[],"tipVi":"Goods là danh từ số nhiều; để chỉ một món hàng đơn lẻ, có thể dùng an item.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_produce', 'en-b1-35', 'produce', '/prəˈduːs/; /ˈproʊduːs/', 'B1', 'sản xuất; tạo ra; gây ra; đem lại; nông sản', 'v.', 'production (n.), producer (n.), productive (adj.), productivity (n.)', NULL, 'Trọng âm rơi vào âm tiết cuối khi là động từ, và rơi vào âm tiết đầu khi là danh từ; danh từ nông sản không đếm được.', 'Our garden produces enough tomatoes for the whole family.', NULL, 'Khu vườn nhà chúng tôi thu hoạch đủ cà chua cho cả nhà ăn.', '{"wordId":"produce","ukIpa":"/prəˈdjuːs/; /ˈprɒdjuːs/","usIpa":"/prəˈduːs/; /ˈproʊduːs/","cefr":"B1","topic":"economy","senses":[{"pos":"v.","en":"To make, grow, or create something.","vi":"sản xuất; tạo ra"},{"pos":"v.","en":"To cause a result or effect.","vi":"gây ra; đem lại"},{"pos":"n.","en":"Food grown on farms, especially fruit and vegetables.","vi":"nông sản"}],"examples":[{"en":"Our garden produces enough tomatoes for the whole family.","vi":"Khu vườn nhà chúng tôi thu hoạch đủ cà chua cho cả nhà ăn.","audioKind":"ex"},{"en":"Investing in renewable energy can produce long-term benefits for both local communities and the environment.","vi":"Đầu tư vào năng lượng tái tạo có thể mang lại lợi ích lâu dài cho cả cộng đồng địa phương và môi trường.","audioKind":"ex2"}],"collocations":[{"en":"produce electricity","vi":"sản xuất điện"},{"en":"produce results","vi":"tạo ra kết quả"},{"en":"fresh produce","vi":"nông sản tươi"}],"wordFamily":["production (n.)","producer (n.)","productive (adj.)","productivity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trọng âm rơi vào âm tiết cuối khi là động từ, và rơi vào âm tiết đầu khi là danh từ; danh từ nông sản không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_economic', 'en-b1-35', 'economic', '/ˌiːkəˈnɑːmɪk/', 'B1', 'thuộc về kinh tế', 'adj.', 'economy (n.), economics (n.), economist (n.), economically (adv.)', NULL, 'economic mang nghĩa liên quan đến kinh tế; economical mang nghĩa tiết kiệm.', 'The news discussed economic problems affecting local shops.', NULL, 'Bản tin thảo luận về các vấn đề kinh tế ảnh hưởng đến các cửa hàng địa phương.', '{"wordId":"economic","ukIpa":"/ˌiːkəˈnɒmɪk/","usIpa":"/ˌiːkəˈnɑːmɪk/","cefr":"B1","topic":"economy","senses":[{"pos":"adj.","en":"Relating to trade, industry, money, or the study of these.","vi":"thuộc về kinh tế"}],"examples":[{"en":"The news discussed economic problems affecting local shops.","vi":"Bản tin thảo luận về các vấn đề kinh tế ảnh hưởng đến các cửa hàng địa phương.","audioKind":"ex"},{"en":"Investment in public transport can support economic growth by connecting workers with a wider range of jobs.","vi":"Đầu tư vào giao thông công cộng có thể hỗ trợ tăng trưởng kinh tế bằng cách kết nối người lao động với nhiều cơ hội việc làm rộng mở hơn.","audioKind":"ex2"}],"collocations":[{"en":"economic growth","vi":"tăng trưởng kinh tế"},{"en":"economic development","vi":"phát triển kinh tế"},{"en":"economic policy","vi":"chính sách kinh tế"},{"en":"economic recession","vi":"suy thoái kinh tế"}],"wordFamily":["economy (n.)","economics (n.)","economist (n.)","economically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"economic mang nghĩa liên quan đến kinh tế; economical mang nghĩa tiết kiệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_financial', 'en-b1-35', 'financial', '/faɪˈnænʃəl/', 'B1', 'thuộc về tài chính; tài chính', 'adj.', 'finance (n.), finance (v.), financially (adv.)', 'Đồng nghĩa: monetary', 'financial thiên về tiền bạc và tài chính cá nhân/tổ chức; economic thiên về nền kinh tế tổng thể.', 'We asked for financial advice before buying our first home.', NULL, 'Chúng tôi đã xin lời khuyên tài chính trước khi mua ngôi nhà đầu tiên.', '{"wordId":"financial","ukIpa":"/faɪˈnænʃəl/","usIpa":"/faɪˈnænʃəl/","cefr":"B1","topic":"economy","senses":[{"pos":"adj.","en":"relating to money or how it is managed","vi":"thuộc về tài chính; tài chính"}],"examples":[{"en":"We asked for financial advice before buying our first home.","vi":"Chúng tôi đã xin lời khuyên tài chính trước khi mua ngôi nhà đầu tiên.","audioKind":"ex"},{"en":"Financial support for disadvantaged students can improve access to higher education and reduce long-term inequality.","vi":"Sự hỗ trợ tài chính cho học sinh sinh viên có hoàn cảnh khó khăn có thể giúp họ dễ dàng tiếp cận giáo dục đại học hơn và giảm thiểu bất bình đẳng lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"financial support","vi":"hỗ trợ tài chính"},{"en":"financial difficulties","vi":"khó khăn tài chính"},{"en":"financial stability","vi":"sự ổn định tài chính"},{"en":"financial services","vi":"dịch vụ tài chính"}],"wordFamily":["finance (n.)","finance (v.)","financially (adv.)"],"synonyms":["monetary"],"antonyms":[],"tipVi":"financial thiên về tiền bạc và tài chính cá nhân/tổ chức; economic thiên về nền kinh tế tổng thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_35_1', 'en-b1-35', 'Cách dùng “produce” (v.) — sản xuất; tạo ra', 'produce electricity  ·  produce results  ·  fresh produce', 'Trọng âm rơi vào âm tiết cuối khi là động từ, và rơi vào âm tiết đầu khi là danh từ; danh từ nông sản không đếm được.', 'Họ từ (Word Family): production (n.), producer (n.), productive (adj.), productivity (n.)', '[{"hanzi":"Our garden produces enough tomatoes for the whole family.","pinyin":"","meaning":"Khu vườn nhà chúng tôi thu hoạch đủ cà chua cho cả nhà ăn."},{"hanzi":"Investing in renewable energy can produce long-term benefits for both local communities and the environment.","pinyin":"","meaning":"Đầu tư vào năng lượng tái tạo có thể mang lại lợi ích lâu dài cho cả cộng đồng địa phương và môi trường."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_35_2', 'en-b1-35', 'Cách dùng “currency” (n.) — tiền tệ (được sử dụng ở một quốc gia cụ thể)', 'foreign currency  ·  local currency  ·  currency exchange', 'Tên các loại tiền tệ có thể đếm được; còn khi chỉ chung khái niệm tiền tệ thì thường không đếm được.', NULL, '[{"hanzi":"We exchanged our money for local currency at the airport.","pinyin":"","meaning":"Chúng tôi đã đổi tiền của mình lấy nội tệ tại sân bay."},{"hanzi":"A weaker currency can attract international tourists by making accommodation and other services more affordable.","pinyin":"","meaning":"Đồng tiền yếu hơn có thể thu hút khách du lịch quốc tế bằng cách giúp chi phí lưu trú và các dịch vụ khác trở nên phải chăng hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_35_3', 'en-b1-35', 'Cách dùng “seller” (n.) — người bán; bên bán', 'online seller  ·  private seller  ·  buyers and sellers', 'seller nghiêng về bên bán trong giao dịch, không nhất thiết là nhân viên bán hàng trong cửa hàng.', 'Họ từ (Word Family): sell (v.), sale (n.) | Đồng nghĩa: vendor · Trái nghĩa: buyer', '[{"hanzi":"The seller wrapped the vase carefully before handing it over.","pinyin":"","meaning":"Người bán đã gói cẩn thận chiếc bình hoa trước khi đưa nó cho khách."},{"hanzi":"Online marketplaces should require each seller to provide accurate product information and clear policies for returns.","pinyin":"","meaning":"Các sàn giao dịch trực tuyến nên yêu cầu mỗi người bán cung cấp thông tin sản phẩm chính xác và chính sách đổi trả rõ ràng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_35_4', 'en-b1-35', 'Cách dùng “financial” (adj.) — thuộc về tài chính; tài chính', 'financial support  ·  financial difficulties  ·  financial stability', 'financial thiên về tiền bạc và tài chính cá nhân/tổ chức; economic thiên về nền kinh tế tổng thể.', 'Họ từ (Word Family): finance (n.), finance (v.), financially (adv.) | Đồng nghĩa: monetary', '[{"hanzi":"We asked for financial advice before buying our first home.","pinyin":"","meaning":"Chúng tôi đã xin lời khuyên tài chính trước khi mua ngôi nhà đầu tiên."},{"hanzi":"Financial support for disadvantaged students can improve access to higher education and reduce long-term inequality.","pinyin":"","meaning":"Sự hỗ trợ tài chính cho học sinh sinh viên có hoàn cảnh khó khăn có thể giúp họ dễ dàng tiếp cận giáo dục đại học hơn và giảm thiểu bất bình đẳng lâu dài."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_35_1', 'en-b1-35', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_1_1', 'ten_b1_35_1', 'currency', 'We exchanged our money for local currency at the airport.', 'We exchanged our money for local currency at the airport.', '/ˈkɜːrənsi/', 'Chúng tôi đã đổi tiền của mình lấy nội tệ tại sân bay.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_1_2', 'ten_b1_35_1', 'development', 'Regular play supports a young child''s development in many ways.', 'Regular play supports a young child''s development in many ways.', '/dɪˈveləpmənt/', 'Vui chơi thường xuyên hỗ trợ sự phát triển của trẻ nhỏ theo nhiều cách.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_1_3', 'ten_b1_35_1', 'inexpensive', 'We found an inexpensive café near the train station.', 'We found an inexpensive café near the train station.', '/ˌɪnɪkˈspensɪv/', 'Chúng tôi tìm thấy một quán cà phê giá rẻ gần ga xe lửa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_1_4', 'ten_b1_35_1', 'supply', 'A nearby farm supplies fresh eggs to our shop.', 'A nearby farm supplies fresh eggs to our shop.', '/səˈplaɪ/', 'Một trang trại gần đó cung cấp trứng tươi cho cửa hàng của chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_1_5', 'ten_b1_35_1', 'income', 'My weekend job gives me a small extra income.', 'My weekend job gives me a small extra income.', '/ˈɪnkʌm/', 'Công việc làm thêm cuối tuần mang lại cho tôi một khoản thu nhập nhỏ phụ trội.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_1_6', 'ten_b1_35_1', 'decrease', 'Our electricity bills decreased after we replaced the old heater.', 'Our electricity bills decreased after we replaced the old heater.', '/dɪˈkriːs/', 'Hóa đơn tiền điện của chúng tôi đã giảm sau khi chúng tôi thay chiếc máy sưởi cũ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_1_7', 'ten_b1_35_1', 'afford', 'We cannot afford a new sofa this month.', 'We cannot afford a new sofa this month.', '/əˈfɔːrd/', 'Tháng này chúng tôi không đủ tiền mua chiếc ghế sofa mới.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_1_8', 'ten_b1_35_1', 'economics', 'My sister studies economics and enjoys discussing food prices.', 'My sister studies economics and enjoys discussing food prices.', '/ˌiːkəˈnɑːmɪks/', 'Chị gái tôi học ngành kinh tế học và rất thích thảo luận về giá cả thực phẩm.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_35_1_1', 'en-b1-35', 'ten_b1_35_1', 'listening', 'listening', 'We exchanged our money for local currency at the airport.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một trang trại gần đó cung cấp trứng tươi cho cửa hàng của chúng tôi.","Anh họ tôi chế tạo máy bơm nước ở một quốc gia đang phát triển.","Một con cá bạc nhỏ đang quẫy đạp bên trong chiếc lưới đánh cá.","Chúng tôi đã đổi tiền của mình lấy nội tệ tại sân bay."]'::jsonb, 3, 'We exchanged our money for local currency at the airport. → Chúng tôi đã đổi tiền của mình lấy nội tệ tại sân bay.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_35_1_2', 'en-b1-35', 'ten_b1_35_1', 'listening', 'listening', 'Regular play supports a young child''s development in many ways.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Vui lòng giữ gìn tài sản cá nhân cẩn thận khi bạn đi bơi.","Vui chơi thường xuyên hỗ trợ sự phát triển của trẻ nhỏ theo nhiều cách.","Chị gái tôi học ngành kinh tế học và rất thích thảo luận về giá cả thực phẩm.","Sự phát triển nhanh chóng của thị trấn chúng tôi khiến ông bà tôi bất ngờ."]'::jsonb, 1, 'Regular play supports a young child''s development in many ways. → Vui chơi thường xuyên hỗ trợ sự phát triển của trẻ nhỏ theo nhiều cách.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_35_1_3', 'en-b1-35', 'ten_b1_35_1', 'listening', 'listening', 'We found an inexpensive café near the train station.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Khu vườn nhà chúng tôi thu hoạch đủ cà chua cho cả nhà ăn.","Sự phát triển nhanh chóng của thị trấn chúng tôi khiến ông bà tôi bất ngờ.","Chúng tôi tìm thấy một quán cà phê giá rẻ gần ga xe lửa.","Người bán đã gói cẩn thận chiếc bình hoa trước khi đưa nó cho khách."]'::jsonb, 2, 'We found an inexpensive café near the train station. → Chúng tôi tìm thấy một quán cà phê giá rẻ gần ga xe lửa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_35_2', 'en-b1-35', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_2_1', 'ten_b1_35_2', 'currency', 'A weaker currency can attract international tourists by making accommodation and other services more affordable.', 'A weaker currency can attract international tourists by making accommodation and other services more affordable.', '/ˈkɜːrənsi/', 'Đồng tiền yếu hơn có thể thu hút khách du lịch quốc tế bằng cách giúp chi phí lưu trú và các dịch vụ khác trở nên phải chăng hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_2_2', 'ten_b1_35_2', 'development', 'Investment in public transport can support economic development while reducing traffic congestion in growing cities.', 'Investment in public transport can support economic development while reducing traffic congestion in growing cities.', '/dɪˈveləpmənt/', 'Đầu tư vào giao thông công cộng có thể hỗ trợ phát triển kinh tế đồng thời giảm thiểu tình trạng ùn tắc giao thông ở các đô thị đang mở rộng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_2_3', 'ten_b1_35_2', 'inexpensive', 'Cycling offers an inexpensive alternative to driving and can help reduce traffic congestion in growing cities.', 'Cycling offers an inexpensive alternative to driving and can help reduce traffic congestion in growing cities.', '/ˌɪnɪkˈspensɪv/', 'Đi xe đạp là một lựa chọn thay thế tiết kiệm cho việc lái xe và có thể giúp giảm ùn tắc giao thông ở các thành phố đang phát triển.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_2_4', 'ten_b1_35_2', 'supply', 'Cities must secure a reliable water supply as population growth and climate change place increasing pressure on resources.', 'Cities must secure a reliable water supply as population growth and climate change place increasing pressure on resources.', '/səˈplaɪ/', 'Các thành phố phải đảm bảo nguồn cung cấp nước ổn định khi sự gia tăng dân số và biến đổi khí hậu đặt ra áp lực ngày càng lớn lên các nguồn tài nguyên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_2_5', 'ten_b1_35_2', 'income', 'Affordable public transport allows families on low incomes to access employment and essential services more easily.', 'Affordable public transport allows families on low incomes to access employment and essential services more easily.', '/ˈɪnkʌm/', 'Giao thông công cộng giá rẻ giúp các gia đình có thu nhập thấp tiếp cận việc làm và các dịch vụ thiết yếu dễ dàng hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_35_2_6', 'ten_b1_35_2', 'decrease', 'Improved public transport could decrease traffic congestion and reduce air pollution in densely populated cities.', 'Improved public transport could decrease traffic congestion and reduce air pollution in densely populated cities.', '/dɪˈkriːs/', 'Việc cải thiện giao thông công cộng có thể làm giảm tình trạng ùn tắc giao thông và cắt giảm ô nhiễm không khí ở các thành phố đông dân cư.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_35_2_1', 'en-b1-35', 'ten_b1_35_2', 'listening', 'listening', 'A weaker currency can attract international tourists by making accommodation and other services more affordable.', NULL, 'Trong câu vừa nghe, từ “currency” mang nghĩa nào sau đây?', '["tiếng khóc; sự khóc","toàn cầu; mang tính thế giới","tiền tệ (được sử dụng ở một quốc gia cụ thể)","sự giao hàng; sự phân phát"]'::jsonb, 2, '“currency” (/ˈkɜːrənsi/): tiền tệ (được sử dụng ở một quốc gia cụ thể). Câu đầy đủ: A weaker currency can attract international tourists by making accommodation and other services more affordable.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_35_2_2', 'en-b1-35', 'ten_b1_35_2', 'listening', 'listening', 'Investment in public transport can support economic development while reducing traffic congestion in growing cities.', NULL, 'Trong câu vừa nghe, từ “development” mang nghĩa nào sau đây?', '["thang cuốn","sự phát triển; sự lớn lên","đang phát triển (về kinh tế, thường kèm theo mức sống được cải thiện)","một tá; mười hai"]'::jsonb, 1, '“development” (/dɪˈveləpmənt/): sự phát triển; sự lớn lên. Câu đầy đủ: Investment in public transport can support economic development while reducing traffic congestion in growing cities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
