INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_35_1', 'en-b1-35', NULL, 'comprehensive_test', 'listening', 'currency', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ngày Lễ tặng quà (ngày 26 tháng 12)","một phần; ở một mức độ nào đó","tiền tệ (được sử dụng ở một quốc gia cụ thể)","tuyến đường; lộ trình"]'::jsonb, 2, 'currency (/ˈkɜːrənsi/) → tiền tệ (được sử dụng ở một quốc gia cụ thể); sự lưu hành, sự thịnh hành (được chấp nhận hoặc sử dụng rộng rãi)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_35_2', 'en-b1-35', NULL, 'comprehensive_test', 'listening', 'Regular play supports a young child''s development in many ways.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã đóng tiền đặt cọc trước khi dọn vào căn hộ.","Vui chơi thường xuyên hỗ trợ sự phát triển của trẻ nhỏ theo nhiều cách.","Chúng tôi đã xin lời khuyên tài chính trước khi mua ngôi nhà đầu tiên.","Khu vườn nhà chúng tôi thu hoạch đủ cà chua cho cả nhà ăn."]'::jsonb, 1, 'Regular play supports a young child''s development in many ways. → Vui chơi thường xuyên hỗ trợ sự phát triển của trẻ nhỏ theo nhiều cách.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_35_3', 'en-b1-35', NULL, 'comprehensive_test', 'listening', 'inexpensive', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["niềm vui; sự thích thú","dây kim loại; dây điện","tò mò; ham học hỏi","giá rẻ; không đắt"]'::jsonb, 3, 'inexpensive (/ˌɪnɪkˈspensɪv/) → giá rẻ; không đắt', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_35_4', 'en-b1-35', NULL, 'comprehensive_test', 'listening', 'A nearby farm supplies fresh eggs to our shop.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi tìm thấy một quán cà phê giá rẻ gần ga xe lửa.","Một con cá bạc nhỏ đang quẫy đạp bên trong chiếc lưới đánh cá.","Một trang trại gần đó cung cấp trứng tươi cho cửa hàng của chúng tôi.","Sự phát triển nhanh chóng của thị trấn chúng tôi khiến ông bà tôi bất ngờ."]'::jsonb, 2, 'A nearby farm supplies fresh eggs to our shop. → Một trang trại gần đó cung cấp trứng tươi cho cửa hàng của chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
