INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_35_6', 'en-b1-35', NULL, 'comprehensive_test', 'listening', 'Our electricity bills decreased after we replaced the old heater.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Vui lòng giữ gìn tài sản cá nhân cẩn thận khi bạn đi bơi.","Hóa đơn tiền điện của chúng tôi đã giảm sau khi chúng tôi thay chiếc máy sưởi cũ.","Sự phát triển nhanh chóng của thị trấn chúng tôi khiến ông bà tôi bất ngờ.","Chúng tôi đã xin lời khuyên tài chính trước khi mua ngôi nhà đầu tiên."]'::jsonb, 1, 'Our electricity bills decreased after we replaced the old heater. → Hóa đơn tiền điện của chúng tôi đã giảm sau khi chúng tôi thay chiếc máy sưởi cũ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
