INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_35_18', 'en-b1-35', NULL, 'comprehensive_test', 'reading', NULL, 'A weaker currency can attract international tourists by making accommodation and other services more affordable.', 'Dựa vào câu trên, từ “currency” có nghĩa phù hợp nhất là gì?', '["con nai; con hươu","lời phát biểu; ý kiến","tiền tệ (được sử dụng ở một quốc gia cụ thể)","bất công; không công bằng"]'::jsonb, 2, 'currency: tiền tệ (được sử dụng ở một quốc gia cụ thể); sự lưu hành, sự thịnh hành (được chấp nhận hoặc sử dụng rộng rãi). Dịch cả câu: Đồng tiền yếu hơn có thể thu hút khách du lịch quốc tế bằng cách giúp chi phí lưu trú và các dịch vụ khác trở nên phải chăng hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_35_19', 'en-b1-35', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in public transport can support economic development while reducing traffic congestion in growing cities.', 'Dựa vào câu trên, từ “development” có nghĩa phù hợp nhất là gì?', '["sự ly hôn","huýt sáo; rít lên; thổi còi","sự phát triển; sự lớn lên","quốc lộ; đường cao tốc chính"]'::jsonb, 2, 'development: sự phát triển; sự lớn lên; sự chế tạo; sự tiến triển; biến động mới. Dịch cả câu: Đầu tư vào giao thông công cộng có thể hỗ trợ phát triển kinh tế đồng thời giảm thiểu tình trạng ùn tắc giao thông ở các đô thị đang mở rộng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_35_20', 'en-b1-35', NULL, 'comprehensive_test', 'reading', NULL, 'Cycling offers an inexpensive alternative to driving and can help reduce traffic congestion in growing cities.', 'Dựa vào câu trên, từ “inexpensive” có nghĩa phù hợp nhất là gì?', '["giá rẻ; không đắt","thân mật; thoải mái; không trang trọng","một cách thành thật; trung thực","bỏ qua; lướt qua; trốn"]'::jsonb, 0, 'inexpensive: giá rẻ; không đắt. Dịch cả câu: Đi xe đạp là một lựa chọn thay thế tiết kiệm cho việc lái xe và có thể giúp giảm ùn tắc giao thông ở các thành phố đang phát triển.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_35_21', 'en-b1-35', NULL, 'comprehensive_test', 'reading', NULL, 'Cities must secure a reliable water supply as population growth and climate change place increasing pressure on resources.', 'Dựa vào câu trên, từ “supply” có nghĩa phù hợp nhất là gì?', '["lời chúc mừng; sự chúc mừng","cung cấp; cung ứng","cạo râu; cạo lông","rời đi; khởi hành"]'::jsonb, 1, 'supply: cung cấp; cung ứng; nguồn cung; lượng dự trữ; vật tư; nhu yếu phẩm. Dịch cả câu: Các thành phố phải đảm bảo nguồn cung cấp nước ổn định khi sự gia tăng dân số và biến đổi khí hậu đặt ra áp lực ngày càng lớn lên các nguồn tài nguyên.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_35_22', 'en-b1-35', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sản xuất; tạo ra”', '["handkerchief","produce","smooth","ladybird"]'::jsonb, 1, 'sản xuất; tạo ra → produce (/prəˈduːs/; /ˈproʊduːs/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_35_23', 'en-b1-35', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về kinh tế”', '["economic","mechanic","lane","tax"]'::jsonb, 0, 'thuộc về kinh tế → economic (/ˌiːkəˈnɑːmɪk/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_35_24', 'en-b1-35', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về tài chính; tài chính”', '["practical","financial","impressive","softly"]'::jsonb, 1, 'thuộc về tài chính; tài chính → financial (/faɪˈnænʃəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-36', 'en', 'Bài 36: Kinh tế & Tài chính (2) - CEFR B1', 'CEFR B1', 'B1 · Kinh tế', '20 từ vựng Tiếng Anh CEFR B1 chủ đề kinh tế & tài chính kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3036, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_demand', 'en-b1-36', 'demand', '/dɪˈmænd/', 'B1', 'nhu cầu; yêu cầu kiên quyết; đòi hỏi; cần thiết', 'n.', 'demanding (adj.)', NULL, 'Yêu cầu làm gì dùng demand to do, không dùng demand sb to do.', 'Demand for cold drinks rises sharply during hot weather.', NULL, 'Nhu cầu về đồ uống lạnh tăng vọt trong thời tiết nóng bức.', '{"wordId":"demand","ukIpa":"/dɪˈmɑːnd/","usIpa":"/dɪˈmænd/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"the desire or need for particular goods or services","vi":"nhu cầu"},{"pos":"n.","en":"a strong request that someone expects to be obeyed","vi":"yêu cầu kiên quyết"},{"pos":"v.","en":"to insist on receiving something or require something essential","vi":"đòi hỏi; cần thiết"}],"examples":[{"en":"Demand for cold drinks rises sharply during hot weather.","vi":"Nhu cầu về đồ uống lạnh tăng vọt trong thời tiết nóng bức.","audioKind":"ex"},{"en":"Growing demand for affordable housing has encouraged local authorities to convert unused office buildings into residential accommodation.","vi":"Nhu cầu ngày càng tăng đối với nhà ở giá rẻ đã khuyến khích các cơ quan chức năng địa phương chuyển đổi các tòa nhà văn phòng bỏ trống thành không gian nhà ở.","audioKind":"ex2"}],"collocations":[{"en":"demand for housing","vi":"nhu cầu nhà ở"},{"en":"meet demand","vi":"đáp ứng nhu cầu"},{"en":"in high demand","vi":"có nhu cầu cao"},{"en":"demand an explanation","vi":"yêu cầu giải thích"}],"wordFamily":["demanding (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Yêu cầu làm gì dùng demand to do, không dùng demand sb to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_percentage', 'en-b1-36', 'percentage', '/pərˈsentɪdʒ/', 'B1', 'tỷ lệ phần trăm; phần trăm', 'n.', 'percent (n.)', NULL, 'Dùng percent sau số cụ thể; dùng percentage khi nói chung về tỷ lệ.', 'What percentage of your monthly income goes on rent?', NULL, 'Thu nhập hàng tháng của bạn dành bao nhiêu phần trăm để trả tiền thuê nhà?', '{"wordId":"percentage","ukIpa":"/pəˈsentɪdʒ/","usIpa":"/pərˈsentɪdʒ/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"an amount expressed as a fraction of one hundred","vi":"tỷ lệ phần trăm; phần trăm"}],"examples":[{"en":"What percentage of your monthly income goes on rent?","vi":"Thu nhập hàng tháng của bạn dành bao nhiêu phần trăm để trả tiền thuê nhà?","audioKind":"ex"},{"en":"The percentage of households using renewable energy has increased as installation costs have fallen in recent years.","vi":"Tỷ lệ hộ gia đình sử dụng năng lượng tái tạo đã tăng lên khi chi phí lắp đặt giảm trong những năm gần đây.","audioKind":"ex2"}],"collocations":[{"en":"a high percentage of","vi":"tỷ lệ phần trăm cao"},{"en":"a small percentage of","vi":"một tỷ lệ nhỏ"},{"en":"percentage point","vi":"điểm phần trăm"},{"en":"percentage increase","vi":"tỷ lệ tăng trưởng phần trăm"}],"wordFamily":["percent (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng percent sau số cụ thể; dùng percentage khi nói chung về tỷ lệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_export', 'en-b1-36', 'export', '/ɪkˈspɔːrt/', 'B1', 'xuất khẩu; đem bán ra nước ngoài; hàng xuất khẩu; xuất dữ liệu (máy tính)', 'v.', 'exporter (n.), exportation (n.), exportable (adj.)', 'Trái nghĩa: import', 'Trọng âm ở động từ rơi vào âm tiết sau; danh từ rơi vào âm tiết đầu.', 'My aunt''s company exports handmade bowls to several countries.', NULL, 'Công ty của dì tôi xuất khẩu bát thủ công sang một số quốc gia.', '{"wordId":"export","ukIpa":"/ɪkˈspɔːt/","usIpa":"/ɪkˈspɔːrt/","cefr":"B1","topic":"economy","senses":[{"pos":"v.","en":"to send goods to another country for sale","vi":"xuất khẩu; đem bán ra nước ngoài"},{"pos":"n.","en":"selling goods abroad, or goods sold to another country","vi":"hàng xuất khẩu"},{"pos":"v.","en":"to save computer data in a format another program uses","vi":"xuất dữ liệu (máy tính)"}],"examples":[{"en":"My aunt''s company exports handmade bowls to several countries.","vi":"Công ty của dì tôi xuất khẩu bát thủ công sang một số quốc gia.","audioKind":"ex"},{"en":"Countries that export mainly raw materials may be vulnerable to sudden changes in global commodity prices.","vi":"Các quốc gia chủ yếu xuất khẩu nguyên liệu thô có thể dễ bị tổn thương trước những biến động đột ngột của giá cả hàng hóa toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"export goods","vi":"hàng hóa xuất khẩu"},{"en":"export markets","vi":"thị trường xuất khẩu"},{"en":"export earnings","vi":"thu nhập từ xuất khẩu"},{"en":"export data","vi":"xuất dữ liệu"}],"wordFamily":["exporter (n.)","exportation (n.)","exportable (adj.)"],"synonyms":[],"antonyms":["import"],"tipVi":"Trọng âm ở động từ rơi vào âm tiết sau; danh từ rơi vào âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_competitor', 'en-b1-36', 'competitor', '/kəmˈpetɪtər/', 'B1', 'đối thủ cạnh tranh; thí sinh; người tham gia thi đấu', 'n.', 'compete (v.), competition (n.), competitive (adj.), competitively (adv.)', 'Đồng nghĩa: rival, contender', 'competitor là chỉ người/tổ chức cạnh tranh; competition là sự cạnh tranh hoặc cuộc thi.', 'The new bakery is our biggest competitor for local customers.', NULL, 'Tiệm bánh mới mở là đối thủ lớn nhất của chúng tôi trong việc thu hút khách hàng địa phương.', '{"wordId":"competitor","ukIpa":"/kəmˈpetɪtə/","usIpa":"/kəmˈpetɪtər/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"A person or organisation trying to succeed against others.","vi":"đối thủ cạnh tranh"},{"pos":"n.","en":"Someone taking part in a competition.","vi":"thí sinh; người tham gia thi đấu"}],"examples":[{"en":"The new bakery is our biggest competitor for local customers.","vi":"Tiệm bánh mới mở là đối thủ lớn nhất của chúng tôi trong việc thu hút khách hàng địa phương.","audioKind":"ex"},{"en":"A business must understand its competitors before developing strategies to attract customers in an increasingly crowded market.","vi":"Một doanh nghiệp phải hiểu rõ các đối thủ cạnh tranh trước khi vạch ra chiến lược thu hút khách hàng trong thị trường ngày càng chật chội.","audioKind":"ex2"}],"collocations":[{"en":"a major competitor","vi":"đối thủ lớn"},{"en":"a direct competitor","vi":"đối thủ trực tiếp"},{"en":"a strong competitor","vi":"đối thủ đáng gờm"}],"wordFamily":["compete (v.)","competition (n.)","competitive (adj.)","competitively (adv.)"],"synonyms":["rival","contender"],"antonyms":[],"tipVi":"competitor là chỉ người/tổ chức cạnh tranh; competition là sự cạnh tranh hoặc cuộc thi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loan', 'en-b1-36', 'loan', '/loʊn/', 'B1', 'khoản vay; khoản tiền cho vay; sự cho mượn; sự cho vay; cho mượn; cho vay', 'n.', 'lender (n.), lending (n.)', NULL, 'loan với tư cách là động từ có nghĩa là cho mượn, không phải là đi mượn.', 'We took out a loan to repair the roof.', NULL, 'Chúng tôi đã vay một khoản tiền để sửa lại mái nhà.', '{"wordId":"loan","ukIpa":"/ləʊn/","usIpa":"/loʊn/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"money borrowed and expected to be paid back","vi":"khoản vay; khoản tiền cho vay"},{"pos":"n.","en":"the temporary use of something belonging to someone else","vi":"sự cho mượn; sự cho vay"},{"pos":"v.","en":"to give money or something temporarily, expecting its return","vi":"cho mượn; cho vay"}],"examples":[{"en":"We took out a loan to repair the roof.","vi":"Chúng tôi đã vay một khoản tiền để sửa lại mái nhà.","audioKind":"ex"},{"en":"Affordable student loans can widen access to university, although repayment may create financial pressure after graduation.","vi":"Các khoản vay sinh viên vừa túi tiền có thể mở rộng cơ hội vào đại học, mặc dù việc trả nợ có thể tạo ra áp lực tài chính sau khi tốt nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"take out a loan","vi":"vay một khoản tiền"},{"en":"repay a loan","vi":"trả nợ vay"},{"en":"student loan","vi":"khoản vay sinh viên"},{"en":"on loan","vi":"đang cho mượn; đang mượn"}],"wordFamily":["lender (n.)","lending (n.)"],"synonyms":[],"antonyms":[],"tipVi":"loan với tư cách là động từ có nghĩa là cho mượn, không phải là đi mượn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_capital', 'en-b1-36', 'capital', '/ˈkæpɪtəl/', 'B1', 'thủ đô; thành phố trung tâm; vốn; nguồn vốn; chữ cái viết hoa', 'n.', 'capitalist (n.), capitalism (n.), capitalise (v.), capitalisation (n.)', NULL, 'Nghĩa chỉ tiền vốn thường không đếm được; nghĩa chỉ chữ cái viết hoa là danh từ đếm được.', 'We visited the capital and explored its busy markets.', NULL, 'Chúng tôi đã đến thăm thủ đô và khám phá những khu chợ tấp nập ở đó.', '{"wordId":"capital","ukIpa":"/ˈkæpɪtəl/","usIpa":"/ˈkæpɪtəl/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"the city where a country or region''s government is based","vi":"thủ đô; thành phố trung tâm"},{"pos":"n.","en":"money or assets used to start or operate a business","vi":"vốn; nguồn vốn"},{"pos":"n.","en":"a letter in its large form","vi":"chữ cái viết hoa"}],"examples":[{"en":"We visited the capital and explored its busy markets.","vi":"Chúng tôi đã đến thăm thủ đô và khám phá những khu chợ tấp nập ở đó.","audioKind":"ex"},{"en":"Small businesses often struggle to obtain enough capital to invest in new equipment and staff training.","vi":"Các doanh nghiệp nhỏ thường gặp khó khăn trong việc huy động đủ vốn để đầu tư vào trang thiết bị mới và đào tạo nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"the capital city","vi":"thành phố thủ đô"},{"en":"raise capital","vi":"huy động vốn"},{"en":"a capital letter","vi":"chữ cái viết hoa"}],"wordFamily":["capitalist (n.)","capitalism (n.)","capitalise (v.)","capitalisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa chỉ tiền vốn thường không đếm được; nghĩa chỉ chữ cái viết hoa là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_charge', 'en-b1-36', 'charge', '/tʃɑːrdʒ/', 'B1', 'tính phí; đòi tiền; khoản phí; tiền thù lao; sạc điện; nạp điện', 'v.', 'charger (n.), recharge (v.), rechargeable (adj.)', NULL, 'To charge someone a specific fee for something: charge someone for something.', 'They charge extra if you want breakfast in your room.', NULL, 'Họ sẽ tính thêm phí nếu bạn muốn ăn sáng tại phòng.', '{"wordId":"charge","ukIpa":"/tʃɑːdʒ/","usIpa":"/tʃɑːrdʒ/","cefr":"B1","topic":"economy","senses":[{"pos":"v.","en":"Ask someone to pay a particular amount for something.","vi":"tính phí; đòi tiền"},{"pos":"n.","en":"An amount of money requested for goods or services.","vi":"khoản phí; tiền thù lao"},{"pos":"v.","en":"Put electrical energy into a battery or device.","vi":"sạc điện; nạp điện"}],"examples":[{"en":"They charge extra if you want breakfast in your room.","vi":"Họ sẽ tính thêm phí nếu bạn muốn ăn sáng tại phòng.","audioKind":"ex"},{"en":"Museums that charge admission fees should offer discounts to ensure that students can still access cultural resources.","vi":"Các bảo tàng thu phí vào cửa nên có các chương trình giảm giá để đảm bảo học sinh vẫn có thể tiếp cận các nguồn tài nguyên văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"charge a fee","vi":"tính phí"},{"en":"free of charge","vi":"miễn phí"},{"en":"charge a battery","vi":"sạc pin"},{"en":"in charge of","vi":"chịu trách nhiệm; phụ trách"}],"wordFamily":["charger (n.)","recharge (v.)","rechargeable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"To charge someone a specific fee for something: charge someone for something.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_deal', 'en-b1-36', 'deal', '/diːl/', 'B1', 'thỏa thuận; giao dịch kinh doanh; giải quyết; đối phó (thường dùng với with); chia (bài); phân phát', 'n.', 'dealer (n.), dealing (n.)', NULL, 'Cụm deal with dùng để chỉ việc xử lý/giải quyết; a great deal of đi với danh từ không đếm được.', 'We got a good deal on our new sofa.', NULL, 'Chúng tôi đã mua được chiếc ghế sofa mới với một mức giá rất hời.', '{"wordId":"deal","ukIpa":"/diːl/","usIpa":"/diːl/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"an agreement between people or organisations, especially in business","vi":"thỏa thuận; giao dịch kinh doanh"},{"pos":"v.","en":"to take action about a problem, usually with with","vi":"giải quyết; đối phó (thường dùng với with)"},{"pos":"v.","en":"to give cards or other things to several people","vi":"chia (bài); phân phát"}],"examples":[{"en":"We got a good deal on our new sofa.","vi":"Chúng tôi đã mua được chiếc ghế sofa mới với một mức giá rất hời.","audioKind":"ex"},{"en":"Governments must deal with housing shortages by supporting affordable construction and improving public transport links.","vi":"Chính phủ phải giải quyết tình trạng thiếu hụt nhà ở bằng cách hỗ trợ xây dựng nhà ở giá rẻ và cải thiện hệ thống giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"make a deal","vi":"đạt ược thỏa thuận"},{"en":"deal with a problem","vi":"giải quyết một vấn đề"},{"en":"a great deal of","vi":"rất nhiều; số lượng lớn"},{"en":"deal cards","vi":"chia bài"}],"wordFamily":["dealer (n.)","dealing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm deal with dùng để chỉ việc xử lý/giải quyết; a great deal of đi với danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brand', 'en-b1-36', 'brand', '/brænd/', 'B1', 'thương hiệu; nhãn hiệu; gán nhãn xấu; đóng mác tiêu cực', 'n.', 'branded (adj.), branding (n.)', NULL, 'brand chỉ nhãn hiệu sản phẩm; trademark nhấn mạnh nhãn hiệu được pháp luật bảo vệ.', 'Which brand of toothpaste do you usually buy?', NULL, 'Bạn thường mua kem đánh răng nhãn hiệu nào?', '{"wordId":"brand","ukIpa":"/brænd/","usIpa":"/brænd/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"A product name identifying the company that makes it","vi":"thương hiệu; nhãn hiệu"},{"pos":"v.","en":"To describe someone publicly as having a particular bad quality","vi":"gán nhãn xấu; đóng mác tiêu cực"}],"examples":[{"en":"Which brand of toothpaste do you usually buy?","vi":"Bạn thường mua kem đánh răng nhãn hiệu nào?","audioKind":"ex"},{"en":"Consumers may choose a familiar brand even when cheaper alternatives offer similar quality.","vi":"Người tiêu dùng có thể chọn một thương hiệu quen thuộc ngay cả khi các lựa chọn thay thế rẻ hơn có chất lượng tương đương.","audioKind":"ex2"}],"collocations":[{"en":"brand loyalty","vi":"lòng trung thành với thương hiệu"},{"en":"brand image","vi":"hình ảnh thương hiệu"},{"en":"a leading brand","vi":"thương hiệu hàng đầu"},{"en":"brand someone as","vi":"gắn mác ai đó là"}],"wordFamily":["branded (adj.)","branding (n.)"],"synonyms":[],"antonyms":[],"tipVi":"brand chỉ nhãn hiệu sản phẩm; trademark nhấn mạnh nhãn hiệu được pháp luật bảo vệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quantity', 'en-b1-36', 'quantity', '/ˈkwɑːntəti/', 'B1', 'số lượng; khối lượng', 'n.', 'quantify (v.), quantitative (adj.)', 'Đồng nghĩa: amount', 'quantity chỉ số lượng, quality chỉ chất lượng; a quantity of có thể đi kèm với cả danh từ đếm được và không đếm được.', 'We bought a large quantity of rice yesterday.', NULL, 'Chúng tôi đã mua một lượng lớn gạo vào ngày hôm qua.', '{"wordId":"quantity","ukIpa":"/ˈkwɒntəti/","usIpa":"/ˈkwɑːntəti/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"the amount or number of something","vi":"số lượng; khối lượng"}],"examples":[{"en":"We bought a large quantity of rice yesterday.","vi":"Chúng tôi đã mua một lượng lớn gạo vào ngày hôm qua.","audioKind":"ex"},{"en":"Reducing the quantity of food wasted by households could lower both environmental damage and living costs.","vi":"Giảm lượng thực phẩm lãng phí bởi các hộ gia đình có thể làm giảm cả tổn hại môi trường và chi phí sinh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"a large quantity of","vi":"một lượng lớn"},{"en":"in small quantities","vi":"với số lượng ít"},{"en":"quality over quantity","vi":"chất lượng hơn số lượng"}],"wordFamily":["quantify (v.)","quantitative (adj.)"],"synonyms":["amount"],"antonyms":[],"tipVi":"quantity chỉ số lượng, quality chỉ chất lượng; a quantity of có thể đi kèm với cả danh từ đếm được và không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trade', 'en-b1-36', 'trade', '/treɪd/', 'B1', 'hoạt động buôn bán, giao thương hàng hóa hoặc dịch vụ; trao đổi, mua bán hàng hóa hoặc dịch vụ; nghề thủ công, nghề nghiệp chân tay', 'n.', 'trader (n.), trading (n.)', 'Đồng nghĩa: commerce', 'trade A for B dùng để chỉ việc dùng A để đổi lấy B; by trade dùng để chỉ nghề nghiệp chuyên môn.', 'At lunch, I traded my apple for a pear.', NULL, 'Vào bữa trưa, tôi đã đổi quả táo của mình lấy một quả lê.', '{"wordId":"trade","ukIpa":"/treɪd/","usIpa":"/treɪd/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"the activity of buying and selling goods or services","vi":"hoạt động buôn bán, giao thương hàng hóa hoặc dịch vụ"},{"pos":"v.","en":"to buy, sell, or exchange goods or services","vi":"trao đổi, mua bán hàng hóa hoặc dịch vụ"},{"pos":"n.","en":"a skilled job, especially one involving practical work","vi":"nghề thủ công, nghề nghiệp chân tay"}],"examples":[{"en":"At lunch, I traded my apple for a pear.","vi":"Vào bữa trưa, tôi đã đổi quả táo của mình lấy một quả lê.","audioKind":"ex"},{"en":"International trade can create employment, but governments must ensure that workers receive fair wages and adequate protection.","vi":"Thương mại quốc tế có thể tạo ra việc làm, nhưng các chính phủ phải đảm bảo rằng người lao động nhận được mức lương công bằng và sự bảo vệ đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"international trade","vi":"thương mại quốc tế"},{"en":"trade agreement","vi":"hiệp định thương mại"},{"en":"trade with","vi":"buôn bán với"},{"en":"learn a trade","vi":"học một nghề"}],"wordFamily":["trader (n.)","trading (n.)"],"synonyms":["commerce"],"antonyms":[],"tipVi":"trade A for B dùng để chỉ việc dùng A để đổi lấy B; by trade dùng để chỉ nghề nghiệp chuyên môn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invest', 'en-b1-36', 'invest', '/ɪnˈvest/', 'B1', 'đầu tư; dành (thời gian, công sức, tài nguyên) cho việc gì', 'v.', 'investment (n.), investor (n.)', 'Trái nghĩa: divest', 'Thường đi với giới từ invest in; đầu tư thời gian làm gì dùng invest time in doing.', 'My aunt plans to invest in a small bakery.', NULL, 'Cô của tôi dự định đầu tư vào một tiệm bánh nhỏ.', '{"wordId":"invest","ukIpa":"/ɪnˈvest/","usIpa":"/ɪnˈvest/","cefr":"B1","topic":"economy","senses":[{"pos":"v.","en":"To put money into something hoping to gain financial returns.","vi":"đầu tư"},{"pos":"v.","en":"To devote resources to something for a future benefit.","vi":"dành (thời gian, công sức, tài nguyên) cho việc gì"}],"examples":[{"en":"My aunt plans to invest in a small bakery.","vi":"Cô của tôi dự định đầu tư vào một tiệm bánh nhỏ.","audioKind":"ex"},{"en":"Governments should invest in renewable energy to improve energy security and reduce dependence on imported fuels.","vi":"Chính phủ nên đầu tư vào năng lượng tái tạo để cải thiện an ninh năng lượng và giảm sự phụ thuộc vào nhiên liệu nhập khẩu.","audioKind":"ex2"}],"collocations":[{"en":"invest in property","vi":"đầu tư vào bất động sản"},{"en":"invest heavily in","vi":"đầu tư mạnh mẽ vào"},{"en":"invest time in","vi":"dành thời gian vào"},{"en":"invest wisely","vi":"đầu tư một cách khôn ngoan"}],"wordFamily":["investment (n.)","investor (n.)"],"synonyms":[],"antonyms":["divest"],"tipVi":"Thường đi với giới từ invest in; đầu tư thời gian làm gì dùng invest time in doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compete', 'en-b1-36', 'compete', '/kəmˈpiːt/', 'B1', 'cạnh tranh; tranh đua; thi đấu; tham gia tranh tài', 'v.', 'competition (n.), competitor (n.), competitive (adj.), competitively (adv.)', NULL, 'compete đi với with/against khi đấu với đối thủ; for khi tranh giải thưởng; in khi tham gia giải đấu.', 'Several bakeries compete for customers on our street.', NULL, 'Nhiều tiệm bánh cạnh tranh nhau để thu hút khách hàng trên con phố của chúng tôi.', '{"wordId":"compete","ukIpa":"/kəmˈpiːt/","usIpa":"/kəmˈpiːt/","cefr":"B1","topic":"economy","senses":[{"pos":"v.","en":"Try to win or succeed against others.","vi":"cạnh tranh; tranh đua"},{"pos":"v.","en":"Take part in a sporting event or other contest.","vi":"thi đấu; tham gia tranh tài"}],"examples":[{"en":"Several bakeries compete for customers on our street.","vi":"Nhiều tiệm bánh cạnh tranh nhau để thu hút khách hàng trên con phố của chúng tôi.","audioKind":"ex"},{"en":"Small businesses often struggle to compete with larger companies that can offer lower prices.","vi":"Các doanh nghiệp nhỏ thường chật vật khi phải cạnh tranh với những tập đoàn lớn có khả năng đưa ra mức giá thấp hơn.","audioKind":"ex2"}],"collocations":[{"en":"compete with","vi":"cạnh tranh với"},{"en":"compete for","vi":"cạnh tranh để giành"},{"en":"compete in a tournament","vi":"thi đấu trong giải đấu"}],"wordFamily":["competition (n.)","competitor (n.)","competitive (adj.)","competitively (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"compete đi với with/against khi đấu với đối thủ; for khi tranh giải thưởng; in khi tham gia giải đấu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insurance', 'en-b1-36', 'insurance', '/ɪnˈʃʊrəns/', 'B1', 'bảo hiểm; biện pháp phòng ngừa; sự bảo đảm', 'n.', 'insure (v.), insurer (n.), insured (adj.)', NULL, 'Thông thường không đếm được; phí bảo hiểm dùng premium, hợp đồng bảo hiểm dùng policy.', 'Our travel insurance covered the cost of my lost suitcase.', NULL, 'Bảo hiểm du lịch của chúng tôi đã chi trả chi phí cho chiếc vali bị mất của tôi.', '{"wordId":"insurance","ukIpa":"/ɪnˈʃʊərəns/","usIpa":"/ɪnˈʃʊrəns/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"An arrangement providing financial protection against specified risks.","vi":"bảo hiểm"},{"pos":"n.","en":"Something that protects against a possible future problem.","vi":"biện pháp phòng ngừa; sự bảo đảm"}],"examples":[{"en":"Our travel insurance covered the cost of my lost suitcase.","vi":"Bảo hiểm du lịch của chúng tôi đã chi trả chi phí cho chiếc vali bị mất của tôi.","audioKind":"ex"},{"en":"Affordable health insurance can prevent families from facing serious financial difficulties when someone becomes ill.","vi":"Bảo hiểm y tế với mức phí hợp lý có thể giúp các gia đình tránh khỏi những khó khăn tài chính nghiêm trọng khi có người ốm đau.","audioKind":"ex2"}],"collocations":[{"en":"take out insurance","vi":"mua bảo hiểm"},{"en":"health insurance","vi":"bảo hiểm y tế"},{"en":"insurance premium","vi":"phí bảo hiểm"},{"en":"insurance claim","vi":"yêu cầu bồi thường bảo hiểm"}],"wordFamily":["insure (v.)","insurer (n.)","insured (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thông thường không đếm được; phí bảo hiểm dùng premium, hợp đồng bảo hiểm dùng policy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fixed', 'en-b1-36', 'fixed', '/fɪkst/', 'B1', 'cố định; không đổi; được gắn chặt; kiên cố', 'adj.', 'fix (v.), fixing (n.)', 'Đồng nghĩa: set, unchanging · Trái nghĩa: variable, flexible', 'fixed price là giá cố định; fixed cũng có thể đóng vai trò là phân từ quá khứ của fix.', 'This cafe offers lunch at a fixed price.', NULL, 'Quán cà phê này phục vụ bữa trưa với mức giá cố định.', '{"wordId":"fixed","ukIpa":"/fɪkst/","usIpa":"/fɪkst/","cefr":"B1","topic":"economy","senses":[{"pos":"adj.","en":"set and not changing or adjustable","vi":"cố định; không đổi"},{"pos":"adj.","en":"securely attached in one position","vi":"được gắn chặt; kiên cố"}],"examples":[{"en":"This cafe offers lunch at a fixed price.","vi":"Quán cà phê này phục vụ bữa trưa với mức giá cố định.","audioKind":"ex"},{"en":"Workers on fixed incomes may struggle to afford basic necessities when inflation significantly increases the cost of living.","vi":"Những người lao động có thu nhập cố định có thể chật vật để chi trả cho các nhu yếu phẩm cơ bản khi lạm phát làm tăng vọt chi phí sinh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"fixed price","vi":"giá cố định"},{"en":"fixed income","vi":"thu nhập cố định"},{"en":"fixed rate","vi":"lãi suất cố định"},{"en":"fixed term","vi":"thời hạn cố định"}],"wordFamily":["fix (v.)","fixing (n.)"],"synonyms":["set","unchanging"],"antonyms":["variable","flexible"],"tipVi":"fixed price là giá cố định; fixed cũng có thể đóng vai trò là phân từ quá khứ của fix.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_economy', 'en-b1-36', 'economy', '/ɪˈkɑːnəmi/', 'B1', 'nền kinh tế; sự tiết kiệm', 'n.', 'economic (adj.), economical (adj.), economist (n.), economise (v.)', NULL, 'Tính từ economic có nghĩa thuộc về kinh tế; còn economical có nghĩa là tiết kiệm, kinh tế (lợi về chi phí).', 'Tourists support the local economy by shopping here.', NULL, 'Khách du lịch đóng góp cho nền kinh tế địa phương bằng cách mua sắm tại đây.', '{"wordId":"economy","ukIpa":"/ɪˈkɒnəmi/","usIpa":"/ɪˈkɑːnəmi/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"the system of producing, trading, and using goods and services","vi":"nền kinh tế"},{"pos":"n.","en":"careful use of money, time, or resources to avoid waste","vi":"sự tiết kiệm"}],"examples":[{"en":"Tourists support the local economy by shopping here.","vi":"Khách du lịch đóng góp cho nền kinh tế địa phương bằng cách mua sắm tại đây.","audioKind":"ex"},{"en":"Investing in renewable energy can strengthen the economy while reducing dependence on imported fuels.","vi":"Đầu tư vào năng lượng tái tạo có thể củng cố nền kinh tế đồng thời giảm bớt sự phụ thuộc vào nhiên liệu nhập khẩu.","audioKind":"ex2"}],"collocations":[{"en":"local economy","vi":"kinh tế địa phương"},{"en":"global economy","vi":"kinh tế toàn cầu"},{"en":"boost the economy","vi":"kích thích nền kinh tế"},{"en":"fuel economy","vi":"khả năng tiết kiệm nhiên liệu"}],"wordFamily":["economic (adj.)","economical (adj.)","economist (n.)","economise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Tính từ economic có nghĩa thuộc về kinh tế; còn economical có nghĩa là tiết kiệm, kinh tế (lợi về chi phí).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_increasing', 'en-b1-36', 'increasing', '/ɪnˈkriːsɪŋ/', 'B1', 'tăng dần; ngày càng nhiều', 'adj.', 'increase (v.), increase (n.), increasingly (adv.)', 'Đồng nghĩa: growing, rising · Trái nghĩa: decreasing, declining', 'increasing bổ nghĩa cho danh từ; increasingly bổ nghĩa cho tính từ,...', 'The increasing noise outside made it hard to sleep.', NULL, 'Tiếng ồn ngày càng lớn bên ngoài khiến tôi khó có thể chợp mắt.', '{"wordId":"increasing","ukIpa":"/ɪnˈkriːsɪŋ/","usIpa":"/ɪnˈkriːsɪŋ/","cefr":"B1","topic":"economy","senses":[{"pos":"adj.","en":"becoming greater in amount, size, number, or degree","vi":"tăng dần; ngày càng nhiều"}],"examples":[{"en":"The increasing noise outside made it hard to sleep.","vi":"Tiếng ồn ngày càng lớn bên ngoài khiến tôi khó có thể chợp mắt.","audioKind":"ex"},{"en":"Increasing demand for clean energy is encouraging governments to invest more heavily in renewable technologies and infrastructure.","vi":"Nhu cầu ngày càng tăng đối với năng lượng sạch đang thúc đẩy các chính phủ đầu tư mạnh mẽ hơn vào công nghệ và cơ sở hạ tầng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"increasing demand","vi":"nhu cầu ngày càng tăng"},{"en":"increasing pressure","vi":"áp lực ngày càng lớn"},{"en":"an increasing number of","vi":"ngày càng nhiều"},{"en":"increasing concern","vi":"sự quan tâm ngày càng sâu sắc"}],"wordFamily":["increase (v.)","increase (n.)","increasingly (adv.)"],"synonyms":["growing","rising"],"antonyms":["decreasing","declining"],"tipVi":"increasing bổ nghĩa cho danh từ; increasingly bổ nghĩa cho tính từ,...","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_production', 'en-b1-36', 'production', '/prəˈdʌkʃən/', 'B1', 'sự sản xuất; chế tạo; sự sản xuất phim, kịch hoặc tác phẩm nghệ thuật', 'n.', 'produce (v.), producer (n.), product (n.), productive (adj.)', NULL, 'production thường không đếm được; khi chỉ một tác phẩm biểu diễn thì đếm được.', 'The factory has increased production to meet summer demand.', NULL, 'Nhà máy đã tăng sản lượng để đáp ứng nhu cầu mùa hè.', '{"wordId":"production","ukIpa":"/prəˈdʌkʃən/","usIpa":"/prəˈdʌkʃən/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"the process of making or growing things for use","vi":"sự sản xuất; chế tạo"},{"pos":"n.","en":"the making of a film or play, or the resulting work","vi":"sự sản xuất phim, kịch hoặc tác phẩm nghệ thuật"}],"examples":[{"en":"The factory has increased production to meet summer demand.","vi":"Nhà máy đã tăng sản lượng để đáp ứng nhu cầu mùa hè.","audioKind":"ex"},{"en":"Cleaner energy production can reduce air pollution while supporting the development of a modern economy.","vi":"Việc sản xuất năng lượng sạch hơn có thể giảm ô nhiễm không khí đồng thời hỗ trợ sự phát triển của nền kinh tế hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"mass production","vi":"sản xuất hàng loạt"},{"en":"food production","vi":"sản xuất thực phẩm"},{"en":"production costs","vi":"chi phí sản xuất"},{"en":"film production","vi":"sản xuất phim"}],"wordFamily":["produce (v.)","producer (n.)","product (n.)","productive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"production thường không đếm được; khi chỉ một tác phẩm biểu diễn thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_average', 'en-b1-36', 'average', '/ˈævərɪdʒ/', 'B1', 'trung bình; thông thường; số trung bình; mức trung bình; đạt mức trung bình; tính trung bình', 'adj.', 'averaging (n.)', NULL, 'on average có nghĩa là "trung bình", không dùng in average.', 'The average price of these jackets is quite reasonable.', NULL, 'Giá trung bình của những chiếc áo khoác này khá hợp lý.', '{"wordId":"average","ukIpa":"/ˈævərɪdʒ/","usIpa":"/ˈævərɪdʒ/","cefr":"B1","topic":"economy","senses":[{"pos":"adj.","en":"Representing a calculated middle value, or typical rather than exceptional.","vi":"trung bình; thông thường"},{"pos":"n.","en":"A value calculated by dividing a total by the item count.","vi":"số trung bình; mức trung bình"},{"pos":"v.","en":"Have a particular amount as the usual or calculated middle value.","vi":"đạt mức trung bình; tính trung bình"}],"examples":[{"en":"The average price of these jackets is quite reasonable.","vi":"Giá trung bình của những chiếc áo khoác này khá hợp lý.","audioKind":"ex"},{"en":"Average household spending on energy may fall as better insulation reduces the need for heating.","vi":"Mức chi tiêu trung bình cho năng lượng của các hộ gia đình có thể giảm xuống khi các biện pháp cách nhiệt tốt hơn làm giảm nhu cầu sưởi ấm.","audioKind":"ex2"}],"collocations":[{"en":"on average","vi":"trung bình"},{"en":"above average","vi":"trên mức trung bình"},{"en":"average income","vi":"thu nhập trung bình"},{"en":"average temperature","vi":"nhiệt độ trung bình"}],"wordFamily":["averaging (n.)"],"synonyms":[],"antonyms":[],"tipVi":"on average có nghĩa là \"trung bình\", không dùng in average.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_luxury', 'en-b1-36', 'luxury', '/ˈlʌkʃəri/', 'B1', 'sự xa hoa; sự sang trọng; món hàng xa xỉ; thứ xa xỉ; xa hoa; cao cấp', 'n.', 'luxurious (adj.), luxuriously (adv.)', 'Đồng nghĩa: opulence', 'Chỉ trạng thái xa hoa thì không đếm được; chỉ một món tận hưởng thì đếm được.', 'The hotel offered a taste of luxury for one night.', NULL, 'Khách sạn mang đến cho chúng tôi trải nghiệm xa hoa trong một đêm.', '{"wordId":"luxury","ukIpa":"/ˈlʌkʃəri/","usIpa":"/ˈlʌkʃəri/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"Great comfort and pleasure involving expensive surroundings or possessions.","vi":"sự xa hoa; sự sang trọng"},{"pos":"n.","en":"Something enjoyable or expensive that is not essential.","vi":"món hàng xa xỉ; thứ xa xỉ"},{"pos":"adj.","en":"Providing exceptional comfort and quality, usually at a high price.","vi":"xa hoa; cao cấp"}],"examples":[{"en":"The hotel offered a taste of luxury for one night.","vi":"Khách sạn mang đến cho chúng tôi trải nghiệm xa hoa trong một đêm.","audioKind":"ex"},{"en":"As household incomes rise, goods once considered a luxury often become part of everyday life.","vi":"Khi thu nhập hộ gia đình tăng lên, những mặt hàng từng được coi là xa xỉ thường trở thành một phần của đời sống thường nhật.","audioKind":"ex2"}],"collocations":[{"en":"live in luxury","vi":"sống trong cảnh xa hoa"},{"en":"luxury goods","vi":"hàng xa xỉ"},{"en":"luxury hotel","vi":"khách sạn sang trọng"},{"en":"afford the luxury of","vi":"có điều kiện tận hưởng"}],"wordFamily":["luxurious (adj.)","luxuriously (adv.)"],"synonyms":["opulence"],"antonyms":[],"tipVi":"Chỉ trạng thái xa hoa thì không đếm được; chỉ một món tận hưởng thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_36_1', 'en-b1-36', 'Cách dùng “quantity” (n.) — số lượng; khối lượng', 'a large quantity of  ·  in small quantities  ·  quality over quantity', 'quantity chỉ số lượng, quality chỉ chất lượng; a quantity of có thể đi kèm với cả danh từ đếm được và không đếm được.', 'Họ từ (Word Family): quantify (v.), quantitative (adj.) | Đồng nghĩa: amount', '[{"hanzi":"We bought a large quantity of rice yesterday.","pinyin":"","meaning":"Chúng tôi đã mua một lượng lớn gạo vào ngày hôm qua."},{"hanzi":"Reducing the quantity of food wasted by households could lower both environmental damage and living costs.","pinyin":"","meaning":"Giảm lượng thực phẩm lãng phí bởi các hộ gia đình có thể làm giảm cả tổn hại môi trường và chi phí sinh hoạt."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_36_2', 'en-b1-36', 'Cách dùng “economy” (n.) — nền kinh tế', 'local economy  ·  global economy  ·  boost the economy', 'Tính từ economic có nghĩa thuộc về kinh tế; còn economical có nghĩa là tiết kiệm, kinh tế (lợi về chi phí).', 'Họ từ (Word Family): economic (adj.), economical (adj.), economist (n.), economise (v.)', '[{"hanzi":"Tourists support the local economy by shopping here.","pinyin":"","meaning":"Khách du lịch đóng góp cho nền kinh tế địa phương bằng cách mua sắm tại đây."},{"hanzi":"Investing in renewable energy can strengthen the economy while reducing dependence on imported fuels.","pinyin":"","meaning":"Đầu tư vào năng lượng tái tạo có thể củng cố nền kinh tế đồng thời giảm bớt sự phụ thuộc vào nhiên liệu nhập khẩu."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_36_3', 'en-b1-36', 'Cách dùng “compete” (v.) — cạnh tranh; tranh đua', 'compete with  ·  compete for  ·  compete in a tournament', 'compete đi với with/against khi đấu với đối thủ; for khi tranh giải thưởng; in khi tham gia giải đấu.', 'Họ từ (Word Family): competition (n.), competitor (n.), competitive (adj.), competitively (adv.)', '[{"hanzi":"Several bakeries compete for customers on our street.","pinyin":"","meaning":"Nhiều tiệm bánh cạnh tranh nhau để thu hút khách hàng trên con phố của chúng tôi."},{"hanzi":"Small businesses often struggle to compete with larger companies that can offer lower prices.","pinyin":"","meaning":"Các doanh nghiệp nhỏ thường chật vật khi phải cạnh tranh với những tập đoàn lớn có khả năng đưa ra mức giá thấp hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_36_4', 'en-b1-36', 'Cách dùng “trade” (n.) — hoạt động buôn bán, giao thương hàng hóa hoặc dịch vụ', 'international trade  ·  trade agreement  ·  trade with', 'trade A for B dùng để chỉ việc dùng A để đổi lấy B; by trade dùng để chỉ nghề nghiệp chuyên môn.', 'Họ từ (Word Family): trader (n.), trading (n.) | Đồng nghĩa: commerce', '[{"hanzi":"At lunch, I traded my apple for a pear.","pinyin":"","meaning":"Vào bữa trưa, tôi đã đổi quả táo của mình lấy một quả lê."},{"hanzi":"International trade can create employment, but governments must ensure that workers receive fair wages and adequate protection.","pinyin":"","meaning":"Thương mại quốc tế có thể tạo ra việc làm, nhưng các chính phủ phải đảm bảo rằng người lao động nhận được mức lương công bằng và sự bảo vệ đầy đủ."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_36_1', 'en-b1-36', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_1_1', 'ten_b1_36_1', 'demand', 'Demand for cold drinks rises sharply during hot weather.', 'Demand for cold drinks rises sharply during hot weather.', '/dɪˈmænd/', 'Nhu cầu về đồ uống lạnh tăng vọt trong thời tiết nóng bức.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_1_2', 'ten_b1_36_1', 'percentage', 'What percentage of your monthly income goes on rent?', 'What percentage of your monthly income goes on rent?', '/pərˈsentɪdʒ/', 'Thu nhập hàng tháng của bạn dành bao nhiêu phần trăm để trả tiền thuê nhà?', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_1_3', 'ten_b1_36_1', 'export', 'My aunt''s company exports handmade bowls to several countries.', 'My aunt''s company exports handmade bowls to several countries.', '/ɪkˈspɔːrt/', 'Công ty của dì tôi xuất khẩu bát thủ công sang một số quốc gia.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_1_4', 'ten_b1_36_1', 'competitor', 'The new bakery is our biggest competitor for local customers.', 'The new bakery is our biggest competitor for local customers.', '/kəmˈpetɪtər/', 'Tiệm bánh mới mở là đối thủ lớn nhất của chúng tôi trong việc thu hút khách hàng địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_1_5', 'ten_b1_36_1', 'loan', 'We took out a loan to repair the roof.', 'We took out a loan to repair the roof.', '/loʊn/', 'Chúng tôi đã vay một khoản tiền để sửa lại mái nhà.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_1_6', 'ten_b1_36_1', 'capital', 'We visited the capital and explored its busy markets.', 'We visited the capital and explored its busy markets.', '/ˈkæpɪtəl/', 'Chúng tôi đã đến thăm thủ đô và khám phá những khu chợ tấp nập ở đó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_1_7', 'ten_b1_36_1', 'charge', 'They charge extra if you want breakfast in your room.', 'They charge extra if you want breakfast in your room.', '/tʃɑːrdʒ/', 'Họ sẽ tính thêm phí nếu bạn muốn ăn sáng tại phòng.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_1_8', 'ten_b1_36_1', 'deal', 'We got a good deal on our new sofa.', 'We got a good deal on our new sofa.', '/diːl/', 'Chúng tôi đã mua được chiếc ghế sofa mới với một mức giá rất hời.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_36_1_1', 'en-b1-36', 'ten_b1_36_1', 'listening', 'listening', 'Demand for cold drinks rises sharply during hot weather.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhà máy đã tăng sản lượng để đáp ứng nhu cầu mùa hè.","Họ sẽ tính thêm phí nếu bạn muốn ăn sáng tại phòng.","Nhiều tiệm bánh cạnh tranh nhau để thu hút khách hàng trên con phố của chúng tôi.","Nhu cầu về đồ uống lạnh tăng vọt trong thời tiết nóng bức."]'::jsonb, 3, 'Demand for cold drinks rises sharply during hot weather. → Nhu cầu về đồ uống lạnh tăng vọt trong thời tiết nóng bức.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_36_1_2', 'en-b1-36', 'ten_b1_36_1', 'listening', 'listening', 'What percentage of your monthly income goes on rent?', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tiệm bánh mới mở là đối thủ lớn nhất của chúng tôi trong việc thu hút khách hàng địa phương.","Thu nhập hàng tháng của bạn dành bao nhiêu phần trăm để trả tiền thuê nhà?","Cô của tôi dự định đầu tư vào một tiệm bánh nhỏ.","Công ty của dì tôi xuất khẩu bát thủ công sang một số quốc gia."]'::jsonb, 1, 'What percentage of your monthly income goes on rent? → Thu nhập hàng tháng của bạn dành bao nhiêu phần trăm để trả tiền thuê nhà?', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_36_1_3', 'en-b1-36', 'ten_b1_36_1', 'listening', 'listening', 'My aunt''s company exports handmade bowls to several countries.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhiều tiệm bánh cạnh tranh nhau để thu hút khách hàng trên con phố của chúng tôi.","Tiệm bánh mới mở là đối thủ lớn nhất của chúng tôi trong việc thu hút khách hàng địa phương.","Quán cà phê này phục vụ bữa trưa với mức giá cố định.","Công ty của dì tôi xuất khẩu bát thủ công sang một số quốc gia."]'::jsonb, 3, 'My aunt''s company exports handmade bowls to several countries. → Công ty của dì tôi xuất khẩu bát thủ công sang một số quốc gia.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_36_2', 'en-b1-36', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_2_1', 'ten_b1_36_2', 'demand', 'Growing demand for affordable housing has encouraged local authorities to convert unused office buildings into residential accommodation.', 'Growing demand for affordable housing has encouraged local authorities to convert unused office buildings into residential accommodation.', '/dɪˈmænd/', 'Nhu cầu ngày càng tăng đối với nhà ở giá rẻ đã khuyến khích các cơ quan chức năng địa phương chuyển đổi các tòa nhà văn phòng bỏ trống thành không gian nhà ở.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_2_2', 'ten_b1_36_2', 'percentage', 'The percentage of households using renewable energy has increased as installation costs have fallen in recent years.', 'The percentage of households using renewable energy has increased as installation costs have fallen in recent years.', '/pərˈsentɪdʒ/', 'Tỷ lệ hộ gia đình sử dụng năng lượng tái tạo đã tăng lên khi chi phí lắp đặt giảm trong những năm gần đây.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_2_3', 'ten_b1_36_2', 'export', 'Countries that export mainly raw materials may be vulnerable to sudden changes in global commodity prices.', 'Countries that export mainly raw materials may be vulnerable to sudden changes in global commodity prices.', '/ɪkˈspɔːrt/', 'Các quốc gia chủ yếu xuất khẩu nguyên liệu thô có thể dễ bị tổn thương trước những biến động đột ngột của giá cả hàng hóa toàn cầu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_2_4', 'ten_b1_36_2', 'competitor', 'A business must understand its competitors before developing strategies to attract customers in an increasingly crowded market.', 'A business must understand its competitors before developing strategies to attract customers in an increasingly crowded market.', '/kəmˈpetɪtər/', 'Một doanh nghiệp phải hiểu rõ các đối thủ cạnh tranh trước khi vạch ra chiến lược thu hút khách hàng trong thị trường ngày càng chật chội.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_2_5', 'ten_b1_36_2', 'loan', 'Affordable student loans can widen access to university, although repayment may create financial pressure after graduation.', 'Affordable student loans can widen access to university, although repayment may create financial pressure after graduation.', '/loʊn/', 'Các khoản vay sinh viên vừa túi tiền có thể mở rộng cơ hội vào đại học, mặc dù việc trả nợ có thể tạo ra áp lực tài chính sau khi tốt nghiệp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_36_2_6', 'ten_b1_36_2', 'capital', 'Small businesses often struggle to obtain enough capital to invest in new equipment and staff training.', 'Small businesses often struggle to obtain enough capital to invest in new equipment and staff training.', '/ˈkæpɪtəl/', 'Các doanh nghiệp nhỏ thường gặp khó khăn trong việc huy động đủ vốn để đầu tư vào trang thiết bị mới và đào tạo nhân viên.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
