INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_36_2_2', 'en-b1-36', 'ten_b1_36_2', 'listening', 'listening', 'The percentage of households using renewable energy has increased as installation costs have fallen in recent years.', NULL, 'Trong câu vừa nghe, từ “percentage” mang nghĩa nào sau đây?', '["nghề nghiệp; chuyên môn (đòi hỏi đào tạo chuyên sâu)","tỷ lệ phần trăm; phần trăm","người bán; bên bán","riêng biệt; tách rời; độc lập"]'::jsonb, 1, '“percentage” (/pərˈsentɪdʒ/): tỷ lệ phần trăm; phần trăm. Câu đầy đủ: The percentage of households using renewable energy has increased as installation costs have fallen in recent years.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
