INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_36_2', 'en-b1-36', NULL, 'comprehensive_test', 'listening', 'What percentage of your monthly income goes on rent?', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Công ty của dì tôi xuất khẩu bát thủ công sang một số quốc gia.","Bạn thường mua kem đánh răng nhãn hiệu nào?","Bảo hiểm du lịch của chúng tôi đã chi trả chi phí cho chiếc vali bị mất của tôi.","Thu nhập hàng tháng của bạn dành bao nhiêu phần trăm để trả tiền thuê nhà?"]'::jsonb, 3, 'What percentage of your monthly income goes on rent? → Thu nhập hàng tháng của bạn dành bao nhiêu phần trăm để trả tiền thuê nhà?', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_36_3', 'en-b1-36', NULL, 'comprehensive_test', 'listening', 'export', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xuất khẩu; đem bán ra nước ngoài","ngô; bắp","chẳng bao lâu nữa; không lâu sau","chùm; bó; nải"]'::jsonb, 0, 'export (/ɪkˈspɔːrt/) → xuất khẩu; đem bán ra nước ngoài; hàng xuất khẩu; xuất dữ liệu (máy tính)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_36_4', 'en-b1-36', NULL, 'comprehensive_test', 'listening', 'The new bakery is our biggest competitor for local customers.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Khách sạn mang đến cho chúng tôi trải nghiệm xa hoa trong một đêm.","Chúng tôi đã đến thăm thủ đô và khám phá những khu chợ tấp nập ở đó.","Vào bữa trưa, tôi đã đổi quả táo của mình lấy một quả lê.","Tiệm bánh mới mở là đối thủ lớn nhất của chúng tôi trong việc thu hút khách hàng địa phương."]'::jsonb, 3, 'The new bakery is our biggest competitor for local customers. → Tiệm bánh mới mở là đối thủ lớn nhất của chúng tôi trong việc thu hút khách hàng địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_36_5', 'en-b1-36', NULL, 'comprehensive_test', 'listening', 'loan', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hiệu quả; có năng suất cao; tiết kiệm (thời gian, năng lượng)","dựa vào; lệ thuộc vào sự giúp đỡ của ai","sự so sánh; sự đối chiếu","khoản vay; khoản tiền cho vay"]'::jsonb, 3, 'loan (/loʊn/) → khoản vay; khoản tiền cho vay; sự cho mượn; sự cho vay; cho mượn; cho vay', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_36_6', 'en-b1-36', NULL, 'comprehensive_test', 'listening', 'We visited the capital and explored its busy markets.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tiệm bánh mới mở là đối thủ lớn nhất của chúng tôi trong việc thu hút khách hàng địa phương.","Quán cà phê này phục vụ bữa trưa với mức giá cố định.","Chúng tôi đã đến thăm thủ đô và khám phá những khu chợ tấp nập ở đó.","Bạn thường mua kem đánh răng nhãn hiệu nào?"]'::jsonb, 2, 'We visited the capital and explored its busy markets. → Chúng tôi đã đến thăm thủ đô và khám phá những khu chợ tấp nập ở đó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
