INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_36_8', 'en-b1-36', NULL, 'comprehensive_test', 'listening', 'We got a good deal on our new sofa.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tiệm bánh mới mở là đối thủ lớn nhất của chúng tôi trong việc thu hút khách hàng địa phương.","Chúng tôi đã vay một khoản tiền để sửa lại mái nhà.","Vào bữa trưa, tôi đã đổi quả táo của mình lấy một quả lê.","Chúng tôi đã mua được chiếc ghế sofa mới với một mức giá rất hời."]'::jsonb, 3, 'We got a good deal on our new sofa. → Chúng tôi đã mua được chiếc ghế sofa mới với một mức giá rất hời.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
