INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_36_18', 'en-b1-36', NULL, 'comprehensive_test', 'reading', NULL, 'Growing demand for affordable housing has encouraged local authorities to convert unused office buildings into residential accommodation.', 'Dựa vào câu trên, từ “demand” có nghĩa phù hợp nhất là gì?', '["nhu cầu","bất cứ thứ gì; bất luận cái gì","thích hợp; thuận tiện","cằm"]'::jsonb, 0, 'demand: nhu cầu; yêu cầu kiên quyết; đòi hỏi; cần thiết. Dịch cả câu: Nhu cầu ngày càng tăng đối với nhà ở giá rẻ đã khuyến khích các cơ quan chức năng địa phương chuyển đổi các tòa nhà văn phòng bỏ trống thành không gian nhà ở.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_36_19', 'en-b1-36', NULL, 'comprehensive_test', 'reading', NULL, 'The percentage of households using renewable energy has increased as installation costs have fallen in recent years.', 'Dựa vào câu trên, từ “percentage” có nghĩa phù hợp nhất là gì?', '["nguyên âm; chữ cái nguyên âm","nhà sinh vật học","tự động","tỷ lệ phần trăm; phần trăm"]'::jsonb, 3, 'percentage: tỷ lệ phần trăm; phần trăm. Dịch cả câu: Tỷ lệ hộ gia đình sử dụng năng lượng tái tạo đã tăng lên khi chi phí lắp đặt giảm trong những năm gần đây.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_36_20', 'en-b1-36', NULL, 'comprehensive_test', 'reading', NULL, 'Countries that export mainly raw materials may be vulnerable to sudden changes in global commodity prices.', 'Dựa vào câu trên, từ “export” có nghĩa phù hợp nhất là gì?', '["xấu hổ; hổ thẹn","xuất khẩu; đem bán ra nước ngoài","phim tài liệu; chương trình tài liệu","làm hỏng; tàn phá"]'::jsonb, 1, 'export: xuất khẩu; đem bán ra nước ngoài; hàng xuất khẩu; xuất dữ liệu (máy tính). Dịch cả câu: Các quốc gia chủ yếu xuất khẩu nguyên liệu thô có thể dễ bị tổn thương trước những biến động đột ngột của giá cả hàng hóa toàn cầu.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_36_21', 'en-b1-36', NULL, 'comprehensive_test', 'reading', NULL, 'A business must understand its competitors before developing strategies to attract customers in an increasingly crowded market.', 'Dựa vào câu trên, từ “competitor” có nghĩa phù hợp nhất là gì?', '["con gà tây","đối thủ cạnh tranh","nhãn; mác","ở trung tâm; thuộc về trung tâm"]'::jsonb, 1, 'competitor: đối thủ cạnh tranh; thí sinh; người tham gia thi đấu. Dịch cả câu: Một doanh nghiệp phải hiểu rõ các đối thủ cạnh tranh trước khi vạch ra chiến lược thu hút khách hàng trong thị trường ngày càng chật chội.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_36_22', 'en-b1-36', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự sản xuất; chế tạo”', '["mask","production","tag","pray"]'::jsonb, 1, 'sự sản xuất; chế tạo → production (/prəˈdʌkʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_36_23', 'en-b1-36', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “trung bình; thông thường”', '["nowadays","average","biologist","advanced"]'::jsonb, 1, 'trung bình; thông thường → average (/ˈævərɪdʒ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_36_24', 'en-b1-36', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự xa hoa; sự sang trọng”', '["luxury","routine","Fahrenheit","terrified"]'::jsonb, 0, 'sự xa hoa; sự sang trọng → luxury (/ˈlʌkʃəri/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-37', 'en', 'Bài 37: Kinh tế & Tài chính (3) - CEFR B1', 'CEFR B1', 'B1 · Kinh tế', '20 từ vựng Tiếng Anh CEFR B1 chủ đề kinh tế & tài chính kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3037, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_buyer', 'en-b1-37', 'buyer', '/ˈbaɪər/', 'B1', 'người mua; khách hàng; nhân viên thu mua', 'n.', 'buy (v.), buying (n.)', 'Đồng nghĩa: purchaser · Trái nghĩa: seller', 'Buyer nhấn mạnh vào giao dịch mua bán; customer nhấn mạnh hơn vào khách hàng của cửa hàng hoặc dịch vụ.', 'The buyer checked the bicycle before handing over cash.', NULL, 'Người mua đã kiểm tra chiếc xe đạp trước khi trao tiền mặt.', '{"wordId":"buyer","ukIpa":"/ˈbaɪə/","usIpa":"/ˈbaɪər/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"a person or organisation that purchases something","vi":"người mua; khách hàng"},{"pos":"n.","en":"someone whose job is choosing goods for a business","vi":"nhân viên thu mua"}],"examples":[{"en":"The buyer checked the bicycle before handing over cash.","vi":"Người mua đã kiểm tra chiếc xe đạp trước khi trao tiền mặt.","audioKind":"ex"},{"en":"First-time buyers often struggle to enter the housing market because property prices rise faster than wages.","vi":"Những người mua nhà lần đầu thường gặp khó khăn trong việc gia nhập thị trường nhà ở vì giá nhà tăng nhanh hơn mức tăng tiền lương.","audioKind":"ex2"}],"collocations":[{"en":"potential buyer","vi":"người mua tiềm năng"},{"en":"first-time buyer","vi":"người mua nhà lần đầu"},{"en":"a buyer''s market","vi":"thị trường của người mua"}],"wordFamily":["buy (v.)","buying (n.)"],"synonyms":["purchaser"],"antonyms":["seller"],"tipVi":"Buyer nhấn mạnh vào giao dịch mua bán; customer nhấn mạnh hơn vào khách hàng của cửa hàng hoặc dịch vụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fee', 'en-b1-37', 'fee', '/fiː/', 'B1', 'tiền phí dịch vụ; học phí; thù lao chuyên môn', 'n.', NULL, 'Đồng nghĩa: charge', 'fee chỉ các khoản phí dịch vụ hoặc vào cửa; tiền boa thông thường dùng tip.', 'The gym charges a small fee for each class.', NULL, 'Phòng tập thể dục tính một khoản phí nhỏ cho mỗi lớp học.', '{"wordId":"fee","ukIpa":"/fiː/","usIpa":"/fiː/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"Money charged for a service, course, or professional advice.","vi":"tiền phí dịch vụ; học phí; thù lao chuyên môn"}],"examples":[{"en":"The gym charges a small fee for each class.","vi":"Phòng tập thể dục tính một khoản phí nhỏ cho mỗi lớp học.","audioKind":"ex"},{"en":"High tuition fees may discourage students from disadvantaged backgrounds from applying to university, even when financial assistance is available.","vi":"Học phí cao có thể khiến học sinh từ các hoàn cảnh khó khăn e ngại nộp đơn vào đại học, ngay cả khi có sẵn hỗ trợ tài chính.","audioKind":"ex2"}],"collocations":[{"en":"tuition fees","vi":"học phí"},{"en":"entrance fee","vi":"phí vào cửa"},{"en":"legal fees","vi":"phí pháp lý"},{"en":"pay a fee","vi":"trả phí"}],"wordFamily":[],"synonyms":["charge"],"antonyms":[],"tipVi":"fee chỉ các khoản phí dịch vụ hoặc vào cửa; tiền boa thông thường dùng tip.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_credit', 'en-b1-37', 'credit', '/ˈkredɪt/', 'B1', 'sự mua chịu; tín dụng; hình thức trả chậm hoặc vay tiền; sự công nhận; lời khen ngợi xứng đáng cho một thành tựu; tín chỉ học phần; đơn vị tích lũy khi hoàn thành một phần chương trình học', 'n.', 'creditor (n.), creditworthy (adj.), creditworthiness (n.)', NULL, 'on credit có nghĩa là mua chịu; nghĩa tín chỉ học tập là danh từ đếm được, thường ở dạng số nhiều.', 'We bought our new fridge on credit last month.', NULL, 'Tháng trước chúng tôi đã mua trả góp chiếc tủ lạnh mới.', '{"wordId":"credit","ukIpa":"/ˈkredɪt/","usIpa":"/ˈkredɪt/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"An arrangement allowing payment later or borrowing money.","vi":"sự mua chịu; tín dụng; hình thức trả chậm hoặc vay tiền"},{"pos":"n.","en":"Recognition that someone deserves for an achievement.","vi":"sự công nhận; lời khen ngợi xứng đáng cho một thành tựu"},{"pos":"n.","en":"A unit earned towards a qualification by completing coursework.","vi":"tín chỉ học phần; đơn vị tích lũy khi hoàn thành một phần chương trình học"}],"examples":[{"en":"We bought our new fridge on credit last month.","vi":"Tháng trước chúng tôi đã mua trả góp chiếc tủ lạnh mới.","audioKind":"ex"},{"en":"Affordable credit can help small businesses invest in equipment and create jobs within local communities.","vi":"Tín dụng với lãi suất hợp lý có thể giúp các doanh nghiệp nhỏ đầu tư vào trang thiết bị và tạo ra việc làm tại các cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"buy on credit","vi":"mua trả góp; mua chịu"},{"en":"give someone credit","vi":"ghi nhận công lao của ai"},{"en":"earn credits","vi":"tích lũy tín chỉ"},{"en":"credit card","vi":"thẻ tín dụng"}],"wordFamily":["creditor (n.)","creditworthy (adj.)","creditworthiness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"on credit có nghĩa là mua chịu; nghĩa tín chỉ học tập là danh từ đếm được, thường ở dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bargain', 'en-b1-37', 'bargain', '/ˈbɑːrɡɪn/', 'B1', 'món hời; hàng giá rẻ; mặc cả; thương lượng giá cả; thỏa thuận; hiệp ước', 'n.', 'bargaining (n.)', NULL, 'Món hời dùng danh từ đếm được; bargain with sb có nghĩa là mặc cả với ai đó.', 'This warm winter coat was a real bargain.', NULL, 'Chiếc áo khoác mùa đông ấm áp này thực sự là một món hời.', '{"wordId":"bargain","ukIpa":"/ˈbɑːɡɪn/","usIpa":"/ˈbɑːrɡɪn/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"Something bought for less than its usual price","vi":"món hời; hàng giá rẻ"},{"pos":"v.","en":"To discuss prices or conditions to reach an agreement","vi":"mặc cả; thương lượng giá cả"},{"pos":"n.","en":"An agreement about what each person will do","vi":"thỏa thuận; hiệp ước"}],"examples":[{"en":"This warm winter coat was a real bargain.","vi":"Chiếc áo khoác mùa đông ấm áp này thực sự là một món hời.","audioKind":"ex"},{"en":"Consumers can often bargain with local sellers, although fixed prices are more common in large stores.","vi":"Người tiêu dùng thường có thể mặc cả với người bán địa phương, mặc dù giá cố định phổ biến hơn ở các cửa hàng lớn.","audioKind":"ex2"}],"collocations":[{"en":"a real bargain","vi":"món hời lớn"},{"en":"bargain with someone","vi":"mặc cả với ai"},{"en":"strike a bargain","vi":"đạt được thỏa thuận"},{"en":"keep your side of the bargain","vi":"giữ đúng cam kết của bạn"}],"wordFamily":["bargaining (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Món hời dùng danh từ đếm được; bargain with sb có nghĩa là mặc cả với ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_billion', 'en-b1-37', 'billion', '/ˈbɪljən/', 'B1', 'một tỷ (1.000.000.000); số lượng cực lớn (thường dùng ở số nhiều)', 'num.', 'billionaire (n.)', NULL, 'Sau số đếm cụ thể billion không thêm s; khi chỉ số lượng phiếm định hàng tỷ thì dùng billions of.', 'The science museum displayed a rock a billion years old.', NULL, 'Bảo tàng khoa học đã trưng bày một viên đá có tuổi đời một tỷ năm.', '{"wordId":"billion","ukIpa":"/ˈbɪljən/","usIpa":"/ˈbɪljən/","cefr":"B1","topic":"economy","senses":[{"pos":"num.","en":"one thousand million","vi":"một tỷ (1.000.000.000)"},{"pos":"n.","en":"an extremely large quantity, usually expressed as billions","vi":"số lượng cực lớn (thường dùng ở số nhiều)"}],"examples":[{"en":"The science museum displayed a rock a billion years old.","vi":"Bảo tàng khoa học đã trưng bày một viên đá có tuổi đời một tỷ năm.","audioKind":"ex"},{"en":"Governments spend billions of dollars on transport infrastructure to support economic growth and connect isolated communities.","vi":"Các chính phủ chi hàng tỷ đô la cho cơ sở hạ tầng giao thông nhằm hỗ trợ tăng trưởng kinh tế và kết nối các cộng đồng bị cô lập.","audioKind":"ex2"}],"collocations":[{"en":"a billion dollars","vi":"một tỷ đô la"},{"en":"billions of people","vi":"hàng tỷ người"},{"en":"a billion years","vi":"một tỷ năm"}],"wordFamily":["billionaire (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Sau số đếm cụ thể billion không thêm s; khi chỉ số lượng phiếm định hàng tỷ thì dùng billions of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_minimum', 'en-b1-37', 'minimum', '/ˈmɪnɪməm/', 'B1', 'mức tối thiểu; lượng tối thiểu; tối thiểu', 'n.', 'minimise (v.), minimisation (n.), minimal (adj.), minimally (adv.)', 'Trái nghĩa: maximum', '"A minimum of" đi sau với danh từ chỉ số lượng, mang nghĩa là "ít nhất".', 'Please keep the noise to a minimum tonight.', NULL, 'Làm ơn hãy giữ tiếng ồn ở mức tối thiểu vào tối nay.', '{"wordId":"minimum","ukIpa":"/ˈmɪnɪməm/","usIpa":"/ˈmɪnɪməm/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"The smallest amount or level possible or allowed.","vi":"mức tối thiểu; lượng tối thiểu"},{"pos":"adj.","en":"Being the smallest amount or level possible or allowed.","vi":"tối thiểu"}],"examples":[{"en":"Please keep the noise to a minimum tonight.","vi":"Làm ơn hãy giữ tiếng ồn ở mức tối thiểu vào tối nay.","audioKind":"ex"},{"en":"A higher minimum wage may improve living standards for workers in low-paid service jobs.","vi":"Mức lương tối thiểu cao hơn có thể cải thiện mức sống cho người lao động làm các công việc dịch vụ thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"a minimum of","vi":"tối thiểu là"},{"en":"keep something to a minimum","vi":"giữ cái gì ở mức tối thiểu"},{"en":"minimum wage","vi":"lương tối thiểu"},{"en":"minimum requirements","vi":"yêu cầu tối thiểu"}],"wordFamily":["minimise (v.)","minimisation (n.)","minimal (adj.)","minimally (adv.)"],"synonyms":[],"antonyms":["maximum"],"tipVi":"\"A minimum of\" đi sau với danh từ chỉ số lượng, mang nghĩa là \"ít nhất\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discount', 'en-b1-37', 'discount', '/ˈdɪskaʊnt/', 'B1', 'sự giảm giá; chiết khấu; giảm giá bán; không xem xét; coi nhẹ', 'n.', 'discounted (adj.)', NULL, 'Danh từ trọng âm ở âm tiết đầu; động từ thường phát âm là /dɪsˈkaʊnt/.', 'The shop offers a discount on winter coats.', NULL, 'Cửa hàng đang có chương trình giảm giá áo khoác mùa đông.', '{"wordId":"discount","ukIpa":"/ˈdɪskaʊnt/","usIpa":"/ˈdɪskaʊnt/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"a reduction in the usual price","vi":"sự giảm giá; chiết khấu"},{"pos":"v.","en":"to sell something at a reduced price","vi":"giảm giá bán"},{"pos":"v.","en":"to consider something unlikely or less important","vi":"không xem xét; coi nhẹ"}],"examples":[{"en":"The shop offers a discount on winter coats.","vi":"Cửa hàng đang có chương trình giảm giá áo khoác mùa đông.","audioKind":"ex"},{"en":"Public transport discounts can encourage more commuters to leave their cars at home.","vi":"Mức giảm giá giao thông công cộng có thể khuyến khích nhiều người đi lại hơn để xe ở nhà.","audioKind":"ex2"}],"collocations":[{"en":"offer a discount","vi":"cung cấp mức giảm giá"},{"en":"at a discount","vi":"với giá ưu đãi"},{"en":"discount the possibility","vi":"loại trừ khả năng; không tính đến"}],"wordFamily":["discounted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ trọng âm ở âm tiết đầu; động từ thường phát âm là /dɪsˈkaʊnt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loss', 'en-b1-37', 'loss', '/lɔːs/', 'B1', 'sự mất mát; sự thất lạc; tổn thất; khoản lỗ; thâm hụt tài chính; thất bại trong trò chơi hoặc cuộc thi', 'n.', 'lose (v.), lost (adj.), loser (n.)', 'Trái nghĩa: gain', 'loss là danh từ, lose là động từ, dạng quá khứ và quá khứ phân từ là lost.', 'She reported the loss of her wallet yesterday.', NULL, 'Cô ấy đã báo mất ví vào ngày hôm qua.', '{"wordId":"loss","ukIpa":"/lɒs/","usIpa":"/lɔːs/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"The fact of no longer having someone or something.","vi":"sự mất mát; sự thất lạc; tổn thất"},{"pos":"n.","en":"Money lost when costs are higher than income.","vi":"khoản lỗ; thâm hụt tài chính"},{"pos":"n.","en":"A defeat in a game or competition.","vi":"thất bại trong trò chơi hoặc cuộc thi"}],"examples":[{"en":"She reported the loss of her wallet yesterday.","vi":"Cô ấy đã báo mất ví vào ngày hôm qua.","audioKind":"ex"},{"en":"The loss of natural habitats threatens biodiversity and can weaken ecosystems that support local agriculture.","vi":"Sự mất mát về môi trường sống tự nhiên đe dọa đa dạng sinh học và có thể làm suy yếu các hệ sinh thái hỗ trợ nông nghiệp địa phương.","audioKind":"ex2"}],"collocations":[{"en":"hearing loss","vi":"giảm thính lực"},{"en":"job losses","vi":"mất việc làm"},{"en":"at a loss","vi":"bị lỗ; lúng túng không biết phải làm gì"},{"en":"a financial loss","vi":"tổn thất tài chính"}],"wordFamily":["lose (v.)","lost (adj.)","loser (n.)"],"synonyms":[],"antonyms":["gain"],"tipVi":"loss là danh từ, lose là động từ, dạng quá khứ và quá khứ phân từ là lost.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_account', 'en-b1-37', 'account', '/əˈkaʊnt/', 'B1', 'tài khoản; bản tường thuật; bài miêu tả; giải thích; chiếm (tỷ lệ)', 'n.', 'accountant (n.), accounting (n.), accountable (adj.), accountability (n.)', NULL, 'account for có thể diễn tả nghĩa "giải thích nguyên nhân" hoặc "chiếm một tỷ lệ nào đó".', 'I opened a savings account at the local bank.', NULL, 'Tôi đã mở một tài khoản tiết kiệm tại ngân hàng địa phương.', '{"wordId":"account","ukIpa":"/əˈkaʊnt/","usIpa":"/əˈkaʊnt/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"an arrangement for managing money or accessing a service","vi":"tài khoản"},{"pos":"n.","en":"a spoken or written description of events","vi":"bản tường thuật; bài miêu tả"},{"pos":"v.","en":"with for: explain something or constitute a share of something","vi":"giải thích; chiếm (tỷ lệ)"}],"examples":[{"en":"I opened a savings account at the local bank.","vi":"Tôi đã mở một tài khoản tiết kiệm tại ngân hàng địa phương.","audioKind":"ex"},{"en":"Transport costs account for a substantial share of household spending, particularly in areas with limited public services.","vi":"Chi phí đi lại chiếm một phần đáng kể trong chi tiêu của hộ gia đình, đặc biệt là ở những khu vực có dịch vụ công cộng hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"open an account","vi":"mở tài khoản"},{"en":"give an account of","vi":"thuật lại"},{"en":"account for","vi":"giải thích; chiếm"},{"en":"take into account","vi":"cân nhắc; tính đến"}],"wordFamily":["accountant (n.)","accounting (n.)","accountable (adj.)","accountability (n.)"],"synonyms":[],"antonyms":[],"tipVi":"account for có thể diễn tả nghĩa \"giải thích nguyên nhân\" hoặc \"chiếm một tỷ lệ nào đó\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_consumer', 'en-b1-37', 'consumer', '/kənˈsuːmər/', 'B1', 'người tiêu dùng', 'n.', 'consume (v.), consumption (n.), consumerism (n.)', 'Đồng nghĩa: buyer, purchaser', 'consumer nhấn mạnh tư cách tiêu dùng; customer nhấn mạnh mối quan hệ giao dịch với người bán.', 'As a consumer, I always compare prices before buying.', NULL, 'Là một người tiêu dùng, tôi luôn so sánh giá cả trước khi mua hàng.', '{"wordId":"consumer","ukIpa":"/kənˈsjuːmə/","usIpa":"/kənˈsuːmər/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"A person who buys goods or services for personal use.","vi":"người tiêu dùng"}],"examples":[{"en":"As a consumer, I always compare prices before buying.","vi":"Là một người tiêu dùng, tôi luôn so sánh giá cả trước khi mua hàng.","audioKind":"ex"},{"en":"Governments should protect consumers by requiring companies to provide accurate information about their products.","vi":"Chính phủ nên bảo vệ người tiêu dùng bằng cách yêu cầu các doanh nghiệp cung cấp thông tin chính xác về sản phẩm của họ.","audioKind":"ex2"}],"collocations":[{"en":"consumer rights","vi":"quyền lợi người tiêu dùng"},{"en":"consumer demand","vi":"nhu cầu tiêu dùng"},{"en":"consumer goods","vi":"hàng tiêu dùng"},{"en":"consumer protection","vi":"bảo vệ người tiêu dùng"}],"wordFamily":["consume (v.)","consumption (n.)","consumerism (n.)"],"synonyms":["buyer","purchaser"],"antonyms":[],"tipVi":"consumer nhấn mạnh tư cách tiêu dùng; customer nhấn mạnh mối quan hệ giao dịch với người bán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_saving', 'en-b1-37', 'saving', '/ˈseɪvɪŋ/', 'B1', 'sự tiết kiệm; khoản tiền tiết kiệm; tiền tiết kiệm; tiền để dành', 'n.', 'save (v.), saver (n.)', NULL, 'Chỉ tiền tích lũy thường dùng dạng số nhiều savings; sự tiết kiệm dùng dạng số ít saving.', 'Buying a monthly pass gave me a useful saving.', NULL, 'Mua vé tháng giúp tôi tiết kiệm được một khoản tiền đáng kể.', '{"wordId":"saving","ukIpa":"/ˈseɪvɪŋ/","usIpa":"/ˈseɪvɪŋ/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"a reduction in the money, time, or resources used","vi":"sự tiết kiệm; khoản tiền tiết kiệm"},{"pos":"n.","en":"money kept rather than spent, usually for future needs","vi":"tiền tiết kiệm; tiền để dành"}],"examples":[{"en":"Buying a monthly pass gave me a useful saving.","vi":"Mua vé tháng giúp tôi tiết kiệm được một khoản tiền đáng kể.","audioKind":"ex"},{"en":"Investing in efficient heating systems can produce significant energy savings for households over the long term.","vi":"Đầu tư vào các hệ thống sưởi ấm hiệu quả có thể giúp các hộ gia đình tiết kiệm đáng kể năng lượng về lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"make a saving","vi":"tiết kiệm chi phí"},{"en":"energy savings","vi":"tiết kiệm năng lượng"},{"en":"life savings","vi":"tiền tích cóp cả đời"},{"en":"savings account","vi":"tài khoản tiết kiệm"}],"wordFamily":["save (v.)","saver (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ tiền tích lũy thường dùng dạng số nhiều savings; sự tiết kiệm dùng dạng số ít saving.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_payment', 'en-b1-37', 'payment', '/ˈpeɪmənt/', 'B1', 'sự thanh toán; việc trả tiền; khoản tiền phải trả; khoản thanh toán', 'n.', 'pay (v.), payable (adj.), payer (n.), repayment (n.)', NULL, 'Hành động thanh toán thường không đếm được; một khoản tiền thanh toán cụ thể dùng a payment.', 'The shop accepts payment by card or cash.', NULL, 'Cửa hàng chấp nhận thanh toán bằng thẻ hoặc tiền mặt.', '{"wordId":"payment","ukIpa":"/ˈpeɪmənt/","usIpa":"/ˈpeɪmənt/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"the act of giving money for something","vi":"sự thanh toán; việc trả tiền"},{"pos":"n.","en":"an amount of money paid or due to be paid","vi":"khoản tiền phải trả; khoản thanh toán"}],"examples":[{"en":"The shop accepts payment by card or cash.","vi":"Cửa hàng chấp nhận thanh toán bằng thẻ hoặc tiền mặt.","audioKind":"ex"},{"en":"Digital payment systems can make everyday transactions more convenient, but they may exclude people without internet access.","vi":"Hệ thống thanh toán số có thể giúp các giao dịch hàng ngày trở nên thuận tiện hơn, nhưng chúng có thể bỏ quên những người không có quyền truy cập internet.","audioKind":"ex2"}],"collocations":[{"en":"make a payment","vi":"thực hiện thanh toán"},{"en":"payment in advance","vi":"thanh toán trước"},{"en":"monthly payment","vi":"khoản trả hàng tháng"},{"en":"payment method","vi":"phương thức thanh toán"}],"wordFamily":["pay (v.)","payable (adj.)","payer (n.)","repayment (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Hành động thanh toán thường không đếm được; một khoản tiền thanh toán cụ thể dùng a payment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tax', 'en-b1-37', 'tax', '/tæks/', 'B1', 'thuế; tiền thuế; đánh thuế; làm căng thẳng; vắt kiệt', 'n.', 'taxation (n.), taxable (adj.), taxpayer (n.), taxing (adj.)', NULL, 'Tax có thể đóng vai trò là danh từ hoặc động từ; từ taxing thường chỉ việc tốn sức, mệt mỏi.', 'The tax on my monthly salary has gone up.', NULL, 'Khoản thuế trừ vào tiền lương hàng tháng của tôi đã tăng lên.', '{"wordId":"tax","ukIpa":"/tæks/","usIpa":"/tæks/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"Money paid to the government to fund public services.","vi":"thuế; tiền thuế"},{"pos":"v.","en":"Require someone to pay money to the government.","vi":"đánh thuế"},{"pos":"v.","en":"Put heavy demands on someone''s strength or abilities.","vi":"làm căng thẳng; vắt kiệt"}],"examples":[{"en":"The tax on my monthly salary has gone up.","vi":"Khoản thuế trừ vào tiền lương hàng tháng của tôi đã tăng lên.","audioKind":"ex"},{"en":"Governments can use tax revenue to improve public transport and make healthcare more accessible.","vi":"Chính phủ có thể sử dụng nguồn thu thuế để cải thiện giao thông công cộng và giúp dịch vụ y tế dễ tiếp cận hơn.","audioKind":"ex2"}],"collocations":[{"en":"income tax","vi":"thuế thu nhập"},{"en":"pay tax","vi":"đóng thuế"},{"en":"tax revenue","vi":"nguồn thu từ thuế"},{"en":"tax goods","vi":"đánh thuế hàng hóa"}],"wordFamily":["taxation (n.)","taxable (adj.)","taxpayer (n.)","taxing (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tax có thể đóng vai trò là danh từ hoặc động từ; từ taxing thường chỉ việc tốn sức, mệt mỏi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sum', 'en-b1-37', 'sum', '/sʌm/', 'B1', 'khoản tiền; tổng; tổng số; tóm tắt; khái quát', 'n.', 'summation (n.)', NULL, 'sum up dùng để chỉ hành động tóm tắt; một khoản tiền được diễn đạt là a sum of money.', 'She saved a small sum for a new bicycle.', NULL, 'Cô ấy đã tiết kiệm được một khoản tiền nhỏ để mua chiếc xe đạp mới.', '{"wordId":"sum","ukIpa":"/sʌm/","usIpa":"/sʌm/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"an amount of money","vi":"khoản tiền"},{"pos":"n.","en":"the total obtained by adding amounts together","vi":"tổng; tổng số"},{"pos":"v.","en":"to state the main points, usually with up","vi":"tóm tắt; khái quát"}],"examples":[{"en":"She saved a small sum for a new bicycle.","vi":"Cô ấy đã tiết kiệm được một khoản tiền nhỏ để mua chiếc xe đạp mới.","audioKind":"ex"},{"en":"Governments invest large sums in public transport to reduce congestion and improve urban air quality.","vi":"Chính phủ đầu tư những khoản tiền lớn vào giao thông công cộng nhằm giảm thiểu tình trạng ùn tắc và cải thiện chất lượng không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a large sum of money","vi":"một khoản tiền lớn"},{"en":"the sum of","vi":"tổng của"},{"en":"sum up","vi":"tóm tắt lại"}],"wordFamily":["summation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"sum up dùng để chỉ hành động tóm tắt; một khoản tiền được diễn đạt là a sum of money.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_profit', 'en-b1-37', 'profit', '/ˈprɑːfɪt/', 'B1', 'lợi nhuận; tiền lãi; thu lợi; có ích', 'n.', 'profitable (adj.), profitability (n.), profitably (adv.), unprofitable (adj.)', 'Trái nghĩa: loss', 'profit là lợi nhuận sau khi trừ chi phí, không đồng nghĩa với doanh thu revenue.', 'The bakery made a small profit this month.', NULL, 'Tiệm bánh đã kiếm được một khoản lợi nhuận nhỏ trong tháng này.', '{"wordId":"profit","ukIpa":"/ˈprɒfɪt/","usIpa":"/ˈprɑːfɪt/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"Money earned after paying the costs of a business.","vi":"lợi nhuận; tiền lãi"},{"pos":"v.","en":"To gain money or an advantage from something.","vi":"thu lợi; có ích"}],"examples":[{"en":"The bakery made a small profit this month.","vi":"Tiệm bánh đã kiếm được một khoản lợi nhuận nhỏ trong tháng này.","audioKind":"ex"},{"en":"Companies should invest part of their profit in cleaner technology to reduce environmental damage.","vi":"Các doanh nghiệp nên đầu tư một phần lợi nhuận của họ vào công nghệ sạch hơn để giảm thiểu tổn hại môi trường.","audioKind":"ex2"}],"collocations":[{"en":"make a profit","vi":"kiếm lợi nhuận"},{"en":"net profit","vi":"lợi nhuận ròng"},{"en":"profit margin","vi":"tỷ suất lợi nhuận"},{"en":"profit from","vi":"thu lợi từ"}],"wordFamily":["profitable (adj.)","profitability (n.)","profitably (adv.)","unprofitable (adj.)"],"synonyms":[],"antonyms":["loss"],"tipVi":"profit là lợi nhuận sau khi trừ chi phí, không đồng nghĩa với doanh thu revenue.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stock', 'en-b1-37', 'stock', '/stɑːk/', 'B1', 'hàng hóa trong kho; nguồn dự trữ; cổ phiếu; phần vốn góp; tích trữ; cung cấp hàng hóa', 'n.', 'stockist (n.), restock (v.)', NULL, 'stock với nghĩa hàng tồn kho thường không đếm được; dùng stocks khi chỉ cổ phiếu của các công ty khác nhau.', 'The shop has fresh stock arriving early tomorrow morning.', NULL, 'Cửa hàng có hàng mới về vào sáng sớm ngày mai.', '{"wordId":"stock","ukIpa":"/stɒk/","usIpa":"/stɑːk/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"Goods available for sale or supplies kept for future use.","vi":"hàng hóa trong kho; nguồn dự trữ"},{"pos":"n.","en":"Shares representing ownership in a company.","vi":"cổ phiếu; phần vốn góp"},{"pos":"v.","en":"To keep goods available for sale or use.","vi":"tích trữ; cung cấp hàng hóa"}],"examples":[{"en":"The shop has fresh stock arriving early tomorrow morning.","vi":"Cửa hàng có hàng mới về vào sáng sớm ngày mai.","audioKind":"ex"},{"en":"Small retailers often struggle to maintain sufficient stock when transport disruptions delay deliveries from major suppliers.","vi":"Các nhà bán lẻ nhỏ thường gặp khó khăn trong việc duy trì đủ hàng trong kho khi sự gián đoạn vận tải làm chậm trễ việc giao hàng từ các nhà cung cấp lớn.","audioKind":"ex2"}],"collocations":[{"en":"in stock","vi":"có sẵn trong kho"},{"en":"out of stock","vi":"hết hàng"},{"en":"the stock market","vi":"thị trường chứng khoán"},{"en":"stock up on food","vi":"dự trữ thực phẩm"}],"wordFamily":["stockist (n.)","restock (v.)"],"synonyms":[],"antonyms":[],"tipVi":"stock với nghĩa hàng tồn kho thường không đếm được; dùng stocks khi chỉ cổ phiếu của các công ty khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_voucher', 'en-b1-37', 'voucher', '/ˈvaʊtʃər/', 'B1', 'phiếu mua hàng; phiếu quà tặng; vé đổi hàng; chứng từ; biên lai thanh toán', 'n.', NULL, 'Đồng nghĩa: coupon', 'Thường dùng a voucher for; để chỉ việc đổi phiếu, dùng redeem a voucher.', 'I used my gift voucher to buy new shoes.', NULL, 'Tôi đã dùng phiếu quà tặng của mình để mua đôi giày mới.', '{"wordId":"voucher","ukIpa":"/ˈvaʊtʃə/","usIpa":"/ˈvaʊtʃər/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"A document exchangeable for goods, services, or a discount.","vi":"phiếu mua hàng; phiếu quà tặng; vé đổi hàng"},{"pos":"n.","en":"A document supporting a payment or accounting entry.","vi":"chứng từ; biên lai thanh toán"}],"examples":[{"en":"I used my gift voucher to buy new shoes.","vi":"Tôi đã dùng phiếu quà tặng của mình để mua đôi giày mới.","audioKind":"ex"},{"en":"Governments can provide training vouchers to help unemployed adults develop skills required by local employers.","vi":"Chính phủ có thể cung cấp các phiếu đào tạo để giúp lao động thất nghiệp phát triển các kỹ năng mà nhà tuyển dụng địa phương cần.","audioKind":"ex2"}],"collocations":[{"en":"gift voucher","vi":"phiếu quà tặng"},{"en":"travel voucher","vi":"phiếu du lịch"},{"en":"redeem a voucher","vi":"đổi phiếu lấy hàng"},{"en":"payment voucher","vi":"chứng từ thanh toán"}],"wordFamily":[],"synonyms":["coupon"],"antonyms":[],"tipVi":"Thường dùng a voucher for; để chỉ việc đổi phiếu, dùng redeem a voucher.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_value', 'en-b1-37', 'value', '/ˈvæljuː/', 'B1', 'giá trị; giá cả; tầm quan trọng; đánh giá cao; trân trọng; định giá; hệ giá trị; chuẩn mực sống', 'n.', 'valuable (adj.), valuation (n.), invaluable (adj.), valueless (adj.)', 'Đồng nghĩa: worth, appreciate · Trái nghĩa: devalue', 'Khi mang nghĩa "giá trị sống", từ này dùng dạng số nhiều values.', 'This sturdy backpack offers excellent value for the price.', NULL, 'Chiếc ba lô chắc chắn này rất đáng đồng tiền bát gạo.', '{"wordId":"value","ukIpa":"/ˈvæljuː/","usIpa":"/ˈvæljuː/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"the worth, price, or importance of something","vi":"giá trị; giá cả; tầm quan trọng"},{"pos":"v.","en":"consider something important or estimate how much it is worth","vi":"đánh giá cao; trân trọng; định giá"},{"pos":"n.","en":"beliefs about what is right and important in life","vi":"hệ giá trị; chuẩn mực sống"}],"examples":[{"en":"This sturdy backpack offers excellent value for the price.","vi":"Chiếc ba lô chắc chắn này rất đáng đồng tiền bát gạo.","audioKind":"ex"},{"en":"Governments should recognise the value of public parks in improving physical health and strengthening community relationships.","vi":"Chính phủ nên nhận ra tầm quan trọng của các công viên công cộng trong việc cải thiện sức khỏe thể chất và thắt chặt mối quan hệ cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"value for money","vi":"đáng đồng tiền bát gạo"},{"en":"place a high value on","vi":"đánh giá rất cao"},{"en":"property value","vi":"giá trị bất động sản"},{"en":"shared values","vi":"các giá trị chung"}],"wordFamily":["valuable (adj.)","valuation (n.)","invaluable (adj.)","valueless (adj.)"],"synonyms":["worth","appreciate"],"antonyms":["devalue"],"tipVi":"Khi mang nghĩa \"giá trị sống\", từ này dùng dạng số nhiều values.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coupon', 'en-b1-37', 'coupon', '/ˈkuːpɑːn/', 'B1', 'phiếu giảm giá; phiếu ưu đãi; phiếu lĩnh lãi trái phiếu', 'n.', NULL, 'Đồng nghĩa: voucher', 'coupon thường chỉ phiếu giảm giá mua hàng; từ voucher cũng hay được dùng để chỉ phiếu mua hàng trả trước.', 'This coupon gives us a discount on fresh vegetables.', NULL, 'Phiếu giảm giá này giúp chúng ta được giảm giá khi mua rau tươi.', '{"wordId":"coupon","ukIpa":"/ˈkuːpɒn/","usIpa":"/ˈkuːpɑːn/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"A ticket or code giving a discount or free item.","vi":"phiếu giảm giá; phiếu ưu đãi"},{"pos":"n.","en":"An interest payment on a bond, or its claiming slip.","vi":"phiếu lĩnh lãi trái phiếu"}],"examples":[{"en":"This coupon gives us a discount on fresh vegetables.","vi":"Phiếu giảm giá này giúp chúng ta được giảm giá khi mua rau tươi.","audioKind":"ex"},{"en":"Although discount coupons help households save money, they may also encourage consumers to buy unnecessary products.","vi":"Mặc dù các phiếu giảm giá giúp các hộ gia đình tiết kiệm tiền, chúng cũng có thể khuyến khích người tiêu dùng mua sắm những sản phẩm không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"discount coupon","vi":"phiếu giảm giá"},{"en":"coupon code","vi":"mã giảm giá"},{"en":"redeem a coupon","vi":"sử dụng phiếu giảm giá"},{"en":"coupon rate","vi":"lãi suất danh nghĩa"}],"wordFamily":[],"synonyms":["voucher"],"antonyms":[],"tipVi":"coupon thường chỉ phiếu giảm giá mua hàng; từ voucher cũng hay được dùng để chỉ phiếu mua hàng trả trước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_figure', 'en-b1-37', 'figure', '/ˈfɪɡjər/', 'B1', 'số liệu; con số; dáng người; hình dáng; nhân vật; cho rằng; nghĩ rằng; tính toán', 'n.', NULL, NULL, 'Dữ liệu thường dùng số nhiều figures; figure out có nghĩa là hiểu ra hoặc tìm ra.', 'She checked the final figure on the bill.', NULL, 'Cô ấy đã kiểm tra số tiền cuối cùng trên hóa đơn.', '{"wordId":"figure","ukIpa":"/ˈfɪɡə/","usIpa":"/ˈfɪɡjər/","cefr":"B1","topic":"economy","senses":[{"pos":"n.","en":"a number expressing an amount, especially in official information","vi":"số liệu; con số"},{"pos":"n.","en":"a person, their outline, or the shape of their body","vi":"dáng người; hình dáng; nhân vật"},{"pos":"v.","en":"to think or decide something after considering it","vi":"cho rằng; nghĩ rằng; tính toán"}],"examples":[{"en":"She checked the final figure on the bill.","vi":"Cô ấy đã kiểm tra số tiền cuối cùng trên hóa đơn.","audioKind":"ex"},{"en":"Recent employment figures suggest that investment in public transport can create substantial opportunities for local workers.","vi":"Các số liệu việc làm gần đây cho thấy việc đầu tư vào giao thông công cộng có thể tạo ra nhiều cơ hội lớn cho người lao động địa phương.","audioKind":"ex2"}],"collocations":[{"en":"sales figures","vi":"số liệu doanh thu"},{"en":"a leading figure","vi":"nhân vật hàng đầu"},{"en":"figure out","vi":"tính ra; tìm ra; hiểu rõ"},{"en":"a rough figure","vi":"số liệu ước chừng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dữ liệu thường dùng số nhiều figures; figure out có nghĩa là hiểu ra hoặc tìm ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_37_1', 'en-b1-37', 'Cách dùng “stock” (n.) — hàng hóa trong kho; nguồn dự trữ', 'in stock  ·  out of stock  ·  the stock market', 'stock với nghĩa hàng tồn kho thường không đếm được; dùng stocks khi chỉ cổ phiếu của các công ty khác nhau.', 'Họ từ (Word Family): stockist (n.), restock (v.)', '[{"hanzi":"The shop has fresh stock arriving early tomorrow morning.","pinyin":"","meaning":"Cửa hàng có hàng mới về vào sáng sớm ngày mai."},{"hanzi":"Small retailers often struggle to maintain sufficient stock when transport disruptions delay deliveries from major suppliers.","pinyin":"","meaning":"Các nhà bán lẻ nhỏ thường gặp khó khăn trong việc duy trì đủ hàng trong kho khi sự gián đoạn vận tải làm chậm trễ việc giao hàng từ các nhà cung cấp lớn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_37_2', 'en-b1-37', 'Cách dùng “coupon” (n.) — phiếu giảm giá; phiếu ưu đãi', 'discount coupon  ·  coupon code  ·  redeem a coupon', 'coupon thường chỉ phiếu giảm giá mua hàng; từ voucher cũng hay được dùng để chỉ phiếu mua hàng trả trước.', 'Đồng nghĩa: voucher', '[{"hanzi":"This coupon gives us a discount on fresh vegetables.","pinyin":"","meaning":"Phiếu giảm giá này giúp chúng ta được giảm giá khi mua rau tươi."},{"hanzi":"Although discount coupons help households save money, they may also encourage consumers to buy unnecessary products.","pinyin":"","meaning":"Mặc dù các phiếu giảm giá giúp các hộ gia đình tiết kiệm tiền, chúng cũng có thể khuyến khích người tiêu dùng mua sắm những sản phẩm không cần thiết."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_37_3', 'en-b1-37', 'Cách dùng “buyer” (n.) — người mua; khách hàng', 'potential buyer  ·  first-time buyer  ·  a buyer''s market', 'Buyer nhấn mạnh vào giao dịch mua bán; customer nhấn mạnh hơn vào khách hàng của cửa hàng hoặc dịch vụ.', 'Họ từ (Word Family): buy (v.), buying (n.) | Đồng nghĩa: purchaser · Trái nghĩa: seller', '[{"hanzi":"The buyer checked the bicycle before handing over cash.","pinyin":"","meaning":"Người mua đã kiểm tra chiếc xe đạp trước khi trao tiền mặt."},{"hanzi":"First-time buyers often struggle to enter the housing market because property prices rise faster than wages.","pinyin":"","meaning":"Những người mua nhà lần đầu thường gặp khó khăn trong việc gia nhập thị trường nhà ở vì giá nhà tăng nhanh hơn mức tăng tiền lương."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_37_4', 'en-b1-37', 'Cách dùng “credit” (n.) — sự mua chịu; tín dụng; hình thức trả chậm hoặc vay tiền', 'buy on credit  ·  give someone credit  ·  earn credits', 'on credit có nghĩa là mua chịu; nghĩa tín chỉ học tập là danh từ đếm được, thường ở dạng số nhiều.', 'Họ từ (Word Family): creditor (n.), creditworthy (adj.), creditworthiness (n.)', '[{"hanzi":"We bought our new fridge on credit last month.","pinyin":"","meaning":"Tháng trước chúng tôi đã mua trả góp chiếc tủ lạnh mới."},{"hanzi":"Affordable credit can help small businesses invest in equipment and create jobs within local communities.","pinyin":"","meaning":"Tín dụng với lãi suất hợp lý có thể giúp các doanh nghiệp nhỏ đầu tư vào trang thiết bị và tạo ra việc làm tại các cộng đồng địa phương."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_37_1', 'en-b1-37', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
