INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_37_1_3', 'ten_b1_37_1', 'credit', 'We bought our new fridge on credit last month.', 'We bought our new fridge on credit last month.', '/ˈkredɪt/', 'Tháng trước chúng tôi đã mua trả góp chiếc tủ lạnh mới.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_37_1_4', 'ten_b1_37_1', 'bargain', 'This warm winter coat was a real bargain.', 'This warm winter coat was a real bargain.', '/ˈbɑːrɡɪn/', 'Chiếc áo khoác mùa đông ấm áp này thực sự là một món hời.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_37_1_5', 'ten_b1_37_1', 'billion', 'The science museum displayed a rock a billion years old.', 'The science museum displayed a rock a billion years old.', '/ˈbɪljən/', 'Bảo tàng khoa học đã trưng bày một viên đá có tuổi đời một tỷ năm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_37_1_6', 'ten_b1_37_1', 'minimum', 'Please keep the noise to a minimum tonight.', 'Please keep the noise to a minimum tonight.', '/ˈmɪnɪməm/', 'Làm ơn hãy giữ tiếng ồn ở mức tối thiểu vào tối nay.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_37_1_7', 'ten_b1_37_1', 'discount', 'The shop offers a discount on winter coats.', 'The shop offers a discount on winter coats.', '/ˈdɪskaʊnt/', 'Cửa hàng đang có chương trình giảm giá áo khoác mùa đông.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_37_1_8', 'ten_b1_37_1', 'loss', 'She reported the loss of her wallet yesterday.', 'She reported the loss of her wallet yesterday.', '/lɔːs/', 'Cô ấy đã báo mất ví vào ngày hôm qua.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_37_1_1', 'en-b1-37', 'ten_b1_37_1', 'listening', 'listening', 'The buyer checked the bicycle before handing over cash.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người mua đã kiểm tra chiếc xe đạp trước khi trao tiền mặt.","Cô ấy đã tiết kiệm được một khoản tiền nhỏ để mua chiếc xe đạp mới.","Bảo tàng khoa học đã trưng bày một viên đá có tuổi đời một tỷ năm.","Làm ơn hãy giữ tiếng ồn ở mức tối thiểu vào tối nay."]'::jsonb, 0, 'The buyer checked the bicycle before handing over cash. → Người mua đã kiểm tra chiếc xe đạp trước khi trao tiền mặt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_37_1_2', 'en-b1-37', 'ten_b1_37_1', 'listening', 'listening', 'The gym charges a small fee for each class.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc ba lô chắc chắn này rất đáng đồng tiền bát gạo.","Cửa hàng có hàng mới về vào sáng sớm ngày mai.","Bảo tàng khoa học đã trưng bày một viên đá có tuổi đời một tỷ năm.","Phòng tập thể dục tính một khoản phí nhỏ cho mỗi lớp học."]'::jsonb, 3, 'The gym charges a small fee for each class. → Phòng tập thể dục tính một khoản phí nhỏ cho mỗi lớp học.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_37_1_3', 'en-b1-37', 'ten_b1_37_1', 'listening', 'listening', 'We bought our new fridge on credit last month.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Khoản thuế trừ vào tiền lương hàng tháng của tôi đã tăng lên.","Tháng trước chúng tôi đã mua trả góp chiếc tủ lạnh mới.","Cửa hàng có hàng mới về vào sáng sớm ngày mai.","Cô ấy đã báo mất ví vào ngày hôm qua."]'::jsonb, 1, 'We bought our new fridge on credit last month. → Tháng trước chúng tôi đã mua trả góp chiếc tủ lạnh mới.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_37_2', 'en-b1-37', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_37_2_1', 'ten_b1_37_2', 'buyer', 'First-time buyers often struggle to enter the housing market because property prices rise faster than wages.', 'First-time buyers often struggle to enter the housing market because property prices rise faster than wages.', '/ˈbaɪər/', 'Những người mua nhà lần đầu thường gặp khó khăn trong việc gia nhập thị trường nhà ở vì giá nhà tăng nhanh hơn mức tăng tiền lương.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_37_2_2', 'ten_b1_37_2', 'fee', 'High tuition fees may discourage students from disadvantaged backgrounds from applying to university, even when financial assistance is available.', 'High tuition fees may discourage students from disadvantaged backgrounds from applying to university, even when financial assistance is available.', '/fiː/', 'Học phí cao có thể khiến học sinh từ các hoàn cảnh khó khăn e ngại nộp đơn vào đại học, ngay cả khi có sẵn hỗ trợ tài chính.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_37_2_3', 'ten_b1_37_2', 'credit', 'Affordable credit can help small businesses invest in equipment and create jobs within local communities.', 'Affordable credit can help small businesses invest in equipment and create jobs within local communities.', '/ˈkredɪt/', 'Tín dụng với lãi suất hợp lý có thể giúp các doanh nghiệp nhỏ đầu tư vào trang thiết bị và tạo ra việc làm tại các cộng đồng địa phương.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_37_2_4', 'ten_b1_37_2', 'bargain', 'Consumers can often bargain with local sellers, although fixed prices are more common in large stores.', 'Consumers can often bargain with local sellers, although fixed prices are more common in large stores.', '/ˈbɑːrɡɪn/', 'Người tiêu dùng thường có thể mặc cả với người bán địa phương, mặc dù giá cố định phổ biến hơn ở các cửa hàng lớn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_37_2_5', 'ten_b1_37_2', 'billion', 'Governments spend billions of dollars on transport infrastructure to support economic growth and connect isolated communities.', 'Governments spend billions of dollars on transport infrastructure to support economic growth and connect isolated communities.', '/ˈbɪljən/', 'Các chính phủ chi hàng tỷ đô la cho cơ sở hạ tầng giao thông nhằm hỗ trợ tăng trưởng kinh tế và kết nối các cộng đồng bị cô lập.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_37_2_6', 'ten_b1_37_2', 'minimum', 'A higher minimum wage may improve living standards for workers in low-paid service jobs.', 'A higher minimum wage may improve living standards for workers in low-paid service jobs.', '/ˈmɪnɪməm/', 'Mức lương tối thiểu cao hơn có thể cải thiện mức sống cho người lao động làm các công việc dịch vụ thu nhập thấp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_37_2_1', 'en-b1-37', 'ten_b1_37_2', 'listening', 'listening', 'First-time buyers often struggle to enter the housing market because property prices rise faster than wages.', NULL, 'Trong câu vừa nghe, từ “buyer” mang nghĩa nào sau đây?', '["chủ yếu; quan trọng hàng đầu; chính","máy bay phản lực","người mua; khách hàng","bưu kiện; gói đồ"]'::jsonb, 2, '“buyer” (/ˈbaɪər/): người mua; khách hàng. Câu đầy đủ: First-time buyers often struggle to enter the housing market because property prices rise faster than wages.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_37_2_2', 'en-b1-37', 'ten_b1_37_2', 'listening', 'listening', 'High tuition fees may discourage students from disadvantaged backgrounds from applying to university, even when financial assistance is available.', NULL, 'Trong câu vừa nghe, từ “fee” mang nghĩa nào sau đây?', '["phích cắm điện","tiền phí dịch vụ; học phí; thù lao chuyên môn","ngày Lễ tặng quà (ngày 26 tháng 12)","hoàn toàn; tuyệt đối"]'::jsonb, 1, '“fee” (/fiː/): tiền phí dịch vụ; học phí; thù lao chuyên môn. Câu đầy đủ: High tuition fees may discourage students from disadvantaged backgrounds from applying to university, even when financial assistance is available.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
