INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_37_2', 'en-b1-37', NULL, 'comprehensive_test', 'listening', 'The gym charges a small fee for each class.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã dùng phiếu quà tặng của mình để mua đôi giày mới.","Chiếc áo khoác mùa đông ấm áp này thực sự là một món hời.","Phòng tập thể dục tính một khoản phí nhỏ cho mỗi lớp học.","Cửa hàng chấp nhận thanh toán bằng thẻ hoặc tiền mặt."]'::jsonb, 2, 'The gym charges a small fee for each class. → Phòng tập thể dục tính một khoản phí nhỏ cho mỗi lớp học.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_37_3', 'en-b1-37', NULL, 'comprehensive_test', 'listening', 'credit', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tủ gửi đồ; tủ có khóa (để đồ cá nhân)","hoãn lại; lùi lịch","biết ơn; cảm kích","sự mua chịu; tín dụng; hình thức trả chậm hoặc vay tiền"]'::jsonb, 3, 'credit (/ˈkredɪt/) → sự mua chịu; tín dụng; hình thức trả chậm hoặc vay tiền; sự công nhận; lời khen ngợi xứng đáng cho một thành tựu; tín chỉ học phần; đơn vị tích lũy khi hoàn thành một phần chương trình học', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_37_4', 'en-b1-37', NULL, 'comprehensive_test', 'listening', 'This warm winter coat was a real bargain.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Làm ơn hãy giữ tiếng ồn ở mức tối thiểu vào tối nay.","Phòng tập thể dục tính một khoản phí nhỏ cho mỗi lớp học.","Cửa hàng đang có chương trình giảm giá áo khoác mùa đông.","Chiếc áo khoác mùa đông ấm áp này thực sự là một món hời."]'::jsonb, 3, 'This warm winter coat was a real bargain. → Chiếc áo khoác mùa đông ấm áp này thực sự là một món hời.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_37_5', 'en-b1-37', NULL, 'comprehensive_test', 'listening', 'billion', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["một tỷ (1.000.000.000)","không thân thiện; lạnh lùng","trầm cảm; chán nản, thất vọng","lối đi lát đá bên cạnh đường dành cho người đi bộ"]'::jsonb, 0, 'billion (/ˈbɪljən/) → một tỷ (1.000.000.000); số lượng cực lớn (thường dùng ở số nhiều)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_37_6', 'en-b1-37', NULL, 'comprehensive_test', 'listening', 'Please keep the noise to a minimum tonight.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã dùng phiếu quà tặng của mình để mua đôi giày mới.","Cửa hàng có hàng mới về vào sáng sớm ngày mai.","Làm ơn hãy giữ tiếng ồn ở mức tối thiểu vào tối nay.","Cửa hàng đang có chương trình giảm giá áo khoác mùa đông."]'::jsonb, 2, 'Please keep the noise to a minimum tonight. → Làm ơn hãy giữ tiếng ồn ở mức tối thiểu vào tối nay.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_37_7', 'en-b1-37', NULL, 'comprehensive_test', 'listening', 'discount', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vỉa hè; lề đường","người đi xe đạp","ống khói","sự giảm giá; chiết khấu"]'::jsonb, 3, 'discount (/ˈdɪskaʊnt/) → sự giảm giá; chiết khấu; giảm giá bán; không xem xét; coi nhẹ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_37_8', 'en-b1-37', NULL, 'comprehensive_test', 'listening', 'She reported the loss of her wallet yesterday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã mở một tài khoản tiết kiệm tại ngân hàng địa phương.","Cô ấy đã báo mất ví vào ngày hôm qua.","Chiếc áo khoác mùa đông ấm áp này thực sự là một món hời.","Phòng tập thể dục tính một khoản phí nhỏ cho mỗi lớp học."]'::jsonb, 1, 'She reported the loss of her wallet yesterday. → Cô ấy đã báo mất ví vào ngày hôm qua.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_37_9', 'en-b1-37', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “one thousand million”?', '["discount","coupon","billion","voucher"]'::jsonb, 2, 'billion (/ˈbɪljən/) → một tỷ (1.000.000.000)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
