INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_37_18', 'en-b1-37', NULL, 'comprehensive_test', 'reading', NULL, 'First-time buyers often struggle to enter the housing market because property prices rise faster than wages.', 'Dựa vào câu trên, từ “buyer” có nghĩa phù hợp nhất là gì?', '["người mua; khách hàng","sự cầu nguyện; lời cầu nguyện","tội phạm; tệ nạn tội phạm","hành lý"]'::jsonb, 0, 'buyer: người mua; khách hàng; nhân viên thu mua. Dịch cả câu: Những người mua nhà lần đầu thường gặp khó khăn trong việc gia nhập thị trường nhà ở vì giá nhà tăng nhanh hơn mức tăng tiền lương.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_37_19', 'en-b1-37', NULL, 'comprehensive_test', 'reading', NULL, 'High tuition fees may discourage students from disadvantaged backgrounds from applying to university, even when financial assistance is available.', 'Dựa vào câu trên, từ “fee” có nghĩa phù hợp nhất là gì?', '["tiền phí dịch vụ; học phí; thù lao chuyên môn","gian lận; chơi gian","ngoài trời; lộ thiên","gia sư; người hướng dẫn riêng"]'::jsonb, 0, 'fee: tiền phí dịch vụ; học phí; thù lao chuyên môn. Dịch cả câu: Học phí cao có thể khiến học sinh từ các hoàn cảnh khó khăn e ngại nộp đơn vào đại học, ngay cả khi có sẵn hỗ trợ tài chính.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_37_20', 'en-b1-37', NULL, 'comprehensive_test', 'reading', NULL, 'Affordable credit can help small businesses invest in equipment and create jobs within local communities.', 'Dựa vào câu trên, từ “credit” có nghĩa phù hợp nhất là gì?', '["đồng mười xu (Mỹ hoặc Canada)","sự mua chịu; tín dụng; hình thức trả chậm hoặc vay tiền","hương va-ni; quả va-ni","xe máy kéo; máy cày"]'::jsonb, 1, 'credit: sự mua chịu; tín dụng; hình thức trả chậm hoặc vay tiền; sự công nhận; lời khen ngợi xứng đáng cho một thành tựu; tín chỉ học phần; đơn vị tích lũy khi hoàn thành một phần chương trình học. Dịch cả câu: Tín dụng với lãi suất hợp lý có thể giúp các doanh nghiệp nhỏ đầu tư vào trang thiết bị và tạo ra việc làm tại các cộng đồng địa phương.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_37_21', 'en-b1-37', NULL, 'comprehensive_test', 'reading', NULL, 'Consumers can often bargain with local sellers, although fixed prices are more common in large stores.', 'Dựa vào câu trên, từ “bargain” có nghĩa phù hợp nhất là gì?', '["làm cho vui; giải trí","đánh bại; chiến thắng","kẻ giết người; kẻ thủ ác","món hời; hàng giá rẻ"]'::jsonb, 3, 'bargain: món hời; hàng giá rẻ; mặc cả; thương lượng giá cả; thỏa thuận; hiệp ước. Dịch cả câu: Người tiêu dùng thường có thể mặc cả với người bán địa phương, mặc dù giá cố định phổ biến hơn ở các cửa hàng lớn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
