INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-38', 'en', 'Bài 38: Chính phủ & Pháp luật - CEFR B1', 'CEFR B1', 'B1 · Chính phủ & Pháp luật', '22 từ vựng Tiếng Anh CEFR B1 chủ đề chính phủ & pháp luật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3038, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_political', 'en-b1-38', 'political', '/pəˈlɪtɪkəl/', 'B1', 'thuộc về chính trị; chính trị', 'adj.', 'politics (n.), politician (n.), politically (adv.)', 'Trái nghĩa: apolitical', 'Political là tính từ; politics chỉ môn chính trị học/đời sống chính trị, còn politician chỉ nhà chính trị gia.', 'We often discuss political issues around the dinner table.', NULL, 'Chúng tôi thường thảo luận về các vấn đề chính trị trong các bữa ăn gia đình.', '{"wordId":"political","ukIpa":"/pəˈlɪtɪkəl/","usIpa":"/pəˈlɪtɪkəl/","cefr":"B1","topic":"government","senses":[{"pos":"adj.","en":"relating to government, public power, or political parties","vi":"thuộc về chính trị; chính trị"}],"examples":[{"en":"We often discuss political issues around the dinner table.","vi":"Chúng tôi thường thảo luận về các vấn đề chính trị trong các bữa ăn gia đình.","audioKind":"ex"},{"en":"Political stability can encourage long-term investment and help governments maintain essential public services.","vi":"Sự ổn định chính trị có thể thúc đẩy đầu tư dài hạn và giúp chính phủ duy trì các dịch vụ công thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"political party","vi":"đảng phái chính trị"},{"en":"political stability","vi":"sự ổn định chính trị"},{"en":"political debate","vi":"cuộc tranh luận chính trị"},{"en":"political system","vi":"hệ thống chính trị"}],"wordFamily":["politics (n.)","politician (n.)","politically (adv.)"],"synonyms":[],"antonyms":["apolitical"],"tipVi":"Political là tính từ; politics chỉ môn chính trị học/đời sống chính trị, còn politician chỉ nhà chính trị gia.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_court', 'en-b1-38', 'court', '/kɔːrt/', 'B1', 'tòa án; pháp đình; sân thi đấu (quần vợt, bóng rổ...); tìm kiếm (sự ủng hộ, thành công); chuốc lấy (rủi ro, thảm họa)', 'n.', 'courtroom (n.), courthouse (n.)', NULL, 'in court chỉ việc có mặt tại tòa án; on court chỉ việc thi đấu trên sân thể thao.', 'She will appear in court on Monday morning.', NULL, 'Cô ấy sẽ ra hầu tòa vào sáng thứ Hai.', '{"wordId":"court","ukIpa":"/kɔːt/","usIpa":"/kɔːrt/","cefr":"B1","topic":"government","senses":[{"pos":"n.","en":"a place or institution where legal cases are heard","vi":"tòa án; pháp đình"},{"pos":"n.","en":"an area for playing sports such as tennis or basketball","vi":"sân thi đấu (quần vợt, bóng rổ...)"},{"pos":"v.","en":"to seek something desirable or risk something harmful","vi":"tìm kiếm (sự ủng hộ, thành công); chuốc lấy (rủi ro, thảm họa)"}],"examples":[{"en":"She will appear in court on Monday morning.","vi":"Cô ấy sẽ ra hầu tòa vào sáng thứ Hai.","audioKind":"ex"},{"en":"Local councils should provide public tennis courts so that more residents can exercise regularly.","vi":"Chính quyền địa phương nên cung cấp các sân quần vợt công cộng để nhiều cư dân có thể tập thể dục thường xuyên hơn.","audioKind":"ex2"}],"collocations":[{"en":"go to court","vi":"ra hầu tòa"},{"en":"tennis court","vi":"sân quần vợt"},{"en":"court disaster","vi":"chuốc lấy thảm họa"}],"wordFamily":["courtroom (n.)","courthouse (n.)"],"synonyms":[],"antonyms":[],"tipVi":"in court chỉ việc có mặt tại tòa án; on court chỉ việc thi đấu trên sân thể thao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ban', 'en-b1-38', 'ban', '/bæn/', 'B1', 'cấm; chính thức cấm đoán; lệnh cấm', 'v.', NULL, 'Đồng nghĩa: prohibit, forbid · Trái nghĩa: allow, permit', 'Cấu trúc ban doing; ban sb from doing; dạng quá khứ là banned.', 'The library bans food near its public computers.', NULL, 'Thư viện cấm mang đồ ăn lại gần các máy tính công cộng.', '{"wordId":"ban","ukIpa":"/bæn/","usIpa":"/bæn/","cefr":"B1","topic":"government","senses":[{"pos":"v.","en":"To officially forbid an activity or the use of something","vi":"cấm; chính thức cấm đoán"},{"pos":"n.","en":"An official rule that forbids something","vi":"lệnh cấm"}],"examples":[{"en":"The library bans food near its public computers.","vi":"Thư viện cấm mang đồ ăn lại gần các máy tính công cộng.","audioKind":"ex"},{"en":"Governments should ban misleading advertisements that encourage consumers to purchase products with unproven health benefits.","vi":"Chính phủ nên cấm các quảng cáo gây hiểu lầm khuyến khích người tiêu dùng mua các sản phẩm có lợi ích sức khỏe chưa được kiểm chứng.","audioKind":"ex2"}],"collocations":[{"en":"ban smoking","vi":"cấm hút thuốc"},{"en":"a ban on something","vi":"lệnh cấm cái gì đó"},{"en":"impose a ban","vi":"ban hành lệnh cấm"},{"en":"lift a ban","vi":"dỡ bỏ lệnh cấm"}],"wordFamily":[],"synonyms":["prohibit","forbid"],"antonyms":["allow","permit"],"tipVi":"Cấu trúc ban doing; ban sb from doing; dạng quá khứ là banned.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_politics', 'en-b1-38', 'politics', '/ˈpɑːlətɪks/', 'B1', 'chính trị; hoạt động chính trị; quan điểm chính trị; lập trường chính trị', 'n.', 'political (adj.), politically (adv.), politician (n.)', NULL, 'Khi chỉ hoạt động chính trị, từ này thường đi với động từ số ít; quan điểm chính trị có thể đi với dạng số nhiều.', 'My uncle loves discussing politics over dinner with friends.', NULL, 'Chú của tôi thích bàn chuyện chính trị cùng bạn bè trong bữa tối.', '{"wordId":"politics","ukIpa":"/ˈpɒlətɪks/","usIpa":"/ˈpɑːlətɪks/","cefr":"B1","topic":"government","senses":[{"pos":"n.","en":"activities concerning government and how a country is run","vi":"chính trị; hoạt động chính trị"},{"pos":"n.","en":"a person''s beliefs about government and public affairs","vi":"quan điểm chính trị; lập trường chính trị"}],"examples":[{"en":"My uncle loves discussing politics over dinner with friends.","vi":"Chú của tôi thích bàn chuyện chính trị cùng bạn bè trong bữa tối.","audioKind":"ex"},{"en":"Greater involvement in politics can help young people influence decisions that affect their future.","vi":"Việc tham gia nhiều hơn vào đời sống chính trị có thể giúp giới trẻ tác động đến các quyết định ảnh hưởng đến tương lai của họ.","audioKind":"ex2"}],"collocations":[{"en":"local politics","vi":"chính trị địa phương"},{"en":"enter politics","vi":"dấn thân vào chính trường"},{"en":"discuss politics","vi":"thảo luận chính trị"},{"en":"party politics","vi":"chính trị đảng phái"}],"wordFamily":["political (adj.)","politically (adv.)","politician (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ hoạt động chính trị, từ này thường đi với động từ số ít; quan điểm chính trị có thể đi với dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_navy', 'en-b1-38', 'navy', '/ˈneɪvi/', 'B1', 'hải quân; màu xanh đậm; màu xanh hải quân; có màu xanh đậm; có màu xanh hải quân', 'n.', 'naval (adj.)', NULL, 'Navy chỉ lực lượng hải quân nói chung; một chiến tàu cụ thể dùng warship.', 'My uncle joined the navy after leaving school.', NULL, 'Chú tôi gia nhập hải quân sau khi tốt nghiệp.', '{"wordId":"navy","ukIpa":"/ˈneɪvi/","usIpa":"/ˈneɪvi/","cefr":"B1","topic":"government","senses":[{"pos":"n.","en":"the armed force that operates mainly at sea","vi":"hải quân"},{"pos":"n.","en":"a very dark blue colour","vi":"màu xanh đậm; màu xanh hải quân"},{"pos":"adj.","en":"having a very dark blue colour","vi":"có màu xanh đậm; có màu xanh hải quân"}],"examples":[{"en":"My uncle joined the navy after leaving school.","vi":"Chú tôi gia nhập hải quân sau khi tốt nghiệp.","audioKind":"ex"},{"en":"The navy can support coastal communities by delivering emergency supplies after severe storms damage local roads.","vi":"Lực lượng hải quân có thể hỗ trợ các cộng đồng ven biển bằng cách vận chuyển hàng cứu trợ khẩn cấp sau khi các cơn bão lớn phá hủy đường sá địa phương.","audioKind":"ex2"}],"collocations":[{"en":"join the navy","vi":"gia nhập hải quân"},{"en":"serve in the navy","vi":"phục vụ trong hải quân"},{"en":"navy blue","vi":"màu xanh hải quân"}],"wordFamily":["naval (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Navy chỉ lực lượng hải quân nói chung; một chiến tàu cụ thể dùng warship.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forbidden', 'en-b1-38', 'forbidden', '/fərˈbɪdən/', 'B1', 'bị cấm; không được phép', 'adj.', 'forbid (v.)', 'Đồng nghĩa: prohibited, banned · Trái nghĩa: permitted, allowed', 'Đây đồng thời là phân từ hai của động từ forbid; quá khứ của nó là forbade.', 'Taking photos is forbidden inside this small museum.', NULL, 'Việc chụp ảnh bị cấm bên trong bảo tàng nhỏ này.', '{"wordId":"forbidden","ukIpa":"/fəˈbɪdən/","usIpa":"/fərˈbɪdən/","cefr":"B1","topic":"government","senses":[{"pos":"adj.","en":"not allowed by a rule, law, or authority","vi":"bị cấm; không được phép"}],"examples":[{"en":"Taking photos is forbidden inside this small museum.","vi":"Việc chụp ảnh bị cấm bên trong bảo tàng nhỏ này.","audioKind":"ex"},{"en":"In many protected areas, hunting is strictly forbidden to preserve wildlife populations and maintain ecological balance.","vi":"Tại nhiều khu bảo tồn, hoạt động săn bắn bị cấm ngặt để bảo vệ quần thể động vật hoang dã và duy trì sự cân bằng sinh thái.","audioKind":"ex2"}],"collocations":[{"en":"strictly forbidden","vi":"bị cấm nghiêm ngặt"},{"en":"forbidden territory","vi":"vùng cấm"},{"en":"forbidden by law","vi":"bị pháp luật cấm"}],"wordFamily":["forbid (v.)"],"synonyms":["prohibited","banned"],"antonyms":["permitted","allowed"],"tipVi":"Đây đồng thời là phân từ hai của động từ forbid; quá khứ của nó là forbade.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_official', 'en-b1-38', 'official', '/əˈfɪʃəl/', 'B1', 'chính thức; thuộc về cơ quan nhà nước; quan chức; viên chức', 'adj.', 'officially (adv.), unofficial (adj.)', 'Đồng nghĩa: authorised · Trái nghĩa: unofficial', 'official nhấn mạnh tính được công nhận chính thức; formal nhấn mạnh hình thức hoặc bối cảnh trang trọng.', 'We checked the official website before booking our tickets.', NULL, 'Chúng tôi đã kiểm tra trang web chính thức trước khi đặt vé.', '{"wordId":"official","ukIpa":"/əˈfɪʃəl/","usIpa":"/əˈfɪʃəl/","cefr":"B1","topic":"government","senses":[{"pos":"adj.","en":"approved or issued by a government or organisation","vi":"chính thức; thuộc về cơ quan nhà nước"},{"pos":"n.","en":"someone with a position of authority in an organisation","vi":"quan chức; viên chức"}],"examples":[{"en":"We checked the official website before booking our tickets.","vi":"Chúng tôi đã kiểm tra trang web chính thức trước khi đặt vé.","audioKind":"ex"},{"en":"Official statistics indicate that investment in public transport has increased steadily over the past decade.","vi":"Các số liệu thống kê chính thức cho thấy vốn đầu tư cho giao thông công cộng đã tăng đều trong thập kỷ qua.","audioKind":"ex2"}],"collocations":[{"en":"official statement","vi":"tuyên bố chính thức"},{"en":"official statistics","vi":"thống kê chính thức"},{"en":"government official","vi":"quan chức chính phủ"},{"en":"official language","vi":"ngôn ngữ chính thức"}],"wordFamily":["officially (adv.)","unofficial (adj.)"],"synonyms":["authorised"],"antonyms":["unofficial"],"tipVi":"official nhấn mạnh tính được công nhận chính thức; formal nhấn mạnh hình thức hoặc bối cảnh trang trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_represent', 'en-b1-38', 'represent', '/ˌreprɪˈzent/', 'B1', 'đại diện; thay mặt; tượng trưng; thể hiện; chiếm; cấu thành', 'v.', 'representation (n.), representative (n.), representative (adj.)', 'Đồng nghĩa: stand for', 'represent là động từ; on behalf of là cụm giới từ mang nghĩa "đại diện".', 'My classmates chose me to represent them at the meeting.', NULL, 'Các bạn cùng lớp đã chọn tôi để đại diện cho họ tại cuộc họp.', '{"wordId":"represent","ukIpa":"/ˌreprɪˈzent/","usIpa":"/ˌreprɪˈzent/","cefr":"B1","topic":"government","senses":[{"pos":"v.","en":"To speak or act officially for someone or a group.","vi":"đại diện; thay mặt"},{"pos":"v.","en":"To stand for or show someone or something.","vi":"tượng trưng; thể hiện"},{"pos":"v.","en":"To amount to something or form part of a whole.","vi":"chiếm; cấu thành"}],"examples":[{"en":"My classmates chose me to represent them at the meeting.","vi":"Các bạn cùng lớp đã chọn tôi để đại diện cho họ tại cuộc họp.","audioKind":"ex"},{"en":"Elected councils should represent the interests of all residents, including those from disadvantaged backgrounds.","vi":"Các hội đồng dân cử nên đại diện cho lợi ích của tất cả cư dân, bao gồm cả những người có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"represent a country","vi":"đại diện cho một quốc gia"},{"en":"represent someone''s interests","vi":"đại diện cho lợi ích của ai"},{"en":"represent a significant proportion","vi":"chiếm một tỷ lệ đáng kể"}],"wordFamily":["representation (n.)","representative (n.)","representative (adj.)"],"synonyms":["stand for"],"antonyms":[],"tipVi":"represent là động từ; on behalf of là cụm giới từ mang nghĩa \"đại diện\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_politician', 'en-b1-38', 'politician', '/ˌpɑːləˈtɪʃən/', 'B1', 'nhà chính trị; chính trị gia', 'n.', 'politics (n.), political (adj.), politically (adv.)', NULL, 'Politician chỉ người tham gia chính trị, bản thân từ này không mang sắc thái tiêu cực.', 'A local politician visited our neighbourhood to discuss transport.', NULL, 'Một chính trị gia địa phương đã đến thăm khu phố của chúng tôi để bàn về vấn đề giao thông.', '{"wordId":"politician","ukIpa":"/ˌpɒləˈtɪʃən/","usIpa":"/ˌpɑːləˈtɪʃən/","cefr":"B1","topic":"government","senses":[{"pos":"n.","en":"Someone whose work involves politics, especially an elected government member.","vi":"nhà chính trị; chính trị gia"}],"examples":[{"en":"A local politician visited our neighbourhood to discuss transport.","vi":"Một chính trị gia địa phương đã đến thăm khu phố của chúng tôi để bàn về vấn đề giao thông.","audioKind":"ex"},{"en":"Politicians should consult local communities before making decisions that could affect access to public services.","vi":"Các chính trị gia nên tham khảo ý kiến của cộng đồng địa phương trước khi đưa ra các quyết định có thể ảnh hưởng đến khả năng tiếp cận dịch vụ công.","audioKind":"ex2"}],"collocations":[{"en":"a local politician","vi":"một chính trị gia địa phương"},{"en":"an elected politician","vi":"một chính trị gia đắc cử"},{"en":"a senior politician","vi":"một chính trị gia kỳ cựu"}],"wordFamily":["politics (n.)","political (adj.)","politically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Politician chỉ người tham gia chính trị, bản thân từ này không mang sắc thái tiêu cực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_illegal', 'en-b1-38', 'illegal', '/ɪˈliːɡəl/', 'B1', 'bất hợp pháp; trái pháp luật', 'adj.', 'legal (adj.), illegally (adv.), illegality (n.)', 'Đồng nghĩa: unlawful · Trái nghĩa: legal, lawful', 'Mẫu câu thông dụng: It is illegal to do sth.', 'It is illegal to park here overnight without permission.', NULL, 'Đỗ xe ở đây qua đêm mà không có phép là trái pháp luật.', '{"wordId":"illegal","ukIpa":"/ɪˈliːɡəl/","usIpa":"/ɪˈliːɡəl/","cefr":"B1","topic":"government","senses":[{"pos":"adj.","en":"Not allowed by law","vi":"bất hợp pháp; trái pháp luật"}],"examples":[{"en":"It is illegal to park here overnight without permission.","vi":"Đỗ xe ở đây qua đêm mà không có phép là trái pháp luật.","audioKind":"ex"},{"en":"Stronger international cooperation is needed to prevent illegal fishing and protect vulnerable marine ecosystems.","vi":"Cần tăng cường hợp tác quốc tế để ngăn chặn tình trạng đánh bắt trái phép và bảo vệ các hệ sinh thái biển mỏng manh.","audioKind":"ex2"}],"collocations":[{"en":"illegal activity","vi":"hoạt động phi pháp"},{"en":"illegal trade","vi":"thương mại trái phép"},{"en":"illegal fishing","vi":"đánh bắt trái phép"},{"en":"make something illegal","vi":"biến cái gì thành bất hợp pháp"}],"wordFamily":["legal (adj.)","illegally (adv.)","illegality (n.)"],"synonyms":["unlawful"],"antonyms":["legal","lawful"],"tipVi":"Mẫu câu thông dụng: It is illegal to do sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_policy', 'en-b1-38', 'policy', '/ˈpɑːləsi/', 'B1', 'chính sách; đường lối; quy tắc; bảo đơn; hợp đồng bảo hiểm', 'n.', 'policymaker (n.), policymaking (n.)', NULL, 'policy là chính sách hoặc hợp đồng bảo hiểm; còn politics chỉ chính trị.', 'Our school has a policy of serving fresh fruit daily.', NULL, 'Trường chúng tôi có quy định phục vụ trái cây tươi mỗi ngày.', '{"wordId":"policy","ukIpa":"/ˈpɒləsi/","usIpa":"/ˈpɑːləsi/","cefr":"B1","topic":"government","senses":[{"pos":"n.","en":"an agreed plan or rule guiding decisions and actions","vi":"chính sách; đường lối; quy tắc"},{"pos":"n.","en":"a contract describing the insurance cover someone has bought","vi":"bảo đơn; hợp đồng bảo hiểm"}],"examples":[{"en":"Our school has a policy of serving fresh fruit daily.","vi":"Trường chúng tôi có quy định phục vụ trái cây tươi mỗi ngày.","audioKind":"ex"},{"en":"An effective housing policy should address both rising rents and the shortage of affordable homes.","vi":"Một chính sách nhà ở hiệu quả cần giải quyết cả vấn đề giá thuê nhà tăng cao lẫn tình trạng thiếu hụt nhà ở giá rẻ.","audioKind":"ex2"}],"collocations":[{"en":"government policy","vi":"chính sách nhà nước; chính sách chính phủ"},{"en":"implement a policy","vi":"thực thi chính sách"},{"en":"insurance policy","vi":"hợp đồng bảo hiểm"},{"en":"foreign policy","vi":"chính sách đối ngoại"}],"wordFamily":["policymaker (n.)","policymaking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"policy là chính sách hoặc hợp đồng bảo hiểm; còn politics chỉ chính trị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_legal', 'en-b1-38', 'legal', '/ˈliːɡl/', 'B1', 'thuộc về pháp luật; liên quan đến pháp lý; hợp pháp; hợp pháp luật cho phép', 'adj.', 'legally (adv.), legality (n.), illegal (adj.), legalise (v.)', 'Đồng nghĩa: lawful · Trái nghĩa: illegal', 'legal có thể mang nghĩa "liên quan đến luật pháp", không nhất thiết phải là "hợp pháp".', 'We sought legal advice before signing the rental agreement.', NULL, 'Chúng tôi đã tìm kiếm tư vấn pháp lý trước khi ký hợp đồng thuê nhà.', '{"wordId":"legal","ukIpa":"/ˈliːɡl/","usIpa":"/ˈliːɡl/","cefr":"B1","topic":"government","senses":[{"pos":"adj.","en":"Relating to laws or the system that applies them","vi":"thuộc về pháp luật; liên quan đến pháp lý"},{"pos":"adj.","en":"Allowed by the law","vi":"hợp pháp; hợp pháp luật cho phép"}],"examples":[{"en":"We sought legal advice before signing the rental agreement.","vi":"Chúng tôi đã tìm kiếm tư vấn pháp lý trước khi ký hợp đồng thuê nhà.","audioKind":"ex"},{"en":"Access to affordable legal services is essential for ensuring that disadvantaged citizens can defend their rights.","vi":"Khả năng tiếp cận các dịch vụ pháp lý có chi phí hợp lý là điều thiết yếu để đảm bảo công dân yếu thế có thể bảo vệ quyền lợi của mình.","audioKind":"ex2"}],"collocations":[{"en":"legal advice","vi":"tư vấn pháp luật"},{"en":"legal action","vi":"hành động pháp lý"},{"en":"legal rights","vi":"quyền hợp pháp"},{"en":"perfectly legal","vi":"hoàn toàn hợp pháp"}],"wordFamily":["legally (adv.)","legality (n.)","illegal (adj.)","legalise (v.)"],"synonyms":["lawful"],"antonyms":["illegal"],"tipVi":"legal có thể mang nghĩa \"liên quan đến luật pháp\", không nhất thiết phải là \"hợp pháp\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_national', 'en-b1-38', 'national', '/ˈnæʃənəl/', 'B1', 'thuộc về quốc gia; toàn quốc; công dân của một quốc gia cụ thể', 'adj.', 'nation (n.), nationality (n.), nationally (adv.), international (adj.)', NULL, 'national nhấn mạnh phạm vi toàn quốc gia; trong khi international mang ý nghĩa quốc tế.', 'My sister hopes to join the national swimming team.', NULL, 'Em gái tôi hy vọng sẽ được gia nhập đội tuyển bơi lội quốc gia.', '{"wordId":"national","ukIpa":"/ˈnæʃənəl/","usIpa":"/ˈnæʃənəl/","cefr":"B1","topic":"government","senses":[{"pos":"adj.","en":"relating to a whole country or its people","vi":"thuộc về quốc gia; toàn quốc"},{"pos":"n.","en":"a person who is a citizen of a particular country","vi":"công dân của một quốc gia cụ thể"}],"examples":[{"en":"My sister hopes to join the national swimming team.","vi":"Em gái tôi hy vọng sẽ được gia nhập đội tuyển bơi lội quốc gia.","audioKind":"ex"},{"en":"National policies can help reduce regional differences in access to healthcare and education.","vi":"Các chính sách quốc gia có thể giúp thu hẹp khoảng cách vùng miền trong việc tiếp cận y tế và giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"national identity","vi":"ý thức dân tộc"},{"en":"national park","vi":"công viên quốc gia"},{"en":"national government","vi":"chính phủ trung ương"},{"en":"foreign national","vi":"công dân nước ngoài"}],"wordFamily":["nation (n.)","nationality (n.)","nationally (adv.)","international (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"national nhấn mạnh phạm vi toàn quốc gia; trong khi international mang ý nghĩa quốc tế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_licence', 'en-b1-38', 'licence', '/ˈlaɪsəns/', 'B1', 'giấy phép; bằng lái; chứng chỉ; sự tự do phóng tác; quyền tự do', 'n.', 'license (v.), licensed (adj.), licensee (n.)', 'Đồng nghĩa: permit', 'Tiếng Anh-Anh dùng licence cho danh từ và license cho động từ; tiếng Anh-Mỹ dùng license cho cả hai.', 'I keep my driving licence in my wallet.', NULL, 'Tôi để bằng lái xe trong ví của mình.', '{"wordId":"licence","ukIpa":"/ˈlaɪsəns/","usIpa":"/ˈlaɪsəns/","cefr":"B1","topic":"government","senses":[{"pos":"n.","en":"an official document allowing someone to do something","vi":"giấy phép; bằng lái; chứng chỉ"},{"pos":"n.","en":"freedom to depart from usual rules or factual accuracy","vi":"sự tự do phóng tác; quyền tự do"}],"examples":[{"en":"I keep my driving licence in my wallet.","vi":"Tôi để bằng lái xe trong ví của mình.","audioKind":"ex"},{"en":"Requiring a licence to operate tourist boats can help authorities maintain safety standards on busy waterways.","vi":"Yêu cầu có giấy phép để điều hành thuyền du lịch có thể giúp các cơ quan chức năng duy trì các tiêu chuẩn an toàn trên các tuyến đường thủy đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"driving licence","vi":"giấy phép lái xe"},{"en":"apply for a licence","vi":"xin cấp phép"},{"en":"renew a licence","vi":"gia hạn giấy phép"},{"en":"poetic licence","vi":"sự tự do nghệ thuật"}],"wordFamily":["license (v.)","licensed (adj.)","licensee (n.)"],"synonyms":["permit"],"antonyms":[],"tipVi":"Tiếng Anh-Anh dùng licence cho danh từ và license cho động từ; tiếng Anh-Mỹ dùng license cho cả hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_border', 'en-b1-38', 'border', '/ˈbɔːrdər/', 'B1', 'đường biên giới; biên giới quốc gia; dải viền; mép ngoài; tiếp giáp; giáp ranh', 'n.', 'bordering (adj.), borderless (adj.)', 'Đồng nghĩa: boundary', 'border đóng vai trò động từ có thể nối trực tiếp với địa điểm; ngoài ra border on còn có thể diễn tả ý nghĩa gần như.', 'We crossed the border by train early this morning.', NULL, 'Chúng tôi đã vượt qua biên giới bằng tàu hỏa vào sáng sớm nay.', '{"wordId":"border","ukIpa":"/ˈbɔːdə/","usIpa":"/ˈbɔːrdər/","cefr":"B1","topic":"government","senses":[{"pos":"n.","en":"the dividing line between countries or regions","vi":"đường biên giới; biên giới quốc gia"},{"pos":"n.","en":"a strip around the outside edge of something","vi":"dải viền; mép ngoài"},{"pos":"v.","en":"to share a boundary with a place","vi":"tiếp giáp; giáp ranh"}],"examples":[{"en":"We crossed the border by train early this morning.","vi":"Chúng tôi đã vượt qua biên giới bằng tàu hỏa vào sáng sớm nay.","audioKind":"ex"},{"en":"Countries that share a border often need to cooperate closely on trade and environmental protection.","vi":"Các quốc gia có chung đường biên giới thường cần hợp tác chặt chẽ về thương mại và bảo vệ môi trường.","audioKind":"ex2"}],"collocations":[{"en":"cross the border","vi":"vượt biên giới"},{"en":"border controls","vi":"kiểm soát biên giới"},{"en":"share a border","vi":"chia sẻ đường biên giới"},{"en":"a decorative border","vi":"đường viền trang trí"}],"wordFamily":["bordering (adj.)","borderless (adj.)"],"synonyms":["boundary"],"antonyms":[],"tipVi":"border đóng vai trò động từ có thể nối trực tiếp với địa điểm; ngoài ra border on còn có thể diễn tả ý nghĩa gần như.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_permit', 'en-b1-38', 'permit', '/pɚˈmɪt/', 'B1', 'cho phép; chuẩn y; giấy phép; thẻ thông hành; làm cho có thể; tạo điều kiện cho', 'v.', 'permission (n.), permitted (v.), permissible (adj.)', 'Đồng nghĩa: allow, authorize · Trái nghĩa: forbid, prohibit', 'Trọng tâm động từ ở âm tiết sau, danh từ ở âm tiết đầu; permit sb to do.', 'The museum permits visitors to take photos without flash.', NULL, 'Bảo tàng cho phép khách tham quan chụp ảnh không dùng đèn flash.', '{"wordId":"permit","ukIpa":"/pəˈmɪt/","usIpa":"/pɚˈmɪt/","cefr":"B1","topic":"government","senses":[{"pos":"v.","en":"to officially allow someone to do something","vi":"cho phép; chuẩn y"},{"pos":"n.","en":"an official document allowing a particular activity","vi":"giấy phép; thẻ thông hành"},{"pos":"v.","en":"to make an action or situation possible","vi":"làm cho có thể; tạo điều kiện cho"}],"examples":[{"en":"The museum permits visitors to take photos without flash.","vi":"Bảo tàng cho phép khách tham quan chụp ảnh không dùng đèn flash.","audioKind":"ex"},{"en":"Local authorities should permit new housing developments only when adequate transport and healthcare services are available.","vi":"Chính quyền địa phương chỉ nên phê duyệt các dự án phát triển nhà ở mới khi đã có đầy đủ dịch vụ giao thông và y tế.","audioKind":"ex2"}],"collocations":[{"en":"permit someone to do something","vi":"cho phép ai làm gì"},{"en":"work permit","vi":"giấy phép làm việc"},{"en":"building permit","vi":"giấy phép xây dựng"},{"en":"weather permitting","vi":"nếu thời tiết cho phép"}],"wordFamily":["permission (n.)","permitted (v.)","permissible (adj.)"],"synonyms":["allow","authorize"],"antonyms":["forbid","prohibit"],"tipVi":"Trọng tâm động từ ở âm tiết sau, danh từ ở âm tiết đầu; permit sb to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_approve', 'en-b1-38', 'approve', '/əˈpruːv/', 'B1', 'phê duyệt; chấp thuận; tán thành; đồng tình', 'v.', 'approval (n.), disapprove (v.), approving (adj.)', 'Đồng nghĩa: authorize, endorse · Trái nghĩa: reject, disapprove', 'Phê duyệt việc gì dùng approve; tán thành việc gì dùng approve of.', 'My manager approved my request for a day off.', NULL, 'Quản lý của tôi đã phê duyệt đơn xin nghỉ phép một ngày của tôi.', '{"wordId":"approve","ukIpa":"/əˈpruːv/","usIpa":"/əˈpruːv/","cefr":"B1","topic":"government","senses":[{"pos":"v.","en":"To officially accept or allow something.","vi":"phê duyệt; chấp thuận"},{"pos":"v.","en":"To think that someone or something is good or acceptable.","vi":"tán thành; đồng tình"}],"examples":[{"en":"My manager approved my request for a day off.","vi":"Quản lý của tôi đã phê duyệt đơn xin nghỉ phép một ngày của tôi.","audioKind":"ex"},{"en":"Local authorities should approve housing developments only when adequate transport and essential services are available.","vi":"Chính quyền địa phương chỉ nên phê duyệt các dự án phát triển nhà ở khi có đầy đủ phương tiện giao thông và các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"approve a proposal","vi":"phê duyệt một đề xuất"},{"en":"approve of something","vi":"tán thành điều gì"},{"en":"approve an application","vi":"phê duyệt một đơn xin"}],"wordFamily":["approval (n.)","disapprove (v.)","approving (adj.)"],"synonyms":["authorize","endorse"],"antonyms":["reject","disapprove"],"tipVi":"Phê duyệt việc gì dùng approve; tán thành việc gì dùng approve of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_limit', 'en-b1-38', 'limit', '/ˈlɪmɪt/', 'B1', 'giới hạn; hạn mức; hạn chế', 'n.', 'limited (adj.), limitation (n.), unlimited (adj.), limitless (adj.)', 'Đồng nghĩa: restriction, restrict', 'limit A to B có nghĩa là hạn chế A trong phạm vi B.', 'There is a limit to what this bag can hold.', NULL, 'Chiếc túi này có sức chứa giới hạn của nó.', '{"wordId":"limit","ukIpa":"/ˈlɪmɪt/","usIpa":"/ˈlɪmɪt/","cefr":"B1","topic":"government","senses":[{"pos":"n.","en":"the greatest amount or level that is allowed or possible","vi":"giới hạn; hạn mức"},{"pos":"v.","en":"to control how much something can increase or happen","vi":"hạn chế; giới hạn"}],"examples":[{"en":"There is a limit to what this bag can hold.","vi":"Chiếc túi này có sức chứa giới hạn của nó.","audioKind":"ex"},{"en":"Governments should limit industrial emissions while providing financial support for businesses adopting cleaner production methods.","vi":"Chính phủ nên hạn chế lượng khí thải công nghiệp đồng thời hỗ trợ tài chính cho các doanh nghiệp áp dụng phương pháp sản xuất sạch hơn.","audioKind":"ex2"}],"collocations":[{"en":"speed limit","vi":"giới hạn tốc độ"},{"en":"time limit","vi":"giới hạn thời gian"},{"en":"set a limit","vi":"đặt ra giới hạn"},{"en":"limit something to","vi":"hạn chế cái gì ở mức"}],"wordFamily":["limited (adj.)","limitation (n.)","unlimited (adj.)","limitless (adj.)"],"synonyms":["restriction","restrict"],"antonyms":[],"tipVi":"limit A to B có nghĩa là hạn chế A trong phạm vi B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mayor', 'en-b1-38', 'mayor', '/ˈmeɪər/', 'B1', 'thị trưởng; chủ tịch ủy ban nhân dân thị trấn', 'n.', 'mayoral (adj.), mayoralty (n.)', NULL, 'mayor là thị trưởng, cần phân biệt với từ major (chính, chủ yếu).', 'The mayor opened our new swimming pool yesterday.', NULL, 'Thị trưởng đã khánh thành hồ bơi mới của chúng ta vào ngày hôm qua.', '{"wordId":"mayor","ukIpa":"/meə/","usIpa":"/ˈmeɪər/","cefr":"B1","topic":"government","senses":[{"pos":"n.","en":"The official who leads or represents a city or town","vi":"thị trưởng; chủ tịch ủy ban nhân dân thị trấn"}],"examples":[{"en":"The mayor opened our new swimming pool yesterday.","vi":"Thị trưởng đã khánh thành hồ bơi mới của chúng ta vào ngày hôm qua.","audioKind":"ex"},{"en":"The newly elected mayor has promised to improve public transport and create more affordable housing for residents.","vi":"Vị thị trưởng mới đắc cử đã cam kết cải thiện giao thông công cộng và tạo thêm nhà ở giá rẻ cho người dân.","audioKind":"ex2"}],"collocations":[{"en":"elect a mayor","vi":"bầu thị trưởng"},{"en":"the mayor of a city","vi":"thị trưởng của một thành phố"},{"en":"deputy mayor","vi":"phó thị trưởng"},{"en":"run for mayor","vi":"ra tranh cử thị trưởng"}],"wordFamily":["mayoral (adj.)","mayoralty (n.)"],"synonyms":[],"antonyms":[],"tipVi":"mayor là thị trưởng, cần phân biệt với từ major (chính, chủ yếu).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_election', 'en-b1-38', 'election', '/ɪˈlekʃən/', 'B1', 'cuộc bầu cử; sự bầu cử; sự đắc cử', 'n.', 'elect (v.), electoral (adj.), electorate (n.), elector (n.)', NULL, 'elect nhấn mạnh việc bầu chọn qua lá phiếu; select mang nghĩa tuyển chọn chung chung.', 'Our club is holding an election for its next chair.', NULL, 'Câu lạc bộ của chúng tôi đang tổ chức một cuộc bầu cử để chọn ra chủ tịch tiếp theo.', '{"wordId":"election","ukIpa":"/ɪˈlekʃən/","usIpa":"/ɪˈlekʃən/","cefr":"B1","topic":"government","senses":[{"pos":"n.","en":"a process in which people vote to choose representatives","vi":"cuộc bầu cử; sự bầu cử"},{"pos":"n.","en":"the act of being chosen for a position by voting","vi":"sự đắc cử"}],"examples":[{"en":"Our club is holding an election for its next chair.","vi":"Câu lạc bộ của chúng tôi đang tổ chức một cuộc bầu cử để chọn ra chủ tịch tiếp theo.","audioKind":"ex"},{"en":"A fair election requires transparent procedures and equal opportunities for candidates to present their policies.","vi":"Một cuộc bầu cử công bằng đòi hỏi các thủ tục minh bạch và cơ hội bình đẳng cho các ứng viên trình bày chính sách của họ.","audioKind":"ex2"}],"collocations":[{"en":"hold an election","vi":"tổ chức bầu cử"},{"en":"general election","vi":"tổng tuyển cử"},{"en":"election campaign","vi":"chiến dịch tranh cử"},{"en":"win an election","vi":"thắng cử"}],"wordFamily":["elect (v.)","electoral (adj.)","electorate (n.)","elector (n.)"],"synonyms":[],"antonyms":[],"tipVi":"elect nhấn mạnh việc bầu chọn qua lá phiếu; select mang nghĩa tuyển chọn chung chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vote', 'en-b1-38', 'vote', '/voʊt/', 'B1', 'bỏ phiếu; biểu quyết; lá phiếu; sự bỏ phiếu; quyền bỏ phiếu', 'v.', 'voter (n.), voting (n.)', NULL, 'vote for có nghĩa là bỏ phiếu ủng hộ; vote against có nghĩa là bỏ phiếu phản đối.', 'We voted to hold the picnic in the park.', NULL, 'Chúng tôi đã bỏ phiếu quyết định tổ chức buổi dã ngoại trong công viên.', '{"wordId":"vote","ukIpa":"/vəʊt/","usIpa":"/voʊt/","cefr":"B1","topic":"government","senses":[{"pos":"v.","en":"To formally express a choice in an election or decision.","vi":"bỏ phiếu; biểu quyết"},{"pos":"n.","en":"A formal expression of choice, or the process of choosing.","vi":"lá phiếu; sự bỏ phiếu; quyền bỏ phiếu"}],"examples":[{"en":"We voted to hold the picnic in the park.","vi":"Chúng tôi đã bỏ phiếu quyết định tổ chức buổi dã ngoại trong công viên.","audioKind":"ex"},{"en":"Allowing residents to vote on local projects may increase public participation in community development.","vi":"Cho phép cư dân bỏ phiếu về các dự án địa phương có thể tăng cường sự tham gia của công chúng vào việc phát triển cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"vote for","vi":"bỏ phiếu ủng hộ"},{"en":"vote against","vi":"bỏ phiếu chống"},{"en":"cast a vote","vi":"bỏ một phiếu"},{"en":"the right to vote","vi":"quyền bầu cử; quyền bỏ phiếu"}],"wordFamily":["voter (n.)","voting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"vote for có nghĩa là bỏ phiếu ủng hộ; vote against có nghĩa là bỏ phiếu phản đối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_council', 'en-b1-38', 'council', '/ˈkaʊnsəl/', 'B1', 'hội đồng; ủy ban', 'n.', 'councillor (n.)', NULL, 'council chỉ hội đồng hoặc ủy ban; counsel chỉ lời khuyên hoặc sự răn dạy.', 'The local council repaired the playground near our house.', NULL, 'Hội đồng địa phương đã sửa chữa khu vui chơi gần nhà chúng tôi.', '{"wordId":"council","ukIpa":"/ˈkaʊnsəl/","usIpa":"/ˈkaʊnsəl/","cefr":"B1","topic":"government","senses":[{"pos":"n.","en":"A group chosen to govern an area or manage affairs.","vi":"hội đồng; ủy ban"}],"examples":[{"en":"The local council repaired the playground near our house.","vi":"Hội đồng địa phương đã sửa chữa khu vui chơi gần nhà chúng tôi.","audioKind":"ex"},{"en":"The city council should consult residents before approving developments that could affect public green spaces.","vi":"Hội đồng thành phố nên tham khảo ý kiến cư dân trước khi phê duyệt các dự án phát triển có thể ảnh hưởng đến không gian xanh công cộng.","audioKind":"ex2"}],"collocations":[{"en":"local council","vi":"hội đồng địa phương"},{"en":"city council","vi":"hội đồng thành phố"},{"en":"council member","vi":"thành viên hội đồng"},{"en":"student council","vi":"hội đồng học sinh"}],"wordFamily":["councillor (n.)"],"synonyms":[],"antonyms":[],"tipVi":"council chỉ hội đồng hoặc ủy ban; counsel chỉ lời khuyên hoặc sự răn dạy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_38_1', 'en-b1-38', 'Cách dùng “border” (n.) — đường biên giới; biên giới quốc gia', 'cross the border  ·  border controls  ·  share a border', 'border đóng vai trò động từ có thể nối trực tiếp với địa điểm; ngoài ra border on còn có thể diễn tả ý nghĩa gần như.', 'Họ từ (Word Family): bordering (adj.), borderless (adj.) | Đồng nghĩa: boundary', '[{"hanzi":"We crossed the border by train early this morning.","pinyin":"","meaning":"Chúng tôi đã vượt qua biên giới bằng tàu hỏa vào sáng sớm nay."},{"hanzi":"Countries that share a border often need to cooperate closely on trade and environmental protection.","pinyin":"","meaning":"Các quốc gia có chung đường biên giới thường cần hợp tác chặt chẽ về thương mại và bảo vệ môi trường."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_38_2', 'en-b1-38', 'Cách dùng “politics” (n.) — chính trị; hoạt động chính trị', 'local politics  ·  enter politics  ·  discuss politics', 'Khi chỉ hoạt động chính trị, từ này thường đi với động từ số ít; quan điểm chính trị có thể đi với dạng số nhiều.', 'Họ từ (Word Family): political (adj.), politically (adv.), politician (n.)', '[{"hanzi":"My uncle loves discussing politics over dinner with friends.","pinyin":"","meaning":"Chú của tôi thích bàn chuyện chính trị cùng bạn bè trong bữa tối."},{"hanzi":"Greater involvement in politics can help young people influence decisions that affect their future.","pinyin":"","meaning":"Việc tham gia nhiều hơn vào đời sống chính trị có thể giúp giới trẻ tác động đến các quyết định ảnh hưởng đến tương lai của họ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_38_3', 'en-b1-38', 'Cách dùng “political” (adj.) — thuộc về chính trị; chính trị', 'political party  ·  political stability  ·  political debate', 'Political là tính từ; politics chỉ môn chính trị học/đời sống chính trị, còn politician chỉ nhà chính trị gia.', 'Họ từ (Word Family): politics (n.), politician (n.), politically (adv.) | Trái nghĩa: apolitical', '[{"hanzi":"We often discuss political issues around the dinner table.","pinyin":"","meaning":"Chúng tôi thường thảo luận về các vấn đề chính trị trong các bữa ăn gia đình."},{"hanzi":"Political stability can encourage long-term investment and help governments maintain essential public services.","pinyin":"","meaning":"Sự ổn định chính trị có thể thúc đẩy đầu tư dài hạn và giúp chính phủ duy trì các dịch vụ công thiết yếu."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_38_4', 'en-b1-38', 'Cách dùng “official” (adj.) — chính thức; thuộc về cơ quan nhà nước', 'official statement  ·  official statistics  ·  government official', 'official nhấn mạnh tính được công nhận chính thức; formal nhấn mạnh hình thức hoặc bối cảnh trang trọng.', 'Họ từ (Word Family): officially (adv.), unofficial (adj.) | Đồng nghĩa: authorised · Trái nghĩa: unofficial', '[{"hanzi":"We checked the official website before booking our tickets.","pinyin":"","meaning":"Chúng tôi đã kiểm tra trang web chính thức trước khi đặt vé."},{"hanzi":"Official statistics indicate that investment in public transport has increased steadily over the past decade.","pinyin":"","meaning":"Các số liệu thống kê chính thức cho thấy vốn đầu tư cho giao thông công cộng đã tăng đều trong thập kỷ qua."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
