INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_38_1_5', 'ten_b1_38_1', 'navy', 'My uncle joined the navy after leaving school.', 'My uncle joined the navy after leaving school.', '/ˈneɪvi/', 'Chú tôi gia nhập hải quân sau khi tốt nghiệp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_38_1_6', 'ten_b1_38_1', 'forbidden', 'Taking photos is forbidden inside this small museum.', 'Taking photos is forbidden inside this small museum.', '/fərˈbɪdən/', 'Việc chụp ảnh bị cấm bên trong bảo tàng nhỏ này.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_38_1_7', 'ten_b1_38_1', 'official', 'We checked the official website before booking our tickets.', 'We checked the official website before booking our tickets.', '/əˈfɪʃəl/', 'Chúng tôi đã kiểm tra trang web chính thức trước khi đặt vé.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_38_1_8', 'ten_b1_38_1', 'represent', 'My classmates chose me to represent them at the meeting.', 'My classmates chose me to represent them at the meeting.', '/ˌreprɪˈzent/', 'Các bạn cùng lớp đã chọn tôi để đại diện cho họ tại cuộc họp.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_38_1_1', 'en-b1-38', 'ten_b1_38_1', 'listening', 'listening', 'We often discuss political issues around the dinner table.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chú của tôi thích bàn chuyện chính trị cùng bạn bè trong bữa tối.","Chúng tôi đã bỏ phiếu quyết định tổ chức buổi dã ngoại trong công viên.","Chú tôi gia nhập hải quân sau khi tốt nghiệp.","Chúng tôi thường thảo luận về các vấn đề chính trị trong các bữa ăn gia đình."]'::jsonb, 3, 'We often discuss political issues around the dinner table. → Chúng tôi thường thảo luận về các vấn đề chính trị trong các bữa ăn gia đình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_38_1_2', 'en-b1-38', 'ten_b1_38_1', 'listening', 'listening', 'She will appear in court on Monday morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Trường chúng tôi có quy định phục vụ trái cây tươi mỗi ngày.","Chú tôi gia nhập hải quân sau khi tốt nghiệp.","Cô ấy sẽ ra hầu tòa vào sáng thứ Hai.","Quản lý của tôi đã phê duyệt đơn xin nghỉ phép một ngày của tôi."]'::jsonb, 2, 'She will appear in court on Monday morning. → Cô ấy sẽ ra hầu tòa vào sáng thứ Hai.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_38_1_3', 'en-b1-38', 'ten_b1_38_1', 'listening', 'listening', 'The library bans food near its public computers.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thị trưởng đã khánh thành hồ bơi mới của chúng ta vào ngày hôm qua.","Chúng tôi thường thảo luận về các vấn đề chính trị trong các bữa ăn gia đình.","Đỗ xe ở đây qua đêm mà không có phép là trái pháp luật.","Thư viện cấm mang đồ ăn lại gần các máy tính công cộng."]'::jsonb, 3, 'The library bans food near its public computers. → Thư viện cấm mang đồ ăn lại gần các máy tính công cộng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_38_2', 'en-b1-38', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_38_2_1', 'ten_b1_38_2', 'political', 'Political stability can encourage long-term investment and help governments maintain essential public services.', 'Political stability can encourage long-term investment and help governments maintain essential public services.', '/pəˈlɪtɪkəl/', 'Sự ổn định chính trị có thể thúc đẩy đầu tư dài hạn và giúp chính phủ duy trì các dịch vụ công thiết yếu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_38_2_2', 'ten_b1_38_2', 'court', 'Local councils should provide public tennis courts so that more residents can exercise regularly.', 'Local councils should provide public tennis courts so that more residents can exercise regularly.', '/kɔːrt/', 'Chính quyền địa phương nên cung cấp các sân quần vợt công cộng để nhiều cư dân có thể tập thể dục thường xuyên hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_38_2_3', 'ten_b1_38_2', 'ban', 'Governments should ban misleading advertisements that encourage consumers to purchase products with unproven health benefits.', 'Governments should ban misleading advertisements that encourage consumers to purchase products with unproven health benefits.', '/bæn/', 'Chính phủ nên cấm các quảng cáo gây hiểu lầm khuyến khích người tiêu dùng mua các sản phẩm có lợi ích sức khỏe chưa được kiểm chứng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_38_2_4', 'ten_b1_38_2', 'politics', 'Greater involvement in politics can help young people influence decisions that affect their future.', 'Greater involvement in politics can help young people influence decisions that affect their future.', '/ˈpɑːlətɪks/', 'Việc tham gia nhiều hơn vào đời sống chính trị có thể giúp giới trẻ tác động đến các quyết định ảnh hưởng đến tương lai của họ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_38_2_5', 'ten_b1_38_2', 'navy', 'The navy can support coastal communities by delivering emergency supplies after severe storms damage local roads.', 'The navy can support coastal communities by delivering emergency supplies after severe storms damage local roads.', '/ˈneɪvi/', 'Lực lượng hải quân có thể hỗ trợ các cộng đồng ven biển bằng cách vận chuyển hàng cứu trợ khẩn cấp sau khi các cơn bão lớn phá hủy đường sá địa phương.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_38_2_6', 'ten_b1_38_2', 'forbidden', 'In many protected areas, hunting is strictly forbidden to preserve wildlife populations and maintain ecological balance.', 'In many protected areas, hunting is strictly forbidden to preserve wildlife populations and maintain ecological balance.', '/fərˈbɪdən/', 'Tại nhiều khu bảo tồn, hoạt động săn bắn bị cấm ngặt để bảo vệ quần thể động vật hoang dã và duy trì sự cân bằng sinh thái.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_38_2_1', 'en-b1-38', 'ten_b1_38_2', 'listening', 'listening', 'Political stability can encourage long-term investment and help governments maintain essential public services.', NULL, 'Trong câu vừa nghe, từ “political” mang nghĩa nào sau đây?', '["cuộc đua tốc độ; môn đua","hỗn hợp; gồm nhiều loại khác nhau","thuộc về chính trị; chính trị","vì vậy; do đó; cho nên"]'::jsonb, 2, '“political” (/pəˈlɪtɪkəl/): thuộc về chính trị; chính trị. Câu đầy đủ: Political stability can encourage long-term investment and help governments maintain essential public services.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_38_2_2', 'en-b1-38', 'ten_b1_38_2', 'listening', 'listening', 'Local councils should provide public tennis courts so that more residents can exercise regularly.', NULL, 'Trong câu vừa nghe, từ “court” mang nghĩa nào sau đây?', '["bột; bụi dạng mịn","lông thú; bộ lông","tòa án; pháp đình","có hại cho sức khỏe; không lành mạnh"]'::jsonb, 2, '“court” (/kɔːrt/): tòa án; pháp đình. Câu đầy đủ: Local councils should provide public tennis courts so that more residents can exercise regularly.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
