INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_38_2', 'en-b1-38', NULL, 'comprehensive_test', 'listening', 'She will appear in court on Monday morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy sẽ ra hầu tòa vào sáng thứ Hai.","Chúng tôi đã kiểm tra trang web chính thức trước khi đặt vé.","Quản lý của tôi đã phê duyệt đơn xin nghỉ phép một ngày của tôi.","Chú của tôi thích bàn chuyện chính trị cùng bạn bè trong bữa tối."]'::jsonb, 0, 'She will appear in court on Monday morning. → Cô ấy sẽ ra hầu tòa vào sáng thứ Hai.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_38_3', 'en-b1-38', NULL, 'comprehensive_test', 'listening', 'ban', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cấm; chính thức cấm đoán","chức năng; trách nhiệm","thuộc y tế; thuộc y học; khám chữa bệnh","khăng khăng đòi; kiên quyết"]'::jsonb, 0, 'ban (/bæn/) → cấm; chính thức cấm đoán; lệnh cấm', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_38_4', 'en-b1-38', NULL, 'comprehensive_test', 'listening', 'My uncle loves discussing politics over dinner with friends.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thư viện cấm mang đồ ăn lại gần các máy tính công cộng.","Chú của tôi thích bàn chuyện chính trị cùng bạn bè trong bữa tối.","Chúng tôi đã bỏ phiếu quyết định tổ chức buổi dã ngoại trong công viên.","Chúng tôi thường thảo luận về các vấn đề chính trị trong các bữa ăn gia đình."]'::jsonb, 1, 'My uncle loves discussing politics over dinner with friends. → Chú của tôi thích bàn chuyện chính trị cùng bạn bè trong bữa tối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_38_5', 'en-b1-38', NULL, 'comprehensive_test', 'listening', 'navy', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xảy ra; diễn ra","đạt được; thu được; gia tăng","khách hàng; thân chủ","hải quân"]'::jsonb, 3, 'navy (/ˈneɪvi/) → hải quân; màu xanh đậm; màu xanh hải quân; có màu xanh đậm; có màu xanh hải quân', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_38_6', 'en-b1-38', NULL, 'comprehensive_test', 'listening', 'Taking photos is forbidden inside this small museum.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc chụp ảnh bị cấm bên trong bảo tàng nhỏ này.","Chú của tôi thích bàn chuyện chính trị cùng bạn bè trong bữa tối.","Chúng tôi đã vượt qua biên giới bằng tàu hỏa vào sáng sớm nay.","Chúng tôi đã tìm kiếm tư vấn pháp lý trước khi ký hợp đồng thuê nhà."]'::jsonb, 0, 'Taking photos is forbidden inside this small museum. → Việc chụp ảnh bị cấm bên trong bảo tàng nhỏ này.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_38_7', 'en-b1-38', NULL, 'comprehensive_test', 'listening', 'official', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chính thức; thuộc về cơ quan nhà nước","kẻ giết người; kẻ thủ ác","tôn giáo; tín ngưỡng","chỗ rẽ; ngã rẽ; ngã ba, ngã tư"]'::jsonb, 0, 'official (/əˈfɪʃəl/) → chính thức; thuộc về cơ quan nhà nước; quan chức; viên chức', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_38_8', 'en-b1-38', NULL, 'comprehensive_test', 'listening', 'My classmates chose me to represent them at the meeting.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy sẽ ra hầu tòa vào sáng thứ Hai.","Chúng tôi thường thảo luận về các vấn đề chính trị trong các bữa ăn gia đình.","Việc chụp ảnh bị cấm bên trong bảo tàng nhỏ này.","Các bạn cùng lớp đã chọn tôi để đại diện cho họ tại cuộc họp."]'::jsonb, 3, 'My classmates chose me to represent them at the meeting. → Các bạn cùng lớp đã chọn tôi để đại diện cho họ tại cuộc họp.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
