INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_38_18', 'en-b1-38', NULL, 'comprehensive_test', 'reading', NULL, 'Political stability can encourage long-term investment and help governments maintain essential public services.', 'Dựa vào câu trên, từ “political” có nghĩa phù hợp nhất là gì?', '["sự tương đồng; điểm giống nhau","có xu hướng; thường","cơ bản; vỡ lòng","thuộc về chính trị; chính trị"]'::jsonb, 3, 'political: thuộc về chính trị; chính trị. Dịch cả câu: Sự ổn định chính trị có thể thúc đẩy đầu tư dài hạn và giúp chính phủ duy trì các dịch vụ công thiết yếu.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_38_19', 'en-b1-38', NULL, 'comprehensive_test', 'reading', NULL, 'Local councils should provide public tennis courts so that more residents can exercise regularly.', 'Dựa vào câu trên, từ “court” có nghĩa phù hợp nhất là gì?', '["quý ông; người lịch sự","xe cứu thương; xe cấp cứu","tòa án; pháp đình","sự hiểu biết; sự thông cảm"]'::jsonb, 2, 'court: tòa án; pháp đình; sân thi đấu (quần vợt, bóng rổ...); tìm kiếm (sự ủng hộ, thành công); chuốc lấy (rủi ro, thảm họa). Dịch cả câu: Chính quyền địa phương nên cung cấp các sân quần vợt công cộng để nhiều cư dân có thể tập thể dục thường xuyên hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_38_20', 'en-b1-38', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should ban misleading advertisements that encourage consumers to purchase products with unproven health benefits.', 'Dựa vào câu trên, từ “ban” có nghĩa phù hợp nhất là gì?', '["giao tiếp; liên lạc","toàn cầu; mang tính thế giới","cấm; chính thức cấm đoán","làm hỏng; tàn phá"]'::jsonb, 2, 'ban: cấm; chính thức cấm đoán; lệnh cấm. Dịch cả câu: Chính phủ nên cấm các quảng cáo gây hiểu lầm khuyến khích người tiêu dùng mua các sản phẩm có lợi ích sức khỏe chưa được kiểm chứng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_38_21', 'en-b1-38', NULL, 'comprehensive_test', 'reading', NULL, 'Greater involvement in politics can help young people influence decisions that affect their future.', 'Dựa vào câu trên, từ “politics” có nghĩa phù hợp nhất là gì?', '["chính trị; hoạt động chính trị","mang thai; có bầu","trực tiếp; đối mặt","bóng râm; bóng mát"]'::jsonb, 0, 'politics: chính trị; hoạt động chính trị; quan điểm chính trị; lập trường chính trị. Dịch cả câu: Việc tham gia nhiều hơn vào đời sống chính trị có thể giúp giới trẻ tác động đến các quyết định ảnh hưởng đến tương lai của họ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
