INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-39', 'en', 'Bài 39: Lịch sử & Văn hóa - CEFR B1', 'CEFR B1', 'B1 · Lịch sử', '15 từ vựng Tiếng Anh CEFR B1 chủ đề lịch sử & văn hóa kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3039, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_temple', 'en-b1-39', 'temple', '/ˈtempl/', 'B1', 'chùa; đền thờ; đền; vùng thái dương; thái dương', 'n.', NULL, NULL, 'Khi chỉ thái dương, người ta thường dùng dạng số nhiều temples để chỉ cả hai bên.', 'We removed our shoes before entering the temple.', NULL, 'Chúng tôi đã cởi giày trước khi bước vào đền thờ.', '{"wordId":"temple","ukIpa":"/ˈtempl/","usIpa":"/ˈtempl/","cefr":"B1","topic":"history","senses":[{"pos":"n.","en":"a building used for worship in certain religions","vi":"chùa; đền thờ; đền"},{"pos":"n.","en":"the flat area on either side of the forehead","vi":"vùng thái dương; thái dương"}],"examples":[{"en":"We removed our shoes before entering the temple.","vi":"Chúng tôi đã cởi giày trước khi bước vào đền thờ.","audioKind":"ex"},{"en":"Restoring an ancient temple can preserve local heritage while attracting visitors interested in history and architecture.","vi":"Việc trùng tu một ngôi đền cổ có thể bảo tồn di sản địa phương đồng thời thu hút du khách quan tâm đến lịch sử và kiến trúc.","audioKind":"ex2"}],"collocations":[{"en":"an ancient temple","vi":"một ngôi đền cổ"},{"en":"a Buddhist temple","vi":"một ngôi chùa Phật giáo"},{"en":"temple ruins","vi":"tàn tích đền thờ"},{"en":"rub your temples","vi":"xoa thái dương"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ thái dương, người ta thường dùng dạng số nhiều temples để chỉ cả hai bên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pirate', 'en-b1-39', 'pirate', '/ˈpaɪrət/', 'B1', 'hải cướp; cướp biển; sao chép hoặc phân phối tài liệu có bản quyền trái phép; kẻ vi phạm bản quyền; kẻ làm đồ giả', 'n.', 'piracy (n.)', NULL, 'pirated nhấn mạnh việc bị sao chép trái phép; piracy là danh từ tương ứng.', 'The pirate in the story sailed a wooden ship.', NULL, 'Tên cướp biển trong câu chuyện lái một con tàu bằng gỗ.', '{"wordId":"pirate","ukIpa":"/ˈpaɪrət/","usIpa":"/ˈpaɪrət/","cefr":"B1","topic":"history","senses":[{"pos":"n.","en":"someone who attacks ships and steals from them","vi":"hải cướp; cướp biển"},{"pos":"v.","en":"to copy or distribute protected material without permission","vi":"sao chép hoặc phân phối tài liệu có bản quyền trái phép"},{"pos":"n.","en":"someone who illegally copies or distributes protected material","vi":"kẻ vi phạm bản quyền; kẻ làm đồ giả"}],"examples":[{"en":"The pirate in the story sailed a wooden ship.","vi":"Tên cướp biển trong câu chuyện lái một con tàu bằng gỗ.","audioKind":"ex"},{"en":"When companies pirate educational software, they undermine the income that developers need to improve their products.","vi":"Khi các công ty sao chép trái phép phần mềm giáo dục, họ làm suy giảm nguồn thu nhập mà các nhà phát triển cần có để cải tiến sản phẩm của mình.","audioKind":"ex2"}],"collocations":[{"en":"pirate ship","vi":"tàu cướp biển"},{"en":"pirated software","vi":"phần mềm lậu"},{"en":"pirate films","vi":"phim lậu"}],"wordFamily":["piracy (n.)"],"synonyms":[],"antonyms":[],"tipVi":"pirated nhấn mạnh việc bị sao chép trái phép; piracy là danh từ tương ứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_windmill', 'en-b1-39', 'windmill', '/ˈwɪndmɪl/', 'B1', 'cối xay gió', 'n.', NULL, NULL, 'Mặt trời và gió tạo năng lượng hiện đại thường gọi là wind turbine.', 'We watched the old windmill turn beside the river.', NULL, 'Chúng tôi ngắm nhìn chiếc cối xay gió cổ kính quay bên dòng sông.', '{"wordId":"windmill","ukIpa":"/ˈwɪndmɪl/","usIpa":"/ˈwɪndmɪl/","cefr":"B1","topic":"history","senses":[{"pos":"n.","en":"A structure whose wind-driven sails power machinery, often for grinding grain.","vi":"cối xay gió"}],"examples":[{"en":"We watched the old windmill turn beside the river.","vi":"Chúng tôi ngắm nhìn chiếc cối xay gió cổ kính quay bên dòng sông.","audioKind":"ex"},{"en":"Restoring a traditional windmill can preserve local heritage while attracting visitors interested in the history of rural technology.","vi":"Việc phục dựng một chiếc cối xay gió truyền thống có thể bảo tồn di sản địa phương đồng thời thu hút khách du lịch quan tâm đến lịch sử kỹ thuật nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"a traditional windmill","vi":"cối xay gió truyền thống"},{"en":"restore a windmill","vi":"phục dựng cối xay gió"},{"en":"windmill sails","vi":"cánh cối xay gió"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Mặt trời và gió tạo năng lượng hiện đại thường gọi là wind turbine.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cathedral', 'en-b1-39', 'cathedral', '/kəˈθiːdrəl/', 'B1', 'nhà thờ lớn; nhà thờ chính tòa', 'n.', NULL, NULL, 'Từ này chỉ nghiêm ngặt nhà thờ là trụ sở của giám mục, chứ không phải mọi nhà thờ lớn đều dùng từ này.', 'Sunlight streamed through the cathedral''s beautiful stained glass windows.', NULL, 'Ánh nắng rọi qua những ô cửa kính màu vô cùng đẹp mắt của nhà thờ lớn.', '{"wordId":"cathedral","ukIpa":"/kəˈθiːdrəl/","usIpa":"/kəˈθiːdrəl/","cefr":"B1","topic":"history","senses":[{"pos":"n.","en":"The main church of a district led by a bishop.","vi":"nhà thờ lớn; nhà thờ chính tòa"}],"examples":[{"en":"Sunlight streamed through the cathedral''s beautiful stained glass windows.","vi":"Ánh nắng rọi qua những ô cửa kính màu vô cùng đẹp mắt của nhà thờ lớn.","audioKind":"ex"},{"en":"Restoring a historic cathedral can preserve traditional craftsmanship while attracting visitors who support the local economy.","vi":"Việc trùng tu một nhà thờ lớn mang tính lịch sử có thể bảo tồn nghề thủ công truyền thống đồng thời thu hút khách du lịch hỗ trợ kinh tế địa phương.","audioKind":"ex2"}],"collocations":[{"en":"medieval cathedral","vi":"nhà thờ lớn thời trung cổ"},{"en":"cathedral tower","vi":"tháp nhà thờ lớn"},{"en":"cathedral restoration","vi":"trùng tu nhà thờ lớn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ này chỉ nghiêm ngặt nhà thờ là trụ sở của giám mục, chứ không phải mọi nhà thờ lớn đều dùng từ này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_treasure', 'en-b1-39', 'treasure', '/ˈtreʒər/', 'B1', 'kho báu; tài sản quý giá; báu vật; vật quý giá; trân trọng; nâng niu; quý trọng', 'n.', 'treasured (adj.), treasurer (n.), treasury (n.)', NULL, 'Khi chỉ kho báu nói chung thì không đếm được; khi chỉ bảo vật cụ thể thì đếm được.', 'The children imagined finding treasure inside the old chest.', NULL, 'Bọn trẻ tưởng tượng ra cảnh tìm thấy kho báu bên trong chiếc rương cũ.', '{"wordId":"treasure","ukIpa":"/ˈtreʒə/","usIpa":"/ˈtreʒər/","cefr":"B1","topic":"history","senses":[{"pos":"n.","en":"Gold, jewels, or other highly valuable objects","vi":"kho báu; tài sản quý giá"},{"pos":"n.","en":"Something greatly valued for its beauty, importance, or personal meaning","vi":"báu vật; vật quý giá"},{"pos":"v.","en":"To value something deeply and care for it","vi":"trân trọng; nâng niu; quý trọng"}],"examples":[{"en":"The children imagined finding treasure inside the old chest.","vi":"Bọn trẻ tưởng tượng ra cảnh tìm thấy kho báu bên trong chiếc rương cũ.","audioKind":"ex"},{"en":"Museums preserve cultural treasures so that future generations can understand the achievements and traditions of earlier societies.","vi":"Các bảo tàng gìn giữ những báu vật văn hóa để các thế hệ tương lai có thể thấu hiểu các thành tựu và truyền thống của các xã hội đi trước.","audioKind":"ex2"}],"collocations":[{"en":"buried treasure","vi":"kho báu chôn giấu"},{"en":"national treasure","vi":"quốc bảo; báu vật quốc gia"},{"en":"treasure memories","vi":"trân trọng những kỷ niệm"},{"en":"treasure hunt","vi":"cuộc thi tìm kho báu"}],"wordFamily":["treasured (adj.)","treasurer (n.)","treasury (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ kho báu nói chung thì không đếm được; khi chỉ bảo vật cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_historian', 'en-b1-39', 'historian', '/hɪˈstɔːriən/', 'B1', 'nhà sử học; nhà nghiên cứu lịch sử', 'n.', 'history (n), historical (adj), historically (adv)', NULL, 'historian chỉ người nghiên cứu; historical biểu thị những gì liên quan đến lịch sử.', 'The historian examined an old map under a lamp.', NULL, 'Nhà sử học đã soi chiếu một tấm bản đồ cũ dưới ánh đèn.', '{"wordId":"historian","ukIpa":"/hɪˈstɔːriən/","usIpa":"/hɪˈstɔːriən/","cefr":"B1","topic":"history","senses":[{"pos":"n.","en":"Someone who studies or writes about the past.","vi":"nhà sử học; nhà nghiên cứu lịch sử"}],"examples":[{"en":"The historian examined an old map under a lamp.","vi":"Nhà sử học đã soi chiếu một tấm bản đồ cũ dưới ánh đèn.","audioKind":"ex"},{"en":"Historians use a range of sources to explain how industrialisation transformed everyday life in urban communities.","vi":"Các nhà sử học sử dụng nhiều nguồn tài liệu khác nhau để giải thích quá trình công nghiệp hóa đã làm biến đổi đời sống thường nhật ở các cộng đồng đô thị như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"a leading historian","vi":"một nhà sử học hàng đầu"},{"en":"a social historian","vi":"một nhà sử học xã hội"},{"en":"a historian of science","vi":"một nhà sử học chuyên ngành khoa học"}],"wordFamily":["history (n)","historical (adj)","historically (adv)"],"synonyms":[],"antonyms":[],"tipVi":"historian chỉ người nghiên cứu; historical biểu thị những gì liên quan đến lịch sử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pyramid', 'en-b1-39', 'pyramid', '/ˈpɪrəmɪd/', 'B1', 'kim tự tháp; hình chóp; hệ thống phân cấp hình kim tự tháp', 'n.', 'pyramidal (adj.)', NULL, 'Vừa chỉ kim tự tháp cổ đại, vừa chỉ hình chóp trong hình học.', 'We built a small pyramid out of wooden blocks.', NULL, 'Chúng tôi đã xếp một kim tự tháp nhỏ bằng những khối gỗ.', '{"wordId":"pyramid","ukIpa":"/ˈpɪrəmɪd/","usIpa":"/ˈpɪrəmɪd/","cefr":"B1","topic":"history","senses":[{"pos":"n.","en":"a structure with triangular sides meeting at a point","vi":"kim tự tháp; hình chóp"},{"pos":"n.","en":"a system with fewer members at each successively higher level","vi":"hệ thống phân cấp hình kim tự tháp"}],"examples":[{"en":"We built a small pyramid out of wooden blocks.","vi":"Chúng tôi đã xếp một kim tự tháp nhỏ bằng những khối gỗ.","audioKind":"ex"},{"en":"The management pyramid in many organisations places a small group of executives above numerous employees.","vi":"Hệ thống quản lý hình kim tự tháp ở nhiều tổ chức đặt một nhóm nhỏ các nhà điều hành lên trên đông đảo nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"ancient pyramid","vi":"kim tự tháp cổ đại"},{"en":"square-based pyramid","vi":"hình chóp đáy vuông"},{"en":"management pyramid","vi":"cơ cấu quản lý hình kim tự tháp"}],"wordFamily":["pyramidal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Vừa chỉ kim tự tháp cổ đại, vừa chỉ hình chóp trong hình học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decade', 'en-b1-39', 'decade', '/ˈdekeɪd/', 'B1', 'thập kỷ; mười năm', 'n.', NULL, NULL, 'a decade là một thập kỷ; decades thường dùng để chỉ nhiều thập kỷ.', 'They have lived on this street for a decade.', NULL, 'Họ đã sống trên con phố này được một thập kỷ.', '{"wordId":"decade","ukIpa":"/ˈdekeɪd/","usIpa":"/ˈdekeɪd/","cefr":"B1","topic":"history","senses":[{"pos":"n.","en":"a period of ten years","vi":"thập kỷ; mười năm"}],"examples":[{"en":"They have lived on this street for a decade.","vi":"Họ đã sống trên con phố này được một thập kỷ.","audioKind":"ex"},{"en":"Over the past decade, digital technology has significantly changed how people access education and healthcare.","vi":"Trong thập kỷ qua, công nghệ số đã thay đổi đáng kể cách mọi người tiếp cận giáo dục và dịch vụ y tế.","audioKind":"ex2"}],"collocations":[{"en":"over the past decade","vi":"trong thập kỷ qua"},{"en":"for decades","vi":"trong nhiều thập kỷ"},{"en":"the next decade","vi":"thập kỷ tới"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"a decade là một thập kỷ; decades thường dùng để chỉ nhiều thập kỷ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bomb', 'en-b1-39', 'bomb', '/bɑːm/', 'B1', 'quả bom; ném bom; oanh tạc', 'n.', 'bombing (n.), bomber (n.)', NULL, 'Chữ "b" cuối từ không phát âm; "bombing" chỉ vụ ném bom hoặc đánh bom.', 'The museum displayed an empty bomb casing behind glass.', NULL, 'Viện bảo tàng trưng bày một vỏ bom trống được đặt đằng sau lớp kính.', '{"wordId":"bomb","ukIpa":"/bɒm/","usIpa":"/bɑːm/","cefr":"B1","topic":"history","senses":[{"pos":"n.","en":"A weapon designed to explode and cause damage.","vi":"quả bom"},{"pos":"v.","en":"To attack a place using bombs.","vi":"ném bom; oanh tạc"}],"examples":[{"en":"The museum displayed an empty bomb casing behind glass.","vi":"Viện bảo tàng trưng bày một vỏ bom trống được đặt đằng sau lớp kính.","audioKind":"ex"},{"en":"Construction projects may be delayed when workers discover an unexploded bomb left over from a past conflict.","vi":"Các dự án xây dựng có thể bị trì hoãn khi công nhân phát hiện một quả bom chưa nổ sót lại từ cuộc xung đột trong quá khứ.","audioKind":"ex2"}],"collocations":[{"en":"an unexploded bomb","vi":"bom chưa nổ"},{"en":"defuse a bomb","vi":"gỡ ngòi nổ bom"},{"en":"a bomb disposal team","vi":"đội rà phá bom mìn"}],"wordFamily":["bombing (n.)","bomber (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ \"b\" cuối từ không phát âm; \"bombing\" chỉ vụ ném bom hoặc đánh bom.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crown', 'en-b1-39', 'crown', '/kraʊn/', 'B1', 'vương miện; mão; đội vương miện; tôn lên ngôi vua; phong vương; đỉnh; đỉnh đầu; tán cây', 'n.', 'crowning (adj.)', NULL, 'be crowned champion có nghĩa là "được phong là quán quân".', 'The queen wore a golden crown during the ceremony.', NULL, 'Nữ hoàng đã đội một chiếc vương miện bằng vàng trong buổi lễ.', '{"wordId":"crown","ukIpa":"/kraʊn/","usIpa":"/kraʊn/","cefr":"B1","topic":"history","senses":[{"pos":"n.","en":"a ceremonial headpiece worn by a king or queen","vi":"vương miện; mão"},{"pos":"v.","en":"to officially make someone a monarch or declare them champion","vi":"đội vương miện; tôn lên ngôi vua; phong vương"},{"pos":"n.","en":"the highest part of a head, tree, or other object","vi":"đỉnh; đỉnh đầu; tán cây"}],"examples":[{"en":"The queen wore a golden crown during the ceremony.","vi":"Nữ hoàng đã đội một chiếc vương miện bằng vàng trong buổi lễ.","audioKind":"ex"},{"en":"A royal crown displayed in a museum can reveal historical attitudes towards wealth, authority, and craftsmanship.","vi":"Một chiếc vương miện hoàng gia được trưng bày trong viện bảo tàng có thể tiết lộ quan niệm lịch sử đối với sự giàu có, quyền lực và nghệ thuật chế tác.","audioKind":"ex2"}],"collocations":[{"en":"wear a crown","vi":"đội vương miện"},{"en":"be crowned champion","vi":"được phong là quán quân"},{"en":"the crown of the head","vi":"đỉnh đầu"},{"en":"the crown of a tree","vi":"tán cây"}],"wordFamily":["crowning (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"be crowned champion có nghĩa là \"được phong là quán quân\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_originally', 'en-b1-39', 'originally', '/əˈrɪdʒənəli/', 'B1', 'ban đầu; vốn dĩ; vốn có nguồn gốc từ', 'adv.', 'origin (n.), original (adj.), originality (n.)', 'Đồng nghĩa: initially, at first', 'Diễn tả tình trạng ban đầu, thường ngụ ý sau đó đã có thay đổi; không đồng nghĩa với currently.', 'This café was originally a small shop selling flowers.', NULL, 'Quán cà phê này ban đầu là một cửa hàng nhỏ bán hoa.', '{"wordId":"originally","ukIpa":"/əˈrɪdʒənəli/","usIpa":"/əˈrɪdʒənəli/","cefr":"B1","topic":"history","senses":[{"pos":"adv.","en":"at first, before later changes","vi":"ban đầu; vốn dĩ"},{"pos":"adv.","en":"in relation to where someone or something first came from","vi":"vốn có nguồn gốc từ"}],"examples":[{"en":"This café was originally a small shop selling flowers.","vi":"Quán cà phê này ban đầu là một cửa hàng nhỏ bán hoa.","audioKind":"ex"},{"en":"Many buildings originally designed as factories have been converted into housing to meet growing urban demand.","vi":"Nhiều tòa nhà vốn được thiết kế làm nhà máy đã được cải tạo thành nhà ở để đáp ứng nhu cầu đô thị ngày càng tăng.","audioKind":"ex2"}],"collocations":[{"en":"originally planned","vi":"dự định ban đầu"},{"en":"originally intended for","vi":"vốn dành cho"},{"en":"originally from","vi":"vốn xuất thân từ"}],"wordFamily":["origin (n.)","original (adj.)","originality (n.)"],"synonyms":["initially","at first"],"antonyms":[],"tipVi":"Diễn tả tình trạng ban đầu, thường ngụ ý sau đó đã có thay đổi; không đồng nghĩa với currently.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_battle', 'en-b1-39', 'battle', '/ˈbætəl/', 'B1', 'trận chiến; cuộc giao tranh; cuộc đấu tranh; sự đấu tranh gian khổ; chiến đấu; đấu tranh', 'n.', 'battleground (n.), battlefield (n.)', 'Đồng nghĩa: fight, struggle', 'battle có thể chỉ chiến đấu cụ thể, cũng thường dùng để ví von với việc chống lại bệnh tật hoặc khó khăn.', 'The museum displays armour from a famous battle.', NULL, 'Bảo tàng trưng bày áo giáp từ một trận chiến nổi tiếng.', '{"wordId":"battle","ukIpa":"/ˈbætəl/","usIpa":"/ˈbætəl/","cefr":"B1","topic":"history","senses":[{"pos":"n.","en":"A fight between armed forces.","vi":"trận chiến; cuộc giao tranh"},{"pos":"n.","en":"A difficult struggle to achieve something or overcome a problem.","vi":"cuộc đấu tranh; sự đấu tranh gian khổ"},{"pos":"v.","en":"To struggle hard against someone or something.","vi":"chiến đấu; đấu tranh"}],"examples":[{"en":"The museum displays armour from a famous battle.","vi":"Bảo tàng trưng bày áo giáp từ một trận chiến nổi tiếng.","audioKind":"ex"},{"en":"The battle against air pollution requires coordinated action from governments, businesses, and individuals across urban areas.","vi":"Cuộc chiến chống ô nhiễm không khí đòi hỏi sự hành động phối hợp từ các chính phủ, doanh nghiệp và cá nhân trên khắp các khu vực đô thị.","audioKind":"ex2"}],"collocations":[{"en":"win a battle","vi":"giành chiến thắng trong một trận chiến"},{"en":"an uphill battle","vi":"cuộc chiến đầy cam go"},{"en":"battle against pollution","vi":"cuộc chiến chống ô nhiễm"},{"en":"battle for survival","vi":"cuộc chiến sinh tồn"}],"wordFamily":["battleground (n.)","battlefield (n.)"],"synonyms":["fight","struggle"],"antonyms":[],"tipVi":"battle có thể chỉ chiến đấu cụ thể, cũng thường dùng để ví von với việc chống lại bệnh tật hoặc khó khăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_monument', 'en-b1-39', 'monument', '/ˈmɑːnjəmənt/', 'B1', 'đài tưởng niệm; công trình tưởng niệm; di tích lịch sử; cổ vật', 'n.', 'monumental (adj.)', 'Đồng nghĩa: memorial', 'Để chỉ công trình tưởng niệm ai hoặc sự kiện gì thì dùng a monument to.', 'We left flowers beside the monument in the town square.', NULL, 'Chúng tôi đã đặt những nhành hoa bên đài tưởng niệm ở quảng trường thị trấn.', '{"wordId":"monument","ukIpa":"/ˈmɒnjʊmənt/","usIpa":"/ˈmɑːnjəmənt/","cefr":"B1","topic":"history","senses":[{"pos":"n.","en":"A structure built to honour a person or important event.","vi":"đài tưởng niệm; công trình tưởng niệm"},{"pos":"n.","en":"An old structure valued for its historical importance.","vi":"di tích lịch sử; cổ vật"}],"examples":[{"en":"We left flowers beside the monument in the town square.","vi":"Chúng tôi đã đặt những nhành hoa bên đài tưởng niệm ở quảng trường thị trấn.","audioKind":"ex"},{"en":"Protecting ancient monuments can strengthen cultural identity while attracting visitors and supporting employment in local communities.","vi":"Bảo vệ các di tích cổ có thể củng cố bản sắc văn hóa đồng thời thu hút du khách và hỗ trợ việc làm cho cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a monument to","vi":"đài tưởng niệm để ghi nhớ"},{"en":"an ancient monument","vi":"một di tích cổ"},{"en":"a historic monument","vi":"một di tích lịch sử"},{"en":"erect a monument","vi":"dựng đài tưởng niệm"}],"wordFamily":["monumental (adj.)"],"synonyms":["memorial"],"antonyms":[],"tipVi":"Để chỉ công trình tưởng niệm ai hoặc sự kiện gì thì dùng a monument to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_historic', 'en-b1-39', 'historic', '/hɪˈstɔːrɪk/', 'B1', 'mang ý nghĩa lịch sử; có tầm quan trọng lịch sử; lịch sử', 'adj.', 'history (n.), historical (adj.), historically (adv.), historian (n.)', 'Đồng nghĩa: momentous', 'historic nhấn mạnh tầm quan trọng lịch sử; historical dùng để chỉ chung những gì liên quan đến lịch sử.', 'We crossed the historic bridge just before sunset.', NULL, 'Chúng tôi băng qua cây cầu lịch sử ngay trước khi mặt trời lặn.', '{"wordId":"historic","ukIpa":"/hɪˈstɒrɪk/","usIpa":"/hɪˈstɔːrɪk/","cefr":"B1","topic":"history","senses":[{"pos":"adj.","en":"Important in history or likely to be remembered in history.","vi":"mang ý nghĩa lịch sử; có tầm quan trọng lịch sử; lịch sử"}],"examples":[{"en":"We crossed the historic bridge just before sunset.","vi":"Chúng tôi băng qua cây cầu lịch sử ngay trước khi mặt trời lặn.","audioKind":"ex"},{"en":"Protecting historic buildings helps cities preserve their cultural identity while attracting visitors and supporting local businesses.","vi":"Việc bảo vệ các công trình lịch sử giúp các thành phố gìn giữ nét đặc sắc văn hóa, đồng thời thu hút khách du lịch và hỗ trợ các doanh nghiệp địa phương.","audioKind":"ex2"}],"collocations":[{"en":"historic building","vi":"công trình lịch sử"},{"en":"historic event","vi":"sự kiện lịch sử"},{"en":"historic landmark","vi":"địa danh lịch sử"},{"en":"historic agreement","vi":"thỏa thuận mang tính lịch sử"}],"wordFamily":["history (n.)","historical (adj.)","historically (adv.)","historian (n.)"],"synonyms":["momentous"],"antonyms":[],"tipVi":"historic nhấn mạnh tầm quan trọng lịch sử; historical dùng để chỉ chung những gì liên quan đến lịch sử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_historical', 'en-b1-39', 'historical', '/hɪˈstɔːrɪkəl/', 'B1', 'thuộc về lịch sử; có liên quan đến các sự kiện trong quá khứ', 'adj.', 'history (n.), historian (n.), historically (adv.), historic (adj.)', NULL, 'Historical dùng để chỉ những gì liên quan đến lịch sử; historic dùng để chỉ sự kiện có tầm quan trọng lịch sử.', 'We found historical photographs of our street in the library.', NULL, 'Chúng tôi tìm thấy những bức ảnh lịch sử về con phố của mình trong thư viện.', '{"wordId":"historical","ukIpa":"/hɪˈstɒrɪkəl/","usIpa":"/hɪˈstɔːrɪkəl/","cefr":"B1","topic":"history","senses":[{"pos":"adj.","en":"connected with history or events in the past","vi":"thuộc về lịch sử; có liên quan đến các sự kiện trong quá khứ"}],"examples":[{"en":"We found historical photographs of our street in the library.","vi":"Chúng tôi tìm thấy những bức ảnh lịch sử về con phố của mình trong thư viện.","audioKind":"ex"},{"en":"Historical records help researchers understand how earlier societies responded to environmental change and economic uncertainty.","vi":"Các tài liệu lịch sử giúp các nhà nghiên cứu hiểu được cách các xã hội trước đây ứng phó với biến đổi môi trường và sự bất định kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"historical records","vi":"tư liệu lịch sử"},{"en":"historical evidence","vi":"bằng chứng lịch sử"},{"en":"historical context","vi":"bối cảnh lịch sử"},{"en":"historical novel","vi":"tiểu thuyết lịch sử"}],"wordFamily":["history (n.)","historian (n.)","historically (adv.)","historic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Historical dùng để chỉ những gì liên quan đến lịch sử; historic dùng để chỉ sự kiện có tầm quan trọng lịch sử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_39_1', 'en-b1-39', 'Cách dùng “historical” (adj.) — thuộc về lịch sử; có liên quan đến các sự kiện trong quá khứ', 'historical records  ·  historical evidence  ·  historical context', 'Historical dùng để chỉ những gì liên quan đến lịch sử; historic dùng để chỉ sự kiện có tầm quan trọng lịch sử.', 'Họ từ (Word Family): history (n.), historian (n.), historically (adv.), historic (adj.)', '[{"hanzi":"We found historical photographs of our street in the library.","pinyin":"","meaning":"Chúng tôi tìm thấy những bức ảnh lịch sử về con phố của mình trong thư viện."},{"hanzi":"Historical records help researchers understand how earlier societies responded to environmental change and economic uncertainty.","pinyin":"","meaning":"Các tài liệu lịch sử giúp các nhà nghiên cứu hiểu được cách các xã hội trước đây ứng phó với biến đổi môi trường và sự bất định kinh tế."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_39_2', 'en-b1-39', 'Cách dùng “battle” (n.) — trận chiến; cuộc giao tranh', 'win a battle  ·  an uphill battle  ·  battle against pollution', 'battle có thể chỉ chiến đấu cụ thể, cũng thường dùng để ví von với việc chống lại bệnh tật hoặc khó khăn.', 'Họ từ (Word Family): battleground (n.), battlefield (n.) | Đồng nghĩa: fight, struggle', '[{"hanzi":"The museum displays armour from a famous battle.","pinyin":"","meaning":"Bảo tàng trưng bày áo giáp từ một trận chiến nổi tiếng."},{"hanzi":"The battle against air pollution requires coordinated action from governments, businesses, and individuals across urban areas.","pinyin":"","meaning":"Cuộc chiến chống ô nhiễm không khí đòi hỏi sự hành động phối hợp từ các chính phủ, doanh nghiệp và cá nhân trên khắp các khu vực đô thị."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_39_3', 'en-b1-39', 'Cách dùng “historic” (adj.) — mang ý nghĩa lịch sử; có tầm quan trọng lịch sử; lịch sử', 'historic building  ·  historic event  ·  historic landmark', 'historic nhấn mạnh tầm quan trọng lịch sử; historical dùng để chỉ chung những gì liên quan đến lịch sử.', 'Họ từ (Word Family): history (n.), historical (adj.), historically (adv.), historian (n.) | Đồng nghĩa: momentous', '[{"hanzi":"We crossed the historic bridge just before sunset.","pinyin":"","meaning":"Chúng tôi băng qua cây cầu lịch sử ngay trước khi mặt trời lặn."},{"hanzi":"Protecting historic buildings helps cities preserve their cultural identity while attracting visitors and supporting local businesses.","pinyin":"","meaning":"Việc bảo vệ các công trình lịch sử giúp các thành phố gìn giữ nét đặc sắc văn hóa, đồng thời thu hút khách du lịch và hỗ trợ các doanh nghiệp địa phương."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_39_4', 'en-b1-39', 'Cách dùng “cathedral” (n.) — nhà thờ lớn; nhà thờ chính tòa', 'medieval cathedral  ·  cathedral tower  ·  cathedral restoration', 'Từ này chỉ nghiêm ngặt nhà thờ là trụ sở của giám mục, chứ không phải mọi nhà thờ lớn đều dùng từ này.', NULL, '[{"hanzi":"Sunlight streamed through the cathedral''s beautiful stained glass windows.","pinyin":"","meaning":"Ánh nắng rọi qua những ô cửa kính màu vô cùng đẹp mắt của nhà thờ lớn."},{"hanzi":"Restoring a historic cathedral can preserve traditional craftsmanship while attracting visitors who support the local economy.","pinyin":"","meaning":"Việc trùng tu một nhà thờ lớn mang tính lịch sử có thể bảo tồn nghề thủ công truyền thống đồng thời thu hút khách du lịch hỗ trợ kinh tế địa phương."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_39_1', 'en-b1-39', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
