INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_39_1_2', 'ten_b1_39_1', 'pirate', 'The pirate in the story sailed a wooden ship.', 'The pirate in the story sailed a wooden ship.', '/ˈpaɪrət/', 'Tên cướp biển trong câu chuyện lái một con tàu bằng gỗ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_39_1_3', 'ten_b1_39_1', 'windmill', 'We watched the old windmill turn beside the river.', 'We watched the old windmill turn beside the river.', '/ˈwɪndmɪl/', 'Chúng tôi ngắm nhìn chiếc cối xay gió cổ kính quay bên dòng sông.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_39_1_4', 'ten_b1_39_1', 'cathedral', 'Sunlight streamed through the cathedral''s beautiful stained glass windows.', 'Sunlight streamed through the cathedral''s beautiful stained glass windows.', '/kəˈθiːdrəl/', 'Ánh nắng rọi qua những ô cửa kính màu vô cùng đẹp mắt của nhà thờ lớn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_39_1_5', 'ten_b1_39_1', 'treasure', 'The children imagined finding treasure inside the old chest.', 'The children imagined finding treasure inside the old chest.', '/ˈtreʒər/', 'Bọn trẻ tưởng tượng ra cảnh tìm thấy kho báu bên trong chiếc rương cũ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_39_1_6', 'ten_b1_39_1', 'historian', 'The historian examined an old map under a lamp.', 'The historian examined an old map under a lamp.', '/hɪˈstɔːriən/', 'Nhà sử học đã soi chiếu một tấm bản đồ cũ dưới ánh đèn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_39_1_7', 'ten_b1_39_1', 'pyramid', 'We built a small pyramid out of wooden blocks.', 'We built a small pyramid out of wooden blocks.', '/ˈpɪrəmɪd/', 'Chúng tôi đã xếp một kim tự tháp nhỏ bằng những khối gỗ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_39_1_8', 'ten_b1_39_1', 'decade', 'They have lived on this street for a decade.', 'They have lived on this street for a decade.', '/ˈdekeɪd/', 'Họ đã sống trên con phố này được một thập kỷ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_39_1_1', 'en-b1-39', 'ten_b1_39_1', 'listening', 'listening', 'We removed our shoes before entering the temple.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Họ đã sống trên con phố này được một thập kỷ.","Chúng tôi đã cởi giày trước khi bước vào đền thờ.","Bọn trẻ tưởng tượng ra cảnh tìm thấy kho báu bên trong chiếc rương cũ.","Chúng tôi đã xếp một kim tự tháp nhỏ bằng những khối gỗ."]'::jsonb, 1, 'We removed our shoes before entering the temple. → Chúng tôi đã cởi giày trước khi bước vào đền thờ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_39_1_2', 'en-b1-39', 'ten_b1_39_1', 'listening', 'listening', 'The pirate in the story sailed a wooden ship.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã đặt những nhành hoa bên đài tưởng niệm ở quảng trường thị trấn.","Nhà sử học đã soi chiếu một tấm bản đồ cũ dưới ánh đèn.","Họ đã sống trên con phố này được một thập kỷ.","Tên cướp biển trong câu chuyện lái một con tàu bằng gỗ."]'::jsonb, 3, 'The pirate in the story sailed a wooden ship. → Tên cướp biển trong câu chuyện lái một con tàu bằng gỗ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_39_1_3', 'en-b1-39', 'ten_b1_39_1', 'listening', 'listening', 'We watched the old windmill turn beside the river.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi tìm thấy những bức ảnh lịch sử về con phố của mình trong thư viện.","Chúng tôi ngắm nhìn chiếc cối xay gió cổ kính quay bên dòng sông.","Nữ hoàng đã đội một chiếc vương miện bằng vàng trong buổi lễ.","Chúng tôi băng qua cây cầu lịch sử ngay trước khi mặt trời lặn."]'::jsonb, 1, 'We watched the old windmill turn beside the river. → Chúng tôi ngắm nhìn chiếc cối xay gió cổ kính quay bên dòng sông.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_39_2', 'en-b1-39', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_39_2_1', 'ten_b1_39_2', 'temple', 'Restoring an ancient temple can preserve local heritage while attracting visitors interested in history and architecture.', 'Restoring an ancient temple can preserve local heritage while attracting visitors interested in history and architecture.', '/ˈtempl/', 'Việc trùng tu một ngôi đền cổ có thể bảo tồn di sản địa phương đồng thời thu hút du khách quan tâm đến lịch sử và kiến trúc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_39_2_2', 'ten_b1_39_2', 'pirate', 'When companies pirate educational software, they undermine the income that developers need to improve their products.', 'When companies pirate educational software, they undermine the income that developers need to improve their products.', '/ˈpaɪrət/', 'Khi các công ty sao chép trái phép phần mềm giáo dục, họ làm suy giảm nguồn thu nhập mà các nhà phát triển cần có để cải tiến sản phẩm của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_39_2_3', 'ten_b1_39_2', 'windmill', 'Restoring a traditional windmill can preserve local heritage while attracting visitors interested in the history of rural technology.', 'Restoring a traditional windmill can preserve local heritage while attracting visitors interested in the history of rural technology.', '/ˈwɪndmɪl/', 'Việc phục dựng một chiếc cối xay gió truyền thống có thể bảo tồn di sản địa phương đồng thời thu hút khách du lịch quan tâm đến lịch sử kỹ thuật nông thôn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_39_2_4', 'ten_b1_39_2', 'cathedral', 'Restoring a historic cathedral can preserve traditional craftsmanship while attracting visitors who support the local economy.', 'Restoring a historic cathedral can preserve traditional craftsmanship while attracting visitors who support the local economy.', '/kəˈθiːdrəl/', 'Việc trùng tu một nhà thờ lớn mang tính lịch sử có thể bảo tồn nghề thủ công truyền thống đồng thời thu hút khách du lịch hỗ trợ kinh tế địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_39_2_5', 'ten_b1_39_2', 'treasure', 'Museums preserve cultural treasures so that future generations can understand the achievements and traditions of earlier societies.', 'Museums preserve cultural treasures so that future generations can understand the achievements and traditions of earlier societies.', '/ˈtreʒər/', 'Các bảo tàng gìn giữ những báu vật văn hóa để các thế hệ tương lai có thể thấu hiểu các thành tựu và truyền thống của các xã hội đi trước.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_39_2_6', 'ten_b1_39_2', 'historian', 'Historians use a range of sources to explain how industrialisation transformed everyday life in urban communities.', 'Historians use a range of sources to explain how industrialisation transformed everyday life in urban communities.', '/hɪˈstɔːriən/', 'Các nhà sử học sử dụng nhiều nguồn tài liệu khác nhau để giải thích quá trình công nghiệp hóa đã làm biến đổi đời sống thường nhật ở các cộng đồng đô thị như thế nào.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_39_2_1', 'en-b1-39', 'ten_b1_39_2', 'listening', 'listening', 'Restoring an ancient temple can preserve local heritage while attracting visitors interested in history and architecture.', NULL, 'Trong câu vừa nghe, từ “temple” mang nghĩa nào sau đây?', '["thuộc về kinh tế","chứa cồn; có cồn","chùa; đền thờ; đền","làm cho ai đó thất vọng vì không đáp ứng được kỳ vọng của họ"]'::jsonb, 2, '“temple” (/ˈtempl/): chùa; đền thờ; đền. Câu đầy đủ: Restoring an ancient temple can preserve local heritage while attracting visitors interested in history and architecture.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_39_2_2', 'en-b1-39', 'ten_b1_39_2', 'listening', 'listening', 'When companies pirate educational software, they undermine the income that developers need to improve their products.', NULL, 'Trong câu vừa nghe, từ “pirate” mang nghĩa nào sau đây?', '["hải cướp; cướp biển","tò mò; ham học hỏi","quả hạch; hạt cứng","bờ; dải đất dọc theo mép biển hoặc hồ"]'::jsonb, 0, '“pirate” (/ˈpaɪrət/): hải cướp; cướp biển. Câu đầy đủ: When companies pirate educational software, they undermine the income that developers need to improve their products.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_39_1', 'en-b1-39', 'We removed our shoes before entering the temple', 'Chúng tôi đã cởi giày trước khi bước vào đền thờ.', 'temple /ˈtempl/', '["removed","shoes","entering","temple","before","our","the","We"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_39_2', 'en-b1-39', 'The pirate in the story sailed a wooden ship', 'Tên cướp biển trong câu chuyện lái một con tàu bằng gỗ.', 'pirate /ˈpaɪrət/', '["wooden","in","ship","a","sailed","pirate","The","the","story"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_39_3', 'en-b1-39', 'We watched the old windmill turn beside the river', 'Chúng tôi ngắm nhìn chiếc cối xay gió cổ kính quay bên dòng sông.', 'windmill /ˈwɪndmɪl/', '["the","turn","beside","old","the","We","watched","river","windmill"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_39_4', 'en-b1-39', 'Sunlight streamed through the cathedral''s beautiful stained glass windows', 'Ánh nắng rọi qua những ô cửa kính màu vô cùng đẹp mắt của nhà thờ lớn.', 'cathedral /kəˈθiːdrəl/', '["beautiful","cathedral''s","Sunlight","glass","through","windows","stained","streamed","the"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_39_5', 'en-b1-39', 'The children imagined finding treasure inside the old chest', 'Bọn trẻ tưởng tượng ra cảnh tìm thấy kho báu bên trong chiếc rương cũ.', 'treasure /ˈtreʒər/', '["imagined","the","finding","inside","treasure","chest","children","The","old"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_39_6', 'en-b1-39', 'The historian examined an old map under a lamp', 'Nhà sử học đã soi chiếu một tấm bản đồ cũ dưới ánh đèn.', 'historian /hɪˈstɔːriən/', '["under","The","examined","an","lamp","historian","map","old","a"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
