INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_1', 'en-b1-39', NULL, 'comprehensive_test', 'listening', 'temple', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cuộc thi; cuộc đấu tranh","sự thanh toán; việc trả tiền","chất độc; thuốc độc","chùa; đền thờ; đền"]'::jsonb, 3, 'temple (/ˈtempl/) → chùa; đền thờ; đền; vùng thái dương; thái dương', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_2', 'en-b1-39', NULL, 'comprehensive_test', 'listening', 'The pirate in the story sailed a wooden ship.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nữ hoàng đã đội một chiếc vương miện bằng vàng trong buổi lễ.","Bảo tàng trưng bày áo giáp từ một trận chiến nổi tiếng.","Tên cướp biển trong câu chuyện lái một con tàu bằng gỗ.","Chúng tôi băng qua cây cầu lịch sử ngay trước khi mặt trời lặn."]'::jsonb, 2, 'The pirate in the story sailed a wooden ship. → Tên cướp biển trong câu chuyện lái một con tàu bằng gỗ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_3', 'en-b1-39', NULL, 'comprehensive_test', 'listening', 'windmill', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trước đây; trước đó","cháo yến mạch; cháo đặc","thúc đẩy; khuyến khích; đề cao","cối xay gió"]'::jsonb, 3, 'windmill (/ˈwɪndmɪl/) → cối xay gió', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_4', 'en-b1-39', NULL, 'comprehensive_test', 'listening', 'Sunlight streamed through the cathedral''s beautiful stained glass windows.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi băng qua cây cầu lịch sử ngay trước khi mặt trời lặn.","Ánh nắng rọi qua những ô cửa kính màu vô cùng đẹp mắt của nhà thờ lớn.","Quán cà phê này ban đầu là một cửa hàng nhỏ bán hoa.","Nữ hoàng đã đội một chiếc vương miện bằng vàng trong buổi lễ."]'::jsonb, 1, 'Sunlight streamed through the cathedral''s beautiful stained glass windows. → Ánh nắng rọi qua những ô cửa kính màu vô cùng đẹp mắt của nhà thờ lớn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_5', 'en-b1-39', NULL, 'comprehensive_test', 'listening', 'treasure', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thuộc chuyên môn; chuyên nghiệp","nhà du hành vũ trụ; phi hành gia","kho báu; tài sản quý giá","phòng kho; nhà kho"]'::jsonb, 2, 'treasure (/ˈtreʒər/) → kho báu; tài sản quý giá; báu vật; vật quý giá; trân trọng; nâng niu; quý trọng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_6', 'en-b1-39', NULL, 'comprehensive_test', 'listening', 'The historian examined an old map under a lamp.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ánh nắng rọi qua những ô cửa kính màu vô cùng đẹp mắt của nhà thờ lớn.","Nhà sử học đã soi chiếu một tấm bản đồ cũ dưới ánh đèn.","Chúng tôi đã xếp một kim tự tháp nhỏ bằng những khối gỗ.","Chúng tôi tìm thấy những bức ảnh lịch sử về con phố của mình trong thư viện."]'::jsonb, 1, 'The historian examined an old map under a lamp. → Nhà sử học đã soi chiếu một tấm bản đồ cũ dưới ánh đèn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_7', 'en-b1-39', NULL, 'comprehensive_test', 'listening', 'pyramid', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm cho tin; thuyết phục","lời giải thích; sự giải thích","bộ đồ ăn (dao, nĩa, thìa)","kim tự tháp; hình chóp"]'::jsonb, 3, 'pyramid (/ˈpɪrəmɪd/) → kim tự tháp; hình chóp; hệ thống phân cấp hình kim tự tháp', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_8', 'en-b1-39', NULL, 'comprehensive_test', 'listening', 'They have lived on this street for a decade.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bọn trẻ tưởng tượng ra cảnh tìm thấy kho báu bên trong chiếc rương cũ.","Họ đã sống trên con phố này được một thập kỷ.","Nhà sử học đã soi chiếu một tấm bản đồ cũ dưới ánh đèn.","Viện bảo tàng trưng bày một vỏ bom trống được đặt đằng sau lớp kính."]'::jsonb, 1, 'They have lived on this street for a decade. → Họ đã sống trên con phố này được một thập kỷ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_9', 'en-b1-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Gold, jewels, or other highly valuable objects”?', '["treasure","historical","historic","decade"]'::jsonb, 0, 'treasure (/ˈtreʒər/) → kho báu; tài sản quý giá', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_10', 'en-b1-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Someone who studies or writes about the past.”?', '["historian","crown","battle","historic"]'::jsonb, 0, 'historian (/hɪˈstɔːriən/) → nhà sử học; nhà nghiên cứu lịch sử', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_11', 'en-b1-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a structure with triangular sides meeting at a point”?', '["bomb","monument","pyramid","historical"]'::jsonb, 2, 'pyramid (/ˈpɪrəmɪd/) → kim tự tháp; hình chóp', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_12', 'en-b1-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a period of ten years”?', '["treasure","originally","monument","decade"]'::jsonb, 3, 'decade (/ˈdekeɪd/) → thập kỷ; mười năm', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
