INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_18', 'en-b1-39', NULL, 'comprehensive_test', 'reading', NULL, 'Restoring an ancient temple can preserve local heritage while attracting visitors interested in history and architecture.', 'Dựa vào câu trên, từ “temple” có nghĩa phù hợp nhất là gì?', '["giọng điệu, khẩu âm","tác động; hiệu quả","chùa; đền thờ; đền","hàng rào; rào chắn"]'::jsonb, 2, 'temple: chùa; đền thờ; đền; vùng thái dương; thái dương. Dịch cả câu: Việc trùng tu một ngôi đền cổ có thể bảo tồn di sản địa phương đồng thời thu hút du khách quan tâm đến lịch sử và kiến trúc.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_19', 'en-b1-39', NULL, 'comprehensive_test', 'reading', NULL, 'When companies pirate educational software, they undermine the income that developers need to improve their products.', 'Dựa vào câu trên, từ “pirate” có nghĩa phù hợp nhất là gì?', '["hỗn hợp; thể hòa trộn","lân cận; giáp ranh; láng giềng","hải cướp; cướp biển","nhà khách; nhà nghỉ gia đình"]'::jsonb, 2, 'pirate: hải cướp; cướp biển; sao chép hoặc phân phối tài liệu có bản quyền trái phép; kẻ vi phạm bản quyền; kẻ làm đồ giả. Dịch cả câu: Khi các công ty sao chép trái phép phần mềm giáo dục, họ làm suy giảm nguồn thu nhập mà các nhà phát triển cần có để cải tiến sản phẩm của mình.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_20', 'en-b1-39', NULL, 'comprehensive_test', 'reading', NULL, 'Restoring a traditional windmill can preserve local heritage while attracting visitors interested in the history of rural technology.', 'Dựa vào câu trên, từ “windmill” có nghĩa phù hợp nhất là gì?', '["cối xay gió","thuộc về kinh tế","rơm; rạ; cỏ khô","la lớn; hét lớn"]'::jsonb, 0, 'windmill: cối xay gió. Dịch cả câu: Việc phục dựng một chiếc cối xay gió truyền thống có thể bảo tồn di sản địa phương đồng thời thu hút khách du lịch quan tâm đến lịch sử kỹ thuật nông thôn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_21', 'en-b1-39', NULL, 'comprehensive_test', 'reading', NULL, 'Restoring a historic cathedral can preserve traditional craftsmanship while attracting visitors who support the local economy.', 'Dựa vào câu trên, từ “cathedral” có nghĩa phù hợp nhất là gì?', '["nhà thờ lớn; nhà thờ chính tòa","sự so sánh; sự đối chiếu","... tuổi","không bên nào; cả hai đều không"]'::jsonb, 0, 'cathedral: nhà thờ lớn; nhà thờ chính tòa. Dịch cả câu: Việc trùng tu một nhà thờ lớn mang tính lịch sử có thể bảo tồn nghề thủ công truyền thống đồng thời thu hút khách du lịch hỗ trợ kinh tế địa phương.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_22', 'en-b1-39', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đài tưởng niệm; công trình tưởng niệm”', '["differ","addition","monument","technical"]'::jsonb, 2, 'đài tưởng niệm; công trình tưởng niệm → monument (/ˈmɑːnjəmənt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_23', 'en-b1-39', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mang ý nghĩa lịch sử; có tầm quan trọng lịch sử; lịch sử”', '["eventually","mystery","historic","affect"]'::jsonb, 2, 'mang ý nghĩa lịch sử; có tầm quan trọng lịch sử; lịch sử → historic (/hɪˈstɔːrɪk/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_39_24', 'en-b1-39', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về lịch sử; có liên quan đến các sự kiện trong quá khứ”', '["base","hurricane","dormitory","historical"]'::jsonb, 3, 'thuộc về lịch sử; có liên quan đến các sự kiện trong quá khứ → historical (/hɪˈstɔːrɪkəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-40', 'en', 'Bài 40: Đô thị & Kiến trúc - CEFR B1', 'CEFR B1', 'B1 · Đô thị', '26 từ vựng Tiếng Anh CEFR B1 chủ đề đô thị & kiến trúc kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3040, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_block', 'en-b1-40', 'block', '/blɑːk/', 'B1', 'khối; tảng; ngăn chặn; làm tắc nghẽn; khu nhà; dãy nhà; tòa nhà lớn', 'n.', 'blockage (n.), blocked (adj.)', NULL, 'Cụm a block of flats chỉ các tòa nhà chung cư, là cách diễn đạt rất phổ biến trong tiếng Anh-Anh.', 'The sculptor carved a bird from a block of wood.', NULL, 'Người thợ điêu khắc đã tạc một chú chim từ một khúc gỗ.', '{"wordId":"block","ukIpa":"/blɒk/","usIpa":"/blɑːk/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"A solid piece of material with fairly flat sides.","vi":"khối; tảng"},{"pos":"v.","en":"To stop movement or prevent something from happening.","vi":"ngăn chặn; làm tắc nghẽn"},{"pos":"n.","en":"An area between streets, or a large building.","vi":"khu nhà; dãy nhà; tòa nhà lớn"}],"examples":[{"en":"The sculptor carved a bird from a block of wood.","vi":"Người thợ điêu khắc đã tạc một chú chim từ một khúc gỗ.","audioKind":"ex"},{"en":"Poorly parked vehicles can block access to public buildings, creating difficulties for wheelchair users.","vi":"Phương tiện đỗ không đúng nơi quy định có thể cản trở lối vào các tòa nhà công cộng, gây khó khăn cho người dùng xe lăn.","audioKind":"ex2"}],"collocations":[{"en":"a block of flats","vi":"một tòa nhà chung cư"},{"en":"block the entrance","vi":"chặn lối vào"},{"en":"a block of ice","vi":"một tảng băng lớn"},{"en":"city block","vi":"khu phố; dãy nhà trong thành phố"}],"wordFamily":["blockage (n.)","blocked (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm a block of flats chỉ các tòa nhà chung cư, là cách diễn đạt rất phổ biến trong tiếng Anh-Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skyscraper', 'en-b1-40', 'skyscraper', '/ˈskaɪskreɪpər/', 'B1', 'tòa nhà chọc trời', 'n.', NULL, 'Đồng nghĩa: high-rise', 'Nhấn mạnh các tòa nhà cực kỳ cao so với các tòa nhà cao tầng (high-rise) thông thường.', 'The skyscraper cast a long shadow across the park.', NULL, 'Tòa nhà chọc trời đổ bóng dài across công viên.', '{"wordId":"skyscraper","ukIpa":"/ˈskaɪskreɪpə/","usIpa":"/ˈskaɪskreɪpər/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"An extremely tall building with many floors.","vi":"tòa nhà chọc trời"}],"examples":[{"en":"The skyscraper cast a long shadow across the park.","vi":"Tòa nhà chọc trời đổ bóng dài across công viên.","audioKind":"ex"},{"en":"Building skyscrapers can accommodate growing urban populations, but cities must also invest in reliable public transport.","vi":"Việc xây dựng các tòa nhà chọc trời có thể đáp ứng dân số đô thị ngày càng tăng, nhưng các thành phố cũng phải đầu tư vào hệ thống giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"build a skyscraper","vi":"xây dựng tòa nhà chọc trời"},{"en":"glass skyscraper","vi":"tòa nhà chọc trời bằng kính"},{"en":"towering skyscraper","vi":"tòa nhà chọc trời cao chót vót"}],"wordFamily":[],"synonyms":["high-rise"],"antonyms":[],"tipVi":"Nhấn mạnh các tòa nhà cực kỳ cao so với các tòa nhà cao tầng (high-rise) thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pavement', 'en-b1-40', 'pavement', '/ˈpeɪvmənt/', 'B1', 'vỉa hè; lề đường; bề mặt đường được lát cứng', 'n.', 'pave (v.), paving (n.)', 'Đồng nghĩa: sidewalk', 'Tiếng Anh-Anh chỉ vỉa hè; tiếng Anh-Mỹ thường chỉ bề mặt lát cứng của đường.', 'We walked along the pavement beside the busy road.', NULL, 'Chúng tôi đi bộ dọc theo vỉa hè cạnh con đường đông đúc.', '{"wordId":"pavement","ukIpa":"/ˈpeɪvmənt/","usIpa":"/ˈpeɪvmənt/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"A path beside a road for people to walk on.","vi":"vỉa hè; lề đường"},{"pos":"n.","en":"The hard surface covering a road or other outdoor area.","vi":"bề mặt đường được lát cứng"}],"examples":[{"en":"We walked along the pavement beside the busy road.","vi":"Chúng tôi đi bộ dọc theo vỉa hè cạnh con đường đông đúc.","audioKind":"ex"},{"en":"Wider pavements can improve pedestrian safety and make urban neighbourhoods more accessible for wheelchair users.","vi":"Vỉa hè rộng hơn có thể cải thiện an toàn cho người đi bộ và giúp các khu dân cư đô thị dễ tiếp cận hơn đối với người ngồi xe lăn.","audioKind":"ex2"}],"collocations":[{"en":"walk on the pavement","vi":"đi bộ trên vỉa hè"},{"en":"uneven pavement","vi":"vỉa hè gập ghềnh"},{"en":"pavement café","vi":"quán cà phê vỉa hè"}],"wordFamily":["pave (v.)","paving (n.)"],"synonyms":["sidewalk"],"antonyms":[],"tipVi":"Tiếng Anh-Anh chỉ vỉa hè; tiếng Anh-Mỹ thường chỉ bề mặt lát cứng của đường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_footbridge', 'en-b1-40', 'footbridge', '/ˈfʊtbrɪdʒ/', 'B1', 'cầu đi bộ', 'n.', NULL, NULL, 'footbridge chuyên dùng cho người đi bộ qua lại, không dành cho phương tiện giao thông.', 'We crossed the wooden footbridge above the stream.', NULL, 'Chúng tôi đã đi qua cây cầu đi bộ bằng gỗ bắc qua con suối.', '{"wordId":"footbridge","ukIpa":"/ˈfʊtbrɪdʒ/","usIpa":"/ˈfʊtbrɪdʒ/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"A bridge for people walking rather than vehicles.","vi":"cầu đi bộ"}],"examples":[{"en":"We crossed the wooden footbridge above the stream.","vi":"Chúng tôi đã đi qua cây cầu đi bộ bằng gỗ bắc qua con suối.","audioKind":"ex"},{"en":"Building a footbridge near the station would allow pedestrians to cross the busy road safely.","vi":"Việc xây dựng một cây cầu đi bộ gần nhà ga sẽ giúp người đi bộ băng qua con đường đông đúc một cách an toàn.","audioKind":"ex2"}],"collocations":[{"en":"cross a footbridge","vi":"đi qua cầu đi bộ"},{"en":"pedestrian footbridge","vi":"cầu vượt đi bộ"},{"en":"wooden footbridge","vi":"cầu đi bộ bằng gỗ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"footbridge chuyên dùng cho người đi bộ qua lại, không dành cho phương tiện giao thông.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_central', 'en-b1-40', 'central', '/ˈsentrəl/', 'B1', 'ở trung tâm; thuộc về trung tâm; quan trọng nhất; cốt lõi; thiết yếu', 'adj.', 'centrally (adv.), centre (n.), centralise (v.), centralisation (n.)', 'Trái nghĩa: peripheral', 'central to biểu thị "đối với... là tối quan trọng", giới từ đi kèm là to.', 'Our apartment is central, so we walk to most places.', NULL, 'Căn hộ của chúng tôi nằm ngay trung tâm, nên chúng tôi đi bộ đến hầu hết các nơi.', '{"wordId":"central","ukIpa":"/ˈsentrəl/","usIpa":"/ˈsentrəl/","cefr":"B1","topic":"city","senses":[{"pos":"adj.","en":"in or near the middle of a place","vi":"ở trung tâm; thuộc về trung tâm"},{"pos":"adj.","en":"extremely important or essential to something","vi":"quan trọng nhất; cốt lõi; thiết yếu"}],"examples":[{"en":"Our apartment is central, so we walk to most places.","vi":"Căn hộ của chúng tôi nằm ngay trung tâm, nên chúng tôi đi bộ đến hầu hết các nơi.","audioKind":"ex"},{"en":"Access to reliable information is central to helping citizens make informed decisions about public health.","vi":"Việc tiếp cận thông tin đáng tin cậy đóng vai trò cốt lõi trong việc giúp người dân đưa ra các quyết định sáng suốt về y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"central location","vi":"vị trí trung tâm"},{"en":"central government","vi":"chính quyền trung ương"},{"en":"a central role","vi":"vai trò cốt lõi"},{"en":"central to","vi":"cốt lõi đối với; tối quan trọng đối với"}],"wordFamily":["centrally (adv.)","centre (n.)","centralise (v.)","centralisation (n.)"],"synonyms":[],"antonyms":["peripheral"],"tipVi":"central to biểu thị \"đối với... là tối quan trọng\", giới từ đi kèm là to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suburb', 'en-b1-40', 'suburb', '/ˈsʌbɜːrb/', 'B1', 'vùng ngoại ô; khu dân cư ngoại ô', 'n.', 'suburban (adj.), suburbanisation (n.)', NULL, 'Thường dùng cụm in the suburbs; suburb không đồng nghĩa với vùng nông thôn.', 'They moved to a quiet suburb near the river.', NULL, 'Họ đã chuyển đến một khu ngoại ô yên tĩnh gần con sông.', '{"wordId":"suburb","ukIpa":"/ˈsʌbɜːb/","usIpa":"/ˈsʌbɜːrb/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"A mainly residential area outside a city''s central part.","vi":"vùng ngoại ô; khu dân cư ngoại ô"}],"examples":[{"en":"They moved to a quiet suburb near the river.","vi":"Họ đã chuyển đến một khu ngoại ô yên tĩnh gần con sông.","audioKind":"ex"},{"en":"Reliable public transport can help residents of distant suburbs reach employment opportunities in the city centre.","vi":"Giao thông công cộng đáng tin cậy có thể giúp cư dân ở các vùng ngoại ô xa xôi tiếp cận các cơ hội việc làm ở trung tâm thành phố.","audioKind":"ex2"}],"collocations":[{"en":"a residential suburb","vi":"khu dân cư ngoại ô"},{"en":"live in the suburbs","vi":"sống ở ngoại ô"},{"en":"a leafy suburb","vi":"vùng ngoại ô nhiều cây xanh"}],"wordFamily":["suburban (adj.)","suburbanisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng cụm in the suburbs; suburb không đồng nghĩa với vùng nông thôn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_corridor', 'en-b1-40', 'corridor', '/ˈkɔːrɪdɔːr/', 'B1', 'hành lang; lối đi; hành lang di chuyển; dải đất nối liền', 'n.', NULL, 'Đồng nghĩa: passage, hallway', 'Vừa chỉ hành lang trong tòa nhà, vừa chỉ dải đất hẹp nối liền các khu vực.', 'Her footsteps echoed along the empty corridor after class.', NULL, 'Tiếng bước chân của cô ấy vang vọng dọc theo hành lang vắng lặng sau giờ học.', '{"wordId":"corridor","ukIpa":"/ˈkɒrɪdɔː/","usIpa":"/ˈkɔːrɪdɔːr/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"a long passage connecting rooms inside a building","vi":"hành lang; lối đi"},{"pos":"n.","en":"a strip of land connecting areas for movement or transport","vi":"hành lang di chuyển; dải đất nối liền"}],"examples":[{"en":"Her footsteps echoed along the empty corridor after class.","vi":"Tiếng bước chân của cô ấy vang vọng dọc theo hành lang vắng lặng sau giờ học.","audioKind":"ex"},{"en":"Wildlife corridors allow animals to move safely between habitats that roads and urban development have separated.","vi":"Các hành lang động vật hoang dã cho phép các loài động vật di chuyển an toàn giữa các môi trường sống bị chia cắt bởi đường sá và sự phát triển đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a narrow corridor","vi":"một hành lang hẹp"},{"en":"along the corridor","vi":"dọc theo hành lang"},{"en":"a wildlife corridor","vi":"hành lang sinh thái động vật hoang dã"},{"en":"a transport corridor","vi":"hành lang giao thông"}],"wordFamily":[],"synonyms":["passage","hallway"],"antonyms":[],"tipVi":"Vừa chỉ hành lang trong tòa nhà, vừa chỉ dải đất hẹp nối liền các khu vực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chimney', 'en-b1-40', 'chimney', '/ˈtʃɪmni/', 'B1', 'ống khói', 'n.', NULL, NULL, 'Dạng số nhiều thêm -s trực tiếp thành chimneys, không đổi y thành i.', 'Smoke rose from the chimney into the cold evening air.', NULL, 'Khói từ ống khói bay lên bầu trời buổi chiều lạnh giá.', '{"wordId":"chimney","ukIpa":"/ˈtʃɪmni/","usIpa":"/ˈtʃɪmni/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"a structure that carries smoke from a fire outside","vi":"ống khói"}],"examples":[{"en":"Smoke rose from the chimney into the cold evening air.","vi":"Khói từ ống khói bay lên bầu trời buổi chiều lạnh giá.","audioKind":"ex"},{"en":"Installing filters in factory chimneys can reduce the amount of harmful particles released into the atmosphere.","vi":"Việc lắp đặt các bộ lọc ở ống khói nhà máy có thể làm giảm lượng hạt độc hại thải vào bầu khí quyển.","audioKind":"ex2"}],"collocations":[{"en":"factory chimney","vi":"ống khói nhà máy"},{"en":"chimney pot","vi":"đầu ống khói"},{"en":"chimney sweep","vi":"thợ quét ống khói"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều thêm -s trực tiếp thành chimneys, không đổi y thành i.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fountain', 'en-b1-40', 'fountain', '/ˈfaʊntən/', 'B1', 'đài phun nước; vòi nước uống công cộng', 'n.', NULL, NULL, 'drinking fountain là vòi nước uống công cộng; fountain pen là bút máy.', 'Children watched the fountain sparkle in the afternoon sunlight.', NULL, 'Lũ trẻ ngắm nhìn đài phun nước lấp lánh dưới ánh nắng buổi chiều.', '{"wordId":"fountain","ukIpa":"/ˈfaʊntɪn/","usIpa":"/ˈfaʊntən/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"a structure that sends water into the air","vi":"đài phun nước"},{"pos":"n.","en":"a device supplying a stream of water for drinking","vi":"vòi nước uống công cộng"}],"examples":[{"en":"Children watched the fountain sparkle in the afternoon sunlight.","vi":"Lũ trẻ ngắm nhìn đài phun nước lấp lánh dưới ánh nắng buổi chiều.","audioKind":"ex"},{"en":"A fountain can make a public square more attractive, although its maintenance requires water and energy.","vi":"Đài phun nước có thể làm cho quảng trường công cộng thêm phần thu hút, mặc dù việc bảo trì nó cần tiêu tốn nước và năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"drinking fountain","vi":"vòi nước uống"},{"en":"ornamental fountain","vi":"đài phun nước trang trí"},{"en":"fountain pen","vi":"bút máy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"drinking fountain là vòi nước uống công cộng; fountain pen là bút máy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hallway', 'en-b1-40', 'hallway', '/ˈhɔːlweɪ/', 'B1', 'hành lang; tiền sảnh', 'n.', NULL, 'Đồng nghĩa: corridor, hall', 'Từ này có thể chỉ cả sảnh chính ở cửa ra vào lẫn hành lang nối các phòng với nhau trong tòa nhà.', 'Please leave your muddy boots in the hallway.', NULL, 'Làm ơn để những chiếc ủng dính bùn của bạn ngoài sảnh vào.', '{"wordId":"hallway","ukIpa":"/ˈhɔːlweɪ/","usIpa":"/ˈhɔːlweɪ/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"A passage inside a building or space by its entrance","vi":"hành lang; tiền sảnh"}],"examples":[{"en":"Please leave your muddy boots in the hallway.","vi":"Làm ơn để những chiếc ủng dính bùn của bạn ngoài sảnh vào.","audioKind":"ex"},{"en":"Wide hallways and accessible entrances make public buildings easier to navigate for people with limited mobility.","vi":"Hành lang rộng rãi và lối vào dễ tiếp cận giúp cho những người có khả năng vận động hạn chế dễ dàng di chuyển trong các tòa nhà công cộng hơn.","audioKind":"ex2"}],"collocations":[{"en":"narrow hallway","vi":"hành lang hẹp"},{"en":"entrance hallway","vi":"tiền sảnh lối vào"},{"en":"down the hallway","vi":"dọc theo hành lang"}],"wordFamily":[],"synonyms":["corridor","hall"],"antonyms":[],"tipVi":"Từ này có thể chỉ cả sảnh chính ở cửa ra vào lẫn hành lang nối các phòng với nhau trong tòa nhà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_open-air', 'en-b1-40', 'open-air', '/ˌoʊpən ˈer/', 'B1', 'ngoài trời; lộ thiên', 'adj.', NULL, 'Đồng nghĩa: outdoor · Trái nghĩa: indoor', 'Tính từ dùng có dấu gạch nối; in the open air có nghĩa là ở ngoài trời.', 'We watched a film at an open-air cinema last night.', NULL, 'Tối qua chúng tôi đã xem phim tại một rạp chiếu phim ngoài trời.', '{"wordId":"open-air","ukIpa":"/ˌəʊpən ˈeə/","usIpa":"/ˌoʊpən ˈer/","cefr":"B1","topic":"city","senses":[{"pos":"adj.","en":"taking place or located outside, without a roof","vi":"ngoài trời; lộ thiên"}],"examples":[{"en":"We watched a film at an open-air cinema last night.","vi":"Tối qua chúng tôi đã xem phim tại một rạp chiếu phim ngoài trời.","audioKind":"ex"},{"en":"Open-air markets can attract visitors while providing affordable trading spaces for small local businesses.","vi":"Các chợ ngoài trời có thể thu hút du khách đồng thời cung cấp không gian giao thương với giá cả phải chăng cho các tiểu thương địa phương.","audioKind":"ex2"}],"collocations":[{"en":"open-air market","vi":"chợ ngoài trời"},{"en":"open-air concert","vi":"buổi hòa nhạc ngoài trời"},{"en":"open-air theatre","vi":"nhà hát ngoài trời"}],"wordFamily":[],"synonyms":["outdoor"],"antonyms":["indoor"],"tipVi":"Tính từ dùng có dấu gạch nối; in the open air có nghĩa là ở ngoài trời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_basement', 'en-b1-40', 'basement', '/ˈbeɪsmənt/', 'B1', 'tầng hầm; phòng dưới mặt đất', 'n.', NULL, NULL, 'basement có thể dùng làm không gian ở; cellar thường chỉ hầm chứa đồ.', 'We keep our bicycles in the basement during winter.', NULL, 'Chúng tôi cất xe đạp ở dưới tầng hầm vào mùa đông.', '{"wordId":"basement","ukIpa":"/ˈbeɪsmənt/","usIpa":"/ˈbeɪsmənt/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"A room or floor below ground level in a building.","vi":"tầng hầm; phòng dưới mặt đất"}],"examples":[{"en":"We keep our bicycles in the basement during winter.","vi":"Chúng tôi cất xe đạp ở dưới tầng hầm vào mùa đông.","audioKind":"ex"},{"en":"Converting unused basement space into community facilities can help densely populated neighbourhoods accommodate more activities.","vi":"Việc chuyển đổi không gian tầng hầm không sử dụng thành các tiện ích cộng đồng có thể giúp các khu phố đông dân cư đáp ứng nhiều hoạt động hơn.","audioKind":"ex2"}],"collocations":[{"en":"in the basement","vi":"ở dưới tầng hầm"},{"en":"basement flat","vi":"căn hộ tầng hầm"},{"en":"basement storage","vi":"kho chứa ở tầng hầm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"basement có thể dùng làm không gian ở; cellar thường chỉ hầm chứa đồ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sidewalk', 'en-b1-40', 'sidewalk', '/ˈsaɪdwɔːk/', 'B1', 'lối đi lát đá bên cạnh đường dành cho người đi bộ', 'n.', NULL, 'Đồng nghĩa: pavement', 'sidewalk theo tiếng Mỹ tương đương với pavement theo tiếng Anh-Anh.', 'Please keep your bicycle off the crowded sidewalk.', NULL, 'Xin đừng lái xe đạp lên phần vỉa hè đang đông đúc người qua lại.', '{"wordId":"sidewalk","ukIpa":"/ˈsaɪdwɔːk/","usIpa":"/ˈsaɪdwɔːk/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"A paved path beside a street for pedestrians.","vi":"lối đi lát đá bên cạnh đường dành cho người đi bộ"}],"examples":[{"en":"Please keep your bicycle off the crowded sidewalk.","vi":"Xin đừng lái xe đạp lên phần vỉa hè đang đông đúc người qua lại.","audioKind":"ex"},{"en":"Planting trees along sidewalks can provide shade for pedestrians and reduce summer temperatures in cities.","vi":"Việc trồng cây dọc theo các vỉa hè có thể tạo bóng mát cho người đi bộ và giảm nhiệt độ mùa hè trong các thành phố.","audioKind":"ex2"}],"collocations":[{"en":"crowded sidewalk","vi":"vỉa hè đông đúc"},{"en":"sidewalk café","vi":"quán cà phê vỉa hè"},{"en":"sidewalk repair","vi":"sửa chữa vỉa hè"}],"wordFamily":[],"synonyms":["pavement"],"antonyms":[],"tipVi":"sidewalk theo tiếng Mỹ tương đương với pavement theo tiếng Anh-Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_location', 'en-b1-40', 'location', '/loʊˈkeɪʃən/', 'B1', 'vị trí; địa điểm; địa điểm ngoại cảnh (quay phim)', 'n.', 'locate (v.), located (adj.), relocate (v.)', 'Đồng nghĩa: place, position, site', '"On location" có nghĩa là quay phim thực tế bên ngoài trường quay.', 'This cafe has a lovely location beside the river.', NULL, 'Quán cà phê này có một vị trí tuyệt đẹp bên dòng sông.', '{"wordId":"location","ukIpa":"/ləʊˈkeɪʃən/","usIpa":"/loʊˈkeɪʃən/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"The place where something is or where something happens.","vi":"vị trí; địa điểm"},{"pos":"n.","en":"A place outside a studio where filming takes place.","vi":"địa điểm ngoại cảnh (quay phim)"}],"examples":[{"en":"This cafe has a lovely location beside the river.","vi":"Quán cà phê này có một vị trí tuyệt đẹp bên dòng sông.","audioKind":"ex"},{"en":"The location of affordable housing strongly influences residents'' access to schools, healthcare, and employment opportunities.","vi":"Vị trí của nhà ở xã hội ảnh hưởng mạnh mẽ đến khả năng tiếp cận trường học, dịch vụ y tế và cơ hội việc làm của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"central location","vi":"vị trí trung tâm"},{"en":"ideal location","vi":"địa điểm lý tưởng"},{"en":"on location","vi":"quay ngoại cảnh"},{"en":"exact location","vi":"vị trí chính xác"}],"wordFamily":["locate (v.)","located (adj.)","relocate (v.)"],"synonyms":["place","position","site"],"antonyms":[],"tipVi":"\"On location\" có nghĩa là quay phim thực tế bên ngoài trường quay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_roundabout', 'en-b1-40', 'roundabout', '/ˈraʊndəbaʊt/', 'B1', 'vòng xuyến; bùng binh; đảo giao thông; vòng vo; quanh co; gián tiếp; mâm xoay (trò chơi trẻ em)', 'n.', NULL, NULL, 'Dùng làm tính từ để chỉ sự không trực tiếp, chẳng hạn như a roundabout answer.', 'Take the second exit at the roundabout near the park.', NULL, 'Hãy rẽ ở lối ra thứ hai tại bùng binh gần công viên.', '{"wordId":"roundabout","ukIpa":"/ˈraʊndəbaʊt/","usIpa":"/ˈraʊndəbaʊt/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"A circular road junction where traffic travels around a central island.","vi":"vòng xuyến; bùng binh; đảo giao thông"},{"pos":"adj.","en":"Not following the most direct route or way of speaking.","vi":"vòng vo; quanh co; gián tiếp"},{"pos":"n.","en":"A rotating platform that children sit or stand on.","vi":"mâm xoay (trò chơi trẻ em)"}],"examples":[{"en":"Take the second exit at the roundabout near the park.","vi":"Hãy rẽ ở lối ra thứ hai tại bùng binh gần công viên.","audioKind":"ex"},{"en":"Replacing a busy junction with a roundabout may improve traffic flow and reduce serious collisions.","vi":"Việc thay thế một ngã tư bận rộn bằng một vòng xuyến có thể cải thiện lưu lượng giao thông và giảm thiểu các vụ va chạm nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"at the roundabout","vi":"tại vòng xuyến"},{"en":"take a roundabout route","vi":"đi đường vòng"},{"en":"in a roundabout way","vi":"theo một cách vòng vo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng làm tính từ để chỉ sự không trực tiếp, chẳng hạn như a roundabout answer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_balcony', 'en-b1-40', 'balcony', '/ˈbælkəni/', 'B1', 'ban công; hiên nhà; tầng lửng; tầng ban công (trong nhà hát)', 'n.', NULL, NULL, 'Dùng ''on the balcony'' để chỉ ở trên ban công, không dùng ''in''.', 'She grows herbs in small pots on her balcony.', NULL, 'Cô ấy trồng các loại thảo mộc trong những chiếc chậu nhỏ ở ban công nhà mình.', '{"wordId":"balcony","ukIpa":"/ˈbælkəni/","usIpa":"/ˈbælkəni/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"A raised outdoor platform attached to a building, with a railing.","vi":"ban công; hiên nhà"},{"pos":"n.","en":"An upper level of seats in a theatre.","vi":"tầng lửng; tầng ban công (trong nhà hát)"}],"examples":[{"en":"She grows herbs in small pots on her balcony.","vi":"Cô ấy trồng các loại thảo mộc trong những chiếc chậu nhỏ ở ban công nhà mình.","audioKind":"ex"},{"en":"Apartments with a balcony offer residents valuable outdoor space, particularly in cities where public gardens are scarce.","vi":"Những căn hộ có ban công đem lại không gian ngoài trời quý giá cho cư dân, đặc biệt là ở các thành phố lớn nơi hiếm có công viên.","audioKind":"ex2"}],"collocations":[{"en":"on the balcony","vi":"ở ngoài ban công"},{"en":"a private balcony","vi":"ban công riêng"},{"en":"balcony seats","vi":"ghế khu vực ban công"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng ''on the balcony'' để chỉ ở trên ban công, không dùng ''in''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_storey', 'en-b1-40', 'storey', '/ˈstɔːri/', 'B1', 'tầng của một tòa nhà', 'n.', NULL, 'Đồng nghĩa: floor', 'Trong tiếng Anh-Anh, số nhiều của storey là storeys; trong tiếng Anh-Mỹ thường được viết là story.', 'Their new house has two storeys and a small garden.', NULL, 'Ngôi nhà mới của họ có hai tầng và một khu vườn nhỏ.', '{"wordId":"storey","ukIpa":"/ˈstɔːri/","usIpa":"/ˈstɔːri/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"A level of a building.","vi":"tầng của một tòa nhà"}],"examples":[{"en":"Their new house has two storeys and a small garden.","vi":"Ngôi nhà mới của họ có hai tầng và một khu vườn nhỏ.","audioKind":"ex"},{"en":"Buildings with many storeys can accommodate more residents without requiring additional land in crowded cities.","vi":"Các tòa nhà nhiều tầng có thể đáp ứng chỗ ở cho nhiều cư dân hơn mà không đòi hỏi thêm diện tích đất ở những thành phố chật chội.","audioKind":"ex2"}],"collocations":[{"en":"a two-storey house","vi":"ngôi nhà hai tầng"},{"en":"the top storey","vi":"tầng trên cùng"},{"en":"a multi-storey building","vi":"tòa nhà nhiều tầng"}],"wordFamily":[],"synonyms":["floor"],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, số nhiều của storey là storeys; trong tiếng Anh-Mỹ thường được viết là story.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_neighboring', 'en-b1-40', 'neighboring', '/ˈneɪbərɪŋ/', 'B1', 'lân cận; giáp ranh; láng giềng', 'adj.', 'neighbor (n.), neighborhood (n.), neighborly (adj.)', 'Đồng nghĩa: nearby, adjacent · Trái nghĩa: distant', 'Đây là cách viết kiểu Mỹ; kiểu Anh là neighbouring, thường đứng trước danh từ.', 'We borrowed a ladder from the neighboring farm.', NULL, 'Chúng tôi đã mượn một cái thang từ trang trại lân cận.', '{"wordId":"neighboring","ukIpa":"/ˈneɪbərɪŋ/","usIpa":"/ˈneɪbərɪŋ/","cefr":"B1","topic":"city","senses":[{"pos":"adj.","en":"located next to or near another place","vi":"lân cận; giáp ranh; láng giềng"}],"examples":[{"en":"We borrowed a ladder from the neighboring farm.","vi":"Chúng tôi đã mượn một cái thang từ trang trại lân cận.","audioKind":"ex"},{"en":"Neighboring countries can reduce environmental damage by coordinating river management and sharing information about industrial pollution.","vi":"Các quốc gia láng giềng có thể giảm thiểu tổn hại môi trường bằng cách phối hợp quản lý sông ngòi và chia sẻ thông tin về ô nhiễm công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"neighboring countries","vi":"các quốc gia láng giềng"},{"en":"neighboring villages","vi":"các ngôi làng lân cận"},{"en":"neighboring areas","vi":"các khu vực lân cận"}],"wordFamily":["neighbor (n.)","neighborhood (n.)","neighborly (adj.)"],"synonyms":["nearby","adjacent"],"antonyms":["distant"],"tipVi":"Đây là cách viết kiểu Mỹ; kiểu Anh là neighbouring, thường đứng trước danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pipe', 'en-b1-40', 'pipe', '/paɪp/', 'B1', 'ống dẫn; đường ống; dẫn (nước hoặc khí) qua ống; tẩu thuốc', 'n.', 'piping (n.)', 'Đồng nghĩa: tube', 'Pipe có thể làm động từ: pipe water to nghĩa là dẫn nước đến một nơi nào đó bằng đường ống.', 'Water dripped from a broken pipe under the sink.', NULL, 'Nước rỉ ra từ một đoạn ống bị vỡ ở dưới bồn rửa chén.', '{"wordId":"pipe","ukIpa":"/paɪp/","usIpa":"/paɪp/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"A hollow tube that carries liquid or gas.","vi":"ống dẫn; đường ống"},{"pos":"v.","en":"To carry liquid or gas through pipes.","vi":"dẫn (nước hoặc khí) qua ống"},{"pos":"n.","en":"A small bowl with a tube used for smoking tobacco.","vi":"tẩu thuốc"}],"examples":[{"en":"Water dripped from a broken pipe under the sink.","vi":"Nước rỉ ra từ một đoạn ống bị vỡ ở dưới bồn rửa chén.","audioKind":"ex"},{"en":"Replacing damaged water pipes can help cities conserve resources and ensure a reliable supply of clean drinking water.","vi":"Việc thay thế các đường ống nước bị hư hỏng có thể giúp các thành phố tiết kiệm tài nguyên và đảm bảo nguồn cung cấp nước uống sạch đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"water pipe","vi":"ống nước"},{"en":"a burst pipe","vi":"đường ống bị vỡ"},{"en":"pipe water to","vi":"dẫn nước đến đâu bằng đường ống"}],"wordFamily":["piping (n.)"],"synonyms":["tube"],"antonyms":[],"tipVi":"Pipe có thể làm động từ: pipe water to nghĩa là dẫn nước đến một nơi nào đó bằng đường ống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_zone', 'en-b1-40', 'zone', '/zoʊn/', 'B1', 'vùng; khu vực; quy hoạch vùng; chia khu', 'n.', 'zoning (n.)', 'Đồng nghĩa: area, district', 'zone nhấn mạnh khu vực có mục đích hoặc đặc điểm cụ thể; area mang nghĩa rộng hơn.', 'Cars are not allowed inside this quiet pedestrian zone.', NULL, 'Ô tô không được phép đi vào khu vực dành riêng cho người đi bộ yên tĩnh này.', '{"wordId":"zone","ukIpa":"/zəʊn/","usIpa":"/zoʊn/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"An area with a particular purpose, feature, or condition.","vi":"vùng; khu vực"},{"pos":"v.","en":"Officially assign land to a particular use.","vi":"quy hoạch vùng; chia khu"}],"examples":[{"en":"Cars are not allowed inside this quiet pedestrian zone.","vi":"Ô tô không được phép đi vào khu vực dành riêng cho người đi bộ yên tĩnh này.","audioKind":"ex"},{"en":"Creating a low-emission zone can reduce air pollution, provided that affordable public transport is available.","vi":"Việc tạo ra một khu vực phát thải thấp có thể làm giảm ô nhiễm không khí, với điều kiện là có phương tiện giao thông công cộng giá cả phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"a pedestrian zone","vi":"khu vực dành cho người đi bộ"},{"en":"a time zone","vi":"múi giờ"},{"en":"a residential zone","vi":"khu dân cư"},{"en":"zone land for housing","vi":"quy hoạch đất làm nhà ở"}],"wordFamily":["zoning (n.)"],"synonyms":["area","district"],"antonyms":[],"tipVi":"zone nhấn mạnh khu vực có mục đích hoặc đặc điểm cụ thể; area mang nghĩa rộng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ceiling', 'en-b1-40', 'ceiling', '/ˈsiːlɪŋ/', 'B1', 'trần nhà; mức giới hạn cao nhất cho phép', 'n.', NULL, NULL, 'ceiling chỉ mặt phẳng phía trên bên trong phòng; còn roof chỉ phần mái ở bên ngoài công trình.', 'A small spider was crawling across the ceiling.', NULL, 'Một con nhện nhỏ đang bò ngang qua trần nhà.', '{"wordId":"ceiling","ukIpa":"/ˈsiːlɪŋ/","usIpa":"/ˈsiːlɪŋ/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"the inside surface at the top of a room","vi":"trần nhà"},{"pos":"n.","en":"the highest amount or level that is allowed","vi":"mức giới hạn cao nhất cho phép"}],"examples":[{"en":"A small spider was crawling across the ceiling.","vi":"Một con nhện nhỏ đang bò ngang qua trần nhà.","audioKind":"ex"},{"en":"A ceiling on annual rent increases could protect tenants, although it might discourage investment in housing.","vi":"Việc áp trần đối với mức tăng tiền thuê nhà hàng năm có thể bảo vệ người thuê nhà, mặc dù nó có thể làm nản lòng các nhà đầu tư vào lĩnh vực nhà ở.","audioKind":"ex2"}],"collocations":[{"en":"high ceiling","vi":"trần nhà cao"},{"en":"ceiling fan","vi":"quạt trần"},{"en":"price ceiling","vi":"giá trần"},{"en":"set a ceiling on","vi":"đặt ra mức giới hạn cho"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"ceiling chỉ mặt phẳng phía trên bên trong phòng; còn roof chỉ phần mái ở bên ngoài công trình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_site', 'en-b1-40', 'site', '/saɪt/', 'B1', 'địa điểm; công trường; khu di tích; trang web; website; xác định vị trí; xây dựng ở', 'n.', NULL, 'Đồng nghĩa: location, website', 'site chỉ địa điểm hoặc trang web; sight chỉ thị lực hoặc cảnh quan, hai từ này phát âm giống nhau.', 'Workers put a fence around the building site.', NULL, 'Các công nhân đã dựng hàng rào xung quanh công trường xây dựng.', '{"wordId":"site","ukIpa":"/saɪt/","usIpa":"/saɪt/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"A place where something is built, happens, or once existed.","vi":"địa điểm; công trường; khu di tích"},{"pos":"n.","en":"A collection of connected web pages.","vi":"trang web; website"},{"pos":"v.","en":"Place or build something in a particular location.","vi":"xác định vị trí; xây dựng ở"}],"examples":[{"en":"Workers put a fence around the building site.","vi":"Các công nhân đã dựng hàng rào xung quanh công trường xây dựng.","audioKind":"ex"},{"en":"The proposed hospital site is close to public transport, making healthcare more accessible to residents.","vi":"Khu đất dự kiến xây dựng bệnh viện nằm gần các phương tiện giao thông công cộng, giúp người dân tiếp cận dịch vụ y tế dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"building site","vi":"công trường xây dựng"},{"en":"historic site","vi":"di tích lịch sử"},{"en":"on site","vi":"tại hiện trường"},{"en":"site a factory","vi":"chọn địa điểm đặt nhà máy"}],"wordFamily":[],"synonyms":["location","website"],"antonyms":[],"tipVi":"site chỉ địa điểm hoặc trang web; sight chỉ thị lực hoặc cảnh quan, hai từ này phát âm giống nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lane', 'en-b1-40', 'lane', '/leɪn/', 'B1', 'làn đường; đường nhỏ; ngõ nhỏ; làn bơi; đường chạy', 'n.', NULL, NULL, 'lane chỉ một làn đường nhỏ; toàn bộ con đường thường gọi là road.', 'Our bus moved into the lane beside the pavement.', NULL, 'Xe buýt của chúng tôi chuyển vào làn đường bên cạnh vỉa hè.', '{"wordId":"lane","ukIpa":"/leɪn/","usIpa":"/leɪn/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"a strip of road for one line of vehicles","vi":"làn đường"},{"pos":"n.","en":"a narrow road, especially in the countryside","vi":"đường nhỏ; ngõ nhỏ"},{"pos":"n.","en":"a marked strip for one swimmer or runner","vi":"làn bơi; đường chạy"}],"examples":[{"en":"Our bus moved into the lane beside the pavement.","vi":"Xe buýt của chúng tôi chuyển vào làn đường bên cạnh vỉa hè.","audioKind":"ex"},{"en":"Dedicated cycle lanes can improve road safety and encourage more residents to travel by bicycle.","vi":"Các làn đường dành riêng cho xe đạp có thể cải thiện an toàn giao thông và khuyến khích nhiều cư dân đi lại bằng xe đạp hơn.","audioKind":"ex2"}],"collocations":[{"en":"cycle lane","vi":"làn đường dành cho xe đạp"},{"en":"bus lane","vi":"làn đường xe buýt"},{"en":"change lanes","vi":"đổi làn đường"},{"en":"country lane","vi":"đường làng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"lane chỉ một làn đường nhỏ; toàn bộ con đường thường gọi là road.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_district', 'en-b1-40', 'district', '/ˈdɪstrɪkt/', 'B1', 'quận; khu vực; vùng', 'n.', NULL, 'Đồng nghĩa: area, zone', 'Có thể chỉ phân chia hành chính, cũng có thể chỉ khu vực đô thị có chức năng cụ thể.', 'We found a small bakery in the old market district.', NULL, 'Chúng tôi tìm thấy một tiệm bánh nhỏ ở khu chợ cổ.', '{"wordId":"district","ukIpa":"/ˈdɪstrɪkt/","usIpa":"/ˈdɪstrɪkt/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"An area defined by its features or official boundaries.","vi":"quận; khu vực; vùng"}],"examples":[{"en":"We found a small bakery in the old market district.","vi":"Chúng tôi tìm thấy một tiệm bánh nhỏ ở khu chợ cổ.","audioKind":"ex"},{"en":"Improving public transport in suburban districts can reduce car dependence and widen access to employment.","vi":"Việc cải thiện giao thông công cộng ở các khu vực ngoại ô có thể giảm sự phụ thuộc vào ô tô và mở rộng khả năng tiếp cận việc làm.","audioKind":"ex2"}],"collocations":[{"en":"residential district","vi":"khu dân cư"},{"en":"business district","vi":"khu thương mại"},{"en":"school district","vi":"huyện học đường"},{"en":"electoral district","vi":"khu vực bầu cử"}],"wordFamily":[],"synonyms":["area","zone"],"antonyms":[],"tipVi":"Có thể chỉ phân chia hành chính, cũng có thể chỉ khu vực đô thị có chức năng cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brick', 'en-b1-40', 'brick', '/brɪk/', 'B1', 'viên gạch; gạch', 'n.', 'bricklayer (n.), brickwork (n.)', NULL, 'Viên gạch đơn lẻ là danh từ đếm được; khi dùng làm vật liệu xây dựng tổng hợp thì có thể không đếm được.', 'One loose brick fell out of the garden wall.', NULL, 'Một viên gạch bị lỏng đã rơi ra từ bức tường vườn.', '{"wordId":"brick","ukIpa":"/brɪk/","usIpa":"/brɪk/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"A hard rectangular block used for building walls and houses.","vi":"viên gạch; gạch"}],"examples":[{"en":"One loose brick fell out of the garden wall.","vi":"Một viên gạch bị lỏng đã rơi ra từ bức tường vườn.","audioKind":"ex"},{"en":"Reusing brick from demolished buildings can reduce construction waste and preserve the character of older neighbourhoods.","vi":"Việc tái sử dụng gạch từ các tòa nhà bị phá dỡ có thể làm giảm chất thải xây dựng và giữ lại nét đặc trưng của các khu9 phố cũ.","audioKind":"ex2"}],"collocations":[{"en":"brick wall","vi":"tường gạch"},{"en":"lay bricks","vi":"xếp gạch"},{"en":"red brick","vi":"gạch đỏ"}],"wordFamily":["bricklayer (n.)","brickwork (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Viên gạch đơn lẻ là danh từ đếm được; khi dùng làm vật liệu xây dựng tổng hợp thì có thể không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_escalator', 'en-b1-40', 'escalator', '/ˈeskəleɪtər/', 'B1', 'thang cuốn', 'n.', NULL, NULL, 'escalator là thang cuốn; lift là thang máy.', 'Hold the handrail while you ride the escalator upstairs.', NULL, 'Hãy bám vào tay vịn khi bạn đi thang cuốn lên lầu.', '{"wordId":"escalator","ukIpa":"/ˈeskəleɪtə/","usIpa":"/ˈeskəleɪtər/","cefr":"B1","topic":"city","senses":[{"pos":"n.","en":"moving stairs that carry people between floors","vi":"thang cuốn"}],"examples":[{"en":"Hold the handrail while you ride the escalator upstairs.","vi":"Hãy bám vào tay vịn khi bạn đi thang cuốn lên lầu.","audioKind":"ex"},{"en":"Although escalators improve passenger flow in stations, lifts are essential for travellers who use wheelchairs.","vi":"Mặc dù thang cuốn cải thiện luồng hành khách ở các nhà ga, nhưng thang máy là thứ thiết yếu đối với những du khách sử dụng xe lăn.","audioKind":"ex2"}],"collocations":[{"en":"take the escalator","vi":"đi thang cuốn"},{"en":"an upward escalator","vi":"thang cuốn đi lên"},{"en":"escalator handrail","vi":"tay vịn thang cuốn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"escalator là thang cuốn; lift là thang máy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_40_1', 'en-b1-40', 'Cách dùng “brick” (n.) — viên gạch; gạch', 'brick wall  ·  lay bricks  ·  red brick', 'Viên gạch đơn lẻ là danh từ đếm được; khi dùng làm vật liệu xây dựng tổng hợp thì có thể không đếm được.', 'Họ từ (Word Family): bricklayer (n.), brickwork (n.)', '[{"hanzi":"One loose brick fell out of the garden wall.","pinyin":"","meaning":"Một viên gạch bị lỏng đã rơi ra từ bức tường vườn."},{"hanzi":"Reusing brick from demolished buildings can reduce construction waste and preserve the character of older neighbourhoods.","pinyin":"","meaning":"Việc tái sử dụng gạch từ các tòa nhà bị phá dỡ có thể làm giảm chất thải xây dựng và giữ lại nét đặc trưng của các khu9 phố cũ."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_40_2', 'en-b1-40', 'Cách dùng “storey” (n.) — tầng của một tòa nhà', 'a two-storey house  ·  the top storey  ·  a multi-storey building', 'Trong tiếng Anh-Anh, số nhiều của storey là storeys; trong tiếng Anh-Mỹ thường được viết là story.', 'Đồng nghĩa: floor', '[{"hanzi":"Their new house has two storeys and a small garden.","pinyin":"","meaning":"Ngôi nhà mới của họ có hai tầng và một khu vườn nhỏ."},{"hanzi":"Buildings with many storeys can accommodate more residents without requiring additional land in crowded cities.","pinyin":"","meaning":"Các tòa nhà nhiều tầng có thể đáp ứng chỗ ở cho nhiều cư dân hơn mà không đòi hỏi thêm diện tích đất ở những thành phố chật chội."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_40_3', 'en-b1-40', 'Cách dùng “site” (n.) — địa điểm; công trường; khu di tích', 'building site  ·  historic site  ·  on site', 'site chỉ địa điểm hoặc trang web; sight chỉ thị lực hoặc cảnh quan, hai từ này phát âm giống nhau.', 'Đồng nghĩa: location, website', '[{"hanzi":"Workers put a fence around the building site.","pinyin":"","meaning":"Các công nhân đã dựng hàng rào xung quanh công trường xây dựng."},{"hanzi":"The proposed hospital site is close to public transport, making healthcare more accessible to residents.","pinyin":"","meaning":"Khu đất dự kiến xây dựng bệnh viện nằm gần các phương tiện giao thông công cộng, giúp người dân tiếp cận dịch vụ y tế dễ dàng hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_40_4', 'en-b1-40', 'Cách dùng “block” (n.) — khối; tảng', 'a block of flats  ·  block the entrance  ·  a block of ice', 'Cụm a block of flats chỉ các tòa nhà chung cư, là cách diễn đạt rất phổ biến trong tiếng Anh-Anh.', 'Họ từ (Word Family): blockage (n.), blocked (adj.)', '[{"hanzi":"The sculptor carved a bird from a block of wood.","pinyin":"","meaning":"Người thợ điêu khắc đã tạc một chú chim từ một khúc gỗ."},{"hanzi":"Poorly parked vehicles can block access to public buildings, creating difficulties for wheelchair users.","pinyin":"","meaning":"Phương tiện đỗ không đúng nơi quy định có thể cản trở lối vào các tòa nhà công cộng, gây khó khăn cho người dùng xe lăn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_40_1', 'en-b1-40', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_1_1', 'ten_b1_40_1', 'block', 'The sculptor carved a bird from a block of wood.', 'The sculptor carved a bird from a block of wood.', '/blɑːk/', 'Người thợ điêu khắc đã tạc một chú chim từ một khúc gỗ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_1_2', 'ten_b1_40_1', 'skyscraper', 'The skyscraper cast a long shadow across the park.', 'The skyscraper cast a long shadow across the park.', '/ˈskaɪskreɪpər/', 'Tòa nhà chọc trời đổ bóng dài across công viên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_1_3', 'ten_b1_40_1', 'pavement', 'We walked along the pavement beside the busy road.', 'We walked along the pavement beside the busy road.', '/ˈpeɪvmənt/', 'Chúng tôi đi bộ dọc theo vỉa hè cạnh con đường đông đúc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_1_4', 'ten_b1_40_1', 'footbridge', 'We crossed the wooden footbridge above the stream.', 'We crossed the wooden footbridge above the stream.', '/ˈfʊtbrɪdʒ/', 'Chúng tôi đã đi qua cây cầu đi bộ bằng gỗ bắc qua con suối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_1_5', 'ten_b1_40_1', 'central', 'Our apartment is central, so we walk to most places.', 'Our apartment is central, so we walk to most places.', '/ˈsentrəl/', 'Căn hộ của chúng tôi nằm ngay trung tâm, nên chúng tôi đi bộ đến hầu hết các nơi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_1_6', 'ten_b1_40_1', 'suburb', 'They moved to a quiet suburb near the river.', 'They moved to a quiet suburb near the river.', '/ˈsʌbɜːrb/', 'Họ đã chuyển đến một khu ngoại ô yên tĩnh gần con sông.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_1_7', 'ten_b1_40_1', 'corridor', 'Her footsteps echoed along the empty corridor after class.', 'Her footsteps echoed along the empty corridor after class.', '/ˈkɔːrɪdɔːr/', 'Tiếng bước chân của cô ấy vang vọng dọc theo hành lang vắng lặng sau giờ học.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_1_8', 'ten_b1_40_1', 'chimney', 'Smoke rose from the chimney into the cold evening air.', 'Smoke rose from the chimney into the cold evening air.', '/ˈtʃɪmni/', 'Khói từ ống khói bay lên bầu trời buổi chiều lạnh giá.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_40_1_1', 'en-b1-40', 'ten_b1_40_1', 'listening', 'listening', 'The sculptor carved a bird from a block of wood.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người thợ điêu khắc đã tạc một chú chim từ một khúc gỗ.","Làm ơn để những chiếc ủng dính bùn của bạn ngoài sảnh vào.","Tối qua chúng tôi đã xem phim tại một rạp chiếu phim ngoài trời.","Ngôi nhà mới của họ có hai tầng và một khu vườn nhỏ."]'::jsonb, 0, 'The sculptor carved a bird from a block of wood. → Người thợ điêu khắc đã tạc một chú chim từ một khúc gỗ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_40_1_2', 'en-b1-40', 'ten_b1_40_1', 'listening', 'listening', 'The skyscraper cast a long shadow across the park.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một con nhện nhỏ đang bò ngang qua trần nhà.","Tòa nhà chọc trời đổ bóng dài across công viên.","Xin đừng lái xe đạp lên phần vỉa hè đang đông đúc người qua lại.","Tối qua chúng tôi đã xem phim tại một rạp chiếu phim ngoài trời."]'::jsonb, 1, 'The skyscraper cast a long shadow across the park. → Tòa nhà chọc trời đổ bóng dài across công viên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_40_1_3', 'en-b1-40', 'ten_b1_40_1', 'listening', 'listening', 'We walked along the pavement beside the busy road.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hãy rẽ ở lối ra thứ hai tại bùng binh gần công viên.","Khói từ ống khói bay lên bầu trời buổi chiều lạnh giá.","Chúng tôi đi bộ dọc theo vỉa hè cạnh con đường đông đúc.","Chúng tôi đã mượn một cái thang từ trang trại lân cận."]'::jsonb, 2, 'We walked along the pavement beside the busy road. → Chúng tôi đi bộ dọc theo vỉa hè cạnh con đường đông đúc.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_40_2', 'en-b1-40', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_2_1', 'ten_b1_40_2', 'block', 'Poorly parked vehicles can block access to public buildings, creating difficulties for wheelchair users.', 'Poorly parked vehicles can block access to public buildings, creating difficulties for wheelchair users.', '/blɑːk/', 'Phương tiện đỗ không đúng nơi quy định có thể cản trở lối vào các tòa nhà công cộng, gây khó khăn cho người dùng xe lăn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_2_2', 'ten_b1_40_2', 'skyscraper', 'Building skyscrapers can accommodate growing urban populations, but cities must also invest in reliable public transport.', 'Building skyscrapers can accommodate growing urban populations, but cities must also invest in reliable public transport.', '/ˈskaɪskreɪpər/', 'Việc xây dựng các tòa nhà chọc trời có thể đáp ứng dân số đô thị ngày càng tăng, nhưng các thành phố cũng phải đầu tư vào hệ thống giao thông công cộng đáng tin cậy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_2_3', 'ten_b1_40_2', 'pavement', 'Wider pavements can improve pedestrian safety and make urban neighbourhoods more accessible for wheelchair users.', 'Wider pavements can improve pedestrian safety and make urban neighbourhoods more accessible for wheelchair users.', '/ˈpeɪvmənt/', 'Vỉa hè rộng hơn có thể cải thiện an toàn cho người đi bộ và giúp các khu dân cư đô thị dễ tiếp cận hơn đối với người ngồi xe lăn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_2_4', 'ten_b1_40_2', 'footbridge', 'Building a footbridge near the station would allow pedestrians to cross the busy road safely.', 'Building a footbridge near the station would allow pedestrians to cross the busy road safely.', '/ˈfʊtbrɪdʒ/', 'Việc xây dựng một cây cầu đi bộ gần nhà ga sẽ giúp người đi bộ băng qua con đường đông đúc một cách an toàn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_2_5', 'ten_b1_40_2', 'central', 'Access to reliable information is central to helping citizens make informed decisions about public health.', 'Access to reliable information is central to helping citizens make informed decisions about public health.', '/ˈsentrəl/', 'Việc tiếp cận thông tin đáng tin cậy đóng vai trò cốt lõi trong việc giúp người dân đưa ra các quyết định sáng suốt về y tế công cộng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_40_2_6', 'ten_b1_40_2', 'suburb', 'Reliable public transport can help residents of distant suburbs reach employment opportunities in the city centre.', 'Reliable public transport can help residents of distant suburbs reach employment opportunities in the city centre.', '/ˈsʌbɜːrb/', 'Giao thông công cộng đáng tin cậy có thể giúp cư dân ở các vùng ngoại ô xa xôi tiếp cận các cơ hội việc làm ở trung tâm thành phố.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_40_2_1', 'en-b1-40', 'ten_b1_40_2', 'listening', 'listening', 'Poorly parked vehicles can block access to public buildings, creating difficulties for wheelchair users.', NULL, 'Trong câu vừa nghe, từ “block” mang nghĩa nào sau đây?', '["sự nghèo đói; cảnh nghèo túng","sự sắp xếp; sự chuẩn bị","số liệu; con số","khối; tảng"]'::jsonb, 3, '“block” (/blɑːk/): khối; tảng. Câu đầy đủ: Poorly parked vehicles can block access to public buildings, creating difficulties for wheelchair users.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_40_2_2', 'en-b1-40', 'ten_b1_40_2', 'listening', 'listening', 'Building skyscrapers can accommodate growing urban populations, but cities must also invest in reliable public transport.', NULL, 'Trong câu vừa nghe, từ “skyscraper” mang nghĩa nào sau đây?', '["tòa nhà chọc trời","lời bình luận; ý kiến","nổi; trôi bồng bềnh","nếu không thì; bằng không"]'::jsonb, 0, '“skyscraper” (/ˈskaɪskreɪpər/): tòa nhà chọc trời. Câu đầy đủ: Building skyscrapers can accommodate growing urban populations, but cities must also invest in reliable public transport.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
