INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_40_2', 'en-b1-40', NULL, 'comprehensive_test', 'listening', 'The skyscraper cast a long shadow across the park.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ô tô không được phép đi vào khu vực dành riêng cho người đi bộ yên tĩnh này.","Tòa nhà chọc trời đổ bóng dài across công viên.","Họ đã chuyển đến một khu ngoại ô yên tĩnh gần con sông.","Xin đừng lái xe đạp lên phần vỉa hè đang đông đúc người qua lại."]'::jsonb, 1, 'The skyscraper cast a long shadow across the park. → Tòa nhà chọc trời đổ bóng dài across công viên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_40_3', 'en-b1-40', NULL, 'comprehensive_test', 'listening', 'pavement', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thường xuyên; hay xảy ra","sự khó khăn; nỗi vất vả","thằn lằn; kỳ nhông","vỉa hè; lề đường"]'::jsonb, 3, 'pavement (/ˈpeɪvmənt/) → vỉa hè; lề đường; bề mặt đường được lát cứng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_40_4', 'en-b1-40', NULL, 'comprehensive_test', 'listening', 'We crossed the wooden footbridge above the stream.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xin đừng lái xe đạp lên phần vỉa hè đang đông đúc người qua lại.","Chúng tôi đã đi qua cây cầu đi bộ bằng gỗ bắc qua con suối.","Cô ấy trồng các loại thảo mộc trong những chiếc chậu nhỏ ở ban công nhà mình.","Tiếng bước chân của cô ấy vang vọng dọc theo hành lang vắng lặng sau giờ học."]'::jsonb, 1, 'We crossed the wooden footbridge above the stream. → Chúng tôi đã đi qua cây cầu đi bộ bằng gỗ bắc qua con suối.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_40_5', 'en-b1-40', NULL, 'comprehensive_test', 'listening', 'central', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cỡ trung bình; trung cỡ","ở trung tâm; thuộc về trung tâm","tấn công; chỉ trích gay gắt","thường xuyên; hay"]'::jsonb, 1, 'central (/ˈsentrəl/) → ở trung tâm; thuộc về trung tâm; quan trọng nhất; cốt lõi; thiết yếu', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_40_6', 'en-b1-40', NULL, 'comprehensive_test', 'listening', 'They moved to a quiet suburb near the river.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Làm ơn để những chiếc ủng dính bùn của bạn ngoài sảnh vào.","Xe buýt của chúng tôi chuyển vào làn đường bên cạnh vỉa hè.","Nước rỉ ra từ một đoạn ống bị vỡ ở dưới bồn rửa chén.","Họ đã chuyển đến một khu ngoại ô yên tĩnh gần con sông."]'::jsonb, 3, 'They moved to a quiet suburb near the river. → Họ đã chuyển đến một khu ngoại ô yên tĩnh gần con sông.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
