INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_40_8', 'en-b1-40', NULL, 'comprehensive_test', 'listening', 'Smoke rose from the chimney into the cold evening air.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người thợ điêu khắc đã tạc một chú chim từ một khúc gỗ.","Khói từ ống khói bay lên bầu trời buổi chiều lạnh giá.","Chúng tôi đã mượn một cái thang từ trang trại lân cận.","Nước rỉ ra từ một đoạn ống bị vỡ ở dưới bồn rửa chén."]'::jsonb, 1, 'Smoke rose from the chimney into the cold evening air. → Khói từ ống khói bay lên bầu trời buổi chiều lạnh giá.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
