INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_40_18', 'en-b1-40', NULL, 'comprehensive_test', 'reading', NULL, 'Poorly parked vehicles can block access to public buildings, creating difficulties for wheelchair users.', 'Dựa vào câu trên, từ “block” có nghĩa phù hợp nhất là gì?', '["sự sản xuất; chế tạo","khối; tảng","thích; yêu mến","trước; trước đó; cũ"]'::jsonb, 1, 'block: khối; tảng; ngăn chặn; làm tắc nghẽn; khu nhà; dãy nhà; tòa nhà lớn. Dịch cả câu: Phương tiện đỗ không đúng nơi quy định có thể cản trở lối vào các tòa nhà công cộng, gây khó khăn cho người dùng xe lăn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_40_19', 'en-b1-40', NULL, 'comprehensive_test', 'reading', NULL, 'Building skyscrapers can accommodate growing urban populations, but cities must also invest in reliable public transport.', 'Dựa vào câu trên, từ “skyscraper” có nghĩa phù hợp nhất là gì?', '["tòa nhà chọc trời","bánh quy giòn mỏng","vật phát minh; phát minh","ôm; ôm chặt"]'::jsonb, 0, 'skyscraper: tòa nhà chọc trời. Dịch cả câu: Việc xây dựng các tòa nhà chọc trời có thể đáp ứng dân số đô thị ngày càng tăng, nhưng các thành phố cũng phải đầu tư vào hệ thống giao thông công cộng đáng tin cậy.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_40_20', 'en-b1-40', NULL, 'comprehensive_test', 'reading', NULL, 'Wider pavements can improve pedestrian safety and make urban neighbourhoods more accessible for wheelchair users.', 'Dựa vào câu trên, từ “pavement” có nghĩa phù hợp nhất là gì?', '["nhận ra; nhận diện","hoàng gia; thuộc về nhà vua hoặc hoàng hậu","địa điểm thu hút; danh lam thắng cảnh","vỉa hè; lề đường"]'::jsonb, 3, 'pavement: vỉa hè; lề đường; bề mặt đường được lát cứng. Dịch cả câu: Vỉa hè rộng hơn có thể cải thiện an toàn cho người đi bộ và giúp các khu dân cư đô thị dễ tiếp cận hơn đối với người ngồi xe lăn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_40_21', 'en-b1-40', NULL, 'comprehensive_test', 'reading', NULL, 'Building a footbridge near the station would allow pedestrians to cross the busy road safely.', 'Dựa vào câu trên, từ “footbridge” có nghĩa phù hợp nhất là gì?', '["thuộc về kinh tế","giấy dán tường","cầu đi bộ","có vị đắng; đắng"]'::jsonb, 2, 'footbridge: cầu đi bộ. Dịch cả câu: Việc xây dựng một cây cầu đi bộ gần nhà ga sẽ giúp người đi bộ băng qua con đường đông đúc một cách an toàn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_40_22', 'en-b1-40', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “quận; khu vực; vùng”', '["enjoyment","district","helmet","lecturer"]'::jsonb, 1, 'quận; khu vực; vùng → district (/ˈdɪstrɪkt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_40_23', 'en-b1-40', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “viên gạch; gạch”', '["keen","brick","booklet","frighten"]'::jsonb, 1, 'viên gạch; gạch → brick (/brɪk/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_40_24', 'en-b1-40', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thang cuốn”', '["stinky","escalator","refund","ambition"]'::jsonb, 1, 'thang cuốn → escalator (/ˈeskəleɪtər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-41', 'en', 'Bài 41: Thể thao & Vận động (1) - CEFR B1', 'CEFR B1', 'B1 · Thể thao', '15 từ vựng Tiếng Anh CEFR B1 chủ đề thể thao & vận động kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3041, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_racket', 'en-b1-41', 'racket', '/ˈrækɪt/', 'B1', 'vợt (thể thao); tiếng ồn ào; tiếng huyên náo', 'n.', NULL, NULL, 'Dụng cụ đánh bóng cũng có thể viết là racquet; còn tiếng ồn ào thì chỉ dùng racket.', 'I left my tennis racket beside the court.', NULL, 'Tôi để quên chiếc vợt tennis ở bên sân đấu.', '{"wordId":"racket","ukIpa":"/ˈrækɪt/","usIpa":"/ˈrækɪt/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"An object with strings used to hit balls in sports.","vi":"vợt (thể thao)"},{"pos":"n.","en":"A loud, unpleasant noise.","vi":"tiếng ồn ào; tiếng huyên náo"}],"examples":[{"en":"I left my tennis racket beside the court.","vi":"Tôi để quên chiếc vợt tennis ở bên sân đấu.","audioKind":"ex"},{"en":"Providing basic equipment, such as a racket, can make school sports more accessible to children.","vi":"Việc cung cấp các thiết bị cơ bản như vợt thể thao có thể giúp trẻ em tiếp cận dễ dàng hơn với các môn thể thao ở trường.","audioKind":"ex2"}],"collocations":[{"en":"tennis racket","vi":"vợt tennis"},{"en":"badminton racket","vi":"vợt cầu lông"},{"en":"make a racket","vi":"làm ồn ào"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dụng cụ đánh bóng cũng có thể viết là racquet; còn tiếng ồn ào thì chỉ dùng racket.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trophy', 'en-b1-41', 'trophy', '/ˈtroʊfi/', 'B1', 'cúp; giải thưởng; chiến lợi phẩm; vật lưu niệm chiến thắng', 'n.', NULL, 'Đồng nghĩa: prize, award', 'Số nhiều là trophies; trong IELTS từ này chủ yếu đóng vai trò là danh từ.', 'Our team lifted the trophy as the crowd cheered.', NULL, 'Đội của chúng tôi đã nâng cao chiếc cúp trong tiếng hò reo của đám đông.', '{"wordId":"trophy","ukIpa":"/ˈtrəʊfi/","usIpa":"/ˈtroʊfi/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"An object awarded to someone for winning a competition.","vi":"cúp; giải thưởng"},{"pos":"n.","en":"An object kept as evidence or a reminder of victory.","vi":"chiến lợi phẩm; vật lưu niệm chiến thắng"}],"examples":[{"en":"Our team lifted the trophy as the crowd cheered.","vi":"Đội của chúng tôi đã nâng cao chiếc cúp trong tiếng hò reo của đám đông.","audioKind":"ex"},{"en":"Although winning a trophy can motivate young athletes, participation should also develop teamwork and personal resilience.","vi":"Mặc dù việc giành được cúp có thể khích lệ các vận động viên trẻ, nhưng sự tham gia cũng cần bồi dưỡng tinh thần đồng đội và khả năng phục hồi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"win a trophy","vi":"giành cúp"},{"en":"lift the trophy","vi":"nâng cúp"},{"en":"a trophy cabinet","vi":"tủ trưng bày cúp"}],"wordFamily":[],"synonyms":["prize","award"],"antonyms":[],"tipVi":"Số nhiều là trophies; trong IELTS từ này chủ yếu đóng vai trò là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_athlete', 'en-b1-41', 'athlete', '/ˈæθliːt/', 'B1', 'vận động viên', 'n.', 'athletic (adj.), athletics (n.), athleticism (n.)', 'Đồng nghĩa: sportsperson', 'athlete thường dùng chỉ chung các vận động viên, không chỉ riêng vận động viên điền kinh.', 'The athlete stretched her legs before the morning race.', NULL, 'Nữ vận động viên đã khởi động chân trước buổi chạy sáng nay.', '{"wordId":"athlete","ukIpa":"/ˈæθliːt/","usIpa":"/ˈæθliːt/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"A person trained to compete in sports requiring physical skill.","vi":"vận động viên"}],"examples":[{"en":"The athlete stretched her legs before the morning race.","vi":"Nữ vận động viên đã khởi động chân trước buổi chạy sáng nay.","audioKind":"ex"},{"en":"Young athletes need balanced training programmes that protect their health while allowing them to pursue sporting excellence.","vi":"Các vận động viên trẻ cần có các chương trình tập luyện cân bằng nhằm bảo vệ sức khỏe đồng thời vươn tới đỉnh cao thể thao.","audioKind":"ex2"}],"collocations":[{"en":"professional athlete","vi":"vận động viên chuyên nghiệp"},{"en":"elite athlete","vi":"vận động viên đỉnh cao"},{"en":"a promising young athlete","vi":"một tài năng trẻ triển vọng trong làng thể thao"}],"wordFamily":["athletic (adj.)","athletics (n.)","athleticism (n.)"],"synonyms":["sportsperson"],"antonyms":[],"tipVi":"athlete thường dùng chỉ chung các vận động viên, không chỉ riêng vận động viên điền kinh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_league', 'en-b1-41', 'league', '/liːɡ/', 'B1', 'giải đấu thể thao; liên minh; hiệp hội; đẳng cấp; cấp độ', 'n.', NULL, NULL, 'Cụm in a different league thường dùng để chỉ trình độ vượt trội hẳn.', 'Our team finished top of the league this season.', NULL, 'Đội của chúng tôi đã đứng đầu bảng xếp hạng giải đấu mùa này.', '{"wordId":"league","ukIpa":"/liːɡ/","usIpa":"/liːɡ/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"A group of sports teams that regularly compete against one another.","vi":"giải đấu thể thao"},{"pos":"n.","en":"An association of people or groups sharing a common purpose.","vi":"liên minh; hiệp hội"},{"pos":"n.","en":"A level of quality, ability, or achievement.","vi":"đẳng cấp; cấp độ"}],"examples":[{"en":"Our team finished top of the league this season.","vi":"Đội của chúng tôi đã đứng đầu bảng xếp hạng giải đấu mùa này.","audioKind":"ex"},{"en":"A local sports league can strengthen community ties by bringing together players from different social backgrounds.","vi":"Một giải đấu thể thao địa phương có thể thắt chặt tình đoàn kết cộng đồng bằng cách quy tụ các cầu thủ từ các tầng lớp xã hội khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"a football league","vi":"giải bóng đá"},{"en":"top of the league","vi":"đứng đầu bảng"},{"en":"in a different league","vi":"ở một đẳng cấp khác"},{"en":"out of my league","vi":"vượt quá tầm với của tôi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm in a different league thường dùng để chỉ trình độ vượt trội hẳn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diving', 'en-b1-41', 'diving', '/ˈdaɪvɪŋ/', 'B1', 'hoạt động lặn dưới nước; môn nhảy cầu', 'n.', 'dive (v.), diver (n.)', NULL, 'go diving thường chỉ đi lặn; môn thể thao nhảy cầu cũng được gọi là diving.', 'We went diving and saw colourful fish near the reef.', NULL, 'Chúng tôi đi lặn và nhìn thấy những chú cá đầy màu sắc gần rạn san hô.', '{"wordId":"diving","ukIpa":"/ˈdaɪvɪŋ/","usIpa":"/ˈdaɪvɪŋ/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"the activity of swimming underwater, often using special breathing equipment","vi":"hoạt động lặn dưới nước"},{"pos":"n.","en":"the sport of jumping into water, often with controlled movements","vi":"môn nhảy cầu"}],"examples":[{"en":"We went diving and saw colourful fish near the reef.","vi":"Chúng tôi đi lặn và nhìn thấy những chú cá đầy màu sắc gần rạn san hô.","audioKind":"ex"},{"en":"Diving tourism can support coastal economies, provided operators protect marine habitats and teach visitors responsible behaviour.","vi":"Du lịch lặn có thể hỗ trợ nền kinh tế ven biển, với điều kiện là các đơn vị khai thác bảo vệ môi trường sống biển và hướng dẫn du khách hành xử có trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"scuba diving","vi":"lặn biển có bình khí"},{"en":"a diving board","vi":"ván nhảy cầu"},{"en":"diving equipment","vi":"trang thiết bị lặn"},{"en":"a diving instructor","vi":"huấn luyện viên lặn"}],"wordFamily":["dive (v.)","diver (n.)"],"synonyms":[],"antonyms":[],"tipVi":"go diving thường chỉ đi lặn; môn thể thao nhảy cầu cũng được gọi là diving.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boxer', 'en-b1-41', 'boxer', '/ˈbɑːksər/', 'B1', 'vận động viên thi đấu môn quyền Anh', 'n.', 'box (v.), boxing (n.)', NULL, 'Động từ box có thể chỉ việc đánh quyền Anh; boxer là vận động viên môn quyền Anh.', 'The boxer pulled on her gloves before training.', NULL, 'Nữ vận động viên quyền Anh xỏ găng trước khi bước vào buổi tập.', '{"wordId":"boxer","ukIpa":"/ˈbɒksə/","usIpa":"/ˈbɑːksər/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"A person who competes in boxing.","vi":"vận động viên thi đấu môn quyền Anh"}],"examples":[{"en":"The boxer pulled on her gloves before training.","vi":"Nữ vận động viên quyền Anh xỏ găng trước khi bước vào buổi tập.","audioKind":"ex"},{"en":"A professional boxer needs disciplined training and adequate recovery time to maintain both performance and long-term health.","vi":"Một vận động viên quyền Anh chuyên nghiệp đòi hỏi phải có quá trình huấn luyện kỷ luật và thời gian hồi phục đầy đủ để duy trì cả phong độ thi đấu lẫn sức khỏe lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"professional boxer","vi":"vận động viên quyền Anh chuyên nghiệp"},{"en":"amateur boxer","vi":"vận động viên quyền Anh nghiệp dư"},{"en":"heavyweight boxer","vi":"vận động viên quyền Anh hạng nặng"}],"wordFamily":["box (v.)","boxing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ box có thể chỉ việc đánh quyền Anh; boxer là vận động viên môn quyền Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sportsman', 'en-b1-41', 'sportsman', '/ˈspɔːrtsmən/', 'B1', 'nam vận động viên; người đàn ông yêu thể thao', 'n.', 'sportswoman (n.), sport (n.), sporting (adj.), sportsmanship (n.)', 'Đồng nghĩa: athlete', 'Chỉ định rõ giới tính nam; khi không cần nhấn mạnh giới tính, có thể dùng athlete.', 'My uncle was a keen sportsman in his youth.', NULL, 'Chú của tôi từng là một người rất nhiệt tình chơi thể thao thời trẻ.', '{"wordId":"sportsman","ukIpa":"/ˈspɔːtsmən/","usIpa":"/ˈspɔːrtsmən/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"a man who plays sports, especially with skill","vi":"nam vận động viên; người đàn ông yêu thể thao"}],"examples":[{"en":"My uncle was a keen sportsman in his youth.","vi":"Chú của tôi từng là một người rất nhiệt tình chơi thể thao thời trẻ.","audioKind":"ex"},{"en":"A successful sportsman can encourage young people to exercise regularly and develop confidence through physical activity.","vi":"Một nam vận động viên thành công có thể khuyến khích giới trẻ tập thể dục thường xuyên và phát triển sự tự tin thông qua các hoạt động thể chất.","audioKind":"ex2"}],"collocations":[{"en":"keen sportsman","vi":"người đàn ông đam mê thể thao"},{"en":"professional sportsman","vi":"nam vận động viên chuyên nghiệp"},{"en":"talented sportsman","vi":"nam vận động viên tài năng"}],"wordFamily":["sportswoman (n.)","sport (n.)","sporting (adj.)","sportsmanship (n.)"],"synonyms":["athlete"],"antonyms":[],"tipVi":"Chỉ định rõ giới tính nam; khi không cần nhấn mạnh giới tính, có thể dùng athlete.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dive', 'en-b1-41', 'dive', '/daɪv/', 'B1', 'lặn; nhảy cắm đầu xuống nước; lao xuống; sụt giá nhanh chóng; cú nhảy cắm đầu xuống nước; cú lặn; sự sụt giảm mạnh', 'v.', 'diver (n.), diving (n.)', 'Đồng nghĩa: plunge', 'British past tense is usually dived, American also uses dove.', 'We watched a swimmer dive smoothly into the pool.', NULL, 'Chúng tôi nhìn một vận động viên bơi lội lao mình thật mượt mà xuống hồ bơi.', '{"wordId":"dive","ukIpa":"/daɪv/","usIpa":"/daɪv/","cefr":"B1","topic":"sport","senses":[{"pos":"v.","en":"to enter water headfirst or swim beneath its surface","vi":"lặn; nhảy cắm đầu xuống nước"},{"pos":"v.","en":"to move downwards suddenly and quickly","vi":"lao xuống; sụt giá nhanh chóng"},{"pos":"n.","en":"an act of diving or a sudden sharp fall","vi":"cú nhảy cắm đầu xuống nước; cú lặn; sự sụt giảm mạnh"}],"examples":[{"en":"We watched a swimmer dive smoothly into the pool.","vi":"Chúng tôi nhìn một vận động viên bơi lội lao mình thật mượt mà xuống hồ bơi.","audioKind":"ex"},{"en":"Tourists who dive near coral reefs should avoid touching marine organisms to prevent damage to fragile ecosystems.","vi":"Du khách lặn gần các rạn san hô nên tránh chạm vào các sinh vật biển để ngăn ngừa tổn hại đến các hệ sinh thái mỏng manh.","audioKind":"ex2"}],"collocations":[{"en":"dive into the water","vi":"lao xuống nước"},{"en":"scuba dive","vi":"lặn với bình dưỡng khí"},{"en":"take a dive","vi":"lao dốc; sụt giảm mạnh"}],"wordFamily":["diver (n.)","diving (n.)"],"synonyms":["plunge"],"antonyms":[],"tipVi":"British past tense is usually dived, American also uses dove.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rugby', 'en-b1-41', 'rugby', '/ˈrʌɡbi/', 'B1', 'môn bóng bầu dục', 'n.', NULL, NULL, 'Thường chỉ môn bóng bầu dục Anh (rugby), không giống với bóng bầu dục Mỹ (american football).', 'My brother plays rugby every Saturday with his friends.', NULL, 'Anh trai tôi chơi bóng bầu dục cùng bạn bè vào thứ Bảy hàng tuần.', '{"wordId":"rugby","ukIpa":"/ˈrʌɡbi/","usIpa":"/ˈrʌɡbi/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"A team sport involving carrying, passing, and kicking an oval ball","vi":"môn bóng bầu dục"}],"examples":[{"en":"My brother plays rugby every Saturday with his friends.","vi":"Anh trai tôi chơi bóng bầu dục cùng bạn bè vào thứ Bảy hàng tuần.","audioKind":"ex"},{"en":"Schools offering rugby should provide suitable coaching and safety equipment to reduce the risk of injuries.","vi":"Các trường học cung cấp môn bóng bầu dục nên cung cấp sự huấn luyện phù hợp và trang1 thiết bị an toàn để giảm thiểu nguy cơ chấn thương.","audioKind":"ex2"}],"collocations":[{"en":"play rugby","vi":"chơi bóng bầu dục"},{"en":"rugby match","vi":"trận đấu bóng bầu dục"},{"en":"rugby union","vi":"liên đoàn bóng bầu dục (Rugby Union)"},{"en":"rugby league","vi":"giải bóng bầu dục (Rugby League)"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ môn bóng bầu dục Anh (rugby), không giống với bóng bầu dục Mỹ (american football).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_helmet', 'en-b1-41', 'helmet', '/ˈhelmɪt/', 'B1', 'mũ bảo hiểm; mũ sắt', 'n.', 'helmeted (adj.)', NULL, 'Danh từ đếm được: đội mũ bảo hiểm dùng wear a helmet.', 'Fasten your helmet before you get on the bicycle.', NULL, 'Hãy cài quai mũ bảo hiểm trước khi bạn lên xe đạp.', '{"wordId":"helmet","ukIpa":"/ˈhelmɪt/","usIpa":"/ˈhelmɪt/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"A strong protective covering worn on the head","vi":"mũ bảo hiểm; mũ sắt"}],"examples":[{"en":"Fasten your helmet before you get on the bicycle.","vi":"Hãy cài quai mũ bảo hiểm trước khi bạn lên xe đạp.","audioKind":"ex"},{"en":"Wearing a helmet can reduce the risk of serious head injuries among cyclists involved in accidents.","vi":"Đội mũ bảo hiểm có thể làm giảm nguy cơ chấn thương đầu nghiêm trọng cho những người đi xe đạp không may gặp tai nạn.","audioKind":"ex2"}],"collocations":[{"en":"wear a helmet","vi":"đội mũ bảo hiểm"},{"en":"cycle helmet","vi":"mũ bảo hiểm đi xe đạp"},{"en":"safety helmet","vi":"mũ bảo hiểm an toàn"}],"wordFamily":["helmeted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được: đội mũ bảo hiểm dùng wear a helmet.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rowing', 'en-b1-41', 'rowing', '/ˈroʊɪŋ/', 'B1', 'chèo thuyền; môn đua thuyền', 'n.', 'row (v.), rower (n.)', NULL, 'Từ rowing (chèo thuyền) phát âm là /rəʊ/, khác với row (tranh cãi) phát âm là /raʊ/.', 'My sister goes rowing on the lake every Saturday.', NULL, 'Chị gái tôi đi chèo thuyền trên hồ vào mỗi thứ Bảy.', '{"wordId":"rowing","ukIpa":"/ˈrəʊɪŋ/","usIpa":"/ˈroʊɪŋ/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"The activity or sport of moving a boat with oars.","vi":"chèo thuyền; môn đua thuyền"}],"examples":[{"en":"My sister goes rowing on the lake every Saturday.","vi":"Chị gái tôi đi chèo thuyền trên hồ vào mỗi thứ Bảy.","audioKind":"ex"},{"en":"Schools that offer rowing can help students develop physical fitness, coordination, and a strong sense of teamwork.","vi":"Các trường có tổ chức môn đua thuyền có thể giúp học sinh rèn luyện thể lực, khả năng phối hợp và tinh thần đồng đội cao.","audioKind":"ex2"}],"collocations":[{"en":"go rowing","vi":"đi chèo thuyền"},{"en":"a rowing club","vi":"câu lạc bộ đua thuyền"},{"en":"a rowing machine","vi":"máy tập chèo thuyền"},{"en":"a rowing team","vi":"đội đua thuyền"}],"wordFamily":["row (v.)","rower (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ rowing (chèo thuyền) phát âm là /rəʊ/, khác với row (tranh cãi) phát âm là /raʊ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_medal', 'en-b1-41', 'medal', '/ˈmedəl/', 'B1', 'huy chương; huân chương', 'n.', 'medallist (n.)', NULL, 'Medal là huy chương; metal là kim loại, cần chú ý phân biệt cách viết.', 'She proudly showed us her first swimming medal.', NULL, 'Cô ấy tự hào khoe huy chương bơi lội đầu tiên của mình.', '{"wordId":"medal","ukIpa":"/ˈmedəl/","usIpa":"/ˈmedəl/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"A metal award given for achievement, service, or bravery.","vi":"huy chương; huân chương"}],"examples":[{"en":"She proudly showed us her first swimming medal.","vi":"Cô ấy tự hào khoe huy chương bơi lội đầu tiên của mình.","audioKind":"ex"},{"en":"Winning an international medal can encourage young athletes to pursue sport as a professional career.","vi":"Việc giành huy chương quốc tế có thể khích lệ các vận động viên trẻ theo đuổi thể thao như một sự nghiệp chuyên nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"win a medal","vi":"giành huy chương"},{"en":"gold medal","vi":"huy chương vàng"},{"en":"silver medal","vi":"huy chương bạc"},{"en":"bronze medal","vi":"huy chương đồng"}],"wordFamily":["medallist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Medal là huy chương; metal là kim loại, cần chú ý phân biệt cách viết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_championship', 'en-b1-41', 'championship', '/ˈtʃæmpiənʃɪp/', 'B1', 'giải vô địch; cuộc thi vô địch; danh hiệu vô địch; ngôi vị quán quân', 'n.', 'champion (n.)', NULL, 'Có thể dùng để chỉ giải đấu tranh ngôi vô địch hoặc danh hiệu quán quân.', 'Our school team reached the final of the championship.', NULL, 'Đội bóng trường chúng tôi đã vào đến trận chung kết của giải vô địch.', '{"wordId":"championship","ukIpa":"/ˈtʃæmpiənʃɪp/","usIpa":"/ˈtʃæmpiənʃɪp/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"a competition to decide the best player or team","vi":"giải vô địch; cuộc thi vô địch"},{"pos":"n.","en":"the position or title of being a champion","vi":"danh hiệu vô địch; ngôi vị quán quân"}],"examples":[{"en":"Our school team reached the final of the championship.","vi":"Đội bóng trường chúng tôi đã vào đến trận chung kết của giải vô địch.","audioKind":"ex"},{"en":"Hosting an international championship can attract visitors, but the cost of new facilities may burden local taxpayers.","vi":"Việc đăng cai một giải vô địch quốc tế có thể thu hút khách du lịch, nhưng chi phí xây dựng cơ sở hạ tầng mới có thể gây gánh nặng cho người đóng thuế địa phương.","audioKind":"ex2"}],"collocations":[{"en":"win a championship","vi":"giành chức vô địch"},{"en":"world championship","vi":"giải vô địch thế giới"},{"en":"championship title","vi":"danh hiệu vô địch"}],"wordFamily":["champion (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể dùng để chỉ giải đấu tranh ngôi vô địch hoặc danh hiệu quán quân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_captain', 'en-b1-41', 'captain', '/ˈkæptɪn/', 'B1', 'đội trưởng; thuyền trưởng; cơ trưởng; lãnh đạo đội; chỉ huy tàu; đại úy; thượng tá', 'n.', 'captaincy (n.)', NULL, 'Quân hàm thay đổi tùy theo quân chủng; trong hải quân thường chỉ cấp thượng tá.', 'Our captain gathered the team before the final match.', NULL, 'Đội trưởng của chúng tôi đã tập hợp toàn đội trước trận chung kết.', '{"wordId":"captain","ukIpa":"/ˈkæptɪn/","usIpa":"/ˈkæptɪn/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"The leader of a team or person commanding a vessel.","vi":"đội trưởng; thuyền trưởng; cơ trưởng"},{"pos":"v.","en":"To lead a team or command a ship.","vi":"lãnh đạo đội; chỉ huy tàu"},{"pos":"n.","en":"An officer holding a particular rank in the armed forces.","vi":"đại úy; thượng tá"}],"examples":[{"en":"Our captain gathered the team before the final match.","vi":"Đội trưởng của chúng tôi đã tập hợp toàn đội trước trận chung kết.","audioKind":"ex"},{"en":"A team captain can encourage cooperation by ensuring that every player feels valued and included.","vi":"Một đội trưởng có thể khích lệ sự hợp tác bằng cách đảm bảo rằng mọi cầu thủ đều cảm thấy được trân trọng và hòa nhập.","audioKind":"ex2"}],"collocations":[{"en":"team captain","vi":"đội trưởng"},{"en":"ship''s captain","vi":"thuyền trưởng"},{"en":"captain a team","vi":"dẫn dắt một đội"}],"wordFamily":["captaincy (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Quân hàm thay đổi tùy theo quân chủng; trong hải quân thường chỉ cấp thượng tá.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_canoe', 'en-b1-41', 'canoe', '/kəˈnuː/', 'B1', 'độc mộc; thuyền chèo tay; chèo thuyền độc mộc', 'n.', 'canoeing (n.), canoeist (n.)', NULL, 'Mặc dù được gọi là độc mộc, thuyền canoe hiện đại không nhất thiết phải làm từ gỗ.', 'We paddled our canoe across the lake before sunset.', NULL, 'Chúng tôi chèo thuyền độc mộc băng qua hồ trước khi mặt trời lặn.', '{"wordId":"canoe","ukIpa":"/kəˈnuː/","usIpa":"/kəˈnuː/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"a narrow, light boat moved using paddles","vi":"độc mộc; thuyền chèo tay"},{"pos":"v.","en":"to travel across water in a canoe","vi":"chèo thuyền độc mộc"}],"examples":[{"en":"We paddled our canoe across the lake before sunset.","vi":"Chúng tôi chèo thuyền độc mộc băng qua hồ trước khi mặt trời lặn.","audioKind":"ex"},{"en":"Visitors who explore wetlands by canoe can observe wildlife quietly without the disturbance caused by motorboats.","vi":"Du khách khám phá các cùng đất ngập nước bằng thuyền độc mộc có thể quan sát động vật hoang dã một cách yên tĩnh mà không bị làm phiền bởi xuồng máy.","audioKind":"ex2"}],"collocations":[{"en":"paddle a canoe","vi":"chèo thuyền độc mộc"},{"en":"go canoeing","vi":"đi chèo thuyền độc mộc"},{"en":"hire a canoe","vi":"thuê thuyền độc mộc"}],"wordFamily":["canoeing (n.)","canoeist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Mặc dù được gọi là độc mộc, thuyền canoe hiện đại không nhất thiết phải làm từ gỗ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_41_1', 'en-b1-41', 'Cách dùng “rugby” (n.) — môn bóng bầu dục', 'play rugby  ·  rugby match  ·  rugby union', 'Thường chỉ môn bóng bầu dục Anh (rugby), không giống với bóng bầu dục Mỹ (american football).', NULL, '[{"hanzi":"My brother plays rugby every Saturday with his friends.","pinyin":"","meaning":"Anh trai tôi chơi bóng bầu dục cùng bạn bè vào thứ Bảy hàng tuần."},{"hanzi":"Schools offering rugby should provide suitable coaching and safety equipment to reduce the risk of injuries.","pinyin":"","meaning":"Các trường học cung cấp môn bóng bầu dục nên cung cấp sự huấn luyện phù hợp và trang1 thiết bị an toàn để giảm thiểu nguy cơ chấn thương."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_41_2', 'en-b1-41', 'Cách dùng “athlete” (n.) — vận động viên', 'professional athlete  ·  elite athlete  ·  a promising young athlete', 'athlete thường dùng chỉ chung các vận động viên, không chỉ riêng vận động viên điền kinh.', 'Họ từ (Word Family): athletic (adj.), athletics (n.), athleticism (n.) | Đồng nghĩa: sportsperson', '[{"hanzi":"The athlete stretched her legs before the morning race.","pinyin":"","meaning":"Nữ vận động viên đã khởi động chân trước buổi chạy sáng nay."},{"hanzi":"Young athletes need balanced training programmes that protect their health while allowing them to pursue sporting excellence.","pinyin":"","meaning":"Các vận động viên trẻ cần có các chương trình tập luyện cân bằng nhằm bảo vệ sức khỏe đồng thời vươn tới đỉnh cao thể thao."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_41_3', 'en-b1-41', 'Cách dùng “rowing” (n.) — chèo thuyền; môn đua thuyền', 'go rowing  ·  a rowing club  ·  a rowing machine', 'Từ rowing (chèo thuyền) phát âm là /rəʊ/, khác với row (tranh cãi) phát âm là /raʊ/.', 'Họ từ (Word Family): row (v.), rower (n.)', '[{"hanzi":"My sister goes rowing on the lake every Saturday.","pinyin":"","meaning":"Chị gái tôi đi chèo thuyền trên hồ vào mỗi thứ Bảy."},{"hanzi":"Schools that offer rowing can help students develop physical fitness, coordination, and a strong sense of teamwork.","pinyin":"","meaning":"Các trường có tổ chức môn đua thuyền có thể giúp học sinh rèn luyện thể lực, khả năng phối hợp và tinh thần đồng đội cao."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_41_4', 'en-b1-41', 'Cách dùng “racket” (n.) — vợt (thể thao)', 'tennis racket  ·  badminton racket  ·  make a racket', 'Dụng cụ đánh bóng cũng có thể viết là racquet; còn tiếng ồn ào thì chỉ dùng racket.', NULL, '[{"hanzi":"I left my tennis racket beside the court.","pinyin":"","meaning":"Tôi để quên chiếc vợt tennis ở bên sân đấu."},{"hanzi":"Providing basic equipment, such as a racket, can make school sports more accessible to children.","pinyin":"","meaning":"Việc cung cấp các thiết bị cơ bản như vợt thể thao có thể giúp trẻ em tiếp cận dễ dàng hơn với các môn thể thao ở trường."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_41_1', 'en-b1-41', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_1_1', 'ten_b1_41_1', 'racket', 'I left my tennis racket beside the court.', 'I left my tennis racket beside the court.', '/ˈrækɪt/', 'Tôi để quên chiếc vợt tennis ở bên sân đấu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_1_2', 'ten_b1_41_1', 'trophy', 'Our team lifted the trophy as the crowd cheered.', 'Our team lifted the trophy as the crowd cheered.', '/ˈtroʊfi/', 'Đội của chúng tôi đã nâng cao chiếc cúp trong tiếng hò reo của đám đông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_1_3', 'ten_b1_41_1', 'athlete', 'The athlete stretched her legs before the morning race.', 'The athlete stretched her legs before the morning race.', '/ˈæθliːt/', 'Nữ vận động viên đã khởi động chân trước buổi chạy sáng nay.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_1_4', 'ten_b1_41_1', 'league', 'Our team finished top of the league this season.', 'Our team finished top of the league this season.', '/liːɡ/', 'Đội của chúng tôi đã đứng đầu bảng xếp hạng giải đấu mùa này.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_1_5', 'ten_b1_41_1', 'diving', 'We went diving and saw colourful fish near the reef.', 'We went diving and saw colourful fish near the reef.', '/ˈdaɪvɪŋ/', 'Chúng tôi đi lặn và nhìn thấy những chú cá đầy màu sắc gần rạn san hô.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_1_6', 'ten_b1_41_1', 'boxer', 'The boxer pulled on her gloves before training.', 'The boxer pulled on her gloves before training.', '/ˈbɑːksər/', 'Nữ vận động viên quyền Anh xỏ găng trước khi bước vào buổi tập.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_1_7', 'ten_b1_41_1', 'sportsman', 'My uncle was a keen sportsman in his youth.', 'My uncle was a keen sportsman in his youth.', '/ˈspɔːrtsmən/', 'Chú của tôi từng là một người rất nhiệt tình chơi thể thao thời trẻ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_1_8', 'ten_b1_41_1', 'dive', 'We watched a swimmer dive smoothly into the pool.', 'We watched a swimmer dive smoothly into the pool.', '/daɪv/', 'Chúng tôi nhìn một vận động viên bơi lội lao mình thật mượt mà xuống hồ bơi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_41_1_1', 'en-b1-41', 'ten_b1_41_1', 'listening', 'listening', 'I left my tennis racket beside the court.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi nhìn một vận động viên bơi lội lao mình thật mượt mà xuống hồ bơi.","Chú của tôi từng là một người rất nhiệt tình chơi thể thao thời trẻ.","Nữ vận động viên quyền Anh xỏ găng trước khi bước vào buổi tập.","Tôi để quên chiếc vợt tennis ở bên sân đấu."]'::jsonb, 3, 'I left my tennis racket beside the court. → Tôi để quên chiếc vợt tennis ở bên sân đấu.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_41_1_2', 'en-b1-41', 'ten_b1_41_1', 'listening', 'listening', 'Our team lifted the trophy as the crowd cheered.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi chèo thuyền độc mộc băng qua hồ trước khi mặt trời lặn.","Đội của chúng tôi đã nâng cao chiếc cúp trong tiếng hò reo của đám đông.","Tôi để quên chiếc vợt tennis ở bên sân đấu.","Đội của chúng tôi đã đứng đầu bảng xếp hạng giải đấu mùa này."]'::jsonb, 1, 'Our team lifted the trophy as the crowd cheered. → Đội của chúng tôi đã nâng cao chiếc cúp trong tiếng hò reo của đám đông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_41_1_3', 'en-b1-41', 'ten_b1_41_1', 'listening', 'listening', 'The athlete stretched her legs before the morning race.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đi lặn và nhìn thấy những chú cá đầy màu sắc gần rạn san hô.","Nữ vận động viên quyền Anh xỏ găng trước khi bước vào buổi tập.","Chúng tôi chèo thuyền độc mộc băng qua hồ trước khi mặt trời lặn.","Nữ vận động viên đã khởi động chân trước buổi chạy sáng nay."]'::jsonb, 3, 'The athlete stretched her legs before the morning race. → Nữ vận động viên đã khởi động chân trước buổi chạy sáng nay.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_41_2', 'en-b1-41', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_2_1', 'ten_b1_41_2', 'racket', 'Providing basic equipment, such as a racket, can make school sports more accessible to children.', 'Providing basic equipment, such as a racket, can make school sports more accessible to children.', '/ˈrækɪt/', 'Việc cung cấp các thiết bị cơ bản như vợt thể thao có thể giúp trẻ em tiếp cận dễ dàng hơn với các môn thể thao ở trường.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_2_2', 'ten_b1_41_2', 'trophy', 'Although winning a trophy can motivate young athletes, participation should also develop teamwork and personal resilience.', 'Although winning a trophy can motivate young athletes, participation should also develop teamwork and personal resilience.', '/ˈtroʊfi/', 'Mặc dù việc giành được cúp có thể khích lệ các vận động viên trẻ, nhưng sự tham gia cũng cần bồi dưỡng tinh thần đồng đội và khả năng phục hồi cá nhân.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_2_3', 'ten_b1_41_2', 'athlete', 'Young athletes need balanced training programmes that protect their health while allowing them to pursue sporting excellence.', 'Young athletes need balanced training programmes that protect their health while allowing them to pursue sporting excellence.', '/ˈæθliːt/', 'Các vận động viên trẻ cần có các chương trình tập luyện cân bằng nhằm bảo vệ sức khỏe đồng thời vươn tới đỉnh cao thể thao.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_2_4', 'ten_b1_41_2', 'league', 'A local sports league can strengthen community ties by bringing together players from different social backgrounds.', 'A local sports league can strengthen community ties by bringing together players from different social backgrounds.', '/liːɡ/', 'Một giải đấu thể thao địa phương có thể thắt chặt tình đoàn kết cộng đồng bằng cách quy tụ các cầu thủ từ các tầng lớp xã hội khác nhau.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_2_5', 'ten_b1_41_2', 'diving', 'Diving tourism can support coastal economies, provided operators protect marine habitats and teach visitors responsible behaviour.', 'Diving tourism can support coastal economies, provided operators protect marine habitats and teach visitors responsible behaviour.', '/ˈdaɪvɪŋ/', 'Du lịch lặn có thể hỗ trợ nền kinh tế ven biển, với điều kiện là các đơn vị khai thác bảo vệ môi trường sống biển và hướng dẫn du khách hành xử có trách nhiệm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_41_2_6', 'ten_b1_41_2', 'boxer', 'A professional boxer needs disciplined training and adequate recovery time to maintain both performance and long-term health.', 'A professional boxer needs disciplined training and adequate recovery time to maintain both performance and long-term health.', '/ˈbɑːksər/', 'Một vận động viên quyền Anh chuyên nghiệp đòi hỏi phải có quá trình huấn luyện kỷ luật và thời gian hồi phục đầy đủ để duy trì cả phong độ thi đấu lẫn sức khỏe lâu dài.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_41_2_1', 'en-b1-41', 'ten_b1_41_2', 'listening', 'listening', 'Providing basic equipment, such as a racket, can make school sports more accessible to children.', NULL, 'Trong câu vừa nghe, từ “racket” mang nghĩa nào sau đây?', '["nơi; địa điểm; chốn","phù hợp; thích hợp","vợt (thể thao)","mưu mẹo; trò lừa bịp"]'::jsonb, 2, '“racket” (/ˈrækɪt/): vợt (thể thao). Câu đầy đủ: Providing basic equipment, such as a racket, can make school sports more accessible to children.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_41_2_2', 'en-b1-41', 'ten_b1_41_2', 'listening', 'listening', 'Although winning a trophy can motivate young athletes, participation should also develop teamwork and personal resilience.', NULL, 'Trong câu vừa nghe, từ “trophy” mang nghĩa nào sau đây?', '["cúp; giải thưởng","lời khen ngợi; sự ca tụng","tầng của một tòa nhà","cần; đòi hỏi"]'::jsonb, 0, '“trophy” (/ˈtroʊfi/): cúp; giải thưởng. Câu đầy đủ: Although winning a trophy can motivate young athletes, participation should also develop teamwork and personal resilience.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
