INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_2', 'en-b1-41', NULL, 'comprehensive_test', 'listening', 'Our team lifted the trophy as the crowd cheered.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đội của chúng tôi đã nâng cao chiếc cúp trong tiếng hò reo của đám đông.","Chị gái tôi đi chèo thuyền trên hồ vào mỗi thứ Bảy.","Chúng tôi đi lặn và nhìn thấy những chú cá đầy màu sắc gần rạn san hô.","Đội của chúng tôi đã đứng đầu bảng xếp hạng giải đấu mùa này."]'::jsonb, 0, 'Our team lifted the trophy as the crowd cheered. → Đội của chúng tôi đã nâng cao chiếc cúp trong tiếng hò reo của đám đông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_3', 'en-b1-41', NULL, 'comprehensive_test', 'listening', 'athlete', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đồ uống có cồn; rượu","vận động viên","con ngỗng","cái bóng; bóng râm"]'::jsonb, 1, 'athlete (/ˈæθliːt/) → vận động viên', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_4', 'en-b1-41', NULL, 'comprehensive_test', 'listening', 'Our team finished top of the league this season.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chị gái tôi đi chèo thuyền trên hồ vào mỗi thứ Bảy.","Chúng tôi chèo thuyền độc mộc băng qua hồ trước khi mặt trời lặn.","Nữ vận động viên quyền Anh xỏ găng trước khi bước vào buổi tập.","Đội của chúng tôi đã đứng đầu bảng xếp hạng giải đấu mùa này."]'::jsonb, 3, 'Our team finished top of the league this season. → Đội của chúng tôi đã đứng đầu bảng xếp hạng giải đấu mùa này.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_5', 'en-b1-41', NULL, 'comprehensive_test', 'listening', 'diving', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hoạt động lặn dưới nước","sắt; chất sắt","thỏa thuận; giao dịch kinh doanh","hiệu quả; có năng suất cao; tiết kiệm (thời gian, năng lượng)"]'::jsonb, 0, 'diving (/ˈdaɪvɪŋ/) → hoạt động lặn dưới nước; môn nhảy cầu', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_6', 'en-b1-41', NULL, 'comprehensive_test', 'listening', 'The boxer pulled on her gloves before training.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi để quên chiếc vợt tennis ở bên sân đấu.","Chú của tôi từng là một người rất nhiệt tình chơi thể thao thời trẻ.","Nữ vận động viên quyền Anh xỏ găng trước khi bước vào buổi tập.","Nữ vận động viên đã khởi động chân trước buổi chạy sáng nay."]'::jsonb, 2, 'The boxer pulled on her gloves before training. → Nữ vận động viên quyền Anh xỏ găng trước khi bước vào buổi tập.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_7', 'en-b1-41', NULL, 'comprehensive_test', 'listening', 'sportsman', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vật; đồ vật","nam vận động viên; người đàn ông yêu thể thao","người hướng dẫn; huấn luyện viên","tình bạn; mối quan hệ bạn bè"]'::jsonb, 1, 'sportsman (/ˈspɔːrtsmən/) → nam vận động viên; người đàn ông yêu thể thao', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_8', 'en-b1-41', NULL, 'comprehensive_test', 'listening', 'We watched a swimmer dive smoothly into the pool.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nữ vận động viên quyền Anh xỏ găng trước khi bước vào buổi tập.","Chúng tôi nhìn một vận động viên bơi lội lao mình thật mượt mà xuống hồ bơi.","Cô ấy tự hào khoe huy chương bơi lội đầu tiên của mình.","Chú của tôi từng là một người rất nhiệt tình chơi thể thao thời trẻ."]'::jsonb, 1, 'We watched a swimmer dive smoothly into the pool. → Chúng tôi nhìn một vận động viên bơi lội lao mình thật mượt mà xuống hồ bơi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_9', 'en-b1-41', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the activity of swimming underwater, often using special breathing equipment”?', '["diving","medal","helmet","trophy"]'::jsonb, 0, 'diving (/ˈdaɪvɪŋ/) → hoạt động lặn dưới nước', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_10', 'en-b1-41', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A person who competes in boxing.”?', '["league","trophy","boxer","racket"]'::jsonb, 2, 'boxer (/ˈbɑːksər/) → vận động viên thi đấu môn quyền Anh', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_11', 'en-b1-41', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a man who plays sports, especially with skill”?', '["canoe","dive","helmet","sportsman"]'::jsonb, 3, 'sportsman (/ˈspɔːrtsmən/) → nam vận động viên; người đàn ông yêu thể thao', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
