INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_18', 'en-b1-41', NULL, 'comprehensive_test', 'reading', NULL, 'Providing basic equipment, such as a racket, can make school sports more accessible to children.', 'Dựa vào câu trên, từ “racket” có nghĩa phù hợp nhất là gì?', '["thích; yêu mến","phù hợp; thích hợp","đuổi theo, rượt đuổi ai đó để bắt","vợt (thể thao)"]'::jsonb, 3, 'racket: vợt (thể thao); tiếng ồn ào; tiếng huyên náo. Dịch cả câu: Việc cung cấp các thiết bị cơ bản như vợt thể thao có thể giúp trẻ em tiếp cận dễ dàng hơn với các môn thể thao ở trường.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_19', 'en-b1-41', NULL, 'comprehensive_test', 'reading', NULL, 'Although winning a trophy can motivate young athletes, participation should also develop teamwork and personal resilience.', 'Dựa vào câu trên, từ “trophy” có nghĩa phù hợp nhất là gì?', '["đồ lót; trang phục mặc sát da","đã đính hôn","thuộc về miền Nam; ở phía nam","cúp; giải thưởng"]'::jsonb, 3, 'trophy: cúp; giải thưởng; chiến lợi phẩm; vật lưu niệm chiến thắng. Dịch cả câu: Mặc dù việc giành được cúp có thể khích lệ các vận động viên trẻ, nhưng sự tham gia cũng cần bồi dưỡng tinh thần đồng đội và khả năng phục hồi cá nhân.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_20', 'en-b1-41', NULL, 'comprehensive_test', 'reading', NULL, 'Young athletes need balanced training programmes that protect their health while allowing them to pursue sporting excellence.', 'Dựa vào câu trên, từ “athlete” có nghĩa phù hợp nhất là gì?', '["hàng hóa trong kho; nguồn dự trữ","hàng rào; rào chắn","vận động viên","có năng khiếu; có tài"]'::jsonb, 2, 'athlete: vận động viên. Dịch cả câu: Các vận động viên trẻ cần có các chương trình tập luyện cân bằng nhằm bảo vệ sức khỏe đồng thời vươn tới đỉnh cao thể thao.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_21', 'en-b1-41', NULL, 'comprehensive_test', 'reading', NULL, 'A local sports league can strengthen community ties by bringing together players from different social backgrounds.', 'Dựa vào câu trên, từ “league” có nghĩa phù hợp nhất là gì?', '["bóng; sáng lấp lánh","sự đến; sự cập bến; sự tới nơi","đi lấy; mang về; tìm và mang đến","giải đấu thể thao"]'::jsonb, 3, 'league: giải đấu thể thao; liên minh; hiệp hội; đẳng cấp; cấp độ. Dịch cả câu: Một giải đấu thể thao địa phương có thể thắt chặt tình đoàn kết cộng đồng bằng cách quy tụ các cầu thủ từ các tầng lớp xã hội khác nhau.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_22', 'en-b1-41', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giải vô địch; cuộc thi vô địch”', '["intermediate","championship","economic","campaign"]'::jsonb, 1, 'giải vô địch; cuộc thi vô địch → championship (/ˈtʃæmpiənʃɪp/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_23', 'en-b1-41', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đội trưởng; thuyền trưởng; cơ trưởng”', '["complaint","stir","captain","amaze"]'::jsonb, 2, 'đội trưởng; thuyền trưởng; cơ trưởng → captain (/ˈkæptɪn/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_41_24', 'en-b1-41', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “độc mộc; thuyền chèo tay”', '["canoe","culture","litter","treasure"]'::jsonb, 0, 'độc mộc; thuyền chèo tay → canoe (/kəˈnuː/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-42', 'en', 'Bài 42: Thể thao & Vận động (2) - CEFR B1', 'CEFR B1', 'B1 · Thể thao', '14 từ vựng Tiếng Anh CEFR B1 chủ đề thể thao & vận động kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3042, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kayak', 'en-b1-42', 'kayak', '/ˈkaɪæk/', 'B1', 'thuyền kayak; thuyền độc mộc thể thao; chèo thuyền kayak', 'n.', 'kayaking (n.), kayaker (n.)', NULL, 'kayak thường sử dụng mái chèo hai đầu; trong khi canoe thường dùng mái chèo một đầu.', 'She paddled her kayak gently across the quiet lake.', NULL, 'Cô ấy nhẹ nhàng chèo chiếc thuyền kayak lướt qua mặt hồ phẳng lặng.', '{"wordId":"kayak","ukIpa":"/ˈkaɪæk/","usIpa":"/ˈkaɪæk/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"A narrow boat moved with a paddle having two blades.","vi":"thuyền kayak; thuyền độc mộc thể thao"},{"pos":"v.","en":"To travel across water in a kayak.","vi":"chèo thuyền kayak"}],"examples":[{"en":"She paddled her kayak gently across the quiet lake.","vi":"Cô ấy nhẹ nhàng chèo chiếc thuyền kayak lướt qua mặt hồ phẳng lặng.","audioKind":"ex"},{"en":"Exploring coastal areas by kayak allows tourists to enjoy natural scenery without producing engine noise.","vi":"Việc khám phá các vùng ven biển bằng thuyền kayak cho phép du khách thưởng ngoạn phong cảnh thiên nhiên mà không tạo ra tiếng ồn động cơ.","audioKind":"ex2"}],"collocations":[{"en":"a sea kayak","vi":"thuyền kayak vượt biển"},{"en":"paddle a kayak","vi":"chèo thuyền kayak"},{"en":"go kayaking","vi":"đi chèo thuyền kayak"}],"wordFamily":["kayaking (n.)","kayaker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"kayak thường sử dụng mái chèo hai đầu; trong khi canoe thường dùng mái chèo một đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_defeat', 'en-b1-42', 'defeat', '/dɪˈfiːt/', 'B1', 'đánh bại; chiến thắng; sự thất bại; trận thua; làm thất bại; làm chệch hướng', 'v.', 'defeated (adj.), undefeated (adj.), defeatist (n.), defeatism (n.)', 'Đồng nghĩa: beat, overcome · Trái nghĩa: victory', 'defeat đi với đối thủ; win đi với cuộc thi, giải thưởng,...', 'Our team defeated the champions in a thrilling final.', NULL, 'Đội của chúng tôi đã đánh bại đương kim vô địch trong một trận chung kết nghẹt thở.', '{"wordId":"defeat","ukIpa":"/dɪˈfiːt/","usIpa":"/dɪˈfiːt/","cefr":"B1","topic":"sport","senses":[{"pos":"v.","en":"to win against someone in a competition or conflict","vi":"đánh bại; chiến thắng"},{"pos":"n.","en":"an occasion when someone loses a competition or conflict","vi":"sự thất bại; trận thua"},{"pos":"v.","en":"to prevent a plan or aim from succeeding","vi":"làm thất bại; làm chệch hướng"}],"examples":[{"en":"Our team defeated the champions in a thrilling final.","vi":"Đội của chúng tôi đã đánh bại đương kim vô địch trong một trận chung kết nghẹt thở.","audioKind":"ex"},{"en":"Although electoral defeat can damage a political party, it may also encourage necessary changes in leadership and policy.","vi":"Mặc dù thất bại trong bầu cử có thể gây tổn hại cho một chính đảng, nhưng nó cũng có thể thúc đẩy những thay đổi cần thiết về lãnh đạo và chính sách.","audioKind":"ex2"}],"collocations":[{"en":"defeat an opponent","vi":"đánh bại đối thủ"},{"en":"suffer a defeat","vi":"gánh chịu thất bại"},{"en":"admit defeat","vi":"thừa nhận thất bại"},{"en":"defeat the purpose","vi":"làm mất mục đích"}],"wordFamily":["defeated (adj.)","undefeated (adj.)","defeatist (n.)","defeatism (n.)"],"synonyms":["beat","overcome"],"antonyms":["victory"],"tipVi":"defeat đi với đối thủ; win đi với cuộc thi, giải thưởng,...","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shot', 'en-b1-42', 'shot', '/ʃɑt/', 'B1', 'cú sút; phát súng; cú đánh bóng; bức ảnh; cảnh quay; sự thử sức; cơ hội', 'n.', 'shoot (v.), shooting (n.)', 'Đồng nghĩa: attempt, photograph', 'give it a shot nghĩa là thử một phen; shot đồng thời là dạng quá khứ của shoot.', 'Her final shot sent the ball into the net.', NULL, 'Cú sút quyết định của cô ấy đã đưa bóng bay thẳng vào lưới.', '{"wordId":"shot","ukIpa":"/ʃɒt/","usIpa":"/ʃɑt/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"an act of firing a weapon or sending a ball","vi":"cú sút; phát súng; cú đánh bóng"},{"pos":"n.","en":"a photograph or a continuous piece of filmed action","vi":"bức ảnh; cảnh quay"},{"pos":"n.","en":"an attempt to achieve or do something","vi":"sự thử sức; cơ hội"}],"examples":[{"en":"Her final shot sent the ball into the net.","vi":"Cú sút quyết định của cô ấy đã đưa bóng bay thẳng vào lưới.","audioKind":"ex"},{"en":"A carefully chosen shot can communicate the effects of environmental damage more powerfully than statistics.","vi":"Một bức ảnh được lựa chọn kỹ càng có thể truyền tải tác động của ô nhiễm môi trường mạnh mẽ hơn cả số liệu thống kê.","audioKind":"ex2"}],"collocations":[{"en":"take a shot","vi":"thực hiện cú sút; chụp ảnh"},{"en":"a close-up shot","vi":"cảnh quay cận cảnh"},{"en":"give it a shot","vi":"thử một phen"},{"en":"a shot at success","vi":"cơ hội thành công"}],"wordFamily":["shoot (v.)","shooting (n.)"],"synonyms":["attempt","photograph"],"antonyms":[],"tipVi":"give it a shot nghĩa là thử một phen; shot đồng thời là dạng quá khứ của shoot.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surf', 'en-b1-42', 'surf', '/sɝːf/', 'B1', 'lướt sóng; lướt web; bọt sóng; sóng bạc đầu', 'v.', 'surfer (n.), surfing (n.), surfboard (n.)', NULL, 'surf the internet chỉ việc lướt web, không nhất thiết có mục đích tìm kiếm cụ thể.', 'My cousin learned to surf during our beach holiday.', NULL, 'Anh họ tôi đã học lướt sóng trong kỳ nghỉ ở bãi biển của chúng tôi.', '{"wordId":"surf","ukIpa":"/sɜːf/","usIpa":"/sɝːf/","cefr":"B1","topic":"sport","senses":[{"pos":"v.","en":"to ride ocean waves while standing or lying on a board","vi":"lướt sóng"},{"pos":"v.","en":"to browse websites, often without a specific purpose","vi":"lướt web"},{"pos":"n.","en":"waves and white foam breaking near the shore","vi":"bọt sóng; sóng bạc đầu"}],"examples":[{"en":"My cousin learned to surf during our beach holiday.","vi":"Anh họ tôi đã học lướt sóng trong kỳ nghỉ ở bãi biển của chúng tôi.","audioKind":"ex"},{"en":"Students who surf the internet for research need skills to distinguish reliable sources from misleading information.","vi":"Những sinh viên lướt Internet để nghiên cứu cần có kỹ năng phân biệt giữa các nguồn đáng tin cậy và thông tin gây hiểu lầm.","audioKind":"ex2"}],"collocations":[{"en":"learn to surf","vi":"học lướt sóng"},{"en":"surf the internet","vi":"lướt Internet"},{"en":"surf the waves","vi":"cưỡi sóng"}],"wordFamily":["surfer (n.)","surfing (n.)","surfboard (n.)"],"synonyms":[],"antonyms":[],"tipVi":"surf the internet chỉ việc lướt web, không nhất thiết có mục đích tìm kiếm cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_canoeing', 'en-b1-42', 'canoeing', '/kəˈnuːɪŋ/', 'B1', 'môn chèo thuyền độc mộc', 'n.', 'canoe (n.), canoe (v.), canoeist (n.)', NULL, 'Thường dùng go canoeing; khi thêm đuôi -ing vào canoe thì giữ nguyên chữ e.', 'We went canoeing on the lake before lunch.', NULL, 'Chúng tôi đã đi chèo thuyền độc mộc trên hồ trước bữa trưa.', '{"wordId":"canoeing","ukIpa":"/kəˈnuːɪŋ/","usIpa":"/kəˈnuːɪŋ/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"the activity of travelling in a canoe using a paddle","vi":"môn chèo thuyền độc mộc"}],"examples":[{"en":"We went canoeing on the lake before lunch.","vi":"Chúng tôi đã đi chèo thuyền độc mộc trên hồ trước bữa trưa.","audioKind":"ex"},{"en":"Outdoor activities such as canoeing can improve physical fitness while encouraging young people to appreciate natural environments.","vi":"Các hoạt động ngoài trời như chèo thuyền độc mộc có thể cải thiện thể lực đồng thời khuyến khích giới trẻ trân trọng môi trường tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"go canoeing","vi":"đi chèo thuyền độc mộc"},{"en":"canoeing trip","vi":"chuyến đi chèo thuyền độc mộc"},{"en":"canoeing equipment","vi":"dụng cụ chèo thuyền độc mộc"}],"wordFamily":["canoe (n.)","canoe (v.)","canoeist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng go canoeing; khi thêm đuôi -ing vào canoe thì giữ nguyên chữ e.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_waterskiing', 'en-b1-42', 'waterskiing', '/ˈwɔːtərˌskiːɪŋ/', 'B1', 'trò lướt ván nước', 'n.', 'waterski (v.), waterskier (n.)', NULL, 'Là danh từ không đếm được khi chỉ môn thể thao; đi lướt ván nước dùng go waterskiing.', 'We tried waterskiing on the lake last summer.', NULL, 'Chúng tôi đã thử lướt ván nước trên hồ vào mùa hè năm ngoái.', '{"wordId":"waterskiing","ukIpa":"/ˈwɔːtəˌskiːɪŋ/","usIpa":"/ˈwɔːtərˌskiːɪŋ/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"Travelling over water on skis while pulled by a boat.","vi":"trò lướt ván nước"}],"examples":[{"en":"We tried waterskiing on the lake last summer.","vi":"Chúng tôi đã thử lướt ván nước trên hồ vào mùa hè năm ngoái.","audioKind":"ex"},{"en":"Waterskiing can attract tourists to lakeside communities, but motorboats may disturb wildlife and increase water pollution.","vi":"Trò lướt ván nước có thể thu hút khách du lịch đến các cộng đồng ven hồ, nhưng xuồng máy có thể làm phiền động vật hoang dã và làm tăng tình trạng ô nhiễm nguồn nước.","audioKind":"ex2"}],"collocations":[{"en":"go waterskiing","vi":"đi lướt ván nước"},{"en":"waterskiing lessons","vi":"các bài học lướt ván nước"},{"en":"waterskiing equipment","vi":"trang thiết bị lướt ván nước"}],"wordFamily":["waterski (v.)","waterskier (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được khi chỉ môn thể thao; đi lướt ván nước dùng go waterskiing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sportswear', 'en-b1-42', 'sportswear', '/ˈspɔːrtswer/', 'B1', 'quần áo thể thao; trang phục thể thao', 'n.', 'sport (n.), sporty (adj.)', NULL, 'Là danh từ không đếm được; một bộ đồ thể thao dùng an item of sportswear.', 'She changed into comfortable sportswear before her evening run.', NULL, 'Cô ấy đã thay sang bộ đồ thể thao thoải mái trước buổi chạy bộ buổi tối.', '{"wordId":"sportswear","ukIpa":"/ˈspɔːtsweə/","usIpa":"/ˈspɔːrtswer/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"Clothes designed for sport or worn in a sporty casual style.","vi":"quần áo thể thao; trang phục thể thao"}],"examples":[{"en":"She changed into comfortable sportswear before her evening run.","vi":"Cô ấy đã thay sang bộ đồ thể thao thoải mái trước buổi chạy bộ buổi tối.","audioKind":"ex"},{"en":"Demand for affordable sportswear may increase as more people participate in regular exercise and community sports.","vi":"Nhu cầu về trang phục thể thao giá cả phải chăng có thể tăng lên khi ngày càng có nhiều người tham gia tập thể dục thường xuyên và các hoạt động thể thao cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"comfortable sportswear","vi":"trang phục thể thao thoải mái"},{"en":"a sportswear retailer","vi":"nhà bán lẻ trang phục thể thao"},{"en":"a range of sportswear","vi":"nhiều loại trang phục thể thao"}],"wordFamily":["sport (n.)","sporty (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; một bộ đồ thể thao dùng an item of sportswear.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gymnastics', 'en-b1-42', 'gymnastics', '/dʒɪmˈnæstɪks/', 'B1', 'môn thể dục dụng cụ; nghệ thuật thể dục', 'n.', 'gymnast (n.), gymnastic (adj.)', NULL, 'Mặc dù tận cùng bằng -s, khi chỉ môn thể thao thì dùng động từ số ít: gymnastics is.', 'My sister practises gymnastics at the local sports centre.', NULL, 'Chị tôi tập thể dục dụng cụ tại trung tâm thể thao địa phương.', '{"wordId":"gymnastics","ukIpa":"/dʒɪmˈnæstɪks/","usIpa":"/dʒɪmˈnæstɪks/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"A sport involving controlled movements that develop strength, balance, and flexibility.","vi":"môn thể dục dụng cụ; nghệ thuật thể dục"}],"examples":[{"en":"My sister practises gymnastics at the local sports centre.","vi":"Chị tôi tập thể dục dụng cụ tại trung tâm thể thao địa phương.","audioKind":"ex"},{"en":"Including gymnastics in school programmes can help children develop coordination, physical confidence, and an interest in exercise.","vi":"Đưa môn thể dục dụng cụ vào chương trình học có thể giúp trẻ phát triển sự phối hợp, sự tự tin về thể chất và nuôi dưỡng niềm đam mê tập luyện.","audioKind":"ex2"}],"collocations":[{"en":"do gymnastics","vi":"tập thể dục dụng cụ"},{"en":"artistic gymnastics","vi":"thể dục dụng cụ nghệ thuật"},{"en":"rhythmic gymnastics","vi":"thể dục nhịp điệu"}],"wordFamily":["gymnast (n.)","gymnastic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Mặc dù tận cùng bằng -s, khi chỉ môn thể thao thì dùng động từ số ít: gymnastics is.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bounce', 'en-b1-42', 'bounce', '/baʊns/', 'B1', 'nảy lên; làm nảy lên; sự nảy lên; sự phản hồi; bị ngân hàng từ chối thanh toán do không đủ tiền', 'v.', 'bouncy (adj.)', 'Đồng nghĩa: rebound', 'bounce back vừa có nghĩa là bật lại, vừa thường chỉ việc phục hồi sau khi gặp khó khăn, trắc trở.', 'The ball bounced over the fence into our neighbour''s garden.', NULL, 'Quả bóng nảy qua hàng rào vào khu vườn nhà hàng xóm.', '{"wordId":"bounce","ukIpa":"/baʊns/","usIpa":"/baʊns/","cefr":"B1","topic":"sport","senses":[{"pos":"v.","en":"move back up after hitting a surface, or cause this","vi":"nảy lên; làm nảy lên"},{"pos":"n.","en":"a movement back up after hitting a surface","vi":"sự nảy lên; sự phản hồi"},{"pos":"v.","en":"be rejected by a bank because funds are insufficient","vi":"bị ngân hàng từ chối thanh toán do không đủ tiền"}],"examples":[{"en":"The ball bounced over the fence into our neighbour''s garden.","vi":"Quả bóng nảy qua hàng rào vào khu vườn nhà hàng xóm.","audioKind":"ex"},{"en":"Local businesses can bounce back after economic shocks if they receive timely financial support.","vi":"Các doanh nghiệp địa phương có thể phục hồi sau các cú sốc kinh tế nếu nhận được hỗ trợ tài chính kịp thời.","audioKind":"ex2"}],"collocations":[{"en":"bounce a ball","vi":"đập bóng"},{"en":"bounce back","vi":"phục hồi"},{"en":"a cheque bounces","vi":"séc bị trả về"},{"en":"bounce ideas off someone","vi":"trao đổi ý kiến với ai đó"}],"wordFamily":["bouncy (adj.)"],"synonyms":["rebound"],"antonyms":[],"tipVi":"bounce back vừa có nghĩa là bật lại, vừa thường chỉ việc phục hồi sau khi gặp khó khăn, trắc trở.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rafting', 'en-b1-42', 'rafting', '/ˈræftɪŋ/', 'B1', 'môn thể thao chèo bè; đi bè vượt thác', 'n.', 'raft (n.), raft (v.), rafter (n.)', NULL, 'Nghĩa thể thao thường dùng cấu trúc go rafting; raft cũng có nghĩa là chiếc bè.', 'We went rafting down a mountain river last weekend.', NULL, 'Chúng tôi đã đi chèo bè trên một dòng sông miền núi vào cuối tuần trước.', '{"wordId":"rafting","ukIpa":"/ˈrɑːftɪŋ/","usIpa":"/ˈræftɪŋ/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"Travelling down a river on a raft for pleasure.","vi":"môn thể thao chèo bè; đi bè vượt thác"}],"examples":[{"en":"We went rafting down a mountain river last weekend.","vi":"Chúng tôi đã đi chèo bè trên một dòng sông miền núi vào cuối tuần trước.","audioKind":"ex"},{"en":"Rafting can support rural tourism, but operators must provide safety equipment and protect river habitats.","vi":"Hoạt động chèo bè có thể hỗ trợ du lịch nông thôn, nhưng các đơn vị tổ chức phải cung cấp trang thiết bị an toàn và bảo vệ môi trường sông nước.","audioKind":"ex2"}],"collocations":[{"en":"go rafting","vi":"đi chèo bè vượt thác"},{"en":"white-water rafting","vi":"chèo bè vượt ghềnh thác"},{"en":"rafting trip","vi":"chuyến đi chèo bè"}],"wordFamily":["raft (n.)","raft (v.)","rafter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa thể thao thường dùng cấu trúc go rafting; raft cũng có nghĩa là chiếc bè.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tournament', 'en-b1-42', 'tournament', '/ˈtʊrnəmənt/', 'B1', 'giải đấu; cuộc thi đấu', 'n.', NULL, NULL, 'Thường bao gồm nhiều trận đấu; trận đấu đơn lẻ thường dùng match hoặc game.', 'Our school tennis tournament starts next Saturday morning.', NULL, 'Giải đấu quần vợt của trường chúng tôi bắt đầu vào sáng thứ Bảy tuần tới.', '{"wordId":"tournament","ukIpa":"/ˈtʊənəmənt/","usIpa":"/ˈtʊrnəmənt/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"a competition involving several games between different players or teams","vi":"giải đấu; cuộc thi đấu"}],"examples":[{"en":"Our school tennis tournament starts next Saturday morning.","vi":"Giải đấu quần vợt của trường chúng tôi bắt đầu vào sáng thứ Bảy tuần tới.","audioKind":"ex"},{"en":"Hosting an international tournament can boost tourism, but maintaining sports facilities afterwards may prove expensive.","vi":"Tổ chức một giải đấu quốc tế có thể thúc đẩy ngành du lịch, nhưng việc bảo trì các cơ sở thể thao sau đó có thể tốn kém.","audioKind":"ex2"}],"collocations":[{"en":"host a tournament","vi":"đăng cai giải đấu"},{"en":"enter a tournament","vi":"tham gia giải đấu"},{"en":"win a tournament","vi":"giành chiến thắng trong giải đấu"},{"en":"tennis tournament","vi":"giải đấu quần vợt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường bao gồm nhiều trận đấu; trận đấu đơn lẻ thường dùng match hoặc game.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_racing', 'en-b1-42', 'racing', '/ˈreɪsɪŋ/', 'B1', 'cuộc đua tốc độ; môn đua; dùng cho việc đua', 'n.', 'race (n.), race (v.), racer (n.)', NULL, 'Dùng làm tên môn thể thao thường không đếm được; một cuộc đua dùng "a race".', 'My cousin enjoys watching bicycle racing on weekend afternoons.', NULL, 'Anh họ tôi thích xem đua xe đạp vào các buổi chiều cuối tuần.', '{"wordId":"racing","ukIpa":"/ˈreɪsɪŋ/","usIpa":"/ˈreɪsɪŋ/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"The sport of competing to move faster than others.","vi":"cuộc đua tốc độ; môn đua"},{"pos":"adj.","en":"Designed or used for races.","vi":"dùng cho việc đua"}],"examples":[{"en":"My cousin enjoys watching bicycle racing on weekend afternoons.","vi":"Anh họ tôi thích xem đua xe đạp vào các buổi chiều cuối tuần.","audioKind":"ex"},{"en":"Professional motor racing encourages technological innovation, but its environmental impact remains a subject of debate.","vi":"Môn đua xe thể thao chuyên nghiệp thúc đẩy đổi mới công nghệ, nhưng tác động môi trường của nó vẫn là chủ đề gây tranh cãi.","audioKind":"ex2"}],"collocations":[{"en":"horse racing","vi":"đua ngựa"},{"en":"motor racing","vi":"đua xe ô tô"},{"en":"a racing car","vi":"xe đua"},{"en":"a racing bike","vi":"xe đạp đua"}],"wordFamily":["race (n.)","race (v.)","racer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng làm tên môn thể thao thường không đếm được; một cuộc đua dùng \"a race\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_champion', 'en-b1-42', 'champion', '/ˈtʃæmpiən/', 'B1', 'nhà vô địch; quán quân; người ủng hộ nhiệt thành; người bảo vệ; ủng hộ; bảo vệ; đấu tranh cho', 'n.', 'championship (n.)', NULL, 'Khi làm động từ, đi thẳng với tân ngữ: champion a cause.', 'The new champion lifted her trophy with both hands.', NULL, 'Tân vương miện vô địch nâng cao chiếc cúp bằng cả hai tay.', '{"wordId":"champion","ukIpa":"/ˈtʃæmpiən/","usIpa":"/ˈtʃæmpiən/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"a person or team that wins a competition","vi":"nhà vô địch; quán quân"},{"pos":"n.","en":"someone who strongly supports a cause or group","vi":"người ủng hộ nhiệt thành; người bảo vệ"},{"pos":"v.","en":"to actively support or defend a cause or person","vi":"ủng hộ; bảo vệ; đấu tranh cho"}],"examples":[{"en":"The new champion lifted her trophy with both hands.","vi":"Tân vương miện vô địch nâng cao chiếc cúp bằng cả hai tay.","audioKind":"ex"},{"en":"Local organisations can champion affordable housing by working with residents and presenting practical proposals to councils.","vi":"Các tổ chức địa phương có thể thúc đẩy nhà ở giá rẻ bằng cách hợp tác với cư dân và đưa ra các đề xuất thiết thực cho hội đồng.","audioKind":"ex2"}],"collocations":[{"en":"world champion","vi":"vô địch thế giới"},{"en":"defending champion","vi":"nhà đương kim vô địch"},{"en":"a champion of equality","vi":"người ủng hộ sự bình đẳng"},{"en":"champion a cause","vi":"đấu tranh cho một chính nghĩa"}],"wordFamily":["championship (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi làm động từ, đi thẳng với tân ngữ: champion a cause.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_push-up', 'en-b1-42', 'push-up', '/ˈpʊʃ ʌp/', 'B1', 'động tác chống đẩy; hít đất', 'n.', 'push (v.)', 'Đồng nghĩa: press-up', 'Đây là danh từ đếm được; trong tiếng Anh-Anh người ta cũng thường dùng từ press-up.', 'I managed one push-up before my arms started shaking.', NULL, 'Tôi mới làm được một cái chống đẩy là tay đã bắt đầu run lên rồi.', '{"wordId":"push-up","ukIpa":"/ˈpʊʃ ʌp/","usIpa":"/ˈpʊʃ ʌp/","cefr":"B1","topic":"sport","senses":[{"pos":"n.","en":"An exercise raising and lowering your body using your arms.","vi":"động tác chống đẩy; hít đất"}],"examples":[{"en":"I managed one push-up before my arms started shaking.","vi":"Tôi mới làm được một cái chống đẩy là tay đã bắt đầu run lên rồi.","audioKind":"ex"},{"en":"Simple exercises such as push-ups allow people to build strength without paying for expensive gym memberships.","vi":"Các bài tập đơn giản như hít đất giúp mọi người rèn luyện thể lực mà không cần tốn tiền mua thẻ tập ở các phòng gym đắt đỏ.","audioKind":"ex2"}],"collocations":[{"en":"do push-ups","vi":"tập chống đẩy"},{"en":"a set of push-ups","vi":"một hiệp hít đất"},{"en":"wall push-up","vi":"chống đẩy dựa tường"}],"wordFamily":["push (v.)"],"synonyms":["press-up"],"antonyms":[],"tipVi":"Đây là danh từ đếm được; trong tiếng Anh-Anh người ta cũng thường dùng từ press-up.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_42_1', 'en-b1-42', 'Cách dùng “bounce” (v.) — nảy lên; làm nảy lên', 'bounce a ball  ·  bounce back  ·  a cheque bounces', 'bounce back vừa có nghĩa là bật lại, vừa thường chỉ việc phục hồi sau khi gặp khó khăn, trắc trở.', 'Họ từ (Word Family): bouncy (adj.) | Đồng nghĩa: rebound', '[{"hanzi":"The ball bounced over the fence into our neighbour''s garden.","pinyin":"","meaning":"Quả bóng nảy qua hàng rào vào khu vườn nhà hàng xóm."},{"hanzi":"Local businesses can bounce back after economic shocks if they receive timely financial support.","pinyin":"","meaning":"Các doanh nghiệp địa phương có thể phục hồi sau các cú sốc kinh tế nếu nhận được hỗ trợ tài chính kịp thời."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_42_2', 'en-b1-42', 'Cách dùng “waterskiing” (n.) — trò lướt ván nước', 'go waterskiing  ·  waterskiing lessons  ·  waterskiing equipment', 'Là danh từ không đếm được khi chỉ môn thể thao; đi lướt ván nước dùng go waterskiing.', 'Họ từ (Word Family): waterski (v.), waterskier (n.)', '[{"hanzi":"We tried waterskiing on the lake last summer.","pinyin":"","meaning":"Chúng tôi đã thử lướt ván nước trên hồ vào mùa hè năm ngoái."},{"hanzi":"Waterskiing can attract tourists to lakeside communities, but motorboats may disturb wildlife and increase water pollution.","pinyin":"","meaning":"Trò lướt ván nước có thể thu hút khách du lịch đến các cộng đồng ven hồ, nhưng xuồng máy có thể làm phiền động vật hoang dã và làm tăng tình trạng ô nhiễm nguồn nước."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_42_3', 'en-b1-42', 'Cách dùng “kayak” (n.) — thuyền kayak; thuyền độc mộc thể thao', 'a sea kayak  ·  paddle a kayak  ·  go kayaking', 'kayak thường sử dụng mái chèo hai đầu; trong khi canoe thường dùng mái chèo một đầu.', 'Họ từ (Word Family): kayaking (n.), kayaker (n.)', '[{"hanzi":"She paddled her kayak gently across the quiet lake.","pinyin":"","meaning":"Cô ấy nhẹ nhàng chèo chiếc thuyền kayak lướt qua mặt hồ phẳng lặng."},{"hanzi":"Exploring coastal areas by kayak allows tourists to enjoy natural scenery without producing engine noise.","pinyin":"","meaning":"Việc khám phá các vùng ven biển bằng thuyền kayak cho phép du khách thưởng ngoạn phong cảnh thiên nhiên mà không tạo ra tiếng ồn động cơ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_42_4', 'en-b1-42', 'Cách dùng “gymnastics” (n.) — môn thể dục dụng cụ; nghệ thuật thể dục', 'do gymnastics  ·  artistic gymnastics  ·  rhythmic gymnastics', 'Mặc dù tận cùng bằng -s, khi chỉ môn thể thao thì dùng động từ số ít: gymnastics is.', 'Họ từ (Word Family): gymnast (n.), gymnastic (adj.)', '[{"hanzi":"My sister practises gymnastics at the local sports centre.","pinyin":"","meaning":"Chị tôi tập thể dục dụng cụ tại trung tâm thể thao địa phương."},{"hanzi":"Including gymnastics in school programmes can help children develop coordination, physical confidence, and an interest in exercise.","pinyin":"","meaning":"Đưa môn thể dục dụng cụ vào chương trình học có thể giúp trẻ phát triển sự phối hợp, sự tự tin về thể chất và nuôi dưỡng niềm đam mê tập luyện."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_42_1', 'en-b1-42', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_1_1', 'ten_b1_42_1', 'kayak', 'She paddled her kayak gently across the quiet lake.', 'She paddled her kayak gently across the quiet lake.', '/ˈkaɪæk/', 'Cô ấy nhẹ nhàng chèo chiếc thuyền kayak lướt qua mặt hồ phẳng lặng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_1_2', 'ten_b1_42_1', 'defeat', 'Our team defeated the champions in a thrilling final.', 'Our team defeated the champions in a thrilling final.', '/dɪˈfiːt/', 'Đội của chúng tôi đã đánh bại đương kim vô địch trong một trận chung kết nghẹt thở.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_1_3', 'ten_b1_42_1', 'shot', 'Her final shot sent the ball into the net.', 'Her final shot sent the ball into the net.', '/ʃɑt/', 'Cú sút quyết định của cô ấy đã đưa bóng bay thẳng vào lưới.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_1_4', 'ten_b1_42_1', 'surf', 'My cousin learned to surf during our beach holiday.', 'My cousin learned to surf during our beach holiday.', '/sɝːf/', 'Anh họ tôi đã học lướt sóng trong kỳ nghỉ ở bãi biển của chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_1_5', 'ten_b1_42_1', 'canoeing', 'We went canoeing on the lake before lunch.', 'We went canoeing on the lake before lunch.', '/kəˈnuːɪŋ/', 'Chúng tôi đã đi chèo thuyền độc mộc trên hồ trước bữa trưa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_1_6', 'ten_b1_42_1', 'waterskiing', 'We tried waterskiing on the lake last summer.', 'We tried waterskiing on the lake last summer.', '/ˈwɔːtərˌskiːɪŋ/', 'Chúng tôi đã thử lướt ván nước trên hồ vào mùa hè năm ngoái.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_1_7', 'ten_b1_42_1', 'sportswear', 'She changed into comfortable sportswear before her evening run.', 'She changed into comfortable sportswear before her evening run.', '/ˈspɔːrtswer/', 'Cô ấy đã thay sang bộ đồ thể thao thoải mái trước buổi chạy bộ buổi tối.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_1_8', 'ten_b1_42_1', 'gymnastics', 'My sister practises gymnastics at the local sports centre.', 'My sister practises gymnastics at the local sports centre.', '/dʒɪmˈnæstɪks/', 'Chị tôi tập thể dục dụng cụ tại trung tâm thể thao địa phương.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_42_1_1', 'en-b1-42', 'ten_b1_42_1', 'listening', 'listening', 'She paddled her kayak gently across the quiet lake.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã thử lướt ván nước trên hồ vào mùa hè năm ngoái.","Giải đấu quần vợt của trường chúng tôi bắt đầu vào sáng thứ Bảy tuần tới.","Anh họ tôi thích xem đua xe đạp vào các buổi chiều cuối tuần.","Cô ấy nhẹ nhàng chèo chiếc thuyền kayak lướt qua mặt hồ phẳng lặng."]'::jsonb, 3, 'She paddled her kayak gently across the quiet lake. → Cô ấy nhẹ nhàng chèo chiếc thuyền kayak lướt qua mặt hồ phẳng lặng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_42_1_2', 'en-b1-42', 'ten_b1_42_1', 'listening', 'listening', 'Our team defeated the champions in a thrilling final.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã đi chèo thuyền độc mộc trên hồ trước bữa trưa.","Đội của chúng tôi đã đánh bại đương kim vô địch trong một trận chung kết nghẹt thở.","Chị tôi tập thể dục dụng cụ tại trung tâm thể thao địa phương.","Chúng tôi đã thử lướt ván nước trên hồ vào mùa hè năm ngoái."]'::jsonb, 1, 'Our team defeated the champions in a thrilling final. → Đội của chúng tôi đã đánh bại đương kim vô địch trong một trận chung kết nghẹt thở.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_42_1_3', 'en-b1-42', 'ten_b1_42_1', 'listening', 'listening', 'Her final shot sent the ball into the net.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đội của chúng tôi đã đánh bại đương kim vô địch trong một trận chung kết nghẹt thở.","Giải đấu quần vợt của trường chúng tôi bắt đầu vào sáng thứ Bảy tuần tới.","Cú sút quyết định của cô ấy đã đưa bóng bay thẳng vào lưới.","Tôi mới làm được một cái chống đẩy là tay đã bắt đầu run lên rồi."]'::jsonb, 2, 'Her final shot sent the ball into the net. → Cú sút quyết định của cô ấy đã đưa bóng bay thẳng vào lưới.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_42_2', 'en-b1-42', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_2_1', 'ten_b1_42_2', 'kayak', 'Exploring coastal areas by kayak allows tourists to enjoy natural scenery without producing engine noise.', 'Exploring coastal areas by kayak allows tourists to enjoy natural scenery without producing engine noise.', '/ˈkaɪæk/', 'Việc khám phá các vùng ven biển bằng thuyền kayak cho phép du khách thưởng ngoạn phong cảnh thiên nhiên mà không tạo ra tiếng ồn động cơ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_2_2', 'ten_b1_42_2', 'defeat', 'Although electoral defeat can damage a political party, it may also encourage necessary changes in leadership and policy.', 'Although electoral defeat can damage a political party, it may also encourage necessary changes in leadership and policy.', '/dɪˈfiːt/', 'Mặc dù thất bại trong bầu cử có thể gây tổn hại cho một chính đảng, nhưng nó cũng có thể thúc đẩy những thay đổi cần thiết về lãnh đạo và chính sách.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_2_3', 'ten_b1_42_2', 'shot', 'A carefully chosen shot can communicate the effects of environmental damage more powerfully than statistics.', 'A carefully chosen shot can communicate the effects of environmental damage more powerfully than statistics.', '/ʃɑt/', 'Một bức ảnh được lựa chọn kỹ càng có thể truyền tải tác động của ô nhiễm môi trường mạnh mẽ hơn cả số liệu thống kê.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_2_4', 'ten_b1_42_2', 'surf', 'Students who surf the internet for research need skills to distinguish reliable sources from misleading information.', 'Students who surf the internet for research need skills to distinguish reliable sources from misleading information.', '/sɝːf/', 'Những sinh viên lướt Internet để nghiên cứu cần có kỹ năng phân biệt giữa các nguồn đáng tin cậy và thông tin gây hiểu lầm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_2_5', 'ten_b1_42_2', 'canoeing', 'Outdoor activities such as canoeing can improve physical fitness while encouraging young people to appreciate natural environments.', 'Outdoor activities such as canoeing can improve physical fitness while encouraging young people to appreciate natural environments.', '/kəˈnuːɪŋ/', 'Các hoạt động ngoài trời như chèo thuyền độc mộc có thể cải thiện thể lực đồng thời khuyến khích giới trẻ trân trọng môi trường tự nhiên.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_42_2_6', 'ten_b1_42_2', 'waterskiing', 'Waterskiing can attract tourists to lakeside communities, but motorboats may disturb wildlife and increase water pollution.', 'Waterskiing can attract tourists to lakeside communities, but motorboats may disturb wildlife and increase water pollution.', '/ˈwɔːtərˌskiːɪŋ/', 'Trò lướt ván nước có thể thu hút khách du lịch đến các cộng đồng ven hồ, nhưng xuồng máy có thể làm phiền động vật hoang dã và làm tăng tình trạng ô nhiễm nguồn nước.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_42_2_1', 'en-b1-42', 'ten_b1_42_2', 'listening', 'listening', 'Exploring coastal areas by kayak allows tourists to enjoy natural scenery without producing engine noise.', NULL, 'Trong câu vừa nghe, từ “kayak” mang nghĩa nào sau đây?', '["cảng; thành phố cảng","trượt; di chuyển trơn tru","chim đại bàng; con đại bàng","thuyền kayak; thuyền độc mộc thể thao"]'::jsonb, 3, '“kayak” (/ˈkaɪæk/): thuyền kayak; thuyền độc mộc thể thao. Câu đầy đủ: Exploring coastal areas by kayak allows tourists to enjoy natural scenery without producing engine noise.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_42_2_2', 'en-b1-42', 'ten_b1_42_2', 'listening', 'listening', 'Although electoral defeat can damage a political party, it may also encourage necessary changes in leadership and policy.', NULL, 'Trong câu vừa nghe, từ “defeat” mang nghĩa nào sau đây?', '["hoạt động buôn bán, giao thương hàng hóa hoặc dịch vụ","chất độc; thuốc độc","bày tỏ; thể hiện; diễn đạt","đánh bại; chiến thắng"]'::jsonb, 3, '“defeat” (/dɪˈfiːt/): đánh bại; chiến thắng. Câu đầy đủ: Although electoral defeat can damage a political party, it may also encourage necessary changes in leadership and policy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
