INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_42_4', 'en-b1-42', 'My cousin learned to surf during our beach holiday', 'Anh họ tôi đã học lướt sóng trong kỳ nghỉ ở bãi biển của chúng tôi.', 'surf /sɝːf/', '["My","beach","to","during","holiday","cousin","surf","our","learned"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
