INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_42_6', 'en-b1-42', 'We tried waterskiing on the lake last summer', 'Chúng tôi đã thử lướt ván nước trên hồ vào mùa hè năm ngoái.', 'waterskiing /ˈwɔːtərˌskiːɪŋ/', '["on","tried","last","lake","We","the","waterskiing","summer"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_42_7', 'en-b1-42', 'She changed into comfortable sportswear before her evening run', 'Cô ấy đã thay sang bộ đồ thể thao thoải mái trước buổi chạy bộ buổi tối.', 'sportswear /ˈspɔːrtswer/', '["evening","She","before","run","sportswear","her","comfortable","changed","into"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
