INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_42_9', 'en-b1-42', 'The ball bounced over the fence into our neighbour''s garden', 'Quả bóng nảy qua hàng rào vào khu vườn nhà hàng xóm.', 'bounce /baʊns/', '["over","our","into","the","fence","The","ball","bounced","neighbour''s","garden"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_42_10', 'en-b1-42', 'We went rafting down a mountain river last weekend', 'Chúng tôi đã đi chèo bè trên một dòng sông miền núi vào cuối tuần trước.', 'rafting /ˈræftɪŋ/', '["river","last","down","weekend","We","went","a","rafting","mountain"]'::jsonb, NULL, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
