INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_42_2', 'en-b1-42', NULL, 'comprehensive_test', 'listening', 'Our team defeated the champions in a thrilling final.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy nhẹ nhàng chèo chiếc thuyền kayak lướt qua mặt hồ phẳng lặng.","Đội của chúng tôi đã đánh bại đương kim vô địch trong một trận chung kết nghẹt thở.","Chị tôi tập thể dục dụng cụ tại trung tâm thể thao địa phương.","Chúng tôi đã đi chèo bè trên một dòng sông miền núi vào cuối tuần trước."]'::jsonb, 1, 'Our team defeated the champions in a thrilling final. → Đội của chúng tôi đã đánh bại đương kim vô địch trong một trận chung kết nghẹt thở.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_42_3', 'en-b1-42', NULL, 'comprehensive_test', 'listening', 'shot', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đã đính hôn","dịch; dịch thuật","cú sút; phát súng; cú đánh bóng","sự giao tiếp; sự trao đổi; sự liên lạc"]'::jsonb, 2, 'shot (/ʃɑt/) → cú sút; phát súng; cú đánh bóng; bức ảnh; cảnh quay; sự thử sức; cơ hội', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_42_4', 'en-b1-42', NULL, 'comprehensive_test', 'listening', 'My cousin learned to surf during our beach holiday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh họ tôi đã học lướt sóng trong kỳ nghỉ ở bãi biển của chúng tôi.","Cô ấy nhẹ nhàng chèo chiếc thuyền kayak lướt qua mặt hồ phẳng lặng.","Anh họ tôi thích xem đua xe đạp vào các buổi chiều cuối tuần.","Giải đấu quần vợt của trường chúng tôi bắt đầu vào sáng thứ Bảy tuần tới."]'::jsonb, 0, 'My cousin learned to surf during our beach holiday. → Anh họ tôi đã học lướt sóng trong kỳ nghỉ ở bãi biển của chúng tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
