INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_42_18', 'en-b1-42', NULL, 'comprehensive_test', 'reading', NULL, 'Exploring coastal areas by kayak allows tourists to enjoy natural scenery without producing engine noise.', 'Dựa vào câu trên, từ “kayak” có nghĩa phù hợp nhất là gì?', '["giấy phép; bằng lái; chứng chỉ","tương tự; giống như vậy","thuyền kayak; thuyền độc mộc thể thao","làm mệt mỏi; mệt mỏi"]'::jsonb, 2, 'kayak: thuyền kayak; thuyền độc mộc thể thao; chèo thuyền kayak. Dịch cả câu: Việc khám phá các vùng ven biển bằng thuyền kayak cho phép du khách thưởng ngoạn phong cảnh thiên nhiên mà không tạo ra tiếng ồn động cơ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_42_19', 'en-b1-42', NULL, 'comprehensive_test', 'reading', NULL, 'Although electoral defeat can damage a political party, it may also encourage necessary changes in leadership and policy.', 'Dựa vào câu trên, từ “defeat” có nghĩa phù hợp nhất là gì?', '["cây sáo (nhạc cụ hơi)","con dơi (thú bay hoạt động chủ yếu về đêm)","cuộc cãi vã; sự tranh cãi","đánh bại; chiến thắng"]'::jsonb, 3, 'defeat: đánh bại; chiến thắng; sự thất bại; trận thua; làm thất bại; làm chệch hướng. Dịch cả câu: Mặc dù thất bại trong bầu cử có thể gây tổn hại cho một chính đảng, nhưng nó cũng có thể thúc đẩy những thay đổi cần thiết về lãnh đạo và chính sách.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_42_20', 'en-b1-42', NULL, 'comprehensive_test', 'reading', NULL, 'A carefully chosen shot can communicate the effects of environmental damage more powerfully than statistics.', 'Dựa vào câu trên, từ “shot” có nghĩa phù hợp nhất là gì?', '["lời cảnh báo; sự nhắc nhở","thuốc giảm đau","giới từ","cú sút; phát súng; cú đánh bóng"]'::jsonb, 3, 'shot: cú sút; phát súng; cú đánh bóng; bức ảnh; cảnh quay; sự thử sức; cơ hội. Dịch cả câu: Một bức ảnh được lựa chọn kỹ càng có thể truyền tải tác động của ô nhiễm môi trường mạnh mẽ hơn cả số liệu thống kê.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_42_21', 'en-b1-42', NULL, 'comprehensive_test', 'reading', NULL, 'Students who surf the internet for research need skills to distinguish reliable sources from misleading information.', 'Dựa vào câu trên, từ “surf” có nghĩa phù hợp nhất là gì?', '["xử lý; giải quyết; đối phó","lướt sóng","lặp đi lặp lại; nhiều lần","thuộc về lịch sử; có liên quan đến các sự kiện trong quá khứ"]'::jsonb, 1, 'surf: lướt sóng; lướt web; bọt sóng; sóng bạc đầu. Dịch cả câu: Những sinh viên lướt Internet để nghiên cứu cần có kỹ năng phân biệt giữa các nguồn đáng tin cậy và thông tin gây hiểu lầm.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_42_22', 'en-b1-42', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cuộc đua tốc độ; môn đua”', '["survey","racing","element","rail"]'::jsonb, 1, 'cuộc đua tốc độ; môn đua → racing (/ˈreɪsɪŋ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_42_23', 'en-b1-42', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhà vô địch; quán quân”', '["insist","champion","accommodation","lately"]'::jsonb, 1, 'nhà vô địch; quán quân → champion (/ˈtʃæmpiən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_42_24', 'en-b1-42', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “động tác chống đẩy; hít đất”', '["employer","push-up","vet","content"]'::jsonb, 1, 'động tác chống đẩy; hít đất → push-up (/ˈpʊʃ ʌp/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-43', 'en', 'Bài 43: Công nghệ & Kỹ thuật (1) - CEFR B1', 'CEFR B1', 'B1 · Công nghệ', '15 từ vựng Tiếng Anh CEFR B1 chủ đề công nghệ & kỹ thuật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3043, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_update', 'en-b1-43', 'update', '/ˌʌpˈdeɪt/', 'B1', 'cập nhật; làm cho mới nhất; thông tin mới nhất; bản cập nhật', 'v.', 'updated (adj.)', NULL, 'Động từ nhấn trọng âm ở âm tiết sau; danh từ nhấn trọng âm ở âm tiết đầu, phát âm là /ˈʌpdeɪt/.', 'Please update your address before we send the parcel.', NULL, 'Vui lòng cập nhật địa chỉ của bạn trước khi chúng tôi gửi bưu kiện.', '{"wordId":"update","ukIpa":"/ˌʌpˈdeɪt/","usIpa":"/ˌʌpˈdeɪt/","cefr":"B1","topic":"technology","senses":[{"pos":"v.","en":"to make something current or give someone the latest information","vi":"cập nhật; làm cho mới nhất"},{"pos":"n.","en":"new information or a change that makes something more current","vi":"thông tin mới nhất; bản cập nhật"}],"examples":[{"en":"Please update your address before we send the parcel.","vi":"Vui lòng cập nhật địa chỉ của bạn trước khi chúng tôi gửi bưu kiện.","audioKind":"ex"},{"en":"Governments should regularly update environmental regulations to reflect scientific discoveries and respond to emerging risks.","vi":"Chính phủ nên thường xuyên cập nhật các quy định về môi trường để phản ánh các phát hiện khoa học và ứng phó với các rủi ro mới nổi.","audioKind":"ex2"}],"collocations":[{"en":"update software","vi":"cập nhật phần mềm"},{"en":"update someone on something","vi":"cập nhật thông tin cho ai đó về việc gì"},{"en":"a software update","vi":"bản cập nhật phần mềm"},{"en":"regular updates","vi":"các bản cập nhật thường xuyên"}],"wordFamily":["updated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ nhấn trọng âm ở âm tiết sau; danh từ nhấn trọng âm ở âm tiết đầu, phát âm là /ˈʌpdeɪt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_access', 'en-b1-43', 'access', '/ˈækses/', 'B1', 'quyền sử dụng; cơ hội tiếp cận; lối vào; đường vào; truy cập; tiếp cận; lấy', 'n.', 'accessible (adj.), inaccessible (adj.), accessibility (n.)', NULL, 'Danh từ đi với to; động từ trực tiếp đi với tân ngữ, không thêm to.', 'Guests have access to the pool until sunset.', NULL, 'Khách lưu trú được sử dụng hồ bơi cho đến khi mặt trời lặn.', '{"wordId":"access","ukIpa":"/ˈækses/","usIpa":"/ˈækses/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"The opportunity or right to enter or use something.","vi":"quyền sử dụng; cơ hội tiếp cận"},{"pos":"n.","en":"A way of reaching or entering a place.","vi":"lối vào; đường vào"},{"pos":"v.","en":"Reach, enter, or obtain something, especially information on a computer.","vi":"truy cập; tiếp cận; lấy"}],"examples":[{"en":"Guests have access to the pool until sunset.","vi":"Khách lưu trú được sử dụng hồ bơi cho đến khi mặt trời lặn.","audioKind":"ex"},{"en":"Affordable internet access enables rural students to benefit from a wider range of educational resources.","vi":"Khả năng tiếp cận internet giá rẻ giúp học sinh nông thôn tiếp cận được nhiều nguồn tài nguyên giáo dục phong phú hơn.","audioKind":"ex2"}],"collocations":[{"en":"access to education","vi":"cơ hội tiếp cận giáo dục"},{"en":"internet access","vi":"truy cập internet"},{"en":"gain access to","vi":"có được quyền tiếp cận"},{"en":"access information","vi":"truy cập thông tin"}],"wordFamily":["accessible (adj.)","inaccessible (adj.)","accessibility (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đi với to; động từ trực tiếp đi với tân ngữ, không thêm to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dial', 'en-b1-43', 'dial', '/ˈdaɪəl/', 'B1', 'mặt số; núm điều chỉnh; quay số điện thoại', 'n.', NULL, NULL, 'Thì quá khứ tiếng Anh-Anh thường dùng dialled, tiếng Anh-Mỹ thường dùng dialed.', 'Turn the dial clockwise to make the room warmer.', NULL, 'Vặn núm điều chỉnh theo chiều kim đồng hồ để làm cho phòng ấm hơn.', '{"wordId":"dial","ukIpa":"/ˈdaɪəl/","usIpa":"/ˈdaɪəl/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"A marked face or rotating control on an instrument","vi":"mặt số; núm điều chỉnh"},{"pos":"v.","en":"Enter a telephone number to make a call","vi":"quay số điện thoại"}],"examples":[{"en":"Turn the dial clockwise to make the room warmer.","vi":"Vặn núm điều chỉnh theo chiều kim đồng hồ để làm cho phòng ấm hơn.","audioKind":"ex"},{"en":"People who struggle with touchscreens may find a physical dial easier to use when adjusting household appliances.","vi":"Những người gặp khó khăn với màn hình cảm ứng có thể thấy núm vặn vật lý dễ sử dụng hơn khi điều chỉnh các thiết bị gia dụng.","audioKind":"ex2"}],"collocations":[{"en":"turn the dial","vi":"vặn núm điều chỉnh"},{"en":"a clock dial","vi":"mặt đồng hồ"},{"en":"dial a number","vi":"quay một số điện thoại"},{"en":"a dial tone","vi":"âm báo hiệu quay số"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thì quá khứ tiếng Anh-Anh thường dùng dialled, tiếng Anh-Mỹ thường dùng dialed.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_microphone', 'en-b1-43', 'microphone', '/ˈmaɪkrəfoʊn/', 'B1', 'micrô; ống nói', 'n.', NULL, 'Đồng nghĩa: mic', 'Microphone là thiết bị thu âm; speaker là loa phát âm thanh, tránh nhầm lẫn.', 'Please speak into the microphone so everyone can hear.', NULL, 'Xin vui lòng nói vào micrô để mọi người đều có thể nghe thấy.', '{"wordId":"microphone","ukIpa":"/ˈmaɪkrəfəʊn/","usIpa":"/ˈmaɪkrəfoʊn/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"A device that captures sound for recording or making it louder.","vi":"micrô; ống nói"}],"examples":[{"en":"Please speak into the microphone so everyone can hear.","vi":"Xin vui lòng nói vào micrô để mọi người đều có thể nghe thấy.","audioKind":"ex"},{"en":"Using a microphone during lectures can help students hear clearly, particularly in large classrooms with poor acoustics.","vi":"Việc sử dụng micrô trong các buổi thuyết giảng có thể giúp sinh viên nghe rõ ràng, đặc biệt là ở những phòng học lớn có âm học kém.","audioKind":"ex2"}],"collocations":[{"en":"speak into a microphone","vi":"nói vào micrô"},{"en":"a wireless microphone","vi":"micrô không dây"},{"en":"a microphone stand","vi":"giá đỡ micrô"}],"wordFamily":[],"synonyms":["mic"],"antonyms":[],"tipVi":"Microphone là thiết bị thu âm; speaker là loa phát âm thanh, tránh nhầm lẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_signal', 'en-b1-43', 'signal', '/ˈsɪɡnəl/', 'B1', 'tín hiệu; dấu hiệu; hiệu lệnh; sóng điện từ hoặc sóng vô tuyến truyền tải thông tin; ra hiệu; báo hiệu; biểu thị', 'n.', 'signalling (n.)', NULL, 'Thì quá khứ của từ này viết theo kiểu Anh-Anh là signalled và Anh-Mỹ là signaled.', 'The coach gave a signal, and we started running.', NULL, 'Huấn luyện viên vừa phát hiệu lệnh là chúng tôi bắt đầu chạy.', '{"wordId":"signal","ukIpa":"/ˈsɪɡnəl/","usIpa":"/ˈsɪɡnəl/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"A sound, movement, or light that communicates a message.","vi":"tín hiệu; dấu hiệu; hiệu lệnh"},{"pos":"n.","en":"An electrical or radio wave carrying information.","vi":"sóng điện từ hoặc sóng vô tuyến truyền tải thông tin"},{"pos":"v.","en":"Communicate through an action, or indicate that something is happening.","vi":"ra hiệu; báo hiệu; biểu thị"}],"examples":[{"en":"The coach gave a signal, and we started running.","vi":"Huấn luyện viên vừa phát hiệu lệnh là chúng tôi bắt đầu chạy.","audioKind":"ex"},{"en":"Increasing investment in renewable energy may signal a government''s commitment to reducing its dependence on fossil fuels.","vi":"Việc tăng đầu tư vào năng lượng tái tạo có thể báo hiệu cam kết của chính phủ trong việc giảm sự phụ thuộc vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"give a signal","vi":"ra hiệu; phát tín hiệu"},{"en":"a weak signal","vi":"tín hiệu yếu"},{"en":"signal a change","vi":"báo hiệu một sự thay đổi"}],"wordFamily":["signalling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thì quá khứ của từ này viết theo kiểu Anh-Anh là signalled và Anh-Mỹ là signaled.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_electronic', 'en-b1-43', 'electronic', '/ɪˌlekˈtrɑːnɪk/', 'B1', 'thuộc về điện tử; dùng vi mạch điện tử; sử dụng hoặc lưu trữ bằng máy tính; kỹ thuật số', 'adj.', 'electron (n.), electronics (n.), electronically (adv.)', NULL, 'Từ electronic dùng để chỉ các thiết bị có vi mạch điện tử; từ electric mang nghĩa chung chung là dùng điện.', 'Please switch off your electronic devices during the performance.', NULL, 'Xin vui lòng tắt các thiết bị điện tử trong suốt buổi biểu diễn.', '{"wordId":"electronic","ukIpa":"/ɪˌlekˈtrɒnɪk/","usIpa":"/ɪˌlekˈtrɑːnɪk/","cefr":"B1","topic":"technology","senses":[{"pos":"adj.","en":"using circuits to control electrical signals","vi":"thuộc về điện tử; dùng vi mạch điện tử"},{"pos":"adj.","en":"stored, sent, or accessed using computers","vi":"sử dụng hoặc lưu trữ bằng máy tính; kỹ thuật số"}],"examples":[{"en":"Please switch off your electronic devices during the performance.","vi":"Xin vui lòng tắt các thiết bị điện tử trong suốt buổi biểu diễn.","audioKind":"ex"},{"en":"Electronic health records can help doctors share information efficiently, but strong safeguards are needed to protect patient privacy.","vi":"Hồ sơ y tế điện tử giúp bác sĩ chia sẻ thông tin hiệu quả, nhưng cần có các biện pháp bảo vệ vững chắc để bảo mật quyền riêng tư của bệnh nhân.","audioKind":"ex2"}],"collocations":[{"en":"electronic devices","vi":"thiết bị điện tử"},{"en":"electronic records","vi":"hồ sơ điện tử"},{"en":"electronic payment","vi":"thanh toán điện tử"},{"en":"electronic waste","vi":"rác thải điện tử"}],"wordFamily":["electron (n.)","electronics (n.)","electronically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ electronic dùng để chỉ các thiết bị có vi mạch điện tử; từ electric mang nghĩa chung chung là dùng điện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loudspeaker', 'en-b1-43', 'loudspeaker', '/ˌlaʊdˈspiːkər/', 'B1', 'loa; hệ thống loa phóng thanh', 'n.', 'speaker (n.)', 'Đồng nghĩa: speaker', 'loudspeaker chỉ thiết bị; trong khi speaker còn có thể chỉ người nói.', 'A voice from the loudspeaker announced our train''s arrival.', NULL, 'Một giọng nói từ loa phóng thanh thông báo đoàn tàu của chúng tôi đã đến.', '{"wordId":"loudspeaker","ukIpa":"/ˌlaʊdˈspiːkə/","usIpa":"/ˌlaʊdˈspiːkər/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"A device that makes recorded or transmitted sound audible","vi":"loa; hệ thống loa phóng thanh"}],"examples":[{"en":"A voice from the loudspeaker announced our train''s arrival.","vi":"Một giọng nói từ loa phóng thanh thông báo đoàn tàu của chúng tôi đã đến.","audioKind":"ex"},{"en":"Public transport stations use loudspeaker systems to communicate urgent safety information to large numbers of passengers.","vi":"Các nhà ga giao thông công cộng sử dụng hệ thống loa phóng thanh để truyền đạt thông tin an toàn khẩn cấp cho lượng lớn hành khách.","audioKind":"ex2"}],"collocations":[{"en":"loudspeaker system","vi":"hệ thống loa phóng thanh"},{"en":"over the loudspeaker","vi":"qua loa phát thanh"},{"en":"portable loudspeaker","vi":"loa xách tay; loa di động"}],"wordFamily":["speaker (n.)"],"synonyms":["speaker"],"antonyms":[],"tipVi":"loudspeaker chỉ thiết bị; trong khi speaker còn có thể chỉ người nói.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_battery', 'en-b1-43', 'battery', '/ˈbætəri/', 'B1', 'thiết bị dự trữ năng lượng và cung cấp điện; pin; ắc-quy; một tập hợp lớn các sự vật tương tự, đặc biệt là các bài kiểm tra hoặc câu hỏi', 'n.', NULL, NULL, 'Dạng số nhiều là batteries; cấu trúc a battery of có thể chỉ một loạt các bài kiểm tra.', 'The torch needs a new battery before our trip.', NULL, 'Chiếc đèn pin cần được thay pin mới trước chuyến đi của chúng ta.', '{"wordId":"battery","ukIpa":"/ˈbætəri/","usIpa":"/ˈbætəri/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"A device that stores energy and supplies electricity.","vi":"thiết bị dự trữ năng lượng và cung cấp điện; pin; ắc-quy"},{"pos":"n.","en":"A large set of similar things, especially tests or questions.","vi":"một tập hợp lớn các sự vật tương tự, đặc biệt là các bài kiểm tra hoặc câu hỏi"}],"examples":[{"en":"The torch needs a new battery before our trip.","vi":"Chiếc đèn pin cần được thay pin mới trước chuyến đi của chúng ta.","audioKind":"ex"},{"en":"Improved battery technology could make electric vehicles more affordable and reduce dependence on fossil fuels.","vi":"Công nghệ pin được cải tiến có thể giúp xe điện trở nên dễ tiếp cận hơn về mặt giá cả và giảm bớt sự phụ thuộc vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"a rechargeable battery","vi":"pin sạc"},{"en":"battery life","vi":"thời lượng pin"},{"en":"charge a battery","vi":"sạc pin"},{"en":"a battery of tests","vi":"một loạt bài kiểm tra"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là batteries; cấu trúc a battery of có thể chỉ một loạt các bài kiểm tra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_link', 'en-b1-43', 'link', '/lɪŋk/', 'B1', 'mối liên hệ; sự kết nối; đường liên kết; đường dẫn; liên kết; kết nối', 'n.', 'linked (adj.), linkage (n.)', 'Đồng nghĩa: connection, connect · Trái nghĩa: disconnect', 'Thường dùng cấu trúc a link between A and B cho danh từ, và link A to/with B cho động từ.', 'The new bridge provides a link between the villages.', NULL, 'Cây cầu mới tạo ra một tuyến kết nối giữa các ngôi làng.', '{"wordId":"link","ukIpa":"/lɪŋk/","usIpa":"/lɪŋk/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"a connection between people, things, or ideas","vi":"mối liên hệ; sự kết nối"},{"pos":"n.","en":"a clickable element that opens another webpage or digital resource","vi":"đường liên kết; đường dẫn"},{"pos":"v.","en":"to connect things or show a relationship between them","vi":"liên kết; kết nối"}],"examples":[{"en":"The new bridge provides a link between the villages.","vi":"Cây cầu mới tạo ra một tuyến kết nối giữa các ngôi làng.","audioKind":"ex"},{"en":"Researchers have identified a strong link between regular physical activity and improved mental health.","vi":"Các nhà nghiên cứu đã xác định có mối liên hệ chặt chẽ giữa việc tập thể dục đều đặn và cải thiện sức khỏe tinh thần.","audioKind":"ex2"}],"collocations":[{"en":"a link between","vi":"mối liên hệ giữa"},{"en":"click a link","vi":"nhấp vào đường liên kết"},{"en":"link A to B","vi":"liên kết A với B"},{"en":"transport links","vi":"mạng lưới giao thông kết nối"}],"wordFamily":["linked (adj.)","linkage (n.)"],"synonyms":["connection","connect"],"antonyms":["disconnect"],"tipVi":"Thường dùng cấu trúc a link between A and B cho danh từ, và link A to/with B cho động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tape-recording', 'en-b1-43', 'tape-recording', '/ˈteɪp rɪˌkɔːrdɪŋ/', 'B1', 'bản ghi âm băng từ', 'n.', 'tape-record (v.), tape recorder (n.), recording (n.)', NULL, 'Cũng thường được viết là tape recording; bản ghi âm kỹ thuật số thường dùng từ recording.', 'We found a tape-recording of our grandfather singing.', NULL, 'Chúng tôi tìm thấy một đoạn băng ghi âm giọng ông nội đang hát.', '{"wordId":"tape-recording","ukIpa":"/ˈteɪp rɪˌkɔːdɪŋ/","usIpa":"/ˈteɪp rɪˌkɔːrdɪŋ/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"sound recorded on magnetic tape","vi":"bản ghi âm băng từ"}],"examples":[{"en":"We found a tape-recording of our grandfather singing.","vi":"Chúng tôi tìm thấy một đoạn băng ghi âm giọng ông nội đang hát.","audioKind":"ex"},{"en":"A tape-recording of a traditional song can help researchers understand how local musical styles have changed.","vi":"Một đoạn băng ghi âm bài hát truyền thống có thể giúp các nhà nghiên cứu hiểu được phong cách âm nhạc địa phương đã thay đổi như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"make a tape-recording","vi":"làm bản ghi âm băng từ"},{"en":"listen to a tape-recording","vi":"nghe bản ghi âm băng từ"},{"en":"a tape-recording of an interview","vi":"bản ghi âm một cuộc phỏng vấn"}],"wordFamily":["tape-record (v.)","tape recorder (n.)","recording (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cũng thường được viết là tape recording; bản ghi âm kỹ thuật số thường dùng từ recording.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_technical', 'en-b1-43', 'technical', '/ˈteknɪkəl/', 'B1', 'thuộc về kỹ thuật; mang tính chuyên môn; có tính chuyên ngành; chuyên môn cao', 'adj.', 'technically (adv.), technician (n.)', NULL, 'technical nhấn mạnh kỹ thuật hoặc chuyên môn kỹ thuật, không đồng nghĩa với high-tech (công nghệ cao).', 'We called an engineer to solve the technical problem.', NULL, 'Chúng tôi đã gọi kỹ sư đến để giải quyết vấn đề kỹ thuật.', '{"wordId":"technical","ukIpa":"/ˈteknɪkəl/","usIpa":"/ˈteknɪkəl/","cefr":"B1","topic":"technology","senses":[{"pos":"adj.","en":"relating to practical skills, machinery, or scientific methods","vi":"thuộc về kỹ thuật; mang tính chuyên môn"},{"pos":"adj.","en":"using specialist knowledge or language in a particular subject","vi":"có tính chuyên ngành; chuyên môn cao"}],"examples":[{"en":"We called an engineer to solve the technical problem.","vi":"Chúng tôi đã gọi kỹ sư đến để giải quyết vấn đề kỹ thuật.","audioKind":"ex"},{"en":"Schools should teach technical skills alongside academic subjects to prepare students for a changing workplace.","vi":"Các trường học nên giảng dạy các kỹ năng kỹ thuật song song với các môn học thuật để chuẩn bị cho học sinh trước một thị trường lao động luôn thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"technical skills","vi":"kỹ năng kỹ thuật"},{"en":"technical support","vi":"hỗ trợ kỹ thuật"},{"en":"technical problem","vi":"vấn đề kỹ thuật"},{"en":"technical terms","vi":"thuật ngữ chuyên ngành"}],"wordFamily":["technically (adv.)","technician (n.)"],"synonyms":[],"antonyms":[],"tipVi":"technical nhấn mạnh kỹ thuật hoặc chuyên môn kỹ thuật, không đồng nghĩa với high-tech (công nghệ cao).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bug', 'en-b1-43', 'bug', '/bʌɡ/', 'B1', 'côn trùng; bọ; lỗi phần mềm; sự cố kỹ thuật; làm phiền; quấy rầy', 'n.', 'buggy (adj.), debug (v.), debugging (n.)', NULL, 'Trong văn nói, bug có thể chỉ chung côn trùng; trong ngữ cảnh công nghệ thường chỉ lỗi chương trình.', 'A tiny green bug landed on my sleeve.', NULL, 'Một con bọ nhỏ màu xanh lá cây đã đậu lên tay áo của tôi.', '{"wordId":"bug","ukIpa":"/bʌɡ/","usIpa":"/bʌɡ/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"a small insect or similar creature","vi":"côn trùng; bọ"},{"pos":"n.","en":"an error in a computer program that causes problems","vi":"lỗi phần mềm; sự cố kỹ thuật"},{"pos":"v.","en":"to annoy someone, especially repeatedly","vi":"làm phiền; quấy rầy"}],"examples":[{"en":"A tiny green bug landed on my sleeve.","vi":"Một con bọ nhỏ màu xanh lá cây đã đậu lên tay áo của tôi.","audioKind":"ex"},{"en":"A software bug can disrupt essential services, highlighting the importance of thorough testing before release.","vi":"Lỗi phần mềm có thể làm gián đoạn các dịch vụ thiết yếu, làm nổi bật tầm quan trọng của việc kiểm tra kỹ lưỡng trước khi phát hành.","audioKind":"ex2"}],"collocations":[{"en":"a software bug","vi":"lỗi phần mềm"},{"en":"fix a bug","vi":"sửa lỗi phần mềm"},{"en":"a tiny bug","vi":"một con côn trùng nhỏ"}],"wordFamily":["buggy (adj.)","debug (v.)","debugging (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong văn nói, bug có thể chỉ chung côn trùng; trong ngữ cảnh công nghệ thường chỉ lỗi chương trình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wire', 'en-b1-43', 'wire', '/ˈwaɪr/', 'B1', 'dây kim loại; dây điện; lắp dây điện; đấu nối dây điện', 'n.', 'wiring (n.), wireless (adj.), rewire (v.)', NULL, '''wire'' có thể chỉ một sợi kim loại đơn; trong khi ''cable'' thường dày hơn hoặc gồm nhiều sợi bện lại.', 'A thin wire connects the lamp to its battery.', NULL, 'Một sợi dây điện mảnh nối chiếc đèn với cục pin của nó.', '{"wordId":"wire","ukIpa":"/ˈwaɪə/","usIpa":"/ˈwaɪr/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"Thin metal drawn into strands, often used to carry electricity.","vi":"dây kim loại; dây điện"},{"pos":"v.","en":"To install or connect electrical wires in something.","vi":"lắp dây điện; đấu nối dây điện"}],"examples":[{"en":"A thin wire connects the lamp to its battery.","vi":"Một sợi dây điện mảnh nối chiếc đèn với cục pin của nó.","audioKind":"ex"},{"en":"Older buildings often need new electrical wire to meet modern safety standards and support increased energy use.","vi":"Các tòa nhà cũ thường cần hệ thống dây điện mới để đáp ứng các tiêu chuẩn an toàn hiện đại và hỗ trợ nhu cầu sử dụng năng lượng tăng cao.","audioKind":"ex2"}],"collocations":[{"en":"copper wire","vi":"dây đồng"},{"en":"electrical wire","vi":"dây điện"},{"en":"wire fence","vi":"hàng rào thép gai"},{"en":"wire up a house","vi":"lắp đặt hệ thống điện cho ngôi nhà"}],"wordFamily":["wiring (n.)","wireless (adj.)","rewire (v.)"],"synonyms":[],"antonyms":[],"tipVi":"''wire'' có thể chỉ một sợi kim loại đơn; trong khi ''cable'' thường dày hơn hoặc gồm nhiều sợi bện lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_engineering', 'en-b1-43', 'engineering', '/ˌendʒɪˈnɪrɪŋ/', 'B1', 'ngành kỹ thuật; kỹ thuật học', 'n.', 'engineer (n.), engineer (v.)', NULL, 'Khi chỉ môn học hoặc lĩnh vực kỹ thuật thì không đếm được; engineer có thể chỉ kỹ sư.', 'My cousin studies engineering and builds small robots at home.', NULL, 'Anh họ của tôi học ngành kỹ thuật và chế tạo các robot nhỏ ở nhà.', '{"wordId":"engineering","ukIpa":"/ˌendʒɪˈnɪərɪŋ/","usIpa":"/ˌendʒɪˈnɪrɪŋ/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"using science to design and build machines, structures, or systems","vi":"ngành kỹ thuật; kỹ thuật học"}],"examples":[{"en":"My cousin studies engineering and builds small robots at home.","vi":"Anh họ của tôi học ngành kỹ thuật và chế tạo các robot nhỏ ở nhà.","audioKind":"ex"},{"en":"Advances in engineering have enabled cities to build bridges that withstand extreme weather and carry heavier traffic.","vi":"Những tiến bộ trong kỹ thuật đã giúp các thành phố xây dựng những cây cầu có thể chống chọi với thời tiết khắc nghiệt và chịu được lưu lượng giao thông lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"civil engineering","vi":"kỹ thuật xây dựng; công trình"},{"en":"mechanical engineering","vi":"kỹ thuật cơ khí"},{"en":"electrical engineering","vi":"kỹ thuật điện"},{"en":"an engineering project","vi":"một dự án kỹ thuật"}],"wordFamily":["engineer (n.)","engineer (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ môn học hoặc lĩnh vực kỹ thuật thì không đếm được; engineer có thể chỉ kỹ sư.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_electrical', 'en-b1-43', 'electrical', '/ɪˈlektrɪkəl/', 'B1', 'thuộc về điện; liên quan đến điện', 'adj.', 'electric (adj.), electricity (n.), electrically (adv.), electrician (n.)', NULL, 'electrical thường chỉ lĩnh vực điện/thuộc về điện; electric thường chỉ thiết bị chạy bằng điện.', 'An electrical fault left our kitchen in darkness.', NULL, 'Một sự cố về điện đã khiến căn bếp nhà chúng tôi chìm trong bóng tối.', '{"wordId":"electrical","ukIpa":"/ɪˈlektrɪkəl/","usIpa":"/ɪˈlektrɪkəl/","cefr":"B1","topic":"technology","senses":[{"pos":"adj.","en":"Related to electricity or equipment that uses it.","vi":"thuộc về điện; liên quan đến điện"}],"examples":[{"en":"An electrical fault left our kitchen in darkness.","vi":"Một sự cố về điện đã khiến căn bếp nhà chúng tôi chìm trong bóng tối.","audioKind":"ex"},{"en":"Regular inspections of electrical equipment can reduce fire risks in crowded residential buildings and workplaces.","vi":"Việc kiểm tra thường xuyên các thiết bị điện có thể làm giảm nguy cơ hỏa hoạn tại các tòa nhà dân cư đông đúc và nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"electrical equipment","vi":"thiết bị điện"},{"en":"electrical engineering","vi":"kỹ thuật điện"},{"en":"electrical fault","vi":"sự cố chập điện"},{"en":"electrical wiring","vi":"hệ thống dây điện"}],"wordFamily":["electric (adj.)","electricity (n.)","electrically (adv.)","electrician (n.)"],"synonyms":[],"antonyms":[],"tipVi":"electrical thường chỉ lĩnh vực điện/thuộc về điện; electric thường chỉ thiết bị chạy bằng điện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_43_1', 'en-b1-43', 'Cách dùng “electronic” (adj.) — thuộc về điện tử; dùng vi mạch điện tử', 'electronic devices  ·  electronic records  ·  electronic payment', 'Từ electronic dùng để chỉ các thiết bị có vi mạch điện tử; từ electric mang nghĩa chung chung là dùng điện.', 'Họ từ (Word Family): electron (n.), electronics (n.), electronically (adv.)', '[{"hanzi":"Please switch off your electronic devices during the performance.","pinyin":"","meaning":"Xin vui lòng tắt các thiết bị điện tử trong suốt buổi biểu diễn."},{"hanzi":"Electronic health records can help doctors share information efficiently, but strong safeguards are needed to protect patient privacy.","pinyin":"","meaning":"Hồ sơ y tế điện tử giúp bác sĩ chia sẻ thông tin hiệu quả, nhưng cần có các biện pháp bảo vệ vững chắc để bảo mật quyền riêng tư của bệnh nhân."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_43_2', 'en-b1-43', 'Cách dùng “technical” (adj.) — thuộc về kỹ thuật; mang tính chuyên môn', 'technical skills  ·  technical support  ·  technical problem', 'technical nhấn mạnh kỹ thuật hoặc chuyên môn kỹ thuật, không đồng nghĩa với high-tech (công nghệ cao).', 'Họ từ (Word Family): technically (adv.), technician (n.)', '[{"hanzi":"We called an engineer to solve the technical problem.","pinyin":"","meaning":"Chúng tôi đã gọi kỹ sư đến để giải quyết vấn đề kỹ thuật."},{"hanzi":"Schools should teach technical skills alongside academic subjects to prepare students for a changing workplace.","pinyin":"","meaning":"Các trường học nên giảng dạy các kỹ năng kỹ thuật song song với các môn học thuật để chuẩn bị cho học sinh trước một thị trường lao động luôn thay đổi."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_43_3', 'en-b1-43', 'Cách dùng “bug” (n.) — côn trùng; bọ', 'a software bug  ·  fix a bug  ·  a tiny bug', 'Trong văn nói, bug có thể chỉ chung côn trùng; trong ngữ cảnh công nghệ thường chỉ lỗi chương trình.', 'Họ từ (Word Family): buggy (adj.), debug (v.), debugging (n.)', '[{"hanzi":"A tiny green bug landed on my sleeve.","pinyin":"","meaning":"Một con bọ nhỏ màu xanh lá cây đã đậu lên tay áo của tôi."},{"hanzi":"A software bug can disrupt essential services, highlighting the importance of thorough testing before release.","pinyin":"","meaning":"Lỗi phần mềm có thể làm gián đoạn các dịch vụ thiết yếu, làm nổi bật tầm quan trọng của việc kiểm tra kỹ lưỡng trước khi phát hành."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_43_4', 'en-b1-43', 'Cách dùng “wire” (n.) — dây kim loại; dây điện', 'copper wire  ·  electrical wire  ·  wire fence', '''wire'' có thể chỉ một sợi kim loại đơn; trong khi ''cable'' thường dày hơn hoặc gồm nhiều sợi bện lại.', 'Họ từ (Word Family): wiring (n.), wireless (adj.), rewire (v.)', '[{"hanzi":"A thin wire connects the lamp to its battery.","pinyin":"","meaning":"Một sợi dây điện mảnh nối chiếc đèn với cục pin của nó."},{"hanzi":"Older buildings often need new electrical wire to meet modern safety standards and support increased energy use.","pinyin":"","meaning":"Các tòa nhà cũ thường cần hệ thống dây điện mới để đáp ứng các tiêu chuẩn an toàn hiện đại và hỗ trợ nhu cầu sử dụng năng lượng tăng cao."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_43_1', 'en-b1-43', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_1_1', 'ten_b1_43_1', 'update', 'Please update your address before we send the parcel.', 'Please update your address before we send the parcel.', '/ˌʌpˈdeɪt/', 'Vui lòng cập nhật địa chỉ của bạn trước khi chúng tôi gửi bưu kiện.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_1_2', 'ten_b1_43_1', 'access', 'Guests have access to the pool until sunset.', 'Guests have access to the pool until sunset.', '/ˈækses/', 'Khách lưu trú được sử dụng hồ bơi cho đến khi mặt trời lặn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_1_3', 'ten_b1_43_1', 'dial', 'Turn the dial clockwise to make the room warmer.', 'Turn the dial clockwise to make the room warmer.', '/ˈdaɪəl/', 'Vặn núm điều chỉnh theo chiều kim đồng hồ để làm cho phòng ấm hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_1_4', 'ten_b1_43_1', 'microphone', 'Please speak into the microphone so everyone can hear.', 'Please speak into the microphone so everyone can hear.', '/ˈmaɪkrəfoʊn/', 'Xin vui lòng nói vào micrô để mọi người đều có thể nghe thấy.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_1_5', 'ten_b1_43_1', 'signal', 'The coach gave a signal, and we started running.', 'The coach gave a signal, and we started running.', '/ˈsɪɡnəl/', 'Huấn luyện viên vừa phát hiệu lệnh là chúng tôi bắt đầu chạy.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_1_6', 'ten_b1_43_1', 'electronic', 'Please switch off your electronic devices during the performance.', 'Please switch off your electronic devices during the performance.', '/ɪˌlekˈtrɑːnɪk/', 'Xin vui lòng tắt các thiết bị điện tử trong suốt buổi biểu diễn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_1_7', 'ten_b1_43_1', 'loudspeaker', 'A voice from the loudspeaker announced our train''s arrival.', 'A voice from the loudspeaker announced our train''s arrival.', '/ˌlaʊdˈspiːkər/', 'Một giọng nói từ loa phóng thanh thông báo đoàn tàu của chúng tôi đã đến.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_1_8', 'ten_b1_43_1', 'battery', 'The torch needs a new battery before our trip.', 'The torch needs a new battery before our trip.', '/ˈbætəri/', 'Chiếc đèn pin cần được thay pin mới trước chuyến đi của chúng ta.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_43_1_1', 'en-b1-43', 'ten_b1_43_1', 'listening', 'listening', 'Please update your address before we send the parcel.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Huấn luyện viên vừa phát hiệu lệnh là chúng tôi bắt đầu chạy.","Khách lưu trú được sử dụng hồ bơi cho đến khi mặt trời lặn.","Vui lòng cập nhật địa chỉ của bạn trước khi chúng tôi gửi bưu kiện.","Một giọng nói từ loa phóng thanh thông báo đoàn tàu của chúng tôi đã đến."]'::jsonb, 2, 'Please update your address before we send the parcel. → Vui lòng cập nhật địa chỉ của bạn trước khi chúng tôi gửi bưu kiện.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_43_1_2', 'en-b1-43', 'ten_b1_43_1', 'listening', 'listening', 'Guests have access to the pool until sunset.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một giọng nói từ loa phóng thanh thông báo đoàn tàu của chúng tôi đã đến.","Một con bọ nhỏ màu xanh lá cây đã đậu lên tay áo của tôi.","Khách lưu trú được sử dụng hồ bơi cho đến khi mặt trời lặn.","Vui lòng cập nhật địa chỉ của bạn trước khi chúng tôi gửi bưu kiện."]'::jsonb, 2, 'Guests have access to the pool until sunset. → Khách lưu trú được sử dụng hồ bơi cho đến khi mặt trời lặn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_43_1_3', 'en-b1-43', 'ten_b1_43_1', 'listening', 'listening', 'Turn the dial clockwise to make the room warmer.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Vặn núm điều chỉnh theo chiều kim đồng hồ để làm cho phòng ấm hơn.","Một con bọ nhỏ màu xanh lá cây đã đậu lên tay áo của tôi.","Chiếc đèn pin cần được thay pin mới trước chuyến đi của chúng ta.","Xin vui lòng tắt các thiết bị điện tử trong suốt buổi biểu diễn."]'::jsonb, 0, 'Turn the dial clockwise to make the room warmer. → Vặn núm điều chỉnh theo chiều kim đồng hồ để làm cho phòng ấm hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_43_2', 'en-b1-43', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_2_1', 'ten_b1_43_2', 'update', 'Governments should regularly update environmental regulations to reflect scientific discoveries and respond to emerging risks.', 'Governments should regularly update environmental regulations to reflect scientific discoveries and respond to emerging risks.', '/ˌʌpˈdeɪt/', 'Chính phủ nên thường xuyên cập nhật các quy định về môi trường để phản ánh các phát hiện khoa học và ứng phó với các rủi ro mới nổi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_2_2', 'ten_b1_43_2', 'access', 'Affordable internet access enables rural students to benefit from a wider range of educational resources.', 'Affordable internet access enables rural students to benefit from a wider range of educational resources.', '/ˈækses/', 'Khả năng tiếp cận internet giá rẻ giúp học sinh nông thôn tiếp cận được nhiều nguồn tài nguyên giáo dục phong phú hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_2_3', 'ten_b1_43_2', 'dial', 'People who struggle with touchscreens may find a physical dial easier to use when adjusting household appliances.', 'People who struggle with touchscreens may find a physical dial easier to use when adjusting household appliances.', '/ˈdaɪəl/', 'Những người gặp khó khăn với màn hình cảm ứng có thể thấy núm vặn vật lý dễ sử dụng hơn khi điều chỉnh các thiết bị gia dụng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_2_4', 'ten_b1_43_2', 'microphone', 'Using a microphone during lectures can help students hear clearly, particularly in large classrooms with poor acoustics.', 'Using a microphone during lectures can help students hear clearly, particularly in large classrooms with poor acoustics.', '/ˈmaɪkrəfoʊn/', 'Việc sử dụng micrô trong các buổi thuyết giảng có thể giúp sinh viên nghe rõ ràng, đặc biệt là ở những phòng học lớn có âm học kém.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_2_5', 'ten_b1_43_2', 'signal', 'Increasing investment in renewable energy may signal a government''s commitment to reducing its dependence on fossil fuels.', 'Increasing investment in renewable energy may signal a government''s commitment to reducing its dependence on fossil fuels.', '/ˈsɪɡnəl/', 'Việc tăng đầu tư vào năng lượng tái tạo có thể báo hiệu cam kết của chính phủ trong việc giảm sự phụ thuộc vào nhiên liệu hóa thạch.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_43_2_6', 'ten_b1_43_2', 'electronic', 'Electronic health records can help doctors share information efficiently, but strong safeguards are needed to protect patient privacy.', 'Electronic health records can help doctors share information efficiently, but strong safeguards are needed to protect patient privacy.', '/ɪˌlekˈtrɑːnɪk/', 'Hồ sơ y tế điện tử giúp bác sĩ chia sẻ thông tin hiệu quả, nhưng cần có các biện pháp bảo vệ vững chắc để bảo mật quyền riêng tư của bệnh nhân.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_43_2_1', 'en-b1-43', 'ten_b1_43_2', 'listening', 'listening', 'Governments should regularly update environmental regulations to reflect scientific discoveries and respond to emerging risks.', NULL, 'Trong câu vừa nghe, từ “update” mang nghĩa nào sau đây?', '["hắt hơi; nhảy mũi","hôi thối; khó ngửi","trò lướt ván nước","cập nhật; làm cho mới nhất"]'::jsonb, 3, '“update” (/ˌʌpˈdeɪt/): cập nhật; làm cho mới nhất. Câu đầy đủ: Governments should regularly update environmental regulations to reflect scientific discoveries and respond to emerging risks.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_43_2_2', 'en-b1-43', 'ten_b1_43_2', 'listening', 'listening', 'Affordable internet access enables rural students to benefit from a wider range of educational resources.', NULL, 'Trong câu vừa nghe, từ “access” mang nghĩa nào sau đây?', '["quyền sử dụng; cơ hội tiếp cận","lớn; trọng yếu; nghiêm trọng","chủ yếu; quan trọng hàng đầu; chính","hoàn hảo; không tì vết"]'::jsonb, 0, '“access” (/ˈækses/): quyền sử dụng; cơ hội tiếp cận. Câu đầy đủ: Affordable internet access enables rural students to benefit from a wider range of educational resources.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
