INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_43_2', 'en-b1-43', NULL, 'comprehensive_test', 'listening', 'Guests have access to the pool until sunset.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một sợi dây điện mảnh nối chiếc đèn với cục pin của nó.","Khách lưu trú được sử dụng hồ bơi cho đến khi mặt trời lặn.","Chiếc đèn pin cần được thay pin mới trước chuyến đi của chúng ta.","Xin vui lòng nói vào micrô để mọi người đều có thể nghe thấy."]'::jsonb, 1, 'Guests have access to the pool until sunset. → Khách lưu trú được sử dụng hồ bơi cho đến khi mặt trời lặn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_43_3', 'en-b1-43', NULL, 'comprehensive_test', 'listening', 'dial', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mặt số; núm điều chỉnh","chống nước; không thấm nước","nhảy lò cò; nhảy chồm chồm","thuộc thực tế; mang tính thực hành"]'::jsonb, 0, 'dial (/ˈdaɪəl/) → mặt số; núm điều chỉnh; quay số điện thoại', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_43_4', 'en-b1-43', NULL, 'comprehensive_test', 'listening', 'Please speak into the microphone so everyone can hear.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xin vui lòng nói vào micrô để mọi người đều có thể nghe thấy.","Một con bọ nhỏ màu xanh lá cây đã đậu lên tay áo của tôi.","Xin vui lòng tắt các thiết bị điện tử trong suốt buổi biểu diễn.","Vui lòng cập nhật địa chỉ của bạn trước khi chúng tôi gửi bưu kiện."]'::jsonb, 0, 'Please speak into the microphone so everyone can hear. → Xin vui lòng nói vào micrô để mọi người đều có thể nghe thấy.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_43_5', 'en-b1-43', NULL, 'comprehensive_test', 'listening', 'signal', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự giảm giá; chiết khấu","cay; có nhiều gia vị","tín hiệu; dấu hiệu; hiệu lệnh","ảnh hưởng; sức ảnh hưởng"]'::jsonb, 2, 'signal (/ˈsɪɡnəl/) → tín hiệu; dấu hiệu; hiệu lệnh; sóng điện từ hoặc sóng vô tuyến truyền tải thông tin; ra hiệu; báo hiệu; biểu thị', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_43_6', 'en-b1-43', NULL, 'comprehensive_test', 'listening', 'Please switch off your electronic devices during the performance.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Vặn núm điều chỉnh theo chiều kim đồng hồ để làm cho phòng ấm hơn.","Xin vui lòng tắt các thiết bị điện tử trong suốt buổi biểu diễn.","Chiếc đèn pin cần được thay pin mới trước chuyến đi của chúng ta.","Vui lòng cập nhật địa chỉ của bạn trước khi chúng tôi gửi bưu kiện."]'::jsonb, 1, 'Please switch off your electronic devices during the performance. → Xin vui lòng tắt các thiết bị điện tử trong suốt buổi biểu diễn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
