INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_43_8', 'en-b1-43', NULL, 'comprehensive_test', 'listening', 'The torch needs a new battery before our trip.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Khách lưu trú được sử dụng hồ bơi cho đến khi mặt trời lặn.","Huấn luyện viên vừa phát hiệu lệnh là chúng tôi bắt đầu chạy.","Chiếc đèn pin cần được thay pin mới trước chuyến đi của chúng ta.","Anh họ của tôi học ngành kỹ thuật và chế tạo các robot nhỏ ở nhà."]'::jsonb, 2, 'The torch needs a new battery before our trip. → Chiếc đèn pin cần được thay pin mới trước chuyến đi của chúng ta.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
