INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_43_18', 'en-b1-43', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should regularly update environmental regulations to reflect scientific discoveries and respond to emerging risks.', 'Dựa vào câu trên, từ “update” có nghĩa phù hợp nhất là gì?', '["làm phiền; quấy rầy","cấu trúc; kết cấu","ngay lập tức; tức thì","cập nhật; làm cho mới nhất"]'::jsonb, 3, 'update: cập nhật; làm cho mới nhất; thông tin mới nhất; bản cập nhật. Dịch cả câu: Chính phủ nên thường xuyên cập nhật các quy định về môi trường để phản ánh các phát hiện khoa học và ứng phó với các rủi ro mới nổi.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_43_19', 'en-b1-43', NULL, 'comprehensive_test', 'reading', NULL, 'Affordable internet access enables rural students to benefit from a wider range of educational resources.', 'Dựa vào câu trên, từ “access” có nghĩa phù hợp nhất là gì?', '["làn đường","con cáo (loài thú hoang dã có tai nhọn và đuôi rậm)","quyền sử dụng; cơ hội tiếp cận","bắp cải; cải bắp"]'::jsonb, 2, 'access: quyền sử dụng; cơ hội tiếp cận; lối vào; đường vào; truy cập; tiếp cận; lấy. Dịch cả câu: Khả năng tiếp cận internet giá rẻ giúp học sinh nông thôn tiếp cận được nhiều nguồn tài nguyên giáo dục phong phú hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_43_20', 'en-b1-43', NULL, 'comprehensive_test', 'reading', NULL, 'People who struggle with touchscreens may find a physical dial easier to use when adjusting household appliances.', 'Dựa vào câu trên, từ “dial” có nghĩa phù hợp nhất là gì?', '["sách tiểu sử; lý lịch","hợp thời trang; sành điệu","mặt số; núm điều chỉnh","cành cây"]'::jsonb, 2, 'dial: mặt số; núm điều chỉnh; quay số điện thoại. Dịch cả câu: Những người gặp khó khăn với màn hình cảm ứng có thể thấy núm vặn vật lý dễ sử dụng hơn khi điều chỉnh các thiết bị gia dụng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_43_21', 'en-b1-43', NULL, 'comprehensive_test', 'reading', NULL, 'Using a microphone during lectures can help students hear clearly, particularly in large classrooms with poor acoustics.', 'Dựa vào câu trên, từ “microphone” có nghĩa phù hợp nhất là gì?', '["thuộc về mặt trời","khuôn viên trường đại học; khu học xá","micrô; ống nói","chân dung; ảnh chụp chân dung"]'::jsonb, 2, 'microphone: micrô; ống nói. Dịch cả câu: Việc sử dụng micrô trong các buổi thuyết giảng có thể giúp sinh viên nghe rõ ràng, đặc biệt là ở những phòng học lớn có âm học kém.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_43_22', 'en-b1-43', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dây kim loại; dây điện”', '["newsletter","shock","wire","minimum"]'::jsonb, 2, 'dây kim loại; dây điện → wire (/ˈwaɪr/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_43_23', 'en-b1-43', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngành kỹ thuật; kỹ thuật học”', '["shock","excite","cathedral","engineering"]'::jsonb, 3, 'ngành kỹ thuật; kỹ thuật học → engineering (/ˌendʒɪˈnɪrɪŋ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_43_24', 'en-b1-43', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về điện; liên quan đến điện”', '["host","deliver","blank","electrical"]'::jsonb, 3, 'thuộc về điện; liên quan đến điện → electrical (/ɪˈlektrɪkəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-44', 'en', 'Bài 44: Công nghệ & Kỹ thuật (2) - CEFR B1', 'CEFR B1', 'B1 · Công nghệ', '15 từ vựng Tiếng Anh CEFR B1 chủ đề công nghệ & kỹ thuật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3044, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_connection', 'en-b1-44', 'connection', '/kəˈnekʃən/', 'B1', 'mối liên hệ; sự liên quan; kết nối; sự kết nối; chuyến chuyển tiếp; phương tiện nối chuyến', 'n.', 'connect (v.), connected (adj.), connectivity (n.), disconnect (v.)', 'Đồng nghĩa: link, relationship', 'Biểu thị mối liên hệ giữa hai đối tượng dùng connection between A and B.', 'Our internet connection stopped working during the storm.', NULL, 'Kết nối internet của chúng tôi đã ngừng hoạt động trong cơn bão.', '{"wordId":"connection","ukIpa":"/kəˈnekʃən/","usIpa":"/kəˈnekʃən/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"a relationship between people, things, or ideas","vi":"mối liên hệ; sự liên quan"},{"pos":"n.","en":"a link that allows devices or systems to work together","vi":"kết nối; sự kết nối"},{"pos":"n.","en":"a further bus, train, or flight taken during a journey","vi":"chuyến chuyển tiếp; phương tiện nối chuyến"}],"examples":[{"en":"Our internet connection stopped working during the storm.","vi":"Kết nối internet của chúng tôi đã ngừng hoạt động trong cơn bão.","audioKind":"ex"},{"en":"Researchers have found a strong connection between regular physical activity and improved mental health among young adults.","vi":"Các nhà nghiên cứu đã tìm thấy mối liên hệ mạnh mẽ giữa việc hoạt động thể chất thường xuyên và cải thiện sức khỏe tinh thần ở người trẻ tuổi.","audioKind":"ex2"}],"collocations":[{"en":"a connection between","vi":"mối liên hệ giữa"},{"en":"internet connection","vi":"kết nối internet"},{"en":"miss a connection","vi":"lỡ chuyến nối chuyến"},{"en":"in connection with","vi":"liên quan đến"}],"wordFamily":["connect (v.)","connected (adj.)","connectivity (n.)","disconnect (v.)"],"synonyms":["link","relationship"],"antonyms":[],"tipVi":"Biểu thị mối liên hệ giữa hai đối tượng dùng connection between A and B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inventor', 'en-b1-44', 'inventor', '/ɪnˈventər/', 'B1', 'nhà phát minh; người sáng chế', 'n.', 'invent (v.), invention (n.), inventive (adj.), inventiveness (n.)', NULL, 'inventor tạo ra thứ hoàn toàn mới; discoverer tìm ra thứ vốn đã tồn tại.', 'The inventor showed us a lamp powered by sunlight.', NULL, 'Nhà phát minh đã cho chúng tôi xem một chiếc đèn chạy bằng năng lượng mặt trời.', '{"wordId":"inventor","ukIpa":"/ɪnˈventə/","usIpa":"/ɪnˈventər/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"someone who creates a device or process not previously existing","vi":"nhà phát minh; người sáng chế"}],"examples":[{"en":"The inventor showed us a lamp powered by sunlight.","vi":"Nhà phát minh đã cho chúng tôi xem một chiếc đèn chạy bằng năng lượng mặt trời.","audioKind":"ex"},{"en":"Inventors often need financial support to turn promising ideas into practical technologies that benefit society.","vi":"Các nhà phát minh thường cần sự hỗ trợ tài chính để biến những ý tưởng đầy hứa hẹn thành công nghệ thực tiễn mang lại lợi ích cho xã hội.","audioKind":"ex2"}],"collocations":[{"en":"a brilliant inventor","vi":"một nhà phát minh lỗi lạc"},{"en":"the inventor of","vi":"nhà phát minh của..."},{"en":"an aspiring inventor","vi":"một người có hoài bão làm nhà phát minh"}],"wordFamily":["invent (v.)","invention (n.)","inventive (adj.)","inventiveness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"inventor tạo ra thứ hoàn toàn mới; discoverer tìm ra thứ vốn đã tồn tại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_typewriter', 'en-b1-44', 'typewriter', '/ˈtaɪpraɪtər/', 'B1', 'máy đánh chữ', 'n.', 'type (v.), typist (n.), typing (n.)', NULL, 'typewriter chỉ máy đánh chữ, còn typist chỉ nhân viên đánh máy.', 'My grandfather still uses a typewriter to write short stories.', NULL, 'Ông tôi vẫn dùng máy đánh chữ để viết truyện ngắn.', '{"wordId":"typewriter","ukIpa":"/ˈtaɪpraɪtə/","usIpa":"/ˈtaɪpraɪtər/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"A machine with keys that print characters directly onto paper.","vi":"máy đánh chữ"}],"examples":[{"en":"My grandfather still uses a typewriter to write short stories.","vi":"Ông tôi vẫn dùng máy đánh chữ để viết truyện ngắn.","audioKind":"ex"},{"en":"Before computers became widespread, the typewriter was an essential tool in offices and newsrooms.","vi":"Trước khi máy tính trở nên phổ biến, máy đánh chữ là công cụ thiết yếu trong các văn phòng và phòng tòa soạn báo.","audioKind":"ex2"}],"collocations":[{"en":"manual typewriter","vi":"máy đánh chữ thủ công"},{"en":"electric typewriter","vi":"máy đánh chữ điện"},{"en":"typewriter ribbon","vi":"băng mực máy đánh chữ"}],"wordFamily":["type (v.)","typist (n.)","typing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"typewriter chỉ máy đánh chữ, còn typist chỉ nhân viên đánh máy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_install', 'en-b1-44', 'install', '/ɪnˈstɔːl/', 'B1', 'lắp đặt; cài đặt; chính thức bổ nhiệm; đưa vào vị trí', 'v.', 'installation (n.), installer (n.), reinstall (v.)', 'Đồng nghĩa: fit, set up · Trái nghĩa: uninstall', 'Tải xuống là download; sau khi tải xuống xong và tiến hành đưa vào máy để dùng thì là install.', 'We hired an electrician to install the new ceiling fan.', NULL, 'Chúng tôi đã thuê một thợ điện đến lắp chiếc quạt trần mới.', '{"wordId":"install","ukIpa":"/ɪnˈstɔːl/","usIpa":"/ɪnˈstɔːl/","cefr":"B1","topic":"technology","senses":[{"pos":"v.","en":"to put equipment or software in place for use","vi":"lắp đặt; cài đặt"},{"pos":"v.","en":"to formally place someone in an important position","vi":"chính thức bổ nhiệm; đưa vào vị trí"}],"examples":[{"en":"We hired an electrician to install the new ceiling fan.","vi":"Chúng tôi đã thuê một thợ điện đến lắp chiếc quạt trần mới.","audioKind":"ex"},{"en":"Schools need sufficient funding to install reliable internet connections and maintain essential digital equipment.","vi":"Các trường học cần có đủ kinh phí để lắp đặt kết nối internet ổn định và duy trì các thiết bị kỹ thuật số thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"install software","vi":"cài đặt phần mềm"},{"en":"install solar panels","vi":"lắp đặt pin mặt trời"},{"en":"install an alarm","vi":"lắp đặt hệ thống báo động"}],"wordFamily":["installation (n.)","installer (n.)","reinstall (v.)"],"synonyms":["fit","set up"],"antonyms":["uninstall"],"tipVi":"Tải xuống là download; sau khi tải xuống xong và tiến hành đưa vào máy để dùng thì là install.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delete', 'en-b1-44', 'delete', '/dɪˈliːt/', 'B1', 'xóa; loại bỏ', 'v.', 'deletion (n.)', 'Đồng nghĩa: remove, erase · Trái nghĩa: insert', 'Thường dùng delete something from... để chỉ việc xóa cái gì đó khỏi một nơi nào đó.', 'Please delete those blurry photos from my phone.', NULL, 'Làm ơn xóa những bức ảnh bị mờ đó khỏi điện thoại của tôi.', '{"wordId":"delete","ukIpa":"/dɪˈliːt/","usIpa":"/dɪˈliːt/","cefr":"B1","topic":"technology","senses":[{"pos":"v.","en":"To remove written material or stored information.","vi":"xóa; loại bỏ"}],"examples":[{"en":"Please delete those blurry photos from my phone.","vi":"Làm ơn xóa những bức ảnh bị mờ đó khỏi điện thoại của tôi.","audioKind":"ex"},{"en":"Online services should allow users to delete their personal data when they no longer need an account.","vi":"Các dịch vụ trực tuyến nên cho phép người dùng xóa dữ liệu cá nhân của họ khi họ không còn cần tài khoản nữa.","audioKind":"ex2"}],"collocations":[{"en":"delete a file","vi":"xóa một tệp tin"},{"en":"delete an account","vi":"xóa một tài khoản"},{"en":"permanently delete","vi":"xóa vĩnh viễn"}],"wordFamily":["deletion (n.)"],"synonyms":["remove","erase"],"antonyms":["insert"],"tipVi":"Thường dùng delete something from... để chỉ việc xóa cái gì đó khỏi một nơi nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invention', 'en-b1-44', 'invention', '/ɪnˈvenʃən/', 'B1', 'vật phát minh; phát minh; sự phát minh; sự sáng tạo; điều bịa đặt; chuyện hoang đường', 'n.', 'invent (v.), inventor (n.), inventive (adj.), inventiveness (n.)', NULL, 'invention chỉ việc tạo ra thứ vốn chưa từng tồn tại; trong khi discovery là việc tìm ra thứ đã có sẵn.', 'Her latest invention waters the plants while she is away.', NULL, 'Phát minh mới nhất của cô ấy giúp tưới cây tự động trong lúc cô ấy đi vắng.', '{"wordId":"invention","ukIpa":"/ɪnˈvenʃən/","usIpa":"/ɪnˈvenʃən/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"something new that someone has designed or created","vi":"vật phát minh; phát minh"},{"pos":"n.","en":"the act of creating something that did not exist before","vi":"sự phát minh; sự sáng tạo"},{"pos":"n.","en":"a story or explanation created rather than based on facts","vi":"điều bịa đặt; chuyện hoang đường"}],"examples":[{"en":"Her latest invention waters the plants while she is away.","vi":"Phát minh mới nhất của cô ấy giúp tưới cây tự động trong lúc cô ấy đi vắng.","audioKind":"ex"},{"en":"The invention of affordable water filters has improved public health in communities with limited access to clean water.","vi":"Sự ra đời của các thiết bị lọc nước giá rẻ đã cải thiện sức khỏe cộng đồng ở những cộng đồng ít có khả năng tiếp cận nguồn nước sạch.","audioKind":"ex2"}],"collocations":[{"en":"a useful invention","vi":"một phát minh hữu ích"},{"en":"the invention of","vi":"sự phát minh ra..."},{"en":"a recent invention","vi":"một phát minh gần đây"}],"wordFamily":["invent (v.)","inventor (n.)","inventive (adj.)","inventiveness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"invention chỉ việc tạo ra thứ vốn chưa từng tồn tại; trong khi discovery là việc tìm ra thứ đã có sẵn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disk', 'en-b1-44', 'disk', '/dɪsk/', 'B1', 'đĩa máy tính; ổ đĩa; vật hình đĩa tròn và mỏng', 'n.', NULL, NULL, 'Đĩa máy tính dùng từ disk; trong khi các vật hình đĩa hoặc đĩa quang ở Anh thường viết là disc.', 'My laptop''s disk is almost full of holiday photos.', NULL, 'Ổ đĩa trên máy tính xách tay của tôi hầu như đã đầy ảnh đi nghỉ mát.', '{"wordId":"disk","ukIpa":"/dɪsk/","usIpa":"/dɪsk/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"a device that stores computer data on a circular surface","vi":"đĩa máy tính; ổ đĩa"},{"pos":"n.","en":"a flat, thin, round object","vi":"vật hình đĩa tròn và mỏng"}],"examples":[{"en":"My laptop''s disk is almost full of holiday photos.","vi":"Ổ đĩa trên máy tính xách tay của tôi hầu như đã đầy ảnh đi nghỉ mát.","audioKind":"ex"},{"en":"Regular backups protect important research data against accidental deletion and unexpected disk failure in university computer systems.","vi":"Việc sao lưu thường xuyên giúp bảo vệ dữ liệu nghiên cứu quan trọng khỏi việc bị xóa nhầm và lỗi ổ đĩa bất ngờ trong hệ thống máy tính của trường đại học.","audioKind":"ex2"}],"collocations":[{"en":"hard disk","vi":"ổ cứng"},{"en":"disk space","vi":"dung lượng đĩa"},{"en":"disk drive","vi":"ổ đĩa"},{"en":"disk failure","vi":"lỗi ổ đĩa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đĩa máy tính dùng từ disk; trong khi các vật hình đĩa hoặc đĩa quang ở Anh thường viết là disc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_upload', 'en-b1-44', 'upload', '/ˌʌpˈloʊd/', 'B1', 'tải lên; quá trình tải lên; dữ liệu tải lên', 'v.', 'uploader (n.)', 'Trái nghĩa: download', 'Tải lên dùng upload, tải xuống dùng download; tải lên một nơi nào đó dùng từ to.', 'I uploaded our picnic photos to a shared folder.', NULL, 'Tôi đã tải những bức ảnh đi dã ngoại của chúng tôi lên một thư mục dùng chung.', '{"wordId":"upload","ukIpa":"/ˌʌpˈləʊd/","usIpa":"/ˌʌpˈloʊd/","cefr":"B1","topic":"technology","senses":[{"pos":"v.","en":"to transfer files from a device to an online system","vi":"tải lên"},{"pos":"n.","en":"the transfer of a file online, or the file itself","vi":"quá trình tải lên; dữ liệu tải lên"}],"examples":[{"en":"I uploaded our picnic photos to a shared folder.","vi":"Tôi đã tải những bức ảnh đi dã ngoại của chúng tôi lên một thư mục dùng chung.","audioKind":"ex"},{"en":"Students can upload their assignments to a secure platform, allowing teachers to provide timely feedback.","vi":"Học sinh có thể tải bài tập lên một nền tảng bảo mật, giúp giáo viên đưa ra phản hồi kịp thời.","audioKind":"ex2"}],"collocations":[{"en":"upload a file","vi":"tải tệp lên"},{"en":"upload photos","vi":"tải ảnh lên"},{"en":"upload to a server","vi":"tải lên máy chủ"}],"wordFamily":["uploader (n.)"],"synonyms":[],"antonyms":["download"],"tipVi":"Tải lên dùng upload, tải xuống dùng download; tải lên một nơi nào đó dùng từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_network', 'en-b1-44', 'network', '/ˈnetwɝːk/', 'B1', 'mạng lưới; hệ thống kết nối; mạng phát sóng; xây dựng quan hệ xã hội; mở rộng mạng lưới quan hệ', 'n.', 'networking (n.)', NULL, 'network nhấn mạnh sự liên kết giữa nhiều nút hoặc thành phần.', 'Our home network connects three laptops and a printer.', NULL, 'Mạng gia đình của chúng tôi kết nối ba máy tính xách tay và một máy in.', '{"wordId":"network","ukIpa":"/ˈnetwɜːk/","usIpa":"/ˈnetwɝːk/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"A system of connected people, things or places.","vi":"mạng lưới; hệ thống kết nối"},{"pos":"n.","en":"A group of broadcasting stations sharing programmes.","vi":"mạng phát sóng"},{"pos":"v.","en":"To meet people and develop useful professional relationships.","vi":"xây dựng quan hệ xã hội; mở rộng mạng lưới quan hệ"}],"examples":[{"en":"Our home network connects three laptops and a printer.","vi":"Mạng gia đình của chúng tôi kết nối ba máy tính xách tay và một máy in.","audioKind":"ex"},{"en":"An efficient public transport network can reduce traffic congestion and improve access to employment.","vi":"Mạng lưới giao thông công cộng hiệu quả có thể giảm thiểu ùn tắc giao thông và cải thiện khả năng tiếp cận việc làm.","audioKind":"ex2"}],"collocations":[{"en":"transport network","vi":"mạng lưới giao thông"},{"en":"wireless network","vi":"mạng không dây"},{"en":"support network","vi":"mạng lưới hỗ trợ"},{"en":"network with colleagues","vi":"mở rộng quan hệ với đồng nghiệp"}],"wordFamily":["networking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"network nhấn mạnh sự liên kết giữa nhiều nút hoặc thành phần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_version', 'en-b1-44', 'version', '/ˈvɝːʒn/', 'B1', 'phiên bản; lời kể; góc nhìn (của một người)', 'n.', NULL, NULL, 'version chỉ các hình thức khác nhau của cùng một sự vật, hoặc lời trần thuật của cá nhân về một sự việc.', 'The new version of this app loads much faster.', NULL, 'Phiên bản mới của ứng dụng này tải nhanh hơn rất nhiều.', '{"wordId":"version","ukIpa":"/ˈvɜːʃn/","usIpa":"/ˈvɝːʒn/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"A particular form of something that exists in different forms","vi":"phiên bản"},{"pos":"n.","en":"One person''s account of an event","vi":"lời kể; góc nhìn (của một người)"}],"examples":[{"en":"The new version of this app loads much faster.","vi":"Phiên bản mới của ứng dụng này tải nhanh hơn rất nhiều.","audioKind":"ex"},{"en":"Comparing each witness''s version of events helps investigators develop a more accurate understanding of what happened.","vi":"Việc so sánh lời kể của từng nhân chứng về sự kiện giúp các nhà điều tra có cái nhìn chính xác hơn về những gì đã xảy ra.","audioKind":"ex2"}],"collocations":[{"en":"the latest version","vi":"phiên bản mới nhất"},{"en":"an updated version","vi":"phiên bản cập nhật"},{"en":"a version of events","vi":"lời kể về một sự việc"},{"en":"a film version","vi":"bản dựng điện ảnh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"version chỉ các hình thức khác nhau của cùng một sự vật, hoặc lời trần thuật của cá nhân về một sự việc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_advanced', 'en-b1-44', 'advanced', '/ədˈvænst/', 'B1', 'tiên tiến; hiện đại; nâng cao; cao cấp; về sau; ở giai đoạn muộn', 'adj.', 'advance (v.), advance (n.), advancement (n.)', 'Đồng nghĩa: sophisticated, high-level · Trái nghĩa: basic, elementary', 'advanced diễn tả tính tiên tiến hoặc trình độ cao; cụm từ ''thông báo trước'' phải dùng advance notice.', 'This advanced camera takes clear pictures even at night.', NULL, 'Chiếc máy ảnh tiên tiến này chụp được những bức ảnh rõ nét ngay cả vào ban đêm.', '{"wordId":"advanced","ukIpa":"/ədˈvɑːnst/","usIpa":"/ədˈvænst/","cefr":"B1","topic":"technology","senses":[{"pos":"adj.","en":"using highly developed technology or methods","vi":"tiên tiến; hiện đại"},{"pos":"adj.","en":"requiring knowledge or skills beyond a basic level","vi":"nâng cao; cao cấp"},{"pos":"adj.","en":"having reached a late stage of development or progress","vi":"về sau; ở giai đoạn muộn"}],"examples":[{"en":"This advanced camera takes clear pictures even at night.","vi":"Chiếc máy ảnh tiên tiến này chụp được những bức ảnh rõ nét ngay cả vào ban đêm.","audioKind":"ex"},{"en":"Advanced medical technology can improve patient outcomes, but its high cost may increase inequalities in healthcare access.","vi":"Công nghệ y tế tiên tiến có thể cải thiện kết quả điều trị cho bệnh nhân, nhưng chi phí cao của nó có thể làm gia tăng sự bất bình đẳng trong việc tiếp cận dịch vụ y tế.","audioKind":"ex2"}],"collocations":[{"en":"advanced technology","vi":"công nghệ tiên tiến"},{"en":"advanced learners","vi":"người học trình độ cao"},{"en":"at an advanced stage","vi":"ở giai đoạn muộn"},{"en":"advanced level","vi":"trình độ nâng cao"}],"wordFamily":["advance (v.)","advance (n.)","advancement (n.)"],"synonyms":["sophisticated","high-level"],"antonyms":["basic","elementary"],"tipVi":"advanced diễn tả tính tiên tiến hoặc trình độ cao; cụm từ ''thông báo trước'' phải dùng advance notice.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_earphone', 'en-b1-44', 'earphone', '/ˈɪrfoʊn/', 'B1', 'tai nghe; tai nghe nhét tai', 'n.', NULL, NULL, 'Thường được dùng ở dạng số nhiều là earphones; khi chỉ một bộ tai nghe thì dùng a pair of.', 'One earphone fell out while I was jogging.', NULL, 'Một bên tai nghe bị rơi ra khi tôi đang chạy bộ.', '{"wordId":"earphone","ukIpa":"/ˈɪəfəʊn/","usIpa":"/ˈɪrfoʊn/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"A small device worn in or over an ear for listening","vi":"tai nghe; tai nghe nhét tai"}],"examples":[{"en":"One earphone fell out while I was jogging.","vi":"Một bên tai nghe bị rơi ra khi tôi đang chạy bộ.","audioKind":"ex"},{"en":"Students using earphones in shared study spaces can listen to educational recordings without disturbing others.","vi":"Học sinh sử dụng tai nghe ở không gian tự học chung có thể nghe các bản ghi âm học tập mà không làm phiền người khác.","audioKind":"ex2"}],"collocations":[{"en":"a pair of earphones","vi":"một cặp tai nghe"},{"en":"wireless earphones","vi":"tai nghe không dây"},{"en":"wear earphones","vi":"đeo tai nghe"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường được dùng ở dạng số nhiều là earphones; khi chỉ một bộ tai nghe thì dùng a pair of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_code', 'en-b1-44', 'code', '/koʊd/', 'B1', 'mã; mật mã; mã máy tính; quy tắc; chuẩn mực ứng xử; lập trình; mã hóa', 'n.', 'coding (n.), coder (n.), encode (v.), decode (v.)', NULL, 'Mã chương trình máy tính thường không đếm được; một dãy mật mã có thể dùng a code.', 'I forgot the code for my bicycle lock again.', NULL, 'Tôi lại quên mất mã khóa xe đạp của mình rồi.', '{"wordId":"code","ukIpa":"/kəʊd/","usIpa":"/koʊd/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"Symbols or instructions representing information, including instructions for computers","vi":"mã; mật mã; mã máy tính"},{"pos":"n.","en":"A set of rules governing behaviour or practice","vi":"quy tắc; chuẩn mực ứng xử"},{"pos":"v.","en":"Write computer instructions or convert information into a coded form","vi":"lập trình; mã hóa"}],"examples":[{"en":"I forgot the code for my bicycle lock again.","vi":"Tôi lại quên mất mã khóa xe đạp của mình rồi.","audioKind":"ex"},{"en":"Teaching students to write code can strengthen problem-solving skills and prepare them for a changing job market.","vi":"Dạy học sinh viết mã lập trình có thể nâng cao kỹ năng giải quyết vấn đề và chuẩn bị cho các em trước thị trường lao động đang thay đổi.","audioKind":"ex2"}],"collocations":[{"en":"write code","vi":"viết mã"},{"en":"access code","vi":"mã truy cập"},{"en":"code of conduct","vi":"quy tắc ứng xử"},{"en":"dress code","vi":"quy định trang phục"}],"wordFamily":["coding (n.)","coder (n.)","encode (v.)","decode (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Mã chương trình máy tính thường không đếm được; một dãy mật mã có thể dùng a code.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_automatic', 'en-b1-44', 'automatic', '/ˌɔːtəˈmætɪk/', 'B1', 'tự động; bản năng; vô thức; tất yếu xảy ra', 'adj.', 'automatically (adv.), automate (v.), automation (n.)', 'Trái nghĩa: manual', 'Có thể chỉ máy móc hoạt động tự động, hoặc chỉ phản ứng không cần suy nghĩ của con người.', 'The automatic doors opened as I approached the supermarket.', NULL, 'Cửa tự động mở ra khi tôi tiến lại gần siêu thị.', '{"wordId":"automatic","ukIpa":"/ˌɔːtəˈmætɪk/","usIpa":"/ˌɔːtəˈmætɪk/","cefr":"B1","topic":"technology","senses":[{"pos":"adj.","en":"Working by itself without direct human control.","vi":"tự động"},{"pos":"adj.","en":"Done without conscious thought or deliberate effort.","vi":"bản năng; vô thức"},{"pos":"adj.","en":"Happening as a direct result without a separate decision.","vi":"tất yếu xảy ra"}],"examples":[{"en":"The automatic doors opened as I approached the supermarket.","vi":"Cửa tự động mở ra khi tôi tiến lại gần siêu thị.","audioKind":"ex"},{"en":"Automatic lighting systems can reduce energy consumption by switching off when nobody is present in a room.","vi":"Hệ thống chiếu sáng tự động có thể giảm mức tiêu thụ năng lượng bằng cách tự tắt khi không có ai trong phòng.","audioKind":"ex2"}],"collocations":[{"en":"automatic doors","vi":"cửa tự động"},{"en":"automatic response","vi":"phản ứng tự động"},{"en":"automatic renewal","vi":"gia hạn tự động"}],"wordFamily":["automatically (adv.)","automate (v.)","automation (n.)"],"synonyms":[],"antonyms":["manual"],"tipVi":"Có thể chỉ máy móc hoạt động tự động, hoặc chỉ phản ứng không cần suy nghĩ của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_device', 'en-b1-44', 'device', '/dɪˈvaɪs/', 'B1', 'thiết bị; dụng cụ; máy móc; thủ thuật; biện pháp; phương kế', 'n.', 'devise (v.)', 'Đồng nghĩa: gadget, instrument', 'device là danh từ; devise là động từ, mang nghĩa là thiết kế hoặc nghĩ ra.', 'This tiny device tracks my steps throughout the day.', NULL, 'Thiết bị nhỏ bé này theo dõi số bước đi của tôi trong suốt cả ngày.', '{"wordId":"device","ukIpa":"/dɪˈvaɪs/","usIpa":"/dɪˈvaɪs/","cefr":"B1","topic":"technology","senses":[{"pos":"n.","en":"an object or machine designed for a particular purpose","vi":"thiết bị; dụng cụ; máy móc"},{"pos":"n.","en":"a method used to achieve an effect or particular result","vi":"thủ thuật; biện pháp; phương kế"}],"examples":[{"en":"This tiny device tracks my steps throughout the day.","vi":"Thiết bị nhỏ bé này theo dõi số bước đi của tôi trong suốt cả ngày.","audioKind":"ex"},{"en":"A portable medical device can help patients monitor their health without frequent hospital visits.","vi":"Một thiết bị y tế cầm tay có thể giúp bệnh nhân theo dõi sức khỏe mà không cần phải đến bệnh viện thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"an electronic device","vi":"thiết bị điện tử"},{"en":"a medical device","vi":"thiết bị y tế"},{"en":"a safety device","vi":"thiết bị an toàn"},{"en":"a literary device","vi":"thủ pháp văn học"}],"wordFamily":["devise (v.)"],"synonyms":["gadget","instrument"],"antonyms":[],"tipVi":"device là danh từ; devise là động từ, mang nghĩa là thiết kế hoặc nghĩ ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_44_1', 'en-b1-44', 'Cách dùng “version” (n.) — phiên bản', 'the latest version  ·  an updated version  ·  a version of events', 'version chỉ các hình thức khác nhau của cùng một sự vật, hoặc lời trần thuật của cá nhân về một sự việc.', NULL, '[{"hanzi":"The new version of this app loads much faster.","pinyin":"","meaning":"Phiên bản mới của ứng dụng này tải nhanh hơn rất nhiều."},{"hanzi":"Comparing each witness''s version of events helps investigators develop a more accurate understanding of what happened.","pinyin":"","meaning":"Việc so sánh lời kể của từng nhân chứng về sự kiện giúp các nhà điều tra có cái nhìn chính xác hơn về những gì đã xảy ra."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_44_2', 'en-b1-44', 'Cách dùng “invention” (n.) — vật phát minh; phát minh', 'a useful invention  ·  the invention of  ·  a recent invention', 'invention chỉ việc tạo ra thứ vốn chưa từng tồn tại; trong khi discovery là việc tìm ra thứ đã có sẵn.', 'Họ từ (Word Family): invent (v.), inventor (n.), inventive (adj.), inventiveness (n.)', '[{"hanzi":"Her latest invention waters the plants while she is away.","pinyin":"","meaning":"Phát minh mới nhất của cô ấy giúp tưới cây tự động trong lúc cô ấy đi vắng."},{"hanzi":"The invention of affordable water filters has improved public health in communities with limited access to clean water.","pinyin":"","meaning":"Sự ra đời của các thiết bị lọc nước giá rẻ đã cải thiện sức khỏe cộng đồng ở những cộng đồng ít có khả năng tiếp cận nguồn nước sạch."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_44_3', 'en-b1-44', 'Cách dùng “advanced” (adj.) — tiên tiến; hiện đại', 'advanced technology  ·  advanced learners  ·  at an advanced stage', 'advanced diễn tả tính tiên tiến hoặc trình độ cao; cụm từ ''thông báo trước'' phải dùng advance notice.', 'Họ từ (Word Family): advance (v.), advance (n.), advancement (n.) | Đồng nghĩa: sophisticated, high-level · Trái nghĩa: basic, elementary', '[{"hanzi":"This advanced camera takes clear pictures even at night.","pinyin":"","meaning":"Chiếc máy ảnh tiên tiến này chụp được những bức ảnh rõ nét ngay cả vào ban đêm."},{"hanzi":"Advanced medical technology can improve patient outcomes, but its high cost may increase inequalities in healthcare access.","pinyin":"","meaning":"Công nghệ y tế tiên tiến có thể cải thiện kết quả điều trị cho bệnh nhân, nhưng chi phí cao của nó có thể làm gia tăng sự bất bình đẳng trong việc tiếp cận dịch vụ y tế."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_44_4', 'en-b1-44', 'Cách dùng “disk” (n.) — đĩa máy tính; ổ đĩa', 'hard disk  ·  disk space  ·  disk drive', 'Đĩa máy tính dùng từ disk; trong khi các vật hình đĩa hoặc đĩa quang ở Anh thường viết là disc.', NULL, '[{"hanzi":"My laptop''s disk is almost full of holiday photos.","pinyin":"","meaning":"Ổ đĩa trên máy tính xách tay của tôi hầu như đã đầy ảnh đi nghỉ mát."},{"hanzi":"Regular backups protect important research data against accidental deletion and unexpected disk failure in university computer systems.","pinyin":"","meaning":"Việc sao lưu thường xuyên giúp bảo vệ dữ liệu nghiên cứu quan trọng khỏi việc bị xóa nhầm và lỗi ổ đĩa bất ngờ trong hệ thống máy tính của trường đại học."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_44_1', 'en-b1-44', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_1_1', 'ten_b1_44_1', 'connection', 'Our internet connection stopped working during the storm.', 'Our internet connection stopped working during the storm.', '/kəˈnekʃən/', 'Kết nối internet của chúng tôi đã ngừng hoạt động trong cơn bão.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_1_2', 'ten_b1_44_1', 'inventor', 'The inventor showed us a lamp powered by sunlight.', 'The inventor showed us a lamp powered by sunlight.', '/ɪnˈventər/', 'Nhà phát minh đã cho chúng tôi xem một chiếc đèn chạy bằng năng lượng mặt trời.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_1_3', 'ten_b1_44_1', 'typewriter', 'My grandfather still uses a typewriter to write short stories.', 'My grandfather still uses a typewriter to write short stories.', '/ˈtaɪpraɪtər/', 'Ông tôi vẫn dùng máy đánh chữ để viết truyện ngắn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_1_4', 'ten_b1_44_1', 'install', 'We hired an electrician to install the new ceiling fan.', 'We hired an electrician to install the new ceiling fan.', '/ɪnˈstɔːl/', 'Chúng tôi đã thuê một thợ điện đến lắp chiếc quạt trần mới.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_1_5', 'ten_b1_44_1', 'delete', 'Please delete those blurry photos from my phone.', 'Please delete those blurry photos from my phone.', '/dɪˈliːt/', 'Làm ơn xóa những bức ảnh bị mờ đó khỏi điện thoại của tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_1_6', 'ten_b1_44_1', 'invention', 'Her latest invention waters the plants while she is away.', 'Her latest invention waters the plants while she is away.', '/ɪnˈvenʃən/', 'Phát minh mới nhất của cô ấy giúp tưới cây tự động trong lúc cô ấy đi vắng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_1_7', 'ten_b1_44_1', 'disk', 'My laptop''s disk is almost full of holiday photos.', 'My laptop''s disk is almost full of holiday photos.', '/dɪsk/', 'Ổ đĩa trên máy tính xách tay của tôi hầu như đã đầy ảnh đi nghỉ mát.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_1_8', 'ten_b1_44_1', 'upload', 'I uploaded our picnic photos to a shared folder.', 'I uploaded our picnic photos to a shared folder.', '/ˌʌpˈloʊd/', 'Tôi đã tải những bức ảnh đi dã ngoại của chúng tôi lên một thư mục dùng chung.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_44_1_1', 'en-b1-44', 'ten_b1_44_1', 'listening', 'listening', 'Our internet connection stopped working during the storm.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc máy ảnh tiên tiến này chụp được những bức ảnh rõ nét ngay cả vào ban đêm.","Kết nối internet của chúng tôi đã ngừng hoạt động trong cơn bão.","Tôi lại quên mất mã khóa xe đạp của mình rồi.","Làm ơn xóa những bức ảnh bị mờ đó khỏi điện thoại của tôi."]'::jsonb, 1, 'Our internet connection stopped working during the storm. → Kết nối internet của chúng tôi đã ngừng hoạt động trong cơn bão.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_44_1_2', 'en-b1-44', 'ten_b1_44_1', 'listening', 'listening', 'The inventor showed us a lamp powered by sunlight.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cửa tự động mở ra khi tôi tiến lại gần siêu thị.","Nhà phát minh đã cho chúng tôi xem một chiếc đèn chạy bằng năng lượng mặt trời.","Tôi lại quên mất mã khóa xe đạp của mình rồi.","Một bên tai nghe bị rơi ra khi tôi đang chạy bộ."]'::jsonb, 1, 'The inventor showed us a lamp powered by sunlight. → Nhà phát minh đã cho chúng tôi xem một chiếc đèn chạy bằng năng lượng mặt trời.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_44_1_3', 'en-b1-44', 'ten_b1_44_1', 'listening', 'listening', 'My grandfather still uses a typewriter to write short stories.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Phát minh mới nhất của cô ấy giúp tưới cây tự động trong lúc cô ấy đi vắng.","Ông tôi vẫn dùng máy đánh chữ để viết truyện ngắn.","Phiên bản mới của ứng dụng này tải nhanh hơn rất nhiều.","Chiếc máy ảnh tiên tiến này chụp được những bức ảnh rõ nét ngay cả vào ban đêm."]'::jsonb, 1, 'My grandfather still uses a typewriter to write short stories. → Ông tôi vẫn dùng máy đánh chữ để viết truyện ngắn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_44_2', 'en-b1-44', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_2_1', 'ten_b1_44_2', 'connection', 'Researchers have found a strong connection between regular physical activity and improved mental health among young adults.', 'Researchers have found a strong connection between regular physical activity and improved mental health among young adults.', '/kəˈnekʃən/', 'Các nhà nghiên cứu đã tìm thấy mối liên hệ mạnh mẽ giữa việc hoạt động thể chất thường xuyên và cải thiện sức khỏe tinh thần ở người trẻ tuổi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_2_2', 'ten_b1_44_2', 'inventor', 'Inventors often need financial support to turn promising ideas into practical technologies that benefit society.', 'Inventors often need financial support to turn promising ideas into practical technologies that benefit society.', '/ɪnˈventər/', 'Các nhà phát minh thường cần sự hỗ trợ tài chính để biến những ý tưởng đầy hứa hẹn thành công nghệ thực tiễn mang lại lợi ích cho xã hội.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_2_3', 'ten_b1_44_2', 'typewriter', 'Before computers became widespread, the typewriter was an essential tool in offices and newsrooms.', 'Before computers became widespread, the typewriter was an essential tool in offices and newsrooms.', '/ˈtaɪpraɪtər/', 'Trước khi máy tính trở nên phổ biến, máy đánh chữ là công cụ thiết yếu trong các văn phòng và phòng tòa soạn báo.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_2_4', 'ten_b1_44_2', 'install', 'Schools need sufficient funding to install reliable internet connections and maintain essential digital equipment.', 'Schools need sufficient funding to install reliable internet connections and maintain essential digital equipment.', '/ɪnˈstɔːl/', 'Các trường học cần có đủ kinh phí để lắp đặt kết nối internet ổn định và duy trì các thiết bị kỹ thuật số thiết yếu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_2_5', 'ten_b1_44_2', 'delete', 'Online services should allow users to delete their personal data when they no longer need an account.', 'Online services should allow users to delete their personal data when they no longer need an account.', '/dɪˈliːt/', 'Các dịch vụ trực tuyến nên cho phép người dùng xóa dữ liệu cá nhân của họ khi họ không còn cần tài khoản nữa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_44_2_6', 'ten_b1_44_2', 'invention', 'The invention of affordable water filters has improved public health in communities with limited access to clean water.', 'The invention of affordable water filters has improved public health in communities with limited access to clean water.', '/ɪnˈvenʃən/', 'Sự ra đời của các thiết bị lọc nước giá rẻ đã cải thiện sức khỏe cộng đồng ở những cộng đồng ít có khả năng tiếp cận nguồn nước sạch.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_44_2_1', 'en-b1-44', 'ten_b1_44_2', 'listening', 'listening', 'Researchers have found a strong connection between regular physical activity and improved mental health among young adults.', NULL, 'Trong câu vừa nghe, từ “connection” mang nghĩa nào sau đây?', '["việc ăn uống; dùng bữa","Manila (thủ đô của Philippines)","phiếu giảm giá; phiếu ưu đãi","mối liên hệ; sự liên quan"]'::jsonb, 3, '“connection” (/kəˈnekʃən/): mối liên hệ; sự liên quan. Câu đầy đủ: Researchers have found a strong connection between regular physical activity and improved mental health among young adults.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_44_2_2', 'en-b1-44', 'ten_b1_44_2', 'listening', 'listening', 'Inventors often need financial support to turn promising ideas into practical technologies that benefit society.', NULL, 'Trong câu vừa nghe, từ “inventor” mang nghĩa nào sau đây?', '["dỡ đồ (khỏi túi, hộp, vali)","núi lửa","nhà phát minh; người sáng chế","bột nhào (hỗn hợp bột và chất lỏng dùng để nướng)"]'::jsonb, 2, '“inventor” (/ɪnˈventər/): nhà phát minh; người sáng chế. Câu đầy đủ: Inventors often need financial support to turn promising ideas into practical technologies that benefit society.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
