INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_1', 'en-b1-44', NULL, 'comprehensive_test', 'listening', 'connection', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hầu như không; hầu như chẳng","mối liên hệ; sự liên quan","sống sót; tồn tại","chùm; bó; nải"]'::jsonb, 1, 'connection (/kəˈnekʃən/) → mối liên hệ; sự liên quan; kết nối; sự kết nối; chuyến chuyển tiếp; phương tiện nối chuyến', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_2', 'en-b1-44', NULL, 'comprehensive_test', 'listening', 'The inventor showed us a lamp powered by sunlight.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhà phát minh đã cho chúng tôi xem một chiếc đèn chạy bằng năng lượng mặt trời.","Phát minh mới nhất của cô ấy giúp tưới cây tự động trong lúc cô ấy đi vắng.","Ông tôi vẫn dùng máy đánh chữ để viết truyện ngắn.","Tôi lại quên mất mã khóa xe đạp của mình rồi."]'::jsonb, 0, 'The inventor showed us a lamp powered by sunlight. → Nhà phát minh đã cho chúng tôi xem một chiếc đèn chạy bằng năng lượng mặt trời.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_3', 'en-b1-44', NULL, 'comprehensive_test', 'listening', 'typewriter', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["máy đánh chữ","nhãn; mác","đĩa máy tính; ổ đĩa","làm tràn; làm đổ; làm rơi vãi"]'::jsonb, 0, 'typewriter (/ˈtaɪpraɪtər/) → máy đánh chữ', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_4', 'en-b1-44', NULL, 'comprehensive_test', 'listening', 'We hired an electrician to install the new ceiling fan.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một bên tai nghe bị rơi ra khi tôi đang chạy bộ.","Làm ơn xóa những bức ảnh bị mờ đó khỏi điện thoại của tôi.","Kết nối internet của chúng tôi đã ngừng hoạt động trong cơn bão.","Chúng tôi đã thuê một thợ điện đến lắp chiếc quạt trần mới."]'::jsonb, 3, 'We hired an electrician to install the new ceiling fan. → Chúng tôi đã thuê một thợ điện đến lắp chiếc quạt trần mới.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_5', 'en-b1-44', NULL, 'comprehensive_test', 'listening', 'delete', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["gót chân","chương (sách); hồi","hoàn hảo; không tì vết","xóa; loại bỏ"]'::jsonb, 3, 'delete (/dɪˈliːt/) → xóa; loại bỏ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_6', 'en-b1-44', NULL, 'comprehensive_test', 'listening', 'Her latest invention waters the plants while she is away.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Phát minh mới nhất của cô ấy giúp tưới cây tự động trong lúc cô ấy đi vắng.","Phiên bản mới của ứng dụng này tải nhanh hơn rất nhiều.","Ông tôi vẫn dùng máy đánh chữ để viết truyện ngắn.","Một bên tai nghe bị rơi ra khi tôi đang chạy bộ."]'::jsonb, 0, 'Her latest invention waters the plants while she is away. → Phát minh mới nhất của cô ấy giúp tưới cây tự động trong lúc cô ấy đi vắng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
