INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_8', 'en-b1-44', NULL, 'comprehensive_test', 'listening', 'I uploaded our picnic photos to a shared folder.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mạng gia đình của chúng tôi kết nối ba máy tính xách tay và một máy in.","Một bên tai nghe bị rơi ra khi tôi đang chạy bộ.","Tôi đã tải những bức ảnh đi dã ngoại của chúng tôi lên một thư mục dùng chung.","Ổ đĩa trên máy tính xách tay của tôi hầu như đã đầy ảnh đi nghỉ mát."]'::jsonb, 2, 'I uploaded our picnic photos to a shared folder. → Tôi đã tải những bức ảnh đi dã ngoại của chúng tôi lên một thư mục dùng chung.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
