INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_18', 'en-b1-44', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers have found a strong connection between regular physical activity and improved mental health among young adults.', 'Dựa vào câu trên, từ “connection” có nghĩa phù hợp nhất là gì?', '["sự an toàn; sự an tâm","hương vị; mùi vị","bài giảng; buổi thuyết trình","mối liên hệ; sự liên quan"]'::jsonb, 3, 'connection: mối liên hệ; sự liên quan; kết nối; sự kết nối; chuyến chuyển tiếp; phương tiện nối chuyến. Dịch cả câu: Các nhà nghiên cứu đã tìm thấy mối liên hệ mạnh mẽ giữa việc hoạt động thể chất thường xuyên và cải thiện sức khỏe tinh thần ở người trẻ tuổi.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_19', 'en-b1-44', NULL, 'comprehensive_test', 'reading', NULL, 'Inventors often need financial support to turn promising ideas into practical technologies that benefit society.', 'Dựa vào câu trên, từ “inventor” có nghĩa phù hợp nhất là gì?', '["nhà phát minh; người sáng chế","nguyên chất; tinh khiết","gồ ghề; xù xì; không bằng phẳng","cân nhắc; suy nghĩ kỹ lưỡng trước khi quyết định"]'::jsonb, 0, 'inventor: nhà phát minh; người sáng chế. Dịch cả câu: Các nhà phát minh thường cần sự hỗ trợ tài chính để biến những ý tưởng đầy hứa hẹn thành công nghệ thực tiễn mang lại lợi ích cho xã hội.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_20', 'en-b1-44', NULL, 'comprehensive_test', 'reading', NULL, 'Before computers became widespread, the typewriter was an essential tool in offices and newsrooms.', 'Dựa vào câu trên, từ “typewriter” có nghĩa phù hợp nhất là gì?', '["bìa cứng; giấy các-tông","máy đánh chữ","bị dị ứng; có dị ứng với","xuất khẩu; đem bán ra nước ngoài"]'::jsonb, 1, 'typewriter: máy đánh chữ. Dịch cả câu: Trước khi máy tính trở nên phổ biến, máy đánh chữ là công cụ thiết yếu trong các văn phòng và phòng tòa soạn báo.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_21', 'en-b1-44', NULL, 'comprehensive_test', 'reading', NULL, 'Schools need sufficient funding to install reliable internet connections and maintain essential digital equipment.', 'Dựa vào câu trên, từ “install” có nghĩa phù hợp nhất là gì?', '["thuộc vùng Nam Cực","áo khoác dài; áo măng-tô","lắp đặt; cài đặt","chứa; bao gồm"]'::jsonb, 2, 'install: lắp đặt; cài đặt; chính thức bổ nhiệm; đưa vào vị trí. Dịch cả câu: Các trường học cần có đủ kinh phí để lắp đặt kết nối internet ổn định và duy trì các thiết bị kỹ thuật số thiết yếu.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_22', 'en-b1-44', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “mã; mật mã; mã máy tính”', '["attract","feature","elbow","code"]'::jsonb, 3, 'mã; mật mã; mã máy tính → code (/koʊd/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_23', 'en-b1-44', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tự động”', '["beyond","time off","percentage","automatic"]'::jsonb, 3, 'tự động → automatic (/ˌɔːtəˈmætɪk/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_44_24', 'en-b1-44', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thiết bị; dụng cụ; máy móc”', '["reservation","stylish","olive","device"]'::jsonb, 3, 'thiết bị; dụng cụ; máy móc → device (/dɪˈvaɪs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-45', 'en', 'Bài 45: Khoa học & Nghiên cứu (1) - CEFR B1', 'CEFR B1', 'B1 · Khoa học', '18 từ vựng Tiếng Anh CEFR B1 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3045, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_measure', 'en-b1-45', 'measure', '/ˈmeʒər/', 'B1', 'đo lường; đánh giá; biện pháp; phương án; tiêu chuẩn đánh giá', 'v.', 'measurement (n.), measurable (adj.)', NULL, 'Cụm từ "take measures" nghĩa là thực hiện biện pháp; khi đo đạc vật gì có thể làm tân ngữ trực tiếp.', 'We measured the window before buying new curtains.', NULL, 'Chúng tôi đã đo kích thước cửa sổ trước khi mua rèm mới.', '{"wordId":"measure","ukIpa":"/ˈmeʒə/","usIpa":"/ˈmeʒər/","cefr":"B1","topic":"science","senses":[{"pos":"v.","en":"Find the size, amount, or degree of something.","vi":"đo lường; đánh giá"},{"pos":"n.","en":"An action intended to achieve a particular result.","vi":"biện pháp; phương án"},{"pos":"n.","en":"A way of judging the quality or degree of something.","vi":"tiêu chuẩn đánh giá"}],"examples":[{"en":"We measured the window before buying new curtains.","vi":"Chúng tôi đã đo kích thước cửa sổ trước khi mua rèm mới.","audioKind":"ex"},{"en":"Governments should introduce effective measures to reduce air pollution without placing excessive costs on low-income households.","vi":"Chính phủ nên đưa ra các biện pháp hiệu quả nhằm giảm ô nhiễm không khí mà không tạo ra gánh nặng chi phí quá mức cho các hộ gia đình thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"measure progress","vi":"đánh giá sự tiến bộ"},{"en":"take measures to do something","vi":"tiến hành các biện pháp để làm gì"},{"en":"a measure of success","vi":"một thước đo thành công"}],"wordFamily":["measurement (n.)","measurable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ \"take measures\" nghĩa là thực hiện biện pháp; khi đo đạc vật gì có thể làm tân ngữ trực tiếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_solar', 'en-b1-45', 'solar', '/ˈsoʊlər/', 'B1', 'thuộc về mặt trời; dùng năng lượng mặt trời', 'adj.', NULL, NULL, 'solar là tính từ, thường dùng trong các cụm từ liên quan đến mặt trời hoặc năng lượng mặt trời.', 'We wore special protective glasses to watch the solar eclipse.', NULL, 'Chúng tôi đã đeo kính bảo vệ chuyên dụng để quan sát hiện tượng nhật thực.', '{"wordId":"solar","ukIpa":"/ˈsəʊlə/","usIpa":"/ˈsoʊlər/","cefr":"B1","topic":"science","senses":[{"pos":"adj.","en":"Relating to the sun.","vi":"thuộc về mặt trời"},{"pos":"adj.","en":"Using energy from sunlight to produce heat or electricity.","vi":"dùng năng lượng mặt trời"}],"examples":[{"en":"We wore special protective glasses to watch the solar eclipse.","vi":"Chúng tôi đã đeo kính bảo vệ chuyên dụng để quan sát hiện tượng nhật thực.","audioKind":"ex"},{"en":"Investment in solar energy can reduce dependence on fossil fuels and create jobs in rural communities.","vi":"Đầu tư vào năng lượng mặt trời có thể giảm sự phụ thuộc vào nhiên liệu hóa thạch và tạo ra việc làm cho các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"solar energy","vi":"năng lượng mặt trời"},{"en":"solar panels","vi":"tấm pin mặt trời"},{"en":"the solar system","vi":"hệ thống mặt trời"},{"en":"a solar eclipse","vi":"nhật thực"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"solar là tính từ, thường dùng trong các cụm từ liên quan đến mặt trời hoặc năng lượng mặt trời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_universe', 'en-b1-45', 'universe', '/ˈjuːnɪvɝːs/', 'B1', 'vũ trụ; toàn bộ không gian và mọi thứ tồn tại trong đó; thế giới trải nghiệm; hệ thống tư tưởng hoặc sự kiện tưởng tượng', 'n.', 'universal (adj.), universally (adv.)', 'Đồng nghĩa: cosmos', 'Chỉ vũ trụ thường dùng the universe; mở đầu bằng âm phụ huynh /j/.', 'We watched a film about stars and the universe.', NULL, 'Chúng tôi đã xem một bộ phim về các vì sao và vũ trụ.', '{"wordId":"universe","ukIpa":"/ˈjuːnɪvɜːs/","usIpa":"/ˈjuːnɪvɝːs/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"All space and everything that exists within it","vi":"vũ trụ; toàn bộ không gian và mọi thứ tồn tại trong đó"},{"pos":"n.","en":"A complete world of experiences, ideas, or imagined events","vi":"thế giới trải nghiệm; hệ thống tư tưởng hoặc sự kiện tưởng tượng"}],"examples":[{"en":"We watched a film about stars and the universe.","vi":"Chúng tôi đã xem một bộ phim về các vì sao và vũ trụ.","audioKind":"ex"},{"en":"Research into the origins of the universe has driven advances in telescope technology and data analysis.","vi":"Nghiên cứu về nguồn gốc của vũ trụ đã thúc đẩy sự tiến bộ trong công nghệ kính viễn vọng và phân tích dữ liệu.","audioKind":"ex2"}],"collocations":[{"en":"the expanding universe","vi":"vũ trụ đang mở rộng"},{"en":"the origins of the universe","vi":"nguồn gốc của vũ trụ"},{"en":"a parallel universe","vi":"vũ trụ song song"},{"en":"the observable universe","vi":"vũ trụ khả quan"}],"wordFamily":["universal (adj.)","universally (adv.)"],"synonyms":["cosmos"],"antonyms":[],"tipVi":"Chỉ vũ trụ thường dùng the universe; mở đầu bằng âm phụ huynh /j/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_research', 'en-b1-45', 'research', '/ˈriːsɝːtʃ/', 'B1', 'nghiên cứu; sự khảo sát; điều tra kỹ lưỡng', 'n.', 'researcher (n.)', 'Đồng nghĩa: investigation, study', 'Danh từ research thường không đếm được; nói a study, không nói a research.', 'I did some research before choosing my new bicycle.', NULL, 'Tôi đã tìm hiểu kỹ lưỡng trước khi chọn chiếc xe đạp mới của mình.', '{"wordId":"research","ukIpa":"/rɪˈsɜːtʃ/","usIpa":"/ˈriːsɝːtʃ/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"Careful study aimed at discovering facts or developing knowledge.","vi":"nghiên cứu; sự khảo sát"},{"pos":"v.","en":"To study a subject carefully to discover information.","vi":"nghiên cứu; điều tra kỹ lưỡng"}],"examples":[{"en":"I did some research before choosing my new bicycle.","vi":"Tôi đã tìm hiểu kỹ lưỡng trước khi chọn chiếc xe đạp mới của mình.","audioKind":"ex"},{"en":"Research into renewable energy can help governments develop cleaner and more reliable sources of electricity.","vi":"Nghiên cứu về năng lượng tái tạo có thể giúp các chính phủ phát triển các nguồn điện sạch hơn và đáng tin cậy hơn.","audioKind":"ex2"}],"collocations":[{"en":"conduct research","vi":"tiến hành nghiên cứu"},{"en":"research into","vi":"nghiên cứu về"},{"en":"research findings","vi":"kết quả nghiên cứu"},{"en":"scientific research","vi":"nghiên cứu khoa học"}],"wordFamily":["researcher (n.)"],"synonyms":["investigation","study"],"antonyms":[],"tipVi":"Danh từ research thường không đếm được; nói a study, không nói a research.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_astronaut', 'en-b1-45', 'astronaut', '/ˈæstrənɔːt/', 'B1', 'nhà du hành vũ trụ; phi hành gia', 'n.', 'astronautics (n.)', NULL, 'astronaut chỉ nhà du hành vũ trụ; astronomer chỉ nhà thiên văn học.', 'The astronaut floated gently through the small space station.', NULL, 'Nhà du hành vũ trụ bay lơ lửng nhẹ nhàng qua trạm không gian nhỏ.', '{"wordId":"astronaut","ukIpa":"/ˈæstrənɔːt/","usIpa":"/ˈæstrənɔːt/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"a person trained to travel and work in space","vi":"nhà du hành vũ trụ; phi hành gia"}],"examples":[{"en":"The astronaut floated gently through the small space station.","vi":"Nhà du hành vũ trụ bay lơ lửng nhẹ nhàng qua trạm không gian nhỏ.","audioKind":"ex"},{"en":"Astronauts conduct experiments in space that help scientists understand how the human body responds to weightlessness.","vi":"Các nhà du hành vũ trụ thực hiện các thí nghiệm trong không gian giúp các nhà khoa học hiểu được cơ thể con người phản ứng thế nào với tình trạng không trọng lực.","audioKind":"ex2"}],"collocations":[{"en":"astronaut training","vi":"quá trình huấn luyện phi hành gia"},{"en":"a team of astronauts","vi":"một nhóm phi hành gia"},{"en":"astronaut crew","vi":"đội ngũ phi hành gia"}],"wordFamily":["astronautics (n.)"],"synonyms":[],"antonyms":[],"tipVi":"astronaut chỉ nhà du hành vũ trụ; astronomer chỉ nhà thiên văn học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fahrenheit', 'en-b1-45', 'Fahrenheit', '/ˈfærənhaɪt/', 'B1', 'thuộc hệ đo nhiệt độ Fahrenheit; thang đo nhiệt độ Fahrenheit', 'adj.', NULL, NULL, 'Chỉ Fahrenheit, không phải nhiệt độ kế; chữ cái đầu tiên luôn được viết hoa.', 'The recipe says to bake at three hundred degrees Fahrenheit.', NULL, 'Công thức nấu ăn yêu cầu nướng ở nhiệt độ ba trăm độ Fahrenheit.', '{"wordId":"fahrenheit","ukIpa":"/ˈfærənhaɪt/","usIpa":"/ˈfærənhaɪt/","cefr":"B1","topic":"science","senses":[{"pos":"adj.","en":"Using a temperature scale where water freezes at thirty-two degrees","vi":"thuộc hệ đo nhiệt độ Fahrenheit"},{"pos":"n.","en":"The temperature scale with water boiling at two hundred twelve degrees","vi":"thang đo nhiệt độ Fahrenheit"}],"examples":[{"en":"The recipe says to bake at three hundred degrees Fahrenheit.","vi":"Công thức nấu ăn yêu cầu nướng ở nhiệt độ ba trăm độ Fahrenheit.","audioKind":"ex"},{"en":"International weather reports may provide temperatures in both Fahrenheit and Celsius to serve different audiences.","vi":"Các bản tin thời tiết quốc tế có thể cung cấp nhiệt độ bằng cả độ Fahrenheit và độ Celsius để phục vụ các đối tượng khán giả khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"degrees Fahrenheit","vi":"độ Fahrenheit"},{"en":"Fahrenheit scale","vi":"thang đo Fahrenheit"},{"en":"convert Fahrenheit to Celsius","vi":"đổi từ độ Fahrenheit sang độ Celsius"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ Fahrenheit, không phải nhiệt độ kế; chữ cái đầu tiên luôn được viết hoa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_approximately', 'en-b1-45', 'approximately', '/əˈprɑːksɪmətli/', 'B1', 'khoảng; xấp xỉ', 'adv.', 'approximate (adj.), approximate (v.), approximation (n.)', 'Đồng nghĩa: about, roughly, around · Trái nghĩa: exactly', 'Thường đặt trước số lượng, mang sắc thái trang trọng hơn từ about.', 'The walk to the lake takes approximately twenty minutes.', NULL, 'Đi bộ ra hồ mất khoảng hai mươi phút.', '{"wordId":"approximately","ukIpa":"/əˈprɒksɪmətli/","usIpa":"/əˈprɑːksɪmətli/","cefr":"B1","topic":"science","senses":[{"pos":"adv.","en":"Close to a particular amount, but not exactly.","vi":"khoảng; xấp xỉ"}],"examples":[{"en":"The walk to the lake takes approximately twenty minutes.","vi":"Đi bộ ra hồ mất khoảng hai mươi phút.","audioKind":"ex"},{"en":"Approximately half of the households surveyed reported using public transport at least once a week.","vi":"Khoảng một nửa số hộ gia đình được khảo sát cho biết họ sử dụng phương tiện giao thông công cộng ít nhất một lần một tuần.","audioKind":"ex2"}],"collocations":[{"en":"approximately equal","vi":"xấp xỉ bằng"},{"en":"approximately half","vi":"khoảng một nửa"},{"en":"approximately double","vi":"khoảng gấp đôi"}],"wordFamily":["approximate (adj.)","approximate (v.)","approximation (n.)"],"synonyms":["about","roughly","around"],"antonyms":["exactly"],"tipVi":"Thường đặt trước số lượng, mang sắc thái trang trọng hơn từ about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_explode', 'en-b1-45', 'explode', '/ɪkˈsploʊd/', 'B1', 'nổ tung; làm nổ tung; tăng vọt; bùng nổ; bộc phát; bùng nổ cảm xúc', 'v.', 'explosion (n.), explosive (adj.), explosively (adv.)', 'Đồng nghĩa: burst, detonate', 'Các vật thể có khả năng phát nổ thường đóng vai trò chủ ngữ ở thể chủ động, không cần dùng thể bị động.', 'We watched colourful fireworks explode above the lake.', NULL, 'Chúng tôi ngắm nhìn những chùm pháo hoa rực rỡ nổ tung trên mặt hồ.', '{"wordId":"explode","ukIpa":"/ɪkˈspləʊd/","usIpa":"/ɪkˈsploʊd/","cefr":"B1","topic":"science","senses":[{"pos":"v.","en":"To burst violently, or cause something to burst violently.","vi":"nổ tung; làm nổ tung"},{"pos":"v.","en":"To increase extremely quickly in size, amount, or popularity.","vi":"tăng vọt; bùng nổ"},{"pos":"v.","en":"To express strong feelings suddenly and forcefully.","vi":"bộc phát; bùng nổ cảm xúc"}],"examples":[{"en":"We watched colourful fireworks explode above the lake.","vi":"Chúng tôi ngắm nhìn những chùm pháo hoa rực rỡ nổ tung trên mặt hồ.","audioKind":"ex"},{"en":"Demand for online courses has exploded as more adults seek flexible opportunities to develop new skills.","vi":"Nhu cầu về các khóa học trực tuyến đã bùng nổ khi ngày càng có nhiều người trưởng thành tìm kiếm cơ hội linh hoạt để phát triển các kỹ năng mới.","audioKind":"ex2"}],"collocations":[{"en":"explode into flames","vi":"bùng cháy dữ dội"},{"en":"explode with anger","vi":"nổi giận đùng đùng"},{"en":"demand explodes","vi":"nhu cầu tăng vọt"},{"en":"a firework explodes","vi":"pháo hoa nổ tung"}],"wordFamily":["explosion (n.)","explosive (adj.)","explosively (adv.)"],"synonyms":["burst","detonate"],"antonyms":[],"tipVi":"Các vật thể có khả năng phát nổ thường đóng vai trò chủ ngữ ở thể chủ động, không cần dùng thể bị động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chemical', 'en-b1-45', 'chemical', '/ˈkemɪkəl/', 'B1', 'hóa chất; chất hóa học; thuộc về hóa học', 'n.', 'chemistry (n.), chemist (n.), chemically (adv.)', NULL, 'Danh từ ''chemical'' là danh từ đếm được; các chất hóa học không phải lúc nào cũng có hại.', 'Keep cleaning chemicals safely out of children''s reach.', NULL, 'Hãy cất giữ các hóa chất tẩy rửa an toàn, tránh xa tầm tay trẻ em.', '{"wordId":"chemical","ukIpa":"/ˈkemɪkəl/","usIpa":"/ˈkemɪkəl/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"A substance produced or used in a chemical process.","vi":"hóa chất; chất hóa học"},{"pos":"adj.","en":"Relating to substances and how they combine or change.","vi":"thuộc về hóa học"}],"examples":[{"en":"Keep cleaning chemicals safely out of children''s reach.","vi":"Hãy cất giữ các hóa chất tẩy rửa an toàn, tránh xa tầm tay trẻ em.","audioKind":"ex"},{"en":"Farmers can protect nearby rivers by reducing the amount of agricultural chemicals used on their land.","vi":"Nông dân có thể bảo vệ các dòng sông gần đó bằng cách giảm lượng hóa chất nông nghiệp sử dụng trên đồng ruộng của họ.","audioKind":"ex2"}],"collocations":[{"en":"a chemical reaction","vi":"phản ứng hóa học"},{"en":"harmful chemicals","vi":"hóa chất độc hại"},{"en":"the chemical industry","vi":"ngành công nghiệp hóa chất"},{"en":"chemical waste","vi":"chất thải hóa học"}],"wordFamily":["chemistry (n.)","chemist (n.)","chemically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ ''chemical'' là danh từ đếm được; các chất hóa học không phải lúc nào cũng có hại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_predict', 'en-b1-45', 'predict', '/prɪˈdɪkt/', 'B1', 'dự đoán; dự báo', 'v.', 'prediction (n.), predictable (adj.), unpredictable (adj.), predictive (adj.)', 'Đồng nghĩa: forecast, foresee', 'Có thể dùng với mệnh đề that; không nhầm lẫn với prevent (ngăn ngừa).', 'They predict heavy rain, so take your umbrella.', NULL, 'Họ dự báo trời sẽ mưa lớn, nên hãy mang theo ô nhé.', '{"wordId":"predict","ukIpa":"/prɪˈdɪkt/","usIpa":"/prɪˈdɪkt/","cefr":"B1","topic":"science","senses":[{"pos":"v.","en":"To say what will happen, often using evidence.","vi":"dự đoán; dự báo"}],"examples":[{"en":"They predict heavy rain, so take your umbrella.","vi":"Họ dự báo trời sẽ mưa lớn, nên hãy mang theo ô nhé.","audioKind":"ex"},{"en":"Climate models help scientists predict how rising temperatures may affect agricultural production in different regions.","vi":"Các mô hình khí hậu giúp các khoa học gia dự đoán nhiệt độ tăng cao có thể tác động ra sao đến sản xuất nông nghiệp ở các vùng miền khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"predict the outcome","vi":"dự đoán kết quả"},{"en":"accurately predict","vi":"dự đoán chính xác"},{"en":"difficult to predict","vi":"khó dự đoán"}],"wordFamily":["prediction (n.)","predictable (adj.)","unpredictable (adj.)","predictive (adj.)"],"synonyms":["forecast","foresee"],"antonyms":[],"tipVi":"Có thể dùng với mệnh đề that; không nhầm lẫn với prevent (ngăn ngừa).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cell', 'en-b1-45', 'cell', '/sel/', 'B1', 'tế bào; phòng giam; buồng giam; pin; bộ pin', 'n.', 'cellular (adj.), unicellular (adj.), multicellular (adj.)', NULL, 'Trong ngữ cảnh sinh học thường chỉ tế bào; ''prison cell'' chỉ phòng giam trong tù.', 'Under the microscope, each onion cell looked like a rectangle.', NULL, 'Dưới kính hiển vi, mỗi tế bào hành trông giống như một hình chữ nhật.', '{"wordId":"cell","ukIpa":"/sel/","usIpa":"/sel/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"the smallest living unit of an organism","vi":"tế bào"},{"pos":"n.","en":"a small room, especially one in a prison","vi":"phòng giam; buồng giam"},{"pos":"n.","en":"a unit that produces electricity through chemical reactions","vi":"pin; bộ pin"}],"examples":[{"en":"Under the microscope, each onion cell looked like a rectangle.","vi":"Dưới kính hiển vi, mỗi tế bào hành trông giống như một hình chữ nhật.","audioKind":"ex"},{"en":"Scientists study how damaged cells repair themselves to develop more effective treatments for disease.","vi":"Các nhà khoa học nghiên cứu cách các tế bào bị tổn thương tự sửa chữa để phát triển các phương pháp điều trị bệnh hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"blood cells","vi":"tế bào máu"},{"en":"stem cells","vi":"tế bào gốc"},{"en":"a prison cell","vi":"phòng giam"},{"en":"a fuel cell","vi":"pin nhiên liệu"}],"wordFamily":["cellular (adj.)","unicellular (adj.)","multicellular (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong ngữ cảnh sinh học thường chỉ tế bào; ''prison cell'' chỉ phòng giam trong tù.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spaceship', 'en-b1-45', 'spaceship', '/ˈspeɪsʃɪp/', 'B1', 'tàu vũ trụ', 'n.', 'space (n.), spaceflight (n.)', 'Đồng nghĩa: spacecraft', 'spaceship là danh từ đếm được; spacecraft có dạng số ít và số nhiều giống nhau.', 'The children built a spaceship from cardboard boxes.', NULL, 'Bọn trẻ đã tự làm một con tàu vũ trụ bằng các thùng các-tông.', '{"wordId":"spaceship","ukIpa":"/ˈspeɪsʃɪp/","usIpa":"/ˈspeɪsʃɪp/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"A vehicle designed to travel through space.","vi":"tàu vũ trụ"}],"examples":[{"en":"The children built a spaceship from cardboard boxes.","vi":"Bọn trẻ đã tự làm một con tàu vũ trụ bằng các thùng các-tông.","audioKind":"ex"},{"en":"Designing a spaceship for long journeys requires careful planning to protect astronauts from radiation and isolation.","vi":"Thiết kế tàu vũ trụ cho các chuyến đi dài ngày đòi hỏi sự lập kế hoạch kỹ lưỡng để bảo vệ các phi hành gia khỏi bức xạ và sự cô lập.","audioKind":"ex2"}],"collocations":[{"en":"board a spaceship","vi":"lên tàu vũ trụ"},{"en":"launch a spaceship","vi":"phóng tàu vũ trụ"},{"en":"aboard a spaceship","vi":"trên tàu vũ trụ"}],"wordFamily":["space (n.)","spaceflight (n.)"],"synonyms":["spacecraft"],"antonyms":[],"tipVi":"spaceship là danh từ đếm được; spacecraft có dạng số ít và số nhiều giống nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_solid', 'en-b1-45', 'solid', '/ˈsɑːlɪd/', 'B1', 'rắn, có hình dạng cố định chứ không phải lỏng hay khí; vững chắc, đáng tin cậy hoặc dựa trên bằng chứng xác thực; chất giữ nguyên hình dạng thay vì chảy lỏng', 'adj.', 'solidify (v.), solidification (n.), solidity (n.), solidly (adv.)', NULL, 'solid khi đóng vai trò danh từ có nghĩa là chất rắn; solid evidence có nghĩa là bằng chứng đáng tin cậy.', 'The lake froze solid during the bitterly cold night.', NULL, 'Hồ nước đã đóng băng hoàn toàn trong đêm giá rét.', '{"wordId":"solid","ukIpa":"/ˈsɒlɪd/","usIpa":"/ˈsɑːlɪd/","cefr":"B1","topic":"science","senses":[{"pos":"adj.","en":"having a firm shape rather than being liquid or gas","vi":"rắn, có hình dạng cố định chứ không phải lỏng hay khí"},{"pos":"adj.","en":"strong, dependable, or based on good evidence","vi":"vững chắc, đáng tin cậy hoặc dựa trên bằng chứng xác thực"},{"pos":"n.","en":"a substance that keeps its shape rather than flowing","vi":"chất giữ nguyên hình dạng thay vì chảy lỏng"}],"examples":[{"en":"The lake froze solid during the bitterly cold night.","vi":"Hồ nước đã đóng băng hoàn toàn trong đêm giá rét.","audioKind":"ex"},{"en":"Governments need solid evidence before introducing policies that could significantly affect public health and household spending.","vi":"Chính phủ cần có những bằng chứng vững chắc trước khi ban hành các chính sách có thể tác động đáng kể đến y tế công cộng và chi tiêu hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"solid evidence","vi":"bằng chứng xác thực"},{"en":"solid foundation","vi":"nền tảng vững chắc"},{"en":"solid waste","vi":"chất thải rắn"},{"en":"solid wood","vi":"gỗ đặc"}],"wordFamily":["solidify (v.)","solidification (n.)","solidity (n.)","solidly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"solid khi đóng vai trò danh từ có nghĩa là chất rắn; solid evidence có nghĩa là bằng chứng đáng tin cậy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scientific', 'en-b1-45', 'scientific', '/ˌsaɪənˈtɪfɪk/', 'B1', 'thuộc về khoa học; có tính khoa học', 'adj.', 'science (n.), scientist (n.), scientifically (adv.)', 'Trái nghĩa: unscientific', '"scientific" nhấn mạnh vào cơ sở khoa học, không đồng nghĩa với việc chỉ có tính hệ thống hay ngăn nắp.', 'Our class used scientific methods to test the water.', NULL, 'Lớp chúng tôi đã sử dụng các phương pháp khoa học để kiểm tra nguồn nước.', '{"wordId":"scientific","ukIpa":"/ˌsaɪənˈtɪfɪk/","usIpa":"/ˌsaɪənˈtɪfɪk/","cefr":"B1","topic":"science","senses":[{"pos":"adj.","en":"relating to science or using methods based on evidence","vi":"thuộc về khoa học; có tính khoa học"}],"examples":[{"en":"Our class used scientific methods to test the water.","vi":"Lớp chúng tôi đã sử dụng các phương pháp khoa học để kiểm tra nguồn nước.","audioKind":"ex"},{"en":"Governments should rely on scientific evidence when developing policies to protect public health.","vi":"Chính phủ nên dựa vào bằng chứng khoa học khi xây dựng các chính sách bảo vệ sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"scientific research","vi":"nghiên cứu khoa học"},{"en":"scientific evidence","vi":"bằng chứng khoa học"},{"en":"scientific method","vi":"phương pháp khoa học"}],"wordFamily":["science (n.)","scientist (n.)","scientifically (adv.)"],"synonyms":[],"antonyms":["unscientific"],"tipVi":"\"scientific\" nhấn mạnh vào cơ sở khoa học, không đồng nghĩa với việc chỉ có tính hệ thống hay ngăn nắp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_researcher', 'en-b1-45', 'researcher', '/rɪˈsɜːrtʃər/', 'B1', 'nhà nghiên cứu; nghiên cứu viên', 'n.', 'research (n.), research (v.)', 'Đồng nghĩa: investigator', 'researcher là danh từ đếm được; research đóng vai trò danh từ thường không đếm được.', 'The researcher carefully examined the leaf under a microscope.', NULL, 'Nhà nghiên cứu đã cẩn thận kiểm tra chiếc lá dưới kính hiển vi.', '{"wordId":"researcher","ukIpa":"/rɪˈsɜːtʃə/","usIpa":"/rɪˈsɜːrtʃər/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"Someone who studies a subject carefully to discover new information.","vi":"nhà nghiên cứu; nghiên cứu viên"}],"examples":[{"en":"The researcher carefully examined the leaf under a microscope.","vi":"Nhà nghiên cứu đã cẩn thận kiểm tra chiếc lá dưới kính hiển vi.","audioKind":"ex"},{"en":"Researchers are investigating how access to green spaces influences the mental health of urban residents.","vi":"Các nhà nghiên cứu đang điều tra xem việc tiếp cận không gian xanh ảnh hưởng như thế nào đến sức khỏe tinh thần của cư dân đô thị.","audioKind":"ex2"}],"collocations":[{"en":"medical researcher","vi":"nhà nghiên cứu y học"},{"en":"lead researcher","vi":"trưởng nhóm nghiên cứu"},{"en":"a team of researchers","vi":"một nhóm các nhà nghiên cứu"}],"wordFamily":["research (n.)","research (v.)"],"synonyms":["investigator"],"antonyms":[],"tipVi":"researcher là danh từ đếm được; research đóng vai trò danh từ thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exist', 'en-b1-45', 'exist', '/ɪɡˈzɪst/', 'B1', 'tồn tại; có thật; sinh sống; xoay xở kiếm sống', 'v.', 'existence (n.), existing (adj.), existent (adj.)', NULL, 'Là nội động từ nên không dùng thể bị động; cấu trúc "không tồn tại" dùng does not exist.', 'Do you think creatures like these really exist?', NULL, 'Bạn có nghĩ rằng những sinh vật thế này thực sự tồn tại không?', '{"wordId":"exist","ukIpa":"/ɪɡˈzɪst/","usIpa":"/ɪɡˈzɪst/","cefr":"B1","topic":"science","senses":[{"pos":"v.","en":"To be real or present in the world.","vi":"tồn tại; có thật"},{"pos":"v.","en":"To stay alive, especially with very limited resources.","vi":"sinh sống; xoay xở kiếm sống"}],"examples":[{"en":"Do you think creatures like these really exist?","vi":"Bạn có nghĩ rằng những sinh vật thế này thực sự tồn tại không?","audioKind":"ex"},{"en":"Significant differences in access to healthcare still exist between rural communities and major urban centres.","vi":"Sự khác biệt đáng kể trong việc tiếp cận dịch vụ y tế vẫn tồn tại giữa các cộng đồng nông thôn và các trung tâm đô thị lớn.","audioKind":"ex2"}],"collocations":[{"en":"already exist","vi":"đã tồn tại sẵn"},{"en":"continue to exist","vi":"tiếp tục tồn tại"},{"en":"exist in nature","vi":"tồn tại trong tự nhiên"},{"en":"exist on limited resources","vi":"sống bằng nguồn tài nguyên hạn hẹp"}],"wordFamily":["existence (n.)","existing (adj.)","existent (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là nội động từ nên không dùng thể bị động; cấu trúc \"không tồn tại\" dùng does not exist.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_laboratory', 'en-b1-45', 'laboratory', '/ˈlæbrətɔːri/', 'B1', 'phòng thí nghiệm; phòng nghiên cứu', 'n.', NULL, 'Đồng nghĩa: lab', 'thường viết tắt là lab; trọng âm phát sinh sự khác biệt giữa tiếng Anh-Anh và Anh-Mỹ.', 'We wore safety glasses inside the school laboratory.', NULL, 'Chúng tôi đã đeo kính bảo hộ bên trong phòng thí nghiệm của trường.', '{"wordId":"laboratory","ukIpa":"/ləˈbɒrətri/","usIpa":"/ˈlæbrətɔːri/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"a room or building equipped for scientific work","vi":"phòng thí nghiệm; phòng nghiên cứu"}],"examples":[{"en":"We wore safety glasses inside the school laboratory.","vi":"Chúng tôi đã đeo kính bảo hộ bên trong phòng thí nghiệm của trường.","audioKind":"ex"},{"en":"Investment in laboratory equipment enables university students to develop practical skills and conduct reliable experiments.","vi":"Việc đầu tư vào trang thiết bị phòng thí nghiệm giúp sinh viên đại học phát triển các kỹ năng thực hành và tiến hành các thí nghiệm đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"laboratory equipment","vi":"thiết bị phòng thí nghiệm"},{"en":"laboratory tests","vi":"xét nghiệm trong phòng thí nghiệm"},{"en":"research laboratory","vi":"phòng nghiên cứu khoa học"}],"wordFamily":[],"synonyms":["lab"],"antonyms":[],"tipVi":"thường viết tắt là lab; trọng âm phát sinh sự khác biệt giữa tiếng Anh-Anh và Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_millimetre', 'en-b1-45', 'millimetre', '/ˈmɪləmiːtər/', 'B1', 'mi-li-mét', 'n.', NULL, NULL, 'Viết tắt là "mm"; cách viết theo tiếng Anh-Mỹ là "millimeter"; một xăng-ti-mét bằng mười mi-li-mét.', 'The shelf was just a millimetre too wide to fit.', NULL, 'Cái kệ chỉ rộng hơn một mi-li-mét nên không thể lắp vừa.', '{"wordId":"millimetre","ukIpa":"/ˈmɪlɪmiːtə/","usIpa":"/ˈmɪləmiːtər/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"A unit of length equal to one thousandth of a metre","vi":"mi-li-mét"}],"examples":[{"en":"The shelf was just a millimetre too wide to fit.","vi":"Cái kệ chỉ rộng hơn một mi-li-mét nên không thể lắp vừa.","audioKind":"ex"},{"en":"Even a few millimetres of sea level rise can increase flood risks for vulnerable coastal communities over time.","vi":"Ngay cả khi mực nước biển dâng lên chỉ vài mi-li-mét cũng có thể làm gia tăng nguy cơ lũ lụt đối với các cộng đồng ven biển dễ bị tổn thương theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"a millimetre thick","vi":"dày một mi-li-mét"},{"en":"a few millimetres","vi":"vài mi-li-mét"},{"en":"measured in millimetres","vi":"được đo bằng mi-li-mét"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Viết tắt là \"mm\"; cách viết theo tiếng Anh-Mỹ là \"millimeter\"; một xăng-ti-mét bằng mười mi-li-mét.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_45_1', 'en-b1-45', 'Cách dùng “solid” (adj.) — rắn, có hình dạng cố định chứ không phải lỏng hay khí', 'solid evidence  ·  solid foundation  ·  solid waste', 'solid khi đóng vai trò danh từ có nghĩa là chất rắn; solid evidence có nghĩa là bằng chứng đáng tin cậy.', 'Họ từ (Word Family): solidify (v.), solidification (n.), solidity (n.), solidly (adv.)', '[{"hanzi":"The lake froze solid during the bitterly cold night.","pinyin":"","meaning":"Hồ nước đã đóng băng hoàn toàn trong đêm giá rét."},{"hanzi":"Governments need solid evidence before introducing policies that could significantly affect public health and household spending.","pinyin":"","meaning":"Chính phủ cần có những bằng chứng vững chắc trước khi ban hành các chính sách có thể tác động đáng kể đến y tế công cộng và chi tiêu hộ gia đình."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_45_2', 'en-b1-45', 'Cách dùng “explode” (v.) — nổ tung; làm nổ tung', 'explode into flames  ·  explode with anger  ·  demand explodes', 'Các vật thể có khả năng phát nổ thường đóng vai trò chủ ngữ ở thể chủ động, không cần dùng thể bị động.', 'Họ từ (Word Family): explosion (n.), explosive (adj.), explosively (adv.) | Đồng nghĩa: burst, detonate', '[{"hanzi":"We watched colourful fireworks explode above the lake.","pinyin":"","meaning":"Chúng tôi ngắm nhìn những chùm pháo hoa rực rỡ nổ tung trên mặt hồ."},{"hanzi":"Demand for online courses has exploded as more adults seek flexible opportunities to develop new skills.","pinyin":"","meaning":"Nhu cầu về các khóa học trực tuyến đã bùng nổ khi ngày càng có nhiều người trưởng thành tìm kiếm cơ hội linh hoạt để phát triển các kỹ năng mới."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_45_3', 'en-b1-45', 'Cách dùng “scientific” (adj.) — thuộc về khoa học; có tính khoa học', 'scientific research  ·  scientific evidence  ·  scientific method', '"scientific" nhấn mạnh vào cơ sở khoa học, không đồng nghĩa với việc chỉ có tính hệ thống hay ngăn nắp.', 'Họ từ (Word Family): science (n.), scientist (n.), scientifically (adv.) | Trái nghĩa: unscientific', '[{"hanzi":"Our class used scientific methods to test the water.","pinyin":"","meaning":"Lớp chúng tôi đã sử dụng các phương pháp khoa học để kiểm tra nguồn nước."},{"hanzi":"Governments should rely on scientific evidence when developing policies to protect public health.","pinyin":"","meaning":"Chính phủ nên dựa vào bằng chứng khoa học khi xây dựng các chính sách bảo vệ sức khỏe cộng đồng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_45_4', 'en-b1-45', 'Cách dùng “measure” (v.) — đo lường; đánh giá', 'measure progress  ·  take measures to do something  ·  a measure of success', 'Cụm từ "take measures" nghĩa là thực hiện biện pháp; khi đo đạc vật gì có thể làm tân ngữ trực tiếp.', 'Họ từ (Word Family): measurement (n.), measurable (adj.)', '[{"hanzi":"We measured the window before buying new curtains.","pinyin":"","meaning":"Chúng tôi đã đo kích thước cửa sổ trước khi mua rèm mới."},{"hanzi":"Governments should introduce effective measures to reduce air pollution without placing excessive costs on low-income households.","pinyin":"","meaning":"Chính phủ nên đưa ra các biện pháp hiệu quả nhằm giảm ô nhiễm không khí mà không tạo ra gánh nặng chi phí quá mức cho các hộ gia đình thu nhập thấp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_45_1', 'en-b1-45', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
