INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_45_1_2', 'ten_b1_45_1', 'solar', 'We wore special protective glasses to watch the solar eclipse.', 'We wore special protective glasses to watch the solar eclipse.', '/ˈsoʊlər/', 'Chúng tôi đã đeo kính bảo vệ chuyên dụng để quan sát hiện tượng nhật thực.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_45_1_3', 'ten_b1_45_1', 'universe', 'We watched a film about stars and the universe.', 'We watched a film about stars and the universe.', '/ˈjuːnɪvɝːs/', 'Chúng tôi đã xem một bộ phim về các vì sao và vũ trụ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_45_1_4', 'ten_b1_45_1', 'research', 'I did some research before choosing my new bicycle.', 'I did some research before choosing my new bicycle.', '/ˈriːsɝːtʃ/', 'Tôi đã tìm hiểu kỹ lưỡng trước khi chọn chiếc xe đạp mới của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_45_1_5', 'ten_b1_45_1', 'astronaut', 'The astronaut floated gently through the small space station.', 'The astronaut floated gently through the small space station.', '/ˈæstrənɔːt/', 'Nhà du hành vũ trụ bay lơ lửng nhẹ nhàng qua trạm không gian nhỏ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_45_1_6', 'ten_b1_45_1', 'Fahrenheit', 'The recipe says to bake at three hundred degrees Fahrenheit.', 'The recipe says to bake at three hundred degrees Fahrenheit.', '/ˈfærənhaɪt/', 'Công thức nấu ăn yêu cầu nướng ở nhiệt độ ba trăm độ Fahrenheit.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_45_1_7', 'ten_b1_45_1', 'approximately', 'The walk to the lake takes approximately twenty minutes.', 'The walk to the lake takes approximately twenty minutes.', '/əˈprɑːksɪmətli/', 'Đi bộ ra hồ mất khoảng hai mươi phút.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_45_1_8', 'ten_b1_45_1', 'explode', 'We watched colourful fireworks explode above the lake.', 'We watched colourful fireworks explode above the lake.', '/ɪkˈsploʊd/', 'Chúng tôi ngắm nhìn những chùm pháo hoa rực rỡ nổ tung trên mặt hồ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_45_1_1', 'en-b1-45', 'ten_b1_45_1', 'listening', 'listening', 'We measured the window before buying new curtains.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Họ dự báo trời sẽ mưa lớn, nên hãy mang theo ô nhé.","Chúng tôi đã đo kích thước cửa sổ trước khi mua rèm mới.","Hồ nước đã đóng băng hoàn toàn trong đêm giá rét.","Chúng tôi đã đeo kính bảo vệ chuyên dụng để quan sát hiện tượng nhật thực."]'::jsonb, 1, 'We measured the window before buying new curtains. → Chúng tôi đã đo kích thước cửa sổ trước khi mua rèm mới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_45_1_2', 'en-b1-45', 'ten_b1_45_1', 'listening', 'listening', 'We wore special protective glasses to watch the solar eclipse.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Lớp chúng tôi đã sử dụng các phương pháp khoa học để kiểm tra nguồn nước.","Chúng tôi đã đeo kính bảo vệ chuyên dụng để quan sát hiện tượng nhật thực.","Đi bộ ra hồ mất khoảng hai mươi phút.","Hồ nước đã đóng băng hoàn toàn trong đêm giá rét."]'::jsonb, 1, 'We wore special protective glasses to watch the solar eclipse. → Chúng tôi đã đeo kính bảo vệ chuyên dụng để quan sát hiện tượng nhật thực.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_45_1_3', 'en-b1-45', 'ten_b1_45_1', 'listening', 'listening', 'We watched a film about stars and the universe.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đi bộ ra hồ mất khoảng hai mươi phút.","Chúng tôi đã xem một bộ phim về các vì sao và vũ trụ.","Bạn có nghĩ rằng những sinh vật thế này thực sự tồn tại không?","Công thức nấu ăn yêu cầu nướng ở nhiệt độ ba trăm độ Fahrenheit."]'::jsonb, 1, 'We watched a film about stars and the universe. → Chúng tôi đã xem một bộ phim về các vì sao và vũ trụ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_45_2', 'en-b1-45', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_45_2_1', 'ten_b1_45_2', 'measure', 'Governments should introduce effective measures to reduce air pollution without placing excessive costs on low-income households.', 'Governments should introduce effective measures to reduce air pollution without placing excessive costs on low-income households.', '/ˈmeʒər/', 'Chính phủ nên đưa ra các biện pháp hiệu quả nhằm giảm ô nhiễm không khí mà không tạo ra gánh nặng chi phí quá mức cho các hộ gia đình thu nhập thấp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_45_2_2', 'ten_b1_45_2', 'solar', 'Investment in solar energy can reduce dependence on fossil fuels and create jobs in rural communities.', 'Investment in solar energy can reduce dependence on fossil fuels and create jobs in rural communities.', '/ˈsoʊlər/', 'Đầu tư vào năng lượng mặt trời có thể giảm sự phụ thuộc vào nhiên liệu hóa thạch và tạo ra việc làm cho các cộng đồng nông thôn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_45_2_3', 'ten_b1_45_2', 'universe', 'Research into the origins of the universe has driven advances in telescope technology and data analysis.', 'Research into the origins of the universe has driven advances in telescope technology and data analysis.', '/ˈjuːnɪvɝːs/', 'Nghiên cứu về nguồn gốc của vũ trụ đã thúc đẩy sự tiến bộ trong công nghệ kính viễn vọng và phân tích dữ liệu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_45_2_4', 'ten_b1_45_2', 'research', 'Research into renewable energy can help governments develop cleaner and more reliable sources of electricity.', 'Research into renewable energy can help governments develop cleaner and more reliable sources of electricity.', '/ˈriːsɝːtʃ/', 'Nghiên cứu về năng lượng tái tạo có thể giúp các chính phủ phát triển các nguồn điện sạch hơn và đáng tin cậy hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_45_2_5', 'ten_b1_45_2', 'astronaut', 'Astronauts conduct experiments in space that help scientists understand how the human body responds to weightlessness.', 'Astronauts conduct experiments in space that help scientists understand how the human body responds to weightlessness.', '/ˈæstrənɔːt/', 'Các nhà du hành vũ trụ thực hiện các thí nghiệm trong không gian giúp các nhà khoa học hiểu được cơ thể con người phản ứng thế nào với tình trạng không trọng lực.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_45_2_6', 'ten_b1_45_2', 'Fahrenheit', 'International weather reports may provide temperatures in both Fahrenheit and Celsius to serve different audiences.', 'International weather reports may provide temperatures in both Fahrenheit and Celsius to serve different audiences.', '/ˈfærənhaɪt/', 'Các bản tin thời tiết quốc tế có thể cung cấp nhiệt độ bằng cả độ Fahrenheit và độ Celsius để phục vụ các đối tượng khán giả khác nhau.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_45_2_1', 'en-b1-45', 'ten_b1_45_2', 'listening', 'listening', 'Governments should introduce effective measures to reduce air pollution without placing excessive costs on low-income households.', NULL, 'Trong câu vừa nghe, từ “measure” mang nghĩa nào sau đây?', '["vị trí; địa điểm","đo lường; đánh giá","động tác chống đẩy; hít đất","nhà khách; nhà nghỉ gia đình"]'::jsonb, 1, '“measure” (/ˈmeʒər/): đo lường; đánh giá. Câu đầy đủ: Governments should introduce effective measures to reduce air pollution without placing excessive costs on low-income households.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
