INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_2', 'en-b1-45', NULL, 'comprehensive_test', 'listening', 'We wore special protective glasses to watch the solar eclipse.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhà nghiên cứu đã cẩn thận kiểm tra chiếc lá dưới kính hiển vi.","Chúng tôi đã đeo kính bảo vệ chuyên dụng để quan sát hiện tượng nhật thực.","Hãy cất giữ các hóa chất tẩy rửa an toàn, tránh xa tầm tay trẻ em.","Hồ nước đã đóng băng hoàn toàn trong đêm giá rét."]'::jsonb, 1, 'We wore special protective glasses to watch the solar eclipse. → Chúng tôi đã đeo kính bảo vệ chuyên dụng để quan sát hiện tượng nhật thực.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
