INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_4', 'en-b1-45', NULL, 'comprehensive_test', 'listening', 'I did some research before choosing my new bicycle.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã tìm hiểu kỹ lưỡng trước khi chọn chiếc xe đạp mới của mình.","Nhà du hành vũ trụ bay lơ lửng nhẹ nhàng qua trạm không gian nhỏ.","Hồ nước đã đóng băng hoàn toàn trong đêm giá rét.","Hãy cất giữ các hóa chất tẩy rửa an toàn, tránh xa tầm tay trẻ em."]'::jsonb, 0, 'I did some research before choosing my new bicycle. → Tôi đã tìm hiểu kỹ lưỡng trước khi chọn chiếc xe đạp mới của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_5', 'en-b1-45', NULL, 'comprehensive_test', 'listening', 'astronaut', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà du hành vũ trụ; phi hành gia","hiệu quả; có năng suất cao; tiết kiệm (thời gian, năng lượng)","mô hình; quy luật","bảo hiểm"]'::jsonb, 0, 'astronaut (/ˈæstrənɔːt/) → nhà du hành vũ trụ; phi hành gia', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_6', 'en-b1-45', NULL, 'comprehensive_test', 'listening', 'The recipe says to bake at three hundred degrees Fahrenheit.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã xem một bộ phim về các vì sao và vũ trụ.","Nhà nghiên cứu đã cẩn thận kiểm tra chiếc lá dưới kính hiển vi.","Chúng tôi đã đeo kính bảo hộ bên trong phòng thí nghiệm của trường.","Công thức nấu ăn yêu cầu nướng ở nhiệt độ ba trăm độ Fahrenheit."]'::jsonb, 3, 'The recipe says to bake at three hundred degrees Fahrenheit. → Công thức nấu ăn yêu cầu nướng ở nhiệt độ ba trăm độ Fahrenheit.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_7', 'en-b1-45', NULL, 'comprehensive_test', 'listening', 'approximately', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đánh cược; cá cược","khoảng; xấp xỉ","vì vậy; do đó; cho nên","trao đổi; đổi"]'::jsonb, 1, 'approximately (/əˈprɑːksɪmətli/) → khoảng; xấp xỉ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_8', 'en-b1-45', NULL, 'comprehensive_test', 'listening', 'We watched colourful fireworks explode above the lake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi ngắm nhìn những chùm pháo hoa rực rỡ nổ tung trên mặt hồ.","Lớp chúng tôi đã sử dụng các phương pháp khoa học để kiểm tra nguồn nước.","Chúng tôi đã đeo kính bảo vệ chuyên dụng để quan sát hiện tượng nhật thực.","Đi bộ ra hồ mất khoảng hai mươi phút."]'::jsonb, 0, 'We watched colourful fireworks explode above the lake. → Chúng tôi ngắm nhìn những chùm pháo hoa rực rỡ nổ tung trên mặt hồ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_9', 'en-b1-45', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a person trained to travel and work in space”?', '["solid","explode","predict","astronaut"]'::jsonb, 3, 'astronaut (/ˈæstrənɔːt/) → nhà du hành vũ trụ; phi hành gia', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_10', 'en-b1-45', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Using a temperature scale where water freezes at thirty-two degrees”?', '["Fahrenheit","astronaut","research","universe"]'::jsonb, 0, 'Fahrenheit (/ˈfærənhaɪt/) → thuộc hệ đo nhiệt độ Fahrenheit', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_11', 'en-b1-45', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Close to a particular amount, but not exactly.”?', '["chemical","approximately","research","universe"]'::jsonb, 1, 'approximately (/əˈprɑːksɪmətli/) → khoảng; xấp xỉ', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_12', 'en-b1-45', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To burst violently, or cause something to burst violently.”?', '["cell","explode","solid","solar"]'::jsonb, 1, 'explode (/ɪkˈsploʊd/) → nổ tung; làm nổ tung', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
