INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_18', 'en-b1-45', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should introduce effective measures to reduce air pollution without placing excessive costs on low-income households.', 'Dựa vào câu trên, từ “measure” có nghĩa phù hợp nhất là gì?', '["làm bẹp dí; ép chặt vào không gian chật hẹp","đo lường; đánh giá","thông tin; hàm lượng","ánh sáng ban ngày; ban ngày"]'::jsonb, 1, 'measure: đo lường; đánh giá; biện pháp; phương án; tiêu chuẩn đánh giá. Dịch cả câu: Chính phủ nên đưa ra các biện pháp hiệu quả nhằm giảm ô nhiễm không khí mà không tạo ra gánh nặng chi phí quá mức cho các hộ gia đình thu nhập thấp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_19', 'en-b1-45', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in solar energy can reduce dependence on fossil fuels and create jobs in rural communities.', 'Dựa vào câu trên, từ “solar” có nghĩa phù hợp nhất là gì?', '["riêng lẻ; cá nhân","chứa cồn; có cồn","khích lệ; động viên","thuộc về mặt trời"]'::jsonb, 3, 'solar: thuộc về mặt trời; dùng năng lượng mặt trời. Dịch cả câu: Đầu tư vào năng lượng mặt trời có thể giảm sự phụ thuộc vào nhiên liệu hóa thạch và tạo ra việc làm cho các cộng đồng nông thôn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_20', 'en-b1-45', NULL, 'comprehensive_test', 'reading', NULL, 'Research into the origins of the universe has driven advances in telescope technology and data analysis.', 'Dựa vào câu trên, từ “universe” có nghĩa phù hợp nhất là gì?', '["xe đẩy mua sắm","lễ; nghi lễ; nghi thức","thường xuyên; hay xảy ra","vũ trụ; toàn bộ không gian và mọi thứ tồn tại trong đó"]'::jsonb, 3, 'universe: vũ trụ; toàn bộ không gian và mọi thứ tồn tại trong đó; thế giới trải nghiệm; hệ thống tư tưởng hoặc sự kiện tưởng tượng. Dịch cả câu: Nghiên cứu về nguồn gốc của vũ trụ đã thúc đẩy sự tiến bộ trong công nghệ kính viễn vọng và phân tích dữ liệu.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_21', 'en-b1-45', NULL, 'comprehensive_test', 'reading', NULL, 'Research into renewable energy can help governments develop cleaner and more reliable sources of electricity.', 'Dựa vào câu trên, từ “research” có nghĩa phù hợp nhất là gì?', '["hy vọng rằng; mong sao","sự tái chế; việc tái chế","nghiên cứu; sự khảo sát","rùa biển; con rùa"]'::jsonb, 2, 'research: nghiên cứu; sự khảo sát; điều tra kỹ lưỡng. Dịch cả câu: Nghiên cứu về năng lượng tái tạo có thể giúp các chính phủ phát triển các nguồn điện sạch hơn và đáng tin cậy hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_22', 'en-b1-45', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tồn tại; có thật”', '["locker","graduate","canal","exist"]'::jsonb, 3, 'tồn tại; có thật → exist (/ɪɡˈzɪst/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_45_23', 'en-b1-45', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phòng thí nghiệm; phòng nghiên cứu”', '["growth","laboratory","realise","effort"]'::jsonb, 1, 'phòng thí nghiệm; phòng nghiên cứu → laboratory (/ˈlæbrətɔːri/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
