INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-46', 'en', 'Bài 46: Khoa học & Nghiên cứu (2) - CEFR B1', 'CEFR B1', 'B1 · Khoa học', '17 từ vựng Tiếng Anh CEFR B1 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3046, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_telescope', 'en-b1-46', 'telescope', '/ˈtelɪskoʊp/', 'B1', 'kính viễn vọng; thu gọn; rút ngắn; lồng vào nhau; trượt lồng', 'n.', 'telescopic (adj.)', NULL, 'Quan sát các vì sao thường dùng telescope; ống nhòm hai mắt thường gọi là binoculars.', 'We watched the moon through a telescope on the balcony.', NULL, 'Chúng tôi ngắm mặt trăng qua một chiếc kính viễn vọng trên ban công.', '{"wordId":"telescope","ukIpa":"/ˈtelɪskəʊp/","usIpa":"/ˈtelɪskoʊp/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"An instrument that makes distant objects appear closer and clearer","vi":"kính viễn vọng"},{"pos":"v.","en":"To fit events or activities into a shorter period","vi":"thu gọn; rút ngắn"},{"pos":"v.","en":"To slide overlapping sections into or out of each other","vi":"lồng vào nhau; trượt lồng"}],"examples":[{"en":"We watched the moon through a telescope on the balcony.","vi":"Chúng tôi ngắm mặt trăng qua một chiếc kính viễn vọng trên ban công.","audioKind":"ex"},{"en":"Space telescopes allow scientists to study distant galaxies without interference from the Earth''s atmosphere.","vi":"Kính viễn vọng không gian cho phép các nhà khoa học nghiên cứu các thiên hà xa xôi mà không bị nhiễu động bởi bầu khí quyển Trái Đất.","audioKind":"ex2"}],"collocations":[{"en":"look through a telescope","vi":"nhìn qua kính viễn vọng"},{"en":"space telescope","vi":"kính viễn vọng không gian"},{"en":"radio telescope","vi":"kính viễn vọng vô tuyến"},{"en":"telescope something into","vi":"thu gọn cái gì vào"}],"wordFamily":["telescopic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Quan sát các vì sao thường dùng telescope; ống nhòm hai mắt thường gọi là binoculars.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_biologist', 'en-b1-46', 'biologist', '/baɪˈɑːlədʒɪst/', 'B1', 'nhà sinh vật học', 'n.', 'biology (n.), biological (adj.), biologically (adv.)', NULL, 'Chuyên gia nghiên cứu về sinh vật biển được gọi là "marine biologist".', 'The biologist carefully examined a frog beside the pond.', NULL, 'Nhà sinh vật học cẩn thận quan sát một con ếch bên bờ ao.', '{"wordId":"biologist","ukIpa":"/baɪˈɒlədʒɪst/","usIpa":"/baɪˈɑːlədʒɪst/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"A scientist who studies living things.","vi":"nhà sinh vật học"}],"examples":[{"en":"The biologist carefully examined a frog beside the pond.","vi":"Nhà sinh vật học cẩn thận quan sát một con ếch bên bờ ao.","audioKind":"ex"},{"en":"A marine biologist can help coastal communities understand how pollution affects local fish populations.","vi":"Một nhà sinh vật học biển có thể giúp các cộng đồng ven biển hiểu được ô nhiễm ảnh hưởng như thế nào đến các quần thể cá địa phương.","audioKind":"ex2"}],"collocations":[{"en":"marine biologist","vi":"nhà sinh vật học biển"},{"en":"wildlife biologist","vi":"nhà sinh vật học động vật hoang dã"},{"en":"evolutionary biologist","vi":"nhà sinh vật học tiến hóa"}],"wordFamily":["biology (n.)","biological (adj.)","biologically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Chuyên gia nghiên cứu về sinh vật biển được gọi là \"marine biologist\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_liquid', 'en-b1-46', 'liquid', '/ˈlɪkwɪd/', 'B1', 'chất lỏng; lỏng; dưới dạng tiền mặt; dễ chuyển đổi thành tiền mặt', 'n.', 'liquidity (n.), liquefy (v.), liquefaction (n.)', 'Đồng nghĩa: fluid · Trái nghĩa: solid', 'liquid làm danh từ chỉ chất lỏng; liquid assets chỉ tiền mặt hoặc tài sản dễ quy đổi ra tiền mặt.', 'She poured the warm liquid carefully into a glass.', NULL, 'Cô ấy cẩn thận rót chất lỏng ấm vào một chiếc ly.', '{"wordId":"liquid","ukIpa":"/ˈlɪkwɪd/","usIpa":"/ˈlɪkwɪd/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"A substance that flows and takes the shape of its container.","vi":"chất lỏng"},{"pos":"adj.","en":"In a form that flows freely rather than remaining solid.","vi":"lỏng"},{"pos":"adj.","en":"Available as cash or easily converted into cash.","vi":"dưới dạng tiền mặt; dễ chuyển đổi thành tiền mặt"}],"examples":[{"en":"She poured the warm liquid carefully into a glass.","vi":"Cô ấy cẩn thận rót chất lỏng ấm vào một chiếc ly.","audioKind":"ex"},{"en":"Scientists analyse liquid samples from rivers to identify pollutants and assess potential risks to public health.","vi":"Các nhà khoa học phân tích các mẫu chất lỏng từ các con sông để xác định chất ô nhiễm và đánh giá các rủi ro tiềm ẩn đối với sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"clear liquid","vi":"chất lỏng trong suốt"},{"en":"liquid water","vi":"nước ở thể lỏng"},{"en":"liquid soap","vi":"xà phòng nước"},{"en":"liquid assets","vi":"tài sản thanh khoản"}],"wordFamily":["liquidity (n.)","liquefy (v.)","liquefaction (n.)"],"synonyms":["fluid"],"antonyms":["solid"],"tipVi":"liquid làm danh từ chỉ chất lỏng; liquid assets chỉ tiền mặt hoặc tài sản dễ quy đổi ra tiền mặt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pure', 'en-b1-46', 'pure', '/pjʊr/', 'B1', 'nguyên chất; tinh khiết; hoàn toàn; đích thực; thuần túy; mang tính lý thuyết', 'adj.', 'purity (n.), purely (adv.), purify (v.), impure (adj.)', 'Đồng nghĩa: unmixed · Trái nghĩa: impure', 'Từ pure vừa có thể dùng để chỉ chất không lẫn tạp chất, vừa dùng để nhấn mạnh mức độ như trong cụm pure luck.', 'This soft scarf is made from pure wool.', NULL, 'Chiếc khăn quàng cổ mềm mại này được làm từ len nguyên chất.', '{"wordId":"pure","ukIpa":"/pjʊə/","usIpa":"/pjʊr/","cefr":"B1","topic":"science","senses":[{"pos":"adj.","en":"not mixed with other substances","vi":"nguyên chất; tinh khiết"},{"pos":"adj.","en":"complete and containing nothing of a different kind","vi":"hoàn toàn; đích thực; thuần túy"},{"pos":"adj.","en":"concerned with theory rather than practical uses","vi":"mang tính lý thuyết"}],"examples":[{"en":"This soft scarf is made from pure wool.","vi":"Chiếc khăn quàng cổ mềm mại này được làm từ len nguyên chất.","audioKind":"ex"},{"en":"Investment in pure science can lead to unexpected discoveries with important practical applications decades later.","vi":"Việc đầu tư vào khoa học thuần túy có thể dẫn đến những khám phá bất ngờ với các ứng dụng thực tiễn quan trọng nhiều thập kỷ sau đó.","audioKind":"ex2"}],"collocations":[{"en":"pure water","vi":"nước tinh khiết"},{"en":"pure wool","vi":"len nguyên chất"},{"en":"pure chance","vi":"hoàn toàn tình cờ"},{"en":"pure mathematics","vi":"toán học thuần túy"}],"wordFamily":["purity (n.)","purely (adv.)","purify (v.)","impure (adj.)"],"synonyms":["unmixed"],"antonyms":["impure"],"tipVi":"Từ pure vừa có thể dùng để chỉ chất không lẫn tạp chất, vừa dùng để nhấn mạnh mức độ như trong cụm pure luck.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_steam', 'en-b1-46', 'steam', '/stiːm/', 'B1', 'hơi nước; làn hơi; hấp; làm chín bằng hơi nước', 'n.', 'steamer (n.), steamy (adj.)', NULL, 'steam đóng vai trò danh từ thường không đếm được; đóng vai trò động từ có thể biểu thị việc hấp thức ăn.', 'Steam rose from the soup as I lifted the lid.', NULL, 'Hơi nước bốc lên từ bát súp khi tôi nhấc nắp nồi lên.', '{"wordId":"steam","ukIpa":"/stiːm/","usIpa":"/stiːm/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"The gas water becomes when heated, often seen as white mist.","vi":"hơi nước; làn hơi"},{"pos":"v.","en":"To cook food using steam from boiling water.","vi":"hấp; làm chín bằng hơi nước"}],"examples":[{"en":"Steam rose from the soup as I lifted the lid.","vi":"Hơi nước bốc lên từ bát súp khi tôi nhấc nắp nồi lên.","audioKind":"ex"},{"en":"Some power stations use heat to produce steam, which drives turbines and generates electricity.","vi":"Một số nhà máy điện sử dụng nhiệt để tạo ra hơi nước nhằm vận hành tuabin và phát ra điện.","audioKind":"ex2"}],"collocations":[{"en":"steam engine","vi":"động cơ hơi nước"},{"en":"steam vegetables","vi":"hấp rau củ"},{"en":"give off steam","vi":"bốc hơi"},{"en":"run out of steam","vi":"kiệt sức"}],"wordFamily":["steamer (n.)","steamy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"steam đóng vai trò danh từ thường không đếm được; đóng vai trò động từ có thể biểu thị việc hấp thức ăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discovery', 'en-b1-46', 'discovery', '/dɪˈskʌvəri/', 'B1', 'sự phát hiện; vật được phát hiện', 'n.', 'discover (v.), discoverer (n.)', 'Đồng nghĩa: finding', 'discovery là phát hiện ra thứ vốn đã tồn tại, khác với invention.', 'We made an exciting discovery behind the old cupboard.', NULL, 'Chúng tôi đã có một phát hiện thú vị phía sau chiếc tủ cũ.', '{"wordId":"discovery","ukIpa":"/dɪˈskʌvəri/","usIpa":"/dɪˈskʌvəri/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"finding something previously unknown, or the thing that is found","vi":"sự phát hiện; vật được phát hiện"}],"examples":[{"en":"We made an exciting discovery behind the old cupboard.","vi":"Chúng tôi đã có một phát hiện thú vị phía sau chiếc tủ cũ.","audioKind":"ex"},{"en":"The discovery of new antibiotics could help health services respond more effectively to drug-resistant infections.","vi":"Việc phát hiện ra các loại kháng sinh mới có thể giúp các cơ quan y tế ứng phó hiệu quả hơn với các bệnh nhiễm trùng kháng thuốc.","audioKind":"ex2"}],"collocations":[{"en":"make a discovery","vi":"có một phát hiện"},{"en":"scientific discovery","vi":"phát hiện khoa học"},{"en":"major discovery","vi":"phát hiện lớn"},{"en":"accidental discovery","vi":"phát hiện tình cờ"}],"wordFamily":["discover (v.)","discoverer (n.)"],"synonyms":["finding"],"antonyms":[],"tipVi":"discovery là phát hiện ra thứ vốn đã tồn tại, khác với invention.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surface', 'en-b1-46', 'surface', '/ˈsɝːfɪs/', 'B1', 'bề mặt; mặt; nổi lên mặt nước; lộ ra; được biết đến', 'n.', NULL, 'Đồng nghĩa: exterior, emerge', 'on the surface có nghĩa là "trên bề mặt", hoặc có thể mang nghĩa là "thoạt nhìn, bề ngoài".', 'Wipe the kitchen surface before you start preparing lunch.', NULL, 'Hãy lau sạch mặt bàn bếp trước khi bạn bắt đầu chuẩn bị bữa trưa.', '{"wordId":"surface","ukIpa":"/ˈsɜːfɪs/","usIpa":"/ˈsɝːfɪs/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"The outside or top layer of something","vi":"bề mặt; mặt"},{"pos":"v.","en":"To rise to the top of water","vi":"nổi lên mặt nước"},{"pos":"v.","en":"To become known or noticeable after being hidden","vi":"lộ ra; được biết đến"}],"examples":[{"en":"Wipe the kitchen surface before you start preparing lunch.","vi":"Hãy lau sạch mặt bàn bếp trước khi bạn bắt đầu chuẩn bị bữa trưa.","audioKind":"ex"},{"en":"Dark road surfaces absorb heat during the day, contributing to higher temperatures in urban areas.","vi":"Bề mặt đường màu sẫm hấp thụ nhiệt vào ban ngày, góp phần làm tăng nhiệt độ ở các khu đô thị.","audioKind":"ex2"}],"collocations":[{"en":"a smooth surface","vi":"bề mặt nhẵn"},{"en":"the Earth''s surface","vi":"bề mặt Trái Đất"},{"en":"beneath the surface","vi":"bên dưới bề mặt"},{"en":"surface tension","vi":"sức căng bề mặt"}],"wordFamily":[],"synonyms":["exterior","emerge"],"antonyms":[],"tipVi":"on the surface có nghĩa là \"trên bề mặt\", hoặc có thể mang nghĩa là \"thoạt nhìn, bề ngoài\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_melt', 'en-b1-46', 'melt', '/melt/', 'B1', 'tan chảy; làm tan chảy; làm mềm lòng; làm cảm động', 'v.', 'melting (adj.), molten (adj.)', 'Trái nghĩa: freeze, solidify', 'melt chỉ hiện tượng tan chảy do nhiệt; dissolve chỉ việc hòa tan trong chất lỏng.', 'The butter melted quickly in the warm pan.', NULL, 'Bơ tan chảy nhanh chóng trong chiếc chảo ấm.', '{"wordId":"melt","ukIpa":"/melt/","usIpa":"/melt/","cefr":"B1","topic":"science","senses":[{"pos":"v.","en":"To become liquid through heat, or make something become liquid","vi":"tan chảy; làm tan chảy"},{"pos":"v.","en":"To become gentler emotionally, or make someone feel this way","vi":"làm mềm lòng; làm cảm động"}],"examples":[{"en":"The butter melted quickly in the warm pan.","vi":"Bơ tan chảy nhanh chóng trong chiếc chảo ấm.","audioKind":"ex"},{"en":"As global temperatures rise, mountain glaciers melt faster, threatening freshwater supplies for communities downstream.","vi":"Khi nhiệt độ toàn cầu tăng lên, các sông băng trên núi tan chảy nhanh hơn, đe dọa nguồn cung cấp nước ngọt cho các cộng đồng hạ lưu.","audioKind":"ex2"}],"collocations":[{"en":"melt ice","vi":"làm tan băng"},{"en":"melt away","vi":"tan biến đi"},{"en":"melt someone''s heart","vi":"làm tan chảy trái tim ai đó"}],"wordFamily":["melting (adj.)","molten (adj.)"],"synonyms":[],"antonyms":["freeze","solidify"],"tipVi":"melt chỉ hiện tượng tan chảy do nhiệt; dissolve chỉ việc hòa tan trong chất lỏng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carbon', 'en-b1-46', 'carbon', '/ˈkɑːrbən/', 'B1', 'cac-bon; nguyên tố carbon', 'n.', 'carbonise (v.), carbonisation (n.)', NULL, 'carbon là carbon nguyên tố; carbon dioxide mới là carbon dioxide.', 'Diamonds and the graphite in pencils both contain carbon.', NULL, 'Kim cương và than chì trong bút chì đều chứa carbon.', '{"wordId":"carbon","ukIpa":"/ˈkɑːbən/","usIpa":"/ˈkɑːrbən/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"A chemical element present in all living things.","vi":"cac-bon; nguyên tố carbon"}],"examples":[{"en":"Diamonds and the graphite in pencils both contain carbon.","vi":"Kim cương và than chì trong bút chì đều chứa carbon.","audioKind":"ex"},{"en":"Protecting forests helps store carbon and reduces the amount of carbon dioxide released into the atmosphere.","vi":"Việc bảo vệ rừng giúp lưu trữ carbon và giảm lượng khí thải carbon dioxide thải vào khí quyển.","audioKind":"ex2"}],"collocations":[{"en":"carbon dioxide","vi":"khí carbon dioxide"},{"en":"carbon emissions","vi":"lượng khí thải carbon"},{"en":"carbon footprint","vi":"dấu chân carbon"},{"en":"carbon neutral","vi":"trung hòa carbon"}],"wordFamily":["carbonise (v.)","carbonisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"carbon là carbon nguyên tố; carbon dioxide mới là carbon dioxide.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_element', 'en-b1-46', 'element', '/ˈelɪmənt/', 'B1', 'yếu tố; thành phần cơ bản; nguyên tố hóa học; thời tiết khắc nghiệt', 'n.', 'elemental (adj.), elementary (adj.)', 'Đồng nghĩa: component, factor', 'Khi chỉ các lực lượng tự nhiên như gió mưa, thường dùng cụm từ the elements.', 'Fresh herbs are a key element of this soup.', NULL, 'Thảo mộc tươi là một yếu tố quan trọng của món súp này.', '{"wordId":"element","ukIpa":"/ˈelɪmənt/","usIpa":"/ˈelɪmənt/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"An important or basic part of something.","vi":"yếu tố; thành phần cơ bản"},{"pos":"n.","en":"A substance that cannot be chemically divided into simpler substances.","vi":"nguyên tố hóa học"},{"pos":"n.","en":"Strong wind, rain, or other difficult weather conditions.","vi":"thời tiết khắc nghiệt"}],"examples":[{"en":"Fresh herbs are a key element of this soup.","vi":"Thảo mộc tươi là một yếu tố quan trọng của món súp này.","audioKind":"ex"},{"en":"Public trust is an essential element of any successful policy aimed at improving community health.","vi":"Sự tin tưởng của công chúng là một yếu tố thiết yếu của bất kỳ chính sách thành công nào nhằm cải thiện sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"a key element","vi":"yếu tố then chốt"},{"en":"a chemical element","vi":"nguyên tố hóa học"},{"en":"exposure to the elements","vi":"chịu sự khắc nghiệt của thời tiết"}],"wordFamily":["elemental (adj.)","elementary (adj.)"],"synonyms":["component","factor"],"antonyms":[],"tipVi":"Khi chỉ các lực lượng tự nhiên như gió mưa, thường dùng cụm từ the elements.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_maximum', 'en-b1-46', 'maximum', '/ˈmæksɪməm/', 'B1', 'tối đa; lớn nhất; cao nhất; giá trị tối đa; hạn mức tối đa', 'adj.', 'maximise (v.), maximisation (n.)', 'Trái nghĩa: minimum', 'a maximum of biểu thị “tối đa”; từ trái nghĩa là minimum.', 'This lift has a maximum capacity of eight people.', NULL, 'Thang máy này có sức chứa tối đa là tám người.', '{"wordId":"maximum","ukIpa":"/ˈmæksɪməm/","usIpa":"/ˈmæksɪməm/","cefr":"B1","topic":"science","senses":[{"pos":"adj.","en":"being the greatest amount or level possible or allowed","vi":"tối đa; lớn nhất; cao nhất"},{"pos":"n.","en":"the greatest amount or level possible or allowed","vi":"giá trị tối đa; hạn mức tối đa"}],"examples":[{"en":"This lift has a maximum capacity of eight people.","vi":"Thang máy này có sức chứa tối đa là tám người.","audioKind":"ex"},{"en":"Governments should set maximum limits on industrial emissions to protect public health and improve air quality.","vi":"Chính phủ nên đặt ra các giới hạn tối đa đối với lượng khí thải công nghiệp để bảo vệ sức khỏe cộng đồng và cải thiện chất lượng không khí.","audioKind":"ex2"}],"collocations":[{"en":"maximum capacity","vi":"sức chứa tối đa"},{"en":"maximum speed","vi":"tốc độ tối đa"},{"en":"a maximum of","vi":"tối đa"},{"en":"reach the maximum","vi":"đạt mức tối đa"}],"wordFamily":["maximise (v.)","maximisation (n.)"],"synonyms":[],"antonyms":["minimum"],"tipVi":"a maximum of biểu thị “tối đa”; từ trái nghĩa là minimum.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rocket', 'en-b1-46', 'rocket', '/ˈrɑːkɪt/', 'B1', 'tên lửa; tăng vọt; vọt lên rất nhanh', 'n.', NULL, NULL, 'Khi làm động từ, rocket thường mô tả giá cả tăng mạnh, mức độ mạnh hơn increase.', 'We watched the rocket rise above the clouds.', NULL, 'Chúng tôi ngắm nhìn tên lửa bay vút lên trên các tầng mây.', '{"wordId":"rocket","ukIpa":"/ˈrɒkɪt/","usIpa":"/ˈrɑːkɪt/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"A vehicle driven forward by powerful gases, often into space","vi":"tên lửa"},{"pos":"v.","en":"Rise or increase very quickly","vi":"tăng vọt; vọt lên rất nhanh"}],"examples":[{"en":"We watched the rocket rise above the clouds.","vi":"Chúng tôi ngắm nhìn tên lửa bay vút lên trên các tầng mây.","audioKind":"ex"},{"en":"As housing demand continues to grow, rents may rocket in cities with limited space for new development.","vi":"Khi nhu cầu nhà ở tiếp tục tăng cao, giá thuê nhà có thể tăng vọt ở những thành phố có ít quỹ đất cho dự án mới.","audioKind":"ex2"}],"collocations":[{"en":"launch a rocket","vi":"phóng tên lửa"},{"en":"rocket engine","vi":"động cơ tên lửa"},{"en":"prices rocket","vi":"giá cả tăng vọt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi làm động từ, rocket thường mô tả giá cả tăng mạnh, mức độ mạnh hơn increase.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chemist', 'en-b1-46', 'chemist', '/ˈkemɪst/', 'B1', 'nhà hóa học; dược sĩ; hiệu thuốc (tiếng Anh - Anh)', 'n.', 'chemistry (n.), chemical (adj.), chemically (adv.)', NULL, 'Trong tiếng Anh - Anh, chemist còn có nghĩa là dược sĩ; chemist''s thường dùng để chỉ hiệu thuốc.', 'The chemist carefully poured the liquid into a glass tube.', NULL, 'Nhà hóa học cẩn thận rót chất lỏng vào ống nghiệm thủy tinh.', '{"wordId":"chemist","ukIpa":"/ˈkemɪst/","usIpa":"/ˈkemɪst/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"A scientist who studies chemicals and how they react.","vi":"nhà hóa học"},{"pos":"n.","en":"A pharmacist, or a shop that sells medicines, in British English.","vi":"dược sĩ; hiệu thuốc (tiếng Anh - Anh)"}],"examples":[{"en":"The chemist carefully poured the liquid into a glass tube.","vi":"Nhà hóa học cẩn thận rót chất lỏng vào ống nghiệm thủy tinh.","audioKind":"ex"},{"en":"Chemists are developing safer materials that could reduce the environmental impact of industrial production.","vi":"Các nhà hóa học đang phát triển những vật liệu an toàn hơn nhằm giảm thiểu tác động môi trường từ hoạt động sản xuất công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"analytical chemist","vi":"nhà hóa học phân tích"},{"en":"research chemist","vi":"nhà nghiên cứu hóa học"},{"en":"at the chemist''s","vi":"ở hiệu thuốc"}],"wordFamily":["chemistry (n.)","chemical (adj.)","chemically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh - Anh, chemist còn có nghĩa là dược sĩ; chemist''s thường dùng để chỉ hiệu thuốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_experiment', 'en-b1-46', 'experiment', '/ɪkˈsperəmənt/', 'B1', 'thí nghiệm; cuộc thử nghiệm; làm thí nghiệm; thử nghiệm', 'n.', 'experimental (adj.), experimentally (adv.), experimentation (n.)', 'Đồng nghĩa: test, trial', 'Động từ đi kèm với giới từ with biểu thị ý nghĩa thử nghiệm; danh từ có trọng âm rơi vào âm tiết thứ hai.', 'Our science experiment showed how roots grow towards water.', NULL, 'Thí nghiệm khoa học của chúng tôi cho thấy phần rễ cây phát triển hướng về phía nguồn nước như thế nào.', '{"wordId":"experiment","ukIpa":"/ɪkˈsperɪmənt/","usIpa":"/ɪkˈsperəmənt/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"a test designed to discover something or check an idea","vi":"thí nghiệm; cuộc thử nghiệm"},{"pos":"v.","en":"test ideas or methods to see what happens","vi":"làm thí nghiệm; thử nghiệm"}],"examples":[{"en":"Our science experiment showed how roots grow towards water.","vi":"Thí nghiệm khoa học của chúng tôi cho thấy phần rễ cây phát triển hướng về phía nguồn nước như thế nào.","audioKind":"ex"},{"en":"Schools should allow students to experiment with different materials before explaining the scientific principles involved.","vi":"Nhà trường nên cho phép học sinh thử nghiệm với các vật liệu khác nhau trước khi giải thích các nguyên lý khoa học liên quan.","audioKind":"ex2"}],"collocations":[{"en":"conduct an experiment","vi":"tiến hành một thí nghiệm"},{"en":"a controlled experiment","vi":"một thí nghiệm có kiểm soát"},{"en":"experiment with materials","vi":"thử nghiệm với các vật liệu"}],"wordFamily":["experimental (adj.)","experimentally (adv.)","experimentation (n.)"],"synonyms":["test","trial"],"antonyms":[],"tipVi":"Động từ đi kèm với giới từ with biểu thị ý nghĩa thử nghiệm; danh từ có trọng âm rơi vào âm tiết thứ hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prediction', 'en-b1-46', 'prediction', '/prɪˈdɪkʃən/', 'B1', 'sự dự đoán; lời tiên đoán', 'n.', 'predict (v.), predictable (adj.), unpredictable (adj.), predictive (adj.)', 'Đồng nghĩa: forecast', 'Cụm từ diễn tả hành động đưa ra dự đoán là make a prediction, không dùng động từ do.', 'Your prediction was right: it rained all afternoon.', NULL, 'Dự đoán của bạn đã đúng: trời mưa suốt cả buổi chiều.', '{"wordId":"prediction","ukIpa":"/prɪˈdɪkʃən/","usIpa":"/prɪˈdɪkʃən/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"A statement about what is expected to happen in the future.","vi":"sự dự đoán; lời tiên đoán"}],"examples":[{"en":"Your prediction was right: it rained all afternoon.","vi":"Dự đoán của bạn đã đúng: trời mưa suốt cả buổi chiều.","audioKind":"ex"},{"en":"Accurate predictions of future energy demand are essential for planning reliable and sustainable electricity supplies.","vi":"Những dự đoán chính xác về nhu cầu năng lượng trong tương lai đóng vai trò cốt lõi trong việc lập kế hoạch cung cấp điện năng ổn định và bền vững.","audioKind":"ex2"}],"collocations":[{"en":"make a prediction","vi":"đưa ra dự đoán"},{"en":"accurate prediction","vi":"dự đoán chính xác"},{"en":"prediction model","vi":"mô hình dự đoán"},{"en":"prediction comes true","vi":"dự đoán thành hiện thực"}],"wordFamily":["predict (v.)","predictable (adj.)","unpredictable (adj.)","predictive (adj.)"],"synonyms":["forecast"],"antonyms":[],"tipVi":"Cụm từ diễn tả hành động đưa ra dự đoán là make a prediction, không dùng động từ do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_force', 'en-b1-46', 'force', '/fɔːrs/', 'B1', 'lực; sức mạnh vật lý; ép buộc; cưỡng bức; vũ lực; bạo lực', 'n.', 'forceful (adj.), forcefully (adv.), forced (adj.), forcibly (adv.)', NULL, 'Cấu trúc "ép buộc ai làm gì" dùng force somebody to do something.', 'The force of the wind blew my umbrella inside out.', NULL, 'Sức gió lớn đã thổi lật ngược chiếc ô của tôi.', '{"wordId":"force","ukIpa":"/fɔːs/","usIpa":"/fɔːrs/","cefr":"B1","topic":"science","senses":[{"pos":"n.","en":"physical power that moves something or changes its shape","vi":"lực; sức mạnh vật lý"},{"pos":"v.","en":"to make someone do something against their wishes","vi":"ép buộc; cưỡng bức"},{"pos":"n.","en":"physical strength used to control or overpower someone","vi":"vũ lực; bạo lực"}],"examples":[{"en":"The force of the wind blew my umbrella inside out.","vi":"Sức gió lớn đã thổi lật ngược chiếc ô của tôi.","audioKind":"ex"},{"en":"Rising housing costs may force essential workers to move further away from the communities they serve.","vi":"Chi phí nhà ở tăng cao có thể buộc những người lao động thiết yếu phải chuyển ra xa hơn các cộng đồng mà họ đang phục vụ.","audioKind":"ex2"}],"collocations":[{"en":"force someone to do something","vi":"buộc ai đó phải làm gì"},{"en":"by force","vi":"bằng vũ lực"},{"en":"gravitational force","vi":"lực hấp dẫn"},{"en":"labour force","vi":"lực lượng lao động"}],"wordFamily":["forceful (adj.)","forcefully (adv.)","forced (adj.)","forcibly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc \"ép buộc ai làm gì\" dùng force somebody to do something.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_centigrade', 'en-b1-46', 'centigrade', '/ˈsentɪɡreɪd/', 'B1', 'độ C (thuộc thang nhiệt độ với điểm đóng băng của nước là không độ)', 'adj.', NULL, 'Đồng nghĩa: Celsius', 'Thường dùng cụm degrees centigrade; trong khoa học hiện đại, từ Celsius được sử dụng phổ biến hơn.', 'It was thirty degrees centigrade in the shade today.', NULL, 'Nhiệt độ trong bóng râm hôm nay là ba mươi độ C.', '{"wordId":"centigrade","ukIpa":"/ˈsentɪɡreɪd/","usIpa":"/ˈsentɪɡreɪd/","cefr":"B1","topic":"science","senses":[{"pos":"adj.","en":"Using the temperature scale with water freezing at zero","vi":"độ C (thuộc thang nhiệt độ với điểm đóng băng của nước là không độ)"}],"examples":[{"en":"It was thirty degrees centigrade in the shade today.","vi":"Nhiệt độ trong bóng râm hôm nay là ba mươi độ C.","audioKind":"ex"},{"en":"A rise of two degrees centigrade in average temperatures could significantly affect agricultural production in vulnerable regions.","vi":"Nhiệt độ trung bình tăng hai độ C có thể ảnh hưởng đáng kể đến sản xuất nông nghiệp ở các vùng dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"degrees centigrade","vi":"độ C"},{"en":"centigrade scale","vi":"thang đo độ C"}],"wordFamily":[],"synonyms":["Celsius"],"antonyms":[],"tipVi":"Thường dùng cụm degrees centigrade; trong khoa học hiện đại, từ Celsius được sử dụng phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_46_1', 'en-b1-46', 'Cách dùng “pure” (adj.) — nguyên chất; tinh khiết', 'pure water  ·  pure wool  ·  pure chance', 'Từ pure vừa có thể dùng để chỉ chất không lẫn tạp chất, vừa dùng để nhấn mạnh mức độ như trong cụm pure luck.', 'Họ từ (Word Family): purity (n.), purely (adv.), purify (v.), impure (adj.) | Đồng nghĩa: unmixed · Trái nghĩa: impure', '[{"hanzi":"This soft scarf is made from pure wool.","pinyin":"","meaning":"Chiếc khăn quàng cổ mềm mại này được làm từ len nguyên chất."},{"hanzi":"Investment in pure science can lead to unexpected discoveries with important practical applications decades later.","pinyin":"","meaning":"Việc đầu tư vào khoa học thuần túy có thể dẫn đến những khám phá bất ngờ với các ứng dụng thực tiễn quan trọng nhiều thập kỷ sau đó."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_46_2', 'en-b1-46', 'Cách dùng “experiment” (n.) — thí nghiệm; cuộc thử nghiệm', 'conduct an experiment  ·  a controlled experiment  ·  experiment with materials', 'Động từ đi kèm với giới từ with biểu thị ý nghĩa thử nghiệm; danh từ có trọng âm rơi vào âm tiết thứ hai.', 'Họ từ (Word Family): experimental (adj.), experimentally (adv.), experimentation (n.) | Đồng nghĩa: test, trial', '[{"hanzi":"Our science experiment showed how roots grow towards water.","pinyin":"","meaning":"Thí nghiệm khoa học của chúng tôi cho thấy phần rễ cây phát triển hướng về phía nguồn nước như thế nào."},{"hanzi":"Schools should allow students to experiment with different materials before explaining the scientific principles involved.","pinyin":"","meaning":"Nhà trường nên cho phép học sinh thử nghiệm với các vật liệu khác nhau trước khi giải thích các nguyên lý khoa học liên quan."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_46_3', 'en-b1-46', 'Cách dùng “steam” (n.) — hơi nước; làn hơi', 'steam engine  ·  steam vegetables  ·  give off steam', 'steam đóng vai trò danh từ thường không đếm được; đóng vai trò động từ có thể biểu thị việc hấp thức ăn.', 'Họ từ (Word Family): steamer (n.), steamy (adj.)', '[{"hanzi":"Steam rose from the soup as I lifted the lid.","pinyin":"","meaning":"Hơi nước bốc lên từ bát súp khi tôi nhấc nắp nồi lên."},{"hanzi":"Some power stations use heat to produce steam, which drives turbines and generates electricity.","pinyin":"","meaning":"Một số nhà máy điện sử dụng nhiệt để tạo ra hơi nước nhằm vận hành tuabin và phát ra điện."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_46_4', 'en-b1-46', 'Cách dùng “centigrade” (adj.) — độ C (thuộc thang nhiệt độ với điểm đóng băng của nước là không độ)', 'degrees centigrade  ·  centigrade scale', 'Thường dùng cụm degrees centigrade; trong khoa học hiện đại, từ Celsius được sử dụng phổ biến hơn.', 'Đồng nghĩa: Celsius', '[{"hanzi":"It was thirty degrees centigrade in the shade today.","pinyin":"","meaning":"Nhiệt độ trong bóng râm hôm nay là ba mươi độ C."},{"hanzi":"A rise of two degrees centigrade in average temperatures could significantly affect agricultural production in vulnerable regions.","pinyin":"","meaning":"Nhiệt độ trung bình tăng hai độ C có thể ảnh hưởng đáng kể đến sản xuất nông nghiệp ở các vùng dễ bị tổn thương."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_46_1', 'en-b1-46', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_1_1', 'ten_b1_46_1', 'telescope', 'We watched the moon through a telescope on the balcony.', 'We watched the moon through a telescope on the balcony.', '/ˈtelɪskoʊp/', 'Chúng tôi ngắm mặt trăng qua một chiếc kính viễn vọng trên ban công.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_1_2', 'ten_b1_46_1', 'biologist', 'The biologist carefully examined a frog beside the pond.', 'The biologist carefully examined a frog beside the pond.', '/baɪˈɑːlədʒɪst/', 'Nhà sinh vật học cẩn thận quan sát một con ếch bên bờ ao.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_1_3', 'ten_b1_46_1', 'liquid', 'She poured the warm liquid carefully into a glass.', 'She poured the warm liquid carefully into a glass.', '/ˈlɪkwɪd/', 'Cô ấy cẩn thận rót chất lỏng ấm vào một chiếc ly.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_1_4', 'ten_b1_46_1', 'pure', 'This soft scarf is made from pure wool.', 'This soft scarf is made from pure wool.', '/pjʊr/', 'Chiếc khăn quàng cổ mềm mại này được làm từ len nguyên chất.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_1_5', 'ten_b1_46_1', 'steam', 'Steam rose from the soup as I lifted the lid.', 'Steam rose from the soup as I lifted the lid.', '/stiːm/', 'Hơi nước bốc lên từ bát súp khi tôi nhấc nắp nồi lên.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_1_6', 'ten_b1_46_1', 'discovery', 'We made an exciting discovery behind the old cupboard.', 'We made an exciting discovery behind the old cupboard.', '/dɪˈskʌvəri/', 'Chúng tôi đã có một phát hiện thú vị phía sau chiếc tủ cũ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_1_7', 'ten_b1_46_1', 'surface', 'Wipe the kitchen surface before you start preparing lunch.', 'Wipe the kitchen surface before you start preparing lunch.', '/ˈsɝːfɪs/', 'Hãy lau sạch mặt bàn bếp trước khi bạn bắt đầu chuẩn bị bữa trưa.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_1_8', 'ten_b1_46_1', 'melt', 'The butter melted quickly in the warm pan.', 'The butter melted quickly in the warm pan.', '/melt/', 'Bơ tan chảy nhanh chóng trong chiếc chảo ấm.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_46_1_1', 'en-b1-46', 'ten_b1_46_1', 'listening', 'listening', 'We watched the moon through a telescope on the balcony.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hơi nước bốc lên từ bát súp khi tôi nhấc nắp nồi lên.","Chúng tôi ngắm mặt trăng qua một chiếc kính viễn vọng trên ban công.","Cô ấy cẩn thận rót chất lỏng ấm vào một chiếc ly.","Chúng tôi đã có một phát hiện thú vị phía sau chiếc tủ cũ."]'::jsonb, 1, 'We watched the moon through a telescope on the balcony. → Chúng tôi ngắm mặt trăng qua một chiếc kính viễn vọng trên ban công.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_46_1_2', 'en-b1-46', 'ten_b1_46_1', 'listening', 'listening', 'The biologist carefully examined a frog beside the pond.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hãy lau sạch mặt bàn bếp trước khi bạn bắt đầu chuẩn bị bữa trưa.","Chiếc khăn quàng cổ mềm mại này được làm từ len nguyên chất.","Chúng tôi ngắm nhìn tên lửa bay vút lên trên các tầng mây.","Nhà sinh vật học cẩn thận quan sát một con ếch bên bờ ao."]'::jsonb, 3, 'The biologist carefully examined a frog beside the pond. → Nhà sinh vật học cẩn thận quan sát một con ếch bên bờ ao.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_46_1_3', 'en-b1-46', 'ten_b1_46_1', 'listening', 'listening', 'She poured the warm liquid carefully into a glass.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy cẩn thận rót chất lỏng ấm vào một chiếc ly.","Sức gió lớn đã thổi lật ngược chiếc ô của tôi.","Chúng tôi đã có một phát hiện thú vị phía sau chiếc tủ cũ.","Kim cương và than chì trong bút chì đều chứa carbon."]'::jsonb, 0, 'She poured the warm liquid carefully into a glass. → Cô ấy cẩn thận rót chất lỏng ấm vào một chiếc ly.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_46_2', 'en-b1-46', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_2_1', 'ten_b1_46_2', 'telescope', 'Space telescopes allow scientists to study distant galaxies without interference from the Earth''s atmosphere.', 'Space telescopes allow scientists to study distant galaxies without interference from the Earth''s atmosphere.', '/ˈtelɪskoʊp/', 'Kính viễn vọng không gian cho phép các nhà khoa học nghiên cứu các thiên hà xa xôi mà không bị nhiễu động bởi bầu khí quyển Trái Đất.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_2_2', 'ten_b1_46_2', 'biologist', 'A marine biologist can help coastal communities understand how pollution affects local fish populations.', 'A marine biologist can help coastal communities understand how pollution affects local fish populations.', '/baɪˈɑːlədʒɪst/', 'Một nhà sinh vật học biển có thể giúp các cộng đồng ven biển hiểu được ô nhiễm ảnh hưởng như thế nào đến các quần thể cá địa phương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_2_3', 'ten_b1_46_2', 'liquid', 'Scientists analyse liquid samples from rivers to identify pollutants and assess potential risks to public health.', 'Scientists analyse liquid samples from rivers to identify pollutants and assess potential risks to public health.', '/ˈlɪkwɪd/', 'Các nhà khoa học phân tích các mẫu chất lỏng từ các con sông để xác định chất ô nhiễm và đánh giá các rủi ro tiềm ẩn đối với sức khỏe cộng đồng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_2_4', 'ten_b1_46_2', 'pure', 'Investment in pure science can lead to unexpected discoveries with important practical applications decades later.', 'Investment in pure science can lead to unexpected discoveries with important practical applications decades later.', '/pjʊr/', 'Việc đầu tư vào khoa học thuần túy có thể dẫn đến những khám phá bất ngờ với các ứng dụng thực tiễn quan trọng nhiều thập kỷ sau đó.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_2_5', 'ten_b1_46_2', 'steam', 'Some power stations use heat to produce steam, which drives turbines and generates electricity.', 'Some power stations use heat to produce steam, which drives turbines and generates electricity.', '/stiːm/', 'Một số nhà máy điện sử dụng nhiệt để tạo ra hơi nước nhằm vận hành tuabin và phát ra điện.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_46_2_6', 'ten_b1_46_2', 'discovery', 'The discovery of new antibiotics could help health services respond more effectively to drug-resistant infections.', 'The discovery of new antibiotics could help health services respond more effectively to drug-resistant infections.', '/dɪˈskʌvəri/', 'Việc phát hiện ra các loại kháng sinh mới có thể giúp các cơ quan y tế ứng phó hiệu quả hơn với các bệnh nhiễm trùng kháng thuốc.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_46_2_1', 'en-b1-46', 'ten_b1_46_2', 'listening', 'listening', 'Space telescopes allow scientists to study distant galaxies without interference from the Earth''s atmosphere.', NULL, 'Trong câu vừa nghe, từ “telescope” mang nghĩa nào sau đây?', '["bài thơ; tác phẩm văn học sử dụng ngôn từ được gọt giũa cẩn thận, thường được chia thành các dòng","kính viễn vọng","hiệu trưởng nam; nam hiệu trưởng","bày ra; trưng bày; hiển thị"]'::jsonb, 1, '“telescope” (/ˈtelɪskoʊp/): kính viễn vọng. Câu đầy đủ: Space telescopes allow scientists to study distant galaxies without interference from the Earth''s atmosphere.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_46_2_2', 'en-b1-46', 'ten_b1_46_2', 'listening', 'listening', 'A marine biologist can help coastal communities understand how pollution affects local fish populations.', NULL, 'Trong câu vừa nghe, từ “biologist” mang nghĩa nào sau đây?', '["khe hở; khoảng trống","ngày nay; hiện nay","nhà sinh vật học","rừng rậm nhiệt đới; rừng nguyên sinh"]'::jsonb, 2, '“biologist” (/baɪˈɑːlədʒɪst/): nhà sinh vật học. Câu đầy đủ: A marine biologist can help coastal communities understand how pollution affects local fish populations.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
