INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_46_2', 'en-b1-46', NULL, 'comprehensive_test', 'listening', 'The biologist carefully examined a frog beside the pond.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy lau sạch mặt bàn bếp trước khi bạn bắt đầu chuẩn bị bữa trưa.","Nhà hóa học cẩn thận rót chất lỏng vào ống nghiệm thủy tinh.","Nhà sinh vật học cẩn thận quan sát một con ếch bên bờ ao.","Thảo mộc tươi là một yếu tố quan trọng của món súp này."]'::jsonb, 2, 'The biologist carefully examined a frog beside the pond. → Nhà sinh vật học cẩn thận quan sát một con ếch bên bờ ao.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_46_3', 'en-b1-46', NULL, 'comprehensive_test', 'listening', 'liquid', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chất lỏng","đã đính hôn","nghề nghiệp; chuyên môn (đòi hỏi đào tạo chuyên sâu)","tấm thảm; chiếu"]'::jsonb, 0, 'liquid (/ˈlɪkwɪd/) → chất lỏng; lỏng; dưới dạng tiền mặt; dễ chuyển đổi thành tiền mặt', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_46_4', 'en-b1-46', NULL, 'comprehensive_test', 'listening', 'This soft scarf is made from pure wool.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy lau sạch mặt bàn bếp trước khi bạn bắt đầu chuẩn bị bữa trưa.","Hơi nước bốc lên từ bát súp khi tôi nhấc nắp nồi lên.","Chiếc khăn quàng cổ mềm mại này được làm từ len nguyên chất.","Thảo mộc tươi là một yếu tố quan trọng của món súp này."]'::jsonb, 2, 'This soft scarf is made from pure wool. → Chiếc khăn quàng cổ mềm mại này được làm từ len nguyên chất.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_46_5', 'en-b1-46', NULL, 'comprehensive_test', 'listening', 'steam', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cuộc khảo sát; cuộc thăm dò ý kiến","nạn nhân","người đưa thư; sứ giả; người truyền tin","hơi nước; làn hơi"]'::jsonb, 3, 'steam (/stiːm/) → hơi nước; làn hơi; hấp; làm chín bằng hơi nước', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_46_6', 'en-b1-46', NULL, 'comprehensive_test', 'listening', 'We made an exciting discovery behind the old cupboard.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Kim cương và than chì trong bút chì đều chứa carbon.","Chúng tôi đã có một phát hiện thú vị phía sau chiếc tủ cũ.","Hơi nước bốc lên từ bát súp khi tôi nhấc nắp nồi lên.","Bơ tan chảy nhanh chóng trong chiếc chảo ấm."]'::jsonb, 1, 'We made an exciting discovery behind the old cupboard. → Chúng tôi đã có một phát hiện thú vị phía sau chiếc tủ cũ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
