INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_46_18', 'en-b1-46', NULL, 'comprehensive_test', 'reading', NULL, 'Space telescopes allow scientists to study distant galaxies without interference from the Earth''s atmosphere.', 'Dựa vào câu trên, từ “telescope” có nghĩa phù hợp nhất là gì?', '["kính viễn vọng","hoài bão; chí hướng","vị trí; địa điểm","tiếng khóc; sự khóc"]'::jsonb, 0, 'telescope: kính viễn vọng; thu gọn; rút ngắn; lồng vào nhau; trượt lồng. Dịch cả câu: Kính viễn vọng không gian cho phép các nhà khoa học nghiên cứu các thiên hà xa xôi mà không bị nhiễu động bởi bầu khí quyển Trái Đất.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_46_19', 'en-b1-46', NULL, 'comprehensive_test', 'reading', NULL, 'A marine biologist can help coastal communities understand how pollution affects local fish populations.', 'Dựa vào câu trên, từ “biologist” có nghĩa phù hợp nhất là gì?', '["cá voi","nhà sinh vật học","kiến trúc sư","có xu hướng; thường"]'::jsonb, 1, 'biologist: nhà sinh vật học. Dịch cả câu: Một nhà sinh vật học biển có thể giúp các cộng đồng ven biển hiểu được ô nhiễm ảnh hưởng như thế nào đến các quần thể cá địa phương.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_46_20', 'en-b1-46', NULL, 'comprehensive_test', 'reading', NULL, 'Scientists analyse liquid samples from rivers to identify pollutants and assess potential risks to public health.', 'Dựa vào câu trên, từ “liquid” có nghĩa phù hợp nhất là gì?', '["chất lỏng","quý giá; đắt tiền","được cho phép; được chuẩn y","mục đích; mục tiêu"]'::jsonb, 0, 'liquid: chất lỏng; lỏng; dưới dạng tiền mặt; dễ chuyển đổi thành tiền mặt. Dịch cả câu: Các nhà khoa học phân tích các mẫu chất lỏng từ các con sông để xác định chất ô nhiễm và đánh giá các rủi ro tiềm ẩn đối với sức khỏe cộng đồng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_46_21', 'en-b1-46', NULL, 'comprehensive_test', 'reading', NULL, 'Investment in pure science can lead to unexpected discoveries with important practical applications decades later.', 'Dựa vào câu trên, từ “pure” có nghĩa phù hợp nhất là gì?', '["nguyên chất; tinh khiết","cuộc bầu cử; sự bầu cử","đồ cũ; đã qua sử dụng","ống khói"]'::jsonb, 0, 'pure: nguyên chất; tinh khiết; hoàn toàn; đích thực; thuần túy; mang tính lý thuyết. Dịch cả câu: Việc đầu tư vào khoa học thuần túy có thể dẫn đến những khám phá bất ngờ với các ứng dụng thực tiễn quan trọng nhiều thập kỷ sau đó.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_46_22', 'en-b1-46', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự dự đoán; lời tiên đoán”', '["string","bunch","carnival","prediction"]'::jsonb, 3, 'sự dự đoán; lời tiên đoán → prediction (/prɪˈdɪkʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_46_23', 'en-b1-46', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lực; sức mạnh vật lý”', '["force","baggage","suitable","string"]'::jsonb, 0, 'lực; sức mạnh vật lý → force (/fɔːrs/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_46_24', 'en-b1-46', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “độ C (thuộc thang nhiệt độ với điểm đóng băng của nước là không độ)”', '["defend","centigrade","skip","scientific"]'::jsonb, 1, 'độ C (thuộc thang nhiệt độ với điểm đóng băng của nước là không độ) → centigrade (/ˈsentɪɡreɪd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-47', 'en', 'Bài 47: Truyền thông & Tin tức (1) - CEFR B1', 'CEFR B1', 'B1 · Truyền thông', '16 từ vựng Tiếng Anh CEFR B1 chủ đề truyền thông & tin tức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3047, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_content', 'en-b1-47', 'content', '/ˈkɑːntent/; /kənˈtent/', 'B1', 'thông tin; hàm lượng; hài lòng; mãn nguyện; làm cho hài lòng', 'n.', 'contentment (n.), contented (adj.)', NULL, 'Danh từ trọng âm ở âm tiết đầu, tính từ và động từ ở âm tiết sau; mục lục sách dùng contents.', 'The content of this podcast always makes me laugh.', NULL, 'Nội dung của podcast này luôn làm tôi bật cười.', '{"wordId":"content","ukIpa":"/ˈkɒntent/; /kənˈtent/","usIpa":"/ˈkɑːntent/; /kənˈtent/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"Information in something, or the amount of a substance it contains","vi":"thông tin; hàm lượng"},{"pos":"adj.","en":"Happy with what you have or with your situation","vi":"hài lòng; mãn nguyện"},{"pos":"v.","en":"To make someone satisfied with what is available","vi":"làm cho hài lòng"}],"examples":[{"en":"The content of this podcast always makes me laugh.","vi":"Nội dung của podcast này luôn làm tôi bật cười.","audioKind":"ex"},{"en":"Schools should teach students to evaluate online content critically rather than accepting every claim as reliable information.","vi":"Nhà trường nên dạy học sinh cách đánh giá nội dung trực tuyến một cách phản biện thay vì mặc nhiên coi mọi tuyên bố là thông tin đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"online content","vi":"nội dung trực tuyến"},{"en":"sugar content","vi":"hàm lượng đường"},{"en":"content with","vi":"hài lòng với"},{"en":"content yourself with","vi":"tự mãn nguyện với"}],"wordFamily":["contentment (n.)","contented (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ trọng âm ở âm tiết đầu, tính từ và động từ ở âm tiết sau; mục lục sách dùng contents.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_image', 'en-b1-47', 'image', '/ˈɪmɪdʒ/', 'B1', 'hình ảnh; ảnh chụp; hình ảnh công chúng; uy tín; hình ảnh trong tâm trí', 'n.', 'imagery (n.), imaging (n.)', 'Đồng nghĩa: picture', 'Có thể chỉ hình ảnh trực quan hoặc hình ảnh cá nhân, tổ chức trước công chúng.', 'The camera captured a sharp image of the bird.', NULL, 'Máy ảnh đã chụp lại một hình ảnh sắc nét của con chim.', '{"wordId":"image","ukIpa":"/ˈɪmɪdʒ/","usIpa":"/ˈɪmɪdʒ/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"A picture or visual representation of someone or something.","vi":"hình ảnh; ảnh chụp"},{"pos":"n.","en":"The impression that people have of a person or organization.","vi":"hình ảnh công chúng; uy tín"},{"pos":"n.","en":"A picture of someone or something formed in your mind.","vi":"hình ảnh trong tâm trí"}],"examples":[{"en":"The camera captured a sharp image of the bird.","vi":"Máy ảnh đã chụp lại một hình ảnh sắc nét của con chim.","audioKind":"ex"},{"en":"Companies increasingly use social media to improve their public image and build stronger relationships with customers.","vi":"Các công ty ngày càng sử dụng mạng xã hội để cải thiện hình ảnh trước công chúng và xây dựng mối quan hệ bền chặt hơn với khách hàng.","audioKind":"ex2"}],"collocations":[{"en":"digital image","vi":"hình ảnh kỹ thuật số"},{"en":"public image","vi":"hình ảnh công chúng"},{"en":"mental image","vi":"hình ảnh trong tâm trí"},{"en":"high-resolution image","vi":"hình ảnh độ phân giải cao"}],"wordFamily":["imagery (n.)","imaging (n.)"],"synonyms":["picture"],"antonyms":[],"tipVi":"Có thể chỉ hình ảnh trực quan hoặc hình ảnh cá nhân, tổ chức trước công chúng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comment', 'en-b1-47', 'comment', '/ˈkɑːment/', 'B1', 'lời bình luận; ý kiến; bình luận; đưa ra ý kiến', 'n.', 'commentary (n.), commentator (n.)', 'Đồng nghĩa: remark', 'Động từ comment đi với giới từ on rồi mới đến đối tượng được bình luận, không trực tiếp đi kèm tân ngữ.', 'Her kind comment about my painting made me smile.', NULL, 'Lời nhận xét ân cần của cô ấy về bức tranh của tôi đã làm tôi mỉm cười.', '{"wordId":"comment","ukIpa":"/ˈkɒment/","usIpa":"/ˈkɑːment/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"something said or written to express an opinion or observation","vi":"lời bình luận; ý kiến"},{"pos":"v.","en":"to express an opinion or observation about something","vi":"bình luận; đưa ra ý kiến"}],"examples":[{"en":"Her kind comment about my painting made me smile.","vi":"Lời nhận xét ân cần của cô ấy về bức tranh của tôi đã làm tôi mỉm cười.","audioKind":"ex"},{"en":"Residents should have opportunities to comment on development proposals before local authorities make final decisions.","vi":"Cư dân nên có cơ hội đóng góp ý kiến về các đề xuất phát triển trước khi cơ quan chức năng đưa ra quyết định cuối cùng.","audioKind":"ex2"}],"collocations":[{"en":"make a comment","vi":"đưa ra bình luận"},{"en":"comment on something","vi":"bình luận về điều gì"},{"en":"constructive comments","vi":"ý kiến đóng góp tính xây dựng"},{"en":"no comment","vi":"không có ý kiến"}],"wordFamily":["commentary (n.)","commentator (n.)"],"synonyms":["remark"],"antonyms":[],"tipVi":"Động từ comment đi với giới từ on rồi mới đến đối tượng được bình luận, không trực tiếp đi kèm tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_advertise', 'en-b1-47', 'advertise', '/ˈædvɚtaɪz/', 'B1', 'quảng cáo; quảng bá; đăng tuyển; rao bán', 'v.', 'advertisement (n.), advertising (n.), advertiser (n.)', 'Đồng nghĩa: promote, publicise', 'Advertise một sản phẩm là quảng cáo; advertise for một người nghĩa là đăng quảng cáo tuyển dụng.', 'The bakery advertises its fresh bread on local radio.', NULL, 'Tiệm bánh quảng cáo bánh mì tươi của họ trên đài phát thanh địa phương.', '{"wordId":"advertise","ukIpa":"/ˈædvətaɪz/","usIpa":"/ˈædvɚtaɪz/","cefr":"B1","topic":"media","senses":[{"pos":"v.","en":"To promote products, services or events through public messages.","vi":"quảng cáo; quảng bá"},{"pos":"v.","en":"To announce publicly that someone or something is wanted.","vi":"đăng tuyển; rao bán"}],"examples":[{"en":"The bakery advertises its fresh bread on local radio.","vi":"Tiệm bánh quảng cáo bánh mì tươi của họ trên đài phát thanh địa phương.","audioKind":"ex"},{"en":"Governments should restrict how companies advertise sugary snacks to children, who may not recognise persuasive marketing techniques.","vi":"Chính phủ nên hạn chế cách các công ty quảng cáo đồ ăn vặt chứa đường cho trẻ em, những đối tượng có thể chưa nhận ra các kỹ thuật tiếp thị mang tính thuyết phục.","audioKind":"ex2"}],"collocations":[{"en":"advertise a product","vi":"quảng cáo một sản phẩm"},{"en":"advertise for staff","vi":"đăng tuyển nhân sự"},{"en":"advertise online","vi":"quảng cáo trực tuyến"}],"wordFamily":["advertisement (n.)","advertising (n.)","advertiser (n.)"],"synonyms":["promote","publicise"],"antonyms":[],"tipVi":"Advertise một sản phẩm là quảng cáo; advertise for một người nghĩa là đăng quảng cáo tuyển dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_advertising', 'en-b1-47', 'advertising', '/ˈædvərtaɪzɪŋ/', 'B1', 'hoạt động quảng cáo; ngành quảng cáo', 'n.', 'advertise (v.), advertisement (n.), advertiser (n.)', NULL, 'advertising thường là danh từ không đếm được; một mẩu quảng cáo cụ thể dùng an advertisement.', 'My sister works in advertising and designs colourful posters.', NULL, 'Chị gái tôi làm việc trong ngành quảng cáo và thiết kế những tấm áp phích đầy màu sắc.', '{"wordId":"advertising","ukIpa":"/ˈædvətaɪzɪŋ/","usIpa":"/ˈædvərtaɪzɪŋ/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"The activity or business of promoting products and services.","vi":"hoạt động quảng cáo; ngành quảng cáo"}],"examples":[{"en":"My sister works in advertising and designs colourful posters.","vi":"Chị gái tôi làm việc trong ngành quảng cáo và thiết kế những tấm áp phích đầy màu sắc.","audioKind":"ex"},{"en":"Advertising can influence consumer choices, which is why campaigns aimed at children require careful regulation.","vi":"Quảng cáo có thể ảnh hưởng đến lựa chọn của người tiêu dùng, đó là lý do tại sao các chiến dịch hướng đến trẻ em đòi hỏi sự quản lý chặt chẽ.","audioKind":"ex2"}],"collocations":[{"en":"advertising campaign","vi":"chiến dịch quảng cáo"},{"en":"advertising agency","vi":"công ty quảng cáo"},{"en":"advertising revenue","vi":"doanh thu quảng cáo"},{"en":"misleading advertising","vi":"quảng cáo gây hiểu lầm"}],"wordFamily":["advertise (v.)","advertisement (n.)","advertiser (n.)"],"synonyms":[],"antonyms":[],"tipVi":"advertising thường là danh từ không đếm được; một mẩu quảng cáo cụ thể dùng an advertisement.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brochure', 'en-b1-47', 'brochure', '/broʊˈʃʊr/', 'B1', 'sách quảng cáo; tờ rơi thông tin', 'n.', NULL, 'Đồng nghĩa: booklet, pamphlet', 'Là danh từ đếm được, thường chỉ các tập sách nhỏ giới thiệu về du lịch, khóa học hoặc sản phẩm.', 'I picked up a travel brochure at the station.', NULL, 'Tôi đã lấy một cuốn cẩm nang du lịch ở nhà ga.', '{"wordId":"brochure","ukIpa":"/ˈbrəʊʃə/","usIpa":"/broʊˈʃʊr/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"A small booklet giving information about products, services, or places.","vi":"sách quảng cáo; tờ rơi thông tin"}],"examples":[{"en":"I picked up a travel brochure at the station.","vi":"Tôi đã lấy một cuốn cẩm nang du lịch ở nhà ga.","audioKind":"ex"},{"en":"University brochures can help prospective students compare courses, accommodation options, and the facilities available on campus.","vi":"Sách quảng cáo tuyển sinh của trường đại học có thể giúp các học sinh tiềm năng so sánh các khóa học, lựa chọn chỗ ở và các cơ sở vật chất có sẵn trong khuôn viên trường.","audioKind":"ex2"}],"collocations":[{"en":"travel brochure","vi":"tờ rơi du lịch"},{"en":"university brochure","vi":"sách quảng cáo đại học"},{"en":"promotional brochure","vi":"tài liệu quảng cáo"}],"wordFamily":[],"synonyms":["booklet","pamphlet"],"antonyms":[],"tipVi":"Là danh từ đếm được, thường chỉ các tập sách nhỏ giới thiệu về du lịch, khóa học hoặc sản phẩm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_episode', 'en-b1-47', 'episode', '/ˈepɪsoʊd/', 'B1', 'tập phim (truyền hình/phát thanh); một sự việc; một giai đoạn; cơn bệnh phát tác', 'n.', 'episodic (adj.)', NULL, 'episode dùng chỉ một tập trong chuỗi; series dùng cho toàn bộ series hoặc phim truyền hình nhiều tập.', 'We watched the final episode together after dinner.', NULL, 'Chúng tôi cùng nhau xem tập cuối sau bữa tối.', '{"wordId":"episode","ukIpa":"/ˈepɪsəʊd/","usIpa":"/ˈepɪsoʊd/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"one part of a television or radio series","vi":"tập phim (truyền hình/phát thanh)"},{"pos":"n.","en":"a particular event or period within a longer story","vi":"một sự việc; một giai đoạn"},{"pos":"n.","en":"a period when someone experiences a particular illness or symptom","vi":"cơn bệnh phát tác"}],"examples":[{"en":"We watched the final episode together after dinner.","vi":"Chúng tôi cùng nhau xem tập cuối sau bữa tối.","audioKind":"ex"},{"en":"Each episode of the documentary explores how urban development affects wildlife in different parts of the world.","vi":"Mỗi tập của bộ phim tài liệu khám phá cách sự phát triển đô thị ảnh hưởng đến động vật hoang dã ở các khu vực khác nhau trên thế giới.","audioKind":"ex2"}],"collocations":[{"en":"the final episode","vi":"tập cuối cùng"},{"en":"an episode of","vi":"một tập của"},{"en":"a pilot episode","vi":"tập thử nghiệm"},{"en":"a brief episode","vi":"một trải nghiệm ngắn ngủi"}],"wordFamily":["episodic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"episode dùng chỉ một tập trong chuỗi; series dùng cho toàn bộ series hoặc phim truyền hình nhiều tập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_announce', 'en-b1-47', 'announce', '/əˈnaʊns/', 'B1', 'thông báo; công bố', 'v.', 'announcement (n.), announcer (n.), unannounced (adj.)', 'Đồng nghĩa: declare, proclaim', 'Dùng announce sth hoặc announce that, không dùng announce sb sth.', 'Our teacher announced the winners after lunch today.', NULL, 'Giáo viên của chúng tôi đã công bố những người chiến thắng sau giờ ăn trưa hôm nay.', '{"wordId":"announce","ukIpa":"/əˈnaʊns/","usIpa":"/əˈnaʊns/","cefr":"B1","topic":"media","senses":[{"pos":"v.","en":"To make information known publicly or officially.","vi":"thông báo; công bố"}],"examples":[{"en":"Our teacher announced the winners after lunch today.","vi":"Giáo viên của chúng tôi đã công bố những người chiến thắng sau giờ ăn trưa hôm nay.","audioKind":"ex"},{"en":"Local authorities should announce major policy changes early so residents have enough time to prepare.","vi":"Chính quyền địa phương nên công bố sớm các thay đổi chính sách lớn để người dân có đủ thời gian chuẩn bị.","audioKind":"ex2"}],"collocations":[{"en":"announce plans","vi":"công bố kế hoạch"},{"en":"announce a decision","vi":"tuyên bố một quyết định"},{"en":"announce the results","vi":"công bố kết quả"}],"wordFamily":["announcement (n.)","announcer (n.)","unannounced (adj.)"],"synonyms":["declare","proclaim"],"antonyms":[],"tipVi":"Dùng announce sth hoặc announce that, không dùng announce sb sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ad', 'en-b1-47', 'ad', '/æd/', 'B1', 'quảng cáo', 'n.', 'advertisement (n.), advertise (v.), advertising (n.), advertiser (n.)', 'Đồng nghĩa: advertisement, advert', 'ad là từ viết tắt không chính thức của advertisement và là một danh từ đếm được.', 'An ad for cooking classes caught my attention yesterday.', NULL, 'Một quảng cáo về các lớp học nấu ăn đã thu hút sự chú ý của tôi ngày hôm qua.', '{"wordId":"ad","ukIpa":"/æd/","usIpa":"/æd/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"a public message promoting a product, service, or opportunity","vi":"quảng cáo"}],"examples":[{"en":"An ad for cooking classes caught my attention yesterday.","vi":"Một quảng cáo về các lớp học nấu ăn đã thu hút sự chú ý của tôi ngày hôm qua.","audioKind":"ex"},{"en":"Online ads can influence consumer choices by presenting products that match users'' browsing habits and interests.","vi":"Quảng cáo trực tuyến có thể ảnh hưởng đến lựa chọn của người tiêu dùng bằng cách hiển thị các sản phẩm phù hợp với thói quen duyệt web và sở thích của người dùng.","audioKind":"ex2"}],"collocations":[{"en":"online ad","vi":"quảng cáo trực tuyến"},{"en":"job ad","vi":"quảng cáo tuyển dụng"},{"en":"place an ad","vi":"đăng quảng cáo"},{"en":"ad campaign","vi":"chiến dịch quảng cáo"}],"wordFamily":["advertisement (n.)","advertise (v.)","advertising (n.)","advertiser (n.)"],"synonyms":["advertisement","advert"],"antonyms":[],"tipVi":"ad là từ viết tắt không chính thức của advertisement và là một danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_journalist', 'en-b1-47', 'journalist', '/ˈdʒɝːnəlɪst/', 'B1', 'nhà báo; phóng viên', 'n.', 'journalism (n.), journalistic (adj.)', 'Đồng nghĩa: reporter', 'Journalist mang nghĩa chung là người làm báo, trong khi reporter thiên về việc đi thực tế phỏng vấn đưa tin.', 'The journalist interviewed our neighbour about the new park.', NULL, 'Nhà báo nọ đã phỏng vấn hàng xóm của chúng tôi về công viên mới.', '{"wordId":"journalist","ukIpa":"/ˈdʒɜːnəlɪst/","usIpa":"/ˈdʒɝːnəlɪst/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"Someone who gathers and reports news for the media.","vi":"nhà báo; phóng viên"}],"examples":[{"en":"The journalist interviewed our neighbour about the new park.","vi":"Nhà báo nọ đã phỏng vấn hàng xóm của chúng tôi về công viên mới.","audioKind":"ex"},{"en":"A responsible journalist should verify information carefully before publishing stories that could influence public opinion.","vi":"Một nhà báo có trách nhiệm nên xác minh thông tin cẩn thận trước khi đăng tải các bài viết có thể ảnh hưởng đến dư luận công chúng.","audioKind":"ex2"}],"collocations":[{"en":"investigative journalist","vi":"nhà báo điều tra"},{"en":"freelance journalist","vi":"nhà báo tự do"},{"en":"broadcast journalist","vi":"phóng viên phát thanh truyền hình"}],"wordFamily":["journalism (n.)","journalistic (adj.)"],"synonyms":["reporter"],"antonyms":[],"tipVi":"Journalist mang nghĩa chung là người làm báo, trong khi reporter thiên về việc đi thực tế phỏng vấn đưa tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subtitle', 'en-b1-47', 'subtitle', '/ˈsʌbtaɪtl/', 'B1', 'phụ đề; phụ đề (tiêu đề phụ); làm phụ đề; thêm phụ đề', 'n.', 'title (n.), subtitling (n.)', NULL, 'Phụ đề phim ảnh thường dùng số nhiều "subtitles"; dạng số ít cũng có thể dùng để chỉ tiêu đề phụ của sách hoặc bài báo.', 'We watched the film with subtitles because the dialogue was quiet.', NULL, 'Chúng tôi xem bộ phim có phụ đề vì âm thanh đối thoại khá nhỏ.', '{"wordId":"subtitle","ukIpa":"/ˈsʌbtaɪtl/","usIpa":"/ˈsʌbtaɪtl/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"written dialogue or translation displayed on a screen","vi":"phụ đề"},{"pos":"n.","en":"an additional title explaining a work''s main title","vi":"phụ đề (tiêu đề phụ)"},{"pos":"v.","en":"to add written dialogue or translation to a film","vi":"làm phụ đề; thêm phụ đề"}],"examples":[{"en":"We watched the film with subtitles because the dialogue was quiet.","vi":"Chúng tôi xem bộ phim có phụ đề vì âm thanh đối thoại khá nhỏ.","audioKind":"ex"},{"en":"Subtitles can support language learning by helping viewers connect spoken expressions with their written forms.","vi":"Phụ đề có thể hỗ trợ việc học ngoại ngữ bằng cách giúp người xem kết nối các biểu đạt nói với dạng văn bản của chúng.","audioKind":"ex2"}],"collocations":[{"en":"English subtitles","vi":"phụ đề tiếng Anh"},{"en":"turn on subtitles","vi":"bật phụ đề"},{"en":"add a subtitle","vi":"thêm phụ đề"}],"wordFamily":["title (n.)","subtitling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Phụ đề phim ảnh thường dùng số nhiều \"subtitles\"; dạng số ít cũng có thể dùng để chỉ tiêu đề phụ của sách hoặc bài báo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_publish', 'en-b1-47', 'publish', '/ˈpʌblɪʃ/', 'B1', 'xuất bản; đăng tải; công bố; ban hành', 'v.', 'publisher (n.), publication (n.), published (adj.), unpublished (adj.)', 'Đồng nghĩa: release', 'Publish nhấn mạnh việc phát hành hoặc công bố rộng rãi trước công chúng, không chỉ đơn thuần là in ấn.', 'The local magazine published my photograph of the river.', NULL, 'Tạp chí địa phương đã đăng bức ảnh chụp dòng sông của tôi.', '{"wordId":"publish","ukIpa":"/ˈpʌblɪʃ/","usIpa":"/ˈpʌblɪʃ/","cefr":"B1","topic":"media","senses":[{"pos":"v.","en":"to produce books or other writing for public reading","vi":"xuất bản; đăng tải"},{"pos":"v.","en":"to make information officially available to the public","vi":"công bố; ban hành"}],"examples":[{"en":"The local magazine published my photograph of the river.","vi":"Tạp chí địa phương đã đăng bức ảnh chụp dòng sông của tôi.","audioKind":"ex"},{"en":"Researchers should publish their findings openly so that policymakers can make decisions based on reliable evidence.","vi":"Các nhà nghiên cứu nên công khai các phát hiện của mình để các nhà hoạch định chính sách có thể đưa ra quyết định dựa trên bằng chứng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"publish a book","vi":"xuất bản sách"},{"en":"publish an article","vi":"đăng bài báo"},{"en":"publish findings","vi":"công bố kết quả nghiên cứu"},{"en":"publish online","vi":"xuất bản trực tuyến"}],"wordFamily":["publisher (n.)","publication (n.)","published (adj.)","unpublished (adj.)"],"synonyms":["release"],"antonyms":[],"tipVi":"Publish nhấn mạnh việc phát hành hoặc công bố rộng rãi trước công chúng, không chỉ đơn thuần là in ấn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_leaflet', 'en-b1-47', 'leaflet', '/ˈliːflət/', 'B1', 'tờ rơi; tờ quảng cáo', 'n.', NULL, 'Đồng nghĩa: flyer', '''leaflet'' thường là một tờ đơn hoặc tờ gấp; ''brochure'' thường là một cuốn sách nhỏ.', 'A volunteer handed me a leaflet about the new library.', NULL, 'Một tình nguyện viên đã đưa cho tôi một tờ rơi về thư viện mới.', '{"wordId":"leaflet","ukIpa":"/ˈliːflət/","usIpa":"/ˈliːflət/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"A small printed sheet giving information or advertising something.","vi":"tờ rơi; tờ quảng cáo"}],"examples":[{"en":"A volunteer handed me a leaflet about the new library.","vi":"Một tình nguyện viên đã đưa cho tôi một tờ rơi về thư viện mới.","audioKind":"ex"},{"en":"Health centres can distribute a leaflet explaining how regular exercise helps prevent several common diseases.","vi":"Các trung tâm y tế có thể phát tờ rơi giải thích cách tập thể dục đều đặn giúp phòng ngừa một số bệnh thông thường.","audioKind":"ex2"}],"collocations":[{"en":"hand out leaflets","vi":"phát tờ rơi"},{"en":"information leaflet","vi":"tờ thông tin"},{"en":"promotional leaflet","vi":"tờ rơi quảng cáo"}],"wordFamily":[],"synonyms":["flyer"],"antonyms":[],"tipVi":"''leaflet'' thường là một tờ đơn hoặc tờ gấp; ''brochure'' thường là một cuốn sách nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_review', 'en-b1-47', 'review', '/rɪˈvjuː/', 'B1', 'bài đánh giá; lời bình phẩm; sự xem xét lại; cuộc tổng kiểm tra; xem xét lại; ôn tập; viết bài đánh giá', 'n.', 'reviewer (n.)', 'Đồng nghĩa: assessment, evaluation', 'Từ ôn tập (bài vở) ở tiếng Anh Mỹ thường dùng review, trong khi tiếng Anh Anh chuộng dùng revise.', 'Her review convinced me to read the whole novel.', NULL, 'Bài đánh giá của cô ấy đã thuyết phục tôi đọc trọn vẹn cuốn tiểu thuyết.', '{"wordId":"review","ukIpa":"/rɪˈvjuː/","usIpa":"/rɪˈvjuː/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"An account giving an opinion of a book, product, or performance.","vi":"bài đánh giá; lời bình phẩm"},{"pos":"n.","en":"A careful examination to assess something or consider changes.","vi":"sự xem xét lại; cuộc tổng kiểm tra"},{"pos":"v.","en":"To examine, study again, or give an opinion about something.","vi":"xem xét lại; ôn tập; viết bài đánh giá"}],"examples":[{"en":"Her review convinced me to read the whole novel.","vi":"Bài đánh giá của cô ấy đã thuyết phục tôi đọc trọn vẹn cuốn tiểu thuyết.","audioKind":"ex"},{"en":"Governments should regularly review housing policies to ensure that affordable accommodation remains available to low-income families.","vi":"Chính phủ nên thường xuyên xem xét lại các chính sách nhà ở để đảm bảo các hộ gia đình thu nhập thấp vẫn có thể tiếp cận nhà ở giá rẻ.","audioKind":"ex2"}],"collocations":[{"en":"write a review","vi":"viết bài đánh giá"},{"en":"a thorough review","vi":"một cuộc xem xét toàn diện"},{"en":"review a policy","vi":"xem xét lại một chính sách"},{"en":"review your notes","vi":"ôn tập vở ghi chép"}],"wordFamily":["reviewer (n.)"],"synonyms":["assessment","evaluation"],"antonyms":[],"tipVi":"Từ ôn tập (bài vở) ở tiếng Anh Mỹ thường dùng review, trong khi tiếng Anh Anh chuộng dùng revise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_documentary', 'en-b1-47', 'documentary', '/ˌdɑːkjəˈmentəri/', 'B1', 'phim tài liệu; chương trình tài liệu; bằng chứng tài liệu; văn bản chứng minh', 'n.', 'document (n.), document (v.), documentation (n.)', NULL, 'Dùng như danh từ để chỉ phim tài liệu; ''documentary evidence'' dùng để chỉ bằng chứng văn bản.', 'We watched a documentary about penguins after dinner.', NULL, 'Chúng tôi xem một bộ phim tài liệu về loài chim cánh cụt sau bữa tối.', '{"wordId":"documentary","ukIpa":"/ˌdɒkjəˈmentəri/","usIpa":"/ˌdɑːkjəˈmentəri/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"A film or programme presenting facts about real subjects.","vi":"phim tài liệu; chương trình tài liệu"},{"pos":"adj.","en":"Consisting of or supported by written documents.","vi":"bằng chứng tài liệu; văn bản chứng minh"}],"examples":[{"en":"We watched a documentary about penguins after dinner.","vi":"Chúng tôi xem một bộ phim tài liệu về loài chim cánh cụt sau bữa tối.","audioKind":"ex"},{"en":"A well-researched documentary can raise public awareness of environmental problems without oversimplifying their causes.","vi":"Một bộ phim tài liệu được nghiên cứu công phu có thể nâng cao nhận thức của công chúng về các vấn đề môi trường mà không làm đơn giản hóa quá mức nguyên nhân của chúng.","audioKind":"ex2"}],"collocations":[{"en":"documentary film","vi":"phim tài liệu"},{"en":"documentary evidence","vi":"bằng chứng bằng tài liệu"},{"en":"documentary about wildlife","vi":"phim tài liệu về đời sống hoang dã"}],"wordFamily":["document (n.)","document (v.)","documentation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng như danh từ để chỉ phim tài liệu; ''documentary evidence'' dùng để chỉ bằng chứng văn bản.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_newsletter', 'en-b1-47', 'newsletter', '/ˈnuːzletər/', 'B1', 'bản tin định kỳ; thông cáo', 'n.', NULL, 'Đồng nghĩa: bulletin', 'có thể là bản in hoặc bản điện tử; động từ đi kèm với việc đăng ký nhận là subscribe to.', 'Our school newsletter arrived in my inbox this morning.', NULL, 'Bản tin của trường chúng tôi đã được gửi đến hộp thư đến vào sáng nay.', '{"wordId":"newsletter","ukIpa":"/ˈnjuːzletə/","usIpa":"/ˈnuːzletər/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"a regular printed or electronic report for a particular group","vi":"bản tin định kỳ; thông cáo"}],"examples":[{"en":"Our school newsletter arrived in my inbox this morning.","vi":"Bản tin của trường chúng tôi đã được gửi đến hộp thư đến vào sáng nay.","audioKind":"ex"},{"en":"A monthly newsletter allows charities to share progress with supporters and explain how donations are being used.","vi":"Một bản tin hàng tháng giúp các tổ chức từ thiện chia sẻ tiến độ công việc với những người ủng hộ và giải thích cách sử dụng tiền quyên góp.","audioKind":"ex2"}],"collocations":[{"en":"monthly newsletter","vi":"bản tin hàng tháng"},{"en":"email newsletter","vi":"bản tin điện tử"},{"en":"subscribe to a newsletter","vi":"đăng ký nhận bản tin"}],"wordFamily":[],"synonyms":["bulletin"],"antonyms":[],"tipVi":"có thể là bản in hoặc bản điện tử; động từ đi kèm với việc đăng ký nhận là subscribe to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_47_1', 'en-b1-47', 'Cách dùng “subtitle” (n.) — phụ đề', 'English subtitles  ·  turn on subtitles  ·  add a subtitle', 'Phụ đề phim ảnh thường dùng số nhiều "subtitles"; dạng số ít cũng có thể dùng để chỉ tiêu đề phụ của sách hoặc bài báo.', 'Họ từ (Word Family): title (n.), subtitling (n.)', '[{"hanzi":"We watched the film with subtitles because the dialogue was quiet.","pinyin":"","meaning":"Chúng tôi xem bộ phim có phụ đề vì âm thanh đối thoại khá nhỏ."},{"hanzi":"Subtitles can support language learning by helping viewers connect spoken expressions with their written forms.","pinyin":"","meaning":"Phụ đề có thể hỗ trợ việc học ngoại ngữ bằng cách giúp người xem kết nối các biểu đạt nói với dạng văn bản của chúng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_47_2', 'en-b1-47', 'Cách dùng “journalist” (n.) — nhà báo; phóng viên', 'investigative journalist  ·  freelance journalist  ·  broadcast journalist', 'Journalist mang nghĩa chung là người làm báo, trong khi reporter thiên về việc đi thực tế phỏng vấn đưa tin.', 'Họ từ (Word Family): journalism (n.), journalistic (adj.) | Đồng nghĩa: reporter', '[{"hanzi":"The journalist interviewed our neighbour about the new park.","pinyin":"","meaning":"Nhà báo nọ đã phỏng vấn hàng xóm của chúng tôi về công viên mới."},{"hanzi":"A responsible journalist should verify information carefully before publishing stories that could influence public opinion.","pinyin":"","meaning":"Một nhà báo có trách nhiệm nên xác minh thông tin cẩn thận trước khi đăng tải các bài viết có thể ảnh hưởng đến dư luận công chúng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_47_3', 'en-b1-47', 'Cách dùng “comment” (n.) — lời bình luận; ý kiến', 'make a comment  ·  comment on something  ·  constructive comments', 'Động từ comment đi với giới từ on rồi mới đến đối tượng được bình luận, không trực tiếp đi kèm tân ngữ.', 'Họ từ (Word Family): commentary (n.), commentator (n.) | Đồng nghĩa: remark', '[{"hanzi":"Her kind comment about my painting made me smile.","pinyin":"","meaning":"Lời nhận xét ân cần của cô ấy về bức tranh của tôi đã làm tôi mỉm cười."},{"hanzi":"Residents should have opportunities to comment on development proposals before local authorities make final decisions.","pinyin":"","meaning":"Cư dân nên có cơ hội đóng góp ý kiến về các đề xuất phát triển trước khi cơ quan chức năng đưa ra quyết định cuối cùng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_47_4', 'en-b1-47', 'Cách dùng “publish” (v.) — xuất bản; đăng tải', 'publish a book  ·  publish an article  ·  publish findings', 'Publish nhấn mạnh việc phát hành hoặc công bố rộng rãi trước công chúng, không chỉ đơn thuần là in ấn.', 'Họ từ (Word Family): publisher (n.), publication (n.), published (adj.), unpublished (adj.) | Đồng nghĩa: release', '[{"hanzi":"The local magazine published my photograph of the river.","pinyin":"","meaning":"Tạp chí địa phương đã đăng bức ảnh chụp dòng sông của tôi."},{"hanzi":"Researchers should publish their findings openly so that policymakers can make decisions based on reliable evidence.","pinyin":"","meaning":"Các nhà nghiên cứu nên công khai các phát hiện của mình để các nhà hoạch định chính sách có thể đưa ra quyết định dựa trên bằng chứng đáng tin cậy."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_47_1', 'en-b1-47', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_47_1_1', 'ten_b1_47_1', 'content', 'The content of this podcast always makes me laugh.', 'The content of this podcast always makes me laugh.', '/ˈkɑːntent/; /kənˈtent/', 'Nội dung của podcast này luôn làm tôi bật cười.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_47_1_2', 'ten_b1_47_1', 'image', 'The camera captured a sharp image of the bird.', 'The camera captured a sharp image of the bird.', '/ˈɪmɪdʒ/', 'Máy ảnh đã chụp lại một hình ảnh sắc nét của con chim.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_47_1_3', 'ten_b1_47_1', 'comment', 'Her kind comment about my painting made me smile.', 'Her kind comment about my painting made me smile.', '/ˈkɑːment/', 'Lời nhận xét ân cần của cô ấy về bức tranh của tôi đã làm tôi mỉm cười.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_47_1_4', 'ten_b1_47_1', 'advertise', 'The bakery advertises its fresh bread on local radio.', 'The bakery advertises its fresh bread on local radio.', '/ˈædvɚtaɪz/', 'Tiệm bánh quảng cáo bánh mì tươi của họ trên đài phát thanh địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
