INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_47_1_8', 'ten_b1_47_1', 'announce', 'Our teacher announced the winners after lunch today.', 'Our teacher announced the winners after lunch today.', '/əˈnaʊns/', 'Giáo viên của chúng tôi đã công bố những người chiến thắng sau giờ ăn trưa hôm nay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_47_1_1', 'en-b1-47', 'ten_b1_47_1', 'listening', 'listening', 'The content of this podcast always makes me laugh.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi xem bộ phim có phụ đề vì âm thanh đối thoại khá nhỏ.","Nội dung của podcast này luôn làm tôi bật cười.","Một tình nguyện viên đã đưa cho tôi một tờ rơi về thư viện mới.","Tiệm bánh quảng cáo bánh mì tươi của họ trên đài phát thanh địa phương."]'::jsonb, 1, 'The content of this podcast always makes me laugh. → Nội dung của podcast này luôn làm tôi bật cười.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_47_1_2', 'en-b1-47', 'ten_b1_47_1', 'listening', 'listening', 'The camera captured a sharp image of the bird.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bản tin của trường chúng tôi đã được gửi đến hộp thư đến vào sáng nay.","Lời nhận xét ân cần của cô ấy về bức tranh của tôi đã làm tôi mỉm cười.","Nội dung của podcast này luôn làm tôi bật cười.","Máy ảnh đã chụp lại một hình ảnh sắc nét của con chim."]'::jsonb, 3, 'The camera captured a sharp image of the bird. → Máy ảnh đã chụp lại một hình ảnh sắc nét của con chim.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_47_1_3', 'en-b1-47', 'ten_b1_47_1', 'listening', 'listening', 'Her kind comment about my painting made me smile.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Lời nhận xét ân cần của cô ấy về bức tranh của tôi đã làm tôi mỉm cười.","Bản tin của trường chúng tôi đã được gửi đến hộp thư đến vào sáng nay.","Một quảng cáo về các lớp học nấu ăn đã thu hút sự chú ý của tôi ngày hôm qua.","Chị gái tôi làm việc trong ngành quảng cáo và thiết kế những tấm áp phích đầy màu sắc."]'::jsonb, 0, 'Her kind comment about my painting made me smile. → Lời nhận xét ân cần của cô ấy về bức tranh của tôi đã làm tôi mỉm cười.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_47_2', 'en-b1-47', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_47_2_1', 'ten_b1_47_2', 'content', 'Schools should teach students to evaluate online content critically rather than accepting every claim as reliable information.', 'Schools should teach students to evaluate online content critically rather than accepting every claim as reliable information.', '/ˈkɑːntent/; /kənˈtent/', 'Nhà trường nên dạy học sinh cách đánh giá nội dung trực tuyến một cách phản biện thay vì mặc nhiên coi mọi tuyên bố là thông tin đáng tin cậy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_47_2_2', 'ten_b1_47_2', 'image', 'Companies increasingly use social media to improve their public image and build stronger relationships with customers.', 'Companies increasingly use social media to improve their public image and build stronger relationships with customers.', '/ˈɪmɪdʒ/', 'Các công ty ngày càng sử dụng mạng xã hội để cải thiện hình ảnh trước công chúng và xây dựng mối quan hệ bền chặt hơn với khách hàng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_47_2_3', 'ten_b1_47_2', 'comment', 'Residents should have opportunities to comment on development proposals before local authorities make final decisions.', 'Residents should have opportunities to comment on development proposals before local authorities make final decisions.', '/ˈkɑːment/', 'Cư dân nên có cơ hội đóng góp ý kiến về các đề xuất phát triển trước khi cơ quan chức năng đưa ra quyết định cuối cùng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_47_2_4', 'ten_b1_47_2', 'advertise', 'Governments should restrict how companies advertise sugary snacks to children, who may not recognise persuasive marketing techniques.', 'Governments should restrict how companies advertise sugary snacks to children, who may not recognise persuasive marketing techniques.', '/ˈædvɚtaɪz/', 'Chính phủ nên hạn chế cách các công ty quảng cáo đồ ăn vặt chứa đường cho trẻ em, những đối tượng có thể chưa nhận ra các kỹ thuật tiếp thị mang tính thuyết phục.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_47_2_5', 'ten_b1_47_2', 'advertising', 'Advertising can influence consumer choices, which is why campaigns aimed at children require careful regulation.', 'Advertising can influence consumer choices, which is why campaigns aimed at children require careful regulation.', '/ˈædvərtaɪzɪŋ/', 'Quảng cáo có thể ảnh hưởng đến lựa chọn của người tiêu dùng, đó là lý do tại sao các chiến dịch hướng đến trẻ em đòi hỏi sự quản lý chặt chẽ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_47_2_6', 'ten_b1_47_2', 'brochure', 'University brochures can help prospective students compare courses, accommodation options, and the facilities available on campus.', 'University brochures can help prospective students compare courses, accommodation options, and the facilities available on campus.', '/broʊˈʃʊr/', 'Sách quảng cáo tuyển sinh của trường đại học có thể giúp các học sinh tiềm năng so sánh các khóa học, lựa chọn chỗ ở và các cơ sở vật chất có sẵn trong khuôn viên trường.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_47_2_1', 'en-b1-47', 'ten_b1_47_2', 'listening', 'listening', 'Schools should teach students to evaluate online content critically rather than accepting every claim as reliable information.', NULL, 'Trong câu vừa nghe, từ “content” mang nghĩa nào sau đây?', '["đáng tin cậy","thông tin; hàm lượng","ghen tị; đố kỵ","mặc dù; dẫu cho"]'::jsonb, 1, '“content” (/ˈkɑːntent/; /kənˈtent/): thông tin; hàm lượng. Câu đầy đủ: Schools should teach students to evaluate online content critically rather than accepting every claim as reliable information.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_47_2_2', 'en-b1-47', 'ten_b1_47_2', 'listening', 'listening', 'Companies increasingly use social media to improve their public image and build stronger relationships with customers.', NULL, 'Trong câu vừa nghe, từ “image” mang nghĩa nào sau đây?', '["hình ảnh; ảnh chụp","nạn nhân","làm cong; bẻ cong","trận động đất"]'::jsonb, 0, '“image” (/ˈɪmɪdʒ/): hình ảnh; ảnh chụp. Câu đầy đủ: Companies increasingly use social media to improve their public image and build stronger relationships with customers.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
