INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_47_2', 'en-b1-47', NULL, 'comprehensive_test', 'listening', 'The camera captured a sharp image of the bird.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một tình nguyện viên đã đưa cho tôi một tờ rơi về thư viện mới.","Chúng tôi xem bộ phim có phụ đề vì âm thanh đối thoại khá nhỏ.","Bản tin của trường chúng tôi đã được gửi đến hộp thư đến vào sáng nay.","Máy ảnh đã chụp lại một hình ảnh sắc nét của con chim."]'::jsonb, 3, 'The camera captured a sharp image of the bird. → Máy ảnh đã chụp lại một hình ảnh sắc nét của con chim.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
