INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_47_4', 'en-b1-47', NULL, 'comprehensive_test', 'listening', 'The bakery advertises its fresh bread on local radio.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bản tin của trường chúng tôi đã được gửi đến hộp thư đến vào sáng nay.","Lời nhận xét ân cần của cô ấy về bức tranh của tôi đã làm tôi mỉm cười.","Tiệm bánh quảng cáo bánh mì tươi của họ trên đài phát thanh địa phương.","Nhà báo nọ đã phỏng vấn hàng xóm của chúng tôi về công viên mới."]'::jsonb, 2, 'The bakery advertises its fresh bread on local radio. → Tiệm bánh quảng cáo bánh mì tươi của họ trên đài phát thanh địa phương.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
