INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_47_18', 'en-b1-47', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should teach students to evaluate online content critically rather than accepting every claim as reliable information.', 'Dựa vào câu trên, từ “content” có nghĩa phù hợp nhất là gì?', '["khốn khổ; đau khổ; buồn rầu","vô cùng ngạc nhiên; kinh ngạc","trách nhiệm; sự chịu trách nhiệm","thông tin; hàm lượng"]'::jsonb, 3, 'content: thông tin; hàm lượng; hài lòng; mãn nguyện; làm cho hài lòng. Dịch cả câu: Nhà trường nên dạy học sinh cách đánh giá nội dung trực tuyến một cách phản biện thay vì mặc nhiên coi mọi tuyên bố là thông tin đáng tin cậy.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_47_19', 'en-b1-47', NULL, 'comprehensive_test', 'reading', NULL, 'Companies increasingly use social media to improve their public image and build stronger relationships with customers.', 'Dựa vào câu trên, từ “image” có nghĩa phù hợp nhất là gì?', '["có hướng dẫn; có người dẫn đường","quả bom","thu nhập; tiền kiếm được","hình ảnh; ảnh chụp"]'::jsonb, 3, 'image: hình ảnh; ảnh chụp; hình ảnh công chúng; uy tín; hình ảnh trong tâm trí. Dịch cả câu: Các công ty ngày càng sử dụng mạng xã hội để cải thiện hình ảnh trước công chúng và xây dựng mối quan hệ bền chặt hơn với khách hàng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_47_20', 'en-b1-47', NULL, 'comprehensive_test', 'reading', NULL, 'Residents should have opportunities to comment on development proposals before local authorities make final decisions.', 'Dựa vào câu trên, từ “comment” có nghĩa phù hợp nhất là gì?', '["chào hỏi; đón tiếp","sự phát triển; sự lớn lên","lời bình luận; ý kiến","vòi nước"]'::jsonb, 2, 'comment: lời bình luận; ý kiến; bình luận; đưa ra ý kiến. Dịch cả câu: Cư dân nên có cơ hội đóng góp ý kiến về các đề xuất phát triển trước khi cơ quan chức năng đưa ra quyết định cuối cùng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_47_21', 'en-b1-47', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should restrict how companies advertise sugary snacks to children, who may not recognise persuasive marketing techniques.', 'Dựa vào câu trên, từ “advertise” có nghĩa phù hợp nhất là gì?', '["xứng đáng; có công","xóa; loại bỏ","quả bí ngô","quảng cáo; quảng bá"]'::jsonb, 3, 'advertise: quảng cáo; quảng bá; đăng tuyển; rao bán. Dịch cả câu: Chính phủ nên hạn chế cách các công ty quảng cáo đồ ăn vặt chứa đường cho trẻ em, những đối tượng có thể chưa nhận ra các kỹ thuật tiếp thị mang tính thuyết phục.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_47_22', 'en-b1-47', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bài đánh giá; lời bình phẩm”', '["arts","addition","progress","review"]'::jsonb, 3, 'bài đánh giá; lời bình phẩm → review (/rɪˈvjuː/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_47_23', 'en-b1-47', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phim tài liệu; chương trình tài liệu”', '["sink","documentary","heavily","underneath"]'::jsonb, 1, 'phim tài liệu; chương trình tài liệu → documentary (/ˌdɑːkjəˈmentəri/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_47_24', 'en-b1-47', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bản tin định kỳ; thông cáo”', '["written","quotation","newsletter","forbidden"]'::jsonb, 2, 'bản tin định kỳ; thông cáo → newsletter (/ˈnuːzletər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-48', 'en', 'Bài 48: Truyền thông & Tin tức (2) - CEFR B1', 'CEFR B1', 'B1 · Truyền thông', '16 từ vựng Tiếng Anh CEFR B1 chủ đề truyền thông & tin tức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3048, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flyer', 'en-b1-48', 'flyer', '/ˈflaɪər/', 'B1', 'tờ rơi quảng cáo; hành khách đi máy bay', 'n.', NULL, 'Đồng nghĩa: leaflet', 'Tờ rơi cũng có thể viết là flier; người đi máy bay thường xuyên dùng cụm frequent flyer.', 'Someone handed me a flyer outside the swimming pool.', NULL, 'Ai đó đã đưa cho tôi một tờ rơi ở bên ngoài hồ bơi.', '{"wordId":"flyer","ukIpa":"/ˈflaɪə/","usIpa":"/ˈflaɪər/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"A small printed sheet advertising an event, product, or service.","vi":"tờ rơi quảng cáo"},{"pos":"n.","en":"A person who travels by plane.","vi":"hành khách đi máy bay"}],"examples":[{"en":"Someone handed me a flyer outside the swimming pool.","vi":"Ai đó đã đưa cho tôi một tờ rơi ở bên ngoài hồ bơi.","audioKind":"ex"},{"en":"Local charities often distribute flyers to encourage residents to participate in community recycling schemes.","vi":"Các tổ chức từ thiện địa phương thường phát tờ rơi để khuyến khích cư dân tham gia các chương trình tái chế của cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"hand out flyers","vi":"phát tờ rơi"},{"en":"promotional flyer","vi":"tờ rơi quảng cáo"},{"en":"frequent flyer","vi":"khách đi máy bay thường xuyên"}],"wordFamily":[],"synonyms":["leaflet"],"antonyms":[],"tipVi":"Tờ rơi cũng có thể viết là flier; người đi máy bay thường xuyên dùng cụm frequent flyer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dialog', 'en-b1-48', 'dialog', '/ˈdaɪəlɔːɡ/', 'B1', 'đối thoại; lời thoại; cuộc đối thoại; sự trao đổi ý kiến; hộp thoại', 'n.', NULL, 'Đồng nghĩa: dialogue, conversation', 'dialog là dạng biến thể tiếng Mỹ; tiếng Anh-Anh thường dùng dialogue.', 'The actors practised their dialog before stepping onto the stage.', NULL, 'Các diễn viên đã luyện tập lời thoại trước khi bước lên sân khấu.', '{"wordId":"dialog","ukIpa":"/ˈdaɪəlɒɡ/","usIpa":"/ˈdaɪəlɔːɡ/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"A conversation, especially between characters in a story or play.","vi":"đối thoại; lời thoại"},{"pos":"n.","en":"Discussion between people or groups to improve understanding.","vi":"cuộc đối thoại; sự trao đổi ý kiến"},{"pos":"n.","en":"A small computer window requesting information or a choice.","vi":"hộp thoại"}],"examples":[{"en":"The actors practised their dialog before stepping onto the stage.","vi":"Các diễn viên đã luyện tập lời thoại trước khi bước lên sân khấu.","audioKind":"ex"},{"en":"Open dialog between local authorities and residents can help resolve disagreements about new housing developments.","vi":"Cuộc đối thoại cởi mở giữa chính quyền địa phương và cư dân có thể giúp giải quyết những bất đồng về các dự án phát triển nhà ở mới.","audioKind":"ex2"}],"collocations":[{"en":"open dialog","vi":"đối thoại cởi mở"},{"en":"dialog between groups","vi":"đối thoại giữa các nhóm"},{"en":"dialog box","vi":"hộp thoại"}],"wordFamily":[],"synonyms":["dialogue","conversation"],"antonyms":[],"tipVi":"dialog là dạng biến thể tiếng Mỹ; tiếng Anh-Anh thường dùng dialogue.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_series', 'en-b1-48', 'series', '/ˈsɪriːz/', 'B1', 'loạt; chuỗi; dải (các sự việc, sự kiện liên tiếp); series; bộ phim truyền hình dài tập; bộ sách', 'n.', NULL, NULL, 'Danh từ có hình thức số ít và số nhiều giống nhau: a series và two series.', 'A series of small delays made us miss lunch.', NULL, 'Một chuỗi những sự cố chậm trễ nhỏ đã khiến chúng tôi lỡ bữa trưa.', '{"wordId":"series","ukIpa":"/ˈsɪəriːz/","usIpa":"/ˈsɪriːz/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"several related things or events following one another","vi":"loạt; chuỗi; dải (các sự việc, sự kiện liên tiếp)"},{"pos":"n.","en":"a set of programmes or books sharing characters or a subject","vi":"series; bộ phim truyền hình dài tập; bộ sách"}],"examples":[{"en":"A series of small delays made us miss lunch.","vi":"Một chuỗi những sự cố chậm trễ nhỏ đã khiến chúng tôi lỡ bữa trưa.","audioKind":"ex"},{"en":"The university introduced a series of workshops to help students evaluate information found on social media.","vi":"Trường đại học đã giới thiệu một loạt các buổi hội thảo nhằm giúp sinh viên đánh giá thông tin tìm thấy trên mạng xã hội.","audioKind":"ex2"}],"collocations":[{"en":"a series of events","vi":"một loạt các sự kiện"},{"en":"a television series","vi":"một bộ phim truyền hình dài tập"},{"en":"a lecture series","vi":"một chuỗi các bài giảng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ có hình thức số ít và số nhiều giống nhau: a series và two series.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_celebrity', 'en-b1-48', 'celebrity', '/səˈlebrəti/', 'B1', 'người nổi tiếng; ngôi sao; sự nổi tiếng; danh tiếng', 'n.', 'celebrated (adj.)', 'Đồng nghĩa: star', 'Khi chỉ người nổi tiếng thì đếm được; khi chỉ sự nổi tiếng thì thường không đếm được.', 'A celebrity stopped outside the theatre to greet fans.', NULL, 'Một ngôi sao nổi tiếng dừng chân bên ngoài nhà hát để chào người hâm mộ.', '{"wordId":"celebrity","ukIpa":"/səˈlebrəti/","usIpa":"/səˈlebrəti/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"A person who is widely known by the public.","vi":"người nổi tiếng; ngôi sao"},{"pos":"n.","en":"The state of being famous.","vi":"sự nổi tiếng; danh tiếng"}],"examples":[{"en":"A celebrity stopped outside the theatre to greet fans.","vi":"Một ngôi sao nổi tiếng dừng chân bên ngoài nhà hát để chào người hâm mộ.","audioKind":"ex"},{"en":"Celebrity endorsements can influence young consumers, so advertisements should clearly distinguish personal opinions from paid promotion.","vi":"Việc người nổi tiếng quảng cáo nhãn hàng có thể tác động đến người tiêu dùng trẻ tuổi, vì vậy các quảng cáo nên phân biệt rõ ràng giữa quan điểm cá nhân và hoạt động tài trợ.","audioKind":"ex2"}],"collocations":[{"en":"celebrity endorsement","vi":"người nổi tiếng đại diện thương hiệu"},{"en":"celebrity culture","vi":"văn hóa thần tượng"},{"en":"achieve celebrity","vi":"đạt được danh tiếng"}],"wordFamily":["celebrated (adj.)"],"synonyms":["star"],"antonyms":[],"tipVi":"Khi chỉ người nổi tiếng thì đếm được; khi chỉ sự nổi tiếng thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_headline', 'en-b1-48', 'headline', '/ˈhedlaɪn/', 'B1', 'tiêu đề tin tức; đầu đề báo; trở thành tin chính hoặc nghệ sĩ biểu diễn chính', 'n.', NULL, NULL, 'make headlines có nghĩa là trở thành tâm điểm chú ý của dư luận, không phải là thiết kế tiêu đề.', 'The headline caught my attention while I ate breakfast.', NULL, 'Tiêu đề bài báo đã thu hút sự chú ý của tôi khi tôi đang ăn sáng.', '{"wordId":"headline","ukIpa":"/ˈhedlaɪn/","usIpa":"/ˈhedlaɪn/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"the title of a news report","vi":"tiêu đề tin tức; đầu đề báo"},{"pos":"v.","en":"to be the main news story or featured performer","vi":"trở thành tin chính hoặc nghệ sĩ biểu diễn chính"}],"examples":[{"en":"The headline caught my attention while I ate breakfast.","vi":"Tiêu đề bài báo đã thu hút sự chú ý của tôi khi tôi đang ăn sáng.","audioKind":"ex"},{"en":"Misleading headlines can shape public opinion before readers examine the evidence presented in a news report.","vi":"Các tiêu đề giật gân, gây hiểu lầm có thể định hình dư luận trước khi người đọc xem xét các bằng chứng được trình bày trong bản tin.","audioKind":"ex2"}],"collocations":[{"en":"front-page headline","vi":"tiêu đề trang nhất"},{"en":"make headlines","vi":"lên trang nhất; gây xôn dư luận"},{"en":"misleading headline","vi":"tiêu đề gây hiểu lầm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"make headlines có nghĩa là trở thành tâm điểm chú ý của dư luận, không phải là thiết kế tiêu đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_edit', 'en-b1-48', 'edit', '/ˈedɪt/', 'B1', 'chỉnh sửa; biên tập; cắt gọt', 'v.', 'editor (n.), editing (n.), editable (adj.), editorial (adj.)', 'Đồng nghĩa: revise', 'edit nhấn mạnh việc sửa đổi hoặc biên tập, trong khi publish mới là xuất bản hoặc phát hành.', 'I need to edit this video before dinner.', NULL, 'Tôi cần chỉnh sửa đoạn video này trước bữa tối.', '{"wordId":"edit","ukIpa":"/ˈedɪt/","usIpa":"/ˈedɪt/","cefr":"B1","topic":"media","senses":[{"pos":"v.","en":"To improve or prepare writing, images, or recordings by making changes.","vi":"chỉnh sửa; biên tập; cắt gọt"}],"examples":[{"en":"I need to edit this video before dinner.","vi":"Tôi cần chỉnh sửa đoạn video này trước bữa tối.","audioKind":"ex"},{"en":"Students should learn to edit their essays carefully, checking both the structure and the accuracy of their arguments.","vi":"Học sinh nên học cách cẩn thận chỉnh sửa bài luận của mình, kiểm tra cả cấu trúc lẫn tính chính xác của các luận điểm.","audioKind":"ex2"}],"collocations":[{"en":"edit an essay","vi":"chỉnh sửa bài luận"},{"en":"edit a video","vi":"cắt gọt video"},{"en":"edit out","vi":"cắt bỏ; xóa bớt"}],"wordFamily":["editor (n.)","editing (n.)","editable (adj.)","editorial (adj.)"],"synonyms":["revise"],"antonyms":[],"tipVi":"edit nhấn mạnh việc sửa đổi hoặc biên tập, trong khi publish mới là xuất bản hoặc phát hành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_audience', 'en-b1-48', 'audience', '/ˈɑːdiəns/', 'B1', 'khán giả; thính giả; độc giả; công chúng tiếp nhận', 'n.', NULL, NULL, 'Khán giả đông dùng large audience, không dùng many audiences.', 'The audience clapped loudly when the dancers finished.', NULL, 'Khán giả đã vỗ tay vang dội khi các vũ công biểu diễn xong.', '{"wordId":"audience","ukIpa":"/ˈɔːdiəns/","usIpa":"/ˈɑːdiəns/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"People watching or listening to a performance, speech, or programme","vi":"khán giả; thính giả"},{"pos":"n.","en":"People who read or receive particular content","vi":"độc giả; công chúng tiếp nhận"}],"examples":[{"en":"The audience clapped loudly when the dancers finished.","vi":"Khán giả đã vỗ tay vang dội khi các vũ công biểu diễn xong.","audioKind":"ex"},{"en":"Online platforms enable museums to reach a wider audience, including people who cannot visit their collections in person.","vi":"Các nền tảng trực tuyến giúp các bảo tàng tiếp cận lượng khán giả rộng lớn hơn, bao gồm cả những người không thể trực tiếp đến tham quan bộ sưu tập.","audioKind":"ex2"}],"collocations":[{"en":"a large audience","vi":"đông đảo khán giả"},{"en":"a target audience","vi":"khán giả mục tiêu"},{"en":"reach a wider audience","vi":"tiếp cận lượng công chúng rộng lớn hơn"},{"en":"audience participation","vi":"sự tham gia của khán giả"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khán giả đông dùng large audience, không dùng many audiences.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_column', 'en-b1-48', 'column', '/ˈkɑːləm/', 'B1', 'cột (dọc); chuyên mục; bài bình luận chuyên mục; mục báo; cột trụ; vật hình cột', 'n.', 'columnist (n.)', NULL, 'column là cột dọc, trong khi row là hàng ngang; phụ âm n ở cuối từ không phát âm.', 'Put the prices in the column beside each item.', NULL, 'Hãy điền các mức giá vào cột bên cạnh mỗi mặt hàng.', '{"wordId":"column","ukIpa":"/ˈkɒləm/","usIpa":"/ˈkɑːləm/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"a vertical arrangement of items or a printed page section","vi":"cột (dọc); chuyên mục"},{"pos":"n.","en":"a regular newspaper or magazine feature on a particular subject","vi":"bài bình luận chuyên mục; mục báo"},{"pos":"n.","en":"a tall upright structure, often supporting a roof","vi":"cột trụ; vật hình cột"}],"examples":[{"en":"Put the prices in the column beside each item.","vi":"Hãy điền các mức giá vào cột bên cạnh mỗi mặt hàng.","audioKind":"ex"},{"en":"The newspaper''s weekly science column helps readers understand how new discoveries may affect everyday life.","vi":"Chuyên mục khoa học hàng tuần của tờ báo giúp độc giả hiểu được những phát hiện mới có thể tác động như thế nào đến đời sống thường nhật.","audioKind":"ex2"}],"collocations":[{"en":"a column of figures","vi":"một cột số liệu"},{"en":"a newspaper column","vi":"chuyên mục báo chí"},{"en":"a stone column","vi":"cột đá"},{"en":"a column of smoke","vi":"cột khói"}],"wordFamily":["columnist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"column là cột dọc, trong khi row là hàng ngang; phụ âm n ở cuối từ không phát âm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_editor', 'en-b1-48', 'editor', '/ˈedɪtər/', 'B1', 'người biên tập; chủ biên; người dựng phim; người biên tập âm thanh; chương trình biên tập; phần mềm chỉnh sửa', 'n.', 'edit (v.), editing (n.), editorial (adj.)', NULL, 'editor có thể chỉ nhân viên biên tập hoặc phần mềm chỉnh sửa.', 'The editor suggested a clearer ending for my story.', NULL, 'Biên tập viên gợi ý cho câu chuyện của tôi một cái kết rõ ràng hơn.', '{"wordId":"editor","ukIpa":"/ˈedɪtə/","usIpa":"/ˈedɪtər/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"someone who prepares written material or manages a publication","vi":"người biên tập; chủ biên"},{"pos":"n.","en":"someone who selects and arranges recorded images or sound","vi":"người dựng phim; người biên tập âm thanh"},{"pos":"n.","en":"software used to change digital content","vi":"chương trình biên tập; phần mềm chỉnh sửa"}],"examples":[{"en":"The editor suggested a clearer ending for my story.","vi":"Biên tập viên gợi ý cho câu chuyện của tôi một cái kết rõ ràng hơn.","audioKind":"ex"},{"en":"A newspaper editor must balance the public''s right to information with respect for individual privacy.","vi":"Một biên tập viên báo chí phải cân bằng giữa quyền tiếp cận thông tin của công chúng và sự tôn trọng quyền riêng tư cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"chief editor","vi":"tổng biên tập"},{"en":"film editor","vi":"dựng phim; biên tập viên điện ảnh"},{"en":"text editor","vi":"trình soạn thảo văn bản"},{"en":"editor of a magazine","vi":"biên tập viên tạp chí"}],"wordFamily":["edit (v.)","editing (n.)","editorial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"editor có thể chỉ nhân viên biên tập hoặc phần mềm chỉnh sửa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_podcast', 'en-b1-48', 'podcast', '/ˈpɑːdkæst/', 'B1', 'chương trình phát thanh trực tuyến; podcast; sản xuất và phát sóng podcast', 'n.', 'podcaster (n.), podcasting (n.)', NULL, 'Nghe podcast dùng listen to a podcast, nhớ đừng quên giới từ to.', 'I listen to a cooking podcast while making dinner.', NULL, 'Tôi nghe một chương trình podcast về nấu ăn trong lúc chuẩn bị bữa tối.', '{"wordId":"podcast","ukIpa":"/ˈpɒdkɑːst/","usIpa":"/ˈpɑːdkæst/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"An online audio programme available to stream or download.","vi":"chương trình phát thanh trực tuyến; podcast"},{"pos":"v.","en":"To produce and distribute an online audio programme.","vi":"sản xuất và phát sóng podcast"}],"examples":[{"en":"I listen to a cooking podcast while making dinner.","vi":"Tôi nghe một chương trình podcast về nấu ăn trong lúc chuẩn bị bữa tối.","audioKind":"ex"},{"en":"Educational podcasts allow learners to explore complex subjects while travelling or completing routine household tasks.","vi":"Các chương trình podcast giáo dục giúp người học khám phá các chủ đề phức tạp khi đang di chuyển hoặc làm việc nhà.","audioKind":"ex2"}],"collocations":[{"en":"listen to a podcast","vi":"nghe podcast"},{"en":"podcast episode","vi":"tập podcast"},{"en":"host a podcast","vi":"dẫn chương trình podcast"},{"en":"subscribe to a podcast","vi":"đăng ký theo dõi podcast"}],"wordFamily":["podcaster (n.)","podcasting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghe podcast dùng listen to a podcast, nhớ đừng quên giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_statement', 'en-b1-48', 'statement', '/ˈsteɪtmənt/', 'B1', 'lời phát biểu; ý kiến; tuyên bố; thông cáo; báo cáo tài chính; bảng sao kê', 'n.', 'state (v.), restate (v.)', NULL, 'Khi mang nghĩa "chúng ta phát biểu", từ này là danh từ đếm được; bảng sao kê ngân hàng cũng dùng "statement".', 'Her statement about the broken window surprised everyone.', NULL, 'Lời phát biểu của cô ấy về ô cửa sổ bị vỡ đã khiến tất cả mọi người ngạc nhiên.', '{"wordId":"statement","ukIpa":"/ˈsteɪtmənt/","usIpa":"/ˈsteɪtmənt/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"something said or written to express information or an opinion","vi":"lời phát biểu; ý kiến"},{"pos":"n.","en":"a formal public announcement about a particular matter","vi":"tuyên bố; thông cáo"},{"pos":"n.","en":"a record showing financial transactions over a period","vi":"báo cáo tài chính; bảng sao kê"}],"examples":[{"en":"Her statement about the broken window surprised everyone.","vi":"Lời phát biểu của cô ấy về ô cửa sổ bị vỡ đã khiến tất cả mọi người ngạc nhiên.","audioKind":"ex"},{"en":"The council issued a statement explaining how the proposed transport scheme would benefit residents with limited mobility.","vi":"Hội đồng đã đưa ra một bản tuyên bố giải thích cách mà kế hoạch giao thông đề xuất sẽ mang lại lợi ích cho cư dân có khả năng đi lại hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"make a statement","vi":"đưa ra phát biểu"},{"en":"issue a statement","vi":"đưa ra tuyên bố"},{"en":"a bank statement","vi":"bảng sao kê ngân hàng"},{"en":"a witness statement","vi":"lời khai của nhân chứng"}],"wordFamily":["state (v.)","restate (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa \"chúng ta phát biểu\", từ này là danh từ đếm được; bảng sao kê ngân hàng cũng dùng \"statement\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_announcement', 'en-b1-48', 'announcement', '/əˈnaʊnsmənt/', 'B1', 'thông báo; lời công bố', 'n.', 'announce (v.), announcer (n.)', 'Đồng nghĩa: notice, statement', 'Khi diễn tả hành động phát đi thông báo, ta dùng cụm "make an announcement".', 'We heard an announcement about our train being delayed.', NULL, 'Chúng tôi nghe thấy một thông báo về việc chuyến tàu của mình bị hoãn.', '{"wordId":"announcement","ukIpa":"/əˈnaʊnsmənt/","usIpa":"/əˈnaʊnsmənt/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"a public statement giving people information or news","vi":"thông báo; lời công bố"}],"examples":[{"en":"We heard an announcement about our train being delayed.","vi":"Chúng tôi nghe thấy một thông báo về việc chuyến tàu của mình bị hoãn.","audioKind":"ex"},{"en":"The government''s announcement of additional education funding was welcomed by teachers and parents.","vi":"Việc chính phủ công bố rót thêm vốn giáo dục đã được các giáo viên và phụ huynh chào đón.","audioKind":"ex2"}],"collocations":[{"en":"make an announcement","vi":"đưa ra thông báo"},{"en":"official announcement","vi":"thông báo chính thức"},{"en":"public announcement","vi":"thông cáo công khai"}],"wordFamily":["announce (v.)","announcer (n.)"],"synonyms":["notice","statement"],"antonyms":[],"tipVi":"Khi diễn tả hành động phát đi thông báo, ta dùng cụm \"make an announcement\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_booklet', 'en-b1-48', 'booklet', '/ˈbʊklət/', 'B1', 'sách mỏng; sách nhỏ; tập tài liệu', 'n.', 'book (n.)', 'Đồng nghĩa: brochure', 'Hậu tố -let thường chỉ kích thước nhỏ; booklet là một cuốn sách mỏng gọn.', 'The nurse gave me a booklet about healthy eating.', NULL, 'Cô y tá đã đưa cho tôi một cuốn sách nhỏ về chế độ ăn uống lành mạnh.', '{"wordId":"booklet","ukIpa":"/ˈbʊklət/","usIpa":"/ˈbʊklət/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"a small, thin book, usually containing practical information","vi":"sách mỏng; sách nhỏ; tập tài liệu"}],"examples":[{"en":"The nurse gave me a booklet about healthy eating.","vi":"Cô y tá đã đưa cho tôi một cuốn sách nhỏ về chế độ ăn uống lành mạnh.","audioKind":"ex"},{"en":"An illustrated booklet can make essential health advice more accessible to patients with limited reading skills.","vi":"Một cuốn sách nhỏ có minh họa có thể giúp những bệnh nhân có khả năng đọc hạn chế tiếp cận dễ dàng hơn với các lời khuyên y tế quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"an information booklet","vi":"tài liệu thông tin"},{"en":"an instruction booklet","vi":"sách hướng dẫn sử dụng"},{"en":"a booklet on","vi":"tập tài liệu về"}],"wordFamily":["book (n.)"],"synonyms":["brochure"],"antonyms":[],"tipVi":"Hậu tố -let thường chỉ kích thước nhỏ; booklet là một cuốn sách mỏng gọn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spread', 'en-b1-48', 'spread', '/spred/', 'B1', 'lan truyền; truyền bá; trải ra; căng ra; phết; sự lan rộng; sự truyền bá', 'v.', NULL, NULL, 'Dạng quá khứ và phân từ hai của spread đều giữ nguyên là spread.', 'She spread a blanket under the tree for our picnic.', NULL, 'Cô ấy trải một tấm chăn dưới gốc cây để chúng tôi tổ chức dã ngoại.', '{"wordId":"spread","ukIpa":"/spred/","usIpa":"/spred/","cefr":"B1","topic":"media","senses":[{"pos":"v.","en":"To reach, or make something reach, more people or places","vi":"lan truyền; truyền bá"},{"pos":"v.","en":"To open something out or cover a surface with something","vi":"trải ra; căng ra; phết"},{"pos":"n.","en":"The process of reaching a wider area or more people","vi":"sự lan rộng; sự truyền bá"}],"examples":[{"en":"She spread a blanket under the tree for our picnic.","vi":"Cô ấy trải một tấm chăn dưới gốc cây để chúng tôi tổ chức dã ngoại.","audioKind":"ex"},{"en":"The rapid spread of false information online highlights the importance of teaching critical reading skills in schools.","vi":"Sự lan truyền nhanh chóng của thông tin sai lệch trên mạng nhấn mạnh tầm quan trọng của việc giảng dạy kỹ năng đọc phản biện tại các trường học.","audioKind":"ex2"}],"collocations":[{"en":"spread awareness","vi":"lan tỏa sự nhận thức"},{"en":"spread rapidly","vi":"lan truyền nhanh chóng"},{"en":"spread butter","vi":"phết bơ"},{"en":"the spread of disease","vi":"sự lây lan của dịch bệnh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai của spread đều giữ nguyên là spread.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cassette', 'en-b1-48', 'cassette', '/kəˈset/', 'B1', 'băng cát-sét; băng ghi âm', 'n.', NULL, 'Đồng nghĩa: tape', 'Lưu ý trọng âm rơi vào âm tiết thứ hai; máy phát gọi là cassette player.', 'We found an old cassette of songs in the cupboard.', NULL, 'Chúng tôi đã tìm thấy một cuộn băng cát-sét cũ chứa các bài hát trong tủ.', '{"wordId":"cassette","ukIpa":"/kəˈset/","usIpa":"/kəˈset/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"a plastic case containing magnetic tape for recording sound","vi":"băng cát-sét; băng ghi âm"}],"examples":[{"en":"We found an old cassette of songs in the cupboard.","vi":"Chúng tôi đã tìm thấy một cuộn băng cát-sét cũ chứa các bài hát trong tủ.","audioKind":"ex"},{"en":"Before digital streaming became widespread, many language learners used cassette recordings to practise listening at home.","vi":"Trước khi dịch vụ phát trực tuyến kỹ thuật số trở nên phổ biến, nhiều người học ngoại ngữ đã sử dụng băng cát-sét để luyện nghe tại nhà.","audioKind":"ex2"}],"collocations":[{"en":"cassette tape","vi":"băng cát-sét"},{"en":"cassette player","vi":"máy phát băng cát-sét"},{"en":"audio cassette","vi":"băng ghi âm"}],"wordFamily":[],"synonyms":["tape"],"antonyms":[],"tipVi":"Lưu ý trọng âm rơi vào âm tiết thứ hai; máy phát gọi là cassette player.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_channel', 'en-b1-48', 'channel', '/ˈtʃænəl/', 'B1', 'kênh truyền hình; đường truyền, phương tiện; luồng nước; eo biển; dồn (năng lượng, tiền bạc, tài nguyên) vào', 'n.', NULL, NULL, 'Động từ thường dùng cấu trúc channel sth into sth, mang ý nghĩa phân bổ hoặc dồn nguồn lực vào một việc cụ thể.', 'Could you change the channel before the film starts?', NULL, 'Bạn có thể đổi kênh trước khi bộ phim bắt đầu được không?', '{"wordId":"channel","ukIpa":"/ˈtʃænəl/","usIpa":"/ˈtʃænəl/","cefr":"B1","topic":"media","senses":[{"pos":"n.","en":"A television service or route for communicating and distributing things","vi":"kênh truyền hình; đường truyền, phương tiện"},{"pos":"n.","en":"A passage of water connecting areas or allowing boats through","vi":"luồng nước; eo biển"},{"pos":"v.","en":"Direct energy, money, or resources towards a particular purpose","vi":"dồn (năng lượng, tiền bạc, tài nguyên) vào"}],"examples":[{"en":"Could you change the channel before the film starts?","vi":"Bạn có thể đổi kênh trước khi bộ phim bắt đầu được không?","audioKind":"ex"},{"en":"Governments should channel more funding into public transport to reduce congestion and improve access to employment.","vi":"Chính phủ nên đầu tư nhiều ngân sách hơn vào hệ thống giao thông công cộng để giảm thiểu tình trạng ùn tắc và cải thiện khả năng tiếp cận việc làm.","audioKind":"ex2"}],"collocations":[{"en":"a television channel","vi":"kênh truyền hình"},{"en":"communication channels","vi":"kênh giao tiếp"},{"en":"a shipping channel","vi":"luồng hàng hải"},{"en":"channel resources into","vi":"dồn tài nguyên vào"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường dùng cấu trúc channel sth into sth, mang ý nghĩa phân bổ hoặc dồn nguồn lực vào một việc cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_48_1', 'en-b1-48', 'Cách dùng “channel” (n.) — kênh truyền hình; đường truyền, phương tiện', 'a television channel  ·  communication channels  ·  a shipping channel', 'Động từ thường dùng cấu trúc channel sth into sth, mang ý nghĩa phân bổ hoặc dồn nguồn lực vào một việc cụ thể.', NULL, '[{"hanzi":"Could you change the channel before the film starts?","pinyin":"","meaning":"Bạn có thể đổi kênh trước khi bộ phim bắt đầu được không?"},{"hanzi":"Governments should channel more funding into public transport to reduce congestion and improve access to employment.","pinyin":"","meaning":"Chính phủ nên đầu tư nhiều ngân sách hơn vào hệ thống giao thông công cộng để giảm thiểu tình trạng ùn tắc và cải thiện khả năng tiếp cận việc làm."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_48_2', 'en-b1-48', 'Cách dùng “statement” (n.) — lời phát biểu; ý kiến', 'make a statement  ·  issue a statement  ·  a bank statement', 'Khi mang nghĩa "chúng ta phát biểu", từ này là danh từ đếm được; bảng sao kê ngân hàng cũng dùng "statement".', 'Họ từ (Word Family): state (v.), restate (v.)', '[{"hanzi":"Her statement about the broken window surprised everyone.","pinyin":"","meaning":"Lời phát biểu của cô ấy về ô cửa sổ bị vỡ đã khiến tất cả mọi người ngạc nhiên."},{"hanzi":"The council issued a statement explaining how the proposed transport scheme would benefit residents with limited mobility.","pinyin":"","meaning":"Hội đồng đã đưa ra một bản tuyên bố giải thích cách mà kế hoạch giao thông đề xuất sẽ mang lại lợi ích cho cư dân có khả năng đi lại hạn chế."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_48_3', 'en-b1-48', 'Cách dùng “headline” (n.) — tiêu đề tin tức; đầu đề báo', 'front-page headline  ·  make headlines  ·  misleading headline', 'make headlines có nghĩa là trở thành tâm điểm chú ý của dư luận, không phải là thiết kế tiêu đề.', NULL, '[{"hanzi":"The headline caught my attention while I ate breakfast.","pinyin":"","meaning":"Tiêu đề bài báo đã thu hút sự chú ý của tôi khi tôi đang ăn sáng."},{"hanzi":"Misleading headlines can shape public opinion before readers examine the evidence presented in a news report.","pinyin":"","meaning":"Các tiêu đề giật gân, gây hiểu lầm có thể định hình dư luận trước khi người đọc xem xét các bằng chứng được trình bày trong bản tin."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_48_4', 'en-b1-48', 'Cách dùng “edit” (v.) — chỉnh sửa; biên tập; cắt gọt', 'edit an essay  ·  edit a video  ·  edit out', 'edit nhấn mạnh việc sửa đổi hoặc biên tập, trong khi publish mới là xuất bản hoặc phát hành.', 'Họ từ (Word Family): editor (n.), editing (n.), editable (adj.), editorial (adj.) | Đồng nghĩa: revise', '[{"hanzi":"I need to edit this video before dinner.","pinyin":"","meaning":"Tôi cần chỉnh sửa đoạn video này trước bữa tối."},{"hanzi":"Students should learn to edit their essays carefully, checking both the structure and the accuracy of their arguments.","pinyin":"","meaning":"Học sinh nên học cách cẩn thận chỉnh sửa bài luận của mình, kiểm tra cả cấu trúc lẫn tính chính xác của các luận điểm."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_48_1', 'en-b1-48', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_1_1', 'ten_b1_48_1', 'flyer', 'Someone handed me a flyer outside the swimming pool.', 'Someone handed me a flyer outside the swimming pool.', '/ˈflaɪər/', 'Ai đó đã đưa cho tôi một tờ rơi ở bên ngoài hồ bơi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_1_2', 'ten_b1_48_1', 'dialog', 'The actors practised their dialog before stepping onto the stage.', 'The actors practised their dialog before stepping onto the stage.', '/ˈdaɪəlɔːɡ/', 'Các diễn viên đã luyện tập lời thoại trước khi bước lên sân khấu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_1_3', 'ten_b1_48_1', 'series', 'A series of small delays made us miss lunch.', 'A series of small delays made us miss lunch.', '/ˈsɪriːz/', 'Một chuỗi những sự cố chậm trễ nhỏ đã khiến chúng tôi lỡ bữa trưa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_1_4', 'ten_b1_48_1', 'celebrity', 'A celebrity stopped outside the theatre to greet fans.', 'A celebrity stopped outside the theatre to greet fans.', '/səˈlebrəti/', 'Một ngôi sao nổi tiếng dừng chân bên ngoài nhà hát để chào người hâm mộ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_1_5', 'ten_b1_48_1', 'headline', 'The headline caught my attention while I ate breakfast.', 'The headline caught my attention while I ate breakfast.', '/ˈhedlaɪn/', 'Tiêu đề bài báo đã thu hút sự chú ý của tôi khi tôi đang ăn sáng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_1_6', 'ten_b1_48_1', 'edit', 'I need to edit this video before dinner.', 'I need to edit this video before dinner.', '/ˈedɪt/', 'Tôi cần chỉnh sửa đoạn video này trước bữa tối.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_1_7', 'ten_b1_48_1', 'audience', 'The audience clapped loudly when the dancers finished.', 'The audience clapped loudly when the dancers finished.', '/ˈɑːdiəns/', 'Khán giả đã vỗ tay vang dội khi các vũ công biểu diễn xong.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_1_8', 'ten_b1_48_1', 'column', 'Put the prices in the column beside each item.', 'Put the prices in the column beside each item.', '/ˈkɑːləm/', 'Hãy điền các mức giá vào cột bên cạnh mỗi mặt hàng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_48_1_1', 'en-b1-48', 'ten_b1_48_1', 'listening', 'listening', 'Someone handed me a flyer outside the swimming pool.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ai đó đã đưa cho tôi một tờ rơi ở bên ngoài hồ bơi.","Khán giả đã vỗ tay vang dội khi các vũ công biểu diễn xong.","Chúng tôi đã tìm thấy một cuộn băng cát-sét cũ chứa các bài hát trong tủ.","Một chuỗi những sự cố chậm trễ nhỏ đã khiến chúng tôi lỡ bữa trưa."]'::jsonb, 0, 'Someone handed me a flyer outside the swimming pool. → Ai đó đã đưa cho tôi một tờ rơi ở bên ngoài hồ bơi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_48_1_2', 'en-b1-48', 'ten_b1_48_1', 'listening', 'listening', 'The actors practised their dialog before stepping onto the stage.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn có thể đổi kênh trước khi bộ phim bắt đầu được không?","Hãy điền các mức giá vào cột bên cạnh mỗi mặt hàng.","Các diễn viên đã luyện tập lời thoại trước khi bước lên sân khấu.","Tôi nghe một chương trình podcast về nấu ăn trong lúc chuẩn bị bữa tối."]'::jsonb, 2, 'The actors practised their dialog before stepping onto the stage. → Các diễn viên đã luyện tập lời thoại trước khi bước lên sân khấu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_48_1_3', 'en-b1-48', 'ten_b1_48_1', 'listening', 'listening', 'A series of small delays made us miss lunch.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Lời phát biểu của cô ấy về ô cửa sổ bị vỡ đã khiến tất cả mọi người ngạc nhiên.","Một chuỗi những sự cố chậm trễ nhỏ đã khiến chúng tôi lỡ bữa trưa.","Tôi cần chỉnh sửa đoạn video này trước bữa tối.","Tiêu đề bài báo đã thu hút sự chú ý của tôi khi tôi đang ăn sáng."]'::jsonb, 1, 'A series of small delays made us miss lunch. → Một chuỗi những sự cố chậm trễ nhỏ đã khiến chúng tôi lỡ bữa trưa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_48_2', 'en-b1-48', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_2_1', 'ten_b1_48_2', 'flyer', 'Local charities often distribute flyers to encourage residents to participate in community recycling schemes.', 'Local charities often distribute flyers to encourage residents to participate in community recycling schemes.', '/ˈflaɪər/', 'Các tổ chức từ thiện địa phương thường phát tờ rơi để khuyến khích cư dân tham gia các chương trình tái chế của cộng đồng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_2_2', 'ten_b1_48_2', 'dialog', 'Open dialog between local authorities and residents can help resolve disagreements about new housing developments.', 'Open dialog between local authorities and residents can help resolve disagreements about new housing developments.', '/ˈdaɪəlɔːɡ/', 'Cuộc đối thoại cởi mở giữa chính quyền địa phương và cư dân có thể giúp giải quyết những bất đồng về các dự án phát triển nhà ở mới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_2_3', 'ten_b1_48_2', 'series', 'The university introduced a series of workshops to help students evaluate information found on social media.', 'The university introduced a series of workshops to help students evaluate information found on social media.', '/ˈsɪriːz/', 'Trường đại học đã giới thiệu một loạt các buổi hội thảo nhằm giúp sinh viên đánh giá thông tin tìm thấy trên mạng xã hội.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_2_4', 'ten_b1_48_2', 'celebrity', 'Celebrity endorsements can influence young consumers, so advertisements should clearly distinguish personal opinions from paid promotion.', 'Celebrity endorsements can influence young consumers, so advertisements should clearly distinguish personal opinions from paid promotion.', '/səˈlebrəti/', 'Việc người nổi tiếng quảng cáo nhãn hàng có thể tác động đến người tiêu dùng trẻ tuổi, vì vậy các quảng cáo nên phân biệt rõ ràng giữa quan điểm cá nhân và hoạt động tài trợ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_2_5', 'ten_b1_48_2', 'headline', 'Misleading headlines can shape public opinion before readers examine the evidence presented in a news report.', 'Misleading headlines can shape public opinion before readers examine the evidence presented in a news report.', '/ˈhedlaɪn/', 'Các tiêu đề giật gân, gây hiểu lầm có thể định hình dư luận trước khi người đọc xem xét các bằng chứng được trình bày trong bản tin.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_48_2_6', 'ten_b1_48_2', 'edit', 'Students should learn to edit their essays carefully, checking both the structure and the accuracy of their arguments.', 'Students should learn to edit their essays carefully, checking both the structure and the accuracy of their arguments.', '/ˈedɪt/', 'Học sinh nên học cách cẩn thận chỉnh sửa bài luận của mình, kiểm tra cả cấu trúc lẫn tính chính xác của các luận điểm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_48_2_1', 'en-b1-48', 'ten_b1_48_2', 'listening', 'listening', 'Local charities often distribute flyers to encourage residents to participate in community recycling schemes.', NULL, 'Trong câu vừa nghe, từ “flyer” mang nghĩa nào sau đây?', '["tờ rơi quảng cáo","thám tử; trinh thám; cảnh sát điều tra","chủ yếu; quan trọng hàng đầu; chính","nhạc cụ"]'::jsonb, 0, '“flyer” (/ˈflaɪər/): tờ rơi quảng cáo. Câu đầy đủ: Local charities often distribute flyers to encourage residents to participate in community recycling schemes.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_48_2_2', 'en-b1-48', 'ten_b1_48_2', 'listening', 'listening', 'Open dialog between local authorities and residents can help resolve disagreements about new housing developments.', NULL, 'Trong câu vừa nghe, từ “dialog” mang nghĩa nào sau đây?', '["tầng của một tòa nhà","đối thoại; lời thoại","mi-li-mét","đèn biển; ngọn hải đăng"]'::jsonb, 1, '“dialog” (/ˈdaɪəlɔːɡ/): đối thoại; lời thoại. Câu đầy đủ: Open dialog between local authorities and residents can help resolve disagreements about new housing developments.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
