INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_48_2', 'en-b1-48', NULL, 'comprehensive_test', 'listening', 'The actors practised their dialog before stepping onto the stage.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy điền các mức giá vào cột bên cạnh mỗi mặt hàng.","Tôi cần chỉnh sửa đoạn video này trước bữa tối.","Lời phát biểu của cô ấy về ô cửa sổ bị vỡ đã khiến tất cả mọi người ngạc nhiên.","Các diễn viên đã luyện tập lời thoại trước khi bước lên sân khấu."]'::jsonb, 3, 'The actors practised their dialog before stepping onto the stage. → Các diễn viên đã luyện tập lời thoại trước khi bước lên sân khấu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_48_3', 'en-b1-48', NULL, 'comprehensive_test', 'listening', 'series', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["con ngỗng","loạt; chuỗi; dải (các sự việc, sự kiện liên tiếp)","gối tựa; đệm lót","trách nhiệm; bổn phận"]'::jsonb, 1, 'series (/ˈsɪriːz/) → loạt; chuỗi; dải (các sự việc, sự kiện liên tiếp); series; bộ phim truyền hình dài tập; bộ sách', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_48_4', 'en-b1-48', NULL, 'comprehensive_test', 'listening', 'A celebrity stopped outside the theatre to greet fans.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy điền các mức giá vào cột bên cạnh mỗi mặt hàng.","Cô y tá đã đưa cho tôi một cuốn sách nhỏ về chế độ ăn uống lành mạnh.","Tôi nghe một chương trình podcast về nấu ăn trong lúc chuẩn bị bữa tối.","Một ngôi sao nổi tiếng dừng chân bên ngoài nhà hát để chào người hâm mộ."]'::jsonb, 3, 'A celebrity stopped outside the theatre to greet fans. → Một ngôi sao nổi tiếng dừng chân bên ngoài nhà hát để chào người hâm mộ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
