INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_48_6', 'en-b1-48', NULL, 'comprehensive_test', 'listening', 'I need to edit this video before dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô y tá đã đưa cho tôi một cuốn sách nhỏ về chế độ ăn uống lành mạnh.","Cô ấy trải một tấm chăn dưới gốc cây để chúng tôi tổ chức dã ngoại.","Tôi cần chỉnh sửa đoạn video này trước bữa tối.","Hãy điền các mức giá vào cột bên cạnh mỗi mặt hàng."]'::jsonb, 2, 'I need to edit this video before dinner. → Tôi cần chỉnh sửa đoạn video này trước bữa tối.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
