INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_48_18', 'en-b1-48', NULL, 'comprehensive_test', 'reading', NULL, 'Local charities often distribute flyers to encourage residents to participate in community recycling schemes.', 'Dựa vào câu trên, từ “flyer” có nghĩa phù hợp nhất là gì?', '["thói quen; công việc thường ngày; lịch trình thường nhật","lời giải thích; sự giải thích","tờ rơi quảng cáo","sự giao hàng; sự phân phát"]'::jsonb, 2, 'flyer: tờ rơi quảng cáo; hành khách đi máy bay. Dịch cả câu: Các tổ chức từ thiện địa phương thường phát tờ rơi để khuyến khích cư dân tham gia các chương trình tái chế của cộng đồng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_48_19', 'en-b1-48', NULL, 'comprehensive_test', 'reading', NULL, 'Open dialog between local authorities and residents can help resolve disagreements about new housing developments.', 'Dựa vào câu trên, từ “dialog” có nghĩa phù hợp nhất là gì?', '["tàu phà; phà","nhà báo; phóng viên","tầng hầm; phòng dưới mặt đất","đối thoại; lời thoại"]'::jsonb, 3, 'dialog: đối thoại; lời thoại; cuộc đối thoại; sự trao đổi ý kiến; hộp thoại. Dịch cả câu: Cuộc đối thoại cởi mở giữa chính quyền địa phương và cư dân có thể giúp giải quyết những bất đồng về các dự án phát triển nhà ở mới.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_48_20', 'en-b1-48', NULL, 'comprehensive_test', 'reading', NULL, 'The university introduced a series of workshops to help students evaluate information found on social media.', 'Dựa vào câu trên, từ “series” có nghĩa phù hợp nhất là gì?', '["đã lên kế hoạch; dự kiến trước","loạt; chuỗi; dải (các sự việc, sự kiện liên tiếp)","bỏ phiếu; biểu quyết","nguồn; nguồn gốc"]'::jsonb, 1, 'series: loạt; chuỗi; dải (các sự việc, sự kiện liên tiếp); series; bộ phim truyền hình dài tập; bộ sách. Dịch cả câu: Trường đại học đã giới thiệu một loạt các buổi hội thảo nhằm giúp sinh viên đánh giá thông tin tìm thấy trên mạng xã hội.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_48_21', 'en-b1-48', NULL, 'comprehensive_test', 'reading', NULL, 'Celebrity endorsements can influence young consumers, so advertisements should clearly distinguish personal opinions from paid promotion.', 'Dựa vào câu trên, từ “celebrity” có nghĩa phù hợp nhất là gì?', '["người nổi tiếng; ngôi sao","thám tử; trinh thám; cảnh sát điều tra","sắt; chất sắt","cơ bản; vỡ lòng"]'::jsonb, 0, 'celebrity: người nổi tiếng; ngôi sao; sự nổi tiếng; danh tiếng. Dịch cả câu: Việc người nổi tiếng quảng cáo nhãn hàng có thể tác động đến người tiêu dùng trẻ tuổi, vì vậy các quảng cáo nên phân biệt rõ ràng giữa quan điểm cá nhân và hoạt động tài trợ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_48_22', 'en-b1-48', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lan truyền; truyền bá”', '["spread","produce","stressed","session"]'::jsonb, 0, 'lan truyền; truyền bá → spread (/spred/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_48_23', 'en-b1-48', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “băng cát-sét; băng ghi âm”', '["cassette","cough","lively","handle"]'::jsonb, 0, 'băng cát-sét; băng ghi âm → cassette (/kəˈset/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_48_24', 'en-b1-48', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kênh truyền hình; đường truyền, phương tiện”', '["float","block","eventually","channel"]'::jsonb, 3, 'kênh truyền hình; đường truyền, phương tiện → channel (/ˈtʃænəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-49', 'en', 'Bài 49: Đời sống hằng ngày (1) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3049, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sour', 'en-b1-49', 'sour', '/ˈsaʊər/', 'B1', 'chua (có vị gắt như chanh); ôi thiu, chua (có mùi vị khó chịu do bị hỏng); trở nên kém vui, làm xẩu đi (mối quan hệ)', 'adj.', 'sourness (n.), sourly (adv.)', 'Trái nghĩa: sweet', 'Cụm go sour có thể chỉ thức ăn bị biến chất, hoặc dùng để chỉ mối quan hệ trở nên tồi tệ hơn.', 'These grapes are too sour for my taste.', NULL, 'Những quả nho này quá chua đối với khẩu vị của tôi.', '{"wordId":"sour","ukIpa":"/ˈsaʊə/","usIpa":"/ˈsaʊər/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Having a sharp taste like a lemon.","vi":"chua (có vị gắt như chanh)"},{"pos":"adj.","en":"Having an unpleasant taste or smell after becoming spoiled.","vi":"ôi thiu, chua (có mùi vị khó chịu do bị hỏng)"},{"pos":"v.","en":"To become less pleasant or make a relationship worse.","vi":"trở nên kém vui, làm xẩu đi (mối quan hệ)"}],"examples":[{"en":"These grapes are too sour for my taste.","vi":"Những quả nho này quá chua đối với khẩu vị của tôi.","audioKind":"ex"},{"en":"Disagreements over shared resources can sour relations between neighbouring countries and delay important environmental projects.","vi":"Những bất đồng về nguồn lực chung có thể làm xấu đi mối quan hệ giữa các quốc gia láng giềng và làm trì hoãn các dự án môi trường quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"sour taste","vi":"vị chua"},{"en":"go sour","vi":"hóa chua, biến chất"},{"en":"sour relations","vi":"làm sứt mẻ quan hệ"}],"wordFamily":["sourness (n.)","sourly (adv.)"],"synonyms":[],"antonyms":["sweet"],"tipVi":"Cụm go sour có thể chỉ thức ăn bị biến chất, hoặc dùng để chỉ mối quan hệ trở nên tồi tệ hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indoors', 'en-b1-49', 'indoors', '/ˌɪnˈdɔːrz/', 'B1', 'ở trong nhà, vào trong nhà (bên trong một tòa nhà)', 'adv.', 'indoor (adj.)', 'Đồng nghĩa: inside · Trái nghĩa: outdoors', 'Indoors là trạng từ; khi cần bổ nghĩa cho danh từ hãy dùng indoor, ví dụ như indoor sports.', 'We stayed indoors and played chess during the storm.', NULL, 'Chúng tôi ở trong nhà và chơi cờ trong suốt cơn bão.', '{"wordId":"indoors","ukIpa":"/ˌɪnˈdɔːz/","usIpa":"/ˌɪnˈdɔːrz/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"Inside a building, or into a building.","vi":"ở trong nhà, vào trong nhà (bên trong một tòa nhà)"}],"examples":[{"en":"We stayed indoors and played chess during the storm.","vi":"Chúng tôi ở trong nhà và chơi cờ trong suốt cơn bão.","audioKind":"ex"},{"en":"Children who spend most of their time indoors may have fewer opportunities for physical activity.","vi":"Trẻ em dành phần lớn thời gian ở trong nhà có thể có ít cơ hội tham gia các hoạt động thể chất hơn.","audioKind":"ex2"}],"collocations":[{"en":"stay indoors","vi":"ở trong nhà"},{"en":"go indoors","vi":"đi vào nhà"},{"en":"keep pets indoors","vi":"nuôi thú cưng trong nhà"}],"wordFamily":["indoor (adj.)"],"synonyms":["inside"],"antonyms":["outdoors"],"tipVi":"Indoors là trạng từ; khi cần bổ nghĩa cho danh từ hãy dùng indoor, ví dụ như indoor sports.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_routine', 'en-b1-49', 'routine', '/ruːˈtiːn/', 'B1', 'thói quen; công việc thường ngày; lịch trình thường nhật; thường lệ; thông lệ; theo quy chuẩn; bài biểu diễn; bài tập luyện theo động tác cố định', 'n.', 'routinely (adv.)', NULL, 'Danh từ chỉ thói quen/lịch trình; tính từ chỉ việc được thực hiện theo lệ thường.', 'A short walk is part of my morning routine.', NULL, 'Một chuyến đi dạo ngắn là một phần trong thói quen buổi sáng của tôi.', '{"wordId":"routine","ukIpa":"/ruːˈtiːn/","usIpa":"/ruːˈtiːn/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A regular way of doing things in a particular order.","vi":"thói quen; công việc thường ngày; lịch trình thường nhật"},{"pos":"adj.","en":"Done regularly as part of the usual process.","vi":"thường lệ; thông lệ; theo quy chuẩn"},{"pos":"n.","en":"A planned sequence of movements in a performance.","vi":"bài biểu diễn; bài tập luyện theo động tác cố định"}],"examples":[{"en":"A short walk is part of my morning routine.","vi":"Một chuyến đi dạo ngắn là một phần trong thói quen buổi sáng của tôi.","audioKind":"ex"},{"en":"Maintaining a regular sleep routine can improve concentration and help students cope with academic pressure.","vi":"Duy trì thói quen ngủ nghỉ đều đặn có thể cải thiện khả năng tập trung và giúp học sinh đối phó với áp lực học tập.","audioKind":"ex2"}],"collocations":[{"en":"daily routine","vi":"thói quen hàng ngày; sinh hoạt thường nhật"},{"en":"routine check","vi":"kiểm tra định kỳ"},{"en":"exercise routine","vi":"bài tập thể dục theo động tác"},{"en":"establish a routine","vi":"thiết lập nề nếp"}],"wordFamily":["routinely (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ thói quen/lịch trình; tính từ chỉ việc được thực hiện theo lệ thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_switch', 'en-b1-49', 'switch', '/swɪtʃ/', 'B1', 'công tắc điện; chuyển đổi; thay đổi; sự chuyển đổi; sự thay đổi', 'n.', NULL, NULL, 'Cụm switch on/off dùng cho việc bật/tắt thiết bị; switch to dùng khi chuyển sang đối tượng hoặc phương án mới.', 'The light switch is just behind the kitchen door.', NULL, 'Công tắc đèn nằm ngay phía sau cửa phòng bếp.', '{"wordId":"switch","ukIpa":"/swɪtʃ/","usIpa":"/swɪtʃ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A device used to turn equipment on or off.","vi":"công tắc điện"},{"pos":"v.","en":"To change from one thing to another.","vi":"chuyển đổi; thay đổi"},{"pos":"n.","en":"A change from one thing to another.","vi":"sự chuyển đổi; sự thay đổi"}],"examples":[{"en":"The light switch is just behind the kitchen door.","vi":"Công tắc đèn nằm ngay phía sau cửa phòng bếp.","audioKind":"ex"},{"en":"Governments can encourage households to switch to renewable energy by offering financial support.","vi":"Chính phủ có thể khuyến khích các hộ gia đình chuyển sang sử dụng năng lượng tái tạo bằng cách cung cấp hỗ trợ tài chính.","audioKind":"ex2"}],"collocations":[{"en":"light switch","vi":"công tắc đèn"},{"en":"switch off","vi":"tắt"},{"en":"switch to","vi":"chuyển sang"},{"en":"make the switch","vi":"thực hiện sự thay đổi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm switch on/off dùng cho việc bật/tắt thiết bị; switch to dùng khi chuyển sang đối tượng hoặc phương án mới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_inch', 'en-b1-49', 'inch', '/ɪntʃ/', 'B1', 'inh-sơ (đơn vị đo chiều dài bằng 2,54 cm); nhích dần; di chuyển rất chậm qua một khoảng cách ngắn', 'n.', NULL, NULL, 'Ký hiệu của inh-sơ là "; khi dùng làm động từ, nó thể hiện hành động di chuyển từng chút một.', 'The shelf is an inch wider than the cupboard.', NULL, 'Cái kệ rộng hơn cái tủ một inh-sơ.', '{"wordId":"inch","ukIpa":"/ɪntʃ/","usIpa":"/ɪntʃ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a unit of length equal to 2.54 centimetres","vi":"inh-sơ (đơn vị đo chiều dài bằng 2,54 cm)"},{"pos":"v.","en":"to move very slowly over a short distance","vi":"nhích dần; di chuyển rất chậm qua một khoảng cách ngắn"}],"examples":[{"en":"The shelf is an inch wider than the cupboard.","vi":"Cái kệ rộng hơn cái tủ một inh-sơ.","audioKind":"ex"},{"en":"During rush hour, buses inch through crowded streets, making public transport less attractive to commuters.","vi":"Vào giờ cao điểm, các xe buýt nhích từng chút một qua những con đường đông đúc, làm giảm sức hút của phương tiện giao thông công cộng đối với người đi làm.","audioKind":"ex2"}],"collocations":[{"en":"an inch thick","vi":"dày một inh-sơ"},{"en":"inch forward","vi":"nhích về phía trước"},{"en":"inch by inch","vi":"từng chút một"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Ký hiệu của inh-sơ là \"; khi dùng làm động từ, nó thể hiện hành động di chuyển từng chút một.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rope', 'en-b1-49', 'rope', '/roʊp/', 'B1', 'dây thừng; dây chão; cột bằng dây; buộc chặt bằng dây thừng', 'n.', NULL, 'Đồng nghĩa: cord', 'Vật liệu chung được gọi là rope; một sợi dây thừng có thể nói là a rope.', 'We tied the boat to a post with rope.', NULL, 'Chúng tôi dùng dây thừng buộc chiếc thuyền vào một cái cột.', '{"wordId":"rope","ukIpa":"/rəʊp/","usIpa":"/roʊp/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a thick, strong cord made from twisted fibres","vi":"dây thừng; dây chão"},{"pos":"v.","en":"to tie or secure something with rope","vi":"cột bằng dây; buộc chặt bằng dây thừng"}],"examples":[{"en":"We tied the boat to a post with rope.","vi":"Chúng tôi dùng dây thừng buộc chiếc thuyền vào một cái cột.","audioKind":"ex"},{"en":"Climbers should inspect their ropes regularly because damaged equipment can put the entire group at risk.","vi":"Những người leo núi nên kiểm tra dây thừng thường xuyên vì thiết bị bị hỏng có thể đặt toàn bộ nhóm vào tình thế nguy hiểm.","audioKind":"ex2"}],"collocations":[{"en":"a length of rope","vi":"một đoạn dây thừng"},{"en":"climbing rope","vi":"dây leo núi"},{"en":"skip rope","vi":"nhảy dây"},{"en":"rope off an area","vi":"rào khu vực bằng dây"}],"wordFamily":[],"synonyms":["cord"],"antonyms":[],"tipVi":"Vật liệu chung được gọi là rope; một sợi dây thừng có thể nói là a rope.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pour', 'en-b1-49', 'pour', '/pɔːr/', 'B1', 'rót; đổ; chất lỏng chảy từ vật chứa; mưa xối xả; mưa tầm tã; tuôn ra; đổ về; di chuyển hoặc đến liên tục với số lượng lớn', 'v.', NULL, NULL, 'Rót vào đâu dùng pour into; đổ cái gì ra dùng pour out of.', 'She poured warm milk into a large blue mug.', NULL, 'Cô ấy rót sữa ấm vào một chiếc cốc lớn màu xanh.', '{"wordId":"pour","ukIpa":"/pɔː/","usIpa":"/pɔːr/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To make liquid flow from a container.","vi":"rót; đổ; chất lỏng chảy từ vật chứa"},{"pos":"v.","en":"To rain very heavily.","vi":"mưa xối xả; mưa tầm tã"},{"pos":"v.","en":"To move or arrive continuously in large quantities.","vi":"tuôn ra; đổ về; di chuyển hoặc đến liên tục với số lượng lớn"}],"examples":[{"en":"She poured warm milk into a large blue mug.","vi":"Cô ấy rót sữa ấm vào một chiếc cốc lớn màu xanh.","audioKind":"ex"},{"en":"When factories pour untreated waste into rivers, they threaten aquatic ecosystems and nearby communities'' drinking water.","vi":"Khi các nhà máy xả nước thải chưa qua xử lý xuống các con sông, họ đang đe dọa các hệ sinh thái dưới nước và nguồn nước sinh hoạt của cộng đồng xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"pour into","vi":"trút vào; đổ vào"},{"en":"pour out","vi":"trút ra; tuôn ra"},{"en":"pour with rain","vi":"mưa tầm tã"},{"en":"pour money into","vi":"đổ tiền vào"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Rót vào đâu dùng pour into; đổ cái gì ra dùng pour out of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dozen', 'en-b1-49', 'dozen', '/ˈdʌzn/', 'B1', 'một tá; mười hai; nhiều; hàng chục', 'num.', NULL, NULL, 'two dozen không thêm s; dozens of dùng để chỉ số lượng nhiều.', 'Please buy a dozen eggs on your way home.', NULL, 'Hãy mua một tá trứng trên đường về nhà nhé.', '{"wordId":"dozen","ukIpa":"/ˈdʌzn/","usIpa":"/ˈdʌzn/","cefr":"B1","topic":"daily","senses":[{"pos":"num.","en":"a group of twelve","vi":"một tá; mười hai"},{"pos":"n.","en":"a large unspecified quantity, used in the plural","vi":"nhiều; hàng chục"}],"examples":[{"en":"Please buy a dozen eggs on your way home.","vi":"Hãy mua một tá trứng trên đường về nhà nhé.","audioKind":"ex"},{"en":"Dozens of community gardens have opened across the city, giving residents more opportunities to grow food.","vi":"Hàng chục khu vườn cộng đồng đã được mở ra khắp thành phố, mang lại cho cư dân nhiều cơ hội trồng trọt hơn.","audioKind":"ex2"}],"collocations":[{"en":"a dozen eggs","vi":"một tá trứng"},{"en":"half a dozen","vi":"nửa tá; sáu cái"},{"en":"dozens of people","vi":"hàng chục người"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"two dozen không thêm s; dozens of dùng để chỉ số lượng nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_currently', 'en-b1-49', 'currently', '/ˈkɝːəntli/', 'B1', 'hiện tại; đang', 'adv.', 'current (adj.)', 'Đồng nghĩa: now, at present', 'Dùng để chỉ thời điểm hiện tại, thường đứng trước động từ chính hoặc sau động từ to be.', 'Our kitchen is currently full of boxes from the move.', NULL, 'Nhà bếp của chúng tôi hiện đang ngập tràn các thùng các-tông sau vụ chuyển nhà.', '{"wordId":"currently","ukIpa":"/ˈkʌrəntli/","usIpa":"/ˈkɝːəntli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"at the present time","vi":"hiện tại; đang"}],"examples":[{"en":"Our kitchen is currently full of boxes from the move.","vi":"Nhà bếp của chúng tôi hiện đang ngập tràn các thùng các-tông sau vụ chuyển nhà.","audioKind":"ex"},{"en":"Many cities are currently investing in cycling infrastructure to reduce traffic congestion and improve urban air quality.","vi":"Nhiều thành phố hiện đang đầu tư vào cơ sở hạ tầng dành cho xe đạp nhằm giảm ùn tắc giao thông và cải thiện chất lượng không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"currently available","vi":"hiện có sẵn"},{"en":"currently working","vi":"hiện đang làm việc"},{"en":"currently under construction","vi":"hiện đang được xây dựng"}],"wordFamily":["current (adj.)"],"synonyms":["now","at present"],"antonyms":[],"tipVi":"Dùng để chỉ thời điểm hiện tại, thường đứng trước động từ chính hoặc sau động từ to be.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cabbage', 'en-b1-49', 'cabbage', '/ˈkæbɪdʒ/', 'B1', 'bắp cải; cải bắp', 'n.', NULL, NULL, 'Cả cây là danh từ đếm được: a cabbage; khi làm nguyên liệu nấu ăn thường không đếm được.', 'She sliced the cabbage thinly and added it to soup.', NULL, 'Cô ấy thái nhỏ bắp cải và cho vào món súp.', '{"wordId":"cabbage","ukIpa":"/ˈkæbɪdʒ/","usIpa":"/ˈkæbɪdʒ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a vegetable with large leaves forming a firm round head","vi":"bắp cải; cải bắp"}],"examples":[{"en":"She sliced the cabbage thinly and added it to soup.","vi":"Cô ấy thái nhỏ bắp cải và cho vào món súp.","audioKind":"ex"},{"en":"Locally grown vegetables such as cabbage can support healthier diets while reducing the environmental impact of food transport.","vi":"Rau củ trồng tại địa phương như bắp cải có thể hỗ trợ chế độ ăn lành mạnh hơn đồng thời giảm thiểu tác động môi trường từ việc vận chuyển thực phẩm.","audioKind":"ex2"}],"collocations":[{"en":"red cabbage","vi":"bắp cải tím"},{"en":"shredded cabbage","vi":"bắp cải thái sợi"},{"en":"a head of cabbage","vi":"một cây bắp cải"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cả cây là danh từ đếm được: a cabbage; khi làm nguyên liệu nấu ăn thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rug', 'en-b1-49', 'rug', '/rʌɡ/', 'B1', 'tấm thảm chùi chân; thảm nhỏ trải sàn; chăn dày giữ ấm', 'n.', NULL, NULL, 'rug thường chỉ che phủ một phần mặt sàn; trong khi carpet có thể trải kín toàn bộ căn phòng.', 'The cat curled up on the rug beside the sofa.', NULL, 'Con mèo cuộn tròn trên tấm thảm nhỏ bên cạnh chiếc ghế sofa.', '{"wordId":"rug","ukIpa":"/rʌɡ/","usIpa":"/rʌɡ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a movable covering for part of a floor","vi":"tấm thảm chùi chân; thảm nhỏ trải sàn"},{"pos":"n.","en":"a thick blanket used for warmth","vi":"chăn dày giữ ấm"}],"examples":[{"en":"The cat curled up on the rug beside the sofa.","vi":"Con mèo cuộn tròn trên tấm thảm nhỏ bên cạnh chiếc ghế sofa.","audioKind":"ex"},{"en":"Placing a rug on a hard floor can reduce noise and make shared housing more comfortable.","vi":"Trải một tấm thảm trên sàn cứng có thể làm giảm tiếng ồn và giúp không gian ở chung trở nên thoải mái hơn.","audioKind":"ex2"}],"collocations":[{"en":"a wool rug","vi":"thảm len"},{"en":"a woven rug","vi":"thảm dệt"},{"en":"a hearth rug","vi":"thảm trước lò sưởi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"rug thường chỉ che phủ một phần mặt sàn; trong khi carpet có thể trải kín toàn bộ căn phòng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_waterproof', 'en-b1-49', 'waterproof', '/ˈwɔːtərpruːf/', 'B1', 'chống nước; không thấm nước; làm cho chống nước; chống thấm', 'adj.', 'waterproofing (n.)', 'Đồng nghĩa: watertight', 'water-resistant chỉ có khả năng kháng nước nhất định, mức độ chống nước yếu hơn.', 'My waterproof jacket kept me dry during the storm.', NULL, 'Chiếc áo khoác chống nước đã giữ cho tôi khô ráo trong suốt cơn bão.', '{"wordId":"waterproof","ukIpa":"/ˈwɔːtəpruːf/","usIpa":"/ˈwɔːtərpruːf/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"not allowing water to pass through","vi":"chống nước; không thấm nước"},{"pos":"v.","en":"to treat something so water cannot pass through it","vi":"làm cho chống nước; chống thấm"}],"examples":[{"en":"My waterproof jacket kept me dry during the storm.","vi":"Chiếc áo khoác chống nước đã giữ cho tôi khô ráo trong suốt cơn bão.","audioKind":"ex"},{"en":"Outdoor workers need waterproof clothing to remain comfortable and protected when carrying out tasks in wet weather.","vi":"Những người làm việc ngoài trời cần trang phục chống nước để giữ cơ thể thoải mái và được bảo vệ khi làm nhiệm vụ trong thời tiết ẩm ướt.","audioKind":"ex2"}],"collocations":[{"en":"a waterproof jacket","vi":"áo khoác chống nước"},{"en":"waterproof boots","vi":"giày đi mưa chống nước"},{"en":"waterproof material","vi":"chất liệu chống thấm nước"},{"en":"waterproof a roof","vi":"chống thấm cho mái nhà"}],"wordFamily":["waterproofing (n.)"],"synonyms":["watertight"],"antonyms":[],"tipVi":"water-resistant chỉ có khả năng kháng nước nhất định, mức độ chống nước yếu hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_request', 'en-b1-49', 'request', '/rɪˈkwest/', 'B1', 'lời thỉnh cầu; sự yêu cầu lịch sự hoặc trang trọng; yêu cầu; đề nghị lịch sự hoặc trang trọng', 'n.', NULL, NULL, 'Danh từ thường đi với giới từ for; động từ đi trực tiếp với tân ngữ: request information.', 'The hotel agreed to my request for extra pillows.', NULL, 'Khách sạn đã đồng ý với yêu cầu xin thêm gối của tôi.', '{"wordId":"request","ukIpa":"/rɪˈkwest/","usIpa":"/rɪˈkwest/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"an act of asking politely or formally for something","vi":"lời thỉnh cầu; sự yêu cầu lịch sự hoặc trang trọng"},{"pos":"v.","en":"to ask politely or formally for something","vi":"yêu cầu; đề nghị lịch sự hoặc trang trọng"}],"examples":[{"en":"The hotel agreed to my request for extra pillows.","vi":"Khách sạn đã đồng ý với yêu cầu xin thêm gối của tôi.","audioKind":"ex"},{"en":"Residents can request detailed information about proposed developments before local authorities make their final planning decisions.","vi":"Cư dân có thể yêu cầu cung cấp thông tin chi tiết về các dự án phát triển được đề xuất trước khi chính quyền địa phương đưa ra quyết định quy hoạch cuối cùng.","audioKind":"ex2"}],"collocations":[{"en":"make a request","vi":"đưa ra yêu cầu"},{"en":"a request for information","vi":"yêu cầu cung cấp thông tin"},{"en":"on request","vi":"theo yêu cầu"},{"en":"request permission","vi":"xin phép"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ thường đi với giới từ for; động từ đi trực tiếp với tân ngữ: request information.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_roast', 'en-b1-49', 'roast', '/roʊst/', 'B1', 'nướng (thức ăn bằng nhiệt khô, đặc biệt trong lò); được nướng (chín bằng nhiệt khô trong lò hoặc trên lửa); thịt nướng (miếng thịt nướng lớn hoặc bữa ăn có món đó)', 'v.', 'roasting (n.), roaster (n.)', NULL, 'roast thường dùng cho thịt và rau; nướng bánh mì, bánh ngọt thường dùng bake.', 'We usually roast potatoes with garlic and fresh herbs.', NULL, 'Chúng tôi thường nướng khoai tây với tỏi và rau thơm tươi.', '{"wordId":"roast","ukIpa":"/rəʊst/","usIpa":"/roʊst/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To cook food using dry heat, especially in an oven.","vi":"nướng (thức ăn bằng nhiệt khô, đặc biệt trong lò)"},{"pos":"adj.","en":"Cooked using dry heat in an oven or over a fire.","vi":"được nướng (chín bằng nhiệt khô trong lò hoặc trên lửa)"},{"pos":"n.","en":"A large piece of roasted meat, or a meal containing it.","vi":"thịt nướng (miếng thịt nướng lớn hoặc bữa ăn có món đó)"}],"examples":[{"en":"We usually roast potatoes with garlic and fresh herbs.","vi":"Chúng tôi thường nướng khoai tây với tỏi và rau thơm tươi.","audioKind":"ex"},{"en":"Families can roast seasonal vegetables at home to prepare nutritious meals without relying on highly processed foods.","vi":"Các gia đình có thể tự nướng rau củ theo mùa tại nhà để chuẩn bị những bữa ăn bổ dưỡng mà không cần phụ thuộc vào thực phẩm chế biến sẵn.","audioKind":"ex2"}],"collocations":[{"en":"roast vegetables","vi":"rau củ nướng"},{"en":"roast chicken","vi":"gà nướng"},{"en":"a Sunday roast","vi":"bữa ăn thịt nướng chủ nhật"}],"wordFamily":["roasting (n.)","roaster (n.)"],"synonyms":[],"antonyms":[],"tipVi":"roast thường dùng cho thịt và rau; nướng bánh mì, bánh ngọt thường dùng bake.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chop', 'en-b1-49', 'chop', '/tʃɑːp/', 'B1', 'cắt nhỏ; chặt; băm (bằng những nhát dao sắc và dứt khoát); cú chặt; cú băm (cú đánh giáng xuống bằng lưỡi dao hoặc tay); miếng thịt có dính xương', 'v.', 'chopper (n.), chopped (adj.)', 'Đồng nghĩa: cut', 'Quá khứ là chopped, phân từ là chopping, đều nhân đôi chữ p.', 'Please chop the carrots while I heat the soup.', NULL, 'Xin hãy thái nhỏ cà rốt trong lúc tôi đun nóng súp.', '{"wordId":"chop","ukIpa":"/tʃɒp/","usIpa":"/tʃɑːp/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To cut with repeated sharp blows using a blade","vi":"cắt nhỏ; chặt; băm (bằng những nhát dao sắc và dứt khoát)"},{"pos":"n.","en":"A sharp downward blow with a blade or hand","vi":"cú chặt; cú băm (cú đánh giáng xuống bằng lưỡi dao hoặc tay)"},{"pos":"n.","en":"A piece of meat cut with a bone attached","vi":"miếng thịt có dính xương"}],"examples":[{"en":"Please chop the carrots while I heat the soup.","vi":"Xin hãy thái nhỏ cà rốt trong lúc tôi đun nóng súp.","audioKind":"ex"},{"en":"When communities chop down trees for fuel, they may unintentionally damage habitats and increase soil erosion.","vi":"Khi người dân chặt cây lấy củi, họ có thể vô tình phá hủy môi trường sống và làm gia tăng tình trạng xói mòn đất.","audioKind":"ex2"}],"collocations":[{"en":"chop vegetables","vi":"cắt rau củ"},{"en":"chop down trees","vi":"chặt cây"},{"en":"chop wood","vi":"bổ củi"},{"en":"lamb chop","vi":"sườn cừu"}],"wordFamily":["chopper (n.)","chopped (adj.)"],"synonyms":["cut"],"antonyms":[],"tipVi":"Quá khứ là chopped, phân từ là chopping, đều nhân đôi chữ p.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gorgeous', 'en-b1-49', 'gorgeous', '/ˈɡɔːrdʒəs/', 'B1', 'tuyệt đẹp; lộng lẫy; rực rỡ; tuyệt vời; dễ chịu; thú vị', 'adj.', 'gorgeously (adv.), gorgeousness (n.)', 'Đồng nghĩa: beautiful, stunning · Trái nghĩa: ugly', 'Cung bậc biểu đạt mạnh hơn beautiful, thường được dùng trong văn phong giao tiếp hàng ngày để khen ngợi.', 'The garden looks gorgeous in the early morning sunshine.', NULL, 'Khu vườn trông vô cùng rực rỡ dưới ánh nắng ban mai.', '{"wordId":"gorgeous","ukIpa":"/ˈɡɔːdʒəs/","usIpa":"/ˈɡɔːrdʒəs/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Extremely beautiful or attractive.","vi":"tuyệt đẹp; lộng lẫy; rực rỡ"},{"pos":"adj.","en":"Very pleasant or enjoyable.","vi":"tuyệt vời; dễ chịu; thú vị"}],"examples":[{"en":"The garden looks gorgeous in the early morning sunshine.","vi":"Khu vườn trông vô cùng rực rỡ dưới ánh nắng ban mai.","audioKind":"ex"},{"en":"Although coastal destinations offer gorgeous scenery, uncontrolled tourism can damage the natural environments that attract visitors.","vi":"Mặc dù các điểm đến ven biển có phong cảnh tuyệt đẹp, nhưng hoạt động du lịch không kiểm soát có thể tàn phá môi trường tự nhiên vốn thu hút du khách.","audioKind":"ex2"}],"collocations":[{"en":"gorgeous scenery","vi":"phong cảnh tuyệt đẹp"},{"en":"gorgeous weather","vi":"thời tiết tuyệt vời"},{"en":"look gorgeous","vi":"trông cực kỳ xinh đẹp"}],"wordFamily":["gorgeously (adv.)","gorgeousness (n.)"],"synonyms":["beautiful","stunning"],"antonyms":["ugly"],"tipVi":"Cung bậc biểu đạt mạnh hơn beautiful, thường được dùng trong văn phong giao tiếp hàng ngày để khen ngợi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glance', 'en-b1-49', 'glance', '/ɡlæns/', 'B1', 'liếc nhìn; nhìn thoáng qua; cái liếc; cái nhìn thoáng qua', 'v.', NULL, NULL, 'Glance at mang nghĩa là nhìn thoáng qua trong chốc lát; trái lại, stare at có nghĩa là nhìn chằm chằm.', 'She glanced out of the window before opening the door.', NULL, 'Cô ấy liếc nhìn ra ngoài cửa sổ trước khi mở cửa.', '{"wordId":"glance","ukIpa":"/ɡlɑːns/","usIpa":"/ɡlæns/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To look at someone or something very briefly.","vi":"liếc nhìn; nhìn thoáng qua"},{"pos":"n.","en":"A quick, brief look at someone or something.","vi":"cái liếc; cái nhìn thoáng qua"}],"examples":[{"en":"She glanced out of the window before opening the door.","vi":"Cô ấy liếc nhìn ra ngoài cửa sổ trước khi mở cửa.","audioKind":"ex"},{"en":"Commuters often glance at their phones while walking, which can reduce their awareness of nearby traffic.","vi":"Những người đi làm thường liếc nhìn điện thoại khi đang đi bộ, điều này có thể làm giảm khả năng chú ý đến giao thông xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"glance at","vi":"liếc nhìn vào"},{"en":"take a glance","vi":"nhìn thoáng qua"},{"en":"at first glance","vi":"thoạt nhìn; thoạt trông"},{"en":"exchange glances","vi":"trao đổi ánh nhìn với nhau"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Glance at mang nghĩa là nhìn thoáng qua trong chốc lát; trái lại, stare at có nghĩa là nhìn chằm chằm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tube', 'en-b1-49', 'tube', '/tuːb/', 'B1', 'ống (vật hình trụ rỗng để dẫn chất lỏng hoặc khí); tuýp (vật đựng mềm để bóp kem hoặc thuốc); hệ thống tàu điện ngầm Luân Đôn', 'n.', 'tubular (adj.)', NULL, 'The tube dùng để chỉ riêng hệ thống tàu điện ngầm Luân Đôn; cụm a tube of dùng cho các loại đồ đựng dạng tuýp mềm.', 'Water flowed through a clear tube into the tank.', NULL, 'Nước chảy qua một ống trong suốt để vào bể chứa.', '{"wordId":"tube","ukIpa":"/tjuːb/","usIpa":"/tuːb/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a long, hollow object that carries liquids or gases","vi":"ống (vật hình trụ rỗng để dẫn chất lỏng hoặc khí)"},{"pos":"n.","en":"a soft container squeezed to release paste or cream","vi":"tuýp (vật đựng mềm để bóp kem hoặc thuốc)"},{"pos":"n.","en":"the underground railway system in London","vi":"hệ thống tàu điện ngầm Luân Đôn"}],"examples":[{"en":"Water flowed through a clear tube into the tank.","vi":"Nước chảy qua một ống trong suốt để vào bể chứa.","audioKind":"ex"},{"en":"Taking the tube instead of driving can help commuters avoid congestion in central London.","vi":"Đi tàu điện ngầm thay vì lái xe có thể giúp những người đi làm tránh được tình trạng tắc nghẽn ở trung tâm Luân Đôn.","audioKind":"ex2"}],"collocations":[{"en":"a tube of toothpaste","vi":"một tuýp kem đánh răng"},{"en":"a plastic tube","vi":"một ống nhựa"},{"en":"take the tube","vi":"đi tàu điện ngầm Luân Đôn"}],"wordFamily":["tubular (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"The tube dùng để chỉ riêng hệ thống tàu điện ngầm Luân Đôn; cụm a tube of dùng cho các loại đồ đựng dạng tuýp mềm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ladder', 'en-b1-49', 'ladder', '/ˈlædər/', 'B1', 'cái thang; thang bậc (thăng tiến trong sự nghiệp, xã hội)', 'n.', NULL, NULL, 'ladder là loại thang di động; còn stairs chỉ cầu thang cố định trong tòa nhà.', 'She climbed the ladder to pick apples from the tree.', NULL, 'Cô ấy trèo lên thang để hái táo trên cây.', '{"wordId":"ladder","ukIpa":"/ˈlædə/","usIpa":"/ˈlædər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Equipment with steps for climbing up or down","vi":"cái thang"},{"pos":"n.","en":"A series of levels through which someone can progress","vi":"thang bậc (thăng tiến trong sự nghiệp, xã hội)"}],"examples":[{"en":"She climbed the ladder to pick apples from the tree.","vi":"Cô ấy trèo lên thang để hái táo trên cây.","audioKind":"ex"},{"en":"Access to professional training can help young employees move up the career ladder more quickly.","vi":"Cơ hội tiếp cận đào tạo chuyên nghiệp có thể giúp nhân viên trẻ thăng tiến nhanh hơn trên nấc thang sự nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"climb a ladder","vi":"trèo thang"},{"en":"career ladder","vi":"nấc thang sự nghiệp"},{"en":"property ladder","vi":"thang bậc bất động sản"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"ladder là loại thang di động; còn stairs chỉ cầu thang cố định trong tòa nhà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shiny', 'en-b1-49', 'shiny', '/ˈʃaɪni/', 'B1', 'bóng; sáng lấp lánh', 'adj.', 'shine (v.), shininess (n.)', 'Đồng nghĩa: glossy, gleaming · Trái nghĩa: dull', 'Chỉ bề mặt phản quang, không đồng nghĩa với việc tự phát sáng.', 'She polished her shoes until they looked shiny.', NULL, 'Cô ấy đánh bóng đôi giày cho đến khi chúng sáng bóng lên.', '{"wordId":"shiny","ukIpa":"/ˈʃaɪni/","usIpa":"/ˈʃaɪni/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Having a smooth surface that reflects light.","vi":"bóng; sáng lấp lánh"}],"examples":[{"en":"She polished her shoes until they looked shiny.","vi":"Cô ấy đánh bóng đôi giày cho đến khi chúng sáng bóng lên.","audioKind":"ex"},{"en":"Shiny packaging may attract consumers, but it often creates waste that is difficult to recycle.","vi":"Bao bì sáng bóng có thể thu hút người tiêu dùng, nhưng nó thường tạo ra rác thải khó tái chế.","audioKind":"ex2"}],"collocations":[{"en":"shiny shoes","vi":"giày bóng loáng"},{"en":"shiny surface","vi":"bề mặt sáng bóng"},{"en":"shiny hair","vi":"mái tóc óng ả"}],"wordFamily":["shine (v.)","shininess (n.)"],"synonyms":["glossy","gleaming"],"antonyms":["dull"],"tipVi":"Chỉ bề mặt phản quang, không đồng nghĩa với việc tự phát sáng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_giant', 'en-b1-49', 'giant', '/ˈdʒaɪənt/', 'B1', 'khổng lồ; to lớn; người khổng lồ; đại doanh nghiệp; nhân vật kiệt xuất', 'adj.', 'gigantic (adj.)', 'Đồng nghĩa: huge, enormous · Trái nghĩa: tiny', 'Khi là tính từ thường đứng trước danh từ; khi là danh từ có thể chỉ tập đoàn hoặc công ty lớn trong ngành.', 'A giant pumpkin filled almost the entire garden cart.', NULL, 'Một quả bí ngô khổng lồ chiếm gần hết chiếc xe đẩy trong vườn.', '{"wordId":"giant","ukIpa":"/ˈdʒaɪənt/","usIpa":"/ˈdʒaɪənt/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Much larger than usual","vi":"khổng lồ; to lớn"},{"pos":"n.","en":"An imaginary person of enormous size","vi":"người khổng lồ"},{"pos":"n.","en":"A very large company or an exceptionally important person","vi":"đại doanh nghiệp; nhân vật kiệt xuất"}],"examples":[{"en":"A giant pumpkin filled almost the entire garden cart.","vi":"Một quả bí ngô khổng lồ chiếm gần hết chiếc xe đẩy trong vườn.","audioKind":"ex"},{"en":"Technology giants have considerable influence over how people access information and communicate with one another.","vi":"Các","audioKind":"ex2"}],"collocations":[{"en":"a giant leap","vi":"một bước tiến vĩ đại"},{"en":"a giant screen","vi":"màn hình khổng lồ"},{"en":"a technology giant","vi":"ông lớn công nghệ"}],"wordFamily":["gigantic (adj.)"],"synonyms":["huge","enormous"],"antonyms":["tiny"],"tipVi":"Khi là tính từ thường đứng trước danh từ; khi là danh từ có thể chỉ tập đoàn hoặc công ty lớn trong ngành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hanger', 'en-b1-49', 'hanger', '/ˈhæŋər/', 'B1', 'móc treo quần áo', 'n.', 'hang (v.)', 'Đồng nghĩa: coat hanger', 'hanger là móc áo; hangar là nhà chứa máy bay, hãy chú ý cách viết.', 'She put her jacket on a wooden hanger.', NULL, 'Cô ấy treo chiếc áo khoác của mình lên một chiếc móc áo bằng gỗ.', '{"wordId":"hanger","ukIpa":"/ˈhæŋə/","usIpa":"/ˈhæŋər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A shaped frame used to hang clothes.","vi":"móc treo quần áo"}],"examples":[{"en":"She put her jacket on a wooden hanger.","vi":"Cô ấy treo chiếc áo khoác của mình lên một chiếc móc áo bằng gỗ.","audioKind":"ex"},{"en":"Retailers can reduce plastic waste by collecting used hangers and replacing damaged ones with recyclable alternatives.","vi":"Các nhà bán lẻ có thể giảm thiểu rác thải nhựa bằng cách thu gom móc áo đã qua sử dụng và thay thế những chiếc bị hỏng bằng các sản phẩm có thể tái chế.","audioKind":"ex2"}],"collocations":[{"en":"coat hanger","vi":"móc treo áo khoác"},{"en":"wooden hanger","vi":"móc áo bằng gỗ"},{"en":"wire hanger","vi":"móc áo bằng kim loại"}],"wordFamily":["hang (v.)"],"synonyms":["coat hanger"],"antonyms":[],"tipVi":"hanger là móc áo; hangar là nhà chứa máy bay, hãy chú ý cách viết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jewel', 'en-b1-49', 'jewel', '/ˈdʒuːəl/', 'B1', 'viên ngọc; đá quý; người hoặc vật vô cùng quý giá, đẹp đẽ hoặc đáng ngưỡng mộ', 'n.', 'jeweller (n.), jewellery (n.), jewelled (adj.)', 'Đồng nghĩa: gem', 'jewel là danh từ đếm được; jewellery dùng để chỉ chung trang sức và là danh từ không đếm được.', 'A blue jewel sparkled on her silver necklace.', NULL, 'Một viên ngọc màu xanh lam lấp lánh trên chiếc vòng cổ bằng bạc của cô ấy.', '{"wordId":"jewel","ukIpa":"/ˈdʒuːəl/","usIpa":"/ˈdʒuːəl/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A valuable stone, often used in decorative personal objects.","vi":"viên ngọc; đá quý"},{"pos":"n.","en":"Someone or something especially valuable, beautiful, or admired.","vi":"người hoặc vật vô cùng quý giá, đẹp đẽ hoặc đáng ngưỡng mộ"}],"examples":[{"en":"A blue jewel sparkled on her silver necklace.","vi":"Một viên ngọc màu xanh lam lấp lánh trên chiếc vòng cổ bằng bạc của cô ấy.","audioKind":"ex"},{"en":"The restored theatre is a cultural jewel that attracts visitors and supports local businesses.","vi":"Nhà hát sau khi được trùng tu là một viên ngọc văn hóa thu hút du khách và hỗ trợ các doanh nghiệp địa phương.","audioKind":"ex2"}],"collocations":[{"en":"precious jewel","vi":"đá quý"},{"en":"a jewel in the crown","vi":"viên ngọc quý giá nhất; niềm tự hào lớn nhất"}],"wordFamily":["jeweller (n.)","jewellery (n.)","jewelled (adj.)"],"synonyms":["gem"],"antonyms":[],"tipVi":"jewel là danh từ đếm được; jewellery dùng để chỉ chung trang sức và là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rub', 'en-b1-49', 'rub', '/rʌb/', 'B1', 'chà; xát; cọ xát; cú chà; động tác xát', 'v.', 'rubbing (n.)', NULL, 'Các dạng quá khứ rubbed và phân từ hiện đều được nhân đôi phụ âm b.', 'She rubbed her cold hands together beside the heater.', NULL, 'Cô ấy xoa hai bàn tay lạnh cóng vào nhau bên cạnh lò sưởi.', '{"wordId":"rub","ukIpa":"/rʌb/","usIpa":"/rʌb/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Move against a surface with pressure, often repeatedly.","vi":"chà; xát; cọ xát"},{"pos":"n.","en":"An act of pressing and moving against a surface.","vi":"cú chà; động tác xát"}],"examples":[{"en":"She rubbed her cold hands together beside the heater.","vi":"Cô ấy xoa hai bàn tay lạnh cóng vào nhau bên cạnh lò sưởi.","audioKind":"ex"},{"en":"Protective gloves prevent workers from rubbing their skin against rough surfaces when handling heavy materials.","vi":"Găng tay bảo hộ giúp công nhân tránh làm da bị cọ xát vào các bề mặt thô ráp khi xử lý vật liệu nặng.","audioKind":"ex2"}],"collocations":[{"en":"rub your eyes","vi":"dụi mắt"},{"en":"rub your hands together","vi":"xoa hai bàn tay vào nhau"},{"en":"rub against","vi":"cọ xát vào"},{"en":"give something a rub","vi":"chà xát cái gì đó"}],"wordFamily":["rubbing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Các dạng quá khứ rubbed và phân từ hiện đều được nhân đôi phụ âm b.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_response', 'en-b1-49', 'response', '/rɪˈspɑːns/', 'B1', 'câu trả lời; sự đáp lại; sự phản ứng; sự hưởng ứng', 'n.', 'respond (v.), responsive (adj.), responsiveness (n.)', 'Đồng nghĩa: reply, answer, reaction', 'response sau thường đi với to, không đi với of.', 'I sent an invitation but haven''t received a response yet.', NULL, 'Tôi đã gửi lời mời nhưng vẫn chưa nhận được hồi âm.', '{"wordId":"response","ukIpa":"/rɪˈspɒns/","usIpa":"/rɪˈspɑːns/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Something said or written as an answer.","vi":"câu trả lời; sự đáp lại"},{"pos":"n.","en":"An action or change caused by an event or situation.","vi":"sự phản ứng; sự hưởng ứng"}],"examples":[{"en":"I sent an invitation but haven''t received a response yet.","vi":"Tôi đã gửi lời mời nhưng vẫn chưa nhận được hồi âm.","audioKind":"ex"},{"en":"A rapid response to disease outbreaks can protect vulnerable communities and reduce pressure on local hospitals.","vi":"Phản ứng nhanh chóng đối với các đợt bùng phát dịch bệnh có thể bảo vệ các cộng đồng dễ bị tổn thương và giảm bớt áp lực cho các bệnh viện địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a response to","vi":"câu trả lời cho"},{"en":"in response to","vi":"đáp lại; để hưởng ứng"},{"en":"a rapid response","vi":"phản ứng nhanh"},{"en":"receive a response","vi":"nhận được phản hồi"}],"wordFamily":["respond (v.)","responsive (adj.)","responsiveness (n.)"],"synonyms":["reply","answer","reaction"],"antonyms":[],"tipVi":"response sau thường đi với to, không đi với of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unlike', 'en-b1-49', 'unlike', '/ˌʌnˈlaɪk/', 'B1', 'khác với; không giống với thói quen thường ngày', 'prep.', 'like (prep.), likeness (n.)', 'Đồng nghĩa: different from · Trái nghĩa: like', 'unlike theo sau là danh từ hoặc đại từ; không trực tiếp đi với một câu hoàn chỉnh.', 'Unlike her brother, Lina enjoys getting up early.', NULL, 'Không giống như anh trai mình, Lina rất thích dậy sớm.', '{"wordId":"unlike","ukIpa":"/ˌʌnˈlaɪk/","usIpa":"/ˌʌnˈlaɪk/","cefr":"B1","topic":"daily","senses":[{"pos":"prep.","en":"different from someone or something","vi":"khác với"},{"pos":"prep.","en":"not typical of someone''s usual behaviour","vi":"không giống với thói quen thường ngày"}],"examples":[{"en":"Unlike her brother, Lina enjoys getting up early.","vi":"Không giống như anh trai mình, Lina rất thích dậy sớm.","audioKind":"ex"},{"en":"Unlike private cars, public transport can move large groups of people while using relatively little road space.","vi":"Khác với xe hơi cá nhân, giao thông công cộng có thể chuyên chở một lượng lớn hành khách mà chỉ chiếm diện tích mặt đường tương đối nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"unlike most people","vi":"không giống như hầu hết mọi người"},{"en":"quite unlike","vi":"rất khác so với"},{"en":"unlike anything else","vi":"không giống bất cứ thứ gì khác"},{"en":"it''s unlike someone to","vi":"không giống tác phong bình thường của ai đó"}],"wordFamily":["like (prep.)","likeness (n.)"],"synonyms":["different from"],"antonyms":["like"],"tipVi":"unlike theo sau là danh từ hoặc đại từ; không trực tiếp đi với một câu hoàn chỉnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_favour', 'en-b1-49', 'favour', '/ˈfeɪvər/', 'B1', 'sự giúp đỡ; việc làm ơn; sự ủng hộ; sự thiên vị; thiên vị; ủng hộ; ưu ái', 'n.', 'favourable (adj.), favourably (adv.), favourite (adj.), favouritism (n.)', NULL, 'Cách viết Anh-Anh là favour, Anh-Mỹ là favor; nhờ ai giúp việc gì dùng do.', 'Could you do me a favour and water my plants?', NULL, 'Bạn có thể làm ơn giúp tôi tưới nước cho mấy chậu cây được không?', '{"wordId":"favour","ukIpa":"/ˈfeɪvə/","usIpa":"/ˈfeɪvər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Something helpful you do for someone.","vi":"sự giúp đỡ; việc làm ơn"},{"pos":"n.","en":"Approval, support, or preference shown towards someone or something.","vi":"sự ủng hộ; sự thiên vị"},{"pos":"v.","en":"To prefer, support, or give an advantage to someone or something.","vi":"thiên vị; ủng hộ; ưu ái"}],"examples":[{"en":"Could you do me a favour and water my plants?","vi":"Bạn có thể làm ơn giúp tôi tưới nước cho mấy chậu cây được không?","audioKind":"ex"},{"en":"Many residents favour investment in public transport because it can reduce congestion and improve air quality.","vi":"Nhiều cư dân ủng hộ việc đầu tư vào giao thông công cộng vì nó có thể giảm ùn tắc và cải thiện chất lượng không khí.","audioKind":"ex2"}],"collocations":[{"en":"do someone a favour","vi":"giúp ai đó một việc"},{"en":"in favour of","vi":"ủng hộ; tán thành"},{"en":"return the favour","vi":"đáp lại ơn huệ"},{"en":"favour one option over another","vi":"ưu tiên phương án này hơn phương án khác"}],"wordFamily":["favourable (adj.)","favourably (adv.)","favourite (adj.)","favouritism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết Anh-Anh là favour, Anh-Mỹ là favor; nhờ ai giúp việc gì dùng do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_49_1', 'en-b1-49', 'Cách dùng “tube” (n.) — ống (vật hình trụ rỗng để dẫn chất lỏng hoặc khí)', 'a tube of toothpaste  ·  a plastic tube  ·  take the tube', 'The tube dùng để chỉ riêng hệ thống tàu điện ngầm Luân Đôn; cụm a tube of dùng cho các loại đồ đựng dạng tuýp mềm.', 'Họ từ (Word Family): tubular (adj.)', '[{"hanzi":"Water flowed through a clear tube into the tank.","pinyin":"","meaning":"Nước chảy qua một ống trong suốt để vào bể chứa."},{"hanzi":"Taking the tube instead of driving can help commuters avoid congestion in central London.","pinyin":"","meaning":"Đi tàu điện ngầm thay vì lái xe có thể giúp những người đi làm tránh được tình trạng tắc nghẽn ở trung tâm Luân Đôn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_49_2', 'en-b1-49', 'Cách dùng “switch” (n.) — công tắc điện', 'light switch  ·  switch off  ·  switch to', 'Cụm switch on/off dùng cho việc bật/tắt thiết bị; switch to dùng khi chuyển sang đối tượng hoặc phương án mới.', NULL, '[{"hanzi":"The light switch is just behind the kitchen door.","pinyin":"","meaning":"Công tắc đèn nằm ngay phía sau cửa phòng bếp."},{"hanzi":"Governments can encourage households to switch to renewable energy by offering financial support.","pinyin":"","meaning":"Chính phủ có thể khuyến khích các hộ gia đình chuyển sang sử dụng năng lượng tái tạo bằng cách cung cấp hỗ trợ tài chính."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_49_3', 'en-b1-49', 'Cách dùng “giant” (adj.) — khổng lồ; to lớn', 'a giant leap  ·  a giant screen  ·  a technology giant', 'Khi là tính từ thường đứng trước danh từ; khi là danh từ có thể chỉ tập đoàn hoặc công ty lớn trong ngành.', 'Họ từ (Word Family): gigantic (adj.) | Đồng nghĩa: huge, enormous · Trái nghĩa: tiny', '[{"hanzi":"A giant pumpkin filled almost the entire garden cart.","pinyin":"","meaning":"Một quả bí ngô khổng lồ chiếm gần hết chiếc xe đẩy trong vườn."},{"hanzi":"Technology giants have considerable influence over how people access information and communicate with one another.","pinyin":"","meaning":"Các"}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_49_4', 'en-b1-49', 'Cách dùng “gorgeous” (adj.) — tuyệt đẹp; lộng lẫy; rực rỡ', 'gorgeous scenery  ·  gorgeous weather  ·  look gorgeous', 'Cung bậc biểu đạt mạnh hơn beautiful, thường được dùng trong văn phong giao tiếp hàng ngày để khen ngợi.', 'Họ từ (Word Family): gorgeously (adv.), gorgeousness (n.) | Đồng nghĩa: beautiful, stunning · Trái nghĩa: ugly', '[{"hanzi":"The garden looks gorgeous in the early morning sunshine.","pinyin":"","meaning":"Khu vườn trông vô cùng rực rỡ dưới ánh nắng ban mai."},{"hanzi":"Although coastal destinations offer gorgeous scenery, uncontrolled tourism can damage the natural environments that attract visitors.","pinyin":"","meaning":"Mặc dù các điểm đến ven biển có phong cảnh tuyệt đẹp, nhưng hoạt động du lịch không kiểm soát có thể tàn phá môi trường tự nhiên vốn thu hút du khách."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_49_1', 'en-b1-49', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_1_1', 'ten_b1_49_1', 'sour', 'These grapes are too sour for my taste.', 'These grapes are too sour for my taste.', '/ˈsaʊər/', 'Những quả nho này quá chua đối với khẩu vị của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_1_2', 'ten_b1_49_1', 'indoors', 'We stayed indoors and played chess during the storm.', 'We stayed indoors and played chess during the storm.', '/ˌɪnˈdɔːrz/', 'Chúng tôi ở trong nhà và chơi cờ trong suốt cơn bão.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_1_3', 'ten_b1_49_1', 'routine', 'A short walk is part of my morning routine.', 'A short walk is part of my morning routine.', '/ruːˈtiːn/', 'Một chuyến đi dạo ngắn là một phần trong thói quen buổi sáng của tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_1_4', 'ten_b1_49_1', 'switch', 'The light switch is just behind the kitchen door.', 'The light switch is just behind the kitchen door.', '/swɪtʃ/', 'Công tắc đèn nằm ngay phía sau cửa phòng bếp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_1_5', 'ten_b1_49_1', 'inch', 'The shelf is an inch wider than the cupboard.', 'The shelf is an inch wider than the cupboard.', '/ɪntʃ/', 'Cái kệ rộng hơn cái tủ một inh-sơ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_1_6', 'ten_b1_49_1', 'rope', 'We tied the boat to a post with rope.', 'We tied the boat to a post with rope.', '/roʊp/', 'Chúng tôi dùng dây thừng buộc chiếc thuyền vào một cái cột.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_1_7', 'ten_b1_49_1', 'pour', 'She poured warm milk into a large blue mug.', 'She poured warm milk into a large blue mug.', '/pɔːr/', 'Cô ấy rót sữa ấm vào một chiếc cốc lớn màu xanh.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_1_8', 'ten_b1_49_1', 'dozen', 'Please buy a dozen eggs on your way home.', 'Please buy a dozen eggs on your way home.', '/ˈdʌzn/', 'Hãy mua một tá trứng trên đường về nhà nhé.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_49_1_1', 'en-b1-49', 'ten_b1_49_1', 'listening', 'listening', 'These grapes are too sour for my taste.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những quả nho này quá chua đối với khẩu vị của tôi.","Bạn có thể làm ơn giúp tôi tưới nước cho mấy chậu cây được không?","Một chuyến đi dạo ngắn là một phần trong thói quen buổi sáng của tôi.","Công tắc đèn nằm ngay phía sau cửa phòng bếp."]'::jsonb, 0, 'These grapes are too sour for my taste. → Những quả nho này quá chua đối với khẩu vị của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_49_1_2', 'en-b1-49', 'ten_b1_49_1', 'listening', 'listening', 'We stayed indoors and played chess during the storm.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã gửi lời mời nhưng vẫn chưa nhận được hồi âm.","Chúng tôi ở trong nhà và chơi cờ trong suốt cơn bão.","Cô ấy thái nhỏ bắp cải và cho vào món súp.","Không giống như anh trai mình, Lina rất thích dậy sớm."]'::jsonb, 1, 'We stayed indoors and played chess during the storm. → Chúng tôi ở trong nhà và chơi cờ trong suốt cơn bão.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_49_1_3', 'en-b1-49', 'ten_b1_49_1', 'listening', 'listening', 'A short walk is part of my morning routine.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn có thể làm ơn giúp tôi tưới nước cho mấy chậu cây được không?","Không giống như anh trai mình, Lina rất thích dậy sớm.","Chúng tôi ở trong nhà và chơi cờ trong suốt cơn bão.","Một chuyến đi dạo ngắn là một phần trong thói quen buổi sáng của tôi."]'::jsonb, 3, 'A short walk is part of my morning routine. → Một chuyến đi dạo ngắn là một phần trong thói quen buổi sáng của tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_49_2', 'en-b1-49', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_2_1', 'ten_b1_49_2', 'sour', 'Disagreements over shared resources can sour relations between neighbouring countries and delay important environmental projects.', 'Disagreements over shared resources can sour relations between neighbouring countries and delay important environmental projects.', '/ˈsaʊər/', 'Những bất đồng về nguồn lực chung có thể làm xấu đi mối quan hệ giữa các quốc gia láng giềng và làm trì hoãn các dự án môi trường quan trọng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_2_2', 'ten_b1_49_2', 'indoors', 'Children who spend most of their time indoors may have fewer opportunities for physical activity.', 'Children who spend most of their time indoors may have fewer opportunities for physical activity.', '/ˌɪnˈdɔːrz/', 'Trẻ em dành phần lớn thời gian ở trong nhà có thể có ít cơ hội tham gia các hoạt động thể chất hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_2_3', 'ten_b1_49_2', 'routine', 'Maintaining a regular sleep routine can improve concentration and help students cope with academic pressure.', 'Maintaining a regular sleep routine can improve concentration and help students cope with academic pressure.', '/ruːˈtiːn/', 'Duy trì thói quen ngủ nghỉ đều đặn có thể cải thiện khả năng tập trung và giúp học sinh đối phó với áp lực học tập.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_2_4', 'ten_b1_49_2', 'switch', 'Governments can encourage households to switch to renewable energy by offering financial support.', 'Governments can encourage households to switch to renewable energy by offering financial support.', '/swɪtʃ/', 'Chính phủ có thể khuyến khích các hộ gia đình chuyển sang sử dụng năng lượng tái tạo bằng cách cung cấp hỗ trợ tài chính.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_2_5', 'ten_b1_49_2', 'inch', 'During rush hour, buses inch through crowded streets, making public transport less attractive to commuters.', 'During rush hour, buses inch through crowded streets, making public transport less attractive to commuters.', '/ɪntʃ/', 'Vào giờ cao điểm, các xe buýt nhích từng chút một qua những con đường đông đúc, làm giảm sức hút của phương tiện giao thông công cộng đối với người đi làm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_49_2_6', 'ten_b1_49_2', 'rope', 'Climbers should inspect their ropes regularly because damaged equipment can put the entire group at risk.', 'Climbers should inspect their ropes regularly because damaged equipment can put the entire group at risk.', '/roʊp/', 'Những người leo núi nên kiểm tra dây thừng thường xuyên vì thiết bị bị hỏng có thể đặt toàn bộ nhóm vào tình thế nguy hiểm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_49_2_1', 'en-b1-49', 'ten_b1_49_2', 'listening', 'listening', 'Disagreements over shared resources can sour relations between neighbouring countries and delay important environmental projects.', NULL, 'Trong câu vừa nghe, từ “sour” mang nghĩa nào sau đây?', '["chua (có vị gắt như chanh)","viên ngọc; đá quý","cành cây","thang cuốn"]'::jsonb, 0, '“sour” (/ˈsaʊər/): chua (có vị gắt như chanh). Câu đầy đủ: Disagreements over shared resources can sour relations between neighbouring countries and delay important environmental projects.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_49_2_2', 'en-b1-49', 'ten_b1_49_2', 'listening', 'listening', 'Children who spend most of their time indoors may have fewer opportunities for physical activity.', NULL, 'Trong câu vừa nghe, từ “indoors” mang nghĩa nào sau đây?', '["tăng dần; ngày càng nhiều","ở trong nhà, vào trong nhà (bên trong một tòa nhà)","hàng; dãy","thập kỷ; mười năm"]'::jsonb, 1, '“indoors” (/ˌɪnˈdɔːrz/): ở trong nhà, vào trong nhà (bên trong một tòa nhà). Câu đầy đủ: Children who spend most of their time indoors may have fewer opportunities for physical activity.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
