INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_1', 'en-b1-49', NULL, 'comprehensive_test', 'listening', 'sour', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chân đế; nền tảng","người lạ; người không quen biết","bong bóng; bọt","chua (có vị gắt như chanh)"]'::jsonb, 3, 'sour (/ˈsaʊər/) → chua (có vị gắt như chanh); ôi thiu, chua (có mùi vị khó chịu do bị hỏng); trở nên kém vui, làm xẩu đi (mối quan hệ)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_2', 'en-b1-49', NULL, 'comprehensive_test', 'listening', 'We stayed indoors and played chess during the storm.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bạn có thể làm ơn giúp tôi tưới nước cho mấy chậu cây được không?","Những quả nho này quá chua đối với khẩu vị của tôi.","Cô ấy trèo lên thang để hái táo trên cây.","Chúng tôi ở trong nhà và chơi cờ trong suốt cơn bão."]'::jsonb, 3, 'We stayed indoors and played chess during the storm. → Chúng tôi ở trong nhà và chơi cờ trong suốt cơn bão.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_3', 'en-b1-49', NULL, 'comprehensive_test', 'listening', 'routine', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["một tá; mười hai","mạng lưới; hệ thống kết nối","thói quen; công việc thường ngày; lịch trình thường nhật","bản ghi âm băng từ"]'::jsonb, 2, 'routine (/ruːˈtiːn/) → thói quen; công việc thường ngày; lịch trình thường nhật; thường lệ; thông lệ; theo quy chuẩn; bài biểu diễn; bài tập luyện theo động tác cố định', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_4', 'en-b1-49', NULL, 'comprehensive_test', 'listening', 'The light switch is just behind the kitchen door.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bạn có thể làm ơn giúp tôi tưới nước cho mấy chậu cây được không?","Cái kệ rộng hơn cái tủ một inh-sơ.","Công tắc đèn nằm ngay phía sau cửa phòng bếp.","Cô ấy liếc nhìn ra ngoài cửa sổ trước khi mở cửa."]'::jsonb, 2, 'The light switch is just behind the kitchen door. → Công tắc đèn nằm ngay phía sau cửa phòng bếp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_5', 'en-b1-49', NULL, 'comprehensive_test', 'listening', 'inch', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chảy; luân chuyển","lễ hội hóa trang; ngày hội","tiền lương; tiền công (thường tính theo giờ hoặc tuần)","inh-sơ (đơn vị đo chiều dài bằng 2,54 cm)"]'::jsonb, 3, 'inch (/ɪntʃ/) → inh-sơ (đơn vị đo chiều dài bằng 2,54 cm); nhích dần; di chuyển rất chậm qua một khoảng cách ngắn', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_6', 'en-b1-49', NULL, 'comprehensive_test', 'listening', 'We tied the boat to a post with rope.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nước chảy qua một ống trong suốt để vào bể chứa.","Chúng tôi dùng dây thừng buộc chiếc thuyền vào một cái cột.","Xin hãy thái nhỏ cà rốt trong lúc tôi đun nóng súp.","Một viên ngọc màu xanh lam lấp lánh trên chiếc vòng cổ bằng bạc của cô ấy."]'::jsonb, 1, 'We tied the boat to a post with rope. → Chúng tôi dùng dây thừng buộc chiếc thuyền vào một cái cột.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_7', 'en-b1-49', NULL, 'comprehensive_test', 'listening', 'pour', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cái thang","kỳ lạ; quái lạ; bất thường","tội phạm; tệ nạn tội phạm","rót; đổ; chất lỏng chảy từ vật chứa"]'::jsonb, 3, 'pour (/pɔːr/) → rót; đổ; chất lỏng chảy từ vật chứa; mưa xối xả; mưa tầm tã; tuôn ra; đổ về; di chuyển hoặc đến liên tục với số lượng lớn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_8', 'en-b1-49', NULL, 'comprehensive_test', 'listening', 'Please buy a dozen eggs on your way home.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một quả bí ngô khổng lồ chiếm gần hết chiếc xe đẩy trong vườn.","Cái kệ rộng hơn cái tủ một inh-sơ.","Hãy mua một tá trứng trên đường về nhà nhé.","Khu vườn trông vô cùng rực rỡ dưới ánh nắng ban mai."]'::jsonb, 2, 'Please buy a dozen eggs on your way home. → Hãy mua một tá trứng trên đường về nhà nhé.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_9', 'en-b1-49', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a unit of length equal to 2.54 centimetres”?', '["gorgeous","sour","tube","inch"]'::jsonb, 3, 'inch (/ɪntʃ/) → inh-sơ (đơn vị đo chiều dài bằng 2,54 cm)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
