INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_18', 'en-b1-49', NULL, 'comprehensive_test', 'reading', NULL, 'Disagreements over shared resources can sour relations between neighbouring countries and delay important environmental projects.', 'Dựa vào câu trên, từ “sour” có nghĩa phù hợp nhất là gì?', '["gấp; xếp","người bán thịt; thợ mổ thịt","chua (có vị gắt như chanh)","quả bơ"]'::jsonb, 2, 'sour: chua (có vị gắt như chanh); ôi thiu, chua (có mùi vị khó chịu do bị hỏng); trở nên kém vui, làm xẩu đi (mối quan hệ). Dịch cả câu: Những bất đồng về nguồn lực chung có thể làm xấu đi mối quan hệ giữa các quốc gia láng giềng và làm trì hoãn các dự án môi trường quan trọng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_19', 'en-b1-49', NULL, 'comprehensive_test', 'reading', NULL, 'Children who spend most of their time indoors may have fewer opportunities for physical activity.', 'Dựa vào câu trên, từ “indoors” có nghĩa phù hợp nhất là gì?', '["chị dâu; em dâu; chị chồng; em chồng; chị vợ; em vợ","hải quân","tan chảy; làm tan chảy","ở trong nhà, vào trong nhà (bên trong một tòa nhà)"]'::jsonb, 3, 'indoors: ở trong nhà, vào trong nhà (bên trong một tòa nhà). Dịch cả câu: Trẻ em dành phần lớn thời gian ở trong nhà có thể có ít cơ hội tham gia các hoạt động thể chất hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_20', 'en-b1-49', NULL, 'comprehensive_test', 'reading', NULL, 'Maintaining a regular sleep routine can improve concentration and help students cope with academic pressure.', 'Dựa vào câu trên, từ “routine” có nghĩa phù hợp nhất là gì?', '["bài tập yoga; môn yoga","thói quen; công việc thường ngày; lịch trình thường nhật","gây bối rối; xấu hổ; khó xử","gây ảnh hưởng; tác động đến"]'::jsonb, 1, 'routine: thói quen; công việc thường ngày; lịch trình thường nhật; thường lệ; thông lệ; theo quy chuẩn; bài biểu diễn; bài tập luyện theo động tác cố định. Dịch cả câu: Duy trì thói quen ngủ nghỉ đều đặn có thể cải thiện khả năng tập trung và giúp học sinh đối phó với áp lực học tập.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_21', 'en-b1-49', NULL, 'comprehensive_test', 'reading', NULL, 'Governments can encourage households to switch to renewable energy by offering financial support.', 'Dựa vào câu trên, từ “switch” có nghĩa phù hợp nhất là gì?', '["hiệu quả; có năng suất cao; tiết kiệm (thời gian, năng lượng)","phức tạp; rắc rối","công tắc điện","lặp đi lặp lại; nhiều lần"]'::jsonb, 2, 'switch: công tắc điện; chuyển đổi; thay đổi; sự chuyển đổi; sự thay đổi. Dịch cả câu: Chính phủ có thể khuyến khích các hộ gia đình chuyển sang sử dụng năng lượng tái tạo bằng cách cung cấp hỗ trợ tài chính.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_22', 'en-b1-49', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “câu trả lời; sự đáp lại”', '["response","fox","scenery","volunteer"]'::jsonb, 0, 'câu trả lời; sự đáp lại → response (/rɪˈspɑːns/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_23', 'en-b1-49', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khác với”', '["shoot","comic","locker","unlike"]'::jsonb, 3, 'khác với → unlike (/ˌʌnˈlaɪk/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_49_24', 'en-b1-49', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự giúp đỡ; việc làm ơn”', '["rid","generally","bush","favour"]'::jsonb, 3, 'sự giúp đỡ; việc làm ơn → favour (/ˈfeɪvər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-50', 'en', 'Bài 50: Đời sống hằng ngày (2) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3050, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_underwear', 'en-b1-50', 'underwear', '/ˈʌndərwer/', 'B1', 'đồ lót; trang phục mặc sát da', 'n.', NULL, 'Đồng nghĩa: undergarments', 'Là danh từ không đếm được, không dùng an underwear hay underwears.', 'I packed clean underwear in my travel bag.', NULL, 'Tôi đã xếp vài bộ đồ lót sạch vào túi du lịch của mình.', '{"wordId":"underwear","ukIpa":"/ˈʌndəweə/","usIpa":"/ˈʌndərwer/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Clothes worn next to the skin beneath other clothes.","vi":"đồ lót; trang phục mặc sát da"}],"examples":[{"en":"I packed clean underwear in my travel bag.","vi":"Tôi đã xếp vài bộ đồ lót sạch vào túi du lịch của mình.","audioKind":"ex"},{"en":"Consumers increasingly prefer underwear made from breathable fabrics, encouraging manufacturers to improve comfort and durability.","vi":"Người tiêu dùng ngày càng ưa chuộng đồ lót làm từ chất liệu thoáng khí, qua đó khuyến khích các nhà sản xuất nâng cao độ thoải mái và độ bền.","audioKind":"ex2"}],"collocations":[{"en":"cotton underwear","vi":"đồ lót bằng cotton"},{"en":"thermal underwear","vi":"đồ lót giữ nhiệt"},{"en":"a change of underwear","vi":"một bộ đồ lót thay thế"}],"wordFamily":[],"synonyms":["undergarments"],"antonyms":[],"tipVi":"Là danh từ không đếm được, không dùng an underwear hay underwears.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_queue', 'en-b1-50', 'queue', '/kjuː/', 'B1', 'hàng người chờ đợi; đoàn xe xếp hàng; xếp hàng chờ đến lượt', 'n.', 'queuing (n.)', 'Đồng nghĩa: line', 'Anh-Anh chuộng queue, Anh-Mỹ chuộng line; queue for đi kèm với thứ đang chờ.', 'We joined the queue outside the bakery this morning.', NULL, 'Sáng nay chúng tôi đã nhập hội xếp hàng ở ngoài tiệm bánh.', '{"wordId":"queue","ukIpa":"/kjuː/","usIpa":"/kjuː/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A line of people or vehicles waiting for something.","vi":"hàng người chờ đợi; đoàn xe xếp hàng"},{"pos":"v.","en":"To wait in a line for your turn.","vi":"xếp hàng chờ đến lượt"}],"examples":[{"en":"We joined the queue outside the bakery this morning.","vi":"Sáng nay chúng tôi đã nhập hội xếp hàng ở ngoài tiệm bánh.","audioKind":"ex"},{"en":"Improved ticketing systems can reduce the time passengers spend waiting in a queue at busy stations.","vi":"Hệ thống bán vé được cải tiến có thể làm giảm thời gian hành khách phải đứng xếp hàng ở các nhà ga đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"join the queue","vi":"vào hàng chờ"},{"en":"queue for tickets","vi":"xếp hàng mua vé"},{"en":"jump the queue","vi":"chen hàng; cắt ngang hàng"},{"en":"a long queue","vi":"một hàng dài"}],"wordFamily":["queuing (n.)"],"synonyms":["line"],"antonyms":[],"tipVi":"Anh-Anh chuộng queue, Anh-Mỹ chuộng line; queue for đi kèm với thứ đang chờ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lighter', 'en-b1-50', 'lighter', '/ˈlaɪtər/', 'B1', 'bật lửa; thiết bị tạo lửa', 'n.', 'light (v.), lighting (n.)', NULL, 'Là danh từ chỉ bật lửa; ngoài ra còn là dạng so sánh hơn của light mang nghĩa nhẹ hơn.', 'Dad used a long lighter to light the candle.', NULL, 'Bố đã dùng một chiếc bật lửa cán dài để thắp nến.', '{"wordId":"lighter","ukIpa":"/ˈlaɪtə/","usIpa":"/ˈlaɪtər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A small device that produces a flame to light things.","vi":"bật lửa; thiết bị tạo lửa"}],"examples":[{"en":"Dad used a long lighter to light the candle.","vi":"Bố đã dùng một chiếc bật lửa cán dài để thắp nến.","audioKind":"ex"},{"en":"A refillable lighter may produce less plastic waste than disposable alternatives when used over a long period.","vi":"Sử dụng bật lửa có thể châm thêm nhiên liệu trong thời gian dài có thể thải ra ít rác thải nhựa hơn so với các loại dùng một lần.","audioKind":"ex2"}],"collocations":[{"en":"a refillable lighter","vi":"bật lửa châm lại được"},{"en":"a disposable lighter","vi":"bật lửa dùng một lần"},{"en":"a gas lighter","vi":"bật lửa dùng gas"}],"wordFamily":["light (v.)","lighting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ chỉ bật lửa; ngoài ra còn là dạng so sánh hơn của light mang nghĩa nhẹ hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_handsome', 'en-b1-50', 'handsome', '/ˈhænsəm/', 'B1', 'đẹp trai; khôi ngô; lớn; hậu hĩnh; đáng kể', 'adj.', 'handsomely (adv.), handsomeness (n.)', 'Đồng nghĩa: good-looking, attractive · Trái nghĩa: unattractive', 'Thường dùng để tả nam giới có ngoại hình đẹp; khi dùng cho lợi nhuận hoặc phần thưởng thì mang nghĩa hậu hĩnh, lớn lao.', 'My brother looks handsome in his new blue jacket.', NULL, 'Anh trai tôi trông rất bảnh bao trong chiếc áo khoác màu xanh mới.', '{"wordId":"handsome","ukIpa":"/ˈhænsəm/","usIpa":"/ˈhænsəm/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Attractive in appearance, especially describing a man.","vi":"đẹp trai; khôi ngô"},{"pos":"adj.","en":"Large and impressive in amount.","vi":"lớn; hậu hĩnh; đáng kể"}],"examples":[{"en":"My brother looks handsome in his new blue jacket.","vi":"Anh trai tôi trông rất bảnh bao trong chiếc áo khoác màu xanh mới.","audioKind":"ex"},{"en":"Companies investing in renewable energy may earn handsome profits as demand for cleaner alternatives continues to grow.","vi":"Các công ty đầu tư vào năng lượng tái tạo có thể thu về lợi nhuận khổng lồ khi nhu cầu về các nguồn năng lượng sạch tiếp tục gia tăng.","audioKind":"ex2"}],"collocations":[{"en":"handsome man","vi":"người đàn ông đẹp trai"},{"en":"handsome profit","vi":"lợi nhuận kếch xù"},{"en":"handsome reward","vi":"khoản thù lao hậu hĩnh"}],"wordFamily":["handsomely (adv.)","handsomeness (n.)"],"synonyms":["good-looking","attractive"],"antonyms":["unattractive"],"tipVi":"Thường dùng để tả nam giới có ngoại hình đẹp; khi dùng cho lợi nhuận hoặc phần thưởng thì mang nghĩa hậu hĩnh, lớn lao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_terribly', 'en-b1-50', 'terribly', '/ˈterəbli/', 'B1', 'rất; cực kỳ; trầm trọng; tồi tệ', 'adv.', 'terrible (adj.)', 'Đồng nghĩa: extremely, awfully', 'Thường dùng trong văn nói để nhấn mạnh, không phải lúc nào cũng mang nghĩa ''một cách đáng sợ''.', 'I''m terribly sorry I spilled juice on your jacket.', NULL, 'Tôi cực kỳ xin lỗi vì đã làm đổ nước trái cây lên áo khoác của bạn.', '{"wordId":"terribly","ukIpa":"/ˈterəbli/","usIpa":"/ˈterəbli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"To a very great degree.","vi":"rất; cực kỳ"},{"pos":"adv.","en":"In a very bad or unsuccessful way.","vi":"trầm trọng; tồi tệ"}],"examples":[{"en":"I''m terribly sorry I spilled juice on your jacket.","vi":"Tôi cực kỳ xin lỗi vì đã làm đổ nước trái cây lên áo khoác của bạn.","audioKind":"ex"},{"en":"Without reliable public transport, elderly residents may feel terribly isolated in remote rural communities.","vi":"Nếu không có hệ thống giao thông công cộng đáng tin cậy, cư dân cao tuổi ở các vùng nông thôn hẻo lánh có thể cảm thấy vô cùng cô lập.","audioKind":"ex2"}],"collocations":[{"en":"terribly sorry","vi":"vô cùng xin lỗi"},{"en":"terribly worried","vi":"vô cùng lo lắng"},{"en":"behave terribly","vi":"cư xử tồi tệ"}],"wordFamily":["terrible (adj.)"],"synonyms":["extremely","awfully"],"antonyms":[],"tipVi":"Thường dùng trong văn nói để nhấn mạnh, không phải lúc nào cũng mang nghĩa ''một cách đáng sợ''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mend', 'en-b1-50', 'mend', '/mend/', 'B1', 'sửa chữa; vá; chữa lành; hồi phục; cải thiện; hàn gắn (mối quan hệ)', 'v.', 'mending (n.)', 'Đồng nghĩa: repair, fix · Trái nghĩa: damage', 'Cụm từ ''on the mend'' có nghĩa là đang hồi phục hoặc tình hình đang chuyển biến tốt hơn.', 'Grandpa showed me how to mend a torn pocket.', NULL, 'Ông đã dạy tôi cách vá cái túi áo bị rách.', '{"wordId":"mend","ukIpa":"/mend/","usIpa":"/mend/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To make something broken or damaged usable again.","vi":"sửa chữa; vá"},{"pos":"v.","en":"To become healthy again after injury or illness.","vi":"chữa lành; hồi phục"},{"pos":"v.","en":"To improve a damaged relationship or a difficult situation.","vi":"cải thiện; hàn gắn (mối quan hệ)"}],"examples":[{"en":"Grandpa showed me how to mend a torn pocket.","vi":"Ông đã dạy tôi cách vá cái túi áo bị rách.","audioKind":"ex"},{"en":"Teaching children to mend their clothes can reduce textile waste and encourage more responsible attitudes towards consumption.","vi":"Dạy trẻ em tự sửa chữa quần áo có thể làm giảm lượng rác thải dệt may và khuyến khích thái độ tiêu dùng có trách nhiệm hơn.","audioKind":"ex2"}],"collocations":[{"en":"mend clothes","vi":"vá quần áo"},{"en":"mend a fence","vi":"sửa hàng rào"},{"en":"mend relations","vi":"hàn gắn quan hệ"},{"en":"on the mend","vi":"đang hồi phục"}],"wordFamily":["mending (n.)"],"synonyms":["repair","fix"],"antonyms":["damage"],"tipVi":"Cụm từ ''on the mend'' có nghĩa là đang hồi phục hoặc tình hình đang chuyển biến tốt hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bury', 'en-b1-50', 'bury', '/ˈberi/', 'B1', 'chôn; chôn cất; giấu; vùi lấp', 'v.', 'burial (n.)', 'Trái nghĩa: unearth', 'Phát âm giống berry; dạng quá khứ là buried, danh động từ là burying.', 'Our dog buried its favourite toy beside the fence.', NULL, 'Con chó của chúng tôi đã giấu món đồ chơi yêu thích của nó bên cạnh hàng rào.', '{"wordId":"bury","ukIpa":"/ˈberi/","usIpa":"/ˈberi/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to put something in the ground and cover it","vi":"chôn; chôn cất"},{"pos":"v.","en":"to hide or cover something beneath other things","vi":"giấu; vùi lấp"}],"examples":[{"en":"Our dog buried its favourite toy beside the fence.","vi":"Con chó của chúng tôi đã giấu món đồ chơi yêu thích của nó bên cạnh hàng rào.","audioKind":"ex"},{"en":"Instead of burying household waste, local authorities should invest in recycling facilities and public education.","vi":"Thay vì chôn lấp rác thải sinh hoạt, chính quyền địa phương nên đầu tư vào các cơ sở tái chế và giáo dục cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"bury treasure","vi":"chôn giấu kho báu"},{"en":"bury waste","vi":"chôn lấp rác thải"},{"en":"be buried under","vi":"bị vùi lấp dưới..."},{"en":"bury your face in","vi":"vùi mặt vào..."}],"wordFamily":["burial (n.)"],"synonyms":[],"antonyms":["unearth"],"tipVi":"Phát âm giống berry; dạng quá khứ là buried, danh động từ là burying.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attach', 'en-b1-50', 'attach', '/əˈtætʃ/', 'B1', 'gắn; dán; đính kèm; gán cho; coi trọng', 'v.', 'attachment (n.), attached (adj.), unattached (adj.)', 'Đồng nghĩa: fasten, affix · Trái nghĩa: detach', 'Thường dùng cấu trúc attach A to B; tệp đính kèm trong email dùng attachment.', 'Attach the little bell to your bicycle''s handlebars.', NULL, 'Hãy gắn chiếc chuông nhỏ vào tay lái xe đạp của bạn.', '{"wordId":"attach","ukIpa":"/əˈtætʃ/","usIpa":"/əˈtætʃ/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Join or fasten something to something else","vi":"gắn; dán; đính kèm"},{"pos":"v.","en":"Consider something to have a particular value or importance","vi":"gán cho; coi trọng"}],"examples":[{"en":"Attach the little bell to your bicycle''s handlebars.","vi":"Hãy gắn chiếc chuông nhỏ vào tay lái xe đạp của bạn.","audioKind":"ex"},{"en":"Many employers attach greater importance to practical experience than to academic qualifications when recruiting new staff.","vi":"Nhiều nhà tuyển dụng coi trọng kinh nghiệm thực tế hơn là bằng cấp học thuật khi tuyển dụng nhân viên mới.","audioKind":"ex2"}],"collocations":[{"en":"attach a file","vi":"đính kèm tệp"},{"en":"attach something to something","vi":"gắn vật gì vào vật gì"},{"en":"attach importance to","vi":"coi trọng; đánh giá cao"}],"wordFamily":["attachment (n.)","attached (adj.)","unattached (adj.)"],"synonyms":["fasten","affix"],"antonyms":["detach"],"tipVi":"Thường dùng cấu trúc attach A to B; tệp đính kèm trong email dùng attachment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_base', 'en-b1-50', 'base', '/beɪs/', 'B1', 'chân đế; nền tảng; cơ sở; căn cứ; lấy làm cơ sở; dựa vào', 'n.', 'basic (adj.), basically (adv.), basis (n.)', NULL, 'Cấu trúc base A on B có nghĩa là "lấy B làm cơ sở để thiết lập A".', 'The heavy base keeps the lamp from falling over.', NULL, 'Phần đế nặng giúp chiếc đèn không bị đổ.', '{"wordId":"base","ukIpa":"/beɪs/","usIpa":"/beɪs/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The lowest supporting part or underlying foundation of something.","vi":"chân đế; nền tảng"},{"pos":"n.","en":"A place from which people work or organise activities.","vi":"cơ sở; căn cứ"},{"pos":"v.","en":"To use something as the foundation for a decision or idea.","vi":"lấy làm cơ sở; dựa vào"}],"examples":[{"en":"The heavy base keeps the lamp from falling over.","vi":"Phần đế nặng giúp chiếc đèn không bị đổ.","audioKind":"ex"},{"en":"Governments should base their environmental policies on reliable scientific evidence rather than short-term political interests.","vi":"Chính phủ nên dựa các chính sách môi trường của mình vào các bằng chứng khoa học đáng tin cậy thay vì lợi ích chính trị ngắn hạn.","audioKind":"ex2"}],"collocations":[{"en":"the base of","vi":"chân của..."},{"en":"base something on","vi":"dựa cái gì vào..."},{"en":"a research base","vi":"cơ sở nghiên cứu"},{"en":"a solid base","vi":"nền tảng vững chắc"}],"wordFamily":["basic (adj.)","basically (adv.)","basis (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc base A on B có nghĩa là \"lấy B làm cơ sở để thiết lập A\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_receipt', 'en-b1-50', 'receipt', '/rɪˈsiːt/', 'B1', 'biên lai; giấy biên nhận; sự nhận được; việc tiếp nhận; khoản thu; doanh thu', 'n.', 'receive (v.), receiver (n.)', NULL, 'Chữ p câm không phát âm; khi chỉ tiền thu vào thường dùng dạng số nhiều receipts.', 'Keep your receipt in case the shoes don''t fit.', NULL, 'Hãy giữ lại biên lai của bạn phòng khi đôi giày không vừa.', '{"wordId":"receipt","ukIpa":"/rɪˈsiːt/","usIpa":"/rɪˈsiːt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a document showing that something has been paid for","vi":"biên lai; giấy biên nhận"},{"pos":"n.","en":"the act of receiving something","vi":"sự nhận được; việc tiếp nhận"},{"pos":"n.","en":"money received by a business or organisation","vi":"khoản thu; doanh thu"}],"examples":[{"en":"Keep your receipt in case the shoes don''t fit.","vi":"Hãy giữ lại biên lai của bạn phòng khi đôi giày không vừa.","audioKind":"ex"},{"en":"Businesses should issue a receipt for every purchase to protect consumers and maintain accurate financial records.","vi":"Doanh nghiệp nên cấp biên lai cho mọi giao dịch mua hàng để bảo vệ người tiêu dùng và duy trì hồ sơ tài chính chính xác.","audioKind":"ex2"}],"collocations":[{"en":"keep the receipt","vi":"giữ lại biên lai"},{"en":"issue a receipt","vi":"cấp biên lai"},{"en":"on receipt of","vi":"khi nhận được"},{"en":"tax receipts","vi":"khoản thu thuế"}],"wordFamily":["receive (v.)","receiver (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ p câm không phát âm; khi chỉ tiền thu vào thường dùng dạng số nhiều receipts.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_object', 'en-b1-50', 'object', '/ˈɑːbdʒekt/; /əbˈdʒekt/', 'B1', 'vật; đồ vật; phản đối; mục đích; mục tiêu', 'n.', 'objection (n.), objector (n.)', NULL, 'Danh từ trọng âm ở âm tiết đầu, động từ ở âm tiết sau; object to đi với danh từ hoặc danh động từ.', 'A shiny object was lying beneath the sofa.', NULL, 'Có một vật sáng lấp lánh nằm dưới chiếc ghế sofa.', '{"wordId":"object","ukIpa":"/ˈɒbdʒɪkt/; /əbˈdʒekt/","usIpa":"/ˈɑːbdʒekt/; /əbˈdʒekt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a thing that can be seen or touched","vi":"vật; đồ vật"},{"pos":"v.","en":"to express disagreement with something","vi":"phản đối"},{"pos":"n.","en":"the aim of an action or activity","vi":"mục đích; mục tiêu"}],"examples":[{"en":"A shiny object was lying beneath the sofa.","vi":"Có một vật sáng lấp lánh nằm dưới chiếc ghế sofa.","audioKind":"ex"},{"en":"Many residents object to the proposed airport expansion because it could increase noise pollution.","vi":"Nhiều người dân phản đối kế hoạch mở rộng sân bay vì nó có thể làm tăng ô nhiễm tiếng ồn.","audioKind":"ex2"}],"collocations":[{"en":"a physical object","vi":"một vật thể vật lý"},{"en":"object to a proposal","vi":"phản đối một đề xuất"},{"en":"the object of the exercise","vi":"mục đích của bài tập này"}],"wordFamily":["objection (n.)","objector (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ trọng âm ở âm tiết đầu, động từ ở âm tiết sau; object to đi với danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_essential', 'en-b1-50', 'essential', '/ɪˈsenʃəl/', 'B1', 'cực kỳ cần thiết; thiết yếu; thuộc bản chất; cơ bản; mặt hàng thiết yếu; yếu tố cơ bản', 'adj.', 'essentially (adv.), essence (n.), nonessential (adj.)', 'Đồng nghĩa: necessary, vital, indispensable · Trái nghĩa: unnecessary, optional', 'Danh từ thường dùng ở dạng số nhiều essentials, chỉ các mặt hàng thiết yếu hoặc điểm cốt lõi.', 'A warm coat is essential for this winter walk.', NULL, 'Một chiếc áo khoác ấm là thứ thiết yếu cho buổi đi dạo mùa đông này.', '{"wordId":"essential","ukIpa":"/ɪˈsenʃəl/","usIpa":"/ɪˈsenʃəl/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Completely necessary for a particular purpose or situation","vi":"cực kỳ cần thiết; thiết yếu"},{"pos":"adj.","en":"Relating to the most important characteristics of something","vi":"thuộc bản chất; cơ bản"},{"pos":"n.","en":"A necessary item or basic fact, usually mentioned in plural","vi":"mặt hàng thiết yếu; yếu tố cơ bản"}],"examples":[{"en":"A warm coat is essential for this winter walk.","vi":"Một chiếc áo khoác ấm là thứ thiết yếu cho buổi đi dạo mùa đông này.","audioKind":"ex"},{"en":"Access to clean drinking water is essential for preventing disease and improving public health.","vi":"Việc tiếp cận nguồn nước uống sạch là tối quan trọng để phòng ngừa bệnh tật và nâng cao sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"essential for survival","vi":"cần thiết cho sự sinh tồn"},{"en":"essential services","vi":"các dịch vụ thiết yếu"},{"en":"essential equipment","vi":"thiết bị thiết yếu"},{"en":"daily essentials","vi":"nhu yếu phẩm hàng ngày"}],"wordFamily":["essentially (adv.)","essence (n.)","nonessential (adj.)"],"synonyms":["necessary","vital","indispensable"],"antonyms":["unnecessary","optional"],"tipVi":"Danh từ thường dùng ở dạng số nhiều essentials, chỉ các mặt hàng thiết yếu hoặc điểm cốt lõi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stir', 'en-b1-50', 'stir', '/stɝː/', 'B1', 'khuấy; trộn; khơi dậy; gợi lên; sự náo động; sự xôn xao', 'v.', 'stirrer (n.), stirring (adj.)', NULL, 'Quá khứ stirred, phân từ hiện đại stirring đều nhân đôi chữ r.', 'Stir the soup gently so it does not stick.', NULL, 'Khuấy canh nhẹ nhàng để không bị dính đáy nồi.', '{"wordId":"stir","ukIpa":"/stɜː/","usIpa":"/stɝː/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To mix something by moving a spoon or similar object around.","vi":"khuấy; trộn"},{"pos":"v.","en":"To cause a strong feeling or reaction.","vi":"khơi dậy; gợi lên"},{"pos":"n.","en":"Excitement or surprise caused by an event or action.","vi":"sự náo động; sự xôn xao"}],"examples":[{"en":"Stir the soup gently so it does not stick.","vi":"Khuấy canh nhẹ nhàng để không bị dính đáy nồi.","audioKind":"ex"},{"en":"Documentaries about endangered animals can stir public concern and encourage stronger support for wildlife conservation.","vi":"Các bộ phim tài liệu về động vật có nguy cơ tuyệt chủng có thể khơi dậy sự quan tâm của công chúng và thúc đẩy sự ủng hộ mạnh mẽ hơn đối với công tác bảo <i>tồn động vật hoang dã.</i>","audioKind":"ex2"}],"collocations":[{"en":"stir well","vi":"khuấy đều"},{"en":"stir in","vi":"khuấy đều để hòa tan"},{"en":"cause a stir","vi":"gây tiếng vang lớn; gây xôn xao"},{"en":"stir up trouble","vi":"gây chuyện; gây rối"}],"wordFamily":["stirrer (n.)","stirring (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ stirred, phân từ hiện đại stirring đều nhân đôi chữ r.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shoot', 'en-b1-50', 'shoot', '/ʃuːt/', 'B1', 'bắn; nã đạn; quay phim; chụp ảnh; chồi non; lộc mới', 'v.', 'shooting (n.), shooter (n.)', NULL, 'Quá khứ và phân từ hai đều là shot; shoot at chỉ hành động nhằm vào ai/cái gì để bắn.', 'She learned to shoot arrows at a local club.', NULL, 'Cô ấy học bắn cung tại một câu lạc bộ địa phương.', '{"wordId":"shoot","ukIpa":"/ʃuːt/","usIpa":"/ʃuːt/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Fire a gun or another weapon; hit with a bullet","vi":"bắn; nã đạn"},{"pos":"v.","en":"Take photographs or record a film","vi":"quay phim; chụp ảnh"},{"pos":"n.","en":"A new part growing from a plant","vi":"chồi non; lộc mới"}],"examples":[{"en":"She learned to shoot arrows at a local club.","vi":"Cô ấy học bắn cung tại một câu lạc bộ địa phương.","audioKind":"ex"},{"en":"Film crews often shoot documentaries in remote locations to highlight the effects of climate change.","vi":"Các đoàn làm phim thường quay phim tài liệu ở các vùng hẻo lánh nhằm làm nổi bật tác động của biến đổi khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"shoot a film","vi":"quay phim"},{"en":"shoot an arrow","vi":"bắn một mũi tên"},{"en":"a young shoot","vi":"chồi non"}],"wordFamily":["shooting (n.)","shooter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ và phân từ hai đều là shot; shoot at chỉ hành động nhằm vào ai/cái gì để bắn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cutlery', 'en-b1-50', 'cutlery', '/ˈkʌtləri/', 'B1', 'bộ đồ ăn (dao, nĩa, thìa)', 'n.', NULL, NULL, 'Là danh từ không đếm được; để chỉ một món/chiếc dụng cụ ăn uống dùng a piece of cutlery.', 'Please put the clean cutlery beside the plates.', NULL, 'Xin hãy đặt bộ dao nĩa sạch bên cạnh các đĩa ăn.', '{"wordId":"cutlery","ukIpa":"/ˈkʌtləri/","usIpa":"/ˈkʌtləri/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Knives, forks, and spoons used for eating or serving food.","vi":"bộ đồ ăn (dao, nĩa, thìa)"}],"examples":[{"en":"Please put the clean cutlery beside the plates.","vi":"Xin hãy đặt bộ dao nĩa sạch bên cạnh các đĩa ăn.","audioKind":"ex"},{"en":"Restaurants can reduce plastic waste by replacing disposable cutlery with durable alternatives that can be washed and reused.","vi":"Các nhà hàng có thể giảm thiểu rác thải nhựa bằng cách thay thế dao nĩa dùng một lần bằng các sản phẩm bền có thể rửa sạch và tái sử dụng.","audioKind":"ex2"}],"collocations":[{"en":"a set of cutlery","vi":"một bộ dao nĩa"},{"en":"disposable cutlery","vi":"dao nĩa dùng một lần"},{"en":"stainless steel cutlery","vi":"dao nĩa bằng thép không gỉ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ không đếm được; để chỉ một món/chiếc dụng cụ ăn uống dùng a piece of cutlery.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nor', 'en-b1-50', 'nor', '/nɔːr/', 'B1', 'cũng không; cũng chẳng', 'conj.', NULL, NULL, 'nor kết nối các mệnh đề độc lập thường có cấu trúc đảo ngữ: nor do I.', 'I could neither find my keys nor remember where I parked.', NULL, 'Tôi vừa không tìm thấy chìa khóa, vừa chẳng nhớ mình đã đỗ xe ở đâu.', '{"wordId":"nor","ukIpa":"/nɔː/","usIpa":"/nɔːr/","cefr":"B1","topic":"daily","senses":[{"pos":"conj.","en":"used to add another negative statement or alternative","vi":"cũng không; cũng chẳng"}],"examples":[{"en":"I could neither find my keys nor remember where I parked.","vi":"Tôi vừa không tìm thấy chìa khóa, vừa chẳng nhớ mình đã đỗ xe ở đâu.","audioKind":"ex"},{"en":"Expanding roads alone will neither solve traffic congestion nor reduce the environmental damage caused by private vehicles.","vi":"Việc chỉ mở rộng đường sá sẽ vừa không giải quyết được tình trạng tắc nghẽn giao thông, vừa chẳng giảm thiểu được tổn hại môi trường do các phương tiện cá nhân gây ra.","audioKind":"ex2"}],"collocations":[{"en":"neither ... nor ...","vi":"cũng không... cũng chẳng..."},{"en":"nor do I","vi":"tôi cũng vậy"},{"en":"nor can we","vi":"chúng ta cũng không thể"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"nor kết nối các mệnh đề độc lập thường có cấu trúc đảo ngữ: nor do I.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_woollen', 'en-b1-50', 'woollen', '/ˈwʊlən/', 'B1', 'bằng len; làm từ len', 'adj.', 'wool (n.), woolly (adj.)', NULL, 'Cách viết theo tiếng Anh-Anh là woollen; tiếng Anh-Mỹ thường viết là woolen.', 'I pulled on thick woollen socks before going outside.', NULL, 'Tôi kéo vớ len dày lên trước khi bước ra ngoài.', '{"wordId":"woollen","ukIpa":"/ˈwʊlən/","usIpa":"/ˈwʊlən/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Made from wool.","vi":"bằng len; làm từ len"}],"examples":[{"en":"I pulled on thick woollen socks before going outside.","vi":"Tôi kéo vớ len dày lên trước khi bước ra ngoài.","audioKind":"ex"},{"en":"Although woollen clothing provides excellent insulation, its environmental impact depends partly on farming practices and manufacturing methods.","vi":"Mặc dù trang phục bằng len mang lại khả năng giữ nhiệt tuyệt vời, tác động môi trường của chúng phần nào phụ thuộc vào phương pháp chăn nuôi và quy trình sản xuất.","audioKind":"ex2"}],"collocations":[{"en":"a woollen jumper","vi":"một chiếc áo len chui đầu"},{"en":"woollen socks","vi":"vớ len"},{"en":"a woollen blanket","vi":"một chiếc chăn len"}],"wordFamily":["wool (n.)","woolly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết theo tiếng Anh-Anh là woollen; tiếng Anh-Mỹ thường viết là woolen.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jug', 'en-b1-50', 'jug', '/dʒʌɡ/', 'B1', 'bình rót nước; cái vại; lượng chứa trong một bình', 'n.', NULL, NULL, 'Tiếng Anh-Anh thường chỉ bình miệng rộng có vòi; tiếng Anh-Mỹ thường chỉ bình có cổ hẹp và có tay cầm.', 'Please bring a jug of water to the table.', NULL, 'Làm ơn mang một bình nước ra bàn giúp tôi.', '{"wordId":"jug","ukIpa":"/dʒʌɡ/","usIpa":"/dʒʌɡ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A handled container used for holding and pouring liquids.","vi":"bình rót nước; cái vại"},{"pos":"n.","en":"The amount of liquid a jug holds.","vi":"lượng chứa trong một bình"}],"examples":[{"en":"Please bring a jug of water to the table.","vi":"Làm ơn mang một bình nước ra bàn giúp tôi.","audioKind":"ex"},{"en":"Serving tap water in a reusable jug can help restaurants reduce their reliance on disposable plastic bottles.","vi":"Việc phục vụ nước máy trong một chiếc bình có thể dùng lại giúp các nhà hàng giảm bớt sự phụ thuộc vào chai nhựa dùng một lần.","audioKind":"ex2"}],"collocations":[{"en":"a jug of water","vi":"một bình nước"},{"en":"milk jug","vi":"bình đựng sữa"},{"en":"fill a jug","vi":"đầy một bình"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Anh thường chỉ bình miệng rộng có vòi; tiếng Anh-Mỹ thường chỉ bình có cổ hẹp và có tay cầm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fashionable', 'en-b1-50', 'fashionable', '/ˈfæʃənəbl/', 'B1', 'hợp thời trang; sành điệu', 'adj.', 'fashion (n.), fashionably (adv.), unfashionable (adj.)', 'Đồng nghĩa: trendy, stylish · Trái nghĩa: unfashionable, outdated', 'Không chỉ dùng để mô tả trang phục, từ này còn có thể dùng cho quan niệm, hoạt động hoặc khu vực.', 'Those colourful trainers are fashionable among my friends.', NULL, 'Đôi giày thể thao đầy màu sắc đó rất được bạn bè tôi ưa chuộng.', '{"wordId":"fashionable","ukIpa":"/ˈfæʃənəbl/","usIpa":"/ˈfæʃənəbl/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Popular or considered attractive at a particular time.","vi":"hợp thời trang; sành điệu"}],"examples":[{"en":"Those colourful trainers are fashionable among my friends.","vi":"Đôi giày thể thao đầy màu sắc đó rất được bạn bè tôi ưa chuộng.","audioKind":"ex"},{"en":"Consumers often replace fashionable clothing quickly, increasing textile waste and placing pressure on natural resources.","vi":"Người tiêu dùng thường nhanh chóng thay thế quần áo hợp thời trang, làm gia tăng lượng rác thải dệt may và gây áp lực lên tài nguyên thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"fashionable clothes","vi":"quần áo hợp thời trang"},{"en":"a fashionable district","vi":"một khu phố sành điệu"},{"en":"become fashionable","vi":"trở nên thịnh hành"}],"wordFamily":["fashion (n.)","fashionably (adv.)","unfashionable (adj.)"],"synonyms":["trendy","stylish"],"antonyms":["unfashionable","outdated"],"tipVi":"Không chỉ dùng để mô tả trang phục, từ này còn có thể dùng cho quan niệm, hoạt động hoặc khu vực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cracker', 'en-b1-50', 'cracker', '/ˈkrækər/', 'B1', 'bánh quy giòn mỏng', 'n.', NULL, NULL, 'Thường chỉ loại bánh quy mỏng và giòn, không nhất thiết phải là bánh soda.', 'I packed some crackers and cheese for the picnic.', NULL, 'Tôi đã chuẩn bị ít bánh quy giòn và phô mai cho buổi dã ngoại.', '{"wordId":"cracker","ukIpa":"/ˈkrækə/","usIpa":"/ˈkrækər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a thin, crisp biscuit, often eaten with cheese","vi":"bánh quy giòn mỏng"}],"examples":[{"en":"I packed some crackers and cheese for the picnic.","vi":"Tôi đã chuẩn bị ít bánh quy giòn và phô mai cho buổi dã ngoại.","audioKind":"ex"},{"en":"Although crackers are convenient snacks, some varieties contain substantial amounts of salt and should be eaten in moderation.","vi":"Mặc dù bánh quy giòn là món ăn nhẹ tiện lợi, nhưng một số loại chứa hàm lượng muối đáng kể và nên được ăn điều độ.","audioKind":"ex2"}],"collocations":[{"en":"cheese and crackers","vi":"phô mai và bánh quy giòn"},{"en":"salted crackers","vi":"bánh quy giòn vị mặn"},{"en":"wholegrain crackers","vi":"bánh quy giòn nguyên cám"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ loại bánh quy mỏng và giòn, không nhất thiết phải là bánh soda.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trick', 'en-b1-50', 'trick', '/trɪk/', 'B1', 'mưu mẹo; trò lừa bịp; mẹo hay; trò ảo thuật; lừa gạt; dụ dỗ', 'n.', 'tricky (adj.), trickery (n.), trickster (n.)', NULL, 'Cấu trúc trick sb into doing sth có nghĩa là lừa phỉnh ai đó làm việc gì.', 'Someone played a trick on me with a plastic spider.', NULL, 'Ai đó đã chơi trò khăm tôi bằng một con nhện nhựa.', '{"wordId":"trick","ukIpa":"/trɪk/","usIpa":"/trɪk/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"an action intended to deceive someone or make them look foolish","vi":"mưu mẹo; trò lừa bịp"},{"pos":"n.","en":"a clever technique or an act that seems magical","vi":"mẹo hay; trò ảo thuật"},{"pos":"v.","en":"to deceive someone into believing or doing something","vi":"lừa gạt; dụ dỗ"}],"examples":[{"en":"Someone played a trick on me with a plastic spider.","vi":"Ai đó đã chơi trò khăm tôi bằng một con nhện nhựa.","audioKind":"ex"},{"en":"Some online advertisements trick consumers into paying for services they initially believed were free.","vi":"Một số quảng cáo trực tuyến lừa người tiêu dùng phải trả tiền cho các dịch vụ mà ban đầu họ tưởng là miễn phí.","audioKind":"ex2"}],"collocations":[{"en":"play a trick on someone","vi":"chơi khăm ai đó"},{"en":"trick someone into doing something","vi":"lừa ai đó làm việc gì"},{"en":"a magic trick","vi":"trò ảo thuật"},{"en":"the trick to doing something","vi":"bí quyết để làm việc gì đó"}],"wordFamily":["tricky (adj.)","trickery (n.)","trickster (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc trick sb into doing sth có nghĩa là lừa phỉnh ai đó làm việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_advise', 'en-b1-50', 'advise', '/ədˈvaɪz/', 'B1', 'khuyên; khuyên bảo; thông báo chính thức', 'v.', 'advice (n.), adviser (n.), advisory (adj.)', 'Đồng nghĩa: recommend, counsel', 'advise là động từ; advice là danh từ không đếm được, tận cùng phát âm là /s/.', 'The doctor advised me to rest for a few days.', NULL, 'Bác sĩ khuyên tôi nên nghỉ ngơi vài ngày.', '{"wordId":"advise","ukIpa":"/ədˈvaɪz/","usIpa":"/ədˈvaɪz/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Tell someone what you think they should do","vi":"khuyên; khuyên bảo"},{"pos":"v.","en":"Officially give someone information about something","vi":"thông báo chính thức"}],"examples":[{"en":"The doctor advised me to rest for a few days.","vi":"Bác sĩ khuyên tôi nên nghỉ ngơi vài ngày.","audioKind":"ex"},{"en":"Schools should advise students on career options before they choose subjects for further study.","vi":"Nhà trường nên tư vấn cho học sinh về các lựa chọn nghề nghiệp trước khi các em chọn môn học để học lên cao.","audioKind":"ex2"}],"collocations":[{"en":"advise someone to do something","vi":"khuyên ai đó làm gì"},{"en":"advise against","vi":"khuyên không nên làm gì"},{"en":"advise on","vi":"tư vấn về; khuyên về"},{"en":"strongly advise","vi":"kịch liệt khuyên; khuyên chân thành"}],"wordFamily":["advice (n.)","adviser (n.)","advisory (adj.)"],"synonyms":["recommend","counsel"],"antonyms":[],"tipVi":"advise là động từ; advice là danh từ không đếm được, tận cùng phát âm là /s/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_overcoat', 'en-b1-50', 'overcoat', '/ˈoʊvərkoʊt/', 'B1', 'áo khoác dài; áo măng-tô', 'n.', NULL, NULL, 'overcoat thường chỉ loại áo khoác ngoài dài để giữ ấm mặc chồng lên các trang phục khác.', 'He pulled on his overcoat before stepping into the snow.', NULL, 'Anh ấy mặc áo khoác dài lên rồi bước ra ngoài trời có tuyết.', '{"wordId":"overcoat","ukIpa":"/ˈəʊvəkəʊt/","usIpa":"/ˈoʊvərkoʊt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a long warm coat worn over other clothes","vi":"áo khoác dài; áo măng-tô"}],"examples":[{"en":"He pulled on his overcoat before stepping into the snow.","vi":"Anh ấy mặc áo khoác dài lên rồi bước ra ngoài trời có tuyết.","audioKind":"ex"},{"en":"Donating an unused overcoat to a local charity can help someone stay warm during winter.","vi":"Việc tặng một chiếc áo khoác dài không dùng đến cho tổ chức từ thiện địa phương có thể giúp ai đó giữ ấm trong mùa đông.","audioKind":"ex2"}],"collocations":[{"en":"a wool overcoat","vi":"áo khoác dạ dài"},{"en":"a heavy overcoat","vi":"áo khoác dày"},{"en":"put on an overcoat","vi":"mặc áo khoác dài"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"overcoat thường chỉ loại áo khoác ngoài dài để giữ ấm mặc chồng lên các trang phục khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weigh', 'en-b1-50', 'weigh', '/weɪ/', 'B1', 'cân; đo trọng lượng; nặng (bao nhiêu); cân nhắc; suy tính kỹ lưỡng', 'v.', 'weight (n.), weighty (adj.)', 'Đồng nghĩa: measure, consider', 'weigh là động từ, còn weight là danh từ; khi diễn tả vật nặng bao nhiêu thì không dùng thể bị động.', 'Please weigh these apples before putting them in the bag.', NULL, 'Xin vui lòng cân số táo này trước khi cho vào túi.', '{"wordId":"weigh","ukIpa":"/weɪ/","usIpa":"/weɪ/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to measure how heavy someone or something is","vi":"cân; đo trọng lượng"},{"pos":"v.","en":"to have a particular weight","vi":"nặng (bao nhiêu)"},{"pos":"v.","en":"to consider something carefully before making a decision","vi":"cân nhắc; suy tính kỹ lưỡng"}],"examples":[{"en":"Please weigh these apples before putting them in the bag.","vi":"Xin vui lòng cân số táo này trước khi cho vào túi.","audioKind":"ex"},{"en":"Governments must weigh the economic benefits of tourism against its potential damage to local ecosystems.","vi":"Chính phủ phải cân nhắc lợi ích kinh tế của ngành du lịch với những thiệt hại tiềm tàng đối với hệ sinh thái địa phương.","audioKind":"ex2"}],"collocations":[{"en":"weigh yourself","vi":"tự cân trọng lượng bản thân"},{"en":"weigh the options","vi":"cân nhắc các lựa chọn"},{"en":"weigh up the evidence","vi":"cân nhắc kỹ lưỡng các bằng chứng"},{"en":"weigh the benefits against the costs","vi":"cân nhắc giữa lợi ích và chi phí"}],"wordFamily":["weight (n.)","weighty (adj.)"],"synonyms":["measure","consider"],"antonyms":[],"tipVi":"weigh là động từ, còn weight là danh từ; khi diễn tả vật nặng bao nhiêu thì không dùng thể bị động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_limited', 'en-b1-50', 'limited', '/ˈlɪmɪtɪd/', 'B1', 'hạn chế; có giới hạn', 'adj.', 'limit (n.), limit (v.), limitation (n.), unlimited (adj.)', 'Đồng nghĩa: restricted · Trái nghĩa: unlimited', 'be limited to biểu thị "chỉ giới hạn ở", to đi theo sau là danh từ hoặc danh động từ.', 'We have limited space, so choose a smaller sofa.', NULL, 'Chúng tôi có không gian hạn chế, vì vậy hãy chọn một chiếc ghế sofa nhỏ hơn.', '{"wordId":"limited","ukIpa":"/ˈlɪmɪtɪd/","usIpa":"/ˈlɪmɪtɪd/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Small in amount or restricted in range","vi":"hạn chế; có giới hạn"}],"examples":[{"en":"We have limited space, so choose a smaller sofa.","vi":"Chúng tôi có không gian hạn chế, vì vậy hãy chọn một chiếc ghế sofa nhỏ hơn.","audioKind":"ex"},{"en":"Students with limited access to reliable internet may struggle to participate fully in online learning.","vi":"Những học sinh có quyền tiếp cận hạn chế với mạng internet ổn định có thể gặp khó khăn trong việc tham gia đầy đủ vào quá trình học trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"limited resources","vi":"tài nguyên hạn chế"},{"en":"limited access","vi":"quyền tiếp cận hạn chế"},{"en":"a limited range","vi":"phạm vi hạn chế"},{"en":"be limited to","vi":"bị giới hạn trong"}],"wordFamily":["limit (n.)","limit (v.)","limitation (n.)","unlimited (adj.)"],"synonyms":["restricted"],"antonyms":["unlimited"],"tipVi":"be limited to biểu thị \"chỉ giới hạn ở\", to đi theo sau là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_screwdriver', 'en-b1-50', 'screwdriver', '/ˈskruːˌdraɪvər/', 'B1', 'tuốc nơ vít; tua vít', 'n.', 'screw (n.), screw (v.)', NULL, 'screw là con ốc/vít; screwdriver là dụng cụ vặn ốc vít.', 'Pass me the screwdriver so I can tighten this handle.', NULL, 'Đưa tôi cái tua vít để tôi vặn chặt cái tay nắm này lại.', '{"wordId":"screwdriver","ukIpa":"/ˈskruːˌdraɪvə/","usIpa":"/ˈskruːˌdraɪvər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A tool used to turn screws into or out of objects.","vi":"tuốc nơ vít; tua vít"}],"examples":[{"en":"Pass me the screwdriver so I can tighten this handle.","vi":"Đưa tôi cái tua vít để tôi vặn chặt cái tay nắm này lại.","audioKind":"ex"},{"en":"Teaching students to use basic tools, such as a screwdriver, can encourage practical skills and greater independence.","vi":"Dạy học sinh sử dụng các dụng cụ cơ bản, chẳng hạn như tuốc nơ vít, có thể thúc đẩy kỹ năng thực hành và sự tự lập cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"a flat-head screwdriver","vi":"tuốc nơ vít đầu dẹp"},{"en":"a cross-head screwdriver","vi":"tuốc nơ vít bốn cạnh"},{"en":"a screwdriver set","vi":"bộ tuốc nơ vít"}],"wordFamily":["screw (n.)","screw (v.)"],"synonyms":[],"antonyms":[],"tipVi":"screw là con ốc/vít; screwdriver là dụng cụ vặn ốc vít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recommend', 'en-b1-50', 'recommend', '/ˌrekəˈmend/', 'B1', 'giới thiệu; gợi ý; khuyên; khuyến nghị', 'v.', 'recommendation (n.), recommended (adj.)', 'Đồng nghĩa: suggest, advise', 'Dùng recommend doing hoặc mệnh đề recommend that.', 'Can you recommend a quiet café near the station?', NULL, 'Bạn có thể giới thiệu một quán cà phê yên tĩnh nào gần nhà ga không?', '{"wordId":"recommend","ukIpa":"/ˌrekəˈmend/","usIpa":"/ˌrekəˈmend/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To suggest someone or something as a good choice.","vi":"giới thiệu; gợi ý"},{"pos":"v.","en":"To advise someone that a particular action would be beneficial.","vi":"khuyên; khuyến nghị"}],"examples":[{"en":"Can you recommend a quiet café near the station?","vi":"Bạn có thể giới thiệu một quán cà phê yên tĩnh nào gần nhà ga không?","audioKind":"ex"},{"en":"Health experts recommend regular exercise to reduce stress and improve overall physical and mental wellbeing.","vi":"Các chuyên gia y tế khuyến nghị tập thể dục thường xuyên để giảm bớt căng thẳng và cải thiện sức khỏe thể chất lẫn tinh thần tổng thể.","audioKind":"ex2"}],"collocations":[{"en":"highly recommend","vi":"đặc biệt giới thiệu"},{"en":"recommend a book","vi":"giới thiệu một cuốn sách"},{"en":"recommend doing something","vi":"khuyên làm điều gì đó"},{"en":"recommend someone for a job","vi":"giới thiệu ai đó nhận việc"}],"wordFamily":["recommendation (n.)","recommended (adj.)"],"synonyms":["suggest","advise"],"antonyms":[],"tipVi":"Dùng recommend doing hoặc mệnh đề recommend that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_50_1', 'en-b1-50', 'Cách dùng “handsome” (adj.) — đẹp trai; khôi ngô', 'handsome man  ·  handsome profit  ·  handsome reward', 'Thường dùng để tả nam giới có ngoại hình đẹp; khi dùng cho lợi nhuận hoặc phần thưởng thì mang nghĩa hậu hĩnh, lớn lao.', 'Họ từ (Word Family): handsomely (adv.), handsomeness (n.) | Đồng nghĩa: good-looking, attractive · Trái nghĩa: unattractive', '[{"hanzi":"My brother looks handsome in his new blue jacket.","pinyin":"","meaning":"Anh trai tôi trông rất bảnh bao trong chiếc áo khoác màu xanh mới."},{"hanzi":"Companies investing in renewable energy may earn handsome profits as demand for cleaner alternatives continues to grow.","pinyin":"","meaning":"Các công ty đầu tư vào năng lượng tái tạo có thể thu về lợi nhuận khổng lồ khi nhu cầu về các nguồn năng lượng sạch tiếp tục gia tăng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_50_2', 'en-b1-50', 'Cách dùng “jug” (n.) — bình rót nước; cái vại', 'a jug of water  ·  milk jug  ·  fill a jug', 'Tiếng Anh-Anh thường chỉ bình miệng rộng có vòi; tiếng Anh-Mỹ thường chỉ bình có cổ hẹp và có tay cầm.', NULL, '[{"hanzi":"Please bring a jug of water to the table.","pinyin":"","meaning":"Làm ơn mang một bình nước ra bàn giúp tôi."},{"hanzi":"Serving tap water in a reusable jug can help restaurants reduce their reliance on disposable plastic bottles.","pinyin":"","meaning":"Việc phục vụ nước máy trong một chiếc bình có thể dùng lại giúp các nhà hàng giảm bớt sự phụ thuộc vào chai nhựa dùng một lần."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_50_3', 'en-b1-50', 'Cách dùng “weigh” (v.) — cân; đo trọng lượng', 'weigh yourself  ·  weigh the options  ·  weigh up the evidence', 'weigh là động từ, còn weight là danh từ; khi diễn tả vật nặng bao nhiêu thì không dùng thể bị động.', 'Họ từ (Word Family): weight (n.), weighty (adj.) | Đồng nghĩa: measure, consider', '[{"hanzi":"Please weigh these apples before putting them in the bag.","pinyin":"","meaning":"Xin vui lòng cân số táo này trước khi cho vào túi."},{"hanzi":"Governments must weigh the economic benefits of tourism against its potential damage to local ecosystems.","pinyin":"","meaning":"Chính phủ phải cân nhắc lợi ích kinh tế của ngành du lịch với những thiệt hại tiềm tàng đối với hệ sinh thái địa phương."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_50_4', 'en-b1-50', 'Cách dùng “object” (n.) — vật; đồ vật', 'a physical object  ·  object to a proposal  ·  the object of the exercise', 'Danh từ trọng âm ở âm tiết đầu, động từ ở âm tiết sau; object to đi với danh từ hoặc danh động từ.', 'Họ từ (Word Family): objection (n.), objector (n.)', '[{"hanzi":"A shiny object was lying beneath the sofa.","pinyin":"","meaning":"Có một vật sáng lấp lánh nằm dưới chiếc ghế sofa."},{"hanzi":"Many residents object to the proposed airport expansion because it could increase noise pollution.","pinyin":"","meaning":"Nhiều người dân phản đối kế hoạch mở rộng sân bay vì nó có thể làm tăng ô nhiễm tiếng ồn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
