INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_50_1_5', 'ten_b1_50_1', 'terribly', 'I''m terribly sorry I spilled juice on your jacket.', 'I''m terribly sorry I spilled juice on your jacket.', '/ˈterəbli/', 'Tôi cực kỳ xin lỗi vì đã làm đổ nước trái cây lên áo khoác của bạn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_50_1_6', 'ten_b1_50_1', 'mend', 'Grandpa showed me how to mend a torn pocket.', 'Grandpa showed me how to mend a torn pocket.', '/mend/', 'Ông đã dạy tôi cách vá cái túi áo bị rách.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_50_1_7', 'ten_b1_50_1', 'bury', 'Our dog buried its favourite toy beside the fence.', 'Our dog buried its favourite toy beside the fence.', '/ˈberi/', 'Con chó của chúng tôi đã giấu món đồ chơi yêu thích của nó bên cạnh hàng rào.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_50_1_8', 'ten_b1_50_1', 'attach', 'Attach the little bell to your bicycle''s handlebars.', 'Attach the little bell to your bicycle''s handlebars.', '/əˈtætʃ/', 'Hãy gắn chiếc chuông nhỏ vào tay lái xe đạp của bạn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_50_1_1', 'en-b1-50', 'ten_b1_50_1', 'listening', 'listening', 'I packed clean underwear in my travel bag.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã xếp vài bộ đồ lót sạch vào túi du lịch của mình.","Xin vui lòng cân số táo này trước khi cho vào túi.","Phần đế nặng giúp chiếc đèn không bị đổ.","Anh trai tôi trông rất bảnh bao trong chiếc áo khoác màu xanh mới."]'::jsonb, 0, 'I packed clean underwear in my travel bag. → Tôi đã xếp vài bộ đồ lót sạch vào túi du lịch của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_50_1_2', 'en-b1-50', 'ten_b1_50_1', 'listening', 'listening', 'We joined the queue outside the bakery this morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi vừa không tìm thấy chìa khóa, vừa chẳng nhớ mình đã đỗ xe ở đâu.","Cô ấy học bắn cung tại một câu lạc bộ địa phương.","Sáng nay chúng tôi đã nhập hội xếp hàng ở ngoài tiệm bánh.","Hãy giữ lại biên lai của bạn phòng khi đôi giày không vừa."]'::jsonb, 2, 'We joined the queue outside the bakery this morning. → Sáng nay chúng tôi đã nhập hội xếp hàng ở ngoài tiệm bánh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_50_1_3', 'en-b1-50', 'ten_b1_50_1', 'listening', 'listening', 'Dad used a long lighter to light the candle.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi có không gian hạn chế, vì vậy hãy chọn một chiếc ghế sofa nhỏ hơn.","Bố đã dùng một chiếc bật lửa cán dài để thắp nến.","Có một vật sáng lấp lánh nằm dưới chiếc ghế sofa.","Anh trai tôi trông rất bảnh bao trong chiếc áo khoác màu xanh mới."]'::jsonb, 1, 'Dad used a long lighter to light the candle. → Bố đã dùng một chiếc bật lửa cán dài để thắp nến.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_50_2', 'en-b1-50', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_50_2_1', 'ten_b1_50_2', 'underwear', 'Consumers increasingly prefer underwear made from breathable fabrics, encouraging manufacturers to improve comfort and durability.', 'Consumers increasingly prefer underwear made from breathable fabrics, encouraging manufacturers to improve comfort and durability.', '/ˈʌndərwer/', 'Người tiêu dùng ngày càng ưa chuộng đồ lót làm từ chất liệu thoáng khí, qua đó khuyến khích các nhà sản xuất nâng cao độ thoải mái và độ bền.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_50_2_2', 'ten_b1_50_2', 'queue', 'Improved ticketing systems can reduce the time passengers spend waiting in a queue at busy stations.', 'Improved ticketing systems can reduce the time passengers spend waiting in a queue at busy stations.', '/kjuː/', 'Hệ thống bán vé được cải tiến có thể làm giảm thời gian hành khách phải đứng xếp hàng ở các nhà ga đông đúc.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_50_2_3', 'ten_b1_50_2', 'lighter', 'A refillable lighter may produce less plastic waste than disposable alternatives when used over a long period.', 'A refillable lighter may produce less plastic waste than disposable alternatives when used over a long period.', '/ˈlaɪtər/', 'Sử dụng bật lửa có thể châm thêm nhiên liệu trong thời gian dài có thể thải ra ít rác thải nhựa hơn so với các loại dùng một lần.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_50_2_4', 'ten_b1_50_2', 'handsome', 'Companies investing in renewable energy may earn handsome profits as demand for cleaner alternatives continues to grow.', 'Companies investing in renewable energy may earn handsome profits as demand for cleaner alternatives continues to grow.', '/ˈhænsəm/', 'Các công ty đầu tư vào năng lượng tái tạo có thể thu về lợi nhuận khổng lồ khi nhu cầu về các nguồn năng lượng sạch tiếp tục gia tăng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_50_2_5', 'ten_b1_50_2', 'terribly', 'Without reliable public transport, elderly residents may feel terribly isolated in remote rural communities.', 'Without reliable public transport, elderly residents may feel terribly isolated in remote rural communities.', '/ˈterəbli/', 'Nếu không có hệ thống giao thông công cộng đáng tin cậy, cư dân cao tuổi ở các vùng nông thôn hẻo lánh có thể cảm thấy vô cùng cô lập.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_50_2_6', 'ten_b1_50_2', 'mend', 'Teaching children to mend their clothes can reduce textile waste and encourage more responsible attitudes towards consumption.', 'Teaching children to mend their clothes can reduce textile waste and encourage more responsible attitudes towards consumption.', '/mend/', 'Dạy trẻ em tự sửa chữa quần áo có thể làm giảm lượng rác thải dệt may và khuyến khích thái độ tiêu dùng có trách nhiệm hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_50_2_1', 'en-b1-50', 'ten_b1_50_2', 'listening', 'listening', 'Consumers increasingly prefer underwear made from breathable fabrics, encouraging manufacturers to improve comfort and durability.', NULL, 'Trong câu vừa nghe, từ “underwear” mang nghĩa nào sau đây?', '["đồ lót; trang phục mặc sát da","đồng mười xu (Mỹ hoặc Canada)","cảng biển; bến cảng","buổi; phiên họp hoặc khoảng thời gian dành cho một hoạt động cụ thể"]'::jsonb, 0, '“underwear” (/ˈʌndərwer/): đồ lót; trang phục mặc sát da. Câu đầy đủ: Consumers increasingly prefer underwear made from breathable fabrics, encouraging manufacturers to improve comfort and durability.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_50_2_2', 'en-b1-50', 'ten_b1_50_2', 'listening', 'listening', 'Improved ticketing systems can reduce the time passengers spend waiting in a queue at busy stations.', NULL, 'Trong câu vừa nghe, từ “queue” mang nghĩa nào sau đây?', '["rác bừa bãi nơi công cộng","bệnh tật; sự ốm đau","sắt; chất sắt","hàng người chờ đợi; đoàn xe xếp hàng"]'::jsonb, 3, '“queue” (/kjuː/): hàng người chờ đợi; đoàn xe xếp hàng. Câu đầy đủ: Improved ticketing systems can reduce the time passengers spend waiting in a queue at busy stations.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
