INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_50_2', 'en-b1-50', NULL, 'comprehensive_test', 'listening', 'We joined the queue outside the bakery this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đôi giày thể thao đầy màu sắc đó rất được bạn bè tôi ưa chuộng.","Anh trai tôi trông rất bảnh bao trong chiếc áo khoác màu xanh mới.","Xin vui lòng cân số táo này trước khi cho vào túi.","Sáng nay chúng tôi đã nhập hội xếp hàng ở ngoài tiệm bánh."]'::jsonb, 3, 'We joined the queue outside the bakery this morning. → Sáng nay chúng tôi đã nhập hội xếp hàng ở ngoài tiệm bánh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_50_3', 'en-b1-50', NULL, 'comprehensive_test', 'listening', 'lighter', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bật lửa; thiết bị tạo lửa","mạnh mẽ; có lực lớn","say rượu","sừng (trên đầu động vật)"]'::jsonb, 0, 'lighter (/ˈlaɪtər/) → bật lửa; thiết bị tạo lửa', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_50_4', 'en-b1-50', NULL, 'comprehensive_test', 'listening', 'My brother looks handsome in his new blue jacket.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Làm ơn mang một bình nước ra bàn giúp tôi.","Anh ấy mặc áo khoác dài lên rồi bước ra ngoài trời có tuyết.","Hãy gắn chiếc chuông nhỏ vào tay lái xe đạp của bạn.","Anh trai tôi trông rất bảnh bao trong chiếc áo khoác màu xanh mới."]'::jsonb, 3, 'My brother looks handsome in his new blue jacket. → Anh trai tôi trông rất bảnh bao trong chiếc áo khoác màu xanh mới.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
