INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_50_6', 'en-b1-50', NULL, 'comprehensive_test', 'listening', 'Grandpa showed me how to mend a torn pocket.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đôi giày thể thao đầy màu sắc đó rất được bạn bè tôi ưa chuộng.","Ông đã dạy tôi cách vá cái túi áo bị rách.","Cô ấy học bắn cung tại một câu lạc bộ địa phương.","Tôi kéo vớ len dày lên trước khi bước ra ngoài."]'::jsonb, 1, 'Grandpa showed me how to mend a torn pocket. → Ông đã dạy tôi cách vá cái túi áo bị rách.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
