INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_50_18', 'en-b1-50', NULL, 'comprehensive_test', 'reading', NULL, 'Consumers increasingly prefer underwear made from breathable fabrics, encouraging manufacturers to improve comfort and durability.', 'Dựa vào câu trên, từ “underwear” có nghĩa phù hợp nhất là gì?', '["thú vị; buồn cười; làm vui vẻ","tập trung; chú trọng","đồ lót; trang phục mặc sát da","bụi; bụi bặm"]'::jsonb, 2, 'underwear: đồ lót; trang phục mặc sát da. Dịch cả câu: Người tiêu dùng ngày càng ưa chuộng đồ lót làm từ chất liệu thoáng khí, qua đó khuyến khích các nhà sản xuất nâng cao độ thoải mái và độ bền.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_50_19', 'en-b1-50', NULL, 'comprehensive_test', 'reading', NULL, 'Improved ticketing systems can reduce the time passengers spend waiting in a queue at busy stations.', 'Dựa vào câu trên, từ “queue” có nghĩa phù hợp nhất là gì?', '["bộ dụng cụ; trang thiết bị","hàng người chờ đợi; đoàn xe xếp hàng","trung bình; thông thường","thái độ; quan điểm"]'::jsonb, 1, 'queue: hàng người chờ đợi; đoàn xe xếp hàng; xếp hàng chờ đến lượt. Dịch cả câu: Hệ thống bán vé được cải tiến có thể làm giảm thời gian hành khách phải đứng xếp hàng ở các nhà ga đông đúc.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_50_20', 'en-b1-50', NULL, 'comprehensive_test', 'reading', NULL, 'A refillable lighter may produce less plastic waste than disposable alternatives when used over a long period.', 'Dựa vào câu trên, từ “lighter” có nghĩa phù hợp nhất là gì?', '["sự quản lý; sự điều hành","khu cắm trại","bật lửa; thiết bị tạo lửa","hương va-ni; quả va-ni"]'::jsonb, 2, 'lighter: bật lửa; thiết bị tạo lửa. Dịch cả câu: Sử dụng bật lửa có thể châm thêm nhiên liệu trong thời gian dài có thể thải ra ít rác thải nhựa hơn so với các loại dùng một lần.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_50_21', 'en-b1-50', NULL, 'comprehensive_test', 'reading', NULL, 'Companies investing in renewable energy may earn handsome profits as demand for cleaner alternatives continues to grow.', 'Dựa vào câu trên, từ “handsome” có nghĩa phù hợp nhất là gì?', '["đẹp trai; khôi ngô","sự quản lý; sự điều hành","nữ tiếp viên hàng không; nữ tiếp viên tàu thủy","tiểu thuyết; truyện dài"]'::jsonb, 0, 'handsome: đẹp trai; khôi ngô; lớn; hậu hĩnh; đáng kể. Dịch cả câu: Các công ty đầu tư vào năng lượng tái tạo có thể thu về lợi nhuận khổng lồ khi nhu cầu về các nguồn năng lượng sạch tiếp tục gia tăng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
