INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-51', 'en', 'Bài 51: Đời sống hằng ngày (3) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3051, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_collection', 'en-b1-51', 'collection', '/kəˈlekʃən/', 'B1', 'bộ sưu tập; tập hợp; sự thu gom; sự thu thập; sự quyên góp; tiền quyên góp', 'n.', 'collect (v.), collector (n.), collectible (adj.)', NULL, 'a collection of đi với danh từ số nhiều, dùng để chỉ một nhóm các vật liên quan với nhau.', 'My aunt keeps her shell collection in a cabinet.', NULL, 'Dì tôi cất bộ sưu tập vỏ sò trong một chiếc tủ.', '{"wordId":"collection","ukIpa":"/kəˈlekʃən/","usIpa":"/kəˈlekʃən/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a group of objects kept or presented together","vi":"bộ sưu tập; tập hợp"},{"pos":"n.","en":"the act of gathering or taking things away","vi":"sự thu gom; sự thu thập"},{"pos":"n.","en":"the gathering of money from people for a purpose","vi":"sự quyên góp; tiền quyên góp"}],"examples":[{"en":"My aunt keeps her shell collection in a cabinet.","vi":"Dì tôi cất bộ sưu tập vỏ sò trong một chiếc tủ.","audioKind":"ex"},{"en":"Regular household waste collection is essential for protecting public health and maintaining a clean urban environment.","vi":"Việc thu gom rác thải sinh hoạt định kỳ là vô cùng quan trọng để bảo vệ sức khỏe cộng đồng và duy trì môi trường đô thị sạch sẽ.","audioKind":"ex2"}],"collocations":[{"en":"a collection of","vi":"một bộ sưu tập..."},{"en":"data collection","vi":"thu thập dữ liệu"},{"en":"waste collection","vi":"thu gom rác thải"},{"en":"make a collection","vi":"tổ chức quyên góp"}],"wordFamily":["collect (v.)","collector (n.)","collectible (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"a collection of đi với danh từ số nhiều, dùng để chỉ một nhóm các vật liên quan với nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_medium', 'en-b1-51', 'medium', '/ˈmiːdiəm/', 'B1', 'trung bình; ở mức vừa; phương tiện truyền thông; phương tiện giao tiếp', 'adj.', 'media (n.)', NULL, 'Khi mang nghĩa "phương tiện", dạng số nhiều thường là media.', 'Cook the vegetables over medium heat until soft.', NULL, 'Nấu rau ở lửa vừa cho đến khi mềm.', '{"wordId":"medium","ukIpa":"/ˈmiːdiəm/","usIpa":"/ˈmiːdiəm/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Between small and large, or between low and high.","vi":"trung bình; ở mức vừa"},{"pos":"n.","en":"A means of communicating information or expressing ideas.","vi":"phương tiện truyền thông; phương tiện giao tiếp"}],"examples":[{"en":"Cook the vegetables over medium heat until soft.","vi":"Nấu rau ở lửa vừa cho đến khi mềm.","audioKind":"ex"},{"en":"Film is an effective medium for exploring social issues and encouraging discussion among young people.","vi":"Phim ảnh là một phương tiện truyền thông hiệu quả để khám phá các vấn đề xã hội và thúc đẩy sự thảo luận trong giới trẻ.","audioKind":"ex2"}],"collocations":[{"en":"medium heat","vi":"lửa vừa"},{"en":"medium size","vi":"kích cỡ trung bình"},{"en":"a medium of communication","vi":"phương tiện giao tiếp"}],"wordFamily":["media (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa \"phương tiện\", dạng số nhiều thường là media.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fence', 'en-b1-51', 'fence', '/fens/', 'B1', 'hàng rào; rào chắn; làm hàng rào vây quanh; rào lại; đấu kiếm', 'n.', 'fencing (n.), fencer (n.)', NULL, 'sit on the fence biểu thị việc giữ thái độ trung lập, không nghiêng về bên nào.', 'Our dog watched the neighbours through the wooden fence.', NULL, 'Con chó nhà chúng tôi nhìn những người hàng xóm qua hàng rào gỗ.', '{"wordId":"fence","ukIpa":"/fens/","usIpa":"/fens/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A barrier enclosing land or separating areas.","vi":"hàng rào; rào chắn"},{"pos":"v.","en":"To surround or divide an area with a fence.","vi":"làm hàng rào vây quanh; rào lại"},{"pos":"v.","en":"To fight with special swords as a sport.","vi":"đấu kiếm"}],"examples":[{"en":"Our dog watched the neighbours through the wooden fence.","vi":"Con chó nhà chúng tôi nhìn những người hàng xóm qua hàng rào gỗ.","audioKind":"ex"},{"en":"Installing fences around protected habitats can reduce conflict between local farmers and endangered wildlife.","vi":"Việc lắp đặt hàng rào quanh các môi trường sống được bảo vệ có thể làm giảm xung đột giữa nông dân địa phương và động vật hoang dã có nguy cơ tuyệt chủng.","audioKind":"ex2"}],"collocations":[{"en":"wooden fence","vi":"hàng rào gỗ"},{"en":"put up a fence","vi":"dựng rào; rào lại"},{"en":"fence off an area","vi":"rào chắn một khu vực"}],"wordFamily":["fencing (n.)","fencer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"sit on the fence biểu thị việc giữ thái độ trung lập, không nghiêng về bên nào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plenty', 'en-b1-51', 'plenty', '/ˈplenti/', 'B1', 'nhiều; thừa thãi; đủ dùng; khá; đầy đủ; sự phong phú; sự sung túc', 'pron.', 'plentiful (adj.), plentifully (adv.)', 'Đồng nghĩa: abundance · Trái nghĩa: scarcity', 'Sau plenty of có thể dùng danh từ đếm được số nhiều hoặc danh từ không đếm được, không cần thêm a.', 'There is plenty of soup left for everyone.', NULL, 'Vẫn còn thừa soup cho tất cả mọi người.', '{"wordId":"plenty","ukIpa":"/ˈplenti/","usIpa":"/ˈplenti/","cefr":"B1","topic":"daily","senses":[{"pos":"pron.","en":"Enough or more than enough of something.","vi":"nhiều; thừa thãi; đủ dùng"},{"pos":"adv.","en":"To a sufficient degree or a large extent.","vi":"khá; đầy đủ"},{"pos":"n.","en":"A state in which resources are abundant.","vi":"sự phong phú; sự sung túc"}],"examples":[{"en":"There is plenty of soup left for everyone.","vi":"Vẫn còn thừa soup cho tất cả mọi người.","audioKind":"ex"},{"en":"Although cities offer plenty of employment opportunities, high housing costs can discourage young workers from moving there.","vi":"Mặc dù các thành phố cung cấp rất nhiều cơ hội việc làm, chi phí nhà ở cao có thể làm chùn bước những người lao động trẻ muốn chuyển đến đó.","audioKind":"ex2"}],"collocations":[{"en":"plenty of time","vi":"thời gian dư dả"},{"en":"plenty of opportunities","vi":"nhiều cơ hội"},{"en":"plenty more","vi":"nhiều hơn nữa"},{"en":"a time of plenty","vi":"thời kỳ sung túc"}],"wordFamily":["plentiful (adj.)","plentifully (adv.)"],"synonyms":["abundance"],"antonyms":["scarcity"],"tipVi":"Sau plenty of có thể dùng danh từ đếm được số nhiều hoặc danh từ không đếm được, không cần thêm a.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_variety', 'en-b1-51', 'variety', '/vəˈraɪəti/', 'B1', 'sự đa dạng; tính phong phú; loại; chủng loại', 'n.', 'vary (v.), various (adj.), varied (adj.), variation (n.)', 'Đồng nghĩa: diversity, type · Trái nghĩa: uniformity', 'Nghĩa tính đa dạng là không đếm được; nghĩa chủng loại, giống loài là danh từ đếm được.', 'We add variety to lunch with different colourful vegetables.', NULL, 'Chúng tôi làm bữa trưa thêm phong phú bằng các loại rau củ nhiều màu sắc.', '{"wordId":"variety","ukIpa":"/vəˈraɪəti/","usIpa":"/vəˈraɪəti/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"the presence of different things rather than only one kind","vi":"sự đa dạng; tính phong phú"},{"pos":"n.","en":"a particular type of something","vi":"loại; chủng loại"}],"examples":[{"en":"We add variety to lunch with different colourful vegetables.","vi":"Chúng tôi làm bữa trưa thêm phong phú bằng các loại rau củ nhiều màu sắc.","audioKind":"ex"},{"en":"Schools should offer a wide variety of activities to support students with different interests.","vi":"Các trường học nên cung cấp đa dạng các hoạt động để hỗ trợ học sinh có sở thích khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"a wide variety of","vi":"nhiều loại đa dạng"},{"en":"add variety to","vi":"làm phong phú thêm"},{"en":"a variety of reasons","vi":"vì nhiều lý do khác nhau"},{"en":"a new variety","vi":"một giống mới"}],"wordFamily":["vary (v.)","various (adj.)","varied (adj.)","variation (n.)"],"synonyms":["diversity","type"],"antonyms":["uniformity"],"tipVi":"Nghĩa tính đa dạng là không đếm được; nghĩa chủng loại, giống loài là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chew', 'en-b1-51', 'chew', '/tʃuː/', 'B1', 'nhai; cắn; cú nhai; cái nhai', 'v.', 'chewy (adj.)', 'Đồng nghĩa: masticate', 'chew là nhai, swallow là nuốt; chew over mang nghĩa suy ngẫm kỹ.', 'Please chew your food slowly before you swallow it.', NULL, 'Hãy nhai kỹ thức ăn trước khi nuốt xuống.', '{"wordId":"chew","ukIpa":"/tʃuː/","usIpa":"/tʃuː/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Break food into smaller pieces with your teeth","vi":"nhai; cắn"},{"pos":"n.","en":"An act of biting something repeatedly with your teeth","vi":"cú nhai; cái nhai"}],"examples":[{"en":"Please chew your food slowly before you swallow it.","vi":"Hãy nhai kỹ thức ăn trước khi nuốt xuống.","audioKind":"ex"},{"en":"Children should be encouraged to chew food thoroughly and develop healthy eating habits from an early age.","vi":"Trẻ em nên được khuyến khích nhai kỹ thức ăn và hình thành thói quen ăn uống lành mạnh từ nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"chew food","vi":"nhai thức ăn"},{"en":"chew gum","vi":"nhai kẹo cao su"},{"en":"chew thoroughly","vi":"nhai kỹ"},{"en":"chew something over","vi":"ngẫm nghĩ kỹ về điều gì"}],"wordFamily":["chewy (adj.)"],"synonyms":["masticate"],"antonyms":[],"tipVi":"chew là nhai, swallow là nuốt; chew over mang nghĩa suy ngẫm kỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bitter', 'en-b1-51', 'bitter', '/ˈbɪt̬.ɚ/', 'B1', 'có vị đắng; đắng; căm phẫn; ấm ức; đầy hằn học; gay gắt; khốc liệt; đầy thù hận', 'adj.', 'bitterness (n.), bitterly (adv.)', 'Đồng nghĩa: resentful · Trái nghĩa: sweet', 'vị bitter là vị đắng, còn sour là vị chua, không nên nhầm lẫn hai từ này.', 'The coffee tasted too bitter without milk or sugar.', NULL, 'Cà phê uống rất đắng nếu không cho thêm sữa hoặc đường.', '{"wordId":"bitter","ukIpa":"/ˈbɪt.ə/","usIpa":"/ˈbɪt̬.ɚ/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"having a sharp taste like strong unsweetened coffee","vi":"có vị đắng; đắng"},{"pos":"adj.","en":"angry and resentful because of unfair treatment or disappointment","vi":"căm phẫn; ấm ức; đầy hằn học"},{"pos":"adj.","en":"involving strong anger and hostility","vi":"gay gắt; khốc liệt; đầy thù hận"}],"examples":[{"en":"The coffee tasted too bitter without milk or sugar.","vi":"Cà phê uống rất đắng nếu không cho thêm sữa hoặc đường.","audioKind":"ex"},{"en":"Proposals to close local libraries have sparked bitter disputes between residents and local authorities.","vi":"Đề xuất đóng cửa các thư viện địa phương đã châm ngòi cho những tranh cãi gay gắt giữa người dân và chính quyền địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a bitter taste","vi":"vị đắng"},{"en":"bitter about","vi":"ấm ức vì điều gì"},{"en":"a bitter dispute","vi":"tranh cãi gay gắt"},{"en":"bitter disappointment","vi":"sự thất vọng tràn trề"}],"wordFamily":["bitterness (n.)","bitterly (adv.)"],"synonyms":["resentful"],"antonyms":["sweet"],"tipVi":"vị bitter là vị đắng, còn sour là vị chua, không nên nhầm lẫn hai từ này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_smooth', 'en-b1-51', 'smooth', '/smuːð/', 'B1', 'mịn màng; phẳng phiu, không có vùng gồ ghề hoặc lồi lõm; thuận lợi; diễn ra suôn sẻ, không gặp sự cố, gián đoạn hay biến động đột ngột; làm phẳng; làm cho bề mặt phẳng mịn hoặc xóa đi các nếp nhăn', 'adj.', 'smoothly (adv.), smoothness (n.)', 'Đồng nghĩa: even · Trái nghĩa: rough', 'Âm cuối th phát âm là phụ âm hữu thanh /ð/; smoothly thường dùng để diễn tả việc tiến hành suôn sẻ.', 'This stone feels smooth and cool in my hand.', NULL, 'Hòn đá này cầm trên tay cho cảm giác rất nhẵn và mát lạnh.', '{"wordId":"smooth","ukIpa":"/smuːð/","usIpa":"/smuːð/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"having an even surface without rough areas or bumps","vi":"mịn màng; phẳng phiu, không có vùng gồ ghề hoặc lồi lõm"},{"pos":"adj.","en":"happening without problems, interruptions, or sudden movements","vi":"thuận lợi; diễn ra suôn sẻ, không gặp sự cố, gián đoạn hay biến động đột ngột"},{"pos":"v.","en":"to make a surface even or remove its wrinkles","vi":"làm phẳng; làm cho bề mặt phẳng mịn hoặc xóa đi các nếp nhăn"}],"examples":[{"en":"This stone feels smooth and cool in my hand.","vi":"Hòn đá này cầm trên tay cho cảm giác rất nhẵn và mát lạnh.","audioKind":"ex"},{"en":"Clear communication between departments is essential for a smooth transition to a new working system.","vi":"Sự giao tiếp rõ ràng giữa các phòng ban đóng vai trò cốt yếu để chuyển sang hệ thống làm việc mới một cách suôn sẻ.","audioKind":"ex2"}],"collocations":[{"en":"smooth surface","vi":"bề mặt nhẵn"},{"en":"smooth transition","vi":"quá trình chuyển đổi suôn sẻ"},{"en":"smooth operation","vi":"vận hành trơn tru"},{"en":"smooth out wrinkles","vi":"ủi phẳng nếp nhăn"}],"wordFamily":["smoothly (adv.)","smoothness (n.)"],"synonyms":["even"],"antonyms":["rough"],"tipVi":"Âm cuối th phát âm là phụ âm hữu thanh /ð/; smoothly thường dùng để diễn tả việc tiến hành suôn sẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_container', 'en-b1-51', 'container', '/kənˈteɪnər/', 'B1', 'đồ đựng; vật dùng để chứa hoặc bảo quản đồ đạc; thùng hàng; hộp kim loại lớn dùng để vận chuyển hàng hóa', 'n.', 'contain (v.), containment (n.)', NULL, 'Chỉ chung các vật chứa đồ; trong ngữ cảnh vận tải thường chỉ container chở hàng.', 'Keep the leftover rice in a container with a lid.', NULL, 'Hãy bảo quản cơm thừa trong một chiếc hộp đựng có nắp đậy.', '{"wordId":"container","ukIpa":"/kənˈteɪnə/","usIpa":"/kənˈteɪnər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"an object used to hold or store things","vi":"đồ đựng; vật dùng để chứa hoặc bảo quản đồ đạc"},{"pos":"n.","en":"a large metal box used to transport goods","vi":"thùng hàng; hộp kim loại lớn dùng để vận chuyển hàng hóa"}],"examples":[{"en":"Keep the leftover rice in a container with a lid.","vi":"Hãy bảo quản cơm thừa trong một chiếc hộp đựng có nắp đậy.","audioKind":"ex"},{"en":"Reusable food containers can reduce household waste when people use them instead of disposable packaging.","vi":"Hộp đựng thực phẩm tái sử dụng có thể giúp giảm thiểu rác thải sinh hoạt khi mọi người dùng chúng thay cho bao bì dùng một lần.","audioKind":"ex2"}],"collocations":[{"en":"airtight container","vi":"hộp kín khí"},{"en":"food container","vi":"hộp đựng thực phẩm"},{"en":"shipping container","vi":"thùng container vận chuyển hàng hóa"}],"wordFamily":["contain (v.)","containment (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ chung các vật chứa đồ; trong ngữ cảnh vận tải thường chỉ container chở hàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tap', 'en-b1-51', 'tap', '/tæp/', 'B1', 'vòi nước; vỗ nhẹ; gõ nhẹ; khai thác; tận dụng', 'n.', NULL, 'Đồng nghĩa: faucet', 'Vòi nước trong tiếng Anh-Mỹ thường được gọi là faucet.', 'Please turn off the tap while brushing your teeth.', NULL, 'Làm ơn khóa vòi nước trong lúc đánh răng.', '{"wordId":"tap","ukIpa":"/tæp/","usIpa":"/tæp/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a device that controls water flowing from a pipe","vi":"vòi nước"},{"pos":"v.","en":"to touch or hit something lightly","vi":"vỗ nhẹ; gõ nhẹ"},{"pos":"v.","en":"to use an available source of energy, knowledge, or resources","vi":"khai thác; tận dụng"}],"examples":[{"en":"Please turn off the tap while brushing your teeth.","vi":"Làm ơn khóa vòi nước trong lúc đánh răng.","audioKind":"ex"},{"en":"Universities can tap local expertise to develop practical solutions to environmental problems affecting nearby communities.","vi":"Các trường đại học có thể tận dụng chuyên môn địa phương để phát triển các giải pháp thiết thực cho các vấn đề môi trường ảnh hưởng đến các cộng đồng lân cận.","audioKind":"ex2"}],"collocations":[{"en":"tap water","vi":"nước máy"},{"en":"turn off the tap","vi":"khóa vòi nước"},{"en":"tap someone on the shoulder","vi":"vỗ vai ai đó"},{"en":"tap into resources","vi":"khai thác nguồn lực"}],"wordFamily":[],"synonyms":["faucet"],"antonyms":[],"tipVi":"Vòi nước trong tiếng Anh-Mỹ thường được gọi là faucet.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ribbon', 'en-b1-51', 'ribbon', '/ˈrɪbən/', 'B1', 'dải ruy băng; dải băng; dải dài và hẹp', 'n.', NULL, NULL, 'Thường có thể đếm được; a ribbon of có thể dùng để miêu tả những thứ dài và hẹp giống như dải băng.', 'She tied a blue ribbon around the gift.', NULL, 'Cô ấy thắt một chiếc nơ ruy băng màu xanh xung quanh hộp quà.', '{"wordId":"ribbon","ukIpa":"/ˈrɪbən/","usIpa":"/ˈrɪbən/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A narrow strip of cloth used for tying or decoration.","vi":"dải ruy băng; dải băng"},{"pos":"n.","en":"Something long and narrow that resembles a strip of cloth.","vi":"dải dài và hẹp"}],"examples":[{"en":"She tied a blue ribbon around the gift.","vi":"Cô ấy thắt một chiếc nơ ruy băng màu xanh xung quanh hộp quà.","audioKind":"ex"},{"en":"During community celebrations, residents decorate public spaces with colourful ribbons to create a welcoming atmosphere.","vi":"Trong các lễ hội cộng đồng, người dân trang trí không gian công cộng bằng những dải ruy băng đầy màu sắc để tạo nên bầu không khí chào đón nồng nhiệt.","audioKind":"ex2"}],"collocations":[{"en":"tie a ribbon","vi":"thắt ruy băng"},{"en":"a ribbon bow","vi":"nơ ruy băng"},{"en":"cut the ribbon","vi":"cắt băng"},{"en":"a ribbon of road","vi":"dải đường dài"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường có thể đếm được; a ribbon of có thể dùng để miêu tả những thứ dài và hẹp giống như dải băng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bunch', 'en-b1-51', 'bunch', '/bʌntʃ/', 'B1', 'chùm; bó; nải; một nhóm người (thân mật); tụm lại; gom lại', 'n.', NULL, 'Đồng nghĩa: cluster, group', 'a bunch of có thể chỉ một bó hoặc một chùm; khi dùng cho người thì mang sắc thái khẩu ngữ thân mật.', 'He brought a bunch of flowers for the kitchen table.', NULL, 'Anh ấy mang một bó hoa để lên bàn ăn trong bếp.', '{"wordId":"bunch","ukIpa":"/bʌntʃ/","usIpa":"/bʌntʃ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a group of similar things held or growing together","vi":"chùm; bó; nải"},{"pos":"n.","en":"a group of people, described informally","vi":"một nhóm người (thân mật)"},{"pos":"v.","en":"to gather closely together, or make things gather together","vi":"tụm lại; gom lại"}],"examples":[{"en":"He brought a bunch of flowers for the kitchen table.","vi":"Anh ấy mang một bó hoa để lên bàn ăn trong bếp.","audioKind":"ex"},{"en":"When passengers bunch together near train doors, boarding becomes slower and less comfortable for everyone.","vi":"Khi hành khách tụ tập quá đông ở gần cửa tàu, việc lên tàu sẽ trở nên chậm hơn và kém thoải mái hơn cho tất cả mọi người.","audioKind":"ex2"}],"collocations":[{"en":"a bunch of grapes","vi":"một chùm nho"},{"en":"a bunch of flowers","vi":"một bó hoa"},{"en":"a bunch of friends","vi":"một đám bạn"},{"en":"bunch up","vi":"bu lại; ép sát lại"}],"wordFamily":[],"synonyms":["cluster","group"],"antonyms":[],"tipVi":"a bunch of có thể chỉ một bó hoặc một chùm; khi dùng cho người thì mang sắc thái khẩu ngữ thân mật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outdoor', 'en-b1-51', 'outdoor', '/ˈaʊtdɔːr/', 'B1', 'ngoài trời; lộ thiên', 'adj.', 'outdoors (adv.)', 'Đồng nghĩa: open-air · Trái nghĩa: indoor', 'outdoor là tính từ; để chỉ hành động diễn ra ở ngoài trời, hãy dùng phó từ outdoors.', 'We bought comfortable chairs for our outdoor dining area.', NULL, 'Chúng tôi đã mua những chiếc ghế thoải mái cho khu vực ăn uống ngoài trời của mình.', '{"wordId":"outdoor","ukIpa":"/ˈaʊtdɔː/","usIpa":"/ˈaʊtdɔːr/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"happening, used, or located outside a building","vi":"ngoài trời; lộ thiên"}],"examples":[{"en":"We bought comfortable chairs for our outdoor dining area.","vi":"Chúng tôi đã mua những chiếc ghế thoải mái cho khu vực ăn uống ngoài trời của mình.","audioKind":"ex"},{"en":"Regular outdoor activities can improve children''s physical health while helping them develop an appreciation of nature.","vi":"Các hoạt động ngoài trời thường xuyên có thể cải thiện sức khỏe thể chất của trẻ em đồng thời giúp các em phát triển sự trân trọng đối với thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"outdoor activities","vi":"hoạt động ngoài trời"},{"en":"outdoor sports","vi":"thể thao ngoài trời"},{"en":"outdoor swimming pool","vi":"hồ bơi ngoài trời"},{"en":"outdoor clothing","vi":"trang phục ngoài trời"}],"wordFamily":["outdoors (adv.)"],"synonyms":["open-air"],"antonyms":["indoor"],"tipVi":"outdoor là tính từ; để chỉ hành động diễn ra ở ngoài trời, hãy dùng phó từ outdoors.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cosy', 'en-b1-51', 'cosy', '/ˈkoʊzi/', 'B1', 'ấm cúng; dễ chịu; thân mật; gần gũi', 'adj.', 'cosily (adv.), cosiness (n.)', 'Đồng nghĩa: snug, comfortable · Trái nghĩa: uncomfortable', 'Cách viết theo Anh-Anh là cosy, còn tiếng Anh-Mỹ thường viết là cozy.', 'We spent a cosy evening beside the fire.', NULL, 'Chúng tôi đã trải qua một buổi tối ấm cúng bên lò sưởi.', '{"wordId":"cosy","ukIpa":"/ˈkəʊzi/","usIpa":"/ˈkoʊzi/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"warm, comfortable, and pleasant, often in a small space","vi":"ấm cúng; dễ chịu"},{"pos":"adj.","en":"friendly and relaxed in a private setting","vi":"thân mật; gần gũi"}],"examples":[{"en":"We spent a cosy evening beside the fire.","vi":"Chúng tôi đã trải qua một buổi tối ấm cúng bên lò sưởi.","audioKind":"ex"},{"en":"Small libraries can provide cosy spaces where residents read, relax, and build connections with their neighbours.","vi":"Các thư viện nhỏ có thể cung cấp không gian ấm cúng nơi cư dân đọc sách, thư giãn và xây dựng mối liên kết với hàng xóm.","audioKind":"ex2"}],"collocations":[{"en":"a cosy room","vi":"một căn phòng ấm cúng"},{"en":"a cosy atmosphere","vi":"bầuokhông khí ấm cúng"},{"en":"a cosy chat","vi":"một buổi trò chuyện thân mật"}],"wordFamily":["cosily (adv.)","cosiness (n.)"],"synonyms":["snug","comfortable"],"antonyms":["uncomfortable"],"tipVi":"Cách viết theo Anh-Anh là cosy, còn tiếng Anh-Mỹ thường viết là cozy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chain', 'en-b1-51', 'chain', '/tʃeɪn/', 'B1', 'dây xích; chuỗi; chuỗi cửa hàng, sự kiện hoặc các sự vật liên kết với nhau; buộc hoặc xích cái gì lại bằng dây xích', 'n.', NULL, NULL, 'Cụm a chain of đi với danh từ số nhiều, diễn tả một loạt sự việc, sự vật liên tiếp.', 'He secured his bicycle with a heavy metal chain.', NULL, 'Anh ấy khóa chiếc xe đạp của mình bằng một sợi xích kim loại dày.', '{"wordId":"chain","ukIpa":"/tʃeɪn/","usIpa":"/tʃeɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a series of connected metal rings","vi":"dây xích; chuỗi"},{"pos":"n.","en":"connected shops, events, or other things forming a series","vi":"chuỗi cửa hàng, sự kiện hoặc các sự vật liên kết với nhau"},{"pos":"v.","en":"to fasten someone or something with a chain","vi":"buộc hoặc xích cái gì lại bằng dây xích"}],"examples":[{"en":"He secured his bicycle with a heavy metal chain.","vi":"Anh ấy khóa chiếc xe đạp của mình bằng một sợi xích kim loại dày.","audioKind":"ex"},{"en":"Large supermarket chains can offer lower prices, but their expansion may threaten small independent shops.","vi":"Các chuỗi siêu thị lớn có thể cung cấp giá rẻ hơn, nhưng sự bành trướng của họ có thể đe dọa các cửa hàng bán lẻ độc lập nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"a chain of events","vi":"một chuỗi sự kiện"},{"en":"a supermarket chain","vi":"chuỗi siêu thị"},{"en":"a supply chain","vi":"chuỗi cung ứng"},{"en":"chain a bicycle to a railing","vi":"xích xe đạp vào lan can"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm a chain of đi với danh từ số nhiều, diễn tả một loạt sự việc, sự vật liên tiếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tiring', 'en-b1-51', 'tiring', '/ˈtaɪrɪŋ/', 'B1', 'làm mệt mỏi; căng thẳng; mệt nhọc', 'adj.', 'tire (v.), tired (adj.), tiredness (n.), tireless (adj.)', 'Đồng nghĩa: exhausting, fatiguing · Trái nghĩa: refreshing', 'tiring dùng để miêu tả sự vật gây mệt mỏi; tired dùng để chỉ cảm giác mệt mỏi của con người.', 'Carrying these heavy bags upstairs is tiring work.', NULL, 'Khuân những chiếc túi nặng này lên lầu là một công việc rất mệt mỏi.', '{"wordId":"tiring","ukIpa":"/ˈtaɪərɪŋ/","usIpa":"/ˈtaɪrɪŋ/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"making someone feel that they need rest","vi":"làm mệt mỏi; căng thẳng; mệt nhọc"}],"examples":[{"en":"Carrying these heavy bags upstairs is tiring work.","vi":"Khuân những chiếc túi nặng này lên lầu là một công việc rất mệt mỏi.","audioKind":"ex"},{"en":"Long and tiring commutes can reduce workers'' productivity and leave them with less time for family activities.","vi":"Những chuyến đi lại kéo dài và mệt mỏi có thể làm giảm năng suất làm việc của nhân viên và khiến họ có ít thời gian hơn cho các hoạt động gia đình.","audioKind":"ex2"}],"collocations":[{"en":"a tiring day","vi":"một ngày mệt mỏi"},{"en":"a tiring journey","vi":"một hành trình mệt mỏi"},{"en":"physically tiring","vi":"mệt mỏi về thể chất"}],"wordFamily":["tire (v.)","tired (adj.)","tiredness (n.)","tireless (adj.)"],"synonyms":["exhausting","fatiguing"],"antonyms":["refreshing"],"tipVi":"tiring dùng để miêu tả sự vật gây mệt mỏi; tired dùng để chỉ cảm giác mệt mỏi của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dryer', 'en-b1-51', 'dryer', '/ˈdraɪər/', 'B1', 'máy sấy; thiết bị làm khô', 'n.', 'dry (v.), dryness (n.)', NULL, 'dryer thông thường chỉ thiết bị sấy khô; dạng so sánh hơn của tính từ dry thường được viết là drier.', 'The towels are still warm from the dryer.', NULL, 'Những chiếc khăn vẫn còn ấm khi lấy từ máy sấy ra.', '{"wordId":"dryer","ukIpa":"/ˈdraɪə/","usIpa":"/ˈdraɪər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A machine or device that removes moisture from things.","vi":"máy sấy; thiết bị làm khô"}],"examples":[{"en":"The towels are still warm from the dryer.","vi":"Những chiếc khăn vẫn còn ấm khi lấy từ máy sấy ra.","audioKind":"ex"},{"en":"Using a clothesline instead of an electric dryer can lower household energy consumption and reduce monthly bills.","vi":"Sử dụng dây phơi đồ thay vì máy sấy điện có thể giúp giảm lượng điện năng tiêu thụ của gia đình và cắt giảm hóa đơn hàng tháng.","audioKind":"ex2"}],"collocations":[{"en":"tumble dryer","vi":"máy sấy quần áo cửa ngang"},{"en":"hair dryer","vi":"máy sấy tóc"},{"en":"hand dryer","vi":"máy sấy tay"},{"en":"clothes dryer","vi":"máy sấy quần áo"}],"wordFamily":["dry (v.)","dryness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"dryer thông thường chỉ thiết bị sấy khô; dạng so sánh hơn của tính từ dry thường được viết là drier.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brilliant', 'en-b1-51', 'brilliant', '/ˈbrɪljənt/', 'B1', 'tuyệt vời; xuất sắc; thông minh tuyệt đỉnh; tài giỏi; sáng chói; rực rỡ', 'adj.', 'brilliance (n.), brilliantly (adv.)', 'Đồng nghĩa: excellent, outstanding · Trái nghĩa: mediocre', 'Trong tiếng Anh-Anh văn nói, brilliant thường được dùng để chỉ "tuyệt vời".', 'Your brilliant idea saved us hours of work.', NULL, 'Ý tưởng tuyệt vời của bạn đã giúp chúng tôi tiết kiệm hàng giờ làm việc.', '{"wordId":"brilliant","ukIpa":"/ˈbrɪljənt/","usIpa":"/ˈbrɪljənt/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Extremely good, impressive, or enjoyable.","vi":"tuyệt vời; xuất sắc"},{"pos":"adj.","en":"Exceptionally intelligent or skilled.","vi":"thông minh tuyệt đỉnh; tài giỏi"},{"pos":"adj.","en":"Shining brightly or having a strong, vivid colour.","vi":"sáng chói; rực rỡ"}],"examples":[{"en":"Your brilliant idea saved us hours of work.","vi":"Ý tưởng tuyệt vời của bạn đã giúp chúng tôi tiết kiệm hàng giờ làm việc.","audioKind":"ex"},{"en":"Brilliant teachers can inspire students to explore difficult subjects with confidence and genuine curiosity.","vi":"Những giáo viên xuất sắc có thể truyền cảm hứng cho học sinh khám phá các môn học khó với sự tự tin và trí tò mò chân thành.","audioKind":"ex2"}],"collocations":[{"en":"brilliant idea","vi":"ý tưởng tuyệt vời"},{"en":"brilliant scientist","vi":"nhà khoa học lỗi lạc"},{"en":"brilliant sunshine","vi":"ánh nắng rực rỡ"}],"wordFamily":["brilliance (n.)","brilliantly (adv.)"],"synonyms":["excellent","outstanding"],"antonyms":["mediocre"],"tipVi":"Trong tiếng Anh-Anh văn nói, brilliant thường được dùng để chỉ \"tuyệt vời\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fancy', 'en-b1-51', 'fancy', '/ˈfænsi/', 'B1', 'muốn có cái gì; thích làm gì; cầu kỳ, tinh xảo; đắt tiền, sang trọng thay vì giản dị; có cảm tình, cảm mến ai đó theo cách lãng mạn', 'v.', NULL, NULL, 'Khi diễn tả ý nghĩa "muốn làm", hãy dùng fancy doing, không dùng fancy to do.', 'Do you fancy a walk by the river after lunch?', NULL, 'Bạn có muốn đi dạo dọc bờ sông sau bữa trưa không?', '{"wordId":"fancy","ukIpa":"/ˈfænsi/","usIpa":"/ˈfænsi/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To want something or feel like doing something.","vi":"muốn có cái gì; thích làm gì"},{"pos":"adj.","en":"Decorative, elaborate, or expensive rather than plain.","vi":"cầu kỳ, tinh xảo; đắt tiền, sang trọng thay vì giản dị"},{"pos":"v.","en":"To feel romantically attracted to someone.","vi":"có cảm tình, cảm mến ai đó theo cách lãng mạn"}],"examples":[{"en":"Do you fancy a walk by the river after lunch?","vi":"Bạn có muốn đi dạo dọc bờ sông sau bữa trưa không?","audioKind":"ex"},{"en":"Some tourists prefer simple local accommodation to fancy hotels because it offers more opportunities for cultural exchange.","vi":"Một số du khách thích những chỗ ở bình dị tại địa phương hơn các khách sạn sang trọng vì nó mang lại nhiều cơ hội giao lưu văn hóa hơn.","audioKind":"ex2"}],"collocations":[{"en":"fancy doing something","vi":"muốn làm gì đó"},{"en":"fancy a drink","vi":"thèm uống một ly"},{"en":"a fancy restaurant","vi":"một nhà hàng sang trọng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi diễn tả ý nghĩa \"muốn làm\", hãy dùng fancy doing, không dùng fancy to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_due', 'en-b1-51', 'due', '/duː/', 'B1', 'đến hạn thanh toán; đến hạn nộp; đến hẹn; dự kiến sẽ xảy ra hoặc đến vào một thời điểm; xứng đáng; thích hợp trong một hoàn cảnh cụ thể', 'adj.', 'duly (adv.)', NULL, 'be due to do chỉ việc dự kiến làm gì; due to cộng với danh từ mang nghĩa là do.', 'Our rent is due at the end of the week.', NULL, 'Tiền thuê nhà của chúng tôi đến hạn trả vào cuối tuần này.', '{"wordId":"due","ukIpa":"/djuː/","usIpa":"/duː/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Required to be paid or submitted by a particular time.","vi":"đến hạn thanh toán; đến hạn nộp"},{"pos":"adj.","en":"Expected to happen or arrive at a particular time.","vi":"đến hẹn; dự kiến sẽ xảy ra hoặc đến vào một thời điểm"},{"pos":"adj.","en":"Deserved or appropriate in a particular situation.","vi":"xứng đáng; thích hợp trong một hoàn cảnh cụ thể"}],"examples":[{"en":"Our rent is due at the end of the week.","vi":"Tiền thuê nhà của chúng tôi đến hạn trả vào cuối tuần này.","audioKind":"ex"},{"en":"When tuition fees are due, some students struggle to cover both educational expenses and basic living costs.","vi":"Khi đến hạn đóng học phí, một số sinh viên gặp khó khăn trong việc trang trải cả chi phí giáo dục lẫn sinh hoạt phí cơ bản.","audioKind":"ex2"}],"collocations":[{"en":"payment due","vi":"khoản thanh toán đến hạn"},{"en":"due to arrive","vi":"dự kiến đến"},{"en":"due consideration","vi":"sự xem xét thỏa đáng"},{"en":"due to","vi":"do, bởi vì"}],"wordFamily":["duly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"be due to do chỉ việc dự kiến làm gì; due to cộng với danh từ mang nghĩa là do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rely', 'en-b1-51', 'rely', '/rɪˈlaɪ/', 'B1', 'dựa vào; lệ thuộc vào sự giúp đỡ của ai; tin tưởng; tín nhiệm ai hoặc cái gì sẽ hành động như mong đợi', 'v.', 'reliable (adj.), reliably (adv.), reliability (n.), reliance (n.)', 'Đồng nghĩa: depend, count on', 'Không đi thẳng với tân ngữ trực tiếp: phải dùng rely on hoặc rely upon.', 'I rely on my bicycle to get to work.', NULL, 'Tôi dựa vào chiếc xe đạp của mình để đi làm.', '{"wordId":"rely","ukIpa":"/rɪˈlaɪ/","usIpa":"/rɪˈlaɪ/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to need someone''s help or depend on something","vi":"dựa vào; lệ thuộc vào sự giúp đỡ của ai"},{"pos":"v.","en":"to trust someone or something to act as expected","vi":"tin tưởng; tín nhiệm ai hoặc cái gì sẽ hành động như mong đợi"}],"examples":[{"en":"I rely on my bicycle to get to work.","vi":"Tôi dựa vào chiếc xe đạp của mình để đi làm.","audioKind":"ex"},{"en":"Communities that rely heavily on tourism may face economic difficulties when visitor numbers suddenly decline.","vi":"Các cộng đồng phụ thuộc nhiều vào du lịch có thể đối mặt với khó khăn kinh tế khi lượng khách du lịch giảm sút đột ngột.","audioKind":"ex2"}],"collocations":[{"en":"rely on","vi":"dựa vào; tin cậy"},{"en":"rely heavily on","vi":"phụ thuộc nặng nề vào"},{"en":"rely on someone to do something","vi":"tin tưởng ai làm việc gì"}],"wordFamily":["reliable (adj.)","reliably (adv.)","reliability (n.)","reliance (n.)"],"synonyms":["depend","count on"],"antonyms":[],"tipVi":"Không đi thẳng với tân ngữ trực tiếp: phải dùng rely on hoặc rely upon.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_salty', 'en-b1-51', 'salty', '/ˈsɔːlti/', 'B1', 'mặn; có nhiều muối', 'adj.', 'salt (n.), salt (v.), saltiness (n.), salted (adj.)', 'Trái nghĩa: unsalted', 'salty nhấn mạnh vị mặn tự nhiên hoặc sẵn có; salted nhấn mạnh việc đã được cho thêm muối.', 'The soup was too salty, so I added water.', NULL, 'Món canh bị mặn quá nên tôi đã cho thêm nước vào.', '{"wordId":"salty","ukIpa":"/ˈsɔːlti/","usIpa":"/ˈsɔːlti/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Tasting of salt or containing a lot of salt.","vi":"mặn; có nhiều muối"}],"examples":[{"en":"The soup was too salty, so I added water.","vi":"Món canh bị mặn quá nên tôi đã cho thêm nước vào.","audioKind":"ex"},{"en":"Eating salty snacks frequently can contribute to high blood pressure, increasing the risk of cardiovascular disease.","vi":"Việc thường xuyên ăn các món ăn vặt mặn có thể dẫn đến cao huyết áp, làm tăng nguy cơ mắc bệnh tim mạch.","audioKind":"ex2"}],"collocations":[{"en":"salty food","vi":"thức ăn mặn"},{"en":"a salty taste","vi":"hương vị mặn"},{"en":"salty snacks","vi":"đồ ăn vặt mặn"}],"wordFamily":["salt (n.)","salt (v.)","saltiness (n.)","salted (adj.)"],"synonyms":[],"antonyms":["unsalted"],"tipVi":"salty nhấn mạnh vị mặn tự nhiên hoặc sẵn có; salted nhấn mạnh việc đã được cho thêm muối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_throughout', 'en-b1-51', 'throughout', '/θruːˈaʊt/', 'B1', 'khắp; xuyên suốt; khắp nơi; từ đầu đến cuối', 'prep.', NULL, NULL, 'throughout nhấn mạnh phạm vi bao trùm toàn bộ không gian hoặc khoảng thời gian chứ không chỉ tại một thời điểm hay địa điểm cụ thể.', 'The smell of fresh bread spread throughout the house.', NULL, 'Mùi bánh mì mới nướng lan tỏa khắp căn nhà.', '{"wordId":"throughout","ukIpa":"/θruːˈaʊt/","usIpa":"/θruːˈaʊt/","cefr":"B1","topic":"daily","senses":[{"pos":"prep.","en":"In every part of a place or during an entire period.","vi":"khắp; xuyên suốt"},{"pos":"adv.","en":"In every part or for the whole time.","vi":"khắp nơi; từ đầu đến cuối"}],"examples":[{"en":"The smell of fresh bread spread throughout the house.","vi":"Mùi bánh mì mới nướng lan tỏa khắp căn nhà.","audioKind":"ex"},{"en":"Reliable internet access throughout rural areas is essential for reducing inequalities in education and employment.","vi":"Khả năng kết nối internet ổn định ở khắp các vùng nông thôn đóng vai trò cốt lõi trong việc thu hẹp khoảng cách bất bình đẳng về giáo dục và việc làm.","audioKind":"ex2"}],"collocations":[{"en":"throughout the world","vi":"trên khắp thế giới"},{"en":"throughout the year","vi":"suốt cả năm"},{"en":"throughout history","vi":"xuyên suốt chiều dài lịch sử"},{"en":"remain consistent throughout","vi":"luôn giữ vững sự nhất quán"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"throughout nhấn mạnh phạm vi bao trùm toàn bộ không gian hoặc khoảng thời gian chứ không chỉ tại một thời điểm hay địa điểm cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suit', 'en-b1-51', 'suit', '/suːt/', 'B1', 'thích hợp; thuận tiện; hợp với (ai); làm cho (ai) trông đẹp hơn; bộ com-lê; bộ âu phục', 'v.', 'suitable (adj.), unsuitable (adj.), suitability (n.)', NULL, 'Từ suit nhấn mạnh sự phù hợp hoặc hợp mốt; từ fit nhấn mạnh sự vừa vặn về kích cỡ.', 'Would an earlier appointment suit you better tomorrow?', NULL, 'Lịch hẹn sớm hơn vào ngày mai có thuận tiện hơn cho bạn không?', '{"wordId":"suit","ukIpa":"/suːt/","usIpa":"/suːt/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to be convenient or right for someone","vi":"thích hợp; thuận tiện"},{"pos":"v.","en":"to make someone look attractive","vi":"hợp với (ai); làm cho (ai) trông đẹp hơn"},{"pos":"n.","en":"matching clothes consisting of a jacket and trousers or skirt","vi":"bộ com-lê; bộ âu phục"}],"examples":[{"en":"Would an earlier appointment suit you better tomorrow?","vi":"Lịch hẹn sớm hơn vào ngày mai có thuận tiện hơn cho bạn không?","audioKind":"ex"},{"en":"Flexible working hours suit employees who need to balance professional responsibilities with family commitments.","vi":"Giờ làm việc linh hoạt phù hợp với những nhân viên cần cân bằng giữa trách nhiệm công việc và cam kết gia đình.","audioKind":"ex2"}],"collocations":[{"en":"suit your needs","vi":"đáp ứng nhu cầu của bạn"},{"en":"suit everyone","vi":"phù hợp với tất cả mọi người"},{"en":"a business suit","vi":"bộ đồ công sở; trang phục công sở"}],"wordFamily":["suitable (adj.)","unsuitable (adj.)","suitability (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ suit nhấn mạnh sự phù hợp hoặc hợp mốt; từ fit nhấn mạnh sự vừa vặn về kích cỡ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transfer', 'en-b1-51', 'transfer', '/trænsˈfɝː/', 'B1', 'chuyển; điều chuyển; chuyển khoản; chuyển xe; chuyển trường; chuyển cơ quan; sự chuyển; sự điều chuyển; sự chuyển khoản', 'v.', 'transferable (adj.), transference (n.)', 'Đồng nghĩa: move, relocate', 'Danh từ trọng âm ở âm tiết đầu; quá khứ transferred gấp đôi chữ r.', 'Please transfer the photos from your camera to my laptop.', NULL, 'Vui lòng chuyển các bức ảnh từ máy ảnh của bạn sang máy tính xách tay của tôi.', '{"wordId":"transfer","ukIpa":"/trænsˈfɜː(r)/","usIpa":"/trænsˈfɝː/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To move someone or something from one place to another.","vi":"chuyển; điều chuyển; chuyển khoản"},{"pos":"v.","en":"To change to another vehicle, school, or institution.","vi":"chuyển xe; chuyển trường; chuyển cơ quan"},{"pos":"n.","en":"The act of moving something or someone to another place.","vi":"sự chuyển; sự điều chuyển; sự chuyển khoản"}],"examples":[{"en":"Please transfer the photos from your camera to my laptop.","vi":"Vui lòng chuyển các bức ảnh từ máy ảnh của bạn sang máy tính xách tay của tôi.","audioKind":"ex"},{"en":"Governments should support the transfer of clean technology to regions that still depend heavily on fossil fuels.","vi":"Chính phủ nên hỗ trợ việc chuyển giao công nghệ sạch sang các khu vực vẫn phụ thuộc nhiều vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"transfer money","vi":"chuyển tiền"},{"en":"transfer data","vi":"truyền dữ liệu"},{"en":"transfer to another school","vi":"chuyển trường khác"},{"en":"technology transfer","vi":"chuyển giao công nghệ"}],"wordFamily":["transferable (adj.)","transference (n.)"],"synonyms":["move","relocate"],"antonyms":[],"tipVi":"Danh từ trọng âm ở âm tiết đầu; quá khứ transferred gấp đôi chữ r.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dot', 'en-b1-51', 'dot', '/dɑːt/', 'B1', 'chấm; điểm tròn nhỏ; nằm rải rác; chấm phá; dấu chấm trong địa chỉ web hoặc email', 'n.', 'dotted (adj.)', 'Đồng nghĩa: spot', 'on the dot nghĩa là đúng giờ, thường đứng sau một mốc thời gian cụ thể.', 'Her yellow umbrella has a pattern of blue dots.', NULL, 'Chiếc ô màu vàng của cô ấy có họa tiết những chấm tròn màu xanh.', '{"wordId":"dot","ukIpa":"/dɒt/","usIpa":"/dɑːt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a small round mark","vi":"chấm; điểm tròn nhỏ"},{"pos":"v.","en":"to appear in scattered places across an area","vi":"nằm rải rác; chấm phá"},{"pos":"n.","en":"the spoken name for a full stop in online addresses","vi":"dấu chấm trong địa chỉ web hoặc email"}],"examples":[{"en":"Her yellow umbrella has a pattern of blue dots.","vi":"Chiếc ô màu vàng của cô ấy có họa tiết những chấm tròn màu xanh.","audioKind":"ex"},{"en":"Small villages dot the coastline, attracting visitors who prefer quieter alternatives to crowded seaside resorts.","vi":"Những ngôi làng nhỏ nằm rải rác dọc theo bờ biển, thu hút du khách thích sự yên tĩnh hơn là những khu nghỉ dưỡng ven biển đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"a red dot","vi":"một dấu chấm đỏ"},{"en":"on the dot","vi":"đúng giờ"},{"en":"dotted line","vi":"đường đứt nét"},{"en":"be dotted with","vi":"được rải rác bởi"}],"wordFamily":["dotted (adj.)"],"synonyms":["spot"],"antonyms":[],"tipVi":"on the dot nghĩa là đúng giờ, thường đứng sau một mốc thời gian cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_previously', 'en-b1-51', 'previously', '/ˈpriːviəsli/', 'B1', 'trước đây; trước đó', 'adv.', 'previous (adj.)', 'Đồng nghĩa: formerly, before, earlier · Trái nghĩa: subsequently', 'previously có nghĩa là trước đó; để chỉ sự chuẩn bị trước thường dùng in advance.', 'I had previously met our neighbour at the library.', NULL, 'Tôi đã từng gặp người hàng xóm của chúng ta ở thư viện trước đó.', '{"wordId":"previously","ukIpa":"/ˈpriːviəsli/","usIpa":"/ˈpriːviəsli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"At a time before now or before another event.","vi":"trước đây; trước đó"}],"examples":[{"en":"I had previously met our neighbour at the library.","vi":"Tôi đã từng gặp người hàng xóm của chúng ta ở thư viện trước đó.","audioKind":"ex"},{"en":"Online courses now provide educational opportunities for people who previously had limited access to universities.","vi":"Các khóa học trực tuyến nay mang lại cơ hội giáo dục cho những người mà trước đây khó có thể tiếp cận với bậc đại học.","audioKind":"ex2"}],"collocations":[{"en":"previously unknown","vi":"chưa từng biết đến trước đây"},{"en":"previously mentioned","vi":"được đề cập trước đó"},{"en":"previously published","vi":"được xuất bản trước đó"}],"wordFamily":["previous (adj.)"],"synonyms":["formerly","before","earlier"],"antonyms":["subsequently"],"tipVi":"previously có nghĩa là trước đó; để chỉ sự chuẩn bị trước thường dùng in advance.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_51_1', 'en-b1-51', 'Cách dùng “throughout” (prep.) — khắp; xuyên suốt', 'throughout the world  ·  throughout the year  ·  throughout history', 'throughout nhấn mạnh phạm vi bao trùm toàn bộ không gian hoặc khoảng thời gian chứ không chỉ tại một thời điểm hay địa điểm cụ thể.', NULL, '[{"hanzi":"The smell of fresh bread spread throughout the house.","pinyin":"","meaning":"Mùi bánh mì mới nướng lan tỏa khắp căn nhà."},{"hanzi":"Reliable internet access throughout rural areas is essential for reducing inequalities in education and employment.","pinyin":"","meaning":"Khả năng kết nối internet ổn định ở khắp các vùng nông thôn đóng vai trò cốt lõi trong việc thu hẹp khoảng cách bất bình đẳng về giáo dục và việc làm."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_51_2', 'en-b1-51', 'Cách dùng “dryer” (n.) — máy sấy; thiết bị làm khô', 'tumble dryer  ·  hair dryer  ·  hand dryer', 'dryer thông thường chỉ thiết bị sấy khô; dạng so sánh hơn của tính từ dry thường được viết là drier.', 'Họ từ (Word Family): dry (v.), dryness (n.)', '[{"hanzi":"The towels are still warm from the dryer.","pinyin":"","meaning":"Những chiếc khăn vẫn còn ấm khi lấy từ máy sấy ra."},{"hanzi":"Using a clothesline instead of an electric dryer can lower household energy consumption and reduce monthly bills.","pinyin":"","meaning":"Sử dụng dây phơi đồ thay vì máy sấy điện có thể giúp giảm lượng điện năng tiêu thụ của gia đình và cắt giảm hóa đơn hàng tháng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_51_3', 'en-b1-51', 'Cách dùng “smooth” (adj.) — mịn màng; phẳng phiu, không có vùng gồ ghề hoặc lồi lõm', 'smooth surface  ·  smooth transition  ·  smooth operation', 'Âm cuối th phát âm là phụ âm hữu thanh /ð/; smoothly thường dùng để diễn tả việc tiến hành suôn sẻ.', 'Họ từ (Word Family): smoothly (adv.), smoothness (n.) | Đồng nghĩa: even · Trái nghĩa: rough', '[{"hanzi":"This stone feels smooth and cool in my hand.","pinyin":"","meaning":"Hòn đá này cầm trên tay cho cảm giác rất nhẵn và mát lạnh."},{"hanzi":"Clear communication between departments is essential for a smooth transition to a new working system.","pinyin":"","meaning":"Sự giao tiếp rõ ràng giữa các phòng ban đóng vai trò cốt yếu để chuyển sang hệ thống làm việc mới một cách suôn sẻ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_51_4', 'en-b1-51', 'Cách dùng “ribbon” (n.) — dải ruy băng; dải băng', 'tie a ribbon  ·  a ribbon bow  ·  cut the ribbon', 'Thường có thể đếm được; a ribbon of có thể dùng để miêu tả những thứ dài và hẹp giống như dải băng.', NULL, '[{"hanzi":"She tied a blue ribbon around the gift.","pinyin":"","meaning":"Cô ấy thắt một chiếc nơ ruy băng màu xanh xung quanh hộp quà."},{"hanzi":"During community celebrations, residents decorate public spaces with colourful ribbons to create a welcoming atmosphere.","pinyin":"","meaning":"Trong các lễ hội cộng đồng, người dân trang trí không gian công cộng bằng những dải ruy băng đầy màu sắc để tạo nên bầu không khí chào đón nồng nhiệt."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_51_1', 'en-b1-51', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
