INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_51_1_3', 'ten_b1_51_1', 'fence', 'Our dog watched the neighbours through the wooden fence.', 'Our dog watched the neighbours through the wooden fence.', '/fens/', 'Con chó nhà chúng tôi nhìn những người hàng xóm qua hàng rào gỗ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_51_1_4', 'ten_b1_51_1', 'plenty', 'There is plenty of soup left for everyone.', 'There is plenty of soup left for everyone.', '/ˈplenti/', 'Vẫn còn thừa soup cho tất cả mọi người.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_51_1_5', 'ten_b1_51_1', 'variety', 'We add variety to lunch with different colourful vegetables.', 'We add variety to lunch with different colourful vegetables.', '/vəˈraɪəti/', 'Chúng tôi làm bữa trưa thêm phong phú bằng các loại rau củ nhiều màu sắc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_51_1_6', 'ten_b1_51_1', 'chew', 'Please chew your food slowly before you swallow it.', 'Please chew your food slowly before you swallow it.', '/tʃuː/', 'Hãy nhai kỹ thức ăn trước khi nuốt xuống.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_51_1_7', 'ten_b1_51_1', 'bitter', 'The coffee tasted too bitter without milk or sugar.', 'The coffee tasted too bitter without milk or sugar.', '/ˈbɪt̬.ɚ/', 'Cà phê uống rất đắng nếu không cho thêm sữa hoặc đường.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_51_1_8', 'ten_b1_51_1', 'smooth', 'This stone feels smooth and cool in my hand.', 'This stone feels smooth and cool in my hand.', '/smuːð/', 'Hòn đá này cầm trên tay cho cảm giác rất nhẵn và mát lạnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_51_1_1', 'en-b1-51', 'ten_b1_51_1', 'listening', 'listening', 'My aunt keeps her shell collection in a cabinet.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tiền thuê nhà của chúng tôi đến hạn trả vào cuối tuần này.","Chúng tôi làm bữa trưa thêm phong phú bằng các loại rau củ nhiều màu sắc.","Tôi dựa vào chiếc xe đạp của mình để đi làm.","Dì tôi cất bộ sưu tập vỏ sò trong một chiếc tủ."]'::jsonb, 3, 'My aunt keeps her shell collection in a cabinet. → Dì tôi cất bộ sưu tập vỏ sò trong một chiếc tủ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_51_1_2', 'en-b1-51', 'ten_b1_51_1', 'listening', 'listening', 'Cook the vegetables over medium heat until soft.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nấu rau ở lửa vừa cho đến khi mềm.","Món canh bị mặn quá nên tôi đã cho thêm nước vào.","Khuân những chiếc túi nặng này lên lầu là một công việc rất mệt mỏi.","Vẫn còn thừa soup cho tất cả mọi người."]'::jsonb, 0, 'Cook the vegetables over medium heat until soft. → Nấu rau ở lửa vừa cho đến khi mềm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_51_1_3', 'en-b1-51', 'ten_b1_51_1', 'listening', 'listening', 'Our dog watched the neighbours through the wooden fence.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mùi bánh mì mới nướng lan tỏa khắp căn nhà.","Con chó nhà chúng tôi nhìn những người hàng xóm qua hàng rào gỗ.","Anh ấy mang một bó hoa để lên bàn ăn trong bếp.","Hãy nhai kỹ thức ăn trước khi nuốt xuống."]'::jsonb, 1, 'Our dog watched the neighbours through the wooden fence. → Con chó nhà chúng tôi nhìn những người hàng xóm qua hàng rào gỗ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_51_2', 'en-b1-51', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_51_2_1', 'ten_b1_51_2', 'collection', 'Regular household waste collection is essential for protecting public health and maintaining a clean urban environment.', 'Regular household waste collection is essential for protecting public health and maintaining a clean urban environment.', '/kəˈlekʃən/', 'Việc thu gom rác thải sinh hoạt định kỳ là vô cùng quan trọng để bảo vệ sức khỏe cộng đồng và duy trì môi trường đô thị sạch sẽ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_51_2_2', 'ten_b1_51_2', 'medium', 'Film is an effective medium for exploring social issues and encouraging discussion among young people.', 'Film is an effective medium for exploring social issues and encouraging discussion among young people.', '/ˈmiːdiəm/', 'Phim ảnh là một phương tiện truyền thông hiệu quả để khám phá các vấn đề xã hội và thúc đẩy sự thảo luận trong giới trẻ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_51_2_3', 'ten_b1_51_2', 'fence', 'Installing fences around protected habitats can reduce conflict between local farmers and endangered wildlife.', 'Installing fences around protected habitats can reduce conflict between local farmers and endangered wildlife.', '/fens/', 'Việc lắp đặt hàng rào quanh các môi trường sống được bảo vệ có thể làm giảm xung đột giữa nông dân địa phương và động vật hoang dã có nguy cơ tuyệt chủng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_51_2_4', 'ten_b1_51_2', 'plenty', 'Although cities offer plenty of employment opportunities, high housing costs can discourage young workers from moving there.', 'Although cities offer plenty of employment opportunities, high housing costs can discourage young workers from moving there.', '/ˈplenti/', 'Mặc dù các thành phố cung cấp rất nhiều cơ hội việc làm, chi phí nhà ở cao có thể làm chùn bước những người lao động trẻ muốn chuyển đến đó.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_51_2_5', 'ten_b1_51_2', 'variety', 'Schools should offer a wide variety of activities to support students with different interests.', 'Schools should offer a wide variety of activities to support students with different interests.', '/vəˈraɪəti/', 'Các trường học nên cung cấp đa dạng các hoạt động để hỗ trợ học sinh có sở thích khác nhau.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_51_2_6', 'ten_b1_51_2', 'chew', 'Children should be encouraged to chew food thoroughly and develop healthy eating habits from an early age.', 'Children should be encouraged to chew food thoroughly and develop healthy eating habits from an early age.', '/tʃuː/', 'Trẻ em nên được khuyến khích nhai kỹ thức ăn và hình thành thói quen ăn uống lành mạnh từ nhỏ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_51_2_1', 'en-b1-51', 'ten_b1_51_2', 'listening', 'listening', 'Regular household waste collection is essential for protecting public health and maintaining a clean urban environment.', NULL, 'Trong câu vừa nghe, từ “collection” mang nghĩa nào sau đây?', '["dải ruy băng; dải băng","bộ sưu tập; tập hợp","đèn pin","đường ray; vận tải đường sắt"]'::jsonb, 1, '“collection” (/kəˈlekʃən/): bộ sưu tập; tập hợp. Câu đầy đủ: Regular household waste collection is essential for protecting public health and maintaining a clean urban environment.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_51_2_2', 'en-b1-51', 'ten_b1_51_2', 'listening', 'listening', 'Film is an effective medium for exploring social issues and encouraging discussion among young people.', NULL, 'Trong câu vừa nghe, từ “medium” mang nghĩa nào sau đây?', '["nướng bằng vỉ","phép nhân (toán học)","trung bình; ở mức vừa","người bán thịt; thợ mổ thịt"]'::jsonb, 2, '“medium” (/ˈmiːdiəm/): trung bình; ở mức vừa. Câu đầy đủ: Film is an effective medium for exploring social issues and encouraging discussion among young people.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
