INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_51_2', 'en-b1-51', NULL, 'comprehensive_test', 'listening', 'Cook the vegetables over medium heat until soft.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Làm ơn khóa vòi nước trong lúc đánh răng.","Vui lòng chuyển các bức ảnh từ máy ảnh của bạn sang máy tính xách tay của tôi.","Tôi dựa vào chiếc xe đạp của mình để đi làm.","Nấu rau ở lửa vừa cho đến khi mềm."]'::jsonb, 3, 'Cook the vegetables over medium heat until soft. → Nấu rau ở lửa vừa cho đến khi mềm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
