INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_51_4', 'en-b1-51', NULL, 'comprehensive_test', 'listening', 'There is plenty of soup left for everyone.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ý tưởng tuyệt vời của bạn đã giúp chúng tôi tiết kiệm hàng giờ làm việc.","Vẫn còn thừa soup cho tất cả mọi người.","Anh ấy khóa chiếc xe đạp của mình bằng một sợi xích kim loại dày.","Tiền thuê nhà của chúng tôi đến hạn trả vào cuối tuần này."]'::jsonb, 1, 'There is plenty of soup left for everyone. → Vẫn còn thừa soup cho tất cả mọi người.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
