INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_51_6', 'en-b1-51', NULL, 'comprehensive_test', 'listening', 'Please chew your food slowly before you swallow it.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy khóa chiếc xe đạp của mình bằng một sợi xích kim loại dày.","Hãy nhai kỹ thức ăn trước khi nuốt xuống.","Tiền thuê nhà của chúng tôi đến hạn trả vào cuối tuần này.","Tôi đã từng gặp người hàng xóm của chúng ta ở thư viện trước đó."]'::jsonb, 1, 'Please chew your food slowly before you swallow it. → Hãy nhai kỹ thức ăn trước khi nuốt xuống.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
