INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_51_8', 'en-b1-51', NULL, 'comprehensive_test', 'listening', 'This stone feels smooth and cool in my hand.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy nhai kỹ thức ăn trước khi nuốt xuống.","Hòn đá này cầm trên tay cho cảm giác rất nhẵn và mát lạnh.","Lịch hẹn sớm hơn vào ngày mai có thuận tiện hơn cho bạn không?","Chúng tôi đã mua những chiếc ghế thoải mái cho khu vực ăn uống ngoài trời của mình."]'::jsonb, 1, 'This stone feels smooth and cool in my hand. → Hòn đá này cầm trên tay cho cảm giác rất nhẵn và mát lạnh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_51_9', 'en-b1-51', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the presence of different things rather than only one kind”?', '["suit","variety","bitter","outdoor"]'::jsonb, 1, 'variety (/vəˈraɪəti/) → sự đa dạng; tính phong phú', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
