INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_51_18', 'en-b1-51', NULL, 'comprehensive_test', 'reading', NULL, 'Regular household waste collection is essential for protecting public health and maintaining a clean urban environment.', 'Dựa vào câu trên, từ “collection” có nghĩa phù hợp nhất là gì?', '["bộ sưu tập; tập hợp","thu nhập; tiền kiếm được","liếc nhìn; nhìn thoáng qua","cỡ trung bình; trung cỡ"]'::jsonb, 0, 'collection: bộ sưu tập; tập hợp; sự thu gom; sự thu thập; sự quyên góp; tiền quyên góp. Dịch cả câu: Việc thu gom rác thải sinh hoạt định kỳ là vô cùng quan trọng để bảo vệ sức khỏe cộng đồng và duy trì môi trường đô thị sạch sẽ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_51_19', 'en-b1-51', NULL, 'comprehensive_test', 'reading', NULL, 'Film is an effective medium for exploring social issues and encouraging discussion among young people.', 'Dựa vào câu trên, từ “medium” có nghĩa phù hợp nhất là gì?', '["trung bình; ở mức vừa","sự tin tưởng; lòng tin","tạp chí chuyên khảo, tạp chí học thuật","lan truyền; truyền bá"]'::jsonb, 0, 'medium: trung bình; ở mức vừa; phương tiện truyền thông; phương tiện giao tiếp. Dịch cả câu: Phim ảnh là một phương tiện truyền thông hiệu quả để khám phá các vấn đề xã hội và thúc đẩy sự thảo luận trong giới trẻ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_51_20', 'en-b1-51', NULL, 'comprehensive_test', 'reading', NULL, 'Installing fences around protected habitats can reduce conflict between local farmers and endangered wildlife.', 'Dựa vào câu trên, từ “fence” có nghĩa phù hợp nhất là gì?', '["quảng cáo; quảng bá","hàng rào; rào chắn","đột ngột; bất ngờ","hôi thối; khó ngửi"]'::jsonb, 1, 'fence: hàng rào; rào chắn; làm hàng rào vây quanh; rào lại; đấu kiếm. Dịch cả câu: Việc lắp đặt hàng rào quanh các môi trường sống được bảo vệ có thể làm giảm xung đột giữa nông dân địa phương và động vật hoang dã có nguy cơ tuyệt chủng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_51_21', 'en-b1-51', NULL, 'comprehensive_test', 'reading', NULL, 'Although cities offer plenty of employment opportunities, high housing costs can discourage young workers from moving there.', 'Dựa vào câu trên, từ “plenty” có nghĩa phù hợp nhất là gì?', '["khó tin; kinh ngạc","nhiều; thừa thãi; đủ dùng","tái nhợt; nhạt màu","bài đánh giá; lời bình phẩm"]'::jsonb, 1, 'plenty: nhiều; thừa thãi; đủ dùng; khá; đầy đủ; sự phong phú; sự sung túc. Dịch cả câu: Mặc dù các thành phố cung cấp rất nhiều cơ hội việc làm, chi phí nhà ở cao có thể làm chùn bước những người lao động trẻ muốn chuyển đến đó.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
