INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-52', 'en', 'Bài 52: Đời sống hằng ngày (4) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3052, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stain', 'en-b1-52', 'stain', '/steɪn/', 'B1', 'vết bẩn; vết ố; làm bẩn; làm ố; nhuộm màu; chất nhuộm; chất tạo màu', 'n.', 'stained (adj.), stainless (adj.), staining (n.)', NULL, 'Vết bẩn dùng stain; màu sắc thông thường không gọi là stain, nhưng chất nhuộm thì có.', 'There is a coffee stain on your white shirt.', NULL, 'Có một vết cà phê trên chiếc áo sơ mi trắng của bạn.', '{"wordId":"stain","ukIpa":"/steɪn/","usIpa":"/steɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a dirty or coloured mark that is difficult to remove","vi":"vết bẩn; vết ố"},{"pos":"v.","en":"to leave a lasting mark or colour on something","vi":"làm bẩn; làm ố; nhuộm màu"},{"pos":"n.","en":"a substance used to colour wood or biological samples","vi":"chất nhuộm; chất tạo màu"}],"examples":[{"en":"There is a coffee stain on your white shirt.","vi":"Có một vết cà phê trên chiếc áo sơ mi trắng của bạn.","audioKind":"ex"},{"en":"Manufacturers are developing fabrics that resist stains, potentially reducing the water and energy required for washing.","vi":"Các nhà sản xuất đang phát triển các loại vải chống bẩn, qua đó có thể giảm lượng nước và năng lượng cần dùng cho việc giặt giũ.","audioKind":"ex2"}],"collocations":[{"en":"remove a stain","vi":"tẩy vết bẩn"},{"en":"a coffee stain","vi":"vết cà phê"},{"en":"wood stain","vi":"chất nhuộm gỗ"},{"en":"stain-resistant fabric","vi":"vải chống bẩn"}],"wordFamily":["stained (adj.)","stainless (adj.)","staining (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Vết bẩn dùng stain; màu sắc thông thường không gọi là stain, nhưng chất nhuộm thì có.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tan', 'en-b1-52', 'tan', '/tæn/', 'B1', 'da rám nắng; làm cho da rám nắng; có màu nâu vàng; màu nâu nhạt', 'n.', 'tanned (adj.), tanning (n.)', NULL, 'tan không chỉ chỉ việc phơi nắng cho da sạm đi; khi làm tính từ, nó cũng có thể mô tả màu nâu nhạt của giày dép hoặc túi xách.', 'His summer tan had faded by the middle of winter.', NULL, 'Làn da rám nắng mùa hè của anh ấy đã phai bớt vào giữa mùa đông.', '{"wordId":"tan","ukIpa":"/tæn/","usIpa":"/tæn/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a darker skin colour caused by exposure to the sun","vi":"da rám nắng"},{"pos":"v.","en":"to become or make skin darker through exposure to sunlight","vi":"làm cho da rám nắng"},{"pos":"adj.","en":"having a light brown colour","vi":"có màu nâu vàng; màu nâu nhạt"}],"examples":[{"en":"His summer tan had faded by the middle of winter.","vi":"Làn da rám nắng mùa hè của anh ấy đã phai bớt vào giữa mùa đông.","audioKind":"ex"},{"en":"Although a tan is sometimes considered attractive, prolonged exposure to sunlight increases the risk of skin damage.","vi":"Mặc dù làn da rám nắng đôi khi được coi là hấp dẫn, việc tiếp xúc lâu với ánh nắng mặt trời sẽ làm tăng nguy cơ tổn thương da.","audioKind":"ex2"}],"collocations":[{"en":"get a tan","vi":"có làn da rám nắng"},{"en":"a deep tan","vi":"làn da rám nắng đậm"},{"en":"tan leather","vi":"da thuộc màu nâu vàng"}],"wordFamily":["tanned (adj.)","tanning (n.)"],"synonyms":[],"antonyms":[],"tipVi":"tan không chỉ chỉ việc phơi nắng cho da sạm đi; khi làm tính từ, nó cũng có thể mô tả màu nâu nhạt của giày dép hoặc túi xách.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_greet', 'en-b1-52', 'greet', '/ɡriːt/', 'B1', 'chào hỏi; đón tiếp; đập vào mắt; truyền đến tai', 'v.', 'greeting (n.)', 'Đồng nghĩa: welcome', 'greet đi trực tiếp với tân ngữ chỉ người; để biểu đạt ý chào hỏi ai đó thì không dùng giới từ to.', 'Our neighbours greeted us warmly when we moved in.', NULL, 'Hàng xóm đã chào đón chúng tôi rất nồng nhiệt khi chúng tôi chuyển đến.', '{"wordId":"greet","ukIpa":"/ɡriːt/","usIpa":"/ɡriːt/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to welcome someone or say hello","vi":"chào hỏi; đón tiếp"},{"pos":"v.","en":"to become noticeable when someone arrives or looks","vi":"đập vào mắt; truyền đến tai"}],"examples":[{"en":"Our neighbours greeted us warmly when we moved in.","vi":"Hàng xóm đã chào đón chúng tôi rất nồng nhiệt khi chúng tôi chuyển đến.","audioKind":"ex"},{"en":"Visitors are greeted by trained volunteers who explain the museum''s collection and help them find their way.","vi":"Khách tham quan được chào đón bởi các tình nguyện viên được đào tạo bài bản, những người sẽ giới thiệu bộ sưu tập của bảo tàng và giúp họ định hướng.","audioKind":"ex2"}],"collocations":[{"en":"greet someone warmly","vi":"chào hỏi ai đó nồng nhiệt"},{"en":"greet someone with a smile","vi":"chào đón ai đó bằng nụ cười"},{"en":"be greeted by","vi":"được chào đón bởi; đập vào mắt"}],"wordFamily":["greeting (n.)"],"synonyms":["welcome"],"antonyms":[],"tipVi":"greet đi trực tiếp với tân ngữ chỉ người; để biểu đạt ý chào hỏi ai đó thì không dùng giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sleeve', 'en-b1-52', 'sleeve', '/sliːv/', 'B1', 'tay áo; vỏ bọc bảo vệ', 'n.', 'sleeveless (adj.)', NULL, 'sleeve chỉ phần tay áo của trang phục, không phải là phần cánh tay (arm).', 'I caught my sleeve on the kitchen door handle.', NULL, 'Tay áo của tôi đã bị mắc vào tay nắm cửa nhà bếp.', '{"wordId":"sleeve","ukIpa":"/sliːv/","usIpa":"/sliːv/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The part of a garment that covers an arm.","vi":"tay áo"},{"pos":"n.","en":"A protective cover that fits closely around an object.","vi":"vỏ bọc bảo vệ"}],"examples":[{"en":"I caught my sleeve on the kitchen door handle.","vi":"Tay áo của tôi đã bị mắc vào tay nắm cửa nhà bếp.","audioKind":"ex"},{"en":"Workers should keep loose sleeves away from moving machinery to reduce the risk of workplace injuries.","vi":"Công nhân nên giữ cho tay áo rộng tránh xa các máy móc đang chuyển động để giảm nguy cơ tai nạn lao động.","audioKind":"ex2"}],"collocations":[{"en":"long sleeves","vi":"tay áo dài"},{"en":"roll up your sleeves","vi":"xắn tay áo lên"},{"en":"protective sleeve","vi":"vỏ bọc bảo vệ"}],"wordFamily":["sleeveless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"sleeve chỉ phần tay áo của trang phục, không phải là phần cánh tay (arm).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cardboard', 'en-b1-52', 'cardboard', '/ˈkɑːrdbɔːrd/', 'B1', 'bìa cứng; giấy các-tông', 'n.', NULL, NULL, 'Danh từ này thường không đếm được; khi muốn nói một tấm bìa cứng, hãy dùng a sheet of cardboard.', 'We cut the cardboard into shapes for a model house.', NULL, 'Chúng tôi cắt tấm bìa cứng thành nhiều hình thù để làm mô hình ngôi nhà.', '{"wordId":"cardboard","ukIpa":"/ˈkɑːdbɔːd/","usIpa":"/ˈkɑːrdbɔːrd/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Thick, stiff paper used for boxes and packaging","vi":"bìa cứng; giấy các-tông"}],"examples":[{"en":"We cut the cardboard into shapes for a model house.","vi":"Chúng tôi cắt tấm bìa cứng thành nhiều hình thù để làm mô hình ngôi nhà.","audioKind":"ex"},{"en":"Replacing plastic packaging with recycled cardboard can reduce waste and encourage more sustainable consumption.","vi":"Việc thay thế bao bì nhựa bằng bìa cứng tái chế có thể làm giảm rác thải và thúc đẩy tiêu dùng bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"cardboard box","vi":"hộp giấy cứng; thùng các-tông"},{"en":"recycled cardboard","vi":"bìa cứng tái chế"},{"en":"a sheet of cardboard","vi":"một tấm bìa cứng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ này thường không đếm được; khi muốn nói một tấm bìa cứng, hãy dùng a sheet of cardboard.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tick', 'en-b1-52', 'tick', '/tɪk/', 'B1', 'đánh dấu tích; phát ra tiếng tích tắc; dấu tích; tiếng tích tắc ngắn; con ve; con rận', 'v.', 'ticking (n.)', NULL, '"Đánh dấu" tiếng Anh-Anh thường dùng tick, tiếng Anh-Mỹ thường dùng check.', 'The old clock ticks softly beside my bed.', NULL, 'Chiếc đồng hồ cũ đang tích tắc nhẹ nhàng bên cạnh giường tôi.', '{"wordId":"tick","ukIpa":"/tɪk/","usIpa":"/tɪk/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To mark an item as correct, or make repeated clicking sounds.","vi":"đánh dấu tích; phát ra tiếng tích tắc"},{"pos":"n.","en":"A mark showing correctness, or a short sound a clock makes.","vi":"dấu tích; tiếng tích tắc ngắn"},{"pos":"n.","en":"A small creature that attaches to skin and feeds on blood.","vi":"con ve; con rận"}],"examples":[{"en":"The old clock ticks softly beside my bed.","vi":"Chiếc đồng hồ cũ đang tích tắc nhẹ nhàng bên cạnh giường tôi.","audioKind":"ex"},{"en":"Participants should tick the appropriate boxes to indicate how frequently they use public transport.","vi":"Những người tham gia nên đánh dấu vào các ô thích hợp để cho biết tần suất họ sử dụng phương tiện giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"tick a box","vi":"đánh dấu vào ô trống"},{"en":"tick off","vi":"đánh dấu hoàn thành"},{"en":"a tick bite","vi":"vết ve cắn"},{"en":"a clock ticks","vi":"đồng hồ kêu tích tắc"}],"wordFamily":["ticking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"Đánh dấu\" tiếng Anh-Anh thường dùng tick, tiếng Anh-Mỹ thường dùng check.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_warning', 'en-b1-52', 'warning', '/ˈwɔːrnɪŋ/', 'B1', 'lời cảnh báo; sự nhắc nhở; điềm báo; dấu hiệu báo trước', 'n.', 'warn (v.)', 'Đồng nghĩa: alert, caution', 'warning là danh từ, cũng có thể là dạng phân từ hiện tại của warn.', 'We turned back after the guide''s warning about slippery rocks.', NULL, 'Chúng tôi đã quay trở lại sau lời cảnh báo của hướng dẫn viên về những tảng đá trơn trượt.', '{"wordId":"warning","ukIpa":"/ˈwɔːnɪŋ/","usIpa":"/ˈwɔːrnɪŋ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Something said or done to alert someone to danger or problems.","vi":"lời cảnh báo; sự nhắc nhở"},{"pos":"n.","en":"A sign that something harmful or unpleasant may happen.","vi":"điềm báo; dấu hiệu báo trước"}],"examples":[{"en":"We turned back after the guide''s warning about slippery rocks.","vi":"Chúng tôi đã quay trở lại sau lời cảnh báo của hướng dẫn viên về những tảng đá trơn trượt.","audioKind":"ex"},{"en":"Effective flood warning systems allow residents to leave dangerous areas before roads become impossible to use.","vi":"Các hệ thống cảnh báo lũ lụt hiệu quả cho phép người dân sơ tán khỏi các khu vực nguy hiểm trước khi đường sá trở nên không thể sử dụng được.","audioKind":"ex2"}],"collocations":[{"en":"issue a warning","vi":"đưa ra cảnh báo"},{"en":"early warning system","vi":"hệ thống cảnh báo sớm"},{"en":"without warning","vi":"không một lời cảnh báo; hoàn toàn bất ngờ"},{"en":"heed a warning","vi":"lưu ý cảnh báo; nghe theo cảnh báo"}],"wordFamily":["warn (v.)"],"synonyms":["alert","caution"],"antonyms":[],"tipVi":"warning là danh từ, cũng có thể là dạng phân từ hiện tại của warn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_delivery', 'en-b1-52', 'delivery', '/dɪˈlɪvəri/', 'B1', 'sự giao hàng; sự phân phát; sự sinh con; sự vượt cạn; phong cách trình bày; cách diễn đạt (khi nói trước công chúng)', 'n.', 'deliver (v.)', NULL, 'delivery chỉ dịch vụ hoặc quá trình giao hàng; deliver là động từ tương ứng.', 'Our grocery delivery arrived just before we started cooking.', NULL, 'Đơn hàng giao thực phẩm của chúng tôi vừa đến ngay trước khi chúng tôi bắt đầu nấu ăn.', '{"wordId":"delivery","ukIpa":"/dɪˈlɪvəri/","usIpa":"/dɪˈlɪvəri/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"the act of taking goods or messages to someone","vi":"sự giao hàng; sự phân phát"},{"pos":"n.","en":"the process of giving birth to a baby","vi":"sự sinh con; sự vượt cạn"},{"pos":"n.","en":"the way someone speaks or performs in public","vi":"phong cách trình bày; cách diễn đạt (khi nói trước công chúng)"}],"examples":[{"en":"Our grocery delivery arrived just before we started cooking.","vi":"Đơn hàng giao thực phẩm của chúng tôi vừa đến ngay trước khi chúng tôi bắt đầu nấu ăn.","audioKind":"ex"},{"en":"The growing demand for home delivery has increased traffic congestion in many urban neighbourhoods.","vi":"Nhu cầu ngày càng tăng về dịch vụ giao hàng tận nhà đã làm gia tăng tình trạng ùn tắc giao thông ở nhiều khu đô thị.","audioKind":"ex2"}],"collocations":[{"en":"free delivery","vi":"giao hàng miễn phí"},{"en":"delivery service","vi":"dịch vụ giao hàng"},{"en":"delivery driver","vi":"tài xế giao hàng"},{"en":"a smooth delivery","vi":"ca sinh nở thuận lợi"}],"wordFamily":["deliver (v.)"],"synonyms":[],"antonyms":[],"tipVi":"delivery chỉ dịch vụ hoặc quá trình giao hàng; deliver là động từ tương ứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frame', 'en-b1-52', 'frame', '/freɪm/', 'B1', 'khung; khung sườn; đóng khung; định hình; cấu trúc lời lẽ', 'n.', 'framework (n.), framing (n.), reframe (v.)', NULL, 'frame có thể chỉ khung vật lý hoặc cách diễn đạt, trình bày một vấn đề.', 'We chose a wooden frame for our family photograph.', NULL, 'Chúng tôi chọn một chiếc khung gỗ cho bức ảnh gia đình.', '{"wordId":"frame","ukIpa":"/freɪm/","usIpa":"/freɪm/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a structure that surrounds or supports something","vi":"khung; khung sườn"},{"pos":"v.","en":"to put a picture or similar object inside a frame","vi":"đóng khung"},{"pos":"v.","en":"to express or present something in a particular way","vi":"định hình; cấu trúc lời lẽ"}],"examples":[{"en":"We chose a wooden frame for our family photograph.","vi":"Chúng tôi chọn một chiếc khung gỗ cho bức ảnh gia đình.","audioKind":"ex"},{"en":"The way journalists frame environmental issues can influence public attitudes towards conservation and government policy.","vi":"Cách các nhà báo định hình các vấn đề môi trường có thể ảnh hưởng đến thái độ của công chúng đối với việc bảo tồn và chính sách của chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"a picture frame","vi":"khung ảnh"},{"en":"a bicycle frame","vi":"khung xe đạp"},{"en":"frame a question","vi":"đặt câu hỏi"},{"en":"a frame of reference","vi":"khung tham chiếu"}],"wordFamily":["framework (n.)","framing (n.)","reframe (v.)"],"synonyms":[],"antonyms":[],"tipVi":"frame có thể chỉ khung vật lý hoặc cách diễn đạt, trình bày một vấn đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_though', 'en-b1-52', 'though', '/ðoʊ/', 'B1', 'mặc dù; dù cho; tuy nhiên; thế nhưng', 'conj.', NULL, 'Đồng nghĩa: although, however', 'Khi làm liên từ chỉ sự nhượng bộ, không dùng chung với but; đặt ở cuối câu để mang nghĩa "tuy nhiên".', 'Though it was raining, we still walked to the bakery.', NULL, 'Dù trời đang mưa, chúng tôi vẫn đi bộ đến tiệm bánh.', '{"wordId":"though","ukIpa":"/ðəʊ/","usIpa":"/ðoʊ/","cefr":"B1","topic":"daily","senses":[{"pos":"conj.","en":"Despite the fact that something is true.","vi":"mặc dù; dù cho"},{"pos":"adv.","en":"Used to introduce a contrasting point, often at sentence end.","vi":"tuy nhiên; thế nhưng"}],"examples":[{"en":"Though it was raining, we still walked to the bakery.","vi":"Dù trời đang mưa, chúng tôi vẫn đi bộ đến tiệm bánh.","audioKind":"ex"},{"en":"Though online courses offer greater flexibility, many students still benefit from direct interaction with teachers.","vi":"Mặc dù các khóa học trực tuyến mang lại sự linh hoạt lớn hơn, nhiều sinh viên vẫn nhận được lợi ích từ sự tương tác trực tiếp với giáo viên.","audioKind":"ex2"}],"collocations":[{"en":"even though","vi":"thậm chí ngay cả khi"},{"en":"as though","vi":"như thể là"}],"wordFamily":[],"synonyms":["although","however"],"antonyms":[],"tipVi":"Khi làm liên từ chỉ sự nhượng bộ, không dùng chung với but; đặt ở cuối câu để mang nghĩa \"tuy nhiên\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flour', 'en-b1-52', 'flour', '/ˈflaʊər/', 'B1', 'bột mì; bột ngũ cốc; rắc bột', 'n.', 'floury (adj.)', NULL, 'flour thường là danh từ không đếm được, và phát âm giống từ flower.', 'Add the flour slowly and stir until smooth.', NULL, 'Từ từ cho bột mì vào và khuấy đều cho đến khi mịn màng.', '{"wordId":"flour","ukIpa":"/flaʊə/","usIpa":"/ˈflaʊər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"powder made by grinding grain, used especially in baking","vi":"bột mì; bột ngũ cốc"},{"pos":"v.","en":"to cover a surface or food lightly with flour","vi":"rắc bột"}],"examples":[{"en":"Add the flour slowly and stir until smooth.","vi":"Từ từ cho bột mì vào và khuấy đều cho đến khi mịn màng.","audioKind":"ex"},{"en":"Replacing some refined flour with wholemeal flour can increase the fibre content of everyday foods.","vi":"Thay thế một phần bột mì tinh luyện bằng bột mì nguyên cám có thể làm tăng hàm lượng chất xơ trong các loại thực phẩm hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"plain flour","vi":"bột mì đa dụng"},{"en":"wholemeal flour","vi":"bột mì nguyên cám"},{"en":"rice flour","vi":"bột gạo"},{"en":"flour a surface","vi":"rắc bột lên bề mặt"}],"wordFamily":["floury (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"flour thường là danh từ không đếm được, và phát âm giống từ flower.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_length', 'en-b1-52', 'length', '/leŋθ/', 'B1', 'chiều dài; độ dài; thời lượng; khoảng thời gian', 'n.', 'long (adj.), lengthen (v.), lengthy (adj.)', NULL, 'at length thường mang nghĩa là "chi tiết; tường tận", không phải "theo chiều dài".', 'We measured the length of the table before buying chairs.', NULL, 'Chúng tôi đã đo chiều dài của cái bàn trước khi mua ghế.', '{"wordId":"length","ukIpa":"/leŋθ/","usIpa":"/leŋθ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The distance from one end of something to the other.","vi":"chiều dài; độ dài"},{"pos":"n.","en":"The amount of time something lasts.","vi":"thời lượng; khoảng thời gian"}],"examples":[{"en":"We measured the length of the table before buying chairs.","vi":"Chúng tôi đã đo chiều dài của cái bàn trước khi mua ghế.","audioKind":"ex"},{"en":"The length of the school day can affect both student concentration and family routines.","vi":"Thời lượng của một ngày học có thể ảnh hưởng đến cả sự tập trung của học sinh lẫn sinh hoạt thường ngày của gia đình.","audioKind":"ex2"}],"collocations":[{"en":"in length","vi":"về chiều dài"},{"en":"the length of time","vi":"độ dài thời gian"},{"en":"at length","vi":"một cách chi tiết"}],"wordFamily":["long (adj.)","lengthen (v.)","lengthy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"at length thường mang nghĩa là \"chi tiết; tường tận\", không phải \"theo chiều dài\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_baby-sit', 'en-b1-52', 'baby-sit', '/ˈbeɪbisɪt/', 'B1', 'trông trẻ hộ; giữ em bé', 'v.', 'babysitter (n.), babysitting (n.)', NULL, 'Thường được viết liền là babysit; dạng quá khứ là baby-sat.', 'Could you baby-sit for us on Saturday evening?', NULL, 'Bạn có thể trông con giúp chúng tôi vào tối thứ Bảy được không?', '{"wordId":"baby-sit","ukIpa":"/ˈbeɪbisɪt/","usIpa":"/ˈbeɪbisɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To look after children while their parents are away.","vi":"trông trẻ hộ; giữ em bé"}],"examples":[{"en":"Could you baby-sit for us on Saturday evening?","vi":"Bạn có thể trông con giúp chúng tôi vào tối thứ Bảy được không?","audioKind":"ex"},{"en":"Relatives who baby-sit regularly can reduce childcare costs and help parents remain in employment.","vi":"Những họ hàng thường xuyên giúp trông con có thể giảm bớt chi phí nuôi dạy trẻ và giúp các bậc cha mẹ tiếp tục đi làm.","audioKind":"ex2"}],"collocations":[{"en":"baby-sit for someone","vi":"trông trẻ giúp ai đó"},{"en":"baby-sit the children","vi":"trông nom các con"}],"wordFamily":["babysitter (n.)","babysitting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường được viết liền là babysit; dạng quá khứ là baby-sat.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sticky', 'en-b1-52', 'sticky', '/ˈstɪki/', 'B1', 'dính; có độ dính; ẩm ướt; oi bức; gay go; khó xử; hóc búa', 'adj.', 'stick (v.), stickiness (n.)', 'Đồng nghĩa: adhesive, tacky', 'Sticky weather chỉ thời tiết oi bức; sticky situation chỉ hoàn cảnh khó xử.', 'My fingers were sticky after eating the honey cake.', NULL, 'Ngón tay tôi dính dấp sau khi ăn bánh mật ong.', '{"wordId":"sticky","ukIpa":"/ˈstɪki/","usIpa":"/ˈstɪki/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"able to stick to things, often because of a substance","vi":"dính; có độ dính"},{"pos":"adj.","en":"uncomfortably warm and damp","vi":"ẩm ướt; oi bức"},{"pos":"adj.","en":"difficult or awkward to deal with","vi":"gay go; khó xử; hóc búa"}],"examples":[{"en":"My fingers were sticky after eating the honey cake.","vi":"Ngón tay tôi dính dấp sau khi ăn bánh mật ong.","audioKind":"ex"},{"en":"Food packaging often contains sticky residues that must be removed before the materials can be recycled effectively.","vi":"Bao bì thực phẩm thường chứa các chất cặn bính phải được làm sạch trước khi vật liệu có thể được tái chế hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"sticky tape","vi":"băng dính"},{"en":"sticky fingers","vi":"ngón tay dính dấp"},{"en":"a sticky situation","vi":"hoàn cảnh khó xử"},{"en":"hot and sticky","vi":"nóng bức và oi ả"}],"wordFamily":["stick (v.)","stickiness (n.)"],"synonyms":["adhesive","tacky"],"antonyms":[],"tipVi":"Sticky weather chỉ thời tiết oi bức; sticky situation chỉ hoàn cảnh khó xử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unless', 'en-b1-52', 'unless', '/ənˈles/', 'B1', 'trừ khi; nếu không', 'conj.', NULL, NULL, 'Khi diễn tả điều kiện trong tương lai, mệnh đề unless thường dùng thì hiện tại đơn.', 'We will eat outside unless it starts to rain.', NULL, 'Chúng tôi sẽ ăn ngoài trừ khi trời bắt đầu mưa.', '{"wordId":"unless","ukIpa":"/ənˈles/","usIpa":"/ənˈles/","cefr":"B1","topic":"daily","senses":[{"pos":"conj.","en":"except if; if something does not happen or is untrue","vi":"trừ khi; nếu không"}],"examples":[{"en":"We will eat outside unless it starts to rain.","vi":"Chúng tôi sẽ ăn ngoài trừ khi trời bắt đầu mưa.","audioKind":"ex"},{"en":"Public transport will remain unpopular unless local authorities improve its reliability and make fares more affordable.","vi":"Giao thông công cộng sẽ vẫn kém thu hút trừ khi chính quyền địa phương nâng cao độ tin cậy và làm cho giá vé hợp lý hơn.","audioKind":"ex2"}],"collocations":[{"en":"unless otherwise stated","vi":"trừ khi có quy định khác"},{"en":"unless absolutely necessary","vi":"trừ khi thực sự cần thiết"},{"en":"unless circumstances change","vi":"trừ khi hoàn cảnh thay đổi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi diễn tả điều kiện trong tương lai, mệnh đề unless thường dùng thì hiện tại đơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_precious', 'en-b1-52', 'precious', '/ˈpreʃəs/', 'B1', 'quý giá; đắt tiền; quý báu; đáng trân trọng', 'adj.', 'preciously (adv.), preciousness (n.)', 'Đồng nghĩa: valuable, treasured · Trái nghĩa: worthless', 'Có thể dùng để chỉ giá trị vật chất cao hoặc giá trị tinh thần, sự khan hiếm.', 'She keeps her precious necklace in a velvet box.', NULL, 'Cô ấy giữ chiếc vòng cổ quý giá của mình trong một chiếc hộp nhung.', '{"wordId":"precious","ukIpa":"/ˈpreʃəs/","usIpa":"/ˈpreʃəs/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Worth a lot of money or deserving great care.","vi":"quý giá; đắt tiền"},{"pos":"adj.","en":"Deeply valued because of personal importance or limited availability.","vi":"quý báu; đáng trân trọng"}],"examples":[{"en":"She keeps her precious necklace in a velvet box.","vi":"Cô ấy giữ chiếc vòng cổ quý giá của mình trong một chiếc hộp nhung.","audioKind":"ex"},{"en":"Fresh water is a precious resource that requires careful management as populations grow and temperatures rise.","vi":"Nước ngọt là một nguồn tài nguyên quý giá đòi hỏi phải quản lý cẩn thận khi dân số tăng lên và nhiệt độ ngày càng cao.","audioKind":"ex2"}],"collocations":[{"en":"precious metals","vi":"kim loại quý"},{"en":"precious stones","vi":"đá quý"},{"en":"precious memories","vi":"những ký ức quý giá"},{"en":"precious resources","vi":"nguồn tài nguyên quý giá"}],"wordFamily":["preciously (adv.)","preciousness (n.)"],"synonyms":["valuable","treasured"],"antonyms":["worthless"],"tipVi":"Có thể dùng để chỉ giá trị vật chất cao hoặc giá trị tinh thần, sự khan hiếm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paste', 'en-b1-52', 'paste', '/peɪst/', 'B1', 'chất nhão; hồ dán; dán; dán (văn bản/hình ảnh trên máy tính)', 'n.', NULL, NULL, 'Danh từ chỉ chất nhão thường không đếm được; trong máy tính dùng để chỉ thao tác ''dán''.', 'Mix the flour with water to make a paste.', NULL, 'Trộn bột mì với nước để tạo thành hỗn hợp sệt.', '{"wordId":"paste","ukIpa":"/peɪst/","usIpa":"/peɪst/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A thick, soft mixture, sometimes used for sticking things together.","vi":"chất nhão; hồ dán"},{"pos":"v.","en":"To stick something onto a surface using paste.","vi":"dán"},{"pos":"v.","en":"To insert copied text or images into a digital location.","vi":"dán (văn bản/hình ảnh trên máy tính)"}],"examples":[{"en":"Mix the flour with water to make a paste.","vi":"Trộn bột mì với nước để tạo thành hỗn hợp sệt.","audioKind":"ex"},{"en":"Students should not simply paste material from websites into assignments without acknowledging the original sources.","vi":"Học sinh không nên chỉ sao chép tài liệu từ các trang web rồi dán vào bài tập mà không ghi rõ nguồn gốc.","audioKind":"ex2"}],"collocations":[{"en":"tomato paste","vi":"sốt cà chua"},{"en":"wallpaper paste","vi":"keo dán tường"},{"en":"paste onto","vi":"dán lên"},{"en":"copy and paste","vi":"sao chép và dán"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ chất nhão thường không đếm được; trong máy tính dùng để chỉ thao tác ''dán''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chin', 'en-b1-52', 'chin', '/tʃɪn/', 'B1', 'cằm', 'n.', NULL, NULL, 'chin chỉ cằm; jaw chỉ hàm, phạm vi rộng hơn.', 'He rested his chin on his hand and sighed.', NULL, 'Anh ấy chống cằm lên tay rồi thở dài.', '{"wordId":"chin","ukIpa":"/tʃɪn/","usIpa":"/tʃɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The part of your face below your mouth.","vi":"cằm"}],"examples":[{"en":"He rested his chin on his hand and sighed.","vi":"Anh ấy chống cằm lên tay rồi thở dài.","audioKind":"ex"},{"en":"Cyclists should adjust helmet straps beneath the chin to ensure a secure fit during travel.","vi":"Người đi xe đạp nên điều chỉnh quai mũ bảo hiểm ở dưới cằm để đảm bảo cố định chắc chắn trong suốt quá trình di chuyển.","audioKind":"ex2"}],"collocations":[{"en":"rest your chin on your hand","vi":"chống cằm lên tay"},{"en":"a pointed chin","vi":"cằm nhọn"},{"en":"a double chin","vi":"cằm đôi; nọng cằm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"chin chỉ cằm; jaw chỉ hàm, phạm vi rộng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_partly', 'en-b1-52', 'partly', '/ˈpɑːrtli/', 'B1', 'một phần; ở một mức độ nào đó', 'adv.', 'part (n.)', 'Đồng nghĩa: partially · Trái nghĩa: completely, entirely', 'Biểu thị một phần chứ không phải toàn bộ; thường dùng partly because để giải thích nguyên nhân.', 'The path was partly covered with fallen leaves.', NULL, 'Con đường bị che khuất một phần bởi những chiếc lá rụng.', '{"wordId":"partly","ukIpa":"/ˈpɑːtli/","usIpa":"/ˈpɑːrtli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"To some extent, but not completely.","vi":"một phần; ở một mức độ nào đó"}],"examples":[{"en":"The path was partly covered with fallen leaves.","vi":"Con đường bị che khuất một phần bởi những chiếc lá rụng.","audioKind":"ex"},{"en":"The rise in cycling is partly due to improved infrastructure and growing concern about air quality.","vi":"Sự gia tăng số lượng người đi xe đạp một phần là do cơ sở hạ tầng được cải thiện và sự quan tâm ngày càng tăng đối với chất lượng không khí.","audioKind":"ex2"}],"collocations":[{"en":"partly because","vi":"một phần là vì"},{"en":"partly due to","vi":"một phần là do"},{"en":"partly responsible","vi":"chịu một phần trách nhiệm"},{"en":"partly cloudy","vi":"trời mây rải rác; có mây một phần"}],"wordFamily":["part (n.)"],"synonyms":["partially"],"antonyms":["completely","entirely"],"tipVi":"Biểu thị một phần chứ không phải toàn bộ; thường dùng partly because để giải thích nguyên nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_old-fashioned', 'en-b1-52', 'old-fashioned', '/ˌoʊldˈfæʃənd/', 'B1', 'lỗi thời; theo kiểu cũ; cổ hủ; theo lối truyền thống', 'adj.', NULL, 'Đồng nghĩa: traditional · Trái nghĩa: modern, fashionable', 'Có thể mang ý hoài niệm, ca ngợi; outdated nhấn mạnh hơn việc đã không còn phù hợp.', 'My grandfather still uses an old-fashioned clock with a pendulum.', NULL, 'Ông tôi vẫn dùng một chiếc đồng hồ quả lắc theo kiểu cũ.', '{"wordId":"old-fashioned","ukIpa":"/ˌəʊldˈfæʃənd/","usIpa":"/ˌoʊldˈfæʃənd/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Belonging to a style that was common in the past.","vi":"lỗi thời; theo kiểu cũ"},{"pos":"adj.","en":"Following beliefs or customs associated with earlier times.","vi":"cổ hủ; theo lối truyền thống"}],"examples":[{"en":"My grandfather still uses an old-fashioned clock with a pendulum.","vi":"Ông tôi vẫn dùng một chiếc đồng hồ quả lắc theo kiểu cũ.","audioKind":"ex"},{"en":"Although some teaching methods seem old-fashioned, they can still help students develop concentration and independent thinking.","vi":"Mặc dù một số phương pháp giảng dạy có vẻ lỗi thời, chúng vẫn có thể giúp học sinh phát triển sự tập trung và tư duy độc lập.","audioKind":"ex2"}],"collocations":[{"en":"old-fashioned clothes","vi":"quần áo kiểu cũ"},{"en":"old-fashioned values","vi":"giá trị truyền thống"},{"en":"old-fashioned manners","vi":"phong cách ứng xử truyền thống"}],"wordFamily":[],"synonyms":["traditional"],"antonyms":["modern","fashionable"],"tipVi":"Có thể mang ý hoài niệm, ca ngợi; outdated nhấn mạnh hơn việc đã không còn phù hợp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vanilla', 'en-b1-52', 'vanilla', '/vəˈnɪlə/', 'B1', 'hương va-ni; quả va-ni; có hương vị va-ni', 'n.', NULL, NULL, 'Trong thực phẩm, vanilla chỉ một loại gia vị cụ thể, không dùng để chỉ tất cả các loại thảo mộc nói chung.', 'Add a little vanilla before you mix the batter.', NULL, 'Hãy cho thêm một chút hương va-ni trước khi bạn trộn bột.', '{"wordId":"vanilla","ukIpa":"/vəˈnɪlə/","usIpa":"/vəˈnɪlə/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A sweet-smelling substance from tropical plant pods, used to flavour food.","vi":"hương va-ni; quả va-ni"},{"pos":"adj.","en":"Flavoured with vanilla.","vi":"có hương vị va-ni"}],"examples":[{"en":"Add a little vanilla before you mix the batter.","vi":"Hãy cho thêm một chút hương va-ni trước khi bạn trộn bột.","audioKind":"ex"},{"en":"Demand for natural vanilla can provide valuable income for farmers, but unstable prices create financial risks.","vi":"Nhu cầu về va-ni tự nhiên có thể mang lại nguồn thu nhập quý giá cho người nông dân, nhưng giá cả bấp bênh tạo ra rủi ro tài chính.","audioKind":"ex2"}],"collocations":[{"en":"vanilla extract","vi":"chiết xuất va-ni"},{"en":"vanilla ice cream","vi":"kem va-ni"},{"en":"vanilla pod","vi":"quả va-ni"},{"en":"vanilla flavour","vi":"hương vị va-ni"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong thực phẩm, vanilla chỉ một loại gia vị cụ thể, không dùng để chỉ tất cả các loại thảo mộc nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dime', 'en-b1-52', 'dime', '/daɪm/', 'B1', 'đồng mười xu (Mỹ hoặc Canada)', 'n.', NULL, NULL, 'Một đô la bằng mười đồng dime; chủ yếu được dùng trong bối cảnh Mỹ và Canada.', 'A shiny dime rolled out of my jacket pocket.', NULL, 'Một đồng mười xu sáng bóng lăn ra từ túi áo khoác của tôi.', '{"wordId":"dime","ukIpa":"/daɪm/","usIpa":"/daɪm/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A coin worth ten cents in the US or Canada.","vi":"đồng mười xu (Mỹ hoặc Canada)"}],"examples":[{"en":"A shiny dime rolled out of my jacket pocket.","vi":"Một đồng mười xu sáng bóng lăn ra từ túi áo khoác của tôi.","audioKind":"ex"},{"en":"Although a dime has little purchasing power, small cash donations can collectively support valuable community projects.","vi":"Mặc dù một đồng mười xu có sức mua rất nhỏ, các khoản quyên góp tiền mặt nhỏ có thể chung tay hỗ trợ các dự án cộng đồng ý nghĩa.","audioKind":"ex2"}],"collocations":[{"en":"a dime a dozen","vi":"rẻ như bèo; vô cùng phổ biến"},{"en":"not cost a dime","vi":"không tốn một xu"},{"en":"on a dime","vi":"thay đổi đột ngột; dừng lại rất nhanh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Một đô la bằng mười đồng dime; chủ yếu được dùng trong bối cảnh Mỹ và Canada.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bald', 'en-b1-52', 'bald', '/bɔːld/', 'B1', 'hói đầu; trọc; nhẵn thín; mòn (lốp xe)', 'adj.', 'baldness (n.), balding (adj.)', 'Đồng nghĩa: hairless', 'bald chỉ tình trạng hói đầu; bold chỉ sự táo bạo, cần chú ý kỹ về cách phát âm và chính tả.', 'My uncle is bald and always wears a hat.', NULL, 'Chú của tôi bị hói đầu và lúc nào cũng đội mũ.', '{"wordId":"bald","ukIpa":"/bɔːld/","usIpa":"/bɔːld/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"having little or no hair on the head","vi":"hói đầu; trọc"},{"pos":"adj.","en":"lacking the usual covering or surface texture","vi":"nhẵn thín; mòn (lốp xe)"}],"examples":[{"en":"My uncle is bald and always wears a hat.","vi":"Chú của tôi bị hói đầu và lúc nào cũng đội mũ.","audioKind":"ex"},{"en":"Driving with bald tyres increases the risk of accidents, particularly when roads are wet or icy.","vi":"Lái xe với lốp đã bị mòn trơn làm tăng nguy cơ tai nạn, đặc biệt là khi đường ướt hoặc đóng băng.","audioKind":"ex2"}],"collocations":[{"en":"go bald","vi":"bắt đầu hói đầu"},{"en":"a bald head","vi":"một cái đầu trọc"},{"en":"a bald patch","vi":"mảng hói trên đầu"},{"en":"bald tyres","vi":"lốp xe mòn"}],"wordFamily":["baldness (n.)","balding (adj.)"],"synonyms":["hairless"],"antonyms":[],"tipVi":"bald chỉ tình trạng hói đầu; bold chỉ sự táo bạo, cần chú ý kỹ về cách phát âm và chính tả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_simply', 'en-b1-52', 'simply', '/ˈsɪmpli/', 'B1', 'chỉ là; đơn thuần là; một cách đơn giản; giản dị; thực sự; hoàn toàn (dùng để nhấn mạnh)', 'adv.', 'simple (adj.), simplicity (n.), simplify (v.), simplification (n.)', 'Đồng nghĩa: merely, only', 'simply có thể mang nghĩa là "chỉ là", không nhất thiết luôn dịch là "một cách đơn giản".', 'I simply want a quiet evening at home.', NULL, 'Tôi chỉ muốn có một buổi tối yên bình ở nhà.', '{"wordId":"simply","ukIpa":"/ˈsɪmpli/","usIpa":"/ˈsɪmpli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"only, with nothing more involved","vi":"chỉ là; đơn thuần là"},{"pos":"adv.","en":"in an uncomplicated or plain way","vi":"một cách đơn giản; giản dị"},{"pos":"adv.","en":"used to emphasise how strongly something is true","vi":"thực sự; hoàn toàn (dùng để nhấn mạnh)"}],"examples":[{"en":"I simply want a quiet evening at home.","vi":"Tôi chỉ muốn có một buổi tối yên bình ở nhà.","audioKind":"ex"},{"en":"Improving public health requires more than simply encouraging individuals to exercise; affordable facilities are also essential.","vi":"Việc cải thiện sức khỏe cộng đồng không chỉ đơn thuần là khuyến khích cá nhân tập thể dục; các cơ sở vật chất giá cả phải chăng cũng vô cùng thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"simply because","vi":"chỉ vì"},{"en":"put simply","vi":"nói một cách đơn giản"},{"en":"explain simply","vi":"giải thích đơn giản"},{"en":"simply impossible","vi":"hoàn toàn không thể"}],"wordFamily":["simple (adj.)","simplicity (n.)","simplify (v.)","simplification (n.)"],"synonyms":["merely","only"],"antonyms":[],"tipVi":"simply có thể mang nghĩa là \"chỉ là\", không nhất thiết luôn dịch là \"một cách đơn giản\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gentle', 'en-b1-52', 'gentle', '/ˈdʒentəl/', 'B1', 'hiền hòa; cẩn thận, không thô bạo hoặc dùng lực mạnh; nhẹ nhàng, dịu nhẹ về cường độ, chuyển động hoặc tác động; thoai thoải, thoai thoải dốc thay vì dốc đứng', 'adj.', 'gently (adv.), gentleness (n.)', 'Đồng nghĩa: mild, soft · Trái nghĩa: rough, harsh', 'Đối với người, dùng cấu trúc be gentle with sb để chỉ sự đối xử nhẹ nhàng, ân cần.', 'Be gentle when you pick up the little kitten.', NULL, 'Hãy nhẹ tay khi bế chú mèo con nhé.', '{"wordId":"gentle","ukIpa":"/ˈdʒentəl/","usIpa":"/ˈdʒentəl/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Kind and careful, without roughness or force.","vi":"hiền hòa; cẩn thận, không thô bạo hoặc dùng lực mạnh"},{"pos":"adj.","en":"Mild in strength, movement, or effect.","vi":"nhẹ nhàng, dịu nhẹ về cường độ, chuyển động hoặc tác động"},{"pos":"adj.","en":"Rising or falling gradually rather than steeply.","vi":"thoai thoải, thoai thoải dốc thay vì dốc đứng"}],"examples":[{"en":"Be gentle when you pick up the little kitten.","vi":"Hãy nhẹ tay khi bế chú mèo con nhé.","audioKind":"ex"},{"en":"Gentle exercise, such as walking or swimming, can improve physical health without placing excessive strain on joints.","vi":"Các bài tập vận động nhẹ nhàng như đi bộ hoặc bơi lội có thể cải thiện sức khỏe thể chất mà không gây áp lực quá mức lên các khớp.","audioKind":"ex2"}],"collocations":[{"en":"a gentle breeze","vi":"một cơn gió nhẹ"},{"en":"gentle exercise","vi":"bài tập nhẹ nhàng"},{"en":"a gentle slope","vi":"một con dốc thoải"},{"en":"a gentle touch","vi":"cái chạm nhẹ nhàng"}],"wordFamily":["gently (adv.)","gentleness (n.)"],"synonyms":["mild","soft"],"antonyms":["rough","harsh"],"tipVi":"Đối với người, dùng cấu trúc be gentle with sb để chỉ sự đối xử nhẹ nhàng, ân cần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sew', 'en-b1-52', 'sew', '/soʊ/', 'B1', 'khâu, may, vá', 'v.', 'sewing (n.), sewn (adj.)', 'Đồng nghĩa: stitch', 'Dạng quá khứ là sewed; phân từ quá khứ là sewn hoặc sewed; phát âm giống từ so.', 'Can you sew this button back onto my coat?', NULL, 'Bạn có thể khâu lại chiếc cúc này vào áo khoác của tôi không?', '{"wordId":"sew","ukIpa":"/səʊ/","usIpa":"/soʊ/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to join or repair fabric using a needle and thread","vi":"khâu, may, vá"}],"examples":[{"en":"Can you sew this button back onto my coat?","vi":"Bạn có thể khâu lại chiếc cúc này vào áo khoác của tôi không?","audioKind":"ex"},{"en":"Learning to sew enables people to repair damaged clothes rather than discard them, reducing household waste.","vi":"Học cách may vá giúp mọi người sửa chữa quần áo hỏng thay vì vứt bỏ chúng, từ đó giảm thiểu rác thải sinh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"sew on a button","vi":"khâu cúc áo"},{"en":"sew by hand","vi":"khâu bằng tay"},{"en":"sew clothes","vi":"may quần áo"},{"en":"sew up a hole","vi":"vá lỗ thủng"}],"wordFamily":["sewing (n.)","sewn (adj.)"],"synonyms":["stitch"],"antonyms":[],"tipVi":"Dạng quá khứ là sewed; phân từ quá khứ là sewn hoặc sewed; phát âm giống từ so.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lively', 'en-b1-52', 'lively', '/ˈlaɪvli/', 'B1', 'sôi nổi; náo nhiệt; sinh động; hào hứng', 'adj.', 'liveliness (n.), liven (v.)', 'Đồng nghĩa: energetic, animated, vibrant · Trái nghĩa: dull, lifeless', 'Dù tận cùng bằng --ly, từ này là tính từ chứ không phải phó từ.', 'The lively puppy chased a ball around the garden.', NULL, 'Chú cún con vô cùng hiếu động chạy đuổi theo quả bóng quanh khu vườn.', '{"wordId":"lively","ukIpa":"/ˈlaɪvli/","usIpa":"/ˈlaɪvli/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"full of energy, activity, or excitement","vi":"sôi nổi; náo nhiệt"},{"pos":"adj.","en":"interesting and engaging, with enthusiastic activity or discussion","vi":"sinh động; hào hứng"}],"examples":[{"en":"The lively puppy chased a ball around the garden.","vi":"Chú cún con vô cùng hiếu động chạy đuổi theo quả bóng quanh khu vườn.","audioKind":"ex"},{"en":"Lively classroom discussions can encourage students to consider different perspectives and develop critical thinking skills.","vi":"Các cuộc thảo luận sôi nổi trên lớp có thể khuyến khích học sinh xem xét các góc nhìn khác nhau và phát triển kỹ năng tư duy phản biện.","audioKind":"ex2"}],"collocations":[{"en":"lively debate","vi":"cuộc tranh luận sôi nổi"},{"en":"lively atmosphere","vi":"bầu không khí náo nhiệt"},{"en":"lively imagination","vi":"trí tưởng tượng phong phú"}],"wordFamily":["liveliness (n.)","liven (v.)"],"synonyms":["energetic","animated","vibrant"],"antonyms":["dull","lifeless"],"tipVi":"Dù tận cùng bằng --ly, từ này là tính từ chứ không phải phó từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_52_1', 'en-b1-52', 'Cách dùng “tan” (n.) — da rám nắng', 'get a tan  ·  a deep tan  ·  tan leather', 'tan không chỉ chỉ việc phơi nắng cho da sạm đi; khi làm tính từ, nó cũng có thể mô tả màu nâu nhạt của giày dép hoặc túi xách.', 'Họ từ (Word Family): tanned (adj.), tanning (n.)', '[{"hanzi":"His summer tan had faded by the middle of winter.","pinyin":"","meaning":"Làn da rám nắng mùa hè của anh ấy đã phai bớt vào giữa mùa đông."},{"hanzi":"Although a tan is sometimes considered attractive, prolonged exposure to sunlight increases the risk of skin damage.","pinyin":"","meaning":"Mặc dù làn da rám nắng đôi khi được coi là hấp dẫn, việc tiếp xúc lâu với ánh nắng mặt trời sẽ làm tăng nguy cơ tổn thương da."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_52_2', 'en-b1-52', 'Cách dùng “vanilla” (n.) — hương va-ni; quả va-ni', 'vanilla extract  ·  vanilla ice cream  ·  vanilla pod', 'Trong thực phẩm, vanilla chỉ một loại gia vị cụ thể, không dùng để chỉ tất cả các loại thảo mộc nói chung.', NULL, '[{"hanzi":"Add a little vanilla before you mix the batter.","pinyin":"","meaning":"Hãy cho thêm một chút hương va-ni trước khi bạn trộn bột."},{"hanzi":"Demand for natural vanilla can provide valuable income for farmers, but unstable prices create financial risks.","pinyin":"","meaning":"Nhu cầu về va-ni tự nhiên có thể mang lại nguồn thu nhập quý giá cho người nông dân, nhưng giá cả bấp bênh tạo ra rủi ro tài chính."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_52_3', 'en-b1-52', 'Cách dùng “though” (conj.) — mặc dù; dù cho', 'even though  ·  as though', 'Khi làm liên từ chỉ sự nhượng bộ, không dùng chung với but; đặt ở cuối câu để mang nghĩa "tuy nhiên".', 'Đồng nghĩa: although, however', '[{"hanzi":"Though it was raining, we still walked to the bakery.","pinyin":"","meaning":"Dù trời đang mưa, chúng tôi vẫn đi bộ đến tiệm bánh."},{"hanzi":"Though online courses offer greater flexibility, many students still benefit from direct interaction with teachers.","pinyin":"","meaning":"Mặc dù các khóa học trực tuyến mang lại sự linh hoạt lớn hơn, nhiều sinh viên vẫn nhận được lợi ích từ sự tương tác trực tiếp với giáo viên."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_52_4', 'en-b1-52', 'Cách dùng “greet” (v.) — chào hỏi; đón tiếp', 'greet someone warmly  ·  greet someone with a smile  ·  be greeted by', 'greet đi trực tiếp với tân ngữ chỉ người; để biểu đạt ý chào hỏi ai đó thì không dùng giới từ to.', 'Họ từ (Word Family): greeting (n.) | Đồng nghĩa: welcome', '[{"hanzi":"Our neighbours greeted us warmly when we moved in.","pinyin":"","meaning":"Hàng xóm đã chào đón chúng tôi rất nồng nhiệt khi chúng tôi chuyển đến."},{"hanzi":"Visitors are greeted by trained volunteers who explain the museum''s collection and help them find their way.","pinyin":"","meaning":"Khách tham quan được chào đón bởi các tình nguyện viên được đào tạo bài bản, những người sẽ giới thiệu bộ sưu tập của bảo tàng và giúp họ định hướng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_52_1', 'en-b1-52', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_1_1', 'ten_b1_52_1', 'stain', 'There is a coffee stain on your white shirt.', 'There is a coffee stain on your white shirt.', '/steɪn/', 'Có một vết cà phê trên chiếc áo sơ mi trắng của bạn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_1_2', 'ten_b1_52_1', 'tan', 'His summer tan had faded by the middle of winter.', 'His summer tan had faded by the middle of winter.', '/tæn/', 'Làn da rám nắng mùa hè của anh ấy đã phai bớt vào giữa mùa đông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_1_3', 'ten_b1_52_1', 'greet', 'Our neighbours greeted us warmly when we moved in.', 'Our neighbours greeted us warmly when we moved in.', '/ɡriːt/', 'Hàng xóm đã chào đón chúng tôi rất nồng nhiệt khi chúng tôi chuyển đến.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_1_4', 'ten_b1_52_1', 'sleeve', 'I caught my sleeve on the kitchen door handle.', 'I caught my sleeve on the kitchen door handle.', '/sliːv/', 'Tay áo của tôi đã bị mắc vào tay nắm cửa nhà bếp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_1_5', 'ten_b1_52_1', 'cardboard', 'We cut the cardboard into shapes for a model house.', 'We cut the cardboard into shapes for a model house.', '/ˈkɑːrdbɔːrd/', 'Chúng tôi cắt tấm bìa cứng thành nhiều hình thù để làm mô hình ngôi nhà.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_1_6', 'ten_b1_52_1', 'tick', 'The old clock ticks softly beside my bed.', 'The old clock ticks softly beside my bed.', '/tɪk/', 'Chiếc đồng hồ cũ đang tích tắc nhẹ nhàng bên cạnh giường tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_1_7', 'ten_b1_52_1', 'warning', 'We turned back after the guide''s warning about slippery rocks.', 'We turned back after the guide''s warning about slippery rocks.', '/ˈwɔːrnɪŋ/', 'Chúng tôi đã quay trở lại sau lời cảnh báo của hướng dẫn viên về những tảng đá trơn trượt.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_1_8', 'ten_b1_52_1', 'delivery', 'Our grocery delivery arrived just before we started cooking.', 'Our grocery delivery arrived just before we started cooking.', '/dɪˈlɪvəri/', 'Đơn hàng giao thực phẩm của chúng tôi vừa đến ngay trước khi chúng tôi bắt đầu nấu ăn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_52_1_1', 'en-b1-52', 'ten_b1_52_1', 'listening', 'listening', 'There is a coffee stain on your white shirt.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi chỉ muốn có một buổi tối yên bình ở nhà.","Bạn có thể trông con giúp chúng tôi vào tối thứ Bảy được không?","Có một vết cà phê trên chiếc áo sơ mi trắng của bạn.","Chúng tôi sẽ ăn ngoài trừ khi trời bắt đầu mưa."]'::jsonb, 2, 'There is a coffee stain on your white shirt. → Có một vết cà phê trên chiếc áo sơ mi trắng của bạn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_52_1_2', 'en-b1-52', 'ten_b1_52_1', 'listening', 'listening', 'His summer tan had faded by the middle of winter.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chú của tôi bị hói đầu và lúc nào cũng đội mũ.","Con đường bị che khuất một phần bởi những chiếc lá rụng.","Có một vết cà phê trên chiếc áo sơ mi trắng của bạn.","Làn da rám nắng mùa hè của anh ấy đã phai bớt vào giữa mùa đông."]'::jsonb, 3, 'His summer tan had faded by the middle of winter. → Làn da rám nắng mùa hè của anh ấy đã phai bớt vào giữa mùa đông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_52_1_3', 'en-b1-52', 'ten_b1_52_1', 'listening', 'listening', 'Our neighbours greeted us warmly when we moved in.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Có một vết cà phê trên chiếc áo sơ mi trắng của bạn.","Một đồng mười xu sáng bóng lăn ra từ túi áo khoác của tôi.","Con đường bị che khuất một phần bởi những chiếc lá rụng.","Hàng xóm đã chào đón chúng tôi rất nồng nhiệt khi chúng tôi chuyển đến."]'::jsonb, 3, 'Our neighbours greeted us warmly when we moved in. → Hàng xóm đã chào đón chúng tôi rất nồng nhiệt khi chúng tôi chuyển đến.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_52_2', 'en-b1-52', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_2_1', 'ten_b1_52_2', 'stain', 'Manufacturers are developing fabrics that resist stains, potentially reducing the water and energy required for washing.', 'Manufacturers are developing fabrics that resist stains, potentially reducing the water and energy required for washing.', '/steɪn/', 'Các nhà sản xuất đang phát triển các loại vải chống bẩn, qua đó có thể giảm lượng nước và năng lượng cần dùng cho việc giặt giũ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_2_2', 'ten_b1_52_2', 'tan', 'Although a tan is sometimes considered attractive, prolonged exposure to sunlight increases the risk of skin damage.', 'Although a tan is sometimes considered attractive, prolonged exposure to sunlight increases the risk of skin damage.', '/tæn/', 'Mặc dù làn da rám nắng đôi khi được coi là hấp dẫn, việc tiếp xúc lâu với ánh nắng mặt trời sẽ làm tăng nguy cơ tổn thương da.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_2_3', 'ten_b1_52_2', 'greet', 'Visitors are greeted by trained volunteers who explain the museum''s collection and help them find their way.', 'Visitors are greeted by trained volunteers who explain the museum''s collection and help them find their way.', '/ɡriːt/', 'Khách tham quan được chào đón bởi các tình nguyện viên được đào tạo bài bản, những người sẽ giới thiệu bộ sưu tập của bảo tàng và giúp họ định hướng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_2_4', 'ten_b1_52_2', 'sleeve', 'Workers should keep loose sleeves away from moving machinery to reduce the risk of workplace injuries.', 'Workers should keep loose sleeves away from moving machinery to reduce the risk of workplace injuries.', '/sliːv/', 'Công nhân nên giữ cho tay áo rộng tránh xa các máy móc đang chuyển động để giảm nguy cơ tai nạn lao động.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_2_5', 'ten_b1_52_2', 'cardboard', 'Replacing plastic packaging with recycled cardboard can reduce waste and encourage more sustainable consumption.', 'Replacing plastic packaging with recycled cardboard can reduce waste and encourage more sustainable consumption.', '/ˈkɑːrdbɔːrd/', 'Việc thay thế bao bì nhựa bằng bìa cứng tái chế có thể làm giảm rác thải và thúc đẩy tiêu dùng bền vững hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_52_2_6', 'ten_b1_52_2', 'tick', 'Participants should tick the appropriate boxes to indicate how frequently they use public transport.', 'Participants should tick the appropriate boxes to indicate how frequently they use public transport.', '/tɪk/', 'Những người tham gia nên đánh dấu vào các ô thích hợp để cho biết tần suất họ sử dụng phương tiện giao thông công cộng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_52_2_1', 'en-b1-52', 'ten_b1_52_2', 'listening', 'listening', 'Manufacturers are developing fabrics that resist stains, potentially reducing the water and energy required for washing.', NULL, 'Trong câu vừa nghe, từ “stain” mang nghĩa nào sau đây?', '["vết bẩn; vết ố","sự an toàn; sự an tâm","chủ yếu là; phần lớn","gây bối rối; xấu hổ; khó xử"]'::jsonb, 0, '“stain” (/steɪn/): vết bẩn; vết ố. Câu đầy đủ: Manufacturers are developing fabrics that resist stains, potentially reducing the water and energy required for washing.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_52_2_2', 'en-b1-52', 'ten_b1_52_2', 'listening', 'listening', 'Although a tan is sometimes considered attractive, prolonged exposure to sunlight increases the risk of skin damage.', NULL, 'Trong câu vừa nghe, từ “tan” mang nghĩa nào sau đây?', '["mặc dù; dù cho","làm cho lúng túng; làm ngượng ngùng; gây bối rối","da rám nắng","con cá heo"]'::jsonb, 2, '“tan” (/tæn/): da rám nắng. Câu đầy đủ: Although a tan is sometimes considered attractive, prolonged exposure to sunlight increases the risk of skin damage.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
