INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_52_2', 'en-b1-52', NULL, 'comprehensive_test', 'listening', 'His summer tan had faded by the middle of winter.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Làn da rám nắng mùa hè của anh ấy đã phai bớt vào giữa mùa đông.","Chiếc đồng hồ cũ đang tích tắc nhẹ nhàng bên cạnh giường tôi.","Chúng tôi đã quay trở lại sau lời cảnh báo của hướng dẫn viên về những tảng đá trơn trượt.","Chúng tôi sẽ ăn ngoài trừ khi trời bắt đầu mưa."]'::jsonb, 0, 'His summer tan had faded by the middle of winter. → Làn da rám nắng mùa hè của anh ấy đã phai bớt vào giữa mùa đông.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
