INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_52_4', 'en-b1-52', NULL, 'comprehensive_test', 'listening', 'I caught my sleeve on the kitchen door handle.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tay áo của tôi đã bị mắc vào tay nắm cửa nhà bếp.","Bạn có thể trông con giúp chúng tôi vào tối thứ Bảy được không?","Con đường bị che khuất một phần bởi những chiếc lá rụng.","Chú của tôi bị hói đầu và lúc nào cũng đội mũ."]'::jsonb, 0, 'I caught my sleeve on the kitchen door handle. → Tay áo của tôi đã bị mắc vào tay nắm cửa nhà bếp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
