INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_52_6', 'en-b1-52', NULL, 'comprehensive_test', 'listening', 'The old clock ticks softly beside my bed.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy chống cằm lên tay rồi thở dài.","Chúng tôi đã quay trở lại sau lời cảnh báo của hướng dẫn viên về những tảng đá trơn trượt.","Chiếc đồng hồ cũ đang tích tắc nhẹ nhàng bên cạnh giường tôi.","Trộn bột mì với nước để tạo thành hỗn hợp sệt."]'::jsonb, 2, 'The old clock ticks softly beside my bed. → Chiếc đồng hồ cũ đang tích tắc nhẹ nhàng bên cạnh giường tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
