INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_52_8', 'en-b1-52', NULL, 'comprehensive_test', 'listening', 'Our grocery delivery arrived just before we started cooking.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy nhẹ tay khi bế chú mèo con nhé.","Đơn hàng giao thực phẩm của chúng tôi vừa đến ngay trước khi chúng tôi bắt đầu nấu ăn.","Làn da rám nắng mùa hè của anh ấy đã phai bớt vào giữa mùa đông.","Chúng tôi chọn một chiếc khung gỗ cho bức ảnh gia đình."]'::jsonb, 1, 'Our grocery delivery arrived just before we started cooking. → Đơn hàng giao thực phẩm của chúng tôi vừa đến ngay trước khi chúng tôi bắt đầu nấu ăn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
