INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_52_18', 'en-b1-52', NULL, 'comprehensive_test', 'reading', NULL, 'Manufacturers are developing fabrics that resist stains, potentially reducing the water and energy required for washing.', 'Dựa vào câu trên, từ “stain” có nghĩa phù hợp nhất là gì?', '["chúc mừng; tán thành","vết bẩn; vết ố","một tỷ (1.000.000.000)","tàn nhẫn; cay nghiệt"]'::jsonb, 1, 'stain: vết bẩn; vết ố; làm bẩn; làm ố; nhuộm màu; chất nhuộm; chất tạo màu. Dịch cả câu: Các nhà sản xuất đang phát triển các loại vải chống bẩn, qua đó có thể giảm lượng nước và năng lượng cần dùng cho việc giặt giũ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_52_19', 'en-b1-52', NULL, 'comprehensive_test', 'reading', NULL, 'Although a tan is sometimes considered attractive, prolonged exposure to sunlight increases the risk of skin damage.', 'Dựa vào câu trên, từ “tan” có nghĩa phù hợp nhất là gì?', '["da rám nắng","thang cuốn","giải đấu; cuộc thi đấu","tổ chức; cơ quan; hiệp hội"]'::jsonb, 0, 'tan: da rám nắng; làm cho da rám nắng; có màu nâu vàng; màu nâu nhạt. Dịch cả câu: Mặc dù làn da rám nắng đôi khi được coi là hấp dẫn, việc tiếp xúc lâu với ánh nắng mặt trời sẽ làm tăng nguy cơ tổn thương da.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_52_20', 'en-b1-52', NULL, 'comprehensive_test', 'reading', NULL, 'Visitors are greeted by trained volunteers who explain the museum''s collection and help them find their way.', 'Dựa vào câu trên, từ “greet” có nghĩa phù hợp nhất là gì?', '["chào hỏi; đón tiếp","mạng lưới; hệ thống kết nối","khác nhau; gồm nhiều loại khác nhau","lông mày"]'::jsonb, 0, 'greet: chào hỏi; đón tiếp; đập vào mắt; truyền đến tai. Dịch cả câu: Khách tham quan được chào đón bởi các tình nguyện viên được đào tạo bài bản, những người sẽ giới thiệu bộ sưu tập của bảo tàng và giúp họ định hướng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_52_21', 'en-b1-52', NULL, 'comprehensive_test', 'reading', NULL, 'Workers should keep loose sleeves away from moving machinery to reduce the risk of workplace injuries.', 'Dựa vào câu trên, từ “sleeve” có nghĩa phù hợp nhất là gì?', '["tay áo","thuyết phục; khuyên nhủ","vỉa hè; lề đường","sự khó khăn; nỗi vất vả"]'::jsonb, 0, 'sleeve: tay áo; vỏ bọc bảo vệ. Dịch cả câu: Công nhân nên giữ cho tay áo rộng tránh xa các máy móc đang chuyển động để giảm nguy cơ tai nạn lao động.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_52_22', 'en-b1-52', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hiền hòa; cẩn thận, không thô bạo hoặc dùng lực mạnh”', '["argument","gentle","fascinating","altogether"]'::jsonb, 1, 'hiền hòa; cẩn thận, không thô bạo hoặc dùng lực mạnh → gentle (/ˈdʒentəl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_52_23', 'en-b1-52', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khâu, may, vá”', '["battery","sew","obvious","smooth"]'::jsonb, 1, 'khâu, may, vá → sew (/soʊ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_52_24', 'en-b1-52', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sôi nổi; náo nhiệt”', '["undress","treatment","waterskiing","lively"]'::jsonb, 3, 'sôi nổi; náo nhiệt → lively (/ˈlaɪvli/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-53', 'en', 'Bài 53: Đời sống hằng ngày (5) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3053, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contents', 'en-b1-53', 'contents', '/ˈkɑːntents/', 'B1', 'đồ bên trong; nội dung bên trong; mục lục', 'n.', 'content (n.)', NULL, 'contents chỉ vật chứa bên trong hoặc mục lục; nội dung bài viết thường dùng content.', 'She emptied the contents of her bag onto the table.', NULL, 'Cô ấy đổ hết mọi thứ trong túi xách của mình lên bàn.', '{"wordId":"contents","ukIpa":"/ˈkɒntents/","usIpa":"/ˈkɑːntents/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"the things held inside a container or space","vi":"đồ bên trong; nội dung bên trong"},{"pos":"n.","en":"a list of a publication''s sections and their locations","vi":"mục lục"}],"examples":[{"en":"She emptied the contents of her bag onto the table.","vi":"Cô ấy đổ hết mọi thứ trong túi xách của mình lên bàn.","audioKind":"ex"},{"en":"A detailed table of contents helps readers locate relevant information quickly in lengthy academic reports.","vi":"Bảng mục lục chi tiết giúp người đọc nhanh chóng tìm thấy thông tin liên quan trong các báo cáo học thuật dài.","audioKind":"ex2"}],"collocations":[{"en":"table of contents","vi":"bảng mục lục"},{"en":"contents page","vi":"trang mục lục"},{"en":"contents of a bag","vi":"đồ đạc trong túi"}],"wordFamily":["content (n.)"],"synonyms":[],"antonyms":[],"tipVi":"contents chỉ vật chứa bên trong hoặc mục lục; nội dung bài viết thường dùng content.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_neat', 'en-b1-53', 'neat', '/niːt/', 'B1', 'ngăn nắp; gọn gàng; khéo léo; gọn gàng và hiệu quả', 'adj.', 'neatly (adv.), neatness (n.)', 'Đồng nghĩa: tidy, orderly · Trái nghĩa: messy, untidy', 'neat ngoài nghĩa là ngăn nắp, còn có thể dùng để mô tả một giải pháp khéo léo và súc tích.', 'She keeps her gardening tools in neat rows.', NULL, 'Cô ấy xếp các dụng cụ làm vườn thành những hàng ngay ngắn.', '{"wordId":"neat","ukIpa":"/niːt/","usIpa":"/niːt/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"tidy and carefully arranged","vi":"ngăn nắp; gọn gàng"},{"pos":"adj.","en":"clever, simple, and effective","vi":"khéo léo; gọn gàng và hiệu quả"}],"examples":[{"en":"She keeps her gardening tools in neat rows.","vi":"Cô ấy xếp các dụng cụ làm vườn thành những hàng ngay ngắn.","audioKind":"ex"},{"en":"Keeping shared workspaces neat can improve efficiency by making essential equipment easier to locate.","vi":"Việc giữ cho không gian làm việc chung ngăn nắp có thể nâng cao hiệu quả bằng cách giúp việc tìm kiếm các thiết bị cần thiết trở nên dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"neat and tidy","vi":"gọn gàng ngăn nắp"},{"en":"neat handwriting","vi":"chữ viết cẩn thận, sạch sẽ"},{"en":"a neat solution","vi":"một giải pháp khéo léo"}],"wordFamily":["neatly (adv.)","neatness (n.)"],"synonyms":["tidy","orderly"],"antonyms":["messy","untidy"],"tipVi":"neat ngoài nghĩa là ngăn nắp, còn có thể dùng để mô tả một giải pháp khéo léo và súc tích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feature', 'en-b1-53', 'feature', '/ˈfiːtʃər/', 'B1', 'đặc điểm; nét đặc trưng; có nét đặc sắc; nổi bật; đặc điểm khuôn mặt; ngũ quan', 'n.', 'featured (adj.), featureless (adj.)', 'Đồng nghĩa: characteristic, attribute', 'Khi dùng làm động từ, đi thẳng theo tân ngữ mà không dùng feature with.', 'My favourite feature of this backpack is its hidden pocket.', NULL, 'Đặc điểm mà tôi thích nhất ở chiếc ba lô này là chiếc túi ẩn của nó.', '{"wordId":"feature","ukIpa":"/ˈfiːtʃə/","usIpa":"/ˈfiːtʃər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a noticeable or important part of something","vi":"đặc điểm; nét đặc trưng"},{"pos":"v.","en":"to include or present someone or something prominently","vi":"có nét đặc sắc; nổi bật"},{"pos":"n.","en":"a part of the face, such as the nose","vi":"đặc điểm khuôn mặt; ngũ quan"}],"examples":[{"en":"My favourite feature of this backpack is its hidden pocket.","vi":"Đặc điểm mà tôi thích nhất ở chiếc ba lô này là chiếc túi ẩn của nó.","audioKind":"ex"},{"en":"Public parks are an essential feature of cities that prioritise residents'' health and wellbeing.","vi":"Các công viên công cộng là một đặc điểm thiết yếu của những thành phố ưu tiên sức khỏe và hạnh phúc của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"a key feature","vi":"đặc điểm chính"},{"en":"facial features","vi":"đặc điểm khuôn mặt"},{"en":"feature prominently","vi":"đóng vai trò nổi bật; chiếm vị trí quan trọng"}],"wordFamily":["featured (adj.)","featureless (adj.)"],"synonyms":["characteristic","attribute"],"antonyms":[],"tipVi":"Khi dùng làm động từ, đi thẳng theo tân ngữ mà không dùng feature with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_specially', 'en-b1-53', 'specially', '/ˈspeʃəli/', 'B1', 'đặc biệt; riêng biệt', 'adv.', 'special (adj.), speciality (n.), specialise (v.)', NULL, 'specially thiên về mục đích riêng biệt; especially thiên về ý nghĩa nhất là/đặc biệt là.', 'I made this cushion specially for your chair.', NULL, 'Tôi đã làm chiếc đệm lót này dành riêng cho chiếc ghế của bạn.', '{"wordId":"specially","ukIpa":"/ˈspeʃəli/","usIpa":"/ˈspeʃəli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"for a particular purpose or person","vi":"đặc biệt; riêng biệt"}],"examples":[{"en":"I made this cushion specially for your chair.","vi":"Tôi đã làm chiếc đệm lót này dành riêng cho chiếc ghế của bạn.","audioKind":"ex"},{"en":"Schools should provide specially designed learning materials to support students with different educational needs.","vi":"Nhà trường nên cung cấp tài liệu học tập được thiết kế riêng nhằm hỗ trợ học sinh có các nhu cầu giáo dục khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"specially designed","vi":"được thiết kế riêng"},{"en":"specially trained","vi":"được đào tạo chuyên sâu"},{"en":"specially made","vi":"được chế tạo riêng"}],"wordFamily":["special (adj.)","speciality (n.)","specialise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"specially thiên về mục đích riêng biệt; especially thiên về ý nghĩa nhất là/đặc biệt là.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_firework', 'en-b1-53', 'firework', '/ˈfaɪərwɜːrk/', 'B1', 'pháo hoa; pháo bông', 'n.', NULL, NULL, 'Đơn pháo hoa đếm được; từ ''fireworks'' thường dùng chung để chỉ pháo hoa hoặc buổi biểu diễn pháo hoa.', 'A single firework burst above the lake, scattering golden sparks.', NULL, 'Một quả pháo hoa bùng nổ trên mặt hồ, tung ra những tia lửa vàng óng.', '{"wordId":"firework","ukIpa":"/ˈfaɪəwɜːk/","usIpa":"/ˈfaɪərwɜːrk/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"an object that burns or explodes with bright colours outdoors","vi":"pháo hoa; pháo bông"}],"examples":[{"en":"A single firework burst above the lake, scattering golden sparks.","vi":"Một quả pháo hoa bùng nổ trên mặt hồ, tung ra những tia lửa vàng óng.","audioKind":"ex"},{"en":"Public firework displays can attract visitors, although their noise may disturb local residents and wildlife.","vi":"Các màn trình diễn pháo hoa công cộng có thể thu hút khách du lịch, mặc dù tiếng ồn của chúng có thể làm phiền cư dân địa phương và động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"firework display","vi":"màn trình diễn pháo hoa"},{"en":"set off fireworks","vi":"đốt pháo hoa"},{"en":"watch fireworks","vi":"xem pháo hoa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đơn pháo hoa đếm được; từ ''fireworks'' thường dùng chung để chỉ pháo hoa hoặc buổi biểu diễn pháo hoa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_warn', 'en-b1-53', 'warn', '/wɔːrn/', 'B1', 'cảnh báo; nhắc nhở', 'v.', 'warning (n.)', 'Đồng nghĩa: alert, caution', 'Sau ''warn'' có thể dùng mệnh đề ''that''; cụm ''warn sb not to do'' dùng để răn đe, khuyên ngăn.', 'Please warn me if the pan gets too hot.', NULL, 'Hãy nhắc tôi nếu cái chảo trở nên quá nóng nhé.', '{"wordId":"warn","ukIpa":"/wɔːn/","usIpa":"/wɔːrn/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"tell someone about possible danger or an unpleasant consequence","vi":"cảnh báo; nhắc nhở"}],"examples":[{"en":"Please warn me if the pan gets too hot.","vi":"Hãy nhắc tôi nếu cái chảo trở nên quá nóng nhé.","audioKind":"ex"},{"en":"Scientists warn that continued habitat loss could put many more species at risk of extinction.","vi":"Các nhà khoa học cảnh báo rằng tình trạng mất môi trường sống liên tục có thể đẩy nhiều loài hơn nữa vào nguy cơ tuyệt chủng.","audioKind":"ex2"}],"collocations":[{"en":"warn someone about something","vi":"cảnh báo ai về điều gì"},{"en":"warn against doing something","vi":"khuyên ngăn không nên làm gì"},{"en":"warn someone not to do something","vi":"cảnh cáo ai không được làm gì"}],"wordFamily":["warning (n.)"],"synonyms":["alert","caution"],"antonyms":[],"tipVi":"Sau ''warn'' có thể dùng mệnh đề ''that''; cụm ''warn sb not to do'' dùng để răn đe, khuyên ngăn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wipe', 'en-b1-53', 'wipe', '/waɪp/', 'B1', 'lau; chùi; hành động lau chùi; khăn giấy ướt', 'v.', NULL, NULL, 'Động từ ''wipe'' nhấn mạnh hành động lau sạch; ''wipe out'' có thể mang nghĩa xóa sổ hoàn toàn.', 'Please wipe the table before you put the plates down.', NULL, 'Vui lòng lau bàn sạch sẽ trước khi đặt đĩa thức ăn lên nhé.', '{"wordId":"wipe","ukIpa":"/waɪp/","usIpa":"/waɪp/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Rub a surface to remove dirt, liquid, or marks.","vi":"lau; chùi"},{"pos":"n.","en":"An act of rubbing a surface to clean or dry it.","vi":"hành động lau chùi"},{"pos":"n.","en":"A small damp cloth used for cleaning, usually thrown away afterwards.","vi":"khăn giấy ướt"}],"examples":[{"en":"Please wipe the table before you put the plates down.","vi":"Vui lòng lau bàn sạch sẽ trước khi đặt đĩa thức ăn lên nhé.","audioKind":"ex"},{"en":"Schools should encourage pupils to wipe shared equipment after use to help maintain a hygienic learning environment.","vi":"Nhà trường nên khuyến khích học sinh lau chùi các thiết bị dùng chung sau khi sử dụng để giúp duy trì một môi trường học tập vệ sinh.","audioKind":"ex2"}],"collocations":[{"en":"wipe a surface","vi":"lau bề mặt"},{"en":"wipe away tears","vi":"lau nước mắt"},{"en":"give something a wipe","vi":"lau qua một cái"},{"en":"wet wipes","vi":"khăn ướt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ ''wipe'' nhấn mạnh hành động lau sạch; ''wipe out'' có thể mang nghĩa xóa sổ hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_range', 'en-b1-53', 'range', '/reɪndʒ/', 'B1', 'phạm vi; chuỗi; đa dạng; biến đổi; dao động trong khoảng; dãy núi', 'n.', 'ranging (adj.), wide-ranging (adj.)', NULL, 'Cấu trúc range from A to B dùng để chỉ phạm vi biến động; danh từ chỉ dãy núi dùng mountain range.', 'This shop sells a wide range of fresh fruit.', NULL, 'Cửa hàng này bán rất nhiều loại trái cây tươi.', '{"wordId":"range","ukIpa":"/reɪndʒ/","usIpa":"/reɪndʒ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The extent or variety of things within certain limits.","vi":"phạm vi; chuỗi; đa dạng"},{"pos":"v.","en":"To vary between particular limits.","vi":"biến đổi; dao động trong khoảng"},{"pos":"n.","en":"A connected group of mountains.","vi":"dãy núi"}],"examples":[{"en":"This shop sells a wide range of fresh fruit.","vi":"Cửa hàng này bán rất nhiều loại trái cây tươi.","audioKind":"ex"},{"en":"Universities should offer a broader range of courses to meet the changing needs of employers.","vi":"Các trường đại học nên cung cấp nhiều khóa học đa dạng hơn để đáp ứng nhu cầu thay đổi của nhà tuyển dụng.","audioKind":"ex2"}],"collocations":[{"en":"a wide range of","vi":"nhiều loại; đa dạng"},{"en":"range from A to B","vi":"dao động từ A đến B"},{"en":"a mountain range","vi":"một dãy núi"}],"wordFamily":["ranging (adj.)","wide-ranging (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc range from A to B dùng để chỉ phạm vi biến động; danh từ chỉ dãy núi dùng mountain range.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flavour', 'en-b1-53', 'flavour', '/ˈfleɪvər/', 'B1', 'hương vị; mùi vị; nêm gia vị; tạo hương vị; nét đặc trưng; phong cách', 'n.', 'flavoured (adj.), flavouring (n.), flavourful (adj.)', 'Đồng nghĩa: taste', 'Cách viết Anh-Anh là flavour, cách viết Anh-Mỹ là flavor.', 'Fresh basil gives this soup a lovely flavour.', NULL, 'Rau húng quế tươi mang lại cho món súp này một hương vị tuyệt vời.', '{"wordId":"flavour","ukIpa":"/ˈfleɪvə/","usIpa":"/ˈfleɪvər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"the particular taste of food or drink","vi":"hương vị; mùi vị"},{"pos":"v.","en":"to give food or drink a particular taste","vi":"nêm gia vị; tạo hương vị"},{"pos":"n.","en":"a distinctive quality that gives something its character","vi":"nét đặc trưng; phong cách"}],"examples":[{"en":"Fresh basil gives this soup a lovely flavour.","vi":"Rau húng quế tươi mang lại cho món súp này một hương vị tuyệt vời.","audioKind":"ex"},{"en":"School cooking lessons can teach children how to improve flavour without adding excessive salt or sugar.","vi":"Các lớp học nấu ăn ở trường có thể dạy trẻ em cách cải thiện hương vị mà không cần cho quá nhiều muối hoặc đường.","audioKind":"ex2"}],"collocations":[{"en":"rich flavour","vi":"hương vị đậm đà"},{"en":"add flavour","vi":"thêm hương vị"},{"en":"flavour with herbs","vi":"nêm gia vị bằng thảo mộc"}],"wordFamily":["flavoured (adj.)","flavouring (n.)","flavourful (adj.)"],"synonyms":["taste"],"antonyms":[],"tipVi":"Cách viết Anh-Anh là flavour, cách viết Anh-Mỹ là flavor.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_self-service', 'en-b1-53', 'self-service', '/ˌselfˈsɝːvɪs/', 'B1', 'tự phục vụ; hệ thống tự phục vụ', 'adj.', 'service (n.), serve (v.)', NULL, 'self-service nhấn mạnh việc khách hàng tự thao tác, không có nghĩa là máy móc tự động hoàn toàn.', 'We carried our trays through the self-service cafeteria.', NULL, 'Chúng tôi bưng khay đựng đồ ăn đi qua khu vực nhà ăn tự phục vụ.', '{"wordId":"self-service","ukIpa":"/ˌselfˈsɜːvɪs/","usIpa":"/ˌselfˈsɝːvɪs/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Requiring customers to serve themselves rather than wait for staff","vi":"tự phục vụ"},{"pos":"n.","en":"A system in which customers serve themselves","vi":"hệ thống tự phục vụ"}],"examples":[{"en":"We carried our trays through the self-service cafeteria.","vi":"Chúng tôi bưng khay đựng đồ ăn đi qua khu vực nhà ăn tự phục vụ.","audioKind":"ex"},{"en":"Although self-service machines can shorten queues, businesses should retain staff to assist customers who need additional support.","vi":"Mặc dù các máy tự phục vụ có thể rút ngắn thời gian xếp hàng, các doanh nghiệp vẫn nên duy trì nhân viên để hỗ trợ những khách hàng cần sự giúp đỡ thêm.","audioKind":"ex2"}],"collocations":[{"en":"self-service checkout","vi":"quầy thanh toán tự phục vụ"},{"en":"self-service cafeteria","vi":"căng tin tự phục vụ"},{"en":"self-service machine","vi":"máy tự phục vụ"}],"wordFamily":["service (n.)","serve (v.)"],"synonyms":[],"antonyms":[],"tipVi":"self-service nhấn mạnh việc khách hàng tự thao tác, không có nghĩa là máy móc tự động hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yell', 'en-b1-53', 'yell', '/jel/', 'B1', 'la lớn; hét lớn; tiếng hét; tiếng la', 'v.', NULL, 'Đồng nghĩa: shout · Trái nghĩa: whisper', 'yell at thường mang thái độ giận dữ; yell to nhấn mạnh việc hét để người kia nghe thấy.', 'We yelled with excitement when our team finally scored.', NULL, 'Chúng tôi hò reo phấn khích khi đội của mình cuối cùng cũng ghi bàn.', '{"wordId":"yell","ukIpa":"/jel/","usIpa":"/jel/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to shout loudly, often from excitement, anger, or fear","vi":"la lớn; hét lớn"},{"pos":"n.","en":"a loud shout","vi":"tiếng hét; tiếng la"}],"examples":[{"en":"We yelled with excitement when our team finally scored.","vi":"Chúng tôi hò reo phấn khích khi đội của mình cuối cùng cũng ghi bàn.","audioKind":"ex"},{"en":"Coaches who yell at young athletes may undermine their confidence rather than improve their performance.","vi":"Các huấn luyện viên la mắng các vận động viên trẻ có thể làm giảm sút sự tự tin của họ thay vì cải thiện thành tích.","audioKind":"ex2"}],"collocations":[{"en":"yell at someone","vi":"la mắng ai đó"},{"en":"yell for help","vi":"gào thét cầu cứu"},{"en":"let out a yell","vi":"thốt lên một tiếng hét"}],"wordFamily":[],"synonyms":["shout"],"antonyms":["whisper"],"tipVi":"yell at thường mang thái độ giận dữ; yell to nhấn mạnh việc hét để người kia nghe thấy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sponge', 'en-b1-53', 'sponge', '/spʌndʒ/', 'B1', 'miếng bọt biển; mút; con bọt biển; lau chùi bằng bọt biển', 'n.', 'spongy (adj.)', NULL, 'Khi ví von khả năng hấp thụ cực tốt, thường dùng cấu trúc like a sponge.', 'Use a damp sponge to wipe the kitchen table.', NULL, 'Dùng miếng bọt biển ẩm để lau bàn bếp.', '{"wordId":"sponge","ukIpa":"/spʌndʒ/","usIpa":"/spʌndʒ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A soft material full of holes that absorbs liquid.","vi":"miếng bọt biển; mút"},{"pos":"n.","en":"A simple aquatic animal with many pores in its body.","vi":"con bọt biển"},{"pos":"v.","en":"To clean or wipe something using a damp sponge.","vi":"lau chùi bằng bọt biển"}],"examples":[{"en":"Use a damp sponge to wipe the kitchen table.","vi":"Dùng miếng bọt biển ẩm để lau bàn bếp.","audioKind":"ex"},{"en":"Urban wetlands act like a sponge, absorbing excess rainwater and reducing the risk of flooding.","vi":"Các vùng đất ngập nước đô thị hoạt động như một chiếc bọt biển, hấp thụ lượng nước mưa dư thừa và giảm nguy cơ ngập lụt.","audioKind":"ex2"}],"collocations":[{"en":"a damp sponge","vi":"một miếng bọt biển ẩm"},{"en":"squeeze out a sponge","vi":"vắt kiệt bọt biển"},{"en":"sponge something down","vi":"lau sạch vật gì bằng bọt biển"}],"wordFamily":["spongy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi ví von khả năng hấp thụ cực tốt, thường dùng cấu trúc like a sponge.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_living', 'en-b1-53', 'living', '/ˈlɪvɪŋ/', 'B1', 'đang sống; còn sống; sinh kế; kế sinh nhai; cách sống; lối sống', 'adj.', 'live (v.), alive (adj.), life (n.)', 'Đồng nghĩa: alive · Trái nghĩa: dead', 'living có thể đứng trước danh từ để bổ nghĩa; alive thường đóng vai trò vị ngữ hoặc bổ ngữ đứng sau.', 'The pond is full of tiny living creatures.', NULL, 'Ao nước có rất nhiều sinh vật sống nhỏ bé.', '{"wordId":"living","ukIpa":"/ˈlɪvɪŋ/","usIpa":"/ˈlɪvɪŋ/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Alive now, rather than dead or without life.","vi":"đang sống; còn sống"},{"pos":"n.","en":"Money earned to pay for everyday needs.","vi":"sinh kế; kế sinh nhai"},{"pos":"n.","en":"The way people live and meet their everyday needs.","vi":"cách sống; lối sống"}],"examples":[{"en":"The pond is full of tiny living creatures.","vi":"Ao nước có rất nhiều sinh vật sống nhỏ bé.","audioKind":"ex"},{"en":"Rising housing costs make it harder for young adults to earn a decent living in major cities.","vi":"Chi phí nhà ở tăng cao khiến những người trẻ tuổi ngày càng khó kiếm đủ tiền trang trải cuộc sống tại các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"living organisms","vi":"sinh vật sống"},{"en":"earn a living","vi":"kiếm sống"},{"en":"cost of living","vi":"chi phí sinh hoạt"},{"en":"standard of living","vi":"mức sống"}],"wordFamily":["live (v.)","alive (adj.)","life (n.)"],"synonyms":["alive"],"antonyms":["dead"],"tipVi":"living có thể đứng trước danh từ để bổ nghĩa; alive thường đóng vai trò vị ngữ hoặc bổ ngữ đứng sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carton', 'en-b1-53', 'carton', '/ˈkɑːrtən/', 'B1', 'hộp giấy; thùng các-tông', 'n.', NULL, 'Đồng nghĩa: box', '"a carton of milk" là một hộp sữa; đừng nhầm lẫn với "cartoon" (phim hoạt hình).', 'Please put the milk carton back in the fridge.', NULL, 'Làm ơn đặt hộp sữa lại vào tủ lạnh.', '{"wordId":"carton","ukIpa":"/ˈkɑːtən/","usIpa":"/ˈkɑːrtən/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A container made of cardboard, often used for food or drinks.","vi":"hộp giấy; thùng các-tông"}],"examples":[{"en":"Please put the milk carton back in the fridge.","vi":"Làm ơn đặt hộp sữa lại vào tủ lạnh.","audioKind":"ex"},{"en":"Local recycling schemes should explain how residents can dispose of each type of food carton correctly.","vi":"Các chương trình tái chế địa phương nên hướng dẫn người dân cách xử lý đúng cách từng loại hộp đựng thực phẩm bằng giấy.","audioKind":"ex2"}],"collocations":[{"en":"a carton of milk","vi":"một hộp sữa"},{"en":"egg carton","vi":"hộp đựng trứng"},{"en":"cardboard carton","vi":"thùng các-tông"}],"wordFamily":[],"synonyms":["box"],"antonyms":[],"tipVi":"\"a carton of milk\" là một hộp sữa; đừng nhầm lẫn với \"cartoon\" (phim hoạt hình).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nod', 'en-b1-53', 'nod', '/nɑːd/', 'B1', 'gật đầu; cái gật đầu', 'v.', NULL, NULL, 'Các dạng thức quá khứ là "nodded" và phân từ hiện tại là "nodding", đều phải gấp đôi chữ "d".', 'She nodded when I offered her another cup of tea.', NULL, 'Cô ấy gật đầu khi tôi mời cô ấy thêm một tách trà.', '{"wordId":"nod","ukIpa":"/nɒd/","usIpa":"/nɑːd/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to move your head down and up to communicate","vi":"gật đầu"},{"pos":"n.","en":"a downward and upward head movement expressing a message","vi":"cái gật đầu"}],"examples":[{"en":"She nodded when I offered her another cup of tea.","vi":"Cô ấy gật đầu khi tôi mời cô ấy thêm một tách trà.","audioKind":"ex"},{"en":"During group discussions, participants may nod to show understanding without necessarily agreeing with the speaker''s views.","vi":"Trong các buổi thảo luận nhóm, những người tham gia có thể gật đầu để thể hiện sự thấu hiểu mà không nhất thiết phải đồng tình với quan điểm của người nói.","audioKind":"ex2"}],"collocations":[{"en":"nod in agreement","vi":"gật đầu đồng ý"},{"en":"give a nod","vi":"đưa ra cái gật đầu"},{"en":"nod at someone","vi":"gật đầu chào ai đó"},{"en":"nod off","vi":"ngủ gật"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Các dạng thức quá khứ là \"nodded\" và phân từ hiện tại là \"nodding\", đều phải gấp đôi chữ \"d\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whistle', 'en-b1-53', 'whistle', '/ˈwɪsəl/', 'B1', 'huýt sáo; rít lên; thổi còi; cái còi; tiếng huýt sáo; tiếng còi; tiếng rít', 'v.', 'whistler (n.)', NULL, 'Âm "t" trong từ "whistle" là âm câm không phát âm; hành động thổi còi dùng cấu trúc "blow a whistle".', 'My brother whistles cheerful tunes while washing the dishes.', NULL, 'Anh trai tôi vừa rửa bát vừa huýt sáo những giai điệu vui tươi.', '{"wordId":"whistle","ukIpa":"/ˈwɪsəl/","usIpa":"/ˈwɪsəl/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to make a high sound with lips or escaping air","vi":"huýt sáo; rít lên; thổi còi"},{"pos":"n.","en":"a small device blown to produce a high, clear sound","vi":"cái còi"},{"pos":"n.","en":"a high, clear sound made by lips, air, or a device","vi":"tiếng huýt sáo; tiếng còi; tiếng rít"}],"examples":[{"en":"My brother whistles cheerful tunes while washing the dishes.","vi":"Anh trai tôi vừa rửa bát vừa huýt sáo những giai điệu vui tươi.","audioKind":"ex"},{"en":"Lifeguards use whistles to attract swimmers'' attention quickly when dangerous conditions develop near the shore.","vi":"Các nhân viên cứu hộ dùng còi để nhanh chóng thu hút sự chú ý của người bơi lội khi có tình huống nguy hiểm phát sinh gần bờ.","audioKind":"ex2"}],"collocations":[{"en":"blow a whistle","vi":"thổi còi"},{"en":"whistle a tune","vi":"huýt sáo một giai điệu"},{"en":"final whistle","vi":"tiếng còi kết thúc trận đấu"},{"en":"whistle for help","vi":"thổi còi cầu cứu"}],"wordFamily":["whistler (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Âm \"t\" trong từ \"whistle\" là âm câm không phát âm; hành động thổi còi dùng cấu trúc \"blow a whistle\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tear', 'en-b1-53', 'tear', '/ter/, /tɪr/', 'B1', 'xé rách; làm rách; giọt nước mắt; vết rách; lỗ thủng', 'v.', 'tearful (adj.), tearfully (adv.)', 'Đồng nghĩa: rip', 'Động từ xé rách phát âm là /teə/, danh từ nước mắt phát âm là /tɪə/; dạng chia của động từ là tore và torn.', 'Be careful not to tear the paper bag.', NULL, 'Cẩn thận kẻo làm rách túi giấy đấy.', '{"wordId":"tear","ukIpa":"/teə/, /tɪə/","usIpa":"/ter/, /tɪr/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To pull something apart or make a hole by pulling.","vi":"xé rách; làm rách"},{"pos":"n.","en":"A drop of liquid that comes from your eye.","vi":"giọt nước mắt"},{"pos":"n.","en":"A hole or split caused by pulling something apart.","vi":"vết rách; lỗ thủng"}],"examples":[{"en":"Be careful not to tear the paper bag.","vi":"Cẩn thận kẻo làm rách túi giấy đấy.","audioKind":"ex"},{"en":"Thin plastic bags tear easily, making them less suitable for repeated use than durable cloth alternatives.","vi":"Các túi nhựa mỏng rất dễ bị rách, khiến chúng ít phù hợp cho việc sử dụng nhiều lần hơn so với các lựa chọn bằng vải bền.","audioKind":"ex2"}],"collocations":[{"en":"tear up paper","vi":"xé rách giấy"},{"en":"burst into tears","vi":"òa khóc"},{"en":"tear apart","vi":"xé tan; xé toạc"}],"wordFamily":["tearful (adj.)","tearfully (adv.)"],"synonyms":["rip"],"antonyms":[],"tipVi":"Động từ xé rách phát âm là /teə/, danh từ nước mắt phát âm là /tɪə/; dạng chia của động từ là tore và torn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_package', 'en-b1-53', 'package', '/ˈpækɪdʒ/', 'B1', 'bưu kiện; gói đồ; gói dịch vụ; gói giải pháp; đóng gói', 'n.', 'pack (v.), packaging (n.), unpack (v.)', 'Đồng nghĩa: parcel', 'Khi nói về bưu kiện gửi qua bưu điện, tiếng Anh-Anh thường dùng từ parcel.', 'A small package arrived at our door this morning.', NULL, 'Một bưu kiện nhỏ đã được chuyển đến trước cửa nhà chúng tôi vào sáng nay.', '{"wordId":"package","ukIpa":"/ˈpækɪdʒ/","usIpa":"/ˈpækɪdʒ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"An object or collection of objects wrapped or boxed together.","vi":"bưu kiện; gói đồ"},{"pos":"n.","en":"A set of services or measures offered together.","vi":"gói dịch vụ; gói giải pháp"},{"pos":"v.","en":"To put something into a container for sale or transport.","vi":"đóng gói"}],"examples":[{"en":"A small package arrived at our door this morning.","vi":"Một bưu kiện nhỏ đã được chuyển đến trước cửa nhà chúng tôi vào sáng nay.","audioKind":"ex"},{"en":"The government introduced a support package to help small businesses invest in cleaner production methods.","vi":"Chính phủ đã đưa ra một gói hỗ trợ nhằm giúp các doanh nghiệp nhỏ đầu tư vào các phương pháp sản xuất sạch hơn.","audioKind":"ex2"}],"collocations":[{"en":"deliver a package","vi":"giao bưu kiện"},{"en":"a support package","vi":"gói hỗ trợ"},{"en":"package holiday","vi":"tour du lịch trọn gói"}],"wordFamily":["pack (v.)","packaging (n.)","unpack (v.)"],"synonyms":["parcel"],"antonyms":[],"tipVi":"Khi nói về bưu kiện gửi qua bưu điện, tiếng Anh-Anh thường dùng từ parcel.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brunch', 'en-b1-53', 'brunch', '/brʌntʃ/', 'B1', 'bữa điểm tâm muộn; bữa sáng kết hợp bữa trưa', 'n.', NULL, NULL, 'Được tạo thành từ breakfast và lunch, dùng để chỉ bữa ăn kết hợp cả hai.', 'We enjoyed brunch on the balcony this morning.', NULL, 'Chúng tôi đã thưởng thức bữa sáng muộn ngoài ban công vào sáng nay.', '{"wordId":"brunch","ukIpa":"/brʌntʃ/","usIpa":"/brʌntʃ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A late morning meal combining breakfast and lunch.","vi":"bữa điểm tâm muộn; bữa sáng kết hợp bữa trưa"}],"examples":[{"en":"We enjoyed brunch on the balcony this morning.","vi":"Chúng tôi đã thưởng thức bữa sáng muộn ngoài ban công vào sáng nay.","audioKind":"ex"},{"en":"Serving brunch allows local cafés to attract customers outside the traditional breakfast and lunch periods.","vi":"Phục vụ bữa sáng muộn giúp các quán cà phê địa phương thu hút khách hàng ngoài khung giờ ăn sáng và ăn trưa truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"have brunch","vi":"dùng bữa sáng muộn"},{"en":"weekend brunch","vi":"bữa sáng muộn cuối tuần"},{"en":"brunch menu","vi":"thực đơn bữa sáng muộn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Được tạo thành từ breakfast và lunch, dùng để chỉ bữa ăn kết hợp cả hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eventually', 'en-b1-53', 'eventually', '/ɪˈventʃuəli/', 'B1', 'cuối cùng; rốt cuộc', 'adv.', 'eventual (adj.), eventuality (n.)', 'Đồng nghĩa: finally, ultimately', 'Nhấn mạnh kết quả đạt được sau một khoảng thời gian hoặc nhiều khó khăn, không dùng để chỉ khả năng xảy ra.', 'After searching every room, we eventually found the missing keys.', NULL, 'Sau khi lục tìm qua mọi căn phòng, cuối cùng chúng tôi cũng tìm thấy chùm chìa khóa bị mất.', '{"wordId":"eventually","ukIpa":"/ɪˈventʃuəli/","usIpa":"/ɪˈventʃuəli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"in the end, especially after a long time or difficulty","vi":"cuối cùng; rốt cuộc"}],"examples":[{"en":"After searching every room, we eventually found the missing keys.","vi":"Sau khi lục tìm qua mọi căn phòng, cuối cùng chúng tôi cũng tìm thấy chùm chìa khóa bị mất.","audioKind":"ex"},{"en":"Investment in public transport may initially be expensive, but it can eventually reduce congestion and improve urban life.","vi":"Đầu tư vào giao thông công cộng thoạt đầu có thể tốn kém, nhưng về lâu dài có thể giảm thiểu ùn tắc và cải thiện cuộc sống đô thị.","audioKind":"ex2"}],"collocations":[{"en":"eventually succeed","vi":"cuối cùng thành công"},{"en":"eventually lead to","vi":"cuối cùng dẫn đến"},{"en":"eventually become","vi":"cuối cùng trở thành"}],"wordFamily":["eventual (adj.)","eventuality (n.)"],"synonyms":["finally","ultimately"],"antonyms":[],"tipVi":"Nhấn mạnh kết quả đạt được sau một khoảng thời gian hoặc nhiều khó khăn, không dùng để chỉ khả năng xảy ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fault', 'en-b1-53', 'fault', '/fɔːlt/', 'B1', 'lỗi; khiếm khuyết; sự cố; trách nhiệm; lỗi lầm; đứt gãy; khe nứt', 'n.', 'faulty (adj.), faultless (adj.)', 'Đồng nghĩa: defect, flaw', 'Cấu trúc It''s my fault nghĩa là "là lỗi của tôi", không dùng mistake để thay thế.', 'A small electrical fault stopped the washing machine yesterday.', NULL, 'Hôm qua một sự cố điện nhỏ đã làm chiếc máy giặt ngừng hoạt động.', '{"wordId":"fault","ukIpa":"/fɔːlt/","usIpa":"/fɔːlt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Something wrong with an object, system, or person''s character","vi":"lỗi; khiếm khuyết; sự cố"},{"pos":"n.","en":"Responsibility for a mistake or something bad that happened","vi":"trách nhiệm; lỗi lầm"},{"pos":"n.","en":"A break in rock where sections have moved apart","vi":"đứt gãy; khe nứt"}],"examples":[{"en":"A small electrical fault stopped the washing machine yesterday.","vi":"Hôm qua một sự cố điện nhỏ đã làm chiếc máy giặt ngừng hoạt động.","audioKind":"ex"},{"en":"Regular inspections can identify a structural fault before it threatens the safety of residents.","vi":"Các cuộc kiểm tra định kỳ có thể phát hiện lỗi cấu trúc trước khi nó đe dọa sự an toàn của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"electrical fault","vi":"sự cố điện"},{"en":"at fault","vi":"có lỗi; chịu trách nhiệm"},{"en":"find fault with","vi":"bới móc; soi mói"},{"en":"fault line","vi":"đường đứt gãy"}],"wordFamily":["faulty (adj.)","faultless (adj.)"],"synonyms":["defect","flaw"],"antonyms":[],"tipVi":"Cấu trúc It''s my fault nghĩa là \"là lỗi của tôi\", không dùng mistake để thay thế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_parcel', 'en-b1-53', 'parcel', '/ˈpɑːrsəl/', 'B1', 'bưu kiện; gói hàng; lô đất; thửa đất; gói; phân chia', 'n.', NULL, 'Đồng nghĩa: package', 'Từ "bưu kiện" trong tiếng Anh-Anh thường dùng parcel, trong khi tiếng Anh-Mỹ dùng package.', 'A small parcel arrived for you this morning.', NULL, 'Sáng nay có một bưu kiện nhỏ gửi đến cho bạn.', '{"wordId":"parcel","ukIpa":"/ˈpɑːsəl/","usIpa":"/ˈpɑːrsəl/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"an object wrapped for sending by post or delivery","vi":"bưu kiện; gói hàng"},{"pos":"n.","en":"a piece of land considered as a single unit","vi":"lô đất; thửa đất"},{"pos":"v.","en":"to wrap something, or divide it into portions for distribution","vi":"gói; phân chia"}],"examples":[{"en":"A small parcel arrived for you this morning.","vi":"Sáng nay có một bưu kiện nhỏ gửi đến cho bạn.","audioKind":"ex"},{"en":"The growing volume of parcel deliveries has encouraged cities to explore cleaner transport options for local distribution.","vi":"Khối lượng giao hàng bưu kiện ngày càng tăng đã khuyến khích các thành phố khám phá các phương thức vận chuyển sạch hơn cho việc phân phối nội địa.","audioKind":"ex2"}],"collocations":[{"en":"send a parcel","vi":"gửi bưu kiện"},{"en":"a parcel of land","vi":"một thửa đất"},{"en":"parcel something up","vi":"gói ghém vật gì lại"},{"en":"parcel something out","vi":"phân chia cái gì"}],"wordFamily":[],"synonyms":["package"],"antonyms":[],"tipVi":"Từ \"bưu kiện\" trong tiếng Anh-Anh thường dùng parcel, trong khi tiếng Anh-Mỹ dùng package.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_totally', 'en-b1-53', 'totally', '/ˈtoʊtəli/', 'B1', 'hoàn toàn; tuyệt đối', 'adv.', 'total (adj.), total (n.), total (v.)', 'Đồng nghĩa: completely, entirely, wholly · Trái nghĩa: partly', 'Từ này có sắc thái biểu cảm mạnh; trong văn viết trang trọng, thường có thể thay thế bằng completely hoặc entirely.', 'I totally forgot to bring my swimming costume.', NULL, 'Tôi hoàn toàn quên mang theo đồ bơi của mình.', '{"wordId":"totally","ukIpa":"/ˈtəʊtəli/","usIpa":"/ˈtoʊtəli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"completely; in every way or to the fullest degree","vi":"hoàn toàn; tuyệt đối"}],"examples":[{"en":"I totally forgot to bring my swimming costume.","vi":"Tôi hoàn toàn quên mang theo đồ bơi của mình.","audioKind":"ex"},{"en":"Online courses cannot totally replace classroom teaching because students also benefit from direct social interaction.","vi":"Các khóa học trực tuyến không thể hoàn toàn thay thế việc giảng dạy trên lớp vì học sinh cũng hưởng lợi từ sự tương tác xã hội trực tiếp.","audioKind":"ex2"}],"collocations":[{"en":"totally different","vi":"hoàn toàn khác biệt"},{"en":"totally agree","vi":"hoàn toàn đồng ý"},{"en":"totally unacceptable","vi":"hoàn toàn không thể chấp nhận được"}],"wordFamily":["total (adj.)","total (n.)","total (v.)"],"synonyms":["completely","entirely","wholly"],"antonyms":["partly"],"tipVi":"Từ này có sắc thái biểu cảm mạnh; trong văn viết trang trọng, thường có thể thay thế bằng completely hoặc entirely.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_airmail', 'en-b1-53', 'airmail', '/ˈermeɪl/', 'B1', 'thư tín và bưu kiện vận chuyển bằng đường hàng không; dịch vụ bưu chính hàng không', 'n.', NULL, NULL, 'Chỉ phương thức gửi dùng by airmail, không thêm mạo từ.', 'We sent the parcel by airmail yesterday morning.', NULL, 'Chúng tôi đã gửi bưu kiện qua đường hàng không vào sáng hôm qua.', '{"wordId":"airmail","ukIpa":"/ˈeəmeɪl/","usIpa":"/ˈermeɪl/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"letters and parcels transported by aircraft, or this postal service","vi":"thư tín và bưu kiện vận chuyển bằng đường hàng không; dịch vụ bưu chính hàng không"}],"examples":[{"en":"We sent the parcel by airmail yesterday morning.","vi":"Chúng tôi đã gửi bưu kiện qua đường hàng không vào sáng hôm qua.","audioKind":"ex"},{"en":"Although digital communication dominates international business, airmail remains useful for sending original documents overseas.","vi":"Mặc dù giao tiếp kỹ thuật số chiếm ưu thế trong thương mại quốc tế, dịch vụ bưu chính hàng không vẫn hữu ích khi gửi các tài liệu gốc ra nước ngoài.","audioKind":"ex2"}],"collocations":[{"en":"by airmail","vi":"bằng đường hàng không"},{"en":"send something by airmail","vi":"gửi vật gì bằng đường hàng không"},{"en":"airmail service","vi":"dịch vụ bưu chính hàng không"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ phương thức gửi dùng by airmail, không thêm mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shortly', 'en-b1-53', 'shortly', '/ˈʃɔːrtli/', 'B1', 'chẳng bao lâu nữa; không lâu sau; một cách ngắn gọn, cộc lốc hoặc thiếu kiên nhẫn', 'adv.', 'short (adj.), shorten (v.), shortness (n.)', 'Đồng nghĩa: soon', 'Diễn đạt ý nghĩa "một cách tóm tắt" thường dùng briefly, không dùng shortly.', 'The bus will arrive shortly, so get your bag ready.', NULL, 'Xe buýt sẽ đến ngay thôi, hãy chuẩn bị sẵn túi xách của bạn nhé.', '{"wordId":"shortly","ukIpa":"/ˈʃɔːtli/","usIpa":"/ˈʃɔːrtli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"After a short amount of time.","vi":"chẳng bao lâu nữa; không lâu sau"},{"pos":"adv.","en":"In a brief, unfriendly or impatient way.","vi":"một cách ngắn gọn, cộc lốc hoặc thiếu kiên nhẫn"}],"examples":[{"en":"The bus will arrive shortly, so get your bag ready.","vi":"Xe buýt sẽ đến ngay thôi, hãy chuẩn bị sẵn túi xách của bạn nhé.","audioKind":"ex"},{"en":"Shortly after the new railway opened, local businesses reported a significant increase in customer visits.","vi":"Không lâu sau khi tuyến đường sắt mới đi vào hoạt động, các doanh nghiệp địa phương ghi nhận lượng khách hàng ghé thăm tăng đáng kể.","audioKind":"ex2"}],"collocations":[{"en":"arrive shortly","vi":"đến nơi ngay"},{"en":"shortly after","vi":"chẳng bao lâu sau"},{"en":"shortly before","vi":"không lâu trước"}],"wordFamily":["short (adj.)","shorten (v.)","shortness (n.)"],"synonyms":["soon"],"antonyms":[],"tipVi":"Diễn đạt ý nghĩa \"một cách tóm tắt\" thường dùng briefly, không dùng shortly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_secondhand', 'en-b1-53', 'secondhand', '/ˌsekəndˈhænd/', 'B1', 'đã qua sử dụng; hàng cũ; đồ si; tiếp thu từ người khác thay vì trải nghiệm trực tiếp; một cách gián tiếp; từ chủ sở hữu trước', 'adj.', NULL, 'Đồng nghĩa: used, pre-owned · Trái nghĩa: new', 'Cũng thường được viết là second-hand; nét nghĩa thông tin dùng để chỉ thông tin không do bản thân trực tiếp trải nghiệm.', 'I bought a secondhand bicycle from my neighbour.', NULL, 'Tôi đã mua một chiếc xe đạp cũ từ người hàng xóm của mình.', '{"wordId":"secondhand","ukIpa":"/ˌsekəndˈhænd/","usIpa":"/ˌsekəndˈhænd/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Previously owned or used by someone else.","vi":"đã qua sử dụng; hàng cũ; đồ si"},{"pos":"adj.","en":"Learned from others rather than experienced directly.","vi":"tiếp thu từ người khác thay vì trải nghiệm trực tiếp"},{"pos":"adv.","en":"From a previous owner or through another person.","vi":"một cách gián tiếp; từ chủ sở hữu trước"}],"examples":[{"en":"I bought a secondhand bicycle from my neighbour.","vi":"Tôi đã mua một chiếc xe đạp cũ từ người hàng xóm của mình.","audioKind":"ex"},{"en":"Buying secondhand furniture can reduce household spending and limit the environmental impact of producing new goods.","vi":"Việc mua nội thất đã qua sử dụng có thể làm giảm chi phí sinh hoạt của gia đình và hạn chế tác động môi trường từ việc sản xuất hàng hóa mới.","audioKind":"ex2"}],"collocations":[{"en":"secondhand furniture","vi":"đồ nội thất cũ"},{"en":"secondhand information","vi":"thông tin truyền miệng; thông tin gián tiếp"},{"en":"buy secondhand","vi":"mua đồ cũ"},{"en":"secondhand smoke","vi":"khói thuốc thụ động"}],"wordFamily":[],"synonyms":["used","pre-owned"],"antonyms":["new"],"tipVi":"Cũng thường được viết là second-hand; nét nghĩa thông tin dùng để chỉ thông tin không do bản thân trực tiếp trải nghiệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_registration', 'en-b1-53', 'registration', '/ˌredʒɪˈstreɪʃən/', 'B1', 'sự đăng ký; việc ghi danh; giấy đăng ký; chứng nhận đăng ký', 'n.', 'register (v.), registered (adj.)', 'Đồng nghĩa: enrolment', 'Khi nói đến việc đăng ký hoặc ghi danh cho một hoạt động nào đó, thường dùng registration for.', 'Registration for the swimming course opens on Monday.', NULL, 'Việc đăng ký tham gia khóa học bơi bắt đầu vào thứ Hai.', '{"wordId":"registration","ukIpa":"/ˌredʒɪˈstreɪʃən/","usIpa":"/ˌredʒɪˈstreɪʃən/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The process of officially recording details or joining something.","vi":"sự đăng ký; việc ghi danh"},{"pos":"n.","en":"An official document showing that something has been registered.","vi":"giấy đăng ký; chứng nhận đăng ký"}],"examples":[{"en":"Registration for the swimming course opens on Monday.","vi":"Việc đăng ký tham gia khóa học bơi bắt đầu vào thứ Hai.","audioKind":"ex"},{"en":"Online registration can improve access to public services, provided that support remains available for people without internet access.","vi":"Đăng ký trực tuyến có thể giúp người dân dễ dàng tiếp cận các dịch vụ công hơn, với điều kiện vẫn hỗ trợ những người không có Internet.","audioKind":"ex2"}],"collocations":[{"en":"online registration","vi":"đăng ký trực tuyến"},{"en":"registration fee","vi":"phí đăng ký"},{"en":"vehicle registration","vi":"đăng ký xe"},{"en":"registration form","vi":"mẫu đăng ký"}],"wordFamily":["register (v.)","registered (adj.)"],"synonyms":["enrolment"],"antonyms":[],"tipVi":"Khi nói đến việc đăng ký hoặc ghi danh cho một hoạt động nào đó, thường dùng registration for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_53_1', 'en-b1-53', 'Cách dùng “secondhand” (adj.) — đã qua sử dụng; hàng cũ; đồ si', 'secondhand furniture  ·  secondhand information  ·  buy secondhand', 'Cũng thường được viết là second-hand; nét nghĩa thông tin dùng để chỉ thông tin không do bản thân trực tiếp trải nghiệm.', 'Đồng nghĩa: used, pre-owned · Trái nghĩa: new', '[{"hanzi":"I bought a secondhand bicycle from my neighbour.","pinyin":"","meaning":"Tôi đã mua một chiếc xe đạp cũ từ người hàng xóm của mình."},{"hanzi":"Buying secondhand furniture can reduce household spending and limit the environmental impact of producing new goods.","pinyin":"","meaning":"Việc mua nội thất đã qua sử dụng có thể làm giảm chi phí sinh hoạt của gia đình và hạn chế tác động môi trường từ việc sản xuất hàng hóa mới."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_53_2', 'en-b1-53', 'Cách dùng “totally” (adv.) — hoàn toàn; tuyệt đối', 'totally different  ·  totally agree  ·  totally unacceptable', 'Từ này có sắc thái biểu cảm mạnh; trong văn viết trang trọng, thường có thể thay thế bằng completely hoặc entirely.', 'Họ từ (Word Family): total (adj.), total (n.), total (v.) | Đồng nghĩa: completely, entirely, wholly · Trái nghĩa: partly', '[{"hanzi":"I totally forgot to bring my swimming costume.","pinyin":"","meaning":"Tôi hoàn toàn quên mang theo đồ bơi của mình."},{"hanzi":"Online courses cannot totally replace classroom teaching because students also benefit from direct social interaction.","pinyin":"","meaning":"Các khóa học trực tuyến không thể hoàn toàn thay thế việc giảng dạy trên lớp vì học sinh cũng hưởng lợi từ sự tương tác xã hội trực tiếp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_53_3', 'en-b1-53', 'Cách dùng “tear” (v.) — xé rách; làm rách', 'tear up paper  ·  burst into tears  ·  tear apart', 'Động từ xé rách phát âm là /teə/, danh từ nước mắt phát âm là /tɪə/; dạng chia của động từ là tore và torn.', 'Họ từ (Word Family): tearful (adj.), tearfully (adv.) | Đồng nghĩa: rip', '[{"hanzi":"Be careful not to tear the paper bag.","pinyin":"","meaning":"Cẩn thận kẻo làm rách túi giấy đấy."},{"hanzi":"Thin plastic bags tear easily, making them less suitable for repeated use than durable cloth alternatives.","pinyin":"","meaning":"Các túi nhựa mỏng rất dễ bị rách, khiến chúng ít phù hợp cho việc sử dụng nhiều lần hơn so với các lựa chọn bằng vải bền."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_53_4', 'en-b1-53', 'Cách dùng “eventually” (adv.) — cuối cùng; rốt cuộc', 'eventually succeed  ·  eventually lead to  ·  eventually become', 'Nhấn mạnh kết quả đạt được sau một khoảng thời gian hoặc nhiều khó khăn, không dùng để chỉ khả năng xảy ra.', 'Họ từ (Word Family): eventual (adj.), eventuality (n.) | Đồng nghĩa: finally, ultimately', '[{"hanzi":"After searching every room, we eventually found the missing keys.","pinyin":"","meaning":"Sau khi lục tìm qua mọi căn phòng, cuối cùng chúng tôi cũng tìm thấy chùm chìa khóa bị mất."},{"hanzi":"Investment in public transport may initially be expensive, but it can eventually reduce congestion and improve urban life.","pinyin":"","meaning":"Đầu tư vào giao thông công cộng thoạt đầu có thể tốn kém, nhưng về lâu dài có thể giảm thiểu ùn tắc và cải thiện cuộc sống đô thị."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_53_1', 'en-b1-53', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_1_1', 'ten_b1_53_1', 'contents', 'She emptied the contents of her bag onto the table.', 'She emptied the contents of her bag onto the table.', '/ˈkɑːntents/', 'Cô ấy đổ hết mọi thứ trong túi xách của mình lên bàn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_1_2', 'ten_b1_53_1', 'neat', 'She keeps her gardening tools in neat rows.', 'She keeps her gardening tools in neat rows.', '/niːt/', 'Cô ấy xếp các dụng cụ làm vườn thành những hàng ngay ngắn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_1_3', 'ten_b1_53_1', 'feature', 'My favourite feature of this backpack is its hidden pocket.', 'My favourite feature of this backpack is its hidden pocket.', '/ˈfiːtʃər/', 'Đặc điểm mà tôi thích nhất ở chiếc ba lô này là chiếc túi ẩn của nó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_1_4', 'ten_b1_53_1', 'specially', 'I made this cushion specially for your chair.', 'I made this cushion specially for your chair.', '/ˈspeʃəli/', 'Tôi đã làm chiếc đệm lót này dành riêng cho chiếc ghế của bạn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_1_5', 'ten_b1_53_1', 'firework', 'A single firework burst above the lake, scattering golden sparks.', 'A single firework burst above the lake, scattering golden sparks.', '/ˈfaɪərwɜːrk/', 'Một quả pháo hoa bùng nổ trên mặt hồ, tung ra những tia lửa vàng óng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_1_6', 'ten_b1_53_1', 'warn', 'Please warn me if the pan gets too hot.', 'Please warn me if the pan gets too hot.', '/wɔːrn/', 'Hãy nhắc tôi nếu cái chảo trở nên quá nóng nhé.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_1_7', 'ten_b1_53_1', 'wipe', 'Please wipe the table before you put the plates down.', 'Please wipe the table before you put the plates down.', '/waɪp/', 'Vui lòng lau bàn sạch sẽ trước khi đặt đĩa thức ăn lên nhé.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_1_8', 'ten_b1_53_1', 'range', 'This shop sells a wide range of fresh fruit.', 'This shop sells a wide range of fresh fruit.', '/reɪndʒ/', 'Cửa hàng này bán rất nhiều loại trái cây tươi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_53_1_1', 'en-b1-53', 'ten_b1_53_1', 'listening', 'listening', 'She emptied the contents of her bag onto the table.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy đổ hết mọi thứ trong túi xách của mình lên bàn.","Chúng tôi đã gửi bưu kiện qua đường hàng không vào sáng hôm qua.","Hãy nhắc tôi nếu cái chảo trở nên quá nóng nhé.","Xe buýt sẽ đến ngay thôi, hãy chuẩn bị sẵn túi xách của bạn nhé."]'::jsonb, 0, 'She emptied the contents of her bag onto the table. → Cô ấy đổ hết mọi thứ trong túi xách của mình lên bàn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_53_1_2', 'en-b1-53', 'ten_b1_53_1', 'listening', 'listening', 'She keeps her gardening tools in neat rows.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy xếp các dụng cụ làm vườn thành những hàng ngay ngắn.","Chúng tôi bưng khay đựng đồ ăn đi qua khu vực nhà ăn tự phục vụ.","Cửa hàng này bán rất nhiều loại trái cây tươi.","Cô ấy gật đầu khi tôi mời cô ấy thêm một tách trà."]'::jsonb, 0, 'She keeps her gardening tools in neat rows. → Cô ấy xếp các dụng cụ làm vườn thành những hàng ngay ngắn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_53_1_3', 'en-b1-53', 'ten_b1_53_1', 'listening', 'listening', 'My favourite feature of this backpack is its hidden pocket.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Rau húng quế tươi mang lại cho món súp này một hương vị tuyệt vời.","Cô ấy xếp các dụng cụ làm vườn thành những hàng ngay ngắn.","Một quả pháo hoa bùng nổ trên mặt hồ, tung ra những tia lửa vàng óng.","Đặc điểm mà tôi thích nhất ở chiếc ba lô này là chiếc túi ẩn của nó."]'::jsonb, 3, 'My favourite feature of this backpack is its hidden pocket. → Đặc điểm mà tôi thích nhất ở chiếc ba lô này là chiếc túi ẩn của nó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_53_2', 'en-b1-53', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_2_1', 'ten_b1_53_2', 'contents', 'A detailed table of contents helps readers locate relevant information quickly in lengthy academic reports.', 'A detailed table of contents helps readers locate relevant information quickly in lengthy academic reports.', '/ˈkɑːntents/', 'Bảng mục lục chi tiết giúp người đọc nhanh chóng tìm thấy thông tin liên quan trong các báo cáo học thuật dài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_2_2', 'ten_b1_53_2', 'neat', 'Keeping shared workspaces neat can improve efficiency by making essential equipment easier to locate.', 'Keeping shared workspaces neat can improve efficiency by making essential equipment easier to locate.', '/niːt/', 'Việc giữ cho không gian làm việc chung ngăn nắp có thể nâng cao hiệu quả bằng cách giúp việc tìm kiếm các thiết bị cần thiết trở nên dễ dàng hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_2_3', 'ten_b1_53_2', 'feature', 'Public parks are an essential feature of cities that prioritise residents'' health and wellbeing.', 'Public parks are an essential feature of cities that prioritise residents'' health and wellbeing.', '/ˈfiːtʃər/', 'Các công viên công cộng là một đặc điểm thiết yếu của những thành phố ưu tiên sức khỏe và hạnh phúc của cư dân.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_2_4', 'ten_b1_53_2', 'specially', 'Schools should provide specially designed learning materials to support students with different educational needs.', 'Schools should provide specially designed learning materials to support students with different educational needs.', '/ˈspeʃəli/', 'Nhà trường nên cung cấp tài liệu học tập được thiết kế riêng nhằm hỗ trợ học sinh có các nhu cầu giáo dục khác nhau.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_2_5', 'ten_b1_53_2', 'firework', 'Public firework displays can attract visitors, although their noise may disturb local residents and wildlife.', 'Public firework displays can attract visitors, although their noise may disturb local residents and wildlife.', '/ˈfaɪərwɜːrk/', 'Các màn trình diễn pháo hoa công cộng có thể thu hút khách du lịch, mặc dù tiếng ồn của chúng có thể làm phiền cư dân địa phương và động vật hoang dã.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_53_2_6', 'ten_b1_53_2', 'warn', 'Scientists warn that continued habitat loss could put many more species at risk of extinction.', 'Scientists warn that continued habitat loss could put many more species at risk of extinction.', '/wɔːrn/', 'Các nhà khoa học cảnh báo rằng tình trạng mất môi trường sống liên tục có thể đẩy nhiều loài hơn nữa vào nguy cơ tuyệt chủng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_53_2_1', 'en-b1-53', 'ten_b1_53_2', 'listening', 'listening', 'A detailed table of contents helps readers locate relevant information quickly in lengthy academic reports.', NULL, 'Trong câu vừa nghe, từ “contents” mang nghĩa nào sau đây?', '["tấm thảm chùi chân; thảm nhỏ trải sàn","sự thật; chân lý","thường xuyên; hay","đồ bên trong; nội dung bên trong"]'::jsonb, 3, '“contents” (/ˈkɑːntents/): đồ bên trong; nội dung bên trong. Câu đầy đủ: A detailed table of contents helps readers locate relevant information quickly in lengthy academic reports.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_53_2_2', 'en-b1-53', 'ten_b1_53_2', 'listening', 'listening', 'Keeping shared workspaces neat can improve efficiency by making essential equipment easier to locate.', NULL, 'Trong câu vừa nghe, từ “neat” mang nghĩa nào sau đây?', '["dân số; toàn bộ cư dân","sự đặt chỗ; việc đặt trước","ngăn nắp; gọn gàng","động từ nguyên thể; nguyên mẫu"]'::jsonb, 2, '“neat” (/niːt/): ngăn nắp; gọn gàng. Câu đầy đủ: Keeping shared workspaces neat can improve efficiency by making essential equipment easier to locate.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
