INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_53_1', 'en-b1-53', NULL, 'comprehensive_test', 'listening', 'contents', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chín; đã trưởng thành để ăn hoặc thu hoạch","hoãn lại; lùi lịch","mối quan hệ; sự liên quan","đồ bên trong; nội dung bên trong"]'::jsonb, 3, 'contents (/ˈkɑːntents/) → đồ bên trong; nội dung bên trong; mục lục', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_53_2', 'en-b1-53', NULL, 'comprehensive_test', 'listening', 'She keeps her gardening tools in neat rows.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã thưởng thức bữa sáng muộn ngoài ban công vào sáng nay.","Tôi đã làm chiếc đệm lót này dành riêng cho chiếc ghế của bạn.","Anh trai tôi vừa rửa bát vừa huýt sáo những giai điệu vui tươi.","Cô ấy xếp các dụng cụ làm vườn thành những hàng ngay ngắn."]'::jsonb, 3, 'She keeps her gardening tools in neat rows. → Cô ấy xếp các dụng cụ làm vườn thành những hàng ngay ngắn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_53_3', 'en-b1-53', NULL, 'comprehensive_test', 'listening', 'feature', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tầm quan trọng; giá trị lớn","vùng; khu vực","đặc điểm; nét đặc trưng","độc nhất; độc đáo"]'::jsonb, 2, 'feature (/ˈfiːtʃər/) → đặc điểm; nét đặc trưng; có nét đặc sắc; nổi bật; đặc điểm khuôn mặt; ngũ quan', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_53_4', 'en-b1-53', NULL, 'comprehensive_test', 'listening', 'I made this cushion specially for your chair.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã làm chiếc đệm lót này dành riêng cho chiếc ghế của bạn.","Cửa hàng này bán rất nhiều loại trái cây tươi.","Sau khi lục tìm qua mọi căn phòng, cuối cùng chúng tôi cũng tìm thấy chùm chìa khóa bị mất.","Đặc điểm mà tôi thích nhất ở chiếc ba lô này là chiếc túi ẩn của nó."]'::jsonb, 0, 'I made this cushion specially for your chair. → Tôi đã làm chiếc đệm lót này dành riêng cho chiếc ghế của bạn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
