INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_53_6', 'en-b1-53', NULL, 'comprehensive_test', 'listening', 'Please warn me if the pan gets too hot.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy nhắc tôi nếu cái chảo trở nên quá nóng nhé.","Cô ấy đổ hết mọi thứ trong túi xách của mình lên bàn.","Tôi hoàn toàn quên mang theo đồ bơi của mình.","Tôi đã làm chiếc đệm lót này dành riêng cho chiếc ghế của bạn."]'::jsonb, 0, 'Please warn me if the pan gets too hot. → Hãy nhắc tôi nếu cái chảo trở nên quá nóng nhé.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
