INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_53_8', 'en-b1-53', NULL, 'comprehensive_test', 'listening', 'This shop sells a wide range of fresh fruit.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cẩn thận kẻo làm rách túi giấy đấy.","Chúng tôi đã thưởng thức bữa sáng muộn ngoài ban công vào sáng nay.","Vui lòng lau bàn sạch sẽ trước khi đặt đĩa thức ăn lên nhé.","Cửa hàng này bán rất nhiều loại trái cây tươi."]'::jsonb, 3, 'This shop sells a wide range of fresh fruit. → Cửa hàng này bán rất nhiều loại trái cây tươi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
