INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_53_18', 'en-b1-53', NULL, 'comprehensive_test', 'reading', NULL, 'A detailed table of contents helps readers locate relevant information quickly in lengthy academic reports.', 'Dựa vào câu trên, từ “contents” có nghĩa phù hợp nhất là gì?', '["động vật hoang dã; sinh vật hoang dã","lan truyền; truyền bá","đồ bên trong; nội dung bên trong","cân nhắc; suy nghĩ kỹ lưỡng trước khi quyết định"]'::jsonb, 2, 'contents: đồ bên trong; nội dung bên trong; mục lục. Dịch cả câu: Bảng mục lục chi tiết giúp người đọc nhanh chóng tìm thấy thông tin liên quan trong các báo cáo học thuật dài.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_53_19', 'en-b1-53', NULL, 'comprehensive_test', 'reading', NULL, 'Keeping shared workspaces neat can improve efficiency by making essential equipment easier to locate.', 'Dựa vào câu trên, từ “neat” có nghĩa phù hợp nhất là gì?', '["thang cuốn","tên ngốc; kẻ đần độn","ngăn nắp; gọn gàng","sự tạ ơn; lời cầu nguyện cảm ơn"]'::jsonb, 2, 'neat: ngăn nắp; gọn gàng; khéo léo; gọn gàng và hiệu quả. Dịch cả câu: Việc giữ cho không gian làm việc chung ngăn nắp có thể nâng cao hiệu quả bằng cách giúp việc tìm kiếm các thiết bị cần thiết trở nên dễ dàng hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_53_20', 'en-b1-53', NULL, 'comprehensive_test', 'reading', NULL, 'Public parks are an essential feature of cities that prioritise residents'' health and wellbeing.', 'Dựa vào câu trên, từ “feature” có nghĩa phù hợp nhất là gì?', '["trần nhà","đặc điểm; nét đặc trưng","cảng biển; bến cảng","buổi tụ họp; buổi liên hoan"]'::jsonb, 1, 'feature: đặc điểm; nét đặc trưng; có nét đặc sắc; nổi bật; đặc điểm khuôn mặt; ngũ quan. Dịch cả câu: Các công viên công cộng là một đặc điểm thiết yếu của những thành phố ưu tiên sức khỏe và hạnh phúc của cư dân.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_53_21', 'en-b1-53', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should provide specially designed learning materials to support students with different educational needs.', 'Dựa vào câu trên, từ “specially” có nghĩa phù hợp nhất là gì?', '["đặc biệt; riêng biệt","sự hiểu biết; sự thông cảm","bão cuồng phong; bão lớn vùng nhiệt đới","tủ gửi đồ; tủ có khóa (để đồ cá nhân)"]'::jsonb, 0, 'specially: đặc biệt; riêng biệt. Dịch cả câu: Nhà trường nên cung cấp tài liệu học tập được thiết kế riêng nhằm hỗ trợ học sinh có các nhu cầu giáo dục khác nhau.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_53_22', 'en-b1-53', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chẳng bao lâu nữa; không lâu sau”', '["shortly","schedule","version","cushion"]'::jsonb, 0, 'chẳng bao lâu nữa; không lâu sau → shortly (/ˈʃɔːrtli/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_53_23', 'en-b1-53', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đã qua sử dụng; hàng cũ; đồ si”', '["secondhand","sudden","remain","generally"]'::jsonb, 0, 'đã qua sử dụng; hàng cũ; đồ si → secondhand (/ˌsekəndˈhænd/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_53_24', 'en-b1-53', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự đăng ký; việc ghi danh”', '["absent","medical","registration","knit"]'::jsonb, 2, 'sự đăng ký; việc ghi danh → registration (/ˌredʒɪˈstreɪʃən/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-54', 'en', 'Bài 54: Đời sống hằng ngày (6) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3054, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whenever', 'en-b1-54', 'whenever', '/wenˈevɚ/', 'B1', 'mỗi khi; bất cứ khi nào; bất cứ lúc nào; rốt cuộc khi nào', 'conj.', 'when (adv.)', NULL, 'Khi dùng để mở đầu mệnh đề chỉ thời gian trong tương lai, thường dùng thì hiện tại đơn thay vì will.', 'Whenever I cook soup, my cat waits beside the stove.', NULL, 'Mỗi khi tôi nấu súp, con mèo nhà tôi lại ngồi chờ bên cạnh bếp lò.', '{"wordId":"whenever","ukIpa":"/wenˈevə/","usIpa":"/wenˈevɚ/","cefr":"B1","topic":"daily","senses":[{"pos":"conj.","en":"Every time that something happens.","vi":"mỗi khi; bất cứ khi nào"},{"pos":"conj.","en":"At any time that something happens or is convenient.","vi":"bất cứ lúc nào"},{"pos":"adv.","en":"Used in questions to express surprise about when something happened.","vi":"rốt cuộc khi nào"}],"examples":[{"en":"Whenever I cook soup, my cat waits beside the stove.","vi":"Mỗi khi tôi nấu súp, con mèo nhà tôi lại ngồi chờ bên cạnh bếp lò.","audioKind":"ex"},{"en":"Whenever cities expand, planners should consider how new developments will affect existing communities and local wildlife.","vi":"Bất cứ khi nào các thành phố mở rộng quy mô, các nhà quy hoạch nên xem xét các dự án phát triển mới sẽ ảnh hưởng như thế nào đến cộng đồng hiện hữu và động vật hoang dã địa phương.","audioKind":"ex2"}],"collocations":[{"en":"whenever possible","vi":"bất cứ khi nào có thể"},{"en":"whenever necessary","vi":"mỗi khi cần thiết"},{"en":"whenever you like","vi":"bất cứ lúc nào bạn thích"}],"wordFamily":["when (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng để mở đầu mệnh đề chỉ thời gian trong tương lai, thường dùng thì hiện tại đơn thay vì will.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reserve', 'en-b1-54', 'reserve', '/rɪˈzɝːv/', 'B1', 'đặt trước; giữ lại; nguồn dự trữ; lượng dự trữ; khu bảo tồn thiên nhiên', 'v.', 'reservation (n.), reserved (adj.)', NULL, 'Động từ thường dùng "reserve sth for sb"; chỉ trữ lượng thường dùng dạng số nhiều "reserves".', 'Could you reserve a table for us tonight?', NULL, 'Bạn có thể đặt trước cho chúng tôi một bàn vào tối nay không?', '{"wordId":"reserve","ukIpa":"/rɪˈzɜːv/","usIpa":"/rɪˈzɝːv/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Arrange to keep something for a particular person or purpose.","vi":"đặt trước; giữ lại"},{"pos":"n.","en":"A supply kept for use when needed.","vi":"nguồn dự trữ; lượng dự trữ"},{"pos":"n.","en":"An area where wildlife and natural habitats are protected.","vi":"khu bảo tồn thiên nhiên"}],"examples":[{"en":"Could you reserve a table for us tonight?","vi":"Bạn có thể đặt trước cho chúng tôi một bàn vào tối nay không?","audioKind":"ex"},{"en":"Governments should maintain adequate food reserves to protect vulnerable communities during periods of severe drought.","vi":"Các chính phủ nên duy trì lượng dự trữ lương thực đầy đủ để bảo vệ các cộng đồng dễ bị tổn thương trong thời kỳ hạn hán nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"reserve a table","vi":"đặt bàn"},{"en":"reserve something for someone","vi":"để dành cái gì cho ai"},{"en":"nature reserve","vi":"khu bảo tồn thiên nhiên"},{"en":"oil reserves","vi":"trữ lượng dầu mỏ"}],"wordFamily":["reservation (n.)","reserved (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường dùng \"reserve sth for sb\"; chỉ trữ lượng thường dùng dạng số nhiều \"reserves\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tag', 'en-b1-54', 'tag', '/tæɡ/', 'B1', 'thẻ; nhãn; mác; dán nhãn; gắn thẻ; đánh dấu; trò chơi đuổi bắt', 'n.', NULL, 'Đồng nghĩa: label', 'Past tense tagged; tag along means to go somewhere with someone.', 'I checked the tag before washing my new jumper.', NULL, 'Tôi đã kiểm tra nhãn mác trước khi giặt chiếc áo len mới của mình.', '{"wordId":"tag","ukIpa":"/tæɡ/","usIpa":"/tæɡ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a small attached piece giving information about something","vi":"thẻ; nhãn; mác"},{"pos":"v.","en":"to attach a label or identifying marker to something","vi":"dán nhãn; gắn thẻ; đánh dấu"},{"pos":"n.","en":"a chasing game where players touch others to catch them","vi":"trò chơi đuổi bắt"}],"examples":[{"en":"I checked the tag before washing my new jumper.","vi":"Tôi đã kiểm tra nhãn mác trước khi giặt chiếc áo len mới của mình.","audioKind":"ex"},{"en":"Researchers tag marine animals to track their movements and identify habitats that require stronger environmental protection.","vi":"Các nhà nghiên cứu gắn thẻ các loài động vật biển để theo dõi hoạt động di chuyển của chúng và xác định các môi trường sống cần được bảo vệ môi trường mạnh mẽ hơn.","audioKind":"ex2"}],"collocations":[{"en":"price tag","vi":"thẻ giá"},{"en":"name tag","vi":"thẻ tên"},{"en":"tag someone in a photo","vi":"gắn thẻ ai đó trong ảnh"},{"en":"play tag","vi":"chơi trò đuổi bắt"}],"wordFamily":[],"synonyms":["label"],"antonyms":[],"tipVi":"Past tense tagged; tag along means to go somewhere with someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stuff', 'en-b1-54', 'stuff', '/stʌf/', 'B1', 'đồ đạc; thứ; vật dụng; nhồi nhét; nhét đầy', 'n.', 'stuffing (n.), stuffed (adj.)', 'Đồng nghĩa: things, belongings', 'Noun stuff is uncountable and informal; formal writing should use specific nouns.', 'Please move your stuff off the kitchen table.', NULL, 'Làm ơn dọn đồ đạc của bạn khỏi bàn bếp đi.', '{"wordId":"stuff","ukIpa":"/stʌf/","usIpa":"/stʌf/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Things or materials referred to without naming them specifically.","vi":"đồ đạc; thứ; vật dụng"},{"pos":"v.","en":"To fill something tightly or push something into a space.","vi":"nhồi nhét; nhét đầy"}],"examples":[{"en":"Please move your stuff off the kitchen table.","vi":"Làm ơn dọn đồ đạc của bạn khỏi bàn bếp đi.","audioKind":"ex"},{"en":"Consumers often buy stuff they rarely use, contributing to household waste and unnecessary resource consumption.","vi":"Người tiêu dùng thường mua những món đồ hiếm khi dùng đến, góp phần gây ra rác thải sinh hoạt và tiêu thụ tài nguyên không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"personal stuff","vi":"đồ đạc cá nhân"},{"en":"stuff a bag with","vi":"nhét đầy túi bằng cái gì"},{"en":"stuff into","vi":"nhét vào trong"}],"wordFamily":["stuffing (n.)","stuffed (adj.)"],"synonyms":["things","belongings"],"antonyms":[],"tipVi":"Noun stuff is uncountable and informal; formal writing should use specific nouns.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pumpkin', 'en-b1-54', 'pumpkin', '/ˈpʌmpkɪn/', 'B1', 'quả bí ngô', 'n.', NULL, NULL, 'Cả quả bí ngô là danh từ đếm được; khi chỉ bí ngô như một nguyên liệu nấu ăn thì thường là danh từ không đếm được.', 'We roasted a pumpkin and served it with rice.', NULL, 'Chúng tôi đã nướng một quả bí ngô và ăn kèm với cơm.', '{"wordId":"pumpkin","ukIpa":"/ˈpʌmpkɪn/","usIpa":"/ˈpʌmpkɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A large, round fruit with thick skin, often orange.","vi":"quả bí ngô"}],"examples":[{"en":"We roasted a pumpkin and served it with rice.","vi":"Chúng tôi đã nướng một quả bí ngô và ăn kèm với cơm.","audioKind":"ex"},{"en":"Growing crops such as pumpkin in community gardens can improve access to fresh food in urban neighbourhoods.","vi":"Trồng các loại cây hoa màu như bí ngô trong các khu vườn cộng đồng có thể giúp cải thiện khả năng tiếp cận thực phẩm tươi sạch ở các khu dân cư đô thị.","audioKind":"ex2"}],"collocations":[{"en":"pumpkin soup","vi":"súp bí ngô"},{"en":"pumpkin seeds","vi":"hạt bí ngô"},{"en":"roasted pumpkin","vi":"bí ngô nướng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cả quả bí ngô là danh từ đếm được; khi chỉ bí ngô như một nguyên liệu nấu ăn thì thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gently', 'en-b1-54', 'gently', '/ˈdʒentli/', 'B1', 'nhẹ nhàng; dịu dàng; thoai thoải; êm ả', 'adv.', 'gentle (adj.), gentleness (n.)', 'Đồng nghĩa: softly, tenderly · Trái nghĩa: roughly, harshly', 'Được tạo thành từ tính từ ''gentle'' bỏ chữ ''e'' ở cuối rồi thêm ''y''.', 'She gently lifted the kitten out of the basket.', NULL, 'Cô ấy nhẹ nhàng nhấc chú mèo con ra khỏi giỏ.', '{"wordId":"gently","ukIpa":"/ˈdʒentli/","usIpa":"/ˈdʒentli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"In a soft, careful, or kind way.","vi":"nhẹ nhàng; dịu dàng"},{"pos":"adv.","en":"With a gradual slope or a small, smooth movement.","vi":"thoai thoải; êm ả"}],"examples":[{"en":"She gently lifted the kitten out of the basket.","vi":"Cô ấy nhẹ nhàng nhấc chú mèo con ra khỏi giỏ.","audioKind":"ex"},{"en":"Health professionals should speak gently to anxious patients to help them feel comfortable during medical examinations.","vi":"Các chuyên gia y tế nên nói chuyện nhẹ nhàng với những bệnh nhân lo lắng để giúp họ cảm thấy thoải mái trong suốt quá trình khám bệnh.","audioKind":"ex2"}],"collocations":[{"en":"gently stir","vi":"khuấy nhẹ"},{"en":"speak gently","vi":"nói chuyện nhẹ nhàng"},{"en":"slope gently","vi":"dốc thoai thoải"}],"wordFamily":["gentle (adj.)","gentleness (n.)"],"synonyms":["softly","tenderly"],"antonyms":["roughly","harshly"],"tipVi":"Được tạo thành từ tính từ ''gentle'' bỏ chữ ''e'' ở cuối rồi thêm ''y''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_medium-sized', 'en-b1-54', 'medium-sized', '/ˌmiːdiəm ˈsaɪzd/', 'B1', 'cỡ trung bình; trung cỡ', 'adj.', 'size (n.), medium (adj.)', 'Đồng nghĩa: mid-sized', 'Diễn tả kích thước vừa phải, không dùng để chỉ chất lượng hay trình độ ở mức trung bình.', 'A medium-sized suitcase should hold everything for the weekend.', NULL, 'Một chiếc vali cỡ trung bình lẽ ra phải đựng vừa mọi thứ cho chuyến đi cuối tuần.', '{"wordId":"medium-sized","ukIpa":"/ˌmiːdiəm ˈsaɪzd/","usIpa":"/ˌmiːdiəm ˈsaɪzd/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"neither large nor small in size","vi":"cỡ trung bình; trung cỡ"}],"examples":[{"en":"A medium-sized suitcase should hold everything for the weekend.","vi":"Một chiếc vali cỡ trung bình lẽ ra phải đựng vừa mọi thứ cho chuyến đi cuối tuần.","audioKind":"ex"},{"en":"Medium-sized cities can offer diverse employment opportunities while maintaining shorter commuting times than major urban centres.","vi":"Các thành phố quy mô trung bình có thể cung cấp nhiều cơ hội việc làm đa dạng đồng thời duy trì thời gian di chuyển ngắn hơn so với các trung tâm đô thị lớn.","audioKind":"ex2"}],"collocations":[{"en":"medium-sized business","vi":"doanh nghiệp vừa"},{"en":"medium-sized city","vi":"thành phố cỡ trung bình"},{"en":"medium-sized suitcase","vi":"vali cỡ trung"}],"wordFamily":["size (n.)","medium (adj.)"],"synonyms":["mid-sized"],"antonyms":[],"tipVi":"Diễn tả kích thước vừa phải, không dùng để chỉ chất lượng hay trình độ ở mức trung bình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blanket', 'en-b1-54', 'blanket', '/ˈblæŋkɪt/', 'B1', 'tấm chăn; lớp phủ; toàn diện; áp dụng chung; bao phủ; bao trùm', 'n.', NULL, NULL, 'Blanket làm tính từ chỉ sự áp dụng toàn diện, chẳng hạn như blanket ban.', 'She wrapped a soft blanket around her cold shoulders.', NULL, 'Cô ấy quấn một chiếc chăn mềm quanh bờ vai lạnh giá của mình.', '{"wordId":"blanket","ukIpa":"/ˈblæŋkɪt/","usIpa":"/ˈblæŋkɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A thick bed covering, or a layer covering something.","vi":"tấm chăn; lớp phủ"},{"pos":"adj.","en":"Applying to everyone or everything without considering individual differences.","vi":"toàn diện; áp dụng chung"},{"pos":"v.","en":"To cover something completely with a layer.","vi":"bao phủ; bao trùm"}],"examples":[{"en":"She wrapped a soft blanket around her cold shoulders.","vi":"Cô ấy quấn một chiếc chăn mềm quanh bờ vai lạnh giá của mình.","audioKind":"ex"},{"en":"A blanket ban on private vehicles may disadvantage residents who cannot easily access public transport.","vi":"Lệnh cấm toàn diện đối với xe cá nhân có thể gây bất lợi cho những cư dân khó tiếp cận phương tiện giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"a warm blanket","vi":"tấm chăn ấm"},{"en":"a blanket of snow","vi":"lớp tuyết dày"},{"en":"a blanket ban","vi":"lệnh cấm toàn diện"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Blanket làm tính từ chỉ sự áp dụng toàn diện, chẳng hạn như blanket ban.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_darkness', 'en-b1-54', 'darkness', '/ˈdɑːrknəs/', 'B1', 'bóng tối; sự tối tăm', 'n.', 'dark (adj.), darken (v.), darkly (adv.)', 'Đồng nghĩa: gloom · Trái nghĩa: light, brightness', 'Thường là danh từ không đếm được; cấu trúc in darkness có nghĩa là ở trong bóng tối.', 'We searched for the torch in complete darkness.', NULL, 'Chúng tôi tìm kiếm chiếc đèn pin trong bóng tối hoàn toàn.', '{"wordId":"darkness","ukIpa":"/ˈdɑːknəs/","usIpa":"/ˈdɑːrknəs/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"the absence of light","vi":"bóng tối; sự tối tăm"}],"examples":[{"en":"We searched for the torch in complete darkness.","vi":"Chúng tôi tìm kiếm chiếc đèn pin trong bóng tối hoàn toàn.","audioKind":"ex"},{"en":"Artificial lighting reduces natural darkness in urban areas, potentially disrupting the sleep patterns of residents and wildlife.","vi":"Hệ thống chiếu sáng nhân tạo làm giảm bóng tối tự nhiên tại các khu vực đô thị, có thể làm xáo trộn nhịp sinh học của cư dân và động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"complete darkness","vi":"bóng tối hoàn toàn"},{"en":"in the darkness","vi":"trong bóng tối"},{"en":"under cover of darkness","vi":"dưới lớp màn đêm"}],"wordFamily":["dark (adj.)","darken (v.)","darkly (adv.)"],"synonyms":["gloom"],"antonyms":["light","brightness"],"tipVi":"Thường là danh từ không đếm được; cấu trúc in darkness có nghĩa là ở trong bóng tối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_odd', 'en-b1-54', 'odd', '/ɑːd/', 'B1', 'kỳ lạ; quái lạ; bất thường; lẻ (số học); thỉnh thoảng; không thường xuyên; lẻ tẻ', 'adj.', 'oddly (adv.), oddness (n.), oddity (n.)', 'Đồng nghĩa: strange, unusual · Trái nghĩa: ordinary, even', 'Cụm từ the odd đi với danh từ số ít thường mang nghĩa thỉnh thoảng/đôi khi.', 'There is an odd smell coming from the fridge.', NULL, 'Có một mùi kỳ lạ phát ra từ tủ lạnh.', '{"wordId":"odd","ukIpa":"/ɒd/","usIpa":"/ɑːd/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Strange or different from what is expected.","vi":"kỳ lạ; quái lạ; bất thường"},{"pos":"adj.","en":"Not divisible by two without a remainder.","vi":"lẻ (số học)"},{"pos":"adj.","en":"Occasional rather than regular or frequent.","vi":"thỉnh thoảng; không thường xuyên; lẻ tẻ"}],"examples":[{"en":"There is an odd smell coming from the fridge.","vi":"Có một mùi kỳ lạ phát ra từ tủ lạnh.","audioKind":"ex"},{"en":"It may seem odd that some rapidly growing cities still lack reliable access to clean drinking water.","vi":"Có vẻ kỳ lạ khi một số thành phố đang phát triển nhanh chóng vẫn thiếu khả năng tiếp cận nguồn nước uống sạch một cách ổn định.","audioKind":"ex2"}],"collocations":[{"en":"an odd smell","vi":"mùi lạ"},{"en":"an odd number","vi":"số lẻ"},{"en":"the odd occasion","vi":"dịp hiếm hoi"},{"en":"odd jobs","vi":"việc vặt; việc làm thời vụ"}],"wordFamily":["oddly (adv.)","oddness (n.)","oddity (n.)"],"synonyms":["strange","unusual"],"antonyms":["ordinary","even"],"tipVi":"Cụm từ the odd đi với danh từ số ít thường mang nghĩa thỉnh thoảng/đôi khi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ashtray', 'en-b1-54', 'ashtray', '/ˈæʃtreɪ/', 'B1', 'gạt tàn thuốc', 'n.', 'ash (n.)', NULL, 'Là danh từ đếm được, được cấu thành từ ash (tro) và tray (khay).', 'An empty glass ashtray stood on the outdoor table.', NULL, 'Một chiếc gạt tàn thủy tinh trống không đặt trên bàn ngoài trời.', '{"wordId":"ashtray","ukIpa":"/ˈæʃtreɪ/","usIpa":"/ˈæʃtreɪ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A small container for cigarette ash and cigarette ends","vi":"gạt tàn thuốc"}],"examples":[{"en":"An empty glass ashtray stood on the outdoor table.","vi":"Một chiếc gạt tàn thủy tinh trống không đặt trên bàn ngoài trời.","audioKind":"ex"},{"en":"Providing ashtrays in designated smoking areas can reduce cigarette litter, although broader measures are needed to protect public health.","vi":"Việc cung cấp gạt tàn tại các khu vực hút thuốc được chỉ định có thể làm giảm rác tàn thuốc, mặc dù cần có các biện pháp rộng hơn để bảo vệ sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"a glass ashtray","vi":"gạt tàn thủy tinh"},{"en":"empty an ashtray","vi":"đổ gạt tàn"},{"en":"a cigarette ashtray","vi":"gạt tàn thuốc lá"}],"wordFamily":["ash (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được, được cấu thành từ ash (tro) và tray (khay).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ingredient', 'en-b1-54', 'ingredient', '/ɪnˈɡriːdiənt/', 'B1', 'nguyên liệu; thành phần (nấu ăn); thành phần; yếu tố (cấu thành một kết quả)', 'n.', NULL, 'Đồng nghĩa: component, element', 'Là danh từ đếm được; dùng cho cả nguyên liệu nấu ăn lẫn yếu tố trừu tượng.', 'Fresh ginger is the main ingredient in this soup.', NULL, 'Gừng tươi là nguyên liệu chính trong món súp này.', '{"wordId":"ingredient","ukIpa":"/ɪnˈɡriːdiənt/","usIpa":"/ɪnˈɡriːdiənt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"one of the foods used to prepare a dish","vi":"nguyên liệu; thành phần (nấu ăn)"},{"pos":"n.","en":"one of the things needed to achieve a particular result","vi":"thành phần; yếu tố (cấu thành một kết quả)"}],"examples":[{"en":"Fresh ginger is the main ingredient in this soup.","vi":"Gừng tươi là nguyên liệu chính trong món súp này.","audioKind":"ex"},{"en":"Public trust is an essential ingredient in the successful implementation of environmental policies.","vi":"Sự tin tưởng của công chúng là một yếu tố thiết yếu trong việc thực thi thành công các chính sách môi trường.","audioKind":"ex2"}],"collocations":[{"en":"main ingredient","vi":"nguyên liệu chính"},{"en":"fresh ingredients","vi":"nguyên liệu tươi"},{"en":"essential ingredient","vi":"yếu tố cốt lõi"}],"wordFamily":[],"synonyms":["component","element"],"antonyms":[],"tipVi":"Là danh từ đếm được; dùng cho cả nguyên liệu nấu ăn lẫn yếu tố trừu tượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blank', 'en-b1-54', 'blank', '/blæŋk/', 'B1', 'trống; để trắng (không có chữ, hình ảnh); trống rỗng; ngơ ngác (không biểu lộ cảm xúc hay sự hiểu biết); chỗ trống (cần điền thông tin)', 'adj.', 'blankly (adv.), blankness (n.)', 'Đồng nghĩa: empty, expressionless · Trái nghĩa: filled', 'Cụm từ go blank dùng khi đầu óc bỗng nhiên trống rỗng, không nhớ ra gì.', 'She handed me a blank sheet and some pencils.', NULL, 'Cô ấy đưa cho tôi một tờ giấy trắng và vài cây bút chì.', '{"wordId":"blank","ukIpa":"/blæŋk/","usIpa":"/blæŋk/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"having no writing, pictures, or other content","vi":"trống; để trắng (không có chữ, hình ảnh)"},{"pos":"adj.","en":"showing no understanding, feeling, or recognition","vi":"trống rỗng; ngơ ngác (không biểu lộ cảm xúc hay sự hiểu biết)"},{"pos":"n.","en":"an empty space where information should be added","vi":"chỗ trống (cần điền thông tin)"}],"examples":[{"en":"She handed me a blank sheet and some pencils.","vi":"Cô ấy đưa cho tôi một tờ giấy trắng và vài cây bút chì.","audioKind":"ex"},{"en":"A blank page can encourage creative thinking by allowing learners to organise ideas without a fixed template.","vi":"Một trang giấy trắng có thể kích thích tư duy sáng tạo bằng cách cho phép người học sắp xếp ý tưởng mà không bị gò bó bởi một khuôn mẫu cố định.","audioKind":"ex2"}],"collocations":[{"en":"a blank page","vi":"một trang giấy trắng"},{"en":"a blank expression","vi":"vẻ mặt đờ đẫn"},{"en":"fill in the blanks","vi":"điền vào chỗ trống"},{"en":"go blank","vi":"trở nên trống rỗng (trong đầu)"}],"wordFamily":["blankly (adv.)","blankness (n.)"],"synonyms":["empty","expressionless"],"antonyms":["filled"],"tipVi":"Cụm từ go blank dùng khi đầu óc bỗng nhiên trống rỗng, không nhớ ra gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_leisure', 'en-b1-54', 'leisure', '/ˈliːʒər/', 'B1', 'thời gian rảnh rỗi; lúc thảnh thơi', 'n.', 'leisurely (adj.)', 'Đồng nghĩa: free time', 'Từ leisure thường là danh từ không đếm được; cụm leisure time có nghĩa là thời gian rảnh rỗi.', 'She spends most of her leisure time in the garden.', NULL, 'Cô ấy dành phần lớn thời gian rảnh rỗi của mình ở ngoài vườn.', '{"wordId":"leisure","ukIpa":"/ˈleʒə/","usIpa":"/ˈliːʒər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Time when you are free from work or other duties.","vi":"thời gian rảnh rỗi; lúc thảnh thơi"}],"examples":[{"en":"She spends most of her leisure time in the garden.","vi":"Cô ấy dành phần lớn thời gian rảnh rỗi của mình ở ngoài vườn.","audioKind":"ex"},{"en":"Public parks provide affordable spaces for leisure, helping urban residents relax and maintain social connections.","vi":"Các công viên công cộng cung cấp không gian giải trí chi phí thấp, giúp cư dân thành thị thư giãn và duy trì các mối quan hệ xã hội.","audioKind":"ex2"}],"collocations":[{"en":"leisure time","vi":"thời gian rảnh rỗi"},{"en":"leisure activities","vi":"các hoạt động giải trí"},{"en":"leisure centre","vi":"trung tâm giải trí"},{"en":"at your leisure","vi":"vào lúc bạn rảnh rỗi; một cách thảnh thơi"}],"wordFamily":["leisurely (adj.)"],"synonyms":["free time"],"antonyms":[],"tipVi":"Từ leisure thường là danh từ không đếm được; cụm leisure time có nghĩa là thời gian rảnh rỗi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prepared', 'en-b1-54', 'prepared', '/prɪˈperd/', 'B1', 'đã chuẩn bị sẵn sàng; sẵn lòng; sẵn sàng (làm việc gì khó khăn hoặc khó chịu)', 'adj.', 'prepare (v.), preparation (n.), preparedness (n.), unprepared (adj.)', 'Đồng nghĩa: ready, willing · Trái nghĩa: unprepared, unwilling', 'Tính từ prepared đi với giới từ for trước danh từ; cấu trúc prepared to do diễn tả sự sẵn lòng.', 'With spare batteries packed, we were prepared for a blackout.', NULL, 'Với những viên pin dự phòng đã được cất kỹ, chúng tôi đã sẵn sàng ứng phó với tình trạng mất điện.', '{"wordId":"prepared","ukIpa":"/prɪˈpeəd/","usIpa":"/prɪˈperd/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Ready to deal with something because of previous planning.","vi":"đã chuẩn bị sẵn sàng"},{"pos":"adj.","en":"Willing to do something, especially something difficult or unpleasant.","vi":"sẵn lòng; sẵn sàng (làm việc gì khó khăn hoặc khó chịu)"}],"examples":[{"en":"With spare batteries packed, we were prepared for a blackout.","vi":"Với những viên pin dự phòng đã được cất kỹ, chúng tôi đã sẵn sàng ứng phó với tình trạng mất điện.","audioKind":"ex"},{"en":"Graduates who gain practical experience are often better prepared for the demands of a competitive labour market.","vi":"Những sinh viên tốt nghiệp có kinh nghiệm thực tế thường chuẩn bị tốt hơn để đáp ứng các yêu cầu của thị trường lao động mang tính cạnh tranh.","audioKind":"ex2"}],"collocations":[{"en":"prepared for emergencies","vi":"sẵn sàng ứng phó với tình huống khẩn cấp"},{"en":"fully prepared","vi":"được chuẩn bị hoàn chu đáo"},{"en":"prepared to compromise","vi":"sẵn sàng thỏa hiệp"}],"wordFamily":["prepare (v.)","preparation (n.)","preparedness (n.)","unprepared (adj.)"],"synonyms":["ready","willing"],"antonyms":["unprepared","unwilling"],"tipVi":"Tính từ prepared đi với giới từ for trước danh từ; cấu trúc prepared to do diễn tả sự sẵn lòng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_entry', 'en-b1-54', 'entry', '/ˈentri/', 'B1', 'sự đi vào; quyền vào; mục (trong danh sách, nhật ký hoặc tài liệu tham khảo); tác phẩm dự thi; người tham gia', 'n.', 'enter (v.), entrance (n.), entrant (n.)', NULL, 'Để chỉ quyền đi vào nơi nào đó dùng entry to, còn lối ra vào cụ thể thường dùng entrance.', 'Entry to the swimming pool is free today.', NULL, 'Hôm nay vé vào hồ bơi được miễn phí.', '{"wordId":"entry","ukIpa":"/ˈentri/","usIpa":"/ˈentri/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The act of entering, or permission to enter a place.","vi":"sự đi vào; quyền vào"},{"pos":"n.","en":"An individual item in a list, diary, or reference work.","vi":"mục (trong danh sách, nhật ký hoặc tài liệu tham khảo)"},{"pos":"n.","en":"A work or person submitted for a competition.","vi":"tác phẩm dự thi; người tham gia"}],"examples":[{"en":"Entry to the swimming pool is free today.","vi":"Hôm nay vé vào hồ bơi được miễn phí.","audioKind":"ex"},{"en":"Strict entry requirements may prevent capable students from disadvantaged backgrounds from accessing higher education opportunities.","vi":"Các yêu cầu đầu vào nghiêm ngặt có thể ngăn cản những học sinh tài năng có hoàn cảnh khó khăn tiếp cận các cơ hội giáo dục đại học.","audioKind":"ex2"}],"collocations":[{"en":"entry requirements","vi":"yêu cầu đầu vào"},{"en":"free entry","vi":"vào cửa miễn phí"},{"en":"diary entry","vi":"mục nhật ký"},{"en":"competition entry","vi":"bài dự thi"}],"wordFamily":["enter (v.)","entrance (n.)","entrant (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Để chỉ quyền đi vào nơi nào đó dùng entry to, còn lối ra vào cụ thể thường dùng entrance.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_require', 'en-b1-54', 'require', '/rɪˈkwaɪr/', 'B1', 'cần; đòi hỏi; quy định; yêu cầu', 'v.', 'requirement (n.), required (adj.)', 'Đồng nghĩa: need, demand', 'require sb to do sth có nghĩa là yêu cầu ai đó làm điều gì.', 'These plants require plenty of sunlight and regular watering.', NULL, 'Những loại cây này cần rất nhiều ánh sáng mặt trời và được tưới nước thường xuyên.', '{"wordId":"require","ukIpa":"/rɪˈkwaɪə/","usIpa":"/rɪˈkwaɪr/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To need something for a particular purpose","vi":"cần; đòi hỏi"},{"pos":"v.","en":"To make something necessary through a rule or instruction","vi":"quy định; yêu cầu"}],"examples":[{"en":"These plants require plenty of sunlight and regular watering.","vi":"Những loại cây này cần rất nhiều ánh sáng mặt trời và được tưới nước thường xuyên.","audioKind":"ex"},{"en":"Governments should require manufacturers to provide clear instructions for repairing products rather than replacing them.","vi":"Chính phủ nên yêu cầu các nhà sản xuất cung cấp hướng dẫn rõ ràng về việc sửa chữa sản phẩm thay vì thay thế chúng.","audioKind":"ex2"}],"collocations":[{"en":"require assistance","vi":"cần sự hỗ trợ"},{"en":"require attention","vi":"cần được chú ý"},{"en":"be required to do something","vi":"bị yêu cầu làm điều gì đó"},{"en":"require further investigation","vi":"cần điều tra thêm"}],"wordFamily":["requirement (n.)","required (adj.)"],"synonyms":["need","demand"],"antonyms":[],"tipVi":"require sb to do sth có nghĩa là yêu cầu ai đó làm điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tend', 'en-b1-54', 'tend', '/tend/', 'B1', 'có xu hướng; thường; chăm sóc; trông nom', 'v.', 'tendency (n.)', NULL, 'tend to do diễn tả có xu hướng làm gì; tend to someone diễn tả việc chăm sóc ai đó.', 'I tend to feel sleepy after a big lunch.', NULL, 'Tôi thường cảm thấy buồn ngủ sau một bữa trưa no nê.', '{"wordId":"tend","ukIpa":"/tend/","usIpa":"/tend/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To usually behave in a particular way.","vi":"có xu hướng; thường"},{"pos":"v.","en":"To look after someone or something.","vi":"chăm sóc; trông nom"}],"examples":[{"en":"I tend to feel sleepy after a big lunch.","vi":"Tôi thường cảm thấy buồn ngủ sau một bữa trưa no nê.","audioKind":"ex"},{"en":"People tend to use public transport more frequently when services are reliable, affordable, and easy to access.","vi":"Mọi người có xu hướng sử dụng phương tiện giao thông công cộng thường xuyên hơn khi dịch vụ đáng tin cậy, có giá cả phải chăng và dễ dàng tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"tend to do something","vi":"có xu hướng làm điều gì"},{"en":"tend towards","vi":"có chiều hướng"},{"en":"tend a garden","vi":"chăm sóc khu vườn"},{"en":"tend to the injured","vi":"chăm sóc người bị thương"}],"wordFamily":["tendency (n.)"],"synonyms":[],"antonyms":[],"tipVi":"tend to do diễn tả có xu hướng làm gì; tend to someone diễn tả việc chăm sóc ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seafood', 'en-b1-54', 'seafood', '/ˈsiːfuːd/', 'B1', 'hải sản', 'n.', NULL, NULL, 'Thường là danh từ không đếm được; một đĩa hải sản có thể dùng a plate of seafood.', 'We bought fresh seafood at the harbour this morning.', NULL, 'Chúng tôi đã mua hải sản tươi sống ở cảng vào sáng nay.', '{"wordId":"seafood","ukIpa":"/ˈsiːfuːd/","usIpa":"/ˈsiːfuːd/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Sea animals, especially shellfish, eaten as food.","vi":"hải sản"}],"examples":[{"en":"We bought fresh seafood at the harbour this morning.","vi":"Chúng tôi đã mua hải sản tươi sống ở cảng vào sáng nay.","audioKind":"ex"},{"en":"Demand for sustainable seafood has encouraged some fishing communities to adopt methods that cause less damage to marine ecosystems.","vi":"Nhu cầu về hải sản khai thác bền vững đã khuyến khích một số cộng đồng ngư dân áp dụng các phương pháp ít gây tổn hại hơn cho hệ sinh thái biển.","audioKind":"ex2"}],"collocations":[{"en":"fresh seafood","vi":"hải sản tươi sống"},{"en":"a seafood restaurant","vi":"nhà hàng hải sản"},{"en":"sustainable seafood","vi":"hải sản bền vững"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; một đĩa hải sản có thể dùng a plate of seafood.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tire', 'en-b1-54', 'tire', '/ˈtaɪər/', 'B1', 'làm mệt mỏi; mệt mỏi; chán ngấy; mất hứng thú; lốp xe; vỏ xe', 'v.', 'tired (adj.), tiring (adj.), tiredness (n.), tireless (adj.)', NULL, 'Động từ tire dùng chung trong cả Anh-Anh và Anh-Mỹ; riêng danh từ lốp xe viết là tyre trong tiếng Anh-Anh.', 'Long walks tire my grandfather, so we stop often.', NULL, 'Những chuyến đi bộ dài làm ông tôi mệt mỏi, nên chúng tôi dừng chân rất thường xuyên.', '{"wordId":"tire","ukIpa":"/ˈtaɪə/","usIpa":"/ˈtaɪər/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To become tired or make someone feel tired","vi":"làm mệt mỏi; mệt mỏi"},{"pos":"v.","en":"To lose interest in someone or something","vi":"chán ngấy; mất hứng thú"},{"pos":"n.","en":"A rubber covering fitted around a vehicle''s wheel","vi":"lốp xe; vỏ xe"}],"examples":[{"en":"Long walks tire my grandfather, so we stop often.","vi":"Những chuyến đi bộ dài làm ông tôi mệt mỏi, nên chúng tôi dừng chân rất thường xuyên.","audioKind":"ex"},{"en":"Students may tire of repetitive exercises unless teachers introduce varied activities that encourage active participation.","vi":"Học sinh có thể cảm thấy chán nản với các bài tập lặp đi lặp lại trừ khi giáo viên đưa ra các hoạt động đa dạng nhằm khuyến khích sự tham gia tích cực.","audioKind":"ex2"}],"collocations":[{"en":"tire easily","vi":"dễ bị mệt"},{"en":"tire of something","vi":"chán ngấy điều gì"},{"en":"a flat tire","vi":"lốp xe bị xịt"}],"wordFamily":["tired (adj.)","tiring (adj.)","tiredness (n.)","tireless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ tire dùng chung trong cả Anh-Anh và Anh-Mỹ; riêng danh từ lốp xe viết là tyre trong tiếng Anh-Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_celery', 'en-b1-54', 'celery', '/ˈseləri/', 'B1', 'cần tây', 'n.', NULL, NULL, 'Thường là danh từ không đếm được; một nhánh cần tây dùng "a stalk of celery".', 'I chopped some celery and added it to the soup.', NULL, 'Tôi đã cắt một ít cần tây và cho vào súp.', '{"wordId":"celery","ukIpa":"/ˈseləri/","usIpa":"/ˈseləri/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A vegetable with long, crisp stalks, eaten raw or cooked.","vi":"cần tây"}],"examples":[{"en":"I chopped some celery and added it to the soup.","vi":"Tôi đã cắt một ít cần tây và cho vào súp.","audioKind":"ex"},{"en":"Growing vegetables such as celery locally can reduce transport costs and provide communities with fresh produce.","vi":"Việc trồng các loại rau như cần tây tại địa phương có thể giúp giảm chi phí vận chuyển và cung cấp nông sản tươi ngon cho cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"a stalk of celery","vi":"một nhánh cần tây"},{"en":"chopped celery","vi":"cần tây cắt nhỏ"},{"en":"celery soup","vi":"súp cần tây"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; một nhánh cần tây dùng \"a stalk of celery\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_label', 'en-b1-54', 'label', '/ˈleɪbəl/', 'B1', 'nhãn; mác; dán nhãn; ghi nhãn; gắn nhãn; định tính (cho ai/cái gì)', 'n.', 'labelling (n.), labelled (adj.)', 'Đồng nghĩa: tag', 'Tiếng Anh-Anh viết là "labelled", tiếng Anh-Mỹ thường dùng "labeled".', 'Check the label before you wash your new sweater.', NULL, 'Hãy kiểm tra nhãn mác trước khi bạn giặt chiếc áo len mới.', '{"wordId":"label","ukIpa":"/ˈleɪbəl/","usIpa":"/ˈleɪbəl/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a small attached piece giving information about something","vi":"nhãn; mác"},{"pos":"v.","en":"to attach information to something for identification","vi":"dán nhãn; ghi nhãn"},{"pos":"v.","en":"to describe someone or something in a particular way","vi":"gắn nhãn; định tính (cho ai/cái gì)"}],"examples":[{"en":"Check the label before you wash your new sweater.","vi":"Hãy kiểm tra nhãn mác trước khi bạn giặt chiếc áo len mới.","audioKind":"ex"},{"en":"Schools should avoid labelling children as failures, since this can damage their confidence and motivation.","vi":"Nhà trường nên tránh gán nhãn trẻ em là những kẻ thất bại, vì điều này có thể làm tổn hại đến sự tự tin và động lực học tập của các em.","audioKind":"ex2"}],"collocations":[{"en":"read the label","vi":"đọc nhãn"},{"en":"food label","vi":"nhãn thực phẩm"},{"en":"label someone as","vi":"gắn nhãn ai đó là"}],"wordFamily":["labelling (n.)","labelled (adj.)"],"synonyms":["tag"],"antonyms":[],"tipVi":"Tiếng Anh-Anh viết là \"labelled\", tiếng Anh-Mỹ thường dùng \"labeled\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trolley', 'en-b1-54', 'trolley', '/ˈtrɑːli/', 'B1', 'xe đẩy mua sắm; xe điện chạy trên ray ở phố', 'n.', NULL, 'Đồng nghĩa: cart', 'Trong tiếng Anh-Anh, xe đẩy siêu thị gọi là "trolley", trong khi tiếng Anh-Mỹ thường dùng "shopping cart".', 'She pushed a trolley full of groceries towards the checkout.', NULL, 'Cô ấy đẩy một chiếc xe chở đầy hàng tạp hóa hướng về quầy thanh toán.', '{"wordId":"trolley","ukIpa":"/ˈtrɒli/","usIpa":"/ˈtrɑːli/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A wheeled cart used for carrying shopping or other items.","vi":"xe đẩy mua sắm"},{"pos":"n.","en":"An electric passenger vehicle that runs on rails in streets.","vi":"xe điện chạy trên ray ở phố"}],"examples":[{"en":"She pushed a trolley full of groceries towards the checkout.","vi":"Cô ấy đẩy một chiếc xe chở đầy hàng tạp hóa hướng về quầy thanh toán.","audioKind":"ex"},{"en":"Airports should provide free luggage trolleys to make travelling easier for families and older passengers.","vi":"Các sân bay nên cung cấp xe đẩy hành lý miễn phí để giúp các gia đình và hành khách lớn tuổi di chuyển dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"shopping trolley","vi":"xe đẩy mua sắm"},{"en":"luggage trolley","vi":"xe đẩy hành lý"},{"en":"push a trolley","vi":"đẩy xe đẩy"}],"wordFamily":[],"synonyms":["cart"],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, xe đẩy siêu thị gọi là \"trolley\", trong khi tiếng Anh-Mỹ thường dùng \"shopping cart\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rush', 'en-b1-54', 'rush', '/rʌʃ/', 'B1', 'vội vã; làm gấp; sự vội vã; khoảng thời gian bận rộn; luồng cảm xúc dâng trào', 'v.', 'rushed (adj.)', 'Đồng nghĩa: hurry, hasten · Trái nghĩa: dawdle', '"Rush to do" diễn tả việc vội vã làm gì đó; "rush into" diễn tả sự hành động hấp tấp, vội vàng.', 'I rushed downstairs when I heard the doorbell.', NULL, 'Tôi vội vàng chạy xuống lầu khi nghe tiếng chuông cửa.', '{"wordId":"rush","ukIpa":"/rʌʃ/","usIpa":"/rʌʃ/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to move or do something very quickly, often without care","vi":"vội vã; làm gấp"},{"pos":"n.","en":"a state of hurry or a period of intense activity","vi":"sự vội vã; khoảng thời gian bận rộn"},{"pos":"n.","en":"a sudden strong feeling or flow of something","vi":"luồng cảm xúc dâng trào"}],"examples":[{"en":"I rushed downstairs when I heard the doorbell.","vi":"Tôi vội vàng chạy xuống lầu khi nghe tiếng chuông cửa.","audioKind":"ex"},{"en":"Governments should not rush major transport projects without first assessing their environmental and financial impacts.","vi":"Chính phủ không nên vội vã thực hiện các dự án giao thông lớn mà chưa đánh giá trước tác động môi trường và tài chính của chúng.","audioKind":"ex2"}],"collocations":[{"en":"rush hour","vi":"giờ cao điểm"},{"en":"in a rush","vi":"vội vã"},{"en":"rush into a decision","vi":"vội vàng đưa ra quyết định"},{"en":"a rush of excitement","vi":"một cảm giác phấn khích dâng trào"}],"wordFamily":["rushed (adj.)"],"synonyms":["hurry","hasten"],"antonyms":["dawdle"],"tipVi":"\"Rush to do\" diễn tả việc vội vã làm gì đó; \"rush into\" diễn tả sự hành động hấp tấp, vội vàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_knit', 'en-b1-54', 'knit', '/nɪt/', 'B1', 'đan; đan len; gắn kết chặt chẽ; liền lại', 'v.', 'knitting (n.), knitted (adj.), knitter (n.)', NULL, 'k không phát âm; dạng quá khứ và quá khứ phân từ có thể dùng knitted hoặc knit.', 'My grandfather knitted a warm scarf for me.', NULL, 'Ông tôi đã đan cho tôi một chiếc khăn choàng cổ ấm áp.', '{"wordId":"knit","ukIpa":"/nɪt/","usIpa":"/nɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to make clothing or fabric by looping yarn with needles","vi":"đan; đan len"},{"pos":"v.","en":"to join closely together or heal into one piece","vi":"gắn kết chặt chẽ; liền lại"}],"examples":[{"en":"My grandfather knitted a warm scarf for me.","vi":"Ông tôi đã đan cho tôi một chiếc khăn choàng cổ ấm áp.","audioKind":"ex"},{"en":"Community groups that knit blankets for local shelters combine practical support with opportunities for social interaction.","vi":"Các nhóm cộng đồng đan chăn cho các mái ấm địa phương kết hợp sự hỗ trợ thiết thực với cơ hội giao lưu xã hội.","audioKind":"ex2"}],"collocations":[{"en":"knit a sweater","vi":"đan một chiếc áo len"},{"en":"knit together","vi":"gắn kết lại với nhau; liền sẹo"},{"en":"knit your brows","vi":"nhíu mày"}],"wordFamily":["knitting (n.)","knitted (adj.)","knitter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"k không phát âm; dạng quá khứ và quá khứ phân từ có thể dùng knitted hoặc knit.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blueberry', 'en-b1-54', 'blueberry', '/ˈbluːberi/', 'B1', 'quả việt quất', 'n.', NULL, NULL, 'Là danh từ đếm được, dạng số nhiều đổi y thành ies: blueberries.', 'A ripe blueberry rolled off my spoon onto the table.', NULL, 'Một quả việt quất chín mọng lăn từ thìa của tôi xuống bàn.', '{"wordId":"blueberry","ukIpa":"/ˈbluːbəri/","usIpa":"/ˈbluːberi/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A small, round, dark blue fruit.","vi":"quả việt quất"}],"examples":[{"en":"A ripe blueberry rolled off my spoon onto the table.","vi":"Một quả việt quất chín mọng lăn từ thìa của tôi xuống bàn.","audioKind":"ex"},{"en":"Growing blueberries locally can diversify farm income, but suitable soil conditions are essential for successful cultivation.","vi":"Trồng việt quất tại địa phương có thể làm đa dạng hóa thu nhập của trang trại, nhưng điều kiện đất đai phù hợp là yếu tố cốt lõi để canh tác thành công.","audioKind":"ex2"}],"collocations":[{"en":"fresh blueberries","vi":"việt quất tươi"},{"en":"blueberry muffin","vi":"bánh xốp việt quất"},{"en":"blueberry jam","vi":"mứt việt quất"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được, dạng số nhiều đổi y thành ies: blueberries.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spicy', 'en-b1-54', 'spicy', '/ˈspaɪsi/', 'B1', 'cay; có nhiều gia vị', 'adj.', 'spice (n.), spice (v.), spiciness (n.)', 'Đồng nghĩa: hot · Trái nghĩa: bland', 'spicy chỉ món ăn có nhiều hương vị gia vị hoặc cay nồng; hot cũng có thể dùng để chỉ độ cay hoặc nhiệt độ cao.', 'The noodles were too spicy, so I ordered rice.', NULL, 'Mì quá cay, nên tôi đã gọi cơm.', '{"wordId":"spicy","ukIpa":"/ˈspaɪsi/","usIpa":"/ˈspaɪsi/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"containing spices, often with a strong, hot flavour","vi":"cay; có nhiều gia vị"}],"examples":[{"en":"The noodles were too spicy, so I ordered rice.","vi":"Mì quá cay, nên tôi đã gọi cơm.","audioKind":"ex"},{"en":"Traditional spicy dishes can attract visitors who want to experience the distinctive flavours of a region.","vi":"Các món ăn cay truyền thống có thể thu hút du khách muốn trải nghiệm hương vị đặc trưng của một vùng miền.","audioKind":"ex2"}],"collocations":[{"en":"spicy food","vi":"thức ăn cay"},{"en":"spicy sauce","vi":"nước sốt cay"},{"en":"mildly spicy","vi":"hơi cay"}],"wordFamily":["spice (n.)","spice (v.)","spiciness (n.)"],"synonyms":["hot"],"antonyms":["bland"],"tipVi":"spicy chỉ món ăn có nhiều hương vị gia vị hoặc cay nồng; hot cũng có thể dùng để chỉ độ cay hoặc nhiệt độ cao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_54_1', 'en-b1-54', 'Cách dùng “pumpkin” (n.) — quả bí ngô', 'pumpkin soup  ·  pumpkin seeds  ·  roasted pumpkin', 'Cả quả bí ngô là danh từ đếm được; khi chỉ bí ngô như một nguyên liệu nấu ăn thì thường là danh từ không đếm được.', NULL, '[{"hanzi":"We roasted a pumpkin and served it with rice.","pinyin":"","meaning":"Chúng tôi đã nướng một quả bí ngô và ăn kèm với cơm."},{"hanzi":"Growing crops such as pumpkin in community gardens can improve access to fresh food in urban neighbourhoods.","pinyin":"","meaning":"Trồng các loại cây hoa màu như bí ngô trong các khu vườn cộng đồng có thể giúp cải thiện khả năng tiếp cận thực phẩm tươi sạch ở các khu dân cư đô thị."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_54_2', 'en-b1-54', 'Cách dùng “spicy” (adj.) — cay; có nhiều gia vị', 'spicy food  ·  spicy sauce  ·  mildly spicy', 'spicy chỉ món ăn có nhiều hương vị gia vị hoặc cay nồng; hot cũng có thể dùng để chỉ độ cay hoặc nhiệt độ cao.', 'Họ từ (Word Family): spice (n.), spice (v.), spiciness (n.) | Đồng nghĩa: hot · Trái nghĩa: bland', '[{"hanzi":"The noodles were too spicy, so I ordered rice.","pinyin":"","meaning":"Mì quá cay, nên tôi đã gọi cơm."},{"hanzi":"Traditional spicy dishes can attract visitors who want to experience the distinctive flavours of a region.","pinyin":"","meaning":"Các món ăn cay truyền thống có thể thu hút du khách muốn trải nghiệm hương vị đặc trưng của một vùng miền."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_54_3', 'en-b1-54', 'Cách dùng “tire” (v.) — làm mệt mỏi; mệt mỏi', 'tire easily  ·  tire of something  ·  a flat tire', 'Động từ tire dùng chung trong cả Anh-Anh và Anh-Mỹ; riêng danh từ lốp xe viết là tyre trong tiếng Anh-Anh.', 'Họ từ (Word Family): tired (adj.), tiring (adj.), tiredness (n.), tireless (adj.)', '[{"hanzi":"Long walks tire my grandfather, so we stop often.","pinyin":"","meaning":"Những chuyến đi bộ dài làm ông tôi mệt mỏi, nên chúng tôi dừng chân rất thường xuyên."},{"hanzi":"Students may tire of repetitive exercises unless teachers introduce varied activities that encourage active participation.","pinyin":"","meaning":"Học sinh có thể cảm thấy chán nản với các bài tập lặp đi lặp lại trừ khi giáo viên đưa ra các hoạt động đa dạng nhằm khuyến khích sự tham gia tích cực."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_54_4', 'en-b1-54', 'Cách dùng “trolley” (n.) — xe đẩy mua sắm', 'shopping trolley  ·  luggage trolley  ·  push a trolley', 'Trong tiếng Anh-Anh, xe đẩy siêu thị gọi là "trolley", trong khi tiếng Anh-Mỹ thường dùng "shopping cart".', 'Đồng nghĩa: cart', '[{"hanzi":"She pushed a trolley full of groceries towards the checkout.","pinyin":"","meaning":"Cô ấy đẩy một chiếc xe chở đầy hàng tạp hóa hướng về quầy thanh toán."},{"hanzi":"Airports should provide free luggage trolleys to make travelling easier for families and older passengers.","pinyin":"","meaning":"Các sân bay nên cung cấp xe đẩy hành lý miễn phí để giúp các gia đình và hành khách lớn tuổi di chuyển dễ dàng hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_54_1', 'en-b1-54', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_1_1', 'ten_b1_54_1', 'whenever', 'Whenever I cook soup, my cat waits beside the stove.', 'Whenever I cook soup, my cat waits beside the stove.', '/wenˈevɚ/', 'Mỗi khi tôi nấu súp, con mèo nhà tôi lại ngồi chờ bên cạnh bếp lò.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_1_2', 'ten_b1_54_1', 'reserve', 'Could you reserve a table for us tonight?', 'Could you reserve a table for us tonight?', '/rɪˈzɝːv/', 'Bạn có thể đặt trước cho chúng tôi một bàn vào tối nay không?', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_1_3', 'ten_b1_54_1', 'tag', 'I checked the tag before washing my new jumper.', 'I checked the tag before washing my new jumper.', '/tæɡ/', 'Tôi đã kiểm tra nhãn mác trước khi giặt chiếc áo len mới của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_1_4', 'ten_b1_54_1', 'stuff', 'Please move your stuff off the kitchen table.', 'Please move your stuff off the kitchen table.', '/stʌf/', 'Làm ơn dọn đồ đạc của bạn khỏi bàn bếp đi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_1_5', 'ten_b1_54_1', 'pumpkin', 'We roasted a pumpkin and served it with rice.', 'We roasted a pumpkin and served it with rice.', '/ˈpʌmpkɪn/', 'Chúng tôi đã nướng một quả bí ngô và ăn kèm với cơm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_1_6', 'ten_b1_54_1', 'gently', 'She gently lifted the kitten out of the basket.', 'She gently lifted the kitten out of the basket.', '/ˈdʒentli/', 'Cô ấy nhẹ nhàng nhấc chú mèo con ra khỏi giỏ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_1_7', 'ten_b1_54_1', 'medium-sized', 'A medium-sized suitcase should hold everything for the weekend.', 'A medium-sized suitcase should hold everything for the weekend.', '/ˌmiːdiəm ˈsaɪzd/', 'Một chiếc vali cỡ trung bình lẽ ra phải đựng vừa mọi thứ cho chuyến đi cuối tuần.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_1_8', 'ten_b1_54_1', 'blanket', 'She wrapped a soft blanket around her cold shoulders.', 'She wrapped a soft blanket around her cold shoulders.', '/ˈblæŋkɪt/', 'Cô ấy quấn một chiếc chăn mềm quanh bờ vai lạnh giá của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_54_1_1', 'en-b1-54', 'ten_b1_54_1', 'listening', 'listening', 'Whenever I cook soup, my cat waits beside the stove.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Có một mùi kỳ lạ phát ra từ tủ lạnh.","Những chuyến đi bộ dài làm ông tôi mệt mỏi, nên chúng tôi dừng chân rất thường xuyên.","Với những viên pin dự phòng đã được cất kỹ, chúng tôi đã sẵn sàng ứng phó với tình trạng mất điện.","Mỗi khi tôi nấu súp, con mèo nhà tôi lại ngồi chờ bên cạnh bếp lò."]'::jsonb, 3, 'Whenever I cook soup, my cat waits beside the stove. → Mỗi khi tôi nấu súp, con mèo nhà tôi lại ngồi chờ bên cạnh bếp lò.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_54_1_2', 'en-b1-54', 'ten_b1_54_1', 'listening', 'listening', 'Could you reserve a table for us tonight?', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn có thể đặt trước cho chúng tôi một bàn vào tối nay không?","Chúng tôi tìm kiếm chiếc đèn pin trong bóng tối hoàn toàn.","Gừng tươi là nguyên liệu chính trong món súp này.","Cô ấy đẩy một chiếc xe chở đầy hàng tạp hóa hướng về quầy thanh toán."]'::jsonb, 0, 'Could you reserve a table for us tonight? → Bạn có thể đặt trước cho chúng tôi một bàn vào tối nay không?', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_54_1_3', 'en-b1-54', 'ten_b1_54_1', 'listening', 'listening', 'I checked the tag before washing my new jumper.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã kiểm tra nhãn mác trước khi giặt chiếc áo len mới của mình.","Ông tôi đã đan cho tôi một chiếc khăn choàng cổ ấm áp.","Cô ấy quấn một chiếc chăn mềm quanh bờ vai lạnh giá của mình.","Hôm nay vé vào hồ bơi được miễn phí."]'::jsonb, 0, 'I checked the tag before washing my new jumper. → Tôi đã kiểm tra nhãn mác trước khi giặt chiếc áo len mới của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_54_2', 'en-b1-54', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_2_1', 'ten_b1_54_2', 'whenever', 'Whenever cities expand, planners should consider how new developments will affect existing communities and local wildlife.', 'Whenever cities expand, planners should consider how new developments will affect existing communities and local wildlife.', '/wenˈevɚ/', 'Bất cứ khi nào các thành phố mở rộng quy mô, các nhà quy hoạch nên xem xét các dự án phát triển mới sẽ ảnh hưởng như thế nào đến cộng đồng hiện hữu và động vật hoang dã địa phương.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_2_2', 'ten_b1_54_2', 'reserve', 'Governments should maintain adequate food reserves to protect vulnerable communities during periods of severe drought.', 'Governments should maintain adequate food reserves to protect vulnerable communities during periods of severe drought.', '/rɪˈzɝːv/', 'Các chính phủ nên duy trì lượng dự trữ lương thực đầy đủ để bảo vệ các cộng đồng dễ bị tổn thương trong thời kỳ hạn hán nghiêm trọng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_2_3', 'ten_b1_54_2', 'tag', 'Researchers tag marine animals to track their movements and identify habitats that require stronger environmental protection.', 'Researchers tag marine animals to track their movements and identify habitats that require stronger environmental protection.', '/tæɡ/', 'Các nhà nghiên cứu gắn thẻ các loài động vật biển để theo dõi hoạt động di chuyển của chúng và xác định các môi trường sống cần được bảo vệ môi trường mạnh mẽ hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_2_4', 'ten_b1_54_2', 'stuff', 'Consumers often buy stuff they rarely use, contributing to household waste and unnecessary resource consumption.', 'Consumers often buy stuff they rarely use, contributing to household waste and unnecessary resource consumption.', '/stʌf/', 'Người tiêu dùng thường mua những món đồ hiếm khi dùng đến, góp phần gây ra rác thải sinh hoạt và tiêu thụ tài nguyên không cần thiết.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_2_5', 'ten_b1_54_2', 'pumpkin', 'Growing crops such as pumpkin in community gardens can improve access to fresh food in urban neighbourhoods.', 'Growing crops such as pumpkin in community gardens can improve access to fresh food in urban neighbourhoods.', '/ˈpʌmpkɪn/', 'Trồng các loại cây hoa màu như bí ngô trong các khu vườn cộng đồng có thể giúp cải thiện khả năng tiếp cận thực phẩm tươi sạch ở các khu dân cư đô thị.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_54_2_6', 'ten_b1_54_2', 'gently', 'Health professionals should speak gently to anxious patients to help them feel comfortable during medical examinations.', 'Health professionals should speak gently to anxious patients to help them feel comfortable during medical examinations.', '/ˈdʒentli/', 'Các chuyên gia y tế nên nói chuyện nhẹ nhàng với những bệnh nhân lo lắng để giúp họ cảm thấy thoải mái trong suốt quá trình khám bệnh.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_54_2_1', 'en-b1-54', 'ten_b1_54_2', 'listening', 'listening', 'Whenever cities expand, planners should consider how new developments will affect existing communities and local wildlife.', NULL, 'Trong câu vừa nghe, từ “whenever” mang nghĩa nào sau đây?', '["ban đầu; nguyên bản","phạm vi; chuỗi; đa dạng","cứu hộ; giải cứu ai đó hoặc vật gì khỏi nguy hiểm hoặc khó khăn","mỗi khi; bất cứ khi nào"]'::jsonb, 3, '“whenever” (/wenˈevɚ/): mỗi khi; bất cứ khi nào. Câu đầy đủ: Whenever cities expand, planners should consider how new developments will affect existing communities and local wildlife.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_54_2_2', 'en-b1-54', 'ten_b1_54_2', 'listening', 'listening', 'Governments should maintain adequate food reserves to protect vulnerable communities during periods of severe drought.', NULL, 'Trong câu vừa nghe, từ “reserve” mang nghĩa nào sau đây?', '["dao cạo râu; máy cạo râu","đặt trước; giữ lại","huy hiệu; thẻ tên; biểu tượng","tài liệu phát tay; bài giảng in sẵn"]'::jsonb, 1, '“reserve” (/rɪˈzɝːv/): đặt trước; giữ lại. Câu đầy đủ: Governments should maintain adequate food reserves to protect vulnerable communities during periods of severe drought.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
