INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_4', 'en-b1-54', NULL, 'comprehensive_test', 'listening', 'Please move your stuff off the kitchen table.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Làm ơn dọn đồ đạc của bạn khỏi bàn bếp đi.","Tôi thường cảm thấy buồn ngủ sau một bữa trưa no nê.","Mỗi khi tôi nấu súp, con mèo nhà tôi lại ngồi chờ bên cạnh bếp lò.","Chúng tôi tìm kiếm chiếc đèn pin trong bóng tối hoàn toàn."]'::jsonb, 0, 'Please move your stuff off the kitchen table. → Làm ơn dọn đồ đạc của bạn khỏi bàn bếp đi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
