INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_6', 'en-b1-54', NULL, 'comprehensive_test', 'listening', 'She gently lifted the kitten out of the basket.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy dành phần lớn thời gian rảnh rỗi của mình ở ngoài vườn.","Bạn có thể đặt trước cho chúng tôi một bàn vào tối nay không?","Gừng tươi là nguyên liệu chính trong món súp này.","Cô ấy nhẹ nhàng nhấc chú mèo con ra khỏi giỏ."]'::jsonb, 3, 'She gently lifted the kitten out of the basket. → Cô ấy nhẹ nhàng nhấc chú mèo con ra khỏi giỏ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_7', 'en-b1-54', NULL, 'comprehensive_test', 'listening', 'medium-sized', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bột; bụi dạng mịn","phtin (đơn vị đo dung tích bằng khoảng nửa lít)","học kỳ","cỡ trung bình; trung cỡ"]'::jsonb, 3, 'medium-sized (/ˌmiːdiəm ˈsaɪzd/) → cỡ trung bình; trung cỡ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_8', 'en-b1-54', NULL, 'comprehensive_test', 'listening', 'She wrapped a soft blanket around her cold shoulders.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Có một mùi kỳ lạ phát ra từ tủ lạnh.","Cô ấy quấn một chiếc chăn mềm quanh bờ vai lạnh giá của mình.","Tôi đã cắt một ít cần tây và cho vào súp.","Cô ấy nhẹ nhàng nhấc chú mèo con ra khỏi giỏ."]'::jsonb, 1, 'She wrapped a soft blanket around her cold shoulders. → Cô ấy quấn một chiếc chăn mềm quanh bờ vai lạnh giá của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_9', 'en-b1-54', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A large, round fruit with thick skin, often orange.”?', '["stuff","ingredient","pumpkin","darkness"]'::jsonb, 2, 'pumpkin (/ˈpʌmpkɪn/) → quả bí ngô', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_10', 'en-b1-54', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “In a soft, careful, or kind way.”?', '["entry","ingredient","gently","ashtray"]'::jsonb, 2, 'gently (/ˈdʒentli/) → nhẹ nhàng; dịu dàng', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_11', 'en-b1-54', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “neither large nor small in size”?', '["seafood","medium-sized","spicy","reserve"]'::jsonb, 1, 'medium-sized (/ˌmiːdiəm ˈsaɪzd/) → cỡ trung bình; trung cỡ', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_12', 'en-b1-54', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A thick bed covering, or a layer covering something.”?', '["blanket","stuff","entry","require"]'::jsonb, 0, 'blanket (/ˈblæŋkɪt/) → tấm chăn; lớp phủ', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
