INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_18', 'en-b1-54', NULL, 'comprehensive_test', 'reading', NULL, 'Whenever cities expand, planners should consider how new developments will affect existing communities and local wildlife.', 'Dựa vào câu trên, từ “whenever” có nghĩa phù hợp nhất là gì?', '["mỗi khi; bất cứ khi nào","toàn cầu; mang tính thế giới","hầu như không; hầu như chẳng","nỗi buồn; sự đau buồn (cảm giác không vui, đặc biệt sau khi mất mát hoặc thất vọng)"]'::jsonb, 0, 'whenever: mỗi khi; bất cứ khi nào; bất cứ lúc nào; rốt cuộc khi nào. Dịch cả câu: Bất cứ khi nào các thành phố mở rộng quy mô, các nhà quy hoạch nên xem xét các dự án phát triển mới sẽ ảnh hưởng như thế nào đến cộng đồng hiện hữu và động vật hoang dã địa phương.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_19', 'en-b1-54', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should maintain adequate food reserves to protect vulnerable communities during periods of severe drought.', 'Dựa vào câu trên, từ “reserve” có nghĩa phù hợp nhất là gì?', '["làm tràn; làm đổ; làm rơi vãi","đặt trước; giữ lại","bài tập giữ gìn vóc dáng; thể dục giữ vóc dáng","thân mật; thoải mái; không trang trọng"]'::jsonb, 1, 'reserve: đặt trước; giữ lại; nguồn dự trữ; lượng dự trữ; khu bảo tồn thiên nhiên. Dịch cả câu: Các chính phủ nên duy trì lượng dự trữ lương thực đầy đủ để bảo vệ các cộng đồng dễ bị tổn thương trong thời kỳ hạn hán nghiêm trọng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_20', 'en-b1-54', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers tag marine animals to track their movements and identify habitats that require stronger environmental protection.', 'Dựa vào câu trên, từ “tag” có nghĩa phù hợp nhất là gì?', '["đặc điểm; nét đặc trưng","micrô; ống nói","thẻ; nhãn; mác","sự giảm giá; chiết khấu"]'::jsonb, 2, 'tag: thẻ; nhãn; mác; dán nhãn; gắn thẻ; đánh dấu; trò chơi đuổi bắt. Dịch cả câu: Các nhà nghiên cứu gắn thẻ các loài động vật biển để theo dõi hoạt động di chuyển của chúng và xác định các môi trường sống cần được bảo vệ môi trường mạnh mẽ hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_21', 'en-b1-54', NULL, 'comprehensive_test', 'reading', NULL, 'Consumers often buy stuff they rarely use, contributing to household waste and unnecessary resource consumption.', 'Dựa vào câu trên, từ “stuff” có nghĩa phù hợp nhất là gì?', '["định nghĩa; giải thích nghĩa","đồ đạc; thứ; vật dụng","vợt (thể thao)","môn thể thao chèo bè; đi bè vượt thác"]'::jsonb, 1, 'stuff: đồ đạc; thứ; vật dụng; nhồi nhét; nhét đầy. Dịch cả câu: Người tiêu dùng thường mua những món đồ hiếm khi dùng đến, góp phần gây ra rác thải sinh hoạt và tiêu thụ tài nguyên không cần thiết.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_22', 'en-b1-54', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đan; đan len”', '["knit","underwear","force","admire"]'::jsonb, 0, 'đan; đan len → knit (/nɪt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_23', 'en-b1-54', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “quả việt quất”', '["litter","effort","blueberry","intelligent"]'::jsonb, 2, 'quả việt quất → blueberry (/ˈbluːberi/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_54_24', 'en-b1-54', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cay; có nhiều gia vị”', '["canal","unfair","gently","spicy"]'::jsonb, 3, 'cay; có nhiều gia vị → spicy (/ˈspaɪsi/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-55', 'en', 'Bài 55: Đời sống hằng ngày (7) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3055, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plug', 'en-b1-55', 'plug', '/plʌɡ/', 'B1', 'phích cắm điện; nút đậy; nút bít; bịt kín; trám', 'n.', 'unplug (v.)', NULL, 'Phích cắm là plug, ổ cắm là socket; plug in chỉ hành động cắm điện.', 'Pull the plug out before you clean the toaster.', NULL, 'Hãy rút phích cắm ra trước khi bạn vệ sinh lò nướng bánh mì.', '{"wordId":"plug","ukIpa":"/plʌɡ/","usIpa":"/plʌɡ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A device connecting electrical equipment to a power socket.","vi":"phích cắm điện"},{"pos":"n.","en":"An object fitted into a hole to stop liquid escaping.","vi":"nút đậy; nút bít"},{"pos":"v.","en":"To fill or block a hole or gap.","vi":"bịt kín; trám"}],"examples":[{"en":"Pull the plug out before you clean the toaster.","vi":"Hãy rút phích cắm ra trước khi bạn vệ sinh lò nướng bánh mì.","audioKind":"ex"},{"en":"Households can reduce some unnecessary electricity consumption by removing plugs from sockets when appliances are not in use.","vi":"Các hộ gia đình có thể giảm bớt một phần lượng điện tiêu thụ không cần thiết bằng cách rút phích cắm ra khỏi ổ cắm khi các thiết bị không được sử dụng.","audioKind":"ex2"}],"collocations":[{"en":"pull out the plug","vi":"rút phích cắm"},{"en":"plug something in","vi":"cắm điện thiết bị nào đó"},{"en":"bath plug","vi":"nút bồn tắm"},{"en":"plug a gap","vi":"lấp đầy khoảng trống"}],"wordFamily":["unplug (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Phích cắm là plug, ổ cắm là socket; plug in chỉ hành động cắm điện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plain', 'en-b1-55', 'plain', '/pleɪn/', 'B1', 'đơn giản, không có trang trí hoặc hoa văn; rõ ràng, dễ thấy hoặc dễ hiểu; vùng đất phẳng rộng lớn, đồng bằng', 'adj.', 'plainly (adv.), plainness (n.)', 'Đồng nghĩa: simple, obvious · Trái nghĩa: decorated, unclear', 'plain có thể chỉ đồ vật không có hoa văn; đồng bằng dùng danh từ plain.', 'She chose a plain white shirt for the interview.', NULL, 'Cô ấy chọn một chiếc áo sơ mi trắng đơn giản để đi phỏng vấn.', '{"wordId":"plain","ukIpa":"/pleɪn/","usIpa":"/pleɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"simple, without decoration or a pattern","vi":"đơn giản, không có trang trí hoặc hoa văn"},{"pos":"adj.","en":"easy to see or understand","vi":"rõ ràng, dễ thấy hoặc dễ hiểu"},{"pos":"n.","en":"a large area of flat land","vi":"vùng đất phẳng rộng lớn, đồng bằng"}],"examples":[{"en":"She chose a plain white shirt for the interview.","vi":"Cô ấy chọn một chiếc áo sơ mi trắng đơn giản để đi phỏng vấn.","audioKind":"ex"},{"en":"Public health advice should use plain language so that everyone can understand essential information.","vi":"Lời khuyên về y tế công cộng nên sử dụng ngôn ngữ dễ hiểu để mọi người đều có thể nắm bắt được thông tin cốt lõi.","audioKind":"ex2"}],"collocations":[{"en":"plain clothes","vi":"thường phục"},{"en":"plain language","vi":"ngôn ngữ dễ hiểu"},{"en":"a coastal plain","vi":"đồng bằng ven biển"}],"wordFamily":["plainly (adv.)","plainness (n.)"],"synonyms":["simple","obvious"],"antonyms":["decorated","unclear"],"tipVi":"plain có thể chỉ đồ vật không có hoa văn; đồng bằng dùng danh từ plain.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_despite', 'en-b1-55', 'despite', '/dɪˈspaɪt/', 'B1', 'mặc dù; dẫu cho', 'prep.', NULL, 'Đồng nghĩa: in spite of, notwithstanding', 'theo sau là danh từ hoặc danh động từ, không đi kèm of; khi đi với mệnh đề, dùng the fact that.', 'We enjoyed our walk despite the cold wind.', NULL, 'Chúng tôi vẫn tận hưởng buổi đi dạo mặc cho cơn gió lạnh buốt.', '{"wordId":"despite","ukIpa":"/dɪˈspaɪt/","usIpa":"/dɪˈspaɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"prep.","en":"Without being prevented or affected by something.","vi":"mặc dù; dẫu cho"}],"examples":[{"en":"We enjoyed our walk despite the cold wind.","vi":"Chúng tôi vẫn tận hưởng buổi đi dạo mặc cho cơn gió lạnh buốt.","audioKind":"ex"},{"en":"Despite significant investment in public transport, many commuters still prefer driving because services remain unreliable.","vi":"Mặc dù đã đầu tư đáng kể vào giao thông công cộng, nhiều người đi làm vẫn thích lái xe hơn vì các dịch vụ vẫn chưa đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"despite the fact that","vi":"mặc dù thực tế là"},{"en":"despite difficulties","vi":"bất chấp khó khăn"},{"en":"despite efforts","vi":"dù đã nỗ lực"}],"wordFamily":[],"synonyms":["in spite of","notwithstanding"],"antonyms":[],"tipVi":"theo sau là danh từ hoặc danh động từ, không đi kèm of; khi đi với mệnh đề, dùng the fact that.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interrupt', 'en-b1-55', 'interrupt', '/ˌɪntəˈrʌpt/', 'B1', 'ngắt lời; làm gián đoạn; làm phiền; làm đình trệ', 'v.', 'interruption (n.), uninterrupted (adj.)', NULL, 'interrupt chỉ việc ngắt quãng giữa chừng; disrupt nhấn mạnh việc gây rối loạn tiến trình bình thường.', 'Please don''t interrupt me while I explain the rules.', NULL, 'Xin đừng ngắt lời tôi khi tôi đang giải thích các quy tắc.', '{"wordId":"interrupt","ukIpa":"/ˌɪntəˈrʌpt/","usIpa":"/ˌɪntəˈrʌpt/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to stop someone speaking or working by doing something","vi":"ngắt lời; làm gián đoạn; làm phiền"},{"pos":"v.","en":"to stop an activity or process for a time","vi":"làm gián đoạn; làm đình trệ"}],"examples":[{"en":"Please don''t interrupt me while I explain the rules.","vi":"Xin đừng ngắt lời tôi khi tôi đang giải thích các quy tắc.","audioKind":"ex"},{"en":"Frequent phone notifications can interrupt students'' concentration and reduce the amount they learn during independent study.","vi":"Thông báo điện thoại liên tục có thể làm gián đoạn sự tập trung của học sinh và làm giảm lượng kiến thức các em thu nhận được trong giờ tự học.","audioKind":"ex2"}],"collocations":[{"en":"interrupt a conversation","vi":"cắt ngang cuộc trò chuyện"},{"en":"interrupt someone","vi":"ngắt lời ai đó"},{"en":"interrupt the flow","vi":"làm gián đoạn dòng chảy"}],"wordFamily":["interruption (n.)","uninterrupted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"interrupt chỉ việc ngắt quãng giữa chừng; disrupt nhấn mạnh việc gây rối loạn tiến trình bình thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bite', 'en-b1-55', 'bite', '/baɪt/', 'B1', 'cắn; ngoạm; đốt; cú cắn; vết cắn; vết đốt; một miếng (thức ăn)', 'v.', 'biting (adj.)', NULL, 'Quá khứ là bit, quá khứ phân từ là bitten; một miếng dùng a bite.', 'She bit into the apple and smiled at its sweetness.', NULL, 'Cô ấy cắn một miếng táo và mỉm cười vì vị ngọt của nó.', '{"wordId":"bite","ukIpa":"/baɪt/","usIpa":"/baɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To cut or grip with teeth, or wound with mouthparts","vi":"cắn; ngoạm; đốt"},{"pos":"n.","en":"An act of biting, its wound, or a mouthful of food","vi":"cú cắn; vết cắn; vết đốt; một miếng (thức ăn)"}],"examples":[{"en":"She bit into the apple and smiled at its sweetness.","vi":"Cô ấy cắn một miếng táo và mỉm cười vì vị ngọt của nó.","audioKind":"ex"},{"en":"Public health campaigns should explain how travellers can prevent mosquito bites in regions with tropical diseases.","vi":"Các chiến dịch y tế công cộng nên giải thích cách khách du lịch có thể phòng tránh muỗi đốt ở những vùng có bệnh nhiệt đới.","audioKind":"ex2"}],"collocations":[{"en":"take a bite","vi":"cắn một miếng"},{"en":"bite into an apple","vi":"cắn vào quả táo"},{"en":"mosquito bite","vi":"muỗi đốt"}],"wordFamily":["biting (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ là bit, quá khứ phân từ là bitten; một miếng dùng a bite.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_instant', 'en-b1-55', 'instant', '/ˈɪnstənt/', 'B1', 'ngay lập tức; tức thì; sử dụng ngay; ăn liền; pha nhanh; khoảnh khắc; chớp mắt', 'adj.', 'instantly (adv.), instantaneous (adj.)', 'Đồng nghĩa: immediate · Trái nghĩa: delayed', 'instant làm tính từ nghĩa là ngay lập tức; in an instant nghĩa là trong chớp mắt.', 'The warm soup brought instant comfort after our walk.', NULL, 'Bát súp ấm mang lại sự dễ chịu tức thì sau buổi đi dạo của chúng tôi.', '{"wordId":"instant","ukIpa":"/ˈɪnstənt/","usIpa":"/ˈɪnstənt/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"happening immediately, without any delay","vi":"ngay lập tức; tức thì"},{"pos":"adj.","en":"prepared very quickly, usually by adding hot water","vi":"sử dụng ngay; ăn liền; pha nhanh"},{"pos":"n.","en":"an extremely short period of time","vi":"khoảnh khắc; chớp mắt"}],"examples":[{"en":"The warm soup brought instant comfort after our walk.","vi":"Bát súp ấm mang lại sự dễ chịu tức thì sau buổi đi dạo của chúng tôi.","audioKind":"ex"},{"en":"Digital platforms provide instant access to educational resources, although reliable internet connections remain essential.","vi":"Các nền tảng kỹ thuật số cung cấp khả năng tiếp cận tức thì với các nguồn tài nguyên giáo dục, mặc dù kết nối internet ổn định vẫn là điều cốt yếu.","audioKind":"ex2"}],"collocations":[{"en":"instant access","vi":"khả năng truy cập tức thì"},{"en":"instant results","vi":"kết quả tức thì"},{"en":"instant coffee","vi":"cà phê hòa tan"},{"en":"in an instant","vi":"trong chớp mắt"}],"wordFamily":["instantly (adv.)","instantaneous (adj.)"],"synonyms":["immediate"],"antonyms":["delayed"],"tipVi":"instant làm tính từ nghĩa là ngay lập tức; in an instant nghĩa là trong chớp mắt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_complain', 'en-b1-55', 'complain', '/kəmˈpleɪn/', 'B1', 'phàn nàn; khiếu nại', 'v.', 'complaint (n.), complainant (n.)', 'Đồng nghĩa: grumble', 'Cấu trúc phàn nàn với ai về điều gì: complain to sb about sth.', 'Our neighbours often complain about noise from the traffic.', NULL, 'Hàng xóm của chúng tôi thường phàn nàn về tiếng ồn từ giao thông.', '{"wordId":"complain","ukIpa":"/kəmˈpleɪn/","usIpa":"/kəmˈpleɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To say that something is wrong or unsatisfactory","vi":"phàn nàn; khiếu nại"}],"examples":[{"en":"Our neighbours often complain about noise from the traffic.","vi":"Hàng xóm của chúng tôi thường phàn nàn về tiếng ồn từ giao thông.","audioKind":"ex"},{"en":"Residents may complain to local authorities when construction work repeatedly disrupts their sleep and daily activities.","vi":"Cư dân có thể khiếu nại với chính quyền địa phương khi công trình xây dựng liên tục làm gián đoạn giấc ngủ và các hoạt động hàng ngày của họ.","audioKind":"ex2"}],"collocations":[{"en":"complain about noise","vi":"phàn nàn về tiếng ồn"},{"en":"complain to the manager","vi":"khiếu nại với quản lý"},{"en":"complain of pain","vi":"than đau"}],"wordFamily":["complaint (n.)","complainant (n.)"],"synonyms":["grumble"],"antonyms":[],"tipVi":"Cấu trúc phàn nàn với ai về điều gì: complain to sb about sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_react', 'en-b1-55', 'react', '/riˈækt/', 'B1', 'phản ứng; ứng phó; có thái độ; phản ứng hóa học', 'v.', 'reaction (n.), reactive (adj.), reactivity (n.)', 'Đồng nghĩa: respond', 'Đối với một việc gì đó dùng react to; phản ứng với chất dùng react with.', 'How did your sister react to the surprise party?', NULL, 'Chị của bạn đã phản ứng thế nào trước bữa tiệc bất ngờ?', '{"wordId":"react","ukIpa":"/riˈækt/","usIpa":"/riˈækt/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Behave or feel in response to something that happens.","vi":"phản ứng; ứng phó; có thái độ"},{"pos":"v.","en":"Change chemically when combined with another substance.","vi":"phản ứng hóa học"}],"examples":[{"en":"How did your sister react to the surprise party?","vi":"Chị của bạn đã phản ứng thế nào trước bữa tiệc bất ngờ?","audioKind":"ex"},{"en":"Governments must react quickly to public health emergencies while providing clear information to citizens.","vi":"Chính phủ phải phản ứng nhanh chóng đối với các trường hợp khẩn cấp về y tế công cộng đồng thời cung cấp thông tin rõ ràng cho người dân.","audioKind":"ex2"}],"collocations":[{"en":"react to news","vi":"phản ứng trước tin tức"},{"en":"react quickly","vi":"phản ứng nhanh"},{"en":"react with oxygen","vi":"tác dụng với oxy"}],"wordFamily":["reaction (n.)","reactive (adj.)","reactivity (n.)"],"synonyms":["respond"],"antonyms":[],"tipVi":"Đối với một việc gì đó dùng react to; phản ứng với chất dùng react with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hook', 'en-b1-55', 'hook', '/hʊk/', 'B1', 'cái móc; móc treo; móc; câu (bằng móc)', 'n.', 'hooked (adj.)', NULL, 'be hooked on có nghĩa là "say mê", không chỉ việc móc thực tế.', 'Hang your wet coat on the hook by the door.', NULL, 'Hãy treo chiếc áo khoác ướt của bạn lên cái móc cạnh cửa.', '{"wordId":"hook","ukIpa":"/hʊk/","usIpa":"/hʊk/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A curved object used for hanging, holding or catching things.","vi":"cái móc; móc treo"},{"pos":"v.","en":"To attach or catch something with a hook.","vi":"móc; câu (bằng móc)"}],"examples":[{"en":"Hang your wet coat on the hook by the door.","vi":"Hãy treo chiếc áo khoác ướt của bạn lên cái móc cạnh cửa.","audioKind":"ex"},{"en":"Installing a simple hook beside each desk can keep school bags off classroom floors and reduce accidents.","vi":"Việc lắp đặt một chiếc móc đơn giản bên cạnh mỗi bàn học có thể giúp cặp sách không bị để dưới sàn lớp học và giảm thiểu tai nạn.","audioKind":"ex2"}],"collocations":[{"en":"coat hook","vi":"móc treo áo khoác"},{"en":"fishing hook","vi":"lưỡi câu cá"},{"en":"hook onto","vi":"móc vào..."}],"wordFamily":["hooked (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"be hooked on có nghĩa là \"say mê\", không chỉ việc móc thực tế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rough', 'en-b1-55', 'rough', '/rʌf/', 'B1', 'gồ ghề; xù xì; không bằng phẳng; thô; phác thảo; đại khái; khó khăn; giông bão; dữ dội', 'adj.', 'roughly (adv.), roughness (n.), roughen (v.)', 'Đồng nghĩa: uneven, approximate · Trái nghĩa: smooth, precise', 'rough estimate là ước tính thô/sơ bộ; âm gh trong rough phát âm là /f/.', 'The rough wooden bench scratched my bare legs.', NULL, 'Chiếc ghế gỗ xù xì đã cào vào đôi chân trần của tôi.', '{"wordId":"rough","ukIpa":"/rʌf/","usIpa":"/rʌf/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Having an uneven surface that is not smooth.","vi":"gồ ghề; xù xì; không bằng phẳng"},{"pos":"adj.","en":"Not exact, detailed, or completely finished.","vi":"thô; phác thảo; đại khái"},{"pos":"adj.","en":"Difficult to experience, or involving strong, uncontrolled movement or force.","vi":"khó khăn; giông bão; dữ dội"}],"examples":[{"en":"The rough wooden bench scratched my bare legs.","vi":"Chiếc ghế gỗ xù xì đã cào vào đôi chân trần của tôi.","audioKind":"ex"},{"en":"A rough estimate of construction costs can help local authorities decide whether a housing project is affordable.","vi":"Việc ước tính sơ bộ chi phí xây dựng có thể giúp cơ quan chức năng địa phương quyết định xem một dự án nhà ở có phù hợp túi tiền hay không.","audioKind":"ex2"}],"collocations":[{"en":"a rough surface","vi":"bề mặt gồ ghề"},{"en":"a rough estimate","vi":"ước tính sơ bộ"},{"en":"a rough time","vi":"thời kỳ khó khăn"},{"en":"rough seas","vi":"vùng biển động"}],"wordFamily":["roughly (adv.)","roughness (n.)","roughen (v.)"],"synonyms":["uneven","approximate"],"antonyms":["smooth","precise"],"tipVi":"rough estimate là ước tính thô/sơ bộ; âm gh trong rough phát âm là /f/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meanwhile', 'en-b1-55', 'meanwhile', '/ˈmiːnwaɪl/', 'B1', 'trong lúc đó; đồng thời; trong khi đó', 'adv.', NULL, 'Đồng nghĩa: in the meantime', 'Khi nối hai câu hoàn chỉnh, phía trước cần dùng dấu chấm hoặc dấu chấm phẩy.', 'The soup is simmering; meanwhile, I will prepare dessert.', NULL, 'Món súp đang được ninh; trong lúc đó, tôi sẽ chuẩn bị món tráng miệng.', '{"wordId":"meanwhile","ukIpa":"/ˈmiːnwaɪl/","usIpa":"/ˈmiːnwaɪl/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"During the same time or while something else is happening.","vi":"trong lúc đó; đồng thời; trong khi đó"}],"examples":[{"en":"The soup is simmering; meanwhile, I will prepare dessert.","vi":"Món súp đang được ninh; trong lúc đó, tôi sẽ chuẩn bị món tráng miệng.","audioKind":"ex"},{"en":"New railway lines may take years to complete; meanwhile, cities should improve existing bus services.","vi":"Các tuyến đường sắt mới có thể mất nhiều năm để hoàn thành; trong khi đó, các thành phố nên cải thiện các dịch vụ xe buýt hiện có.","audioKind":"ex2"}],"collocations":[{"en":"in the meanwhile","vi":"trong thời gian này"},{"en":"meanwhile, elsewhere","vi":"trong khi đó, ở một nơi khác"}],"wordFamily":[],"synonyms":["in the meantime"],"antonyms":[],"tipVi":"Khi nối hai câu hoàn chỉnh, phía trước cần dùng dấu chấm hoặc dấu chấm phẩy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_altogether', 'en-b1-55', 'altogether', '/ˌɔːltəˈɡeðɚ/', 'B1', 'hoàn toàn; trọn vẹn; tổng cộng; nói chung; xét cho cùng', 'adv.', NULL, NULL, 'Altogether nghĩa là hoàn toàn hoặc tổng cộng; trong khi all together nghĩa là tất cả cùng một lúc hoặc ở cùng nhau.', 'We stopped going to that crowded café altogether.', NULL, 'Chúng tôi đã hoàn toàn ngừng đến quán cà phê đông đúc đó.', '{"wordId":"altogether","ukIpa":"/ˌɔːltəˈɡeðə/","usIpa":"/ˌɔːltəˈɡeðɚ/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"completely or entirely","vi":"hoàn toàn; trọn vẹn"},{"pos":"adv.","en":"when everything or everyone is counted","vi":"tổng cộng"},{"pos":"adv.","en":"when considering everything","vi":"nói chung; xét cho cùng"}],"examples":[{"en":"We stopped going to that crowded café altogether.","vi":"Chúng tôi đã hoàn toàn ngừng đến quán cà phê đông đúc đó.","audioKind":"ex"},{"en":"Although online courses improve access, they cannot altogether replace the social benefits of classroom learning.","vi":"Mặc dù các khóa học trực tuyến giúp nâng cao khả năng tiếp cận, nhưng chúng không thể hoàn toàn thay thế những lợi ích xã hội của việc học trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"altogether different","vi":"hoàn toàn khác biệt"},{"en":"not altogether clear","vi":"không hoàn toàn rõ ràng"},{"en":"disappear altogether","vi":"biến mất hoàn toàn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Altogether nghĩa là hoàn toàn hoặc tổng cộng; trong khi all together nghĩa là tất cả cùng một lúc hoặc ở cùng nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mainly', 'en-b1-55', 'mainly', '/ˈmeɪnli/', 'B1', 'chủ yếu là; phần lớn', 'adv.', 'main (adj.)', 'Đồng nghĩa: primarily, chiefly, mostly', 'Diễn đạt ý "chủ yếu chứ không phải là toàn bộ"; thường đứng trước động từ thường.', 'This little shop mainly sells fresh bread and cakes.', NULL, 'Cửa hàng nhỏ này chủ yếu bán bánh mì tươi và bánh ngọt.', '{"wordId":"mainly","ukIpa":"/ˈmeɪnli/","usIpa":"/ˈmeɪnli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"mostly, or more than anything else","vi":"chủ yếu là; phần lớn"}],"examples":[{"en":"This little shop mainly sells fresh bread and cakes.","vi":"Cửa hàng nhỏ này chủ yếu bán bánh mì tươi và bánh ngọt.","audioKind":"ex"},{"en":"Many rural communities depend mainly on agriculture, making them particularly vulnerable to changes in weather patterns.","vi":"Nhiều cộng đồng nông thôn chủ yếu phụ thuộc vào nông nghiệp, khiến họ đặc biệt dễ bị tổn thương trước những thay đổi của thời tiết.","audioKind":"ex2"}],"collocations":[{"en":"mainly because","vi":"chủ yếu là vì"},{"en":"mainly due to","vi":"chủ yếu do"},{"en":"consist mainly of","vi":"chủ yếu bao gồm"},{"en":"depend mainly on","vi":"chủ yếu dựa vào"}],"wordFamily":["main (adj.)"],"synonyms":["primarily","chiefly","mostly"],"antonyms":[],"tipVi":"Diễn đạt ý \"chủ yếu chứ không phải là toàn bộ\"; thường đứng trước động từ thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_saucer', 'en-b1-55', 'saucer', '/ˈsɔːsər/', 'B1', 'cái đĩa lót tách; đĩa đựng chén trà', 'n.', NULL, NULL, 'Saucer là chiếc đĩa nhỏ đặt dưới tách; flying saucer có nghĩa là đĩa bay.', 'She placed a biscuit on the saucer beside her cup.', NULL, 'Cô ấy đặt một chiếc bánh quy lên chiếc đĩa lót cạnh tách trà của mình.', '{"wordId":"saucer","ukIpa":"/ˈsɔːsə/","usIpa":"/ˈsɔːsər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a small shallow dish placed underneath a cup","vi":"cái đĩa lót tách; đĩa đựng chén trà"}],"examples":[{"en":"She placed a biscuit on the saucer beside her cup.","vi":"Cô ấy đặt một chiếc bánh quy lên chiếc đĩa lót cạnh tách trà của mình.","audioKind":"ex"},{"en":"Traditional tea sets, including matching cups and saucers, can reflect local craftsmanship and cultural preferences.","vi":"Các bộ ấm chén truyền thống, bao gồm cả tách và đĩa lót đồng bộ, có thể phản ánh tay nghề thủ công và gu thẩm mỹ của địa phương.","audioKind":"ex2"}],"collocations":[{"en":"cup and saucer","vi":"tách và đĩa lót"},{"en":"matching saucer","vi":"đĩa lót đồng bộ"},{"en":"flying saucer","vi":"đĩa bay"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Saucer là chiếc đĩa nhỏ đặt dưới tách; flying saucer có nghĩa là đĩa bay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sink', 'en-b1-55', 'sink', '/sɪŋk/', 'B1', 'chìm xuống; làm chìm; chậu rửa; bồn rửa mặt/bát; suy giảm; rơi vào', 'v.', 'sinking (adj.), sunken (adj.)', 'Đồng nghĩa: submerge · Trái nghĩa: float, rise', 'Các dạng bất quy tắc của từ này: sink—sank—sunk.', 'The little toy boat sank beneath the bathwater.', NULL, 'Con thuyền đồ chơi nhỏ chìm nghỉm xuống dưới làn nước bồn tắm.', '{"wordId":"sink","ukIpa":"/sɪŋk/","usIpa":"/sɪŋk/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To move below a surface, or make something do this.","vi":"chìm xuống; làm chìm"},{"pos":"n.","en":"A fixed basin with taps and a drain for washing.","vi":"chậu rửa; bồn rửa mặt/bát"},{"pos":"v.","en":"To fall to a lower level or become weaker.","vi":"suy giảm; rơi vào"}],"examples":[{"en":"The little toy boat sank beneath the bathwater.","vi":"Con thuyền đồ chơi nhỏ chìm nghỉm xuống dưới làn nước bồn tắm.","audioKind":"ex"},{"en":"Coastal communities face increasing risks as land sinks and sea levels rise because of climate change.","vi":"Các cộng đồng ven biển phải đối mặt với rủi ro ngày càng tăng khi đất sụt lún và mực nước biển dâng cao do biến đổi khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"sink to the bottom","vi":"chìm xuống đáy"},{"en":"kitchen sink","vi":"bồn rửa bát"},{"en":"sink into debt","vi":"lâm vào cảnh nợ nần"}],"wordFamily":["sinking (adj.)","sunken (adj.)"],"synonyms":["submerge"],"antonyms":["float","rise"],"tipVi":"Các dạng bất quy tắc của từ này: sink—sank—sunk.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chase', 'en-b1-55', 'chase', '/tʃeɪs/', 'B1', 'đuổi theo, rượt đuổi ai đó để bắt; nỗ lực hết sức để đạt được điều mình muốn, theo đuổi; cuộc đuổi bắt, cuộc truy đuổi', 'v.', 'chaser (n.)', 'Đồng nghĩa: pursue', 'Động từ chase có thể đi thẳng với đối tượng bị đuổi theo hoặc dùng kèm với giới từ after.', 'Our puppy chased a leaf across the garden.', NULL, 'Chú chó con của chúng tôi đuổi theo một chiếc lá chạy khắp khu vườn.', '{"wordId":"chase","ukIpa":"/tʃeɪs/","usIpa":"/tʃeɪs/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to run or move after someone to catch them","vi":"đuổi theo, rượt đuổi ai đó để bắt"},{"pos":"v.","en":"to try hard to obtain something you want","vi":"nỗ lực hết sức để đạt được điều mình muốn, theo đuổi"},{"pos":"n.","en":"an attempt to catch someone by following them","vi":"cuộc đuổi bắt, cuộc truy đuổi"}],"examples":[{"en":"Our puppy chased a leaf across the garden.","vi":"Chú chó con của chúng tôi đuổi theo một chiếc lá chạy khắp khu vườn.","audioKind":"ex"},{"en":"Many young professionals chase higher salaries rather than seek work that offers lasting satisfaction.","vi":"Nhiều chuyên gia trẻ tuổi chạy theo mức lương cao hơn là tìm kiếm công việc mang lại sự thỏa mãn lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"chase after someone","vi":"đuổi theo ai đó"},{"en":"chase a dream","vi":"theo đuổi một giấc mơ"},{"en":"a high-speed chase","vi":"cuộc rượt đuổi tốc độ cao"}],"wordFamily":["chaser (n.)"],"synonyms":["pursue"],"antonyms":[],"tipVi":"Động từ chase có thể đi thẳng với đối tượng bị đuổi theo hoặc dùng kèm với giới từ after.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_width', 'en-b1-55', 'width', '/wɪdθ/', 'B1', 'chiều rộng; bề ngang', 'n.', 'wide (adj.), widen (v.), widely (adv.)', 'Đồng nghĩa: breadth', 'Tính từ wide, danh từ width, động từ widen.', 'Check the width of the sofa before buying it.', NULL, 'Hãy kiểm tra chiều rộng của chiếc ghế sofa trước khi mua nó.', '{"wordId":"width","ukIpa":"/wɪdθ/","usIpa":"/wɪdθ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The distance from one side of something to the other.","vi":"chiều rộng; bề ngang"}],"examples":[{"en":"Check the width of the sofa before buying it.","vi":"Hãy kiểm tra chiều rộng của chiếc ghế sofa trước khi mua nó.","audioKind":"ex"},{"en":"Increasing the width of pavements can improve accessibility for wheelchair users and make walking more comfortable.","vi":"Việc mở rộng chiều rộng của vỉa hè có thể cải thiện khả năng tiếp cận cho người đi xe lăn và giúp việc đi bộ trở nên thoải mái hơn.","audioKind":"ex2"}],"collocations":[{"en":"measure the width","vi":"đo chiều rộng"},{"en":"in width","vi":"về chiều rộng"},{"en":"full width","vi":"toàn bộ chiều rộng"}],"wordFamily":["wide (adj.)","widen (v.)","widely (adv.)"],"synonyms":["breadth"],"antonyms":[],"tipVi":"Tính từ wide, danh từ width, động từ widen.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_incredibly', 'en-b1-55', 'incredibly', '/ɪnˈkredəbli/', 'B1', 'cực kỳ; vô cùng; đến mức khó tin; một cách đáng kinh ngạc', 'adv.', 'incredible (adj.), credibility (n.), credible (adj.)', 'Đồng nghĩa: extremely, remarkably', 'Thường bổ nghĩa cho tính từ hoặc phó từ; đứng đầu câu có thể biểu thị ý nghĩa "đáng kinh ngạc là".', 'The soup was incredibly hot, so I waited.', NULL, 'Bát súp cực kỳ nóng, nên tôi đã đợi một lúc.', '{"wordId":"incredibly","ukIpa":"/ɪnˈkredəbli/","usIpa":"/ɪnˈkredəbli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"To an extremely high degree.","vi":"cực kỳ; vô cùng"},{"pos":"adv.","en":"In a way that is surprising or hard to believe.","vi":"đến mức khó tin; một cách đáng kinh ngạc"}],"examples":[{"en":"The soup was incredibly hot, so I waited.","vi":"Bát súp cực kỳ nóng, nên tôi đã đợi một lúc.","audioKind":"ex"},{"en":"Reliable public transport can be incredibly valuable to older residents who no longer drive.","vi":"Giao thông công cộng đáng tin cậy có thể vô cùng có giá trị đối với những cư dân lớn tuổi không còn lái xe.","audioKind":"ex2"}],"collocations":[{"en":"incredibly difficult","vi":"cực kỳ khó khăn"},{"en":"incredibly useful","vi":"vô cùng hữu ích"},{"en":"incredibly fast","vi":"nhanh đến kinh ngạc"}],"wordFamily":["incredible (adj.)","credibility (n.)","credible (adj.)"],"synonyms":["extremely","remarkably"],"antonyms":[],"tipVi":"Thường bổ nghĩa cho tính từ hoặc phó từ; đứng đầu câu có thể biểu thị ý nghĩa \"đáng kinh ngạc là\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perfume', 'en-b1-55', 'perfume', '/ˈpɜːrfjuːm/', 'B1', 'nước hoa; hương thơm; mùi thơm (đặc biệt từ hoa); làm cho thơm; xức nước hoa', 'n.', 'perfumed (adj.), perfumery (n.), perfumer (n.)', 'Đồng nghĩa: fragrance, scent', 'Diễn tả việc xức nước hoa trên người thường dùng wear perfume, không dùng put perfume.', 'She sprayed a little perfume on her wrist.', NULL, 'Cô ấy xịt một ít nước hoa lên cổ tay.', '{"wordId":"perfume","ukIpa":"/ˈpɜːfjuːm/","usIpa":"/ˈpɜːrfjuːm/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A pleasant-smelling liquid applied to the body.","vi":"nước hoa"},{"pos":"n.","en":"A pleasant smell, especially from flowers.","vi":"hương thơm; mùi thơm (đặc biệt từ hoa)"},{"pos":"v.","en":"To give something a pleasant smell.","vi":"làm cho thơm; xức nước hoa"}],"examples":[{"en":"She sprayed a little perfume on her wrist.","vi":"Cô ấy xịt một ít nước hoa lên cổ tay.","audioKind":"ex"},{"en":"Some workplaces discourage employees from wearing perfume because strong fragrances can cause discomfort for sensitive colleagues.","vi":"Một số nơi làm việc không khuyến khích nhân viên dùng nước hoa vì mùi hương nồng có thể gây khó chịu cho các đồng nghiệp nhạy cảm.","audioKind":"ex2"}],"collocations":[{"en":"wear perfume","vi":"dùng nước hoa"},{"en":"a bottle of perfume","vi":"một lọ nước hoa"},{"en":"the perfume of flowers","vi":"hương thơm của các loài hoa"}],"wordFamily":["perfumed (adj.)","perfumery (n.)","perfumer (n.)"],"synonyms":["fragrance","scent"],"antonyms":[],"tipVi":"Diễn tả việc xức nước hoa trên người thường dùng wear perfume, không dùng put perfume.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swing', 'en-b1-55', 'swing', '/swɪŋ/', 'B1', 'đu đưa; lắc lư; dao động; cái xích đu; sự thay đổi rõ rệt; sự chuyển biến', 'v.', NULL, NULL, 'Quá khứ và phân từ hai đều là swung; không dùng swinged.', 'Her bag swung gently as she walked down the street.', NULL, 'Chiếc túi của cô ấy lắc lư nhẹ nhàng khi cô ấy đi dọc con phố.', '{"wordId":"swing","ukIpa":"/swɪŋ/","usIpa":"/swɪŋ/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To move backwards and forwards or in a curved path.","vi":"đu đưa; lắc lư; dao động"},{"pos":"n.","en":"A hanging seat that moves backwards and forwards.","vi":"cái xích đu"},{"pos":"n.","en":"A noticeable change in an opinion, mood, or situation.","vi":"sự thay đổi rõ rệt; sự chuyển biến"}],"examples":[{"en":"Her bag swung gently as she walked down the street.","vi":"Chiếc túi của cô ấy lắc lư nhẹ nhàng khi cô ấy đi dọc con phố.","audioKind":"ex"},{"en":"A sharp swing in public opinion can encourage governments to reconsider policies that previously enjoyed widespread support.","vi":"Sự thay đổi đột ngột trong quan điểm công luận có thể khuyến khích các chính phủ xem xét lại các chính sách trước đây từng nhận được sự ủng hộ rộng rãi.","audioKind":"ex2"}],"collocations":[{"en":"swing back and forth","vi":"đu đưa qua lại"},{"en":"a playground swing","vi":"xích đu ở sân chơi"},{"en":"mood swings","vi":"sự dao động tâm trạng"},{"en":"a swing in public opinion","vi":"sự chuyển biến trong dư luận"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ và phân từ hai đều là swung; không dùng swinged.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_preparation', 'en-b1-55', 'preparation', '/ˌprepəˈreɪʃən/', 'B1', 'sự chuẩn bị; công tác chuẩn bị', 'n.', 'prepare (v.), prepared (adj.), preparatory (adj.)', NULL, 'Khi nói chung về sự chuẩn bị, từ này không đếm được; khi chỉ các công việc chuẩn bị cụ thể, thường dùng dạng số nhiều "preparations".', 'Dinner preparation takes longer when the children help.', NULL, 'Việc chuẩn bị bữa tối mất nhiều thời gian hơn khi có bọn trẻ giúp sức.', '{"wordId":"preparation","ukIpa":"/ˌprepəˈreɪʃən/","usIpa":"/ˌprepəˈreɪʃən/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The work done to get ready for something.","vi":"sự chuẩn bị; công tác chuẩn bị"}],"examples":[{"en":"Dinner preparation takes longer when the children help.","vi":"Việc chuẩn bị bữa tối mất nhiều thời gian hơn khi có bọn trẻ giúp sức.","audioKind":"ex"},{"en":"Thorough preparation for job interviews can help graduates communicate their skills and experience more confidently.","vi":"Sự chuẩn bị kỹ lưỡng cho các buổi phỏng vấn xin việc có thể giúp sinh viên tốt nghiệp truyền đạt kỹ năng và kinh nghiệm của mình một cách tự tin hơn.","audioKind":"ex2"}],"collocations":[{"en":"in preparation for","vi":"để chuẩn bị cho"},{"en":"make preparations","vi":"tiến hành chuẩn bị"},{"en":"food preparation","vi":"việc chuẩn bị thức ăn"},{"en":"thorough preparation","vi":"sự chuẩn bị kỹ lưỡng"}],"wordFamily":["prepare (v.)","prepared (adj.)","preparatory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nói chung về sự chuẩn bị, từ này không đếm được; khi chỉ các công việc chuẩn bị cụ thể, thường dùng dạng số nhiều \"preparations\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alarm', 'en-b1-55', 'alarm', '/əˈlɑːrm/', 'B1', 'tiếng báo động; thiết bị báo động; đồng hồ báo thức; sự hoảng sợ; sự lo lắng; làm cho ai đó sợ hãi; làm lo lắng', 'n.', 'alarming (adj.), alarmed (adj.)', NULL, 'Báo động kêu lên dùng go off, không dùng go on.', 'My alarm rang before sunrise, waking the whole family.', NULL, 'Đồng hồ báo thức của tôi reo trước khi mặt trời mọc, đánh thức cả nhà dậy.', '{"wordId":"alarm","ukIpa":"/əˈlɑːm/","usIpa":"/əˈlɑːrm/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A warning signal or device, or something that wakes you.","vi":"tiếng báo động; thiết bị báo động; đồng hồ báo thức"},{"pos":"n.","en":"A sudden feeling of fear or worry.","vi":"sự hoảng sợ; sự lo lắng"},{"pos":"v.","en":"To make someone frightened or worried.","vi":"làm cho ai đó sợ hãi; làm lo lắng"}],"examples":[{"en":"My alarm rang before sunrise, waking the whole family.","vi":"Đồng hồ báo thức của tôi reo trước khi mặt trời mọc, đánh thức cả nhà dậy.","audioKind":"ex"},{"en":"Every school should test its fire alarm regularly to ensure that pupils receive an immediate warning.","vi":"Mỗi trường học nên kiểm tra chuông báo cháy thường xuyên để đảm bảo học sinh nhận được cảnh báo ngay lập tức.","audioKind":"ex2"}],"collocations":[{"en":"set an alarm","vi":"cài đặt báo thức"},{"en":"fire alarm","vi":"chuông báo cháy"},{"en":"raise the alarm","vi":"phát tín hiệu báo động"},{"en":"in alarm","vi":"trong sự hoảng sợ"}],"wordFamily":["alarming (adj.)","alarmed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Báo động kêu lên dùng go off, không dùng go on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dull', 'en-b1-55', 'dull', '/dʌl/', 'B1', 'nhàm chán; tẻ nhạt; âm u; xám xịt; cùn; không sắc bén', 'adj.', 'dullness (n.), dully (adv.)', 'Đồng nghĩa: boring, uninteresting · Trái nghĩa: interesting, sharp', 'Khi mô tả lưỡi dao nghĩa là "cùn", khi mô tả hoạt động nghĩa là "nhàm chán".', 'The film was so dull that I nearly fell asleep.', NULL, 'Bộ phim chán đến nỗi tôi suýt ngủ thiếp đi.', '{"wordId":"dull","ukIpa":"/dʌl/","usIpa":"/dʌl/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Not interesting or exciting.","vi":"nhàm chán; tẻ nhạt"},{"pos":"adj.","en":"Not bright or sunny.","vi":"âm u; xám xịt"},{"pos":"adj.","en":"Having an edge that does not cut easily.","vi":"cùn; không sắc bén"}],"examples":[{"en":"The film was so dull that I nearly fell asleep.","vi":"Bộ phim chán đến nỗi tôi suýt ngủ thiếp đi.","audioKind":"ex"},{"en":"Lessons can seem dull when students have few opportunities to ask questions or explore ideas independently.","vi":"Các bài học có thể trở nên tẻ nhạt khi học sinh có ít cơ hội đặt câu hỏi hoặc tự mình khám phá các ý tưởng.","audioKind":"ex2"}],"collocations":[{"en":"dull routine","vi":"công việc nhàm chán lặp đi lặp lại"},{"en":"dull weather","vi":"thời tiết âm u"},{"en":"dull blade","vi":"lưỡi dao cùn"},{"en":"dull ache","vi":"cơn đau âm ỉ"}],"wordFamily":["dullness (n.)","dully (adv.)"],"synonyms":["boring","uninteresting"],"antonyms":["interesting","sharp"],"tipVi":"Khi mô tả lưỡi dao nghĩa là \"cùn\", khi mô tả hoạt động nghĩa là \"nhàm chán\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_in-advance', 'en-b1-55', 'in advance', '/ɪn ədˈvæns/', 'B1', 'trước; sớm hơn', 'phr.', 'advance (n.), advance (v.)', 'Đồng nghĩa: beforehand, ahead of time', 'in advance có thể dùng độc lập; khi muốn nói trước một sự kiện nào đó, dùng in advance of.', 'We booked our train tickets two weeks in advance.', NULL, 'Chúng tôi đã đặt vé tàu trước hai tuần.', '{"wordId":"in-advance","ukIpa":"/ɪn ədˈvɑːns/","usIpa":"/ɪn ədˈvæns/","cefr":"B1","topic":"daily","senses":[{"pos":"phr.","en":"Before a planned event or a particular time.","vi":"trước; sớm hơn"}],"examples":[{"en":"We booked our train tickets two weeks in advance.","vi":"Chúng tôi đã đặt vé tàu trước hai tuần.","audioKind":"ex"},{"en":"Publishing consultation dates well in advance allows more residents to participate in local planning decisions.","vi":"Việc công bố sớm lịch trình tư vấn giúp nhiều cư dân tham gia vào các quyết định quy hoạch địa phương hơn.","audioKind":"ex2"}],"collocations":[{"en":"book in advance","vi":"đặt trước"},{"en":"pay in advance","vi":"trả trước"},{"en":"well in advance","vi":"từ trước; sớm"}],"wordFamily":["advance (n.)","advance (v.)"],"synonyms":["beforehand","ahead of time"],"antonyms":[],"tipVi":"in advance có thể dùng độc lập; khi muốn nói trước một sự kiện nào đó, dùng in advance of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_monthly', 'en-b1-55', 'monthly', '/ˈmʌnθli/', 'B1', 'hàng tháng; mỗi tháng một lần; tờ nguyệt san; tạp chí phát hành hàng tháng', 'adj.', 'month (n.)', NULL, 'monthly có thể đóng vai trò là cả tính từ và trạng từ.', 'My monthly bus pass fits neatly inside my wallet.', NULL, 'Thẻ xe buýt hàng tháng của tôi vừa vặn nằm gọn trong ví.', '{"wordId":"monthly","ukIpa":"/ˈmʌnθli/","usIpa":"/ˈmʌnθli/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Happening, produced, or paid once every month.","vi":"hàng tháng; mỗi tháng một lần"},{"pos":"adv.","en":"Once every month.","vi":"hàng tháng; mỗi tháng một lần"},{"pos":"n.","en":"A magazine published once every month.","vi":"tờ nguyệt san; tạp chí phát hành hàng tháng"}],"examples":[{"en":"My monthly bus pass fits neatly inside my wallet.","vi":"Thẻ xe buýt hàng tháng của tôi vừa vặn nằm gọn trong ví.","audioKind":"ex"},{"en":"Monthly payments can make essential services more affordable, but households should monitor their total spending carefully.","vi":"Việc thanh toán hàng tháng có thể giúp các dịch vụ thiết yếu trở nên dễ chi trả hơn, nhưng các hộ gia đình vẫn nên theo dõi kỹ tổng chi tiêu của mình.","audioKind":"ex2"}],"collocations":[{"en":"monthly payments","vi":"khoản thanh toán hàng tháng"},{"en":"monthly income","vi":"thu nhập hàng tháng"},{"en":"monthly subscription","vi":"gói đăng ký hàng tháng"},{"en":"meet monthly","vi":"họp hàng tháng"}],"wordFamily":["month (n.)"],"synonyms":[],"antonyms":[],"tipVi":"monthly có thể đóng vai trò là cả tính từ và trạng từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_remain', 'en-b1-55', 'remain', '/rɪˈmeɪn/', 'B1', 'vẫn là; giữ nguyên; ở lại; lưu lại; còn lại; sót lại', 'v.', 'remaining (adj.), remains (n.)', 'Đồng nghĩa: stay', 'Khi diễn tả việc duy trì một trạng thái, động từ này đi sau bởi tính từ hoặc danh từ, không dùng phó từ.', 'Please remain seated until the bus has stopped completely.', NULL, 'Xin vui lòng ngồi yên tại chỗ cho đến khi xe buýt dừng hẳn.', '{"wordId":"remain","ukIpa":"/rɪˈmeɪn/","usIpa":"/rɪˈmeɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to continue to be in the same state","vi":"vẫn là; giữ nguyên"},{"pos":"v.","en":"to stay in a place rather than leave","vi":"ở lại; lưu lại"},{"pos":"v.","en":"to still exist after other things have gone","vi":"còn lại; sót lại"}],"examples":[{"en":"Please remain seated until the bus has stopped completely.","vi":"Xin vui lòng ngồi yên tại chỗ cho đến khi xe buýt dừng hẳn.","audioKind":"ex"},{"en":"Despite improvements in public transport, private cars remain the main means of travel in many rural areas.","vi":"Mặc dù giao thông công cộng đã được cải thiện, ô tô cá nhân vẫn là phương tiện đi lại chính ở nhiều vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"remain calm","vi":"giữ sự bình tĩnh"},{"en":"remain unchanged","vi":"giữ nguyên không đổi"},{"en":"remain a challenge","vi":"vẫn là một thử thách"},{"en":"remain to be seen","vi":"vẫn còn phải chờ xem"}],"wordFamily":["remaining (adj.)","remains (n.)"],"synonyms":["stay"],"antonyms":[],"tipVi":"Khi diễn tả việc duy trì một trạng thái, động từ này đi sau bởi tính từ hoặc danh từ, không dùng phó từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vest', 'en-b1-55', 'vest', '/vest/', 'B1', 'áo lót sát nách (Anh); áo lê-ki-na, áo ghi-lê (Mỹ); trao quyền; ban quyền; trao trách nhiệm', 'n.', 'vested (adj.)', NULL, 'Từ vest theo tiếng Anh-Anh thường chỉ áo lót mặc sát người; theo tiếng Anh-Mỹ thường chỉ loại áo ghi-lê kiểu Anh.', 'I wore a cotton vest under my shirt today.', NULL, 'Hôm nay tôi mặc một chiếc áo lót bằng cotton bên trong áo sơ mi.', '{"wordId":"vest","ukIpa":"/vest/","usIpa":"/vest/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a sleeveless garment worn underneath or over other clothes","vi":"áo lót sát nách (Anh); áo lê-ki-na, áo ghi-lê (Mỹ)"},{"pos":"v.","en":"to formally give someone a right, power, or responsibility","vi":"trao quyền; ban quyền; trao trách nhiệm"}],"examples":[{"en":"I wore a cotton vest under my shirt today.","vi":"Hôm nay tôi mặc một chiếc áo lót bằng cotton bên trong áo sơ mi.","audioKind":"ex"},{"en":"The constitution vests executive authority in elected officials, who remain accountable to the public through regular elections.","vi":"Hiến pháp trao quyền hành pháp cho các quan chức do bầu cử, những người chịu trách nhiệm trước công chúng thông qua các cuộc bầu cử định kỳ.","audioKind":"ex2"}],"collocations":[{"en":"a cotton vest","vi":"một chiếc áo lót cotton"},{"en":"a bulletproof vest","vi":"áo chống đạn"},{"en":"vest power in someone","vi":"trao quyền lực cho ai đó"}],"wordFamily":["vested (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ vest theo tiếng Anh-Anh thường chỉ áo lót mặc sát người; theo tiếng Anh-Mỹ thường chỉ loại áo ghi-lê kiểu Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_55_1', 'en-b1-55', 'Cách dùng “preparation” (n.) — sự chuẩn bị; công tác chuẩn bị', 'in preparation for  ·  make preparations  ·  food preparation', 'Khi nói chung về sự chuẩn bị, từ này không đếm được; khi chỉ các công việc chuẩn bị cụ thể, thường dùng dạng số nhiều "preparations".', 'Họ từ (Word Family): prepare (v.), prepared (adj.), preparatory (adj.)', '[{"hanzi":"Dinner preparation takes longer when the children help.","pinyin":"","meaning":"Việc chuẩn bị bữa tối mất nhiều thời gian hơn khi có bọn trẻ giúp sức."},{"hanzi":"Thorough preparation for job interviews can help graduates communicate their skills and experience more confidently.","pinyin":"","meaning":"Sự chuẩn bị kỹ lưỡng cho các buổi phỏng vấn xin việc có thể giúp sinh viên tốt nghiệp truyền đạt kỹ năng và kinh nghiệm của mình một cách tự tin hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_55_2', 'en-b1-55', 'Cách dùng “altogether” (adv.) — hoàn toàn; trọn vẹn', 'altogether different  ·  not altogether clear  ·  disappear altogether', 'Altogether nghĩa là hoàn toàn hoặc tổng cộng; trong khi all together nghĩa là tất cả cùng một lúc hoặc ở cùng nhau.', NULL, '[{"hanzi":"We stopped going to that crowded café altogether.","pinyin":"","meaning":"Chúng tôi đã hoàn toàn ngừng đến quán cà phê đông đúc đó."},{"hanzi":"Although online courses improve access, they cannot altogether replace the social benefits of classroom learning.","pinyin":"","meaning":"Mặc dù các khóa học trực tuyến giúp nâng cao khả năng tiếp cận, nhưng chúng không thể hoàn toàn thay thế những lợi ích xã hội của việc học trên lớp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_55_3', 'en-b1-55', 'Cách dùng “vest” (n.) — áo lót sát nách (Anh); áo lê-ki-na, áo ghi-lê (Mỹ)', 'a cotton vest  ·  a bulletproof vest  ·  vest power in someone', 'Từ vest theo tiếng Anh-Anh thường chỉ áo lót mặc sát người; theo tiếng Anh-Mỹ thường chỉ loại áo ghi-lê kiểu Anh.', 'Họ từ (Word Family): vested (adj.)', '[{"hanzi":"I wore a cotton vest under my shirt today.","pinyin":"","meaning":"Hôm nay tôi mặc một chiếc áo lót bằng cotton bên trong áo sơ mi."},{"hanzi":"The constitution vests executive authority in elected officials, who remain accountable to the public through regular elections.","pinyin":"","meaning":"Hiến pháp trao quyền hành pháp cho các quan chức do bầu cử, những người chịu trách nhiệm trước công chúng thông qua các cuộc bầu cử định kỳ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_55_4', 'en-b1-55', 'Cách dùng “remain” (v.) — vẫn là; giữ nguyên', 'remain calm  ·  remain unchanged  ·  remain a challenge', 'Khi diễn tả việc duy trì một trạng thái, động từ này đi sau bởi tính từ hoặc danh từ, không dùng phó từ.', 'Họ từ (Word Family): remaining (adj.), remains (n.) | Đồng nghĩa: stay', '[{"hanzi":"Please remain seated until the bus has stopped completely.","pinyin":"","meaning":"Xin vui lòng ngồi yên tại chỗ cho đến khi xe buýt dừng hẳn."},{"hanzi":"Despite improvements in public transport, private cars remain the main means of travel in many rural areas.","pinyin":"","meaning":"Mặc dù giao thông công cộng đã được cải thiện, ô tô cá nhân vẫn là phương tiện đi lại chính ở nhiều vùng nông thôn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_55_1', 'en-b1-55', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
