INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_55_1_6', 'ten_b1_55_1', 'instant', 'The warm soup brought instant comfort after our walk.', 'The warm soup brought instant comfort after our walk.', '/ˈɪnstənt/', 'Bát súp ấm mang lại sự dễ chịu tức thì sau buổi đi dạo của chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_55_1_7', 'ten_b1_55_1', 'complain', 'Our neighbours often complain about noise from the traffic.', 'Our neighbours often complain about noise from the traffic.', '/kəmˈpleɪn/', 'Hàng xóm của chúng tôi thường phàn nàn về tiếng ồn từ giao thông.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_55_1_8', 'ten_b1_55_1', 'react', 'How did your sister react to the surprise party?', 'How did your sister react to the surprise party?', '/riˈækt/', 'Chị của bạn đã phản ứng thế nào trước bữa tiệc bất ngờ?', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_55_1_1', 'en-b1-55', 'ten_b1_55_1', 'listening', 'listening', 'Pull the plug out before you clean the toaster.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cửa hàng nhỏ này chủ yếu bán bánh mì tươi và bánh ngọt.","Đồng hồ báo thức của tôi reo trước khi mặt trời mọc, đánh thức cả nhà dậy.","Hãy rút phích cắm ra trước khi bạn vệ sinh lò nướng bánh mì.","Thẻ xe buýt hàng tháng của tôi vừa vặn nằm gọn trong ví."]'::jsonb, 2, 'Pull the plug out before you clean the toaster. → Hãy rút phích cắm ra trước khi bạn vệ sinh lò nướng bánh mì.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_55_1_2', 'en-b1-55', 'ten_b1_55_1', 'listening', 'listening', 'She chose a plain white shirt for the interview.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy chọn một chiếc áo sơ mi trắng đơn giản để đi phỏng vấn.","Món súp đang được ninh; trong lúc đó, tôi sẽ chuẩn bị món tráng miệng.","Cô ấy cắn một miếng táo và mỉm cười vì vị ngọt của nó.","Hàng xóm của chúng tôi thường phàn nàn về tiếng ồn từ giao thông."]'::jsonb, 0, 'She chose a plain white shirt for the interview. → Cô ấy chọn một chiếc áo sơ mi trắng đơn giản để đi phỏng vấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_55_1_3', 'en-b1-55', 'ten_b1_55_1', 'listening', 'listening', 'We enjoyed our walk despite the cold wind.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy xịt một ít nước hoa lên cổ tay.","Thẻ xe buýt hàng tháng của tôi vừa vặn nằm gọn trong ví.","Cô ấy cắn một miếng táo và mỉm cười vì vị ngọt của nó.","Chúng tôi vẫn tận hưởng buổi đi dạo mặc cho cơn gió lạnh buốt."]'::jsonb, 3, 'We enjoyed our walk despite the cold wind. → Chúng tôi vẫn tận hưởng buổi đi dạo mặc cho cơn gió lạnh buốt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_55_2', 'en-b1-55', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_55_2_1', 'ten_b1_55_2', 'plug', 'Households can reduce some unnecessary electricity consumption by removing plugs from sockets when appliances are not in use.', 'Households can reduce some unnecessary electricity consumption by removing plugs from sockets when appliances are not in use.', '/plʌɡ/', 'Các hộ gia đình có thể giảm bớt một phần lượng điện tiêu thụ không cần thiết bằng cách rút phích cắm ra khỏi ổ cắm khi các thiết bị không được sử dụng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_55_2_2', 'ten_b1_55_2', 'plain', 'Public health advice should use plain language so that everyone can understand essential information.', 'Public health advice should use plain language so that everyone can understand essential information.', '/pleɪn/', 'Lời khuyên về y tế công cộng nên sử dụng ngôn ngữ dễ hiểu để mọi người đều có thể nắm bắt được thông tin cốt lõi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_55_2_3', 'ten_b1_55_2', 'despite', 'Despite significant investment in public transport, many commuters still prefer driving because services remain unreliable.', 'Despite significant investment in public transport, many commuters still prefer driving because services remain unreliable.', '/dɪˈspaɪt/', 'Mặc dù đã đầu tư đáng kể vào giao thông công cộng, nhiều người đi làm vẫn thích lái xe hơn vì các dịch vụ vẫn chưa đáng tin cậy.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_55_2_4', 'ten_b1_55_2', 'interrupt', 'Frequent phone notifications can interrupt students'' concentration and reduce the amount they learn during independent study.', 'Frequent phone notifications can interrupt students'' concentration and reduce the amount they learn during independent study.', '/ˌɪntəˈrʌpt/', 'Thông báo điện thoại liên tục có thể làm gián đoạn sự tập trung của học sinh và làm giảm lượng kiến thức các em thu nhận được trong giờ tự học.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_55_2_5', 'ten_b1_55_2', 'bite', 'Public health campaigns should explain how travellers can prevent mosquito bites in regions with tropical diseases.', 'Public health campaigns should explain how travellers can prevent mosquito bites in regions with tropical diseases.', '/baɪt/', 'Các chiến dịch y tế công cộng nên giải thích cách khách du lịch có thể phòng tránh muỗi đốt ở những vùng có bệnh nhiệt đới.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_55_2_6', 'ten_b1_55_2', 'instant', 'Digital platforms provide instant access to educational resources, although reliable internet connections remain essential.', 'Digital platforms provide instant access to educational resources, although reliable internet connections remain essential.', '/ˈɪnstənt/', 'Các nền tảng kỹ thuật số cung cấp khả năng tiếp cận tức thì với các nguồn tài nguyên giáo dục, mặc dù kết nối internet ổn định vẫn là điều cốt yếu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_55_2_1', 'en-b1-55', 'ten_b1_55_2', 'listening', 'listening', 'Households can reduce some unnecessary electricity consumption by removing plugs from sockets when appliances are not in use.', NULL, 'Trong câu vừa nghe, từ “plug” mang nghĩa nào sau đây?', '["gọt vỏ; bóc vỏ","rác bừa bãi nơi công cộng","phích cắm điện","dịch; dịch thuật"]'::jsonb, 2, '“plug” (/plʌɡ/): phích cắm điện. Câu đầy đủ: Households can reduce some unnecessary electricity consumption by removing plugs from sockets when appliances are not in use.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_55_2_2', 'en-b1-55', 'ten_b1_55_2', 'listening', 'listening', 'Public health advice should use plain language so that everyone can understand essential information.', NULL, 'Trong câu vừa nghe, từ “plain” mang nghĩa nào sau đây?', '["kèn trôm-pét; kèn đồng","con gà tây","đơn giản, không có trang trí hoặc hoa văn","không khỏe; mệt trong người"]'::jsonb, 2, '“plain” (/pleɪn/): đơn giản, không có trang trí hoặc hoa văn. Câu đầy đủ: Public health advice should use plain language so that everyone can understand essential information.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
