INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_55_2', 'en-b1-55', NULL, 'comprehensive_test', 'listening', 'She chose a plain white shirt for the interview.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bát súp cực kỳ nóng, nên tôi đã đợi một lúc.","Hãy rút phích cắm ra trước khi bạn vệ sinh lò nướng bánh mì.","Cô ấy chọn một chiếc áo sơ mi trắng đơn giản để đi phỏng vấn.","Chiếc túi của cô ấy lắc lư nhẹ nhàng khi cô ấy đi dọc con phố."]'::jsonb, 2, 'She chose a plain white shirt for the interview. → Cô ấy chọn một chiếc áo sơ mi trắng đơn giản để đi phỏng vấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_55_3', 'en-b1-55', NULL, 'comprehensive_test', 'listening', 'despite', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thứ hai là; thứ nhì; mặt khác","cộng đồng; người dân địa phương","mặc dù; dẫu cho","săn bắn"]'::jsonb, 2, 'despite (/dɪˈspaɪt/) → mặc dù; dẫu cho', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_55_4', 'en-b1-55', NULL, 'comprehensive_test', 'listening', 'Please don''t interrupt me while I explain the rules.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xin đừng ngắt lời tôi khi tôi đang giải thích các quy tắc.","Chúng tôi đã hoàn toàn ngừng đến quán cà phê đông đúc đó.","Bộ phim chán đến nỗi tôi suýt ngủ thiếp đi.","Hãy kiểm tra chiều rộng của chiếc ghế sofa trước khi mua nó."]'::jsonb, 0, 'Please don''t interrupt me while I explain the rules. → Xin đừng ngắt lời tôi khi tôi đang giải thích các quy tắc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_55_5', 'en-b1-55', NULL, 'comprehensive_test', 'listening', 'bite', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["xứng đáng; có công","cắn; ngoạm; đốt","diễu hành; bước đều","lời phàn nàn; đơn khiếu nại; sự khiếu nại"]'::jsonb, 1, 'bite (/baɪt/) → cắn; ngoạm; đốt; cú cắn; vết cắn; vết đốt; một miếng (thức ăn)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_55_6', 'en-b1-55', NULL, 'comprehensive_test', 'listening', 'The warm soup brought instant comfort after our walk.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bát súp ấm mang lại sự dễ chịu tức thì sau buổi đi dạo của chúng tôi.","Hôm nay tôi mặc một chiếc áo lót bằng cotton bên trong áo sơ mi.","Thẻ xe buýt hàng tháng của tôi vừa vặn nằm gọn trong ví.","Món súp đang được ninh; trong lúc đó, tôi sẽ chuẩn bị món tráng miệng."]'::jsonb, 0, 'The warm soup brought instant comfort after our walk. → Bát súp ấm mang lại sự dễ chịu tức thì sau buổi đi dạo của chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
