INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_55_18', 'en-b1-55', NULL, 'comprehensive_test', 'reading', NULL, 'Households can reduce some unnecessary electricity consumption by removing plugs from sockets when appliances are not in use.', 'Dựa vào câu trên, từ “plug” có nghĩa phù hợp nhất là gì?', '["truyện; chuyện cổ tích; chuyện truyền thuyết","ngáp","phích cắm điện","nhà vô địch; quán quân"]'::jsonb, 2, 'plug: phích cắm điện; nút đậy; nút bít; bịt kín; trám. Dịch cả câu: Các hộ gia đình có thể giảm bớt một phần lượng điện tiêu thụ không cần thiết bằng cách rút phích cắm ra khỏi ổ cắm khi các thiết bị không được sử dụng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_55_19', 'en-b1-55', NULL, 'comprehensive_test', 'reading', NULL, 'Public health advice should use plain language so that everyone can understand essential information.', 'Dựa vào câu trên, từ “plain” có nghĩa phù hợp nhất là gì?', '["đơn giản, không có trang trí hoặc hoa văn","thu thập; gom lại","lễ kỷ niệm; sự kiện ăn mừng","làm bẹp dí; ép chặt vào không gian chật hẹp"]'::jsonb, 0, 'plain: đơn giản, không có trang trí hoặc hoa văn; rõ ràng, dễ thấy hoặc dễ hiểu; vùng đất phẳng rộng lớn, đồng bằng. Dịch cả câu: Lời khuyên về y tế công cộng nên sử dụng ngôn ngữ dễ hiểu để mọi người đều có thể nắm bắt được thông tin cốt lõi.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_55_20', 'en-b1-55', NULL, 'comprehensive_test', 'reading', NULL, 'Despite significant investment in public transport, many commuters still prefer driving because services remain unreliable.', 'Dựa vào câu trên, từ “despite” có nghĩa phù hợp nhất là gì?', '["giọng điệu, khẩu âm","nhận ra; hiểu rõ","người tiêu dùng","mặc dù; dẫu cho"]'::jsonb, 3, 'despite: mặc dù; dẫu cho. Dịch cả câu: Mặc dù đã đầu tư đáng kể vào giao thông công cộng, nhiều người đi làm vẫn thích lái xe hơn vì các dịch vụ vẫn chưa đáng tin cậy.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_55_21', 'en-b1-55', NULL, 'comprehensive_test', 'reading', NULL, 'Frequent phone notifications can interrupt students'' concentration and reduce the amount they learn during independent study.', 'Dựa vào câu trên, từ “interrupt” có nghĩa phù hợp nhất là gì?', '["ngắt lời; làm gián đoạn; làm phiền","giảm, làm giảm, thu nhỏ","sự hạ cánh; sự cập bến","thực tế; thực trạng"]'::jsonb, 0, 'interrupt: ngắt lời; làm gián đoạn; làm phiền; làm đình trệ. Dịch cả câu: Thông báo điện thoại liên tục có thể làm gián đoạn sự tập trung của học sinh và làm giảm lượng kiến thức các em thu nhận được trong giờ tự học.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_55_22', 'en-b1-55', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hàng tháng; mỗi tháng một lần”', '["tin","whisky","coal","monthly"]'::jsonb, 3, 'hàng tháng; mỗi tháng một lần → monthly (/ˈmʌnθli/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_55_23', 'en-b1-55', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “vẫn là; giữ nguyên”', '["otherwise","disgusting","remain","seller"]'::jsonb, 2, 'vẫn là; giữ nguyên → remain (/rɪˈmeɪn/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_55_24', 'en-b1-55', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “áo lót sát nách (Anh); áo lê-ki-na, áo ghi-lê (Mỹ)”', '["misunderstand","seafood","unfriendly","vest"]'::jsonb, 3, 'áo lót sát nách (Anh); áo lê-ki-na, áo ghi-lê (Mỹ) → vest (/vest/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-56', 'en', 'Bài 56: Đời sống hằng ngày (8) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3056, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sudden', 'en-b1-56', 'sudden', '/ˈsʌdən/', 'B1', 'đột ngột; bất ngờ', 'adj.', 'suddenly (adv.), suddenness (n.)', 'Đồng nghĩa: abrupt, unexpected · Trái nghĩa: gradual', 'Sudden là tính từ; bổ nghĩa cho hành động thường dùng trạng từ suddenly.', 'A sudden gust blew my hat into the pond.', NULL, 'Một cơn gió mạnh bất chợt thổi bay chiếc mũ của tôi xuống ao.', '{"wordId":"sudden","ukIpa":"/ˈsʌdən/","usIpa":"/ˈsʌdən/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Happening quickly and unexpectedly","vi":"đột ngột; bất ngờ"}],"examples":[{"en":"A sudden gust blew my hat into the pond.","vi":"Một cơn gió mạnh bất chợt thổi bay chiếc mũ của tôi xuống ao.","audioKind":"ex"},{"en":"A sudden rise in food prices can place considerable pressure on families with low incomes.","vi":"Giá thực phẩm tăng đột ngột có thể tạo ra áp lực đáng kể cho các gia đình có thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"a sudden change","vi":"sự thay đổi đột ngột"},{"en":"a sudden increase","vi":"sự gia tăng đột ngột"},{"en":"a sudden movement","vi":"chuyển động bất ngờ"},{"en":"all of a sudden","vi":"bỗng nhiên"}],"wordFamily":["suddenly (adv.)","suddenness (n.)"],"synonyms":["abrupt","unexpected"],"antonyms":["gradual"],"tipVi":"Sudden là tính từ; bổ nghĩa cho hành động thường dùng trạng từ suddenly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_zipper', 'en-b1-56', 'zipper', '/ˈzɪpər/', 'B1', 'khóa kéo', 'n.', 'zip (n.), zip (v.), unzip (v.)', 'Đồng nghĩa: zip', 'Zipper được dùng chủ yếu trong tiếng Anh-Mỹ, trong khi tiếng Anh-Anh thường dùng zip.', 'My jacket zipper got stuck halfway up this morning.', NULL, 'Sáng nay khóa kéo áo khoác của tôi bị kẹt ở giữa.', '{"wordId":"zipper","ukIpa":"/ˈzɪpə/","usIpa":"/ˈzɪpər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a fastener with two rows of teeth joined by sliding","vi":"khóa kéo"}],"examples":[{"en":"My jacket zipper got stuck halfway up this morning.","vi":"Sáng nay khóa kéo áo khoác của tôi bị kẹt ở giữa.","audioKind":"ex"},{"en":"Designing clothing with replaceable buttons and zippers could extend its lifespan and reduce household textile waste.","vi":"Việc thiết kế quần áo có cúc và khóa kéo thay thế được có thể kéo dài tuổi thọ của trang phục và giảm thiểu rác thải dệt may trong gia đình.","audioKind":"ex2"}],"collocations":[{"en":"a broken zipper","vi":"khóa kéo hỏng"},{"en":"close a zipper","vi":"kéo khóa lên"},{"en":"replace a zipper","vi":"thay khóa kéo"}],"wordFamily":["zip (n.)","zip (v.)","unzip (v.)"],"synonyms":["zip"],"antonyms":[],"tipVi":"Zipper được dùng chủ yếu trong tiếng Anh-Mỹ, trong khi tiếng Anh-Anh thường dùng zip.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_makeup', 'en-b1-56', 'makeup', '/ˈmeɪkʌp/', 'B1', 'mỹ phẩm; đồ trang điểm; cấu trúc; thành phần cấu tạo', 'n.', 'make up (v.)', NULL, 'Makeup là danh từ; make up là cụm động từ.', 'She removed her makeup before going to bed.', NULL, 'Cô ấy đã tẩy trang trước khi đi ngủ.', '{"wordId":"makeup","ukIpa":"/ˈmeɪkʌp/","usIpa":"/ˈmeɪkʌp/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"products applied to the face to change or improve appearance","vi":"mỹ phẩm; đồ trang điểm"},{"pos":"n.","en":"the parts or qualities that together form something","vi":"cấu trúc; thành phần cấu tạo"}],"examples":[{"en":"She removed her makeup before going to bed.","vi":"Cô ấy đã tẩy trang trước khi đi ngủ.","audioKind":"ex"},{"en":"Changes in the demographic makeup of cities can influence demand for housing, healthcare and public transport.","vi":"Sự thay đổi trong cơ cấu nhân khẩu học của các thành phố có thể ảnh hưởng đến nhu cầu về nhà ở, y tế và giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"wear makeup","vi":"đeo đồ trang điểm"},{"en":"remove makeup","vi":"tẩy trang"},{"en":"genetic makeup","vi":"cấu trúc di truyền"},{"en":"demographic makeup","vi":"cấu trúc nhân khẩu học"}],"wordFamily":["make up (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Makeup là danh từ; make up là cụm động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_various', 'en-b1-56', 'various', '/ˈveriəs/', 'B1', 'khác nhau; gồm nhiều loại khác nhau', 'adj.', 'vary (v.), variety (n.), variation (n.), varied (adj.)', 'Đồng nghĩa: different, assorted', 'Thường đi kèm với danh từ đếm được số nhiều, như various reasons.', 'We tried various dishes at the weekend market.', NULL, 'Chúng tôi đã thử nhiều món ăn khác nhau ở chợ cuối tuần.', '{"wordId":"various","ukIpa":"/ˈveəriəs/","usIpa":"/ˈveriəs/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Of several different kinds.","vi":"khác nhau; gồm nhiều loại khác nhau"}],"examples":[{"en":"We tried various dishes at the weekend market.","vi":"Chúng tôi đã thử nhiều món ăn khác nhau ở chợ cuối tuần.","audioKind":"ex"},{"en":"Schools should offer various activities to help students discover their interests and develop practical skills.","vi":"Các trường học nên cung cấp nhiều hoạt động đa dạng để giúp học sinh khám phá sở thích và phát triển kỹ năng thực tế.","audioKind":"ex2"}],"collocations":[{"en":"various reasons","vi":"nhiều lý do khác nhau"},{"en":"various types of","vi":"nhiều loại"},{"en":"various aspects","vi":"các khía cạnh khác nhau"}],"wordFamily":["vary (v.)","variety (n.)","variation (n.)","varied (adj.)"],"synonyms":["different","assorted"],"antonyms":[],"tipVi":"Thường đi kèm với danh từ đếm được số nhiều, như various reasons.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frequent', 'en-b1-56', 'frequent', '/ˈfriːkwənt/', 'B1', 'thường xuyên; hay xảy ra; thường lui tới; hay đến', 'adj.', 'frequency (n.), frequently (adv.), infrequent (adj.)', 'Đồng nghĩa: regular, repeated · Trái nghĩa: infrequent, rare', 'Tính từ (frequent) có trọng âm rơi vào âm tiết đầu; động từ (frequent) có trọng âm rơi vào âm tiết thứ hai.', 'Frequent buses make getting to the market easy.', NULL, 'Các chuyến xe buýt hoạt động thường xuyên giúp việc đi lại ra chợ trở nên dễ dàng.', '{"wordId":"frequent","ukIpa":"/ˈfriːkwənt/","usIpa":"/ˈfriːkwənt/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Happening often or at short intervals","vi":"thường xuyên; hay xảy ra"},{"pos":"v.","en":"Visit a particular place regularly","vi":"thường lui tới; hay đến"}],"examples":[{"en":"Frequent buses make getting to the market easy.","vi":"Các chuyến xe buýt hoạt động thường xuyên giúp việc đi lại ra chợ trở nên dễ dàng.","audioKind":"ex"},{"en":"Frequent changes in education policy can make it difficult for teachers to plan effective lessons.","vi":"Những thay đổi thường xuyên trong chính sách giáo dục có thể khiến giáo viên gặp khó khăn trong việc lên kế hoạch bài dạy hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"frequent visits","vi":"thường xuyên ghé thăm"},{"en":"frequent delays","vi":"thường xuyên bị chậm trễ"},{"en":"a frequent visitor","vi":"khách quen"},{"en":"frequent changes","vi":"những thay đổi liên tục"}],"wordFamily":["frequency (n.)","frequently (adv.)","infrequent (adj.)"],"synonyms":["regular","repeated"],"antonyms":["infrequent","rare"],"tipVi":"Tính từ (frequent) có trọng âm rơi vào âm tiết đầu; động từ (frequent) có trọng âm rơi vào âm tiết thứ hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_directly', 'en-b1-56', 'directly', '/dəˈrektli/', 'B1', 'trực tiếp; ngay lập tức; chẳng mấy chốc; trực diện; đúng vào vị trí', 'adv.', 'direct (adj.), direct (v.), indirect (adj.), indirectly (adv.)', 'Trái nghĩa: indirectly', 'directly có thể chỉ sự trực tiếp hoặc chỉ chính xác một vị trí nào đó.', 'Please send the photos directly to my phone.', NULL, 'Xin vui lòng gửi những bức ảnh đó trực tiếp đến điện thoại của tôi.', '{"wordId":"directly","ukIpa":"/dəˈrektli/","usIpa":"/dəˈrektli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"Without anyone or anything coming between","vi":"trực tiếp"},{"pos":"adv.","en":"Immediately or after a very short time","vi":"ngay lập tức; chẳng mấy chốc"},{"pos":"adv.","en":"Exactly in a particular position","vi":"trực diện; đúng vào vị trí"}],"examples":[{"en":"Please send the photos directly to my phone.","vi":"Xin vui lòng gửi những bức ảnh đó trực tiếp đến điện thoại của tôi.","audioKind":"ex"},{"en":"Improved public transport can directly reduce household travel costs and increase access to employment.","vi":"Cải thiện giao thông công cộng có thể trực tiếp làm giảm chi phí đi lại của các hộ gia đình và tăng cơ hội tiếp cận việc làm.","audioKind":"ex2"}],"collocations":[{"en":"directly affect","vi":"ảnh hưởng trực tiếp"},{"en":"directly responsible","vi":"chịu trách nhiệm trực tiếp"},{"en":"directly opposite","vi":"nằm ngay ở phía đối diện"},{"en":"directly above","vi":"nằm ngay phía trên"}],"wordFamily":["direct (adj.)","direct (v.)","indirect (adj.)","indirectly (adv.)"],"synonyms":[],"antonyms":["indirectly"],"tipVi":"directly có thể chỉ sự trực tiếp hoặc chỉ chính xác một vị trí nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gradually', 'en-b1-56', 'gradually', '/ˈɡrædʒuəli/', 'B1', 'dần dần; từ từ', 'adv.', 'gradual (adj.)', 'Đồng nghĩa: progressively · Trái nghĩa: suddenly, abruptly', 'Nhấn mạnh sự thay đổi diễn ra từ từ, không chỉ đơn thuần là tốc độ hành động chậm.', 'The sky gradually grew darker as we walked home.', NULL, 'Bầu trời dần tối đi khi chúng tôi đi bộ về nhà.', '{"wordId":"gradually","ukIpa":"/ˈɡrædʒuəli/","usIpa":"/ˈɡrædʒuəli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"slowly over time, rather than all at once","vi":"dần dần; từ từ"}],"examples":[{"en":"The sky gradually grew darker as we walked home.","vi":"Bầu trời dần tối đi khi chúng tôi đi bộ về nhà.","audioKind":"ex"},{"en":"Cities can gradually reduce traffic congestion by improving public transport and creating safer routes for cyclists.","vi":"Các thành phố có thể từng bước giảm thiểu tình trạng ùn tắc giao thông bằng cách cải thiện giao thông công cộng và tạo ra các tuyến đường an toàn hơn cho người đi xe đạp.","audioKind":"ex2"}],"collocations":[{"en":"gradually increase","vi":"tăng dần"},{"en":"gradually improve","vi":"cải thiện dần"},{"en":"gradually disappear","vi":"dần biến mất"}],"wordFamily":["gradual (adj.)"],"synonyms":["progressively"],"antonyms":["suddenly","abruptly"],"tipVi":"Nhấn mạnh sự thay đổi diễn ra từ từ, không chỉ đơn thuần là tốc độ hành động chậm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fireplace', 'en-b1-56', 'fireplace', '/ˈfaɪərpleɪs/', 'B1', 'lò sưởi', 'n.', NULL, NULL, 'Lò sưởi là fireplace; kệ phía trên lò sưởi thường gọi là mantelpiece.', 'We warmed our feet beside the fireplace after dinner.', NULL, 'Chúng tôi sưởi ấm đôi chân bên lò sưởi sau bữa tối.', '{"wordId":"fireplace","ukIpa":"/ˈfaɪəpleɪs/","usIpa":"/ˈfaɪərpleɪs/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A space in a wall where a fire burns.","vi":"lò sưởi"}],"examples":[{"en":"We warmed our feet beside the fireplace after dinner.","vi":"Chúng tôi sưởi ấm đôi chân bên lò sưởi sau bữa tối.","audioKind":"ex"},{"en":"Traditional homes often feature a fireplace, although modern heating systems are generally more convenient.","vi":"Các ngôi nhà truyền thống thường có lò sưởi, mặc dù hệ thống sưởi hiện đại nhìn chung tiện lợi hơn.","audioKind":"ex2"}],"collocations":[{"en":"light a fire in the fireplace","vi":"đốt lửa trong lò sưởi"},{"en":"an open fireplace","vi":"lò sưởi mở"},{"en":"a stone fireplace","vi":"lò sưởi bằng đá"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Lò sưởi là fireplace; kệ phía trên lò sưởi thường gọi là mantelpiece.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_casual', 'en-b1-56', 'casual', '/ˈkæʒuəl/', 'B1', 'thường ngày; giản dị; không trang trọng; tạm thời; không thường xuyên; bất chợt; tình cờ; không dụng tâm', 'adj.', 'casually (adv.), casualness (n.)', 'Đồng nghĩa: informal, relaxed · Trái nghĩa: formal', 'casual có thể chỉ trang phục thoải mái, hoặc công việc không cố định lâu dài.', 'You can wear casual clothes to dinner tonight.', NULL, 'Bạn có thể mặc trang phục thoải mái khi đi ăn tối tối nay.', '{"wordId":"casual","ukIpa":"/ˈkæʒuəl/","usIpa":"/ˈkæʒuəl/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"relaxed and not formal","vi":"thường ngày; giản dị; không trang trọng"},{"pos":"adj.","en":"done occasionally rather than regularly or permanently","vi":"tạm thời; không thường xuyên"},{"pos":"adj.","en":"done without much attention or serious thought","vi":"bất chợt; tình cờ; không dụng tâm"}],"examples":[{"en":"You can wear casual clothes to dinner tonight.","vi":"Bạn có thể mặc trang phục thoải mái khi đi ăn tối tối nay.","audioKind":"ex"},{"en":"Casual employment offers flexibility, but workers may lack the financial security associated with permanent jobs.","vi":"Việc làm thời vụ mang lại sự linh hoạt, nhưng người lao động có thể thiếu sự bảo đảm về tài chính giống như các công việc lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"casual clothes","vi":"trang phục thường ngày"},{"en":"casual conversation","vi":"buổi trò chuyện bình thường"},{"en":"casual work","vi":"công việc thời vụ"},{"en":"casual remark","vi":"câu nói bâng quơ"}],"wordFamily":["casually (adv.)","casualness (n.)"],"synonyms":["informal","relaxed"],"antonyms":["formal"],"tipVi":"casual có thể chỉ trang phục thoải mái, hoặc công việc không cố định lâu dài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spice', 'en-b1-56', 'spice', '/spaɪs/', 'B1', 'gia vị; nêm gia vị; làm tăng hương vị; sự thú vị; nét hấp dẫn', 'n.', 'spicy (adj.), spiced (adj.), spiciness (n.)', NULL, 'spice không nhất thiết phải có vị cay; spice up cũng có thể mang nghĩa là làm cho sinh động, thú vị hơn.', 'This warming spice gives the soup a lovely flavour.', NULL, 'Loại gia vị ấm áp này mang lại hương vị tuyệt vời cho món súp.', '{"wordId":"spice","ukIpa":"/spaɪs/","usIpa":"/spaɪs/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A plant substance used to add flavour to food.","vi":"gia vị"},{"pos":"v.","en":"To add spices to food.","vi":"nêm gia vị; làm tăng hương vị"},{"pos":"n.","en":"Something that makes an experience more interesting or exciting.","vi":"sự thú vị; nét hấp dẫn"}],"examples":[{"en":"This warming spice gives the soup a lovely flavour.","vi":"Loại gia vị ấm áp này mang lại hương vị tuyệt vời cho món súp.","audioKind":"ex"},{"en":"The historical spice trade connected distant societies and encouraged the exchange of agricultural knowledge and cooking techniques.","vi":"Thương mại gia vị lịch sử đã kết nối các xã hội xa xôi và thúc đẩy sự trao đổi kiến thức nông nghiệp cùng kỹ thuật nấu nướng.","audioKind":"ex2"}],"collocations":[{"en":"ground spices","vi":"gia vị xay"},{"en":"spice trade","vi":"thương mại gia vị"},{"en":"spice rack","vi":"kệ đựng gia vị"},{"en":"spice up","vi":"làm cho hấp dẫn hơn; thêm gia vị"}],"wordFamily":["spicy (adj.)","spiced (adj.)","spiciness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"spice không nhất thiết phải có vị cay; spice up cũng có thể mang nghĩa là làm cho sinh động, thú vị hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pretend', 'en-b1-56', 'pretend', '/prɪˈtend/', 'B1', 'giả vờ; giả bộ; giả tưởng; nhân tạo', 'v.', 'pretence (n.), pretender (n.)', 'Đồng nghĩa: feign', 'Thường dùng pretend to do hoặc pretend that, không dùng pretend doing.', 'The children pretended the sofa was a pirate ship.', NULL, 'Bọn trẻ giả vờ chiếc ghế sô-pha là một con tàu cướp biển.', '{"wordId":"pretend","ukIpa":"/prɪˈtend/","usIpa":"/prɪˈtend/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to act as though something untrue is true","vi":"giả vờ; giả bộ"},{"pos":"adj.","en":"imaginary or artificial, especially as part of children''s play","vi":"giả tưởng; nhân tạo"}],"examples":[{"en":"The children pretended the sofa was a pirate ship.","vi":"Bọn trẻ giả vờ chiếc ghế sô-pha là một con tàu cướp biển.","audioKind":"ex"},{"en":"Children who pretend to be different characters can develop empathy by exploring unfamiliar perspectives through play.","vi":"Trẻ em đóng vai các nhân vật khác nhau có thể phát triển sự đồng cảm thông qua việc khám phá các góc nhìn xa lạ trong trò chơi.","audioKind":"ex2"}],"collocations":[{"en":"pretend to be","vi":"giả vờ là"},{"en":"pretend not to notice","vi":"giả vờ không để ý"},{"en":"pretend play","vi":"trò chơi giả tưởng"}],"wordFamily":["pretence (n.)","pretender (n.)"],"synonyms":["feign"],"antonyms":[],"tipVi":"Thường dùng pretend to do hoặc pretend that, không dùng pretend doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dirt', 'en-b1-56', 'dirt', '/dɝːt/', 'B1', 'vết bẩn; bụi bẩn; đất; đất mùn', 'n.', 'dirty (adj.)', 'Đồng nghĩa: grime, soil', 'Thường là danh từ không đếm được; nghĩa chỉ ''đất'' phổ biến hơn trong tiếng Anh-Mỹ.', 'Please wipe the dirt off your shoes before entering.', NULL, 'Xin vui lòng lau sạch bụi bẩn trên giày trước khi bước vào.', '{"wordId":"dirt","ukIpa":"/dɜːt/","usIpa":"/dɝːt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Unwanted material that makes something unclean","vi":"vết bẩn; bụi bẩn"},{"pos":"n.","en":"Loose earth, especially on the ground","vi":"đất; đất mùn"}],"examples":[{"en":"Please wipe the dirt off your shoes before entering.","vi":"Xin vui lòng lau sạch bụi bẩn trên giày trước khi bước vào.","audioKind":"ex"},{"en":"Regular handwashing removes dirt and reduces the spread of infections in schools and other shared spaces.","vi":"Việc rửa tay thường xuyên giúp loại bỏ bụi bẩn và giảm sự lây lan của các bệnh truyền nhiễm ở trường học và các không gian chung khác.","audioKind":"ex2"}],"collocations":[{"en":"remove dirt","vi":"làm sạch vết bẩn"},{"en":"covered in dirt","vi":"dính đầy bụi bẩn"},{"en":"dirt road","vi":"đường đất"}],"wordFamily":["dirty (adj.)"],"synonyms":["grime","soil"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; nghĩa chỉ ''đất'' phổ biến hơn trong tiếng Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hammer', 'en-b1-56', 'hammer', '/ˈhæmɚ/', 'B1', 'cái búa; đóng búa; nện; gõ', 'n.', 'hammering (n.)', NULL, 'Động từ hammer có nghĩa là đอก búa; cụm hammer out dùng để chỉ việc thương lượng vất vả để đưa ra giải pháp.', 'She used a hammer to repair the wooden chair.', NULL, 'Cô ấy dùng búa để sửa chiếc ghế gỗ.', '{"wordId":"hammer","ukIpa":"/ˈhæmə/","usIpa":"/ˈhæmɚ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A tool with a heavy head used for hitting things","vi":"cái búa"},{"pos":"v.","en":"To hit something repeatedly, especially with a hammer","vi":"đóng búa; nện; gõ"}],"examples":[{"en":"She used a hammer to repair the wooden chair.","vi":"Cô ấy dùng búa để sửa chiếc ghế gỗ.","audioKind":"ex"},{"en":"During practical lessons, students learn to use a hammer safely while building simple wooden structures.","vi":"Trong các giờ học thực hành, học sinh học cách sử dụng búa an toàn khi tạo ra các cấu trúc gỗ đơn giản.","audioKind":"ex2"}],"collocations":[{"en":"a hammer and nails","vi":"búa và đinh"},{"en":"hammer a nail","vi":"đóng đinh bằng búa"},{"en":"hammer out an agreement","vi":"thảo luận căng thẳng để đạt được thỏa thuận"}],"wordFamily":["hammering (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ hammer có nghĩa là đอก búa; cụm hammer out dùng để chỉ việc thương lượng vất vả để đưa ra giải pháp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dust', 'en-b1-56', 'dust', '/dʌst/', 'B1', 'bụi; bụi bặm; quét bụi; phủi bụi; rắc một lớp bột mỏng', 'n.', 'dusty (adj.), duster (n.)', NULL, 'Động từ dust vừa có nghĩa là phủi bụi vừa có nghĩa là rắc bột, tùy thuộc vào tân ngữ đi kèm để phân biệt.', 'A thick layer of dust covered the old piano.', NULL, 'Một lớp bụi dày phủ kín cây đàn piano cũ.', '{"wordId":"dust","ukIpa":"/dʌst/","usIpa":"/dʌst/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Fine, dry particles that settle on surfaces or float.","vi":"bụi; bụi bặm"},{"pos":"v.","en":"To remove dust from a surface.","vi":"quét bụi; phủi bụi"},{"pos":"v.","en":"To cover something lightly with a powder.","vi":"rắc một lớp bột mỏng"}],"examples":[{"en":"A thick layer of dust covered the old piano.","vi":"Một lớp bụi dày phủ kín cây đàn piano cũ.","audioKind":"ex"},{"en":"Construction dust can reduce local air quality and cause breathing difficulties among nearby residents.","vi":"Bụi xây dựng có thể làm giảm chất lượng không khí địa phương và gây khó khăn về hô hấp cho cư dân sống gần đó.","audioKind":"ex2"}],"collocations":[{"en":"a layer of dust","vi":"một lớp bụi"},{"en":"gather dust","vi":"bám bụi; không được dùng đến"},{"en":"dust the shelves","vi":"lau bụi trên kệ"},{"en":"dust with flour","vi":"rắc bột mì lên"}],"wordFamily":["dusty (adj.)","duster (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ dust vừa có nghĩa là phủi bụi vừa có nghĩa là rắc bột, tùy thuộc vào tân ngữ đi kèm để phân biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_afterward', 'en-b1-56', 'afterward', '/ˈæftərwərd/', 'B1', 'sau đó; sau khi', 'adv.', NULL, 'Đồng nghĩa: afterwards, later · Trái nghĩa: beforehand', 'Mỹ thường dùng afterward, trong khi Anh-Anh thường dùng afterwards.', 'We watched a film and discussed the ending afterward.', NULL, 'Chúng tôi đã xem một bộ phim và bàn về đoạn kết của nó ngay sau đó.', '{"wordId":"afterward","ukIpa":"/ˈɑːftəwəd/","usIpa":"/ˈæftərwərd/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"at a later time, following an event already mentioned","vi":"sau đó; sau khi"}],"examples":[{"en":"We watched a film and discussed the ending afterward.","vi":"Chúng tôi đã xem một bộ phim và bàn về đoạn kết của nó ngay sau đó.","audioKind":"ex"},{"en":"Students who review new material shortly afterward are more likely to remember it over the long term.","vi":"Những học sinh ôn tập lại kiến thức mới ngay sau đó sẽ có nhiều khả năng ghi nhớ chúng lâu hơn về lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"shortly afterward","vi":"chẳng bao lâu sau"},{"en":"soon afterward","vi":"không lâu sau đó"},{"en":"immediately afterward","vi":"ngay sau đó"}],"wordFamily":[],"synonyms":["afterwards","later"],"antonyms":["beforehand"],"tipVi":"Mỹ thường dùng afterward, trong khi Anh-Anh thường dùng afterwards.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rather', 'en-b1-56', 'rather', '/ˈræðər/', 'B1', 'hơi; khá là; thà; thích hơn; đúng hơn là', 'adv.', NULL, 'Đồng nghĩa: quite, somewhat', 'would rather đi với động từ nguyên mẫu không to; rather than mang nghĩa "hơn là / chứ không phải là".', 'This soup is rather salty, but the bread is delicious.', NULL, 'Món súp này hơi mặn, nhưng bánh mì thì rất ngon.', '{"wordId":"rather","ukIpa":"/ˈrɑːðə/","usIpa":"/ˈræðər/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"To a noticeable degree, often more than expected.","vi":"hơi; khá là"},{"pos":"adv.","en":"Used with would to express a preference.","vi":"thà; thích hơn"},{"pos":"adv.","en":"Used to correct or make a previous statement more accurate.","vi":"đúng hơn là"}],"examples":[{"en":"This soup is rather salty, but the bread is delicious.","vi":"Món súp này hơi mặn, nhưng bánh mì thì rất ngon.","audioKind":"ex"},{"en":"Many commuters would rather cycle to work if safer routes were available throughout the city.","vi":"Nhiều người đi làm sẽ thích đạp xe đi làm hơn nếu có những tuyến đường an toàn hơn trên toàn thành phố.","audioKind":"ex2"}],"collocations":[{"en":"rather difficult","vi":"khá khó khăn"},{"en":"would rather stay","vi":"thà ở lại"},{"en":"rather than","vi":"hơn là"},{"en":"or rather","vi":"hoặc đúng hơn là"}],"wordFamily":[],"synonyms":["quite","somewhat"],"antonyms":[],"tipVi":"would rather đi với động từ nguyên mẫu không to; rather than mang nghĩa \"hơn là / chứ không phải là\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mention', 'en-b1-56', 'mention', '/ˈmenʃən/', 'B1', 'nhắc đến; đề cập; sự nhắc đến; lời đề cập', 'v.', NULL, NULL, 'Đi thẳng với nội dung được nhắc đến bằng cấu trúc mention sth, không dùng giới từ about.', 'Did you mention the broken window to the landlord?', NULL, 'Bạn đã nhắc đến chiếc cửa sổ bị hỏng với chủ nhà chưa?', '{"wordId":"mention","ukIpa":"/ˈmenʃən/","usIpa":"/ˈmenʃən/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to refer to someone or something briefly","vi":"nhắc đến; đề cập"},{"pos":"n.","en":"a brief reference to someone or something","vi":"sự nhắc đến; lời đề cập"}],"examples":[{"en":"Did you mention the broken window to the landlord?","vi":"Bạn đã nhắc đến chiếc cửa sổ bị hỏng với chủ nhà chưa?","audioKind":"ex"},{"en":"Reports on urban transport often mention congestion but overlook the needs of people with limited mobility.","vi":"Các báo cáo về giao thông đô thị thường đề cập đến tình trạng tắc nghẽn nhưng lại bỏ quên nhu cầu của những người đi lại khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"mention something to someone","vi":"nhắc đến chuyện gì với ai"},{"en":"mention that","vi":"nhắc đến việc rằng"},{"en":"make no mention of","vi":"không hề đả động đến"},{"en":"not to mention","vi":"chưa kể đến"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đi thẳng với nội dung được nhắc đến bằng cấu trúc mention sth, không dùng giới từ about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_otherwise', 'en-b1-56', 'otherwise', '/ˈʌðɚwaɪz/', 'B1', 'nếu không thì; bằng không; về mặt khác; ngoài ra; theo cách khác', 'adv.', NULL, NULL, 'khi mang nghĩa "nếu không thì", văn phong viết thường đặt dấu chấm phẩy ở phía trước.', 'Take an umbrella; otherwise, you will get wet.', NULL, 'Hãy mang theo ô; nếu không, bạn sẽ bị ướt đấy.', '{"wordId":"otherwise","ukIpa":"/ˈʌðəwaɪz/","usIpa":"/ˈʌðɚwaɪz/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"If this does not happen or is not done.","vi":"nếu không thì; bằng không"},{"pos":"adv.","en":"In all other ways apart from the one mentioned.","vi":"về mặt khác; ngoài ra"},{"pos":"adv.","en":"In a different way or with a different result.","vi":"theo cách khác"}],"examples":[{"en":"Take an umbrella; otherwise, you will get wet.","vi":"Hãy mang theo ô; nếu không, bạn sẽ bị ướt đấy.","audioKind":"ex"},{"en":"Cities must invest in reliable public transport; otherwise, more residents may choose to drive.","vi":"Các thành phố phải đầu tư vào hệ thống giao thông công cộng đáng tin cậy; nếu không, nhiều cư dân hơn có thể chọn lái xe ô tô.","audioKind":"ex2"}],"collocations":[{"en":"unless otherwise stated","vi":"trừ khi có quy định khác"},{"en":"think otherwise","vi":"có suy nghĩ khác"},{"en":"otherwise healthy","vi":"ngoài ra sức khỏe vẫn tốt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"khi mang nghĩa \"nếu không thì\", văn phong viết thường đặt dấu chấm phẩy ở phía trước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slim', 'en-b1-56', 'slim', '/slɪm/', 'B1', 'mảnh mai; thon gọn; nhỏ bé; mong manh (về số lượng hoặc cơ hội); giảm cân; làm thon gọn', 'adj.', 'slimness (n.), slimming (adj.)', 'Đồng nghĩa: slender, thin · Trái nghĩa: thick', 'Khi dùng để tả vóc dáng thường mang nghĩa khen ngợi; slim chance có nghĩa là cơ hội rất mong manh.', 'This slim lamp fits neatly on my small desk.', NULL, 'Cây đèn mảnh dẻ này vừa khít trên chiếc bàn làm việc nhỏ của tôi.', '{"wordId":"slim","ukIpa":"/slɪm/","usIpa":"/slɪm/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"having a thin, often attractive shape","vi":"mảnh mai; thon gọn"},{"pos":"adj.","en":"very small in amount or likelihood","vi":"nhỏ bé; mong manh (về số lượng hoặc cơ hội)"},{"pos":"v.","en":"to lose weight or reduce something in size","vi":"giảm cân; làm thon gọn"}],"examples":[{"en":"This slim lamp fits neatly on my small desk.","vi":"Cây đèn mảnh dẻ này vừa khít trên chiếc bàn làm việc nhỏ của tôi.","audioKind":"ex"},{"en":"Without reliable public transport, there is only a slim chance that commuters will stop driving.","vi":"Nếu không có hệ thống giao thông công cộng đáng tin cậy, cơ hội để những người đi làm từ bỏ việc lái xe là rất mong manh.","audioKind":"ex2"}],"collocations":[{"en":"a slim figure","vi":"vóc dáng mảnh mai"},{"en":"a slim chance","vi":"cơ hội mong manh"},{"en":"a slim majority","vi":"chiến thắng với thếa đa số sít sao"},{"en":"slim down","vi":"giảm cân; tinh gọn"}],"wordFamily":["slimness (n.)","slimming (adj.)"],"synonyms":["slender","thin"],"antonyms":["thick"],"tipVi":"Khi dùng để tả vóc dáng thường mang nghĩa khen ngợi; slim chance có nghĩa là cơ hội rất mong manh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_combine', 'en-b1-56', 'combine', '/kəmˈbaɪn/', 'B1', 'kết hợp; phối hợp; máy gặt đập liên hợp', 'v.', 'combination (n.), combined (adj.)', 'Đồng nghĩa: join, merge · Trái nghĩa: separate', 'Động từ nhấn trọng âm ở âm tiết sau; danh từ chỉ máy gặt đọc là /ˈkɒmbaɪn/.', 'Combine the flour and butter in a large bowl.', NULL, 'Trộn đều bột mì và bơ trong một cái bát lớn.', '{"wordId":"combine","ukIpa":"/kəmˈbaɪn/","usIpa":"/kəmˈbaɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To bring things together or join to form a whole.","vi":"kết hợp; phối hợp"},{"pos":"n.","en":"A farm machine that harvests grain and separates the seeds.","vi":"máy gặt đập liên hợp"}],"examples":[{"en":"Combine the flour and butter in a large bowl.","vi":"Trộn đều bột mì và bơ trong một cái bát lớn.","audioKind":"ex"},{"en":"Cities can combine improved public transport with safer cycling routes to reduce dependence on private cars.","vi":"Các thành phố có thể kết hợp cải thiện giao thông công cộng với các tuyến đường đạp xe an toàn hơn để giảm sự phụ thuộc vào xe hơi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"combine A with B","vi":"kết hợp A với B"},{"en":"combine efforts","vi":"hợp sức; chung tay"},{"en":"combine theory and practice","vi":"kết hợp lý thuyết và thực tiễn"}],"wordFamily":["combination (n.)","combined (adj.)"],"synonyms":["join","merge"],"antonyms":["separate"],"tipVi":"Động từ nhấn trọng âm ở âm tiết sau; danh từ chỉ máy gặt đọc là /ˈkɒmbaɪn/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ideal', 'en-b1-56', 'ideal', '/aɪˈdiːəl/', 'B1', 'lý tưởng; hoàn hảo nhất; điều lý tưởng; tiêu chuẩn lý tưởng', 'adj.', 'ideally (adv.), idealism (n.), idealist (n.), idealistic (adj.)', 'Đồng nghĩa: perfect, optimal', 'ideal for theo sau bởi danh từ hoặc danh động từ, biểu thị sự phù hợp nhất cho một mục đích nào đó.', 'This quiet corner is ideal for reading after lunch.', NULL, 'Góc nhỏ yên tĩnh này rất lý tưởng để đọc sách sau bữa trưa.', '{"wordId":"ideal","ukIpa":"/aɪˈdɪəl/","usIpa":"/aɪˈdiːəl/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"perfect or the best possible for a particular purpose","vi":"lý tưởng; hoàn hảo nhất"},{"pos":"n.","en":"a belief or standard of perfection someone aims to achieve","vi":"điều lý tưởng; tiêu chuẩn lý tưởng"}],"examples":[{"en":"This quiet corner is ideal for reading after lunch.","vi":"Góc nhỏ yên tĩnh này rất lý tưởng để đọc sách sau bữa trưa.","audioKind":"ex"},{"en":"An ideal public transport system would be affordable, reliable, and accessible to residents of all ages.","vi":"Một hệ thống giao thông công cộng lý tưởng phải có giá cả phải chăng, đáng tin cậy và thuận tiện cho cư dân ở mọi lứa tuổi.","audioKind":"ex2"}],"collocations":[{"en":"ideal for","vi":"lý tưởng cho"},{"en":"ideal conditions","vi":"điều kiện lý tưởng"},{"en":"an ideal solution","vi":"một giải pháp lý tưởng"},{"en":"live up to an ideal","vi":"đạt được tiêu chuẩn lý tưởng"}],"wordFamily":["ideally (adv.)","idealism (n.)","idealist (n.)","idealistic (adj.)"],"synonyms":["perfect","optimal"],"antonyms":[],"tipVi":"ideal for theo sau bởi danh từ hoặc danh động từ, biểu thị sự phù hợp nhất cho một mục đích nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nightgown', 'en-b1-56', 'nightgown', '/ˈnaɪtɡaʊn/', 'B1', 'váy ngủ', 'n.', NULL, 'Đồng nghĩa: nightdress', 'Chỉ trang phục ngủ dạng váy; tiếng Anh Anh cũng thường dùng nightdress và không phải là đồ ngủ rời hai mảnh.', 'She packed a cotton nightgown for her weekend trip.', NULL, 'Cô ấy đã chuẩn bị một chiếc váy ngủ bằng cotton cho chuyến đi cuối tuần.', '{"wordId":"nightgown","ukIpa":"/ˈnaɪtɡaʊn/","usIpa":"/ˈnaɪtɡaʊn/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a loose dress worn in bed, usually by women or girls","vi":"váy ngủ"}],"examples":[{"en":"She packed a cotton nightgown for her weekend trip.","vi":"Cô ấy đã chuẩn bị một chiếc váy ngủ bằng cotton cho chuyến đi cuối tuần.","audioKind":"ex"},{"en":"For patients with limited mobility, a loose nightgown can make dressing easier and improve comfort during hospital stays.","vi":"Đối với bệnh nhân đi lại khó khăn, một chiếc váy ngủ rộng rãi có thể giúp việc mặc đồ dễ dàng hơn và tăng sự thoải mái khi nằm viện.","audioKind":"ex2"}],"collocations":[{"en":"cotton nightgown","vi":"váy ngủ cotton"},{"en":"silk nightgown","vi":"váy ngủ lụa"},{"en":"loose nightgown","vi":"váy ngủ rộng rãi"}],"wordFamily":[],"synonyms":["nightdress"],"antonyms":[],"tipVi":"Chỉ trang phục ngủ dạng váy; tiếng Anh Anh cũng thường dùng nightdress và không phải là đồ ngủ rời hai mảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_powder', 'en-b1-56', 'powder', '/ˈpaʊdər/', 'B1', 'bột; bụi dạng mịn; rắc bột; thoa phấn', 'n.', 'powdery (adj.), powdered (adj.)', NULL, 'Danh từ powder thường không đếm được; dùng a spoonful of powder để chỉ một muỗng bột.', 'Stir the cocoa powder into a little warm milk.', NULL, 'Khuấy đều bột cacao vào một ít sữa ấm.', '{"wordId":"powder","ukIpa":"/ˈpaʊdə/","usIpa":"/ˈpaʊdər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A dry substance consisting of very small loose particles.","vi":"bột; bụi dạng mịn"},{"pos":"v.","en":"To put a layer of powder on something.","vi":"rắc bột; thoa phấn"}],"examples":[{"en":"Stir the cocoa powder into a little warm milk.","vi":"Khuấy đều bột cacao vào một ít sữa ấm.","audioKind":"ex"},{"en":"Some manufacturers turn surplus fruit into powder to extend its shelf life and reduce food waste.","vi":"Một số nhà sản xuất chế biến trái cây dư thừa thành dạng bột để kéo dài thời gian bảo quản và giảm lãng phí thực phẩm.","audioKind":"ex2"}],"collocations":[{"en":"washing powder","vi":"bột giặt"},{"en":"baking powder","vi":"bột nở"},{"en":"fine powder","vi":"bột mịn"},{"en":"cocoa powder","vi":"bột cacao"}],"wordFamily":["powdery (adj.)","powdered (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ powder thường không đếm được; dùng a spoonful of powder để chỉ một muỗng bột.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bucket', 'en-b1-56', 'bucket', '/ˈbʌkɪt/', 'B1', 'cái xô; một xô', 'n.', NULL, 'Đồng nghĩa: pail', 'Dùng a bucket of water để chỉ một xô nước, từ of đi kèm với vật chứa bên trong.', 'She filled a bucket with water to wash the windows.', NULL, 'Cô ấy đổ đầy nước vào xô để lau cửa sổ.', '{"wordId":"bucket","ukIpa":"/ˈbʌkɪt/","usIpa":"/ˈbʌkɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"An open container with a handle, or the amount it holds.","vi":"cái xô; một xô"}],"examples":[{"en":"She filled a bucket with water to wash the windows.","vi":"Cô ấy đổ đầy nước vào xô để lau cửa sổ.","audioKind":"ex"},{"en":"Collecting rainwater in a bucket can help households reduce the amount of drinking water used for gardening.","vi":"Việc hứng nước mưa bằng xô có thể giúp các hộ gia đình giảm lượng nước sinh hoạt dùng cho việc làm vườn.","audioKind":"ex2"}],"collocations":[{"en":"a bucket of water","vi":"một xô nước"},{"en":"fill a bucket","vi":"đổ đầy xô"},{"en":"mop and bucket","vi":"cây lau nhà và xô"}],"wordFamily":[],"synonyms":["pail"],"antonyms":[],"tipVi":"Dùng a bucket of water để chỉ một xô nước, từ of đi kèm với vật chứa bên trong.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bubble', 'en-b1-56', 'bubble', '/ˈbʌbəl/', 'B1', 'bong bóng; bọt; sủi bọt; sủi tăm; bong bóng kinh tế', 'n.', 'bubbly (adj.)', NULL, 'bubble vừa chỉ bong bóng vật lý, vừa dùng để ẩn dụ cho bong bóng giá tài sản.', 'A huge soap bubble floated gently above the garden.', NULL, 'Một bong bóng xà phòng lớn lơ lửng nhẹ nhàng phía trên khu vườn.', '{"wordId":"bubble","ukIpa":"/ˈbʌbəl/","usIpa":"/ˈbʌbəl/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a round pocket of gas inside liquid or a thin film","vi":"bong bóng; bọt"},{"pos":"v.","en":"to produce bubbles or make a sound as bubbles rise","vi":"sủi bọt; sủi tăm"},{"pos":"n.","en":"a period when asset prices rise beyond their real value","vi":"bong bóng kinh tế"}],"examples":[{"en":"A huge soap bubble floated gently above the garden.","vi":"Một bong bóng xà phòng lớn lơ lửng nhẹ nhàng phía trên khu vườn.","audioKind":"ex"},{"en":"A housing bubble can leave families with heavy debts when property prices suddenly fall.","vi":"Bong bóng bất động sản có thể khiến các gia đình gánh khoản nợ nặng nề khi giá nhà đất bất ngờ sụt giảm.","audioKind":"ex2"}],"collocations":[{"en":"soap bubble","vi":"bong bóng xà phòng"},{"en":"air bubble","vi":"bọt khí"},{"en":"housing bubble","vi":"bong bóng bất động sản"},{"en":"burst a bubble","vi":"làm vỡ bong bóng"}],"wordFamily":["bubbly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"bubble vừa chỉ bong bóng vật lý, vừa dùng để ẩn dụ cho bong bóng giá tài sản.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decorate', 'en-b1-56', 'decorate', '/ˈdekəreɪt/', 'B1', 'trang trí; bày biện; sơn tường; dán giấy dán tường', 'v.', 'decoration (n.), decorative (adj.), decorator (n.)', 'Đồng nghĩa: adorn, embellish', 'Cấu trúc decorate A with B có nghĩa là trang trí A bằng B.', 'We decorated the balcony with colourful pots and tiny lights.', NULL, 'Chúng tôi trang trí ban công bằng những chậu cây đầy màu sắc và những dải đèn nhỏ.', '{"wordId":"decorate","ukIpa":"/ˈdekəreɪt/","usIpa":"/ˈdekəreɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to make something more attractive by adding beautiful things","vi":"trang trí; bày biện"},{"pos":"v.","en":"to paint walls or cover them with wallpaper","vi":"sơn tường; dán giấy dán tường"}],"examples":[{"en":"We decorated the balcony with colourful pots and tiny lights.","vi":"Chúng tôi trang trí ban công bằng những chậu cây đầy màu sắc và những dải đèn nhỏ.","audioKind":"ex"},{"en":"Allowing students to decorate shared learning spaces may increase their sense of ownership and responsibility.","vi":"Việc cho phép học sinh trang trí không gian học tập chung có thể nâng cao ý thức làm chủ và trách nhiệm của các em.","audioKind":"ex2"}],"collocations":[{"en":"decorate with flowers","vi":"trang trí bằng hoa"},{"en":"decorate a room","vi":"trang trí phòng"},{"en":"beautifully decorated","vi":"được trang trí đẹp mắt"}],"wordFamily":["decoration (n.)","decorative (adj.)","decorator (n.)"],"synonyms":["adorn","embellish"],"antonyms":[],"tipVi":"Cấu trúc decorate A with B có nghĩa là trang trí A bằng B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stew', 'en-b1-56', 'stew', '/stuː/', 'B1', 'món hầm; thịt hầm; hầm; ninh nhừ', 'n.', 'stewed (adj.)', NULL, 'stew vừa có thể là danh từ chỉ món hầm, vừa là động từ chỉ thao tác nấu chín bằng lửa nhỏ.', 'We shared a bowl of vegetable stew after our walk.', NULL, 'Chúng tôi cùng nhau ăn một bát rau củ hầm sau buổi đi dạo.', '{"wordId":"stew","ukIpa":"/stjuː/","usIpa":"/stuː/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A dish of meat or vegetables cooked slowly in liquid.","vi":"món hầm; thịt hầm"},{"pos":"v.","en":"To cook slowly in liquid over gentle heat.","vi":"hầm; ninh nhừ"}],"examples":[{"en":"We shared a bowl of vegetable stew after our walk.","vi":"Chúng tôi cùng nhau ăn một bát rau củ hầm sau buổi đi dạo.","audioKind":"ex"},{"en":"Traditional stews can provide affordable, nutritious meals while making effective use of locally grown vegetables.","vi":"Các món hầm truyền thống vừa cung cấp bữa ăn đủ dinh dưỡng với chi phí phải chăng, vừa tận dụng hiệu quả các loại rau củ trồng tại địa phương.","audioKind":"ex2"}],"collocations":[{"en":"beef stew","vi":"món bò hầm"},{"en":"vegetable stew","vi":"món rau củ hầm"},{"en":"stew gently","vi":"hầm với lửa nhỏ"}],"wordFamily":["stewed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"stew vừa có thể là danh từ chỉ món hầm, vừa là động từ chỉ thao tác nấu chín bằng lửa nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_56_1', 'en-b1-56', 'Cách dùng “hammer” (n.) — cái búa', 'a hammer and nails  ·  hammer a nail  ·  hammer out an agreement', 'Động từ hammer có nghĩa là đอก búa; cụm hammer out dùng để chỉ việc thương lượng vất vả để đưa ra giải pháp.', 'Họ từ (Word Family): hammering (n.)', '[{"hanzi":"She used a hammer to repair the wooden chair.","pinyin":"","meaning":"Cô ấy dùng búa để sửa chiếc ghế gỗ."},{"hanzi":"During practical lessons, students learn to use a hammer safely while building simple wooden structures.","pinyin":"","meaning":"Trong các giờ học thực hành, học sinh học cách sử dụng búa an toàn khi tạo ra các cấu trúc gỗ đơn giản."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_56_2', 'en-b1-56', 'Cách dùng “nightgown” (n.) — váy ngủ', 'cotton nightgown  ·  silk nightgown  ·  loose nightgown', 'Chỉ trang phục ngủ dạng váy; tiếng Anh Anh cũng thường dùng nightdress và không phải là đồ ngủ rời hai mảnh.', 'Đồng nghĩa: nightdress', '[{"hanzi":"She packed a cotton nightgown for her weekend trip.","pinyin":"","meaning":"Cô ấy đã chuẩn bị một chiếc váy ngủ bằng cotton cho chuyến đi cuối tuần."},{"hanzi":"For patients with limited mobility, a loose nightgown can make dressing easier and improve comfort during hospital stays.","pinyin":"","meaning":"Đối với bệnh nhân đi lại khó khăn, một chiếc váy ngủ rộng rãi có thể giúp việc mặc đồ dễ dàng hơn và tăng sự thoải mái khi nằm viện."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_56_3', 'en-b1-56', 'Cách dùng “frequent” (adj.) — thường xuyên; hay xảy ra', 'frequent visits  ·  frequent delays  ·  a frequent visitor', 'Tính từ (frequent) có trọng âm rơi vào âm tiết đầu; động từ (frequent) có trọng âm rơi vào âm tiết thứ hai.', 'Họ từ (Word Family): frequency (n.), frequently (adv.), infrequent (adj.) | Đồng nghĩa: regular, repeated · Trái nghĩa: infrequent, rare', '[{"hanzi":"Frequent buses make getting to the market easy.","pinyin":"","meaning":"Các chuyến xe buýt hoạt động thường xuyên giúp việc đi lại ra chợ trở nên dễ dàng."},{"hanzi":"Frequent changes in education policy can make it difficult for teachers to plan effective lessons.","pinyin":"","meaning":"Những thay đổi thường xuyên trong chính sách giáo dục có thể khiến giáo viên gặp khó khăn trong việc lên kế hoạch bài dạy hiệu quả."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_56_4', 'en-b1-56', 'Cách dùng “dust” (n.) — bụi; bụi bặm', 'a layer of dust  ·  gather dust  ·  dust the shelves', 'Động từ dust vừa có nghĩa là phủi bụi vừa có nghĩa là rắc bột, tùy thuộc vào tân ngữ đi kèm để phân biệt.', 'Họ từ (Word Family): dusty (adj.), duster (n.)', '[{"hanzi":"A thick layer of dust covered the old piano.","pinyin":"","meaning":"Một lớp bụi dày phủ kín cây đàn piano cũ."},{"hanzi":"Construction dust can reduce local air quality and cause breathing difficulties among nearby residents.","pinyin":"","meaning":"Bụi xây dựng có thể làm giảm chất lượng không khí địa phương và gây khó khăn về hô hấp cho cư dân sống gần đó."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_56_1', 'en-b1-56', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_1_1', 'ten_b1_56_1', 'sudden', 'A sudden gust blew my hat into the pond.', 'A sudden gust blew my hat into the pond.', '/ˈsʌdən/', 'Một cơn gió mạnh bất chợt thổi bay chiếc mũ của tôi xuống ao.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_1_2', 'ten_b1_56_1', 'zipper', 'My jacket zipper got stuck halfway up this morning.', 'My jacket zipper got stuck halfway up this morning.', '/ˈzɪpər/', 'Sáng nay khóa kéo áo khoác của tôi bị kẹt ở giữa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_1_3', 'ten_b1_56_1', 'makeup', 'She removed her makeup before going to bed.', 'She removed her makeup before going to bed.', '/ˈmeɪkʌp/', 'Cô ấy đã tẩy trang trước khi đi ngủ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_1_4', 'ten_b1_56_1', 'various', 'We tried various dishes at the weekend market.', 'We tried various dishes at the weekend market.', '/ˈveriəs/', 'Chúng tôi đã thử nhiều món ăn khác nhau ở chợ cuối tuần.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_1_5', 'ten_b1_56_1', 'frequent', 'Frequent buses make getting to the market easy.', 'Frequent buses make getting to the market easy.', '/ˈfriːkwənt/', 'Các chuyến xe buýt hoạt động thường xuyên giúp việc đi lại ra chợ trở nên dễ dàng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_1_6', 'ten_b1_56_1', 'directly', 'Please send the photos directly to my phone.', 'Please send the photos directly to my phone.', '/dəˈrektli/', 'Xin vui lòng gửi những bức ảnh đó trực tiếp đến điện thoại của tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_1_7', 'ten_b1_56_1', 'gradually', 'The sky gradually grew darker as we walked home.', 'The sky gradually grew darker as we walked home.', '/ˈɡrædʒuəli/', 'Bầu trời dần tối đi khi chúng tôi đi bộ về nhà.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_1_8', 'ten_b1_56_1', 'fireplace', 'We warmed our feet beside the fireplace after dinner.', 'We warmed our feet beside the fireplace after dinner.', '/ˈfaɪərpleɪs/', 'Chúng tôi sưởi ấm đôi chân bên lò sưởi sau bữa tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_56_1_1', 'en-b1-56', 'ten_b1_56_1', 'listening', 'listening', 'A sudden gust blew my hat into the pond.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hãy mang theo ô; nếu không, bạn sẽ bị ướt đấy.","Xin vui lòng gửi những bức ảnh đó trực tiếp đến điện thoại của tôi.","Bầu trời dần tối đi khi chúng tôi đi bộ về nhà.","Một cơn gió mạnh bất chợt thổi bay chiếc mũ của tôi xuống ao."]'::jsonb, 3, 'A sudden gust blew my hat into the pond. → Một cơn gió mạnh bất chợt thổi bay chiếc mũ của tôi xuống ao.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_56_1_2', 'en-b1-56', 'ten_b1_56_1', 'listening', 'listening', 'My jacket zipper got stuck halfway up this morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một lớp bụi dày phủ kín cây đàn piano cũ.","Sáng nay khóa kéo áo khoác của tôi bị kẹt ở giữa.","Chúng tôi đã thử nhiều món ăn khác nhau ở chợ cuối tuần.","Một bong bóng xà phòng lớn lơ lửng nhẹ nhàng phía trên khu vườn."]'::jsonb, 1, 'My jacket zipper got stuck halfway up this morning. → Sáng nay khóa kéo áo khoác của tôi bị kẹt ở giữa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_56_1_3', 'en-b1-56', 'ten_b1_56_1', 'listening', 'listening', 'She removed her makeup before going to bed.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi trang trí ban công bằng những chậu cây đầy màu sắc và những dải đèn nhỏ.","Bọn trẻ giả vờ chiếc ghế sô-pha là một con tàu cướp biển.","Chúng tôi sưởi ấm đôi chân bên lò sưởi sau bữa tối.","Cô ấy đã tẩy trang trước khi đi ngủ."]'::jsonb, 3, 'She removed her makeup before going to bed. → Cô ấy đã tẩy trang trước khi đi ngủ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_56_2', 'en-b1-56', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_2_1', 'ten_b1_56_2', 'sudden', 'A sudden rise in food prices can place considerable pressure on families with low incomes.', 'A sudden rise in food prices can place considerable pressure on families with low incomes.', '/ˈsʌdən/', 'Giá thực phẩm tăng đột ngột có thể tạo ra áp lực đáng kể cho các gia đình có thu nhập thấp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_2_2', 'ten_b1_56_2', 'zipper', 'Designing clothing with replaceable buttons and zippers could extend its lifespan and reduce household textile waste.', 'Designing clothing with replaceable buttons and zippers could extend its lifespan and reduce household textile waste.', '/ˈzɪpər/', 'Việc thiết kế quần áo có cúc và khóa kéo thay thế được có thể kéo dài tuổi thọ của trang phục và giảm thiểu rác thải dệt may trong gia đình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_2_3', 'ten_b1_56_2', 'makeup', 'Changes in the demographic makeup of cities can influence demand for housing, healthcare and public transport.', 'Changes in the demographic makeup of cities can influence demand for housing, healthcare and public transport.', '/ˈmeɪkʌp/', 'Sự thay đổi trong cơ cấu nhân khẩu học của các thành phố có thể ảnh hưởng đến nhu cầu về nhà ở, y tế và giao thông công cộng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_2_4', 'ten_b1_56_2', 'various', 'Schools should offer various activities to help students discover their interests and develop practical skills.', 'Schools should offer various activities to help students discover their interests and develop practical skills.', '/ˈveriəs/', 'Các trường học nên cung cấp nhiều hoạt động đa dạng để giúp học sinh khám phá sở thích và phát triển kỹ năng thực tế.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_2_5', 'ten_b1_56_2', 'frequent', 'Frequent changes in education policy can make it difficult for teachers to plan effective lessons.', 'Frequent changes in education policy can make it difficult for teachers to plan effective lessons.', '/ˈfriːkwənt/', 'Những thay đổi thường xuyên trong chính sách giáo dục có thể khiến giáo viên gặp khó khăn trong việc lên kế hoạch bài dạy hiệu quả.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_56_2_6', 'ten_b1_56_2', 'directly', 'Improved public transport can directly reduce household travel costs and increase access to employment.', 'Improved public transport can directly reduce household travel costs and increase access to employment.', '/dəˈrektli/', 'Cải thiện giao thông công cộng có thể trực tiếp làm giảm chi phí đi lại của các hộ gia đình và tăng cơ hội tiếp cận việc làm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_56_2_1', 'en-b1-56', 'ten_b1_56_2', 'listening', 'listening', 'A sudden rise in food prices can place considerable pressure on families with low incomes.', NULL, 'Trong câu vừa nghe, từ “sudden” mang nghĩa nào sau đây?', '["chủ yếu; quan trọng hàng đầu; chính","hội đồng; ủy ban","đột ngột; bất ngờ","khăn giấy; giấy ăn"]'::jsonb, 2, '“sudden” (/ˈsʌdən/): đột ngột; bất ngờ. Câu đầy đủ: A sudden rise in food prices can place considerable pressure on families with low incomes.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_56_2_2', 'en-b1-56', 'ten_b1_56_2', 'listening', 'listening', 'Designing clothing with replaceable buttons and zippers could extend its lifespan and reduce household textile waste.', NULL, 'Trong câu vừa nghe, từ “zipper” mang nghĩa nào sau đây?', '["khẩn cấp; cấp bách","vắng mặt; không có ở nơi được mong đợi","hoạt động buôn bán, giao thương hàng hóa hoặc dịch vụ","khóa kéo"]'::jsonb, 3, '“zipper” (/ˈzɪpər/): khóa kéo. Câu đầy đủ: Designing clothing with replaceable buttons and zippers could extend its lifespan and reduce household textile waste.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
