INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_56_7', 'en-b1-56', 'The sky gradually grew darker as we walked home', 'Bầu trời dần tối đi khi chúng tôi đi bộ về nhà.', 'gradually /ˈɡrædʒuəli/', '["grew","home","darker","gradually","we","as","The","sky","walked"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_56_8', 'en-b1-56', 'We warmed our feet beside the fireplace after dinner', 'Chúng tôi sưởi ấm đôi chân bên lò sưởi sau bữa tối.', 'fireplace /ˈfaɪərpleɪs/', '["the","after","We","feet","dinner","beside","our","warmed","fireplace"]'::jsonb, NULL, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
