INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_56_1', 'en-b1-56', NULL, 'comprehensive_test', 'listening', 'sudden', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thông báo; lời công bố","đột ngột; bất ngờ","người mua; khách hàng","bìa cứng; giấy các-tông"]'::jsonb, 1, 'sudden (/ˈsʌdən/) → đột ngột; bất ngờ', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_56_2', 'en-b1-56', NULL, 'comprehensive_test', 'listening', 'My jacket zipper got stuck halfway up this morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một lớp bụi dày phủ kín cây đàn piano cũ.","Cây đèn mảnh dẻ này vừa khít trên chiếc bàn làm việc nhỏ của tôi.","Sáng nay khóa kéo áo khoác của tôi bị kẹt ở giữa.","Một bong bóng xà phòng lớn lơ lửng nhẹ nhàng phía trên khu vườn."]'::jsonb, 2, 'My jacket zipper got stuck halfway up this morning. → Sáng nay khóa kéo áo khoác của tôi bị kẹt ở giữa.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_56_3', 'en-b1-56', NULL, 'comprehensive_test', 'listening', 'makeup', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mỹ phẩm; đồ trang điểm","giúp thoát khỏi; tẩy sạch","nhạc cụ","giấm"]'::jsonb, 0, 'makeup (/ˈmeɪkʌp/) → mỹ phẩm; đồ trang điểm; cấu trúc; thành phần cấu tạo', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_56_4', 'en-b1-56', NULL, 'comprehensive_test', 'listening', 'We tried various dishes at the weekend market.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy mang theo ô; nếu không, bạn sẽ bị ướt đấy.","Chúng tôi đã thử nhiều món ăn khác nhau ở chợ cuối tuần.","Xin vui lòng gửi những bức ảnh đó trực tiếp đến điện thoại của tôi.","Món súp này hơi mặn, nhưng bánh mì thì rất ngon."]'::jsonb, 1, 'We tried various dishes at the weekend market. → Chúng tôi đã thử nhiều món ăn khác nhau ở chợ cuối tuần.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_56_5', 'en-b1-56', NULL, 'comprehensive_test', 'listening', 'frequent', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cằm","tất yếu; nhất thiết; ắt là","thường xuyên; hay xảy ra","vết nứt; vết rạn"]'::jsonb, 2, 'frequent (/ˈfriːkwənt/) → thường xuyên; hay xảy ra; thường lui tới; hay đến', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_56_6', 'en-b1-56', NULL, 'comprehensive_test', 'listening', 'Please send the photos directly to my phone.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đã tẩy trang trước khi đi ngủ.","Chúng tôi cùng nhau ăn một bát rau củ hầm sau buổi đi dạo.","Món súp này hơi mặn, nhưng bánh mì thì rất ngon.","Xin vui lòng gửi những bức ảnh đó trực tiếp đến điện thoại của tôi."]'::jsonb, 3, 'Please send the photos directly to my phone. → Xin vui lòng gửi những bức ảnh đó trực tiếp đến điện thoại của tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_56_7', 'en-b1-56', NULL, 'comprehensive_test', 'listening', 'gradually', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["dần dần; từ từ","sự xa hoa; sự sang trọng","trao đổi; đổi","cuộc thi; cuộc đấu tranh"]'::jsonb, 0, 'gradually (/ˈɡrædʒuəli/) → dần dần; từ từ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_56_8', 'en-b1-56', NULL, 'comprehensive_test', 'listening', 'We warmed our feet beside the fireplace after dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã xem một bộ phim và bàn về đoạn kết của nó ngay sau đó.","Trộn đều bột mì và bơ trong một cái bát lớn.","Chúng tôi sưởi ấm đôi chân bên lò sưởi sau bữa tối.","Một lớp bụi dày phủ kín cây đàn piano cũ."]'::jsonb, 2, 'We warmed our feet beside the fireplace after dinner. → Chúng tôi sưởi ấm đôi chân bên lò sưởi sau bữa tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
