INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_56_18', 'en-b1-56', NULL, 'comprehensive_test', 'reading', NULL, 'A sudden rise in food prices can place considerable pressure on families with low incomes.', 'Dựa vào câu trên, từ “sudden” có nghĩa phù hợp nhất là gì?', '["quý giá; đắt tiền","tổ chức; cơ quan; hiệp hội","đột ngột; bất ngờ","phòng thí nghiệm; phòng nghiên cứu"]'::jsonb, 2, 'sudden: đột ngột; bất ngờ. Dịch cả câu: Giá thực phẩm tăng đột ngột có thể tạo ra áp lực đáng kể cho các gia đình có thu nhập thấp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_56_19', 'en-b1-56', NULL, 'comprehensive_test', 'reading', NULL, 'Designing clothing with replaceable buttons and zippers could extend its lifespan and reduce household textile waste.', 'Dựa vào câu trên, từ “zipper” có nghĩa phù hợp nhất là gì?', '["khóa kéo","thuộc về thể chất; thuộc cơ thể","kim tự tháp; hình chóp","toàn thời gian; toàn ngày"]'::jsonb, 0, 'zipper: khóa kéo. Dịch cả câu: Việc thiết kế quần áo có cúc và khóa kéo thay thế được có thể kéo dài tuổi thọ của trang phục và giảm thiểu rác thải dệt may trong gia đình.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_56_20', 'en-b1-56', NULL, 'comprehensive_test', 'reading', NULL, 'Changes in the demographic makeup of cities can influence demand for housing, healthcare and public transport.', 'Dựa vào câu trên, từ “makeup” có nghĩa phù hợp nhất là gì?', '["mỹ phẩm; đồ trang điểm","bài đánh giá; lời bình phẩm","sự thêm vào; sự gia tăng","tái nhợt; nhạt màu"]'::jsonb, 0, 'makeup: mỹ phẩm; đồ trang điểm; cấu trúc; thành phần cấu tạo. Dịch cả câu: Sự thay đổi trong cơ cấu nhân khẩu học của các thành phố có thể ảnh hưởng đến nhu cầu về nhà ở, y tế và giao thông công cộng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_56_21', 'en-b1-56', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should offer various activities to help students discover their interests and develop practical skills.', 'Dựa vào câu trên, từ “various” có nghĩa phù hợp nhất là gì?', '["khác nhau; gồm nhiều loại khác nhau","tối đa; lớn nhất; cao nhất","lan truyền; truyền bá","sự an toàn; sự an tâm"]'::jsonb, 0, 'various: khác nhau; gồm nhiều loại khác nhau. Dịch cả câu: Các trường học nên cung cấp nhiều hoạt động đa dạng để giúp học sinh khám phá sở thích và phát triển kỹ năng thực tế.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
