INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-57', 'en', 'Bài 57: Đời sống hằng ngày (9) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3057, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_occasion', 'en-b1-57', 'occasion', '/əˈkeɪʒən/', 'B1', 'dịp; lần; dịp đặc biệt; sự kiện trọng đại; cơ hội; thời cơ', 'n.', 'occasional (adj.), occasionally (adv.)', NULL, 'Diễn đạt ý "vào dịp nào đó" thì dùng giới từ on, không dùng in.', 'I have met your sister on several occasions.', NULL, 'Tôi đã gặp chị gái của bạn vài lần rồi.', '{"wordId":"occasion","ukIpa":"/əˈkeɪʒən/","usIpa":"/əˈkeɪʒən/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a particular time when something happens","vi":"dịp; lần"},{"pos":"n.","en":"an important or special event","vi":"dịp đặc biệt; sự kiện trọng đại"},{"pos":"n.","en":"a suitable opportunity to do something","vi":"cơ hội; thời cơ"}],"examples":[{"en":"I have met your sister on several occasions.","vi":"Tôi đã gặp chị gái của bạn vài lần rồi.","audioKind":"ex"},{"en":"Community festivals provide an occasion for residents from different backgrounds to share traditions and build friendships.","vi":"Các lễ hội cộng đồng tạo cơ hội cho người dân từ các hoàn cảnh khác nhau chia sẻ truyền thống và xây dựng tình bạn.","audioKind":"ex2"}],"collocations":[{"en":"on several occasions","vi":"trong vài dịp"},{"en":"a special occasion","vi":"một dịp đặc biệt"},{"en":"on occasion","vi":"thỉnh thoảng"},{"en":"rise to the occasion","vi":"đứng vững trước thử thách"}],"wordFamily":["occasional (adj.)","occasionally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Diễn đạt ý \"vào dịp nào đó\" thì dùng giới từ on, không dùng in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nut', 'en-b1-57', 'nut', '/nʌt/', 'B1', 'quả hạch; hạt cứng; đai ốc; con ốc; ốc vít', 'n.', 'nutty (adj.)', NULL, 'Cả nghĩa thực phẩm (quả hạch) và nghĩa kỹ thuật (đai ốc) đều là danh từ đếm được.', 'She cracked a nut and shared the kernel with me.', NULL, 'Cô ấy đập một quả hạch rồi chia phần nhân cho tôi.', '{"wordId":"nut","ukIpa":"/nʌt/","usIpa":"/nʌt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A hard-shelled fruit with an edible seed inside.","vi":"quả hạch; hạt cứng"},{"pos":"n.","en":"A small metal piece screwed onto a bolt to fasten things.","vi":"đai ốc; con ốc; ốc vít"}],"examples":[{"en":"She cracked a nut and shared the kernel with me.","vi":"Cô ấy đập một quả hạch rồi chia phần nhân cho tôi.","audioKind":"ex"},{"en":"Nuts provide useful nutrients, although schools must consider food allergies when planning meals for children.","vi":"Các loại hạt cung cấp chất dinh dưỡng có lợi, mặc dù nhà trường phải lưu ý vấn đề dị ứng thực phẩm khi lên thực đơn cho trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"mixed nuts","vi":"các loại hạt trộn"},{"en":"nut allergy","vi":"dị ứng hạt"},{"en":"tighten a nut","vi":"vặn chặt đai ốc"},{"en":"nuts and bolts","vi":"chi tiết cơ khí; những chi tiết cốt lõi"}],"wordFamily":["nutty (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cả nghĩa thực phẩm (quả hạch) và nghĩa kỹ thuật (đai ốc) đều là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perfectly', 'en-b1-57', 'perfectly', '/ˈpɝːfɪktli/', 'B1', 'hoàn hảo; không tì vết; hoàn toàn; hết sức', 'adv.', 'perfect (adj.), perfection (n.), perfectionist (n.)', 'Đồng nghĩa: flawlessly, completely · Trái nghĩa: imperfectly', 'Cụm perfectly clear nghĩa là vô cùng rõ ràng, không dịch là hoàn hảo rõ ràng.', 'The new curtains match our sofa perfectly.', NULL, 'Bộ rèm cửa mới rất hợp với chiếc ghế sofa của chúng tôi.', '{"wordId":"perfectly","ukIpa":"/ˈpɜːfɪktli/","usIpa":"/ˈpɝːfɪktli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"In a way that has no faults or mistakes.","vi":"hoàn hảo; không tì vết"},{"pos":"adv.","en":"Completely; used to emphasize a description.","vi":"hoàn toàn; hết sức"}],"examples":[{"en":"The new curtains match our sofa perfectly.","vi":"Bộ rèm cửa mới rất hợp với chiếc ghế sofa của chúng tôi.","audioKind":"ex"},{"en":"It is perfectly reasonable for residents to expect reliable public services in return for their taxes.","vi":"Việc cư dân mong đợi các dịch vụ công đáng tin cậy để đổi lấy tiền thuế của họ là điều hoàn toàn hợp lý.","audioKind":"ex2"}],"collocations":[{"en":"fit perfectly","vi":"vừa vặn hoàn hảo"},{"en":"work perfectly","vi":"hoạt động hoàn hảo"},{"en":"perfectly reasonable","vi":"hoàn toàn hợp lý"},{"en":"perfectly clear","vi":"rõ mồn một; vô cùng rõ ràng"}],"wordFamily":["perfect (adj.)","perfection (n.)","perfectionist (n.)"],"synonyms":["flawlessly","completely"],"antonyms":["imperfectly"],"tipVi":"Cụm perfectly clear nghĩa là vô cùng rõ ràng, không dịch là hoàn hảo rõ ràng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proper', 'en-b1-57', 'proper', '/ˈprɑːpər/', 'B1', 'thích hợp; đúng đắn; ra trò; đích thực; tử tế; nghĩa đen; chính cống; tự thân', 'adj.', 'properly (adv.), improper (adj.), improperly (adv.)', 'Đồng nghĩa: appropriate, suitable, correct · Trái nghĩa: improper, inappropriate', 'Khi mang nghĩa "chính cống/bản thân", từ này đặt sau danh từ, ví dụ như the city proper.', 'You need proper shoes for walking on rocky paths.', NULL, 'Bạn cần mang giày thích hợp để đi trên những con đường đá lởm chởm.', '{"wordId":"proper","ukIpa":"/ˈprɒpə/","usIpa":"/ˈprɑːpər/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Suitable or correct for a particular purpose or situation.","vi":"thích hợp; đúng đắn"},{"pos":"adj.","en":"Real or satisfactory, rather than incomplete or inadequate.","vi":"ra trò; đích thực; tử tế"},{"pos":"adj.","en":"Strictly understood, excluding surrounding or related things.","vi":"nghĩa đen; chính cống; tự thân"}],"examples":[{"en":"You need proper shoes for walking on rocky paths.","vi":"Bạn cần mang giày thích hợp để đi trên những con đường đá lởm chởm.","audioKind":"ex"},{"en":"Workers should receive proper training before operating machinery that could pose a risk to their safety.","vi":"Công nhân nên được đào tạo đầy đủ trước khi vận hành máy móc có thể gây rủi ro cho sự an toàn của họ.","audioKind":"ex2"}],"collocations":[{"en":"proper training","vi":"đào tạo bài bản"},{"en":"proper care","vi":"chăm sóc chu đáo"},{"en":"a proper meal","vi":"một bữa ăn đàng hoàng"},{"en":"the city proper","vi":"khu nội thành"}],"wordFamily":["properly (adv.)","improper (adj.)","improperly (adv.)"],"synonyms":["appropriate","suitable","correct"],"antonyms":["improper","inappropriate"],"tipVi":"Khi mang nghĩa \"chính cống/bản thân\", từ này đặt sau danh từ, ví dụ như the city proper.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_softly', 'en-b1-57', 'softly', '/ˈsɔːftli/', 'B1', 'khẽ; nhỏ nhẹ; nhẹ nhàng; dịu dàng', 'adv.', 'soft (adj.), softness (n.), soften (v.)', 'Đồng nghĩa: gently, quietly · Trái nghĩa: loudly', 'softly nhấn mạnh sự nhẹ nhàng hoặc âm lượng nhỏ; không đồng nghĩa với từ từ.', 'She spoke softly so the sleeping baby would not wake.', NULL, 'Cô ấy nói chuyện nhỏ nhẹ để em bé đang ngủ không bị thức giấc.', '{"wordId":"softly","ukIpa":"/ˈsɒftli/","usIpa":"/ˈsɔːftli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"in a quiet voice or with little noise","vi":"khẽ; nhỏ nhẹ"},{"pos":"adv.","en":"in a gentle way without force or harshness","vi":"nhẹ nhàng; dịu dàng"}],"examples":[{"en":"She spoke softly so the sleeping baby would not wake.","vi":"Cô ấy nói chuyện nhỏ nhẹ để em bé đang ngủ không bị thức giấc.","audioKind":"ex"},{"en":"In hospital wards, staff should speak softly at night to help patients rest and recover.","vi":"Trong phòng bệnh, nhân viên nên nói chuyện khẽ khàng vào ban đêm để giúp bệnh nhân nghỉ ngơi và hồi phục.","audioKind":"ex2"}],"collocations":[{"en":"speak softly","vi":"nói nhỏ nhẹ"},{"en":"whisper softly","vi":"thì thầm khẽ"},{"en":"softly lit","vi":"được chiếu sáng nhẹ nhàng"}],"wordFamily":["soft (adj.)","softness (n.)","soften (v.)"],"synonyms":["gently","quietly"],"antonyms":["loudly"],"tipVi":"softly nhấn mạnh sự nhẹ nhàng hoặc âm lượng nhỏ; không đồng nghĩa với từ từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_permanent', 'en-b1-57', 'permanent', '/ˈpɝːmənənt/', 'B1', 'vĩnh viễn; lâu dài; thường xuyên; làm việc dài hạn; chính thức', 'adj.', 'permanently (adv.), permanence (n.), impermanent (adj.)', 'Đồng nghĩa: lasting · Trái nghĩa: temporary', 'permanent job chỉ công việc không có thời hạn kết thúc cố định, chứ không đảm bảo được biên chế suốt đời.', 'The hot pan left a permanent mark on the table.', NULL, 'Chiếc chảo nóng đã để lại một vết hằn vĩnh viễn trên bàn.', '{"wordId":"permanent","ukIpa":"/ˈpɜːmənənt/","usIpa":"/ˈpɝːmənənt/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Lasting indefinitely rather than for a limited time.","vi":"vĩnh viễn; lâu dài; thường xuyên"},{"pos":"adj.","en":"Employed without a fixed end date.","vi":"làm việc dài hạn; chính thức"}],"examples":[{"en":"The hot pan left a permanent mark on the table.","vi":"Chiếc chảo nóng đã để lại một vết hằn vĩnh viễn trên bàn.","audioKind":"ex"},{"en":"Investment in flood prevention can reduce the risk of permanent damage to homes and public infrastructure.","vi":"Đầu tư vào phòng chống lũ lụt có thể làm giảm nguy cơ tổn hại lâu dài cho nhà cửa và cơ sở hạ tầng công cộng.","audioKind":"ex2"}],"collocations":[{"en":"permanent damage","vi":"tổn hại lâu dài"},{"en":"permanent resident","vi":"thường trú nhân"},{"en":"permanent job","vi":"công việc lâu dài"},{"en":"permanent address","vi":"địa chỉ thường trú"}],"wordFamily":["permanently (adv.)","permanence (n.)","impermanent (adj.)"],"synonyms":["lasting"],"antonyms":["temporary"],"tipVi":"permanent job chỉ công việc không có thời hạn kết thúc cố định, chứ không đảm bảo được biên chế suốt đời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spare', 'en-b1-57', 'spare', '/sper/', 'B1', 'dự phòng; thừa; rảnh rỗi; dành ra; bố trí (thời gian, tài nguyên); giúp ai tránh khỏi; tha thứ', 'adj.', NULL, NULL, 'spare time là thời gian rảnh; spare đóng vai trò động từ có thể biểu thị việc dành ra.', 'I keep a spare umbrella in my car.', NULL, 'Tôi giữ một chiếc ô dự phòng trong xe hơi của mình.', '{"wordId":"spare","ukIpa":"/speə/","usIpa":"/sper/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"extra and available to use when needed","vi":"dự phòng; thừa; rảnh rỗi"},{"pos":"v.","en":"to give time or resources that you can make available","vi":"dành ra; bố trí (thời gian, tài nguyên)"},{"pos":"v.","en":"to prevent someone from experiencing harm or difficulty","vi":"giúp ai tránh khỏi; tha thứ"}],"examples":[{"en":"I keep a spare umbrella in my car.","vi":"Tôi giữ một chiếc ô dự phòng trong xe hơi của mình.","audioKind":"ex"},{"en":"People who can spare a few hours each week could support local charities through regular volunteering.","vi":"Những người có thể dành ra vài giờ mỗi tuần có thể hỗ trợ các tổ chức từ thiện địa phương thông qua việc làm tình nguyện đều đặn.","audioKind":"ex2"}],"collocations":[{"en":"spare time","vi":"thời gian rảnh"},{"en":"spare key","vi":"chìa khóa dự phòng"},{"en":"spare parts","vi":"phụ tùng thay thế"},{"en":"spare a moment","vi":"dành ra một chút thời gian"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"spare time là thời gian rảnh; spare đóng vai trò động từ có thể biểu thị việc dành ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_outfit', 'en-b1-57', 'outfit', '/ˈaʊtfɪt/', 'B1', 'bộ trang phục; trang bị; cung cấp thiết bị; đội ngũ; tổ chức', 'n.', 'outfitter (n.)', NULL, 'Một bộ quần áo có thể gọi là an outfit; động từ thường đi kèm với giới từ with.', 'She chose a bright outfit for her birthday party.', NULL, 'Cô ấy chọn một bộ trang phục rực rỡ cho bữa tiệc sinh nhật của mình.', '{"wordId":"outfit","ukIpa":"/ˈaʊtfɪt/","usIpa":"/ˈaʊtfɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A set of clothes worn together for a particular occasion.","vi":"bộ trang phục"},{"pos":"v.","en":"To provide someone or something with necessary equipment or clothes.","vi":"trang bị; cung cấp thiết bị"},{"pos":"n.","en":"A group or organization working together, used informally.","vi":"đội ngũ; tổ chức"}],"examples":[{"en":"She chose a bright outfit for her birthday party.","vi":"Cô ấy chọn một bộ trang phục rực rỡ cho bữa tiệc sinh nhật của mình.","audioKind":"ex"},{"en":"Schools should outfit science laboratories with modern equipment so that students can develop practical research skills.","vi":"Các trường học nên trang bị cho các phòng thí nghiệm khoa học các thiết bị hiện đại để học sinh có thể phát triển các kỹ năng nghiên cứu thực tế.","audioKind":"ex2"}],"collocations":[{"en":"casual outfit","vi":"trang phục thường ngày"},{"en":"matching outfit","vi":"bộ trang phục đồng điệu"},{"en":"outfit something with equipment","vi":"trang bị thiết bị cho thứ gì đó"}],"wordFamily":["outfitter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Một bộ quần áo có thể gọi là an outfit; động từ thường đi kèm với giới từ with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_closet', 'en-b1-57', 'closet', '/ˈklɑːzɪt/', 'B1', 'tủ tường; phòng chứa đồ nhỏ; giữ kín; che giấu (thân phận, sở thích)', 'n.', NULL, 'Đồng nghĩa: cupboard', 'Nghĩa chứa đồ quần áo phổ biến trong tiếng Mỹ; tiếng Anh-Anh thường dùng từ wardrobe.', 'I hung my winter coat in the hallway closet.', NULL, 'Tôi treo chiếc áo khoác mùa đông của mình vào tủ ở hành lang.', '{"wordId":"closet","ukIpa":"/ˈklɒzɪt/","usIpa":"/ˈklɑːzɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A cupboard or small enclosed space for storing clothes or belongings","vi":"tủ tường; phòng chứa đồ nhỏ"},{"pos":"adj.","en":"Keeping a particular identity, belief, or interest secret","vi":"giữ kín; che giấu (thân phận, sở thích)"}],"examples":[{"en":"I hung my winter coat in the hallway closet.","vi":"Tôi treo chiếc áo khoác mùa đông của mình vào tủ ở hành lang.","audioKind":"ex"},{"en":"Small apartments can feel more spacious when residents organise belongings efficiently and make better use of closet space.","vi":"Các căn hộ nhỏ có thể có cảm giác rộng rãi hơn khi cư dân sắp xếp đồ đạc ngăn nắp và tận dụng tốt hơn không gian tủ tường.","audioKind":"ex2"}],"collocations":[{"en":"built-in closet","vi":"tủ âm tường"},{"en":"walk-in closet","vi":"phòng thay đồ lớn"},{"en":"closet space","vi":"không gian tủ đồ"}],"wordFamily":[],"synonyms":["cupboard"],"antonyms":[],"tipVi":"Nghĩa chứa đồ quần áo phổ biến trong tiếng Mỹ; tiếng Anh-Anh thường dùng từ wardrobe.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ignore', 'en-b1-57', 'ignore', '/ɪɡˈnɔːr/', 'B1', 'phớt lờ; ngó lơ; không đếm xỉa', 'v.', 'ignorance (n.), ignorant (adj.)', 'Đồng nghĩa: disregard · Trái nghĩa: notice, heed', 'Kết hợp trực tiếp với tân ngữ; không dùng với nghĩa pháp lý là "bác bỏ vụ án".', 'Please don''t ignore that strange noise from the engine.', NULL, 'Làm ơn đừng phớt lờ tiếng động kỳ lạ phát ra từ động cơ đó.', '{"wordId":"ignore","ukIpa":"/ɪɡˈnɔː/","usIpa":"/ɪɡˈnɔːr/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Pay no attention to someone or something","vi":"phớt lờ; ngó lơ; không đếm xỉa"}],"examples":[{"en":"Please don''t ignore that strange noise from the engine.","vi":"Làm ơn đừng phớt lờ tiếng động kỳ lạ phát ra từ động cơ đó.","audioKind":"ex"},{"en":"Governments cannot ignore the long-term effects of air pollution on children''s health and development.","vi":"Chính phủ không thể phớt lờ những tác động lâu dài của ô nhiễm không khí đối với sức khỏe và sự phát triển của trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"ignore a warning","vi":"bỏ qua một lời cảnh báo"},{"en":"ignore the evidence","vi":"phớt lờ bằng chứng"},{"en":"completely ignore","vi":"hoàn toàn phớt lờ"}],"wordFamily":["ignorance (n.)","ignorant (adj.)"],"synonyms":["disregard"],"antonyms":["notice","heed"],"tipVi":"Kết hợp trực tiếp với tân ngữ; không dùng với nghĩa pháp lý là \"bác bỏ vụ án\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regularly', 'en-b1-57', 'regularly', '/ˈreɡjələrli/', 'B1', 'thường xuyên; đều đặn; có quy luật', 'adv.', 'regular (adj.), regularity (n.), irregular (adj.), irregularly (adv.)', 'Đồng nghĩa: frequently, routinely · Trái nghĩa: irregularly', 'Có thể chỉ tần suất thường xuyên hoặc khoảng thời gian cố định; không nhất thiết phải diễn ra hàng ngày.', 'We regularly walk along the river after dinner.', NULL, 'Chúng tôi thường xuyên đi dạo dọc bờ sông sau bữa tối.', '{"wordId":"regularly","ukIpa":"/ˈreɡjələli/","usIpa":"/ˈreɡjələrli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"often or at repeated intervals","vi":"thường xuyên; đều đặn"},{"pos":"adv.","en":"with equal spaces or a consistent pattern","vi":"đều đặn; có quy luật"}],"examples":[{"en":"We regularly walk along the river after dinner.","vi":"Chúng tôi thường xuyên đi dạo dọc bờ sông sau bữa tối.","audioKind":"ex"},{"en":"People who exercise regularly are more likely to maintain good physical health as they grow older.","vi":"Những người tập thể dục đều đặn có nhiều khả năng duy trì sức khỏe thể chất tốt khi họ lớn tuổi hơn.","audioKind":"ex2"}],"collocations":[{"en":"exercise regularly","vi":"tập thể dục đều đặn"},{"en":"check regularly","vi":"kiểm tra định kỳ"},{"en":"regularly updated","vi":"được cập nhật thường xuyên"},{"en":"regularly spaced","vi":"được bố trí đều đặn"}],"wordFamily":["regular (adj.)","regularity (n.)","irregular (adj.)","irregularly (adv.)"],"synonyms":["frequently","routinely"],"antonyms":["irregularly"],"tipVi":"Có thể chỉ tần suất thường xuyên hoặc khoảng thời gian cố định; không nhất thiết phải diễn ra hàng ngày.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_babysitter', 'en-b1-57', 'babysitter', '/ˈbeɪbisɪtər/', 'B1', 'người trông trẻ tạm thời', 'n.', 'babysit (v.), babysitting (n.)', NULL, 'Thường chỉ người nhận trông giữ trẻ giúp trong thời gian ngắn, không giới hạn chỉ chăm sóc mỗi trẻ sơ sinh.', 'The babysitter read a story while the children ate.', NULL, 'Người trông trẻ đã đọc một câu chuyện trong lúc lũ trẻ ăn uống.', '{"wordId":"babysitter","ukIpa":"/ˈbeɪbisɪtə/","usIpa":"/ˈbeɪbisɪtər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Someone who temporarily looks after children while their parents are away.","vi":"người trông trẻ tạm thời"}],"examples":[{"en":"The babysitter read a story while the children ate.","vi":"Người trông trẻ đã đọc một câu chuyện trong lúc lũ trẻ ăn uống.","audioKind":"ex"},{"en":"Finding a reliable babysitter can help parents balance occasional evening commitments with their childcare responsibilities.","vi":"Tìm kiếm một người trông trẻ đáng tin cậy có thể giúp các bậc cha mẹ cân bằng giữa các cam kết buổi tối không thường xuyên với trách nhiệm chăm sóc con cái.","audioKind":"ex2"}],"collocations":[{"en":"hire a babysitter","vi":"thuê người trông trẻ"},{"en":"reliable babysitter","vi":"người trông trẻ đáng tin cậy"},{"en":"find a babysitter","vi":"tìm người trông trẻ"}],"wordFamily":["babysit (v.)","babysitting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ người nhận trông giữ trẻ giúp trong thời gian ngắn, không giới hạn chỉ chăm sóc mỗi trẻ sơ sinh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_urgent', 'en-b1-57', 'urgent', '/ˈɝːdʒənt/', 'B1', 'khẩn cấp; cấp bách', 'adj.', 'urgency (n.), urgently (adv.)', 'Đồng nghĩa: pressing · Trái nghĩa: non-urgent', 'Urgent nhấn mạnh tính chất phải xử lý ngay lập tức, không chỉ đơn thuần là quan trọng.', 'The plumber came quickly because the leak was urgent.', NULL, 'Thợ sửa ống nước đã đến rất nhanh vì vết rò rỉ là vấn đề khẩn cấp.', '{"wordId":"urgent","ukIpa":"/ˈɜːdʒənt/","usIpa":"/ˈɝːdʒənt/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Needing immediate attention or action","vi":"khẩn cấp; cấp bách"}],"examples":[{"en":"The plumber came quickly because the leak was urgent.","vi":"Thợ sửa ống nước đã đến rất nhanh vì vết rò rỉ là vấn đề khẩn cấp.","audioKind":"ex"},{"en":"There is an urgent need for affordable housing as urban populations continue to grow.","vi":"Nhu cầu về nhà ở giá rẻ đang rất cấp bách khi dân số đô thị tiếp tục gia tăng.","audioKind":"ex2"}],"collocations":[{"en":"urgent action","vi":"hành động khẩn cấp"},{"en":"an urgent need","vi":"một nhu cầu cấp thiết"},{"en":"urgent medical attention","vi":"sự chăm sóc y tế khẩn cấp"}],"wordFamily":["urgency (n.)","urgently (adv.)"],"synonyms":["pressing"],"antonyms":["non-urgent"],"tipVi":"Urgent nhấn mạnh tính chất phải xử lý ngay lập tức, không chỉ đơn thuần là quan trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fasten', 'en-b1-57', 'fasten', '/ˈfæsən/', 'B1', 'cố định; thắt chặt; cài', 'v.', 'fastener (n.), unfasten (v.)', 'Đồng nghĩa: secure, attach · Trái nghĩa: unfasten, undo', 'Chữ t trong từ này bị câm; từ trái nghĩa là unfasten có nghĩa là cởi ra hoặc tháo ra.', 'Please fasten your seat belt before we leave.', NULL, 'Xin vui lòng thắt dây an toàn trước khi chúng ta khởi hành.', '{"wordId":"fasten","ukIpa":"/ˈfɑːsən/","usIpa":"/ˈfæsən/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to close or attach something securely","vi":"cố định; thắt chặt; cài"}],"examples":[{"en":"Please fasten your seat belt before we leave.","vi":"Xin vui lòng thắt dây an toàn trước khi chúng ta khởi hành.","audioKind":"ex"},{"en":"Passengers must fasten their seat belts during takeoff and landing to reduce the risk of injury.","vi":"Hành khách phải thắt chặt dây an toàn trong suốt quá trình cất cánh và hạ cánh để giảm thiểu nguy cơ chấn thương.","audioKind":"ex2"}],"collocations":[{"en":"fasten a seat belt","vi":"thắt dây an toàn"},{"en":"fasten a button","vi":"cài khuy áo"},{"en":"fasten securely","vi":"cố định chắc chắn"}],"wordFamily":["fastener (n.)","unfasten (v.)"],"synonyms":["secure","attach"],"antonyms":["unfasten","undo"],"tipVi":"Chữ t trong từ này bị câm; từ trái nghĩa là unfasten có nghĩa là cởi ra hoặc tháo ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_balance', 'en-b1-57', 'balance', '/ˈbæləns/', 'B1', 'sự cân bằng; sự hài hòa; giữ cân bằng; cân đối; số dư tài khoản; tiền còn thiếu', 'n.', 'balanced (adj.), unbalanced (adj.), imbalance (n.)', 'Đồng nghĩa: equilibrium · Trái nghĩa: imbalance', 'Để diễn tả việc cân bằng giữa hai yếu tố, hãy dùng cấu trúc balance A with B; còn dạng tính từ của sự cân bằng là balanced.', 'She lost her balance while stepping off the bus.', NULL, 'Cô ấy bị mất thăng bằng khi bước xuống xe buýt.', '{"wordId":"balance","ukIpa":"/ˈbæləns/","usIpa":"/ˈbæləns/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A steady position or a suitable mixture of different things","vi":"sự cân bằng; sự hài hòa"},{"pos":"v.","en":"To keep something steady or give competing needs suitable attention","vi":"giữ cân bằng; cân đối"},{"pos":"n.","en":"The money remaining in an account or still owed","vi":"số dư tài khoản; tiền còn thiếu"}],"examples":[{"en":"She lost her balance while stepping off the bus.","vi":"Cô ấy bị mất thăng bằng khi bước xuống xe buýt.","audioKind":"ex"},{"en":"Governments must balance the demand for affordable housing with the need to protect green spaces.","vi":"Chính phủ phải cân đối giữa nhu cầu về nhà ở giá rẻ và nhu cầu bảo vệ không gian xanh.","audioKind":"ex2"}],"collocations":[{"en":"keep your balance","vi":"giữ thăng bằng"},{"en":"strike a balance","vi":"đạt được sự cân bằng"},{"en":"work-life balance","vi":"cân bằng giữa công việc và cuộc sống"},{"en":"bank balance","vi":"số dư tài khoản ngân hàng"}],"wordFamily":["balanced (adj.)","unbalanced (adj.)","imbalance (n.)"],"synonyms":["equilibrium"],"antonyms":["imbalance"],"tipVi":"Để diễn tả việc cân bằng giữa hai yếu tố, hãy dùng cấu trúc balance A with B; còn dạng tính từ của sự cân bằng là balanced.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dig', 'en-b1-57', 'dig', '/dɪɡ/', 'B1', 'đào; bới; tìm hiểu; nghiên cứu sâu; cuộc khai quật', 'v.', 'digger (n.)', 'Đồng nghĩa: excavate', 'Quá khứ và phân từ hai đều là dug; dig into có thể dùng với nghĩa điều tra sâu.', 'We dug a deep hole for the young apple tree.', NULL, 'Chúng tôi đã đào một cái hố sâu cho cây táo non.', '{"wordId":"dig","ukIpa":"/dɪɡ/","usIpa":"/dɪɡ/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Move earth to make a hole or uncover something","vi":"đào; bới"},{"pos":"v.","en":"Search carefully for hidden information","vi":"tìm hiểu; nghiên cứu sâu"},{"pos":"n.","en":"An organized activity to uncover ancient objects in the ground","vi":"cuộc khai quật"}],"examples":[{"en":"We dug a deep hole for the young apple tree.","vi":"Chúng tôi đã đào một cái hố sâu cho cây táo non.","audioKind":"ex"},{"en":"Researchers dig into historical records to understand how earlier societies responded to periods of rapid environmental change.","vi":"Các nhà nghiên cứu đào sâu vào các tài liệu lịch sử để hiểu cách các xã hội trước đây ứng phó với các thời kỳ biến đổi môi trường nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"dig a hole","vi":"đào một cái hố"},{"en":"dig up","vi":"đào lên"},{"en":"dig into","vi":"tìm hiểu sâu"},{"en":"an archaeological dig","vi":"một cuộc khai quật khảo cổ"}],"wordFamily":["digger (n.)"],"synonyms":["excavate"],"antonyms":[],"tipVi":"Quá khứ và phân từ hai đều là dug; dig into có thể dùng với nghĩa điều tra sâu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_position', 'en-b1-57', 'position', '/pəˈzɪʃən/', 'B1', 'vị trí; tư thế; chức vụ; địa vị; quan điểm; đặt; bố trí', 'n.', 'positional (adj.)', NULL, 'Khi chỉ lập trường, dùng position on; chỉ chức vụ là danh từ đếm được.', 'Can you move the lamp to a better position?', NULL, 'Bạn có thể di chuyển chiếc đèn đến một vị trí tốt hơn không?', '{"wordId":"position","ukIpa":"/pəˈzɪʃən/","usIpa":"/pəˈzɪʃən/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"where something is or how a body is arranged","vi":"vị trí; tư thế"},{"pos":"n.","en":"a job, social rank, or opinion on an issue","vi":"chức vụ; địa vị; quan điểm"},{"pos":"v.","en":"to put someone or something in a particular place","vi":"đặt; bố trí"}],"examples":[{"en":"Can you move the lamp to a better position?","vi":"Bạn có thể di chuyển chiếc đèn đến một vị trí tốt hơn không?","audioKind":"ex"},{"en":"The report explains the government''s position on providing affordable housing for young families.","vi":"Báo cáo giải thích quan điểm của chính phủ về việc cung cấp nhà ở giá rẻ cho các gia đình trẻ.","audioKind":"ex2"}],"collocations":[{"en":"sitting position","vi":"tư thế ngồi"},{"en":"apply for a position","vi":"nộp đơn xin việc"},{"en":"take a position on","vi":"bày tỏ quan điểm về"},{"en":"position carefully","vi":"đặt cẩn thận"}],"wordFamily":["positional (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ lập trường, dùng position on; chỉ chức vụ là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cafeteria', 'en-b1-57', 'cafeteria', '/ˌkæfəˈtɪriə/', 'B1', 'quán ăn tự phục vụ; nhà ăn tập thể', 'n.', NULL, 'Đồng nghĩa: canteen', 'Nhấn mạnh việc tự lấy đồ ăn, không nhất thiết là buffet ăn thoải mái.', 'We carried our lunch trays to the cafeteria window.', NULL, 'Chúng tôi bê khay đựng bữa trưa đến cửa sổ nhà ăn.', '{"wordId":"cafeteria","ukIpa":"/ˌkæfəˈtɪəriə/","usIpa":"/ˌkæfəˈtɪriə/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A restaurant where customers collect food and carry it to tables.","vi":"quán ăn tự phục vụ; nhà ăn tập thể"}],"examples":[{"en":"We carried our lunch trays to the cafeteria window.","vi":"Chúng tôi bê khay đựng bữa trưa đến cửa sổ nhà ăn.","audioKind":"ex"},{"en":"School cafeterias can promote healthier eating habits by offering affordable meals with fresh vegetables and fruit.","vi":"Nhà ăn trường học có thể thúc đẩy thói quen ăn uống lành mạnh hơn bằng cách cung cấp các bữa ăn giá cả phải chăng với rau củ và trái cây tươi.","audioKind":"ex2"}],"collocations":[{"en":"a school cafeteria","vi":"nhà ăn trường học"},{"en":"a hospital cafeteria","vi":"nhà ăn bệnh viện"},{"en":"a cafeteria tray","vi":"khay đựng ở nhà ăn"}],"wordFamily":[],"synonyms":["canteen"],"antonyms":[],"tipVi":"Nhấn mạnh việc tự lấy đồ ăn, không nhất thiết là buffet ăn thoải mái.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anniversary', 'en-b1-57', 'anniversary', '/ˌænɪˈvɝːsəri/', 'B1', 'ngày kỷ niệm (hàng năm)', 'n.', NULL, NULL, 'Chỉ ngày tương ứng hàng năm của một sự kiện quan trọng, không chỉ dùng riêng cho đám cưới.', 'We cooked a special meal for our wedding anniversary.', NULL, 'Chúng tôi đã nấu một bữa ăn đặc biệt cho ngày kỷ niệm ngày cưới của mình.', '{"wordId":"anniversary","ukIpa":"/ˌænɪˈvɜːsəri/","usIpa":"/ˌænɪˈvɝːsəri/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A date marking another year since an important event.","vi":"ngày kỷ niệm (hàng năm)"}],"examples":[{"en":"We cooked a special meal for our wedding anniversary.","vi":"Chúng tôi đã nấu một bữa ăn đặc biệt cho ngày kỷ niệm ngày cưới của mình.","audioKind":"ex"},{"en":"The museum celebrated its anniversary by offering free admission to encourage more residents to explore local history.","vi":"Bảo tàng đã tổ chức kỷ niệm ngày thành lập bằng cách miễn phí vé vào cửa nhằm khuyến khích nhiều cư dân tìm hiểu về lịch sử địa phương.","audioKind":"ex2"}],"collocations":[{"en":"wedding anniversary","vi":"kỷ niệm ngày cưới"},{"en":"celebrate an anniversary","vi":"kỷ niệm ngày lễ lớn"},{"en":"mark an anniversary","vi":"đánh dấu mốc kỷ niệm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ ngày tương ứng hàng năm của một sự kiện quan trọng, không chỉ dùng riêng cho đám cưới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_backward', 'en-b1-57', 'backward', '/ˈbækwərd/', 'B1', 'hướng về phía sau; thụt lùi; về phía sau; lùi lại; lạc hậu; kém phát triển', 'adj.', 'backwards (adv.), backwardness (n.)', 'Đồng nghĩa: rearward · Trái nghĩa: forward', 'Phó từ tiếng Anh-Anh thường dùng backwards; dùng từ này để miêu tả người có thể gây tổn thương.', 'He took a backward step to avoid the puddle.', NULL, 'Anh ấy lùi lại một bước để tránh vũng nước.', '{"wordId":"backward","ukIpa":"/ˈbækwəd/","usIpa":"/ˈbækwərd/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Directed towards the back or away from progress.","vi":"hướng về phía sau; thụt lùi"},{"pos":"adv.","en":"Towards the back or in the reverse direction.","vi":"về phía sau; lùi lại"},{"pos":"adj.","en":"Less developed or advanced than expected.","vi":"lạc hậu; kém phát triển"}],"examples":[{"en":"He took a backward step to avoid the puddle.","vi":"Anh ấy lùi lại một bước để tránh vũng nước.","audioKind":"ex"},{"en":"Reducing investment in public transport would be a backward step for cities seeking to cut emissions.","vi":"Việc giảm đầu tư vào giao thông công cộng sẽ là một bước thụt lùi đối với các thành phố đang tìm cách cắt giảm khí thải.","audioKind":"ex2"}],"collocations":[{"en":"a backward step","vi":"một bước lùi"},{"en":"a backward glance","vi":"cái nhìn ngoảnh lại phía sau"},{"en":"move backward","vi":"di chuyển lùi"}],"wordFamily":["backwards (adv.)","backwardness (n.)"],"synonyms":["rearward"],"antonyms":["forward"],"tipVi":"Phó từ tiếng Anh-Anh thường dùng backwards; dùng từ này để miêu tả người có thể gây tổn thương.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_useless', 'en-b1-57', 'useless', '/ˈjuːsləs/', 'B1', 'vô dụng; không có ích; không đạt được kết quả mong muốn', 'adj.', 'use (v.), useful (adj.), uselessly (adv.), uselessness (n.)', 'Đồng nghĩa: ineffective, unhelpful · Trái nghĩa: useful, effective', 'useless at đi với danh từ hoặc danh động từ, dùng để chỉ sự không giỏi việc gì.', 'This broken umbrella is useless in heavy rain.', NULL, 'Chiếc ô bị gãy này hoàn toàn vô dụng trong trận mưa lớn.', '{"wordId":"useless","ukIpa":"/ˈjuːsləs/","usIpa":"/ˈjuːsləs/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Not useful or unable to achieve the intended result","vi":"vô dụng; không có ích; không đạt được kết quả mong muốn"}],"examples":[{"en":"This broken umbrella is useless in heavy rain.","vi":"Chiếc ô bị gãy này hoàn toàn vô dụng trong trận mưa lớn.","audioKind":"ex"},{"en":"Collecting environmental data is useless unless governments use the findings to guide effective policies.","vi":"Việc thu thập dữ liệu môi trường sẽ trở nên vô ích trừ khi chính phủ sử dụng kết quả nghiên cứu để định hướng các chính sách hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"completely useless","vi":"hoàn toàn vô dụng"},{"en":"useless at","vi":"kém cỏi/không giỏi về"},{"en":"render something useless","vi":"làm cho cái gì trở nên vô dụng"}],"wordFamily":["use (v.)","useful (adj.)","uselessly (adv.)","uselessness (n.)"],"synonyms":["ineffective","unhelpful"],"antonyms":["useful","effective"],"tipVi":"useless at đi với danh từ hoặc danh động từ, dùng để chỉ sự không giỏi việc gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_upside-down', 'en-b1-57', 'upside-down', '/ˌʌpsaɪd ˈdaʊn/', 'B1', 'lộn ngược; đảo ngược', 'adj.', NULL, 'Đồng nghĩa: inverted', 'Thường có dấu gạch nối khi đứng trước danh từ; khi làm vị ngữ hoặc trạng ngữ thì thường viết là upside down.', 'An upside-down bowl covered the last slice of cake.', NULL, 'Một chiếc bát úp ngược đã che đậy miếng bánh ngọt cuối cùng.', '{"wordId":"upside-down","ukIpa":"/ˌʌpsaɪd ˈdaʊn/","usIpa":"/ˌʌpsaɪd ˈdaʊn/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Positioned with the usual top at the bottom","vi":"lộn ngược; đảo ngược"}],"examples":[{"en":"An upside-down bowl covered the last slice of cake.","vi":"Một chiếc bát úp ngược đã che đậy miếng bánh ngọt cuối cùng.","audioKind":"ex"},{"en":"In a classroom experiment, students used an upside-down glass of water to explore the effects of air pressure.","vi":"Trong một thí nghiệm trên lớp, học sinh đã dùng một cốc nước úp ngược để khám phá tác động của áp suất khí quyển.","audioKind":"ex2"}],"collocations":[{"en":"an upside-down image","vi":"hình ảnh bị lộn ngược"},{"en":"an upside-down bowl","vi":"chiếc bát úp ngược"},{"en":"turn something upside down","vi":"làm đảo lộn cái gì"}],"wordFamily":[],"synonyms":["inverted"],"antonyms":[],"tipVi":"Thường có dấu gạch nối khi đứng trước danh từ; khi làm vị ngữ hoặc trạng ngữ thì thường viết là upside down.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_starting', 'en-b1-57', 'starting', '/ˈstɑːrtɪŋ/', 'B1', 'khởi đầu; ban đầu; sự bắt đầu; sự khởi động', 'adj.', 'start (v.), start (n.), starter (n.)', 'Đồng nghĩa: initial · Trái nghĩa: final', 'Thường gặp trong cụm starting point; ngoài ra cũng có thể đóng vai trò là phân từ của start.', 'We gathered at the starting point before sunrise.', NULL, 'Chúng tôi tập trung tại điểm xuất phát trước khi mặt trời mọc.', '{"wordId":"starting","ukIpa":"/ˈstɑːtɪŋ/","usIpa":"/ˈstɑːrtɪŋ/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Relating to the point where something begins","vi":"khởi đầu; ban đầu"},{"pos":"n.","en":"The act of beginning something or making it operate","vi":"sự bắt đầu; sự khởi động"}],"examples":[{"en":"We gathered at the starting point before sunrise.","vi":"Chúng tôi tập trung tại điểm xuất phát trước khi mặt trời mọc.","audioKind":"ex"},{"en":"A fair starting salary can help employers attract talented graduates and improve long-term staff retention.","vi":"Mức lương khởi điểm hợp lý có thể giúp các nhà tuyển dụng thu hút những sinh viên tốt nghiệp tài năng và cải thiện tỷ lệ giữ chân nhân viên lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"a starting point","vi":"điểm xuất phát"},{"en":"a starting salary","vi":"mức lương khởi điểm"},{"en":"the starting line","vi":"vạch xuất phát"},{"en":"a starting position","vi":"vị trí khởi đầu"}],"wordFamily":["start (v.)","start (n.)","starter (n.)"],"synonyms":["initial"],"antonyms":["final"],"tipVi":"Thường gặp trong cụm starting point; ngoài ra cũng có thể đóng vai trò là phân từ của start.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_besides', 'en-b1-57', 'besides', '/bɪˈsaɪdz/', 'B1', 'ngoài ra; bên cạnh; hơn nữa; vả lại', 'prep.', NULL, 'Đồng nghĩa: in addition to, moreover', 'besides mang ý nghĩa bổ sung bao gồm thêm; trong khi beside có nghĩa là ở bên cạnh.', 'Besides apples, we need some bread and fresh milk.', NULL, 'Ngoài táo ra, chúng tôi cần thêm một ít bánh mì và sữa tươi.', '{"wordId":"besides","ukIpa":"/bɪˈsaɪdz/","usIpa":"/bɪˈsaɪdz/","cefr":"B1","topic":"daily","senses":[{"pos":"prep.","en":"In addition to someone or something.","vi":"ngoài ra; bên cạnh"},{"pos":"adv.","en":"Used to add another fact or supporting reason.","vi":"hơn nữa; vả lại; ngoài ra"}],"examples":[{"en":"Besides apples, we need some bread and fresh milk.","vi":"Ngoài táo ra, chúng tôi cần thêm một ít bánh mì và sữa tươi.","audioKind":"ex"},{"en":"Besides reducing air pollution, investment in public transport can make cities more accessible to older residents.","vi":"Ngoài việc giảm ô nhiễm không khí, việc đầu tư vào giao thông công cộng còn giúp cư dân lớn tuổi dễ dàng di chuyển trong thành phố hơn.","audioKind":"ex2"}],"collocations":[{"en":"besides that","vi":"ngoài điều đó ra"},{"en":"besides being","vi":"ngoài việc là"},{"en":"besides the fact that","vi":"ngoài việc thực tế là"}],"wordFamily":[],"synonyms":["in addition to","moreover"],"antonyms":[],"tipVi":"besides mang ý nghĩa bổ sung bao gồm thêm; trong khi beside có nghĩa là ở bên cạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_split', 'en-b1-57', 'split', '/splɪt/', 'B1', 'chia ra; tách ra; phân chia; vết nứt; sự phân tách; sự bất đồng sâu sắc', 'v.', NULL, 'Đồng nghĩa: divide, separate · Trái nghĩa: unite', 'Dạng quá khứ và phân từ quá khứ của từ này đều là split; dạng phân từ hiện tại là splitting.', 'We split the cake and shared it with our neighbours.', NULL, 'Chúng tôi cắt chiếc bánh thành nhiều phần và chia sẻ với những người hàng xóm.', '{"wordId":"split","ukIpa":"/splɪt/","usIpa":"/splɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To divide something into parts, or separate into groups","vi":"chia ra; tách ra; phân chia"},{"pos":"n.","en":"A crack, division, or serious disagreement","vi":"vết nứt; sự phân tách; sự bất đồng sâu sắc"}],"examples":[{"en":"We split the cake and shared it with our neighbours.","vi":"Chúng tôi cắt chiếc bánh thành nhiều phần và chia sẻ với những người hàng xóm.","audioKind":"ex"},{"en":"Schools sometimes split large classes into smaller groups to provide more individual attention and support.","vi":"Các trường học đôi khi chia các lớp học lớn thành các nhóm nhỏ hơn để quan tâm và hỗ trợ học sinh tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"split into groups","vi":"chia thành các nhóm"},{"en":"split the cost","vi":"chia sẻ chi phí"},{"en":"split in two","vi":"chia đôi"},{"en":"a deep split","vi":"sự bất đồng sâu sắc"}],"wordFamily":[],"synonyms":["divide","separate"],"antonyms":["unite"],"tipVi":"Dạng quá khứ và phân từ quá khứ của từ này đều là split; dạng phân từ hiện tại là splitting.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unable', 'en-b1-57', 'unable', '/ʌnˈeɪbəl/', 'B1', 'không thể; không có khả năng', 'adj.', 'able (adj.), ability (n.), inability (n.)', 'Trái nghĩa: able', 'Dùng cấu trúc be unable to do, không dùng unable doing.', 'I was unable to open the tightly sealed jar.', NULL, 'Tôi không thể mở cái lọ được đậy rất kín đó.', '{"wordId":"unable","ukIpa":"/ʌnˈeɪbəl/","usIpa":"/ʌnˈeɪbəl/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Not having the ability or opportunity to do something.","vi":"không thể; không có khả năng"}],"examples":[{"en":"I was unable to open the tightly sealed jar.","vi":"Tôi không thể mở cái lọ được đậy rất kín đó.","audioKind":"ex"},{"en":"Without affordable internet access, many students are unable to participate fully in online learning programmes.","vi":"Không có dịch vụ Internet giá cả phải chăng, nhiều học sinh không thể tham gia đầy đủ vào các chương trình học trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"be unable to attend","vi":"không thể tham dự"},{"en":"be unable to afford","vi":"không đủ khả năng chi trả"},{"en":"be unable to cope","vi":"không thể đương đầu"}],"wordFamily":["able (adj.)","ability (n.)","inability (n.)"],"synonyms":[],"antonyms":["able"],"tipVi":"Dùng cấu trúc be unable to do, không dùng unable doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_razor', 'en-b1-57', 'razor', '/ˈreɪzər/', 'B1', 'dao cạo râu; máy cạo râu', 'n.', NULL, NULL, 'razor chỉ dụng cụ cạo râu; dao cắt thông thường gọi là knife.', 'He rinsed his razor and put it beside the sink.', NULL, 'Anh ấy rửa sạch dao cạo rồi đặt nó bên cạnh bồn rửa mặt.', '{"wordId":"razor","ukIpa":"/ˈreɪzə/","usIpa":"/ˈreɪzər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A tool with a sharp blade used to shave hair.","vi":"dao cạo râu; máy cạo râu"}],"examples":[{"en":"He rinsed his razor and put it beside the sink.","vi":"Anh ấy rửa sạch dao cạo rồi đặt nó bên cạnh bồn rửa mặt.","audioKind":"ex"},{"en":"Choosing a reusable razor can reduce the amount of plastic waste generated by daily grooming.","vi":"Lựa chọn dao cạo có thể tái sử dụng giúp giảm lượng rác thải nhựa phát sinh từ việc chăm sóc cá nhân hằng ngày.","audioKind":"ex2"}],"collocations":[{"en":"electric razor","vi":"máy cạo râu điện"},{"en":"disposable razor","vi":"dao cạo dùng một lần"},{"en":"razor blade","vi":"lưỡi dao cạo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"razor chỉ dụng cụ cạo râu; dao cắt thông thường gọi là knife.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_57_1', 'en-b1-57', 'Cách dùng “balance” (n.) — sự cân bằng; sự hài hòa', 'keep your balance  ·  strike a balance  ·  work-life balance', 'Để diễn tả việc cân bằng giữa hai yếu tố, hãy dùng cấu trúc balance A with B; còn dạng tính từ của sự cân bằng là balanced.', 'Họ từ (Word Family): balanced (adj.), unbalanced (adj.), imbalance (n.) | Đồng nghĩa: equilibrium · Trái nghĩa: imbalance', '[{"hanzi":"She lost her balance while stepping off the bus.","pinyin":"","meaning":"Cô ấy bị mất thăng bằng khi bước xuống xe buýt."},{"hanzi":"Governments must balance the demand for affordable housing with the need to protect green spaces.","pinyin":"","meaning":"Chính phủ phải cân đối giữa nhu cầu về nhà ở giá rẻ và nhu cầu bảo vệ không gian xanh."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_57_2', 'en-b1-57', 'Cách dùng “upside-down” (adj.) — lộn ngược; đảo ngược', 'an upside-down image  ·  an upside-down bowl  ·  turn something upside down', 'Thường có dấu gạch nối khi đứng trước danh từ; khi làm vị ngữ hoặc trạng ngữ thì thường viết là upside down.', 'Đồng nghĩa: inverted', '[{"hanzi":"An upside-down bowl covered the last slice of cake.","pinyin":"","meaning":"Một chiếc bát úp ngược đã che đậy miếng bánh ngọt cuối cùng."},{"hanzi":"In a classroom experiment, students used an upside-down glass of water to explore the effects of air pressure.","pinyin":"","meaning":"Trong một thí nghiệm trên lớp, học sinh đã dùng một cốc nước úp ngược để khám phá tác động của áp suất khí quyển."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_57_3', 'en-b1-57', 'Cách dùng “babysitter” (n.) — người trông trẻ tạm thời', 'hire a babysitter  ·  reliable babysitter  ·  find a babysitter', 'Thường chỉ người nhận trông giữ trẻ giúp trong thời gian ngắn, không giới hạn chỉ chăm sóc mỗi trẻ sơ sinh.', 'Họ từ (Word Family): babysit (v.), babysitting (n.)', '[{"hanzi":"The babysitter read a story while the children ate.","pinyin":"","meaning":"Người trông trẻ đã đọc một câu chuyện trong lúc lũ trẻ ăn uống."},{"hanzi":"Finding a reliable babysitter can help parents balance occasional evening commitments with their childcare responsibilities.","pinyin":"","meaning":"Tìm kiếm một người trông trẻ đáng tin cậy có thể giúp các bậc cha mẹ cân bằng giữa các cam kết buổi tối không thường xuyên với trách nhiệm chăm sóc con cái."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_57_4', 'en-b1-57', 'Cách dùng “permanent” (adj.) — vĩnh viễn; lâu dài; thường xuyên', 'permanent damage  ·  permanent resident  ·  permanent job', 'permanent job chỉ công việc không có thời hạn kết thúc cố định, chứ không đảm bảo được biên chế suốt đời.', 'Họ từ (Word Family): permanently (adv.), permanence (n.), impermanent (adj.) | Đồng nghĩa: lasting · Trái nghĩa: temporary', '[{"hanzi":"The hot pan left a permanent mark on the table.","pinyin":"","meaning":"Chiếc chảo nóng đã để lại một vết hằn vĩnh viễn trên bàn."},{"hanzi":"Investment in flood prevention can reduce the risk of permanent damage to homes and public infrastructure.","pinyin":"","meaning":"Đầu tư vào phòng chống lũ lụt có thể làm giảm nguy cơ tổn hại lâu dài cho nhà cửa và cơ sở hạ tầng công cộng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_57_1', 'en-b1-57', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
