INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_57_1_2', 'ten_b1_57_1', 'nut', 'She cracked a nut and shared the kernel with me.', 'She cracked a nut and shared the kernel with me.', '/nʌt/', 'Cô ấy đập một quả hạch rồi chia phần nhân cho tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_57_1_3', 'ten_b1_57_1', 'perfectly', 'The new curtains match our sofa perfectly.', 'The new curtains match our sofa perfectly.', '/ˈpɝːfɪktli/', 'Bộ rèm cửa mới rất hợp với chiếc ghế sofa của chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_57_1_4', 'ten_b1_57_1', 'proper', 'You need proper shoes for walking on rocky paths.', 'You need proper shoes for walking on rocky paths.', '/ˈprɑːpər/', 'Bạn cần mang giày thích hợp để đi trên những con đường đá lởm chởm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_57_1_5', 'ten_b1_57_1', 'softly', 'She spoke softly so the sleeping baby would not wake.', 'She spoke softly so the sleeping baby would not wake.', '/ˈsɔːftli/', 'Cô ấy nói chuyện nhỏ nhẹ để em bé đang ngủ không bị thức giấc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
