INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_57_1_7', 'ten_b1_57_1', 'spare', 'I keep a spare umbrella in my car.', 'I keep a spare umbrella in my car.', '/sper/', 'Tôi giữ một chiếc ô dự phòng trong xe hơi của mình.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_57_1_8', 'ten_b1_57_1', 'outfit', 'She chose a bright outfit for her birthday party.', 'She chose a bright outfit for her birthday party.', '/ˈaʊtfɪt/', 'Cô ấy chọn một bộ trang phục rực rỡ cho bữa tiệc sinh nhật của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_57_1_1', 'en-b1-57', 'ten_b1_57_1', 'listening', 'listening', 'I have met your sister on several occasions.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin vui lòng thắt dây an toàn trước khi chúng ta khởi hành.","Ngoài táo ra, chúng tôi cần thêm một ít bánh mì và sữa tươi.","Bạn cần mang giày thích hợp để đi trên những con đường đá lởm chởm.","Tôi đã gặp chị gái của bạn vài lần rồi."]'::jsonb, 3, 'I have met your sister on several occasions. → Tôi đã gặp chị gái của bạn vài lần rồi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_57_1_2', 'en-b1-57', 'ten_b1_57_1', 'listening', 'listening', 'She cracked a nut and shared the kernel with me.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn có thể di chuyển chiếc đèn đến một vị trí tốt hơn không?","Cô ấy đập một quả hạch rồi chia phần nhân cho tôi.","Ngoài táo ra, chúng tôi cần thêm một ít bánh mì và sữa tươi.","Một chiếc bát úp ngược đã che đậy miếng bánh ngọt cuối cùng."]'::jsonb, 1, 'She cracked a nut and shared the kernel with me. → Cô ấy đập một quả hạch rồi chia phần nhân cho tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_57_1_3', 'en-b1-57', 'ten_b1_57_1', 'listening', 'listening', 'The new curtains match our sofa perfectly.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy bị mất thăng bằng khi bước xuống xe buýt.","Chúng tôi đã nấu một bữa ăn đặc biệt cho ngày kỷ niệm ngày cưới của mình.","Anh ấy rửa sạch dao cạo rồi đặt nó bên cạnh bồn rửa mặt.","Bộ rèm cửa mới rất hợp với chiếc ghế sofa của chúng tôi."]'::jsonb, 3, 'The new curtains match our sofa perfectly. → Bộ rèm cửa mới rất hợp với chiếc ghế sofa của chúng tôi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_57_2', 'en-b1-57', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_57_2_1', 'ten_b1_57_2', 'occasion', 'Community festivals provide an occasion for residents from different backgrounds to share traditions and build friendships.', 'Community festivals provide an occasion for residents from different backgrounds to share traditions and build friendships.', '/əˈkeɪʒən/', 'Các lễ hội cộng đồng tạo cơ hội cho người dân từ các hoàn cảnh khác nhau chia sẻ truyền thống và xây dựng tình bạn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_57_2_2', 'ten_b1_57_2', 'nut', 'Nuts provide useful nutrients, although schools must consider food allergies when planning meals for children.', 'Nuts provide useful nutrients, although schools must consider food allergies when planning meals for children.', '/nʌt/', 'Các loại hạt cung cấp chất dinh dưỡng có lợi, mặc dù nhà trường phải lưu ý vấn đề dị ứng thực phẩm khi lên thực đơn cho trẻ em.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_57_2_3', 'ten_b1_57_2', 'perfectly', 'It is perfectly reasonable for residents to expect reliable public services in return for their taxes.', 'It is perfectly reasonable for residents to expect reliable public services in return for their taxes.', '/ˈpɝːfɪktli/', 'Việc cư dân mong đợi các dịch vụ công đáng tin cậy để đổi lấy tiền thuế của họ là điều hoàn toàn hợp lý.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_57_2_4', 'ten_b1_57_2', 'proper', 'Workers should receive proper training before operating machinery that could pose a risk to their safety.', 'Workers should receive proper training before operating machinery that could pose a risk to their safety.', '/ˈprɑːpər/', 'Công nhân nên được đào tạo đầy đủ trước khi vận hành máy móc có thể gây rủi ro cho sự an toàn của họ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_57_2_5', 'ten_b1_57_2', 'softly', 'In hospital wards, staff should speak softly at night to help patients rest and recover.', 'In hospital wards, staff should speak softly at night to help patients rest and recover.', '/ˈsɔːftli/', 'Trong phòng bệnh, nhân viên nên nói chuyện khẽ khàng vào ban đêm để giúp bệnh nhân nghỉ ngơi và hồi phục.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
