INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_57_2', 'en-b1-57', NULL, 'comprehensive_test', 'listening', 'She cracked a nut and shared the kernel with me.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc ô bị gãy này hoàn toàn vô dụng trong trận mưa lớn.","Làm ơn đừng phớt lờ tiếng động kỳ lạ phát ra từ động cơ đó.","Cô ấy đập một quả hạch rồi chia phần nhân cho tôi.","Chúng tôi đã đào một cái hố sâu cho cây táo non."]'::jsonb, 2, 'She cracked a nut and shared the kernel with me. → Cô ấy đập một quả hạch rồi chia phần nhân cho tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_57_3', 'en-b1-57', NULL, 'comprehensive_test', 'listening', 'perfectly', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm mệt mỏi; mệt mỏi","hoàn hảo; không tì vết","cái kẹp; kẹp giấy","hứng thú; say mê; khao khát"]'::jsonb, 1, 'perfectly (/ˈpɝːfɪktli/) → hoàn hảo; không tì vết; hoàn toàn; hết sức', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_57_4', 'en-b1-57', NULL, 'comprehensive_test', 'listening', 'You need proper shoes for walking on rocky paths.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi bê khay đựng bữa trưa đến cửa sổ nhà ăn.","Cô ấy nói chuyện nhỏ nhẹ để em bé đang ngủ không bị thức giấc.","Bạn cần mang giày thích hợp để đi trên những con đường đá lởm chởm.","Chúng tôi đã đào một cái hố sâu cho cây táo non."]'::jsonb, 2, 'You need proper shoes for walking on rocky paths. → Bạn cần mang giày thích hợp để đi trên những con đường đá lởm chởm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_57_5', 'en-b1-57', NULL, 'comprehensive_test', 'listening', 'softly', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khẽ; nhỏ nhẹ","phong tục; tập quán; thói quen truyền thống","khe hở; khoảng trống","người lớn; người trưởng thành (thường dùng khi nói chuyện với hoặc về trẻ em)"]'::jsonb, 0, 'softly (/ˈsɔːftli/) → khẽ; nhỏ nhẹ; nhẹ nhàng; dịu dàng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_57_6', 'en-b1-57', NULL, 'comprehensive_test', 'listening', 'The hot pan left a permanent mark on the table.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy lùi lại một bước để tránh vũng nước.","Chúng tôi đã đào một cái hố sâu cho cây táo non.","Chiếc chảo nóng đã để lại một vết hằn vĩnh viễn trên bàn.","Xin vui lòng thắt dây an toàn trước khi chúng ta khởi hành."]'::jsonb, 2, 'The hot pan left a permanent mark on the table. → Chiếc chảo nóng đã để lại một vết hằn vĩnh viễn trên bàn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_57_7', 'en-b1-57', NULL, 'comprehensive_test', 'listening', 'spare', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nghệ sĩ piano; người chơi đàn piano","món hời; hàng giá rẻ","dự phòng; thừa; rảnh rỗi","nhà sản xuất; hãng sản xuất; thợ thủ công"]'::jsonb, 2, 'spare (/sper/) → dự phòng; thừa; rảnh rỗi; dành ra; bố trí (thời gian, tài nguyên); giúp ai tránh khỏi; tha thứ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_57_8', 'en-b1-57', NULL, 'comprehensive_test', 'listening', 'She chose a bright outfit for her birthday party.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi thường xuyên đi dạo dọc bờ sông sau bữa tối.","Bạn có thể di chuyển chiếc đèn đến một vị trí tốt hơn không?","Thợ sửa ống nước đã đến rất nhanh vì vết rò rỉ là vấn đề khẩn cấp.","Cô ấy chọn một bộ trang phục rực rỡ cho bữa tiệc sinh nhật của mình."]'::jsonb, 3, 'She chose a bright outfit for her birthday party. → Cô ấy chọn một bộ trang phục rực rỡ cho bữa tiệc sinh nhật của mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
