INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_57_18', 'en-b1-57', NULL, 'comprehensive_test', 'reading', NULL, 'Community festivals provide an occasion for residents from different backgrounds to share traditions and build friendships.', 'Dựa vào câu trên, từ “occasion” có nghĩa phù hợp nhất là gì?', '["chật; bó sát; chặt","hỗn hợp; thể hòa trộn","dịp; lần","không có khả năng; khó xảy ra"]'::jsonb, 2, 'occasion: dịp; lần; dịp đặc biệt; sự kiện trọng đại; cơ hội; thời cơ. Dịch cả câu: Các lễ hội cộng đồng tạo cơ hội cho người dân từ các hoàn cảnh khác nhau chia sẻ truyền thống và xây dựng tình bạn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_57_19', 'en-b1-57', NULL, 'comprehensive_test', 'reading', NULL, 'Nuts provide useful nutrients, although schools must consider food allergies when planning meals for children.', 'Dựa vào câu trên, từ “nut” có nghĩa phù hợp nhất là gì?', '["thợ điện; kỹ thuật viên điện","sự ôn tập; sự học tập lại","quả hạch; hạt cứng","biết ơn; cảm kích"]'::jsonb, 2, 'nut: quả hạch; hạt cứng; đai ốc; con ốc; ốc vít. Dịch cả câu: Các loại hạt cung cấp chất dinh dưỡng có lợi, mặc dù nhà trường phải lưu ý vấn đề dị ứng thực phẩm khi lên thực đơn cho trẻ em.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_57_20', 'en-b1-57', NULL, 'comprehensive_test', 'reading', NULL, 'It is perfectly reasonable for residents to expect reliable public services in return for their taxes.', 'Dựa vào câu trên, từ “perfectly” có nghĩa phù hợp nhất là gì?', '["hoàn hảo; không tì vết","lối đi lát đá bên cạnh đường dành cho người đi bộ","đang diễn ra, đang tồn tại hoặc đang được sử dụng ở hiện tại; hiện tại; hiện hành","kẻ ngốc; người hành động thiếu khôn ngoan"]'::jsonb, 0, 'perfectly: hoàn hảo; không tì vết; hoàn toàn; hết sức. Dịch cả câu: Việc cư dân mong đợi các dịch vụ công đáng tin cậy để đổi lấy tiền thuế của họ là điều hoàn toàn hợp lý.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_57_21', 'en-b1-57', NULL, 'comprehensive_test', 'reading', NULL, 'Workers should receive proper training before operating machinery that could pose a risk to their safety.', 'Dựa vào câu trên, từ “proper” có nghĩa phù hợp nhất là gì?', '["thích hợp; đúng đắn","khán giả; thính giả","xác nhận; chứng thực","truyện trinh thám ly kỳ; phim kinh dị ly kỳ"]'::jsonb, 0, 'proper: thích hợp; đúng đắn; ra trò; đích thực; tử tế; nghĩa đen; chính cống; tự thân. Dịch cả câu: Công nhân nên được đào tạo đầy đủ trước khi vận hành máy móc có thể gây rủi ro cho sự an toàn của họ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
