INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_57_24', 'en-b1-57', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dao cạo râu; máy cạo râu”', '["object","razor","hunting","element"]'::jsonb, 1, 'dao cạo râu; máy cạo râu → razor (/ˈreɪzər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-58', 'en', 'Bài 58: Đời sống hằng ngày (10) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3058, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_material', 'en-b1-58', 'material', '/məˈtɪriəl/', 'B1', 'vật liệu; nguyên liệu; vải vóc; tài liệu; tư liệu; thuộc về vật chất; thiết yếu', 'n.', 'materialism (n.), materialist (n.), materialistic (adj.), materially (adv.)', 'Trái nghĩa: immaterial', 'Nghĩa tài liệu thường không đếm được; nhiều loại vật liệu có thể dùng "materials".', 'This bag is made from a strong waterproof material.', NULL, 'Chiếc túi này được làm từ một loại vật liệu chống thấm nước bền chắc.', '{"wordId":"material","ukIpa":"/məˈtɪəriəl/","usIpa":"/məˈtɪriəl/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A substance used to make things, including cloth.","vi":"vật liệu; nguyên liệu; vải vóc"},{"pos":"n.","en":"Information or ideas used for study or creative work.","vi":"tài liệu; tư liệu"},{"pos":"adj.","en":"Relating to physical possessions, or significant enough to matter.","vi":"thuộc về vật chất; thiết yếu"}],"examples":[{"en":"This bag is made from a strong waterproof material.","vi":"Chiếc túi này được làm từ một loại vật liệu chống thấm nước bền chắc.","audioKind":"ex"},{"en":"Using recycled material in construction can reduce waste and lower demand for newly extracted natural resources.","vi":"Việc sử dụng vật liệu tái chế trong xây dựng có thể giảm thiểu rác thải và hạ thấp nhu cầu khai thác tài nguyên thiên nhiên mới.","audioKind":"ex2"}],"collocations":[{"en":"raw materials","vi":"nguyên liệu thô"},{"en":"building materials","vi":"vật liệu xây dựng"},{"en":"reading material","vi":"tài liệu đọc"},{"en":"material possessions","vi":"tài sản vật chất"}],"wordFamily":["materialism (n.)","materialist (n.)","materialistic (adj.)","materially (adv.)"],"synonyms":[],"antonyms":["immaterial"],"tipVi":"Nghĩa tài liệu thường không đếm được; nhiều loại vật liệu có thể dùng \"materials\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tight', 'en-b1-58', 'tight', '/taɪt/', 'B1', 'chật; bó sát; chặt; eo hẹp; căng thẳng (thời gian, tiền bạc, không gian); chặt chẽ; vững chắc', 'adj.', 'tightly (adv.), tighten (v.), tightness (n.)', 'Đồng nghĩa: snug · Trái nghĩa: loose', 'Bản thân "tight" có thể làm trạng từ, ví dụ "hold tight"; "tightly" cũng mang nghĩa chặt chẽ.', 'These shoes are too tight around my toes.', NULL, 'Đôi giày này quá chật ở phần mũi, làm đau các ngón chân của tôi.', '{"wordId":"tight","ukIpa":"/taɪt/","usIpa":"/taɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Fitting closely or held firmly, with little room to move.","vi":"chật; bó sát; chặt"},{"pos":"adj.","en":"Leaving very little extra time, money, or space.","vi":"eo hẹp; căng thẳng (thời gian, tiền bạc, không gian)"},{"pos":"adv.","en":"Firmly and securely, without becoming loose.","vi":"chặt chẽ; vững chắc"}],"examples":[{"en":"These shoes are too tight around my toes.","vi":"Đôi giày này quá chật ở phần mũi, làm đau các ngón chân của tôi.","audioKind":"ex"},{"en":"Schools operating on tight budgets may struggle to provide students with modern equipment and adequate support.","vi":"Các trường học hoạt động với ngân sách eo hẹp có thể gặp khó khăn trong việc cung cấp cho học sinh thiết bị hiện đại và sự hỗ trợ đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"tight jeans","vi":"quần jean bó sát"},{"en":"a tight budget","vi":"ngân sách eo hẹp"},{"en":"a tight deadline","vi":"thời hạn gấp rút"},{"en":"hold tight","vi":"giữ chặt"}],"wordFamily":["tightly (adv.)","tighten (v.)","tightness (n.)"],"synonyms":["snug"],"antonyms":["loose"],"tipVi":"Bản thân \"tight\" có thể làm trạng từ, ví dụ \"hold tight\"; \"tightly\" cũng mang nghĩa chặt chẽ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_well-dressed', 'en-b1-58', 'well-dressed', '/ˌwel ˈdrest/', 'B1', 'ăn mặc chỉn chu; ăn mặc lịch sự', 'adj.', 'dress (v.), dressed (adj.)', 'Đồng nghĩa: smartly dressed · Trái nghĩa: badly dressed', 'Nhấn mạnh việc ăn mặc gọn gàng, lịch sự, không nhất thiết là quần áo đắt tiền hay chạy theo mốt.', 'A well-dressed guest arrived in a neatly pressed suit.', NULL, 'Một vị khách ăn mặc lịch sự bước vào trong bộ vest được là ủi phẳng phiu.', '{"wordId":"well-dressed","ukIpa":"/ˌwel ˈdrest/","usIpa":"/ˌwel ˈdrest/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Wearing attractive, neat, and appropriate clothes.","vi":"ăn mặc chỉn chu; ăn mặc lịch sự"}],"examples":[{"en":"A well-dressed guest arrived in a neatly pressed suit.","vi":"Một vị khách ăn mặc lịch sự bước vào trong bộ vest được là ủi phẳng phiu.","audioKind":"ex"},{"en":"Although well-dressed applicants may create positive first impressions, employers should prioritise relevant skills and professional experience.","vi":"Mặc dù những ứng viên ăn mặc chỉn chu có thể tạo ấn tượng ban đầu tốt đẹp, nhà tuyển dụng vẫn nên ưu tiên các kỹ năng liên quan và kinh nghiệm chuyên môn.","audioKind":"ex2"}],"collocations":[{"en":"well-dressed guests","vi":"những vị khách ăn mặc lịch sự"},{"en":"a well-dressed applicant","vi":"một ứng viên ăn mặc chỉn chu"}],"wordFamily":["dress (v.)","dressed (adj.)"],"synonyms":["smartly dressed"],"antonyms":["badly dressed"],"tipVi":"Nhấn mạnh việc ăn mặc gọn gàng, lịch sự, không nhất thiết là quần áo đắt tiền hay chạy theo mốt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grown-up', 'en-b1-58', 'grown-up', '/ˈɡroʊn ʌp/', 'B1', 'người lớn; người trưởng thành (thường dùng khi nói chuyện với hoặc về trẻ em); trưởng thành; có cách hành xử chín chắn và có trách nhiệm', 'n.', 'grow (v.), growth (n.)', 'Đồng nghĩa: adult', 'Danh từ nhiều khi dùng trong ngữ cảnh trẻ em; văn phong trang trọng nên dùng adult.', 'Ask a grown-up to help you slice the bread.', NULL, 'Hãy nhờ một người lớn giúp bạn cắt bánh mì nhé.', '{"wordId":"grown-up","ukIpa":"/ˈɡrəʊn ʌp/","usIpa":"/ˈɡroʊn ʌp/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"An adult, especially when described by or to children.","vi":"người lớn; người trưởng thành (thường dùng khi nói chuyện với hoặc về trẻ em)"},{"pos":"adj.","en":"Adult, or behaving in a sensible and responsible way.","vi":"trưởng thành; có cách hành xử chín chắn và có trách nhiệm"}],"examples":[{"en":"Ask a grown-up to help you slice the bread.","vi":"Hãy nhờ một người lớn giúp bạn cắt bánh mì nhé.","audioKind":"ex"},{"en":"Children often develop grown-up attitudes towards responsibility when they participate in age-appropriate household tasks.","vi":"Trẻ em thường phát triển thái độ trưởng thành đối với trách nhiệm khi các em tham gia vào những công việc nhà phù hợp với lứa tuổi.","audioKind":"ex2"}],"collocations":[{"en":"ask a grown-up","vi":"nhờ người lớn"},{"en":"grown-up children","vi":"con cái đã trưởng thành"},{"en":"a grown-up attitude","vi":"thái độ trưởng thành"}],"wordFamily":["grow (v.)","growth (n.)"],"synonyms":["adult"],"antonyms":[],"tipVi":"Danh từ nhiều khi dùng trong ngữ cảnh trẻ em; văn phong trang trọng nên dùng adult.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hidden', 'en-b1-58', 'hidden', '/ˈhɪdən/', 'B1', 'bị che khuất; ẩn giấu; khó nhận thấy', 'adj.', 'hide (v.), hiding (n.)', 'Đồng nghĩa: concealed, unseen · Trái nghĩa: visible, obvious', 'Cũng là quá khứ phân từ của hide; ẩn giấu không có nghĩa là mắt thường hoàn toàn không thể nhìn thấy.', 'We found a hidden cupboard behind the kitchen door.', NULL, 'Chúng tôi tìm thấy một chiếc tủ ẩn sau cánh cửa bếp.', '{"wordId":"hidden","ukIpa":"/ˈhɪdən/","usIpa":"/ˈhɪdən/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Kept out of sight or not easily noticed.","vi":"bị che khuất; ẩn giấu; khó nhận thấy"}],"examples":[{"en":"We found a hidden cupboard behind the kitchen door.","vi":"Chúng tôi tìm thấy một chiếc tủ ẩn sau cánh cửa bếp.","audioKind":"ex"},{"en":"Consumers should consider the hidden costs of online purchases, including delivery fees and charges for returning items.","vi":"Người tiêu dùng nên cân nhắc các chi phí ẩn khi mua sắm trực tuyến, bao gồm phí vận chuyển và phí trả lại hàng.","audioKind":"ex2"}],"collocations":[{"en":"hidden costs","vi":"chi phí ẩn"},{"en":"hidden meaning","vi":"ý nghĩa ẩn"},{"en":"hidden talent","vi":"tài năng tiềm ẩn"}],"wordFamily":["hide (v.)","hiding (n.)"],"synonyms":["concealed","unseen"],"antonyms":["visible","obvious"],"tipVi":"Cũng là quá khứ phân từ của hide; ẩn giấu không có nghĩa là mắt thường hoàn toàn không thể nhìn thấy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uncomfortable', 'en-b1-58', 'uncomfortable', '/ʌnˈkʌmftɚbəl/', 'B1', 'không thoải mái; gây khó chịu về thể chất; bất an; ngượng ngùng; lúng túng', 'adj.', 'comfortable (adj.), comfort (n.), discomfort (n.), uncomfortably (adv.)', 'Đồng nghĩa: uneasy · Trái nghĩa: comfortable', 'Từ này vừa có thể chỉ cảm giác khó chịu về thể chất, vừa chỉ sự bất an hoặc ngượng ngùng về tâm lý.', 'These new shoes feel uncomfortable after a long walk.', NULL, 'Đôi giày mới này mang lại cảm giác không thoải mái sau một quãng đường đi bộ dài.', '{"wordId":"uncomfortable","ukIpa":"/ʌnˈkʌmftəbəl/","usIpa":"/ʌnˈkʌmftɚbəl/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Causing or feeling physical discomfort.","vi":"không thoải mái; gây khó chịu về thể chất"},{"pos":"adj.","en":"Feeling worried, embarrassed, or uneasy.","vi":"bất an; ngượng ngùng; lúng túng"}],"examples":[{"en":"These new shoes feel uncomfortable after a long walk.","vi":"Đôi giày mới này mang lại cảm giác không thoải mái sau một quãng đường đi bộ dài.","audioKind":"ex"},{"en":"Students may feel uncomfortable asking questions in large classes, which can limit their participation and understanding.","vi":"Học sinh có thể cảm thấy ngượng ngùng khi đặt câu hỏi trong các lớp học lớn, điều này có thể hạn chế sự tham gia và mức độ hiểu bài của các em.","audioKind":"ex2"}],"collocations":[{"en":"an uncomfortable chair","vi":"một chiếc ghế không thoải mái"},{"en":"feel uncomfortable","vi":"cảm thấy khó chịu"},{"en":"an uncomfortable silence","vi":"sự im lặng đến ngượng ngùng"}],"wordFamily":["comfortable (adj.)","comfort (n.)","discomfort (n.)","uncomfortably (adv.)"],"synonyms":["uneasy"],"antonyms":["comfortable"],"tipVi":"Từ này vừa có thể chỉ cảm giác khó chịu về thể chất, vừa chỉ sự bất an hoặc ngượng ngùng về tâm lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peel', 'en-b1-58', 'peel', '/piːl/', 'B1', 'gọt vỏ; bóc vỏ; bong ra; tróc ra; vỏ trái cây; vỏ rau củ', 'v.', 'peeler (n.), peelings (n.)', NULL, 'peel khi làm động từ có thể chỉ việc gọt vỏ, hoặc chỉ việc lớp sơn và các bề mặt bị bong tróc.', 'Could you peel these potatoes while I chop the carrots?', NULL, 'Bạn có thể gọt vỏ những củ khoai tây này trong lúc tôi thái cà rốt không?', '{"wordId":"peel","ukIpa":"/piːl/","usIpa":"/piːl/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To remove the outer skin of fruit or vegetables.","vi":"gọt vỏ; bóc vỏ"},{"pos":"v.","en":"To come off a surface in thin pieces.","vi":"bong ra; tróc ra"},{"pos":"n.","en":"The outer skin of a fruit or vegetable.","vi":"vỏ trái cây; vỏ rau củ"}],"examples":[{"en":"Could you peel these potatoes while I chop the carrots?","vi":"Bạn có thể gọt vỏ những củ khoai tây này trong lúc tôi thái cà rốt không?","audioKind":"ex"},{"en":"Households can compost vegetable peels rather than discard them, reducing the amount of waste sent to landfill.","vi":"Các hộ gia đình có thể ủ vỏ rau củ thay vì vứt bỏ chúng, qua đó làm giảm lượng rác thải đem chôn lấp.","audioKind":"ex2"}],"collocations":[{"en":"peel potatoes","vi":"gọt vỏ khoai tây"},{"en":"orange peel","vi":"vỏ cam"},{"en":"peeling paint","vi":"sơn bị bong tróc"}],"wordFamily":["peeler (n.)","peelings (n.)"],"synonyms":[],"antonyms":[],"tipVi":"peel khi làm động từ có thể chỉ việc gọt vỏ, hoặc chỉ việc lớp sơn và các bề mặt bị bong tróc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fully', 'en-b1-58', 'fully', '/ˈfʊli/', 'B1', 'hoàn toàn; đầy đủ; hoàn trọn', 'adv.', 'full (adj.), fullness (n.)', 'Đồng nghĩa: completely, entirely · Trái nghĩa: partly, partially', 'Thường bổ nghĩa cho phân từ hoặc tính từ, ví dụ như fully prepared.', 'Make sure your phone is fully charged before leaving.', NULL, 'Hãy đảm bảo điện thoại của bạn đã được sạc đầy trước khi rời đi.', '{"wordId":"fully","ukIpa":"/ˈfʊli/","usIpa":"/ˈfʊli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"Completely or to the greatest possible extent.","vi":"hoàn toàn; đầy đủ; hoàn trọn"}],"examples":[{"en":"Make sure your phone is fully charged before leaving.","vi":"Hãy đảm bảo điện thoại của bạn đã được sạc đầy trước khi rời đi.","audioKind":"ex"},{"en":"Students benefit most from online learning when they fully understand how to use the available digital tools.","vi":"Học sinh nhận được lợi ích nhiều nhất từ việc học trực tuyến khi các em hiểu rõ cách sử dụng các công cụ kỹ thuật số có sẵn.","audioKind":"ex2"}],"collocations":[{"en":"fully aware","vi":"nhận thức rõ; hoàn toàn ý thức"},{"en":"fully equipped","vi":"được trang bị đầy đủ"},{"en":"fully understand","vi":"hiểu rõ; thấu hiểu"},{"en":"fully booked","vi":"đã kín chỗ; đã đặt hết"}],"wordFamily":["full (adj.)","fullness (n.)"],"synonyms":["completely","entirely"],"antonyms":["partly","partially"],"tipVi":"Thường bổ nghĩa cho phân từ hoặc tính từ, ví dụ như fully prepared.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spot', 'en-b1-58', 'spot', '/spɑːt/', 'B1', 'nơi; địa điểm; chốn; vết; đốm; nốt; phát hiện; nhận ra; bắt gặp', 'n.', 'spotty (adj.), spotless (adj.)', NULL, 'on the spot có thể mang nghĩa là "ngay tại chỗ" hoặc "tại hiện trường", tùy thuộc vào ngữ cảnh.', 'We found a shady spot beside the river.', NULL, 'Chúng tôi tìm thấy một góc râm mát bên bờ sông.', '{"wordId":"spot","ukIpa":"/spɒt/","usIpa":"/spɑːt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A particular place or position.","vi":"nơi; địa điểm; chốn"},{"pos":"n.","en":"A small mark differing in colour from its surroundings.","vi":"vết; đốm; nốt"},{"pos":"v.","en":"Notice or recognise someone or something.","vi":"phát hiện; nhận ra; bắt gặp"}],"examples":[{"en":"We found a shady spot beside the river.","vi":"Chúng tôi tìm thấy một góc râm mát bên bờ sông.","audioKind":"ex"},{"en":"Satellite images help researchers spot changes in forest cover before extensive damage occurs.","vi":"Hình ảnh vệ tinh giúp các nhà nghiên cứu phát hiện ra sự thay đổi về độ che phủ của rừng trước khi những tổn hại diện rộng xảy ra.","audioKind":"ex2"}],"collocations":[{"en":"a quiet spot","vi":"một nơi yên tĩnh"},{"en":"on the spot","vi":"ngay tại chỗ; ngay lập tức"},{"en":"spot a mistake","vi":"phát hiện lỗi"},{"en":"a tourist spot","vi":"điểm du lịch"}],"wordFamily":["spotty (adj.)","spotless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"on the spot có thể mang nghĩa là \"ngay tại chỗ\" hoặc \"tại hiện trường\", tùy thuộc vào ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ought', 'en-b1-58', 'ought', '/ɔːt/', 'B1', 'nên; phải (chỉ lời khuyên, bổn phận hoặc hành động đúng đắn); có lẽ; chắc là (chỉ điều có khả năng xảy ra hoặc được mong đợi)', 'v.', NULL, 'Đồng nghĩa: should', 'ought là động từ khuyết thiếu, theo sau là to do; dạng phủ định là ought not to.', 'You ought to take an umbrella; those clouds look dark.', NULL, 'Bạn nên mang theo ô; mấy đám mây kia trông có vẻ âm u lắm.', '{"wordId":"ought","ukIpa":"/ɔːt/","usIpa":"/ɔːt/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Used with to for advice, duty, or the right action.","vi":"nên; phải (chỉ lời khuyên, bổn phận hoặc hành động đúng đắn)"},{"pos":"v.","en":"Used with to to express what is likely or expected.","vi":"có lẽ; chắc là (chỉ điều có khả năng xảy ra hoặc được mong đợi)"}],"examples":[{"en":"You ought to take an umbrella; those clouds look dark.","vi":"Bạn nên mang theo ô; mấy đám mây kia trông có vẻ âm u lắm.","audioKind":"ex"},{"en":"Governments ought to ensure that all children have access to quality education, regardless of family income.","vi":"Chính phủ nên đảm bảo rằng tất cả trẻ em đều được tiếp cận giáo dục chất lượng, không phân biệt thu nhập gia đình.","audioKind":"ex2"}],"collocations":[{"en":"ought to do","vi":"nên làm"},{"en":"ought not to do","vi":"không nên làm"},{"en":"ought to have done","vi":"lẽ ra nên làm"}],"wordFamily":[],"synonyms":["should"],"antonyms":[],"tipVi":"ought là động từ khuyết thiếu, theo sau là to do; dạng phủ định là ought not to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_napkin', 'en-b1-58', 'napkin', '/ˈnæpkɪn/', 'B1', 'khăn ăn; giấy ăn', 'n.', NULL, 'Đồng nghĩa: serviette', 'Ngày nay thường chỉ khăn ăn; từ "tã lót" tiếng Anh-Anh thường dùng nappy.', 'He wiped the soup from his chin with a napkin.', NULL, 'Anh ấy dùng khăn ăn để lau vết súp dính trên cằm.', '{"wordId":"napkin","ukIpa":"/ˈnæpkɪn/","usIpa":"/ˈnæpkɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Cloth or paper used to wipe your mouth while eating","vi":"khăn ăn; giấy ăn"}],"examples":[{"en":"He wiped the soup from his chin with a napkin.","vi":"Anh ấy dùng khăn ăn để lau vết súp dính trên cằm.","audioKind":"ex"},{"en":"Restaurants can reduce waste by replacing disposable paper napkins with reusable cloth alternatives, provided laundering is managed efficiently.","vi":"Các nhà hàng có thể giảm rác thải bằng cách thay thế khăn giấy dùng một lần bằng khăn vải dùng lại được, miễn là công tác giặt giủi được quản lý hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"a paper napkin","vi":"khăn giấy ăn"},{"en":"a cloth napkin","vi":"khăn ăn bằng vải"},{"en":"fold a napkin","vi":"gấp khăn ăn"}],"wordFamily":[],"synonyms":["serviette"],"antonyms":[],"tipVi":"Ngày nay thường chỉ khăn ăn; từ \"tã lót\" tiếng Anh-Anh thường dùng nappy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_porridge', 'en-b1-58', 'porridge', '/ˈpɔːrɪdʒ/', 'B1', 'cháo yến mạch; cháo đặc', 'n.', NULL, NULL, 'Thường là danh từ không đếm được; dùng a bowl of để chỉ một bát.', 'I topped my warm porridge with sliced banana.', NULL, 'Tôi rắc vài lát chuối lên bát cháo yến mạch còn đang ấm.', '{"wordId":"porridge","ukIpa":"/ˈpɒrɪdʒ/","usIpa":"/ˈpɔːrɪdʒ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A thick breakfast dish made by cooking oats in liquid.","vi":"cháo yến mạch; cháo đặc"}],"examples":[{"en":"I topped my warm porridge with sliced banana.","vi":"Tôi rắc vài lát chuối lên bát cháo yến mạch còn đang ấm.","audioKind":"ex"},{"en":"Schools can offer porridge at breakfast to provide pupils with an affordable and nutritious meal.","vi":"Các trường học có thể phục vụ cháo yến mạch vào bữa sáng để cung cấp cho học sinh một bữa ăn giá cả phải chăng và giàu dinh dưỡng.","audioKind":"ex2"}],"collocations":[{"en":"a bowl of porridge","vi":"một bát cháo yến mạch"},{"en":"porridge oats","vi":"yến mạch nấu cháo"},{"en":"make porridge","vi":"nấu cháo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; dùng a bowl of để chỉ một bát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_roughly', 'en-b1-58', 'roughly', '/ˈrʌfli/', 'B1', 'khoảng chừng; đại khái; thô bạo; cộc cằn', 'adv.', 'rough (adj.), roughness (n.), roughen (v.)', 'Đồng nghĩa: approximately, about · Trái nghĩa: exactly', 'Khi dùng với nghĩa "khoảng", từ này thường đứng trước các con số; đôi khi cũng chỉ cách thức thô bạo.', 'The walk to the lake takes roughly twenty minutes.', NULL, 'Đi bộ ra hồ mất khoảng chừng hai mươi phút.', '{"wordId":"roughly","ukIpa":"/ˈrʌfli/","usIpa":"/ˈrʌfli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"approximately, rather than exactly","vi":"khoảng chừng; đại khái"},{"pos":"adv.","en":"in a forceful, careless, or uneven manner","vi":"thô bạo; cộc cằn"}],"examples":[{"en":"The walk to the lake takes roughly twenty minutes.","vi":"Đi bộ ra hồ mất khoảng chừng hai mươi phút.","audioKind":"ex"},{"en":"Roughly half of the residents surveyed supported replacing the old car park with a public garden.","vi":"Khoảng một nửa số cư dân được khảo sát ủng hộ việc biến bãi đậu xe cũ thành một khu vườn công cộng.","audioKind":"ex2"}],"collocations":[{"en":"roughly equal","vi":"xấp xỉ bằng"},{"en":"roughly speaking","vi":"nói một cách đại khái"},{"en":"treat roughly","vi":"đối xử thô bạo"}],"wordFamily":["rough (adj.)","roughness (n.)","roughen (v.)"],"synonyms":["approximately","about"],"antonyms":["exactly"],"tipVi":"Khi dùng với nghĩa \"khoảng\", từ này thường đứng trước các con số; đôi khi cũng chỉ cách thức thô bạo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tray', 'en-b1-58', 'tray', '/treɪ/', 'B1', 'khay; mâm', 'n.', NULL, NULL, 'tray thường có gờ nông, có thể dùng làm khay đựng đồ ăn hoặc khay nướng.', 'She carried two cups of tea on a wooden tray.', NULL, 'Cô ấy bưng hai tách trà trên một chiếc khay gỗ.', '{"wordId":"tray","ukIpa":"/treɪ/","usIpa":"/treɪ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A flat container with raised edges for carrying or holding things","vi":"khay; mâm"}],"examples":[{"en":"She carried two cups of tea on a wooden tray.","vi":"Cô ấy bưng hai tách trà trên một chiếc khay gỗ.","audioKind":"ex"},{"en":"Replacing disposable food trays with reusable alternatives can significantly reduce waste in school cafeterias.","vi":"Việc thay thế khay đựng thức ăn dùng một lần bằng các lựa chọn thay thế có thể tái sử dụng có thể làm giảm đáng kể lượng rác thải trong các nhà ăn trường học.","audioKind":"ex2"}],"collocations":[{"en":"a serving tray","vi":"khay phục vụ"},{"en":"a baking tray","vi":"khay nướng bánh"},{"en":"an ice cube tray","vi":"khay làm đá"},{"en":"a tray of drinks","vi":"một khay đồ uống"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"tray thường có gờ nông, có thể dùng làm khay đựng đồ ăn hoặc khay nướng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_edge', 'en-b1-58', 'edge', '/edʒ/', 'B1', 'bờ; mép; rìa; lợi thế; ưu thế vượt trội; dịch chuyển từ từ cẩn thận', 'n.', 'edgy (adj.)', NULL, 'Khi diễn tả sự vượt trội, thường dùng cụm an edge over để chỉ việc chiếm ưu thế hơn ai đó.', 'Keep your glass away from the edge of the table.', NULL, 'Đừng để ly nước của bạn sát mép bàn.', '{"wordId":"edge","ukIpa":"/edʒ/","usIpa":"/edʒ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The outer limit of an object, area, or surface.","vi":"bờ; mép; rìa"},{"pos":"n.","en":"A quality that makes someone or something more competitive.","vi":"lợi thế; ưu thế vượt trội"},{"pos":"v.","en":"To move slowly and carefully in a particular direction.","vi":"dịch chuyển từ từ cẩn thận"}],"examples":[{"en":"Keep your glass away from the edge of the table.","vi":"Đừng để ly nước của bạn sát mép bàn.","audioKind":"ex"},{"en":"Practical experience can give graduates an edge over other candidates in a competitive job market.","vi":"Kinh nghiệm thực tế có thể mang lại cho sinh viên tốt nghiệp lợi thế hơn các ứng viên khác trong thị trường việc làm cạnh tranh.","audioKind":"ex2"}],"collocations":[{"en":"on the edge of","vi":"ở bờ của"},{"en":"a competitive edge","vi":"lợi thế cạnh tranh"},{"en":"have an edge over","vi":"có lợi thế hơn"},{"en":"edge towards","vi":"dịch chuyển về phía"}],"wordFamily":["edgy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi diễn tả sự vượt trội, thường dùng cụm an edge over để chỉ việc chiếm ưu thế hơn ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_favor', 'en-b1-58', 'favor', '/ˈfeɪvər/', 'B1', 'ân huệ; sự giúp đỡ; sự ủng hộ; sự tán thành; sự quý mến; ưu ái; ủng hộ; có lợi cho', 'n.', 'favorable (adj.), favorably (adv.), favored (adj.), favoritism (n.)', NULL, 'favor là cách viết theo tiếng Mỹ, còn tiếng Anh-Anh là favour; cụm từ diễn đạt việc giúp đỡ là do a favor.', 'Could you do me a favor and water my plants?', NULL, 'Bạn có thể làm ơn giúp tôi tưới chỗ cây cối được không?', '{"wordId":"favor","ukIpa":"/ˈfeɪvə/","usIpa":"/ˈfeɪvər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"something helpful you do for someone","vi":"ân huệ; sự giúp đỡ"},{"pos":"n.","en":"approval, support, or liking for someone or something","vi":"sự ủng hộ; sự tán thành; sự quý mến"},{"pos":"v.","en":"to prefer, support, or give an advantage to","vi":"ưu ái; ủng hộ; có lợi cho"}],"examples":[{"en":"Could you do me a favor and water my plants?","vi":"Bạn có thể làm ơn giúp tôi tưới chỗ cây cối được không?","audioKind":"ex"},{"en":"Many residents favor investment in public transport because it can reduce congestion and improve access to employment.","vi":"Nhiều cư dân ủng hộ việc đầu tư vào giao thông công cộng vì nó có thể làm giảm tắc nghẽn và giúp việc di chuyển đến nơi làm việc thuận lợi hơn.","audioKind":"ex2"}],"collocations":[{"en":"do someone a favor","vi":"làm ai đó một việc"},{"en":"in favor of","vi":"ủng hộ; tán thành"},{"en":"favor one option over another","vi":"thiên vị lựa chọn này hơn lựa chọn khác"},{"en":"win favor","vi":"chiếm được cảm tìình"}],"wordFamily":["favorable (adj.)","favorably (adv.)","favored (adj.)","favoritism (n.)"],"synonyms":[],"antonyms":[],"tipVi":"favor là cách viết theo tiếng Mỹ, còn tiếng Anh-Anh là favour; cụm từ diễn đạt việc giúp đỡ là do a favor.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lid', 'en-b1-58', 'lid', '/lɪd/', 'B1', 'nắp; vung; mi mắt; mí mắt', 'n.', NULL, NULL, 'Nắp của hộp, thùng dùng lid; nắp vặn của chai lọ thường dùng cap.', 'Put the lid on before you shake the jar.', NULL, 'Hãy đậy nắp lại trước khi bạn lắc chiếc lọ.', '{"wordId":"lid","ukIpa":"/lɪd/","usIpa":"/lɪd/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a cover that closes the top of a container","vi":"nắp; vung"},{"pos":"n.","en":"either fold of skin that covers an eye","vi":"mi mắt; mí mắt"}],"examples":[{"en":"Put the lid on before you shake the jar.","vi":"Hãy đậy nắp lại trước khi bạn lắc chiếc lọ.","audioKind":"ex"},{"en":"A tightly fitted lid helps households keep food fresh and reduce unnecessary waste.","vi":"Chiếc nắp đậy khít giúp các hộ gia đình giữ thực phẩm tươi ngon và giảm thiểu lãng phí không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"a tight-fitting lid","vi":"nắp đậy khít"},{"en":"put the lid on","vi":"đậy nắp lại"},{"en":"lift the lid","vi":"nhấc nắp lên"},{"en":"keep a lid on costs","vi":"kiểm soát chi phí"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nắp của hộp, thùng dùng lid; nắp vặn của chai lọ thường dùng cap.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_listener', 'en-b1-58', 'listener', '/ˈlɪsənər/', 'B1', 'người nghe; thính giả', 'n.', 'listen (v.), listening (n.)', NULL, 'listener chỉ người nghe; listen sau khi có tân ngữ phải dùng to.', 'My sister is a patient listener when I feel worried.', NULL, 'Chị tôi là một người biết lắng nghe kiên nhẫn khi tôi cảm thấy lo lắng.', '{"wordId":"listener","ukIpa":"/ˈlɪsənə/","usIpa":"/ˈlɪsənər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"someone who listens to a person, programme, or performance","vi":"người nghe; thính giả"}],"examples":[{"en":"My sister is a patient listener when I feel worried.","vi":"Chị tôi là một người biết lắng nghe kiên nhẫn khi tôi cảm thấy lo lắng.","audioKind":"ex"},{"en":"A good listener can help colleagues resolve disagreements by understanding different perspectives before offering advice.","vi":"Một người lắng nghe tốt có thể giúp đồng nghiệp giải quyết bất đồng bằng cách thấu hiểu các góc nhìn khác nhau trước khi đưa ra lời khuyên.","audioKind":"ex2"}],"collocations":[{"en":"a good listener","vi":"một người lắng nghe tốt"},{"en":"radio listeners","vi":"thính giả nghe đài"},{"en":"an attentive listener","vi":"một người nghe chăm chú"}],"wordFamily":["listen (v.)","listening (n.)"],"synonyms":[],"antonyms":[],"tipVi":"listener chỉ người nghe; listen sau khi có tân ngữ phải dùng to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blow', 'en-b1-58', 'blow', '/bloʊ/', 'B1', 'thổi; thổi bay; đòn giáng; tai họa; cú đánh mạnh; cú đấm', 'v.', NULL, NULL, 'Động từ bất quy tắc chia theo dạng blow–blew–blown.', 'A cold wind blew leaves across the empty playground.', NULL, 'Một cơn gió lạnh thổi những chiếc lá bay qua sân chơi trống trải.', '{"wordId":"blow","ukIpa":"/bləʊ/","usIpa":"/bloʊ/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to move air, or move because of moving air","vi":"thổi; thổi bay"},{"pos":"n.","en":"an event that causes disappointment, difficulty, or loss","vi":"đòn giáng; tai họa"},{"pos":"n.","en":"a hard hit with a hand or object","vi":"cú đánh mạnh; cú đấm"}],"examples":[{"en":"A cold wind blew leaves across the empty playground.","vi":"Một cơn gió lạnh thổi những chiếc lá bay qua sân chơi trống trải.","audioKind":"ex"},{"en":"The closure of the local factory dealt a serious blow to employment opportunities in the region.","vi":"Việc đóng cửa nhà máy địa phương đã giáng một đòn nặng nề vào cơ hội việc làm trong vùng.","audioKind":"ex2"}],"collocations":[{"en":"blow out a candle","vi":"thổi tắt nến"},{"en":"blow your nose","vi":"hỉ mũi"},{"en":"a major blow","vi":"một đòn giáng lớn"},{"en":"deal a blow to","vi":"giáng một đòn vào"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ bất quy tắc chia theo dạng blow–blew–blown.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_storeroom', 'en-b1-58', 'storeroom', '/ˈstɔːrruːm/', 'B1', 'phòng kho; nhà kho', 'n.', 'store (v.), storage (n.)', 'Đồng nghĩa: storage room', 'storeroom là phòng chứa đồ; warehouse thường chỉ nhà kho lớn hơn.', 'The spare chairs are stacked neatly in the storeroom.', NULL, 'Những chiếc ghế dự phòng được xếp gọn gàng trong phòng kho.', '{"wordId":"storeroom","ukIpa":"/ˈstɔːruːm/","usIpa":"/ˈstɔːrruːm/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a room used for keeping supplies or unused things","vi":"phòng kho; nhà kho"}],"examples":[{"en":"The spare chairs are stacked neatly in the storeroom.","vi":"Những chiếc ghế dự phòng được xếp gọn gàng trong phòng kho.","audioKind":"ex"},{"en":"Schools should keep emergency supplies in a secure storeroom that staff can access quickly when necessary.","vi":"Nhà trường nên cất giữ các vật tư khẩn cấp trong một nhà kho an toàn để nhân viên có thể nhanh chóng lấy khi cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"locked storeroom","vi":"phòng kho bị khóa"},{"en":"storeroom shelves","vi":"kệ trong phòng kho"},{"en":"keep something in a storeroom","vi":"giữ vật gì trong phòng kho"}],"wordFamily":["store (v.)","storage (n.)"],"synonyms":["storage room"],"antonyms":[],"tipVi":"storeroom là phòng chứa đồ; warehouse thường chỉ nhà kho lớn hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rid', 'en-b1-58', 'rid', '/rɪd/', 'B1', 'giúp thoát khỏi; tẩy sạch', 'v.', NULL, NULL, 'Ghi nhớ cấu trúc get rid of; rid A of B có nghĩa là làm cho A sạch khỏi B.', 'We finally got rid of the broken garden chairs.', NULL, 'Cuối cùng chúng tôi cũng tống khứ được những chiếc ghế vườn đã hỏng.', '{"wordId":"rid","ukIpa":"/rɪd/","usIpa":"/rɪd/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"free someone or something from an unwanted thing","vi":"giúp thoát khỏi; tẩy sạch"}],"examples":[{"en":"We finally got rid of the broken garden chairs.","vi":"Cuối cùng chúng tôi cũng tống khứ được những chiếc ghế vườn đã hỏng.","audioKind":"ex"},{"en":"Cities can rid their streets of excessive litter by improving waste collection and encouraging responsible behaviour.","vi":"Các thành phố có thể làm sạch rác thải dư thừa trên đường phố bằng cách cải thiện việc thu gom rác và khuyến khích lối sống có trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"get rid of","vi":"thoát khỏi; vứt bỏ"},{"en":"rid something of","vi":"làm cho cái gì sạch khỏi"},{"en":"be rid of","vi":"được giải thoát khỏi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Ghi nhớ cấu trúc get rid of; rid A of B có nghĩa là làm cho A sạch khỏi B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_second-hand', 'en-b1-58', 'second-hand', '/ˌsekənd ˈhænd/', 'B1', 'đồ cũ; đã qua sử dụng; tiếp thu gián tiếp; một cách gián tiếp; từ người khác', 'adj.', NULL, 'Đồng nghĩa: used, pre-owned · Trái nghĩa: brand-new', 'Từ này vừa có thể chỉ vật dụng đã qua sử dụng, vừa có thể chỉ thông tin không phải do tự mình trải nghiệm.', 'My second-hand bicycle still rides smoothly after years of use.', NULL, 'Chiếc xe đạp cũ của tôi vẫn chạy rất mượt mà sau nhiều năm sử dụng.', '{"wordId":"second-hand","ukIpa":"/ˌsekənd ˈhænd/","usIpa":"/ˌsekənd ˈhænd/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"previously owned or used by someone else","vi":"đồ cũ; đã qua sử dụng"},{"pos":"adj.","en":"learned from others rather than through direct experience","vi":"tiếp thu gián tiếp"},{"pos":"adv.","en":"from a previous owner, or through another person''s account","vi":"một cách gián tiếp; từ người khác"}],"examples":[{"en":"My second-hand bicycle still rides smoothly after years of use.","vi":"Chiếc xe đạp cũ của tôi vẫn chạy rất mượt mà sau nhiều năm sử dụng.","audioKind":"ex"},{"en":"Buying second-hand furniture can reduce household spending and prevent usable goods from ending up in landfill.","vi":"Việc mua nội thất đã qua sử dụng có thể giúp giảm chi phí sinh hoạt và ngăn chặn các vật dụng còn dùng được bị vứt ra bãi rác.","audioKind":"ex2"}],"collocations":[{"en":"second-hand clothes","vi":"quần áo cũ"},{"en":"second-hand shop","vi":"cửa hàng đồ cũ"},{"en":"buy second-hand","vi":"mua đồ cũ"},{"en":"second-hand information","vi":"thông tin truyền miệng gián tiếp"}],"wordFamily":[],"synonyms":["used","pre-owned"],"antonyms":["brand-new"],"tipVi":"Từ này vừa có thể chỉ vật dụng đã qua sử dụng, vừa có thể chỉ thông tin không phải do tự mình trải nghiệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_remind', 'en-b1-58', 'remind', '/rɪˈmaɪnd/', 'B1', 'nhắc nhở; làm cho nhớ; làm cho nhớ đến; gợi nhắc', 'v.', 'reminder (n.)', 'Đồng nghĩa: prompt', 'Nhắc nhở ai làm gì dùng remind sb to do; làm cho ai nhớ đến ai/cái gì dùng remind sb of sth.', 'Please remind me to take my umbrella before we leave.', NULL, 'Làm ơn nhắc tôi mang theo ô trước khi chúng ta rời đi.', '{"wordId":"remind","ukIpa":"/rɪˈmaɪnd/","usIpa":"/rɪˈmaɪnd/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Help someone remember something they need to do or know","vi":"nhắc nhở; làm cho nhớ"},{"pos":"v.","en":"Make someone think of a similar person, thing, or experience","vi":"làm cho nhớ đến; gợi nhắc"}],"examples":[{"en":"Please remind me to take my umbrella before we leave.","vi":"Làm ơn nhắc tôi mang theo ô trước khi chúng ta rời đi.","audioKind":"ex"},{"en":"Schools should regularly remind students to protect their personal information when using online learning platforms.","vi":"Các trường học nên thường xuyên nhắc nhở học sinh bảo vệ thông tin cá nhân khi sử dụng các nền tảng học tập trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"remind someone to do something","vi":"nhắc nhở ai làm gì"},{"en":"remind someone of something","vi":"làm cho ai nhớ đến điều gì"},{"en":"gently remind","vi":"nhắc nhở nhẹ nhàng"}],"wordFamily":["reminder (n.)"],"synonyms":["prompt"],"antonyms":[],"tipVi":"Nhắc nhở ai làm gì dùng remind sb to do; làm cho ai nhớ đến ai/cái gì dùng remind sb of sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stripes', 'en-b1-58', 'stripes', '/straɪps/', 'B1', 'sọc; vạch; đường sọc', 'n.', 'stripe (n.), striped (adj.)', 'Đồng nghĩa: bands', 'Stripes là dạng số nhiều của stripe; tính từ "có sọc" là striped.', 'My favourite shirt has blue stripes across the front.', NULL, 'Chiếc áo sơ mi yêu thích của tôi có các sọc xanh ở mặt trước.', '{"wordId":"stripes","ukIpa":"/straɪps/","usIpa":"/straɪps/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Long narrow bands differing in colour from the surrounding surface","vi":"sọc; vạch; đường sọc"}],"examples":[{"en":"My favourite shirt has blue stripes across the front.","vi":"Chiếc áo sơ mi yêu thích của tôi có các sọc xanh ở mặt trước.","audioKind":"ex"},{"en":"Researchers investigate how zebra stripes may discourage biting insects, potentially revealing useful strategies for protecting livestock.","vi":"Các nhà nghiên cứu tìm hiểu xem các vạch sọc của ngựa vằn có thể ngăn chặn côn trùng cắn như thế nào, qua đó có khả năng hé lộ những chiến lược hữu ích để bảo vệ gia súc.","audioKind":"ex2"}],"collocations":[{"en":"vertical stripes","vi":"sọc dọc"},{"en":"horizontal stripes","vi":"sọc ngang"},{"en":"narrow stripes","vi":"sọc nhỏ"},{"en":"black and white stripes","vi":"sọc đen trắng"}],"wordFamily":["stripe (n.)","striped (adj.)"],"synonyms":["bands"],"antonyms":[],"tipVi":"Stripes là dạng số nhiều của stripe; tính từ \"có sọc\" là striped.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mixture', 'en-b1-58', 'mixture', '/ˈmɪkstʃər/', 'B1', 'hỗn hợp; thể hòa trộn', 'n.', 'mix (v.), mixed (adj.), mixer (n.)', 'Đồng nghĩa: blend, combination', 'a mixture of có thể đi kèm danh từ chỉ vật chất hoặc các sự việc trừu tượng như cảm xúc.', 'Stir the mixture until it becomes smooth and creamy.', NULL, 'Khuấy đều hỗn hợp cho đến khi trở nên mịn và sánh.', '{"wordId":"mixture","ukIpa":"/ˈmɪkstʃə/","usIpa":"/ˈmɪkstʃər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Something made by combining two or more different things.","vi":"hỗn hợp; thể hòa trộn"}],"examples":[{"en":"Stir the mixture until it becomes smooth and creamy.","vi":"Khuấy đều hỗn hợp cho đến khi trở nên mịn và sánh.","audioKind":"ex"},{"en":"Successful cities offer a mixture of affordable housing, reliable transport, and accessible public spaces.","vi":"Các thành phố thành công mang lại sự kết hợp giữa nhà ở giá rẻ, giao thông đáng tin cậy và không gian công cộng dễ tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"a mixture of","vi":"hỗn hợp gồm"},{"en":"stir the mixture","vi":"khuấy hỗn hợp"},{"en":"a rich mixture","vi":"tổ hợp phong phú"}],"wordFamily":["mix (v.)","mixed (adj.)","mixer (n.)"],"synonyms":["blend","combination"],"antonyms":[],"tipVi":"a mixture of có thể đi kèm danh từ chỉ vật chất hoặc các sự việc trừu tượng như cảm xúc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shave', 'en-b1-58', 'shave', '/ʃeɪv/', 'B1', 'cạo râu; cạo lông; gọt mỏng; cắt giảm một lượng nhỏ; lần cạo râu', 'v.', 'shaver (n.), shaving (n.), shaven (adj.)', NULL, 'Thì quá khứ là shaved; phân tử hai là shaved hoặc shaven.', 'I shave every morning before leaving for work.', NULL, 'Tôi cạo râu mỗi sáng trước khi đi làm.', '{"wordId":"shave","ukIpa":"/ʃeɪv/","usIpa":"/ʃeɪv/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To remove hair from skin using a razor.","vi":"cạo râu; cạo lông"},{"pos":"v.","en":"To remove thin pieces or reduce something by a small amount.","vi":"gọt mỏng; cắt giảm một lượng nhỏ"},{"pos":"n.","en":"An act of removing facial hair with a razor.","vi":"lần cạo râu"}],"examples":[{"en":"I shave every morning before leaving for work.","vi":"Tôi cạo râu mỗi sáng trước khi đi làm.","audioKind":"ex"},{"en":"Improved transport connections could shave several minutes off daily journeys and encourage more people to commute by train.","vi":"Việc cải thiện kết nối giao thông có thể rút ngắn vài phút cho hành trình di chuyển hàng ngày và khuyến khích nhiều người đi lại bằng tàu hỏa hơn.","audioKind":"ex2"}],"collocations":[{"en":"shave your head","vi":"cạo trọc đầu"},{"en":"have a shave","vi":"cạo râu"},{"en":"shave time off","vi":"rút ngắn thời gian"}],"wordFamily":["shaver (n.)","shaving (n.)","shaven (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thì quá khứ là shaved; phân tử hai là shaved hoặc shaven.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bend', 'en-b1-58', 'bend', '/bend/', 'B1', 'làm cong; bẻ cong; cúi xuống; gập người; đoạn cong; khúc cua', 'v.', 'bent (adj.), bendable (adj.)', 'Đồng nghĩa: curve · Trái nghĩa: straighten', 'Quá khứ và phân tử hai đều là bent; bend down nghĩa là cúi người xuống.', 'Bend the wire gently to make a small hook.', NULL, 'Nhẹ nhàng uốn cong sợi dây thép để tạo thành một chiếc móc nhỏ.', '{"wordId":"bend","ukIpa":"/bend/","usIpa":"/bend/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To become curved or make something curved.","vi":"làm cong; bẻ cong"},{"pos":"v.","en":"To move your body downwards or forwards from the waist.","vi":"cúi xuống; gập người"},{"pos":"n.","en":"A curved section of a road, river, or other long object.","vi":"đoạn cong; khúc cua"}],"examples":[{"en":"Bend the wire gently to make a small hook.","vi":"Nhẹ nhàng uốn cong sợi dây thép để tạo thành một chiếc móc nhỏ.","audioKind":"ex"},{"en":"Drivers should reduce their speed before approaching a sharp bend, especially when road conditions are poor.","vi":"Người lái xe nên giảm tốc độ trước khi vào một khúc cua gấp, đặc biệt là khi điều kiện đường xá kém.","audioKind":"ex2"}],"collocations":[{"en":"bend your knees","vi":"gập đầu gối"},{"en":"bend down","vi":"cúi xuống"},{"en":"a sharp bend","vi":"khúc cua gắt"},{"en":"bend the rules","vi":"lách luật; uyển chuyển theo quy tắc"}],"wordFamily":["bent (adj.)","bendable (adj.)"],"synonyms":["curve"],"antonyms":["straighten"],"tipVi":"Quá khứ và phân tử hai đều là bent; bend down nghĩa là cúi người xuống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_58_1', 'en-b1-58', 'Cách dùng “favor” (n.) — ân huệ; sự giúp đỡ', 'do someone a favor  ·  in favor of  ·  favor one option over another', 'favor là cách viết theo tiếng Mỹ, còn tiếng Anh-Anh là favour; cụm từ diễn đạt việc giúp đỡ là do a favor.', 'Họ từ (Word Family): favorable (adj.), favorably (adv.), favored (adj.), favoritism (n.)', '[{"hanzi":"Could you do me a favor and water my plants?","pinyin":"","meaning":"Bạn có thể làm ơn giúp tôi tưới chỗ cây cối được không?"},{"hanzi":"Many residents favor investment in public transport because it can reduce congestion and improve access to employment.","pinyin":"","meaning":"Nhiều cư dân ủng hộ việc đầu tư vào giao thông công cộng vì nó có thể làm giảm tắc nghẽn và giúp việc di chuyển đến nơi làm việc thuận lợi hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_58_2', 'en-b1-58', 'Cách dùng “second-hand” (adj.) — đồ cũ; đã qua sử dụng', 'second-hand clothes  ·  second-hand shop  ·  buy second-hand', 'Từ này vừa có thể chỉ vật dụng đã qua sử dụng, vừa có thể chỉ thông tin không phải do tự mình trải nghiệm.', 'Đồng nghĩa: used, pre-owned · Trái nghĩa: brand-new', '[{"hanzi":"My second-hand bicycle still rides smoothly after years of use.","pinyin":"","meaning":"Chiếc xe đạp cũ của tôi vẫn chạy rất mượt mà sau nhiều năm sử dụng."},{"hanzi":"Buying second-hand furniture can reduce household spending and prevent usable goods from ending up in landfill.","pinyin":"","meaning":"Việc mua nội thất đã qua sử dụng có thể giúp giảm chi phí sinh hoạt và ngăn chặn các vật dụng còn dùng được bị vứt ra bãi rác."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_58_3', 'en-b1-58', 'Cách dùng “hidden” (adj.) — bị che khuất; ẩn giấu; khó nhận thấy', 'hidden costs  ·  hidden meaning  ·  hidden talent', 'Cũng là quá khứ phân từ của hide; ẩn giấu không có nghĩa là mắt thường hoàn toàn không thể nhìn thấy.', 'Họ từ (Word Family): hide (v.), hiding (n.) | Đồng nghĩa: concealed, unseen · Trái nghĩa: visible, obvious', '[{"hanzi":"We found a hidden cupboard behind the kitchen door.","pinyin":"","meaning":"Chúng tôi tìm thấy một chiếc tủ ẩn sau cánh cửa bếp."},{"hanzi":"Consumers should consider the hidden costs of online purchases, including delivery fees and charges for returning items.","pinyin":"","meaning":"Người tiêu dùng nên cân nhắc các chi phí ẩn khi mua sắm trực tuyến, bao gồm phí vận chuyển và phí trả lại hàng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_58_4', 'en-b1-58', 'Cách dùng “roughly” (adv.) — khoảng chừng; đại khái', 'roughly equal  ·  roughly speaking  ·  treat roughly', 'Khi dùng với nghĩa "khoảng", từ này thường đứng trước các con số; đôi khi cũng chỉ cách thức thô bạo.', 'Họ từ (Word Family): rough (adj.), roughness (n.), roughen (v.) | Đồng nghĩa: approximately, about · Trái nghĩa: exactly', '[{"hanzi":"The walk to the lake takes roughly twenty minutes.","pinyin":"","meaning":"Đi bộ ra hồ mất khoảng chừng hai mươi phút."},{"hanzi":"Roughly half of the residents surveyed supported replacing the old car park with a public garden.","pinyin":"","meaning":"Khoảng một nửa số cư dân được khảo sát ủng hộ việc biến bãi đậu xe cũ thành một khu vườn công cộng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_58_1', 'en-b1-58', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
