INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_58_1_6', 'ten_b1_58_1', 'uncomfortable', 'These new shoes feel uncomfortable after a long walk.', 'These new shoes feel uncomfortable after a long walk.', '/ʌnˈkʌmftɚbəl/', 'Đôi giày mới này mang lại cảm giác không thoải mái sau một quãng đường đi bộ dài.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_58_1_7', 'ten_b1_58_1', 'peel', 'Could you peel these potatoes while I chop the carrots?', 'Could you peel these potatoes while I chop the carrots?', '/piːl/', 'Bạn có thể gọt vỏ những củ khoai tây này trong lúc tôi thái cà rốt không?', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_58_1_8', 'ten_b1_58_1', 'fully', 'Make sure your phone is fully charged before leaving.', 'Make sure your phone is fully charged before leaving.', '/ˈfʊli/', 'Hãy đảm bảo điện thoại của bạn đã được sạc đầy trước khi rời đi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_58_1_1', 'en-b1-58', 'ten_b1_58_1', 'listening', 'listening', 'This bag is made from a strong waterproof material.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một cơn gió lạnh thổi những chiếc lá bay qua sân chơi trống trải.","Chiếc túi này được làm từ một loại vật liệu chống thấm nước bền chắc.","Chúng tôi tìm thấy một góc râm mát bên bờ sông.","Đừng để ly nước của bạn sát mép bàn."]'::jsonb, 1, 'This bag is made from a strong waterproof material. → Chiếc túi này được làm từ một loại vật liệu chống thấm nước bền chắc.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_58_1_2', 'en-b1-58', 'ten_b1_58_1', 'listening', 'listening', 'These shoes are too tight around my toes.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một cơn gió lạnh thổi những chiếc lá bay qua sân chơi trống trải.","Chiếc xe đạp cũ của tôi vẫn chạy rất mượt mà sau nhiều năm sử dụng.","Đôi giày này quá chật ở phần mũi, làm đau các ngón chân của tôi.","Khuấy đều hỗn hợp cho đến khi trở nên mịn và sánh."]'::jsonb, 2, 'These shoes are too tight around my toes. → Đôi giày này quá chật ở phần mũi, làm đau các ngón chân của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_58_1_3', 'en-b1-58', 'ten_b1_58_1', 'listening', 'listening', 'A well-dressed guest arrived in a neatly pressed suit.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hãy đậy nắp lại trước khi bạn lắc chiếc lọ.","Làm ơn nhắc tôi mang theo ô trước khi chúng ta rời đi.","Chúng tôi tìm thấy một chiếc tủ ẩn sau cánh cửa bếp.","Một vị khách ăn mặc lịch sự bước vào trong bộ vest được là ủi phẳng phiu."]'::jsonb, 3, 'A well-dressed guest arrived in a neatly pressed suit. → Một vị khách ăn mặc lịch sự bước vào trong bộ vest được là ủi phẳng phiu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_58_2', 'en-b1-58', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_58_2_1', 'ten_b1_58_2', 'material', 'Using recycled material in construction can reduce waste and lower demand for newly extracted natural resources.', 'Using recycled material in construction can reduce waste and lower demand for newly extracted natural resources.', '/məˈtɪriəl/', 'Việc sử dụng vật liệu tái chế trong xây dựng có thể giảm thiểu rác thải và hạ thấp nhu cầu khai thác tài nguyên thiên nhiên mới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_58_2_2', 'ten_b1_58_2', 'tight', 'Schools operating on tight budgets may struggle to provide students with modern equipment and adequate support.', 'Schools operating on tight budgets may struggle to provide students with modern equipment and adequate support.', '/taɪt/', 'Các trường học hoạt động với ngân sách eo hẹp có thể gặp khó khăn trong việc cung cấp cho học sinh thiết bị hiện đại và sự hỗ trợ đầy đủ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_58_2_3', 'ten_b1_58_2', 'well-dressed', 'Although well-dressed applicants may create positive first impressions, employers should prioritise relevant skills and professional experience.', 'Although well-dressed applicants may create positive first impressions, employers should prioritise relevant skills and professional experience.', '/ˌwel ˈdrest/', 'Mặc dù những ứng viên ăn mặc chỉn chu có thể tạo ấn tượng ban đầu tốt đẹp, nhà tuyển dụng vẫn nên ưu tiên các kỹ năng liên quan và kinh nghiệm chuyên môn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_58_2_4', 'ten_b1_58_2', 'grown-up', 'Children often develop grown-up attitudes towards responsibility when they participate in age-appropriate household tasks.', 'Children often develop grown-up attitudes towards responsibility when they participate in age-appropriate household tasks.', '/ˈɡroʊn ʌp/', 'Trẻ em thường phát triển thái độ trưởng thành đối với trách nhiệm khi các em tham gia vào những công việc nhà phù hợp với lứa tuổi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_58_2_5', 'ten_b1_58_2', 'hidden', 'Consumers should consider the hidden costs of online purchases, including delivery fees and charges for returning items.', 'Consumers should consider the hidden costs of online purchases, including delivery fees and charges for returning items.', '/ˈhɪdən/', 'Người tiêu dùng nên cân nhắc các chi phí ẩn khi mua sắm trực tuyến, bao gồm phí vận chuyển và phí trả lại hàng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_58_2_6', 'ten_b1_58_2', 'uncomfortable', 'Students may feel uncomfortable asking questions in large classes, which can limit their participation and understanding.', 'Students may feel uncomfortable asking questions in large classes, which can limit their participation and understanding.', '/ʌnˈkʌmftɚbəl/', 'Học sinh có thể cảm thấy ngượng ngùng khi đặt câu hỏi trong các lớp học lớn, điều này có thể hạn chế sự tham gia và mức độ hiểu bài của các em.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_58_2_1', 'en-b1-58', 'ten_b1_58_2', 'listening', 'listening', 'Using recycled material in construction can reduce waste and lower demand for newly extracted natural resources.', NULL, 'Trong câu vừa nghe, từ “material” mang nghĩa nào sau đây?', '["xe nhà lưu động (kéo theo sau ô tô)","vật liệu; nguyên liệu; vải vóc","nguồn; nguồn gốc","đồ cũ; đã qua sử dụng"]'::jsonb, 1, '“material” (/məˈtɪriəl/): vật liệu; nguyên liệu; vải vóc. Câu đầy đủ: Using recycled material in construction can reduce waste and lower demand for newly extracted natural resources.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_58_2_2', 'en-b1-58', 'ten_b1_58_2', 'listening', 'listening', 'Schools operating on tight budgets may struggle to provide students with modern equipment and adequate support.', NULL, 'Trong câu vừa nghe, từ “tight” mang nghĩa nào sau đây?', '["cũng không; cũng chẳng","sửa chữa; vá","chật; bó sát; chặt","cảnh; phong cảnh"]'::jsonb, 2, '“tight” (/taɪt/): chật; bó sát; chặt. Câu đầy đủ: Schools operating on tight budgets may struggle to provide students with modern equipment and adequate support.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
