INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_1', 'en-b1-58', NULL, 'comprehensive_test', 'listening', 'material', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bộ dụng cụ; trang thiết bị","nghiên cứu; sự khảo sát","vật liệu; nguyên liệu; vải vóc","sống; chưa nấu chín"]'::jsonb, 2, 'material (/məˈtɪriəl/) → vật liệu; nguyên liệu; vải vóc; tài liệu; tư liệu; thuộc về vật chất; thiết yếu', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_2', 'en-b1-58', NULL, 'comprehensive_test', 'listening', 'These shoes are too tight around my toes.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi cạo râu mỗi sáng trước khi đi làm.","Đừng để ly nước của bạn sát mép bàn.","Đôi giày này quá chật ở phần mũi, làm đau các ngón chân của tôi.","Hãy đậy nắp lại trước khi bạn lắc chiếc lọ."]'::jsonb, 2, 'These shoes are too tight around my toes. → Đôi giày này quá chật ở phần mũi, làm đau các ngón chân của tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_3', 'en-b1-58', NULL, 'comprehensive_test', 'listening', 'well-dressed', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thám tử; trinh thám; cảnh sát điều tra","người đánh cá; thợ câu cá","ăn mặc chỉn chu; ăn mặc lịch sự","lều; nhà tranh; chòi"]'::jsonb, 2, 'well-dressed (/ˌwel ˈdrest/) → ăn mặc chỉn chu; ăn mặc lịch sự', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_4', 'en-b1-58', NULL, 'comprehensive_test', 'listening', 'Ask a grown-up to help you slice the bread.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy đảm bảo điện thoại của bạn đã được sạc đầy trước khi rời đi.","Nhẹ nhàng uốn cong sợi dây thép để tạo thành một chiếc móc nhỏ.","Đôi giày này quá chật ở phần mũi, làm đau các ngón chân của tôi.","Hãy nhờ một người lớn giúp bạn cắt bánh mì nhé."]'::jsonb, 3, 'Ask a grown-up to help you slice the bread. → Hãy nhờ một người lớn giúp bạn cắt bánh mì nhé.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_5', 'en-b1-58', NULL, 'comprehensive_test', 'listening', 'hidden', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ấn tượng; cảm giác","sau đó; sau khi","người yêu; tình nhân","bị che khuất; ẩn giấu; khó nhận thấy"]'::jsonb, 3, 'hidden (/ˈhɪdən/) → bị che khuất; ẩn giấu; khó nhận thấy', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_6', 'en-b1-58', NULL, 'comprehensive_test', 'listening', 'These new shoes feel uncomfortable after a long walk.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cuối cùng chúng tôi cũng tống khứ được những chiếc ghế vườn đã hỏng.","Chúng tôi tìm thấy một chiếc tủ ẩn sau cánh cửa bếp.","Hãy đậy nắp lại trước khi bạn lắc chiếc lọ.","Đôi giày mới này mang lại cảm giác không thoải mái sau một quãng đường đi bộ dài."]'::jsonb, 3, 'These new shoes feel uncomfortable after a long walk. → Đôi giày mới này mang lại cảm giác không thoải mái sau một quãng đường đi bộ dài.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_7', 'en-b1-58', NULL, 'comprehensive_test', 'listening', 'peel', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["người ăn chay","bạn bè; bạn đồng hành","tay trống; người đánh trống","gọt vỏ; bóc vỏ"]'::jsonb, 3, 'peel (/piːl/) → gọt vỏ; bóc vỏ; bong ra; tróc ra; vỏ trái cây; vỏ rau củ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_8', 'en-b1-58', NULL, 'comprehensive_test', 'listening', 'Make sure your phone is fully charged before leaving.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc xe đạp cũ của tôi vẫn chạy rất mượt mà sau nhiều năm sử dụng.","Hãy đảm bảo điện thoại của bạn đã được sạc đầy trước khi rời đi.","Chiếc áo sơ mi yêu thích của tôi có các sọc xanh ở mặt trước.","Anh ấy dùng khăn ăn để lau vết súp dính trên cằm."]'::jsonb, 1, 'Make sure your phone is fully charged before leaving. → Hãy đảm bảo điện thoại của bạn đã được sạc đầy trước khi rời đi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_9', 'en-b1-58', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Kept out of sight or not easily noticed.”?', '["porridge","listener","hidden","grown-up"]'::jsonb, 2, 'hidden (/ˈhɪdən/) → bị che khuất; ẩn giấu; khó nhận thấy', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_10', 'en-b1-58', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Causing or feeling physical discomfort.”?', '["uncomfortable","roughly","material","tray"]'::jsonb, 0, 'uncomfortable (/ʌnˈkʌmftɚbəl/) → không thoải mái; gây khó chịu về thể chất', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
