INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_18', 'en-b1-58', NULL, 'comprehensive_test', 'reading', NULL, 'Using recycled material in construction can reduce waste and lower demand for newly extracted natural resources.', 'Dựa vào câu trên, từ “material” có nghĩa phù hợp nhất là gì?', '["con giun; con trùn","đồ lót; trang phục mặc sát da","vật liệu; nguyên liệu; vải vóc","thông tin; hàm lượng"]'::jsonb, 2, 'material: vật liệu; nguyên liệu; vải vóc; tài liệu; tư liệu; thuộc về vật chất; thiết yếu. Dịch cả câu: Việc sử dụng vật liệu tái chế trong xây dựng có thể giảm thiểu rác thải và hạ thấp nhu cầu khai thác tài nguyên thiên nhiên mới.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_19', 'en-b1-58', NULL, 'comprehensive_test', 'reading', NULL, 'Schools operating on tight budgets may struggle to provide students with modern equipment and adequate support.', 'Dựa vào câu trên, từ “tight” có nghĩa phù hợp nhất là gì?', '["phục tụng; kể lại; thuật lại","chật; bó sát; chặt","ngực; khoang ngực","tổ chức; cơ quan; hiệp hội"]'::jsonb, 1, 'tight: chật; bó sát; chặt; eo hẹp; căng thẳng (thời gian, tiền bạc, không gian); chặt chẽ; vững chắc. Dịch cả câu: Các trường học hoạt động với ngân sách eo hẹp có thể gặp khó khăn trong việc cung cấp cho học sinh thiết bị hiện đại và sự hỗ trợ đầy đủ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_20', 'en-b1-58', NULL, 'comprehensive_test', 'reading', NULL, 'Although well-dressed applicants may create positive first impressions, employers should prioritise relevant skills and professional experience.', 'Dựa vào câu trên, từ “well-dressed” có nghĩa phù hợp nhất là gì?', '["mê hoặc; đáng yêu; duyên dáng","khách hàng; thân chủ","chú hề","ăn mặc chỉn chu; ăn mặc lịch sự"]'::jsonb, 3, 'well-dressed: ăn mặc chỉn chu; ăn mặc lịch sự. Dịch cả câu: Mặc dù những ứng viên ăn mặc chỉn chu có thể tạo ấn tượng ban đầu tốt đẹp, nhà tuyển dụng vẫn nên ưu tiên các kỹ năng liên quan và kinh nghiệm chuyên môn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_21', 'en-b1-58', NULL, 'comprehensive_test', 'reading', NULL, 'Children often develop grown-up attitudes towards responsibility when they participate in age-appropriate household tasks.', 'Dựa vào câu trên, từ “grown-up” có nghĩa phù hợp nhất là gì?', '["ho","khách sạn ven đường","người lớn; người trưởng thành (thường dùng khi nói chuyện với hoặc về trẻ em)","đồ đạc; thứ; vật dụng"]'::jsonb, 2, 'grown-up: người lớn; người trưởng thành (thường dùng khi nói chuyện với hoặc về trẻ em); trưởng thành; có cách hành xử chín chắn và có trách nhiệm. Dịch cả câu: Trẻ em thường phát triển thái độ trưởng thành đối với trách nhiệm khi các em tham gia vào những công việc nhà phù hợp với lứa tuổi.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_22', 'en-b1-58', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hỗn hợp; thể hòa trộn”', '["shame","cassette","mixture","stinky"]'::jsonb, 2, 'hỗn hợp; thể hòa trộn → mixture (/ˈmɪkstʃər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_23', 'en-b1-58', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cạo râu; cạo lông”', '["shadow","ribbon","shave","incredible"]'::jsonb, 2, 'cạo râu; cạo lông → shave (/ʃeɪv/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_58_24', 'en-b1-58', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “làm cong; bẻ cong”', '["quotation","babysitter","capital","bend"]'::jsonb, 3, 'làm cong; bẻ cong → bend (/bend/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-59', 'en', 'Bài 59: Đời sống hằng ngày (11) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3059, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cap', 'en-b1-59', 'cap', '/kæp/', 'B1', 'mũ lưỡi trai; mũ mềm có vành cứng phía trước; nắp; nút đậy (che phần đầu hoặc miệng của vật gì); giới hạn mức tối đa', 'n.', 'capped (adj.)', NULL, 'cap dùng như động từ có nghĩa là thiết lập giới hạn; dùng cụm "a cap on" để chỉ đối tượng bị giới hạn.', 'He pulled on his cap before leaving for practice.', NULL, 'Anh ấy đội chiếc mũ lưỡi trai của mình trước khi đi tập.', '{"wordId":"cap","ukIpa":"/kæp/","usIpa":"/kæp/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a soft hat, often with a stiff front part","vi":"mũ lưỡi trai; mũ mềm có vành cứng phía trước"},{"pos":"n.","en":"a cover fitted over the end or opening of something","vi":"nắp; nút đậy (che phần đầu hoặc miệng của vật gì)"},{"pos":"v.","en":"to set a maximum amount or level for something","vi":"giới hạn mức tối đa"}],"examples":[{"en":"He pulled on his cap before leaving for practice.","vi":"Anh ấy đội chiếc mũ lưỡi trai của mình trước khi đi tập.","audioKind":"ex"},{"en":"Governments could cap annual rent increases to protect households from sudden rises in housing costs.","vi":"Chính phủ có thể áp trần tăng giá thuê nhà hàng năm để bảo vệ các hộ gia đình trước tình trạng chi phí nhà ở tăng vọt đột ngột.","audioKind":"ex2"}],"collocations":[{"en":"baseball cap","vi":"mũ bóng chày"},{"en":"bottle cap","vi":"nắp chai"},{"en":"cap spending","vi":"hạn chế chi tiêu"},{"en":"a cap on fees","vi":"giá trần; mức phí giới hạn"}],"wordFamily":["capped (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"cap dùng như động từ có nghĩa là thiết lập giới hạn; dùng cụm \"a cap on\" để chỉ đối tượng bị giới hạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peach', 'en-b1-59', 'peach', '/piːtʃ/', 'B1', 'quả đào; màu hồng cam nhạt', 'n.', 'peachy (adj.)', NULL, 'Hạt đào trong tiếng Anh Anh thường gọi là stone, trong tiếng Anh Mỹ gọi là pit.', 'She sliced a ripe peach into her breakfast bowl.', NULL, 'Cô ấy cắt một quả đào chín vào bát bữa sáng của mình.', '{"wordId":"peach","ukIpa":"/piːtʃ/","usIpa":"/piːtʃ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A juicy fruit with fuzzy skin and a large hard stone","vi":"quả đào"},{"pos":"adj.","en":"Having a pale pinkish orange colour","vi":"màu hồng cam nhạt"}],"examples":[{"en":"She sliced a ripe peach into her breakfast bowl.","vi":"Cô ấy cắt một quả đào chín vào bát bữa sáng của mình.","audioKind":"ex"},{"en":"Peach growers may face reduced harvests when unusually warm winters disrupt the trees'' natural flowering cycle.","vi":"Những người trồng đào có thể phải đối mặt với tình trạng giảm thu hoạch khi mùa đông ấm bất thường làm gián đoạn chu kỳ ra hoa tự nhiên của cây.","audioKind":"ex2"}],"collocations":[{"en":"a ripe peach","vi":"quả đào chín"},{"en":"peach juice","vi":"nước ép đào"},{"en":"a peach tree","vi":"cây đào"}],"wordFamily":["peachy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Hạt đào trong tiếng Anh Anh thường gọi là stone, trong tiếng Anh Mỹ gọi là pit.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sender', 'en-b1-59', 'sender', '/ˈsendər/', 'B1', 'người gửi; bên gửi (thư, tin nhắn hoặc bưu phẩm)', 'n.', 'send (v.)', 'Trái nghĩa: recipient', 'sender là người gửi, còn recipient là người nhận.', 'The sender wrapped the parcel carefully before posting it.', NULL, 'Người gửi đã gói bưu kiện cẩn thận trước khi đem đi gửi.', '{"wordId":"sender","ukIpa":"/ˈsendə/","usIpa":"/ˈsendər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A person who sends a message, letter or package.","vi":"người gửi; bên gửi (thư, tin nhắn hoặc bưu phẩm)"}],"examples":[{"en":"The sender wrapped the parcel carefully before posting it.","vi":"Người gửi đã gói bưu kiện cẩn thận trước khi đem đi gửi.","audioKind":"ex"},{"en":"Email users should verify the sender before opening attachments to reduce the risk of digital fraud.","vi":"Người dùng email nên xác minh người gửi trước khi mở các tệp đính kèm để giảm thiểu rủi ro gian lận trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"the sender''s address","vi":"địa chỉ người gửi"},{"en":"return to sender","vi":"trả lại cho người gửi"},{"en":"an unknown sender","vi":"người gửi không xác định"}],"wordFamily":["send (v.)"],"synonyms":[],"antonyms":["recipient"],"tipVi":"sender là người gửi, còn recipient là người nhận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fetch', 'en-b1-59', 'fetch', '/fetʃ/', 'B1', 'đi lấy; mang về; tìm và mang đến; bán được (với một mức giá cụ thể)', 'v.', NULL, NULL, 'fetch nhấn mạnh hành động đi đến một nơi rồi mang thứ gì về; bring chỉ nhấn mạnh việc mang thứ gì đến.', 'Could you fetch my jacket from the bedroom?', NULL, 'Bạn có thể lấy giúp tôi chiếc áo khoác trong phòng ngủ được không?', '{"wordId":"fetch","ukIpa":"/fetʃ/","usIpa":"/fetʃ/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To go somewhere and bring someone or something back.","vi":"đi lấy; mang về; tìm và mang đến"},{"pos":"v.","en":"To be sold for a particular amount of money.","vi":"bán được (với một mức giá cụ thể)"}],"examples":[{"en":"Could you fetch my jacket from the bedroom?","vi":"Bạn có thể lấy giúp tôi chiếc áo khoác trong phòng ngủ được không?","audioKind":"ex"},{"en":"Homes near reliable public transport often fetch higher prices because buyers value convenient access to employment.","vi":"Nhà ở gần các tuyến giao thông công cộng thuận tiện thường bán được giá cao hơn vì người mua coi trọng sự tiện lợi khi đi lại.","audioKind":"ex2"}],"collocations":[{"en":"fetch some water","vi":"đi lấy ít nước"},{"en":"fetch someone from school","vi":"đón ai từ trường về"},{"en":"fetch a high price","vi":"bán được giá cao"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"fetch nhấn mạnh hành động đi đến một nơi rồi mang thứ gì về; bring chỉ nhấn mạnh việc mang thứ gì đến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_badge', 'en-b1-59', 'badge', '/bædʒ/', 'B1', 'huy hiệu; thẻ tên; biểu tượng', 'n.', NULL, NULL, 'Thường chỉ huy hiệu nhỏ được đeo trên người; huy chương thể thao thường dùng medal.', 'She pinned her new badge onto her jacket.', NULL, 'Cô ấy ghim huy hiệu mới của mình lên áo khoác.', '{"wordId":"badge","ukIpa":"/bædʒ/","usIpa":"/bædʒ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A small item worn to show identity, membership, or achievement.","vi":"huy hiệu; thẻ tên; biểu tượng"}],"examples":[{"en":"She pinned her new badge onto her jacket.","vi":"Cô ấy ghim huy hiệu mới của mình lên áo khoác.","audioKind":"ex"},{"en":"Requiring visitors to wear a visible badge can improve security in schools and other public buildings.","vi":"Việc yêu cầu khách tham quan đeo huy hiệu nhận diện rõ ràng có thể nâng cao an ninh tại trường học và các tòa nhà công cộng khác.","audioKind":"ex2"}],"collocations":[{"en":"wear a badge","vi":"đeo huy hiệu"},{"en":"identity badge","vi":"thẻ nhận diện"},{"en":"a badge of honour","vi":"biểu tượng của niềm vinh dự"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ huy hiệu nhỏ được đeo trên người; huy chương thể thao thường dùng medal.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_freeze', 'en-b1-59', 'freeze', '/friːz/', 'B1', 'đóng băng; làm đông lạnh; tạm ngưng; đứng hình; khựng lại', 'v.', 'frozen (adj.), freezing (adj.), freezer (n.)', 'Trái nghĩa: thaw', 'Quá khứ là froze, quá khứ phân từ là frozen.', 'Freeze the leftover soup and eat it next week.', NULL, 'Hãy đông lạnh phần súp còn thừa lại và ăn vào tuần tới.', '{"wordId":"freeze","ukIpa":"/friːz/","usIpa":"/friːz/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To become ice or make something extremely cold and solid.","vi":"đóng băng; làm đông lạnh"},{"pos":"v.","en":"To stop something changing or being used temporarily.","vi":"đóng băng; tạm ngưng"},{"pos":"v.","en":"To stop moving suddenly because of fear or surprise.","vi":"đứng hình; khựng lại"}],"examples":[{"en":"Freeze the leftover soup and eat it next week.","vi":"Hãy đông lạnh phần súp còn thừa lại và ăn vào tuần tới.","audioKind":"ex"},{"en":"Governments may freeze public transport fares to reduce financial pressure on households during economic downturns.","vi":"Chính phủ có thể đóng băng giá vé phương tiện giao thông công cộng để giảm bớt áp lực tài chính cho các hộ gia đình trong thời kỳ kinh tế suy thoái.","audioKind":"ex2"}],"collocations":[{"en":"freeze food","vi":"cấp đông thực phẩm"},{"en":"freeze wages","vi":"đóng băng tiền lương"},{"en":"freeze with fear","vi":"sợ đến mức đứng hình"}],"wordFamily":["frozen (adj.)","freezing (adj.)","freezer (n.)"],"synonyms":[],"antonyms":["thaw"],"tipVi":"Quá khứ là froze, quá khứ phân từ là frozen.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_filling', 'en-b1-59', 'filling', '/ˈfɪlɪŋ/', 'B1', 'nhân; phần nhân kẹp bên trong; chất hàn răng; vật liệu trám răng; làm no; dễ no', 'n.', 'fill (v.), filled (adj.), filler (n.)', NULL, 'Tính từ filling dùng để chỉ thức ăn làm cho no, không dùng để chỉ trạng thái cảm thấy no của con người.', 'This pie has a warm apple and cinnamon filling.', NULL, 'Chiếc bánh nướng này có phần nhân táo và quế ấm nóng.', '{"wordId":"filling","ukIpa":"/ˈfɪlɪŋ/","usIpa":"/ˈfɪlɪŋ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Food placed inside a pie, sandwich, or similar item.","vi":"nhân; phần nhân kẹp bên trong"},{"pos":"n.","en":"Material used to repair a hole in a tooth.","vi":"chất hàn răng; vật liệu trám răng"},{"pos":"adj.","en":"Making you feel full after eating.","vi":"làm no; dễ no"}],"examples":[{"en":"This pie has a warm apple and cinnamon filling.","vi":"Chiếc bánh nướng này có phần nhân táo và quế ấm nóng.","audioKind":"ex"},{"en":"School lunches should offer filling meals that provide sufficient nutrients to support children''s growth and concentration.","vi":"Bữa trưa ở trường nên cung cấp những món ăn đủ no và đầy đủ chất dinh dưỡng để hỗ trợ sự phát triển cũng như khả năng tập trung của trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"a sandwich filling","vi":"nhân bánh mì kẹp"},{"en":"a dental filling","vi":"vật liệu trám răng"},{"en":"a filling meal","vi":"bữa ăn chắc bụng"}],"wordFamily":["fill (v.)","filled (adj.)","filler (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tính từ filling dùng để chỉ thức ăn làm cho no, không dùng để chỉ trạng thái cảm thấy no của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_condition', 'en-b1-59', 'condition', '/kənˈdɪʃən/', 'B1', 'tình trạng; trạng thái; điều kiện; hoàn cảnh; bệnh lý; vấn đề sức khỏe', 'n.', 'conditional (adj.), conditionally (adv.), unconditional (adj.)', 'Đồng nghĩa: state, requirement', 'Danh từ khi chỉ trạng thái thường là không đếm được; khi chỉ điều kiện làm việc hoặc sinh sống thường dùng dạng số nhiều.', 'Despite its age, this bicycle is in excellent condition.', NULL, 'Dù đã có tuổi, chiếc xe đạp này vẫn đang ở tình trạng rất tốt.', '{"wordId":"condition","ukIpa":"/kənˈdɪʃən/","usIpa":"/kənˈdɪʃən/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The physical state of someone or something","vi":"tình trạng; trạng thái"},{"pos":"n.","en":"A requirement, or circumstances affecting life or activity","vi":"điều kiện; hoàn cảnh"},{"pos":"n.","en":"A medical problem affecting someone''s health","vi":"bệnh lý; vấn đề sức khỏe"}],"examples":[{"en":"Despite its age, this bicycle is in excellent condition.","vi":"Dù đã có tuổi, chiếc xe đạp này vẫn đang ở tình trạng rất tốt.","audioKind":"ex"},{"en":"Improving working conditions can increase employee satisfaction and reduce the number of people leaving their jobs.","vi":"Việc cải thiện điều kiện làm việc có thể nâng cao sự hài lòng của nhân viên và giảm tỷ lệ nhân viên nghỉ việc.","audioKind":"ex2"}],"collocations":[{"en":"in good condition","vi":"ở tình trạng tốt"},{"en":"working conditions","vi":"điều kiện làm việc"},{"en":"on condition that","vi":"với điều kiện là"},{"en":"medical condition","vi":"tình trạng bệnh lý"}],"wordFamily":["conditional (adj.)","conditionally (adv.)","unconditional (adj.)"],"synonyms":["state","requirement"],"antonyms":[],"tipVi":"Danh từ khi chỉ trạng thái thường là không đếm được; khi chỉ điều kiện làm việc hoặc sinh sống thường dùng dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_separate', 'en-b1-59', 'separate', '/ˈseprət/ (adj.); /ˈsepəreɪt/ (v.)', 'B1', 'riêng biệt; tách rời; độc lập; làm tách ra; phân loại; chia tách', 'adj.', 'separation (n.), separately (adv.), inseparable (adj.)', 'Đồng nghĩa: distinct · Trái nghĩa: joint', 'Dạng tính từ có phần đuôi phát âm là /ət/, trong khi dạng động từ có phần đuôi phát âm là /eɪt/.', 'We keep clean towels in a separate cupboard.', NULL, 'Chúng tôi cất khăn tắm sạch trong một chiếc tủ riêng.', '{"wordId":"separate","ukIpa":"/ˈseprət/ (adj.); /ˈsepəreɪt/ (v.)","usIpa":"/ˈseprət/ (adj.); /ˈsepəreɪt/ (v.)","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"not joined, shared, or considered together","vi":"riêng biệt; tách rời; độc lập"},{"pos":"v.","en":"to divide things or move them apart","vi":"làm tách ra; phân loại; chia tách"}],"examples":[{"en":"We keep clean towels in a separate cupboard.","vi":"Chúng tôi cất khăn tắm sạch trong một chiếc tủ riêng.","audioKind":"ex"},{"en":"Local authorities should provide separate bins for recyclable materials to make household waste sorting easier.","vi":"Chính quyền địa phương nên cung cấp các thùng đựng riêng cho vật liệu có thể tái chế để việc phân loại rác thải sinh hoạt trở nên dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"separate rooms","vi":"các phòng riêng biệt"},{"en":"separate from","vi":"tách biệt khỏi"},{"en":"separate accounts","vi":"các tài khoản độc lập"},{"en":"separate waste","vi":"phân loại rác thải"}],"wordFamily":["separation (n.)","separately (adv.)","inseparable (adj.)"],"synonyms":["distinct"],"antonyms":["joint"],"tipVi":"Dạng tính từ có phần đuôi phát âm là /ət/, trong khi dạng động từ có phần đuôi phát âm là /eɪt/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chilli', 'en-b1-59', 'chilli', '/ˈtʃɪli/', 'B1', 'quả ớt; món thịt nấu đậu cay', 'n.', NULL, NULL, 'Từ chilli là cách viết theo Anh-Anh, trong khi tiếng Mỹ thường viết là chili.', 'Add one chopped chilli if you like spicy food.', NULL, 'Hãy cho thêm một quả ớt thái nhỏ nếu bạn thích ăn cay.', '{"wordId":"chilli","ukIpa":"/ˈtʃɪli/","usIpa":"/ˈtʃɪli/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a small pepper with a strong, hot taste","vi":"quả ớt"},{"pos":"n.","en":"a spicy dish usually made with meat, beans, and tomatoes","vi":"món thịt nấu đậu cay"}],"examples":[{"en":"Add one chopped chilli if you like spicy food.","vi":"Hãy cho thêm một quả ớt thái nhỏ nếu bạn thích ăn cay.","audioKind":"ex"},{"en":"Farmers growing chilli peppers may need reliable irrigation systems as rising temperatures increase water demand.","vi":"Những người nông dân trồng ớt có thể cần đến các hệ thống tưới tiêu đáng tin cậy khi nhiệt độ tăng cao làm gia tăng nhu cầu về nước.","audioKind":"ex2"}],"collocations":[{"en":"fresh chilli","vi":"ớt tươi"},{"en":"chilli powder","vi":"bột ớt"},{"en":"chilli sauce","vi":"tương ớt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ chilli là cách viết theo Anh-Anh, trong khi tiếng Mỹ thường viết là chili.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stinky', 'en-b1-59', 'stinky', '/ˈstɪŋki/', 'B1', 'hôi thối; khó ngửi', 'adj.', 'stink (v.), stink (n.), stinking (adj.)', 'Đồng nghĩa: smelly, foul-smelling · Trái nghĩa: fragrant', 'Đây là từ không trang trọng; trong văn viết chính thức, có thể dùng foul-smelling.', 'Please leave those stinky shoes outside the front door.', NULL, 'Làm ơn để những đôi giày hôi thối đó ở ngoài cửa trước.', '{"wordId":"stinky","ukIpa":"/ˈstɪŋki/","usIpa":"/ˈstɪŋki/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"having a strong, unpleasant smell","vi":"hôi thối; khó ngửi"}],"examples":[{"en":"Please leave those stinky shoes outside the front door.","vi":"Làm ơn để những đôi giày hôi thối đó ở ngoài cửa trước.","audioKind":"ex"},{"en":"Residents often describe neglected rubbish bins as stinky, highlighting how poor waste collection affects daily life.","vi":"Người dân thường mô tả những thùng rác không được dọn dẹp là hôi thối, làm nổi bật việc thu gom rác kém hiệu quả ảnh hưởng đến đời sống hàng ngày như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"stinky socks","vi":"tất hôi"},{"en":"stinky shoes","vi":"giày hôi"},{"en":"stinky rubbish","vi":"rác bốc mùi"}],"wordFamily":["stink (v.)","stink (n.)","stinking (adj.)"],"synonyms":["smelly","foul-smelling"],"antonyms":["fragrant"],"tipVi":"Đây là từ không trang trọng; trong văn viết chính thức, có thể dùng foul-smelling.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kit', 'en-b1-59', 'kit', '/kɪt/', 'B1', 'bộ dụng cụ; trang thiết bị; bộ linh kiện lắp ráp', 'n.', NULL, NULL, 'kit chỉ các bộ đồ nghề trọn gói; kit sb out nghĩa là trang bị đầy đủ đồ dùng cho ai.', 'We keep a first aid kit in the car.', NULL, 'Chúng tôi để một bộ sơ cứu trong xe ô tô.', '{"wordId":"kit","ukIpa":"/kɪt/","usIpa":"/kɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A set of tools or equipment for a particular activity","vi":"bộ dụng cụ; trang thiết bị"},{"pos":"n.","en":"A set of parts used to build something","vi":"bộ linh kiện lắp ráp"}],"examples":[{"en":"We keep a first aid kit in the car.","vi":"Chúng tôi để một bộ sơ cứu trong xe ô tô.","audioKind":"ex"},{"en":"Schools should provide basic science kits so that all pupils can take part in practical experiments.","vi":"Nhà trường nên cung cấp các bộ dụng cụ khoa học cơ bản để tất cả học sinh có thể tham gia vào các thí nghiệm thực tế.","audioKind":"ex2"}],"collocations":[{"en":"first aid kit","vi":"hộp sơ cứu"},{"en":"tool kit","vi":"bộ dụng cụ"},{"en":"repair kit","vi":"bộ dụng cụ sửa chữa"},{"en":"kit someone out","vi":"trang bị đầy đủ cho ai đó"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"kit chỉ các bộ đồ nghề trọn gói; kit sb out nghĩa là trang bị đầy đủ đồ dùng cho ai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_landlady', 'en-b1-59', 'landlady', '/ˈlændleɪdi/', 'B1', 'nữ chủ nhà; bà chủ nhà cho thuê trọ; bà chủ quán rượu; nữ chủ quán', 'n.', 'landlord (n.)', NULL, 'landlady chỉ nữ giới; landlord có thể dùng chung cho cả nam lẫn nữ hoặc chỉ nam giới.', 'Our landlady came round to fix the kitchen tap.', NULL, 'Nữ chủ nhà của chúng tôi đã qua sửa vòi nước trong bếp.', '{"wordId":"landlady","ukIpa":"/ˈlændleɪdi/","usIpa":"/ˈlændleɪdi/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a woman who rents property or rooms to other people","vi":"nữ chủ nhà; bà chủ nhà cho thuê trọ"},{"pos":"n.","en":"a woman who owns or manages a pub","vi":"bà chủ quán rượu; nữ chủ quán"}],"examples":[{"en":"Our landlady came round to fix the kitchen tap.","vi":"Nữ chủ nhà của chúng tôi đã qua sửa vòi nước trong bếp.","audioKind":"ex"},{"en":"A responsible landlady should maintain safe housing conditions and respond promptly when tenants report serious problems.","vi":"Một nữ chủ nhà có trách nhiệm nên duy trì điều kiện nhà ở an toàn và phản hồi kịp thời khi người thuê nhà báo cáo các vấn đề nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"ask the landlady","vi":"hỏi nữ chủ nhà"},{"en":"pay rent to the landlady","vi":"trả tiền thuê nhà cho nữ chủ nhà"},{"en":"pub landlady","vi":"nữ chủ quán rượu"}],"wordFamily":["landlord (n.)"],"synonyms":[],"antonyms":[],"tipVi":"landlady chỉ nữ giới; landlord có thể dùng chung cho cả nam lẫn nữ hoặc chỉ nam giới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hostess', 'en-b1-59', 'hostess', '/ˈhoʊstəs/', 'B1', 'nữ chủ nhà; nữ gia chủ (tiếp đón khách); nữ tiếp viên; nhân viên nữ hướng dẫn khách vào bàn ăn', 'n.', 'host (n.), host (v.)', NULL, 'hostess chỉ đặc trưng phụ nữ; host hiện nay có thể dùng cho mọi giới tính.', 'Our hostess brought out fresh fruit after dinner.', NULL, 'Nữ chủ nhà của chúng tôi đã mang trái cây tươi ra sau bữa tối.', '{"wordId":"hostess","ukIpa":"/ˈhəʊstəs/","usIpa":"/ˈhoʊstəs/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A woman who welcomes and entertains guests.","vi":"nữ chủ nhà; nữ gia chủ (tiếp đón khách)"},{"pos":"n.","en":"A woman who welcomes customers and takes them to restaurant tables.","vi":"nữ tiếp viên; nhân viên nữ hướng dẫn khách vào bàn ăn"}],"examples":[{"en":"Our hostess brought out fresh fruit after dinner.","vi":"Nữ chủ nhà của chúng tôi đã mang trái cây tươi ra sau bữa tối.","audioKind":"ex"},{"en":"A welcoming hostess can help international visitors feel comfortable and encourage meaningful conversations across cultures.","vi":"Một nữ chủ nhà niềm nở có thể giúp các vị khách quốc tế cảm thấy thoải mái và thúc đẩy những cuộc trò chuyện ý nghĩa vượt qua rào cản văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"a gracious hostess","vi":"một nữ chủ nhà chu đáo niềm nở"},{"en":"the perfect hostess","vi":"nữ chủ nhà hoàn hảo"},{"en":"restaurant hostess","vi":"nữ nhân viên đón khách nhà hàng"}],"wordFamily":["host (n.)","host (v.)"],"synonyms":[],"antonyms":[],"tipVi":"hostess chỉ đặc trưng phụ nữ; host hiện nay có thể dùng cho mọi giới tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_silent', 'en-b1-59', 'silent', '/ˈsaɪlənt/', 'B1', 'im lặng; không nói gì; yên tĩnh; không có tiếng động; không phát âm (trong từ vựng)', 'adj.', 'silence (n.), silence (v.), silently (adv.)', 'Đồng nghĩa: quiet, soundless · Trái nghĩa: noisy, talkative', 'silent nhấn mạnh sự không phát ra tiếng; quiet cũng có thể chỉ âm thanh nhỏ.', 'He remained silent while his sister explained the problem.', NULL, 'Cậu ấy giữ im lặng trong khi chị gái giải thích vấn đề.', '{"wordId":"silent","ukIpa":"/ˈsaɪlənt/","usIpa":"/ˈsaɪlənt/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Not speaking or choosing not to speak.","vi":"im lặng; không nói gì"},{"pos":"adj.","en":"Making no sound or containing no noise.","vi":"yên tĩnh; không có tiếng động"},{"pos":"adj.","en":"Written in a word but not pronounced.","vi":"không phát âm (trong từ vựng)"}],"examples":[{"en":"He remained silent while his sister explained the problem.","vi":"Cậu ấy giữ im lặng trong khi chị gái giải thích vấn đề.","audioKind":"ex"},{"en":"Employees may remain silent about workplace problems if they fear losing their jobs.","vi":"Nhân viên có thể giữ im lặng về các vấn đề nơi làm việc nếu họ sợ mất việc.","audioKind":"ex2"}],"collocations":[{"en":"remain silent","vi":"giữ im lặng"},{"en":"fall silent","vi":"trở nên im lặng"},{"en":"silent film","vi":"phim câm"},{"en":"silent letter","vi":"chữ cái câm không phát âm"}],"wordFamily":["silence (n.)","silence (v.)","silently (adv.)"],"synonyms":["quiet","soundless"],"antonyms":["noisy","talkative"],"tipVi":"silent nhấn mạnh sự không phát ra tiếng; quiet cũng có thể chỉ âm thanh nhỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enormous', 'en-b1-59', 'enormous', '/ɪˈnɔːrməs/', 'B1', 'khổng lồ; to lớn; cực kỳ lớn', 'adj.', 'enormously (adv.)', 'Đồng nghĩa: huge, immense, vast · Trái nghĩa: tiny', 'Có thể dùng để miêu tả kích thước, cũng như áp lực, số lượng hoặc mức độ ảnh hưởng lớn.', 'An enormous pumpkin filled the basket on our kitchen table.', NULL, 'Một quả bí ngô khổng lồ lấp đầy chiếc giỏ trên bàn bếp của chúng tôi.', '{"wordId":"enormous","ukIpa":"/ɪˈnɔːməs/","usIpa":"/ɪˈnɔːrməs/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"extremely large in size, amount, or degree","vi":"khổng lồ; to lớn; cực kỳ lớn"}],"examples":[{"en":"An enormous pumpkin filled the basket on our kitchen table.","vi":"Một quả bí ngô khổng lồ lấp đầy chiếc giỏ trên bàn bếp của chúng tôi.","audioKind":"ex"},{"en":"Rapid urban growth places enormous pressure on housing, transport networks, and other essential public services.","vi":"Sự phát triển đô thị nhanh chóng đặt áp lực khổng lồ lên nhà ở, hệ thống giao thông và các dịch vụ công cộng thiết yếu khác.","audioKind":"ex2"}],"collocations":[{"en":"enormous pressure","vi":"áp lực khổng lồ"},{"en":"an enormous amount of","vi":"một lượng lớn"},{"en":"enormous potential","vi":"tiềm năng to lớn"}],"wordFamily":["enormously (adv.)"],"synonyms":["huge","immense","vast"],"antonyms":["tiny"],"tipVi":"Có thể dùng để miêu tả kích thước, cũng như áp lực, số lượng hoặc mức độ ảnh hưởng lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arrangement', 'en-b1-59', 'arrangement', '/əˈreɪndʒmənt/', 'B1', 'sự sắp xếp; sự chuẩn bị; sự bố trí; cách bài trí; sự thỏa thuận; sự dàn xếp', 'n.', 'arrange (v.), arranger (n.), rearrange (v.)', NULL, 'Chỉ việc chuẩn bị cụ thể thường dùng dạng số nhiều: make arrangements for.', 'We made arrangements for someone to feed the cat.', NULL, 'Chúng tôi đã sắp xếp người cho mèo ăn.', '{"wordId":"arrangement","ukIpa":"/əˈreɪndʒmənt/","usIpa":"/əˈreɪndʒmənt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A plan or preparation for something that will happen.","vi":"sự sắp xếp; sự chuẩn bị"},{"pos":"n.","en":"The way objects are positioned or organised.","vi":"sự bố trí; cách bài trí"},{"pos":"n.","en":"An agreement about how something will be done.","vi":"sự thỏa thuận; sự dàn xếp"}],"examples":[{"en":"We made arrangements for someone to feed the cat.","vi":"Chúng tôi đã sắp xếp người cho mèo ăn.","audioKind":"ex"},{"en":"Flexible working arrangements can help parents balance professional responsibilities with the demands of family life.","vi":"Sự sắp xếp công việc linh hoạt có thể giúp các bậc phụ huynh cân bằng giữa trách nhiệm nghề nghiệp và nhu cầu của đời sống gia đình.","audioKind":"ex2"}],"collocations":[{"en":"make arrangements","vi":"lên kế hoạch sắp xếp"},{"en":"travel arrangements","vi":"sắp xếp chuyến đi"},{"en":"flower arrangement","vi":"cách cắm hoa"},{"en":"come to an arrangement","vi":"đạt được thỏa thuận"}],"wordFamily":["arrange (v.)","arranger (n.)","rearrange (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ việc chuẩn bị cụ thể thường dùng dạng số nhiều: make arrangements for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lay', 'en-b1-59', 'lay', '/leɪ/', 'B1', 'đặt; để; trải; bố trí; đẻ trứng; ngoại đạo; không chuyên nghiệp; không có chức sắc', 'v.', NULL, 'Đồng nghĩa: place, put', 'Hành động đặt để dùng lay–laid–laid; hành động nằm dùng lie–lay–lain.', 'Please lay the clean towels on the bathroom shelf.', NULL, 'Xin vui lòng đặt những chiếc khăn sạch lên kệ phòng tắm.', '{"wordId":"lay","ukIpa":"/leɪ/","usIpa":"/leɪ/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to put something down carefully or arrange it flat","vi":"đặt; để; trải; bố trí"},{"pos":"v.","en":"to produce eggs from the body","vi":"đẻ trứng"},{"pos":"adj.","en":"not professionally trained in a subject or ordained in religion","vi":"ngoại đạo; không chuyên nghiệp; không có chức sắc"}],"examples":[{"en":"Please lay the clean towels on the bathroom shelf.","vi":"Xin vui lòng đặt những chiếc khăn sạch lên kệ phòng tắm.","audioKind":"ex"},{"en":"Investment in early childhood education can lay the foundations for a more skilled and adaptable workforce.","vi":"Đầu tư vào giáo dục mầm non có thể đặt nền móng cho một lực lượng lao động có tay nghề cao và dễ thích ứng hơn.","audioKind":"ex2"}],"collocations":[{"en":"lay the foundations","vi":"đặt nền móng"},{"en":"lay eggs","vi":"đẻ trứng"},{"en":"lay the table","vi":"dọn bàn ăn"},{"en":"lay cables","vi":"rải cáp ngầm"}],"wordFamily":[],"synonyms":["place","put"],"antonyms":[],"tipVi":"Hành động đặt để dùng lay–laid–laid; hành động nằm dùng lie–lay–lain.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refund', 'en-b1-59', 'refund', '/ˈriːfʌnd/', 'B1', 'khoản tiền hoàn lại; sự hoàn tiền; hoàn tiền; trả lại tiền', 'n.', 'refundable (adj.), non-refundable (adj.)', 'Đồng nghĩa: reimbursement', 'Danh từ trọng âm ở đầu; động từ đọc là /rɪˈfʌnd/, trọng âm ở cuối.', 'The shop gave me a refund for the broken kettle.', NULL, 'Cửa hàng đã hoàn lại tiền cho tôi vì chiếc ấm bị hỏng.', '{"wordId":"refund","ukIpa":"/ˈriːfʌnd/","usIpa":"/ˈriːfʌnd/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Money returned after a purchase or an overpayment.","vi":"khoản tiền hoàn lại; sự hoàn tiền"},{"pos":"v.","en":"To return money paid for something.","vi":"hoàn tiền; trả lại tiền"}],"examples":[{"en":"The shop gave me a refund for the broken kettle.","vi":"Cửa hàng đã hoàn lại tiền cho tôi vì chiếc ấm bị hỏng.","audioKind":"ex"},{"en":"Airlines should offer passengers a full refund when flights are cancelled without reasonable alternatives.","vi":"Các hãng hàng không nên hoàn lại toàn bộ tiền vé cho hành khách khi chuyến bay bị hủy mà không có phương án thay thế hợp lý.","audioKind":"ex2"}],"collocations":[{"en":"a full refund","vi":"hoàn tiền đầy đủ"},{"en":"request a refund","vi":"yêu cầu hoàn tiền"},{"en":"refund the cost","vi":"hoàn lại chi phí"}],"wordFamily":["refundable (adj.)","non-refundable (adj.)"],"synonyms":["reimbursement"],"antonyms":[],"tipVi":"Danh từ trọng âm ở đầu; động từ đọc là /rɪˈfʌnd/, trọng âm ở cuối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heavily', 'en-b1-59', 'heavily', '/ˈhevɪli/', 'B1', 'nhiều; ở mức độ lớn; nặng nề; dữ dội', 'adv.', 'heavy (adj.), heaviness (n.)', 'Trái nghĩa: lightly', 'Diễn tả mưa to dùng rain heavily, không dùng rain strongly.', 'It rained heavily while we waited for the bus.', NULL, 'Trời mưa rất to trong lúc chúng tôi đứng chờ xe buýt.', '{"wordId":"heavily","ukIpa":"/ˈhevɪli/","usIpa":"/ˈhevɪli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"To a great degree or in large amounts.","vi":"nhiều; ở mức độ lớn"},{"pos":"adv.","en":"With great weight, force, or effort.","vi":"nặng nề; dữ dội"}],"examples":[{"en":"It rained heavily while we waited for the bus.","vi":"Trời mưa rất to trong lúc chúng tôi đứng chờ xe buýt.","audioKind":"ex"},{"en":"Countries that rely heavily on imported fuel are particularly vulnerable to sudden changes in global energy prices.","vi":"Các quốc gia phụ thuộc nhiều vào nhiên liệu nhập khẩu đặc biệt dễ chịu tổn thương trước những biến động đột ngột của giá năng lượng toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"rain heavily","vi":"mưa to"},{"en":"rely heavily on","vi":"phụ thuộc nhiều vào"},{"en":"invest heavily in","vi":"đầu tư mạnh mẽ vào"},{"en":"breathe heavily","vi":"thở hồng hộc"}],"wordFamily":["heavy (adj.)","heaviness (n.)"],"synonyms":[],"antonyms":["lightly"],"tipVi":"Diễn tả mưa to dùng rain heavily, không dùng rain strongly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tank', 'en-b1-59', 'tank', '/tæŋk/', 'B1', 'bể chứa; thùng chứa; hồ nước; xe tăng', 'n.', NULL, NULL, 'fish tank là bể cá cảnh; bình xăng ô tô dùng fuel tank.', 'The fish swam behind a rock in the tank.', NULL, 'Con cá bơi phía sau một tảng đá trong bể cá.', '{"wordId":"tank","ukIpa":"/tæŋk/","usIpa":"/tæŋk/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A large container for holding liquids or gases.","vi":"bể chứa; thùng chứa; hồ nước"},{"pos":"n.","en":"A heavily protected military vehicle that moves on tracks.","vi":"xe tăng"}],"examples":[{"en":"The fish swam behind a rock in the tank.","vi":"Con cá bơi phía sau một tảng đá trong bể cá.","audioKind":"ex"},{"en":"Installing a rainwater tank allows households to water gardens without relying entirely on treated drinking water.","vi":"Việc lắp đặt bể chứa nước mưa giúp các hộ gia đình tưới cây mà không phải phụ thuộc hoàn toàn vào nước máy.","audioKind":"ex2"}],"collocations":[{"en":"a water tank","vi":"bể chứa nước"},{"en":"a fuel tank","vi":"bình xăng"},{"en":"a fish tank","vi":"bể cá"},{"en":"fill the tank","vi":"đổ đầy bình xăng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"fish tank là bể cá cảnh; bình xăng ô tô dùng fuel tank.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_iron', 'en-b1-59', 'iron', '/ˈaɪərn/', 'B1', 'sắt; chất sắt; bàn là; bàn ủi; ủi; là', 'n.', 'ironing (n.)', NULL, 'Sắt là danh từ không đếm được; bàn là đếm được, dùng an iron.', 'These old iron gates are too heavy to lift.', NULL, 'Những cánh cổng sắt cũ này quá nặng không nhấc lên được.', '{"wordId":"iron","ukIpa":"/ˈaɪən/","usIpa":"/ˈaɪərn/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A strong metal used in construction and needed by the body.","vi":"sắt; chất sắt"},{"pos":"n.","en":"A tool with a heated base for smoothing clothes.","vi":"bàn là; bàn ủi"},{"pos":"v.","en":"To make clothes smooth using a heated iron.","vi":"ủi; là"}],"examples":[{"en":"These old iron gates are too heavy to lift.","vi":"Những cánh cổng sắt cũ này quá nặng không nhấc lên được.","audioKind":"ex"},{"en":"A diet containing sufficient iron can help prevent anaemia, particularly among children and pregnant women.","vi":"Chế độ ăn uống chứa đủ chất sắt có thể giúp ngăn ngừa bệnh thiếu máu, đặc biệt là ở trẻ em và phụ nữ mang thai.","audioKind":"ex2"}],"collocations":[{"en":"iron deficiency","vi":"thiếu sắt"},{"en":"iron ore","vi":"quặng sắt"},{"en":"cast iron","vi":"gang"},{"en":"iron a shirt","vi":"ủi một chiếc áo sơ mi"}],"wordFamily":["ironing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Sắt là danh từ không đếm được; bàn là đếm được, dùng an iron.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mixed', 'en-b1-59', 'mixed', '/mɪkst/', 'B1', 'hỗn hợp; gồm nhiều loại khác nhau; lẫn lộn; vui buồn lẫn lộn; khen chê đan xen', 'adj.', 'mix (v.), mixture (n.), mixing (n.)', 'Đồng nghĩa: assorted, varied', 'mixed feelings chỉ tâm trạng mâu thuẫn; mixed đồng thời là phân từ quá khứ của mix.', 'I bought a bag of mixed nuts for our picnic.', NULL, 'Tôi đã mua một gói hạt hỗn hợp cho buổi dã ngoại của chúng tôi.', '{"wordId":"mixed","ukIpa":"/mɪkst/","usIpa":"/mɪkst/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"containing different types of things or people","vi":"hỗn hợp; gồm nhiều loại khác nhau"},{"pos":"adj.","en":"including both positive and negative feelings, opinions, or results","vi":"lẫn lộn; vui buồn lẫn lộn; khen chê đan xen"}],"examples":[{"en":"I bought a bag of mixed nuts for our picnic.","vi":"Tôi đã mua một gói hạt hỗn hợp cho buổi dã ngoại của chúng tôi.","audioKind":"ex"},{"en":"The introduction of online lessons received mixed reactions from students, parents, and teachers.","vi":"Việc áp dụng các bài học trực tuyến nhận được phản ứng trái chiều từ học sinh, phụ huynh và giáo viên.","audioKind":"ex2"}],"collocations":[{"en":"mixed feelings","vi":"cảm xúc lẫn lộn"},{"en":"mixed results","vi":"kết quả vui buồn lẫn lộn"},{"en":"mixed reactions","vi":"phản ứng trái chiều"},{"en":"mixed nuts","vi":"hạt hỗn hợp"}],"wordFamily":["mix (v.)","mixture (n.)","mixing (n.)"],"synonyms":["assorted","varied"],"antonyms":[],"tipVi":"mixed feelings chỉ tâm trạng mâu thuẫn; mixed đồng thời là phân từ quá khứ của mix.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pint', 'en-b1-59', 'pint', '/paɪnt/', 'B1', 'phtin (đơn vị đo dung tích bằng khoảng nửa lít)', 'n.', NULL, NULL, 'Một phtin Anh khoảng 568 ml, trong khi một phtin chất lỏng Mỹ khoảng 473 ml.', 'Please add a pint of milk to the bowl.', NULL, 'Xin hãy cho một phtin sữa vào tô.', '{"wordId":"pint","ukIpa":"/paɪnt/","usIpa":"/paɪnt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A liquid measure of about half a litre.","vi":"phtin (đơn vị đo dung tích bằng khoảng nửa lít)"}],"examples":[{"en":"Please add a pint of milk to the bowl.","vi":"Xin hãy cho một phtin sữa vào tô.","audioKind":"ex"},{"en":"Consumers comparing international recipes should note that a British pint is larger than an American pint.","vi":"Người tiêu dùng so sánh các công thức nấu ăn quốc tế nên lưu ý rằng một phtin của Anh lớn hơn một phtin của Mỹ.","audioKind":"ex2"}],"collocations":[{"en":"a pint of milk","vi":"một phtin sữa"},{"en":"half a pint","vi":"nửa phtin"},{"en":"a pint glass","vi":"cốc uống bia phtin"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Một phtin Anh khoảng 568 ml, trong khi một phtin chất lỏng Mỹ khoảng 473 ml.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_apart', 'en-b1-59', 'apart', '/əˈpɑːrt/', 'B1', 'cách xa nhau; tách biệt; thành mảnh vụn; rời ra; ngoại trừ; ngoài ra', 'adv.', NULL, 'Trái nghĩa: together', 'apart from có thể mang nghĩa "ngoại trừ" hoặc "ngoài... ra", tùy thuộc vào ngữ cảnh.', 'We planted the young trees two metres apart.', NULL, 'Chúng tôi trồng những cây non cách nhau hai mét.', '{"wordId":"apart","ukIpa":"/əˈpɑːt/","usIpa":"/əˈpɑːrt/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"separated by distance or time; not together","vi":"cách xa nhau; tách biệt"},{"pos":"adv.","en":"into separate pieces","vi":"thành mảnh vụn; rời ra"},{"pos":"adv.","en":"except for something being considered","vi":"ngoại trừ; ngoài ra"}],"examples":[{"en":"We planted the young trees two metres apart.","vi":"Chúng tôi trồng những cây non cách nhau hai mét.","audioKind":"ex"},{"en":"Living apart from their families can make international students more independent, but may also cause loneliness.","vi":"Sống xa gia đình có thể khiến du học sinh trở nên độc lập hơn, nhưng cũng có thể gây ra cảm giác cô đơn.","audioKind":"ex2"}],"collocations":[{"en":"far apart","vi":"cách nhau xa"},{"en":"take apart","vi":"tháo rời"},{"en":"apart from","vi":"ngoại trừ"},{"en":"tell apart","vi":"phân biệt"}],"wordFamily":[],"synonyms":[],"antonyms":["together"],"tipVi":"apart from có thể mang nghĩa \"ngoại trừ\" hoặc \"ngoài... ra\", tùy thuộc vào ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alike', 'en-b1-59', 'alike', '/əˈlaɪk/', 'B1', 'tương tự; giống nhau; như nhau; đều đặn cho cả hai bên', 'adj.', 'likeness (n.)', 'Đồng nghĩa: similar · Trái nghĩa: different', 'Tính từ alike thường đứng sau động từ liên kết, không đứng trực tiếp trước danh từ.', 'These two jackets look alike, but one feels warmer.', NULL, 'Hai chiếc áo khoác này trông rất giống nhau, nhưng một chiếc mặc ấm hơn.', '{"wordId":"alike","ukIpa":"/əˈlaɪk/","usIpa":"/əˈlaɪk/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"similar in appearance or character","vi":"tương tự; giống nhau"},{"pos":"adv.","en":"in the same way, or equally for both groups","vi":"như nhau; đều đặn cho cả hai bên"}],"examples":[{"en":"These two jackets look alike, but one feels warmer.","vi":"Hai chiếc áo khoác này trông rất giống nhau, nhưng một chiếc mặc ấm hơn.","audioKind":"ex"},{"en":"Public parks benefit children and adults alike by providing accessible spaces for exercise and relaxation.","vi":"Các công viên công cộng mang lại lợi ích cho cả trẻ em lẫn người lớn bằng cách cung cấp không gian dễ tiếp cận để tập thể dục và thư giãn.","audioKind":"ex2"}],"collocations":[{"en":"look alike","vi":"trông giống nhau"},{"en":"think alike","vi":"có cùng suy nghĩ"},{"en":"treat everyone alike","vi":"đối xử với mọi người như nhau"}],"wordFamily":["likeness (n.)"],"synonyms":["similar"],"antonyms":["different"],"tipVi":"Tính từ alike thường đứng sau động từ liên kết, không đứng trực tiếp trước danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vinegar', 'en-b1-59', 'vinegar', '/ˈvɪnɪɡɚ/', 'B1', 'giấm', 'n.', NULL, NULL, 'Thường là danh từ không đếm được, khi muốn chỉ số lượng có thể dùng a bottle of vinegar (một chai giấm).', 'Add a little vinegar to the salad dressing.', NULL, 'Cho thêm một chút giấm vào nước sốt salad.', '{"wordId":"vinegar","ukIpa":"/ˈvɪnɪɡə/","usIpa":"/ˈvɪnɪɡɚ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A sour liquid used to flavour or preserve food.","vi":"giấm"}],"examples":[{"en":"Add a little vinegar to the salad dressing.","vi":"Cho thêm một chút giấm vào nước sốt salad.","audioKind":"ex"},{"en":"Traditional food preservation methods often use vinegar to slow bacterial growth and extend the storage life of vegetables.","vi":"Các phương pháp bảo quản thực phẩm truyền thống thường dùng giấm để kìm hãm sự phát triểnของ vi khuẩn và kéo dài thời gian bảo quản rau củ.","audioKind":"ex2"}],"collocations":[{"en":"rice vinegar","vi":"giấm gạo"},{"en":"wine vinegar","vi":"giấm táo/giấm rượu vang"},{"en":"a splash of vinegar","vi":"một chút giấm"},{"en":"pickled in vinegar","vi":"ngâm giấm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được, khi muốn chỉ số lượng có thể dùng a bottle of vinegar (một chai giấm).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_59_1', 'en-b1-59', 'Cách dùng “condition” (n.) — tình trạng; trạng thái', 'in good condition  ·  working conditions  ·  on condition that', 'Danh từ khi chỉ trạng thái thường là không đếm được; khi chỉ điều kiện làm việc hoặc sinh sống thường dùng dạng số nhiều.', 'Họ từ (Word Family): conditional (adj.), conditionally (adv.), unconditional (adj.) | Đồng nghĩa: state, requirement', '[{"hanzi":"Despite its age, this bicycle is in excellent condition.","pinyin":"","meaning":"Dù đã có tuổi, chiếc xe đạp này vẫn đang ở tình trạng rất tốt."},{"hanzi":"Improving working conditions can increase employee satisfaction and reduce the number of people leaving their jobs.","pinyin":"","meaning":"Việc cải thiện điều kiện làm việc có thể nâng cao sự hài lòng của nhân viên và giảm tỷ lệ nhân viên nghỉ việc."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_59_2', 'en-b1-59', 'Cách dùng “vinegar” (n.) — giấm', 'rice vinegar  ·  wine vinegar  ·  a splash of vinegar', 'Thường là danh từ không đếm được, khi muốn chỉ số lượng có thể dùng a bottle of vinegar (một chai giấm).', NULL, '[{"hanzi":"Add a little vinegar to the salad dressing.","pinyin":"","meaning":"Cho thêm một chút giấm vào nước sốt salad."},{"hanzi":"Traditional food preservation methods often use vinegar to slow bacterial growth and extend the storage life of vegetables.","pinyin":"","meaning":"Các phương pháp bảo quản thực phẩm truyền thống thường dùng giấm để kìm hãm sự phát triểnของ vi khuẩn và kéo dài thời gian bảo quản rau củ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_59_3', 'en-b1-59', 'Cách dùng “filling” (n.) — nhân; phần nhân kẹp bên trong', 'a sandwich filling  ·  a dental filling  ·  a filling meal', 'Tính từ filling dùng để chỉ thức ăn làm cho no, không dùng để chỉ trạng thái cảm thấy no của con người.', 'Họ từ (Word Family): fill (v.), filled (adj.), filler (n.)', '[{"hanzi":"This pie has a warm apple and cinnamon filling.","pinyin":"","meaning":"Chiếc bánh nướng này có phần nhân táo và quế ấm nóng."},{"hanzi":"School lunches should offer filling meals that provide sufficient nutrients to support children''s growth and concentration.","pinyin":"","meaning":"Bữa trưa ở trường nên cung cấp những món ăn đủ no và đầy đủ chất dinh dưỡng để hỗ trợ sự phát triển cũng như khả năng tập trung của trẻ em."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_59_4', 'en-b1-59', 'Cách dùng “cap” (n.) — mũ lưỡi trai; mũ mềm có vành cứng phía trước', 'baseball cap  ·  bottle cap  ·  cap spending', 'cap dùng như động từ có nghĩa là thiết lập giới hạn; dùng cụm "a cap on" để chỉ đối tượng bị giới hạn.', 'Họ từ (Word Family): capped (adj.)', '[{"hanzi":"He pulled on his cap before leaving for practice.","pinyin":"","meaning":"Anh ấy đội chiếc mũ lưỡi trai của mình trước khi đi tập."},{"hanzi":"Governments could cap annual rent increases to protect households from sudden rises in housing costs.","pinyin":"","meaning":"Chính phủ có thể áp trần tăng giá thuê nhà hàng năm để bảo vệ các hộ gia đình trước tình trạng chi phí nhà ở tăng vọt đột ngột."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_59_1', 'en-b1-59', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_59_1_1', 'ten_b1_59_1', 'cap', 'He pulled on his cap before leaving for practice.', 'He pulled on his cap before leaving for practice.', '/kæp/', 'Anh ấy đội chiếc mũ lưỡi trai của mình trước khi đi tập.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_59_1_2', 'ten_b1_59_1', 'peach', 'She sliced a ripe peach into her breakfast bowl.', 'She sliced a ripe peach into her breakfast bowl.', '/piːtʃ/', 'Cô ấy cắt một quả đào chín vào bát bữa sáng của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_59_1_3', 'ten_b1_59_1', 'sender', 'The sender wrapped the parcel carefully before posting it.', 'The sender wrapped the parcel carefully before posting it.', '/ˈsendər/', 'Người gửi đã gói bưu kiện cẩn thận trước khi đem đi gửi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_59_1_4', 'ten_b1_59_1', 'fetch', 'Could you fetch my jacket from the bedroom?', 'Could you fetch my jacket from the bedroom?', '/fetʃ/', 'Bạn có thể lấy giúp tôi chiếc áo khoác trong phòng ngủ được không?', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_59_1_5', 'ten_b1_59_1', 'badge', 'She pinned her new badge onto her jacket.', 'She pinned her new badge onto her jacket.', '/bædʒ/', 'Cô ấy ghim huy hiệu mới của mình lên áo khoác.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_59_1_6', 'ten_b1_59_1', 'freeze', 'Freeze the leftover soup and eat it next week.', 'Freeze the leftover soup and eat it next week.', '/friːz/', 'Hãy đông lạnh phần súp còn thừa lại và ăn vào tuần tới.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
