INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_59_1_8', 'ten_b1_59_1', 'condition', 'Despite its age, this bicycle is in excellent condition.', 'Despite its age, this bicycle is in excellent condition.', '/kənˈdɪʃən/', 'Dù đã có tuổi, chiếc xe đạp này vẫn đang ở tình trạng rất tốt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_59_1_1', 'en-b1-59', 'ten_b1_59_1', 'listening', 'listening', 'He pulled on his cap before leaving for practice.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Làm ơn để những đôi giày hôi thối đó ở ngoài cửa trước.","Người gửi đã gói bưu kiện cẩn thận trước khi đem đi gửi.","Anh ấy đội chiếc mũ lưỡi trai của mình trước khi đi tập.","Trời mưa rất to trong lúc chúng tôi đứng chờ xe buýt."]'::jsonb, 2, 'He pulled on his cap before leaving for practice. → Anh ấy đội chiếc mũ lưỡi trai của mình trước khi đi tập.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_59_1_2', 'en-b1-59', 'ten_b1_59_1', 'listening', 'listening', 'She sliced a ripe peach into her breakfast bowl.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một quả bí ngô khổng lồ lấp đầy chiếc giỏ trên bàn bếp của chúng tôi.","Cô ấy cắt một quả đào chín vào bát bữa sáng của mình.","Cửa hàng đã hoàn lại tiền cho tôi vì chiếc ấm bị hỏng.","Cho thêm một chút giấm vào nước sốt salad."]'::jsonb, 1, 'She sliced a ripe peach into her breakfast bowl. → Cô ấy cắt một quả đào chín vào bát bữa sáng của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_59_1_3', 'en-b1-59', 'ten_b1_59_1', 'listening', 'listening', 'The sender wrapped the parcel carefully before posting it.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người gửi đã gói bưu kiện cẩn thận trước khi đem đi gửi.","Cho thêm một chút giấm vào nước sốt salad.","Hai chiếc áo khoác này trông rất giống nhau, nhưng một chiếc mặc ấm hơn.","Hãy đông lạnh phần súp còn thừa lại và ăn vào tuần tới."]'::jsonb, 0, 'The sender wrapped the parcel carefully before posting it. → Người gửi đã gói bưu kiện cẩn thận trước khi đem đi gửi.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_59_2', 'en-b1-59', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_59_2_1', 'ten_b1_59_2', 'cap', 'Governments could cap annual rent increases to protect households from sudden rises in housing costs.', 'Governments could cap annual rent increases to protect households from sudden rises in housing costs.', '/kæp/', 'Chính phủ có thể áp trần tăng giá thuê nhà hàng năm để bảo vệ các hộ gia đình trước tình trạng chi phí nhà ở tăng vọt đột ngột.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_59_2_2', 'ten_b1_59_2', 'peach', 'Peach growers may face reduced harvests when unusually warm winters disrupt the trees'' natural flowering cycle.', 'Peach growers may face reduced harvests when unusually warm winters disrupt the trees'' natural flowering cycle.', '/piːtʃ/', 'Những người trồng đào có thể phải đối mặt với tình trạng giảm thu hoạch khi mùa đông ấm bất thường làm gián đoạn chu kỳ ra hoa tự nhiên của cây.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_59_2_3', 'ten_b1_59_2', 'sender', 'Email users should verify the sender before opening attachments to reduce the risk of digital fraud.', 'Email users should verify the sender before opening attachments to reduce the risk of digital fraud.', '/ˈsendər/', 'Người dùng email nên xác minh người gửi trước khi mở các tệp đính kèm để giảm thiểu rủi ro gian lận trực tuyến.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_59_2_4', 'ten_b1_59_2', 'fetch', 'Homes near reliable public transport often fetch higher prices because buyers value convenient access to employment.', 'Homes near reliable public transport often fetch higher prices because buyers value convenient access to employment.', '/fetʃ/', 'Nhà ở gần các tuyến giao thông công cộng thuận tiện thường bán được giá cao hơn vì người mua coi trọng sự tiện lợi khi đi lại.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_59_2_5', 'ten_b1_59_2', 'badge', 'Requiring visitors to wear a visible badge can improve security in schools and other public buildings.', 'Requiring visitors to wear a visible badge can improve security in schools and other public buildings.', '/bædʒ/', 'Việc yêu cầu khách tham quan đeo huy hiệu nhận diện rõ ràng có thể nâng cao an ninh tại trường học và các tòa nhà công cộng khác.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_59_2_6', 'ten_b1_59_2', 'freeze', 'Governments may freeze public transport fares to reduce financial pressure on households during economic downturns.', 'Governments may freeze public transport fares to reduce financial pressure on households during economic downturns.', '/friːz/', 'Chính phủ có thể đóng băng giá vé phương tiện giao thông công cộng để giảm bớt áp lực tài chính cho các hộ gia đình trong thời kỳ kinh tế suy thoái.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_59_2_1', 'en-b1-59', 'ten_b1_59_2', 'listening', 'listening', 'Governments could cap annual rent increases to protect households from sudden rises in housing costs.', NULL, 'Trong câu vừa nghe, từ “cap” mang nghĩa nào sau đây?', '["kẹo cao su","xe taxi","mũ lưỡi trai; mũ mềm có vành cứng phía trước","thử thách; nhiệm vụ khó khăn"]'::jsonb, 2, '“cap” (/kæp/): mũ lưỡi trai; mũ mềm có vành cứng phía trước. Câu đầy đủ: Governments could cap annual rent increases to protect households from sudden rises in housing costs.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_59_2_2', 'en-b1-59', 'ten_b1_59_2', 'listening', 'listening', 'Peach growers may face reduced harvests when unusually warm winters disrupt the trees'' natural flowering cycle.', NULL, 'Trong câu vừa nghe, từ “peach” mang nghĩa nào sau đây?', '["quả đào","trực tiếp","người đã tốt nghiệp đại học","môn thể thao chèo bè; đi bè vượt thác"]'::jsonb, 0, '“peach” (/piːtʃ/): quả đào. Câu đầy đủ: Peach growers may face reduced harvests when unusually warm winters disrupt the trees'' natural flowering cycle.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
