INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_59_2', 'en-b1-59', NULL, 'comprehensive_test', 'listening', 'She sliced a ripe peach into her breakfast bowl.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cho thêm một chút giấm vào nước sốt salad.","Nữ chủ nhà của chúng tôi đã qua sửa vòi nước trong bếp.","Cô ấy cắt một quả đào chín vào bát bữa sáng của mình.","Những cánh cổng sắt cũ này quá nặng không nhấc lên được."]'::jsonb, 2, 'She sliced a ripe peach into her breakfast bowl. → Cô ấy cắt một quả đào chín vào bát bữa sáng của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_59_3', 'en-b1-59', NULL, 'comprehensive_test', 'listening', 'sender', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hối tiếc; ân hận","người gửi; bên gửi (thư, tin nhắn hoặc bưu phẩm)","trận động đất","khiếm thị; mù"]'::jsonb, 1, 'sender (/ˈsendər/) → người gửi; bên gửi (thư, tin nhắn hoặc bưu phẩm)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_59_4', 'en-b1-59', NULL, 'comprehensive_test', 'listening', 'Could you fetch my jacket from the bedroom?', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi trồng những cây non cách nhau hai mét.","Xin hãy cho một phtin sữa vào tô.","Bạn có thể lấy giúp tôi chiếc áo khoác trong phòng ngủ được không?","Trời mưa rất to trong lúc chúng tôi đứng chờ xe buýt."]'::jsonb, 2, 'Could you fetch my jacket from the bedroom? → Bạn có thể lấy giúp tôi chiếc áo khoác trong phòng ngủ được không?', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_59_5', 'en-b1-59', NULL, 'comprehensive_test', 'listening', 'badge', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ngay lập tức; tức thì","huy hiệu; thẻ tên; biểu tượng","nguồn; nguồn gốc","nhiều; thừa thãi; đủ dùng"]'::jsonb, 1, 'badge (/bædʒ/) → huy hiệu; thẻ tên; biểu tượng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_59_6', 'en-b1-59', NULL, 'comprehensive_test', 'listening', 'Freeze the leftover soup and eat it next week.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy đông lạnh phần súp còn thừa lại và ăn vào tuần tới.","Xin vui lòng đặt những chiếc khăn sạch lên kệ phòng tắm.","Chiếc bánh nướng này có phần nhân táo và quế ấm nóng.","Cửa hàng đã hoàn lại tiền cho tôi vì chiếc ấm bị hỏng."]'::jsonb, 0, 'Freeze the leftover soup and eat it next week. → Hãy đông lạnh phần súp còn thừa lại và ăn vào tuần tới.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_59_7', 'en-b1-59', NULL, 'comprehensive_test', 'listening', 'filling', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["việc ăn uống; dùng bữa","thuộc về điện tử; dùng vi mạch điện tử","nhân; phần nhân kẹp bên trong","chủ yếu là; phần lớn"]'::jsonb, 2, 'filling (/ˈfɪlɪŋ/) → nhân; phần nhân kẹp bên trong; chất hàn răng; vật liệu trám răng; làm no; dễ no', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
