INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_59_18', 'en-b1-59', NULL, 'comprehensive_test', 'reading', NULL, 'Governments could cap annual rent increases to protect households from sudden rises in housing costs.', 'Dựa vào câu trên, từ “cap” có nghĩa phù hợp nhất là gì?', '["mũ lưỡi trai; mũ mềm có vành cứng phía trước","giao hàng; phân phát","lễ kỷ niệm; sự kiện ăn mừng","tiệc tự chọn; tiệc buffet"]'::jsonb, 0, 'cap: mũ lưỡi trai; mũ mềm có vành cứng phía trước; nắp; nút đậy (che phần đầu hoặc miệng của vật gì); giới hạn mức tối đa. Dịch cả câu: Chính phủ có thể áp trần tăng giá thuê nhà hàng năm để bảo vệ các hộ gia đình trước tình trạng chi phí nhà ở tăng vọt đột ngột.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_59_19', 'en-b1-59', NULL, 'comprehensive_test', 'reading', NULL, 'Peach growers may face reduced harvests when unusually warm winters disrupt the trees'' natural flowering cycle.', 'Dựa vào câu trên, từ “peach” có nghĩa phù hợp nhất là gì?', '["cơ; bắp thịt","trích dẫn","quả đào","hy vọng rằng; mong sao"]'::jsonb, 2, 'peach: quả đào; màu hồng cam nhạt. Dịch cả câu: Những người trồng đào có thể phải đối mặt với tình trạng giảm thu hoạch khi mùa đông ấm bất thường làm gián đoạn chu kỳ ra hoa tự nhiên của cây.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_59_20', 'en-b1-59', NULL, 'comprehensive_test', 'reading', NULL, 'Email users should verify the sender before opening attachments to reduce the risk of digital fraud.', 'Dựa vào câu trên, từ “sender” có nghĩa phù hợp nhất là gì?', '["người gửi; bên gửi (thư, tin nhắn hoặc bưu phẩm)","trước; trước đó; cũ","quả lạc; hạt đậu phộng","tự tin"]'::jsonb, 0, 'sender: người gửi; bên gửi (thư, tin nhắn hoặc bưu phẩm). Dịch cả câu: Người dùng email nên xác minh người gửi trước khi mở các tệp đính kèm để giảm thiểu rủi ro gian lận trực tuyến.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_59_21', 'en-b1-59', NULL, 'comprehensive_test', 'reading', NULL, 'Homes near reliable public transport often fetch higher prices because buyers value convenient access to employment.', 'Dựa vào câu trên, từ “fetch” có nghĩa phù hợp nhất là gì?', '["cấp dưới; sơ cấp; ít thâm niên hơn","sọc; vạch; đường sọc","mũi tiêm; sự tiêm thuốc","đi lấy; mang về; tìm và mang đến"]'::jsonb, 3, 'fetch: đi lấy; mang về; tìm và mang đến; bán được (với một mức giá cụ thể). Dịch cả câu: Nhà ở gần các tuyến giao thông công cộng thuận tiện thường bán được giá cao hơn vì người mua coi trọng sự tiện lợi khi đi lại.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_59_22', 'en-b1-59', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cách xa nhau; tách biệt”', '["fairly","apart","option","diving"]'::jsonb, 1, 'cách xa nhau; tách biệt → apart (/əˈpɑːrt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_59_23', 'en-b1-59', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tương tự; giống nhau”', '["odd","alike","intermediate","cottage"]'::jsonb, 1, 'tương tự; giống nhau → alike (/əˈlaɪk/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_59_24', 'en-b1-59', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giấm”', '["vinegar","sadness","impress","delay"]'::jsonb, 0, 'giấm → vinegar (/ˈvɪnɪɡɚ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-60', 'en', 'Bài 60: Đời sống hằng ngày (12) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3060, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chilly', 'en-b1-60', 'chilly', '/ˈtʃɪli/', 'B1', 'lạnh buốt; se lạnh; lạnh nhạt; thờ ơ', 'adj.', 'chill (n.), chill (v.), chilliness (n.)', 'Đồng nghĩa: cold, cool · Trái nghĩa: warm', 'Chilly có mức độ lạnh nhẹ hơn freezing, đồng thời có thể dùng để mô tả thái độ lạnh lùng, xa cách.', 'It felt chilly outside, so I grabbed my jacket.', NULL, 'Bên ngoài trời se lạnh nên tôi đã lấy áo khoác mặc vào.', '{"wordId":"chilly","ukIpa":"/ˈtʃɪli/","usIpa":"/ˈtʃɪli/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Unpleasantly cold, though usually not extremely cold.","vi":"lạnh buốt; se lạnh"},{"pos":"adj.","en":"Showing little warmth or friendliness towards someone.","vi":"lạnh nhạt; thờ ơ"}],"examples":[{"en":"It felt chilly outside, so I grabbed my jacket.","vi":"Bên ngoài trời se lạnh nên tôi đã lấy áo khoác mặc vào.","audioKind":"ex"},{"en":"Providing warm public spaces during chilly weather can help protect older residents from cold-related illnesses.","vi":"Việc cung cấp không gian công cộng ấm áp trong thời tiết se lạnh có thể giúp bảo vệ cư dân lớn tuổi khỏi các bệnh do lạnh.","audioKind":"ex2"}],"collocations":[{"en":"a chilly morning","vi":"buổi sáng se lạnh"},{"en":"feel chilly","vi":"cảm thấy lạnh"},{"en":"a chilly reception","vi":"sự tiếp đón lạnh nhạt"}],"wordFamily":["chill (n.)","chill (v.)","chilliness (n.)"],"synonyms":["cold","cool"],"antonyms":["warm"],"tipVi":"Chilly có mức độ lạnh nhẹ hơn freezing, đồng thời có thể dùng để mô tả thái độ lạnh lùng, xa cách.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peaceful', 'en-b1-60', 'peaceful', '/ˈpiːsfəl/', 'B1', 'yên bình; thanh bình; tĩnh lặng; hòa bình; không bạo lực', 'adj.', 'peace (n.), peacefully (adv.), peacefulness (n.)', 'Đồng nghĩa: calm, tranquil · Trái nghĩa: violent, noisy', 'Có thể dùng để chỉ môi trường yên tĩnh hoặc hành động không dùng bạo lực.', 'The lake looks peaceful in the early morning light.', NULL, 'Hồ nước trông thật yên bình trong ánh sáng sớm mai.', '{"wordId":"peaceful","ukIpa":"/ˈpiːsfəl/","usIpa":"/ˈpiːsfəl/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"quiet and calm, without disturbance or worry","vi":"yên bình; thanh bình; tĩnh lặng"},{"pos":"adj.","en":"not involving war, violence, or fighting","vi":"hòa bình; không bạo lực"}],"examples":[{"en":"The lake looks peaceful in the early morning light.","vi":"Hồ nước trông thật yên bình trong ánh sáng sớm mai.","audioKind":"ex"},{"en":"Creating peaceful public spaces can improve residents'' wellbeing and encourage more people to spend time outdoors.","vi":"Việc tạo ra các không gian công cộng yên bình có thể nâng cao phúc lợi của cư dân và khuyến khích nhiều người ra ngoài trời hơn.","audioKind":"ex2"}],"collocations":[{"en":"peaceful surroundings","vi":"khung cảnh yên bình"},{"en":"peaceful protest","vi":"cuộc biểu tình ôn hòa"},{"en":"peaceful solution","vi":"giải pháp hòa bình"}],"wordFamily":["peace (n.)","peacefully (adv.)","peacefulness (n.)"],"synonyms":["calm","tranquil"],"antonyms":["violent","noisy"],"tipVi":"Có thể dùng để chỉ môi trường yên tĩnh hoặc hành động không dùng bạo lực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_teacup', 'en-b1-60', 'teacup', '/ˈtiːkʌp/', 'B1', 'tách trà; chén trà', 'n.', NULL, NULL, 'teacup là cái tách trà; còn a cup of tea là một tách trà.', 'She placed a delicate teacup beside the biscuit plate.', NULL, 'Cô ấy đặt một chiếc tách trà tinh xảo bên cạnh đĩa bánh quy.', '{"wordId":"teacup","ukIpa":"/ˈtiːkʌp/","usIpa":"/ˈtiːkʌp/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A small cup with a handle, used for drinking tea.","vi":"tách trà; chén trà"}],"examples":[{"en":"She placed a delicate teacup beside the biscuit plate.","vi":"Cô ấy đặt một chiếc tách trà tinh xảo bên cạnh đĩa bánh quy.","audioKind":"ex"},{"en":"A museum display of decorated teacups can reveal how domestic tastes and manufacturing techniques changed over time.","vi":"Triển lãm bảo tàng về những chiếc tách trà trang trí có thể cho thấy gu thẩm mỹ gia đình và kỹ thuật sản xuất đã thay đổi theo thời gian như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"a china teacup","vi":"tách trà bằng sứ"},{"en":"a teacup and saucer","vi":"tách trà và đĩa lót"},{"en":"a storm in a teacup","vi":"chuyện bé xé ra to"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"teacup là cái tách trà; còn a cup of tea là một tách trà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rarely', 'en-b1-60', 'rarely', '/ˈrerli/', 'B1', 'hiếm khi; ít khi', 'adv.', 'rare (adj.), rarity (n.)', 'Đồng nghĩa: seldom, infrequently · Trái nghĩa: often, frequently', 'Thường đặt trước động từ thường và sau động từ "be"; bản thân từ này đã mang nghĩa phủ định.', 'We rarely eat outside when the weather turns cold.', NULL, 'Chúng tôi hiếm khi ăn ngoài khi trời trở lạnh.', '{"wordId":"rarely","ukIpa":"/ˈreəli/","usIpa":"/ˈrerli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"Not often; on very few occasions.","vi":"hiếm khi; ít khi"}],"examples":[{"en":"We rarely eat outside when the weather turns cold.","vi":"Chúng tôi hiếm khi ăn ngoài khi trời trở lạnh.","audioKind":"ex"},{"en":"People living in remote villages rarely have easy access to specialist medical services.","vi":"Những người sống ở các ngôi làng hẻo lánh hiếm khi có cơ hội tiếp cận dễ dàng với các dịch vụ y tế chuyên khoa.","audioKind":"ex2"}],"collocations":[{"en":"rarely ever","vi":"rất hiếm khi"},{"en":"rarely seen","vi":"hiếm thấy"},{"en":"rarely used","vi":"ít khi được sử dụng"}],"wordFamily":["rare (adj.)","rarity (n.)"],"synonyms":["seldom","infrequently"],"antonyms":["often","frequently"],"tipVi":"Thường đặt trước động từ thường và sau động từ \"be\"; bản thân từ này đã mang nghĩa phủ định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hardly', 'en-b1-60', 'hardly', '/ˈhɑːrdli/', 'B1', 'hầu như không; hầu như chẳng; vừa mới... thì', 'adv.', NULL, 'Đồng nghĩa: scarcely, barely', 'Hardly mang nghĩa hầu như không, không phải là trạng từ của hard.', 'I could hardly hear you over the heavy rain.', NULL, 'Tôi hầu như không nghe thấy bạn nói gì vì tiếng mưa rơi quá lớn.', '{"wordId":"hardly","ukIpa":"/ˈhɑːdli/","usIpa":"/ˈhɑːrdli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"almost not, or only to a very small degree","vi":"hầu như không; hầu như chẳng"},{"pos":"adv.","en":"only just, before something else happens","vi":"vừa mới... thì"}],"examples":[{"en":"I could hardly hear you over the heavy rain.","vi":"Tôi hầu như không nghe thấy bạn nói gì vì tiếng mưa rơi quá lớn.","audioKind":"ex"},{"en":"Expanding roads alone is hardly sufficient to solve traffic congestion without improvements to public transport.","vi":"Chỉ mở rộng đường sá thôi thì hầu như không đủ để giải quyết tình trạng tắc nghẽn giao thông nếu không cải thiện giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"hardly ever","vi":"hầu như không bao giờ"},{"en":"hardly any","vi":"hầu như không có chút nào"},{"en":"can hardly wait","vi":"nóng lòng chờ đợi"},{"en":"hardly surprising","vi":"không có gì ngạc nhiên"}],"wordFamily":[],"synonyms":["scarcely","barely"],"antonyms":[],"tipVi":"Hardly mang nghĩa hầu như không, không phải là trạng từ của hard.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_difficulty', 'en-b1-60', 'difficulty', '/ˈdɪfɪkəlti/', 'B1', 'sự khó khăn; nỗi vất vả; điều khó khăn; trở ngại', 'n.', 'difficult (adj.)', 'Đồng nghĩa: trouble, problem · Trái nghĩa: ease', 'Dùng have difficulty doing, không dùng difficulty to do.', 'I had difficulty opening the jar with wet hands.', NULL, 'Tôi gặp khó khăn khi mở chiếc hũ với đôi tay ướt.', '{"wordId":"difficulty","ukIpa":"/ˈdɪfɪkəlti/","usIpa":"/ˈdɪfɪkəlti/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The state of being hard to do or understand.","vi":"sự khó khăn; nỗi vất vả"},{"pos":"n.","en":"A problem that makes progress or success harder.","vi":"điều khó khăn; trở ngại"}],"examples":[{"en":"I had difficulty opening the jar with wet hands.","vi":"Tôi gặp khó khăn khi mở chiếc hũ với đôi tay ướt.","audioKind":"ex"},{"en":"Students with limited internet access may have difficulty completing assignments that require extensive online research.","vi":"Học sinh có khả năng tiếp cận internet hạn chế có thể gặp khó khăn trong việc hoàn thành các bài tập đòi hỏi phải nghiên cứu trực tuyến nhiều.","audioKind":"ex2"}],"collocations":[{"en":"have difficulty doing something","vi":"gặp khó khăn khi làm việc gì"},{"en":"overcome difficulties","vi":"khắc phục khó khăn"},{"en":"financial difficulties","vi":"khó khăn tài chính"},{"en":"with difficulty","vi":"một cách chật vật"}],"wordFamily":["difficult (adj.)"],"synonyms":["trouble","problem"],"antonyms":["ease"],"tipVi":"Dùng have difficulty doing, không dùng difficulty to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bet', 'en-b1-60', 'bet', '/bet/', 'B1', 'đánh cược; cá cược; đoán chắc; dám cá; tiền cược; sự đánh cược', 'v.', 'betting (n.), bettor (n.)', 'Đồng nghĩa: wager', 'Dạng quá khứ và phân từ quá khứ thường vẫn giữ nguyên là bet; cụm I bet thường biểu thị sự chắc chắn.', 'I bet you left your keys in the kitchen.', NULL, 'Tôi cá là anh đã để quên chìa khóa trong bếp rồi.', '{"wordId":"bet","ukIpa":"/bet/","usIpa":"/bet/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to risk money on the result of an uncertain event","vi":"đánh cược; cá cược"},{"pos":"v.","en":"to say confidently that something is true or will happen","vi":"đoán chắc; dám cá"},{"pos":"n.","en":"an agreement to risk money on an uncertain result","vi":"tiền cược; sự đánh cược"}],"examples":[{"en":"I bet you left your keys in the kitchen.","vi":"Tôi cá là anh đã để quên chìa khóa trong bếp rồi.","audioKind":"ex"},{"en":"Some investors bet on emerging technologies despite considerable uncertainty about their future commercial success.","vi":"Một số nhà đầu tư vẫn mạo hiểm rót vốn vào các công nghệ mới nổi mặc dù vẫn có rất nhiều bất định về thành công thương mại trong tương lai của chúng.","audioKind":"ex2"}],"collocations":[{"en":"bet on","vi":"đặt cược vào"},{"en":"place a bet","vi":"đặt cược"},{"en":"I bet","vi":"tôi dám cá"},{"en":"a safe bet","vi":"một lựa chọn an toàn"}],"wordFamily":["betting (n.)","bettor (n.)"],"synonyms":["wager"],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ quá khứ thường vẫn giữ nguyên là bet; cụm I bet thường biểu thị sự chắc chắn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_respond', 'en-b1-60', 'respond', '/rɪˈspɑːnd/', 'B1', 'trả lời; hồi âm; phản ứng; đáp ứng', 'v.', 'response (n.), respondent (n.), responsive (adj.), responsiveness (n.)', 'Đồng nghĩa: reply, react', 'respond to đi sau nhận diện đối tượng phản hồi, không được trực tiếp đi với tân ngữ.', 'I asked about dinner, but nobody responded to my message.', NULL, 'Tôi hỏi về bữa tối nhưng không ai trả lời tin nhắn của tôi cả.', '{"wordId":"respond","ukIpa":"/rɪˈspɒnd/","usIpa":"/rɪˈspɑːnd/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To say or write something in reply.","vi":"trả lời; hồi âm"},{"pos":"v.","en":"To react to something through actions or physical changes.","vi":"phản ứng; đáp ứng"}],"examples":[{"en":"I asked about dinner, but nobody responded to my message.","vi":"Tôi hỏi về bữa tối nhưng không ai trả lời tin nhắn của tôi cả.","audioKind":"ex"},{"en":"Healthcare systems must respond quickly to changing population needs while maintaining high standards of care.","vi":"Hệ thống y tế phải nhanh chóng đáp ứng các nhu cầu thay đổi của dân số trong khi vẫn duy trì các tiêu chuẩn chăm sóc cao.","audioKind":"ex2"}],"collocations":[{"en":"respond to a question","vi":"trả lời câu hỏi"},{"en":"respond to treatment","vi":"đáp ứng điều trị"},{"en":"respond promptly","vi":"phản hồi kịp thời"},{"en":"respond positively","vi":"phản hồi tích cực"}],"wordFamily":["response (n.)","respondent (n.)","responsive (adj.)","responsiveness (n.)"],"synonyms":["reply","react"],"antonyms":[],"tipVi":"respond to đi sau nhận diện đối tượng phản hồi, không được trực tiếp đi với tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_contain', 'en-b1-60', 'contain', '/kənˈteɪn/', 'B1', 'chứa; bao gồm; kiểm soát; kìm chế', 'v.', 'container (n.), containment (n.)', 'Đồng nghĩa: hold', 'Là ngoại động từ, đi thẳng với tân ngữ; biểu thị nghĩa ''chứa'' thì thường không dùng thì tiếp diễn.', 'This small box contains all my sewing supplies.', NULL, 'Chiếc hộp nhỏ này chứa tất cả dụng cụ may vá của tôi.', '{"wordId":"contain","ukIpa":"/kənˈteɪn/","usIpa":"/kənˈteɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to have something inside or as a part","vi":"chứa; bao gồm"},{"pos":"v.","en":"to prevent something from spreading or becoming stronger","vi":"kiểm soát; kìm chế"}],"examples":[{"en":"This small box contains all my sewing supplies.","vi":"Chiếc hộp nhỏ này chứa tất cả dụng cụ may vá của tôi.","audioKind":"ex"},{"en":"Processed foods often contain large amounts of salt, which can contribute to serious health problems.","vi":"Thực phẩm chế biến sẵn thường chứa lượng lớn muối, có thể dẫn đến các vấn đề sức khỏe nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"contain ingredients","vi":"chứa thành phần"},{"en":"contain the spread","vi":"ngăn chặn sự lây lan"},{"en":"contain costs","vi":"kiểm soát chi phí"},{"en":"contain your excitement","vi":"kìm nén sự phấn khích"}],"wordFamily":["container (n.)","containment (n.)"],"synonyms":["hold"],"antonyms":[],"tipVi":"Là ngoại động từ, đi thẳng với tân ngữ; biểu thị nghĩa ''chứa'' thì thường không dùng thì tiếp diễn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_daylight', 'en-b1-60', 'daylight', '/ˈdeɪlaɪt/', 'B1', 'ánh sáng ban ngày; ban ngày', 'n.', NULL, 'Trái nghĩa: darkness', 'Thường là không đếm được; in broad daylight có nghĩa là giữa ban ngày ban mặt.', 'Let''s finish planting these flowers while there''s still daylight.', NULL, 'Hãy hoàn thành việc trồng mấy bông hoa này khi trời vẫn còn sáng.', '{"wordId":"daylight","ukIpa":"/ˈdeɪlaɪt/","usIpa":"/ˈdeɪlaɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Natural light from the sun, or the time it is available.","vi":"ánh sáng ban ngày; ban ngày"}],"examples":[{"en":"Let''s finish planting these flowers while there''s still daylight.","vi":"Hãy hoàn thành việc trồng mấy bông hoa này khi trời vẫn còn sáng.","audioKind":"ex"},{"en":"Designing classrooms to receive more daylight can reduce electricity use and create a more comfortable learning environment.","vi":"Thiết kế lớp học để đón nhiều ánh sáng tự nhiên hơn có thể giảm việc sử dụng điện và tạo môi trường học tập thoải mái hơn.","audioKind":"ex2"}],"collocations":[{"en":"in broad daylight","vi":"giữa ban ngày"},{"en":"daylight hours","vi":"giờ ban ngày"},{"en":"natural daylight","vi":"ánh sáng ban ngày tự nhiên"}],"wordFamily":[],"synonyms":[],"antonyms":["darkness"],"tipVi":"Thường là không đếm được; in broad daylight có nghĩa là giữa ban ngày ban mặt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_notepaper', 'en-b1-60', 'notepaper', '/ˈnoʊtpeɪpər/', 'B1', 'giấy viết thư; giấy viết nháp', 'n.', NULL, 'Đồng nghĩa: writing paper', 'Là danh từ không đếm được; một tờ giấy dùng a sheet of notepaper.', 'She took some notepaper from the desk drawer.', NULL, 'Cô ấy lấy một ít giấy viết thư từ ngăn kéo bàn làm việc.', '{"wordId":"notepaper","ukIpa":"/ˈnəʊtpeɪpə/","usIpa":"/ˈnoʊtpeɪpər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"paper used for writing letters or short messages","vi":"giấy viết thư; giấy viết nháp"}],"examples":[{"en":"She took some notepaper from the desk drawer.","vi":"Cô ấy lấy một ít giấy viết thư từ ngăn kéo bàn làm việc.","audioKind":"ex"},{"en":"Providing recycled notepaper in offices is a simple measure that can support more sustainable purchasing practices.","vi":"Cung cấp giấy viết tái chế tại văn phòng là một biện pháp đơn giản nhằm hỗ trợ các hoạt động mua sắm bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"a sheet of notepaper","vi":"một tờ giấy viết thư"},{"en":"a pad of notepaper","vi":"một tập giấy viết thư"},{"en":"personal notepaper","vi":"giấy viết thư cá nhân"}],"wordFamily":[],"synonyms":["writing paper"],"antonyms":[],"tipVi":"Là danh từ không đếm được; một tờ giấy dùng a sheet of notepaper.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_backwards', 'en-b1-60', 'backwards', '/ˈbækwərdz/', 'B1', 'về phía sau; quay lưng về phía trước; ngược chiều; ngược thứ tự', 'adv.', 'backward (adj.), back (adv.)', 'Đồng nghĩa: backward · Trái nghĩa: forwards', 'backwards là phó từ; bổ nghĩa cho danh từ thường dùng từ backward.', 'She stepped backwards to let the cyclist pass.', NULL, 'Cô ấy bước lùi lại để nhường đường cho người đi xe đạp.', '{"wordId":"backwards","ukIpa":"/ˈbækwədz/","usIpa":"/ˈbækwərdz/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"Towards the back, or with the back facing forwards.","vi":"về phía sau; quay lưng về phía trước"},{"pos":"adv.","en":"In the opposite order or direction to the usual one.","vi":"ngược chiều; ngược thứ tự"}],"examples":[{"en":"She stepped backwards to let the cyclist pass.","vi":"Cô ấy bước lùi lại để nhường đường cho người đi xe đạp.","audioKind":"ex"},{"en":"Researchers can work backwards from current pollution levels to identify the likely sources of environmental damage.","vi":"Các nhà nghiên cứu có thể truy ngược từ mức độ ô nhiễm hiện tại để xác định các nguyên nhân gây tổn hại môi trường.","audioKind":"ex2"}],"collocations":[{"en":"walk backwards","vi":"đi lùi"},{"en":"backwards and forwards","vi":"tiến lên và lùi lại"},{"en":"work backwards","vi":"phản hồi ngược"}],"wordFamily":["backward (adj.)","back (adv.)"],"synonyms":["backward"],"antonyms":["forwards"],"tipVi":"backwards là phó từ; bổ nghĩa cho danh từ thường dùng từ backward.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pale', 'en-b1-60', 'pale', '/peɪl/', 'B1', 'tái nhợt; nhạt màu; mờ nhạt; yếu ớt; trở nên nhợt nhạt; lu mờ đi', 'adj.', 'paleness (n.), paler (adj.), palest (adj.)', 'Đồng nghĩa: pallid, faint · Trái nghĩa: rosy', 'pale có thể chỉ sắc mặt tái nhợt hoặc màu sắc nhạt, không đồng nghĩa với màu trắng.', 'You look pale; sit down and have some water.', NULL, 'Trông bạn tái nhợt quá; hãy ngồi xuống và uống chút nước đi.', '{"wordId":"pale","ukIpa":"/peɪl/","usIpa":"/peɪl/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Having little colour, or less colour than usual.","vi":"tái nhợt; nhạt màu"},{"pos":"adj.","en":"Giving only a weak light.","vi":"mờ nhạt; yếu ớt"},{"pos":"v.","en":"To lose colour or seem less impressive in comparison.","vi":"trở nên nhợt nhạt; lu mờ đi"}],"examples":[{"en":"You look pale; sit down and have some water.","vi":"Trông bạn tái nhợt quá; hãy ngồi xuống và uống chút nước đi.","audioKind":"ex"},{"en":"The financial benefits of tourism may pale in comparison with its long-term environmental costs.","vi":"Lợi ích tài chính từ du lịch có thể trở nên lu mờ khi so sánh với chi phí môi trường lâu dài của nó.","audioKind":"ex2"}],"collocations":[{"en":"pale blue","vi":"màu xanh nhạt"},{"en":"look pale","vi":"trông tái nhợt"},{"en":"pale in comparison","vi":"lu mờ khi so sánh"}],"wordFamily":["paleness (n.)","paler (adj.)","palest (adj.)"],"synonyms":["pallid","faint"],"antonyms":["rosy"],"tipVi":"pale có thể chỉ sắc mặt tái nhợt hoặc màu sắc nhạt, không đồng nghĩa với màu trắng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tough', 'en-b1-60', 'tough', '/tʌf/', 'B1', 'khó khăn; gai góc; nan giải; kiên cường; chịu khó; bền bỉ; dai; khó vỡ; khó cắt; bền chắc', 'adj.', 'toughness (n.), toughen (v.)', 'Đồng nghĩa: difficult, resilient, durable · Trái nghĩa: easy, fragile', 'Phát âm vần với rough; khi dùng cho thịt có nghĩa là dai, khó nhai.', 'It was a tough climb, but the view was worth it.', NULL, 'Đó là một chuyến leo núi khó khăn, nhưng phong cảnh thực sự đáng giá.', '{"wordId":"tough","ukIpa":"/tʌf/","usIpa":"/tʌf/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Difficult to do, deal with, or endure","vi":"khó khăn; gai góc; nan giải"},{"pos":"adj.","en":"Able to cope with hardship, pain, or difficult conditions","vi":"kiên cường; chịu khó; bền bỉ"},{"pos":"adj.","en":"Strong and difficult to break, cut, or damage","vi":"dai; khó vỡ; khó cắt; bền chắc"}],"examples":[{"en":"It was a tough climb, but the view was worth it.","vi":"Đó là một chuyến leo núi khó khăn, nhưng phong cảnh thực sự đáng giá.","audioKind":"ex"},{"en":"Governments face tough choices when balancing economic growth with the need to protect natural resources.","vi":"Các chính phủ phải đối mặt với những lựa chọn khó khăn khi cân bằng giữa tăng trưởng kinh tế và nhu cầu bảo vệ tài nguyên thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"tough decision","vi":"quyết định khó khăn"},{"en":"tough times","vi":"thời kỳ khó khăn"},{"en":"tough competition","vi":"cạnh tranh khốc liệt"},{"en":"tough material","vi":"chất liệu bền chắc"}],"wordFamily":["toughness (n.)","toughen (v.)"],"synonyms":["difficult","resilient","durable"],"antonyms":["easy","fragile"],"tipVi":"Phát âm vần với rough; khi dùng cho thịt có nghĩa là dai, khó nhai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slightly', 'en-b1-60', 'slightly', '/ˈslaɪtli/', 'B1', 'hơi; một chút; nhẹ', 'adv.', 'slight (adj.)', 'Đồng nghĩa: a little, somewhat · Trái nghĩa: considerably', 'Có thể bổ nghĩa cho tính từ, so sánh hơn hoặc động từ, ví dụ như slightly higher.', 'Please open the window slightly; it feels warm.', NULL, 'Làm ơn mở hé cửa sổ một chút; trời hơi nóng.', '{"wordId":"slightly","ukIpa":"/ˈslaɪtli/","usIpa":"/ˈslaɪtli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"by a small amount or to a small degree","vi":"hơi; một chút; nhẹ"}],"examples":[{"en":"Please open the window slightly; it feels warm.","vi":"Làm ơn mở hé cửa sổ một chút; trời hơi nóng.","audioKind":"ex"},{"en":"Although average incomes rose slightly, many households continued to struggle with higher food and energy costs.","vi":"Mặc dù thu nhập trung bình tăng nhẹ, nhiều hộ gia đình vẫn tiếp tục chật vật với chi phí thực phẩm và năng lượng tăng cao.","audioKind":"ex2"}],"collocations":[{"en":"slightly higher","vi":"cao hơn một chút"},{"en":"slightly different","vi":"khác biệt chút ít"},{"en":"slightly more","vi":"nhiều hơn một chút"}],"wordFamily":["slight (adj.)"],"synonyms":["a little","somewhat"],"antonyms":["considerably"],"tipVi":"Có thể bổ nghĩa cho tính từ, so sánh hơn hoặc động từ, ví dụ như slightly higher.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_addition', 'en-b1-60', 'addition', '/əˈdɪʃən/', 'B1', 'sự thêm vào; sự gia tăng; phép cộng; vật bổ sung; người mới gia nhập', 'n.', 'add (v.), additional (adj.), additionally (adv.)', 'Trái nghĩa: subtraction', 'in addition dùng làm từ nối; in addition to đi với danh từ hoặc danh động từ.', 'The addition of fresh lemon made the soup delicious.', NULL, 'Việc cho thêm chanh tươi vào khiến món súp trở nên rất ngon.', '{"wordId":"addition","ukIpa":"/əˈdɪʃən/","usIpa":"/əˈdɪʃən/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"the act of putting something extra into something","vi":"sự thêm vào; sự gia tăng"},{"pos":"n.","en":"the process of finding the total of quantities","vi":"phép cộng"},{"pos":"n.","en":"something extra that joins an existing group or collection","vi":"vật bổ sung; người mới gia nhập"}],"examples":[{"en":"The addition of fresh lemon made the soup delicious.","vi":"Việc cho thêm chanh tươi vào khiến món súp trở nên rất ngon.","audioKind":"ex"},{"en":"The addition of cycle lanes can make urban transport safer and encourage residents to exercise regularly.","vi":"Việc bổ sung các làn đường dành cho xe đạp có thể làm cho giao thông đô thị an toàn hơn và khuyến khích người dân tập thể dục thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"in addition to","vi":"ngoài ra; bên cạnh"},{"en":"the addition of","vi":"sự thêm vào của"},{"en":"a welcome addition","vi":"một sự bổ sung đáng hoan nghênh"},{"en":"simple addition","vi":"phép cộng đơn giản"}],"wordFamily":["add (v.)","additional (adj.)","additionally (adv.)"],"synonyms":[],"antonyms":["subtraction"],"tipVi":"in addition dùng làm từ nối; in addition to đi với danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dusty', 'en-b1-60', 'dusty', '/ˈdʌsti/', 'B1', 'bám đầy bụi; đầy bụi', 'adj.', 'dust (n.), dust (v.), dustiness (n.)', NULL, 'dusty dùng để tả có bụi; dust làm động từ có nghĩa là phủi bụi.', 'I wiped the dusty shelf with a damp cloth.', NULL, 'Tôi lau cái kệ bám đầy bụi bằng một chiếc khăn ẩm.', '{"wordId":"dusty","ukIpa":"/ˈdʌsti/","usIpa":"/ˈdʌsti/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Covered with dust or containing a lot of dust.","vi":"bám đầy bụi; đầy bụi"}],"examples":[{"en":"I wiped the dusty shelf with a damp cloth.","vi":"Tôi lau cái kệ bám đầy bụi bằng một chiếc khăn ẩm.","audioKind":"ex"},{"en":"Workers in dusty environments need appropriate protective equipment to reduce their risk of developing respiratory diseases.","vi":"Công nhân làm việc trong môi trường nhiều bụi cần có thiết bị bảo hộ thích hợp để giảm nguy cơ mắc các bệnh về đường hô hấp.","audioKind":"ex2"}],"collocations":[{"en":"a dusty road","vi":"con đường bụi mù mịt"},{"en":"dusty shelves","vi":"những chiếc kệ bám bụi"},{"en":"a dusty environment","vi":"môi trường nhiều bụi"}],"wordFamily":["dust (n.)","dust (v.)","dustiness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"dusty dùng để tả có bụi; dust làm động từ có nghĩa là phủi bụi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frozen', 'en-b1-60', 'frozen', '/ˈfroʊzən/', 'B1', 'đóng băng; bị đông cứng; được đông lạnh; tê cóng; lạnh cóng', 'adj.', 'freeze (v.), freezing (adj.), freezer (n.)', 'Đồng nghĩa: icy · Trái nghĩa: thawed', 'Đây cũng là phân từ hai của freeze; dạng quá khứ là froze.', 'A frozen puddle cracked beneath my boot this morning.', NULL, 'Một vũng nước đóng băng đã nứt vỡ dưới đôi bốt của tôi sáng nay.', '{"wordId":"frozen","ukIpa":"/ˈfrəʊzən/","usIpa":"/ˈfroʊzən/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Turned into ice or made hard by extreme cold.","vi":"đóng băng; bị đông cứng"},{"pos":"adj.","en":"Kept at very low temperatures to preserve freshness.","vi":"được đông lạnh"},{"pos":"adj.","en":"Feeling extremely cold.","vi":"tê cóng; lạnh cóng"}],"examples":[{"en":"A frozen puddle cracked beneath my boot this morning.","vi":"Một vũng nước đóng băng đã nứt vỡ dưới đôi bốt của tôi sáng nay.","audioKind":"ex"},{"en":"Frozen vegetables can help households reduce food waste because they remain usable much longer than fresh produce.","vi":"Rau củ đông lạnh có thể giúp các hộ gia đình giảm thiểu lãng phí thực phẩm vì chúng giữ được độ tươi lâu hơn nhiều so với rau củ tươi.","audioKind":"ex2"}],"collocations":[{"en":"frozen lake","vi":"hồ đóng băng"},{"en":"frozen food","vi":"thực phẩm đông lạnh"},{"en":"frozen solid","vi":"đông cứng ngắc"},{"en":"frozen with fear","vi":"cứng đờ vì sợ"}],"wordFamily":["freeze (v.)","freezing (adj.)","freezer (n.)"],"synonyms":["icy"],"antonyms":["thawed"],"tipVi":"Đây cũng là phân từ hai của freeze; dạng quá khứ là froze.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_occur', 'en-b1-60', 'occur', '/əˈkɝː/', 'B1', 'xảy ra; diễn ra; tồn tại; xuất hiện; nảy ra; lóe lên trong đầu', 'v.', 'occurrence (n.)', 'Đồng nghĩa: happen, take place', 'Không dùng ở thể bị động; dạng quá khứ là occurred, phân từ là occurring.', 'Power cuts often occur here during heavy winter storms.', NULL, 'Mất điện thường xảy ra ở đây trong các trận bão mùa đông lớn.', '{"wordId":"occur","ukIpa":"/əˈkɜː/","usIpa":"/əˈkɝː/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Happen, especially at a particular time or place.","vi":"xảy ra; diễn ra"},{"pos":"v.","en":"Exist or be found in a particular place or situation.","vi":"tồn tại; xuất hiện"},{"pos":"v.","en":"Come into someone''s mind as an idea or thought.","vi":"nảy ra; lóe lên trong đầu"}],"examples":[{"en":"Power cuts often occur here during heavy winter storms.","vi":"Mất điện thường xảy ra ở đây trong các trận bão mùa đông lớn.","audioKind":"ex"},{"en":"Traffic accidents are more likely to occur when drivers are tired or distracted by mobile phones.","vi":"Tai nạn giao thông có xu hướng xảy ra cao hơn khi tài xế mệt mỏi hoặc bị điện thoại làm phân tâm.","audioKind":"ex2"}],"collocations":[{"en":"occur naturally","vi":"xuất hiện tự nhiên"},{"en":"occur frequently","vi":"xảy ra thường xuyên"},{"en":"occur to someone","vi":"nảy ra trong đầu ai đó"}],"wordFamily":["occurrence (n.)"],"synonyms":["happen","take place"],"antonyms":[],"tipVi":"Không dùng ở thể bị động; dạng quá khứ là occurred, phân từ là occurring.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eyebrow', 'en-b1-60', 'eyebrow', '/ˈaɪbraʊ/', 'B1', 'lông mày', 'n.', 'brow (n.)', 'Đồng nghĩa: brow', 'eyebrow là lông mày; eyelash là lông mi.', 'He raised one eyebrow when he saw the enormous cake.', NULL, 'Anh ấy nhướng một bên lông mày khi nhìn thấy chiếc bánh khổng lồ.', '{"wordId":"eyebrow","ukIpa":"/ˈaɪbraʊ/","usIpa":"/ˈaɪbraʊ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The curved line of hair above each eye.","vi":"lông mày"}],"examples":[{"en":"He raised one eyebrow when he saw the enormous cake.","vi":"Anh ấy nhướng một bên lông mày khi nhìn thấy chiếc bánh khổng lồ.","audioKind":"ex"},{"en":"Facial movements, such as raising an eyebrow, can communicate surprise without relying on spoken language.","vi":"Các chuyển động trên khuôn mặt, chẳng hạn như nhướng mày, có thể truyền đạt sự ngạc nhiên mà không cần dựa vào ngôn ngữ nói.","audioKind":"ex2"}],"collocations":[{"en":"raise an eyebrow","vi":"nhướng mày; biểu lộ sự ngạc nhiên"},{"en":"thick eyebrows","vi":"lông mày rậm"},{"en":"arched eyebrows","vi":"lông mày cong"}],"wordFamily":["brow (n.)"],"synonyms":["brow"],"antonyms":[],"tipVi":"eyebrow là lông mày; eyelash là lông mi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_divide', 'en-b1-60', 'divide', '/dɪˈvaɪd/', 'B1', 'chia; phân chia; tách ra; chia cho; sự chia rẽ; khoảng cách; hố ngăn cách', 'v.', 'division (n.), divided (adj.), divisible (adj.), divisive (adj.)', 'Đồng nghĩa: separate, split · Trái nghĩa: unite, combine', 'divide into chỉ sự chia thành; divide by chỉ phép chia cho.', 'Let''s divide the cake into slices before everyone arrives.', NULL, 'Hãy cắt chiếc bánh thành từng lát trước khi mọi người đến nhé.', '{"wordId":"divide","ukIpa":"/dɪˈvaɪd/","usIpa":"/dɪˈvaɪd/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to separate something into parts or share it among people","vi":"chia; phân chia; tách ra"},{"pos":"v.","en":"to calculate how many times one quantity fits into another","vi":"chia cho"},{"pos":"n.","en":"a major difference separating people or groups","vi":"sự chia rẽ; khoảng cách; hố ngăn cách"}],"examples":[{"en":"Let''s divide the cake into slices before everyone arrives.","vi":"Hãy cắt chiếc bánh thành từng lát trước khi mọi người đến nhé.","audioKind":"ex"},{"en":"Unequal access to reliable internet services can deepen the digital divide between urban and rural communities.","vi":"Sự tiếp cận không đồng đều với các dịch vụ internet ổn định có thể làm sâu sắc thêm khoảng cách số giữa các cộng đồng thành thị và nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"divide into groups","vi":"chia thành các nhóm"},{"en":"divide equally","vi":"chia đều"},{"en":"divide by","vi":"chia cho"},{"en":"the digital divide","vi":"khoảng cách số"}],"wordFamily":["division (n.)","divided (adj.)","divisible (adj.)","divisive (adj.)"],"synonyms":["separate","split"],"antonyms":["unite","combine"],"tipVi":"divide into chỉ sự chia thành; divide by chỉ phép chia cho.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_upper', 'en-b1-60', 'upper', '/ˈʌpər/', 'B1', 'phía trên; trên cao; cao hơn; cấp trên', 'adj.', NULL, 'Trái nghĩa: lower', 'Thường đứng trước danh từ, như upper floor; từ trái nghĩa là lower.', 'Keep the spare blankets on the upper shelf.', NULL, 'Hãy cất những chiếc chăn dự phòng ở chiếc kệ phía trên.', '{"wordId":"upper","ukIpa":"/ˈʌpə/","usIpa":"/ˈʌpər/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Located above another part or nearer the top.","vi":"phía trên; trên cao"},{"pos":"adj.","en":"Higher in rank, level, or position within a range.","vi":"cao hơn; cấp trên"}],"examples":[{"en":"Keep the spare blankets on the upper shelf.","vi":"Hãy cất những chiếc chăn dự phòng ở chiếc kệ phía trên.","audioKind":"ex"},{"en":"Residents on the upper floors of apartment buildings may face difficulties when lifts stop working.","vi":"Cư dân ở các tầng trên của các tòa nhà chung cư có thể gặp khó khăn khi thang máy ngừng hoạt động.","audioKind":"ex2"}],"collocations":[{"en":"upper floor","vi":"tầng trên"},{"en":"upper body","vi":"nửa thân trên"},{"en":"upper limit","vi":"giới hạn trên"},{"en":"upper class","vi":"tầng lớp thượng lưu"}],"wordFamily":[],"synonyms":[],"antonyms":["lower"],"tipVi":"Thường đứng trước danh từ, như upper floor; từ trái nghĩa là lower.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_worth', 'en-b1-60', 'worth', '/wɝːθ/', 'B1', 'đáng giá (tiền bạc); xứng đáng (thời gian, công sức); giá trị; tầm quan trọng', 'adj.', 'worthless (adj.), worthy (adj.)', NULL, 'Diễn đạt sự đáng làm gì dùng be worth doing, không dùng worth to do.', 'This old bicycle is still worth fifty pounds.', NULL, 'Chiếc xe đạp cũ này vẫn đáng giá năm mươi bảng.', '{"wordId":"worth","ukIpa":"/wɜːθ/","usIpa":"/wɝːθ/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Having a particular value in money.","vi":"đáng giá (tiền bạc)"},{"pos":"adj.","en":"Deserving the time, effort, or money something requires.","vi":"xứng đáng (thời gian, công sức)"},{"pos":"n.","en":"The value, importance, or usefulness of something.","vi":"giá trị; tầm quan trọng"}],"examples":[{"en":"This old bicycle is still worth fifty pounds.","vi":"Chiếc xe đạp cũ này vẫn đáng giá năm mươi bảng.","audioKind":"ex"},{"en":"Investing in public transport is worth the initial expense because it can reduce congestion and pollution.","vi":"Đầu tư vào giao thông công cộng rất đáng với chi phí ban đầu vì nó có thể làm giảm tắc nghẽn và ô nhiễm.","audioKind":"ex2"}],"collocations":[{"en":"be worth doing","vi":"đáng làm gì"},{"en":"be worth the effort","vi":"xứng đáng với công sức"},{"en":"prove your worth","vi":"chứng minh giá trị bản thân"}],"wordFamily":["worthless (adj.)","worthy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Diễn đạt sự đáng làm gì dùng be worth doing, không dùng worth to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_collar', 'en-b1-60', 'collar', '/ˈkɑːlər/', 'B1', 'cổ áo; vòng cổ (động vật); tóm lấy; chặn lại', 'n.', 'collared (adj.), collarless (adj.)', NULL, 'white-collar chỉ nhân viên văn phòng; blue-collar chỉ công nhân lao động chân tay.', 'He straightened his shirt collar before the interview.', NULL, 'Anh ấy chỉnh lại cổ áo sơ mi trước buổi phỏng vấn.', '{"wordId":"collar","ukIpa":"/ˈkɒlə/","usIpa":"/ˈkɑːlər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The part of a garment that surrounds the neck.","vi":"cổ áo"},{"pos":"n.","en":"A band worn around an animal''s neck.","vi":"vòng cổ (động vật)"},{"pos":"v.","en":"To catch or stop someone, often to speak to them.","vi":"tóm lấy; chặn lại"}],"examples":[{"en":"He straightened his shirt collar before the interview.","vi":"Anh ấy chỉnh lại cổ áo sơ mi trước buổi phỏng vấn.","audioKind":"ex"},{"en":"A well-fitted collar allows owners to attach a lead and keep dogs under control in public spaces.","vi":"Một chiếc vòng cổ vừa vặn giúp chủ nuôi dễ dàng gắn dây dắt và kiểm soát chó ở nơi công cộng.","audioKind":"ex2"}],"collocations":[{"en":"shirt collar","vi":"cổ áo sơ mi"},{"en":"dog collar","vi":"vòng cổ chó"},{"en":"a stiff collar","vi":"cổ áo cứng"},{"en":"turn up your collar","vi":"dựng cổ áo lên"}],"wordFamily":["collared (adj.)","collarless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"white-collar chỉ nhân viên văn phòng; blue-collar chỉ công nhân lao động chân tay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fold', 'en-b1-60', 'fold', '/foʊld/', 'B1', 'gấp; xếp; nếp gấp; nếp nhăn; đóng cửa; phá sản', 'v.', 'unfold (v.), folding (adj.)', 'Trái nghĩa: unfold', 'fold nhấn mạnh hành động gấp lại; bend chỉ biểu thị sự uốn cong chứ không nhất thiết phải chồng khít lên nhau.', 'Please fold these towels and put them on the shelf.', NULL, 'Hãy gấp những chiếc khăn này lại và cất lên kệ.', '{"wordId":"fold","ukIpa":"/fəʊld/","usIpa":"/foʊld/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to bend something so one part lies over another","vi":"gấp; xếp"},{"pos":"n.","en":"a bend or crease in paper, cloth, or skin","vi":"nếp gấp; nếp nhăn"},{"pos":"v.","en":"to close because a business cannot continue operating","vi":"đóng cửa; phá sản"}],"examples":[{"en":"Please fold these towels and put them on the shelf.","vi":"Hãy gấp những chiếc khăn này lại và cất lên kệ.","audioKind":"ex"},{"en":"Small businesses may fold when rising rental costs make it impossible to maintain a reasonable profit.","vi":"Các doanh nghiệp nhỏ có thể phải đóng cửa khi chi phí thuê mặt bằng tăng cao khiến họ không thể duy trì mức lợi nhuận hợp lý.","audioKind":"ex2"}],"collocations":[{"en":"fold in half","vi":"gấp đôi"},{"en":"fold your arms","vi":"khoanh tay trước ngực"},{"en":"fold up a chair","vi":"gấp ghế lại"},{"en":"fold the laundry","vi":"gấp quần áo"}],"wordFamily":["unfold (v.)","folding (adj.)"],"synonyms":[],"antonyms":["unfold"],"tipVi":"fold nhấn mạnh hành động gấp lại; bend chỉ biểu thị sự uốn cong chứ không nhất thiết phải chồng khít lên nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reliable', 'en-b1-60', 'reliable', '/rɪˈlaɪəbl/', 'B1', 'đáng tin cậy', 'adj.', 'rely (v.), reliability (n.), reliably (adv.), unreliable (adj.)', 'Đồng nghĩa: dependable, trustworthy · Trái nghĩa: unreliable', 'reliable có thể dùng để mô tả con người, thông tin hoặc máy móc, nhấn mạnh sự đáng tin cậy.', 'Our old car is still reliable in cold weather.', NULL, 'Chiếc ô tô cũ của chúng tôi vẫn rất đáng tin cậy trong thời tiết lạnh giá.', '{"wordId":"reliable","ukIpa":"/rɪˈlaɪəbl/","usIpa":"/rɪˈlaɪəbl/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Able to be trusted to work well or behave consistently","vi":"đáng tin cậy"}],"examples":[{"en":"Our old car is still reliable in cold weather.","vi":"Chiếc ô tô cũ của chúng tôi vẫn rất đáng tin cậy trong thời tiết lạnh giá.","audioKind":"ex"},{"en":"Access to reliable information helps citizens make informed decisions about their health and finances.","vi":"Việc tiếp cận thông tin đáng tin cậy giúp công dân đưa ra những quyết định sáng suốt về sức khỏe và tài chính của họ.","audioKind":"ex2"}],"collocations":[{"en":"reliable source","vi":"nguồn tin cậy"},{"en":"reliable information","vi":"thông tin đáng tin cậy"},{"en":"reliable service","vi":"dịch vụ đáng tin cậy"}],"wordFamily":["rely (v.)","reliability (n.)","reliably (adv.)","unreliable (adj.)"],"synonyms":["dependable","trustworthy"],"antonyms":["unreliable"],"tipVi":"reliable có thể dùng để mô tả con người, thông tin hoặc máy móc, nhấn mạnh sự đáng tin cậy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skip', 'en-b1-60', 'skip', '/skɪp/', 'B1', 'bỏ qua; lướt qua; trốn; nhảy cẫng lên; nhảy dây', 'v.', 'skipping (n.)', 'Đồng nghĩa: omit, miss', 'skip đi liền sau với tân ngữ trực tiếp; các dạng skipped và skipping phải gấp đôi chữ cái p.', 'I skipped breakfast because I woke up too late.', NULL, 'Tôi bỏ bữa sáng vì dậy quá muộn.', '{"wordId":"skip","ukIpa":"/skɪp/","usIpa":"/skɪp/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To leave something out or not do something expected.","vi":"bỏ qua; lướt qua; trốn"},{"pos":"v.","en":"To move with light hops or jump over a swinging rope.","vi":"nhảy cẫng lên; nhảy dây"}],"examples":[{"en":"I skipped breakfast because I woke up too late.","vi":"Tôi bỏ bữa sáng vì dậy quá muộn.","audioKind":"ex"},{"en":"Students who regularly skip classes may struggle to develop the knowledge required for more advanced courses.","vi":"Những học sinh thường xuyên trốn học có thể gặp khó khăn trong việc tiếp thu kiến thức cần thiết cho các khóa học nâng cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"skip breakfast","vi":"bỏ bữa sáng"},{"en":"skip a class","vi":"trốn một tiết học"},{"en":"skip a step","vi":"bỏ qua một bước"},{"en":"skip rope","vi":"nhảy dây"}],"wordFamily":["skipping (n.)"],"synonyms":["omit","miss"],"antonyms":[],"tipVi":"skip đi liền sau với tân ngữ trực tiếp; các dạng skipped và skipping phải gấp đôi chữ cái p.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_60_1', 'en-b1-60', 'Cách dùng “fold” (v.) — gấp; xếp', 'fold in half  ·  fold your arms  ·  fold up a chair', 'fold nhấn mạnh hành động gấp lại; bend chỉ biểu thị sự uốn cong chứ không nhất thiết phải chồng khít lên nhau.', 'Họ từ (Word Family): unfold (v.), folding (adj.) | Trái nghĩa: unfold', '[{"hanzi":"Please fold these towels and put them on the shelf.","pinyin":"","meaning":"Hãy gấp những chiếc khăn này lại và cất lên kệ."},{"hanzi":"Small businesses may fold when rising rental costs make it impossible to maintain a reasonable profit.","pinyin":"","meaning":"Các doanh nghiệp nhỏ có thể phải đóng cửa khi chi phí thuê mặt bằng tăng cao khiến họ không thể duy trì mức lợi nhuận hợp lý."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_60_2', 'en-b1-60', 'Cách dùng “bet” (v.) — đánh cược; cá cược', 'bet on  ·  place a bet  ·  I bet', 'Dạng quá khứ và phân từ quá khứ thường vẫn giữ nguyên là bet; cụm I bet thường biểu thị sự chắc chắn.', 'Họ từ (Word Family): betting (n.), bettor (n.) | Đồng nghĩa: wager', '[{"hanzi":"I bet you left your keys in the kitchen.","pinyin":"","meaning":"Tôi cá là anh đã để quên chìa khóa trong bếp rồi."},{"hanzi":"Some investors bet on emerging technologies despite considerable uncertainty about their future commercial success.","pinyin":"","meaning":"Một số nhà đầu tư vẫn mạo hiểm rót vốn vào các công nghệ mới nổi mặc dù vẫn có rất nhiều bất định về thành công thương mại trong tương lai của chúng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_60_3', 'en-b1-60', 'Cách dùng “chilly” (adj.) — lạnh buốt; se lạnh', 'a chilly morning  ·  feel chilly  ·  a chilly reception', 'Chilly có mức độ lạnh nhẹ hơn freezing, đồng thời có thể dùng để mô tả thái độ lạnh lùng, xa cách.', 'Họ từ (Word Family): chill (n.), chill (v.), chilliness (n.) | Đồng nghĩa: cold, cool · Trái nghĩa: warm', '[{"hanzi":"It felt chilly outside, so I grabbed my jacket.","pinyin":"","meaning":"Bên ngoài trời se lạnh nên tôi đã lấy áo khoác mặc vào."},{"hanzi":"Providing warm public spaces during chilly weather can help protect older residents from cold-related illnesses.","pinyin":"","meaning":"Việc cung cấp không gian công cộng ấm áp trong thời tiết se lạnh có thể giúp bảo vệ cư dân lớn tuổi khỏi các bệnh do lạnh."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_60_4', 'en-b1-60', 'Cách dùng “contain” (v.) — chứa; bao gồm', 'contain ingredients  ·  contain the spread  ·  contain costs', 'Là ngoại động từ, đi thẳng với tân ngữ; biểu thị nghĩa ''chứa'' thì thường không dùng thì tiếp diễn.', 'Họ từ (Word Family): container (n.), containment (n.) | Đồng nghĩa: hold', '[{"hanzi":"This small box contains all my sewing supplies.","pinyin":"","meaning":"Chiếc hộp nhỏ này chứa tất cả dụng cụ may vá của tôi."},{"hanzi":"Processed foods often contain large amounts of salt, which can contribute to serious health problems.","pinyin":"","meaning":"Thực phẩm chế biến sẵn thường chứa lượng lớn muối, có thể dẫn đến các vấn đề sức khỏe nghiêm trọng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_60_1', 'en-b1-60', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
