INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_60_1_2', 'ten_b1_60_1', 'peaceful', 'The lake looks peaceful in the early morning light.', 'The lake looks peaceful in the early morning light.', '/ˈpiːsfəl/', 'Hồ nước trông thật yên bình trong ánh sáng sớm mai.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_60_1_3', 'ten_b1_60_1', 'teacup', 'She placed a delicate teacup beside the biscuit plate.', 'She placed a delicate teacup beside the biscuit plate.', '/ˈtiːkʌp/', 'Cô ấy đặt một chiếc tách trà tinh xảo bên cạnh đĩa bánh quy.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_60_1_4', 'ten_b1_60_1', 'rarely', 'We rarely eat outside when the weather turns cold.', 'We rarely eat outside when the weather turns cold.', '/ˈrerli/', 'Chúng tôi hiếm khi ăn ngoài khi trời trở lạnh.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_60_1_5', 'ten_b1_60_1', 'hardly', 'I could hardly hear you over the heavy rain.', 'I could hardly hear you over the heavy rain.', '/ˈhɑːrdli/', 'Tôi hầu như không nghe thấy bạn nói gì vì tiếng mưa rơi quá lớn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_60_1_6', 'ten_b1_60_1', 'difficulty', 'I had difficulty opening the jar with wet hands.', 'I had difficulty opening the jar with wet hands.', '/ˈdɪfɪkəlti/', 'Tôi gặp khó khăn khi mở chiếc hũ với đôi tay ướt.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_60_1_7', 'ten_b1_60_1', 'bet', 'I bet you left your keys in the kitchen.', 'I bet you left your keys in the kitchen.', '/bet/', 'Tôi cá là anh đã để quên chìa khóa trong bếp rồi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_60_1_8', 'ten_b1_60_1', 'respond', 'I asked about dinner, but nobody responded to my message.', 'I asked about dinner, but nobody responded to my message.', '/rɪˈspɑːnd/', 'Tôi hỏi về bữa tối nhưng không ai trả lời tin nhắn của tôi cả.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_60_1_1', 'en-b1-60', 'ten_b1_60_1', 'listening', 'listening', 'It felt chilly outside, so I grabbed my jacket.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bên ngoài trời se lạnh nên tôi đã lấy áo khoác mặc vào.","Chiếc xe đạp cũ này vẫn đáng giá năm mươi bảng.","Đó là một chuyến leo núi khó khăn, nhưng phong cảnh thực sự đáng giá.","Anh ấy nhướng một bên lông mày khi nhìn thấy chiếc bánh khổng lồ."]'::jsonb, 0, 'It felt chilly outside, so I grabbed my jacket. → Bên ngoài trời se lạnh nên tôi đã lấy áo khoác mặc vào.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_60_1_2', 'en-b1-60', 'ten_b1_60_1', 'listening', 'listening', 'The lake looks peaceful in the early morning light.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy lấy một ít giấy viết thư từ ngăn kéo bàn làm việc.","Hồ nước trông thật yên bình trong ánh sáng sớm mai.","Tôi gặp khó khăn khi mở chiếc hũ với đôi tay ướt.","Việc cho thêm chanh tươi vào khiến món súp trở nên rất ngon."]'::jsonb, 1, 'The lake looks peaceful in the early morning light. → Hồ nước trông thật yên bình trong ánh sáng sớm mai.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_60_1_3', 'en-b1-60', 'ten_b1_60_1', 'listening', 'listening', 'She placed a delicate teacup beside the biscuit plate.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hãy cất những chiếc chăn dự phòng ở chiếc kệ phía trên.","Cô ấy đặt một chiếc tách trà tinh xảo bên cạnh đĩa bánh quy.","Tôi hỏi về bữa tối nhưng không ai trả lời tin nhắn của tôi cả.","Chiếc ô tô cũ của chúng tôi vẫn rất đáng tin cậy trong thời tiết lạnh giá."]'::jsonb, 1, 'She placed a delicate teacup beside the biscuit plate. → Cô ấy đặt một chiếc tách trà tinh xảo bên cạnh đĩa bánh quy.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_60_2', 'en-b1-60', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_60_2_1', 'ten_b1_60_2', 'chilly', 'Providing warm public spaces during chilly weather can help protect older residents from cold-related illnesses.', 'Providing warm public spaces during chilly weather can help protect older residents from cold-related illnesses.', '/ˈtʃɪli/', 'Việc cung cấp không gian công cộng ấm áp trong thời tiết se lạnh có thể giúp bảo vệ cư dân lớn tuổi khỏi các bệnh do lạnh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_60_2_2', 'ten_b1_60_2', 'peaceful', 'Creating peaceful public spaces can improve residents'' wellbeing and encourage more people to spend time outdoors.', 'Creating peaceful public spaces can improve residents'' wellbeing and encourage more people to spend time outdoors.', '/ˈpiːsfəl/', 'Việc tạo ra các không gian công cộng yên bình có thể nâng cao phúc lợi của cư dân và khuyến khích nhiều người ra ngoài trời hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_60_2_3', 'ten_b1_60_2', 'teacup', 'A museum display of decorated teacups can reveal how domestic tastes and manufacturing techniques changed over time.', 'A museum display of decorated teacups can reveal how domestic tastes and manufacturing techniques changed over time.', '/ˈtiːkʌp/', 'Triển lãm bảo tàng về những chiếc tách trà trang trí có thể cho thấy gu thẩm mỹ gia đình và kỹ thuật sản xuất đã thay đổi theo thời gian như thế nào.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_60_2_4', 'ten_b1_60_2', 'rarely', 'People living in remote villages rarely have easy access to specialist medical services.', 'People living in remote villages rarely have easy access to specialist medical services.', '/ˈrerli/', 'Những người sống ở các ngôi làng hẻo lánh hiếm khi có cơ hội tiếp cận dễ dàng với các dịch vụ y tế chuyên khoa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_60_2_5', 'ten_b1_60_2', 'hardly', 'Expanding roads alone is hardly sufficient to solve traffic congestion without improvements to public transport.', 'Expanding roads alone is hardly sufficient to solve traffic congestion without improvements to public transport.', '/ˈhɑːrdli/', 'Chỉ mở rộng đường sá thôi thì hầu như không đủ để giải quyết tình trạng tắc nghẽn giao thông nếu không cải thiện giao thông công cộng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_60_2_6', 'ten_b1_60_2', 'difficulty', 'Students with limited internet access may have difficulty completing assignments that require extensive online research.', 'Students with limited internet access may have difficulty completing assignments that require extensive online research.', '/ˈdɪfɪkəlti/', 'Học sinh có khả năng tiếp cận internet hạn chế có thể gặp khó khăn trong việc hoàn thành các bài tập đòi hỏi phải nghiên cứu trực tuyến nhiều.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_60_2_1', 'en-b1-60', 'ten_b1_60_2', 'listening', 'listening', 'Providing warm public spaces during chilly weather can help protect older residents from cold-related illnesses.', NULL, 'Trong câu vừa nghe, từ “chilly” mang nghĩa nào sau đây?', '["quảng cáo","sự giao tiếp; sự trao đổi; sự liên lạc","gây ấn tượng sâu sắc; hùng vĩ; xuất sắc; đáng nể","lạnh buốt; se lạnh"]'::jsonb, 3, '“chilly” (/ˈtʃɪli/): lạnh buốt; se lạnh. Câu đầy đủ: Providing warm public spaces during chilly weather can help protect older residents from cold-related illnesses.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_60_2_2', 'en-b1-60', 'ten_b1_60_2', 'listening', 'listening', 'Creating peaceful public spaces can improve residents'' wellbeing and encourage more people to spend time outdoors.', NULL, 'Trong câu vừa nghe, từ “peaceful” mang nghĩa nào sau đây?', '["cối xay gió","niềm tin; sự tin tưởng","yên bình; thanh bình; tĩnh lặng","dải ruy băng; dải băng"]'::jsonb, 2, '“peaceful” (/ˈpiːsfəl/): yên bình; thanh bình; tĩnh lặng. Câu đầy đủ: Creating peaceful public spaces can improve residents'' wellbeing and encourage more people to spend time outdoors.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_60_1', 'en-b1-60', 'It felt chilly outside, so I grabbed my jacket', 'Bên ngoài trời se lạnh nên tôi đã lấy áo khoác mặc vào.', 'chilly /ˈtʃɪli/', '["felt","chilly","It","so","I","my","outside","jacket","grabbed"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
