INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_60_4', 'en-b1-60', NULL, 'comprehensive_test', 'listening', 'We rarely eat outside when the weather turns cold.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Làm ơn mở hé cửa sổ một chút; trời hơi nóng.","Tôi hầu như không nghe thấy bạn nói gì vì tiếng mưa rơi quá lớn.","Chiếc xe đạp cũ này vẫn đáng giá năm mươi bảng.","Chúng tôi hiếm khi ăn ngoài khi trời trở lạnh."]'::jsonb, 3, 'We rarely eat outside when the weather turns cold. → Chúng tôi hiếm khi ăn ngoài khi trời trở lạnh.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
