INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_60_18', 'en-b1-60', NULL, 'comprehensive_test', 'reading', NULL, 'Providing warm public spaces during chilly weather can help protect older residents from cold-related illnesses.', 'Dựa vào câu trên, từ “chilly” có nghĩa phù hợp nhất là gì?', '["rất vui mừng; hài lòng","lạnh buốt; se lạnh","tiệm thuốc; nhà thuốc; quầy dược","tài khoản"]'::jsonb, 1, 'chilly: lạnh buốt; se lạnh; lạnh nhạt; thờ ơ. Dịch cả câu: Việc cung cấp không gian công cộng ấm áp trong thời tiết se lạnh có thể giúp bảo vệ cư dân lớn tuổi khỏi các bệnh do lạnh.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_60_19', 'en-b1-60', NULL, 'comprehensive_test', 'reading', NULL, 'Creating peaceful public spaces can improve residents'' wellbeing and encourage more people to spend time outdoors.', 'Dựa vào câu trên, từ “peaceful” có nghĩa phù hợp nhất là gì?', '["yên bình; thanh bình; tĩnh lặng","tái chế; tái tạo","hang động; động","cô dâu"]'::jsonb, 0, 'peaceful: yên bình; thanh bình; tĩnh lặng; hòa bình; không bạo lực. Dịch cả câu: Việc tạo ra các không gian công cộng yên bình có thể nâng cao phúc lợi của cư dân và khuyến khích nhiều người ra ngoài trời hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_60_20', 'en-b1-60', NULL, 'comprehensive_test', 'reading', NULL, 'A museum display of decorated teacups can reveal how domestic tastes and manufacturing techniques changed over time.', 'Dựa vào câu trên, từ “teacup” có nghĩa phù hợp nhất là gì?', '["ngày Lễ tặng quà (ngày 26 tháng 12)","tách trà; chén trà","gia vị","giảng viên đại học; báo cáo viên"]'::jsonb, 1, 'teacup: tách trà; chén trà. Dịch cả câu: Triển lãm bảo tàng về những chiếc tách trà trang trí có thể cho thấy gu thẩm mỹ gia đình và kỹ thuật sản xuất đã thay đổi theo thời gian như thế nào.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_60_21', 'en-b1-60', NULL, 'comprehensive_test', 'reading', NULL, 'People living in remote villages rarely have easy access to specialist medical services.', 'Dựa vào câu trên, từ “rarely” có nghĩa phù hợp nhất là gì?', '["đồ đựng; vật dùng để chứa hoặc bảo quản đồ đạc","hiếm khi; ít khi","làm bẹp dí; ép chặt vào không gian chật hẹp","gọt vỏ; bóc vỏ"]'::jsonb, 1, 'rarely: hiếm khi; ít khi. Dịch cả câu: Những người sống ở các ngôi làng hẻo lánh hiếm khi có cơ hội tiếp cận dễ dàng với các dịch vụ y tế chuyên khoa.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
