INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-61', 'en', 'Bài 61: Đời sống hằng ngày (13) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3061, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spill', 'en-b1-61', 'spill', '/spɪl/', 'B1', 'làm tràn; làm đổ; làm rơi vãi; chất lỏng bị đổ; vụ tràn dầu', 'v.', 'spillage (n.)', NULL, 'Dạng quá khứ và quá khứ phân từ có thể dùng spilled hoặc spilt.', 'I spilled orange juice all over my clean shirt.', NULL, 'Tôi vô tình làm đổ nước cam lênh láng khắp chiếc áo sơ mi sạch của mình.', '{"wordId":"spill","ukIpa":"/spɪl/","usIpa":"/spɪl/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To accidentally let liquid or loose material escape its container.","vi":"làm tràn; làm đổ; làm rơi vãi"},{"pos":"n.","en":"An amount of liquid spilled, or an incident involving spilling.","vi":"chất lỏng bị đổ; vụ tràn dầu"}],"examples":[{"en":"I spilled orange juice all over my clean shirt.","vi":"Tôi vô tình làm đổ nước cam lênh láng khắp chiếc áo sơ mi sạch của mình.","audioKind":"ex"},{"en":"Oil spills can damage marine ecosystems and threaten the livelihoods of communities that depend on fishing.","vi":"Sự cố tràn dầu có thể tàn phá hệ sinh thái biển và đe dọa sinh kế của các cộng đồng sống dựa vào đánh bắt thủy hải sản.","audioKind":"ex2"}],"collocations":[{"en":"spill a drink","vi":"làm đổ đồ uống"},{"en":"an oil spill","vi":"vụ tràn dầu"},{"en":"spill over","vi":"tràn ra; lan sang"},{"en":"spill the beans","vi":"tiết lộ bí mật"}],"wordFamily":["spillage (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ có thể dùng spilled hoặc spilt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sharp', 'en-b1-61', 'sharp', '/ʃɑːrp/', 'B1', 'sắc bén; nhọn; đột ngột; mạnh (mức độ lớn); nhanh nhạy; sắc sảo', 'adj.', 'sharpen (v.), sharply (adv.), sharpness (n.), sharpener (n.)', 'Trái nghĩa: blunt', 'Khi mô tả sự thay đổi, từ này thường chỉ mức độ lớn và xảy ra bất ngờ, ví dụ như a sharp rise.', 'This knife is sharp enough to slice tomatoes easily.', NULL, 'Con dao này đủ sắc để cắt cà chua một cách dễ dàng.', '{"wordId":"sharp","ukIpa":"/ʃɑːp/","usIpa":"/ʃɑːrp/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Having an edge or point that cuts or pierces easily.","vi":"sắc bén; nhọn"},{"pos":"adj.","en":"Sudden and large in degree or amount.","vi":"đột ngột; mạnh (mức độ lớn)"},{"pos":"adj.","en":"Quick to notice, understand, or respond to things.","vi":"nhanh nhạy; sắc sảo"}],"examples":[{"en":"This knife is sharp enough to slice tomatoes easily.","vi":"Con dao này đủ sắc để cắt cà chua một cách dễ dàng.","audioKind":"ex"},{"en":"A sharp increase in housing costs has forced many young adults to delay moving out of their parents'' homes.","vi":"Sự gia tăng đột ngột của chi phí nhà ở đã buộc nhiều người trẻ tuổi phải hoãn kế hoạch chuyển ra khỏi nhà cha mẹ.","audioKind":"ex2"}],"collocations":[{"en":"sharp knife","vi":"dao sắc"},{"en":"sharp increase","vi":"sự tăng vọt"},{"en":"sharp contrast","vi":"sự tương phản rõ rệt"},{"en":"sharp mind","vi":"tư duy nhạy bén"}],"wordFamily":["sharpen (v.)","sharply (adv.)","sharpness (n.)","sharpener (n.)"],"synonyms":[],"antonyms":["blunt"],"tipVi":"Khi mô tả sự thay đổi, từ này thường chỉ mức độ lớn và xảy ra bất ngờ, ví dụ như a sharp rise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_silence', 'en-b1-61', 'silence', '/ˈsaɪləns/', 'B1', 'sự yên lặng; sự im lặng; làm cho im lặng; dập tắt; bịt miệng', 'n.', 'silent (adj.), silently (adv.)', 'Đồng nghĩa: quiet · Trái nghĩa: noise', 'in silence mang nghĩa là lặng lẽ, âm thầm; silent là tính từ.', 'We sat in silence as the snow fell outside.', NULL, 'Chúng tôi ngồi trong sự tĩnh lặng khi tuyết rơi ngoài kia.', '{"wordId":"silence","ukIpa":"/ˈsaɪləns/","usIpa":"/ˈsaɪləns/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a lack of sound or speech","vi":"sự yên lặng; sự im lặng"},{"pos":"v.","en":"to stop someone or something making noise or expressing opinions","vi":"làm cho im lặng; dập tắt; bịt miệng"}],"examples":[{"en":"We sat in silence as the snow fell outside.","vi":"Chúng tôi ngồi trong sự tĩnh lặng khi tuyết rơi ngoài kia.","audioKind":"ex"},{"en":"Extended periods of silence in classrooms can give students valuable time to reflect on difficult questions.","vi":"Khoảng thời gian im lặng kéo dài trong lớp học có thể mang lại cho học sinh khoảng thời gian quý giá để suy ngẫm về những câu hỏi khó.","audioKind":"ex2"}],"collocations":[{"en":"in silence","vi":"trong sự im lặng"},{"en":"break the silence","vi":"phá vỡ sự im lặng"},{"en":"complete silence","vi":"sự im lặng tuyệt đối"},{"en":"silence criticism","vi":"trấn áp những lời chỉ trích"}],"wordFamily":["silent (adj.)","silently (adv.)"],"synonyms":["quiet"],"antonyms":["noise"],"tipVi":"in silence mang nghĩa là lặng lẽ, âm thầm; silent là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mat', 'en-b1-61', 'mat', '/mæt/', 'B1', 'tấm thảm; chiếu; làm cho rối bù; làm xoắn tít', 'n.', 'matting (n.), matted (adj.)', NULL, '"mat" thường là tấm thảm nhỏ có tính chức năng, không đồng nghĩa với "carpet".', 'Please wipe your shoes on the mat before entering.', NULL, 'Xin hãy lau giày lên thảm chùi chân trước khi bước vào.', '{"wordId":"mat","ukIpa":"/mæt/","usIpa":"/mæt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A piece of material covering or protecting a surface.","vi":"tấm thảm; chiếu"},{"pos":"v.","en":"To twist hair or fibres into a thick tangled mass.","vi":"làm cho rối bù; làm xoắn tít"}],"examples":[{"en":"Please wipe your shoes on the mat before entering.","vi":"Xin hãy lau giày lên thảm chùi chân trước khi bước vào.","audioKind":"ex"},{"en":"Placing a rubber mat near each entrance can help prevent slips in busy public buildings.","vi":"Việc đặt một tấm thảm cao su gần mỗi lối vào có thể giúp ngăn ngừa trượt ngã tại các tòa nhà công cộng đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"a yoga mat","vi":"thảm tập yoga"},{"en":"a rubber mat","vi":"thảm cao su"},{"en":"a bath mat","vi":"thảm phòng tắm"},{"en":"an exercise mat","vi":"thảm tập thể dục"}],"wordFamily":["matting (n.)","matted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"mat\" thường là tấm thảm nhỏ có tính chức năng, không đồng nghĩa với \"carpet\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_press', 'en-b1-61', 'press', '/pres/', 'B1', 'nhấn; ấn; giới truyền thông; báo chí; thúc giục; nài nỉ', 'v.', 'pressure (n.), pressing (adj.)', 'Đồng nghĩa: push, urge', 'Chỉ giới truyền thông thường dùng "the press"; ấn nút không dùng "push down".', 'Press this button to open the garage door.', NULL, 'Nhấn nút này để mở cửa nhà để xe.', '{"wordId":"press","ukIpa":"/pres/","usIpa":"/pres/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"Push firmly against something.","vi":"nhấn; ấn"},{"pos":"n.","en":"Newspapers, magazines, and the journalists who produce them.","vi":"giới truyền thông; báo chí"},{"pos":"v.","en":"Try firmly to persuade someone to do something.","vi":"thúc giục; nài nỉ"}],"examples":[{"en":"Press this button to open the garage door.","vi":"Nhấn nút này để mở cửa nhà để xe.","audioKind":"ex"},{"en":"A free press helps citizens understand public affairs and holds those in power accountable.","vi":"Một nền báo chí tự do giúp công dân hiểu rõ các vấn đề công cộng và buộc những người nắm quyền lực phải chịu trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"press a button","vi":"nhấn nút"},{"en":"freedom of the press","vi":"tự do báo chí"},{"en":"press conference","vi":"họp báo"},{"en":"press for change","vi":"thúc đẩy cải cách"}],"wordFamily":["pressure (n.)","pressing (adj.)"],"synonyms":["push","urge"],"antonyms":[],"tipVi":"Chỉ giới truyền thông thường dùng \"the press\"; ấn nút không dùng \"push down\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_postpone', 'en-b1-61', 'postpone', '/poʊˈspoʊn/', 'B1', 'hoãn lại; lùi lịch', 'v.', 'postponement (n.)', 'Đồng nghĩa: delay, defer · Trái nghĩa: bring forward', 'Theo sau là danh từ hoặc danh động từ: postpone doing, không dùng to do.', 'We postponed our picnic because heavy rain was forecast.', NULL, 'Chúng tôi đã hoãn buổi dã ngoại vì dự báo có mưa lớn.', '{"wordId":"postpone","ukIpa":"/pəˈspəʊn/","usIpa":"/poʊˈspoʊn/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to arrange for something to happen later than originally planned","vi":"hoãn lại; lùi lịch"}],"examples":[{"en":"We postponed our picnic because heavy rain was forecast.","vi":"Chúng tôi đã hoãn buổi dã ngoại vì dự báo có mưa lớn.","audioKind":"ex"},{"en":"Local authorities decided to postpone construction until a full assessment of the environmental impact was completed.","vi":"Các nhà chức trách địa phương đã quyết định hoãn việc thi công cho đến khi hoàn thành đánh giá toàn diện về tác động môi trường.","audioKind":"ex2"}],"collocations":[{"en":"postpone a meeting","vi":"hoãn cuộc họp"},{"en":"postpone a decision","vi":"hoãn một quyết định"},{"en":"postpone until further notice","vi":"hoãn lại cho đến khi có thông báo mới"}],"wordFamily":["postponement (n.)"],"synonyms":["delay","defer"],"antonyms":["bring forward"],"tipVi":"Theo sau là danh từ hoặc danh động từ: postpone doing, không dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_escape', 'en-b1-61', 'escape', '/ɪˈskeɪp/', 'B1', 'trốn thoát; thoát khỏi; tránh; né; thoát khỏi (điều tồi tệ); sự trốn thoát; sự thoát hiểm', 'v.', 'escaped (adj.), escapee (n.), inescapable (adj.)', 'Đồng nghĩa: get away', 'Thoát khỏi nơi nào đó dùng escape from; tránh được việc gì có thể dùng trực tiếp với danh từ.', 'Our rabbit escaped through a small gap in the fence.', NULL, 'Con thỏ của chúng tôi đã trốn thoát qua một khe hở nhỏ trên hàng rào.', '{"wordId":"escape","ukIpa":"/ɪˈskeɪp/","usIpa":"/ɪˈskeɪp/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to get away from confinement or a dangerous situation","vi":"trốn thoát; thoát khỏi"},{"pos":"v.","en":"to avoid something unpleasant or harmful","vi":"tránh; né; thoát khỏi (điều tồi tệ)"},{"pos":"n.","en":"the act of getting free from danger or unpleasant conditions","vi":"sự trốn thoát; sự thoát hiểm"}],"examples":[{"en":"Our rabbit escaped through a small gap in the fence.","vi":"Con thỏ của chúng tôi đã trốn thoát qua một khe hở nhỏ trên hàng rào.","audioKind":"ex"},{"en":"Accessible parks offer urban residents an escape from crowded streets and opportunities to enjoy nature.","vi":"Các công viên dễ tiếp cận mang lại cho cư dân thành phố chốn nghỉ ngơi thoát khỏi những con đường đông đúc và cơ hội tận hưởng thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"escape from danger","vi":"thoát khỏi nguy hiểm"},{"en":"narrow escape","vi":"thoát nạn trong gang tấc"},{"en":"escape injury","vi":"thoát bị thương"},{"en":"escape route","vi":"lối thoát hiểm"}],"wordFamily":["escaped (adj.)","escapee (n.)","inescapable (adj.)"],"synonyms":["get away"],"antonyms":[],"tipVi":"Thoát khỏi nơi nào đó dùng escape from; tránh được việc gì có thể dùng trực tiếp với danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_raw', 'en-b1-61', 'raw', '/rɔː/', 'B1', 'sống; chưa nấu chín; thô; chưa qua xử lý; chưa qua phân tích; trầy da; đỏ rát; tươm máu', 'adj.', 'rawness (n.)', 'Đồng nghĩa: uncooked, unprocessed · Trái nghĩa: cooked, processed', 'raw nhấn mạnh trạng thái chưa nấu chín hoặc chưa qua chế biến, không đồng nghĩa với "tươi" (fresh).', 'I prefer raw carrots because they are so crunchy.', NULL, 'Tôi thích ăn cà rốt sống hơn vì chúng rất giòn.', '{"wordId":"raw","ukIpa":"/rɔː/","usIpa":"/rɔː/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"not cooked","vi":"sống; chưa nấu chín"},{"pos":"adj.","en":"in its original state before processing or analysis","vi":"thô; chưa qua xử lý; chưa qua phân tích"},{"pos":"adj.","en":"sore because the skin is damaged or irritated","vi":"trầy da; đỏ rát; tươm máu"}],"examples":[{"en":"I prefer raw carrots because they are so crunchy.","vi":"Tôi thích ăn cà rốt sống hơn vì chúng rất giòn.","audioKind":"ex"},{"en":"Countries that export mainly raw materials may be vulnerable to sudden changes in global commodity prices.","vi":"Các quốc gia chủ yếu xuất khẩu nguyên liệu thô có thể dễ bị tổn thương trước những biến động đột ngột của giá hàng hóa toàn cầu.","audioKind":"ex2"}],"collocations":[{"en":"raw vegetables","vi":"rau sống"},{"en":"raw materials","vi":"nguyên liệu thô"},{"en":"raw data","vi":"dữ liệu thô"},{"en":"raw talent","vi":"tài năng thiên bẩm chưa qua mài giũa"}],"wordFamily":["rawness (n.)"],"synonyms":["uncooked","unprocessed"],"antonyms":["cooked","processed"],"tipVi":"raw nhấn mạnh trạng thái chưa nấu chín hoặc chưa qua chế biến, không đồng nghĩa với \"tươi\" (fresh).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suitable', 'en-b1-61', 'suitable', '/ˈsuːtəbl/', 'B1', 'phù hợp; thích hợp', 'adj.', 'suit (v.), suitability (n.), unsuitable (adj.), suitably (adv.)', 'Đồng nghĩa: appropriate, fitting · Trái nghĩa: unsuitable, inappropriate', 'Thường dùng suitable for sb/sth hoặc suitable to do sth.', 'These walking shoes are suitable for muddy forest paths.', NULL, 'Đôi giày đi bộ này phù hợp với những con đường mòn bùn lầy trong rừng.', '{"wordId":"suitable","ukIpa":"/ˈsuːtəbl/","usIpa":"/ˈsuːtəbl/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"right for a particular person, purpose, or situation","vi":"phù hợp; thích hợp"}],"examples":[{"en":"These walking shoes are suitable for muddy forest paths.","vi":"Đôi giày đi bộ này phù hợp với những con đường mòn bùn lầy trong rừng.","audioKind":"ex"},{"en":"Cities should provide suitable housing for older residents, with easy access to healthcare and public transport.","vi":"Các thành phố nên cung cấp nhà ở phù hợp cho người cao tuổi, thuận tiện tiếp cận dịch vụ y tế và giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"suitable for children","vi":"thích hợp cho trẻ em"},{"en":"suitable accommodation","vi":"chỗ ở phù hợp"},{"en":"a suitable candidate","vi":"một ứng viên phù hợp"}],"wordFamily":["suit (v.)","suitability (n.)","unsuitable (adj.)","suitably (adv.)"],"synonyms":["appropriate","fitting"],"antonyms":["unsuitable","inappropriate"],"tipVi":"Thường dùng suitable for sb/sth hoặc suitable to do sth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hop', 'en-b1-61', 'hop', '/hɑːp/', 'B1', 'nhảy lò cò; nhảy chồm chồm; cú nhảy lò cò; bước nhảy ngắn; lên xuống xe nhanh chóng', 'v.', NULL, 'Đồng nghĩa: jump, bounce', 'Dạng quá khứ là hopped, tiếp diễn là hopping, cần gấp đôi chữ p.', 'The little bird hopped across the wet garden path.', NULL, 'Con chim nhỏ nhảy lò cò băng qua lối đi ướt át trong vườn.', '{"wordId":"hop","ukIpa":"/hɒp/","usIpa":"/hɑːp/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To jump on one foot or make small jumps.","vi":"nhảy lò cò; nhảy chồm chồm"},{"pos":"n.","en":"A small jump, especially one made on one foot.","vi":"cú nhảy lò cò; bước nhảy ngắn"},{"pos":"v.","en":"To get on or off a vehicle quickly and easily.","vi":"lên xuống xe nhanh chóng"}],"examples":[{"en":"The little bird hopped across the wet garden path.","vi":"Con chim nhỏ nhảy lò cò băng qua lối đi ướt át trong vườn.","audioKind":"ex"},{"en":"Activities that encourage children to hop and balance can support physical development in early education.","vi":"Các hoạt động khuyến khích trẻ em nhảy lò cò và giữ thăng bằng có thể hỗ trợ sự phát triển thể chất trong giáo dục mầm non.","audioKind":"ex2"}],"collocations":[{"en":"hop on one foot","vi":"nhảy lò cò bằng một chân"},{"en":"hop on a bus","vi":"nhanh chóng lên xe buýt"},{"en":"hop off","vi":"nhanh chóng xuống xe"},{"en":"a short hop","vi":"một chuyến đi ngắn"}],"wordFamily":[],"synonyms":["jump","bounce"],"antonyms":[],"tipVi":"Dạng quá khứ là hopped, tiếp diễn là hopping, cần gấp đôi chữ p.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_confirm', 'en-b1-61', 'confirm', '/kənˈfɝːm/', 'B1', 'xác nhận; chứng thực; phê duyệt; xác nhận lịch hẹn', 'v.', 'confirmation (n.), confirmed (adj.)', 'Đồng nghĩa: verify, substantiate · Trái nghĩa: refute', 'Có thể đi với danh từ hoặc mệnh đề that; không dùng confirm to do.', 'Please call the hotel to confirm our booking today.', NULL, 'Xin hãy gọi điện cho khách sạn để xác nhận lịch đặt phòng của chúng ta hôm nay.', '{"wordId":"confirm","ukIpa":"/kənˈfɜːm/","usIpa":"/kənˈfɝːm/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To establish that something is true or correct.","vi":"xác nhận; chứng thực"},{"pos":"v.","en":"To make an arrangement certain or give it official approval.","vi":"phê duyệt; xác nhận lịch hẹn"}],"examples":[{"en":"Please call the hotel to confirm our booking today.","vi":"Xin hãy gọi điện cho khách sạn để xác nhận lịch đặt phòng của chúng ta hôm nay.","audioKind":"ex"},{"en":"Further research is needed to confirm whether smaller classes consistently improve learning outcomes in primary schools.","vi":"Cần có thêm nhiều nghiên cứu để xác định xem lớp học quy mô nhỏ có thực sự cải thiện kết quả học tập ở trường tiểu học hay không.","audioKind":"ex2"}],"collocations":[{"en":"confirm a booking","vi":"xác nhận đặt chỗ"},{"en":"confirm that","vi":"xác nhận rằng"},{"en":"confirm a diagnosis","vi":"chẩn đoán xác định"},{"en":"confirm receipt","vi":"xác nhận đã nhận"}],"wordFamily":["confirmation (n.)","confirmed (adj.)"],"synonyms":["verify","substantiate"],"antonyms":["refute"],"tipVi":"Có thể đi với danh từ hoặc mệnh đề that; không dùng confirm to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pin', 'en-b1-61', 'pin', '/pɪn/', 'B1', 'đinh ghim; kim băng; ghim lại; đính lại; giữ chặt; đè chặt', 'n.', 'pinned (adj.)', NULL, 'Khi pin là động từ, quá khứ là pinned, phân từ hiện tại là pinning.', 'She used a pin to hold the fabric together.', NULL, 'Cô ấy dùng một chiếc kim băng để kẹp các mảnh vải lại với nhau.', '{"wordId":"pin","ukIpa":"/pɪn/","usIpa":"/pɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a small pointed metal object used to hold things together","vi":"đinh ghim; kim băng"},{"pos":"v.","en":"to fasten something with a pin or similar object","vi":"ghim lại; đính lại"},{"pos":"v.","en":"to hold someone or something firmly so movement is impossible","vi":"giữ chặt; đè chặt"}],"examples":[{"en":"She used a pin to hold the fabric together.","vi":"Cô ấy dùng một chiếc kim băng để kẹp các mảnh vải lại với nhau.","audioKind":"ex"},{"en":"Teachers can pin students'' artwork to classroom walls to celebrate creativity and encourage participation.","vi":"Giáo viên có thể ghim các tác phẩm nghệ thuật của học sinh lên tường lớp học để tôn vinh sự sáng tạo và khuyến khích các em tham gia.","audioKind":"ex2"}],"collocations":[{"en":"safety pin","vi":"kim băng"},{"en":"drawing pin","vi":"đinh ghim"},{"en":"pin something to","vi":"ghim cái gì vào đâu"},{"en":"pin down","vi":"ghim chặt; xác định rõ"}],"wordFamily":["pinned (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi pin là động từ, quá khứ là pinned, phân từ hiện tại là pinning.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shared', 'en-b1-61', 'shared', '/ʃerd/', 'B1', 'chung; dùng chung; chia sẻ; dùng chung (quá khứ)', 'adj.', 'share (v.), share (n.), sharing (n.)', 'Đồng nghĩa: joint, communal · Trái nghĩa: private', 'Có thể đóng vai trò là tính từ, hoặc là dạng quá khứ/quá khứ phân từ của share.', 'Our shared kitchen gets busy around dinner time.', NULL, 'Căn bếp chung của chúng tôi trở nên bận rộn vào giờ ăn tối.', '{"wordId":"shared","ukIpa":"/ʃeəd/","usIpa":"/ʃerd/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Used, owned, or experienced by more than one person","vi":"chung; dùng chung"},{"pos":"v.","en":"Gave others part of something or used something together","vi":"chia sẻ; dùng chung (quá khứ)"}],"examples":[{"en":"Our shared kitchen gets busy around dinner time.","vi":"Căn bếp chung của chúng tôi trở nên bận rộn vào giờ ăn tối.","audioKind":"ex"},{"en":"Shared responsibility for household tasks can reduce stress and improve relationships between family members.","vi":"Việc cùng nhau gánh vác trách việc nhà có thể làm giảm căng thẳng và cải thiện mối quan hệ giữa các thành viên trong gia đình.","audioKind":"ex2"}],"collocations":[{"en":"shared accommodation","vi":"nơi ở chung"},{"en":"shared responsibility","vi":"trách nhiệm chung"},{"en":"shared interests","vi":"sở thích chung"},{"en":"shared resources","vi":"tài nguyên chung"}],"wordFamily":["share (v.)","share (n.)","sharing (n.)"],"synonyms":["joint","communal"],"antonyms":["private"],"tipVi":"Có thể đóng vai trò là tính từ, hoặc là dạng quá khứ/quá khứ phân từ của share.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thumb', 'en-b1-61', 'thumb', '/θʌm/', 'B1', 'ngón tay cái; lướt nhanh; đọc lướt qua', 'n.', 'thumbnail (n.)', NULL, 'b không phát âm; thumb through diễn tả hành động lướt nhanh qua trang sách.', 'I accidentally hit my thumb while hanging a picture.', NULL, 'Tôi vô tình đập trúng ngón tay cái khi đang treo tranh.', '{"wordId":"thumb","ukIpa":"/θʌm/","usIpa":"/θʌm/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The short, thick finger on the side of your hand.","vi":"ngón tay cái"},{"pos":"v.","en":"To turn pages quickly without reading everything carefully.","vi":"lướt nhanh; đọc lướt qua"}],"examples":[{"en":"I accidentally hit my thumb while hanging a picture.","vi":"Tôi vô tình đập trúng ngón tay cái khi đang treo tranh.","audioKind":"ex"},{"en":"Many readers thumb through printed magazines before deciding which articles deserve their full attention.","vi":"Nhiều độc giả lướt nhanh qua các tạp chí in trước khi quyết định bài viết nào đáng để họ chú ý hoàn toàn.","audioKind":"ex2"}],"collocations":[{"en":"thumb through","vi":"lướt nhanh qua"},{"en":"a thumbs-up","vi":"giơ ngón tay cái tán thành"},{"en":"a rule of thumb","vi":"quy tắc kinh nghiệm"}],"wordFamily":["thumbnail (n.)"],"synonyms":[],"antonyms":[],"tipVi":"b không phát âm; thumb through diễn tả hành động lướt nhanh qua trang sách.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_laundry', 'en-b1-61', 'laundry', '/ˈlɔːndri/', 'B1', 'quần áo bẩn (hoặc mới giặt); việc giặt giũ; tiệm giặt là', 'n.', 'launder (v.)', NULL, 'Khi chỉ quần áo hoặc hành động giặt giũ, từ này thường không đếm được.', 'Please put your dirty laundry in the basket.', NULL, 'Làm ơn cho quần áo bẩn của bạn vào giỏ đi.', '{"wordId":"laundry","ukIpa":"/ˈlɔːndri/","usIpa":"/ˈlɔːndri/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Clothes and other fabrics waiting to be washed or freshly washed.","vi":"quần áo bẩn (hoặc mới giặt)"},{"pos":"n.","en":"The activity of washing clothes, or a place providing this service.","vi":"việc giặt giũ; tiệm giặt là"}],"examples":[{"en":"Please put your dirty laundry in the basket.","vi":"Làm ơn cho quần áo bẩn của bạn vào giỏ đi.","audioKind":"ex"},{"en":"Shared laundry facilities can reduce water consumption and save space in modern apartment buildings.","vi":"Các khu giặt là chung có thể làm giảm lượng nước tiêu thụ và tiết kiệm không gian trong các tòa nhà chung cư hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"do the laundry","vi":"giặt quần áo"},{"en":"dirty laundry","vi":"quần áo bẩn"},{"en":"a laundry basket","vi":"giỏ đựng đồ giặt"},{"en":"laundry facilities","vi":"thiet bi giặt là"}],"wordFamily":["launder (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ quần áo hoặc hành động giặt giũ, từ này thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_layer', 'en-b1-61', 'layer', '/ˈleɪər/', 'B1', 'lớp (vật chất phủ trên bề mặt hoặc chồng lên nhau); xếp thành lớp; phân tầng', 'n.', 'layered (adj.), layering (n.)', NULL, '"một lớp vật gì đó" dùng a layer of; layer cũng có thể dùng như động từ.', 'A thin layer of dust covered the shelf.', NULL, 'Một lớp bụi mỏng phủ lên chiếc kệ.', '{"wordId":"layer","ukIpa":"/ˈleɪə/","usIpa":"/ˈleɪər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"an amount of material covering a surface or another amount","vi":"lớp (vật chất phủ trên bề mặt hoặc chồng lên nhau)"},{"pos":"v.","en":"to arrange things in sheets or levels over each other","vi":"xếp thành lớp; phân tầng"}],"examples":[{"en":"A thin layer of dust covered the shelf.","vi":"Một lớp bụi mỏng phủ lên chiếc kệ.","audioKind":"ex"},{"en":"Adding an extra layer of insulation can significantly reduce energy consumption in older homes.","vi":"Việc bổ sung thêm một lớp cách nhiệt có thể làm giảm đáng kể mức tiêu thụ năng lượng ở các ngôi nhà cũ.","audioKind":"ex2"}],"collocations":[{"en":"a thin layer","vi":"một lớp mỏng"},{"en":"a layer of dust","vi":"một lớp bụi"},{"en":"protective layer","vi":"lớp bảo vệ"},{"en":"outer layer","vi":"lớp bên ngoài"}],"wordFamily":["layered (adj.)","layering (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"một lớp vật gì đó\" dùng a layer of; layer cũng có thể dùng như động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dough', 'en-b1-61', 'dough', '/doʊ/', 'B1', 'bột nhào (hỗn hợp bột và chất lỏng dùng để nướng); tiền (ngôn ngữ không chính thức)', 'n.', 'doughy (adj.)', NULL, 'là danh từ không đếm được; hỗn hợp bột lỏng thường được gọi là batter.', 'Mina kneaded the dough on a flour-covered kitchen table.', NULL, 'Mina nhào bột trên chiếc bàn bếp được phủ một lớp bột mì.', '{"wordId":"dough","ukIpa":"/dəʊ/","usIpa":"/doʊ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A thick mixture of flour and liquid used for baking.","vi":"bột nhào (hỗn hợp bột và chất lỏng dùng để nướng)"},{"pos":"n.","en":"Money, in informal speech.","vi":"tiền (ngôn ngữ không chính thức)"}],"examples":[{"en":"Mina kneaded the dough on a flour-covered kitchen table.","vi":"Mina nhào bột trên chiếc bàn bếp được phủ một lớp bột mì.","audioKind":"ex"},{"en":"Allowing dough to rise slowly can improve bread quality without the need for artificial additives.","vi":"Để bột nổi từ từ có thể cải thiện chất lượng bánh mì mà không cần dùng đến phụ gia nhân tạo.","audioKind":"ex2"}],"collocations":[{"en":"knead dough","vi":"nhào bột"},{"en":"roll out dough","vi":"cán bột"},{"en":"bread dough","vi":"bột làm bánh mì"},{"en":"let the dough rise","vi":"để bột nở"}],"wordFamily":["doughy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"là danh từ không đếm được; hỗn hợp bột lỏng thường được gọi là batter.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lack', 'en-b1-61', 'lack', '/læk/', 'B1', 'sự thiếu hụt; sự không có đủ; thiếu; không có đủ', 'n.', 'lacking (adj.)', 'Đồng nghĩa: shortage · Trái nghĩa: abundance', 'danh từ đi với a lack of; động từ nối trực tiếp với tân ngữ, không dùng thêm of.', 'A lack of sleep made me tired all morning.', NULL, 'Sự thiếu ngủ khiến tôi mệt mỏi suốt cả buổi sáng.', '{"wordId":"lack","ukIpa":"/læk/","usIpa":"/læk/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The absence of something or not having enough of it","vi":"sự thiếu hụt; sự không có đủ"},{"pos":"v.","en":"Not have something necessary or enough of it","vi":"thiếu; không có đủ"}],"examples":[{"en":"A lack of sleep made me tired all morning.","vi":"Sự thiếu ngủ khiến tôi mệt mỏi suốt cả buổi sáng.","audioKind":"ex"},{"en":"Many rural schools lack the resources needed to provide students with practical science lessons.","vi":"Nhiều trường học vùng nông thôn thiếu các nguồn lực cần thiết để cung cấp cho học sinh những buổi học thực hành khoa học.","audioKind":"ex2"}],"collocations":[{"en":"a lack of resources","vi":"thiếu thốn tài nguyên"},{"en":"lack confidence","vi":"thiếu sự tự tin"},{"en":"for lack of funding","vi":"vì thiếu kinh phí"},{"en":"a lack of sleep","vi":"sự thiếu ngủ"}],"wordFamily":["lacking (adj.)"],"synonyms":["shortage"],"antonyms":["abundance"],"tipVi":"danh từ đi với a lack of; động từ nối trực tiếp với tân ngữ, không dùng thêm of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dining', 'en-b1-61', 'dining', '/ˈdaɪnɪŋ/', 'B1', 'việc ăn uống; dùng bữa', 'n.', 'dine (v.), diner (n.)', NULL, 'Đồng thời là phân từ hiện tại của động từ dine; từ dining chỉ chứa một chữ n ở cuối đoạn.', 'We moved the dining table closer to the window.', NULL, 'Chúng tôi đã dịch chuyển bàn ăn lại gần cửa sổ hơn.', '{"wordId":"dining","ukIpa":"/ˈdaɪnɪŋ/","usIpa":"/ˈdaɪnɪŋ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The activity of eating a meal","vi":"việc ăn uống; dùng bữa"}],"examples":[{"en":"We moved the dining table closer to the window.","vi":"Chúng tôi đã dịch chuyển bàn ăn lại gần cửa sổ hơn.","audioKind":"ex"},{"en":"Shared dining spaces in student accommodation can encourage social interaction and help newcomers develop a sense of belonging.","vi":"Khu vực dùng bữa chung trong ký túc xá sinh viên có thể thúc đẩy sự giao lưu xã hội và giúp những tân sinh viên xây dựng cảm giác thân thuộc.","audioKind":"ex2"}],"collocations":[{"en":"dining room","vi":"phòng ăn"},{"en":"dining table","vi":"bàn ăn"},{"en":"fine dining","vi":"ẩm thực cao cấp"},{"en":"outdoor dining","vi":"ăn uống ngoài trời"}],"wordFamily":["dine (v.)","diner (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Đồng thời là phân từ hiện tại của động từ dine; từ dining chỉ chứa một chữ n ở cuối đoạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gather', 'en-b1-61', 'gather', '/ˈɡæðər/', 'B1', 'thu thập; gom lại; tụ tập; tụ hội; suy ra; hiểu ra', 'v.', 'gathering (n.), gatherer (n.)', 'Đồng nghĩa: collect, assemble · Trái nghĩa: scatter', 'Cấu trúc I gather that... biểu thị ý nghĩa "tôi nghe ngóng được hoặc suy luận rằng...".', 'We gathered fallen apples in a basket before lunch.', NULL, 'Chúng tôi đã gom những quả táo rụng vào một chiếc giỏ trước bữa trưa.', '{"wordId":"gather","ukIpa":"/ˈɡæðə/","usIpa":"/ˈɡæðər/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to collect things from different places or sources","vi":"thu thập; gom lại"},{"pos":"v.","en":"to come together or bring people together","vi":"tụ tập; tụ hội"},{"pos":"v.","en":"to understand something from what you hear or observe","vi":"suy ra; hiểu ra"}],"examples":[{"en":"We gathered fallen apples in a basket before lunch.","vi":"Chúng tôi đã gom những quả táo rụng vào một chiếc giỏ trước bữa trưa.","audioKind":"ex"},{"en":"Researchers gather information from local residents to understand how public transport affects access to employment.","vi":"Các nhà nghiên cứu thu thập thông tin từ cư dân địa phương để tìm hiểu cách hệ thống giao thông công cộng ảnh hưởng đến khả năng tiếp cận việc làm.","audioKind":"ex2"}],"collocations":[{"en":"gather information","vi":"thu thập thông tin"},{"en":"gather evidence","vi":"thu thập chứng cứ"},{"en":"gather together","vi":"tụ họp lại với nhau"},{"en":"gather strength","vi":"tích lũy sức mạnh"}],"wordFamily":["gathering (n.)","gatherer (n.)"],"synonyms":["collect","assemble"],"antonyms":["scatter"],"tipVi":"Cấu trúc I gather that... biểu thị ý nghĩa \"tôi nghe ngóng được hoặc suy luận rằng...\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fortnight', 'en-b1-61', 'fortnight', '/ˈfɔːrtnaɪt/', 'B1', 'hai tuần; nửa tháng', 'n.', 'fortnightly (adj.), fortnightly (adv.)', 'Đồng nghĩa: two weeks', 'Chủ yếu được dùng trong tiếng Anh-Anh; tiếng Anh-Mỹ thường dùng two weeks.', 'We''re spending a fortnight by the sea this summer.', NULL, 'Chúng tôi sẽ dành hai tuần bên bờ biển vào mùa hè này.', '{"wordId":"fortnight","ukIpa":"/ˈfɔːtnaɪt/","usIpa":"/ˈfɔːrtnaɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A period of two weeks.","vi":"hai tuần; nửa tháng"}],"examples":[{"en":"We''re spending a fortnight by the sea this summer.","vi":"Chúng tôi sẽ dành hai tuần bên bờ biển vào mùa hè này.","audioKind":"ex"},{"en":"Allowing employees to work remotely for a fortnight could help employers evaluate the benefits of flexible working.","vi":"Việc cho phép nhân viên làm việc từ xa trong hai tuần có thể giúp các nhà tuyển dụng đánh giá được lợi ích của chế độ làm việc linh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"a fortnight ago","vi":"hai tuần trước"},{"en":"in a fortnight","vi":"trong vòng hai tuần nữa"},{"en":"once a fortnight","vi":"mỗi hai tuần một lần"}],"wordFamily":["fortnightly (adj.)","fortnightly (adv.)"],"synonyms":["two weeks"],"antonyms":[],"tipVi":"Chủ yếu được dùng trong tiếng Anh-Anh; tiếng Anh-Mỹ thường dùng two weeks.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whatever', 'en-b1-61', 'whatever', '/wʌtˈevər/', 'B1', 'bất cứ thứ gì; bất luận cái gì; bất cứ loại nào; bất kỳ... nào', 'pron.', NULL, NULL, 'whatever không giới hạn phạm vi; whichever thường dùng để chỉ việc chọn lựa trong một giới hạn nhất định.', 'You can choose whatever you like for dinner tonight.', NULL, 'Bạn có thể chọn bất cứ món gì bạn thích cho bữa tối nay.', '{"wordId":"whatever","ukIpa":"/wɒtˈevə/","usIpa":"/wʌtˈevər/","cefr":"B1","topic":"daily","senses":[{"pos":"pron.","en":"anything that; no matter what","vi":"bất cứ thứ gì; bất luận cái gì"},{"pos":"det.","en":"any kind of something, without restriction","vi":"bất cứ loại nào; bất kỳ... nào"}],"examples":[{"en":"You can choose whatever you like for dinner tonight.","vi":"Bạn có thể chọn bất cứ món gì bạn thích cho bữa tối nay.","audioKind":"ex"},{"en":"Whatever their background, students should have equal access to high-quality education and appropriate learning support.","vi":"Dù bối cảnh có thế nào đi nữa, học sinh đều nên có cơ hội tiếp cận công bằng với nền giáo dục chất lượng cao và sự hỗ trợ học tập phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"whatever happens","vi":"bất kể điều gì xảy ra"},{"en":"whatever the reason","vi":"dù lý do là gì đi nữa"},{"en":"whatever you like","vi":"bất cứ thứ gì bạn thích"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"whatever không giới hạn phạm vi; whichever thường dùng để chỉ việc chọn lựa trong một giới hạn nhất định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grab', 'en-b1-61', 'grab', '/ɡræb/', 'B1', 'chộp lấy; vồ lấy; nắm lấy; ăn vội; uống vội; tranh thủ; thu hút; gây chú ý mạnh mẽ', 'v.', NULL, 'Đồng nghĩa: seize, snatch · Trái nghĩa: release', 'grab mang phong cách khẩu ngữ; dạng quá khứ là grabbed, phân từ là grabbing.', 'She grabbed her umbrella and ran towards the bus.', NULL, 'Cô ấy chộp lấy chiếc ô rồi chạy về phía xe buýt.', '{"wordId":"grab","ukIpa":"/ɡræb/","usIpa":"/ɡræb/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to take hold of something suddenly or firmly","vi":"chộp lấy; vồ lấy; nắm lấy"},{"pos":"v.","en":"to get food, drink, or something else quickly","vi":"ăn vội; uống vội; tranh thủ"},{"pos":"v.","en":"to attract someone''s attention strongly","vi":"thu hút; gây chú ý mạnh mẽ"}],"examples":[{"en":"She grabbed her umbrella and ran towards the bus.","vi":"Cô ấy chộp lấy chiếc ô rồi chạy về phía xe buýt.","audioKind":"ex"},{"en":"Public health campaigns often use striking images to grab attention and encourage people to change unhealthy habits.","vi":"Các chiến dịch y tế cộng đồng thường sử dụng những hình ảnh nổi bật để thu hút sự chú ý và khuyến khích mọi người thay đổi thói quen không lành mạnh.","audioKind":"ex2"}],"collocations":[{"en":"grab someone''s attention","vi":"thu hút sự chú ý của ai đó"},{"en":"grab a bite","vi":"ăn vội một miếng lót dạ"},{"en":"grab an opportunity","vi":"chớp lấy cơ hội"}],"wordFamily":[],"synonyms":["seize","snatch"],"antonyms":["release"],"tipVi":"grab mang phong cách khẩu ngữ; dạng quá khứ là grabbed, phân từ là grabbing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frequently', 'en-b1-61', 'frequently', '/ˈfriːkwəntli/', 'B1', 'thường xuyên; hay', 'adv.', 'frequent (adj.), frequency (n.), infrequently (adv.)', 'Đồng nghĩa: often, regularly · Trái nghĩa: rarely, infrequently', 'Thường đặt trước động từ chỉ hành động và sau động từ "be", có nghĩa gần giống với "often".', 'Our neighbour frequently brings us vegetables from her garden.', NULL, 'Hàng xóm của chúng tôi thường xuyên mang rau từ vườn nhà cô ấy sang cho chúng tôi.', '{"wordId":"frequently","ukIpa":"/ˈfriːkwəntli/","usIpa":"/ˈfriːkwəntli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"Often or many times","vi":"thường xuyên; hay"}],"examples":[{"en":"Our neighbour frequently brings us vegetables from her garden.","vi":"Hàng xóm của chúng tôi thường xuyên mang rau từ vườn nhà cô ấy sang cho chúng tôi.","audioKind":"ex"},{"en":"People who frequently use public transport may spend less on travel than those who drive daily.","vi":"Những người thường xuyên sử dụng phương tiện giao thông công cộng có thể chi tiêu cho việc đi lại ít hơn so với những người lái xe hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"frequently asked questions","vi":"câu hỏi thường gặp"},{"en":"occur frequently","vi":"xảy ra thường xuyên"},{"en":"frequently used","vi":"được sử dụng thường xuyên"}],"wordFamily":["frequent (adj.)","frequency (n.)","infrequently (adv.)"],"synonyms":["often","regularly"],"antonyms":["rarely","infrequently"],"tipVi":"Thường đặt trước động từ chỉ hành động và sau động từ \"be\", có nghĩa gần giống với \"often\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cushion', 'en-b1-61', 'cushion', '/ˈkʊʃən/', 'B1', 'gối tựa; đệm lót; làm giảm; làm dịu bớt (tác động mạnh); vật bảo vệ; sự đệm lót (tránh tổn thất)', 'n.', 'cushioned (adj.), cushioning (n.)', NULL, 'Động từ thường đi với "impact" hoặc "blow" để chỉ việc giảm bớt tác động mạnh.', 'She put a soft cushion behind her back.', NULL, 'Cô ấy đặt một chiếc gối tựa mềm đằng sau lưng.', '{"wordId":"cushion","ukIpa":"/ˈkʊʃən/","usIpa":"/ˈkʊʃən/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A soft filled bag used for comfort or support.","vi":"gối tựa; đệm lót"},{"pos":"v.","en":"To soften an impact or reduce a harmful effect.","vi":"làm giảm; làm dịu bớt (tác động mạnh)"},{"pos":"n.","en":"Something that protects against difficulty, loss, or sudden change.","vi":"vật bảo vệ; sự đệm lót (tránh tổn thất)"}],"examples":[{"en":"She put a soft cushion behind her back.","vi":"Cô ấy đặt một chiếc gối tựa mềm đằng sau lưng.","audioKind":"ex"},{"en":"Emergency savings can cushion the financial impact of unemployment and help families maintain their living standards.","vi":"Tiền tiết kiệm dự phòng có thể làm giảm cú sốc tài chính do thất nghiệp gây ra và giúp các gia đình duy trì mức sống.","audioKind":"ex2"}],"collocations":[{"en":"soft cushion","vi":"gối tựa mềm"},{"en":"cushion the impact","vi":"giảm nhẹ tác động"},{"en":"financial cushion","vi":"sự bảo đảm tài chính"}],"wordFamily":["cushioned (adj.)","cushioning (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường đi với \"impact\" hoặc \"blow\" để chỉ việc giảm bớt tác động mạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_remove', 'en-b1-61', 'remove', '/rɪˈmuːv/', 'B1', 'lấy đi; tháo ra; cởi ra; xóa bỏ; loại bỏ; cách chức; bãi nhiệm', 'v.', 'removal (n.), removable (adj.)', 'Đồng nghĩa: take away, eliminate', 'Thường dùng cấu trúc remove A from B, biểu thị hành động lấy A ra khỏi B.', 'Please remove your shoes before stepping onto the new carpet.', NULL, 'Vui lòng cởi giày trước khi bước lên tấm thảm mới.', '{"wordId":"remove","ukIpa":"/rɪˈmuːv/","usIpa":"/rɪˈmuːv/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to take something away from where it is","vi":"lấy đi; tháo ra; cởi ra"},{"pos":"v.","en":"to get rid of something unwanted","vi":"xóa bỏ; loại bỏ"},{"pos":"v.","en":"to make someone leave a job or position","vi":"cách chức; bãi nhiệm"}],"examples":[{"en":"Please remove your shoes before stepping onto the new carpet.","vi":"Vui lòng cởi giày trước khi bước lên tấm thảm mới.","audioKind":"ex"},{"en":"Governments should remove unnecessary barriers that prevent qualified workers from entering the labour market.","vi":"Chính phủ nên loại bỏ những rào cản không cần thiết ngăn cản lao động có trình độ tham gia thị trường lao động.","audioKind":"ex2"}],"collocations":[{"en":"remove stains","vi":"tẩy vết bẩn"},{"en":"remove barriers","vi":"xóa bỏ rào cản"},{"en":"remove waste","vi":"xử lý chất thải"},{"en":"remove someone from office","vi":"bãi nhiệm chức vụ của ai đó"}],"wordFamily":["removal (n.)","removable (adj.)"],"synonyms":["take away","eliminate"],"antonyms":[],"tipVi":"Thường dùng cấu trúc remove A from B, biểu thị hành động lấy A ra khỏi B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_separately', 'en-b1-61', 'separately', '/ˈsepərətli/', 'B1', 'riêng biệt; tách rời nhau; độc lập', 'adv.', 'separate (adj.), separate (v.), separation (n.)', 'Đồng nghĩa: individually, apart · Trái nghĩa: together, jointly', 'Dùng separately from để chỉ việc tách biệt với vật gì, không dùng với từ with.', 'We paid separately, then walked home together after lunch.', NULL, 'Chúng tôi trả tiền riêng, sau đó đi bộ về nhà cùng nhau sau bữa trưa.', '{"wordId":"separately","ukIpa":"/ˈseprətli/","usIpa":"/ˈsepərətli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"Apart from others, or individually rather than together.","vi":"riêng biệt; tách rời nhau; độc lập"}],"examples":[{"en":"We paid separately, then walked home together after lunch.","vi":"Chúng tôi trả tiền riêng, sau đó đi bộ về nhà cùng nhau sau bữa trưa.","audioKind":"ex"},{"en":"Households should collect food waste separately so that local authorities can process it into compost more efficiently.","vi":"Các hộ gia đình nên thu gom rác thải thực phẩm riêng biệt để các cơ quan chức năng có thể xử lý thành phân hữu cơ hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"sold separately","vi":"bán rời"},{"en":"pay separately","vi":"thanh toán riêng"},{"en":"separately from","vi":"tách biệt khỏi"}],"wordFamily":["separate (adj.)","separate (v.)","separation (n.)"],"synonyms":["individually","apart"],"antonyms":["together","jointly"],"tipVi":"Dùng separately from để chỉ việc tách biệt với vật gì, không dùng với từ with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_61_1', 'en-b1-61', 'Cách dùng “whatever” (pron.) — bất cứ thứ gì; bất luận cái gì', 'whatever happens  ·  whatever the reason  ·  whatever you like', 'whatever không giới hạn phạm vi; whichever thường dùng để chỉ việc chọn lựa trong một giới hạn nhất định.', NULL, '[{"hanzi":"You can choose whatever you like for dinner tonight.","pinyin":"","meaning":"Bạn có thể chọn bất cứ món gì bạn thích cho bữa tối nay."},{"hanzi":"Whatever their background, students should have equal access to high-quality education and appropriate learning support.","pinyin":"","meaning":"Dù bối cảnh có thế nào đi nữa, học sinh đều nên có cơ hội tiếp cận công bằng với nền giáo dục chất lượng cao và sự hỗ trợ học tập phù hợp."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_61_2', 'en-b1-61', 'Cách dùng “raw” (adj.) — sống; chưa nấu chín', 'raw vegetables  ·  raw materials  ·  raw data', 'raw nhấn mạnh trạng thái chưa nấu chín hoặc chưa qua chế biến, không đồng nghĩa với "tươi" (fresh).', 'Họ từ (Word Family): rawness (n.) | Đồng nghĩa: uncooked, unprocessed · Trái nghĩa: cooked, processed', '[{"hanzi":"I prefer raw carrots because they are so crunchy.","pinyin":"","meaning":"Tôi thích ăn cà rốt sống hơn vì chúng rất giòn."},{"hanzi":"Countries that export mainly raw materials may be vulnerable to sudden changes in global commodity prices.","pinyin":"","meaning":"Các quốc gia chủ yếu xuất khẩu nguyên liệu thô có thể dễ bị tổn thương trước những biến động đột ngột của giá hàng hóa toàn cầu."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_61_3', 'en-b1-61', 'Cách dùng “sharp” (adj.) — sắc bén; nhọn', 'sharp knife  ·  sharp increase  ·  sharp contrast', 'Khi mô tả sự thay đổi, từ này thường chỉ mức độ lớn và xảy ra bất ngờ, ví dụ như a sharp rise.', 'Họ từ (Word Family): sharpen (v.), sharply (adv.), sharpness (n.), sharpener (n.) | Trái nghĩa: blunt', '[{"hanzi":"This knife is sharp enough to slice tomatoes easily.","pinyin":"","meaning":"Con dao này đủ sắc để cắt cà chua một cách dễ dàng."},{"hanzi":"A sharp increase in housing costs has forced many young adults to delay moving out of their parents'' homes.","pinyin":"","meaning":"Sự gia tăng đột ngột của chi phí nhà ở đã buộc nhiều người trẻ tuổi phải hoãn kế hoạch chuyển ra khỏi nhà cha mẹ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_61_4', 'en-b1-61', 'Cách dùng “escape” (v.) — trốn thoát; thoát khỏi', 'escape from danger  ·  narrow escape  ·  escape injury', 'Thoát khỏi nơi nào đó dùng escape from; tránh được việc gì có thể dùng trực tiếp với danh từ.', 'Họ từ (Word Family): escaped (adj.), escapee (n.), inescapable (adj.) | Đồng nghĩa: get away', '[{"hanzi":"Our rabbit escaped through a small gap in the fence.","pinyin":"","meaning":"Con thỏ của chúng tôi đã trốn thoát qua một khe hở nhỏ trên hàng rào."},{"hanzi":"Accessible parks offer urban residents an escape from crowded streets and opportunities to enjoy nature.","pinyin":"","meaning":"Các công viên dễ tiếp cận mang lại cho cư dân thành phố chốn nghỉ ngơi thoát khỏi những con đường đông đúc và cơ hội tận hưởng thiên nhiên."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_61_1', 'en-b1-61', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
