INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_61_1_8', 'ten_b1_61_1', 'raw', 'I prefer raw carrots because they are so crunchy.', 'I prefer raw carrots because they are so crunchy.', '/rɔː/', 'Tôi thích ăn cà rốt sống hơn vì chúng rất giòn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_61_1_1', 'en-b1-61', 'ten_b1_61_1', 'listening', 'listening', 'I spilled orange juice all over my clean shirt.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi vô tình làm đổ nước cam lênh láng khắp chiếc áo sơ mi sạch của mình.","Cô ấy dùng một chiếc kim băng để kẹp các mảnh vải lại với nhau.","Vui lòng cởi giày trước khi bước lên tấm thảm mới.","Cô ấy chộp lấy chiếc ô rồi chạy về phía xe buýt."]'::jsonb, 0, 'I spilled orange juice all over my clean shirt. → Tôi vô tình làm đổ nước cam lênh láng khắp chiếc áo sơ mi sạch của mình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_61_1_2', 'en-b1-61', 'ten_b1_61_1', 'listening', 'listening', 'This knife is sharp enough to slice tomatoes easily.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhấn nút này để mở cửa nhà để xe.","Chúng tôi đã dịch chuyển bàn ăn lại gần cửa sổ hơn.","Con dao này đủ sắc để cắt cà chua một cách dễ dàng.","Con chim nhỏ nhảy lò cò băng qua lối đi ướt át trong vườn."]'::jsonb, 2, 'This knife is sharp enough to slice tomatoes easily. → Con dao này đủ sắc để cắt cà chua một cách dễ dàng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_61_1_3', 'en-b1-61', 'ten_b1_61_1', 'listening', 'listening', 'We sat in silence as the snow fell outside.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một lớp bụi mỏng phủ lên chiếc kệ.","Xin hãy lau giày lên thảm chùi chân trước khi bước vào.","Chúng tôi ngồi trong sự tĩnh lặng khi tuyết rơi ngoài kia.","Cô ấy dùng một chiếc kim băng để kẹp các mảnh vải lại với nhau."]'::jsonb, 2, 'We sat in silence as the snow fell outside. → Chúng tôi ngồi trong sự tĩnh lặng khi tuyết rơi ngoài kia.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_61_2', 'en-b1-61', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_61_2_1', 'ten_b1_61_2', 'spill', 'Oil spills can damage marine ecosystems and threaten the livelihoods of communities that depend on fishing.', 'Oil spills can damage marine ecosystems and threaten the livelihoods of communities that depend on fishing.', '/spɪl/', 'Sự cố tràn dầu có thể tàn phá hệ sinh thái biển và đe dọa sinh kế của các cộng đồng sống dựa vào đánh bắt thủy hải sản.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_61_2_2', 'ten_b1_61_2', 'sharp', 'A sharp increase in housing costs has forced many young adults to delay moving out of their parents'' homes.', 'A sharp increase in housing costs has forced many young adults to delay moving out of their parents'' homes.', '/ʃɑːrp/', 'Sự gia tăng đột ngột của chi phí nhà ở đã buộc nhiều người trẻ tuổi phải hoãn kế hoạch chuyển ra khỏi nhà cha mẹ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_61_2_3', 'ten_b1_61_2', 'silence', 'Extended periods of silence in classrooms can give students valuable time to reflect on difficult questions.', 'Extended periods of silence in classrooms can give students valuable time to reflect on difficult questions.', '/ˈsaɪləns/', 'Khoảng thời gian im lặng kéo dài trong lớp học có thể mang lại cho học sinh khoảng thời gian quý giá để suy ngẫm về những câu hỏi khó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_61_2_4', 'ten_b1_61_2', 'mat', 'Placing a rubber mat near each entrance can help prevent slips in busy public buildings.', 'Placing a rubber mat near each entrance can help prevent slips in busy public buildings.', '/mæt/', 'Việc đặt một tấm thảm cao su gần mỗi lối vào có thể giúp ngăn ngừa trượt ngã tại các tòa nhà công cộng đông đúc.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_61_2_5', 'ten_b1_61_2', 'press', 'A free press helps citizens understand public affairs and holds those in power accountable.', 'A free press helps citizens understand public affairs and holds those in power accountable.', '/pres/', 'Một nền báo chí tự do giúp công dân hiểu rõ các vấn đề công cộng và buộc những người nắm quyền lực phải chịu trách nhiệm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_61_2_6', 'ten_b1_61_2', 'postpone', 'Local authorities decided to postpone construction until a full assessment of the environmental impact was completed.', 'Local authorities decided to postpone construction until a full assessment of the environmental impact was completed.', '/poʊˈspoʊn/', 'Các nhà chức trách địa phương đã quyết định hoãn việc thi công cho đến khi hoàn thành đánh giá toàn diện về tác động môi trường.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_61_2_1', 'en-b1-61', 'ten_b1_61_2', 'listening', 'listening', 'Oil spills can damage marine ecosystems and threaten the livelihoods of communities that depend on fishing.', NULL, 'Trong câu vừa nghe, từ “spill” mang nghĩa nào sau đây?', '["hai tuần; nửa tháng","cực kỳ ngạc nhiên và buồn bã trước điều gì đó bất ngờ; bị sốc; bàng hoàng","có sọc; có vằn","làm tràn; làm đổ; làm rơi vãi"]'::jsonb, 3, '“spill” (/spɪl/): làm tràn; làm đổ; làm rơi vãi. Câu đầy đủ: Oil spills can damage marine ecosystems and threaten the livelihoods of communities that depend on fishing.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_61_2_2', 'en-b1-61', 'ten_b1_61_2', 'listening', 'listening', 'A sharp increase in housing costs has forced many young adults to delay moving out of their parents'' homes.', NULL, 'Trong câu vừa nghe, từ “sharp” mang nghĩa nào sau đây?', '["cái đĩa lót tách; đĩa đựng chén trà","sắc bén; nhọn","thang cuốn","hoàn toàn; tuyệt đối"]'::jsonb, 1, '“sharp” (/ʃɑːrp/): sắc bén; nhọn. Câu đầy đủ: A sharp increase in housing costs has forced many young adults to delay moving out of their parents'' homes.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
