INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_2', 'en-b1-61', NULL, 'comprehensive_test', 'listening', 'This knife is sharp enough to slice tomatoes easily.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con dao này đủ sắc để cắt cà chua một cách dễ dàng.","Căn bếp chung của chúng tôi trở nên bận rộn vào giờ ăn tối.","Đôi giày đi bộ này phù hợp với những con đường mòn bùn lầy trong rừng.","Chúng tôi đã dịch chuyển bàn ăn lại gần cửa sổ hơn."]'::jsonb, 0, 'This knife is sharp enough to slice tomatoes easily. → Con dao này đủ sắc để cắt cà chua một cách dễ dàng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_3', 'en-b1-61', NULL, 'comprehensive_test', 'listening', 'silence', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự yên lặng; sự im lặng","cừu con; cừu non","sự mua chịu; tín dụng; hình thức trả chậm hoặc vay tiền","hoàn toàn; tuyệt đối"]'::jsonb, 0, 'silence (/ˈsaɪləns/) → sự yên lặng; sự im lặng; làm cho im lặng; dập tắt; bịt miệng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_4', 'en-b1-61', NULL, 'comprehensive_test', 'listening', 'Please wipe your shoes on the mat before entering.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi vô tình làm đổ nước cam lênh láng khắp chiếc áo sơ mi sạch của mình.","Tôi thích ăn cà rốt sống hơn vì chúng rất giòn.","Con dao này đủ sắc để cắt cà chua một cách dễ dàng.","Xin hãy lau giày lên thảm chùi chân trước khi bước vào."]'::jsonb, 3, 'Please wipe your shoes on the mat before entering. → Xin hãy lau giày lên thảm chùi chân trước khi bước vào.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_5', 'en-b1-61', NULL, 'comprehensive_test', 'listening', 'press', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chảy; luân chuyển","nhấn; ấn","thu thập; gom lại","cái trống"]'::jsonb, 1, 'press (/pres/) → nhấn; ấn; giới truyền thông; báo chí; thúc giục; nài nỉ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_6', 'en-b1-61', NULL, 'comprehensive_test', 'listening', 'We postponed our picnic because heavy rain was forecast.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi thích ăn cà rốt sống hơn vì chúng rất giòn.","Chúng tôi đã dịch chuyển bàn ăn lại gần cửa sổ hơn.","Xin hãy gọi điện cho khách sạn để xác nhận lịch đặt phòng của chúng ta hôm nay.","Chúng tôi đã hoãn buổi dã ngoại vì dự báo có mưa lớn."]'::jsonb, 3, 'We postponed our picnic because heavy rain was forecast. → Chúng tôi đã hoãn buổi dã ngoại vì dự báo có mưa lớn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_7', 'en-b1-61', NULL, 'comprehensive_test', 'listening', 'escape', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["không có khả năng; khó xảy ra","trốn thoát; thoát khỏi","lời phàn nàn; đơn khiếu nại; sự khiếu nại","lưới; vật làm bằng lưới"]'::jsonb, 1, 'escape (/ɪˈskeɪp/) → trốn thoát; thoát khỏi; tránh; né; thoát khỏi (điều tồi tệ); sự trốn thoát; sự thoát hiểm', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_8', 'en-b1-61', NULL, 'comprehensive_test', 'listening', 'I prefer raw carrots because they are so crunchy.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy dùng một chiếc kim băng để kẹp các mảnh vải lại với nhau.","Chúng tôi đã hoãn buổi dã ngoại vì dự báo có mưa lớn.","Tôi thích ăn cà rốt sống hơn vì chúng rất giòn.","Chúng tôi trả tiền riêng, sau đó đi bộ về nhà cùng nhau sau bữa trưa."]'::jsonb, 2, 'I prefer raw carrots because they are so crunchy. → Tôi thích ăn cà rốt sống hơn vì chúng rất giòn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
