INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_18', 'en-b1-61', NULL, 'comprehensive_test', 'reading', NULL, 'Oil spills can damage marine ecosystems and threaten the livelihoods of communities that depend on fishing.', 'Dựa vào câu trên, từ “spill” có nghĩa phù hợp nhất là gì?', '["chị dâu; em dâu; chị chồng; em chồng; chị vợ; em vợ","lạc quan; tích cực; có ích","làm tràn; làm đổ; làm rơi vãi","đĩa máy tính; ổ đĩa"]'::jsonb, 2, 'spill: làm tràn; làm đổ; làm rơi vãi; chất lỏng bị đổ; vụ tràn dầu. Dịch cả câu: Sự cố tràn dầu có thể tàn phá hệ sinh thái biển và đe dọa sinh kế của các cộng đồng sống dựa vào đánh bắt thủy hải sản.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_19', 'en-b1-61', NULL, 'comprehensive_test', 'reading', NULL, 'A sharp increase in housing costs has forced many young adults to delay moving out of their parents'' homes.', 'Dựa vào câu trên, từ “sharp” có nghĩa phù hợp nhất là gì?', '["người đưa thư; sứ giả; người truyền tin","tờ rơi; tờ quảng cáo","quả bơ","sắc bén; nhọn"]'::jsonb, 3, 'sharp: sắc bén; nhọn; đột ngột; mạnh (mức độ lớn); nhanh nhạy; sắc sảo. Dịch cả câu: Sự gia tăng đột ngột của chi phí nhà ở đã buộc nhiều người trẻ tuổi phải hoãn kế hoạch chuyển ra khỏi nhà cha mẹ.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_20', 'en-b1-61', NULL, 'comprehensive_test', 'reading', NULL, 'Extended periods of silence in classrooms can give students valuable time to reflect on difficult questions.', 'Dựa vào câu trên, từ “silence” có nghĩa phù hợp nhất là gì?', '["tổ chức; cơ quan; hiệp hội","bị cấm; không được phép","xấu hổ; hổ thẹn","sự yên lặng; sự im lặng"]'::jsonb, 3, 'silence: sự yên lặng; sự im lặng; làm cho im lặng; dập tắt; bịt miệng. Dịch cả câu: Khoảng thời gian im lặng kéo dài trong lớp học có thể mang lại cho học sinh khoảng thời gian quý giá để suy ngẫm về những câu hỏi khó.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_21', 'en-b1-61', NULL, 'comprehensive_test', 'reading', NULL, 'Placing a rubber mat near each entrance can help prevent slips in busy public buildings.', 'Dựa vào câu trên, từ “mat” có nghĩa phù hợp nhất là gì?', '["chiến dịch; cuộc vận động","hiếm khi; ít khi","có hướng dẫn; có người dẫn đường","tấm thảm; chiếu"]'::jsonb, 3, 'mat: tấm thảm; chiếu; làm cho rối bù; làm xoắn tít. Dịch cả câu: Việc đặt một tấm thảm cao su gần mỗi lối vào có thể giúp ngăn ngừa trượt ngã tại các tòa nhà công cộng đông đúc.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_22', 'en-b1-61', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “gối tựa; đệm lót”', '["limit","retire","cushion","sunscreen"]'::jsonb, 2, 'gối tựa; đệm lót → cushion (/ˈkʊʃən/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_23', 'en-b1-61', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lấy đi; tháo ra; cởi ra”', '["editor","gather","disadvantage","remove"]'::jsonb, 3, 'lấy đi; tháo ra; cởi ra → remove (/rɪˈmuːv/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_61_24', 'en-b1-61', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “riêng biệt; tách rời nhau; độc lập”', '["separately","coal","pin","bat"]'::jsonb, 0, 'riêng biệt; tách rời nhau; độc lập → separately (/ˈsepərətli/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-62', 'en', 'Bài 62: Đời sống hằng ngày (14) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3062, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_temporary', 'en-b1-62', 'temporary', '/ˈtempəreri/', 'B1', 'tạm thời; lâm thời', 'adj.', 'temporarily (adv.)', 'Đồng nghĩa: short-term · Trái nghĩa: permanent', 'Nhấn mạnh khoảng thời gian tồn tại có hạn, từ trái nghĩa là permanent.', 'This temporary desk will do until the new one arrives.', NULL, 'Chiếc bàn tạm thời này sẽ dùng tạm cho đến khi chiếc bàn mới được chuyển đến.', '{"wordId":"temporary","ukIpa":"/ˈtemprəri/","usIpa":"/ˈtempəreri/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Lasting for only a limited period of time.","vi":"tạm thời; lâm thời"}],"examples":[{"en":"This temporary desk will do until the new one arrives.","vi":"Chiếc bàn tạm thời này sẽ dùng tạm cho đến khi chiếc bàn mới được chuyển đến.","audioKind":"ex"},{"en":"Temporary accommodation provides essential shelter while families wait for suitable permanent housing to become available.","vi":"Nơi ở tạm thời cung cấp chỗ che chở thiết yếu trong lúc các gia đình chờ đợi nhà ở cố định phù hợp có sẵn.","audioKind":"ex2"}],"collocations":[{"en":"temporary accommodation","vi":"nơi ở tạm thời"},{"en":"temporary job","vi":"công việc tạm thời"},{"en":"temporary solution","vi":"giải pháp tạm thời"},{"en":"temporary closure","vi":"sự đóng cửa tạm thời"}],"wordFamily":["temporarily (adv.)"],"synonyms":["short-term"],"antonyms":["permanent"],"tipVi":"Nhấn mạnh khoảng thời gian tồn tại có hạn, từ trái nghĩa là permanent.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bother', 'en-b1-62', 'bother', '/ˈbɑːðər/', 'B1', 'làm phiền; quấy rầy; bận tâm; phiền phức; phiền toái; rắc rối', 'v.', 'bothered (adj.), bothersome (adj.)', 'Đồng nghĩa: annoy, trouble, disturb', 'Cấu trúc bother to do thường xuất hiện trong câu phủ định hoặc câu hỏi, diễn tả việc nhọc công hay bận lòng làm gì.', 'Please do not bother your sister while she studies.', NULL, 'Xin đừng làm phiền chị gái của bạn trong lúc chị ấy đang học bài.', '{"wordId":"bother","ukIpa":"/ˈbɒðə/","usIpa":"/ˈbɑːðər/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to interrupt, annoy, or worry someone","vi":"làm phiền; quấy rầy"},{"pos":"v.","en":"to make the effort to do something","vi":"bận tâm; phiền phức"},{"pos":"n.","en":"trouble or effort that causes inconvenience","vi":"phiền toái; rắc rối"}],"examples":[{"en":"Please do not bother your sister while she studies.","vi":"Xin đừng làm phiền chị gái của bạn trong lúc chị ấy đang học bài.","audioKind":"ex"},{"en":"Constant notifications can bother students during lessons and reduce their ability to concentrate on complex tasks.","vi":"Những thông báo liên tục có thể quấy rầy học sinh trong giờ học và làm suy giảm khả năng tập trung vào các nhiệm vụ phức tạp của các em.","audioKind":"ex2"}],"collocations":[{"en":"bother someone with something","vi":"làm phiền ai bằng chuyện gì"},{"en":"bother to do something","vi":"bận tâm làm việc gì"},{"en":"cannot be bothered","vi":"lười biếng không muốn bận tâm"},{"en":"a lot of bother","vi":"rất nhiều phiền phức"}],"wordFamily":["bothered (adj.)","bothersome (adj.)"],"synonyms":["annoy","trouble","disturb"],"antonyms":[],"tipVi":"Cấu trúc bother to do thường xuất hiện trong câu phủ định hoặc câu hỏi, diễn tả việc nhọc công hay bận lòng làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unnecessary', 'en-b1-62', 'unnecessary', '/ʌnˈnesəseri/', 'B1', 'không cần thiết; thừa thãi', 'adj.', 'necessary (adj.), unnecessarily (adv.), necessity (n.)', 'Đồng nghĩa: needless, superfluous · Trái nghĩa: necessary, essential', 'Biểu thị "không cần thiết phải làm gì" có thể dùng it is unnecessary to do.', 'Bring a light jacket, but heavy boots are unnecessary.', NULL, 'Mang theo một chiếc áo khoác mỏng, nhưng ủng dày thì không cần thiết.', '{"wordId":"unnecessary","ukIpa":"/ʌnˈnesəsəri/","usIpa":"/ʌnˈnesəseri/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Not needed or serving no useful purpose.","vi":"không cần thiết; thừa thãi"}],"examples":[{"en":"Bring a light jacket, but heavy boots are unnecessary.","vi":"Mang theo một chiếc áo khoác mỏng, nhưng ủng dày thì không cần thiết.","audioKind":"ex"},{"en":"Clear instructions can prevent unnecessary delays and help public services operate more efficiently.","vi":"Các hướng dẫn rõ ràng có thể ngăn ngừa sự chậm trễ không cần thiết và giúp các dịch vụ công hoạt động hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"unnecessary expense","vi":"chi phí không cần thiết"},{"en":"unnecessary stress","vi":"áp lực không cần thiết"},{"en":"avoid unnecessary delays","vi":"tránh những sự chậm trễ không đáng có"}],"wordFamily":["necessary (adj.)","unnecessarily (adv.)","necessity (n.)"],"synonyms":["needless","superfluous"],"antonyms":["necessary","essential"],"tipVi":"Biểu thị \"không cần thiết phải làm gì\" có thể dùng it is unnecessary to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spoil', 'en-b1-62', 'spoil', '/spɔɪl/', 'B1', 'làm hỏng; phá hỏng; nuông chiều; cưng chiều quá mức; làm ôi thiu', 'v.', 'spoiled (adj.), spoilt (adj.), spoilage (n.)', 'Đồng nghĩa: ruin', 'Dạng quá khứ và quá khứ phân từ đều có thể dùng spoiled hoặc spoilt.', 'Please don''t spoil the surprise by telling your sister.', NULL, 'Xin đừng làm hỏng điều bất ngờ bằng cách kể cho chị bạn nghe nhé.', '{"wordId":"spoil","ukIpa":"/spɔɪl/","usIpa":"/spɔɪl/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To make something less enjoyable, useful, or attractive.","vi":"làm hỏng; phá hỏng"},{"pos":"v.","en":"To give someone excessive attention or everything they want.","vi":"nuông chiều; cưng chiều quá mức"},{"pos":"v.","en":"To become, or make food become, unfit to eat.","vi":"làm hỏng; làm ôi thiu"}],"examples":[{"en":"Please don''t spoil the surprise by telling your sister.","vi":"Xin đừng làm hỏng điều bất ngờ bằng cách kể cho chị bạn nghe nhé.","audioKind":"ex"},{"en":"Poorly planned construction can spoil natural landscapes and reduce their appeal to both residents and tourists.","vi":"Công trình xây dựng được quy hoạch kém có thể phá hủy cảnh quan thiên nhiên và làm giảm sức hút của chúng đối với cả cư dân lẫn du khách.","audioKind":"ex2"}],"collocations":[{"en":"spoil the surprise","vi":"làm hỏng điều bất ngờ"},{"en":"spoil a child","vi":"chiều chuộng trẻ con"},{"en":"spoil your appetite","vi":"làm mất cảm giác thèm ăn"}],"wordFamily":["spoiled (adj.)","spoilt (adj.)","spoilage (n.)"],"synonyms":["ruin"],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ đều có thể dùng spoiled hoặc spoilt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_underneath', 'en-b1-62', 'underneath', '/ˌʌndɚˈniːθ/', 'B1', 'ở dưới; bên dưới; ở phía dưới; ở phần đáy', 'prep.', NULL, 'Đồng nghĩa: under, beneath, below · Trái nghĩa: above', 'Theo sau là danh từ thì đóng vai trò là giới từ; đứng độc lập thì đóng vai trò là phó từ.', 'Your slippers are underneath the chair by the bed.', NULL, 'Đôi dép của bạn ở dưới chiếc ghế cạnh giường kìa.', '{"wordId":"underneath","ukIpa":"/ˌʌndəˈniːθ/","usIpa":"/ˌʌndɚˈniːθ/","cefr":"B1","topic":"daily","senses":[{"pos":"prep.","en":"Directly below something, often covered or hidden by it.","vi":"ở dưới; bên dưới"},{"pos":"adv.","en":"In a lower position, often beneath a covering.","vi":"ở phía dưới; ở phần đáy"}],"examples":[{"en":"Your slippers are underneath the chair by the bed.","vi":"Đôi dép của bạn ở dưới chiếc ghế cạnh giường kìa.","audioKind":"ex"},{"en":"Insulation installed underneath floors can reduce heat loss and improve energy efficiency in older homes.","vi":"Lớp vật liệu cách nhiệt lắp đặt dưới sàn nhà có thể làm giảm thất thoát nhiệt và nâng cao hiệu quả năng lượng trong những ngôi nhà cũ.","audioKind":"ex2"}],"collocations":[{"en":"underneath the bed","vi":"ở dưới gầm giường"},{"en":"underneath the surface","vi":"dưới bề mặt"},{"en":"hidden underneath","vi":"ẩn giấu bên dưới"}],"wordFamily":[],"synonyms":["under","beneath","below"],"antonyms":["above"],"tipVi":"Theo sau là danh từ thì đóng vai trò là giới từ; đứng độc lập thì đóng vai trò là phó từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grill', 'en-b1-62', 'grill', '/ɡrɪl/', 'B1', 'nướng bằng vỉ; vỉ nướng; lò nướng; gặng hỏi; tra khảo', 'v.', 'grilled (adj.), grilling (n.)', NULL, 'Trong tiếng Anh-Anh grill thường chỉ việc gia nhiệt từ trên xuống; tiếng Anh-Mỹ thường chỉ việc nướng từ dưới lên.', 'We grilled some peppers and ate them with rice.', NULL, 'Chúng tôi đã nướng một ít ớt chuông và ăn kèm với cơm.', '{"wordId":"grill","ukIpa":"/ɡrɪl/","usIpa":"/ɡrɪl/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To cook food using direct heat from above or below.","vi":"nướng bằng vỉ"},{"pos":"n.","en":"A cooking device that exposes food to direct heat.","vi":"vỉ nướng; lò nướng"},{"pos":"v.","en":"To question someone intensely, often for a long time.","vi":"gặng hỏi; tra khảo"}],"examples":[{"en":"We grilled some peppers and ate them with rice.","vi":"Chúng tôi đã nướng một ít ớt chuông và ăn kèm với cơm.","audioKind":"ex"},{"en":"Grilling vegetables with little oil can be a practical way to prepare healthier meals at home.","vi":"Nướng rau củ với một chút dầu là một cách thiết thực để chuẩn bị các bữa ăn lành mạnh hơn tại nhà.","audioKind":"ex2"}],"collocations":[{"en":"grilled fish","vi":"cá nướng"},{"en":"a charcoal grill","vi":"lò nướng than hoa"},{"en":"under the grill","vi":"đặt dưới vỉ nướng"},{"en":"grill someone about something","vi":"tra hỏi ai về vấn đề gì"}],"wordFamily":["grilled (adj.)","grilling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh grill thường chỉ việc gia nhiệt từ trên xuống; tiếng Anh-Mỹ thường chỉ việc nướng từ dưới lên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ruin', 'en-b1-62', 'ruin', '/ˈruːɪn/', 'B1', 'làm hỏng; tàn phá; đồ nát; tàn tích; sự sụp đổ; sự phá sản', 'v.', 'ruined (adj.), ruinous (adj.)', 'Đồng nghĩa: destroy, wreck · Trái nghĩa: restore', 'Biểu đạt kiến trúc tàn tích thường dùng số nhiều ruins, ví dụ ancient ruins.', 'Heavy rain ruined the picnic we had planned.', NULL, 'Cơn mưa lớn đã làm hỏng buổi dã ngoại mà chúng tôi đã lên kế hoạch.', '{"wordId":"ruin","ukIpa":"/ˈruːɪn/","usIpa":"/ˈruːɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to damage something so badly that it loses its value","vi":"làm hỏng; tàn phá"},{"pos":"n.","en":"the remains of a building that has been badly damaged","vi":"đồ nát; tàn tích"},{"pos":"n.","en":"the complete loss of money, success, or good condition","vi":"sự sụp đổ; sự phá sản"}],"examples":[{"en":"Heavy rain ruined the picnic we had planned.","vi":"Cơn mưa lớn đã làm hỏng buổi dã ngoại mà chúng tôi đã lên kế hoạch.","audioKind":"ex"},{"en":"Uncontrolled tourism can ruin fragile natural habitats unless visitor numbers and construction activities are carefully managed.","vi":"Du lịch không kiểm soát có thể tàn phá các môi trường sống tự nhiên mỏng manh trừ khi số lượng du khách và hoạt động xây dựng được quản lý cẩn thận.","audioKind":"ex2"}],"collocations":[{"en":"ruin someone''s plans","vi":"làm hỏng kế hoạch của ai đó"},{"en":"ancient ruins","vi":"tàn tích cổ"},{"en":"financial ruin","vi":"sự phá sản về tài chính"},{"en":"in ruins","vi":"thành đống đổ nát"}],"wordFamily":["ruined (adj.)","ruinous (adj.)"],"synonyms":["destroy","wreck"],"antonyms":["restore"],"tipVi":"Biểu đạt kiến trúc tàn tích thường dùng số nhiều ruins, ví dụ ancient ruins.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grocery', 'en-b1-62', 'grocery', '/ˈɡroʊsəri/', 'B1', 'hàng thực phẩm và nhu yếu phẩm; cửa hàng tạp hóa', 'n.', 'grocer (n.)', NULL, 'Hàng thực phẩm dùng số nhiều groceries; làm định từ dùng grocery.', 'I carried two bags of groceries into the kitchen.', NULL, 'Tôi xách hai túi hàng tạp hóa bước vào nhà bếp.', '{"wordId":"grocery","ukIpa":"/ˈɡrəʊsəri/","usIpa":"/ˈɡroʊsəri/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Food and household supplies bought at a shop; usually plural.","vi":"hàng thực phẩm và nhu yếu phẩm"},{"pos":"n.","en":"A shop selling food and basic household supplies.","vi":"cửa hàng tạp hóa"}],"examples":[{"en":"I carried two bags of groceries into the kitchen.","vi":"Tôi xách hai túi hàng tạp hóa bước vào nhà bếp.","audioKind":"ex"},{"en":"Rising grocery prices place considerable pressure on households that already spend most of their income on essentials.","vi":"Giá thực phẩm tăng cao gây ra áp lực đáng kể cho các hộ gia đình vốn đã dùng phần lớn thu nhập cho các nhu yếu phẩm.","audioKind":"ex2"}],"collocations":[{"en":"grocery shopping","vi":"mua sắm tạp hóa"},{"en":"grocery store","vi":"cửa hàng tạp hóa"},{"en":"grocery bill","vi":"hóa đơn tiền tạp hóa"}],"wordFamily":["grocer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Hàng thực phẩm dùng số nhiều groceries; làm định từ dùng grocery.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amuse', 'en-b1-62', 'amuse', '/əˈmjuːz/', 'B1', 'làm buồn cười; làm cho cười; làm cho giải trí; làm cho khuây khỏa', 'v.', 'amusement (n.), amusing (adj.), amused (adj.)', 'Đồng nghĩa: entertain, delight · Trái nghĩa: bore', 'amused miêu tả cảm xúc của con người; amusing miêu tả sự vật thú vị.', 'His silly dance amused everyone waiting in the kitchen.', NULL, 'Điệu nhảy ngớ ngẩn của anh ấy đã làm mọi người đang đợi trong bếp cười thích thú.', '{"wordId":"amuse","ukIpa":"/əˈmjuːz/","usIpa":"/əˈmjuːz/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To make someone smile or laugh.","vi":"làm buồn cười; làm cho cười"},{"pos":"v.","en":"To keep someone pleasantly occupied.","vi":"làm cho giải trí; làm cho khuây khỏa"}],"examples":[{"en":"His silly dance amused everyone waiting in the kitchen.","vi":"Điệu nhảy ngớ ngẩn của anh ấy đã làm mọi người đang đợi trong bếp cười thích thú.","audioKind":"ex"},{"en":"Interactive museum exhibits can amuse young visitors while helping them understand complex scientific ideas.","vi":"Các triển lãm bảo tàng tương tác vừa có thể mang lại sự giải trí cho các du khách nhỏ tuổi vừa giúp họ hiểu các khái niệm khoa học phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"amuse an audience","vi":"làm khán giả vui cười"},{"en":"amuse yourself","vi":"tự giải trí"},{"en":"keep someone amused","vi":"giữ cho ai đó không bị nhàm chán"}],"wordFamily":["amusement (n.)","amusing (adj.)","amused (adj.)"],"synonyms":["entertain","delight"],"antonyms":["bore"],"tipVi":"amused miêu tả cảm xúc của con người; amusing miêu tả sự vật thú vị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recipe', 'en-b1-62', 'recipe', '/ˈresəpi/', 'B1', 'công thức nấu ăn; bí quyết; phương sách', 'n.', NULL, NULL, 'recipe chỉ cách nấu ăn; menu là thực đơn, prescription là đơn thuốc.', 'This soup recipe needs only a few simple ingredients.', NULL, 'Công thức món súp này chỉ cần một vài nguyên liệu đơn giản.', '{"wordId":"recipe","ukIpa":"/ˈresəpi/","usIpa":"/ˈresəpi/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"instructions explaining how to prepare and cook a dish","vi":"công thức nấu ăn"},{"pos":"n.","en":"a method or situation likely to produce a particular result","vi":"bí quyết; phương sách"}],"examples":[{"en":"This soup recipe needs only a few simple ingredients.","vi":"Công thức món súp này chỉ cần một vài nguyên liệu đơn giản.","audioKind":"ex"},{"en":"Investment in teacher training and accessible learning materials provides a recipe for educational success.","vi":"Đầu tư vào đào tạo giáo viên và tài liệu học tập dễ tiếp cận chính là bí quyết mang lại thành công trong giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"follow a recipe","vi":"làm theo công thức nấu ăn"},{"en":"a recipe for success","vi":"bí quyết thành công"},{"en":"a recipe for disaster","vi":"công thức dẫn đến thảm họa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"recipe chỉ cách nấu ăn; menu là thực đơn, prescription là đơn thuốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_locker', 'en-b1-62', 'locker', '/ˈlɑːkər/', 'B1', 'tủ gửi đồ; tủ có khóa (để đồ cá nhân)', 'n.', 'lock (n.), lock (v.), lockable (adj.)', NULL, 'Locker thường là tủ nhỏ để cất giữ đồ đạc cá nhân, không dùng để chỉ người có khóa.', 'I left my trainers in a locker at the gym.', NULL, 'Tôi để giày tập trong tủ đồ ở phòng gym.', '{"wordId":"locker","ukIpa":"/ˈlɒkə/","usIpa":"/ˈlɑːkər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"a small cupboard for keeping personal belongings secure","vi":"tủ gửi đồ; tủ có khóa (để đồ cá nhân)"}],"examples":[{"en":"I left my trainers in a locker at the gym.","vi":"Tôi để giày tập trong tủ đồ ở phòng gym.","audioKind":"ex"},{"en":"Providing each student with a locker can reduce the weight of bags carried around school.","vi":"Việc cung cấp cho mỗi học sinh một tủ đựng đồ có thể làm giảm trọng lượng túi xách phải mang theo ở trường.","audioKind":"ex2"}],"collocations":[{"en":"locker room","vi":"phòng thay đồ"},{"en":"school locker","vi":"tủ đựng đồ ở trường"},{"en":"locker key","vi":"chìa khóa tủ đồ"}],"wordFamily":["lock (n.)","lock (v.)","lockable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Locker thường là tủ nhỏ để cất giữ đồ đạc cá nhân, không dùng để chỉ người có khóa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lately', 'en-b1-62', 'lately', '/ˈleɪtli/', 'B1', 'gần đây; dạo này', 'adv.', 'late (adj.), lateness (n.)', 'Đồng nghĩa: recently', 'Thường đi với thì hiện tại hoàn thành; tránh nhầm lẫn với từ late chỉ sự muộn màng.', 'Have you been sleeping well lately, or feeling tired?', NULL, 'Dạo này bạn ngủ có ngon giấc không, hay cảm thấy mệt mỏi?', '{"wordId":"lately","ukIpa":"/ˈleɪtli/","usIpa":"/ˈleɪtli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"during the recent period up to the present","vi":"gần đây; dạo này"}],"examples":[{"en":"Have you been sleeping well lately, or feeling tired?","vi":"Dạo này bạn ngủ có ngon giấc không, hay cảm thấy mệt mỏi?","audioKind":"ex"},{"en":"Lately, researchers have paid greater attention to the relationship between access to green spaces and mental health.","vi":"Gần đây, các nhà nghiên cứu đã chú ý nhiều hơn đến mối quan hệ giữa khả năng tiếp cận không gian xanh và sức khỏe tinh thần.","audioKind":"ex2"}],"collocations":[{"en":"have lately become","vi":"dạo gần đây đã trở thành"},{"en":"until lately","vi":"cho đến tận gần đây"},{"en":"more often lately","vi":"gần đây thường xuyên hơn"}],"wordFamily":["late (adj.)","lateness (n.)"],"synonyms":["recently"],"antonyms":[],"tipVi":"Thường đi với thì hiện tại hoàn thành; tránh nhầm lẫn với từ late chỉ sự muộn màng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clip', 'en-b1-62', 'clip', '/klɪp/', 'B1', 'cái kẹp; kẹp giấy; đoạn phim; đoạn ghi âm ngắn; kẹp lại; cắt ngắn; tỉa', 'n.', 'clipping (n.), clippers (n.)', NULL, 'Kẹp thứ gì vào đâu dùng clip onto; đoạn video ngắn cũng được gọi là clip.', 'She used a clip to hold her hair back.', NULL, 'Cô ấy dùng một chiếc kẹp để vén tóc ra phía sau.', '{"wordId":"clip","ukIpa":"/klɪp/","usIpa":"/klɪp/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A small object that holds things together or in place.","vi":"cái kẹp; kẹp giấy"},{"pos":"n.","en":"A short section of a film or audio recording.","vi":"đoạn phim; đoạn ghi âm ngắn"},{"pos":"v.","en":"To fasten with a clip, or cut something shorter.","vi":"kẹp lại; cắt ngắn; tỉa"}],"examples":[{"en":"She used a clip to hold her hair back.","vi":"Cô ấy dùng một chiếc kẹp để vén tóc ra phía sau.","audioKind":"ex"},{"en":"Teachers can use a short video clip to introduce complex scientific concepts before a classroom discussion.","vi":"Giáo viên có thể sử dụng một đoạn video ngắn để giới thiệu các khái niệm khoa học phức tạp trước khi thảo luận trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"paper clip","vi":"kẹp giấy"},{"en":"video clip","vi":"đoạn video ngắn"},{"en":"clip your nails","vi":"cắt móng tay"},{"en":"clip something onto","vi":"kẹp cái gì đó vào"}],"wordFamily":["clipping (n.)","clippers (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Kẹp thứ gì vào đâu dùng clip onto; đoạn video ngắn cũng được gọi là clip.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mop', 'en-b1-62', 'mop', '/mɑːp/', 'B1', 'cây lau nhà; giẻ lau nhà; lau chùi (sàn nhà); thấm (chất lỏng)', 'n.', NULL, NULL, 'Động từ quá khứ mopped, phân từ mopping, đều gấp đôi chữ p.', 'I used a mop to clean the muddy kitchen floor.', NULL, 'Tôi dùng cây lau nhà để làm sạch sàn bếp dính đầy bùn.', '{"wordId":"mop","ukIpa":"/mɒp/","usIpa":"/mɑːp/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A long-handled tool for washing floors","vi":"cây lau nhà; giẻ lau nhà"},{"pos":"v.","en":"To clean a surface or remove liquid with absorbent material","vi":"lau chùi (sàn nhà); thấm (chất lỏng)"}],"examples":[{"en":"I used a mop to clean the muddy kitchen floor.","vi":"Tôi dùng cây lau nhà để làm sạch sàn bếp dính đầy bùn.","audioKind":"ex"},{"en":"Staff should mop shared floors regularly to maintain hygiene in schools and other public buildings.","vi":"Nhân viên nên thường xuyên lau sàn chung để duy trì vệ sinh trong trường học và các tòa nhà công cộng khác.","audioKind":"ex2"}],"collocations":[{"en":"mop the floor","vi":"lau sàn nhà"},{"en":"mop up a spill","vi":"thấm khô chất lỏng bị đổ"},{"en":"a mop and bucket","vi":"cây lau nhà và xô"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ quá khứ mopped, phân từ mopping, đều gấp đôi chữ p.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_baby-sitter', 'en-b1-62', 'baby-sitter', '/ˈbeɪbisɪtər/', 'B1', 'người trông trẻ; bảo mẫu tạm thời', 'n.', 'babysit (v.), babysitting (n.)', 'Đồng nghĩa: sitter', 'Hiện đại thường viết là babysitter; thường chỉ người tạm thời trông nom trẻ em.', 'The baby-sitter read our daughter a story before bed.', NULL, 'Người trông trẻ đã đọc cho con gái chúng tôi nghe một câu chuyện trước khi đi ngủ.', '{"wordId":"baby-sitter","ukIpa":"/ˈbeɪbisɪtə/","usIpa":"/ˈbeɪbisɪtər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Someone who temporarily looks after children while their parents are away","vi":"người trông trẻ; bảo mẫu tạm thời"}],"examples":[{"en":"The baby-sitter read our daughter a story before bed.","vi":"Người trông trẻ đã đọc cho con gái chúng tôi nghe một câu chuyện trước khi đi ngủ.","audioKind":"ex"},{"en":"Hiring a reliable baby-sitter can help parents balance occasional evening work with their family responsibilities.","vi":"Việc thuê một người trông trẻ đáng tin cậy có thể giúp các bậc cha mẹ cân bằng giữa công việc buổi tối không thường xuyên và trách nhiệm gia đình.","audioKind":"ex2"}],"collocations":[{"en":"hire a baby-sitter","vi":"thuê người trông trẻ"},{"en":"reliable baby-sitter","vi":"người trông trẻ đáng tin cậy"},{"en":"experienced baby-sitter","vi":"người trông trẻ có kinh nghiệm"}],"wordFamily":["babysit (v.)","babysitting (n.)"],"synonyms":["sitter"],"antonyms":[],"tipVi":"Hiện đại thường viết là babysitter; thường chỉ người tạm thời trông nom trẻ em.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_striped', 'en-b1-62', 'striped', '/straɪpt/', 'B1', 'có sọc; có vằn', 'adj.', 'stripe (n.), stripe (v.)', 'Trái nghĩa: plain', 'striped có nghĩa là có sọc; quá khứ của strip là stripped.', 'She wore a striped shirt and dark blue jeans.', NULL, 'Cô ấy mặc một chiếc áo sơ mi sọc và quần jean xanh đậm.', '{"wordId":"striped","ukIpa":"/straɪpt/","usIpa":"/straɪpt/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Having a pattern of long, narrow bands.","vi":"có sọc; có vằn"}],"examples":[{"en":"She wore a striped shirt and dark blue jeans.","vi":"Cô ấy mặc một chiếc áo sơ mi sọc và quần jean xanh đậm.","audioKind":"ex"},{"en":"The striped coats of certain animals may help them avoid detection in their natural habitats.","vi":"Bộ lông có sọc của một số loài động vật có thể giúp chúng tránh bị phát hiện trong môi trường sống tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"striped shirt","vi":"áo sơ mi sọc"},{"en":"striped fabric","vi":"vải sọc"},{"en":"striped pattern","vi":"họa tiết sọc"}],"wordFamily":["stripe (n.)","stripe (v.)"],"synonyms":[],"antonyms":["plain"],"tipVi":"striped có nghĩa là có sọc; quá khứ của strip là stripped.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cheek', 'en-b1-62', 'cheek', '/tʃiːk/', 'B1', 'má; gò má; sự vô lễ; sự hỗn xược', 'n.', 'cheeky (adj.), cheekily (adv.)', NULL, 'Nghĩa má (cheek) là danh từ đếm được; nghĩa sự vô lễ thường là danh từ không đếm được và hay dùng trong tiếng Anh-Anh khẩu ngữ.', 'A cold raindrop landed on my cheek outside.', NULL, 'Một giọt mưa lạnh buốt rơi xuống má tôi khi tôi đang ở ngoài trời.', '{"wordId":"cheek","ukIpa":"/tʃiːk/","usIpa":"/tʃiːk/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"either side of the face below the eyes","vi":"má; gò má"},{"pos":"n.","en":"rude behaviour that shows a lack of respect","vi":"sự vô lễ; sự hỗn xược"}],"examples":[{"en":"A cold raindrop landed on my cheek outside.","vi":"Một giọt mưa lạnh buốt rơi xuống má tôi khi tôi đang ở ngoài trời.","audioKind":"ex"},{"en":"Protective clothing should cover exposed areas, including the cheeks, when people work in extremely cold environments.","vi":"Quần áo bảo hộ nên che kín các vùng cơ thể bị hở, bao gồm cả vùng má, khi làm việc trong môi trường cực kỳ lạnh giá.","audioKind":"ex2"}],"collocations":[{"en":"rosy cheeks","vi":"má hồng"},{"en":"a kiss on the cheek","vi":"một nụ hôn lên má"},{"en":"have the cheek to","vi":"cả gan làm gì"},{"en":"cheek by cheek","vi":"áp sát má vào nhau"}],"wordFamily":["cheeky (adj.)","cheekily (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa má (cheek) là danh từ đếm được; nghĩa sự vô lễ thường là danh từ không đếm được và hay dùng trong tiếng Anh-Anh khẩu ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slide', 'en-b1-62', 'slide', '/slaɪd/', 'B1', 'trượt; di chuyển trơn tru; trang chiếu; bản trình chiếu; cầu tuột; cái cầu trượt', 'v.', 'sliding (adj.), slider (n.)', NULL, 'Dạng quá khứ và quá khứ phân từ của động từ slide đều là slid.', 'She slid the plate across the table towards me.', NULL, 'Cô ấy đẩy chiếc đĩa trượt trên mặt bàn về phía tôi.', '{"wordId":"slide","ukIpa":"/slaɪd/","usIpa":"/slaɪd/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to move smoothly across a surface without lifting","vi":"trượt; di chuyển trơn tru"},{"pos":"n.","en":"a single image or page shown during a presentation","vi":"trang chiếu; bản trình chiếu"},{"pos":"n.","en":"a sloping structure that children slide down","vi":"cầu tuột; cái cầu trượt"}],"examples":[{"en":"She slid the plate across the table towards me.","vi":"Cô ấy đẩy chiếc đĩa trượt trên mặt bàn về phía tôi.","audioKind":"ex"},{"en":"Teachers can use a carefully designed slide to explain complex scientific processes more clearly.","vi":"Giáo viên có thể sử dụng một trang chiếu được thiết kế cẩn thận để giải thích các quá trình khoa học phức tạp một cách rõ ràng hơn.","audioKind":"ex2"}],"collocations":[{"en":"slide across","vi":"trượt qua"},{"en":"slide into","vi":"trượt vào trong"},{"en":"presentation slide","vi":"slide thuyết trình"},{"en":"go down a slide","vi":"trượt cầu tuột"}],"wordFamily":["sliding (adj.)","slider (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ của động từ slide đều là slid.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_torch', 'en-b1-62', 'torch', '/tɔːrtʃ/', 'B1', 'đèn pin; ngọn đuốc', 'n.', NULL, 'Đồng nghĩa: flashlight', 'Đèn pin tiếng Anh-Anh là torch, còn tiếng Anh-Mỹ là flashlight.', 'I used a torch to find my missing keys.', NULL, 'Tôi dùng đèn pin để tìm những chiếc chìa khóa bị mất.', '{"wordId":"torch","ukIpa":"/tɔːtʃ/","usIpa":"/tɔːrtʃ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A small electric light carried in the hand.","vi":"đèn pin"},{"pos":"n.","en":"A stick with burning material at one end, providing light.","vi":"ngọn đuốc"}],"examples":[{"en":"I used a torch to find my missing keys.","vi":"Tôi dùng đèn pin để tìm những chiếc chìa khóa bị mất.","audioKind":"ex"},{"en":"Hikers should carry a torch and spare batteries when exploring remote areas after sunset.","vi":"Người đi bộ đường dài nên mang theo đèn pin và pin dự phòng khi khám phá các khu vực hẻo lánh sau khi mặt trời lặn.","audioKind":"ex2"}],"collocations":[{"en":"switch on a torch","vi":"bật đèn pin"},{"en":"a torch beam","vi":"luồng sáng đèn pin"},{"en":"carry a torch","vi":"mang theo đuốc"},{"en":"a flaming torch","vi":"ngọn đuốc cháy rực"}],"wordFamily":[],"synonyms":["flashlight"],"antonyms":[],"tipVi":"Đèn pin tiếng Anh-Anh là torch, còn tiếng Anh-Mỹ là flashlight.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crack', 'en-b1-62', 'crack', '/kræk/', 'B1', 'vết nứt; vết rạn; làm nứt; làm rạn; nứt ra; tiếng nứt đanh; tiếng nổ giòn', 'n.', 'cracked (adj.), cracking (n.)', 'Đồng nghĩa: split', 'crack thường chỉ việc nứt mà chưa vỡ hẳn; shatter nhấn mạnh việc vỡ vụn thành nhiều mảnh.', 'There''s a thin crack across my favourite blue mug.', NULL, 'Có một vết nứt mảnh chạy ngang qua chiếc cốc màu xanh yêu thích của tôi.', '{"wordId":"crack","ukIpa":"/kræk/","usIpa":"/kræk/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A narrow break in a surface or solid object","vi":"vết nứt; vết rạn"},{"pos":"v.","en":"Break or cause something to break without completely separating","vi":"làm nứt; làm rạn; nứt ra"},{"pos":"n.","en":"A sudden sharp sound, like something breaking","vi":"tiếng nứt đanh; tiếng nổ giòn"}],"examples":[{"en":"There''s a thin crack across my favourite blue mug.","vi":"Có một vết nứt mảnh chạy ngang qua chiếc cốc màu xanh yêu thích của tôi.","audioKind":"ex"},{"en":"Engineers discovered a crack in the bridge during a routine inspection and recommended immediate repairs.","vi":"Các kỹ sư đã phát hiện ra một vết nứt trên cầu trong một lần kiểm tra định kỳ và kiến nghị sửa chữa ngay lập tức.","audioKind":"ex2"}],"collocations":[{"en":"a crack in the wall","vi":"vết nứt trên tường"},{"en":"crack an egg","vi":"đập trứng"},{"en":"a loud crack","vi":"tiếng nổ lớn"}],"wordFamily":["cracked (adj.)","cracking (n.)"],"synonyms":["split"],"antonyms":[],"tipVi":"crack thường chỉ việc nứt mà chưa vỡ hẳn; shatter nhấn mạnh việc vỡ vụn thành nhiều mảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_row', 'en-b1-62', 'row', '/roʊ/', 'B1', 'hàng; dãy; chèo thuyền; cuộc cãi vã; sự la ó', 'n.', 'rower (n.), rowing (n.)', NULL, 'Nghĩa hàng ghế và chèo thuyền đọc là /rəʊ/; nghĩa tranh cãi cả Anh và Mỹ đều đọc là /raʊ/.', 'We found two empty seats in the front row.', NULL, 'Chúng tôi tìm thấy hai chỗ ngồi trống ở hàng ghế đầu.', '{"wordId":"row","ukIpa":"/rəʊ/","usIpa":"/roʊ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"people or things arranged in a straight line","vi":"hàng; dãy"},{"pos":"v.","en":"to move a boat through water using oars","vi":"chèo thuyền"},{"pos":"n.","en":"a noisy argument or loud disturbance","vi":"cuộc cãi vã; sự la ó"}],"examples":[{"en":"We found two empty seats in the front row.","vi":"Chúng tôi tìm thấy hai chỗ ngồi trống ở hàng ghế đầu.","audioKind":"ex"},{"en":"Planting a row of trees beside busy roads can help reduce noise and improve local air quality.","vi":"Việc trồng một hàng cây bên cạnh các con đường bận rộn có thể giúp giảm tiếng ồn và cải thiện chất lượng không khí địa phương.","audioKind":"ex2"}],"collocations":[{"en":"in a row","vi":"liên tiếp; xếp thành hàng"},{"en":"front row","vi":"hàng ghế đầu"},{"en":"row a boat","vi":"chèo thuyền"},{"en":"have a row","vi":"cãi nhau"}],"wordFamily":["rower (n.)","rowing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa hàng ghế và chèo thuyền đọc là /rəʊ/; nghĩa tranh cãi cả Anh và Mỹ đều đọc là /raʊ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fairly', 'en-b1-62', 'fairly', '/ˈferli/', 'B1', 'khá; tương đối; công bằng; hợp lý', 'adv.', 'fair (adj.), fairness (n.), unfairly (adv.)', 'Đồng nghĩa: reasonably · Trái nghĩa: unfairly', 'Khi chỉ mức độ, fairly nhẹ hơn very; fairly good nghĩa là khá tốt chứ không phải xuất sắc.', 'The walk home was fairly short and very pleasant.', NULL, 'Quãng đường đi bộ về nhà khá ngắn và rất dễ chịu.', '{"wordId":"fairly","ukIpa":"/ˈfeəli/","usIpa":"/ˈferli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"to a moderate degree, but not very","vi":"khá; tương đối"},{"pos":"adv.","en":"in a way that treats people equally and reasonably","vi":"công bằng; hợp lý"}],"examples":[{"en":"The walk home was fairly short and very pleasant.","vi":"Quãng đường đi bộ về nhà khá ngắn và rất dễ chịu.","audioKind":"ex"},{"en":"Schools should distribute resources fairly so that students from disadvantaged backgrounds receive the support they need.","vi":"Các trường học nên phân bổ nguồn lực một cách công bằng để học sinh có hoàn cảnh khó khăn nhận được sự hỗ trợ cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"fairly easy","vi":"khá dễ"},{"en":"fairly common","vi":"khá phổ biến"},{"en":"treat people fairly","vi":"đối xử công bằng với mọi người"},{"en":"distribute resources fairly","vi":"phân bổ tài nguyên công bằng"}],"wordFamily":["fair (adj.)","fairness (n.)","unfairly (adv.)"],"synonyms":["reasonably"],"antonyms":["unfairly"],"tipVi":"Khi chỉ mức độ, fairly nhẹ hơn very; fairly good nghĩa là khá tốt chứ không phải xuất sắc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tape', 'en-b1-62', 'tape', '/teɪp/', 'B1', 'băng dính; băng keo; băng từ; băng ghi âm; dán bằng băng dính', 'n.', NULL, NULL, 'Băng dính thường không đếm được; một cuộn băng dính nói là a roll of tape.', 'I sealed the parcel with a strip of tape.', NULL, 'Tôi đã niêm phong bưu kiện bằng một đoạn băng dính.', '{"wordId":"tape","ukIpa":"/teɪp/","usIpa":"/teɪp/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A narrow sticky strip used to attach or seal things.","vi":"băng dính; băng keo"},{"pos":"n.","en":"A magnetic strip used to record sound, images, or data.","vi":"băng từ; băng ghi âm"},{"pos":"v.","en":"Attach or secure something using sticky tape.","vi":"dán bằng băng dính"}],"examples":[{"en":"I sealed the parcel with a strip of tape.","vi":"Tôi đã niêm phong bưu kiện bằng một đoạn băng dính.","audioKind":"ex"},{"en":"Older interviews stored on magnetic tape should be digitised to preserve valuable records for future historical research.","vi":"Những cuộc phỏng vấn cũ được lưu trữ trên băng từ nên được số hóa để bảo lưu các tài liệu quý giá cho nghiên cứu lịch sử trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"adhesive tape","vi":"băng dính"},{"en":"magnetic tape","vi":"băng từ"},{"en":"a roll of tape","vi":"một cuộn băng dính"},{"en":"tape measure","vi":"thước dây"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Băng dính thường không đếm được; một cuộn băng dính nói là a roll of tape.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wallpaper', 'en-b1-62', 'wallpaper', '/ˈwɔːlpeɪpər/', 'B1', 'giấy dán tường; hình nền máy tính; ảnh nền; dán giấy tường', 'n.', NULL, NULL, 'wallpaper thường là danh từ không đếm được; một cuộn giấy dán tường dùng là a roll of wallpaper.', 'We chose pale green wallpaper for our small bedroom.', NULL, 'Chúng tôi đã chọn giấy dán tường màu xanh nhạt cho phòng ngủ nhỏ của mình.', '{"wordId":"wallpaper","ukIpa":"/ˈwɔːlpeɪpə/","usIpa":"/ˈwɔːlpeɪpər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"decorative paper used to cover interior walls","vi":"giấy dán tường"},{"pos":"n.","en":"an image displayed behind icons on a screen","vi":"hình nền máy tính; ảnh nền"},{"pos":"v.","en":"to cover walls with decorative paper","vi":"dán giấy tường"}],"examples":[{"en":"We chose pale green wallpaper for our small bedroom.","vi":"Chúng tôi đã chọn giấy dán tường màu xanh nhạt cho phòng ngủ nhỏ của mình.","audioKind":"ex"},{"en":"Choosing durable wallpaper can reduce the frequency of interior renovations and limit household material waste.","vi":"Việc lựa chọn giấy dán tường bền đẹp có thể làm giảm tần suất sửa chữa nội thất và hạn chế lãng phí vật liệu gia đình.","audioKind":"ex2"}],"collocations":[{"en":"patterned wallpaper","vi":"giấy dán tường có hoa văn"},{"en":"a roll of wallpaper","vi":"một cuộn giấy dán tường"},{"en":"hang wallpaper","vi":"dán giấy tường"},{"en":"desktop wallpaper","vi":"hình nền máy tính"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"wallpaper thường là danh từ không đếm được; một cuộn giấy dán tường dùng là a roll of wallpaper.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_undress', 'en-b1-62', 'undress', '/ʌnˈdres/', 'B1', 'cởi quần áo; thay đồ', 'v.', 'dress (v.), undressed (adj.)', 'Trái nghĩa: dress', 'undress có thể dùng mà không cần tân ngữ đi kèm; để chỉ việc cởi một món đồ cụ thể, hãy dùng take off.', 'I undressed behind the curtain and put on pyjamas.', NULL, 'Tôi thay đồ phía sau tấm rèm và mặc bộ đồ ngủ vào.', '{"wordId":"undress","ukIpa":"/ʌnˈdres/","usIpa":"/ʌnˈdres/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To take off your own clothes or someone else''s clothes.","vi":"cởi quần áo; thay đồ"}],"examples":[{"en":"I undressed behind the curtain and put on pyjamas.","vi":"Tôi thay đồ phía sau tấm rèm và mặc bộ đồ ngủ vào.","audioKind":"ex"},{"en":"Healthcare staff should provide private spaces where patients can undress comfortably before a physical examination.","vi":"Nhân viên y tế nên cung cấp không gian riêng tư để bệnh nhân có thể thoải mái cởi đồ trước khi khám sức khỏe.","audioKind":"ex2"}],"collocations":[{"en":"get undressed","vi":"cởi bỏ quần áo"},{"en":"undress for bed","vi":"cởi đồ để đi ngủ"}],"wordFamily":["dress (v.)","undressed (adj.)"],"synonyms":[],"antonyms":["dress"],"tipVi":"undress có thể dùng mà không cần tân ngữ đi kèm; để chỉ việc cởi một món đồ cụ thể, hãy dùng take off.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_generally', 'en-b1-62', 'generally', '/ˈdʒenrəli/', 'B1', 'thường; nhìn chung; phổ biến; rộng rãi', 'adv.', 'general (adj.), generalise (v.), generalisation (n.)', 'Đồng nghĩa: usually, normally', 'generally chỉ phần lớn trường hợp chứ không phải không có ngoại lệ; ở đầu câu có thể dùng generally speaking.', 'I generally walk to work unless it rains.', NULL, 'Tôi thường đi bộ đi làm trừ khi trời mưa.', '{"wordId":"generally","ukIpa":"/ˈdʒenrəli/","usIpa":"/ˈdʒenrəli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"In most cases or at most times.","vi":"thường; nhìn chung"},{"pos":"adv.","en":"By most people or across most places.","vi":"phổ biến; rộng rãi"}],"examples":[{"en":"I generally walk to work unless it rains.","vi":"Tôi thường đi bộ đi làm trừ khi trời mưa.","audioKind":"ex"},{"en":"Public transport is generally more energy-efficient than private cars, especially when services carry large numbers of passengers.","vi":"Giao thông công cộng nhìn chung tiết kiệm năng lượng hơn xe hơi cá nhân, đặc biệt là khi các phương tiện chở số lượng lớn hành khách.","audioKind":"ex2"}],"collocations":[{"en":"generally speaking","vi":"nói chung là"},{"en":"generally accepted","vi":"được chấp nhận chung"},{"en":"generally regarded as","vi":"thường được xem là"}],"wordFamily":["general (adj.)","generalise (v.)","generalisation (n.)"],"synonyms":["usually","normally"],"antonyms":[],"tipVi":"generally chỉ phần lớn trường hợp chứ không phải không có ngoại lệ; ở đầu câu có thể dùng generally speaking.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pile', 'en-b1-62', 'pile', '/paɪl/', 'B1', 'đống; một đống; chồng lên; chất đống', 'n.', NULL, 'Đồng nghĩa: heap, stack', 'a pile of đi với vật được chồng lên; pile up có nghĩa là tích tụ lại.', 'A pile of dirty dishes filled the sink.', NULL, 'Một đống bát đĩa bẩn đầy ắp trong bồn rửa.', '{"wordId":"pile","ukIpa":"/paɪl/","usIpa":"/paɪl/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Objects placed together, often one on top of another.","vi":"đống; một đống"},{"pos":"v.","en":"To put things together in a heap.","vi":"chồng lên; chất đống"}],"examples":[{"en":"A pile of dirty dishes filled the sink.","vi":"Một đống bát đĩa bẩn đầy ắp trong bồn rửa.","audioKind":"ex"},{"en":"When waste collection services are inadequate, piles of rubbish can threaten public health in densely populated neighbourhoods.","vi":"Khi các dịch vụ thu gom rác không đáp ứng đủ, những đống rác có thể đe dọa sức khỏe cộng đồng ở các khu3 dân cư đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"a pile of books","vi":"một chồng sách"},{"en":"pile up","vi":"chất đống lên"},{"en":"pile plates on a table","vi":"chất đĩa lên bàn"}],"wordFamily":[],"synonyms":["heap","stack"],"antonyms":[],"tipVi":"a pile of đi với vật được chồng lên; pile up có nghĩa là tích tụ lại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_62_1', 'en-b1-62', 'Cách dùng “cheek” (n.) — má; gò má', 'rosy cheeks  ·  a kiss on the cheek  ·  have the cheek to', 'Nghĩa má (cheek) là danh từ đếm được; nghĩa sự vô lễ thường là danh từ không đếm được và hay dùng trong tiếng Anh-Anh khẩu ngữ.', 'Họ từ (Word Family): cheeky (adj.), cheekily (adv.)', '[{"hanzi":"A cold raindrop landed on my cheek outside.","pinyin":"","meaning":"Một giọt mưa lạnh buốt rơi xuống má tôi khi tôi đang ở ngoài trời."},{"hanzi":"Protective clothing should cover exposed areas, including the cheeks, when people work in extremely cold environments.","pinyin":"","meaning":"Quần áo bảo hộ nên che kín các vùng cơ thể bị hở, bao gồm cả vùng má, khi làm việc trong môi trường cực kỳ lạnh giá."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_62_2', 'en-b1-62', 'Cách dùng “bother” (v.) — làm phiền; quấy rầy', 'bother someone with something  ·  bother to do something  ·  cannot be bothered', 'Cấu trúc bother to do thường xuất hiện trong câu phủ định hoặc câu hỏi, diễn tả việc nhọc công hay bận lòng làm gì.', 'Họ từ (Word Family): bothered (adj.), bothersome (adj.) | Đồng nghĩa: annoy, trouble, disturb', '[{"hanzi":"Please do not bother your sister while she studies.","pinyin":"","meaning":"Xin đừng làm phiền chị gái của bạn trong lúc chị ấy đang học bài."},{"hanzi":"Constant notifications can bother students during lessons and reduce their ability to concentrate on complex tasks.","pinyin":"","meaning":"Những thông báo liên tục có thể quấy rầy học sinh trong giờ học và làm suy giảm khả năng tập trung vào các nhiệm vụ phức tạp của các em."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_62_3', 'en-b1-62', 'Cách dùng “grill” (v.) — nướng bằng vỉ', 'grilled fish  ·  a charcoal grill  ·  under the grill', 'Trong tiếng Anh-Anh grill thường chỉ việc gia nhiệt từ trên xuống; tiếng Anh-Mỹ thường chỉ việc nướng từ dưới lên.', 'Họ từ (Word Family): grilled (adj.), grilling (n.)', '[{"hanzi":"We grilled some peppers and ate them with rice.","pinyin":"","meaning":"Chúng tôi đã nướng một ít ớt chuông và ăn kèm với cơm."},{"hanzi":"Grilling vegetables with little oil can be a practical way to prepare healthier meals at home.","pinyin":"","meaning":"Nướng rau củ với một chút dầu là một cách thiết thực để chuẩn bị các bữa ăn lành mạnh hơn tại nhà."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_62_4', 'en-b1-62', 'Cách dùng “generally” (adv.) — thường; nhìn chung', 'generally speaking  ·  generally accepted  ·  generally regarded as', 'generally chỉ phần lớn trường hợp chứ không phải không có ngoại lệ; ở đầu câu có thể dùng generally speaking.', 'Họ từ (Word Family): general (adj.), generalise (v.), generalisation (n.) | Đồng nghĩa: usually, normally', '[{"hanzi":"I generally walk to work unless it rains.","pinyin":"","meaning":"Tôi thường đi bộ đi làm trừ khi trời mưa."},{"hanzi":"Public transport is generally more energy-efficient than private cars, especially when services carry large numbers of passengers.","pinyin":"","meaning":"Giao thông công cộng nhìn chung tiết kiệm năng lượng hơn xe hơi cá nhân, đặc biệt là khi các phương tiện chở số lượng lớn hành khách."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_62_1', 'en-b1-62', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_1_1', 'ten_b1_62_1', 'temporary', 'This temporary desk will do until the new one arrives.', 'This temporary desk will do until the new one arrives.', '/ˈtempəreri/', 'Chiếc bàn tạm thời này sẽ dùng tạm cho đến khi chiếc bàn mới được chuyển đến.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_1_2', 'ten_b1_62_1', 'bother', 'Please do not bother your sister while she studies.', 'Please do not bother your sister while she studies.', '/ˈbɑːðər/', 'Xin đừng làm phiền chị gái của bạn trong lúc chị ấy đang học bài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_1_3', 'ten_b1_62_1', 'unnecessary', 'Bring a light jacket, but heavy boots are unnecessary.', 'Bring a light jacket, but heavy boots are unnecessary.', '/ʌnˈnesəseri/', 'Mang theo một chiếc áo khoác mỏng, nhưng ủng dày thì không cần thiết.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_1_4', 'ten_b1_62_1', 'spoil', 'Please don''t spoil the surprise by telling your sister.', 'Please don''t spoil the surprise by telling your sister.', '/spɔɪl/', 'Xin đừng làm hỏng điều bất ngờ bằng cách kể cho chị bạn nghe nhé.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_1_5', 'ten_b1_62_1', 'underneath', 'Your slippers are underneath the chair by the bed.', 'Your slippers are underneath the chair by the bed.', '/ˌʌndɚˈniːθ/', 'Đôi dép của bạn ở dưới chiếc ghế cạnh giường kìa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_1_6', 'ten_b1_62_1', 'grill', 'We grilled some peppers and ate them with rice.', 'We grilled some peppers and ate them with rice.', '/ɡrɪl/', 'Chúng tôi đã nướng một ít ớt chuông và ăn kèm với cơm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_1_7', 'ten_b1_62_1', 'ruin', 'Heavy rain ruined the picnic we had planned.', 'Heavy rain ruined the picnic we had planned.', '/ˈruːɪn/', 'Cơn mưa lớn đã làm hỏng buổi dã ngoại mà chúng tôi đã lên kế hoạch.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_1_8', 'ten_b1_62_1', 'grocery', 'I carried two bags of groceries into the kitchen.', 'I carried two bags of groceries into the kitchen.', '/ˈɡroʊsəri/', 'Tôi xách hai túi hàng tạp hóa bước vào nhà bếp.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_62_1_1', 'en-b1-62', 'ten_b1_62_1', 'listening', 'listening', 'This temporary desk will do until the new one arrives.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc bàn tạm thời này sẽ dùng tạm cho đến khi chiếc bàn mới được chuyển đến.","Xin đừng làm phiền chị gái của bạn trong lúc chị ấy đang học bài.","Dạo này bạn ngủ có ngon giấc không, hay cảm thấy mệt mỏi?","Tôi để giày tập trong tủ đồ ở phòng gym."]'::jsonb, 0, 'This temporary desk will do until the new one arrives. → Chiếc bàn tạm thời này sẽ dùng tạm cho đến khi chiếc bàn mới được chuyển đến.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_62_1_2', 'en-b1-62', 'ten_b1_62_1', 'listening', 'listening', 'Please do not bother your sister while she studies.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy đẩy chiếc đĩa trượt trên mặt bàn về phía tôi.","Có một vết nứt mảnh chạy ngang qua chiếc cốc màu xanh yêu thích của tôi.","Xin đừng làm phiền chị gái của bạn trong lúc chị ấy đang học bài.","Cô ấy mặc một chiếc áo sơ mi sọc và quần jean xanh đậm."]'::jsonb, 2, 'Please do not bother your sister while she studies. → Xin đừng làm phiền chị gái của bạn trong lúc chị ấy đang học bài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_62_1_3', 'en-b1-62', 'ten_b1_62_1', 'listening', 'listening', 'Bring a light jacket, but heavy boots are unnecessary.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một đống bát đĩa bẩn đầy ắp trong bồn rửa.","Điệu nhảy ngớ ngẩn của anh ấy đã làm mọi người đang đợi trong bếp cười thích thú.","Cô ấy đẩy chiếc đĩa trượt trên mặt bàn về phía tôi.","Mang theo một chiếc áo khoác mỏng, nhưng ủng dày thì không cần thiết."]'::jsonb, 3, 'Bring a light jacket, but heavy boots are unnecessary. → Mang theo một chiếc áo khoác mỏng, nhưng ủng dày thì không cần thiết.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_62_2', 'en-b1-62', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_2_1', 'ten_b1_62_2', 'temporary', 'Temporary accommodation provides essential shelter while families wait for suitable permanent housing to become available.', 'Temporary accommodation provides essential shelter while families wait for suitable permanent housing to become available.', '/ˈtempəreri/', 'Nơi ở tạm thời cung cấp chỗ che chở thiết yếu trong lúc các gia đình chờ đợi nhà ở cố định phù hợp có sẵn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_2_2', 'ten_b1_62_2', 'bother', 'Constant notifications can bother students during lessons and reduce their ability to concentrate on complex tasks.', 'Constant notifications can bother students during lessons and reduce their ability to concentrate on complex tasks.', '/ˈbɑːðər/', 'Những thông báo liên tục có thể quấy rầy học sinh trong giờ học và làm suy giảm khả năng tập trung vào các nhiệm vụ phức tạp của các em.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_2_3', 'ten_b1_62_2', 'unnecessary', 'Clear instructions can prevent unnecessary delays and help public services operate more efficiently.', 'Clear instructions can prevent unnecessary delays and help public services operate more efficiently.', '/ʌnˈnesəseri/', 'Các hướng dẫn rõ ràng có thể ngăn ngừa sự chậm trễ không cần thiết và giúp các dịch vụ công hoạt động hiệu quả hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_2_4', 'ten_b1_62_2', 'spoil', 'Poorly planned construction can spoil natural landscapes and reduce their appeal to both residents and tourists.', 'Poorly planned construction can spoil natural landscapes and reduce their appeal to both residents and tourists.', '/spɔɪl/', 'Công trình xây dựng được quy hoạch kém có thể phá hủy cảnh quan thiên nhiên và làm giảm sức hút của chúng đối với cả cư dân lẫn du khách.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_2_5', 'ten_b1_62_2', 'underneath', 'Insulation installed underneath floors can reduce heat loss and improve energy efficiency in older homes.', 'Insulation installed underneath floors can reduce heat loss and improve energy efficiency in older homes.', '/ˌʌndɚˈniːθ/', 'Lớp vật liệu cách nhiệt lắp đặt dưới sàn nhà có thể làm giảm thất thoát nhiệt và nâng cao hiệu quả năng lượng trong những ngôi nhà cũ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_62_2_6', 'ten_b1_62_2', 'grill', 'Grilling vegetables with little oil can be a practical way to prepare healthier meals at home.', 'Grilling vegetables with little oil can be a practical way to prepare healthier meals at home.', '/ɡrɪl/', 'Nướng rau củ với một chút dầu là một cách thiết thực để chuẩn bị các bữa ăn lành mạnh hơn tại nhà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_62_2_1', 'en-b1-62', 'ten_b1_62_2', 'listening', 'listening', 'Temporary accommodation provides essential shelter while families wait for suitable permanent housing to become available.', NULL, 'Trong câu vừa nghe, từ “temporary” mang nghĩa nào sau đây?', '["thuộc về âm nhạc cổ điển","bình minh; lúc mặt trời mọc","tạm thời; lâm thời","hình ảnh; ảnh chụp"]'::jsonb, 2, '“temporary” (/ˈtempəreri/): tạm thời; lâm thời. Câu đầy đủ: Temporary accommodation provides essential shelter while families wait for suitable permanent housing to become available.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_62_2_2', 'en-b1-62', 'ten_b1_62_2', 'listening', 'listening', 'Constant notifications can bother students during lessons and reduce their ability to concentrate on complex tasks.', NULL, 'Trong câu vừa nghe, từ “bother” mang nghĩa nào sau đây?', '["thiên thần","mối liên hệ; sự liên quan","làm phiền; quấy rầy","bình minh; lúc mặt trời mọc"]'::jsonb, 2, '“bother” (/ˈbɑːðər/): làm phiền; quấy rầy. Câu đầy đủ: Constant notifications can bother students during lessons and reduce their ability to concentrate on complex tasks.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_62_1', 'en-b1-62', 'This temporary desk will do until the new one arrives', 'Chiếc bàn tạm thời này sẽ dùng tạm cho đến khi chiếc bàn mới được chuyển đến.', 'temporary /ˈtempəreri/', '["the","This","one","do","temporary","until","new","desk","arrives","will"]'::jsonb, NULL, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_62_2', 'en-b1-62', 'Please do not bother your sister while she studies', 'Xin đừng làm phiền chị gái của bạn trong lúc chị ấy đang học bài.', 'bother /ˈbɑːðər/', '["your","sister","Please","she","do","studies","bother","while","not"]'::jsonb, NULL, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_62_3', 'en-b1-62', 'Bring a light jacket, but heavy boots are unnecessary', 'Mang theo một chiếc áo khoác mỏng, nhưng ủng dày thì không cần thiết.', 'unnecessary /ʌnˈnesəseri/', '["Bring","but","a","heavy","unnecessary","boots","light","are","jacket"]'::jsonb, NULL, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_62_4', 'en-b1-62', 'Please don''t spoil the surprise by telling your sister', 'Xin đừng làm hỏng điều bất ngờ bằng cách kể cho chị bạn nghe nhé.', 'spoil /spɔɪl/', '["telling","the","surprise","don''t","spoil","sister","your","Please","by"]'::jsonb, NULL, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_62_5', 'en-b1-62', 'Your slippers are underneath the chair by the bed', 'Đôi dép của bạn ở dưới chiếc ghế cạnh giường kìa.', 'underneath /ˌʌndɚˈniːθ/', '["bed","underneath","Your","are","the","by","slippers","chair","the"]'::jsonb, NULL, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_62_6', 'en-b1-62', 'We grilled some peppers and ate them with rice', 'Chúng tôi đã nướng một ít ớt chuông và ăn kèm với cơm.', 'grill /ɡrɪl/', '["peppers","with","grilled","some","and","We","them","rice","ate"]'::jsonb, NULL, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_62_7', 'en-b1-62', 'Heavy rain ruined the picnic we had planned', 'Cơn mưa lớn đã làm hỏng buổi dã ngoại mà chúng tôi đã lên kế hoạch.', 'ruin /ˈruːɪn/', '["planned","Heavy","we","ruined","had","the","rain","picnic"]'::jsonb, NULL, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
