INSERT INTO sentence_scrambles (id, lesson_id, target_hanzi, target_meaning, pinyin, tokens, unlearned_hint, sort_order, is_deleted, deleted_at) VALUES ('ssen_b1_62_9', 'en-b1-62', 'His silly dance amused everyone waiting in the kitchen', 'Điệu nhảy ngớ ngẩn của anh ấy đã làm mọi người đang đợi trong bếp cười thích thú.', 'amuse /əˈmjuːz/', '["everyone","silly","dance","kitchen","amused","waiting","the","His","in"]'::jsonb, NULL, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, target_hanzi = EXCLUDED.target_hanzi, target_meaning = EXCLUDED.target_meaning, pinyin = EXCLUDED.pinyin, tokens = EXCLUDED.tokens, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
