INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_2', 'en-b1-62', NULL, 'comprehensive_test', 'listening', 'Please do not bother your sister while she studies.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Công thức món súp này chỉ cần một vài nguyên liệu đơn giản.","Chúng tôi đã chọn giấy dán tường màu xanh nhạt cho phòng ngủ nhỏ của mình.","Xin đừng làm phiền chị gái của bạn trong lúc chị ấy đang học bài.","Chúng tôi tìm thấy hai chỗ ngồi trống ở hàng ghế đầu."]'::jsonb, 2, 'Please do not bother your sister while she studies. → Xin đừng làm phiền chị gái của bạn trong lúc chị ấy đang học bài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_3', 'en-b1-62', NULL, 'comprehensive_test', 'listening', 'unnecessary', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["không cần thiết; thừa thãi","nhấn; ấn","nhu cầu","quả bơ"]'::jsonb, 0, 'unnecessary (/ʌnˈnesəseri/) → không cần thiết; thừa thãi', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_4', 'en-b1-62', NULL, 'comprehensive_test', 'listening', 'Please don''t spoil the surprise by telling your sister.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xin đừng làm hỏng điều bất ngờ bằng cách kể cho chị bạn nghe nhé.","Người trông trẻ đã đọc cho con gái chúng tôi nghe một câu chuyện trước khi đi ngủ.","Cô ấy mặc một chiếc áo sơ mi sọc và quần jean xanh đậm.","Có một vết nứt mảnh chạy ngang qua chiếc cốc màu xanh yêu thích của tôi."]'::jsonb, 0, 'Please don''t spoil the surprise by telling your sister. → Xin đừng làm hỏng điều bất ngờ bằng cách kể cho chị bạn nghe nhé.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_5', 'en-b1-62', NULL, 'comprehensive_test', 'listening', 'underneath', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trừ đi; khấu trừ","tình nguyện viên; người làm công tác thiện nguyện","hương vị; mùi vị","ở dưới; bên dưới"]'::jsonb, 3, 'underneath (/ˌʌndɚˈniːθ/) → ở dưới; bên dưới; ở phía dưới; ở phần đáy', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_6', 'en-b1-62', NULL, 'comprehensive_test', 'listening', 'We grilled some peppers and ate them with rice.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mang theo một chiếc áo khoác mỏng, nhưng ủng dày thì không cần thiết.","Có một vết nứt mảnh chạy ngang qua chiếc cốc màu xanh yêu thích của tôi.","Một giọt mưa lạnh buốt rơi xuống má tôi khi tôi đang ở ngoài trời.","Chúng tôi đã nướng một ít ớt chuông và ăn kèm với cơm."]'::jsonb, 3, 'We grilled some peppers and ate them with rice. → Chúng tôi đã nướng một ít ớt chuông và ăn kèm với cơm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_7', 'en-b1-62', NULL, 'comprehensive_test', 'listening', 'ruin', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["làm hỏng; tàn phá","khác nhau; gồm nhiều loại khác nhau","chủ nhà; người dẫn chương trình","động vật hoang dã; sinh vật hoang dã"]'::jsonb, 0, 'ruin (/ˈruːɪn/) → làm hỏng; tàn phá; đồ nát; tàn tích; sự sụp đổ; sự phá sản', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_8', 'en-b1-62', NULL, 'comprehensive_test', 'listening', 'I carried two bags of groceries into the kitchen.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi xách hai túi hàng tạp hóa bước vào nhà bếp.","Đôi dép của bạn ở dưới chiếc ghế cạnh giường kìa.","Mang theo một chiếc áo khoác mỏng, nhưng ủng dày thì không cần thiết.","Người trông trẻ đã đọc cho con gái chúng tôi nghe một câu chuyện trước khi đi ngủ."]'::jsonb, 0, 'I carried two bags of groceries into the kitchen. → Tôi xách hai túi hàng tạp hóa bước vào nhà bếp.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_9', 'en-b1-62', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Directly below something, often covered or hidden by it.”?', '["grocery","bother","tape","underneath"]'::jsonb, 3, 'underneath (/ˌʌndɚˈniːθ/) → ở dưới; bên dưới', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
