INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_18', 'en-b1-62', NULL, 'comprehensive_test', 'reading', NULL, 'Temporary accommodation provides essential shelter while families wait for suitable permanent housing to become available.', 'Dựa vào câu trên, từ “temporary” có nghĩa phù hợp nhất là gì?', '["đi lấy; mang về; tìm và mang đến","tạm thời; lâm thời","thực tế; thực trạng","tham gia; liên quan"]'::jsonb, 1, 'temporary: tạm thời; lâm thời. Dịch cả câu: Nơi ở tạm thời cung cấp chỗ che chở thiết yếu trong lúc các gia đình chờ đợi nhà ở cố định phù hợp có sẵn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_19', 'en-b1-62', NULL, 'comprehensive_test', 'reading', NULL, 'Constant notifications can bother students during lessons and reduce their ability to concentrate on complex tasks.', 'Dựa vào câu trên, từ “bother” có nghĩa phù hợp nhất là gì?', '["bối rối; hoang mang","làm phiền; quấy rầy","tách trà; chén trà","khuyết tật; tàn tật"]'::jsonb, 1, 'bother: làm phiền; quấy rầy; bận tâm; phiền phức; phiền toái; rắc rối. Dịch cả câu: Những thông báo liên tục có thể quấy rầy học sinh trong giờ học và làm suy giảm khả năng tập trung vào các nhiệm vụ phức tạp của các em.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_20', 'en-b1-62', NULL, 'comprehensive_test', 'reading', NULL, 'Clear instructions can prevent unnecessary delays and help public services operate more efficiently.', 'Dựa vào câu trên, từ “unnecessary” có nghĩa phù hợp nhất là gì?', '["truyện trinh thám ly kỳ; phim kinh dị ly kỳ","biên lai; giấy biên nhận","ao; hồ nước nhỏ","không cần thiết; thừa thãi"]'::jsonb, 3, 'unnecessary: không cần thiết; thừa thãi. Dịch cả câu: Các hướng dẫn rõ ràng có thể ngăn ngừa sự chậm trễ không cần thiết và giúp các dịch vụ công hoạt động hiệu quả hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_21', 'en-b1-62', NULL, 'comprehensive_test', 'reading', NULL, 'Poorly planned construction can spoil natural landscapes and reduce their appeal to both residents and tourists.', 'Dựa vào câu trên, từ “spoil” có nghĩa phù hợp nhất là gì?', '["chia ra; tách ra; phân chia","gồ ghề; xù xì; không bằng phẳng","thỏa thuận; hiệp định","làm hỏng; phá hỏng"]'::jsonb, 3, 'spoil: làm hỏng; phá hỏng; nuông chiều; cưng chiều quá mức; làm ôi thiu. Dịch cả câu: Công trình xây dựng được quy hoạch kém có thể phá hủy cảnh quan thiên nhiên và làm giảm sức hút của chúng đối với cả cư dân lẫn du khách.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_22', 'en-b1-62', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cởi quần áo; thay đồ”', '["rub","undress","loan","pregnant"]'::jsonb, 1, 'cởi quần áo; thay đồ → undress (/ʌnˈdres/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_23', 'en-b1-62', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thường; nhìn chung”', '["sunrise","licence","leisure","generally"]'::jsonb, 3, 'thường; nhìn chung → generally (/ˈdʒenrəli/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_62_24', 'en-b1-62', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đống; một đống”', '["storeroom","source","pile","assignment"]'::jsonb, 2, 'đống; một đống → pile (/paɪl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-b1-63', 'en', 'Bài 63: Đời sống hằng ngày (15) - CEFR B1', 'CEFR B1', 'B1 · Đời sống', '27 từ vựng Tiếng Anh CEFR B1 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 3063, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flashlight', 'en-b1-63', 'flashlight', '/ˈflæʃlaɪt/', 'B1', 'đèn pin', 'n.', NULL, 'Đồng nghĩa: torch', 'flashlight là từ chỉ đèn pin trong tiếng Anh-Mỹ; tiếng Anh-Anh thường dùng torch.', 'She used a flashlight to look under the bed.', NULL, 'Cô ấy dùng đèn pin để soi xuống gầm giường.', '{"wordId":"flashlight","ukIpa":"/ˈflæʃlaɪt/","usIpa":"/ˈflæʃlaɪt/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A small portable electric light powered by batteries.","vi":"đèn pin"}],"examples":[{"en":"She used a flashlight to look under the bed.","vi":"Cô ấy dùng đèn pin để soi xuống gầm giường.","audioKind":"ex"},{"en":"Households should keep a flashlight readily available to improve safety during unexpected power cuts.","vi":"Các hộ gia đình nên để sẵn đèn pin ở nơi dễ lấy để tăng độ an toàn trong các đợt cúp điện bất ngờ.","audioKind":"ex2"}],"collocations":[{"en":"turn on a flashlight","vi":"bật đèn pin"},{"en":"shine a flashlight","vi":"chiếu đèn pin"},{"en":"flashlight beam","vi":"chùm sáng đèn pin"}],"wordFamily":[],"synonyms":["torch"],"antonyms":[],"tipVi":"flashlight là từ chỉ đèn pin trong tiếng Anh-Mỹ; tiếng Anh-Anh thường dùng torch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_handkerchief', 'en-b1-63', 'handkerchief', '/ˈhæŋkərtʃɪf/', 'B1', 'khăn tay', 'n.', NULL, 'Đồng nghĩa: hanky', 'Chỉ chiếc khăn dùng để lau mặt hoặc lau mũi, thường không dùng để chỉ khăn trùm đầu.', 'She pulled a clean handkerchief from her coat pocket.', NULL, 'Cô ấy rút một chiếc khăn tay sạch từ túi áo khoác ra.', '{"wordId":"handkerchief","ukIpa":"/ˈhæŋkətʃɪf/","usIpa":"/ˈhæŋkərtʃɪf/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A small cloth used for wiping your nose or face.","vi":"khăn tay"}],"examples":[{"en":"She pulled a clean handkerchief from her coat pocket.","vi":"Cô ấy rút một chiếc khăn tay sạch từ túi áo khoác ra.","audioKind":"ex"},{"en":"Using a washable handkerchief instead of disposable tissues can reduce everyday household waste.","vi":"Việc sử dụng khăn tay có thể giặt thay vì khăn giấy dùng một lần có thể làm giảm lượng rác thải sinh hoạt hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"a clean handkerchief","vi":"một chiếc khăn tay sạch"},{"en":"a cotton handkerchief","vi":"khăn tay bằng cotton"},{"en":"a pocket handkerchief","vi":"khăn tay bỏ túi"}],"wordFamily":[],"synonyms":["hanky"],"antonyms":[],"tipVi":"Chỉ chiếc khăn dùng để lau mặt hoặc lau mũi, thường không dùng để chỉ khăn trùm đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ink', 'en-b1-63', 'ink', '/ɪŋk/', 'B1', 'mực (viết, vẽ, in); bôi mực; tra mực', 'n.', 'inky (adj.)', NULL, 'ink làm danh từ thường không đếm được; "viết bằng mực" dùng in ink.', 'Blue ink leaked from my pen onto my sleeve.', NULL, 'Mực xanh từ cây bút của tôi bị rỉ ra tay áo.', '{"wordId":"ink","ukIpa":"/ɪŋk/","usIpa":"/ɪŋk/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"coloured liquid used for writing, drawing or printing","vi":"mực (viết, vẽ, in)"},{"pos":"v.","en":"to apply ink to a surface","vi":"bôi mực; tra mực"}],"examples":[{"en":"Blue ink leaked from my pen onto my sleeve.","vi":"Mực xanh từ cây bút của tôi bị rỉ ra tay áo.","audioKind":"ex"},{"en":"Schools can reduce their environmental impact by using less paper and choosing refillable ink cartridges.","vi":"Các trường học có thể giảm thiểu tác động môi trường bằng cách dùng ít giấy hơn và chọn hộp mực có thể nạp lại.","audioKind":"ex2"}],"collocations":[{"en":"in ink","vi":"bằng mực"},{"en":"ink cartridge","vi":"hộp mực"},{"en":"printing ink","vi":"mực in"},{"en":"run out of ink","vi":"hết mực"}],"wordFamily":["inky (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"ink làm danh từ thường không đếm được; \"viết bằng mực\" dùng in ink.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_string', 'en-b1-63', 'string', '/strɪŋ/', 'B1', 'dây thừng mảnh; dây buộc; dây đàn; chuỗi; một loạt', 'n.', 'stringy (adj.)', 'Đồng nghĩa: cord', 'Dây thừng thường không đếm được; dây đàn và string trong a string of thì đếm được.', 'I tied the parcel with a piece of string.', NULL, 'Tôi buộc gói hàng lại bằng một đoạn dây thừng mảnh.', '{"wordId":"string","ukIpa":"/strɪŋ/","usIpa":"/strɪŋ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Thin cord used for tying or fastening things.","vi":"dây thừng mảnh; dây buộc"},{"pos":"n.","en":"A stretched wire or thread that produces musical sounds.","vi":"dây đàn"},{"pos":"n.","en":"A series of connected things or events.","vi":"chuỗi; một loạt"}],"examples":[{"en":"I tied the parcel with a piece of string.","vi":"Tôi buộc gói hàng lại bằng một đoạn dây thừng mảnh.","audioKind":"ex"},{"en":"A string of successful conservation projects has demonstrated the value of involving local communities in environmental protection.","vi":"Một loạt các dự án bảo tồn thành công đã minh chứng cho giá trị của việc lôi kéo cộng đồng địa phương vào công tác bảo vệ môi trường.","audioKind":"ex2"}],"collocations":[{"en":"a piece of string","vi":"một đoạn dây"},{"en":"guitar strings","vi":"dây đàn guitar"},{"en":"a string of successes","vi":"một chuỗi thành công"},{"en":"tie with string","vi":"buộc bằng dây"}],"wordFamily":["stringy (adj.)"],"synonyms":["cord"],"antonyms":[],"tipVi":"Dây thừng thường không đếm được; dây đàn và string trong a string of thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shadow', 'en-b1-63', 'shadow', '/ˈʃædoʊ/', 'B1', 'cái bóng; bóng râm; đi theo sát; theo chân học việc', 'n.', 'shadowy (adj.)', NULL, 'shadow chỉ cái bóng cụ thể; shade thường chỉ chỗ mát che bóng râm.', 'The cat chased its shadow across the sunny kitchen floor.', NULL, 'Con mèo đuổi theo cái bóng của chính nó trên sàn bếp ngập tràn ánh nắng.', '{"wordId":"shadow","ukIpa":"/ˈʃædəʊ/","usIpa":"/ˈʃædoʊ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A dark shape or area where something blocks light.","vi":"cái bóng; bóng râm"},{"pos":"v.","en":"To follow someone closely, often to learn about their work.","vi":"đi theo sát; theo chân học việc"}],"examples":[{"en":"The cat chased its shadow across the sunny kitchen floor.","vi":"Con mèo đuổi theo cái bóng của chính nó trên sàn bếp ngập tràn ánh nắng.","audioKind":"ex"},{"en":"Allowing students to shadow experienced nurses can help them understand the practical demands of a healthcare career.","vi":"Việc cho học sinh theo chân các y điều dưỡng có kinh nghiệm có thể giúp các em hiểu được những yêu cầu thực tế của một sự nghiệp y tế.","audioKind":"ex2"}],"collocations":[{"en":"cast a shadow","vi":"tạo bóng; gieo rắc bóng tối"},{"en":"in the shadows","vi":"trong bóng tối"},{"en":"job shadowing","vi":"chương trình theo chân học việc"}],"wordFamily":["shadowy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"shadow chỉ cái bóng cụ thể; shade thường chỉ chỗ mát che bóng râm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_careless', 'en-b1-63', 'careless', '/ˈkerləs/', 'B1', 'bất cẩn; cẩu thả', 'adj.', 'care (n.), careful (adj.), carelessly (adv.), carelessness (n.)', 'Đồng nghĩa: inattentive, negligent · Trái nghĩa: careful, attentive', 'careless là bất cẩn; trong khi carefree mới là vô tư, không lo âu.', 'I was careless and left my keys in the door.', NULL, 'Tôi đãng trí để quên chìa khóa ở ổ khóa cửa.', '{"wordId":"careless","ukIpa":"/ˈkeələs/","usIpa":"/ˈkerləs/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Not giving enough attention to avoid mistakes or damage.","vi":"bất cẩn; cẩu thả"}],"examples":[{"en":"I was careless and left my keys in the door.","vi":"Tôi đãng trí để quên chìa khóa ở ổ khóa cửa.","audioKind":"ex"},{"en":"Careless disposal of household waste can pollute local waterways and create serious risks for wildlife.","vi":"Việc vứt bỏ rác thải sinh hoạt bừa bãi có thể gây ô nhiễm nguồn nước địa phương và tạo ra rủi ro nghiêm trọng cho động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"a careless mistake","vi":"một lỗi do sơ suất"},{"en":"careless driving","vi":"lái xe ẩu"},{"en":"careless with money","vi":"tiêu tiền không cẩn thận"}],"wordFamily":["care (n.)","careful (adj.)","carelessly (adv.)","carelessness (n.)"],"synonyms":["inattentive","negligent"],"antonyms":["careful","attentive"],"tipVi":"careless là bất cẩn; trong khi carefree mới là vô tư, không lo âu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hundredth', 'en-b1-63', 'hundredth', '/ˈhʌndrədθ/', 'B1', 'thứ một trăm; phần trăm', 'num.', 'hundred (num.)', NULL, 'Số thứ tự chỉ thứ một trăm; a hundredth chỉ một phần trăm.', 'Our village celebrated its hundredth anniversary with a picnic.', NULL, 'Làng chúng tôi đã tổ chức buổi dã ngoại để kỷ niệm một trăm năm thành lập.', '{"wordId":"hundredth","ukIpa":"/ˈhʌndrədθ/","usIpa":"/ˈhʌndrədθ/","cefr":"B1","topic":"daily","senses":[{"pos":"num.","en":"coming after the ninety-ninth in a sequence","vi":"thứ một trăm"},{"pos":"n.","en":"one of a hundred equal parts of something","vi":"phần trăm"}],"examples":[{"en":"Our village celebrated its hundredth anniversary with a picnic.","vi":"Làng chúng tôi đã tổ chức buổi dã ngoại để kỷ niệm một trăm năm thành lập.","audioKind":"ex"},{"en":"The athlete missed the qualifying time by just one hundredth of a second, demonstrating the precision required.","vi":"Vận động viên này chỉ bỏ lỡ thời gian chuẩn đạt chuẩn đúng một phần trăm giây, cho thấy độ chính xác đòi hỏi rất cao.","audioKind":"ex2"}],"collocations":[{"en":"the hundredth anniversary","vi":"lễ kỷ niệm một trăm năm"},{"en":"one hundredth of a second","vi":"một phần trăm giây"},{"en":"for the hundredth time","vi":"lần thứ một trăm"}],"wordFamily":["hundred (num.)"],"synonyms":[],"antonyms":[],"tipVi":"Số thứ tự chỉ thứ một trăm; a hundredth chỉ một phần trăm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sweep', 'en-b1-63', 'sweep', '/swiːp/', 'B1', 'quét; làm sạch; càn quét; tràn qua nhanh chóng', 'v.', 'sweeper (n.), sweeping (adj.)', NULL, 'Dạng quá khứ và quá khứ phân từ của từ này đều là swept.', 'Please sweep the kitchen floor before our guests arrive.', NULL, 'Làm ơn quét sạch sàn nhà bếp trước khi khách của chúng ta đến nhé.', '{"wordId":"sweep","ukIpa":"/swiːp/","usIpa":"/swiːp/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to clean a surface using a brush or broom","vi":"quét; làm sạch"},{"pos":"v.","en":"to move quickly and powerfully across an area","vi":"càn quét; tràn qua nhanh chóng"}],"examples":[{"en":"Please sweep the kitchen floor before our guests arrive.","vi":"Làm ơn quét sạch sàn nhà bếp trước khi khách của chúng ta đến nhé.","audioKind":"ex"},{"en":"Severe storms can sweep across coastal regions, damaging homes and disrupting essential transport services.","vi":"Những cơn bão dữ dội có thể càn quét qua các vùng ven biển, phá hủy nhà cửa và làm tê liệt các dịch vụ giao thông thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"sweep the floor","vi":"quét nhà"},{"en":"sweep away","vi":"quét sạch; cuốn trôi"},{"en":"sweep across","vi":"càn quét qua; tràn qua"}],"wordFamily":["sweeper (n.)","sweeping (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ của từ này đều là swept.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pause', 'en-b1-63', 'pause', '/pɔːz/', 'B1', 'tạm dừng; dừng lại chốc lát; sự tạm dừng; khoảng ngừng ngắn', 'v.', NULL, 'Trái nghĩa: continue', 'Pause chỉ việc tạm dừng trong chốc lát, thường ngầm hiểu là sẽ tiếp tục sau đó.', 'She paused at the door to check her bag.', NULL, 'Cô ấy dừng lại ở cửa để kiểm tra lại chiếc túi của mình.', '{"wordId":"pause","ukIpa":"/pɔːz/","usIpa":"/pɔːz/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to stop briefly before continuing","vi":"tạm dừng; dừng lại chốc lát"},{"pos":"n.","en":"a short break in an activity or speech","vi":"sự tạm dừng; khoảng ngừng ngắn"}],"examples":[{"en":"She paused at the door to check her bag.","vi":"Cô ấy dừng lại ở cửa để kiểm tra lại chiếc túi của mình.","audioKind":"ex"},{"en":"Teachers should pause after asking questions to give students enough time to develop their answers.","vi":"Giáo viên nên tạm dừng một chút sau khi đặt câu hỏi để học sinh có đủ thời gian chuẩn bị câu trả lời.","audioKind":"ex2"}],"collocations":[{"en":"pause for a moment","vi":"dừng lại chốc lát"},{"en":"a brief pause","vi":"khoảng dừng ngắn"},{"en":"pause a video","vi":"tạm dừng video"}],"wordFamily":[],"synonyms":[],"antonyms":["continue"],"tipVi":"Pause chỉ việc tạm dừng trong chốc lát, thường ngầm hiểu là sẽ tiếp tục sau đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wrap', 'en-b1-63', 'wrap', '/ræp/', 'B1', 'gói; bọc; quấn; khăn quàng vai; áo choàng; bánh cuộn', 'v.', 'wrapping (n.), wrapper (n.)', 'Trái nghĩa: unwrap', 'Dùng wrap A in B để diễn tả việc dùng vật liệu B để bọc quanh vật A.', 'She wrapped the birthday present in bright yellow paper.', NULL, 'Cô ấy gói món quà sinh nhật bằng một lớp giấy màu vàng rực rỡ.', '{"wordId":"wrap","ukIpa":"/ræp/","usIpa":"/ræp/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"to cover something by folding material around it","vi":"gói; bọc; quấn"},{"pos":"n.","en":"a loose piece of clothing worn around the shoulders","vi":"khăn quàng vai; áo choàng"},{"pos":"n.","en":"a thin flat bread rolled around a filling","vi":"bánh cuộn"}],"examples":[{"en":"She wrapped the birthday present in bright yellow paper.","vi":"Cô ấy gói món quà sinh nhật bằng một lớp giấy màu vàng rực rỡ.","audioKind":"ex"},{"en":"Retailers could reduce packaging waste by encouraging customers to wrap gifts in reusable fabric.","vi":"Các nhà bán lẻ có thể giảm thiểu rác thải bao bì bằng cách khuyến khích khách hàng gói quà bằng vải có thể tái sử dụng.","audioKind":"ex2"}],"collocations":[{"en":"wrap a present","vi":"gói quà"},{"en":"wrap something in paper","vi":"gói cái gì đó bằng giấy"},{"en":"wrap up warm","vi":"mặc thật ấm"}],"wordFamily":["wrapping (n.)","wrapper (n.)"],"synonyms":[],"antonyms":["unwrap"],"tipVi":"Dùng wrap A in B để diễn tả việc dùng vật liệu B để bọc quanh vật A.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_neither', 'en-b1-63', 'neither', '/ˈniːðər/', 'B1', 'không bên nào; cả hai đều không; không ai trong hai người; không cái nào trong hai thứ; cũng không', 'det.', NULL, 'Trái nghĩa: both', 'Neither chỉ dùng cho hai đối tượng; đi với danh từ số ít và thường kết hợp với nor.', 'Neither jacket fits me, so I will keep looking.', NULL, 'Cả hai chiếc áo khoác đều không vừa với tôi, nên tôi sẽ tiếp tục tìm kiếm.', '{"wordId":"neither","ukIpa":"/ˈnaɪðə/","usIpa":"/ˈniːðər/","cefr":"B1","topic":"daily","senses":[{"pos":"det.","en":"not one or the other of two","vi":"không bên nào; cả hai đều không"},{"pos":"pron.","en":"not either of two people or things","vi":"không ai trong hai người; không cái nào trong hai thứ"},{"pos":"adv.","en":"used to add another negative statement","vi":"cũng không"}],"examples":[{"en":"Neither jacket fits me, so I will keep looking.","vi":"Cả hai chiếc áo khoác đều không vừa với tôi, nên tôi sẽ tiếp tục tìm kiếm.","audioKind":"ex"},{"en":"Neither approach can solve traffic congestion alone, so cities need a combination of investment and regulation.","vi":"Cả hai phương pháp đều không thể đơn độc giải quyết tình trạng ùn tắc giao thông, vì vậy các thành phố cần kết hợp giữa đầu tư và quản lý.","audioKind":"ex2"}],"collocations":[{"en":"neither of them","vi":"không ai trong số họ"},{"en":"neither option","vi":"cả hai lựa chọn đều không"},{"en":"neither ... nor ...","vi":"không... cũng không..."},{"en":"neither do I","vi":"tôi cũng vậy (trong câu phủ định)"}],"wordFamily":[],"synonyms":[],"antonyms":["both"],"tipVi":"Neither chỉ dùng cho hai đối tượng; đi với danh từ số ít và thường kết hợp với nor.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_immediate', 'en-b1-63', 'immediate', '/ɪˈmiːdiət/', 'B1', 'ngay lập tức; tức thì; gần nhất; sát bên; trực tiếp', 'adj.', 'immediately (adv.), immediacy (n.)', 'Đồng nghĩa: instant · Trái nghĩa: delayed', 'Immediate là tính từ; để bổ nghĩa cho động từ, hãy dùng trạng từ immediately.', 'The leaking pipe needs immediate attention before the kitchen floods.', NULL, 'Đường ống bị rò rỉ cần được xử lý ngay lập tức trước khi nhà bếp bị ngập.', '{"wordId":"immediate","ukIpa":"/ɪˈmiːdiət/","usIpa":"/ɪˈmiːdiət/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Happening or needed now, without any delay.","vi":"ngay lập tức; tức thì"},{"pos":"adj.","en":"Closest in space, time, or relationship.","vi":"gần nhất; sát bên"},{"pos":"adj.","en":"Directly connected to something, without anything coming between.","vi":"trực tiếp"}],"examples":[{"en":"The leaking pipe needs immediate attention before the kitchen floods.","vi":"Đường ống bị rò rỉ cần được xử lý ngay lập tức trước khi nhà bếp bị ngập.","audioKind":"ex"},{"en":"Governments should take immediate action to protect communities facing severe water shortages during prolonged droughts.","vi":"Chính phủ nên hành động ngay lập tức để bảo vệ các cộng đồng đang phải đối mặt với tình trạng thiếu nước nghiêm trọng trong các đợt hạn hán kéo dài.","audioKind":"ex2"}],"collocations":[{"en":"immediate action","vi":"hành động ngay lập tức"},{"en":"immediate response","vi":"phản hồi tức thì"},{"en":"immediate family","vi":"gia đình trực hệ; người thân ruột thịt"},{"en":"immediate surroundings","vi":"môi trường xung quanh trực tiếp"}],"wordFamily":["immediately (adv.)","immediacy (n.)"],"synonyms":["instant"],"antonyms":["delayed"],"tipVi":"Immediate là tính từ; để bổ nghĩa cho động từ, hãy dùng trạng từ immediately.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tin', 'en-b1-63', 'tin', '/tɪn/', 'B1', 'hộp kim loại; lon; đồ hộp; thiếc', 'n.', NULL, NULL, 'Nghĩa hộp đựng là danh từ đếm được (tiếng Anh-Anh dùng tin, tiếng Anh-Mỹ dùng can); nghĩa kim loại thiếc không đếm được.', 'There is a tin of beans in the cupboard.', NULL, 'Có một hộp đậu trong tủ chén.', '{"wordId":"tin","ukIpa":"/tɪn/","usIpa":"/tɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A metal container, especially for food, or its contents.","vi":"hộp kim loại; lon; đồ hộp"},{"pos":"n.","en":"A soft, silver-coloured metal used to coat other metals.","vi":"thiếc"}],"examples":[{"en":"There is a tin of beans in the cupboard.","vi":"Có một hộp đậu trong tủ chén.","audioKind":"ex"},{"en":"Reusing a metal tin for storage can reduce household waste and the need for new containers.","vi":"Việc tái sử dụng hộp kim loại để đựng đồ có thể làm giảm rác thải sinh hoạt và nhu cầu sử dụng các hộp đựng mới.","audioKind":"ex2"}],"collocations":[{"en":"a tin of soup","vi":"một hộp súp"},{"en":"a biscuit tin","vi":"hộp đựng bánh quy"},{"en":"a tin opener","vi":"cái mở hộp"},{"en":"tin mining","vi":"khai thác mỏ thiếc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa hộp đựng là danh từ đếm được (tiếng Anh-Anh dùng tin, tiếng Anh-Mỹ dùng can); nghĩa kim loại thiếc không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_conditioner', 'en-b1-63', 'conditioner', '/kənˈdɪʃənər/', 'B1', 'dầu xả tóc; kem xả tóc; nước xả vải', 'n.', 'condition (v.), conditioning (n.)', NULL, 'Khi dùng đơn độc, từ này thường chỉ dầu xả tóc; điều hòa không khí phải dùng là air conditioner.', 'I use conditioner to keep my curly hair soft.', NULL, 'Tôi dùng dầu xả để giữ cho mái tóc xoăn của mình luôn mềm mượt.', '{"wordId":"conditioner","ukIpa":"/kənˈdɪʃənə/","usIpa":"/kənˈdɪʃənər/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A product that makes hair softer and easier to manage.","vi":"dầu xả tóc; kem xả tóc"},{"pos":"n.","en":"A liquid added during washing to make fabrics softer.","vi":"nước xả vải"}],"examples":[{"en":"I use conditioner to keep my curly hair soft.","vi":"Tôi dùng dầu xả để giữ cho mái tóc xoăn của mình luôn mềm mượt.","audioKind":"ex"},{"en":"Consumers can reduce plastic waste by choosing refillable containers for shampoo and conditioner products.","vi":"Người tiêu dùng có thể giảm thiểu rác thải nhựa bằng cách lựa chọn các bao bì có thể đổ đầy lại cho các sản phẩm dầu gội và dầu xả.","audioKind":"ex2"}],"collocations":[{"en":"hair conditioner","vi":"dầu xả tóc"},{"en":"leave-in conditioner","vi":"dầu xả khô"},{"en":"fabric conditioner","vi":"nước xả mềm vải"}],"wordFamily":["condition (v.)","conditioning (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng đơn độc, từ này thường chỉ dầu xả tóc; điều hòa không khí phải dùng là air conditioner.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_within', 'en-b1-63', 'within', '/wɪˈðɪn/', 'B1', 'trong vòng; trong khoảng; ở bên trong; phía trong', 'prep.', NULL, 'Trái nghĩa: outside', 'within nhấn mạnh không vượt quá giới hạn phạm vi; within a week chỉ trong vòng một tuần.', 'Your parcel should arrive within the next three days.', NULL, 'Bưu kiện của bạn nên đến nơi trong vòng ba ngày tới.', '{"wordId":"within","ukIpa":"/wɪˈðɪn/","usIpa":"/wɪˈðɪn/","cefr":"B1","topic":"daily","senses":[{"pos":"prep.","en":"Inside a particular area, period, or limit.","vi":"trong vòng; trong khoảng"},{"pos":"adv.","en":"Inside something rather than outside it.","vi":"ở bên trong; phía trong"}],"examples":[{"en":"Your parcel should arrive within the next three days.","vi":"Bưu kiện của bạn nên đến nơi trong vòng ba ngày tới.","audioKind":"ex"},{"en":"Local authorities should ensure that essential services are available within walking distance of residential areas.","vi":"Các cơ quan địa phương nên đảm bảo rằng các dịch vụ thiết yếu nằm trong khoảng cách đi bộ được từ các khuresidential.","audioKind":"ex2"}],"collocations":[{"en":"within walking distance","vi":"trong khoảng cách đi bộ được"},{"en":"within reach","vi":"trong tầm với; có thể đạt được"},{"en":"within budget","vi":"trong ngân sách"},{"en":"within a week","vi":"trong vòng một tuần"}],"wordFamily":[],"synonyms":[],"antonyms":["outside"],"tipVi":"within nhấn mạnh không vượt quá giới hạn phạm vi; within a week chỉ trong vòng một tuần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_owe', 'en-b1-63', 'owe', '/oʊ/', 'B1', 'nợ tiền; phải có trách nhiệm trao; mang ơn; quy cho; nhờ có', 'v.', NULL, NULL, 'Cấu trúc owe A to B có thể mang nghĩa nợ B vật gì đó (A), hoặc quy công lao/kết quả (A) cho (B).', 'I still owe my sister money for the tickets.', NULL, 'Tôi vẫn còn nợ chị tôi tiền vé.', '{"wordId":"owe","ukIpa":"/əʊ/","usIpa":"/oʊ/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To have to pay money back to someone.","vi":"nợ tiền"},{"pos":"v.","en":"To have a duty to give someone something.","vi":"phải có trách nhiệm trao; mang ơn"},{"pos":"v.","en":"To have something because of someone''s help or another cause.","vi":"quy cho; nhờ có"}],"examples":[{"en":"I still owe my sister money for the tickets.","vi":"Tôi vẫn còn nợ chị tôi tiền vé.","audioKind":"ex"},{"en":"Many successful students owe their progress to consistent practice rather than exceptional natural ability.","vi":"Nhiều học sinh thành công có được sự tiến bộ nhờ vào việc luyện tập đều đặn hơn là nhờ năng bẩm thiên phú ngoại lệ.","audioKind":"ex2"}],"collocations":[{"en":"owe someone money","vi":"nợ tiền ai đó"},{"en":"owe an apology","vi":"nợ một lời xin lỗi"},{"en":"owe a debt of gratitude","vi":"mang ơn sâu sắc"},{"en":"owe success to","vi":"quy thành công cho"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc owe A to B có thể mang nghĩa nợ B vật gì đó (A), hoặc quy công lao/kết quả (A) cho (B).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whisky', 'en-b1-63', 'whisky', '/ˈwɪski/', 'B1', 'rượu u-uy-ski (rượu mạnh làm từ ngũ cốc và ủ trong thùng gỗ)', 'n.', NULL, NULL, 'Rượu Scotland thường được viết là whisky, trong khi rượu Ai-len và Mỹ thường được viết là whiskey.', 'The guide showed us barrels used for ageing whisky.', NULL, 'Hướng dẫn viên đã cho chúng tôi xem các thùng gỗ được dùng để ủ rượu u-uy-ski.', '{"wordId":"whisky","ukIpa":"/ˈwɪski/","usIpa":"/ˈwɪski/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A strong alcoholic drink made from grain and aged in barrels.","vi":"rượu u-uy-ski (rượu mạnh làm từ ngũ cốc và ủ trong thùng gỗ)"}],"examples":[{"en":"The guide showed us barrels used for ageing whisky.","vi":"Hướng dẫn viên đã cho chúng tôi xem các thùng gỗ được dùng để ủ rượu u-uy-ski.","audioKind":"ex"},{"en":"Traditional whisky production attracts tourists to rural areas and supports employment in farming, manufacturing, and hospitality.","vi":"Việc sản xuất rượu u-uy-ski truyền thống thu hút khách du lịch đến các vùng nông thôn và thúc đẩy việc làm trong lĩnh vực nông nghiệp, sản xuất và dịch vụ lưu trú, ăn uống.","audioKind":"ex2"}],"collocations":[{"en":"Scotch whisky","vi":"rượu u-uy-ski Scotland"},{"en":"malt whisky","vi":"rượu u-uy-ski mạch nha"},{"en":"whisky distillery","vi":"nhà máy chưng cất rượu u-uy-ski"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Rượu Scotland thường được viết là whisky, trong khi rượu Ai-len và Mỹ thường được viết là whiskey.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_squash', 'en-b1-63', 'squash', '/skwɑːʃ/', 'B1', 'làm bẹp dí; ép chặt vào không gian chật hẹp; môn đánh tường (bóng quần); quả bí; các loại rau củ thuộc họ bí', 'v.', NULL, NULL, 'Trong tiếng Anh-Anh, từ này còn có thể chỉ loại nước trái cây cô đặc cần pha loãng với nước khi uống.', 'Don''t squash the bread under those heavy shopping bags.', NULL, 'Đừng để chiếc bánh mì bị đè bẹp dưới những chiếc túi mua sắm nặng nề đó.', '{"wordId":"squash","ukIpa":"/skwɒʃ/","usIpa":"/skwɑːʃ/","cefr":"B1","topic":"daily","senses":[{"pos":"v.","en":"To crush something flat or squeeze into a small space","vi":"làm bẹp dí; ép chặt vào không gian chật hẹp"},{"pos":"n.","en":"An indoor racket sport played by hitting a ball against walls","vi":"môn đánh tường (bóng quần)"},{"pos":"n.","en":"A vegetable with thick skin and a soft, seed-filled centre","vi":"quả bí; các loại rau củ thuộc họ bí"}],"examples":[{"en":"Don''t squash the bread under those heavy shopping bags.","vi":"Đừng để chiếc bánh mì bị đè bẹp dưới những chiếc túi mua sắm nặng nề đó.","audioKind":"ex"},{"en":"Playing squash regularly can improve cardiovascular fitness, although beginners should increase the intensity of exercise gradually.","vi":"Chơi bóng quần thường xuyên có thể cải thiện thể lực tim mạch, mặc dù người mới tập nên tăng cường độ tập luyện từ từ.","audioKind":"ex2"}],"collocations":[{"en":"squash flat","vi":"làm bẹp dẹt"},{"en":"squash into","vi":"chen chúc vào"},{"en":"play squash","vi":"chơi môn đánh tường"},{"en":"butternut squash","vi":"bí bơ (bí hạt đậu)"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, từ này còn có thể chỉ loại nước trái cây cô đặc cần pha loãng với nước khi uống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jar', 'en-b1-63', 'jar', '/dʒɑːr/', 'B1', 'lọ miệng rộng; hũ; bình; gây khó chịu; chói tai; xung đột; làm chấn động; làm ê ẩm', 'n.', 'jarring (adj.)', NULL, 'jar thường chỉ bình miệng rộng có nắp; a jar of đi kèm với vật chứa bên trong.', 'She keeps homemade jam in a small glass jar.', NULL, 'Cô ấy đựng mứt tự làm trong một chiếc hũ thủy tinh nhỏ.', '{"wordId":"jar","ukIpa":"/dʒɑː/","usIpa":"/dʒɑːr/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A wide-mouthed container, often glass, with a lid.","vi":"lọ miệng rộng; hũ; bình"},{"pos":"v.","en":"To feel unpleasant or clash with something.","vi":"gây khó chịu; chói tai; xung đột"},{"pos":"v.","en":"To shake suddenly and sharply, sometimes causing pain.","vi":"làm chấn động; làm ê ẩm"}],"examples":[{"en":"She keeps homemade jam in a small glass jar.","vi":"Cô ấy đựng mứt tự làm trong một chiếc hũ thủy tinh nhỏ.","audioKind":"ex"},{"en":"Reusing glass jars for food storage can help households reduce their reliance on disposable plastic packaging.","vi":"Việc tái sử dụng lọ thủy tinh để đựng thực phẩm có thể giúp các hộ gia đình giảm bớt sự phụ thuộc vào bao bì nhựa dùng một lần.","audioKind":"ex2"}],"collocations":[{"en":"a jar of honey","vi":"một hũ mật ong"},{"en":"a glass jar","vi":"lọ thủy tinh"},{"en":"jar with the surroundings","vi":"không hòa hợp với xung quanh"}],"wordFamily":["jarring (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"jar thường chỉ bình miệng rộng có nắp; a jar of đi kèm với vật chứa bên trong.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_daytime', 'en-b1-63', 'daytime', '/ˈdeɪtaɪm/', 'B1', 'ban ngày; thời gian ban ngày; thuộc ban ngày; diễn ra ban ngày', 'n.', 'day (n.)', 'Trái nghĩa: nighttime', 'Thường dùng in the daytime; khi làm định ngữ thường không có mạo từ the.', 'The cat usually sleeps indoors during the daytime.', NULL, 'Con mèo thường ngủ trong nhà vào ban ngày.', '{"wordId":"daytime","ukIpa":"/ˈdeɪtaɪm/","usIpa":"/ˈdeɪtaɪm/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"The part of the day when there is natural light.","vi":"ban ngày; thời gian ban ngày"},{"pos":"adj.","en":"Happening or existing during the day rather than at night.","vi":"thuộc ban ngày; diễn ra ban ngày"}],"examples":[{"en":"The cat usually sleeps indoors during the daytime.","vi":"Con mèo thường ngủ trong nhà vào ban ngày.","audioKind":"ex"},{"en":"Higher daytime temperatures may force outdoor workers to adjust their schedules during the summer months.","vi":"Nhiệt độ ban ngày tăng cao có thể buộc những người làm việc ngoài trời phải điều chỉnh lịch làm việc trong những tháng mùa hè.","audioKind":"ex2"}],"collocations":[{"en":"during the daytime","vi":"vào ban ngày"},{"en":"daytime temperatures","vi":"nhiệt độ ban ngày"},{"en":"daytime television","vi":"chương trình truyền hình ban ngày"}],"wordFamily":["day (n.)"],"synonyms":[],"antonyms":["nighttime"],"tipVi":"Thường dùng in the daytime; khi làm định ngữ thường không có mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wherever', 'en-b1-63', 'wherever', '/werˈevər/', 'B1', 'bất cứ nơi nào; dù ở đâu; đâu (dùng trong câu hỏi để bày tỏ sự ngạc nhiên về một địa điểm)', 'conj.', 'where (adv.)', NULL, 'Khi mang nghĩa "bất cứ nơi nào", nó tương đương với no matter where.', 'You can sit wherever you feel most comfortable.', NULL, 'Bạn có thể ngồi ở bất cứ đâu mà bạn cảm thấy thoải mái nhất.', '{"wordId":"wherever","ukIpa":"/weərˈevə/","usIpa":"/werˈevər/","cefr":"B1","topic":"daily","senses":[{"pos":"conj.","en":"in or to any place, regardless of where","vi":"bất cứ nơi nào; dù ở đâu"},{"pos":"adv.","en":"used in questions to express surprise about a place","vi":"đâu (dùng trong câu hỏi để bày tỏ sự ngạc nhiên về một địa điểm)"}],"examples":[{"en":"You can sit wherever you feel most comfortable.","vi":"Bạn có thể ngồi ở bất cứ đâu mà bạn cảm thấy thoải mái nhất.","audioKind":"ex"},{"en":"Governments should ensure that children receive a good education wherever they live, including in remote rural communities.","vi":"Chính phủ nên đảm bảo rằng trẻ em nhận được nền giáo dục tốt dù các em sống ở bất cứ đâu, kể cả trong các cộng đồng nông thôn vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"wherever possible","vi":"bất cứ khi nào có thể"},{"en":"wherever you go","vi":"bất cứ nơi nào bạn đi"},{"en":"wherever you live","vi":"dù bạn sống ở đâu"}],"wordFamily":["where (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa \"bất cứ nơi nào\", nó tương đương với no matter where.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_signature', 'en-b1-63', 'signature', '/ˈsɪɡnətʃɚ/', 'B1', 'chữ ký; tên ký; đặc trưng; mang dấu ấn riêng', 'n.', 'sign (v.), signatory (n.)', 'Đồng nghĩa: autograph', 'signature thường chỉ chữ ký thông thường; chữ ký của người nổi tiếng hay dùng autograph.', 'The delivery driver asked for my signature at the door.', NULL, 'Người giao hàng đã yêu cầu tôi ký tên ở cửa.', '{"wordId":"signature","ukIpa":"/ˈsɪɡnətʃə/","usIpa":"/ˈsɪɡnətʃɚ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"Your name written in your own distinctive way","vi":"chữ ký; tên ký"},{"pos":"adj.","en":"Distinctive and closely associated with a particular person or place","vi":"đặc trưng; mang dấu ấn riêng"}],"examples":[{"en":"The delivery driver asked for my signature at the door.","vi":"Người giao hàng đã yêu cầu tôi ký tên ở cửa.","audioKind":"ex"},{"en":"Electronic signatures allow businesses to complete agreements remotely, reducing delays and the need for paper documents.","vi":"Chữ ký điện tử cho phép các doanh nghiệp hoàn tất thỏa thuận từ xa, giúp giảm thiểu sự chậm trễ và nhu cầu sử dụng tài liệu giấy.","audioKind":"ex2"}],"collocations":[{"en":"require a signature","vi":"yêu cầu chữ ký"},{"en":"electronic signature","vi":"chữ ký điện tử"},{"en":"signature dish","vi":"món ăn đặc trưng"}],"wordFamily":["sign (v.)","signatory (n.)"],"synonyms":["autograph"],"antonyms":[],"tipVi":"signature thường chỉ chữ ký thông thường; chữ ký của người nổi tiếng hay dùng autograph.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_absolutely', 'en-b1-63', 'absolutely', '/ˈæbsəluːtli/', 'B1', 'hoàn toàn; tuyệt đối; tất nhiên; hoàn toàn đồng ý', 'adv.', 'absolute (adj.)', 'Đồng nghĩa: completely, entirely · Trái nghĩa: partly', 'Thường bổ nghĩa cho các tính từ cực cấp như essential, không thường nói absolutely good.', 'The kitchen was absolutely spotless after we cleaned it.', NULL, 'Căn bếp sạch bóng không một vết bẩn sau khi chúng tôi dọn dẹp.', '{"wordId":"absolutely","ukIpa":"/ˈæbsəluːtli/","usIpa":"/ˈæbsəluːtli/","cefr":"B1","topic":"daily","senses":[{"pos":"adv.","en":"completely or without any doubt","vi":"hoàn toàn; tuyệt đối"},{"pos":"adv.","en":"used to express strong agreement with someone","vi":"tất nhiên; hoàn toàn đồng ý"}],"examples":[{"en":"The kitchen was absolutely spotless after we cleaned it.","vi":"Căn bếp sạch bóng không một vết bẩn sau khi chúng tôi dọn dẹp.","audioKind":"ex"},{"en":"Reliable internet access is absolutely essential for students participating in online courses from remote communities.","vi":"Kết nối Internet ổn định là điều tuyệt đối cần thiết đối với học sinh tham gia các khóa học trực tuyến từ các cộng đồng vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"absolutely essential","vi":"hoàn toàn cần thiết"},{"en":"absolutely certain","vi":"hoàn toàn chắc chắn"},{"en":"absolutely right","vi":"hoàn toàn đúng"},{"en":"absolutely not","vi":"tuyệt đối không"}],"wordFamily":["absolute (adj.)"],"synonyms":["completely","entirely"],"antonyms":["partly"],"tipVi":"Thường bổ nghĩa cho các tính từ cực cấp như essential, không thường nói absolutely good.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unexpected', 'en-b1-63', 'unexpected', '/ˌʌnɪkˈspektɪd/', 'B1', 'bất ngờ; không ngờ tới', 'adj.', 'expect (v.), expected (adj.), unexpectedly (adv.), expectation (n.)', 'Đồng nghĩa: unforeseen, unanticipated, surprising · Trái nghĩa: expected, anticipated', 'unexpected nhấn mạnh việc không lường trước, không nhất thiết phải xảy ra đột ngột.', 'An unexpected visitor arrived just as we finished lunch.', NULL, 'Một vị khách bất ngờ đã đến ngay lúc chúng tôi ăn trưa xong.', '{"wordId":"unexpected","ukIpa":"/ˌʌnɪkˈspektɪd/","usIpa":"/ˌʌnɪkˈspektɪd/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"Happening without being expected or predicted.","vi":"bất ngờ; không ngờ tới"}],"examples":[{"en":"An unexpected visitor arrived just as we finished lunch.","vi":"Một vị khách bất ngờ đã đến ngay lúc chúng tôi ăn trưa xong.","audioKind":"ex"},{"en":"Governments need emergency funds to manage unexpected events without reducing essential spending on healthcare and education.","vi":"Chính phủ cần quỹ khẩn cấp để quản lý các sự kiện bất ngờ mà không làm giảm chi tiêu thiết yếu cho y tế và giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"unexpected result","vi":"kết quả bất ngờ"},{"en":"unexpected visitor","vi":"vị khách không mời; khách bất ngờ"},{"en":"unexpected delay","vi":"sự chậm trễ bất ngờ"}],"wordFamily":["expect (v.)","expected (adj.)","unexpectedly (adv.)","expectation (n.)"],"synonyms":["unforeseen","unanticipated","surprising"],"antonyms":["expected","anticipated"],"tipVi":"unexpected nhấn mạnh việc không lường trước, không nhất thiết phải xảy ra đột ngột.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_avocado', 'en-b1-63', 'avocado', '/ˌævəˈkɑːdoʊ/', 'B1', 'quả bơ', 'n.', NULL, NULL, 'Dạng số nhiều là avocados, không thêm -es.', 'She spread ripe avocado on her warm toast.', NULL, 'Cô ấy phết bơ chín lên miếng bánh mì nướng còn ấm.', '{"wordId":"avocado","ukIpa":"/ˌævəˈkɑːdəʊ/","usIpa":"/ˌævəˈkɑːdoʊ/","cefr":"B1","topic":"daily","senses":[{"pos":"n.","en":"A fruit with creamy green flesh and a large central stone.","vi":"quả bơ"}],"examples":[{"en":"She spread ripe avocado on her warm toast.","vi":"Cô ấy phết bơ chín lên miếng bánh mì nướng còn ấm.","audioKind":"ex"},{"en":"Growing demand for avocados can place pressure on water supplies in regions with limited rainfall.","vi":"Nhu cầu ngày càng tăng đối với quả bơ có thể gây áp lực lên nguồn cung cấp nước ở những khu vực có lượng mưa hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"a ripe avocado","vi":"quả bơ chín"},{"en":"mashed avocado","vi":"bơ nghiền"},{"en":"avocado toast","vi":"bánh mì nướng bơ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là avocados, không thêm -es.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_typical', 'en-b1-63', 'typical', '/ˈtɪpɪkəl/', 'B1', 'điển hình; tiêu biểu; có các đặc điểm thông thường của một nhóm hoặc tình huống; đặc trưng; đúng với phong cách thường thấy của ai đó', 'adj.', 'typically (adv.), atypical (adj.)', 'Đồng nghĩa: representative, characteristic, usual · Trái nghĩa: atypical, unusual', 'Sử dụng cấu trúc typical of để diễn tả đặc điểm tiêu biểu của ai hoặc cái gì.', 'A typical weekday starts with breakfast and a walk.', NULL, 'Một ngày làm việc bình thường bắt đầu bằng bữa sáng và một buổi đi dạo.', '{"wordId":"typical","ukIpa":"/ˈtɪpɪkəl/","usIpa":"/ˈtɪpɪkəl/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"having the usual features of a particular group or situation","vi":"điển hình; tiêu biểu; có các đặc điểm thông thường của một nhóm hoặc tình huống"},{"pos":"adj.","en":"showing the behaviour or qualities usually associated with someone","vi":"đặc trưng; đúng với phong cách thường thấy của ai đó"}],"examples":[{"en":"A typical weekday starts with breakfast and a walk.","vi":"Một ngày làm việc bình thường bắt đầu bằng bữa sáng và một buổi đi dạo.","audioKind":"ex"},{"en":"Long commuting times are typical of large cities where housing near employment centres is expensive.","vi":"Thời gian đi lại kéo dài là hiện tượng phổ biến ở các thành phố lớn nơi nhà ở gần khu vực làm việc có giá đắt đỏ.","audioKind":"ex2"}],"collocations":[{"en":"a typical example","vi":"một ví dụ điển hình"},{"en":"typical of","vi":"là đặc trưng của"},{"en":"a typical day","vi":"một ngày bình thường"}],"wordFamily":["typically (adv.)","atypical (adj.)"],"synonyms":["representative","characteristic","usual"],"antonyms":["atypical","unusual"],"tipVi":"Sử dụng cấu trúc typical of để diễn tả đặc điểm tiêu biểu của ai hoặc cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_repeated', 'en-b1-63', 'repeated', '/rɪˈpiːtɪd/', 'B1', 'lặp đi lặp lại; nhiều lần; đã lặp lại; đã nói lại', 'adj.', 'repeat (v.), repetition (n.), repeatedly (adv.), repetitive (adj.)', 'Đồng nghĩa: recurring', 'repeated nhấn mạnh sự việc xảy ra nhiều lần; trong khi đó repetitive thường mang hàm ý đơn điệu, nhàm chán.', 'Repeated phone calls kept interrupting our quiet dinner.', NULL, 'Những cuộc gọi liên tục lặp đi lặp lại cứ làm gián đoạn bữa tối yên bình của chúng tôi.', '{"wordId":"repeated","ukIpa":"/rɪˈpiːtɪd/","usIpa":"/rɪˈpiːtɪd/","cefr":"B1","topic":"daily","senses":[{"pos":"adj.","en":"happening or done again and again","vi":"lặp đi lặp lại; nhiều lần"},{"pos":"v.","en":"said or did something again","vi":"đã lặp lại; đã nói lại"}],"examples":[{"en":"Repeated phone calls kept interrupting our quiet dinner.","vi":"Những cuộc gọi liên tục lặp đi lặp lại cứ làm gián đoạn bữa tối yên bình của chúng tôi.","audioKind":"ex"},{"en":"Repeated exposure to new vocabulary helps learners remember words and use them more confidently.","vi":"Việc tiếp xúc lặp đi lặp lại với từ vựng mới giúp người học ghi nhớ từ tốt hơn và sử dụng chúng một cách tự tin hơn.","audioKind":"ex2"}],"collocations":[{"en":"repeated attempts","vi":"nhiều lần cố gắng"},{"en":"repeated warnings","vi":"những lời cảnh báo nhiều lần"},{"en":"repeated exposure to","vi":"việc tiếp xúc liên tục với"}],"wordFamily":["repeat (v.)","repetition (n.)","repeatedly (adv.)","repetitive (adj.)"],"synonyms":["recurring"],"antonyms":[],"tipVi":"repeated nhấn mạnh sự việc xảy ra nhiều lần; trong khi đó repetitive thường mang hàm ý đơn điệu, nhàm chán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_63_1', 'en-b1-63', 'Cách dùng “tin” (n.) — hộp kim loại; lon; đồ hộp', 'a tin of soup  ·  a biscuit tin  ·  a tin opener', 'Nghĩa hộp đựng là danh từ đếm được (tiếng Anh-Anh dùng tin, tiếng Anh-Mỹ dùng can); nghĩa kim loại thiếc không đếm được.', NULL, '[{"hanzi":"There is a tin of beans in the cupboard.","pinyin":"","meaning":"Có một hộp đậu trong tủ chén."},{"hanzi":"Reusing a metal tin for storage can reduce household waste and the need for new containers.","pinyin":"","meaning":"Việc tái sử dụng hộp kim loại để đựng đồ có thể làm giảm rác thải sinh hoạt và nhu cầu sử dụng các hộp đựng mới."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_63_2', 'en-b1-63', 'Cách dùng “repeated” (adj.) — lặp đi lặp lại; nhiều lần', 'repeated attempts  ·  repeated warnings  ·  repeated exposure to', 'repeated nhấn mạnh sự việc xảy ra nhiều lần; trong khi đó repetitive thường mang hàm ý đơn điệu, nhàm chán.', 'Họ từ (Word Family): repeat (v.), repetition (n.), repeatedly (adv.), repetitive (adj.) | Đồng nghĩa: recurring', '[{"hanzi":"Repeated phone calls kept interrupting our quiet dinner.","pinyin":"","meaning":"Những cuộc gọi liên tục lặp đi lặp lại cứ làm gián đoạn bữa tối yên bình của chúng tôi."},{"hanzi":"Repeated exposure to new vocabulary helps learners remember words and use them more confidently.","pinyin":"","meaning":"Việc tiếp xúc lặp đi lặp lại với từ vựng mới giúp người học ghi nhớ từ tốt hơn và sử dụng chúng một cách tự tin hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_63_3', 'en-b1-63', 'Cách dùng “squash” (v.) — làm bẹp dí; ép chặt vào không gian chật hẹp', 'squash flat  ·  squash into  ·  play squash', 'Trong tiếng Anh-Anh, từ này còn có thể chỉ loại nước trái cây cô đặc cần pha loãng với nước khi uống.', NULL, '[{"hanzi":"Don''t squash the bread under those heavy shopping bags.","pinyin":"","meaning":"Đừng để chiếc bánh mì bị đè bẹp dưới những chiếc túi mua sắm nặng nề đó."},{"hanzi":"Playing squash regularly can improve cardiovascular fitness, although beginners should increase the intensity of exercise gradually.","pinyin":"","meaning":"Chơi bóng quần thường xuyên có thể cải thiện thể lực tim mạch, mặc dù người mới tập nên tăng cường độ tập luyện từ từ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_b1_63_4', 'en-b1-63', 'Cách dùng “whisky” (n.) — rượu u-uy-ski (rượu mạnh làm từ ngũ cốc và ủ trong thùng gỗ)', 'Scotch whisky  ·  malt whisky  ·  whisky distillery', 'Rượu Scotland thường được viết là whisky, trong khi rượu Ai-len và Mỹ thường được viết là whiskey.', NULL, '[{"hanzi":"The guide showed us barrels used for ageing whisky.","pinyin":"","meaning":"Hướng dẫn viên đã cho chúng tôi xem các thùng gỗ được dùng để ủ rượu u-uy-ski."},{"hanzi":"Traditional whisky production attracts tourists to rural areas and supports employment in farming, manufacturing, and hospitality.","pinyin":"","meaning":"Việc sản xuất rượu u-uy-ski truyền thống thu hút khách du lịch đến các vùng nông thôn và thúc đẩy việc làm trong lĩnh vực nông nghiệp, sản xuất và dịch vụ lưu trú, ăn uống."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_63_1', 'en-b1-63', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_1_1', 'ten_b1_63_1', 'flashlight', 'She used a flashlight to look under the bed.', 'She used a flashlight to look under the bed.', '/ˈflæʃlaɪt/', 'Cô ấy dùng đèn pin để soi xuống gầm giường.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_1_2', 'ten_b1_63_1', 'handkerchief', 'She pulled a clean handkerchief from her coat pocket.', 'She pulled a clean handkerchief from her coat pocket.', '/ˈhæŋkərtʃɪf/', 'Cô ấy rút một chiếc khăn tay sạch từ túi áo khoác ra.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_1_3', 'ten_b1_63_1', 'ink', 'Blue ink leaked from my pen onto my sleeve.', 'Blue ink leaked from my pen onto my sleeve.', '/ɪŋk/', 'Mực xanh từ cây bút của tôi bị rỉ ra tay áo.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_1_4', 'ten_b1_63_1', 'string', 'I tied the parcel with a piece of string.', 'I tied the parcel with a piece of string.', '/strɪŋ/', 'Tôi buộc gói hàng lại bằng một đoạn dây thừng mảnh.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_1_5', 'ten_b1_63_1', 'shadow', 'The cat chased its shadow across the sunny kitchen floor.', 'The cat chased its shadow across the sunny kitchen floor.', '/ˈʃædoʊ/', 'Con mèo đuổi theo cái bóng của chính nó trên sàn bếp ngập tràn ánh nắng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_1_6', 'ten_b1_63_1', 'careless', 'I was careless and left my keys in the door.', 'I was careless and left my keys in the door.', '/ˈkerləs/', 'Tôi đãng trí để quên chìa khóa ở ổ khóa cửa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_1_7', 'ten_b1_63_1', 'hundredth', 'Our village celebrated its hundredth anniversary with a picnic.', 'Our village celebrated its hundredth anniversary with a picnic.', '/ˈhʌndrədθ/', 'Làng chúng tôi đã tổ chức buổi dã ngoại để kỷ niệm một trăm năm thành lập.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_1_8', 'ten_b1_63_1', 'sweep', 'Please sweep the kitchen floor before our guests arrive.', 'Please sweep the kitchen floor before our guests arrive.', '/swiːp/', 'Làm ơn quét sạch sàn nhà bếp trước khi khách của chúng ta đến nhé.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_63_1_1', 'en-b1-63', 'ten_b1_63_1', 'listening', 'listening', 'She used a flashlight to look under the bed.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn có thể ngồi ở bất cứ đâu mà bạn cảm thấy thoải mái nhất.","Đừng để chiếc bánh mì bị đè bẹp dưới những chiếc túi mua sắm nặng nề đó.","Cô ấy dùng đèn pin để soi xuống gầm giường.","Bưu kiện của bạn nên đến nơi trong vòng ba ngày tới."]'::jsonb, 2, 'She used a flashlight to look under the bed. → Cô ấy dùng đèn pin để soi xuống gầm giường.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_63_1_2', 'en-b1-63', 'ten_b1_63_1', 'listening', 'listening', 'She pulled a clean handkerchief from her coat pocket.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy đựng mứt tự làm trong một chiếc hũ thủy tinh nhỏ.","Cô ấy rút một chiếc khăn tay sạch từ túi áo khoác ra.","Người giao hàng đã yêu cầu tôi ký tên ở cửa.","Tôi buộc gói hàng lại bằng một đoạn dây thừng mảnh."]'::jsonb, 1, 'She pulled a clean handkerchief from her coat pocket. → Cô ấy rút một chiếc khăn tay sạch từ túi áo khoác ra.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_b1_63_1_3', 'en-b1-63', 'ten_b1_63_1', 'listening', 'listening', 'Blue ink leaked from my pen onto my sleeve.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi buộc gói hàng lại bằng một đoạn dây thừng mảnh.","Con mèo đuổi theo cái bóng của chính nó trên sàn bếp ngập tràn ánh nắng.","Mực xanh từ cây bút của tôi bị rỉ ra tay áo.","Đừng để chiếc bánh mì bị đè bẹp dưới những chiếc túi mua sắm nặng nề đó."]'::jsonb, 2, 'Blue ink leaked from my pen onto my sleeve. → Mực xanh từ cây bút của tôi bị rỉ ra tay áo.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_b1_63_2', 'en-b1-63', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng B1 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_2_1', 'ten_b1_63_2', 'flashlight', 'Households should keep a flashlight readily available to improve safety during unexpected power cuts.', 'Households should keep a flashlight readily available to improve safety during unexpected power cuts.', '/ˈflæʃlaɪt/', 'Các hộ gia đình nên để sẵn đèn pin ở nơi dễ lấy để tăng độ an toàn trong các đợt cúp điện bất ngờ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_2_2', 'ten_b1_63_2', 'handkerchief', 'Using a washable handkerchief instead of disposable tissues can reduce everyday household waste.', 'Using a washable handkerchief instead of disposable tissues can reduce everyday household waste.', '/ˈhæŋkərtʃɪf/', 'Việc sử dụng khăn tay có thể giặt thay vì khăn giấy dùng một lần có thể làm giảm lượng rác thải sinh hoạt hàng ngày.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_2_3', 'ten_b1_63_2', 'ink', 'Schools can reduce their environmental impact by using less paper and choosing refillable ink cartridges.', 'Schools can reduce their environmental impact by using less paper and choosing refillable ink cartridges.', '/ɪŋk/', 'Các trường học có thể giảm thiểu tác động môi trường bằng cách dùng ít giấy hơn và chọn hộp mực có thể nạp lại.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_2_4', 'ten_b1_63_2', 'string', 'A string of successful conservation projects has demonstrated the value of involving local communities in environmental protection.', 'A string of successful conservation projects has demonstrated the value of involving local communities in environmental protection.', '/strɪŋ/', 'Một loạt các dự án bảo tồn thành công đã minh chứng cho giá trị của việc lôi kéo cộng đồng địa phương vào công tác bảo vệ môi trường.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_2_5', 'ten_b1_63_2', 'shadow', 'Allowing students to shadow experienced nurses can help them understand the practical demands of a healthcare career.', 'Allowing students to shadow experienced nurses can help them understand the practical demands of a healthcare career.', '/ˈʃædoʊ/', 'Việc cho học sinh theo chân các y điều dưỡng có kinh nghiệm có thể giúp các em hiểu được những yêu cầu thực tế của một sự nghiệp y tế.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_b1_63_2_6', 'ten_b1_63_2', 'careless', 'Careless disposal of household waste can pollute local waterways and create serious risks for wildlife.', 'Careless disposal of household waste can pollute local waterways and create serious risks for wildlife.', '/ˈkerləs/', 'Việc vứt bỏ rác thải sinh hoạt bừa bãi có thể gây ô nhiễm nguồn nước địa phương và tạo ra rủi ro nghiêm trọng cho động vật hoang dã.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
