INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_63_2', 'en-b1-63', NULL, 'comprehensive_test', 'listening', 'She pulled a clean handkerchief from her coat pocket.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một vị khách bất ngờ đã đến ngay lúc chúng tôi ăn trưa xong.","Đừng để chiếc bánh mì bị đè bẹp dưới những chiếc túi mua sắm nặng nề đó.","Cô ấy phết bơ chín lên miếng bánh mì nướng còn ấm.","Cô ấy rút một chiếc khăn tay sạch từ túi áo khoác ra."]'::jsonb, 3, 'She pulled a clean handkerchief from her coat pocket. → Cô ấy rút một chiếc khăn tay sạch từ túi áo khoác ra.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_63_3', 'en-b1-63', NULL, 'comprehensive_test', 'listening', 'ink', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["áo lót sát nách (Anh); áo lê-ki-na, áo ghi-lê (Mỹ)","mực (viết, vẽ, in)","vui vẻ; rộn ràng; hân hoan","đường xích đạo"]'::jsonb, 1, 'ink (/ɪŋk/) → mực (viết, vẽ, in); bôi mực; tra mực', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_63_4', 'en-b1-63', NULL, 'comprehensive_test', 'listening', 'I tied the parcel with a piece of string.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi buộc gói hàng lại bằng một đoạn dây thừng mảnh.","Cả hai chiếc áo khoác đều không vừa với tôi, nên tôi sẽ tiếp tục tìm kiếm.","Tôi vẫn còn nợ chị tôi tiền vé.","Con mèo đuổi theo cái bóng của chính nó trên sàn bếp ngập tràn ánh nắng."]'::jsonb, 0, 'I tied the parcel with a piece of string. → Tôi buộc gói hàng lại bằng một đoạn dây thừng mảnh.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_63_5', 'en-b1-63', NULL, 'comprehensive_test', 'listening', 'shadow', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["môn bóng bầu dục","áp lực (tinh thần); sự thúc ép","cái bóng; bóng râm","lộn ngược; đảo ngược"]'::jsonb, 2, 'shadow (/ˈʃædoʊ/) → cái bóng; bóng râm; đi theo sát; theo chân học việc', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_63_6', 'en-b1-63', NULL, 'comprehensive_test', 'listening', 'I was careless and left my keys in the door.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Làng chúng tôi đã tổ chức buổi dã ngoại để kỷ niệm một trăm năm thành lập.","Con mèo đuổi theo cái bóng của chính nó trên sàn bếp ngập tràn ánh nắng.","Tôi đãng trí để quên chìa khóa ở ổ khóa cửa.","Cô ấy rút một chiếc khăn tay sạch từ túi áo khoác ra."]'::jsonb, 2, 'I was careless and left my keys in the door. → Tôi đãng trí để quên chìa khóa ở ổ khóa cửa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
