INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_63_8', 'en-b1-63', NULL, 'comprehensive_test', 'listening', 'Please sweep the kitchen floor before our guests arrive.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Làm ơn quét sạch sàn nhà bếp trước khi khách của chúng ta đến nhé.","Cô ấy gói món quà sinh nhật bằng một lớp giấy màu vàng rực rỡ.","Bạn có thể ngồi ở bất cứ đâu mà bạn cảm thấy thoải mái nhất.","Tôi đãng trí để quên chìa khóa ở ổ khóa cửa."]'::jsonb, 0, 'Please sweep the kitchen floor before our guests arrive. → Làm ơn quét sạch sàn nhà bếp trước khi khách của chúng ta đến nhé.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
