INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_63_18', 'en-b1-63', NULL, 'comprehensive_test', 'reading', NULL, 'Households should keep a flashlight readily available to improve safety during unexpected power cuts.', 'Dựa vào câu trên, từ “flashlight” có nghĩa phù hợp nhất là gì?', '["chảy; luân chuyển","trận chiến; cuộc giao tranh","đèn pin","thuộc về môi trường tự nhiên; liên quan đến bảo vệ môi trường"]'::jsonb, 2, 'flashlight: đèn pin. Dịch cả câu: Các hộ gia đình nên để sẵn đèn pin ở nơi dễ lấy để tăng độ an toàn trong các đợt cúp điện bất ngờ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_63_19', 'en-b1-63', NULL, 'comprehensive_test', 'reading', NULL, 'Using a washable handkerchief instead of disposable tissues can reduce everyday household waste.', 'Dựa vào câu trên, từ “handkerchief” có nghĩa phù hợp nhất là gì?', '["thuộc vùng Nam Cực","khăn tay","quả bí ngô","thiên thần"]'::jsonb, 1, 'handkerchief: khăn tay. Dịch cả câu: Việc sử dụng khăn tay có thể giặt thay vì khăn giấy dùng một lần có thể làm giảm lượng rác thải sinh hoạt hàng ngày.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_63_20', 'en-b1-63', NULL, 'comprehensive_test', 'reading', NULL, 'Schools can reduce their environmental impact by using less paper and choosing refillable ink cartridges.', 'Dựa vào câu trên, từ “ink” có nghĩa phù hợp nhất là gì?', '["hiệu trưởng nam; nam hiệu trưởng","làm hỏng; tàn phá","mực (viết, vẽ, in)","ngoài trời; lộ thiên"]'::jsonb, 2, 'ink: mực (viết, vẽ, in); bôi mực; tra mực. Dịch cả câu: Các trường học có thể giảm thiểu tác động môi trường bằng cách dùng ít giấy hơn và chọn hộp mực có thể nạp lại.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_b1_63_21', 'en-b1-63', NULL, 'comprehensive_test', 'reading', NULL, 'A string of successful conservation projects has demonstrated the value of involving local communities in environmental protection.', 'Dựa vào câu trên, từ “string” có nghĩa phù hợp nhất là gì?', '["ống (vật hình trụ rỗng để dẫn chất lỏng hoặc khí)","dây thừng mảnh; dây buộc","sự phát hiện; vật được phát hiện","hài hước; liên quan đến hài kịch"]'::jsonb, 1, 'string: dây thừng mảnh; dây buộc; dây đàn; chuỗi; một loạt. Dịch cả câu: Một loạt các dự án bảo tồn thành công đã minh chứng cho giá trị của việc lôi kéo cộng đồng địa phương vào công tác bảo vệ môi trường.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
